const CANONICAL_SIGNATURE_IDS=new Set(["MTB_NSCLC_001_v0_6","MTB_NSCLC_002_v1_3","MTB_CRC_002_v1_3","MTB_OVAR_002_v1_3","MET_NGS_003_v1_0","LAB_RUN_002_v0_8","LAB_POST_001_v1_0","RES_HYP_001_v0_9","MTB_CRC_001_v0_6","MTB_OVAR_001_v0_7","MTB_IO_001_v1_0","MTB_CNS_001_v1_0","LAB_DOC_001_v1_0","RES_OMICS_001_v1_0","RES_ETH_001_v1_0"]);
const EXACT={"en":{"ERBB2-VUS im RAS/BRAF-WT-mCRC: Genname ist noch kein Target":"ERBB2 VUS in RAS/BRAF-WT mCRC: a gene name is not yet a target","VUS im Onkogen":"VUS in an oncogene","Initialer Auftrag":"Initial request","Einsender":"Referrer","Gastroonkologie / Molekulares Tumorboard":"Gastrointestinal oncology / Molecular Tumor Board","Klinische Information":"Clinical information","63-jährige Patientin mit linksseitigem metastasiertem CRC und Progress nach mehreren Therapielinien. Ein externer NGS-Bericht markiert „ERBB2 altered“ prominent.":"63-year-old woman with left-sided metastatic CRC and progression after several lines of therapy. An external NGS report prominently flags ‘ERBB2 altered’. ","Fragestellung":"Clinical question","Reicht eine seltene ERBB2-Missense-VUS als Grundlage für HER2-gerichtete Therapie?":"Is a rare ERBB2 missense VUS sufficient to justify HER2-directed therapy?","Zeitfenster":"Time frame","Nächste Therapielinie soll im MTB diskutiert werden.":"The next line of therapy is to be discussed at the MTB.","Anamnese und klinischer Kontext":"Medical history and clinical context","Molekularer Kontext":"Molecular context","KRAS/NRAS/BRAF wildtyp, pMMR/MSS.":"KRAS/NRAS/BRAF wild type, pMMR/MSS.","Externer Report":"External report","Seltene ERBB2-Missense-Variante, VAF 18 %, Klassifikation VUS; im Summary trotzdem gelb als „potential target“ hervorgehoben.":"Rare ERBB2 missense variant, VAF 18%, classified as VUS; nevertheless highlighted in yellow in the summary as a ‘potential target’. ","Didaktische Falle":"Teaching trap","Genname, Datenbanktreffer und Actionability werden miteinander vermischt.":"Gene name, database hit and actionability are being conflated.","Ziel":"Goal","Variante, Biomarker und klinische Evidenz getrennt bewerten.":"Assess the variant, biomarker and clinical evidence separately.","Histologie + Vorinformation":"Histology + prior information","Histologie":"Histology","Metastasiertes kolorektales Adenokarzinom.":"Metastatic colorectal adenocarcinoma.","HER2-IHC":"HER2 IHC","noch nicht erfolgt.":"not yet performed.","ISH":"ISH","Offen":"Pending","Gibt es unabhängig von der VUS einen etablierten HER2-Biomarker?":"Is there an established HER2 biomarker independent of the VUS?","Materialprüfung":"Material review","Material":"Material","FFPE-Metastase, ausreichend.":"FFPE metastasis, sufficient.","Tumoranteil":"Tumor fraction","ca. 55 %.":"approx. 55%.","NGS-QC":"NGS QC","Variante technisch robust detektiert.":"Variant detected with high technical confidence.","Wichtig":"Important","Technisch echt bedeutet nicht automatisch klinisch bedeutsam.":"Being technically real does not automatically mean being clinically relevant.","ERBB2-Variantenbewertung":"ERBB2 variant assessment","VUS-/Evidenzkurationsschritt":"VUS/evidence curation step","Unabhängigen HER2-Biomarker prüfen":"Assess an independent HER2 biomarker","ERBB2-NGS":"ERBB2 NGS","Seltene ERBB2-Missense-Variante, VAF 18 %, technisch robust; aktuelle Klassifikation VUS.":"Rare ERBB2 missense variant, VAF 18%, technically robust; current classification: VUS.","VUS-Curation":"VUS curation","Keine ausreichende klinische Evidenz für prädiktive Actionability; einzelne präklinische Hinweise reichen nicht zur Hochstufung.":"Insufficient clinical evidence for predictive actionability; isolated preclinical findings are not enough for upgrading.","HER2 IHC 1+, keine starke membranöse Überexpression.":"HER2 IHC 1+, no strong membranous overexpression.","HER2-FISH/ISH":"HER2 FISH/ISH","Keine ERBB2-Amplifikation.":"No ERBB2 amplification.","Fehlentscheidung":"Incorrect decision","Eine direkte HER2-Therapieempfehlung allein aus einer VUS wäre ein Evidenz-Overcall.":"A direct recommendation for HER2-targeted therapy based solely on a VUS would be an evidence overcall.","Die VUS ist technisch real detektiert.":"The VUS is technically real.","Kernaussage":"Key message","Technische Echtheit, Pathogenität und prädiktive Actionability sind drei getrennte Ebenen.":"Technical validity, pathogenicity and predictive actionability are three separate levels.","Die ERBB2-Variante ist technisch robust, aber klinisch weiterhin VUS und darf nicht als gesicherter prädiktiver Biomarker behandelt werden. HER2-IHC 1+ und fehlende ERBB2-Amplifikation liefern keinen unabhängigen etablierten HER2-Amplifikationskontext. Eine Therapieempfehlung allein aus der VUS wäre nicht evidenzbasiert.":"The ERBB2 variant is technically robust but remains a VUS clinically and must not be treated as an established predictive biomarker. HER2 IHC 1+ and absence of ERBB2 amplification provide no independent established HER2-amplification context. A treatment recommendation based solely on the VUS would not be evidence-based.","Teilbefund: Ein technisch echter Variantenfund ist ohne belastbare funktionelle/klinische Evidenz nicht automatisch actionable.":"Partial result: a technically genuine variant finding is not automatically actionable without robust functional/clinical evidence.","VUS klar als VUS benennen":"Clearly label the VUS as a VUS","technische Validität, Pathogenität und Actionability trennen":"separate technical validity, pathogenicity and actionability","IHC/ISH als separaten Biomarkerpfad verstehen":"understand IHC/ISH as a separate HER2 biomarker pathway","Falschaussage: ERBB2 steht im Genfeld, also ist HER2-Therapie indiziert":"False statement: ERBB2 is listed in the gene field, therefore HER2 therapy is indicated","Optimale Lösung: ERBB2-VUS nicht overcallen, unabhängige HER2-Biomarker separat prüfen und die Therapieaussage an Evidenz statt an Genname oder Datenbankfarbe koppeln.":"Optimal solution: do not overcall the ERBB2 VUS, assess independent HER2 biomarkers separately, and base the treatment statement on evidence rather than on the gene name or database color.","VUS":"VUS","ERBB2":"ERBB2","HER2":"HER2","Evidenz":"Evidence","MTB":"MTB","Deep Dive":"Deep Dive","Das gelbe „potential target“":"The yellow ‘potential target’","Molekulares Tumorboard / Varianteninterpretation":"Molecular Tumor Board / variant interpretation","VUS nicht als pathogene/actionable Variante berichten.":"Do not report a VUS as pathogenic/actionable.","Technische Validität, biologische Pathogenität und klinische Prädiktion trennen.":"Separate technical validity, biological pathogenicity and clinical prediction.","IHC/ISH bei HER2 als eigenständigen Biomarkerpfad einordnen.":"Classify IHC/ISH for HER2 as an independent biomarker pathway.","Datenbank-/Software-Highlights nicht mit klinischer Evidenz verwechseln.":"Do not confuse database/software highlights with clinical evidence.","Im externen Report ist ERBB2 gelb hervorgehoben: „potential target“. In der Detailzeile steht jedoch schlicht VUS. Der Fall ist ein Test dafür, ob das Board die Farbe oder die Evidenz liest.":"In the external report, ERBB2 is highlighted in yellow: ‘potential target’. The detail line, however, simply says VUS. The case tests whether the board reads the color or the evidence.","63-jährige Patientin mit RAS/BRAF-WT-mCRC. Eine seltene ERBB2-Missense-Variante ist technisch sicher detektiert, aber als VUS klassifiziert. Das Board soll entscheiden, ob daraus eine HER2-gerichtete Therapieaussage entsteht.":"63-year-old woman with RAS/BRAF-WT mCRC. A rare ERBB2 missense variant is technically secure but classified as a VUS. The board must decide whether this supports a HER2-directed treatment statement.","Drei Ebenen":"Three levels","Call echt? Variante pathogen? Befund prädiktiv?":"Call real? Variant pathogenic? Finding predictive?","Diese Ebenen dürfen nicht zusammenfallen.":"These levels must not collapse into one another.","HER2 ist mehr als ein Genname":"HER2 is more than a gene name","Amplifikation/Überexpression und einzelne Sequenzvarianten sind unterschiedliche Biomarker.":"Amplification/overexpression and individual sequence variants are different biomarkers.","Methoden beantworten verschiedene Fragen.":"Methods answer different questions.","Software ist keine Leitlinie":"Software is not a guideline","Ein automatisch hervorgehobener Datenbanktreffer kann evidenzarm sein.":"An automatically highlighted database hit may have weak evidence.","Finale Interpretation bleibt fachlich verantwortlich.":"Final interpretation remains a professional responsibility.","ERBB2-Variante":"ERBB2 variant","VAF 18 %, technisch robust, Klassifikation VUS":"VAF 18%, technically robust, classified as VUS","RAS/BRAF":"RAS/BRAF","MMR/MSI":"MMR/MSI","pMMR/MSS":"pMMR/MSS","Material ausreichend.":"Material sufficient.","Keine analytische Unsicherheit des Calls – die Unsicherheit ist interpretativ.":"There is no analytical uncertainty in the call—the uncertainty is interpretive.","Der Fall verlangt keine Therapieempfehlung aus einem nicht etablierten VUS.":"The case does not require a treatment recommendation from a non-established VUS.","Was ist die korrekte Bedeutung einer technisch robusten ERBB2-VUS?":"What is the correct meaning of a technically robust ERBB2 VUS?","Die Variante ist nach aktueller Evidenz nicht ausreichend als pathogen/prädiktiv klassifiziert.":"According to current evidence, the variant is not sufficiently classified as pathogenic/predictive.","Jede ERBB2-Variante ist actionable.":"Every ERBB2 variant is actionable.","VUS bedeutet sicher benign.":"VUS means definitely benign.","VUS bedeutet Keimbahn.":"VUS means germline.","VUS beschreibt unzureichende Evidenz, nicht eine halbe Therapieindikation.":"VUS describes insufficient evidence, not half a treatment indication.","Welche Ebenen müssen getrennt bewertet werden?":"Which levels must be assessed separately?","analytische Echtheit des Calls":"analytical validity of the call","Pathogenität/biologische Bedeutung":"pathogenicity/biological significance","klinisch-prädiktive Evidenz":"clinical predictive evidence","Farbe im Software-Report":"color in the software report","Der Software-Look ist keine Evidenzebene.":"The software appearance is not a level of evidence.","HER2 IHC 1+ und keine ERBB2-Amplifikation: Was folgt daraus?":"HER2 IHC 1+ and no ERBB2 amplification: what follows?","Es liegt kein unabhängiger etablierter Amplifikations-/Überexpressionsbefund vor, der die VUS „rettet“.":"There is no independent established amplification/overexpression finding that ‘rescues’ the VUS.","Damit wird die VUS automatisch pathogen.":"This automatically makes the VUS pathogenic.","HER2-Therapie ist allein dadurch zwingend.":"HER2 therapy is mandatory on this basis alone.","IHC/ISH und Sequenzierung messen exakt dasselbe.":"IHC/ISH and sequencing measure exactly the same thing.","Die Methoden adressieren unterschiedliche Biomarker.":"The methods address different biomarkers.","Eine Datenbank nennt einen präklinischen Zelllinienhinweis. Reicht das zur Therapieableitung?":"A database cites a preclinical cell-line finding. Is that enough to derive therapy?","Nein; präklinische Hinweise können Hypothesen stützen, ersetzen aber keine ausreichende klinische Evidenz für diese VUS.":"No; preclinical findings can support hypotheses but do not replace sufficient clinical evidence for this VUS.","Ja, jeder präklinische Treffer macht eine VUS actionable.":"Yes, every preclinical hit makes a VUS actionable.","Literatur ist grundsätzlich irrelevant.":"Literature is fundamentally irrelevant.","Die Variante wird automatisch Tier I.":"The variant automatically becomes Tier I.","Evidenzhierarchie und variantenspezifische Daten müssen berücksichtigt werden.":"Evidence hierarchy and variant-specific data must be considered.","Formulieren Sie eine MTB-Kernaussage, die den ERBB2-Fund korrekt einordnet, ohne ihn zu overcallen.":"Formulate an MTB key statement that correctly classifies the ERBB2 finding without overcalling it.","Technische Echtheit bestätigen.":"Confirm technical validity.","Aktuelle Variantenklassifikation übernehmen bzw. fachlich kuratieren.":"Adopt or professionally curate the current variant classification.","Keine Pathogenität/Actionability aus dem Genname ableiten.":"Do not infer pathogenicity/actionability from the gene name.","HER2-IHC/ISH als separaten Biomarkerpfad bewerten.":"Assess HER2 IHC/ISH as a separate biomarker pathway.","VUS klar und nicht handlungsleitend kommunizieren; Re-Evaluation bei neuer Evidenz möglich.":"Communicate the VUS clearly as non-action-guiding; re-evaluation may be possible when new evidence emerges.","Studieneinschluss kann je nach Protokoll breitere molekulare Kriterien verwenden; das ist von einer etablierten Therapieempfehlung zu trennen.":"Trial enrollment may use broader molecular criteria depending on the protocol; this must be distinguished from an established treatment recommendation.","Genname = Target":"Gene name = target","Ignoriert Variantenspezifität und Evidenz.":"Ignores variant specificity and evidence.","VUS = benign":"VUS = benign","Unsicherheit wird fälschlich in Harmlosigkeit umgedeutet.":"Uncertainty is incorrectly reinterpreted as harmlessness.","IHC/ISH macht Missense-VUS pathogen":"IHC/ISH makes a missense VUS pathogenic","Unterschiedliche Biomarkerfragen werden vermischt.":"Different biomarker questions are being conflated.","Die Variante ist echt – und trotzdem kein Target":"The variant is real—and still not a target","Curation bestätigt die technische Echtheit, aber nicht die klinische Actionability. HER2-IHC/ISH liefern ebenfalls keinen unabhängigen etablierten HER2-Befund.":"Curation confirms technical validity but not clinical actionability. HER2 IHC/ISH likewise provides no independent established HER2 finding.","Der Twist ist kein Laborfehler, sondern die Trennung von Detektion und Bedeutung.":"The twist is not a laboratory error, but the separation of detection from meaning.","VUS sauber begrenzt":"VUS appropriately delimited","Technisch echt, klinisch unklar, kein Overcalling.":"Technically real, clinically unclear, no overcalling.","Evidenzgerechte MTB-Kommunikation.":"Evidence-based MTB communication.","Direkt HER2-Therapie":"Immediate HER2 therapy","VUS wird wie ein etablierter Biomarker behandelt.":"The VUS is treated like an established biomarker.","Kritischer Interpretationsfehler.":"Critical interpretation error.","VUS verschwiegen":"VUS omitted","Unsicherheit wird nicht transparent kommuniziert.":"Uncertainty is not communicated transparently.","Besser klar benennen und begrenzen.":"Better to name and delimit it clearly.","VUS ohne ausreichende prädiktive Evidenz":"VUS without sufficient predictive evidence","nicht als gesichertes Target formulieren":"do not describe as an established target","ggf. Re-Evaluation bei neuer Evidenz.":"consider re-evaluation if new evidence emerges.","VUS ist eine Evidenzkategorie.":"VUS is an evidence category.","Softwareannotation ersetzt keine fachliche Varianteninterpretation.":"Software annotation does not replace professional variant interpretation.","Ein Gen kann mehrere völlig unterschiedliche Biomarkerarten tragen.":"A gene can carry several completely different types of biomarkers.","ERBB2-VUS technisch bestätigt, jedoch ohne ausreichende klinisch-prädiktive Evidenz; HER2 IHC/ISH ohne unabhängigen positiven Biomarker. Keine etablierte Therapieableitung allein aus der VUS.":"ERBB2 VUS technically confirmed, but without sufficient clinical predictive evidence; HER2 IHC/ISH without an independent positive biomarker. No established treatment implication based solely on the VUS.","Evidenzhierarchie":"Evidence hierarchy","Variantenspezifität":"Variant specificity","MTB-Kommunikation":"MTB communication","Wann darf eine VUS reklassifiziert werden?":"When may a VUS be reclassified?","Wie häufig sollte Re-Annotation erfolgen?":"How often should re-annotation be performed?","Wie verhindert man Software-bedingtes Overcalling?":"How can software-driven overcalling be prevented?","Twist: technisch echt ≠ klinisch actionable":"Twist: technically real ≠ clinically actionable","HER2-IHC/ISH und Sequenz-VUS getrennt":"HER2 IHC/ISH and sequence VUS kept separate","Referenzpfad: Call → Klassifikation → Evidenz → klinische Aussage":"Reference pathway: call → classification → evidence → clinical statement","ALK/ROS1/RET/NTRK-Fusionsverdacht bei jungem Nie-Raucher → FISH, RNA-NGS oder DNA-NGS?":"Suspected ALK/ROS1/RET/NTRK fusion in a young never-smoker → FISH, RNA NGS or DNA NGS?","ALK/ROS1/RET/NTRK-Fusionsverdacht …":"Suspected ALK/ROS1/RET/NTRK fusion …","Thoraxonkologie / Molekulares Tumorboard":"Thoracic oncology / Molecular Tumor Board","42-jährige Patientin, Nie-Raucherin, metastasiertes pulmonales Adenokarzinom mit Leber- und Knochenmetastasen.":"42-year-old woman, never-smoker, with metastatic pulmonary adenocarcinoma involving liver and bone.","Ein externes DNA-basiertes Panel meldet keinen therapierbaren Treiber. Ist die molekulare Abklärung damit abgeschlossen oder muss eine Fusionsdiagnostik ergänzt werden?":"An external DNA-based panel reports no actionable driver. Is the molecular work-up complete, or should fusion testing be added?","Die Erstlinientherapie soll im MTB in fünf Tagen festgelegt werden.":"First-line therapy is to be defined at the MTB in five days.","Raucherstatus":"Smoking status","Nie-Raucherin, keine relevante berufliche Exposition.":"Never-smoker, no relevant occupational exposure.","Klinischer Verlauf":"Clinical course","ECOG 1, symptomatische ossäre Metastase, insgesamt aber klinisch stabil.":"ECOG 1, symptomatic bone metastasis, but overall clinically stable.","Vorbefund":"Prior result","Externes DNA-NGS ohne EGFR-, KRAS-, BRAF-, MET-Exon-14- oder ERBB2-Alteration; der Bericht enthält keine belastbare Aussage zur RNA-basierten Fusionserfassung.":"External DNA NGS without EGFR, KRAS, BRAF, MET exon 14 or ERBB2 alteration; the report provides no robust statement on RNA-based fusion detection.","Entscheidungsdruck":"Decision pressure","Die Onkologie erwägt bereits eine nicht zielgerichtete Systemtherapie, falls kein Treiber gefunden wird.":"Oncology is already considering a non-targeted systemic therapy if no driver is found.","HE":"H&E","Mäßig differenziertes pulmonales Adenokarzinom in einer Lebermetastasenbiopsie.":"Moderately differentiated pulmonary adenocarcinoma in a liver metastasis biopsy.","IHC":"IHC","TTF-1 und Napsin A positiv; p40 negativ. Die Morphologie und der klinische Kontext stützen einen pulmonalen Primarius.":"TTF-1 and Napsin A positive; p40 negative. Morphology and clinical context support a pulmonary primary.","Biologischer Hinweis":"Biological clue","Junges Alter und Nie-Raucherstatus erhöhen die Aufmerksamkeit für eine onkogene Treiberalteration, ersetzen aber keinen methodisch vollständigen Nachweis.":"Young age and never-smoking status increase suspicion for an oncogenic driver alteration but do not replace methodologically complete testing.","Offene Frage":"Open question","Wurden ALK-, ROS1-, RET- und NTRK-Fusionen mit einer dafür geeigneten Methode tatsächlich ausreichend ausgeschlossen?":"Were ALK, ROS1, RET and NTRK fusions truly excluded with an appropriate method?","FFPE-Leberbiopsie, Block M2.":"FFPE liver biopsy, block M2.","ca. 35–40 %, nach Markierung gut geeignet.":"approx. 35–40%, well suited after marking.","RNA-Prognose":"RNA outlook","RNA-Qualität nach Vorprüfung grenzwertig bis ausreichend; noch genügend Material für einen gezielten RNA-Ansatz.":"RNA quality is borderline to sufficient after preliminary assessment; enough material remains for a targeted RNA approach.","Schnittbudget":"Slide budget","8 ungefärbte Schnitte verfügbar.":"8 unstained sections available.","Materialfalle":"Material trap","Ein wiederholtes DNA-only-Panel verbraucht Material und kann die eigentliche Fusionsfrage trotzdem offenlassen.":"Repeating a DNA-only panel consumes material and may still leave the actual fusion question unanswered.","Breite Fusionsdiagnostik":"Broad fusion testing","DNA-NGS":"DNA NGS","Kein relevanter SNV/Indel-Treiber nachweisbar. Die konkrete Assay-Konfiguration erlaubt keinen belastbaren Ausschluss aller klinisch relevanten Fusionen.":"No relevant SNV/indel driver detected. The specific assay configuration does not allow reliable exclusion of all clinically relevant fusions.","RNA-Fusionsdiagnostik":"RNA fusion testing","KIF5B::RET-Fusion nachweisbar; in-frame und exprimiert. Der Befund erklärt den bisher DNA-negativen Treiberstatus.":"KIF5B::RET fusion detected; in-frame and expressed. The finding explains the previously DNA-negative driver status.","FISH":"FISH","Bei gezielter RET-FISH zeigt sich ein Rearrangement. Die Methode bestätigt die Umlagerung, liefert aber nicht die Breite einer parallelen RNA-Fusionsanalyse.":"Targeted RET FISH shows a rearrangement. The method confirms the rearrangement but does not provide the breadth of a parallel RNA fusion analysis.","QC":"QC","Tumorzellanteil ausreichend. RNA ist knapp, aber nach QC verwertbar; Material Stewardship bleibt relevant.":"Tumor fraction sufficient. RNA is limited but usable after QC; material stewardship remains relevant.","Die RNA-basierte Fusionsdiagnostik weist eine therapeutisch relevante KIF5B::RET-Fusion nach. Der zuvor negative DNA-Befund war kein belastbarer Ausschluss einer onkogenen Fusion.":"RNA-based fusion testing detects a therapeutically relevant KIF5B::RET fusion. The previously negative DNA result was not a reliable exclusion of an oncogenic fusion.","Teilbefund: Eine gezielte Einzelmethode oder DNA-only-Strategie kann die breite Fusionsfrage nicht vollständig beantworten. Eine RNA-basierte Fusionsdiagnostik sollte ergänzt werden.":"Partial result: a targeted single method or DNA-only strategy cannot fully answer the broad fusion question. RNA-based fusion testing should be added.","Die RET-Fusion als therapieentscheidenden Treiber benennen":"Identify the RET fusion as a treatment-defining driver","DNA-only nicht mit umfassend treibernegativ gleichsetzen":"do not equate DNA-only with comprehensively driver-negative","FISH als gezielte Bestätigungs-/Alternativmethode, nicht als universellen Ersatz einer breiten RNA-Analyse einordnen":"classify FISH as a targeted confirmatory/alternative method, not as a universal substitute for broad RNA analysis","Assay- und RNA-QC-Limitationen transparent kommunizieren":"communicate assay and RNA QC limitations transparently","Optimale Lösung: vorhandenen DNA-Befund methodisch prüfen und die offene Fusionsfrage mit einer breiten RNA-basierten Analyse schließen; gezielte FISH kann bei konkreter Hypothese ergänzen.":"Optimal solution: review the existing DNA result methodologically and close the open fusion question with broad RNA-based analysis; targeted FISH can be added for a specific hypothesis.","NSCLC":"NSCLC","NGS":"NGS","RNA":"RNA","MVP":"MVP","Standard":"Standard","Junge Nie-Raucherin mit DNA-negativem NSCLC: Ist der Tumor wirklich treibernegativ?":"Young never-smoker with DNA-negative NSCLC: is the tumor really driver-negative?","Molekularpathologie / Thoraxonkologie / MTB":"Molecular pathology / Thoracic oncology / MTB","Einen negativen DNA-NGS-Befund nur innerhalb der tatsächlich validierten Assaygrenzen interpretieren.":"Interpret a negative DNA NGS result only within the assay boundaries that were actually validated.","RNA-basierte Fusionsdiagnostik bei klinisch plausibler Fusionsfrage gegenüber serieller FISH und erneutem DNA-only-Test priorisieren.":"Prioritize RNA-based fusion testing over serial FISH and repeat DNA-only testing when there is a clinically plausible fusion question.","FISH als gezielte orthogonale Methode sinnvoll einordnen, ohne sie mit einer breiten parallelen Fusionssuche gleichzusetzen.":"Use FISH appropriately as a targeted orthogonal method without equating it with a broad parallel fusion screen.","Einen methodisch unvollständigen 'kein Treiber'-Befund im MTB aktiv korrigieren.":"Actively correct a methodologically incomplete ‘no driver’ result in the MTB.","Mittwochmorgen vor dem Thorax-MTB. Auf dem Bildschirm steht bei einer 42-jährigen Nie-Raucherin mit metastasiertem Lungenadenokarzinom bereits der externe Satz: 'Kein therapeutisch relevanter Treiber nachweisbar.' Die Onkologie plant deshalb eine nicht zielgerichtete Systemtherapie. Beim Lesen des Methodenteils fällt jedoch auf: Untersucht wurde ein DNA-only-Panel; eine belastbare RNA-basierte Fusionsdiagnostik ist nicht dokumentiert. Aus einem scheinbar abgeschlossenen Befund wird wieder eine offene Therapiefrage.":"Wednesday morning before the thoracic MTB. On screen, the external report for a 42-year-old never-smoker with metastatic lung adenocarcinoma already states: ‘No therapeutically relevant driver detected.’ Oncology is therefore planning non-targeted systemic therapy. But the methods section reveals that only a DNA-only panel was performed; robust RNA-based fusion testing is not documented. A seemingly closed result becomes an open treatment question again.","42-jährige Nie-Raucherin, ECOG 1, pulmonales Adenokarzinom mit Leber- und Knochenmetastasen. Externes DNA-NGS ohne relevante SNV/Indel-Treiber. Für das MTB muss entschieden werden, ob dieser Befund als treibernegativ akzeptiert werden kann oder ob die offene ALK/ROS1/RET/NTRK-Fusionsfrage mit einer geeigneten Methode geschlossen werden muss.":"42-year-old never-smoker, ECOG 1, pulmonary adenocarcinoma with liver and bone metastases. External DNA NGS shows no relevant SNV/indel driver. The MTB must decide whether this can be accepted as driver-negative or whether the open ALK/ROS1/RET/NTRK fusion question must be closed with an appropriate method.","Klinischer Kontext":"Clinical context","Junges Alter, Nie-Raucherstatus und Adenokarzinom machen eine onkogene Treiberalteration plausibel, beweisen sie aber nicht.":"Young age, never-smoking status and adenocarcinoma make an oncogenic driver alteration plausible but do not prove it.","Klinische Plausibilität steuert die Aufmerksamkeit; die Diagnose entsteht aus Methodik und Befund.":"Clinical plausibility directs attention; the diagnosis is established by method and result.","Externer Befund":"External result","DNA-NGS: EGFR, KRAS, BRAF, MET-Exon-14 und ERBB2 ohne relevante Alteration. Der Methodenteil beschreibt keine validierte breite RNA-Fusionsanalyse.":"DNA NGS: EGFR, KRAS, BRAF, MET exon 14 and ERBB2 without relevant alteration. The methods section describes no validated broad RNA fusion analysis.","'Negativ' ist nur so breit wie der verwendete Assay.":"‘Negative’ is only as broad as the assay used.","Leberbiopsie mit 35–40 % Tumor, acht ungefärbte Schnitte. RNA-QC ist grenzwertig bis ausreichend.":"Liver biopsy with 35–40% tumor, eight unstained sections. RNA QC is borderline to sufficient.","Jetzt ist eine gezielte, informationsreiche Ergänzung sinnvoller als serielle Einzeltests.":"A targeted, information-rich addition is now more useful than serial single tests.","MTB-Druck":"MTB time pressure","Therapieentscheidung in fünf Tagen; jeder unnötige Zusatzlauf kostet Zeit und Material.":"Treatment decision in five days; every unnecessary additional run costs time and material.","TAT und Material Stewardship gehören zur klinischen Methodenauswahl.":"TAT and material stewardship are part of clinical method selection.","HE/IHC":"H&E/IHC","Metastase eines TTF-1-/Napsin-A-positiven pulmonalen Adenokarzinoms.":"Metastasis of a TTF-1/Napsin-A-positive pulmonary adenocarcinoma.","DNA-NGS extern":"External DNA NGS","Kein relevanter SNV/Indel-Treiber; Fusionsabdeckung nicht ausreichend dokumentiert.":"No relevant SNV/indel driver; fusion coverage is not adequately documented.","RNA-QC":"RNA QC","RNA ist nicht perfekt, aber für einen zielgerichteten Fusionsassay noch verwertbar.":"RNA is not perfect, but remains usable for a targeted fusion assay.","Nur acht ungefärbte Schnitte verbleiben.":"Only eight unstained sections remain.","TAT-Ziel fünf Tage bis MTB.":"TAT target: five days until the MTB.","Eine breite serielle FISH-Strategie würde mehrere Einzelansätze und Vorannahmen benötigen.":"A broad serial FISH strategy would require multiple individual assays and prior assumptions.","Ein erneutes DNA-only-Panel kann denselben methodischen blinden Fleck reproduzieren.":"Repeating a DNA-only panel can reproduce the same methodological blind spot.","Was bedeutet der externe Satz 'kein therapeutisch relevanter Treiber nachweisbar' in diesem Fall?":"What does the external statement ‘no therapeutically relevant driver detected’ mean in this case?","Alle relevanten Treiber einschließlich Fusionen sind sicher ausgeschlossen.":"All relevant drivers, including fusions, have been safely excluded.","Er gilt nur innerhalb der validierten DNA-Assaygrenzen; die Fusionsfrage bleibt offen.":"It applies only within the validated DNA assay boundaries; the fusion question remains open.","Bei Nie-Rauchern ist ein negativer Befund grundsätzlich falsch.":"In never-smokers, a negative result is always false.","Er bedeutet automatisch, dass jetzt jede Fusion einzeln per FISH getestet werden muss.":"It automatically means that every fusion must now be tested individually by FISH.","Ein negativer molekularer Befund ist immer an die analytische Abdeckung der verwendeten Methode gebunden.":"A negative molecular result is always bound to the analytical coverage of the method used.","Welche Ergänzung beantwortet die offene breite Fusionsfrage am effizientesten?":"Which additional test answers the open broad fusion question most efficiently?","Breites RNA-basiertes Fusionspanel":"Broad RNA-based fusion panel","Dasselbe DNA-only-Panel noch einmal":"The same DNA-only panel again","Eine einzelne ALK-FISH als vollständiger Ersatz":"A single ALK FISH as a complete substitute","Keine Ergänzung, weil die Histologie bereits eindeutig ist":"No additional testing because histology is already unequivocal","RNA-NGS kann mehrere exprimierte Fusionsereignisse parallel erfassen und ist für diese offene Fragestellung besonders geeignet.":"RNA NGS can detect several expressed fusion events in parallel and is particularly suitable for this open question.","Wann bleibt FISH in diesem Fall sinnvoll?":"When does FISH remain useful in this case?","Bei konkreter Genhypothese als schnelle/orthogonale Bestätigung":"For a specific gene hypothesis as a rapid/orthogonal confirmation","Wenn RNA nicht verwertbar ist und ein gezielter Rearrangement-Nachweis benötigt wird":"When RNA is unusable and targeted rearrangement detection is required","Als universell umfassender Ersatz für eine breite RNA-Fusionsanalyse":"As a universally comprehensive substitute for broad RNA fusion analysis","Zur sicheren Bestimmung jedes Fusionspartners":"For reliably determining every fusion partner","FISH ist für gezielte Rearrangement-Fragen nützlich, aber meist weniger breit und partnerinformativ als RNA-basierte Verfahren.":"FISH is useful for targeted rearrangement questions but is usually less broad and less informative about the partner than RNA-based methods.","Entscheiden Sie, ob der externe DNA-negative Befund als vollständig akzeptiert werden kann und welche Ergänzung jetzt mit dem verbliebenen Material die größte klinische Information liefert.":"Decide whether the external DNA-negative result can be accepted as complete and which additional test now provides the greatest clinical information from the remaining material.","Methodenteil des externen DNA-Befunds prüfen und die unzureichend geklärte Fusionsabdeckung benennen.":"Review the methods section of the external DNA result and identify the inadequately resolved fusion coverage.","RNA-basiertes Fusionspanel priorisieren.":"Prioritize an RNA-based fusion panel.","Material aus dem markierten Tumorareal gezielt für RNA aufarbeiten.":"Process material from the marked tumor area specifically for RNA.","FISH nur bei konkreter Hypothese oder nicht verwertbarer RNA als gezielte Alternative/Bestätigung einsetzen.":"Use FISH only as a targeted alternative/confirmation for a specific hypothesis or unusable RNA.","Im MTB bis zum Abschluss der Fusionsdiagnostik nicht 'treibernegativ' formulieren.":"Do not call the case ‘driver-negative’ in the MTB until fusion testing is complete.","Validiertes kombiniertes DNA/RNA-Pan-Panel, wenn es die relevante Fusionsbreite sicher abdeckt und Material/TAT vertretbar sind.":"A validated combined DNA/RNA pan-panel if it reliably covers the relevant fusion spectrum and material/TAT are acceptable.","Gezielte RET-FISH, wenn RNA technisch scheitert und die konkrete Hypothese bereits fokussiert ist.":"Targeted RET FISH if RNA technically fails and the specific hypothesis is already focused.","DNA-negativ = vollständig negativ":"DNA-negative = completely negative","Die Aussage überschreitet die analytische Reichweite des verwendeten Assays.":"The statement exceeds the analytical reach of the assay used.","Serielle FISH für jede denkbare Fusion":"Serial FISH for every conceivable fusion","Material- und zeitintensiv; benötigt Vorannahmen und ist weniger parallelisierbar.":"Material- and time-intensive; requires prior assumptions and is less parallelizable.","Noch einmal dasselbe DNA-only-Panel":"Repeat the same DNA-only panel","Wiederholung behebt keinen systematischen Assay-Blindspot.":"Repeating does not fix a systematic assay blind spot.","Der 'treibernegative' Tumor ist nicht treibernegativ":"The ‘driver-negative’ tumor is not driver-negative","Das RNA-Fusionspanel detektiert eine exprimierte KIF5B::RET-Fusion. Eine anschließende gezielte RET-FISH bestätigt ein Rearrangement. Der zunächst geplante nicht zielgerichtete Therapieweg muss im MTB neu bewertet werden.":"The RNA fusion panel detects an expressed KIF5B::RET fusion. Subsequent targeted RET FISH confirms a rearrangement. The initially planned non-targeted treatment pathway must be reassessed in the MTB.","Der Fehler lag nicht in der Qualität des ersten DNA-Laufs, sondern in der zu breiten Interpretation eines methodisch begrenzten Negativbefunds.":"The error was not the quality of the first DNA run, but the overly broad interpretation of a methodologically limited negative result.","RNA schließt die offene Lücke":"RNA closes the open gap","KIF5B::RET-Fusion nachweisbar; DNA-SNV/Indel-Profil ohne weiteren relevanten Treiber.":"KIF5B::RET fusion detected; DNA SNV/indel profile without another relevant driver.","Sehr gut: Assaygrenze erkannt, passende Methode ergänzt, klinisch entscheidenden Treiber gefunden.":"Excellent: assay limitation recognized, appropriate method added, clinically decisive driver found.","DNA-only bleibt Endpunkt":"DNA-only remains the endpoint","Kein SNV/Indel-Treiber; Fusionsstatus bleibt methodisch unzureichend geklärt.":"No SNV/indel driver; fusion status remains methodologically insufficiently resolved.","Der Befund klingt abgeschlossen, ist es aber nicht.":"The report sounds complete, but it is not.","Einzel-FISH":"Single-gene FISH","Eine gezielte Einzel-FISH kann ein bestimmtes Rearrangement beantworten, lässt andere Fusionsklassen offen.":"A targeted single FISH can answer one specific rearrangement question but leaves other fusion classes open.","Bei fokussierter Hypothese sinnvoll, als breite Erststrategie unvollständig.":"Useful for a focused hypothesis, incomplete as a broad first-line strategy.","RNA ausreichend":"RNA sufficient","Breites RNA-Fusionspanel durchführen.":"Perform broad RNA fusion panel.","Direkter Nachweis KIF5B::RET und vollständige MTB-Einordnung.":"Direct detection of KIF5B::RET and complete MTB interpretation.","RNA nicht verwertbar":"RNA unusable","Gezielte FISH/alternatives validiertes Material erwägen.":"Consider targeted FISH/alternative validated material.","Fragestellung wird fokussiert weiterverfolgt statt vorschnell geschlossen.":"The question is pursued in a focused way rather than closed prematurely.","Nur DNA ausgewählt":"DNA only selected","Fusionsdiagnostik nachfordern.":"Request fusion testing.","Fall ist rettbar, aber TAT und Score verschlechtern sich.":"The case can be rescued, but TAT and score worsen.","Ein negativer Befund ist kein universeller biologischer Zustand, sondern ein methodisch begrenztes Messergebnis.":"A negative result is not a universal biological state but a method-limited measurement result.","RNA-basierte Verfahren sind bei vielen Fusionsfragen besonders wertvoll.":"RNA-based methods are particularly valuable for many fusion questions.","FISH bleibt relevant, wenn die Frage gezielt ist oder RNA scheitert.":"FISH remains relevant when the question is targeted or RNA fails.","Das Wort 'treibernegativ' sollte nur verwendet werden, wenn die relevanten Alterationsklassen tatsächlich adäquat untersucht wurden.":"The term ‘driver-negative’ should be used only when the relevant alteration classes have actually been adequately tested.","Der externe DNA-Befund darf nicht als vollständiger Treiberausschluss übernommen werden. Die offene Fusionsfrage wird mit einem breiten RNA-basierten Fusionspanel geschlossen. Ergebnis: KIF5B::RET-Fusion. FISH kann gezielt bestätigen oder bei nicht verwertbarer RNA aushelfen.":"The external DNA result must not be accepted as a complete driver exclusion. The open fusion question is closed with a broad RNA-based fusion panel. Result: KIF5B::RET fusion. FISH can confirm selectively or serve as a fallback when RNA is unusable.","Assaygrenze erkannt":"Assay limitation recognized","RNA-Fusionsdiagnostik priorisiert":"RNA fusion testing prioritized","FISH korrekt eingeordnet":"FISH correctly classified","Kein Overclaim eines negativen DNA-Befunds":"No overclaim from a negative DNA result","Wann ist DNA-NGS für Fusionen ausreichend?":"When is DNA NGS sufficient for fusions?","Welche Informationen liefert RNA zusätzlich zur strukturellen Umlagerung?":"What information does RNA provide in addition to the structural rearrangement?","Wie sollte ein pathologischer Negativbefund formuliert sein, wenn eine relevante Alterationsklasse nicht sicher abgedeckt ist?":"How should a pathology negative result be worded when a relevant alteration class is not reliably covered?","DE master reviewed structure":"DE master reviewed structure","KIF5B::RET trotz DNA-negativem Vorbericht":"KIF5B::RET despite prior DNA-negative report","Negativbefunde sind assaygebunden":"Negative results are assay-bound","DNA-negativ → Methodencheck → RNA → Fusion":"DNA-negative → method check → RNA → fusion","KRAS-mutiertes NSCLC mit STK11/KEAP1-Kontext → Target, Prognose, Immuntherapie-Kontext korrekt gewichten":"KRAS-mutant NSCLC with STK11/KEAP1 context → correctly weigh target, prognosis and immunotherapy context","KRAS-mutiertes NSCLC mit STK11/KEA…":"KRAS-mutant NSCLC with STK11/KEA…","Thoraxonkologie / MTB":"Thoracic oncology / MTB","66-jähriger Patient mit metastasiertem Lungenadenokarzinom. Das DNA-Panel zeigt KRAS p.G12C sowie pathogene STK11- und KEAP1-Alterationen.":"66-year-old man with metastatic lung adenocarcinoma. The DNA panel shows KRAS p.G12C plus pathogenic STK11 and KEAP1 alterations.","Bedeutet die Ko-Mutationskonstellation, dass Immuntherapie nicht sinnvoll ist? Welche Information ist tatsächlich therapeutisch, welche prognostisch und welche nur biologischer Kontext?":"Does the co-mutation pattern mean immunotherapy is not useful? Which information is truly therapeutic, which prognostic, and which only biological context?","Therapieentscheidung im MTB innerhalb einer Woche.":"Treatment decision at the MTB within one week.","35 pack years, vor sechs Jahren aufgehört.":"35 pack-years, stopped six years ago.","Stadium":"Stage","Leber-, Nebennieren- und ossäre Metastasen; ECOG 1.":"Liver, adrenal and bone metastases; ECOG 1.","Vorbehandlung":"Prior treatment","Keine systemische Therapie im metastasierten Stadium.":"No systemic therapy in the metastatic setting.","Klinische Falle":"Clinical trap","Im Vorbericht wurde STK11/KEAP1 bereits als 'Immuntherapie-Resistenzmarker' bezeichnet. Das Tumorboard möchte wissen, ob daraus ein Therapieausschluss folgt.":"The preliminary report has already labeled STK11/KEAP1 as ‘immunotherapy resistance markers’. The tumor board wants to know whether this implies treatment exclusion.","Pulmonales Adenokarzinom mit soliden und azinären Anteilen.":"Pulmonary adenocarcinoma with solid and acinar components.","TTF-1 positiv, p40 negativ.":"TTF-1 positive, p40 negative.","PD-L1":"PD-L1","Noch ausstehend.":"Pending.","Molekular":"Molecular","KRAS p.G12C, STK11 loss-of-function und KEAP1 loss-of-function; keine klassische EGFR-/ALK-/ROS1-Treiberkonstellation.":"KRAS p.G12C, STK11 loss-of-function and KEAP1 loss-of-function; no classic EGFR/ALK/ROS1 driver constellation.","Wie werden KRAS-Targetierbarkeit, adverse Ko-Mutationen und Immuntherapie-Kontext getrennt und zusammengeführt?":"How should KRAS targetability, adverse co-mutations and the immunotherapy context be separated and integrated?","FFPE-Lungenbiopsie mit ca. 45 % Tumoranteil.":"FFPE lung biopsy with approx. 45% tumor fraction.","DNA-QC":"DNA QC","ausreichend, Panel vollständig auswertbar.":"sufficient, panel fully evaluable.","9 ungefärbte Schnitte verfügbar.":"9 unstained sections available.","Zusätzliche explorative Biomarker dürfen nicht den Eindruck erzeugen, es gebe einen validierten Einzeltest, der die Immuntherapieentscheidung sicher vorhersagt.":"Additional exploratory biomarkers must not create the impression that there is a validated single test that reliably predicts the immunotherapy decision.","KRAS/STK11/KEAP1-Kontext":"KRAS/STK11/KEAP1 context","PD-L1-Kontext":"PD-L1 context","KRAS/STK11/KEAP1":"KRAS/STK11/KEAP1","KRAS p.G12C sowie pathogene STK11- und KEAP1-loss-of-function-Alterationen. Die Ko-Mutationen markieren eine biologisch ungünstige Subgruppe, sind aber kein eigenständiger binärer Ausschlusstest für Immuntherapie.":"KRAS p.G12C plus pathogenic STK11 and KEAP1 loss-of-function alterations. The co-mutations mark a biologically adverse subgroup but are not a stand-alone binary exclusion test for immunotherapy.","PD-L1 TPS 70 %. Hohe Expression ist klinisch relevant, muss aber zusammen mit klinischem Kontext und Ko-Mutationen interpretiert werden.":"PD-L1 TPS 70%. High expression is clinically relevant but must be interpreted together with clinical context and co-mutations.","TMB":"TMB","TMB im intermediären Bereich. Kein Befund, der die komplexe Ko-Mutationskonstellation alleine auflöst.":"TMB in the intermediate range. No finding that resolves the complex co-mutation constellation on its own.","Immun-Kontext-IHC":"Immune-context IHC","Relativ geringes CD8-positives Infiltrat. Biologisch interessant, aber kein validierter alleiniger Therapieausschlussmarker.":"Relatively sparse CD8-positive infiltrate. Biologically interesting, but not a validated stand-alone treatment exclusion marker.","DNA-QC und Tumoranteil ausreichend; PD-L1 technisch auswertbar.":"DNA QC and tumor fraction sufficient; PD-L1 technically evaluable.","KRAS p.G12C ist ein potenziell therapeutisch relevanter Genotyp im passenden Behandlungskontext. STK11/KEAP1 sind wichtige adverse biologische/prognostische Ko-Alterationen, dürfen aber nicht als binärer 'kein ICI'-Marker überinterpretiert werden. PD-L1 TPS 70 % bleibt eine eigenständige klinisch relevante Information.":"KRAS p.G12C is a potentially therapeutically relevant genotype in the appropriate treatment context. STK11/KEAP1 are important adverse biological/prognostic co-alterations but must not be overinterpreted as binary ‘no ICI’ markers. PD-L1 TPS 70% remains an independent clinically relevant piece of information.","Teilbefund: KRAS/Ko-Mutationen oder PD-L1 fehlen. Ohne beide Ebenen ist eine ausgewogene MTB-Einordnung nicht möglich.":"Partial result: KRAS/co-mutations or PD-L1 are missing. Without both levels, a balanced MTB interpretation is not possible.","KRAS p.G12C als Genotyp mit möglicher Target-Relevanz im passenden Therapiekontext benennen":"Identify KRAS p.G12C as a genotype with possible target relevance in the appropriate treatment context","STK11/KEAP1 als adverse Kontextmarker, nicht als absoluten ICI-Ausschluss darstellen":"Describe STK11/KEAP1 as adverse context markers, not as absolute ICI exclusions","PD-L1 separat und nicht durch Ko-Mutationen 'weginterpretieren'":"Report PD-L1 separately and do not ‘interpret it away’ because of co-mutations","Prognostische Assoziation und prädiktive Therapieentscheidung sprachlich trennen":"Distinguish prognostic association from predictive treatment decision in the wording","Optimale Lösung: KRAS, STK11/KEAP1 und PD-L1 auf getrennten Evidenzebenen berichten und im MTB integrieren; keine einzelne Ko-Mutation als absoluten Therapieausschluss verwenden.":"Optimal solution: report KRAS, STK11/KEAP1 and PD-L1 at separate levels of evidence and integrate them in the MTB; do not use any single co-mutation as an absolute treatment exclusion.","Immunescape":"Immune escape","Phase":"Phase","KRAS/STK11/KEAP1-NSCLC: Kontextmarker sind kein Therapie-Ausschalter":"KRAS/STK11/KEAP1 NSCLC: context markers are not treatment off-switches","KRAS-Targetierbarkeit, STK11/KEAP1-Kontext und PD-L1 auf getrennten Evidenzebenen einordnen.":"Classify KRAS targetability, STK11/KEAP1 context and PD-L1 on separate levels of evidence.","Prognostische bzw. assoziierte Resistenzsignale nicht als validierten binären prädiktiven Ausschlusstest formulieren.":"Do not phrase prognostic or associated resistance signals as a validated binary predictive exclusion test.","Widersprüchliche Biomarkerinformationen in einer balancierten MTB-Aussage integrieren.":"Integrate conflicting biomarker information into a balanced MTB statement.","Explorative TME-Marker von klinisch etablierten Routineentscheidungen trennen.":"Separate exploratory TME markers from clinically established routine decisions.","Im Thorax-MTB liegt ein Befund mit drei fett markierten Genen: KRAS, STK11 und KEAP1. Der Vorbericht bezeichnet die beiden Ko-Mutationen bereits als 'Immuntherapie-Resistenzmarker'. Gleichzeitig ist PD-L1 noch nicht bestimmt. Die klinische Frage lautet nicht nur, was mutiert ist, sondern ob aus dieser biologisch ungünstigen Konstellation wirklich ein Therapieverbot abgeleitet werden darf.":"At the thoracic MTB, the report contains three genes in bold: KRAS, STK11 and KEAP1. The preliminary report already calls the two co-mutations ‘immunotherapy resistance markers’. At the same time, PD-L1 has not yet been measured. The clinical question is not only what is mutated, but whether this biologically adverse constellation really justifies a treatment prohibition.","66-jähriger Patient, ehemaliger starker Raucher, metastasiertes Lungenadenokarzinom mit Leber-, Nebennieren- und Knochenmetastasen, ECOG 1. DNA-NGS zeigt KRAS p.G12C plus pathogene STK11- und KEAP1-Alterationen. Das MTB möchte Target-Relevanz, Prognose und Immuntherapie-Kontext sauber gewichten.":"66-year-old man, former heavy smoker, with metastatic lung adenocarcinoma involving liver, adrenal gland and bone, ECOG 1. DNA NGS shows KRAS p.G12C plus pathogenic STK11 and KEAP1 alterations. The MTB wants to weigh target relevance, prognosis and immunotherapy context appropriately.","Genotyp":"Genotype","KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.":"KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.","Nicht jede genetische Information erfüllt dieselbe klinische Funktion.":"Not every piece of genetic information serves the same clinical function.","Klinik":"Clinical situation","Hohe Tumorlast, aber aktuell stabil; keine vorangegangene systemische Therapie im metastasierten Stadium.":"High tumor burden, but currently stable; no prior systemic therapy in the metastatic setting.","Therapieentscheidungen bleiben klinisch eingebettet.":"Treatment decisions remain embedded in the clinical context.","Vorbericht":"Preliminary report","STK11/KEAP1 wurden als 'ICI-resistent' bezeichnet.":"STK11/KEAP1 were labeled ‘ICI-resistant’.","Assoziation mit ungünstigen Outcomes ist nicht dasselbe wie ein validierter absoluter Ausschlussmarker.":"Association with adverse outcomes is not the same as a validated absolute exclusion marker.","Offene Information":"Open information","PD-L1 steht noch aus; zusätzliche TMB-/TIL-Daten könnten biologischen Kontext liefern, sind aber kein Ersatz für klinische Evidenz.":"PD-L1 is still pending; additional TMB/TIL data may provide biological context but are no substitute for clinical evidence.","Mehr Biomarker bedeutet nicht automatisch eine klarere Therapieentscheidung.":"More biomarkers do not automatically produce a clearer treatment decision.","KRAS p.G12C; pathogene STK11- und KEAP1-loss-of-function-Alterationen.":"KRAS p.G12C; pathogenic STK11 and KEAP1 loss-of-function alterations.","TTF-1-positives pulmonales Adenokarzinom.":"TTF-1-positive pulmonary adenocarcinoma.","Noch nicht bestimmt.":"Not yet determined.","Ausreichendes FFPE-Material; keine akute Materialknappheit.":"Sufficient FFPE material; no acute material shortage.","Die eigentliche Grenze ist interpretativ: zusätzliche Marker dürfen nicht als stärker validiert erscheinen, als sie sind.":"The true limitation is interpretive: additional markers must not appear more strongly validated than they are.","TMB/CD8-IHC können Kontext liefern, sind in diesem Fall aber nicht als zwingende Entscheidungsmarker definiert.":"TMB/CD8 IHC can provide context but are not defined as mandatory decision markers in this case.","Welche Aussagen sind fachlich angemessen?":"Which statements are professionally appropriate?","KRAS p.G12C kann im geeigneten Therapiekontext targetrelevant sein.":"KRAS p.G12C can be target-relevant in the appropriate treatment context.","STK11/KEAP1 kennzeichnen eine biologisch/prognostisch ungünstige Subgruppe.":"STK11/KEAP1 identify a biologically/prognostically adverse subgroup.","STK11 oder KEAP1 schließen Immuntherapie grundsätzlich aus.":"STK11 or KEAP1 fundamentally exclude immunotherapy.","PD-L1 bleibt eine eigenständige klinisch relevante Information.":"PD-L1 remains an independent clinically relevant piece of information.","Die Marker besitzen unterschiedliche Rollen; STK11/KEAP1 sind kein binärer ICI-Ausschluss.":"The markers have different roles; STK11/KEAP1 are not binary ICI exclusions.","PD-L1 ergibt später TPS 70 %. Wie ist der Befund zu integrieren?":"PD-L1 later returns TPS 70%. How should this be integrated?","Ignorieren, weil STK11/KEAP1 wichtiger sind.":"Ignore it because STK11/KEAP1 are more important.","PD-L1 70 % garantiert eine sehr gute ICI-Antwort.":"PD-L1 70% guarantees an excellent ICI response.","Als relevante positive Information berichten, aber zusammen mit klinischem Kontext und der adversen Ko-Mutationsbiologie interpretieren.":"Report it as relevant positive information, but interpret it together with clinical context and the adverse co-mutation biology.","STK11/KEAP1 und PD-L1 heben sich gegenseitig auf; deshalb keine Aussage möglich.":"STK11/KEAP1 and PD-L1 cancel each other out; therefore no statement is possible.","Widersprüchliche Biomarker werden integriert, nicht gegeneinander 'verrechnet'.":"Conflicting biomarkers are integrated, not ‘subtracted’ from one another.","Welche Rolle haben TMB oder CD8/TIL-IHC hier?":"What role do TMB or CD8/TIL IHC play here?","Optionaler biologischer Kontext; kein alleiniger validierter Therapieausschluss.":"Optional biological context; not a validated stand-alone treatment exclusion.","Zwingend erforderlich, bevor überhaupt eine Therapie diskutiert werden darf.":"Mandatory before any treatment can even be discussed.","Sie ersetzen PD-L1 vollständig.":"They completely replace PD-L1.","Sie sind in der Tumorbiologie grundsätzlich bedeutungslos.":"They are fundamentally irrelevant in tumor biology.","Die Zusatzmarker können das biologische Bild vertiefen, lösen die klinische Evidenzfrage aber nicht allein.":"The additional markers can deepen the biological picture but do not resolve the clinical evidence question on their own.","Formulieren Sie eine MTB-Empfehlung, die KRAS p.G12C, STK11/KEAP1 und PD-L1 korrekt gewichtet, ohne aus einer Ko-Mutation ein nicht validiertes Therapieverbot zu machen.":"Formulate an MTB recommendation that appropriately weighs KRAS p.G12C, STK11/KEAP1 and PD-L1 without turning a co-mutation into a non-validated treatment prohibition.","KRAS p.G12C als eigenständigen Genotyp mit potenzieller Target-Relevanz im passenden Behandlungskontext benennen.":"Identify KRAS p.G12C as an independent genotype with potential target relevance in the appropriate treatment context.","STK11/KEAP1 als adverse biologische/prognostische Ko-Alterationen beschreiben.":"Describe STK11/KEAP1 as adverse biological/prognostic co-alterations.","PD-L1 bestimmen und separat berichten.":"Determine and report PD-L1 separately.","Aus STK11/KEAP1 keinen absoluten Immuntherapieausschluss ableiten.":"Do not derive an absolute immunotherapy exclusion from STK11/KEAP1.","Optional erhobene TMB/TIL-Daten als Kontext, nicht als übergeordneten Entscheidungsmarker kennzeichnen.":"Label optionally obtained TMB/TIL data as context, not as a superior decision marker.","Breites DNA-Panel statt fokussierter KRAS/STK11/KEAP1-Analyse, wenn es bereits Bestandteil der vollständigen NSCLC-Profilierung ist.":"Broad DNA panel instead of focused KRAS/STK11/KEAP1 analysis when it is already part of complete NSCLC profiling.","TMB oder Immun-Kontext-IHC als zusätzliche Lehr-/Kontextinformation, solange daraus keine binäre Therapieentscheidung konstruiert wird.":"TMB or immune-context IHC as additional teaching/context information, provided no binary treatment decision is constructed from it.","STK11/KEAP1 = kein ICI":"STK11/KEAP1 = no ICI","Aus einer adversen Assoziation wird fälschlich ein absoluter prädiktiver Ausschlussmarker.":"An adverse association is incorrectly turned into an absolute predictive exclusion marker.","PD-L1 hoch = sichere Antwort":"High PD-L1 = guaranteed response","Auch ein etablierter Biomarker ist kein individuelles Response-Versprechen.":"Even an established biomarker is not a promise of an individual response.","Jeden Kontextmarker erzwingen":"Force every context marker","Mehr Messwerte erhöhen nicht automatisch die klinische Entscheidungsqualität.":"More measurements do not automatically improve the quality of clinical decision-making.","Der 'resistente' Tumor hat PD-L1 TPS 70 %":"The 'resistant' tumor has PD-L1 TPS 70%","Die nachgeforderte PD-L1-IHC zeigt eine hohe Expression von 70 %. Eine optionale Immun-Kontext-IHC zeigt gleichzeitig nur ein geringes CD8-Infiltrat. Statt einer eindeutigen Antwort entsteht ein scheinbarer Widerspruch: positive etablierte Information, adverse Ko-Mutationsbiologie und ein eher 'cold' wirkendes Mikromilieu.":"The requested PD-L1 IHC shows high expression of 70%. An optional immune-context IHC simultaneously shows only sparse CD8 infiltration. Instead of a clear answer, an apparent contradiction emerges: positive established information, adverse co-mutation biology and a rather 'cold' microenvironment.","Der Fall zwingt dazu, Biomarker nach Evidenzebene zu gewichten statt sie zu einem simplen Plus/Minus-Score zu verrechnen.":"The case requires biomarkers to be weighted by level of evidence rather than reduced to a simple plus/minus score.","Evidenzebenen getrennt":"Levels of evidence separated","KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70 %. Ko-Mutationen werden als adverse Kontextmarker berichtet, nicht als absoluter ICI-Ausschluss.":"KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70%. Co-mutations are reported as adverse context markers, not as absolute ICI exclusion criteria.","Sehr gute, klinisch belastbare Integration.":"Very good, clinically robust integration.","STK11/KEAP1 verbieten ICI":"STK11/KEAP1 prohibit ICI","Die Ko-Mutationen werden als definitive prädiktive Resistenzmarker ausgegeben.":"The co-mutations are reported as definitive predictive resistance markers.","Overcalling: prognostisch/assoziativ wird mit binär prädiktiv verwechselt.":"Overcalling: prognostic/associative evidence is confused with binary predictive evidence.","Nur PD-L1 zählt":"Only PD-L1 matters","PD-L1 70 % wird ohne Genotyp- und Ko-Mutationskontext als eindeutige Antwort dargestellt.":"PD-L1 70% is presented as an unequivocal answer without genotype and co-mutation context.","Unvollständige Integration und zu starke Individualprognose.":"Incomplete integration and overly strong individual prognosis.","PD-L1 fehlt":"PD-L1 missing","PD-L1 ergänzen.":"Add PD-L1.","Etablierte klinische Information steht für die MTB-Integration zur Verfügung.":"Established clinical information is available for MTB integration.","TMB/TILs gewählt":"TMB/TILs selected","Als optionalen Kontext berichten.":"Report as optional context.","Kein zusätzlicher binärer Therapieentscheid aus diesen Daten.":"No additional binary treatment decision should be derived from these data.","STK11/KEAP1 als Ausschluss formuliert":"STK11/KEAP1 phrased as exclusion","Befund sprachlich korrigieren.":"Correct the report wording.","Prognostische/assoziierte Evidenz wird von prädiktiver Aussage getrennt.":"Prognostic/associative evidence is separated from predictive statements.","Ein molekulares Panel liefert nicht automatisch Marker gleicher klinischer Wertigkeit.":"A molecular panel does not automatically produce markers of equal clinical value.","STK11/KEAP1 sind wichtige adverse Kontextinformationen, aber keine simplen ICI-Ausschalter.":"STK11/KEAP1 are important adverse contextual information, but not simple ICI off-switches.","PD-L1 bleibt relevant, ohne individuelle Antwort zu garantieren.":"PD-L1 remains relevant without guaranteeing an individual response.","Gute MTB-Kommunikation macht die Evidenzebene jeder Aussage sichtbar.":"Good MTB communication makes the level of evidence behind each statement explicit.","KRAS p.G12C wird als eigenständiger targetrelevanter Genotyp im passenden Therapiekontext berichtet. STK11/KEAP1 werden als adverse biologische/prognostische Ko-Alterationen eingeordnet, nicht als absolutes ICI-Verbot. PD-L1 TPS 70 % bleibt klinisch relevant. TMB/TILs können Kontext liefern, dürfen aber nicht überinterpretiert werden.":"KRAS p.G12C is reported as an independently target-relevant genotype in the appropriate treatment context. STK11/KEAP1 are classified as adverse biological/prognostic co-alterations, not as an absolute prohibition of ICI. PD-L1 TPS 70% remains clinically relevant. TMB/TILs may provide context but must not be overinterpreted.","Keine binäre STK11/KEAP1-Überinterpretation":"No binary overinterpretation of STK11/KEAP1","PD-L1 integriert":"PD-L1 integrated","KRAS-Targetebene getrennt":"KRAS target level separated","Zusatzmarker limitiert formuliert":"Additional markers phrased with limitations","Wann wird ein prognostischer Marker prädiktiv?":"When does a prognostic marker become predictive?","Wie sollte ein Befund formuliert sein, damit die Onkologie die Evidenzebene sofort erkennt?":"How should a report be worded so that oncology immediately recognizes the level of evidence?","Welche Rolle könnten Ko-Mutationen künftig für Therapiestratifizierung spielen, ohne heutige Routineentscheidungen vorwegzunehmen?":"What role might co-mutations play in future treatment stratification without pre-empting today's routine decisions?","PD-L1 70 % trotz STK11/KEAP1":"PD-L1 70% despite STK11/KEAP1","Biomarker nach Evidenzebene gewichten":"Weight biomarkers by level of evidence","Genotyp → Ko-Mutationen → PD-L1 → integrierte Aussage":"Genotype → co-mutations → PD-L1 → integrated statement","Melanom: BRAF V600 und Immuntherapie-Sequenz → Schnelle TKI-Therapie vs. Immuncheckpoint-Strategie":"Melanoma: BRAF V600 and immunotherapy sequencing → Rapid targeted therapy vs. immune checkpoint strategy","Melanom: BRAF V600 und Immuntherap…":"Melanoma: BRAF V600 and immunotherapy sequenc…","Dermatoonkologie / Interdisziplinäres Tumorboard":"Dermato-oncology / Interdisciplinary tumor board","51-jähriger Patient mit neu metastasiertem kutanem Melanom, pulmonalen und hepatischen Metastasen.":"51-year-old patient with newly metastatic cutaneous melanoma, pulmonary and hepatic metastases.","Liegt eine BRAF-V600-Alteration vor und wie beeinflusst sie die Sequenz zwischen Immuncheckpoint- und BRAF/MEK-Strategie?":"Is a BRAF V600 alteration present and how does it influence sequencing between immune checkpoint and BRAF/MEK strategies?","Systemische Therapie soll innerhalb weniger Tage beginnen.":"Systemic treatment should start within a few days.","Performance":"Performance status","ECOG 0–1, zunächst klinisch stabil.":"ECOG 0–1, initially clinically stable.","Tumorlast":"Tumor burden","Mehrere Lebermetastasen, LDH moderat erhöht, keine initialen neurologischen Symptome.":"Multiple liver metastases, moderately elevated LDH, no initial neurological symptoms.","Entscheidungsfalle":"Decision trap","Der Nachweis einer BRAF-V600-Mutation entscheidet nicht automatisch über die erste Therapiesequenz; klinisches Tempo, ZNS-Situation, Steroidbedarf und Eignung für Immuntherapie sind mitentscheidend.":"Detection of a BRAF V600 mutation does not automatically determine the first treatment sequence; clinical tempo, CNS status, steroid requirement and suitability for immunotherapy also matter.","Metastase eines malignen Melanoms.":"Metastasis of malignant melanoma.","SOX10 und S100 positiv, Melan-A fokal positiv.":"SOX10 and S100 positive, Melan-A focally positive.","Molekulare Kernfrage":"Core molecular question","BRAF V600 muss rasch geklärt werden, damit beide strategischen Optionen realistisch bewertet werden können.":"BRAF V600 must be clarified rapidly so that both strategic options can be assessed realistically.","Nicht die Kernfrage":"Not the core question","PD-L1, TMB oder TILs sind in diesem Fall keine einfachen Schalter für die Sequenzentscheidung.":"PD-L1, TMB or TILs are not simple switches for the sequencing decision in this case.","FFPE-Lebermetastase, Block L4.":"FFPE liver metastasis, block L4.","ca. 60 %, geringe Nekrose.":"approx. 60%, little necrosis.","gut; rascher BRAF-Test technisch problemlos möglich.":"good; rapid BRAF testing is technically straightforward.","10 ungefärbte Schnitte verfügbar.":"10 unstained sections available.","Breite Zusatzdiagnostik darf die dringliche BRAF-Klärung nicht verzögern.":"Broad additional testing must not delay urgent BRAF clarification.","BRAF V600-Status":"BRAF V600 status","BRAF V600":"BRAF V600","BRAF p.V600E nachweisbar. Damit ist eine BRAF/MEK-basierte Therapieoption grundsätzlich vorhanden.":"BRAF p.V600E detected. A BRAF/MEK-based treatment option is therefore available in principle.","Melanom-IO-Kontext":"Melanoma IO context","Immunhistologischer Kontext ohne eindeutigen Ausschlussbefund. Die Sequenzentscheidung bleibt primär klinisch-strategisch und wird nicht durch einen einzelnen IHC-Marker festgelegt.":"Immunohistologic context without a clear exclusion finding. The sequencing decision remains primarily clinical-strategic and is not determined by a single IHC marker.","TMB erhöht. Dies ersetzt weder die BRAF-Testung noch die klinische Sequenzentscheidung.":"TMB elevated. This replaces neither BRAF testing nor the clinical sequencing decision.","Tumoranteil und DNA-Qualität sind gut; BRAF-V600-Status ist rasch und belastbar bestimmbar.":"Tumor fraction and DNA quality are good; BRAF V600 status can be determined rapidly and reliably.","BRAF p.V600E ist nachweisbar und eröffnet eine BRAF/MEK-Option. Bei zunächst klinisch stabilem, immuntherapiefähigem Patienten spricht die Evidenz häufig für eine Immuntherapie-first-Strategie; bei rascher klinischer Verschlechterung oder notwendigem schnellen Tumoransprechen kann sich die Gewichtung zugunsten einer zielgerichteten Therapie verschieben.":"BRAF p.V600E is detected and creates a BRAF/MEK option. In an initially clinically stable patient suitable for immunotherapy, the evidence often favors an immunotherapy-first strategy; with rapid clinical deterioration or a need for rapid tumor response, the balance may shift toward targeted therapy.","Teilbefund: Ohne geklärten BRAF-V600-Status fehlt eine zentrale Voraussetzung für die Sequenzplanung. Zusätzliche IO-Kontextmarker ersetzen diese Klärung nicht.":"Partial finding: Without clarified BRAF V600 status, a key prerequisite for sequence planning is missing. Additional IO context markers do not replace this clarification.","BRAF V600 als Voraussetzung für eine BRAF/MEK-Option benennen":"State BRAF V600 as a prerequisite for a BRAF/MEK option","Therapiesequenz nicht allein aus dem Mutationsstatus ableiten":"Do not derive the treatment sequence from mutation status alone","Tumorlast, klinisches Tempo, ZNS-Beteiligung/Steroidbedarf und Immuntherapiefähigkeit berücksichtigen":"Consider tumor burden, clinical tempo, CNS involvement/steroid requirement and suitability for immunotherapy","PD-L1/TMB/TILs nicht als simplen Sequenzschalter verwenden":"Do not use PD-L1/TMB/TILs as a simple sequencing switch","Optimale Lösung: BRAF V600 rasch klären und anschließend die Sequenz anhand von Evidenz und klinischer Dynamik entscheiden; Mutation vorhanden bedeutet nicht automatisch 'Targeted Therapy zuerst'.":"Optimal solution: Clarify BRAF V600 rapidly and then decide the sequence based on evidence and clinical dynamics; mutation present does not automatically mean 'targeted therapy first'.","BRAF":"BRAF","KI":"AI","Melanom":"Melanoma","BRAF-V600-Melanom: Die Mutation eröffnet eine Option – die Klinik bestimmt die Sequenz":"BRAF V600 melanoma: The mutation opens an option – the clinical situation determines the sequence","Molekularpathologie / Dermatoonkologie / MTB":"Molecular pathology / Dermato-oncology / MTB","BRAF V600 als prädiktiven Marker für eine Target-Option korrekt bestimmen.":"Correctly determine BRAF V600 as a predictive marker for a targeted-treatment option.","Den BRAF-Nachweis nicht mit einer automatischen Targeted-Therapy-first-Entscheidung verwechseln.":"Do not confuse BRAF detection with an automatic targeted-therapy-first decision.","Klinisches Tempo, Tumorlast, ZNS-Beteiligung, Steroidbedarf und Immuntherapiefähigkeit in die Sequenz einbeziehen.":"Include clinical tempo, tumor burden, CNS involvement, steroid requirement and suitability for immunotherapy in sequencing.","PD-L1/TMB/TILs beim Melanom nicht als einfachen Sequenzschalter überinterpretieren.":"Do not overinterpret PD-L1/TMB/TILs in melanoma as a simple sequencing switch.","Freitagnachmittag im Melanomboard. Ein 51-jähriger Patient mit neu metastasiertem Melanom ist BRAF noch nicht getestet. Die Onkologie diskutiert bereits zwei sehr unterschiedliche Strategien: zuerst Immuncheckpoint-Therapie mit Aussicht auf langanhaltende Kontrolle oder – falls BRAF V600 positiv – eine BRAF/MEK-Therapie mit typischerweise rascherem Ansprechen. Noch wirkt der Patient klinisch stabil. Die Frage scheint planbar. Zwei Tage später ändert sich die Situation.":"Friday afternoon in the melanoma board. A 51-year-old patient with newly metastatic melanoma has not yet been tested for BRAF. Oncology is already discussing two very different strategies: immune checkpoint therapy first, with the prospect of durable control, or – if BRAF V600 is positive – BRAF/MEK therapy with typically faster response. The patient still appears clinically stable. The question seems manageable. Two days later, the situation changes.","51-jähriger Patient, kutanes Melanom mit Leber- und Lungenmetastasen, ECOG 0–1, moderat erhöhtes LDH. Keine systemische Vorbehandlung. Zunächst keine neurologischen Symptome. Für die Sequenzentscheidung muss der BRAF-V600-Status rasch vorliegen; die endgültige Strategie darf aber nicht allein aus dem Genotyp abgeleitet werden.":"51-year-old patient, cutaneous melanoma with liver and lung metastases, ECOG 0–1, moderately elevated LDH. No prior systemic treatment. Initially no neurological symptoms. BRAF V600 status must be available quickly for sequencing, but the final strategy must not be derived from genotype alone.","Molekulare Voraussetzung":"Molecular prerequisite","Ohne BRAF-V600-Nachweis gibt es keine belastbare Grundlage für eine BRAF/MEK-Strategie.":"Without detection of BRAF V600 there is no robust basis for a BRAF/MEK strategy.","Erst Option nachweisen, dann Sequenz diskutieren.":"First establish the option, then discuss the sequence.","Initiale Klinik":"Initial clinical status","ECOG 0–1, systemisch metastasiert, aber zunächst keine akute Organ- oder ZNS-Symptomatik.":"ECOG 0–1, systemically metastatic, but initially no acute organ or CNS symptoms.","Bei klinischer Stabilität kann Langzeitstrategie stärker gewichtet werden.":"When clinically stable, the long-term strategy can be weighted more heavily.","Evidenz zur Sequenz":"Sequencing evidence","Für viele geeignete Patienten mit BRAF-V600-mutiertem metastasiertem Melanom spricht die randomisierte Sequenzevidenz für Immuntherapie zuerst; dies ist aber keine starre Regel für jede klinische Situation.":"For many suitable patients with BRAF V600-mutant metastatic melanoma, randomized sequencing evidence supports immunotherapy first; however, this is not a rigid rule for every clinical situation.","Populationsevidenz und individuelle Dringlichkeit müssen zusammengeführt werden.":"Population-level evidence and individual urgency must be integrated.","Nicht der Schalter":"Not the switch","PD-L1, TMB und TILs können biologisch interessant sein, ersetzen aber weder BRAF-Testung noch die klinische Sequenzentscheidung.":"PD-L1, TMB and TILs may be biologically interesting, but replace neither BRAF testing nor the clinical sequencing decision.","Nicht jedes messbare Immunmerkmal ist ein Routine-Entscheidungstest.":"Not every measurable immune feature is a routine decision test.","Histologie/IHC":"Histology/IHC","Metastase eines SOX10-/S100-positiven malignen Melanoms.":"Metastasis of a SOX10-/S100-positive malignant melanoma.","Klinik initial":"Initial clinical status","Keine symptomatische ZNS-Beteiligung; keine Steroidtherapie.":"No symptomatic CNS involvement; no steroid therapy.","Material-QC":"Material QC","Lebermetastase mit ca. 60 % Tumor; DNA-QC gut.":"Liver metastasis with approx. 60% tumor; DNA QC good.","BRAF-V600-Status muss rasch vorliegen; unnötige Zusatzanalysen dürfen die Entscheidung nicht verzögern.":"BRAF V600 status must be available rapidly; unnecessary additional analyses must not delay the decision.","Therapiesequenz kann nicht aus der Pathologie allein entschieden werden; aktuelle klinische Dynamik muss ins MTB zurückgespielt werden.":"Treatment sequencing cannot be decided by pathology alone; current clinical dynamics must be fed back into the MTB.","PD-L1/TMB/TILs sind nicht als zwingende Sequenzmarker definiert.":"PD-L1/TMB/TILs are not defined as mandatory sequencing markers.","Welche molekulare Information muss für die Targeted-Therapy-Option zuerst belastbar vorliegen?":"Which molecular information must first be reliably available for the targeted-therapy option?","PD-L1 zwingend":"PD-L1 mandatory","TMB zwingend":"TMB mandatory","CD8/TIL-IHC zwingend":"CD8/TIL IHC mandatory","BRAF V600 ist die zentrale molekulare Voraussetzung für eine BRAF/MEK-basierte Option.":"BRAF V600 is the key molecular prerequisite for a BRAF/MEK-based option.","Welche Faktoren beeinflussen die Sequenzentscheidung zusätzlich zum BRAF-Status?":"Which factors influence sequencing in addition to BRAF status?","Klinisches Progressionstempo und Tumorlast":"Clinical pace of progression and tumor burden","ZNS-Beteiligung und neurologische Symptomatik":"CNS involvement and neurological symptoms","Steroidbedarf/Immuntherapiefähigkeit":"Steroid requirement/suitability for immunotherapy","Allgemeinzustand und Eignung für die jeweiligen Regime":"General condition and suitability for the respective regimens","Alleiniger PD-L1-Wert als Sequenzschalter":"PD-L1 value alone as sequencing switch","Die Sequenz ist eine klinisch-strategische Entscheidung, nicht nur eine Genotypentscheidung.":"Sequencing is a clinical-strategic decision, not merely a genotype decision.","Der Patient ist BRAF V600E-positiv und klinisch stabil. Welche Aussage ist am besten?":"The patient is BRAF V600E-positive and clinically stable. Which statement is best?","Für viele geeignete Patienten spricht die Sequenzevidenz für Immuntherapie-first; individuelle Faktoren bleiben entscheidend.":"For many suitable patients, sequencing evidence supports immunotherapy first; individual factors remain decisive.","BRAF V600E bedeutet zwingend BRAF/MEK zuerst.":"BRAF V600E mandates BRAF/MEK first.","Bei BRAF-Mutation sollte Immuntherapie nicht eingesetzt werden.":"Immunotherapy should not be used when BRAF is mutated.","Erst PD-L1 entscheidet, ob BRAF/MEK oder Immuntherapie beginnt.":"PD-L1 alone decides whether BRAF/MEK or immunotherapy starts first.","Randomisierte Sequenzdaten favorisieren bei vielen geeigneten Patienten Immuntherapie-first, ohne jede dringliche Ausnahmesituation abzudecken.":"Randomized sequencing data favor immunotherapy first in many suitable patients without covering every urgent exceptional situation.","Bestimmen Sie den BRAF-V600-Status und formulieren Sie anschließend eine Sequenzempfehlung, die Evidenz und aktuelle klinische Dynamik ausdrücklich miteinander verknüpft.":"Determine BRAF V600 status and then formulate a sequencing recommendation that explicitly links evidence with the current clinical dynamics.","BRAF-V600-Testung rasch durchführen.":"Perform BRAF V600 testing rapidly.","Bei BRAF p.V600E beide prinzipiellen Strategien als verfügbar benennen.":"If BRAF p.V600E is present, state that both principal strategies are available.","Bei klinisch stabilem, immuntherapiefähigem Patienten die Evidenz für Immuntherapie-first diskutieren.":"In a clinically stable patient suitable for immunotherapy, discuss the evidence for immunotherapy first.","Vor Therapiebeginn aktuelle ZNS-Situation, Steroidbedarf und Progressionstempo erneut prüfen.":"Before treatment starts, reassess current CNS status, steroid requirement and pace of progression.","Bei akuter Dynamik die Notwendigkeit schnellen Ansprechens neu gewichten.":"With acute clinical dynamics, reweight the need for a rapid response.","Validiertes breites Panel, wenn BRAF V600 ohne relevante Verzögerung sicher erfasst wird.":"Validated broad panel if it reliably covers BRAF V600 without relevant delay.","Targeted Therapy first bei dringlicher klinischer Situation oder wenn Immuntherapie nicht geeignet ist; dies muss explizit klinisch begründet werden.":"Targeted therapy first in an urgent clinical situation or when immunotherapy is unsuitable; this must be explicitly justified clinically.","BRAF-mutiert = automatisch Targeted Therapy first":"BRAF-mutant = automatically targeted therapy first","Der Genotyp eröffnet die Option, entscheidet aber nicht alleine die optimale Sequenz.":"The genotype opens the option but does not by itself determine the optimal sequence.","PD-L1 entscheidet die Reihenfolge":"PD-L1 decides the sequence","Beim metastasierten Melanom ist PD-L1 kein einfacher Sequenzschalter zwischen BRAF/MEK und Immuntherapie.":"In metastatic melanoma, PD-L1 is not a simple sequencing switch between BRAF/MEK and immunotherapy.","Klinik vom Molekularbefund trennen":"Separate clinical status from molecular finding","Eine Sequenzentscheidung kann sich durch akute Progression innerhalb von Tagen verändern.":"A sequencing decision can change within days because of acute progression.","48 Stunden später: neue symptomatische Hirnmetastase":"48 hours later: new symptomatic brain metastasis","Noch vor Therapiebeginn entwickelt der Patient Kopfschmerzen und eine diskrete Hemiparese. Das MRT zeigt eine neue symptomatische Hirnmetastase; Dexamethason wird begonnen. Gleichzeitig liegt der molekulare Befund vor: BRAF p.V600E. Die ursprünglich in Ruhe geplante Sequenz muss unter dem Gesichtspunkt rascher Krankheitskontrolle und Steroidbedarf neu diskutiert werden.":"Before treatment starts, the patient develops headache and mild hemiparesis. MRI shows a new symptomatic brain metastasis; dexamethasone is started. At the same time, the molecular result becomes available: BRAF p.V600E. The sequence originally planned at leisure must now be reconsidered in light of the need for rapid disease control and steroid use.","Der molekulare Befund ist unverändert, aber die klinische Priorität hat sich verändert. Genau deshalb darf BRAF V600 nie isoliert als Sequenzautomat interpretiert werden.":"The molecular finding is unchanged, but the clinical priority has changed. This is exactly why BRAF V600 must never be interpreted in isolation as an automatic sequencing command.","BRAF positiv, Klinik integriert":"BRAF positive, clinical context integrated","BRAF p.V600E nachweisbar. Beide Strategien sind grundsätzlich verfügbar; nach klinischer Verschlechterung wird die Notwendigkeit schneller Kontrolle im MTB neu gewichtet.":"BRAF p.V600E detected. Both strategies are available in principle; after clinical deterioration, the need for rapid control is reweighted in the MTB.","Sehr gute Verbindung von molekularer Option und klinischer Situation.":"Very good linkage between molecular option and clinical situation.","Mutation entscheidet alles":"Mutation decides everything","BRAF p.V600E wird automatisch mit 'BRAF/MEK zuerst' gleichgesetzt, unabhängig von Klinik und Sequenzevidenz.":"BRAF p.V600E is automatically equated with 'BRAF/MEK first' regardless of clinical context and sequencing evidence.","Zu mechanistisch; Option und Sequenz wurden verwechselt.":"Too mechanistic; availability of an option was confused with sequencing.","Nur IO-Kontextmarker":"Only IO context markers","PD-L1/TMB/TILs werden breit untersucht, BRAF bleibt ausstehend.":"PD-L1/TMB/TILs are tested broadly while BRAF remains pending.","Die zentrale molekulare Voraussetzung für eine Targeted-Therapy-Option fehlt.":"The key molecular prerequisite for a targeted-therapy option is missing.","BRAF V600E positiv, klinisch stabil":"BRAF V600E positive, clinically stable","Immuntherapie-first als evidenzgestützte Standardstrategie für viele geeignete Patienten diskutieren.":"Discuss immunotherapy first as an evidence-supported standard strategy for many suitable patients.","Langfristige Sequenzplanung steht im Vordergrund.":"Long-term sequencing strategy is the priority.","Neue symptomatische ZNS-Progression/Steroidbedarf":"New symptomatic CNS progression/steroid requirement","Sequenz im MTB sofort neu bewerten und schnelle Krankheitskontrolle stärker gewichten.":"Reassess sequencing immediately in the MTB and give greater weight to rapid disease control.","Targeted Therapy kann klinisch an Gewicht gewinnen.":"Targeted therapy may gain clinical weight.","BRAF nicht bestimmt":"BRAF not determined","Schnelltest nachfordern.":"Request rapid test.","Sequenzentscheidung bleibt unvollständig.":"Sequencing decision remains incomplete.","BRAF V600 ist ein prädiktiver Marker für eine Target-Option, kein automatischer Sequenzbefehl.":"BRAF V600 is a predictive marker for a targeted option, not an automatic sequencing command.","Bei vielen geeigneten, stabilen Patienten spricht randomisierte Sequenzevidenz für Immuntherapie-first.":"For many suitable, stable patients, randomized sequencing evidence supports immunotherapy first.","Akute klinische Dynamik kann die optimale Reihenfolge verändern.":"Acute clinical dynamics can change the optimal order.","Molekularpathologie ist Teil der Entscheidung, aber nicht deren alleiniger Eigentümer.":"Molecular pathology is part of the decision, but not its sole owner.","BRAF p.V600E wird rasch bestätigt. Zunächst wäre bei klinischer Stabilität für viele geeignete Patienten Immuntherapie-first evidenzgestützt. Der Twist – symptomatische Hirnmetastase mit Steroidbedarf – erzwingt eine erneute klinische Gewichtung und kann die Bedeutung einer rasch wirksamen BRAF/MEK-Strategie erhöhen. PD-L1/TMB/TILs sind kein einfacher Sequenzschalter.":"BRAF p.V600E is rapidly confirmed. Initially, with clinical stability, immunotherapy first would be evidence-supported for many suitable patients. The twist – symptomatic brain metastasis requiring steroids – forces a renewed clinical weighting and may increase the importance of a rapidly effective BRAF/MEK strategy. PD-L1/TMB/TILs are not a simple sequencing switch.","BRAF als Voraussetzung erkannt":"BRAF recognized as prerequisite","Keine automatische Targeted-first-Regel":"No automatic targeted-first rule","Klinische Dynamik integriert":"Clinical dynamics integrated","IO-Kontextmarker nicht überinterpretiert":"IO context markers not overinterpreted","Welche Patientengruppen waren in Sequenzstudien besonders gut repräsentiert – und welche weniger?":"Which patient groups were particularly well represented in sequencing studies – and which were less so?","Wie ändert Steroidbedarf die praktische Immuntherapieplanung?":"How does steroid requirement change practical immunotherapy planning?","Welche Information muss die Pathologie liefern und welche Entscheidung bleibt interdisziplinär?":"Which information must pathology provide and which decision remains interdisciplinary?","symptomatische Hirnmetastase nach initial stabiler Situation":"symptomatic brain metastasis after initially stable situation","Mutation eröffnet Option, Klinik bestimmt Sequenz":"Mutation opens the option, clinical situation determines the sequence","BRAF-Test → stabile Sequenzplanung → klinischer Twist → Re-Assessment":"BRAF test → stable sequencing plan → clinical twist → reassessment","GIST mit KIT/PDGFRA-Fragestellung → Welcher Marker entscheidet über TKI-Auswahl?":"GIST with KIT/PDGFRA question → Which marker determines TKI selection?","GIST mit KIT/PDGFRA-Fragestellung":"GIST with KIT/PDGFRA question","Sarkomzentrum / MTB":"Sarcoma center / MTB","64-jährige Patientin mit gastralem GIST und neu aufgetretenen Lebermetastasen.":"64-year-old woman with gastric GIST and newly developed liver metastases.","Ist 'GIST = Imatinib' ausreichend, oder muss vor der TKI-Auswahl der KIT/PDGFRA-Genotyp vorliegen?":"Is 'GIST = imatinib' sufficient, or must the KIT/PDGFRA genotype be available before choosing a TKI?","Therapiebeginn ist nach Abschluss der molekularen Typisierung geplant.":"Treatment is planned to start after molecular typing is completed.","Primärtumor":"Primary tumor","Gastraler GIST, vor drei Jahren reseziert; nun hepatische Metastasierung.":"Gastric GIST resected three years ago; now hepatic metastases.","Keine systemische TKI-Therapie.":"No systemic TKI therapy.","Klinischer Reflex":"Clinical reflex","Im Tumorboard fällt früh der Satz: 'CD117-positiver GIST – dann Imatinib.'":"Early in the tumor board someone says: 'CD117-positive GIST – then imatinib.'","Lernziel":"Learning objective","Diagnosemarker und prädiktiver Genotyp müssen getrennt werden.":"Diagnostic markers and predictive genotype must be kept separate.","Epithelioider mesenchymaler Tumor, morphologisch passend zu GIST.":"Epithelioid mesenchymal tumor, morphologically consistent with GIST.","DOG1 stark positiv, CD117 nur fokal/heterogen positiv.":"DOG1 strongly positive, CD117 only focal/heterogeneous.","Arbeitsdiagnose":"Working diagnosis","Metastasierter gastrointestinaler Stromatumor.":"Metastatic gastrointestinal stromal tumor.","Welcher KIT-/PDGFRA-Genotyp liegt vor und verändert er die TKI-Auswahl?":"Which KIT/PDGFRA genotype is present and does it alter TKI selection?","FFPE-Lebermetastase, Block H3.":"FFPE liver metastasis, block H3.","ca. 75 %, DNA-QC gut.":"approx. 75%, DNA QC good.","6 ungefärbte Schnitte verfügbar.":"6 unstained sections available.","Ein sehr breites Pan-Tumor-Panel ist für die konkrete Erstfrage unnötig, wenn eine valide KIT/PDGFRA-Analyse verfügbar ist.":"A very broad pan-tumor panel is unnecessary for the specific first-line question when a valid KIT/PDGFRA assay is available.","KIT/PDGFRA-Genotyp":"KIT/PDGFRA genotype","KIT/PDGFRA":"KIT/PDGFRA","PDGFRA Exon 18 p.D842V nachweisbar; keine aktivierende KIT-Mutation. Die Konstellation ist für die TKI-Auswahl unmittelbar relevant.":"PDGFRA exon 18 p.D842V detected; no activating KIT mutation. This constellation is directly relevant to TKI selection.","Hoher Tumoranteil, DNA-Qualität gut; gezielte KIT/PDGFRA-Analyse vollständig auswertbar.":"High tumor fraction, good DNA quality; focused KIT/PDGFRA analysis is fully evaluable.","Metastasierter GIST mit PDGFRA p.D842V. Der Genotyp widerspricht dem reflexhaften 'Imatinib für jeden GIST'-Schema und verlangt eine genotypspezifische TKI-Strategie.":"Metastatic GIST with PDGFRA p.D842V. The genotype contradicts the reflexive 'imatinib for every GIST' scheme and requires a genotype-specific TKI strategy.","Teilbefund: Die GIST-Diagnose ist morphologisch/IHC-basiert gesichert, aber ohne KIT/PDGFRA-Genotyp ist die prädiktive TKI-Einordnung unvollständig.":"Partial finding: The GIST diagnosis is established morphologically/IHC, but without KIT/PDGFRA genotype the predictive TKI classification is incomplete.","DOG1/CD117 als Diagnosekontext, nicht als ausreichenden prädiktiven Marker einordnen":"Classify DOG1/CD117 as diagnostic context, not as sufficient predictive markers","PDGFRA D842V explizit benennen":"Explicitly state PDGFRA D842V","Genotypspezifische TKI-Auswahl statt pauschalem Imatinib-Reflex formulieren":"Phrase genotype-specific TKI selection instead of a blanket imatinib reflex","Bei KIT/PDGFRA-Wildtyp weitere molekulare Subklassifikation als mögliche Folgefrage erwähnen, ohne sie in diesem Fall zu erzwingen":"If KIT/PDGFRA wild type, mention further molecular subclassification as a possible follow-up without forcing it in this case","Optimale Lösung: KIT/PDGFRA gezielt bestimmen. Der Nachweis von PDGFRA p.D842V ist der Twist, der die TKI-Auswahl gegenüber einem pauschalen Imatinib-Ansatz verändert.":"Optimal solution: Perform focused KIT/PDGFRA testing. Detection of PDGFRA p.D842V is the twist that changes TKI selection compared with a blanket imatinib approach.","KIT":"KIT","PDGFRA":"PDGFRA","GIST":"GIST","Mini":"Mini","GIST ist nicht gleich Imatinib: PDGFRA D842V kippt den TKI-Reflex":"GIST is not synonymous with imatinib: PDGFRA D842V overturns the TKI reflex","Molekularpathologie / Sarkompathologie / MTB":"Molecular pathology / Sarcoma pathology / MTB","GIST-Diagnosemarker und prädiktiven KIT/PDGFRA-Genotyp klar trennen.":"Clearly separate GIST diagnostic markers from the predictive KIT/PDGFRA genotype.","Vor systemischer TKI-Therapie die für Sensitivität/Resistenz relevante Mutationsklasse bestimmen.":"Before systemic TKI therapy, determine the mutation class relevant to sensitivity/resistance.","PDGFRA D842V als klinisch entscheidenden Sonderfall erkennen.":"Recognize PDGFRA D842V as a clinically decisive special case.","Für eine fokussierte klinische Frage eine gezielte, ressourcenschonende Methode wählen.":"Choose a focused, resource-efficient method for a focused clinical question.","Im Sarkomboard ist der Fall scheinbar in zehn Sekunden erledigt: metastasierter GIST, DOG1 positiv, also Imatinib. Die Pathologin stoppt die Diskussion mit einer einfachen Frage: 'Welcher KIT- oder PDGFRA-Genotyp liegt eigentlich vor?' Plötzlich ist klar, dass der diagnostische Name noch keine prädiktive Antwort ist.":"In the sarcoma board, the case seems settled in ten seconds: metastatic GIST, DOG1 positive, so imatinib. The pathologist stops the discussion with a simple question: 'What KIT or PDGFRA genotype is actually present?' Suddenly it becomes clear that the diagnostic label is not yet a predictive answer.","64-jährige Patientin mit vor drei Jahren reseziertem gastralem GIST und jetzt multiplen Lebermetastasen. DOG1 stark positiv, CD117 fokal. Keine bisherige TKI-Therapie. Vor Therapiebeginn soll der KIT/PDGFRA-Status geklärt werden.":"64-year-old woman with gastric GIST resected three years ago and now multiple liver metastases. DOG1 strongly positive, CD117 focal. No prior TKI therapy. KIT/PDGFRA status is to be clarified before treatment starts.","Diagnose":"Diagnosis","Morphologie und DOG1/CD117 sichern den GIST-Kontext.":"Morphology and DOG1/CD117 establish the GIST context.","IHC beantwortet 'Was ist der Tumor?', nicht automatisch 'Welcher TKI wirkt?'.":"IHC answers 'What is the tumor?', not automatically 'Which TKI works?'.","Therapiefrage":"Treatment question","Die Onkologie möchte mit einer TKI-Therapie beginnen.":"Oncology wants to start TKI therapy.","Der prädiktive Genotyp gehört vor die Wirkstoffwahl.":"The predictive genotype should precede drug selection.","Lebermetastase, 75 % Tumor, DNA-QC sehr gut; nur sechs Schnitte nötig verfügbar.":"Liver metastasis, 75% tumor, very good DNA QC; only six sections required/available.","Eine fokussierte KIT/PDGFRA-Analyse ist effizient.":"A focused KIT/PDGFRA analysis is efficient.","Epithelioider mesenchymaler Tumor, vereinbar mit GIST.":"Epithelioid mesenchymal tumor, compatible with GIST.","DOG1 stark positiv; CD117 fokal/heterogen positiv.":"DOG1 strongly positive; CD117 focal/heterogeneous positive.","Systemtherapie":"Systemic therapy","Noch nicht begonnen.":"Not yet started.","Kleine, aber sehr tumorreiche Metastasenbiopsie.":"Small but highly tumor-rich metastatic biopsy.","Die klinische Kernfrage ist fokussiert; ein extrem breites Pan-Tumor-Panel ist nicht zwingend nötig.":"The core clinical question is focused; an extremely broad pan-tumor panel is not mandatory.","Therapie sollte nicht allein aufgrund der IHC gestartet werden, wenn der Genotyp zeitnah verfügbar ist.":"Treatment should not be started solely on the basis of IHC when the genotype can be available promptly.","Welcher Befund entscheidet in diesem Fall am direktesten über die TKI-Auswahl?":"Which finding most directly determines TKI selection in this case?","KIT/PDGFRA-Mutationsstatus":"KIT/PDGFRA mutation status","Stärke der CD117-IHC allein":"Strength of CD117 IHC alone","Ki-67 allein":"Ki-67 alone","Der KIT/PDGFRA-Genotyp ist für die prädiktive Einordnung zentral.":"KIT/PDGFRA genotype is central to predictive classification.","Was bedeutet DOG1+/CD117+ für die TKI-Wahl?":"What does DOG1+/CD117+ mean for TKI selection?","Es stützt die GIST-Diagnose, ersetzt aber die Genotypisierung nicht.":"It supports the GIST diagnosis but does not replace genotyping.","Es beweist Imatinib-Sensitivität.":"It proves imatinib sensitivity.","Es schließt PDGFRA-Mutationen aus.":"It excludes PDGFRA mutations.","Es macht molekulare Diagnostik grundsätzlich überflüssig.":"It makes molecular testing fundamentally unnecessary.","Diagnostische IHC und prädiktive Genotypisierung beantworten verschiedene Fragen.":"Diagnostic IHC and predictive genotyping answer different questions.","Wählen Sie die minimale diagnostische Strategie, mit der die geplante TKI-Therapie genotypspezifisch abgesichert werden kann.":"Choose the minimal diagnostic strategy that can support the planned TKI therapy in a genotype-specific manner.","GIST-Diagnose als gesichert akzeptieren.":"Accept the GIST diagnosis as established.","KIT/PDGFRA-Mutationsanalyse durchführen.":"Perform KIT/PDGFRA mutation analysis.","Mutation auf Exon/Variantebene berichten.":"Report the mutation at exon/variant level.","Therapieempfehlung an die konkrete Sensitivitäts-/Resistenzkonstellation koppeln.":"Link treatment recommendation to the specific sensitivity/resistance constellation.","Bei KIT/PDGFRA-Wildtyp weitere Subklassifikation nur als Folgefrage erwägen.":"If KIT/PDGFRA wild type, consider further subclassification only as a follow-up question.","Breiteres validiertes NGS-Panel, wenn es KIT/PDGFRA vollständig abdeckt und ohne relevante Mehrbelastung verfügbar ist.":"Broader validated NGS panel if it fully covers KIT/PDGFRA and is available without relevant additional burden.","CD117 positiv = Imatinib":"CD117 positive = imatinib","Diagnostische Proteinexpression wird fälschlich als prädiktiver Genotyp interpretiert.":"Diagnostic protein expression is incorrectly interpreted as a predictive genotype.","Pan-Panel ohne klare Zusatzfrage":"Pan-panel without clear additional question","Kann funktionieren, ist bei der fokussierten Erstfrage aber unnötig breit.":"It may work, but is unnecessarily broad for the focused initial question.","Therapie vor Genotyp":"Treatment before genotype","Eine klinisch relevante Resistenz-/Sensitivitätskonstellation kann übersehen werden.":"A clinically relevant resistance/sensitivity constellation may be missed.","PDGFRA D842V statt 'klassischem KIT-GIST'":"PDGFRA D842V instead of 'classic KIT GIST'","Die gezielte Sequenzierung zeigt keine KIT-Mutation, sondern PDGFRA Exon 18 p.D842V. Der zunächst reflexhaft diskutierte Imatinib-Start wäre für genau diese Konstellation ungeeignet; die TKI-Strategie muss genotypspezifisch geändert werden.":"Focused sequencing shows no KIT mutation but PDGFRA exon 18 p.D842V. The reflexively discussed imatinib start would be unsuitable for precisely this constellation; the TKI strategy must be changed according to genotype.","Der Fall zeigt maximal kompakt, warum Diagnosesicherung und prädiktive Molekularpathologie zwei getrennte Schritte sind.":"The case demonstrates very compactly why diagnostic confirmation and predictive molecular pathology are two separate steps.","Genotyp vor TKI":"Genotype before TKI","PDGFRA Exon 18 p.D842V, KIT wildtyp.":"PDGFRA exon 18 p.D842V, KIT wild type.","Kernentscheidung getroffen; TKI-Auswahl kann genotypspezifisch erfolgen.":"Core decision made; TKI selection can proceed according to genotype.","IHC reicht":"IHC is sufficient","GIST wird korrekt diagnostiziert, aber ohne KIT/PDGFRA-Genotyp pauschal als Imatinib-sensitiv behandelt.":"GIST is diagnosed correctly but treated generically as imatinib-sensitive without KIT/PDGFRA genotype.","Diagnose korrekt, prädiktive Ebene verfehlt.":"Diagnosis correct, predictive level missed.","Breites Pan-Panel":"Broad pan-panel","PDGFRA D842V wird ebenfalls gefunden, jedoch mit mehr Ressourcen als für die Kernfrage nötig.":"PDGFRA D842V is also detected, but with more resources than needed for the core question.","Fachlich brauchbar, aber weniger fokussiert.":"Clinically usable, but less focused.","PDGFRA D842V":"PDGFRA D842V","Genotypspezifische TKI-Strategie im Sarkomboard diskutieren.":"Discuss genotype-specific TKI strategy in the sarcoma board.","Pauschaler Imatinib-Reflex wird vermieden.":"A blanket imatinib reflex is avoided.","KIT/PDGFRA wildtyp":"KIT/PDGFRA wild type","Weitere molekulare Subklassifikation erwägen.":"Consider further molecular subclassification.","Der Fall geht in eine zweite diagnostische Ebene über.":"The case moves to a second diagnostic level.","DOG1/CD117 sichern den diagnostischen Kontext, nicht die TKI-Sensitivität.":"DOG1/CD117 establish the diagnostic context, not TKI sensitivity.","KIT/PDGFRA-Genotypisierung ist eine prädiktive Entscheidungsebene.":"KIT/PDGFRA genotyping is a predictive decision level.","PDGFRA D842V ist der klassische Fall, in dem ein pauschaler Imatinib-Reflex scheitert.":"PDGFRA D842V is the classic case in which a blanket imatinib reflex fails.","Fokussierte Diagnostik kann besser sein als maximale Panelbreite, wenn die klinische Frage klar ist.":"Focused diagnostics can be better than maximal panel breadth when the clinical question is clear.","Gezielte KIT/PDGFRA-Analyse vor TKI-Start. Ergebnis: PDGFRA Exon 18 p.D842V, KIT wildtyp. Damit ist der reflexhafte Imatinib-Ansatz nicht passend; die Therapie muss genotypspezifisch geplant werden.":"Focused KIT/PDGFRA analysis before starting TKI. Result: PDGFRA exon 18 p.D842V, KIT wild type. The reflexive imatinib approach is therefore inappropriate; treatment must be planned according to genotype.","Diagnose vs. Prädiktion getrennt":"Diagnosis and prediction separated","KIT/PDGFRA gewählt":"KIT/PDGFRA selected","D842V korrekt gewichtet":"D842V weighted correctly","Keine unnötige Panelinflation":"No unnecessary panel inflation","Welche weiteren GIST-Genotypen beeinflussen Dosis oder TKI-Sensitivität?":"Which other GIST genotypes influence dose or TKI sensitivity?","Wann wäre ein breiteres Panel sinnvoll?":"When would a broader panel be useful?","Wie sollte ein Befund formuliert sein, damit Diagnose und Prädiktion klar getrennt bleiben?":"How should a report be phrased so that diagnosis and prediction remain clearly separated?","GIST-Diagnose ist nicht gleich TKI-Sensitivität":"GIST diagnosis is not the same as TKI sensitivity","IHC-Diagnose → Genotyp → TKI-Wechsel":"IHC diagnosis → genotype → TKI change","Cholangiozelluläres Karzinom mit FGFR2/IDH-Frage → Paneldiagnostik und Studienoptionen":"Cholangiocarcinoma with FGFR2/IDH question → Panel testing and clinical-trial options","Cholangiozelluläres Karzinom mit F…":"Cholangiocarcinoma with FGFR2/IDH q…","Hepatobiliäre Onkologie / MTB":"Hepatobiliary oncology / MTB","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie.":"59-year-old woman with unresectable intrahepatic cholangiocarcinoma and progression after first-line therapy.","Welche molekulare Profilierung ist jetzt sinnvoll, insbesondere für FGFR2- und IDH1/2-Alterationen sowie weitere potenziell targetierbare Befunde?":"Which molecular profiling is appropriate now, particularly for FGFR2 and IDH1/2 alterations and other potentially targetable findings?","Der molekulare Befund soll vor Festlegung der nächsten Therapielinie vorliegen.":"The molecular report should be available before the next treatment line is selected.","Tumorlokalisation":"Tumor location","Intrahepatische dominante Raumforderung mit multiplen Satelliten und pulmonalen Metastasen.":"Dominant intrahepatic mass with multiple satellites and pulmonary metastases.","Systemische Erstlinientherapie abgeschlossen; aktuell radiologischer Progress.":"Systemic first-line therapy completed; current radiologic progression.","Ein kleines DNA-only-Panel aus der Erstdiagnose meldete keinen therapeutisch relevanten SNV/Indel-Befund; Fusionen waren im Bericht nicht valide abgedeckt.":"A small DNA-only panel from the initial diagnosis reported no therapeutically relevant SNV/indel finding; fusions were not validly covered in the report.","'Panel negativ' wird im Tumorboard bereits mit 'keine Target-Option' gleichgesetzt.":"In the tumor board, 'panel negative' is already being equated with 'no target option'.","Adenokarzinom mit tubulären und desmoplastischen Anteilen, vereinbar mit intrahepatischem Cholangiokarzinom.":"Adenocarcinoma with tubular and desmoplastic components, consistent with intrahepatic cholangiocarcinoma.","CK7 positiv; HepPar1/Arginase-1 negativ; klinisch-radiologische Integration stützt iCCA.":"CK7 positive; HepPar1/Arginase-1 negative; clinical-radiologic integration supports iCCA.","Breite DNA-basierte Alterationen und insbesondere strukturelle FGFR2-Ereignisse müssen methodisch adäquat erfasst werden.":"Broad DNA-based alterations and, in particular, structural FGFR2 events must be captured with methodologically appropriate assays.","Nicht relevant":"Not relevant","Neuroonkologische IDH1-R132H-IHC, G-CIMP oder ein ZNS-Methylierungsclassifier beantworten diese Fragestellung nicht.":"Neuro-oncology IDH1-R132H IHC, G-CIMP or a CNS methylation classifier do not answer this question.","FFPE-Leberbiopsie, Block C5.":"FFPE liver biopsy, block C5.","ca. 50 %, ausreichende vitale Tumorareale.":"approx. 50%, sufficient viable tumor areas.","DNA/RNA-QC":"DNA/RNA QC","DNA gut; RNA nach QC ausreichend.":"DNA good; RNA sufficient after QC.","Erneutes DNA-only-Testen ohne valide Fusionserfassung kann denselben blinden Fleck reproduzieren.":"Repeating DNA-only testing without valid fusion coverage may reproduce the same blind spot.","CCA-Molekularprofil / IDH1/2-Kontext":"CCA molecular profile / IDH1/2 context","FGFR2-Fusions-/Rearrangementdiagnostik":"FGFR2 fusion/rearrangement testing","CCA-DNA-Profil":"CCA DNA profile","Keine pathogene IDH1/2-Mutation; kein BRAF-V600- oder ERBB2-Hotspot-Befund. Das DNA-Profil allein erklärt keine Target-Option.":"No pathogenic IDH1/2 mutation; no BRAF V600 or ERBB2 hotspot finding. The DNA profile alone does not reveal a target option.","FGFR2-Fusionsdiagnostik":"FGFR2 fusion testing","FGFR2::BICC1-Fusion nachweisbar. Der Befund ist bei intrahepatischem Cholangiokarzinom therapeutisch relevant und gehört in die nächste Linienplanung.":"FGFR2::BICC1 fusion detected. The finding is therapeutically relevant in intrahepatic cholangiocarcinoma and belongs in next-line planning.","DNA und RNA aus dem markierten Tumorareal sind auswertbar; ausreichende Restreserve vorhanden.":"DNA and RNA from the marked tumor area are evaluable; sufficient residual material remains.","Intrahepatisches Cholangiokarzinom mit FGFR2::BICC1-Fusion und ohne IDH1/2-Mutation. Die zuvor DNA-only negative Profilierung war kein ausreichender Ausschluss einer strukturellen Targetalteration.":"Intrahepatic cholangiocarcinoma with FGFR2::BICC1 fusion and no IDH1/2 mutation. The previous DNA-only negative profiling was not sufficient to exclude a structural target alteration.","Teilbefund: Die CCA-Profilierung ist ohne belastbare FGFR2-Fusions-/Rearrangementdiagnostik unvollständig. Neuroonkologische IDH-/Methylierungsverfahren sind für diese Frage nicht geeignet.":"Partial finding: CCA profiling is incomplete without robust FGFR2 fusion/rearrangement testing. Neuro-oncology IDH/methylation methods are not suitable for this question.","Intrahepatisches Cholangiokarzinom als relevanten molekularen Kontext benennen":"State intrahepatic cholangiocarcinoma as the relevant molecular context","FGFR2-Fusion/Rearrangement als eigenständige strukturelle Alterationsklasse erfassen":"Capture FGFR2 fusion/rearrangement as a distinct structural alteration class","IDH1/2-Sequenzierung im CCA-Kontext von neuroonkologischer IDH-IHC/Methylomdiagnostik trennen":"Separate IDH1/2 sequencing in the CCA context from neuro-oncology IDH IHC/methylome testing","DNA-only Negativbefund nicht als vollständigen Fusionsausschluss formulieren":"Do not phrase a DNA-only negative result as complete exclusion of fusions","Optimale Lösung: CCA-spezifisches Molekularprofil plus valide FGFR2-Fusionserfassung. Der ZNS-Methylierungs-/G-CIMP-Copyover wird vollständig entfernt.":"Optimal solution: CCA-specific molecular profile plus valid FGFR2 fusion detection. The CNS methylation/G-CIMP copyover is removed completely.","IDH":"IDH","FGFR":"FGFR","Intrahepatisches Cholangiokarzinom: Das negative DNA-Panel übersieht die strukturelle Targetalteration":"Intrahepatic cholangiocarcinoma: The negative DNA panel misses the structural target alteration","Molekularpathologie / hepatobiliäre Onkologie / MTB":"Molecular pathology / hepatobiliary oncology / MTB","Das intrahepatische Cholangiokarzinom als Entität mit relevanter breiter molekularer Profilierung einordnen.":"Classify intrahepatic cholangiocarcinoma as an entity requiring relevant broad molecular profiling.","FGFR2-Fusionen/Rearrangements methodisch von SNV/Indel-Analysen unterscheiden.":"Distinguish FGFR2 fusions/rearrangements methodologically from SNV/indel analyses.","IDH1/2 im CCA-Kontext von neuroonkologischer IDH-IHC/G-CIMP/Methylomdiagnostik trennen.":"Separate IDH1/2 in the CCA context from neuro-oncology IDH IHC/G-CIMP/methylome diagnostics.","Einen negativen DNA-only-Befund nicht als vollständigen Ausschluss struktureller Targetalterationen interpretieren.":"Do not interpret a negative DNA-only result as complete exclusion of structural target alterations.","Im hepatobiliären MTB liegt ein alter Molekularbefund mit der Überschrift 'kein targetierbarer Befund'. Die 59-jährige Patientin mit intrahepatischem Cholangiokarzinom ist nach Erstlinientherapie progredient, und die nächste Linie muss geplant werden. Beim Blick in den Methodenteil zeigt sich: Das damalige kleine Panel war DNA-basiert und auf SNV/Indels fokussiert. FGFR2-Rearrangements wurden nicht valide breit erfasst. Gleichzeitig findet sich in der Falllogik ein völlig fachfremder Verweis auf G-CIMP und einen ZNS-Methylierungsclassifier – genau diese Altlast soll der Fall jetzt bewusst bereinigen.":"At the hepatobiliary MTB, an old molecular report is headed 'no targetable finding'. The 59-year-old woman with intrahepatic cholangiocarcinoma has progressed after first-line therapy and the next line must be planned. A look at the methods section shows that the previous small panel was DNA-based and focused on SNVs/indels. FGFR2 rearrangements were not validly covered broadly. At the same time, the case logic contains a completely irrelevant reference to G-CIMP and a CNS methylation classifier – exactly the legacy error this case is now meant to correct deliberately.","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie. DNA-only-Vorbefund ohne relevante SNV/Indel-Targetalteration. Für die nächste Linie sollen FGFR2-Fusionen/Rearrangements, IDH1/2 und weitere relevante molekulare Alterationen methodisch vollständig bewertet werden.":"59-year-old woman with unresectable intrahepatic cholangiocarcinoma and progression after first-line therapy. Prior DNA-only result without relevant SNV/indel target alteration. For the next line, FGFR2 fusions/rearrangements, IDH1/2 and other relevant molecular alterations must be assessed completely with appropriate methods.","Entität":"Entity","Intrahepatisches Cholangiokarzinom mit metastasierter Erkrankung.":"Intrahepatic cholangiocarcinoma with metastatic disease.","Tumorentität und Erkrankungsphase bestimmen die sinnvolle molekulare Breite.":"Tumor entity and disease phase determine the appropriate molecular breadth.","Kleines DNA-only-Panel ohne relevanten SNV/Indel-Treffer; keine belastbare breite Fusionserfassung.":"Small DNA-only panel without relevant SNV/indel hit; no robust broad fusion coverage.","Ein negatives SNV/Indel-Profil schließt strukturelle Alterationen nicht aus.":"A negative SNV/indel profile does not exclude structural alterations.","Leberbiopsie mit 50 % Tumor; DNA und RNA ausreichend.":"Liver biopsy with 50% tumor; DNA and RNA sufficient.","Es gibt keinen technischen Grund, die Fusionsfrage offen zu lassen.":"There is no technical reason to leave the fusion question unresolved.","Copyover-Falle":"Copyover trap","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier gehören in neuroonkologische Kontexte und beantworten die CCA-Targetfrage nicht.":"IDH1-R132H IHC, G-CIMP and CNS methylation classifiers belong to neuro-oncology contexts and do not answer the CCA target question.","Gleiche Genbezeichnung bedeutet nicht gleiche diagnostische Methode oder biologische Fragestellung.":"The same gene name does not imply the same diagnostic method or biological question.","Adenokarzinom mit desmoplastischem Stroma; klinisch-radiologisch und immunhistologisch mit intrahepatischem CCA vereinbar.":"Adenocarcinoma with desmoplastic stroma; clinically, radiologically and immunohistologically consistent with intrahepatic CCA.","DNA-only Vorprofil":"Prior DNA-only profile","Kein relevanter IDH1/2-, BRAF-V600- oder ERBB2-Hotspot-Befund; Fusionserfassung unzureichend.":"No relevant IDH1/2, BRAF V600 or ERBB2 hotspot finding; fusion coverage inadequate.","ausreichend für gezielte Fusionsanalyse.":"sufficient for targeted fusion analysis.","Zehn ungefärbte Schnitte verfügbar.":"Ten unstained sections available.","DNA und RNA sind ausreichend; die Limitation liegt primär in der Wahl des Assays.":"DNA and RNA are sufficient; the limitation lies primarily in assay selection.","Neuroonkologische IDH-/Methylierungsverfahren sind explizit entitätsfremd.":"Neuro-oncology IDH/methylation methods are explicitly inappropriate for this entity.","Das TAT-Ziel liegt vor der nächsten Therapieentscheidung.":"The TAT target is before the next treatment decision.","Welche molekulare Kernstrategie ist bei diesem progredienten intrahepatischen Cholangiokarzinom sinnvoll?":"Which core molecular strategy is appropriate for this progressive intrahepatic cholangiocarcinoma?","CCA-spezifisches Molekularprofil plus valide FGFR2-Fusions-/Rearrangementdiagnostik":"CCA-specific molecular profile plus valid FGFR2 fusion/rearrangement testing","IDH1-R132H-IHC plus ZNS-Methylierungsclassifier":"IDH1-R132H IHC plus CNS methylation classifier","Keine weitere Diagnostik, weil das alte DNA-Panel negativ war":"No further testing because the old DNA panel was negative","MGMT-Promotor-Methylierung":"MGMT promoter methylation","Die klinische Frage verlangt CCA-spezifische molekulare Profilierung mit adäquater Erfassung struktureller Alterationen.":"The clinical question requires CCA-specific molecular profiling with adequate capture of structural alterations.","Wie soll IDH in diesem Fall untersucht/eingeordnet werden?":"How should IDH be tested/interpreted in this case?","IDH1/2-Sequenzierung im CCA-Panel-/Targetkontext":"IDH1/2 sequencing in the CCA panel/target context","IDH1-R132H-IHC als primärer CCA-Screeningstandard":"IDH1-R132H IHC as the primary CCA screening standard","G-CIMP-Profil als Therapiebiomarker":"G-CIMP profile as treatment biomarker","ZNS-Methylierungsclassifier":"CNS methylation classifier","Die neuroonkologische R132H-IHC/G-CIMP-/Classifier-Logik darf nicht auf das Cholangiokarzinom übertragen werden.":"The neuro-oncology R132H IHC/G-CIMP/classifier logic must not be transferred to cholangiocarcinoma.","Das alte DNA-only-Panel ist negativ. Was folgt daraus für FGFR2?":"The old DNA-only panel is negative. What follows for FGFR2?","Eine Fusion/Rearrangement-Frage kann weiterhin offen sein, wenn der Assay diese Alterationsklasse nicht valide abdeckt.":"A fusion/rearrangement question may remain open if the assay does not validly cover this alteration class.","FGFR2 ist sicher ausgeschlossen.":"FGFR2 is definitively excluded.","Dann kann nur noch IDH1 relevant sein.":"Then only IDH1 can still be relevant.","Strukturelle Alterationen sind beim CCA klinisch nicht relevant.":"Structural alterations are not clinically relevant in CCA.","SNV/Indel-negative DNA-Daten sind kein universeller Fusionsausschluss.":"SNV/indel-negative DNA data are not a universal exclusion of fusions.","Planen Sie eine CCA-spezifische molekulare Abklärung für die nächste Therapielinie und entfernen Sie die neuroonkologischen Copyover-Methoden vollständig aus der Entscheidungslogik.":"Plan a CCA-specific molecular workup for the next treatment line and remove the neuro-oncology copyover methods completely from the decision logic.","Intrahepatischen CCA-Kontext bestätigen.":"Confirm the intrahepatic CCA context.","CCA-spezifisches DNA-Profil für IDH1/2 und weitere relevante Alterationen nutzen.":"Use a CCA-specific DNA profile for IDH1/2 and other relevant alterations.","FGFR2-Fusion/Rearrangement mit einer dafür validierten Methode explizit erfassen.":"Explicitly assess FGFR2 fusion/rearrangement with a validated method.","DNA-only Negativbefund methodisch begrenzen.":"Limit the interpretation of the DNA-only negative result methodologically.","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier nicht verwenden.":"Do not use IDH1-R132H IHC, G-CIMP or CNS methylation classifier.","Validiertes kombiniertes DNA/RNA-Pan-Panel mit sicherer FGFR2-Fusionserfassung.":"Validated combined DNA/RNA pan-panel with reliable FGFR2 fusion coverage.","Gezielte FGFR2-Fusionsdiagnostik plus separates IDH1/2-Assay, wenn ein integriertes CCA-Panel nicht verfügbar ist.":"Targeted FGFR2 fusion testing plus a separate IDH1/2 assay if an integrated CCA panel is unavailable.","Fachfremder Copyover; beantwortet weder FGFR2- noch IDH1/2-Targetfrage beim CCA.":"Irrelevant copyover; answers neither the FGFR2 nor IDH1/2 target question in CCA.","IDH1-R132H-IHC als CCA-Standard":"IDH1-R132H IHC as CCA standard","Neuroonkologische Screeninglogik wird auf eine andere Entität übertragen.":"Neuro-oncology screening logic is transferred to another entity.","DNA-negativ = keine Targetoption":"DNA-negative = no target option","Strukturelle Alterationen können methodisch offen bleiben.":"Structural alterations may remain methodologically unresolved.","FGFR2::BICC1 trotz 'kein targetierbarer Befund'":"FGFR2::BICC1 despite 'no targetable finding'","Die CCA-spezifische DNA-Analyse bleibt für IDH1/2, BRAF und ERBB2 ohne relevanten Treffer. Die gezielte Fusionsdiagnostik detektiert jedoch eine FGFR2::BICC1-Fusion. Der alte Satz 'kein targetierbarer Befund' war damit nicht biologisch falsch, sondern methodisch zu weit formuliert.":"The CCA-specific DNA analysis remains negative for relevant IDH1/2, BRAF and ERBB2 findings. However, targeted fusion testing detects an FGFR2::BICC1 fusion. The old phrase 'no targetable finding' was therefore not biologically wrong, but methodologically overbroad.","Die zentrale Lektion ist zweifach: strukturelle Alterationen brauchen passende Assays, und identische Genbegriffe dürfen nicht entitätsfremde Diagnostikpfade triggern.":"The central lesson is twofold: structural alterations require appropriate assays, and identical gene names must not trigger entity-inappropriate diagnostic pathways.","CCA-Profil + Fusion":"CCA profile + fusion","FGFR2::BICC1-Fusion nachweisbar; IDH1/2 wildtyp; kein BRAF-V600-/ERBB2-Hotspot-Befund.":"FGFR2::BICC1 fusion detected; IDH1/2 wild type; no BRAF V600/ERBB2 hotspot finding.","Vollständige, entitätsspezifische Profilierung mit klinisch relevanter Targetalteration.":"Complete, entity-specific profiling with a clinically relevant target alteration.","DNA-only wiederholt":"DNA-only repeated","Kein relevanter SNV/Indel-Treffer; FGFR2-Fusionsstatus bleibt offen.":"No relevant SNV/indel hit; FGFR2 fusion status remains unresolved.","Der alte methodische blinde Fleck wurde reproduziert.":"The old methodological blind spot was reproduced.","Neuroonkologischer IDH-Pfad":"Neuro-oncology IDH pathway","IDH1-R132H-IHC/Methylierungsclassifier werden angefordert; die eigentliche CCA-Targetfrage bleibt ungelöst.":"IDH1-R132H IHC/methylation classifier are ordered; the actual CCA target question remains unresolved.","Klarer Cross-Template-Fehler.":"Clear cross-template error.","FGFR2-Fusion positiv":"FGFR2 fusion positive","Target-Relevanz und passende Therapielinie im hepatobiliären MTB diskutieren.":"Discuss target relevance and the appropriate treatment line in the hepatobiliary MTB.","Der Befund verändert die nächste Linienplanung.":"The finding changes next-line planning.","FGFR2 negativ, DNA-Profil ohne Target":"FGFR2 negative, DNA profile without target","Weitere im validierten Panel erfasste Alterationsklassen und Studienoptionen prüfen.":"Review other alteration classes covered by the validated panel and clinical-trial options.","Negativbefund bleibt methodisch transparent.":"The negative result remains methodologically transparent.","Nur CNS-IDH/Methylom gewählt":"Only CNS IDH/methylome selected","Anforderung korrigieren und CCA-spezifische Diagnostik durchführen.":"Correct the request and perform CCA-specific diagnostics.","Material/TAT-Verlust, aber fachlich rettbarer Fall.":"Material/TAT loss, but a clinically salvageable case.","Beim iCCA ist molekulare Profilierung Teil moderner Therapieplanung.":"In iCCA, molecular profiling is part of modern treatment planning.","FGFR2-Fusionen sind strukturelle Alterationen und benötigen passende Assayabdeckung.":"FGFR2 fusions are structural alterations and require appropriate assay coverage.","IDH1/2 im Cholangiokarzinom ist nicht dasselbe diagnostische Problem wie IDH/G-CIMP im Gliom.":"IDH1/2 in cholangiocarcinoma is not the same diagnostic problem as IDH/G-CIMP in glioma.","Cross-Template-Copyover ist ein reales Qualitätsrisiko in standardisierten Fallbibliotheken und Labor-Workflows.":"Cross-template copyover is a real quality risk in standardized case libraries and laboratory workflows.","CCA-spezifisches Molekularprofil plus explizite FGFR2-Fusions-/Rearrangementdiagnostik. Ergebnis: FGFR2::BICC1-Fusion, IDH1/2 wildtyp. Die bisherigen neuroonkologischen IDH1-R132H-/G-CIMP-/Methylierungsclassifier-Elemente sind fachfremd und werden vollständig entfernt.":"CCA-specific molecular profile plus explicit FGFR2 fusion/rearrangement testing. Result: FGFR2::BICC1 fusion, IDH1/2 wild type. The previous neuro-oncology IDH1-R132H/G-CIMP/methylation-classifier elements are inappropriate and are removed completely.","iCCA-Kontext erkannt":"iCCA context recognized","FGFR2 strukturell korrekt getestet":"FGFR2 structurally tested correctly","IDH1/2 entitätsspezifisch eingeordnet":"IDH1/2 interpreted in an entity-specific way","CNS-Copyover aktiv verworfen":"CNS copyover actively rejected","Wann reicht ein DNA-Panel für Fusionen, wann nicht?":"When is a DNA panel sufficient for fusions, and when is it not?","Welche weiteren Alterationsklassen sollten CCA-Panels abdecken?":"Which other alteration classes should CCA panels cover?","Wie können Template-Bibliotheken gegen Cross-Entity-Copyover QA-gesichert werden?":"How can template libraries be QA-protected against cross-entity copyover?","FGFR2::BICC1 nach DNA-only Negativbefund":"FGFR2::BICC1 after a DNA-only negative result","Strukturelle Targets brauchen passende Methoden":"Structural targets require appropriate methods","DNA-negativ → Assaycheck → CCA-Profil + Fusion → FGFR2":"DNA negative → assay check → CCA profile + fusion → FGFR2","Rechte Kolonkarzinom-Metastase mit BRAF V600E → Prognose, MSI-Kontext, Therapieoption":"Right-sided colon cancer metastasis with BRAF V600E → Prognosis, MSI context, treatment option","Rechte Kolonkarzinom-Metastase mit…":"Right-sided colon cancer metastasis with…","Viszeralonkologie / Molekulares Tumorboard":"Visceral oncology / Molecular tumor board","72-jährige Patientin mit rechtsseitigem Kolonkarzinom und synchronen Leber- und Peritonealmetastasen.":"72-year-old woman with right-sided colon cancer and synchronous liver and peritoneal metastases.","Im Tumorprofil wurde BRAF p.V600E nachgewiesen. Welche prognostische und therapeutische Bedeutung hat der Befund im CRC – und was muss zusätzlich über MMR/MSI bekannt sein?":"BRAF p.V600E was detected in the tumor profile. What prognostic and therapeutic significance does it have in CRC – and what else must be known about MMR/MSI?","Die Erstlinienstrategie soll im MTB innerhalb weniger Tage festgelegt werden.":"The first-line strategy is to be defined in the MTB within a few days.","Coecum/Colon ascendens, rechtsseitig.":"Cecum/ascending colon, right-sided.","Metastasiert mit Leber- und Peritonealbefall; ECOG 1.":"Metastatic with liver and peritoneal involvement; ECOG 1.","BRAF V600E wird reflexartig wie beim Melanom interpretiert oder mit MSI-H gleichgesetzt. Beides ist im CRC falsch bzw. unvollständig.":"BRAF V600E is reflexively interpreted as in melanoma or equated with MSI-H. Both are wrong or incomplete in CRC.","Mäßig bis gering differenziertes kolorektales Adenokarzinom mit fokal muzinöser Morphologie.":"Moderately to poorly differentiated colorectal adenocarcinoma with focal mucinous morphology.","Lineage":"Lineage","CDX2/SATB2 positiv; Morphologie und Klinik vereinbar mit kolorektalem Primarius.":"CDX2/SATB2 positive; morphology and clinical context consistent with colorectal primary.","Molekularer Vorbefund":"Prior molecular result","BRAF p.V600E in einer schnellen Einzeltestung nachgewiesen.":"BRAF p.V600E detected in a rapid single-gene test.","Ist der Tumor dMMR/MSI-H oder pMMR/MSS, und wie muss die BRAF-Alteration CRC-spezifisch therapeutisch eingeordnet werden?":"Is the tumor dMMR/MSI-H or pMMR/MSS, and how should the BRAF alteration be interpreted therapeutically in a CRC-specific way?","FFPE-Resektat, Block C6 mit vitalem invasivem Tumor.":"FFPE resection specimen, block C6 with viable invasive tumor.","ca. 55 %, gut geeignet für DNA-basierte Analysen.":"approx. 55%, well suited for DNA-based analyses.","DNA-Qualität gut; MMR-IHC technisch gut beurteilbar.":"DNA quality good; MMR IHC technically well evaluable.","Melanom-spezifische BRAF-Methoden oder Therapiealgorithmen beantworten die CRC-Frage nicht.":"Melanoma-specific BRAF methods or treatment algorithms do not answer the CRC question.","BRAF-V600E im CRC-Kontext":"BRAF V600E in the CRC context","MMR-IHC":"MMR IHC","MSI-Testung":"MSI testing","BRAF V600E":"BRAF V600E","BRAF p.V600E nachweisbar. Der Befund ist im metastasierten CRC prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden – nicht nach dem Melanom-Algorithmus.":"BRAF p.V600E detected. The finding is prognostically and therapeutically relevant in metastatic CRC, but must be interpreted according to CRC-specific evidence – not a melanoma algorithm.","Erweiterter RAS-Status":"Extended RAS status","KRAS/NRAS Wildtyp. Der BRAF-V600E-Befund bleibt der dominante MAPK-Treiberkontext.":"KRAS/NRAS wild type. The BRAF V600E finding remains the dominant MAPK driver context.","Intakte nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Intact nuclear expression of MLH1, PMS2, MSH2 and MSH6: pMMR.","MSI":"MSI","MSS / kein MSI-H. BRAF V600E ist damit gerade nicht automatisch mit MSI-H gleichzusetzen.":"MSS / no MSI-H. BRAF V600E is therefore explicitly not synonymous with MSI-H.","MLH1-Methylierung":"MLH1 methylation","Bei erhaltener MLH1/PMS2-Expression besteht in diesem Fall keine primäre Reflexindikation; die Zusatzanalyse liefert keinen entscheidungsrelevanten Mehrwert.":"With preserved MLH1/PMS2 expression there is no primary reflex indication in this case; the additional analysis provides no decision-relevant benefit.","Tumoranteil und DNA-Qualität ausreichend; MMR-IHC auswertbar.":"Tumor fraction and DNA quality sufficient; MMR IHC evaluable.","BRAF p.V600E liegt in einem rechtsseitigen, pMMR/MSS metastasierten CRC vor. Der Befund ist prognostisch ungünstig und eröffnet einen CRC-spezifischen BRAF-gerichteten Therapiekontext mit EGFR-Blockade nach aktueller Therapielinie/Leitlinie. Eine Melanom-artige BRAF/MEK-Übertragung ist nicht angemessen; BRAF V600E bedeutet außerdem nicht automatisch MSI-H.":"BRAF p.V600E is present in a right-sided, pMMR/MSS metastatic CRC. The finding is prognostically adverse and opens a CRC-specific BRAF-targeted treatment context with EGFR blockade according to the current treatment line/guideline. A melanoma-like transfer of BRAF/MEK is inappropriate; BRAF V600E also does not automatically mean MSI-H.","Teilbefund: BRAF V600E ist bekannt, aber ohne MMR/MSI-Kontext bleibt die molekulare Einordnung unvollständig. Therapie- und Prognoseaussagen dürfen nicht aus einem Melanom-Template übernommen werden.":"Partial finding: BRAF V600E is known, but without MMR/MSI context the molecular classification remains incomplete. Treatment and prognostic statements must not be copied from a melanoma template.","BRAF V600E als CRC-spezifischen prognostisch/therapeutisch relevanten Befund benennen":"State BRAF V600E as a CRC-specific prognostically and therapeutically relevant finding","BRAF V600E nicht mit MSI-H gleichsetzen; pMMR/MSS separat kommunizieren":"Do not equate BRAF V600E with MSI-H; communicate pMMR/MSS separately","BRAF-gerichtete Strategie im CRC mit EGFR-Blockade und aktueller Therapielinie verknüpfen, nicht mit einem Melanom-Schema":"Link the BRAF-targeted CRC strategy to EGFR blockade and the current treatment line, not to a melanoma regimen","Entitätsspezifische Evidenz und aktuelle Leitlinien-/Zulassungssituation sprachlich sauber begrenzen":"Phrase entity-specific evidence and the current guideline/approval situation with appropriate limitations","Optimale Lösung: BRAF V600E, RAS-Kontext und MMR/MSI gemeinsam einordnen; der Tumor ist pMMR/MSS und benötigt eine CRC-spezifische BRAF-/EGFR-Therapielogik statt eines Melanom-Copyovers.":"Optimal solution: Interpret BRAF V600E, RAS context and MMR/MSI together; the tumor is pMMR/MSS and requires CRC-specific BRAF/EGFR treatment logic rather than melanoma copyover.","CRC":"CRC","mCRC":"mCRC","pMMR":"pMMR","MSS":"MSS","anti-EGFR":"anti-EGFR","Targeted Therapy":"Targeted therapy","BRAF V600E im rechten mCRC: CRC-Biologie statt Melanom-Copyover":"BRAF V600E in right-sided mCRC: CRC biology instead of melanoma copyover","Molekularpathologie / Viszeralonkologie / MTB":"Molecular pathology / Visceral oncology / MTB","BRAF V600E beim mCRC prognostisch und therapeutisch korrekt einordnen.":"Correctly interpret BRAF V600E prognostically and therapeutically in mCRC.","BRAF V600E nicht automatisch mit MSI-H gleichsetzen, sondern MMR/MSI separat prüfen.":"Do not automatically equate BRAF V600E with MSI-H; assess MMR/MSI separately.","Die CRC-spezifische BRAF-Therapielogik von Melanom-Algorithmen abgrenzen.":"Distinguish CRC-specific BRAF treatment logic from melanoma algorithms.","Rechtsseitigkeit, pMMR/MSS und BRAF-Kontext in einer integrierten MTB-Aussage zusammenführen.":"Integrate sidedness, pMMR/MSS and BRAF context into a single MTB statement.","Im MTB fällt sofort der rote Marker 'BRAF V600E' ins Auge. Jemand schlägt vor, den Fall wie ein BRAF-mutiertes Melanom zu behandeln; ein anderer sagt, rechtsseitig plus BRAF sei wahrscheinlich ohnehin MSI-high. Beides klingt auf den ersten Blick plausibel – und beides greift zu kurz.":"In the MTB, the red marker 'BRAF V600E' immediately catches the eye. Someone suggests treating the case like a BRAF-mutant melanoma; another says right-sided plus BRAF probably means MSI-high anyway. Both sound plausible at first glance – and both fall short.","72-jährige Patientin mit rechtsseitigem metastasiertem CRC. BRAF p.V600E wurde bereits nachgewiesen. Die Lernaufgabe besteht darin, die Mutation entitätsspezifisch zu interpretieren, MMR/MSI unabhängig zu klären und aus Prognose, Immuntherapie- und BRAF-Targetkontext eine belastbare MTB-Empfehlung zu formulieren.":"72-year-old woman with right-sided metastatic CRC. BRAF p.V600E is already known. The learning task is to interpret the mutation in an entity-specific way, clarify MMR/MSI independently and formulate a robust MTB recommendation from prognosis, immunotherapy and BRAF-target context.","Tumorbiologie":"Tumor biology","Rechtsseitiges metastasiertes CRC mit BRAF V600E.":"Right-sided metastatic CRC with BRAF V600E.","BRAF ist ein starker biologischer Kontextmarker, aber nicht die gesamte Therapieentscheidung.":"BRAF is a strong biological context marker but not the entire treatment decision.","Zu Beginn noch unbekannt.":"Unknown initially.","BRAF V600E und MSI-H sind assoziiert, aber nicht synonym.":"BRAF V600E and MSI-H are associated but not synonymous.","Therapiekontext":"Treatment context","Erstlinienentscheidung steht an.":"First-line decision pending.","BRAF-Targeting im CRC folgt einer anderen Logik als beim Melanom.":"BRAF targeting in CRC follows a different logic than in melanoma.","Schneller BRAF-Befund":"Rapid BRAF result","BRAF p.V600E positiv.":"BRAF p.V600E positive.","Rechtsseitiges kolorektales Adenokarzinom, metastasiert.":"Right-sided colorectal adenocarcinoma, metastatic.","Material ausreichend für MMR-IHC und MSI-Testung.":"Material sufficient for MMR IHC and MSI testing.","Zehn Schnitte reichen für eine fokussierte CRC-Diagnostik.":"Ten sections are sufficient for focused CRC diagnostics.","Melanom-spezifische Zusatztests sind methodisch und didaktisch Low Value.":"Melanoma-specific additional tests are methodologically and educationally low value.","MMR/MSI muss trotz bekanntem BRAF-Befund eigenständig beantwortet werden.":"MMR/MSI must be answered independently despite the known BRAF result.","Welche Aussage zum BRAF-V600E-Befund ist im mCRC am treffendsten?":"Which statement about BRAF V600E in mCRC is most accurate?","BRAF V600E ist prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden; ein Melanom-Algorithmus darf nicht übertragen werden.":"BRAF V600E is prognostically and therapeutically relevant, but must be interpreted according to CRC-specific evidence; a melanoma algorithm must not be transferred.","BRAF V600E bedeutet unabhängig von der Entität denselben BRAF/MEK-Algorithmus wie beim Melanom.":"BRAF V600E means the same BRAF/MEK algorithm as in melanoma, regardless of entity.","BRAF V600E ist beim CRC nur prognostisch, nicht therapeutisch relevant.":"In CRC, BRAF V600E is only prognostic, not therapeutically relevant.","Bei rechtsseitigem CRC spielt BRAF keine Rolle.":"In right-sided CRC, BRAF is irrelevant.","Entitätsspezifische Biologie und Therapiedaten sind entscheidend.":"Entity-specific biology and treatment data are decisive.","BRAF V600E ist nachgewiesen. Was folgt für MMR/MSI?":"BRAF V600E is detected. What follows for MMR/MSI?","MMR/MSI weiterhin separat bestimmen; BRAF V600E beweist weder dMMR noch MSI-H.":"Continue to assess MMR/MSI separately; BRAF V600E proves neither dMMR nor MSI-H.","BRAF V600E reicht als Surrogat für MSI-H.":"BRAF V600E is sufficient as a surrogate for MSI-H.","MMR/MSI ist bei BRAF-mutiertem mCRC therapeutisch bedeutungslos.":"MMR/MSI is therapeutically irrelevant in BRAF-mutant mCRC.","PD-L1 ersetzt die MSI-Testung.":"PD-L1 replaces MSI testing.","Die MMR/MSI-Ebene besitzt eine unabhängige prädiktive und ggf. hereditäre Bedeutung.":"The MMR/MSI level has independent predictive and potentially hereditary significance.","Welche Targetlogik ist für BRAF V600E im mCRC korrekt?":"Which target logic is correct for BRAF V600E in mCRC?","CRC-spezifische BRAF-gerichtete Strategie unter Einbezug der EGFR-Achse gemäß aktueller Therapielinie/Leitlinie.":"CRC-specific BRAF-targeted strategy incorporating the EGFR axis according to the current treatment line/guideline.","BRAF-Inhibitor allein ist die logische Standardstrategie.":"BRAF inhibitor alone is the logical standard strategy.","BRAF/MEK wie beim Melanom ohne CRC-spezifischen Kontext.":"BRAF/MEK as in melanoma without CRC-specific context.","BRAF V600E ist nicht targetierbar.":"BRAF V600E is not targetable.","Beim CRC ist die EGFR-Rückkopplung/Signalachse Teil der therapeutischen BRAF-Logik.":"In CRC, EGFR feedback/signaling is part of the therapeutic BRAF logic.","Interpretieren Sie BRAF V600E in einem rechtsseitigen mCRC und vervollständigen Sie MMR/MSI so, dass Prognose, Immuntherapie- und BRAF-Targetkontext sauber getrennt und integriert werden.":"Interpret BRAF V600E in right-sided mCRC and complete MMR/MSI so that prognosis, immunotherapy and BRAF-target contexts are clearly separated and integrated.","BRAF-V600E-Befund entitätsspezifisch bestätigen/einordnen.":"Confirm/classify the BRAF V600E finding in an entity-specific way.","MMR-IHC und MSI unabhängig bestimmen.":"Determine MMR IHC and MSI independently.","Ergebnis pMMR/MSS explizit kommunizieren.":"Explicitly communicate the pMMR/MSS result.","BRAF V600E als prognostisch ungünstigen und therapeutisch relevanten CRC-Kontext berichten.":"Report BRAF V600E as an adverse prognostic and therapeutically relevant CRC context.","Keinen Melanom-Algorithmus übertragen; aktuelle CRC-spezifische BRAF/EGFR-Strategie heranziehen.":"Do not transfer a melanoma algorithm; use the current CRC-specific BRAF/EGFR strategy.","Kolon-NGS-Panel zur gemeinsamen Erfassung von BRAF/RAS plus separate MMR-IHC/MSI.":"Colon NGS panel for joint detection of BRAF/RAS plus separate MMR IHC/MSI.","Breiteres validiertes Pan-Panel, sofern BRAF und MSI zuverlässig abgedeckt und die MMR-IHC sinnvoll ergänzt werden.":"Broader validated pan-panel provided BRAF and MSI are reliably covered and MMR IHC is appropriately added.","Melanom-BRAF-Template":"Melanoma BRAF template","Gleiche Mutation bedeutet nicht gleichen Therapiealgorithmus über Tumorentitäten hinweg.":"The same mutation does not mean the same treatment algorithm across tumor entities.","BRAF = MSI-H":"BRAF = MSI-H","Assoziation ist kein Ersatz für MMR/MSI-Diagnostik.":"Association is not a substitute for MMR/MSI testing.","BRAF allein befundet":"BRAF reported alone","Der Immuntherapie-/MMR-Kontext bleibt offen.":"The immunotherapy/MMR context remains unresolved.","BRAF V600E – aber pMMR/MSS":"BRAF V600E – but pMMR/MSS","Die MMR-IHC ist vollständig erhalten und die MSI-Testung zeigt MSS. Der rechtsseitige BRAF-V600E-Tumor ist damit gerade kein MSI-H-Fall. Gleichzeitig wird klar: Der BRAF-Befund führt nicht in einen Melanom-Pfad, sondern in eine CRC-spezifische BRAF-/EGFR-Therapielogik.":"MMR IHC is fully preserved and MSI testing shows MSS. The right-sided BRAF V600E tumor is therefore explicitly not an MSI-H case. At the same time, it becomes clear that the BRAF finding does not lead into a melanoma pathway but into CRC-specific BRAF/EGFR treatment logic.","Der Fall löst zwei häufige Kurzschlüsse gleichzeitig auf: BRAF ist weder ein MSI-Surrogat noch eine entitätsunabhängige Therapieschablone.":"The case resolves two common shortcuts at once: BRAF is neither an MSI surrogate nor an entity-independent treatment template.","CRC-spezifisch vollständig":"CRC-specific and complete","BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Prognostisch ungünstiger BRAF-Kontext; CRC-spezifische BRAF-gerichtete Strategie mit EGFR-Blockade nach aktueller Linie/Leitlinie diskutieren.":"BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Adverse prognostic BRAF context; discuss CRC-specific BRAF-targeted strategy with EGFR blockade according to current line/guideline.","Entität, MSI und Targetlogik korrekt integriert.":"Entity, MSI and target logic correctly integrated.","Nur BRAF":"BRAF only","BRAF V600E ist bekannt, MMR/MSI bleibt offen.":"BRAF V600E is known; MMR/MSI remains unresolved.","Therapeutisch und biologisch unvollständig.":"Therapeutically and biologically incomplete.","Melanom-Copyover":"Melanoma copyover","BRAF/MEK-Logik wird ohne CRC-spezifischen Kontext übertragen.":"BRAF/MEK logic is transferred without CRC-specific context.","Cross-Entity-Fehlinterpretation.":"Cross-entity misinterpretation.","pMMR/MSS bestätigt":"pMMR/MSS confirmed","BRAF- und Chemotherapie-/EGFR-Kontext nach aktueller Linie im MTB diskutieren.":"Discuss BRAF and chemotherapy/EGFR context in the MTB according to the current treatment line.","Der Fall bleibt Targeted-Therapy-orientiert, ohne MSI-H-IO-Pfad.":"The case remains targeted-therapy-oriented, without an MSI-H IO pathway.","unerwartet dMMR/MSI-H":"unexpected dMMR/MSI-H","Immuntherapie- und Lynch/sporadisch-Kontext zusätzlich priorisieren.":"Also prioritize immunotherapy and Lynch/sporadic context.","Therapiepriorisierung verändert sich.":"Treatment prioritization changes.","BRAF V600E ist im CRC entitätsspezifisch zu interpretieren.":"BRAF V600E must be interpreted in an entity-specific way in CRC.","BRAF V600E und MSI-H sind nicht gleichbedeutend.":"BRAF V600E and MSI-H are not equivalent.","MMR/MSI bleibt ein unabhängiger Biomarkerblock.":"MMR/MSI remains an independent biomarker block.","BRAF-gerichtete Therapie im CRC bindet die EGFR-Achse ein und darf nicht aus dem Melanom kopiert werden.":"BRAF-targeted treatment in CRC incorporates the EGFR axis and must not be copied from melanoma.","BRAF V600E + pMMR/MSS im rechtsseitigen mCRC. Kein Melanom-Algorithmus; CRC-spezifische BRAF-/EGFR-Strategie nach aktueller Therapielinie. MMR/MSI separat bestimmt und korrekt negativ eingeordnet.":"BRAF V600E + pMMR/MSS in right-sided mCRC. No melanoma algorithm; CRC-specific BRAF/EGFR strategy according to current treatment line. MMR/MSI assessed separately and correctly interpreted as negative.","Entitätsspezifische BRAF-Interpretation":"Entity-specific BRAF interpretation","MMR/MSI unabhängig geprüft":"MMR/MSI assessed independently","kein Melanom-Copyover":"no melanoma copyover","Prognose vs. Prädiktion getrennt":"Prognosis vs. prediction separated","Warum ist BRAF V600E kein MSI-Surrogat?":"Why is BRAF V600E not an MSI surrogate?","Warum reicht BRAF-Hemmung allein im CRC biologisch/klinisch nicht als Übertrag aus dem Melanom?":"Why is BRAF inhibition alone not biologically/clinically transferable from melanoma to CRC?","Welche Rolle spielt die Tumorlokalisation zusätzlich?":"What additional role does tumor sidedness play?","DE master":"DE master","BRAF V600E, aber pMMR/MSS":"BRAF V600E, but pMMR/MSS","Mutation ist entitätsspezifisch zu interpretieren":"Mutation must be interpreted in an entity-specific way","BRAF+ → MMR/MSI separat → pMMR/MSS → CRC-spezifische BRAF/EGFR-Logik":"BRAF+ → assess MMR/MSI separately → pMMR/MSS → CRC-specific BRAF/EGFR logic","Polypenrest statt invasivem Tumor eingeschickt → Befundbar oder neues Material anfordern?":"Polyp remnant submitted instead of invasive tumor → Reportable or request new material?","Polypenrest statt invasivem Tumor …":"Polyp remnant instead of invasive tumor …","Viszeralonkologie / Molekularpathologie":"Visceral oncology / Molecular pathology","64-jähriger Patient mit metastasiertem Sigma-Karzinom; vor Beginn der Systemtherapie werden RAS/BRAF und MMR/MSI angefordert.":"64-year-old patient with metastatic sigmoid carcinoma; RAS/BRAF and MMR/MSI are requested before systemic therapy.","Der eingesandte Block soll 'repräsentatives Tumorgewebe' enthalten. Ist das Material tatsächlich für die prädiktive Diagnostik geeignet?":"The submitted block is supposed to contain 'representative tumor tissue'. Is the material actually suitable for predictive diagnostics?","MTB in vier Tagen; die Onkologie bittet ausdrücklich um eine schnelle Freigabe.":"MTB in four days; oncology explicitly requests rapid release.","Vorgeschichte":"Medical history","Zunächst endoskopische Polypektomie, anschließend onkologische Sigmaresektion mit invasivem Adenokarzinom; inzwischen Lebermetastasen.":"Initially endoscopic polypectomy, followed by oncologic sigmoid resection showing invasive adenocarcinoma; now liver metastases.","Anforderung":"Request","Auf dem Molekularschein steht Block 'A1'. Im Pathologiesystem existieren jedoch sowohl Polypektomie A1 als auch Resektionsblock B7.":"The molecular request form lists block 'A1'. In the pathology system, however, there is both polypectomy A1 and resection block B7.","Ein automatisches 'Material vorhanden → testen' wäre schnell, könnte aber die falsche Läsion analysieren.":"An automatic 'material available → test' approach would be fast but could analyze the wrong lesion.","Technisch erfolgreiche Molekulardiagnostik ist nicht automatisch klinisch valide, wenn das untersuchte Gewebe die Fragestellung nicht repräsentiert.":"Technically successful molecular diagnostics are not automatically clinically valid if the tissue tested does not represent the clinical question.","HE-Reevaluation des eingesandten Blocks":"H&E reevaluation of the submitted block","Tubulovillöses Adenom mit hochgradiger intraepithelialer Neoplasie; kein sicher invasives Karzinom im eingesandten Material.":"Tubulovillous adenoma with high-grade intraepithelial neoplasia; no definite invasive carcinoma in the submitted material.","Diskrepanz":"Discrepancy","Die klinische Anforderung lautet metastasiertes CRC, der ausgewählte Block repräsentiert jedoch nur den früheren Polypenrest.":"The clinical request is metastatic CRC, but the selected block represents only the previous polyp remnant.","Verfügbarer Alternativblock":"Available alternative block","Im Archiv ist Resektionsblock B7 mit invasivem Adenokarzinom und ca. 60 % Tumor dokumentiert.":"Resection block B7 containing invasive adenocarcinoma with approx. 60% tumor is documented in the archive.","Darf der Polypenblock trotzdem molekular befundet werden oder muss die Analyse gestoppt und repräsentatives invasives Tumormaterial angefordert werden?":"Can the polyp block nevertheless be used for a molecular report, or must testing be stopped and representative invasive tumor material requested?","Eingesandter Block":"Submitted block","Polypektomie A1, adenomatöses Gewebe ohne sichere Invasion.":"Polypectomy A1, adenomatous tissue without definite invasion.","Tumoranteil für die klinische Fragestellung":"Tumor fraction for the clinical question","0 % sicher invasives Karzinom.":"0% definite invasive carcinoma.","Technische DNA-Qualität":"Technical DNA quality","gut – genau das macht die Falle gefährlich.":"good – exactly what makes the trap dangerous.","Archivhinweis":"Archive note","Resektionsblock B7 ist verfügbar und enthält repräsentatives invasives Karzinom.":"Resection block B7 is available and contains representative invasive carcinoma.","Ein molekular technisch plausibler Befund aus dem Polypenrest darf nicht als Biomarkerbefund des metastasierten invasiven Karzinoms ausgegeben werden.":"A technically plausible molecular result from the polyp remnant must not be issued as the biomarker result of the metastatic invasive carcinoma.","Materialidentität / HE-Reevaluation":"Material identity / H&E reevaluation","Repräsentatives invasives Tumormaterial anfordern":"Request representative invasive tumor material","HE-Reevaluation":"H&E reevaluation","Im eingesandten Block findet sich adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Das Material repräsentiert die klinische Fragestellung nicht.":"The submitted block contains adenomatous tissue with high-grade dysplasia but no definite invasive carcinoma. The material does not represent the clinical question.","Neues / korrektes Tumormaterial":"New / correct tumor material","Resektionsblock B7 wird nachgefordert: invasives kolorektales Adenokarzinom, ca. 60 % Tumoranteil, für prädiktive Molekulardiagnostik geeignet.":"Resection block B7 is requested: invasive colorectal adenocarcinoma, approx. 60% tumor fraction, suitable for predictive molecular diagnostics.","MMR/MSI auf dem falschen Block":"MMR/MSI on the wrong block","Die Untersuchung kann technisch auswertbar sein, beantwortet aber am adenomatösen Polypenrest die Biomarkerfrage des invasiven/metastasierten Karzinoms nicht belastbar. Keine klinische Freigabe als Tumorbefund.":"The test may be technically evaluable, but on adenomatous polyp remnant it does not reliably answer the biomarker question of the invasive/metastatic carcinoma. Do not release clinically as a tumor result.","NGS/RAS/BRAF auf dem falschen Block":"NGS/RAS/BRAF on the wrong block","Technisch plausibler Befund aus adenomatösem Gewebe – z. B. APC-Alteration bei fehlendem RAS/BRAF-Nachweis. Dieser Befund darf nicht als prädiktiver Status des invasiven/metastasierten CRC interpretiert werden.":"Technically plausible finding from adenomatous tissue – e.g. APC alteration with no RAS/BRAF detected. This must not be interpreted as the predictive status of the invasive/metastatic CRC.","Präanalytik":"Preanalytics","Anforderung, Blockbezeichnung und Histologie sind diskordant; vor Freigabe muss die Probenidentität bzw. Repräsentativität geklärt werden.":"Request, block designation and histology are discordant; sample identity/representativeness must be clarified before release.","Der eingesandte Polypenblock ist für die prädiktive Diagnostik des metastasierten invasiven CRC nicht geeignet. Die Analyse muss für diese klinische Fragestellung gestoppt bzw. nicht freigegeben und repräsentatives invasives Tumormaterial angefordert werden. Ein technisch erfolgreicher Befund aus dem falschen Gewebe wäre klinisch irreführend.":"The submitted polyp block is unsuitable for predictive diagnostics of the metastatic invasive CRC. Testing must be stopped/not released for this clinical question and representative invasive tumor material requested. A technically successful result from the wrong tissue would be clinically misleading.","Teilbefund: Ohne HE-Reevaluation und Abgleich der Blockidentität bleibt unklar, ob das untersuchte Material den invasiven Tumor repräsentiert. Molekulare Ergebnisse dürfen nicht allein aufgrund technischer QC freigegeben werden.":"Partial finding: Without H&E reevaluation and verification of block identity, it remains unclear whether the tested material represents the invasive tumor. Molecular results must not be released based on technical QC alone.","Falsches/nicht repräsentatives Material als primäres Problem erkennen":"Recognize wrong/non-representative material as the primary problem","Molekulare Freigabe stoppen bzw. nicht als invasiven Tumor befundet ausgeben":"Stop molecular release or do not issue it as an invasive tumor result","Diskrepanz und Grund der Nachforderung transparent mit Klinik/Pathologie kommunizieren":"Communicate discrepancy and reason for requesting new material transparently with clinicians/pathology","Technische Validität klar von klinischer Validität unterscheiden":"Clearly distinguish technical validity from clinical validity","Optimale Lösung: zuerst HE und Materialidentität prüfen; der eingesandte Polypenrest ist klinisch ungeeignet. Nicht 'irgendetwas' sequenzieren und befundbar machen, sondern den richtigen invasiven Tumorblock anfordern.":"Optimal solution: First check H&E and material identity; the submitted polyp remnant is clinically unsuitable. Do not sequence 'whatever is there' and make it reportable; request the correct invasive tumor block.","falsches Material":"wrong material","Materialidentität":"Material identity","LAB":"LAB","Falscher Block, perfektes QC: Wann ein technisch guter Befund klinisch wertlos ist":"Wrong block, perfect QC: When a technically good result is clinically worthless","Molekularpathologie / Pathologieassistenz / Labor":"Molecular pathology / Pathology assistance / Laboratory","Repräsentativität des Materials vor Molekulardiagnostik prüfen.":"Check material representativeness before molecular diagnostics.","Technische Validität von klinischer Validität unterscheiden.":"Distinguish technical validity from clinical validity.","Bei falschem/nicht invasivem Material die Freigabe stoppen und korrektes Tumorgewebe anfordern.":"For wrong/non-invasive material, stop release and request correct tumor tissue.","Eine Präanalytik-Diskrepanz nachvollziehbar dokumentieren und kommunizieren.":"Document and communicate a preanalytical discrepancy in a traceable manner.","Die DNA-QC ist hervorragend, der Tumorboard-Termin ist nah und der Auftrag lautet RAS/BRAF/MMR/MSI. Der einzige Haken: Auf dem Kontroll-HE liegt gar kein invasives Karzinom, sondern nur der Rest eines früheren Adenoms. Genau jetzt entscheidet sich, ob 'gute Technik' zur gefährlichen Scheinsicherheit wird.":"DNA QC is excellent, the tumor board is approaching, and the request is RAS/BRAF/MMR/MSI. The only catch: the control H&E contains no invasive carcinoma at all, only the remnant of an earlier adenoma. This is exactly where 'good technology' can become dangerous false reassurance.","64-jähriger Patient mit metastasiertem Sigma-Karzinom. Für die prädiktive Molekulardiagnostik wurde versehentlich der Block einer früheren Polypektomie ausgewählt. Er enthält adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Ein repräsentativer Resektionsblock ist im Archiv vorhanden.":"64-year-old patient with metastatic sigmoid carcinoma. The block from an earlier polypectomy was selected by mistake for predictive molecular diagnostics. It contains adenomatous tissue with high-grade dysplasia but no definite invasive carcinoma. A representative resection block is available in the archive.","RAS/BRAF und MMR/MSI vor Systemtherapie.":"RAS/BRAF and MMR/MSI before systemic therapy.","Die klinische Frage bezieht sich auf das invasive/metastasierte Karzinom.":"The clinical question refers to the invasive/metastatic carcinoma.","Polypektomie A1 mit Adenom/HGIEN, ohne sichere Invasion.":"Polypectomy A1 with adenoma/HGIEN, without definite invasion.","Die Probenidentität ist klinisch falsch, obwohl die DNA technisch gut sein kann.":"The sample identity is clinically wrong even though the DNA may be technically good.","Alternativmaterial":"Alternative material","Resektionsblock B7 mit ca. 60 % invasivem Tumor ist verfügbar.":"Resection block B7 with approx. 60% invasive tumor is available.","Die richtige Lösung ist Nachforderung/Blockwechsel, nicht Interpretation des falschen Materials.":"The correct solution is to request/switch block, not interpret the wrong material.","Kein sicher invasives Karzinom im eingesandten Block.":"No definite invasive carcinoma in the submitted block.","Sehr gute DNA-Qualität – technisch wären PCR/NGS problemlos möglich.":"Very good DNA quality – technically PCR/NGS would be straightforward.","LIMS-Abgleich":"LIMS cross-check","Block A1 gehört zur Polypektomie; Resektionsblock B7 trägt den invasiven Tumor.":"Block A1 belongs to the polypectomy; resection block B7 contains the invasive tumor.","MTB in vier Tagen erzeugt realen Zeitdruck.":"MTB in four days creates real time pressure.","Das korrekte Material existiert, muss aber aktiv nachgefordert/umgebucht werden.":"The correct material exists but must be actively requested/reassigned.","Jede Molekulardiagnostik am falschen Block produziert potenziell einen technisch plausiblen, klinisch irreführenden Befund.":"Any molecular testing on the wrong block may produce a technically plausible but clinically misleading result.","Was ist der nächste entscheidende Schritt?":"What is the next decisive step?","HE/Blockidentität prüfen, Analyse am Polypenrest stoppen und repräsentatives invasives Tumormaterial anfordern.":"Check H&E/block identity, stop analysis on the polyp remnant and request representative invasive tumor material.","Wegen des MTB-Termins sofort NGS durchführen; gute DNA-QC reicht.":"Because of the MTB deadline, run NGS immediately; good DNA QC is sufficient.","Nur MMR-IHC durchführen und den Rest später entscheiden.":"Perform only MMR IHC and decide the rest later.","Molekularbefund aus dem Adenom als Status des metastasierten CRC berichten.":"Report the molecular result from the adenoma as the status of the metastatic CRC.","Präanalytische Repräsentativität ist Voraussetzung jeder klinischen Interpretation.":"Preanalytical representativeness is a prerequisite for any clinical interpretation.","Ein NGS-Lauf aus dem Polypenrest ist technisch valide. Ist der Befund damit klinisch valide?":"An NGS run from the polyp remnant is technically valid. Does that make the result clinically valid?","Nein. Ein technisch korrekter Befund kann klinisch unbrauchbar sein, wenn das analysierte Gewebe die Fragestellung nicht repräsentiert.":"No. A technically correct result can be clinically unusable if the analyzed tissue does not represent the clinical question.","Ja. Technische QC ist die einzige Voraussetzung für Freigabe.":"Yes. Technical QC is the only prerequisite for release.","Ja, sofern RAS/BRAF Wildtyp sind.":"Yes, provided RAS/BRAF are wild type.","Ja, wenn ein breites Panel benutzt wurde.":"Yes, if a broad panel was used.","Analytische Qualität ersetzt nicht Probenidentität und klinische Repräsentativität.":"Analytical quality does not replace sample identity and clinical representativeness.","Wie soll die Diskrepanz behandelt werden?":"How should the discrepancy be handled?","Dokumentieren, Einsender/Pathologie kontaktieren, korrekten Block nachfordern und erst dann prädiktiv testen.":"Document it, contact the submitter/pathology, request the correct block and only then perform predictive testing.","Intern korrigieren, aber nicht dokumentieren.":"Correct internally but do not document.","Annehmen, dass Polyp und Karzinom denselben Biomarkerstatus haben.":"Assume polyp and carcinoma have the same biomarker status.","Gesamten Fall endgültig abbrechen, obwohl geeignetes Material vorhanden ist.":"Abort the entire case permanently even though suitable material is available.","Rückverfolgbarkeit und transparente Kommunikation gehören zur Fehlerbeherrschung.":"Traceability and transparent communication are part of error control.","Entscheiden Sie, ob der Polypenrest befundbar ist, und steuern Sie den Fall so, dass nur repräsentatives invasives Tumorgewebe in die prädiktive Diagnostik eingeht.":"Decide whether the polyp remnant is reportable and manage the case so that only representative invasive tumor tissue enters predictive diagnostics.","Kontroll-HE des ausgewählten Blocks prüfen.":"Review the control H&E of the selected block.","Diskrepanz zwischen Anforderung und Histologie erkennen.":"Recognize the discrepancy between request and histology.","Molekulare Freigabe am Polypenrest stoppen.":"Stop molecular release from the polyp remnant.","Resektionsblock B7 bzw. anderes repräsentatives invasives Material anfordern.":"Request resection block B7 or other representative invasive material.","Diskrepanz und Kommunikation dokumentieren.":"Document the discrepancy and communication.","Erst am korrekten Tumormaterial mit RAS/BRAF/MMR/MSI fortfahren.":"Only continue with RAS/BRAF/MMR/MSI on the correct tumor material.","Geeignete Metastasenbiopsie anfordern, falls der Resektionsblock nicht verfügbar/qualitativ ungeeignet wäre.":"Request a suitable metastatic biopsy if the resection block is unavailable/qualitatively unsuitable.","'DNA ist gut, also los'":"'DNA is good, so go ahead'","Technische QC sagt nichts darüber aus, ob die richtige Läsion untersucht wird.":"Technical QC says nothing about whether the correct lesion is being tested.","Adenom-Biomarker = Karzinom-Biomarker":"Adenoma biomarker = carcinoma biomarker","Klonale Evolution und fehlende Repräsentativität machen diese Gleichsetzung unzulässig.":"Clonal evolution and lack of representativeness make this equation invalid.","Zeitdruck als Freigabeargument":"Time pressure as an argument for release","Ein schneller falscher Befund ist schlechter als eine dokumentierte Nachforderung.":"A fast wrong result is worse than a documented request for correct material.","Der falsche Block liefert einen überzeugenden Befund":"The wrong block yields a convincing result","Wird voreilig sequenziert, zeigt das Adenom eine plausible APC-Alteration und keinen RAS/BRAF-Treiber. Technisch sieht alles sauber aus. Erst der HE-/LIMS-Abgleich zeigt, dass dieser Befund für das invasive metastasierte CRC gar nicht freigegeben werden darf.":"If sequencing is performed prematurely, the adenoma shows a plausible APC alteration and no RAS/BRAF driver. Technically everything looks clean. Only H&E/LIMS cross-check reveals that this result must not be released for the invasive metastatic CRC.","Die gefährlichsten Präanalytikfehler produzieren nicht zwingend einen technischen Fehler – sondern einen glaubwürdigen Befund am falschen Material.":"The most dangerous preanalytical errors do not necessarily produce a technical error – they may produce a credible result on the wrong material.","Materialfehler vor Analytik gestoppt":"Material error stopped before analysis","HE zeigt kein invasives Karzinom; korrekter Resektionsblock B7 wird angefordert.":"H&E shows no invasive carcinoma; correct resection block B7 is requested.","Patientensicher und ressourcenschonend.":"Safe for the patient and resource-efficient.","Technisch erfolgreich, klinisch falsch":"Technically successful, clinically wrong","NGS aus Adenom: APC-Alteration, RAS/BRAF WT. Befund darf nicht als metastasiertes CRC interpretiert werden.":"NGS from adenoma: APC alteration, RAS/BRAF WT. The result must not be interpreted as metastatic CRC.","Analytisch valide, klinisch invalide.":"Analytically valid, clinically invalid.","Falschen Block freigegeben":"Wrong block released","Adenom-Befund wird als Tumorprofil berichtet.":"Adenoma result is reported as the tumor profile.","Kritischer Präanalytik-/Freigabefehler.":"Critical preanalytical/release error.","Resektionsblock B7 verfügbar":"Resection block B7 available","Kontroll-HE, Tumormarkierung und reguläre CRC-Biomarkerdiagnostik durchführen.":"Perform control H&E, tumor marking and standard CRC biomarker diagnostics.","Der Fall kann ohne neue invasive Probengewinnung korrekt abgeschlossen werden.":"The case can be completed correctly without obtaining a new invasive sample.","Kein geeignetes Archivmaterial":"No suitable archived material","Mit Klinik eine geeignete Metastasen- oder Primärtumorprobe abstimmen.":"Coordinate an appropriate metastatic or primary tumor sample with the clinical team.","TAT steigt, klinische Validität bleibt gewahrt.":"TAT increases, clinical validity is preserved.","Materialidentität und Repräsentativität stehen vor analytischer QC.":"Material identity and representativeness come before analytical QC.","Ein technisch valider Befund kann klinisch falsch sein.":"A technically valid result can be clinically wrong.","Polyp/Adenom ist kein automatischer Surrogatblock für ein invasives metastasiertes CRC.":"Polyp/adenoma is not an automatic surrogate block for invasive metastatic CRC.","Zeitdruck rechtfertigt keine Freigabe aus falschem Material.":"Time pressure does not justify release from the wrong material.","HE-Reevaluation zeigt nur Adenom/HGIEN. Molekulare Freigabe stoppen, Blockidentität klären und Resektionsblock B7 mit invasivem Tumor anfordern. Etwaige bereits erzeugte Daten aus dem Polypenrest nicht als prädiktiven Tumorbefund freigeben.":"H&E reevaluation shows only adenoma/HGIEN. Stop molecular release, clarify block identity and request resection block B7 with invasive tumor. Do not release any already generated data from the polyp remnant as a predictive tumor result.","Präanalytik vor Analytik":"Preanalytics before analytics","Stop/No-Go korrekt":"Stop/No-Go correct","korrektes Material angefordert":"correct material requested","technische vs. klinische Validität verstanden":"technical vs. clinical validity understood","Welche Kontrollen verhindern solche Blockverwechslungen?":"Which controls prevent such block mix-ups?","Wann kann ein Vorläuferläsionsblock überhaupt sinnvoll molekular untersucht werden?":"When can a precursor-lesion block be meaningfully tested molecularly?","Wie dokumentiert man einen bereits erzeugten, aber klinisch nicht freigabefähigen Datensatz?":"How should an already generated but clinically non-releasable dataset be documented?","perfekte DNA aus falschem Gewebe":"perfect DNA from the wrong tissue","technisch valide ≠ klinisch valide":"technically valid ≠ clinically valid","HE → Diskrepanz → Stop → korrekter Block":"H&E → discrepancy → stop → correct block","HER2-amplifiziertes RAS-WT-CRC → HER2 als Resistenz-/Target-Kontext":"HER2-amplified RAS-WT CRC → HER2 as resistance/target context","HER2-amplifiziertes RAS-WT-CRC":"HER2-amplified RAS-WT CRC","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom. Initial RAS/BRAF-Wildtyp und pMMR/MSS; unter FOLFOX plus Cetuximab zunächst deutliche Remission, jetzt hepatischer Progress.":"61-year-old patient with left-sided metastatic sigmoid carcinoma. Initially RAS/BRAF wild type and pMMR/MSS; marked response to FOLFOX plus cetuximab, now hepatic progression.","Der Progressionsbefund zeigt weiterhin keine RAS- oder BRAF-Mutation, aber einen ERBB2/HER2-Copy-number-Hinweis. Wie ist das therapeutisch zu interpretieren?":"The progression sample still shows no RAS or BRAF mutation but suggests ERBB2/HER2 copy-number gain. How should this be interpreted therapeutically?","Die nächste Therapielinie soll im MTB in fünf Tagen festgelegt werden.":"The next treatment line is to be defined in the MTB in five days.","Sigma, linksseitig; initiale Resektion vor 18 Monaten.":"Sigmoid, left-sided; initial resection 18 months ago.","Initiales Molekularprofil":"Initial molecular profile","KRAS/NRAS Wildtyp, BRAF Wildtyp, pMMR/MSS.":"KRAS/NRAS wild type, BRAF wild type, pMMR/MSS.","Therapieverlauf":"Treatment course","FOLFOX plus Cetuximab mit gutem initialem Ansprechen; nach 11 Monaten Progress einzelner Leberläsionen.":"FOLFOX plus cetuximab with good initial response; progression of individual liver lesions after 11 months.","Didaktischer Schlüssel":"Educational key","Der Satz 'RAS und BRAF negativ' ist beim mCRC therapeutisch nicht einfach 'kein Befund': Das Fehlen etablierter MAPK-Downstream-Resistenztreiber ist eine Voraussetzung, die anti-EGFR-Antikörperstrategie bei passendem klinischem Kontext überhaupt eröffnet.":"In mCRC, the phrase 'RAS and BRAF negative' is not simply 'no finding' therapeutically: the absence of established downstream MAPK resistance drivers is a prerequisite that makes an anti-EGFR antibody strategy possible in an appropriate clinical context.","Warum kann der Tumor trotz weiterem RAS/BRAF-Wildtyp progredient sein, und welche Rolle spielt HER2?":"Why can the tumor progress despite continued RAS/BRAF wild type, and what role does HER2 play?","Progressionsbiopsie":"Progression biopsy","Lebermetastase eines kolorektalen Adenokarzinoms, vital und gut repräsentativ.":"Liver metastasis of colorectal adenocarcinoma, viable and well representative.","ca. 65 %.":"approx. 65%.","Aus der Primärdiagnostik pMMR/MSS, klinisch ausreichend dokumentiert.":"pMMR/MSS from primary diagnostics, sufficiently documented clinically.","Progressionsprofil":"Progression profile","Kein RAS-/BRAF-Resistenzbefund; ERBB2 mit deutlicher Copy-number-Erhöhung im DNA-Panel.":"No RAS/BRAF resistance finding; ERBB2 with marked copy-number gain in the DNA panel.","Ist die ERBB2-Veränderung bestätigt, und wie verändert sie die scheinbar 'negative' RAS/BRAF-Situation?":"Is the ERBB2 alteration confirmed, and how does it change the apparently 'negative' RAS/BRAF situation?","FFPE-Lebermetastasenbiopsie, Block L3.":"FFPE liver metastasis biopsy, block L3.","ca. 65 %, DNA-QC sehr gut.":"approx. 65%, DNA QC very good.","HER2-Bestätigung":"HER2 confirmation","IHC/ISH ist am vorhandenen Material möglich.":"IHC/ISH is possible on the available material.","Breite Wiederholung bereits gesicherter MMR/MSI-Diagnostik verbraucht Material, während die konkrete Progressionsfrage HER2-Bestätigung und Resistenzkontext betrifft.":"Broad repetition of already established MMR/MSI testing consumes material, whereas the specific progression question concerns HER2 confirmation and resistance context.","Progressionsprofil / RAS-BRAF-ERBB2-Kontext":"Progression profile / RAS-BRAF-ERBB2 context","HER2-Amplifikation bestätigen":"Confirm HER2 amplification","KRAS/NRAS weiterhin Wildtyp, BRAF Wildtyp; keine neue klassische RAS/RAF-Resistenzmutation. ERBB2 zeigt eine hochgradige Copy-number-Erhöhung.":"KRAS/NRAS remain wild type, BRAF wild type; no new classic RAS/RAF resistance mutation. ERBB2 shows high-level copy-number gain.","KRAS/NRAS Wildtyp. Das Fehlen einer RAS-Mutation ist im geeigneten linksseitigen mCRC-Kontext therapeutisch relevant, garantiert aber keine dauerhafte Sensitivität gegenüber anti-EGFR-Antikörpern.":"KRAS/NRAS wild type. The absence of a RAS mutation is therapeutically relevant in an appropriate left-sided mCRC context, but does not guarantee durable sensitivity to anti-EGFR antibodies.","BRAF V600E nicht nachweisbar. RAS/BRAF-Wildtyp bedeutet nicht 'molekular ohne Bedeutung', sondern schließt wichtige etablierte MAPK-Resistenztreiber aus.":"BRAF V600E not detected. RAS/BRAF wild type does not mean 'molecularly meaningless'; it excludes important established MAPK resistance drivers.","HER2 IHC/ISH":"HER2 IHC/ISH","HER2 stark überexprimiert / ERBB2 amplifiziert. Der Befund ist im RAS/BRAF-WT-mCRC ein relevanter Target- und möglicher anti-EGFR-Resistenzkontext, insbesondere in der Progressionssituation.":"HER2 strongly overexpressed / ERBB2 amplified. In RAS/BRAF-WT mCRC, the finding is a relevant target and possible anti-EGFR resistance context, particularly in progression.","HER2-IHC allein":"HER2 IHC alone","HER2 IHC 3+. Im CRC-Kontext sollte die zugrunde liegende ERBB2-Amplifikation bzw. ein validierter HER2-positiver Status nach lokalem Algorithmus gesichert werden.":"HER2 IHC 3+. In the CRC context, the underlying ERBB2 amplification or a validated HER2-positive status should be confirmed according to the local algorithm.","Erneute MMR/MSI-Testung":"Repeat MMR/MSI testing","pMMR/MSS wird bestätigt. In diesem Fall war der Status bereits belastbar bekannt; die Wiederholung beantwortet die konkrete Progressions-/HER2-Frage kaum und ist daher eher ressourcenarm zu priorisieren.":"pMMR/MSS is confirmed. In this case the status was already robustly known; repeating it barely answers the specific progression/HER2 question and should therefore be given low priority for resource use.","Progressionsbiopsie repräsentativ; hohe Tumorzellularität und gute DNA-Qualität. Baseline-HER2-Status war nicht bestimmt.":"Progression biopsy representative; high tumor cellularity and good DNA quality. Baseline HER2 status was not determined.","RAS/BRAF-Wildtyp ist beim linksseitigen mCRC kein bedeutungsloser Negativbefund: Das Fehlen zentraler downstream MAPK-Resistenztreiber schafft erst die molekulare Voraussetzung für eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext. Wildtyp garantiert jedoch keine Sensitivität. Im Progress wird eine bestätigte ERBB2/HER2-Amplifikation gefunden, die einen alternativen Signalweg, einen möglichen anti-EGFR-Resistenzkontext und zugleich eine HER2-gerichtete Therapieoption im passenden Linien-/Zulassungskontext eröffnet. Ohne Baseline-HER2 kann nicht sicher behauptet werden, dass die Amplifikation neu erworben wurde.":"RAS/BRAF wild type is not a meaningless negative finding in left-sided mCRC: the absence of key downstream MAPK resistance drivers creates the molecular prerequisite for an anti-EGFR antibody strategy in the appropriate clinical context. Wild type, however, does not guarantee sensitivity. At progression, confirmed ERBB2/HER2 amplification is found, opening an alternative signaling pathway, a possible anti-EGFR resistance context and, at the same time, a HER2-directed treatment option in the appropriate line/approval context. Without baseline HER2, it cannot be stated with certainty that the amplification was newly acquired.","Teilbefund: RAS/BRAF-Wildtyp ist korrekt erkannt, aber entweder wird 'negativ' fälschlich als therapeutisch bedeutungslos bezeichnet oder die ERBB2-Copy-number-Veränderung bleibt unbestätigt. Beides verhindert eine belastbare Progressionsinterpretation.":"Partial finding: RAS/BRAF wild type is correctly recognized, but either 'negative' is incorrectly described as therapeutically meaningless or the ERBB2 copy-number alteration remains unconfirmed. Both prevent robust interpretation of progression.","Explizit erklären: RAS/BRAF-Wildtyp ist ein therapeutisch relevanter 'negativer' Befund, der anti-EGFR bei passendem linksseitigem mCRC-Kontext ermöglicht":"Explicitly explain: RAS/BRAF wild type is a therapeutically relevant 'negative' selection finding that enables anti-EGFR in the appropriate left-sided mCRC context","Wildtyp nicht als Garantie für anti-EGFR-Sensitivität darstellen":"Do not present wild type as a guarantee of anti-EGFR sensitivity","HER2-Amplifikation als alternativen Target-/Resistenzkontext integrieren":"Integrate HER2 amplification as an alternative target/resistance context","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher neu erworben":"Without baseline HER2, do not claim that the amplification is definitely newly acquired","Aktuelle Linien-/Leitlinien-/Zulassungssituation für HER2-gerichtete Therapie transparent berücksichtigen":"Transparently account for the current line/guideline/approval context for HER2-directed therapy","Optimale Lösung: den RAS/BRAF-Wildtyp bewusst als therapeutisch positiven Selektionsbefund erklären; Progress trotz Wildtyp als Hinweis auf alternative Resistenzwege verstehen und die ERBB2/HER2-Amplifikation bestätigen und als Target-/Resistenzkontext integrieren.":"Optimal solution: Explain RAS/BRAF wild type deliberately as a therapeutically positive selection finding; understand progression despite wild type as a clue to alternative resistance pathways and confirm ERBB2/HER2 amplification, integrating it as a target/resistance context.","RAS Wildtyp":"RAS wild type","BRAF Wildtyp":"BRAF wild type","ERBB2 Amplifikation":"ERBB2 amplification","Resistenz":"Resistance","Wenn 'negativ' therapeutisch positiv ist: RAS/BRAF-Wildtyp, anti-EGFR und der HER2-Twist":"When 'negative' is therapeutically positive: RAS/BRAF wild type, anti-EGFR and the HER2 twist","RAS/BRAF-Wildtyp als therapeutisch relevanten negativen Selektionsbefund im mCRC erklären.":"Explain RAS/BRAF wild type as a therapeutically relevant negative selection finding in mCRC.","Anti-EGFR-Eignung als Kontextentscheidung und nicht als garantierte Sensitivität verstehen.":"Understand anti-EGFR eligibility as a contextual decision rather than guaranteed sensitivity.","HER2/ERBB2-Amplifikation als alternativen Target- und möglichen Resistenzkontext integrieren.":"Integrate HER2/ERBB2 amplification as an alternative target and possible resistance context.","Zwischen 'nach Progress nachgewiesen' und 'erworben' unterscheiden, wenn kein Baseline-HER2 vorliegt.":"Distinguish 'detected after progression' from 'acquired' when no baseline HER2 is available.","Im Progressions-MTB steht auf der Folie: 'KRAS, NRAS, BRAF: keine Mutation nachweisbar'. Ein Kollege fasst zusammen: 'Molekular also wieder negativ.' Genau hier liegt der Kern des Falls: Beim mCRC kann ein negativer RAS/BRAF-Befund therapeutisch eine positive Information sein – und trotzdem erklärt er den jetzigen Progress nicht. Im selben Panel taucht nämlich eine deutliche ERBB2-Copy-number-Erhöhung auf.":"On the progression MTB slide it says: 'KRAS, NRAS, BRAF: no mutation detected'. A colleague summarizes: 'So molecularly negative again.' This is exactly the core of the case: in mCRC, a negative RAS/BRAF result can be therapeutically positive information – and still fail to explain the current progression. The same panel, however, shows a marked ERBB2 copy-number gain.","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom, initial RAS/BRAF-Wildtyp und pMMR/MSS. Unter FOLFOX plus Cetuximab gutes Ansprechen, nach elf Monaten Progress in der Leber. Die Progressionsbiopsie bleibt RAS/BRAF-Wildtyp, zeigt aber eine hochgradige ERBB2-Copy-number-Erhöhung. Der Fall soll den scheinbaren Widerspruch 'negativ = therapeutisch positiv' erklären und anschließend HER2 als alternativen Resistenz-/Targetkontext einordnen.":"61-year-old patient with left-sided metastatic sigmoid carcinoma, initially RAS/BRAF wild type and pMMR/MSS. Good response to FOLFOX plus cetuximab, liver progression after 11 months. Progression biopsy remains RAS/BRAF wild type but shows high-level ERBB2 copy-number gain. The case is intended to explain the apparent contradiction 'negative = therapeutically positive' and then classify HER2 as an alternative resistance/target context.","Baseline":"Baseline","Linksseitiges mCRC, RAS/BRAF-Wildtyp, pMMR/MSS.":"Left-sided mCRC, RAS/BRAF wild type, pMMR/MSS.","Dieser Molekularkontext ermöglichte grundsätzlich eine anti-EGFR-Antikörperstrategie.":"This molecular context made an anti-EGFR antibody strategy possible in principle.","Gutes initiales Ansprechen unter FOLFOX + Cetuximab, Progress nach 11 Monaten.":"Good initial response to FOLFOX + cetuximab, progression after 11 months.","Wildtyp ist Selektion, keine Garantie dauerhafter Sensitivität.":"Wild type is selection, not a guarantee of durable sensitivity.","Weiterhin RAS/BRAF-Wildtyp, aber ERBB2-Copy-number hoch.":"Still RAS/BRAF wild type, but ERBB2 copy number high.","Resistenz kann über alternative Signalwege entstehen/bestehen.":"Resistance can arise/persist through alternative signaling pathways.","Limitation":"Limitation","HER2 wurde an der Baseline nicht bestimmt.":"HER2 was not assessed at baseline.","Die aktuelle Amplifikation darf nicht sicher als neu erworben bezeichnet werden.":"The current amplification cannot be described with certainty as newly acquired.","Initialdiagnostik":"Initial diagnostics","KRAS/NRAS WT, BRAF WT, pMMR/MSS.":"KRAS/NRAS WT, BRAF WT, pMMR/MSS.","Aktueller Progress":"Current progression","Lebermetastasenbiopsie mit 65 % Tumor und guter DNA-QC.":"Liver metastasis biopsy with 65% tumor and good DNA QC.","Panel-Hinweis":"Panel signal","ERBB2 hochgradige Copy-number-Erhöhung; RAS/BRAF weiter WT.":"High-level ERBB2 copy-number gain; RAS/BRAF remain WT.","Neun Schnitte reichen für HER2-Bestätigung und fokussierte Progressionsdiagnostik.":"Nine sections are sufficient for HER2 confirmation and focused progression diagnostics.","MMR/MSI ist bereits belastbar dokumentiert und muss nicht reflexartig wiederholt werden.":"MMR/MSI is already robustly documented and need not be repeated reflexively.","HER2-Status sollte orthogonal/validiert bestätigt werden, bevor die therapeutische Schlussfolgerung formuliert wird.":"HER2 status should be confirmed orthogonally/with a validated method before formulating the therapeutic conclusion.","Wie ist 'KRAS/NRAS/BRAF: keine pathogene Mutation nachweisbar' beim linksseitigen mCRC therapeutisch zu lesen?":"How should 'KRAS/NRAS/BRAF: no pathogenic mutation detected' be read therapeutically in left-sided mCRC?","Als therapeutisch relevanter Wildtyp-/Ausschlussbefund: zentrale downstream MAPK-Resistenztreiber fehlen, sodass eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext grundsätzlich möglich wird.":"As a therapeutically relevant wild-type/exclusion finding: key downstream MAPK resistance drivers are absent, so an anti-EGFR antibody strategy becomes possible in the appropriate clinical context.","Als völlig bedeutungsloser Negativbefund ohne therapeutische Aussage.":"As a completely meaningless negative finding with no therapeutic implication.","Als Garantie, dass anti-EGFR sicher und dauerhaft wirkt.":"As a guarantee that anti-EGFR will work safely and durably.","Als Beweis, dass auch HER2 keine Rolle spielen kann.":"As proof that HER2 cannot play a role either.","Das Fehlen von RAS/BRAF-Treibern ist eine positive Selektionsinformation, aber keine Erfolgsgarantie.":"The absence of RAS/BRAF drivers is positive selection information, but not a guarantee of success.","Der Patient progrediert trotz weiterem RAS/BRAF-Wildtyp. Was ist die beste Interpretation?":"The patient progresses despite continued RAS/BRAF wild type. What is the best interpretation?","Wildtyp schließt nur bestimmte Resistenzwege aus; alternative Mechanismen wie HER2/ERBB2 können relevant sein.":"Wild type excludes only certain resistance pathways; alternative mechanisms such as HER2/ERBB2 may be relevant.","Progress beweist, dass der RAS/BRAF-Test falsch sein muss.":"Progression proves that the RAS/BRAF test must be wrong.","Damit war die ursprüngliche anti-EGFR-Strategie grundsätzlich falsch.":"This means the original anti-EGFR strategy was fundamentally wrong.","Molekulare Diagnostik kann den Progress nicht mehr erklären.":"Molecular diagnostics can no longer explain progression.","Resistenzbiologie ist breiter als RAS/BRAF allein.":"Resistance biology is broader than RAS/BRAF alone.","Wie sollte die ERBB2-Copy-number-Erhöhung weiterbehandelt werden?":"How should the ERBB2 copy-number gain be followed up?","HER2-positiven Status mit validiertem IHC/ISH-Algorithmus bestätigen und als Target-/möglichen anti-EGFR-Resistenzkontext integrieren.":"Confirm HER2-positive status with a validated IHC/ISH algorithm and integrate it as a target/possible anti-EGFR resistance context.","Ignorieren, da RAS/BRAF Wildtyp sind.":"Ignore it because RAS/BRAF are wild type.","Ohne weitere Prüfung als sicher erworbene Resistenzmutation bezeichnen.":"Without further testing, call it a definitely acquired resistance mutation.","Unverändert nach Mammakarzinom-Regeln interpretieren.":"Interpret unchanged according to breast cancer rules.","HER2 ist entitätsspezifisch zu bestätigen und zu interpretieren; Baseline fehlt für eine sichere Akquisitionsaussage.":"HER2 must be confirmed and interpreted in an entity-specific manner; the lack of baseline prevents a definite acquisition statement.","Darf die HER2-Amplifikation als 'erworben unter Cetuximab' bezeichnet werden?":"Can the HER2 amplification be described as 'acquired under cetuximab'?","Nicht sicher. Ohne Baseline-HER2 kann sie präexistent gewesen oder unter Therapie selektiert/angereichert worden sein.":"Not with certainty. Without baseline HER2, it may have been pre-existing or selected/enriched under therapy.","Ja, weil sie erst beim Progress gemessen wurde.":"Yes, because it was only measured at progression.","Ja, weil RAS/BRAF Wildtyp sind.":"Yes, because RAS/BRAF are wild type.","Die zeitliche Einordnung ist für die Befundsprache irrelevant.":"The temporal classification is irrelevant to report wording.","Nachweiszeitpunkt und biologischer Entstehungszeitpunkt sind nicht identisch.":"Time of detection and biological time of emergence are not identical.","Erklären Sie zuerst, warum RAS/BRAF-Wildtyp im mCRC eine therapeutisch relevante 'negative' Information ist. Integrieren Sie danach die bestätigte HER2-Amplifikation in die Progressions- und Targetinterpretation, ohne Überinterpretation der Akquisition.":"First explain why RAS/BRAF wild type in mCRC is therapeutically relevant 'negative' information. Then integrate the confirmed HER2 amplification into progression and target interpretation without overcalling acquisition.","Linksseitigkeit und initialen RAS/BRAF-Wildtyp zusammen mit pMMR/MSS erfassen.":"Capture left-sidedness and initial RAS/BRAF wild type together with pMMR/MSS.","RAS/BRAF-Wildtyp als Selektionsvoraussetzung für anti-EGFR-Antikörper erklären, nicht als 'kein Befund'.":"Explain RAS/BRAF wild type as a selection prerequisite for anti-EGFR antibodies, not as 'no finding'.","Progress trotz Wildtyp als Hinweis auf alternative Resistenzmechanismen verstehen.":"Understand progression despite wild type as a clue to alternative resistance mechanisms.","ERBB2-Copy-number-Befund durch HER2-IHC/ISH bestätigen.":"Confirm the ERBB2 copy-number finding with HER2 IHC/ISH.","HER2 als Target- und möglichen anti-EGFR-Resistenzkontext berichten.":"Report HER2 as a target and possible anti-EGFR resistance context.","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher erworben.":"Without baseline HER2, do not claim the amplification is definitely acquired.","Validiertes breit angelegtes Progressionspanel mit zuverlässiger ERBB2-CNV-Erfassung plus orthogonale HER2-Bestätigung.":"Validated broad progression panel with reliable ERBB2 CNV detection plus orthogonal HER2 confirmation.","Bei nicht ausreichendem Gewebe ctDNA als ergänzender Resistenzansatz, sofern methodisch geeignet; negativer ctDNA-Befund würde Gewebe jedoch nicht automatisch ersetzen.":"If tissue is insufficient, ctDNA as a complementary resistance approach when methodologically appropriate; however, a negative ctDNA result would not automatically replace tissue.","'Alles negativ'":"'Everything negative'","RAS/BRAF-Wildtyp ist therapeutisch relevante Selektionsinformation.":"RAS/BRAF wild type is therapeutically relevant selection information.","Wildtyp = garantiert sensitiv":"Wild type = guaranteed sensitivity","Andere primäre oder sekundäre Resistenzmechanismen bleiben möglich.":"Other primary or secondary resistance mechanisms remain possible.","HER2 = sicher erworben":"HER2 = definitely acquired","Ohne Baseline-HER2 kann die zeitliche Entstehung nicht bewiesen werden.":"Without baseline HER2, the timing of emergence cannot be proven.","Nur MMR/MSI wiederholen":"Repeat only MMR/MSI","Der Status ist bereits bekannt und beantwortet die konkrete Progressionsfrage kaum.":"The status is already known and barely addresses the specific progression question.","Kein RAS/RAF-Resistenztreiber – dafür HER2 amplifiziert":"No RAS/RAF resistance driver – but HER2 amplified","Das Progressionspanel bleibt KRAS/NRAS/BRAF-Wildtyp. Genau dieser 'negative' Befund war initial therapeutisch hilfreich, erklärt aber den aktuellen Progress nicht. Die HER2-Bestätigung zeigt IHC 3+ und ERBB2-Amplifikation. Damit erscheint ein alternativer Signal-/Resistenzweg und zugleich ein neuer Targetkontext. Weil Baseline-HER2 fehlt, bleibt offen, ob die Amplifikation schon vorher vorhanden oder unter Therapie selektiert war.":"The progression panel remains KRAS/NRAS/BRAF wild type. Exactly this 'negative' result was therapeutically helpful initially, but it does not explain current progression. HER2 confirmation shows IHC 3+ and ERBB2 amplification. This reveals an alternative signaling/resistance pathway and, at the same time, a new target context. Because baseline HER2 is unavailable, it remains open whether the amplification was already present or selected under therapy.","Der Fall trennt drei Ebenen, die häufig vermischt werden: Selektionsmarker, Resistenzmechanismus und Target. 'Negativ' und 'positiv' sind therapeutisch kontextabhängige Begriffe.":"The case separates three levels that are often conflated: selection marker, resistance mechanism and target. 'Negative' and 'positive' are therapeutically context-dependent terms.","Wildtyp richtig gelesen + HER2 integriert":"Wild type read correctly + HER2 integrated","KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplifiziert. Anti-EGFR war im initialen linksseitigen WT-Kontext plausibel; HER2 ist nun ein relevanter Target-/Resistenzkontext. Akquisition nicht beweisbar.":"KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplified. Anti-EGFR was plausible in the initial left-sided WT context; HER2 is now a relevant target/resistance context. Acquisition cannot be proven.","Alle Ebenen sauber getrennt und integriert.":"All levels cleanly separated and integrated.","Wildtyp als 'negativ' abgehakt":"Wild type dismissed as 'negative'","RAS/BRAF WT wird nur als fehlender Befund erwähnt; HER2 wird zwar gefunden, aber die Selektionslogik bleibt unverstanden.":"RAS/BRAF WT is mentioned only as an absent finding; HER2 is found, but the selection logic remains misunderstood.","Zentrales Lernziel verfehlt.":"Core learning objective missed.","HER2 als sicher erworbene Resistenz bezeichnet":"HER2 labeled definitely acquired resistance","Kausalität/Akquisition wird ohne Baseline behauptet.":"Causality/acquisition is claimed without baseline.","Überinterpretation der zeitlichen Evidenz.":"Overinterpretation of temporal evidence.","HER2 bestätigt":"HER2 confirmed","HER2-gerichtete Therapieoptionen nach aktueller Zulassung/Leitlinie und Vorbehandlung im MTB prüfen.":"Review HER2-directed treatment options in the MTB according to current approval/guideline and prior treatment.","Der Progressionsbefund eröffnet eine neue therapeutische Achse.":"The progression finding opens a new therapeutic axis.","HER2 nicht bestätigt":"HER2 not confirmed","Alternative Resistenzmechanismen im Progressionsprofil/ctDNA/Gewebe prüfen.":"Assess alternative resistance mechanisms in the progression profile/ctDNA/tissue.","RAS/BRAF-Wildtyp allein erklärt den Progress weiterhin nicht.":"RAS/BRAF wild type alone still does not explain progression.","Beim mCRC kann ein negativer Mutationsbefund therapeutisch positiv sein.":"In mCRC, a negative mutation result can be therapeutically positive.","RAS/BRAF-Wildtyp ist Voraussetzung/Selektionsinformation für anti-EGFR, aber keine Garantie für Wirkung.":"RAS/BRAF wild type is a prerequisite/selection information for anti-EGFR, but not a guarantee of efficacy.","HER2-Amplifikation kann einen alternativen Target-/Resistenzkontext darstellen.":"HER2 amplification can represent an alternative target/resistance context.","Ohne Baseline darf 'erworben' nicht behauptet werden.":"Without baseline, 'acquired' must not be claimed.","Linksseitiges mCRC mit initial RAS/BRAF-WT/pMMR/MSS: der Wildtypstatus ist eine positive Selektionsinformation für anti-EGFR-Antikörper. Beim Progress bleibt RAS/BRAF WT, aber ERBB2 ist amplifiziert und HER2 bestätigt. HER2 als alternativen Target-/Resistenzkontext berichten; mangels Baseline nicht als sicher erworben bezeichnen.":"Left-sided mCRC with initial RAS/BRAF-WT/pMMR/MSS: wild-type status is positive selection information for anti-EGFR antibodies. At progression, RAS/BRAF remains WT, but ERBB2 is amplified and HER2 confirmed. Report HER2 as an alternative target/resistance context; without baseline, do not call it definitely acquired.","negativ=positiv-Konzept explizit verstanden":"'negative = positive' concept explicitly understood","WT nicht als Erfolgsgarantie":"WT not treated as guarantee of success","HER2 bestätigt und integriert":"HER2 confirmed and integrated","Akquisitionssprache begrenzt":"Acquisition wording appropriately limited","Warum sind Wildtypbefunde in der Onkologie oft therapeutisch hochinformativ?":"Why are wild-type findings often highly informative therapeutically in oncology?","Welche weiteren anti-EGFR-Resistenzmechanismen gibt es neben RAS/BRAF?":"Which other anti-EGFR resistance mechanisms exist besides RAS/BRAF?","Wie verändert ctDNA die Rechallenge-/Resistenzdiagnostik?":"How does ctDNA change rechallenge/resistance diagnostics?","RAS/BRAF WT bleibt, HER2 wird positiv":"RAS/BRAF remains WT, HER2 becomes positive","negativ kann therapeutisch positiv sein":"negative can be therapeutically positive","WT-Selektion → anti-EGFR → Progress → HER2-Amplifikation":"WT selection → anti-EGFR → progression → HER2 amplification","Mammakarzinom: BRCA/PIK3CA/ERBB2-Kontext → Klassische Marker vs. Panel-Zusatznutzen":"Breast cancer: BRCA/PIK3CA/ERBB2 context → Classic markers vs. added value of panel testing","Mammakarzinom: BRCA/PIK3CA/ERBB2-K…":"Breast cancer: BRCA/PIK3CA/ERBB2 c…","Gynäko-Onkologie / Molekulares Tumorboard":"Gynecologic oncology / Molecular tumor board","56-jährige Patientin mit sechs Jahre zuvor behandeltem invasivem Mammakarzinom; jetzt neu aufgetretene Leber- und Knochenmetastasen nach Progress unter endokriner Therapie plus CDK4/6-Inhibition.":"56-year-old woman with invasive breast cancer treated six years earlier; now new liver and bone metastases after progression on endocrine therapy plus CDK4/6 inhibition.","Welche klassischen prädiktiven Marker müssen an der Metastase erneut geklärt werden, und welchen zusätzlichen therapeutischen Nutzen liefern PIK3CA- sowie BRCA/HRR-Analysen?":"Which classic predictive markers must be reassessed in the metastasis, and what additional therapeutic value do PIK3CA and BRCA/HRR analyses provide?","Therapiewechsel soll im nächsten MTB festgelegt werden.":"Treatment change is to be defined at the next MTB.","Primärtumor vor 6 Jahren":"Primary tumor 6 years ago","ER 95 %, PgR 70 %, HER2 IHC 0; adjuvante Chemotherapie und anschließende endokrine Therapie.":"ER 95%, PgR 70%, HER2 IHC 0; adjuvant chemotherapy followed by endocrine therapy.","Metastasierte Situation":"Metastatic setting","Nach initialer Krankheitskontrolle unter Aromatasehemmer + CDK4/6-Inhibitor nun hepatischer Progress.":"After initial disease control with aromatase inhibitor + CDK4/6 inhibitor, now hepatic progression.","Familienanamnese":"Family history","Mutter mit Ovarialkarzinom im Alter von 63 Jahren; bisher keine dokumentierte humangenetische Abklärung.":"Mother with ovarian cancer at age 63; no documented genetic counseling/testing to date.","Ein breites Panel wird als Ersatz für die erneute Bestimmung der klassischen Tumorbiologie verstanden – oder ein Tumor-BRCA-Befund wird direkt als gesicherte Keimbahnmutation behandelt.":"A broad panel is understood as a substitute for reassessing classic tumor biology – or a tumor BRCA finding is directly treated as a proven germline mutation.","Metastasenbiopsie":"Metastatic biopsy","Adenokarzinom, morphologisch und immunhistochemisch vereinbar mit Mammakarzinommetastase.":"Adenocarcinoma morphologically and immunohistochemically consistent with breast cancer metastasis.","Rezeptorstatus Metastase":"Receptor status of metastasis","ER 80 %, PgR 5 %. HER2-IHC 2+ und damit für die klassische HER2-Statusbestimmung zunächst äquivok.":"ER 80%, PgR 5%. HER2 IHC 2+ and therefore initially equivocal for classic HER2 status assessment.","Offene molekulare Fragen":"Open molecular questions","PIK3CA als endokrin-targetierbarer Kontext; BRCA1/2/HRR wegen PARP- und hereditärer Fragestellung.":"PIK3CA as an endocrine-targetable context; BRCA1/2/HRR because of PARP and hereditary questions.","Kernproblem":"Core problem","Klassische Marker und Molekularpanel beantworten unterschiedliche Ebenen derselben Therapieentscheidung.":"Classic markers and molecular panels answer different levels of the same treatment decision.","FFPE-Leberbiopsie, Block L3.":"FFPE liver biopsy, block L3.","ca. 45 %, nach Makrodissektion gut geeignet.":"approx. 45%, well suited after macrodissection.","11 ungefärbte Schnitte; genug für gezielte IHC/ISH und fokussierte Molekulardiagnostik.":"11 unstained sections; enough for focused IHC/ISH and targeted molecular diagnostics.","DNA ausreichend; HER2-IHC technisch gut beurteilbar.":"DNA sufficient; HER2 IHC technically well evaluable.","Ein großes Pan-Panel verbraucht mehr Material, ersetzt aber weder die validierte HER2-IHC/ISH-Ebene noch die getrennte Keimbahnabklärung.":"A large pan-panel consumes more material but replaces neither the validated HER2 IHC/ISH level nor separate germline assessment.","HER2-Status der Metastase klären":"Clarify HER2 status of the metastasis","PIK3CA-Kontext":"PIK3CA context","Tumor-BRCA/HRR-Kontext":"Tumor BRCA/HRR context","HER2-Status":"HER2 status","HER2-IHC 2+; ERBB2-ISH/FISH ohne Amplifikation. Der Tumor ist damit nicht HER2-amplifiziert; die äquivoke IHC allein darf nicht als HER2-positiv überinterpretiert werden.":"HER2 IHC 2+; ERBB2 ISH/FISH without amplification. The tumor is therefore not HER2-amplified; equivocal IHC alone must not be overcalled as HER2-positive.","PIK3CA":"PIK3CA","PIK3CA p.H1047R, pathogen/aktivierend. Im HR-positiven, HER2-negativen metastasierten Kontext therapeutisch relevant abhängig von Vorbehandlung, Therapielinie und aktueller Zulassung/Leitlinie.":"PIK3CA p.H1047R, pathogenic/activating. Therapeutically relevant in HR-positive, HER2-negative metastatic disease depending on pretreatment, treatment line and current approval/guideline.","Tumor-BRCA/HRR":"Tumor BRCA/HRR","BRCA2-Frameshift-Variante mit Loss-of-function-Konsequenz, VAF 47 %. Der Tumorbefund kann eine therapeutisch und hereditär relevante Spur sein, beweist aber für sich keine Keimbahnmutation.":"BRCA2 frameshift variant with loss-of-function consequence, VAF 47%. The tumor finding may be a therapeutically and hereditarily relevant clue, but does not by itself prove a germline mutation.","Humangenetische Weiterleitung":"Genetic counseling referral","Humangenetische Beratung und Keimbahnabklärung werden empfohlen. Die hereditäre Einordnung erfolgt aus einer geeigneten Normalprobe und getrennt vom Tumor-only-Befund.":"Genetic counseling and germline testing are recommended. Hereditary classification is performed from an appropriate normal sample and separately from the tumor-only finding.","Rezeptorbiologie":"Receptor biology","ER 80 %, PgR 5 %; HER2-IHC 2+ an der Metastase.":"ER 80%, PgR 5%; HER2 IHC 2+ in the metastasis.","Metastasenbiopsie ausreichend für fokussierte IHC/ISH und Molekulardiagnostik.":"Metastatic biopsy sufficient for focused IHC/ISH and molecular diagnostics.","HR-positives metastasiertes Mammakarzinom mit HER2-IHC 2+, aber ohne ERBB2-Amplifikation. Zusätzlich liegt eine aktivierende PIK3CA-Mutation vor. Eine pathogene BRCA2-Loss-of-function-Variante wurde im Tumor gefunden; ihre Keimbahnherkunft ist aus der Tumoranalyse nicht ableitbar und muss separat humangenetisch geklärt werden. Klassische Rezeptor-/HER2-Diagnostik und molekulare Zusatzdiagnostik ergänzen sich und dürfen nicht gegeneinander ersetzt werden.":"HR-positive metastatic breast cancer with HER2 IHC 2+ but no ERBB2 amplification. In addition, an activating PIK3CA mutation is present. A pathogenic BRCA2 loss-of-function variant was found in the tumor; its germline origin cannot be inferred from tumor analysis and must be clarified separately through genetic counseling/testing. Classic receptor/HER2 diagnostics and additional molecular testing complement each other and must not be substituted for one another.","Teilbefund: Die molekularen Zusatzmarker sind nur im aktuellen ER/PgR/HER2-Kontext sinnvoll interpretierbar. Ein HER2-IHC-2+-Befund benötigt die validierte ISH/FISH-Klärung; ein Tumor-BRCA2-Befund ist nicht automatisch ein Keimbahnbefund.":"Partial finding: Additional molecular markers can only be interpreted meaningfully in the current ER/PgR/HER2 context. A HER2 IHC 2+ result requires validated ISH/FISH clarification; a tumor BRCA2 finding is not automatically a germline finding.","Aktuellen ER/PgR/HER2-Kontext der Metastase als Grundlage benennen":"State the current ER/PgR/HER2 context of the metastasis as the foundation","HER2 IHC 2+ durch ISH/FISH klären und nicht vorschnell als HER2-positiv bezeichnen":"Clarify HER2 IHC 2+ by ISH/FISH and do not prematurely call it HER2-positive","PIK3CA als zusätzlichen, therapielinienabhängigen Targetkontext integrieren":"Integrate PIK3CA as an additional treatment-line-dependent target context","Tumor-BRCA2 therapeutisch/hereditär relevant einordnen, Keimbahn aber separat klären":"Classify tumor BRCA2 as therapeutically/hereditarily relevant, but assess germline separately","Paneldiagnostik nicht als Ersatz für klassische Biomarker oder Humangenetik darstellen":"Do not present panel testing as a substitute for classic biomarkers or genetic counseling","Optimale Lösung: Metastasenbiologie zuerst korrekt mit ER/PgR/HER2 charakterisieren; HER2 2+ durch ISH als nicht amplifiziert klären; PIK3CA als zusätzliche therapeutische Information nutzen; pathogene Tumor-BRCA2-Variante als wichtige Spur berichten, aber Keimbahnstatus separat abklären.":"Optimal solution: First characterize metastatic biology correctly with ER/PgR/HER2; clarify HER2 2+ by ISH as non-amplified; use PIK3CA as additional therapeutic information; report the pathogenic tumor BRCA2 variant as an important clue, but assess germline status separately.","Mammakarzinom":"Breast cancer","HR+":"HR+","BRCA2":"BRCA2","Keimbahn":"Germline","PARP":"PARP","Klassische Marker zuerst, Panel danach: HER2 2+, PIK3CA und der Tumor-BRCA2-Twist":"Classic markers first, panel second: HER2 2+, PIK3CA and the tumor BRCA2 twist","Molekularpathologie / Gynäko-Onkologie / MTB":"Molecular pathology / Gynecologic oncology / MTB","Bei metastasiertem Mammakarzinom die aktuelle Tumorbiologie der Metastase einschließlich ER/PgR/HER2 als Grundlage der Systemtherapie verstehen.":"In metastatic breast cancer, understand the current biology of the metastasis including ER/PgR/HER2 as the foundation of systemic treatment.","HER2-IHC 2+ nicht als HER2-positiv überinterpretieren, sondern mit validierter ISH/FISH klären.":"Do not overinterpret HER2 IHC 2+ as HER2-positive; clarify with validated ISH/FISH.","PIK3CA als zusätzliche molekulare Therapieinformation im HR-positiven/HER2-negativen Kontext einordnen.":"Classify PIK3CA as additional molecular treatment information in the HR-positive/HER2-negative context.","Eine pathogene BRCA2-Variante aus Tumor-only-NGS von einer gesicherten Keimbahnmutation trennen.":"Distinguish a pathogenic BRCA2 variant from tumor-only NGS from a confirmed germline mutation.","Verstehen, dass Multigen-NGS klassische Biomarker ergänzt, aber nicht ersetzt.":"Understand that multigene NGS complements classic biomarkers but does not replace them.","Die Lebermetastase ist ER-positiv und HER2-IHC 2+. Parallel meldet das Panel eine aktivierende PIK3CA-Mutation und eine pathogene BRCA2-Frameshift-Variante. Im Tumorboard fallen sofort drei vermeintlich einfache Schlussfolgerungen: 'HER2-positiv', 'PIK3CA-targetierbar' und 'BRCA erblich'. Genau dieser Fall zeigt, warum alle drei Aussagen erst im richtigen diagnostischen Kontext belastbar werden.":"The liver metastasis is ER-positive and HER2 IHC 2+. In parallel, the panel reports an activating PIK3CA mutation and a pathogenic BRCA2 frameshift variant. Three apparently simple conclusions immediately arise in the tumor board: 'HER2-positive', 'PIK3CA-targetable' and 'BRCA hereditary'. This case shows exactly why all three statements become reliable only in the correct diagnostic context.","56-jährige Patientin mit HR-positivem Mammakarzinom und hepatischem Progress nach endokriner Therapie plus CDK4/6-Inhibition. Die aktuelle Metastasenbiopsie ist ER 80 %, PgR 5 % und HER2-IHC 2+. Gesucht wird eine integrierte Therapiebiologie aus klassischer HER2-Diagnostik, PIK3CA und BRCA/HRR, ohne die Grenzen von Tumor-only-NGS zu verwischen.":"56-year-old patient with HR-positive breast cancer and hepatic progression after endocrine therapy plus CDK4/6 inhibition. The current metastatic biopsy is ER 80%, PgR 5% and HER2 IHC 2+. The task is to derive an integrated treatment biology from classic HER2 diagnostics, PIK3CA and BRCA/HRR without blurring the limitations of tumor-only NGS.","Metastasenbiologie":"Metastatic biology","ER 80 %, PgR 5 %, HER2-IHC 2+.":"ER 80%, PgR 5%, HER2 IHC 2+.","Die aktuelle Metastase kann sich biologisch vom Primärtumor unterscheiden; klassische Marker bleiben Grundlage.":"The current metastasis may differ biologically from the primary tumor; classic markers remain fundamental.","Molekulare Zusatzebene":"Additional molecular layer","PIK3CA und BRCA/HRR sollen gezielt ergänzt werden.":"PIK3CA and BRCA/HRR should be added in a targeted manner.","Zusatznutzen entsteht erst im bekannten HR/HER2-Kontext.":"Added value arises only within the known HR/HER2 context.","Familienrelevanz":"Family relevance","Mutter mit Ovarialkarzinom; keine bisherige Humangenetik.":"Mother with ovarian cancer; no previous genetic counseling/testing.","Tumor-only kann einen Verdacht erzeugen, aber Keimbahn nicht beweisen.":"Tumor-only testing can raise suspicion but cannot prove germline origin.","Mammakarzinommetastase, ER 80 %, PgR 5 %, HER2-IHC 2+.":"Breast cancer metastasis, ER 80%, PgR 5%, HER2 IHC 2+.","Vor sechs Jahren ER/PgR stark positiv, HER2-IHC 0.":"Six years ago strongly ER/PgR-positive, HER2 IHC 0.","Leberbiopsie mit ca. 45 % Tumor; fokussierte IHC/ISH und NGS sind möglich.":"Liver biopsy with approximately 45% tumor; focused IHC/ISH and NGS are feasible.","Elf Schnitte erlauben eine fokussierte Diagnostik, aber unnötige Breitdiagnostik kostet Material.":"Eleven sections allow focused diagnostics, but unnecessary broad testing consumes material.","HER2-IHC 2+ benötigt eine validierte Amplifikationsabklärung; NGS ersetzt diesen diagnostischen Algorithmus nicht automatisch.":"HER2 IHC 2+ requires validated amplification testing; NGS does not automatically replace this diagnostic algorithm.","Eine Normalprobe für die Keimbahnabklärung ist in der Tumorpathologie nicht vorhanden.":"No normal sample for germline assessment is available in tumor pathology.","Was ist die wichtigste Grundlage, bevor PIK3CA/BRCA therapeutisch interpretiert werden?":"What is the most important basis before interpreting PIK3CA/BRCA therapeutically?","Die aktuelle ER/PgR/HER2-Biologie der Metastase muss belastbar feststehen; das Panel ergänzt diese Ebene.":"The current ER/PgR/HER2 biology of the metastasis must be reliably established; the panel complements this layer.","Ein ausreichend breites NGS-Panel ersetzt ER/PgR/HER2 vollständig.":"A sufficiently broad NGS panel completely replaces ER/PgR/HER2.","Der Rezeptorstatus des Primärtumors vor sechs Jahren reicht aus.":"The receptor status of the primary tumor six years ago is sufficient.","BRCA2 entscheidet unabhängig von HR/HER2 über die gesamte Therapie.":"BRCA2 determines the entire treatment independently of HR/HER2.","Beim metastasierten Mammakarzinom bleibt die aktuelle Tumorbiologie eine zentrale prädiktive Grundlage.":"In metastatic breast cancer, the current tumor biology remains a central predictive basis.","Die Metastase ist HER2-IHC 2+. Was bedeutet das?":"The metastasis is HER2 IHC 2+. What does this mean?","Äquivoker Befund: ERBB2-Amplifikation mit validierter ISH/FISH klären; IHC 2+ allein ist nicht gleich HER2-amplifiziert.":"Equivocal finding: clarify ERBB2 amplification with validated ISH/FISH; IHC 2+ alone does not equal HER2 amplification.","HER2-positiv, weitere Klärung unnötig.":"HER2-positive, no further clarification needed.","Sicher HER2-negativ, ISH ist nie erforderlich.":"Definitely HER2-negative; ISH is never required.","Nur die BRCA-Analyse entscheidet, HER2 ist irrelevant.":"Only BRCA analysis matters; HER2 is irrelevant.","IHC 2+ benötigt die etablierte Amplifikationsabklärung.":"IHC 2+ requires the established amplification work-up.","Tumor-NGS zeigt eine pathogene BRCA2-Frameshift-Variante mit VAF 47 %. Was darf daraus geschlossen werden?":"Tumor NGS shows a pathogenic BRCA2 frameshift variant with VAF 47%. What can be concluded?","Der Befund ist therapeutisch/hereditär relevant, aber Tumor-only beweist keine Keimbahnmutation; Humangenetik/Normalprobe separat klären.":"The finding is therapeutically/hereditarily relevant, but tumor-only testing does not prove a germline mutation; clarify separately by genetic counseling/normal sample.","VAF nahe 50 % beweist eine Keimbahnmutation.":"A VAF close to 50% proves a germline mutation.","Da die Probe Tumorgewebe ist, ist die Variante sicher rein somatisch.":"Because the sample is tumor tissue, the variant is definitely purely somatic.","Eine Frameshift-Variante ist automatisch eine VUS.":"A frameshift variant is automatically a VUS.","Tumor-VAF und selbst LOH trennen somatisch und Keimbahn nicht zuverlässig.":"Tumor VAF and even LOH do not reliably distinguish somatic from germline origin.","Wie ist der Zusatznutzen des Panels hier am besten beschrieben?":"How is the added value of the panel best described here?","PIK3CA/BRCA liefern zusätzliche therapie- und familienrelevante Information, ersetzen aber weder HER2-IHC/ISH noch die Keimbahnabklärung.":"PIK3CA/BRCA provide additional treatment- and family-relevant information but replace neither HER2 IHC/ISH nor germline assessment.","Das Panel macht klassische Biomarker und Humangenetik überflüssig.":"The panel makes classic biomarkers and genetic counseling unnecessary.","Molekulardiagnostik hat bei HR-positivem Mammakarzinom keinen Zusatznutzen.":"Molecular diagnostics add no value in HR-positive breast cancer.","Nur BRCA2 ist relevant; PIK3CA und HER2 können ignoriert werden.":"Only BRCA2 is relevant; PIK3CA and HER2 can be ignored.","Die Stärke liegt in der Integration komplementärer diagnostischer Ebenen.":"The strength lies in integrating complementary diagnostic layers.","Formulieren Sie eine integrierte MTB-Aussage, die den aktuellen HR/HER2-Status der Metastase, PIK3CA und die Tumor-BRCA2-Variante zusammenführt und klar trennt, welche Information unmittelbar tumorbezogen ist und welche eine separate Keimbahnabklärung erfordert.":"Formulate an integrated MTB statement that brings together the current HR/HER2 status of the metastasis, PIK3CA and the tumor BRCA2 variant, and clearly distinguishes which information is directly tumor-related and which requires separate germline assessment.","Aktuelle Metastasenbiologie mit ER/PgR/HER2 als Grundlage verwenden.":"Use the current metastatic biology with ER/PgR/HER2 as the foundation.","HER2-IHC 2+ durch ISH/FISH klären: keine ERBB2-Amplifikation.":"Clarify HER2 IHC 2+ by ISH/FISH: no ERBB2 amplification.","PIK3CA p.H1047R als zusätzlichen therapielinienabhängigen Targetkontext berichten.":"Report PIK3CA p.H1047R as an additional line-dependent target context.","Tumor-BRCA2-Loss-of-function als relevante molekulare Spur einordnen.":"Classify tumor BRCA2 loss-of-function as a relevant molecular clue.","Tumor-BRCA2 nicht als gesicherte Keimbahnmutation bezeichnen; humangenetische Beratung/Normalprobe empfehlen.":"Do not label tumor BRCA2 as a confirmed germline mutation; recommend genetic counseling/normal sample.","Therapieoptionen an aktuelle Zulassung, Vorbehandlung und Gesamtbiologie binden.":"Tie treatment options to current approval, prior therapy and overall biology.","Validiertes Multigenpanel zur kombinierten Erfassung von PIK3CA und BRCA/HRR, sofern HER2 weiterhin separat nach validiertem IHC/ISH-Algorithmus beurteilt wird.":"Validated multigene panel for combined detection of PIK3CA and BRCA/HRR, provided HER2 continues to be assessed separately using a validated IHC/ISH algorithm.","Gezielte PIK3CA-Analyse plus Tumor-BRCA/HRR-Panel, um Material und TAT zu schonen.":"Targeted PIK3CA analysis plus tumor BRCA/HRR panel to conserve material and TAT.","HER2 2+ = HER2-positiv":"HER2 2+ = HER2-positive","IHC 2+ ist äquivok und benötigt die Amplifikationsabklärung.":"IHC 2+ is equivocal and requires amplification assessment.","Tumor-BRCA2 = Keimbahn-BRCA2":"Tumor BRCA2 = germline BRCA2","Tumor-only-NGS kann die Herkunft nicht sicher bestimmen.":"Tumor-only NGS cannot reliably determine origin.","Pan-Panel ersetzt alles":"Pan-panel replaces everything","Klassische Protein-/Amplifikationsmarker und Humangenetik beantworten andere diagnostische Ebenen.":"Classic protein/amplification markers and germline genetics answer different diagnostic layers.","Primärtumorstatus reicht":"Primary tumor status is sufficient","Bei metastasierter Erkrankung kann eine Rebiopsie die aktuelle Tumorbiologie neu bewerten.":"In metastatic disease, re-biopsy can reassess the current tumor biology.","Zwei 'positive' Befunde – aber keiner bedeutet das, was der erste Blick suggeriert":"Two 'positive' findings – but neither means what the first glance suggests","HER2-IHC 2+ wird durch ISH als nicht amplifiziert geklärt. Gleichzeitig zeigt Tumor-NGS BRCA2 Loss-of-function bei VAF 47 %. Das klingt nach HER2-positiv plus erblichem BRCA-Syndrom – tatsächlich ist ersteres äquivok/nicht amplifiziert und letzteres zunächst ein Tumorbefund mit notwendiger separater Keimbahnklärung. Die klar tumorbezogene Zusatzinformation ist eine aktivierende PIK3CA-p.H1047R-Mutation.":"HER2 IHC 2+ is clarified by ISH as non-amplified. At the same time, tumor NGS shows BRCA2 loss-of-function at VAF 47%. This sounds like HER2-positive disease plus a hereditary BRCA syndrome – in reality, the first is equivocal/non-amplified and the second is initially a tumor finding requiring separate germline clarification. The clearly tumor-related additional information is an activating PIK3CA p.H1047R mutation.","Der Fall zwingt zur Trennung von Proteinexpression, Genamplifikation, somatischer Tumorgenetik und Keimbahnstatus – vier Ebenen, die therapeutisch miteinander interagieren, aber diagnostisch nicht austauschbar sind.":"The case forces separation of protein expression, gene amplification, somatic tumor genetics and germline status – four layers that interact therapeutically but are not diagnostically interchangeable.","Klassik und Molekularprofil integriert":"Classic markers and molecular profile integrated","ER 80 %, PgR 5 %, HER2-IHC 2+/ISH nicht amplifiziert; PIK3CA p.H1047R; pathogene BRCA2-Frameshift-Variante im Tumor. PIK3CA im aktuellen HR+/HER2-negativen Therapiekontext berücksichtigen; BRCA2 als relevante Tumorspur mit separater Keimbahnabklärung berichten.":"ER 80%, PgR 5%, HER2 IHC 2+/ISH non-amplified; PIK3CA p.H1047R; pathogenic BRCA2 frameshift variant in the tumor. Consider PIK3CA in the current HR+/HER2-negative treatment context; report BRCA2 as a relevant tumor finding with separate germline assessment.","Alle diagnostischen Ebenen korrekt getrennt und integriert.":"All diagnostic layers correctly separated and integrated.","Panel gut, klassische Ebene offen":"Panel good, classic layer unresolved","PIK3CA und BRCA2 werden gefunden, HER2-IHC 2+ aber nicht durch ISH geklärt.":"PIK3CA and BRCA2 are found, but HER2 IHC 2+ is not clarified by ISH.","Therapiebiologie bleibt unvollständig.":"Treatment biology remains incomplete.","HER2 und Keimbahn überinterpretiert":"HER2 and germline overinterpreted","HER2-IHC 2+ wird als HER2-positiv und Tumor-BRCA2 als sicher keimbahnpathogen bezeichnet.":"HER2 IHC 2+ is labeled HER2-positive and tumor BRCA2 as definitely germline pathogenic.","Zwei zentrale diagnostische Grenzüberschreitungen.":"Two major diagnostic boundary violations.","Tumor-BRCA2 pathologisch":"Tumor BRCA2 pathological","Humangenetische Beratung und Keimbahntestung aus geeigneter Normalprobe veranlassen.":"Arrange genetic counseling and germline testing from an appropriate normal sample.","Therapie- und Familienrelevanz werden getrennt, aber koordiniert weiterverfolgt.":"Treatment and family relevance are pursued separately but in a coordinated way.","HER2-ISH nicht amplifiziert":"HER2 ISH non-amplified","Therapieplanung im HR+/HER2-negativen Kontext fortsetzen und PIK3CA/weitere Linienmarker berücksichtigen.":"Continue treatment planning in the HR+/HER2-negative context and consider PIK3CA/other line-specific markers.","HER2-IHC 2+ wird nicht als Amplifikationspositivität fehlgedeutet.":"HER2 IHC 2+ is not misinterpreted as amplification positivity.","Beim metastasierten Mammakarzinom bleibt die aktuelle ER/PgR/HER2-Biologie zentral.":"In metastatic breast cancer, the current ER/PgR/HER2 biology remains central.","HER2-IHC 2+ ist ein Klärungsbefund, kein automatisches positives Endergebnis.":"HER2 IHC 2+ is a finding requiring clarification, not an automatically positive final result.","PIK3CA erweitert die therapeutische Information im passenden HR+/HER2-negativen Kontext.":"PIK3CA extends therapeutic information in the appropriate HR+/HER2-negative context.","Tumor-only BRCA kann klinisch hochrelevant sein, beweist aber keinen Keimbahnstatus.":"Tumor-only BRCA can be highly clinically relevant but does not prove germline status.","Multigen-NGS ergänzt klassische Pathologiemarker; es ersetzt sie nicht.":"Multigene NGS complements classic pathology markers; it does not replace them.","Aktuelle Metastasenbiologie zuerst: HR-positiv, HER2-IHC 2+, aber ISH nicht amplifiziert. PIK3CA p.H1047R ist als zusätzlicher therapeutischer Marker relevant. Die pathogene BRCA2-Frameshift-Variante stammt aus Tumor-only-NGS; sie darf nicht als Keimbahnmutation bezeichnet werden und löst eine separate humangenetische Abklärung aus.":"Current metastatic biology first: HR-positive, HER2 IHC 2+, but ISH non-amplified. PIK3CA p.H1047R is relevant as an additional therapeutic marker. The pathogenic BRCA2 frameshift variant comes from tumor-only NGS; it must not be called a germline mutation and triggers separate genetic assessment.","HER2 2+ korrekt geklärt":"HER2 2+ correctly clarified","PIK3CA im passenden Kontext integriert":"PIK3CA integrated in the appropriate context","Tumor vs. Keimbahn getrennt":"Tumor vs germline separated","Panel nicht als Ersatz klassischer Marker":"Panel not treated as a replacement for classic markers","Warum sollte die Metastase erneut auf ER/PgR/HER2 untersucht werden?":"Why should the metastasis be retested for ER/PgR/HER2?","Welche Aussage kann eine Tumor-VAF von etwa 50 % zur Keimbahnherkunft leisten – und welche nicht?":"What can a tumor VAF of about 50% tell us about germline origin – and what can it not tell us?","Wann ist ein breites Panel gegenüber fokussierter Diagnostik wirklich sinnvoll?":"When is a broad panel truly useful compared with focused diagnostics?","HER2 2+ nicht amplifiziert + Tumor-BRCA2 ist nicht automatisch Keimbahn":"HER2 2+ non-amplified + tumor BRCA2 does not automatically mean germline","Klassische Marker und Molekularprofil sind komplementär":"Classic markers and molecular profile are complementary","Metastasenbiologie → HER2-Klärung → PIK3CA/BRCA → Keimbahn separat":"Metastatic biology → HER2 clarification → PIK3CA/BRCA → germline separately","Metastasiertes Prostatakarzinom: HRR-Gene/MMR → PARP/IO/Studie und Keimbahnfrage":"Metastatic prostate cancer: HRR genes/MMR → PARP/IO/trial and germline question","Metastasiertes Prostatakarzinom: H…":"Metastatic prostate cancer: H…","Uro-Onkologie / Molekulares Tumorboard":"Uro-oncology / Molecular Tumor Board","69-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom und radiologischem Progress nach Androgendeprivation plus neuem hormonellen Wirkstoff.":"69-year-old patient with metastatic castration-resistant prostate cancer and radiologic progression after androgen-deprivation therapy plus a novel hormonal agent.","Gibt es einen HRR-/BRCA-Biomarker für eine PARP-Strategie? Besteht ein MMR/MSI-basierter Immuntherapiekontext? Muss eine Keimbahnabklärung folgen?":"Is there an HRR/BRCA biomarker for a PARP strategy? Is there an MMR/MSI-based immunotherapy context? Is germline evaluation required?","Therapieentscheidung in der kommenden Woche.":"Treatment decision next week.","Verlauf":"Clinical course","Initial lokal fortgeschrittenes Adenokarzinom; später ossäre und nodale Metastasierung, jetzt mCRPC.":"Initially locally advanced adenocarcinoma; later osseous and nodal metastases, now mCRPC.","ADT fortgeführt; Progress unter neuem hormonellem Wirkstoff.":"ADT continued; progression on a novel hormonal agent.","Auf dem ursprünglichen Anforderungsschein 'unauffällig'. Im Gespräch berichtet der Patient später von einem Bruder mit Pankreaskarzinom und einem Vater mit Prostatakarzinom.":"The original request form states 'unremarkable'. Later in conversation, the patient reports a brother with pancreatic cancer and a father with prostate cancer.","HRD-Score aus dem Ovarialkarzinom wird als universeller PARP-Test verwendet oder Tumor-BRCA und Keimbahnstatus werden gleichgesetzt.":"An ovarian-cancer HRD score is used as a universal PARP test, or tumor BRCA is equated with germline status.","Stanzbiopsie einer Lebermetastase mit hochgradigem Prostataadenokarzinom.":"Core biopsy of a liver metastasis with high-grade prostate adenocarcinoma.","NKX3.1/PSA-Kontext mit Prostataursprung vereinbar.":"NKX3.1/PSA context compatible with prostatic origin.","Klinische Frage":"Clinical question","Therapiebiomarker im mCRPC, nicht erneute Primärdiagnostik.":"Treatment biomarkers in mCRPC, not renewed primary diagnosis.","BRCA/HRR, MMR/MSI und hereditäre Einordnung.":"BRCA/HRR, MMR/MSI and hereditary classification.","ca. 55 %, ausreichend für NGS und MMR-IHC.":"approx. 55%, sufficient for NGS and MMR IHC.","DNA":"DNA","gute Qualität.":"good quality.","12 Schnitte.":"12 sections.","Methodenfalle":"Methodological pitfall","Ein unspezifischer HRD-Genomic-Scar-Score ist hier nicht der primäre etablierte Selektionsweg; gen-spezifische HRR/BRCA-Diagnostik und MMR/MSI beantworten die konkrete Frage direkter.":"A nonspecific HRD genomic-scar score is not the primary established selection pathway here; gene-specific HRR/BRCA diagnostics and MMR/MSI address the concrete question more directly.","Prostata-HRR/BRCA-Status":"Prostate HRR/BRCA status","MMR/MSI-Kontext":"MMR/MSI context","HRR/BRCA":"HRR/BRCA","Pathogene BRCA2-Frameshift-Variante im Tumor, VAF 58 %, mit zusätzlichem Verlust des Wildtypallels vereinbar. Im mCRPC ist BRCA1/2 unabhängig von somatischer oder Keimbahnherkunft ein relevanter PARP-Biomarkerkontext; die konkrete Therapie richtet sich nach Vorbehandlung und aktueller Zulassung/Leitlinie.":"Pathogenic BRCA2 frameshift variant in the tumor, VAF 58%, compatible with additional loss of the wild-type allele. In mCRPC, BRCA1/2 irrespective of somatic or germline origin provides a relevant PARP biomarker context; actual treatment depends on prior therapy and current approval/guidelines.","Erhaltene Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Preserved expression of MLH1, PMS2, MSH2 and MSH6: pMMR.","MSS / kein MSI-H. Damit ergibt sich aus MMR/MSI in diesem Fall kein spezifischer IO-Biomarkerkontext.":"MSS / no MSI-H. Thus, MMR/MSI provides no specific IO biomarker context in this case.","HRD-Score":"HRD score","Ein Genomic-Scar/HRD-Score liefert im Prostatakarzinom keine gleichwertige, etablierte Ersatzinformation für die gen-spezifische BRCA/HRR-Diagnostik. Er darf den BRCA2-Befund nicht überstimmen oder eine negative HRR-Analyse ersetzen.":"A genomic-scar/HRD score in prostate cancer does not provide equivalent established replacement information for gene-specific BRCA/HRR diagnostics. It must not override the BRCA2 finding or replace a negative HRR analysis.","Keimbahnabklärung":"Germline assessment","Humangenetische Beratung/Keimbahntestung wird aufgrund der pathogenen BRCA2-Variante und der Familienanamnese empfohlen. Tumor-only VAF und LOH beweisen die Keimbahnherkunft nicht.":"Genetic counseling/germline testing is recommended because of the pathogenic BRCA2 variant and family history. Tumor-only VAF and LOH do not prove germline origin.","Klinischer Status":"Clinical status","mCRPC mit Progress nach neuem hormonellen Wirkstoff.":"mCRPC with progression after a novel hormonal agent.","Metastasenbiopsie mit ausreichendem Tumoranteil für HRR- und MMR-Diagnostik.":"Metastatic biopsy with sufficient tumor content for HRR and MMR testing.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und Hinweis auf biallelische Inaktivierung; pMMR/MSS. Der BRCA2-Befund eröffnet einen PARP-relevanten Therapiekontext gemäß aktueller Indikation/Vorbehandlung. Die Tumoranalyse unterscheidet somatisch und Keimbahn nicht sicher; wegen BRCA2 und Familienanamnese ist eine separate humangenetische Keimbahnabklärung angezeigt. Ein HRD-Score ist kein notwendiger Ersatz für diese gen-spezifische Prostata-Diagnostik.":"mCRPC with pathogenic BRCA2 loss-of-function alteration and evidence compatible with biallelic inactivation; pMMR/MSS. The BRCA2 finding opens a PARP-relevant treatment context according to current indication/prior therapy. Tumor testing cannot reliably distinguish somatic from germline origin; because of BRCA2 and the family history, separate germline assessment through genetics is indicated. An HRD score is not a necessary substitute for this gene-specific prostate diagnostic approach.","Teilbefund: HRR/BRCA, MMR/MSI und Keimbahnfrage müssen getrennt beantwortet werden. Ein tumor-only BRCA2-Befund kann therapeutisch relevant sein, sagt aber nicht automatisch, ob die Variante vererbt ist.":"Partial result: HRR/BRCA, MMR/MSI and the germline question must be answered separately. A tumor-only BRCA2 finding can be therapeutically relevant but does not automatically indicate whether the variant is inherited.","BRCA2 im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen":"Classify BRCA2 in mCRPC as a gene-specific PARP biomarker context","pMMR/MSS als fehlenden MMR/MSI-basierten IO-Selektionsbefund kommunizieren":"Communicate pMMR/MSS as absence of an MMR/MSI-based IO selection finding","Tumor-BRCA2 nicht mit Keimbahn gleichsetzen; Humangenetik empfehlen":"Do not equate tumor BRCA2 with germline; recommend genetic counseling","HRD-Score nicht als universellen oder zwingenden Prostata-PARP-Selektionsmarker darstellen":"Do not present the HRD score as a universal or mandatory prostate PARP selection marker","Therapieempfehlung an aktuelle Zulassung, Vorbehandlung und klinischen Kontext binden":"Tie treatment recommendation to current approval, prior therapy and clinical context","Optimale Lösung: BRCA2 im Tumor als therapeutisch relevanten mCRPC-Biomarker erkennen, pMMR/MSS separat für den IO-Kontext dokumentieren, HRD-Score nicht aus dem Ovarial-Workflow übertragen und die Keimbahnfrage wegen möglicher Familienrelevanz eigenständig humangenetisch klären.":"Optimal solution: recognize tumor BRCA2 as a therapeutically relevant mCRPC biomarker, document pMMR/MSS separately for the IO context, do not transfer the HRD score from the ovarian workflow, and clarify the germline question independently through genetics because of potential family relevance.","Prostatakarzinom":"Prostate cancer","mCRPC":"mCRPC","HRR":"HRR","MMR":"MMR","BRCA2 im mCRPC: therapeutisch relevant – aber ist es auch Keimbahn?":"BRCA2 in mCRPC: therapeutically relevant – but is it also germline?","Molekularpathologie / Uro-Onkologie / MTB":"Molecular pathology / Uro-oncology / MTB","BRCA1/2- und HRR-Alterationen im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen.":"Classify BRCA1/2 and HRR alterations in mCRPC as a gene-specific PARP biomarker context.","Somatische und Keimbahn-BRCA-Alterationen therapeutisch und hereditär getrennt betrachten.":"Consider somatic and germline BRCA alterations separately from therapeutic and hereditary perspectives.","MMR/MSI als eigenständigen IO-Biomarkerblock prüfen.":"Assess MMR/MSI as an independent IO biomarker block.","Einen ovarialkarzinomtypischen HRD-Genomic-Scar-Score nicht als universellen Pflichtmarker auf das Prostatakarzinom übertragen.":"Do not transfer an ovarian-cancer-type HRD genomic-scar score to prostate cancer as a universal mandatory marker.","Familienanamnese und humangenetische Weiterleitung in die MTB-Empfehlung integrieren.":"Integrate family history and genetic referral into the MTB recommendation.","Das Tumorpanel meldet eine pathogene BRCA2-Frameshift-Variante mit VAF 58 % und Hinweis auf Verlust des zweiten Allels. Im MTB heißt es sofort: 'Dann ist das erblich – und wir brauchen noch einen HRD-Score, bevor PARP möglich ist.' Der Fall ist ideal, um zwei häufige Ebenenfehler gleichzeitig zu korrigieren.":"The tumor panel reports a pathogenic BRCA2 frameshift variant with VAF 58% and evidence of loss of the second allele. In the MTB someone immediately says: 'Then it's hereditary – and we still need an HRD score before PARP is possible.' The case is ideal for correcting two common category errors at the same time.","69-jähriger Patient mit mCRPC und Progress nach neuem hormonellem Wirkstoff. Eine Lebermetastasenbiopsie steht für HRR/BRCA- und MMR/MSI-Diagnostik zur Verfügung. Gesucht wird eine Therapieempfehlung, die den tumorbezogenen BRCA2-Befund nutzt, die Keimbahnfrage separat löst und keine Ovarial-HRD-Logik auf die Prostata überträgt.":"69-year-old patient with mCRPC and progression after a novel hormonal agent. A liver metastasis biopsy is available for HRR/BRCA and MMR/MSI testing. The goal is a treatment recommendation that uses the tumor BRCA2 finding, resolves the germline question separately and does not transfer ovarian HRD logic to prostate cancer.","Therapiesituation":"Treatment setting","mCRPC nach Progress unter neuem hormonellem Wirkstoff.":"mCRPC after progression on a novel hormonal agent.","Der konkrete Therapiekontext macht BRCA1/2 besonders relevant.":"The specific treatment context makes BRCA1/2 particularly relevant.","Hereditäre Ebene":"Hereditary layer","Bruder mit Pankreas- und Vater mit Prostatakarzinom werden erst im Gespräch bekannt.":"A brother with pancreatic cancer and a father with prostate cancer are only reported during the consultation.","Familienanamnese verstärkt die Keimbahnindikation, ersetzt aber keine Testung.":"Family history strengthens the indication for germline testing but does not replace testing.","IO-Ebene":"IO layer","MMR/MSI ist zu Beginn unbekannt.":"MMR/MSI is unknown at the start.","DNA-Reparaturdefekt allgemein ist nicht gleich dMMR/MSI-H.":"A DNA repair defect in general is not equivalent to dMMR/MSI-H.","Lebermetastase, ca. 55 % Tumor; DNA und IHC gut auswertbar.":"Liver metastasis, approx. 55% tumor; DNA and IHC are readily evaluable.","mCRPC mit Progress nach neuem hormonellem Wirkstoff.":"mCRPC with progression after a novel hormonal agent.","Im Verlauf Pankreas- und Prostatakarzinom bei nahen Angehörigen berichtet.":"Pancreatic and prostate cancer in close relatives reported during the course.","Gen-spezifische HRR/BRCA-Diagnostik hat für die konkrete Frage höhere Priorität als ein unspezifischer HRD-Genomic-Scar-Score.":"Gene-specific HRR/BRCA testing has higher priority for this question than a nonspecific HRD genomic-scar score.","Tumorgewebe enthält keine saubere Normalreferenz für die Keimbahnfrage.":"Tumor tissue does not provide a clean normal reference for the germline question.","MMR/MSI benötigt eine eigene funktionelle/biomarkerbezogene Beurteilung.":"MMR/MSI requires its own functional/biomarker assessment.","Was ist der zentrale PARP-Biomarkerbefund in diesem Fall?":"What is the central PARP biomarker finding in this case?","Die pathogene BRCA2-Alteration im mCRPC ist der entscheidende gen-spezifische Biomarkerkontext; die konkrete Nutzung hängt von Vorbehandlung und aktueller Indikation ab.":"The pathogenic BRCA2 alteration in mCRPC is the decisive gene-specific biomarker context; actual use depends on prior therapy and current indication.","Nur ein positiver HRD-Score erlaubt eine PARP-Strategie.":"Only a positive HRD score permits a PARP strategy.","pMMR ist der entscheidende PARP-Biomarker.":"pMMR is the decisive PARP biomarker.","Eine VAF über 50 % ist allein der therapeutische Biomarker.":"A VAF above 50% alone is the therapeutic biomarker.","Bei mCRPC ist die gen-spezifische BRCA1/2-Alteration zentral; ein Ovarial-HRD-Score ist kein universeller Ersatz.":"In mCRPC, the gene-specific BRCA1/2 alteration is central; an ovarian HRD score is not a universal substitute.","Tumor-BRCA2, VAF 58 %, mit LOH: Ist damit die Keimbahnherkunft bewiesen?":"Tumor BRCA2, VAF 58%, with LOH: does this prove germline origin?","Nein. Der Tumorbefund kann therapeutisch relevant sein, aber die Keimbahnherkunft muss aus einer geeigneten Normalprobe separat geklärt werden.":"No. The tumor finding can be therapeutically relevant, but germline origin must be assessed separately using an appropriate normal sample.","Ja, VAF >50 % beweist Keimbahn.":"Yes, VAF >50% proves germline origin.","Ja, LOH beweist immer eine erbliche Variante.":"Yes, LOH always proves an inherited variant.","Nein, Tumorvarianten können grundsätzlich nie Keimbahn sein.":"No, tumor variants can never be germline.","Tumor-only-NGS trennt somatische und Keimbahnherkunft nicht sicher.":"Tumor-only NGS cannot reliably distinguish somatic from germline origin.","Reicht eine HRR/BRCA-Alteration als Begründung für eine MMR/MSI-basierte Immuntherapie?":"Is an HRR/BRCA alteration sufficient to justify MMR/MSI-based immunotherapy?","Nein. MMR/MSI ist ein separater Biomarkerblock; hier zeigt pMMR/MSS keinen spezifischen MSI-basierten IO-Kontext.":"No. MMR/MSI is a separate biomarker block; here pMMR/MSS provides no specific MSI-based IO context.","Ja. Jede DNA-Reparaturmutation bedeutet immunogen und ICI-sensitiv.":"Yes. Any DNA repair mutation means immunogenic and ICI-sensitive.","BRCA2 ist funktionell gleichbedeutend mit MSI-H.":"BRCA2 is functionally equivalent to MSI-H.","Nur PD-L1 kann die Frage beantworten.":"Only PD-L1 can answer the question.","HRR und MMR sind unterschiedliche Reparaturachsen mit unterschiedlichen Biomarkerfolgen.":"HRR and MMR are different repair pathways with different biomarker consequences.","Welche Rolle sollte der HRD-Score hier spielen?":"What role should the HRD score play here?","Nicht als Pflicht- oder Ersatzmarker: gen-spezifische BRCA/HRR-Diagnostik ist für diesen Prostatafall entscheidender.":"Not as a mandatory or replacement marker: gene-specific BRCA/HRR diagnostics are more decisive for this prostate case.","Zwingend vor jeder PARP-Diskussion.":"Mandatory before every PARP discussion.","Er ersetzt die Keimbahnabklärung.":"It replaces germline assessment.","Er entscheidet primär über Immuntherapie.":"It primarily determines immunotherapy.","Der Ovarial-HRD-Workflow darf nicht unkritisch auf mCRPC übertragen werden.":"The ovarian HRD workflow must not be transferred uncritically to mCRPC.","Ordnen Sie BRCA2, MMR/MSI und die Keimbahnfrage beim mCRPC so ein, dass die therapeutische Relevanz des Tumorbefunds genutzt wird, ohne die hereditäre Herkunft zu behaupten oder einen HRD-Score unnötig zur Voraussetzung zu machen.":"Classify BRCA2, MMR/MSI and the germline question in mCRPC so that the therapeutic relevance of the tumor finding is used without claiming hereditary origin or making an HRD score an unnecessary prerequisite.","Validierte HRR/BRCA-Diagnostik am Tumor durchführen.":"Perform validated tumor HRR/BRCA testing.","Pathogene BRCA2-Loss-of-function-Alteration als relevanten mCRPC-Biomarkerkontext berichten.":"Report pathogenic BRCA2 loss-of-function alteration as a relevant mCRPC biomarker context.","MMR-IHC/MSI separat prüfen: pMMR/MSS.":"Assess MMR IHC/MSI separately: pMMR/MSS.","PARP-Option an aktuelle Indikation, Vorbehandlung und klinische Eignung binden.":"Tie the PARP option to current indication, prior therapy and clinical suitability.","Keimbahnherkunft aus Tumor-VAF/LOH nicht ableiten; Humangenetik/Normalprobe empfehlen.":"Do not infer germline origin from tumor VAF/LOH; recommend genetics/normal sample.","HRD-Score nicht als universellen Pflichtmarker aus dem Ovarialkarzinom übernehmen.":"Do not adopt the HRD score from ovarian cancer as a universal mandatory marker.","Validiertes Tumor-BRCA/HRR-Panel statt Prostata-spezifischem Panel, sofern relevante HRR-Gene und Copy-number/Variantentypen ausreichend erfasst werden.":"Validated tumor BRCA/HRR panel rather than a prostate-specific panel, provided relevant HRR genes and copy-number/variant types are adequately covered.","Breiteres validiertes Panel mit BRCA/HRR plus MSI, wenn Material und TAT vertretbar sind; funktionelle MMR-IHC kann ergänzen.":"Broader validated panel including BRCA/HRR plus MSI if material and TAT are acceptable; functional MMR IHC can complement it.","HRD-Score als Pflicht":"HRD score as mandatory","Überträgt einen entitätsspezifischen Ovarial-Workflow auf die Prostata.":"Transfers an entity-specific ovarian workflow to prostate cancer.","Tumor-BRCA = erblich":"Tumor BRCA = hereditary","Tumor-only-NGS beweist keine Keimbahnherkunft.":"Tumor-only NGS does not prove germline origin.","BRCA = MSI/IO":"BRCA = MSI/IO","HRR und MMR sind verschiedene Reparaturwege und Biomarker.":"HRR and MMR are different repair pathways and biomarkers.","Familienanamnese ignorieren":"Ignore family history","Ein möglicher Keimbahnbefund hat Konsequenzen für Patient und Angehörige.":"A possible germline finding has consequences for the patient and relatives.","Therapie kann schon tumorbezogen relevant sein, Familienrelevanz bleibt trotzdem offen":"Treatment can already be relevant at tumor level while family relevance remains unresolved","Die BRCA2-Loss-of-function-Alteration ist im mCRPC therapeutisch relevant, auch wenn sie somatisch sein könnte. Gleichzeitig macht die aktualisierte Familienanamnese eine Keimbahnabklärung besonders wichtig. MMR-IHC und MSI sind unauffällig. Der vermeintlich noch fehlende HRD-Score ist dagegen gar nicht der zentrale nächste Schritt.":"The BRCA2 loss-of-function alteration is therapeutically relevant in mCRPC even if it could be somatic. At the same time, the updated family history makes germline assessment particularly important. MMR IHC and MSI are unremarkable. The supposedly still-missing HRD score, however, is not the central next step at all.","Der Fall trennt Therapiebiomarker und Hereditätsdiagnostik: dieselbe Variante kann für die Tumortherapie relevant sein, während ihre Herkunft für die Familie separat geklärt werden muss.":"The case separates treatment biomarkers from hereditary diagnostics: the same variant can be relevant for tumor treatment while its origin must be clarified separately for the family.","BRCA2 genutzt, Keimbahn sauber getrennt":"BRCA2 used, germline cleanly separated","Pathogene BRCA2-Loss-of-function-Alteration im Tumor mit Hinweis auf biallelische Inaktivierung; pMMR/MSS. PARP-relevanter mCRPC-Kontext gemäß aktueller Indikation/Vorbehandlung; separate humangenetische Keimbahnabklärung empfohlen. HRD-Score nicht als Pflichtmarker benötigt.":"Pathogenic BRCA2 loss-of-function alteration in the tumor with evidence compatible with biallelic inactivation; pMMR/MSS. PARP-relevant mCRPC context according to current indication/prior therapy; separate germline assessment by genetics recommended. HRD score not required as a mandatory marker.","Therapie-, IO- und Hereditätsebene korrekt getrennt.":"Treatment, IO and hereditary layers correctly separated.","BRCA2 erkannt, Heredität offen":"BRCA2 recognized, heredity unresolved","BRCA2 wird therapeutisch korrekt erkannt, aber Keimbahnabklärung/Familienrelevanz nicht adressiert.":"BRCA2 is correctly recognized therapeutically, but germline assessment/family relevance is not addressed.","Klinisch wichtige zweite Ebene fehlt.":"A clinically important second layer is missing.","Ovarial-Workflow kopiert":"Ovarian workflow copied","PARP-Entscheidung wird von einem HRD-Score abhängig gemacht und Tumor-BRCA2 zugleich als sicher erblich bezeichnet.":"The PARP decision is made dependent on an HRD score while tumor BRCA2 is simultaneously labeled definitely hereditary.","Zwei entitätsspezifische Fehlübertragungen.":"Two entity-specific misapplications.","Pathogene BRCA2-Variante im Tumor":"Pathogenic BRCA2 variant in the tumor","PARP-Eignung nach aktueller Indikation/Vorbehandlung prüfen und parallel humangenetische Beratung veranlassen.":"Assess PARP eligibility according to current indication/prior therapy and arrange genetic counseling in parallel.","Therapieentscheidung und Familienabklärung laufen koordiniert, aber diagnostisch getrennt.":"Treatment decision and family assessment proceed in a coordinated but diagnostically separate manner.","Keinen MSI/MMR-basierten IO-Biomarker behaupten; andere klinische IO-Indikationen nur separat bewerten.":"Do not claim an MSI/MMR-based IO biomarker; assess other clinical IO indications separately only.","DNA-Reparatur wird nicht pauschal mit Immuntherapie gleichgesetzt.":"DNA repair is not equated broadly with immunotherapy.","BRCA1/2 ist im mCRPC ein gen-spezifischer, therapeutisch relevanter Biomarkerkontext.":"BRCA1/2 is a gene-specific, therapeutically relevant biomarker context in mCRPC.","Somatische und Keimbahn-BRCA-Alterationen sind für Therapie und Familie unterschiedliche Ebenen.":"Somatic and germline BRCA alterations represent different layers for treatment and family.","Tumor-VAF/LOH beweist die Keimbahn nicht.":"Tumor VAF/LOH does not prove germline origin.","MMR/MSI muss unabhängig von HRR beurteilt werden.":"MMR/MSI must be assessed independently of HRR.","Ein HRD-Genomic-Scar-Score ist kein universeller Pflichtmarker für PARP über Tumorentitäten hinweg.":"An HRD genomic-scar score is not a universal mandatory marker for PARP across tumor entities.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und pMMR/MSS. BRCA2 ist tumorbezogen PARP-relevant gemäß aktueller Indikation/Vorbehandlung. Die Keimbahnherkunft ist nicht aus Tumor-VAF oder LOH ableitbar; wegen Befund und Familienanamnese Humangenetik empfehlen. Kein obligatorischer Ovarial-HRD-Score.":"mCRPC with pathogenic BRCA2 loss-of-function alteration and pMMR/MSS. BRCA2 is tumor-level PARP-relevant according to current indication/prior therapy. Germline origin cannot be inferred from tumor VAF or LOH; recommend genetics because of the finding and family history. No mandatory ovarian HRD score.","BRCA2 tumorbezogen korrekt genutzt":"Tumor BRCA2 used correctly","MMR/MSI separat bewertet":"MMR/MSI assessed separately","Keimbahn nicht behauptet":"Germline not claimed","HRD-Score nicht zum Pflichtmarker gemacht":"HRD score not made mandatory","Warum kann derselbe BRCA2-Befund therapeutisch nutzbar sein, obwohl die Keimbahnherkunft noch offen ist?":"Why can the same BRCA2 finding be therapeutically usable even while germline origin remains unresolved?","Welche Proben eignen sich zur Keimbahnklärung?":"Which samples are suitable for clarifying germline status?","Warum sind HRD-Genomic-Scar-Tests nicht automatisch zwischen Tumorentitäten übertragbar?":"Why are HRD genomic-scar tests not automatically transferable between tumor entities?","BRCA2 ist therapeutisch relevant, ohne dass die Keimbahn bereits geklärt ist":"BRCA2 is therapeutically relevant without germline status already being clarified","Therapiebiomarker und Hereditätsstatus sind getrennte Ebenen":"Treatment biomarker and hereditary status are separate layers","HRR/BRCA → MMR/MSI separat → PARP-Kontext → Keimbahnklärung":"HRR/BRCA → MMR/MSI separately → PARP context → germline clarification","Therapieassoziierte MDS/AML nach DNA-schädigender Therapie → Instabilität als Chance und Risiko einordnen":"Therapy-related MDS/AML after DNA-damaging therapy → classify instability as opportunity and risk","Therapieassoziierte MDS/AML nach D…":"Therapy-related MDS/AML after D…","Hämatologie / interdisziplinäres Tumorboard":"Hematology / Interdisciplinary Tumor Board","67-jährige Patientin mit neu aufgetretener Pancytopenie acht Jahre nach Behandlung eines Mammakarzinoms mit zytotoxischer Chemotherapie und Radiotherapie.":"67-year-old patient with newly developed pancytopenia eight years after treatment of breast cancer with cytotoxic chemotherapy and radiotherapy.","Wie werden Morphologie, Zytogenetik, molekulares Profil und die frühere zytotoxische Therapie zu einer belastbaren Diagnose- und Risikoeinschätzung integriert?":"How should morphology, cytogenetics, molecular profile and prior cytotoxic therapy be integrated into a robust diagnostic and risk assessment?","Therapiebeginn nach Abschluss der hämatologischen Klassifikation.":"Treatment starts after completion of hematologic classification.","Anthrazyklin-/Cyclophosphamid-haltige Chemotherapie und Bestrahlung vor acht Jahren.":"Anthracycline/cyclophosphamide-containing chemotherapy and radiotherapy eight years ago.","Aktuell":"Current findings","Hb 8,4 g/dl, Thrombozyten 46/nl, Neutrophile 0,7/nl; peripher 9 % Blasten.":"Hb 8.4 g/dL, platelets 46/nL, neutrophils 0.7/nL; peripheral blood 9% blasts.","Knochenmark":"Bone marrow","27 % myeloische Blasten, ausgeprägte Dysplasie.":"27% myeloid blasts, marked dysplasia.","Die Vorgeschichte wird allein zur Diagnose 'therapieassoziierte AML' gemacht oder ein einzelner DNMT3A-/TET2-/ASXL1-Befund wird ohne Morphologie/Zytogenetik als Neoplasiebeweis interpretiert.":"The history alone is used to diagnose 'therapy-related AML', or a single DNMT3A/TET2/ASXL1 finding is interpreted as proof of neoplasia without morphology/cytogenetics.","Morphologie + Vorbefunde":"Morphology + prior findings","Hyperzellulär, 27 % Blasten, dysplastische Granulo- und Megakaryopoese.":"Hypercellular, 27% blasts, dysplastic granulopoiesis and megakaryopoiesis.","Zytogenetik":"Cytogenetics","Komplexer Karyotyp mit -5/del(5q), -7 und 17p-Verlust.":"Complex karyotype with -5/del(5q), -7 and 17p loss.","Akute myeloische Neoplasie mit hochriskanter Genominstabilität; frühere zytotoxische Exposition muss als qualifizierender Kontext integriert werden.":"Acute myeloid neoplasm with high-risk genomic instability; prior cytotoxic exposure must be integrated as qualifying context.","Welche Rolle spielt das molekulare Profil – und was darf daraus gerade nicht abgeleitet werden?":"What role does the molecular profile play – and what must specifically not be inferred from it?","EDTA-Knochenmarkaspirat plus Trepanobiopsie.":"EDTA bone marrow aspirate plus trephine biopsy.","Tumorzellanteil":"Tumor cell content","Blasten ca. 27 %; NGS aus Knochenmark geeignet.":"Blasts approx. 27%; bone marrow suitable for NGS.","Vorbefunde":"Prior findings","Morphologie und Zytogenetik liegen bereits vor und dürfen nicht durch NGS ersetzt werden.":"Morphology and cytogenetics are already available and must not be replaced by NGS.","Ein Pan-Tumorpanel mit TMB/MSI wäre für die konkrete myeloische Klassifikationsfrage Low Value; das fokussierte hämatologische Panel ist näher an der Fragestellung.":"A pan-tumor panel with TMB/MSI would be low value for the specific myeloid classification question; a focused hematologic panel is closer to the clinical question.","Myeloischer Molekularkontext":"Myeloid molecular context","Hämatologisches NGS":"Hematologic NGS","TP53 p.R273H mit VAF 43 % sowie DNMT3A p.R882H mit VAF 4 %. Im Kontext von 17p-Verlust und komplexem Karyotyp ist TP53 Teil der hochriskanten Neoplasie; die niedrigfrequente DNMT3A-Alteration allein wäre dagegen kein Beweis für AML und kann klonale Hämatopoese repräsentieren.":"TP53 p.R273H with VAF 43% and DNMT3A p.R882H with VAF 4%. In the context of 17p loss and a complex karyotype, TP53 is part of the high-risk neoplasm; the low-frequency DNMT3A alteration alone, however, would not prove AML and may represent clonal hematopoiesis.","Zusätzliche solide-tumororientierte TMB/MSI-/Pan-Cancer-Information beantwortet die zentrale myeloische Klassifikations- und Risikofrage nicht besser und erzeugt unnötige Nebenbefunde.":"Additional solid-tumor-oriented TMB/MSI/pan-cancer information does not better answer the central myeloid classification and risk question and creates unnecessary incidental findings.","Morphologie":"Morphology","27 % myeloische Blasten mit Dysplasie.":"27% myeloid blasts with dysplasia.","Exposition":"Exposure","Zytotoxische Chemotherapie/Radiotherapie acht Jahre zuvor.":"Cytotoxic chemotherapy/radiotherapy eight years previously.","Akute myeloische Neoplasie mit TP53-Alteration und komplexer Zytogenetik nach vorausgegangener zytotoxischer Therapie. Die frühere Therapie ist ein wichtiger qualifizierender klinischer Kontext, die Erkrankung wird jedoch primär aus Morphologie und genetischen Merkmalen klassifiziert. Der TP53/komplexe-Karyotyp-Kontext spricht für ungünstige Biologie. Eine niedrigfrequente DNMT3A-Alteration allein wäre nicht ausreichend, um die Neoplasie zu definieren. 'Genomische Instabilität' ist hier kein pauschales Target- oder Immuntherapiesignal.":"Acute myeloid neoplasm with TP53 alteration and complex cytogenetics after prior cytotoxic therapy. Prior treatment is an important qualifying clinical context, but the disease is classified primarily by morphology and genetic features. The TP53/complex-karyotype context indicates adverse biology. A low-frequency DNMT3A alteration alone would not be sufficient to define the neoplasm. 'Genomic instability' is not a blanket target or immunotherapy signal here.","Teilbefund: Die frühere zytotoxische Therapie erhöht die Plausibilität eines post-zytotoxischen/therapiebezogenen Kontextes, ersetzt aber nicht die aktuelle morphologische und genetische Klassifikation. CHIP-typische Varianten dürfen nicht isoliert überinterpretiert werden.":"Partial result: prior cytotoxic therapy increases the plausibility of a post-cytotoxic/therapy-related context but does not replace current morphologic and genetic classification. CHIP-typical variants must not be overinterpreted in isolation.","Morphologie/Genetik priorisieren und frühere zytotoxische Therapie als qualifizierenden Kontext integrieren":"Prioritize morphology/genetics and integrate prior cytotoxic therapy as qualifying context","TP53 plus komplexen Karyotyp als hochriskante Biologie erkennen":"Recognize TP53 plus complex karyotype as high-risk biology","Niedrigfrequentes DNMT3A nicht allein als AML-Beweis interpretieren":"Do not interpret low-frequency DNMT3A alone as proof of AML","Genominstabilität nicht automatisch als Target-/TMB-/IO-Chance verkaufen":"Do not automatically sell genomic instability as a target/TMB/IO opportunity","Hämatologische Klassifikation und Risikostratifikation nicht durch ein solides Pan-Panel ersetzen":"Do not replace hematologic classification and risk stratification with a solid-tumor pan-panel","Optimale Lösung: AML/myeloische Neoplasie aus Morphologie und Genetik klassifizieren; die frühere zytotoxische Therapie als qualifizierenden Kontext dokumentieren; TP53 plus komplexe Zytogenetik als ungünstige Biologie einordnen; niedrigfrequentes DNMT3A als potenziellen CH-Klon nicht überbewerten.":"Optimal solution: classify AML/myeloid neoplasm from morphology and genetics; document prior cytotoxic therapy as qualifying context; classify TP53 plus complex cytogenetics as adverse biology; do not overvalue low-frequency DNMT3A, which may represent a CH clone.","AML":"AML","post cytotoxic therapy":"post cytotoxic therapy","TP53":"TP53","complex karyotype":"complex karyotype","clonal hematopoiesis":"clonal hematopoiesis","genomic instability":"genomic instability","Nach zytotoxischer Therapie: TP53, komplexer Karyotyp und die Falle 'Genominstabilität = Target'":"After cytotoxic therapy: TP53, complex karyotype and the trap 'genomic instability = target'","Molekularpathologie / Hämatologie / Translation":"Molecular pathology / Hematology / Translation","Eine myeloische Neoplasie nach zytotoxischer Therapie primär aus aktueller Morphologie und Genetik klassifizieren und die frühere Exposition als qualifizierenden Kontext integrieren.":"Classify a myeloid neoplasm after cytotoxic therapy primarily from current morphology and genetics and integrate prior exposure as qualifying context.","TP53 plus komplexe Zytogenetik als hochriskante Biologie erkennen.":"Recognize TP53 plus complex cytogenetics as high-risk biology.","CHIP-typische Varianten wie niedrigfrequentes DNMT3A nicht isoliert als AML-Beweis interpretieren.":"Do not interpret CHIP-typical variants such as low-frequency DNMT3A in isolation as proof of AML.","Das biologische Konzept 'genomische Instabilität' nicht automatisch in einen therapeutischen Target- oder Immuntherapiemarker übersetzen.":"Do not automatically translate the biological concept 'genomic instability' into a therapeutic target or immunotherapy marker.","Solide-tumororientierte Pan-Cancer-Tests nicht unkritisch auf eine myeloische Fragestellung übertragen.":"Do not uncritically transfer solid-tumor-oriented pan-cancer tests to a myeloid question.","Acht Jahre nach Chemotherapie und Bestrahlung wegen Mammakarzinoms entwickelt die Patientin eine Pancytopenie. Das Knochenmark zeigt 27 % Blasten, der Karyotyp ist komplex. Im NGS erscheinen TP53 mit hoher und DNMT3A mit sehr niedriger VAF. Im Board fallen zwei schnelle Erklärungen: 'Die alte Chemotherapie hat die AML verursacht' und 'viel Genominstabilität bedeutet vielleicht viel Target-/IO-Potenzial'. Beide Aussagen müssen präziser werden.":"Eight years after chemotherapy and radiotherapy for breast cancer, the patient develops pancytopenia. Bone marrow shows 27% blasts and the karyotype is complex. NGS reveals TP53 at high VAF and DNMT3A at very low VAF. Two quick explanations arise in the board: 'The old chemotherapy caused the AML' and 'a lot of genomic instability may mean lots of target/IO potential.' Both statements need greater precision.","67-jährige Patientin mit akuter myeloischer Neoplasie nach vorausgegangener zytotoxischer Therapie. Morphologie und komplexe Zytogenetik stehen bereits fest; das molekulare Panel soll die biologische Einordnung ergänzen. Ziel ist nicht, aus einer Exposition oder einem Einzelgen allein eine Diagnose zu konstruieren, sondern die aktuelle Erkrankung korrekt zu klassifizieren und die Genominstabilität klinisch realistisch zu bewerten.":"67-year-old patient with an acute myeloid neoplasm after prior cytotoxic therapy. Morphology and complex cytogenetics are already established; the molecular panel should complement biological classification. The goal is not to construct a diagnosis from an exposure or single gene alone, but to correctly classify the current disease and assess genomic instability realistically in clinical terms.","27 % myeloische Blasten mit deutlicher Dysplasie.":"27% myeloid blasts with marked dysplasia.","Die aktuelle Neoplasie ist morphologisch manifest; NGS ersetzt diese Ebene nicht.":"The current neoplasm is morphologically manifest; NGS does not replace this layer.","Mehrere strukturelle Verluste sprechen für hochriskante klonale Genominstabilität.":"Multiple structural losses indicate high-risk clonal genomic instability.","Zytotoxische Chemotherapie und Radiotherapie acht Jahre zuvor.":"Cytotoxic chemotherapy and radiotherapy eight years previously.","Wichtiger diagnostischer Qualifier/Kontext, aber nicht die alleinige Krankheitsdefinition.":"Important diagnostic qualifier/context, but not the sole disease definition.","Blutbild":"Blood count","Pancytopenie, peripher 9 % Blasten.":"Pancytopenia, peripheral blood 9% blasts.","27 % Blasten, dysplastische Myelopoese.":"27% blasts, dysplastic myelopoiesis.","Karyotyp":"Karyotype","Komplex mit -5/del(5q), -7 und 17p-Verlust.":"Complex with -5/del(5q), -7 and 17p loss.","Knochenmark ist für fokussiertes hämatologisches NGS geeignet.":"Bone marrow is suitable for focused hematologic NGS.","Morphologie und Zytogenetik sind bereits hochinformativ und dürfen nicht durch einen molekularen Einzelmarker ersetzt werden.":"Morphology and cytogenetics are already highly informative and must not be replaced by a single molecular marker.","Ein solides Pan-Cancer-Panel mit TMB/MSI erzeugt für diese Fragestellung eher Nebeninformation als klinischen Mehrwert.":"A solid-tumor pan-cancer panel with TMB/MSI would generate more incidental information than clinical value for this question.","Wie sollte die frühere zytotoxische Therapie diagnostisch verwendet werden?":"How should prior cytotoxic therapy be used diagnostically?","Als wichtiger qualifizierender Kontext einer anhand aktueller morphologischer/genetischer Merkmale klassifizierten myeloischen Neoplasie.":"As an important qualifying context for a myeloid neoplasm classified by current morphologic/genetic features.","Allein die Exposition definiert unabhängig von aktuellen Befunden automatisch die AML-Untergruppe.":"Exposure alone automatically defines the AML subgroup regardless of current findings.","Die frühere Therapie darf in der Diagnose überhaupt nicht erwähnt werden.":"Prior therapy must not be mentioned in the diagnosis at all.","Sie ist primär ein therapeutischer Target-Biomarker.":"It is primarily a therapeutic target biomarker.","Moderne Klassifikation priorisiert die aktuelle Krankheitsbiologie; die Exposition wird als relevanter Kontext/Qualifier integriert.":"Modern classification prioritizes current disease biology; exposure is integrated as relevant context/qualifier.","Wie ist TP53 VAF 43 % zusammen mit 17p-Verlust und komplexem Karyotyp zu bewerten?":"How should TP53 VAF 43% together with 17p loss and a complex karyotype be assessed?","Als Teil einer hochriskanten TP53-/komplex-karyotypischen Krankheitsbiologie, nicht als isolierter Einzelmarker.":"As part of high-risk TP53/complex-karyotype disease biology, not as an isolated single marker.","Als einfacher Targetmarker mit erwartbar günstiger Prognose.":"As a simple target marker with expected favorable prognosis.","Sicher nur CHIP, weil TP53 auch in klonaler Hämatopoese vorkommen kann.":"Definitely only CHIP because TP53 can also occur in clonal hematopoiesis.","Zytogenetik macht molekulare Befunde irrelevant.":"Cytogenetics makes molecular findings irrelevant.","Genetischer Kontext und klonale Architektur sind entscheidend.":"Genetic context and clonal architecture are decisive.","DNMT3A p.R882H liegt zusätzlich mit 4 % VAF vor. Was ist die beste Interpretation?":"DNMT3A p.R882H is additionally present at 4% VAF. What is the best interpretation?","Ein niedrigfrequenter CH-Klon ist möglich; DNMT3A allein beweist weder AML noch erklärt es die gesamte hochriskante Erkrankung.":"A low-frequency CH clone is possible; DNMT3A alone proves neither AML nor explains the entire high-risk disease.","DNMT3A definiert allein die AML.":"DNMT3A alone defines AML.","4 % VAF beweist eine Keimbahnmutation.":"4% VAF proves a germline mutation.","DNMT3A ist ein PARP-Biomarker.":"DNMT3A is a PARP biomarker.","CHIP-typische Gene müssen im morphologischen und klonalen Kontext interpretiert werden.":"CHIP-typical genes must be interpreted in morphologic and clonal context.","Was bedeutet die ausgeprägte Genominstabilität therapeutisch?":"What does the marked genomic instability mean therapeutically?","Sie erklärt aggressive klonale Evolution/Risikobiologie, ist aber kein pauschaler TMB-, IO- oder Targetmarker; konkrete Alterationen und hämatologische Evidenz entscheiden.":"It explains aggressive clonal evolution/risk biology but is not a blanket TMB, IO or target marker; specific alterations and hematologic evidence determine treatment.","Viele Aberrationen bedeuten automatisch hohe Immuntherapie-Sensitivität.":"Many aberrations automatically mean high immunotherapy sensitivity.","Komplexer Karyotyp ist automatisch eine PARP-Indikation.":"A complex karyotype automatically indicates PARP.","Mehr Instabilität bedeutet generell bessere Targetierbarkeit und Prognose.":"More instability generally means better targetability and prognosis.","Ein biologisches Hallmark ist nicht identisch mit einem validierten klinischen Biomarker.":"A biological hallmark is not identical to a validated clinical biomarker.","Integrieren Sie frühere zytotoxische Therapie, Morphologie, komplexen Karyotyp und TP53/DNMT3A so, dass Diagnose-/Risikokontext und Grenzen des Begriffs 'genomische Instabilität' klar werden.":"Integrate prior cytotoxic therapy, morphology, complex karyotype and TP53/DNMT3A so that diagnostic/risk context and the limits of the term 'genomic instability' become clear.","Aktuelle myeloische Neoplasie aus Morphologie und Genetik einordnen.":"Classify the current myeloid neoplasm from morphology and genetics.","Vorausgegangene zytotoxische Therapie als relevanten post-zytotoxischen/therapiebezogenen Qualifier dokumentieren.":"Document prior cytotoxic therapy as a relevant post-cytotoxic/therapy-related qualifier.","TP53 zusammen mit 17p-Verlust und komplexem Karyotyp als hochriskanten biologischen Kontext bewerten.":"Assess TP53 together with 17p loss and complex karyotype as a high-risk biological context.","Niedrigfrequentes DNMT3A nicht isoliert als AML-definierend interpretieren.":"Do not interpret low-frequency DNMT3A in isolation as AML-defining.","Keine pauschale PARP-/IO-/TMB-Logik aus 'Genominstabilität' ableiten.":"Do not infer blanket PARP/IO/TMB logic from 'genomic instability'.","Hämatologiespezifische Diagnostik gegenüber einem Pan-Cancer-Panel priorisieren.":"Prioritize hematology-specific diagnostics over a pan-cancer panel.","Ein umfassenderes validiertes myeloisches NGS-Panel wäre für reale Routinediagnostik sinnvoll, sofern Morphologie, Immunphänotyp und Zytogenetik integriert bleiben.":"A more comprehensive validated myeloid NGS panel would be appropriate in real routine diagnostics, provided morphology, immunophenotype and cytogenetics remain integrated.","Bei unklarer klonaler Architektur kann eine geeignete Verlauf-/Vorprobe helfen, präexistente klonale Hämatopoese von dominanter Leukämieklonalität abzugrenzen.":"If clonal architecture is unclear, an appropriate follow-up/prior sample can help distinguish pre-existing clonal hematopoiesis from dominant leukemia clonality.","Exposition = Diagnose":"Exposure = diagnosis","Die frühere Therapie ist Kontext/Qualifier; aktuelle Morphologie und Genetik definieren die Erkrankung.":"Prior therapy is context/qualifier; current morphology and genetics define the disease.","DNMT3A = AML":"DNMT3A = AML","CHIP-typische Varianten können ohne manifeste Neoplasie vorkommen und brauchen Kontext.":"CHIP-typical variants can occur without overt neoplasia and require context.","Genominstabilität = IO/PARP":"Genomic instability = IO/PARP","Hallmark und validierter prädiktiver Biomarker sind nicht dasselbe.":"Hallmark and validated predictive biomarker are not the same thing.","Pan-Cancer-TMB/MSI":"Pan-cancer TMB/MSI","Für die konkrete myeloische Klassifikationsfrage ist dies kein sinnvoller Primäransatz.":"This is not a useful primary approach for the specific myeloid classification question.","Der kleine DNMT3A-Klon ist nicht die Geschichte – TP53 plus Karyotyp ist es":"The small DNMT3A clone is not the story – TP53 plus karyotype is","Das Panel zeigt DNMT3A p.R882H nur mit 4 % VAF, daneben TP53 p.R273H mit 43 %. Zusammen mit 17p-Verlust und komplexem Karyotyp ist TP53 Teil der dominanten hochriskanten Krankheitsbiologie. DNMT3A kann dagegen einen kleineren, möglicherweise präexistierenden CH-Klon markieren. Die 'vielen genetischen Schäden' sind hier vor allem Risikosignatur – nicht automatisch therapeutische Verwundbarkeit.":"The panel shows DNMT3A p.R882H at only 4% VAF, alongside TP53 p.R273H at 43%. Together with 17p loss and a complex karyotype, TP53 is part of the dominant high-risk disease biology. DNMT3A, by contrast, may mark a smaller, possibly pre-existing CH clone. The 'many genetic lesions' here are primarily a risk signature – not automatically a therapeutic vulnerability.","Der Fall zeigt, dass Mutationsnamen ohne Klonstärke, Zytogenetik, Morphologie und klinischen Kontext leicht in die falsche Richtung führen.":"The case shows how mutation names without clone size, cytogenetics, morphology and clinical context can easily point in the wrong direction.","Klonale Architektur und Exposition integriert":"Clonal architecture and exposure integrated","Akute myeloische Neoplasie mit TP53-Alteration und komplexem Karyotyp nach zytotoxischer Therapie. TP53/17p/komplexer Karyotyp = hochriskanter dominanter Kontext; DNMT3A 4 % VAF potenziell CH-Klon. Keine pauschale Target-/IO-Aussage aus Genominstabilität.":"Acute myeloid neoplasm with TP53 alteration and complex karyotype after cytotoxic therapy. TP53/17p/complex karyotype = dominant high-risk context; DNMT3A 4% VAF potentially CH clone. No blanket target/IO statement from genomic instability.","Morphologie, Genetik, Exposition und Klonalität korrekt zusammengeführt.":"Morphology, genetics, exposure and clonality correctly integrated.","Therapieassoziiert erkannt, Genetik zu grob":"Therapy-related context recognized, genetics too coarse","Die frühere Chemotherapie wird korrekt erwähnt, aber TP53 und DNMT3A werden gleichgewichtet und der komplexe Karyotyp bleibt unterbewertet.":"Prior chemotherapy is correctly mentioned, but TP53 and DNMT3A are weighted equally and the complex karyotype is undervalued.","Klonale und prognostische Hierarchie fehlt.":"Clonal and prognostic hierarchy is missing.","Instabilität als Therapiechance verkauft":"Instability sold as treatment opportunity","Komplexer Karyotyp und TP53 werden als unspezifischer Hinweis auf hohe TMB/IO- oder PARP-Sensitivität interpretiert.":"Complex karyotype and TP53 are interpreted as a nonspecific indication of high TMB/IO or PARP sensitivity.","Hallmark wurde fälschlich zum prädiktiven Biomarker gemacht.":"A hallmark was incorrectly turned into a predictive biomarker.","TP53 + komplexer Karyotyp bestätigt":"TP53 + complex karyotype confirmed","Hämatologische Risikostratifikation und Therapieplanung entsprechend der hochriskanten Krankheitsbiologie durchführen.":"Perform hematologic risk stratification and treatment planning according to the high-risk disease biology.","Die Priorität liegt auf korrekter Klassifikation/Risiko- und Therapieplanung, nicht auf unspezifischem Pan-Cancer-Targeting.":"The priority is correct classification/risk and treatment planning, not nonspecific pan-cancer targeting.","niedrigfrequente CH-typische Variante":"low-frequency CH-typical variant","Nur im Kontext interpretieren; bei Bedarf Verlauf/Vorproben zur Klonhistorie heranziehen.":"Interpret only in context; if needed use follow-up/prior samples to assess clonal history.","CHIP und manifeste Neoplasie werden nicht verwechselt.":"CHIP and overt neoplasia are not confused.","Post-zytotoxische/therapiebezogene Vorgeschichte ist ein wichtiger Qualifier, nicht die alleinige Definition der aktuellen myeloischen Erkrankung.":"Post-cytotoxic/therapy-related history is an important qualifier, not the sole definition of the current myeloid disease.","TP53 plus komplexer Karyotyp kennzeichnet hochriskante Biologie.":"TP53 plus complex karyotype characterizes high-risk biology.","Niedrige VAF in CHIP-typischen Genen kann eine kleinere Begleitklonalität darstellen.":"Low VAF in CHIP-typical genes can represent a smaller accompanying clone.","Genomische Instabilität ist ein Hallmark, aber kein universeller Target- oder Immuntherapiemarker.":"Genomic instability is a hallmark, but not a universal target or immunotherapy biomarker.","Hämatologische Diagnostik muss Morphologie, Zytogenetik und Molekulargenetik integrieren.":"Hematologic diagnostics must integrate morphology, cytogenetics and molecular genetics.","Akute myeloische Neoplasie nach zytotoxischer Therapie mit dominanter TP53-/komplex-karyotypischer Hochrisikobiologie. Die Exposition wird als Qualifier integriert. DNMT3A bei 4 % VAF kann eine kleinere CH-Klonalität repräsentieren und definiert die AML nicht. Aus Genominstabilität folgt keine pauschale PARP-/IO-Indikation.":"Acute myeloid neoplasm after cytotoxic therapy with dominant TP53/complex-karyotype high-risk biology. Exposure is integrated as a qualifier. DNMT3A at 4% VAF may represent a smaller CH clone and does not define AML. Genomic instability does not imply a blanket PARP/IO indication.","Exposition als Qualifier statt Alleindefinition":"Exposure as qualifier rather than sole definition","TP53/komplexer Karyotyp priorisiert":"TP53/complex karyotype prioritized","DNMT3A niedrig-VAF nicht überinterpretiert":"Low-VAF DNMT3A not overinterpreted","Hallmark ≠ klinischer Biomarker":"Hallmark ≠ clinical biomarker","Warum sind Therapiegeschichte und aktuelle Genetik beide wichtig, aber nicht austauschbar?":"Why are treatment history and current genetics both important but not interchangeable?","Wie hilft die VAF bei der Interpretation möglicher CH-Klone?":"How does VAF help interpret possible CH clones?","Welche zusätzlichen Untersuchungen gehören real zur AML-Klassifikation, obwohl dieser Simulatorfall den Fokus enger setzt?":"Which additional tests genuinely belong to AML classification even though this simulator case has a narrower focus?","DNMT3A low-VAF ist Nebenklon; TP53 plus komplexer Karyotyp dominiert":"Low-VAF DNMT3A is a minor clone; TP53 plus complex karyotype dominates","Genominstabilität ist Risikobiologie, nicht automatisch Target":"Genomic instability is risk biology, not automatically a target","Exposition → Morphologie/Zytogenetik → TP53/DNMT3A-Klonalität → Risikokontext":"Exposure → morphology/cytogenetics → TP53/DNMT3A clonality → risk context","„Cold Tumor“ mit wenig TILs und dichter Stromabarriere → Warum ist PD-1 allein wahrscheinlich schwach?":"'Cold tumor' with few TILs and a dense stromal barrier → Why is PD-1 alone likely to be weak?","„Cold Tumor“ mit wenig TILs und di…":"'Cold tumor' with few TILs and den…","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach systemischer Erstlinientherapie. Ein externer Zusatzbefund nennt PD-L1 TPS 15 % und löst die Frage nach einer PD-1-Monotherapie aus.":"64-year-old patient with metastatic pancreatic ductal adenocarcinoma and progression after first-line systemic therapy. An external supplementary report cites PD-L1 TPS 15% and triggers the question of PD-1 monotherapy.","Ist die PD-L1-Expression hier ein belastbarer Hinweis auf Checkpoint-Sensitivität – oder spricht das gesamte Tumor-Immune-Milieu eher dagegen?":"Is PD-L1 expression here a robust sign of checkpoint sensitivity – or does the overall tumor-immune milieu argue against it?","Die Zweitlinienstrategie soll im nächsten MTB festgelegt werden.":"The second-line strategy is to be determined at the next MTB.","Krankheitsverlauf":"Disease course","Primär lokal fortgeschritten, später hepatische Metastasierung; nun radiologischer Progress.":"Initially locally advanced, later hepatic metastasis; now radiologic progression.","Systemische Standardtherapie, insgesamt gute Belastbarkeit; keine bekannte Autoimmunerkrankung.":"Systemic standard therapy, overall good performance status; no known autoimmune disease.","Externer Impuls":"External prompt","PD-L1 TPS 15 % wird im Zuweiserbrief als 'positiv – Immuntherapie möglich?' markiert.":"PD-L1 TPS 15% is marked in the referral letter as 'positive – immunotherapy possible?'.","Ein exprimierter Checkpoint wird mit bereits vorhandener effektiver Antitumor-Immunität gleichgesetzt.":"An expressed checkpoint is equated with pre-existing effective antitumor immunity.","Duktales Adenokarzinom mit ausgeprägter desmoplastischer Stromareaktion.":"Ductal adenocarcinoma with marked desmoplastic stromal reaction.","Immunmorphologie":"Immune morphology","Nur wenige intraepitheliale Lymphozyten; Immunzellen liegen überwiegend stromal/peritumoral.":"Only a few intraepithelial lymphocytes; immune cells are predominantly stromal/peritumoral.","PD-L1 Vorbefund":"Prior PD-L1 result","TPS 15 %, technisch plausibel und reproduzierbar.":"TPS 15%, technically plausible and reproducible.","MMR/MSI, TMB sowie räumlicher TIL-/Stromakontext.":"MMR/MSI, TMB and spatial TIL/stromal context.","FFPE-Lebermetastase, Block M4.":"FFPE liver metastasis, block M4.","ca. 35 %, nach Makrodissektion ausreichend.":"approx. 35%, sufficient after macrodissection.","10 Schnitte; fokussierte IHC plus DNA-basierte Zusatzdiagnostik möglich.":"10 sections; focused IHC plus DNA-based additional testing is possible.","Explorative TME-Marker können die Biologie illustrieren, sind aber kein validierter Ersatz für etablierte prädiktive Marker.":"Exploratory TME markers can illustrate the biology but are not a validated substitute for established predictive markers.","Etablierte immunonkologische Biomarker":"Established immuno-oncology biomarkers","TIL-/TME-Kontext":"TIL/TME context","MMR-Proteine erhalten; molekular MSS. Es liegt damit kein dMMR/MSI-H-Kontext als etablierter starker ICI-Biomarker vor.":"MMR proteins retained; molecularly MSS. Thus, there is no dMMR/MSI-H context as an established strong ICI biomarker.","TMB niedrig (3,2 Mut/Mb). Der Wert liefert in diesem Fall keinen zusätzlichen Hinweis auf eine ausgeprägte Neoantigenlast.":"TMB low (3.2 Mut/Mb). In this case, the value provides no additional indication of a high neoantigen burden.","PD-L1 TPS 15 % wird bestätigt. Der Befund ist real, darf beim Pankreasadenokarzinom aber nicht isoliert als ausreichender Selektionsmarker für PD-1-Monotherapie interpretiert werden.":"PD-L1 TPS 15% is confirmed. The finding is real, but in pancreatic adenocarcinoma it must not be interpreted in isolation as a sufficient selection marker for PD-1 monotherapy.","Immuninfiltrat":"Immune infiltrate","CD8-positive T-Zellen sind insgesamt spärlich und überwiegend stromal/peritumoral; nur wenige erreichen Tumorzellnester.":"CD8-positive T cells are sparse overall and predominantly stromal/peritumoral; only a few reach tumor cell nests.","Stromakontext":"Stromal context","Ausgeprägte desmoplastische, fibroblastenreiche Stromazone mit immune-excluded Muster. Der Befund illustriert eine physische/biologische Barriere, ist aber kein eigenständig validierter Therapie-Selektionsassay.":"Marked desmoplastic, fibroblast-rich stromal zone with an immune-excluded pattern. This illustrates a physical/biological barrier but is not an independently validated treatment-selection assay.","Ausgeprägt desmoplastisches Pankreasadenokarzinom mit wenig intratumoralen Lymphozyten.":"Markedly desmoplastic pancreatic adenocarcinoma with few intratumoral lymphocytes.","IHC und DNA-basierte Analysen technisch auswertbar.":"IHC and DNA-based analyses technically evaluable.","Metastasiertes duktales Pankreasadenokarzinom mit bestätigter PD-L1-Expression, jedoch pMMR/MSS, niedriger TMB und deutlich immune-excluded/desmoplastischem Mikromilieu. PD-L1 allein begründet hier keine belastbare PD-1-Monotherapie-Strategie. TIL-/Stromamarker erklären die biologische Plausibilität eines 'cold/excluded' Tumors, sind aber selbst keine validierten Selektionsmarker.":"Metastatic pancreatic ductal adenocarcinoma with confirmed PD-L1 expression, but pMMR/MSS, low TMB and a clearly immune-excluded/desmoplastic microenvironment. PD-L1 alone does not provide a robust basis for a PD-1 monotherapy strategy here. TIL/stromal markers explain the biological plausibility of a 'cold/excluded' tumor, but are not themselves validated selection markers.","Teilbefund: PD-L1 ist exprimiert, aber ohne MMR/MSI/TMB- und räumlichen TIL-Kontext bleibt die Aussage zur Checkpoint-Sensitivität unvollständig.":"Partial result: PD-L1 is expressed, but without MMR/MSI/TMB and spatial TIL context, the statement on checkpoint sensitivity remains incomplete.","PD-L1 als Kontextmarker, nicht als alleinige Therapieentscheidung behandeln":"Treat PD-L1 as a contextual marker, not as the sole treatment decision","pMMR/MSS und niedrige TMB als fehlende starke ICI-Signale benennen":"Identify pMMR/MSS and low TMB as absence of strong ICI signals","immune-excluded/desmoplastisches Muster biologisch erklären":"Explain the immune-excluded/desmoplastic pattern biologically","TME-IHC nicht als validierten Therapie-Selektionsassay verkaufen":"Do not present TME IHC as a validated treatment-selection assay","Falschaussage: PD-L1-Positivität beweist eine ausreichende Effektor-T-Zell-Antwort":"False statement: PD-L1 positivity proves an adequate effector T-cell response","Optimale Lösung: PD-L1 15 % nicht isoliert interpretieren; pMMR/MSS, niedrige TMB und das immune-excluded/desmoplastische Muster integrieren. Die TME-Befunde erklären die biologische Barriere, ersetzen aber keine klinisch validierten Biomarker oder leitliniengerechte Therapieentscheidung.":"Optimal solution: do not interpret PD-L1 15% in isolation; integrate pMMR/MSS, low TMB and the immune-excluded/desmoplastic pattern. The TME findings explain the biological barrier but do not replace clinically validated biomarkers or guideline-based treatment decisions.","Pankreasadenokarzinom":"Pancreatic adenocarcinoma","TMB-low":"TMB-low","TILs":"TILs","TME":"TME","Desmoplasie":"Desmoplasia","Immune exclusion":"Immune exclusion","PD-L1 vorhanden, aber die T-Zellen kommen nicht hinein: immune-excluded Pankreasadenokarzinom":"PD-L1 present, but T cells cannot get in: immune-excluded pancreatic adenocarcinoma","Molekularpathologie / Gastroonkologie / MTB":"Molecular pathology / Gastrointestinal oncology / MTB","PD-L1-Expression von einer tatsächlich inflamed/hot Tumormikroumgebung unterscheiden.":"Distinguish PD-L1 expression from a truly inflamed/hot tumor microenvironment.","MMR/MSI und TMB als etabliertere immunonkologische Biomarker gegenüber explorativen TME-Markern priorisieren.":"Prioritize MMR/MSI and TMB as more established immuno-oncology biomarkers over exploratory TME markers.","Ein immune-excluded Muster aus Morphologie, TIL-Verteilung und desmoplastischem Stroma ableiten.":"Derive an immune-excluded pattern from morphology, TIL distribution and desmoplastic stroma.","Verstehen, dass Stromabarriere/TIL-IHC die Biologie erklären, aber keine validierte Therapie-Selektion ersetzen.":"Understand that stromal barrier/TIL IHC explains biology but does not replace validated treatment selection.","PD-1-Monotherapie nicht allein aus einem PD-L1-positiven Befund ableiten.":"Do not infer PD-1 monotherapy from a PD-L1-positive finding alone.","Im Zuweiserbrief steht fett: 'PD-L1 TPS 15 % – Immuntherapie?' Auf dem HE sieht der Tumor jedoch fast wie eine Festung aus: breite desmoplastische Stromazonen, wenige T-Zellen und kaum Lymphozyten in den Tumorzellnestern. Der Fall zwingt zur Frage, ob ein exprimierter Checkpoint überhaupt etwas nützt, wenn kaum aktivierbare Effektor-T-Zellen den Tumor erreichen.":"The referral letter says in bold: 'PD-L1 TPS 15% – immunotherapy?' On H&E, however, the tumor looks almost like a fortress: broad desmoplastic stromal zones, few T cells and hardly any lymphocytes in the tumor cell nests. The case forces the question of whether an expressed checkpoint is useful at all when few activatable effector T cells reach the tumor.","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach Erstlinientherapie. Ein externer PD-L1-Befund ist positiv. Im MTB soll geklärt werden, ob daraus eine belastbare PD-1-Monotherapie-Strategie folgt und welche Bedeutung das auffallend desmoplastische, lymphozytenarme Mikromilieu besitzt.":"64-year-old patient with metastatic pancreatic ductal adenocarcinoma and progression after first-line therapy. An external PD-L1 result is positive. The MTB must determine whether this supports a robust PD-1 monotherapy strategy and what significance the striking desmoplastic, lymphocyte-poor microenvironment has.","Verlockender Einzelmarker":"Tempting single marker","PD-L1 TPS 15 % ist technisch reproduzierbar.":"PD-L1 TPS 15% is technically reproducible.","Ein real positiver Marker kann trotzdem im falschen Entitäts-/Biologiekontext wenig prädiktive Aussage besitzen.":"A truly positive marker can still have little predictive value in the wrong entity/biological context.","Morphologisches Gegenargument":"Morphologic counterargument","Breite Desmoplasie, wenige intratumorale TILs.":"Broad desmoplasia, few intratumoral TILs.","Checkpoint-Blockade reaktiviert vorhandene Immunantwort; sie erzeugt nicht automatisch eine fehlende T-Zell-Infiltration.":"Checkpoint blockade reactivates an existing immune response; it does not automatically create missing T-cell infiltration.","Validierte vs. explorative Ebene":"Validated vs exploratory layer","MMR/MSI/TMB können klinisch validierte Signale liefern; TME-IHC illustriert Mechanismen.":"MMR/MSI/TMB can provide clinically validated signals; TME IHC illustrates mechanisms.","Mechanistische Plausibilität und validierter Therapiebiomarker sind nicht dasselbe.":"Mechanistic plausibility and validated treatment biomarker are not the same thing.","PDAC mit ausgeprägter Desmoplasie und wenig intratumoralen Lymphozyten.":"PDAC with marked desmoplasia and few intratumoral lymphocytes.","TPS 15 %, reproduzierbar.":"TPS 15%, reproducible.","Metastasenblock mit ca. 35 % Tumoranteil; fokussierte Zusatzdiagnostik möglich.":"Metastatic block with approx. 35% tumor content; focused additional testing possible.","Nur zehn Schnitte: explorative Zusatz-IHC muss einen klaren didaktischen/biologischen Nutzen haben.":"Only ten sections: exploratory additional IHC must have clear educational/biological value.","TME-/Stroma-IHC ist in diesem Fall bewusst eine mechanistische Zusatzebene, kein validierter Companion-Diagnostic-Ersatz.":"TME/stromal IHC is deliberately a mechanistic additional layer in this case, not a validated companion-diagnostic substitute.","MMR/MSI/TMB müssen gegenüber breit gestreuter Immun-IHC priorisiert werden, wenn die Therapiefrage im Vordergrund steht.":"MMR/MSI/TMB must be prioritized over broadly scattered immune IHC when the treatment question is central.","Was bedeutet PD-L1 TPS 15 % in diesem PDAC am ehesten?":"What does PD-L1 TPS 15% most likely mean in this PDAC?","Der Befund ist biologisch real, reicht aber ohne entitätsspezifisch validierten Kontext nicht für eine belastbare PD-1-Monotherapie-Entscheidung.":"The finding is biologically real, but without an entity-specifically validated context it is not sufficient for a robust PD-1 monotherapy decision.","Jede PD-L1-Positivität ist tumoragnostisch eine ICI-Indikation.":"Any PD-L1 positivity is a tumor-agnostic indication for ICI.","PD-L1 kann bei PDAC technisch nicht gemessen werden.":"PD-L1 cannot technically be measured in PDAC.","PD-L1 15 % beweist automatisch TMB-high.":"PD-L1 15% automatically proves TMB-high.","PD-L1-Expression ist nicht tumoragnostisch gleichbedeutend mit validierter Checkpoint-Sensitivität.":"PD-L1 expression is not tumor-agnostically synonymous with validated checkpoint sensitivity.","Wodurch ist ein immune-excluded Muster am besten charakterisiert?":"What best characterizes an immune-excluded pattern?","Immunzellen sind vorhanden, bleiben aber überwiegend im Stroma/peritumoral und erreichen Tumorzellnester nur schlecht.":"Immune cells are present but remain predominantly in the stroma/peritumoral area and reach tumor cell nests poorly.","Dichtes intraepitheliales CD8-Infiltrat in allen Tumorarealen.":"Dense intraepithelial CD8 infiltrate in all tumor areas.","Jeder immune-excluded Tumor ist automatisch MSI-H.":"Every immune-excluded tumor is automatically MSI-H.","PD-L1-Expression allein definiert immune exclusion.":"PD-L1 expression alone defines immune exclusion.","Die räumliche Verteilung der Immunzellen ist zentral; 'vorhanden' ist nicht gleich 'im Tumor wirksam'.":"The spatial distribution of immune cells is central; 'present' is not the same as 'effective within the tumor'.","Welche Zusatzdiagnostik sollte für die klinische IO-Frage priorisiert werden?":"Which additional diagnostics should be prioritized for the clinical IO question?","MMR/MSI und ggf. TMB als etabliertere Biomarker; TME-IHC nur ergänzend/mechanistisch.":"MMR/MSI and, where appropriate, TMB as more established biomarkers; TME IHC only as complementary/mechanistic information.","Nur CAF-/Stroma-IHC, da diese allein die Therapie festlegt.":"Only CAF/stromal IHC, since this alone determines treatment.","PD-L1 mehrfach wiederholen, bis ein höherer Wert entsteht.":"Repeat PD-L1 until a higher value is obtained.","Keine weitere Kontextdiagnostik; TPS 15 % reicht.":"No further contextual testing; TPS 15% is enough.","Explorative TME-Marker dürfen validierte Biomarker nicht ersetzen.":"Exploratory TME markers must not replace validated biomarkers.","Wie darf der desmoplastische/TIL-arme Befund im MTB verwendet werden?":"How may the desmoplastic/TIL-poor finding be used in the MTB?","Als biologische Erklärung für geringe Checkpoint-Sensitivität bzw. immune exclusion – nicht als eigenständiger validierter Therapieausschlusstest.":"As a biological explanation for low checkpoint sensitivity or immune exclusion – not as an independently validated treatment-exclusion test.","Als absolute Kontraindikation gegen jede Immuntherapie.":"As an absolute contraindication to any immunotherapy.","Als Beweis für einen zugelassenen CAF-Target-Standard.":"As proof of an approved CAF-targeting standard.","Morphologie und TIL-Verteilung sind grundsätzlich bedeutungslos.":"Morphology and TIL distribution are fundamentally meaningless.","Der TME-Befund ist mechanistisch stark, klinisch aber nicht als alleiniger Selektionsassay validiert.":"The TME finding is mechanistically strong but not clinically validated as a sole selection assay.","Formulieren Sie die MTB-Kernaussage so, dass PD-L1, pMMR/MSS/TMB und das immune-excluded/desmoplastische Muster hierarchisch korrekt integriert werden, ohne explorative TME-Befunde zu einem Companion Diagnostic aufzuwerten.":"Formulate the core MTB statement so that PD-L1, pMMR/MSS/TMB and the immune-excluded/desmoplastic pattern are integrated in the correct hierarchy without elevating exploratory TME findings to a companion diagnostic.","PD-L1 TPS 15 % als realen, aber nicht ausreichenden Einzelbefund anerkennen.":"Acknowledge PD-L1 TPS 15% as a real but insufficient single finding.","MMR/MSI prüfen: pMMR/MSS.":"Assess MMR/MSI: pMMR/MSS.","TMB als niedrig einordnen.":"Classify TMB as low.","Räumlich spärliches CD8-Infiltrat und Desmoplasie als immune-excluded TME beschreiben.":"Describe spatially sparse CD8 infiltration and desmoplasia as an immune-excluded TME.","PD-1-Monotherapie nicht allein aus PD-L1 ableiten.":"Do not infer PD-1 monotherapy from PD-L1 alone.","TME-IHC als mechanistische Zusatzinformation, nicht als validierten Selektionsmarker berichten.":"Report TME IHC as mechanistic additional information, not as a validated selection marker.","MMR-IHC plus MSI-Test und TMB aus einem validierten breiteren Panel, sofern Material und TAT dies erlauben.":"MMR IHC plus MSI testing and TMB from a validated broader panel, if material and TAT permit.","Auf zusätzliche Stroma-IHC verzichten, wenn die Morphologie die immune exclusion bereits überzeugend zeigt und die klinisch validierten Biomarker priorisiert werden.":"Omit additional stromal IHC if morphology already convincingly demonstrates immune exclusion and clinically validated biomarkers are prioritized.","PD-L1 = ICI":"PD-L1 = ICI","Die prädiktive Bedeutung von PD-L1 ist entitäts- und therapiespezifisch.":"The predictive significance of PD-L1 is entity- and therapy-specific.","CAF-IHC als Companion Diagnostic":"CAF IHC as companion diagnostic","Mechanistische TME-Marker sind hier nicht als eigenständige Therapie-Selektion validiert.":"Mechanistic TME markers are not validated here as independent treatment-selection tools.","TIL-arm = absolute Resistenz":"TIL-poor = absolute resistance","Biologische Wahrscheinlichkeit ist keine absolute patientenindividuelle Ausschlussregel.":"Biological probability is not an absolute patient-specific exclusion rule.","TMB/MSI ignorieren":"Ignore TMB/MSI","Damit würden etabliertere immunonkologische Biomarker ausgelassen.":"This would omit more established immuno-oncology biomarkers.","Der 'positive' Marker sitzt auf einem biologisch kalten Tumor":"The 'positive' marker sits on a biologically cold tumor","PD-L1 TPS 15 % wird bestätigt – gleichzeitig ist der Tumor pMMR/MSS, TMB-low und zeigt nur wenige CD8-T-Zellen, die überwiegend im desmoplastischen Stroma stecken bleiben. Der vermeintlich positive Einzelmarker kippt dadurch nicht ins 'falsch', sondern bekommt die richtige Hierarchie: biologischer Kontextmarker statt Therapie-Schalter.":"PD-L1 TPS 15% is confirmed – at the same time the tumor is pMMR/MSS, TMB-low and shows only a few CD8 T cells that remain largely trapped in the desmoplastic stroma. The apparently positive single marker therefore does not become 'wrong'; it acquires the correct hierarchy: biological context marker rather than treatment switch.","Der Fall trennt Expression eines Checkpoints von einer vorhandenen effektiven Antitumor-Immunantwort und zeigt, warum räumliche TME-Biologie die Interpretation verändert.":"The case separates checkpoint expression from an existing effective antitumor immune response and shows why spatial TME biology changes interpretation.","PD-L1 im richtigen TME-Kontext":"PD-L1 in the correct TME context","PD-L1 TPS 15 %, pMMR/MSS, TMB 3,2 Mut/Mb, CD8-arm/immune-excluded mit ausgeprägter Desmoplasie. Kein belastbarer Grund für PD-1-Monotherapie allein aus PD-L1; TME-Befund mechanistisch, nicht als Companion Diagnostic.":"PD-L1 TPS 15%, pMMR/MSS, TMB 3.2 Mut/Mb, CD8-poor/immune-excluded with marked desmoplasia. No robust basis for PD-1 monotherapy from PD-L1 alone; TME finding mechanistic, not a companion diagnostic.","Validierte Biomarker und TME-Biologie korrekt hierarchisiert.":"Validated biomarkers and TME biology correctly prioritized.","Cold erkannt, Biomarkerhierarchie unklar":"Cold pattern recognized, biomarker hierarchy unclear","Desmoplasie und wenige TILs werden beschrieben, MMR/MSI/TMB aber nicht integriert.":"Desmoplasia and few TILs are described, but MMR/MSI/TMB are not integrated.","Biologisch plausibel, klinisch unvollständig.":"Biologically plausible, clinically incomplete.","PD-L1 als universeller IO-Schalter":"PD-L1 as universal IO switch","TPS 15 % wird als ausreichende tumoragnostische ICI-Indikation interpretiert.":"TPS 15% is interpreted as a sufficient tumor-agnostic ICI indication.","Entitätsspezifische Biomarkerlogik übergangen.":"Entity-specific biomarker logic ignored.","pMMR/MSS und TMB-low bestätigt":"pMMR/MSS and TMB-low confirmed","Therapieplanung auf etablierte PDAC-Strategien bzw. passende Studien fokussieren; PD-L1 nicht isoliert übergewichten.":"Focus treatment planning on established PDAC strategies or appropriate trials; do not overweight PD-L1 in isolation.","Der Fall bleibt evidenzbasiert statt biomarkergetrieben spekulativ.":"The case remains evidence-based rather than biomarker-driven speculative.","TME-/Stromaforschung diskutiert":"TME/stromal research discussed","Studienoptionen klar als experimentell kennzeichnen.":"Clearly label trial options as experimental.","Mechanistische Hypothesen werden von Routineempfehlungen getrennt.":"Mechanistic hypotheses are separated from routine recommendations.","PD-L1-Expression ist nicht gleichbedeutend mit vorhandener effektiver T-Zell-Antwort.":"PD-L1 expression is not synonymous with an existing effective T-cell response.","Immune exclusion beschreibt die räumliche Barriere zwischen Immunzellen und Tumorzellnestern.":"Immune exclusion describes the spatial barrier between immune cells and tumor cell nests.","pMMR/MSS und niedrige TMB liefern hier keine starken etablierten Immunogenitätssignale.":"pMMR/MSS and low TMB provide no strong established immunogenicity signals here.","TME-/CAF-/TIL-Marker können Mechanismen erklären, sind aber nicht automatisch validierte Therapie-Selektionstests.":"TME/CAF/TIL markers can explain mechanisms but are not automatically validated treatment-selection tests.","Der klinische Wert eines Biomarkers hängt von Entität, Therapie und Evidenzniveau ab.":"The clinical value of a biomarker depends on entity, treatment and level of evidence.","PD-L1 TPS 15 % ist kein ausreichender Monotherapie-Schalter. Der Tumor ist pMMR/MSS und TMB-low; morphologisch/IHC zeigt sich ein deutlich immune-excluded, desmoplastisches TME. Das erklärt biologisch eine geringe Wahrscheinlichkeit effektiver Checkpoint-Reaktivierung, darf aber nicht als absoluter Ausschlusstest oder validierter Companion Diagnostic formuliert werden.":"PD-L1 TPS 15% is not a sufficient monotherapy switch. The tumor is pMMR/MSS and TMB-low; morphologically/IHC there is a clearly immune-excluded, desmoplastic TME. This biologically explains a low probability of effective checkpoint reactivation, but must not be phrased as an absolute exclusion test or validated companion diagnostic.","PD-L1 nicht überinterpretiert":"PD-L1 not overinterpreted","MMR/MSI/TMB priorisiert":"MMR/MSI/TMB prioritized","immune-excluded räumlich verstanden":"immune-excluded understood spatially","TME-Marker als explorativ begrenzt":"TME markers limited as exploratory","Warum kann PD-L1 exprimiert sein, obwohl kaum T-Zellen im Tumor sitzen?":"Why can PD-L1 be expressed even though hardly any T cells are present within the tumor?","Was unterscheidet immune-desert von immune-excluded?":"What distinguishes immune-desert from immune-excluded?","Welche TME-Marker sind mechanistisch interessant, aber nicht routineprädiktiv validiert?":"Which TME markers are mechanistically interesting but not validated as routine predictive markers?","PD-L1 positiv, aber pMMR/MSS/TMB-low + immune-excluded":"PD-L1 positive, but pMMR/MSS/TMB-low + immune-excluded","Checkpoint-Expression braucht einen validierten Entitäts- und Immunitätskontext":"Checkpoint expression requires a validated entity and immune context","PD-L1 → MMR/MSI/TMB → räumliche TILs → TME-Limitation":"PD-L1 → MMR/MSI/TMB → spatial TILs → TME limitation","PD-L1 positiv, aber niedrige TMB und kein Immuninfiltrat → PD-L1 nicht überinterpretieren":"PD-L1 positive, but low TMB and no immune infiltrate → do not overinterpret PD-L1","PD-L1 positiv, aber niedrige TMB u…":"PD-L1 positive, but low TMB a…","61-jährige Patientin mit metastasiertem kolorektalem Adenokarzinom nach Progress unter mehreren Standardtherapien. In einer Metastasenbiopsie wird PD-L1 CPS 25 berichtet.":"61-year-old patient with metastatic colorectal adenocarcinoma after progression on several standard therapies. PD-L1 CPS 25 is reported in a metastatic biopsy.","Kann die hohe PD-L1-Expression trotz fehlender klassischer Immunogenitätsmarker eine PD-1-Monotherapie begründen?":"Can high PD-L1 expression justify PD-1 monotherapy despite the absence of classic immunogenicity markers?","Es wird nach einer weiteren systemischen Option gesucht; Studienzugang wird parallel geprüft.":"A further systemic option is being sought; trial access is being assessed in parallel.","Primarius":"Primary tumor","Linksseitiges Kolonkarzinom, inzwischen hepatisch und pulmonal metastasiert.":"Left-sided colon cancer, now metastatic to liver and lung.","Fluoropyrimidin/Oxaliplatin, Irinotecan-basierte Therapie und weitere leitliniengerechte Linien.":"Fluoropyrimidine/oxaliplatin, irinotecan-based therapy and further guideline-concordant lines.","Außenbefund":"External report","PD-L1 CPS 25 wird auf dem Deckblatt fett hervorgehoben.":"PD-L1 CPS 25 is highlighted in bold on the cover sheet.","Ein 'positiver' Marker wird aus einer anderen Tumorentität in den CRC-Kontext übertragen, obwohl die prädiktive Hierarchie dort anders ist.":"A 'positive' marker is transferred from another tumor entity into the CRC context even though the predictive hierarchy differs there.","Kolorektales Adenokarzinom, mäßig differenziert; keine ausgeprägt lymphozytenreiche Morphologie.":"Moderately differentiated colorectal adenocarcinoma; no markedly lymphocyte-rich morphology.","CPS 25, überwiegend durch PD-L1-positive Immunzellen an Nekrose-/Stromagrenzen mitgetragen.":"CPS 25, driven predominantly by PD-L1-positive immune cells at necrotic/stromal interfaces.","Nur spärliche intratumorale CD8-positive Lymphozyten.":"Only sparse intratumoral CD8-positive lymphocytes.","MMR/MSI und TMB als entitätsspezifisch relevanter immunonkologischer Kontext.":"MMR/MSI and TMB as the entity-relevant immuno-oncology context.","FFPE-Lebermetastase, Block H2.":"FFPE liver metastasis, block H2.","ca. 50 %, gut geeignet.":"approx. 50%, well suited.","PD-L1 ist technisch messbar, seine prädiktive Bedeutung ist aber entitäts- und therapiespezifisch; ein numerisch hoher Score ist nicht automatisch ein universeller IO-Biomarker.":"PD-L1 is technically measurable, but its predictive significance is entity- and therapy-specific; a numerically high score is not automatically a universal IO biomarker.","Immunonkologischer Kontext":"Immuno-oncology context","Erhaltene nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Preserved nuclear expression of MLH1, PMS2, MSH2 and MSH6: pMMR.","MSS. Damit fehlt der für mCRC etablierte dMMR/MSI-H-Immuntherapiekontext.":"MSS. Thus, the established dMMR/MSI-H immunotherapy context for mCRC is absent.","TMB niedrig (4,0 Mut/Mb).":"TMB low (4.0 Mut/Mb).","PD-L1 CPS 25 bestätigt. Die Expression ist biologisch real, aber im pMMR/MSS-mCRC kein Ersatz für einen validierten MSI/dMMR-basierten Selektionsmarker.":"PD-L1 CPS 25 confirmed. The expression is biologically real, but in pMMR/MSS mCRC it does not replace a validated MSI/dMMR-based selection marker.","TIL-Kontext":"TIL context","Nur wenige intratumorale CD8-positive T-Zellen; kein ausgeprägt inflamed/hot pattern.":"Only a few intratumoral CD8-positive T cells; no markedly inflamed/hot pattern.","Kernausgangslage":"Core starting point","PD-L1 CPS 25 bei mCRC ohne morphologisch ausgeprägtes Immuninfiltrat.":"PD-L1 CPS 25 in mCRC without a morphologically prominent immune infiltrate.","MMR-IHC, MSI und DNA-basierte Zusatzanalysen technisch verwertbar.":"MMR IHC, MSI and DNA-based additional analyses technically usable.","Metastasiertes CRC mit realer PD-L1-Expression, aber pMMR/MSS, niedriger TMB und spärlichem intratumoralem T-Zell-Infiltrat. PD-L1-Positivität allein begründet in diesem Kontext keine etablierte PD-1-Monotherapie. Für mCRC besitzt dMMR/MSI-H eine deutlich stärkere und validierte prädiktive Rolle; experimentelle Kombinationen bei pMMR/MSS gehören in einen Studien-/Evidenzkontext.":"Metastatic CRC with genuine PD-L1 expression, but pMMR/MSS, low TMB and sparse intratumoral T-cell infiltrate. PD-L1 positivity alone does not establish an approved PD-1 monotherapy in this context. In mCRC, dMMR/MSI-H has a substantially stronger and validated predictive role; experimental combinations in pMMR/MSS belong in a trial/evidence context.","Teilbefund: PD-L1 ist hoch, aber ohne MMR/MSI-Kontext ist die Übertragbarkeit auf eine Therapieentscheidung nicht belastbar.":"Partial result: PD-L1 is high, but without MMR/MSI context its transferability to a treatment decision is not robust.","PD-L1-Bedeutung entitätsspezifisch einordnen":"Interpret PD-L1 significance in an entity-specific manner","pMMR/MSS als entscheidenden Gegenbefund zur einfachen PD-L1-Logik benennen":"Identify pMMR/MSS as the decisive counterfinding to simple PD-L1 logic","niedrige TMB und spärliches Infiltrat als zusätzliche Kontextmarker integrieren":"Integrate low TMB and sparse infiltrate as additional contextual markers","pMMR/MSS-IO-Kombinationen nicht mit etablierter Monotherapie gleichsetzen":"Do not equate pMMR/MSS IO combinations with established monotherapy","Falschaussage: Hoher PD-L1-Score ist tumoragnostisch immer prädiktiv":"False statement: a high PD-L1 score is always tumor-agnostically predictive","Optimale Lösung: PD-L1 CPS 25 ist kein universeller IO-Schalter. Im pMMR/MSS-mCRC mit niedriger TMB und wenig TILs darf der Score die entitätsspezifisch validierte Biomarkerhierarchie nicht überstimmen; experimentelle Strategien gehören in Studien.":"Optimal solution: PD-L1 CPS 25 is not a universal IO switch. In pMMR/MSS mCRC with low TMB and few TILs, the score must not override the entity-specifically validated biomarker hierarchy; experimental strategies belong in trials.","TIL-low":"TIL-low","Immuntherapie":"Immunotherapy","Biomarkerhierarchie":"Biomarker hierarchy","PD-L1 CPS 25 und trotzdem kein ICI-Biomarker: MSS-mCRC als Überinterpretationsfalle":"PD-L1 CPS 25 and still no ICI biomarker: MSS mCRC as an overinterpretation trap","PD-L1 als entitätsabhängigen und nicht tumoragnostischen Biomarker verstehen.":"Understand PD-L1 as an entity-dependent and not tumor-agnostic biomarker.","Beim mCRC dMMR/MSI-H gegenüber PD-L1 als prädiktiv stärker validierten IO-Kontext priorisieren.":"In mCRC, prioritize dMMR/MSI-H over PD-L1 as the more strongly validated predictive IO context.","pMMR/MSS, niedrige TMB und TIL-Armut als konsistente Gegenkonstellation zu einer simplen PD-L1-Logik integrieren.":"Integrate pMMR/MSS, low TMB and TIL paucity as a consistent counterconfiguration to simple PD-L1 logic.","PD-L1-Score und zelluläre Quelle/Spatial Context nicht mit universeller Therapieindikation verwechseln.":"Do not confuse PD-L1 score and cellular source/spatial context with a universal treatment indication.","Experimentelle ICI-Kombinationen im pMMR/MSS-mCRC von etablierter Monotherapie unterscheiden.":"Distinguish experimental ICI combinations in pMMR/MSS mCRC from established monotherapy.","Der Außenbefund klingt spektakulär: PD-L1 CPS 25. Im Tumorboard kommt sofort die Frage nach Pembrolizumab. Doch die Histologie ist lymphozytenarm, die MMR-Proteine sind erhalten und der Tumor ist MSS. Der Fall ist ein Lehrstück dafür, dass derselbe Biomarkerwert je nach Tumorentität völlig unterschiedliche klinische Bedeutung haben kann.":"The external report sounds spectacular: PD-L1 CPS 25. In the tumor board, pembrolizumab is immediately raised. But the histology is lymphocyte-poor, MMR proteins are retained and the tumor is MSS. The case is a lesson that the same biomarker value can have completely different clinical significance depending on tumor entity.","61-jährige Patientin mit mehrfach vorbehandeltem metastasiertem kolorektalem Adenokarzinom. Eine Metastasenbiopsie zeigt PD-L1 CPS 25. Gesucht ist eine evidenzbasierte Einordnung, ob dieser Wert im pMMR/MSS-mCRC eine etablierte PD-1-Monotherapie begründet oder ob die entitätsspezifische MSI/dMMR-Hierarchie Vorrang hat.":"61-year-old patient with heavily pretreated metastatic colorectal adenocarcinoma. A metastatic biopsy shows PD-L1 CPS 25. The task is an evidence-based assessment of whether this value supports established PD-1 monotherapy in pMMR/MSS mCRC or whether the entity-specific MSI/dMMR hierarchy takes priority.","Hohe Zahl, falsche Abkürzung":"High number, wrong shortcut","PD-L1 CPS 25 wird als 'positiv' hervorgehoben.":"PD-L1 CPS 25 is highlighted as 'positive'.","Ein numerisch hoher Wert ist nur dann prädiktiv, wenn Assay, Scoring, Entität und Therapie dafür validiert sind.":"A numerically high value is predictive only if assay, scoring, entity and treatment are validated for that use.","CRC-spezifische Hierarchie":"CRC-specific hierarchy","MMR/MSI ist für die IO-Selektion beim mCRC zentral.":"MMR/MSI is central for IO selection in mCRC.","Biomarker dürfen nicht entitätsübergreifend ohne Evidenz transferiert werden.":"Biomarkers must not be transferred across entities without evidence.","Biologisches Gesamtbild":"Overall biological picture","TMB-low und TIL-arm.":"TMB-low and TIL-poor.","Mehrere unabhängige Kontextsignale sprechen gegen die einfache Annahme eines hoch immunogenen Tumors.":"Several independent contextual signals argue against the simple assumption of a highly immunogenic tumor.","PD-L1 Außenbefund":"External PD-L1 result","CPS 25, überwiegend an Tumor-/Stromagrenzen und Immunzellen.":"CPS 25, predominantly at tumor/stromal interfaces and on immune cells.","Keine ausgeprägt lymphozytenreiche CRC-Morphologie.":"No markedly lymphocyte-rich CRC morphology.","Lebermetastase mit ca. 50 % Tumoranteil.":"Liver metastasis with approx. 50% tumor content.","MMR-IHC und MSI-Testung sind mit wenig Material möglich und beantworten die entscheidende CRC-spezifische Frage direkter als wiederholte PD-L1-IHC.":"MMR IHC and MSI testing require little material and answer the decisive CRC-specific question more directly than repeated PD-L1 IHC.","TMB ist additive Kontextinformation und darf MSI/dMMR nicht ersetzen.":"TMB is additive contextual information and must not replace MSI/dMMR.","Breite Zusatzdiagnostik soll nicht nur deshalb erfolgen, weil ein einzelner PD-L1-Score klinisch verlockend wirkt.":"Broad additional testing should not be performed merely because a single PD-L1 score appears clinically tempting.","Wie ist PD-L1 CPS 25 im mCRC grundsätzlich zu behandeln?":"How should PD-L1 CPS 25 generally be handled in mCRC?","Als entitätsspezifisch zu interpretierender Kontextbefund; nicht als universeller tumoragnostischer ICI-Schalter.":"As a contextual finding that must be interpreted by entity; not as a universal tumor-agnostic ICI switch.","CPS ≥10 ist bei jeder soliden Tumorentität automatisch prädiktiv.":"CPS ≥10 is automatically predictive in every solid tumor entity.","PD-L1-IHC ist im CRC technisch grundsätzlich ungültig.":"PD-L1 IHC is technically invalid in CRC as a matter of principle.","PD-L1 CPS 25 beweist MSI-H.":"PD-L1 CPS 25 proves MSI-H.","Prädiktive Biomarker funktionieren nur in validiertem Entitäts-/Therapiekontext.":"Predictive biomarkers only work within a validated entity/treatment context.","Welcher Befund besitzt beim mCRC die klarere etablierte IO-Relevanz?":"Which finding has the clearer established IO relevance in mCRC?","dMMR/MSI-H.":"dMMR/MSI-H.","PD-L1 CPS allein.":"PD-L1 CPS alone.","TIL-Zahl allein.":"TIL count alone.","Tumornekrose allein.":"Tumor necrosis alone.","dMMR/MSI-H ist der etablierte zentrale Immuntherapie-Biomarkerkontext im mCRC.":"dMMR/MSI-H is the established central immunotherapy biomarker context in mCRC.","PD-L1 CPS 25, aber pMMR/MSS und TMB 4 Mut/Mb. Was ist die sauberste Aussage?":"PD-L1 CPS 25, but pMMR/MSS and TMB 4 mut/Mb. What is the most appropriate statement?","PD-L1 überstimmt pMMR/MSS nicht; daraus folgt keine etablierte PD-1-Monotherapie. Studienstrategien müssen als experimentell gekennzeichnet werden.":"PD-L1 does not override pMMR/MSS; this does not establish an indication for PD-1 monotherapy. Trial strategies must be labeled experimental.","Hoher CPS macht die Monotherapie unabhängig von MSI zum Standard.":"A high CPS makes monotherapy standard regardless of MSI.","Ein pMMR/MSS-CRC kann in keiner Studie jemals auf Immuntherapie reagieren.":"A pMMR/MSS CRC can never respond to immunotherapy in any trial.","CPS 25 definiert automatisch TMB-high.":"CPS 25 automatically defines TMB-high.","Fehlende etablierte Monotherapie-Indikation ist nicht gleichbedeutend mit biologisch unmöglicher Aktivität in Studienkombinationen.":"The absence of an established monotherapy indication does not mean that activity in investigational combinations is biologically impossible.","Warum ist es hilfreich zu wissen, woher der CPS stammt?":"Why is it useful to know where the CPS comes from?","PD-L1-positive Immunzellen an Stromagrenzen können den Score erhöhen, ohne ein dichtes intratumorales Effektor-T-Zell-Infiltrat zu belegen.":"PD-L1-positive immune cells at stromal boundaries can increase the score without demonstrating a dense intratumoral effector T-cell infiltrate.","Immunzell-PD-L1 beweist immer bessere ICI-Wirkung.":"PD-L1 on immune cells always proves better ICI efficacy.","CPS darf Immunzellen niemals berücksichtigen.":"CPS must never include immune cells.","Zelluläre Quelle und räumlicher Kontext sind grundsätzlich irrelevant.":"Cellular source and spatial context are fundamentally irrelevant.","Score und räumliche Immunbiologie sind unterschiedliche Informationsebenen.":"Score and spatial immune biology are different layers of information.","Entscheiden Sie, wie PD-L1 CPS 25 im pMMR/MSS-mCRC berichtet und im MTB gewichtet wird, ohne den Befund zu ignorieren oder ihn entitätsfremd zur etablierten ICI-Indikation aufzuwerten.":"Decide how PD-L1 CPS 25 should be reported and weighted in the MTB for pMMR/MSS mCRC, without ignoring the finding or promoting it outside its entity-specific validated ICI indication.","PD-L1 CPS 25 als technisch realen Befund anerkennen.":"Acknowledge PD-L1 CPS 25 as a technically real finding.","MMR-IHC und MSI prüfen: pMMR/MSS.":"Check MMR IHC and MSI: pMMR/MSS.","TMB als niedrig und TIL-Infiltrat als spärlich einordnen.":"Classify TMB as low and the TIL infiltrate as sparse.","PD-L1 im CRC nicht als tumoragnostischen Therapie-Schalter formulieren.":"Do not formulate PD-L1 in CRC as a tumor-agnostic treatment switch.","Keine etablierte PD-1-Monotherapie aus PD-L1 allein ableiten.":"Do not derive an established PD-1 monotherapy indication from PD-L1 alone.","Experimentelle pMMR/MSS-IO-Kombinationen ausschließlich als Studienoption/Evidenzentwicklung kennzeichnen.":"Label experimental pMMR/MSS immunotherapy combinations exclusively as trial options/evolving evidence.","MMR-IHC plus MSI-Test; TMB nur ergänzend, wenn bereits aus validiertem Panel verfügbar.":"MMR IHC plus MSI testing; TMB only as an adjunct if already available from a validated panel.","Bei klarem pMMR/MSS kann auf wiederholte PD-L1-IHC verzichtet werden, wenn sie die klinische Entscheidung nicht verändert.":"With clearly established pMMR/MSS, repeat PD-L1 IHC may be omitted if it will not change the clinical decision.","CPS aus anderer Entität übertragen":"Transfer CPS from another tumor entity","PD-L1-Cutoffs sind nicht tumoragnostisch austauschbar.":"PD-L1 cutoffs are not interchangeable across tumor types.","PD-L1 ignorieren":"Ignore PD-L1","Der Befund ist biologisch real und kann Forschung/Studienkontext informieren; er ist nur nicht der etablierte Selektionsmarker.":"The finding is biologically real and may inform research/trial context; it is simply not the established selection biomarker.","pMMR/MSS = absolute Immunresistenz":"pMMR/MSS = absolute immune resistance","Das wäre zu absolut; Studienkombinationen werden untersucht.":"That would be too absolute; investigational combinations are being studied.","TMB ersetzt MSI":"TMB replaces MSI","TMB und MSI sind verwandte, aber nicht austauschbare Biomarker.":"TMB and MSI are related but not interchangeable biomarkers.","Die 25 ist echt – aber klinisch nicht der Hauptmarker":"The 25 is real — but clinically it is not the key marker","PD-L1 CPS 25 wird bestätigt. Gleichzeitig zeigen MMR-IHC und MSI-Testung pMMR/MSS, TMB liegt bei 4 Mut/Mb und CD8-T-Zellen sind spärlich. Der Twist ist nicht, dass PD-L1 'falsch' war, sondern dass ein realer positiver Befund außerhalb seines validierten Entitätskontexts therapeutisch viel weniger trägt.":"PD-L1 CPS 25 is confirmed. At the same time, MMR IHC and MSI testing show pMMR/MSS, TMB is 4 mut/Mb, and CD8 T cells are sparse. The twist is not that PD-L1 was 'wrong', but that a genuinely positive finding carries much less therapeutic weight outside its validated entity-specific context.","So wird die zentrale Präzisionsonkologie-Kompetenz trainiert: Biomarker werden nicht nach Positiv/Negativ, sondern nach Evidenz, Entität und Therapiehierarchie interpretiert.":"This trains a core precision-oncology skill: biomarkers are interpreted not merely as positive/negative, but according to evidence, tumor entity, and treatment hierarchy.","PD-L1 entitätsspezifisch begrenzt":"PD-L1 limited by entity-specific context","PD-L1 CPS 25, pMMR/MSS, TMB 4 Mut/Mb, TIL-arm. Keine etablierte PD-1-Monotherapie aus PD-L1 allein; dMMR/MSI-H wäre der relevante validierte IO-Kontext. Studienkombinationen klar als experimentell kennzeichnen.":"PD-L1 CPS 25, pMMR/MSS, TMB 4 mut/Mb, sparse TILs. No established PD-1 monotherapy based on PD-L1 alone; dMMR/MSI-H would be the relevant validated ICI context. Clearly label trial combinations as experimental.","Biomarkerhierarchie sauber getroffen.":"Biomarker hierarchy correctly identified.","MSS erkannt, PD-L1 aber nicht eingeordnet":"MSS recognized, but PD-L1 not contextualized","pMMR/MSS wird berichtet, der hohe CPS bleibt ohne Erklärung im Raum.":"pMMR/MSS is reported, but the high CPS remains unexplained.","Der wichtigste Lernkonflikt wird nicht aufgelöst.":"The key learning conflict remains unresolved.","CPS 25 = Pembrolizumab":"CPS 25 = pembrolizumab","PD-L1 wird entitätsübergreifend als Standardindikation interpretiert.":"PD-L1 is interpreted across tumor types as a standard indication.","Validierungskontext missachtet.":"Validation context disregarded.","Nicht-MSI-basierte Routineoptionen und geeignete klinische Studien prüfen.":"Assess established non-MSI-based options and suitable clinical trials.","Experimentelle Immuntherapiestrategien bleiben möglich, aber werden nicht als etablierte Monotherapie verkauft.":"Experimental immunotherapy strategies remain possible, but should not be presented as established monotherapy.","PD-L1 ist kein tumoragnostischer Biomarker.":"PD-L1 is not a tumor-agnostic biomarker.","Im mCRC hat dMMR/MSI-H eine zentrale etablierte prädiktive Rolle für Checkpoint-Inhibition.":"In mCRC, dMMR/MSI-H has a central established predictive role for checkpoint inhibition.","pMMR/MSS und niedrige TMB/TILs relativieren die intuitive Interpretation eines hohen PD-L1-Scores.":"pMMR/MSS and low TMB/TILs temper the intuitive interpretation of a high PD-L1 score.","Ein positiver Labormarker kann korrekt gemessen und trotzdem klinisch nicht entscheidend sein.":"A positive laboratory marker can be measured correctly and still not be clinically decisive.","Studienevidenz bei pMMR/MSS darf nicht mit Routine-Standard gleichgesetzt werden.":"Trial evidence in pMMR/MSS must not be equated with routine standard of care.","PD-L1 CPS 25 ist ein realer Kontextbefund, aber im pMMR/MSS-mCRC kein etablierter Ersatz für dMMR/MSI-H. TMB ist niedrig, TILs spärlich. Daher keine etablierte PD-1-Monotherapie allein aus dem CPS ableiten; Studienkombinationen nur als experimentelle Optionen kommunizieren.":"PD-L1 CPS 25 is a real contextual finding, but in pMMR/MSS mCRC it is not an established substitute for dMMR/MSI-H. TMB is low and TILs are sparse. Therefore, do not derive established PD-1 monotherapy from CPS alone; communicate trial combinations only as experimental options.","Entitätsspezifität":"Entity specificity","MMR/MSI priorisiert":"MMR/MSI prioritized","PD-L1 nicht ignoriert, aber begrenzt":"PD-L1 not ignored, but appropriately limited","Studie vs. Standard getrennt":"Trial versus standard separated","Warum kann derselbe PD-L1-Score in zwei Tumorentitäten unterschiedliche Bedeutung besitzen?":"Why can the same PD-L1 score have different significance in two tumor entities?","Welche Biomarker sind tumoragnostisch zugelassen und welche nicht?":"Which biomarkers have tumor-agnostic approvals and which do not?","Wie formuliert man einen 'positiven, aber nicht entscheidenden' Marker verständlich im Befund?":"How do you communicate a 'positive but non-decisive' marker clearly in a report?","PD-L1 CPS 25 wird durch pMMR/MSS/TMB-low relativiert":"PD-L1 CPS 25 is tempered by pMMR/MSS/TMB-low","Biomarkerpositivität ist ohne Entitätsvalidierung keine Therapieindikation":"Biomarker positivity is not a treatment indication without entity-specific validation","PD-L1 → MMR/MSI → TMB/TIL → Evidenzhierarchie":"PD-L1 → MMR/MSI → TMB/TIL → evidence hierarchy","MSI-H-Karzinom: Therapieoption und Lynch-Abklärung → IO, MMR-IHC, Keimbahnkontext":"MSI-H carcinoma: treatment option and Lynch work-up → IO, MMR IHC, germline context","MSI-H-Karzinom: Therapieoption und…":"MSI-H carcinoma: treatment option and…","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und pulmonalen Metastasen. Im Primärtumor war keine strukturierte MMR-/Lynch-Abklärung dokumentiert.":"49-year-old woman with recurrent endometrioid endometrial carcinoma and pulmonary metastases. No structured MMR/Lynch work-up had been documented in the primary tumor.","Ist der Tumor dMMR/MSI-H und damit immuntherapeutisch relevant? Welche Reflexdiagnostik ist bei einem MMR-Verlust erforderlich, und wann muss Humangenetik folgen?":"Is the tumor dMMR/MSI-H and therefore relevant for immunotherapy? Which reflex testing is required after MMR loss, and when should genetics follow?","Die molekulare Einordnung soll Therapieplanung und hereditäre Beratung parallel strukturieren.":"The molecular classification should structure treatment planning and hereditary counseling in parallel.","Alter":"Age","49 Jahre bei aktueller Rezidivsituation.":"49 years at the current recurrence.","Mutter mit Kolonkarzinom mit 52 Jahren; mütterlicher Onkel mit Urothelkarzinom des oberen Harntrakts.":"Mother with colorectal cancer at age 52; maternal uncle with upper urinary tract urothelial carcinoma.","Außenbefund nennt 'MSI verdächtig', ohne dokumentierte MMR-IHC oder MLH1-Methylierung.":"External report states 'suspicious for MSI' without documented MMR IHC or MLH1 methylation.","CRC-Reflexdiagnostik wird unverändert auf das Endometriumkarzinom übertragen – insbesondere BRAF-V600E statt MLH1-Promotormethylierung.":"CRC reflex diagnostics are transferred unchanged to endometrial carcinoma — particularly BRAF V600E instead of MLH1 promoter methylation.","Endometrioides Endometriumkarzinom, high-grade, mit fokal lymphozytenreichem Stroma.":"High-grade endometrioid endometrial carcinoma with focally lymphocyte-rich stroma.","Rezidiv-/Metastasenmaterial bestätigt endometrialen Ursprung.":"Recurrence/metastatic material confirms endometrial origin.","MMR-Proteinmuster, MSI-Status und bei MLH1/PMS2-Verlust die Frage einer sporadischen MLH1-Promotormethylierung.":"MMR protein pattern, MSI status, and in the setting of MLH1/PMS2 loss, the question of sporadic MLH1 promoter methylation.","Therapiebiomarker und Lynch-Screening nutzen dieselbe MMR-Biologie, führen aber zu unterschiedlichen nächsten Schritten.":"The treatment biomarker and Lynch screening use the same MMR biology but lead to different next steps.","FFPE-Resektat des Primärtumors plus aktuelle Metastasenbiopsie.":"FFPE resection specimen of the primary tumor plus a current metastatic biopsy.","Primärtumor ca. 60 %, DNA gut geeignet.":"Primary tumor about 60%, DNA well suited.","Ausreichend für MMR-IHC und molekulare Reflexdiagnostik.":"Sufficient for MMR IHC and molecular reflex testing.","BRAF V600E ist als Lynch-Reflex aus dem CRC-Kontext bekannt, beantwortet beim Endometriumkarzinom aber nicht die entscheidende sporadisch-vs.-hereditär-Frage.":"BRAF V600E is known as a Lynch reflex from the CRC context, but in endometrial carcinoma it does not answer the key sporadic-versus-hereditary question.","MSI-Bestätigung":"MSI confirmation","MLH1-Reflexdiagnostik":"MLH1 reflex testing","Hereditäre Weiterleitung":"Hereditary referral","Verlust von MLH1 und PMS2 bei erhaltener Expression von MSH2 und MSH6: dMMR-Muster.":"Loss of MLH1 and PMS2 with retained MSH2 and MSH6 expression: dMMR pattern.","MSI-high, konsistent mit dem dMMR-Befund.":"MSI-high, consistent with the dMMR finding.","MLH1-Promotormethylierung":"MLH1 promoter methylation","Keine MLH1-Promotor-Hypermethylierung nachweisbar. Damit ist eine häufige sporadische Ursache des MLH1/PMS2-Verlusts nicht belegt; Lynch-Syndrom bleibt abklärungsbedürftig, ist aber noch nicht bewiesen.":"No MLH1 promoter hypermethylation detected. A common sporadic cause of MLH1/PMS2 loss is therefore not demonstrated; Lynch syndrome still requires work-up but is not yet proven.","BRAF-V600E-Testung ist hier kein geeigneter Lynch-Screening-Reflex. Die aus dem CRC bekannte BRAF-Logik darf nicht auf das Endometriumkarzinom übertragen werden.":"BRAF V600E testing is not an appropriate Lynch-screening reflex here. The BRAF logic known from CRC must not be transferred to endometrial carcinoma.","Humangenetische Beratung und Keimbahndiagnostik der MMR/Lynch-relevanten Gene werden empfohlen; der Tumorbefund allein stellt keine Lynch-Diagnose.":"Genetic counseling and germline testing of MMR/Lynch-relevant genes are recommended; the tumor result alone does not establish a diagnosis of Lynch syndrome.","PD-L1/TMB Zusatzkontext":"Additional PD-L1/TMB context","Zusatzmarker können berichtet werden, stehen aber hinter dem robusten dMMR/MSI-H-Befund zurück und sind für die Lynch-Reflexdiagnostik nicht entscheidend.":"Additional markers may be reported but remain secondary to the robust dMMR/MSI-H finding and are not decisive for Lynch reflex testing.","Rezidiviertes Endometriumkarzinom bei junger Patientin mit auffälliger Familienanamnese.":"Recurrent endometrial carcinoma in a young patient with a notable family history.","MMR-IHC und MSI-/Methylierungsdiagnostik technisch verwertbar.":"MMR IHC and MSI/methylation testing are technically evaluable.","Rezidiviertes Endometriumkarzinom mit MLH1/PMS2-Verlust und MSI-H. Der dMMR/MSI-H-Befund ist therapeutisch relevant. Da keine MLH1-Promotor-Hypermethylierung nachweisbar ist, bleibt ein Lynch-Syndrom abklärungsbedürftig und erfordert humangenetische Beratung/Keimbahndiagnostik. BRAF V600E ist in diesem Endometrium-Kontext kein adäquater Ersatzreflex und Lynch ist aus dem Tumorbefund allein nicht bewiesen.":"Recurrent endometrial carcinoma with MLH1/PMS2 loss and MSI-H. The dMMR/MSI-H finding is therapeutically relevant. Because no MLH1 promoter hypermethylation is detected, Lynch syndrome remains to be investigated and requires genetic counseling/germline testing. BRAF V600E is not an adequate substitute reflex in this endometrial context, and Lynch syndrome is not proven by the tumor finding alone.","Teilbefund: dMMR/MSI-H ist erkannt, aber ohne MLH1-Methylierungsreflex und humangenetische Weiterleitung bleibt die hereditäre Ebene unvollständig.":"Partial result: dMMR/MSI-H is recognized, but without MLH1 methylation reflex testing and genetic referral, the hereditary dimension remains incomplete.","dMMR/MSI-H als starken prädiktiven Immuntherapiekontext benennen":"State dMMR/MSI-H as a strong predictive immunotherapy context","MLH1/PMS2-Verlust korrekt als gekoppeltes MMR-Muster einordnen":"Correctly interpret MLH1/PMS2 loss as a paired MMR pattern","MLH1-Promotormethylierung als passenden Endometrium-Reflex nutzen":"Use MLH1 promoter methylation as the appropriate endometrial reflex test","fehlende Methylierung → Lynch-Abklärung empfehlen, aber Lynch nicht als bewiesen darstellen":"No methylation → recommend Lynch work-up, but do not present Lynch syndrome as proven","Falschaussage: BRAF-V600E ist auch beim Endometriumkarzinom der Standardreflex für MLH1/PMS2-Verlust":"False statement: BRAF V600E is also the standard reflex for MLH1/PMS2 loss in endometrial carcinoma","Optimale Lösung: MLH1/PMS2-Verlust + MSI-H therapeutisch kommunizieren; beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex prüfen. Fehlt die Methylierung, humangenetisch weiterleiten – ohne aus dem Tumorscreening bereits eine Lynch-Diagnose zu machen.":"Optimal solution: communicate MLH1/PMS2 loss + MSI-H therapeutically; in endometrial carcinoma, assess MLH1 promoter methylation as the reflex test. If methylation is absent, refer for genetic evaluation — without turning the tumor screen itself into a Lynch diagnosis.","Endometriumkarzinom":"Endometrial carcinoma","dMMR":"dMMR","MSI-H":"MSI-H","MLH1":"MLH1","PMS2":"PMS2","Lynch":"Lynch","MSI-H und MLH1/PMS2-Verlust: Endometriumkarzinom zwischen Immuntherapie und Lynch-Abklärung":"MSI-H and MLH1/PMS2 loss: endometrial carcinoma between immunotherapy and Lynch work-up","Molekularpathologie / Gynäko-Onkologie / Humangenetik / MTB":"Molecular Pathology / Gynecologic Oncology / Medical Genetics / MTB","MMR-IHC-Muster korrekt lesen und MLH1/PMS2-Verlust funktionell einordnen.":"Read the MMR IHC pattern correctly and interpret MLH1/PMS2 loss functionally.","dMMR/MSI-H gleichzeitig als prädiktiven Therapiebiomarker und als möglichen Hinweis auf hereditäre Prädisposition verstehen.":"Understand dMMR/MSI-H both as a predictive treatment biomarker and as a possible indicator of hereditary predisposition.","Beim Endometriumkarzinom MLH1-Promotormethylierung als passenden Reflex bei MLH1/PMS2-Verlust einsetzen.":"In endometrial carcinoma, use MLH1 promoter methylation as the appropriate reflex test for MLH1/PMS2 loss.","Den CRC-spezifischen BRAF-V600E-Reflex nicht unkritisch auf das Endometriumkarzinom übertragen.":"Do not uncritically transfer the CRC-specific BRAF V600E reflex to endometrial carcinoma.","Fehlende MLH1-Methylierung als Anlass zur Lynch-Abklärung, nicht als bereits bewiesenes Lynch-Syndrom kommunizieren.":"Communicate absent MLH1 methylation as a reason for Lynch work-up, not as already proven Lynch syndrome.","Die MMR-IHC zeigt einen klaren MLH1/PMS2-Verlust, der MSI-Test ist high. Im Tumorboard sind sich alle einig, dass das therapeutisch wichtig ist. Dann kommt die zweite Frage: 'Dann machen wir jetzt BRAF wie beim Kolon?' Genau hier kippt der Fall von Immuntherapie in echte molekularpathologische Reflexdiagnostik.":"MMR IHC shows clear MLH1/PMS2 loss and MSI testing is high. Everyone in the tumor board agrees that this is therapeutically important. Then comes the second question: 'So now we do BRAF, like in colon cancer?' This is exactly where the case shifts from immunotherapy to genuine molecular-pathology reflex diagnostics.","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und auffälliger Familienanamnese. Der Tumor ist dMMR/MSI-H mit MLH1/PMS2-Verlust. Gesucht wird die korrekte Trennung von unmittelbarer therapeutischer Relevanz und Lynch-Screening inklusive entitätsspezifischem MLH1-Methylierungsreflex.":"49-year-old woman with recurrent endometrioid endometrial carcinoma and a notable family history. The tumor is dMMR/MSI-H with MLH1/PMS2 loss. The task is to correctly separate immediate therapeutic relevance from Lynch screening, including the entity-specific MLH1 methylation reflex.","Ein Befund, zwei Konsequenzen":"One finding, two consequences","dMMR/MSI-H ist therapie- und hereditär relevant.":"dMMR/MSI-H is relevant both therapeutically and for hereditary assessment.","Dieselbe Tumorbiologie kann unterschiedliche klinische Pfade auslösen.":"The same tumor biology can trigger different clinical pathways.","Verlustmuster":"Loss pattern","MLH1 und PMS2 fehlen gemeinsam.":"MLH1 and PMS2 are lost together.","Das Heterodimer-Muster lenkt die Reflexdiagnostik auf MLH1.":"The heterodimer pattern directs reflex testing toward MLH1.","Entität zählt":"Tumor entity matters","BRAF-Reflex ist aus dem CRC bekannt.":"The BRAF reflex is known from CRC.","Reflexalgorithmen dürfen nicht mechanisch zwischen Tumorentitäten übertragen werden.":"Reflex algorithms must not be mechanically transferred between tumor entities.","High-grade endometrioides Endometriumkarzinom.":"High-grade endometrioid endometrial carcinoma.","Mutter Kolonkarzinom mit 52, Onkel oberer Harntrakt.":"Mother with colorectal cancer at 52, uncle with upper urinary tract cancer.","Primärtumor mit guter DNA-Qualität; MMR-IHC und Methylierung möglich.":"Primary tumor with good DNA quality; MMR IHC and methylation testing feasible.","MMR-IHC liefert bereits das entscheidende Proteinverlustmuster und sollte nicht durch ein unspezifisches Breitpanel ersetzt werden.":"MMR IHC already provides the decisive protein-loss pattern and should not be replaced by a nonspecific broad panel.","Bei MLH1/PMS2-Verlust ist eine gezielte MLH1-Promotormethylierung material- und fragestellungseffizient.":"With MLH1/PMS2 loss, targeted MLH1 promoter methylation testing is efficient in terms of both material and clinical question.","Die Keimbahndiagnostik benötigt humangenetische Beratung und eine geeignete Normalprobe; Tumorgewebe allein reicht nicht.":"Germline testing requires genetic counseling and an appropriate normal sample; tumor tissue alone is insufficient.","MMR-IHC: MLH1 und PMS2 verloren, MSH2/MSH6 erhalten. Was ist der passende nächste Reflex im Endometriumkarzinom?":"MMR IHC: MLH1 and PMS2 lost, MSH2/MSH6 retained. What is the appropriate next reflex test in endometrial carcinoma?","MLH1-Promotormethylierung prüfen, um eine häufige sporadische MLH1-Inaktivierung zu erfassen.":"Assess MLH1 promoter methylation to identify a common sporadic mechanism of MLH1 inactivation.","BRAF V600E ist hier der Standardreflex wie beim CRC.":"BRAF V600E is the standard reflex here, just as in CRC.","Nur PD-L1 nachtesten; MMR-Muster ist für Lynch irrelevant.":"Only repeat PD-L1; the MMR pattern is irrelevant to Lynch.","Kein Reflex: MLH1/PMS2-Verlust beweist bereits Lynch.":"No reflex testing: MLH1/PMS2 loss already proves Lynch syndrome.","Beim Endometriumkarzinom ist die MLH1-Promotormethylierung der relevante Reflex bei MLH1/PMS2-Verlust.":"In endometrial carcinoma, MLH1 promoter methylation is the relevant reflex test for MLH1/PMS2 loss.","Was bedeutet dMMR/MSI-H therapeutisch?":"What does dMMR/MSI-H mean therapeutically?","Ein starker prädiktiver Immuntherapiekontext, dessen konkrete Nutzung von Stadium, Linie und aktueller Zulassung/Leitlinie abhängt.":"A strong predictive immunotherapy context whose specific use depends on stage, treatment line, and current approval/guideline.","Ohne hohen PD-L1-Score ist MSI-H therapeutisch bedeutungslos.":"Without a high PD-L1 score, MSI-H has no therapeutic significance.","MSI-H ist ausschließlich ein Lynch-Screeningmarker.":"MSI-H is exclusively a Lynch screening marker.","MSI-H beweist eine Keimbahn-MMR-Mutation.":"MSI-H proves a germline MMR mutation.","dMMR/MSI-H besitzt eine eigenständige prädiktive Bedeutung, unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"dMMR/MSI-H has independent predictive significance, regardless of whether the cause is sporadic or hereditary.","MLH1/PMS2-Verlust + MSI-H, aber keine MLH1-Promotormethylierung. Was folgt?":"MLH1/PMS2 loss + MSI-H, but no MLH1 promoter methylation. What follows?","Lynch-Syndrom bleibt verdächtig: humangenetische Beratung/Keimbahndiagnostik veranlassen, ohne Lynch bereits als bewiesen zu bezeichnen.":"Lynch syndrome remains suspected: arrange genetic counseling/germline testing without already labeling Lynch syndrome as proven.","Lynch-Syndrom ist damit sicher bewiesen.":"Lynch syndrome is now definitively proven.","Fehlende Methylierung beweist einen sporadischen Tumor.":"Absent methylation proves a sporadic tumor.","Nur ein negatives BRAF-Ergebnis kann jetzt Lynch ausschließen.":"Only a negative BRAF result can now exclude Lynch syndrome.","Tumorscreening stratifiziert den Verdacht; die Keimbahndiagnose ist ein separater Schritt.":"Tumor screening stratifies suspicion; the germline diagnosis is a separate step.","Warum ist BRAF V600E hier eine Falle?":"Why is BRAF V600E a trap here?","Der BRAF-Reflex gehört zur CRC-spezifischen MLH1/PMS2-Logik und ist beim Endometriumkarzinom kein adäquater Ersatz für MLH1-Promotormethylierung.":"The BRAF reflex belongs to the CRC-specific MLH1/PMS2 algorithm and is not an adequate substitute for MLH1 promoter methylation in endometrial carcinoma.","BRAF kann in keinem Endometriumtumor mutiert sein.":"BRAF can never be mutated in any endometrial tumor.","BRAF bestimmt hier ausschließlich die PD-L1-Expression.":"BRAF determines only PD-L1 expression here.","CRC- und Endometrium-Reflexalgorithmen sind identisch.":"CRC and endometrial reflex algorithms are identical.","Reflexdiagnostik ist entitätsspezifisch und darf nicht als universelles Rezept behandelt werden.":"Reflex diagnostics are entity-specific and must not be treated as a universal recipe.","Formulieren Sie eine integrierte MTB-/Befundaussage, die dMMR/MSI-H therapeutisch würdigt, den MLH1/PMS2-Verlust korrekt reflexdiagnostisch weiterführt und die Lynch-Frage sauber von der Tumordiagnostik trennt.":"Formulate an integrated MTB/report statement that appropriately reflects the therapeutic significance of dMMR/MSI-H, follows up MLH1/PMS2 loss with the correct reflex testing, and cleanly separates the Lynch question from tumor diagnostics.","MMR-IHC: MLH1/PMS2-Verlust benennen.":"MMR IHC: state MLH1/PMS2 loss.","MSI-H als konsistenten molekularen Befund bestätigen.":"Confirm MSI-H as a concordant molecular finding.","dMMR/MSI-H als prädiktiven IO-Kontext kommunizieren.":"Communicate dMMR/MSI-H as a predictive immunotherapy context.","MLH1-Promotormethylierung als entitätsspezifischen Reflex durchführen.":"Perform MLH1 promoter methylation as the entity-specific reflex test.","Fehlende MLH1-Methylierung als erhöhten Lynch-Verdacht, nicht als Beweis interpretieren.":"Interpret absent MLH1 methylation as increased suspicion for Lynch syndrome, not as proof.","Humangenetische Beratung/Keimbahndiagnostik empfehlen.":"Recommend genetic counseling/germline testing.","BRAF-V600E-CRC-Reflex ausdrücklich nicht übertragen.":"Explicitly do not transfer the CRC BRAF V600E reflex.","MSI kann molekular aus einem validierten Panel bestätigt werden, sofern MMR-IHC und MLH1-Methylierungsreflex trotzdem korrekt integriert werden.":"MSI may be molecularly confirmed from a validated panel, provided MMR IHC and the MLH1 methylation reflex are still correctly integrated.","Bei bereits qualitativ eindeutiger dMMR-IHC kann die therapeutische Kommunikation sofort erfolgen, während die hereditäre Reflexdiagnostik parallel abgeschlossen wird.":"If dMMR IHC is already unequivocal and technically sound, the therapeutic interpretation can be communicated immediately while hereditary reflex testing is completed in parallel.","BRAF wie beim CRC":"BRAF as in CRC","Entitätsspezifischer Reflexalgorithmus falsch übertragen.":"Entity-specific reflex algorithm incorrectly transferred.","MSI-H = Lynch":"MSI-H = Lynch","Viele dMMR/MSI-H-Tumoren sind sporadisch; Tumorscreening ist keine Keimbahndiagnose.":"Many dMMR/MSI-H tumors are sporadic; tumor screening is not a germline diagnosis.","Methylierungsnegativ = bewiesen erblich":"Methylation-negative = proven hereditary","Der Befund erhöht den Verdacht, beweist aber noch keine Keimbahnmutation.":"The result increases suspicion but does not yet prove a germline mutation.","PD-L1 priorisieren":"Prioritize PD-L1","dMMR/MSI-H ist hier der robustere Kernbiomarker; PD-L1 ist für die Lynch-Frage irrelevant.":"dMMR/MSI-H is the more robust core biomarker here; PD-L1 is irrelevant to the Lynch question.","Der CRC-Reflex wäre hier genau der falsche Automatismus":"The CRC reflex would be exactly the wrong automatic response here","MLH1/PMS2-Verlust und MSI-H wirken zunächst wie ein vertrauter CRC-Fall. Doch beim Endometriumkarzinom ist der sinnvolle Reflex die MLH1-Promotormethylierung – nicht BRAF V600E. Als die Methylierung negativ bleibt, steigt der Lynch-Verdacht deutlich, ohne bereits zur genetischen Diagnose zu werden.":"MLH1/PMS2 loss and MSI-H initially look like a familiar CRC case. But in endometrial carcinoma the appropriate reflex is MLH1 promoter methylation — not BRAF V600E. When methylation remains negative, suspicion for Lynch rises substantially without yet becoming a genetic diagnosis.","Der Fall trainiert zwei Kernkompetenzen gleichzeitig: entitätsspezifische Reflexdiagnostik und saubere Trennung von Tumor-Screening und Keimbahndiagnose.":"This case trains two core skills at once: entity-specific reflex diagnostics and a clean separation between tumor screening and germline diagnosis.","Therapie und Lynch-Pfad sauber getrennt":"Treatment and Lynch pathway cleanly separated","MLH1/PMS2-Verlust, MSI-H, keine MLH1-Promotormethylierung. dMMR/MSI-H als IO-relevant berichten; Lynch-Syndrom humangenetisch abklären. BRAF-CRC-Reflex nicht verwenden.":"MLH1/PMS2 loss, MSI-H, no MLH1 promoter methylation. Report dMMR/MSI-H as relevant for IO; pursue genetic evaluation for Lynch syndrome. Do not use the CRC BRAF reflex.","Beide klinischen Konsequenzen korrekt geführt.":"Both clinical consequences handled correctly.","IO erkannt, Lynch-Pfad unvollständig":"IO recognized, Lynch pathway incomplete","dMMR/MSI-H wird therapeutisch korrekt eingeordnet, MLH1-Methylierung/Genetik fehlen.":"dMMR/MSI-H is interpreted correctly therapeutically, but MLH1 methylation/genetic referral are missing.","Hereditäre Konsequenz verpasst.":"Hereditary consequence missed.","BRAF-Automatismus":"BRAF automatism","BRAF V600E wird als Standardreflex bestellt und ein negatives Ergebnis als Lynch-Beweis interpretiert.":"BRAF V600E is ordered as the standard reflex and a negative result is interpreted as proof of Lynch syndrome.","Entitätsspezifische Reflexdiagnostik und Keimbahnlogik verfehlt.":"Entity-specific reflex diagnostics and germline logic missed.","MLH1-Methylierung negativ":"MLH1 methylation negative","Humangenetische Beratung und Keimbahndiagnostik veranlassen.":"Arrange genetic counseling and germline testing.","Lynch-Syndrom kann bestätigt oder ausgeschlossen werden; Familienmanagement erst danach festlegen.":"Lynch syndrome can then be confirmed or excluded; family management should only be defined afterwards.","dMMR/MSI-H bestätigt":"dMMR/MSI-H confirmed","Therapieplanung mit aktuellem endometriumkarzinomspezifischem IO-Standard/Leitlinie abgleichen.":"Align treatment planning with the current endometrial-carcinoma-specific IO standard/guideline.","Prädiktiver Befund wird unabhängig von der noch offenen Keimbahnursache genutzt.":"The predictive finding can be used independently of the still unresolved germline cause.","dMMR/MSI-H kann zugleich Therapiebiomarker und Hinweis auf hereditäre Prädisposition sein.":"dMMR/MSI-H can simultaneously be a treatment biomarker and an indicator of hereditary predisposition.","MLH1/PMS2-Verlust lenkt die Reflexdiagnostik auf MLH1-Promotormethylierung.":"MLH1/PMS2 loss directs reflex testing toward MLH1 promoter methylation.","CRC-BRAF-Reflexe dürfen nicht automatisch auf das Endometriumkarzinom übertragen werden.":"CRC BRAF reflexes must not automatically be transferred to endometrial carcinoma.","Fehlende MLH1-Methylierung erhöht den Lynch-Verdacht, beweist aber keine Keimbahnmutation.":"Absent MLH1 methylation increases suspicion for Lynch syndrome but does not prove a germline mutation.","Tumorbiomarker und Humangenetik laufen parallel, aber diagnostisch getrennt.":"Tumor biomarkers and medical genetics proceed in parallel but remain diagnostically separate.","MLH1/PMS2-Verlust + MSI-H = dMMR/MSI-H und damit therapeutisch relevant. Beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex; hier negativ. Deshalb Lynch-Syndrom humangenetisch abklären, aber nicht bereits diagnostizieren. BRAF V600E ist kein adäquater Ersatzreflex.":"MLH1/PMS2 loss + MSI-H = dMMR/MSI-H and therefore therapeutically relevant. In endometrial carcinoma use MLH1 promoter methylation as the reflex test; here it is negative. Therefore pursue genetic evaluation for Lynch syndrome, but do not diagnose it yet. BRAF V600E is not an adequate substitute reflex.","MMR-Muster korrekt":"MMR pattern correct","MLH1-Methylierungsreflex":"MLH1 methylation reflex","IO-Relevanz":"IO relevance","Lynch-Verdacht ≠ Diagnose":"Lynch suspicion ≠ diagnosis","BRAF-Copyover vermieden":"BRAF copyover avoided","Warum fallen MLH1 und PMS2 gemeinsam aus?":"Why are MLH1 and PMS2 lost together?","Warum unterscheidet sich der Reflexalgorithmus zwischen CRC und Endometrium?":"Why does the reflex algorithm differ between CRC and endometrial carcinoma?","Welche Information darf bereits im Tumorbefund stehen und welche erst nach Keimbahndiagnostik?":"Which information may already appear in the tumor report, and which only after germline testing?","MLH1/PMS2-Verlust + keine MLH1-Methylierung":"MLH1/PMS2 loss + no MLH1 methylation","dMMR ist Therapiebiomarker und Lynch-Screening, aber Entität bestimmt den Reflex":"dMMR is both a treatment biomarker and Lynch screen, but the tumor entity determines the reflex","MMR-IHC → MSI → MLH1-Methylierung → Humangenetik":"MMR IHC → MSI → MLH1 methylation → medical genetics","Antibiotika kurz vor ICI, Mikrobiom-Frage im Tumorboard → Evidenz korrekt begrenzen":"Antibiotics shortly before ICI, microbiome question in the tumor board → appropriately limit the evidence","Antibiotika kurz vor ICI, Mikrobio…":"Antibiotics shortly before ICI, microbio…","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom. PD-L1 TPS 80 %. Vor Beginn der geplanten Immuntherapie musste er wegen einer mikrobiologisch gesicherten bakteriellen Pneumonie sieben Tage breit antibiotisch behandelt werden.":"72-year-old man with metastatic pulmonary adenocarcinoma. PD-L1 TPS 80%. Before the planned start of immunotherapy, he required seven days of broad-spectrum antibiotics for microbiologically confirmed bacterial pneumonia.","Soll die notwendige Antibiotikatherapie wegen möglicher Mikrobiom-Effekte die ICI-Entscheidung verändern, verzögern oder durch Mikrobiom-Interventionen 'kompensiert' werden?":"Should necessary antibiotic therapy, because of possible microbiome effects, change or delay the ICI decision, or be 'compensated' by microbiome interventions?","Die Pneumonie ist klinisch abgeheilt; Systemtherapie soll zeitnah beginnen.":"The pneumonia has clinically resolved; systemic therapy should start promptly.","Tumor":"Tumor","Metastasiertes Lungenadenokarzinom, ECOG 1.":"Metastatic lung adenocarcinoma, ECOG 1.","Treiberdiagnostik":"Driver testing","Breites DNA/RNA-Profil ohne etablierte actionable Driveralteration; ALK/ROS1/RET/NTRK/METex14/EGFR etc. ohne therapieentscheidenden Befund.":"Broad DNA/RNA profiling without an established actionable driver alteration; ALK/ROS1/RET/NTRK/METex14/EGFR etc. without a treatment-defining finding.","TPS 80 %, technisch valide.":"TPS 80%, technically valid.","Antibiotika":"Antibiotics","Piperacillin/Tazobactam, anschließend orale Komplettierung wegen gesicherter bakterieller Pneumonie; Therapie war klinisch indiziert.":"Piperacillin/tazobactam followed by oral completion for confirmed bacterial pneumonia; treatment was clinically indicated.","Eine populationsbasierte Assoziation zwischen Antibiotika/Mikrobiom und ICI-Outcome wird zur individuellen Kontraindikation oder zum Anlass für unvalidierte Probiotika/FMT gemacht.":"A population-level association between antibiotics/microbiome and ICI outcome is turned into an individual contraindication or a reason for unvalidated probiotics/FMT.","Pulmonales Adenokarzinom, TTF-1/Napsin A positiv.":"Pulmonary adenocarcinoma, TTF-1/Napsin A positive.","TPS 80 %.":"TPS 80%.","Molekularprofil":"Molecular profile","DNA/RNA-basierte Treiberdiagnostik ohne etablierte Targetalteration.":"DNA/RNA-based driver testing without an established targetable alteration.","Nicht die Tumordiagnostik, sondern die Evidenzstärke der Mikrobiom-/Antibiotika-Assoziation und ihre Konsequenz für die individuelle Therapie.":"The key issue is not tumor testing, but the strength of evidence for the microbiome/antibiotic association and its consequence for the individual treatment decision.","Kleine Bronchialbiopsie; wesentliche Treiber- und PD-L1-Diagnostik bereits vollständig.":"Small bronchial biopsy; essential driver and PD-L1 testing already complete.","Restmaterial":"Remaining material","Nur noch begrenzt verfügbar.":"Only limited material remains.","Zusätzliche TMB-/TIL-/Breitdiagnostik kann den Effekt einer Antibiotikatherapie auf das Darmmikrobiom nicht valide quantifizieren und erzeugt keine etablierte 'ICI-Freigabe'.":"Additional TMB/TIL/broad testing cannot validly quantify the effect of antibiotic therapy on the gut microbiome and does not generate an established 'ICI clearance'.","Klinische Ressource":"Clinical resource","Der wichtigste Zusatzdatensatz ist hier die Indikation und zeitliche Einordnung der Antibiotikatherapie – nicht noch ein Tumortest.":"The most important additional dataset here is the indication and timing of antibiotic therapy — not another tumor test.","Validierter Tumor-/ICI-Kontext":"Validated tumor/ICI context","PD-L1 TPS 80 % bestätigt. Der Marker bleibt ein etablierter Bestandteil der NSCLC-Therapieplanung im passenden driver-negativen Kontext.":"PD-L1 TPS 80% confirmed. The marker remains an established component of NSCLC treatment planning in the appropriate driver-negative context.","Treiberprofil":"Driver profile","Keine etablierte actionable Driveralteration nach integrierter DNA/RNA-Diagnostik. Die hohe PD-L1-Expression wird damit nicht durch einen offensichtlichen targetierbaren Treiberkontext verdrängt.":"No established actionable driver alteration after integrated DNA/RNA testing. High PD-L1 expression is therefore not displaced by an obvious targetable driver context.","TMB intermediär (7 Mut/Mb). Dieser Wert beantwortet die Antibiotika-/Mikrobiomfrage nicht und ersetzt die validierte NSCLC-Biomarkerhierarchie nicht.":"TMB intermediate (7 mut/Mb). This value does not answer the antibiotic/microbiome question and does not replace the validated NSCLC biomarker hierarchy.","Mäßiges CD8-Infiltrat. Auch dieser Befund erlaubt keine patientenspezifische Quantifizierung eines möglichen Antibiotikaeffekts auf ICI-Wirksamkeit.":"Moderate CD8 infiltrate. This finding also cannot quantify a patient-specific effect of antibiotics on ICI efficacy.","Antibiotikaanamnese":"Antibiotic history","Sieben Tage notwendige Antibiotikatherapie wegen gesicherter bakterieller Pneumonie unmittelbar vor geplantem ICI-Beginn.":"Seven days of necessary antibiotic therapy for confirmed bacterial pneumonia immediately before planned ICI initiation.","Infektion abgeheilt; Patient therapiefähig.":"Infection resolved; patient fit for therapy.","Evidenzkonflikt":"Evidence conflict","Beobachtungsdaten zeigen Assoziationen zwischen Antibiotikaexposition und schlechteren ICI-Outcomes, beweisen aber für den individuellen Patienten keine kausale Therapieresistenz.":"Observational data show associations between antibiotic exposure and poorer ICI outcomes, but do not prove causal treatment resistance in an individual patient.","Driver-negatives metastasiertes NSCLC mit hoher PD-L1-Expression. Die kürzlich notwendige Antibiotikatherapie ist als möglicher prognostischer/biologischer Kontext diskutierbar, stellt aber keine validierte individuelle Kontraindikation gegen eine indizierte Checkpoint-Therapie dar. Eine klinisch notwendige bakterielle Infektion durfte nicht unbehandelt bleiben. Unnötige Antibiotika sollten vermieden werden; Mikrobiomtests, Probiotika oder FMT sind nicht als routinemäßige Kompensationsstrategie validiert und gehören – sofern überhaupt – in Studien.":"Driver-negative metastatic NSCLC with high PD-L1 expression. Recent necessary antibiotic therapy can be discussed as a possible prognostic/biological context, but it is not a validated individual contraindication to indicated checkpoint therapy. A clinically necessary bacterial infection should not have been left untreated. Unnecessary antibiotics should be avoided; microbiome testing, probiotics, or FMT are not validated as routine compensation strategies and belong, if at all, in clinical trials.","Teilbefund: Die Mikrobiom-Assoziation wird erwähnt, aber ohne Trennung von Kausalität, Konfounding, klinischer Antibiotikaindikation und validierten Tumorbiomarkern bleibt die Empfehlung unsauber.":"Partial interpretation: the microbiome association is mentioned, but without separating causality, confounding, the clinical indication for antibiotics, and validated tumor biomarkers, the recommendation remains imprecise.","PD-L1 und vollständigen Driverstatus als etablierte NSCLC-Biomarkerhierarchie priorisieren":"Prioritize PD-L1 and complete driver status as the established NSCLC biomarker hierarchy","Antibiotika/ICI als Assoziation mit möglichem Confounding, nicht als individuellen Resistenztest erklären":"Explain antibiotics/ICI as an association with possible confounding, not as an individual resistance test","klinisch notwendige Antibiotikatherapie nicht retrospektiv als Fehler darstellen":"Do not retrospectively frame clinically necessary antibiotic therapy as an error","keine unvalidierte Mikrobiomdiagnostik, Probiotika oder FMT als Routineempfehlung aussprechen":"Do not recommend unvalidated microbiome testing, probiotics, or FMT as routine care","Falschaussage: Antibiotika kurz vor ICI sind eine absolute Kontraindikation gegen Immuntherapie":"False statement: antibiotics shortly before ICI are an absolute contraindication to immunotherapy","Optimale Lösung: Hohe PD-L1-Expression und driver-negativer NSCLC-Kontext bleiben die belastbaren Therapiebiomarker. Die notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext zu erwähnen, aber nicht als validierte individuelle Kontraindikation. Keine unvalidierten Mikrobiom-Interventionen außerhalb von Studien.":"Optimal solution: high PD-L1 expression and a driver-negative NSCLC context remain the reliable treatment biomarkers. Necessary antibiotic therapy should be mentioned as a possible outcome context, but not as a validated individual contraindication. No unvalidated microbiome interventions outside trials.","Mikrobiom":"Microbiome","ICI":"ICI","Confounding":"Confounding","Antibiotika vor ICI: relevante Assoziation, aber keine patientenindividuelle Kontraindikation":"Antibiotics before ICI: relevant association, but not an individual patient contraindication","Beobachtungsassoziation, Kausalität und Confounding in der Mikrobiom-/ICI-Literatur unterscheiden.":"Distinguish observational association, causality, and confounding in the microbiome/ICI literature.","Validierte NSCLC-Tumorbiomarker gegenüber unvalidierten Mikrobiom-Surrogaten priorisieren.":"Prioritize validated NSCLC tumor biomarkers over unvalidated microbiome surrogates.","Klinisch notwendige Antibiotikatherapie nicht retrospektiv als vermeidbaren onkologischen Fehler behandeln.":"Do not retrospectively treat clinically necessary antibiotic therapy as an avoidable oncologic error.","Eine vorausgegangene Antibiotikaexposition nicht als absolute ICI-Kontraindikation formulieren.":"Do not formulate prior antibiotic exposure as an absolute contraindication to ICI.","Mikrobiomtests, Probiotika und FMT als experimentell statt als Routinetherapie einordnen.":"Classify microbiome testing, probiotics, and FMT as experimental rather than routine therapy.","Der Patient hat genau den Tumor, bei dem das Team an Checkpoint-Therapie denkt: driver-negatives NSCLC, PD-L1 TPS 80 %. Dann fällt im Medikamentenplan auf, dass er in der Vorwoche sieben Tage Breitbandantibiotika bekommen hat. Sofort steht die Frage im Raum: 'Haben wir damit die Immuntherapie kaputtgemacht?' Der Fall dreht sich weniger um einen weiteren Labortest als um Evidenzkompetenz.":"The patient has exactly the kind of tumor for which the team is considering checkpoint therapy: driver-negative NSCLC, PD-L1 TPS 80%. Then the medication list reveals that he received seven days of broad-spectrum antibiotics the previous week. The immediate question is: 'Have we ruined the immunotherapy?' The case is less about ordering another laboratory test than about evidence literacy.","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom, vollständiger DNA/RNA-Treiberdiagnostik ohne actionable Alteration und PD-L1 TPS 80 %. Unmittelbar vor geplantem ICI-Beginn wurde eine mikrobiologisch gesicherte Pneumonie leitliniengerecht antibiotisch behandelt. Das MTB soll entscheiden, ob dies die Immuntherapie verändert und wie Mikrobiomdaten klinisch korrekt begrenzt werden.":"72-year-old man with metastatic pulmonary adenocarcinoma, complete DNA/RNA driver testing without actionable alteration, and PD-L1 TPS 80%. Immediately before planned ICI initiation, a microbiologically confirmed pneumonia was treated appropriately with antibiotics. The MTB must decide whether this changes immunotherapy and how microbiome data should be appropriately constrained clinically.","Starker etablierter Tumorbiomarker":"Strong established tumor biomarker","PD-L1 TPS 80 %, kein etablierter actionable Driver.":"PD-L1 TPS 80%, no established actionable driver.","Die Therapieplanung basiert zunächst auf validierten Tumor- und Klinikfaktoren.":"Treatment planning is based first on validated tumor and clinical factors.","Reale Mikrobiomassoziation":"Real microbiome association","Antibiotikaexposition um ICI-Beginn ist in Kohorten mit schlechterem Outcome assoziiert.":"Antibiotic exposure around ICI initiation is associated with poorer outcomes in cohorts.","Assoziation kann biologisch plausibel sein und trotzdem durch Infektion, Krankheitslast oder andere Faktoren konfundiert werden.":"An association can be biologically plausible and still be confounded by infection, disease burden, or other factors.","Klinische Indikation zählt":"Clinical indication matters","Die Pneumonie war gesichert und behandlungsbedürftig.":"The pneumonia was confirmed and required treatment.","Ein notwendiges Antibiotikum wird nicht dadurch falsch, dass es möglicherweise das Mikrobiom beeinflusst.":"A necessary antibiotic does not become wrong simply because it may influence the microbiome.","DNA/RNA-Treiberprofil":"DNA/RNA driver profile","Kein etablierter actionable Driver.":"No established actionable driver.","Sieben Tage wegen gesicherter bakterieller Pneumonie; Infektion jetzt abgeheilt.":"Seven days for confirmed bacterial pneumonia; infection now resolved.","Restmaterial ist knapp; zusätzliche Tumortests beantworten die Mikrobiomfrage nicht valide.":"Remaining material is scarce; additional tumor tests do not validly answer the microbiome question.","Der Simulator enthält bewusst keinen 'Mikrobiom-ICI-Freigabetest', weil hierfür kein etablierter Routineassay mit validiertem Cutoff existiert.":"The simulator deliberately contains no 'microbiome ICI clearance test' because no established routine assay with a validated cutoff exists for this purpose.","Die entscheidende Zusatzinformation ist klinisch: Indikation, Zeitpunkt, Dauer und Infektionsstatus.":"The decisive additional information is clinical: indication, timing, duration, and infection status.","Was lässt sich aus der Beobachtung 'Antibiotika um ICI-Beginn sind mit schlechterem Outcome assoziiert' für diesen Patienten ableiten?":"What can be inferred for this patient from the observation that 'antibiotics around ICI initiation are associated with poorer outcome'?","Es ist ein relevanter möglicher Risiko-/Biologiekontext, aber kein kausaler individueller Resistenztest; Confounding durch Infektion und Krankheitsstatus muss bedacht werden.":"It is a relevant possible risk/biological context, but not a causal individual resistance test; confounding by infection and disease status must be considered.","Antibiotika beweisen, dass ICI nicht mehr wirken kann.":"Antibiotics prove that ICI can no longer work.","Beobachtungsdaten sind grundsätzlich wertlos und dürfen nie erwähnt werden.":"Observational data are fundamentally worthless and should never be mentioned.","ICI muss nach jeder Antibiotikagabe zwingend für einen festen Zeitraum verschoben werden.":"ICI must always be postponed for a fixed period after any antibiotic course.","Beobachtungsassoziationen sind klinisch relevant, aber nicht gleichbedeutend mit kausaler patientenindividueller Vorhersage.":"Observational associations are clinically relevant but are not equivalent to causal, patient-specific prediction.","War die Antibiotikatherapie onkologisch ein Fehler?":"Was the antibiotic therapy an oncologic mistake?","Nein. Eine gesicherte bakterielle Pneumonie musste behandelt werden; unnötige Antibiotika sollten vermieden werden, notwendige aber nicht aus Mikrobiomangst vorenthalten werden.":"No. Confirmed bacterial pneumonia required treatment; unnecessary antibiotics should be avoided, but necessary treatment should not be withheld out of fear of microbiome effects.","Ja. Vor ICI dürfen Antibiotika nie gegeben werden.":"Yes. Antibiotics must never be given before ICI.","Nur wenn gleichzeitig FMT gegeben wird, war sie vertretbar.":"It was acceptable only if FMT was given at the same time.","Bei PD-L1 80 % ist eine Infektionsbehandlung generell unwichtig.":"With PD-L1 80%, treating an infection is generally unimportant.","Patientensicherheit und Behandlung einer realen Infektion haben Vorrang vor nicht validierter Mikrobiomoptimierung.":"Patient safety and treatment of a real infection take priority over unvalidated microbiome optimization.","Soll jetzt routinemäßig ein Mikrobiomtest, Probiotikum oder FMT zur 'Rettung' der ICI-Wirkung veranlasst werden?":"Should a microbiome test, probiotic, or FMT now be routinely ordered to 'rescue' ICI efficacy?","Nein. Solche Strategien sind derzeit nicht als routinemäßige patientenindividuelle Kompensation validiert und gehören gegebenenfalls in Studien.":"No. Such strategies are not currently validated as routine patient-specific compensation and, if considered at all, belong in clinical trials.","FMT ist nach Antibiotika vor ICI Standard.":"FMT is standard after antibiotics before ICI.","Ein frei verkäufliches Probiotikum ist evidenzbasiert obligat.":"An over-the-counter probiotic is evidence-based and mandatory.","Ein einzelnes 16S-Profil kann zuverlässig die ICI-Wirkung vorhersagen.":"A single 16S profile can reliably predict ICI efficacy.","Mikrobiominterventionen sind ein Forschungsfeld, kein etablierter Routinealgorithmus zur ICI-Freigabe.":"Microbiome interventions are a research field, not an established routine algorithm for ICI clearance.","Welche Information sollte die Therapieentscheidung stärker tragen?":"Which information should carry more weight in the treatment decision?","Validierter NSCLC-Kontext aus Histologie, vollständigem Driverprofil, PD-L1, Klinik und Infektionsstatus; Antibiotikaexposition als zusätzlicher Unsicherheits-/Risikokontext.":"Validated NSCLC context from histology, complete driver profile, PD-L1, clinical status, and infection status; antibiotic exposure as an additional uncertainty/risk context.","Allein die Antibiotikaexposition.":"Antibiotic exposure alone.","Ein zusätzlicher TMB-Wert unabhängig von PD-L1 und Driverstatus.":"An additional TMB value regardless of PD-L1 and driver status.","Ein experimentelles Darmmikrobiomprofil.":"An experimental gut microbiome profile.","Evidenzhierarchie verhindert, dass ein interessanter Forschungsmarker etablierte Therapiebiomarker verdrängt.":"An evidence hierarchy prevents an interesting research marker from displacing established treatment biomarkers.","Formulieren Sie eine MTB-Empfehlung, die die Antibiotika-/Mikrobiomassoziation ernst nimmt, aber die individuelle Therapieentscheidung auf validierte NSCLC-Biomarker und den aktuellen klinischen Zustand stützt.":"Formulate an MTB recommendation that takes the antibiotic/microbiome association seriously but bases the individual treatment decision on validated NSCLC biomarkers and the current clinical status.","Driver-negatives NSCLC und PD-L1 TPS 80 % als validierten Tumorkontext priorisieren.":"Prioritize driver-negative NSCLC and PD-L1 TPS 80% as the validated tumor context.","Antibiotikaexposition zeitlich und indikationsbezogen dokumentieren.":"Document antibiotic exposure with timing and indication.","Assoziation mit schlechterem ICI-Outcome als Beobachtungsbefund mit möglichem Confounding erklären.":"Explain the association with poorer ICI outcomes as an observational finding with possible confounding.","Notwendige Infektionsbehandlung nicht als Fehler darstellen.":"Do not portray necessary infection treatment as an error.","Keine absolute ICI-Kontraindikation oder fixe Wartezeit allein aus Antibiotika ableiten.":"Do not derive an absolute ICI contraindication or a fixed waiting period from antibiotics alone.","Keine routinemäßigen Mikrobiomtests/Probiotika/FMT außerhalb validierter Indikation bzw. klinischer Studien empfehlen.":"Do not recommend routine microbiome tests/probiotics/FMT outside a validated indication or clinical trial.","Wenn nach Abheilung der Infektion klinische Gründe für eine kurze Verzögerung bestehen, diese klinisch und nicht als 'Mikrobiom-Washout' begründen.":"If there are clinical reasons for a brief delay after infection resolution, justify them clinically rather than as a 'microbiome washout'.","Mikrobiomstudie anbieten, sofern verfügbar und ohne die Standardtherapie unangemessen zu verzögern.":"Offer a microbiome study if available, provided standard therapy is not inappropriately delayed.","Antibiotika = absolute ICI-Kontraindikation":"Antibiotics = absolute ICI contraindication","Dafür existiert kein validierter patientenindividueller Entscheidungsalgorithmus.":"No validated patient-specific decision algorithm exists for this.","Notwendige Infektion unbehandelt lassen":"Leave a necessary infection untreated","Patientensicherheit und Infektionskontrolle haben Vorrang.":"Patient safety and infection control take priority.","FMT/Probiotika als Routine":"FMT/probiotics as routine care","Experimentelle Interventionen dürfen nicht als Standard verkauft werden.":"Experimental interventions must not be presented as standard care.","Mehr Tumortests bestellen":"Order more tumor tests","TMB/TILs quantifizieren keinen individuellen Antibiotika-Mikrobiomeffekt.":"TMB/TILs do not quantify an individual antibiotic-microbiome effect.","Das Antibiotikum war möglicherweise biologisch ungünstig – und trotzdem medizinisch richtig":"The antibiotic may have been biologically unfavorable — and still medically correct","Die Literaturassoziation ist plausibel und soll nicht weggewischt werden. Gleichzeitig war die Pneumonie mikrobiologisch gesichert und behandlungsbedürftig. Der zentrale Twist ist daher epistemisch: Ein möglicher negativer Biomarker-/Expositionskontext macht eine notwendige Behandlung nicht falsch und liefert keine validierte individuelle ICI-Kontraindikation.":"The association in the literature is plausible and should not be dismissed. At the same time, the pneumonia was microbiologically confirmed and required treatment. The central twist is therefore epistemic: a potentially unfavorable biomarker/exposure context does not make a necessary treatment wrong and does not provide a validated individual ICI contraindication.","Der Fall trainiert Evidenzstufen, Confounding und die Fähigkeit, populationsbasierte Forschung nicht in überharte Einzelpatientenregeln zu übersetzen.":"The case trains evidence grading, confounding, and the ability not to turn population-based research into overly rigid rules for individual patients.","Evidenz sauber begrenzt":"Evidence appropriately bounded","Driver-negatives NSCLC, PD-L1 TPS 80 %. Antibiotika wegen gesicherter Pneumonie waren notwendig. Exposition als möglicher Outcome-Kontext erwähnen, aber keine absolute ICI-Kontraindikation oder Mikrobiom-Routineintervention ableiten.":"Driver-negative NSCLC, PD-L1 TPS 80%. Antibiotics for confirmed pneumonia were necessary. Mention exposure as a possible outcome context, but do not derive an absolute ICI contraindication or routine microbiome intervention.","Validierte Biomarker und unsichere Exposition korrekt gewichtet.":"Validated biomarkers and uncertain exposure weighted appropriately.","Assoziation erkannt, aber zu viel Unsicherheit":"Association recognized, but too much uncertainty","Antibiotikadaten werden erwähnt, die Therapie wird jedoch ohne belastbare Grundlage allein deshalb unbestimmt verschoben.":"Antibiotic data are mentioned, but treatment is then postponed indefinitely solely on this basis without robust justification.","Beobachtungsdaten zu stark operationalisiert.":"Observational data over-operationalized.","ICI gestrichen, FMT empfohlen":"ICI cancelled, FMT recommended","Antibiotika werden als Beweis für ICI-Resistenz behandelt und FMT/Probiotika als Routine empfohlen.":"Antibiotics are treated as proof of ICI resistance, and FMT/probiotics are recommended as routine care.","Evidenzniveau und Patientensicherheit verfehlt.":"Evidence level and patient safety missed.","Infektion klinisch abgeheilt":"Infection clinically resolved","Systemtherapie nach regulären onkologischen Kriterien planen; keine fixe 'Mikrobiom-Wartezeit' erfinden.":"Plan systemic therapy according to standard oncologic criteria; do not invent a fixed 'microbiome waiting period'.","Die Therapie wird nicht aufgrund unvalidierter Surrogate unangemessen verzögert.":"Treatment is not inappropriately delayed because of unvalidated surrogates.","künftige Antibiotikafrage":"Future antibiotic question","Antibiotic stewardship: unnötige Exposition vermeiden, notwendige Infektionen zielgerichtet behandeln.":"Antibiotic stewardship: avoid unnecessary exposure and treat necessary infections in a targeted manner.","Pragmatische Risikoreduktion ohne Pseudopräzision.":"Pragmatic risk reduction without pseudo-precision.","Mikrobiomstudie verfügbar":"Microbiome study available","Teilnahme als Forschungsoption diskutieren.":"Discuss participation as a research option.","Innovative Ansätze bleiben im passenden Evidenzrahmen.":"Innovative approaches remain within the appropriate evidence framework.","Antibiotikaexposition um ICI ist in Beobachtungsdaten mit schlechteren Outcomes assoziiert, aber Confounding ist relevant.":"Antibiotic exposure around ICI is associated with poorer outcomes in observational data, but confounding is relevant.","Eine klinisch notwendige Antibiotikatherapie darf nicht aus Angst vor Mikrobiomeffekten vorenthalten werden.":"Clinically necessary antibiotic therapy must not be withheld out of fear of microbiome effects.","Es gibt keinen etablierten Routine-Mikrobiomtest, der nach Antibiotika die individuelle ICI-Wirkung freigibt oder ausschließt.":"There is no established routine microbiome test that can clear or rule out individual ICI efficacy after antibiotics.","FMT/Probiotika zur ICI-Optimierung sind Forschungsansätze, keine Standardkompensation.":"FMT/probiotics to optimize ICI are research approaches, not standard compensation.","Präzisionsonkologie bedeutet auch, Evidenzgrenzen präzise zu kommunizieren.":"Precision oncology also means communicating the limits of evidence precisely.","PD-L1 TPS 80 % bei driver-negativem NSCLC bleibt ein etablierter Therapiebiomarkerkontext. Die kürzlich notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext relevant, aber keine validierte individuelle Kontraindikation. Keine unvalidierte fixe Wartezeit oder routinemäßige Mikrobiomintervention ableiten; unnötige Antibiotika künftig vermeiden, notwendige behandeln.":"PD-L1 TPS 80% in driver-negative NSCLC remains an established treatment-biomarker context. Recent necessary antibiotic therapy is relevant as a possible outcome context, but not as a validated individual contraindication. Do not infer an unvalidated fixed waiting period or routine microbiome intervention; avoid unnecessary antibiotics in future and treat those that are necessary.","Assoziation ≠ Kausalität":"Association ≠ causality","Confounding erkannt":"Confounding recognized","Patientensicherheit":"Patient safety","validierte Biomarker priorisiert":"Validated biomarkers prioritized","keine unvalidierte Mikrobiomtherapie":"No unvalidated microbiome therapy","Welche Confounder erklären die Antibiotika-ICI-Assoziation möglicherweise mit?":"Which confounders might partly explain the antibiotic-ICI association?","Wann wird aus einem prognostischen Faktor ein prädiktiver Biomarker?":"When does a prognostic factor become a predictive biomarker?","Wie kommuniziert man interessante, aber nicht handlungsleitende Forschung im MTB?":"How do you communicate interesting but non-action-guiding research in the MTB?","notwendige Antibiotikatherapie trotz möglicher negativer Assoziation":"Necessary antibiotic therapy despite a potentially negative association","Populationsassoziation ist keine individuelle Kontraindikation":"Population association is not an individual contraindication","validierte Tumorbiomarker → Antibiotikaindikation → Evidenzgrad → keine Pseudopräzision":"validated tumor biomarkers → antibiotic indication → evidence level → no pseudo-precision","IDH-mutiertes Gliom: R132H-IHC negativ – und trotzdem IDH-mutiert":"IDH-mutant glioma: R132H IHC negative — yet still IDH-mutant","IDH-mutiertes Gliom mit G-CIMP-Pro…":"IDH-mutant glioma with G-CIMP prof…","Neuropathologie / Neuroonkologisches Tumorboard":"Neuropathology / Neuro-oncology tumor board","36-jähriger Patient nach Resektion eines linksfrontalen diffus infiltrierenden Glioms. Die IDH1-R132H-IHC ist negativ; Alter und Morphologie passen jedoch schlecht zu einem typischen IDH-Wildtyp-Glioblastom.":"36-year-old man after resection of a left frontal diffusely infiltrating glioma. IDH1 R132H IHC is negative; however, age and morphology fit poorly with a typical IDH-wildtype glioblastoma.","Darf der Tumor nach negativer R132H-IHC als IDH-Wildtyp eingeordnet werden – und welche Rolle spielt das Methylierungsprofil?":"May the tumor be classified as IDH-wildtype after negative R132H IHC — and what role does the methylation profile play?","Die integrierte Diagnose soll vor Festlegung der adjuvanten Therapie finalisiert werden.":"The integrated diagnosis should be finalized before adjuvant treatment is determined.","Erstmanifestation mit fokalem Krampfanfall; MRT zeigt einen nicht kontrastmittelaufnehmenden frontalen Tumor.":"Initial presentation with focal seizure; MRI shows a non-enhancing frontal tumor.","36 Jahre – damit ist eine nicht-kanonische IDH-Alteration klinisch relevant genug, um nach negativer R132H-IHC nicht vorschnell abzubrechen.":"Age 36 — making a non-canonical IDH alteration clinically relevant enough not to stop prematurely after negative R132H IHC.","ATRX-Verlust und diffuse p53-Überexpression; 1p/19q-Kodeletion nicht nachweisbar.":"ATRX loss and diffuse p53 overexpression; no 1p/19q codeletion detected.","Eine negative mutationsspezifische IHC wird mit einem negativen Genstatus gleichgesetzt.":"A negative mutation-specific IHC result is equated with a negative gene status.","Diffus infiltrierendes astrozytäres Gliom, mäßige Zelldichte, keine Nekrosen oder mikrovaskuläre Proliferation.":"Diffusely infiltrating astrocytic glioma, moderate cellularity, no necrosis or microvascular proliferation.","IDH1 R132H negativ; ATRX nukleär verloren; p53 in großer Tumorzellfraktion stark positiv.":"IDH1 R132H negative; nuclear ATRX loss; strong p53 positivity in a large tumor-cell fraction.","Molekulare Vorinformation":"Prior molecular information","1p/19q intakt.":"1p/19q intact.","Nicht-kanonische IDH1/2-Mutation? Passt das epigenetische Gesamtprofil zu einem IDH-mutierten Astrozytom?":"Non-canonical IDH1/2 mutation? Does the overall epigenetic profile fit an IDH-mutant astrocytoma?","FFPE-Resektat, Block F6.":"FFPE resection specimen, block F6.","ca. 70 %, sehr gut geeignet.":"approx. 70%, very well suited.","ausreichend für Sequenzierung und Methylierungsprofil.":"sufficient for sequencing and methylation profiling.","Eine fokale Bisulfit-PCR kann einzelne CpG-Loci untersuchen, ersetzt aber keinen genomeweiten CNS-Methylierungsclassifier.":"A focal bisulfite PCR can examine individual CpG loci but does not replace a genome-wide CNS methylation classifier.","IDH1/2-Status vollständig klären":"Fully resolve IDH1/2 status","CNS-Methylierungsprofil / Classifier":"CNS methylation profile / classifier","IDH1-R132H-IHC negativ; Sequenzierung zeigt eine pathogene nicht-kanonische IDH1-p.R132C-Mutation. Die negative R132H-IHC war daher kein Ausschluss eines IDH-mutierten Glioms.":"IDH1 R132H IHC negative; sequencing shows a pathogenic non-canonical IDH1 p.R132C mutation. The negative R132H IHC therefore did not exclude an IDH-mutant glioma.","Methylierungsclassifier":"Methylation classifier","Genomeweites Methylierungsprofil mit hochkonfidenter Zuordnung zur Familie der IDH-mutierten Astrozytome und ausgeprägtem G-CIMP-typischem Hypermethylierungsmuster.":"Genome-wide methylation profile with high-confidence assignment to the family of IDH-mutant astrocytomas and a pronounced G-CIMP-like hypermethylation pattern.","Fokale Bisulfit-PCR":"Focal bisulfite PCR","Ein fokaler Methylierungsmarker ist messbar, erlaubt aber keine gleichwertige globale Tumorklassifikation und ist kein Ersatz für den CNS-Methylierungsclassifier.":"A focal methylation marker can be measured, but does not provide an equivalent global tumor classification and is not a substitute for the CNS methylation classifier.","Breites Panel":"Broad panel","Zusätzliche Varianten ändern die zentrale integrierte Einordnung nicht; der breite Ansatz ist für die konkrete Klassifikationsfrage nicht zwingend erforderlich.":"Additional variants do not change the central integrated classification; a broad approach is not strictly required for the specific classification question.","Diffus infiltrierendes Astrozytom mit ATRX-Verlust und p53-Akkumulation; keine hochgradigen morphologischen Kriterien.":"Diffusely infiltrating astrocytoma with ATRX loss and p53 accumulation; no high-grade morphologic criteria.","Tumoranteil und DNA-Qualität für Sequenzierung und Methylom geeignet.":"Tumor fraction and DNA quality suitable for sequencing and methylome analysis.","Die negative IDH1-R132H-IHC schließt bei diesem jungen Patienten eine IDH-Mutation nicht aus. Die Sequenzierung weist eine nicht-kanonische IDH1-p.R132C-Mutation nach; das genomeweite Methylierungsprofil unterstützt einen IDH-mutierten astrozytären Tumor und zeigt das erwartete G-CIMP-artige Hypermethylierungsmuster. Der Methylierungsclassifier ergänzt die integrierte Diagnose, ersetzt aber nicht Histologie und definierende molekulare Marker.":"Negative IDH1 R132H IHC does not exclude an IDH mutation in this young patient. Sequencing identifies a non-canonical IDH1 p.R132C mutation; the genome-wide methylation profile supports an IDH-mutant astrocytic tumor and shows the expected G-CIMP-like hypermethylation pattern. The methylation classifier complements the integrated diagnosis but does not replace histology and defining molecular markers.","Teilbefund: Eine negative R132H-IHC allein reicht nicht, um den IDH-Status in diesem klinisch-morphologischen Kontext sicher festzulegen.":"Partial result: negative R132H IHC alone is insufficient to establish IDH status with certainty in this clinical-morphologic context.","R132H-IHC negativ nicht mit IDH1/2-Wildtyp gleichsetzen":"Do not equate R132H IHC negative with IDH1/2 wildtype","Bei passendem Kontext Sequenzierung nicht-kanonischer IDH1/2-Varianten einfordern":"In the appropriate context, request sequencing for non-canonical IDH1/2 variants","Methylierungsclassifier als integrativen Klassifikationsbaustein einordnen":"Classify the methylation classifier as an integrative diagnostic component","G-CIMP als biologisches/epigenetisches Muster erklären, nicht als isolierten Routinetest":"Explain G-CIMP as a biologic/epigenetic pattern, not an isolated routine test","Falschaussage: negative R132H-IHC beweist IDH-Wildtyp":"False statement: negative R132H IHC proves IDH wildtype","Optimale Lösung: R132H-IHC als Screening verstehen, nicht-kanonische IDH1/2-Mutationen bei passendem Kontext sequenzieren und das Methylom als integrativen, nicht alleinstehenden Klassifikationsbaustein verwenden.":"Optimal solution: understand R132H IHC as screening, sequence non-canonical IDH1/2 mutations in the appropriate context, and use the methylome as an integrative rather than standalone classification component.","Gliom":"Glioma","IDH1":"IDH1","non-canonical IDH":"non-canonical IDH","G-CIMP":"G-CIMP","Astrozytom":"Astrocytoma","R132H negativ – aber nicht IDH-Wildtyp":"R132H negative — but not IDH wildtype","Neuropathologie / Neuroonkologie / MTB":"Neuropathology / Neuro-oncology / MTB","IDH1-R132H-IHC als Screening und nicht als vollständigen IDH1/2-Ausschluss verstehen.":"Understand IDH1 R132H IHC as screening, not as complete exclusion of IDH1/2 alterations.","Bei jungem Patienten und passender Morphologie nicht-kanonische IDH1/2-Varianten sequenzieren.":"In a young patient with fitting morphology, sequence non-canonical IDH1/2 variants.","G-CIMP als Folge der IDH-Biologie und nicht als isolierte Diagnose interpretieren.":"Interpret G-CIMP as a consequence of IDH biology rather than an isolated diagnosis.","Genomeweiten Methylierungsclassifier von fokaler Methylierungs-PCR unterscheiden.":"Distinguish a genome-wide methylation classifier from focal methylation PCR.","Histologie, definierende Marker und Methylom zu einer integrierten Diagnose zusammenführen.":"Combine histology, defining markers, and methylome into an integrated diagnosis.","Die IDH1-R132H-IHC ist negativ. Der Patient ist aber 36, der Tumor sieht diffus astrozytär aus, ATRX ist verloren und 1p/19q intakt. Der vermeintlich einfache 'IDH-Wildtyp'-Stempel beginnt zu wackeln.":"IDH1 R132H IHC is negative. But the patient is 36, the tumor looks diffusely astrocytic, ATRX is lost, and 1p/19q is intact. The apparently simple 'IDH-wildtype' label starts to wobble.","36-jähriger Patient mit linksfrontalem diffus infiltrierendem Gliom. R132H-IHC negativ, ATRX-Verlust und p53-Akkumulation. Das Board muss entscheiden, ob weiter sequenziert wird und wie ein G-CIMP-/Methylierungsprofil die integrierte Diagnose unterstützt.":"36-year-old man with a left frontal diffusely infiltrating glioma. R132H IHC negative, ATRX loss, and p53 accumulation. The board must decide whether to sequence further and how a G-CIMP/methylation profile supports the integrated diagnosis.","Screening ist nicht Sequenzierung":"Screening is not sequencing","R132H-IHC erkennt die häufigste IDH1-Variante, nicht jede IDH1/2-Mutation.":"R132H IHC detects the most common IDH1 variant, not every IDH1/2 mutation.","Ein negatives mutationsspezifisches Antikörperergebnis ist kein vollständiger Gen-Ausschluss.":"A negative mutation-specific antibody result is not a complete gene-level exclusion.","Alter + Morphologie zählen":"Age + morphology matter","Junger Erwachsener, diffus astrozytärer Tumor, ATRX-Verlust.":"Young adult, diffusely astrocytic tumor, ATRX loss.","Prätestwahrscheinlichkeit bestimmt, wann Sequenzierung trotz negativer IHC sinnvoll ist.":"Pretest probability determines when sequencing is useful despite negative IHC.","Epigenom als Integrator":"Epigenome as integrator","IDH-Mutationen erzeugen ein charakteristisches Hypermethylierungsprogramm.":"IDH mutations generate a characteristic hypermethylation program.","Das Methylom unterstützt Klassifikation, ersetzt aber definierende Marker nicht.":"The methylome supports classification but does not replace defining markers.","IDH1-R132H-IHC":"IDH1 R132H IHC","ATRX/p53":"ATRX/p53","ATRX-Verlust, diffuse p53-Akkumulation":"ATRX loss, diffuse p53 accumulation","1p/19q":"1p/19q","keine Kodeletion":"no codeletion","Tumoranteil ca. 70 %, DNA gut.":"Tumor fraction approx. 70%, good DNA quality.","Keine Materialnot – die Herausforderung ist Testhierarchie, nicht Schnittökonomie.":"No material shortage — the challenge is test hierarchy, not section economy.","Fokale Bisulfit-PCR ist kein Ersatz für genomeweite Klassifikation.":"Focal bisulfite PCR is not a substitute for genome-wide classification.","Was ist der wichtigste Schluss aus negativer IDH1-R132H-IHC?":"What is the most important conclusion from negative IDH1 R132H IHC?","Bei passendem klinisch-morphologischem Kontext IDH1/2 sequenzieren, weil nicht-kanonische Mutationen übersehen werden können.":"In the appropriate clinical-morphologic context, sequence IDH1/2 because non-canonical mutations may be missed.","IDH-Wildtyp ist sicher bewiesen.":"IDH wildtype is definitively proven.","Nur Methylierungsclassifier durchführen; Sequenzierung ist überflüssig.":"Perform only the methylation classifier; sequencing is unnecessary.","IDH ist bei Erwachsenen diagnostisch nicht relevant.":"IDH is not diagnostically relevant in adults.","R132H-IHC ist hoch nützlich, aber mutationsspezifisch.":"R132H IHC is highly useful, but mutation-specific.","Was bedeutet ein G-CIMP-artiges Profil am ehesten?":"What does a G-CIMP-like profile most likely mean?","Es ist ein epigenetisches Muster, das zur IDH-mutierten Biologie passt und die integrierte Klassifikation stützt.":"It is an epigenetic pattern consistent with IDH-mutant biology and supports integrated classification.","Es definiert allein den WHO-Grad.":"It alone defines the WHO grade.","Es ist ein eigenständiger zugelassener Therapietest.":"It is a standalone approved treatment test.","Es beweist eine Keimbahn-IDH-Mutation.":"It proves a germline IDH mutation.","G-CIMP ist biologischer/klassifikatorischer Kontext, kein alleiniger Therapie- oder Gradmarker.":"G-CIMP is a biologic/classification context, not a standalone treatment or grade marker.","Welche Aussage zum Methylierungsclassifier ist korrekt?":"Which statement about the methylation classifier is correct?","Genomeweites Profil kann diagnostisch stark sein, muss aber mit Histologie, QC und definierenden molekularen Markern integriert werden.":"A genome-wide profile can be diagnostically powerful, but must be integrated with histology, QC, and defining molecular markers.","Der höchste Klassenname ist immer die Diagnose.":"The highest class name is always the diagnosis.","Eine fokale Bisulfit-PCR ist gleichwertig.":"A focal bisulfite PCR is equivalent.","Methylom ersetzt IDH-Sequenzierung.":"Methylome analysis replaces IDH sequencing.","Classifier ist stark, aber integrativ.":"The classifier is powerful, but integrative.","Sequenzierung zeigt IDH1 p.R132C. Was kippt dadurch?":"Sequencing shows IDH1 p.R132C. What changes?","Der Tumor ist IDH-mutiert; die negative R132H-IHC war ein Screening-False-negative für diese nicht-kanonische Variante.":"The tumor is IDH-mutant; negative R132H IHC was a screening false negative for this non-canonical variant.","Die Sequenzierung muss falsch sein, weil die IHC negativ war.":"The sequencing must be wrong because the IHC was negative.","IDH-Status bleibt Wildtyp.":"IDH status remains wildtype.","Es folgt Keimbahndiagnostik auf Lynch.":"Proceed to germline testing for Lynch syndrome.","Nicht-kanonische IDH-Varianten sind der zentrale Twist.":"Non-canonical IDH variants are the central twist.","Formulieren Sie die integrierte neuropathologische Kernaussage und begründen Sie, warum nach negativer R132H-IHC sequenziert wurde und wie das Methylom gewichtet wird.":"Formulate the integrated neuropathology conclusion and explain why sequencing was performed after negative R132H IHC and how the methylome is weighted.","R132H-IHC als Screening einordnen.":"Classify R132H IHC as a screening test.","Nicht-kanonische IDH1/2-Sequenzierung bei hoher Prätestwahrscheinlichkeit durchführen.":"Perform non-canonical IDH1/2 sequencing when pretest probability is high.","IDH1 p.R132C als definierenden Befund anerkennen.":"Recognize IDH1 p.R132C as the defining finding.","Methylierungsprofil/G-CIMP als konsistenten integrativen Baustein berichten.":"Report methylation profile/G-CIMP as a consistent integrative component.","Fokale Methylierungs-PCR nicht als gleichwertigen Classifier-Ersatz darstellen.":"Do not present focal methylation PCR as an equivalent substitute for the classifier.","Auf Methylierungsclassifier verzichten, wenn Histologie und definierende molekulare Marker bereits eindeutig sind; in diesem Fall ist er didaktisch/klassifikatorisch zusätzlich hilfreich.":"The methylation classifier may be omitted when histology and defining molecular markers are already unequivocal; in this case it is additionally useful for teaching/classification.","Breites Panel nur bei zusätzlicher klinischer Fragestellung.":"Use a broad panel only if there is an additional clinical question.","R132H-negativ = IDH-WT":"R132H negative = IDH-WT","Mutationsspezifische IHC erfasst nicht alle IDH1/2-Varianten.":"Mutation-specific IHC does not capture all IDH1/2 variants.","Classifier statt Sequenzierung":"Classifier instead of sequencing","Definierende Genalteration und epigenetische Klasse sind unterschiedliche Ebenen.":"A defining gene alteration and an epigenetic class are different levels of information.","G-CIMP als Therapiebiomarker":"G-CIMP as treatment biomarker","Das Muster ist biologisch/klassifikatorisch, nicht allein handlungsleitend.":"The pattern is biologic/classificatory, not independently action-guiding.","Der 'negative' IDH-Test wird positiv":"The 'negative' IDH test turns positive","Die Sequenzierung weist IDH1 p.R132C nach. Gleichzeitig ordnet der Methylierungsclassifier den Tumor hochkonfident der IDH-mutierten Astrozytomfamilie zu. Der Twist ist kein Laborwiderspruch, sondern zeigt die Grenze einer mutationsspezifischen IHC.":"Sequencing identifies IDH1 p.R132C. At the same time, the methylation classifier assigns the tumor with high confidence to the IDH-mutant astrocytoma family. The twist is not a laboratory contradiction, but demonstrates the limit of mutation-specific IHC.","Er trainiert Prätestwahrscheinlichkeit, Methodengrenzen und integrierte CNS-Diagnostik.":"It trains pretest probability, method limitations, and integrated CNS diagnostics.","Screeninggrenze erkannt":"Screening limitation recognized","R132H-IHC negativ, IDH1 p.R132C sequenziert, Methylom konsistent mit IDH-mutiertem Astrozytom/G-CIMP.":"R132H IHC negative, IDH1 p.R132C detected by sequencing, methylome consistent with IDH-mutant astrocytoma/G-CIMP.","Methoden korrekt hierarchisiert.":"Methods correctly prioritized.","Methylom richtig, IDH zu spät":"Methylome correct, IDH too late","Classifier wird genutzt, die notwendige IDH1/2-Sequenzierung aber nicht sauber begründet.":"The classifier is used, but the necessary IDH1/2 sequencing is not properly justified.","Definierenden Marker nicht durch Epigenom ersetzen.":"Do not replace a defining marker with the epigenome.","IDH-Wildtyp abgestempelt":"Labeled IDH-wildtype","Nach negativer R132H-IHC wird keine Sequenzierung veranlasst.":"No sequencing is ordered after negative R132H IHC.","Zentralen methodischen Fallstrick verpasst.":"Key methodological pitfall missed.","Nicht-kanonische IDH-Mutation":"Non-canonical IDH mutation","Integrierte Diagnose entsprechend IDH-mutierter Entität formulieren.":"Formulate the integrated diagnosis according to the IDH-mutant entity.","Der Tumor verlässt den IDH-Wildtyp-Pfad.":"The tumor leaves the IDH-wildtype pathway.","Methylom diskordant":"Discordant methylome","QC, Tumoranteil und Differenzialdiagnose erneut prüfen.":"Reassess QC, tumor fraction, and differential diagnosis.","Keine automatisierte Übersteuerung der Morphologie.":"No automated override of morphology.","IDH1-R132H-IHC ist ein sehr gutes Screening, aber kein vollständiger IDH1/2-Ausschluss.":"IDH1 R132H IHC is excellent screening, but not a complete IDH1/2 exclusion.","Nicht-kanonische IDH-Mutationen sind besonders bei jüngeren Patienten mit passendem diffusem Gliom relevant.":"Non-canonical IDH mutations are particularly relevant in younger patients with an appropriate diffuse glioma context.","IDH-Biologie erzeugt charakteristische epigenetische Muster wie G-CIMP.":"IDH biology produces characteristic epigenetic patterns such as G-CIMP.","Methylierungsclassifier sind integrative Diagnostikwerkzeuge, keine Orakel.":"Methylation classifiers are integrative diagnostic tools, not oracles.","Fokale Methylierungs-PCR und genomeweiter Classifier beantworten unterschiedliche Fragen.":"Focal methylation PCR and a genome-wide classifier answer different questions.","Bei diesem 36-jährigen Patienten darf die negative R132H-IHC nicht als vollständiger IDH-Wildtyp-Nachweis gelten. IDH1/2-Sequenzierung weist IDH1 p.R132C nach. Das Methylierungsprofil unterstützt die IDH-mutierte astrozytäre Klassifikation und zeigt ein G-CIMP-artiges Muster. Histologie, IDH, ATRX/p53/1p19q und Methylom werden integriert.":"In this 36-year-old patient, negative R132H IHC must not be considered complete proof of IDH-wildtype status. IDH1/2 sequencing detects IDH1 p.R132C. The methylation profile supports IDH-mutant astrocytic classification and shows a G-CIMP-like pattern. Histology, IDH, ATRX/p53/1p19q, and methylome are integrated.","Screeninggrenze R132H-IHC":"R132H IHC screening limitation","nicht-kanonische Sequenzierung":"Non-canonical sequencing","Classifier integrativ":"Classifier integrative","G-CIMP korrekt eingeordnet":"G-CIMP correctly interpreted","Wann reicht R132H-IHC allein?":"When is R132H IHC alone sufficient?","Warum ist Prätestwahrscheinlichkeit in der Molekularpathologie wichtig?":"Why is pretest probability important in molecular pathology?","Was kann ein Methylierungsclassifier, was eine fokale Bisulfit-PCR nicht kann?":"What can a methylation classifier do that focal bisulfite PCR cannot?","IDH1 p.R132C trotz negativer R132H-IHC":"IDH1 p.R132C despite negative R132H IHC","Negativer Screeningtest ist nicht automatisch negativer Genstatus":"A negative screening test is not automatically a negative gene status","R132H-IHC → Sequenzierung → Methylom → integrierte Diagnose":"R132H IHC → sequencing → methylome → integrated diagnosis","Unklarer ZNS-Tumor: Der Methylierungsclassifier hilft – aber nur bei guter Probe":"Unclear CNS tumor: the methylation classifier helps — but only with a good sample","Histologisch unklarer ZNS-Tumor: M…":"Histologically unclear CNS tumor: m…","Neuropathologie / Neuroonkologisches Referenzboard":"Neuropathology / Neuro-oncology reference board","47-jährige Patientin mit einem posterior-fossären Tumor. Histologie und IHC ergeben ein ungewöhnliches gliales/ependymales Mischbild; mehrere Differenzialdiagnosen bleiben plausibel.":"47-year-old woman with a posterior fossa tumor. Histology and IHC show an unusual mixed glial/ependymal pattern; several differential diagnoses remain plausible.","Kann ein DNA-Methylierungsclassifier die Diagnose klären – und wann darf ein Classifier-Ergebnis gerade nicht überinterpretiert werden?":"Can a DNA methylation classifier clarify the diagnosis — and when must a classifier result specifically not be overinterpreted?","Die Referenzdiagnose beeinflusst Nachsorge und Therapieplanung.":"The reference diagnosis affects follow-up and treatment planning.","Schwindel, Gangunsicherheit und okzipitale Kopfschmerzen; MRT mit gut abgrenzbarer Raumforderung im Kleinhirn.":"Dizziness, gait instability, and occipital headache; MRI shows a well-circumscribed cerebellar mass.","Voroperation":"Previous surgery","Keine bekannte Tumorerkrankung.":"No known tumor disease.","Pathologie":"Pathology","Morphologie uneindeutig; IHC nicht widersprüchlich, aber nicht ausreichend spezifisch.":"Morphology is ambiguous; IHC is not contradictory but insufficiently specific.","Ein Classifier-Score wird als maschinelles Wahrheitsurteil behandelt, unabhängig von Tumoranteil und Plausibilität.":"A classifier score is treated as machine truth regardless of tumor fraction and plausibility.","Piloide und stellenweise ependymale Architektur, fokale Gefäßhyalinisierung, keine eindeutige klassische Entität.":"Piloid and focally ependymal architecture, focal vascular hyalinization, no unequivocal classic entity.","GFAP positiv; EMA nur fokal dot-like; OLIG2 heterogen; keine sichere Linie.":"GFAP positive; EMA only focally dot-like; OLIG2 heterogeneous; no secure lineage.","Erste Differentialdiagnose":"Initial differential diagnosis","Ependymom versus astrozytärer/piloider Tumor.":"Ependymoma versus astrocytic/piloid tumor.","Genomeweites Methylierungsmuster und Copy-number-Kontext.":"Genome-wide methylation pattern and copy-number context.","Erster FFPE-Block enthält nur ca. 15 % Tumor und viel reaktives Kleinhirngewebe; zweiter Block enthält ca. 65 % Tumor.":"The first FFPE block contains only about 15% tumor and abundant reactive cerebellar tissue; the second block contains about 65% tumor.","beide Blöcke technisch extrahierbar.":"Both blocks are technically extractable.","Classifier-Risiko":"Classifier risk","Niedriger Tumoranteil kann den Score und das Profil verwässern.":"Low tumor fraction can dilute the score and profile.","Eine fokale Bisulfit-PCR beantwortet nicht die globale Klassifikationsfrage.":"Focal bisulfite PCR does not answer a global classification question.","Genomeweiter CNS-Methylierungsclassifier":"Genome-wide CNS methylation classifier","Classifier – Block mit wenig Tumor":"Classifier — low-tumor block","Erste Analyse aus dem tumorarmen Block liefert nur eine niedrig-konfidente, biologisch wenig plausible Zuordnung unterhalb des lokal validierten Freigabebereichs. Kein belastbarer Klassenruf.":"The first analysis from the low-tumor block gives only a low-confidence, biologically implausible assignment below the locally validated reporting range. No reliable class call.","Classifier – tumorangereicherter Block":"Classifier — tumor-enriched block","Nach Auswahl des tumorreichen Blocks ergibt sich eine hochkonfidente Zuordnung zur Methylierungsfamilie 'High-grade astrocytoma with piloid features' mit passendem Copy-number-Profil.":"After selecting the tumor-rich block, there is a high-confidence assignment to the methylation family 'High-grade astrocytoma with piloid features' with a matching copy-number profile.","Lokale CpG-Methylierung nachweisbar, aber diagnostisch nicht ausreichend zur genomeweiten Klassifikation.":"Local CpG methylation is detectable but diagnostically insufficient for genome-wide classification.","Molekulare Zusatzbefunde können die Plausibilität stützen, ersetzen aber bei diesem morphologisch schwierigen Fall den validierten Methylierungsclassifier nicht.":"Additional molecular findings may support plausibility but do not replace the validated methylation classifier in this morphologically difficult case.","Histologisch uneindeutiger posterior-fossärer glialer Tumor.":"Histologically ambiguous posterior fossa glial tumor.","Es stehen ein tumorarmer und ein deutlich tumorreicherer Block zur Verfügung.":"A low-tumor block and a clearly tumor-richer block are available.","Der CNS-Methylierungsclassifier ist bei morphologisch unklaren Tumoren besonders wertvoll, sein Ergebnis muss aber zusammen mit Tumoranteil, QC, Score, Copy-number-Profil und Histologie bewertet werden. Der erste niedrig-konfidente Lauf aus tumorarmem Material ist nicht berichtsfähig; die Wiederholung aus tumorreichem Material liefert eine plausible hochkonfidente Klassifikation.":"The CNS methylation classifier is especially valuable in morphologically unclear tumors, but its result must be assessed together with tumor fraction, QC, score, copy-number profile, and histology. The first low-confidence run from low-tumor material is not reportable; repeat testing from tumor-rich material provides a plausible high-confidence classification.","Teilbefund: Ein niedrig-konfidentes Classifier-Ergebnis aus tumorarmem Material darf nicht als definitive Diagnose ausgegeben werden.":"Partial result: a low-confidence classifier result from low-tumor material must not be issued as a definitive diagnosis.","Methylierungsclassifier gezielt bei diagnostisch schwierigem ZNS-Tumor einsetzen":"Use the methylation classifier specifically for a diagnostically difficult CNS tumor","Tumoranteil und Classifier-QC vor Klassenruf prüfen":"Check tumor fraction and classifier QC before making a class call","Classifier mit Histologie und molekularen Zusatzdaten integrieren":"Integrate classifier with histology and additional molecular data","Bei unplausiblem Low-confidence-Ergebnis besseres Material wählen statt überinterpretieren":"For an implausible low-confidence result, choose better material rather than overinterpreting it","Falschaussage: der höchste angezeigte Klassenname ist unabhängig vom Score die Diagnose":"False statement: the highest displayed class name is the diagnosis regardless of score","Optimale Lösung: Classifier als starken integrativen Diagnostikbaustein nutzen, aber nur aus geeignetem Material und mit validiertem Confidence-/QC-Kontext; ein Low-confidence-Ergebnis ist ein Hinweis, kein Wahrheitsurteil.":"Optimal solution: use the classifier as a strong integrative diagnostic component, but only from suitable material and within a validated confidence/QC context; a low-confidence result is a clue, not a truth verdict.","ZNS":"CNS","Integrated diagnosis":"Integrated diagnosis","Der Classifier ist nur so gut wie Probe und Plausibilität":"The classifier is only as good as the sample and plausibility","Neuropathologie / Molekulardiagnostik / MTB":"Neuropathology / Molecular Diagnostics / MTB","Indikationen für CNS-Methylierungsclassification bei diagnostisch schwierigen Tumoren erkennen.":"Recognize indications for CNS methylation classification in diagnostically difficult tumors.","Tumoranteil, QC und Confidence/Score vor Klassenruf prüfen.":"Check tumor fraction, QC, and confidence/score before a class call.","Low-confidence-Ergebnisse nicht als definitive Diagnose ausgeben.":"Do not report low-confidence results as a definitive diagnosis.","Bei unplausiblem Ergebnis besseres Material priorisieren.":"Prioritize better material when the result is implausible.","Classifier, Copy-number-Profil, Histologie und Molekulargenetik integrieren.":"Integrate classifier, copy-number profile, histology, and molecular genetics.","Der Computer liefert einen Klassennamen – aber aus einem Block mit nur 15 % Tumor und mit einem Score unterhalb des lokal validierten Freigabebereichs. Die Versuchung ist groß, den Namen trotzdem in den Befund zu schreiben.":"The computer outputs a class name — but from a block with only 15% tumor and a score below the locally validated reporting range. The temptation to put the name in the report anyway is strong.","47-jährige Patientin mit morphologisch uneindeutigem posterior-fossärem glialem Tumor. Zwei Blöcke unterscheiden sich massiv im Tumoranteil. Der Fall lehrt, wann Methylierungsclassification enorm hilfreich ist und wann ein scheinbares Ergebnis verworfen werden muss.":"47-year-old woman with a morphologically ambiguous posterior fossa glial tumor. Two blocks differ markedly in tumor fraction. The case teaches when methylation classification is enormously helpful and when an apparent result must be discarded.","Unklare Morphologie":"Unclear morphology","Ependymal/piloid/glial überlappende Merkmale.":"Overlapping ependymal/piloid/glial features.","Genau hier kann ein validierter classifier besonders wertvoll sein.":"This is exactly where a validated classifier can be especially valuable.","Zwei Blöcke, zwei Welten":"Two blocks, two worlds","15 % versus 65 % Tumoranteil.":"15% versus 65% tumor fraction.","Preanalytics beeinflusst auch digitale/epigenetische Klassifikatoren.":"Preanalytics also affects digital/epigenetic classifiers.","Score braucht Kontext":"Score needs context","Low confidence + unplausible Morphologie.":"Low confidence + implausible morphology.","Ein Output ist noch kein reportable Result.":"An output is not yet a reportable result.","Block A":"Block A","ca. 15 % Tumor, viel normales Kleinhirngewebe":"approx. 15% tumor, abundant normal cerebellar tissue","Block B":"Block B","ca. 65 % Tumor":"approx. 65% tumor","mehrere plausible ZNS-Differenzialdiagnosen":"Several plausible CNS differential diagnoses","Classifier aus geeignetem tumorreichem Material priorisieren.":"Prioritize classifier testing from suitable tumor-rich material.","Lokaler validierter Score-/QC-Rahmen ist Teil der Befundfreigabe.":"The locally validated score/QC framework is part of report release.","Fokale Bisulfit-PCR löst keine genomeweite Klassifikationsfrage.":"Focal bisulfite PCR does not solve a genome-wide classification question.","Wann ist der Methylierungsclassifier hier am wertvollsten?":"When is the methylation classifier most valuable here?","Bei persistierender diagnostischer Unsicherheit trotz Histologie/IHC und ausreichendem Material.":"When diagnostic uncertainty persists despite histology/IHC and sufficient material is available.","Immer als Ersatz für Histologie.":"Always as a replacement for histology.","Nur wenn eine medikamentöse Targettherapie existiert.":"Only if a target therapy exists.","Bei Erwachsenen grundsätzlich nicht.":"Never in adults.","Der größte Zusatznutzen entsteht bei schwierigen integrierten Diagnosen.":"The greatest added value is in difficult integrated diagnoses.","Wie wird ein niedrig-konfidentes Ergebnis aus 15-%-Tumorblock behandelt?":"How should a low-confidence result from a 15%-tumor block be handled?","Nicht definitiv reporten; QC/Tumoranteil prüfen und besseres Material analysieren.":"Do not report definitively; check QC/tumor fraction and analyze better material.","Höchste Klasse trotzdem als Diagnose berichten.":"Report the highest class as the diagnosis anyway.","Mit HE-Diagnose mitteln.":"Average it with the H&E diagnosis.","Score ist irrelevant.":"Score is irrelevant.","Confidence und Präanalytik sind Teil der diagnostischen Aussage.":"Confidence and preanalytics are part of the diagnostic statement.","Der tumorreiche Block liefert einen hochkonfidenten, morphologisch plausiblen Treffer. Was folgt?":"The tumor-rich block yields a high-confidence, morphologically plausible hit. What follows?","Mit Histologie und molekularen Zusatzdaten integrieren und als starke diagnostische Evidenz nutzen.":"Integrate it with histology and additional molecular data and use it as strong diagnostic evidence.","Alle bisherigen Befunde verwerfen.":"Discard all previous findings.","Classifier immer ignorieren.":"Always ignore the classifier.","Erst eine fokale Bisulfit-PCR muss den Namen bestätigen.":"A focal bisulfite PCR must first confirm the name.","Plausible hochkonfidente Klassifikation ist stark, aber integriert.":"A plausible high-confidence classification is strong, but integrated.","Warum ist das begleitende Copy-number-Profil nützlich?":"Why is the accompanying copy-number profile useful?","Es kann die Klassenplausibilität stützen und zusätzliche diagnostische Muster liefern.":"It can support class plausibility and provide additional diagnostic patterns.","Es beweist Keimbahnveränderungen.":"It proves germline alterations.","Es ersetzt Histologie vollständig.":"It completely replaces histology.","Es ist immer ein zugelassener Therapietest.":"It is always an approved treatment test.","Classifier und CN-Profil ergänzen die integrierte Diagnose.":"Classifier and CN profile complement the integrated diagnosis.","Entscheiden Sie, welcher Block analysiert und welches Classifier-Ergebnis reportet werden darf. Formulieren Sie die integrierte Diagnose mit klarer QC-Grenze.":"Decide which block should be analyzed and which classifier result may be reported. Formulate the integrated diagnosis with a clear QC boundary.","Morphologische Unsicherheit als legitime Classifier-Indikation erkennen.":"Recognize morphologic uncertainty as a legitimate indication for the classifier.","Tumorarmen Block als Risikomaterial identifizieren.":"Identify the low-tumor block as high-risk material.","Low-confidence-Ausgabe nicht als definitive Diagnose reporten.":"Do not report a low-confidence output as a definitive diagnosis.","Tumorreichen Block analysieren.":"Analyze the tumor-rich block.","Hochkonfidenten, plausiblen Classifier mit Morphologie/CN-Profil integrieren.":"Integrate the high-confidence, plausible classifier result with morphology/CN profile.","Bei fehlendem besserem Material eine rein deskriptive/NEC-artige Diagnose mit Limitation statt erzwungenem Classifier-Call.":"If no better material is available, use a purely descriptive/NEC-like diagnosis with limitations rather than forcing a classifier call.","Referenzzentrum bei persistierender Diskordanz.":"Refer to a reference center if discordance persists.","Highest score wins":"Highest score wins","Confidence, QC und Plausibilität werden ignoriert.":"Confidence, QC, and plausibility are ignored.","Classifier ersetzt Histologie":"Classifier replaces histology","CNS-Diagnostik bleibt integriert.":"CNS diagnostics remain integrated.","Fokale Methylierung statt Methylom":"Focal methylation instead of methylome","Lokaler Marker beantwortet eine andere Frage.":"A local marker answers a different question.","Der erste Classifier war technisch echt – diagnostisch trotzdem nicht gut genug":"The first classifier was technically real — but diagnostically not good enough","Aus dem tumorarmen Block entsteht ein Low-confidence-Match. Erst der gezielte Wechsel auf den tumorreichen Block erzeugt eine hochkonfidente, morphologisch passende Klassifikation. Das Problem war nicht 'KI vs. Mensch', sondern Präanalytik und Freigabekriterien.":"The low-tumor block produces a low-confidence match. Only after deliberately switching to the tumor-rich block does a high-confidence, morphologically fitting classification emerge. The problem was not 'AI versus human', but preanalytics and release criteria.","Der Fall macht deutlich, dass auch moderne Klassifikatoren klassische Labor-QC brauchen.":"The case makes clear that modern classifiers also require classic laboratory QC.","QC vor Klassenname":"QC before class name","Low-confidence aus Block A verworfen; Block B liefert hochkonfidenten plausiblen Classifier-Match.":"Low-confidence result from block A rejected; block B yields a high-confidence, plausible classifier match.","Classifier als Laborverfahren behandelt, nicht als Black Box.":"Classifier treated as a laboratory method, not a black box.","Richtige Klasse, falscher Weg":"Right class, wrong path","Klasse erkannt, aber der erste Low-score-Lauf wird nicht klar als nicht freigabefähig markiert.":"The class is recognized, but the first low-score run is not clearly marked as unsuitable for release.","QA-Lernziel verfehlt.":"QA learning objective missed.","Low score reportet":"Low score reported","Erster angezeigter Klassenname wird ungeprüft zur Diagnose.":"The first displayed class name is adopted as the diagnosis without review.","Kritischer Befundfreigabefehler.":"Critical report-release error.","Low-confidence / diskordant":"Low-confidence / discordant","Tumoranteil, DNA-QC, Referenzklasse und Materialauswahl prüfen.":"Check tumor fraction, DNA QC, reference class, and material selection.","Keine Scheinsicherheit.":"No false certainty.","High-confidence + plausibel":"High confidence + plausible","In integrierte Diagnose übernehmen.":"Incorporate into the integrated diagnosis.","Methylom liefert echten diagnostischen Mehrwert.":"Methylome provides real diagnostic added value.","Methylierungsclassifier sind besonders bei schwierigen ZNS-Tumoren leistungsfähig.":"Methylation classifiers are particularly powerful in difficult CNS tumors.","Tumoranteil und Probenqualität beeinflussen das Ergebnis.":"Tumor fraction and sample quality affect the result.","Confidence/Score ist kein kosmetischer Parameter, sondern Teil der Befundfreigabe.":"Confidence/score is not cosmetic; it is part of report release.","Ein niedriger Score kann korrekt gerechnet und trotzdem diagnostisch nicht ausreichend sein.":"A low score can be calculated correctly and still be diagnostically insufficient.","Moderne Klassifikation funktioniert nur integriert mit Pathologie und Molekulargenetik.":"Modern classification works only when integrated with pathology and molecular genetics.","Der erste Lauf aus tumorarmem Material ist trotz angezeigtem Klassennamen nicht freigabefähig. Nach Analyse des tumorreichen Blocks entsteht eine hochkonfidente, morphologisch und genomisch plausible Klassifikation. Diese wird als starker integrativer Diagnostikbaustein genutzt.":"The first run from low-tumor material is not releasable despite a displayed class name. Analysis of the tumor-rich block then yields a high-confidence classification that is morphologically and genomically plausible. This is used as a strong integrative diagnostic component.","QC/Confidence":"QC/Confidence","Materialauswahl":"Material selection","integrative Diagnose":"Integrated diagnosis","kein Black-box-Overcalling":"No black-box overcalling","Welche Mindest-QC braucht ein Classifier in Ihrem Labor?":"What minimum QC does a classifier require in your laboratory?","Wie berichtet man Low-confidence-Ergebnisse?":"How should low-confidence results be reported?","Wann ist 'kein Klassenruf' die bessere Diagnose?":"When is 'no class call' the better diagnosis?","Low-confidence aus falschem Block":"Low confidence from the wrong block","Classifier braucht Labor-QC wie jede andere Methode":"A classifier needs laboratory QC like any other method","Morphologische Unsicherheit → Materialwahl → Classifier-QC → integrierter Call":"Morphologic uncertainty → material selection → classifier QC → integrated call","DNMT3A/TET2/ASXL1 bei Zytopenie: CHIP, CCUS oder MDS?":"DNMT3A/TET2/ASXL1 with cytopenia: CHIP, CCUS, or MDS?","MDS/AML mit DNMT3A/TET2/ASXL1":"MDS/AML with DNMT3A/TET2/ASXL1","Hämatologie / Molekulares Board":"Hematology / Molecular Board","74-jähriger Patient mit seit neun Monaten persistierender makrozytärer Anämie und milder Thrombozytopenie. Im peripheren Blut wurden DNMT3A- und TET2-Varianten gefunden.":"74-year-old man with persistent macrocytic anemia and mild thrombocytopenia for nine months. DNMT3A and TET2 variants were detected in peripheral blood.","Beweisen diese Mutationen bereits ein MDS – oder handelt es sich um CHIP?":"Do these mutations already prove MDS — or is this CHIP?","Die Diagnose soll vor Einleitung einer krankheitsspezifischen Therapie geklärt werden.":"The diagnosis should be clarified before disease-specific therapy is initiated.","Hb 9,8 g/dl, MCV erhöht, Thrombozyten 115/nl; Leukozyten normal.":"Hb 9.8 g/dl, elevated MCV, platelets 115/nl; leukocytes normal.","Sekundäre Ursachen":"Secondary causes","Vitaminmangel, relevante Blutung, Niereninsuffizienz und Medikamente als Hauptursache weitgehend ausgeschlossen.":"Vitamin deficiency, relevant bleeding, renal insufficiency, and medications largely excluded as the main cause.","Blut-NGS: DNMT3A p.R882H VAF 12 %, TET2 Frameshift VAF 8 %.":"Blood NGS: DNMT3A p.R882H VAF 12%, TET2 frameshift VAF 8%.","Mutationen typischer CH-Gene werden mit einer definierten myeloischen Neoplasie gleichgesetzt.":"Mutations in typical CH genes are equated with a defined myeloid neoplasm.","Knochenmark + Vorinformation":"Bone marrow + prior information","Normo- bis leicht hyperzellulär; Dysplasie unterhalb diagnostischer Schwelle, Blasten 2 %.":"Normocellular to mildly hypercellular; dysplasia below diagnostic threshold, blasts 2%.","Kein MDS-definierender Befund.":"No MDS-defining finding.","Flow":"Flow","Kein eindeutiger aberranter Blastenphänotyp.":"No unequivocal aberrant blast phenotype.","Wie werden persistierende Zytopenie und klonale Mutationen zusammengeführt?":"How should persistent cytopenia and clonal mutations be integrated?","Knochenmarkaspirat + Stanze sowie EDTA-Blut.":"Bone marrow aspirate + biopsy and EDTA blood.","ausreichende Tiefe zur VAF-Beurteilung.":"Sufficient depth for VAF assessment.","CHIP setzt definitionsgemäß das Fehlen einer anderweitig ungeklärten Zytopenie voraus.":"By definition, CHIP requires the absence of otherwise unexplained cytopenia.","Ein breites Pan-Cancer-Panel schafft nicht automatisch mehr diagnostische Sicherheit als eine integrierte hämatologische Bewertung.":"A broad pan-cancer panel does not automatically create more diagnostic certainty than an integrated hematologic assessment.","Knochenmark-/Morphologiekontext":"Bone marrow/morphology context","Klonale Hämatopoese / Myeloid-Panel":"Clonal hematopoiesis / myeloid panel","Persistierende Zytopenie, aber keine ausreichende Dysplasie, keine erhöhte Blastenzahl und kein morphologisch definierendes MDS-Kriterium.":"Persistent cytopenia, but insufficient dysplasia, no increased blast count, and no morphologically defining MDS criterion.","Myeloid-Panel":"Myeloid panel","DNMT3A p.R882H (VAF 12 %) und TET2 Frameshift (VAF 8 %); keine TP53-Alteration im untersuchten Panel. Klonalität ist belegt, eine MDS-Diagnose dadurch allein jedoch nicht.":"DNMT3A p.R882H (VAF 12%) and TET2 frameshift (VAF 8%); no TP53 alteration in the tested panel. Clonality is established, but this alone does not establish MDS.","Zusätzliche unspezifische Varianten erhöhen die Informationsmenge, lösen aber die diagnostische Abgrenzung nicht ohne Blutbild, Morphologie und definierende Kriterien.":"Additional nonspecific variants increase the amount of information but do not resolve the diagnostic distinction without blood count, morphology, and defining criteria.","Persistierende, anderweitig nicht erklärte Anämie und Thrombozytopenie.":"Persistent, otherwise unexplained anemia and thrombocytopenia.","Keine ausreichenden morphologischen oder genetischen Kriterien für eine manifeste myeloische Neoplasie.":"No sufficient morphologic or genetic criteria for overt myeloid neoplasia.","Die DNMT3A- und TET2-Mutationen belegen klonale Hämatopoese, definieren aber allein kein MDS. Weil gleichzeitig persistierende ungeklärte Zytopenien bestehen, ist 'CHIP' nicht die passende Kategorie; bei fehlenden diagnostischen MDS-Kriterien passt die Konstellation zu einer klonalen Zytopenie unklarer Signifikanz (CCUS). Verlauf und erneute Abklärung bei Progression sind wichtiger als ein vorschnelles Neoplasie-Label.":"DNMT3A and TET2 mutations establish clonal hematopoiesis but do not by themselves define MDS. Because persistent unexplained cytopenias are also present, 'CHIP' is not the appropriate category; in the absence of diagnostic MDS criteria, the constellation fits clonal cytopenia of undetermined significance (CCUS). Follow-up and repeat work-up if progression occurs are more important than a premature neoplasia label.","Teilbefund: Mutationen in DNMT3A/TET2/ASXL1 können bei CHIP, CCUS und myeloischen Neoplasien vorkommen; die Diagnose entsteht erst aus Klinik, Blutbild, Morphologie und Genetik zusammen.":"Partial result: mutations in DNMT3A/TET2/ASXL1 may occur in CHIP, CCUS, and myeloid neoplasms; the diagnosis emerges only from integrating clinical context, blood count, morphology, and genetics.","Klonale Mutation nicht mit MDS gleichsetzen":"Do not equate a clonal mutation with MDS","CHIP nur ohne ungeklärte Zytopenie verwenden":"Use CHIP only in the absence of unexplained cytopenia","CCUS als passende Zwischenkategorie bei Zytopenie + Klon ohne MDS-Kriterien erkennen":"Recognize CCUS as the appropriate intermediate category for cytopenia + clone without MDS criteria","Verlaufskontrolle und erneute KM-Diagnostik bei Dynamik einplanen":"Plan follow-up and repeat bone marrow assessment if the picture evolves","Falschaussage: DNMT3A/TET2 beweisen eine hämatologische Neoplasie":"False statement: DNMT3A/TET2 prove a hematologic neoplasm","Optimale Lösung: DNMT3A/TET2 zeigen einen Klon; Zytopenie verhindert die CHIP-Bezeichnung, fehlende MDS-definierende Kriterien verhindern die MDS-Diagnose – damit ist CCUS die saubere integrierte Einordnung.":"Optimal solution: DNMT3A/TET2 demonstrate a clone; cytopenia prevents the CHIP label, while absent MDS-defining criteria prevent an MDS diagnosis — making CCUS the clean integrated classification.","Hämatologie":"Hematology","DNMT3A":"DNMT3A","TET2":"TET2","CHIP":"CHIP","CCUS":"CCUS","MDS":"MDS","Clonal hematopoiesis":"Clonal hematopoiesis","Der Klon ist echt – die Neoplasie noch nicht":"The clone is real — the neoplasm is not yet","Hämatopathologie / Hämatologie / MTB":"Hematopathology / Hematology / MTB","DNMT3A/TET2/ASXL1-Mutationen als häufige Klone und nicht als automatische MDS-Diagnose erkennen.":"Recognize DNMT3A/TET2/ASXL1 mutations as common clones rather than an automatic MDS diagnosis.","CHIP, CCUS und MDS anhand von Zytopenie und diagnostischen Kriterien trennen.":"Distinguish CHIP, CCUS, and MDS using cytopenia and diagnostic criteria.","VAF/Klonalität als Kontext, nicht als alleinige Entitätsdefinition verwenden.":"Use VAF/clonality as context, not as the sole definition of an entity.","Morphologie und Blutbild gegenüber 'Genetik allein' priorisieren.":"Prioritize morphology and blood count over 'genetics alone'.","Verlaufskontrolle als Teil einer ehrlichen diagnostischen Strategie verstehen.":"Understand follow-up as part of an honest diagnostic strategy.","Zwei pathogene Mutationen stehen schwarz auf weiß im NGS-Bericht. Der Reflex lautet: 'Dann hat er MDS.' Das Knochenmark liefert aber keine ausreichenden Kriterien – und die persistierende Zytopenie macht gleichzeitig 'CHIP' falsch.":"Two pathogenic mutations are printed clearly in the NGS report. The reflex is: 'Then he has MDS.' But the bone marrow does not meet sufficient criteria — and the persistent cytopenia simultaneously makes 'CHIP' incorrect.","74-jähriger Patient mit ungeklärter makrozytärer Anämie und Thrombozytopenie. DNMT3A und TET2 sind mutiert, das Knochenmark bleibt jedoch unterhalb diagnostischer MDS-Schwellen. Gesucht ist die richtige Kategorie zwischen benignem Zufallsbefund und manifester Neoplasie.":"74-year-old man with unexplained macrocytic anemia and thrombocytopenia. DNMT3A and TET2 are mutated, but bone marrow remains below diagnostic MDS thresholds. The task is to identify the correct category between a benign incidental finding and overt neoplasia.","Klonalität ist bewiesen":"Clonality is proven","DNMT3A 12 %, TET2 8 % VAF.":"DNMT3A 12%, TET2 8% VAF.","Ein Klon ist nicht automatisch eine Neoplasie.":"A clone is not automatically a neoplasm.","Zytopenie ist real":"Cytopenia is real","Persistierende Anämie + Thrombozytopenie ohne klare Sekundärursache.":"Persistent anemia + thrombocytopenia without a clear secondary cause.","Damit passt die Definition von CHIP gerade nicht.":"This means the definition of CHIP does not fit.","MDS-Kriterien fehlen":"MDS criteria are absent","Blasten 2 %, Dysplasie unter Schwelle, keine definierende Genetik.":"Blasts 2%, dysplasia below threshold, no defining genetics.","CCUS ist eine sinnvolle Zwischenkategorie.":"CCUS is a meaningful intermediate category.","Hb 9,8 g/dl; Thrombozyten 115/nl":"Hb 9.8 g/dl; platelets 115/nl","DNMT3A p.R882H 12 %, TET2 Frameshift 8 %":"DNMT3A p.R882H 12%, TET2 frameshift 8%","keine ausreichende Dysplasie, Blasten 2 %":"Insufficient dysplasia, blasts 2%","Knochenmarkmorphologie ist unverzichtbar.":"Bone marrow morphology is indispensable.","Breites Pan-Cancer-NGS kann die Kategorie nicht ohne klinisch-hämatologischen Kontext definieren.":"Broad pan-cancer NGS cannot define the category without clinical-hematologic context.","Verlauf ist diagnostisch relevant, wenn Kriterien heute noch nicht erfüllt sind.":"Follow-up is diagnostically relevant when criteria are not yet met today.","Was beweisen DNMT3A/TET2 hier?":"What do DNMT3A/TET2 prove here?","Klonale Hämatopoese.":"Clonal hematopoiesis.","Sicher ein MDS.":"Definitely MDS.","Sicher AML.":"Definitely AML.","Eine Keimbahnerkrankung.":"A germline disorder.","Diese Gene überlappen stark zwischen CH, CCUS und myeloischen Neoplasien.":"These genes overlap substantially between CH, CCUS, and myeloid neoplasms.","Warum ist 'CHIP' hier unpassend?":"Why is 'CHIP' inappropriate here?","Weil persistierende anderweitig ungeklärte Zytopenien bestehen.":"Because persistent otherwise unexplained cytopenias are present.","Weil der Patient älter als 70 ist.":"Because the patient is older than 70.","Weil zwei Mutationen vorliegen.":"Because two mutations are present.","Weil VAF über 5 % liegt.":"Because VAF is above 5%.","CHIP setzt gerade das Fehlen entsprechender ungeklärter Zytopenien voraus.":"CHIP specifically requires the absence of corresponding unexplained cytopenias.","Welche Kategorie passt bei Zytopenie + Klon ohne MDS-definierende Kriterien am besten?":"Which category best fits cytopenia + clone without MDS-defining criteria?","CCUS.":"CCUS.","CHIP.":"CHIP.","AML.":"AML.","Normalbefund.":"Normal finding.","CCUS beschreibt genau diese Zwischenkonstellation.":"CCUS describes exactly this intermediate constellation.","Was ist die sinnvollste nächste Strategie?":"What is the most appropriate next strategy?","Klinisch/hämatologisch monitoren und bei Dynamik erneut Knochenmark/Molekulargenetik bewerten.":"Monitor clinically/hematologically and reassess bone marrow/molecular genetics if there is progression.","Sofort MDS-Therapie allein wegen DNMT3A/TET2.":"Start MDS therapy immediately based solely on DNMT3A/TET2.","Keine weitere Kontrolle.":"No further follow-up.","Automatisch Keimbahntest für DNMT3A/TET2.":"Automatically perform germline testing for DNMT3A/TET2.","Diagnostische Ehrlichkeit plus Verlauf ist hier angemessen.":"Diagnostic honesty plus follow-up is appropriate here.","Ordnen Sie den Fall zwischen CHIP, CCUS und MDS ein und formulieren Sie, welche Information die Mutationen liefern – und welche nicht.":"Classify the case between CHIP, CCUS, and MDS and state what information the mutations provide — and what they do not.","Klonalität anerkennen.":"Acknowledge clonality.","Persistierende ungeklärte Zytopenie berücksichtigen.":"Account for persistent unexplained cytopenia.","Fehlende MDS-definierende Morphologie/Genetik benennen.":"State the absence of MDS-defining morphology/genetics.","CHIP ausschließen, weil Zytopenie vorhanden.":"Exclude CHIP because cytopenia is present.","CCUS als passendste aktuelle Kategorie formulieren.":"Formulate CCUS as the best current category.","Verlaufskontrolle/erneute Diagnostik bei Progression empfehlen.":"Recommend follow-up/repeat work-up if progression occurs.","Bei später neu auftretenden definierenden Kriterien Re-Klassifikation zur myeloischen Neoplasie.":"If defining criteria emerge later, reclassify as a myeloid neoplasm.","Bei identifizierter sekundärer Zytopenieursache Neubewertung der CCUS-Einordnung.":"If a secondary cause of cytopenia is identified, reassess the CCUS classification.","Mutation = MDS":"Mutation = MDS","CH-Gene sind nicht krankheitsspezifisch.":"CH genes are not disease-specific.","Alles CHIP":"Everything is CHIP","Persistierende ungeklärte Zytopenie widerspricht CHIP.":"Persistent unexplained cytopenia is incompatible with CHIP.","Mehr Panel = mehr Diagnose":"More panel = more diagnosis","Diagnosekriterien bleiben klinisch-morphologisch integriert.":"Diagnostic criteria remain clinically and morphologically integrated.","Der richtige Befund ist die Zwischenkategorie":"The correct result is the intermediate category","Die Mutationen sind echt und klinisch relevant, aber weder 'Zufalls-CHIP' noch bereits diagnostisches MDS. Die Zytopenie verschiebt den Fall in CCUS – ein Ergebnis, das weniger endgültig klingt, aber fachlich präziser ist.":"The mutations are real and clinically relevant, but represent neither 'incidental CHIP' nor diagnostic MDS yet. Cytopenia moves the case into CCUS — a result that sounds less final but is more precise.","Er trainiert, diagnostische Unsicherheit korrekt zu benennen statt molekulare Befunde zu overcallen.":"It trains the ability to name diagnostic uncertainty correctly instead of overcalling molecular findings.","CCUS sauber erkannt":"CCUS correctly recognized","Zytopenie + DNMT3A/TET2-Klon, aber keine MDS-definierenden Kriterien → CCUS.":"Cytopenia + DNMT3A/TET2 clone, but no MDS-defining criteria → CCUS.","Klon, Klinik und Morphologie korrekt integriert.":"Clone, clinical context, and morphology integrated correctly.","CH erkannt, Kategorie unscharf":"CH recognized, category unclear","MDS wird vermieden, aber trotz Zytopenie 'CHIP' berichtet.":"MDS is avoided, but despite cytopenia it is reported as 'CHIP'.","Definition nicht sauber angewendet.":"Definition not applied correctly.","NGS diagnostiziert MDS":"NGS diagnoses MDS","DNMT3A/TET2 werden allein als MDS-Beweis verwendet.":"DNMT3A/TET2 alone are used as proof of MDS.","Molekulares Overcalling.":"Molecular overcalling.","Zytopenien verschlechtern sich":"Cytopenias worsen","Erneute Knochenmarkdiagnostik inklusive Morphologie/Genetik.":"Repeat bone-marrow workup including morphology/genetics.","Progression kann neue definierende Kriterien sichtbar machen.":"Progression may reveal new defining criteria.","Stabiler Verlauf":"Stable course","Strukturiertes Monitoring.":"Structured monitoring.","Keine unnötige Neoplasietherapie.":"No unnecessary neoplasm therapy.","DNMT3A/TET2/ASXL1 sind häufige Gene klonaler Hämatopoese.":"DNMT3A/TET2/ASXL1 are common genes in clonal hematopoiesis.","CHIP, CCUS und MDS teilen molekulare Befunde; Kontext trennt die Kategorien.":"CHIP, CCUS, and MDS share molecular findings; context separates the categories.","CHIP ohne ungeklärte Zytopenie, CCUS mit Zytopenie aber ohne definierende Neoplasiekriterien.":"CHIP without unexplained cytopenia, CCUS with cytopenia but without defining neoplasm criteria.","NGS erhöht Sensitivität für Klonalität, nicht automatisch Spezifität für MDS.":"NGS increases sensitivity for clonality, not automatically specificity for MDS.","Verlauf kann Teil der Diagnostik sein.":"Longitudinal follow-up can be part of the diagnostic process.","Die Mutationen belegen einen myeloischen Klon. Wegen persistierender ungeklärter Zytopenien ist CHIP unpassend; wegen fehlender MDS-definierender Morphologie/Genetik ist ein MDS derzeit nicht gesichert. Die präziseste Einordnung ist CCUS mit strukturierter Verlaufskontrolle.":"The mutations establish a myeloid clone. Because of persistent unexplained cytopenias, CHIP is inappropriate; because MDS-defining morphology/genetics are absent, MDS is not currently established. The most precise classification is CCUS with structured follow-up.","Mutation ≠ Neoplasie":"Mutation ≠ neoplasm","CHIP vs CCUS":"CHIP vs CCUS","Morphologie integriert":"Morphology integrated","Monitoring":"Monitoring","Welche Mutationen erhöhen die Progressionswahrscheinlichkeit stärker?":"Which mutations confer a higher probability of progression?","Wie verändert VAF die Risikoeinschätzung, ohne die Diagnose allein zu definieren?":"How does VAF modify risk assessment without defining the diagnosis by itself?","Wann wiederholt man das Knochenmark?":"When should bone marrow assessment be repeated?","CCUS statt binärer CHIP/MDS-Antwort":"CCUS instead of a binary CHIP/MDS answer","Klonalität und Neoplasie sind nicht dasselbe":"Clonality and neoplasia are not the same","Zytopenie → Klon → Morphologie → CCUS/MDS-Entscheidung":"Cytopenia → clone → morphology → CCUS/MDS decision","MSI-H-CRC mit MLH1/PMS2-Verlust: BRAF-Wildtyp ist noch kein Lynch-Syndrom":"MSI-H CRC with MLH1/PMS2 loss: BRAF wild type is not yet Lynch syndrome","MLH1-Promotor-Methylierung bei MSI…":"MLH1 promoter methylation in MSI…","Viszeralonkologie / Humangenetik-Screening":"Visceral oncology / genetic screening","71-jährige Patientin mit rechtsseitigem Kolonkarzinom. Universal-Screening zeigt Verlust von MLH1/PMS2 und MSI-H.":"71-year-old woman with right-sided colon cancer. Universal screening shows loss of MLH1/PMS2 and MSI-H.","Ist bei BRAF-Wildtyp nun automatisch von Lynch-Syndrom auszugehen – oder fehlt noch der entscheidende epigenetische Reflex?":"Does BRAF wild type now automatically imply Lynch syndrome—or is the decisive epigenetic reflex test still missing?","Der Tumorbefund soll therapeutisch und hereditär korrekt eingeordnet werden.":"The tumor finding must be classified correctly for both therapy and hereditary risk.","Rechtsseitiges, lymphozytenreiches Adenokarzinom.":"Right-sided, lymphocyte-rich adenocarcinoma.","Familie":"Family history","Keine auffällige Häufung Lynch-assoziierter Tumoren dokumentiert.":"No notable clustering of Lynch-associated tumors documented.","MLH1/PMS2-Verlust, MSI-H; BRAF V600E nicht nachweisbar.":"MLH1/PMS2 loss, MSI-H; BRAF V600E not detected.","BRAF-Wildtyp wird fälschlich als positiver Lynch-Nachweis interpretiert.":"BRAF wild type is incorrectly interpreted as positive evidence of Lynch syndrome.","Mäßig differenziertes Adenokarzinom mit medullär/lymphozytenreichen Anteilen.":"Moderately differentiated adenocarcinoma with medullary/lymphocyte-rich areas.","MLH1 und PMS2 verloren; MSH2/MSH6 erhalten.":"MLH1 and PMS2 lost; MSH2/MSH6 retained.","MSI-high bestätigt.":"MSI-high confirmed.","Somatische MLH1-Promotor-Methylierung als Ursache der MLH1-Inaktivierung.":"Somatic MLH1 promoter methylation as the cause of MLH1 inactivation.","FFPE-Resektat mit hohem Tumoranteil.":"FFPE resection specimen with high tumor content.","Methylierung":"Methylation","gezielter validierter MLH1-Promotor-Assay möglich.":"A targeted validated MLH1 promoter assay is feasible.","Wildtyp – informativ, aber nicht beweisend für Lynch.":"Wild type—informative, but not proof of Lynch syndrome.","Ein negatives Ausschlussmerkmal darf nicht in einen positiven hereditären Nachweis umgedeutet werden.":"A negative exclusion marker must not be reinterpreted as positive hereditary evidence.","MLH1-Promotor-Methylierung":"MLH1 promoter methylation","Verlust von MLH1/PMS2 bei erhaltener MSH2/MSH6-Expression.":"Loss of MLH1/PMS2 with retained MSH2/MSH6 expression.","MSI-high bestätigt; damit besteht ein therapeutisch relevanter dMMR/MSI-H-Kontext.":"MSI-high confirmed; this establishes a therapeutically relevant dMMR/MSI-H context.","BRAF V600E nicht nachweisbar. Das entfernt ein starkes Indiz für sporadische MLH1-Inaktivierung, beweist Lynch aber nicht.":"BRAF V600E not detected. This removes a strong clue for sporadic MLH1 inactivation, but does not prove Lynch syndrome.","Deutliche MLH1-Promotor-Hypermethylierung. Die Konstellation spricht bei dieser 71-jährigen Patientin stark für eine sporadische epigenetische MLH1-Silenzierung; klinische/familiäre Auffälligkeiten bleiben dennoch zu berücksichtigen.":"Marked MLH1 promoter hypermethylation. In this 71-year-old woman, the constellation strongly supports sporadic epigenetic MLH1 silencing; clinical/family-history features must nevertheless still be considered.","Kernbefund":"Key finding","dMMR/MSI-H durch MLH1/PMS2-Verlust.":"dMMR/MSI-H due to MLH1/PMS2 loss.","Wildtyp – kein Lynch-Beweis.":"Wild type—not proof of Lynch syndrome.","Der dMMR/MSI-H-Status ist therapeutisch relevant. Für die hereditäre Einordnung zeigt der MLH1/PMS2-Verlust zunächst nur die Richtung der Reflexdiagnostik. BRAF-Wildtyp beweist kein Lynch-Syndrom. Die nachgewiesene MLH1-Promotor-Hypermethylierung spricht stark für eine sporadische epigenetische MLH1-Inaktivierung; Alter, Familienanamnese und besondere klinische Konstellationen können dennoch eine weitergehende humangenetische Beurteilung rechtfertigen.":"The dMMR/MSI-H status is therapeutically relevant. For hereditary classification, MLH1/PMS2 loss initially only indicates the direction of reflex testing. BRAF wild type does not prove Lynch syndrome. The detected MLH1 promoter hypermethylation strongly supports sporadic epigenetic MLH1 inactivation; age, family history, and special clinical constellations may nevertheless justify further genetic evaluation.","Teilbefund: MLH1/PMS2-Verlust + MSI-H ist nicht synonym mit Lynch; die Ursache der MLH1-Inaktivierung muss reflexdiagnostisch geklärt werden.":"Partial result: MLH1/PMS2 loss + MSI-H is not synonymous with Lynch syndrome; the cause of MLH1 inactivation must be clarified by reflex testing.","dMMR/MSI-H therapeutisch korrekt einordnen":"Classify dMMR/MSI-H correctly for therapy","BRAF-Wildtyp nicht als Lynch-Beweis interpretieren":"Do not interpret BRAF wild type as proof of Lynch syndrome","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex priorisieren":"Prioritize MLH1 promoter methylation as the direct epigenetic reflex test","Alter/Familie/klinischen Kontext trotz Methylierung berücksichtigen":"Consider age/family/clinical context despite methylation","Falschaussage: BRAF-Wildtyp + MLH1/PMS2-Verlust = Lynch gesichert":"False statement: BRAF wild type + MLH1/PMS2 loss = Lynch syndrome confirmed","Optimale Lösung: MSI-H/dMMR therapeutisch nutzen, MLH1/PMS2-Verlust hereditär reflexdiagnostisch abarbeiten und BRAF-Wildtyp nicht überinterpretieren; positive MLH1-Methylierung spricht stark für sporadische Silenzierung.":"Optimal solution: use MSI-H/dMMR therapeutically, investigate MLH1/PMS2 loss with appropriate hereditary reflex testing, and do not overinterpret BRAF wild type; positive MLH1 methylation strongly supports sporadic silencing.","MLH1 methylation":"MLH1 methylation","BRAF wild type":"BRAF wild type","BRAF-Wildtyp ist kein positiver Lynch-Test":"BRAF wild type is not a positive Lynch test","Gastrointestinale Molekularpathologie / MTB / Humangenetik":"Gastrointestinal molecular pathology / MTB / clinical genetics","MLH1/PMS2-Verlust als Trigger einer spezifischen Reflexdiagnostik verstehen.":"Understand MLH1/PMS2 loss as the trigger for specific reflex testing.","MSI-H/dMMR therapeutische und hereditäre Ebenen trennen.":"Separate the therapeutic and hereditary dimensions of MSI-H/dMMR.","BRAF V600E positiv als starkes sporadisches Indiz, BRAF-Wildtyp aber nicht als Lynch-Beweis verstehen.":"Understand BRAF V600E positivity as a strong sporadic clue, but BRAF wild type not as proof of Lynch syndrome.","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex einordnen.":"Classify MLH1 promoter methylation as the direct epigenetic reflex test.","Alter und Familienanamnese trotz scheinbar sporadischem Muster berücksichtigen.":"Consider age and family history despite an apparently sporadic pattern.","MLH1 und PMS2 fehlen, der Tumor ist MSI-H – und BRAF ist Wildtyp. Im Board fällt sofort der Satz: 'Dann ist es Lynch.' Genau an dieser Stelle setzt der Fall an.":"MLH1 and PMS2 are absent, the tumor is MSI-H—and BRAF is wild type. In the board someone immediately says: 'Then it's Lynch.' That is exactly where this case begins.","71-jährige Patientin mit rechtsseitigem MSI-H-CRC und MLH1/PMS2-Verlust. BRAF V600E ist nicht nachweisbar. Die zentrale Frage ist, ob das bereits Lynch beweist oder ob die epigenetische Ursache der MLH1-Silenzierung noch direkt geprüft werden muss.":"71-year-old woman with right-sided MSI-H CRC and MLH1/PMS2 loss. BRAF V600E is not detected. The central question is whether this already proves Lynch syndrome or whether the epigenetic cause of MLH1 silencing still needs direct testing.","Therapieebene":"Therapeutic dimension","MSI-H/dMMR ist bereits ein wichtiger prädiktiver Tumorbefund.":"MSI-H/dMMR is already an important predictive tumor finding.","Die Therapieaussage braucht nicht erst eine Lynch-Diagnose.":"The therapeutic statement does not require a prior Lynch diagnosis.","MLH1/PMS2-Verlust kann sporadisch oder hereditär entstehen.":"MLH1/PMS2 loss can arise sporadically or hereditarily.","Reflexdiagnostik klärt die Ursache.":"Reflex testing clarifies the cause.","Negativ ist nicht positiv":"Negative is not positive","BRAF-Wildtyp entfernt ein sporadisches Indiz, beweist aber Lynch nicht.":"BRAF wild type removes a sporadic clue, but does not prove Lynch syndrome.","Ausschlussmarker nicht in Bestätigungsmarker verwandeln.":"Do not turn an exclusion marker into a confirmation marker.","MLH1/PMS2 verloren":"MLH1/PMS2 lost","MSI-high":"MSI-high","V600E nicht nachweisbar":"V600E not detected","Ausreichendes Resektat für gezielte MLH1-Methylierungsanalyse.":"Adequate resection specimen for targeted MLH1 methylation analysis.","Kein Grund für ein breites Panel, wenn die Reflexfrage fokussiert beantwortet werden kann.":"No need for a broad panel when the focused reflex question can be answered directly.","Klinischer Kontext bleibt Teil der Lynch-Risikobewertung.":"Clinical context remains part of Lynch risk assessment.","Was bedeutet BRAF-Wildtyp bei MLH1/PMS2-Verlust?":"What does BRAF wild type mean in the setting of MLH1/PMS2 loss?","Lynch bleibt möglich, ist aber nicht bewiesen; MLH1-Promotor-Methylierung sollte direkt geprüft werden.":"Lynch syndrome remains possible but is not proven; MLH1 promoter methylation should be tested directly.","Lynch ist damit gesichert.":"Lynch syndrome is thereby confirmed.","Sporadisch ist damit gesichert.":"A sporadic origin is thereby confirmed.","BRAF hat nie Bedeutung im CRC-Lynch-Screening.":"BRAF is never relevant in CRC Lynch screening.","Negatives BRAF-Ergebnis ist kein positiver Lynch-Nachweis.":"A negative BRAF result is not positive evidence of Lynch syndrome.","MLH1-Promotor-Methylierung ist deutlich positiv. Was ist die beste Interpretation?":"MLH1 promoter methylation is clearly positive. What is the best interpretation?","Starkes Indiz für sporadische epigenetische MLH1-Silenzierung; klinische Sonderkonstellationen trotzdem beachten.":"Strong evidence for sporadic epigenetic MLH1 silencing; still consider special clinical constellations.","Beweist Lynch.":"Proves Lynch syndrome.","Macht MSI-H therapeutisch irrelevant.":"Makes MSI-H therapeutically irrelevant.","Ist bei CRC bedeutungslos.":"Is irrelevant in CRC.","Tumorale MLH1-Hypermethylierung erklärt häufig sporadischen MLH1/PMS2-Verlust.":"Tumoral MLH1 hypermethylation frequently explains sporadic MLH1/PMS2 loss.","Welche Aussage trennt die Ebenen korrekt?":"Which statement correctly separates the two dimensions?","MSI-H/dMMR ist therapeutisch relevant; Lynch-Abklärung ist eine zusätzliche hereditäre Frage.":"MSI-H/dMMR is therapeutically relevant; Lynch evaluation is an additional hereditary question.","Immuntherapie darf erst nach Keimbahnbefund diskutiert werden.":"Immunotherapy may only be discussed after a germline result.","dMMR und Lynch sind Synonyme.":"dMMR and Lynch syndrome are synonyms.","Nur BRAF entscheidet beide Ebenen.":"Only BRAF determines both dimensions.","Tumorbiomarker und hereditäre Diagnose sind verwandt, aber nicht identisch.":"Tumor biomarker and hereditary diagnosis are related, but not identical.","Wann sollte trotz MLH1-Methylierung genauer hingesehen werden?":"When should one look more closely despite MLH1 methylation?","Bei ungewöhnlich jungem Alter, auffälliger Familien-/Eigenanamnese oder anderer klinischer Diskordanz.":"With unusually young age, suspicious personal/family history, or another clinical discordance.","Nie.":"Never.","Immer vollständige Keimbahndiagnostik unabhängig vom Kontext.":"Always perform complete germline testing regardless of context.","Nur bei PD-L1-Positivität.":"Only with PD-L1 positivity.","Seltene konstitutionelle Epimutationen und klinische Sonderkonstellationen verhindern absolute Aussagen.":"Rare constitutional epimutations and special clinical constellations preclude absolute statements.","Formulieren Sie eine zweigeteilte MTB-Aussage: therapeutische Bedeutung von MSI-H/dMMR und hereditäre Einordnung des MLH1/PMS2-Verlusts nach BRAF- und MLH1-Methylierungsbefund.":"Formulate a two-part MTB statement: the therapeutic significance of MSI-H/dMMR and the hereditary interpretation of MLH1/PMS2 loss after BRAF and MLH1 methylation results.","dMMR/MSI-H therapeutisch einordnen.":"Classify dMMR/MSI-H therapeutically.","MLH1/PMS2-Verlust als Reflextrigger verstehen.":"Understand MLH1/PMS2 loss as a reflex-testing trigger.","BRAF-Wildtyp nicht als Lynch-Beweis formulieren.":"Do not report BRAF wild type as proof of Lynch syndrome.","MLH1-Promotor-Methylierung direkt testen.":"Test MLH1 promoter methylation directly.","Positive Methylierung als starkes sporadisches Indiz berichten.":"Report positive methylation as strong evidence of sporadic silencing.","Klinische Sonderkonstellationen offenhalten.":"Keep special clinical constellations open.","In Laborpfaden, die BRAF und Methylierung anders sequenzieren, ist die Kernaussage identisch: BRAF-WT allein reicht nicht für Lynch-Diagnose.":"In laboratory pathways that sequence BRAF and methylation differently, the key message is identical: BRAF wild type alone is not sufficient for a Lynch diagnosis.","Bei klarer hereditärer Auffälligkeit humangenetische Vorstellung trotz Tumormethylierung erwägen.":"If hereditary features are clearly suspicious, consider genetic consultation despite tumor methylation.","BRAF-WT = Lynch":"BRAF wild type = Lynch syndrome","Negatives Ausschlussindiz ist kein positiver hereditärer Nachweis.":"A negative exclusion clue is not positive hereditary evidence.","dMMR = Lynch":"dMMR = Lynch syndrome","Viele MLH1/PMS2-defiziente CRC sind sporadisch methyliert.":"Many MLH1/PMS2-deficient CRCs are sporadically methylated.","Methylierung löscht MSI-Therapiebedeutung":"Methylation removes the therapeutic significance of MSI","Therapeutische und hereditäre Ebenen werden vermischt.":"Therapeutic and hereditary dimensions are conflated.","Der BRAF-Wildtyp führt in die falsche Sicherheit":"BRAF wild type creates false certainty","Obwohl BRAF V600E fehlt, ist der MLH1-Promotor deutlich methyliert. Das kippt die intuitive 'BRAF-WT = Lynch'-Kurzform und zeigt, warum der direkte epigenetische Reflex diagnostisch stärker ist.":"Although BRAF V600E is absent, the MLH1 promoter is clearly methylated. This overturns the intuitive shortcut 'BRAF wild type = Lynch' and shows why the direct epigenetic reflex test is diagnostically stronger.","Der Fall trainiert Negativbefunde, Reflexdiagnostik und die Trennung von Tumortherapie und Familienmedizin.":"The case trains interpretation of negative findings, reflex diagnostics, and separation of tumor therapy from family medicine.","Zwei Ebenen sauber getrennt":"Two dimensions cleanly separated","MSI-H/dMMR therapeutisch relevant; BRAF-WT kein Lynch-Beweis; MLH1-Methylierung positiv → sporadische Silenzierung stark wahrscheinlich.":"MSI-H/dMMR therapeutically relevant; BRAF wild type is not proof of Lynch syndrome; MLH1 methylation positive → sporadic silencing highly likely.","Reflexdiagnostik korrekt.":"Reflex diagnostics correct.","Lynch offen, Methylierung vergessen":"Lynch remains open, methylation forgotten","BRAF-WT wird korrekt nicht überinterpretiert, aber der direkte MLH1-Reflex fehlt.":"BRAF wild type is correctly not overinterpreted, but the direct MLH1 reflex test is missing.","Diagnostik unvollständig.":"Diagnostic workup incomplete.","Keimbahndiagnose aus negativem Tumormarker abgeleitet.":"Germline diagnosis inferred from a negative tumor marker.","Kritisches Overcalling.":"Critical overcalling.","MLH1-Methylierung positiv":"MLH1 methylation positive","Sporadische MLH1-Silenzierung als wahrscheinlich berichten; Klinik/Familie abgleichen.":"Report sporadic MLH1 silencing as likely; correlate with clinical context/family history.","Viele unnötige Keimbahnabklärungen können vermieden werden, ohne Sonderfälle zu ignorieren.":"Many unnecessary germline evaluations can be avoided without ignoring exceptional cases.","Humangenetische/germline Abklärung priorisieren.":"Prioritize genetic/germline evaluation.","Lynch-Verdacht bleibt bestehen.":"Suspicion of Lynch syndrome remains.","MLH1/PMS2-Verlust ist kein automatischer Lynch-Befund.":"MLH1/PMS2 loss is not automatically a Lynch finding.","BRAF V600E kann sporadische MLH1-Inaktivierung stützen; BRAF-Wildtyp beweist Lynch nicht.":"BRAF V600E can support sporadic MLH1 inactivation; BRAF wild type does not prove Lynch syndrome.","MLH1-Promotor-Methylierung ist ein direkter epigenetischer Reflex.":"MLH1 promoter methylation is a direct epigenetic reflex test.","MSI-H/dMMR hat eine therapeutische Aussage unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"MSI-H/dMMR has therapeutic significance regardless of whether the cause is sporadic or hereditary.","Sehr junges Alter oder auffällige Familienanamnese können trotz Tumormethylierung weitere Abklärung rechtfertigen.":"Very young age or a suspicious family history may justify further evaluation despite tumor methylation.","MSI-H/dMMR ist therapeutisch relevant. Für die hereditäre Einordnung ist BRAF-Wildtyp nicht beweisend; die positive MLH1-Promotor-Methylierung spricht stark für sporadische MLH1-Silenzierung. Alter und Familienanamnese bleiben als Sicherheitsnetz bestehen.":"MSI-H/dMMR is therapeutically relevant. For hereditary classification, BRAF wild type is not conclusive; positive MLH1 promoter methylation strongly supports sporadic MLH1 silencing. Age and family history remain a safety net.","BRAF-WT nicht overcallen":"Do not overcall BRAF wild type","Therapie vs Heredität":"Therapy vs heredity","Kontext":"Context","Warum ist ein negativer Marker selten ein positiver Beweis?":"Why is a negative marker rarely positive proof?","Wie unterscheiden sich BRAF- und MLH1-Methylierungsreflex?":"How do BRAF and MLH1 methylation reflex tests differ?","Wann kann Tumormethylierung eine hereditäre Ursache nicht vollständig ausschließen?":"When can tumor methylation fail to completely exclude a hereditary cause?","MLH1-Methylierung positiv trotz BRAF-WT":"MLH1 methylation positive despite BRAF wild type","BRAF-Wildtyp ist kein Lynch-Beweis":"BRAF wild type is not proof of Lynch syndrome","MMR/MSI → BRAF-Kontext → MLH1-Methylierung → hereditäre Einordnung":"MMR/MSI → BRAF context → MLH1 methylation → hereditary classification","mCRC und Bevacizumab: Anti-VEGF braucht keinen VHL-Test":"mCRC and bevacizumab: anti-VEGF does not require a VHL test","mCRC: Bevacizumab und VEGF-Angioge…":"mCRC: bevacizumab and VEGF angiogene…","63-jähriger Patient mit metastasiertem rechtsseitigem Kolonkarzinom, KRAS p.G12D-mutiert. Im Board wird Bevacizumab als Bestandteil der Systemtherapie diskutiert.":"63-year-old man with metastatic right-sided colon cancer, KRAS p.G12D-mutated. The board discusses bevacizumab as part of systemic therapy.","Muss vor Anti-VEGF-Therapie die VHL/HIF/VEGF-Achse des Tumors molekular getestet oder eine hohe VEGF-Expression nachgewiesen werden?":"Before anti-VEGF therapy, must the tumor's VHL/HIF/VEGF axis be molecularly tested or high VEGF expression demonstrated?","Therapieentscheidung in dieser Woche.":"Therapy decision this week.","Rechtsseitiges mCRC mit multiplen Lebermetastasen.":"Right-sided mCRC with multiple liver metastases.","KRAS p.G12D; BRAF-Wildtyp; pMMR/MSS aus Basisdiagnostik.":"KRAS p.G12D; BRAF wild type; pMMR/MSS from baseline diagnostics.","Anti-EGFR ist wegen RAS-Mutation nicht der naheliegende Weg; eine antiangiogene Kombination wird diskutiert.":"Anti-EGFR is not the obvious route because of the RAS mutation; an antiangiogenic combination is being discussed.","Mechanistische Biologie wird mit einem notwendigen prädiktiven Companion Diagnostic verwechselt.":"Mechanistic biology is confused with a required predictive companion diagnostic.","Konventionelles kolorektales Adenokarzinom mit vitalen Metastasenarealen.":"Conventional colorectal adenocarcinoma with viable metastatic areas.","Gefäße":"Vessels","Tumor zeigt erwartbare Neovaskularisation; kein spezifischer morphologischer Selektionsmarker.":"The tumor shows expected neovascularization; there is no specific morphological selection marker.","Basisprofil":"Baseline profile","RAS-mutiert, pMMR/MSS.":"RAS-mutated, pMMR/MSS.","Welche Rolle spielt VEGF-Biologie für das Verständnis – und welche gerade nicht für die Testauswahl?":"What role does VEGF biology play in understanding the treatment—and what role specifically does it not play in test selection?","FFPE-Lebermetastase, ausreichend für Zusatzanalysen.":"FFPE liver metastasis, adequate for additional analyses.","Begrenzt; keine diagnostische Fragestellung rechtfertigt einen RCC-spezifischen VHL/HIF-Test.":"Limited; no diagnostic question justifies an RCC-specific VHL/HIF test.","Mechanismus":"Mechanism","VEGF-A ist ein zentraler proangiogener Ligand; Bevacizumab neutralisiert VEGF-A.":"VEGF-A is a central proangiogenic ligand; bevacizumab neutralizes VEGF-A.","Ein biologisch plausibler Signalweg ist nicht automatisch ein validierter Patientenselektions-Biomarker.":"A biologically plausible pathway is not automatically a validated patient-selection biomarker.","VEGF-/Angiogenese-Kontext korrekt einordnen":"Classify VEGF/angiogenesis context correctly","CRC-Basisprofil":"CRC baseline profile","KRAS p.G12D, BRAF-Wildtyp, keine zusätzliche Alteration, die einen Anti-VEGF-spezifischen Companion-Diagnostic-Pfad definiert.":"KRAS p.G12D, BRAF wild type, no additional alteration defining an anti-VEGF-specific companion-diagnostic pathway.","VEGF-Kontext":"VEGF context","Anti-VEGF hemmt einen zentralen Angiogeneseweg; beim mCRC existiert jedoch kein etablierter routinemäßiger Tumor-VEGF- oder VHL/HIF-Test, der vor Bevacizumab positiv sein muss.":"Anti-VEGF inhibits a central angiogenesis pathway; however, in mCRC there is no established routine tumor VEGF or VHL/HIF test that must be positive before bevacizumab.","Molekularer CRC-Kontext":"Molecular CRC context","KRAS-mutiert, pMMR/MSS.":"KRAS-mutated, pMMR/MSS.","Kernfrage":"Core question","Biologischen Wirkmechanismus von prädiktiver Testpflicht trennen.":"Separate biological mechanism of action from predictive testing requirements.","Bevacizumab adressiert die VEGF-A-vermittelte Angiogenese, seine klinische Anwendung beim mCRC setzt aber keinen positiven VHL/HIF-/VEGF-Tumortest voraus. Die RAS-Mutation erklärt hier den fehlenden anti-EGFR-Kontext, ist aber kein Gegenargument gegen die antiangiogene Wirklogik. Zusätzliche VHL/HIF-Testung wäre ein aus dem RCC übertragener Low-value-Copyover.":"Bevacizumab targets VEGF-A-mediated angiogenesis, but its clinical use in mCRC does not require a positive VHL/HIF/VEGF tumor test. The RAS mutation here explains the lack of an anti-EGFR context, but is not an argument against the antiangiogenic mechanism. Additional VHL/HIF testing would be a low-value copyover from RCC.","Teilbefund: VEGF ist biologisch relevant, aber es fehlt die Trennung zwischen Wirkmechanismus und validiertem Selektionsbiomarker.":"Partial result: VEGF is biologically relevant, but the distinction between mechanism of action and validated selection biomarker is missing.","VEGF-A/Angiogenese als Wirkmechanismus erklären":"Explain VEGF-A/angiogenesis as the mechanism of action","Keinen routinemäßigen positiven VEGF-/VHL-Test als Voraussetzung behaupten":"Do not claim a routine positive VEGF/VHL test as a prerequisite","RAS-Mutation korrekt auf anti-EGFR, nicht auf Anti-VEGF beziehen":"Relate RAS mutation correctly to anti-EGFR, not anti-VEGF","RCC-spezifische VHL/HIF-Testung vermeiden":"Avoid RCC-specific VHL/HIF testing","Falschaussage: Bevacizumab nur bei molekular aktivierter VHL/HIF-Achse":"False statement: bevacizumab only with molecular activation of the VHL/HIF axis","Optimale Lösung: Anti-VEGF biologisch sauber erklären, aber keinen erfundenen Companion Diagnostic verlangen; RAS-Status und VEGF-Therapieachse sind unterschiedliche Entscheidungsebenen.":"Optimal solution: explain anti-VEGF biology correctly without inventing a companion diagnostic; RAS status and the VEGF therapeutic axis are separate decision layers.","Bevacizumab":"Bevacizumab","VEGF":"VEGF","Angiogenese":"Angiogenesis","KRAS":"KRAS","Biomarker hierarchy":"Biomarker hierarchy","Anti-VEGF ist ein Wirkmechanismus, kein VHL-Companion-Diagnostic":"Anti-VEGF is a mechanism of action, not a VHL companion diagnostic","Gastroonkologie / Molekularpathologie / MTB":"Gastrointestinal oncology / molecular pathology / MTB","VEGF-Angiogenese als Wirkmechanismus von Bevacizumab erklären.":"Explain VEGF angiogenesis as the mechanism of action of bevacizumab.","Wirkmechanismus und prädiktiven Companion Diagnostic sauber trennen.":"Clearly separate mechanism of action from predictive companion diagnostic.","RAS-Status korrekt auf anti-EGFR und nicht auf Anti-VEGF beziehen.":"Relate RAS status correctly to anti-EGFR and not to anti-VEGF.","Entitätsfremde VHL/HIF-Testung beim mCRC vermeiden.":"Avoid entity-inappropriate VHL/HIF testing in mCRC.","Material- und Testökonomie als Teil guter Präzisionsonkologie verstehen.":"Understand material and testing economy as part of good precision oncology.","Der Tumor ist KRAS-mutiert. Jemand fragt, ob man für Bevacizumab jetzt noch 'VHL/HIF/VEGF molekular bestätigen' müsse. Genau diese scheinbar logische Zusatzdiagnostik ist der Fehler.":"The tumor is KRAS-mutated. Someone asks whether VHL/HIF/VEGF now needs to be 'molecularly confirmed' for bevacizumab. This seemingly logical additional testing is exactly the error.","63-jähriger Patient mit KRAS-mutiertem, pMMR/MSS mCRC. Bevacizumab wird als Teil einer systemischen Kombination diskutiert. Die Aufgabe ist nicht, einen neuen Biomarker zu erfinden, sondern Mechanismus, RAS-Kontext und echte Testpflicht zu trennen.":"63-year-old man with KRAS-mutated, pMMR/MSS mCRC. Bevacizumab is being considered as part of systemic combination therapy. The task is not to invent a new biomarker, but to separate mechanism, RAS context, and genuine testing requirements.","RAS beantwortet eine andere Frage":"RAS answers a different question","KRAS p.G12D schließt einen klassischen anti-EGFR-Kontext aus.":"KRAS p.G12D excludes a classic anti-EGFR context.","Das macht Anti-VEGF nicht biologisch unplausibel.":"That does not make anti-VEGF biologically implausible.","VEGF ist zentral":"VEGF is central","Tumorangiogenese benötigt proangiogene Signale.":"Tumor angiogenesis requires proangiogenic signals.","Zentraler Mechanismus bedeutet nicht automatisch Companion Diagnostic.":"A central mechanism does not automatically mean a companion diagnostic.","RCC-Copyover":"RCC copyover","VHL/HIF ist beim ccRCC kanonisch.":"VHL/HIF is canonical in ccRCC.","Signalwege dürfen nicht blind zwischen Entitäten als Testalgorithmus übertragen werden.":"Pathways must not be blindly transferred between entities as testing algorithms.","CRC-Profil":"CRC profile","KRAS p.G12D, BRAF-WT, pMMR/MSS":"KRAS p.G12D, BRAF wild type, pMMR/MSS","metastasiert, systemische Therapie geplant":"Metastatic, systemic therapy planned","ausreichend, aber kein Grund für unnötige Zusatztests":"Adequate, but no reason for unnecessary additional testing","Keine validierte positive VEGF-/VHL-Testpflicht vor Bevacizumab im mCRC.":"No validated requirement for a positive VEGF/VHL test before bevacizumab in mCRC.","Entitätsfremde Testung verbraucht Ressourcen ohne Entscheidungsgewinn.":"Entity-inappropriate testing consumes resources without adding decision value.","Mechanistische Erklärung kann ohne zusätzlichen Wet-lab-Test erfolgen.":"The mechanistic explanation can be given without an additional wet-lab test.","Was bedeutet KRAS p.G12D für die Anti-VEGF-Frage?":"What does KRAS p.G12D mean for the anti-VEGF question?","Es betrifft die anti-EGFR-Logik; es ist kein automatischer Ausschluss von Bevacizumab.":"It concerns anti-EGFR logic; it is not an automatic exclusion of bevacizumab.","Es ist eine Kontraindikation gegen Anti-VEGF.":"It is a contraindication to anti-VEGF.","Es beweist besonders gutes Bevacizumab-Ansprechen.":"It proves particularly good response to bevacizumab.","RAS hat im CRC gar keine therapeutische Bedeutung.":"RAS has no therapeutic relevance at all in CRC.","Therapieachsen müssen getrennt gehalten werden.":"Therapeutic axes must be kept separate.","Braucht Bevacizumab einen positiven Tumor-VEGF/VHL-Test?":"Does bevacizumab require a positive tumor VEGF/VHL test?","Nein; der Wirkmechanismus ist biologisch VEGF-gerichtet, aber es existiert kein solcher routinemäßiger Companion-Diagnostic-Pfad.":"No; the mechanism of action is biologically VEGF-directed, but no such routine companion-diagnostic pathway exists.","Ja, VHL-Mutation ist Voraussetzung.":"Yes, a VHL mutation is required.","Ja, hohe VEGF-IHC muss dokumentiert sein.":"Yes, high VEGF IHC must be documented.","Ja, HIF-2α muss mutiert sein.":"Yes, HIF-2α must be mutated.","Mechanismus und Testpflicht sind nicht dasselbe.":"Mechanism of action and testing requirement are not the same.","Warum ist ein VHL/HIF-Panel hier Low-value?":"Why is a VHL/HIF panel low-value here?","Es importiert ccRCC-Biologie in einen CRC-Therapiealgorithmus ohne validierten Selektionsnutzen.":"It imports ccRCC biology into a CRC treatment algorithm without validated selection benefit.","Nur weil es teuer ist.":"Only because it is expensive.","Weil CRC keine DNA enthält.":"Because CRC contains no DNA.","Weil VEGF im CRC keine Rolle spielt.":"Because VEGF has no role in CRC.","Entitätsspezifische Evidenz entscheidet.":"Entity-specific evidence determines the answer.","Was ist hier Präzisionsonkologie?":"What is precision oncology here?","Die richtigen wenigen Informationen verwenden und unnötige Tests weglassen.":"Use the few right pieces of information and omit unnecessary tests.","Immer das breiteste Panel bestellen.":"Always order the broadest panel.","Jeden bekannten Signalweg molekular bestätigen.":"Molecularly confirm every known pathway.","Nur positive Biomarker zählen.":"Only positive biomarkers count.","Präzision ist nicht Informationsmaximierung.":"Precision is not information maximization.","Formulieren Sie die Anti-VEGF-Rationale und begründen Sie explizit, warum weder KRAS-Mutation noch fehlende VHL/HIF-Testung die Bevacizumab-Logik aufheben.":"Formulate the anti-VEGF rationale and explicitly explain why neither the KRAS mutation nor the absence of VHL/HIF testing invalidates the bevacizumab logic.","KRAS p.G12D als anti-EGFR-Resistenzkontext benennen.":"Identify KRAS p.G12D as an anti-EGFR resistance context.","VEGF-Angiogenese als Wirkmechanismus erklären.":"Explain VEGF angiogenesis as the mechanism of action.","Keine positive VEGF-/VHL-Testpflicht erfinden.":"Do not invent a positive VEGF/VHL testing requirement.","VHL/HIF-Testung als entitätsfremden Low-value-Test vermeiden.":"Avoid VHL/HIF testing as an entity-inappropriate low-value test.","Therapieentscheidung im klinischen CRC-Kontext belassen.":"Keep the therapy decision within the clinical CRC context.","Breites CRC-Panel nur, wenn andere therapeutische Fragestellungen offen sind.":"Use a broad CRC panel only if other therapeutic questions remain open.","VEGF-Biologie rein interpretativ erklären, ohne Zusatztest.":"Explain VEGF biology interpretively without additional testing.","VHL testen, weil VEGF":"Test VHL because VEGF","RCC-Biologie wird ohne Evidenz in CRC übertragen.":"RCC biology is transferred to CRC without evidence.","KRAS-mutiert = kein Bevacizumab":"KRAS-mutated = no bevacizumab","RAS und VEGF sind unterschiedliche therapeutische Achsen.":"RAS and VEGF are different therapeutic axes.","Mehr Test = mehr Präzision":"More testing = more precision","Test ohne Entscheidungsnutzen ist Low-value.":"A test without decision value is low-value.","Der beste Test ist hier: keiner":"The best test here is: none","Die vorhandenen Daten reichen für die Anti-VEGF-Rationale. Ein VHL/HIF-Panel würde nichts klinisch Validiertes hinzufügen. Der Twist ist, dass fachliche Tiefe nicht durch zusätzliche Diagnostik, sondern durch korrektes Weglassen entsteht.":"The available data are sufficient for the anti-VEGF rationale. A VHL/HIF panel would add nothing clinically validated. The twist is that expertise is shown not by additional diagnostics, but by correctly omitting them.","Er trainiert Testökonomie und verhindert pathway-driven Overdiagnostics.":"It trains test economy and prevents pathway-driven overdiagnostics.","Mechanismus ohne Pseudobiomarker":"Mechanism without pseudo-biomarker","KRAS-mutiertes mCRC; Anti-VEGF biologisch plausibel, kein VHL/VEGF Companion Diagnostic erforderlich.":"KRAS-mutated mCRC; anti-VEGF biologically plausible, no VHL/VEGF companion diagnostic required.","Saubere Evidenzhierarchie.":"Clean evidence hierarchy.","VEGF erklärt, RAS unscharf":"VEGF explained, RAS unclear","Angiogenese korrekt, aber RAS-/anti-EGFR-Kontext wird vermischt.":"Angiogenesis is correct, but the RAS/anti-EGFR context is conflated.","Therapieachsen trennen.":"Separate therapeutic axes.","VHL-Pflicht erfunden":"VHL requirement invented","Bevacizumab wird von einem RCC-artigen VHL/HIF-Panel abhängig gemacht.":"Bevacizumab is made dependent on an RCC-like VHL/HIF panel.","Entitäts-Copyover.":"Entity copyover.","Weitere CRC-Targets offen":"Additional CRC targets still open","Entitätsspezifische Standarddiagnostik ergänzen.":"Add entity-specific standard diagnostics.","Zusatztests beantworten echte Fragen.":"Additional tests answer genuine questions.","Nur Anti-VEGF-Mechanismus gefragt":"Only the anti-VEGF mechanism is being asked","Interpretation statt Wet-lab-Overtesting.":"Interpretation instead of wet-lab overtesting.","Material und TAT werden geschont.":"Material and TAT are preserved.","Bevacizumab neutralisiert VEGF-A und adressiert Tumorangiogenese.":"Bevacizumab neutralizes VEGF-A and targets tumor angiogenesis.","Für mCRC ist kein positiver VHL/HIF-/Tumor-VEGF-Test als Routinevoraussetzung etabliert.":"No positive VHL/HIF/tumor-VEGF test is established as a routine prerequisite in mCRC.","RAS-Status entscheidet eine andere Therapieachse.":"RAS status determines a different therapeutic axis.","Mechanistische Plausibilität ist nicht gleich Companion Diagnostic.":"Mechanistic plausibility is not the same as a companion diagnostic.","Gute Präzisionsdiagnostik beinhaltet bewusstes Weglassen unnötiger Tests.":"Good precision diagnostics includes deliberately omitting unnecessary tests.","Die KRAS-Mutation erklärt den fehlenden anti-EGFR-Kontext, nicht eine Anti-VEGF-Kontraindikation. Bevacizumab wirkt über VEGF-A; ein positiver VHL/HIF-/VEGF-Tumortest ist dafür im mCRC nicht erforderlich. VHL/HIF-Testung wäre Low-value.":"The KRAS mutation explains the lack of an anti-EGFR context, not an anti-VEGF contraindication. Bevacizumab acts via VEGF-A; a positive VHL/HIF/VEGF tumor test is not required in mCRC. VHL/HIF testing would be low-value.","Mechanismus vs Biomarker":"Mechanism vs biomarker","RAS-Achse getrennt":"RAS axis separated","kein VHL-Copyover":"No VHL copyover","Testökonomie":"Testing economy","Warum führen Signalwegdiagramme manchmal zu Overdiagnostics?":"Why do pathway diagrams sometimes lead to overdiagnostics?","Was unterscheidet einen Wirkmechanismus von einem Companion Diagnostic?":"What distinguishes a mechanism of action from a companion diagnostic?","Wann ist ein nicht bestellter Test die beste Entscheidung?":"When is not ordering a test the best decision?","VHL/HIF wird bewusst nicht getestet":"VHL/HIF is deliberately not tested","Mechanismus ≠ Companion Diagnostic":"Mechanism ≠ companion diagnostic","CRC-Profil → Therapieachse → VEGF-Rationale → kein Zusatztest":"CRC profile → therapeutic axis → VEGF rationale → no additional test","Klarzelliges RCC: VHL/HIF/VEGF erklärt die Biologie – wählt aber nicht allein die Therapie":"Clear-cell RCC: VHL/HIF/VEGF explains the biology—but does not select therapy by itself","Klarzelliges RCC: VHL/HIF/VEGF-Ach…":"Clear-cell RCC: VHL/HIF/VEGF axis…","Uroonkologie / Molekulares Tumorboard":"Urologic oncology / Molecular Tumor Board","59-jähriger Patient mit metastasiertem klarzelligem Nierenzellkarzinom. Ein Tumorpanel weist eine inaktivierende VHL-Alteration nach.":"59-year-old man with metastatic clear-cell renal cell carcinoma. A tumor panel detects an inactivating VHL alteration.","Wie erklärt die VHL/HIF/VEGF-Achse die ausgeprägte Vaskularisierung und die Plausibilität von VEGFR-TKI/IO-Kombinationen – und wie weit darf man den VHL-Befund therapeutisch individualisieren?":"How does the VHL/HIF/VEGF axis explain the marked vascularization and plausibility of VEGFR-TKI/IO combinations—and how far may the VHL finding be used to individualize therapy?","Erstlinienstrategie soll im interdisziplinären Board festgelegt werden.":"First-line strategy is to be determined by the interdisciplinary board.","Krankheit":"Disease","Nephrektomie vor 18 Monaten; nun pulmonale und ossäre Metastasen.":"Nephrectomy 18 months ago; now pulmonary and bone metastases.","Klarzelliges RCC, typische feine Gefäßarchitektur.":"Clear-cell RCC, typical delicate vascular architecture.","VHL Loss-of-function im Tumor.":"VHL loss-of-function in the tumor.","Ein häufiger biologischer Driver wird als spezifischer prädiktiver Marker für genau eine zugelassene Kombination missverstanden.":"A common biological driver is misinterpreted as a specific predictive marker for exactly one approved combination.","Alveolär/nestartig aufgebauter klarzelliger Tumor mit dichtem kapillärem Netzwerk.":"Alveolar/nested clear-cell tumor with a dense capillary network.","Biologie":"Biology","VHL-Verlust stabilisiert HIF-Signale und fördert u. a. VEGF-abhängige Angiogenese.":"VHL loss stabilizes HIF signaling and promotes, among other effects, VEGF-dependent angiogenesis.","Moderne Erstlinienoptionen kombinieren häufig Immuncheckpoint- und VEGFR-gerichtete Strategien.":"Modern first-line options often combine immune-checkpoint and VEGFR-directed strategies.","Biologische Plausibilität versus echte prädiktive Individualisierung.":"Biological plausibility versus genuine predictive individualization.","Nephrektomieblock und aktuelle Metastasenbiopsie verfügbar.":"Nephrectomy block and current metastasis biopsy available.","Testnutzen":"Testing utility","VHL/HIF-Kontext kann die Biologie illustrieren, ist aber für Standard-IO/TKI-Auswahl nicht zwingend als positiver Companion Diagnostic erforderlich.":"VHL/HIF context can illustrate the biology, but a positive companion diagnostic is not mandatory for standard IO/TKI selection.","Mehr Molekulardaten dürfen keine Scheingenauigkeit bei der Auswahl zwischen mehreren klinisch etablierten Regimen erzeugen.":"More molecular data must not create false precision when choosing among several clinically established regimens.","VHL/HIF/VEGF-Biologie integrieren":"Integrate VHL/HIF/VEGF biology","VHL/HIF":"VHL/HIF","Inaktivierende VHL-Alteration; Befund passt zur kanonischen ccRCC-Biologie mit HIF-Stabilisierung und proangiogenem Programm.":"Inactivating VHL alteration; the finding fits canonical ccRCC biology with HIF stabilization and a proangiogenic program.","Die ausgeprägte Angiogenese erklärt die Wirksamkeitslogik VEGFR-gerichteter TKIs; die Kombination mit IO adressiert gleichzeitig Tumorimmunität und Gefäß-/TME-Biologie.":"The marked angiogenesis explains the mechanistic rationale for VEGFR-directed TKIs; combination with IO simultaneously addresses tumor immunity and vascular/TME biology.","Klarzelliges RCC mit prominentem kapillärem Netzwerk.":"Clear-cell RCC with a prominent capillary network.","Kernbotschaft":"Key message","Biologischer Driver ≠ alleiniger prädiktiver Regimenselektor.":"Biological driver ≠ sole predictive regimen selector.","Der VHL-Verlust liefert eine sehr plausible biologische Erklärung für HIF-Aktivierung und VEGF-dominierte Angiogenese des klarzelligen RCC. Daraus folgt die biologische Plausibilität VEGFR-gerichteter Therapie und kombinierter IO/VEGFR-Strategien. Der konkrete VHL-Tumorbefund ist jedoch kein alleiniger validierter Selektionsmarker, der eine bestimmte Erstlinienkombination gegenüber allen anderen festlegt.":"VHL loss provides a highly plausible biological explanation for HIF activation and VEGF-dominant angiogenesis in clear-cell RCC. This supports the biological plausibility of VEGFR-directed therapy and combined IO/VEGFR strategies. However, the specific VHL tumor finding is not a sole validated selection marker that determines one first-line combination over all others.","Teilbefund: VHL/HIF/VEGF erklärt die Erkrankungsbiologie, beantwortet aber die klinische Regimenwahl nicht ohne Gesamtpatientenkontext.":"Partial result: VHL/HIF/VEGF explains disease biology but does not answer regimen choice without the overall clinical context.","VHL-Verlust biologisch korrekt über HIF/VEGF erklären":"Explain VHL loss biologically via HIF/VEGF","Rationale von VEGFR-TKI + IO mechanistisch erläutern":"Explain the rationale for VEGFR-TKI + IO mechanistically","VHL nicht als alleinigen prädiktiven Regimenselektor verkaufen":"Do not present VHL as the sole predictive regimen selector","Risikogruppe, Komorbiditäten und klinische Faktoren in der Therapieentscheidung belassen":"Keep risk group, comorbidities, and clinical factors in the treatment decision","Falschaussage: VHL-Mutation bestimmt zwingend eine bestimmte IO/TKI-Kombination":"False statement: VHL mutation mandates a specific IO/TKI combination","Optimale Lösung: VHL/HIF/VEGF als Lehrbuchbeispiel einer biologisch sehr starken Achse nutzen, ohne daraus einen nicht validierten Präzisionsmarker für die konkrete Regimenwahl zu machen.":"Optimal solution: use VHL/HIF/VEGF as a textbook example of a biologically powerful axis without turning it into an unvalidated precision marker for selecting the specific regimen.","ccRCC":"ccRCC","VHL":"VHL","HIF":"HIF","VEGFR-TKI":"VEGFR-TKI","VHL erklärt fast alles – aber nicht die konkrete Regimenwahl":"VHL explains almost everything—but not the specific regimen choice","Uroonkologie / Molekularpathologie / MTB":"Urologic oncology / molecular pathology / MTB","VHL-Verlust über HIF-Stabilisierung und VEGF-Angiogenese erklären.":"Explain VHL loss through HIF stabilization and VEGF angiogenesis.","Die starke Vaskularisierung des ccRCC biologisch mit VEGFR-TKI verknüpfen.":"Biologically connect the strong vascularization of ccRCC with VEGFR-TKI.","Komplementäre Rationale von IO + VEGFR-TKI verstehen.":"Understand the complementary rationale of IO + VEGFR-TKI.","VHL als häufigen biologischen Driver, aber nicht als alleinigen Regimenselektor einordnen.":"Classify VHL as a common biological driver, but not as the sole regimen selector.","Klinische Faktoren neben Tumorbiologie in der Therapiewahl belassen.":"Keep clinical factors alongside tumor biology in treatment selection.","Das Panel zeigt eine klare VHL-Loss-of-function-Mutation. Der Befund ist biologisch wunderschön – so schön, dass man leicht zu viel daraus ableitet und glaubt, er müsse nun exakt eine bestimmte Kombination bestimmen.":"The panel shows a clear VHL loss-of-function mutation. The finding is biologically elegant—so elegant that it is easy to infer too much and assume it must now determine one exact combination.","59-jähriger Patient mit metastasiertem klarzelligem RCC und VHL-Loss-of-function. Ziel ist, VHL/HIF/VEGF als Lehrbuchachse zu verstehen und gleichzeitig die Grenze zur klinischen Prädiktion zu ziehen.":"59-year-old man with metastatic clear-cell RCC and VHL loss-of-function. The goal is to understand VHL/HIF/VEGF as a textbook axis while drawing the boundary to clinical prediction.","Kanonische Biologie":"Canonical biology","VHL-Verlust → HIF-Stabilisierung → proangiogenes Programm.":"VHL loss → HIF stabilization → proangiogenic program.","ccRCC ist ein Paradebeispiel für pathway-driven Tumorbiologie.":"ccRCC is a prime example of pathway-driven tumor biology.","Therapie-Rationale":"Therapeutic rationale","VEGFR-TKI adressieren die angiogene Achse; IO adressiert Tumorimmunität/TME.":"VEGFR-TKIs target the angiogenic axis; IO targets tumor immunity/TME.","Kombinationen können biologisch komplementär sein.":"Combinations can be biologically complementary.","Grenze":"Boundary","VHL ist häufig, aber kein alleiniger Selektor zwischen allen Standardregimen.":"VHL is common, but not the sole selector among all standard regimens.","Biologische Erklärung ist stärker als prädiktive Spezifität.":"The biological explanation is stronger than the predictive specificity.","typisches klarzelliges RCC mit feinem Kapillarnetz":"Typical clear-cell RCC with a delicate capillary network","Tumor-NGS":"Tumor NGS","VHL Loss-of-function":"VHL loss-of-function","metastasiert, Erstlinie offen":"Metastatic, first line open","Kein zusätzlicher Test muss eine bestimmte IO/TKI-Kombination 'freigeben'.":"No additional test has to 'authorize' a specific IO/TKI combination.","VHL-Tumorbefund ist nicht automatisch hereditär; Keimbahnfrage nur bei passendem klinischem Kontext.":"A tumor VHL finding is not automatically hereditary; a germline question arises only with an appropriate clinical context.","Klinische Risikogruppe, Komorbiditäten und Nebenwirkungsprofile bleiben entscheidend.":"Clinical risk group, comorbidities, and toxicity profiles remain decisive.","Welche Kette beschreibt die ccRCC-Biologie am besten?":"Which chain best describes ccRCC biology?","VHL-Verlust → HIF-Stabilisierung → VEGF/proangiogene Programme.":"VHL loss → HIF stabilization → VEGF/proangiogenic programs.","KRAS → EGFR → MSI.":"KRAS → EGFR → MSI.","BRCA → HRD → VEGF.":"BRCA → HRD → VEGF.","MMR-Verlust → VHL.":"MMR loss → VHL.","Die VHL/HIF/VEGF-Achse ist kanonisch.":"The VHL/HIF/VEGF axis is canonical.","Warum ist IO + VEGFR-TKI biologisch plausibel?":"Why is IO + VEGFR-TKI biologically plausible?","Gefäß-/TME- und Immunachsen werden komplementär adressiert.":"Vascular/TME and immune axes are addressed complementarily.","Weil nur VHL-mutierte Tumoren IO vertragen.":"Because only VHL-mutated tumors tolerate IO.","Beide Medikamente blockieren exakt dasselbe Molekül.":"Both drugs block exactly the same molecule.","Weil PD-L1 immer hoch sein muss.":"Because PD-L1 must always be high.","Die Kombination adressiert unterschiedliche, interagierende Ebenen.":"The combination targets different, interacting layers.","Was darf aus VHL Loss-of-function NICHT abgeleitet werden?":"What must NOT be inferred from VHL loss-of-function?","Dass genau eine bestimmte Erstlinienkombination zwingend die einzig richtige ist.":"That exactly one specific first-line combination is necessarily the only correct choice.","Dass HIF/VEGF-Biologie plausibel ist.":"That HIF/VEGF biology is plausible.","Dass angiogene Programme typisch sein können.":"That angiogenic programs may be typical.","Dass der Befund zur ccRCC-Biologie passt.":"That the finding fits ccRCC biology.","VHL ist biologisch stark, aber nicht so prädiktiv spezifisch.":"VHL is biologically strong, but not that predictively specific.","Wann wird aus Tumor-VHL eine Keimbahnfrage?":"When does a tumor VHL finding become a germline question?","Bei passendem Alter, multifokaler/bilateraler Erkrankung oder VHL-Syndrom-typischem klinischem Kontext – nicht automatisch bei jedem somatischen Tumorbefund.":"With an appropriate age, multifocal/bilateral disease, or a clinical context typical of VHL syndrome—not automatically for every somatic tumor finding.","Immer.":"Always.","Nur wenn TKI versagt.":"Only if TKI fails.","Tumor- und Keimbahnebene müssen getrennt werden.":"Tumor and germline layers must be separated.","Erklären Sie im MTB VHL/HIF/VEGF und die Kombination von antiangiogener und immunologischer Therapie, ohne den VHL-Befund zu einem nicht validierten Ein-Patient-ein-Regime-Marker zu machen.":"Explain VHL/HIF/VEGF and the combination of antiangiogenic and immune therapy in the MTB without turning the VHL finding into an unvalidated one-patient-one-regimen marker.","VHL-Verlust biologisch erklären.":"Explain VHL loss biologically.","HIF/VEGF-Angiogenese ableiten.":"Derive HIF/VEGF angiogenesis.","VEGFR-TKI-Rationale erläutern.":"Explain the VEGFR-TKI rationale.","IO-Komponente als komplementäre Immun-/TME-Achse erklären.":"Explain the IO component as a complementary immune/TME axis.","VHL nicht als alleinigen Regimenselektor überinterpretieren.":"Do not overinterpret VHL as the sole regimen selector.","Keimbahnfrage nur bei klinischem Anlass öffnen.":"Open the germline question only with a clinical indication.","Auf VHL-Testung verzichten, wenn Histologie und klinische Therapiefrage bereits klar sind; der Fall nutzt sie als didaktischen Biologieanker.":"Omit VHL testing when histology and the clinical treatment question are already clear; this case uses it as a didactic biology anchor.","Breiteres Panel nur bei zusätzlicher Target-/Studienfrage.":"Use a broader panel only for an additional target/study question.","VHL = bestimmtes Regime":"VHL = specific regimen","Biologischer Driver besitzt nicht diese prädiktive Spezifität.":"The biological driver does not have that predictive specificity.","Tumor-VHL = VHL-Syndrom":"Tumor VHL = VHL syndrome","Somatisch und Keimbahn werden verwechselt.":"Somatic and germline findings are confused.","VEGF-TKI und IO tun dasselbe":"VEGF-TKI and IO do the same thing","Komplementäre Mechanismen werden verkannt.":"Complementary mechanisms are overlooked.","Der stärkste biologische Befund ist nicht der stärkste Selektionsmarker":"The strongest biological finding is not the strongest selection marker","VHL Loss-of-function passt perfekt zum Tumor und erklärt die Angiogenese. Trotzdem wählt er nicht allein zwischen den klinisch etablierten Erstlinienoptionen. Der Fall kippt von 'Pathway gefunden' zu 'Evidenzgrad verstanden'.":"VHL loss-of-function fits the tumor perfectly and explains the angiogenesis. Yet it does not by itself choose among clinically established first-line options. The case shifts from 'pathway found' to 'evidence level understood'.","Präzisionsonkologie braucht Grenzen selbst bei sehr überzeugender Biologie.":"Precision oncology needs boundaries even with highly convincing biology.","Biologie stark, Prädiktion begrenzt":"Biology strong, prediction limited","VHL/HIF/VEGF korrekt erklärt; IO/TKI plausibel; konkrete Regimenwahl klinisch, nicht allein VHL-basiert.":"VHL/HIF/VEGF explained correctly; IO/TKI plausible; specific regimen choice is clinical, not based on VHL alone.","Sehr gute Hierarchie.":"Very good hierarchy.","Achse verstanden, Regime überpräzisiert":"Axis understood, regimen over-precisified","VHL korrekt, aber eine Kombination wird molekular zwingend gemacht.":"VHL is correct, but one combination is made molecularly mandatory.","Biologie überinterpretiert.":"Biology overinterpreted.","VHL ignoriert oder germline gesetzt":"VHL ignored or assigned to germline","Entweder zentrale Biologie verpasst oder somatischen Befund automatisch hereditär erklärt.":"Either the central biology is missed or the somatic finding is automatically declared hereditary.","Integration misslungen.":"Integration failed.","VHL-Syndrom-verdächtige Klinik":"Clinical suspicion of VHL syndrome","Humangenetische Abklärung separat initiieren.":"Initiate separate genetic evaluation.","Hereditäre Ebene korrekt adressiert.":"Hereditary layer correctly addressed.","Standard metastasiertes ccRCC":"Standard metastatic ccRCC","Regimenwahl anhand aktueller klinischer Kriterien/Guidelines.":"Regimen selection according to current clinical criteria/guidelines.","Molekularbiologie informiert, ersetzt aber nicht die klinische Auswahl.":"Molecular biology informs, but does not replace clinical selection.","VHL/HIF/VEGF ist eine kanonische ccRCC-Achse.":"VHL/HIF/VEGF is a canonical ccRCC axis.","VEGFR-TKI haben eine starke biologische Rationale im hochangiogenen ccRCC.":"VEGFR-TKIs have a strong biological rationale in highly angiogenic ccRCC.","IO/VEGFR-Kombinationen adressieren komplementäre Ebenen.":"IO/VEGFR combinations target complementary layers.","VHL ist kein alleiniger validierter Selektor für ein bestimmtes Standardregime.":"VHL is not a sole validated selector for a specific standard regimen.","Somatischer VHL-Befund ist nicht automatisch VHL-Syndrom.":"A somatic VHL finding is not automatically VHL syndrome.","VHL Loss-of-function erklärt HIF-Stabilisierung und VEGF-dominierte Angiogenese des ccRCC. Diese Biologie macht VEGFR-gerichtete und kombinierte IO/VEGFR-Strategien plausibel, bestimmt aber nicht allein das konkrete Regime. Klinischer Gesamtkontext bleibt entscheidend.":"VHL loss-of-function explains HIF stabilization and VEGF-dominant angiogenesis in ccRCC. This biology makes VEGFR-directed and combined IO/VEGFR strategies plausible, but does not by itself determine the specific regimen. The overall clinical context remains decisive.","VHL/HIF/VEGF":"VHL/HIF/VEGF","Kombinationsrationale":"Combination rationale","prädiktive Grenze":"Predictive boundary","somatisch vs germline":"Somatic vs germline","Warum sind manche Driver diagnostisch stark, aber prädiktiv schwach?":"Why are some drivers diagnostically strong but predictively weak?","Welche TME-Effekte können VEGF-Inhibition immunologisch haben?":"What immunological TME effects can VEGF inhibition have?","Wann wird eine Tumor-VHL-Variante humangenetisch relevant?":"When does a tumor VHL variant become relevant for clinical genetics?","VHL erklärt Biologie, aber nicht allein das Regime":"VHL explains biology, but not the regimen by itself","Pathway-Stärke ≠ Selektionsspezifität":"Pathway strength ≠ selection specificity","VHL → HIF/VEGF → TKI/IO-Rationale → klinische Regimenwahl":"VHL → HIF/VEGF → TKI/IO rationale → clinical regimen choice","Rezidiv-Glioblastom unter Bevacizumab: Wenn das MRT besser aussieht als der Tumor":"Recurrent glioblastoma on bevacizumab: when the MRI looks better than the tumor","Glioblastom mit Gefäßproliferation…":"Glioblastoma with vascular proliferation…","Neuroonkologie / Neuro-Radiologie / MTB":"Neuro-oncology / Neuro-radiology / MTB","62-jähriger Patient mit rezidiviertem IDH-Wildtyp-Glioblastom, ausgeprägtem perifokalem Ödem und steroidabhängigen neurologischen Symptomen. Bevacizumab wird zur Krankheits- und Symptomkontrolle diskutiert.":"62-year-old man with recurrent IDH-wild-type glioblastoma, marked perifocal edema, and steroid-dependent neurological symptoms. Bevacizumab is being discussed for disease and symptom control.","Was kann Anti-VEGF kurzfristig bewirken – und warum darf eine dramatische Abnahme der Kontrastmittelaufnahme nicht automatisch als proportionale Tumorzellreduktion gelesen werden?":"What can anti-VEGF achieve in the short term—and why must a dramatic decrease in contrast enhancement not automatically be read as a proportional reduction in tumor cells?","Hoher Symptomdruck durch Ödem.":"High symptom burden due to edema.","Operation, Radiochemotherapie und Temozolomid; jetzt erstes relevantes Rezidiv.":"Surgery, radiochemotherapy, and temozolomide; now first clinically relevant recurrence.","Hemiparese und Kopfschmerzen, Dexamethasonbedarf steigend.":"Hemiparesis and headaches, increasing dexamethasone requirement.","MRT":"MRI","Stark kontrastmittelaufnehmendes Rezidiv mit ausgeprägtem vasogenem Ödem.":"Strongly contrast-enhancing recurrence with marked vasogenic edema.","Radiologische Kontrastmittelreduktion nach Anti-VEGF wird mit echter Zytoreduktion gleichgesetzt.":"Radiologic reduction in contrast enhancement after anti-VEGF is equated with true cytoreduction.","Glioblastomtypische Nekrosen und mikrovaskuläre Proliferation.":"Glioblastoma-typical necrosis and microvascular proliferation.","Hypoxie und proangiogene Signale prägen den Tumor.":"Hypoxia and proangiogenic signals shape the tumor.","Anti-VEGF-Effekt":"Anti-VEGF effect","Gefäßpermeabilität und Ödem können rasch abnehmen.":"Vascular permeability and edema can decrease rapidly.","Wie wird die Bildgebung nach Therapiebeginn korrekt interpretiert?":"How should imaging be interpreted correctly after treatment begins?","Archiviertes Resektat ausreichend; keine neue Biopsie allein zur 'VEGF-Testung' erforderlich.":"Archived resection specimen adequate; no new biopsy required solely for 'VEGF testing'.","Testfalle":"Testing trap","Ein RCC-spezifischer VHL/HIF-Test hat hier keinen sinnvollen Selektionsnutzen.":"An RCC-specific VHL/HIF test has no meaningful selection utility here.","Radiologie":"Radiology","Kontrastmittelaufnahme ist stark von Blut-Hirn-Schranken-Permeabilität abhängig.":"Contrast enhancement strongly depends on blood-brain barrier permeability.","Symptomverbesserung kann real sein, auch wenn der antitumorale Effekt begrenzt bleibt.":"Symptom improvement can be real even if the antitumor effect remains limited.","Anti-VEGF-/Angiogenese-Kontext":"Anti-VEGF/angiogenesis context","GBM zeigt ausgeprägte Gefäßproliferation; Anti-VEGF kann Gefäßpermeabilität und vasogenes Ödem rasch reduzieren.":"GBM shows marked vascular proliferation; anti-VEGF can rapidly reduce vascular permeability and vasogenic edema.","VHL/HIF-Panel":"VHL/HIF panel","RCC-spezifische VHL/HIF-Testung liefert für diesen GBM-Fall keinen validierten Therapie-Selektionsnutzen und wäre ein entitätsfremder Low-value-Test.":"RCC-specific VHL/HIF testing provides no validated therapy-selection benefit in this GBM case and would be an entity-inappropriate low-value test.","Zusätzliche genomische Information ändert die zentrale Anti-VEGF-/Imaging-Lernfrage nicht.":"Additional genomic information does not change the central anti-VEGF/imaging learning question.","MRT vor Therapie":"MRI before therapy","Starke Kontrastmittelaufnahme und ausgeprägtes vasogenes Ödem.":"Marked contrast enhancement and pronounced vasogenic edema.","Steroidabhängige fokal-neurologische Symptome.":"Steroid-dependent focal neurological symptoms.","Anti-VEGF kann beim rezidivierten Glioblastom rasch Gefäßpermeabilität und Ödem reduzieren und damit Symptome sowie Kontrastmittelaufnahme deutlich verbessern. Diese radiologische 'Pseudoresponse' darf jedoch nicht mit einer proportionalen Eliminierung infiltrierender Tumorzellen gleichgesetzt werden. Verlaufskontrolle muss deshalb neben Kontrastmittelaufnahme auch FLAIR/non-enhancing disease, Klinik und Steroidbedarf integrieren.":"Anti-VEGF can rapidly reduce vascular permeability and edema in recurrent glioblastoma, markedly improving symptoms and contrast enhancement. However, this radiologic 'pseudoresponse' must not be equated with proportional elimination of infiltrating tumor cells. Follow-up must therefore integrate enhancement, FLAIR/non-enhancing disease, clinical status, and steroid requirement.","Teilbefund: Die Gefäßreaktion kann eindrucksvoll sein, sagt aber allein wenig über die gesamte infiltrative Tumorlast aus.":"Partial result: the vascular response can be impressive, but alone says little about the total infiltrative tumor burden.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem erklären":"Explain the anti-VEGF effect on vascular permeability/edema","Pseudoresponse von echter proportionaler Zytoreduktion trennen":"Separate pseudoresponse from true proportional cytoreduction","FLAIR/non-enhancing disease und Klinik mitbewerten":"Assess FLAIR/non-enhancing disease and clinical status as well","RCC-VHL/HIF-Testung nicht importieren":"Do not import RCC VHL/HIF testing","Falschaussage: 80 % weniger Enhancement = 80 % weniger Tumorzellen":"False statement: 80% less enhancement = 80% fewer tumor cells","Optimale Lösung: Bevacizumab kann klinisch sehr wertvolle Ödem-/Permeabilitätseffekte erzeugen; gerade deshalb muss die beeindruckende MRT-Reaktion als mögliche Pseudoresponse erkannt und multimodal beurteilt werden.":"Optimal solution: bevacizumab can produce clinically valuable effects on edema/permeability; precisely for that reason, the impressive MRI response must be recognized as possible pseudoresponse and assessed multimodally.","Glioblastom":"Glioblastoma","Pseudoresponse":"Pseudoresponse","Ödem":"Edema","Das MRT schrumpft schneller als der Tumor":"The MRI shrinks faster than the tumor","Neuroonkologie / Neuroradiologie / MTB":"Neuro-oncology / Neuroradiology / MTB","VEGF-bedingte Gefäßpermeabilität und Ödem beim GBM erklären.":"Explain VEGF-related vascular permeability and edema in GBM.","Anti-VEGF-bedingte Pseudoresponse erkennen.":"Recognize anti-VEGF-induced pseudoresponse.","Kontrastmittelreduktion nicht direkt in Tumorzellreduktion übersetzen.":"Do not directly translate reduced enhancement into fewer tumor cells.","FLAIR/non-enhancing disease, Klinik und Steroidbedarf in die Verlaufskontrolle integrieren.":"Integrate FLAIR/non-enhancing disease, clinical status, and steroid requirement into follow-up.","Entitätsfremde VHL/HIF-Testung vermeiden.":"Avoid entity-inappropriate VHL/HIF testing.","Zwei Wochen nach Bevacizumab ist die Kontrastmittelaufnahme dramatisch kleiner, der Patient braucht weniger Steroid und fühlt sich besser. Auf den ersten Blick ein spektakuläres Tumoransprechen – bis man versteht, was Anti-VEGF mit der Blut-Hirn-Schranke macht.":"Two weeks after bevacizumab, contrast enhancement is dramatically smaller, the patient needs less steroid, and feels better. At first glance, a spectacular tumor response—until one understands what anti-VEGF does to the blood-brain barrier.","62-jähriger Patient mit symptomatischem Rezidiv eines IDH-Wildtyp-Glioblastoms. Bevacizumab wird wegen Ödem und Progress eingesetzt. Der Fall lehrt, echte klinische Verbesserung und radiologische Pseudoresponse gleichzeitig richtig zu würdigen.":"62-year-old man with symptomatic recurrence of an IDH-wild-type glioblastoma. Bevacizumab is used for edema and progression. The case teaches how to correctly value both true clinical improvement and radiologic pseudoresponse.","Gefäßpermeabilität":"Vascular permeability","GBM-Gefäße sind abnormal und leaky.":"GBM vessels are abnormal and leaky.","Enhancement ist nicht nur Tumormasse, sondern auch Blut-Hirn-Schranken-Phänomen.":"Enhancement reflects not only tumor mass, but also a blood-brain barrier phenomenon.","Anti-VEGF kann wirklich helfen":"Anti-VEGF can truly help","Ödem und Steroidbedarf sinken.":"Edema and steroid requirement decrease.","Pseudoresponse bedeutet nicht 'kein Nutzen'.":"Pseudoresponse does not mean 'no benefit'.","Aber Imaging kann täuschen":"But imaging can mislead","Non-enhancing/infiltrative disease kann fortbestehen.":"Non-enhancing/infiltrative disease can persist.","Response muss multimodal bewertet werden.":"Response must be assessed multimodally.","Vor Therapie":"Before therapy","starkes Enhancement + massives vasogenes Ödem":"Marked enhancement + massive vasogenic edema","Hemiparese, Kopfschmerz, Steroidbedarf":"Hemiparesis, headache, steroid requirement","Nekrose + mikrovaskuläre Proliferation":"Necrosis + microvascular proliferation","Keine neue Biopsie nur zur VEGF-Testung nötig.":"No new biopsy required solely for VEGF testing.","VHL/HIF-Panel ist hier ein bewusster RCC-Copyover und nicht erforderlich.":"The VHL/HIF panel is a deliberate RCC copyover here and is not required.","Radiologische Verlaufskriterien müssen Anti-VEGF-Effekte berücksichtigen.":"Radiologic response criteria must account for anti-VEGF effects.","Was erklärt die schnelle Abnahme des Enhancements am besten?":"What best explains the rapid decrease in enhancement?","Reduzierte Gefäßpermeabilität/Normalisierung und weniger Ödem können einen großen Anteil beitragen.":"Reduced vascular permeability/normalization and less edema can contribute substantially.","Es beweist proportional dieselbe Abnahme der Tumorzellzahl.":"It proves a proportional decrease in tumor-cell number.","IDH-Mutation entsteht unter Therapie.":"An IDH mutation develops during therapy.","Es ist immer Strahlennekrose.":"It is always radiation necrosis.","Anti-VEGF beeinflusst die Blut-Hirn-Schranke stark.":"Anti-VEGF strongly affects the blood-brain barrier.","Was bedeutet 'Pseudoresponse'?":"What does 'pseudoresponse' mean?","Radiologisch eindrucksvolle Abnahme des Enhancements kann den antitumoralen Zell-Effekt überschätzen.":"A radiologically impressive decrease in enhancement can overestimate the antitumor cellular effect.","Jede klinische Verbesserung ist eingebildet.":"Every clinical improvement is imagined.","Es bedeutet zwingend Progress.":"It necessarily means progression.","MRT ist technisch unbrauchbar.":"MRI is technically unusable.","Der Nutzen kann real sein, aber Enhancement überschätzt den Zell-Effekt.":"The benefit may be real, but enhancement overestimates the cellular effect.","Was muss zusätzlich betrachtet werden?":"What else must be considered?","FLAIR/non-enhancing disease, Klinik, Steroidbedarf und serieller Verlauf.":"FLAIR/non-enhancing disease, clinical status, steroid requirement, and serial course.","Nur kontrastmittelaufnehmendes Volumen.":"Only contrast-enhancing volume.","VHL-Mutationsstatus.":"VHL mutation status.","PD-L1-IHC.":"PD-L1 IHC.","Anti-VEGF erfordert breitere Responsebewertung.":"Anti-VEGF requires broader response assessment.","Warum ist VHL/HIF-Panel hier falsch?":"Why is the VHL/HIF panel wrong here?","Es importiert einen RCC-spezifischen Test ohne validierten Selektionsnutzen in den GBM-Fall.":"It imports an RCC-specific test into the GBM case without validated selection utility.","GBM hat keine DNA.":"GBM has no DNA.","VEGF ist im GBM irrelevant.":"VEGF is irrelevant in GBM.","Nur wegen TAT.":"Only because of TAT.","Angiogenese ist gemeinsam, Testalgorithmen sind entitätsspezifisch.":"Angiogenesis is shared, but testing algorithms are entity-specific.","Bewerten Sie die frühe MRT- und klinische Veränderung nach Bevacizumab und formulieren Sie, warum eine starke Kontrastmittelreduktion nicht automatisch eine gleich starke Zytoreduktion bedeutet.":"Assess the early MRI and clinical change after bevacizumab and explain why a major reduction in contrast enhancement does not automatically mean equally strong cytoreduction.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem benennen.":"Identify the anti-VEGF effect on vascular permeability/edema.","Klinische Symptomverbesserung anerkennen.":"Acknowledge clinical symptom improvement.","Pseudoresponse erklären.":"Explain pseudoresponse.","FLAIR/non-enhancing disease und seriellen Verlauf integrieren.":"Integrate FLAIR/non-enhancing disease and serial course.","VHL/HIF-Testung vermeiden.":"Avoid VHL/HIF testing.","Wenn Bildgebung und Klinik diskordant bleiben, neuroradiologische Spezialverfahren/Verlauf nutzen.":"If imaging and clinical findings remain discordant, use specialized neuroradiologic techniques/follow-up.","Bevacizumab primär symptomatisch/krankheitskontrollierend diskutieren, ohne radiologische Überversprechen.":"Discuss bevacizumab primarily for symptom/disease control without overpromising radiologic response.","Enhancement = Tumorzellzahl":"Enhancement = tumor-cell number","BBB-Permeabilität beeinflusst Enhancement stark.":"BBB permeability strongly influences enhancement.","Pseudoresponse = kein Nutzen":"Pseudoresponse = no benefit","Ödem- und Steroidreduktion können klinisch sehr relevant sein.":"Reduction in edema and steroid requirement can be clinically very relevant.","VHL testen":"Test VHL","RCC-Copyover ohne Selektionsnutzen.":"RCC copyover without selection utility.","80 % weniger Enhancement, aber nicht 80 % weniger Tumor":"80% less enhancement, but not 80% less tumor","Der Patient verbessert sich und das MRT sieht spektakulär aus. FLAIR zeigt jedoch weiter infiltrative Erkrankung. Der Twist ist doppelt: Der Effekt ist klinisch real und radiologisch zugleich potenziell irreführend.":"The patient improves and the MRI looks spectacular. Yet FLAIR still shows infiltrative disease. The twist is twofold: the effect is clinically real and radiologically potentially misleading at the same time.","Er verhindert sowohl Über- als auch Unterbewertung antiangiogener Therapie.":"It prevents both over- and underestimation of antiangiogenic therapy.","Pseudoresponse richtig gelesen":"Pseudoresponse interpreted correctly","Ödem/Enhancement deutlich geringer, Klinik besser; infiltrative FLAIR-Komponente bleibt → Response nicht als proportionale Zytoreduktion überinterpretieren.":"Edema/enhancement clearly reduced, clinical status improved; infiltrative FLAIR component remains → do not overinterpret response as proportional cytoreduction.","Neuroonkologische Response korrekt.":"Neuro-oncologic response interpreted correctly.","Pseudoresponse erkannt, Nutzen abgewertet":"Pseudoresponse recognized, benefit discounted","Imaging-Falle erkannt, aber reale Symptom-/Ödemkontrolle fälschlich als bedeutungslos bezeichnet.":"The imaging trap is recognized, but real symptom/edema control is incorrectly called meaningless.","Zu einseitig.":"Too one-sided.","MRT = Zellzählung":"MRI = cell count","Kontrastmittelvolumen wird direkt als Tumormasse interpretiert.":"Contrast-enhancing volume is directly interpreted as tumor mass.","Zentralen Anti-VEGF-Effekt verpasst.":"Central anti-VEGF effect missed.","Enhancement sinkt, FLAIR stabil/steigend":"Enhancement decreases, FLAIR stable/increasing","Pseudoresponse/discordant response erwägen und seriell beurteilen.":"Consider pseudoresponse/discordant response and assess serially.","Keine falsche Vollremission.":"No false complete remission.","Steroidbedarf sinkt":"Steroid requirement decreases","Als echten klinischen Benefit dokumentieren.":"Document as a real clinical benefit.","Symptomkontrolle wird nicht kleingeredet.":"Symptom control is not minimized.","VEGF-Inhibition kann Gefäßpermeabilität und Ödem rasch reduzieren.":"VEGF inhibition can rapidly reduce vascular permeability and edema.","Kontrastmittelaufnahme ist beim GBM kein reiner Tumorzellmarker.":"Contrast enhancement in GBM is not a pure tumor-cell marker.","Pseudoresponse kann gleichzeitig mit echter klinischer Besserung bestehen.":"Pseudoresponse can coexist with genuine clinical improvement.","FLAIR/non-enhancing disease und Klinik gehören in die Verlaufskontrolle.":"FLAIR/non-enhancing disease and clinical status belong in follow-up assessment.","Angiogenese-Biologie rechtfertigt nicht automatisch VHL/HIF-Tumortestung.":"Angiogenesis biology does not automatically justify VHL/HIF tumor testing.","Nach Bevacizumab sinken Enhancement, Ödem und Steroidbedarf deutlich. Das ist klinisch relevant, kann aber den zytoreduktiven Effekt überschätzen. FLAIR/non-enhancing disease und Verlauf müssen integriert werden; ein RCC-artiges VHL/HIF-Panel hat keinen Selektionsnutzen.":"After bevacizumab, enhancement, edema, and steroid requirement decrease markedly. This is clinically relevant but may overestimate the cytoreductive effect. FLAIR/non-enhancing disease and course must be integrated; an RCC-like VHL/HIF panel has no selection utility.","Ödem vs Tumor":"Edema vs tumor","multimodale Bildgebung":"Multimodal imaging","kein RCC-Copyover":"No RCC copyover","Wie unterscheiden sich Pseudoprogression und Pseudoresponse?":"How do pseudoprogression and pseudoresponse differ?","Welche klinischen Parameter helfen bei anti-VEGF?":"Which clinical parameters help during anti-VEGF therapy?","Warum ist Enhancement biologisch kein einfacher Tumormasse-Readout?":"Why is enhancement biologically not a simple readout of tumor mass?","dramatische MRT-Besserung trotz persistierender FLAIR-Krankheit":"Dramatic MRI improvement despite persistent FLAIR disease","Anti-VEGF verändert Bildgebung und Klinik unterschiedlich":"Anti-VEGF changes imaging and clinical status differently","VEGF/Ödem → Bevacizumab → Enhancement fällt → multimodale Response":"VEGF/edema → bevacizumab → enhancement falls → multimodal response assessment","PD-L1 und TMB sehen gut aus – aber die T-Zellen bleiben im Stroma":"PD-L1 and TMB look favorable—but T cells remain in the stroma","Stromareicher Tumor mit immune-exc…":"Stroma-rich tumor with immune-exc…","68-jähriger Patient mit metastasiertem Urothelkarzinom. Vor Checkpoint-Therapie lagen PD-L1-Expression und eine relativ hohe Mutationslast vor; klinisch kam es dennoch zu frühem Progress.":"68-year-old man with metastatic urothelial carcinoma. Before checkpoint therapy, PD-L1 expression and relatively high mutation burden were present; nevertheless, early clinical progression occurred.","Wie kann ein scheinbar immunogener Tumor trotzdem primär resistent sein – und was lehrt die räumliche Verteilung der Immunzellen?":"How can an apparently immunogenic tumor still be primarily resistant—and what does the spatial distribution of immune cells teach us?","Retrospektive Einordnung und Studienplanung für die nächste Linie.":"Retrospective interpretation and study planning for the next line.","PD-L1 hoch; TMB erhöht; kein MSI-H-Kontext.":"PD-L1 high; TMB elevated; no MSI-H context.","Checkpoint-Inhibition mit frühem radiologischem Progress.":"Checkpoint inhibition with early radiologic progression.","Biopsie":"Biopsy","Progressionsbiopsie zeigt stark stromareichen Tumor.":"Progression biopsy shows a strongly stroma-rich tumor.","Biomarkerwerte werden ohne räumlichen Zellkontext als Garantie für Immunantwort interpretiert.":"Biomarker values are interpreted as a guarantee of immune response without spatial cellular context.","Invasive Tumornester in breiten fibrotischen Stromasepten.":"Invasive tumor nests within broad fibrotic stromal septa.","CD8":"CD8","Viele T-Zellen vorhanden, aber überwiegend im peritumoralen Stroma; Tumorzellnester selbst sind arm an CD8-Zellen.":"Many T cells are present, but predominantly in peritumoral stroma; the tumor-cell nests themselves contain few CD8 cells.","CAF-Kontext":"CAF context","FAP/αSMA-reiches aktiviertes Stroma.":"FAP/αSMA-rich activated stroma.","Immune-excluded statt wirklich inflamed/hot.":"Immune-excluded rather than truly inflamed/hot.","Progressionsbiopsie mit 45 % Tumoranteil.":"Progression biopsy with 45% tumor content.","ausreichend für fokussierte TIL-/Stroma-IHC.":"Adequate for focused TIL/stroma IHC.","Evidenzgrenze":"Evidence boundary","TME-IHC erklärt die Resistenzbiologie, ist aber kein routinemäßiger alleiniger Therapieausschluss- oder Auswahltest.":"TME IHC explains resistance biology but is not a routine stand-alone treatment exclusion or selection test.","Räumliche Biologie nicht mit einem neuen Companion Diagnostic verwechseln.":"Do not confuse spatial biology with a new companion diagnostic.","Stroma-/Immune-exclusion-Kontext":"Stroma/immune-exclusion context","PD-L1 bleibt deutlich exprimiert; der Befund allein erklärt die fehlende klinische Antwort nicht.":"PD-L1 remains clearly expressed; this finding alone does not explain the lack of clinical response.","TMB erhöht. Potenziell vorhandene Neoantigene garantieren dennoch keine effektive T-Zell-Interaktion mit den Tumorzellen.":"TMB elevated. Potential neoantigens nevertheless do not guarantee effective T-cell interaction with tumor cells.","TIL-Verteilung":"TIL distribution","CD8-positive T-Zellen sind zahlreich, bleiben jedoch überwiegend stromal/peritumoral; intratumorale Penetration ist gering.":"CD8-positive T cells are numerous but remain predominantly stromal/peritumoral; intratumoral penetration is low.","Stroma":"Stroma","Breites FAP/αSMA-positives fibroblastenreiches Stroma stützt ein immune-excluded Muster. Der Befund ist mechanistisch plausibel, aber kein allein validierter Therapie-Selektionsassay.":"Broad FAP/αSMA-positive fibroblast-rich stroma supports an immune-excluded pattern. The finding is mechanistically plausible but is not a stand-alone validated therapy-selection assay.","Klinischer Twist":"Clinical twist","Früher Progress trotz scheinbar günstiger Immunmarker.":"Early progression despite seemingly favorable immune markers.","Stark stromareicher Tumor mit räumlicher Trennung von CD8-Zellen und Tumornestern.":"Strongly stroma-rich tumor with spatial separation of CD8 cells and tumor nests.","PD-L1-Expression und erhöhte TMB können immunologische Potenziale anzeigen, garantieren aber keine effektive Antitumor-Immunität. Die Progressionsbiopsie zeigt ein klassisches immune-excluded Muster: T-Zellen sind vorhanden, werden jedoch durch das stromale Mikromilieu räumlich von Tumorzellen ferngehalten. Dieser Befund erklärt Resistenzbiologie, darf aber nicht als alleiniger validierter Companion Diagnostic für eine konkrete Folgetherapie überinterpretiert werden.":"PD-L1 expression and elevated TMB can indicate immunologic potential but do not guarantee effective antitumor immunity. The progression biopsy shows a classic immune-excluded pattern: T cells are present but are spatially kept away from tumor cells by the stromal microenvironment. This explains resistance biology but must not be overinterpreted as a stand-alone validated companion diagnostic for a specific subsequent therapy.","Teilbefund: Gute Biomarkerwerte ohne räumliche TIL-Analyse erklären die tatsächliche Immunfunktion nur unvollständig.":"Partial result: favorable biomarker values without spatial TIL analysis incompletely describe actual immune function.","TMB/PD-L1 als Potenzialmarker von funktioneller T-Zell-Tumor-Interaktion trennen":"Separate TMB/PD-L1 as potential markers from functional T-cell–tumor interaction","Immune exclusion über räumliche CD8-Verteilung erkennen":"Recognize immune exclusion through spatial CD8 distribution","CAF-/Stroma-Barriere biologisch erklären":"Explain the CAF/stromal barrier biologically","TME-IHC nicht zum nicht validierten Therapieausschlusstest machen":"Do not turn TME IHC into an unvalidated treatment-exclusion test","Falschaussage: hohe TMB + PD-L1 garantieren Checkpoint-Ansprechen":"False statement: high TMB + PD-L1 guarantee checkpoint response","Optimale Lösung: PD-L1/TMB nicht als Garantie interpretieren; die räumliche TIL-Verteilung zeigt, dass Immunzellen vorhanden, aber funktionell vom Tumor ausgeschlossen sind. Mechanistisch stark, prädiktiv aber nicht als alleiniger Routinetest validiert.":"Optimal solution: do not interpret PD-L1/TMB as a guarantee; spatial TIL distribution shows that immune cells are present but functionally excluded from the tumor. Mechanistically strong, but not validated as a stand-alone routine predictive test.","CAF":"CAF","Urothelkarzinom":"Urothelial carcinoma","Viele T-Zellen – aber auf der falschen Seite der Stromabarriere":"Many T cells—but on the wrong side of the stromal barrier","Molekularpathologie / Immunonkologie / MTB":"Molecular pathology / Immuno-oncology / MTB","PD-L1/TMB als Potenzialmarker von funktioneller Immunantwort unterscheiden.":"Distinguish PD-L1/TMB as potential markers from functional immune response.","Immune-excluded Muster anhand räumlicher TIL-Verteilung erkennen.":"Recognize an immune-excluded pattern from spatial TIL distribution.","CAF-/Stromabarriere als Resistenzmechanismus erklären.":"Explain the CAF/stromal barrier as a resistance mechanism.","TME-IHC als mechanistischen und nicht automatisch validierten Selektionsmarker einordnen.":"Classify TME IHC as mechanistic, not automatically as a validated selection marker.","Klinische Nonresponse trotz günstiger Einzelmarker biologisch plausibel erklären.":"Biologically explain clinical nonresponse despite favorable individual markers.","PD-L1 ist hoch, TMB ist erhöht – und der Tumor wächst unter Checkpoint-Inhibition trotzdem weiter. In der Progressionsbiopsie sind sogar viele CD8-T-Zellen zu sehen. Das Problem: Sie stehen fast alle draußen im Stroma.":"PD-L1 is high, TMB is elevated—and the tumor still grows under checkpoint inhibition. The progression biopsy even shows many CD8 T cells. The problem: almost all of them remain outside in the stroma.","68-jähriger Patient mit metastasiertem Urothelkarzinom und frühem Progress unter ICI trotz scheinbar günstiger PD-L1-/TMB-Konstellation. Die Progressionsbiopsie zeigt, dass nicht die Zahl allein, sondern die räumliche Position der Immunzellen entscheidend ist.":"68-year-old man with metastatic urothelial carcinoma and early progression on ICI despite seemingly favorable PD-L1/TMB findings. The progression biopsy shows that not only the number, but also the spatial position of immune cells matters.","Potenzial":"Potential","PD-L1 hoch, TMB erhöht.":"PD-L1 high, TMB elevated.","Diese Marker können Immunogenität anzeigen, garantieren aber keine effektive Antwort.":"These markers can indicate immunogenicity, but do not guarantee an effective response.","Raum":"Space","CD8-Zellen liegen vor allem stromal/peritumoral.":"CD8 cells are located mainly in stromal/peritumoral regions.","Immune exclusion ist ein räumliches Phänomen.":"Immune exclusion is a spatial phenomenon.","Barriere":"Barrier","FAP/αSMA-reiches Stroma.":"FAP/αSMA-rich stroma.","CAF/Matrix können physische und signalbiologische Barrieren bilden.":"CAF/matrix can form physical and signaling barriers.","deutlich exprimiert":"Clearly expressed","erhöht":"Elevated","früher Progress unter Checkpoint-Inhibition":"Early progression under checkpoint inhibition","Progressionsbiopsie ermöglicht räumliche TIL-/Stroma-Bewertung.":"Progression biopsy enables spatial TIL/stroma assessment.","TME-Marker sind keine validierte alleinige Folgetherapie-Selektion.":"TME markers are not validated as stand-alone selection tests for subsequent therapy.","Mechanistische Erklärung darf nicht in Pseudopräzision kippen.":"Mechanistic explanation must not turn into pseudo-precision.","Was ist die wichtigste Erklärung für PD-L1/TMB ohne Response?":"What is the most important explanation for PD-L1/TMB without response?","Marker zeigen Potenzial, aber nicht zwingend erfolgreiche T-Zell-Penetration und Funktion im Tumornest.":"Markers indicate potential, but not necessarily successful T-cell penetration and function within tumor nests.","PD-L1 und TMB müssen technisch falsch sein.":"PD-L1 and TMB must be technically wrong.","So eine Konstellation ist unmöglich.":"Such a constellation is impossible.","Hohe TMB beweist MSI-H.":"High TMB proves MSI-H.","Biomarker und Funktion sind unterschiedliche Ebenen.":"Biomarkers and function are different layers.","Welcher Befund definiert immune exclusion am besten?":"Which finding best defines immune exclusion?","Viele T-Zellen im Stroma, wenige innerhalb der Tumorzellnester.":"Many T cells in the stroma, few within the tumor-cell nests.","Gar keine Immunzellen im gesamten Präparat.":"No immune cells anywhere in the specimen.","Dichtes intraepitheliales CD8-Infiltrat.":"Dense intraepithelial CD8 infiltrate.","PD-L1 hoch.":"PD-L1 high.","Räumliche Verteilung ist zentral.":"Spatial distribution is central.","Wie darf FAP/αSMA/CD8-IHC genutzt werden?":"How may FAP/αSMA/CD8 IHC be used?","Als mechanistische Unterstützung eines stromal-excluded Musters, nicht als alleiniger zugelassener Companion Diagnostic.":"As mechanistic support for a stromal-excluded pattern, not as a stand-alone approved companion diagnostic.","Als absolute Kontraindikation gegen jede ICI.":"As an absolute contraindication to every ICI.","Als Beweis für eine Standard-CAF-Therapie.":"As proof for a standard CAF therapy.","Gar nicht interpretieren.":"Do not interpret it at all.","Mechanistisch stark, klinisch nicht allein selektiv validiert.":"Mechanistically strong, but not clinically validated as a stand-alone selector.","Was ist die beste MTB-Kommunikation?":"What is the best MTB communication?","Günstige Einzelmarker anerkennen, reale Nonresponse und spatial TME integrieren, experimentelle TME-Strategien als Studienoption kennzeichnen.":"Acknowledge favorable individual markers, integrate actual nonresponse and spatial TME, and label experimental TME strategies as study options.","PD-L1 so oft wiederholen, bis ein höherer Wert entsteht.":"Repeat PD-L1 until a higher value appears.","TMB/PD-L1 als nutzlos erklären.":"Declare TMB/PD-L1 useless.","CAF-Targeting als Standard empfehlen.":"Recommend CAF targeting as standard.","Evidenzhierarchie + Biologie.":"Evidence hierarchy + biology.","Erklären Sie die primäre Resistenz trotz PD-L1/TMB und formulieren Sie, welche Aussage die Progressionsbiopsie liefert – und welche Therapieentscheidung sie gerade nicht allein rechtfertigt.":"Explain primary resistance despite PD-L1/TMB and state what the progression biopsy tells us—and which treatment decision it specifically does not justify on its own.","PD-L1/TMB als Potenzial, nicht Garantie einordnen.":"Classify PD-L1/TMB as potential, not guarantee.","CD8-Verteilung räumlich beschreiben.":"Describe CD8 distribution spatially.","Immune exclusion erkennen.":"Recognize immune exclusion.","CAF-/Stromabarriere mechanistisch erklären.":"Explain the CAF/stromal barrier mechanistically.","TME-IHC nicht als alleinigen Companion Diagnostic verwenden.":"Do not use TME IHC as a stand-alone companion diagnostic.","Studienoptionen klar als experimentell markieren.":"Clearly label study options as experimental.","Wenn keine Progressionsbiopsie verfügbar ist, morphologische/radiologische Daten nutzen und TME-Hypothese als Hypothese belassen.":"If no progression biopsy is available, use morphologic/radiologic data and keep the TME hypothesis as a hypothesis.","TME-gerichtete Studien bei passender Verfügbarkeit diskutieren.":"Discuss TME-directed studies if appropriately available.","PD-L1/TMB garantieren Response":"PD-L1/TMB guarantee response","Funktionelle Immunantwort braucht mehr als Potenzialmarker.":"Functional immune response requires more than potential markers.","TME-IHC = Therapieausschluss":"TME IHC = treatment exclusion","Nicht als alleiniger validierter Selektionsassay etabliert.":"Not established as a stand-alone validated selection assay.","CAF-Targeting Standard":"CAF targeting standard","Mechanismus wird zu Routineempfehlung überhöht.":"A mechanism is overpromoted into a routine recommendation.","Die T-Zellen sind da – und kommen trotzdem nicht an den Tumor":"The T cells are there—and still cannot reach the tumor","Die Progressionsbiopsie zeigt viele CD8-Zellen, aber fast ausschließlich in FAP/αSMA-reichem Stroma. Der scheinbare Widerspruch zwischen 'immunogen' und 'resistent' löst sich räumlich auf.":"The progression biopsy shows many CD8 cells, but almost exclusively within FAP/αSMA-rich stroma. The apparent contradiction between 'immunogenic' and 'resistant' resolves spatially.","Der Fall macht aus TME ein sichtbares diagnostisches Konzept statt einer abstrakten Signalwegfolie.":"The case turns TME into a visible diagnostic concept rather than an abstract pathway slide.","Spatial biology integriert":"Spatial biology integrated","PD-L1/TMB günstig, aber CD8 stromal ausgeschlossen; TME erklärt Resistenz, ohne einen neuen Companion Diagnostic zu behaupten.":"PD-L1/TMB favorable, but CD8 cells stromally excluded; TME explains resistance without claiming a new companion diagnostic.","Biologie und Evidenz sauber getrennt.":"Biology and evidence cleanly separated.","Stroma erkannt, Marker verworfen":"Stroma recognized, markers discarded","Immune exclusion korrekt, aber PD-L1/TMB pauschal als wertlos dargestellt.":"Immune exclusion is correct, but PD-L1/TMB are broadly declared worthless.","Zu absolut.":"Too absolute.","Biomarker-Garantie":"Biomarker guarantee","Früher Progress wird ignoriert, weil PD-L1/TMB 'gut' sind.":"Early progression is ignored because PD-L1/TMB are 'good'.","Funktionelle Ebene verpasst.":"Functional layer missed.","Studie mit TME-gerichteter Kombination verfügbar":"Study with TME-directed combination available","Als experimentelle Option diskutieren.":"Discuss as an experimental option.","Mechanistische Hypothese wird im passenden Evidenzrahmen genutzt.":"The mechanistic hypothesis is used within the appropriate evidence framework.","Keine Studie":"No study","Standardtherapie nach etablierter Entitätslogik.":"Standard therapy according to established entity-specific logic.","TME-Befund bleibt erklärend, nicht pseudoprädiktiv.":"The TME finding remains explanatory, not pseudo-predictive.","Biomarker können Potenzial anzeigen, aber keine Antwort garantieren.":"Biomarkers can indicate potential, but cannot guarantee response.","Immune exclusion ist räumlich: Immunzellen vorhanden, aber vom Tumornest ferngehalten.":"Immune exclusion is spatial: immune cells are present but kept away from tumor nests.","CAF-/Matrix-Komponenten können physische und signalbiologische Barrieren bilden.":"CAF/matrix components can form physical and signaling barriers.","TME-IHC ist mechanistisch wertvoll, aber kein automatisch validierter Companion Diagnostic.":"TME IHC is mechanistically valuable, but not an automatically validated companion diagnostic.","Progressionsmaterial kann Resistenzbiologie sichtbar machen.":"Progression material can reveal resistance biology.","Trotz PD-L1 und erhöhter TMB zeigt die Progressionsbiopsie ein immune-excluded Muster mit CD8-Zellen im stromalen Kompartiment. Das erklärt die fehlende effektive Tumorinteraktion, ist aber kein alleiniger routinemäßiger Selektionsmarker für eine konkrete Folgetherapie.":"Despite PD-L1 and elevated TMB, the progression biopsy shows an immune-excluded pattern with CD8 cells in the stromal compartment. This explains the lack of effective tumor interaction, but is not a stand-alone routine selection marker for a specific subsequent therapy.","Marker vs Funktion":"Markers vs function","spatial TILs":"Spatial TILs","Stromabarriere":"Stromal barrier","Was ist der Unterschied zwischen immune-desert und immune-excluded?":"What is the difference between immune-desert and immune-excluded?","Welche Rolle kann TGF-β/CAF-Biologie spielen?":"What role can TGF-β/CAF biology play?","Wie könnte Digitalpathologie spatial TILs künftig standardisieren?":"How could digital pathology standardize spatial TILs in the future?","viele CD8-Zellen, aber außerhalb der Tumornester":"Many CD8 cells, but outside the tumor nests","Räumliche Immunbiologie kann Einzelmarker widersprechen":"Spatial immune biology can contradict individual markers","PD-L1/TMB → Nonresponse → spatial biopsy → immune exclusion":"PD-L1/TMB → nonresponse → spatial biopsy → immune exclusion","pT1-CRC nach Endoskopie: Tumor budding als sichtbarer Invasions-Hallmark":"pT1 CRC after endoscopy: tumor budding as a visible invasion hallmark","EMT-/Invasionsfront-Fall mit Metas…":"EMT/invasive-front case with metas…","Gastroenterologie / Viszeralchirurgie / Pathologieboard":"Gastroenterology / Visceral surgery / Pathology board","56-jähriger Patient nach endoskopischer en-bloc-Resektion eines pT1-Sigmakarzinoms. Die Frage ist, ob die lokale Therapie ausreicht oder wegen Lymphknotenrisiko eine onkologische Nachresektion diskutiert werden muss.":"56-year-old man after endoscopic en-bloc resection of a pT1 sigmoid carcinoma. The question is whether local therapy is sufficient or oncologic re-resection should be discussed because of lymph-node risk.","Welche morphologischen Merkmale an der Invasionsfront sind klinisch relevant – und welche Rolle spielt das EMT-Konzept dabei?":"Which morphologic features at the invasive front are clinically relevant—and what role does the EMT concept play?","Entscheidung über weitere Operation im nächsten Board.":"Decision on further surgery at the next board.","Endoskopie":"Endoscopy","20-mm-Läsion, vollständig en bloc reseziert.":"20-mm lesion, completely resected en bloc.","pT1-Adenokarzinom, Resektionsrand tumorfrei.":"pT1 adenocarcinoma, tumor-free resection margin.","Konflikt":"Conflict","Ein 'R0' klingt beruhigend, aber R0 beantwortet das Risiko okkulter Lymphknotenmetastasen nicht allein.":"An 'R0' sounds reassuring, but R0 alone does not answer the risk of occult lymph-node metastases.","Ein experimentelles EMT-IHC-Panel wird höher gewichtet als validierte histopathologische Risikofaktoren.":"An experimental EMT IHC panel is weighted more heavily than validated histopathologic risk factors.","Histologie + Invasionsfront":"Histology + invasive front","Submukosale Invasion; an der tiefsten Front zahlreiche Einzelzellen und kleine Tumorzellcluster entsprechend hochgradigem Tumor budding.":"Submucosal invasion; at the deepest front, numerous single cells and small tumor-cell clusters corresponding to high-grade tumor budding.","Weitere Risiken":"Additional risks","Fokale lymphovaskuläre Invasion; keine schlechte Differenzierung.":"Focal lymphovascular invasion; no poor differentiation.","EMT-Kontext":"EMT context","An Buds fokal reduzierte membranäre E-Cadherin-Expression und veränderte β-Catenin-Lokalisation möglich – biologisch passend zu partieller EMT.":"At buds, focal reduced membranous E-cadherin expression and altered β-catenin localization may occur—biologically consistent with partial EMT.","Morphologischer Risikomarker versus mechanistischer Zusatzbefund.":"Morphologic risk marker versus mechanistic additional finding.","Komplettes endoskopisches Resektat, gut orientiert.":"Complete endoscopic resection specimen, well oriented.","Primärentscheidung":"Primary decision","HE-basierte Bewertung von Budding, LVI, Differenzierung, Invasionstiefe und Resektionsrand.":"H&E-based assessment of budding, LVI, differentiation, depth of invasion, and resection margin.","Zusatz-IHC":"Additional IHC","EMT-Panel kann den Hallmark illustrieren, ist aber nicht erforderlich, um den klinischen Hochrisikobefund zu erkennen.":"An EMT panel can illustrate the hallmark but is not required to recognize the clinical high-risk finding.","Mechanismusmarker dürfen die standardisierte Morphologie nicht verdrängen.":"Mechanistic markers must not displace standardized morphology.","Histologische Invasionsfront / Risikofaktoren":"Histologic invasive front / risk factors","HE / Invasionsfront":"H&E / invasive front","Hochgradiges Tumor budding an der tiefen Invasionsfront plus fokale lymphovaskuläre Invasion. Diese histopathologischen Hochrisikofaktoren sind für die Entscheidung nach endoskopischer pT1-Resektion klinisch relevant.":"High-grade tumor budding at the deep invasive front plus focal lymphovascular invasion. These histopathologic high-risk factors are clinically relevant for decisions after endoscopic pT1 resection.","EMT-IHC":"EMT IHC","Buds zeigen fokal reduzierte E-Cadherin-Membranfärbung, Vimentin-Zunahme und veränderte β-Catenin-Lokalisation – mechanistisch vereinbar mit partieller EMT, aber kein eigenständiger validierter Operationsindikator.":"Buds show focal reduced E-cadherin membrane staining, increased vimentin, and altered β-catenin localization—mechanistically compatible with partial EMT, but not an independent validated indication for surgery.","Breite Tumorgenetik liefert für die unmittelbare pT1-Risikostratifikation keinen Ersatz für die relevanten histopathologischen Invasionsmerkmale.":"Broad tumor genetics does not replace relevant histopathologic invasion features for immediate pT1 risk stratification.","Resektion":"Resection","Endoskopisch R0.":"Endoscopic R0.","Invasionsfront":"Invasive front","Hochgradiges Tumor budding und fokale Lymphgefäßinvasion.":"High-grade tumor budding and focal lymphatic invasion.","Der Fall verbindet Morphologie und Hallmark-Biologie: Tumor budding an der Invasionsfront ist ein sichtbares Korrelat invasiver/plastischer Tumorzellzustände und bei pT1-CRC ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen. EMT-IHC kann die Biologie illustrieren, entscheidet aber nicht über die weitere Operation. Die klinische Konsequenz entsteht aus standardisierten Hochrisikofaktoren wie Budding, LVI, Differenzierung, Tiefe und Resektionsstatus.":"The case links morphology and hallmark biology: tumor budding at the invasive front is a visible correlate of invasive/plastic tumor-cell states and an established histopathologic risk factor for lymph-node metastasis in pT1 CRC. EMT IHC can illustrate the biology but does not decide further surgery. The clinical consequence arises from standardized high-risk factors such as budding, LVI, differentiation, depth, and resection status.","Teilbefund: EMT ist biologisch plausibel, aber die klinische Risikoeinschätzung muss an validierten histopathologischen Merkmalen hängen.":"Partial result: EMT is biologically plausible, but clinical risk assessment must rely on validated histopathologic features.","Tumor budding als klinisch relevanten Invasionsfront-Befund erkennen":"Recognize tumor budding as a clinically relevant invasive-front finding","R0 nicht mit niedrigem Lymphknotenrisiko gleichsetzen":"Do not equate R0 with low lymph-node risk","EMT als mechanistische Erklärung, nicht als eigenständigen Routine-Selektionsassay einordnen":"Classify EMT as a mechanistic explanation, not a stand-alone routine selection assay","HE-basierte standardisierte Risikofaktoren priorisieren":"Prioritize standardized H&E-based risk factors","Falschaussage: ein positives EMT-IHC-Panel ist die Operationsindikation":"False statement: a positive EMT IHC panel is the indication for surgery","Optimale Lösung: Morphologie zuerst. High-grade budding und LVI machen den pT1-Fall trotz R0 klinisch risikorelevant; EMT-IHC erklärt das Hallmark, ersetzt aber nicht die standardisierte histopathologische Entscheidung.":"Optimal solution: morphology first. High-grade budding and LVI make the pT1 case clinically high-risk despite R0; EMT IHC explains the hallmark but does not replace the standardized histopathologic decision.","pT1 CRC":"pT1 CRC","Tumor budding":"Tumor budding","Invasion":"Invasion","EMT":"EMT","Lymphovascular invasion":"Lymphovascular invasion","Hallmarks":"Hallmarks","Tumor budding: Hallmark im HE statt EMT-Overtesting":"Tumor budding: a hallmark visible on H&E instead of EMT overtesting","GI-Pathologie / Molekularpathologie / MTB":"GI pathology / Molecular pathology / MTB","Tumor budding als morphologisches Korrelat invasiver/plastischer Tumorzellzustände erkennen.":"Recognize tumor budding as a morphologic correlate of invasive/plastic tumor-cell states.","Bei pT1-CRC klinisch relevante histopathologische Hochrisikofaktoren priorisieren.":"Prioritize clinically relevant histopathologic high-risk factors in pT1 CRC.","R0-Resektion von Lymphknotenrisiko unterscheiden.":"Distinguish R0 resection from lymph-node risk.","EMT-IHC als mechanistische Illustration und nicht als eigenständigen Operationsindikator einordnen.":"Classify EMT IHC as a mechanistic illustration, not a stand-alone indication for surgery.","Morphologie direkt mit Hallmark-Biologie und klinischer Konsequenz verbinden.":"Directly connect morphology with hallmark biology and clinical consequence.","Der Polyp ist komplett raus, der Rand ist frei – eigentlich klingt alles gut. An der tiefen Invasionsfront stehen jedoch zahlreiche einzelne Tumorzellen und kleine Cluster: High-grade tumor budding. Genau dort wird ein abstrakter Hallmark plötzlich klinisch sichtbar.":"The polyp is completely removed and the margin is clear—everything sounds good. Yet at the deep invasive front there are numerous single tumor cells and small clusters: high-grade tumor budding. This is where an abstract hallmark suddenly becomes clinically visible.","56-jähriger Patient nach endoskopischer R0-Resektion eines pT1-Sigmakarzinoms. Das Board muss entscheiden, ob wegen histopathologischer Hochrisikofaktoren eine onkologische Nachresektion diskutiert werden sollte. EMT ist die biologische Erklärung, aber nicht der primäre klinische Test.":"56-year-old man after endoscopic R0 resection of a pT1 sigmoid carcinoma. The board must decide whether oncologic re-resection should be discussed because of histopathologic high-risk factors. EMT is the biological explanation, but not the primary clinical test.","R0 ist nicht alles":"R0 is not everything","Lokale Exzision ist vollständig.":"Local excision is complete.","Okkultes Lymphknotenrisiko bleibt eine andere Frage.":"Occult lymph-node risk remains a separate question.","Budding ist sichtbar":"Budding is visible","Einzelzellen/kleine Cluster an der Invasionsfront.":"Single cells/small clusters at the invasive front.","Morphologie kann funktionelle Tumorbiologie verdichten.":"Morphology can condense functional tumor biology.","EMT erklärt, entscheidet aber nicht allein":"EMT explains, but does not decide alone","E-Cadherin/Vimentin/β-Catenin können partielle EMT illustrieren.":"E-cadherin/vimentin/β-catenin can illustrate partial EMT.","Standardisierte Histopathologie trägt die klinische Entscheidung.":"Standardized histopathology drives the clinical decision.","Resektionsstatus":"Resection status","R0":"R0","high-grade tumor budding + fokale LVI":"High-grade tumor budding + focal LVI","Differenzierung":"Differentiation","nicht schlecht differenziert":"Not poorly differentiated","Komplettes gut orientiertes endoskopisches Resektat.":"Complete, well-oriented endoscopic resection specimen.","HE-Reevaluation ist der wichtigste 'Test'.":"H&E reevaluation is the most important 'test'.","EMT-IHC verbraucht Schnitte ohne zwingenden Zusatznutzen für die Operationsentscheidung.":"EMT IHC consumes sections without compelling added value for the surgical decision.","Welche Aussage zu Tumor budding im pT1-CRC ist am treffendsten?":"Which statement about tumor budding in pT1 CRC is most accurate?","Es ist ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen und muss mit anderen Hochrisikofaktoren integriert werden.":"It is an established histopathologic risk factor for lymph-node metastasis and must be integrated with other high-risk factors.","Es ist nur ein interessantes Morphologiedetail.":"It is only an interesting morphologic detail.","Es kann nur durch NGS diagnostiziert werden.":"It can only be diagnosed by NGS.","Es ist synonym mit positivem Resektionsrand.":"It is synonymous with a positive resection margin.","Budding hat klinische Risikobedeutung.":"Budding has clinical risk relevance.","Was bedeutet R0 hier?":"What does R0 mean here?","Die lokale Resektion ist vollständig; das nodale Metastasierungsrisiko wird dadurch nicht automatisch null.":"The local resection is complete; the risk of nodal metastasis is not automatically zero.","Heilung ist sicher.":"Cure is certain.","Lymphknotenmetastasen sind ausgeschlossen.":"Lymph-node metastases are excluded.","EMT ist ausgeschlossen.":"EMT is excluded.","Lokaler Randstatus und biologisches Metastasierungsrisiko sind getrennt.":"Local margin status and biological metastatic risk are separate.","Welche Rolle hat das EMT-IHC-Panel?":"What role does the EMT IHC panel have?","Es kann partielle EMT mechanistisch illustrieren, ist aber kein eigenständiger validierter Operationsindikator.":"It can mechanistically illustrate partial EMT, but is not an independent validated indication for surgery.","Es ist zwingend vor jeder Nachresektion erforderlich.":"It is mandatory before every re-resection.","Es ersetzt Tumor budding.":"It replaces tumor budding.","Es liefert unmittelbar eine zugelassene Targettherapie.":"It directly provides an approved targeted therapy.","Mechanismusmarker ≠ klinischer Standard-Risikomarker.":"Mechanism marker ≠ clinical standard risk marker.","Welche Befunde tragen die klinische Entscheidung primär?":"Which findings primarily drive the clinical decision?","Budding, LVI, Differenzierung, Invasionstiefe und Resektionsstatus im standardisierten histopathologischen Kontext.":"Budding, LVI, differentiation, depth of invasion, and resection status in the standardized histopathologic context.","Nur E-Cadherin/Vimentin.":"Only E-cadherin/vimentin.","Breites Pan-Cancer-NGS.":"Broad pan-cancer NGS.","PD-L1.":"PD-L1.","Morphologische Risikofaktoren sind hier zentral.":"Morphologic risk factors are central here.","Leiten Sie vom HE-Befund an der Invasionsfront über die Hallmark-Biologie zur klinischen Konsequenz nach endoskopischer pT1-Resektion ab.":"Derive the clinical consequence after endoscopic pT1 resection from the H&E finding at the invasive front through hallmark biology.","R0 als lokalen Resektionsstatus anerkennen.":"Acknowledge R0 as local resection status.","High-grade tumor budding erkennen und standardisiert bewerten.":"Recognize and standardize high-grade tumor budding.","LVI als zusätzlichen Hochrisikofaktor integrieren.":"Integrate LVI as an additional high-risk factor.","EMT als mechanistische Erklärung formulieren.":"Formulate EMT as a mechanistic explanation.","EMT-IHC nicht zur Operationsvoraussetzung machen.":"Do not make EMT IHC a prerequisite for surgery.","Onkologische Nachresektion wegen kombinierter Hochrisikofaktoren im Board diskutieren.":"Discuss oncologic re-resection because of combined high-risk factors in the board.","Auf EMT-IHC vollständig verzichten und die Hallmark-Biologie rein morphologisch erklären – klinisch absolut vertretbar.":"Completely omit EMT IHC and explain the hallmark biology purely morphologically—clinically entirely acceptable.","Bei Grenzfällen zusätzliche pathologische Zweitbegutachtung statt breitem Molekularpanel.":"In borderline cases, use additional pathology review rather than a broad molecular panel.","R0 = kein Risiko":"R0 = no risk","Lymphknotenrisiko ist nicht identisch mit lokalem Randstatus.":"Lymph-node risk is not identical to local margin status.","EMT-IHC entscheidet":"EMT IHC decides","Mechanistische Marker ersetzen keine validierte pT1-Risikostratifikation.":"Mechanistic markers do not replace validated pT1 risk stratification.","Budding nur Forschung":"Budding only for research","Budding besitzt etablierte prognostische/Risikobedeutung.":"Budding has established prognostic/risk relevance.","Der wichtigste Hallmark-Test ist bereits auf dem HE":"The most important hallmark test is already on the H&E slide","Das optionale EMT-Panel zeigt erwartbare partielle EMT-Zeichen, ändert aber die klinische Entscheidung nicht. High-grade budding und LVI waren bereits im HE sichtbar und tragen die Konsequenz.":"The optional EMT panel shows expected partial-EMT features but does not change the clinical decision. High-grade budding and LVI were already visible on H&E and drive the consequence.","Der Fall verbindet Grundlagenbiologie mit Pathologieroutine, ohne Molekulardiagnostik künstlich aufzublähen.":"The case connects basic biology with routine pathology without artificially inflating molecular diagnostics.","Morphologie → Hallmark → Konsequenz":"Morphology → hallmark → consequence","R0-pT1-CRC, aber high-grade budding + LVI → relevantes nodales Risiko; EMT mechanistisch, nicht als Pflichtassay.":"R0 pT1 CRC, but high-grade budding + LVI → relevant nodal risk; EMT mechanistic, not a mandatory assay.","Genau die gewünschte Integrationsleistung.":"Exactly the intended integration task.","EMT verstanden, Risiko unscharf":"EMT understood, risk unclear","Biologie gut erklärt, aber klinisch relevante Histofaktoren nicht priorisiert.":"Biology well explained, but clinically relevant histologic factors not prioritized.","Zu grundlagenlastig.":"Too focused on basic biology.","R0 = erledigt":"R0 = done","Budding/LVI werden trotz freiem Rand ignoriert.":"Budding/LVI are ignored despite a clear margin.","Klinische Konsequenz verpasst.":"Clinical consequence missed.","Mehrere histologische Hochrisikofaktoren":"Multiple histologic high-risk factors","Onkologische Nachresektion mit Lymphknotenbewertung im interdisziplinären Kontext diskutieren.":"Discuss oncologic re-resection with lymph-node assessment in an interdisciplinary context.","Nodales Risiko wird adressiert.":"Nodal risk is addressed.","Keine Hochrisikofaktoren":"No high-risk factors","Lokale Strategie nach geltenden Kriterien erwägen.":"Consider a local strategy according to applicable criteria.","Übertherapie vermeiden.":"Avoid overtreatment.","Tumor budding ist ein morphologisches Korrelat von Invasion/plastischen Zellzuständen.":"Tumor budding is a morphologic correlate of invasion/plastic cell states.","Bei pT1-CRC ist budding ein klinisch relevanter Risikofaktor für Lymphknotenmetastasen.":"In pT1 CRC, budding is a clinically relevant risk factor for lymph-node metastases.","R0 beantwortet die lokale Resektion, nicht automatisch das nodale Risiko.":"R0 answers local resection status, not automatically nodal risk.","EMT-IHC kann Mechanismus illustrieren, ist aber kein notwendiger Operationsindikator.":"EMT IHC can illustrate mechanism but is not a necessary indication for surgery.","HE kann funktionelle Tumorbiologie als kumulative Morphologie sichtbar machen.":"H&E can make functional tumor biology visible as cumulative morphology.","Trotz R0-Resektion zeigen high-grade tumor budding und LVI ein relevantes Lymphknotenrisiko. Tumor budding verbindet die Invasionsfront direkt mit Hallmark-Biologie; EMT-IHC ist optional erklärend, nicht entscheidungsdefinierend.":"Despite R0 resection, high-grade tumor budding and LVI indicate relevant lymph-node risk. Tumor budding directly connects the invasive front with hallmark biology; EMT IHC is optional and explanatory, not decision-defining.","R0 vs nodales Risiko":"R0 vs nodal risk","EMT als Mechanismus":"EMT as mechanism","Morphologie priorisiert":"Morphology prioritized","Welche HE-Merkmale sind funktionelle 'Fingerabdrücke' von Hallmarks?":"Which H&E features are functional 'fingerprints' of hallmarks?","Warum ist partielle EMT biologisch plausibler als ein binärer EMT-Schalter?":"Why is partial EMT biologically more plausible than a binary EMT switch?","Wo hilft Molekulardiagnostik – und wo macht sie einen guten HE-Befund nur komplizierter?":"Where does molecular diagnostics help—and where does it merely make a good H&E finding more complicated?","high-grade budding trotz R0":"High-grade budding despite R0","Morphologie kann Hallmarks klinisch relevant abbilden":"Morphology can depict hallmarks in a clinically relevant way","R0 → Invasionsfront → budding/LVI → Hallmark → klinische Konsequenz":"R0 → invasive front → budding/LVI → hallmark → clinical consequence","Coverage-Loch im EGFR-Exon 20: „negativ“ ist hier nicht negativ":"Coverage gap in EGFR exon 20: ‘negative’ is not negative here","Coverage-Loch in therapieentscheid…":"Coverage gap in a treatment-decisive exon…","58-jährige Nie-Raucherin mit metastasiertem pulmonalem Adenokarzinom. Das DNA-Panel wird als „kein therapierbarer Treiber nachweisbar“ zusammengefasst.":"58-year-old never-smoker with metastatic pulmonary adenocarcinoma. The DNA panel is summarized as ‘no actionable driver detected’. ","Darf der Fall als molekular negativ abgeschlossen werden, obwohl der Coverage-Report für EGFR-Exon 20 unterhalb des laborintern validierten Mindestkriteriums liegt?":"Can the case be closed as molecularly negative even though the coverage report for EGFR exon 20 is below the laboratory’s internally validated minimum criterion?","Die Erstlinienentscheidung soll in vier Tagen fallen.":"The first-line treatment decision is due in four days.","ECOG 1, Leber- und Knochenmetastasen; ausreichend Zeit für eine gezielte Nachklärung, aber nicht für beliebig viele Wiederholungen.":"ECOG 1, liver and bone metastases; enough time for targeted clarification, but not for an unlimited number of repeats.","KRAS, BRAF, MET-Exon-14 und ERBB2 ohne pathogene Alteration; Fusionstestung separat vorgesehen.":"KRAS, BRAF, MET exon 14 and ERBB2 without pathogenic alteration; fusion testing planned separately.","QC-Hinweis":"QC note","Median-Coverage des Panels ca. 780×, EGFR-Exon 20 jedoch nur 24×; laborintern validiertes Mindestkriterium für einen negativen Call wird dort nicht erreicht.":"Median panel coverage approx. 780×, but EGFR exon 20 only 24×; the laboratory’s internally validated minimum criterion for a negative call is not met there.","Ein global „guter“ Run wird mit vollständiger lokaler Aussagefähigkeit gleichgesetzt.":"A globally ‘good’ run is equated with complete local interpretability.","Adenokarzinom der Lunge, TTF1/Napsin A positiv.":"Lung adenocarcinoma, TTF1/Napsin A positive.","ca. 45 %.":"approx. 45%.","Ist das Exon tatsächlich wildtyp oder nur unzureichend untersucht?":"Is the exon truly wild type, or simply insufficiently assessed?","Hinweis":"Note","„Nicht nachgewiesen“ und „nicht ausreichend geprüft“ sind unterschiedliche Aussagen.":"‘Not detected’ and ‘not adequately assessed’ are different statements.","FFPE-Lebermetastase, Restblock vorhanden.":"FFPE liver metastasis, residual block available.","Menge ausreichend; übrige Targets technisch unauffällig.":"Quantity sufficient; other targets technically unremarkable.","Coverage":"Coverage","isolierter Dropout in EGFR-Exon 20.":"isolated dropout in EGFR exon 20.","Ressourcen":"Resources","Eine gezielte orthogonale Abklärung ist schneller und materialsparender als ein blindes komplettes Re-Panel.":"A targeted orthogonal clarification is faster and uses less material than blindly repeating the entire panel.","Coverage-/QC-Review":"Coverage/QC review","Nicht ausreichend abgedecktes Exon gezielt klären":"Targeted clarification of the insufficiently covered exon","Coverage-Review":"Coverage review","Der Run ist global valide, aber EGFR-Exon 20 unterschreitet das laborintern validierte Mindestkriterium. Für dieses Exon ist ein negativer Befund nicht belastbar.":"The run is globally valid, but EGFR exon 20 falls below the laboratory’s internally validated minimum criterion. A negative result for this exon is not reliable.","Orthogonale Abklärung":"Orthogonal clarification","Eine unabhängig amplifizierte, validierte Zielmethode weist eine EGFR-Exon-20-Insertion nach. Der ursprüngliche „negative“ Panelbefund war an dieser Stelle nicht aussagefähig.":"An independently amplified, validated targeted method detects an EGFR exon 20 insertion. The original ‘negative’ panel result was not informative at this site.","NGS-Wiederholung":"NGS repeat","Die Wiederholung mit demselben Assay zeigt erneut den lokalen Dropout. Ein identisches technisches Design löst den systematischen Coverage-Ausfall nicht zuverlässig.":"Repeating the same assay again shows the local dropout. An identical technical design does not reliably resolve the systematic coverage failure.","Breites Re-Panel":"Broad re-panel","Mehr Panelbreite beantwortet das lokale Coverage-Problem nicht automatisch; entscheidend ist die validierte Abdeckung des fraglichen Exons.":"Greater panel breadth does not automatically solve a local coverage problem; what matters is validated coverage of the exon in question.","Global gute Sequenzierqualität; isolierter lokaler Coverage-Ausfall in einem therapieentscheidenden Bereich.":"Globally good sequencing quality; isolated local coverage failure in a treatment-decisive region.","Ein negativer Call ist nur für ausreichend validiert untersuchte Zielregionen zulässig.":"A negative call is permissible only for target regions that have been adequately examined under validated conditions.","Der NGS-Run ist nicht insgesamt ungültig, aber EGFR-Exon 20 ist wegen lokaler Unterabdeckung nicht sicher negativ befundbar. Die Limitation muss explizit berichtet und die Zielregion gezielt nachuntersucht werden. Eine orthogonale Methode weist schließlich eine EGFR-Exon-20-Insertion nach.":"The NGS run is not invalid overall, but EGFR exon 20 cannot be reliably reported as negative because of local undercoverage. The limitation must be explicitly reported and the target region specifically retested. An orthogonal method ultimately detects an EGFR exon 20 insertion.","Teilbefund: Das Panel darf nicht pauschal als vollständig negativ zusammengefasst werden, solange die therapieentscheidende Zielregion das validierte Coverage-Kriterium nicht erfüllt.":"Partial report: the panel must not be summarized globally as completely negative while the treatment-decisive target region fails the validated coverage criterion.","lokale Coverage statt nur Mittelwert prüfen":"check local coverage, not only the mean","„nicht nachgewiesen“ von „nicht ausreichend untersucht“ trennen":"distinguish ‘not detected’ from ‘not adequately assessed’","gezielte Nachtestung definieren":"define targeted follow-up testing","Falschaussage: hohe Median-Coverage macht jede Zielregion sicher negativ":"False statement: high median coverage makes every target region reliably negative","Optimale Lösung: lokalen Coverage-Defekt erkennen, die Aussage im Befund begrenzen und das betroffene Exon mit einer unabhängigen validierten Methode schließen.":"Optimal solution: recognize the local coverage defect, limit the statement in the report and close the affected exon with an independent validated method.","MTB-LAB":"MTB-LAB","Das Loch im „negativen“ Panel":"The gap in the ‘negative’ panel","Molekularpathologie / NGS-Freigabe / MTB":"Molecular pathology / NGS release / MTB","Coverage auf Zielregionsebene statt nur als Run-Mittelwert bewerten.":"Assess coverage at target-region level rather than only as a run average.","Nicht nachgewiesen von nicht ausreichend untersucht unterscheiden.":"Distinguish not detected from not adequately assessed.","Bei lokalem Coverage-Ausfall Limitation und gezielte Nachtestung formulieren.":"For a local coverage failure, state the limitation and targeted follow-up testing.","Wiederholung desselben Assays von einer methodisch unabhängigen Bestätigung unterscheiden.":"Distinguish repetition of the same assay from methodologically independent confirmation.","Der Bericht sagt „kein therapierbarer Treiber“. Im QC-Tab fällt aber eine einzige rote Zeile auf: EGFR-Exon 20, 24×. Der Rest des Panels liegt bei mehreren hundert Reads. Genau dort darf aus „nichts gesehen“ kein „sicher nicht vorhanden“ werden.":"The report says ‘no actionable driver’. But one red line stands out in the QC tab: EGFR exon 20, 24×. The rest of the panel has several hundred reads. Precisely here, ‘nothing seen’ must not become ‘certainly absent’. ","58-jährige Nie-Raucherin mit metastasiertem Lungenadenokarzinom. Das Panel ist global technisch gut, aber eine therapieentscheidende Zielregion unterschreitet das validierte Mindestkriterium. Das Board muss entscheiden, ob limitiert berichtet, wiederholt oder orthogonal geschlossen wird.":"58-year-old never-smoker with metastatic lung adenocarcinoma. The panel is technically good overall, but a treatment-decisive target region falls below the validated minimum criterion. The board must decide whether to issue a limited report, repeat the test, or close the gap orthogonally.","Global gut, lokal schlecht":"Globally good, locally poor","Median-Coverage ca. 780×, EGFR-Exon 20 nur 24×.":"Median coverage approx. 780×, EGFR exon 20 only 24×.","Run-QC ersetzt keine Target-QC.":"Run QC does not replace target QC.","Sprache ist Diagnostik":"Language is diagnostics","„Keine Mutation nachweisbar“ behauptet mehr als „Region nicht ausreichend abgedeckt“.":"‘No mutation detected’ claims more than ‘region insufficiently covered’. ","Befundformulierung muss die analytische Aussagegrenze spiegeln.":"Report wording must reflect the analytical limits of interpretation.","Wiederholung ist nicht automatisch unabhängig":"Repetition is not automatically independent","Ein identisches Assaydesign kann denselben Dropout reproduzieren.":"An identical assay design can reproduce the same dropout.","Orthogonale Testung kann systematische Assaygrenzen besser adressieren.":"Orthogonal testing can better address systematic assay limitations.","ca. 45 %":"approx. 45%","Panel-QC":"Panel QC","global valide":"globally valid","Lokale QC":"Local QC","EGFR-Exon 20 unter laborintern validierter Mindest-Coverage":"EGFR exon 20 below the laboratory-validated minimum coverage","Restmaterial vorhanden, aber nicht unbegrenzt.":"Residual material available, but not unlimited.","Zeitkritische Therapieentscheidung.":"Time-critical treatment decision.","Der lokale Coverage-Grenzwert ist assay- und laborvalidiert; es wird kein universeller Zahlenwert postuliert.":"The local coverage threshold is validated for the assay and laboratory; no universal numerical value is postulated.","Welche Aussage ist bei hoher Median-Coverage, aber unzureichender Coverage eines therapieentscheidenden Exons korrekt?":"Which statement is correct when median coverage is high but coverage of a treatment-decisive exon is insufficient?","Der Run kann global valide sein, während dieses Exon nicht sicher negativ befundbar ist.":"The run may be globally valid while this exon cannot reliably be reported as negative.","Hohe Median-Coverage macht alle Exons sicher negativ.":"High median coverage makes all exons reliably negative.","Der gesamte Run ist zwingend ungültig.":"The entire run is necessarily invalid.","Coverage ist nur für Forschungsdaten relevant.":"Coverage is relevant only for research data.","Aussagefähigkeit wird zielregionsbezogen bewertet.":"Interpretability is assessed at the target-region level.","Wie sollte die Limitation berichtet werden?":"How should the limitation be reported?","Die betroffene Region ausdrücklich als nicht ausreichend beurteilt kennzeichnen und Nachtestung empfehlen.":"Explicitly label the affected region as insufficiently assessed and recommend follow-up testing.","Gesamtbefund schlicht „negativ“ nennen.":"Simply call the overall result ‘negative’. ","Coverage nur intern dokumentieren.":"Document coverage only internally.","Direkt eine Therapie ausschließen.":"Directly exclude a treatment option.","Die klinische Aussage darf die analytische Leistung nicht überschreiten.":"The clinical statement must not exceed the analytical performance.","Was ist bei einem reproduzierbaren lokalen Assay-Dropout besonders sinnvoll?":"What is particularly appropriate for a reproducible local assay dropout?","Eine unabhängig validierte Methode für die Zielregion einsetzen.":"Use an independently validated method for the target region.","Den identischen Assay beliebig oft wiederholen.":"Repeat the identical assay as many times as desired.","Nur ein größeres Panel bestellen, ohne die Zielabdeckung zu prüfen.":"Order only a larger panel without checking target coverage.","Keine weitere Abklärung.":"No further clarification.","Eine methodisch unabhängige Lösung adressiert systematische Grenzen besser.":"A methodologically independent solution better addresses systematic limitations.","Die orthogonale Methode weist eine EGFR-Exon-20-Insertion nach. Was war der ursprüngliche Fehler?":"The orthogonal method detects an EGFR exon 20 insertion. What was the original error?","Ein nicht ausreichend untersuchter Bereich wurde wie ein sicher negativer Bereich behandelt.":"An insufficiently assessed region was treated as reliably negative.","Der gesamte NGS-Run war zwingend wertlos.":"The entire NGS run was necessarily worthless.","Die Histologie war falsch.":"The histology was wrong.","Es wurde eine Keimbahnvariante übersehen.":"A germline variant was missed.","Der Fehler lag in der Reichweite der Negativaussage.":"The error lay in the scope of the negative statement.","Entscheiden Sie, wie der Panelbefund freigegeben wird und wie die offene Zielregion methodisch geschlossen wird.":"Decide how the panel result should be released and how the unresolved target region should be closed methodologically.","Coverage-Report auf therapieentscheidende Regionen prüfen.":"Review the coverage report for treatment-decisive regions.","Lokale Limitation explizit formulieren.":"Explicitly state the local limitation.","Nicht den gesamten Run verwerfen, wenn der Rest valide ist.":"Do not discard the entire run if the remainder is valid.","Gezielte orthogonale oder technisch geeignete Wiederholungsstrategie wählen.":"Choose a targeted orthogonal or technically appropriate repeat strategy.","Endbefund nach Nachtestung aktualisieren.":"Update the final report after follow-up testing.","Wiederholung des Panels kann vertretbar sein, wenn die Ursache plausibel zufällig/librarybezogen ist und das Wiederholungsdesign die Zielregion zuverlässig abdeckt.":"Repeating the panel may be reasonable if the cause is plausibly random/library-related and the repeat design reliably covers the target region.","„Panel negativ“ trotz Coverage-Loch":"‘Panel negative’ despite a coverage gap","Überdehnt die analytische Aussage.":"Overextends the analytical statement.","Run komplett verwerfen":"Discard the entire run","Ignoriert, dass die übrigen Regionen valide sein können.":"Ignores that the remaining regions may be valid.","Blind identisch wiederholen":"Blindly repeat identically","Kann systematische Dropouts reproduzieren.":"May reproduce systematic dropouts.","Die rote Zeile war der eigentliche Befund":"The red line was the real finding","Die gezielte unabhängige Nachtestung weist eine EGFR-Exon-20-Insertion nach.":"Targeted independent follow-up testing detects an EGFR exon 20 insertion.","Der Fall zeigt, dass analytische Nichtbeurteilbarkeit klinisch relevanter sein kann als ein langer negativer Variantenbericht.":"The case shows that analytical non-assessability can be clinically more relevant than a long negative variant report.","Limitiert + gezielt geschlossen":"Limited + specifically resolved","Lokale Limitation erkannt, orthogonal nachgetestet, relevante Alteration gefunden.":"Local limitation recognized, orthogonally retested, relevant alteration found.","Vollständige analytische und klinische Einordnung.":"Complete analytical and clinical interpretation.","Falsch-negativ freigegeben":"Released as false negative","Coverage-Loch wird ignoriert und die Region als negativ berichtet.":"The coverage gap is ignored and the region is reported as negative.","Kritischer Scope-Fehler.":"Critical scope error.","Ganzer Run verworfen":"Entire run discarded","Valide übrige Ergebnisse werden unnötig wiederholt.":"Other valid results are repeated unnecessarily.","Unnötiger Material-/TAT-Verlust.":"Unnecessary material/TAT loss.","Coverage unter validiertem Kriterium":"Coverage below validated criterion","Zielregion als nicht sicher beurteilbar kennzeichnen":"Label target region as not reliably assessable","Nachtestung erforderlich, wenn klinisch relevant.":"Follow-up testing required if clinically relevant.","Coverage ist lokal.":"Coverage is local.","Negativbefunde brauchen nachgewiesene analytische Aussagefähigkeit.":"Negative findings require demonstrated analytical interpretability.","Limitationen gehören in die klinische Kernaussage, nicht nur in interne QC.":"Limitations belong in the core clinical statement, not only in internal QC.","Der Run bleibt für ausreichend abgedeckte Regionen valide. EGFR-Exon 20 ist nicht sicher negativ befundbar und muss explizit limitiert sowie gezielt nachuntersucht werden; eine unabhängige Methode schließt die diagnostische Lücke.":"The run remains valid for adequately covered regions. EGFR exon 20 cannot reliably be reported as negative and must be explicitly limited and specifically retested; an independent method closes the diagnostic gap.","Target-spezifische QC":"Target-specific QC","Befundsprache":"Report language","Nachteststrategie":"Follow-up testing strategy","Wann reicht eine NGS-Wiederholung?":"When is an NGS repeat sufficient?","Welche Coverage-Metriken müssen im Labor validiert sein?":"Which coverage metrics must be validated in the laboratory?","Wie formuliert man Negativbefunde bei partieller Nichtbeurteilbarkeit?":"How should negative findings be worded when part of the assay is not assessable?","Twist: relevanter Befund liegt in der QC, nicht in der Variantenliste":"Twist: the relevant finding is in QC, not in the variant list","Kernfehler: nicht ausreichend untersucht ≠ negativ":"Core error: insufficiently assessed ≠ negative","Referenzpfad: Coverage prüfen → limitieren → gezielt schließen":"Reference pathway: review coverage → state limitation → close gap specifically","1,4 % EGFR-T790M im FFPE: Resistenzmutation oder Desaminierungsartefakt?":"1.4% EGFR T790M in FFPE: resistance mutation or deamination artifact?","FFPE-C>T-Artefakt bei niedriger VA…":"FFPE C>T artifact at low VAF…","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress unter zielgerichteter Therapie. In einer kleinen FFPE-Rebiopsie wird zusätzlich EGFR p.T790M mit 1,4 % VAF gemeldet.":"67-year-old patient with EGFR-mutant NSCLC and progression on targeted therapy. In a small FFPE rebiopsy, EGFR p.T790M is additionally reported at 1.4% VAF.","Ist die niedrigfrequente C>T-Variante als echte Resistenzsubpopulation belastbar oder zunächst artefaktverdächtig?":"Is the low-frequency C>T variant reliable as a true resistant subpopulation, or should it first be considered artifact-suspicious?","Therapiewechsel soll kurzfristig festgelegt werden.":"A treatment switch is to be decided shortly.","Primärtreiber":"Primary driver","Bekannte klonale EGFR-aktivierende Mutation mit hoher VAF wird in der Rebiopsie erneut nachgewiesen.":"The known clonal EGFR-activating mutation with high VAF is again detected in the rebiopsy.","Neue Variante":"New variant","EGFR p.T790M, 1,4 % VAF, nur knapp oberhalb der technischen Reporting-Grenze.":"EGFR p.T790M, 1.4% VAF, only just above the technical reporting threshold.","Kleine Biopsie, lange Formalinfixierung; DNA zeigt deutliche Fragmentierung.":"Small biopsy, prolonged formalin fixation; DNA shows marked fragmentation.","Actionability des Gens wird mit analytischer Validität des einzelnen Calls verwechselt.":"Gene actionability is confused with analytical validity of the individual call.","Vitales Adenokarzinom, Tumoranteil ca. 30 %.":"Viable adenocarcinoma, tumor content approx. 30%.","Sequenzdaten":"Sequencing data","T790M vorwiegend in einem Strang-/Endkontext, niedrige Molekülzahl; mehrere weitere sehr niedrige C>T/G>A-Ereignisse.":"T790M predominantly in a strand/end-context, low molecule count; several additional very-low-level C>T/G>A events.","Echte Subklonmutation oder FFPE-bedingte Cytosindesaminierung?":"True subclonal mutation or FFPE-related cytosine deamination?","Ein klinisch attraktiver Call verdient nicht weniger, sondern mehr QC.":"A clinically attractive call deserves more QC, not less.","FFPE-Stanzbiopsie, nur wenige Restrollen.":"FFPE core biopsy, only a few residual sections available.","stark fragmentiert.":"severely fragmented.","Alternative":"Alternative","zweite Extraktion aus tieferen Schnitten möglich.":"a second extraction from deeper sections is possible.","Orthogonale Bestätigung gezielt möglich.":"Targeted orthogonal confirmation is possible.","FFPE-Artefaktprüfung":"FFPE artifact assessment","Niedrigfrequenten klinisch relevanten Call bestätigen":"Confirm a low-frequency clinically relevant call","Artefaktreview":"Artifact review","Der Call zeigt typische Warnsignale: sehr niedrige VAF, geringe unabhängige Molekülzahl, ungünstiger Strang-/Read-End-Kontext und zusätzliche niedrigfrequente C>T/G>A-Ereignisse im stark fragmentierten FFPE-Material.":"The call shows typical warning signs: very low VAF, few independent molecules, unfavorable strand/read-end context, and additional low-frequency C>T/G>A events in severely fragmented FFPE material.","Orthogonale Bestätigung":"Orthogonal confirmation","In einer unabhängigen Extraktion und orthogonalen Zielmethode ist p.T790M nicht reproduzierbar, während die bekannte klonale EGFR-Mutation stabil nachweisbar bleibt. Gesamtbild spricht für FFPE-Artefakt.":"In an independent extraction and an orthogonal targeted method, p.T790M is not reproducible, while the known clonal EGFR mutation remains stably detectable. Overall, the pattern supports an FFPE artifact.","Mehr Sequenzierbreite ersetzt die gezielte analytische Prüfung des grenzwertigen Calls nicht.":"Greater sequencing breadth does not replace targeted analytical assessment of the borderline call.","Stark fragmentierte FFPE-DNA mit erhöhtem Risiko niedrigfrequenter Desaminierungsartefakte.":"Severely fragmented FFPE DNA with increased risk of low-frequency deamination artifacts.","Niedrige VAF allein beweist weder Artefakt noch Subklon; Muster, Reproduzierbarkeit und Assay-QC entscheiden.":"Low VAF alone proves neither artifact nor subclone; pattern, reproducibility, and assay QC are decisive.","Die klinisch relevante C>T-Variante liegt in einem stark artefaktanfälligen FFPE-Kontext und ist nicht unabhängig reproduzierbar. Sie darf daher nicht als gesicherte Resistenzmutation berichtet werden; die bekannte klonale EGFR-Alteration bleibt dagegen robust nachweisbar.":"The clinically relevant C>T variant occurs in a highly artifact-prone FFPE context and is not independently reproducible. It must therefore not be reported as a confirmed resistance mutation; the known clonal EGFR alteration, by contrast, remains robustly detectable.","Teilbefund: Eine niedrigfrequente C>T-Variante in stark geschädigter FFPE-DNA muss vor therapeutischer Interpretation auf Artefaktmuster und Reproduzierbarkeit geprüft werden.":"Partial result: A low-frequency C>T variant in severely damaged FFPE DNA must be assessed for artifact pattern and reproducibility before therapeutic interpretation.","Desaminierungsartefakte als Differenzialdiagnose nennen":"Mention deamination artifacts as a differential explanation","VAF nicht isoliert interpretieren":"Do not interpret VAF in isolation","klinisch relevanten Low-VAF-Call unabhängig bestätigen":"Independently confirm a clinically relevant low-VAF call","Falschaussage: therapierbares Gen macht jeden Low-VAF-Call automatisch echt":"False statement: an actionable gene automatically makes every low-VAF call real","Optimale Lösung: Low-VAF-C>T-Call im FFPE-Kontext kritisch prüfen, technische Artefaktmerkmale berücksichtigen und vor Therapieableitung unabhängig bestätigen.":"Optimal solution: critically assess the low-VAF C>T call in the FFPE context, consider technical artifact features, and confirm it independently before deriving treatment implications.","FFPE":"FFPE","Artefakt":"Artifact","Low VAF":"Low VAF","Der attraktive 1,4-%-Call":"The attractive 1.4% call","Molekularpathologie / NGS-QC / MTB":"Molecular Pathology / NGS QC / MTB","FFPE-bedingte C>T/G>A-Artefakte als analytische Differenzialdiagnose erkennen.":"Recognize FFPE-related C>T/G>A artifacts as an analytical differential diagnosis.","VAF, Molekülzahl, Strang-/Read-Kontext und Reproduzierbarkeit gemeinsam bewerten.":"Assess VAF, molecule count, strand/read context, and reproducibility together.","Klinische Relevanz nicht mit analytischer Validität verwechseln.":"Do not confuse clinical relevance with analytical validity.","Low-VAF-Calls vor weitreichender Therapieableitung angemessen bestätigen.":"Appropriately confirm low-VAF calls before far-reaching treatment decisions.","Auf dem Variantenboard leuchtet EGFR p.T790M. VAF 1,4 %. Klinisch wäre der Befund wichtig – analytisch sieht er aber genau so aus, wie ein alter FFPE-Block Probleme machen kann.":"EGFR p.T790M lights up on the variant board. VAF 1.4%. Clinically, the finding would matter—but analytically it looks exactly like the kind of problem an old FFPE block can create.","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress. In einer kleinen, stark fragmentierten Rebiopsie erscheint ein neuer C>T-Call knapp oberhalb der Reporting-Grenze. Das Board muss entscheiden, ob dies ein echter Resistenzklon ist.":"67-year-old patient with EGFR-mutant NSCLC and progression. A new C>T call just above the reporting threshold appears in a small, severely fragmented rebiopsy. The board must decide whether this is a true resistance subclone.","Actionability ist kein QC-Kriterium":"Actionability is not a QC criterion","Ein therapeutisch interessanter Genname macht einen Call nicht analytisch wahr.":"A therapeutically interesting gene name does not make a call analytically true.","Analytische Validität kommt vor klinischer Interpretation.":"Analytical validity comes before clinical interpretation.","FFPE-Muster":"FFPE pattern","Mehrere sehr niedrige C>T/G>A-Ereignisse und fragmentierte DNA erhöhen den Artefaktverdacht.":"Multiple very-low-level C>T/G>A events and fragmented DNA increase suspicion of artifact.","Muster ist informativer als eine einzelne VAF.":"The pattern is more informative than a single VAF.","Unabhängige Reproduzierbarkeit":"Independent reproducibility","Eine zweite Extraktion/orthogonale Methode kann einen grenzwertigen Call stabilisieren oder entkräften.":"A second extraction/orthogonal method can support or refute a borderline call.","Bestätigung sollte möglichst methodisch unabhängig sein.":"Confirmation should be methodologically independent whenever possible.","Bekannter Treiber":"Known driver","klonale EGFR-aktivierende Mutation robust nachweisbar":"clonal activating EGFR mutation robustly detectable","Neuer Call":"New call","EGFR p.T790M, 1,4 % VAF":"EGFR p.T790M, 1.4% VAF","FFPE-QC":"FFPE QC","stark fragmentiert; weitere sehr niedrige C>T/G>A-Ereignisse":"severely fragmented; additional very-low-level C>T/G>A events","Wenig Restmaterial.":"Little residual material.","Der Fall postuliert keine universelle VAF-Grenze; entscheidend ist die laborvalidierte Performance im konkreten Assay.":"The case does not posit a universal VAF threshold; the decisive factor is the laboratory-validated performance of the specific assay.","Was ist der erste richtige Schritt bei einem klinisch relevanten 1,4-%-C>T-Call in stark geschädigtem FFPE?":"What is the first correct step for a clinically relevant 1.4% C>T call in severely damaged FFPE material?","Call-level QC und FFPE-Artefaktmuster prüfen.":"Review call-level QC and the FFPE artifact pattern.","Sofort Therapie ableiten.":"Immediately derive treatment.","Jede Variante unter 5 % grundsätzlich verwerfen.":"Discard every variant below 5% as a rule.","Keimbahntestung veranlassen.":"Arrange germline testing.","Es gibt keine universelle VAF-Regel; der Call muss assay- und kontextbezogen validiert werden.":"There is no universal VAF rule; the call must be validated in an assay- and context-specific manner.","Welche Befunde erhöhen hier den Artefaktverdacht?":"Which findings increase suspicion of artifact here?","sehr niedrige VAF/geringe Molekülzahl":"very low VAF/few molecules","mehrere niedrigfrequente C>T/G>A-Ereignisse":"multiple low-frequency C>T/G>A events","stark fragmentierte FFPE-DNA":"severely fragmented FFPE DNA","bekannte klonale Treibermutation ist robust":"known clonal driver mutation is robust","Die Kombination aus FFPE-Schaden und typischem Substitutionsmuster ist verdächtig.":"The combination of FFPE damage and a typical substitution pattern is suspicious.","Was erhöht die Sicherheit vor therapeutischer Interpretation am stärksten?":"What most strongly increases confidence before therapeutic interpretation?","Unabhängige Extraktion und/oder orthogonale validierte Zielmethode.":"Independent extraction and/or an orthogonal validated targeted method.","Längere Literaturrecherche ohne analytische Prüfung.":"A longer literature search without analytical assessment.","Den gleichen Report erneut öffnen.":"Open the same report again.","Nur die Therapierbarkeit des Gens bewerten.":"Assess only whether the gene is targetable.","Reproduzierbarkeit adressiert die analytische Kernfrage.":"Reproducibility addresses the core analytical question.","T790M ist unabhängig nicht reproduzierbar, der bekannte klonale EGFR-Treiber schon. Wie ist das Gesamtbild?":"T790M is not independently reproducible, but the known clonal EGFR driver is. How should the overall pattern be interpreted?","Der neue Low-VAF-Call ist nicht gesichert und im Kontext am ehesten artefaktbedingt.":"The new low-VAF call is unconfirmed and, in context, most likely artifact-related.","T790M ist trotzdem sicher echt.":"T790M is still definitely real.","Auch der bekannte EGFR-Treiber ist damit falsch.":"The known EGFR driver must therefore also be false.","Der Unterschied ist ohne Bedeutung.":"The difference is irrelevant.","Selektive Nichtreproduzierbarkeit plus Artefaktmuster entkräftet den grenzwertigen Call.":"Selective non-reproducibility plus the artifact pattern argues against the borderline call.","Bewerten Sie, ob der Low-VAF-Call als gesichert berichtet und therapeutisch verwendet werden darf.":"Assess whether the low-VAF call may be reported as confirmed and used therapeutically.","FFPE-Qualität und Substitutionsmuster prüfen.":"Review FFPE quality and substitution pattern.","Call-level Evidenz bewerten.":"Assess call-level evidence.","Low-VAF nicht pauschal verwerfen, aber bei hoher Konsequenz bestätigen.":"Do not reject low VAF categorically, but confirm it when the clinical consequence is high.","Unabhängige Reproduzierbarkeit einbeziehen.":"Include independent reproducibility in the assessment.","Nur robuste Befunde in die Therapiekernaussage aufnehmen.":"Include only robust findings in the core treatment statement.","Bei sehr gut validiertem ultrasensitivem Assay und überzeugender unabhängiger Molekülevidenz kann ein niedriger VAF real sein; der Fall lehrt keine starre Prozentgrenze.":"With a well-validated ultrasensitive assay and convincing independent molecular evidence, a low VAF can be real; the case does not teach a rigid percentage threshold.","<5 % = immer Artefakt":"<5% = always artifact","Ignoriert echte Subklone und assayspezifische Nachweisgrenzen.":"Ignores true subclones and assay-specific detection limits.","Actionable = echt":"Actionable = real","Verwechselt klinische mit analytischer Evidenz.":"Confuses clinical with analytical evidence.","Breites Re-Panel statt Call-QC":"Broad repeat panel instead of call-level QC","Mehr Daten lösen den konkreten Artefaktverdacht nicht automatisch.":"More data do not automatically resolve the specific artifact concern.","Die Resistenzmutation verschwindet":"The resistance mutation disappears","In unabhängiger Extraktion und orthogonaler Zielmethode ist T790M nicht reproduzierbar, der klonale Primärtreiber jedoch stabil.":"In an independent extraction and orthogonal targeted method, T790M is not reproducible, while the clonal primary driver remains stable.","Der attraktivste Befund des Reports ist nicht der belastbarste.":"The most attractive finding in the report is not the most robust one.","Low-VAF korrekt entkräftet":"Low-VAF call correctly ruled out","Artefaktmuster erkannt und Call unabhängig nicht bestätigt.":"An artefact pattern was recognised and the call was not independently confirmed.","Therapeutisches Overcalling vermieden.":"Therapeutic overcalling avoided.","Direkt als Resistenzmutation berichtet":"Reported directly as a resistance mutation","Ein grenzwertiger FFPE-Call steuert die Therapie.":"A borderline FFPE call drives the treatment decision.","Analytische Evidenz unzureichend.":"Analytical evidence is insufficient.","Pauschal unter 5 % verworfen":"Automatically discarded below 5%","Der richtige Ausgang wird aus der falschen Regel abgeleitet.":"The correct outcome is reached using the wrong rule.","Keine universelle VAF-Grenze verwenden.":"Do not use a universal VAF threshold.","klinisch relevanter Low-VAF-Call + Artefaktmuster":"clinically relevant low-VAF call + artefact pattern","analytische Bestätigung vor finaler Therapieaussage":"analytical confirmation before the final treatment statement","Bei Nichtbestätigung nicht als gesicherte Resistenzmutation berichten.":"If not confirmed, do not report it as an established resistance mutation.","FFPE-Artefakte sind call- und kontextabhängig.":"FFPE artefacts are call- and context-dependent.","Niedrige VAF ist ein Warnsignal, kein Urteil.":"A low VAF is a warning signal, not a verdict.","Je größer die klinische Konsequenz, desto wichtiger die analytische Absicherung.":"The greater the clinical consequence, the more important analytical confirmation becomes.","Der T790M-Call ist aufgrund des FFPE-Musters und fehlender unabhängiger Reproduzierbarkeit nicht gesichert; keine Therapieentscheidung allein darauf stützen.":"The T790M call is not established because of the FFPE artefact pattern and lack of independent reproducibility; do not base a treatment decision on it alone.","Low-VAF-Interpretation":"Low-VAF interpretation","Bestätigung":"Confirmation","Welche Artefaktmuster sind plattformabhängig?":"Which artefact patterns are platform-dependent?","Wann ist eine zweite Extraktion sinnvoll?":"When is a second extraction useful?","Wie dokumentiert man nicht bestätigte Calls?":"How should unconfirmed calls be documented?","Twist: klinisch attraktivster Call ist analytisch schwächster":"Twist: the most clinically attractive call is analytically the weakest","Keine starre VAF-Grenze":"No rigid VAF threshold","Referenzpfad: Call-QC → Artefaktmuster → unabhängige Bestätigung":"Reference pathway: call QC → artefact pattern → independent confirmation","Tumor-only BRCA2 bei 48 % VAF: therapeutisch relevant, Keimbahn trotzdem offen":"Tumor-only BRCA2 at 48% VAF: therapeutically relevant, germline status still unresolved","Tumor-only NGS: Keimbahnverdacht B…":"Tumor-only NGS: suspected germline B…","61-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom. Tumor-only NGS zeigt eine pathogene truncierende BRCA2-Variante mit 48 % VAF.":"61-year-old patient with metastatic castration-resistant prostate cancer. Tumor-only NGS shows a pathogenic truncating BRCA2 variant at 48% VAF.","Darf aus VAF und Gen direkt auf eine Keimbahnmutation geschlossen werden – und wie werden therapeutische und hereditäre Konsequenzen getrennt?":"Can VAF and gene identity alone establish a germline mutation—and how should therapeutic and hereditary consequences be separated?","Systemische Therapieentscheidung und genetische Beratung sollen parallel geplant werden.":"Systemic treatment planning and genetic counseling should proceed in parallel.","Schwester mit Mammakarzinom mit 46 Jahren, Vater mit Prostatakarzinom mit 58 Jahren.":"Sister with breast cancer at age 46, father with prostate cancer at age 58.","Tumorprofil":"Tumor profile","Pathogene BRCA2-Trunkierung; Tumorreinheit und Kopienzahl machen eine Herkunft aus der VAF allein nicht eindeutig.":"Pathogenic BRCA2 truncation; tumor purity and copy number make the variant’s origin indeterminate from VAF alone.","„ungefähr 50 %“ wird mit „Keimbahn bewiesen“ gleichgesetzt.":"‘Approximately 50%’ is equated with ‘germline proven’.","Tumorbiomarker und hereditäre Diagnostik sauber entkoppeln und dann wieder integrieren.":"Cleanly separate the tumor biomarker question from hereditary diagnostics, then integrate both again.","Metastasiertes Prostataadenokarzinom.":"Metastatic prostate adenocarcinoma.","BRCA2 pathogene Loss-of-function-Variante, VAF 48 %.":"Pathogenic BRCA2 loss-of-function variant, VAF 48%.","somatisch, Keimbahn oder beides im Tumorkontext?":"somatic, germline, or both in the tumor context?","Tumorreinheit, LOH und Copy-number können VAF deutlich verschieben.":"Tumor purity, LOH and copy number can substantially shift the VAF.","FFPE-Metastase für Tumorprofil; EDTA-Blut für bestätigende Keimbahndiagnostik verfügbar.":"FFPE metastasis for tumor profiling; EDTA blood available for confirmatory germline testing.","ca. 60 %.":"approx. 60%.","Consent":"Consent","Genetische Beratung/Einwilligung für Keimbahndiagnostik erforderlich.":"Genetic counseling/consent is required for germline testing.","Tumor-normal bzw. gezielte Keimbahnbestätigung möglich.":"Tumor-normal analysis or targeted germline confirmation is possible.","Tumor-BRCA/HRR einordnen":"Interpret tumor BRCA/HRR finding","Potenzielle Keimbahn separat klären":"Clarify possible germline origin separately","Pathogene BRCA2-Loss-of-function-Variante im Tumor; für die tumorbezogene Therapieentscheidung relevant, ohne damit die Keimbahnherkunft zu beweisen.":"Pathogenic BRCA2 loss-of-function variant in the tumor; relevant for tumor-directed treatment without proving germline origin.","Die pathogene BRCA2-Variante wird im konstitutionellen Material bestätigt: Keimbahnmutation. Der Tumor-only-Befund war ein Hinweis, nicht der Beweis.":"The pathogenic BRCA2 variant is confirmed in constitutional material: germline mutation. The tumor-only finding was a clue, not proof.","Humangenetische Beratung":"Genetic counseling","Genetische Beratung wird veranlasst; hereditäre Konsequenzen werden außerhalb des reinen Tumorbefunds adressiert.":"Genetic counseling is arranged; hereditary implications are addressed outside the tumor-only report.","Tumor-only":"Tumor-only","Ohne Normalprobe kann die Herkunft einer Variante nicht allein aus der VAF sicher bestimmt werden.":"Without a normal sample, the origin of a variant cannot be determined reliably from VAF alone.","Therapeutische Tumorrelevanz und hereditäre Bedeutung sind getrennte Fragestellungen.":"Therapeutic tumor relevance and hereditary significance are separate questions.","Die pathogene BRCA2-Variante ist im Tumor therapeutisch relevant, aber Tumor-only Sequenzierung beweist keine Keimbahnherkunft. VAF um 50 % erhöht den Verdacht, ist wegen Tumorreinheit, LOH und Copy-number jedoch nicht beweisend. Die bestätigende Analyse im konstitutionellen Material zeigt hier tatsächlich eine Keimbahnmutation.":"The pathogenic BRCA2 variant is therapeutically relevant in the tumor, but tumor-only sequencing does not prove germline origin. A VAF around 50% raises suspicion but is not conclusive because tumor purity, LOH and copy number can alter the value. Confirmatory analysis in constitutional material demonstrates a germline mutation in this case.","Teilbefund: Ein Tumor-only BRCA2-Befund kann therapeutisch relevant sein und gleichzeitig eine separate Keimbahnabklärung auslösen; die VAF allein entscheidet die Herkunft nicht.":"Partial finding: A tumor-only BRCA2 result can be therapeutically relevant while also triggering a separate germline work-up; VAF alone does not determine origin.","Tumoractionability separat bewerten":"Assess tumor actionability separately","Keimbahnverdacht separat adressieren":"Address suspected germline origin separately","VAF nicht als Herkunftsbeweis verwenden":"Do not use VAF as proof of origin","Falschaussage: 48–50 % VAF im Tumor beweist Keimbahn":"False statement: 48–50% VAF in a tumor proves germline origin","Optimale Lösung: Tumorbefund therapeutisch einordnen, Keimbahnverdacht transparent markieren und mit konstitutionellem Material/genetischer Beratung bestätigen.":"Optimal solution: interpret the tumor finding therapeutically, flag suspected germline origin transparently, and confirm it using constitutional material/genetic counseling.","48 % sind kein Abstammungsnachweis":"48% is not proof of ancestry","Molekulares Tumorboard / Humangenetik-Schnittstelle":"Molecular Tumor Board / Genetics interface","Tumor-only NGS nicht mit Keimbahndiagnostik gleichsetzen.":"Do not equate tumor-only NGS with germline diagnostics.","VAF nur als Hinweis und nie isoliert als Herkunftsbeweis nutzen.":"Use VAF only as a clue and never in isolation as proof of origin.","Tumorbezogene Therapieinformation und hereditäre Konsequenzen getrennt bearbeiten.":"Handle tumor-directed treatment information and hereditary implications separately.","Bestätigende Keimbahndiagnostik mit geeigneter Beratung/Einwilligung veranlassen.":"Arrange confirmatory germline testing with appropriate counseling/consent.","BRCA2, pathogene Trunkierung, VAF 48 %. Der Report sieht „keimbahnverdächtig“ aus – aber 48 % im Tumor sind keine Blutprobe. Genau hier muss das Board zwei richtige Aussagen gleichzeitig halten.":"BRCA2, pathogenic truncating variant, VAF 48%. The report looks ‘suggestive of germline’—but 48% in a tumor is not a blood sample. This is exactly where the board must hold two correct statements at once.","61-jähriger Patient mit mCRPC und pathogener BRCA2-Variante im Tumor-only Panel. Der Befund kann therapeutisch relevant sein. Wegen VAF und Familienanamnese besteht zusätzlich Keimbahnverdacht, der separat bestätigt werden muss.":"61-year-old patient with mCRPC and a pathogenic BRCA2 variant in a tumor-only panel. The finding may be therapeutically relevant. VAF and family history additionally raise suspicion of germline origin, which requires separate confirmation.","VAF ist modellabhängig":"VAF is model-dependent","Tumorreinheit, LOH, Amplifikation/Deletion und Klonalität verschieben die beobachtete VAF.":"Tumor purity, LOH, amplification/deletion, and clonality can shift the observed VAF.","50 % ist kein magischer Keimbahn-Cutoff.":"50% is not a magical germline cutoff.","Zwei Konsequenzachsen":"Two consequence axes","Tumortherapie kann auf dem somatischen Befund beruhen; Familien-/Prädispositionsfragen brauchen Keimbahndiagnostik.":"Tumor treatment may rely on the somatic finding; family/predisposition questions require germline testing.","Dasselbe Gen erzeugt zwei unterschiedliche Workflows.":"The same gene generates two different workflows.","Tumor-only hat Grenzen":"Tumor-only has limitations","Ohne Normalprobe bleibt die Herkunft vieler Varianten unbestimmt.":"Without a normal sample, the origin of many variants remains unresolved.","Bericht und Beratung müssen das transparent machen.":"The report and counseling must make this transparent.","pathogene BRCA2-LoF, VAF 48 %":"pathogenic BRCA2 LoF, VAF 48%","frühes Mammakarzinom bei Schwester, Prostatakarzinom beim Vater":"early-onset breast cancer in sister, prostate cancer in father","Normalprobe":"Normal sample","noch nicht untersucht":"not yet tested","Konstitutionelles Material verfügbar.":"Constitutional material is available.","Hereditäre Diagnostik erfordert eigenen Prozess/Einwilligung.":"Hereditary diagnostics require a separate process/consent.","Tumor-VAF wird im Kontext von Reinheit und Copy-number interpretiert.":"Tumor VAF is interpreted in the context of purity and copy number.","Was beweist eine pathogene BRCA2-Variante mit 48 % VAF im Tumor-only Panel?":"What does a pathogenic BRCA2 variant at 48% VAF in a tumor-only panel prove?","Sie ist keimbahnverdächtig, beweist aber ohne konstitutionelle Probe keine Keimbahnherkunft.":"It raises suspicion of germline origin but does not prove it without constitutional material.","Keimbahn ist sicher bewiesen.":"Germline origin is definitely proven.","Somatisch ist sicher bewiesen.":"Somatic origin is definitely proven.","Die Variante ist ein Artefakt.":"The variant is an artifact.","Tumorreinheit und Copy-number verhindern einfache VAF-Herkunftsregeln.":"Tumor purity and copy number prevent simple VAF-based rules for origin.","Welche zwei Fragen müssen getrennt beantwortet werden?":"Which two questions must be answered separately?","Welche tumorbezogene therapeutische Bedeutung hat BRCA2?":"What tumor-directed therapeutic significance does BRCA2 have?","Liegt eine konstitutionelle pathogene Variante vor?":"Is there a constitutional pathogenic variant?","Welche Farbe hat der Report?":"What color is the report?","Reicht das Alter allein als Keimbahntest?":"Is age alone sufficient for germline testing?","Therapie und Prädisposition sind gekoppelt, aber nicht identisch.":"Treatment and predisposition are linked but not identical.","Wie wird die Keimbahnfrage belastbar geklärt?":"How can the germline question be resolved reliably?","Analyse geeigneten konstitutionellen Materials im passenden genetischen Prozess.":"Analyze appropriate constitutional material within the appropriate genetic pathway.","Nur VAF erneut ansehen.":"Just look at the VAF again.","Nur denselben Tumor erneut sequenzieren.":"Just sequence the same tumor again.","Gar nicht; Tumor-only reicht.":"Do nothing; tumor-only is sufficient.","Die Herkunft braucht konstitutionellen Vergleich/Bestätigung.":"Origin requires constitutional comparison/confirmation.","Die Variante wird im Blut bestätigt. Was ändert sich?":"The variant is confirmed in blood. What changes?","Zusätzlich zur Tumorrelevanz ist nun eine Keimbahnmutation bestätigt und hereditäre Konsequenzen können adressiert werden.":"In addition to tumor relevance, a germline mutation is now confirmed and hereditary implications can be addressed.","Die Tumorrelevanz verschwindet.":"The tumor relevance disappears.","Der Tumorbefund war falsch.":"The tumor finding was wrong.","Es gibt keinerlei zusätzliche Konsequenz.":"There are no additional consequences.","Die bestätigte Herkunft ergänzt den Tumorbefund um eine zweite klinische Dimension.":"Confirmed origin adds a second clinical dimension to the tumor finding.","Formulieren Sie Tumor- und Keimbahnaussage getrennt und definieren Sie den nächsten diagnostischen Schritt.":"Formulate the tumor and germline statements separately and define the next diagnostic step.","Pathogene BRCA2-Variante im Tumor als tumorbezogenen Biomarker einordnen.":"Interpret the pathogenic BRCA2 variant in the tumor as a tumor biomarker.","VAF und Familienanamnese als Keimbahnverdacht, nicht Beweis, kommunizieren.":"Communicate VAF and family history as evidence of germline suspicion, not proof.","Konstitutionelle Testung/genetische Beratung veranlassen.":"Arrange constitutional testing/genetic counseling.","Nach Bestätigung hereditäre Ebene getrennt dokumentieren.":"After confirmation, document the hereditary level separately.","Je nach lokaler Struktur kann eine direkte Überweisung zur Humangenetik statt tumor-normal Analyse im selben Labor sinnvoll sein.":"Depending on local structure, direct referral to genetics rather than tumor-normal analysis in the same laboratory may be appropriate.","48 % = Keimbahn":"48% = germline","VAF im Tumor hängt von Reinheit, LOH und Copy-number ab.":"Tumor VAF depends on purity, LOH, and copy number.","Nur Therapie, Keimbahn ignorieren":"Treatment only, ignore germline","Verpasst potenziell relevante Prädispositionsinformation.":"Misses potentially relevant predisposition information.","Nur Keimbahn diskutieren":"Discuss germline only","Ignoriert die unmittelbare tumorbezogene Bedeutung.":"Ignores the immediate tumor-directed relevance.","Der Verdacht bestätigt sich – aber erst im richtigen Material":"The suspicion is confirmed—but only in the right material","Die BRCA2-Variante wird im konstitutionellen Material bestätigt.":"The BRCA2 variant is confirmed in constitutional material.","Der Fall zeigt den Unterschied zwischen einem starken Hinweis aus Tumor-only NGS und einem echten Keimbahnnachweis.":"The case demonstrates the difference between a strong clue from tumor-only NGS and true germline confirmation.","Tumorrelevanz genutzt, Keimbahn separat bestätigt.":"Tumor relevance used, germline status confirmed separately.","Vollständige Präzisionsonkologie plus Prädispositionslogik.":"Complete precision oncology plus predisposition logic.","Keimbahn aus 48 % behauptet":"Germline origin claimed from 48%","Herkunft ohne Normalprobe overcallt.":"Origin overcalled without a normal sample.","Methodisch unzulässig.":"Methodologically invalid.","Keimbahnverdacht ignoriert":"Germline suspicion ignored","Hereditäre Ebene bleibt ungeklärt.":"The hereditary dimension remains unresolved.","Unvollständige Nachsorge.":"Incomplete follow-up.","pathogene Variante in Prädispositionsgen im Tumor-only Kontext":"pathogenic variant in a predisposition gene in a tumor-only context","Keimbahnpotenzial bewerten und ggf. Bestätigung/Genetik veranlassen":"assess germline potential and arrange confirmation/genetics when appropriate","Tumorbefund nicht als konstitutionellen Befund etikettieren.":"Do not label the tumor finding as a constitutional finding.","Tumor-only ist keine Keimbahndiagnostik.":"Tumor-only is not germline diagnostics.","VAF ist ein Hinweis, kein Beweis.":"VAF is a clue, not proof.","Dasselbe Variantenergebnis kann therapeutische und hereditäre Konsequenzen parallel haben.":"The same variant result can have therapeutic and hereditary consequences in parallel.","Pathogene BRCA2-Variante im Tumor therapeutisch relevant; Keimbahnherkunft aus Tumor-only/VAF nicht beweisbar. Bestätigende konstitutionelle Diagnostik ist indiziert und zeigt hier eine Keimbahnmutation.":"Pathogenic BRCA2 variant in the tumor is therapeutically relevant; germline origin cannot be proven from tumor-only/VAF. Confirmatory constitutional testing is indicated and, in this case, demonstrates a germline mutation.","Tumor-only-Grenzen":"Tumor-only limitations","VAF-Interpretation":"VAF interpretation","Keimbahnworkflow":"Germline workflow","Welche Gene lösen besonders häufig Keimbahn-Reflexfragen aus?":"Which genes most often trigger germline reflex questions?","Wie beeinflusst LOH die Tumor-VAF?":"How does LOH affect tumor VAF?","Wie formuliert man Keimbahnverdacht im Tumorbericht?":"How should suspected germline origin be phrased in a tumor report?","Twist: 48 % ist Hinweis, kein Beweis":"Twist: 48% is a clue, not proof","Tumor- und Keimbahnkonsequenz getrennt":"Separate tumor and germline consequences","Referenzpfad: Tumoractionability → Keimbahnverdacht → konstitutionelle Bestätigung":"Reference pathway: tumor actionability → germline suspicion → constitutional confirmation","ALK-IHC positiv, DNA-NGS negativ: die Fusion steckt im Transkript":"ALK IHC positive, DNA NGS negative: the fusion is in the transcript","DNA-NGS negativ, aber Fusionsverda…":"DNA NGS negative, but fusion suspicion remains…","Sarkomzentrum / Molekulares Tumorboard":"Sarcoma center / Molecular Tumor Board","34-jährige Patientin mit nicht vollständig resezierbarem inflammatorischem myofibroblastärem Tumor (IMT) im kleinen Becken. ALK-IHC diffus stark positiv, DNA-basiertes Panel meldet keine ALK-Fusion.":"34-year-old patient with incompletely resectable inflammatory myofibroblastic tumor (IMT) of the pelvis. ALK IHC is diffusely strong positive; a DNA-based panel reports no ALK fusion.","Ist die Fusionshypothese damit erledigt oder muss RNA-basiert/orthogonal weiter untersucht werden?":"Does that end the fusion hypothesis, or should RNA-based/orthogonal testing continue?","Die systemische Behandlungsstrategie soll im Sarkomboard festgelegt werden.":"The systemic treatment strategy is to be defined at the sarcoma board.","Spindelzelliger myofibroblastärer Tumor mit entzündlichem Hintergrund, passend zu IMT.":"Spindle-cell myofibroblastic tumor with inflammatory background, compatible with IMT.","ALK diffus zytoplasmatisch stark positiv.":"ALK diffusely strong cytoplasmic positive.","DNA-Panel":"DNA panel","Keine Fusion detektiert; Report weist darauf hin, dass nicht alle intronischen Breakpointregionen vollständig erfasst werden.":"No fusion detected; the report notes that not all intronic breakpoint regions are fully covered.","„Gen im Panel enthalten“ wird mit „jede mögliche Fusion erfasst“ gleichgesetzt.":"‘Gene included in the panel’ is equated with ‘every possible fusion covered’.","IMT-morphologischer Kontext.":"IMT morphologic context.","ALK-IHC":"ALK IHC","stark positiv.":"strongly positive.","kein Fusionscall.":"no fusion call.","Ist ein exprimiertes ALK-Fusionstranskript nachweisbar?":"Is an expressed ALK fusion transcript detectable?","FFPE-Resektat, RNA-QC ausreichend.":"FFPE resection specimen, RNA QC adequate.","DNA-Limitation":"DNA limitation","Breakpoint kann außerhalb der erfassten intronischen Regionen liegen.":"The breakpoint may lie outside the captured intronic regions.","Gezieltes RNA-Fusionspanel und FISH verfügbar.":"Targeted RNA fusion panel and FISH are available.","Fusionsverdacht mit geeigneter Methode klären":"Clarify fusion suspicion with an appropriate method","RNA-basiertes Fusionspanel weist ein exprimiertes TPM3::ALK-Fusionstranskript nach.":"RNA-based fusion panel detects an expressed TPM3::ALK fusion transcript.","ALK-Break-apart-FISH ist positiv und stützt das Rearrangement, ohne den Fusionspartner auf Sequenzebene zu definieren.":"ALK break-apart FISH is positive and supports the rearrangement without defining the fusion partner at sequence level.","Breites DNA-Panel":"Broad DNA panel","Mehr DNA-Panelbreite garantiert keine vollständige Erfassung aller Fusionsbreakpoints; die relevante methodische Lücke bleibt.":"Greater DNA panel breadth does not guarantee full coverage of all fusion breakpoints; the relevant methodological gap remains.","Prätestwahrscheinlichkeit":"Pretest probability","Morphologie plus starke ALK-IHC machen einen Fusionsmechanismus plausibel.":"Morphology plus strong ALK IHC make a fusion mechanism plausible.","Ein negatives DNA-Fusionsergebnis ist nur so vollständig wie das Assaydesign der relevanten intronischen Regionen.":"A negative DNA fusion result is only as complete as the assay design for the relevant intronic regions.","Der negative DNA-Fusionscall schließt in diesem hochgradig verdächtigen Kontext ein ALK-Rearrangement nicht aus. RNA-NGS weist ein exprimiertes TPM3::ALK-Transkript nach; ALK-FISH bestätigt das Rearrangement orthogonal. Der Fall zeigt den komplementären Wert von RNA- und DNA-basierten Ansätzen.":"The negative DNA fusion call does not exclude an ALK rearrangement in this highly suspicious context. RNA NGS detects an expressed TPM3::ALK transcript; ALK FISH confirms the rearrangement orthogonally. The case demonstrates the complementary value of RNA- and DNA-based approaches.","Teilbefund: Bei hoher morphologisch-immunhistochemischer Prätestwahrscheinlichkeit ist ein negativer DNA-Fusionscall nicht automatisch abschließend.":"Partial result: With high morphologic/immunohistochemical pretest probability, a negative DNA fusion call is not automatically definitive.","Assaydesign/Breakpointabdeckung berücksichtigen":"Consider assay design/breakpoint coverage","RNA als direkte Ebene des exprimierten Fusionstranskripts einordnen":"Position RNA as the direct level of the expressed fusion transcript","FISH als orthogonalen Rearrangementnachweis einordnen":"Position FISH as orthogonal evidence of rearrangement","Falschaussage: ALK steht im DNA-Panel, daher sind alle ALK-Fusionen ausgeschlossen":"False statement: ALK is included in the DNA panel, therefore all ALK fusions are excluded","Optimale Lösung: Widerspruch zwischen starker Prätestwahrscheinlichkeit und negativem DNA-Fusionscall erkennen und mit RNA-basierter Fusionsdiagnostik bzw. FISH klären.":"Optimal solution: recognize the conflict between high pretest probability and a negative DNA fusion call, and resolve it with RNA-based fusion testing and/or FISH.","Fusion":"Fusion","ALK":"ALK","DNA negativ, Biologie positiv":"DNA negative, biology positive","Molekularpathologie / Fusionsdiagnostik / Sarkom-MTB":"Molecular Pathology / Fusion Diagnostics / Sarcoma MTB","Grenzen DNA-basierter Fusionsdetektion durch Breakpoint-/Intronabdeckung verstehen.":"Understand the limits of DNA-based fusion detection imposed by breakpoint/intron coverage.","RNA-NGS als komplementären Nachweis exprimierter Fusionstranskripte nutzen.":"Use RNA NGS as complementary evidence for expressed fusion transcripts.","Prätestwahrscheinlichkeit aus Morphologie/IHC in die Methodenauswahl integrieren.":"Integrate pretest probability from morphology/IHC into method selection.","FISH als orthogonalen Rearrangementnachweis mit begrenzter Partnerinformation einordnen.":"Interpret FISH as orthogonal evidence of rearrangement with limited partner information.","ALK ist immunhistochemisch leuchtend positiv, die Morphologie passt – und trotzdem sagt das DNA-Panel „keine Fusion“. Der Fall beginnt dort, wo ein Automat aufhören würde.":"ALK is brightly positive by IHC, the morphology fits—and yet the DNA panel says ‘no fusion’. The case begins where an automated system would stop.","34-jährige Patientin mit IMT. ALK-IHC und Morphologie sprechen stark für einen Fusionsmechanismus, das DNA-Panel bleibt negativ. Das Assaydesign deckt nicht alle möglichen intronischen Breakpoints ab.":"34-year-old patient with IMT. ALK IHC and morphology strongly support a fusion mechanism, but the DNA panel is negative. The assay design does not cover all possible intronic breakpoints.","Panelinhalt ≠ vollständige Fusionsabdeckung":"Panel content ≠ complete fusion coverage","Ein Gen kann im Panel sein, ohne dass jeder relevante intronische Breakpoint erfasst wird.":"A gene can be in the panel without every relevant intronic breakpoint being covered.","Assaydesign bestimmt Sensitivität.":"Assay design determines sensitivity.","RNA fragt nach dem Produkt":"RNA asks about the product","Ein RNA-Fusionsassay kann das tatsächlich exprimierte Chimärtranskript nachweisen.":"An RNA fusion assay can detect the actually expressed chimeric transcript.","RNA und DNA sind komplementär.":"RNA and DNA are complementary.","Prätestwahrscheinlichkeit zählt":"Pretest probability matters","Morphologie + ALK-IHC machen einen negativen DNA-Call unplausibel genug für Reflexdiagnostik.":"Morphology + ALK IHC make a negative DNA call implausible enough to justify reflex testing.","Diagnostik ist Bayes, nicht nur Softwareoutput.":"Diagnostics is Bayesian, not just software output.","IMT-kompatibel":"compatible with IMT","diffus stark positiv":"diffusely strong positive","kein Fusionscall; intronische Coverage limitiert":"no fusion call; intronic coverage limited","RNA-Qualität ausreichend.":"RNA quality adequate.","FISH verfügbar.":"FISH available.","Kein Bedarf für beliebige weitere DNA-Breite, wenn die offene Frage eine Fusion ist.":"No need for arbitrary additional DNA breadth when the open question is a fusion.","Wie ist der negative DNA-Fusionscall bei starker ALK-IHC und passender Morphologie zu bewerten?":"How should the negative DNA fusion call be interpreted with strong ALK IHC and compatible morphology?","Er schließt eine Fusion nicht sicher aus, wenn relevante Breakpoints vom Assay nicht vollständig erfasst werden.":"It does not safely exclude a fusion if relevant breakpoints are not fully covered by the assay.","ALK-Fusion ist sicher ausgeschlossen.":"ALK fusion is definitely excluded.","IHC ist damit automatisch falsch.":"IHC is therefore automatically wrong.","Es handelt sich um Keimbahn-ALK.":"This is germline ALK.","Fusionssensitivität hängt stark vom Assaydesign ab.":"Fusion sensitivity depends strongly on assay design.","Warum ist RNA-NGS hier besonders sinnvoll?":"Why is RNA NGS particularly useful here?","Es kann ein exprimiertes Fusionstranskript direkt erfassen und DNA-Breakpointgrenzen umgehen.":"It can directly capture an expressed fusion transcript and bypass DNA breakpoint limitations.","Es ist exakt derselbe Test wie DNA-NGS.":"It is exactly the same test as DNA NGS.","Es misst nur Proteinexpression.":"It measures only protein expression.","Es ist primär ein Copy-number-Test.":"It is primarily a copy-number test.","RNA liefert eine komplementäre Fusionsinformation.":"RNA provides complementary fusion information.","Was kann ein positiver ALK-Break-apart-FISH hier sinnvoll beitragen?":"What can a positive ALK break-apart FISH usefully add here?","Orthogonaler Nachweis eines ALK-Rearrangements, meist ohne genaue Partner-/Transkriptinformation.":"Orthogonal evidence of an ALK rearrangement, usually without exact partner/transcript information.","Immer vollständige Sequenz des Fusionspartners.":"Always the complete sequence of the fusion partner.","Quantitative RNA-Expression.":"Quantitative RNA expression.","Keimbahnstatus.":"Germline status.","FISH ist schnell und orthogonal, aber informationsärmer als sequenzbasierte Partnerbestimmung.":"FISH is fast and orthogonal but provides less information than sequence-based partner identification.","RNA-NGS zeigt TPM3::ALK. Was erklärt die DNA/RNA-Diskrepanz am besten?":"RNA NGS shows TPM3::ALK. What best explains the DNA/RNA discrepancy?","Das DNA-Assaydesign hat den relevanten Breakpoint nicht zuverlässig abgedeckt; RNA erfasst das exprimierte Transkript.":"The DNA assay design did not reliably cover the relevant breakpoint; RNA captures the expressed transcript.","RNA muss falsch sein, weil DNA negativ war.":"RNA must be wrong because DNA was negative.","Die Histologie ist damit irrelevant.":"Histology is therefore irrelevant.","Beide Tests sind negativ.":"Both tests are negative.","Komplementäre Assaygrenzen erklären die Diskrepanz.":"Complementary assay limitations explain the discrepancy.","Entscheiden Sie, ob und wie der Fusionsverdacht nach negativem DNA-NGS weiter abgeklärt wird.":"Decide whether and how to further investigate fusion suspicion after negative DNA NGS.","Prätestwahrscheinlichkeit aus Morphologie/IHC festhalten.":"Record pretest probability from morphology/IHC.","DNA-Assaydesign und intronische Abdeckung prüfen.":"Review DNA assay design and intronic coverage.","RNA-basierte Fusionsdiagnostik ergänzen.":"Add RNA-based fusion testing.","FISH bei Bedarf orthogonal oder schnell ergänzen.":"Add FISH orthogonally or rapidly when needed.","Endbefund als integrierte Fusionsevidenz formulieren.":"Formulate the final report as integrated fusion evidence.","Bei nicht verwertbarer RNA kann FISH eine praktikable orthogonale Alternative sein; für Partner-/Transkriptinformation bleibt sequenzbasierte Diagnostik überlegen.":"If RNA is not evaluable, FISH can be a practical orthogonal alternative; sequence-based testing remains superior for partner/transcript information.","DNA negativ = Fusion ausgeschlossen":"DNA negative = fusion excluded","Ignoriert intronische Assaygrenzen.":"Ignores intronic assay limitations.","Nur IHC als endgültiger Fusionsnachweis":"IHC only as definitive fusion evidence","Proteinexpression ist kontextabhängig und nicht identisch mit Sequenznachweis.":"Protein expression is context-dependent and not identical to sequence evidence.","Beliebig größeres DNA-Panel":"Arbitrarily larger DNA panel","Mehr Gene lösen nicht zwingend das Breakpointproblem.":"More genes do not necessarily solve the breakpoint problem.","Die Fusion war die ganze Zeit exprimiert":"The fusion was expressed all along","RNA-NGS weist TPM3::ALK nach; FISH bestätigt das ALK-Rearrangement.":"RNA NGS detects TPM3::ALK; FISH confirms the ALK rearrangement.","Der negative DNA-Call war methodisch begrenzt, nicht biologisch endgültig.":"The negative DNA call was methodologically limited, not biologically definitive.","Komplementär getestet":"Complementary testing performed","RNA weist exprimierte Fusion nach, FISH stützt Rearrangement.":"RNA detects the expressed fusion, FISH supports the rearrangement.","Methodengerechte Auflösung der Diskrepanz.":"Method-appropriate resolution of the discrepancy.","Nach DNA-NGS beendet":"Stopped after DNA NGS","Relevante Fusion bleibt unentdeckt.":"Relevant fusion remains undetected.","Falsch-negatives Methodensilo.":"False-negative method silo.","Nur IHC akzeptiert":"IHC only accepted","Fusionsmechanismus nicht molekular geklärt.":"Fusion mechanism not molecularly resolved.","Unvollständige Charakterisierung.":"Incomplete characterization.","hohe Fusionsprätestwahrscheinlichkeit + nichtinformativer/negativer DNA-Call":"high fusion pretest probability + non-informative/negative DNA call","RNA-Fusionsdiagnostik und/oder orthogonalen Assay ergänzen":"add RNA fusion testing and/or an orthogonal assay","Negativer DNA-Call nicht als universellen Ausschluss formulieren.":"Do not phrase a negative DNA call as a universal exclusion.","DNA- und RNA-Fusionsdiagnostik sind komplementär.":"DNA- and RNA-based fusion diagnostics are complementary.","Assaydesign ist Teil der Befundinterpretation.":"Assay design is part of report interpretation.","Prätestwahrscheinlichkeit entscheidet, wann ein negativer Test nicht das Ende ist.":"Pretest probability determines when a negative test is not the end.","Trotz negativem DNA-NGS bleibt der Fusionsverdacht hoch; RNA-NGS weist TPM3::ALK nach, FISH bestätigt das Rearrangement. DNA-Negativität war durch die Breakpointabdeckung limitiert.":"Despite negative DNA NGS, fusion suspicion remains high; RNA NGS detects TPM3::ALK and FISH confirms the rearrangement. DNA negativity was limited by breakpoint coverage.","Fusionsmethodik":"Fusion methodology","Assaygrenzen":"Assay limitations","Wann ist FISH schneller als RNA-NGS?":"When is FISH faster than RNA NGS?","Welche RNA-QC ist für FFPE kritisch?":"Which RNA QC parameters are critical for FFPE?","Wie sollte ein negativer DNA-Fusionsbericht Limitationen nennen?":"How should a negative DNA fusion report state its limitations?","Twist: DNA-negativ trotz echter Fusion":"Twist: DNA negative despite a true fusion","RNA als komplementäre Ebene":"RNA as a complementary layer","Referenzpfad: Prätestwahrscheinlichkeit → Assaydesign → RNA/FISH":"Reference pathway: pretest probability → assay design → RNA/FISH","Liquid Biopsy negativ bei Progress: kein ctDNA-Signal ist kein Tumor-Wildtyp":"Negative liquid biopsy at progression: no ctDNA signal is not the same as tumor wild type","Liquid Biopsy negativ bei Progress":"Negative liquid biopsy at progression","66-jähriger Patient mit EGFR-mutiertem NSCLC und radiologischem Progress nach längerer Krankheitskontrolle. Plasma-NGS meldet „keine tumorassoziierte Variante nachweisbar“.":"66-year-old patient with EGFR-mutant NSCLC and radiologic progression after prolonged disease control. Plasma NGS reports ‘no tumor-associated variant detected’.","Darf das als fehlender Resistenzmechanismus interpretiert werden oder ist die Probe schlicht nicht informativ?":"Can this be interpreted as absence of a resistance mechanism, or is the sample simply non-informative?","Therapieumstellung soll im nächsten MTB erfolgen.":"Treatment modification is to be decided at the next MTB.","Neue Leberläsion und progrediente mediastinale Lymphknoten.":"New liver lesion and progressive mediastinal lymph nodes.","Plasma":"Plasma","Keine bekannte klonale EGFR-Mutation detektierbar; Tumorfraktionsschätzer sehr niedrig/nicht informativ.":"Known clonal EGFR mutation not detectable; tumor-fraction estimate very low/non-informative.","Ein negativer Plasma-Report wird wie ein negativer Tumorbefund gelesen.":"A negative plasma report is read like a negative tumor result.","Informative von nichtinformativer Negativität unterscheiden.":"Distinguish informative from non-informative negativity.","Vorbekannter Tumor":"Known tumor","EGFR-aktivierende Mutation im ursprünglichen Tumor.":"Activating EGFR mutation in the original tumor.","Plasma jetzt":"Plasma now","Weder der bekannte Treiber noch neue Resistenzalterationen detektierbar.":"Neither the known driver nor new resistance alterations are detectable.","Fehlt biologisch ein Resistenzmechanismus oder fehlt im Plasma ausreichend ctDNA?":"Is a resistance mechanism biologically absent, or is there simply insufficient ctDNA in plasma?","Wenn selbst der bekannte Tumormarker nicht erscheint, ist die Negativaussage besonders fragil.":"If even the known tumor marker is absent, the negative statement is especially fragile.","Plasma technisch korrekt gewonnen.":"Plasma collected correctly from a technical standpoint.","ctDNA":"ctDNA","sehr niedrige Tumorfraktion.":"very low tumor fraction.","Rebiopsie":"Rebiopsy","Leberläsion bildgesteuert zugänglich.":"Liver lesion accessible for image-guided biopsy.","Tissue-Rebiopsie und Gewebeprofil möglich.":"Tissue rebiopsy and tissue profiling are possible.","Liquid-Biopsy-Informativität bewerten":"Assess liquid-biopsy informativeness","Nichtinformatives Plasma durch Tumorgewebe klären":"Clarify non-informative plasma using tumor tissue","Liquid Biopsy":"Liquid biopsy","Keine tumorassoziierte Variante nachweisbar; selbst der bekannte klonale EGFR-Treiber fehlt. Tumorfraktion sehr niedrig – negatives Ergebnis ist nicht als Tumor-Wildtyp interpretierbar.":"No tumor-associated variant detected; even the known clonal EGFR driver is absent. Tumor fraction is very low—the negative result cannot be interpreted as tumor wild type.","Tissue-Rebiopsie":"Tissue rebiopsy","Rebiopsie der progredienten Lebermetastase bestätigt Tumor und liefert ausreichend DNA für Gewebeprofiling.":"Rebiopsy of the progressive liver metastasis confirms tumor and provides sufficient DNA for tissue profiling.","Gewebeprofil":"Tissue profile","Im Progressionsgewebe bleibt der EGFR-Treiber nachweisbar; zusätzlich zeigt sich eine relevante MET-Amplifikation als Resistenzmechanismus.":"The EGFR driver remains detectable in progression tissue; a relevant MET amplification additionally appears as a resistance mechanism.","Plasma-QC":"Plasma QC","Technisch valide Probe, biologisch jedoch mit sehr niedriger/nicht informativer Tumorfraktion.":"Technically valid sample, but biologically with very low/non-informative tumor fraction.","Ein nichtinformatives negatives ctDNA-Ergebnis darf einen Tumorbefund nicht ersetzen.":"A non-informative negative ctDNA result must not replace a tumor result.","Die negative Liquid Biopsy ist wegen sehr niedriger Tumorfraktion und fehlendem Nachweis sogar des bekannten Treibers nicht informativ. Geweberebiopsie ist deshalb sinnvoll und zeigt im Progressionsgewebe weiterhin die EGFR-Alteration sowie eine MET-Amplifikation. „Plasma negativ“ war kein Beweis für fehlende Tumoralterationen.":"The negative liquid biopsy is non-informative because tumor fraction is very low and even the known driver is absent. Tissue rebiopsy is therefore appropriate and shows the EGFR alteration plus a MET amplification in progression tissue. ‘Plasma negative’ was not proof of absent tumor alterations.","Teilbefund: Eine negative Liquid Biopsy muss im Kontext von ctDNA/Tumorfraktion, Tumorbiologie und bekannten Markerbefunden interpretiert werden.":"Partial result: A negative liquid biopsy must be interpreted in the context of ctDNA/tumor fraction, tumor biology, and known marker findings.","Tumorfraktion/Shedding berücksichtigen":"Consider tumor fraction/shedding","Fehlen des bekannten Treibers als Warnsignal für Nichtinformativität":"Absence of the known driver as a warning sign of non-informativeness","bei klinischer Relevanz Gewebe-Reflex erwägen":"Consider tissue reflex testing when clinically relevant","Falschaussage: Plasma negativ = Tumor molekular negativ":"False statement: plasma negative = tumor molecularly negative","Optimale Lösung: negative Liquid Biopsy als möglicherweise nichtinformativ erkennen und bei zugänglichem Progressionsgewebe reflexartig tissue-basiert nachtesten.":"Optimal solution: recognize a negative liquid biopsy as potentially non-informative and reflex to tissue-based testing when accessible progression tissue is available.","Progress":"Progression","Negativ – aber ohne Tumorsignal":"Negative—but without tumor signal","Thoraxonkologie / Liquid Biopsy / MTB":"Thoracic Oncology / Liquid Biopsy / MTB","Negative ctDNA-Ergebnisse von informativen positiven Ergebnissen asymmetrisch interpretieren.":"Interpret negative ctDNA results asymmetrically relative to informative positive results.","Tumorfraktion/Shedding und Nachweis eines bekannten Tumormarkers berücksichtigen.":"Consider tumor fraction/shedding and detection of a known tumor marker.","Bei nichtinformativem Plasma und klinischer Relevanz Gewebetestung erwägen.":"Consider tissue testing when plasma is non-informative and the question is clinically relevant.","Plasma- und Tissue-Profiling als komplementäre Strategien verstehen.":"Understand plasma and tissue profiling as complementary strategies.","Der Plasma-Report ist leer. Nicht einmal die bekannte EGFR-Mutation taucht auf. Das kann heißen „Tumor ohne Alterationen“ – oder viel wahrscheinlicher: „zu wenig Tumor-DNA im Röhrchen, um etwas sicher auszuschließen“.":"The plasma report is empty. Not even the known EGFR mutation appears. That can mean ‘tumor without alterations’—or, much more likely, ‘too little tumor DNA in the tube to exclude anything reliably’.","66-jähriger Patient mit EGFR-mutiertem NSCLC im Progress. Plasma-NGS ist technisch valide, zeigt aber keine tumorassoziierten Varianten und eine sehr niedrige Tumorfraktion. Eine Leberläsion ist biopsierbar.":"66-year-old patient with EGFR-mutant NSCLC at progression. Plasma NGS is technically valid but shows no tumor-associated variants and a very low tumor fraction. A liver lesion can be biopsied.","Negativ ist asymmetrisch":"Negativity is asymmetric","Ein positiver validierter ctDNA-Befund kann sehr informativ sein; ein negativer Befund kann bei niedrigem Shedding falsch-negativ sein.":"A validated positive ctDNA result can be highly informative; a negative result can be false-negative when shedding is low.","Negativaussagen brauchen Informativitätskontext.":"Negative statements require an informativeness context.","Der bekannte Treiber als interne Plausibilität":"The known driver as internal plausibility check","Wenn die etablierte EGFR-Mutation nicht detektierbar ist, spricht das gegen ausreichend Tumorsignal.":"If the established EGFR mutation is not detectable, this argues against sufficient tumor signal.","Vorwissen hilft, die Probe zu interpretieren.":"Prior knowledge helps interpret the sample.","Tissue bleibt relevant":"Tissue remains relevant","Bei nichtinformativer ctDNA kann Gewebe einen Resistenzmechanismus sichtbar machen.":"When ctDNA is non-informative, tissue can reveal a resistance mechanism.","Liquid Biopsy ersetzt Gewebe nicht in jeder Situation.":"Liquid biopsy does not replace tissue in every situation.","EGFR-mutierter Primärtumor":"EGFR-mutant primary tumor","Plasma-NGS":"Plasma NGS","keine tumorassoziierte Variante":"no tumor-associated variant","Tumorfraktion":"Tumor fraction","sehr niedrig / nicht informativ":"very low / non-informative","Plasma technisch korrekt.":"Plasma technically adequate.","Progressionsgewebe zugänglich.":"Progression tissue accessible.","Copy-number-/Fusionserfassung kann zusätzlich von Assay und Tumorfraktion abhängen.":"Copy-number/fusion detection can additionally depend on assay and tumor fraction.","Wie ist eine negative ctDNA-Analyse bei sehr niedriger Tumorfraktion zu bewerten?":"How should a negative ctDNA analysis with very low tumor fraction be assessed?","Als potenziell nichtinformativ/falsch-negativ; Tumoralterationen sind damit nicht sicher ausgeschlossen.":"As potentially non-informative/false-negative; tumor alterations are not reliably excluded.","Der Tumor ist sicher wildtyp.":"The tumor is definitely wild type.","Es liegt sicher kein Tumor mehr vor.":"There is definitely no tumor left.","Nur Keimbahnvarianten sind möglich.":"Only germline variants are possible.","ctDNA-Sensitivität hängt vom Tumorshedding und der Tumorfraktion ab.":"ctDNA sensitivity depends on tumor shedding and tumor fraction.","Warum ist das Fehlen der bekannten klonalen EGFR-Mutation besonders wichtig?":"Why is absence of the known clonal EGFR mutation particularly important?","Es ist ein Warnsignal, dass im Plasma möglicherweise kaum detektierbare Tumor-DNA vorliegt.":"It is a warning sign that there may be hardly any detectable tumor DNA in plasma.","Der Tumor muss EGFR sicher verloren haben.":"The tumor must definitely have lost EGFR.","Der gesamte Labortest ist technisch zwingend ungültig.":"The entire laboratory test is necessarily technically invalid.","Es ist ohne Bedeutung.":"It is irrelevant.","Der bekannte Marker dient als biologische Plausibilitätskontrolle.":"The known marker serves as a biological plausibility control.","Was ist bei zugänglichem Progressionsgewebe der sinnvollste nächste Schritt?":"What is the most appropriate next step when progression tissue is accessible?","Geweberebiopsie/Gewebeprofiling zur Resistenzklärung.":"Tissue rebiopsy/tissue profiling to clarify resistance.","Keine weitere Diagnostik.":"No further diagnostics.","Nur dasselbe Plasmaresultat erneut interpretieren.":"Only reinterpret the same plasma result.","Methylierungsarray.":"Methylation array.","Nichtinformative ctDNA sollte bei relevanter Frage durch Gewebe ergänzt werden.":"Non-informative ctDNA should be complemented by tissue when the question is clinically relevant.","Gewebe zeigt den bekannten EGFR-Treiber plus MET-Amplifikation. Was lehrt die Diskrepanz?":"Tissue shows the known EGFR driver plus MET amplification. What does the discrepancy teach?","Das negative Plasma war wegen geringer Tumorfraktion nicht ausreichend zum Ausschluss eines Resistenzmechanismus.":"The negative plasma result was insufficient to exclude a resistance mechanism because tumor fraction was low.","Das Gewebe muss falsch sein.":"The tissue must be wrong.","Liquid Biopsy ist grundsätzlich nutzlos.":"Liquid biopsy is generally useless.","Beide Befunde bedeuten dasselbe.":"Both findings mean the same thing.","Liquid Biopsy ist wertvoll, aber negative Ergebnisse sind kontextabhängig.":"Liquid biopsy is valuable, but negative results are context-dependent.","Entscheiden Sie, ob die negative Liquid Biopsy die Resistenzdiagnostik beendet oder eine Tissue-Reflexstrategie nötig ist.":"Decide whether the negative liquid biopsy ends resistance testing or requires a tissue-reflex strategy.","Plasma-QC und Tumorfraktion bewerten.":"Assess plasma QC and tumor fraction.","Bekannten Tumormarker als Plausibilitätsanker nutzen.":"Use the known tumor marker as a plausibility anchor.","Negativbefund nicht überinterpretieren.":"Do not overinterpret the negative result.","Bei zugänglichem Progressionsgewebe Gewebetestung ergänzen.":"Add tissue testing when progression tissue is accessible.","Diskrepanz integriert berichten.":"Report the discrepancy in an integrated manner.","Wenn Gewebe nicht zugänglich ist, kann eine erneute Plasmaanalyse zu einem biologisch günstigeren Zeitpunkt oder eine alternative Flüssigkeit je nach Entität erwogen werden; das ersetzt keine pauschale Garantie.":"If tissue is inaccessible, repeat plasma analysis at a biologically more favorable time or an alternative fluid may be considered depending on the entity; this is not a universal guarantee.","Plasma negativ = Tumor negativ":"Plasma negative = tumor negative","Ignoriert falsch-negative Ergebnisse bei niedrigem Shedding.":"Ignores false-negative results with low shedding.","Liquid Biopsy generell verwerfen":"Reject liquid biopsy altogether","Positive/informative Ergebnisse können klinisch sehr nützlich sein.":"Positive/informative results can be clinically very useful.","Tumorfraktion ignorieren":"Ignore tumor fraction","Entfernt den wichtigsten Informativitätsparameter.":"Removes the most important informativeness parameter.","Das Gewebe findet, was das Plasma nicht sehen konnte":"The tissue finds what plasma could not see","Tissue-Profiling zeigt den bekannten Treiber und eine MET-Amplifikation.":"Tissue profiling shows the known driver and a MET amplification.","Die diagnostische Frage war nicht „war der Plasmatest technisch okay?“, sondern „war er biologisch informativ genug, um etwas auszuschließen?“":"The diagnostic question was not ‘was the plasma test technically okay?’ but ‘was it biologically informative enough to exclude something?’","Nichtinformativ erkannt":"Non-informative result recognized","Tissue-Reflex deckt Resistenzmechanismus auf.":"Tissue reflex reveals a resistance mechanism.","Korrekte Liquid-Biopsy-Logik.":"Correct liquid-biopsy logic.","Nach negativem Plasma beendet":"Stopped after negative plasma","Resistenzmechanismus bleibt unentdeckt.":"Resistance mechanism remains undetected.","Falsch-negatives Overconfidence.":"False-negative overconfidence.","Liquid Biopsy generell abgelehnt":"Liquid biopsy rejected altogether","Methodennutzen wird unnötig negiert.":"Method usefulness is unnecessarily negated.","Zu pauschal.":"Too sweeping.","negatives ctDNA + niedrige Tumorfraktion/fehlender bekannter Treiber":"negative ctDNA + low tumor fraction/absent known driver","Ergebnis als nichtinformativ kennzeichnen und Gewebe erwägen":"label result as non-informative and consider tissue","Keine sichere Negativaussage über Tumorgenom.":"No reliable negative statement about the tumor genome.","Negative ctDNA-Befunde sind kontextabhängig.":"Negative ctDNA findings are context-dependent.","Tumorfraktion und Shedding gehören zur Interpretation.":"Tumor fraction and shedding belong in the interpretation.","Plasma und Gewebe ergänzen sich.":"Plasma and tissue complement each other.","Negative Liquid Biopsy bei sehr niedriger Tumorfraktion und fehlendem bekanntem Treiber ist nicht ausreichend zum Ausschluss von Resistenzalterationen; Gewebe-Reflex zeigt hier MET-Amplifikation.":"A negative liquid biopsy with very low tumor fraction and absent known driver is insufficient to exclude resistance alterations; tissue reflex reveals MET amplification in this case.","ctDNA-Informativität":"ctDNA informativeness","Reflex-Tissue":"Tissue reflex","Negativbefund":"Negative result","Welche Tumorlokalisationen sheddern schlecht?":"Which tumor sites shed poorly?","Wann ist Plasma besonders sinnvoll?":"When is plasma particularly useful?","Wie sollte Tumorfraktion im Report kommuniziert werden?":"How should tumor fraction be communicated in the report?","Twist: technisch negatives Plasma, biologisch nichtinformativ":"Twist: technically negative plasma, biologically non-informative","Bekannter Treiber als Plausibilitätsanker":"Known driver as plausibility anchor","Referenzpfad: Tumorfraktion → Negativität begrenzen → Tissue-Reflex":"Reference pathway: tumor fraction → limit negative interpretation → tissue reflex","NPM1-MRD: diagnostisches NGS negativ, gezielte PCR noch positiv":"NPM1 MRD: diagnostic NGS negative, targeted PCR still positive","qPCR/dPCR für MRD statt breites Pa…":"qPCR/dPCR for MRD instead of a broad panel…","Hämatologie / Molekulares Tumorboard":"Hematology / Molecular Tumor Board","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung in morphologischer kompletter Remission. Ein breites myeloisches NGS-Panel ist „negativ“.":"52-year-old patient with NPM1-mutated AML after consolidation in morphologic complete remission. A broad myeloid NGS panel is ‘negative’.","Reicht das breite Panel für die MRD-Beurteilung oder braucht es die hochsensitive, zielgerichtete NPM1-Methode?":"Is the broad panel sufficient for MRD assessment, or is the highly sensitive targeted NPM1 method required?","MRD-Status soll vor der nächsten risikoadaptierten Entscheidung vorliegen.":"MRD status is required before the next risk-adapted decision.","Diagnosemarker":"Diagnostic marker","NPM1-Mutation bei Erstdiagnose eindeutig dokumentiert.":"NPM1 mutation clearly documented at initial diagnosis.","<5 % Blasten, komplette morphologische Remission.":"<5% blasts, complete morphologic remission.","Breites NGS":"Broad NGS","Keine pathogene Variante oberhalb der diagnostischen Reporting-Grenzen.":"No pathogenic variant above diagnostic reporting thresholds.","Breite wird mit Sensitivität verwechselt.":"Breadth is confused with sensitivity.","morphologisch in Remission.":"in morphologic remission.","Zielmarker":"Target marker","NPM1 patientenspezifisch bekannt.":"Patient-specific NPM1 marker known.","Ist unterhalb der Sensitivität eines diagnostischen Panels noch messbare Resterkrankung nachweisbar?":"Can measurable residual disease still be detected below the sensitivity of a diagnostic panel?","MRD ist eine andere analytische Aufgabe als initiale Genotypisierung.":"MRD is a different analytical task from initial genotyping.","Knochenmark, ausreichende Nukleinsäurequalität.":"Bone marrow, nucleic-acid quality adequate.","bekannter NPM1-Marker.":"known NPM1 marker.","Methodenwahl":"Method selection","gezielte qPCR/dPCR-artige MRD-Methode vs. breites Panel.":"targeted qPCR/dPCR-like MRD method vs broad panel.","Beide technisch verfügbar; entscheidend ist die validierte Sensitivität für die Fragestellung.":"Both are technically available; the decisive factor is validated sensitivity for the clinical question.","Sensitive zielgerichtete MRD-Methode":"Sensitive targeted MRD method","Zielgerichtete MRD-PCR":"Targeted MRD PCR","Patientenspezifischer NPM1-Marker bleibt in niedriger Menge reproduzierbar positiv; messbare Resterkrankung ist trotz morphologischer Remission nachweisbar.":"The patient-specific NPM1 marker remains reproducibly positive at low level; measurable residual disease is detectable despite morphologic remission.","Breites myeloisches Panel":"Broad myeloid panel","Keine Variante oberhalb der diagnostischen Panelgrenzen; dieser Negativbefund erreicht nicht automatisch die für NPM1-MRD erforderliche Sensitivität.":"No variant above diagnostic panel thresholds; this negative result does not automatically reach the sensitivity required for NPM1 MRD.","Komplette morphologische Remission.":"Complete morphologic remission.","Diagnostische Panelbreite und MRD-Sensitivität sind unterschiedliche Leistungsmerkmale.":"Diagnostic panel breadth and MRD sensitivity are different performance characteristics.","Das negative diagnostische NGS-Panel beweist keine molekulare MRD-Negativität. Da ein geeigneter NPM1-Zielmarker bekannt ist, ist eine validierte hochsensitive zielgerichtete qPCR/dPCR-basierte Strategie angemessen. Diese bleibt niedrig positiv und zeigt messbare Resterkrankung trotz morphologischer Remission.":"A negative diagnostic NGS panel does not prove molecular MRD negativity. Because an appropriate NPM1 target marker is known, a validated highly sensitive targeted qPCR/dPCR-based strategy is appropriate. It remains low-level positive and demonstrates measurable residual disease despite morphologic remission.","Teilbefund: Für MRD muss die Methode zur erwarteten sehr niedrigen Krankheitslast und zum bekannten Zielmarker passen; ein breites Diagnostikpanel ist nicht automatisch sensitiv genug.":"Partial result: For MRD, the method must match the expected very low disease burden and the known target marker; a broad diagnostic panel is not automatically sensitive enough.","Diagnostik vs. MRD als unterschiedliche Testzwecke trennen":"Separate diagnostic testing from MRD as different test purposes","assayvalidierte Sensitivität berücksichtigen":"Consider assay-validated sensitivity","stabilen geeigneten Zielmarker nutzen":"Use a stable suitable target marker","Falschaussage: breiteres Panel ist für MRD automatisch besser":"False statement: a broader panel is automatically better for MRD","Optimale Lösung: bekannten NPM1-Marker mit validierter hochsensitiver Zielmethode verfolgen; diagnostisches NGS negativ nicht mit MRD-negativ gleichsetzen.":"Optimal solution: follow the known NPM1 marker with a validated highly sensitive targeted method; do not equate negative diagnostic NGS with MRD negative.","MRD":"MRD","NPM1":"NPM1","qPCR":"qPCR","dPCR":"dPCR","Breit negativ, hochsensitiv positiv":"Broadly negative, highly sensitive positive","Hämatologie / molekulare MRD-Diagnostik":"Hematology / molecular MRD diagnostics","Diagnostisches NGS von MRD-Methodik unterscheiden.":"Distinguish diagnostic NGS from MRD methodology.","Bei bekanntem geeignetem Marker eine validierte hochsensitive Zielmethode wählen.":"When a suitable known marker exists, choose a validated highly sensitive targeted method.","Analytische Sensitivität passend zur klinischen Fragestellung bewerten.":"Assess analytical sensitivity appropriate to the clinical question.","Morphologische Remission nicht mit molekularer MRD-Negativität gleichsetzen.":"Do not equate morphologic remission with molecular MRD negativity.","Im Abschlussbefund steht zweimal „negativ“: Morphologie unauffällig, breites NGS ohne Treffer. Die NPM1-MRD-PCR sagt trotzdem positiv. Der Widerspruch ist nur scheinbar – die Methoden fragen auf völlig unterschiedlichen Tiefen.":"The final report says ‘negative’ twice: morphology is unremarkable, broad NGS finds nothing. Yet the NPM1 MRD PCR is positive. The contradiction is only apparent—the methods interrogate disease at completely different depths.","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung. Morphologisch komplette Remission und diagnostisches Panel ohne Varianten oberhalb seiner Reporting-Grenzen. Für die MRD-Frage steht ein bekannter NPM1-Zielmarker zur Verfügung.":"52-year-old patient with NPM1-mutated AML after consolidation. Morphologic complete remission and a diagnostic panel without variants above its reporting thresholds. A known NPM1 target marker is available for the MRD question.","Breite ist nicht Tiefe":"Breadth is not depth","Ein diagnostisches Panel kann viele Gene erfassen, aber nicht dieselbe Nachweisgrenze wie eine fokussierte MRD-Methode erreichen.":"A diagnostic panel can cover many genes without reaching the same detection limit as a focused MRD method.","Methodenauswahl folgt der Frage.":"Method selection follows the question.","Bekannter Marker ist ein Vorteil":"A known marker is an advantage","NPM1 ist bei Diagnose dokumentiert und gezielt verfolgbar.":"NPM1 is documented at diagnosis and can be tracked specifically.","MRD kann patientenspezifisch hochsensitiv sein.":"MRD can be highly sensitive and patient-specific.","Remission hat Ebenen":"Remission has levels","Morphologische CR und molekulare MRD sind nicht synonym.":"Morphologic CR and molecular MRD are not synonymous.","Mehrere Ebenen der Krankheitslast koexistieren.":"Multiple levels of disease burden coexist.","NPM1-mutierte AML":"NPM1-mutated AML","komplette Remission":"complete remission","kein Call oberhalb diagnostischer Reporting-Grenze":"no call above diagnostic reporting threshold","Knochenmarkmaterial ausreichend.":"Bone marrow material adequate.","Zielmarker bekannt.":"Target marker known.","Die konkrete Nachweisgrenze ist labor- und assayvalidiert; keine universelle Prozentzahl wird vorausgesetzt.":"The exact detection limit is laboratory- and assay-validated; no universal percentage is assumed.","Welche Methode passt am besten zur MRD-Frage bei bekanntem NPM1-Zielmarker?":"Which method best fits the MRD question when a known NPM1 target marker is available?","Validierte hochsensitive zielgerichtete qPCR/dPCR-basierte MRD-Methode.":"Validated highly sensitive targeted qPCR/dPCR-based MRD method.","Nur ein möglichst breites diagnostisches Panel.":"Only the broadest possible diagnostic panel.","Nur HE-Morphologie.":"H&E morphology only.","MRD verlangt hohe Sensitivität für einen geeigneten Zielmarker.":"MRD requires high sensitivity for a suitable target marker.","Was bedeutet ein negatives diagnostisches NGS-Panel hier?":"What does a negative diagnostic NGS panel mean here?","Keine Variante oberhalb seiner validierten Grenzen; molekulare MRD unterhalb dieser Grenzen kann bestehen.":"No variant above its validated limits; molecular MRD below those limits may still exist.","Absolut keine Leukämiezelle vorhanden.":"Absolutely no leukemia cell is present.","MRD ist sicher negativ, unabhängig vom Assay.":"MRD is definitely negative regardless of assay.","Die ursprüngliche AML-Diagnose war falsch.":"The original AML diagnosis was wrong.","Negativität gilt nur innerhalb der analytischen Leistungsfähigkeit.":"Negativity applies only within analytical performance limits.","Morphologische komplette Remission und MRD-positiv – ist das möglich?":"Morphologic complete remission and MRD positive—is that possible?","Ja; MRD-Methoden erfassen deutlich niedrigere Krankheitslast als Morphologie.":"Yes; MRD methods detect much lower disease burden than morphology.","Nein, die Befunde schließen sich aus.":"No, the findings are mutually exclusive.","MRD ist immer Artefakt.":"MRD is always an artifact.","MRD hat keine klinische Bedeutung.":"MRD has no clinical significance.","Die Ebenen messen unterschiedliche Sensitivitätsbereiche.":"The levels measure different sensitivity ranges.","Die NPM1-MRD-Methode ist reproduzierbar niedrig positiv. Wie lautet die Kernaussage?":"The NPM1 MRD method is reproducibly low positive. What is the core statement?","Molekulare MRD ist nachweisbar, obwohl Morphologie und diagnostisches Panel negativ sind.":"Molecular MRD is detectable even though morphology and diagnostic panel are negative.","Das breite Panel überschreibt die MRD-PCR.":"The broad panel overrides the MRD PCR.","CR bedeutet zwingend null Resterkrankung.":"CR necessarily means zero residual disease.","Der Zielmarker darf nicht verwendet werden.":"The target marker must not be used.","Die gezielte validierte MRD-Methode ist für diese Frage geeigneter.":"The validated targeted MRD method is better suited to this question.","Wählen und begründen Sie die Methode zur molekularen MRD-Beurteilung.":"Select and justify the method for molecular MRD assessment.","Klinische Frage als MRD statt Diagnose definieren.":"Define the clinical question as MRD rather than diagnosis.","Geeigneten bekannten Zielmarker identifizieren.":"Identify an appropriate known target marker.","Assayvalidierte Sensitivität berücksichtigen.":"Consider assay-validated sensitivity.","Zielgerichtete MRD-PCR verwenden.":"Use targeted MRD PCR.","Ergebnis getrennt von Morphologie und diagnostischem Panel berichten.":"Report the result separately from morphology and the diagnostic panel.","NGS-basierte MRD kann in validierten spezialisierten Ansätzen sinnvoll sein; der Fall richtet sich gegen die unkritische Verwendung eines routinemäßigen diagnostischen Breitenpanels als MRD-Ersatz.":"NGS-based MRD can be useful in validated specialized approaches; the case argues against uncritical use of a routine broad diagnostic panel as a substitute for MRD testing.","Breiter = sensitiver":"Broader = more sensitive","Verwechselt Panelumfang mit Nachweisgrenze.":"Confuses panel scope with detection limit.","Morphologische CR = MRD-negativ":"Morphologic CR = MRD negative","Ignoriert unterschiedliche Sensitivitätsebenen.":"Ignores different sensitivity levels.","Jede Persistenzmutation als MRD":"Every persistent mutation as MRD","Nicht jeder Marker ist gleich geeignet; clonal hematopoiesis kann einzelne Gene persistieren lassen.":"Not every marker is equally suitable; clonal hematopoiesis can cause persistence of individual genes.","Die Resterkrankung liegt unter der Paneloberfläche":"Residual disease lies below the panel surface","Gezielte NPM1-MRD bleibt reproduzierbar positiv.":"Targeted NPM1 MRD remains reproducibly positive.","Der Fall zeigt, warum Testzweck und Sensitivität wichtiger sind als maximale Genbreite.":"The case shows why test purpose and sensitivity matter more than maximal gene breadth.","Zielgerichtete MRD":"Targeted MRD","NPM1-MRD korrekt nachgewiesen.":"NPM1 MRD correctly detected.","Fragestellungsgerechte Methodik.":"Question-appropriate methodology.","Nur breites Panel":"Broad panel only","Niedrige Resterkrankung wird fälschlich als negativ interpretiert.":"Low-level residual disease is falsely interpreted as negative.","Sensitivitätsproblem.":"Sensitivity problem.","Nur Morphologie":"Morphology only","Molekulare Resterkrankung bleibt unsichtbar.":"Molecular residual disease remains invisible.","Unvollständig.":"Incomplete.","bekannter geeigneter MRD-Marker":"known suitable MRD marker","validierte hochsensitive Zielmethode nutzen":"use a validated highly sensitive targeted method","Diagnostische Panelnegativität nicht als MRD-Negativität umdeuten.":"Do not reinterpret diagnostic panel negativity as MRD negativity.","MRD ist eine eigene analytische Aufgabe.":"MRD is its own analytical task.","Breite und Sensitivität sind unabhängige Dimensionen.":"Breadth and sensitivity are independent dimensions.","Der beste Test ist der, dessen validierte Leistung zur klinischen Frage passt.":"The best test is the one whose validated performance matches the clinical question.","Bei bekannter NPM1-mutierter AML ist die validierte zielgerichtete MRD-PCR der geeignete Test; diagnostisches NGS negativ schließt niedriggradige molekulare Resterkrankung nicht aus.":"In known NPM1-mutated AML, validated targeted MRD PCR is the appropriate test; negative diagnostic NGS does not exclude low-level molecular residual disease.","MRD-Methodenwahl":"MRD method selection","Sensitivität":"Sensitivity","Befundebenen":"Result levels","Welche Mutationen sind für AML-MRD problematisch?":"Which mutations are problematic for AML MRD?","Wann ist dPCR gegenüber qPCR sinnvoll?":"When is dPCR useful compared with qPCR?","Welche Rolle hat NGS-basierte MRD?":"What role does NGS-based MRD have?","Twist: diagnostisches NGS negativ, MRD-PCR positiv":"Twist: diagnostic NGS negative, MRD PCR positive","Breite ≠ Sensitivität":"Breadth ≠ sensitivity","Referenzpfad: Zielmarker → validierte MRD-Methode → getrennte Interpretation":"Reference pathway: target marker → validated MRD method → separate interpretation","MGMT-Frage im gesicherten Glioblastom: lokaler Marker statt Classifier-Overkill":"MGMT question in a confirmed glioblastoma: local marker instead of classifier overkill","Bisulfit-PCR vs. Methylierungsarra…":"Bisulfite PCR vs methylation arra…","69-jähriger Patient mit histologisch und molekular eindeutig klassifiziertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung wird der MGMT-Promotor-Methylierungsstatus benötigt.":"69-year-old patient with histologically and molecularly unequivocally classified glioblastoma, IDH wild type. MGMT promoter methylation status is required for treatment planning.","Braucht dieser Fall einen genomeweiten Methylierungsclassifier oder eine validierte zielgerichtete MGMT-Methylierungsanalyse?":"Does this case require a genome-wide methylation classifier or a validated targeted MGMT methylation assay?","Adjuvante Therapieplanung steht unmittelbar an.":"Adjuvant treatment planning is imminent.","Glioblastom, IDH-Wildtyp, integriert gesichert; keine offene Entitätsfrage.":"Glioblastoma, IDH wild type, integrated diagnosis established; no unresolved entity question.","Offene Biomarkerfrage":"Open biomarker question","MGMT-Promotor-Methylierung.":"MGMT promoter methylation.","Ein technologisch umfassenderes Methylierungsarray wird automatisch als „besser“ angesehen.":"A technologically more comprehensive methylation array is automatically regarded as ‘better’.","Testscope an die konkrete klinische Frage und lokale Validierung koppeln.":"Match test scope to the specific clinical question and local validation.","Hochgradiges diffuses Astrozytom mit Nekrosen und mikrovaskulärer Proliferation.":"High-grade diffuse astrocytoma with necrosis and microvascular proliferation.","IDH-Wildtyp; integrierte Diagnose steht.":"IDH wild type; integrated diagnosis established.","MGMT-Promotor-Methylierungsstatus.":"MGMT promoter methylation status.","Klassifikation und prädiktiver Einzelmarker sind zwei verschiedene Aufgaben.":"Classification and a predictive single biomarker are two different tasks.","FFPE-Resektat, ausreichender Tumoranteil.":"FFPE resection specimen, adequate tumor content.","für beide Verfahren ausreichend.":"sufficient for both methods.","Lokale Validierung":"Local validation","Bisulfit-basierte Zielmethode ist für MGMT klinisch validiert; das Array wird im Labor primär für CNS-Klassifikation eingesetzt.":"The bisulfite-based targeted method is clinically validated for MGMT; the array is used in this laboratory primarily for CNS classification.","Array wäre teurer/langsamer und beantwortet hier keine offene Klassifikationsfrage.":"The array would be more expensive/slower and would not answer any unresolved classification question here.","Zielgerichtete validierte MGMT-Methylierungsanalyse":"Targeted validated MGMT methylation analysis","Zielgerichtete Bisulfit-Methylierungsanalyse":"Targeted bisulfite methylation analysis","MGMT-Promotor-Methylierung ist mit der lokal validierten zielgerichteten Methode nachweisbar und für die konkrete prädiktive Fragestellung berichtbar.":"MGMT promoter methylation is detectable with the locally validated targeted method and can be reported for the specific predictive question.","CNS-Methylierungsclassifier":"CNS methylation classifier","Das genomeweite Profil bestätigt die bereits gesicherte Tumorklasse, ist in diesem Labor aber nicht als Ersatz für die klinische MGMT-Einzelmarkerbestimmung validiert.":"The genome-wide profile confirms the already established tumor class, but in this laboratory it is not validated as a substitute for the clinical single-marker MGMT assay.","Zusätzliche Sequenzierungsbreite beantwortet die epigenetische MGMT-Frage nicht.":"Additional sequencing breadth does not answer the epigenetic MGMT question.","Tumorentität bereits integriert gesichert.":"Tumor entity already established by integrated diagnosis.","Mehr Omik ist nicht automatisch die passendere Methode; Scope und Validierung müssen zur Frage passen.":"More omics is not automatically the more appropriate method; scope and validation must match the question.","Da die Tumorentität bereits sicher klassifiziert ist und die konkrete Frage MGMT-Promotor-Methylierung lautet, ist die lokal validierte zielgerichtete Bisulfitmethode die passende Untersuchung. Ein genomeweiter Methylierungsclassifier wäre für eine offene Entitätsfrage sinnvoll, ist hier aber unnötig und im lokalen Workflow kein validierter Ersatz für den prädiktiven Einzelmarker.":"Because the tumor entity is already securely classified and the specific question is MGMT promoter methylation, the locally validated targeted bisulfite method is the appropriate test. A genome-wide methylation classifier would be useful for an unresolved entity question, but is unnecessary here and is not a validated substitute for the predictive single biomarker in the local workflow.","Teilbefund: Lokaler prädiktiver Marker und globale epigenetische Klassifikation sind unterschiedliche diagnostische Aufgaben.":"Partial result: A local predictive biomarker and global epigenetic classification are different diagnostic tasks.","Fragestellung vor Technologie wählen":"Choose the clinical question before the technology","lokale klinische Validierung berücksichtigen":"take local clinical validation into account","Classifier für Klassifikation, nicht automatisch für jeden Methylierungsmarker":"classifier for classification, not automatically for every methylation biomarker","Falschaussage: genomeweit ist immer klinisch besser":"Incorrect statement: genome-wide is always clinically better","Optimale Lösung: gesicherte Diagnose respektieren und die offene MGMT-Frage mit der dafür validierten zielgerichteten Methylierungsmethode beantworten.":"Optimal solution: respect the established diagnosis and answer the open MGMT question with the targeted methylation method validated for that purpose.","MGMT":"MGMT","Bisulfit":"Bisulfite","CNS":"CNS","Nicht jedes Methylom braucht ein Methylom":"Not every methylation question needs a methylome","Neuropathologie / Methodenauswahl":"Neuropathology / method selection","Zielgerichtete Methylierungsanalyse von genomeweiter Klassifikation unterscheiden.":"Distinguish targeted methylation analysis from genome-wide classification.","Methodenumfang nicht mit klinischer Eignung gleichsetzen.":"Do not equate methodological breadth with clinical suitability.","Lokale Validierung und Intended Use in die Auswahl integrieren.":"Integrate local validation and intended use into test selection.","Bei bereits gesicherter Entität unnötige Classifier-Diagnostik vermeiden.":"Avoid unnecessary classifier diagnostics when the entity is already established.","Die Diagnose steht. Die einzige offene Frage lautet MGMT. Trotzdem liegt im Warenkorb ein genomeweites Methylierungsarray – weil „mehr Daten“ intuitiv nach „mehr Sicherheit“ klingt.":"The diagnosis is established. The only open question is MGMT. Nevertheless, a genome-wide methylation array is in the cart—because ‘more data’ intuitively sounds like ‘more certainty’.","69-jähriger Patient mit integriert gesichertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung ist ausschließlich der MGMT-Promotor-Methylierungsstatus offen. Das Labor hat dafür eine validierte zielgerichtete Bisulfitmethode; der CNS-Classifier ist für Entitätsklassifikation validiert.":"69-year-old patient with an integrated confirmed glioblastoma, IDH wild type. Only MGMT promoter methylation status remains open for treatment planning. The laboratory has a validated targeted bisulfite method for this purpose; the CNS classifier is validated for entity classification.","Frage vor Plattform":"Question before platform","MGMT-Status ist eine fokale Biomarkerfrage, Tumorklassifikation eine globale Musterfrage.":"MGMT status is a focal biomarker question; tumor classification is a global pattern question.","Testscope muss die Fragestellung spiegeln.":"Test scope must reflect the question.","Validierung schlägt Prestige":"Validation beats prestige","Ein technisch komplexeres Verfahren ist nicht automatisch für jeden klinischen Output validiert.":"A technically more complex method is not automatically validated for every clinical output.","Intended Use ist Teil der Methode.":"Intended use is part of the method.","Materialökonomie":"Material economy","Unnötige Omik verbraucht Zeit, Geld und ggf. Material.":"Unnecessary omics consumes time, money and potentially material.","Effizienz ist diagnostische Qualität.":"Efficiency is diagnostic quality.","Entitätsdiagnose":"Entity diagnosis","bereits integriert gesichert":"already established by integrated diagnosis","Lokaler Workflow":"Local workflow","zielgerichtete Bisulfitmethode klinisch validiert":"targeted bisulfite method clinically validated","Ausreichendes Material.":"Adequate material.","Kein Klassifikationsproblem.":"No classification problem.","Das Array ist lokal nicht als direkter Ersatz für die MGMT-Einzelmarkerfreigabe validiert.":"The array is not locally validated as a direct substitute for the single-marker MGMT report.","Welche Methode passt zur isolierten MGMT-Frage bei bereits gesicherter Glioblastomdiagnose am besten?":"Which method best fits the isolated MGMT question when the glioblastoma diagnosis is already established?","Die dafür lokal validierte zielgerichtete Bisulfit-Methylierungsanalyse.":"The locally validated targeted bisulfite methylation assay.","Zwingend genomeweiter Classifier.":"Mandatory genome-wide classifier.","Breites DNA-NGS.":"Broad DNA NGS.","FISH.":"FISH.","Der klinische Output ist ein definierter lokaler Methylierungsmarker.":"The clinical output is a defined local methylation biomarker.","Wann wäre der CNS-Methylierungsclassifier besonders sinnvoll?":"When is the CNS methylation classifier particularly useful?","Bei diagnostisch unklarer Tumorentität, wenn ein genomeweites Muster die integrierte Klassifikation unterstützen kann.":"For a diagnostically unclear tumor entity, when a genome-wide pattern can support integrated classification.","Bei jedem MGMT-Auftrag unabhängig von Diagnose.":"For every MGMT request regardless of diagnosis.","Zur AML-MRD.":"For AML MRD.","Für Keimbahndiagnostik.":"For germline diagnostics.","Classifier und Einzelmarker haben unterschiedliche Intended Uses.":"Classifier and single biomarker have different intended uses.","Warum darf ein Array nicht automatisch den lokal validierten MGMT-Test ersetzen?":"Why should an array not automatically replace the locally validated MGMT test?","Weil klinische Freigabe die validierte Performance für genau diesen Output voraussetzt.":"Because clinical reporting requires validated performance for that exact output.","Weil Arrays grundsätzlich ungenau sind.":"Because arrays are inherently inaccurate.","Weil Arrays keine DNA messen.":"Because arrays do not measure DNA.","Weil Methylierungsarrays nie diagnostisch genutzt werden.":"Because methylation arrays are never used diagnostically.","Die Aussage richtet sich gegen ungeprüften Methodenwechsel, nicht gegen Arrays an sich.":"The point is to avoid an unvalidated method switch, not to reject arrays themselves.","Das Array bestätigt erwartungsgemäß die Tumorklasse, liefert aber keinen lokal validierten MGMT-Report. Was war der Fehler?":"The array confirms the expected tumor class but does not provide a locally validated MGMT report. What was the mistake?","Eine globale Klassifikationsplattform wurde für eine fokale prädiktive Frage eingesetzt, ohne passenden validierten Output.":"A global classification platform was used for a focal predictive question without an appropriate validated output.","Methylierungsclassifier sind grundsätzlich nutzlos.":"Methylation classifiers are fundamentally useless.","Es gibt keinen Unterschied.":"There is no difference.","Technische Information und klinisch validierter Output sind nicht identisch.":"Technical information and a clinically validated output are not identical.","Wählen Sie die Methylierungsmethode passend zur konkreten klinischen Frage.":"Choose the methylation method according to the specific clinical question.","Prüfen, ob die Tumorentität bereits gesichert ist.":"Check whether the tumor entity is already established.","Offene Frage als MGMT-Einzelmarker definieren.":"Define the open question as a single-marker MGMT question.","Lokal validierten Zielassay verwenden.":"Use the locally validated targeted assay.","Classifier nur bei echter globaler Klassifikationsfrage einsetzen.":"Use the classifier only when there is a genuine global classification question.","Intended Use im Befund transparent halten.":"Keep intended use transparent in the report.","Wenn ein Labor einen arraybasierten MGMT-Algorithmus spezifisch klinisch validiert hat, kann dieser lokal geeignet sein; der Fall lehrt Scope/Validierung, keine universelle Plattformhierarchie.":"If a laboratory has specifically clinically validated an array-based MGMT algorithm, it may be locally appropriate; this case teaches scope/validation, not a universal platform hierarchy.","Mehr Daten = besser":"More data = better","Ignoriert Fragestellung und Validierung.":"Ignores the clinical question and validation.","Classifier nie verwenden":"Never use a classifier","Bei unklaren CNS-Tumoren kann er sehr wertvoll sein.":"It can be very valuable in diagnostically unclear CNS tumors.","NGS für MGMT-Methylierung":"NGS for MGMT methylation","Sequenzvarianten beantworten die epigenetische Frage nicht.":"Sequence variants do not answer the epigenetic question.","Das teurere Ergebnis beantwortet die falsche Frage":"The more expensive result answers the wrong question","Der Classifier bestätigt nur die bereits bekannte Tumorklasse; die klinisch offene MGMT-Frage bleibt ohne lokal validierten Einzelmarkeroutput bestehen.":"The classifier only confirms the already known tumor class; the clinically open MGMT question remains unanswered without a locally validated single-marker output.","Der Fall verschiebt Methodenauswahl von Technologieprestige zu Intended Use.":"The case shifts method selection from technology prestige to intended use.","Zielmarker passend getestet":"Target marker tested appropriately","MGMT mit validierter Zielmethode berichtet.":"MGMT reported using the validated targeted method.","Effizient und klinisch passend.":"Efficient and clinically appropriate.","Classifier ohne offene Klassifikationsfrage":"Classifier without an open classification question","Mehr Daten, aber falscher primärer Output.":"More data, but the wrong primary output.","Scope-Mismatch.":"Scope mismatch.","Epigenetische Frage bleibt offen.":"Epigenetic question remains unresolved.","Methodenfehler.":"Method error.","isolierte validierte Einzelmarkerfrage":"isolated validated single-marker question","zielgerichteten validierten Assay bevorzugen":"prefer the validated targeted assay","globale Omik nur bei zusätzlicher passender Fragestellung.":"global omics only when there is an additional appropriate question.","Fragestellung bestimmt Methodenumfang.":"The clinical question determines methodological scope.","Methylierungsclassifier und lokaler Bisulfitassay sind nicht austauschbar.":"Methylation classifier and local bisulfite assay are not interchangeable.","Intended Use und lokale Validierung gehören zur klinischen Interpretation.":"Intended use and local validation are part of clinical interpretation.","Bei gesichertem Glioblastom und isolierter MGMT-Frage ist die lokal validierte zielgerichtete Methylierungsanalyse angemessen; ein Classifier ist kein automatischer Ersatz.":"With an established glioblastoma and an isolated MGMT question, the locally validated targeted methylation assay is appropriate; a classifier is not an automatic substitute.","Methodenscope":"Method scope","Validierung":"Validation","Methylierungsdiagnostik":"Methylation diagnostics","Wann ist ein CNS-Classifier wirklich diagnostisch entscheidend?":"When is a CNS classifier truly diagnostically decisive?","Wie validiert man einen MGMT-Assay?":"How do you validate an MGMT assay?","Wann kann ein Array mehrere Outputs klinisch tragen?":"When can an array support multiple clinical outputs?","Twist: globale Plattform beantwortet lokale Frage nicht automatisch":"Twist: a global platform does not automatically answer a local question","Intended Use vor Omikbreite":"Intended use before omics breadth","Referenzpfad: klinische Frage → validierter Output → Methode":"Reference pathway: clinical question → validated output → method","EWSR1-FISH positiv: schneller Rearrangementnachweis, aber noch keine Entität":"EWSR1 FISH positive: rapid rearrangement detection, but not yet an entity","Amplifikation/Fusion: FISH als sch…":"Amplification/fusion: FISH as a rapid add…","Sarkomzentrum / Referenzpathologie":"Sarcoma center / reference pathology","32-jährige Patientin mit einem tiefen Weichteiltumor am Fuß. Morphologisch monomorpher Tumor; EWSR1-Break-apart-FISH wird wegen Zeitdruck früh durchgeführt und ist positiv.":"32-year-old woman with a deep soft-tissue tumor of the foot. Morphology shows a monomorphic tumor; EWSR1 break-apart FISH is performed early because of time pressure and is positive.","Darf daraus unmittelbar „Ewing-Sarkom“ werden oder braucht es partner-/transkriptspezifische Auflösung?":"Can this immediately be called ‘Ewing sarcoma’, or is partner-/transcript-specific resolution required?","Neoadjuvante Strategie wird in wenigen Tagen diskutiert.":"The neoadjuvant strategy will be discussed within a few days.","Monomorphe Zellen, aber nicht klassisch genug für eine alleinige Ewing-Diagnose.":"Monomorphic cells, but not sufficiently classic for a standalone Ewing diagnosis.","EWSR1-Break-apart positiv.":"EWSR1 break-apart positive.","Ein Gen-Rearrangement wird mit einer bestimmten Tumorentität gleichgesetzt.":"A gene rearrangement is equated with a specific tumor entity.","FISH als schnellen, robusten, aber informationsbegrenzten Test einordnen.":"Classify FISH as a rapid, robust but information-limited test.","Melaninarm, nested/solid; immunhistochemischer Kontext nicht eindeutig für Ewing.":"Melanin-poor, nested/solid; immunohistochemical context not unequivocal for Ewing.","EWSR1 rearrangiert.":"EWSR1 rearranged.","Welcher Partner und welche Transkriptfusion liegt vor?":"Which partner and which transcript fusion is present?","EWSR1-Rearrangements kommen in mehreren Tumorentitäten vor.":"EWSR1 rearrangements occur in multiple tumor entities.","FFPE-Biopsie; RNA ausreichend.":"FFPE biopsy; RNA adequate.","schnell verfügbar und technisch robust.":"rapidly available and technically robust.","Targeted RNA-NGS verfügbar.":"Targeted RNA NGS available.","Partnerbestimmung kann die Entitätsdiagnose entscheidend verändern.":"Partner identification can decisively change the entity diagnosis.","Rearrangement schnell/orthogonal erfassen":"Detect rearrangement rapidly/orthogonally","Fusionspartner/Transkript klären":"Clarify fusion partner/transcript","Break-apart-FISH":"Break-apart FISH","EWSR1-Break-apart positiv: ein EWSR1-Rearrangement ist nachgewiesen, die Partneridentität und damit die genaue Entität sind dadurch nicht allein definiert.":"EWSR1 break-apart positive: an EWSR1 rearrangement is demonstrated, but partner identity and therefore the exact entity are not defined by this alone.","RNA-NGS weist EWSR1::ATF1 nach und unterstützt im passenden morphologisch-immunhistochemischen Kontext die Diagnose eines Clear-Cell-Sarkoms statt eines Ewing-Sarkoms.":"RNA NGS detects EWSR1::ATF1 and, in the appropriate morphologic-immunohistochemical context, supports a diagnosis of clear cell sarcoma rather than Ewing sarcoma.","Zusatzvarianten tragen weniger zur Kernfrage bei als die direkte Partnerbestimmung der Fusion.":"Additional variants contribute less to the core question than direct fusion-partner identification.","schneller Rearrangementnachweis, aber keine universelle Entitätsdefinition.":"rapid rearrangement detection, but no universal entity definition.","Gen-Rearrangement und Fusionspartner müssen im morphologischen Kontext interpretiert werden.":"Gene rearrangement and fusion partner must be interpreted in the morphologic context.","EWSR1-Break-apart-FISH ist ein sinnvoller schneller Nachweis eines Rearrangements, beweist aber nicht automatisch ein Ewing-Sarkom. Die RNA-basierte Partnerbestimmung zeigt EWSR1::ATF1 und verschiebt die integrierte Diagnose im passenden Kontext zu einem Clear-Cell-Sarkom. FISH bleibt wertvoll – aber seine Aussagegrenze muss respektiert werden.":"EWSR1 break-apart FISH is a useful rapid assay for detecting a rearrangement, but it does not automatically prove Ewing sarcoma. RNA-based partner identification reveals EWSR1::ATF1 and shifts the integrated diagnosis, in the appropriate context, toward clear cell sarcoma. FISH remains valuable—but its reporting limits must be respected.","Teilbefund: Ein positiver Break-apart-FISH beantwortet „ist das Gen rearrangiert?“, nicht immer „welche Fusion/Entität liegt vor?“.":"Partial result: A positive break-apart FISH answers ‘is the gene rearranged?’, not always ‘which fusion/entity is present?’","FISH-Stärke und -Grenze benennen":"State the strength and limitation of FISH","Partnerbestimmung bei entitätsrelevanter Frage ergänzen":"Add partner identification when it is relevant to entity diagnosis","Molekularbefund in Morphologie/IHC integrieren":"Integrate the molecular result with morphology/IHC","Falschaussage: EWSR1-FISH positiv = Ewing-Sarkom":"Incorrect statement: EWSR1 FISH positive = Ewing sarcoma","Optimale Lösung: FISH als schnellen Rearrangementnachweis nutzen, aber bei nicht entitätsspezifischem Genereignis den Partner mit RNA-NGS bestimmen und integriert diagnostizieren.":"Optimal solution: use FISH for rapid rearrangement detection, but when the gene event is not entity-specific, determine the partner by RNA NGS and establish an integrated diagnosis.","EWSR1":"EWSR1","Sarcoma":"Sarcoma","FISH positiv – Diagnose noch offen":"FISH positive – diagnosis still open","Sarkompathologie / FISH / RNA-Fusion":"Sarcoma pathology / FISH / RNA fusion","Break-apart-FISH als schnellen Rearrangementnachweis korrekt einordnen.":"Correctly position break-apart FISH as a rapid rearrangement assay.","Nicht entitätsspezifische Rearrangements nicht überinterpretieren.":"Do not overinterpret rearrangements that are not entity-specific.","RNA-NGS zur Partner-/Transkriptbestimmung nutzen.":"Use RNA NGS to identify partner/transcript.","Morphologie, IHC, FISH und RNA integriert bewerten.":"Integrate morphology, IHC, FISH and RNA.","Der FISH ist positiv. EWSR1 rearrangiert. Im ersten Moment klingt das wie die Diagnose – bis man sich erinnert, dass EWSR1 in mehreren völlig unterschiedlichen Tumoren rearrangiert sein kann.":"The FISH is positive. EWSR1 is rearranged. At first it sounds like the diagnosis—until you remember that EWSR1 can be rearranged in several completely different tumors.","32-jährige Patientin mit Weichteiltumor am Fuß. EWSR1-Break-apart-FISH ist positiv, die Morphologie aber nicht klassisch für Ewing. RNA ist ausreichend für Partnerbestimmung.":"32-year-old woman with a soft-tissue tumor of the foot. EWSR1 break-apart FISH is positive, but morphology is not classic for Ewing. RNA is adequate for partner identification.","FISH beantwortet eine enge Frage":"FISH answers a narrow question","Break-apart: Rearrangement ja/nein.":"Break-apart: rearrangement yes/no.","Partner und Transkript bleiben oft offen.":"Partner and transcript often remain unresolved.","Genereignis ist nicht immer entitätsspezifisch":"The gene event is not always entity-specific","EWSR1 kann verschiedene Fusionspartner und Tumorentitäten haben.":"EWSR1 can have different fusion partners and occur in different tumor entities.","Molekularer Befund braucht Kontext.":"A molecular result needs context.","RNA löst die Partnerfrage":"RNA resolves the partner question","Sequenzbasierter Transkriptnachweis kann die diagnostische Klasse entscheidend präzisieren.":"Sequence-based transcript detection can decisively refine the diagnostic class.","FISH und RNA konkurrieren nicht, sie ergänzen sich.":"FISH and RNA do not compete; they complement each other.","monomorph, aber nicht klassisch Ewing":"monomorphic, but not classic Ewing","EWSR1 break-apart positiv":"EWSR1 break-apart positive","Zeitdruck macht FISH attraktiv.":"Time pressure makes FISH attractive.","RNA-NGS ist innerhalb der diagnostischen Frist möglich.":"RNA NGS is feasible within the diagnostic timeframe.","Positives FISH darf nicht über seine validierte Zielaussage hinaus interpretiert werden.":"A positive FISH must not be interpreted beyond its validated target claim.","Was beweist ein positiver EWSR1-Break-apart-FISH primär?":"What does a positive EWSR1 break-apart FISH primarily prove?","Ein EWSR1-Rearrangement.":"An EWSR1 rearrangement.","Immer ein Ewing-Sarkom.":"Always Ewing sarcoma.","Immer den exakten Fusionspartner.":"Always the exact fusion partner.","Quantitative Proteinexpression.":"Quantitative protein expression.","Break-apart-FISH ist genbezogen, nicht zwingend partner- oder entitätsspezifisch.":"Break-apart FISH is gene-specific, not necessarily partner- or entity-specific.","Warum ist RNA-NGS bei atypischer Morphologie sinnvoll?":"Why is RNA NGS useful when morphology is atypical?","Zur Bestimmung des exprimierten Fusionspartners/Transkripts.":"To identify the expressed fusion partner/transcript.","Weil es exakt dasselbe wie FISH misst.":"Because it measures exactly the same thing as FISH.","Nur zur Copy-number-Bestimmung.":"Only for copy-number determination.","Nur für Keimbahn.":"Only for germline testing.","Die Partnerinformation kann die Diagnose präzisieren.":"Partner information can refine the diagnosis.","Wie sollte ein Fusionsbefund diagnostisch verwendet werden?":"How should a fusion result be used diagnostically?","Mit Morphologie, IHC und klinischem Kontext integrieren.":"Integrate it with morphology, IHC and clinical context.","Molekularer Befund ersetzt immer die Histologie.":"A molecular result always replaces histology.","Molekulare Befunde sind bei Sarkomen unwichtig.":"Molecular results are unimportant in sarcoma.","FISH entscheidet jede Entität allein.":"FISH determines every entity by itself.","Entitätsdiagnostik ist integriert.":"Entity diagnosis is integrated.","RNA zeigt EWSR1::ATF1. Was ändert sich?":"RNA shows EWSR1::ATF1. What changes?","Im passenden Kontext unterstützt dies Clear-Cell-Sarkom statt einer vorschnellen Ewing-Diagnose.":"In the appropriate context, this supports clear cell sarcoma instead of a premature Ewing diagnosis.","Es beweist weiterhin Ewing unabhängig vom Partner.":"It still proves Ewing regardless of the partner.","Der positive FISH war falsch.":"The positive FISH was wrong.","Partnerinformation ist bedeutungslos.":"Partner information is meaningless.","Die Partneridentität kann die Entitätszuordnung entscheidend verändern.":"Partner identity can decisively change entity assignment.","Nutzen Sie FISH dort, wo er stark ist, und definieren Sie, wann Partnerbestimmung erforderlich ist.":"Use FISH where it is strong and define when partner identification is required.","Morphologie und Prätestwahrscheinlichkeit erfassen.":"Assess morphology and pre-test probability.","FISH als schnellen Rearrangementnachweis verwenden.":"Use FISH as a rapid rearrangement assay.","Aussagegrenze explizit halten.":"Keep the reporting limit explicit.","Bei entitätsrelevanter Partnerfrage RNA-NGS ergänzen.":"Add RNA NGS when partner identity is relevant to the entity.","Integrierte Diagnose aus allen Ebenen formulieren.":"Formulate an integrated diagnosis from all levels.","Bei sehr charakteristischer Morphologie und entitätsspezifischem Rearrangement kann FISH ausreichend sein; das hängt von Gen, Tumorart und validiertem diagnostischem Kontext ab.":"With very characteristic morphology and an entity-specific rearrangement, FISH may be sufficient; this depends on the gene, tumor type and validated diagnostic context.","Break-apart = Partner bekannt":"Break-apart = partner known","FISH liefert diese Information häufig nicht.":"FISH often does not provide this information.","EWSR1 = Ewing":"EWSR1 = Ewing","EWSR1 ist nicht entitätsspezifisch.":"EWSR1 is not entity-specific.","FISH ist veraltet und nutzlos":"FISH is outdated and useless","FISH kann schnell, robust und materialeffizient sehr wertvoll sein.":"FISH can be fast, robust, material-efficient and very valuable.","Der Partner kippt die Diagnose":"The partner changes the diagnosis","RNA zeigt EWSR1::ATF1 statt einer Ewing-typischen Fusion.":"RNA shows EWSR1::ATF1 instead of an Ewing-typical fusion.","FISH war korrekt positiv, aber die überzogene Interpretation wäre falsch gewesen.":"FISH was correctly positive, but the overextended interpretation would have been wrong.","FISH + RNA integriert":"Integrated FISH + RNA","Rearrangement schnell erkannt, Partner korrekt bestimmt, Diagnose präzisiert.":"Rearrangement rapidly detected, partner correctly identified, diagnosis refined.","Stärken beider Methoden genutzt.":"Strengths of both methods used.","Ewing nur aus EWSR1-FISH":"Ewing based only on EWSR1 FISH","Entität falsch überinterpretiert.":"Entity overinterpreted incorrectly.","Scope-Fehler.":"Scope error.","FISH komplett verworfen":"FISH discarded completely","Schnelle robuste Information unnötig verloren.":"Rapid robust information unnecessarily lost.","positiver genbezogener FISH ohne entitätsspezifische Eindeutigkeit":"positive gene-based FISH without entity-specific unambiguity","Partner-/Transkriptbestimmung erwägen":"consider partner/transcript identification","Diagnose nicht allein aus Gen-Rearrangement ableiten.":"do not derive the diagnosis from the gene rearrangement alone.","FISH bleibt klinisch nützlich.":"FISH remains clinically useful.","Aussagegrenze ist Teil der Methode.":"The reporting limit is part of the method.","Partnerinformation kann diagnostisch wichtiger sein als der reine Gen-Rearrangementnachweis.":"Partner information may be diagnostically more important than detection of the gene rearrangement alone.","EWSR1-FISH bestätigt ein Rearrangement, aber keine automatische Ewing-Diagnose; RNA-NGS zeigt EWSR1::ATF1 und präzisiert die Entität im morphologischen Kontext.":"EWSR1 FISH confirms a rearrangement but does not automatically diagnose Ewing; RNA NGS shows EWSR1::ATF1 and refines the entity in the morphologic context.","FISH-Scope":"FISH scope","Partnerbestimmung":"Partner identification","integrierte Sarkomdiagnostik":"Integrated sarcoma diagnosis","Welche Break-apart-Sonden sind besonders entitätsspezifisch oder unspezifisch?":"Which break-apart probes are particularly entity-specific or nonspecific?","Wann ist FISH bei schlechter RNA die beste Option?":"When is FISH the best option with poor-quality RNA?","Wie formuliert man einen positiven FISH ohne Partner?":"How do you phrase a positive FISH result without a known partner?","Twist: FISH korrekt, Interpretation fast falsch":"Twist: FISH correct, interpretation almost wrong","Gen-Rearrangement ≠ Entität":"Gene rearrangement ≠ entity","Referenzpfad: FISH → Scope prüfen → RNA-Partner → integrieren":"Reference pathway: FISH → check scope → RNA partner → integrate","23 Seiten Multiomics: eine belastbare Kernaussage, viele Hypothesen":"23 pages of multiomics: one robust core message, many hypotheses","Multiomics-Bericht: viel Informati…":"Multiomics report: lots of informati…","Hepatobiliäres Tumorboard / Präzisionsonkologie":"Hepatobiliary tumor board / precision oncology","59-jährige Patientin mit metastasiertem intrahepatischem Cholangiokarzinom. Ein externer Multiomics-Bericht umfasst DNA, RNA, Immunmarker und Proteinsignaturen auf 23 Seiten.":"59-year-old woman with metastatic intrahepatic cholangiocarcinoma. An external 23-page multiomics report includes DNA, RNA, immune markers and protein signatures.","Welche Befunde sind unmittelbar klinisch belastbar, welche nur biologischer Kontext und welche reine Hypothese?":"Which findings are immediately clinically robust, which are only biological context, and which are pure hypotheses?","Das MTB hat sieben Minuten für die molekulare Kernaussage.":"The tumor board has seven minutes for the molecular core message.","Pathogene IDH1 p.R132C-Mutation; keine FGFR2-Fusion im validierten Fusionsassay.":"Pathogenic IDH1 p.R132C mutation; no FGFR2 fusion in the validated fusion assay.","FGFR2-Expression deutlich erhöht; mehrere Pathway-Scores für MAPK/EMT.":"FGFR2 expression markedly increased; several MAPK/EMT pathway scores.","Immunprofil":"Immune profile","MSS, niedrige TMB; PD-L1 niedrig.":"MSS, low TMB; low PD-L1.","Der visuell spektakulärste Omics-Score wird mit einem validierten prädiktiven Biomarker gleichgesetzt.":"The visually most striking omics score is equated with a validated predictive biomarker.","Intrahepatisches Cholangiokarzinom.":"Intrahepatic cholangiocarcinoma.","Molekulare Schlüsseldaten":"Key molecular data","IDH1 pathogen; keine FGFR2-Fusion.":"IDH1 pathogenic; no FGFR2 fusion.","Explorative Daten":"Exploratory data","FGFR2-high expression, EMT-/MET-Signaturen.":"FGFR2-high expression, EMT/MET signatures.","Was gehört in die erste Zeile des Tumorboards?":"What belongs in the first line of the tumor board summary?","Mehrere Omics-Layer bereits erzeugt.":"Multiple omics layers already generated.","Problem":"Problem","Nicht Datenmangel, sondern Evidenzpriorisierung.":"Not a lack of data, but prioritization of evidence.","Zeit":"Time","MTB-Kommunikation muss extrem komprimiert sein.":"Tumor-board communication must be extremely concise.","Keine weitere Messung nötig, bevor die vorhandenen Daten sauber hierarchisiert sind.":"No further testing is needed before the existing data are properly prioritized.","Multiomics-Evidenz priorisieren und verdichten":"Prioritize and condense multiomics evidence","Multiomics-Kernaussage":"Multiomics core message","Kernaussage: pathogene IDH1-Alteration als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. FGFR2-Überexpression sowie EMT/MET-Signaturen bleiben explorativ und dürfen nicht wie validierte prädiktive Targets kommuniziert werden.":"Core message: pathogenic IDH1 alteration as an established tumor-related biomarker; no FGFR2 fusion. FGFR2 overexpression and EMT/MET signatures remain exploratory and must not be communicated as validated predictive targets.","Noch breiteres Panel":"Even broader panel","Mehr Daten lösen die zentrale Aufgabe – Evidenzhierarchie und klare Kommunikation – nicht.":"More data do not solve the central task—evidence hierarchy and clear communication.","Informationsdichte":"Information density","Viele biologisch interessante Signale, aber nur wenige direkt handlungsleitende Befunde.":"Many biologically interesting signals, but only a few directly decision-guiding findings.","Multiomics braucht Evidenzhierarchie, nicht nur Datensynthese.":"Multiomics needs an evidence hierarchy, not just data synthesis.","Der Bericht wird auf eine belastbare klinische Kernaussage reduziert: pathogene IDH1-Veränderung als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression ist nicht gleichbedeutend mit einer FGFR2-Fusion, und EMT/MET-/Pathway-Signaturen bleiben ohne passende klinische Validierung explorativ. Das MTB erhält Evidenzstufen statt Datenrauschen.":"The report is reduced to a robust clinical core message: pathogenic IDH1 alteration as an established tumor-related biomarker; no FGFR2 fusion. High FGFR2 expression is not equivalent to an FGFR2 fusion, and EMT/MET/pathway signatures remain exploratory without appropriate clinical validation. The tumor board receives evidence levels instead of data noise.","Teilbefund: Multiomics ist nur dann klinisch nützlich, wenn validierte Biomarker, Kontextsignale und Hypothesen klar getrennt werden.":"Partial result: Multiomics is clinically useful only when validated biomarkers, contextual signals and hypotheses are clearly separated.","Befunde nach klinischer Evidenz ordnen":"Order findings by clinical evidence","Expression nicht mit Fusion gleichsetzen":"Do not equate expression with fusion","explorative Signaturen als Hypothesen kennzeichnen":"Label exploratory signatures as hypotheses","Falschaussage: stärkstes Heatmap-Signal = bestes Target":"Incorrect statement: strongest heatmap signal = best target","Optimale Lösung: aus vielen Daten eine kurze Evidenzhierarchie bauen – gesicherter Biomarker zuerst, relevante negative Befunde danach, explorative Omics klar als Hypothesen.":"Optimal solution: build a short evidence hierarchy from many data—established biomarker first, relevant negative findings next, exploratory omics clearly labeled as hypotheses.","Multiomics":"Multiomics","MTB-RES":"MTB-RES","23 Seiten auf drei Sätze reduzieren":"Reduce 23 pages to three sentences","Präzisionsonkologie / MTB-Kommunikation":"Precision oncology / tumor-board communication","Multiomics-Befunde nach klinischer Evidenz hierarchisieren.":"Hierarchize multiomics findings by clinical evidence.","Genomische Alteration, Expression und Pathway-Signatur nicht miteinander gleichsetzen.":"Do not equate genomic alteration, expression and pathway signature.","Relevante Negativbefunde sichtbar halten.":"Keep relevant negative findings visible.","Explorative Hypothesen klar von handlungsleitenden Biomarkern trennen.":"Clearly separate exploratory hypotheses from decision-guiding biomarkers.","Eine präzise MTB-Kernaussage aus Datenfülle formulieren.":"Formulate a precise tumor-board core message from a data-rich report.","Der Report ist 23 Seiten lang. Das Tumorboard hat sieben Minuten. Die Aufgabe ist nicht, alles vorzulesen – sondern zu wissen, welche zwei Sätze wirklich eine Entscheidung tragen.":"The report is 23 pages long. The tumor board has seven minutes. The task is not to read everything aloud—but to know which two sentences truly support a decision.","59-jährige Patientin mit intrahepatischem Cholangiokarzinom. DNA, RNA und weitere Omics-Layer liegen vor. Eine pathogene IDH1-Alteration ist klar, eine FGFR2-Fusion fehlt, während FGFR2-Expression und mehrere Pathway-Scores hoch sind.":"59-year-old woman with intrahepatic cholangiocarcinoma. DNA, RNA and additional omics layers are available. A pathogenic IDH1 alteration is clear, no FGFR2 fusion is detected, while FGFR2 expression and several pathway scores are high.","Evidenz vor Datenmenge":"Evidence before data volume","Ein validierter Biomarker wiegt klinisch mehr als viele explorative Signaturen.":"A validated biomarker carries more clinical weight than many exploratory signatures.","Informationsmenge ist keine Evidenzstufe.":"Amount of information is not an evidence level.","Expression ≠ Fusion":"Expression ≠ fusion","Hohe FGFR2-mRNA ist biologisch interessant, aber nicht dasselbe wie ein nachgewiesenes FGFR2-Fusionsereignis.":"High FGFR2 mRNA is biologically interesting, but it is not the same as a demonstrated FGFR2 fusion event.","Omics-Layer messen unterschiedliche Phänomene.":"Omics layers measure different phenomena.","Negative Befunde können entscheidend sein":"Negative findings can be decisive","„Keine FGFR2-Fusion“ verhindert ein falsches Target-Narrativ.":"‘No FGFR2 fusion’ prevents a false target narrative.","Klinische Zusammenfassung braucht auch relevante Ausschlüsse.":"A clinical summary also needs relevant exclusions.","IDH1 p.R132C pathogen":"IDH1 p.R132C pathogenic","keine FGFR2-Fusion":"no FGFR2 fusion","FGFR2 hoch exprimiert; EMT/MET-Signaturen erhöht":"FGFR2 highly expressed; EMT/MET signatures increased","Immunkontext":"Immune context","MSS, TMB niedrig, PD-L1 niedrig":"MSS, low TMB, low PD-L1","Alle Daten bereits vorhanden.":"All data already available.","Keine akute Materialfrage.":"No acute material issue.","Limitierend ist die Evidenzinterpretation, nicht die Messkapazität.":"The limitation is evidence interpretation, not measurement capacity.","Was gehört in die erste Zeile der MTB-Zusammenfassung?":"What belongs in the first line of the tumor-board summary?","Der klinisch am besten validierte relevante Biomarker und seine konkrete Bedeutung.":"The clinically best-validated relevant biomarker and its concrete meaning.","Die stärkste Farbe der Heatmap.":"The strongest color in the heatmap.","Alle 200 Signaturen alphabetisch.":"All 200 signatures alphabetically.","Jede VUS vor gesicherten Befunden.":"Every VUS before established findings.","MTB-Kommunikation priorisiert klinische Evidenz.":"Tumor-board communication prioritizes clinical evidence.","Was bedeutet hohe FGFR2-Expression ohne nachgewiesene FGFR2-Fusion?":"What does high FGFR2 expression without a demonstrated FGFR2 fusion mean?","Biologischer/explorativer Kontext, aber kein automatischer Ersatz für den validierten Fusionsbiomarker.":"Biological/exploratory context, but not an automatic substitute for the validated fusion biomarker.","Eine Fusion ist damit bewiesen.":"A fusion is thereby proven.","Target-Therapie ist allein dadurch zwingend.":"Targeted therapy is mandatory on this basis alone.","RNA ist grundsätzlich Artefakt.":"RNA is inherently an artifact.","Expression und strukturelle Genfusion sind verschiedene Befundarten.":"Expression and structural gene fusion are different finding types.","Warum ist „keine FGFR2-Fusion“ ein wichtiger Befund?":"Why is ‘no FGFR2 fusion’ an important finding?","Er verhindert, dass die hohe Expression fälschlich als etablierter Fusions-Targetkontext verkauft wird.":"It prevents high expression from being falsely presented as an established fusion-target context.","Negative Befunde gehören nie ins MTB.":"Negative findings never belong in the tumor board.","Er hat keinerlei Interpretationswert.":"It has no interpretive value at all.","Er macht IDH1 automatisch negativ.":"It automatically makes IDH1 negative.","Relevante Negativbefunde begrenzen falsche Handlungsableitungen.":"Relevant negative findings limit false actionability inferences.","Der Bericht rankt „FGFR pathway activation“ als stärkstes Signal. Was tun Sie?":"The report ranks ‘FGFR pathway activation’ as the strongest signal. What do you do?","Als explorative Signatur kennzeichnen und hinter validierten molekularen Befunden priorisieren.":"Label it as an exploratory signature and prioritize it below validated molecular findings.","Als stärkstes Target behandeln.":"Treat it as the strongest target.","Alle Omics-Daten verwerfen.":"Discard all omics data.","Eine FGFR2-Fusion daraus ableiten.":"Infer an FGFR2 fusion from it.","Pathway-Scores sind ohne entsprechende klinische Validierung Hypothesen, keine automatischen Companion Biomarker.":"Without corresponding clinical validation, pathway scores are hypotheses, not automatic companion biomarkers.","Verdichten Sie den Multiomics-Bericht zu einer evidenzhierarchischen MTB-Kernaussage.":"Condense the multiomics report into an evidence-hierarchical tumor-board core message.","Validierte/etablierte Biomarker identifizieren.":"Identify validated/established biomarkers.","Relevante negative Befunde sichtbar machen.":"Make relevant negative findings visible.","Expression, Fusion, Protein und Pathways als unterschiedliche Ebenen behandeln.":"Treat expression, fusion, protein and pathways as different layers.","Explorative Signaturen kennzeichnen.":"Label exploratory signatures.","MTB-Aussage auf Entscheidung statt Dateninventar fokussieren.":"Focus the tumor-board statement on the decision, not on the data inventory.","Explorative Omics können für Studienhypothesen oder Translation wertvoll sein; sie gehören nur nicht unmarkiert in dieselbe Evidenzstufe wie validierte klinische Biomarker.":"Exploratory omics can be valuable for study hypotheses or translational research; they simply should not be placed, unlabeled, at the same evidence level as validated clinical biomarkers.","Heatmap-Tophit = Target":"Heatmap top hit = target","Visuelle Effektstärke ersetzt keine klinische Validierung.":"Visual effect size does not replace clinical validation.","Alles in einen Satz pressen":"Compress everything into one sentence","Verwischt Evidenzstufen.":"Blurs evidence levels.","Exploratives komplett löschen":"Delete all exploratory data","Verliert wissenschaftlich wertvolle Hypothesen; besser klar labeln.":"Loses scientifically valuable hypotheses; better to label them clearly.","Der lauteste Signalweg ist nicht die stärkste klinische Aussage":"The loudest pathway is not the strongest clinical statement","FGFR2-Expression ist hoch, aber es gibt keine FGFR2-Fusion. Die belastbare Topline bleibt die pathogene IDH1-Alteration; Omics-Signaturen werden als explorativ eingeordnet.":"FGFR2 expression is high, but there is no FGFR2 fusion. The robust topline remains the pathogenic IDH1 alteration; omics signatures are classified as exploratory.","Der Twist dreht die Priorität von Signalstärke zu Evidenzstärke.":"The twist shifts priority from signal strength to strength of evidence.","Klarer Biomarker, klarer Ausschluss, klar markierte Hypothesen.":"Clear biomarker, clear exclusion, clearly labeled hypotheses.","MTB-taugliche Verdichtung.":"Tumor-board-ready condensation.","Report vorgelesen":"Report read aloud","Viele Daten, keine Entscheidung.":"Lots of data, no decision.","Informationsüberlastung.":"Information overload.","FGFR2-expression als Fusion behandelt":"FGFR2 expression treated as fusion","Explorativer Befund wird targetiert.":"Exploratory finding is targeted.","Layer-Verwechslung.":"Layer confusion.","Omics-Signal ohne validierten klinischen Biomarkerstatus":"Omics signal without validated clinical biomarker status","als explorativ/hypothesengenerierend kennzeichnen":"label as exploratory/hypothesis-generating","nicht auf gleiche Ebene wie etablierte prädiktive Marker stellen.":"do not place at the same level as established predictive markers.","Multiomics braucht Evidenzhierarchie.":"Multiomics needs an evidence hierarchy.","Biologische Plausibilität ist nicht identisch mit klinischer Actionability.":"Biological plausibility is not identical to clinical actionability.","Gute MTB-Kommunikation ist selektiv und transparent.":"Good tumor-board communication is selective and transparent.","Kernaussage: pathogene IDH1-Alteration als belastbarer tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression und Pathway-Signaturen sind explorativ und nicht als validierte Targets zu überinterpretieren.":"Core message: pathogenic IDH1 alteration as a robust tumor-related biomarker; no FGFR2 fusion. High FGFR2 expression and pathway signatures are exploratory and should not be overinterpreted as validated targets.","Evidenzpriorisierung":"Evidence prioritization","Omics-Layer":"Omics layers","Wie viele Ebenen sollte ein MTB-Report zeigen?":"How many levels should a tumor-board report show?","Wie labelt man explorative Signaturen?":"How do you label exploratory signatures?","Welche negativen Befunde sind entscheidungsrelevant?":"Which negative findings are decision-relevant?","Twist: stärkstes Signal ist nicht stärkste Evidenz":"Twist: strongest signal is not strongest evidence","Referenzpfad: validiert → relevante Negative → explorativ":"Reference pathway: validated → relevant negatives → exploratory","dna_rna_lung_combo":"Combined DNA/RNA lung panel","Resistenzdiagnostik bei Progress":"Resistance testing at progression","Gewebe-Rebiopsie bei negativer Liquid Biopsy":"Tissue rebiopsy after a negative liquid biopsy","Liquid Biopsy richtig einordnen":"Interpret the liquid biopsy appropriately","Progressionspanel: erworbener Resistenzmechanismus wird plausibilisiert; Liquid Biopsy allein ist bei negativem Ergebnis nicht ausreichend.":"Progression panel: an acquired resistance mechanism is supported; a negative liquid biopsy alone is insufficient.","Rebiopsie liefert beurteilbares Tumormaterial für Resistenzanalyse.":"Rebiopsy provides evaluable tumor material for resistance analysis.","Negative Liquid Biopsy wird nur mit ctDNA-/Materialkontext interpretiert; Rebiopsie bleibt Option.":"A negative liquid biopsy is interpreted only in the context of ctDNA and specimen adequacy; rebiopsy remains an option.","Integrierte Interpretation vollständig: Liquid Biopsy negativ: reicht das oder Rebiopsie? Die gewählten Methoden beantworten die Kernfrage mit angemessener Aussagekraft und Limitationen.":"Integrated interpretation complete: negative liquid biopsy— is that sufficient, or is rebiopsy needed? The selected methods address the core question with appropriate analytical scope and limitations.","Teilbefund: Für die Kernentscheidung („Liquid Biopsy negativ: reicht das oder Rebiopsie?“) fehlen noch zentrale Bausteine oder die Methode ist zu eng gewählt.":"Partial result: key elements are still missing for the central decision (“Negative liquid biopsy: is that sufficient, or is rebiopsy needed?”), or the selected method is too narrow.","Resistenzdiagnostik bei Progress in der MTB-Kernaussage korrekt einordnen":"Correctly position resistance testing at progression in the core MTB statement","Gewebe-Rebiopsie bei negativer Liquid Biopsy in der MTB-Kernaussage korrekt einordnen":"Correctly position tissue rebiopsy after a negative liquid biopsy in the core MTB statement","Liquid Biopsy richtig einordnen in der MTB-Kernaussage korrekt einordnen":"Correctly interpret the liquid biopsy in the core MTB statement","Optimale Lösung: Liquid Biopsy negativ: reicht das oder Rebiopsie? – mit fallgerechter Methodenkombination, Material-/QC-Bewertung und klarer MTB-Kommunikation.":"Optimal solution: negative liquid biopsy—sufficient or rebiopsy? Use a case-appropriate method combination, assess specimen/QC context, and communicate the conclusion clearly in the MTB.","RNA-Fusionsdiagnostik primär fehlt":"Primary RNA fusion testing is missing","entitätsfremde Tests gewählt":"Tests unrelated to the tumor entity selected","nur Liquid Biopsy gewählt":"Only liquid biopsy selected","Rebiopsie gewählt, aber MET/CNV/Transformation nicht bedacht":"Rebiopsy selected, but MET/CNV/transformational resistance not considered","MTB Basics / Präanalytik":"MTB Basics / Preanalytics","colon_ngs_panel":"Colorectal cancer NGS panel","MTB Basics / Genominstabilität":"MTB Basics / Genomic instability","broad_pan_panel":"Broad pan-cancer panel","MTB Basics / Advanced":"MTB Basics / Advanced","hoch.":"high.","MTB / Molecular Diagnostics":"MTB / Molecular Diagnostics","wildtyp":"wild type"},"ro":{"ERBB2-VUS im RAS/BRAF-WT-mCRC: Genname ist noch kein Target":"VUS ERBB2 în mCRC RAS/BRAF-WT: numele genei nu reprezintă încă o țintă terapeutică","VUS im Onkogen":"VUS într-o oncogenă","Initialer Auftrag":"Solicitarea inițială","Einsender":"Solicitant","Gastroonkologie / Molekulares Tumorboard":"Oncologie gastrointestinală / Tumor Board molecular","Klinische Information":"Informații clinice","63-jährige Patientin mit linksseitigem metastasiertem CRC und Progress nach mehreren Therapielinien. Ein externer NGS-Bericht markiert „ERBB2 altered“ prominent.":"Pacientă de 63 de ani cu CRC metastatic stâng și progresie după mai multe linii terapeutice. Un raport NGS extern evidențiază proeminent «ERBB2 altered». ","Fragestellung":"Întrebarea clinică","Reicht eine seltene ERBB2-Missense-VUS als Grundlage für HER2-gerichtete Therapie?":"Este o VUS missense rară în ERBB2 suficientă pentru a fundamenta o terapie anti-HER2?","Zeitfenster":"Interval de timp","Nächste Therapielinie soll im MTB diskutiert werden.":"Următoarea linie terapeutică urmează să fie discutată în Tumor Board-ul molecular.","Anamnese und klinischer Kontext":"Anamneză și context clinic","Molekularer Kontext":"Context molecular","KRAS/NRAS/BRAF wildtyp, pMMR/MSS.":"KRAS/NRAS/BRAF wild-type, pMMR/MSS.","Externer Report":"Raport extern","Seltene ERBB2-Missense-Variante, VAF 18 %, Klassifikation VUS; im Summary trotzdem gelb als „potential target“ hervorgehoben.":"Variantă missense rară ERBB2, VAF 18 %, clasificată VUS; totuși evidențiată cu galben în rezumat ca «potential target». ","Didaktische Falle":"Capcană didactică","Genname, Datenbanktreffer und Actionability werden miteinander vermischt.":"Numele genei, rezultatul din baza de date și caracterul acționabil sunt confundate între ele.","Ziel":"Obiectiv","Variante, Biomarker und klinische Evidenz getrennt bewerten.":"Evaluați separat varianta, biomarkerul și dovezile clinice.","Histologie + Vorinformation":"Histologie + informații preexistente","Histologie":"Histologie","Metastasiertes kolorektales Adenokarzinom.":"Adenocarcinom colorectal metastatic.","HER2-IHC":"IHC HER2","noch nicht erfolgt.":"nu a fost încă efectuată.","ISH":"ISH","Offen":"În așteptare","Gibt es unabhängig von der VUS einen etablierten HER2-Biomarker?":"Există un biomarker HER2 consacrat, independent de VUS?","Materialprüfung":"Evaluarea materialului","Material":"Material","FFPE-Metastase, ausreichend.":"Metastază FFPE, material suficient.","Tumoranteil":"Proporția tumorală","ca. 55 %.":"aprox. 55 %.","NGS-QC":"QC NGS","Variante technisch robust detektiert.":"Variantă detectată cu robustețe tehnică ridicată.","Wichtig":"Important","Technisch echt bedeutet nicht automatisch klinisch bedeutsam.":"Faptul că este tehnic real nu înseamnă automat că este relevant clinic.","ERBB2-Variantenbewertung":"Evaluarea variantei ERBB2","VUS-/Evidenzkurationsschritt":"Etapă de curare VUS/dovezi","Unabhängigen HER2-Biomarker prüfen":"Evaluați un biomarker HER2 independent","ERBB2-NGS":"NGS ERBB2","Seltene ERBB2-Missense-Variante, VAF 18 %, technisch robust; aktuelle Klassifikation VUS.":"Variantă missense rară ERBB2, VAF 18 %, tehnic robustă; clasificare actuală: VUS.","VUS-Curation":"Curarea VUS","Keine ausreichende klinische Evidenz für prädiktive Actionability; einzelne präklinische Hinweise reichen nicht zur Hochstufung.":"Dovezi clinice insuficiente pentru acționabilitate predictivă; indicii preclinice izolate nu sunt suficiente pentru reclasificare.","HER2 IHC 1+, keine starke membranöse Überexpression.":"IHC HER2 1+, fără supraexpresie membranară intensă.","HER2-FISH/ISH":"FISH/ISH HER2","Keine ERBB2-Amplifikation.":"Fără amplificare ERBB2.","Fehlentscheidung":"Decizie incorectă","Eine direkte HER2-Therapieempfehlung allein aus einer VUS wäre ein Evidenz-Overcall.":"O recomandare directă de terapie anti-HER2 bazată exclusiv pe o VUS ar reprezenta o supra-interpretare a dovezilor.","Die VUS ist technisch real detektiert.":"VUS este tehnic reală.","Kernaussage":"Mesaj-cheie","Technische Echtheit, Pathogenität und prädiktive Actionability sind drei getrennte Ebenen.":"Validitatea tehnică, patogenitatea și acționabilitatea predictivă sunt trei niveluri distincte.","Die ERBB2-Variante ist technisch robust, aber klinisch weiterhin VUS und darf nicht als gesicherter prädiktiver Biomarker behandelt werden. HER2-IHC 1+ und fehlende ERBB2-Amplifikation liefern keinen unabhängigen etablierten HER2-Amplifikationskontext. Eine Therapieempfehlung allein aus der VUS wäre nicht evidenzbasiert.":"Varianta ERBB2 este tehnic robustă, dar rămâne clinic o VUS și nu trebuie tratată ca biomarker predictiv consacrat. IHC HER2 1+ și absența amplificării ERBB2 nu oferă un context independent consacrat de amplificare HER2. O recomandare terapeutică bazată exclusiv pe VUS nu ar fi bazată pe dovezi.","Teilbefund: Ein technisch echter Variantenfund ist ohne belastbare funktionelle/klinische Evidenz nicht automatisch actionable.":"Rezultat parțial: un rezultat de variantă tehnic real nu este automat acționabil fără dovezi funcționale/clinice solide.","VUS klar als VUS benennen":"Denumiți clar VUS ca VUS","technische Validität, Pathogenität und Actionability trennen":"separați validitatea tehnică, patogenitatea și acționabilitatea","IHC/ISH als separaten Biomarkerpfad verstehen":"înțelegeți IHC/ISH ca o cale separată de evaluare a biomarkerului HER2","Falschaussage: ERBB2 steht im Genfeld, also ist HER2-Therapie indiziert":"Afirmație falsă: ERBB2 apare în câmpul genei, deci este indicată terapia anti-HER2","Optimale Lösung: ERBB2-VUS nicht overcallen, unabhängige HER2-Biomarker separat prüfen und die Therapieaussage an Evidenz statt an Genname oder Datenbankfarbe koppeln.":"Soluție optimă: nu supra-interpretați VUS ERBB2, evaluați separat biomarkerii HER2 independenți și bazați afirmația terapeutică pe dovezi, nu pe numele genei sau pe culoarea din baza de date.","VUS":"VUS","ERBB2":"ERBB2","HER2":"HER2","Evidenz":"Dovezi","MTB":"MTB","Deep Dive":"Deep Dive","Das gelbe „potential target“":"«Potential target» evidențiat cu galben","Molekulares Tumorboard / Varianteninterpretation":"Tumor Board molecular / interpretarea variantelor","VUS nicht als pathogene/actionable Variante berichten.":"Nu raportați o VUS ca patogenă/acționabilă.","Technische Validität, biologische Pathogenität und klinische Prädiktion trennen.":"Separați validitatea tehnică, patogenitatea biologică și predicția clinică.","IHC/ISH bei HER2 als eigenständigen Biomarkerpfad einordnen.":"Încadrați IHC/ISH pentru HER2 ca o cale de biomarker independentă.","Datenbank-/Software-Highlights nicht mit klinischer Evidenz verwechseln.":"Nu confundați evidențierile din baze de date/software cu dovezile clinice.","Im externen Report ist ERBB2 gelb hervorgehoben: „potential target“. In der Detailzeile steht jedoch schlicht VUS. Der Fall ist ein Test dafür, ob das Board die Farbe oder die Evidenz liest.":"În raportul extern, ERBB2 este evidențiat cu galben: «potential target». În linia de detaliu scrie însă pur și simplu VUS. Cazul testează dacă board-ul citește culoarea sau dovezile.","63-jährige Patientin mit RAS/BRAF-WT-mCRC. Eine seltene ERBB2-Missense-Variante ist technisch sicher detektiert, aber als VUS klassifiziert. Das Board soll entscheiden, ob daraus eine HER2-gerichtete Therapieaussage entsteht.":"Pacientă de 63 de ani cu mCRC RAS/BRAF-WT. O variantă missense rară ERBB2 este tehnic sigură, dar clasificată VUS. Board-ul trebuie să decidă dacă aceasta susține o afirmație terapeutică anti-HER2.","Drei Ebenen":"Trei niveluri","Call echt? Variante pathogen? Befund prädiktiv?":"Call real? Variantă patogenă? Rezultat predictiv?","Diese Ebenen dürfen nicht zusammenfallen.":"Aceste niveluri nu trebuie confundate între ele.","HER2 ist mehr als ein Genname":"HER2 înseamnă mai mult decât numele unei gene","Amplifikation/Überexpression und einzelne Sequenzvarianten sind unterschiedliche Biomarker.":"Amplificarea/supraexpresia și variantele individuale de secvență sunt biomarkeri diferiți.","Methoden beantworten verschiedene Fragen.":"Metodele răspund la întrebări diferite.","Software ist keine Leitlinie":"Software-ul nu este un ghid","Ein automatisch hervorgehobener Datenbanktreffer kann evidenzarm sein.":"Un rezultat din baza de date evidențiat automat poate avea dovezi slabe.","Finale Interpretation bleibt fachlich verantwortlich.":"Interpretarea finală rămâne o responsabilitate profesională.","ERBB2-Variante":"Variantă ERBB2","VAF 18 %, technisch robust, Klassifikation VUS":"VAF 18 %, tehnic robustă, clasificată VUS","RAS/BRAF":"RAS/BRAF","MMR/MSI":"MMR/MSI","pMMR/MSS":"pMMR/MSS","Material ausreichend.":"Material suficient.","Keine analytische Unsicherheit des Calls – die Unsicherheit ist interpretativ.":"Nu există incertitudine analitică a call-ului; incertitudinea este interpretativă.","Der Fall verlangt keine Therapieempfehlung aus einem nicht etablierten VUS.":"Cazul nu cere o recomandare terapeutică bazată pe o VUS neconsacrată.","Was ist die korrekte Bedeutung einer technisch robusten ERBB2-VUS?":"Care este semnificația corectă a unei VUS ERBB2 tehnic robuste?","Die Variante ist nach aktueller Evidenz nicht ausreichend als pathogen/prädiktiv klassifiziert.":"Conform dovezilor actuale, varianta nu este suficient clasificată ca patogenă/predictivă.","Jede ERBB2-Variante ist actionable.":"Orice variantă ERBB2 este acționabilă.","VUS bedeutet sicher benign.":"VUS înseamnă cu siguranță benignă.","VUS bedeutet Keimbahn.":"VUS înseamnă germinală.","VUS beschreibt unzureichende Evidenz, nicht eine halbe Therapieindikation.":"VUS descrie dovezi insuficiente, nu o jumătate de indicație terapeutică.","Welche Ebenen müssen getrennt bewertet werden?":"Ce niveluri trebuie evaluate separat?","analytische Echtheit des Calls":"validitatea analitică a call-ului","Pathogenität/biologische Bedeutung":"patogenitate/semnificație biologică","klinisch-prädiktive Evidenz":"dovezi clinice predictive","Farbe im Software-Report":"culoarea din raportul software","Der Software-Look ist keine Evidenzebene.":"Aspectul software-ului nu reprezintă un nivel de dovezi.","HER2 IHC 1+ und keine ERBB2-Amplifikation: Was folgt daraus?":"IHC HER2 1+ și fără amplificare ERBB2: ce rezultă?","Es liegt kein unabhängiger etablierter Amplifikations-/Überexpressionsbefund vor, der die VUS „rettet“.":"Nu există un rezultat independent consacrat de amplificare/supraexpresie care să «salveze» VUS.","Damit wird die VUS automatisch pathogen.":"Astfel VUS devine automat patogenă.","HER2-Therapie ist allein dadurch zwingend.":"Doar pe această bază, terapia anti-HER2 este obligatorie.","IHC/ISH und Sequenzierung messen exakt dasselbe.":"IHC/ISH și secvențierea măsoară exact același lucru.","Die Methoden adressieren unterschiedliche Biomarker.":"Metodele evaluează biomarkeri diferiți.","Eine Datenbank nennt einen präklinischen Zelllinienhinweis. Reicht das zur Therapieableitung?":"O bază de date citează un rezultat preclinic într-o linie celulară. Este suficient pentru a deriva o terapie?","Nein; präklinische Hinweise können Hypothesen stützen, ersetzen aber keine ausreichende klinische Evidenz für diese VUS.":"Nu; rezultatele preclinice pot susține ipoteze, dar nu înlocuiesc dovezi clinice suficiente pentru această VUS.","Ja, jeder präklinische Treffer macht eine VUS actionable.":"Da, orice rezultat preclinic face o VUS acționabilă.","Literatur ist grundsätzlich irrelevant.":"Literatura este în principiu irelevantă.","Die Variante wird automatisch Tier I.":"Varianta devine automat Tier I.","Evidenzhierarchie und variantenspezifische Daten müssen berücksichtigt werden.":"Trebuie luate în considerare ierarhia dovezilor și datele specifice variantei.","Formulieren Sie eine MTB-Kernaussage, die den ERBB2-Fund korrekt einordnet, ohne ihn zu overcallen.":"Formulați un mesaj-cheie pentru MTB care încadrează corect rezultatul ERBB2 fără supra-interpretare.","Technische Echtheit bestätigen.":"Confirmați validitatea tehnică.","Aktuelle Variantenklassifikation übernehmen bzw. fachlich kuratieren.":"Preluați sau curați profesional clasificarea actuală a variantei.","Keine Pathogenität/Actionability aus dem Genname ableiten.":"Nu deduceți patogenitatea/acționabilitatea din numele genei.","HER2-IHC/ISH als separaten Biomarkerpfad bewerten.":"Evaluați IHC/ISH HER2 ca o cale de biomarker separată.","VUS klar und nicht handlungsleitend kommunizieren; Re-Evaluation bei neuer Evidenz möglich.":"Comunicați clar VUS ca nefiind orientativă pentru acțiune; reevaluarea este posibilă dacă apar dovezi noi.","Studieneinschluss kann je nach Protokoll breitere molekulare Kriterien verwenden; das ist von einer etablierten Therapieempfehlung zu trennen.":"În funcție de protocol, includerea într-un studiu poate utiliza criterii moleculare mai largi; aceasta trebuie diferențiată de o recomandare terapeutică consacrată.","Genname = Target":"Numele genei = țintă","Ignoriert Variantenspezifität und Evidenz.":"Ignoră specificitatea variantei și dovezile.","VUS = benign":"VUS = benignă","Unsicherheit wird fälschlich in Harmlosigkeit umgedeutet.":"Incertitudinea este reinterpretată greșit ca lipsă de risc.","IHC/ISH macht Missense-VUS pathogen":"IHC/ISH face o VUS missense patogenă","Unterschiedliche Biomarkerfragen werden vermischt.":"Sunt confundate întrebări diferite privind biomarkerii.","Die Variante ist echt – und trotzdem kein Target":"Varianta este reală — și totuși nu este o țintă","Curation bestätigt die technische Echtheit, aber nicht die klinische Actionability. HER2-IHC/ISH liefern ebenfalls keinen unabhängigen etablierten HER2-Befund.":"Curarea confirmă validitatea tehnică, dar nu acționabilitatea clinică. Nici IHC/ISH HER2 nu oferă un rezultat HER2 independent consacrat.","Der Twist ist kein Laborfehler, sondern die Trennung von Detektion und Bedeutung.":"Twist-ul nu este o eroare de laborator, ci separarea detecției de semnificație.","VUS sauber begrenzt":"VUS delimitată corect","Technisch echt, klinisch unklar, kein Overcalling.":"Tehnic reală, clinic neclară, fără supra-interpretare.","Evidenzgerechte MTB-Kommunikation.":"Comunicare MTB bazată pe dovezi.","Direkt HER2-Therapie":"Terapie anti-HER2 directă","VUS wird wie ein etablierter Biomarker behandelt.":"VUS este tratată ca un biomarker consacrat.","Kritischer Interpretationsfehler.":"Eroare critică de interpretare.","VUS verschwiegen":"VUS omisă","Unsicherheit wird nicht transparent kommuniziert.":"Incertitudinea nu este comunicată transparent.","Besser klar benennen und begrenzen.":"Este mai bine să fie denumită și delimitată clar.","VUS ohne ausreichende prädiktive Evidenz":"VUS fără dovezi predictive suficiente","nicht als gesichertes Target formulieren":"nu o descrieți ca țintă consacrată","ggf. Re-Evaluation bei neuer Evidenz.":"luați în considerare reevaluarea dacă apar dovezi noi.","VUS ist eine Evidenzkategorie.":"VUS este o categorie de dovezi.","Softwareannotation ersetzt keine fachliche Varianteninterpretation.":"Adnotarea software nu înlocuiește interpretarea profesională a variantei.","Ein Gen kann mehrere völlig unterschiedliche Biomarkerarten tragen.":"O genă poate conține mai multe tipuri complet diferite de biomarkeri.","ERBB2-VUS technisch bestätigt, jedoch ohne ausreichende klinisch-prädiktive Evidenz; HER2 IHC/ISH ohne unabhängigen positiven Biomarker. Keine etablierte Therapieableitung allein aus der VUS.":"VUS ERBB2 confirmată tehnic, dar fără dovezi clinice predictive suficiente; IHC/ISH HER2 fără biomarker pozitiv independent. Nicio implicație terapeutică consacrată bazată exclusiv pe VUS.","Evidenzhierarchie":"Ierarhia dovezilor","Variantenspezifität":"Specificitatea variantei","MTB-Kommunikation":"Comunicare MTB","Wann darf eine VUS reklassifiziert werden?":"Când poate fi reclasificată o VUS?","Wie häufig sollte Re-Annotation erfolgen?":"Cât de des ar trebui efectuată re-adnotarea?","Wie verhindert man Software-bedingtes Overcalling?":"Cum poate fi prevenită supra-interpretarea indusă de software?","Twist: technisch echt ≠ klinisch actionable":"Twist: tehnic real ≠ clinic acționabil","HER2-IHC/ISH und Sequenz-VUS getrennt":"IHC/ISH HER2 și VUS de secvență evaluate separat","Referenzpfad: Call → Klassifikation → Evidenz → klinische Aussage":"Cale de referință: call → clasificare → dovezi → afirmație clinică","ALK/ROS1/RET/NTRK-Fusionsverdacht bei jungem Nie-Raucher → FISH, RNA-NGS oder DNA-NGS?":"Suspiciune de fuziune ALK/ROS1/RET/NTRK la o pacientă tânără nefumătoare → FISH, NGS ARN sau NGS ADN?","ALK/ROS1/RET/NTRK-Fusionsverdacht …":"Suspiciune de fuziune ALK/ROS1/RET/NTRK …","Thoraxonkologie / Molekulares Tumorboard":"Oncologie toracică / Tumor Board molecular","42-jährige Patientin, Nie-Raucherin, metastasiertes pulmonales Adenokarzinom mit Leber- und Knochenmetastasen.":"Pacientă de 42 de ani, nefumătoare, cu adenocarcinom pulmonar metastatic cu metastaze hepatice și osoase.","Ein externes DNA-basiertes Panel meldet keinen therapierbaren Treiber. Ist die molekulare Abklärung damit abgeschlossen oder muss eine Fusionsdiagnostik ergänzt werden?":"Un panel extern bazat pe ADN nu raportează niciun driver acționabil. Este evaluarea moleculară completă sau trebuie adăugată testarea fuziunilor?","Die Erstlinientherapie soll im MTB in fünf Tagen festgelegt werden.":"Tratamentul de primă linie urmează să fie stabilit în Tumor Board-ul molecular peste cinci zile.","Raucherstatus":"Status de fumător","Nie-Raucherin, keine relevante berufliche Exposition.":"Nefumătoare, fără expunere profesională relevantă.","Klinischer Verlauf":"Evoluție clinică","ECOG 1, symptomatische ossäre Metastase, insgesamt aber klinisch stabil.":"ECOG 1, metastază osoasă simptomatică, dar per ansamblu clinic stabilă.","Vorbefund":"Rezultat anterior","Externes DNA-NGS ohne EGFR-, KRAS-, BRAF-, MET-Exon-14- oder ERBB2-Alteration; der Bericht enthält keine belastbare Aussage zur RNA-basierten Fusionserfassung.":"NGS ADN extern fără alterări EGFR, KRAS, BRAF, MET exon 14 sau ERBB2; raportul nu oferă o afirmație robustă privind detecția fuziunilor bazată pe ARN.","Entscheidungsdruck":"Presiune decizională","Die Onkologie erwägt bereits eine nicht zielgerichtete Systemtherapie, falls kein Treiber gefunden wird.":"Oncologia ia deja în calcul o terapie sistemică nețintită dacă nu este identificat niciun driver.","HE":"HE","Mäßig differenziertes pulmonales Adenokarzinom in einer Lebermetastasenbiopsie.":"Adenocarcinom pulmonar moderat diferențiat într-o biopsie de metastază hepatică.","IHC":"IHC","TTF-1 und Napsin A positiv; p40 negativ. Die Morphologie und der klinische Kontext stützen einen pulmonalen Primarius.":"TTF-1 și Napsin A pozitive; p40 negativ. Morfologia și contextul clinic susțin o origine pulmonară.","Biologischer Hinweis":"Indiciu biologic","Junges Alter und Nie-Raucherstatus erhöhen die Aufmerksamkeit für eine onkogene Treiberalteration, ersetzen aber keinen methodisch vollständigen Nachweis.":"Vârsta tânără și statutul de nefumătoare cresc suspiciunea unei alterări driver oncogene, dar nu înlocuiesc o testare metodologic completă.","Offene Frage":"Întrebare deschisă","Wurden ALK-, ROS1-, RET- und NTRK-Fusionen mit einer dafür geeigneten Methode tatsächlich ausreichend ausgeschlossen?":"Au fost fuziunile ALK, ROS1, RET și NTRK într-adevăr excluse printr-o metodă adecvată?","FFPE-Leberbiopsie, Block M2.":"Biopsie hepatică FFPE, bloc M2.","ca. 35–40 %, nach Markierung gut geeignet.":"aprox. 35–40 %, bine adecvat după marcaj.","RNA-Prognose":"Prognostic privind ARN-ul","RNA-Qualität nach Vorprüfung grenzwertig bis ausreichend; noch genügend Material für einen gezielten RNA-Ansatz.":"Calitatea ARN este la limită până la suficientă după evaluarea preliminară; rămâne suficient material pentru o abordare ARN țintită.","Schnittbudget":"Buget de secțiuni","8 ungefärbte Schnitte verfügbar.":"Sunt disponibile 8 secțiuni necolorate.","Materialfalle":"Capcană privind materialul","Ein wiederholtes DNA-only-Panel verbraucht Material und kann die eigentliche Fusionsfrage trotzdem offenlassen.":"Repetarea unui panel doar ADN consumă material și poate lăsa în continuare fără răspuns întrebarea reală privind fuziunile.","Breite Fusionsdiagnostik":"Testare largă a fuziunilor","DNA-NGS":"NGS ADN","Kein relevanter SNV/Indel-Treiber nachweisbar. Die konkrete Assay-Konfiguration erlaubt keinen belastbaren Ausschluss aller klinisch relevanten Fusionen.":"Nu s-a detectat niciun driver SNV/indel relevant. Configurația specifică a testului nu permite excluderea fiabilă a tuturor fuziunilor clinic relevante.","RNA-Fusionsdiagnostik":"Testarea fuziunilor prin ARN","KIF5B::RET-Fusion nachweisbar; in-frame und exprimiert. Der Befund erklärt den bisher DNA-negativen Treiberstatus.":"Fuziune KIF5B::RET detectată; in-frame și exprimată. Rezultatul explică statusul driver anterior negativ la ADN.","FISH":"FISH","Bei gezielter RET-FISH zeigt sich ein Rearrangement. Die Methode bestätigt die Umlagerung, liefert aber nicht die Breite einer parallelen RNA-Fusionsanalyse.":"FISH țintit pentru RET evidențiază o rearanjare. Metoda confirmă rearanjarea, dar nu oferă amploarea unei analize paralele a fuziunilor prin ARN.","QC":"QC","Tumorzellanteil ausreichend. RNA ist knapp, aber nach QC verwertbar; Material Stewardship bleibt relevant.":"Proporție tumorală suficientă. ARN-ul este limitat, dar utilizabil după QC; gestionarea atentă a materialului rămâne importantă.","Die RNA-basierte Fusionsdiagnostik weist eine therapeutisch relevante KIF5B::RET-Fusion nach. Der zuvor negative DNA-Befund war kein belastbarer Ausschluss einer onkogenen Fusion.":"Testarea fuziunilor bazată pe ARN detectează o fuziune KIF5B::RET relevantă terapeutic. Rezultatul ADN anterior negativ nu reprezenta o excludere fiabilă a unei fuziuni oncogene.","Teilbefund: Eine gezielte Einzelmethode oder DNA-only-Strategie kann die breite Fusionsfrage nicht vollständig beantworten. Eine RNA-basierte Fusionsdiagnostik sollte ergänzt werden.":"Rezultat parțial: o singură metodă țintită sau o strategie doar ADN nu poate răspunde complet întrebării largi privind fuziunile. Trebuie adăugată testarea fuziunilor bazată pe ARN.","Die RET-Fusion als therapieentscheidenden Treiber benennen":"Identificați fuziunea RET ca driver care definește tratamentul","DNA-only nicht mit umfassend treibernegativ gleichsetzen":"nu echivalați doar ADN cu negativ complet pentru drivere","FISH als gezielte Bestätigungs-/Alternativmethode, nicht als universellen Ersatz einer breiten RNA-Analyse einordnen":"încadrați FISH ca metodă țintită de confirmare/alternativă, nu ca substitut universal pentru analiza largă ARN","Assay- und RNA-QC-Limitationen transparent kommunizieren":"comunicați transparent limitările testului și ale QC ARN","Optimale Lösung: vorhandenen DNA-Befund methodisch prüfen und die offene Fusionsfrage mit einer breiten RNA-basierten Analyse schließen; gezielte FISH kann bei konkreter Hypothese ergänzen.":"Soluție optimă: revizuiți metodologic rezultatul ADN existent și închideți întrebarea deschisă privind fuziunile printr-o analiză largă bazată pe ARN; FISH țintit poate fi adăugat pentru o ipoteză concretă.","NSCLC":"NSCLC","NGS":"NGS","RNA":"ARN","MVP":"MVP","Standard":"Standard","Junge Nie-Raucherin mit DNA-negativem NSCLC: Ist der Tumor wirklich treibernegativ?":"Pacientă tânără nefumătoare cu NSCLC negativ la ADN: tumora este într-adevăr fără driver?","Molekularpathologie / Thoraxonkologie / MTB":"Patologie moleculară / Oncologie toracică / MTB","Einen negativen DNA-NGS-Befund nur innerhalb der tatsächlich validierten Assaygrenzen interpretieren.":"Interpretați un rezultat NGS ADN negativ numai în limitele testului care au fost efectiv validate.","RNA-basierte Fusionsdiagnostik bei klinisch plausibler Fusionsfrage gegenüber serieller FISH und erneutem DNA-only-Test priorisieren.":"Prioritizați testarea fuziunilor bazată pe ARN față de FISH seriat și repetarea unui test doar ADN atunci când există o suspiciune clinic plauzibilă de fuziune.","FISH als gezielte orthogonale Methode sinnvoll einordnen, ohne sie mit einer breiten parallelen Fusionssuche gleichzusetzen.":"Încadrați adecvat FISH ca metodă ortogonală țintită, fără a o echivala cu o căutare largă paralelă a fuziunilor.","Einen methodisch unvollständigen 'kein Treiber'-Befund im MTB aktiv korrigieren.":"Corectați activ în MTB un rezultat «fără driver» care este metodologic incomplet.","Mittwochmorgen vor dem Thorax-MTB. Auf dem Bildschirm steht bei einer 42-jährigen Nie-Raucherin mit metastasiertem Lungenadenokarzinom bereits der externe Satz: 'Kein therapeutisch relevanter Treiber nachweisbar.' Die Onkologie plant deshalb eine nicht zielgerichtete Systemtherapie. Beim Lesen des Methodenteils fällt jedoch auf: Untersucht wurde ein DNA-only-Panel; eine belastbare RNA-basierte Fusionsdiagnostik ist nicht dokumentiert. Aus einem scheinbar abgeschlossenen Befund wird wieder eine offene Therapiefrage.":"Miercuri dimineața înainte de MTB-ul toracic. Pe ecran, raportul extern al unei paciente de 42 de ani, nefumătoare, cu adenocarcinom pulmonar metastatic menționează deja: «Nu s-a detectat niciun driver relevant terapeutic». Prin urmare, oncologia planifică o terapie sistemică nețintită. Dar secțiunea de metodă arată că s-a efectuat doar un panel ADN; nu este documentată o testare robustă a fuziunilor bazată pe ARN. Un rezultat aparent închis devine din nou o întrebare terapeutică deschisă.","42-jährige Nie-Raucherin, ECOG 1, pulmonales Adenokarzinom mit Leber- und Knochenmetastasen. Externes DNA-NGS ohne relevante SNV/Indel-Treiber. Für das MTB muss entschieden werden, ob dieser Befund als treibernegativ akzeptiert werden kann oder ob die offene ALK/ROS1/RET/NTRK-Fusionsfrage mit einer geeigneten Methode geschlossen werden muss.":"Pacientă de 42 de ani, nefumătoare, ECOG 1, cu adenocarcinom pulmonar și metastaze hepatice și osoase. NGS ADN extern nu arată niciun driver SNV/indel relevant. MTB-ul trebuie să decidă dacă rezultatul poate fi acceptat drept negativ pentru driver sau dacă întrebarea deschisă privind fuziunile ALK/ROS1/RET/NTRK trebuie clarificată printr-o metodă adecvată.","Klinischer Kontext":"Context clinic","Junges Alter, Nie-Raucherstatus und Adenokarzinom machen eine onkogene Treiberalteration plausibel, beweisen sie aber nicht.":"Vârsta tânără, statutul de nefumătoare și adenocarcinomul fac plauzibilă o alterare driver oncogenă, dar nu o dovedesc.","Klinische Plausibilität steuert die Aufmerksamkeit; die Diagnose entsteht aus Methodik und Befund.":"Plausibilitatea clinică orientează atenția; diagnosticul rezultă din metodă și rezultat.","Externer Befund":"Rezultat extern","DNA-NGS: EGFR, KRAS, BRAF, MET-Exon-14 und ERBB2 ohne relevante Alteration. Der Methodenteil beschreibt keine validierte breite RNA-Fusionsanalyse.":"NGS ADN: EGFR, KRAS, BRAF, MET exon 14 și ERBB2 fără alterări relevante. Secțiunea de metodă nu descrie nicio analiză largă validată a fuziunilor prin ARN.","'Negativ' ist nur so breit wie der verwendete Assay.":"«Negativ» este doar atât de cuprinzător cât este testul utilizat.","Leberbiopsie mit 35–40 % Tumor, acht ungefärbte Schnitte. RNA-QC ist grenzwertig bis ausreichend.":"Biopsie hepatică cu 35–40 % tumoră, opt secțiuni necolorate. QC ARN este la limită până la suficient.","Jetzt ist eine gezielte, informationsreiche Ergänzung sinnvoller als serielle Einzeltests.":"O completare țintită, bogată în informație, este acum mai utilă decât testele individuale în serie.","MTB-Druck":"Presiune de timp în MTB","Therapieentscheidung in fünf Tagen; jeder unnötige Zusatzlauf kostet Zeit und Material.":"Decizie terapeutică în cinci zile; fiecare run suplimentar inutil consumă timp și material.","TAT und Material Stewardship gehören zur klinischen Methodenauswahl.":"TAT și gestionarea responsabilă a materialului fac parte din selecția clinică a metodei.","HE/IHC":"HE/IHC","Metastase eines TTF-1-/Napsin-A-positiven pulmonalen Adenokarzinoms.":"Metastază a unui adenocarcinom pulmonar TTF-1/Napsin A pozitiv.","DNA-NGS extern":"NGS ADN extern","Kein relevanter SNV/Indel-Treiber; Fusionsabdeckung nicht ausreichend dokumentiert.":"Fără driver SNV/indel relevant; acoperirea fuziunilor nu este documentată adecvat.","RNA-QC":"QC ARN","RNA ist nicht perfekt, aber für einen zielgerichteten Fusionsassay noch verwertbar.":"ARN-ul nu este perfect, dar rămâne utilizabil pentru un test țintit de fuziuni.","Nur acht ungefärbte Schnitte verbleiben.":"Au mai rămas doar opt secțiuni necolorate.","TAT-Ziel fünf Tage bis MTB.":"Țintă TAT: cinci zile până la MTB.","Eine breite serielle FISH-Strategie würde mehrere Einzelansätze und Vorannahmen benötigen.":"O strategie largă de FISH seriat ar necesita mai multe teste individuale și ipoteze prealabile.","Ein erneutes DNA-only-Panel kann denselben methodischen blinden Fleck reproduzieren.":"Repetarea unui panel doar ADN poate reproduce același punct orb metodologic.","Was bedeutet der externe Satz 'kein therapeutisch relevanter Treiber nachweisbar' in diesem Fall?":"Ce înseamnă în acest caz afirmația externă «nu s-a detectat niciun driver relevant terapeutic»?","Alle relevanten Treiber einschließlich Fusionen sind sicher ausgeschlossen.":"Toți driverii relevanți, inclusiv fuziunile, au fost excluși cu certitudine.","Er gilt nur innerhalb der validierten DNA-Assaygrenzen; die Fusionsfrage bleibt offen.":"Este valabilă numai în limitele validate ale testului ADN; întrebarea privind fuziunile rămâne deschisă.","Bei Nie-Rauchern ist ein negativer Befund grundsätzlich falsch.":"La nefumători, un rezultat negativ este întotdeauna fals.","Er bedeutet automatisch, dass jetzt jede Fusion einzeln per FISH getestet werden muss.":"Înseamnă automat că fiecare fuziune trebuie testată acum individual prin FISH.","Ein negativer molekularer Befund ist immer an die analytische Abdeckung der verwendeten Methode gebunden.":"Un rezultat molecular negativ este întotdeauna legat de acoperirea analitică a metodei utilizate.","Welche Ergänzung beantwortet die offene breite Fusionsfrage am effizientesten?":"Ce test suplimentar răspunde cel mai eficient întrebării largi deschise privind fuziunile?","Breites RNA-basiertes Fusionspanel":"Panel larg de fuziuni bazat pe ARN","Dasselbe DNA-only-Panel noch einmal":"Același panel doar ADN încă o dată","Eine einzelne ALK-FISH als vollständiger Ersatz":"Un singur FISH ALK ca înlocuitor complet","Keine Ergänzung, weil die Histologie bereits eindeutig ist":"Fără testare suplimentară deoarece histologia este deja neechivocă","RNA-NGS kann mehrere exprimierte Fusionsereignisse parallel erfassen und ist für diese offene Fragestellung besonders geeignet.":"NGS ARN poate detecta în paralel mai multe evenimente de fuziune exprimate și este deosebit de potrivit pentru această întrebare deschisă.","Wann bleibt FISH in diesem Fall sinnvoll?":"Când rămâne util FISH în acest caz?","Bei konkreter Genhypothese als schnelle/orthogonale Bestätigung":"Pentru o ipoteză genică specifică, ca confirmare rapidă/ortogonală","Wenn RNA nicht verwertbar ist und ein gezielter Rearrangement-Nachweis benötigt wird":"Când ARN-ul nu este utilizabil și este necesară detectarea țintită a unei rearanjări","Als universell umfassender Ersatz für eine breite RNA-Fusionsanalyse":"Ca înlocuitor universal și cuprinzător pentru analiza largă a fuziunilor prin ARN","Zur sicheren Bestimmung jedes Fusionspartners":"Pentru determinarea sigură a fiecărui partener de fuziune","FISH ist für gezielte Rearrangement-Fragen nützlich, aber meist weniger breit und partnerinformativ als RNA-basierte Verfahren.":"FISH este util pentru întrebări țintite privind rearanjările, dar de obicei este mai puțin larg și oferă mai puține informații despre partener decât metodele bazate pe ARN.","Entscheiden Sie, ob der externe DNA-negative Befund als vollständig akzeptiert werden kann und welche Ergänzung jetzt mit dem verbliebenen Material die größte klinische Information liefert.":"Decideți dacă rezultatul extern negativ la ADN poate fi acceptat ca fiind complet și ce test suplimentar oferă acum cea mai mare informație clinică din materialul rămas.","Methodenteil des externen DNA-Befunds prüfen und die unzureichend geklärte Fusionsabdeckung benennen.":"Revizuiți secțiunea de metodă a rezultatului ADN extern și menționați acoperirea insuficient clarificată a fuziunilor.","RNA-basiertes Fusionspanel priorisieren.":"Prioritizați un panel de fuziuni bazat pe ARN.","Material aus dem markierten Tumorareal gezielt für RNA aufarbeiten.":"Prelucrați materialul din zona tumorală marcată în mod specific pentru ARN.","FISH nur bei konkreter Hypothese oder nicht verwertbarer RNA als gezielte Alternative/Bestätigung einsetzen.":"Utilizați FISH doar ca alternativă/confirmare țintită în cazul unei ipoteze concrete sau al ARN-ului neutilizabil.","Im MTB bis zum Abschluss der Fusionsdiagnostik nicht 'treibernegativ' formulieren.":"Nu descrieți cazul drept «negativ pentru driver» în MTB până la finalizarea testării fuziunilor.","Validiertes kombiniertes DNA/RNA-Pan-Panel, wenn es die relevante Fusionsbreite sicher abdeckt und Material/TAT vertretbar sind.":"Un pan-panel combinat ADN/ARN validat, dacă acoperă fiabil spectrul relevant de fuziuni și materialul/TAT sunt acceptabile.","Gezielte RET-FISH, wenn RNA technisch scheitert und die konkrete Hypothese bereits fokussiert ist.":"FISH țintit RET dacă ARN-ul eșuează tehnic și ipoteza concretă este deja focalizată.","DNA-negativ = vollständig negativ":"ADN negativ = complet negativ","Die Aussage überschreitet die analytische Reichweite des verwendeten Assays.":"Afirmația depășește domeniul analitic al testului utilizat.","Serielle FISH für jede denkbare Fusion":"FISH seriat pentru fiecare fuziune posibilă","Material- und zeitintensiv; benötigt Vorannahmen und ist weniger parallelisierbar.":"Consum mare de material și timp; necesită ipoteze prealabile și se paralelizează mai greu.","Noch einmal dasselbe DNA-only-Panel":"Repetați același panel doar ADN","Wiederholung behebt keinen systematischen Assay-Blindspot.":"Repetarea nu corectează un punct orb sistematic al testului.","Der 'treibernegative' Tumor ist nicht treibernegativ":"Tumora «negativă pentru driver» nu este negativă pentru driver","Das RNA-Fusionspanel detektiert eine exprimierte KIF5B::RET-Fusion. Eine anschließende gezielte RET-FISH bestätigt ein Rearrangement. Der zunächst geplante nicht zielgerichtete Therapieweg muss im MTB neu bewertet werden.":"Panelul de fuziuni ARN detectează o fuziune KIF5B::RET exprimată. FISH țintit ulterior pentru RET confirmă o rearanjare. Calea terapeutică nețintită planificată inițial trebuie reevaluată în MTB.","Der Fehler lag nicht in der Qualität des ersten DNA-Laufs, sondern in der zu breiten Interpretation eines methodisch begrenzten Negativbefunds.":"Eroarea nu a fost calitatea primului run ADN, ci interpretarea prea largă a unui rezultat negativ limitat metodologic.","RNA schließt die offene Lücke":"ARN-ul închide lacuna deschisă","KIF5B::RET-Fusion nachweisbar; DNA-SNV/Indel-Profil ohne weiteren relevanten Treiber.":"Fuziune KIF5B::RET detectată; profil ADN SNV/indel fără alt driver relevant.","Sehr gut: Assaygrenze erkannt, passende Methode ergänzt, klinisch entscheidenden Treiber gefunden.":"Foarte bine: limita testului recunoscută, metodă adecvată adăugată, driver clinic decisiv identificat.","DNA-only bleibt Endpunkt":"Doar ADN rămâne punctul final","Kein SNV/Indel-Treiber; Fusionsstatus bleibt methodisch unzureichend geklärt.":"Fără driver SNV/indel; statusul fuziunilor rămâne insuficient clarificat metodologic.","Der Befund klingt abgeschlossen, ist es aber nicht.":"Raportul pare complet, dar nu este.","Einzel-FISH":"FISH pentru o singură genă","Eine gezielte Einzel-FISH kann ein bestimmtes Rearrangement beantworten, lässt andere Fusionsklassen offen.":"Un FISH țintit unic poate răspunde unei întrebări specifice privind rearanjarea, dar lasă deschise alte clase de fuziuni.","Bei fokussierter Hypothese sinnvoll, als breite Erststrategie unvollständig.":"Utilă pentru o ipoteză focalizată, incompletă ca strategie largă inițială.","RNA ausreichend":"ARN suficient","Breites RNA-Fusionspanel durchführen.":"Efectuați un panel larg de fuziuni ARN.","Direkter Nachweis KIF5B::RET und vollständige MTB-Einordnung.":"Detectare directă KIF5B::RET și interpretare completă în MTB.","RNA nicht verwertbar":"ARN neutilizabil","Gezielte FISH/alternatives validiertes Material erwägen.":"Luați în considerare FISH țintit/material alternativ validat.","Fragestellung wird fokussiert weiterverfolgt statt vorschnell geschlossen.":"Întrebarea este urmărită focalizat, în loc să fie închisă prematur.","Nur DNA ausgewählt":"Selectat doar ADN","Fusionsdiagnostik nachfordern.":"Solicitați testarea fuziunilor.","Fall ist rettbar, aber TAT und Score verschlechtern sich.":"Cazul poate fi salvat, dar TAT și scorul se înrăutățesc.","Ein negativer Befund ist kein universeller biologischer Zustand, sondern ein methodisch begrenztes Messergebnis.":"Un rezultat negativ nu este o stare biologică universală, ci un rezultat de măsurare limitat de metodă.","RNA-basierte Verfahren sind bei vielen Fusionsfragen besonders wertvoll.":"Metodele bazate pe ARN sunt deosebit de valoroase pentru multe întrebări privind fuziunile.","FISH bleibt relevant, wenn die Frage gezielt ist oder RNA scheitert.":"FISH rămâne relevant atunci când întrebarea este țintită sau ARN-ul eșuează.","Das Wort 'treibernegativ' sollte nur verwendet werden, wenn die relevanten Alterationsklassen tatsächlich adäquat untersucht wurden.":"Termenul «negativ pentru driver» ar trebui utilizat numai atunci când clasele relevante de alterări au fost într-adevăr testate adecvat.","Der externe DNA-Befund darf nicht als vollständiger Treiberausschluss übernommen werden. Die offene Fusionsfrage wird mit einem breiten RNA-basierten Fusionspanel geschlossen. Ergebnis: KIF5B::RET-Fusion. FISH kann gezielt bestätigen oder bei nicht verwertbarer RNA aushelfen.":"Rezultatul ADN extern nu trebuie preluat drept excludere completă a driverilor. Întrebarea deschisă privind fuziunile este clarificată printr-un panel larg de fuziuni bazat pe ARN. Rezultat: fuziune KIF5B::RET. FISH poate confirma țintit sau poate servi ca alternativă dacă ARN-ul nu este utilizabil.","Assaygrenze erkannt":"Limita testului recunoscută","RNA-Fusionsdiagnostik priorisiert":"Testarea fuziunilor prin ARN prioritizată","FISH korrekt eingeordnet":"FISH încadrat corect","Kein Overclaim eines negativen DNA-Befunds":"Fără supra-interpretarea unui rezultat ADN negativ","Wann ist DNA-NGS für Fusionen ausreichend?":"Când este suficient NGS ADN pentru fuziuni?","Welche Informationen liefert RNA zusätzlich zur strukturellen Umlagerung?":"Ce informații oferă ARN-ul în plus față de rearanjarea structurală?","Wie sollte ein pathologischer Negativbefund formuliert sein, wenn eine relevante Alterationsklasse nicht sicher abgedeckt ist?":"Cum ar trebui formulat un rezultat negativ de anatomie patologică atunci când o clasă relevantă de alterări nu este acoperită fiabil?","DE master reviewed structure":"Structură master DE revizuită","KIF5B::RET trotz DNA-negativem Vorbericht":"KIF5B::RET în ciuda raportului anterior negativ la ADN","Negativbefunde sind assaygebunden":"Rezultatele negative sunt legate de test","DNA-negativ → Methodencheck → RNA → Fusion":"ADN negativ → verificarea metodei → ARN → fuziune","KRAS-mutiertes NSCLC mit STK11/KEAP1-Kontext → Target, Prognose, Immuntherapie-Kontext korrekt gewichten":"NSCLC mutant KRAS cu context STK11/KEAP1 → ponderarea corectă a țintei, prognosticului și contextului imunoterapiei","KRAS-mutiertes NSCLC mit STK11/KEA…":"NSCLC mutant KRAS cu STK11/KEA…","Thoraxonkologie / MTB":"Oncologie toracică / MTB","66-jähriger Patient mit metastasiertem Lungenadenokarzinom. Das DNA-Panel zeigt KRAS p.G12C sowie pathogene STK11- und KEAP1-Alterationen.":"Pacient de 66 de ani cu adenocarcinom pulmonar metastatic. Panelul ADN arată KRAS p.G12C plus alterări patogene STK11 și KEAP1.","Bedeutet die Ko-Mutationskonstellation, dass Immuntherapie nicht sinnvoll ist? Welche Information ist tatsächlich therapeutisch, welche prognostisch und welche nur biologischer Kontext?":"Înseamnă profilul de co-mutații că imunoterapia nu este utilă? Ce informație este cu adevărat terapeutică, ce este prognostică și ce reprezintă doar context biologic?","Therapieentscheidung im MTB innerhalb einer Woche.":"Decizie terapeutică în MTB în decurs de o săptămână.","35 pack years, vor sechs Jahren aufgehört.":"35 pack-years, s-a oprit din fumat acum șase ani.","Stadium":"Stadiu","Leber-, Nebennieren- und ossäre Metastasen; ECOG 1.":"Metastaze hepatice, suprarenaliene și osoase; ECOG 1.","Vorbehandlung":"Tratament anterior","Keine systemische Therapie im metastasierten Stadium.":"Fără terapie sistemică în stadiul metastatic.","Klinische Falle":"Capcană clinică","Im Vorbericht wurde STK11/KEAP1 bereits als 'Immuntherapie-Resistenzmarker' bezeichnet. Das Tumorboard möchte wissen, ob daraus ein Therapieausschluss folgt.":"Raportul preliminar a etichetat deja STK11/KEAP1 drept «markeri de rezistență la imunoterapie». Tumor board-ul dorește să știe dacă rezultă de aici o excludere terapeutică.","Pulmonales Adenokarzinom mit soliden und azinären Anteilen.":"Adenocarcinom pulmonar cu componente solide și acinare.","TTF-1 positiv, p40 negativ.":"TTF-1 pozitiv, p40 negativ.","PD-L1":"PD-L1","Noch ausstehend.":"În așteptare.","Molekular":"Molecular","KRAS p.G12C, STK11 loss-of-function und KEAP1 loss-of-function; keine klassische EGFR-/ALK-/ROS1-Treiberkonstellation.":"KRAS p.G12C, STK11 loss-of-function și KEAP1 loss-of-function; fără configurație clasică de driver EGFR/ALK/ROS1.","Wie werden KRAS-Targetierbarkeit, adverse Ko-Mutationen und Immuntherapie-Kontext getrennt und zusammengeführt?":"Cum trebuie separate și integrate targetabilitatea KRAS, co-mutațiile adverse și contextul imunoterapiei?","FFPE-Lungenbiopsie mit ca. 45 % Tumoranteil.":"Biopsie pulmonară FFPE cu aprox. 45 % proporție tumorală.","DNA-QC":"QC ADN","ausreichend, Panel vollständig auswertbar.":"suficient, panel complet evaluabil.","9 ungefärbte Schnitte verfügbar.":"Sunt disponibile 9 secțiuni necolorate.","Zusätzliche explorative Biomarker dürfen nicht den Eindruck erzeugen, es gebe einen validierten Einzeltest, der die Immuntherapieentscheidung sicher vorhersagt.":"Biomarkerii exploratori suplimentari nu trebuie să creeze impresia că există un singur test validat care prezice sigur decizia de imunoterapie.","KRAS/STK11/KEAP1-Kontext":"Context KRAS/STK11/KEAP1","PD-L1-Kontext":"Context PD-L1","KRAS/STK11/KEAP1":"KRAS/STK11/KEAP1","KRAS p.G12C sowie pathogene STK11- und KEAP1-loss-of-function-Alterationen. Die Ko-Mutationen markieren eine biologisch ungünstige Subgruppe, sind aber kein eigenständiger binärer Ausschlusstest für Immuntherapie.":"KRAS p.G12C plus alterări patogene loss-of-function STK11 și KEAP1. Co-mutațiile marchează un subgrup biologic nefavorabil, dar nu reprezintă un test binar independent de excludere a imunoterapiei.","PD-L1 TPS 70 %. Hohe Expression ist klinisch relevant, muss aber zusammen mit klinischem Kontext und Ko-Mutationen interpretiert werden.":"PD-L1 TPS 70 %. Expresia ridicată este relevantă clinic, dar trebuie interpretată împreună cu contextul clinic și co-mutațiile.","TMB":"TMB","TMB im intermediären Bereich. Kein Befund, der die komplexe Ko-Mutationskonstellation alleine auflöst.":"TMB în intervalul intermediar. Niciun rezultat care să rezolve singur configurația complexă de co-mutații.","Immun-Kontext-IHC":"IHC pentru context imun","Relativ geringes CD8-positives Infiltrat. Biologisch interessant, aber kein validierter alleiniger Therapieausschlussmarker.":"Infiltrat CD8-pozitiv relativ redus. Interesant biologic, dar nu un marker validat independent de excludere terapeutică.","DNA-QC und Tumoranteil ausreichend; PD-L1 technisch auswertbar.":"QC ADN și proporție tumorală suficiente; PD-L1 evaluabil tehnic.","KRAS p.G12C ist ein potenziell therapeutisch relevanter Genotyp im passenden Behandlungskontext. STK11/KEAP1 sind wichtige adverse biologische/prognostische Ko-Alterationen, dürfen aber nicht als binärer 'kein ICI'-Marker überinterpretiert werden. PD-L1 TPS 70 % bleibt eine eigenständige klinisch relevante Information.":"KRAS p.G12C este un genotip potențial relevant terapeutic în contextul adecvat de tratament. STK11/KEAP1 sunt co-alterări biologice/prognostice adverse importante, dar nu trebuie supra-interpretate drept markeri binari «fără ICI». PD-L1 TPS 70 % rămâne o informație clinică relevantă independentă.","Teilbefund: KRAS/Ko-Mutationen oder PD-L1 fehlen. Ohne beide Ebenen ist eine ausgewogene MTB-Einordnung nicht möglich.":"Rezultat parțial: lipsesc KRAS/co-mutațiile sau PD-L1. Fără ambele niveluri, nu este posibilă o interpretare echilibrată în MTB.","KRAS p.G12C als Genotyp mit möglicher Target-Relevanz im passenden Therapiekontext benennen":"Menționați KRAS p.G12C ca genotip cu posibilă relevanță de target în contextul terapeutic adecvat","STK11/KEAP1 als adverse Kontextmarker, nicht als absoluten ICI-Ausschluss darstellen":"Descrieți STK11/KEAP1 ca markeri de context advers, nu ca excluderi absolute pentru ICI","PD-L1 separat und nicht durch Ko-Mutationen 'weginterpretieren'":"Raportați PD-L1 separat și nu îl «anulați prin interpretare» din cauza co-mutațiilor","Prognostische Assoziation und prädiktive Therapieentscheidung sprachlich trennen":"Separați în formulare asocierea prognostică de decizia terapeutică predictivă","Optimale Lösung: KRAS, STK11/KEAP1 und PD-L1 auf getrennten Evidenzebenen berichten und im MTB integrieren; keine einzelne Ko-Mutation als absoluten Therapieausschluss verwenden.":"Soluție optimă: raportați KRAS, STK11/KEAP1 și PD-L1 pe niveluri separate de dovezi și integrați-le în MTB; nu utilizați nicio co-mutație ca excludere terapeutică absolută.","Immunescape":"Evadare imună","Phase":"Fază","KRAS/STK11/KEAP1-NSCLC: Kontextmarker sind kein Therapie-Ausschalter":"NSCLC KRAS/STK11/KEAP1: markerii de context nu sunt întrerupătoare terapeutice","KRAS-Targetierbarkeit, STK11/KEAP1-Kontext und PD-L1 auf getrennten Evidenzebenen einordnen.":"Încadrați targetabilitatea KRAS, contextul STK11/KEAP1 și PD-L1 pe niveluri separate de dovezi.","Prognostische bzw. assoziierte Resistenzsignale nicht als validierten binären prädiktiven Ausschlusstest formulieren.":"Nu formulați semnalele prognostice sau asociate rezistenței ca pe un test predictiv binar validat de excludere.","Widersprüchliche Biomarkerinformationen in einer balancierten MTB-Aussage integrieren.":"Integrați informațiile conflictuale despre biomarkeri într-o concluzie echilibrată pentru MTB.","Explorative TME-Marker von klinisch etablierten Routineentscheidungen trennen.":"Separați markerii exploratori ai TME de deciziile de rutină consacrate clinic.","Im Thorax-MTB liegt ein Befund mit drei fett markierten Genen: KRAS, STK11 und KEAP1. Der Vorbericht bezeichnet die beiden Ko-Mutationen bereits als 'Immuntherapie-Resistenzmarker'. Gleichzeitig ist PD-L1 noch nicht bestimmt. Die klinische Frage lautet nicht nur, was mutiert ist, sondern ob aus dieser biologisch ungünstigen Konstellation wirklich ein Therapieverbot abgeleitet werden darf.":"În MTB-ul toracic, raportul conține trei gene evidențiate: KRAS, STK11 și KEAP1. Raportul preliminar numește deja cele două co-mutații «markeri de rezistență la imunoterapie». În același timp, PD-L1 nu a fost încă determinat. Întrebarea clinică nu este doar ce este mutat, ci dacă această configurație biologic nefavorabilă justifică într-adevăr o interdicție terapeutică.","66-jähriger Patient, ehemaliger starker Raucher, metastasiertes Lungenadenokarzinom mit Leber-, Nebennieren- und Knochenmetastasen, ECOG 1. DNA-NGS zeigt KRAS p.G12C plus pathogene STK11- und KEAP1-Alterationen. Das MTB möchte Target-Relevanz, Prognose und Immuntherapie-Kontext sauber gewichten.":"Pacient de 66 de ani, fost fumător important, cu adenocarcinom pulmonar metastatic cu metastaze hepatice, suprarenaliene și osoase, ECOG 1. NGS ADN arată KRAS p.G12C plus alterări patogene STK11 și KEAP1. MTB-ul dorește să evalueze corect relevanța de target, prognosticul și contextul imunoterapiei.","Genotyp":"Genotip","KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.":"KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.","Nicht jede genetische Information erfüllt dieselbe klinische Funktion.":"Nu orice informație genetică îndeplinește aceeași funcție clinică.","Klinik":"Situație clinică","Hohe Tumorlast, aber aktuell stabil; keine vorangegangene systemische Therapie im metastasierten Stadium.":"Încărcătură tumorală mare, dar momentan stabilă; fără terapie sistemică anterioară în stadiul metastatic.","Therapieentscheidungen bleiben klinisch eingebettet.":"Deciziile terapeutice rămân integrate în contextul clinic.","Vorbericht":"Raport preliminar","STK11/KEAP1 wurden als 'ICI-resistent' bezeichnet.":"STK11/KEAP1 au fost etichetate drept «rezistente la ICI».","Assoziation mit ungünstigen Outcomes ist nicht dasselbe wie ein validierter absoluter Ausschlussmarker.":"Asocierea cu rezultate nefavorabile nu este același lucru cu un marker absolut de excludere validat.","Offene Information":"Informație încă deschisă","PD-L1 steht noch aus; zusätzliche TMB-/TIL-Daten könnten biologischen Kontext liefern, sind aber kein Ersatz für klinische Evidenz.":"PD-L1 este încă în așteptare; date suplimentare TMB/TIL pot oferi context biologic, dar nu înlocuiesc dovezile clinice.","Mehr Biomarker bedeutet nicht automatisch eine klarere Therapieentscheidung.":"Mai mulți biomarkeri nu produc automat o decizie terapeutică mai clară.","KRAS p.G12C; pathogene STK11- und KEAP1-loss-of-function-Alterationen.":"KRAS p.G12C; alterări patogene loss-of-function STK11 și KEAP1.","TTF-1-positives pulmonales Adenokarzinom.":"Adenocarcinom pulmonar TTF-1 pozitiv.","Noch nicht bestimmt.":"Nu a fost încă determinat.","Ausreichendes FFPE-Material; keine akute Materialknappheit.":"Material FFPE suficient; fără deficit acut de material.","Die eigentliche Grenze ist interpretativ: zusätzliche Marker dürfen nicht als stärker validiert erscheinen, als sie sind.":"Limita reală este interpretativă: markerii suplimentari nu trebuie să pară mai puternic validați decât sunt în realitate.","TMB/CD8-IHC können Kontext liefern, sind in diesem Fall aber nicht als zwingende Entscheidungsmarker definiert.":"TMB/IHC CD8 pot oferi context, dar nu sunt definite ca markeri obligatorii de decizie în acest caz.","Welche Aussagen sind fachlich angemessen?":"Ce afirmații sunt corecte profesional?","KRAS p.G12C kann im geeigneten Therapiekontext targetrelevant sein.":"KRAS p.G12C poate fi relevant ca țintă în contextul terapeutic adecvat.","STK11/KEAP1 kennzeichnen eine biologisch/prognostisch ungünstige Subgruppe.":"STK11/KEAP1 identifică un subgrup biologic/prognostic nefavorabil.","STK11 oder KEAP1 schließen Immuntherapie grundsätzlich aus.":"STK11 sau KEAP1 exclud în principiu imunoterapia.","PD-L1 bleibt eine eigenständige klinisch relevante Information.":"PD-L1 rămâne o informație clinică relevantă independentă.","Die Marker besitzen unterschiedliche Rollen; STK11/KEAP1 sind kein binärer ICI-Ausschluss.":"Markerii au roluri diferite; STK11/KEAP1 nu sunt excluderi binare pentru ICI.","PD-L1 ergibt später TPS 70 %. Wie ist der Befund zu integrieren?":"PD-L1 revine ulterior cu TPS 70 %. Cum trebuie integrat rezultatul?","Ignorieren, weil STK11/KEAP1 wichtiger sind.":"Ignorați-l deoarece STK11/KEAP1 sunt mai importante.","PD-L1 70 % garantiert eine sehr gute ICI-Antwort.":"PD-L1 70 % garantează un răspuns foarte bun la ICI.","Als relevante positive Information berichten, aber zusammen mit klinischem Kontext und der adversen Ko-Mutationsbiologie interpretieren.":"Raportați-l ca informație pozitivă relevantă, dar interpretați-l împreună cu contextul clinic și biologia adversă a co-mutațiilor.","STK11/KEAP1 und PD-L1 heben sich gegenseitig auf; deshalb keine Aussage möglich.":"STK11/KEAP1 și PD-L1 se anulează reciproc; prin urmare nu este posibilă nicio concluzie.","Widersprüchliche Biomarker werden integriert, nicht gegeneinander 'verrechnet'.":"Biomarkerii conflictuali sunt integrați, nu «scăzuți» unul din altul.","Welche Rolle haben TMB oder CD8/TIL-IHC hier?":"Ce rol au aici TMB sau IHC CD8/TIL?","Optionaler biologischer Kontext; kein alleiniger validierter Therapieausschluss.":"Context biologic opțional; nu o excludere terapeutică independentă validată.","Zwingend erforderlich, bevor überhaupt eine Therapie diskutiert werden darf.":"Obligatoriu înainte ca orice tratament să poată fi măcar discutat.","Sie ersetzen PD-L1 vollständig.":"Înlocuiesc complet PD-L1.","Sie sind in der Tumorbiologie grundsätzlich bedeutungslos.":"Sunt fundamental irelevanți în biologia tumorală.","Die Zusatzmarker können das biologische Bild vertiefen, lösen die klinische Evidenzfrage aber nicht allein.":"Markerii suplimentari pot aprofunda imaginea biologică, dar nu rezolvă singuri întrebarea privind dovezile clinice.","Formulieren Sie eine MTB-Empfehlung, die KRAS p.G12C, STK11/KEAP1 und PD-L1 korrekt gewichtet, ohne aus einer Ko-Mutation ein nicht validiertes Therapieverbot zu machen.":"Formulați o recomandare MTB care ponderază corect KRAS p.G12C, STK11/KEAP1 și PD-L1 fără a transforma o co-mutație într-o interdicție terapeutică nevalidată.","KRAS p.G12C als eigenständigen Genotyp mit potenzieller Target-Relevanz im passenden Behandlungskontext benennen.":"Menționați KRAS p.G12C ca genotip independent cu potențială relevanță de target în contextul terapeutic adecvat.","STK11/KEAP1 als adverse biologische/prognostische Ko-Alterationen beschreiben.":"Descrieți STK11/KEAP1 ca co-alterări biologice/prognostice adverse.","PD-L1 bestimmen und separat berichten.":"Determinați și raportați PD-L1 separat.","Aus STK11/KEAP1 keinen absoluten Immuntherapieausschluss ableiten.":"Nu derivați o excludere absolută a imunoterapiei din STK11/KEAP1.","Optional erhobene TMB/TIL-Daten als Kontext, nicht als übergeordneten Entscheidungsmarker kennzeichnen.":"Etichetați datele TMB/TIL obținute opțional ca informație de context, nu ca marker decizional superior.","Breites DNA-Panel statt fokussierter KRAS/STK11/KEAP1-Analyse, wenn es bereits Bestandteil der vollständigen NSCLC-Profilierung ist.":"Panel ADN larg în locul unei analize focalizate KRAS/STK11/KEAP1 atunci când face deja parte din profilarea completă a NSCLC.","TMB oder Immun-Kontext-IHC als zusätzliche Lehr-/Kontextinformation, solange daraus keine binäre Therapieentscheidung konstruiert wird.":"TMB sau IHC de context imun ca informație didactică/de context suplimentară, atât timp cât nu se construiește din aceasta o decizie terapeutică binară.","STK11/KEAP1 = kein ICI":"STK11/KEAP1 = fără ICI","Aus einer adversen Assoziation wird fälschlich ein absoluter prädiktiver Ausschlussmarker.":"O asociere nefavorabilă este transformată în mod eronat într-un marker predictiv absolut de excludere.","PD-L1 hoch = sichere Antwort":"PD-L1 crescut = răspuns garantat","Auch ein etablierter Biomarker ist kein individuelles Response-Versprechen.":"Nici măcar un biomarker consacrat nu garantează răspunsul individual.","Jeden Kontextmarker erzwingen":"Forțarea fiecărui marker contextual","Mehr Messwerte erhöhen nicht automatisch die klinische Entscheidungsqualität.":"Mai multe măsurători nu cresc automat calitatea deciziei clinice.","Der 'resistente' Tumor hat PD-L1 TPS 70 %":"Tumora «rezistentă» are PD-L1 TPS 70 %","Die nachgeforderte PD-L1-IHC zeigt eine hohe Expression von 70 %. Eine optionale Immun-Kontext-IHC zeigt gleichzeitig nur ein geringes CD8-Infiltrat. Statt einer eindeutigen Antwort entsteht ein scheinbarer Widerspruch: positive etablierte Information, adverse Ko-Mutationsbiologie und ein eher 'cold' wirkendes Mikromilieu.":"IHC PD-L1 solicitată arată o expresie crescută de 70 %. O IHC opțională pentru contextul imun arată în același timp doar un infiltrat CD8 redus. În locul unui răspuns clar apare o contradicție aparentă: informație pozitivă consacrată, biologie nefavorabilă a comutațiilor și un micromediu mai degrabă «rece».","Der Fall zwingt dazu, Biomarker nach Evidenzebene zu gewichten statt sie zu einem simplen Plus/Minus-Score zu verrechnen.":"Cazul impune ponderarea biomarkerilor în funcție de nivelul dovezilor, nu reducerea lor la un simplu scor plus/minus.","Evidenzebenen getrennt":"Niveluri de dovezi separate","KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70 %. Ko-Mutationen werden als adverse Kontextmarker berichtet, nicht als absoluter ICI-Ausschluss.":"KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70 %. Comutațiile sunt raportate ca markeri contextuali nefavorabili, nu ca criterii absolute de excludere a ICI.","Sehr gute, klinisch belastbare Integration.":"Integrare foarte bună și clinic robustă.","STK11/KEAP1 verbieten ICI":"STK11/KEAP1 interzic ICI","Die Ko-Mutationen werden als definitive prädiktive Resistenzmarker ausgegeben.":"Comutațiile sunt raportate ca markeri predictivi definitivi de rezistență.","Overcalling: prognostisch/assoziativ wird mit binär prädiktiv verwechselt.":"Supra-interpretare: dovezile prognostice/asociative sunt confundate cu dovezi predictive binare.","Nur PD-L1 zählt":"Contează doar PD-L1","PD-L1 70 % wird ohne Genotyp- und Ko-Mutationskontext als eindeutige Antwort dargestellt.":"PD-L1 70 % este prezentat ca răspuns fără echivoc, fără contextul genotipului și al comutațiilor.","Unvollständige Integration und zu starke Individualprognose.":"Integrare incompletă și prognostic individual formulat excesiv de categoric.","PD-L1 fehlt":"PD-L1 lipsește","PD-L1 ergänzen.":"Completați PD-L1.","Etablierte klinische Information steht für die MTB-Integration zur Verfügung.":"Informația clinică consacrată este disponibilă pentru integrarea în MTB.","TMB/TILs gewählt":"TMB/TIL selectate","Als optionalen Kontext berichten.":"Raportați ca informație contextuală opțională.","Kein zusätzlicher binärer Therapieentscheid aus diesen Daten.":"Din aceste date nu trebuie derivată nicio decizie terapeutică binară suplimentară.","STK11/KEAP1 als Ausschluss formuliert":"STK11/KEAP1 formulate ca excludere","Befund sprachlich korrigieren.":"Corectați formularea raportului.","Prognostische/assoziierte Evidenz wird von prädiktiver Aussage getrennt.":"Dovezile prognostice/asociative sunt separate de afirmațiile predictive.","Ein molekulares Panel liefert nicht automatisch Marker gleicher klinischer Wertigkeit.":"Un panel molecular nu furnizează automat markeri cu aceeași valoare clinică.","STK11/KEAP1 sind wichtige adverse Kontextinformationen, aber keine simplen ICI-Ausschalter.":"STK11/KEAP1 reprezintă informații contextuale nefavorabile importante, dar nu simple comutatoare care opresc ICI.","PD-L1 bleibt relevant, ohne individuelle Antwort zu garantieren.":"PD-L1 rămâne relevant fără a garanta un răspuns individual.","Gute MTB-Kommunikation macht die Evidenzebene jeder Aussage sichtbar.":"O bună comunicare în MTB face vizibil nivelul dovezilor din spatele fiecărei afirmații.","KRAS p.G12C wird als eigenständiger targetrelevanter Genotyp im passenden Therapiekontext berichtet. STK11/KEAP1 werden als adverse biologische/prognostische Ko-Alterationen eingeordnet, nicht als absolutes ICI-Verbot. PD-L1 TPS 70 % bleibt klinisch relevant. TMB/TILs können Kontext liefern, dürfen aber nicht überinterpretiert werden.":"KRAS p.G12C este raportat ca genotip independent relevant pentru o terapie țintită în contextul terapeutic adecvat. STK11/KEAP1 sunt încadrate ca modificări concomitente biologice/prognostice nefavorabile, nu ca interdicție absolută a ICI. PD-L1 TPS 70 % rămâne relevant clinic. TMB/TIL pot oferi context, dar nu trebuie supra-interpretate.","Keine binäre STK11/KEAP1-Überinterpretation":"Fără supra-interpretare binară a STK11/KEAP1","PD-L1 integriert":"PD-L1 integrat","KRAS-Targetebene getrennt":"Nivelul de target KRAS separat","Zusatzmarker limitiert formuliert":"Markerii suplimentari formulați cu limitări","Wann wird ein prognostischer Marker prädiktiv?":"Când devine predictiv un marker prognostic?","Wie sollte ein Befund formuliert sein, damit die Onkologie die Evidenzebene sofort erkennt?":"Cum trebuie formulat un raport astfel încât oncologia să recunoască imediat nivelul dovezilor?","Welche Rolle könnten Ko-Mutationen künftig für Therapiestratifizierung spielen, ohne heutige Routineentscheidungen vorwegzunehmen?":"Ce rol ar putea avea comutațiile în viitoarea stratificare terapeutică fără a anticipa nejustificat deciziile de rutină de astăzi?","PD-L1 70 % trotz STK11/KEAP1":"PD-L1 70 % în ciuda STK11/KEAP1","Biomarker nach Evidenzebene gewichten":"Ponderarea biomarkerilor după nivelul dovezilor","Genotyp → Ko-Mutationen → PD-L1 → integrierte Aussage":"Genotip → comutații → PD-L1 → concluzie integrată","Melanom: BRAF V600 und Immuntherapie-Sequenz → Schnelle TKI-Therapie vs. Immuncheckpoint-Strategie":"Melanom: BRAF V600 și secvențierea imunoterapiei → terapie țintită rapidă vs. strategie cu inhibitori ai checkpointurilor imune","Melanom: BRAF V600 und Immuntherap…":"Melanom: BRAF V600 și secvențierea imunoterap…","Dermatoonkologie / Interdisziplinäres Tumorboard":"Dermato-oncologie / Tumor Board interdisciplinar","51-jähriger Patient mit neu metastasiertem kutanem Melanom, pulmonalen und hepatischen Metastasen.":"Pacient de 51 de ani cu melanom cutanat nou metastatic, cu metastaze pulmonare și hepatice.","Liegt eine BRAF-V600-Alteration vor und wie beeinflusst sie die Sequenz zwischen Immuncheckpoint- und BRAF/MEK-Strategie?":"Este prezentă o alterare BRAF V600 și cum influențează aceasta secvența dintre strategia cu inhibitori ai checkpointurilor imune și strategia BRAF/MEK?","Systemische Therapie soll innerhalb weniger Tage beginnen.":"Tratamentul sistemic trebuie început în câteva zile.","Performance":"Status de performanță","ECOG 0–1, zunächst klinisch stabil.":"ECOG 0–1, inițial stabil clinic.","Tumorlast":"Încărcătură tumorală","Mehrere Lebermetastasen, LDH moderat erhöht, keine initialen neurologischen Symptome.":"Metastaze hepatice multiple, LDH moderat crescut, fără simptome neurologice inițiale.","Entscheidungsfalle":"Capcană decizională","Der Nachweis einer BRAF-V600-Mutation entscheidet nicht automatisch über die erste Therapiesequenz; klinisches Tempo, ZNS-Situation, Steroidbedarf und Eignung für Immuntherapie sind mitentscheidend.":"Detectarea unei mutații BRAF V600 nu stabilește automat prima secvență terapeutică; ritmul clinic, statusul SNC, necesarul de corticosteroizi și eligibilitatea pentru imunoterapie sunt de asemenea decisive.","Metastase eines malignen Melanoms.":"Metastază de melanom malign.","SOX10 und S100 positiv, Melan-A fokal positiv.":"SOX10 și S100 pozitive, Melan-A focal pozitiv.","Molekulare Kernfrage":"Întrebarea moleculară centrală","BRAF V600 muss rasch geklärt werden, damit beide strategischen Optionen realistisch bewertet werden können.":"BRAF V600 trebuie clarificat rapid pentru ca ambele opțiuni strategice să poată fi evaluate realist.","Nicht die Kernfrage":"Nu este întrebarea centrală","PD-L1, TMB oder TILs sind in diesem Fall keine einfachen Schalter für die Sequenzentscheidung.":"PD-L1, TMB sau TIL nu sunt comutatoare simple pentru decizia de secvențiere în acest caz.","FFPE-Lebermetastase, Block L4.":"Metastază hepatică FFPE, bloc L4.","ca. 60 %, geringe Nekrose.":"aprox. 60 %, necroză redusă.","gut; rascher BRAF-Test technisch problemlos möglich.":"bună; testarea rapidă BRAF este tehnic fără probleme.","10 ungefärbte Schnitte verfügbar.":"Sunt disponibile 10 secțiuni necolorate.","Breite Zusatzdiagnostik darf die dringliche BRAF-Klärung nicht verzögern.":"Testarea suplimentară extinsă nu trebuie să întârzie clarificarea urgentă a BRAF.","BRAF V600-Status":"Status BRAF V600","BRAF V600":"BRAF V600","BRAF p.V600E nachweisbar. Damit ist eine BRAF/MEK-basierte Therapieoption grundsätzlich vorhanden.":"BRAF p.V600E detectabil. Prin urmare, există în principiu o opțiune terapeutică bazată pe BRAF/MEK.","Melanom-IO-Kontext":"Context IO al melanomului","Immunhistologischer Kontext ohne eindeutigen Ausschlussbefund. Die Sequenzentscheidung bleibt primär klinisch-strategisch und wird nicht durch einen einzelnen IHC-Marker festgelegt.":"Context imunohistologic fără un criteriu clar de excludere. Decizia de secvențiere rămâne în primul rând clinico-strategică și nu este stabilită de un singur marker IHC.","TMB erhöht. Dies ersetzt weder die BRAF-Testung noch die klinische Sequenzentscheidung.":"TMB crescut. Acest lucru nu înlocuiește nici testarea BRAF, nici decizia clinică privind secvența terapeutică.","Tumoranteil und DNA-Qualität sind gut; BRAF-V600-Status ist rasch und belastbar bestimmbar.":"Fracția tumorală și calitatea ADN sunt bune; statusul BRAF V600 poate fi determinat rapid și fiabil.","BRAF p.V600E ist nachweisbar und eröffnet eine BRAF/MEK-Option. Bei zunächst klinisch stabilem, immuntherapiefähigem Patienten spricht die Evidenz häufig für eine Immuntherapie-first-Strategie; bei rascher klinischer Verschlechterung oder notwendigem schnellen Tumoransprechen kann sich die Gewichtung zugunsten einer zielgerichteten Therapie verschieben.":"BRAF p.V600E este detectabil și oferă o opțiune BRAF/MEK. La un pacient inițial stabil clinic și eligibil pentru imunoterapie, dovezile favorizează adesea o strategie cu imunoterapie prima; în cazul deteriorării clinice rapide sau al necesității unui răspuns tumoral rapid, balanța se poate deplasa spre terapia țintită.","Teilbefund: Ohne geklärten BRAF-V600-Status fehlt eine zentrale Voraussetzung für die Sequenzplanung. Zusätzliche IO-Kontextmarker ersetzen diese Klärung nicht.":"Rezultat parțial: fără clarificarea statusului BRAF V600 lipsește o condiție centrală pentru planificarea secvenței. Markerii suplimentari de context IO nu înlocuiesc această clarificare.","BRAF V600 als Voraussetzung für eine BRAF/MEK-Option benennen":"Menționați BRAF V600 ca premisă pentru o opțiune BRAF/MEK","Therapiesequenz nicht allein aus dem Mutationsstatus ableiten":"Nu deduceți secvența terapeutică doar din statusul mutațional","Tumorlast, klinisches Tempo, ZNS-Beteiligung/Steroidbedarf und Immuntherapiefähigkeit berücksichtigen":"Luați în considerare încărcătura tumorală, ritmul clinic, afectarea SNC/necesarul de corticosteroizi și eligibilitatea pentru imunoterapie","PD-L1/TMB/TILs nicht als simplen Sequenzschalter verwenden":"Nu utilizați PD-L1/TMB/TIL ca simplu comutator pentru secvență","Optimale Lösung: BRAF V600 rasch klären und anschließend die Sequenz anhand von Evidenz und klinischer Dynamik entscheiden; Mutation vorhanden bedeutet nicht automatisch 'Targeted Therapy zuerst'.":"Soluția optimă: clarificați rapid BRAF V600 și apoi decideți secvența pe baza dovezilor și a dinamicii clinice; prezența mutației nu înseamnă automat «terapie țintită prima».","BRAF":"BRAF","KI":"IA","Melanom":"Melanom","BRAF-V600-Melanom: Die Mutation eröffnet eine Option – die Klinik bestimmt die Sequenz":"Melanom BRAF V600: mutația deschide o opțiune – situația clinică determină secvența","Molekularpathologie / Dermatoonkologie / MTB":"Patologie moleculară / Dermato-oncologie / MTB","BRAF V600 als prädiktiven Marker für eine Target-Option korrekt bestimmen.":"Determinați corect BRAF V600 ca marker predictiv pentru o opțiune de terapie țintită.","Den BRAF-Nachweis nicht mit einer automatischen Targeted-Therapy-first-Entscheidung verwechseln.":"Nu confundați detectarea BRAF cu o decizie automată de terapie țintită prima.","Klinisches Tempo, Tumorlast, ZNS-Beteiligung, Steroidbedarf und Immuntherapiefähigkeit in die Sequenz einbeziehen.":"Integrați ritmul clinic, încărcătura tumorală, afectarea SNC, necesarul de corticosteroizi și eligibilitatea pentru imunoterapie în secvențiere.","PD-L1/TMB/TILs beim Melanom nicht als einfachen Sequenzschalter überinterpretieren.":"Nu supra-interpretați PD-L1/TMB/TIL în melanom ca simplu comutator pentru secvență.","Freitagnachmittag im Melanomboard. Ein 51-jähriger Patient mit neu metastasiertem Melanom ist BRAF noch nicht getestet. Die Onkologie diskutiert bereits zwei sehr unterschiedliche Strategien: zuerst Immuncheckpoint-Therapie mit Aussicht auf langanhaltende Kontrolle oder – falls BRAF V600 positiv – eine BRAF/MEK-Therapie mit typischerweise rascherem Ansprechen. Noch wirkt der Patient klinisch stabil. Die Frage scheint planbar. Zwei Tage später ändert sich die Situation.":"Vineri după-amiază la tumor board-ul pentru melanom. Un pacient de 51 de ani cu melanom nou metastatic nu a fost încă testat pentru BRAF. Oncologia discută deja două strategii foarte diferite: mai întâi terapie cu inhibitori ai checkpointurilor imune, cu perspectiva unui control de durată, sau – dacă BRAF V600 este pozitiv – terapie BRAF/MEK, de regulă cu răspuns mai rapid. Pacientul pare încă stabil clinic. Întrebarea pare planificabilă. Două zile mai târziu, situația se schimbă.","51-jähriger Patient, kutanes Melanom mit Leber- und Lungenmetastasen, ECOG 0–1, moderat erhöhtes LDH. Keine systemische Vorbehandlung. Zunächst keine neurologischen Symptome. Für die Sequenzentscheidung muss der BRAF-V600-Status rasch vorliegen; die endgültige Strategie darf aber nicht allein aus dem Genotyp abgeleitet werden.":"Pacient de 51 de ani, melanom cutanat cu metastaze hepatice și pulmonare, ECOG 0–1, LDH moderat crescut. Fără tratament sistemic anterior. Inițial fără simptome neurologice. Statusul BRAF V600 trebuie să fie disponibil rapid pentru decizia de secvență, dar strategia finală nu trebuie dedusă numai din genotip.","Molekulare Voraussetzung":"Premisă moleculară","Ohne BRAF-V600-Nachweis gibt es keine belastbare Grundlage für eine BRAF/MEK-Strategie.":"Fără detectarea BRAF V600 nu există o bază robustă pentru o strategie BRAF/MEK.","Erst Option nachweisen, dann Sequenz diskutieren.":"Mai întâi demonstrați opțiunea, apoi discutați secvența.","Initiale Klinik":"Situația clinică inițială","ECOG 0–1, systemisch metastasiert, aber zunächst keine akute Organ- oder ZNS-Symptomatik.":"ECOG 0–1, boală metastatică sistemică, dar inițial fără simptome acute de organ sau SNC.","Bei klinischer Stabilität kann Langzeitstrategie stärker gewichtet werden.":"În stabilitate clinică, strategia pe termen lung poate primi o pondere mai mare.","Evidenz zur Sequenz":"Dovezi privind secvențierea","Für viele geeignete Patienten mit BRAF-V600-mutiertem metastasiertem Melanom spricht die randomisierte Sequenzevidenz für Immuntherapie zuerst; dies ist aber keine starre Regel für jede klinische Situation.":"Pentru mulți pacienți eligibili cu melanom metastatic BRAF V600-mutant, dovezile randomizate privind secvența susțin imunoterapia prima; aceasta nu este însă o regulă rigidă pentru orice situație clinică.","Populationsevidenz und individuelle Dringlichkeit müssen zusammengeführt werden.":"Dovezile la nivel populațional și urgența individuală trebuie integrate.","Nicht der Schalter":"Nu este comutatorul","PD-L1, TMB und TILs können biologisch interessant sein, ersetzen aber weder BRAF-Testung noch die klinische Sequenzentscheidung.":"PD-L1, TMB și TIL pot fi interesante biologic, dar nu înlocuiesc nici testarea BRAF, nici decizia clinică privind secvența.","Nicht jedes messbare Immunmerkmal ist ein Routine-Entscheidungstest.":"Nu orice caracteristică imună măsurabilă este un test decizional de rutină.","Histologie/IHC":"Histologie/IHC","Metastase eines SOX10-/S100-positiven malignen Melanoms.":"Metastază a unui melanom malign SOX10-/S100-pozitiv.","Klinik initial":"Situația clinică inițială","Keine symptomatische ZNS-Beteiligung; keine Steroidtherapie.":"Fără afectare simptomatică a SNC; fără terapie cu corticosteroizi.","Material-QC":"QC material","Lebermetastase mit ca. 60 % Tumor; DNA-QC gut.":"Metastază hepatică cu aprox. 60 % tumoră; QC ADN bun.","BRAF-V600-Status muss rasch vorliegen; unnötige Zusatzanalysen dürfen die Entscheidung nicht verzögern.":"Statusul BRAF V600 trebuie să fie disponibil rapid; analizele suplimentare inutile nu trebuie să întârzie decizia.","Therapiesequenz kann nicht aus der Pathologie allein entschieden werden; aktuelle klinische Dynamik muss ins MTB zurückgespielt werden.":"Secvența terapeutică nu poate fi decisă doar de patologie; dinamica clinică actuală trebuie reintegrată în MTB.","PD-L1/TMB/TILs sind nicht als zwingende Sequenzmarker definiert.":"PD-L1/TMB/TIL nu sunt definiți ca markeri obligatorii pentru secvențiere.","Welche molekulare Information muss für die Targeted-Therapy-Option zuerst belastbar vorliegen?":"Ce informație moleculară trebuie să fie mai întâi disponibilă în mod fiabil pentru opțiunea de terapie țintită?","PD-L1 zwingend":"PD-L1 obligatoriu","TMB zwingend":"TMB obligatoriu","CD8/TIL-IHC zwingend":"IHC CD8/TIL obligatorie","BRAF V600 ist die zentrale molekulare Voraussetzung für eine BRAF/MEK-basierte Option.":"BRAF V600 este premisa moleculară centrală pentru o opțiune bazată pe BRAF/MEK.","Welche Faktoren beeinflussen die Sequenzentscheidung zusätzlich zum BRAF-Status?":"Ce factori influențează secvența terapeutică pe lângă statusul BRAF?","Klinisches Progressionstempo und Tumorlast":"Ritmul clinic al progresiei și încărcătura tumorală","ZNS-Beteiligung und neurologische Symptomatik":"Afectarea SNC și simptomatologia neurologică","Steroidbedarf/Immuntherapiefähigkeit":"Necesar de corticosteroizi/eligibilitate pentru imunoterapie","Allgemeinzustand und Eignung für die jeweiligen Regime":"Starea generală și eligibilitatea pentru regimurile respective","Alleiniger PD-L1-Wert als Sequenzschalter":"Valoarea PD-L1 singură ca întrerupător al secvenței","Die Sequenz ist eine klinisch-strategische Entscheidung, nicht nur eine Genotypentscheidung.":"Secvențierea este o decizie clinico-strategică, nu doar o decizie de genotip.","Der Patient ist BRAF V600E-positiv und klinisch stabil. Welche Aussage ist am besten?":"Pacientul este BRAF V600E-pozitiv și stabil clinic. Care afirmație este cea mai corectă?","Für viele geeignete Patienten spricht die Sequenzevidenz für Immuntherapie-first; individuelle Faktoren bleiben entscheidend.":"Pentru mulți pacienți eligibili, dovezile privind secvența susțin imunoterapia prima; factorii individuali rămân decisivi.","BRAF V600E bedeutet zwingend BRAF/MEK zuerst.":"BRAF V600E impune BRAF/MEK prima.","Bei BRAF-Mutation sollte Immuntherapie nicht eingesetzt werden.":"Imunoterapia nu ar trebui utilizată în cazul unei mutații BRAF.","Erst PD-L1 entscheidet, ob BRAF/MEK oder Immuntherapie beginnt.":"Doar PD-L1 decide dacă se începe cu BRAF/MEK sau cu imunoterapie.","Randomisierte Sequenzdaten favorisieren bei vielen geeigneten Patienten Immuntherapie-first, ohne jede dringliche Ausnahmesituation abzudecken.":"Datele randomizate de secvențiere favorizează imunoterapia prima la mulți pacienți eligibili, fără a acoperi fiecare situație urgentă excepțională.","Bestimmen Sie den BRAF-V600-Status und formulieren Sie anschließend eine Sequenzempfehlung, die Evidenz und aktuelle klinische Dynamik ausdrücklich miteinander verknüpft.":"Determinați statusul BRAF V600 și apoi formulați o recomandare de secvențiere care leagă explicit dovezile de dinamica clinică actuală.","BRAF-V600-Testung rasch durchführen.":"Efectuați rapid testarea BRAF V600.","Bei BRAF p.V600E beide prinzipiellen Strategien als verfügbar benennen.":"Dacă BRAF p.V600E este prezent, menționați că ambele strategii principale sunt disponibile.","Bei klinisch stabilem, immuntherapiefähigem Patienten die Evidenz für Immuntherapie-first diskutieren.":"La un pacient stabil clinic și eligibil pentru imunoterapie, discutați dovezile pentru imunoterapie prima.","Vor Therapiebeginn aktuelle ZNS-Situation, Steroidbedarf und Progressionstempo erneut prüfen.":"Înainte de începerea tratamentului, reevaluați statusul actual al SNC, necesarul de corticosteroizi și ritmul progresiei.","Bei akuter Dynamik die Notwendigkeit schnellen Ansprechens neu gewichten.":"În cazul unei dinamici clinice acute, reevaluați ponderea necesității unui răspuns rapid.","Validiertes breites Panel, wenn BRAF V600 ohne relevante Verzögerung sicher erfasst wird.":"Panel larg validat, dacă acoperă în mod fiabil BRAF V600 fără întârziere relevantă.","Targeted Therapy first bei dringlicher klinischer Situation oder wenn Immuntherapie nicht geeignet ist; dies muss explizit klinisch begründet werden.":"Terapie țintită prima într-o situație clinică urgentă sau când imunoterapia nu este adecvată; acest lucru trebuie justificat clinic în mod explicit.","BRAF-mutiert = automatisch Targeted Therapy first":"BRAF-mutant = automat terapie țintită prima","Der Genotyp eröffnet die Option, entscheidet aber nicht alleine die optimale Sequenz.":"Genotipul deschide opțiunea, dar nu determină singur secvența optimă.","PD-L1 entscheidet die Reihenfolge":"PD-L1 decide secvența","Beim metastasierten Melanom ist PD-L1 kein einfacher Sequenzschalter zwischen BRAF/MEK und Immuntherapie.":"În melanomul metastatic, PD-L1 nu este un simplu comutator de secvențiere între BRAF/MEK și imunoterapie.","Klinik vom Molekularbefund trennen":"Separarea situației clinice de rezultatul molecular","Eine Sequenzentscheidung kann sich durch akute Progression innerhalb von Tagen verändern.":"O decizie de secvențiere se poate schimba în câteva zile din cauza unei progresii acute.","48 Stunden später: neue symptomatische Hirnmetastase":"48 de ore mai târziu: metastază cerebrală nouă simptomatică","Noch vor Therapiebeginn entwickelt der Patient Kopfschmerzen und eine diskrete Hemiparese. Das MRT zeigt eine neue symptomatische Hirnmetastase; Dexamethason wird begonnen. Gleichzeitig liegt der molekulare Befund vor: BRAF p.V600E. Die ursprünglich in Ruhe geplante Sequenz muss unter dem Gesichtspunkt rascher Krankheitskontrolle und Steroidbedarf neu diskutiert werden.":"Înainte de începerea tratamentului, pacientul dezvoltă cefalee și hemipareză discretă. RMN arată o nouă metastază cerebrală simptomatică; se începe dexametazonă. În același timp este disponibil rezultatul molecular: BRAF p.V600E. Secvența planificată inițial în condiții stabile trebuie rediscutată prin prisma necesității unui control rapid al bolii și a corticoterapiei.","Der molekulare Befund ist unverändert, aber die klinische Priorität hat sich verändert. Genau deshalb darf BRAF V600 nie isoliert als Sequenzautomat interpretiert werden.":"Rezultatul molecular este neschimbat, dar prioritatea clinică s-a modificat. Tocmai de aceea BRAF V600 nu trebuie interpretat niciodată izolat ca o comandă automată de secvențiere.","BRAF positiv, Klinik integriert":"BRAF pozitiv, contextul clinic integrat","BRAF p.V600E nachweisbar. Beide Strategien sind grundsätzlich verfügbar; nach klinischer Verschlechterung wird die Notwendigkeit schneller Kontrolle im MTB neu gewichtet.":"BRAF p.V600E detectabil. Ambele strategii sunt în principiu disponibile; după deteriorarea clinică, necesitatea controlului rapid este reevaluată în MTB.","Sehr gute Verbindung von molekularer Option und klinischer Situation.":"Conexiune foarte bună între opțiunea moleculară și situația clinică.","Mutation entscheidet alles":"Mutația decide totul","BRAF p.V600E wird automatisch mit 'BRAF/MEK zuerst' gleichgesetzt, unabhängig von Klinik und Sequenzevidenz.":"BRAF p.V600E este echivalat automat cu «BRAF/MEK prima», indiferent de contextul clinic și de dovezile privind secvența.","Zu mechanistisch; Option und Sequenz wurden verwechselt.":"Prea mecanicist; disponibilitatea unei opțiuni a fost confundată cu secvența.","Nur IO-Kontextmarker":"Doar markeri de context IO","PD-L1/TMB/TILs werden breit untersucht, BRAF bleibt ausstehend.":"PD-L1/TMB/TIL sunt analizate extensiv, în timp ce BRAF rămâne neclarificat.","Die zentrale molekulare Voraussetzung für eine Targeted-Therapy-Option fehlt.":"Lipsește premisa moleculară centrală pentru o opțiune de terapie țintită.","BRAF V600E positiv, klinisch stabil":"BRAF V600E pozitiv, stabil clinic","Immuntherapie-first als evidenzgestützte Standardstrategie für viele geeignete Patienten diskutieren.":"Discutați imunoterapia prima ca strategie standard susținută de dovezi pentru mulți pacienți eligibili.","Langfristige Sequenzplanung steht im Vordergrund.":"Planificarea secvenței pe termen lung este prioritară.","Neue symptomatische ZNS-Progression/Steroidbedarf":"Nouă progresie simptomatică SNC/necesar de corticosteroizi","Sequenz im MTB sofort neu bewerten und schnelle Krankheitskontrolle stärker gewichten.":"Reevaluați imediat secvența în MTB și acordați o pondere mai mare controlului rapid al bolii.","Targeted Therapy kann klinisch an Gewicht gewinnen.":"Terapia țintită poate câștiga importanță clinică.","BRAF nicht bestimmt":"BRAF nedeterminat","Schnelltest nachfordern.":"Solicitați test rapid.","Sequenzentscheidung bleibt unvollständig.":"Decizia de secvențiere rămâne incompletă.","BRAF V600 ist ein prädiktiver Marker für eine Target-Option, kein automatischer Sequenzbefehl.":"BRAF V600 este un marker predictiv pentru o opțiune țintită, nu o comandă automată de secvențiere.","Bei vielen geeigneten, stabilen Patienten spricht randomisierte Sequenzevidenz für Immuntherapie-first.":"Pentru mulți pacienți eligibili și stabili, dovezile randomizate privind secvența susțin imunoterapia prima.","Akute klinische Dynamik kann die optimale Reihenfolge verändern.":"Dinamica clinică acută poate modifica ordinea optimă.","Molekularpathologie ist Teil der Entscheidung, aber nicht deren alleiniger Eigentümer.":"Patologia moleculară face parte din decizie, dar nu este singurul ei proprietar.","BRAF p.V600E wird rasch bestätigt. Zunächst wäre bei klinischer Stabilität für viele geeignete Patienten Immuntherapie-first evidenzgestützt. Der Twist – symptomatische Hirnmetastase mit Steroidbedarf – erzwingt eine erneute klinische Gewichtung und kann die Bedeutung einer rasch wirksamen BRAF/MEK-Strategie erhöhen. PD-L1/TMB/TILs sind kein einfacher Sequenzschalter.":"BRAF p.V600E este confirmat rapid. Inițial, în condiții de stabilitate clinică, imunoterapia prima ar fi susținută de dovezi pentru mulți pacienți eligibili. Twist-ul – metastaza cerebrală simptomatică necesitând corticosteroizi – impune o nouă ponderare clinică și poate crește importanța unei strategii BRAF/MEK cu efect rapid. PD-L1/TMB/TIL nu sunt un simplu comutator de secvențiere.","BRAF als Voraussetzung erkannt":"BRAF recunoscut ca premisă","Keine automatische Targeted-first-Regel":"Fără regulă automată de terapie țintită prima","Klinische Dynamik integriert":"Dinamica clinică integrată","IO-Kontextmarker nicht überinterpretiert":"Markerii de context IO nu sunt supra-interpretați","Welche Patientengruppen waren in Sequenzstudien besonders gut repräsentiert – und welche weniger?":"Ce grupuri de pacienți au fost deosebit de bine reprezentate în studiile de secvențiere – și care mai puțin?","Wie ändert Steroidbedarf die praktische Immuntherapieplanung?":"Cum modifică necesarul de corticosteroizi planificarea practică a imunoterapiei?","Welche Information muss die Pathologie liefern und welche Entscheidung bleibt interdisziplinär?":"Ce informație trebuie să furnizeze patologia și ce decizie rămâne interdisciplinară?","symptomatische Hirnmetastase nach initial stabiler Situation":"metastază cerebrală simptomatică după o situație inițial stabilă","Mutation eröffnet Option, Klinik bestimmt Sequenz":"Mutația deschide opțiunea, situația clinică determină secvența","BRAF-Test → stabile Sequenzplanung → klinischer Twist → Re-Assessment":"Test BRAF → plan stabil de secvențiere → twist clinic → reevaluare","GIST mit KIT/PDGFRA-Fragestellung → Welcher Marker entscheidet über TKI-Auswahl?":"GIST cu întrebare KIT/PDGFRA → Ce marker determină selecția TKI?","GIST mit KIT/PDGFRA-Fragestellung":"GIST cu întrebare KIT/PDGFRA","Sarkomzentrum / MTB":"Centru de sarcoame / MTB","64-jährige Patientin mit gastralem GIST und neu aufgetretenen Lebermetastasen.":"Pacientă de 64 de ani cu GIST gastric și metastaze hepatice nou apărute.","Ist 'GIST = Imatinib' ausreichend, oder muss vor der TKI-Auswahl der KIT/PDGFRA-Genotyp vorliegen?":"Este suficient «GIST = imatinib» sau trebuie să fie disponibil genotipul KIT/PDGFRA înainte de alegerea TKI?","Therapiebeginn ist nach Abschluss der molekularen Typisierung geplant.":"Începerea tratamentului este planificată după finalizarea tipizării moleculare.","Primärtumor":"Tumora primară","Gastraler GIST, vor drei Jahren reseziert; nun hepatische Metastasierung.":"GIST gastric rezecat în urmă cu trei ani; acum metastaze hepatice.","Keine systemische TKI-Therapie.":"Fără terapie TKI sistemică.","Klinischer Reflex":"Reflex clinic","Im Tumorboard fällt früh der Satz: 'CD117-positiver GIST – dann Imatinib.'":"În tumor board apare devreme afirmația: «GIST CD117-pozitiv – deci imatinib.»","Lernziel":"Obiectiv de învățare","Diagnosemarker und prädiktiver Genotyp müssen getrennt werden.":"Markerii diagnostici și genotipul predictiv trebuie separați clar.","Epithelioider mesenchymaler Tumor, morphologisch passend zu GIST.":"Tumoră mezenchimală epitelioidă, morfologic compatibilă cu GIST.","DOG1 stark positiv, CD117 nur fokal/heterogen positiv.":"DOG1 intens pozitiv, CD117 doar focal/heterogen pozitiv.","Arbeitsdiagnose":"Diagnostic de lucru","Metastasierter gastrointestinaler Stromatumor.":"Tumor stromal gastrointestinal metastatic.","Welcher KIT-/PDGFRA-Genotyp liegt vor und verändert er die TKI-Auswahl?":"Ce genotip KIT/PDGFRA este prezent și modifică acesta selecția TKI?","FFPE-Lebermetastase, Block H3.":"Metastază hepatică FFPE, bloc H3.","ca. 75 %, DNA-QC gut.":"aprox. 75 %, QC ADN bun.","6 ungefärbte Schnitte verfügbar.":"Sunt disponibile 6 secțiuni necolorate.","Ein sehr breites Pan-Tumor-Panel ist für die konkrete Erstfrage unnötig, wenn eine valide KIT/PDGFRA-Analyse verfügbar ist.":"Un panel pan-tumoral foarte larg este inutil pentru întrebarea inițială concretă atunci când este disponibilă o analiză validă KIT/PDGFRA.","KIT/PDGFRA-Genotyp":"Genotip KIT/PDGFRA","KIT/PDGFRA":"KIT/PDGFRA","PDGFRA Exon 18 p.D842V nachweisbar; keine aktivierende KIT-Mutation. Die Konstellation ist für die TKI-Auswahl unmittelbar relevant.":"PDGFRA exon 18 p.D842V detectabil; fără mutație KIT activatoare. Această constelație este direct relevantă pentru selecția TKI.","Hoher Tumoranteil, DNA-Qualität gut; gezielte KIT/PDGFRA-Analyse vollständig auswertbar.":"Fracție tumorală mare, calitate bună a ADN; analiza țintită KIT/PDGFRA este complet evaluabilă.","Metastasierter GIST mit PDGFRA p.D842V. Der Genotyp widerspricht dem reflexhaften 'Imatinib für jeden GIST'-Schema und verlangt eine genotypspezifische TKI-Strategie.":"GIST metastatic cu PDGFRA p.D842V. Genotipul contrazice reflexul «imatinib pentru orice GIST» și impune o strategie TKI specifică genotipului.","Teilbefund: Die GIST-Diagnose ist morphologisch/IHC-basiert gesichert, aber ohne KIT/PDGFRA-Genotyp ist die prädiktive TKI-Einordnung unvollständig.":"Rezultat parțial: diagnosticul de GIST este confirmat morfologic/IHC, dar fără genotipul KIT/PDGFRA încadrarea predictivă pentru TKI rămâne incompletă.","DOG1/CD117 als Diagnosekontext, nicht als ausreichenden prädiktiven Marker einordnen":"Încadrați DOG1/CD117 ca context diagnostic, nu ca markeri predictivi suficienți","PDGFRA D842V explizit benennen":"Menționați explicit PDGFRA D842V","Genotypspezifische TKI-Auswahl statt pauschalem Imatinib-Reflex formulieren":"Formulați selecția TKI specifică genotipului în locul unui reflex generalizat cu imatinib","Bei KIT/PDGFRA-Wildtyp weitere molekulare Subklassifikation als mögliche Folgefrage erwähnen, ohne sie in diesem Fall zu erzwingen":"Dacă KIT/PDGFRA sunt wild type, menționați o subclasificare moleculară suplimentară ca posibilă etapă ulterioară fără a o impune în acest caz","Optimale Lösung: KIT/PDGFRA gezielt bestimmen. Der Nachweis von PDGFRA p.D842V ist der Twist, der die TKI-Auswahl gegenüber einem pauschalen Imatinib-Ansatz verändert.":"Soluția optimă: efectuați testarea țintită KIT/PDGFRA. Detectarea PDGFRA p.D842V este twist-ul care schimbă selecția TKI față de o abordare generalizată cu imatinib.","KIT":"KIT","PDGFRA":"PDGFRA","GIST":"GIST","Mini":"Mini","GIST ist nicht gleich Imatinib: PDGFRA D842V kippt den TKI-Reflex":"GIST nu înseamnă automat imatinib: PDGFRA D842V răstoarnă reflexul TKI","Molekularpathologie / Sarkompathologie / MTB":"Patologie moleculară / Patologie a sarcoamelor / MTB","GIST-Diagnosemarker und prädiktiven KIT/PDGFRA-Genotyp klar trennen.":"Separați clar markerii diagnostici ai GIST de genotipul predictiv KIT/PDGFRA.","Vor systemischer TKI-Therapie die für Sensitivität/Resistenz relevante Mutationsklasse bestimmen.":"Înainte de terapia sistemică cu TKI, determinați clasa mutațională relevantă pentru sensibilitate/rezistență.","PDGFRA D842V als klinisch entscheidenden Sonderfall erkennen.":"Recunoașteți PDGFRA D842V ca situație specială decisivă clinic.","Für eine fokussierte klinische Frage eine gezielte, ressourcenschonende Methode wählen.":"Alegeți o metodă țintită și eficientă din punct de vedere al resurselor pentru o întrebare clinică bine definită.","Im Sarkomboard ist der Fall scheinbar in zehn Sekunden erledigt: metastasierter GIST, DOG1 positiv, also Imatinib. Die Pathologin stoppt die Diskussion mit einer einfachen Frage: 'Welcher KIT- oder PDGFRA-Genotyp liegt eigentlich vor?' Plötzlich ist klar, dass der diagnostische Name noch keine prädiktive Antwort ist.":"În board-ul de sarcoame, cazul pare rezolvat în zece secunde: GIST metastatic, DOG1 pozitiv, deci imatinib. Patologul oprește discuția cu o întrebare simplă: «Ce genotip KIT sau PDGFRA este de fapt prezent?» Devine brusc clar că denumirea diagnosticului nu este încă un răspuns predictiv.","64-jährige Patientin mit vor drei Jahren reseziertem gastralem GIST und jetzt multiplen Lebermetastasen. DOG1 stark positiv, CD117 fokal. Keine bisherige TKI-Therapie. Vor Therapiebeginn soll der KIT/PDGFRA-Status geklärt werden.":"Pacientă de 64 de ani cu GIST gastric rezecat în urmă cu trei ani și acum metastaze hepatice multiple. DOG1 intens pozitiv, CD117 focal. Fără terapie TKI anterioară. Statusul KIT/PDGFRA trebuie clarificat înainte de începerea tratamentului.","Diagnose":"Diagnostic","Morphologie und DOG1/CD117 sichern den GIST-Kontext.":"Morfologia și DOG1/CD117 stabilesc contextul de GIST.","IHC beantwortet 'Was ist der Tumor?', nicht automatisch 'Welcher TKI wirkt?'.":"IHC răspunde la «Ce este tumora?», nu automat la «Ce TKI funcționează?». ","Therapiefrage":"Întrebarea terapeutică","Die Onkologie möchte mit einer TKI-Therapie beginnen.":"Oncologia dorește să înceapă terapie cu TKI.","Der prädiktive Genotyp gehört vor die Wirkstoffwahl.":"Genotipul predictiv trebuie să preceadă alegerea medicamentului.","Lebermetastase, 75 % Tumor, DNA-QC sehr gut; nur sechs Schnitte nötig verfügbar.":"Metastază hepatică, 75 % tumoră, QC ADN foarte bun; sunt necesare/disponibile doar șase secțiuni.","Eine fokussierte KIT/PDGFRA-Analyse ist effizient.":"O analiză țintită KIT/PDGFRA este eficientă.","Epithelioider mesenchymaler Tumor, vereinbar mit GIST.":"Tumoră mezenchimală epitelioidă, compatibilă cu GIST.","DOG1 stark positiv; CD117 fokal/heterogen positiv.":"DOG1 intens pozitiv; CD117 focal/heterogen pozitiv.","Systemtherapie":"Terapie sistemică","Noch nicht begonnen.":"Nu a fost încă începută.","Kleine, aber sehr tumorreiche Metastasenbiopsie.":"Biopsie metastatică mică, dar foarte bogată în tumoră.","Die klinische Kernfrage ist fokussiert; ein extrem breites Pan-Tumor-Panel ist nicht zwingend nötig.":"Întrebarea clinică centrală este bine focalizată; un panel pan-tumoral extrem de larg nu este obligatoriu.","Therapie sollte nicht allein aufgrund der IHC gestartet werden, wenn der Genotyp zeitnah verfügbar ist.":"Tratamentul nu ar trebui început doar pe baza IHC dacă genotipul poate fi disponibil rapid.","Welcher Befund entscheidet in diesem Fall am direktesten über die TKI-Auswahl?":"Ce rezultat determină cel mai direct selecția TKI în acest caz?","KIT/PDGFRA-Mutationsstatus":"Status mutațional KIT/PDGFRA","Stärke der CD117-IHC allein":"Doar intensitatea IHC CD117","Ki-67 allein":"Doar Ki-67","Der KIT/PDGFRA-Genotyp ist für die prädiktive Einordnung zentral.":"Genotipul KIT/PDGFRA este central pentru încadrarea predictivă.","Was bedeutet DOG1+/CD117+ für die TKI-Wahl?":"Ce înseamnă DOG1+/CD117+ pentru selecția TKI?","Es stützt die GIST-Diagnose, ersetzt aber die Genotypisierung nicht.":"Susține diagnosticul de GIST, dar nu înlocuiește genotiparea.","Es beweist Imatinib-Sensitivität.":"Dovedește sensibilitatea la imatinib.","Es schließt PDGFRA-Mutationen aus.":"Exclude mutațiile PDGFRA.","Es macht molekulare Diagnostik grundsätzlich überflüssig.":"Face diagnosticul molecular în principiu inutil.","Diagnostische IHC und prädiktive Genotypisierung beantworten verschiedene Fragen.":"IHC diagnostică și genotiparea predictivă răspund la întrebări diferite.","Wählen Sie die minimale diagnostische Strategie, mit der die geplante TKI-Therapie genotypspezifisch abgesichert werden kann.":"Alegeți strategia diagnostică minimă prin care terapia TKI planificată poate fi susținută specific genotipului.","GIST-Diagnose als gesichert akzeptieren.":"Acceptați diagnosticul de GIST ca fiind confirmat.","KIT/PDGFRA-Mutationsanalyse durchführen.":"Efectuați analiza mutațională KIT/PDGFRA.","Mutation auf Exon/Variantebene berichten.":"Raportați mutația la nivel de exon/variantă.","Therapieempfehlung an die konkrete Sensitivitäts-/Resistenzkonstellation koppeln.":"Corelați recomandarea terapeutică cu constelația specifică de sensibilitate/rezistență.","Bei KIT/PDGFRA-Wildtyp weitere Subklassifikation nur als Folgefrage erwägen.":"Dacă KIT/PDGFRA sunt wild type, luați în considerare o subclasificare suplimentară doar ca întrebare ulterioară.","Breiteres validiertes NGS-Panel, wenn es KIT/PDGFRA vollständig abdeckt und ohne relevante Mehrbelastung verfügbar ist.":"Panel NGS validat mai larg dacă acoperă complet KIT/PDGFRA și este disponibil fără povară suplimentară relevantă.","CD117 positiv = Imatinib":"CD117 pozitiv = imatinib","Diagnostische Proteinexpression wird fälschlich als prädiktiver Genotyp interpretiert.":"Expresia proteică diagnostică este interpretată eronat ca genotip predictiv.","Pan-Panel ohne klare Zusatzfrage":"Pan-panel fără întrebare suplimentară clară","Kann funktionieren, ist bei der fokussierten Erstfrage aber unnötig breit.":"Poate funcționa, dar este inutil de larg pentru întrebarea inițială focalizată.","Therapie vor Genotyp":"Tratament înainte de genotip","Eine klinisch relevante Resistenz-/Sensitivitätskonstellation kann übersehen werden.":"Poate fi omisă o constelație de rezistență/sensibilitate relevantă clinic.","PDGFRA D842V statt 'klassischem KIT-GIST'":"PDGFRA D842V în loc de «GIST KIT clasic»","Die gezielte Sequenzierung zeigt keine KIT-Mutation, sondern PDGFRA Exon 18 p.D842V. Der zunächst reflexhaft diskutierte Imatinib-Start wäre für genau diese Konstellation ungeeignet; die TKI-Strategie muss genotypspezifisch geändert werden.":"Secvențierea țintită nu arată o mutație KIT, ci PDGFRA exon 18 p.D842V. Începerea reflexă cu imatinib ar fi nepotrivită exact pentru această constelație; strategia TKI trebuie modificată specific genotipului.","Der Fall zeigt maximal kompakt, warum Diagnosesicherung und prädiktive Molekularpathologie zwei getrennte Schritte sind.":"Cazul arată foarte compact de ce confirmarea diagnosticului și patologia moleculară predictivă sunt două etape separate.","Genotyp vor TKI":"Genotip înainte de TKI","PDGFRA Exon 18 p.D842V, KIT wildtyp.":"PDGFRA exon 18 p.D842V, KIT wild type.","Kernentscheidung getroffen; TKI-Auswahl kann genotypspezifisch erfolgen.":"Decizia centrală a fost luată; selecția TKI poate fi făcută specific genotipului.","IHC reicht":"IHC este suficientă","GIST wird korrekt diagnostiziert, aber ohne KIT/PDGFRA-Genotyp pauschal als Imatinib-sensitiv behandelt.":"GIST este diagnosticat corect, dar fără genotip KIT/PDGFRA este tratat generic ca sensibil la imatinib.","Diagnose korrekt, prädiktive Ebene verfehlt.":"Diagnostic corect, nivel predictiv ratat.","Breites Pan-Panel":"Pan-panel larg","PDGFRA D842V wird ebenfalls gefunden, jedoch mit mehr Ressourcen als für die Kernfrage nötig.":"PDGFRA D842V este de asemenea detectat, dar cu mai multe resurse decât sunt necesare pentru întrebarea centrală.","Fachlich brauchbar, aber weniger fokussiert.":"Util clinic, dar mai puțin focalizat.","PDGFRA D842V":"PDGFRA D842V","Genotypspezifische TKI-Strategie im Sarkomboard diskutieren.":"Discutați strategia TKI specifică genotipului în board-ul de sarcoame.","Pauschaler Imatinib-Reflex wird vermieden.":"Este evitat reflexul generalizat cu imatinib.","KIT/PDGFRA wildtyp":"KIT/PDGFRA wild type","Weitere molekulare Subklassifikation erwägen.":"Luați în considerare o subclasificare moleculară suplimentară.","Der Fall geht in eine zweite diagnostische Ebene über.":"Cazul trece la un al doilea nivel diagnostic.","DOG1/CD117 sichern den diagnostischen Kontext, nicht die TKI-Sensitivität.":"DOG1/CD117 stabilesc contextul diagnostic, nu sensibilitatea la TKI.","KIT/PDGFRA-Genotypisierung ist eine prädiktive Entscheidungsebene.":"Genotiparea KIT/PDGFRA reprezintă un nivel predictiv de decizie.","PDGFRA D842V ist der klassische Fall, in dem ein pauschaler Imatinib-Reflex scheitert.":"PDGFRA D842V este cazul clasic în care reflexul generalizat cu imatinib eșuează.","Fokussierte Diagnostik kann besser sein als maximale Panelbreite, wenn die klinische Frage klar ist.":"Diagnosticul focalizat poate fi mai bun decât lățimea maximă a panelului atunci când întrebarea clinică este clară.","Gezielte KIT/PDGFRA-Analyse vor TKI-Start. Ergebnis: PDGFRA Exon 18 p.D842V, KIT wildtyp. Damit ist der reflexhafte Imatinib-Ansatz nicht passend; die Therapie muss genotypspezifisch geplant werden.":"Analiză țintită KIT/PDGFRA înainte de începerea TKI. Rezultat: PDGFRA exon 18 p.D842V, KIT wild type. Prin urmare, abordarea reflexă cu imatinib nu este potrivită; tratamentul trebuie planificat specific genotipului.","Diagnose vs. Prädiktion getrennt":"Diagnostic și predicție separate","KIT/PDGFRA gewählt":"KIT/PDGFRA selectat","D842V korrekt gewichtet":"D842V ponderat corect","Keine unnötige Panelinflation":"Fără extindere inutilă a panelului","Welche weiteren GIST-Genotypen beeinflussen Dosis oder TKI-Sensitivität?":"Ce alte genotipuri GIST influențează doza sau sensibilitatea la TKI?","Wann wäre ein breiteres Panel sinnvoll?":"Când ar fi util un panel mai larg?","Wie sollte ein Befund formuliert sein, damit Diagnose und Prädiktion klar getrennt bleiben?":"Cum trebuie formulat un raport astfel încât diagnosticul și predicția să rămână clar separate?","GIST-Diagnose ist nicht gleich TKI-Sensitivität":"Diagnosticul GIST nu este echivalent cu sensibilitatea la TKI","IHC-Diagnose → Genotyp → TKI-Wechsel":"Diagnostic IHC → genotip → schimbare TKI","Cholangiozelluläres Karzinom mit FGFR2/IDH-Frage → Paneldiagnostik und Studienoptionen":"Colangiocarcinom cu întrebare FGFR2/IDH → testare prin panel și opțiuni de studii clinice","Cholangiozelluläres Karzinom mit F…":"Colangiocarcinom cu întrebare FGFR2/IDH…","Hepatobiliäre Onkologie / MTB":"Oncologie hepatobiliară / MTB","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie.":"Pacientă de 59 de ani cu colangiocarcinom intrahepatic nerezecabil și progresie după terapia de primă linie.","Welche molekulare Profilierung ist jetzt sinnvoll, insbesondere für FGFR2- und IDH1/2-Alterationen sowie weitere potenziell targetierbare Befunde?":"Ce profilare moleculară este adecvată acum, în special pentru alterări FGFR2 și IDH1/2 și alte rezultate potențial targetabile?","Der molekulare Befund soll vor Festlegung der nächsten Therapielinie vorliegen.":"Raportul molecular trebuie să fie disponibil înainte de stabilirea următoarei linii terapeutice.","Tumorlokalisation":"Localizarea tumorii","Intrahepatische dominante Raumforderung mit multiplen Satelliten und pulmonalen Metastasen.":"Masă dominantă intrahepatică cu multipli sateliți și metastaze pulmonare.","Systemische Erstlinientherapie abgeschlossen; aktuell radiologischer Progress.":"Terapia sistemică de primă linie a fost finalizată; progresie radiologică actuală.","Ein kleines DNA-only-Panel aus der Erstdiagnose meldete keinen therapeutisch relevanten SNV/Indel-Befund; Fusionen waren im Bericht nicht valide abgedeckt.":"Un mic panel doar ADN de la diagnosticul inițial nu a raportat niciun SNV/indel relevant terapeutic; fuziunile nu au fost acoperite valid în raport.","'Panel negativ' wird im Tumorboard bereits mit 'keine Target-Option' gleichgesetzt.":"În tumor board, «panel negativ» este deja echivalat cu «fără opțiune target». ","Adenokarzinom mit tubulären und desmoplastischen Anteilen, vereinbar mit intrahepatischem Cholangiokarzinom.":"Adenocarcinom cu componente tubulare și desmoplazice, compatibil cu colangiocarcinom intrahepatic.","CK7 positiv; HepPar1/Arginase-1 negativ; klinisch-radiologische Integration stützt iCCA.":"CK7 pozitiv; HepPar1/Arginase-1 negative; integrarea clinico-radiologică susține iCCA.","Breite DNA-basierte Alterationen und insbesondere strukturelle FGFR2-Ereignisse müssen methodisch adäquat erfasst werden.":"Alterările ADN largi și, în special, evenimentele structurale FGFR2 trebuie detectate prin metode adecvate.","Nicht relevant":"Nu este relevant","Neuroonkologische IDH1-R132H-IHC, G-CIMP oder ein ZNS-Methylierungsclassifier beantworten diese Fragestellung nicht.":"IHC IDH1-R132H neuro-oncologică, G-CIMP sau un clasificator de metilare SNC nu răspund acestei întrebări.","FFPE-Leberbiopsie, Block C5.":"Biopsie hepatică FFPE, bloc C5.","ca. 50 %, ausreichende vitale Tumorareale.":"aprox. 50 %, arii tumorale viabile suficiente.","DNA/RNA-QC":"QC ADN/ARN","DNA gut; RNA nach QC ausreichend.":"ADN bun; ARN suficient după QC.","Erneutes DNA-only-Testen ohne valide Fusionserfassung kann denselben blinden Fleck reproduzieren.":"Repetarea testării doar ADN fără acoperire validă a fuziunilor poate reproduce același punct orb.","CCA-Molekularprofil / IDH1/2-Kontext":"Profil molecular CCA / context IDH1/2","FGFR2-Fusions-/Rearrangementdiagnostik":"Testare fuziune/rearanjament FGFR2","CCA-DNA-Profil":"Profil ADN CCA","Keine pathogene IDH1/2-Mutation; kein BRAF-V600- oder ERBB2-Hotspot-Befund. Das DNA-Profil allein erklärt keine Target-Option.":"Fără mutație patogenă IDH1/2; fără BRAF V600 sau hotspot ERBB2. Profilul ADN singur nu evidențiază o opțiune target.","FGFR2-Fusionsdiagnostik":"Testarea fuziunilor FGFR2","FGFR2::BICC1-Fusion nachweisbar. Der Befund ist bei intrahepatischem Cholangiokarzinom therapeutisch relevant und gehört in die nächste Linienplanung.":"Fuziune FGFR2::BICC1 detectabilă. Rezultatul este relevant terapeutic în colangiocarcinomul intrahepatic și trebuie integrat în planificarea liniei următoare.","DNA und RNA aus dem markierten Tumorareal sind auswertbar; ausreichende Restreserve vorhanden.":"ADN și ARN din aria tumorală marcată sunt evaluabile; există rezervă reziduală suficientă.","Intrahepatisches Cholangiokarzinom mit FGFR2::BICC1-Fusion und ohne IDH1/2-Mutation. Die zuvor DNA-only negative Profilierung war kein ausreichender Ausschluss einer strukturellen Targetalteration.":"Colangiocarcinom intrahepatic cu fuziune FGFR2::BICC1 și fără mutație IDH1/2. Profilarea anterioară negativă doar ADN nu a fost suficientă pentru excluderea unei alterări structurale targetabile.","Teilbefund: Die CCA-Profilierung ist ohne belastbare FGFR2-Fusions-/Rearrangementdiagnostik unvollständig. Neuroonkologische IDH-/Methylierungsverfahren sind für diese Frage nicht geeignet.":"Rezultat parțial: profilarea CCA este incompletă fără testare robustă a fuziunilor/rearanjamentelor FGFR2. Metodele neuro-oncologice IDH/metilare nu sunt adecvate acestei întrebări.","Intrahepatisches Cholangiokarzinom als relevanten molekularen Kontext benennen":"Menționați colangiocarcinomul intrahepatic ca context molecular relevant","FGFR2-Fusion/Rearrangement als eigenständige strukturelle Alterationsklasse erfassen":"Detectați fuziunea/rearanjamentul FGFR2 ca o clasă distinctă de alterări structurale","IDH1/2-Sequenzierung im CCA-Kontext von neuroonkologischer IDH-IHC/Methylomdiagnostik trennen":"Separați secvențierea IDH1/2 în context CCA de IHC IDH/metilomul neuro-oncologic","DNA-only Negativbefund nicht als vollständigen Fusionsausschluss formulieren":"Nu formulați un rezultat negativ doar ADN ca excludere completă a fuziunilor","Optimale Lösung: CCA-spezifisches Molekularprofil plus valide FGFR2-Fusionserfassung. Der ZNS-Methylierungs-/G-CIMP-Copyover wird vollständig entfernt.":"Soluția optimă: profil molecular specific CCA plus detectare validă a fuziunilor FGFR2. Copyover-ul de metilare SNC/G-CIMP este eliminat complet.","IDH":"IDH","FGFR":"FGFR","Intrahepatisches Cholangiokarzinom: Das negative DNA-Panel übersieht die strukturelle Targetalteration":"Colangiocarcinom intrahepatic: panelul ADN negativ ratează alterarea structurală targetabilă","Molekularpathologie / hepatobiliäre Onkologie / MTB":"Patologie moleculară / oncologie hepatobiliară / MTB","Das intrahepatische Cholangiokarzinom als Entität mit relevanter breiter molekularer Profilierung einordnen.":"Încadrați colangiocarcinomul intrahepatic ca entitate care necesită profilare moleculară largă relevantă.","FGFR2-Fusionen/Rearrangements methodisch von SNV/Indel-Analysen unterscheiden.":"Distingeți metodologic fuziunile/rearanjamentele FGFR2 de analizele SNV/indel.","IDH1/2 im CCA-Kontext von neuroonkologischer IDH-IHC/G-CIMP/Methylomdiagnostik trennen.":"Separați IDH1/2 în context CCA de diagnosticul neuro-oncologic IDH IHC/G-CIMP/metilom.","Einen negativen DNA-only-Befund nicht als vollständigen Ausschluss struktureller Targetalterationen interpretieren.":"Nu interpretați un rezultat negativ doar ADN ca excludere completă a alterărilor structurale targetabile.","Im hepatobiliären MTB liegt ein alter Molekularbefund mit der Überschrift 'kein targetierbarer Befund'. Die 59-jährige Patientin mit intrahepatischem Cholangiokarzinom ist nach Erstlinientherapie progredient, und die nächste Linie muss geplant werden. Beim Blick in den Methodenteil zeigt sich: Das damalige kleine Panel war DNA-basiert und auf SNV/Indels fokussiert. FGFR2-Rearrangements wurden nicht valide breit erfasst. Gleichzeitig findet sich in der Falllogik ein völlig fachfremder Verweis auf G-CIMP und einen ZNS-Methylierungsclassifier – genau diese Altlast soll der Fall jetzt bewusst bereinigen.":"În MTB-ul hepatobiliar există un raport molecular vechi cu titlul «fără rezultat targetabil». Pacienta de 59 de ani cu colangiocarcinom intrahepatic a progresat după terapia de primă linie, iar următoarea linie trebuie planificată. O privire la secțiunea de metode arată că vechiul panel mic era bazat pe ADN și focalizat pe SNV/indel. Rearanjamentele FGFR2 nu au fost acoperite valid și larg. În același timp, logica cazului conține o trimitere complet irelevantă la G-CIMP și la un clasificator de metilare SNC – exact această moștenire trebuie corectată acum în mod deliberat.","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie. DNA-only-Vorbefund ohne relevante SNV/Indel-Targetalteration. Für die nächste Linie sollen FGFR2-Fusionen/Rearrangements, IDH1/2 und weitere relevante molekulare Alterationen methodisch vollständig bewertet werden.":"Pacientă de 59 de ani cu colangiocarcinom intrahepatic nerezecabil și progresie după prima linie. Rezultat anterior doar ADN fără alterare SNV/indel target relevantă. Pentru linia următoare, fuziunile/rearanjamentele FGFR2, IDH1/2 și alte alterări moleculare relevante trebuie evaluate complet prin metode adecvate.","Entität":"Entitate","Intrahepatisches Cholangiokarzinom mit metastasierter Erkrankung.":"Colangiocarcinom intrahepatic cu boală metastatică.","Tumorentität und Erkrankungsphase bestimmen die sinnvolle molekulare Breite.":"Entitatea tumorală și faza bolii determină amploarea moleculară adecvată.","Kleines DNA-only-Panel ohne relevanten SNV/Indel-Treffer; keine belastbare breite Fusionserfassung.":"Panel mic doar ADN fără rezultat relevant SNV/indel; fără acoperire robustă și largă a fuziunilor.","Ein negatives SNV/Indel-Profil schließt strukturelle Alterationen nicht aus.":"Un profil SNV/indel negativ nu exclude alterările structurale.","Leberbiopsie mit 50 % Tumor; DNA und RNA ausreichend.":"Biopsie hepatică cu 50 % tumoră; ADN și ARN suficiente.","Es gibt keinen technischen Grund, die Fusionsfrage offen zu lassen.":"Nu există niciun motiv tehnic pentru a lăsa neclarificată întrebarea privind fuziunile.","Copyover-Falle":"Capcană de copyover","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier gehören in neuroonkologische Kontexte und beantworten die CCA-Targetfrage nicht.":"IHC IDH1-R132H, G-CIMP și clasificatorii de metilare SNC aparțin contextelor neuro-oncologice și nu răspund întrebării de target în CCA.","Gleiche Genbezeichnung bedeutet nicht gleiche diagnostische Methode oder biologische Fragestellung.":"Aceeași denumire de genă nu implică aceeași metodă diagnostică sau aceeași întrebare biologică.","Adenokarzinom mit desmoplastischem Stroma; klinisch-radiologisch und immunhistologisch mit intrahepatischem CCA vereinbar.":"Adenocarcinom cu stromă desmoplazică; clinic, radiologic și imunohistologic compatibil cu CCA intrahepatic.","DNA-only Vorprofil":"Profil anterior doar ADN","Kein relevanter IDH1/2-, BRAF-V600- oder ERBB2-Hotspot-Befund; Fusionserfassung unzureichend.":"Fără rezultat relevant IDH1/2, BRAF V600 sau hotspot ERBB2; acoperire inadecvată a fuziunilor.","ausreichend für gezielte Fusionsanalyse.":"suficient pentru analiza țintită a fuziunilor.","Zehn ungefärbte Schnitte verfügbar.":"Sunt disponibile zece secțiuni necolorate.","DNA und RNA sind ausreichend; die Limitation liegt primär in der Wahl des Assays.":"ADN și ARN sunt suficiente; limitarea constă în primul rând în alegerea assay-ului.","Neuroonkologische IDH-/Methylierungsverfahren sind explizit entitätsfremd.":"Metodele neuro-oncologice IDH/metilare sunt explicit neadecvate acestei entități.","Das TAT-Ziel liegt vor der nächsten Therapieentscheidung.":"Ținta TAT este înaintea următoarei decizii terapeutice.","Welche molekulare Kernstrategie ist bei diesem progredienten intrahepatischen Cholangiokarzinom sinnvoll?":"Ce strategie moleculară centrală este adecvată pentru acest colangiocarcinom intrahepatic progresiv?","CCA-spezifisches Molekularprofil plus valide FGFR2-Fusions-/Rearrangementdiagnostik":"Profil molecular specific CCA plus testare validă fuziune/rearanjament FGFR2","IDH1-R132H-IHC plus ZNS-Methylierungsclassifier":"IHC IDH1-R132H plus clasificator de metilare SNC","Keine weitere Diagnostik, weil das alte DNA-Panel negativ war":"Fără testare suplimentară deoarece vechiul panel ADN a fost negativ","MGMT-Promotor-Methylierung":"Metilarea promotorului MGMT","Die klinische Frage verlangt CCA-spezifische molekulare Profilierung mit adäquater Erfassung struktureller Alterationen.":"Întrebarea clinică necesită profilare moleculară specifică CCA cu detectarea adecvată a alterărilor structurale.","Wie soll IDH in diesem Fall untersucht/eingeordnet werden?":"Cum trebuie testat/interpretat IDH în acest caz?","IDH1/2-Sequenzierung im CCA-Panel-/Targetkontext":"Secvențiere IDH1/2 în context panel/target CCA","IDH1-R132H-IHC als primärer CCA-Screeningstandard":"IHC IDH1-R132H ca standard primar de screening pentru CCA","G-CIMP-Profil als Therapiebiomarker":"Profil G-CIMP ca biomarker terapeutic","ZNS-Methylierungsclassifier":"Clasificator de metilare SNC","Die neuroonkologische R132H-IHC/G-CIMP-/Classifier-Logik darf nicht auf das Cholangiokarzinom übertragen werden.":"Logica neuro-oncologică R132H IHC/G-CIMP/clasificator nu trebuie transferată la colangiocarcinom.","Das alte DNA-only-Panel ist negativ. Was folgt daraus für FGFR2?":"Vechiul panel doar ADN este negativ. Ce rezultă pentru FGFR2?","Eine Fusion/Rearrangement-Frage kann weiterhin offen sein, wenn der Assay diese Alterationsklasse nicht valide abdeckt.":"Întrebarea privind fuziunea/rearanjamentul poate rămâne deschisă dacă assay-ul nu acoperă valid această clasă de alterări.","FGFR2 ist sicher ausgeschlossen.":"FGFR2 este exclus cu certitudine.","Dann kann nur noch IDH1 relevant sein.":"Atunci doar IDH1 mai poate fi relevant.","Strukturelle Alterationen sind beim CCA klinisch nicht relevant.":"Alterările structurale nu sunt relevante clinic în CCA.","SNV/Indel-negative DNA-Daten sind kein universeller Fusionsausschluss.":"Datele ADN negative pentru SNV/indel nu reprezintă o excludere universală a fuziunilor.","Planen Sie eine CCA-spezifische molekulare Abklärung für die nächste Therapielinie und entfernen Sie die neuroonkologischen Copyover-Methoden vollständig aus der Entscheidungslogik.":"Planificați o evaluare moleculară specifică CCA pentru următoarea linie terapeutică și eliminați complet metodele copyover neuro-oncologice din logica decizională.","Intrahepatischen CCA-Kontext bestätigen.":"Confirmați contextul CCA intrahepatic.","CCA-spezifisches DNA-Profil für IDH1/2 und weitere relevante Alterationen nutzen.":"Utilizați un profil ADN specific CCA pentru IDH1/2 și alte alterări relevante.","FGFR2-Fusion/Rearrangement mit einer dafür validierten Methode explizit erfassen.":"Evaluați explicit fuziunea/rearanjamentul FGFR2 cu o metodă validată.","DNA-only Negativbefund methodisch begrenzen.":"Limitați metodologic interpretarea rezultatului negativ doar ADN.","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier nicht verwenden.":"Nu utilizați IHC IDH1-R132H, G-CIMP sau clasificator de metilare SNC.","Validiertes kombiniertes DNA/RNA-Pan-Panel mit sicherer FGFR2-Fusionserfassung.":"Pan-panel combinat ADN/ARN validat cu acoperire sigură a fuziunilor FGFR2.","Gezielte FGFR2-Fusionsdiagnostik plus separates IDH1/2-Assay, wenn ein integriertes CCA-Panel nicht verfügbar ist.":"Testare țintită a fuziunilor FGFR2 plus assay separat IDH1/2 dacă nu este disponibil un panel CCA integrat.","Fachfremder Copyover; beantwortet weder FGFR2- noch IDH1/2-Targetfrage beim CCA.":"Copyover irelevant; nu răspunde nici întrebării FGFR2, nici întrebării target IDH1/2 în CCA.","IDH1-R132H-IHC als CCA-Standard":"IHC IDH1-R132H ca standard CCA","Neuroonkologische Screeninglogik wird auf eine andere Entität übertragen.":"Logica de screening neuro-oncologică este transferată unei alte entități.","DNA-negativ = keine Targetoption":"ADN negativ = fără opțiune target","Strukturelle Alterationen können methodisch offen bleiben.":"Alterările structurale pot rămâne metodologic neclarificate.","FGFR2::BICC1 trotz 'kein targetierbarer Befund'":"FGFR2::BICC1 în ciuda «fără rezultat targetabil»","Die CCA-spezifische DNA-Analyse bleibt für IDH1/2, BRAF und ERBB2 ohne relevanten Treffer. Die gezielte Fusionsdiagnostik detektiert jedoch eine FGFR2::BICC1-Fusion. Der alte Satz 'kein targetierbarer Befund' war damit nicht biologisch falsch, sondern methodisch zu weit formuliert.":"Analiza ADN specifică CCA rămâne fără rezultate relevante pentru IDH1/2, BRAF și ERBB2. Totuși, testarea țintită a fuziunilor detectează o fuziune FGFR2::BICC1. Vechea formulare «fără rezultat targetabil» nu era deci biologic greșită, ci metodologic prea largă.","Die zentrale Lektion ist zweifach: strukturelle Alterationen brauchen passende Assays, und identische Genbegriffe dürfen nicht entitätsfremde Diagnostikpfade triggern.":"Lecția centrală este dublă: alterările structurale necesită assay-uri adecvate, iar denumiri genetice identice nu trebuie să declanșeze căi diagnostice nepotrivite entității.","CCA-Profil + Fusion":"Profil CCA + fuziune","FGFR2::BICC1-Fusion nachweisbar; IDH1/2 wildtyp; kein BRAF-V600-/ERBB2-Hotspot-Befund.":"Fuziune FGFR2::BICC1 detectabilă; IDH1/2 wild type; fără BRAF V600/hotspot ERBB2.","Vollständige, entitätsspezifische Profilierung mit klinisch relevanter Targetalteration.":"Profilare completă, specifică entității, cu o alterare targetabilă relevantă clinic.","DNA-only wiederholt":"DNA-only repetat","Kein relevanter SNV/Indel-Treffer; FGFR2-Fusionsstatus bleibt offen.":"Fără rezultat relevant SNV/indel; statusul fuziunii FGFR2 rămâne neclarificat.","Der alte methodische blinde Fleck wurde reproduziert.":"Vechiul punct orb metodologic a fost reprodus.","Neuroonkologischer IDH-Pfad":"Cale IDH neuro-oncologică","IDH1-R132H-IHC/Methylierungsclassifier werden angefordert; die eigentliche CCA-Targetfrage bleibt ungelöst.":"Sunt solicitate IHC IDH1-R132H/clasificator de metilare; întrebarea target reală a CCA rămâne nerezolvată.","Klarer Cross-Template-Fehler.":"Eroare clară cross-template.","FGFR2-Fusion positiv":"Fuziune FGFR2 pozitivă","Target-Relevanz und passende Therapielinie im hepatobiliären MTB diskutieren.":"Discutați relevanța targetului și linia terapeutică adecvată în MTB-ul hepatobiliar.","Der Befund verändert die nächste Linienplanung.":"Rezultatul schimbă planificarea liniei următoare.","FGFR2 negativ, DNA-Profil ohne Target":"FGFR2 negativ, profil ADN fără target","Weitere im validierten Panel erfasste Alterationsklassen und Studienoptionen prüfen.":"Revizuiți alte clase de alterări acoperite de panelul validat și opțiunile de studii clinice.","Negativbefund bleibt methodisch transparent.":"Rezultatul negativ rămâne transparent metodologic.","Nur CNS-IDH/Methylom gewählt":"Selectat doar IDH/metilom SNC","Anforderung korrigieren und CCA-spezifische Diagnostik durchführen.":"Corectați solicitarea și efectuați diagnostic specific CCA.","Material/TAT-Verlust, aber fachlich rettbarer Fall.":"Pierdere de material/TAT, dar caz salvabil clinic.","Beim iCCA ist molekulare Profilierung Teil moderner Therapieplanung.":"În iCCA, profilarea moleculară face parte din planificarea modernă a tratamentului.","FGFR2-Fusionen sind strukturelle Alterationen und benötigen passende Assayabdeckung.":"Fuziunile FGFR2 sunt alterări structurale și necesită acoperire adecvată a assay-ului.","IDH1/2 im Cholangiokarzinom ist nicht dasselbe diagnostische Problem wie IDH/G-CIMP im Gliom.":"IDH1/2 în colangiocarcinom nu reprezintă aceeași problemă diagnostică precum IDH/G-CIMP în gliom.","Cross-Template-Copyover ist ein reales Qualitätsrisiko in standardisierten Fallbibliotheken und Labor-Workflows.":"Copyover-ul cross-template este un risc real de calitate în bibliotecile standardizate de cazuri și fluxurile de laborator.","CCA-spezifisches Molekularprofil plus explizite FGFR2-Fusions-/Rearrangementdiagnostik. Ergebnis: FGFR2::BICC1-Fusion, IDH1/2 wildtyp. Die bisherigen neuroonkologischen IDH1-R132H-/G-CIMP-/Methylierungsclassifier-Elemente sind fachfremd und werden vollständig entfernt.":"Profil molecular specific CCA plus testare explicită a fuziunilor/rearanjamentelor FGFR2. Rezultat: fuziune FGFR2::BICC1, IDH1/2 wild type. Elementele anterioare neuro-oncologice IDH1-R132H/G-CIMP/clasificator de metilare sunt neadecvate și sunt eliminate complet.","iCCA-Kontext erkannt":"Context iCCA recunoscut","FGFR2 strukturell korrekt getestet":"FGFR2 testat structural corect","IDH1/2 entitätsspezifisch eingeordnet":"IDH1/2 interpretat specific entității","CNS-Copyover aktiv verworfen":"Copyover SNC respins activ","Wann reicht ein DNA-Panel für Fusionen, wann nicht?":"Când este suficient un panel ADN pentru fuziuni și când nu?","Welche weiteren Alterationsklassen sollten CCA-Panels abdecken?":"Ce alte clase de alterări ar trebui să acopere panelurile CCA?","Wie können Template-Bibliotheken gegen Cross-Entity-Copyover QA-gesichert werden?":"Cum pot fi bibliotecile de template-uri protejate prin QA împotriva copyover-ului între entități?","FGFR2::BICC1 nach DNA-only Negativbefund":"FGFR2::BICC1 după un rezultat negativ doar ADN","Strukturelle Targets brauchen passende Methoden":"Targeturile structurale necesită metode adecvate","DNA-negativ → Assaycheck → CCA-Profil + Fusion → FGFR2":"ADN negativ → verificare assay → profil CCA + fuziune → FGFR2","Rechte Kolonkarzinom-Metastase mit BRAF V600E → Prognose, MSI-Kontext, Therapieoption":"Metastază de cancer de colon drept cu BRAF V600E → prognostic, context MSI, opțiune terapeutică","Rechte Kolonkarzinom-Metastase mit…":"Metastază de cancer de colon drept cu…","Viszeralonkologie / Molekulares Tumorboard":"Oncologie viscerală / Tumor Board molecular","72-jährige Patientin mit rechtsseitigem Kolonkarzinom und synchronen Leber- und Peritonealmetastasen.":"Pacientă de 72 de ani cu cancer de colon drept și metastaze hepatice și peritoneale sincrone.","Im Tumorprofil wurde BRAF p.V600E nachgewiesen. Welche prognostische und therapeutische Bedeutung hat der Befund im CRC – und was muss zusätzlich über MMR/MSI bekannt sein?":"BRAF p.V600E a fost detectat în profilul tumoral. Ce semnificație prognostică și terapeutică are în CRC – și ce mai trebuie cunoscut despre MMR/MSI?","Die Erstlinienstrategie soll im MTB innerhalb weniger Tage festgelegt werden.":"Strategia de primă linie trebuie stabilită în MTB în câteva zile.","Coecum/Colon ascendens, rechtsseitig.":"Cec/colon ascendent, partea dreaptă.","Metastasiert mit Leber- und Peritonealbefall; ECOG 1.":"Boală metastatică cu afectare hepatică și peritoneală; ECOG 1.","BRAF V600E wird reflexartig wie beim Melanom interpretiert oder mit MSI-H gleichgesetzt. Beides ist im CRC falsch bzw. unvollständig.":"BRAF V600E este interpretat reflex ca în melanom sau echivalat cu MSI-H. Ambele sunt greșite sau incomplete în CRC.","Mäßig bis gering differenziertes kolorektales Adenokarzinom mit fokal muzinöser Morphologie.":"Adenocarcinom colorectal moderat până la slab diferențiat cu morfologie mucinoasă focală.","Lineage":"Linie de diferențiere","CDX2/SATB2 positiv; Morphologie und Klinik vereinbar mit kolorektalem Primarius.":"CDX2/SATB2 pozitive; morfologia și contextul clinic sunt compatibile cu un primar colorectal.","Molekularer Vorbefund":"Rezultat molecular anterior","BRAF p.V600E in einer schnellen Einzeltestung nachgewiesen.":"BRAF p.V600E detectat într-un test rapid individual.","Ist der Tumor dMMR/MSI-H oder pMMR/MSS, und wie muss die BRAF-Alteration CRC-spezifisch therapeutisch eingeordnet werden?":"Este tumora dMMR/MSI-H sau pMMR/MSS și cum trebuie interpretată terapeutic alterarea BRAF în mod specific CRC?","FFPE-Resektat, Block C6 mit vitalem invasivem Tumor.":"Piesă de rezecție FFPE, bloc C6 cu tumoră invazivă viabilă.","ca. 55 %, gut geeignet für DNA-basierte Analysen.":"aprox. 55 %, bine adecvat pentru analize bazate pe ADN.","DNA-Qualität gut; MMR-IHC technisch gut beurteilbar.":"Calitatea ADN bună; IHC MMR bine evaluabilă tehnic.","Melanom-spezifische BRAF-Methoden oder Therapiealgorithmen beantworten die CRC-Frage nicht.":"Metodele BRAF sau algoritmii terapeutici specifici melanomului nu răspund întrebării CRC.","BRAF-V600E im CRC-Kontext":"BRAF V600E în context CRC","MMR-IHC":"IHC MMR","MSI-Testung":"Testare MSI","BRAF V600E":"BRAF V600E","BRAF p.V600E nachweisbar. Der Befund ist im metastasierten CRC prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden – nicht nach dem Melanom-Algorithmus.":"BRAF p.V600E detectabil. Rezultatul este relevant prognostic și terapeutic în CRC metastatic, dar trebuie interpretat conform dovezilor specifice CRC – nu unui algoritm de melanom.","Erweiterter RAS-Status":"Status RAS extins","KRAS/NRAS Wildtyp. Der BRAF-V600E-Befund bleibt der dominante MAPK-Treiberkontext.":"KRAS/NRAS wild type. Rezultatul BRAF V600E rămâne contextul dominant de driver MAPK.","Intakte nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expresie nucleară intactă a MLH1, PMS2, MSH2 și MSH6: pMMR.","MSI":"MSI","MSS / kein MSI-H. BRAF V600E ist damit gerade nicht automatisch mit MSI-H gleichzusetzen.":"MSS / fără MSI-H. BRAF V600E nu este deci în mod automat sinonim cu MSI-H.","MLH1-Methylierung":"Metilare MLH1","Bei erhaltener MLH1/PMS2-Expression besteht in diesem Fall keine primäre Reflexindikation; die Zusatzanalyse liefert keinen entscheidungsrelevanten Mehrwert.":"Cu expresie MLH1/PMS2 păstrată nu există o indicație reflexă primară în acest caz; analiza suplimentară nu aduce un beneficiu relevant pentru decizie.","Tumoranteil und DNA-Qualität ausreichend; MMR-IHC auswertbar.":"Fracție tumorală și calitate ADN suficiente; IHC MMR evaluabilă.","BRAF p.V600E liegt in einem rechtsseitigen, pMMR/MSS metastasierten CRC vor. Der Befund ist prognostisch ungünstig und eröffnet einen CRC-spezifischen BRAF-gerichteten Therapiekontext mit EGFR-Blockade nach aktueller Therapielinie/Leitlinie. Eine Melanom-artige BRAF/MEK-Übertragung ist nicht angemessen; BRAF V600E bedeutet außerdem nicht automatisch MSI-H.":"BRAF p.V600E este prezent într-un CRC metastatic drept, pMMR/MSS. Rezultatul este prognostic nefavorabil și deschide un context terapeutic specific CRC de targetare BRAF cu blocadă EGFR conform liniei terapeutice/ghidului actual. Transferul unui algoritm BRAF/MEK de tip melanom nu este adecvat; BRAF V600E nu înseamnă automat MSI-H.","Teilbefund: BRAF V600E ist bekannt, aber ohne MMR/MSI-Kontext bleibt die molekulare Einordnung unvollständig. Therapie- und Prognoseaussagen dürfen nicht aus einem Melanom-Template übernommen werden.":"Rezultat parțial: BRAF V600E este cunoscut, dar fără context MMR/MSI încadrarea moleculară rămâne incompletă. Afirmațiile terapeutice și prognostice nu trebuie preluate dintr-un template de melanom.","BRAF V600E als CRC-spezifischen prognostisch/therapeutisch relevanten Befund benennen":"Menționați BRAF V600E ca rezultat relevant prognostic și terapeutic specific CRC","BRAF V600E nicht mit MSI-H gleichsetzen; pMMR/MSS separat kommunizieren":"Nu echivalați BRAF V600E cu MSI-H; comunicați separat pMMR/MSS","BRAF-gerichtete Strategie im CRC mit EGFR-Blockade und aktueller Therapielinie verknüpfen, nicht mit einem Melanom-Schema":"Corelați strategia de targetare BRAF în CRC cu blocada EGFR și linia terapeutică actuală, nu cu un regim de melanom","Entitätsspezifische Evidenz und aktuelle Leitlinien-/Zulassungssituation sprachlich sauber begrenzen":"Formulați dovezile specifice entității și situația actuală de ghid/aprobare cu limitări adecvate","Optimale Lösung: BRAF V600E, RAS-Kontext und MMR/MSI gemeinsam einordnen; der Tumor ist pMMR/MSS und benötigt eine CRC-spezifische BRAF-/EGFR-Therapielogik statt eines Melanom-Copyovers.":"Soluția optimă: interpretați împreună BRAF V600E, contextul RAS și MMR/MSI; tumora este pMMR/MSS și necesită o logică terapeutică BRAF/EGFR specifică CRC, nu un copyover de melanom.","CRC":"CRC","mCRC":"mCRC","pMMR":"pMMR","MSS":"MSS","anti-EGFR":"anti-EGFR","Targeted Therapy":"Terapie țintită","BRAF V600E im rechten mCRC: CRC-Biologie statt Melanom-Copyover":"BRAF V600E în mCRC drept: biologie CRC în loc de copyover de melanom","Molekularpathologie / Viszeralonkologie / MTB":"Patologie moleculară / Oncologie viscerală / MTB","BRAF V600E beim mCRC prognostisch und therapeutisch korrekt einordnen.":"Interpretați corect BRAF V600E prognostic și terapeutic în mCRC.","BRAF V600E nicht automatisch mit MSI-H gleichsetzen, sondern MMR/MSI separat prüfen.":"Nu echivalați automat BRAF V600E cu MSI-H; evaluați separat MMR/MSI.","Die CRC-spezifische BRAF-Therapielogik von Melanom-Algorithmen abgrenzen.":"Distingeți logica terapeutică BRAF specifică CRC de algoritmii de melanom.","Rechtsseitigkeit, pMMR/MSS und BRAF-Kontext in einer integrierten MTB-Aussage zusammenführen.":"Integrați lateralitatea, pMMR/MSS și contextul BRAF într-o singură concluzie MTB.","Im MTB fällt sofort der rote Marker 'BRAF V600E' ins Auge. Jemand schlägt vor, den Fall wie ein BRAF-mutiertes Melanom zu behandeln; ein anderer sagt, rechtsseitig plus BRAF sei wahrscheinlich ohnehin MSI-high. Beides klingt auf den ersten Blick plausibel – und beides greift zu kurz.":"În MTB, markerul roșu «BRAF V600E» atrage imediat atenția. Cineva propune tratarea cazului ca pe un melanom BRAF-mutant; altcineva spune că partea dreaptă plus BRAF înseamnă probabil oricum MSI-high. Ambele sună plauzibil la prima vedere – și ambele sunt insuficiente.","72-jährige Patientin mit rechtsseitigem metastasiertem CRC. BRAF p.V600E wurde bereits nachgewiesen. Die Lernaufgabe besteht darin, die Mutation entitätsspezifisch zu interpretieren, MMR/MSI unabhängig zu klären und aus Prognose, Immuntherapie- und BRAF-Targetkontext eine belastbare MTB-Empfehlung zu formulieren.":"Pacientă de 72 de ani cu CRC metastatic drept. BRAF p.V600E este deja cunoscut. Sarcina este de a interpreta mutația specific entității, de a clarifica independent MMR/MSI și de a formula o recomandare MTB robustă din prognostic, context de imunoterapie și targetare BRAF.","Tumorbiologie":"Biologia tumorală","Rechtsseitiges metastasiertes CRC mit BRAF V600E.":"CRC metastatic drept cu BRAF V600E.","BRAF ist ein starker biologischer Kontextmarker, aber nicht die gesamte Therapieentscheidung.":"BRAF este un marker biologic contextual puternic, dar nu reprezintă întreaga decizie terapeutică.","Zu Beginn noch unbekannt.":"Inițial necunoscut.","BRAF V600E und MSI-H sind assoziiert, aber nicht synonym.":"BRAF V600E și MSI-H sunt asociate, dar nu sinonime.","Therapiekontext":"Context terapeutic","Erstlinienentscheidung steht an.":"Decizia de primă linie este în curs.","BRAF-Targeting im CRC folgt einer anderen Logik als beim Melanom.":"Targetarea BRAF în CRC urmează o logică diferită de melanom.","Schneller BRAF-Befund":"Rezultat BRAF rapid","BRAF p.V600E positiv.":"BRAF p.V600E pozitiv.","Rechtsseitiges kolorektales Adenokarzinom, metastasiert.":"Adenocarcinom colorectal drept, metastatic.","Material ausreichend für MMR-IHC und MSI-Testung.":"Material suficient pentru IHC MMR și testare MSI.","Zehn Schnitte reichen für eine fokussierte CRC-Diagnostik.":"Zece secțiuni sunt suficiente pentru diagnosticul CRC focalizat.","Melanom-spezifische Zusatztests sind methodisch und didaktisch Low Value.":"Testele suplimentare specifice melanomului au valoare metodologică și didactică redusă.","MMR/MSI muss trotz bekanntem BRAF-Befund eigenständig beantwortet werden.":"MMR/MSI trebuie clarificat independent în ciuda rezultatului BRAF cunoscut.","Welche Aussage zum BRAF-V600E-Befund ist im mCRC am treffendsten?":"Care afirmație despre BRAF V600E în mCRC este cea mai corectă?","BRAF V600E ist prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden; ein Melanom-Algorithmus darf nicht übertragen werden.":"BRAF V600E este relevant prognostic și terapeutic, dar trebuie interpretat conform dovezilor specifice CRC; un algoritm de melanom nu trebuie transferat.","BRAF V600E bedeutet unabhängig von der Entität denselben BRAF/MEK-Algorithmus wie beim Melanom.":"BRAF V600E înseamnă același algoritm BRAF/MEK ca în melanom, indiferent de entitate.","BRAF V600E ist beim CRC nur prognostisch, nicht therapeutisch relevant.":"În CRC, BRAF V600E este doar prognostic, nu relevant terapeutic.","Bei rechtsseitigem CRC spielt BRAF keine Rolle.":"În CRC drept, BRAF nu are relevanță.","Entitätsspezifische Biologie und Therapiedaten sind entscheidend.":"Biologia specifică entității și datele terapeutice sunt decisive.","BRAF V600E ist nachgewiesen. Was folgt für MMR/MSI?":"BRAF V600E este detectat. Ce urmează pentru MMR/MSI?","MMR/MSI weiterhin separat bestimmen; BRAF V600E beweist weder dMMR noch MSI-H.":"Continuați evaluarea separată MMR/MSI; BRAF V600E nu dovedește nici dMMR, nici MSI-H.","BRAF V600E reicht als Surrogat für MSI-H.":"BRAF V600E este suficient ca surogat pentru MSI-H.","MMR/MSI ist bei BRAF-mutiertem mCRC therapeutisch bedeutungslos.":"MMR/MSI este irelevant terapeutic în mCRC BRAF-mutant.","PD-L1 ersetzt die MSI-Testung.":"PD-L1 înlocuiește testarea MSI.","Die MMR/MSI-Ebene besitzt eine unabhängige prädiktive und ggf. hereditäre Bedeutung.":"Nivelul MMR/MSI are o semnificație predictivă independentă și potențial ereditară.","Welche Targetlogik ist für BRAF V600E im mCRC korrekt?":"Ce logică de targetare este corectă pentru BRAF V600E în mCRC?","CRC-spezifische BRAF-gerichtete Strategie unter Einbezug der EGFR-Achse gemäß aktueller Therapielinie/Leitlinie.":"Strategie specifică CRC de targetare BRAF, cu includerea axei EGFR conform liniei terapeutice/ghidului actual.","BRAF-Inhibitor allein ist die logische Standardstrategie.":"Inhibitorul BRAF singur este strategia standard logică.","BRAF/MEK wie beim Melanom ohne CRC-spezifischen Kontext.":"BRAF/MEK ca în melanom, fără context specific CRC.","BRAF V600E ist nicht targetierbar.":"BRAF V600E nu este targetabil.","Beim CRC ist die EGFR-Rückkopplung/Signalachse Teil der therapeutischen BRAF-Logik.":"În CRC, feedback-ul/semnalizarea EGFR face parte din logica terapeutică BRAF.","Interpretieren Sie BRAF V600E in einem rechtsseitigen mCRC und vervollständigen Sie MMR/MSI so, dass Prognose, Immuntherapie- und BRAF-Targetkontext sauber getrennt und integriert werden.":"Interpretați BRAF V600E într-un mCRC drept și completați MMR/MSI astfel încât prognosticul, imunoterapia și contextul de targetare BRAF să fie clar separate și integrate.","BRAF-V600E-Befund entitätsspezifisch bestätigen/einordnen.":"Confirmați/încadrați rezultatul BRAF V600E specific entității.","MMR-IHC und MSI unabhängig bestimmen.":"Determinați independent IHC MMR și MSI.","Ergebnis pMMR/MSS explizit kommunizieren.":"Comunicați explicit rezultatul pMMR/MSS.","BRAF V600E als prognostisch ungünstigen und therapeutisch relevanten CRC-Kontext berichten.":"Raportați BRAF V600E ca un context CRC prognostic nefavorabil și relevant terapeutic.","Keinen Melanom-Algorithmus übertragen; aktuelle CRC-spezifische BRAF/EGFR-Strategie heranziehen.":"Nu transferați un algoritm de melanom; utilizați strategia actuală BRAF/EGFR specifică CRC.","Kolon-NGS-Panel zur gemeinsamen Erfassung von BRAF/RAS plus separate MMR-IHC/MSI.":"Panel NGS colorectal pentru detectarea comună BRAF/RAS plus IHC MMR/MSI separat.","Breiteres validiertes Pan-Panel, sofern BRAF und MSI zuverlässig abgedeckt und die MMR-IHC sinnvoll ergänzt werden.":"Pan-panel validat mai larg, cu condiția ca BRAF și MSI să fie acoperite fiabil și IHC MMR să fie completată adecvat.","Melanom-BRAF-Template":"Template BRAF de melanom","Gleiche Mutation bedeutet nicht gleichen Therapiealgorithmus über Tumorentitäten hinweg.":"Aceeași mutație nu înseamnă același algoritm terapeutic în toate entitățile tumorale.","BRAF = MSI-H":"BRAF = MSI-H","Assoziation ist kein Ersatz für MMR/MSI-Diagnostik.":"Asocierea nu înlocuiește diagnosticul MMR/MSI.","BRAF allein befundet":"Doar BRAF raportat","Der Immuntherapie-/MMR-Kontext bleibt offen.":"Contextul imunoterapiei/MMR rămâne neclarificat.","BRAF V600E – aber pMMR/MSS":"BRAF V600E – dar pMMR/MSS","Die MMR-IHC ist vollständig erhalten und die MSI-Testung zeigt MSS. Der rechtsseitige BRAF-V600E-Tumor ist damit gerade kein MSI-H-Fall. Gleichzeitig wird klar: Der BRAF-Befund führt nicht in einen Melanom-Pfad, sondern in eine CRC-spezifische BRAF-/EGFR-Therapielogik.":"IHC MMR este complet păstrată, iar testarea MSI arată MSS. Tumora dreaptă BRAF V600E nu este deci un caz MSI-H. În același timp devine clar că rezultatul BRAF nu conduce într-o cale de melanom, ci într-o logică terapeutică BRAF/EGFR specifică CRC.","Der Fall löst zwei häufige Kurzschlüsse gleichzeitig auf: BRAF ist weder ein MSI-Surrogat noch eine entitätsunabhängige Therapieschablone.":"Cazul clarifică simultan două scurtături frecvente: BRAF nu este nici surogat MSI, nici șablon terapeutic independent de entitate.","CRC-spezifisch vollständig":"Complet și specific CRC","BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Prognostisch ungünstiger BRAF-Kontext; CRC-spezifische BRAF-gerichtete Strategie mit EGFR-Blockade nach aktueller Linie/Leitlinie diskutieren.":"BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Context BRAF prognostic nefavorabil; discutați strategia specifică CRC de targetare BRAF cu blocadă EGFR conform liniei/ghidului actual.","Entität, MSI und Targetlogik korrekt integriert.":"Entitatea, MSI și logica de targetare sunt integrate corect.","Nur BRAF":"Doar BRAF","BRAF V600E ist bekannt, MMR/MSI bleibt offen.":"BRAF V600E este cunoscut; MMR/MSI rămâne neclarificat.","Therapeutisch und biologisch unvollständig.":"Incomplet terapeutic și biologic.","Melanom-Copyover":"Copyover de melanom","BRAF/MEK-Logik wird ohne CRC-spezifischen Kontext übertragen.":"Logica BRAF/MEK este transferată fără context specific CRC.","Cross-Entity-Fehlinterpretation.":"Interpretare eronată între entități.","pMMR/MSS bestätigt":"pMMR/MSS confirmat","BRAF- und Chemotherapie-/EGFR-Kontext nach aktueller Linie im MTB diskutieren.":"Discutați contextul BRAF și chimioterapie/EGFR în MTB conform liniei terapeutice actuale.","Der Fall bleibt Targeted-Therapy-orientiert, ohne MSI-H-IO-Pfad.":"Cazul rămâne orientat spre terapie țintită, fără o cale IO MSI-H.","unerwartet dMMR/MSI-H":"dMMR/MSI-H neașteptat","Immuntherapie- und Lynch/sporadisch-Kontext zusätzlich priorisieren.":"Prioritizați suplimentar contextul de imunoterapie și Lynch/sporadic.","Therapiepriorisierung verändert sich.":"Prioritizarea terapeutică se modifică.","BRAF V600E ist im CRC entitätsspezifisch zu interpretieren.":"BRAF V600E trebuie interpretat specific entității în CRC.","BRAF V600E und MSI-H sind nicht gleichbedeutend.":"BRAF V600E și MSI-H nu sunt echivalente.","MMR/MSI bleibt ein unabhängiger Biomarkerblock.":"MMR/MSI rămâne un bloc independent de biomarkeri.","BRAF-gerichtete Therapie im CRC bindet die EGFR-Achse ein und darf nicht aus dem Melanom kopiert werden.":"Terapia de targetare BRAF în CRC include axa EGFR și nu trebuie copiată din melanom.","BRAF V600E + pMMR/MSS im rechtsseitigen mCRC. Kein Melanom-Algorithmus; CRC-spezifische BRAF-/EGFR-Strategie nach aktueller Therapielinie. MMR/MSI separat bestimmt und korrekt negativ eingeordnet.":"BRAF V600E + pMMR/MSS în mCRC drept. Fără algoritm de melanom; strategie BRAF/EGFR specifică CRC conform liniei terapeutice actuale. MMR/MSI evaluat separat și interpretat corect ca negativ.","Entitätsspezifische BRAF-Interpretation":"Interpretare BRAF specifică entității","MMR/MSI unabhängig geprüft":"MMR/MSI evaluat independent","kein Melanom-Copyover":"fără copyover de melanom","Prognose vs. Prädiktion getrennt":"Prognostic vs. predicție separate","Warum ist BRAF V600E kein MSI-Surrogat?":"De ce BRAF V600E nu este un surogat MSI?","Warum reicht BRAF-Hemmung allein im CRC biologisch/klinisch nicht als Übertrag aus dem Melanom?":"De ce inhibarea BRAF singură nu poate fi transferată biologic/clinic din melanom în CRC?","Welche Rolle spielt die Tumorlokalisation zusätzlich?":"Ce rol suplimentar are lateralitatea tumorii?","DE master":"Master DE","BRAF V600E, aber pMMR/MSS":"BRAF V600E, dar pMMR/MSS","Mutation ist entitätsspezifisch zu interpretieren":"Mutația trebuie interpretată specific entității","BRAF+ → MMR/MSI separat → pMMR/MSS → CRC-spezifische BRAF/EGFR-Logik":"BRAF+ → MMR/MSI separat → pMMR/MSS → logică BRAF/EGFR specifică CRC","Polypenrest statt invasivem Tumor eingeschickt → Befundbar oder neues Material anfordern?":"Rest de polip trimis în locul tumorii invazive → Se poate raporta sau trebuie solicitat material nou?","Polypenrest statt invasivem Tumor …":"Rest de polip în locul tumorii invazive …","Viszeralonkologie / Molekularpathologie":"Oncologie viscerală / Patologie moleculară","64-jähriger Patient mit metastasiertem Sigma-Karzinom; vor Beginn der Systemtherapie werden RAS/BRAF und MMR/MSI angefordert.":"Pacient de 64 de ani cu carcinom sigmoid metastatic; RAS/BRAF și MMR/MSI sunt solicitate înainte de terapia sistemică.","Der eingesandte Block soll 'repräsentatives Tumorgewebe' enthalten. Ist das Material tatsächlich für die prädiktive Diagnostik geeignet?":"Blocul trimis ar trebui să conțină «țesut tumoral reprezentativ». Este materialul într-adevăr adecvat diagnosticului predictiv?","MTB in vier Tagen; die Onkologie bittet ausdrücklich um eine schnelle Freigabe.":"MTB în patru zile; oncologia solicită explicit eliberare rapidă.","Vorgeschichte":"Antecedente","Zunächst endoskopische Polypektomie, anschließend onkologische Sigmaresektion mit invasivem Adenokarzinom; inzwischen Lebermetastasen.":"Inițial polipectomie endoscopică, urmată de rezecție oncologică de sigmoid cu adenocarcinom invaziv; acum metastaze hepatice.","Anforderung":"Solicitare","Auf dem Molekularschein steht Block 'A1'. Im Pathologiesystem existieren jedoch sowohl Polypektomie A1 als auch Resektionsblock B7.":"Pe formularul molecular este trecut blocul «A1». În sistemul de patologie există însă atât polipectomia A1, cât și blocul de rezecție B7.","Ein automatisches 'Material vorhanden → testen' wäre schnell, könnte aber die falsche Läsion analysieren.":"O abordare automată «material disponibil → testare» ar fi rapidă, dar ar putea analiza leziunea greșită.","Technisch erfolgreiche Molekulardiagnostik ist nicht automatisch klinisch valide, wenn das untersuchte Gewebe die Fragestellung nicht repräsentiert.":"Un diagnostic molecular reușit tehnic nu este automat valid clinic dacă țesutul analizat nu reprezintă întrebarea clinică.","HE-Reevaluation des eingesandten Blocks":"Reevaluare H&E a blocului trimis","Tubulovillöses Adenom mit hochgradiger intraepithelialer Neoplasie; kein sicher invasives Karzinom im eingesandten Material.":"Adenom tubulovilos cu neoplazie intraepitelială de grad înalt; fără carcinom invaziv cert în materialul trimis.","Diskrepanz":"Discrepanță","Die klinische Anforderung lautet metastasiertes CRC, der ausgewählte Block repräsentiert jedoch nur den früheren Polypenrest.":"Solicitarea clinică este pentru CRC metastatic, dar blocul selectat reprezintă doar restul polipului anterior.","Verfügbarer Alternativblock":"Bloc alternativ disponibil","Im Archiv ist Resektionsblock B7 mit invasivem Adenokarzinom und ca. 60 % Tumor dokumentiert.":"În arhivă este documentat blocul de rezecție B7 cu adenocarcinom invaziv și aprox. 60 % tumoră.","Darf der Polypenblock trotzdem molekular befundet werden oder muss die Analyse gestoppt und repräsentatives invasives Tumormaterial angefordert werden?":"Poate fi totuși raportat molecular blocul de polip sau trebuie oprită analiza și solicitat material reprezentativ de tumoră invazivă?","Eingesandter Block":"Bloc trimis","Polypektomie A1, adenomatöses Gewebe ohne sichere Invasion.":"Polipectomie A1, țesut adenomatos fără invazie certă.","Tumoranteil für die klinische Fragestellung":"Fracție tumorală pentru întrebarea clinică","0 % sicher invasives Karzinom.":"0 % carcinom invaziv cert.","Technische DNA-Qualität":"Calitatea tehnică a ADN","gut – genau das macht die Falle gefährlich.":"bună – exact ceea ce face capcana periculoasă.","Archivhinweis":"Notă de arhivă","Resektionsblock B7 ist verfügbar und enthält repräsentatives invasives Karzinom.":"Blocul de rezecție B7 este disponibil și conține carcinom invaziv reprezentativ.","Ein molekular technisch plausibler Befund aus dem Polypenrest darf nicht als Biomarkerbefund des metastasierten invasiven Karzinoms ausgegeben werden.":"Un rezultat molecular tehnic plauzibil din restul de polip nu trebuie emis ca rezultat de biomarker al carcinomului invaziv metastatic.","Materialidentität / HE-Reevaluation":"Identitatea materialului / reevaluare H&E","Repräsentatives invasives Tumormaterial anfordern":"Solicitați material reprezentativ de tumoră invazivă","HE-Reevaluation":"Reevaluare H&E","Im eingesandten Block findet sich adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Das Material repräsentiert die klinische Fragestellung nicht.":"Blocul trimis conține țesut adenomatos cu displazie de grad înalt, dar fără carcinom invaziv cert. Materialul nu reprezintă întrebarea clinică.","Neues / korrektes Tumormaterial":"Material tumoral nou / corect","Resektionsblock B7 wird nachgefordert: invasives kolorektales Adenokarzinom, ca. 60 % Tumoranteil, für prädiktive Molekulardiagnostik geeignet.":"Se solicită blocul de rezecție B7: adenocarcinom colorectal invaziv, aprox. 60 % fracție tumorală, adecvat diagnosticului molecular predictiv.","MMR/MSI auf dem falschen Block":"MMR/MSI pe blocul greșit","Die Untersuchung kann technisch auswertbar sein, beantwortet aber am adenomatösen Polypenrest die Biomarkerfrage des invasiven/metastasierten Karzinoms nicht belastbar. Keine klinische Freigabe als Tumorbefund.":"Testul poate fi evaluabil tehnic, dar pe restul adenomatos de polip nu răspunde fiabil la întrebarea de biomarker a carcinomului invaziv/metastatic. Nu îl eliberați clinic ca rezultat tumoral.","NGS/RAS/BRAF auf dem falschen Block":"NGS/RAS/BRAF pe blocul greșit","Technisch plausibler Befund aus adenomatösem Gewebe – z. B. APC-Alteration bei fehlendem RAS/BRAF-Nachweis. Dieser Befund darf nicht als prädiktiver Status des invasiven/metastasierten CRC interpretiert werden.":"Rezultat tehnic plauzibil din țesut adenomatos – de ex. alterare APC fără RAS/BRAF detectabil. Acesta nu trebuie interpretat ca status predictiv al CRC invaziv/metastatic.","Präanalytik":"Preanalitică","Anforderung, Blockbezeichnung und Histologie sind diskordant; vor Freigabe muss die Probenidentität bzw. Repräsentativität geklärt werden.":"Solicitarea, denumirea blocului și histologia sunt discordante; identitatea/reprezentativitatea probei trebuie clarificată înainte de eliberare.","Der eingesandte Polypenblock ist für die prädiktive Diagnostik des metastasierten invasiven CRC nicht geeignet. Die Analyse muss für diese klinische Fragestellung gestoppt bzw. nicht freigegeben und repräsentatives invasives Tumormaterial angefordert werden. Ein technisch erfolgreicher Befund aus dem falschen Gewebe wäre klinisch irreführend.":"Blocul de polip trimis nu este adecvat diagnosticului predictiv al CRC invaziv metastatic. Analiza trebuie oprită/nu trebuie eliberată pentru această întrebare clinică și trebuie solicitat material reprezentativ de tumoră invazivă. Un rezultat tehnic reușit din țesutul greșit ar fi clinic înșelător.","Teilbefund: Ohne HE-Reevaluation und Abgleich der Blockidentität bleibt unklar, ob das untersuchte Material den invasiven Tumor repräsentiert. Molekulare Ergebnisse dürfen nicht allein aufgrund technischer QC freigegeben werden.":"Rezultat parțial: fără reevaluare H&E și verificarea identității blocului rămâne neclar dacă materialul analizat reprezintă tumora invazivă. Rezultatele moleculare nu trebuie eliberate doar pe baza QC tehnic.","Falsches/nicht repräsentatives Material als primäres Problem erkennen":"Recunoașteți materialul greșit/nereprezentativ ca problema principală","Molekulare Freigabe stoppen bzw. nicht als invasiven Tumor befundet ausgeben":"Opriți eliberarea moleculară sau nu o emiteți ca rezultat al tumorii invazive","Diskrepanz und Grund der Nachforderung transparent mit Klinik/Pathologie kommunizieren":"Comunicați transparent discrepanța și motivul solicitării noului material cu clinica/patologia","Technische Validität klar von klinischer Validität unterscheiden":"Distingeți clar validitatea tehnică de validitatea clinică","Optimale Lösung: zuerst HE und Materialidentität prüfen; der eingesandte Polypenrest ist klinisch ungeeignet. Nicht 'irgendetwas' sequenzieren und befundbar machen, sondern den richtigen invasiven Tumorblock anfordern.":"Soluția optimă: verificați mai întâi H&E și identitatea materialului; restul de polip trimis este clinic neadecvat. Nu secvențiați «ce este disponibil» pentru a-l face raportabil; solicitați blocul corect cu tumoră invazivă.","falsches Material":"material greșit","Materialidentität":"Identitatea materialului","LAB":"LAB","Falscher Block, perfektes QC: Wann ein technisch guter Befund klinisch wertlos ist":"Bloc greșit, QC perfect: când un rezultat tehnic bun este clinic fără valoare","Molekularpathologie / Pathologieassistenz / Labor":"Patologie moleculară / Asistență în patologie / Laborator","Repräsentativität des Materials vor Molekulardiagnostik prüfen.":"Verificați reprezentativitatea materialului înainte de diagnosticul molecular.","Technische Validität von klinischer Validität unterscheiden.":"Distingeți validitatea tehnică de cea clinică.","Bei falschem/nicht invasivem Material die Freigabe stoppen und korrektes Tumorgewebe anfordern.":"Pentru material greșit/neinvaziv, opriți eliberarea și solicitați țesut tumoral corect.","Eine Präanalytik-Diskrepanz nachvollziehbar dokumentieren und kommunizieren.":"Documentați și comunicați trasabil o discrepanță preanalitică.","Die DNA-QC ist hervorragend, der Tumorboard-Termin ist nah und der Auftrag lautet RAS/BRAF/MMR/MSI. Der einzige Haken: Auf dem Kontroll-HE liegt gar kein invasives Karzinom, sondern nur der Rest eines früheren Adenoms. Genau jetzt entscheidet sich, ob 'gute Technik' zur gefährlichen Scheinsicherheit wird.":"QC-ul ADN este excelent, tumor board-ul se apropie, iar solicitarea este RAS/BRAF/MMR/MSI. Singura problemă: pe H&E de control nu există deloc carcinom invaziv, ci doar restul unui adenom anterior. Exact aici «tehnica bună» poate deveni o falsă siguranță periculoasă.","64-jähriger Patient mit metastasiertem Sigma-Karzinom. Für die prädiktive Molekulardiagnostik wurde versehentlich der Block einer früheren Polypektomie ausgewählt. Er enthält adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Ein repräsentativer Resektionsblock ist im Archiv vorhanden.":"Pacient de 64 de ani cu carcinom sigmoid metastatic. Pentru diagnosticul molecular predictiv a fost selectat din greșeală blocul unei polipectomii anterioare. Acesta conține țesut adenomatos cu displazie de grad înalt, dar fără carcinom invaziv cert. În arhivă este disponibil un bloc de rezecție reprezentativ.","RAS/BRAF und MMR/MSI vor Systemtherapie.":"RAS/BRAF și MMR/MSI înainte de terapia sistemică.","Die klinische Frage bezieht sich auf das invasive/metastasierte Karzinom.":"Întrebarea clinică se referă la carcinomul invaziv/metastatic.","Polypektomie A1 mit Adenom/HGIEN, ohne sichere Invasion.":"Polipectomie A1 cu adenom/HGIEN, fără invazie certă.","Die Probenidentität ist klinisch falsch, obwohl die DNA technisch gut sein kann.":"Identitatea probei este clinic greșită, chiar dacă ADN-ul poate fi tehnic bun.","Alternativmaterial":"Material alternativ","Resektionsblock B7 mit ca. 60 % invasivem Tumor ist verfügbar.":"Blocul de rezecție B7 cu aprox. 60 % tumoră invazivă este disponibil.","Die richtige Lösung ist Nachforderung/Blockwechsel, nicht Interpretation des falschen Materials.":"Soluția corectă este solicitarea/schimbarea blocului, nu interpretarea materialului greșit.","Kein sicher invasives Karzinom im eingesandten Block.":"Fără carcinom invaziv cert în blocul trimis.","Sehr gute DNA-Qualität – technisch wären PCR/NGS problemlos möglich.":"Calitate ADN foarte bună – tehnic PCR/NGS ar fi fără probleme.","LIMS-Abgleich":"Verificare LIMS","Block A1 gehört zur Polypektomie; Resektionsblock B7 trägt den invasiven Tumor.":"Blocul A1 aparține polipectomiei; blocul de rezecție B7 conține tumora invazivă.","MTB in vier Tagen erzeugt realen Zeitdruck.":"MTB în patru zile creează presiune reală de timp.","Das korrekte Material existiert, muss aber aktiv nachgefordert/umgebucht werden.":"Materialul corect există, dar trebuie solicitat/realocat activ.","Jede Molekulardiagnostik am falschen Block produziert potenziell einen technisch plausiblen, klinisch irreführenden Befund.":"Orice testare moleculară pe blocul greșit poate produce un rezultat tehnic plauzibil, dar clinic înșelător.","Was ist der nächste entscheidende Schritt?":"Care este următorul pas decisiv?","HE/Blockidentität prüfen, Analyse am Polypenrest stoppen und repräsentatives invasives Tumormaterial anfordern.":"Verificați H&E/identitatea blocului, opriți analiza pe restul de polip și solicitați material reprezentativ de tumoră invazivă.","Wegen des MTB-Termins sofort NGS durchführen; gute DNA-QC reicht.":"Din cauza termenului MTB, efectuați imediat NGS; QC ADN bun este suficient.","Nur MMR-IHC durchführen und den Rest später entscheiden.":"Efectuați doar IHC MMR și decideți restul ulterior.","Molekularbefund aus dem Adenom als Status des metastasierten CRC berichten.":"Raportați rezultatul molecular din adenom ca status al CRC metastatic.","Präanalytische Repräsentativität ist Voraussetzung jeder klinischen Interpretation.":"Reprezentativitatea preanalitică este o condiție prealabilă pentru orice interpretare clinică.","Ein NGS-Lauf aus dem Polypenrest ist technisch valide. Ist der Befund damit klinisch valide?":"Un run NGS din restul de polip este tehnic valid. Devine astfel rezultatul clinic valid?","Nein. Ein technisch korrekter Befund kann klinisch unbrauchbar sein, wenn das analysierte Gewebe die Fragestellung nicht repräsentiert.":"Nu. Un rezultat tehnic corect poate fi clinic inutilizabil dacă țesutul analizat nu reprezintă întrebarea clinică.","Ja. Technische QC ist die einzige Voraussetzung für Freigabe.":"Da. QC tehnic este singura condiție pentru eliberare.","Ja, sofern RAS/BRAF Wildtyp sind.":"Da, dacă RAS/BRAF sunt wild type.","Ja, wenn ein breites Panel benutzt wurde.":"Da, dacă s-a folosit un panel larg.","Analytische Qualität ersetzt nicht Probenidentität und klinische Repräsentativität.":"Calitatea analitică nu înlocuiește identitatea probei și reprezentativitatea clinică.","Wie soll die Diskrepanz behandelt werden?":"Cum trebuie gestionată discrepanța?","Dokumentieren, Einsender/Pathologie kontaktieren, korrekten Block nachfordern und erst dann prädiktiv testen.":"Documentați, contactați trimițătorul/patologia, solicitați blocul corect și abia apoi efectuați testarea predictivă.","Intern korrigieren, aber nicht dokumentieren.":"Corectați intern, dar nu documentați.","Annehmen, dass Polyp und Karzinom denselben Biomarkerstatus haben.":"Presupuneți că polipul și carcinomul au același status de biomarkeri.","Gesamten Fall endgültig abbrechen, obwohl geeignetes Material vorhanden ist.":"Abandonați definitiv întregul caz, deși există material adecvat.","Rückverfolgbarkeit und transparente Kommunikation gehören zur Fehlerbeherrschung.":"Trasabilitatea și comunicarea transparentă fac parte din controlul erorilor.","Entscheiden Sie, ob der Polypenrest befundbar ist, und steuern Sie den Fall so, dass nur repräsentatives invasives Tumorgewebe in die prädiktive Diagnostik eingeht.":"Decideți dacă restul de polip poate fi raportat și gestionați cazul astfel încât doar țesutul tumoral invaziv reprezentativ să intre în diagnosticul predictiv.","Kontroll-HE des ausgewählten Blocks prüfen.":"Revizuiți H&E de control al blocului selectat.","Diskrepanz zwischen Anforderung und Histologie erkennen.":"Recunoașteți discrepanța dintre solicitare și histologie.","Molekulare Freigabe am Polypenrest stoppen.":"Opriți eliberarea moleculară din restul de polip.","Resektionsblock B7 bzw. anderes repräsentatives invasives Material anfordern.":"Solicitați blocul de rezecție B7 sau alt material invaziv reprezentativ.","Diskrepanz und Kommunikation dokumentieren.":"Documentați discrepanța și comunicarea.","Erst am korrekten Tumormaterial mit RAS/BRAF/MMR/MSI fortfahren.":"Continuați cu RAS/BRAF/MMR/MSI doar pe materialul tumoral corect.","Geeignete Metastasenbiopsie anfordern, falls der Resektionsblock nicht verfügbar/qualitativ ungeeignet wäre.":"Solicitați o biopsie metastatică adecvată dacă blocul de rezecție nu este disponibil/necorespunzător calitativ.","'DNA ist gut, also los'":"«ADN-ul este bun, deci continuăm»","Technische QC sagt nichts darüber aus, ob die richtige Läsion untersucht wird.":"QC tehnic nu spune nimic despre faptul că este analizată leziunea corectă.","Adenom-Biomarker = Karzinom-Biomarker":"Biomarker adenom = biomarker carcinom","Klonale Evolution und fehlende Repräsentativität machen diese Gleichsetzung unzulässig.":"Evoluția clonală și lipsa reprezentativității fac această echivalare nevalidă.","Zeitdruck als Freigabeargument":"Presiunea timpului ca argument pentru eliberare","Ein schneller falscher Befund ist schlechter als eine dokumentierte Nachforderung.":"Un rezultat rapid, dar greșit, este mai rău decât o solicitare documentată de material corect.","Der falsche Block liefert einen überzeugenden Befund":"Blocul greșit produce un rezultat convingător","Wird voreilig sequenziert, zeigt das Adenom eine plausible APC-Alteration und keinen RAS/BRAF-Treiber. Technisch sieht alles sauber aus. Erst der HE-/LIMS-Abgleich zeigt, dass dieser Befund für das invasive metastasierte CRC gar nicht freigegeben werden darf.":"Dacă secvențierea este efectuată prematur, adenomul arată o alterare APC plauzibilă și niciun driver RAS/BRAF. Tehnic totul arată curat. Abia verificarea H&E/LIMS arată că acest rezultat nu poate fi eliberat pentru CRC invaziv metastatic.","Die gefährlichsten Präanalytikfehler produzieren nicht zwingend einen technischen Fehler – sondern einen glaubwürdigen Befund am falschen Material.":"Cele mai periculoase erori preanalitice nu produc neapărat o eroare tehnică – pot produce un rezultat credibil pe materialul greșit.","Materialfehler vor Analytik gestoppt":"Eroare de material oprită înainte de analiză","HE zeigt kein invasives Karzinom; korrekter Resektionsblock B7 wird angefordert.":"H&E nu arată carcinom invaziv; se solicită blocul corect de rezecție B7.","Patientensicher und ressourcenschonend.":"Sigur pentru pacient și eficient din punct de vedere al resurselor.","Technisch erfolgreich, klinisch falsch":"Tehnic reușit, clinic greșit","NGS aus Adenom: APC-Alteration, RAS/BRAF WT. Befund darf nicht als metastasiertes CRC interpretiert werden.":"NGS din adenom: alterare APC, RAS/BRAF WT. Rezultatul nu trebuie interpretat ca CRC metastatic.","Analytisch valide, klinisch invalide.":"Valid analitic, invalid clinic.","Falschen Block freigegeben":"Bloc greșit eliberat","Adenom-Befund wird als Tumorprofil berichtet.":"Rezultatul adenomului este raportat ca profil tumoral.","Kritischer Präanalytik-/Freigabefehler.":"Eroare critică preanalitică/de eliberare.","Resektionsblock B7 verfügbar":"Blocul de rezecție B7 disponibil","Kontroll-HE, Tumormarkierung und reguläre CRC-Biomarkerdiagnostik durchführen.":"Efectuați H&E de control, marcarea tumorii și diagnosticul standard de biomarkeri CRC.","Der Fall kann ohne neue invasive Probengewinnung korrekt abgeschlossen werden.":"Cazul poate fi finalizat corect fără obținerea unei noi probe invazive.","Kein geeignetes Archivmaterial":"Fără material de arhivă adecvat","Mit Klinik eine geeignete Metastasen- oder Primärtumorprobe abstimmen.":"Coordonați cu clinica o probă adecvată de metastază sau tumoră primară.","TAT steigt, klinische Validität bleibt gewahrt.":"TAT crește, validitatea clinică este menținută.","Materialidentität und Repräsentativität stehen vor analytischer QC.":"Identitatea și reprezentativitatea materialului preced QC-ul analitic.","Ein technisch valider Befund kann klinisch falsch sein.":"Un rezultat tehnic valid poate fi clinic greșit.","Polyp/Adenom ist kein automatischer Surrogatblock für ein invasives metastasiertes CRC.":"Polipul/adenomul nu este un bloc surogat automat pentru CRC invaziv metastatic.","Zeitdruck rechtfertigt keine Freigabe aus falschem Material.":"Presiunea timpului nu justifică eliberarea din materialul greșit.","HE-Reevaluation zeigt nur Adenom/HGIEN. Molekulare Freigabe stoppen, Blockidentität klären und Resektionsblock B7 mit invasivem Tumor anfordern. Etwaige bereits erzeugte Daten aus dem Polypenrest nicht als prädiktiven Tumorbefund freigeben.":"Reevaluarea H&E arată doar adenom/HGIEN. Opriți eliberarea moleculară, clarificați identitatea blocului și solicitați blocul de rezecție B7 cu tumoră invazivă. Nu eliberați datele deja generate din restul de polip ca rezultat predictiv tumoral.","Präanalytik vor Analytik":"Preanalitică înainte de analitică","Stop/No-Go korrekt":"Stop/No-Go corect","korrektes Material angefordert":"material corect solicitat","technische vs. klinische Validität verstanden":"validitate tehnică vs. clinică înțeleasă","Welche Kontrollen verhindern solche Blockverwechslungen?":"Ce controale previn astfel de confuzii de blocuri?","Wann kann ein Vorläuferläsionsblock überhaupt sinnvoll molekular untersucht werden?":"Când poate fi investigat molecular în mod util un bloc de leziune precursoare?","Wie dokumentiert man einen bereits erzeugten, aber klinisch nicht freigabefähigen Datensatz?":"Cum trebuie documentat un set de date deja generat, dar care nu poate fi eliberat clinic?","perfekte DNA aus falschem Gewebe":"ADN perfect din țesutul greșit","technisch valide ≠ klinisch valide":"valid tehnic ≠ valid clinic","HE → Diskrepanz → Stop → korrekter Block":"H&E → discrepanță → stop → bloc corect","HER2-amplifiziertes RAS-WT-CRC → HER2 als Resistenz-/Target-Kontext":"CRC RAS-WT amplificat HER2 → HER2 ca context de rezistență/target","HER2-amplifiziertes RAS-WT-CRC":"CRC RAS-WT amplificat HER2","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom. Initial RAS/BRAF-Wildtyp und pMMR/MSS; unter FOLFOX plus Cetuximab zunächst deutliche Remission, jetzt hepatischer Progress.":"Pacient de 61 de ani cu carcinom sigmoid metastatic stâng. Inițial RAS/BRAF wild type și pMMR/MSS; remisiune marcată sub FOLFOX plus cetuximab, acum progresie hepatică.","Der Progressionsbefund zeigt weiterhin keine RAS- oder BRAF-Mutation, aber einen ERBB2/HER2-Copy-number-Hinweis. Wie ist das therapeutisch zu interpretieren?":"Proba de progresie nu arată în continuare mutație RAS sau BRAF, dar sugerează un câștig de copy-number ERBB2/HER2. Cum trebuie interpretat terapeutic?","Die nächste Therapielinie soll im MTB in fünf Tagen festgelegt werden.":"Următoarea linie terapeutică trebuie stabilită în MTB în cinci zile.","Sigma, linksseitig; initiale Resektion vor 18 Monaten.":"Sigmoid, stâng; rezecție inițială cu 18 luni în urmă.","Initiales Molekularprofil":"Profil molecular inițial","KRAS/NRAS Wildtyp, BRAF Wildtyp, pMMR/MSS.":"KRAS/NRAS wild type, BRAF wild type, pMMR/MSS.","Therapieverlauf":"Evoluția tratamentului","FOLFOX plus Cetuximab mit gutem initialem Ansprechen; nach 11 Monaten Progress einzelner Leberläsionen.":"FOLFOX plus cetuximab cu răspuns inițial bun; progresia unor leziuni hepatice după 11 luni.","Didaktischer Schlüssel":"Cheie didactică","Der Satz 'RAS und BRAF negativ' ist beim mCRC therapeutisch nicht einfach 'kein Befund': Das Fehlen etablierter MAPK-Downstream-Resistenztreiber ist eine Voraussetzung, die anti-EGFR-Antikörperstrategie bei passendem klinischem Kontext überhaupt eröffnet.":"În mCRC, formularea «RAS și BRAF negative» nu înseamnă terapeutic pur și simplu «niciun rezultat»: absența driverilor consacrați de rezistență downstream MAPK este o condiție care face posibilă o strategie cu anticorpi anti-EGFR într-un context clinic adecvat.","Warum kann der Tumor trotz weiterem RAS/BRAF-Wildtyp progredient sein, und welche Rolle spielt HER2?":"De ce poate progresa tumora în ciuda menținerii RAS/BRAF wild type și ce rol are HER2?","Progressionsbiopsie":"Biopsie de progresie","Lebermetastase eines kolorektalen Adenokarzinoms, vital und gut repräsentativ.":"Metastază hepatică de adenocarcinom colorectal, viabilă și bine reprezentativă.","ca. 65 %.":"aprox. 65 %.","Aus der Primärdiagnostik pMMR/MSS, klinisch ausreichend dokumentiert.":"pMMR/MSS din diagnosticul inițial, suficient documentat clinic.","Progressionsprofil":"Profil de progresie","Kein RAS-/BRAF-Resistenzbefund; ERBB2 mit deutlicher Copy-number-Erhöhung im DNA-Panel.":"Fără rezultat de rezistență RAS/BRAF; ERBB2 cu creștere marcată a numărului de copii în panelul ADN.","Ist die ERBB2-Veränderung bestätigt, und wie verändert sie die scheinbar 'negative' RAS/BRAF-Situation?":"Este confirmată alterarea ERBB2 și cum schimbă ea situația aparent «negativă» RAS/BRAF?","FFPE-Lebermetastasenbiopsie, Block L3.":"Biopsie FFPE de metastază hepatică, bloc L3.","ca. 65 %, DNA-QC sehr gut.":"aprox. 65 %, QC ADN foarte bun.","HER2-Bestätigung":"Confirmare HER2","IHC/ISH ist am vorhandenen Material möglich.":"IHC/ISH este posibilă pe materialul disponibil.","Breite Wiederholung bereits gesicherter MMR/MSI-Diagnostik verbraucht Material, während die konkrete Progressionsfrage HER2-Bestätigung und Resistenzkontext betrifft.":"Repetarea largă a diagnosticului MMR/MSI deja stabilit consumă material, în timp ce întrebarea concretă de progresie privește confirmarea HER2 și contextul de rezistență.","Progressionsprofil / RAS-BRAF-ERBB2-Kontext":"Profil de progresie / context RAS-BRAF-ERBB2","HER2-Amplifikation bestätigen":"Confirmați amplificarea HER2","KRAS/NRAS weiterhin Wildtyp, BRAF Wildtyp; keine neue klassische RAS/RAF-Resistenzmutation. ERBB2 zeigt eine hochgradige Copy-number-Erhöhung.":"KRAS/NRAS rămân wild type, BRAF wild type; fără mutație clasică nouă de rezistență RAS/RAF. ERBB2 arată o creștere de copy-number de nivel înalt.","KRAS/NRAS Wildtyp. Das Fehlen einer RAS-Mutation ist im geeigneten linksseitigen mCRC-Kontext therapeutisch relevant, garantiert aber keine dauerhafte Sensitivität gegenüber anti-EGFR-Antikörpern.":"KRAS/NRAS wild type. Absența unei mutații RAS este relevantă terapeutic în contextul adecvat de mCRC stâng, dar nu garantează sensibilitate durabilă la anticorpi anti-EGFR.","BRAF V600E nicht nachweisbar. RAS/BRAF-Wildtyp bedeutet nicht 'molekular ohne Bedeutung', sondern schließt wichtige etablierte MAPK-Resistenztreiber aus.":"BRAF V600E nu este detectabil. RAS/BRAF wild type nu înseamnă «fără semnificație moleculară»; exclude drivere MAPK importante și consacrate de rezistență.","HER2 IHC/ISH":"IHC/ISH HER2","HER2 stark überexprimiert / ERBB2 amplifiziert. Der Befund ist im RAS/BRAF-WT-mCRC ein relevanter Target- und möglicher anti-EGFR-Resistenzkontext, insbesondere in der Progressionssituation.":"HER2 supraexprimat intens / ERBB2 amplificat. În mCRC RAS/BRAF-WT, rezultatul reprezintă un target relevant și un posibil context de rezistență la anti-EGFR, în special la progresie.","HER2-IHC allein":"Doar IHC HER2","HER2 IHC 3+. Im CRC-Kontext sollte die zugrunde liegende ERBB2-Amplifikation bzw. ein validierter HER2-positiver Status nach lokalem Algorithmus gesichert werden.":"HER2 IHC 3+. În context CRC, amplificarea ERBB2 subiacentă sau un status HER2-pozitiv validat trebuie confirmat conform algoritmului local.","Erneute MMR/MSI-Testung":"Repetare testare MMR/MSI","pMMR/MSS wird bestätigt. In diesem Fall war der Status bereits belastbar bekannt; die Wiederholung beantwortet die konkrete Progressions-/HER2-Frage kaum und ist daher eher ressourcenarm zu priorisieren.":"pMMR/MSS este confirmat. În acest caz statusul era deja cunoscut în mod robust; repetarea răspunde foarte puțin întrebării concrete de progresie/HER2 și ar trebui deci prioritizată scăzut din perspectiva resurselor.","Progressionsbiopsie repräsentativ; hohe Tumorzellularität und gute DNA-Qualität. Baseline-HER2-Status war nicht bestimmt.":"Biopsie de progresie reprezentativă; celularitate tumorală mare și calitate ADN bună. Statusul HER2 de baseline nu a fost determinat.","RAS/BRAF-Wildtyp ist beim linksseitigen mCRC kein bedeutungsloser Negativbefund: Das Fehlen zentraler downstream MAPK-Resistenztreiber schafft erst die molekulare Voraussetzung für eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext. Wildtyp garantiert jedoch keine Sensitivität. Im Progress wird eine bestätigte ERBB2/HER2-Amplifikation gefunden, die einen alternativen Signalweg, einen möglichen anti-EGFR-Resistenzkontext und zugleich eine HER2-gerichtete Therapieoption im passenden Linien-/Zulassungskontext eröffnet. Ohne Baseline-HER2 kann nicht sicher behauptet werden, dass die Amplifikation neu erworben wurde.":"RAS/BRAF wild type nu este un rezultat negativ lipsit de sens în mCRC stâng: absența driverilor principali downstream MAPK de rezistență creează premisa moleculară pentru o strategie cu anticorpi anti-EGFR în contextul clinic adecvat. Totuși, wild type nu garantează sensibilitatea. La progresie se găsește o amplificare ERBB2/HER2 confirmată, care deschide o cale alternativă de semnalizare, un posibil context de rezistență anti-EGFR și totodată o opțiune de terapie anti-HER2 în contextul corespunzător de linie/aprobare. Fără HER2 de baseline nu se poate afirma cu certitudine că amplificarea este nou dobândită.","Teilbefund: RAS/BRAF-Wildtyp ist korrekt erkannt, aber entweder wird 'negativ' fälschlich als therapeutisch bedeutungslos bezeichnet oder die ERBB2-Copy-number-Veränderung bleibt unbestätigt. Beides verhindert eine belastbare Progressionsinterpretation.":"Rezultat parțial: RAS/BRAF wild type este recunoscut corect, dar fie «negativ» este descris eronat ca lipsit de semnificație terapeutică, fie alterarea copy-number ERBB2 rămâne neconfirmată. Ambele împiedică o interpretare robustă a progresiei.","Explizit erklären: RAS/BRAF-Wildtyp ist ein therapeutisch relevanter 'negativer' Befund, der anti-EGFR bei passendem linksseitigem mCRC-Kontext ermöglicht":"Explicați explicit: RAS/BRAF wild type este un rezultat de selecție «negativ» relevant terapeutic, care permite anti-EGFR în contextul adecvat de mCRC stâng","Wildtyp nicht als Garantie für anti-EGFR-Sensitivität darstellen":"Nu prezentați wild type ca garanție a sensibilității anti-EGFR","HER2-Amplifikation als alternativen Target-/Resistenzkontext integrieren":"Integrați amplificarea HER2 ca context alternativ de target/rezistență","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher neu erworben":"Fără HER2 de baseline, nu afirmați că amplificarea este cu certitudine nou dobândită","Aktuelle Linien-/Leitlinien-/Zulassungssituation für HER2-gerichtete Therapie transparent berücksichtigen":"Țineți cont transparent de contextul actual de linie/ghid/aprobare pentru terapia anti-HER2","Optimale Lösung: den RAS/BRAF-Wildtyp bewusst als therapeutisch positiven Selektionsbefund erklären; Progress trotz Wildtyp als Hinweis auf alternative Resistenzwege verstehen und die ERBB2/HER2-Amplifikation bestätigen und als Target-/Resistenzkontext integrieren.":"Soluția optimă: explicați deliberat RAS/BRAF wild type ca rezultat de selecție terapeutic pozitiv; înțelegeți progresia în ciuda wild type ca indiciu pentru căi alternative de rezistență și confirmați amplificarea ERBB2/HER2, integrând-o ca target/context de rezistență.","RAS Wildtyp":"RAS wild type","BRAF Wildtyp":"BRAF wild type","ERBB2 Amplifikation":"Amplificare ERBB2","Resistenz":"Rezistență","Wenn 'negativ' therapeutisch positiv ist: RAS/BRAF-Wildtyp, anti-EGFR und der HER2-Twist":"Când «negativ» este terapeutic pozitiv: RAS/BRAF wild type, anti-EGFR și twist-ul HER2","RAS/BRAF-Wildtyp als therapeutisch relevanten negativen Selektionsbefund im mCRC erklären.":"Explicați RAS/BRAF wild type ca rezultat negativ de selecție relevant terapeutic în mCRC.","Anti-EGFR-Eignung als Kontextentscheidung und nicht als garantierte Sensitivität verstehen.":"Înțelegeți eligibilitatea anti-EGFR ca decizie contextuală, nu ca sensibilitate garantată.","HER2/ERBB2-Amplifikation als alternativen Target- und möglichen Resistenzkontext integrieren.":"Integrați amplificarea HER2/ERBB2 ca target alternativ și posibil context de rezistență.","Zwischen 'nach Progress nachgewiesen' und 'erworben' unterscheiden, wenn kein Baseline-HER2 vorliegt.":"Distingeți «detectat după progresie» de «dobândit» atunci când nu există HER2 de baseline.","Im Progressions-MTB steht auf der Folie: 'KRAS, NRAS, BRAF: keine Mutation nachweisbar'. Ein Kollege fasst zusammen: 'Molekular also wieder negativ.' Genau hier liegt der Kern des Falls: Beim mCRC kann ein negativer RAS/BRAF-Befund therapeutisch eine positive Information sein – und trotzdem erklärt er den jetzigen Progress nicht. Im selben Panel taucht nämlich eine deutliche ERBB2-Copy-number-Erhöhung auf.":"Pe slide-ul MTB de progresie scrie: «KRAS, NRAS, BRAF: nicio mutație detectată». Un coleg rezumă: «Deci molecular din nou negativ.» Exact aici este nucleul cazului: în mCRC, un rezultat RAS/BRAF negativ poate fi o informație terapeutic pozitivă – și totuși să nu explice progresia actuală. În același panel apare însă o creștere marcată a copy-number ERBB2.","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom, initial RAS/BRAF-Wildtyp und pMMR/MSS. Unter FOLFOX plus Cetuximab gutes Ansprechen, nach elf Monaten Progress in der Leber. Die Progressionsbiopsie bleibt RAS/BRAF-Wildtyp, zeigt aber eine hochgradige ERBB2-Copy-number-Erhöhung. Der Fall soll den scheinbaren Widerspruch 'negativ = therapeutisch positiv' erklären und anschließend HER2 als alternativen Resistenz-/Targetkontext einordnen.":"Pacient de 61 de ani cu carcinom sigmoid metastatic stâng, inițial RAS/BRAF wild type și pMMR/MSS. Răspuns bun la FOLFOX plus cetuximab, progresie hepatică după 11 luni. Biopsia de progresie rămâne RAS/BRAF wild type, dar arată o creștere de copy-number ERBB2 de nivel înalt. Cazul explică aparenta contradicție «negativ = terapeutic pozitiv» și apoi încadrează HER2 ca un context alternativ de rezistență/target.","Baseline":"Baseline","Linksseitiges mCRC, RAS/BRAF-Wildtyp, pMMR/MSS.":"mCRC stâng, RAS/BRAF wild type, pMMR/MSS.","Dieser Molekularkontext ermöglichte grundsätzlich eine anti-EGFR-Antikörperstrategie.":"Acest context molecular a făcut posibilă în principiu o strategie cu anticorpi anti-EGFR.","Gutes initiales Ansprechen unter FOLFOX + Cetuximab, Progress nach 11 Monaten.":"Răspuns inițial bun la FOLFOX + cetuximab, progresie după 11 luni.","Wildtyp ist Selektion, keine Garantie dauerhafter Sensitivität.":"Wild type este selecție, nu garanție a sensibilității durabile.","Weiterhin RAS/BRAF-Wildtyp, aber ERBB2-Copy-number hoch.":"În continuare RAS/BRAF wild type, dar copy-number ERBB2 crescut.","Resistenz kann über alternative Signalwege entstehen/bestehen.":"Rezistența poate apărea/persista prin căi alternative de semnalizare.","Limitation":"Limitare","HER2 wurde an der Baseline nicht bestimmt.":"HER2 nu a fost determinat la baseline.","Die aktuelle Amplifikation darf nicht sicher als neu erworben bezeichnet werden.":"Amplificarea actuală nu poate fi descrisă cu certitudine ca nou dobândită.","Initialdiagnostik":"Diagnostic inițial","KRAS/NRAS WT, BRAF WT, pMMR/MSS.":"KRAS/NRAS WT, BRAF WT, pMMR/MSS.","Aktueller Progress":"Progresie actuală","Lebermetastasenbiopsie mit 65 % Tumor und guter DNA-QC.":"Biopsie de metastază hepatică cu 65 % tumoră și QC ADN bun.","Panel-Hinweis":"Indiciu din panel","ERBB2 hochgradige Copy-number-Erhöhung; RAS/BRAF weiter WT.":"Creștere de copy-number ERBB2 de nivel înalt; RAS/BRAF rămân WT.","Neun Schnitte reichen für HER2-Bestätigung und fokussierte Progressionsdiagnostik.":"Nouă secțiuni sunt suficiente pentru confirmarea HER2 și diagnosticul focalizat al progresiei.","MMR/MSI ist bereits belastbar dokumentiert und muss nicht reflexartig wiederholt werden.":"MMR/MSI este deja documentat robust și nu trebuie repetat reflex.","HER2-Status sollte orthogonal/validiert bestätigt werden, bevor die therapeutische Schlussfolgerung formuliert wird.":"Statusul HER2 trebuie confirmat ortogonal/printr-o metodă validată înainte de formularea concluziei terapeutice.","Wie ist 'KRAS/NRAS/BRAF: keine pathogene Mutation nachweisbar' beim linksseitigen mCRC therapeutisch zu lesen?":"Cum trebuie citit terapeutic «KRAS/NRAS/BRAF: nicio mutație patogenă detectată» în mCRC stâng?","Als therapeutisch relevanter Wildtyp-/Ausschlussbefund: zentrale downstream MAPK-Resistenztreiber fehlen, sodass eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext grundsätzlich möglich wird.":"Ca rezultat wild type/de excludere relevant terapeutic: lipsesc drivere downstream MAPK importante de rezistență, astfel încât o strategie cu anticorpi anti-EGFR devine posibilă în contextul clinic adecvat.","Als völlig bedeutungsloser Negativbefund ohne therapeutische Aussage.":"Ca rezultat negativ complet lipsit de semnificație terapeutică.","Als Garantie, dass anti-EGFR sicher und dauerhaft wirkt.":"Ca garanție că anti-EGFR va funcționa sigur și durabil.","Als Beweis, dass auch HER2 keine Rolle spielen kann.":"Ca dovadă că nici HER2 nu poate avea un rol.","Das Fehlen von RAS/BRAF-Treibern ist eine positive Selektionsinformation, aber keine Erfolgsgarantie.":"Absența driverilor RAS/BRAF este o informație pozitivă de selecție, dar nu o garanție de succes.","Der Patient progrediert trotz weiterem RAS/BRAF-Wildtyp. Was ist die beste Interpretation?":"Pacientul progresează în ciuda menținerii RAS/BRAF wild type. Care este cea mai bună interpretare?","Wildtyp schließt nur bestimmte Resistenzwege aus; alternative Mechanismen wie HER2/ERBB2 können relevant sein.":"Wild type exclude doar anumite căi de rezistență; mecanisme alternative precum HER2/ERBB2 pot fi relevante.","Progress beweist, dass der RAS/BRAF-Test falsch sein muss.":"Progresia dovedește că testul RAS/BRAF trebuie să fie greșit.","Damit war die ursprüngliche anti-EGFR-Strategie grundsätzlich falsch.":"Aceasta înseamnă că strategia anti-EGFR inițială a fost fundamental greșită.","Molekulare Diagnostik kann den Progress nicht mehr erklären.":"Diagnosticul molecular nu mai poate explica progresia.","Resistenzbiologie ist breiter als RAS/BRAF allein.":"Biologia rezistenței este mai largă decât RAS/BRAF singur.","Wie sollte die ERBB2-Copy-number-Erhöhung weiterbehandelt werden?":"Cum trebuie investigată în continuare creșterea copy-number ERBB2?","HER2-positiven Status mit validiertem IHC/ISH-Algorithmus bestätigen und als Target-/möglichen anti-EGFR-Resistenzkontext integrieren.":"Confirmați statusul HER2-pozitiv cu un algoritm validat IHC/ISH și integrați-l ca target/posibil context de rezistență anti-EGFR.","Ignorieren, da RAS/BRAF Wildtyp sind.":"Ignorați deoarece RAS/BRAF sunt wild type.","Ohne weitere Prüfung als sicher erworbene Resistenzmutation bezeichnen.":"Fără investigații suplimentare, denumiți-o mutație de rezistență sigur dobândită.","Unverändert nach Mammakarzinom-Regeln interpretieren.":"Interpretați neschimbat conform regulilor de cancer mamar.","HER2 ist entitätsspezifisch zu bestätigen und zu interpretieren; Baseline fehlt für eine sichere Akquisitionsaussage.":"HER2 trebuie confirmat și interpretat specific entității; lipsa baseline-ului împiedică o afirmație certă de achiziție.","Darf die HER2-Amplifikation als 'erworben unter Cetuximab' bezeichnet werden?":"Poate fi descrisă amplificarea HER2 ca «dobândită sub cetuximab»?","Nicht sicher. Ohne Baseline-HER2 kann sie präexistent gewesen oder unter Therapie selektiert/angereichert worden sein.":"Nu cu certitudine. Fără HER2 de baseline, putea fi preexistentă sau selectată/îmbogățită sub terapie.","Ja, weil sie erst beim Progress gemessen wurde.":"Da, deoarece a fost măsurată abia la progresie.","Ja, weil RAS/BRAF Wildtyp sind.":"Da, deoarece RAS/BRAF sunt wild type.","Die zeitliche Einordnung ist für die Befundsprache irrelevant.":"Încadrarea temporală este irelevantă pentru formularea raportului.","Nachweiszeitpunkt und biologischer Entstehungszeitpunkt sind nicht identisch.":"Momentul detectării și momentul biologic al apariției nu sunt identice.","Erklären Sie zuerst, warum RAS/BRAF-Wildtyp im mCRC eine therapeutisch relevante 'negative' Information ist. Integrieren Sie danach die bestätigte HER2-Amplifikation in die Progressions- und Targetinterpretation, ohne Überinterpretation der Akquisition.":"Explicați mai întâi de ce RAS/BRAF wild type în mCRC este o informație «negativă» relevantă terapeutic. Apoi integrați amplificarea HER2 confirmată în interpretarea progresiei și targetului fără a supra-interpreta achiziția.","Linksseitigkeit und initialen RAS/BRAF-Wildtyp zusammen mit pMMR/MSS erfassen.":"Integrați lateralitatea stângă și RAS/BRAF wild type inițial împreună cu pMMR/MSS.","RAS/BRAF-Wildtyp als Selektionsvoraussetzung für anti-EGFR-Antikörper erklären, nicht als 'kein Befund'.":"Explicați RAS/BRAF wild type ca premisă de selecție pentru anticorpi anti-EGFR, nu ca «niciun rezultat».","Progress trotz Wildtyp als Hinweis auf alternative Resistenzmechanismen verstehen.":"Înțelegeți progresia în ciuda wild type ca indiciu pentru mecanisme alternative de rezistență.","ERBB2-Copy-number-Befund durch HER2-IHC/ISH bestätigen.":"Confirmați rezultatul de copy-number ERBB2 prin IHC/ISH HER2.","HER2 als Target- und möglichen anti-EGFR-Resistenzkontext berichten.":"Raportați HER2 ca target și posibil context de rezistență anti-EGFR.","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher erworben.":"Fără HER2 de baseline, nu afirmați că amplificarea este cu certitudine dobândită.","Validiertes breit angelegtes Progressionspanel mit zuverlässiger ERBB2-CNV-Erfassung plus orthogonale HER2-Bestätigung.":"Panel larg validat de progresie cu detectare fiabilă a CNV ERBB2 plus confirmare HER2 ortogonală.","Bei nicht ausreichendem Gewebe ctDNA als ergänzender Resistenzansatz, sofern methodisch geeignet; negativer ctDNA-Befund würde Gewebe jedoch nicht automatisch ersetzen.":"Dacă țesutul este insuficient, ctDNA ca abordare complementară pentru rezistență dacă este metodologic adecvat; un rezultat ctDNA negativ nu ar înlocui automat țesutul.","'Alles negativ'":"«Totul negativ»","RAS/BRAF-Wildtyp ist therapeutisch relevante Selektionsinformation.":"RAS/BRAF wild type este informație de selecție relevantă terapeutic.","Wildtyp = garantiert sensitiv":"Wild type = sensibilitate garantată","Andere primäre oder sekundäre Resistenzmechanismen bleiben möglich.":"Alte mecanisme de rezistență primară sau secundară rămân posibile.","HER2 = sicher erworben":"HER2 = sigur dobândit","Ohne Baseline-HER2 kann die zeitliche Entstehung nicht bewiesen werden.":"Fără HER2 de baseline, momentul apariției nu poate fi dovedit.","Nur MMR/MSI wiederholen":"Repetați doar MMR/MSI","Der Status ist bereits bekannt und beantwortet die konkrete Progressionsfrage kaum.":"Statusul este deja cunoscut și răspunde foarte puțin întrebării concrete de progresie.","Kein RAS/RAF-Resistenztreiber – dafür HER2 amplifiziert":"Fără driver RAS/RAF de rezistență – dar HER2 amplificat","Das Progressionspanel bleibt KRAS/NRAS/BRAF-Wildtyp. Genau dieser 'negative' Befund war initial therapeutisch hilfreich, erklärt aber den aktuellen Progress nicht. Die HER2-Bestätigung zeigt IHC 3+ und ERBB2-Amplifikation. Damit erscheint ein alternativer Signal-/Resistenzweg und zugleich ein neuer Targetkontext. Weil Baseline-HER2 fehlt, bleibt offen, ob die Amplifikation schon vorher vorhanden oder unter Therapie selektiert war.":"Panelul de progresie rămâne KRAS/NRAS/BRAF wild type. Exact acest rezultat «negativ» a fost inițial util terapeutic, dar nu explică progresia actuală. Confirmarea HER2 arată IHC 3+ și amplificare ERBB2. Astfel apare o cale alternativă de semnalizare/rezistență și, totodată, un nou context de target. Deoarece HER2 de baseline lipsește, rămâne deschis dacă amplificarea era deja prezentă sau a fost selectată sub terapie.","Der Fall trennt drei Ebenen, die häufig vermischt werden: Selektionsmarker, Resistenzmechanismus und Target. 'Negativ' und 'positiv' sind therapeutisch kontextabhängige Begriffe.":"Cazul separă trei niveluri adesea confundate: marker de selecție, mecanism de rezistență și target. «Negativ» și «pozitiv» sunt termeni terapeutici dependenți de context.","Wildtyp richtig gelesen + HER2 integriert":"Wild type interpretat corect + HER2 integrat","KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplifiziert. Anti-EGFR war im initialen linksseitigen WT-Kontext plausibel; HER2 ist nun ein relevanter Target-/Resistenzkontext. Akquisition nicht beweisbar.":"KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplificat. Anti-EGFR a fost plauzibil în contextul inițial stâng WT; HER2 este acum un context relevant de target/rezistență. Achiziția nu poate fi dovedită.","Alle Ebenen sauber getrennt und integriert.":"Toate nivelurile sunt clar separate și integrate.","Wildtyp als 'negativ' abgehakt":"Wild type bifat doar ca «negativ»","RAS/BRAF WT wird nur als fehlender Befund erwähnt; HER2 wird zwar gefunden, aber die Selektionslogik bleibt unverstanden.":"RAS/BRAF WT este menționat doar ca rezultat absent; HER2 este găsit, dar logica de selecție rămâne neînțeleasă.","Zentrales Lernziel verfehlt.":"Obiectivul central de învățare a fost ratat.","HER2 als sicher erworbene Resistenz bezeichnet":"HER2 etichetat ca rezistență sigur dobândită","Kausalität/Akquisition wird ohne Baseline behauptet.":"Cauzalitatea/achiziția este afirmată fără baseline.","Überinterpretation der zeitlichen Evidenz.":"Supra-interpretarea dovezilor temporale.","HER2 bestätigt":"HER2 confirmat","HER2-gerichtete Therapieoptionen nach aktueller Zulassung/Leitlinie und Vorbehandlung im MTB prüfen.":"Evaluați în MTB opțiunile de terapie anti-HER2 conform aprobării/ghidului actual și tratamentelor anterioare.","Der Progressionsbefund eröffnet eine neue therapeutische Achse.":"Rezultatul de progresie deschide o nouă axă terapeutică.","HER2 nicht bestätigt":"HER2 neconfirmat","Alternative Resistenzmechanismen im Progressionsprofil/ctDNA/Gewebe prüfen.":"Evaluați mecanisme alternative de rezistență în profilul de progresie/ctDNA/țesut.","RAS/BRAF-Wildtyp allein erklärt den Progress weiterhin nicht.":"RAS/BRAF wild type singur tot nu explică progresia.","Beim mCRC kann ein negativer Mutationsbefund therapeutisch positiv sein.":"În mCRC, un rezultat mutațional negativ poate fi terapeutic pozitiv.","RAS/BRAF-Wildtyp ist Voraussetzung/Selektionsinformation für anti-EGFR, aber keine Garantie für Wirkung.":"RAS/BRAF wild type este o premisă/informație de selecție pentru anti-EGFR, dar nu o garanție a eficacității.","HER2-Amplifikation kann einen alternativen Target-/Resistenzkontext darstellen.":"Amplificarea HER2 poate reprezenta un context alternativ de target/rezistență.","Ohne Baseline darf 'erworben' nicht behauptet werden.":"Fără baseline, «dobândit» nu trebuie afirmat.","Linksseitiges mCRC mit initial RAS/BRAF-WT/pMMR/MSS: der Wildtypstatus ist eine positive Selektionsinformation für anti-EGFR-Antikörper. Beim Progress bleibt RAS/BRAF WT, aber ERBB2 ist amplifiziert und HER2 bestätigt. HER2 als alternativen Target-/Resistenzkontext berichten; mangels Baseline nicht als sicher erworben bezeichnen.":"mCRC stâng cu RAS/BRAF-WT/pMMR/MSS inițial: statusul wild type este o informație pozitivă de selecție pentru anticorpi anti-EGFR. La progresie, RAS/BRAF rămâne WT, dar ERBB2 este amplificat și HER2 confirmat. Raportați HER2 ca target/context alternativ de rezistență; fără baseline, nu îl numiți sigur dobândit.","negativ=positiv-Konzept explizit verstanden":"conceptul «negativ = pozitiv» înțeles explicit","WT nicht als Erfolgsgarantie":"WT nu este tratat ca garanție a succesului","HER2 bestätigt und integriert":"HER2 confirmat și integrat","Akquisitionssprache begrenzt":"Formularea privind achiziția este limitată adecvat","Warum sind Wildtypbefunde in der Onkologie oft therapeutisch hochinformativ?":"De ce rezultatele wild type sunt adesea foarte informative terapeutic în oncologie?","Welche weiteren anti-EGFR-Resistenzmechanismen gibt es neben RAS/BRAF?":"Ce alte mecanisme de rezistență anti-EGFR există în afară de RAS/BRAF?","Wie verändert ctDNA die Rechallenge-/Resistenzdiagnostik?":"Cum schimbă ctDNA diagnosticul de rechallenge/rezistență?","RAS/BRAF WT bleibt, HER2 wird positiv":"RAS/BRAF rămâne WT, HER2 devine pozitiv","negativ kann therapeutisch positiv sein":"negativ poate fi terapeutic pozitiv","WT-Selektion → anti-EGFR → Progress → HER2-Amplifikation":"Selecție WT → anti-EGFR → progresie → amplificare HER2","Mammakarzinom: BRCA/PIK3CA/ERBB2-Kontext → Klassische Marker vs. Panel-Zusatznutzen":"Cancer mamar: context BRCA/PIK3CA/ERBB2 → markeri clasici vs. valoarea adăugată a panelului","Mammakarzinom: BRCA/PIK3CA/ERBB2-K…":"Cancer mamar: context BRCA/PIK3CA/ERBB2…","Gynäko-Onkologie / Molekulares Tumorboard":"Oncologie ginecologică / Tumor Board molecular","56-jährige Patientin mit sechs Jahre zuvor behandeltem invasivem Mammakarzinom; jetzt neu aufgetretene Leber- und Knochenmetastasen nach Progress unter endokriner Therapie plus CDK4/6-Inhibition.":"Pacientă de 56 de ani cu cancer mamar invaziv tratat cu șase ani în urmă; acum metastaze hepatice și osoase noi după progresie sub terapie endocrină plus inhibiție CDK4/6.","Welche klassischen prädiktiven Marker müssen an der Metastase erneut geklärt werden, und welchen zusätzlichen therapeutischen Nutzen liefern PIK3CA- sowie BRCA/HRR-Analysen?":"Ce markeri predictivi clasici trebuie reevaluați în metastază și ce valoare terapeutică suplimentară oferă analizele PIK3CA și BRCA/HRR?","Therapiewechsel soll im nächsten MTB festgelegt werden.":"Schimbarea tratamentului trebuie stabilită la următorul MTB.","Primärtumor vor 6 Jahren":"Tumora primară acum 6 ani","ER 95 %, PgR 70 %, HER2 IHC 0; adjuvante Chemotherapie und anschließende endokrine Therapie.":"ER 95 %, PgR 70 %, HER2 IHC 0; chimioterapie adjuvantă urmată de terapie endocrină.","Metastasierte Situation":"Situație metastatică","Nach initialer Krankheitskontrolle unter Aromatasehemmer + CDK4/6-Inhibitor nun hepatischer Progress.":"După control inițial al bolii sub inhibitor de aromatază + inhibitor CDK4/6, acum progresie hepatică.","Familienanamnese":"Istoric familial","Mutter mit Ovarialkarzinom im Alter von 63 Jahren; bisher keine dokumentierte humangenetische Abklärung.":"Mamă cu cancer ovarian la 63 de ani; până în prezent fără consiliere/testare genetică documentată.","Ein breites Panel wird als Ersatz für die erneute Bestimmung der klassischen Tumorbiologie verstanden – oder ein Tumor-BRCA-Befund wird direkt als gesicherte Keimbahnmutation behandelt.":"Un panel larg este înțeles ca înlocuitor pentru reevaluarea biologiei tumorale clasice – sau un rezultat BRCA tumoral este tratat direct ca mutație germinală dovedită.","Metastasenbiopsie":"Biopsie metastatică","Adenokarzinom, morphologisch und immunhistochemisch vereinbar mit Mammakarzinommetastase.":"Adenocarcinom morfologic și imunohistochimic compatibil cu metastază de cancer mamar.","Rezeptorstatus Metastase":"Statusul receptorilor metastazei","ER 80 %, PgR 5 %. HER2-IHC 2+ und damit für die klassische HER2-Statusbestimmung zunächst äquivok.":"ER 80 %, PgR 5 %. HER2 IHC 2+ și astfel inițial echivoc pentru determinarea clasică a statusului HER2.","Offene molekulare Fragen":"Întrebări moleculare deschise","PIK3CA als endokrin-targetierbarer Kontext; BRCA1/2/HRR wegen PARP- und hereditärer Fragestellung.":"PIK3CA ca un context targetabil endocrin; BRCA1/2/HRR pentru întrebările PARP și ereditare.","Kernproblem":"Problema centrală","Klassische Marker und Molekularpanel beantworten unterschiedliche Ebenen derselben Therapieentscheidung.":"Markerii clasici și panelurile moleculare răspund la niveluri diferite ale aceleiași decizii terapeutice.","FFPE-Leberbiopsie, Block L3.":"Biopsie hepatică FFPE, bloc L3.","ca. 45 %, nach Makrodissektion gut geeignet.":"aprox. 45 %, bine adecvat după macrodisecție.","11 ungefärbte Schnitte; genug für gezielte IHC/ISH und fokussierte Molekulardiagnostik.":"11 secțiuni necolorate; suficiente pentru IHC/ISH țintit și diagnostic molecular focalizat.","DNA ausreichend; HER2-IHC technisch gut beurteilbar.":"ADN suficient; IHC HER2 tehnic bine evaluabilă.","Ein großes Pan-Panel verbraucht mehr Material, ersetzt aber weder die validierte HER2-IHC/ISH-Ebene noch die getrennte Keimbahnabklärung.":"Un pan-panel mare consumă mai mult material, dar nu înlocuiește nici nivelul validat HER2 IHC/ISH, nici evaluarea germinală separată.","HER2-Status der Metastase klären":"Clarificați statusul HER2 al metastazei","PIK3CA-Kontext":"Context PIK3CA","Tumor-BRCA/HRR-Kontext":"Context tumoral BRCA/HRR","HER2-Status":"Status HER2","HER2-IHC 2+; ERBB2-ISH/FISH ohne Amplifikation. Der Tumor ist damit nicht HER2-amplifiziert; die äquivoke IHC allein darf nicht als HER2-positiv überinterpretiert werden.":"HER2 IHC 2+; ERBB2 ISH/FISH fără amplificare. Tumora nu este deci HER2-amplificată; IHC echivocă singură nu trebuie supra-interpretată ca HER2-pozitivă.","PIK3CA":"PIK3CA","PIK3CA p.H1047R, pathogen/aktivierend. Im HR-positiven, HER2-negativen metastasierten Kontext therapeutisch relevant abhängig von Vorbehandlung, Therapielinie und aktueller Zulassung/Leitlinie.":"PIK3CA p.H1047R, patogenă/activatoare. Relevantă terapeutic în boala metastatică HR-pozitivă, HER2-negativă, în funcție de tratamentul anterior, linia terapeutică și aprobarea/ghidul actual.","Tumor-BRCA/HRR":"BRCA/HRR tumoral","BRCA2-Frameshift-Variante mit Loss-of-function-Konsequenz, VAF 47 %. Der Tumorbefund kann eine therapeutisch und hereditär relevante Spur sein, beweist aber für sich keine Keimbahnmutation.":"Variantă frameshift BRCA2 cu consecință loss-of-function, VAF 47 %. Rezultatul tumoral poate fi o pistă relevantă terapeutic și ereditar, dar nu dovedește singur o mutație germinală.","Humangenetische Weiterleitung":"Trimitere la consiliere genetică","Humangenetische Beratung und Keimbahnabklärung werden empfohlen. Die hereditäre Einordnung erfolgt aus einer geeigneten Normalprobe und getrennt vom Tumor-only-Befund.":"Se recomandă consiliere genetică și testare germinală. Încadrarea ereditară se face dintr-o probă normală adecvată și separat de rezultatul tumor-only.","Rezeptorbiologie":"Biologia receptorilor","ER 80 %, PgR 5 %; HER2-IHC 2+ an der Metastase.":"ER 80 %, PgR 5 %; HER2 IHC 2+ în metastază.","Metastasenbiopsie ausreichend für fokussierte IHC/ISH und Molekulardiagnostik.":"Biopsie metastatică suficientă pentru IHC/ISH focalizat și diagnostic molecular.","HR-positives metastasiertes Mammakarzinom mit HER2-IHC 2+, aber ohne ERBB2-Amplifikation. Zusätzlich liegt eine aktivierende PIK3CA-Mutation vor. Eine pathogene BRCA2-Loss-of-function-Variante wurde im Tumor gefunden; ihre Keimbahnherkunft ist aus der Tumoranalyse nicht ableitbar und muss separat humangenetisch geklärt werden. Klassische Rezeptor-/HER2-Diagnostik und molekulare Zusatzdiagnostik ergänzen sich und dürfen nicht gegeneinander ersetzt werden.":"Cancer mamar metastatic HR-pozitiv cu HER2 IHC 2+, dar fără amplificare ERBB2. În plus, este prezentă o mutație PIK3CA activatoare. În tumoră a fost găsită o variantă patogenă BRCA2 loss-of-function; originea ei germinală nu poate fi dedusă din analiza tumorală și trebuie clarificată separat prin consiliere/testare genetică. Diagnosticul clasic al receptorilor/HER2 și testarea moleculară suplimentară se completează și nu trebuie să se înlocuiască reciproc.","Teilbefund: Die molekularen Zusatzmarker sind nur im aktuellen ER/PgR/HER2-Kontext sinnvoll interpretierbar. Ein HER2-IHC-2+-Befund benötigt die validierte ISH/FISH-Klärung; ein Tumor-BRCA2-Befund ist nicht automatisch ein Keimbahnbefund.":"Rezultat parțial: markerii moleculari suplimentari pot fi interpretați corect doar în contextul actual ER/PgR/HER2. Un rezultat HER2 IHC 2+ necesită clarificare validată ISH/FISH; un rezultat BRCA2 tumoral nu este automat un rezultat germinal.","Aktuellen ER/PgR/HER2-Kontext der Metastase als Grundlage benennen":"Menționați contextul actual ER/PgR/HER2 al metastazei ca bază","HER2 IHC 2+ durch ISH/FISH klären und nicht vorschnell als HER2-positiv bezeichnen":"Clarificați HER2 IHC 2+ prin ISH/FISH și nu îl numiți prematur HER2-pozitiv","PIK3CA als zusätzlichen, therapielinienabhängigen Targetkontext integrieren":"Integrați PIK3CA ca target suplimentar dependent de linia terapeutică","Tumor-BRCA2 therapeutisch/hereditär relevant einordnen, Keimbahn aber separat klären":"Încadrați BRCA2 tumoral ca relevant terapeutic/ereditar, dar evaluați germinal separat","Paneldiagnostik nicht als Ersatz für klassische Biomarker oder Humangenetik darstellen":"Nu prezentați testarea prin panel ca înlocuitor pentru biomarkerii clasici sau consilierea genetică","Optimale Lösung: Metastasenbiologie zuerst korrekt mit ER/PgR/HER2 charakterisieren; HER2 2+ durch ISH als nicht amplifiziert klären; PIK3CA als zusätzliche therapeutische Information nutzen; pathogene Tumor-BRCA2-Variante als wichtige Spur berichten, aber Keimbahnstatus separat abklären.":"Soluția optimă: caracterizați mai întâi corect biologia metastazei prin ER/PgR/HER2; clarificați HER2 2+ prin ISH ca neamplificat; utilizați PIK3CA ca informație terapeutică suplimentară; raportați varianta patogenă BRCA2 tumorală ca indiciu important, dar evaluați statusul germinal separat.","Mammakarzinom":"Cancer mamar","HR+":"HR+","BRCA2":"BRCA2","Keimbahn":"Germinal","PARP":"PARP","Klassische Marker zuerst, Panel danach: HER2 2+, PIK3CA und der Tumor-BRCA2-Twist":"Mai întâi markerii clasici, apoi panelul: HER2 2+, PIK3CA și twist-ul BRCA2 tumoral","Molekularpathologie / Gynäko-Onkologie / MTB":"Patologie moleculară / Oncologie ginecologică / MTB","Bei metastasiertem Mammakarzinom die aktuelle Tumorbiologie der Metastase einschließlich ER/PgR/HER2 als Grundlage der Systemtherapie verstehen.":"În cancerul mamar metastatic, înțelegeți biologia actuală a metastazei, inclusiv ER/PgR/HER2, ca bază a tratamentului sistemic.","HER2-IHC 2+ nicht als HER2-positiv überinterpretieren, sondern mit validierter ISH/FISH klären.":"Nu suprainterpreta HER2 IHC 2+ ca HER2-pozitiv; clarifică prin ISH/FISH validat.","PIK3CA als zusätzliche molekulare Therapieinformation im HR-positiven/HER2-negativen Kontext einordnen.":"Încadrează PIK3CA ca informație moleculară terapeutică suplimentară în context HR-pozitiv/HER2-negativ.","Eine pathogene BRCA2-Variante aus Tumor-only-NGS von einer gesicherten Keimbahnmutation trennen.":"Distinge o variantă BRCA2 patogenă detectată prin NGS tumor-only de o mutație germinală confirmată.","Verstehen, dass Multigen-NGS klassische Biomarker ergänzt, aber nicht ersetzt.":"Înțelege că NGS multigenică completează biomarkerii clasici, dar nu îi înlocuiește.","Die Lebermetastase ist ER-positiv und HER2-IHC 2+. Parallel meldet das Panel eine aktivierende PIK3CA-Mutation und eine pathogene BRCA2-Frameshift-Variante. Im Tumorboard fallen sofort drei vermeintlich einfache Schlussfolgerungen: 'HER2-positiv', 'PIK3CA-targetierbar' und 'BRCA erblich'. Genau dieser Fall zeigt, warum alle drei Aussagen erst im richtigen diagnostischen Kontext belastbar werden.":"Metastaza hepatică este ER-pozitivă și HER2 IHC 2+. În paralel, panelul raportează o mutație activatoare PIK3CA și o variantă frameshift patogenă BRCA2. În Tumor Board apar imediat trei concluzii aparent simple: «HER2-pozitiv», «PIK3CA targetabil» și «BRCA ereditar». Acest caz arată de ce toate cele trei afirmații devin solide numai în contextul diagnostic corect.","56-jährige Patientin mit HR-positivem Mammakarzinom und hepatischem Progress nach endokriner Therapie plus CDK4/6-Inhibition. Die aktuelle Metastasenbiopsie ist ER 80 %, PgR 5 % und HER2-IHC 2+. Gesucht wird eine integrierte Therapiebiologie aus klassischer HER2-Diagnostik, PIK3CA und BRCA/HRR, ohne die Grenzen von Tumor-only-NGS zu verwischen.":"Pacientă de 56 de ani cu cancer mamar HR-pozitiv și progresie hepatică după terapie endocrină plus inhibitor CDK4/6. Biopsia metastatică actuală este ER 80%, PgR 5% și HER2 IHC 2+. Trebuie construită o biologie terapeutică integrată din diagnosticul HER2 clasic, PIK3CA și BRCA/HRR, fără a estompa limitele NGS tumor-only.","Metastasenbiologie":"Biologia metastazei","ER 80 %, PgR 5 %, HER2-IHC 2+.":"ER 80%, PgR 5%, HER2 IHC 2+.","Die aktuelle Metastase kann sich biologisch vom Primärtumor unterscheiden; klassische Marker bleiben Grundlage.":"Metastaza actuală poate diferi biologic de tumora primară; markerii clasici rămân fundamentali.","Molekulare Zusatzebene":"Nivel molecular suplimentar","PIK3CA und BRCA/HRR sollen gezielt ergänzt werden.":"PIK3CA și BRCA/HRR trebuie completate țintit.","Zusatznutzen entsteht erst im bekannten HR/HER2-Kontext.":"Valoarea adăugată apare numai în contextul HR/HER2 cunoscut.","Familienrelevanz":"Relevanță familială","Mutter mit Ovarialkarzinom; keine bisherige Humangenetik.":"Mamă cu cancer ovarian; fără evaluare genetică umană anterioară.","Tumor-only kann einen Verdacht erzeugen, aber Keimbahn nicht beweisen.":"Analiza tumor-only poate ridica suspiciunea, dar nu poate demonstra originea germinală.","Mammakarzinommetastase, ER 80 %, PgR 5 %, HER2-IHC 2+.":"Metastază de cancer mamar, ER 80%, PgR 5%, HER2 IHC 2+.","Vor sechs Jahren ER/PgR stark positiv, HER2-IHC 0.":"În urmă cu șase ani ER/PgR intens pozitiv, HER2 IHC 0.","Leberbiopsie mit ca. 45 % Tumor; fokussierte IHC/ISH und NGS sind möglich.":"Biopsie hepatică cu aproximativ 45% tumoră; IHC/ISH focalizat și NGS sunt fezabile.","Elf Schnitte erlauben eine fokussierte Diagnostik, aber unnötige Breitdiagnostik kostet Material.":"Unsprezece secțiuni permit un diagnostic focalizat, dar testarea largă inutilă consumă material.","HER2-IHC 2+ benötigt eine validierte Amplifikationsabklärung; NGS ersetzt diesen diagnostischen Algorithmus nicht automatisch.":"HER2 IHC 2+ necesită verificarea validată a amplificării; NGS nu înlocuiește automat acest algoritm diagnostic.","Eine Normalprobe für die Keimbahnabklärung ist in der Tumorpathologie nicht vorhanden.":"În patologia tumorală nu este disponibilă o probă normală pentru evaluarea germinală.","Was ist die wichtigste Grundlage, bevor PIK3CA/BRCA therapeutisch interpretiert werden?":"Care este baza cea mai importantă înainte de interpretarea terapeutică a PIK3CA/BRCA?","Die aktuelle ER/PgR/HER2-Biologie der Metastase muss belastbar feststehen; das Panel ergänzt diese Ebene.":"Biologia ER/PgR/HER2 actuală a metastazei trebuie stabilită în mod fiabil; panelul completează acest nivel.","Ein ausreichend breites NGS-Panel ersetzt ER/PgR/HER2 vollständig.":"Un panel NGS suficient de larg înlocuiește complet ER/PgR/HER2.","Der Rezeptorstatus des Primärtumors vor sechs Jahren reicht aus.":"Statusul receptorilor tumorii primare de acum șase ani este suficient.","BRCA2 entscheidet unabhängig von HR/HER2 über die gesamte Therapie.":"BRCA2 determină întreaga terapie independent de HR/HER2.","Beim metastasierten Mammakarzinom bleibt die aktuelle Tumorbiologie eine zentrale prädiktive Grundlage.":"În cancerul mamar metastatic, biologia tumorală actuală rămâne o bază predictivă centrală.","Die Metastase ist HER2-IHC 2+. Was bedeutet das?":"Metastaza este HER2 IHC 2+. Ce înseamnă?","Äquivoker Befund: ERBB2-Amplifikation mit validierter ISH/FISH klären; IHC 2+ allein ist nicht gleich HER2-amplifiziert.":"Rezultat echivoc: clarifică amplificarea ERBB2 prin ISH/FISH validat; IHC 2+ singur nu înseamnă amplificare HER2.","HER2-positiv, weitere Klärung unnötig.":"HER2-pozitiv, nu este necesară nicio clarificare suplimentară.","Sicher HER2-negativ, ISH ist nie erforderlich.":"Cu siguranță HER2-negativ; ISH nu este niciodată necesar.","Nur die BRCA-Analyse entscheidet, HER2 ist irrelevant.":"Contează doar analiza BRCA; HER2 este irelevant.","IHC 2+ benötigt die etablierte Amplifikationsabklärung.":"IHC 2+ necesită evaluarea standardizată a amplificării.","Tumor-NGS zeigt eine pathogene BRCA2-Frameshift-Variante mit VAF 47 %. Was darf daraus geschlossen werden?":"NGS tumoral arată o variantă frameshift patogenă BRCA2 cu VAF 47%. Ce se poate concluziona?","Der Befund ist therapeutisch/hereditär relevant, aber Tumor-only beweist keine Keimbahnmutation; Humangenetik/Normalprobe separat klären.":"Rezultatul este relevant terapeutic/ereditar, dar testarea tumor-only nu demonstrează o mutație germinală; clarifică separat prin consiliere genetică/probă normală.","VAF nahe 50 % beweist eine Keimbahnmutation.":"O VAF apropiată de 50% demonstrează o mutație germinală.","Da die Probe Tumorgewebe ist, ist die Variante sicher rein somatisch.":"Deoarece proba este țesut tumoral, varianta este sigur exclusiv somatică.","Eine Frameshift-Variante ist automatisch eine VUS.":"O variantă frameshift este automat o VUS.","Tumor-VAF und selbst LOH trennen somatisch und Keimbahn nicht zuverlässig.":"VAF tumorală și chiar LOH nu diferențiază în mod fiabil originea somatică de cea germinală.","Wie ist der Zusatznutzen des Panels hier am besten beschrieben?":"Cum este descrisă cel mai bine valoarea adăugată a panelului aici?","PIK3CA/BRCA liefern zusätzliche therapie- und familienrelevante Information, ersetzen aber weder HER2-IHC/ISH noch die Keimbahnabklärung.":"PIK3CA/BRCA oferă informații suplimentare relevante terapeutic și familial, dar nu înlocuiesc nici HER2 IHC/ISH, nici evaluarea germinală.","Das Panel macht klassische Biomarker und Humangenetik überflüssig.":"Panelul face inutili biomarkerii clasici și consilierea genetică.","Molekulardiagnostik hat bei HR-positivem Mammakarzinom keinen Zusatznutzen.":"Diagnosticul molecular nu aduce valoare suplimentară în cancerul mamar HR-pozitiv.","Nur BRCA2 ist relevant; PIK3CA und HER2 können ignoriert werden.":"Doar BRCA2 este relevant; PIK3CA și HER2 pot fi ignorate.","Die Stärke liegt in der Integration komplementärer diagnostischer Ebenen.":"Punctul forte constă în integrarea nivelurilor diagnostice complementare.","Formulieren Sie eine integrierte MTB-Aussage, die den aktuellen HR/HER2-Status der Metastase, PIK3CA und die Tumor-BRCA2-Variante zusammenführt und klar trennt, welche Information unmittelbar tumorbezogen ist und welche eine separate Keimbahnabklärung erfordert.":"Formulați o concluzie MTB integrată care să combine statusul HR/HER2 actual al metastazei, PIK3CA și varianta BRCA2 tumorală și să separe clar informația direct tumorală de cea care necesită evaluare germinală separată.","Aktuelle Metastasenbiologie mit ER/PgR/HER2 als Grundlage verwenden.":"Folosește biologia actuală a metastazei cu ER/PgR/HER2 ca bază.","HER2-IHC 2+ durch ISH/FISH klären: keine ERBB2-Amplifikation.":"Clarifică HER2 IHC 2+ prin ISH/FISH: fără amplificare ERBB2.","PIK3CA p.H1047R als zusätzlichen therapielinienabhängigen Targetkontext berichten.":"Raportează PIK3CA p.H1047R ca un context target suplimentar dependent de linia terapeutică.","Tumor-BRCA2-Loss-of-function als relevante molekulare Spur einordnen.":"Încadrează loss-of-function BRCA2 tumoral ca indiciu molecular relevant.","Tumor-BRCA2 nicht als gesicherte Keimbahnmutation bezeichnen; humangenetische Beratung/Normalprobe empfehlen.":"Nu eticheta BRCA2 tumoral ca mutație germinală confirmată; recomandă consiliere genetică/probă normală.","Therapieoptionen an aktuelle Zulassung, Vorbehandlung und Gesamtbiologie binden.":"Leagă opțiunile terapeutice de aprobarea actuală, tratamentul anterior și biologia globală.","Validiertes Multigenpanel zur kombinierten Erfassung von PIK3CA und BRCA/HRR, sofern HER2 weiterhin separat nach validiertem IHC/ISH-Algorithmus beurteilt wird.":"Panel multigenic validat pentru detectarea combinată PIK3CA și BRCA/HRR, cu condiția ca HER2 să fie evaluat separat în continuare prin algoritm IHC/ISH validat.","Gezielte PIK3CA-Analyse plus Tumor-BRCA/HRR-Panel, um Material und TAT zu schonen.":"Analiză PIK3CA țintită plus panel tumoral BRCA/HRR pentru a economisi material și TAT.","HER2 2+ = HER2-positiv":"HER2 2+ = HER2-pozitiv","IHC 2+ ist äquivok und benötigt die Amplifikationsabklärung.":"IHC 2+ este echivoc și necesită evaluarea amplificării.","Tumor-BRCA2 = Keimbahn-BRCA2":"BRCA2 tumoral = BRCA2 germinal","Tumor-only-NGS kann die Herkunft nicht sicher bestimmen.":"NGS tumor-only nu poate determina sigur originea.","Pan-Panel ersetzt alles":"Pan-panelul înlocuiește tot","Klassische Protein-/Amplifikationsmarker und Humangenetik beantworten andere diagnostische Ebenen.":"Markerii clasici de proteină/amplificare și genetica germinală răspund unor niveluri diagnostice diferite.","Primärtumorstatus reicht":"Statusul tumorii primare este suficient","Bei metastasierter Erkrankung kann eine Rebiopsie die aktuelle Tumorbiologie neu bewerten.":"În boala metastatică, rebiopsia poate reevalua biologia tumorală actuală.","Zwei 'positive' Befunde – aber keiner bedeutet das, was der erste Blick suggeriert":"Două rezultate «pozitive» – dar niciunul nu înseamnă ce sugerează prima impresie","HER2-IHC 2+ wird durch ISH als nicht amplifiziert geklärt. Gleichzeitig zeigt Tumor-NGS BRCA2 Loss-of-function bei VAF 47 %. Das klingt nach HER2-positiv plus erblichem BRCA-Syndrom – tatsächlich ist ersteres äquivok/nicht amplifiziert und letzteres zunächst ein Tumorbefund mit notwendiger separater Keimbahnklärung. Die klar tumorbezogene Zusatzinformation ist eine aktivierende PIK3CA-p.H1047R-Mutation.":"HER2 IHC 2+ este clarificat prin ISH ca neamplificat. În același timp, NGS tumoral arată loss-of-function BRCA2 la VAF 47%. Pare HER2-pozitiv plus sindrom BRCA ereditar – în realitate, primul este echivoc/neamplificat, iar al doilea este inițial un rezultat tumoral care necesită clarificare germinală separată. Informația suplimentară clar tumorală este mutația activatoare PIK3CA p.H1047R.","Der Fall zwingt zur Trennung von Proteinexpression, Genamplifikation, somatischer Tumorgenetik und Keimbahnstatus – vier Ebenen, die therapeutisch miteinander interagieren, aber diagnostisch nicht austauschbar sind.":"Cazul obligă la separarea expresiei proteice, amplificării genice, geneticii somatice tumorale și statusului germinal – patru niveluri care interacționează terapeutic, dar nu sunt interschimbabile diagnostic.","Klassik und Molekularprofil integriert":"Markeri clasici și profil molecular integrate","ER 80 %, PgR 5 %, HER2-IHC 2+/ISH nicht amplifiziert; PIK3CA p.H1047R; pathogene BRCA2-Frameshift-Variante im Tumor. PIK3CA im aktuellen HR+/HER2-negativen Therapiekontext berücksichtigen; BRCA2 als relevante Tumorspur mit separater Keimbahnabklärung berichten.":"ER 80%, PgR 5%, HER2 IHC 2+/ISH neamplificat; PIK3CA p.H1047R; variantă frameshift patogenă BRCA2 în tumoră. Ia în considerare PIK3CA în contextul terapeutic actual HR+/HER2-negativ; raportează BRCA2 ca rezultat tumoral relevant cu evaluare germinală separată.","Alle diagnostischen Ebenen korrekt getrennt und integriert.":"Toate nivelurile diagnostice sunt separate și integrate corect.","Panel gut, klassische Ebene offen":"Panel bun, nivelul clasic rămâne neclarificat","PIK3CA und BRCA2 werden gefunden, HER2-IHC 2+ aber nicht durch ISH geklärt.":"PIK3CA și BRCA2 sunt detectate, dar HER2 IHC 2+ nu este clarificat prin ISH.","Therapiebiologie bleibt unvollständig.":"Biologia terapeutică rămâne incompletă.","HER2 und Keimbahn überinterpretiert":"HER2 și statusul germinal suprainterpretate","HER2-IHC 2+ wird als HER2-positiv und Tumor-BRCA2 als sicher keimbahnpathogen bezeichnet.":"HER2 IHC 2+ este etichetat HER2-pozitiv, iar BRCA2 tumoral ca sigur patogen germinal.","Zwei zentrale diagnostische Grenzüberschreitungen.":"Două încălcări majore ale limitelor diagnostice.","Tumor-BRCA2 pathologisch":"BRCA2 tumoral patologic","Humangenetische Beratung und Keimbahntestung aus geeigneter Normalprobe veranlassen.":"Organizează consiliere genetică și testare germinală dintr-o probă normală adecvată.","Therapie- und Familienrelevanz werden getrennt, aber koordiniert weiterverfolgt.":"Relevanța terapeutică și familială sunt urmărite separat, dar coordonat.","HER2-ISH nicht amplifiziert":"HER2 ISH neamplificat","Therapieplanung im HR+/HER2-negativen Kontext fortsetzen und PIK3CA/weitere Linienmarker berücksichtigen.":"Continuă planificarea terapeutică în context HR+/HER2-negativ și ia în considerare PIK3CA/alți markeri specifici liniei.","HER2-IHC 2+ wird nicht als Amplifikationspositivität fehlgedeutet.":"HER2 IHC 2+ nu este interpretat greșit ca pozitivitate de amplificare.","Beim metastasierten Mammakarzinom bleibt die aktuelle ER/PgR/HER2-Biologie zentral.":"În cancerul mamar metastatic, biologia actuală ER/PgR/HER2 rămâne centrală.","HER2-IHC 2+ ist ein Klärungsbefund, kein automatisches positives Endergebnis.":"HER2 IHC 2+ este un rezultat care necesită clarificare, nu un rezultat final automat pozitiv.","PIK3CA erweitert die therapeutische Information im passenden HR+/HER2-negativen Kontext.":"PIK3CA extinde informația terapeutică în contextul adecvat HR+/HER2-negativ.","Tumor-only BRCA kann klinisch hochrelevant sein, beweist aber keinen Keimbahnstatus.":"BRCA tumor-only poate fi foarte relevant clinic, dar nu demonstrează statusul germinal.","Multigen-NGS ergänzt klassische Pathologiemarker; es ersetzt sie nicht.":"NGS multigenică completează markerii clasici de patologie; nu îi înlocuiește.","Aktuelle Metastasenbiologie zuerst: HR-positiv, HER2-IHC 2+, aber ISH nicht amplifiziert. PIK3CA p.H1047R ist als zusätzlicher therapeutischer Marker relevant. Die pathogene BRCA2-Frameshift-Variante stammt aus Tumor-only-NGS; sie darf nicht als Keimbahnmutation bezeichnet werden und löst eine separate humangenetische Abklärung aus.":"Mai întâi biologia metastatică actuală: HR-pozitiv, HER2 IHC 2+, dar ISH neamplificat. PIK3CA p.H1047R este relevant ca marker terapeutic suplimentar. Varianta frameshift patogenă BRCA2 provine din NGS tumor-only; nu trebuie denumită mutație germinală și declanșează o evaluare genetică separată.","HER2 2+ korrekt geklärt":"HER2 2+ clarificat corect","PIK3CA im passenden Kontext integriert":"PIK3CA integrat în contextul adecvat","Tumor vs. Keimbahn getrennt":"Tumoral vs germinal separat","Panel nicht als Ersatz klassischer Marker":"Panelul nu este tratat ca înlocuitor al markerilor clasici","Warum sollte die Metastase erneut auf ER/PgR/HER2 untersucht werden?":"De ce ar trebui retestată metastaza pentru ER/PgR/HER2?","Welche Aussage kann eine Tumor-VAF von etwa 50 % zur Keimbahnherkunft leisten – und welche nicht?":"Ce poate spune o VAF tumorală de aproximativ 50% despre originea germinală – și ce nu poate spune?","Wann ist ein breites Panel gegenüber fokussierter Diagnostik wirklich sinnvoll?":"Când este un panel larg cu adevărat util față de diagnosticul focalizat?","HER2 2+ nicht amplifiziert + Tumor-BRCA2 ist nicht automatisch Keimbahn":"HER2 2+ neamplificat + BRCA2 tumoral nu înseamnă automat germinal","Klassische Marker und Molekularprofil sind komplementär":"Markerii clasici și profilul molecular sunt complementare","Metastasenbiologie → HER2-Klärung → PIK3CA/BRCA → Keimbahn separat":"Biologia metastazei → clarificare HER2 → PIK3CA/BRCA → germinal separat","Metastasiertes Prostatakarzinom: HRR-Gene/MMR → PARP/IO/Studie und Keimbahnfrage":"Cancer de prostată metastatic: gene HRR/MMR → PARP/IO/studiu și problema germinală","Metastasiertes Prostatakarzinom: H…":"Cancer de prostată metastatic: H…","Uro-Onkologie / Molekulares Tumorboard":"Uro-oncologie / Tumor Board molecular","69-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom und radiologischem Progress nach Androgendeprivation plus neuem hormonellen Wirkstoff.":"Pacient de 69 de ani cu cancer de prostată metastatic rezistent la castrare și progresie radiologică după deprivare androgenică plus un nou agent hormonal.","Gibt es einen HRR-/BRCA-Biomarker für eine PARP-Strategie? Besteht ein MMR/MSI-basierter Immuntherapiekontext? Muss eine Keimbahnabklärung folgen?":"Există un biomarker HRR/BRCA pentru o strategie PARP? Există un context de imunoterapie bazat pe MMR/MSI? Este necesară evaluarea germinală?","Therapieentscheidung in der kommenden Woche.":"Decizie terapeutică săptămâna viitoare.","Verlauf":"Evoluție","Initial lokal fortgeschrittenes Adenokarzinom; später ossäre und nodale Metastasierung, jetzt mCRPC.":"Inițial adenocarcinom local avansat; ulterior metastaze osoase și ganglionare, acum mCRPC.","ADT fortgeführt; Progress unter neuem hormonellem Wirkstoff.":"ADT continuată; progresie sub un nou agent hormonal.","Auf dem ursprünglichen Anforderungsschein 'unauffällig'. Im Gespräch berichtet der Patient später von einem Bruder mit Pankreaskarzinom und einem Vater mit Prostatakarzinom.":"Pe formularul inițial de solicitare apare «fără particularități». Ulterior, în discuție, pacientul menționează un frate cu cancer pancreatic și un tată cu cancer de prostată.","HRD-Score aus dem Ovarialkarzinom wird als universeller PARP-Test verwendet oder Tumor-BRCA und Keimbahnstatus werden gleichgesetzt.":"Un scor HRD din cancerul ovarian este folosit ca test PARP universal sau BRCA tumoral este echivalat cu statusul germinal.","Stanzbiopsie einer Lebermetastase mit hochgradigem Prostataadenokarzinom.":"Biopsie cu ac dintr-o metastază hepatică cu adenocarcinom de prostată de grad înalt.","NKX3.1/PSA-Kontext mit Prostataursprung vereinbar.":"Context NKX3.1/PSA compatibil cu origine prostatică.","Klinische Frage":"Întrebare clinică","Therapiebiomarker im mCRPC, nicht erneute Primärdiagnostik.":"Biomarkeri terapeutici în mCRPC, nu repetarea diagnosticului primar.","BRCA/HRR, MMR/MSI und hereditäre Einordnung.":"BRCA/HRR, MMR/MSI și încadrare ereditară.","ca. 55 %, ausreichend für NGS und MMR-IHC.":"aprox. 55%, suficient pentru NGS și IHC MMR.","DNA":"ADN","gute Qualität.":"calitate bună.","12 Schnitte.":"12 secțiuni.","Methodenfalle":"Capcană metodologică","Ein unspezifischer HRD-Genomic-Scar-Score ist hier nicht der primäre etablierte Selektionsweg; gen-spezifische HRR/BRCA-Diagnostik und MMR/MSI beantworten die konkrete Frage direkter.":"Un scor genomic-scar HRD nespecific nu reprezintă aici calea primară consacrată de selecție; diagnosticul HRR/BRCA specific genelor și MMR/MSI răspund mai direct întrebării concrete.","Prostata-HRR/BRCA-Status":"Status HRR/BRCA prostatic","MMR/MSI-Kontext":"Context MMR/MSI","HRR/BRCA":"HRR/BRCA","Pathogene BRCA2-Frameshift-Variante im Tumor, VAF 58 %, mit zusätzlichem Verlust des Wildtypallels vereinbar. Im mCRPC ist BRCA1/2 unabhängig von somatischer oder Keimbahnherkunft ein relevanter PARP-Biomarkerkontext; die konkrete Therapie richtet sich nach Vorbehandlung und aktueller Zulassung/Leitlinie.":"Variantă frameshift patogenă BRCA2 în tumoră, VAF 58%, compatibilă cu pierderea suplimentară a alelei wild type. În mCRPC, BRCA1/2, indiferent de originea somatică sau germinală, oferă un context relevant de biomarker PARP; tratamentul concret depinde de terapia anterioară și de aprobările/ghidurile actuale.","Erhaltene Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expresie păstrată MLH1, PMS2, MSH2 și MSH6: pMMR.","MSS / kein MSI-H. Damit ergibt sich aus MMR/MSI in diesem Fall kein spezifischer IO-Biomarkerkontext.":"MSS / fără MSI-H. Prin urmare, MMR/MSI nu oferă în acest caz un context specific de biomarker IO.","HRD-Score":"Scor HRD","Ein Genomic-Scar/HRD-Score liefert im Prostatakarzinom keine gleichwertige, etablierte Ersatzinformation für die gen-spezifische BRCA/HRR-Diagnostik. Er darf den BRCA2-Befund nicht überstimmen oder eine negative HRR-Analyse ersetzen.":"Un scor genomic-scar/HRD în cancerul de prostată nu oferă informație substitutivă echivalentă și consacrată pentru diagnosticul BRCA/HRR specific genelor. Nu trebuie să suprascrie rezultatul BRCA2 și nici să înlocuiască o analiză HRR negativă.","Keimbahnabklärung":"Evaluare germinală","Humangenetische Beratung/Keimbahntestung wird aufgrund der pathogenen BRCA2-Variante und der Familienanamnese empfohlen. Tumor-only VAF und LOH beweisen die Keimbahnherkunft nicht.":"Consilierea genetică/testarea germinală este recomandată din cauza variantei BRCA2 patogene și a antecedentelor familiale. VAF tumor-only și LOH nu demonstrează originea germinală.","Klinischer Status":"Status clinic","mCRPC mit Progress nach neuem hormonellen Wirkstoff.":"mCRPC cu progresie după un nou agent hormonal.","Metastasenbiopsie mit ausreichendem Tumoranteil für HRR- und MMR-Diagnostik.":"Biopsie metastatică cu conținut tumoral suficient pentru testare HRR și MMR.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und Hinweis auf biallelische Inaktivierung; pMMR/MSS. Der BRCA2-Befund eröffnet einen PARP-relevanten Therapiekontext gemäß aktueller Indikation/Vorbehandlung. Die Tumoranalyse unterscheidet somatisch und Keimbahn nicht sicher; wegen BRCA2 und Familienanamnese ist eine separate humangenetische Keimbahnabklärung angezeigt. Ein HRD-Score ist kein notwendiger Ersatz für diese gen-spezifische Prostata-Diagnostik.":"mCRPC cu alterare patogenă loss-of-function BRCA2 și indicii compatibile cu inactivare bialelică; pMMR/MSS. Rezultatul BRCA2 deschide un context terapeutic relevant pentru PARP conform indicației actuale/tratamentului anterior. Analiza tumorală nu diferențiază sigur originea somatică de cea germinală; din cauza BRCA2 și a antecedentelor familiale, este indicată o evaluare germinală separată prin genetică. Un scor HRD nu este un substitut necesar pentru această abordare prostatică specifică genelor.","Teilbefund: HRR/BRCA, MMR/MSI und Keimbahnfrage müssen getrennt beantwortet werden. Ein tumor-only BRCA2-Befund kann therapeutisch relevant sein, sagt aber nicht automatisch, ob die Variante vererbt ist.":"Rezultat parțial: HRR/BRCA, MMR/MSI și problema germinală trebuie răspunse separat. Un rezultat BRCA2 tumor-only poate fi terapeutic relevant, dar nu indică automat dacă varianta este moștenită.","BRCA2 im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen":"Încadrează BRCA2 în mCRPC ca context de biomarker PARP specific genei","pMMR/MSS als fehlenden MMR/MSI-basierten IO-Selektionsbefund kommunizieren":"Comunică pMMR/MSS ca absență a unui rezultat de selecție IO bazat pe MMR/MSI","Tumor-BRCA2 nicht mit Keimbahn gleichsetzen; Humangenetik empfehlen":"Nu echivala BRCA2 tumoral cu germinal; recomandă consiliere genetică","HRD-Score nicht als universellen oder zwingenden Prostata-PARP-Selektionsmarker darstellen":"Nu prezenta scorul HRD ca marker universal sau obligatoriu de selecție PARP în prostată","Therapieempfehlung an aktuelle Zulassung, Vorbehandlung und klinischen Kontext binden":"Leagă recomandarea terapeutică de aprobarea actuală, tratamentul anterior și contextul clinic","Optimale Lösung: BRCA2 im Tumor als therapeutisch relevanten mCRPC-Biomarker erkennen, pMMR/MSS separat für den IO-Kontext dokumentieren, HRD-Score nicht aus dem Ovarial-Workflow übertragen und die Keimbahnfrage wegen möglicher Familienrelevanz eigenständig humangenetisch klären.":"Soluție optimă: recunoaște BRCA2 tumoral ca biomarker mCRPC relevant terapeutic, documentează pMMR/MSS separat pentru contextul IO, nu transfera scorul HRD din fluxul ovarian și clarifică independent problema germinală prin genetică din cauza potențialei relevanțe familiale.","Prostatakarzinom":"Cancer de prostată","mCRPC":"mCRPC","HRR":"HRR","MMR":"MMR","BRCA2 im mCRPC: therapeutisch relevant – aber ist es auch Keimbahn?":"BRCA2 în mCRPC: relevant terapeutic – dar este și germinal?","Molekularpathologie / Uro-Onkologie / MTB":"Patologie moleculară / Uro-oncologie / MTB","BRCA1/2- und HRR-Alterationen im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen.":"Încadrează alterările BRCA1/2 și HRR în mCRPC ca un context de biomarker PARP specific genelor.","Somatische und Keimbahn-BRCA-Alterationen therapeutisch und hereditär getrennt betrachten.":"Consideră separat alterările BRCA somatice și germinale din perspectiva terapeutică și ereditară.","MMR/MSI als eigenständigen IO-Biomarkerblock prüfen.":"Evaluează MMR/MSI ca bloc independent de biomarkeri IO.","Einen ovarialkarzinomtypischen HRD-Genomic-Scar-Score nicht als universellen Pflichtmarker auf das Prostatakarzinom übertragen.":"Nu transfera un scor HRD genomic-scar de tip ovarian la cancerul de prostată ca marker universal obligatoriu.","Familienanamnese und humangenetische Weiterleitung in die MTB-Empfehlung integrieren.":"Integrează istoricul familial și trimiterea la genetică în recomandarea MTB.","Das Tumorpanel meldet eine pathogene BRCA2-Frameshift-Variante mit VAF 58 % und Hinweis auf Verlust des zweiten Allels. Im MTB heißt es sofort: 'Dann ist das erblich – und wir brauchen noch einen HRD-Score, bevor PARP möglich ist.' Der Fall ist ideal, um zwei häufige Ebenenfehler gleichzeitig zu korrigieren.":"Panelul tumoral raportează o variantă frameshift patogenă BRCA2 cu VAF 58% și indicii de pierdere a celei de-a doua alele. În MTB se spune imediat: «Atunci este ereditar – și mai avem nevoie de un scor HRD înainte de PARP.» Cazul este ideal pentru corectarea simultană a două erori frecvente de nivel.","69-jähriger Patient mit mCRPC und Progress nach neuem hormonellem Wirkstoff. Eine Lebermetastasenbiopsie steht für HRR/BRCA- und MMR/MSI-Diagnostik zur Verfügung. Gesucht wird eine Therapieempfehlung, die den tumorbezogenen BRCA2-Befund nutzt, die Keimbahnfrage separat löst und keine Ovarial-HRD-Logik auf die Prostata überträgt.":"Pacient de 69 de ani cu mCRPC și progresie după un nou agent hormonal. Este disponibilă o biopsie de metastază hepatică pentru testare HRR/BRCA și MMR/MSI. Se urmărește o recomandare terapeutică ce utilizează rezultatul BRCA2 tumoral, rezolvă separat problema germinală și nu transferă logica HRD ovariană la cancerul de prostată.","Therapiesituation":"Situație terapeutică","mCRPC nach Progress unter neuem hormonellem Wirkstoff.":"mCRPC după progresie sub un nou agent hormonal.","Der konkrete Therapiekontext macht BRCA1/2 besonders relevant.":"Contextul terapeutic concret face BRCA1/2 deosebit de relevant.","Hereditäre Ebene":"Nivel ereditar","Bruder mit Pankreas- und Vater mit Prostatakarzinom werden erst im Gespräch bekannt.":"Un frate cu cancer pancreatic și un tată cu cancer de prostată sunt menționați abia în timpul discuției.","Familienanamnese verstärkt die Keimbahnindikation, ersetzt aber keine Testung.":"Istoricul familial întărește indicația pentru testarea germinală, dar nu înlocuiește testarea.","IO-Ebene":"Nivel IO","MMR/MSI ist zu Beginn unbekannt.":"MMR/MSI este necunoscut la început.","DNA-Reparaturdefekt allgemein ist nicht gleich dMMR/MSI-H.":"Un defect de reparare ADN în general nu este echivalent cu dMMR/MSI-H.","Lebermetastase, ca. 55 % Tumor; DNA und IHC gut auswertbar.":"Metastază hepatică, aprox. 55% tumoră; ADN și IHC evaluabile bine.","mCRPC mit Progress nach neuem hormonellem Wirkstoff.":"mCRPC cu progresie după un nou agent hormonal.","Im Verlauf Pankreas- und Prostatakarzinom bei nahen Angehörigen berichtet.":"Pe parcurs sunt raportate cancer pancreatic și de prostată la rude apropiate.","Gen-spezifische HRR/BRCA-Diagnostik hat für die konkrete Frage höhere Priorität als ein unspezifischer HRD-Genomic-Scar-Score.":"Testarea HRR/BRCA specifică genelor are prioritate mai mare pentru această întrebare decât un scor HRD genomic-scar nespecific.","Tumorgewebe enthält keine saubere Normalreferenz für die Keimbahnfrage.":"Țesutul tumoral nu oferă o referință normală curată pentru problema germinală.","MMR/MSI benötigt eine eigene funktionelle/biomarkerbezogene Beurteilung.":"MMR/MSI necesită propria evaluare funcțională/de biomarker.","Was ist der zentrale PARP-Biomarkerbefund in diesem Fall?":"Care este rezultatul central de biomarker PARP în acest caz?","Die pathogene BRCA2-Alteration im mCRPC ist der entscheidende gen-spezifische Biomarkerkontext; die konkrete Nutzung hängt von Vorbehandlung und aktueller Indikation ab.":"Alterarea BRCA2 patogenă în mCRPC este contextul de biomarker specific genei decisiv; utilizarea concretă depinde de terapia anterioară și indicația actuală.","Nur ein positiver HRD-Score erlaubt eine PARP-Strategie.":"Doar un scor HRD pozitiv permite o strategie PARP.","pMMR ist der entscheidende PARP-Biomarker.":"pMMR este biomarkerul PARP decisiv.","Eine VAF über 50 % ist allein der therapeutische Biomarker.":"O VAF peste 50% este singură biomarkerul terapeutic.","Bei mCRPC ist die gen-spezifische BRCA1/2-Alteration zentral; ein Ovarial-HRD-Score ist kein universeller Ersatz.":"În mCRPC, alterarea BRCA1/2 specifică genei este centrală; un scor HRD ovarian nu este un substitut universal.","Tumor-BRCA2, VAF 58 %, mit LOH: Ist damit die Keimbahnherkunft bewiesen?":"BRCA2 tumoral, VAF 58%, cu LOH: demonstrează aceasta originea germinală?","Nein. Der Tumorbefund kann therapeutisch relevant sein, aber die Keimbahnherkunft muss aus einer geeigneten Normalprobe separat geklärt werden.":"Nu. Rezultatul tumoral poate fi relevant terapeutic, dar originea germinală trebuie clarificată separat folosind o probă normală adecvată.","Ja, VAF >50 % beweist Keimbahn.":"Da, VAF >50% demonstrează originea germinală.","Ja, LOH beweist immer eine erbliche Variante.":"Da, LOH demonstrează întotdeauna o variantă ereditară.","Nein, Tumorvarianten können grundsätzlich nie Keimbahn sein.":"Nu, variantele tumorale nu pot fi niciodată germinale.","Tumor-only-NGS trennt somatische und Keimbahnherkunft nicht sicher.":"NGS tumor-only nu poate diferenția sigur originea somatică de cea germinală.","Reicht eine HRR/BRCA-Alteration als Begründung für eine MMR/MSI-basierte Immuntherapie?":"Este suficientă o alterare HRR/BRCA pentru a justifica imunoterapia bazată pe MMR/MSI?","Nein. MMR/MSI ist ein separater Biomarkerblock; hier zeigt pMMR/MSS keinen spezifischen MSI-basierten IO-Kontext.":"Nu. MMR/MSI este un bloc separat de biomarkeri; aici pMMR/MSS nu oferă un context specific IO bazat pe MSI.","Ja. Jede DNA-Reparaturmutation bedeutet immunogen und ICI-sensitiv.":"Da. Orice mutație de reparare ADN înseamnă imunogen și sensibil la ICI.","BRCA2 ist funktionell gleichbedeutend mit MSI-H.":"BRCA2 este funcțional echivalent cu MSI-H.","Nur PD-L1 kann die Frage beantworten.":"Doar PD-L1 poate răspunde la întrebare.","HRR und MMR sind unterschiedliche Reparaturachsen mit unterschiedlichen Biomarkerfolgen.":"HRR și MMR sunt căi de reparare diferite, cu consecințe diferite asupra biomarkerilor.","Welche Rolle sollte der HRD-Score hier spielen?":"Ce rol ar trebui să aibă scorul HRD aici?","Nicht als Pflicht- oder Ersatzmarker: gen-spezifische BRCA/HRR-Diagnostik ist für diesen Prostatafall entscheidender.":"Nu ca marker obligatoriu sau de substituție: diagnosticul BRCA/HRR specific genelor este mai decisiv în acest caz de prostată.","Zwingend vor jeder PARP-Diskussion.":"Obligatoriu înainte de orice discuție PARP.","Er ersetzt die Keimbahnabklärung.":"Înlocuiește evaluarea germinală.","Er entscheidet primär über Immuntherapie.":"Determină în principal imunoterapia.","Der Ovarial-HRD-Workflow darf nicht unkritisch auf mCRPC übertragen werden.":"Fluxul HRD ovarian nu trebuie transferat necritic la mCRPC.","Ordnen Sie BRCA2, MMR/MSI und die Keimbahnfrage beim mCRPC so ein, dass die therapeutische Relevanz des Tumorbefunds genutzt wird, ohne die hereditäre Herkunft zu behaupten oder einen HRD-Score unnötig zur Voraussetzung zu machen.":"Încadrați BRCA2, MMR/MSI și problema germinală în mCRPC astfel încât relevanța terapeutică a rezultatului tumoral să fie utilizată fără a afirma originea ereditară și fără a transforma inutil scorul HRD într-o condiție prealabilă.","Validierte HRR/BRCA-Diagnostik am Tumor durchführen.":"Efectuează testare tumorală HRR/BRCA validată.","Pathogene BRCA2-Loss-of-function-Alteration als relevanten mCRPC-Biomarkerkontext berichten.":"Raportează alterarea patogenă loss-of-function BRCA2 ca context de biomarker relevant în mCRPC.","MMR-IHC/MSI separat prüfen: pMMR/MSS.":"Evaluează separat IHC MMR/MSI: pMMR/MSS.","PARP-Option an aktuelle Indikation, Vorbehandlung und klinische Eignung binden.":"Leagă opțiunea PARP de indicația actuală, tratamentul anterior și adecvarea clinică.","Keimbahnherkunft aus Tumor-VAF/LOH nicht ableiten; Humangenetik/Normalprobe empfehlen.":"Nu deduce originea germinală din VAF/LOH tumoral; recomandă genetică/probă normală.","HRD-Score nicht als universellen Pflichtmarker aus dem Ovarialkarzinom übernehmen.":"Nu prelua scorul HRD din cancerul ovarian ca marker universal obligatoriu.","Validiertes Tumor-BRCA/HRR-Panel statt Prostata-spezifischem Panel, sofern relevante HRR-Gene und Copy-number/Variantentypen ausreichend erfasst werden.":"Panel tumoral BRCA/HRR validat în locul unui panel specific prostatei, dacă genele HRR relevante și tipurile copy-number/variantă sunt acoperite adecvat.","Breiteres validiertes Panel mit BRCA/HRR plus MSI, wenn Material und TAT vertretbar sind; funktionelle MMR-IHC kann ergänzen.":"Panel validat mai larg cu BRCA/HRR plus MSI dacă materialul și TAT sunt acceptabile; IHC MMR funcțional poate completa.","HRD-Score als Pflicht":"Scor HRD obligatoriu","Überträgt einen entitätsspezifischen Ovarial-Workflow auf die Prostata.":"Transferă un flux ovarian specific entității la cancerul de prostată.","Tumor-BRCA = erblich":"BRCA tumoral = ereditar","Tumor-only-NGS beweist keine Keimbahnherkunft.":"NGS tumor-only nu demonstrează originea germinală.","BRCA = MSI/IO":"BRCA = MSI/IO","HRR und MMR sind verschiedene Reparaturwege und Biomarker.":"HRR și MMR sunt căi de reparare și biomarkeri diferiți.","Familienanamnese ignorieren":"Ignoră istoricul familial","Ein möglicher Keimbahnbefund hat Konsequenzen für Patient und Angehörige.":"Un posibil rezultat germinal are consecințe pentru pacient și rude.","Therapie kann schon tumorbezogen relevant sein, Familienrelevanz bleibt trotzdem offen":"Tratamentul poate fi deja relevant la nivel tumoral, în timp ce relevanța familială rămâne neclarificată","Die BRCA2-Loss-of-function-Alteration ist im mCRPC therapeutisch relevant, auch wenn sie somatisch sein könnte. Gleichzeitig macht die aktualisierte Familienanamnese eine Keimbahnabklärung besonders wichtig. MMR-IHC und MSI sind unauffällig. Der vermeintlich noch fehlende HRD-Score ist dagegen gar nicht der zentrale nächste Schritt.":"Alterarea loss-of-function BRCA2 este relevantă terapeutic în mCRPC chiar dacă ar putea fi somatică. În același timp, istoricul familial actualizat face evaluarea germinală deosebit de importantă. IHC MMR și MSI sunt nepatologice. Scorul HRD presupus încă lipsă nu este însă deloc următorul pas central.","Der Fall trennt Therapiebiomarker und Hereditätsdiagnostik: dieselbe Variante kann für die Tumortherapie relevant sein, während ihre Herkunft für die Familie separat geklärt werden muss.":"Cazul separă biomarkerii terapeutici de diagnosticul ereditar: aceeași variantă poate fi relevantă pentru tratamentul tumorii, în timp ce originea ei trebuie clarificată separat pentru familie.","BRCA2 genutzt, Keimbahn sauber getrennt":"BRCA2 utilizat, statusul germinal separat corect","Pathogene BRCA2-Loss-of-function-Alteration im Tumor mit Hinweis auf biallelische Inaktivierung; pMMR/MSS. PARP-relevanter mCRPC-Kontext gemäß aktueller Indikation/Vorbehandlung; separate humangenetische Keimbahnabklärung empfohlen. HRD-Score nicht als Pflichtmarker benötigt.":"Alterare loss-of-function BRCA2 patogenă în tumoră cu indicii compatibile cu inactivare bialelică; pMMR/MSS. Context mCRPC relevant pentru PARP conform indicației actuale/tratamentului anterior; se recomandă evaluare germinală separată prin genetică. Scorul HRD nu este necesar ca marker obligatoriu.","Therapie-, IO- und Hereditätsebene korrekt getrennt.":"Nivelurile terapeutic, IO și ereditar sunt separate corect.","BRCA2 erkannt, Heredität offen":"BRCA2 recunoscut, ereditatea rămâne neclarificată","BRCA2 wird therapeutisch korrekt erkannt, aber Keimbahnabklärung/Familienrelevanz nicht adressiert.":"BRCA2 este recunoscut corect terapeutic, dar evaluarea germinală/relevanța familială nu este abordată.","Klinisch wichtige zweite Ebene fehlt.":"Lipsește un al doilea nivel clinic important.","Ovarial-Workflow kopiert":"Flux ovarian copiat","PARP-Entscheidung wird von einem HRD-Score abhängig gemacht und Tumor-BRCA2 zugleich als sicher erblich bezeichnet.":"Decizia PARP este făcută dependentă de un scor HRD, iar BRCA2 tumoral este simultan declarat sigur ereditar.","Zwei entitätsspezifische Fehlübertragungen.":"Două transferuri greșite specifice entității.","Pathogene BRCA2-Variante im Tumor":"Variantă BRCA2 patogenă în tumoră","PARP-Eignung nach aktueller Indikation/Vorbehandlung prüfen und parallel humangenetische Beratung veranlassen.":"Evaluează eligibilitatea PARP conform indicației actuale/tratamentului anterior și organizează în paralel consiliere genetică.","Therapieentscheidung und Familienabklärung laufen koordiniert, aber diagnostisch getrennt.":"Decizia terapeutică și evaluarea familială se desfășoară coordonat, dar separat diagnostic.","Keinen MSI/MMR-basierten IO-Biomarker behaupten; andere klinische IO-Indikationen nur separat bewerten.":"Nu afirma un biomarker IO bazat pe MSI/MMR; alte indicații clinice IO se evaluează doar separat.","DNA-Reparatur wird nicht pauschal mit Immuntherapie gleichgesetzt.":"Repararea ADN nu este echivalată în mod general cu imunoterapia.","BRCA1/2 ist im mCRPC ein gen-spezifischer, therapeutisch relevanter Biomarkerkontext.":"BRCA1/2 este un context de biomarker specific genelor și relevant terapeutic în mCRPC.","Somatische und Keimbahn-BRCA-Alterationen sind für Therapie und Familie unterschiedliche Ebenen.":"Alterările BRCA somatice și germinale reprezintă niveluri diferite pentru tratament și familie.","Tumor-VAF/LOH beweist die Keimbahn nicht.":"VAF/LOH tumoral nu demonstrează originea germinală.","MMR/MSI muss unabhängig von HRR beurteilt werden.":"MMR/MSI trebuie evaluat independent de HRR.","Ein HRD-Genomic-Scar-Score ist kein universeller Pflichtmarker für PARP über Tumorentitäten hinweg.":"Un scor HRD genomic-scar nu este un marker universal obligatoriu pentru PARP în toate entitățile tumorale.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und pMMR/MSS. BRCA2 ist tumorbezogen PARP-relevant gemäß aktueller Indikation/Vorbehandlung. Die Keimbahnherkunft ist nicht aus Tumor-VAF oder LOH ableitbar; wegen Befund und Familienanamnese Humangenetik empfehlen. Kein obligatorischer Ovarial-HRD-Score.":"mCRPC cu alterare patogenă loss-of-function BRCA2 și pMMR/MSS. BRCA2 este relevant tumoral pentru PARP conform indicației actuale/tratamentului anterior. Originea germinală nu poate fi dedusă din VAF tumoral sau LOH; recomandă genetică datorită rezultatului și istoricului familial. Fără scor HRD ovarian obligatoriu.","BRCA2 tumorbezogen korrekt genutzt":"BRCA2 tumoral utilizat corect","MMR/MSI separat bewertet":"MMR/MSI evaluat separat","Keimbahn nicht behauptet":"Originea germinală nu este afirmată","HRD-Score nicht zum Pflichtmarker gemacht":"Scorul HRD nu este făcut obligatoriu","Warum kann derselbe BRCA2-Befund therapeutisch nutzbar sein, obwohl die Keimbahnherkunft noch offen ist?":"De ce poate același rezultat BRCA2 fi utilizabil terapeutic chiar dacă originea germinală rămâne neclarificată?","Welche Proben eignen sich zur Keimbahnklärung?":"Ce probe sunt adecvate pentru clarificarea statusului germinal?","Warum sind HRD-Genomic-Scar-Tests nicht automatisch zwischen Tumorentitäten übertragbar?":"De ce testele HRD genomic-scar nu sunt automat transferabile între entități tumorale?","BRCA2 ist therapeutisch relevant, ohne dass die Keimbahn bereits geklärt ist":"BRCA2 este relevant terapeutic fără ca statusul germinal să fie deja clarificat","Therapiebiomarker und Hereditätsstatus sind getrennte Ebenen":"Biomarkerul terapeutic și statusul ereditar sunt niveluri separate","HRR/BRCA → MMR/MSI separat → PARP-Kontext → Keimbahnklärung":"HRR/BRCA → MMR/MSI separat → context PARP → clarificare germinală","Therapieassoziierte MDS/AML nach DNA-schädigender Therapie → Instabilität als Chance und Risiko einordnen":"MDS/AML asociată terapiei după tratament genotoxic → încadrarea instabilității ca oportunitate și risc","Therapieassoziierte MDS/AML nach D…":"MDS/AML asociată terapiei după D…","Hämatologie / interdisziplinäres Tumorboard":"Hematologie / Tumor Board interdisciplinar","67-jährige Patientin mit neu aufgetretener Pancytopenie acht Jahre nach Behandlung eines Mammakarzinoms mit zytotoxischer Chemotherapie und Radiotherapie.":"Pacientă de 67 de ani cu pancitopenie nou apărută la opt ani după tratamentul unui cancer mamar cu chimioterapie citotoxică și radioterapie.","Wie werden Morphologie, Zytogenetik, molekulares Profil und die frühere zytotoxische Therapie zu einer belastbaren Diagnose- und Risikoeinschätzung integriert?":"Cum trebuie integrate morfologia, citogenetica, profilul molecular și terapia citotoxică anterioară într-o evaluare solidă a diagnosticului și riscului?","Therapiebeginn nach Abschluss der hämatologischen Klassifikation.":"Tratamentul începe după finalizarea clasificării hematologice.","Anthrazyklin-/Cyclophosphamid-haltige Chemotherapie und Bestrahlung vor acht Jahren.":"Chimioterapie cu antraciclină/ciclofosfamidă și radioterapie în urmă cu opt ani.","Aktuell":"Constatări actuale","Hb 8,4 g/dl, Thrombozyten 46/nl, Neutrophile 0,7/nl; peripher 9 % Blasten.":"Hb 8,4 g/dl, trombocite 46/nl, neutrofile 0,7/nl; 9% blaști periferici.","Knochenmark":"Măduvă osoasă","27 % myeloische Blasten, ausgeprägte Dysplasie.":"27% blaști mieloizi, displazie marcată.","Die Vorgeschichte wird allein zur Diagnose 'therapieassoziierte AML' gemacht oder ein einzelner DNMT3A-/TET2-/ASXL1-Befund wird ohne Morphologie/Zytogenetik als Neoplasiebeweis interpretiert.":"Doar istoricul este folosit pentru diagnosticul «AML asociată terapiei», sau un singur rezultat DNMT3A/TET2/ASXL1 este interpretat ca dovadă de neoplazie fără morfologie/citogenetică.","Morphologie + Vorbefunde":"Morfologie + rezultate anterioare","Hyperzellulär, 27 % Blasten, dysplastische Granulo- und Megakaryopoese.":"Hipercelular, 27% blaști, granulopoieză și megacariopoieză displazică.","Zytogenetik":"Citogenetică","Komplexer Karyotyp mit -5/del(5q), -7 und 17p-Verlust.":"Cariotip complex cu -5/del(5q), -7 și pierdere 17p.","Akute myeloische Neoplasie mit hochriskanter Genominstabilität; frühere zytotoxische Exposition muss als qualifizierender Kontext integriert werden.":"Neoplazie mieloidă acută cu instabilitate genomică de risc înalt; expunerea citotoxică anterioară trebuie integrată ca context calificator.","Welche Rolle spielt das molekulare Profil – und was darf daraus gerade nicht abgeleitet werden?":"Ce rol are profilul molecular – și ce nu trebuie dedus în mod specific din el?","EDTA-Knochenmarkaspirat plus Trepanobiopsie.":"Aspirat de măduvă osoasă în EDTA plus biopsie osteomedulară.","Tumorzellanteil":"Conținut tumoral","Blasten ca. 27 %; NGS aus Knochenmark geeignet.":"Blaști aprox. 27%; măduva osoasă este adecvată pentru NGS.","Vorbefunde":"Rezultate anterioare","Morphologie und Zytogenetik liegen bereits vor und dürfen nicht durch NGS ersetzt werden.":"Morfologia și citogenetica sunt deja disponibile și nu trebuie înlocuite de NGS.","Ein Pan-Tumorpanel mit TMB/MSI wäre für die konkrete myeloische Klassifikationsfrage Low Value; das fokussierte hämatologische Panel ist näher an der Fragestellung.":"Un panel pan-tumoral cu TMB/MSI ar avea valoare redusă pentru problema concretă de clasificare mieloidă; un panel hematologic focalizat este mai apropiat de întrebarea clinică.","Myeloischer Molekularkontext":"Context molecular mieloid","Hämatologisches NGS":"NGS hematologic","TP53 p.R273H mit VAF 43 % sowie DNMT3A p.R882H mit VAF 4 %. Im Kontext von 17p-Verlust und komplexem Karyotyp ist TP53 Teil der hochriskanten Neoplasie; die niedrigfrequente DNMT3A-Alteration allein wäre dagegen kein Beweis für AML und kann klonale Hämatopoese repräsentieren.":"TP53 p.R273H cu VAF 43% și DNMT3A p.R882H cu VAF 4%. În contextul pierderii 17p și al cariotipului complex, TP53 face parte din neoplazia cu risc înalt; alterarea DNMT3A de frecvență joasă singură nu ar demonstra AML și poate reprezenta hematopoieză clonală.","Zusätzliche solide-tumororientierte TMB/MSI-/Pan-Cancer-Information beantwortet die zentrale myeloische Klassifikations- und Risikofrage nicht besser und erzeugt unnötige Nebenbefunde.":"Informația suplimentară TMB/MSI/pan-cancer orientată spre tumori solide nu răspunde mai bine întrebării centrale de clasificare și risc mieloid și generează rezultate incidentale inutile.","Morphologie":"Morfologie","27 % myeloische Blasten mit Dysplasie.":"27% blaști mieloizi cu displazie.","Exposition":"Expunere","Zytotoxische Chemotherapie/Radiotherapie acht Jahre zuvor.":"Chimioterapie citotoxică/radioterapie cu opt ani înainte.","Akute myeloische Neoplasie mit TP53-Alteration und komplexer Zytogenetik nach vorausgegangener zytotoxischer Therapie. Die frühere Therapie ist ein wichtiger qualifizierender klinischer Kontext, die Erkrankung wird jedoch primär aus Morphologie und genetischen Merkmalen klassifiziert. Der TP53/komplexe-Karyotyp-Kontext spricht für ungünstige Biologie. Eine niedrigfrequente DNMT3A-Alteration allein wäre nicht ausreichend, um die Neoplasie zu definieren. 'Genomische Instabilität' ist hier kein pauschales Target- oder Immuntherapiesignal.":"Neoplazie mieloidă acută cu alterare TP53 și citogenetică complexă după terapie citotoxică anterioară. Tratamentul anterior este un context clinic calificator important, dar boala se clasifică în primul rând după morfologie și caracteristicile genetice. Contextul TP53/cariotip complex indică biologie nefavorabilă. O alterare DNMT3A de frecvență joasă singură nu ar fi suficientă pentru definirea neoplaziei. «Instabilitatea genomică» nu este aici un semnal general de target sau imunoterapie.","Teilbefund: Die frühere zytotoxische Therapie erhöht die Plausibilität eines post-zytotoxischen/therapiebezogenen Kontextes, ersetzt aber nicht die aktuelle morphologische und genetische Klassifikation. CHIP-typische Varianten dürfen nicht isoliert überinterpretiert werden.":"Rezultat parțial: terapia citotoxică anterioară crește plauzibilitatea unui context post-citotoxic/asociat terapiei, dar nu înlocuiește clasificarea morfologică și genetică actuală. Variantele tipice CHIP nu trebuie suprainterpretate izolat.","Morphologie/Genetik priorisieren und frühere zytotoxische Therapie als qualifizierenden Kontext integrieren":"Prioritizează morfologia/genetica și integrează terapia citotoxică anterioară ca context calificator","TP53 plus komplexen Karyotyp als hochriskante Biologie erkennen":"Recunoaște TP53 plus cariotip complex ca biologie de risc înalt","Niedrigfrequentes DNMT3A nicht allein als AML-Beweis interpretieren":"Nu interpreta DNMT3A de frecvență joasă singur ca dovadă de AML","Genominstabilität nicht automatisch als Target-/TMB-/IO-Chance verkaufen":"Nu prezenta automat instabilitatea genomică drept oportunitate target/TMB/IO","Hämatologische Klassifikation und Risikostratifikation nicht durch ein solides Pan-Panel ersetzen":"Nu înlocui clasificarea hematologică și stratificarea riscului cu un pan-panel pentru tumori solide","Optimale Lösung: AML/myeloische Neoplasie aus Morphologie und Genetik klassifizieren; die frühere zytotoxische Therapie als qualifizierenden Kontext dokumentieren; TP53 plus komplexe Zytogenetik als ungünstige Biologie einordnen; niedrigfrequentes DNMT3A als potenziellen CH-Klon nicht überbewerten.":"Soluție optimă: clasifică AML/neoplazia mieloidă pe baza morfologiei și geneticii; documentează terapia citotoxică anterioară ca context calificator; încadrează TP53 plus citogenetica complexă ca biologie nefavorabilă; nu supraevalua DNMT3A de frecvență joasă, care poate reprezenta o clonă CH.","AML":"AML","post cytotoxic therapy":"după terapie citotoxică","TP53":"TP53","complex karyotype":"cariotip complex","clonal hematopoiesis":"hematopoieză clonală","genomic instability":"instabilitate genomică","Nach zytotoxischer Therapie: TP53, komplexer Karyotyp und die Falle 'Genominstabilität = Target'":"După terapie citotoxică: TP53, cariotip complex și capcana «instabilitate genomică = target»","Molekularpathologie / Hämatologie / Translation":"Patologie moleculară / Hematologie / Translație","Eine myeloische Neoplasie nach zytotoxischer Therapie primär aus aktueller Morphologie und Genetik klassifizieren und die frühere Exposition als qualifizierenden Kontext integrieren.":"Clasifică o neoplazie mieloidă după terapie citotoxică în primul rând pe baza morfologiei și geneticii actuale și integrează expunerea anterioară ca context calificator.","TP53 plus komplexe Zytogenetik als hochriskante Biologie erkennen.":"Recunoaște TP53 plus citogenetica complexă ca biologie de risc înalt.","CHIP-typische Varianten wie niedrigfrequentes DNMT3A nicht isoliert als AML-Beweis interpretieren.":"Nu interpreta izolat variante tipice CHIP, precum DNMT3A de frecvență joasă, ca dovadă de AML.","Das biologische Konzept 'genomische Instabilität' nicht automatisch in einen therapeutischen Target- oder Immuntherapiemarker übersetzen.":"Nu traduce automat conceptul biologic «instabilitate genomică» într-un target terapeutic sau marker de imunoterapie.","Solide-tumororientierte Pan-Cancer-Tests nicht unkritisch auf eine myeloische Fragestellung übertragen.":"Nu transfera necritic teste pan-cancer orientate spre tumori solide la o problemă mieloidă.","Acht Jahre nach Chemotherapie und Bestrahlung wegen Mammakarzinoms entwickelt die Patientin eine Pancytopenie. Das Knochenmark zeigt 27 % Blasten, der Karyotyp ist komplex. Im NGS erscheinen TP53 mit hoher und DNMT3A mit sehr niedriger VAF. Im Board fallen zwei schnelle Erklärungen: 'Die alte Chemotherapie hat die AML verursacht' und 'viel Genominstabilität bedeutet vielleicht viel Target-/IO-Potenzial'. Beide Aussagen müssen präziser werden.":"La opt ani după chimioterapie și radioterapie pentru cancer mamar, pacienta dezvoltă pancitopenie. Măduva osoasă arată 27% blaști, iar cariotipul este complex. NGS evidențiază TP53 cu VAF mare și DNMT3A cu VAF foarte mică. În board apar două explicații rapide: «Chimioterapia veche a cauzat AML» și «multă instabilitate genomică poate însemna mult potențial target/IO». Ambele afirmații necesită mai multă precizie.","67-jährige Patientin mit akuter myeloischer Neoplasie nach vorausgegangener zytotoxischer Therapie. Morphologie und komplexe Zytogenetik stehen bereits fest; das molekulare Panel soll die biologische Einordnung ergänzen. Ziel ist nicht, aus einer Exposition oder einem Einzelgen allein eine Diagnose zu konstruieren, sondern die aktuelle Erkrankung korrekt zu klassifizieren und die Genominstabilität klinisch realistisch zu bewerten.":"Pacientă de 67 de ani cu neoplazie mieloidă acută după terapie citotoxică anterioară. Morfologia și citogenetica complexă sunt deja stabilite; panelul molecular trebuie să completeze încadrarea biologică. Scopul nu este construirea unui diagnostic dintr-o expunere sau o singură genă, ci clasificarea corectă a bolii actuale și evaluarea realistă clinic a instabilității genomice.","27 % myeloische Blasten mit deutlicher Dysplasie.":"27% blaști mieloizi cu displazie marcată.","Die aktuelle Neoplasie ist morphologisch manifest; NGS ersetzt diese Ebene nicht.":"Neoplazia actuală este manifestă morfologic; NGS nu înlocuiește acest nivel.","Mehrere strukturelle Verluste sprechen für hochriskante klonale Genominstabilität.":"Pierderile structurale multiple indică instabilitate genomică clonală de risc înalt.","Zytotoxische Chemotherapie und Radiotherapie acht Jahre zuvor.":"Chimioterapie citotoxică și radioterapie cu opt ani înainte.","Wichtiger diagnostischer Qualifier/Kontext, aber nicht die alleinige Krankheitsdefinition.":"Qualifier/context diagnostic important, dar nu definiția unică a bolii.","Blutbild":"Hemogramă","Pancytopenie, peripher 9 % Blasten.":"Pancitopenie, 9% blaști periferici.","27 % Blasten, dysplastische Myelopoese.":"27% blaști, mielopoieză displazică.","Karyotyp":"Cariotip","Komplex mit -5/del(5q), -7 und 17p-Verlust.":"Complex cu -5/del(5q), -7 și pierdere 17p.","Knochenmark ist für fokussiertes hämatologisches NGS geeignet.":"Măduva osoasă este adecvată pentru NGS hematologic focalizat.","Morphologie und Zytogenetik sind bereits hochinformativ und dürfen nicht durch einen molekularen Einzelmarker ersetzt werden.":"Morfologia și citogenetica sunt deja foarte informative și nu trebuie înlocuite de un singur marker molecular.","Ein solides Pan-Cancer-Panel mit TMB/MSI erzeugt für diese Fragestellung eher Nebeninformation als klinischen Mehrwert.":"Un panel pan-cancer pentru tumori solide cu TMB/MSI ar genera mai degrabă informații secundare decât valoare clinică pentru această întrebare.","Wie sollte die frühere zytotoxische Therapie diagnostisch verwendet werden?":"Cum trebuie utilizată diagnostic terapia citotoxică anterioară?","Als wichtiger qualifizierender Kontext einer anhand aktueller morphologischer/genetischer Merkmale klassifizierten myeloischen Neoplasie.":"Ca un context calificator important pentru o neoplazie mieloidă clasificată după caracteristicile morfologice/genetice actuale.","Allein die Exposition definiert unabhängig von aktuellen Befunden automatisch die AML-Untergruppe.":"Expunerea singură definește automat subgrupul AML indiferent de rezultatele actuale.","Die frühere Therapie darf in der Diagnose überhaupt nicht erwähnt werden.":"Terapia anterioară nu trebuie menționată deloc în diagnostic.","Sie ist primär ein therapeutischer Target-Biomarker.":"Este în primul rând un biomarker target terapeutic.","Moderne Klassifikation priorisiert die aktuelle Krankheitsbiologie; die Exposition wird als relevanter Kontext/Qualifier integriert.":"Clasificarea modernă prioritizează biologia actuală a bolii; expunerea este integrată ca context/qualifier relevant.","Wie ist TP53 VAF 43 % zusammen mit 17p-Verlust und komplexem Karyotyp zu bewerten?":"Cum trebuie evaluat TP53 VAF 43% împreună cu pierderea 17p și cariotipul complex?","Als Teil einer hochriskanten TP53-/komplex-karyotypischen Krankheitsbiologie, nicht als isolierter Einzelmarker.":"Ca parte a biologiei bolii cu TP53/cariotip complex de risc înalt, nu ca marker izolat.","Als einfacher Targetmarker mit erwartbar günstiger Prognose.":"Ca marker target simplu cu prognostic favorabil așteptat.","Sicher nur CHIP, weil TP53 auch in klonaler Hämatopoese vorkommen kann.":"Sigur doar CHIP, deoarece TP53 poate apărea și în hematopoieza clonală.","Zytogenetik macht molekulare Befunde irrelevant.":"Citogenetica face rezultatele moleculare irelevante.","Genetischer Kontext und klonale Architektur sind entscheidend.":"Contextul genetic și arhitectura clonală sunt decisive.","DNMT3A p.R882H liegt zusätzlich mit 4 % VAF vor. Was ist die beste Interpretation?":"DNMT3A p.R882H este prezent suplimentar la VAF 4%. Care este cea mai bună interpretare?","Ein niedrigfrequenter CH-Klon ist möglich; DNMT3A allein beweist weder AML noch erklärt es die gesamte hochriskante Erkrankung.":"Este posibilă o clonă CH de frecvență joasă; DNMT3A singur nu demonstrează AML și nici nu explică întreaga boală de risc înalt.","DNMT3A definiert allein die AML.":"DNMT3A singur definește AML.","4 % VAF beweist eine Keimbahnmutation.":"VAF 4% demonstrează o mutație germinală.","DNMT3A ist ein PARP-Biomarker.":"DNMT3A este biomarker PARP.","CHIP-typische Gene müssen im morphologischen und klonalen Kontext interpretiert werden.":"Genele tipice CHIP trebuie interpretate în context morfologic și clonal.","Was bedeutet die ausgeprägte Genominstabilität therapeutisch?":"Ce înseamnă terapeutic instabilitatea genomică marcată?","Sie erklärt aggressive klonale Evolution/Risikobiologie, ist aber kein pauschaler TMB-, IO- oder Targetmarker; konkrete Alterationen und hämatologische Evidenz entscheiden.":"Explică evoluția clonală agresivă/biologia de risc, dar nu este un marker general TMB, IO sau target; alterările concrete și dovezile hematologice decid.","Viele Aberrationen bedeuten automatisch hohe Immuntherapie-Sensitivität.":"Multe aberații înseamnă automat sensibilitate ridicată la imunoterapie.","Komplexer Karyotyp ist automatisch eine PARP-Indikation.":"Un cariotip complex indică automat PARP.","Mehr Instabilität bedeutet generell bessere Targetierbarkeit und Prognose.":"Mai multă instabilitate înseamnă în general targetabilitate și prognostic mai bune.","Ein biologisches Hallmark ist nicht identisch mit einem validierten klinischen Biomarker.":"Un hallmark biologic nu este identic cu un biomarker clinic validat.","Integrieren Sie frühere zytotoxische Therapie, Morphologie, komplexen Karyotyp und TP53/DNMT3A so, dass Diagnose-/Risikokontext und Grenzen des Begriffs 'genomische Instabilität' klar werden.":"Integrați terapia citotoxică anterioară, morfologia, cariotipul complex și TP53/DNMT3A astfel încât contextul diagnostic/de risc și limitele termenului «instabilitate genomică» să fie clare.","Aktuelle myeloische Neoplasie aus Morphologie und Genetik einordnen.":"Încadrează neoplazia mieloidă actuală pe baza morfologiei și geneticii.","Vorausgegangene zytotoxische Therapie als relevanten post-zytotoxischen/therapiebezogenen Qualifier dokumentieren.":"Documentează terapia citotoxică anterioară ca qualifier relevant post-citotoxic/asociat terapiei.","TP53 zusammen mit 17p-Verlust und komplexem Karyotyp als hochriskanten biologischen Kontext bewerten.":"Evaluează TP53 împreună cu pierderea 17p și cariotipul complex ca un context biologic de risc înalt.","Niedrigfrequentes DNMT3A nicht isoliert als AML-definierend interpretieren.":"Nu interpreta DNMT3A de frecvență joasă izolat ca definitoriu pentru AML.","Keine pauschale PARP-/IO-/TMB-Logik aus 'Genominstabilität' ableiten.":"Nu deduce o logică generală PARP/IO/TMB din «instabilitate genomică».","Hämatologiespezifische Diagnostik gegenüber einem Pan-Cancer-Panel priorisieren.":"Prioritizează diagnosticul specific hematologic față de un panel pan-cancer.","Ein umfassenderes validiertes myeloisches NGS-Panel wäre für reale Routinediagnostik sinnvoll, sofern Morphologie, Immunphänotyp und Zytogenetik integriert bleiben.":"Un panel NGS mieloid validat mai cuprinzător ar fi adecvat în diagnosticul de rutină real, cu condiția integrării morfologiei, imunofenotipului și citogeneticii.","Bei unklarer klonaler Architektur kann eine geeignete Verlauf-/Vorprobe helfen, präexistente klonale Hämatopoese von dominanter Leukämieklonalität abzugrenzen.":"Dacă arhitectura clonală este neclară, o probă adecvată de follow-up/anterioară poate ajuta la diferențierea hematopoiezei clonale preexistente de clonalitatea leucemică dominantă.","Exposition = Diagnose":"Expunere = diagnostic","Die frühere Therapie ist Kontext/Qualifier; aktuelle Morphologie und Genetik definieren die Erkrankung.":"Terapia anterioară este context/qualifier; morfologia și genetica actuale definesc boala.","DNMT3A = AML":"DNMT3A = AML","CHIP-typische Varianten können ohne manifeste Neoplasie vorkommen und brauchen Kontext.":"Variantele tipice CHIP pot apărea fără neoplazie manifestă și necesită context.","Genominstabilität = IO/PARP":"Instabilitate genomică = IO/PARP","Hallmark und validierter prädiktiver Biomarker sind nicht dasselbe.":"Hallmark și biomarkerul predictiv validat nu sunt același lucru.","Pan-Cancer-TMB/MSI":"TMB/MSI pan-cancer","Für die konkrete myeloische Klassifikationsfrage ist dies kein sinnvoller Primäransatz.":"Aceasta nu este o abordare primară utilă pentru problema concretă de clasificare mieloidă.","Der kleine DNMT3A-Klon ist nicht die Geschichte – TP53 plus Karyotyp ist es":"Mica clonă DNMT3A nu este povestea – TP53 plus cariotipul da","Das Panel zeigt DNMT3A p.R882H nur mit 4 % VAF, daneben TP53 p.R273H mit 43 %. Zusammen mit 17p-Verlust und komplexem Karyotyp ist TP53 Teil der dominanten hochriskanten Krankheitsbiologie. DNMT3A kann dagegen einen kleineren, möglicherweise präexistierenden CH-Klon markieren. Die 'vielen genetischen Schäden' sind hier vor allem Risikosignatur – nicht automatisch therapeutische Verwundbarkeit.":"Panelul arată DNMT3A p.R882H la doar 4% VAF, alături de TP53 p.R273H la 43%. Împreună cu pierderea 17p și cariotipul complex, TP53 face parte din biologia dominantă de risc înalt a bolii. DNMT3A poate marca în schimb o clonă CH mai mică, posibil preexistentă. «Multe leziuni genetice» reprezintă aici în primul rând o semnătură de risc – nu automat o vulnerabilitate terapeutică.","Der Fall zeigt, dass Mutationsnamen ohne Klonstärke, Zytogenetik, Morphologie und klinischen Kontext leicht in die falsche Richtung führen.":"Cazul arată cât de ușor pot duce în direcția greșită numele mutațiilor fără mărimea clonei, citogenetică, morfologie și context clinic.","Klonale Architektur und Exposition integriert":"Arhitectură clonală și expunere integrate","Akute myeloische Neoplasie mit TP53-Alteration und komplexem Karyotyp nach zytotoxischer Therapie. TP53/17p/komplexer Karyotyp = hochriskanter dominanter Kontext; DNMT3A 4 % VAF potenziell CH-Klon. Keine pauschale Target-/IO-Aussage aus Genominstabilität.":"Neoplazie mieloidă acută cu alterare TP53 și cariotip complex după terapie citotoxică. TP53/17p/cariotip complex = context dominant de risc înalt; DNMT3A VAF 4% potențial clonă CH. Fără afirmație generală target/IO din instabilitate genomică.","Morphologie, Genetik, Exposition und Klonalität korrekt zusammengeführt.":"Morfologia, genetica, expunerea și clonalitatea sunt integrate corect.","Therapieassoziiert erkannt, Genetik zu grob":"Contextul asociat terapiei recunoscut, genetica prea grosieră","Die frühere Chemotherapie wird korrekt erwähnt, aber TP53 und DNMT3A werden gleichgewichtet und der komplexe Karyotyp bleibt unterbewertet.":"Chimioterapia anterioară este menționată corect, dar TP53 și DNMT3A sunt ponderate egal, iar cariotipul complex este subevaluat.","Klonale und prognostische Hierarchie fehlt.":"Lipsește ierarhia clonală și prognostică.","Instabilität als Therapiechance verkauft":"Instabilitatea prezentată ca oportunitate terapeutică","Komplexer Karyotyp und TP53 werden als unspezifischer Hinweis auf hohe TMB/IO- oder PARP-Sensitivität interpretiert.":"Cariotipul complex și TP53 sunt interpretate ca indiciu nespecific de TMB ridicat/IO sau sensibilitate PARP.","Hallmark wurde fälschlich zum prädiktiven Biomarker gemacht.":"Un hallmark a fost transformat greșit într-un biomarker predictiv.","TP53 + komplexer Karyotyp bestätigt":"TP53 + cariotip complex confirmat","Hämatologische Risikostratifikation und Therapieplanung entsprechend der hochriskanten Krankheitsbiologie durchführen.":"Efectuează stratificarea hematologică a riscului și planificarea terapeutică în funcție de biologia bolii cu risc înalt.","Die Priorität liegt auf korrekter Klassifikation/Risiko- und Therapieplanung, nicht auf unspezifischem Pan-Cancer-Targeting.":"Prioritatea este clasificarea corectă/riscul și planificarea terapeutică, nu targetarea pan-cancer nespecifică.","niedrigfrequente CH-typische Variante":"variantă tipică CH de frecvență joasă","Nur im Kontext interpretieren; bei Bedarf Verlauf/Vorproben zur Klonhistorie heranziehen.":"Interpretează numai în context; dacă este necesar, folosește probe de follow-up/anterioare pentru istoricul clonal.","CHIP und manifeste Neoplasie werden nicht verwechselt.":"CHIP și neoplazia manifestă nu sunt confundate.","Post-zytotoxische/therapiebezogene Vorgeschichte ist ein wichtiger Qualifier, nicht die alleinige Definition der aktuellen myeloischen Erkrankung.":"Istoricul post-citotoxic/asociat terapiei este un qualifier important, nu definiția unică a bolii mieloide actuale.","TP53 plus komplexer Karyotyp kennzeichnet hochriskante Biologie.":"TP53 plus cariotip complex caracterizează biologia de risc înalt.","Niedrige VAF in CHIP-typischen Genen kann eine kleinere Begleitklonalität darstellen.":"VAF scăzută în gene tipice CHIP poate reprezenta o clonă însoțitoare mai mică.","Genomische Instabilität ist ein Hallmark, aber kein universeller Target- oder Immuntherapiemarker.":"Instabilitatea genomică este un hallmark, dar nu un biomarker universal de target sau imunoterapie.","Hämatologische Diagnostik muss Morphologie, Zytogenetik und Molekulargenetik integrieren.":"Diagnosticul hematologic trebuie să integreze morfologia, citogenetica și genetica moleculară.","Akute myeloische Neoplasie nach zytotoxischer Therapie mit dominanter TP53-/komplex-karyotypischer Hochrisikobiologie. Die Exposition wird als Qualifier integriert. DNMT3A bei 4 % VAF kann eine kleinere CH-Klonalität repräsentieren und definiert die AML nicht. Aus Genominstabilität folgt keine pauschale PARP-/IO-Indikation.":"Neoplazie mieloidă acută după terapie citotoxică, cu biologie dominantă TP53/cariotip complex de risc înalt. Expunerea este integrată ca qualifier. DNMT3A la VAF 4% poate reprezenta o clonă CH mai mică și nu definește AML. Instabilitatea genomică nu implică o indicație generală PARP/IO.","Exposition als Qualifier statt Alleindefinition":"Expunerea ca qualifier, nu ca definiție unică","TP53/komplexer Karyotyp priorisiert":"TP53/cariotip complex prioritizat","DNMT3A niedrig-VAF nicht überinterpretiert":"DNMT3A cu VAF scăzută nesuprainterpretat","Hallmark ≠ klinischer Biomarker":"Hallmark ≠ biomarker clinic","Warum sind Therapiegeschichte und aktuelle Genetik beide wichtig, aber nicht austauschbar?":"De ce sunt importante atât istoricul terapeutic, cât și genetica actuală, dar nu sunt interschimbabile?","Wie hilft die VAF bei der Interpretation möglicher CH-Klone?":"Cum ajută VAF la interpretarea posibilelor clone CH?","Welche zusätzlichen Untersuchungen gehören real zur AML-Klassifikation, obwohl dieser Simulatorfall den Fokus enger setzt?":"Ce investigații suplimentare fac în mod real parte din clasificarea AML, chiar dacă acest caz din simulator are un focus mai restrâns?","DNMT3A low-VAF ist Nebenklon; TP53 plus komplexer Karyotyp dominiert":"DNMT3A cu VAF scăzută este o clonă minoră; TP53 plus cariotipul complex domină","Genominstabilität ist Risikobiologie, nicht automatisch Target":"Instabilitatea genomică este biologie de risc, nu automat un target","Exposition → Morphologie/Zytogenetik → TP53/DNMT3A-Klonalität → Risikokontext":"Expunere → morfologie/citogenetică → clonalitate TP53/DNMT3A → context de risc","„Cold Tumor“ mit wenig TILs und dichter Stromabarriere → Warum ist PD-1 allein wahrscheinlich schwach?":"«Tumor rece» cu puțini TIL și barieră stromală densă → De ce este probabil slab PD-1 singur?","„Cold Tumor“ mit wenig TILs und di…":"«Tumor rece» cu puțini TIL și ba…","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach systemischer Erstlinientherapie. Ein externer Zusatzbefund nennt PD-L1 TPS 15 % und löst die Frage nach einer PD-1-Monotherapie aus.":"Pacient de 64 de ani cu adenocarcinom ductal pancreatic metastatic și progresie după terapia sistemică de primă linie. Un raport extern suplimentar menționează PD-L1 TPS 15% și ridică întrebarea unei monoterapii PD-1.","Ist die PD-L1-Expression hier ein belastbarer Hinweis auf Checkpoint-Sensitivität – oder spricht das gesamte Tumor-Immune-Milieu eher dagegen?":"Este expresia PD-L1 aici un indiciu solid de sensibilitate la checkpoint – sau mediul tumoral-imun global sugerează contrariul?","Die Zweitlinienstrategie soll im nächsten MTB festgelegt werden.":"Strategia de linia a doua trebuie stabilită la următorul MTB.","Krankheitsverlauf":"Evoluția bolii","Primär lokal fortgeschritten, später hepatische Metastasierung; nun radiologischer Progress.":"Inițial local avansat, ulterior metastaze hepatice; acum progresie radiologică.","Systemische Standardtherapie, insgesamt gute Belastbarkeit; keine bekannte Autoimmunerkrankung.":"Terapie sistemică standard, stare generală bună; fără boală autoimună cunoscută.","Externer Impuls":"Impuls extern","PD-L1 TPS 15 % wird im Zuweiserbrief als 'positiv – Immuntherapie möglich?' markiert.":"PD-L1 TPS 15% este marcat în scrisoarea de trimitere ca «pozitiv – imunoterapie posibilă?».","Ein exprimierter Checkpoint wird mit bereits vorhandener effektiver Antitumor-Immunität gleichgesetzt.":"Un checkpoint exprimat este echivalat cu o imunitate antitumorală eficientă deja prezentă.","Duktales Adenokarzinom mit ausgeprägter desmoplastischer Stromareaktion.":"Adenocarcinom ductal cu reacție stromală desmoplazică marcată.","Immunmorphologie":"Morfologie imună","Nur wenige intraepitheliale Lymphozyten; Immunzellen liegen überwiegend stromal/peritumoral.":"Doar câteva limfocite intraepiteliale; celulele imune sunt predominant stromale/peritumorale.","PD-L1 Vorbefund":"Rezultat PD-L1 anterior","TPS 15 %, technisch plausibel und reproduzierbar.":"TPS 15%, tehnic plauzibil și reproductibil.","MMR/MSI, TMB sowie räumlicher TIL-/Stromakontext.":"MMR/MSI, TMB și contextul spațial TIL/stromal.","FFPE-Lebermetastase, Block M4.":"Metastază hepatică FFPE, bloc M4.","ca. 35 %, nach Makrodissektion ausreichend.":"aprox. 35%, suficient după macrodisecție.","10 Schnitte; fokussierte IHC plus DNA-basierte Zusatzdiagnostik möglich.":"10 secțiuni; este posibilă IHC focalizată plus testare suplimentară bazată pe ADN.","Explorative TME-Marker können die Biologie illustrieren, sind aber kein validierter Ersatz für etablierte prädiktive Marker.":"Markerii exploratori TME pot ilustra biologia, dar nu sunt un substitut validat pentru markerii predictivi consacrați.","Etablierte immunonkologische Biomarker":"Biomarkeri imunooncologici consacrați","TIL-/TME-Kontext":"Context TIL/TME","MMR-Proteine erhalten; molekular MSS. Es liegt damit kein dMMR/MSI-H-Kontext als etablierter starker ICI-Biomarker vor.":"Proteinele MMR sunt păstrate; molecular MSS. Prin urmare, nu există context dMMR/MSI-H ca biomarker ICI puternic consacrat.","TMB niedrig (3,2 Mut/Mb). Der Wert liefert in diesem Fall keinen zusätzlichen Hinweis auf eine ausgeprägte Neoantigenlast.":"TMB scăzut (3,2 Mut/Mb). În acest caz, valoarea nu oferă un indiciu suplimentar pentru o încărcătură neoantigenică ridicată.","PD-L1 TPS 15 % wird bestätigt. Der Befund ist real, darf beim Pankreasadenokarzinom aber nicht isoliert als ausreichender Selektionsmarker für PD-1-Monotherapie interpretiert werden.":"PD-L1 TPS 15% este confirmat. Rezultatul este real, dar în adenocarcinomul pancreatic nu trebuie interpretat izolat ca marker suficient de selecție pentru monoterapie PD-1.","Immuninfiltrat":"Infiltrat imun","CD8-positive T-Zellen sind insgesamt spärlich und überwiegend stromal/peritumoral; nur wenige erreichen Tumorzellnester.":"Celulele T CD8-pozitive sunt în general rare și predominant stromale/peritumorale; doar câteva ajung în cuiburile de celule tumorale.","Stromakontext":"Context stromal","Ausgeprägte desmoplastische, fibroblastenreiche Stromazone mit immune-excluded Muster. Der Befund illustriert eine physische/biologische Barriere, ist aber kein eigenständig validierter Therapie-Selektionsassay.":"Zonă stromală desmoplazică marcată, bogată în fibroblaste, cu pattern immune-excluded. Rezultatul ilustrează o barieră fizică/biologică, dar nu este un test independent validat pentru selecția terapiei.","Ausgeprägt desmoplastisches Pankreasadenokarzinom mit wenig intratumoralen Lymphozyten.":"Adenocarcinom pancreatic puternic desmoplazic cu puține limfocite intratumorale.","IHC und DNA-basierte Analysen technisch auswertbar.":"IHC și analizele bazate pe ADN sunt tehnic evaluabile.","Metastasiertes duktales Pankreasadenokarzinom mit bestätigter PD-L1-Expression, jedoch pMMR/MSS, niedriger TMB und deutlich immune-excluded/desmoplastischem Mikromilieu. PD-L1 allein begründet hier keine belastbare PD-1-Monotherapie-Strategie. TIL-/Stromamarker erklären die biologische Plausibilität eines 'cold/excluded' Tumors, sind aber selbst keine validierten Selektionsmarker.":"Adenocarcinom ductal pancreatic metastatic cu expresie PD-L1 confirmată, dar pMMR/MSS, TMB scăzut și microambient clar immune-excluded/desmoplazic. PD-L1 singur nu oferă aici o bază solidă pentru o strategie de monoterapie PD-1. Markerii TIL/stromali explică plauzibilitatea biologică a unui tumor «cold/excluded», dar nu sunt ei înșiși markeri de selecție validați.","Teilbefund: PD-L1 ist exprimiert, aber ohne MMR/MSI/TMB- und räumlichen TIL-Kontext bleibt die Aussage zur Checkpoint-Sensitivität unvollständig.":"Rezultat parțial: PD-L1 este exprimat, dar fără MMR/MSI/TMB și contextul spațial TIL, concluzia privind sensibilitatea la checkpoint rămâne incompletă.","PD-L1 als Kontextmarker, nicht als alleinige Therapieentscheidung behandeln":"Tratează PD-L1 ca marker de context, nu ca unică decizie terapeutică","pMMR/MSS und niedrige TMB als fehlende starke ICI-Signale benennen":"Menționează pMMR/MSS și TMB scăzut ca absență a unor semnale ICI puternice","immune-excluded/desmoplastisches Muster biologisch erklären":"Explică biologic patternul immune-excluded/desmoplazic","TME-IHC nicht als validierten Therapie-Selektionsassay verkaufen":"Nu prezenta IHC TME ca test validat de selecție terapeutică","Falschaussage: PD-L1-Positivität beweist eine ausreichende Effektor-T-Zell-Antwort":"Afirmație falsă: pozitivitatea PD-L1 demonstrează un răspuns adecvat al celulelor T efectoare","Optimale Lösung: PD-L1 15 % nicht isoliert interpretieren; pMMR/MSS, niedrige TMB und das immune-excluded/desmoplastische Muster integrieren. Die TME-Befunde erklären die biologische Barriere, ersetzen aber keine klinisch validierten Biomarker oder leitliniengerechte Therapieentscheidung.":"Soluție optimă: nu interpreta PD-L1 15% izolat; integrează pMMR/MSS, TMB scăzut și patternul immune-excluded/desmoplazic. Rezultatele TME explică bariera biologică, dar nu înlocuiesc biomarkerii validați clinic sau deciziile terapeutice bazate pe ghiduri.","Pankreasadenokarzinom":"Adenocarcinom pancreatic","TMB-low":"TMB-low","TILs":"TIL","TME":"TME","Desmoplasie":"Desmoplazie","Immune exclusion":"Excludere imună","PD-L1 vorhanden, aber die T-Zellen kommen nicht hinein: immune-excluded Pankreasadenokarzinom":"PD-L1 prezent, dar celulele T nu pot pătrunde: adenocarcinom pancreatic immune-excluded","Molekularpathologie / Gastroonkologie / MTB":"Patologie moleculară / Gastro-oncologie / MTB","PD-L1-Expression von einer tatsächlich inflamed/hot Tumormikroumgebung unterscheiden.":"Distinge expresia PD-L1 de un microambient tumoral cu adevărat inflamat/hot.","MMR/MSI und TMB als etabliertere immunonkologische Biomarker gegenüber explorativen TME-Markern priorisieren.":"Prioritizează MMR/MSI și TMB ca biomarkeri imunooncologici mai consacrați față de markerii exploratori TME.","Ein immune-excluded Muster aus Morphologie, TIL-Verteilung und desmoplastischem Stroma ableiten.":"Deduce un pattern immune-excluded din morfologie, distribuția TIL și stroma desmoplazică.","Verstehen, dass Stromabarriere/TIL-IHC die Biologie erklären, aber keine validierte Therapie-Selektion ersetzen.":"Înțelege că bariera stromală/IHC TIL explică biologia, dar nu înlocuiește selecția terapeutică validată.","PD-1-Monotherapie nicht allein aus einem PD-L1-positiven Befund ableiten.":"Nu deduce monoterapia PD-1 doar dintr-un rezultat PD-L1 pozitiv.","Im Zuweiserbrief steht fett: 'PD-L1 TPS 15 % – Immuntherapie?' Auf dem HE sieht der Tumor jedoch fast wie eine Festung aus: breite desmoplastische Stromazonen, wenige T-Zellen und kaum Lymphozyten in den Tumorzellnestern. Der Fall zwingt zur Frage, ob ein exprimierter Checkpoint überhaupt etwas nützt, wenn kaum aktivierbare Effektor-T-Zellen den Tumor erreichen.":"Scrisoarea de trimitere spune cu litere îngroșate: «PD-L1 TPS 15% – imunoterapie?» Pe HE însă tumora arată aproape ca o fortăreață: zone stromale desmoplazice largi, puține celule T și aproape niciun limfocit în cuiburile tumorale. Cazul obligă la întrebarea dacă un checkpoint exprimat este util atunci când puține celule T efectoare activabile ajung la tumoră.","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach Erstlinientherapie. Ein externer PD-L1-Befund ist positiv. Im MTB soll geklärt werden, ob daraus eine belastbare PD-1-Monotherapie-Strategie folgt und welche Bedeutung das auffallend desmoplastische, lymphozytenarme Mikromilieu besitzt.":"Pacient de 64 de ani cu adenocarcinom ductal pancreatic metastatic și progresie după terapia de primă linie. Un rezultat extern PD-L1 este pozitiv. MTB trebuie să clarifice dacă aceasta susține o strategie solidă de monoterapie PD-1 și ce semnificație are microambientul evident desmoplazic, sărac în limfocite.","Verlockender Einzelmarker":"Marker unic tentant","PD-L1 TPS 15 % ist technisch reproduzierbar.":"PD-L1 TPS 15% este tehnic reproductibil.","Ein real positiver Marker kann trotzdem im falschen Entitäts-/Biologiekontext wenig prädiktive Aussage besitzen.":"Un marker cu adevărat pozitiv poate avea totuși valoare predictivă redusă în contextul greșit de entitate/biologie.","Morphologisches Gegenargument":"Contraargument morfologic","Breite Desmoplasie, wenige intratumorale TILs.":"Desmoplazie largă, puțini TIL intratumorali.","Checkpoint-Blockade reaktiviert vorhandene Immunantwort; sie erzeugt nicht automatisch eine fehlende T-Zell-Infiltration.":"Blocada checkpoint reactivează un răspuns imun existent; nu creează automat infiltrarea cu celule T care lipsește.","Validierte vs. explorative Ebene":"Nivel validat vs explorator","MMR/MSI/TMB können klinisch validierte Signale liefern; TME-IHC illustriert Mechanismen.":"MMR/MSI/TMB pot oferi semnale validate clinic; IHC TME ilustrează mecanisme.","Mechanistische Plausibilität und validierter Therapiebiomarker sind nicht dasselbe.":"Plausibilitatea mecanistică și biomarkerul terapeutic validat nu sunt același lucru.","PDAC mit ausgeprägter Desmoplasie und wenig intratumoralen Lymphozyten.":"PDAC cu desmoplazie marcată și puține limfocite intratumorale.","TPS 15 %, reproduzierbar.":"TPS 15%, reproductibil.","Metastasenblock mit ca. 35 % Tumoranteil; fokussierte Zusatzdiagnostik möglich.":"Bloc metastatic cu aprox. 35% conținut tumoral; testare suplimentară focalizată posibilă.","Nur zehn Schnitte: explorative Zusatz-IHC muss einen klaren didaktischen/biologischen Nutzen haben.":"Doar zece secțiuni: IHC suplimentară exploratorie trebuie să aibă o valoare didactică/biologică clară.","TME-/Stroma-IHC ist in diesem Fall bewusst eine mechanistische Zusatzebene, kein validierter Companion-Diagnostic-Ersatz.":"IHC TME/stromală este intenționat un nivel mecanistic suplimentar în acest caz, nu un substitut validat de companion diagnostic.","MMR/MSI/TMB müssen gegenüber breit gestreuter Immun-IHC priorisiert werden, wenn die Therapiefrage im Vordergrund steht.":"MMR/MSI/TMB trebuie prioritizate față de o IHC imună larg dispersată atunci când întrebarea terapeutică este centrală.","Was bedeutet PD-L1 TPS 15 % in diesem PDAC am ehesten?":"Ce înseamnă cel mai probabil PD-L1 TPS 15% în acest PDAC?","Der Befund ist biologisch real, reicht aber ohne entitätsspezifisch validierten Kontext nicht für eine belastbare PD-1-Monotherapie-Entscheidung.":"Rezultatul este biologic real, dar fără un context validat specific entității nu este suficient pentru o decizie solidă de monoterapie PD-1.","Jede PD-L1-Positivität ist tumoragnostisch eine ICI-Indikation.":"Orice pozitivitate PD-L1 este o indicație tumor-agnostică pentru ICI.","PD-L1 kann bei PDAC technisch nicht gemessen werden.":"PD-L1 nu poate fi măsurat tehnic în PDAC.","PD-L1 15 % beweist automatisch TMB-high.":"PD-L1 15% demonstrează automat TMB-high.","PD-L1-Expression ist nicht tumoragnostisch gleichbedeutend mit validierter Checkpoint-Sensitivität.":"Expresia PD-L1 nu este tumor-agnostic sinonimă cu sensibilitatea la checkpoint validată.","Wodurch ist ein immune-excluded Muster am besten charakterisiert?":"Ce caracterizează cel mai bine un pattern immune-excluded?","Immunzellen sind vorhanden, bleiben aber überwiegend im Stroma/peritumoral und erreichen Tumorzellnester nur schlecht.":"Celulele imune sunt prezente, dar rămân predominant în stroma/peritumoral și ajung slab la cuiburile tumorale.","Dichtes intraepitheliales CD8-Infiltrat in allen Tumorarealen.":"Infiltrat CD8 intraepitelial dens în toate zonele tumorale.","Jeder immune-excluded Tumor ist automatisch MSI-H.":"Orice tumoră immune-excluded este automat MSI-H.","PD-L1-Expression allein definiert immune exclusion.":"Expresia PD-L1 singură definește immune exclusion.","Die räumliche Verteilung der Immunzellen ist zentral; 'vorhanden' ist nicht gleich 'im Tumor wirksam'.":"Distribuția spațială a celulelor imune este centrală; «prezent» nu este același lucru cu «eficient în tumoră».","Welche Zusatzdiagnostik sollte für die klinische IO-Frage priorisiert werden?":"Ce diagnostic suplimentar trebuie prioritizat pentru întrebarea clinică IO?","MMR/MSI und ggf. TMB als etabliertere Biomarker; TME-IHC nur ergänzend/mechanistisch.":"MMR/MSI și, după caz, TMB ca biomarkeri mai consacrați; IHC TME doar complementar/mecanistic.","Nur CAF-/Stroma-IHC, da diese allein die Therapie festlegt.":"Doar IHC CAF/stromală, deoarece aceasta singură stabilește terapia.","PD-L1 mehrfach wiederholen, bis ein höherer Wert entsteht.":"Repetă PD-L1 până se obține o valoare mai mare.","Keine weitere Kontextdiagnostik; TPS 15 % reicht.":"Fără alte teste de context; TPS 15% este suficient.","Explorative TME-Marker dürfen validierte Biomarker nicht ersetzen.":"Markerii exploratori TME nu trebuie să înlocuiască biomarkerii validați.","Wie darf der desmoplastische/TIL-arme Befund im MTB verwendet werden?":"Cum poate fi utilizat în MTB rezultatul desmoplazic/sărac în TIL?","Als biologische Erklärung für geringe Checkpoint-Sensitivität bzw. immune exclusion – nicht als eigenständiger validierter Therapieausschlusstest.":"Ca explicație biologică pentru sensibilitate redusă la checkpoint sau immune exclusion – nu ca test independent validat de excludere terapeutică.","Als absolute Kontraindikation gegen jede Immuntherapie.":"Ca o contraindicație absolută pentru orice imunoterapie.","Als Beweis für einen zugelassenen CAF-Target-Standard.":"Ca dovadă pentru un standard aprobat de targetare CAF.","Morphologie und TIL-Verteilung sind grundsätzlich bedeutungslos.":"Morfologia și distribuția TIL sunt în principiu lipsite de semnificație.","Der TME-Befund ist mechanistisch stark, klinisch aber nicht als alleiniger Selektionsassay validiert.":"Rezultatul TME este mecanistic puternic, dar nu este validat clinic ca test unic de selecție.","Formulieren Sie die MTB-Kernaussage so, dass PD-L1, pMMR/MSS/TMB und das immune-excluded/desmoplastische Muster hierarchisch korrekt integriert werden, ohne explorative TME-Befunde zu einem Companion Diagnostic aufzuwerten.":"Formulați concluzia centrală MTB astfel încât PD-L1, pMMR/MSS/TMB și patternul immune-excluded/desmoplazic să fie integrate în ierarhia corectă, fără a ridica rezultatele exploratorii TME la rang de companion diagnostic.","PD-L1 TPS 15 % als realen, aber nicht ausreichenden Einzelbefund anerkennen.":"Recunoaște PD-L1 TPS 15% ca rezultat real, dar insuficient singur.","MMR/MSI prüfen: pMMR/MSS.":"Evaluează MMR/MSI: pMMR/MSS.","TMB als niedrig einordnen.":"Încadrează TMB ca scăzut.","Räumlich spärliches CD8-Infiltrat und Desmoplasie als immune-excluded TME beschreiben.":"Descrie infiltratul CD8 spațial rar și desmoplazia ca TME immune-excluded.","PD-1-Monotherapie nicht allein aus PD-L1 ableiten.":"Nu deduce monoterapie PD-1 doar din PD-L1.","TME-IHC als mechanistische Zusatzinformation, nicht als validierten Selektionsmarker berichten.":"Raportează IHC TME ca informație mecanistică suplimentară, nu ca marker de selecție validat.","MMR-IHC plus MSI-Test und TMB aus einem validierten breiteren Panel, sofern Material und TAT dies erlauben.":"IHC MMR plus test MSI și TMB dintr-un panel validat mai larg, dacă materialul și TAT permit.","Auf zusätzliche Stroma-IHC verzichten, wenn die Morphologie die immune exclusion bereits überzeugend zeigt und die klinisch validierten Biomarker priorisiert werden.":"Renunță la IHC stromală suplimentară dacă morfologia demonstrează deja convingător immune exclusion și sunt prioritizați biomarkerii validați clinic.","PD-L1 = ICI":"PD-L1 = ICI","Die prädiktive Bedeutung von PD-L1 ist entitäts- und therapiespezifisch.":"Semnificația predictivă a PD-L1 este specifică entității și terapiei.","CAF-IHC als Companion Diagnostic":"IHC CAF ca companion diagnostic","Mechanistische TME-Marker sind hier nicht als eigenständige Therapie-Selektion validiert.":"Markerii TME mecanistici nu sunt validați aici ca instrumente independente de selecție terapeutică.","TIL-arm = absolute Resistenz":"TIL-redus = rezistență absolută","Biologische Wahrscheinlichkeit ist keine absolute patientenindividuelle Ausschlussregel.":"Probabilitatea biologică nu este o regulă absolută de excludere la nivel individual.","TMB/MSI ignorieren":"Ignoră TMB/MSI","Damit würden etabliertere immunonkologische Biomarker ausgelassen.":"Astfel ar fi omiși biomarkeri imunooncologici mai consacrați.","Der 'positive' Marker sitzt auf einem biologisch kalten Tumor":"Markerul «pozitiv» se află pe un tumor biologic rece","PD-L1 TPS 15 % wird bestätigt – gleichzeitig ist der Tumor pMMR/MSS, TMB-low und zeigt nur wenige CD8-T-Zellen, die überwiegend im desmoplastischen Stroma stecken bleiben. Der vermeintlich positive Einzelmarker kippt dadurch nicht ins 'falsch', sondern bekommt die richtige Hierarchie: biologischer Kontextmarker statt Therapie-Schalter.":"PD-L1 TPS 15% este confirmat – în același timp tumora este pMMR/MSS, TMB-low și prezintă doar câteva celule T CD8 care rămân în mare parte captive în stroma desmoplazică. Markerul unic aparent pozitiv nu devine «greșit», ci primește ierarhia corectă: marker de context biologic, nu comutator terapeutic.","Der Fall trennt Expression eines Checkpoints von einer vorhandenen effektiven Antitumor-Immunantwort und zeigt, warum räumliche TME-Biologie die Interpretation verändert.":"Cazul separă expresia checkpoint de existența unui răspuns imun antitumoral eficient și arată de ce biologia spațială TME schimbă interpretarea.","PD-L1 im richtigen TME-Kontext":"PD-L1 în contextul TME corect","PD-L1 TPS 15 %, pMMR/MSS, TMB 3,2 Mut/Mb, CD8-arm/immune-excluded mit ausgeprägter Desmoplasie. Kein belastbarer Grund für PD-1-Monotherapie allein aus PD-L1; TME-Befund mechanistisch, nicht als Companion Diagnostic.":"PD-L1 TPS 15%, pMMR/MSS, TMB 3,2 Mut/Mb, CD8-sărac/immune-excluded cu desmoplazie marcată. Fără bază solidă pentru monoterapie PD-1 doar din PD-L1; rezultatul TME este mecanistic, nu companion diagnostic.","Validierte Biomarker und TME-Biologie korrekt hierarchisiert.":"Biomarkerii validați și biologia TME ierarhizate corect.","Cold erkannt, Biomarkerhierarchie unklar":"Pattern rece recunoscut, ierarhia biomarkerilor neclară","Desmoplasie und wenige TILs werden beschrieben, MMR/MSI/TMB aber nicht integriert.":"Desmoplazia și puținii TIL sunt descriși, dar MMR/MSI/TMB nu sunt integrate.","Biologisch plausibel, klinisch unvollständig.":"Biologic plauzibil, clinic incomplet.","PD-L1 als universeller IO-Schalter":"PD-L1 ca comutator universal IO","TPS 15 % wird als ausreichende tumoragnostische ICI-Indikation interpretiert.":"TPS 15% este interpretat ca indicație ICI tumor-agnostică suficientă.","Entitätsspezifische Biomarkerlogik übergangen.":"Logica biomarkerilor specifică entității este ignorată.","pMMR/MSS und TMB-low bestätigt":"pMMR/MSS și TMB-low confirmate","Therapieplanung auf etablierte PDAC-Strategien bzw. passende Studien fokussieren; PD-L1 nicht isoliert übergewichten.":"Focalizează planificarea terapeutică pe strategii PDAC consacrate sau studii adecvate; nu supraevalua PD-L1 izolat.","Der Fall bleibt evidenzbasiert statt biomarkergetrieben spekulativ.":"Cazul rămâne bazat pe dovezi, nu speculativ și condus de biomarker.","TME-/Stromaforschung diskutiert":"Cercetare TME/stromală discutată","Studienoptionen klar als experimentell kennzeichnen.":"Etichetează clar opțiunile de studiu ca experimentale.","Mechanistische Hypothesen werden von Routineempfehlungen getrennt.":"Ipotezele mecanistice sunt separate de recomandările de rutină.","PD-L1-Expression ist nicht gleichbedeutend mit vorhandener effektiver T-Zell-Antwort.":"Expresia PD-L1 nu este sinonimă cu existența unui răspuns eficient al celulelor T.","Immune exclusion beschreibt die räumliche Barriere zwischen Immunzellen und Tumorzellnestern.":"Immune exclusion descrie bariera spațială dintre celulele imune și cuiburile tumorale.","pMMR/MSS und niedrige TMB liefern hier keine starken etablierten Immunogenitätssignale.":"pMMR/MSS și TMB scăzut nu oferă aici semnale puternice consacrate de imunogenicitate.","TME-/CAF-/TIL-Marker können Mechanismen erklären, sind aber nicht automatisch validierte Therapie-Selektionstests.":"Markerii TME/CAF/TIL pot explica mecanisme, dar nu sunt automat teste validate de selecție terapeutică.","Der klinische Wert eines Biomarkers hängt von Entität, Therapie und Evidenzniveau ab.":"Valoarea clinică a unui biomarker depinde de entitate, terapie și nivelul dovezilor.","PD-L1 TPS 15 % ist kein ausreichender Monotherapie-Schalter. Der Tumor ist pMMR/MSS und TMB-low; morphologisch/IHC zeigt sich ein deutlich immune-excluded, desmoplastisches TME. Das erklärt biologisch eine geringe Wahrscheinlichkeit effektiver Checkpoint-Reaktivierung, darf aber nicht als absoluter Ausschlusstest oder validierter Companion Diagnostic formuliert werden.":"PD-L1 TPS 15% nu este un comutator suficient pentru monoterapie. Tumora este pMMR/MSS și TMB-low; morfologic/IHC există un TME clar immune-excluded, desmoplazic. Aceasta explică biologic o probabilitate redusă de reactivare eficientă a checkpointului, dar nu trebuie formulată ca test absolut de excludere sau companion diagnostic validat.","PD-L1 nicht überinterpretiert":"PD-L1 nesuprainterpretat","MMR/MSI/TMB priorisiert":"MMR/MSI/TMB prioritizate","immune-excluded räumlich verstanden":"immune-excluded înțeles spațial","TME-Marker als explorativ begrenzt":"Markerii TME limitați ca exploratori","Warum kann PD-L1 exprimiert sein, obwohl kaum T-Zellen im Tumor sitzen?":"De ce poate fi exprimat PD-L1 chiar dacă aproape nu există celule T în interiorul tumorii?","Was unterscheidet immune-desert von immune-excluded?":"Ce diferențiază immune-desert de immune-excluded?","Welche TME-Marker sind mechanistisch interessant, aber nicht routineprädiktiv validiert?":"Ce markeri TME sunt interesanți mecanistic, dar nu validați predictiv de rutină?","PD-L1 positiv, aber pMMR/MSS/TMB-low + immune-excluded":"PD-L1 pozitiv, dar pMMR/MSS/TMB-low + immune-excluded","Checkpoint-Expression braucht einen validierten Entitäts- und Immunitätskontext":"Expresia checkpoint necesită un context validat de entitate și imunitate","PD-L1 → MMR/MSI/TMB → räumliche TILs → TME-Limitation":"PD-L1 → MMR/MSI/TMB → TIL spațiali → limitarea TME","PD-L1 positiv, aber niedrige TMB und kein Immuninfiltrat → PD-L1 nicht überinterpretieren":"PD-L1 pozitiv, dar TMB scăzut și fără infiltrat imun → nu suprainterpreta PD-L1","PD-L1 positiv, aber niedrige TMB u…":"PD-L1 pozitiv, dar TMB scăzut ș…","61-jährige Patientin mit metastasiertem kolorektalem Adenokarzinom nach Progress unter mehreren Standardtherapien. In einer Metastasenbiopsie wird PD-L1 CPS 25 berichtet.":"Pacientă de 61 de ani cu adenocarcinom colorectal metastatic după progresie sub mai multe terapii standard. Într-o biopsie metastatică se raportează PD-L1 CPS 25.","Kann die hohe PD-L1-Expression trotz fehlender klassischer Immunogenitätsmarker eine PD-1-Monotherapie begründen?":"Poate expresia PD-L1 ridicată să justifice monoterapia PD-1 în ciuda absenței markerilor clasici de imunogenicitate?","Es wird nach einer weiteren systemischen Option gesucht; Studienzugang wird parallel geprüft.":"Se caută o altă opțiune sistemică; accesul la studii este evaluat în paralel.","Primarius":"Tumoră primară","Linksseitiges Kolonkarzinom, inzwischen hepatisch und pulmonal metastasiert.":"Cancer de colon stâng, acum metastatic hepatic și pulmonar.","Fluoropyrimidin/Oxaliplatin, Irinotecan-basierte Therapie und weitere leitliniengerechte Linien.":"Fluoropirimidină/oxaliplatin, terapie pe bază de irinotecan și alte linii conforme ghidurilor.","Außenbefund":"Raport extern","PD-L1 CPS 25 wird auf dem Deckblatt fett hervorgehoben.":"PD-L1 CPS 25 este evidențiat cu caractere îngroșate pe pagina de gardă.","Ein 'positiver' Marker wird aus einer anderen Tumorentität in den CRC-Kontext übertragen, obwohl die prädiktive Hierarchie dort anders ist.":"Un marker «pozitiv» este transferat dintr-o altă entitate tumorală în contextul CRC, deși ierarhia predictivă este diferită.","Kolorektales Adenokarzinom, mäßig differenziert; keine ausgeprägt lymphozytenreiche Morphologie.":"Adenocarcinom colorectal moderat diferențiat; fără morfologie marcat bogată în limfocite.","CPS 25, überwiegend durch PD-L1-positive Immunzellen an Nekrose-/Stromagrenzen mitgetragen.":"CPS 25, susținut predominant de celule imune PD-L1-pozitive la interfețele necroză/stromă.","Nur spärliche intratumorale CD8-positive Lymphozyten.":"Doar limfocite CD8-pozitive intratumorale rare.","MMR/MSI und TMB als entitätsspezifisch relevanter immunonkologischer Kontext.":"MMR/MSI și TMB ca context imunooncologic relevant entității.","FFPE-Lebermetastase, Block H2.":"Metastază hepatică FFPE, bloc H2.","ca. 50 %, gut geeignet.":"aprox. 50%, bine adecvat.","PD-L1 ist technisch messbar, seine prädiktive Bedeutung ist aber entitäts- und therapiespezifisch; ein numerisch hoher Score ist nicht automatisch ein universeller IO-Biomarker.":"PD-L1 este tehnic măsurabil, dar semnificația sa predictivă este specifică entității și terapiei; un scor numeric ridicat nu este automat un biomarker IO universal.","Immunonkologischer Kontext":"Context imunooncologic","Erhaltene nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expresie nucleară păstrată MLH1, PMS2, MSH2 și MSH6: pMMR.","MSS. Damit fehlt der für mCRC etablierte dMMR/MSI-H-Immuntherapiekontext.":"MSS. Astfel lipsește contextul dMMR/MSI-H de imunoterapie consacrat pentru mCRC.","TMB niedrig (4,0 Mut/Mb).":"TMB scăzut (4,0 Mut/Mb).","PD-L1 CPS 25 bestätigt. Die Expression ist biologisch real, aber im pMMR/MSS-mCRC kein Ersatz für einen validierten MSI/dMMR-basierten Selektionsmarker.":"PD-L1 CPS 25 confirmat. Expresia este biologic reală, dar în mCRC pMMR/MSS nu înlocuiește un marker de selecție validat bazat pe MSI/dMMR.","TIL-Kontext":"Context TIL","Nur wenige intratumorale CD8-positive T-Zellen; kein ausgeprägt inflamed/hot pattern.":"Doar câteva celule T CD8-pozitive intratumorale; fără pattern inflamed/hot pronunțat.","Kernausgangslage":"Situație de bază","PD-L1 CPS 25 bei mCRC ohne morphologisch ausgeprägtes Immuninfiltrat.":"PD-L1 CPS 25 în mCRC fără infiltrat imun morfologic pronunțat.","MMR-IHC, MSI und DNA-basierte Zusatzanalysen technisch verwertbar.":"IHC MMR, MSI și analize suplimentare bazate pe ADN sunt tehnic utilizabile.","Metastasiertes CRC mit realer PD-L1-Expression, aber pMMR/MSS, niedriger TMB und spärlichem intratumoralem T-Zell-Infiltrat. PD-L1-Positivität allein begründet in diesem Kontext keine etablierte PD-1-Monotherapie. Für mCRC besitzt dMMR/MSI-H eine deutlich stärkere und validierte prädiktive Rolle; experimentelle Kombinationen bei pMMR/MSS gehören in einen Studien-/Evidenzkontext.":"CRC metastatic cu expresie PD-L1 reală, dar pMMR/MSS, TMB scăzut și infiltrat intratumoral rar de celule T. Pozitivitatea PD-L1 singură nu fundamentează în acest context o monoterapie PD-1 consacrată. În mCRC, dMMR/MSI-H are un rol predictiv mult mai puternic și validat; combinațiile experimentale în pMMR/MSS aparțin contextului de studiu/dovezi.","Teilbefund: PD-L1 ist hoch, aber ohne MMR/MSI-Kontext ist die Übertragbarkeit auf eine Therapieentscheidung nicht belastbar.":"Rezultat parțial: PD-L1 este ridicat, dar fără context MMR/MSI transferabilitatea către o decizie terapeutică nu este solidă.","PD-L1-Bedeutung entitätsspezifisch einordnen":"Interpretează semnificația PD-L1 specific entității","pMMR/MSS als entscheidenden Gegenbefund zur einfachen PD-L1-Logik benennen":"Menționează pMMR/MSS ca rezultat decisiv împotriva logicii simple PD-L1","niedrige TMB und spärliches Infiltrat als zusätzliche Kontextmarker integrieren":"Integrează TMB scăzut și infiltratul rar ca markeri suplimentari de context","pMMR/MSS-IO-Kombinationen nicht mit etablierter Monotherapie gleichsetzen":"Nu echivala combinațiile IO în pMMR/MSS cu monoterapia consacrată","Falschaussage: Hoher PD-L1-Score ist tumoragnostisch immer prädiktiv":"Afirmație falsă: un scor PD-L1 ridicat este întotdeauna predictiv tumor-agnostic","Optimale Lösung: PD-L1 CPS 25 ist kein universeller IO-Schalter. Im pMMR/MSS-mCRC mit niedriger TMB und wenig TILs darf der Score die entitätsspezifisch validierte Biomarkerhierarchie nicht überstimmen; experimentelle Strategien gehören in Studien.":"Soluție optimă: PD-L1 CPS 25 nu este un comutator IO universal. În mCRC pMMR/MSS cu TMB scăzut și puțini TIL, scorul nu trebuie să suprascrie ierarhia biomarkerilor validată specific entității; strategiile experimentale aparțin studiilor.","TIL-low":"TIL-low","Immuntherapie":"Imunoterapie","Biomarkerhierarchie":"Ierarhia biomarkerilor","PD-L1 CPS 25 und trotzdem kein ICI-Biomarker: MSS-mCRC als Überinterpretationsfalle":"PD-L1 CPS 25 și totuși fără biomarker ICI: mCRC MSS ca capcană de suprainterpretare","PD-L1 als entitätsabhängigen und nicht tumoragnostischen Biomarker verstehen.":"Înțelege PD-L1 ca biomarker dependent de entitate și nu tumor-agnostic.","Beim mCRC dMMR/MSI-H gegenüber PD-L1 als prädiktiv stärker validierten IO-Kontext priorisieren.":"În mCRC, prioritizează dMMR/MSI-H față de PD-L1 ca context IO predictiv mai solid validat.","pMMR/MSS, niedrige TMB und TIL-Armut als konsistente Gegenkonstellation zu einer simplen PD-L1-Logik integrieren.":"Integrează pMMR/MSS, TMB scăzut și deficitul TIL ca o configurație coerentă împotriva logicii simple PD-L1.","PD-L1-Score und zelluläre Quelle/Spatial Context nicht mit universeller Therapieindikation verwechseln.":"Nu confunda scorul PD-L1 și sursa celulară/contextul spațial cu o indicație terapeutică universală.","Experimentelle ICI-Kombinationen im pMMR/MSS-mCRC von etablierter Monotherapie unterscheiden.":"Distinge combinațiile ICI experimentale în mCRC pMMR/MSS de monoterapia consacrată.","Der Außenbefund klingt spektakulär: PD-L1 CPS 25. Im Tumorboard kommt sofort die Frage nach Pembrolizumab. Doch die Histologie ist lymphozytenarm, die MMR-Proteine sind erhalten und der Tumor ist MSS. Der Fall ist ein Lehrstück dafür, dass derselbe Biomarkerwert je nach Tumorentität völlig unterschiedliche klinische Bedeutung haben kann.":"Raportul extern sună spectaculos: PD-L1 CPS 25. În Tumor Board se ridică imediat problema pembrolizumab. Dar histologia este săracă în limfocite, proteinele MMR sunt păstrate și tumora este MSS. Cazul este o lecție că aceeași valoare de biomarker poate avea semnificație clinică complet diferită în funcție de entitatea tumorală.","61-jährige Patientin mit mehrfach vorbehandeltem metastasiertem kolorektalem Adenokarzinom. Eine Metastasenbiopsie zeigt PD-L1 CPS 25. Gesucht ist eine evidenzbasierte Einordnung, ob dieser Wert im pMMR/MSS-mCRC eine etablierte PD-1-Monotherapie begründet oder ob die entitätsspezifische MSI/dMMR-Hierarchie Vorrang hat.":"Pacientă de 61 de ani cu adenocarcinom colorectal metastatic multiplu tratat. O biopsie metastatică arată PD-L1 CPS 25. Se cere o evaluare bazată pe dovezi dacă această valoare susține monoterapia PD-1 consacrată în mCRC pMMR/MSS sau dacă ierarhia MSI/dMMR specifică entității are prioritate.","Hohe Zahl, falsche Abkürzung":"Număr mare, scurtătură greșită","PD-L1 CPS 25 wird als 'positiv' hervorgehoben.":"PD-L1 CPS 25 este evidențiat ca «pozitiv».","Ein numerisch hoher Wert ist nur dann prädiktiv, wenn Assay, Scoring, Entität und Therapie dafür validiert sind.":"O valoare numeric ridicată este predictivă doar dacă assay-ul, scoringul, entitatea și terapia sunt validate pentru acea utilizare.","CRC-spezifische Hierarchie":"Ierarhie specifică CRC","MMR/MSI ist für die IO-Selektion beim mCRC zentral.":"MMR/MSI este central pentru selecția IO în mCRC.","Biomarker dürfen nicht entitätsübergreifend ohne Evidenz transferiert werden.":"Biomarkerii nu trebuie transferați între entități fără dovezi.","Biologisches Gesamtbild":"Imagine biologică globală","TMB-low und TIL-arm.":"TMB-low și TIL-sărac.","Mehrere unabhängige Kontextsignale sprechen gegen die einfache Annahme eines hoch immunogenen Tumors.":"Mai multe semnale independente de context contrazic presupunerea simplă a unei tumori foarte imunogene.","PD-L1 Außenbefund":"Rezultat extern PD-L1","CPS 25, überwiegend an Tumor-/Stromagrenzen und Immunzellen.":"CPS 25, predominant la interfețe tumoră/stromă și pe celule imune.","Keine ausgeprägt lymphozytenreiche CRC-Morphologie.":"Fără morfologie CRC marcat bogată în limfocite.","Lebermetastase mit ca. 50 % Tumoranteil.":"Metastază hepatică cu aprox. 50% conținut tumoral.","MMR-IHC und MSI-Testung sind mit wenig Material möglich und beantworten die entscheidende CRC-spezifische Frage direkter als wiederholte PD-L1-IHC.":"IHC MMR și testarea MSI necesită puțin material și răspund mai direct întrebării decisive specifice CRC decât repetarea IHC PD-L1.","TMB ist additive Kontextinformation und darf MSI/dMMR nicht ersetzen.":"TMB este informație contextuală aditivă și nu trebuie să înlocuiască MSI/dMMR.","Breite Zusatzdiagnostik soll nicht nur deshalb erfolgen, weil ein einzelner PD-L1-Score klinisch verlockend wirkt.":"Testarea suplimentară largă nu trebuie efectuată doar pentru că un singur scor PD-L1 pare clinic tentant.","Wie ist PD-L1 CPS 25 im mCRC grundsätzlich zu behandeln?":"Cum trebuie tratat în general PD-L1 CPS 25 în mCRC?","Als entitätsspezifisch zu interpretierender Kontextbefund; nicht als universeller tumoragnostischer ICI-Schalter.":"Ca rezultat de context ce trebuie interpretat specific entității; nu ca un comutator ICI universal tumor-agnostic.","CPS ≥10 ist bei jeder soliden Tumorentität automatisch prädiktiv.":"CPS ≥10 este automat predictiv în orice entitate tumorală solidă.","PD-L1-IHC ist im CRC technisch grundsätzlich ungültig.":"IHC PD-L1 este tehnic invalidă în CRC din principiu.","PD-L1 CPS 25 beweist MSI-H.":"PD-L1 CPS 25 demonstrează MSI-H.","Prädiktive Biomarker funktionieren nur in validiertem Entitäts-/Therapiekontext.":"Biomarkerii predictivi funcționează doar într-un context validat de entitate/terapie.","Welcher Befund besitzt beim mCRC die klarere etablierte IO-Relevanz?":"Ce rezultat are relevanța IO consacrată mai clară în mCRC?","dMMR/MSI-H.":"dMMR/MSI-H.","PD-L1 CPS allein.":"Doar PD-L1 CPS.","TIL-Zahl allein.":"Doar numărul de TIL.","Tumornekrose allein.":"Doar necroza tumorală.","dMMR/MSI-H ist der etablierte zentrale Immuntherapie-Biomarkerkontext im mCRC.":"dMMR/MSI-H reprezintă contextul central consacrat al biomarkerilor pentru imunoterapie în mCRC.","PD-L1 CPS 25, aber pMMR/MSS und TMB 4 Mut/Mb. Was ist die sauberste Aussage?":"PD-L1 CPS 25, dar pMMR/MSS și TMB 4 mut/Mb. Care este formularea cea mai corectă?","PD-L1 überstimmt pMMR/MSS nicht; daraus folgt keine etablierte PD-1-Monotherapie. Studienstrategien müssen als experimentell gekennzeichnet werden.":"PD-L1 nu prevalează asupra pMMR/MSS; de aici nu rezultă o indicație consacrată pentru monoterapia anti-PD-1. Strategiile din studii trebuie marcate ca experimentale.","Hoher CPS macht die Monotherapie unabhängig von MSI zum Standard.":"Un CPS crescut face din monoterapie standardul, indiferent de MSI.","Ein pMMR/MSS-CRC kann in keiner Studie jemals auf Immuntherapie reagieren.":"Un CRC pMMR/MSS nu poate răspunde niciodată la imunoterapie în niciun studiu.","CPS 25 definiert automatisch TMB-high.":"CPS 25 definește automat TMB-high.","Fehlende etablierte Monotherapie-Indikation ist nicht gleichbedeutend mit biologisch unmöglicher Aktivität in Studienkombinationen.":"Absența unei indicații consacrate pentru monoterapie nu înseamnă că activitatea în combinații investigate este biologic imposibilă.","Warum ist es hilfreich zu wissen, woher der CPS stammt?":"De ce este util să știm din ce tip de celule provine CPS?","PD-L1-positive Immunzellen an Stromagrenzen können den Score erhöhen, ohne ein dichtes intratumorales Effektor-T-Zell-Infiltrat zu belegen.":"Celulele imune PD-L1-pozitive de la limitele stromale pot crește scorul fără a demonstra un infiltrat dens intratumoral de celule T efectoare.","Immunzell-PD-L1 beweist immer bessere ICI-Wirkung.":"PD-L1 pe celulele imune dovedește întotdeauna o eficacitate mai bună a ICI.","CPS darf Immunzellen niemals berücksichtigen.":"CPS nu trebuie să includă niciodată celulele imune.","Zelluläre Quelle und räumlicher Kontext sind grundsätzlich irrelevant.":"Sursa celulară și contextul spațial sunt fundamental irelevante.","Score und räumliche Immunbiologie sind unterschiedliche Informationsebenen.":"Scorul și biologia imună spațială reprezintă niveluri diferite de informație.","Entscheiden Sie, wie PD-L1 CPS 25 im pMMR/MSS-mCRC berichtet und im MTB gewichtet wird, ohne den Befund zu ignorieren oder ihn entitätsfremd zur etablierten ICI-Indikation aufzuwerten.":"Decideți cum trebuie raportat și ponderat în MTB un PD-L1 CPS 25 într-un mCRC pMMR/MSS, fără a ignora rezultatul și fără a-l ridica, în afara contextului validat al entității, la rangul unei indicații consacrate pentru ICI.","PD-L1 CPS 25 als technisch realen Befund anerkennen.":"Recunoașteți PD-L1 CPS 25 ca rezultat tehnic real.","MMR-IHC und MSI prüfen: pMMR/MSS.":"Verificați IHC MMR și MSI: pMMR/MSS.","TMB als niedrig und TIL-Infiltrat als spärlich einordnen.":"Încadrați TMB ca scăzut și infiltratul TIL ca redus.","PD-L1 im CRC nicht als tumoragnostischen Therapie-Schalter formulieren.":"Nu formulați PD-L1 în CRC ca pe un comutator terapeutic tumor-agnostic.","Keine etablierte PD-1-Monotherapie aus PD-L1 allein ableiten.":"Nu deduceți o indicație consacrată pentru monoterapia anti-PD-1 numai din PD-L1.","Experimentelle pMMR/MSS-IO-Kombinationen ausschließlich als Studienoption/Evidenzentwicklung kennzeichnen.":"Etichetați combinațiile experimentale de imunoterapie în pMMR/MSS exclusiv ca opțiuni de studiu/evidență în evoluție.","MMR-IHC plus MSI-Test; TMB nur ergänzend, wenn bereits aus validiertem Panel verfügbar.":"IHC MMR plus testare MSI; TMB doar ca informație suplimentară dacă este deja disponibil dintr-un panel validat.","Bei klarem pMMR/MSS kann auf wiederholte PD-L1-IHC verzichtet werden, wenn sie die klinische Entscheidung nicht verändert.":"În cazul unui pMMR/MSS clar stabilit, repetarea IHC PD-L1 poate fi omisă dacă nu modifică decizia clinică.","CPS aus anderer Entität übertragen":"Transferați CPS dintr-o altă entitate tumorală","PD-L1-Cutoffs sind nicht tumoragnostisch austauschbar.":"Pragurile PD-L1 nu sunt interschimbabile între entitățile tumorale.","PD-L1 ignorieren":"Ignorați PD-L1","Der Befund ist biologisch real und kann Forschung/Studienkontext informieren; er ist nur nicht der etablierte Selektionsmarker.":"Rezultatul este biologic real și poate informa contextul de cercetare/studii; pur și simplu nu este biomarkerul de selecție consacrat.","pMMR/MSS = absolute Immunresistenz":"pMMR/MSS = rezistență imună absolută","Das wäre zu absolut; Studienkombinationen werden untersucht.":"Această afirmație ar fi prea absolută; sunt investigate combinații experimentale.","TMB ersetzt MSI":"TMB înlocuiește MSI","TMB und MSI sind verwandte, aber nicht austauschbare Biomarker.":"TMB și MSI sunt biomarkeri înrudiți, dar nu interschimbabili.","Die 25 ist echt – aber klinisch nicht der Hauptmarker":"Valoarea 25 este reală — dar clinic nu este markerul principal","PD-L1 CPS 25 wird bestätigt. Gleichzeitig zeigen MMR-IHC und MSI-Testung pMMR/MSS, TMB liegt bei 4 Mut/Mb und CD8-T-Zellen sind spärlich. Der Twist ist nicht, dass PD-L1 'falsch' war, sondern dass ein realer positiver Befund außerhalb seines validierten Entitätskontexts therapeutisch viel weniger trägt.":"PD-L1 CPS 25 este confirmat. În același timp, IHC MMR și testarea MSI arată pMMR/MSS, TMB este 4 mut/Mb, iar celulele T CD8 sunt rare. Twist-ul nu este că PD-L1 a fost «greșit», ci că un rezultat cu adevărat pozitiv are o greutate terapeutică mult mai mică în afara contextului validat specific entității.","So wird die zentrale Präzisionsonkologie-Kompetenz trainiert: Biomarker werden nicht nach Positiv/Negativ, sondern nach Evidenz, Entität und Therapiehierarchie interpretiert.":"Astfel este antrenată o competență centrală în oncologia de precizie: biomarkerii nu sunt interpretați doar ca pozitiv/negativ, ci în funcție de dovezi, entitate și ierarhia terapeutică.","PD-L1 entitätsspezifisch begrenzt":"PD-L1 limitat de contextul specific entității","PD-L1 CPS 25, pMMR/MSS, TMB 4 Mut/Mb, TIL-arm. Keine etablierte PD-1-Monotherapie aus PD-L1 allein; dMMR/MSI-H wäre der relevante validierte IO-Kontext. Studienkombinationen klar als experimentell kennzeichnen.":"PD-L1 CPS 25, pMMR/MSS, TMB 4 mut/Mb, TIL puține. Fără monoterapie anti-PD-1 consacrată pe baza PD-L1 singur; dMMR/MSI-H ar reprezenta contextul ICI validat relevant. Combinațiile din studii trebuie marcate clar ca experimentale.","Biomarkerhierarchie sauber getroffen.":"Ierarhia biomarkerilor a fost identificată corect.","MSS erkannt, PD-L1 aber nicht eingeordnet":"MSS recunoscut, dar PD-L1 necontextualizat","pMMR/MSS wird berichtet, der hohe CPS bleibt ohne Erklärung im Raum.":"pMMR/MSS este raportat, dar CPS crescut rămâne fără explicație.","Der wichtigste Lernkonflikt wird nicht aufgelöst.":"Conflictul didactic principal rămâne nerezolvat.","CPS 25 = Pembrolizumab":"CPS 25 = pembrolizumab","PD-L1 wird entitätsübergreifend als Standardindikation interpretiert.":"PD-L1 este interpretat între entități tumorale ca indicație standard.","Validierungskontext missachtet.":"Contextul de validare este ignorat.","Nicht-MSI-basierte Routineoptionen und geeignete klinische Studien prüfen.":"Evaluați opțiunile de rutină care nu se bazează pe MSI și studiile clinice adecvate.","Experimentelle Immuntherapiestrategien bleiben möglich, aber werden nicht als etablierte Monotherapie verkauft.":"Strategiile experimentale de imunoterapie rămân posibile, dar nu trebuie prezentate ca monoterapie consacrată.","PD-L1 ist kein tumoragnostischer Biomarker.":"PD-L1 nu este un biomarker tumor-agnostic.","Im mCRC hat dMMR/MSI-H eine zentrale etablierte prädiktive Rolle für Checkpoint-Inhibition.":"În mCRC, dMMR/MSI-H are un rol predictiv central și consacrat pentru inhibarea checkpoint-urilor imune.","pMMR/MSS und niedrige TMB/TILs relativieren die intuitive Interpretation eines hohen PD-L1-Scores.":"pMMR/MSS și TMB/TIL scăzute temperează interpretarea intuitivă a unui scor PD-L1 crescut.","Ein positiver Labormarker kann korrekt gemessen und trotzdem klinisch nicht entscheidend sein.":"Un marker de laborator pozitiv poate fi măsurat corect și totuși să nu fie decisiv clinic.","Studienevidenz bei pMMR/MSS darf nicht mit Routine-Standard gleichgesetzt werden.":"Dovezile din studii pentru pMMR/MSS nu trebuie echivalate cu standardul de rutină.","PD-L1 CPS 25 ist ein realer Kontextbefund, aber im pMMR/MSS-mCRC kein etablierter Ersatz für dMMR/MSI-H. TMB ist niedrig, TILs spärlich. Daher keine etablierte PD-1-Monotherapie allein aus dem CPS ableiten; Studienkombinationen nur als experimentelle Optionen kommunizieren.":"PD-L1 CPS 25 este un rezultat contextual real, dar în mCRC pMMR/MSS nu reprezintă un substitut consacrat pentru dMMR/MSI-H. TMB este scăzut, iar TIL sunt puține. Prin urmare, nu deduceți monoterapia anti-PD-1 consacrată doar din CPS; combinațiile din studii trebuie comunicate numai ca opțiuni experimentale.","Entitätsspezifität":"Specificitatea entității","MMR/MSI priorisiert":"MMR/MSI prioritizat","PD-L1 nicht ignoriert, aber begrenzt":"PD-L1 nu este ignorat, dar este limitat corespunzător","Studie vs. Standard getrennt":"Studiul și standardul sunt diferențiate","Warum kann derselbe PD-L1-Score in zwei Tumorentitäten unterschiedliche Bedeutung besitzen?":"De ce poate același scor PD-L1 să aibă o semnificație diferită în două entități tumorale?","Welche Biomarker sind tumoragnostisch zugelassen und welche nicht?":"Ce biomarkeri au aprobări tumor-agnostice și care nu?","Wie formuliert man einen 'positiven, aber nicht entscheidenden' Marker verständlich im Befund?":"Cum formulați clar într-un raport un marker «pozitiv, dar nedecisiv»?","PD-L1 CPS 25 wird durch pMMR/MSS/TMB-low relativiert":"PD-L1 CPS 25 este relativizat de pMMR/MSS/TMB-low","Biomarkerpositivität ist ohne Entitätsvalidierung keine Therapieindikation":"Pozitivitatea unui biomarker nu reprezintă o indicație terapeutică fără validare specifică entității","PD-L1 → MMR/MSI → TMB/TIL → Evidenzhierarchie":"PD-L1 → MMR/MSI → TMB/TIL → ierarhia dovezilor","MSI-H-Karzinom: Therapieoption und Lynch-Abklärung → IO, MMR-IHC, Keimbahnkontext":"Carcinom MSI-H: opțiune terapeutică și evaluare Lynch → IO, IHC MMR, context germinal","MSI-H-Karzinom: Therapieoption und…":"Carcinom MSI-H: opțiune terapeutică și…","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und pulmonalen Metastasen. Im Primärtumor war keine strukturierte MMR-/Lynch-Abklärung dokumentiert.":"Pacientă de 49 de ani cu carcinom endometrioid endometrial recidivat și metastaze pulmonare. Pentru tumora primară nu fusese documentată o evaluare structurată MMR/Lynch.","Ist der Tumor dMMR/MSI-H und damit immuntherapeutisch relevant? Welche Reflexdiagnostik ist bei einem MMR-Verlust erforderlich, und wann muss Humangenetik folgen?":"Este tumora dMMR/MSI-H și, prin urmare, relevantă pentru imunoterapie? Ce testare reflexă este necesară în cazul pierderii MMR și când trebuie implicată genetica medicală?","Die molekulare Einordnung soll Therapieplanung und hereditäre Beratung parallel strukturieren.":"Încadrarea moleculară trebuie să structureze în paralel planificarea tratamentului și consilierea ereditară.","Alter":"Vârstă","49 Jahre bei aktueller Rezidivsituation.":"49 de ani la recidiva actuală.","Mutter mit Kolonkarzinom mit 52 Jahren; mütterlicher Onkel mit Urothelkarzinom des oberen Harntrakts.":"Mamă cu cancer colorectal la 52 de ani; unchi matern cu carcinom urotelial al tractului urinar superior.","Außenbefund nennt 'MSI verdächtig', ohne dokumentierte MMR-IHC oder MLH1-Methylierung.":"Raportul extern menționează „suspiciune de MSI”, fără IHC MMR sau metilare MLH1 documentate.","CRC-Reflexdiagnostik wird unverändert auf das Endometriumkarzinom übertragen – insbesondere BRAF-V600E statt MLH1-Promotormethylierung.":"Diagnosticul reflex din CRC este transferat neschimbat la carcinomul endometrial — în special BRAF V600E în locul metilării promotorului MLH1.","Endometrioides Endometriumkarzinom, high-grade, mit fokal lymphozytenreichem Stroma.":"Carcinom endometrioid endometrial high-grade, cu stromă focal bogată în limfocite.","Rezidiv-/Metastasenmaterial bestätigt endometrialen Ursprung.":"Materialul din recidivă/metastază confirmă originea endometrială.","MMR-Proteinmuster, MSI-Status und bei MLH1/PMS2-Verlust die Frage einer sporadischen MLH1-Promotormethylierung.":"Profilul proteinelor MMR, statusul MSI și, în caz de pierdere MLH1/PMS2, întrebarea unei metilări sporadice a promotorului MLH1.","Therapiebiomarker und Lynch-Screening nutzen dieselbe MMR-Biologie, führen aber zu unterschiedlichen nächsten Schritten.":"Biomarkerul terapeutic și screeningul Lynch folosesc aceeași biologie MMR, dar conduc la pași următori diferiți.","FFPE-Resektat des Primärtumors plus aktuelle Metastasenbiopsie.":"Piesă de rezecție FFPE a tumorii primare plus biopsie actuală a unei metastaze.","Primärtumor ca. 60 %, DNA gut geeignet.":"Tumoră primară aproximativ 60 %, ADN adecvat.","Ausreichend für MMR-IHC und molekulare Reflexdiagnostik.":"Suficient pentru IHC MMR și testare moleculară reflexă.","BRAF V600E ist als Lynch-Reflex aus dem CRC-Kontext bekannt, beantwortet beim Endometriumkarzinom aber nicht die entscheidende sporadisch-vs.-hereditär-Frage.":"BRAF V600E este cunoscut ca test reflex Lynch în contextul CRC, dar în carcinomul endometrial nu răspunde la întrebarea esențială sporadic versus ereditar.","MSI-Bestätigung":"Confirmare MSI","MLH1-Reflexdiagnostik":"Testare reflexă MLH1","Hereditäre Weiterleitung":"Trimitere pentru evaluare ereditară","Verlust von MLH1 und PMS2 bei erhaltener Expression von MSH2 und MSH6: dMMR-Muster.":"Pierdere MLH1 și PMS2 cu expresie păstrată MSH2 și MSH6: profil dMMR.","MSI-high, konsistent mit dem dMMR-Befund.":"MSI-high, concordant cu rezultatul dMMR.","MLH1-Promotormethylierung":"Metilarea promotorului MLH1","Keine MLH1-Promotor-Hypermethylierung nachweisbar. Damit ist eine häufige sporadische Ursache des MLH1/PMS2-Verlusts nicht belegt; Lynch-Syndrom bleibt abklärungsbedürftig, ist aber noch nicht bewiesen.":"Nu se detectează hipermetilarea promotorului MLH1. Prin urmare, o cauză sporadică frecventă a pierderii MLH1/PMS2 nu este demonstrată; sindromul Lynch necesită în continuare evaluare, dar nu este încă dovedit.","BRAF-V600E-Testung ist hier kein geeigneter Lynch-Screening-Reflex. Die aus dem CRC bekannte BRAF-Logik darf nicht auf das Endometriumkarzinom übertragen werden.":"Testarea BRAF V600E nu este aici un reflex adecvat pentru screeningul Lynch. Logica BRAF cunoscută din CRC nu trebuie transferată la carcinomul endometrial.","Humangenetische Beratung und Keimbahndiagnostik der MMR/Lynch-relevanten Gene werden empfohlen; der Tumorbefund allein stellt keine Lynch-Diagnose.":"Se recomandă consiliere genetică și testare germinală a genelor relevante pentru MMR/Lynch; rezultatul tumoral singur nu stabilește diagnosticul de sindrom Lynch.","PD-L1/TMB Zusatzkontext":"Context suplimentar PD-L1/TMB","Zusatzmarker können berichtet werden, stehen aber hinter dem robusten dMMR/MSI-H-Befund zurück und sind für die Lynch-Reflexdiagnostik nicht entscheidend.":"Markerii suplimentari pot fi raportați, dar rămân secundari față de rezultatul robust dMMR/MSI-H și nu sunt decisivi pentru testarea reflexă Lynch.","Rezidiviertes Endometriumkarzinom bei junger Patientin mit auffälliger Familienanamnese.":"Carcinom endometrial recidivat la o pacientă tânără cu antecedente familiale sugestive.","MMR-IHC und MSI-/Methylierungsdiagnostik technisch verwertbar.":"IHC MMR și testarea MSI/metilării sunt tehnic evaluabile.","Rezidiviertes Endometriumkarzinom mit MLH1/PMS2-Verlust und MSI-H. Der dMMR/MSI-H-Befund ist therapeutisch relevant. Da keine MLH1-Promotor-Hypermethylierung nachweisbar ist, bleibt ein Lynch-Syndrom abklärungsbedürftig und erfordert humangenetische Beratung/Keimbahndiagnostik. BRAF V600E ist in diesem Endometrium-Kontext kein adäquater Ersatzreflex und Lynch ist aus dem Tumorbefund allein nicht bewiesen.":"Carcinom endometrial recidivat cu pierdere MLH1/PMS2 și MSI-H. Rezultatul dMMR/MSI-H este relevant terapeutic. Deoarece nu se detectează hipermetilarea promotorului MLH1, sindromul Lynch rămâne de investigat și necesită consiliere genetică/testare germinală. BRAF V600E nu reprezintă un reflex substitut adecvat în acest context endometrial, iar sindromul Lynch nu este dovedit doar prin rezultatul tumoral.","Teilbefund: dMMR/MSI-H ist erkannt, aber ohne MLH1-Methylierungsreflex und humangenetische Weiterleitung bleibt die hereditäre Ebene unvollständig.":"Rezultat parțial: dMMR/MSI-H este recunoscut, dar fără testarea reflexă a metilării MLH1 și trimiterea la genetică, componenta ereditară rămâne incompletă.","dMMR/MSI-H als starken prädiktiven Immuntherapiekontext benennen":"Menționați dMMR/MSI-H ca un context predictiv puternic pentru imunoterapie","MLH1/PMS2-Verlust korrekt als gekoppeltes MMR-Muster einordnen":"Interpretați corect pierderea MLH1/PMS2 ca profil MMR cuplat","MLH1-Promotormethylierung als passenden Endometrium-Reflex nutzen":"Utilizați metilarea promotorului MLH1 ca test reflex adecvat în endometru","fehlende Methylierung → Lynch-Abklärung empfehlen, aber Lynch nicht als bewiesen darstellen":"Fără metilare → recomandați evaluarea Lynch, dar nu prezentați sindromul Lynch ca fiind dovedit","Falschaussage: BRAF-V600E ist auch beim Endometriumkarzinom der Standardreflex für MLH1/PMS2-Verlust":"Afirmație falsă: BRAF V600E este și în carcinomul endometrial testul reflex standard pentru pierderea MLH1/PMS2","Optimale Lösung: MLH1/PMS2-Verlust + MSI-H therapeutisch kommunizieren; beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex prüfen. Fehlt die Methylierung, humangenetisch weiterleiten – ohne aus dem Tumorscreening bereits eine Lynch-Diagnose zu machen.":"Soluție optimă: comunicați terapeutic pierderea MLH1/PMS2 + MSI-H; în carcinomul endometrial, testați metilarea promotorului MLH1 ca reflex. Dacă metilarea lipsește, continuați cu evaluare genetică — fără a transforma screeningul tumoral în sine într-un diagnostic de Lynch.","Endometriumkarzinom":"Carcinom endometrial","dMMR":"dMMR","MSI-H":"MSI-H","MLH1":"MLH1","PMS2":"PMS2","Lynch":"Lynch","MSI-H und MLH1/PMS2-Verlust: Endometriumkarzinom zwischen Immuntherapie und Lynch-Abklärung":"MSI-H și pierdere MLH1/PMS2: carcinom endometrial între imunoterapie și evaluarea Lynch","Molekularpathologie / Gynäko-Onkologie / Humangenetik / MTB":"Patologie moleculară / Oncologie ginecologică / Genetică medicală / MTB","MMR-IHC-Muster korrekt lesen und MLH1/PMS2-Verlust funktionell einordnen.":"Citiți corect profilul IHC MMR și interpretați funcțional pierderea MLH1/PMS2.","dMMR/MSI-H gleichzeitig als prädiktiven Therapiebiomarker und als möglichen Hinweis auf hereditäre Prädisposition verstehen.":"Înțelegeți dMMR/MSI-H atât ca biomarker predictiv terapeutic, cât și ca posibil indiciu al unei predispoziții ereditare.","Beim Endometriumkarzinom MLH1-Promotormethylierung als passenden Reflex bei MLH1/PMS2-Verlust einsetzen.":"În carcinomul endometrial, utilizați metilarea promotorului MLH1 ca test reflex adecvat în cazul pierderii MLH1/PMS2.","Den CRC-spezifischen BRAF-V600E-Reflex nicht unkritisch auf das Endometriumkarzinom übertragen.":"Nu transferați necritic reflexul BRAF V600E specific CRC la carcinomul endometrial.","Fehlende MLH1-Methylierung als Anlass zur Lynch-Abklärung, nicht als bereits bewiesenes Lynch-Syndrom kommunizieren.":"Comunicați absența metilării MLH1 ca motiv pentru evaluarea Lynch, nu ca sindrom Lynch deja dovedit.","Die MMR-IHC zeigt einen klaren MLH1/PMS2-Verlust, der MSI-Test ist high. Im Tumorboard sind sich alle einig, dass das therapeutisch wichtig ist. Dann kommt die zweite Frage: 'Dann machen wir jetzt BRAF wie beim Kolon?' Genau hier kippt der Fall von Immuntherapie in echte molekularpathologische Reflexdiagnostik.":"IHC MMR arată o pierdere clară MLH1/PMS2, iar testarea MSI este high. În tumor board toată lumea este de acord că acest lucru este important terapeutic. Apoi vine a doua întrebare: „Atunci facem acum BRAF, ca la colon?” Exact aici cazul trece de la imunoterapie la o veritabilă diagnosticare reflexă de patologie moleculară.","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und auffälliger Familienanamnese. Der Tumor ist dMMR/MSI-H mit MLH1/PMS2-Verlust. Gesucht wird die korrekte Trennung von unmittelbarer therapeutischer Relevanz und Lynch-Screening inklusive entitätsspezifischem MLH1-Methylierungsreflex.":"Pacientă de 49 de ani cu carcinom endometrioid endometrial recidivat și antecedente familiale sugestive. Tumora este dMMR/MSI-H cu pierdere MLH1/PMS2. Sarcina este separarea corectă a relevanței terapeutice imediate de screeningul Lynch, inclusiv reflexul de metilare MLH1 specific entității.","Ein Befund, zwei Konsequenzen":"Un rezultat, două consecințe","dMMR/MSI-H ist therapie- und hereditär relevant.":"dMMR/MSI-H este relevant atât terapeutic, cât și pentru evaluarea ereditară.","Dieselbe Tumorbiologie kann unterschiedliche klinische Pfade auslösen.":"Aceeași biologie tumorală poate declanșa trasee clinice diferite.","Verlustmuster":"Profil de pierdere","MLH1 und PMS2 fehlen gemeinsam.":"MLH1 și PMS2 sunt pierdute împreună.","Das Heterodimer-Muster lenkt die Reflexdiagnostik auf MLH1.":"Profilul heterodimerului direcționează testarea reflexă către MLH1.","Entität zählt":"Entitatea tumorală contează","BRAF-Reflex ist aus dem CRC bekannt.":"Reflexul BRAF este cunoscut din CRC.","Reflexalgorithmen dürfen nicht mechanisch zwischen Tumorentitäten übertragen werden.":"Algoritmii de testare reflexă nu trebuie transferați mecanic între entități tumorale.","High-grade endometrioides Endometriumkarzinom.":"Carcinom endometrioid endometrial high-grade.","Mutter Kolonkarzinom mit 52, Onkel oberer Harntrakt.":"Mamă cu cancer colorectal la 52 de ani, unchi cu cancer al tractului urinar superior.","Primärtumor mit guter DNA-Qualität; MMR-IHC und Methylierung möglich.":"Tumoră primară cu ADN de bună calitate; IHC MMR și testarea metilării sunt posibile.","MMR-IHC liefert bereits das entscheidende Proteinverlustmuster und sollte nicht durch ein unspezifisches Breitpanel ersetzt werden.":"IHC MMR oferă deja profilul decisiv de pierdere proteică și nu trebuie înlocuită de un panel larg nespecific.","Bei MLH1/PMS2-Verlust ist eine gezielte MLH1-Promotormethylierung material- und fragestellungseffizient.":"În cazul pierderii MLH1/PMS2, testarea țintită a metilării promotorului MLH1 este eficientă atât din punct de vedere al materialului, cât și al întrebării clinice.","Die Keimbahndiagnostik benötigt humangenetische Beratung und eine geeignete Normalprobe; Tumorgewebe allein reicht nicht.":"Testarea germinală necesită consiliere genetică și o probă normală adecvată; țesutul tumoral singur nu este suficient.","MMR-IHC: MLH1 und PMS2 verloren, MSH2/MSH6 erhalten. Was ist der passende nächste Reflex im Endometriumkarzinom?":"IHC MMR: MLH1 și PMS2 pierdute, MSH2/MSH6 păstrate. Care este următorul test reflex adecvat în carcinomul endometrial?","MLH1-Promotormethylierung prüfen, um eine häufige sporadische MLH1-Inaktivierung zu erfassen.":"Evaluați metilarea promotorului MLH1 pentru a identifica un mecanism sporadic frecvent de inactivare MLH1.","BRAF V600E ist hier der Standardreflex wie beim CRC.":"BRAF V600E este testul reflex standard aici, la fel ca în CRC.","Nur PD-L1 nachtesten; MMR-Muster ist für Lynch irrelevant.":"Repetați doar PD-L1; profilul MMR este irelevant pentru Lynch.","Kein Reflex: MLH1/PMS2-Verlust beweist bereits Lynch.":"Fără testare reflexă: pierderea MLH1/PMS2 dovedește deja sindromul Lynch.","Beim Endometriumkarzinom ist die MLH1-Promotormethylierung der relevante Reflex bei MLH1/PMS2-Verlust.":"În carcinomul endometrial, metilarea promotorului MLH1 este testul reflex relevant în cazul pierderii MLH1/PMS2.","Was bedeutet dMMR/MSI-H therapeutisch?":"Ce înseamnă dMMR/MSI-H din punct de vedere terapeutic?","Ein starker prädiktiver Immuntherapiekontext, dessen konkrete Nutzung von Stadium, Linie und aktueller Zulassung/Leitlinie abhängt.":"Un context predictiv puternic pentru imunoterapie, a cărui utilizare concretă depinde de stadiu, linie terapeutică și aprobările/ghidurile actuale.","Ohne hohen PD-L1-Score ist MSI-H therapeutisch bedeutungslos.":"Fără un scor PD-L1 crescut, MSI-H nu are semnificație terapeutică.","MSI-H ist ausschließlich ein Lynch-Screeningmarker.":"MSI-H este exclusiv un marker de screening Lynch.","MSI-H beweist eine Keimbahn-MMR-Mutation.":"MSI-H dovedește o mutație germinală MMR.","dMMR/MSI-H besitzt eine eigenständige prädiktive Bedeutung, unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"dMMR/MSI-H are o semnificație predictivă proprie, indiferent dacă etiologia este sporadică sau ereditară.","MLH1/PMS2-Verlust + MSI-H, aber keine MLH1-Promotormethylierung. Was folgt?":"Pierdere MLH1/PMS2 + MSI-H, dar fără metilarea promotorului MLH1. Ce urmează?","Lynch-Syndrom bleibt verdächtig: humangenetische Beratung/Keimbahndiagnostik veranlassen, ohne Lynch bereits als bewiesen zu bezeichnen.":"Sindromul Lynch rămâne suspect: organizați consiliere genetică/testare germinală fără a eticheta deja sindromul Lynch ca dovedit.","Lynch-Syndrom ist damit sicher bewiesen.":"Sindromul Lynch este acum dovedit cu certitudine.","Fehlende Methylierung beweist einen sporadischen Tumor.":"Absența metilării dovedește o tumoră sporadică.","Nur ein negatives BRAF-Ergebnis kann jetzt Lynch ausschließen.":"Doar un rezultat BRAF negativ poate exclude acum sindromul Lynch.","Tumorscreening stratifiziert den Verdacht; die Keimbahndiagnose ist ein separater Schritt.":"Screeningul tumoral stratifică suspiciunea; diagnosticul germinal este un pas separat.","Warum ist BRAF V600E hier eine Falle?":"De ce este BRAF V600E o capcană aici?","Der BRAF-Reflex gehört zur CRC-spezifischen MLH1/PMS2-Logik und ist beim Endometriumkarzinom kein adäquater Ersatz für MLH1-Promotormethylierung.":"Reflexul BRAF aparține algoritmului MLH1/PMS2 specific CRC și nu este un substitut adecvat pentru metilarea promotorului MLH1 în carcinomul endometrial.","BRAF kann in keinem Endometriumtumor mutiert sein.":"BRAF nu poate fi niciodată mutat într-o tumoră endometrială.","BRAF bestimmt hier ausschließlich die PD-L1-Expression.":"BRAF determină aici exclusiv expresia PD-L1.","CRC- und Endometrium-Reflexalgorithmen sind identisch.":"Algoritmii reflex pentru CRC și endometru sunt identici.","Reflexdiagnostik ist entitätsspezifisch und darf nicht als universelles Rezept behandelt werden.":"Diagnosticul reflex este specific entității și nu trebuie tratat ca o rețetă universală.","Formulieren Sie eine integrierte MTB-/Befundaussage, die dMMR/MSI-H therapeutisch würdigt, den MLH1/PMS2-Verlust korrekt reflexdiagnostisch weiterführt und die Lynch-Frage sauber von der Tumordiagnostik trennt.":"Formulați o declarație integrată MTB/raport care să reflecte corespunzător relevanța terapeutică a dMMR/MSI-H, să continue corect reflex pierderea MLH1/PMS2 și să separe clar întrebarea Lynch de diagnosticul tumoral.","MMR-IHC: MLH1/PMS2-Verlust benennen.":"IHC MMR: menționați pierderea MLH1/PMS2.","MSI-H als konsistenten molekularen Befund bestätigen.":"Confirmați MSI-H ca rezultat molecular concordant.","dMMR/MSI-H als prädiktiven IO-Kontext kommunizieren.":"Comunicați dMMR/MSI-H ca un context predictiv pentru imunoterapie.","MLH1-Promotormethylierung als entitätsspezifischen Reflex durchführen.":"Efectuați metilarea promotorului MLH1 ca test reflex specific entității.","Fehlende MLH1-Methylierung als erhöhten Lynch-Verdacht, nicht als Beweis interpretieren.":"Interpretați absența metilării MLH1 ca suspiciune crescută de sindrom Lynch, nu ca dovadă.","Humangenetische Beratung/Keimbahndiagnostik empfehlen.":"Recomandați consiliere genetică/testare germinală.","BRAF-V600E-CRC-Reflex ausdrücklich nicht übertragen.":"Nu transferați în mod explicit reflexul BRAF V600E din CRC.","MSI kann molekular aus einem validierten Panel bestätigt werden, sofern MMR-IHC und MLH1-Methylierungsreflex trotzdem korrekt integriert werden.":"MSI poate fi confirmat molecular dintr-un panel validat, cu condiția ca IHC MMR și reflexul de metilare MLH1 să fie integrate corect în continuare.","Bei bereits qualitativ eindeutiger dMMR-IHC kann die therapeutische Kommunikation sofort erfolgen, während die hereditäre Reflexdiagnostik parallel abgeschlossen wird.":"Dacă IHC dMMR este deja clară și de bună calitate, interpretarea terapeutică poate fi comunicată imediat, în timp ce testarea reflexă ereditară este finalizată în paralel.","BRAF wie beim CRC":"BRAF ca în CRC","Entitätsspezifischer Reflexalgorithmus falsch übertragen.":"Algoritmul reflex specific entității a fost transferat incorect.","MSI-H = Lynch":"MSI-H = Lynch","Viele dMMR/MSI-H-Tumoren sind sporadisch; Tumorscreening ist keine Keimbahndiagnose.":"Multe tumori dMMR/MSI-H sunt sporadice; screeningul tumoral nu reprezintă un diagnostic germinal.","Methylierungsnegativ = bewiesen erblich":"Metilare negativă = ereditar dovedit","Der Befund erhöht den Verdacht, beweist aber noch keine Keimbahnmutation.":"Rezultatul crește suspiciunea, dar nu dovedește încă o mutație germinală.","PD-L1 priorisieren":"Prioritizați PD-L1","dMMR/MSI-H ist hier der robustere Kernbiomarker; PD-L1 ist für die Lynch-Frage irrelevant.":"dMMR/MSI-H este aici biomarkerul central mai robust; PD-L1 este irelevant pentru întrebarea Lynch.","Der CRC-Reflex wäre hier genau der falsche Automatismus":"Reflexul din CRC ar fi exact automatismul greșit aici","MLH1/PMS2-Verlust und MSI-H wirken zunächst wie ein vertrauter CRC-Fall. Doch beim Endometriumkarzinom ist der sinnvolle Reflex die MLH1-Promotormethylierung – nicht BRAF V600E. Als die Methylierung negativ bleibt, steigt der Lynch-Verdacht deutlich, ohne bereits zur genetischen Diagnose zu werden.":"Pierderea MLH1/PMS2 și MSI-H par inițial un caz familiar de CRC. Însă în carcinomul endometrial reflexul potrivit este metilarea promotorului MLH1 — nu BRAF V600E. Când metilarea rămâne negativă, suspiciunea de Lynch crește semnificativ, fără a deveni încă un diagnostic genetic.","Der Fall trainiert zwei Kernkompetenzen gleichzeitig: entitätsspezifische Reflexdiagnostik und saubere Trennung von Tumor-Screening und Keimbahndiagnose.":"Cazul antrenează simultan două competențe esențiale: diagnosticul reflex specific entității și separarea clară dintre screeningul tumoral și diagnosticul germinal.","Therapie und Lynch-Pfad sauber getrennt":"Tratamentul și traseul Lynch sunt clar separate","MLH1/PMS2-Verlust, MSI-H, keine MLH1-Promotormethylierung. dMMR/MSI-H als IO-relevant berichten; Lynch-Syndrom humangenetisch abklären. BRAF-CRC-Reflex nicht verwenden.":"Pierdere MLH1/PMS2, MSI-H, fără metilarea promotorului MLH1. Raportați dMMR/MSI-H ca relevant pentru IO; continuați evaluarea genetică pentru sindrom Lynch. Nu utilizați reflexul BRAF din CRC.","Beide klinischen Konsequenzen korrekt geführt.":"Ambele consecințe clinice au fost gestionate corect.","IO erkannt, Lynch-Pfad unvollständig":"IO recunoscută, traseu Lynch incomplet","dMMR/MSI-H wird therapeutisch korrekt eingeordnet, MLH1-Methylierung/Genetik fehlen.":"dMMR/MSI-H este interpretat corect terapeutic, dar lipsesc metilarea MLH1/trimiterea la genetică.","Hereditäre Konsequenz verpasst.":"Consecința ereditară a fost omisă.","BRAF-Automatismus":"Automatism BRAF","BRAF V600E wird als Standardreflex bestellt und ein negatives Ergebnis als Lynch-Beweis interpretiert.":"BRAF V600E este comandat ca reflex standard, iar un rezultat negativ este interpretat ca dovadă a sindromului Lynch.","Entitätsspezifische Reflexdiagnostik und Keimbahnlogik verfehlt.":"Au fost ratate diagnosticul reflex specific entității și logica germinală.","MLH1-Methylierung negativ":"Metilare MLH1 negativă","Humangenetische Beratung und Keimbahndiagnostik veranlassen.":"Organizați consiliere genetică și testare germinală.","Lynch-Syndrom kann bestätigt oder ausgeschlossen werden; Familienmanagement erst danach festlegen.":"Sindromul Lynch poate fi apoi confirmat sau exclus; managementul familial trebuie stabilit numai ulterior.","dMMR/MSI-H bestätigt":"dMMR/MSI-H confirmat","Therapieplanung mit aktuellem endometriumkarzinomspezifischem IO-Standard/Leitlinie abgleichen.":"Aliniați planificarea tratamentului la standardul/ghidul actual de IO specific carcinomului endometrial.","Prädiktiver Befund wird unabhängig von der noch offenen Keimbahnursache genutzt.":"Rezultatul predictiv poate fi utilizat independent de cauza germinală încă neclarificată.","dMMR/MSI-H kann zugleich Therapiebiomarker und Hinweis auf hereditäre Prädisposition sein.":"dMMR/MSI-H poate fi simultan biomarker terapeutic și indiciu al unei predispoziții ereditare.","MLH1/PMS2-Verlust lenkt die Reflexdiagnostik auf MLH1-Promotormethylierung.":"Pierderea MLH1/PMS2 direcționează testarea reflexă către metilarea promotorului MLH1.","CRC-BRAF-Reflexe dürfen nicht automatisch auf das Endometriumkarzinom übertragen werden.":"Reflexele BRAF din CRC nu trebuie transferate automat la carcinomul endometrial.","Fehlende MLH1-Methylierung erhöht den Lynch-Verdacht, beweist aber keine Keimbahnmutation.":"Absența metilării MLH1 crește suspiciunea de sindrom Lynch, dar nu dovedește o mutație germinală.","Tumorbiomarker und Humangenetik laufen parallel, aber diagnostisch getrennt.":"Biomarkerii tumorali și genetica medicală se desfășoară în paralel, dar rămân diagnostice separate.","MLH1/PMS2-Verlust + MSI-H = dMMR/MSI-H und damit therapeutisch relevant. Beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex; hier negativ. Deshalb Lynch-Syndrom humangenetisch abklären, aber nicht bereits diagnostizieren. BRAF V600E ist kein adäquater Ersatzreflex.":"Pierderea MLH1/PMS2 + MSI-H = dMMR/MSI-H și, prin urmare, este relevantă terapeutic. În carcinomul endometrial utilizați metilarea promotorului MLH1 ca test reflex; aici este negativă. Prin urmare, continuați evaluarea genetică pentru sindrom Lynch, fără a-l diagnostica deja. BRAF V600E nu este un substitut reflex adecvat.","MMR-Muster korrekt":"Profil MMR corect","MLH1-Methylierungsreflex":"Reflex de metilare MLH1","IO-Relevanz":"Relevanță IO","Lynch-Verdacht ≠ Diagnose":"Suspiciune Lynch ≠ diagnostic","BRAF-Copyover vermieden":"Transferul BRAF a fost evitat","Warum fallen MLH1 und PMS2 gemeinsam aus?":"De ce se pierd împreună MLH1 și PMS2?","Warum unterscheidet sich der Reflexalgorithmus zwischen CRC und Endometrium?":"De ce diferă algoritmul reflex între CRC și carcinomul endometrial?","Welche Information darf bereits im Tumorbefund stehen und welche erst nach Keimbahndiagnostik?":"Ce informații pot apărea deja în raportul tumoral și care numai după testarea germinală?","MLH1/PMS2-Verlust + keine MLH1-Methylierung":"Pierdere MLH1/PMS2 + fără metilare MLH1","dMMR ist Therapiebiomarker und Lynch-Screening, aber Entität bestimmt den Reflex":"dMMR este atât biomarker terapeutic, cât și screening Lynch, dar entitatea tumorală determină reflexul","MMR-IHC → MSI → MLH1-Methylierung → Humangenetik":"IHC MMR → MSI → metilare MLH1 → genetică medicală","Antibiotika kurz vor ICI, Mikrobiom-Frage im Tumorboard → Evidenz korrekt begrenzen":"Antibiotice cu puțin timp înainte de ICI, întrebare despre microbiom în tumor board → limitați corect nivelul dovezilor","Antibiotika kurz vor ICI, Mikrobio…":"Antibiotice cu puțin timp înainte de ICI, microbio…","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom. PD-L1 TPS 80 %. Vor Beginn der geplanten Immuntherapie musste er wegen einer mikrobiologisch gesicherten bakteriellen Pneumonie sieben Tage breit antibiotisch behandelt werden.":"Bărbat de 72 de ani cu adenocarcinom pulmonar metastatic. PD-L1 TPS 80 %. Înainte de începerea planificată a imunoterapiei, a necesitat șapte zile de antibiotice cu spectru larg pentru o pneumonie bacteriană confirmată microbiologic.","Soll die notwendige Antibiotikatherapie wegen möglicher Mikrobiom-Effekte die ICI-Entscheidung verändern, verzögern oder durch Mikrobiom-Interventionen 'kompensiert' werden?":"Ar trebui ca antibioterapia necesară, din cauza unor posibile efecte asupra microbiomului, să modifice sau să amâne decizia de ICI ori să fie „compensată” prin intervenții asupra microbiomului?","Die Pneumonie ist klinisch abgeheilt; Systemtherapie soll zeitnah beginnen.":"Pneumonia s-a remis clinic; terapia sistemică trebuie începută prompt.","Tumor":"Tumoră","Metastasiertes Lungenadenokarzinom, ECOG 1.":"Adenocarcinom pulmonar metastatic, ECOG 1.","Treiberdiagnostik":"Testare driver","Breites DNA/RNA-Profil ohne etablierte actionable Driveralteration; ALK/ROS1/RET/NTRK/METex14/EGFR etc. ohne therapieentscheidenden Befund.":"Profilare largă ADN/ARN fără o alterare driver actionable consacrată; ALK/ROS1/RET/NTRK/METex14/EGFR etc. fără rezultat determinant terapeutic.","TPS 80 %, technisch valide.":"TPS 80 %, valid tehnic.","Antibiotika":"Antibiotice","Piperacillin/Tazobactam, anschließend orale Komplettierung wegen gesicherter bakterieller Pneumonie; Therapie war klinisch indiziert.":"Piperacilină/tazobactam urmată de completare orală pentru pneumonie bacteriană confirmată; tratamentul a fost indicat clinic.","Eine populationsbasierte Assoziation zwischen Antibiotika/Mikrobiom und ICI-Outcome wird zur individuellen Kontraindikation oder zum Anlass für unvalidierte Probiotika/FMT gemacht.":"O asociere la nivel populațional între antibiotice/microbiom și rezultatul ICI este transformată într-o contraindicație individuală sau într-un motiv pentru probiotice/FMT nevalidate.","Pulmonales Adenokarzinom, TTF-1/Napsin A positiv.":"Adenocarcinom pulmonar, TTF-1/Napsin A pozitiv.","TPS 80 %.":"TPS 80 %.","Molekularprofil":"Profil molecular","DNA/RNA-basierte Treiberdiagnostik ohne etablierte Targetalteration.":"Testare driver bazată pe ADN/ARN fără o alterare targetabilă consacrată.","Nicht die Tumordiagnostik, sondern die Evidenzstärke der Mikrobiom-/Antibiotika-Assoziation und ihre Konsequenz für die individuelle Therapie.":"Problema-cheie nu este testarea tumorii, ci forța dovezilor pentru asocierea microbiom/antibiotice și consecința acesteia asupra deciziei terapeutice individuale.","Kleine Bronchialbiopsie; wesentliche Treiber- und PD-L1-Diagnostik bereits vollständig.":"Biopsie bronșică mică; testarea esențială driver și PD-L1 este deja completă.","Restmaterial":"Material restant","Nur noch begrenzt verfügbar.":"Mai este disponibil doar material limitat.","Zusätzliche TMB-/TIL-/Breitdiagnostik kann den Effekt einer Antibiotikatherapie auf das Darmmikrobiom nicht valide quantifizieren und erzeugt keine etablierte 'ICI-Freigabe'.":"Testarea suplimentară TMB/TIL/largă nu poate cuantifica în mod valid efectul antibioterapiei asupra microbiomului intestinal și nu generează o „aprobare ICI” consacrată.","Klinische Ressource":"Resursă clinică","Der wichtigste Zusatzdatensatz ist hier die Indikation und zeitliche Einordnung der Antibiotikatherapie – nicht noch ein Tumortest.":"Cel mai important set suplimentar de date aici este indicația și momentul antibioterapiei — nu încă un test tumoral.","Validierter Tumor-/ICI-Kontext":"Context tumoral/ICI validat","PD-L1 TPS 80 % bestätigt. Der Marker bleibt ein etablierter Bestandteil der NSCLC-Therapieplanung im passenden driver-negativen Kontext.":"PD-L1 TPS 80 % confirmat. Markerul rămâne o componentă consacrată a planificării terapiei NSCLC în contextul driver-negativ adecvat.","Treiberprofil":"Profil driver","Keine etablierte actionable Driveralteration nach integrierter DNA/RNA-Diagnostik. Die hohe PD-L1-Expression wird damit nicht durch einen offensichtlichen targetierbaren Treiberkontext verdrängt.":"Nicio alterare driver actionable consacrată după testarea integrată ADN/ARN. Expresia PD-L1 ridicată nu este astfel eclipsată de un context driver evident targetabil.","TMB intermediär (7 Mut/Mb). Dieser Wert beantwortet die Antibiotika-/Mikrobiomfrage nicht und ersetzt die validierte NSCLC-Biomarkerhierarchie nicht.":"TMB intermediar (7 mut/Mb). Această valoare nu răspunde la întrebarea antibiotice/microbiom și nu înlocuiește ierarhia validată a biomarkerilor NSCLC.","Mäßiges CD8-Infiltrat. Auch dieser Befund erlaubt keine patientenspezifische Quantifizierung eines möglichen Antibiotikaeffekts auf ICI-Wirksamkeit.":"Infiltrat CD8 moderat. Nici acest rezultat nu permite cuantificarea unui efect specific pacientului al antibioticelor asupra eficacității ICI.","Antibiotikaanamnese":"Istoric antibiotic","Sieben Tage notwendige Antibiotikatherapie wegen gesicherter bakterieller Pneumonie unmittelbar vor geplantem ICI-Beginn.":"Șapte zile de antibioterapie necesară pentru pneumonie bacteriană confirmată, imediat înainte de începerea planificată a ICI.","Infektion abgeheilt; Patient therapiefähig.":"Infecție remisă; pacient apt pentru terapie.","Evidenzkonflikt":"Conflict de dovezi","Beobachtungsdaten zeigen Assoziationen zwischen Antibiotikaexposition und schlechteren ICI-Outcomes, beweisen aber für den individuellen Patienten keine kausale Therapieresistenz.":"Datele observaționale arată asocieri între expunerea la antibiotice și rezultate ICI mai slabe, dar nu dovedesc rezistență terapeutică cauzală la pacientul individual.","Driver-negatives metastasiertes NSCLC mit hoher PD-L1-Expression. Die kürzlich notwendige Antibiotikatherapie ist als möglicher prognostischer/biologischer Kontext diskutierbar, stellt aber keine validierte individuelle Kontraindikation gegen eine indizierte Checkpoint-Therapie dar. Eine klinisch notwendige bakterielle Infektion durfte nicht unbehandelt bleiben. Unnötige Antibiotika sollten vermieden werden; Mikrobiomtests, Probiotika oder FMT sind nicht als routinemäßige Kompensationsstrategie validiert und gehören – sofern überhaupt – in Studien.":"NSCLC metastatic driver-negativ cu expresie PD-L1 ridicată. Antibioterapia recentă și necesară poate fi discutată ca posibil context prognostic/biologic, dar nu reprezintă o contraindicație individuală validată pentru terapia checkpoint indicată. O infecție bacteriană clinic necesară nu trebuia lăsată netratată. Antibioticele inutile trebuie evitate; testarea microbiomului, probioticele sau FMT nu sunt validate ca strategii de compensare de rutină și aparțin, dacă este cazul, studiilor clinice.","Teilbefund: Die Mikrobiom-Assoziation wird erwähnt, aber ohne Trennung von Kausalität, Konfounding, klinischer Antibiotikaindikation und validierten Tumorbiomarkern bleibt die Empfehlung unsauber.":"Interpretare parțială: asocierea cu microbiomul este menționată, dar fără separarea cauzalității, confounding-ului, indicației clinice pentru antibiotice și biomarkerilor tumorali validați, recomandarea rămâne imprecisă.","PD-L1 und vollständigen Driverstatus als etablierte NSCLC-Biomarkerhierarchie priorisieren":"Prioritizați PD-L1 și statusul driver complet ca ierarhie consacrată a biomarkerilor NSCLC","Antibiotika/ICI als Assoziation mit möglichem Confounding, nicht als individuellen Resistenztest erklären":"Explicați antibiotice/ICI ca o asociere cu posibil confounding, nu ca test individual de rezistență","klinisch notwendige Antibiotikatherapie nicht retrospektiv als Fehler darstellen":"Nu prezentați retrospectiv antibioterapia necesară clinic ca pe o eroare","keine unvalidierte Mikrobiomdiagnostik, Probiotika oder FMT als Routineempfehlung aussprechen":"Nu recomandați testare nevalidată a microbiomului, probiotice sau FMT ca rutină","Falschaussage: Antibiotika kurz vor ICI sind eine absolute Kontraindikation gegen Immuntherapie":"Afirmație falsă: antibioticele cu puțin timp înainte de ICI reprezintă o contraindicație absolută pentru imunoterapie","Optimale Lösung: Hohe PD-L1-Expression und driver-negativer NSCLC-Kontext bleiben die belastbaren Therapiebiomarker. Die notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext zu erwähnen, aber nicht als validierte individuelle Kontraindikation. Keine unvalidierten Mikrobiom-Interventionen außerhalb von Studien.":"Soluție optimă: expresia PD-L1 ridicată și contextul NSCLC driver-negativ rămân biomarkerii terapeutici de încredere. Antibioterapia necesară trebuie menționată ca posibil context de outcome, dar nu ca o contraindicație individuală validată. Fără intervenții nevalidate asupra microbiomului în afara studiilor.","Mikrobiom":"Microbiom","ICI":"ICI","Confounding":"Confounding","Antibiotika vor ICI: relevante Assoziation, aber keine patientenindividuelle Kontraindikation":"Antibiotice înainte de ICI: asociere relevantă, dar nu contraindicație individuală","Beobachtungsassoziation, Kausalität und Confounding in der Mikrobiom-/ICI-Literatur unterscheiden.":"Diferențiați asocierea observațională, cauzalitatea și confounding-ul în literatura microbiom/ICI.","Validierte NSCLC-Tumorbiomarker gegenüber unvalidierten Mikrobiom-Surrogaten priorisieren.":"Prioritizați biomarkerii tumorali NSCLC validați față de surrogate nevalidate ale microbiomului.","Klinisch notwendige Antibiotikatherapie nicht retrospektiv als vermeidbaren onkologischen Fehler behandeln.":"Nu tratați retrospectiv antibioterapia necesară clinic ca pe o eroare oncologică evitabilă.","Eine vorausgegangene Antibiotikaexposition nicht als absolute ICI-Kontraindikation formulieren.":"Nu formulați expunerea anterioară la antibiotice ca o contraindicație absolută pentru ICI.","Mikrobiomtests, Probiotika und FMT als experimentell statt als Routinetherapie einordnen.":"Încadrați testarea microbiomului, probioticele și FMT ca experimentale, nu ca terapie de rutină.","Der Patient hat genau den Tumor, bei dem das Team an Checkpoint-Therapie denkt: driver-negatives NSCLC, PD-L1 TPS 80 %. Dann fällt im Medikamentenplan auf, dass er in der Vorwoche sieben Tage Breitbandantibiotika bekommen hat. Sofort steht die Frage im Raum: 'Haben wir damit die Immuntherapie kaputtgemacht?' Der Fall dreht sich weniger um einen weiteren Labortest als um Evidenzkompetenz.":"Pacientul are exact tipul de tumoră pentru care echipa se gândește la terapia checkpoint: NSCLC driver-negativ, PD-L1 TPS 80 %. Apoi, lista de medicamente arată că în săptămâna precedentă a primit șapte zile de antibiotice cu spectru larg. Întrebarea apare imediat: „Am stricat astfel imunoterapia?” Cazul este mai puțin despre comandarea unui alt test de laborator și mai mult despre competența de interpretare a dovezilor.","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom, vollständiger DNA/RNA-Treiberdiagnostik ohne actionable Alteration und PD-L1 TPS 80 %. Unmittelbar vor geplantem ICI-Beginn wurde eine mikrobiologisch gesicherte Pneumonie leitliniengerecht antibiotisch behandelt. Das MTB soll entscheiden, ob dies die Immuntherapie verändert und wie Mikrobiomdaten klinisch korrekt begrenzt werden.":"Bărbat de 72 de ani cu adenocarcinom pulmonar metastatic, testare completă ADN/ARN pentru drivere fără alterare actionable și PD-L1 TPS 80 %. Imediat înainte de începerea planificată a ICI, o pneumonie confirmată microbiologic a fost tratată corespunzător cu antibiotice. MTB trebuie să decidă dacă acest lucru modifică imunoterapia și cum trebuie limitate clinic datele despre microbiom.","Starker etablierter Tumorbiomarker":"Biomarker tumoral puternic consacrat","PD-L1 TPS 80 %, kein etablierter actionable Driver.":"PD-L1 TPS 80 %, fără driver actionable consacrat.","Die Therapieplanung basiert zunächst auf validierten Tumor- und Klinikfaktoren.":"Planificarea terapiei se bazează în primul rând pe factori tumorali și clinici validați.","Reale Mikrobiomassoziation":"Asociere reală cu microbiomul","Antibiotikaexposition um ICI-Beginn ist in Kohorten mit schlechterem Outcome assoziiert.":"Expunerea la antibiotice în jurul începerii ICI este asociată cu rezultate mai slabe în cohorte.","Assoziation kann biologisch plausibel sein und trotzdem durch Infektion, Krankheitslast oder andere Faktoren konfundiert werden.":"O asociere poate fi biologic plauzibilă și totuși confuzionată de infecție, povara bolii sau alți factori.","Klinische Indikation zählt":"Indicația clinică contează","Die Pneumonie war gesichert und behandlungsbedürftig.":"Pneumonia a fost confirmată și necesita tratament.","Ein notwendiges Antibiotikum wird nicht dadurch falsch, dass es möglicherweise das Mikrobiom beeinflusst.":"Un antibiotic necesar nu devine greșit doar pentru că poate influența microbiomul.","DNA/RNA-Treiberprofil":"Profil driver ADN/ARN","Kein etablierter actionable Driver.":"Fără driver actionable consacrat.","Sieben Tage wegen gesicherter bakterieller Pneumonie; Infektion jetzt abgeheilt.":"Șapte zile pentru pneumonie bacteriană confirmată; infecția este acum remisă.","Restmaterial ist knapp; zusätzliche Tumortests beantworten die Mikrobiomfrage nicht valide.":"Materialul restant este redus; testele tumorale suplimentare nu răspund în mod valid la întrebarea despre microbiom.","Der Simulator enthält bewusst keinen 'Mikrobiom-ICI-Freigabetest', weil hierfür kein etablierter Routineassay mit validiertem Cutoff existiert.":"Simulatorul nu conține intenționat niciun „test de autorizare ICI pe baza microbiomului”, deoarece nu există pentru acest scop un test de rutină consacrat cu prag validat.","Die entscheidende Zusatzinformation ist klinisch: Indikation, Zeitpunkt, Dauer und Infektionsstatus.":"Informația suplimentară decisivă este clinică: indicație, moment, durată și statusul infecției.","Was lässt sich aus der Beobachtung 'Antibiotika um ICI-Beginn sind mit schlechterem Outcome assoziiert' für diesen Patienten ableiten?":"Ce se poate deduce pentru acest pacient din observația că „antibioticele în jurul începerii ICI sunt asociate cu un outcome mai slab”?","Es ist ein relevanter möglicher Risiko-/Biologiekontext, aber kein kausaler individueller Resistenztest; Confounding durch Infektion und Krankheitsstatus muss bedacht werden.":"Este un posibil context relevant de risc/biologie, dar nu un test cauzal de rezistență individuală; trebuie luat în calcul confounding-ul prin infecție și statusul bolii.","Antibiotika beweisen, dass ICI nicht mehr wirken kann.":"Antibioticele dovedesc că ICI nu mai poate funcționa.","Beobachtungsdaten sind grundsätzlich wertlos und dürfen nie erwähnt werden.":"Datele observaționale sunt fundamental lipsite de valoare și nu trebuie menționate niciodată.","ICI muss nach jeder Antibiotikagabe zwingend für einen festen Zeitraum verschoben werden.":"ICI trebuie întotdeauna amânată pentru o perioadă fixă după orice cură de antibiotice.","Beobachtungsassoziationen sind klinisch relevant, aber nicht gleichbedeutend mit kausaler patientenindividueller Vorhersage.":"Asocierile observaționale sunt relevante clinic, dar nu echivalează cu o predicție cauzală specifică pacientului.","War die Antibiotikatherapie onkologisch ein Fehler?":"A fost antibioterapia o greșeală oncologică?","Nein. Eine gesicherte bakterielle Pneumonie musste behandelt werden; unnötige Antibiotika sollten vermieden werden, notwendige aber nicht aus Mikrobiomangst vorenthalten werden.":"Nu. Pneumonia bacteriană confirmată necesita tratament; antibioticele inutile trebuie evitate, dar tratamentul necesar nu trebuie reținut din teama efectelor asupra microbiomului.","Ja. Vor ICI dürfen Antibiotika nie gegeben werden.":"Da. Antibioticele nu trebuie administrate niciodată înainte de ICI.","Nur wenn gleichzeitig FMT gegeben wird, war sie vertretbar.":"A fost acceptabilă doar dacă s-a administrat simultan FMT.","Bei PD-L1 80 % ist eine Infektionsbehandlung generell unwichtig.":"La PD-L1 80 %, tratamentul unei infecții este în general neimportant.","Patientensicherheit und Behandlung einer realen Infektion haben Vorrang vor nicht validierter Mikrobiomoptimierung.":"Siguranța pacientului și tratamentul unei infecții reale au prioritate față de optimizarea nevalidată a microbiomului.","Soll jetzt routinemäßig ein Mikrobiomtest, Probiotikum oder FMT zur 'Rettung' der ICI-Wirkung veranlasst werden?":"Ar trebui acum solicitate de rutină un test al microbiomului, un probiotic sau FMT pentru a „salva” eficacitatea ICI?","Nein. Solche Strategien sind derzeit nicht als routinemäßige patientenindividuelle Kompensation validiert und gehören gegebenenfalls in Studien.":"Nu. Astfel de strategii nu sunt în prezent validate ca măsuri de compensare individuală de rutină și, dacă sunt luate în calcul, aparțin studiilor clinice.","FMT ist nach Antibiotika vor ICI Standard.":"FMT este standard după antibiotice înainte de ICI.","Ein frei verkäufliches Probiotikum ist evidenzbasiert obligat.":"Un probiotic fără prescripție este bazat pe dovezi și obligatoriu.","Ein einzelnes 16S-Profil kann zuverlässig die ICI-Wirkung vorhersagen.":"Un singur profil 16S poate prezice în mod fiabil eficacitatea ICI.","Mikrobiominterventionen sind ein Forschungsfeld, kein etablierter Routinealgorithmus zur ICI-Freigabe.":"Intervențiile asupra microbiomului reprezintă un domeniu de cercetare, nu un algoritm de rutină consacrat pentru „autorizarea” ICI.","Welche Information sollte die Therapieentscheidung stärker tragen?":"Ce informație ar trebui să aibă o greutate mai mare în decizia terapeutică?","Validierter NSCLC-Kontext aus Histologie, vollständigem Driverprofil, PD-L1, Klinik und Infektionsstatus; Antibiotikaexposition als zusätzlicher Unsicherheits-/Risikokontext.":"Context NSCLC validat din histologie, profil driver complet, PD-L1, status clinic și status infecțios; expunerea la antibiotice ca un context suplimentar de incertitudine/risc.","Allein die Antibiotikaexposition.":"Doar expunerea la antibiotice.","Ein zusätzlicher TMB-Wert unabhängig von PD-L1 und Driverstatus.":"O valoare TMB suplimentară indiferent de PD-L1 și statusul driver.","Ein experimentelles Darmmikrobiomprofil.":"Un profil experimental al microbiomului intestinal.","Evidenzhierarchie verhindert, dass ein interessanter Forschungsmarker etablierte Therapiebiomarker verdrängt.":"O ierarhie a dovezilor împiedică un marker de cercetare interesant să înlocuiască biomarkerii terapeutici consacrați.","Formulieren Sie eine MTB-Empfehlung, die die Antibiotika-/Mikrobiomassoziation ernst nimmt, aber die individuelle Therapieentscheidung auf validierte NSCLC-Biomarker und den aktuellen klinischen Zustand stützt.":"Formulați o recomandare MTB care ia în serios asocierea antibiotice/microbiom, dar bazează decizia terapeutică individuală pe biomarkeri NSCLC validați și pe starea clinică actuală.","Driver-negatives NSCLC und PD-L1 TPS 80 % als validierten Tumorkontext priorisieren.":"Prioritizați NSCLC driver-negativ și PD-L1 TPS 80 % ca context tumoral validat.","Antibiotikaexposition zeitlich und indikationsbezogen dokumentieren.":"Documentați expunerea la antibiotice cu momentul și indicația.","Assoziation mit schlechterem ICI-Outcome als Beobachtungsbefund mit möglichem Confounding erklären.":"Explicați asocierea cu rezultate ICI mai slabe ca un rezultat observațional cu posibil confounding.","Notwendige Infektionsbehandlung nicht als Fehler darstellen.":"Nu prezentați tratamentul necesar al infecției ca pe o eroare.","Keine absolute ICI-Kontraindikation oder fixe Wartezeit allein aus Antibiotika ableiten.":"Nu deduceți o contraindicație absolută pentru ICI sau o perioadă fixă de așteptare doar din antibiotice.","Keine routinemäßigen Mikrobiomtests/Probiotika/FMT außerhalb validierter Indikation bzw. klinischer Studien empfehlen.":"Nu recomandați de rutină teste de microbiom/probiotice/FMT în afara unei indicații validate sau a unui studiu clinic.","Wenn nach Abheilung der Infektion klinische Gründe für eine kurze Verzögerung bestehen, diese klinisch und nicht als 'Mikrobiom-Washout' begründen.":"Dacă există motive clinice pentru o scurtă amânare după remiterea infecției, justificați-le clinic și nu ca „washout al microbiomului”.","Mikrobiomstudie anbieten, sofern verfügbar und ohne die Standardtherapie unangemessen zu verzögern.":"Oferiți participarea la un studiu de microbiom dacă este disponibil, fără a întârzia nejustificat terapia standard.","Antibiotika = absolute ICI-Kontraindikation":"Antibiotice = contraindicație absolută pentru ICI","Dafür existiert kein validierter patientenindividueller Entscheidungsalgorithmus.":"Nu există un algoritm validat de decizie specific pacientului pentru aceasta.","Notwendige Infektion unbehandelt lassen":"Lăsați netratată o infecție care necesită tratament","Patientensicherheit und Infektionskontrolle haben Vorrang.":"Siguranța pacientului și controlul infecției au prioritate.","FMT/Probiotika als Routine":"FMT/probiotice ca rutină","Experimentelle Interventionen dürfen nicht als Standard verkauft werden.":"Intervențiile experimentale nu trebuie prezentate ca standard de îngrijire.","Mehr Tumortests bestellen":"Comandați mai multe teste tumorale","TMB/TILs quantifizieren keinen individuellen Antibiotika-Mikrobiomeffekt.":"TMB/TIL nu cuantifică un efect individual antibiotice-microbiom.","Das Antibiotikum war möglicherweise biologisch ungünstig – und trotzdem medizinisch richtig":"Antibioticul poate să fi fost biologic nefavorabil — și totuși corect medical","Die Literaturassoziation ist plausibel und soll nicht weggewischt werden. Gleichzeitig war die Pneumonie mikrobiologisch gesichert und behandlungsbedürftig. Der zentrale Twist ist daher epistemisch: Ein möglicher negativer Biomarker-/Expositionskontext macht eine notwendige Behandlung nicht falsch und liefert keine validierte individuelle ICI-Kontraindikation.":"Asocierea din literatură este plauzibilă și nu trebuie ignorată. În același timp, pneumonia a fost confirmată microbiologic și necesita tratament. Twist-ul central este deci epistemic: un posibil context nefavorabil de biomarker/expunere nu face greșit un tratament necesar și nu oferă o contraindicație individuală validată pentru ICI.","Der Fall trainiert Evidenzstufen, Confounding und die Fähigkeit, populationsbasierte Forschung nicht in überharte Einzelpatientenregeln zu übersetzen.":"Cazul antrenează nivelurile de dovezi, confounding-ul și capacitatea de a nu transforma cercetarea populațională în reguli excesiv de rigide pentru pacientul individual.","Evidenz sauber begrenzt":"Dovezi limitate corect","Driver-negatives NSCLC, PD-L1 TPS 80 %. Antibiotika wegen gesicherter Pneumonie waren notwendig. Exposition als möglicher Outcome-Kontext erwähnen, aber keine absolute ICI-Kontraindikation oder Mikrobiom-Routineintervention ableiten.":"NSCLC driver-negativ, PD-L1 TPS 80 %. Antibioticele pentru pneumonia confirmată au fost necesare. Menționați expunerea ca posibil context de outcome, dar nu deduceți o contraindicație absolută pentru ICI sau o intervenție de rutină asupra microbiomului.","Validierte Biomarker und unsichere Exposition korrekt gewichtet.":"Biomarkerii validați și expunerea incertă au fost ponderați corect.","Assoziation erkannt, aber zu viel Unsicherheit":"Asocierea este recunoscută, dar cu prea multă incertitudine","Antibiotikadaten werden erwähnt, die Therapie wird jedoch ohne belastbare Grundlage allein deshalb unbestimmt verschoben.":"Datele despre antibiotice sunt menționate, dar terapia este apoi amânată pe termen nedefinit numai din acest motiv, fără bază solidă.","Beobachtungsdaten zu stark operationalisiert.":"Datele observaționale au fost operaționalizate excesiv.","ICI gestrichen, FMT empfohlen":"ICI anulată, FMT recomandat","Antibiotika werden als Beweis für ICI-Resistenz behandelt und FMT/Probiotika als Routine empfohlen.":"Antibioticele sunt tratate ca dovadă a rezistenței la ICI, iar FMT/probioticele sunt recomandate ca rutină.","Evidenzniveau und Patientensicherheit verfehlt.":"Nivelul dovezilor și siguranța pacientului au fost ratate.","Infektion klinisch abgeheilt":"Infecție remisă clinic","Systemtherapie nach regulären onkologischen Kriterien planen; keine fixe 'Mikrobiom-Wartezeit' erfinden.":"Planificați terapia sistemică după criterii oncologice obișnuite; nu inventați o „perioadă de așteptare pentru microbiom” fixă.","Die Therapie wird nicht aufgrund unvalidierter Surrogate unangemessen verzögert.":"Terapia nu este amânată necorespunzător din cauza unor surrogate nevalidate.","künftige Antibiotikafrage":"Întrebarea privind antibioticele viitoare","Antibiotic stewardship: unnötige Exposition vermeiden, notwendige Infektionen zielgerichtet behandeln.":"Antibiotic stewardship: evitați expunerea inutilă și tratați țintit infecțiile care necesită tratament.","Pragmatische Risikoreduktion ohne Pseudopräzision.":"Reducere pragmatică a riscului fără pseudo-precizie.","Mikrobiomstudie verfügbar":"Studiu de microbiom disponibil","Teilnahme als Forschungsoption diskutieren.":"Discutați participarea ca opțiune de cercetare.","Innovative Ansätze bleiben im passenden Evidenzrahmen.":"Abordările inovatoare rămân în cadrul adecvat al dovezilor.","Antibiotikaexposition um ICI ist in Beobachtungsdaten mit schlechteren Outcomes assoziiert, aber Confounding ist relevant.":"Expunerea la antibiotice în jurul ICI este asociată cu rezultate mai slabe în date observaționale, dar confounding-ul este relevant.","Eine klinisch notwendige Antibiotikatherapie darf nicht aus Angst vor Mikrobiomeffekten vorenthalten werden.":"Antibioterapia necesară clinic nu trebuie reținută din teama efectelor asupra microbiomului.","Es gibt keinen etablierten Routine-Mikrobiomtest, der nach Antibiotika die individuelle ICI-Wirkung freigibt oder ausschließt.":"Nu există un test de rutină consacrat al microbiomului care să confirme sau să excludă eficacitatea individuală a ICI după antibiotice.","FMT/Probiotika zur ICI-Optimierung sind Forschungsansätze, keine Standardkompensation.":"FMT/probioticele pentru optimizarea ICI sunt abordări de cercetare, nu compensare standard.","Präzisionsonkologie bedeutet auch, Evidenzgrenzen präzise zu kommunizieren.":"Oncologia de precizie înseamnă și comunicarea precisă a limitelor dovezilor.","PD-L1 TPS 80 % bei driver-negativem NSCLC bleibt ein etablierter Therapiebiomarkerkontext. Die kürzlich notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext relevant, aber keine validierte individuelle Kontraindikation. Keine unvalidierte fixe Wartezeit oder routinemäßige Mikrobiomintervention ableiten; unnötige Antibiotika künftig vermeiden, notwendige behandeln.":"PD-L1 TPS 80 % în NSCLC driver-negativ rămâne un context consacrat de biomarker terapeutic. Antibioterapia recentă și necesară este relevantă ca posibil context de outcome, dar nu ca o contraindicație individuală validată. Nu deduceți o perioadă fixă de așteptare nevalidată sau o intervenție de rutină asupra microbiomului; evitați pe viitor antibioticele inutile și tratați când sunt necesare.","Assoziation ≠ Kausalität":"Asociere ≠ cauzalitate","Confounding erkannt":"Confounding recunoscut","Patientensicherheit":"Siguranța pacientului","validierte Biomarker priorisiert":"Biomarkeri validați prioritizați","keine unvalidierte Mikrobiomtherapie":"Fără terapie nevalidată a microbiomului","Welche Confounder erklären die Antibiotika-ICI-Assoziation möglicherweise mit?":"Ce factori de confuzie ar putea explica parțial asocierea antibiotice-ICI?","Wann wird aus einem prognostischen Faktor ein prädiktiver Biomarker?":"Când devine un factor prognostic un biomarker predictiv?","Wie kommuniziert man interessante, aber nicht handlungsleitende Forschung im MTB?":"Cum comunicați în MTB cercetare interesantă, dar care nu ghidează acțiunea?","notwendige Antibiotikatherapie trotz möglicher negativer Assoziation":"Antibioterapie necesară în ciuda unei posibile asocieri negative","Populationsassoziation ist keine individuelle Kontraindikation":"Asocierea populațională nu este o contraindicație individuală","validierte Tumorbiomarker → Antibiotikaindikation → Evidenzgrad → keine Pseudopräzision":"biomarkeri tumorali validați → indicația antibioticelor → nivelul dovezilor → fără pseudo-precizie","IDH-mutiertes Gliom: R132H-IHC negativ – und trotzdem IDH-mutiert":"Gliom IDH-mutant: IHC R132H negativă — și totuși IDH-mutant","IDH-mutiertes Gliom mit G-CIMP-Pro…":"Gliom IDH-mutant cu profil G-CIMP…","Neuropathologie / Neuroonkologisches Tumorboard":"Neuropatologie / Tumor board neuro-oncologic","36-jähriger Patient nach Resektion eines linksfrontalen diffus infiltrierenden Glioms. Die IDH1-R132H-IHC ist negativ; Alter und Morphologie passen jedoch schlecht zu einem typischen IDH-Wildtyp-Glioblastom.":"Bărbat de 36 de ani după rezecția unui gliom difuz infiltrativ frontal stâng. IHC IDH1 R132H este negativă; totuși, vârsta și morfologia se potrivesc slab cu un glioblastom tipic IDH-wildtype.","Darf der Tumor nach negativer R132H-IHC als IDH-Wildtyp eingeordnet werden – und welche Rolle spielt das Methylierungsprofil?":"Poate tumora fi clasificată IDH-wildtype după IHC R132H negativă — și ce rol are profilul de metilare?","Die integrierte Diagnose soll vor Festlegung der adjuvanten Therapie finalisiert werden.":"Diagnosticul integrat trebuie finalizat înainte de stabilirea terapiei adjuvante.","Erstmanifestation mit fokalem Krampfanfall; MRT zeigt einen nicht kontrastmittelaufnehmenden frontalen Tumor.":"Debut cu criză focală; RMN arată o tumoră frontală fără priză de contrast.","36 Jahre – damit ist eine nicht-kanonische IDH-Alteration klinisch relevant genug, um nach negativer R132H-IHC nicht vorschnell abzubrechen.":"36 de ani — ceea ce face o alterare IDH non-canonică suficient de relevantă clinic pentru a nu opri prematur evaluarea după IHC R132H negativă.","ATRX-Verlust und diffuse p53-Überexpression; 1p/19q-Kodeletion nicht nachweisbar.":"Pierdere ATRX și supraexpresie difuză p53; fără codeleție 1p/19q detectabilă.","Eine negative mutationsspezifische IHC wird mit einem negativen Genstatus gleichgesetzt.":"Un rezultat IHC negativ specific unei mutații este echivalat cu un status genetic negativ.","Diffus infiltrierendes astrozytäres Gliom, mäßige Zelldichte, keine Nekrosen oder mikrovaskuläre Proliferation.":"Gliom astrocitar difuz infiltrativ, celularitate moderată, fără necroză sau proliferare microvasculară.","IDH1 R132H negativ; ATRX nukleär verloren; p53 in großer Tumorzellfraktion stark positiv.":"IDH1 R132H negativ; pierdere nucleară ATRX; p53 puternic pozitiv într-o mare fracțiune de celule tumorale.","Molekulare Vorinformation":"Informații moleculare prealabile","1p/19q intakt.":"1p/19q intact.","Nicht-kanonische IDH1/2-Mutation? Passt das epigenetische Gesamtprofil zu einem IDH-mutierten Astrozytom?":"Mutație IDH1/2 non-canonică? Se potrivește profilul epigenetic global cu un astrocitom IDH-mutant?","FFPE-Resektat, Block F6.":"Piesă de rezecție FFPE, bloc F6.","ca. 70 %, sehr gut geeignet.":"aprox. 70 %, foarte bine adecvat.","ausreichend für Sequenzierung und Methylierungsprofil.":"suficient pentru secvențiere și profilare de metilare.","Eine fokale Bisulfit-PCR kann einzelne CpG-Loci untersuchen, ersetzt aber keinen genomeweiten CNS-Methylierungsclassifier.":"O PCR focală cu bisulfit poate examina loci CpG individuali, dar nu înlocuiește un clasificator de metilare CNS la nivel genomic.","IDH1/2-Status vollständig klären":"Clarificați complet statusul IDH1/2","CNS-Methylierungsprofil / Classifier":"Profil de metilare CNS / clasificator","IDH1-R132H-IHC negativ; Sequenzierung zeigt eine pathogene nicht-kanonische IDH1-p.R132C-Mutation. Die negative R132H-IHC war daher kein Ausschluss eines IDH-mutierten Glioms.":"IHC IDH1 R132H negativă; secvențierea arată o mutație patogenă non-canonică IDH1 p.R132C. IHC R132H negativă nu a exclus, așadar, un gliom IDH-mutant.","Methylierungsclassifier":"Clasificator de metilare","Genomeweites Methylierungsprofil mit hochkonfidenter Zuordnung zur Familie der IDH-mutierten Astrozytome und ausgeprägtem G-CIMP-typischem Hypermethylierungsmuster.":"Profil de metilare la nivel genomic cu încadrare de înaltă încredere în familia astrocitoamelor IDH-mutant și profil pronunțat de hipermetilare de tip G-CIMP.","Fokale Bisulfit-PCR":"PCR focală cu bisulfit","Ein fokaler Methylierungsmarker ist messbar, erlaubt aber keine gleichwertige globale Tumorklassifikation und ist kein Ersatz für den CNS-Methylierungsclassifier.":"Un marker focal de metilare poate fi măsurat, dar nu permite o clasificare globală echivalentă a tumorii și nu înlocuiește clasificatorul de metilare CNS.","Breites Panel":"Panel larg","Zusätzliche Varianten ändern die zentrale integrierte Einordnung nicht; der breite Ansatz ist für die konkrete Klassifikationsfrage nicht zwingend erforderlich.":"Variantele suplimentare nu schimbă clasificarea integrată centrală; o abordare largă nu este obligatorie pentru întrebarea specifică de clasificare.","Diffus infiltrierendes Astrozytom mit ATRX-Verlust und p53-Akkumulation; keine hochgradigen morphologischen Kriterien.":"Astrocitom difuz infiltrativ cu pierdere ATRX și acumulare p53; fără criterii morfologice high-grade.","Tumoranteil und DNA-Qualität für Sequenzierung und Methylom geeignet.":"Fracția tumorală și calitatea ADN adecvate pentru secvențiere și analiza metilomului.","Die negative IDH1-R132H-IHC schließt bei diesem jungen Patienten eine IDH-Mutation nicht aus. Die Sequenzierung weist eine nicht-kanonische IDH1-p.R132C-Mutation nach; das genomeweite Methylierungsprofil unterstützt einen IDH-mutierten astrozytären Tumor und zeigt das erwartete G-CIMP-artige Hypermethylierungsmuster. Der Methylierungsclassifier ergänzt die integrierte Diagnose, ersetzt aber nicht Histologie und definierende molekulare Marker.":"IHC IDH1 R132H negativă nu exclude o mutație IDH la acest pacient tânăr. Secvențierea identifică o mutație non-canonică IDH1 p.R132C; profilul genomic de metilare susține o tumoră astrocitară IDH-mutant și arată profilul de hipermetilare de tip G-CIMP așteptat. Clasificatorul de metilare completează diagnosticul integrat, dar nu înlocuiește histologia și markerii moleculari definitorii.","Teilbefund: Eine negative R132H-IHC allein reicht nicht, um den IDH-Status in diesem klinisch-morphologischen Kontext sicher festzulegen.":"Rezultat parțial: IHC R132H negativă singură nu este suficientă pentru a stabili cu certitudine statusul IDH în acest context clinic-morfologic.","R132H-IHC negativ nicht mit IDH1/2-Wildtyp gleichsetzen":"Nu echivalați IHC R132H negativă cu IDH1/2 wildtype","Bei passendem Kontext Sequenzierung nicht-kanonischer IDH1/2-Varianten einfordern":"În contextul potrivit, solicitați secvențierea variantelor IDH1/2 non-canonice","Methylierungsclassifier als integrativen Klassifikationsbaustein einordnen":"Încadrați clasificatorul de metilare ca element integrativ de diagnostic","G-CIMP als biologisches/epigenetisches Muster erklären, nicht als isolierten Routinetest":"Explicați G-CIMP ca profil biologic/epigenetic, nu ca test de rutină izolat","Falschaussage: negative R132H-IHC beweist IDH-Wildtyp":"Afirmație falsă: IHC R132H negativă dovedește IDH wildtype","Optimale Lösung: R132H-IHC als Screening verstehen, nicht-kanonische IDH1/2-Mutationen bei passendem Kontext sequenzieren und das Methylom als integrativen, nicht alleinstehenden Klassifikationsbaustein verwenden.":"Soluție optimă: înțelegeți IHC R132H ca screening, secvențiați mutațiile IDH1/2 non-canonice în contextul adecvat și utilizați metilomul ca element integrativ, nu de sine stătător, al clasificării.","Gliom":"Gliom","IDH1":"IDH1","non-canonical IDH":"IDH non-canonic","G-CIMP":"G-CIMP","Astrozytom":"Astrocitom","R132H negativ – aber nicht IDH-Wildtyp":"R132H negativ — dar nu IDH wildtype","Neuropathologie / Neuroonkologie / MTB":"Neuropatologie / Neuro-oncologie / MTB","IDH1-R132H-IHC als Screening und nicht als vollständigen IDH1/2-Ausschluss verstehen.":"Înțelegeți IHC IDH1 R132H ca screening, nu ca excludere completă a alterărilor IDH1/2.","Bei jungem Patienten und passender Morphologie nicht-kanonische IDH1/2-Varianten sequenzieren.":"La un pacient tânăr cu morfologie compatibilă, secvențiați variante IDH1/2 non-canonice.","G-CIMP als Folge der IDH-Biologie und nicht als isolierte Diagnose interpretieren.":"Interpretați G-CIMP ca o consecință a biologiei IDH, nu ca diagnostic izolat.","Genomeweiten Methylierungsclassifier von fokaler Methylierungs-PCR unterscheiden.":"Diferențiați un clasificator genomic de metilare de PCR focală de metilare.","Histologie, definierende Marker und Methylom zu einer integrierten Diagnose zusammenführen.":"Integrați histologia, markerii definitorii și metilomul într-un diagnostic integrat.","Die IDH1-R132H-IHC ist negativ. Der Patient ist aber 36, der Tumor sieht diffus astrozytär aus, ATRX ist verloren und 1p/19q intakt. Der vermeintlich einfache 'IDH-Wildtyp'-Stempel beginnt zu wackeln.":"IHC IDH1 R132H este negativă. Dar pacientul are 36 de ani, tumora pare difuz astrocitară, ATRX este pierdut, iar 1p/19q este intact. Eticheta aparent simplă „IDH-wildtype” începe să se clatine.","36-jähriger Patient mit linksfrontalem diffus infiltrierendem Gliom. R132H-IHC negativ, ATRX-Verlust und p53-Akkumulation. Das Board muss entscheiden, ob weiter sequenziert wird und wie ein G-CIMP-/Methylierungsprofil die integrierte Diagnose unterstützt.":"Bărbat de 36 de ani cu gliom difuz infiltrativ frontal stâng. IHC R132H negativă, pierdere ATRX și acumulare p53. Board-ul trebuie să decidă dacă se continuă secvențierea și cum susține un profil G-CIMP/de metilare diagnosticul integrat.","Screening ist nicht Sequenzierung":"Screeningul nu este secvențiere","R132H-IHC erkennt die häufigste IDH1-Variante, nicht jede IDH1/2-Mutation.":"IHC R132H detectează cea mai frecventă variantă IDH1, nu fiecare mutație IDH1/2.","Ein negatives mutationsspezifisches Antikörperergebnis ist kein vollständiger Gen-Ausschluss.":"Un rezultat negativ al unui anticorp specific unei mutații nu reprezintă o excludere completă la nivel de genă.","Alter + Morphologie zählen":"Vârsta + morfologia contează","Junger Erwachsener, diffus astrozytärer Tumor, ATRX-Verlust.":"Adult tânăr, tumoră difuz astrocitară, pierdere ATRX.","Prätestwahrscheinlichkeit bestimmt, wann Sequenzierung trotz negativer IHC sinnvoll ist.":"Probabilitatea pretest determină când este utilă secvențierea în ciuda IHC negative.","Epigenom als Integrator":"Epigenomul ca integrator","IDH-Mutationen erzeugen ein charakteristisches Hypermethylierungsprogramm.":"Mutațiile IDH generează un program caracteristic de hipermetilare.","Das Methylom unterstützt Klassifikation, ersetzt aber definierende Marker nicht.":"Metilomul susține clasificarea, dar nu înlocuiește markerii definitorii.","IDH1-R132H-IHC":"IHC IDH1 R132H","ATRX/p53":"ATRX/p53","ATRX-Verlust, diffuse p53-Akkumulation":"Pierdere ATRX, acumulare difuză p53","1p/19q":"1p/19q","keine Kodeletion":"fără codeleție","Tumoranteil ca. 70 %, DNA gut.":"Fracție tumorală aprox. 70 %, ADN de bună calitate.","Keine Materialnot – die Herausforderung ist Testhierarchie, nicht Schnittökonomie.":"Fără lipsă de material — provocarea este ierarhia testelor, nu economia secțiunilor.","Fokale Bisulfit-PCR ist kein Ersatz für genomeweite Klassifikation.":"PCR focală cu bisulfit nu înlocuiește clasificarea la nivel genomic.","Was ist der wichtigste Schluss aus negativer IDH1-R132H-IHC?":"Care este cea mai importantă concluzie din IHC IDH1 R132H negativă?","Bei passendem klinisch-morphologischem Kontext IDH1/2 sequenzieren, weil nicht-kanonische Mutationen übersehen werden können.":"În contextul clinic-morfologic adecvat, secvențiați IDH1/2 deoarece mutațiile non-canonice pot fi omise.","IDH-Wildtyp ist sicher bewiesen.":"IDH wildtype este dovedit cu certitudine.","Nur Methylierungsclassifier durchführen; Sequenzierung ist überflüssig.":"Efectuați doar clasificatorul de metilare; secvențierea este inutilă.","IDH ist bei Erwachsenen diagnostisch nicht relevant.":"IDH nu este relevant diagnostic la adulți.","R132H-IHC ist hoch nützlich, aber mutationsspezifisch.":"IHC R132H este foarte utilă, dar specifică mutației.","Was bedeutet ein G-CIMP-artiges Profil am ehesten?":"Ce înseamnă cel mai probabil un profil de tip G-CIMP?","Es ist ein epigenetisches Muster, das zur IDH-mutierten Biologie passt und die integrierte Klassifikation stützt.":"Este un profil epigenetic compatibil cu biologia IDH-mutant și susține clasificarea integrată.","Es definiert allein den WHO-Grad.":"Definește singur gradul WHO.","Es ist ein eigenständiger zugelassener Therapietest.":"Este un test terapeutic de sine stătător aprobat.","Es beweist eine Keimbahn-IDH-Mutation.":"Dovedește o mutație germinală IDH.","G-CIMP ist biologischer/klassifikatorischer Kontext, kein alleiniger Therapie- oder Gradmarker.":"G-CIMP este un context biologic/de clasificare, nu un marker de sine stătător pentru tratament sau grad.","Welche Aussage zum Methylierungsclassifier ist korrekt?":"Ce afirmație despre clasificatorul de metilare este corectă?","Genomeweites Profil kann diagnostisch stark sein, muss aber mit Histologie, QC und definierenden molekularen Markern integriert werden.":"Un profil genomic poate fi foarte puternic diagnostic, dar trebuie integrat cu histologia, QC și markerii moleculari definitorii.","Der höchste Klassenname ist immer die Diagnose.":"Numele clasei cu scorul cel mai mare este întotdeauna diagnosticul.","Eine fokale Bisulfit-PCR ist gleichwertig.":"O PCR focală cu bisulfit este echivalentă.","Methylom ersetzt IDH-Sequenzierung.":"Analiza metilomului înlocuiește secvențierea IDH.","Classifier ist stark, aber integrativ.":"Clasificatorul este puternic, dar integrativ.","Sequenzierung zeigt IDH1 p.R132C. Was kippt dadurch?":"Secvențierea arată IDH1 p.R132C. Ce se schimbă?","Der Tumor ist IDH-mutiert; die negative R132H-IHC war ein Screening-False-negative für diese nicht-kanonische Variante.":"Tumora este IDH-mutant; IHC R132H negativă a fost un fals negativ de screening pentru această variantă non-canonică.","Die Sequenzierung muss falsch sein, weil die IHC negativ war.":"Secvențierea trebuie să fie greșită deoarece IHC a fost negativă.","IDH-Status bleibt Wildtyp.":"Statusul IDH rămâne wildtype.","Es folgt Keimbahndiagnostik auf Lynch.":"Continuați cu testare germinală pentru sindrom Lynch.","Nicht-kanonische IDH-Varianten sind der zentrale Twist.":"Variantele IDH non-canonice sunt twist-ul central.","Formulieren Sie die integrierte neuropathologische Kernaussage und begründen Sie, warum nach negativer R132H-IHC sequenziert wurde und wie das Methylom gewichtet wird.":"Formulați concluzia neuropatologică integrată și explicați de ce s-a efectuat secvențierea după IHC R132H negativă și cum este ponderat metilomul.","R132H-IHC als Screening einordnen.":"Încadrați IHC R132H ca test de screening.","Nicht-kanonische IDH1/2-Sequenzierung bei hoher Prätestwahrscheinlichkeit durchführen.":"Efectuați secvențiere IDH1/2 pentru variante non-canonice când probabilitatea pretest este mare.","IDH1 p.R132C als definierenden Befund anerkennen.":"Recunoașteți IDH1 p.R132C ca rezultat definitoriu.","Methylierungsprofil/G-CIMP als konsistenten integrativen Baustein berichten.":"Raportați profilul de metilare/G-CIMP ca element integrativ concordant.","Fokale Methylierungs-PCR nicht als gleichwertigen Classifier-Ersatz darstellen.":"Nu prezentați PCR focală de metilare ca substitut echivalent pentru clasificator.","Auf Methylierungsclassifier verzichten, wenn Histologie und definierende molekulare Marker bereits eindeutig sind; in diesem Fall ist er didaktisch/klassifikatorisch zusätzlich hilfreich.":"Clasificatorul de metilare poate fi omis când histologia și markerii moleculari definitorii sunt deja neechivoci; în acest caz este suplimentar util didactic/clasificator.","Breites Panel nur bei zusätzlicher klinischer Fragestellung.":"Utilizați un panel larg doar dacă există o întrebare clinică suplimentară.","R132H-negativ = IDH-WT":"R132H negativ = IDH-WT","Mutationsspezifische IHC erfasst nicht alle IDH1/2-Varianten.":"IHC specifică unei mutații nu detectează toate variantele IDH1/2.","Classifier statt Sequenzierung":"Clasificator în loc de secvențiere","Definierende Genalteration und epigenetische Klasse sind unterschiedliche Ebenen.":"O alterare genetică definitorie și o clasă epigenetică sunt niveluri diferite de informație.","G-CIMP als Therapiebiomarker":"G-CIMP ca biomarker terapeutic","Das Muster ist biologisch/klassifikatorisch, nicht allein handlungsleitend.":"Profilul este biologic/clasificator, nu ghid de acțiune de sine stătător.","Der 'negative' IDH-Test wird positiv":"Testul IDH „negativ” devine pozitiv","Die Sequenzierung weist IDH1 p.R132C nach. Gleichzeitig ordnet der Methylierungsclassifier den Tumor hochkonfident der IDH-mutierten Astrozytomfamilie zu. Der Twist ist kein Laborwiderspruch, sondern zeigt die Grenze einer mutationsspezifischen IHC.":"Secvențierea identifică IDH1 p.R132C. În același timp, clasificatorul de metilare atribuie tumora cu încredere mare familiei astrocitoamelor IDH-mutant. Twist-ul nu este o contradicție de laborator, ci demonstrează limita IHC specifice unei mutații.","Er trainiert Prätestwahrscheinlichkeit, Methodengrenzen und integrierte CNS-Diagnostik.":"Antrenează probabilitatea pretest, limitele metodelor și diagnosticul CNS integrat.","Screeninggrenze erkannt":"Limita screeningului recunoscută","R132H-IHC negativ, IDH1 p.R132C sequenziert, Methylom konsistent mit IDH-mutiertem Astrozytom/G-CIMP.":"IHC R132H negativă, IDH1 p.R132C detectat prin secvențiere, metilom compatibil cu astrocitom IDH-mutant/G-CIMP.","Methoden korrekt hierarchisiert.":"Metodele au fost prioritizate corect.","Methylom richtig, IDH zu spät":"Metilom corect, IDH prea târziu","Classifier wird genutzt, die notwendige IDH1/2-Sequenzierung aber nicht sauber begründet.":"Clasificatorul este utilizat, dar secvențierea necesară IDH1/2 nu este justificată corespunzător.","Definierenden Marker nicht durch Epigenom ersetzen.":"Nu înlocuiți un marker definitoriu cu epigenomul.","IDH-Wildtyp abgestempelt":"Etichetat IDH-wildtype","Nach negativer R132H-IHC wird keine Sequenzierung veranlasst.":"Nu se solicită secvențiere după IHC R132H negativă.","Zentralen methodischen Fallstrick verpasst.":"Capcana metodologică centrală a fost omisă.","Nicht-kanonische IDH-Mutation":"Mutație IDH non-canonică","Integrierte Diagnose entsprechend IDH-mutierter Entität formulieren.":"Formulați diagnosticul integrat conform entității IDH-mutant.","Der Tumor verlässt den IDH-Wildtyp-Pfad.":"Tumora părăsește traseul IDH-wildtype.","Methylom diskordant":"Metilom discordant","QC, Tumoranteil und Differenzialdiagnose erneut prüfen.":"Reevaluați QC, fracția tumorală și diagnosticul diferențial.","Keine automatisierte Übersteuerung der Morphologie.":"Fără suprascriere automată a morfologiei.","IDH1-R132H-IHC ist ein sehr gutes Screening, aber kein vollständiger IDH1/2-Ausschluss.":"IHC IDH1 R132H este un screening excelent, dar nu o excludere completă IDH1/2.","Nicht-kanonische IDH-Mutationen sind besonders bei jüngeren Patienten mit passendem diffusem Gliom relevant.":"Mutațiile IDH non-canonice sunt deosebit de relevante la pacienții mai tineri cu context adecvat de gliom difuz.","IDH-Biologie erzeugt charakteristische epigenetische Muster wie G-CIMP.":"Biologia IDH produce profile epigenetice caracteristice precum G-CIMP.","Methylierungsclassifier sind integrative Diagnostikwerkzeuge, keine Orakel.":"Clasificatoarele de metilare sunt instrumente diagnostice integrative, nu oracole.","Fokale Methylierungs-PCR und genomeweiter Classifier beantworten unterschiedliche Fragen.":"PCR focală de metilare și un clasificator genomic răspund la întrebări diferite.","Bei diesem 36-jährigen Patienten darf die negative R132H-IHC nicht als vollständiger IDH-Wildtyp-Nachweis gelten. IDH1/2-Sequenzierung weist IDH1 p.R132C nach. Das Methylierungsprofil unterstützt die IDH-mutierte astrozytäre Klassifikation und zeigt ein G-CIMP-artiges Muster. Histologie, IDH, ATRX/p53/1p19q und Methylom werden integriert.":"La acest pacient de 36 de ani, IHC R132H negativă nu trebuie considerată dovadă completă de status IDH-wildtype. Secvențierea IDH1/2 detectează IDH1 p.R132C. Profilul de metilare susține clasificarea astrocitară IDH-mutant și arată un profil de tip G-CIMP. Histologia, IDH, ATRX/p53/1p19q și metilomul sunt integrate.","Screeninggrenze R132H-IHC":"Limita screeningului IHC R132H","nicht-kanonische Sequenzierung":"Secvențiere non-canonică","Classifier integrativ":"Clasificator integrativ","G-CIMP korrekt eingeordnet":"G-CIMP interpretat corect","Wann reicht R132H-IHC allein?":"Când este suficientă singură IHC R132H?","Warum ist Prätestwahrscheinlichkeit in der Molekularpathologie wichtig?":"De ce este importantă probabilitatea pretest în patologia moleculară?","Was kann ein Methylierungsclassifier, was eine fokale Bisulfit-PCR nicht kann?":"Ce poate face un clasificator de metilare și nu poate face o PCR focală cu bisulfit?","IDH1 p.R132C trotz negativer R132H-IHC":"IDH1 p.R132C în ciuda IHC R132H negative","Negativer Screeningtest ist nicht automatisch negativer Genstatus":"Un test de screening negativ nu înseamnă automat un status genetic negativ","R132H-IHC → Sequenzierung → Methylom → integrierte Diagnose":"IHC R132H → secvențiere → metilom → diagnostic integrat","Unklarer ZNS-Tumor: Der Methylierungsclassifier hilft – aber nur bei guter Probe":"Tumoră CNS neclară: clasificatorul de metilare ajută — dar doar cu o probă bună","Histologisch unklarer ZNS-Tumor: M…":"Tumoră CNS histologic neclară: m…","Neuropathologie / Neuroonkologisches Referenzboard":"Neuropatologie / Board de referință neuro-oncologic","47-jährige Patientin mit einem posterior-fossären Tumor. Histologie und IHC ergeben ein ungewöhnliches gliales/ependymales Mischbild; mehrere Differenzialdiagnosen bleiben plausibel.":"Pacientă de 47 de ani cu tumoră de fosă posterioară. Histologia și IHC arată un profil neobișnuit mixt glial/ependimal; mai multe diagnostice diferențiale rămân plauzibile.","Kann ein DNA-Methylierungsclassifier die Diagnose klären – und wann darf ein Classifier-Ergebnis gerade nicht überinterpretiert werden?":"Poate un clasificator de metilare ADN clarifica diagnosticul — și când nu trebuie în mod special supra-interpretat un rezultat al clasificatorului?","Die Referenzdiagnose beeinflusst Nachsorge und Therapieplanung.":"Diagnosticul de referință influențează urmărirea și planificarea tratamentului.","Schwindel, Gangunsicherheit und okzipitale Kopfschmerzen; MRT mit gut abgrenzbarer Raumforderung im Kleinhirn.":"Amețeli, instabilitate la mers și cefalee occipitală; RMN arată o formațiune cerebeloasă bine delimitată.","Voroperation":"Intervenție anterioară","Keine bekannte Tumorerkrankung.":"Fără boală tumorală cunoscută.","Pathologie":"Patologie","Morphologie uneindeutig; IHC nicht widersprüchlich, aber nicht ausreichend spezifisch.":"Morfologia este neclară; IHC nu este contradictorie, dar nu este suficient de specifică.","Ein Classifier-Score wird als maschinelles Wahrheitsurteil behandelt, unabhängig von Tumoranteil und Plausibilität.":"Un scor al clasificatorului este tratat ca adevăr al mașinii indiferent de fracția tumorală și plauzibilitate.","Piloide und stellenweise ependymale Architektur, fokale Gefäßhyalinisierung, keine eindeutige klassische Entität.":"Arhitectură piloidă și focal ependimală, hialinizare vasculară focală, fără entitate clasică neechivocă.","GFAP positiv; EMA nur fokal dot-like; OLIG2 heterogen; keine sichere Linie.":"GFAP pozitiv; EMA doar focal dot-like; OLIG2 heterogen; fără linie sigură.","Erste Differentialdiagnose":"Diagnostic diferențial inițial","Ependymom versus astrozytärer/piloider Tumor.":"Ependimom versus tumoră astrocitară/piloidă.","Genomeweites Methylierungsmuster und Copy-number-Kontext.":"Profil genomic de metilare și context copy-number.","Erster FFPE-Block enthält nur ca. 15 % Tumor und viel reaktives Kleinhirngewebe; zweiter Block enthält ca. 65 % Tumor.":"Primul bloc FFPE conține doar aproximativ 15 % tumoră și mult țesut cerebelos reactiv; al doilea bloc conține aproximativ 65 % tumoră.","beide Blöcke technisch extrahierbar.":"Ambele blocuri pot fi extrase tehnic.","Classifier-Risiko":"Risc al clasificatorului","Niedriger Tumoranteil kann den Score und das Profil verwässern.":"Fracția tumorală mică poate dilua scorul și profilul.","Eine fokale Bisulfit-PCR beantwortet nicht die globale Klassifikationsfrage.":"PCR focală cu bisulfit nu răspunde unei întrebări globale de clasificare.","Genomeweiter CNS-Methylierungsclassifier":"Clasificator genomic de metilare CNS","Classifier – Block mit wenig Tumor":"Clasificator — bloc cu puțină tumoră","Erste Analyse aus dem tumorarmen Block liefert nur eine niedrig-konfidente, biologisch wenig plausible Zuordnung unterhalb des lokal validierten Freigabebereichs. Kein belastbarer Klassenruf.":"Prima analiză din blocul cu puțină tumoră oferă doar o atribuire low-confidence, biologic puțin plauzibilă, sub intervalul local validat pentru raportare. Fără clasă fiabilă.","Classifier – tumorangereicherter Block":"Clasificator — bloc bogat în tumoră","Nach Auswahl des tumorreichen Blocks ergibt sich eine hochkonfidente Zuordnung zur Methylierungsfamilie 'High-grade astrocytoma with piloid features' mit passendem Copy-number-Profil.":"După selectarea blocului bogat în tumoră, rezultă o atribuire cu încredere mare la familia de metilare „High-grade astrocytoma with piloid features”, cu profil copy-number concordant.","Lokale CpG-Methylierung nachweisbar, aber diagnostisch nicht ausreichend zur genomeweiten Klassifikation.":"Metilarea CpG locală este detectabilă, dar insuficientă diagnostic pentru clasificarea genomică.","Molekulare Zusatzbefunde können die Plausibilität stützen, ersetzen aber bei diesem morphologisch schwierigen Fall den validierten Methylierungsclassifier nicht.":"Rezultatele moleculare suplimentare pot susține plauzibilitatea, dar nu înlocuiesc clasificatorul de metilare validat în acest caz morfologic dificil.","Histologisch uneindeutiger posterior-fossärer glialer Tumor.":"Tumoră glială de fosă posterioară histologic neclară.","Es stehen ein tumorarmer und ein deutlich tumorreicherer Block zur Verfügung.":"Este disponibil un bloc cu puțină tumoră și unul clar mai bogat în tumoră.","Der CNS-Methylierungsclassifier ist bei morphologisch unklaren Tumoren besonders wertvoll, sein Ergebnis muss aber zusammen mit Tumoranteil, QC, Score, Copy-number-Profil und Histologie bewertet werden. Der erste niedrig-konfidente Lauf aus tumorarmem Material ist nicht berichtsfähig; die Wiederholung aus tumorreichem Material liefert eine plausible hochkonfidente Klassifikation.":"Clasificatorul de metilare CNS este deosebit de valoros în tumorile morfologic neclare, dar rezultatul trebuie evaluat împreună cu fracția tumorală, QC, scorul, profilul copy-number și histologia. Primul run low-confidence din material sărac în tumoră nu este raportabil; repetarea din material bogat în tumoră oferă o clasificare plauzibilă cu încredere mare.","Teilbefund: Ein niedrig-konfidentes Classifier-Ergebnis aus tumorarmem Material darf nicht als definitive Diagnose ausgegeben werden.":"Rezultat parțial: un rezultat low-confidence al clasificatorului din material sărac în tumoră nu trebuie emis ca diagnostic definitiv.","Methylierungsclassifier gezielt bei diagnostisch schwierigem ZNS-Tumor einsetzen":"Utilizați țintit clasificatorul de metilare pentru o tumoră CNS diagnostic dificilă","Tumoranteil und Classifier-QC vor Klassenruf prüfen":"Verificați fracția tumorală și QC-ul clasificatorului înainte de a emite o clasă","Classifier mit Histologie und molekularen Zusatzdaten integrieren":"Integrați clasificatorul cu histologia și datele moleculare suplimentare","Bei unplausiblem Low-confidence-Ergebnis besseres Material wählen statt überinterpretieren":"Pentru un rezultat low-confidence neplauzibil, alegeți material mai bun în loc să îl supra-interpretați","Falschaussage: der höchste angezeigte Klassenname ist unabhängig vom Score die Diagnose":"Afirmație falsă: numele clasei cu scorul cel mai mare afișat este diagnosticul indiferent de scor","Optimale Lösung: Classifier als starken integrativen Diagnostikbaustein nutzen, aber nur aus geeignetem Material und mit validiertem Confidence-/QC-Kontext; ein Low-confidence-Ergebnis ist ein Hinweis, kein Wahrheitsurteil.":"Soluție optimă: utilizați clasificatorul ca un puternic element diagnostic integrativ, dar numai din material adecvat și într-un context validat de confidence/QC; un rezultat low-confidence este un indiciu, nu un verdict de adevăr.","ZNS":"CNS","Integrated diagnosis":"Diagnostic integrat","Der Classifier ist nur so gut wie Probe und Plausibilität":"Clasificatorul este doar atât de bun cât proba și plauzibilitatea","Neuropathologie / Molekulardiagnostik / MTB":"Neuropatologie / Diagnostic molecular / MTB","Indikationen für CNS-Methylierungsclassification bei diagnostisch schwierigen Tumoren erkennen.":"Recunoașteți indicațiile pentru clasificarea metilării CNS în tumorile diagnostic dificile.","Tumoranteil, QC und Confidence/Score vor Klassenruf prüfen.":"Verificați fracția tumorală, QC și confidence/scor înainte de emiterea unei clase.","Low-confidence-Ergebnisse nicht als definitive Diagnose ausgeben.":"Nu raportați rezultate low-confidence ca diagnostic definitiv.","Bei unplausiblem Ergebnis besseres Material priorisieren.":"Prioritizați material mai bun când rezultatul este neplauzibil.","Classifier, Copy-number-Profil, Histologie und Molekulargenetik integrieren.":"Integrați clasificatorul, profilul copy-number, histologia și genetica moleculară.","Der Computer liefert einen Klassennamen – aber aus einem Block mit nur 15 % Tumor und mit einem Score unterhalb des lokal validierten Freigabebereichs. Die Versuchung ist groß, den Namen trotzdem in den Befund zu schreiben.":"Computerul oferă un nume de clasă — dar dintr-un bloc cu doar 15 % tumoră și cu un scor sub intervalul local validat pentru raportare. Tentația de a scrie totuși numele în raport este mare.","47-jährige Patientin mit morphologisch uneindeutigem posterior-fossärem glialem Tumor. Zwei Blöcke unterscheiden sich massiv im Tumoranteil. Der Fall lehrt, wann Methylierungsclassification enorm hilfreich ist und wann ein scheinbares Ergebnis verworfen werden muss.":"Pacientă de 47 de ani cu tumoră glială de fosă posterioară morfologic neclară. Două blocuri diferă masiv prin fracția tumorală. Cazul arată când clasificarea prin metilare este extrem de utilă și când un rezultat aparent trebuie respins.","Unklare Morphologie":"Morfologie neclară","Ependymal/piloid/glial überlappende Merkmale.":"Caracteristici ependimale/piloide/gliale suprapuse.","Genau hier kann ein validierter classifier besonders wertvoll sein.":"Exact aici un clasificator validat poate fi deosebit de valoros.","Zwei Blöcke, zwei Welten":"Două blocuri, două lumi","15 % versus 65 % Tumoranteil.":"15 % versus 65 % fracție tumorală.","Preanalytics beeinflusst auch digitale/epigenetische Klassifikatoren.":"Preanalitica afectează și clasificatoarele digitale/epigenetice.","Score braucht Kontext":"Scorul are nevoie de context","Low confidence + unplausible Morphologie.":"Low confidence + morfologie neplauzibilă.","Ein Output ist noch kein reportable Result.":"Un output nu este încă un rezultat raportabil.","Block A":"Bloc A","ca. 15 % Tumor, viel normales Kleinhirngewebe":"aprox. 15 % tumoră, mult țesut cerebelos normal","Block B":"Bloc B","ca. 65 % Tumor":"aprox. 65 % tumoră","mehrere plausible ZNS-Differenzialdiagnosen":"Mai multe diagnostice diferențiale CNS plauzibile","Classifier aus geeignetem tumorreichem Material priorisieren.":"Prioritizați testarea clasificatorului din material adecvat bogat în tumoră.","Lokaler validierter Score-/QC-Rahmen ist Teil der Befundfreigabe.":"Cadrul local validat de scor/QC face parte din eliberarea raportului.","Fokale Bisulfit-PCR löst keine genomeweite Klassifikationsfrage.":"PCR focală cu bisulfit nu rezolvă o întrebare de clasificare genomică.","Wann ist der Methylierungsclassifier hier am wertvollsten?":"Când este cel mai valoros aici clasificatorul de metilare?","Bei persistierender diagnostischer Unsicherheit trotz Histologie/IHC und ausreichendem Material.":"Când incertitudinea diagnostică persistă în ciuda histologiei/IHC și există material suficient.","Immer als Ersatz für Histologie.":"Întotdeauna ca înlocuitor al histologiei.","Nur wenn eine medikamentöse Targettherapie existiert.":"Doar dacă există o terapie țintită.","Bei Erwachsenen grundsätzlich nicht.":"Niciodată la adulți.","Der größte Zusatznutzen entsteht bei schwierigen integrierten Diagnosen.":"Cel mai mare beneficiu suplimentar apare în diagnosticele integrate dificile.","Wie wird ein niedrig-konfidentes Ergebnis aus 15-%-Tumorblock behandelt?":"Cum trebuie gestionat un rezultat low-confidence dintr-un bloc cu 15 % tumoră?","Nicht definitiv reporten; QC/Tumoranteil prüfen und besseres Material analysieren.":"Nu raportați definitiv; verificați QC/fracția tumorală și analizați material mai bun.","Höchste Klasse trotzdem als Diagnose berichten.":"Raportați totuși clasa cea mai înaltă ca diagnostic.","Mit HE-Diagnose mitteln.":"Faceți media cu diagnosticul HE.","Score ist irrelevant.":"Scorul este irelevant.","Confidence und Präanalytik sind Teil der diagnostischen Aussage.":"Confidence și preanalitica fac parte din afirmația diagnostică.","Der tumorreiche Block liefert einen hochkonfidenten, morphologisch plausiblen Treffer. Was folgt?":"Blocul bogat în tumoră oferă un rezultat cu încredere mare și morfologic plauzibil. Ce urmează?","Mit Histologie und molekularen Zusatzdaten integrieren und als starke diagnostische Evidenz nutzen.":"Integrați-l cu histologia și datele moleculare suplimentare și utilizați-l ca dovadă diagnostică puternică.","Alle bisherigen Befunde verwerfen.":"Respingeți toate rezultatele anterioare.","Classifier immer ignorieren.":"Ignorați întotdeauna clasificatorul.","Erst eine fokale Bisulfit-PCR muss den Namen bestätigen.":"Mai întâi, o PCR focală cu bisulfit trebuie să confirme numele.","Plausible hochkonfidente Klassifikation ist stark, aber integriert.":"O clasificare plauzibilă cu încredere mare este puternică, dar integrată.","Warum ist das begleitende Copy-number-Profil nützlich?":"De ce este util profilul copy-number însoțitor?","Es kann die Klassenplausibilität stützen und zusätzliche diagnostische Muster liefern.":"Poate susține plauzibilitatea clasei și poate oferi profile diagnostice suplimentare.","Es beweist Keimbahnveränderungen.":"Dovedește alterări germinale.","Es ersetzt Histologie vollständig.":"Înlocuiește complet histologia.","Es ist immer ein zugelassener Therapietest.":"Este întotdeauna un test terapeutic aprobat.","Classifier und CN-Profil ergänzen die integrierte Diagnose.":"Clasificatorul și profilul CN completează diagnosticul integrat.","Entscheiden Sie, welcher Block analysiert und welches Classifier-Ergebnis reportet werden darf. Formulieren Sie die integrierte Diagnose mit klarer QC-Grenze.":"Decideți ce bloc trebuie analizat și ce rezultat al clasificatorului poate fi raportat. Formulați diagnosticul integrat cu o limită QC clară.","Morphologische Unsicherheit als legitime Classifier-Indikation erkennen.":"Recunoașteți incertitudinea morfologică drept indicație legitimă pentru clasificator.","Tumorarmen Block als Risikomaterial identifizieren.":"Identificați blocul cu puțină tumoră ca material cu risc.","Low-confidence-Ausgabe nicht als definitive Diagnose reporten.":"Nu raportați un output low-confidence ca diagnostic definitiv.","Tumorreichen Block analysieren.":"Analizați blocul bogat în tumoră.","Hochkonfidenten, plausiblen Classifier mit Morphologie/CN-Profil integrieren.":"Integrați rezultatul plauzibil cu încredere mare al clasificatorului cu morfologia/profilul CN.","Bei fehlendem besserem Material eine rein deskriptive/NEC-artige Diagnose mit Limitation statt erzwungenem Classifier-Call.":"Dacă nu există material mai bun, utilizați un diagnostic pur descriptiv/de tip NEC cu limitări, în loc să forțați un class call.","Referenzzentrum bei persistierender Diskordanz.":"Trimiteți la un centru de referință dacă discordanța persistă.","Highest score wins":"Câștigă scorul cel mai mare","Confidence, QC und Plausibilität werden ignoriert.":"Confidence, QC și plauzibilitatea sunt ignorate.","Classifier ersetzt Histologie":"Clasificatorul înlocuiește histologia","CNS-Diagnostik bleibt integriert.":"Diagnosticul CNS rămâne integrat.","Fokale Methylierung statt Methylom":"Metilare focală în loc de metilom","Lokaler Marker beantwortet eine andere Frage.":"Un marker local răspunde la o altă întrebare.","Der erste Classifier war technisch echt – diagnostisch trotzdem nicht gut genug":"Primul clasificator a fost tehnic real — dar diagnostic insuficient","Aus dem tumorarmen Block entsteht ein Low-confidence-Match. Erst der gezielte Wechsel auf den tumorreichen Block erzeugt eine hochkonfidente, morphologisch passende Klassifikation. Das Problem war nicht 'KI vs. Mensch', sondern Präanalytik und Freigabekriterien.":"Blocul sărac în tumoră produce un match low-confidence. Doar după trecerea intenționată la blocul bogat în tumoră apare o clasificare cu încredere mare și potrivită morfologic. Problema nu a fost „AI versus om”, ci preanalitica și criteriile de eliberare.","Der Fall macht deutlich, dass auch moderne Klassifikatoren klassische Labor-QC brauchen.":"Cazul arată clar că și clasificatoarele moderne necesită QC clasic de laborator.","QC vor Klassenname":"QC înainte de numele clasei","Low-confidence aus Block A verworfen; Block B liefert hochkonfidenten plausiblen Classifier-Match.":"Rezultatul low-confidence din blocul A este respins; blocul B oferă un match al clasificatorului plauzibil și cu încredere mare.","Classifier als Laborverfahren behandelt, nicht als Black Box.":"Clasificatorul este tratat ca metodă de laborator, nu ca black box.","Richtige Klasse, falscher Weg":"Clasa corectă, calea greșită","Klasse erkannt, aber der erste Low-score-Lauf wird nicht klar als nicht freigabefähig markiert.":"Clasa este recunoscută, dar primul run cu scor scăzut nu este marcat clar ca neeligibil pentru eliberare.","QA-Lernziel verfehlt.":"Obiectivul didactic QA a fost omis.","Low score reportet":"Scor scăzut raportat","Erster angezeigter Klassenname wird ungeprüft zur Diagnose.":"Primul nume de clasă afișat este preluat ca diagnostic fără verificare.","Kritischer Befundfreigabefehler.":"Eroare critică de eliberare a raportului.","Low-confidence / diskordant":"Low-confidence / discordant","Tumoranteil, DNA-QC, Referenzklasse und Materialauswahl prüfen.":"Verificați fracția tumorală, QC ADN, clasa de referință și selecția materialului.","Keine Scheinsicherheit.":"Fără falsă certitudine.","High-confidence + plausibel":"Încredere mare + plauzibil","In integrierte Diagnose übernehmen.":"Integrați în diagnosticul integrat.","Methylom liefert echten diagnostischen Mehrwert.":"Metilomul oferă valoare diagnostică adăugată reală.","Methylierungsclassifier sind besonders bei schwierigen ZNS-Tumoren leistungsfähig.":"Clasificatoarele de metilare sunt deosebit de performante în tumorile CNS dificile.","Tumoranteil und Probenqualität beeinflussen das Ergebnis.":"Fracția tumorală și calitatea probei influențează rezultatul.","Confidence/Score ist kein kosmetischer Parameter, sondern Teil der Befundfreigabe.":"Confidence/scorul nu este cosmetic; face parte din eliberarea raportului.","Ein niedriger Score kann korrekt gerechnet und trotzdem diagnostisch nicht ausreichend sein.":"Un scor scăzut poate fi calculat corect și totuși insuficient diagnostic.","Moderne Klassifikation funktioniert nur integriert mit Pathologie und Molekulargenetik.":"Clasificarea modernă funcționează doar integrată cu patologia și genetica moleculară.","Der erste Lauf aus tumorarmem Material ist trotz angezeigtem Klassennamen nicht freigabefähig. Nach Analyse des tumorreichen Blocks entsteht eine hochkonfidente, morphologisch und genomisch plausible Klassifikation. Diese wird als starker integrativer Diagnostikbaustein genutzt.":"Primul run din material sărac în tumoră nu este eliberabil, în ciuda numelui de clasă afișat. Analiza blocului bogat în tumoră produce apoi o clasificare cu încredere mare, plauzibilă morfologic și genomic. Aceasta este utilizată ca element diagnostic integrativ puternic.","QC/Confidence":"QC/Confidence","Materialauswahl":"Selecția materialului","integrative Diagnose":"Diagnostic integrat","kein Black-box-Overcalling":"Fără overcalling de tip black box","Welche Mindest-QC braucht ein Classifier in Ihrem Labor?":"Ce QC minim necesită un clasificator în laboratorul dumneavoastră?","Wie berichtet man Low-confidence-Ergebnisse?":"Cum trebuie raportate rezultatele low-confidence?","Wann ist 'kein Klassenruf' die bessere Diagnose?":"Când este „fără clasă” diagnosticul mai bun?","Low-confidence aus falschem Block":"Low confidence din blocul greșit","Classifier braucht Labor-QC wie jede andere Methode":"Un clasificator are nevoie de QC de laborator ca orice altă metodă","Morphologische Unsicherheit → Materialwahl → Classifier-QC → integrierter Call":"Incertitudine morfologică → selecția materialului → QC clasificator → call integrat","DNMT3A/TET2/ASXL1 bei Zytopenie: CHIP, CCUS oder MDS?":"DNMT3A/TET2/ASXL1 cu citopenie: CHIP, CCUS sau MDS?","MDS/AML mit DNMT3A/TET2/ASXL1":"MDS/AML cu DNMT3A/TET2/ASXL1","Hämatologie / Molekulares Board":"Hematologie / Board molecular","74-jähriger Patient mit seit neun Monaten persistierender makrozytärer Anämie und milder Thrombozytopenie. Im peripheren Blut wurden DNMT3A- und TET2-Varianten gefunden.":"Bărbat de 74 de ani cu anemie macrocitară persistentă și trombocitopenie ușoară de nouă luni. În sângele periferic au fost detectate variante DNMT3A și TET2.","Beweisen diese Mutationen bereits ein MDS – oder handelt es sich um CHIP?":"Aceste mutații dovedesc deja un MDS — sau este vorba de CHIP?","Die Diagnose soll vor Einleitung einer krankheitsspezifischen Therapie geklärt werden.":"Diagnosticul trebuie clarificat înainte de inițierea unei terapii specifice bolii.","Hb 9,8 g/dl, MCV erhöht, Thrombozyten 115/nl; Leukozyten normal.":"Hb 9,8 g/dl, MCV crescut, trombocite 115/nl; leucocite normale.","Sekundäre Ursachen":"Cauze secundare","Vitaminmangel, relevante Blutung, Niereninsuffizienz und Medikamente als Hauptursache weitgehend ausgeschlossen.":"Deficitul vitaminic, hemoragia relevantă, insuficiența renală și medicamentele au fost în mare parte excluse ca principală cauză.","Blut-NGS: DNMT3A p.R882H VAF 12 %, TET2 Frameshift VAF 8 %.":"NGS din sânge: DNMT3A p.R882H VAF 12 %, TET2 frameshift VAF 8 %.","Mutationen typischer CH-Gene werden mit einer definierten myeloischen Neoplasie gleichgesetzt.":"Mutațiile genelor tipice de CH sunt echivalate cu o neoplazie mieloidă definită.","Knochenmark + Vorinformation":"Măduvă osoasă + informații anterioare","Normo- bis leicht hyperzellulär; Dysplasie unterhalb diagnostischer Schwelle, Blasten 2 %.":"Normocelulară până la ușor hipercelulară; displazie sub pragul diagnostic, blaști 2 %.","Kein MDS-definierender Befund.":"Fără rezultat definitoriu pentru MDS.","Flow":"Flow","Kein eindeutiger aberranter Blastenphänotyp.":"Fără fenotip aberant neechivoc al blaștilor.","Wie werden persistierende Zytopenie und klonale Mutationen zusammengeführt?":"Cum trebuie integrate citopenia persistentă și mutațiile clonale?","Knochenmarkaspirat + Stanze sowie EDTA-Blut.":"Aspirat medular + biopsie și sânge EDTA.","ausreichende Tiefe zur VAF-Beurteilung.":"Adâncime suficientă pentru evaluarea VAF.","CHIP setzt definitionsgemäß das Fehlen einer anderweitig ungeklärten Zytopenie voraus.":"Prin definiție, CHIP presupune absența unei citopenii altfel neexplicate.","Ein breites Pan-Cancer-Panel schafft nicht automatisch mehr diagnostische Sicherheit als eine integrierte hämatologische Bewertung.":"Un panel pan-cancer larg nu creează automat mai multă certitudine diagnostică decât o evaluare hematologică integrată.","Knochenmark-/Morphologiekontext":"Context măduvă osoasă/morfologie","Klonale Hämatopoese / Myeloid-Panel":"Hematopoieză clonală / panel mieloid","Persistierende Zytopenie, aber keine ausreichende Dysplasie, keine erhöhte Blastenzahl und kein morphologisch definierendes MDS-Kriterium.":"Citopenie persistentă, dar displazie insuficientă, fără creșterea blaștilor și fără criteriu morfologic definitoriu pentru MDS.","Myeloid-Panel":"Panel mieloid","DNMT3A p.R882H (VAF 12 %) und TET2 Frameshift (VAF 8 %); keine TP53-Alteration im untersuchten Panel. Klonalität ist belegt, eine MDS-Diagnose dadurch allein jedoch nicht.":"DNMT3A p.R882H (VAF 12 %) și TET2 frameshift (VAF 8 %); fără alterare TP53 în panelul testat. Clonalitatea este dovedită, dar acest lucru singur nu stabilește un MDS.","Zusätzliche unspezifische Varianten erhöhen die Informationsmenge, lösen aber die diagnostische Abgrenzung nicht ohne Blutbild, Morphologie und definierende Kriterien.":"Variantele suplimentare nespecifice cresc cantitatea de informație, dar nu rezolvă delimitarea diagnostică fără hemogramă, morfologie și criterii definitorii.","Persistierende, anderweitig nicht erklärte Anämie und Thrombozytopenie.":"Anemie și trombocitopenie persistente, altfel neexplicate.","Keine ausreichenden morphologischen oder genetischen Kriterien für eine manifeste myeloische Neoplasie.":"Fără criterii morfologice sau genetice suficiente pentru o neoplazie mieloidă manifestă.","Die DNMT3A- und TET2-Mutationen belegen klonale Hämatopoese, definieren aber allein kein MDS. Weil gleichzeitig persistierende ungeklärte Zytopenien bestehen, ist 'CHIP' nicht die passende Kategorie; bei fehlenden diagnostischen MDS-Kriterien passt die Konstellation zu einer klonalen Zytopenie unklarer Signifikanz (CCUS). Verlauf und erneute Abklärung bei Progression sind wichtiger als ein vorschnelles Neoplasie-Label.":"Mutațiile DNMT3A și TET2 dovedesc hematopoieză clonală, dar nu definesc singure un MDS. Deoarece există și citopenii persistente neexplicate, „CHIP” nu este categoria potrivită; în absența criteriilor diagnostice de MDS, constelația se potrivește unei citopenii clonale cu semnificație nedeterminată (CCUS). Urmărirea și reevaluarea la progresie sunt mai importante decât o etichetă prematură de neoplazie.","Teilbefund: Mutationen in DNMT3A/TET2/ASXL1 können bei CHIP, CCUS und myeloischen Neoplasien vorkommen; die Diagnose entsteht erst aus Klinik, Blutbild, Morphologie und Genetik zusammen.":"Rezultat parțial: mutațiile DNMT3A/TET2/ASXL1 pot apărea în CHIP, CCUS și neoplazii mieloide; diagnosticul rezultă doar din integrarea contextului clinic, hemogramei, morfologiei și geneticii.","Klonale Mutation nicht mit MDS gleichsetzen":"Nu echivalați o mutație clonală cu MDS","CHIP nur ohne ungeklärte Zytopenie verwenden":"Utilizați CHIP doar în absența unei citopenii neexplicate","CCUS als passende Zwischenkategorie bei Zytopenie + Klon ohne MDS-Kriterien erkennen":"Recunoașteți CCUS ca o categorie intermediară adecvată pentru citopenie + clonă fără criterii MDS","Verlaufskontrolle und erneute KM-Diagnostik bei Dynamik einplanen":"Planificați urmărirea și reevaluarea măduvei osoase dacă tabloul evoluează","Falschaussage: DNMT3A/TET2 beweisen eine hämatologische Neoplasie":"Afirmație falsă: DNMT3A/TET2 dovedesc o neoplazie hematologică","Optimale Lösung: DNMT3A/TET2 zeigen einen Klon; Zytopenie verhindert die CHIP-Bezeichnung, fehlende MDS-definierende Kriterien verhindern die MDS-Diagnose – damit ist CCUS die saubere integrierte Einordnung.":"Soluție optimă: DNMT3A/TET2 demonstrează o clonă; citopenia împiedică eticheta CHIP, iar lipsa criteriilor definitorii pentru MDS împiedică diagnosticul de MDS — ceea ce face CCUS clasificarea integrată corectă.","Hämatologie":"Hematologie","DNMT3A":"DNMT3A","TET2":"TET2","CHIP":"CHIP","CCUS":"CCUS","MDS":"MDS","Clonal hematopoiesis":"Hematopoieză clonală","Der Klon ist echt – die Neoplasie noch nicht":"Clona este reală — neoplazia încă nu","Hämatopathologie / Hämatologie / MTB":"Hematopatologie / Hematologie / MTB","DNMT3A/TET2/ASXL1-Mutationen als häufige Klone und nicht als automatische MDS-Diagnose erkennen.":"Recunoașteți mutațiile DNMT3A/TET2/ASXL1 ca clone frecvente, nu ca diagnostic automat de MDS.","CHIP, CCUS und MDS anhand von Zytopenie und diagnostischen Kriterien trennen.":"Diferențiați CHIP, CCUS și MDS folosind citopenia și criteriile diagnostice.","VAF/Klonalität als Kontext, nicht als alleinige Entitätsdefinition verwenden.":"Utilizați VAF/clonalitatea ca context, nu ca definiție unică a unei entități.","Morphologie und Blutbild gegenüber 'Genetik allein' priorisieren.":"Prioritizați morfologia și hemograma față de „genetica singură”.","Verlaufskontrolle als Teil einer ehrlichen diagnostischen Strategie verstehen.":"Înțelegeți urmărirea ca parte a unei strategii diagnostice oneste.","Zwei pathogene Mutationen stehen schwarz auf weiß im NGS-Bericht. Der Reflex lautet: 'Dann hat er MDS.' Das Knochenmark liefert aber keine ausreichenden Kriterien – und die persistierende Zytopenie macht gleichzeitig 'CHIP' falsch.":"Două mutații patogene apar clar în raportul NGS. Reflexul este: „Atunci are MDS.” Dar măduva osoasă nu îndeplinește criterii suficiente — iar citopenia persistentă face simultan incorectă eticheta „CHIP”.","74-jähriger Patient mit ungeklärter makrozytärer Anämie und Thrombozytopenie. DNMT3A und TET2 sind mutiert, das Knochenmark bleibt jedoch unterhalb diagnostischer MDS-Schwellen. Gesucht ist die richtige Kategorie zwischen benignem Zufallsbefund und manifester Neoplasie.":"Bărbat de 74 de ani cu anemie macrocitară și trombocitopenie neexplicate. DNMT3A și TET2 sunt mutate, dar măduva osoasă rămâne sub pragurile diagnostice pentru MDS. Sarcina este identificarea categoriei corecte între un rezultat incidental benign și neoplazia manifestă.","Klonalität ist bewiesen":"Clonalitatea este dovedită","DNMT3A 12 %, TET2 8 % VAF.":"DNMT3A 12 %, TET2 8 % VAF.","Ein Klon ist nicht automatisch eine Neoplasie.":"O clonă nu este automat o neoplazie.","Zytopenie ist real":"Citopenia este reală","Persistierende Anämie + Thrombozytopenie ohne klare Sekundärursache.":"Anemie persistentă + trombocitopenie fără cauză secundară clară.","Damit passt die Definition von CHIP gerade nicht.":"Prin urmare, definiția CHIP nu se potrivește.","MDS-Kriterien fehlen":"Criteriile MDS lipsesc","Blasten 2 %, Dysplasie unter Schwelle, keine definierende Genetik.":"Blaști 2 %, displazie sub prag, fără genetică definitorie.","CCUS ist eine sinnvolle Zwischenkategorie.":"CCUS este o categorie intermediară utilă.","Hb 9,8 g/dl; Thrombozyten 115/nl":"Hb 9,8 g/dl; trombocite 115/nl","DNMT3A p.R882H 12 %, TET2 Frameshift 8 %":"DNMT3A p.R882H 12 %, TET2 frameshift 8 %","keine ausreichende Dysplasie, Blasten 2 %":"Displazie insuficientă, blaști 2 %","Knochenmarkmorphologie ist unverzichtbar.":"Morfologia măduvei osoase este indispensabilă.","Breites Pan-Cancer-NGS kann die Kategorie nicht ohne klinisch-hämatologischen Kontext definieren.":"NGS pan-cancer larg nu poate defini categoria fără context clinic-hematologic.","Verlauf ist diagnostisch relevant, wenn Kriterien heute noch nicht erfüllt sind.":"Evoluția în timp este relevantă diagnostic când criteriile nu sunt încă îndeplinite.","Was beweisen DNMT3A/TET2 hier?":"Ce dovedesc aici DNMT3A/TET2?","Klonale Hämatopoese.":"Hematopoieză clonală.","Sicher ein MDS.":"Sigur MDS.","Sicher AML.":"Sigur AML.","Eine Keimbahnerkrankung.":"O afecțiune germinală.","Diese Gene überlappen stark zwischen CH, CCUS und myeloischen Neoplasien.":"Aceste gene se suprapun considerabil între CH, CCUS și neoplaziile mieloide.","Warum ist 'CHIP' hier unpassend?":"De ce este „CHIP” nepotrivit aici?","Weil persistierende anderweitig ungeklärte Zytopenien bestehen.":"Pentru că există citopenii persistente, altfel neexplicate.","Weil der Patient älter als 70 ist.":"Pentru că pacientul are peste 70 de ani.","Weil zwei Mutationen vorliegen.":"Pentru că sunt prezente două mutații.","Weil VAF über 5 % liegt.":"Pentru că VAF este peste 5 %.","CHIP setzt gerade das Fehlen entsprechender ungeklärter Zytopenien voraus.":"CHIP presupune în mod specific absența citopeniilor neexplicate corespunzătoare.","Welche Kategorie passt bei Zytopenie + Klon ohne MDS-definierende Kriterien am besten?":"Ce categorie se potrivește cel mai bine pentru citopenie + clonă fără criterii definitorii MDS?","CCUS.":"CCUS.","CHIP.":"CHIP.","AML.":"AML.","Normalbefund.":"Rezultat normal.","CCUS beschreibt genau diese Zwischenkonstellation.":"CCUS descrie exact această constelație intermediară.","Was ist die sinnvollste nächste Strategie?":"Care este cea mai potrivită strategie următoare?","Klinisch/hämatologisch monitoren und bei Dynamik erneut Knochenmark/Molekulargenetik bewerten.":"Monitorizați clinic/hematologic și reevaluați măduva osoasă/genetica moleculară dacă există progresie.","Sofort MDS-Therapie allein wegen DNMT3A/TET2.":"Începeți imediat terapia MDS doar pe baza DNMT3A/TET2.","Keine weitere Kontrolle.":"Fără urmărire suplimentară.","Automatisch Keimbahntest für DNMT3A/TET2.":"Efectuați automat testare germinală pentru DNMT3A/TET2.","Diagnostische Ehrlichkeit plus Verlauf ist hier angemessen.":"Onestitatea diagnostică plus urmărirea sunt adecvate aici.","Ordnen Sie den Fall zwischen CHIP, CCUS und MDS ein und formulieren Sie, welche Information die Mutationen liefern – und welche nicht.":"Încadrați cazul între CHIP, CCUS și MDS și formulați ce informație oferă mutațiile — și ce nu oferă.","Klonalität anerkennen.":"Recunoașteți clonalitatea.","Persistierende ungeklärte Zytopenie berücksichtigen.":"Luați în considerare citopenia persistentă neexplicată.","Fehlende MDS-definierende Morphologie/Genetik benennen.":"Menționați absența morfologiei/geneticii definitorii pentru MDS.","CHIP ausschließen, weil Zytopenie vorhanden.":"Excludeți CHIP deoarece există citopenie.","CCUS als passendste aktuelle Kategorie formulieren.":"Formulați CCUS ca cea mai potrivită categorie actuală.","Verlaufskontrolle/erneute Diagnostik bei Progression empfehlen.":"Recomandați urmărire/reevaluare dacă apare progresie.","Bei später neu auftretenden definierenden Kriterien Re-Klassifikation zur myeloischen Neoplasie.":"Dacă apar ulterior criterii definitorii, reclasificați ca neoplazie mieloidă.","Bei identifizierter sekundärer Zytopenieursache Neubewertung der CCUS-Einordnung.":"Dacă se identifică o cauză secundară a citopeniei, reevaluați clasificarea CCUS.","Mutation = MDS":"Mutație = MDS","CH-Gene sind nicht krankheitsspezifisch.":"Genele CH nu sunt specifice bolii.","Alles CHIP":"Totul este CHIP","Persistierende ungeklärte Zytopenie widerspricht CHIP.":"Citopenia persistentă neexplicată este incompatibilă cu CHIP.","Mehr Panel = mehr Diagnose":"Mai mult panel = mai mult diagnostic","Diagnosekriterien bleiben klinisch-morphologisch integriert.":"Criteriile diagnostice rămân integrate clinic și morfologic.","Der richtige Befund ist die Zwischenkategorie":"Rezultatul corect este categoria intermediară","Die Mutationen sind echt und klinisch relevant, aber weder 'Zufalls-CHIP' noch bereits diagnostisches MDS. Die Zytopenie verschiebt den Fall in CCUS – ein Ergebnis, das weniger endgültig klingt, aber fachlich präziser ist.":"Mutațiile sunt reale și relevante clinic, dar nu reprezintă nici „CHIP incidental”, nici încă MDS diagnostic. Citopenia mută cazul în CCUS — un rezultat care sună mai puțin definitiv, dar este mai precis.","Er trainiert, diagnostische Unsicherheit korrekt zu benennen statt molekulare Befunde zu overcallen.":"Antrenează capacitatea de a numi corect incertitudinea diagnostică în loc de a overcalla rezultatele moleculare.","CCUS sauber erkannt":"CCUS recunoscut corect","Zytopenie + DNMT3A/TET2-Klon, aber keine MDS-definierenden Kriterien → CCUS.":"Citopenie + clonă DNMT3A/TET2, dar fără criterii definitorii MDS → CCUS.","Klon, Klinik und Morphologie korrekt integriert.":"Clona, contextul clinic și morfologia au fost integrate corect.","CH erkannt, Kategorie unscharf":"CH recunoscută, categorie neclară","MDS wird vermieden, aber trotz Zytopenie 'CHIP' berichtet.":"MDS este evitat, dar în ciuda citopeniei cazul este raportat ca 'CHIP'.","Definition nicht sauber angewendet.":"Definiția nu este aplicată corect.","NGS diagnostiziert MDS":"NGS diagnostichează MDS","DNMT3A/TET2 werden allein als MDS-Beweis verwendet.":"DNMT3A/TET2 sunt folosite singure ca dovadă pentru MDS.","Molekulares Overcalling.":"Suprainterpretare moleculară.","Zytopenien verschlechtern sich":"Citopeniile se agravează","Erneute Knochenmarkdiagnostik inklusive Morphologie/Genetik.":"Repetarea evaluării măduvei osoase, inclusiv morfologie/genetică.","Progression kann neue definierende Kriterien sichtbar machen.":"Progresia poate evidenția noi criterii definitorii.","Stabiler Verlauf":"Evoluție stabilă","Strukturiertes Monitoring.":"Monitorizare structurată.","Keine unnötige Neoplasietherapie.":"Fără tratament inutil pentru neoplazie.","DNMT3A/TET2/ASXL1 sind häufige Gene klonaler Hämatopoese.":"DNMT3A/TET2/ASXL1 sunt gene frecvente în hematopoieza clonală.","CHIP, CCUS und MDS teilen molekulare Befunde; Kontext trennt die Kategorien.":"CHIP, CCUS și MDS împărtășesc constatări moleculare; contextul separă categoriile.","CHIP ohne ungeklärte Zytopenie, CCUS mit Zytopenie aber ohne definierende Neoplasiekriterien.":"CHIP fără citopenie neexplicată, CCUS cu citopenie dar fără criterii definitorii de neoplazie.","NGS erhöht Sensitivität für Klonalität, nicht automatisch Spezifität für MDS.":"NGS crește sensibilitatea pentru clonalitate, nu automat specificitatea pentru MDS.","Verlauf kann Teil der Diagnostik sein.":"Evoluția în timp poate face parte din procesul diagnostic.","Die Mutationen belegen einen myeloischen Klon. Wegen persistierender ungeklärter Zytopenien ist CHIP unpassend; wegen fehlender MDS-definierender Morphologie/Genetik ist ein MDS derzeit nicht gesichert. Die präziseste Einordnung ist CCUS mit strukturierter Verlaufskontrolle.":"Mutațiile demonstrează o clonă mieloidă. Din cauza citopeniilor persistente neexplicate, CHIP este nepotrivit; în absența morfologiei/geneticii definitorii pentru MDS, MDS nu este în prezent demonstrat. Cea mai precisă încadrare este CCUS cu monitorizare structurată.","Mutation ≠ Neoplasie":"Mutație ≠ neoplazie","CHIP vs CCUS":"CHIP vs CCUS","Morphologie integriert":"Morfologie integrată","Monitoring":"Monitorizare","Welche Mutationen erhöhen die Progressionswahrscheinlichkeit stärker?":"Care mutații cresc mai mult probabilitatea de progresie?","Wie verändert VAF die Risikoeinschätzung, ohne die Diagnose allein zu definieren?":"Cum modifică VAF evaluarea riscului fără a defini singură diagnosticul?","Wann wiederholt man das Knochenmark?":"Când trebuie repetată evaluarea măduvei osoase?","CCUS statt binärer CHIP/MDS-Antwort":"CCUS în locul unui răspuns binar CHIP/MDS","Klonalität und Neoplasie sind nicht dasselbe":"Clonalitatea și neoplazia nu sunt același lucru","Zytopenie → Klon → Morphologie → CCUS/MDS-Entscheidung":"Citopenie → clonă → morfologie → decizie CCUS/MDS","MSI-H-CRC mit MLH1/PMS2-Verlust: BRAF-Wildtyp ist noch kein Lynch-Syndrom":"CRC MSI-H cu pierdere MLH1/PMS2: BRAF wild type nu înseamnă încă sindrom Lynch","MLH1-Promotor-Methylierung bei MSI…":"Metilarea promotorului MLH1 în MSI…","Viszeralonkologie / Humangenetik-Screening":"Oncologie viscerală / screening genetic","71-jährige Patientin mit rechtsseitigem Kolonkarzinom. Universal-Screening zeigt Verlust von MLH1/PMS2 und MSI-H.":"Pacientă de 71 de ani cu cancer de colon drept. Screeningul universal arată pierderea MLH1/PMS2 și MSI-H.","Ist bei BRAF-Wildtyp nun automatisch von Lynch-Syndrom auszugehen – oder fehlt noch der entscheidende epigenetische Reflex?":"BRAF wild type înseamnă acum automat sindrom Lynch sau lipsește încă reflexul epigenetic decisiv?","Der Tumorbefund soll therapeutisch und hereditär korrekt eingeordnet werden.":"Rezultatul tumoral trebuie încadrat corect atât terapeutic, cât și ereditar.","Rechtsseitiges, lymphozytenreiches Adenokarzinom.":"Adenocarcinom drept, bogat în limfocite.","Familie":"Istoric familial","Keine auffällige Häufung Lynch-assoziierter Tumoren dokumentiert.":"Nu este documentată o agregare familială evidentă de tumori asociate Lynch.","MLH1/PMS2-Verlust, MSI-H; BRAF V600E nicht nachweisbar.":"Pierdere MLH1/PMS2, MSI-H; BRAF V600E nedetectat.","BRAF-Wildtyp wird fälschlich als positiver Lynch-Nachweis interpretiert.":"BRAF wild type este interpretat greșit ca dovadă pozitivă pentru sindromul Lynch.","Mäßig differenziertes Adenokarzinom mit medullär/lymphozytenreichen Anteilen.":"Adenocarcinom moderat diferențiat cu zone medulare/bogate în limfocite.","MLH1 und PMS2 verloren; MSH2/MSH6 erhalten.":"MLH1 și PMS2 pierdute; MSH2/MSH6 păstrate.","MSI-high bestätigt.":"MSI-high confirmat.","Somatische MLH1-Promotor-Methylierung als Ursache der MLH1-Inaktivierung.":"Metilarea somatică a promotorului MLH1 ca explicație pentru inactivarea MLH1.","FFPE-Resektat mit hohem Tumoranteil.":"Piesă de rezecție FFPE cu conținut tumoral ridicat.","Methylierung":"Metilare","gezielter validierter MLH1-Promotor-Assay möglich.":"Este posibil un test țintit și validat pentru promotorul MLH1.","Wildtyp – informativ, aber nicht beweisend für Lynch.":"Wild type — informativ, dar nu dovadă pentru sindromul Lynch.","Ein negatives Ausschlussmerkmal darf nicht in einen positiven hereditären Nachweis umgedeutet werden.":"Un marker negativ de excludere nu trebuie reinterpretat ca dovadă ereditară pozitivă.","MLH1-Promotor-Methylierung":"Metilarea promotorului MLH1","Verlust von MLH1/PMS2 bei erhaltener MSH2/MSH6-Expression.":"Pierdere MLH1/PMS2 cu expresie MSH2/MSH6 păstrată.","MSI-high bestätigt; damit besteht ein therapeutisch relevanter dMMR/MSI-H-Kontext.":"MSI-high confirmat; există astfel un context dMMR/MSI-H relevant terapeutic.","BRAF V600E nicht nachweisbar. Das entfernt ein starkes Indiz für sporadische MLH1-Inaktivierung, beweist Lynch aber nicht.":"BRAF V600E nedetectat. Aceasta elimină un indiciu puternic pentru inactivarea sporadică a MLH1, dar nu dovedește sindromul Lynch.","Deutliche MLH1-Promotor-Hypermethylierung. Die Konstellation spricht bei dieser 71-jährigen Patientin stark für eine sporadische epigenetische MLH1-Silenzierung; klinische/familiäre Auffälligkeiten bleiben dennoch zu berücksichtigen.":"Hipermetilare marcată a promotorului MLH1. La această pacientă de 71 de ani, constelația susține puternic o silențiere epigenetică sporadică a MLH1; particularitățile clinice și familiale trebuie totuși luate în considerare.","Kernbefund":"Constatare-cheie","dMMR/MSI-H durch MLH1/PMS2-Verlust.":"dMMR/MSI-H prin pierderea MLH1/PMS2.","Wildtyp – kein Lynch-Beweis.":"Wild type — nu reprezintă dovadă pentru sindromul Lynch.","Der dMMR/MSI-H-Status ist therapeutisch relevant. Für die hereditäre Einordnung zeigt der MLH1/PMS2-Verlust zunächst nur die Richtung der Reflexdiagnostik. BRAF-Wildtyp beweist kein Lynch-Syndrom. Die nachgewiesene MLH1-Promotor-Hypermethylierung spricht stark für eine sporadische epigenetische MLH1-Inaktivierung; Alter, Familienanamnese und besondere klinische Konstellationen können dennoch eine weitergehende humangenetische Beurteilung rechtfertigen.":"Statusul dMMR/MSI-H este relevant terapeutic. Pentru încadrarea ereditară, pierderea MLH1/PMS2 indică inițial doar direcția testării reflexe. BRAF wild type nu dovedește sindromul Lynch. Hipermetilarea detectată a promotorului MLH1 susține puternic o inactivare epigenetică sporadică a MLH1; vârsta, istoricul familial și constelațiile clinice speciale pot totuși justifica o evaluare genetică suplimentară.","Teilbefund: MLH1/PMS2-Verlust + MSI-H ist nicht synonym mit Lynch; die Ursache der MLH1-Inaktivierung muss reflexdiagnostisch geklärt werden.":"Rezultat parțial: pierderea MLH1/PMS2 + MSI-H nu este sinonimă cu sindromul Lynch; cauza inactivării MLH1 trebuie clarificată prin testare reflexă.","dMMR/MSI-H therapeutisch korrekt einordnen":"Încadrați corect dMMR/MSI-H din punct de vedere terapeutic","BRAF-Wildtyp nicht als Lynch-Beweis interpretieren":"Nu interpretați BRAF wild type ca dovadă pentru sindromul Lynch","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex priorisieren":"Prioritizați metilarea promotorului MLH1 ca test reflex epigenetic direct","Alter/Familie/klinischen Kontext trotz Methylierung berücksichtigen":"Luați în considerare vârsta/familia/contextul clinic în ciuda metilării","Falschaussage: BRAF-Wildtyp + MLH1/PMS2-Verlust = Lynch gesichert":"Afirmație falsă: BRAF wild type + pierdere MLH1/PMS2 = sindrom Lynch confirmat","Optimale Lösung: MSI-H/dMMR therapeutisch nutzen, MLH1/PMS2-Verlust hereditär reflexdiagnostisch abarbeiten und BRAF-Wildtyp nicht überinterpretieren; positive MLH1-Methylierung spricht stark für sporadische Silenzierung.":"Soluție optimă: utilizați MSI-H/dMMR din punct de vedere terapeutic, investigați pierderea MLH1/PMS2 prin testare reflexă ereditară adecvată și nu suprainterpretați BRAF wild type; metilarea MLH1 pozitivă susține puternic silențierea sporadică.","MLH1 methylation":"Metilare MLH1","BRAF wild type":"BRAF wild type","BRAF-Wildtyp ist kein positiver Lynch-Test":"BRAF wild type nu este un test pozitiv pentru Lynch","Gastrointestinale Molekularpathologie / MTB / Humangenetik":"Patologie moleculară gastrointestinală / MTB / genetică medicală","MLH1/PMS2-Verlust als Trigger einer spezifischen Reflexdiagnostik verstehen.":"Înțelegeți pierderea MLH1/PMS2 ca declanșator al unei testări reflexe specifice.","MSI-H/dMMR therapeutische und hereditäre Ebenen trennen.":"Separați nivelurile terapeutic și ereditar ale MSI-H/dMMR.","BRAF V600E positiv als starkes sporadisches Indiz, BRAF-Wildtyp aber nicht als Lynch-Beweis verstehen.":"Înțelegeți BRAF V600E pozitiv ca indiciu puternic pentru origine sporadică, dar nu BRAF wild type ca dovadă pentru Lynch.","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex einordnen.":"Încadrați metilarea promotorului MLH1 ca test reflex epigenetic direct.","Alter und Familienanamnese trotz scheinbar sporadischem Muster berücksichtigen.":"Luați în considerare vârsta și istoricul familial în ciuda unui model aparent sporadic.","MLH1 und PMS2 fehlen, der Tumor ist MSI-H – und BRAF ist Wildtyp. Im Board fällt sofort der Satz: 'Dann ist es Lynch.' Genau an dieser Stelle setzt der Fall an.":"MLH1 și PMS2 lipsesc, tumora este MSI-H — iar BRAF este wild type. În board apare imediat afirmația: «Atunci este Lynch.» Exact aici începe cazul.","71-jährige Patientin mit rechtsseitigem MSI-H-CRC und MLH1/PMS2-Verlust. BRAF V600E ist nicht nachweisbar. Die zentrale Frage ist, ob das bereits Lynch beweist oder ob die epigenetische Ursache der MLH1-Silenzierung noch direkt geprüft werden muss.":"Pacientă de 71 de ani cu CRC drept MSI-H și pierdere MLH1/PMS2. BRAF V600E nu este detectat. Întrebarea centrală este dacă aceasta dovedește deja sindromul Lynch sau dacă trebuie testată direct cauza epigenetică a silențierii MLH1.","Therapieebene":"Nivel terapeutic","MSI-H/dMMR ist bereits ein wichtiger prädiktiver Tumorbefund.":"MSI-H/dMMR este deja un rezultat tumoral predictiv important.","Die Therapieaussage braucht nicht erst eine Lynch-Diagnose.":"Concluzia terapeutică nu necesită mai întâi un diagnostic de Lynch.","MLH1/PMS2-Verlust kann sporadisch oder hereditär entstehen.":"Pierderea MLH1/PMS2 poate apărea sporadic sau ereditar.","Reflexdiagnostik klärt die Ursache.":"Testarea reflexă clarifică cauza.","Negativ ist nicht positiv":"Negativ nu înseamnă pozitiv","BRAF-Wildtyp entfernt ein sporadisches Indiz, beweist aber Lynch nicht.":"BRAF wild type elimină un indiciu pentru origine sporadică, dar nu dovedește sindromul Lynch.","Ausschlussmarker nicht in Bestätigungsmarker verwandeln.":"Nu transformați un marker de excludere într-un marker de confirmare.","MLH1/PMS2 verloren":"MLH1/PMS2 pierdute","MSI-high":"MSI-high","V600E nicht nachweisbar":"V600E nedetectat","Ausreichendes Resektat für gezielte MLH1-Methylierungsanalyse.":"Piesă de rezecție adecvată pentru analiza țintită a metilării MLH1.","Kein Grund für ein breites Panel, wenn die Reflexfrage fokussiert beantwortet werden kann.":"Nu este nevoie de un panel larg dacă întrebarea reflexă focalizată poate fi răspunsă direct.","Klinischer Kontext bleibt Teil der Lynch-Risikobewertung.":"Contextul clinic rămâne parte din evaluarea riscului de Lynch.","Was bedeutet BRAF-Wildtyp bei MLH1/PMS2-Verlust?":"Ce înseamnă BRAF wild type în contextul pierderii MLH1/PMS2?","Lynch bleibt möglich, ist aber nicht bewiesen; MLH1-Promotor-Methylierung sollte direkt geprüft werden.":"Sindromul Lynch rămâne posibil, dar nu este dovedit; metilarea promotorului MLH1 trebuie testată direct.","Lynch ist damit gesichert.":"Sindromul Lynch este astfel confirmat.","Sporadisch ist damit gesichert.":"Originea sporadică este astfel confirmată.","BRAF hat nie Bedeutung im CRC-Lynch-Screening.":"BRAF nu are niciodată relevanță în screeningul Lynch la CRC.","Negatives BRAF-Ergebnis ist kein positiver Lynch-Nachweis.":"Un rezultat BRAF negativ nu este dovadă pozitivă pentru sindromul Lynch.","MLH1-Promotor-Methylierung ist deutlich positiv. Was ist die beste Interpretation?":"Metilarea promotorului MLH1 este clar pozitivă. Care este cea mai bună interpretare?","Starkes Indiz für sporadische epigenetische MLH1-Silenzierung; klinische Sonderkonstellationen trotzdem beachten.":"Indiciu puternic pentru silențiere epigenetică sporadică a MLH1; trebuie totuși avute în vedere constelațiile clinice speciale.","Beweist Lynch.":"Dovedește sindromul Lynch.","Macht MSI-H therapeutisch irrelevant.":"Face MSI-H irelevant terapeutic.","Ist bei CRC bedeutungslos.":"Este irelevantă în CRC.","Tumorale MLH1-Hypermethylierung erklärt häufig sporadischen MLH1/PMS2-Verlust.":"Hipermetilarea tumorală a MLH1 explică frecvent pierderea sporadică MLH1/PMS2.","Welche Aussage trennt die Ebenen korrekt?":"Care afirmație separă corect cele două niveluri?","MSI-H/dMMR ist therapeutisch relevant; Lynch-Abklärung ist eine zusätzliche hereditäre Frage.":"MSI-H/dMMR este relevant terapeutic; evaluarea Lynch este o întrebare ereditară suplimentară.","Immuntherapie darf erst nach Keimbahnbefund diskutiert werden.":"Imunoterapia poate fi discutată numai după un rezultat germinal.","dMMR und Lynch sind Synonyme.":"dMMR și sindromul Lynch sunt sinonime.","Nur BRAF entscheidet beide Ebenen.":"Doar BRAF decide ambele niveluri.","Tumorbiomarker und hereditäre Diagnose sind verwandt, aber nicht identisch.":"Biomarkerul tumoral și diagnosticul ereditar sunt legate, dar nu identice.","Wann sollte trotz MLH1-Methylierung genauer hingesehen werden?":"Când trebuie investigat mai atent în ciuda metilării MLH1?","Bei ungewöhnlich jungem Alter, auffälliger Familien-/Eigenanamnese oder anderer klinischer Diskordanz.":"La vârstă neobișnuit de tânără, antecedente personale/familiale sugestive sau altă discordanță clinică.","Nie.":"Niciodată.","Immer vollständige Keimbahndiagnostik unabhängig vom Kontext.":"Întotdeauna testare germinală completă, indiferent de context.","Nur bei PD-L1-Positivität.":"Doar la PD-L1 pozitiv.","Seltene konstitutionelle Epimutationen und klinische Sonderkonstellationen verhindern absolute Aussagen.":"Epimutațiile constituționale rare și constelațiile clinice speciale împiedică afirmațiile absolute.","Formulieren Sie eine zweigeteilte MTB-Aussage: therapeutische Bedeutung von MSI-H/dMMR und hereditäre Einordnung des MLH1/PMS2-Verlusts nach BRAF- und MLH1-Methylierungsbefund.":"Formulați o concluzie MTB în două părți: semnificația terapeutică a MSI-H/dMMR și încadrarea ereditară a pierderii MLH1/PMS2 după rezultatele BRAF și metilarea MLH1.","dMMR/MSI-H therapeutisch einordnen.":"Încadrați dMMR/MSI-H terapeutic.","MLH1/PMS2-Verlust als Reflextrigger verstehen.":"Înțelegeți pierderea MLH1/PMS2 ca declanșator al testării reflexe.","BRAF-Wildtyp nicht als Lynch-Beweis formulieren.":"Nu raportați BRAF wild type ca dovadă pentru sindromul Lynch.","MLH1-Promotor-Methylierung direkt testen.":"Testați direct metilarea promotorului MLH1.","Positive Methylierung als starkes sporadisches Indiz berichten.":"Raportați metilarea pozitivă ca indiciu puternic pentru silențiere sporadică.","Klinische Sonderkonstellationen offenhalten.":"Păstrați deschise constelațiile clinice speciale.","In Laborpfaden, die BRAF und Methylierung anders sequenzieren, ist die Kernaussage identisch: BRAF-WT allein reicht nicht für Lynch-Diagnose.":"În fluxurile de laborator care ordonează diferit BRAF și metilarea, mesajul-cheie rămâne identic: BRAF wild type singur nu este suficient pentru diagnosticul Lynch.","Bei klarer hereditärer Auffälligkeit humangenetische Vorstellung trotz Tumormethylierung erwägen.":"Dacă există elemente ereditare clar sugestive, luați în considerare consultul genetic în ciuda metilării tumorale.","BRAF-WT = Lynch":"BRAF wild type = sindrom Lynch","Negatives Ausschlussindiz ist kein positiver hereditärer Nachweis.":"Un indiciu negativ de excludere nu este dovadă ereditară pozitivă.","dMMR = Lynch":"dMMR = sindrom Lynch","Viele MLH1/PMS2-defiziente CRC sind sporadisch methyliert.":"Multe CRC cu deficit MLH1/PMS2 sunt metilate sporadic.","Methylierung löscht MSI-Therapiebedeutung":"Metilarea anulează semnificația terapeutică a MSI","Therapeutische und hereditäre Ebenen werden vermischt.":"Nivelurile terapeutic și ereditar sunt confundate.","Der BRAF-Wildtyp führt in die falsche Sicherheit":"BRAF wild type creează o falsă certitudine","Obwohl BRAF V600E fehlt, ist der MLH1-Promotor deutlich methyliert. Das kippt die intuitive 'BRAF-WT = Lynch'-Kurzform und zeigt, warum der direkte epigenetische Reflex diagnostisch stärker ist.":"Deși BRAF V600E lipsește, promotorul MLH1 este clar metilat. Acest lucru răstoarnă scurtătura intuitivă «BRAF wild type = Lynch» și arată de ce testul reflex epigenetic direct este mai puternic diagnostic.","Der Fall trainiert Negativbefunde, Reflexdiagnostik und die Trennung von Tumortherapie und Familienmedizin.":"Cazul antrenează interpretarea rezultatelor negative, diagnosticul reflex și separarea terapiei tumorale de medicina familială/genetică.","Zwei Ebenen sauber getrennt":"Două niveluri separate clar","MSI-H/dMMR therapeutisch relevant; BRAF-WT kein Lynch-Beweis; MLH1-Methylierung positiv → sporadische Silenzierung stark wahrscheinlich.":"MSI-H/dMMR relevant terapeutic; BRAF wild type nu dovedește Lynch; metilare MLH1 pozitivă → silențiere sporadică foarte probabilă.","Reflexdiagnostik korrekt.":"Diagnostic reflex corect.","Lynch offen, Methylierung vergessen":"Lynch rămâne deschis, metilarea uitată","BRAF-WT wird korrekt nicht überinterpretiert, aber der direkte MLH1-Reflex fehlt.":"BRAF wild type nu este suprainterpretat corect, dar lipsește testul reflex direct MLH1.","Diagnostik unvollständig.":"Evaluare diagnostică incompletă.","Keimbahndiagnose aus negativem Tumormarker abgeleitet.":"Diagnostic germinal dedus dintr-un marker tumoral negativ.","Kritisches Overcalling.":"Suprainterpretare critică.","MLH1-Methylierung positiv":"Metilare MLH1 pozitivă","Sporadische MLH1-Silenzierung als wahrscheinlich berichten; Klinik/Familie abgleichen.":"Raportați silențierea sporadică MLH1 ca probabilă; corelați cu contextul clinic/istoricul familial.","Viele unnötige Keimbahnabklärungen können vermieden werden, ohne Sonderfälle zu ignorieren.":"Multe evaluări germinale inutile pot fi evitate fără a ignora cazurile speciale.","Humangenetische/germline Abklärung priorisieren.":"Prioritizați evaluarea genetică/germinală.","Lynch-Verdacht bleibt bestehen.":"Suspiciunea de sindrom Lynch persistă.","MLH1/PMS2-Verlust ist kein automatischer Lynch-Befund.":"Pierderea MLH1/PMS2 nu reprezintă automat un rezultat Lynch.","BRAF V600E kann sporadische MLH1-Inaktivierung stützen; BRAF-Wildtyp beweist Lynch nicht.":"BRAF V600E poate susține inactivarea sporadică a MLH1; BRAF wild type nu dovedește sindromul Lynch.","MLH1-Promotor-Methylierung ist ein direkter epigenetischer Reflex.":"Metilarea promotorului MLH1 este un test reflex epigenetic direct.","MSI-H/dMMR hat eine therapeutische Aussage unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"MSI-H/dMMR are semnificație terapeutică indiferent dacă originea este sporadică sau ereditară.","Sehr junges Alter oder auffällige Familienanamnese können trotz Tumormethylierung weitere Abklärung rechtfertigen.":"Vârsta foarte tânără sau un istoric familial sugestiv pot justifica investigații suplimentare în ciuda metilării tumorale.","MSI-H/dMMR ist therapeutisch relevant. Für die hereditäre Einordnung ist BRAF-Wildtyp nicht beweisend; die positive MLH1-Promotor-Methylierung spricht stark für sporadische MLH1-Silenzierung. Alter und Familienanamnese bleiben als Sicherheitsnetz bestehen.":"MSI-H/dMMR este relevant terapeutic. Pentru încadrarea ereditară, BRAF wild type nu este concludent; metilarea pozitivă a promotorului MLH1 susține puternic silențierea sporadică a MLH1. Vârsta și istoricul familial rămân o plasă de siguranță.","BRAF-WT nicht overcallen":"Nu suprainterpretați BRAF wild type","Therapie vs Heredität":"Terapie vs ereditate","Kontext":"Context","Warum ist ein negativer Marker selten ein positiver Beweis?":"De ce un marker negativ este rareori o dovadă pozitivă?","Wie unterscheiden sich BRAF- und MLH1-Methylierungsreflex?":"Cum diferă testarea reflexă BRAF de cea pentru metilarea MLH1?","Wann kann Tumormethylierung eine hereditäre Ursache nicht vollständig ausschließen?":"Când poate metilarea tumorală să nu excludă complet o cauză ereditară?","MLH1-Methylierung positiv trotz BRAF-WT":"Metilare MLH1 pozitivă în ciuda BRAF wild type","BRAF-Wildtyp ist kein Lynch-Beweis":"BRAF wild type nu dovedește sindromul Lynch","MMR/MSI → BRAF-Kontext → MLH1-Methylierung → hereditäre Einordnung":"MMR/MSI → context BRAF → metilare MLH1 → încadrare ereditară","mCRC und Bevacizumab: Anti-VEGF braucht keinen VHL-Test":"mCRC și bevacizumab: anti-VEGF nu necesită test VHL","mCRC: Bevacizumab und VEGF-Angioge…":"mCRC: bevacizumab și angiogeneza VEGF…","63-jähriger Patient mit metastasiertem rechtsseitigem Kolonkarzinom, KRAS p.G12D-mutiert. Im Board wird Bevacizumab als Bestandteil der Systemtherapie diskutiert.":"Bărbat de 63 de ani cu cancer de colon drept metastatic, mutant KRAS p.G12D. În board se discută bevacizumab ca parte a terapiei sistemice.","Muss vor Anti-VEGF-Therapie die VHL/HIF/VEGF-Achse des Tumors molekular getestet oder eine hohe VEGF-Expression nachgewiesen werden?":"Înainte de terapia anti-VEGF trebuie testată molecular axa VHL/HIF/VEGF a tumorii sau demonstrată o expresie VEGF ridicată?","Therapieentscheidung in dieser Woche.":"Decizie terapeutică în această săptămână.","Rechtsseitiges mCRC mit multiplen Lebermetastasen.":"mCRC drept cu metastaze hepatice multiple.","KRAS p.G12D; BRAF-Wildtyp; pMMR/MSS aus Basisdiagnostik.":"KRAS p.G12D; BRAF wild type; pMMR/MSS din diagnosticul inițial.","Anti-EGFR ist wegen RAS-Mutation nicht der naheliegende Weg; eine antiangiogene Kombination wird diskutiert.":"Anti-EGFR nu este calea evidentă din cauza mutației RAS; se discută o combinație antiangiogenică.","Mechanistische Biologie wird mit einem notwendigen prädiktiven Companion Diagnostic verwechselt.":"Biologia mecanistică este confundată cu un companion diagnostic predictiv obligatoriu.","Konventionelles kolorektales Adenokarzinom mit vitalen Metastasenarealen.":"Adenocarcinom colorectal convențional cu zone metastatice viabile.","Gefäße":"Vase","Tumor zeigt erwartbare Neovaskularisation; kein spezifischer morphologischer Selektionsmarker.":"Tumora prezintă neovascularizația așteptată; nu există un marker morfologic specific de selecție.","Basisprofil":"Profil de bază","RAS-mutiert, pMMR/MSS.":"RAS mutant, pMMR/MSS.","Welche Rolle spielt VEGF-Biologie für das Verständnis – und welche gerade nicht für die Testauswahl?":"Ce rol are biologia VEGF pentru înțelegere și ce rol nu are tocmai în selecția testelor?","FFPE-Lebermetastase, ausreichend für Zusatzanalysen.":"Metastază hepatică FFPE, adecvată pentru analize suplimentare.","Begrenzt; keine diagnostische Fragestellung rechtfertigt einen RCC-spezifischen VHL/HIF-Test.":"Limitat; nicio întrebare diagnostică nu justifică un test VHL/HIF specific RCC.","Mechanismus":"Mecanism","VEGF-A ist ein zentraler proangiogener Ligand; Bevacizumab neutralisiert VEGF-A.":"VEGF-A este un ligand proangiogenic central; bevacizumab neutralizează VEGF-A.","Ein biologisch plausibler Signalweg ist nicht automatisch ein validierter Patientenselektions-Biomarker.":"O cale biologic plauzibilă nu este automat un biomarker validat de selecție a pacienților.","VEGF-/Angiogenese-Kontext korrekt einordnen":"Încadrați corect contextul VEGF/angiogeneză","CRC-Basisprofil":"Profil CRC de bază","KRAS p.G12D, BRAF-Wildtyp, keine zusätzliche Alteration, die einen Anti-VEGF-spezifischen Companion-Diagnostic-Pfad definiert.":"KRAS p.G12D, BRAF wild type, fără altă alterare care să definească un traseu companion diagnostic specific anti-VEGF.","VEGF-Kontext":"Context VEGF","Anti-VEGF hemmt einen zentralen Angiogeneseweg; beim mCRC existiert jedoch kein etablierter routinemäßiger Tumor-VEGF- oder VHL/HIF-Test, der vor Bevacizumab positiv sein muss.":"Anti-VEGF inhibă o cale centrală a angiogenezei; totuși, în mCRC nu există un test tumoral VEGF sau VHL/HIF de rutină stabilit care trebuie să fie pozitiv înainte de bevacizumab.","Molekularer CRC-Kontext":"Context molecular CRC","KRAS-mutiert, pMMR/MSS.":"KRAS mutant, pMMR/MSS.","Kernfrage":"Întrebarea centrală","Biologischen Wirkmechanismus von prädiktiver Testpflicht trennen.":"Separați mecanismul biologic de acțiune de cerința unui test predictiv.","Bevacizumab adressiert die VEGF-A-vermittelte Angiogenese, seine klinische Anwendung beim mCRC setzt aber keinen positiven VHL/HIF-/VEGF-Tumortest voraus. Die RAS-Mutation erklärt hier den fehlenden anti-EGFR-Kontext, ist aber kein Gegenargument gegen die antiangiogene Wirklogik. Zusätzliche VHL/HIF-Testung wäre ein aus dem RCC übertragener Low-value-Copyover.":"Bevacizumab vizează angiogeneza mediată de VEGF-A, dar utilizarea sa clinică în mCRC nu necesită un test tumoral VHL/HIF/VEGF pozitiv. Mutația RAS explică aici lipsa contextului anti-EGFR, dar nu este un argument împotriva mecanismului antiangiogenic. Testarea suplimentară VHL/HIF ar fi un copyover low-value din RCC.","Teilbefund: VEGF ist biologisch relevant, aber es fehlt die Trennung zwischen Wirkmechanismus und validiertem Selektionsbiomarker.":"Rezultat parțial: VEGF este relevant biologic, dar lipsește separarea dintre mecanismul de acțiune și biomarkerul validat de selecție.","VEGF-A/Angiogenese als Wirkmechanismus erklären":"Explicați VEGF-A/angiogeneza ca mecanism de acțiune","Keinen routinemäßigen positiven VEGF-/VHL-Test als Voraussetzung behaupten":"Nu susțineți un test VEGF/VHL pozitiv de rutină ca premisă","RAS-Mutation korrekt auf anti-EGFR, nicht auf Anti-VEGF beziehen":"Corelați corect mutația RAS cu anti-EGFR, nu cu anti-VEGF","RCC-spezifische VHL/HIF-Testung vermeiden":"Evitați testarea VHL/HIF specifică RCC","Falschaussage: Bevacizumab nur bei molekular aktivierter VHL/HIF-Achse":"Afirmație falsă: bevacizumab doar cu activarea moleculară a axei VHL/HIF","Optimale Lösung: Anti-VEGF biologisch sauber erklären, aber keinen erfundenen Companion Diagnostic verlangen; RAS-Status und VEGF-Therapieachse sind unterschiedliche Entscheidungsebenen.":"Soluție optimă: explicați corect biologia anti-VEGF fără a inventa un companion diagnostic; statusul RAS și axa terapeutică VEGF sunt niveluri decizionale separate.","Bevacizumab":"Bevacizumab","VEGF":"VEGF","Angiogenese":"Angiogeneză","KRAS":"KRAS","Biomarker hierarchy":"Ierarhia biomarkerilor","Anti-VEGF ist ein Wirkmechanismus, kein VHL-Companion-Diagnostic":"Anti-VEGF este un mecanism de acțiune, nu un companion diagnostic VHL","Gastroonkologie / Molekularpathologie / MTB":"Oncologie gastrointestinală / patologie moleculară / MTB","VEGF-Angiogenese als Wirkmechanismus von Bevacizumab erklären.":"Explicați angiogeneza VEGF ca mecanism de acțiune al bevacizumab.","Wirkmechanismus und prädiktiven Companion Diagnostic sauber trennen.":"Separați clar mecanismul de acțiune de companion diagnostic predictiv.","RAS-Status korrekt auf anti-EGFR und nicht auf Anti-VEGF beziehen.":"Corelați corect statusul RAS cu anti-EGFR și nu cu anti-VEGF.","Entitätsfremde VHL/HIF-Testung beim mCRC vermeiden.":"Evitați testarea VHL/HIF nepotrivită entității în mCRC.","Material- und Testökonomie als Teil guter Präzisionsonkologie verstehen.":"Înțelegeți economia de material și testare ca parte a unei bune oncologii de precizie.","Der Tumor ist KRAS-mutiert. Jemand fragt, ob man für Bevacizumab jetzt noch 'VHL/HIF/VEGF molekular bestätigen' müsse. Genau diese scheinbar logische Zusatzdiagnostik ist der Fehler.":"Tumora este mutantă KRAS. Cineva întreabă dacă pentru bevacizumab trebuie acum „confirmate molecular” VHL/HIF/VEGF. Tocmai această testare suplimentară aparent logică este eroarea.","63-jähriger Patient mit KRAS-mutiertem, pMMR/MSS mCRC. Bevacizumab wird als Teil einer systemischen Kombination diskutiert. Die Aufgabe ist nicht, einen neuen Biomarker zu erfinden, sondern Mechanismus, RAS-Kontext und echte Testpflicht zu trennen.":"Bărbat de 63 de ani cu mCRC mutant KRAS, pMMR/MSS. Bevacizumab este discutat ca parte a unei combinații sistemice. Sarcina nu este inventarea unui biomarker nou, ci separarea mecanismului, contextului RAS și cerințelor reale de testare.","RAS beantwortet eine andere Frage":"RAS răspunde unei alte întrebări","KRAS p.G12D schließt einen klassischen anti-EGFR-Kontext aus.":"KRAS p.G12D exclude un context anti-EGFR clasic.","Das macht Anti-VEGF nicht biologisch unplausibel.":"Aceasta nu face anti-VEGF biologic neplauzibil.","VEGF ist zentral":"VEGF este central","Tumorangiogenese benötigt proangiogene Signale.":"Angiogeneza tumorală necesită semnale proangiogenice.","Zentraler Mechanismus bedeutet nicht automatisch Companion Diagnostic.":"Un mecanism central nu înseamnă automat companion diagnostic.","RCC-Copyover":"Copyover din RCC","VHL/HIF ist beim ccRCC kanonisch.":"VHL/HIF este canonic în ccRCC.","Signalwege dürfen nicht blind zwischen Entitäten als Testalgorithmus übertragen werden.":"Căile de semnalizare nu trebuie transferate orbește între entități ca algoritmi de testare.","CRC-Profil":"Profil CRC","KRAS p.G12D, BRAF-WT, pMMR/MSS":"KRAS p.G12D, BRAF wild type, pMMR/MSS","metastasiert, systemische Therapie geplant":"Metastatic, terapie sistemică planificată","ausreichend, aber kein Grund für unnötige Zusatztests":"Adecvat, dar fără motiv pentru teste suplimentare inutile","Keine validierte positive VEGF-/VHL-Testpflicht vor Bevacizumab im mCRC.":"Nu există cerință validată pentru un test VEGF/VHL pozitiv înainte de bevacizumab în mCRC.","Entitätsfremde Testung verbraucht Ressourcen ohne Entscheidungsgewinn.":"Testarea nepotrivită entității consumă resurse fără câștig decizional.","Mechanistische Erklärung kann ohne zusätzlichen Wet-lab-Test erfolgen.":"Explicația mecanistică poate fi oferită fără un test wet-lab suplimentar.","Was bedeutet KRAS p.G12D für die Anti-VEGF-Frage?":"Ce înseamnă KRAS p.G12D pentru întrebarea anti-VEGF?","Es betrifft die anti-EGFR-Logik; es ist kein automatischer Ausschluss von Bevacizumab.":"Privește logica anti-EGFR; nu reprezintă excluderea automată a bevacizumab.","Es ist eine Kontraindikation gegen Anti-VEGF.":"Este o contraindicație pentru anti-VEGF.","Es beweist besonders gutes Bevacizumab-Ansprechen.":"Dovedește un răspuns deosebit de bun la bevacizumab.","RAS hat im CRC gar keine therapeutische Bedeutung.":"RAS nu are deloc relevanță terapeutică în CRC.","Therapieachsen müssen getrennt gehalten werden.":"Axele terapeutice trebuie menținute separate.","Braucht Bevacizumab einen positiven Tumor-VEGF/VHL-Test?":"Necesită bevacizumab un test tumoral VEGF/VHL pozitiv?","Nein; der Wirkmechanismus ist biologisch VEGF-gerichtet, aber es existiert kein solcher routinemäßiger Companion-Diagnostic-Pfad.":"Nu; mecanismul de acțiune este biologic direcționat spre VEGF, dar nu există un astfel de traseu companion diagnostic de rutină.","Ja, VHL-Mutation ist Voraussetzung.":"Da, este necesară o mutație VHL.","Ja, hohe VEGF-IHC muss dokumentiert sein.":"Da, trebuie documentată IHC VEGF ridicată.","Ja, HIF-2α muss mutiert sein.":"Da, HIF-2α trebuie să fie mutant.","Mechanismus und Testpflicht sind nicht dasselbe.":"Mecanismul de acțiune și cerința de testare nu sunt același lucru.","Warum ist ein VHL/HIF-Panel hier Low-value?":"De ce este un panel VHL/HIF low-value aici?","Es importiert ccRCC-Biologie in einen CRC-Therapiealgorithmus ohne validierten Selektionsnutzen.":"Importă biologia ccRCC într-un algoritm terapeutic CRC fără beneficiu validat de selecție.","Nur weil es teuer ist.":"Doar pentru că este scump.","Weil CRC keine DNA enthält.":"Pentru că CRC nu conține ADN.","Weil VEGF im CRC keine Rolle spielt.":"Pentru că VEGF nu are niciun rol în CRC.","Entitätsspezifische Evidenz entscheidet.":"Evidența specifică entității decide.","Was ist hier Präzisionsonkologie?":"Ce înseamnă oncologie de precizie aici?","Die richtigen wenigen Informationen verwenden und unnötige Tests weglassen.":"Folosiți puținele informații corecte și omiteți testele inutile.","Immer das breiteste Panel bestellen.":"Comandați întotdeauna cel mai larg panel.","Jeden bekannten Signalweg molekular bestätigen.":"Confirmați molecular fiecare cale cunoscută.","Nur positive Biomarker zählen.":"Contează doar biomarkerii pozitivi.","Präzision ist nicht Informationsmaximierung.":"Precizia nu înseamnă maximizarea informației.","Formulieren Sie die Anti-VEGF-Rationale und begründen Sie explizit, warum weder KRAS-Mutation noch fehlende VHL/HIF-Testung die Bevacizumab-Logik aufheben.":"Formulați raționamentul anti-VEGF și explicați explicit de ce nici mutația KRAS, nici absența testării VHL/HIF nu invalidează logica bevacizumab.","KRAS p.G12D als anti-EGFR-Resistenzkontext benennen.":"Identificați KRAS p.G12D ca un context de rezistență anti-EGFR.","VEGF-Angiogenese als Wirkmechanismus erklären.":"Explicați angiogeneza VEGF ca mecanism de acțiune.","Keine positive VEGF-/VHL-Testpflicht erfinden.":"Nu inventați o cerință de test VEGF/VHL pozitiv.","VHL/HIF-Testung als entitätsfremden Low-value-Test vermeiden.":"Evitați testarea VHL/HIF ca test low-value nepotrivit entității.","Therapieentscheidung im klinischen CRC-Kontext belassen.":"Păstrați decizia terapeutică în contextul clinic CRC.","Breites CRC-Panel nur, wenn andere therapeutische Fragestellungen offen sind.":"Folosiți un panel CRC larg doar dacă rămân deschise alte întrebări terapeutice.","VEGF-Biologie rein interpretativ erklären, ohne Zusatztest.":"Explicați interpretativ biologia VEGF fără test suplimentar.","VHL testen, weil VEGF":"Testați VHL pentru că VEGF","RCC-Biologie wird ohne Evidenz in CRC übertragen.":"Biologia RCC este transferată în CRC fără dovezi.","KRAS-mutiert = kein Bevacizumab":"KRAS mutant = fără bevacizumab","RAS und VEGF sind unterschiedliche therapeutische Achsen.":"RAS și VEGF sunt axe terapeutice diferite.","Mehr Test = mehr Präzision":"Mai multe teste = mai multă precizie","Test ohne Entscheidungsnutzen ist Low-value.":"Un test fără valoare decizională este low-value.","Der beste Test ist hier: keiner":"Cel mai bun test aici este: niciunul","Die vorhandenen Daten reichen für die Anti-VEGF-Rationale. Ein VHL/HIF-Panel würde nichts klinisch Validiertes hinzufügen. Der Twist ist, dass fachliche Tiefe nicht durch zusätzliche Diagnostik, sondern durch korrektes Weglassen entsteht.":"Datele disponibile sunt suficiente pentru raționamentul anti-VEGF. Un panel VHL/HIF nu ar adăuga nimic validat clinic. Twist-ul este că expertiza nu se arată prin diagnostic suplimentar, ci prin omisiunea corectă a acestuia.","Er trainiert Testökonomie und verhindert pathway-driven Overdiagnostics.":"Antrenează economia testării și previne overdiagnostics ghidat de pathway.","Mechanismus ohne Pseudobiomarker":"Mecanism fără pseudo-biomarker","KRAS-mutiertes mCRC; Anti-VEGF biologisch plausibel, kein VHL/VEGF Companion Diagnostic erforderlich.":"mCRC mutant KRAS; anti-VEGF biologic plauzibil, fără necesitatea unui companion diagnostic VHL/VEGF.","Saubere Evidenzhierarchie.":"Ierarhie clară a dovezilor.","VEGF erklärt, RAS unscharf":"VEGF explicat, RAS neclar","Angiogenese korrekt, aber RAS-/anti-EGFR-Kontext wird vermischt.":"Angiogeneza este corectă, dar contextul RAS/anti-EGFR este confundat.","Therapieachsen trennen.":"Separați axele terapeutice.","VHL-Pflicht erfunden":"Cerință VHL inventată","Bevacizumab wird von einem RCC-artigen VHL/HIF-Panel abhängig gemacht.":"Bevacizumab este făcut dependent de un panel VHL/HIF de tip RCC.","Entitäts-Copyover.":"Copyover între entități.","Weitere CRC-Targets offen":"Alte ținte CRC încă deschise","Entitätsspezifische Standarddiagnostik ergänzen.":"Completați diagnosticul standard specific entității.","Zusatztests beantworten echte Fragen.":"Testele suplimentare răspund unor întrebări reale.","Nur Anti-VEGF-Mechanismus gefragt":"Este întrebat doar mecanismul anti-VEGF","Interpretation statt Wet-lab-Overtesting.":"Interpretare în loc de overtesting wet-lab.","Material und TAT werden geschont.":"Materialul și TAT sunt protejate.","Bevacizumab neutralisiert VEGF-A und adressiert Tumorangiogenese.":"Bevacizumab neutralizează VEGF-A și vizează angiogeneza tumorală.","Für mCRC ist kein positiver VHL/HIF-/Tumor-VEGF-Test als Routinevoraussetzung etabliert.":"Niciun test VHL/HIF/VEGF tumoral pozitiv nu este stabilit ca premisă de rutină în mCRC.","RAS-Status entscheidet eine andere Therapieachse.":"Statusul RAS decide o altă axă terapeutică.","Mechanistische Plausibilität ist nicht gleich Companion Diagnostic.":"Plausibilitatea mecanistică nu este echivalentă cu un companion diagnostic.","Gute Präzisionsdiagnostik beinhaltet bewusstes Weglassen unnötiger Tests.":"Un diagnostic de precizie bun include omiterea deliberată a testelor inutile.","Die KRAS-Mutation erklärt den fehlenden anti-EGFR-Kontext, nicht eine Anti-VEGF-Kontraindikation. Bevacizumab wirkt über VEGF-A; ein positiver VHL/HIF-/VEGF-Tumortest ist dafür im mCRC nicht erforderlich. VHL/HIF-Testung wäre Low-value.":"Mutația KRAS explică lipsa contextului anti-EGFR, nu o contraindicație anti-VEGF. Bevacizumab acționează prin VEGF-A; un test tumoral VHL/HIF/VEGF pozitiv nu este necesar în mCRC. Testarea VHL/HIF ar fi low-value.","Mechanismus vs Biomarker":"Mecanism vs biomarker","RAS-Achse getrennt":"Axa RAS separată","kein VHL-Copyover":"Fără copyover VHL","Testökonomie":"Economia testării","Warum führen Signalwegdiagramme manchmal zu Overdiagnostics?":"De ce diagramele de pathways duc uneori la overdiagnostics?","Was unterscheidet einen Wirkmechanismus von einem Companion Diagnostic?":"Ce diferențiază un mecanism de acțiune de un companion diagnostic?","Wann ist ein nicht bestellter Test die beste Entscheidung?":"Când este necomandarea unui test cea mai bună decizie?","VHL/HIF wird bewusst nicht getestet":"VHL/HIF nu este testat intenționat","Mechanismus ≠ Companion Diagnostic":"Mecanism ≠ companion diagnostic","CRC-Profil → Therapieachse → VEGF-Rationale → kein Zusatztest":"Profil CRC → axă terapeutică → raționament VEGF → fără test suplimentar","Klarzelliges RCC: VHL/HIF/VEGF erklärt die Biologie – wählt aber nicht allein die Therapie":"RCC cu celule clare: VHL/HIF/VEGF explică biologia — dar nu selectează singur terapia","Klarzelliges RCC: VHL/HIF/VEGF-Ach…":"RCC cu celule clare: axa VHL/HIF/VEGF…","Uroonkologie / Molekulares Tumorboard":"Oncologie urologică / Molecular Tumor Board","59-jähriger Patient mit metastasiertem klarzelligem Nierenzellkarzinom. Ein Tumorpanel weist eine inaktivierende VHL-Alteration nach.":"Bărbat de 59 de ani cu carcinom renal cu celule clare metastatic. Un panel tumoral detectează o alterare inactivantă VHL.","Wie erklärt die VHL/HIF/VEGF-Achse die ausgeprägte Vaskularisierung und die Plausibilität von VEGFR-TKI/IO-Kombinationen – und wie weit darf man den VHL-Befund therapeutisch individualisieren?":"Cum explică axa VHL/HIF/VEGF vascularizația marcată și plauzibilitatea combinațiilor VEGFR-TKI/IO — și cât de mult poate fi folosit rezultatul VHL pentru individualizarea terapiei?","Erstlinienstrategie soll im interdisziplinären Board festgelegt werden.":"Strategia de primă linie trebuie stabilită în boardul interdisciplinar.","Krankheit":"Boală","Nephrektomie vor 18 Monaten; nun pulmonale und ossäre Metastasen.":"Nefrectomie acum 18 luni; acum metastaze pulmonare și osoase.","Klarzelliges RCC, typische feine Gefäßarchitektur.":"RCC cu celule clare, arhitectură vasculară fină tipică.","VHL Loss-of-function im Tumor.":"VHL loss-of-function în tumoră.","Ein häufiger biologischer Driver wird als spezifischer prädiktiver Marker für genau eine zugelassene Kombination missverstanden.":"Un driver biologic frecvent este interpretat greșit ca marker predictiv specific pentru exact o combinație aprobată.","Alveolär/nestartig aufgebauter klarzelliger Tumor mit dichtem kapillärem Netzwerk.":"Tumor cu celule clare cu arhitectură alveolară/nest-like și rețea capilară densă.","Biologie":"Biologie","VHL-Verlust stabilisiert HIF-Signale und fördert u. a. VEGF-abhängige Angiogenese.":"Pierderea VHL stabilizează semnalizarea HIF și favorizează, printre altele, angiogeneza dependentă de VEGF.","Moderne Erstlinienoptionen kombinieren häufig Immuncheckpoint- und VEGFR-gerichtete Strategien.":"Opțiunile moderne de primă linie combină frecvent strategii de checkpoint imun și direcționate către VEGFR.","Biologische Plausibilität versus echte prädiktive Individualisierung.":"Plausibilitate biologică versus individualizare predictivă reală.","Nephrektomieblock und aktuelle Metastasenbiopsie verfügbar.":"Blocul de nefrectomie și biopsia metastazei actuale sunt disponibile.","Testnutzen":"Utilitatea testării","VHL/HIF-Kontext kann die Biologie illustrieren, ist aber für Standard-IO/TKI-Auswahl nicht zwingend als positiver Companion Diagnostic erforderlich.":"Contextul VHL/HIF poate ilustra biologia, dar un companion diagnostic pozitiv nu este obligatoriu pentru selecția standard IO/TKI.","Mehr Molekulardaten dürfen keine Scheingenauigkeit bei der Auswahl zwischen mehreren klinisch etablierten Regimen erzeugen.":"Mai multe date moleculare nu trebuie să creeze o falsă precizie în alegerea dintre mai multe regimuri clinice consacrate.","VHL/HIF/VEGF-Biologie integrieren":"Integrați biologia VHL/HIF/VEGF","VHL/HIF":"VHL/HIF","Inaktivierende VHL-Alteration; Befund passt zur kanonischen ccRCC-Biologie mit HIF-Stabilisierung und proangiogenem Programm.":"Alterare VHL inactivantă; rezultatul se potrivește biologiei canonice ccRCC cu stabilizare HIF și program proangiogenic.","Die ausgeprägte Angiogenese erklärt die Wirksamkeitslogik VEGFR-gerichteter TKIs; die Kombination mit IO adressiert gleichzeitig Tumorimmunität und Gefäß-/TME-Biologie.":"Angiogeneza marcată explică raționamentul pentru TKI direcționate către VEGFR; combinația cu IO abordează simultan imunitatea tumorală și biologia vasculară/TME.","Klarzelliges RCC mit prominentem kapillärem Netzwerk.":"RCC cu celule clare cu rețea capilară proeminentă.","Kernbotschaft":"Mesaj-cheie","Biologischer Driver ≠ alleiniger prädiktiver Regimenselektor.":"Driver biologic ≠ selector predictiv unic al regimului.","Der VHL-Verlust liefert eine sehr plausible biologische Erklärung für HIF-Aktivierung und VEGF-dominierte Angiogenese des klarzelligen RCC. Daraus folgt die biologische Plausibilität VEGFR-gerichteter Therapie und kombinierter IO/VEGFR-Strategien. Der konkrete VHL-Tumorbefund ist jedoch kein alleiniger validierter Selektionsmarker, der eine bestimmte Erstlinienkombination gegenüber allen anderen festlegt.":"Pierderea VHL oferă o explicație biologică foarte plauzibilă pentru activarea HIF și angiogeneza dominată de VEGF în RCC cu celule clare. Aceasta susține plauzibilitatea biologică a terapiei direcționate către VEGFR și a strategiilor combinate IO/VEGFR. Totuși, rezultatul VHL tumoral specific nu este un marker de selecție unic validat care să stabilească o combinație de primă linie în detrimentul tuturor celorlalte.","Teilbefund: VHL/HIF/VEGF erklärt die Erkrankungsbiologie, beantwortet aber die klinische Regimenwahl nicht ohne Gesamtpatientenkontext.":"Rezultat parțial: VHL/HIF/VEGF explică biologia bolii, dar nu răspunde la alegerea regimului fără contextul clinic global.","VHL-Verlust biologisch korrekt über HIF/VEGF erklären":"Explicați biologic pierderea VHL prin HIF/VEGF","Rationale von VEGFR-TKI + IO mechanistisch erläutern":"Explicați mecanistic raționamentul VEGFR-TKI + IO","VHL nicht als alleinigen prädiktiven Regimenselektor verkaufen":"Nu prezentați VHL ca selector predictiv unic al regimului","Risikogruppe, Komorbiditäten und klinische Faktoren in der Therapieentscheidung belassen":"Păstrați grupa de risc, comorbiditățile și factorii clinici în decizia terapeutică","Falschaussage: VHL-Mutation bestimmt zwingend eine bestimmte IO/TKI-Kombination":"Afirmație falsă: mutația VHL impune o combinație IO/TKI specifică","Optimale Lösung: VHL/HIF/VEGF als Lehrbuchbeispiel einer biologisch sehr starken Achse nutzen, ohne daraus einen nicht validierten Präzisionsmarker für die konkrete Regimenwahl zu machen.":"Soluție optimă: utilizați VHL/HIF/VEGF ca exemplu clasic al unei axe biologic foarte puternice fără a o transforma într-un marker de precizie nevalidat pentru alegerea regimului concret.","ccRCC":"ccRCC","VHL":"VHL","HIF":"HIF","VEGFR-TKI":"VEGFR-TKI","VHL erklärt fast alles – aber nicht die konkrete Regimenwahl":"VHL explică aproape totul — dar nu alegerea concretă a regimului","Uroonkologie / Molekularpathologie / MTB":"Oncologie urologică / patologie moleculară / MTB","VHL-Verlust über HIF-Stabilisierung und VEGF-Angiogenese erklären.":"Explicați pierderea VHL prin stabilizarea HIF și angiogeneza VEGF.","Die starke Vaskularisierung des ccRCC biologisch mit VEGFR-TKI verknüpfen.":"Corelați biologic vascularizația intensă a ccRCC cu VEGFR-TKI.","Komplementäre Rationale von IO + VEGFR-TKI verstehen.":"Înțelegeți raționamentul complementar al IO + VEGFR-TKI.","VHL als häufigen biologischen Driver, aber nicht als alleinigen Regimenselektor einordnen.":"Încadrați VHL ca driver biologic frecvent, dar nu ca selector unic al regimului.","Klinische Faktoren neben Tumorbiologie in der Therapiewahl belassen.":"Păstrați factorii clinici alături de biologia tumorală în alegerea tratamentului.","Das Panel zeigt eine klare VHL-Loss-of-function-Mutation. Der Befund ist biologisch wunderschön – so schön, dass man leicht zu viel daraus ableitet und glaubt, er müsse nun exakt eine bestimmte Kombination bestimmen.":"Panelul arată o mutație VHL loss-of-function clară. Rezultatul este biologic elegant — atât de elegant încât este ușor să se deducă prea mult și să se creadă că trebuie să determine acum exact o combinație.","59-jähriger Patient mit metastasiertem klarzelligem RCC und VHL-Loss-of-function. Ziel ist, VHL/HIF/VEGF als Lehrbuchachse zu verstehen und gleichzeitig die Grenze zur klinischen Prädiktion zu ziehen.":"Bărbat de 59 de ani cu RCC cu celule clare metastatic și VHL loss-of-function. Scopul este înțelegerea VHL/HIF/VEGF ca axă clasică și, simultan, trasarea limitei față de predicția clinică.","Kanonische Biologie":"Biologie canonică","VHL-Verlust → HIF-Stabilisierung → proangiogenes Programm.":"Pierdere VHL → stabilizare HIF → program proangiogenic.","ccRCC ist ein Paradebeispiel für pathway-driven Tumorbiologie.":"ccRCC este un exemplu clasic de biologie tumorală pathway-driven.","Therapie-Rationale":"Raționament terapeutic","VEGFR-TKI adressieren die angiogene Achse; IO adressiert Tumorimmunität/TME.":"VEGFR-TKI vizează axa angiogenică; IO vizează imunitatea tumorală/TME.","Kombinationen können biologisch komplementär sein.":"Combinațiile pot fi biologic complementare.","Grenze":"Limită","VHL ist häufig, aber kein alleiniger Selektor zwischen allen Standardregimen.":"VHL este frecvent, dar nu este selectorul unic între toate regimurile standard.","Biologische Erklärung ist stärker als prädiktive Spezifität.":"Explicația biologică este mai puternică decât specificitatea predictivă.","typisches klarzelliges RCC mit feinem Kapillarnetz":"RCC cu celule clare tipic, cu rețea capilară fină","Tumor-NGS":"NGS tumoral","VHL Loss-of-function":"VHL loss-of-function","metastasiert, Erstlinie offen":"Metastatic, prima linie deschisă","Kein zusätzlicher Test muss eine bestimmte IO/TKI-Kombination 'freigeben'.":"Niciun test suplimentar nu trebuie să „autorizeze” o combinație IO/TKI specifică.","VHL-Tumorbefund ist nicht automatisch hereditär; Keimbahnfrage nur bei passendem klinischem Kontext.":"Un rezultat tumoral VHL nu este automat ereditar; întrebarea germinală apare doar într-un context clinic adecvat.","Klinische Risikogruppe, Komorbiditäten und Nebenwirkungsprofile bleiben entscheidend.":"Grupa de risc clinică, comorbiditățile și profilele de toxicitate rămân decisive.","Welche Kette beschreibt die ccRCC-Biologie am besten?":"Care lanț descrie cel mai bine biologia ccRCC?","VHL-Verlust → HIF-Stabilisierung → VEGF/proangiogene Programme.":"Pierdere VHL → stabilizare HIF → programe VEGF/proangiogenice.","KRAS → EGFR → MSI.":"KRAS → EGFR → MSI.","BRCA → HRD → VEGF.":"BRCA → HRD → VEGF.","MMR-Verlust → VHL.":"Pierdere MMR → VHL.","Die VHL/HIF/VEGF-Achse ist kanonisch.":"Axa VHL/HIF/VEGF este canonică.","Warum ist IO + VEGFR-TKI biologisch plausibel?":"De ce este IO + VEGFR-TKI biologic plauzibil?","Gefäß-/TME- und Immunachsen werden komplementär adressiert.":"Axele vasculară/TME și imună sunt abordate complementar.","Weil nur VHL-mutierte Tumoren IO vertragen.":"Pentru că doar tumorile cu mutație VHL tolerează IO.","Beide Medikamente blockieren exakt dasselbe Molekül.":"Ambele medicamente blochează exact aceeași moleculă.","Weil PD-L1 immer hoch sein muss.":"Pentru că PD-L1 trebuie să fie întotdeauna ridicat.","Die Kombination adressiert unterschiedliche, interagierende Ebenen.":"Combinația vizează niveluri diferite care interacționează.","Was darf aus VHL Loss-of-function NICHT abgeleitet werden?":"Ce NU trebuie dedus din VHL loss-of-function?","Dass genau eine bestimmte Erstlinienkombination zwingend die einzig richtige ist.":"Că exact o combinație specifică de primă linie este obligatoriu singura alegere corectă.","Dass HIF/VEGF-Biologie plausibel ist.":"Că biologia HIF/VEGF este plauzibilă.","Dass angiogene Programme typisch sein können.":"Că programele angiogenice pot fi tipice.","Dass der Befund zur ccRCC-Biologie passt.":"Că rezultatul se potrivește biologiei ccRCC.","VHL ist biologisch stark, aber nicht so prädiktiv spezifisch.":"VHL este biologic puternic, dar nu atât de specific predictiv.","Wann wird aus Tumor-VHL eine Keimbahnfrage?":"Când devine un rezultat tumoral VHL o întrebare germinală?","Bei passendem Alter, multifokaler/bilateraler Erkrankung oder VHL-Syndrom-typischem klinischem Kontext – nicht automatisch bei jedem somatischen Tumorbefund.":"La vârsta potrivită, boală multifocală/bilaterală sau context clinic tipic pentru sindrom VHL — nu automat pentru fiecare rezultat tumoral somatic.","Immer.":"Întotdeauna.","Nur wenn TKI versagt.":"Doar dacă TKI eșuează.","Tumor- und Keimbahnebene müssen getrennt werden.":"Nivelurile tumoral și germinal trebuie separate.","Erklären Sie im MTB VHL/HIF/VEGF und die Kombination von antiangiogener und immunologischer Therapie, ohne den VHL-Befund zu einem nicht validierten Ein-Patient-ein-Regime-Marker zu machen.":"Explicați în MTB VHL/HIF/VEGF și combinația dintre terapia antiangiogenică și cea imunologică fără a transforma rezultatul VHL într-un marker nevalidat „un pacient–un regim”.","VHL-Verlust biologisch erklären.":"Explicați biologic pierderea VHL.","HIF/VEGF-Angiogenese ableiten.":"Deduceți angiogeneza HIF/VEGF.","VEGFR-TKI-Rationale erläutern.":"Explicați raționamentul VEGFR-TKI.","IO-Komponente als komplementäre Immun-/TME-Achse erklären.":"Explicați componenta IO ca axă imună/TME complementară.","VHL nicht als alleinigen Regimenselektor überinterpretieren.":"Nu suprainterpretați VHL ca selector unic al regimului.","Keimbahnfrage nur bei klinischem Anlass öffnen.":"Deschideți întrebarea germinală doar la indicație clinică.","Auf VHL-Testung verzichten, wenn Histologie und klinische Therapiefrage bereits klar sind; der Fall nutzt sie als didaktischen Biologieanker.":"Renunțați la testarea VHL când histologia și întrebarea terapeutică clinică sunt deja clare; cazul o folosește ca ancoră didactică de biologie.","Breiteres Panel nur bei zusätzlicher Target-/Studienfrage.":"Folosiți un panel mai larg doar pentru o întrebare suplimentară de target/studiu.","VHL = bestimmtes Regime":"VHL = regim specific","Biologischer Driver besitzt nicht diese prädiktive Spezifität.":"Driverul biologic nu are această specificitate predictivă.","Tumor-VHL = VHL-Syndrom":"VHL tumoral = sindrom VHL","Somatisch und Keimbahn werden verwechselt.":"Somatic și germinal sunt confundate.","VEGF-TKI und IO tun dasselbe":"VEGF-TKI și IO fac același lucru","Komplementäre Mechanismen werden verkannt.":"Mecanismele complementare sunt ignorate.","Der stärkste biologische Befund ist nicht der stärkste Selektionsmarker":"Cel mai puternic rezultat biologic nu este cel mai puternic marker de selecție","VHL Loss-of-function passt perfekt zum Tumor und erklärt die Angiogenese. Trotzdem wählt er nicht allein zwischen den klinisch etablierten Erstlinienoptionen. Der Fall kippt von 'Pathway gefunden' zu 'Evidenzgrad verstanden'.":"VHL loss-of-function se potrivește perfect tumorii și explică angiogeneza. Totuși, nu alege singur între opțiunile clinice consacrate de primă linie. Cazul trece de la „pathway găsit” la „nivelul dovezilor înțeles”.","Präzisionsonkologie braucht Grenzen selbst bei sehr überzeugender Biologie.":"Oncologia de precizie are nevoie de limite chiar și în fața unei biologii foarte convingătoare.","Biologie stark, Prädiktion begrenzt":"Biologie puternică, predicție limitată","VHL/HIF/VEGF korrekt erklärt; IO/TKI plausibel; konkrete Regimenwahl klinisch, nicht allein VHL-basiert.":"VHL/HIF/VEGF explicat corect; IO/TKI plauzibil; alegerea regimului concret este clinică, nu bazată doar pe VHL.","Sehr gute Hierarchie.":"Ierarhie foarte bună.","Achse verstanden, Regime überpräzisiert":"Axa înțeleasă, regimul supra-precizat","VHL korrekt, aber eine Kombination wird molekular zwingend gemacht.":"VHL este corect, dar o combinație este făcută molecular obligatorie.","Biologie überinterpretiert.":"Biologie suprainterpretată.","VHL ignoriert oder germline gesetzt":"VHL ignorat sau atribuit germinal","Entweder zentrale Biologie verpasst oder somatischen Befund automatisch hereditär erklärt.":"Fie biologia centrală este ratată, fie rezultatul somatic este declarat automat ereditar.","Integration misslungen.":"Integrare nereușită.","VHL-Syndrom-verdächtige Klinik":"Clinic suspect pentru sindrom VHL","Humangenetische Abklärung separat initiieren.":"Inițiați separat evaluarea genetică.","Hereditäre Ebene korrekt adressiert.":"Nivelul ereditar este abordat corect.","Standard metastasiertes ccRCC":"ccRCC metastatic standard","Regimenwahl anhand aktueller klinischer Kriterien/Guidelines.":"Alegerea regimului conform criteriilor clinice/guidelines actuale.","Molekularbiologie informiert, ersetzt aber nicht die klinische Auswahl.":"Biologia moleculară informează, dar nu înlocuiește selecția clinică.","VHL/HIF/VEGF ist eine kanonische ccRCC-Achse.":"VHL/HIF/VEGF este o axă canonică ccRCC.","VEGFR-TKI haben eine starke biologische Rationale im hochangiogenen ccRCC.":"VEGFR-TKI au o rațiune biologică puternică în ccRCC intens angiogenic.","IO/VEGFR-Kombinationen adressieren komplementäre Ebenen.":"Combinațiile IO/VEGFR vizează niveluri complementare.","VHL ist kein alleiniger validierter Selektor für ein bestimmtes Standardregime.":"VHL nu este un selector unic validat pentru un regim standard specific.","Somatischer VHL-Befund ist nicht automatisch VHL-Syndrom.":"Un rezultat somatic VHL nu înseamnă automat sindrom VHL.","VHL Loss-of-function erklärt HIF-Stabilisierung und VEGF-dominierte Angiogenese des ccRCC. Diese Biologie macht VEGFR-gerichtete und kombinierte IO/VEGFR-Strategien plausibel, bestimmt aber nicht allein das konkrete Regime. Klinischer Gesamtkontext bleibt entscheidend.":"VHL loss-of-function explică stabilizarea HIF și angiogeneza dominată de VEGF în ccRCC. Această biologie face plauzibile strategiile direcționate către VEGFR și combinațiile IO/VEGFR, dar nu determină singură regimul concret. Contextul clinic global rămâne decisiv.","VHL/HIF/VEGF":"VHL/HIF/VEGF","Kombinationsrationale":"Raționamentul combinației","prädiktive Grenze":"Limită predictivă","somatisch vs germline":"Somatic vs germinal","Warum sind manche Driver diagnostisch stark, aber prädiktiv schwach?":"De ce unii driveri sunt puternici diagnostic, dar slabi predictiv?","Welche TME-Effekte können VEGF-Inhibition immunologisch haben?":"Ce efecte imunologice asupra TME poate avea inhibiția VEGF?","Wann wird eine Tumor-VHL-Variante humangenetisch relevant?":"Când devine o variantă tumorală VHL relevantă pentru genetica medicală?","VHL erklärt Biologie, aber nicht allein das Regime":"VHL explică biologia, dar nu singur regimul","Pathway-Stärke ≠ Selektionsspezifität":"Forța pathway-ului ≠ specificitatea selecției","VHL → HIF/VEGF → TKI/IO-Rationale → klinische Regimenwahl":"VHL → HIF/VEGF → raționament TKI/IO → alegerea clinică a regimului","Rezidiv-Glioblastom unter Bevacizumab: Wenn das MRT besser aussieht als der Tumor":"Glioblastom recidivat sub bevacizumab: când RMN-ul arată mai bine decât tumora","Glioblastom mit Gefäßproliferation…":"Glioblastom cu proliferare vasculară…","Neuroonkologie / Neuro-Radiologie / MTB":"Neuro-oncologie / Neuro-radiologie / MTB","62-jähriger Patient mit rezidiviertem IDH-Wildtyp-Glioblastom, ausgeprägtem perifokalem Ödem und steroidabhängigen neurologischen Symptomen. Bevacizumab wird zur Krankheits- und Symptomkontrolle diskutiert.":"Bărbat de 62 de ani cu glioblastom IDH-wild-type recidivat, edem perifocal marcat și simptome neurologice dependente de steroizi. Bevacizumab este discutat pentru controlul bolii și al simptomelor.","Was kann Anti-VEGF kurzfristig bewirken – und warum darf eine dramatische Abnahme der Kontrastmittelaufnahme nicht automatisch als proportionale Tumorzellreduktion gelesen werden?":"Ce poate realiza anti-VEGF pe termen scurt — și de ce o scădere dramatică a captării de contrast nu trebuie interpretată automat ca o reducere proporțională a celulelor tumorale?","Hoher Symptomdruck durch Ödem.":"Povară simptomatică mare prin edem.","Operation, Radiochemotherapie und Temozolomid; jetzt erstes relevantes Rezidiv.":"Operație, radiochimioterapie și temozolomid; acum prima recidivă relevantă clinic.","Hemiparese und Kopfschmerzen, Dexamethasonbedarf steigend.":"Hemipareză și cefalee, necesar de dexametazonă în creștere.","MRT":"RMN","Stark kontrastmittelaufnehmendes Rezidiv mit ausgeprägtem vasogenem Ödem.":"Recidivă cu captare intensă de contrast și edem vasogenic marcat.","Radiologische Kontrastmittelreduktion nach Anti-VEGF wird mit echter Zytoreduktion gleichgesetzt.":"Reducerea radiologică a captării de contrast după anti-VEGF este echivalată cu o citoreducție reală.","Glioblastomtypische Nekrosen und mikrovaskuläre Proliferation.":"Necroze tipice de glioblastom și proliferare microvasculară.","Hypoxie und proangiogene Signale prägen den Tumor.":"Hipoxia și semnalele proangiogenice caracterizează tumora.","Anti-VEGF-Effekt":"Efect anti-VEGF","Gefäßpermeabilität und Ödem können rasch abnehmen.":"Permeabilitatea vasculară și edemul pot scădea rapid.","Wie wird die Bildgebung nach Therapiebeginn korrekt interpretiert?":"Cum trebuie interpretată corect imagistica după începerea tratamentului?","Archiviertes Resektat ausreichend; keine neue Biopsie allein zur 'VEGF-Testung' erforderlich.":"Piesa de rezecție arhivată este adecvată; nu este necesară o nouă biopsie doar pentru „testarea VEGF”.","Testfalle":"Capcană de testare","Ein RCC-spezifischer VHL/HIF-Test hat hier keinen sinnvollen Selektionsnutzen.":"Un test VHL/HIF specific RCC nu are aici utilitate relevantă de selecție.","Radiologie":"Radiologie","Kontrastmittelaufnahme ist stark von Blut-Hirn-Schranken-Permeabilität abhängig.":"Captarea de contrast depinde puternic de permeabilitatea barierei hemato-encefalice.","Symptomverbesserung kann real sein, auch wenn der antitumorale Effekt begrenzt bleibt.":"Ameliorarea simptomelor poate fi reală chiar dacă efectul antitumoral rămâne limitat.","Anti-VEGF-/Angiogenese-Kontext":"Context anti-VEGF/angiogeneză","GBM zeigt ausgeprägte Gefäßproliferation; Anti-VEGF kann Gefäßpermeabilität und vasogenes Ödem rasch reduzieren.":"GBM prezintă proliferare vasculară marcată; anti-VEGF poate reduce rapid permeabilitatea vasculară și edemul vasogenic.","VHL/HIF-Panel":"Panel VHL/HIF","RCC-spezifische VHL/HIF-Testung liefert für diesen GBM-Fall keinen validierten Therapie-Selektionsnutzen und wäre ein entitätsfremder Low-value-Test.":"Testarea VHL/HIF specifică RCC nu oferă niciun beneficiu validat de selecție terapeutică în acest caz de GBM și ar fi un test low-value nepotrivit entității.","Zusätzliche genomische Information ändert die zentrale Anti-VEGF-/Imaging-Lernfrage nicht.":"Informația genomică suplimentară nu modifică întrebarea centrală despre anti-VEGF/imaging.","MRT vor Therapie":"RMN înainte de terapie","Starke Kontrastmittelaufnahme und ausgeprägtes vasogenes Ödem.":"Captare de contrast intensă și edem vasogenic pronunțat.","Steroidabhängige fokal-neurologische Symptome.":"Simptome neurologice focale dependente de steroizi.","Anti-VEGF kann beim rezidivierten Glioblastom rasch Gefäßpermeabilität und Ödem reduzieren und damit Symptome sowie Kontrastmittelaufnahme deutlich verbessern. Diese radiologische 'Pseudoresponse' darf jedoch nicht mit einer proportionalen Eliminierung infiltrierender Tumorzellen gleichgesetzt werden. Verlaufskontrolle muss deshalb neben Kontrastmittelaufnahme auch FLAIR/non-enhancing disease, Klinik und Steroidbedarf integrieren.":"Anti-VEGF poate reduce rapid permeabilitatea vasculară și edemul în glioblastomul recidivat, ameliorând semnificativ simptomele și captarea de contrast. Totuși, această „pseudoresponse” radiologică nu trebuie echivalată cu eliminarea proporțională a celulelor tumorale infiltrative. Monitorizarea trebuie să integreze captarea de contrast, FLAIR/non-enhancing disease, starea clinică și necesarul de steroizi.","Teilbefund: Die Gefäßreaktion kann eindrucksvoll sein, sagt aber allein wenig über die gesamte infiltrative Tumorlast aus.":"Rezultat parțial: răspunsul vascular poate fi impresionant, dar singur spune puțin despre întreaga povară tumorală infiltrativă.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem erklären":"Explicați efectul anti-VEGF asupra permeabilității vasculare/edemului","Pseudoresponse von echter proportionaler Zytoreduktion trennen":"Separați pseudoresponse de citoreducția proporțională reală","FLAIR/non-enhancing disease und Klinik mitbewerten":"Evaluați și FLAIR/non-enhancing disease și starea clinică","RCC-VHL/HIF-Testung nicht importieren":"Nu importați testarea VHL/HIF din RCC","Falschaussage: 80 % weniger Enhancement = 80 % weniger Tumorzellen":"Afirmație falsă: cu 80% mai puțin enhancement = cu 80% mai puține celule tumorale","Optimale Lösung: Bevacizumab kann klinisch sehr wertvolle Ödem-/Permeabilitätseffekte erzeugen; gerade deshalb muss die beeindruckende MRT-Reaktion als mögliche Pseudoresponse erkannt und multimodal beurteilt werden.":"Soluție optimă: bevacizumab poate produce efecte clinic valoroase asupra edemului/permeabilității; tocmai de aceea răspunsul RMN impresionant trebuie recunoscut ca posibilă pseudoresponse și evaluat multimodal.","Glioblastom":"Glioblastom","Pseudoresponse":"Pseudoresponse","Ödem":"Edem","Das MRT schrumpft schneller als der Tumor":"RMN-ul se micșorează mai repede decât tumora","Neuroonkologie / Neuroradiologie / MTB":"Neuro-oncologie / Neuroradiologie / MTB","VEGF-bedingte Gefäßpermeabilität und Ödem beim GBM erklären.":"Explicați permeabilitatea vasculară și edemul legate de VEGF în GBM.","Anti-VEGF-bedingte Pseudoresponse erkennen.":"Recunoașteți pseudoresponse indusă de anti-VEGF.","Kontrastmittelreduktion nicht direkt in Tumorzellreduktion übersetzen.":"Nu traduceți direct reducerea enhancement-ului în reducerea celulelor tumorale.","FLAIR/non-enhancing disease, Klinik und Steroidbedarf in die Verlaufskontrolle integrieren.":"Integrați FLAIR/non-enhancing disease, starea clinică și necesarul de steroizi în monitorizare.","Entitätsfremde VHL/HIF-Testung vermeiden.":"Evitați testarea VHL/HIF nepotrivită entității.","Zwei Wochen nach Bevacizumab ist die Kontrastmittelaufnahme dramatisch kleiner, der Patient braucht weniger Steroid und fühlt sich besser. Auf den ersten Blick ein spektakuläres Tumoransprechen – bis man versteht, was Anti-VEGF mit der Blut-Hirn-Schranke macht.":"La două săptămâni după bevacizumab, captarea de contrast este dramatic mai mică, pacientul necesită mai puțini steroizi și se simte mai bine. La prima vedere, un răspuns tumoral spectaculos — până când înțelegem ce face anti-VEGF barierei hemato-encefalice.","62-jähriger Patient mit symptomatischem Rezidiv eines IDH-Wildtyp-Glioblastoms. Bevacizumab wird wegen Ödem und Progress eingesetzt. Der Fall lehrt, echte klinische Verbesserung und radiologische Pseudoresponse gleichzeitig richtig zu würdigen.":"Bărbat de 62 de ani cu recidivă simptomatică a unui glioblastom IDH-wild-type. Bevacizumab este utilizat pentru edem și progresie. Cazul arată cum trebuie apreciate corect simultan ameliorarea clinică reală și pseudoresponse radiologică.","Gefäßpermeabilität":"Permeabilitate vasculară","GBM-Gefäße sind abnormal und leaky.":"Vasele GBM sunt anormale și permeabile.","Enhancement ist nicht nur Tumormasse, sondern auch Blut-Hirn-Schranken-Phänomen.":"Enhancement-ul reflectă nu doar masa tumorală, ci și un fenomen al barierei hemato-encefalice.","Anti-VEGF kann wirklich helfen":"Anti-VEGF poate ajuta cu adevărat","Ödem und Steroidbedarf sinken.":"Edemul și necesarul de steroizi scad.","Pseudoresponse bedeutet nicht 'kein Nutzen'.":"Pseudoresponse nu înseamnă „fără beneficiu”.","Aber Imaging kann täuschen":"Dar imagistica poate induce în eroare","Non-enhancing/infiltrative disease kann fortbestehen.":"Non-enhancing/infiltrative disease poate persista.","Response muss multimodal bewertet werden.":"Răspunsul trebuie evaluat multimodal.","Vor Therapie":"Înainte de terapie","starkes Enhancement + massives vasogenes Ödem":"Enhancement intens + edem vasogenic masiv","Hemiparese, Kopfschmerz, Steroidbedarf":"Hemipareză, cefalee, necesar de steroizi","Nekrose + mikrovaskuläre Proliferation":"Necroză + proliferare microvasculară","Keine neue Biopsie nur zur VEGF-Testung nötig.":"Nu este necesară o nouă biopsie doar pentru testarea VEGF.","VHL/HIF-Panel ist hier ein bewusster RCC-Copyover und nicht erforderlich.":"Panelul VHL/HIF este aici un copyover deliberat din RCC și nu este necesar.","Radiologische Verlaufskriterien müssen Anti-VEGF-Effekte berücksichtigen.":"Criteriile radiologice de răspuns trebuie să țină cont de efectele anti-VEGF.","Was erklärt die schnelle Abnahme des Enhancements am besten?":"Ce explică cel mai bine scăderea rapidă a enhancement-ului?","Reduzierte Gefäßpermeabilität/Normalisierung und weniger Ödem können einen großen Anteil beitragen.":"Reducerea permeabilității vasculare/normalizarea și diminuarea edemului pot contribui în mare măsură.","Es beweist proportional dieselbe Abnahme der Tumorzellzahl.":"Dovedește o scădere proporțională a numărului de celule tumorale.","IDH-Mutation entsteht unter Therapie.":"O mutație IDH apare în timpul terapiei.","Es ist immer Strahlennekrose.":"Este întotdeauna necroză post-radioterapie.","Anti-VEGF beeinflusst die Blut-Hirn-Schranke stark.":"Anti-VEGF influențează puternic bariera hemato-encefalică.","Was bedeutet 'Pseudoresponse'?":"Ce înseamnă „pseudoresponse”?","Radiologisch eindrucksvolle Abnahme des Enhancements kann den antitumoralen Zell-Effekt überschätzen.":"O scădere radiologic impresionantă a enhancement-ului poate supraestima efectul antitumoral celular.","Jede klinische Verbesserung ist eingebildet.":"Orice ameliorare clinică este imaginară.","Es bedeutet zwingend Progress.":"Înseamnă obligatoriu progresie.","MRT ist technisch unbrauchbar.":"RMN este tehnic inutilizabil.","Der Nutzen kann real sein, aber Enhancement überschätzt den Zell-Effekt.":"Beneficiul poate fi real, dar enhancement-ul supraestimează efectul celular.","Was muss zusätzlich betrachtet werden?":"Ce trebuie evaluat suplimentar?","FLAIR/non-enhancing disease, Klinik, Steroidbedarf und serieller Verlauf.":"FLAIR/non-enhancing disease, starea clinică, necesarul de steroizi și evoluția serială.","Nur kontrastmittelaufnehmendes Volumen.":"Doar volumul cu enhancement.","VHL-Mutationsstatus.":"Statusul mutației VHL.","PD-L1-IHC.":"IHC PD-L1.","Anti-VEGF erfordert breitere Responsebewertung.":"Anti-VEGF necesită o evaluare mai largă a răspunsului.","Warum ist VHL/HIF-Panel hier falsch?":"De ce este greșit panelul VHL/HIF aici?","Es importiert einen RCC-spezifischen Test ohne validierten Selektionsnutzen in den GBM-Fall.":"Importă în cazul GBM un test specific RCC fără utilitate validată de selecție.","GBM hat keine DNA.":"GBM nu conține ADN.","VEGF ist im GBM irrelevant.":"VEGF este irelevant în GBM.","Nur wegen TAT.":"Doar din cauza TAT.","Angiogenese ist gemeinsam, Testalgorithmen sind entitätsspezifisch.":"Angiogeneza este comună, dar algoritmii de testare sunt specifici entității.","Bewerten Sie die frühe MRT- und klinische Veränderung nach Bevacizumab und formulieren Sie, warum eine starke Kontrastmittelreduktion nicht automatisch eine gleich starke Zytoreduktion bedeutet.":"Evaluați modificările precoce RMN și clinice după bevacizumab și explicați de ce o reducere marcată a enhancement-ului nu înseamnă automat o citoreducție la fel de mare.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem benennen.":"Identificați efectul anti-VEGF asupra permeabilității vasculare/edemului.","Klinische Symptomverbesserung anerkennen.":"Recunoașteți ameliorarea clinică a simptomelor.","Pseudoresponse erklären.":"Explicați pseudoresponse.","FLAIR/non-enhancing disease und seriellen Verlauf integrieren.":"Integrați FLAIR/non-enhancing disease și evoluția serială.","VHL/HIF-Testung vermeiden.":"Evitați testarea VHL/HIF.","Wenn Bildgebung und Klinik diskordant bleiben, neuroradiologische Spezialverfahren/Verlauf nutzen.":"Dacă imagistica și clinica rămân discordante, utilizați tehnici neuroradiologice specializate/monitorizare.","Bevacizumab primär symptomatisch/krankheitskontrollierend diskutieren, ohne radiologische Überversprechen.":"Discutați bevacizumab în principal pentru control simptomatic/al bolii, fără a supra-promite răspunsul radiologic.","Enhancement = Tumorzellzahl":"Enhancement = număr de celule tumorale","BBB-Permeabilität beeinflusst Enhancement stark.":"Permeabilitatea BBB influențează puternic enhancement-ul.","Pseudoresponse = kein Nutzen":"Pseudoresponse = fără beneficiu","Ödem- und Steroidreduktion können klinisch sehr relevant sein.":"Reducerea edemului și a necesarului de steroizi poate fi foarte relevantă clinic.","VHL testen":"Testați VHL","RCC-Copyover ohne Selektionsnutzen.":"Copyover din RCC fără utilitate de selecție.","80 % weniger Enhancement, aber nicht 80 % weniger Tumor":"Cu 80% mai puțin enhancement, dar nu cu 80% mai puțină tumoră","Der Patient verbessert sich und das MRT sieht spektakulär aus. FLAIR zeigt jedoch weiter infiltrative Erkrankung. Der Twist ist doppelt: Der Effekt ist klinisch real und radiologisch zugleich potenziell irreführend.":"Pacientul se ameliorează și RMN-ul arată spectaculos. Totuși, FLAIR arată în continuare boală infiltrativă. Twist-ul este dublu: efectul este clinic real și simultan potențial înșelător radiologic.","Er verhindert sowohl Über- als auch Unterbewertung antiangiogener Therapie.":"Previne atât supraevaluarea, cât și subevaluarea terapiei antiangiogenice.","Pseudoresponse richtig gelesen":"Pseudoresponse interpretată corect","Ödem/Enhancement deutlich geringer, Klinik besser; infiltrative FLAIR-Komponente bleibt → Response nicht als proportionale Zytoreduktion überinterpretieren.":"Edem/enhancement clar reduse, clinică ameliorată; componenta infiltrativă FLAIR persistă → nu suprainterpretați răspunsul ca citoreducție proporțională.","Neuroonkologische Response korrekt.":"Răspuns neuro-oncologic interpretat corect.","Pseudoresponse erkannt, Nutzen abgewertet":"Pseudoresponse recunoscută, beneficiul subestimat","Imaging-Falle erkannt, aber reale Symptom-/Ödemkontrolle fälschlich als bedeutungslos bezeichnet.":"Capcana imagistică este recunoscută, dar controlul real al simptomelor/edemului este declarat greșit lipsit de importanță.","Zu einseitig.":"Prea unilateral.","MRT = Zellzählung":"RMN = număr de celule","Kontrastmittelvolumen wird direkt als Tumormasse interpretiert.":"Volumul cu enhancement este interpretat direct ca masă tumorală.","Zentralen Anti-VEGF-Effekt verpasst.":"Efectul central anti-VEGF este ratat.","Enhancement sinkt, FLAIR stabil/steigend":"Enhancement scade, FLAIR stabil/în creștere","Pseudoresponse/discordant response erwägen und seriell beurteilen.":"Luați în considerare pseudoresponse/răspuns discordant și evaluați serial.","Keine falsche Vollremission.":"Fără remisiune completă falsă.","Steroidbedarf sinkt":"Necesarul de steroizi scade","Als echten klinischen Benefit dokumentieren.":"Documentați ca beneficiu clinic real.","Symptomkontrolle wird nicht kleingeredet.":"Controlul simptomelor nu este minimalizat.","VEGF-Inhibition kann Gefäßpermeabilität und Ödem rasch reduzieren.":"Inhibiția VEGF poate reduce rapid permeabilitatea vasculară și edemul.","Kontrastmittelaufnahme ist beim GBM kein reiner Tumorzellmarker.":"Captarea de contrast în GBM nu este un marker pur al celulelor tumorale.","Pseudoresponse kann gleichzeitig mit echter klinischer Besserung bestehen.":"Pseudoresponse poate coexista cu ameliorare clinică reală.","FLAIR/non-enhancing disease und Klinik gehören in die Verlaufskontrolle.":"FLAIR/non-enhancing disease și starea clinică trebuie incluse în evaluarea de follow-up.","Angiogenese-Biologie rechtfertigt nicht automatisch VHL/HIF-Tumortestung.":"Biologia angiogenezei nu justifică automat testarea tumorală VHL/HIF.","Nach Bevacizumab sinken Enhancement, Ödem und Steroidbedarf deutlich. Das ist klinisch relevant, kann aber den zytoreduktiven Effekt überschätzen. FLAIR/non-enhancing disease und Verlauf müssen integriert werden; ein RCC-artiges VHL/HIF-Panel hat keinen Selektionsnutzen.":"După bevacizumab, enhancement-ul, edemul și necesarul de steroizi scad marcat. Acest lucru este relevant clinic, dar poate supraestima efectul citoreductiv. FLAIR/non-enhancing disease și evoluția trebuie integrate; un panel VHL/HIF de tip RCC nu are utilitate de selecție.","Ödem vs Tumor":"Edem vs tumoră","multimodale Bildgebung":"Imagistică multimodală","kein RCC-Copyover":"Fără copyover RCC","Wie unterscheiden sich Pseudoprogression und Pseudoresponse?":"Cum diferă pseudoprogression și pseudoresponse?","Welche klinischen Parameter helfen bei anti-VEGF?":"Ce parametri clinici ajută în timpul terapiei anti-VEGF?","Warum ist Enhancement biologisch kein einfacher Tumormasse-Readout?":"De ce enhancement-ul nu este biologic un readout simplu al masei tumorale?","dramatische MRT-Besserung trotz persistierender FLAIR-Krankheit":"Ameliorare dramatică RMN în ciuda bolii FLAIR persistente","Anti-VEGF verändert Bildgebung und Klinik unterschiedlich":"Anti-VEGF modifică diferit imagistica și starea clinică","VEGF/Ödem → Bevacizumab → Enhancement fällt → multimodale Response":"VEGF/edem → bevacizumab → enhancement scade → evaluare multimodală a răspunsului","PD-L1 und TMB sehen gut aus – aber die T-Zellen bleiben im Stroma":"PD-L1 și TMB arată favorabil — dar celulele T rămân în stromă","Stromareicher Tumor mit immune-exc…":"Tumoră bogată în stromă cu immune-exc…","68-jähriger Patient mit metastasiertem Urothelkarzinom. Vor Checkpoint-Therapie lagen PD-L1-Expression und eine relativ hohe Mutationslast vor; klinisch kam es dennoch zu frühem Progress.":"Bărbat de 68 de ani cu carcinom urotelial metastatic. Înainte de terapia checkpoint existau expresie PD-L1 și o încărcătură mutațională relativ ridicată; totuși a apărut progresie clinică precoce.","Wie kann ein scheinbar immunogener Tumor trotzdem primär resistent sein – und was lehrt die räumliche Verteilung der Immunzellen?":"Cum poate o tumoră aparent imunogenă să fie totuși primar rezistentă — și ce ne învață distribuția spațială a celulelor imune?","Retrospektive Einordnung und Studienplanung für die nächste Linie.":"Interpretare retrospectivă și planificarea studiului pentru linia următoare.","PD-L1 hoch; TMB erhöht; kein MSI-H-Kontext.":"PD-L1 ridicat; TMB crescut; fără context MSI-H.","Checkpoint-Inhibition mit frühem radiologischem Progress.":"Inhibiție checkpoint cu progresie radiologică precoce.","Biopsie":"Biopsie","Progressionsbiopsie zeigt stark stromareichen Tumor.":"Biopsia de progresie arată o tumoră foarte bogată în stromă.","Biomarkerwerte werden ohne räumlichen Zellkontext als Garantie für Immunantwort interpretiert.":"Valorile biomarkerilor sunt interpretate ca garanție a răspunsului imun fără contextul spațial celular.","Invasive Tumornester in breiten fibrotischen Stromasepten.":"Cuiburi tumorale invazive în septuri stromale fibroase largi.","CD8":"CD8","Viele T-Zellen vorhanden, aber überwiegend im peritumoralen Stroma; Tumorzellnester selbst sind arm an CD8-Zellen.":"Sunt prezente multe celule T, dar predominant în stroma peritumorală; cuiburile tumorale în sine conțin puține celule CD8.","CAF-Kontext":"Context CAF","FAP/αSMA-reiches aktiviertes Stroma.":"Stromă activată bogată în FAP/αSMA.","Immune-excluded statt wirklich inflamed/hot.":"Immune-excluded mai degrabă decât cu adevărat inflamat/hot.","Progressionsbiopsie mit 45 % Tumoranteil.":"Biopsie de progresie cu 45% conținut tumoral.","ausreichend für fokussierte TIL-/Stroma-IHC.":"Adecvată pentru IHC focalizată TIL/stromă.","Evidenzgrenze":"Limită a dovezilor","TME-IHC erklärt die Resistenzbiologie, ist aber kein routinemäßiger alleiniger Therapieausschluss- oder Auswahltest.":"IHC TME explică biologia rezistenței, dar nu este un test de rutină de excludere sau selecție terapeutică de sine stătător.","Räumliche Biologie nicht mit einem neuen Companion Diagnostic verwechseln.":"Nu confundați biologia spațială cu un nou companion diagnostic.","Stroma-/Immune-exclusion-Kontext":"Context stromă/immune-exclusion","PD-L1 bleibt deutlich exprimiert; der Befund allein erklärt die fehlende klinische Antwort nicht.":"PD-L1 rămâne exprimat clar; acest rezultat singur nu explică lipsa răspunsului clinic.","TMB erhöht. Potenziell vorhandene Neoantigene garantieren dennoch keine effektive T-Zell-Interaktion mit den Tumorzellen.":"TMB crescut. Neoantigenele potențiale nu garantează totuși interacțiunea eficientă a celulelor T cu celulele tumorale.","TIL-Verteilung":"Distribuția TIL","CD8-positive T-Zellen sind zahlreich, bleiben jedoch überwiegend stromal/peritumoral; intratumorale Penetration ist gering.":"Celulele T CD8-pozitive sunt numeroase, dar rămân predominant stromale/peritumorale; penetrarea intratumorală este redusă.","Stroma":"Stromă","Breites FAP/αSMA-positives fibroblastenreiches Stroma stützt ein immune-excluded Muster. Der Befund ist mechanistisch plausibel, aber kein allein validierter Therapie-Selektionsassay.":"Stroma largă, bogată în fibroblaste FAP/αSMA-pozitive, susține un model immune-excluded. Rezultatul este mecanistic plauzibil, dar nu reprezintă un assay validat de sine stătător pentru selecția terapiei.","Klinischer Twist":"Twist clinic","Früher Progress trotz scheinbar günstiger Immunmarker.":"Progresie precoce în ciuda markerilor imunologici aparent favorabili.","Stark stromareicher Tumor mit räumlicher Trennung von CD8-Zellen und Tumornestern.":"Tumoră foarte bogată în stromă, cu separare spațială între celulele CD8 și cuiburile tumorale.","PD-L1-Expression und erhöhte TMB können immunologische Potenziale anzeigen, garantieren aber keine effektive Antitumor-Immunität. Die Progressionsbiopsie zeigt ein klassisches immune-excluded Muster: T-Zellen sind vorhanden, werden jedoch durch das stromale Mikromilieu räumlich von Tumorzellen ferngehalten. Dieser Befund erklärt Resistenzbiologie, darf aber nicht als alleiniger validierter Companion Diagnostic für eine konkrete Folgetherapie überinterpretiert werden.":"Expresia PD-L1 și TMB crescut pot indica potențial imunologic, dar nu garantează imunitate antitumorală eficientă. Biopsia de progresie arată un model clasic immune-excluded: celulele T sunt prezente, dar microambientul stromal le menține spațial departe de celulele tumorale. Acest lucru explică biologia rezistenței, dar nu trebuie suprainterpretat ca un companion diagnostic validat de sine stătător pentru o terapie ulterioară concretă.","Teilbefund: Gute Biomarkerwerte ohne räumliche TIL-Analyse erklären die tatsächliche Immunfunktion nur unvollständig.":"Rezultat parțial: valori favorabile ale biomarkerilor fără analiză spațială TIL descriu incomplet funcția imună reală.","TMB/PD-L1 als Potenzialmarker von funktioneller T-Zell-Tumor-Interaktion trennen":"Separați TMB/PD-L1 ca markeri de potențial de interacțiunea funcțională celulă T–tumoră","Immune exclusion über räumliche CD8-Verteilung erkennen":"Recunoașteți immune exclusion prin distribuția spațială CD8","CAF-/Stroma-Barriere biologisch erklären":"Explicați biologic bariera CAF/stromală","TME-IHC nicht zum nicht validierten Therapieausschlusstest machen":"Nu transformați IHC TME într-un test nevalidat de excludere terapeutică","Falschaussage: hohe TMB + PD-L1 garantieren Checkpoint-Ansprechen":"Afirmație falsă: TMB ridicat + PD-L1 garantează răspunsul la checkpoint","Optimale Lösung: PD-L1/TMB nicht als Garantie interpretieren; die räumliche TIL-Verteilung zeigt, dass Immunzellen vorhanden, aber funktionell vom Tumor ausgeschlossen sind. Mechanistisch stark, prädiktiv aber nicht als alleiniger Routinetest validiert.":"Soluție optimă: nu interpretați PD-L1/TMB ca garanție; distribuția spațială TIL arată că celulele imune sunt prezente, dar funcțional excluse de la tumoră. Mecanic puternic, dar nevalidat ca test predictiv de rutină de sine stătător.","CAF":"CAF","Urothelkarzinom":"Carcinom urotelial","Viele T-Zellen – aber auf der falschen Seite der Stromabarriere":"Multe celule T — dar pe partea greșită a barierei stromale","Molekularpathologie / Immunonkologie / MTB":"Patologie moleculară / Imuno-oncologie / MTB","PD-L1/TMB als Potenzialmarker von funktioneller Immunantwort unterscheiden.":"Distingeți PD-L1/TMB ca markeri de potențial de răspunsul imun funcțional.","Immune-excluded Muster anhand räumlicher TIL-Verteilung erkennen.":"Recunoașteți un model immune-excluded din distribuția spațială TIL.","CAF-/Stromabarriere als Resistenzmechanismus erklären.":"Explicați bariera CAF/stromală ca mecanism de rezistență.","TME-IHC als mechanistischen und nicht automatisch validierten Selektionsmarker einordnen.":"Încadrați IHC TME ca mecanistică, nu automat ca marker validat de selecție.","Klinische Nonresponse trotz günstiger Einzelmarker biologisch plausibel erklären.":"Explicați biologic nonresponse clinic în ciuda markerilor individuali favorabili.","PD-L1 ist hoch, TMB ist erhöht – und der Tumor wächst unter Checkpoint-Inhibition trotzdem weiter. In der Progressionsbiopsie sind sogar viele CD8-T-Zellen zu sehen. Das Problem: Sie stehen fast alle draußen im Stroma.":"PD-L1 este ridicat, TMB este crescut — și tumora continuă să crească sub inhibiție checkpoint. Biopsia de progresie arată chiar multe celule T CD8. Problema: aproape toate rămân în afara tumorii, în stromă.","68-jähriger Patient mit metastasiertem Urothelkarzinom und frühem Progress unter ICI trotz scheinbar günstiger PD-L1-/TMB-Konstellation. Die Progressionsbiopsie zeigt, dass nicht die Zahl allein, sondern die räumliche Position der Immunzellen entscheidend ist.":"Bărbat de 68 de ani cu carcinom urotelial metastatic și progresie precoce sub ICI în ciuda unei constelații aparent favorabile PD-L1/TMB. Biopsia de progresie arată că nu doar numărul, ci și poziția spațială a celulelor imune este decisivă.","Potenzial":"Potențial","PD-L1 hoch, TMB erhöht.":"PD-L1 ridicat, TMB crescut.","Diese Marker können Immunogenität anzeigen, garantieren aber keine effektive Antwort.":"Acești markeri pot indica imunogenitate, dar nu garantează un răspuns eficient.","Raum":"Spațiu","CD8-Zellen liegen vor allem stromal/peritumoral.":"Celulele CD8 sunt localizate mai ales stromal/peritumoral.","Immune exclusion ist ein räumliches Phänomen.":"Immune exclusion este un fenomen spațial.","Barriere":"Barieră","FAP/αSMA-reiches Stroma.":"Stromă bogată în FAP/αSMA.","CAF/Matrix können physische und signalbiologische Barrieren bilden.":"CAF/matricea pot forma bariere fizice și de semnalizare.","deutlich exprimiert":"Exprimat clar","erhöht":"Crescut","früher Progress unter Checkpoint-Inhibition":"Progresie precoce sub inhibiție checkpoint","Progressionsbiopsie ermöglicht räumliche TIL-/Stroma-Bewertung.":"Biopsia de progresie permite evaluarea spațială TIL/stromă.","TME-Marker sind keine validierte alleinige Folgetherapie-Selektion.":"Markerii TME nu sunt validați ca teste independente de selecție pentru terapia ulterioară.","Mechanistische Erklärung darf nicht in Pseudopräzision kippen.":"Explicația mecanistică nu trebuie să devină pseudo-precizie.","Was ist die wichtigste Erklärung für PD-L1/TMB ohne Response?":"Care este cea mai importantă explicație pentru PD-L1/TMB fără răspuns?","Marker zeigen Potenzial, aber nicht zwingend erfolgreiche T-Zell-Penetration und Funktion im Tumornest.":"Markerii indică potențial, dar nu neapărat penetrare și funcție reușite ale celulelor T în cuiburile tumorale.","PD-L1 und TMB müssen technisch falsch sein.":"PD-L1 și TMB trebuie să fie tehnic greșite.","So eine Konstellation ist unmöglich.":"O astfel de constelație este imposibilă.","Hohe TMB beweist MSI-H.":"TMB ridicat dovedește MSI-H.","Biomarker und Funktion sind unterschiedliche Ebenen.":"Biomarkerii și funcția sunt niveluri diferite.","Welcher Befund definiert immune exclusion am besten?":"Ce rezultat definește cel mai bine immune exclusion?","Viele T-Zellen im Stroma, wenige innerhalb der Tumorzellnester.":"Multe celule T în stromă, puține în cuiburile tumorale.","Gar keine Immunzellen im gesamten Präparat.":"Nicio celulă imună în întregul preparat.","Dichtes intraepitheliales CD8-Infiltrat.":"Infiltrat CD8 intraepitelial dens.","PD-L1 hoch.":"PD-L1 ridicat.","Räumliche Verteilung ist zentral.":"Distribuția spațială este centrală.","Wie darf FAP/αSMA/CD8-IHC genutzt werden?":"Cum poate fi utilizată IHC FAP/αSMA/CD8?","Als mechanistische Unterstützung eines stromal-excluded Musters, nicht als alleiniger zugelassener Companion Diagnostic.":"Ca suport mecanistic pentru un model stromal-excluded, nu ca companion diagnostic aprobat de sine stătător.","Als absolute Kontraindikation gegen jede ICI.":"Ca o contraindicație absolută pentru orice ICI.","Als Beweis für eine Standard-CAF-Therapie.":"Ca dovadă pentru o terapie CAF standard.","Gar nicht interpretieren.":"Nu o interpretați deloc.","Mechanistisch stark, klinisch nicht allein selektiv validiert.":"Mecanic puternic, dar nevalidat clinic ca selector de sine stătător.","Was ist die beste MTB-Kommunikation?":"Care este cea mai bună comunicare în MTB?","Günstige Einzelmarker anerkennen, reale Nonresponse und spatial TME integrieren, experimentelle TME-Strategien als Studienoption kennzeichnen.":"Recunoașteți markerii individuali favorabili, integrați nonresponse real și TME spațial și etichetați strategiile experimentale TME ca opțiuni de studiu.","PD-L1 so oft wiederholen, bis ein höherer Wert entsteht.":"Repetați PD-L1 până apare o valoare mai mare.","TMB/PD-L1 als nutzlos erklären.":"Declarați TMB/PD-L1 inutile.","CAF-Targeting als Standard empfehlen.":"Recomandați CAF-targeting ca standard.","Evidenzhierarchie + Biologie.":"Ierarhia dovezilor + biologie.","Erklären Sie die primäre Resistenz trotz PD-L1/TMB und formulieren Sie, welche Aussage die Progressionsbiopsie liefert – und welche Therapieentscheidung sie gerade nicht allein rechtfertigt.":"Explicați rezistența primară în ciuda PD-L1/TMB și formulați ce arată biopsia de progresie — și ce decizie terapeutică nu justifică singură.","PD-L1/TMB als Potenzial, nicht Garantie einordnen.":"Încadrați PD-L1/TMB ca potențial, nu garanție.","CD8-Verteilung räumlich beschreiben.":"Descrieți spațial distribuția CD8.","Immune exclusion erkennen.":"Recunoașteți immune exclusion.","CAF-/Stromabarriere mechanistisch erklären.":"Explicați mecanistic bariera CAF/stromală.","TME-IHC nicht als alleinigen Companion Diagnostic verwenden.":"Nu utilizați IHC TME ca companion diagnostic de sine stătător.","Studienoptionen klar als experimentell markieren.":"Marcați clar opțiunile de studiu ca experimentale.","Wenn keine Progressionsbiopsie verfügbar ist, morphologische/radiologische Daten nutzen und TME-Hypothese als Hypothese belassen.":"Dacă nu este disponibilă biopsie de progresie, utilizați date morfologice/radiologice și păstrați ipoteza TME ca ipoteză.","TME-gerichtete Studien bei passender Verfügbarkeit diskutieren.":"Discutați studii direcționate către TME dacă sunt disponibile adecvat.","PD-L1/TMB garantieren Response":"PD-L1/TMB garantează răspunsul","Funktionelle Immunantwort braucht mehr als Potenzialmarker.":"Răspunsul imun funcțional necesită mai mult decât markeri de potențial.","TME-IHC = Therapieausschluss":"IHC TME = excludere terapeutică","Nicht als alleiniger validierter Selektionsassay etabliert.":"Nu este stabilit ca assay de selecție validat de sine stătător.","CAF-Targeting Standard":"CAF targeting standard","Mechanismus wird zu Routineempfehlung überhöht.":"Un mecanism este exagerat până la recomandare de rutină.","Die T-Zellen sind da – und kommen trotzdem nicht an den Tumor":"Celulele T sunt acolo — și totuși nu ajung la tumoră","Die Progressionsbiopsie zeigt viele CD8-Zellen, aber fast ausschließlich in FAP/αSMA-reichem Stroma. Der scheinbare Widerspruch zwischen 'immunogen' und 'resistent' löst sich räumlich auf.":"Biopsia de progresie arată multe celule CD8, dar aproape exclusiv în stroma bogată în FAP/αSMA. Contradicția aparentă dintre „imunogen” și „rezistent” se rezolvă spațial.","Der Fall macht aus TME ein sichtbares diagnostisches Konzept statt einer abstrakten Signalwegfolie.":"Cazul transformă TME într-un concept diagnostic vizibil, nu într-un slide abstract de pathway.","Spatial biology integriert":"Biologie spațială integrată","PD-L1/TMB günstig, aber CD8 stromal ausgeschlossen; TME erklärt Resistenz, ohne einen neuen Companion Diagnostic zu behaupten.":"PD-L1/TMB favorabile, dar celulele CD8 sunt excluse stromal; TME explică rezistența fără a pretinde un nou companion diagnostic.","Biologie und Evidenz sauber getrennt.":"Biologia și dovezile sunt separate clar.","Stroma erkannt, Marker verworfen":"Stroma recunoscută, markerii respinși","Immune exclusion korrekt, aber PD-L1/TMB pauschal als wertlos dargestellt.":"Immune exclusion este corect, dar PD-L1/TMB sunt declarate global fără valoare.","Zu absolut.":"Prea absolut.","Biomarker-Garantie":"Garanție prin biomarker","Früher Progress wird ignoriert, weil PD-L1/TMB 'gut' sind.":"Progresia precoce este ignorată pentru că PD-L1/TMB sunt „bune”.","Funktionelle Ebene verpasst.":"Nivelul funcțional este ratat.","Studie mit TME-gerichteter Kombination verfügbar":"Studiu cu combinație TME-directed disponibil","Als experimentelle Option diskutieren.":"Discutați ca opțiune experimentală.","Mechanistische Hypothese wird im passenden Evidenzrahmen genutzt.":"Ipoteza mecanistică este utilizată în cadrul adecvat al dovezilor.","Keine Studie":"Fără studiu","Standardtherapie nach etablierter Entitätslogik.":"Terapie standard conform logicii consacrate specifice entității.","TME-Befund bleibt erklärend, nicht pseudoprädiktiv.":"Rezultatul TME rămâne explicativ, nu pseudo-predictiv.","Biomarker können Potenzial anzeigen, aber keine Antwort garantieren.":"Biomarkerii pot indica potențial, dar nu pot garanta răspunsul.","Immune exclusion ist räumlich: Immunzellen vorhanden, aber vom Tumornest ferngehalten.":"Immune exclusion este spațial: celulele imune sunt prezente, dar ținute departe de cuiburile tumorale.","CAF-/Matrix-Komponenten können physische und signalbiologische Barrieren bilden.":"Componentele CAF/matrice pot forma bariere fizice și de semnalizare.","TME-IHC ist mechanistisch wertvoll, aber kein automatisch validierter Companion Diagnostic.":"IHC TME este valoroasă mecanistic, dar nu este automat un companion diagnostic validat.","Progressionsmaterial kann Resistenzbiologie sichtbar machen.":"Materialul de progresie poate evidenția biologia rezistenței.","Trotz PD-L1 und erhöhter TMB zeigt die Progressionsbiopsie ein immune-excluded Muster mit CD8-Zellen im stromalen Kompartiment. Das erklärt die fehlende effektive Tumorinteraktion, ist aber kein alleiniger routinemäßiger Selektionsmarker für eine konkrete Folgetherapie.":"În ciuda PD-L1 și TMB crescut, biopsia de progresie arată un model immune-excluded cu celule CD8 în compartimentul stromal. Aceasta explică lipsa interacțiunii tumorale eficiente, dar nu este un marker de selecție de rutină de sine stătător pentru o terapie ulterioară specifică.","Marker vs Funktion":"Markeri vs funcție","spatial TILs":"TIL spațiali","Stromabarriere":"Barieră stromală","Was ist der Unterschied zwischen immune-desert und immune-excluded?":"Care este diferența dintre immune-desert și immune-excluded?","Welche Rolle kann TGF-β/CAF-Biologie spielen?":"Ce rol poate avea biologia TGF-β/CAF?","Wie könnte Digitalpathologie spatial TILs künftig standardisieren?":"Cum ar putea patologia digitală standardiza TIL spațiali în viitor?","viele CD8-Zellen, aber außerhalb der Tumornester":"Multe celule CD8, dar în afara cuiburilor tumorale","Räumliche Immunbiologie kann Einzelmarker widersprechen":"Biologia imună spațială poate contrazice markerii individuali","PD-L1/TMB → Nonresponse → spatial biopsy → immune exclusion":"PD-L1/TMB → nonresponse → biopsie spațială → immune exclusion","pT1-CRC nach Endoskopie: Tumor budding als sichtbarer Invasions-Hallmark":"CRC pT1 după endoscopie: tumor budding ca hallmark vizibil al invaziei","EMT-/Invasionsfront-Fall mit Metas…":"Caz EMT/front de invazie cu metas…","Gastroenterologie / Viszeralchirurgie / Pathologieboard":"Gastroenterologie / Chirurgie viscerală / Board de patologie","56-jähriger Patient nach endoskopischer en-bloc-Resektion eines pT1-Sigmakarzinoms. Die Frage ist, ob die lokale Therapie ausreicht oder wegen Lymphknotenrisiko eine onkologische Nachresektion diskutiert werden muss.":"Bărbat de 56 de ani după rezecție endoscopică en-bloc a unui carcinom sigmoid pT1. Întrebarea este dacă terapia locală este suficientă sau trebuie discutată o rezecție oncologică suplimentară din cauza riscului ganglionar.","Welche morphologischen Merkmale an der Invasionsfront sind klinisch relevant – und welche Rolle spielt das EMT-Konzept dabei?":"Ce caracteristici morfologice la frontul de invazie sunt relevante clinic — și ce rol are conceptul EMT?","Entscheidung über weitere Operation im nächsten Board.":"Decizie privind o intervenție suplimentară la următorul board.","Endoskopie":"Endoscopie","20-mm-Läsion, vollständig en bloc reseziert.":"Leziune de 20 mm, rezecată complet en bloc.","pT1-Adenokarzinom, Resektionsrand tumorfrei.":"Adenocarcinom pT1, margine de rezecție fără tumoră.","Konflikt":"Conflict","Ein 'R0' klingt beruhigend, aber R0 beantwortet das Risiko okkulter Lymphknotenmetastasen nicht allein.":"Un „R0” sună liniștitor, dar R0 singur nu răspunde riscului de metastaze ganglionare oculte.","Ein experimentelles EMT-IHC-Panel wird höher gewichtet als validierte histopathologische Risikofaktoren.":"Un panel IHC EMT experimental este ponderat mai mult decât factorii de risc histopatologici validați.","Histologie + Invasionsfront":"Histologie + front de invazie","Submukosale Invasion; an der tiefsten Front zahlreiche Einzelzellen und kleine Tumorzellcluster entsprechend hochgradigem Tumor budding.":"Invazie submucoasă; la frontul cel mai profund, numeroase celule izolate și mici grupuri tumorale corespunzătoare unui tumor budding de grad înalt.","Weitere Risiken":"Riscuri suplimentare","Fokale lymphovaskuläre Invasion; keine schlechte Differenzierung.":"Invazie limfovasculară focală; fără diferențiere slabă.","EMT-Kontext":"Context EMT","An Buds fokal reduzierte membranäre E-Cadherin-Expression und veränderte β-Catenin-Lokalisation möglich – biologisch passend zu partieller EMT.":"La buds pot apărea reducere focală a expresiei membranare E-cadherin și localizare modificată a β-catenin — biologic compatibile cu EMT parțial.","Morphologischer Risikomarker versus mechanistischer Zusatzbefund.":"Marker de risc morfologic versus rezultat mecanistic suplimentar.","Komplettes endoskopisches Resektat, gut orientiert.":"Piesă de rezecție endoscopică completă, bine orientată.","Primärentscheidung":"Decizie principală","HE-basierte Bewertung von Budding, LVI, Differenzierung, Invasionstiefe und Resektionsrand.":"Evaluare pe HE a budding-ului, LVI, diferențierii, profunzimii invaziei și marginii de rezecție.","Zusatz-IHC":"IHC suplimentară","EMT-Panel kann den Hallmark illustrieren, ist aber nicht erforderlich, um den klinischen Hochrisikobefund zu erkennen.":"Un panel EMT poate ilustra hallmark-ul, dar nu este necesar pentru a recunoaște rezultatul clinic de risc înalt.","Mechanismusmarker dürfen die standardisierte Morphologie nicht verdrängen.":"Markerii mecanistici nu trebuie să înlocuiască morfologia standardizată.","Histologische Invasionsfront / Risikofaktoren":"Front histologic de invazie / factori de risc","HE / Invasionsfront":"HE / front de invazie","Hochgradiges Tumor budding an der tiefen Invasionsfront plus fokale lymphovaskuläre Invasion. Diese histopathologischen Hochrisikofaktoren sind für die Entscheidung nach endoskopischer pT1-Resektion klinisch relevant.":"Tumor budding de grad înalt la frontul profund de invazie plus invazie limfovasculară focală. Acești factori histopatologici de risc înalt sunt relevanți clinic pentru decizia după rezecția endoscopică pT1.","EMT-IHC":"IHC EMT","Buds zeigen fokal reduzierte E-Cadherin-Membranfärbung, Vimentin-Zunahme und veränderte β-Catenin-Lokalisation – mechanistisch vereinbar mit partieller EMT, aber kein eigenständiger validierter Operationsindikator.":"Buds arată focal colorare membranară E-cadherin redusă, creștere vimentin și localizare modificată β-catenin — mecanistic compatibil cu EMT parțial, dar nu o indicație chirurgicală independentă validată.","Breite Tumorgenetik liefert für die unmittelbare pT1-Risikostratifikation keinen Ersatz für die relevanten histopathologischen Invasionsmerkmale.":"Genetica tumorală largă nu înlocuiește caracteristicile histopatologice relevante de invazie pentru stratificarea imediată a riscului pT1.","Resektion":"Rezecție","Endoskopisch R0.":"R0 endoscopic.","Invasionsfront":"Front de invazie","Hochgradiges Tumor budding und fokale Lymphgefäßinvasion.":"Tumor budding de grad înalt și invazie limfatică focală.","Der Fall verbindet Morphologie und Hallmark-Biologie: Tumor budding an der Invasionsfront ist ein sichtbares Korrelat invasiver/plastischer Tumorzellzustände und bei pT1-CRC ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen. EMT-IHC kann die Biologie illustrieren, entscheidet aber nicht über die weitere Operation. Die klinische Konsequenz entsteht aus standardisierten Hochrisikofaktoren wie Budding, LVI, Differenzierung, Tiefe und Resektionsstatus.":"Cazul leagă morfologia de biologia hallmark: tumor budding la frontul de invazie este un corelat vizibil al stărilor invazive/plastice ale celulelor tumorale și un factor histopatologic consacrat de risc pentru metastaze ganglionare în CRC pT1. IHC EMT poate ilustra biologia, dar nu decide intervenția suplimentară. Consecința clinică rezultă din factori standardizați de risc înalt precum budding, LVI, diferențiere, profunzime și status de rezecție.","Teilbefund: EMT ist biologisch plausibel, aber die klinische Risikoeinschätzung muss an validierten histopathologischen Merkmalen hängen.":"Rezultat parțial: EMT este biologic plauzibil, dar evaluarea riscului clinic trebuie să se bazeze pe caracteristici histopatologice validate.","Tumor budding als klinisch relevanten Invasionsfront-Befund erkennen":"Recunoașteți tumor budding ca rezultat clinic relevant al frontului de invazie","R0 nicht mit niedrigem Lymphknotenrisiko gleichsetzen":"Nu echivalați R0 cu risc ganglionar scăzut","EMT als mechanistische Erklärung, nicht als eigenständigen Routine-Selektionsassay einordnen":"Încadrați EMT ca explicație mecanistică, nu ca assay de rutină independent de selecție","HE-basierte standardisierte Risikofaktoren priorisieren":"Prioritizați factorii de risc standardizați bazați pe HE","Falschaussage: ein positives EMT-IHC-Panel ist die Operationsindikation":"Afirmație falsă: un panel IHC EMT pozitiv reprezintă indicația operatorie","Optimale Lösung: Morphologie zuerst. High-grade budding und LVI machen den pT1-Fall trotz R0 klinisch risikorelevant; EMT-IHC erklärt das Hallmark, ersetzt aber nicht die standardisierte histopathologische Entscheidung.":"Soluție optimă: morfologia mai întâi. Budding de grad înalt și LVI fac cazul pT1 clinic cu risc înalt în ciuda R0; IHC EMT explică hallmark-ul, dar nu înlocuiește decizia histopatologică standardizată.","pT1 CRC":"CRC pT1","Tumor budding":"Tumor budding","Invasion":"Invazie","EMT":"EMT","Lymphovascular invasion":"Invazie limfovasculară","Hallmarks":"Hallmarks","Tumor budding: Hallmark im HE statt EMT-Overtesting":"Tumor budding: hallmark vizibil pe HE în loc de EMT overtesting","GI-Pathologie / Molekularpathologie / MTB":"Patologie GI / Patologie moleculară / MTB","Tumor budding als morphologisches Korrelat invasiver/plastischer Tumorzellzustände erkennen.":"Recunoașteți tumor budding ca un corelat morfologic al stărilor invazive/plastice ale celulelor tumorale.","Bei pT1-CRC klinisch relevante histopathologische Hochrisikofaktoren priorisieren.":"Prioritizați factorii histopatologici de risc înalt relevanți clinic în CRC pT1.","R0-Resektion von Lymphknotenrisiko unterscheiden.":"Distingeți rezecția R0 de riscul ganglionar.","EMT-IHC als mechanistische Illustration und nicht als eigenständigen Operationsindikator einordnen.":"Încadrați IHC EMT ca ilustrare mecanistică, nu ca indicație chirurgicală de sine stătătoare.","Morphologie direkt mit Hallmark-Biologie und klinischer Konsequenz verbinden.":"Conectați direct morfologia cu biologia hallmark și consecința clinică.","Der Polyp ist komplett raus, der Rand ist frei – eigentlich klingt alles gut. An der tiefen Invasionsfront stehen jedoch zahlreiche einzelne Tumorzellen und kleine Cluster: High-grade tumor budding. Genau dort wird ein abstrakter Hallmark plötzlich klinisch sichtbar.":"Polipul este scos complet, marginea este liberă — totul sună bine. Totuși, la frontul profund de invazie se observă numeroase celule tumorale izolate și mici grupuri: tumor budding de grad înalt. Exact aici un hallmark abstract devine brusc vizibil clinic.","56-jähriger Patient nach endoskopischer R0-Resektion eines pT1-Sigmakarzinoms. Das Board muss entscheiden, ob wegen histopathologischer Hochrisikofaktoren eine onkologische Nachresektion diskutiert werden sollte. EMT ist die biologische Erklärung, aber nicht der primäre klinische Test.":"Bărbat de 56 de ani după rezecție endoscopică R0 a unui carcinom sigmoid pT1. Boardul trebuie să decidă dacă trebuie discutată o rezecție oncologică suplimentară din cauza factorilor histopatologici de risc înalt. EMT este explicația biologică, dar nu testul clinic primar.","R0 ist nicht alles":"R0 nu este totul","Lokale Exzision ist vollständig.":"Excizia locală este completă.","Okkultes Lymphknotenrisiko bleibt eine andere Frage.":"Riscul ganglionar ocult rămâne o întrebare separată.","Budding ist sichtbar":"Budding-ul este vizibil","Einzelzellen/kleine Cluster an der Invasionsfront.":"Celule izolate/mici grupuri la frontul de invazie.","Morphologie kann funktionelle Tumorbiologie verdichten.":"Morfologia poate condensa biologia tumorală funcțională.","EMT erklärt, entscheidet aber nicht allein":"EMT explică, dar nu decide singur","E-Cadherin/Vimentin/β-Catenin können partielle EMT illustrieren.":"E-cadherin/vimentin/β-catenin pot ilustra EMT parțial.","Standardisierte Histopathologie trägt die klinische Entscheidung.":"Histopatologia standardizată conduce decizia clinică.","Resektionsstatus":"Status de rezecție","R0":"R0","high-grade tumor budding + fokale LVI":"Tumor budding de grad înalt + LVI focală","Differenzierung":"Diferențiere","nicht schlecht differenziert":"Nu este slab diferențiat","Komplettes gut orientiertes endoskopisches Resektat.":"Piesă completă de rezecție endoscopică, bine orientată.","HE-Reevaluation ist der wichtigste 'Test'.":"Reevaluarea HE este cel mai important „test”.","EMT-IHC verbraucht Schnitte ohne zwingenden Zusatznutzen für die Operationsentscheidung.":"IHC EMT consumă secțiuni fără beneficiu suplimentar obligatoriu pentru decizia chirurgicală.","Welche Aussage zu Tumor budding im pT1-CRC ist am treffendsten?":"Care afirmație despre tumor budding în CRC pT1 este cea mai corectă?","Es ist ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen und muss mit anderen Hochrisikofaktoren integriert werden.":"Este un factor histopatologic consacrat de risc pentru metastaze ganglionare și trebuie integrat cu alți factori de risc înalt.","Es ist nur ein interessantes Morphologiedetail.":"Este doar un detaliu morfologic interesant.","Es kann nur durch NGS diagnostiziert werden.":"Poate fi diagnosticat doar prin NGS.","Es ist synonym mit positivem Resektionsrand.":"Este sinonim cu o margine de rezecție pozitivă.","Budding hat klinische Risikobedeutung.":"Budding-ul are relevanță clinică de risc.","Was bedeutet R0 hier?":"Ce înseamnă R0 aici?","Die lokale Resektion ist vollständig; das nodale Metastasierungsrisiko wird dadurch nicht automatisch null.":"Rezecția locală este completă; riscul de metastaze ganglionare nu devine automat zero.","Heilung ist sicher.":"Vindecarea este sigură.","Lymphknotenmetastasen sind ausgeschlossen.":"Metastazele ganglionare sunt excluse.","EMT ist ausgeschlossen.":"EMT este exclus.","Lokaler Randstatus und biologisches Metastasierungsrisiko sind getrennt.":"Statusul marginii locale și riscul biologic de metastazare sunt separate.","Welche Rolle hat das EMT-IHC-Panel?":"Ce rol are panelul IHC EMT?","Es kann partielle EMT mechanistisch illustrieren, ist aber kein eigenständiger validierter Operationsindikator.":"Poate ilustra mecanistic EMT parțial, dar nu este o indicație chirurgicală independentă validată.","Es ist zwingend vor jeder Nachresektion erforderlich.":"Este obligatoriu înainte de fiecare rezecție suplimentară.","Es ersetzt Tumor budding.":"Înlocuiește tumor budding.","Es liefert unmittelbar eine zugelassene Targettherapie.":"Furnizează direct o terapie țintită aprobată.","Mechanismusmarker ≠ klinischer Standard-Risikomarker.":"Marker mecanistic ≠ marker clinic standard de risc.","Welche Befunde tragen die klinische Entscheidung primär?":"Ce rezultate susțin în primul rând decizia clinică?","Budding, LVI, Differenzierung, Invasionstiefe und Resektionsstatus im standardisierten histopathologischen Kontext.":"Budding, LVI, diferențierea, profunzimea invaziei și statusul rezecției în contextul histopatologic standardizat.","Nur E-Cadherin/Vimentin.":"Doar E-cadherin/vimentin.","Breites Pan-Cancer-NGS.":"NGS pan-cancer larg.","PD-L1.":"PD-L1.","Morphologische Risikofaktoren sind hier zentral.":"Factorii morfologici de risc sunt centrali aici.","Leiten Sie vom HE-Befund an der Invasionsfront über die Hallmark-Biologie zur klinischen Konsequenz nach endoskopischer pT1-Resektion ab.":"Derivați consecința clinică după rezecția endoscopică pT1 de la rezultatul HE al frontului de invazie prin biologia hallmark.","R0 als lokalen Resektionsstatus anerkennen.":"Recunoașteți R0 ca status local al rezecției.","High-grade tumor budding erkennen und standardisiert bewerten.":"Recunoașteți și evaluați standardizat tumor budding de grad înalt.","LVI als zusätzlichen Hochrisikofaktor integrieren.":"Integrați LVI ca factor suplimentar de risc înalt.","EMT als mechanistische Erklärung formulieren.":"Formulați EMT ca explicație mecanistică.","EMT-IHC nicht zur Operationsvoraussetzung machen.":"Nu faceți IHC EMT o condiție pentru operație.","Onkologische Nachresektion wegen kombinierter Hochrisikofaktoren im Board diskutieren.":"Discutați rezecția oncologică suplimentară în board din cauza factorilor combinați de risc înalt.","Auf EMT-IHC vollständig verzichten und die Hallmark-Biologie rein morphologisch erklären – klinisch absolut vertretbar.":"Renunțați complet la IHC EMT și explicați biologia hallmark pur morfologic — clinic absolut acceptabil.","Bei Grenzfällen zusätzliche pathologische Zweitbegutachtung statt breitem Molekularpanel.":"În cazurile limită, utilizați o a doua evaluare patologică în locul unui panel molecular larg.","R0 = kein Risiko":"R0 = fără risc","Lymphknotenrisiko ist nicht identisch mit lokalem Randstatus.":"Riscul ganglionar nu este identic cu statusul marginii locale.","EMT-IHC entscheidet":"IHC EMT decide","Mechanistische Marker ersetzen keine validierte pT1-Risikostratifikation.":"Markerii mecanistici nu înlocuiesc stratificarea validată a riscului pT1.","Budding nur Forschung":"Budding doar pentru cercetare","Budding besitzt etablierte prognostische/Risikobedeutung.":"Budding-ul are relevanță prognostică/de risc consacrată.","Der wichtigste Hallmark-Test ist bereits auf dem HE":"Cel mai important test hallmark este deja pe lama HE","Das optionale EMT-Panel zeigt erwartbare partielle EMT-Zeichen, ändert aber die klinische Entscheidung nicht. High-grade budding und LVI waren bereits im HE sichtbar und tragen die Konsequenz.":"Panelul EMT opțional arată semne așteptate de EMT parțial, dar nu modifică decizia clinică. Budding de grad înalt și LVI erau deja vizibile pe HE și determină consecința.","Der Fall verbindet Grundlagenbiologie mit Pathologieroutine, ohne Molekulardiagnostik künstlich aufzublähen.":"Cazul conectează biologia fundamentală cu rutina patologică fără a umfla artificial diagnosticul molecular.","Morphologie → Hallmark → Konsequenz":"Morfologie → hallmark → consecință","R0-pT1-CRC, aber high-grade budding + LVI → relevantes nodales Risiko; EMT mechanistisch, nicht als Pflichtassay.":"CRC pT1 R0, dar budding de grad înalt + LVI → risc ganglionar relevant; EMT mecanistic, nu assay obligatoriu.","Genau die gewünschte Integrationsleistung.":"Exact integrarea dorită.","EMT verstanden, Risiko unscharf":"EMT înțeles, risc neclar","Biologie gut erklärt, aber klinisch relevante Histofaktoren nicht priorisiert.":"Biologia este bine explicată, dar factorii histologici relevanți clinic nu sunt prioritizați.","Zu grundlagenlastig.":"Prea orientat spre biologia fundamentală.","R0 = erledigt":"R0 = gata","Budding/LVI werden trotz freiem Rand ignoriert.":"Budding/LVI sunt ignorate în ciuda marginii libere.","Klinische Konsequenz verpasst.":"Consecința clinică este ratată.","Mehrere histologische Hochrisikofaktoren":"Multipli factori histologici de risc înalt","Onkologische Nachresektion mit Lymphknotenbewertung im interdisziplinären Kontext diskutieren.":"Discutați rezecția oncologică suplimentară cu evaluare ganglionară în context interdisciplinar.","Nodales Risiko wird adressiert.":"Riscul ganglionar este abordat.","Keine Hochrisikofaktoren":"Fără factori de risc înalt","Lokale Strategie nach geltenden Kriterien erwägen.":"Luați în considerare o strategie locală conform criteriilor aplicabile.","Übertherapie vermeiden.":"Evitați supratratarea.","Tumor budding ist ein morphologisches Korrelat von Invasion/plastischen Zellzuständen.":"Tumor budding este un corelat morfologic al invaziei/stărilor celulare plastice.","Bei pT1-CRC ist budding ein klinisch relevanter Risikofaktor für Lymphknotenmetastasen.":"În CRC pT1, budding-ul este un factor de risc clinic relevant pentru metastaze ganglionare.","R0 beantwortet die lokale Resektion, nicht automatisch das nodale Risiko.":"R0 răspunde statusului rezecției locale, nu automat riscului ganglionar.","EMT-IHC kann Mechanismus illustrieren, ist aber kein notwendiger Operationsindikator.":"IHC EMT poate ilustra mecanismul, dar nu este o indicație chirurgicală necesară.","HE kann funktionelle Tumorbiologie als kumulative Morphologie sichtbar machen.":"HE poate face vizibilă biologia tumorală funcțională ca morfologie cumulativă.","Trotz R0-Resektion zeigen high-grade tumor budding und LVI ein relevantes Lymphknotenrisiko. Tumor budding verbindet die Invasionsfront direkt mit Hallmark-Biologie; EMT-IHC ist optional erklärend, nicht entscheidungsdefinierend.":"În ciuda rezecției R0, tumor budding de grad înalt și LVI indică un risc ganglionar relevant. Tumor budding conectează direct frontul de invazie cu biologia hallmark; IHC EMT este opțională și explicativă, nu definitorie pentru decizie.","R0 vs nodales Risiko":"R0 vs risc ganglionar","EMT als Mechanismus":"EMT ca mecanism","Morphologie priorisiert":"Morfologie prioritizată","Welche HE-Merkmale sind funktionelle 'Fingerabdrücke' von Hallmarks?":"Ce caracteristici HE sunt „amprente” funcționale ale hallmarks?","Warum ist partielle EMT biologisch plausibler als ein binärer EMT-Schalter?":"De ce EMT parțial este biologic mai plauzibil decât un comutator EMT binar?","Wo hilft Molekulardiagnostik – und wo macht sie einen guten HE-Befund nur komplizierter?":"Unde ajută diagnosticul molecular — și unde doar complică un rezultat HE bun?","high-grade budding trotz R0":"Budding de grad înalt în ciuda R0","Morphologie kann Hallmarks klinisch relevant abbilden":"Morfologia poate reprezenta hallmarks într-un mod clinic relevant","R0 → Invasionsfront → budding/LVI → Hallmark → klinische Konsequenz":"R0 → front de invazie → budding/LVI → hallmark → consecință clinică","Coverage-Loch im EGFR-Exon 20: „negativ“ ist hier nicht negativ":"Lacună de acoperire în exonul 20 EGFR: aici „negativ” nu înseamnă negativ","Coverage-Loch in therapieentscheid…":"Lacună de acoperire într-un exon decisiv pentru tratament…","58-jährige Nie-Raucherin mit metastasiertem pulmonalem Adenokarzinom. Das DNA-Panel wird als „kein therapierbarer Treiber nachweisbar“ zusammengefasst.":"Femeie de 58 de ani, nefumătoare, cu adenocarcinom pulmonar metastatic. Panelul ADN este rezumat ca „nu s-a detectat niciun driver terapeutic”.","Darf der Fall als molekular negativ abgeschlossen werden, obwohl der Coverage-Report für EGFR-Exon 20 unterhalb des laborintern validierten Mindestkriteriums liegt?":"Poate cazul fi închis ca negativ molecular, deși raportul de acoperire pentru exonul 20 EGFR este sub criteriul minim validat intern de laborator?","Die Erstlinienentscheidung soll in vier Tagen fallen.":"Decizia privind tratamentul de primă linie trebuie luată în patru zile.","ECOG 1, Leber- und Knochenmetastasen; ausreichend Zeit für eine gezielte Nachklärung, aber nicht für beliebig viele Wiederholungen.":"ECOG 1, metastaze hepatice și osoase; există suficient timp pentru o clarificare țintită, dar nu pentru repetări nelimitate.","KRAS, BRAF, MET-Exon-14 und ERBB2 ohne pathogene Alteration; Fusionstestung separat vorgesehen.":"KRAS, BRAF, exonul 14 MET și ERBB2 fără alterări patogene; testarea fuziunilor este planificată separat.","QC-Hinweis":"Notă QC","Median-Coverage des Panels ca. 780×, EGFR-Exon 20 jedoch nur 24×; laborintern validiertes Mindestkriterium für einen negativen Call wird dort nicht erreicht.":"Acoperirea mediană a panelului este de aproximativ 780×, dar exonul 20 EGFR are doar 24×; criteriul minim validat intern de laborator pentru un call negativ nu este îndeplinit în această regiune.","Ein global „guter“ Run wird mit vollständiger lokaler Aussagefähigkeit gleichgesetzt.":"Un run global „bun” este echivalat cu o interpretabilitate locală completă.","Adenokarzinom der Lunge, TTF1/Napsin A positiv.":"Adenocarcinom pulmonar, TTF1/Napsin A pozitiv.","ca. 45 %.":"aprox. 45%.","Ist das Exon tatsächlich wildtyp oder nur unzureichend untersucht?":"Exonul este cu adevărat wild type sau doar insuficient investigat?","Hinweis":"Notă","„Nicht nachgewiesen“ und „nicht ausreichend geprüft“ sind unterschiedliche Aussagen.":"„Nedetectat” și „neevaluat suficient” sunt afirmații diferite.","FFPE-Lebermetastase, Restblock vorhanden.":"Metastază hepatică FFPE, bloc rezidual disponibil.","Menge ausreichend; übrige Targets technisch unauffällig.":"Cantitate suficientă; celelalte ținte sunt tehnic fără particularități.","Coverage":"Acoperire","isolierter Dropout in EGFR-Exon 20.":"dropout izolat în exonul 20 EGFR.","Ressourcen":"Resurse","Eine gezielte orthogonale Abklärung ist schneller und materialsparender als ein blindes komplettes Re-Panel.":"O clarificare ortogonală țintită este mai rapidă și economisește mai mult material decât repetarea oarbă a întregului panel.","Coverage-/QC-Review":"Revizuire coverage/QC","Nicht ausreichend abgedecktes Exon gezielt klären":"Clarificarea țintită a exonului insuficient acoperit","Coverage-Review":"Revizuirea acoperirii","Der Run ist global valide, aber EGFR-Exon 20 unterschreitet das laborintern validierte Mindestkriterium. Für dieses Exon ist ein negativer Befund nicht belastbar.":"Run-ul este global valid, dar exonul 20 EGFR este sub criteriul minim validat intern de laborator. Un rezultat negativ pentru acest exon nu este fiabil.","Orthogonale Abklärung":"Clarificare ortogonală","Eine unabhängig amplifizierte, validierte Zielmethode weist eine EGFR-Exon-20-Insertion nach. Der ursprüngliche „negative“ Panelbefund war an dieser Stelle nicht aussagefähig.":"O metodă țintită validată, cu amplificare independentă, detectează o inserție în exonul 20 EGFR. Rezultatul inițial „negativ” al panelului nu era informativ în această regiune.","NGS-Wiederholung":"Repetare NGS","Die Wiederholung mit demselben Assay zeigt erneut den lokalen Dropout. Ein identisches technisches Design löst den systematischen Coverage-Ausfall nicht zuverlässig.":"Repetarea aceluiași assay arată din nou dropout-ul local. Un design tehnic identic nu rezolvă în mod fiabil eșecul sistematic de acoperire.","Breites Re-Panel":"Re-panel extins","Mehr Panelbreite beantwortet das lokale Coverage-Problem nicht automatisch; entscheidend ist die validierte Abdeckung des fraglichen Exons.":"Un panel mai larg nu rezolvă automat o problemă locală de acoperire; decisivă este acoperirea validată a exonului în cauză.","Global gute Sequenzierqualität; isolierter lokaler Coverage-Ausfall in einem therapieentscheidenden Bereich.":"Calitate global bună a secvențierii; eșec local izolat de acoperire într-o regiune decisivă pentru tratament.","Ein negativer Call ist nur für ausreichend validiert untersuchte Zielregionen zulässig.":"Un call negativ este permis doar pentru regiuni țintă investigate suficient în condiții validate.","Der NGS-Run ist nicht insgesamt ungültig, aber EGFR-Exon 20 ist wegen lokaler Unterabdeckung nicht sicher negativ befundbar. Die Limitation muss explizit berichtet und die Zielregion gezielt nachuntersucht werden. Eine orthogonale Methode weist schließlich eine EGFR-Exon-20-Insertion nach.":"Run-ul NGS nu este invalid per ansamblu, dar exonul 20 EGFR nu poate fi raportat în mod sigur ca negativ din cauza acoperirii locale insuficiente. Limitarea trebuie raportată explicit, iar regiunea țintă retestată specific. O metodă ortogonală detectează în final o inserție în exonul 20 EGFR.","Teilbefund: Das Panel darf nicht pauschal als vollständig negativ zusammengefasst werden, solange die therapieentscheidende Zielregion das validierte Coverage-Kriterium nicht erfüllt.":"Raport parțial: panelul nu trebuie rezumat global ca fiind complet negativ cât timp regiunea țintă decisivă pentru tratament nu îndeplinește criteriul validat de acoperire.","lokale Coverage statt nur Mittelwert prüfen":"verificați acoperirea locală, nu doar media","„nicht nachgewiesen“ von „nicht ausreichend untersucht“ trennen":"separați „nedetectat” de „neevaluat suficient”","gezielte Nachtestung definieren":"definiți retestarea țintită","Falschaussage: hohe Median-Coverage macht jede Zielregion sicher negativ":"Afirmație falsă: acoperirea mediană mare face fiecare regiune țintă sigur negativă","Optimale Lösung: lokalen Coverage-Defekt erkennen, die Aussage im Befund begrenzen und das betroffene Exon mit einer unabhängigen validierten Methode schließen.":"Soluție optimă: recunoașteți defectul local de acoperire, limitați afirmația în raport și clarificați exonul afectat cu o metodă validată independentă.","MTB-LAB":"MTB-LAB","Das Loch im „negativen“ Panel":"Lacuna din panelul „negativ”","Molekularpathologie / NGS-Freigabe / MTB":"Patologie moleculară / eliberare NGS / MTB","Coverage auf Zielregionsebene statt nur als Run-Mittelwert bewerten.":"Evaluați acoperirea la nivelul regiunii țintă, nu doar ca medie a run-ului.","Nicht nachgewiesen von nicht ausreichend untersucht unterscheiden.":"Distingeți nedetectat de neevaluat suficient.","Bei lokalem Coverage-Ausfall Limitation und gezielte Nachtestung formulieren.":"În cazul unui eșec local de acoperire, formulați limitarea și retestarea țintită.","Wiederholung desselben Assays von einer methodisch unabhängigen Bestätigung unterscheiden.":"Distingeți repetarea aceluiași assay de confirmarea metodologic independentă.","Der Bericht sagt „kein therapierbarer Treiber“. Im QC-Tab fällt aber eine einzige rote Zeile auf: EGFR-Exon 20, 24×. Der Rest des Panels liegt bei mehreren hundert Reads. Genau dort darf aus „nichts gesehen“ kein „sicher nicht vorhanden“ werden.":"Raportul spune „niciun driver terapeutic”. Dar în fila QC iese în evidență o singură linie roșie: exonul 20 EGFR, 24×. Restul panelului are câteva sute de reads. Exact aici, din „nu s-a văzut nimic” nu trebuie să rezulte „sigur nu există”.","58-jährige Nie-Raucherin mit metastasiertem Lungenadenokarzinom. Das Panel ist global technisch gut, aber eine therapieentscheidende Zielregion unterschreitet das validierte Mindestkriterium. Das Board muss entscheiden, ob limitiert berichtet, wiederholt oder orthogonal geschlossen wird.":"Femeie de 58 de ani, nefumătoare, cu adenocarcinom pulmonar metastatic. Panelul este tehnic bun per ansamblu, dar o regiune țintă decisivă pentru tratament este sub criteriul minim validat. Board-ul trebuie să decidă dacă emite un raport limitat, repetă testul sau închide lacuna ortogonal.","Global gut, lokal schlecht":"Global bun, local slab","Median-Coverage ca. 780×, EGFR-Exon 20 nur 24×.":"Acoperire mediană aprox. 780×, exonul 20 EGFR doar 24×.","Run-QC ersetzt keine Target-QC.":"QC-ul run-ului nu înlocuiește QC-ul țintei.","Sprache ist Diagnostik":"Limbajul face parte din diagnostic","„Keine Mutation nachweisbar“ behauptet mehr als „Region nicht ausreichend abgedeckt“.":"„Nu s-a detectat nicio mutație” afirmă mai mult decât „regiune insuficient acoperită”.","Befundformulierung muss die analytische Aussagegrenze spiegeln.":"Formularea raportului trebuie să reflecte limitele analitice ale interpretării.","Wiederholung ist nicht automatisch unabhängig":"Repetarea nu este automat independentă","Ein identisches Assaydesign kann denselben Dropout reproduzieren.":"Un design identic al assay-ului poate reproduce același dropout.","Orthogonale Testung kann systematische Assaygrenzen besser adressieren.":"Testarea ortogonală poate aborda mai bine limitările sistematice ale assay-ului.","ca. 45 %":"aprox. 45 %","Panel-QC":"QC panel","global valide":"global valid","Lokale QC":"QC local","EGFR-Exon 20 unter laborintern validierter Mindest-Coverage":"Exonul 20 EGFR sub acoperirea minimă validată de laborator","Restmaterial vorhanden, aber nicht unbegrenzt.":"Material rezidual disponibil, dar nu nelimitat.","Zeitkritische Therapieentscheidung.":"Decizie terapeutică urgentă.","Der lokale Coverage-Grenzwert ist assay- und laborvalidiert; es wird kein universeller Zahlenwert postuliert.":"Pragul local de acoperire este validat pentru assay și laborator; nu se postulează o valoare numerică universală.","Welche Aussage ist bei hoher Median-Coverage, aber unzureichender Coverage eines therapieentscheidenden Exons korrekt?":"Care afirmație este corectă când acoperirea mediană este mare, dar acoperirea unui exon decisiv terapeutic este insuficientă?","Der Run kann global valide sein, während dieses Exon nicht sicher negativ befundbar ist.":"Run-ul poate fi global valid, în timp ce acest exon nu poate fi raportat în mod sigur ca negativ.","Hohe Median-Coverage macht alle Exons sicher negativ.":"O acoperire mediană mare face toate exoanele sigur negative.","Der gesamte Run ist zwingend ungültig.":"Întregul run este în mod obligatoriu invalid.","Coverage ist nur für Forschungsdaten relevant.":"Acoperirea este relevantă doar pentru date de cercetare.","Aussagefähigkeit wird zielregionsbezogen bewertet.":"Interpretabilitatea este evaluată la nivelul regiunii țintă.","Wie sollte die Limitation berichtet werden?":"Cum trebuie raportată limitarea?","Die betroffene Region ausdrücklich als nicht ausreichend beurteilt kennzeichnen und Nachtestung empfehlen.":"Marcați explicit regiunea afectată ca insuficient evaluată și recomandați retestarea.","Gesamtbefund schlicht „negativ“ nennen.":"Numiți pur și simplu rezultatul global „negativ”.","Coverage nur intern dokumentieren.":"Documentați acoperirea doar intern.","Direkt eine Therapie ausschließen.":"Excludeți direct o opțiune terapeutică.","Die klinische Aussage darf die analytische Leistung nicht überschreiten.":"Afirmația clinică nu trebuie să depășească performanța analitică.","Was ist bei einem reproduzierbaren lokalen Assay-Dropout besonders sinnvoll?":"Ce este deosebit de potrivit în cazul unui dropout local reproductibil al assay-ului?","Eine unabhängig validierte Methode für die Zielregion einsetzen.":"Utilizați o metodă validată independent pentru regiunea țintă.","Den identischen Assay beliebig oft wiederholen.":"Repetați assay-ul identic de câte ori doriți.","Nur ein größeres Panel bestellen, ohne die Zielabdeckung zu prüfen.":"Comandați doar un panel mai mare fără a verifica acoperirea țintei.","Keine weitere Abklärung.":"Nicio clarificare suplimentară.","Eine methodisch unabhängige Lösung adressiert systematische Grenzen besser.":"O soluție metodologic independentă abordează mai bine limitările sistematice.","Die orthogonale Methode weist eine EGFR-Exon-20-Insertion nach. Was war der ursprüngliche Fehler?":"Metoda ortogonală detectează o inserție în exonul 20 EGFR. Care a fost eroarea inițială?","Ein nicht ausreichend untersuchter Bereich wurde wie ein sicher negativer Bereich behandelt.":"O regiune insuficient investigată a fost tratată ca fiind sigur negativă.","Der gesamte NGS-Run war zwingend wertlos.":"Întregul run NGS a fost în mod obligatoriu inutil.","Die Histologie war falsch.":"Histologia a fost greșită.","Es wurde eine Keimbahnvariante übersehen.":"A fost omisă o variantă germinală.","Der Fehler lag in der Reichweite der Negativaussage.":"Eroarea a fost în amploarea afirmației negative.","Entscheiden Sie, wie der Panelbefund freigegeben wird und wie die offene Zielregion methodisch geschlossen wird.":"Decideți cum se eliberează rezultatul panelului și cum se clarifică metodologic regiunea țintă rămasă deschisă.","Coverage-Report auf therapieentscheidende Regionen prüfen.":"Revizuiți raportul de acoperire pentru regiunile decisive terapeutic.","Lokale Limitation explizit formulieren.":"Formulați explicit limitarea locală.","Nicht den gesamten Run verwerfen, wenn der Rest valide ist.":"Nu respingeți întregul run dacă restul este valid.","Gezielte orthogonale oder technisch geeignete Wiederholungsstrategie wählen.":"Alegeți o strategie țintită ortogonală sau de repetare adecvată tehnic.","Endbefund nach Nachtestung aktualisieren.":"Actualizați raportul final după retestare.","Wiederholung des Panels kann vertretbar sein, wenn die Ursache plausibel zufällig/librarybezogen ist und das Wiederholungsdesign die Zielregion zuverlässig abdeckt.":"Repetarea panelului poate fi justificată dacă cauza este plauzibil aleatorie/legată de library și designul repetării acoperă fiabil regiunea țintă.","„Panel negativ“ trotz Coverage-Loch":"„Panel negativ” în ciuda unei lacune de acoperire","Überdehnt die analytische Aussage.":"Depășește limitele afirmației analitice.","Run komplett verwerfen":"Respingeți întregul run","Ignoriert, dass die übrigen Regionen valide sein können.":"Ignoră faptul că celelalte regiuni pot fi valide.","Blind identisch wiederholen":"Repetați identic, fără țintă","Kann systematische Dropouts reproduzieren.":"Poate reproduce dropout-uri sistematice.","Die rote Zeile war der eigentliche Befund":"Linia roșie era adevăratul rezultat","Die gezielte unabhängige Nachtestung weist eine EGFR-Exon-20-Insertion nach.":"Retestarea țintită independentă detectează o inserție în exonul 20 EGFR.","Der Fall zeigt, dass analytische Nichtbeurteilbarkeit klinisch relevanter sein kann als ein langer negativer Variantenbericht.":"Cazul arată că neevaluabilitatea analitică poate fi clinic mai relevantă decât un raport lung de variante negative.","Limitiert + gezielt geschlossen":"Limitat + clarificat țintit","Lokale Limitation erkannt, orthogonal nachgetestet, relevante Alteration gefunden.":"Limitare locală recunoscută, retestată ortogonal, alterare relevantă identificată.","Vollständige analytische und klinische Einordnung.":"Interpretare analitică și clinică completă.","Falsch-negativ freigegeben":"Eliberat fals negativ","Coverage-Loch wird ignoriert und die Region als negativ berichtet.":"Lacuna de acoperire este ignorată, iar regiunea este raportată ca negativă.","Kritischer Scope-Fehler.":"Eroare critică de sferă a afirmației.","Ganzer Run verworfen":"Întregul run respins","Valide übrige Ergebnisse werden unnötig wiederholt.":"Alte rezultate valide sunt repetate inutil.","Unnötiger Material-/TAT-Verlust.":"Pierdere inutilă de material/TAT.","Coverage unter validiertem Kriterium":"Acoperire sub criteriul validat","Zielregion als nicht sicher beurteilbar kennzeichnen":"Marcați regiunea țintă ca nefiind evaluabilă în mod sigur","Nachtestung erforderlich, wenn klinisch relevant.":"Retestare necesară dacă este relevant clinic.","Coverage ist lokal.":"Acoperirea este locală.","Negativbefunde brauchen nachgewiesene analytische Aussagefähigkeit.":"Rezultatele negative necesită demonstrată interpretabilitatea analitică.","Limitationen gehören in die klinische Kernaussage, nicht nur in interne QC.":"Limitările trebuie incluse în mesajul clinic central, nu doar în QC-ul intern.","Der Run bleibt für ausreichend abgedeckte Regionen valide. EGFR-Exon 20 ist nicht sicher negativ befundbar und muss explizit limitiert sowie gezielt nachuntersucht werden; eine unabhängige Methode schließt die diagnostische Lücke.":"Run-ul rămâne valid pentru regiunile acoperite suficient. Exonul 20 EGFR nu poate fi raportat sigur ca negativ și trebuie limitat explicit și retestat specific; o metodă independentă închide lacuna diagnostică.","Target-spezifische QC":"QC specific țintei","Befundsprache":"Limbajul raportului","Nachteststrategie":"Strategie de retestare","Wann reicht eine NGS-Wiederholung?":"Când este suficientă repetarea NGS?","Welche Coverage-Metriken müssen im Labor validiert sein?":"Ce metrici de acoperire trebuie validate în laborator?","Wie formuliert man Negativbefunde bei partieller Nichtbeurteilbarkeit?":"Cum se formulează rezultatele negative când o parte a assay-ului nu este evaluabilă?","Twist: relevanter Befund liegt in der QC, nicht in der Variantenliste":"Twist: rezultatul relevant este în QC, nu în lista de variante","Kernfehler: nicht ausreichend untersucht ≠ negativ":"Eroare centrală: insuficient evaluat ≠ negativ","Referenzpfad: Coverage prüfen → limitieren → gezielt schließen":"Calea de referință: verificați acoperirea → formulați limitarea → închideți țintit lacuna","1,4 % EGFR-T790M im FFPE: Resistenzmutation oder Desaminierungsartefakt?":"EGFR T790M 1,4 % în FFPE: mutație de rezistență sau artefact de deaminare?","FFPE-C>T-Artefakt bei niedriger VA…":"Artefact FFPE C>T la VAF mic…","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress unter zielgerichteter Therapie. In einer kleinen FFPE-Rebiopsie wird zusätzlich EGFR p.T790M mit 1,4 % VAF gemeldet.":"Pacient de 67 de ani cu NSCLC mutant EGFR și progresie sub terapie țintită. Într-o mică rebiopsie FFPE se raportează suplimentar EGFR p.T790M la VAF 1,4 %.","Ist die niedrigfrequente C>T-Variante als echte Resistenzsubpopulation belastbar oder zunächst artefaktverdächtig?":"Este varianta C>T cu frecvență joasă fiabilă ca subpopulație reală de rezistență sau trebuie considerată inițial suspectă de artefact?","Therapiewechsel soll kurzfristig festgelegt werden.":"Schimbarea terapiei trebuie decisă rapid.","Primärtreiber":"Driver primar","Bekannte klonale EGFR-aktivierende Mutation mit hoher VAF wird in der Rebiopsie erneut nachgewiesen.":"Mutația clonală activatoare EGFR cunoscută, cu VAF mare, este detectată din nou în rebiopsie.","Neue Variante":"Variantă nouă","EGFR p.T790M, 1,4 % VAF, nur knapp oberhalb der technischen Reporting-Grenze.":"EGFR p.T790M, VAF 1,4 %, doar puțin peste pragul tehnic de raportare.","Kleine Biopsie, lange Formalinfixierung; DNA zeigt deutliche Fragmentierung.":"Biopsie mică, fixare prelungită în formol; ADN-ul prezintă fragmentare marcată.","Actionability des Gens wird mit analytischer Validität des einzelnen Calls verwechselt.":"Actionabilitatea genei este confundată cu validitatea analitică a call-ului individual.","Vitales Adenokarzinom, Tumoranteil ca. 30 %.":"Adenocarcinom viabil, conținut tumoral aprox. 30 %.","Sequenzdaten":"Date de secvențiere","T790M vorwiegend in einem Strang-/Endkontext, niedrige Molekülzahl; mehrere weitere sehr niedrige C>T/G>A-Ereignisse.":"T790M predominant într-un context de strand/capăt, număr redus de molecule; mai multe evenimente C>T/G>A suplimentare la nivel foarte scăzut.","Echte Subklonmutation oder FFPE-bedingte Cytosindesaminierung?":"Mutație subclonală reală sau dezaminare a citozinei indusă de FFPE?","Ein klinisch attraktiver Call verdient nicht weniger, sondern mehr QC.":"Un call atractiv clinic merită mai mult QC, nu mai puțin.","FFPE-Stanzbiopsie, nur wenige Restrollen.":"Biopsie cilindrică FFPE, cu doar câteva secțiuni reziduale disponibile.","stark fragmentiert.":"puternic fragmentat.","Alternative":"Alternativă","zweite Extraktion aus tieferen Schnitten möglich.":"este posibilă o a doua extracție din secțiuni mai profunde.","Orthogonale Bestätigung gezielt möglich.":"Este posibilă confirmarea ortogonală țintită.","FFPE-Artefaktprüfung":"Evaluarea artefactelor FFPE","Niedrigfrequenten klinisch relevanten Call bestätigen":"Confirmarea unui call clinic relevant cu frecvență joasă","Artefaktreview":"Revizuirea artefactelor","Der Call zeigt typische Warnsignale: sehr niedrige VAF, geringe unabhängige Molekülzahl, ungünstiger Strang-/Read-End-Kontext und zusätzliche niedrigfrequente C>T/G>A-Ereignisse im stark fragmentierten FFPE-Material.":"Call-ul prezintă semnale de avertizare tipice: VAF foarte mic, puține molecule independente, context nefavorabil de catenă/capăt de read și evenimente suplimentare C>T/G>A cu frecvență joasă în material FFPE puternic fragmentat.","Orthogonale Bestätigung":"Confirmare ortogonală","In einer unabhängigen Extraktion und orthogonalen Zielmethode ist p.T790M nicht reproduzierbar, während die bekannte klonale EGFR-Mutation stabil nachweisbar bleibt. Gesamtbild spricht für FFPE-Artefakt.":"Într-o extracție independentă și printr-o metodă țintită ortogonală, p.T790M nu este reproductibilă, în timp ce mutația clonală EGFR cunoscută rămâne detectabilă stabil. Per ansamblu, aspectul susține un artefact FFPE.","Mehr Sequenzierbreite ersetzt die gezielte analytische Prüfung des grenzwertigen Calls nicht.":"O acoperire mai largă prin secvențiere nu înlocuiește evaluarea analitică țintită a call-ului la limită.","Stark fragmentierte FFPE-DNA mit erhöhtem Risiko niedrigfrequenter Desaminierungsartefakte.":"ADN FFPE puternic fragmentat, cu risc crescut de artefacte de dezaminare cu frecvență joasă.","Niedrige VAF allein beweist weder Artefakt noch Subklon; Muster, Reproduzierbarkeit und Assay-QC entscheiden.":"Un VAF mic singur nu dovedește nici artefact, nici subclonă; modelul, reproductibilitatea și QC-ul testului sunt decisive.","Die klinisch relevante C>T-Variante liegt in einem stark artefaktanfälligen FFPE-Kontext und ist nicht unabhängig reproduzierbar. Sie darf daher nicht als gesicherte Resistenzmutation berichtet werden; die bekannte klonale EGFR-Alteration bleibt dagegen robust nachweisbar.":"Varianta C>T relevantă clinic apare într-un context FFPE cu risc mare de artefact și nu este reproductibilă independent. Prin urmare, nu trebuie raportată ca mutație de rezistență confirmată; în schimb, alterarea clonală EGFR cunoscută rămâne detectabilă robust.","Teilbefund: Eine niedrigfrequente C>T-Variante in stark geschädigter FFPE-DNA muss vor therapeutischer Interpretation auf Artefaktmuster und Reproduzierbarkeit geprüft werden.":"Rezultat parțial: o variantă C>T cu frecvență joasă în ADN FFPE sever deteriorat trebuie evaluată pentru model de artefact și reproductibilitate înainte de interpretarea terapeutică.","Desaminierungsartefakte als Differenzialdiagnose nennen":"Menționarea artefactelor de dezaminare ca diagnostic diferențial","VAF nicht isoliert interpretieren":"Nu interpretați VAF izolat","klinisch relevanten Low-VAF-Call unabhängig bestätigen":"Confirmarea independentă a unui call clinic relevant cu VAF mic","Falschaussage: therapierbares Gen macht jeden Low-VAF-Call automatisch echt":"Afirmație falsă: o genă actionabilă face automat real orice call cu VAF mic","Optimale Lösung: Low-VAF-C>T-Call im FFPE-Kontext kritisch prüfen, technische Artefaktmerkmale berücksichtigen und vor Therapieableitung unabhängig bestätigen.":"Soluție optimă: evaluarea critică a call-ului C>T cu VAF mic în context FFPE, luarea în considerare a caracteristicilor tehnice de artefact și confirmarea independentă înainte de concluzii terapeutice.","FFPE":"FFPE","Artefakt":"Artefact","Low VAF":"VAF mic","Der attraktive 1,4-%-Call":"Call-ul atractiv de 1,4%","Molekularpathologie / NGS-QC / MTB":"Patologie moleculară / QC NGS / MTB","FFPE-bedingte C>T/G>A-Artefakte als analytische Differenzialdiagnose erkennen.":"Recunoașterea artefactelor C>T/G>A induse de FFPE ca diagnostic diferențial analitic.","VAF, Molekülzahl, Strang-/Read-Kontext und Reproduzierbarkeit gemeinsam bewerten.":"Evaluarea împreună a VAF, numărului de molecule, contextului de catenă/read și reproductibilității.","Klinische Relevanz nicht mit analytischer Validität verwechseln.":"Nu confundați relevanța clinică cu validitatea analitică.","Low-VAF-Calls vor weitreichender Therapieableitung angemessen bestätigen.":"Confirmarea adecvată a call-urilor cu VAF mic înainte de decizii terapeutice cu consecințe majore.","Auf dem Variantenboard leuchtet EGFR p.T790M. VAF 1,4 %. Klinisch wäre der Befund wichtig – analytisch sieht er aber genau so aus, wie ein alter FFPE-Block Probleme machen kann.":"Pe board-ul de variante apare EGFR p.T790M. VAF 1,4%. Clinic, rezultatul ar fi important — analitic însă arată exact ca o problemă pe care o poate produce un bloc FFPE vechi.","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress. In einer kleinen, stark fragmentierten Rebiopsie erscheint ein neuer C>T-Call knapp oberhalb der Reporting-Grenze. Das Board muss entscheiden, ob dies ein echter Resistenzklon ist.":"Pacient de 67 de ani cu NSCLC EGFR-mutant și progresie. Într-o rebiopsie mică, puternic fragmentată, apare un nou call C>T puțin peste pragul de raportare. Board-ul trebuie să decidă dacă este o subclonă reală de rezistență.","Actionability ist kein QC-Kriterium":"Actionabilitatea nu este un criteriu de QC","Ein therapeutisch interessanter Genname macht einen Call nicht analytisch wahr.":"Un nume de genă interesant terapeutic nu face un call adevărat din punct de vedere analitic.","Analytische Validität kommt vor klinischer Interpretation.":"Validitatea analitică precede interpretarea clinică.","FFPE-Muster":"Model FFPE","Mehrere sehr niedrige C>T/G>A-Ereignisse und fragmentierte DNA erhöhen den Artefaktverdacht.":"Mai multe evenimente C>T/G>A la nivel foarte scăzut și ADN-ul fragmentat cresc suspiciunea de artefact.","Muster ist informativer als eine einzelne VAF.":"Modelul este mai informativ decât un singur VAF.","Unabhängige Reproduzierbarkeit":"Reproductibilitate independentă","Eine zweite Extraktion/orthogonale Methode kann einen grenzwertigen Call stabilisieren oder entkräften.":"O a doua extracție/metodă ortogonală poate susține sau infirma un call la limită.","Bestätigung sollte möglichst methodisch unabhängig sein.":"Confirmarea trebuie să fie, pe cât posibil, independentă metodologic.","Bekannter Treiber":"Driver cunoscut","klonale EGFR-aktivierende Mutation robust nachweisbar":"mutația clonală activatoare EGFR este detectabilă robust","Neuer Call":"Call nou","EGFR p.T790M, 1,4 % VAF":"EGFR p.T790M, VAF 1,4%","FFPE-QC":"QC FFPE","stark fragmentiert; weitere sehr niedrige C>T/G>A-Ereignisse":"puternic fragmentat; evenimente suplimentare C>T/G>A la nivel foarte scăzut","Wenig Restmaterial.":"Puțin material rezidual.","Der Fall postuliert keine universelle VAF-Grenze; entscheidend ist die laborvalidierte Performance im konkreten Assay.":"Cazul nu presupune un prag VAF universal; decisivă este performanța validată în laborator a testului concret.","Was ist der erste richtige Schritt bei einem klinisch relevanten 1,4-%-C>T-Call in stark geschädigtem FFPE?":"Care este primul pas corect pentru un call C>T relevant clinic de 1,4% în material FFPE sever deteriorat?","Call-level QC und FFPE-Artefaktmuster prüfen.":"Revizuirea QC la nivel de call și a modelului de artefact FFPE.","Sofort Therapie ableiten.":"Derivarea imediată a tratamentului.","Jede Variante unter 5 % grundsätzlich verwerfen.":"Respingerea de principiu a oricărei variante sub 5%.","Keimbahntestung veranlassen.":"Inițierea testării germinale.","Es gibt keine universelle VAF-Regel; der Call muss assay- und kontextbezogen validiert werden.":"Nu există o regulă universală pentru VAF; call-ul trebuie validat în funcție de test și context.","Welche Befunde erhöhen hier den Artefaktverdacht?":"Ce constatări cresc aici suspiciunea de artefact?","sehr niedrige VAF/geringe Molekülzahl":"VAF foarte mic/puține molecule","mehrere niedrigfrequente C>T/G>A-Ereignisse":"mai multe evenimente C>T/G>A cu frecvență joasă","stark fragmentierte FFPE-DNA":"ADN FFPE puternic fragmentat","bekannte klonale Treibermutation ist robust":"mutația driver clonală cunoscută este robustă","Die Kombination aus FFPE-Schaden und typischem Substitutionsmuster ist verdächtig.":"Combinația dintre deteriorarea FFPE și modelul tipic de substituții este suspectă.","Was erhöht die Sicherheit vor therapeutischer Interpretation am stärksten?":"Ce crește cel mai mult siguranța înainte de interpretarea terapeutică?","Unabhängige Extraktion und/oder orthogonale validierte Zielmethode.":"Extracție independentă și/sau metodă țintită ortogonală validată.","Längere Literaturrecherche ohne analytische Prüfung.":"O căutare mai lungă în literatură fără evaluare analitică.","Den gleichen Report erneut öffnen.":"Redeschiderea aceluiași raport.","Nur die Therapierbarkeit des Gens bewerten.":"Evaluarea exclusivă a posibilității de țintire terapeutică a genei.","Reproduzierbarkeit adressiert die analytische Kernfrage.":"Reproductibilitatea răspunde întrebării analitice centrale.","T790M ist unabhängig nicht reproduzierbar, der bekannte klonale EGFR-Treiber schon. Wie ist das Gesamtbild?":"T790M nu este reproductibil independent, dar driver-ul clonal EGFR cunoscut este. Cum se interpretează tabloul general?","Der neue Low-VAF-Call ist nicht gesichert und im Kontext am ehesten artefaktbedingt.":"Noul call cu VAF mic nu este confirmat și, în context, este cel mai probabil legat de un artefact.","T790M ist trotzdem sicher echt.":"T790M este totuși cu siguranță reală.","Auch der bekannte EGFR-Treiber ist damit falsch.":"Prin urmare, și driver-ul EGFR cunoscut trebuie să fie fals.","Der Unterschied ist ohne Bedeutung.":"Diferența nu are importanță.","Selektive Nichtreproduzierbarkeit plus Artefaktmuster entkräftet den grenzwertigen Call.":"Nereproductibilitatea selectivă împreună cu modelul de artefact slăbesc puternic call-ul la limită.","Bewerten Sie, ob der Low-VAF-Call als gesichert berichtet und therapeutisch verwendet werden darf.":"Evaluați dacă call-ul cu VAF mic poate fi raportat ca fiind confirmat și utilizat terapeutic.","FFPE-Qualität und Substitutionsmuster prüfen.":"Evaluarea calității FFPE și a modelului de substituții.","Call-level Evidenz bewerten.":"Evaluarea dovezilor la nivel de call.","Low-VAF nicht pauschal verwerfen, aber bei hoher Konsequenz bestätigen.":"Nu respingeți categoric un VAF mic, dar confirmați-l când consecința clinică este majoră.","Unabhängige Reproduzierbarkeit einbeziehen.":"Integrarea reproductibilității independente în evaluare.","Nur robuste Befunde in die Therapiekernaussage aufnehmen.":"Includeți în mesajul terapeutic central doar rezultate robuste.","Bei sehr gut validiertem ultrasensitivem Assay und überzeugender unabhängiger Molekülevidenz kann ein niedriger VAF real sein; der Fall lehrt keine starre Prozentgrenze.":"Cu un test ultrasensibil bine validat și dovezi moleculare independente convingătoare, un VAF mic poate fi real; cazul nu predă un prag procentual rigid.","<5 % = immer Artefakt":"<5% = întotdeauna artefact","Ignoriert echte Subklone und assayspezifische Nachweisgrenzen.":"Ignoră subclone reale și limitele de detecție specifice testului.","Actionable = echt":"Actionabil = real","Verwechselt klinische mit analytischer Evidenz.":"Confundă dovezile clinice cu cele analitice.","Breites Re-Panel statt Call-QC":"Repetarea unui panel larg în loc de QC la nivel de call","Mehr Daten lösen den konkreten Artefaktverdacht nicht automatisch.":"Mai multe date nu rezolvă automat suspiciunea concretă de artefact.","Die Resistenzmutation verschwindet":"Mutația de rezistență dispare","In unabhängiger Extraktion und orthogonaler Zielmethode ist T790M nicht reproduzierbar, der klonale Primärtreiber jedoch stabil.":"Într-o extracție independentă și printr-o metodă țintită ortogonală, T790M nu este reproductibilă, în timp ce driver-ul clonal primar rămâne stabil.","Der attraktivste Befund des Reports ist nicht der belastbarste.":"Cel mai atractiv rezultat din raport nu este cel mai robust.","Low-VAF korrekt entkräftet":"Varianta cu VAF scăzut a fost corect infirmată","Artefaktmuster erkannt und Call unabhängig nicht bestätigt.":"A fost recunoscut un tipar de artefact, iar varianta nu a fost confirmată independent.","Therapeutisches Overcalling vermieden.":"A fost evitată supra-interpretarea terapeutică.","Direkt als Resistenzmutation berichtet":"Raportată direct ca mutație de rezistență","Ein grenzwertiger FFPE-Call steuert die Therapie.":"O variantă FFPE la limită ajunge să determine decizia terapeutică.","Analytische Evidenz unzureichend.":"Dovezile analitice sunt insuficiente.","Pauschal unter 5 % verworfen":"Respinsă automat sub 5 %","Der richtige Ausgang wird aus der falschen Regel abgeleitet.":"Se ajunge la rezultatul corect prin aplicarea unei reguli greșite.","Keine universelle VAF-Grenze verwenden.":"Nu utilizați un prag VAF universal.","klinisch relevanter Low-VAF-Call + Artefaktmuster":"variantă cu VAF scăzut relevantă clinic + tipar de artefact","analytische Bestätigung vor finaler Therapieaussage":"confirmare analitică înaintea concluziei terapeutice finale","Bei Nichtbestätigung nicht als gesicherte Resistenzmutation berichten.":"Dacă nu este confirmată, nu o raportați ca mutație de rezistență certă.","FFPE-Artefakte sind call- und kontextabhängig.":"Artefactele FFPE depind de variantă și de context.","Niedrige VAF ist ein Warnsignal, kein Urteil.":"Un VAF scăzut este un semnal de avertizare, nu un verdict.","Je größer die klinische Konsequenz, desto wichtiger die analytische Absicherung.":"Cu cât consecința clinică este mai mare, cu atât confirmarea analitică este mai importantă.","Der T790M-Call ist aufgrund des FFPE-Musters und fehlender unabhängiger Reproduzierbarkeit nicht gesichert; keine Therapieentscheidung allein darauf stützen.":"Varianta T790M nu este confirmată din cauza tiparului de artefact FFPE și a lipsei de reproductibilitate independentă; nu bazați o decizie terapeutică doar pe acest rezultat.","Low-VAF-Interpretation":"Interpretarea VAF scăzut","Bestätigung":"Confirmare","Welche Artefaktmuster sind plattformabhängig?":"Ce tipare de artefact depind de platformă?","Wann ist eine zweite Extraktion sinnvoll?":"Când este utilă o a doua extracție?","Wie dokumentiert man nicht bestätigte Calls?":"Cum se documentează variantele neconfirmate?","Twist: klinisch attraktivster Call ist analytisch schwächster":"Twist: varianta cea mai atractivă clinic este cea mai slabă analitic","Keine starre VAF-Grenze":"Fără prag VAF rigid","Referenzpfad: Call-QC → Artefaktmuster → unabhängige Bestätigung":"Cale de referință: QC al variantei → tipar de artefact → confirmare independentă","Tumor-only BRCA2 bei 48 % VAF: therapeutisch relevant, Keimbahn trotzdem offen":"BRCA2 tumor-only la VAF 48%: relevant terapeutic, statutul germinal rămâne neclar","Tumor-only NGS: Keimbahnverdacht B…":"NGS tumor-only: suspiciune de variantă germinală B…","61-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom. Tumor-only NGS zeigt eine pathogene truncierende BRCA2-Variante mit 48 % VAF.":"Pacient de 61 de ani cu cancer de prostată metastatic rezistent la castrare. NGS tumor-only evidențiază o variantă patogenă truncantă BRCA2 cu VAF de 48%.","Darf aus VAF und Gen direkt auf eine Keimbahnmutation geschlossen werden – und wie werden therapeutische und hereditäre Konsequenzen getrennt?":"Se poate concluziona direct din VAF și genă că este o mutație germinală — și cum se separă consecințele terapeutice de cele ereditare?","Systemische Therapieentscheidung und genetische Beratung sollen parallel geplant werden.":"Planificarea tratamentului sistemic și consilierea genetică trebuie realizate în paralel.","Schwester mit Mammakarzinom mit 46 Jahren, Vater mit Prostatakarzinom mit 58 Jahren.":"Soră cu cancer mamar la 46 de ani, tată cu cancer de prostată la 58 de ani.","Tumorprofil":"Profil tumoral","Pathogene BRCA2-Trunkierung; Tumorreinheit und Kopienzahl machen eine Herkunft aus der VAF allein nicht eindeutig.":"Trunchiere patogenă BRCA2; puritatea tumorală și numărul de copii fac imposibilă stabilirea originii variantei doar pe baza VAF.","„ungefähr 50 %“ wird mit „Keimbahn bewiesen“ gleichgesetzt.":"„Aproximativ 50%” este echivalat cu „germinal dovedit”.","Tumorbiomarker und hereditäre Diagnostik sauber entkoppeln und dann wieder integrieren.":"Separarea clară a biomarkerului tumoral de diagnosticul ereditar, urmată de reintegrarea celor două niveluri.","Metastasiertes Prostataadenokarzinom.":"Adenocarcinom de prostată metastatic.","BRCA2 pathogene Loss-of-function-Variante, VAF 48 %.":"Variantă patogenă BRCA2 loss-of-function, VAF 48%.","somatisch, Keimbahn oder beides im Tumorkontext?":"somatică, germinală sau ambele în context tumoral?","Tumorreinheit, LOH und Copy-number können VAF deutlich verschieben.":"Puritatea tumorală, LOH și numărul de copii pot modifica semnificativ VAF.","FFPE-Metastase für Tumorprofil; EDTA-Blut für bestätigende Keimbahndiagnostik verfügbar.":"Metastază FFPE pentru profilare tumorală; sânge EDTA disponibil pentru confirmarea germinală.","ca. 60 %.":"aprox. 60%.","Consent":"Consimțământ","Genetische Beratung/Einwilligung für Keimbahndiagnostik erforderlich.":"Pentru testarea germinală sunt necesare consiliere genetică și consimțământ.","Tumor-normal bzw. gezielte Keimbahnbestätigung möglich.":"Este posibilă analiza tumor-normal sau confirmarea germinală țintită.","Tumor-BRCA/HRR einordnen":"Interpretarea BRCA/HRR tumoral","Potenzielle Keimbahn separat klären":"Clarificarea separată a posibilei origini germinale","Pathogene BRCA2-Loss-of-function-Variante im Tumor; für die tumorbezogene Therapieentscheidung relevant, ohne damit die Keimbahnherkunft zu beweisen.":"Variantă patogenă BRCA2 loss-of-function în tumoră; relevantă pentru terapia tumorală, fără a demonstra o origine germinală.","Die pathogene BRCA2-Variante wird im konstitutionellen Material bestätigt: Keimbahnmutation. Der Tumor-only-Befund war ein Hinweis, nicht der Beweis.":"Varianta patogenă BRCA2 este confirmată în material constituțional: mutație germinală. Rezultatul tumor-only a fost un indiciu, nu o dovadă.","Humangenetische Beratung":"Consiliere genetică","Genetische Beratung wird veranlasst; hereditäre Konsequenzen werden außerhalb des reinen Tumorbefunds adressiert.":"Se organizează consiliere genetică; implicațiile ereditare sunt abordate separat de raportul tumor-only.","Tumor-only":"Tumor-only","Ohne Normalprobe kann die Herkunft einer Variante nicht allein aus der VAF sicher bestimmt werden.":"Fără o probă normală, originea unei variante nu poate fi stabilită în siguranță doar din VAF.","Therapeutische Tumorrelevanz und hereditäre Bedeutung sind getrennte Fragestellungen.":"Relevanța terapeutică tumorală și semnificația ereditară sunt întrebări distincte.","Die pathogene BRCA2-Variante ist im Tumor therapeutisch relevant, aber Tumor-only Sequenzierung beweist keine Keimbahnherkunft. VAF um 50 % erhöht den Verdacht, ist wegen Tumorreinheit, LOH und Copy-number jedoch nicht beweisend. Die bestätigende Analyse im konstitutionellen Material zeigt hier tatsächlich eine Keimbahnmutation.":"Varianta patogenă BRCA2 este relevantă terapeutic în tumoră, dar secvențierea tumor-only nu demonstrează originea germinală. Un VAF în jur de 50% crește suspiciunea, însă nu este concludent din cauza purității tumorale, LOH și numărului de copii. Analiza de confirmare în material constituțional demonstrează în acest caz o mutație germinală.","Teilbefund: Ein Tumor-only BRCA2-Befund kann therapeutisch relevant sein und gleichzeitig eine separate Keimbahnabklärung auslösen; die VAF allein entscheidet die Herkunft nicht.":"Rezultat parțial: un rezultat BRCA2 tumor-only poate fi relevant terapeutic și, în același timp, poate declanșa o evaluare germinală separată; VAF singur nu stabilește originea.","Tumoractionability separat bewerten":"Evaluarea separată a actionabilității tumorale","Keimbahnverdacht separat adressieren":"Abordați separat suspiciunea de origine germinală","VAF nicht als Herkunftsbeweis verwenden":"Nu utilizați VAF ca dovadă a originii","Falschaussage: 48–50 % VAF im Tumor beweist Keimbahn":"Afirmație falsă: VAF 48–50% într-o tumoră dovedește originea germinală","Optimale Lösung: Tumorbefund therapeutisch einordnen, Keimbahnverdacht transparent markieren und mit konstitutionellem Material/genetischer Beratung bestätigen.":"Soluție optimă: interpretați terapeutic rezultatul tumoral, marcați transparent suspiciunea de origine germinală și confirmați-o prin material constituțional/consiliere genetică.","48 % sind kein Abstammungsnachweis":"48% nu este dovada originii germinale","Molekulares Tumorboard / Humangenetik-Schnittstelle":"Interfață Tumor Board molecular / Genetică medicală","Tumor-only NGS nicht mit Keimbahndiagnostik gleichsetzen.":"Nu echivalați NGS tumor-only cu diagnosticul germinal.","VAF nur als Hinweis und nie isoliert als Herkunftsbeweis nutzen.":"Utilizați VAF doar ca indiciu și niciodată izolat ca dovadă a originii.","Tumorbezogene Therapieinformation und hereditäre Konsequenzen getrennt bearbeiten.":"Gestionați separat informația terapeutică tumorală și implicațiile ereditare.","Bestätigende Keimbahndiagnostik mit geeigneter Beratung/Einwilligung veranlassen.":"Inițiați testarea germinală de confirmare cu consiliere/consimțământ adecvat.","BRCA2, pathogene Trunkierung, VAF 48 %. Der Report sieht „keimbahnverdächtig“ aus – aber 48 % im Tumor sind keine Blutprobe. Genau hier muss das Board zwei richtige Aussagen gleichzeitig halten.":"BRCA2, variantă truncantă patogenă, VAF 48%. Raportul pare „sugestiv pentru germinal” — dar 48% într-o tumoră nu este o probă de sânge. Exact aici board-ul trebuie să mențină simultan două afirmații corecte.","61-jähriger Patient mit mCRPC und pathogener BRCA2-Variante im Tumor-only Panel. Der Befund kann therapeutisch relevant sein. Wegen VAF und Familienanamnese besteht zusätzlich Keimbahnverdacht, der separat bestätigt werden muss.":"Pacient de 61 de ani cu mCRPC și variantă patogenă BRCA2 într-un panel tumor-only. Rezultatul poate fi relevant terapeutic. VAF și istoricul familial ridică suplimentar suspiciunea de origine germinală, care trebuie confirmată separat.","VAF ist modellabhängig":"VAF depinde de model/context","Tumorreinheit, LOH, Amplifikation/Deletion und Klonalität verschieben die beobachtete VAF.":"Puritatea tumorală, LOH, amplificarea/deleția și clonalitatea pot modifica VAF observat.","50 % ist kein magischer Keimbahn-Cutoff.":"50% nu este un prag magic pentru originea germinală.","Zwei Konsequenzachsen":"Două axe de consecințe","Tumortherapie kann auf dem somatischen Befund beruhen; Familien-/Prädispositionsfragen brauchen Keimbahndiagnostik.":"Terapia tumorală se poate baza pe rezultatul somatic; întrebările privind familia/predispoziția necesită testare germinală.","Dasselbe Gen erzeugt zwei unterschiedliche Workflows.":"Aceeași genă generează două fluxuri de lucru diferite.","Tumor-only hat Grenzen":"Tumor-only are limitări","Ohne Normalprobe bleibt die Herkunft vieler Varianten unbestimmt.":"Fără o probă normală, originea multor variante rămâne neclară.","Bericht und Beratung müssen das transparent machen.":"Raportul și consilierea trebuie să facă acest lucru transparent.","pathogene BRCA2-LoF, VAF 48 %":"BRCA2 LoF patogen, VAF 48%","frühes Mammakarzinom bei Schwester, Prostatakarzinom beim Vater":"cancer mamar precoce la soră, cancer de prostată la tată","Normalprobe":"Probă normală","noch nicht untersucht":"nu a fost încă testată","Konstitutionelles Material verfügbar.":"Este disponibil material constituțional.","Hereditäre Diagnostik erfordert eigenen Prozess/Einwilligung.":"Diagnosticul ereditar necesită un proces/consimțământ separat.","Tumor-VAF wird im Kontext von Reinheit und Copy-number interpretiert.":"VAF tumoral este interpretat în contextul purității și al numărului de copii.","Was beweist eine pathogene BRCA2-Variante mit 48 % VAF im Tumor-only Panel?":"Ce dovedește o variantă patogenă BRCA2 cu VAF 48% într-un panel tumor-only?","Sie ist keimbahnverdächtig, beweist aber ohne konstitutionelle Probe keine Keimbahnherkunft.":"Ridică suspiciunea unei origini germinale, dar nu o dovedește fără material constituțional.","Keimbahn ist sicher bewiesen.":"Originea germinală este dovedită cu certitudine.","Somatisch ist sicher bewiesen.":"Originea somatică este dovedită cu certitudine.","Die Variante ist ein Artefakt.":"Varianta este un artefact.","Tumorreinheit und Copy-number verhindern einfache VAF-Herkunftsregeln.":"Puritatea tumorală și numărul de copii împiedică reguli simple de origine bazate pe VAF.","Welche zwei Fragen müssen getrennt beantwortet werden?":"Care două întrebări trebuie răspunse separat?","Welche tumorbezogene therapeutische Bedeutung hat BRCA2?":"Ce semnificație terapeutică tumorală are BRCA2?","Liegt eine konstitutionelle pathogene Variante vor?":"Există o variantă patogenă constituțională?","Welche Farbe hat der Report?":"Ce culoare are raportul?","Reicht das Alter allein als Keimbahntest?":"Este vârsta singură suficientă pentru testare germinală?","Therapie und Prädisposition sind gekoppelt, aber nicht identisch.":"Tratamentul și predispoziția sunt legate, dar nu identice.","Wie wird die Keimbahnfrage belastbar geklärt?":"Cum poate fi clarificată în mod fiabil întrebarea germinală?","Analyse geeigneten konstitutionellen Materials im passenden genetischen Prozess.":"Analizați material constituțional adecvat în cadrul procesului genetic corespunzător.","Nur VAF erneut ansehen.":"Doar reanalizați VAF.","Nur denselben Tumor erneut sequenzieren.":"Doar secvențiați din nou aceeași tumoră.","Gar nicht; Tumor-only reicht.":"Nu faceți nimic; tumor-only este suficient.","Die Herkunft braucht konstitutionellen Vergleich/Bestätigung.":"Originea necesită comparație/confirmare constituțională.","Die Variante wird im Blut bestätigt. Was ändert sich?":"Varianta este confirmată în sânge. Ce se schimbă?","Zusätzlich zur Tumorrelevanz ist nun eine Keimbahnmutation bestätigt und hereditäre Konsequenzen können adressiert werden.":"Pe lângă relevanța tumorală, este acum confirmată o mutație germinală și pot fi abordate implicațiile ereditare.","Die Tumorrelevanz verschwindet.":"Relevanța tumorală dispare.","Der Tumorbefund war falsch.":"Rezultatul tumoral a fost greșit.","Es gibt keinerlei zusätzliche Konsequenz.":"Nu există nicio consecință suplimentară.","Die bestätigte Herkunft ergänzt den Tumorbefund um eine zweite klinische Dimension.":"Originea confirmată adaugă o a doua dimensiune clinică rezultatului tumoral.","Formulieren Sie Tumor- und Keimbahnaussage getrennt und definieren Sie den nächsten diagnostischen Schritt.":"Formulați separat afirmația tumorală și cea germinală și definiți următorul pas diagnostic.","Pathogene BRCA2-Variante im Tumor als tumorbezogenen Biomarker einordnen.":"Interpretați varianta patogenă BRCA2 din tumoră ca biomarker tumoral.","VAF und Familienanamnese als Keimbahnverdacht, nicht Beweis, kommunizieren.":"Comunicați VAF și istoricul familial ca elemente de suspiciune germinală, nu ca dovadă.","Konstitutionelle Testung/genetische Beratung veranlassen.":"Inițiați testare constituțională/consiliere genetică.","Nach Bestätigung hereditäre Ebene getrennt dokumentieren.":"După confirmare, documentați separat nivelul ereditar.","Je nach lokaler Struktur kann eine direkte Überweisung zur Humangenetik statt tumor-normal Analyse im selben Labor sinnvoll sein.":"În funcție de structura locală, poate fi adecvată trimiterea directă la genetică în locul unei analize tumor-normal în același laborator.","48 % = Keimbahn":"48% = germinal","VAF im Tumor hängt von Reinheit, LOH und Copy-number ab.":"VAF tumoral depinde de puritate, LOH și numărul de copii.","Nur Therapie, Keimbahn ignorieren":"Doar terapie, ignorați germinalul","Verpasst potenziell relevante Prädispositionsinformation.":"Ratează informații potențial relevante privind predispoziția.","Nur Keimbahn diskutieren":"Discutați doar germinalul","Ignoriert die unmittelbare tumorbezogene Bedeutung.":"Ignoră relevanța tumorală imediată.","Der Verdacht bestätigt sich – aber erst im richtigen Material":"Suspiciunea se confirmă — dar numai în materialul potrivit","Die BRCA2-Variante wird im konstitutionellen Material bestätigt.":"Varianta BRCA2 este confirmată în material constituțional.","Der Fall zeigt den Unterschied zwischen einem starken Hinweis aus Tumor-only NGS und einem echten Keimbahnnachweis.":"Cazul demonstrează diferența dintre un indiciu puternic din NGS tumor-only și confirmarea reală germinală.","Tumorrelevanz genutzt, Keimbahn separat bestätigt.":"Relevanța tumorală utilizată, statutul germinal confirmat separat.","Vollständige Präzisionsonkologie plus Prädispositionslogik.":"Oncologie de precizie completă plus logică de predispoziție.","Keimbahn aus 48 % behauptet":"Origine germinală afirmată pe baza a 48%","Herkunft ohne Normalprobe overcallt.":"Originea este suprainterpretată fără probă normală.","Methodisch unzulässig.":"Nevalid metodologic.","Keimbahnverdacht ignoriert":"Suspiciunea germinală ignorată","Hereditäre Ebene bleibt ungeklärt.":"Dimensiunea ereditară rămâne neclarificată.","Unvollständige Nachsorge.":"Urmărire incompletă.","pathogene Variante in Prädispositionsgen im Tumor-only Kontext":"variantă patogenă într-o genă de predispoziție în context tumor-only","Keimbahnpotenzial bewerten und ggf. Bestätigung/Genetik veranlassen":"evaluați potențialul germinal și inițiați confirmare/genetică atunci când este indicat","Tumorbefund nicht als konstitutionellen Befund etikettieren.":"Nu etichetați rezultatul tumoral drept rezultat constituțional.","Tumor-only ist keine Keimbahndiagnostik.":"Tumor-only nu este diagnostic germinal.","VAF ist ein Hinweis, kein Beweis.":"VAF este un indiciu, nu o dovadă.","Dasselbe Variantenergebnis kann therapeutische und hereditäre Konsequenzen parallel haben.":"Același rezultat de variantă poate avea în paralel consecințe terapeutice și ereditare.","Pathogene BRCA2-Variante im Tumor therapeutisch relevant; Keimbahnherkunft aus Tumor-only/VAF nicht beweisbar. Bestätigende konstitutionelle Diagnostik ist indiziert und zeigt hier eine Keimbahnmutation.":"Varianta patogenă BRCA2 din tumoră este relevantă terapeutic; originea germinală nu poate fi dovedită din tumor-only/VAF. Este indicată testarea constituțională de confirmare, care în acest caz demonstrează o mutație germinală.","Tumor-only-Grenzen":"Limitările tumor-only","VAF-Interpretation":"Interpretarea VAF","Keimbahnworkflow":"Flux de lucru germinal","Welche Gene lösen besonders häufig Keimbahn-Reflexfragen aus?":"Ce gene ridică cel mai frecvent întrebări reflex privind originea germinală?","Wie beeinflusst LOH die Tumor-VAF?":"Cum influențează LOH VAF tumoral?","Wie formuliert man Keimbahnverdacht im Tumorbericht?":"Cum se formulează suspiciunea de origine germinală într-un raport tumoral?","Twist: 48 % ist Hinweis, kein Beweis":"Twist: 48% este un indiciu, nu o dovadă","Tumor- und Keimbahnkonsequenz getrennt":"Separarea consecințelor tumorale și germinale","Referenzpfad: Tumoractionability → Keimbahnverdacht → konstitutionelle Bestätigung":"Cale de referință: actionabilitate tumorală → suspiciune germinală → confirmare constituțională","ALK-IHC positiv, DNA-NGS negativ: die Fusion steckt im Transkript":"IHC ALK pozitiv, NGS ADN negativ: fuziunea se află în transcript","DNA-NGS negativ, aber Fusionsverda…":"NGS ADN negativ, dar suspiciunea de fuziune persistă…","Sarkomzentrum / Molekulares Tumorboard":"Centru de sarcoame / Tumor Board molecular","34-jährige Patientin mit nicht vollständig resezierbarem inflammatorischem myofibroblastärem Tumor (IMT) im kleinen Becken. ALK-IHC diffus stark positiv, DNA-basiertes Panel meldet keine ALK-Fusion.":"Pacientă de 34 de ani cu tumoră miofibroblastică inflamatorie (IMT) pelvină, incomplet rezecabilă. IHC ALK este difuz intens pozitivă; un panel bazat pe ADN nu raportează nicio fuziune ALK.","Ist die Fusionshypothese damit erledigt oder muss RNA-basiert/orthogonal weiter untersucht werden?":"Înseamnă aceasta că ipoteza de fuziune este exclusă sau trebuie continuată testarea bazată pe ARN/ortogonală?","Die systemische Behandlungsstrategie soll im Sarkomboard festgelegt werden.":"Strategia de tratament sistemic urmează să fie stabilită în board-ul de sarcoame.","Spindelzelliger myofibroblastärer Tumor mit entzündlichem Hintergrund, passend zu IMT.":"Tumoră miofibroblastică fusocelulară cu fond inflamator, compatibilă cu IMT.","ALK diffus zytoplasmatisch stark positiv.":"ALK difuz intens pozitiv citoplasmatic.","DNA-Panel":"Panel ADN","Keine Fusion detektiert; Report weist darauf hin, dass nicht alle intronischen Breakpointregionen vollständig erfasst werden.":"Nu a fost detectată nicio fuziune; raportul menționează că nu toate regiunile intronice de breakpoint sunt acoperite complet.","„Gen im Panel enthalten“ wird mit „jede mögliche Fusion erfasst“ gleichgesetzt.":"„Gena este inclusă în panel” este echivalat cu „toate fuziunile posibile sunt acoperite”.","IMT-morphologischer Kontext.":"Context morfologic de IMT.","ALK-IHC":"IHC ALK","stark positiv.":"intens pozitiv.","kein Fusionscall.":"fără call de fuziune.","Ist ein exprimiertes ALK-Fusionstranskript nachweisbar?":"Este detectabil un transcript de fuziune ALK exprimat?","FFPE-Resektat, RNA-QC ausreichend.":"Piesă de rezecție FFPE, QC ARN adecvat.","DNA-Limitation":"Limitare ADN","Breakpoint kann außerhalb der erfassten intronischen Regionen liegen.":"Breakpoint-ul poate fi în afara regiunilor intronice capturate.","Gezieltes RNA-Fusionspanel und FISH verfügbar.":"Sunt disponibile un panel țintit de fuziuni ARN și FISH.","Fusionsverdacht mit geeigneter Methode klären":"Clarificați suspiciunea de fuziune printr-o metodă adecvată","RNA-basiertes Fusionspanel weist ein exprimiertes TPM3::ALK-Fusionstranskript nach.":"Panelul de fuziuni bazat pe ARN detectează un transcript de fuziune TPM3::ALK exprimat.","ALK-Break-apart-FISH ist positiv und stützt das Rearrangement, ohne den Fusionspartner auf Sequenzebene zu definieren.":"FISH break-apart ALK este pozitiv și susține rearanjarea, fără a defini partenerul de fuziune la nivel de secvență.","Breites DNA-Panel":"Panel ADN larg","Mehr DNA-Panelbreite garantiert keine vollständige Erfassung aller Fusionsbreakpoints; die relevante methodische Lücke bleibt.":"Un panel ADN mai larg nu garantează acoperirea completă a tuturor breakpoint-urilor de fuziune; lacuna metodologică relevantă rămâne.","Prätestwahrscheinlichkeit":"Probabilitate pretest","Morphologie plus starke ALK-IHC machen einen Fusionsmechanismus plausibel.":"Morfologia plus IHC ALK intens pozitivă fac plauzibil un mecanism de fuziune.","Ein negatives DNA-Fusionsergebnis ist nur so vollständig wie das Assaydesign der relevanten intronischen Regionen.":"Un rezultat negativ pentru fuziune în ADN este doar atât de complet cât permite designul testului pentru regiunile intronice relevante.","Der negative DNA-Fusionscall schließt in diesem hochgradig verdächtigen Kontext ein ALK-Rearrangement nicht aus. RNA-NGS weist ein exprimiertes TPM3::ALK-Transkript nach; ALK-FISH bestätigt das Rearrangement orthogonal. Der Fall zeigt den komplementären Wert von RNA- und DNA-basierten Ansätzen.":"Call-ul negativ de fuziune ADN nu exclude o rearanjare ALK în acest context cu suspiciune mare. NGS ARN detectează un transcript TPM3::ALK exprimat; FISH ALK confirmă ortogonal rearanjarea. Cazul arată valoarea complementară a abordărilor bazate pe ARN și ADN.","Teilbefund: Bei hoher morphologisch-immunhistochemischer Prätestwahrscheinlichkeit ist ein negativer DNA-Fusionscall nicht automatisch abschließend.":"Rezultat parțial: la o probabilitate pretest morfologică/imunohistochimică mare, un call negativ de fuziune ADN nu este automat definitiv.","Assaydesign/Breakpointabdeckung berücksichtigen":"Luați în considerare designul testului/acoperirea breakpoint-urilor","RNA als direkte Ebene des exprimierten Fusionstranskripts einordnen":"Încadrați ARN ca nivel direct al transcriptului de fuziune exprimat","FISH als orthogonalen Rearrangementnachweis einordnen":"Încadrați FISH ca dovadă ortogonală a rearanjării","Falschaussage: ALK steht im DNA-Panel, daher sind alle ALK-Fusionen ausgeschlossen":"Afirmație falsă: ALK este inclus în panelul ADN, deci toate fuziunile ALK sunt excluse","Optimale Lösung: Widerspruch zwischen starker Prätestwahrscheinlichkeit und negativem DNA-Fusionscall erkennen und mit RNA-basierter Fusionsdiagnostik bzw. FISH klären.":"Soluție optimă: recunoașteți contradicția dintre probabilitatea pretest mare și call-ul negativ de fuziune ADN și clarificați-o prin testare de fuziuni bazată pe ARN și/sau FISH.","Fusion":"Fuziune","ALK":"ALK","DNA negativ, Biologie positiv":"ADN negativ, biologie pozitivă","Molekularpathologie / Fusionsdiagnostik / Sarkom-MTB":"Patologie moleculară / Diagnostic de fuziuni / MTB sarcoame","Grenzen DNA-basierter Fusionsdetektion durch Breakpoint-/Intronabdeckung verstehen.":"Înțelegerea limitelor detecției fuziunilor bazate pe ADN impuse de acoperirea breakpoint-urilor/intronilor.","RNA-NGS als komplementären Nachweis exprimierter Fusionstranskripte nutzen.":"Utilizați NGS ARN ca dovadă complementară pentru transcriptele de fuziune exprimate.","Prätestwahrscheinlichkeit aus Morphologie/IHC in die Methodenauswahl integrieren.":"Integrați probabilitatea pretest din morfologie/IHC în alegerea metodei.","FISH als orthogonalen Rearrangementnachweis mit begrenzter Partnerinformation einordnen.":"Interpretați FISH ca dovadă ortogonală a rearanjării, cu informație limitată despre partener.","ALK ist immunhistochemisch leuchtend positiv, die Morphologie passt – und trotzdem sagt das DNA-Panel „keine Fusion“. Der Fall beginnt dort, wo ein Automat aufhören würde.":"ALK este intens pozitiv la IHC, morfologia se potrivește — și totuși panelul ADN spune „fără fuziune”. Cazul începe acolo unde un sistem automat s-ar opri.","34-jährige Patientin mit IMT. ALK-IHC und Morphologie sprechen stark für einen Fusionsmechanismus, das DNA-Panel bleibt negativ. Das Assaydesign deckt nicht alle möglichen intronischen Breakpoints ab.":"Pacientă de 34 de ani cu IMT. IHC ALK și morfologia susțin puternic un mecanism de fuziune, dar panelul ADN este negativ. Designul testului nu acoperă toate breakpoint-urile intronice posibile.","Panelinhalt ≠ vollständige Fusionsabdeckung":"Conținutul panelului ≠ acoperire completă a fuziunilor","Ein Gen kann im Panel sein, ohne dass jeder relevante intronische Breakpoint erfasst wird.":"O genă poate fi în panel fără ca fiecare breakpoint intronic relevant să fie acoperit.","Assaydesign bestimmt Sensitivität.":"Designul testului determină sensibilitatea.","RNA fragt nach dem Produkt":"ARN întreabă despre produs","Ein RNA-Fusionsassay kann das tatsächlich exprimierte Chimärtranskript nachweisen.":"Un test de fuziuni ARN poate detecta transcriptul himeric exprimat efectiv.","RNA und DNA sind komplementär.":"ARN și ADN sunt complementare.","Prätestwahrscheinlichkeit zählt":"Probabilitatea pretest contează","Morphologie + ALK-IHC machen einen negativen DNA-Call unplausibel genug für Reflexdiagnostik.":"Morfologia + IHC ALK fac un call ADN negativ suficient de improbabil pentru a justifica testarea reflex.","Diagnostik ist Bayes, nicht nur Softwareoutput.":"Diagnosticul este bayesian, nu doar output de software.","IMT-kompatibel":"compatibil cu IMT","diffus stark positiv":"difuz intens pozitiv","kein Fusionscall; intronische Coverage limitiert":"fără call de fuziune; acoperire intronică limitată","RNA-Qualität ausreichend.":"Calitatea ARN este adecvată.","FISH verfügbar.":"FISH disponibil.","Kein Bedarf für beliebige weitere DNA-Breite, wenn die offene Frage eine Fusion ist.":"Nu este nevoie de extindere ADN arbitrară atunci când întrebarea deschisă este o fuziune.","Wie ist der negative DNA-Fusionscall bei starker ALK-IHC und passender Morphologie zu bewerten?":"Cum trebuie interpretat call-ul negativ de fuziune ADN în prezența unei IHC ALK intens pozitive și a unei morfologii compatibile?","Er schließt eine Fusion nicht sicher aus, wenn relevante Breakpoints vom Assay nicht vollständig erfasst werden.":"Nu exclude în siguranță o fuziune dacă breakpoint-urile relevante nu sunt acoperite complet de test.","ALK-Fusion ist sicher ausgeschlossen.":"Fuziunea ALK este exclusă cu certitudine.","IHC ist damit automatisch falsch.":"Prin urmare, IHC este automat greșită.","Es handelt sich um Keimbahn-ALK.":"Este ALK germinal.","Fusionssensitivität hängt stark vom Assaydesign ab.":"Sensibilitatea pentru fuziuni depinde puternic de designul testului.","Warum ist RNA-NGS hier besonders sinnvoll?":"De ce este NGS ARN deosebit de util aici?","Es kann ein exprimiertes Fusionstranskript direkt erfassen und DNA-Breakpointgrenzen umgehen.":"Poate detecta direct un transcript de fuziune exprimat și poate ocoli limitările breakpoint-urilor ADN.","Es ist exakt derselbe Test wie DNA-NGS.":"Este exact același test ca NGS ADN.","Es misst nur Proteinexpression.":"Măsoară doar expresia proteică.","Es ist primär ein Copy-number-Test.":"Este în principal un test de copy-number.","RNA liefert eine komplementäre Fusionsinformation.":"ARN furnizează informație complementară despre fuziune.","Was kann ein positiver ALK-Break-apart-FISH hier sinnvoll beitragen?":"Ce poate adăuga util aici un FISH break-apart ALK pozitiv?","Orthogonaler Nachweis eines ALK-Rearrangements, meist ohne genaue Partner-/Transkriptinformation.":"Dovadă ortogonală a unei rearanjări ALK, de obicei fără informație exactă despre partener/transcript.","Immer vollständige Sequenz des Fusionspartners.":"Întotdeauna secvența completă a partenerului de fuziune.","Quantitative RNA-Expression.":"Expresie ARN cantitativă.","Keimbahnstatus.":"Statut germinal.","FISH ist schnell und orthogonal, aber informationsärmer als sequenzbasierte Partnerbestimmung.":"FISH este rapid și ortogonal, dar oferă mai puține informații decât identificarea partenerului bazată pe secvență.","RNA-NGS zeigt TPM3::ALK. Was erklärt die DNA/RNA-Diskrepanz am besten?":"NGS ARN arată TPM3::ALK. Ce explică cel mai bine discrepanța ADN/ARN?","Das DNA-Assaydesign hat den relevanten Breakpoint nicht zuverlässig abgedeckt; RNA erfasst das exprimierte Transkript.":"Designul testului ADN nu a acoperit fiabil breakpoint-ul relevant; ARN detectează transcriptul exprimat.","RNA muss falsch sein, weil DNA negativ war.":"ARN trebuie să fie greșit deoarece ADN a fost negativ.","Die Histologie ist damit irrelevant.":"Prin urmare, histologia este irelevantă.","Beide Tests sind negativ.":"Ambele teste sunt negative.","Komplementäre Assaygrenzen erklären die Diskrepanz.":"Limitările complementare ale testelor explică discrepanța.","Entscheiden Sie, ob und wie der Fusionsverdacht nach negativem DNA-NGS weiter abgeklärt wird.":"Decideți dacă și cum trebuie investigată în continuare suspiciunea de fuziune după NGS ADN negativ.","Prätestwahrscheinlichkeit aus Morphologie/IHC festhalten.":"Documentați probabilitatea pretest din morfologie/IHC.","DNA-Assaydesign und intronische Abdeckung prüfen.":"Revizuiți designul testului ADN și acoperirea intronică.","RNA-basierte Fusionsdiagnostik ergänzen.":"Adăugați testare de fuziuni bazată pe ARN.","FISH bei Bedarf orthogonal oder schnell ergänzen.":"Adăugați FISH ortogonal sau rapid, la nevoie.","Endbefund als integrierte Fusionsevidenz formulieren.":"Formulați raportul final ca evidență integrată de fuziune.","Bei nicht verwertbarer RNA kann FISH eine praktikable orthogonale Alternative sein; für Partner-/Transkriptinformation bleibt sequenzbasierte Diagnostik überlegen.":"Dacă ARN nu este evaluabil, FISH poate fi o alternativă ortogonală practică; testarea bazată pe secvență rămâne superioară pentru informații despre partener/transcript.","DNA negativ = Fusion ausgeschlossen":"ADN negativ = fuziune exclusă","Ignoriert intronische Assaygrenzen.":"Ignoră limitările intronice ale testului.","Nur IHC als endgültiger Fusionsnachweis":"Doar IHC ca dovadă definitivă a fuziunii","Proteinexpression ist kontextabhängig und nicht identisch mit Sequenznachweis.":"Expresia proteică este dependentă de context și nu este identică cu dovada prin secvență.","Beliebig größeres DNA-Panel":"Panel ADN arbitrar mai mare","Mehr Gene lösen nicht zwingend das Breakpointproblem.":"Mai multe gene nu rezolvă neapărat problema breakpoint-ului.","Die Fusion war die ganze Zeit exprimiert":"Fuziunea era exprimată tot timpul","RNA-NGS weist TPM3::ALK nach; FISH bestätigt das ALK-Rearrangement.":"NGS ARN detectează TPM3::ALK; FISH confirmă rearanjarea ALK.","Der negative DNA-Call war methodisch begrenzt, nicht biologisch endgültig.":"Call-ul ADN negativ a fost limitat metodologic, nu definitiv biologic.","Komplementär getestet":"Testare complementară efectuată","RNA weist exprimierte Fusion nach, FISH stützt Rearrangement.":"ARN detectează fuziunea exprimată, FISH susține rearanjarea.","Methodengerechte Auflösung der Diskrepanz.":"Rezolvare a discrepanței adecvată metodei.","Nach DNA-NGS beendet":"Oprit după NGS ADN","Relevante Fusion bleibt unentdeckt.":"Fuziunea relevantă rămâne nedetectată.","Falsch-negatives Methodensilo.":"Silo metodologic fals-negativ.","Nur IHC akzeptiert":"Acceptat doar IHC","Fusionsmechanismus nicht molekular geklärt.":"Mecanismul de fuziune nu este clarificat molecular.","Unvollständige Charakterisierung.":"Caracterizare incompletă.","hohe Fusionsprätestwahrscheinlichkeit + nichtinformativer/negativer DNA-Call":"probabilitate pretest mare de fuziune + call ADN neinformativ/negativ","RNA-Fusionsdiagnostik und/oder orthogonalen Assay ergänzen":"adăugați testare de fuziuni ARN și/sau un test ortogonal","Negativer DNA-Call nicht als universellen Ausschluss formulieren.":"Nu formulați un call ADN negativ ca excludere universală.","DNA- und RNA-Fusionsdiagnostik sind komplementär.":"Diagnosticul fuziunilor bazat pe ADN și ARN este complementar.","Assaydesign ist Teil der Befundinterpretation.":"Designul testului face parte din interpretarea raportului.","Prätestwahrscheinlichkeit entscheidet, wann ein negativer Test nicht das Ende ist.":"Probabilitatea pretest determină când un test negativ nu reprezintă finalul.","Trotz negativem DNA-NGS bleibt der Fusionsverdacht hoch; RNA-NGS weist TPM3::ALK nach, FISH bestätigt das Rearrangement. DNA-Negativität war durch die Breakpointabdeckung limitiert.":"În ciuda NGS ADN negativ, suspiciunea de fuziune rămâne mare; NGS ARN detectează TPM3::ALK, iar FISH confirmă rearanjarea. Negativitatea ADN a fost limitată de acoperirea breakpoint-ului.","Fusionsmethodik":"Metodologia fuziunilor","Assaygrenzen":"Limitările testului","Wann ist FISH schneller als RNA-NGS?":"Când este FISH mai rapid decât NGS ARN?","Welche RNA-QC ist für FFPE kritisch?":"Ce parametri QC pentru ARN sunt critici în FFPE?","Wie sollte ein negativer DNA-Fusionsbericht Limitationen nennen?":"Cum trebuie să menționeze limitările un raport negativ de fuziune ADN?","Twist: DNA-negativ trotz echter Fusion":"Twist: ADN negativ în ciuda unei fuziuni reale","RNA als komplementäre Ebene":"ARN ca nivel complementar","Referenzpfad: Prätestwahrscheinlichkeit → Assaydesign → RNA/FISH":"Cale de referință: probabilitate pretest → designul testului → ARN/FISH","Liquid Biopsy negativ bei Progress: kein ctDNA-Signal ist kein Tumor-Wildtyp":"Biopsie lichidă negativă la progresie: absența semnalului ctDNA nu înseamnă tumoră wild type","Liquid Biopsy negativ bei Progress":"Biopsie lichidă negativă la progresie","66-jähriger Patient mit EGFR-mutiertem NSCLC und radiologischem Progress nach längerer Krankheitskontrolle. Plasma-NGS meldet „keine tumorassoziierte Variante nachweisbar“.":"Pacient de 66 de ani cu NSCLC EGFR-mutant și progresie radiologică după control prelungit al bolii. NGS plasmatic raportează „nicio variantă asociată tumorii detectată”.","Darf das als fehlender Resistenzmechanismus interpretiert werden oder ist die Probe schlicht nicht informativ?":"Poate fi interpretat ca absență a unui mecanism de rezistență sau proba este pur și simplu neinformativă?","Therapieumstellung soll im nächsten MTB erfolgen.":"Modificarea terapiei urmează să fie decisă la următorul MTB.","Neue Leberläsion und progrediente mediastinale Lymphknoten.":"Leziune hepatică nouă și ganglioni mediastinali progresivi.","Plasma":"Plasmă","Keine bekannte klonale EGFR-Mutation detektierbar; Tumorfraktionsschätzer sehr niedrig/nicht informativ.":"Mutația clonală EGFR cunoscută nu este detectabilă; estimarea fracției tumorale este foarte mică/neinformativă.","Ein negativer Plasma-Report wird wie ein negativer Tumorbefund gelesen.":"Un raport plasmatic negativ este citit ca un rezultat tumoral negativ.","Informative von nichtinformativer Negativität unterscheiden.":"Distingeți negativitatea informativă de cea neinformativă.","Vorbekannter Tumor":"Tumoră cunoscută","EGFR-aktivierende Mutation im ursprünglichen Tumor.":"Mutație activatoare EGFR în tumora inițială.","Plasma jetzt":"Plasmă acum","Weder der bekannte Treiber noch neue Resistenzalterationen detektierbar.":"Nu este detectabil nici driver-ul cunoscut, nici alterări noi de rezistență.","Fehlt biologisch ein Resistenzmechanismus oder fehlt im Plasma ausreichend ctDNA?":"Lipsește biologic un mecanism de rezistență sau pur și simplu nu există suficient ctDNA în plasmă?","Wenn selbst der bekannte Tumormarker nicht erscheint, ist die Negativaussage besonders fragil.":"Dacă lipsește chiar și markerul tumoral cunoscut, afirmația negativă este deosebit de fragilă.","Plasma technisch korrekt gewonnen.":"Plasmă recoltată corect din punct de vedere tehnic.","ctDNA":"ctDNA","sehr niedrige Tumorfraktion.":"fracție tumorală foarte mică.","Rebiopsie":"Rebiopsie","Leberläsion bildgesteuert zugänglich.":"Leziune hepatică accesibilă pentru biopsie ghidată imagistic.","Tissue-Rebiopsie und Gewebeprofil möglich.":"Sunt posibile rebiopsia tisulară și profilarea tisulară.","Liquid-Biopsy-Informativität bewerten":"Evaluați caracterul informativ al biopsiei lichide","Nichtinformatives Plasma durch Tumorgewebe klären":"Clarificați plasma neinformativă prin țesut tumoral","Liquid Biopsy":"Biopsie lichidă","Keine tumorassoziierte Variante nachweisbar; selbst der bekannte klonale EGFR-Treiber fehlt. Tumorfraktion sehr niedrig – negatives Ergebnis ist nicht als Tumor-Wildtyp interpretierbar.":"Nu este detectată nicio variantă asociată tumorii; lipsește chiar și driver-ul clonal EGFR cunoscut. Fracția tumorală este foarte mică — rezultatul negativ nu poate fi interpretat ca tumoră wild type.","Tissue-Rebiopsie":"Rebiopsie tisulară","Rebiopsie der progredienten Lebermetastase bestätigt Tumor und liefert ausreichend DNA für Gewebeprofiling.":"Rebiopsia metastazei hepatice progresive confirmă tumora și furnizează suficient ADN pentru profilare tisulară.","Gewebeprofil":"Profil tisular","Im Progressionsgewebe bleibt der EGFR-Treiber nachweisbar; zusätzlich zeigt sich eine relevante MET-Amplifikation als Resistenzmechanismus.":"Driver-ul EGFR rămâne detectabil în țesutul de progresie; în plus, apare o amplificare MET relevantă ca mecanism de rezistență.","Plasma-QC":"QC plasmă","Technisch valide Probe, biologisch jedoch mit sehr niedriger/nicht informativer Tumorfraktion.":"Probă tehnic validă, dar biologic cu fracție tumorală foarte mică/neinformativă.","Ein nichtinformatives negatives ctDNA-Ergebnis darf einen Tumorbefund nicht ersetzen.":"Un rezultat ctDNA negativ neinformativ nu trebuie să înlocuiască un rezultat tumoral.","Die negative Liquid Biopsy ist wegen sehr niedriger Tumorfraktion und fehlendem Nachweis sogar des bekannten Treibers nicht informativ. Geweberebiopsie ist deshalb sinnvoll und zeigt im Progressionsgewebe weiterhin die EGFR-Alteration sowie eine MET-Amplifikation. „Plasma negativ“ war kein Beweis für fehlende Tumoralterationen.":"Biopsia lichidă negativă este neinformativă din cauza fracției tumorale foarte mici și a absenței chiar și a driver-ului cunoscut. Rebiopsia tisulară este astfel adecvată și arată alterarea EGFR plus o amplificare MET în țesutul de progresie. „Plasmă negativă” nu a fost dovada absenței alterărilor tumorale.","Teilbefund: Eine negative Liquid Biopsy muss im Kontext von ctDNA/Tumorfraktion, Tumorbiologie und bekannten Markerbefunden interpretiert werden.":"Rezultat parțial: o biopsie lichidă negativă trebuie interpretată în contextul ctDNA/fracției tumorale, biologiei tumorale și markerilor cunoscuți.","Tumorfraktion/Shedding berücksichtigen":"Luați în considerare fracția tumorală/shedding-ul","Fehlen des bekannten Treibers als Warnsignal für Nichtinformativität":"Absența driver-ului cunoscut ca semnal de avertizare pentru neinformativitate","bei klinischer Relevanz Gewebe-Reflex erwägen":"Luați în considerare testarea reflex pe țesut când este clinic relevant","Falschaussage: Plasma negativ = Tumor molekular negativ":"Afirmație falsă: plasmă negativă = tumoră molecular negativă","Optimale Lösung: negative Liquid Biopsy als möglicherweise nichtinformativ erkennen und bei zugänglichem Progressionsgewebe reflexartig tissue-basiert nachtesten.":"Soluție optimă: recunoașteți o biopsie lichidă negativă ca potențial neinformativă și efectuați reflex testare pe țesut când există țesut de progresie accesibil.","Progress":"Progresie","Negativ – aber ohne Tumorsignal":"Negativ — dar fără semnal tumoral","Thoraxonkologie / Liquid Biopsy / MTB":"Oncologie toracică / Biopsie lichidă / MTB","Negative ctDNA-Ergebnisse von informativen positiven Ergebnissen asymmetrisch interpretieren.":"Interpretați asimetric rezultatele ctDNA negative față de rezultatele pozitive informative.","Tumorfraktion/Shedding und Nachweis eines bekannten Tumormarkers berücksichtigen.":"Luați în considerare fracția tumorală/shedding-ul și detectarea unui marker tumoral cunoscut.","Bei nichtinformativem Plasma und klinischer Relevanz Gewebetestung erwägen.":"Luați în considerare testarea tisulară când plasma este neinformativă și întrebarea este clinic relevantă.","Plasma- und Tissue-Profiling als komplementäre Strategien verstehen.":"Înțelegeți profilarea plasmatică și tisulară ca strategii complementare.","Der Plasma-Report ist leer. Nicht einmal die bekannte EGFR-Mutation taucht auf. Das kann heißen „Tumor ohne Alterationen“ – oder viel wahrscheinlicher: „zu wenig Tumor-DNA im Röhrchen, um etwas sicher auszuschließen“.":"Raportul plasmatic este gol. Nu apare nici măcar mutația EGFR cunoscută. Aceasta poate însemna „tumoră fără alterări” — sau, mult mai probabil, „prea puțin ADN tumoral în tub pentru a exclude ceva în mod fiabil”.","66-jähriger Patient mit EGFR-mutiertem NSCLC im Progress. Plasma-NGS ist technisch valide, zeigt aber keine tumorassoziierten Varianten und eine sehr niedrige Tumorfraktion. Eine Leberläsion ist biopsierbar.":"Pacient de 66 de ani cu NSCLC EGFR-mutant în progresie. NGS plasmatic este tehnic valid, dar nu arată variante asociate tumorii și are o fracție tumorală foarte mică. O leziune hepatică poate fi biopsiată.","Negativ ist asymmetrisch":"Negativitatea este asimetrică","Ein positiver validierter ctDNA-Befund kann sehr informativ sein; ein negativer Befund kann bei niedrigem Shedding falsch-negativ sein.":"Un rezultat ctDNA pozitiv validat poate fi foarte informativ; un rezultat negativ poate fi fals-negativ când shedding-ul este scăzut.","Negativaussagen brauchen Informativitätskontext.":"Afirmațiile negative necesită context privind informativitatea.","Der bekannte Treiber als interne Plausibilität":"Driver-ul cunoscut ca verificare internă de plauzibilitate","Wenn die etablierte EGFR-Mutation nicht detektierbar ist, spricht das gegen ausreichend Tumorsignal.":"Dacă mutația EGFR cunoscută nu este detectabilă, aceasta sugerează un semnal tumoral insuficient.","Vorwissen hilft, die Probe zu interpretieren.":"Cunoștințele anterioare ajută la interpretarea probei.","Tissue bleibt relevant":"Țesutul rămâne relevant","Bei nichtinformativer ctDNA kann Gewebe einen Resistenzmechanismus sichtbar machen.":"Când ctDNA este neinformativ, țesutul poate evidenția un mecanism de rezistență.","Liquid Biopsy ersetzt Gewebe nicht in jeder Situation.":"Biopsia lichidă nu înlocuiește țesutul în orice situație.","EGFR-mutierter Primärtumor":"Tumoră primară EGFR-mutantă","Plasma-NGS":"NGS plasmatic","keine tumorassoziierte Variante":"nicio variantă asociată tumorii","Tumorfraktion":"Fracție tumorală","sehr niedrig / nicht informativ":"foarte mică / neinformativă","Plasma technisch korrekt.":"Plasma tehnic adecvată.","Progressionsgewebe zugänglich.":"Țesut de progresie accesibil.","Copy-number-/Fusionserfassung kann zusätzlich von Assay und Tumorfraktion abhängen.":"Detecția copy-number/fuziunilor poate depinde suplimentar de test și fracția tumorală.","Wie ist eine negative ctDNA-Analyse bei sehr niedriger Tumorfraktion zu bewerten?":"Cum trebuie evaluată o analiză ctDNA negativă cu fracție tumorală foarte mică?","Als potenziell nichtinformativ/falsch-negativ; Tumoralterationen sind damit nicht sicher ausgeschlossen.":"Ca potențial neinformativă/fals-negativă; alterările tumorale nu sunt excluse în mod fiabil.","Der Tumor ist sicher wildtyp.":"Tumora este cu siguranță wild type.","Es liegt sicher kein Tumor mehr vor.":"Cu siguranță nu mai există tumoră.","Nur Keimbahnvarianten sind möglich.":"Sunt posibile doar variante germinale.","ctDNA-Sensitivität hängt vom Tumorshedding und der Tumorfraktion ab.":"Sensibilitatea ctDNA depinde de shedding-ul tumoral și fracția tumorală.","Warum ist das Fehlen der bekannten klonalen EGFR-Mutation besonders wichtig?":"De ce este deosebit de importantă absența mutației clonale EGFR cunoscute?","Es ist ein Warnsignal, dass im Plasma möglicherweise kaum detektierbare Tumor-DNA vorliegt.":"Este un semnal de avertizare că în plasmă poate exista foarte puțin ADN tumoral detectabil.","Der Tumor muss EGFR sicher verloren haben.":"Tumora trebuie să fi pierdut cu siguranță EGFR.","Der gesamte Labortest ist technisch zwingend ungültig.":"Întregul test de laborator este obligatoriu tehnic invalid.","Es ist ohne Bedeutung.":"Este fără importanță.","Der bekannte Marker dient als biologische Plausibilitätskontrolle.":"Markerul cunoscut servește drept control biologic de plauzibilitate.","Was ist bei zugänglichem Progressionsgewebe der sinnvollste nächste Schritt?":"Care este următorul pas cel mai potrivit când țesutul de progresie este accesibil?","Geweberebiopsie/Gewebeprofiling zur Resistenzklärung.":"Rebiopsie tisulară/profilare tisulară pentru clarificarea rezistenței.","Keine weitere Diagnostik.":"Fără alte investigații.","Nur dasselbe Plasmaresultat erneut interpretieren.":"Doar reinterpretați același rezultat plasmatic.","Methylierungsarray.":"Array de metilare.","Nichtinformative ctDNA sollte bei relevanter Frage durch Gewebe ergänzt werden.":"ctDNA neinformativ trebuie completat prin țesut când întrebarea este clinic relevantă.","Gewebe zeigt den bekannten EGFR-Treiber plus MET-Amplifikation. Was lehrt die Diskrepanz?":"Țesutul arată driver-ul EGFR cunoscut plus amplificare MET. Ce ne învață discrepanța?","Das negative Plasma war wegen geringer Tumorfraktion nicht ausreichend zum Ausschluss eines Resistenzmechanismus.":"Rezultatul plasmatic negativ a fost insuficient pentru a exclude un mecanism de rezistență din cauza fracției tumorale mici.","Das Gewebe muss falsch sein.":"Țesutul trebuie să fie greșit.","Liquid Biopsy ist grundsätzlich nutzlos.":"Biopsia lichidă este în general inutilă.","Beide Befunde bedeuten dasselbe.":"Ambele rezultate înseamnă același lucru.","Liquid Biopsy ist wertvoll, aber negative Ergebnisse sind kontextabhängig.":"Biopsia lichidă este valoroasă, dar rezultatele negative depind de context.","Entscheiden Sie, ob die negative Liquid Biopsy die Resistenzdiagnostik beendet oder eine Tissue-Reflexstrategie nötig ist.":"Decideți dacă biopsia lichidă negativă încheie testarea rezistenței sau necesită o strategie reflex pe țesut.","Plasma-QC und Tumorfraktion bewerten.":"Evaluați QC plasmatic și fracția tumorală.","Bekannten Tumormarker als Plausibilitätsanker nutzen.":"Utilizați markerul tumoral cunoscut ca ancoră de plauzibilitate.","Negativbefund nicht überinterpretieren.":"Nu suprainterpretați rezultatul negativ.","Bei zugänglichem Progressionsgewebe Gewebetestung ergänzen.":"Adăugați testare tisulară când țesutul de progresie este accesibil.","Diskrepanz integriert berichten.":"Raportați integrat discrepanța.","Wenn Gewebe nicht zugänglich ist, kann eine erneute Plasmaanalyse zu einem biologisch günstigeren Zeitpunkt oder eine alternative Flüssigkeit je nach Entität erwogen werden; das ersetzt keine pauschale Garantie.":"Dacă țesutul nu este accesibil, se poate lua în considerare repetarea analizei plasmatice într-un moment biologic mai favorabil sau un lichid alternativ, în funcție de entitate; aceasta nu reprezintă o garanție universală.","Plasma negativ = Tumor negativ":"Plasmă negativă = tumoră negativă","Ignoriert falsch-negative Ergebnisse bei niedrigem Shedding.":"Ignoră rezultatele fals-negative la shedding scăzut.","Liquid Biopsy generell verwerfen":"Respingeți biopsia lichidă în general","Positive/informative Ergebnisse können klinisch sehr nützlich sein.":"Rezultatele pozitive/informative pot fi foarte utile clinic.","Tumorfraktion ignorieren":"Ignorați fracția tumorală","Entfernt den wichtigsten Informativitätsparameter.":"Elimină cel mai important parametru de informativitate.","Das Gewebe findet, was das Plasma nicht sehen konnte":"Țesutul găsește ceea ce plasma nu a putut vedea","Tissue-Profiling zeigt den bekannten Treiber und eine MET-Amplifikation.":"Profilarea tisulară arată driver-ul cunoscut și o amplificare MET.","Die diagnostische Frage war nicht „war der Plasmatest technisch okay?“, sondern „war er biologisch informativ genug, um etwas auszuschließen?“":"Întrebarea diagnostică nu a fost „a fost testul plasmatic tehnic în regulă?”, ci „a fost biologic suficient de informativ pentru a exclude ceva?”.","Nichtinformativ erkannt":"Rezultat neinformativ recunoscut","Tissue-Reflex deckt Resistenzmechanismus auf.":"Reflex-ul tisular evidențiază un mecanism de rezistență.","Korrekte Liquid-Biopsy-Logik.":"Logică corectă pentru biopsia lichidă.","Nach negativem Plasma beendet":"Oprit după plasmă negativă","Resistenzmechanismus bleibt unentdeckt.":"Mecanismul de rezistență rămâne nedetectat.","Falsch-negatives Overconfidence.":"Încredere excesivă într-un fals-negativ.","Liquid Biopsy generell abgelehnt":"Biopsia lichidă respinsă în general","Methodennutzen wird unnötig negiert.":"Utilitatea metodei este negată inutil.","Zu pauschal.":"Prea general.","negatives ctDNA + niedrige Tumorfraktion/fehlender bekannter Treiber":"ctDNA negativ + fracție tumorală mică/driver cunoscut absent","Ergebnis als nichtinformativ kennzeichnen und Gewebe erwägen":"marcați rezultatul ca neinformativ și luați în considerare țesutul","Keine sichere Negativaussage über Tumorgenom.":"Nicio afirmație negativă sigură despre genomul tumoral.","Negative ctDNA-Befunde sind kontextabhängig.":"Rezultatele ctDNA negative depind de context.","Tumorfraktion und Shedding gehören zur Interpretation.":"Fracția tumorală și shedding-ul fac parte din interpretare.","Plasma und Gewebe ergänzen sich.":"Plasma și țesutul se completează reciproc.","Negative Liquid Biopsy bei sehr niedriger Tumorfraktion und fehlendem bekanntem Treiber ist nicht ausreichend zum Ausschluss von Resistenzalterationen; Gewebe-Reflex zeigt hier MET-Amplifikation.":"O biopsie lichidă negativă cu fracție tumorală foarte mică și driver cunoscut absent este insuficientă pentru a exclude alterări de rezistență; reflex-ul tisular evidențiază aici o amplificare MET.","ctDNA-Informativität":"Informativitatea ctDNA","Reflex-Tissue":"Reflex tisular","Negativbefund":"Rezultat negativ","Welche Tumorlokalisationen sheddern schlecht?":"Ce localizări tumorale sheddează slab?","Wann ist Plasma besonders sinnvoll?":"Când este plasma deosebit de utilă?","Wie sollte Tumorfraktion im Report kommuniziert werden?":"Cum trebuie comunicată fracția tumorală în raport?","Twist: technisch negatives Plasma, biologisch nichtinformativ":"Twist: plasmă tehnic negativă, biologic neinformativă","Bekannter Treiber als Plausibilitätsanker":"Driver cunoscut ca ancoră de plauzibilitate","Referenzpfad: Tumorfraktion → Negativität begrenzen → Tissue-Reflex":"Cale de referință: fracție tumorală → limitarea interpretării negative → reflex tisular","NPM1-MRD: diagnostisches NGS negativ, gezielte PCR noch positiv":"MRD NPM1: NGS diagnostic negativ, PCR țintită încă pozitivă","qPCR/dPCR für MRD statt breites Pa…":"qPCR/dPCR pentru MRD în locul unui panel larg…","Hämatologie / Molekulares Tumorboard":"Hematologie / Tumor Board molecular","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung in morphologischer kompletter Remission. Ein breites myeloisches NGS-Panel ist „negativ“.":"Pacientă de 52 de ani cu AML NPM1-mutată, după consolidare, în remisiune completă morfologică. Un panel NGS mieloid larg este „negativ”.","Reicht das breite Panel für die MRD-Beurteilung oder braucht es die hochsensitive, zielgerichtete NPM1-Methode?":"Este suficient panelul larg pentru evaluarea MRD sau este necesară metoda NPM1 țintită, cu sensibilitate înaltă?","MRD-Status soll vor der nächsten risikoadaptierten Entscheidung vorliegen.":"Statusul MRD trebuie cunoscut înaintea următoarei decizii adaptate riscului.","Diagnosemarker":"Marker diagnostic","NPM1-Mutation bei Erstdiagnose eindeutig dokumentiert.":"Mutația NPM1 este clar documentată la diagnosticul inițial.","<5 % Blasten, komplette morphologische Remission.":"<5% blaști, remisiune completă morfologică.","Breites NGS":"NGS larg","Keine pathogene Variante oberhalb der diagnostischen Reporting-Grenzen.":"Nicio variantă patogenă peste pragurile diagnostice de raportare.","Breite wird mit Sensitivität verwechselt.":"Lărgimea panelului este confundată cu sensibilitatea.","morphologisch in Remission.":"în remisiune morfologică.","Zielmarker":"Marker țintă","NPM1 patientenspezifisch bekannt.":"Marker NPM1 specific pacientei cunoscut.","Ist unterhalb der Sensitivität eines diagnostischen Panels noch messbare Resterkrankung nachweisbar?":"Poate fi detectată boală reziduală măsurabilă sub sensibilitatea unui panel diagnostic?","MRD ist eine andere analytische Aufgabe als initiale Genotypisierung.":"MRD este o sarcină analitică diferită de genotiparea inițială.","Knochenmark, ausreichende Nukleinsäurequalität.":"Măduvă osoasă, calitate adecvată a acizilor nucleici.","bekannter NPM1-Marker.":"marker NPM1 cunoscut.","Methodenwahl":"Alegerea metodei","gezielte qPCR/dPCR-artige MRD-Methode vs. breites Panel.":"metodă MRD țintită de tip qPCR/dPCR vs panel larg.","Beide technisch verfügbar; entscheidend ist die validierte Sensitivität für die Fragestellung.":"Ambele sunt disponibile tehnic; decisivă este sensibilitatea validată pentru întrebarea clinică.","Sensitive zielgerichtete MRD-Methode":"Metodă MRD țintită sensibilă","Zielgerichtete MRD-PCR":"PCR MRD țintită","Patientenspezifischer NPM1-Marker bleibt in niedriger Menge reproduzierbar positiv; messbare Resterkrankung ist trotz morphologischer Remission nachweisbar.":"Markerul NPM1 specific pacientei rămâne reproductibil pozitiv la nivel scăzut; boala reziduală măsurabilă este detectabilă în ciuda remisiunii morfologice.","Breites myeloisches Panel":"Panel mieloid larg","Keine Variante oberhalb der diagnostischen Panelgrenzen; dieser Negativbefund erreicht nicht automatisch die für NPM1-MRD erforderliche Sensitivität.":"Nicio variantă peste pragurile panelului diagnostic; acest rezultat negativ nu atinge automat sensibilitatea necesară pentru MRD NPM1.","Komplette morphologische Remission.":"Remisiune completă morfologică.","Diagnostische Panelbreite und MRD-Sensitivität sind unterschiedliche Leistungsmerkmale.":"Lărgimea unui panel diagnostic și sensibilitatea MRD sunt caracteristici de performanță diferite.","Das negative diagnostische NGS-Panel beweist keine molekulare MRD-Negativität. Da ein geeigneter NPM1-Zielmarker bekannt ist, ist eine validierte hochsensitive zielgerichtete qPCR/dPCR-basierte Strategie angemessen. Diese bleibt niedrig positiv und zeigt messbare Resterkrankung trotz morphologischer Remission.":"Un panel NGS diagnostic negativ nu dovedește negativitatea MRD moleculară. Deoarece este cunoscut un marker țintă NPM1 adecvat, este indicată o strategie țintită validată, foarte sensibilă, bazată pe qPCR/dPCR. Aceasta rămâne pozitivă la nivel scăzut și demonstrează boală reziduală măsurabilă în ciuda remisiunii morfologice.","Teilbefund: Für MRD muss die Methode zur erwarteten sehr niedrigen Krankheitslast und zum bekannten Zielmarker passen; ein breites Diagnostikpanel ist nicht automatisch sensitiv genug.":"Rezultat parțial: pentru MRD, metoda trebuie să corespundă încărcăturii foarte mici de boală așteptate și markerului țintă cunoscut; un panel diagnostic larg nu este automat suficient de sensibil.","Diagnostik vs. MRD als unterschiedliche Testzwecke trennen":"Separați diagnosticul de MRD ca scopuri de testare diferite","assayvalidierte Sensitivität berücksichtigen":"Luați în considerare sensibilitatea validată a testului","stabilen geeigneten Zielmarker nutzen":"Utilizați un marker țintă stabil și adecvat","Falschaussage: breiteres Panel ist für MRD automatisch besser":"Afirmație falsă: un panel mai larg este automat mai bun pentru MRD","Optimale Lösung: bekannten NPM1-Marker mit validierter hochsensitiver Zielmethode verfolgen; diagnostisches NGS negativ nicht mit MRD-negativ gleichsetzen.":"Soluție optimă: urmăriți markerul NPM1 cunoscut cu o metodă țintită validată și foarte sensibilă; nu echivalați NGS diagnostic negativ cu MRD negativ.","MRD":"MRD","NPM1":"NPM1","qPCR":"qPCR","dPCR":"dPCR","Breit negativ, hochsensitiv positiv":"Negativ la panel larg, pozitiv la metodă foarte sensibilă","Hämatologie / molekulare MRD-Diagnostik":"Hematologie / diagnostic molecular MRD","Diagnostisches NGS von MRD-Methodik unterscheiden.":"Distingeți NGS diagnostic de metodologia MRD.","Bei bekanntem geeignetem Marker eine validierte hochsensitive Zielmethode wählen.":"Când există un marker cunoscut adecvat, alegeți o metodă țintită validată, cu sensibilitate înaltă.","Analytische Sensitivität passend zur klinischen Fragestellung bewerten.":"Evaluați sensibilitatea analitică potrivită întrebării clinice.","Morphologische Remission nicht mit molekularer MRD-Negativität gleichsetzen.":"Nu echivalați remisiunea morfologică cu negativitatea MRD moleculară.","Im Abschlussbefund steht zweimal „negativ“: Morphologie unauffällig, breites NGS ohne Treffer. Die NPM1-MRD-PCR sagt trotzdem positiv. Der Widerspruch ist nur scheinbar – die Methoden fragen auf völlig unterschiedlichen Tiefen.":"Raportul final spune de două ori „negativ”: morfologia este fără particularități, NGS larg nu găsește nimic. Totuși PCR MRD NPM1 este pozitivă. Contradicția este doar aparentă — metodele investighează boala la profunzimi complet diferite.","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung. Morphologisch komplette Remission und diagnostisches Panel ohne Varianten oberhalb seiner Reporting-Grenzen. Für die MRD-Frage steht ein bekannter NPM1-Zielmarker zur Verfügung.":"Pacientă de 52 de ani cu AML NPM1-mutată după consolidare. Remisiune completă morfologică și panel diagnostic fără variante peste pragurile sale de raportare. Pentru întrebarea MRD este disponibil un marker țintă NPM1 cunoscut.","Breite ist nicht Tiefe":"Lărgimea nu este profunzime","Ein diagnostisches Panel kann viele Gene erfassen, aber nicht dieselbe Nachweisgrenze wie eine fokussierte MRD-Methode erreichen.":"Un panel diagnostic poate acoperi multe gene fără a atinge aceeași limită de detecție ca o metodă MRD focalizată.","Methodenauswahl folgt der Frage.":"Alegerea metodei urmează întrebarea.","Bekannter Marker ist ein Vorteil":"Un marker cunoscut este un avantaj","NPM1 ist bei Diagnose dokumentiert und gezielt verfolgbar.":"NPM1 este documentat la diagnostic și poate fi urmărit țintit.","MRD kann patientenspezifisch hochsensitiv sein.":"MRD poate fi foarte sensibilă și specifică pacientului.","Remission hat Ebenen":"Remisiunea are niveluri","Morphologische CR und molekulare MRD sind nicht synonym.":"CR morfologică și MRD moleculară nu sunt sinonime.","Mehrere Ebenen der Krankheitslast koexistieren.":"Coexistă mai multe niveluri ale încărcăturii de boală.","NPM1-mutierte AML":"AML NPM1-mutată","komplette Remission":"remisiune completă","kein Call oberhalb diagnostischer Reporting-Grenze":"niciun call peste pragul diagnostic de raportare","Knochenmarkmaterial ausreichend.":"Material de măduvă osoasă adecvat.","Zielmarker bekannt.":"Marker țintă cunoscut.","Die konkrete Nachweisgrenze ist labor- und assayvalidiert; keine universelle Prozentzahl wird vorausgesetzt.":"Limita exactă de detecție este validată de laborator și pentru testul respectiv; nu se presupune un procent universal.","Welche Methode passt am besten zur MRD-Frage bei bekanntem NPM1-Zielmarker?":"Ce metodă se potrivește cel mai bine întrebării MRD când există un marker țintă NPM1 cunoscut?","Validierte hochsensitive zielgerichtete qPCR/dPCR-basierte MRD-Methode.":"Metodă MRD țintită, validată, cu sensibilitate înaltă, bazată pe qPCR/dPCR.","Nur ein möglichst breites diagnostisches Panel.":"Doar cel mai larg panel diagnostic posibil.","Nur HE-Morphologie.":"Doar morfologie HE.","MRD verlangt hohe Sensitivität für einen geeigneten Zielmarker.":"MRD necesită sensibilitate înaltă pentru un marker țintă adecvat.","Was bedeutet ein negatives diagnostisches NGS-Panel hier?":"Ce înseamnă aici un panel NGS diagnostic negativ?","Keine Variante oberhalb seiner validierten Grenzen; molekulare MRD unterhalb dieser Grenzen kann bestehen.":"Nicio variantă peste limitele sale validate; MRD moleculară sub aceste limite poate exista totuși.","Absolut keine Leukämiezelle vorhanden.":"Nu este prezentă absolut nicio celulă leucemică.","MRD ist sicher negativ, unabhängig vom Assay.":"MRD este sigur negativă indiferent de test.","Die ursprüngliche AML-Diagnose war falsch.":"Diagnosticul inițial de AML a fost greșit.","Negativität gilt nur innerhalb der analytischen Leistungsfähigkeit.":"Negativitatea este valabilă doar în limitele performanței analitice.","Morphologische komplette Remission und MRD-positiv – ist das möglich?":"Remisiune completă morfologică și MRD pozitivă — este posibil?","Ja; MRD-Methoden erfassen deutlich niedrigere Krankheitslast als Morphologie.":"Da; metodele MRD detectează o încărcătură de boală mult mai mică decât morfologia.","Nein, die Befunde schließen sich aus.":"Nu, rezultatele se exclud reciproc.","MRD ist immer Artefakt.":"MRD este întotdeauna un artefact.","MRD hat keine klinische Bedeutung.":"MRD nu are semnificație clinică.","Die Ebenen messen unterschiedliche Sensitivitätsbereiche.":"Nivelurile măsoară intervale diferite de sensibilitate.","Die NPM1-MRD-Methode ist reproduzierbar niedrig positiv. Wie lautet die Kernaussage?":"Metoda MRD NPM1 este reproductibil slab pozitivă. Care este mesajul central?","Molekulare MRD ist nachweisbar, obwohl Morphologie und diagnostisches Panel negativ sind.":"MRD moleculară este detectabilă deși morfologia și panelul diagnostic sunt negative.","Das breite Panel überschreibt die MRD-PCR.":"Panelul larg prevalează asupra PCR MRD.","CR bedeutet zwingend null Resterkrankung.":"CR înseamnă obligatoriu zero boală reziduală.","Der Zielmarker darf nicht verwendet werden.":"Markerul țintă nu trebuie utilizat.","Die gezielte validierte MRD-Methode ist für diese Frage geeigneter.":"Metoda MRD țintită validată este mai potrivită pentru această întrebare.","Wählen und begründen Sie die Methode zur molekularen MRD-Beurteilung.":"Selectați și justificați metoda pentru evaluarea MRD moleculare.","Klinische Frage als MRD statt Diagnose definieren.":"Definiți întrebarea clinică drept MRD, nu diagnostic.","Geeigneten bekannten Zielmarker identifizieren.":"Identificați un marker țintă cunoscut și adecvat.","Assayvalidierte Sensitivität berücksichtigen.":"Luați în considerare sensibilitatea validată a testului.","Zielgerichtete MRD-PCR verwenden.":"Utilizați PCR MRD țintită.","Ergebnis getrennt von Morphologie und diagnostischem Panel berichten.":"Raportați rezultatul separat de morfologie și panelul diagnostic.","NGS-basierte MRD kann in validierten spezialisierten Ansätzen sinnvoll sein; der Fall richtet sich gegen die unkritische Verwendung eines routinemäßigen diagnostischen Breitenpanels als MRD-Ersatz.":"MRD bazată pe NGS poate fi utilă în abordări specializate validate; cazul se opune utilizării necritice a unui panel diagnostic larg de rutină ca substitut pentru testarea MRD.","Breiter = sensitiver":"Mai larg = mai sensibil","Verwechselt Panelumfang mit Nachweisgrenze.":"Confundă amploarea panelului cu limita de detecție.","Morphologische CR = MRD-negativ":"CR morfologică = MRD negativă","Ignoriert unterschiedliche Sensitivitätsebenen.":"Ignoră nivelurile diferite de sensibilitate.","Jede Persistenzmutation als MRD":"Orice mutație persistentă considerată MRD","Nicht jeder Marker ist gleich geeignet; clonal hematopoiesis kann einzelne Gene persistieren lassen.":"Nu orice marker este la fel de adecvat; hematopoieza clonală poate determina persistența unor gene individuale.","Die Resterkrankung liegt unter der Paneloberfläche":"Boala reziduală se află sub suprafața panelului","Gezielte NPM1-MRD bleibt reproduzierbar positiv.":"MRD NPM1 țintită rămâne reproductibil pozitivă.","Der Fall zeigt, warum Testzweck und Sensitivität wichtiger sind als maximale Genbreite.":"Cazul arată de ce scopul testului și sensibilitatea sunt mai importante decât lărgimea maximă a genelor.","Zielgerichtete MRD":"MRD țintită","NPM1-MRD korrekt nachgewiesen.":"MRD NPM1 detectată corect.","Fragestellungsgerechte Methodik.":"Metodologie adecvată întrebării.","Nur breites Panel":"Doar panel larg","Niedrige Resterkrankung wird fälschlich als negativ interpretiert.":"Boala reziduală la nivel scăzut este interpretată fals ca negativă.","Sensitivitätsproblem.":"Problemă de sensibilitate.","Nur Morphologie":"Doar morfologie","Molekulare Resterkrankung bleibt unsichtbar.":"Boala reziduală moleculară rămâne invizibilă.","Unvollständig.":"Incomplet.","bekannter geeigneter MRD-Marker":"marker MRD cunoscut și adecvat","validierte hochsensitive Zielmethode nutzen":"utilizați o metodă țintită validată, cu sensibilitate înaltă","Diagnostische Panelnegativität nicht als MRD-Negativität umdeuten.":"Nu reinterpretați negativitatea panelului diagnostic drept negativitate MRD.","MRD ist eine eigene analytische Aufgabe.":"MRD este o sarcină analitică proprie.","Breite und Sensitivität sind unabhängige Dimensionen.":"Lărgimea și sensibilitatea sunt dimensiuni independente.","Der beste Test ist der, dessen validierte Leistung zur klinischen Frage passt.":"Cel mai bun test este cel a cărui performanță validată corespunde întrebării clinice.","Bei bekannter NPM1-mutierter AML ist die validierte zielgerichtete MRD-PCR der geeignete Test; diagnostisches NGS negativ schließt niedriggradige molekulare Resterkrankung nicht aus.":"În AML NPM1-mutată cunoscută, PCR MRD țintită validată este testul potrivit; NGS diagnostic negativ nu exclude boala reziduală moleculară la nivel scăzut.","MRD-Methodenwahl":"Alegerea metodei MRD","Sensitivität":"Sensibilitate","Befundebenen":"Nivelurile rezultatelor","Welche Mutationen sind für AML-MRD problematisch?":"Ce mutații sunt problematice pentru MRD în AML?","Wann ist dPCR gegenüber qPCR sinnvoll?":"Când este utilă dPCR comparativ cu qPCR?","Welche Rolle hat NGS-basierte MRD?":"Ce rol are MRD bazată pe NGS?","Twist: diagnostisches NGS negativ, MRD-PCR positiv":"Twist: NGS diagnostic negativ, PCR MRD pozitivă","Breite ≠ Sensitivität":"Lărgime ≠ sensibilitate","Referenzpfad: Zielmarker → validierte MRD-Methode → getrennte Interpretation":"Cale de referință: marker țintă → metodă MRD validată → interpretare separată","MGMT-Frage im gesicherten Glioblastom: lokaler Marker statt Classifier-Overkill":"Întrebarea MGMT într-un glioblastom confirmat: marker local în loc de exces cu clasificatorul","Bisulfit-PCR vs. Methylierungsarra…":"PCR au bisulfit vs. array de metilare…","69-jähriger Patient mit histologisch und molekular eindeutig klassifiziertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung wird der MGMT-Promotor-Methylierungsstatus benötigt.":"Pacient de 69 de ani cu glioblastom clasificat fără echivoc histologic și molecular, IDH wild-type. Pentru planificarea tratamentului este necesar statusul metilării promotorului MGMT.","Braucht dieser Fall einen genomeweiten Methylierungsclassifier oder eine validierte zielgerichtete MGMT-Methylierungsanalyse?":"Este necesar în acest caz un clasificator de metilare la nivel genomic sau o analiză țintită validată a metilării MGMT?","Adjuvante Therapieplanung steht unmittelbar an.":"Planificarea tratamentului adjuvant este iminentă.","Glioblastom, IDH-Wildtyp, integriert gesichert; keine offene Entitätsfrage.":"Glioblastom, IDH wild-type, diagnostic integrat stabilit; nu există o întrebare nerezolvată privind entitatea.","Offene Biomarkerfrage":"Întrebare deschisă privind biomarkerul","MGMT-Promotor-Methylierung.":"Metilarea promotorului MGMT.","Ein technologisch umfassenderes Methylierungsarray wird automatisch als „besser“ angesehen.":"Un array de metilare mai cuprinzător din punct de vedere tehnologic este considerat automat „mai bun”.","Testscope an die konkrete klinische Frage und lokale Validierung koppeln.":"Corelați domeniul testului cu întrebarea clinică specifică și cu validarea locală.","Hochgradiges diffuses Astrozytom mit Nekrosen und mikrovaskulärer Proliferation.":"Astrocitom difuz de grad înalt cu necroză și proliferare microvasculară.","IDH-Wildtyp; integrierte Diagnose steht.":"IDH wild-type; diagnosticul integrat este stabilit.","MGMT-Promotor-Methylierungsstatus.":"Statusul metilării promotorului MGMT.","Klassifikation und prädiktiver Einzelmarker sind zwei verschiedene Aufgaben.":"Clasificarea și un biomarker predictiv unic sunt două sarcini diferite.","FFPE-Resektat, ausreichender Tumoranteil.":"Piesă de rezecție FFPE, cu conținut tumoral adecvat.","für beide Verfahren ausreichend.":"suficient pentru ambele metode.","Lokale Validierung":"Validare locală","Bisulfit-basierte Zielmethode ist für MGMT klinisch validiert; das Array wird im Labor primär für CNS-Klassifikation eingesetzt.":"Metoda țintită bazată pe bisulfit este validată clinic pentru MGMT; array-ul este utilizat în acest laborator în principal pentru clasificarea tumorilor SNC.","Array wäre teurer/langsamer und beantwortet hier keine offene Klassifikationsfrage.":"Array-ul ar fi mai scump/mai lent și nu ar răspunde aici niciunei întrebări de clasificare nerezolvate.","Zielgerichtete validierte MGMT-Methylierungsanalyse":"Analiză țintită validată a metilării MGMT","Zielgerichtete Bisulfit-Methylierungsanalyse":"Analiză țintită a metilării cu bisulfit","MGMT-Promotor-Methylierung ist mit der lokal validierten zielgerichteten Methode nachweisbar und für die konkrete prädiktive Fragestellung berichtbar.":"Metilarea promotorului MGMT este detectabilă prin metoda țintită validată local și poate fi raportată pentru întrebarea predictivă concretă.","CNS-Methylierungsclassifier":"Clasificator de metilare SNC","Das genomeweite Profil bestätigt die bereits gesicherte Tumorklasse, ist in diesem Labor aber nicht als Ersatz für die klinische MGMT-Einzelmarkerbestimmung validiert.":"Profilul la nivel genomic confirmă clasa tumorală deja stabilită, dar în acest laborator nu este validat ca înlocuitor al determinării clinice MGMT ca marker unic.","Zusätzliche Sequenzierungsbreite beantwortet die epigenetische MGMT-Frage nicht.":"O secvențiere mai largă nu răspunde întrebării epigenetice privind MGMT.","Tumorentität bereits integriert gesichert.":"Entitatea tumorală este deja stabilită prin diagnosticul integrat.","Mehr Omik ist nicht automatisch die passendere Methode; Scope und Validierung müssen zur Frage passen.":"Mai multă omică nu înseamnă automat metoda mai potrivită; domeniul și validarea trebuie să corespundă întrebării.","Da die Tumorentität bereits sicher klassifiziert ist und die konkrete Frage MGMT-Promotor-Methylierung lautet, ist die lokal validierte zielgerichtete Bisulfitmethode die passende Untersuchung. Ein genomeweiter Methylierungsclassifier wäre für eine offene Entitätsfrage sinnvoll, ist hier aber unnötig und im lokalen Workflow kein validierter Ersatz für den prädiktiven Einzelmarker.":"Deoarece entitatea tumorală este deja clasificată cu certitudine, iar întrebarea concretă este metilarea promotorului MGMT, metoda țintită cu bisulfit validată local este investigația potrivită. Un clasificator de metilare la nivel genomic ar fi util pentru o entitate neclară, dar aici este inutil și nu reprezintă în fluxul local un înlocuitor validat pentru biomarkerul predictiv unic.","Teilbefund: Lokaler prädiktiver Marker und globale epigenetische Klassifikation sind unterschiedliche diagnostische Aufgaben.":"Rezultat parțial: un biomarker predictiv local și clasificarea epigenetică globală sunt sarcini diagnostice diferite.","Fragestellung vor Technologie wählen":"Alegeți întrebarea clinică înaintea tehnologiei","lokale klinische Validierung berücksichtigen":"luați în considerare validarea clinică locală","Classifier für Klassifikation, nicht automatisch für jeden Methylierungsmarker":"clasificator pentru clasificare, nu automat pentru fiecare biomarker de metilare","Falschaussage: genomeweit ist immer klinisch besser":"Afirmație falsă: analiza la nivel genomic este întotdeauna mai bună clinic","Optimale Lösung: gesicherte Diagnose respektieren und die offene MGMT-Frage mit der dafür validierten zielgerichteten Methylierungsmethode beantworten.":"Soluția optimă: respectați diagnosticul stabilit și răspundeți întrebării MGMT deschise cu metoda țintită de metilare validată în acest scop.","MGMT":"MGMT","Bisulfit":"Bisulfit","CNS":"SNC","Nicht jedes Methylom braucht ein Methylom":"Nu orice întrebare privind metilarea necesită un metilom","Neuropathologie / Methodenauswahl":"Neuropatologie / selectarea metodei","Zielgerichtete Methylierungsanalyse von genomeweiter Klassifikation unterscheiden.":"Distingeți analiza țintită a metilării de clasificarea la nivel genomic.","Methodenumfang nicht mit klinischer Eignung gleichsetzen.":"Nu echivalați amploarea metodei cu adecvarea clinică.","Lokale Validierung und Intended Use in die Auswahl integrieren.":"Integrați validarea locală și utilizarea prevăzută în alegerea testului.","Bei bereits gesicherter Entität unnötige Classifier-Diagnostik vermeiden.":"Evitați diagnosticul inutil cu clasificator atunci când entitatea este deja stabilită.","Die Diagnose steht. Die einzige offene Frage lautet MGMT. Trotzdem liegt im Warenkorb ein genomeweites Methylierungsarray – weil „mehr Daten“ intuitiv nach „mehr Sicherheit“ klingt.":"Diagnosticul este stabilit. Singura întrebare deschisă este MGMT. Totuși, în coș se află un array de metilare la nivel genomic, deoarece „mai multe date” sună intuitiv ca „mai multă certitudine”.","69-jähriger Patient mit integriert gesichertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung ist ausschließlich der MGMT-Promotor-Methylierungsstatus offen. Das Labor hat dafür eine validierte zielgerichtete Bisulfitmethode; der CNS-Classifier ist für Entitätsklassifikation validiert.":"Pacient de 69 de ani cu glioblastom confirmat prin diagnostic integrat, IDH wild-type. Pentru planificarea tratamentului rămâne deschis exclusiv statusul metilării promotorului MGMT. Laboratorul dispune pentru aceasta de o metodă țintită validată cu bisulfit; clasificatorul SNC este validat pentru clasificarea entității.","Frage vor Plattform":"Întrebarea înaintea platformei","MGMT-Status ist eine fokale Biomarkerfrage, Tumorklassifikation eine globale Musterfrage.":"Statusul MGMT este o întrebare focală de biomarker; clasificarea tumorală este o întrebare privind un tipar global.","Testscope muss die Fragestellung spiegeln.":"Domeniul testului trebuie să reflecte întrebarea.","Validierung schlägt Prestige":"Validarea primează asupra prestigiului","Ein technisch komplexeres Verfahren ist nicht automatisch für jeden klinischen Output validiert.":"O metodă tehnic mai complexă nu este automat validată pentru fiecare rezultat clinic.","Intended Use ist Teil der Methode.":"Utilizarea prevăzută face parte din metodă.","Materialökonomie":"Economia materialului","Unnötige Omik verbraucht Zeit, Geld und ggf. Material.":"Omica inutilă consumă timp, bani și posibil material.","Effizienz ist diagnostische Qualität.":"Eficiența este parte a calității diagnostice.","Entitätsdiagnose":"Diagnosticul entității","bereits integriert gesichert":"deja stabilit prin diagnostic integrat","Lokaler Workflow":"Flux local de lucru","zielgerichtete Bisulfitmethode klinisch validiert":"metodă țintită cu bisulfit validată clinic","Ausreichendes Material.":"Material adecvat.","Kein Klassifikationsproblem.":"Nu există o problemă de clasificare.","Das Array ist lokal nicht als direkter Ersatz für die MGMT-Einzelmarkerfreigabe validiert.":"Array-ul nu este validat local ca înlocuitor direct pentru raportarea MGMT ca marker unic.","Welche Methode passt zur isolierten MGMT-Frage bei bereits gesicherter Glioblastomdiagnose am besten?":"Ce metodă se potrivește cel mai bine întrebării izolate privind MGMT atunci când diagnosticul de glioblastom este deja stabilit?","Die dafür lokal validierte zielgerichtete Bisulfit-Methylierungsanalyse.":"Analiza țintită a metilării cu bisulfit validată local.","Zwingend genomeweiter Classifier.":"Clasificator obligatoriu la nivel genomic.","Breites DNA-NGS.":"NGS ADN extins.","FISH.":"FISH.","Der klinische Output ist ein definierter lokaler Methylierungsmarker.":"Rezultatul clinic este un biomarker local definit de metilare.","Wann wäre der CNS-Methylierungsclassifier besonders sinnvoll?":"Când este deosebit de util clasificatorul de metilare SNC?","Bei diagnostisch unklarer Tumorentität, wenn ein genomeweites Muster die integrierte Klassifikation unterstützen kann.":"În cazul unei entități tumorale neclare din punct de vedere diagnostic, când un tipar la nivel genomic poate susține clasificarea integrată.","Bei jedem MGMT-Auftrag unabhängig von Diagnose.":"Pentru fiecare solicitare MGMT indiferent de diagnostic.","Zur AML-MRD.":"Pentru MRD în AML.","Für Keimbahndiagnostik.":"Pentru diagnosticul germinal.","Classifier und Einzelmarker haben unterschiedliche Intended Uses.":"Clasificatorul și biomarkerul unic au utilizări prevăzute diferite.","Warum darf ein Array nicht automatisch den lokal validierten MGMT-Test ersetzen?":"De ce nu ar trebui ca un array să înlocuiască automat testul MGMT validat local?","Weil klinische Freigabe die validierte Performance für genau diesen Output voraussetzt.":"Deoarece raportarea clinică necesită performanță validată exact pentru acel rezultat.","Weil Arrays grundsätzlich ungenau sind.":"Deoarece array-urile sunt în principiu inexacte.","Weil Arrays keine DNA messen.":"Deoarece array-urile nu măsoară ADN.","Weil Methylierungsarrays nie diagnostisch genutzt werden.":"Deoarece array-urile de metilare nu sunt utilizate niciodată în diagnostic.","Die Aussage richtet sich gegen ungeprüften Methodenwechsel, nicht gegen Arrays an sich.":"Ideea este evitarea unei schimbări nevalidate de metodă, nu respingerea array-urilor în sine.","Das Array bestätigt erwartungsgemäß die Tumorklasse, liefert aber keinen lokal validierten MGMT-Report. Was war der Fehler?":"Array-ul confirmă clasa tumorală așteptată, dar nu oferă un raport MGMT validat local. Care a fost eroarea?","Eine globale Klassifikationsplattform wurde für eine fokale prädiktive Frage eingesetzt, ohne passenden validierten Output.":"A fost utilizată o platformă globală de clasificare pentru o întrebare predictivă focală, fără un rezultat validat corespunzător.","Methylierungsclassifier sind grundsätzlich nutzlos.":"Clasificatoarele de metilare sunt în principiu inutile.","Es gibt keinen Unterschied.":"Nu există nicio diferență.","Technische Information und klinisch validierter Output sind nicht identisch.":"Informația tehnică și un rezultat validat clinic nu sunt identice.","Wählen Sie die Methylierungsmethode passend zur konkreten klinischen Frage.":"Alegeți metoda de metilare în funcție de întrebarea clinică specifică.","Prüfen, ob die Tumorentität bereits gesichert ist.":"Verificați dacă entitatea tumorală este deja stabilită.","Offene Frage als MGMT-Einzelmarker definieren.":"Definiți întrebarea deschisă ca o întrebare MGMT de marker unic.","Lokal validierten Zielassay verwenden.":"Utilizați testul țintit validat local.","Classifier nur bei echter globaler Klassifikationsfrage einsetzen.":"Utilizați clasificatorul numai atunci când există o întrebare reală de clasificare globală.","Intended Use im Befund transparent halten.":"Mențineți utilizarea prevăzută transparentă în raport.","Wenn ein Labor einen arraybasierten MGMT-Algorithmus spezifisch klinisch validiert hat, kann dieser lokal geeignet sein; der Fall lehrt Scope/Validierung, keine universelle Plattformhierarchie.":"Dacă un laborator a validat clinic în mod specific un algoritm MGMT bazat pe array, acesta poate fi adecvat local; cazul explică domeniul/validarea, nu o ierarhie universală a platformelor.","Mehr Daten = besser":"Mai multe date = mai bine","Ignoriert Fragestellung und Validierung.":"Ignoră întrebarea clinică și validarea.","Classifier nie verwenden":"Nu utilizați niciodată un clasificator","Bei unklaren CNS-Tumoren kann er sehr wertvoll sein.":"Poate fi foarte valoros în tumorile SNC cu diagnostic neclar.","NGS für MGMT-Methylierung":"NGS pentru metilarea MGMT","Sequenzvarianten beantworten die epigenetische Frage nicht.":"Variantele de secvență nu răspund întrebării epigenetice.","Das teurere Ergebnis beantwortet die falsche Frage":"Rezultatul mai scump răspunde întrebării greșite","Der Classifier bestätigt nur die bereits bekannte Tumorklasse; die klinisch offene MGMT-Frage bleibt ohne lokal validierten Einzelmarkeroutput bestehen.":"Clasificatorul confirmă doar clasa tumorală deja cunoscută; întrebarea clinică deschisă privind MGMT rămâne fără răspuns în absența unui rezultat de marker unic validat local.","Der Fall verschiebt Methodenauswahl von Technologieprestige zu Intended Use.":"Cazul mută selecția metodei de la prestigiul tehnologiei către utilizarea prevăzută.","Zielmarker passend getestet":"Marker țintă testat corespunzător","MGMT mit validierter Zielmethode berichtet.":"MGMT raportat prin metoda țintită validată.","Effizient und klinisch passend.":"Eficient și adecvat clinic.","Classifier ohne offene Klassifikationsfrage":"Clasificator fără o întrebare deschisă de clasificare","Mehr Daten, aber falscher primärer Output.":"Mai multe date, dar rezultatul primar greșit.","Scope-Mismatch.":"Nepotrivire de domeniu.","Epigenetische Frage bleibt offen.":"Întrebarea epigenetică rămâne nerezolvată.","Methodenfehler.":"Eroare de metodă.","isolierte validierte Einzelmarkerfrage":"întrebare izolată validată de marker unic","zielgerichteten validierten Assay bevorzugen":"preferați testul țintit validat","globale Omik nur bei zusätzlicher passender Fragestellung.":"omică globală numai dacă există o întrebare suplimentară adecvată.","Fragestellung bestimmt Methodenumfang.":"Întrebarea clinică determină domeniul metodei.","Methylierungsclassifier und lokaler Bisulfitassay sind nicht austauschbar.":"Clasificatorul de metilare și testul local cu bisulfit nu sunt interschimbabile.","Intended Use und lokale Validierung gehören zur klinischen Interpretation.":"Utilizarea prevăzută și validarea locală fac parte din interpretarea clinică.","Bei gesichertem Glioblastom und isolierter MGMT-Frage ist die lokal validierte zielgerichtete Methylierungsanalyse angemessen; ein Classifier ist kein automatischer Ersatz.":"Într-un glioblastom stabilit și cu o întrebare izolată privind MGMT, analiza țintită de metilare validată local este adecvată; un clasificator nu reprezintă un înlocuitor automat.","Methodenscope":"Domeniul metodei","Validierung":"Validare","Methylierungsdiagnostik":"Diagnostic prin metilare","Wann ist ein CNS-Classifier wirklich diagnostisch entscheidend?":"Când este un clasificator SNC cu adevărat decisiv pentru diagnostic?","Wie validiert man einen MGMT-Assay?":"Cum validați un test MGMT?","Wann kann ein Array mehrere Outputs klinisch tragen?":"Când poate un array susține mai multe rezultate clinice?","Twist: globale Plattform beantwortet lokale Frage nicht automatisch":"Twist: o platformă globală nu răspunde automat unei întrebări locale","Intended Use vor Omikbreite":"Utilizarea prevăzută înaintea amplorii omice","Referenzpfad: klinische Frage → validierter Output → Methode":"Calea de referință: întrebare clinică → rezultat validat → metodă","EWSR1-FISH positiv: schneller Rearrangementnachweis, aber noch keine Entität":"FISH EWSR1 pozitiv: detectare rapidă a rearanjării, dar încă nu o entitate","Amplifikation/Fusion: FISH als sch…":"Amplificare/fuziune: FISH ca supliment rapid…","Sarkomzentrum / Referenzpathologie":"Centru de sarcoame / anatomie patologică de referință","32-jährige Patientin mit einem tiefen Weichteiltumor am Fuß. Morphologisch monomorpher Tumor; EWSR1-Break-apart-FISH wird wegen Zeitdruck früh durchgeführt und ist positiv.":"Pacientă de 32 de ani cu o tumoră profundă de țesuturi moi la nivelul piciorului. Morfologic, tumora este monomorfă; din cauza presiunii de timp, FISH break-apart EWSR1 se efectuează precoce și este pozitiv.","Darf daraus unmittelbar „Ewing-Sarkom“ werden oder braucht es partner-/transkriptspezifische Auflösung?":"Se poate concluziona imediat „sarcom Ewing” sau este necesară clarificarea specifică a partenerului/transcriptului?","Neoadjuvante Strategie wird in wenigen Tagen diskutiert.":"Strategia neoadjuvantă va fi discutată în câteva zile.","Monomorphe Zellen, aber nicht klassisch genug für eine alleinige Ewing-Diagnose.":"Celule monomorfe, dar nu suficient de clasice pentru un diagnostic de Ewing de sine stătător.","EWSR1-Break-apart positiv.":"EWSR1 break-apart pozitiv.","Ein Gen-Rearrangement wird mit einer bestimmten Tumorentität gleichgesetzt.":"O rearanjare genică este echivalată cu o anumită entitate tumorală.","FISH als schnellen, robusten, aber informationsbegrenzten Test einordnen.":"Încadrați FISH ca test rapid și robust, dar cu informație limitată.","Melaninarm, nested/solid; immunhistochemischer Kontext nicht eindeutig für Ewing.":"Sărac în melanină, pattern nested/solid; contextul imunohistochimic nu este fără echivoc pentru Ewing.","EWSR1 rearrangiert.":"EWSR1 rearanjat.","Welcher Partner und welche Transkriptfusion liegt vor?":"Ce partener și ce transcript de fuziune sunt prezente?","EWSR1-Rearrangements kommen in mehreren Tumorentitäten vor.":"Rearanjările EWSR1 apar în multiple entități tumorale.","FFPE-Biopsie; RNA ausreichend.":"Biopsie FFPE; ARN adecvat.","schnell verfügbar und technisch robust.":"disponibil rapid și robust tehnic.","Targeted RNA-NGS verfügbar.":"NGS ARN țintit disponibil.","Partnerbestimmung kann die Entitätsdiagnose entscheidend verändern.":"Identificarea partenerului poate schimba decisiv diagnosticul entității.","Rearrangement schnell/orthogonal erfassen":"Detectați rearanjarea rapid/ortogonal","Fusionspartner/Transkript klären":"Clarificați partenerul/transcriptul fuziunii","Break-apart-FISH":"FISH break-apart","EWSR1-Break-apart positiv: ein EWSR1-Rearrangement ist nachgewiesen, die Partneridentität und damit die genaue Entität sind dadurch nicht allein definiert.":"EWSR1 break-apart pozitiv: este demonstrată o rearanjare EWSR1, dar identitatea partenerului și, prin urmare, entitatea exactă nu sunt definite doar prin acest rezultat.","RNA-NGS weist EWSR1::ATF1 nach und unterstützt im passenden morphologisch-immunhistochemischen Kontext die Diagnose eines Clear-Cell-Sarkoms statt eines Ewing-Sarkoms.":"NGS ARN detectează EWSR1::ATF1 și, în contextul morfologic-imunohistochimic adecvat, susține diagnosticul de sarcom cu celule clare în locul sarcomului Ewing.","Zusatzvarianten tragen weniger zur Kernfrage bei als die direkte Partnerbestimmung der Fusion.":"Variantele suplimentare contribuie mai puțin la întrebarea centrală decât identificarea directă a partenerului de fuziune.","schneller Rearrangementnachweis, aber keine universelle Entitätsdefinition.":"detectare rapidă a rearanjării, dar fără definiție universală a entității.","Gen-Rearrangement und Fusionspartner müssen im morphologischen Kontext interpretiert werden.":"Rearanjarea genică și partenerul de fuziune trebuie interpretate în context morfologic.","EWSR1-Break-apart-FISH ist ein sinnvoller schneller Nachweis eines Rearrangements, beweist aber nicht automatisch ein Ewing-Sarkom. Die RNA-basierte Partnerbestimmung zeigt EWSR1::ATF1 und verschiebt die integrierte Diagnose im passenden Kontext zu einem Clear-Cell-Sarkom. FISH bleibt wertvoll – aber seine Aussagegrenze muss respektiert werden.":"FISH break-apart EWSR1 este un test rapid util pentru detectarea unei rearanjări, dar nu demonstrează automat un sarcom Ewing. Identificarea partenerului pe bază de ARN evidențiază EWSR1::ATF1 și deplasează diagnosticul integrat, în contextul adecvat, către sarcomul cu celule clare. FISH rămâne valoros, dar limitele interpretării sale trebuie respectate.","Teilbefund: Ein positiver Break-apart-FISH beantwortet „ist das Gen rearrangiert?“, nicht immer „welche Fusion/Entität liegt vor?“.":"Rezultat parțial: un FISH break-apart pozitiv răspunde la „gena este rearanjată?”, nu întotdeauna la „ce fuziune/entitate este prezentă?”.","FISH-Stärke und -Grenze benennen":"Precizați punctul forte și limita FISH","Partnerbestimmung bei entitätsrelevanter Frage ergänzen":"Adăugați identificarea partenerului atunci când este relevantă pentru diagnosticul entității","Molekularbefund in Morphologie/IHC integrieren":"Integrați rezultatul molecular cu morfologia/IHC","Falschaussage: EWSR1-FISH positiv = Ewing-Sarkom":"Afirmație falsă: FISH EWSR1 pozitiv = sarcom Ewing","Optimale Lösung: FISH als schnellen Rearrangementnachweis nutzen, aber bei nicht entitätsspezifischem Genereignis den Partner mit RNA-NGS bestimmen und integriert diagnostizieren.":"Soluția optimă: utilizați FISH pentru detectarea rapidă a rearanjării, dar dacă evenimentul genic nu este specific unei entități, determinați partenerul prin NGS ARN și formulați un diagnostic integrat.","EWSR1":"EWSR1","Sarcoma":"Sarcom","FISH positiv – Diagnose noch offen":"FISH pozitiv – diagnosticul rămâne deschis","Sarkompathologie / FISH / RNA-Fusion":"Patologia sarcoamelor / FISH / fuziune ARN","Break-apart-FISH als schnellen Rearrangementnachweis korrekt einordnen.":"Încadrați corect FISH break-apart ca test rapid pentru rearanjare.","Nicht entitätsspezifische Rearrangements nicht überinterpretieren.":"Nu supra-interpretați rearanjările care nu sunt specifice unei entități.","RNA-NGS zur Partner-/Transkriptbestimmung nutzen.":"Utilizați NGS ARN pentru identificarea partenerului/transcriptului.","Morphologie, IHC, FISH und RNA integriert bewerten.":"Evaluați integrat morfologia, IHC, FISH și ARN.","Der FISH ist positiv. EWSR1 rearrangiert. Im ersten Moment klingt das wie die Diagnose – bis man sich erinnert, dass EWSR1 in mehreren völlig unterschiedlichen Tumoren rearrangiert sein kann.":"FISH este pozitiv. EWSR1 este rearanjat. La început pare că acesta este diagnosticul, până când vă amintiți că EWSR1 poate fi rearanjat în mai multe tumori complet diferite.","32-jährige Patientin mit Weichteiltumor am Fuß. EWSR1-Break-apart-FISH ist positiv, die Morphologie aber nicht klassisch für Ewing. RNA ist ausreichend für Partnerbestimmung.":"Pacientă de 32 de ani cu tumoră de țesuturi moi la nivelul piciorului. FISH break-apart EWSR1 este pozitiv, dar morfologia nu este clasică pentru Ewing. ARN este adecvat pentru identificarea partenerului.","FISH beantwortet eine enge Frage":"FISH răspunde unei întrebări restrânse","Break-apart: Rearrangement ja/nein.":"Break-apart: rearanjare da/nu.","Partner und Transkript bleiben oft offen.":"Partenerul și transcriptul rămân adesea neclarificate.","Genereignis ist nicht immer entitätsspezifisch":"Evenimentul genic nu este întotdeauna specific unei entități","EWSR1 kann verschiedene Fusionspartner und Tumorentitäten haben.":"EWSR1 poate avea diferiți parteneri de fuziune și poate apărea în entități tumorale diferite.","Molekularer Befund braucht Kontext.":"Un rezultat molecular necesită context.","RNA löst die Partnerfrage":"ARN clarifică întrebarea privind partenerul","Sequenzbasierter Transkriptnachweis kann die diagnostische Klasse entscheidend präzisieren.":"Detectarea transcriptului bazată pe secvențiere poate rafina decisiv clasa diagnostică.","FISH und RNA konkurrieren nicht, sie ergänzen sich.":"FISH și ARN nu concurează; se completează reciproc.","monomorph, aber nicht klassisch Ewing":"monomorf, dar nu clasic pentru Ewing","EWSR1 break-apart positiv":"EWSR1 break-apart pozitiv","Zeitdruck macht FISH attraktiv.":"Presiunea de timp face FISH atractiv.","RNA-NGS ist innerhalb der diagnostischen Frist möglich.":"NGS ARN este posibil în intervalul de diagnostic.","Positives FISH darf nicht über seine validierte Zielaussage hinaus interpretiert werden.":"Un FISH pozitiv nu trebuie interpretat dincolo de afirmația-țintă validată.","Was beweist ein positiver EWSR1-Break-apart-FISH primär?":"Ce demonstrează în primul rând un FISH break-apart EWSR1 pozitiv?","Ein EWSR1-Rearrangement.":"O rearanjare EWSR1.","Immer ein Ewing-Sarkom.":"Întotdeauna sarcom Ewing.","Immer den exakten Fusionspartner.":"Întotdeauna partenerul exact de fuziune.","Quantitative Proteinexpression.":"Expresie proteică cantitativă.","Break-apart-FISH ist genbezogen, nicht zwingend partner- oder entitätsspezifisch.":"FISH break-apart este specific genei, nu neapărat partenerului sau entității.","Warum ist RNA-NGS bei atypischer Morphologie sinnvoll?":"De ce este util NGS ARN atunci când morfologia este atipică?","Zur Bestimmung des exprimierten Fusionspartners/Transkripts.":"Pentru identificarea partenerului/transcriptului de fuziune exprimat.","Weil es exakt dasselbe wie FISH misst.":"Deoarece măsoară exact același lucru ca FISH.","Nur zur Copy-number-Bestimmung.":"Doar pentru determinarea numărului de copii.","Nur für Keimbahn.":"Doar pentru testare germinală.","Die Partnerinformation kann die Diagnose präzisieren.":"Informația despre partener poate rafina diagnosticul.","Wie sollte ein Fusionsbefund diagnostisch verwendet werden?":"Cum trebuie utilizat diagnostic un rezultat de fuziune?","Mit Morphologie, IHC und klinischem Kontext integrieren.":"Integrați-l cu morfologia, IHC și contextul clinic.","Molekularer Befund ersetzt immer die Histologie.":"Un rezultat molecular înlocuiește întotdeauna histologia.","Molekulare Befunde sind bei Sarkomen unwichtig.":"Rezultatele moleculare sunt neimportante în sarcoame.","FISH entscheidet jede Entität allein.":"FISH stabilește singur orice entitate.","Entitätsdiagnostik ist integriert.":"Diagnosticul entității este integrat.","RNA zeigt EWSR1::ATF1. Was ändert sich?":"ARN arată EWSR1::ATF1. Ce se schimbă?","Im passenden Kontext unterstützt dies Clear-Cell-Sarkom statt einer vorschnellen Ewing-Diagnose.":"În contextul adecvat, acest rezultat susține sarcomul cu celule clare în locul unui diagnostic prematur de Ewing.","Es beweist weiterhin Ewing unabhängig vom Partner.":"Demonstrează în continuare Ewing indiferent de partener.","Der positive FISH war falsch.":"FISH pozitiv a fost greșit.","Partnerinformation ist bedeutungslos.":"Informația despre partener este lipsită de importanță.","Die Partneridentität kann die Entitätszuordnung entscheidend verändern.":"Identitatea partenerului poate schimba decisiv atribuirea entității.","Nutzen Sie FISH dort, wo er stark ist, und definieren Sie, wann Partnerbestimmung erforderlich ist.":"Utilizați FISH acolo unde este puternic și definiți când este necesară identificarea partenerului.","Morphologie und Prätestwahrscheinlichkeit erfassen.":"Evaluați morfologia și probabilitatea pre-test.","FISH als schnellen Rearrangementnachweis verwenden.":"Utilizați FISH ca test rapid pentru rearanjare.","Aussagegrenze explizit halten.":"Mențineți explicită limita de interpretare.","Bei entitätsrelevanter Partnerfrage RNA-NGS ergänzen.":"Adăugați NGS ARN atunci când identitatea partenerului este relevantă pentru entitate.","Integrierte Diagnose aus allen Ebenen formulieren.":"Formulați un diagnostic integrat din toate nivelurile.","Bei sehr charakteristischer Morphologie und entitätsspezifischem Rearrangement kann FISH ausreichend sein; das hängt von Gen, Tumorart und validiertem diagnostischem Kontext ab.":"În cazul unei morfologii foarte caracteristice și al unei rearanjări specifice entității, FISH poate fi suficient; aceasta depinde de genă, tipul tumoral și contextul diagnostic validat.","Break-apart = Partner bekannt":"Break-apart = partener cunoscut","FISH liefert diese Information häufig nicht.":"FISH adesea nu oferă această informație.","EWSR1 = Ewing":"EWSR1 = Ewing","EWSR1 ist nicht entitätsspezifisch.":"EWSR1 nu este specific unei entități.","FISH ist veraltet und nutzlos":"FISH este depășit și inutil","FISH kann schnell, robust und materialeffizient sehr wertvoll sein.":"FISH poate fi rapid, robust, eficient din punct de vedere al materialului și foarte valoros.","Der Partner kippt die Diagnose":"Partenerul schimbă diagnosticul","RNA zeigt EWSR1::ATF1 statt einer Ewing-typischen Fusion.":"ARN arată EWSR1::ATF1 în locul unei fuziuni tipice pentru Ewing.","FISH war korrekt positiv, aber die überzogene Interpretation wäre falsch gewesen.":"FISH a fost corect pozitiv, dar interpretarea exagerată ar fi fost greșită.","FISH + RNA integriert":"FISH + ARN integrat","Rearrangement schnell erkannt, Partner korrekt bestimmt, Diagnose präzisiert.":"Rearanjare detectată rapid, partener identificat corect, diagnostic rafinat.","Stärken beider Methoden genutzt.":"Au fost utilizate punctele forte ale ambelor metode.","Ewing nur aus EWSR1-FISH":"Ewing doar pe baza FISH EWSR1","Entität falsch überinterpretiert.":"Entitate supra-interpretată incorect.","Scope-Fehler.":"Eroare de domeniu.","FISH komplett verworfen":"FISH eliminat complet","Schnelle robuste Information unnötig verloren.":"Informație rapidă și robustă pierdută inutil.","positiver genbezogener FISH ohne entitätsspezifische Eindeutigkeit":"FISH gen-specific pozitiv fără caracter univoc pentru entitate","Partner-/Transkriptbestimmung erwägen":"luați în considerare identificarea partenerului/transcriptului","Diagnose nicht allein aus Gen-Rearrangement ableiten.":"nu derivați diagnosticul doar din rearanjarea genică.","FISH bleibt klinisch nützlich.":"FISH rămâne util clinic.","Aussagegrenze ist Teil der Methode.":"Limita de interpretare face parte din metodă.","Partnerinformation kann diagnostisch wichtiger sein als der reine Gen-Rearrangementnachweis.":"Informația despre partener poate fi diagnostic mai importantă decât simpla detectare a rearanjării genice.","EWSR1-FISH bestätigt ein Rearrangement, aber keine automatische Ewing-Diagnose; RNA-NGS zeigt EWSR1::ATF1 und präzisiert die Entität im morphologischen Kontext.":"FISH EWSR1 confirmă o rearanjare, dar nu diagnostichează automat Ewing; NGS ARN arată EWSR1::ATF1 și precizează entitatea în context morfologic.","FISH-Scope":"Domeniul FISH","Partnerbestimmung":"Identificarea partenerului","integrierte Sarkomdiagnostik":"Diagnostic integrat al sarcomului","Welche Break-apart-Sonden sind besonders entitätsspezifisch oder unspezifisch?":"Ce sonde break-apart sunt deosebit de specifice sau nespecifice unei entități?","Wann ist FISH bei schlechter RNA die beste Option?":"Când este FISH cea mai bună opțiune în cazul ARN de calitate slabă?","Wie formuliert man einen positiven FISH ohne Partner?":"Cum formulați un rezultat FISH pozitiv fără un partener cunoscut?","Twist: FISH korrekt, Interpretation fast falsch":"Twist: FISH corect, interpretarea aproape greșită","Gen-Rearrangement ≠ Entität":"Rearanjare genică ≠ entitate","Referenzpfad: FISH → Scope prüfen → RNA-Partner → integrieren":"Calea de referință: FISH → verificați domeniul → partener ARN → integrare","23 Seiten Multiomics: eine belastbare Kernaussage, viele Hypothesen":"23 de pagini de multiomică: un mesaj central robust, multe ipoteze","Multiomics-Bericht: viel Informati…":"Raport multiomic: multă informați…","Hepatobiliäres Tumorboard / Präzisionsonkologie":"Tumor board hepatobiliar / oncologie de precizie","59-jährige Patientin mit metastasiertem intrahepatischem Cholangiokarzinom. Ein externer Multiomics-Bericht umfasst DNA, RNA, Immunmarker und Proteinsignaturen auf 23 Seiten.":"Pacientă de 59 de ani cu colangiocarcinom intrahepatic metastatic. Un raport multiomic extern de 23 de pagini include ADN, ARN, markeri imunologici și semnături proteice.","Welche Befunde sind unmittelbar klinisch belastbar, welche nur biologischer Kontext und welche reine Hypothese?":"Ce constatări sunt imediat solide clinic, care reprezintă doar context biologic și care sunt doar ipoteze?","Das MTB hat sieben Minuten für die molekulare Kernaussage.":"Tumor board-ul are șapte minute pentru mesajul molecular central.","Pathogene IDH1 p.R132C-Mutation; keine FGFR2-Fusion im validierten Fusionsassay.":"Mutație patogenă IDH1 p.R132C; fără fuziune FGFR2 în testul de fuziune validat.","FGFR2-Expression deutlich erhöht; mehrere Pathway-Scores für MAPK/EMT.":"Expresie FGFR2 marcat crescută; mai multe scoruri de căi MAPK/EMT.","Immunprofil":"Profil imunologic","MSS, niedrige TMB; PD-L1 niedrig.":"MSS, TMB scăzut; PD-L1 scăzut.","Der visuell spektakulärste Omics-Score wird mit einem validierten prädiktiven Biomarker gleichgesetzt.":"Cel mai spectaculos scor omic vizual este echivalat cu un biomarker predictiv validat.","Intrahepatisches Cholangiokarzinom.":"Colangiocarcinom intrahepatic.","Molekulare Schlüsseldaten":"Date moleculare cheie","IDH1 pathogen; keine FGFR2-Fusion.":"IDH1 patogen; fără fuziune FGFR2.","Explorative Daten":"Date exploratorii","FGFR2-high expression, EMT-/MET-Signaturen.":"Expresie FGFR2 crescută, semnături EMT/MET.","Was gehört in die erste Zeile des Tumorboards?":"Ce trebuie să apară în prima linie a rezumatului pentru tumor board?","Mehrere Omics-Layer bereits erzeugt.":"Mai multe straturi omice au fost deja generate.","Problem":"Problemă","Nicht Datenmangel, sondern Evidenzpriorisierung.":"Nu lipsa datelor, ci prioritizarea dovezilor.","Zeit":"Timp","MTB-Kommunikation muss extrem komprimiert sein.":"Comunicarea în tumor board trebuie să fie extrem de concisă.","Keine weitere Messung nötig, bevor die vorhandenen Daten sauber hierarchisiert sind.":"Nu este necesară nicio măsurare suplimentară înainte ca datele existente să fie ierarhizate corect.","Multiomics-Evidenz priorisieren und verdichten":"Prioritizați și condensați dovezile multiomice","Multiomics-Kernaussage":"Mesaj central multiomic","Kernaussage: pathogene IDH1-Alteration als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. FGFR2-Überexpression sowie EMT/MET-Signaturen bleiben explorativ und dürfen nicht wie validierte prädiktive Targets kommuniziert werden.":"Mesaj central: alterare patogenă IDH1 ca biomarker tumoral stabilit; fără fuziune FGFR2. Supraexpresia FGFR2 și semnăturile EMT/MET rămân exploratorii și nu trebuie comunicate ca ținte predictive validate.","Noch breiteres Panel":"Panel și mai extins","Mehr Daten lösen die zentrale Aufgabe – Evidenzhierarchie und klare Kommunikation – nicht.":"Mai multe date nu rezolvă sarcina centrală: ierarhia dovezilor și comunicarea clară.","Informationsdichte":"Densitatea informației","Viele biologisch interessante Signale, aber nur wenige direkt handlungsleitende Befunde.":"Multe semnale biologic interesante, dar doar câteva constatări direct utile deciziei.","Multiomics braucht Evidenzhierarchie, nicht nur Datensynthese.":"Multiomica are nevoie de o ierarhie a dovezilor, nu doar de sinteza datelor.","Der Bericht wird auf eine belastbare klinische Kernaussage reduziert: pathogene IDH1-Veränderung als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression ist nicht gleichbedeutend mit einer FGFR2-Fusion, und EMT/MET-/Pathway-Signaturen bleiben ohne passende klinische Validierung explorativ. Das MTB erhält Evidenzstufen statt Datenrauschen.":"Raportul este redus la un mesaj clinic central robust: alterare patogenă IDH1 ca biomarker tumoral stabilit; fără fuziune FGFR2. Expresia crescută FGFR2 nu este echivalentă cu o fuziune FGFR2, iar semnăturile EMT/MET/căi rămân exploratorii fără validare clinică adecvată. Tumor board-ul primește niveluri de dovezi în loc de zgomot informațional.","Teilbefund: Multiomics ist nur dann klinisch nützlich, wenn validierte Biomarker, Kontextsignale und Hypothesen klar getrennt werden.":"Rezultat parțial: multiomica este utilă clinic numai atunci când biomarkerii validați, semnalele de context și ipotezele sunt clar separate.","Befunde nach klinischer Evidenz ordnen":"Ordonarea constatărilor după dovezile clinice","Expression nicht mit Fusion gleichsetzen":"Nu echivalați expresia cu fuziunea","explorative Signaturen als Hypothesen kennzeichnen":"Etichetați semnăturile exploratorii ca ipoteze","Falschaussage: stärkstes Heatmap-Signal = bestes Target":"Afirmație falsă: cel mai puternic semnal din heatmap = cea mai bună țintă","Optimale Lösung: aus vielen Daten eine kurze Evidenzhierarchie bauen – gesicherter Biomarker zuerst, relevante negative Befunde danach, explorative Omics klar als Hypothesen.":"Soluția optimă: construiți din multe date o ierarhie scurtă a dovezilor — mai întâi biomarkerul stabilit, apoi constatările negative relevante, iar omica exploratorie clar etichetată ca ipoteză.","Multiomics":"Multiomică","MTB-RES":"MTB-RES","23 Seiten auf drei Sätze reduzieren":"Reduceți 23 de pagini la trei propoziții","Präzisionsonkologie / MTB-Kommunikation":"Oncologie de precizie / comunicare în tumor board","Multiomics-Befunde nach klinischer Evidenz hierarchisieren.":"Ierarhizați constatările multiomice după dovezile clinice.","Genomische Alteration, Expression und Pathway-Signatur nicht miteinander gleichsetzen.":"Nu echivalați alterarea genomică, expresia și semnătura de cale.","Relevante Negativbefunde sichtbar halten.":"Păstrați vizibile constatările negative relevante.","Explorative Hypothesen klar von handlungsleitenden Biomarkern trennen.":"Separați clar ipotezele exploratorii de biomarkerii care ghidează decizia.","Eine präzise MTB-Kernaussage aus Datenfülle formulieren.":"Formulați un mesaj central precis pentru tumor board dintr-un raport bogat în date.","Der Report ist 23 Seiten lang. Das Tumorboard hat sieben Minuten. Die Aufgabe ist nicht, alles vorzulesen – sondern zu wissen, welche zwei Sätze wirklich eine Entscheidung tragen.":"Raportul are 23 de pagini. Tumor board-ul are șapte minute. Sarcina nu este să citiți totul cu voce tare, ci să știți care două propoziții susțin cu adevărat o decizie.","59-jährige Patientin mit intrahepatischem Cholangiokarzinom. DNA, RNA und weitere Omics-Layer liegen vor. Eine pathogene IDH1-Alteration ist klar, eine FGFR2-Fusion fehlt, während FGFR2-Expression und mehrere Pathway-Scores hoch sind.":"Pacientă de 59 de ani cu colangiocarcinom intrahepatic. Sunt disponibile ADN, ARN și straturi omice suplimentare. O alterare patogenă IDH1 este clară, nu se detectează nicio fuziune FGFR2, în timp ce expresia FGFR2 și mai multe scoruri de cale sunt crescute.","Evidenz vor Datenmenge":"Dovezile înaintea volumului de date","Ein validierter Biomarker wiegt klinisch mehr als viele explorative Signaturen.":"Un biomarker validat are o greutate clinică mai mare decât multe semnături exploratorii.","Informationsmenge ist keine Evidenzstufe.":"Cantitatea de informație nu reprezintă un nivel de dovezi.","Expression ≠ Fusion":"Expresie ≠ fuziune","Hohe FGFR2-mRNA ist biologisch interessant, aber nicht dasselbe wie ein nachgewiesenes FGFR2-Fusionsereignis.":"ARNm FGFR2 crescut este biologic interesant, dar nu este același lucru cu un eveniment de fuziune FGFR2 demonstrat.","Omics-Layer messen unterschiedliche Phänomene.":"Straturile omice măsoară fenomene diferite.","Negative Befunde können entscheidend sein":"Constatările negative pot fi decisive","„Keine FGFR2-Fusion“ verhindert ein falsches Target-Narrativ.":"„Fără fuziune FGFR2” previne un narativ fals de target.","Klinische Zusammenfassung braucht auch relevante Ausschlüsse.":"Un rezumat clinic are nevoie și de excluderi relevante.","IDH1 p.R132C pathogen":"IDH1 p.R132C patogen","keine FGFR2-Fusion":"fără fuziune FGFR2","FGFR2 hoch exprimiert; EMT/MET-Signaturen erhöht":"FGFR2 exprimat crescut; semnături EMT/MET crescute","Immunkontext":"Context imunologic","MSS, TMB niedrig, PD-L1 niedrig":"MSS, TMB scăzut, PD-L1 scăzut","Alle Daten bereits vorhanden.":"Toate datele sunt deja disponibile.","Keine akute Materialfrage.":"Nu există o problemă acută de material.","Limitierend ist die Evidenzinterpretation, nicht die Messkapazität.":"Limitarea este interpretarea dovezilor, nu capacitatea de măsurare.","Was gehört in die erste Zeile der MTB-Zusammenfassung?":"Ce trebuie să apară în prima linie a rezumatului pentru tumor board?","Der klinisch am besten validierte relevante Biomarker und seine konkrete Bedeutung.":"Biomarkerul relevant cel mai bine validat clinic și semnificația sa concretă.","Die stärkste Farbe der Heatmap.":"Cea mai intensă culoare din heatmap.","Alle 200 Signaturen alphabetisch.":"Toate cele 200 de semnături în ordine alfabetică.","Jede VUS vor gesicherten Befunden.":"Fiecare VUS înaintea constatărilor certe.","MTB-Kommunikation priorisiert klinische Evidenz.":"Comunicarea în tumor board prioritizează dovezile clinice.","Was bedeutet hohe FGFR2-Expression ohne nachgewiesene FGFR2-Fusion?":"Ce înseamnă expresia crescută FGFR2 fără o fuziune FGFR2 demonstrată?","Biologischer/explorativer Kontext, aber kein automatischer Ersatz für den validierten Fusionsbiomarker.":"Context biologic/exploratoriu, dar nu un înlocuitor automat pentru biomarkerul de fuziune validat.","Eine Fusion ist damit bewiesen.":"Prin aceasta este demonstrată o fuziune.","Target-Therapie ist allein dadurch zwingend.":"Terapia țintită este obligatorie doar pe această bază.","RNA ist grundsätzlich Artefakt.":"ARN este în principiu un artefact.","Expression und strukturelle Genfusion sind verschiedene Befundarten.":"Expresia și fuziunea genică structurală sunt tipuri diferite de constatări.","Warum ist „keine FGFR2-Fusion“ ein wichtiger Befund?":"De ce este „fără fuziune FGFR2” o constatare importantă?","Er verhindert, dass die hohe Expression fälschlich als etablierter Fusions-Targetkontext verkauft wird.":"Împiedică prezentarea falsă a expresiei crescute drept context stabilit de target prin fuziune.","Negative Befunde gehören nie ins MTB.":"Constatările negative nu au niciodată loc în tumor board.","Er hat keinerlei Interpretationswert.":"Nu are deloc valoare interpretativă.","Er macht IDH1 automatisch negativ.":"Face automat IDH1 negativ.","Relevante Negativbefunde begrenzen falsche Handlungsableitungen.":"Constatările negative relevante limitează concluziile false privind acționabilitatea.","Der Bericht rankt „FGFR pathway activation“ als stärkstes Signal. Was tun Sie?":"Raportul clasifică „activarea căii FGFR” drept cel mai puternic semnal. Ce faceți?","Als explorative Signatur kennzeichnen und hinter validierten molekularen Befunden priorisieren.":"Etichetați-l ca semnătură exploratorie și plasați-l după constatările moleculare validate.","Als stärkstes Target behandeln.":"Tratați-l ca cea mai puternică țintă.","Alle Omics-Daten verwerfen.":"Eliminați toate datele omice.","Eine FGFR2-Fusion daraus ableiten.":"Deduceți din acesta o fuziune FGFR2.","Pathway-Scores sind ohne entsprechende klinische Validierung Hypothesen, keine automatischen Companion Biomarker.":"Fără validare clinică corespunzătoare, scorurile de cale sunt ipoteze, nu biomarkeri companion automați.","Verdichten Sie den Multiomics-Bericht zu einer evidenzhierarchischen MTB-Kernaussage.":"Condensați raportul multiomic într-un mesaj central pentru tumor board ierarhizat după dovezi.","Validierte/etablierte Biomarker identifizieren.":"Identificați biomarkerii validați/stabiliți.","Relevante negative Befunde sichtbar machen.":"Faceți vizibile constatările negative relevante.","Expression, Fusion, Protein und Pathways als unterschiedliche Ebenen behandeln.":"Tratați expresia, fuziunea, proteina și căile ca niveluri diferite.","Explorative Signaturen kennzeichnen.":"Etichetați semnăturile exploratorii.","MTB-Aussage auf Entscheidung statt Dateninventar fokussieren.":"Concentrați afirmația pentru tumor board pe decizie, nu pe inventarul de date.","Explorative Omics können für Studienhypothesen oder Translation wertvoll sein; sie gehören nur nicht unmarkiert in dieselbe Evidenzstufe wie validierte klinische Biomarker.":"Omica exploratorie poate fi valoroasă pentru ipoteze de studiu sau cercetare translațională; doar că nu trebuie plasată, fără etichetare, la același nivel de dovezi cu biomarkerii clinici validați.","Heatmap-Tophit = Target":"Top hit heatmap = target","Visuelle Effektstärke ersetzt keine klinische Validierung.":"Mărimea efectului vizual nu înlocuiește validarea clinică.","Alles in einen Satz pressen":"Comprimați totul într-o singură propoziție","Verwischt Evidenzstufen.":"Estompează nivelurile de dovezi.","Exploratives komplett löschen":"Ștergeți complet datele exploratorii","Verliert wissenschaftlich wertvolle Hypothesen; besser klar labeln.":"Pierde ipoteze valoroase științific; este mai bine să fie etichetate clar.","Der lauteste Signalweg ist nicht die stärkste klinische Aussage":"Cea mai „zgomotoasă” cale nu este cea mai puternică afirmație clinică","FGFR2-Expression ist hoch, aber es gibt keine FGFR2-Fusion. Die belastbare Topline bleibt die pathogene IDH1-Alteration; Omics-Signaturen werden als explorativ eingeordnet.":"Expresia FGFR2 este crescută, dar nu există fuziune FGFR2. Mesajul principal robust rămâne alterarea patogenă IDH1; semnăturile omice sunt clasificate ca exploratorii.","Der Twist dreht die Priorität von Signalstärke zu Evidenzstärke.":"Twist-ul mută prioritatea de la intensitatea semnalului la forța dovezilor.","Klarer Biomarker, klarer Ausschluss, klar markierte Hypothesen.":"Biomarker clar, excludere clară, ipoteze etichetate clar.","MTB-taugliche Verdichtung.":"Condensare potrivită pentru tumor board.","Report vorgelesen":"Raport citit cu voce tare","Viele Daten, keine Entscheidung.":"Multe date, nicio decizie.","Informationsüberlastung.":"Supraîncărcare informațională.","FGFR2-expression als Fusion behandelt":"Expresia FGFR2 tratată ca fuziune","Explorativer Befund wird targetiert.":"Constatarea exploratorie este tratată ca target.","Layer-Verwechslung.":"Confuzie între niveluri.","Omics-Signal ohne validierten klinischen Biomarkerstatus":"Semnal omic fără statut validat de biomarker clinic","als explorativ/hypothesengenerierend kennzeichnen":"etichetați ca exploratoriu/generator de ipoteze","nicht auf gleiche Ebene wie etablierte prädiktive Marker stellen.":"nu plasați la același nivel cu markerii predictivi stabiliți.","Multiomics braucht Evidenzhierarchie.":"Multiomica are nevoie de o ierarhie a dovezilor.","Biologische Plausibilität ist nicht identisch mit klinischer Actionability.":"Plausibilitatea biologică nu este identică cu acționabilitatea clinică.","Gute MTB-Kommunikation ist selektiv und transparent.":"O bună comunicare în tumor board este selectivă și transparentă.","Kernaussage: pathogene IDH1-Alteration als belastbarer tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression und Pathway-Signaturen sind explorativ und nicht als validierte Targets zu überinterpretieren.":"Mesaj central: alterare patogenă IDH1 ca biomarker tumoral robust; fără fuziune FGFR2. Expresia crescută FGFR2 și semnăturile de cale sunt exploratorii și nu trebuie supra-interpretate ca ținte validate.","Evidenzpriorisierung":"Prioritizarea dovezilor","Omics-Layer":"Straturi omice","Wie viele Ebenen sollte ein MTB-Report zeigen?":"Câte niveluri ar trebui să arate un raport pentru tumor board?","Wie labelt man explorative Signaturen?":"Cum etichetați semnăturile exploratorii?","Welche negativen Befunde sind entscheidungsrelevant?":"Ce constatări negative sunt relevante pentru decizie?","Twist: stärkstes Signal ist nicht stärkste Evidenz":"Twist: cel mai puternic semnal nu este cea mai puternică dovadă","Referenzpfad: validiert → relevante Negative → explorativ":"Calea de referință: validat → negative relevante → exploratoriu","dna_rna_lung_combo":"Panel pulmonar combinat ADN/ARN","Resistenzdiagnostik bei Progress":"Testarea rezistenței la progresie","Gewebe-Rebiopsie bei negativer Liquid Biopsy":"Rebiopsie tisulară după o biopsie lichidă negativă","Liquid Biopsy richtig einordnen":"Interpretarea corectă a biopsiei lichide","Progressionspanel: erworbener Resistenzmechanismus wird plausibilisiert; Liquid Biopsy allein ist bei negativem Ergebnis nicht ausreichend.":"Panel la progresie: este susținut un mecanism de rezistență dobândită; o biopsie lichidă negativă singură nu este suficientă.","Rebiopsie liefert beurteilbares Tumormaterial für Resistenzanalyse.":"Rebiopsia furnizează material tumoral evaluabil pentru analiza rezistenței.","Negative Liquid Biopsy wird nur mit ctDNA-/Materialkontext interpretiert; Rebiopsie bleibt Option.":"O biopsie lichidă negativă este interpretată numai în contextul ctDNA și al adecvării probei; rebiopsia rămâne o opțiune.","Integrierte Interpretation vollständig: Liquid Biopsy negativ: reicht das oder Rebiopsie? Die gewählten Methoden beantworten die Kernfrage mit angemessener Aussagekraft und Limitationen.":"Interpretare integrată completă: biopsie lichidă negativă — este suficientă sau este necesară rebiopsia? Metodele selectate răspund întrebării centrale cu o putere de evaluare și limitări adecvate.","Teilbefund: Für die Kernentscheidung („Liquid Biopsy negativ: reicht das oder Rebiopsie?“) fehlen noch zentrale Bausteine oder die Methode ist zu eng gewählt.":"Rezultat parțial: pentru decizia centrală („Biopsie lichidă negativă: este suficientă sau este necesară rebiopsia?”) lipsesc încă elemente esențiale sau metoda aleasă este prea restrânsă.","Resistenzdiagnostik bei Progress in der MTB-Kernaussage korrekt einordnen":"Încadrarea corectă a testării rezistenței la progresie în mesajul central al MTB","Gewebe-Rebiopsie bei negativer Liquid Biopsy in der MTB-Kernaussage korrekt einordnen":"Încadrarea corectă a rebiopsiei tisulare după o biopsie lichidă negativă în mesajul central al MTB","Liquid Biopsy richtig einordnen in der MTB-Kernaussage korrekt einordnen":"Interpretarea corectă a biopsiei lichide în mesajul central al MTB","Optimale Lösung: Liquid Biopsy negativ: reicht das oder Rebiopsie? – mit fallgerechter Methodenkombination, Material-/QC-Bewertung und klarer MTB-Kommunikation.":"Soluție optimă: biopsie lichidă negativă — este suficientă sau este necesară rebiopsia? Utilizați o combinație de metode adecvată cazului, evaluați contextul probei/QC și comunicați clar concluzia în MTB.","RNA-Fusionsdiagnostik primär fehlt":"Lipsește testarea primară a fuziunilor prin ARN","entitätsfremde Tests gewählt":"Au fost selectate teste necorespunzătoare entității tumorale","nur Liquid Biopsy gewählt":"A fost selectată doar biopsia lichidă","Rebiopsie gewählt, aber MET/CNV/Transformation nicht bedacht":"A fost selectată rebiopsia, dar nu au fost luate în considerare MET/CNV/transformarea histologică","MTB Basics / Präanalytik":"Bazele MTB / Preanalitică","colon_ngs_panel":"Panel NGS pentru cancer colorectal","MTB Basics / Genominstabilität":"Bazele MTB / Instabilitate genomică","broad_pan_panel":"Panel pan-cancer extins","MTB Basics / Advanced":"Bazele MTB / Avansat","hoch.":"ridicat.","MTB / Molecular Diagnostics":"MTB / Diagnostic molecular","wildtyp":"tip sălbatic"},"el":{"ERBB2-VUS im RAS/BRAF-WT-mCRC: Genname ist noch kein Target":"VUS του ERBB2 σε mCRC RAS/BRAF-WT: το όνομα ενός γονιδίου δεν αποτελεί ακόμη θεραπευτικό στόχο","VUS im Onkogen":"VUS σε ογκογονίδιο","Initialer Auftrag":"Αρχικό αίτημα","Einsender":"Παραπέμπων","Gastroonkologie / Molekulares Tumorboard":"Γαστρεντερική ογκολογία / Μοριακό ογκολογικό συμβούλιο","Klinische Information":"Κλινικές πληροφορίες","63-jährige Patientin mit linksseitigem metastasiertem CRC und Progress nach mehreren Therapielinien. Ein externer NGS-Bericht markiert „ERBB2 altered“ prominent.":"Γυναίκα 63 ετών με αριστερό μεταστατικό CRC και πρόοδο μετά από πολλαπλές γραμμές θεραπείας. Εξωτερική αναφορά NGS επισημαίνει έντονα «ERBB2 altered». ","Fragestellung":"Κλινικό ερώτημα","Reicht eine seltene ERBB2-Missense-VUS als Grundlage für HER2-gerichtete Therapie?":"Αρκεί μια σπάνια missense VUS του ERBB2 για να τεκμηριώσει θεραπεία κατευθυνόμενη έναντι του HER2;","Zeitfenster":"Χρονικό πλαίσιο","Nächste Therapielinie soll im MTB diskutiert werden.":"Η επόμενη γραμμή θεραπείας πρόκειται να συζητηθεί στο μοριακό ογκολογικό συμβούλιο.","Anamnese und klinischer Kontext":"Ιστορικό και κλινικό πλαίσιο","Molekularer Kontext":"Μοριακό πλαίσιο","KRAS/NRAS/BRAF wildtyp, pMMR/MSS.":"KRAS/NRAS/BRAF wild type, pMMR/MSS.","Externer Report":"Εξωτερική αναφορά","Seltene ERBB2-Missense-Variante, VAF 18 %, Klassifikation VUS; im Summary trotzdem gelb als „potential target“ hervorgehoben.":"Σπάνια missense παραλλαγή ERBB2, VAF 18%, ταξινομημένη ως VUS· παρ’ όλα αυτά επισημαίνεται με κίτρινο στη σύνοψη ως «potential target». ","Didaktische Falle":"Διδακτική παγίδα","Genname, Datenbanktreffer und Actionability werden miteinander vermischt.":"Το όνομα του γονιδίου, το εύρημα σε βάση δεδομένων και η θεραπευτική αξιοποιησιμότητα συγχέονται μεταξύ τους.","Ziel":"Στόχος","Variante, Biomarker und klinische Evidenz getrennt bewerten.":"Αξιολογήστε χωριστά την παραλλαγή, τον βιοδείκτη και την κλινική τεκμηρίωση.","Histologie + Vorinformation":"Ιστολογία + προϋπάρχουσες πληροφορίες","Histologie":"Ιστολογία","Metastasiertes kolorektales Adenokarzinom.":"Μεταστατικό αδενοκαρκίνωμα παχέος εντέρου.","HER2-IHC":"IHC HER2","noch nicht erfolgt.":"δεν έχει ακόμη πραγματοποιηθεί.","ISH":"ISH","Offen":"Εκκρεμεί","Gibt es unabhängig von der VUS einen etablierten HER2-Biomarker?":"Υπάρχει καθιερωμένος βιοδείκτης HER2 ανεξάρτητα από τη VUS;","Materialprüfung":"Έλεγχος υλικού","Material":"Υλικό","FFPE-Metastase, ausreichend.":"Μετάσταση FFPE, επαρκές υλικό.","Tumoranteil":"Ποσοστό όγκου","ca. 55 %.":"περ. 55%.","NGS-QC":"QC NGS","Variante technisch robust detektiert.":"Η παραλλαγή ανιχνεύθηκε με υψηλή τεχνική αξιοπιστία.","Wichtig":"Σημαντικό","Technisch echt bedeutet nicht automatisch klinisch bedeutsam.":"Το ότι ένα εύρημα είναι τεχνικά πραγματικό δεν σημαίνει αυτομάτως ότι είναι κλινικά σημαντικό.","ERBB2-Variantenbewertung":"Αξιολόγηση παραλλαγής ERBB2","VUS-/Evidenzkurationsschritt":"Βήμα επιμέλειας VUS/τεκμηρίωσης","Unabhängigen HER2-Biomarker prüfen":"Αξιολογήστε ανεξάρτητο βιοδείκτη HER2","ERBB2-NGS":"NGS ERBB2","Seltene ERBB2-Missense-Variante, VAF 18 %, technisch robust; aktuelle Klassifikation VUS.":"Σπάνια missense παραλλαγή ERBB2, VAF 18%, τεχνικά αξιόπιστη· τρέχουσα ταξινόμηση: VUS.","VUS-Curation":"Επιμέλεια VUS","Keine ausreichende klinische Evidenz für prädiktive Actionability; einzelne präklinische Hinweise reichen nicht zur Hochstufung.":"Ανεπαρκής κλινική τεκμηρίωση για προγνωστική θεραπευτική αξιοποιησιμότητα· μεμονωμένα προκλινικά δεδομένα δεν επαρκούν για αναβάθμιση της ταξινόμησης.","HER2 IHC 1+, keine starke membranöse Überexpression.":"IHC HER2 1+, χωρίς έντονη μεμβρανική υπερέκφραση.","HER2-FISH/ISH":"FISH/ISH HER2","Keine ERBB2-Amplifikation.":"Δεν ανιχνεύεται ενίσχυση ERBB2.","Fehlentscheidung":"Λανθασμένη απόφαση","Eine direkte HER2-Therapieempfehlung allein aus einer VUS wäre ein Evidenz-Overcall.":"Άμεση σύσταση θεραπείας έναντι HER2 μόνο βάσει μιας VUS θα αποτελούσε υπερερμηνεία της τεκμηρίωσης.","Die VUS ist technisch real detektiert.":"Η VUS είναι τεχνικά πραγματική.","Kernaussage":"Κεντρικό μήνυμα","Technische Echtheit, Pathogenität und prädiktive Actionability sind drei getrennte Ebenen.":"Η τεχνική εγκυρότητα, η παθογονικότητα και η προγνωστική θεραπευτική αξιοποιησιμότητα είναι τρία διακριτά επίπεδα.","Die ERBB2-Variante ist technisch robust, aber klinisch weiterhin VUS und darf nicht als gesicherter prädiktiver Biomarker behandelt werden. HER2-IHC 1+ und fehlende ERBB2-Amplifikation liefern keinen unabhängigen etablierten HER2-Amplifikationskontext. Eine Therapieempfehlung allein aus der VUS wäre nicht evidenzbasiert.":"Η παραλλαγή ERBB2 είναι τεχνικά αξιόπιστη, αλλά κλινικά παραμένει VUS και δεν πρέπει να αντιμετωπίζεται ως καθιερωμένος προγνωστικός βιοδείκτης. Η IHC HER2 1+ και η απουσία ενίσχυσης ERBB2 δεν παρέχουν ανεξάρτητο καθιερωμένο πλαίσιο ενίσχυσης HER2. Θεραπευτική σύσταση μόνο βάσει της VUS δεν θα ήταν τεκμηριωμένη.","Teilbefund: Ein technisch echter Variantenfund ist ohne belastbare funktionelle/klinische Evidenz nicht automatisch actionable.":"Μερικό αποτέλεσμα: ένα τεχνικά γνήσιο εύρημα παραλλαγής δεν είναι αυτομάτως θεραπευτικά αξιοποιήσιμο χωρίς ισχυρή λειτουργική/κλινική τεκμηρίωση.","VUS klar als VUS benennen":"Χαρακτηρίστε σαφώς τη VUS ως VUS","technische Validität, Pathogenität und Actionability trennen":"διαχωρίστε την τεχνική εγκυρότητα, την παθογονικότητα και τη θεραπευτική αξιοποιησιμότητα","IHC/ISH als separaten Biomarkerpfad verstehen":"αντιληφθείτε την IHC/ISH ως ξεχωριστή οδό βιοδείκτη HER2","Falschaussage: ERBB2 steht im Genfeld, also ist HER2-Therapie indiziert":"Λανθασμένη δήλωση: το ERBB2 εμφανίζεται στο πεδίο γονιδίου, άρα ενδείκνυται θεραπεία HER2","Optimale Lösung: ERBB2-VUS nicht overcallen, unabhängige HER2-Biomarker separat prüfen und die Therapieaussage an Evidenz statt an Genname oder Datenbankfarbe koppeln.":"Βέλτιστη λύση: μην υπερερμηνεύετε τη VUS ERBB2, αξιολογήστε χωριστά ανεξάρτητους βιοδείκτες HER2 και βασίστε τη θεραπευτική δήλωση στην τεκμηρίωση και όχι στο όνομα του γονιδίου ή στο χρώμα της βάσης δεδομένων.","VUS":"VUS","ERBB2":"ERBB2","HER2":"HER2","Evidenz":"Τεκμηρίωση","MTB":"MTB","Deep Dive":"Deep Dive","Das gelbe „potential target“":"Το κίτρινο «potential target»","Molekulares Tumorboard / Varianteninterpretation":"Μοριακό ογκολογικό συμβούλιο / ερμηνεία παραλλαγών","VUS nicht als pathogene/actionable Variante berichten.":"Μην αναφέρετε μια VUS ως παθογόνο/θεραπευτικά αξιοποιήσιμη.","Technische Validität, biologische Pathogenität und klinische Prädiktion trennen.":"Διαχωρίστε την τεχνική εγκυρότητα, τη βιολογική παθογονικότητα και την κλινική πρόβλεψη.","IHC/ISH bei HER2 als eigenständigen Biomarkerpfad einordnen.":"Εντάξτε την IHC/ISH για HER2 ως ανεξάρτητη οδό βιοδείκτη.","Datenbank-/Software-Highlights nicht mit klinischer Evidenz verwechseln.":"Μην συγχέετε επισημάνσεις βάσεων δεδομένων/λογισμικού με κλινική τεκμηρίωση.","Im externen Report ist ERBB2 gelb hervorgehoben: „potential target“. In der Detailzeile steht jedoch schlicht VUS. Der Fall ist ein Test dafür, ob das Board die Farbe oder die Evidenz liest.":"Στην εξωτερική αναφορά, το ERBB2 επισημαίνεται με κίτρινο: «potential target». Στη γραμμή λεπτομερειών όμως αναγράφεται απλώς VUS. Η περίπτωση ελέγχει αν το συμβούλιο διαβάζει το χρώμα ή την τεκμηρίωση.","63-jährige Patientin mit RAS/BRAF-WT-mCRC. Eine seltene ERBB2-Missense-Variante ist technisch sicher detektiert, aber als VUS klassifiziert. Das Board soll entscheiden, ob daraus eine HER2-gerichtete Therapieaussage entsteht.":"Γυναίκα 63 ετών με mCRC RAS/BRAF-WT. Μια σπάνια missense παραλλαγή ERBB2 είναι τεχνικά ασφαλής αλλά ταξινομημένη ως VUS. Το συμβούλιο πρέπει να αποφασίσει αν αυτό στηρίζει θεραπευτική δήλωση έναντι HER2.","Drei Ebenen":"Τρία επίπεδα","Call echt? Variante pathogen? Befund prädiktiv?":"Πραγματικό call; Παθογόνος παραλλαγή; Προγνωστικό εύρημα;","Diese Ebenen dürfen nicht zusammenfallen.":"Αυτά τα επίπεδα δεν πρέπει να συγχέονται.","HER2 ist mehr als ein Genname":"Το HER2 είναι κάτι περισσότερο από το όνομα ενός γονιδίου","Amplifikation/Überexpression und einzelne Sequenzvarianten sind unterschiedliche Biomarker.":"Η ενίσχυση/υπερέκφραση και οι μεμονωμένες παραλλαγές αλληλουχίας είναι διαφορετικοί βιοδείκτες.","Methoden beantworten verschiedene Fragen.":"Οι μέθοδοι απαντούν σε διαφορετικά ερωτήματα.","Software ist keine Leitlinie":"Το λογισμικό δεν είναι κατευθυντήρια οδηγία","Ein automatisch hervorgehobener Datenbanktreffer kann evidenzarm sein.":"Ένα εύρημα βάσης δεδομένων που επισημαίνεται αυτόματα μπορεί να έχει ασθενή τεκμηρίωση.","Finale Interpretation bleibt fachlich verantwortlich.":"Η τελική ερμηνεία παραμένει επαγγελματική ευθύνη.","ERBB2-Variante":"Παραλλαγή ERBB2","VAF 18 %, technisch robust, Klassifikation VUS":"VAF 18%, τεχνικά αξιόπιστη, ταξινομημένη ως VUS","RAS/BRAF":"RAS/BRAF","MMR/MSI":"MMR/MSI","pMMR/MSS":"pMMR/MSS","Material ausreichend.":"Επαρκές υλικό.","Keine analytische Unsicherheit des Calls – die Unsicherheit ist interpretativ.":"Δεν υπάρχει αναλυτική αβεβαιότητα στο call· η αβεβαιότητα αφορά την ερμηνεία.","Der Fall verlangt keine Therapieempfehlung aus einem nicht etablierten VUS.":"Η περίπτωση δεν απαιτεί θεραπευτική σύσταση από μη καθιερωμένη VUS.","Was ist die korrekte Bedeutung einer technisch robusten ERBB2-VUS?":"Ποια είναι η σωστή σημασία μιας τεχνικά αξιόπιστης VUS του ERBB2;","Die Variante ist nach aktueller Evidenz nicht ausreichend als pathogen/prädiktiv klassifiziert.":"Με βάση την τρέχουσα τεκμηρίωση, η παραλλαγή δεν είναι επαρκώς ταξινομημένη ως παθογόνος/προγνωστική.","Jede ERBB2-Variante ist actionable.":"Κάθε παραλλαγή ERBB2 είναι θεραπευτικά αξιοποιήσιμη.","VUS bedeutet sicher benign.":"VUS σημαίνει οπωσδήποτε καλοήθης.","VUS bedeutet Keimbahn.":"VUS σημαίνει βλαστική παραλλαγή.","VUS beschreibt unzureichende Evidenz, nicht eine halbe Therapieindikation.":"Η VUS περιγράφει ανεπαρκή τεκμηρίωση, όχι «μισή» θεραπευτική ένδειξη.","Welche Ebenen müssen getrennt bewertet werden?":"Ποια επίπεδα πρέπει να αξιολογούνται χωριστά;","analytische Echtheit des Calls":"αναλυτική εγκυρότητα του call","Pathogenität/biologische Bedeutung":"παθογονικότητα/βιολογική σημασία","klinisch-prädiktive Evidenz":"κλινική προγνωστική τεκμηρίωση","Farbe im Software-Report":"χρώμα στην αναφορά λογισμικού","Der Software-Look ist keine Evidenzebene.":"Η εμφάνιση στο λογισμικό δεν αποτελεί επίπεδο τεκμηρίωσης.","HER2 IHC 1+ und keine ERBB2-Amplifikation: Was folgt daraus?":"IHC HER2 1+ και χωρίς ενίσχυση ERBB2: τι συμπεραίνουμε;","Es liegt kein unabhängiger etablierter Amplifikations-/Überexpressionsbefund vor, der die VUS „rettet“.":"Δεν υπάρχει ανεξάρτητο καθιερωμένο εύρημα ενίσχυσης/υπερέκφρασης που να «διασώζει» τη VUS.","Damit wird die VUS automatisch pathogen.":"Έτσι η VUS γίνεται αυτομάτως παθογόνος.","HER2-Therapie ist allein dadurch zwingend.":"Μόνο με βάση αυτό, η θεραπεία HER2 είναι υποχρεωτική.","IHC/ISH und Sequenzierung messen exakt dasselbe.":"Η IHC/ISH και η αλληλούχηση μετρούν ακριβώς το ίδιο πράγμα.","Die Methoden adressieren unterschiedliche Biomarker.":"Οι μέθοδοι αξιολογούν διαφορετικούς βιοδείκτες.","Eine Datenbank nennt einen präklinischen Zelllinienhinweis. Reicht das zur Therapieableitung?":"Μια βάση δεδομένων αναφέρει προκλινικό εύρημα σε κυτταρική σειρά. Αρκεί αυτό για θεραπευτική απόφαση;","Nein; präklinische Hinweise können Hypothesen stützen, ersetzen aber keine ausreichende klinische Evidenz für diese VUS.":"Όχι· τα προκλινικά δεδομένα μπορούν να στηρίξουν υποθέσεις, αλλά δεν υποκαθιστούν επαρκή κλινική τεκμηρίωση για αυτή τη VUS.","Ja, jeder präklinische Treffer macht eine VUS actionable.":"Ναι, κάθε προκλινικό εύρημα καθιστά μια VUS θεραπευτικά αξιοποιήσιμη.","Literatur ist grundsätzlich irrelevant.":"Η βιβλιογραφία είναι εξ ορισμού άσχετη.","Die Variante wird automatisch Tier I.":"Η παραλλαγή γίνεται αυτομάτως Tier I.","Evidenzhierarchie und variantenspezifische Daten müssen berücksichtigt werden.":"Πρέπει να λαμβάνονται υπόψη η ιεραρχία τεκμηρίωσης και τα δεδομένα ειδικά για την παραλλαγή.","Formulieren Sie eine MTB-Kernaussage, die den ERBB2-Fund korrekt einordnet, ohne ihn zu overcallen.":"Διατυπώστε βασικό μήνυμα για το MTB που εντάσσει σωστά το εύρημα ERBB2 χωρίς υπερερμηνεία.","Technische Echtheit bestätigen.":"Επιβεβαιώστε την τεχνική εγκυρότητα.","Aktuelle Variantenklassifikation übernehmen bzw. fachlich kuratieren.":"Υιοθετήστε ή επιμεληθείτε επιστημονικά την τρέχουσα ταξινόμηση της παραλλαγής.","Keine Pathogenität/Actionability aus dem Genname ableiten.":"Μην συμπεραίνετε παθογονικότητα/θεραπευτική αξιοποιησιμότητα από το όνομα του γονιδίου.","HER2-IHC/ISH als separaten Biomarkerpfad bewerten.":"Αξιολογήστε την IHC/ISH HER2 ως ξεχωριστή οδό βιοδείκτη.","VUS klar und nicht handlungsleitend kommunizieren; Re-Evaluation bei neuer Evidenz möglich.":"Επικοινωνήστε σαφώς ότι η VUS δεν καθοδηγεί δράση· επανεκτίμηση μπορεί να γίνει όταν προκύψουν νέα δεδομένα.","Studieneinschluss kann je nach Protokoll breitere molekulare Kriterien verwenden; das ist von einer etablierten Therapieempfehlung zu trennen.":"Ανάλογα με το πρωτόκολλο, η ένταξη σε μελέτη μπορεί να χρησιμοποιεί ευρύτερα μοριακά κριτήρια· αυτό πρέπει να διακρίνεται από καθιερωμένη θεραπευτική σύσταση.","Genname = Target":"Όνομα γονιδίου = στόχος","Ignoriert Variantenspezifität und Evidenz.":"Αγνοεί την ειδικότητα της παραλλαγής και την τεκμηρίωση.","VUS = benign":"VUS = καλοήθης","Unsicherheit wird fälschlich in Harmlosigkeit umgedeutet.":"Η αβεβαιότητα ερμηνεύεται λανθασμένα ως αβλαβής κατάσταση.","IHC/ISH macht Missense-VUS pathogen":"Η IHC/ISH καθιστά μια missense VUS παθογόνο","Unterschiedliche Biomarkerfragen werden vermischt.":"Συγχέονται διαφορετικά ερωτήματα βιοδεικτών.","Die Variante ist echt – und trotzdem kein Target":"Η παραλλαγή είναι πραγματική — και παρ’ όλα αυτά δεν είναι στόχος","Curation bestätigt die technische Echtheit, aber nicht die klinische Actionability. HER2-IHC/ISH liefern ebenfalls keinen unabhängigen etablierten HER2-Befund.":"Η επιμέλεια επιβεβαιώνει την τεχνική εγκυρότητα αλλά όχι την κλινική θεραπευτική αξιοποιησιμότητα. Ούτε η IHC/ISH HER2 παρέχει ανεξάρτητο καθιερωμένο εύρημα HER2.","Der Twist ist kein Laborfehler, sondern die Trennung von Detektion und Bedeutung.":"Η ανατροπή δεν είναι εργαστηριακό σφάλμα, αλλά ο διαχωρισμός της ανίχνευσης από τη σημασία.","VUS sauber begrenzt":"Ορθή οριοθέτηση της VUS","Technisch echt, klinisch unklar, kein Overcalling.":"Τεχνικά πραγματική, κλινικά ασαφής, χωρίς υπερερμηνεία.","Evidenzgerechte MTB-Kommunikation.":"Επικοινωνία MTB βασισμένη στην τεκμηρίωση.","Direkt HER2-Therapie":"Άμεση θεραπεία HER2","VUS wird wie ein etablierter Biomarker behandelt.":"Η VUS αντιμετωπίζεται σαν καθιερωμένος βιοδείκτης.","Kritischer Interpretationsfehler.":"Κρίσιμο σφάλμα ερμηνείας.","VUS verschwiegen":"VUS αποσιωπημένη","Unsicherheit wird nicht transparent kommuniziert.":"Η αβεβαιότητα δεν επικοινωνείται με διαφάνεια.","Besser klar benennen und begrenzen.":"Καλύτερα να αναφέρεται και να οριοθετείται σαφώς.","VUS ohne ausreichende prädiktive Evidenz":"VUS χωρίς επαρκή προγνωστική τεκμηρίωση","nicht als gesichertes Target formulieren":"μην τη διατυπώνετε ως καθιερωμένο στόχο","ggf. Re-Evaluation bei neuer Evidenz.":"εξετάστε επανεκτίμηση εάν προκύψουν νέα δεδομένα.","VUS ist eine Evidenzkategorie.":"Η VUS είναι κατηγορία τεκμηρίωσης.","Softwareannotation ersetzt keine fachliche Varianteninterpretation.":"Η σχολιασμένη πληροφορία λογισμικού δεν υποκαθιστά την επιστημονική ερμηνεία παραλλαγών.","Ein Gen kann mehrere völlig unterschiedliche Biomarkerarten tragen.":"Ένα γονίδιο μπορεί να φέρει πολλούς εντελώς διαφορετικούς τύπους βιοδεικτών.","ERBB2-VUS technisch bestätigt, jedoch ohne ausreichende klinisch-prädiktive Evidenz; HER2 IHC/ISH ohne unabhängigen positiven Biomarker. Keine etablierte Therapieableitung allein aus der VUS.":"Η VUS ERBB2 επιβεβαιώθηκε τεχνικά, αλλά χωρίς επαρκή κλινική προγνωστική τεκμηρίωση· IHC/ISH HER2 χωρίς ανεξάρτητο θετικό βιοδείκτη. Δεν προκύπτει καθιερωμένη θεραπευτική συνέπεια μόνο από τη VUS.","Evidenzhierarchie":"Ιεραρχία τεκμηρίωσης","Variantenspezifität":"Ειδικότητα παραλλαγής","MTB-Kommunikation":"Επικοινωνία MTB","Wann darf eine VUS reklassifiziert werden?":"Πότε μπορεί να επαναταξινομηθεί μια VUS;","Wie häufig sollte Re-Annotation erfolgen?":"Πόσο συχνά πρέπει να γίνεται επανασχολιασμός;","Wie verhindert man Software-bedingtes Overcalling?":"Πώς μπορεί να αποτραπεί η υπερερμηνεία που προκαλείται από λογισμικό;","Twist: technisch echt ≠ klinisch actionable":"Ανατροπή: τεχνικά πραγματικό ≠ κλινικά αξιοποιήσιμο","HER2-IHC/ISH und Sequenz-VUS getrennt":"IHC/ISH HER2 και VUS αλληλουχίας αξιολογούνται χωριστά","Referenzpfad: Call → Klassifikation → Evidenz → klinische Aussage":"Οδός αναφοράς: call → ταξινόμηση → τεκμηρίωση → κλινική δήλωση","ALK/ROS1/RET/NTRK-Fusionsverdacht bei jungem Nie-Raucher → FISH, RNA-NGS oder DNA-NGS?":"Υποψία σύντηξης ALK/ROS1/RET/NTRK σε νεαρή μη καπνίστρια → FISH, RNA-NGS ή DNA-NGS;","ALK/ROS1/RET/NTRK-Fusionsverdacht …":"Υποψία σύντηξης ALK/ROS1/RET/NTRK …","Thoraxonkologie / Molekulares Tumorboard":"Θωρακική ογκολογία / Μοριακό ογκολογικό συμβούλιο","42-jährige Patientin, Nie-Raucherin, metastasiertes pulmonales Adenokarzinom mit Leber- und Knochenmetastasen.":"Γυναίκα 42 ετών, μη καπνίστρια, με μεταστατικό πνευμονικό αδενοκαρκίνωμα με ηπατικές και οστικές μεταστάσεις.","Ein externes DNA-basiertes Panel meldet keinen therapierbaren Treiber. Ist die molekulare Abklärung damit abgeschlossen oder muss eine Fusionsdiagnostik ergänzt werden?":"Εξωτερικό panel βασισμένο σε DNA δεν αναφέρει θεραπευτικά αξιοποιήσιμο driver. Έχει ολοκληρωθεί ο μοριακός έλεγχος ή πρέπει να προστεθεί έλεγχος συντήξεων;","Die Erstlinientherapie soll im MTB in fünf Tagen festgelegt werden.":"Η θεραπεία πρώτης γραμμής πρόκειται να καθοριστεί στο μοριακό ογκολογικό συμβούλιο σε πέντε ημέρες.","Raucherstatus":"Καπνισματικό ιστορικό","Nie-Raucherin, keine relevante berufliche Exposition.":"Μη καπνίστρια, χωρίς σχετική επαγγελματική έκθεση.","Klinischer Verlauf":"Κλινική πορεία","ECOG 1, symptomatische ossäre Metastase, insgesamt aber klinisch stabil.":"ECOG 1, συμπτωματική οστική μετάσταση, αλλά συνολικά κλινικά σταθερή.","Vorbefund":"Προηγούμενο αποτέλεσμα","Externes DNA-NGS ohne EGFR-, KRAS-, BRAF-, MET-Exon-14- oder ERBB2-Alteration; der Bericht enthält keine belastbare Aussage zur RNA-basierten Fusionserfassung.":"Εξωτερικό DNA-NGS χωρίς αλλοίωση EGFR, KRAS, BRAF, MET exon 14 ή ERBB2· η αναφορά δεν παρέχει αξιόπιστη δήλωση για ανίχνευση συντήξεων μέσω RNA.","Entscheidungsdruck":"Πίεση λήψης απόφασης","Die Onkologie erwägt bereits eine nicht zielgerichtete Systemtherapie, falls kein Treiber gefunden wird.":"Η ογκολογική ομάδα εξετάζει ήδη μη στοχευμένη συστηματική θεραπεία εάν δεν βρεθεί driver.","HE":"H&E","Mäßig differenziertes pulmonales Adenokarzinom in einer Lebermetastasenbiopsie.":"Μέτρια διαφοροποιημένο πνευμονικό αδενοκαρκίνωμα σε βιοψία ηπατικής μετάστασης.","IHC":"IHC","TTF-1 und Napsin A positiv; p40 negativ. Die Morphologie und der klinische Kontext stützen einen pulmonalen Primarius.":"TTF-1 και Napsin A θετικά· p40 αρνητικό. Η μορφολογία και το κλινικό πλαίσιο υποστηρίζουν πνευμονική πρωτοπαθή εστία.","Biologischer Hinweis":"Βιολογική ένδειξη","Junges Alter und Nie-Raucherstatus erhöhen die Aufmerksamkeit für eine onkogene Treiberalteration, ersetzen aber keinen methodisch vollständigen Nachweis.":"Η νεαρή ηλικία και η απουσία καπνίσματος αυξάνουν την υποψία ογκογονικής driver αλλοίωσης, αλλά δεν υποκαθιστούν μεθοδολογικά πλήρη έλεγχο.","Offene Frage":"Ανοικτό ερώτημα","Wurden ALK-, ROS1-, RET- und NTRK-Fusionen mit einer dafür geeigneten Methode tatsächlich ausreichend ausgeschlossen?":"Έχουν πράγματι αποκλειστεί οι συντήξεις ALK, ROS1, RET και NTRK με κατάλληλη μέθοδο;","FFPE-Leberbiopsie, Block M2.":"Βιοψία ήπατος FFPE, block M2.","ca. 35–40 %, nach Markierung gut geeignet.":"περ. 35–40%, κατάλληλο μετά από επισήμανση.","RNA-Prognose":"Εκτίμηση RNA","RNA-Qualität nach Vorprüfung grenzwertig bis ausreichend; noch genügend Material für einen gezielten RNA-Ansatz.":"Η ποιότητα RNA είναι οριακή έως επαρκής μετά τον προκαταρκτικό έλεγχο· απομένει αρκετό υλικό για στοχευμένη προσέγγιση RNA.","Schnittbudget":"Διαθέσιμος αριθμός τομών","8 ungefärbte Schnitte verfügbar.":"Διαθέσιμες 8 άχρωμες τομές.","Materialfalle":"Παγίδα υλικού","Ein wiederholtes DNA-only-Panel verbraucht Material und kann die eigentliche Fusionsfrage trotzdem offenlassen.":"Η επανάληψη panel μόνο DNA καταναλώνει υλικό και μπορεί να αφήσει αναπάντητο το πραγματικό ερώτημα των συντήξεων.","Breite Fusionsdiagnostik":"Ευρεία διερεύνηση συντήξεων","DNA-NGS":"DNA-NGS","Kein relevanter SNV/Indel-Treiber nachweisbar. Die konkrete Assay-Konfiguration erlaubt keinen belastbaren Ausschluss aller klinisch relevanten Fusionen.":"Δεν ανιχνεύθηκε σχετικό SNV/indel driver. Η συγκεκριμένη διαμόρφωση της εξέτασης δεν επιτρέπει αξιόπιστο αποκλεισμό όλων των κλινικά σημαντικών συντήξεων.","RNA-Fusionsdiagnostik":"Έλεγχος συντήξεων RNA","KIF5B::RET-Fusion nachweisbar; in-frame und exprimiert. Der Befund erklärt den bisher DNA-negativen Treiberstatus.":"Ανιχνεύθηκε σύντηξη KIF5B::RET· in-frame και εκφραζόμενη. Το εύρημα εξηγεί το προηγουμένως DNA-αρνητικό driver status.","FISH":"FISH","Bei gezielter RET-FISH zeigt sich ein Rearrangement. Die Methode bestätigt die Umlagerung, liefert aber nicht die Breite einer parallelen RNA-Fusionsanalyse.":"Στοχευμένο FISH για RET δείχνει αναδιάταξη. Η μέθοδος επιβεβαιώνει την αναδιάταξη, αλλά δεν παρέχει το εύρος παράλληλης ανάλυσης συντήξεων RNA.","QC":"QC","Tumorzellanteil ausreichend. RNA ist knapp, aber nach QC verwertbar; Material Stewardship bleibt relevant.":"Επαρκές ποσοστό όγκου. Το RNA είναι περιορισμένο αλλά αξιοποιήσιμο μετά το QC· η συνετή διαχείριση υλικού παραμένει σημαντική.","Die RNA-basierte Fusionsdiagnostik weist eine therapeutisch relevante KIF5B::RET-Fusion nach. Der zuvor negative DNA-Befund war kein belastbarer Ausschluss einer onkogenen Fusion.":"Ο έλεγχος συντήξεων μέσω RNA ανιχνεύει θεραπευτικά σημαντική σύντηξη KIF5B::RET. Το προηγουμένως αρνητικό αποτέλεσμα DNA δεν αποτελούσε αξιόπιστο αποκλεισμό ογκογονικής σύντηξης.","Teilbefund: Eine gezielte Einzelmethode oder DNA-only-Strategie kann die breite Fusionsfrage nicht vollständig beantworten. Eine RNA-basierte Fusionsdiagnostik sollte ergänzt werden.":"Μερικό αποτέλεσμα: μία στοχευμένη μεμονωμένη μέθοδος ή στρατηγική μόνο DNA δεν μπορεί να απαντήσει πλήρως στο ευρύ ερώτημα συντήξεων. Πρέπει να προστεθεί έλεγχος συντήξεων μέσω RNA.","Die RET-Fusion als therapieentscheidenden Treiber benennen":"Αναγνωρίστε τη σύντηξη RET ως driver καθοριστικό για τη θεραπεία","DNA-only nicht mit umfassend treibernegativ gleichsetzen":"μην εξισώνετε το DNA-only με πλήρως driver-αρνητικό αποτέλεσμα","FISH als gezielte Bestätigungs-/Alternativmethode, nicht als universellen Ersatz einer breiten RNA-Analyse einordnen":"εντάξτε το FISH ως στοχευμένη επιβεβαιωτική/εναλλακτική μέθοδο και όχι ως καθολικό υποκατάστατο ευρείας ανάλυσης RNA","Assay- und RNA-QC-Limitationen transparent kommunizieren":"επικοινωνήστε με διαφάνεια τους περιορισμούς του assay και του QC RNA","Optimale Lösung: vorhandenen DNA-Befund methodisch prüfen und die offene Fusionsfrage mit einer breiten RNA-basierten Analyse schließen; gezielte FISH kann bei konkreter Hypothese ergänzen.":"Βέλτιστη λύση: ελέγξτε μεθοδολογικά το υπάρχον αποτέλεσμα DNA και κλείστε το ανοικτό ερώτημα συντήξεων με ευρεία ανάλυση βασισμένη σε RNA· στοχευμένο FISH μπορεί να προστεθεί για συγκεκριμένη υπόθεση.","NSCLC":"NSCLC","NGS":"NGS","RNA":"RNA","MVP":"MVP","Standard":"Standard","Junge Nie-Raucherin mit DNA-negativem NSCLC: Ist der Tumor wirklich treibernegativ?":"Νεαρή μη καπνίστρια με DNA-αρνητικό NSCLC: είναι ο όγκος πραγματικά driver-negative;","Molekularpathologie / Thoraxonkologie / MTB":"Μοριακή παθολογία / Θωρακική ογκολογία / MTB","Einen negativen DNA-NGS-Befund nur innerhalb der tatsächlich validierten Assaygrenzen interpretieren.":"Ερμηνεύστε ένα αρνητικό αποτέλεσμα DNA-NGS μόνο εντός των ορίων του assay που έχουν πράγματι επικυρωθεί.","RNA-basierte Fusionsdiagnostik bei klinisch plausibler Fusionsfrage gegenüber serieller FISH und erneutem DNA-only-Test priorisieren.":"Προτιμήστε έλεγχο συντήξεων μέσω RNA έναντι σειριακού FISH και επανάληψης DNA-only όταν υπάρχει κλινικά εύλογο ερώτημα σύντηξης.","FISH als gezielte orthogonale Methode sinnvoll einordnen, ohne sie mit einer breiten parallelen Fusionssuche gleichzusetzen.":"Χρησιμοποιήστε ορθά το FISH ως στοχευμένη ορθογώνια μέθοδο χωρίς να το εξισώνετε με ευρύ παράλληλο έλεγχο συντήξεων.","Einen methodisch unvollständigen 'kein Treiber'-Befund im MTB aktiv korrigieren.":"Διορθώστε ενεργά στο MTB ένα μεθοδολογικά ελλιπές αποτέλεσμα «χωρίς driver».","Mittwochmorgen vor dem Thorax-MTB. Auf dem Bildschirm steht bei einer 42-jährigen Nie-Raucherin mit metastasiertem Lungenadenokarzinom bereits der externe Satz: 'Kein therapeutisch relevanter Treiber nachweisbar.' Die Onkologie plant deshalb eine nicht zielgerichtete Systemtherapie. Beim Lesen des Methodenteils fällt jedoch auf: Untersucht wurde ein DNA-only-Panel; eine belastbare RNA-basierte Fusionsdiagnostik ist nicht dokumentiert. Aus einem scheinbar abgeschlossenen Befund wird wieder eine offene Therapiefrage.":"Τετάρτη πρωί πριν από το θωρακικό MTB. Στην οθόνη, η εξωτερική αναφορά μιας 42χρονης μη καπνίστριας με μεταστατικό αδενοκαρκίνωμα πνεύμονα αναφέρει ήδη: «Δεν ανιχνεύθηκε θεραπευτικά σημαντικός driver». Έτσι η ογκολογική ομάδα σχεδιάζει μη στοχευμένη συστηματική θεραπεία. Όμως στο τμήμα μεθόδων φαίνεται ότι έγινε μόνο panel DNA· δεν τεκμηριώνεται αξιόπιστος έλεγχος συντήξεων μέσω RNA. Ένα φαινομενικά κλειστό αποτέλεσμα γίνεται ξανά ανοικτό θεραπευτικό ερώτημα.","42-jährige Nie-Raucherin, ECOG 1, pulmonales Adenokarzinom mit Leber- und Knochenmetastasen. Externes DNA-NGS ohne relevante SNV/Indel-Treiber. Für das MTB muss entschieden werden, ob dieser Befund als treibernegativ akzeptiert werden kann oder ob die offene ALK/ROS1/RET/NTRK-Fusionsfrage mit einer geeigneten Methode geschlossen werden muss.":"Γυναίκα 42 ετών, μη καπνίστρια, ECOG 1, με πνευμονικό αδενοκαρκίνωμα και ηπατικές/οστικές μεταστάσεις. Εξωτερικό DNA-NGS δεν δείχνει σημαντικό SNV/indel driver. Το MTB πρέπει να αποφασίσει αν αυτό μπορεί να γίνει δεκτό ως driver-negative ή αν το ανοικτό ερώτημα συντήξεων ALK/ROS1/RET/NTRK πρέπει να απαντηθεί με κατάλληλη μέθοδο.","Klinischer Kontext":"Κλινικό πλαίσιο","Junges Alter, Nie-Raucherstatus und Adenokarzinom machen eine onkogene Treiberalteration plausibel, beweisen sie aber nicht.":"Η νεαρή ηλικία, η απουσία καπνίσματος και το αδενοκαρκίνωμα καθιστούν εύλογη μια ογκογονική driver αλλοίωση, αλλά δεν την αποδεικνύουν.","Klinische Plausibilität steuert die Aufmerksamkeit; die Diagnose entsteht aus Methodik und Befund.":"Η κλινική πιθανότητα κατευθύνει την προσοχή· η διάγνωση προκύπτει από τη μέθοδο και το αποτέλεσμα.","Externer Befund":"Εξωτερικό αποτέλεσμα","DNA-NGS: EGFR, KRAS, BRAF, MET-Exon-14 und ERBB2 ohne relevante Alteration. Der Methodenteil beschreibt keine validierte breite RNA-Fusionsanalyse.":"DNA-NGS: EGFR, KRAS, BRAF, MET exon 14 και ERBB2 χωρίς σημαντική αλλοίωση. Το τμήμα μεθόδων δεν περιγράφει επικυρωμένη ευρεία ανάλυση συντήξεων RNA.","'Negativ' ist nur so breit wie der verwendete Assay.":"Το «αρνητικό» είναι τόσο ευρύ όσο το assay που χρησιμοποιήθηκε.","Leberbiopsie mit 35–40 % Tumor, acht ungefärbte Schnitte. RNA-QC ist grenzwertig bis ausreichend.":"Βιοψία ήπατος με 35–40% όγκο, οκτώ άχρωμες τομές. Το QC RNA είναι οριακό έως επαρκές.","Jetzt ist eine gezielte, informationsreiche Ergänzung sinnvoller als serielle Einzeltests.":"Μια στοχευμένη, πλούσια σε πληροφορία συμπληρωματική εξέταση είναι τώρα χρησιμότερη από σειριακές μεμονωμένες εξετάσεις.","MTB-Druck":"Χρονική πίεση MTB","Therapieentscheidung in fünf Tagen; jeder unnötige Zusatzlauf kostet Zeit und Material.":"Θεραπευτική απόφαση σε πέντε ημέρες· κάθε περιττό επιπλέον run κοστίζει χρόνο και υλικό.","TAT und Material Stewardship gehören zur klinischen Methodenauswahl.":"Το TAT και η συνετή διαχείριση υλικού αποτελούν μέρος της κλινικής επιλογής μεθόδου.","HE/IHC":"H&E/IHC","Metastase eines TTF-1-/Napsin-A-positiven pulmonalen Adenokarzinoms.":"Μετάσταση πνευμονικού αδενοκαρκινώματος θετικού για TTF-1/Napsin A.","DNA-NGS extern":"Εξωτερικό DNA-NGS","Kein relevanter SNV/Indel-Treiber; Fusionsabdeckung nicht ausreichend dokumentiert.":"Χωρίς σημαντικό SNV/indel driver· η κάλυψη συντήξεων δεν τεκμηριώνεται επαρκώς.","RNA-QC":"QC RNA","RNA ist nicht perfekt, aber für einen zielgerichteten Fusionsassay noch verwertbar.":"Το RNA δεν είναι τέλειο, αλλά παραμένει αξιοποιήσιμο για στοχευμένο assay συντήξεων.","Nur acht ungefärbte Schnitte verbleiben.":"Απομένουν μόνο οκτώ άχρωμες τομές.","TAT-Ziel fünf Tage bis MTB.":"Στόχος TAT: πέντε ημέρες μέχρι το MTB.","Eine breite serielle FISH-Strategie würde mehrere Einzelansätze und Vorannahmen benötigen.":"Μια ευρεία στρατηγική σειριακού FISH θα απαιτούσε πολλαπλές μεμονωμένες εξετάσεις και προϋποθέσεις.","Ein erneutes DNA-only-Panel kann denselben methodischen blinden Fleck reproduzieren.":"Η επανάληψη panel DNA-only μπορεί να αναπαράγει το ίδιο μεθοδολογικό τυφλό σημείο.","Was bedeutet der externe Satz 'kein therapeutisch relevanter Treiber nachweisbar' in diesem Fall?":"Τι σημαίνει σε αυτή την περίπτωση η εξωτερική δήλωση «δεν ανιχνεύθηκε θεραπευτικά σημαντικός driver»;","Alle relevanten Treiber einschließlich Fusionen sind sicher ausgeschlossen.":"Όλοι οι σημαντικοί drivers, συμπεριλαμβανομένων των συντήξεων, έχουν αποκλειστεί με ασφάλεια.","Er gilt nur innerhalb der validierten DNA-Assaygrenzen; die Fusionsfrage bleibt offen.":"Ισχύει μόνο εντός των επικυρωμένων ορίων του assay DNA· το ερώτημα συντήξεων παραμένει ανοικτό.","Bei Nie-Rauchern ist ein negativer Befund grundsätzlich falsch.":"Σε μη καπνιστές, ένα αρνητικό αποτέλεσμα είναι πάντοτε λάθος.","Er bedeutet automatisch, dass jetzt jede Fusion einzeln per FISH getestet werden muss.":"Σημαίνει αυτομάτως ότι κάθε σύντηξη πρέπει τώρα να ελεγχθεί ξεχωριστά με FISH.","Ein negativer molekularer Befund ist immer an die analytische Abdeckung der verwendeten Methode gebunden.":"Ένα αρνητικό μοριακό αποτέλεσμα συνδέεται πάντοτε με την αναλυτική κάλυψη της χρησιμοποιούμενης μεθόδου.","Welche Ergänzung beantwortet die offene breite Fusionsfrage am effizientesten?":"Ποια συμπληρωματική εξέταση απαντά πιο αποτελεσματικά στο ανοικτό ευρύ ερώτημα συντήξεων;","Breites RNA-basiertes Fusionspanel":"Ευρύ panel συντήξεων βασισμένο σε RNA","Dasselbe DNA-only-Panel noch einmal":"Το ίδιο panel DNA-only ξανά","Eine einzelne ALK-FISH als vollständiger Ersatz":"Ένα μόνο FISH ALK ως πλήρες υποκατάστατο","Keine Ergänzung, weil die Histologie bereits eindeutig ist":"Καμία συμπληρωματική εξέταση επειδή η ιστολογία είναι ήδη σαφής","RNA-NGS kann mehrere exprimierte Fusionsereignisse parallel erfassen und ist für diese offene Fragestellung besonders geeignet.":"Το RNA-NGS μπορεί να ανιχνεύσει παράλληλα πολλαπλά εκφραζόμενα συμβάντα σύντηξης και είναι ιδιαίτερα κατάλληλο για αυτό το ανοικτό ερώτημα.","Wann bleibt FISH in diesem Fall sinnvoll?":"Πότε παραμένει χρήσιμο το FISH σε αυτή την περίπτωση;","Bei konkreter Genhypothese als schnelle/orthogonale Bestätigung":"Για συγκεκριμένη γονιδιακή υπόθεση ως ταχεία/ορθογώνια επιβεβαίωση","Wenn RNA nicht verwertbar ist und ein gezielter Rearrangement-Nachweis benötigt wird":"Όταν το RNA δεν είναι αξιοποιήσιμο και απαιτείται στοχευμένη ανίχνευση αναδιάταξης","Als universell umfassender Ersatz für eine breite RNA-Fusionsanalyse":"Ως καθολικά πλήρες υποκατάστατο ευρείας ανάλυσης συντήξεων RNA","Zur sicheren Bestimmung jedes Fusionspartners":"Για ασφαλή προσδιορισμό κάθε εταίρου σύντηξης","FISH ist für gezielte Rearrangement-Fragen nützlich, aber meist weniger breit und partnerinformativ als RNA-basierte Verfahren.":"Το FISH είναι χρήσιμο για στοχευμένα ερωτήματα αναδιάταξης, αλλά συνήθως έχει μικρότερο εύρος και παρέχει λιγότερες πληροφορίες για τον εταίρο από μεθόδους βασισμένες σε RNA.","Entscheiden Sie, ob der externe DNA-negative Befund als vollständig akzeptiert werden kann und welche Ergänzung jetzt mit dem verbliebenen Material die größte klinische Information liefert.":"Αποφασίστε αν το εξωτερικό DNA-αρνητικό αποτέλεσμα μπορεί να γίνει δεκτό ως πλήρες και ποια συμπληρωματική εξέταση δίνει τώρα τη μεγαλύτερη κλινική πληροφορία από το εναπομείναν υλικό.","Methodenteil des externen DNA-Befunds prüfen und die unzureichend geklärte Fusionsabdeckung benennen.":"Ελέγξτε το τμήμα μεθόδων του εξωτερικού αποτελέσματος DNA και επισημάνετε την ανεπαρκώς διευκρινισμένη κάλυψη συντήξεων.","RNA-basiertes Fusionspanel priorisieren.":"Δώστε προτεραιότητα σε panel συντήξεων βασισμένο σε RNA.","Material aus dem markierten Tumorareal gezielt für RNA aufarbeiten.":"Επεξεργαστείτε το υλικό από τη σημειωμένη περιοχή όγκου ειδικά για RNA.","FISH nur bei konkreter Hypothese oder nicht verwertbarer RNA als gezielte Alternative/Bestätigung einsetzen.":"Χρησιμοποιήστε FISH μόνο ως στοχευμένη εναλλακτική/επιβεβαίωση για συγκεκριμένη υπόθεση ή μη αξιοποιήσιμο RNA.","Im MTB bis zum Abschluss der Fusionsdiagnostik nicht 'treibernegativ' formulieren.":"Μην χαρακτηρίζετε την περίπτωση ως «driver-negative» στο MTB μέχρι να ολοκληρωθεί ο έλεγχος συντήξεων.","Validiertes kombiniertes DNA/RNA-Pan-Panel, wenn es die relevante Fusionsbreite sicher abdeckt und Material/TAT vertretbar sind.":"Ένα επικυρωμένο συνδυασμένο pan-panel DNA/RNA, εφόσον καλύπτει αξιόπιστα το σχετικό φάσμα συντήξεων και το υλικό/TAT είναι αποδεκτά.","Gezielte RET-FISH, wenn RNA technisch scheitert und die konkrete Hypothese bereits fokussiert ist.":"Στοχευμένο FISH RET εάν το RNA αποτύχει τεχνικά και η συγκεκριμένη υπόθεση είναι ήδη εστιασμένη.","DNA-negativ = vollständig negativ":"DNA-αρνητικό = πλήρως αρνητικό","Die Aussage überschreitet die analytische Reichweite des verwendeten Assays.":"Η δήλωση υπερβαίνει την αναλυτική εμβέλεια του assay που χρησιμοποιήθηκε.","Serielle FISH für jede denkbare Fusion":"Σειριακό FISH για κάθε πιθανή σύντηξη","Material- und zeitintensiv; benötigt Vorannahmen und ist weniger parallelisierbar.":"Απαιτεί πολύ υλικό και χρόνο· χρειάζεται προϋποθέσεις και είναι λιγότερο παράλληλα εφαρμόσιμο.","Noch einmal dasselbe DNA-only-Panel":"Επαναλάβετε το ίδιο panel DNA-only","Wiederholung behebt keinen systematischen Assay-Blindspot.":"Η επανάληψη δεν διορθώνει συστηματικό τυφλό σημείο του assay.","Der 'treibernegative' Tumor ist nicht treibernegativ":"Ο «driver-negative» όγκος δεν είναι driver-negative","Das RNA-Fusionspanel detektiert eine exprimierte KIF5B::RET-Fusion. Eine anschließende gezielte RET-FISH bestätigt ein Rearrangement. Der zunächst geplante nicht zielgerichtete Therapieweg muss im MTB neu bewertet werden.":"Το panel συντήξεων RNA ανιχνεύει εκφραζόμενη σύντηξη KIF5B::RET. Επακόλουθο στοχευμένο FISH RET επιβεβαιώνει αναδιάταξη. Η αρχικά σχεδιασμένη μη στοχευμένη θεραπευτική πορεία πρέπει να επανεκτιμηθεί στο MTB.","Der Fehler lag nicht in der Qualität des ersten DNA-Laufs, sondern in der zu breiten Interpretation eines methodisch begrenzten Negativbefunds.":"Το σφάλμα δεν ήταν η ποιότητα του πρώτου run DNA, αλλά η υπερβολικά ευρεία ερμηνεία ενός μεθοδολογικά περιορισμένου αρνητικού αποτελέσματος.","RNA schließt die offene Lücke":"Το RNA κλείνει το ανοικτό κενό","KIF5B::RET-Fusion nachweisbar; DNA-SNV/Indel-Profil ohne weiteren relevanten Treiber.":"Ανιχνεύθηκε σύντηξη KIF5B::RET· προφίλ DNA SNV/indel χωρίς άλλο σημαντικό driver.","Sehr gut: Assaygrenze erkannt, passende Methode ergänzt, klinisch entscheidenden Treiber gefunden.":"Εξαιρετικά: αναγνωρίστηκε ο περιορισμός του assay, προστέθηκε κατάλληλη μέθοδος και βρέθηκε κλινικά καθοριστικός driver.","DNA-only bleibt Endpunkt":"Το DNA-only παραμένει το τελικό σημείο","Kein SNV/Indel-Treiber; Fusionsstatus bleibt methodisch unzureichend geklärt.":"Χωρίς SNV/indel driver· το status συντήξεων παραμένει μεθοδολογικά ανεπαρκώς διευκρινισμένο.","Der Befund klingt abgeschlossen, ist es aber nicht.":"Η αναφορά ακούγεται ολοκληρωμένη, αλλά δεν είναι.","Einzel-FISH":"FISH ενός γονιδίου","Eine gezielte Einzel-FISH kann ein bestimmtes Rearrangement beantworten, lässt andere Fusionsklassen offen.":"Ένα στοχευμένο μεμονωμένο FISH μπορεί να απαντήσει ένα συγκεκριμένο ερώτημα αναδιάταξης, αλλά αφήνει ανοικτές άλλες κατηγορίες συντήξεων.","Bei fokussierter Hypothese sinnvoll, als breite Erststrategie unvollständig.":"Χρήσιμη για εστιασμένη υπόθεση, ελλιπής ως ευρεία αρχική στρατηγική.","RNA ausreichend":"Επαρκές RNA","Breites RNA-Fusionspanel durchführen.":"Πραγματοποιήστε ευρύ panel συντήξεων RNA.","Direkter Nachweis KIF5B::RET und vollständige MTB-Einordnung.":"Άμεση ανίχνευση KIF5B::RET και πλήρης ερμηνεία στο MTB.","RNA nicht verwertbar":"Μη αξιοποιήσιμο RNA","Gezielte FISH/alternatives validiertes Material erwägen.":"Εξετάστε στοχευμένο FISH/εναλλακτικό επικυρωμένο υλικό.","Fragestellung wird fokussiert weiterverfolgt statt vorschnell geschlossen.":"Το ερώτημα διερευνάται εστιασμένα αντί να κλείσει πρόωρα.","Nur DNA ausgewählt":"Επιλέχθηκε μόνο DNA","Fusionsdiagnostik nachfordern.":"Ζητήστε έλεγχο συντήξεων.","Fall ist rettbar, aber TAT und Score verschlechtern sich.":"Η περίπτωση μπορεί να διορθωθεί, αλλά το TAT και η βαθμολογία επιδεινώνονται.","Ein negativer Befund ist kein universeller biologischer Zustand, sondern ein methodisch begrenztes Messergebnis.":"Ένα αρνητικό αποτέλεσμα δεν είναι καθολική βιολογική κατάσταση αλλά μέτρηση περιορισμένη από τη μέθοδο.","RNA-basierte Verfahren sind bei vielen Fusionsfragen besonders wertvoll.":"Οι μέθοδοι βασισμένες σε RNA είναι ιδιαίτερα πολύτιμες για πολλά ερωτήματα συντήξεων.","FISH bleibt relevant, wenn die Frage gezielt ist oder RNA scheitert.":"Το FISH παραμένει σημαντικό όταν το ερώτημα είναι στοχευμένο ή όταν αποτυγχάνει το RNA.","Das Wort 'treibernegativ' sollte nur verwendet werden, wenn die relevanten Alterationsklassen tatsächlich adäquat untersucht wurden.":"Ο όρος «driver-negative» πρέπει να χρησιμοποιείται μόνο όταν οι σχετικές κατηγορίες αλλοιώσεων έχουν πράγματι διερευνηθεί επαρκώς.","Der externe DNA-Befund darf nicht als vollständiger Treiberausschluss übernommen werden. Die offene Fusionsfrage wird mit einem breiten RNA-basierten Fusionspanel geschlossen. Ergebnis: KIF5B::RET-Fusion. FISH kann gezielt bestätigen oder bei nicht verwertbarer RNA aushelfen.":"Το εξωτερικό αποτέλεσμα DNA δεν πρέπει να θεωρηθεί πλήρης αποκλεισμός drivers. Το ανοικτό ερώτημα συντήξεων κλείνει με ευρύ panel συντήξεων βασισμένο σε RNA. Αποτέλεσμα: σύντηξη KIF5B::RET. Το FISH μπορεί να επιβεβαιώσει στοχευμένα ή να χρησιμοποιηθεί όταν το RNA δεν είναι αξιοποιήσιμο.","Assaygrenze erkannt":"Αναγνωρίστηκε ο περιορισμός του assay","RNA-Fusionsdiagnostik priorisiert":"Δόθηκε προτεραιότητα στον έλεγχο συντήξεων RNA","FISH korrekt eingeordnet":"Ορθή ένταξη του FISH","Kein Overclaim eines negativen DNA-Befunds":"Χωρίς υπερβολικό συμπέρασμα από αρνητικό DNA","Wann ist DNA-NGS für Fusionen ausreichend?":"Πότε επαρκεί το DNA-NGS για συντήξεις;","Welche Informationen liefert RNA zusätzlich zur strukturellen Umlagerung?":"Ποιες πληροφορίες προσφέρει το RNA πέρα από τη δομική αναδιάταξη;","Wie sollte ein pathologischer Negativbefund formuliert sein, wenn eine relevante Alterationsklasse nicht sicher abgedeckt ist?":"Πώς πρέπει να διατυπώνεται ένα αρνητικό παθολογοανατομικό αποτέλεσμα όταν μια σημαντική κατηγορία αλλοιώσεων δεν καλύπτεται αξιόπιστα;","DE master reviewed structure":"Ελεγμένη δομή DE master","KIF5B::RET trotz DNA-negativem Vorbericht":"KIF5B::RET παρά την προηγούμενη DNA-αρνητική αναφορά","Negativbefunde sind assaygebunden":"Τα αρνητικά αποτελέσματα εξαρτώνται από το assay","DNA-negativ → Methodencheck → RNA → Fusion":"DNA-αρνητικό → έλεγχος μεθόδου → RNA → σύντηξη","KRAS-mutiertes NSCLC mit STK11/KEAP1-Kontext → Target, Prognose, Immuntherapie-Kontext korrekt gewichten":"KRAS-μεταλλαγμένο NSCLC με πλαίσιο STK11/KEAP1 → σωστή στάθμιση στόχου, πρόγνωσης και πλαισίου ανοσοθεραπείας","KRAS-mutiertes NSCLC mit STK11/KEA…":"KRAS-μεταλλαγμένο NSCLC με STK11/KEA…","Thoraxonkologie / MTB":"Θωρακική ογκολογία / MTB","66-jähriger Patient mit metastasiertem Lungenadenokarzinom. Das DNA-Panel zeigt KRAS p.G12C sowie pathogene STK11- und KEAP1-Alterationen.":"Άνδρας 66 ετών με μεταστατικό αδενοκαρκίνωμα πνεύμονα. Το panel DNA δείχνει KRAS p.G12C μαζί με παθογόνες αλλοιώσεις STK11 και KEAP1.","Bedeutet die Ko-Mutationskonstellation, dass Immuntherapie nicht sinnvoll ist? Welche Information ist tatsächlich therapeutisch, welche prognostisch und welche nur biologischer Kontext?":"Σημαίνει το προφίλ συν-μεταλλάξεων ότι η ανοσοθεραπεία δεν είναι χρήσιμη; Ποια πληροφορία είναι πραγματικά θεραπευτική, ποια προγνωστική και ποια μόνο βιολογικό πλαίσιο;","Therapieentscheidung im MTB innerhalb einer Woche.":"Θεραπευτική απόφαση στο MTB εντός μίας εβδομάδας.","35 pack years, vor sechs Jahren aufgehört.":"35 pack-years, διακοπή καπνίσματος πριν από έξι χρόνια.","Stadium":"Στάδιο","Leber-, Nebennieren- und ossäre Metastasen; ECOG 1.":"Ηπατικές, επινεφριδιακές και οστικές μεταστάσεις· ECOG 1.","Vorbehandlung":"Προηγούμενη θεραπεία","Keine systemische Therapie im metastasierten Stadium.":"Καμία συστηματική θεραπεία στο μεταστατικό στάδιο.","Klinische Falle":"Κλινική παγίδα","Im Vorbericht wurde STK11/KEAP1 bereits als 'Immuntherapie-Resistenzmarker' bezeichnet. Das Tumorboard möchte wissen, ob daraus ein Therapieausschluss folgt.":"Η προκαταρκτική αναφορά έχει ήδη χαρακτηρίσει τα STK11/KEAP1 ως «δείκτες αντοχής στην ανοσοθεραπεία». Το ογκολογικό συμβούλιο θέλει να γνωρίζει αν αυτό συνεπάγεται αποκλεισμό θεραπείας.","Pulmonales Adenokarzinom mit soliden und azinären Anteilen.":"Πνευμονικό αδενοκαρκίνωμα με συμπαγή και αδενικά/acinär στοιχεία.","TTF-1 positiv, p40 negativ.":"TTF-1 θετικό, p40 αρνητικό.","PD-L1":"PD-L1","Noch ausstehend.":"Εκκρεμεί.","Molekular":"Μοριακά δεδομένα","KRAS p.G12C, STK11 loss-of-function und KEAP1 loss-of-function; keine klassische EGFR-/ALK-/ROS1-Treiberkonstellation.":"KRAS p.G12C, STK11 loss-of-function και KEAP1 loss-of-function· χωρίς κλασικό προφίλ driver EGFR/ALK/ROS1.","Wie werden KRAS-Targetierbarkeit, adverse Ko-Mutationen und Immuntherapie-Kontext getrennt und zusammengeführt?":"Πώς πρέπει να διαχωριστούν και να ενσωματωθούν η δυνατότητα στόχευσης του KRAS, οι δυσμενείς συν-μεταλλάξεις και το πλαίσιο ανοσοθεραπείας;","FFPE-Lungenbiopsie mit ca. 45 % Tumoranteil.":"Βιοψία πνεύμονα FFPE με περ. 45% ποσοστό όγκου.","DNA-QC":"QC DNA","ausreichend, Panel vollständig auswertbar.":"επαρκές, το panel είναι πλήρως αξιολογήσιμο.","9 ungefärbte Schnitte verfügbar.":"Διαθέσιμες 9 άχρωμες τομές.","Zusätzliche explorative Biomarker dürfen nicht den Eindruck erzeugen, es gebe einen validierten Einzeltest, der die Immuntherapieentscheidung sicher vorhersagt.":"Πρόσθετοι διερευνητικοί βιοδείκτες δεν πρέπει να δημιουργούν την εντύπωση ότι υπάρχει ένα επικυρωμένο μεμονωμένο test που προβλέπει με βεβαιότητα την απόφαση ανοσοθεραπείας.","KRAS/STK11/KEAP1-Kontext":"Πλαίσιο KRAS/STK11/KEAP1","PD-L1-Kontext":"Πλαίσιο PD-L1","KRAS/STK11/KEAP1":"KRAS/STK11/KEAP1","KRAS p.G12C sowie pathogene STK11- und KEAP1-loss-of-function-Alterationen. Die Ko-Mutationen markieren eine biologisch ungünstige Subgruppe, sind aber kein eigenständiger binärer Ausschlusstest für Immuntherapie.":"KRAS p.G12C μαζί με παθογόνες loss-of-function αλλοιώσεις STK11 και KEAP1. Οι συν-μεταλλάξεις χαρακτηρίζουν βιολογικά δυσμενή υποομάδα, αλλά δεν αποτελούν αυτόνομο δυαδικό test αποκλεισμού ανοσοθεραπείας.","PD-L1 TPS 70 %. Hohe Expression ist klinisch relevant, muss aber zusammen mit klinischem Kontext und Ko-Mutationen interpretiert werden.":"PD-L1 TPS 70%. Η υψηλή έκφραση είναι κλινικά σημαντική, αλλά πρέπει να ερμηνεύεται μαζί με το κλινικό πλαίσιο και τις συν-μεταλλάξεις.","TMB":"TMB","TMB im intermediären Bereich. Kein Befund, der die komplexe Ko-Mutationskonstellation alleine auflöst.":"TMB σε ενδιάμεσο εύρος. Κανένα εύρημα που να επιλύει μόνο του το σύνθετο προφίλ συν-μεταλλάξεων.","Immun-Kontext-IHC":"IHC ανοσολογικού πλαισίου","Relativ geringes CD8-positives Infiltrat. Biologisch interessant, aber kein validierter alleiniger Therapieausschlussmarker.":"Σχετικά περιορισμένη CD8-θετική διήθηση. Βιολογικά ενδιαφέρουσα, αλλά όχι επικυρωμένος αυτόνομος δείκτης αποκλεισμού θεραπείας.","DNA-QC und Tumoranteil ausreichend; PD-L1 technisch auswertbar.":"Επαρκές QC DNA και ποσοστό όγκου· το PD-L1 είναι τεχνικά αξιολογήσιμο.","KRAS p.G12C ist ein potenziell therapeutisch relevanter Genotyp im passenden Behandlungskontext. STK11/KEAP1 sind wichtige adverse biologische/prognostische Ko-Alterationen, dürfen aber nicht als binärer 'kein ICI'-Marker überinterpretiert werden. PD-L1 TPS 70 % bleibt eine eigenständige klinisch relevante Information.":"Το KRAS p.G12C είναι δυνητικά θεραπευτικά σημαντικός γονότυπος στο κατάλληλο θεραπευτικό πλαίσιο. Τα STK11/KEAP1 είναι σημαντικές δυσμενείς βιολογικές/προγνωστικές συν-αλλοιώσεις, αλλά δεν πρέπει να υπερερμηνεύονται ως δυαδικοί δείκτες «όχι ICI». Το PD-L1 TPS 70% παραμένει ανεξάρτητη κλινικά σημαντική πληροφορία.","Teilbefund: KRAS/Ko-Mutationen oder PD-L1 fehlen. Ohne beide Ebenen ist eine ausgewogene MTB-Einordnung nicht möglich.":"Μερικό αποτέλεσμα: λείπουν KRAS/συν-μεταλλάξεις ή PD-L1. Χωρίς και τα δύο επίπεδα δεν είναι δυνατή ισορροπημένη ερμηνεία στο MTB.","KRAS p.G12C als Genotyp mit möglicher Target-Relevanz im passenden Therapiekontext benennen":"Αναφέρετε το KRAS p.G12C ως γονότυπο με πιθανή target relevance στο κατάλληλο θεραπευτικό πλαίσιο","STK11/KEAP1 als adverse Kontextmarker, nicht als absoluten ICI-Ausschluss darstellen":"Περιγράψτε τα STK11/KEAP1 ως δυσμενείς δείκτες πλαισίου, όχι ως απόλυτους αποκλεισμούς ICI","PD-L1 separat und nicht durch Ko-Mutationen 'weginterpretieren'":"Αναφέρετε το PD-L1 χωριστά και μην το «εξουδετερώνετε ερμηνευτικά» λόγω συν-μεταλλάξεων","Prognostische Assoziation und prädiktive Therapieentscheidung sprachlich trennen":"Διαχωρίστε λεκτικά την προγνωστική συσχέτιση από την προγνωστική θεραπευτική απόφαση","Optimale Lösung: KRAS, STK11/KEAP1 und PD-L1 auf getrennten Evidenzebenen berichten und im MTB integrieren; keine einzelne Ko-Mutation als absoluten Therapieausschluss verwenden.":"Βέλτιστη λύση: αναφέρετε KRAS, STK11/KEAP1 και PD-L1 σε χωριστά επίπεδα τεκμηρίωσης και ενσωματώστε τα στο MTB· μην χρησιμοποιείτε καμία μεμονωμένη συν-μετάλλαξη ως απόλυτο αποκλεισμό θεραπείας.","Immunescape":"Ανοσοδιαφυγή","Phase":"Φάση","KRAS/STK11/KEAP1-NSCLC: Kontextmarker sind kein Therapie-Ausschalter":"NSCLC KRAS/STK11/KEAP1: οι δείκτες πλαισίου δεν είναι διακόπτες θεραπείας","KRAS-Targetierbarkeit, STK11/KEAP1-Kontext und PD-L1 auf getrennten Evidenzebenen einordnen.":"Εντάξτε τη δυνατότητα στόχευσης KRAS, το πλαίσιο STK11/KEAP1 και το PD-L1 σε χωριστά επίπεδα τεκμηρίωσης.","Prognostische bzw. assoziierte Resistenzsignale nicht als validierten binären prädiktiven Ausschlusstest formulieren.":"Μην διατυπώνετε προγνωστικά ή συσχετιζόμενα σήματα αντοχής ως επικυρωμένο δυαδικό προγνωστικό test αποκλεισμού.","Widersprüchliche Biomarkerinformationen in einer balancierten MTB-Aussage integrieren.":"Ενσωματώστε αντικρουόμενες πληροφορίες βιοδεικτών σε ισορροπημένη δήλωση MTB.","Explorative TME-Marker von klinisch etablierten Routineentscheidungen trennen.":"Διαχωρίστε διερευνητικούς δείκτες TME από κλινικά καθιερωμένες αποφάσεις ρουτίνας.","Im Thorax-MTB liegt ein Befund mit drei fett markierten Genen: KRAS, STK11 und KEAP1. Der Vorbericht bezeichnet die beiden Ko-Mutationen bereits als 'Immuntherapie-Resistenzmarker'. Gleichzeitig ist PD-L1 noch nicht bestimmt. Die klinische Frage lautet nicht nur, was mutiert ist, sondern ob aus dieser biologisch ungünstigen Konstellation wirklich ein Therapieverbot abgeleitet werden darf.":"Στο θωρακικό MTB η αναφορά περιέχει τρία γονίδια με έντονα γράμματα: KRAS, STK11 και KEAP1. Η προκαταρκτική αναφορά αποκαλεί ήδη τις δύο συν-μεταλλάξεις «δείκτες αντοχής στην ανοσοθεραπεία». Ταυτόχρονα, το PD-L1 δεν έχει ακόμη προσδιοριστεί. Το κλινικό ερώτημα δεν είναι μόνο τι έχει μεταλλαχθεί, αλλά αν αυτή η βιολογικά δυσμενής συνθήκη δικαιολογεί πραγματικά απαγόρευση θεραπείας.","66-jähriger Patient, ehemaliger starker Raucher, metastasiertes Lungenadenokarzinom mit Leber-, Nebennieren- und Knochenmetastasen, ECOG 1. DNA-NGS zeigt KRAS p.G12C plus pathogene STK11- und KEAP1-Alterationen. Das MTB möchte Target-Relevanz, Prognose und Immuntherapie-Kontext sauber gewichten.":"Άνδρας 66 ετών, πρώην βαρύς καπνιστής, με μεταστατικό αδενοκαρκίνωμα πνεύμονα σε ήπαρ, επινεφρίδια και οστά, ECOG 1. Το DNA-NGS δείχνει KRAS p.G12C μαζί με παθογόνες αλλοιώσεις STK11 και KEAP1. Το MTB θέλει να σταθμίσει σωστά τη στόχευση, την πρόγνωση και το πλαίσιο ανοσοθεραπείας.","Genotyp":"Γονότυπος","KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.":"KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.","Nicht jede genetische Information erfüllt dieselbe klinische Funktion.":"Δεν επιτελεί κάθε γενετική πληροφορία την ίδια κλινική λειτουργία.","Klinik":"Κλινική κατάσταση","Hohe Tumorlast, aber aktuell stabil; keine vorangegangene systemische Therapie im metastasierten Stadium.":"Υψηλό φορτίο όγκου, αλλά προς το παρόν σταθερός· χωρίς προηγούμενη συστηματική θεραπεία στο μεταστατικό στάδιο.","Therapieentscheidungen bleiben klinisch eingebettet.":"Οι θεραπευτικές αποφάσεις παραμένουν ενταγμένες στο κλινικό πλαίσιο.","Vorbericht":"Προκαταρκτική αναφορά","STK11/KEAP1 wurden als 'ICI-resistent' bezeichnet.":"Τα STK11/KEAP1 χαρακτηρίστηκαν «ανθεκτικά σε ICI».","Assoziation mit ungünstigen Outcomes ist nicht dasselbe wie ein validierter absoluter Ausschlussmarker.":"Η συσχέτιση με δυσμενή έκβαση δεν ισοδυναμεί με επικυρωμένο απόλυτο δείκτη αποκλεισμού.","Offene Information":"Εκκρεμής πληροφορία","PD-L1 steht noch aus; zusätzliche TMB-/TIL-Daten könnten biologischen Kontext liefern, sind aber kein Ersatz für klinische Evidenz.":"Το PD-L1 εκκρεμεί· πρόσθετα δεδομένα TMB/TIL μπορεί να προσφέρουν βιολογικό πλαίσιο, αλλά δεν υποκαθιστούν την κλινική τεκμηρίωση.","Mehr Biomarker bedeutet nicht automatisch eine klarere Therapieentscheidung.":"Περισσότεροι βιοδείκτες δεν οδηγούν αυτομάτως σε σαφέστερη θεραπευτική απόφαση.","KRAS p.G12C; pathogene STK11- und KEAP1-loss-of-function-Alterationen.":"KRAS p.G12C· παθογόνες loss-of-function αλλοιώσεις STK11 και KEAP1.","TTF-1-positives pulmonales Adenokarzinom.":"TTF-1-θετικό πνευμονικό αδενοκαρκίνωμα.","Noch nicht bestimmt.":"Δεν έχει ακόμη προσδιοριστεί.","Ausreichendes FFPE-Material; keine akute Materialknappheit.":"Επαρκές υλικό FFPE· δεν υπάρχει άμεση έλλειψη υλικού.","Die eigentliche Grenze ist interpretativ: zusätzliche Marker dürfen nicht als stärker validiert erscheinen, als sie sind.":"Ο πραγματικός περιορισμός είναι ερμηνευτικός: οι πρόσθετοι δείκτες δεν πρέπει να εμφανίζονται ως περισσότερο επικυρωμένοι απ’ όσο είναι.","TMB/CD8-IHC können Kontext liefern, sind in diesem Fall aber nicht als zwingende Entscheidungsmarker definiert.":"TMB/IHC CD8 μπορούν να προσφέρουν πλαίσιο, αλλά δεν ορίζονται ως υποχρεωτικοί δείκτες απόφασης σε αυτή την περίπτωση.","Welche Aussagen sind fachlich angemessen?":"Ποιες δηλώσεις είναι επιστημονικά κατάλληλες;","KRAS p.G12C kann im geeigneten Therapiekontext targetrelevant sein.":"Το KRAS p.G12C μπορεί να έχει σημασία ως στόχος στο κατάλληλο θεραπευτικό πλαίσιο.","STK11/KEAP1 kennzeichnen eine biologisch/prognostisch ungünstige Subgruppe.":"Τα STK11/KEAP1 χαρακτηρίζουν βιολογικά/προγνωστικά δυσμενή υποομάδα.","STK11 oder KEAP1 schließen Immuntherapie grundsätzlich aus.":"Το STK11 ή KEAP1 αποκλείουν κατ’ αρχήν την ανοσοθεραπεία.","PD-L1 bleibt eine eigenständige klinisch relevante Information.":"Το PD-L1 παραμένει ανεξάρτητη κλινικά σημαντική πληροφορία.","Die Marker besitzen unterschiedliche Rollen; STK11/KEAP1 sind kein binärer ICI-Ausschluss.":"Οι δείκτες έχουν διαφορετικούς ρόλους· τα STK11/KEAP1 δεν αποτελούν δυαδικούς αποκλεισμούς ICI.","PD-L1 ergibt später TPS 70 %. Wie ist der Befund zu integrieren?":"Το PD-L1 αργότερα είναι TPS 70%. Πώς πρέπει να ενσωματωθεί το αποτέλεσμα;","Ignorieren, weil STK11/KEAP1 wichtiger sind.":"Αγνοήστε το επειδή τα STK11/KEAP1 είναι σημαντικότερα.","PD-L1 70 % garantiert eine sehr gute ICI-Antwort.":"PD-L1 70% εγγυάται πολύ καλή ανταπόκριση σε ICI.","Als relevante positive Information berichten, aber zusammen mit klinischem Kontext und der adversen Ko-Mutationsbiologie interpretieren.":"Αναφέρετέ το ως σημαντική θετική πληροφορία, αλλά ερμηνεύστε το μαζί με το κλινικό πλαίσιο και τη δυσμενή βιολογία των συν-μεταλλάξεων.","STK11/KEAP1 und PD-L1 heben sich gegenseitig auf; deshalb keine Aussage möglich.":"STK11/KEAP1 και PD-L1 αλληλοαναιρούνται· συνεπώς δεν είναι δυνατή καμία δήλωση.","Widersprüchliche Biomarker werden integriert, nicht gegeneinander 'verrechnet'.":"Οι αντικρουόμενοι βιοδείκτες ενσωματώνονται, δεν «αφαιρούνται» ο ένας από τον άλλο.","Welche Rolle haben TMB oder CD8/TIL-IHC hier?":"Ποιος είναι εδώ ο ρόλος του TMB ή της IHC CD8/TIL;","Optionaler biologischer Kontext; kein alleiniger validierter Therapieausschluss.":"Προαιρετικό βιολογικό πλαίσιο· όχι επικυρωμένος αυτόνομος αποκλεισμός θεραπείας.","Zwingend erforderlich, bevor überhaupt eine Therapie diskutiert werden darf.":"Υποχρεωτικά πριν συζητηθεί οποιαδήποτε θεραπεία.","Sie ersetzen PD-L1 vollständig.":"Αντικαθιστούν πλήρως το PD-L1.","Sie sind in der Tumorbiologie grundsätzlich bedeutungslos.":"Είναι εξ ορισμού άσχετα με τη βιολογία του όγκου.","Die Zusatzmarker können das biologische Bild vertiefen, lösen die klinische Evidenzfrage aber nicht allein.":"Οι πρόσθετοι δείκτες μπορούν να εμβαθύνουν τη βιολογική εικόνα, αλλά δεν επιλύουν μόνοι τους το ερώτημα της κλινικής τεκμηρίωσης.","Formulieren Sie eine MTB-Empfehlung, die KRAS p.G12C, STK11/KEAP1 und PD-L1 korrekt gewichtet, ohne aus einer Ko-Mutation ein nicht validiertes Therapieverbot zu machen.":"Διατυπώστε σύσταση MTB που σταθμίζει σωστά KRAS p.G12C, STK11/KEAP1 και PD-L1 χωρίς να μετατρέπει μια συν-μετάλλαξη σε μη επικυρωμένη απαγόρευση θεραπείας.","KRAS p.G12C als eigenständigen Genotyp mit potenzieller Target-Relevanz im passenden Behandlungskontext benennen.":"Αναφέρετε το KRAS p.G12C ως ανεξάρτητο γονότυπο με πιθανή σημασία ως στόχος στο κατάλληλο θεραπευτικό πλαίσιο.","STK11/KEAP1 als adverse biologische/prognostische Ko-Alterationen beschreiben.":"Περιγράψτε τα STK11/KEAP1 ως δυσμενείς βιολογικές/προγνωστικές συν-αλλοιώσεις.","PD-L1 bestimmen und separat berichten.":"Προσδιορίστε και αναφέρετε το PD-L1 χωριστά.","Aus STK11/KEAP1 keinen absoluten Immuntherapieausschluss ableiten.":"Μην συνάγετε απόλυτο αποκλεισμό ανοσοθεραπείας από STK11/KEAP1.","Optional erhobene TMB/TIL-Daten als Kontext, nicht als übergeordneten Entscheidungsmarker kennzeichnen.":"Χαρακτηρίστε τυχόν προαιρετικά δεδομένα TMB/TIL ως πλαίσιο και όχι ως ανώτερο δείκτη απόφασης.","Breites DNA-Panel statt fokussierter KRAS/STK11/KEAP1-Analyse, wenn es bereits Bestandteil der vollständigen NSCLC-Profilierung ist.":"Ευρύ panel DNA αντί εστιασμένης ανάλυσης KRAS/STK11/KEAP1 όταν αποτελεί ήδη μέρος της πλήρους προφίλ NSCLC.","TMB oder Immun-Kontext-IHC als zusätzliche Lehr-/Kontextinformation, solange daraus keine binäre Therapieentscheidung konstruiert wird.":"TMB ή IHC ανοσολογικού πλαισίου ως πρόσθετη διδακτική/συμφραζόμενη πληροφορία, εφόσον δεν κατασκευάζεται από αυτή δυαδική θεραπευτική απόφαση.","STK11/KEAP1 = kein ICI":"STK11/KEAP1 = όχι ICI","Aus einer adversen Assoziation wird fälschlich ein absoluter prädiktiver Ausschlussmarker.":"Μια δυσμενής συσχέτιση μετατρέπεται λανθασμένα σε απόλυτο προγνωστικό δείκτη αποκλεισμού.","PD-L1 hoch = sichere Antwort":"Υψηλό PD-L1 = βέβαιη ανταπόκριση","Auch ein etablierter Biomarker ist kein individuelles Response-Versprechen.":"Ακόμη και ένας καθιερωμένος βιοδείκτης δεν εγγυάται ατομική ανταπόκριση.","Jeden Kontextmarker erzwingen":"Επιβολή κάθε δείκτη συμφραζομένων","Mehr Messwerte erhöhen nicht automatisch die klinische Entscheidungsqualität.":"Περισσότερες μετρήσεις δεν βελτιώνουν αυτόματα την ποιότητα της κλινικής απόφασης.","Der 'resistente' Tumor hat PD-L1 TPS 70 %":"Ο «ανθεκτικός» όγκος έχει PD-L1 TPS 70%","Die nachgeforderte PD-L1-IHC zeigt eine hohe Expression von 70 %. Eine optionale Immun-Kontext-IHC zeigt gleichzeitig nur ein geringes CD8-Infiltrat. Statt einer eindeutigen Antwort entsteht ein scheinbarer Widerspruch: positive etablierte Information, adverse Ko-Mutationsbiologie und ein eher 'cold' wirkendes Mikromilieu.":"Η ζητηθείσα IHC PD-L1 δείχνει υψηλή έκφραση 70%. Μια προαιρετική IHC ανοσολογικού πλαισίου δείχνει ταυτόχρονα μόνο μικρή διήθηση CD8. Αντί για σαφή απάντηση προκύπτει μια φαινομενική αντίφαση: θετική καθιερωμένη πληροφορία, δυσμενής βιολογία συν-μεταλλάξεων και ένα μάλλον «ψυχρό» μικροπεριβάλλον.","Der Fall zwingt dazu, Biomarker nach Evidenzebene zu gewichten statt sie zu einem simplen Plus/Minus-Score zu verrechnen.":"Η περίπτωση απαιτεί στάθμιση των βιοδεικτών ανά επίπεδο τεκμηρίωσης και όχι αναγωγή τους σε ένα απλό σκορ συν/πλην.","Evidenzebenen getrennt":"Διαχωρισμένα επίπεδα τεκμηρίωσης","KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70 %. Ko-Mutationen werden als adverse Kontextmarker berichtet, nicht als absoluter ICI-Ausschluss.":"KRAS p.G12C + STK11/KEAP1· PD-L1 TPS 70%. Οι συν-μεταλλάξεις αναφέρονται ως δυσμενείς δείκτες πλαισίου και όχι ως απόλυτα κριτήρια αποκλεισμού ICI.","Sehr gute, klinisch belastbare Integration.":"Πολύ καλή, κλινικά ισχυρή ενσωμάτωση.","STK11/KEAP1 verbieten ICI":"STK11/KEAP1 απαγορεύουν ICI","Die Ko-Mutationen werden als definitive prädiktive Resistenzmarker ausgegeben.":"Οι συν-μεταλλάξεις αναφέρονται ως οριστικοί προγνωστικοί δείκτες αντοχής.","Overcalling: prognostisch/assoziativ wird mit binär prädiktiv verwechselt.":"Υπερερμηνεία: η προγνωστική/συσχετιστική τεκμηρίωση συγχέεται με δυαδική προβλεπτική τεκμηρίωση.","Nur PD-L1 zählt":"Μετρά μόνο το PD-L1","PD-L1 70 % wird ohne Genotyp- und Ko-Mutationskontext als eindeutige Antwort dargestellt.":"Το PD-L1 70% παρουσιάζεται ως σαφής απάντηση χωρίς το πλαίσιο γονοτύπου και συν-μεταλλάξεων.","Unvollständige Integration und zu starke Individualprognose.":"Ατελής ενσωμάτωση και υπερβολικά ισχυρή ατομική πρόγνωση.","PD-L1 fehlt":"Λείπει το PD-L1","PD-L1 ergänzen.":"Προσθέστε PD-L1.","Etablierte klinische Information steht für die MTB-Integration zur Verfügung.":"Υπάρχει διαθέσιμη καθιερωμένη κλινική πληροφορία για ενσωμάτωση στο MTB.","TMB/TILs gewählt":"Επιλέχθηκαν TMB/TILs","Als optionalen Kontext berichten.":"Αναφέρετε ως προαιρετικό πλαίσιο.","Kein zusätzlicher binärer Therapieentscheid aus diesen Daten.":"Δεν πρέπει να εξαχθεί πρόσθετη δυαδική θεραπευτική απόφαση από αυτά τα δεδομένα.","STK11/KEAP1 als Ausschluss formuliert":"STK11/KEAP1 διατυπωμένα ως αποκλεισμός","Befund sprachlich korrigieren.":"Διορθώστε τη διατύπωση της έκθεσης.","Prognostische/assoziierte Evidenz wird von prädiktiver Aussage getrennt.":"Η προγνωστική/συσχετιστική τεκμηρίωση διαχωρίζεται από τις προβλεπτικές δηλώσεις.","Ein molekulares Panel liefert nicht automatisch Marker gleicher klinischer Wertigkeit.":"Ένα μοριακό panel δεν παράγει αυτόματα δείκτες ίσης κλινικής αξίας.","STK11/KEAP1 sind wichtige adverse Kontextinformationen, aber keine simplen ICI-Ausschalter.":"Τα STK11/KEAP1 αποτελούν σημαντικές δυσμενείς πληροφορίες πλαισίου, αλλά όχι απλούς διακόπτες αποκλεισμού ICI.","PD-L1 bleibt relevant, ohne individuelle Antwort zu garantieren.":"Το PD-L1 παραμένει σχετικό χωρίς να εγγυάται ατομική ανταπόκριση.","Gute MTB-Kommunikation macht die Evidenzebene jeder Aussage sichtbar.":"Η καλή επικοινωνία στο MTB καθιστά σαφές το επίπεδο τεκμηρίωσης κάθε δήλωσης.","KRAS p.G12C wird als eigenständiger targetrelevanter Genotyp im passenden Therapiekontext berichtet. STK11/KEAP1 werden als adverse biologische/prognostische Ko-Alterationen eingeordnet, nicht als absolutes ICI-Verbot. PD-L1 TPS 70 % bleibt klinisch relevant. TMB/TILs können Kontext liefern, dürfen aber nicht überinterpretiert werden.":"Το KRAS p.G12C αναφέρεται ως ανεξάρτητος γονότυπος σχετικός με στοχευμένη θεραπεία στο κατάλληλο θεραπευτικό πλαίσιο. Τα STK11/KEAP1 ταξινομούνται ως δυσμενείς βιολογικές/προγνωστικές συν-αλλοιώσεις και όχι ως απόλυτη απαγόρευση ICI. Το PD-L1 TPS 70% παραμένει κλινικά σχετικό. TMB/TILs μπορούν να παρέχουν πλαίσιο, αλλά δεν πρέπει να υπερερμηνεύονται.","Keine binäre STK11/KEAP1-Überinterpretation":"Χωρίς δυαδική υπερερμηνεία των STK11/KEAP1","PD-L1 integriert":"PD-L1 ενσωματωμένο","KRAS-Targetebene getrennt":"Διαχωρισμένο επίπεδο στόχευσης KRAS","Zusatzmarker limitiert formuliert":"Οι πρόσθετοι δείκτες διατυπώνονται με περιορισμούς","Wann wird ein prognostischer Marker prädiktiv?":"Πότε ένας προγνωστικός δείκτης γίνεται προβλεπτικός;","Wie sollte ein Befund formuliert sein, damit die Onkologie die Evidenzebene sofort erkennt?":"Πώς πρέπει να διατυπώνεται μια έκθεση ώστε η ογκολογία να αναγνωρίζει αμέσως το επίπεδο τεκμηρίωσης;","Welche Rolle könnten Ko-Mutationen künftig für Therapiestratifizierung spielen, ohne heutige Routineentscheidungen vorwegzunehmen?":"Ποιο ρόλο θα μπορούσαν να παίξουν οι συν-μεταλλάξεις στη μελλοντική θεραπευτική διαστρωμάτωση χωρίς να προδικάζουν τις σημερινές αποφάσεις ρουτίνας;","PD-L1 70 % trotz STK11/KEAP1":"PD-L1 70% παρά STK11/KEAP1","Biomarker nach Evidenzebene gewichten":"Στάθμιση βιοδεικτών ανά επίπεδο τεκμηρίωσης","Genotyp → Ko-Mutationen → PD-L1 → integrierte Aussage":"Γονότυπος → συν-μεταλλάξεις → PD-L1 → ολοκληρωμένη δήλωση","Melanom: BRAF V600 und Immuntherapie-Sequenz → Schnelle TKI-Therapie vs. Immuncheckpoint-Strategie":"Μελάνωμα: BRAF V600 και αλληλουχία ανοσοθεραπείας → ταχεία στοχευμένη θεραπεία έναντι στρατηγικής immune checkpoint","Melanom: BRAF V600 und Immuntherap…":"Μελάνωμα: BRAF V600 και αλληλουχία ανοσοθερ…","Dermatoonkologie / Interdisziplinäres Tumorboard":"Δερματο-ογκολογία / Διεπιστημονικό ογκολογικό συμβούλιο","51-jähriger Patient mit neu metastasiertem kutanem Melanom, pulmonalen und hepatischen Metastasen.":"Ασθενής 51 ετών με νεοδιαγνωσμένο μεταστατικό δερματικό μελάνωμα, με πνευμονικές και ηπατικές μεταστάσεις.","Liegt eine BRAF-V600-Alteration vor und wie beeinflusst sie die Sequenz zwischen Immuncheckpoint- und BRAF/MEK-Strategie?":"Υπάρχει αλλοίωση BRAF V600 και πώς επηρεάζει την αλληλουχία μεταξύ στρατηγικής immune checkpoint και BRAF/MEK;","Systemische Therapie soll innerhalb weniger Tage beginnen.":"Η συστηματική θεραπεία πρέπει να αρχίσει εντός λίγων ημερών.","Performance":"Κατάσταση απόδοσης","ECOG 0–1, zunächst klinisch stabil.":"ECOG 0–1, αρχικά κλινικά σταθερός.","Tumorlast":"Φορτίο όγκου","Mehrere Lebermetastasen, LDH moderat erhöht, keine initialen neurologischen Symptome.":"Πολλαπλές ηπατικές μεταστάσεις, μέτρια αυξημένη LDH, χωρίς αρχικά νευρολογικά συμπτώματα.","Entscheidungsfalle":"Παγίδα απόφασης","Der Nachweis einer BRAF-V600-Mutation entscheidet nicht automatisch über die erste Therapiesequenz; klinisches Tempo, ZNS-Situation, Steroidbedarf und Eignung für Immuntherapie sind mitentscheidend.":"Η ανίχνευση μετάλλαξης BRAF V600 δεν καθορίζει αυτόματα την πρώτη θεραπευτική αλληλουχία· ο κλινικός ρυθμός, η κατάσταση του ΚΝΣ, η ανάγκη για στεροειδή και η καταλληλότητα για ανοσοθεραπεία συνυπολογίζονται.","Metastase eines malignen Melanoms.":"Μετάσταση κακοήθους μελανώματος.","SOX10 und S100 positiv, Melan-A fokal positiv.":"SOX10 και S100 θετικά, Melan-A εστιακά θετικό.","Molekulare Kernfrage":"Κεντρικό μοριακό ερώτημα","BRAF V600 muss rasch geklärt werden, damit beide strategischen Optionen realistisch bewertet werden können.":"Το BRAF V600 πρέπει να διευκρινιστεί γρήγορα ώστε και οι δύο στρατηγικές επιλογές να μπορούν να αξιολογηθούν ρεαλιστικά.","Nicht die Kernfrage":"Δεν είναι το κεντρικό ερώτημα","PD-L1, TMB oder TILs sind in diesem Fall keine einfachen Schalter für die Sequenzentscheidung.":"PD-L1, TMB ή TILs δεν αποτελούν απλούς διακόπτες για την απόφαση αλληλουχίας σε αυτή την περίπτωση.","FFPE-Lebermetastase, Block L4.":"FFPE ηπατική μετάσταση, block L4.","ca. 60 %, geringe Nekrose.":"περ. 60%, μικρή νέκρωση.","gut; rascher BRAF-Test technisch problemlos möglich.":"καλή· ο ταχύς έλεγχος BRAF είναι τεχνικά απλός.","10 ungefärbte Schnitte verfügbar.":"Διατίθενται 10 άχρωμες τομές.","Breite Zusatzdiagnostik darf die dringliche BRAF-Klärung nicht verzögern.":"Ο εκτεταμένος πρόσθετος έλεγχος δεν πρέπει να καθυστερεί την επείγουσα διευκρίνιση του BRAF.","BRAF V600-Status":"Κατάσταση BRAF V600","BRAF V600":"BRAF V600","BRAF p.V600E nachweisbar. Damit ist eine BRAF/MEK-basierte Therapieoption grundsätzlich vorhanden.":"Ανιχνεύεται BRAF p.V600E. Επομένως υπάρχει κατ’ αρχήν θεραπευτική επιλογή βασισμένη σε BRAF/MEK.","Melanom-IO-Kontext":"Πλαίσιο IO μελανώματος","Immunhistologischer Kontext ohne eindeutigen Ausschlussbefund. Die Sequenzentscheidung bleibt primär klinisch-strategisch und wird nicht durch einen einzelnen IHC-Marker festgelegt.":"Ανοσοϊστολογικό πλαίσιο χωρίς σαφές εύρημα αποκλεισμού. Η απόφαση αλληλουχίας παραμένει κυρίως κλινικο-στρατηγική και δεν καθορίζεται από έναν μόνο δείκτη IHC.","TMB erhöht. Dies ersetzt weder die BRAF-Testung noch die klinische Sequenzentscheidung.":"Αυξημένο TMB. Αυτό δεν αντικαθιστά ούτε τον έλεγχο BRAF ούτε την κλινική απόφαση αλληλουχίας.","Tumoranteil und DNA-Qualität sind gut; BRAF-V600-Status ist rasch und belastbar bestimmbar.":"Το ποσοστό όγκου και η ποιότητα DNA είναι καλά· η κατάσταση BRAF V600 μπορεί να προσδιοριστεί γρήγορα και αξιόπιστα.","BRAF p.V600E ist nachweisbar und eröffnet eine BRAF/MEK-Option. Bei zunächst klinisch stabilem, immuntherapiefähigem Patienten spricht die Evidenz häufig für eine Immuntherapie-first-Strategie; bei rascher klinischer Verschlechterung oder notwendigem schnellen Tumoransprechen kann sich die Gewichtung zugunsten einer zielgerichteten Therapie verschieben.":"Ανιχνεύεται BRAF p.V600E και δημιουργείται επιλογή BRAF/MEK. Σε αρχικά κλινικά σταθερό ασθενή κατάλληλο για ανοσοθεραπεία, η τεκμηρίωση συχνά ευνοεί στρατηγική ανοσοθεραπείας πρώτα· σε ταχεία κλινική επιδείνωση ή ανάγκη για γρήγορη συρρίκνωση του όγκου, η στάθμιση μπορεί να μετακινηθεί προς στοχευμένη θεραπεία.","Teilbefund: Ohne geklärten BRAF-V600-Status fehlt eine zentrale Voraussetzung für die Sequenzplanung. Zusätzliche IO-Kontextmarker ersetzen diese Klärung nicht.":"Μερικό εύρημα: Χωρίς διευκρινισμένη κατάσταση BRAF V600 λείπει βασική προϋπόθεση για τον σχεδιασμό της αλληλουχίας. Πρόσθετοι δείκτες IO δεν αντικαθιστούν αυτή τη διευκρίνιση.","BRAF V600 als Voraussetzung für eine BRAF/MEK-Option benennen":"Αναφέρετε το BRAF V600 ως προϋπόθεση για επιλογή BRAF/MEK","Therapiesequenz nicht allein aus dem Mutationsstatus ableiten":"Μην εξάγετε τη θεραπευτική αλληλουχία μόνο από την κατάσταση μετάλλαξης","Tumorlast, klinisches Tempo, ZNS-Beteiligung/Steroidbedarf und Immuntherapiefähigkeit berücksichtigen":"Λάβετε υπόψη φορτίο όγκου, κλινικό ρυθμό, συμμετοχή ΚΝΣ/ανάγκη στεροειδών και καταλληλότητα για ανοσοθεραπεία","PD-L1/TMB/TILs nicht als simplen Sequenzschalter verwenden":"Μην χρησιμοποιείτε PD-L1/TMB/TILs ως απλό διακόπτη αλληλουχίας","Optimale Lösung: BRAF V600 rasch klären und anschließend die Sequenz anhand von Evidenz und klinischer Dynamik entscheiden; Mutation vorhanden bedeutet nicht automatisch 'Targeted Therapy zuerst'.":"Βέλτιστη λύση: Διευκρινίστε γρήγορα το BRAF V600 και στη συνέχεια αποφασίστε την αλληλουχία βάσει τεκμηρίωσης και κλινικής δυναμικής· η παρουσία μετάλλαξης δεν σημαίνει αυτόματα «στοχευμένη θεραπεία πρώτα».","BRAF":"BRAF","KI":"AI","Melanom":"Μελάνωμα","BRAF-V600-Melanom: Die Mutation eröffnet eine Option – die Klinik bestimmt die Sequenz":"Μελάνωμα BRAF V600: Η μετάλλαξη ανοίγει μια επιλογή – η κλινική κατάσταση καθορίζει την αλληλουχία","Molekularpathologie / Dermatoonkologie / MTB":"Μοριακή παθολογία / Δερματο-ογκολογία / MTB","BRAF V600 als prädiktiven Marker für eine Target-Option korrekt bestimmen.":"Προσδιορίστε σωστά το BRAF V600 ως προβλεπτικό δείκτη για επιλογή στοχευμένης θεραπείας.","Den BRAF-Nachweis nicht mit einer automatischen Targeted-Therapy-first-Entscheidung verwechseln.":"Μην συγχέετε την ανίχνευση BRAF με αυτόματη απόφαση στοχευμένης θεραπείας πρώτα.","Klinisches Tempo, Tumorlast, ZNS-Beteiligung, Steroidbedarf und Immuntherapiefähigkeit in die Sequenz einbeziehen.":"Ενσωματώστε τον κλινικό ρυθμό, το φορτίο όγκου, τη συμμετοχή ΚΝΣ, την ανάγκη στεροειδών και την καταλληλότητα για ανοσοθεραπεία στην αλληλουχία.","PD-L1/TMB/TILs beim Melanom nicht als einfachen Sequenzschalter überinterpretieren.":"Μην υπερερμηνεύετε PD-L1/TMB/TILs στο μελάνωμα ως απλό διακόπτη αλληλουχίας.","Freitagnachmittag im Melanomboard. Ein 51-jähriger Patient mit neu metastasiertem Melanom ist BRAF noch nicht getestet. Die Onkologie diskutiert bereits zwei sehr unterschiedliche Strategien: zuerst Immuncheckpoint-Therapie mit Aussicht auf langanhaltende Kontrolle oder – falls BRAF V600 positiv – eine BRAF/MEK-Therapie mit typischerweise rascherem Ansprechen. Noch wirkt der Patient klinisch stabil. Die Frage scheint planbar. Zwei Tage später ändert sich die Situation.":"Παρασκευή απόγευμα στο συμβούλιο μελανώματος. Ένας ασθενής 51 ετών με νεομεταστατικό μελάνωμα δεν έχει ακόμη ελεγχθεί για BRAF. Η ογκολογική ομάδα συζητά ήδη δύο πολύ διαφορετικές στρατηγικές: πρώτα θεραπεία immune checkpoint με προοπτική μακροχρόνιου ελέγχου ή – εάν BRAF V600 θετικό – θεραπεία BRAF/MEK με συνήθως ταχύτερη ανταπόκριση. Ο ασθενής φαίνεται ακόμη κλινικά σταθερός. Η απόφαση μοιάζει προγραμματίσιμη. Δύο ημέρες αργότερα η κατάσταση αλλάζει.","51-jähriger Patient, kutanes Melanom mit Leber- und Lungenmetastasen, ECOG 0–1, moderat erhöhtes LDH. Keine systemische Vorbehandlung. Zunächst keine neurologischen Symptome. Für die Sequenzentscheidung muss der BRAF-V600-Status rasch vorliegen; die endgültige Strategie darf aber nicht allein aus dem Genotyp abgeleitet werden.":"Ασθενής 51 ετών, δερματικό μελάνωμα με ηπατικές και πνευμονικές μεταστάσεις, ECOG 0–1, μέτρια αυξημένη LDH. Χωρίς προηγούμενη συστηματική θεραπεία. Αρχικά χωρίς νευρολογικά συμπτώματα. Η κατάσταση BRAF V600 πρέπει να είναι γρήγορα διαθέσιμη για την απόφαση αλληλουχίας, αλλά η τελική στρατηγική δεν πρέπει να προκύπτει μόνο από τον γονότυπο.","Molekulare Voraussetzung":"Μοριακή προϋπόθεση","Ohne BRAF-V600-Nachweis gibt es keine belastbare Grundlage für eine BRAF/MEK-Strategie.":"Χωρίς ανίχνευση BRAF V600 δεν υπάρχει ισχυρή βάση για στρατηγική BRAF/MEK.","Erst Option nachweisen, dann Sequenz diskutieren.":"Πρώτα τεκμηριώστε την επιλογή και μετά συζητήστε την αλληλουχία.","Initiale Klinik":"Αρχική κλινική κατάσταση","ECOG 0–1, systemisch metastasiert, aber zunächst keine akute Organ- oder ZNS-Symptomatik.":"ECOG 0–1, συστηματικά μεταστατική νόσος, αλλά αρχικά χωρίς οξέα συμπτώματα οργάνων ή ΚΝΣ.","Bei klinischer Stabilität kann Langzeitstrategie stärker gewichtet werden.":"Σε κλινική σταθερότητα, η μακροπρόθεσμη στρατηγική μπορεί να σταθμιστεί περισσότερο.","Evidenz zur Sequenz":"Τεκμηρίωση για την αλληλουχία","Für viele geeignete Patienten mit BRAF-V600-mutiertem metastasiertem Melanom spricht die randomisierte Sequenzevidenz für Immuntherapie zuerst; dies ist aber keine starre Regel für jede klinische Situation.":"Για πολλούς κατάλληλους ασθενείς με μεταστατικό μελάνωμα BRAF V600-mutant, η τυχαιοποιημένη τεκμηρίωση αλληλουχίας υποστηρίζει ανοσοθεραπεία πρώτα· ωστόσο δεν αποτελεί άκαμπτο κανόνα για κάθε κλινική κατάσταση.","Populationsevidenz und individuelle Dringlichkeit müssen zusammengeführt werden.":"Η τεκμηρίωση σε επίπεδο πληθυσμού και η ατομική επείγουσα ανάγκη πρέπει να συνδυάζονται.","Nicht der Schalter":"Δεν είναι ο διακόπτης","PD-L1, TMB und TILs können biologisch interessant sein, ersetzen aber weder BRAF-Testung noch die klinische Sequenzentscheidung.":"PD-L1, TMB και TILs μπορεί να έχουν βιολογικό ενδιαφέρον, αλλά δεν αντικαθιστούν ούτε τον έλεγχο BRAF ούτε την κλινική απόφαση αλληλουχίας.","Nicht jedes messbare Immunmerkmal ist ein Routine-Entscheidungstest.":"Δεν αποτελεί κάθε μετρήσιμο ανοσολογικό χαρακτηριστικό εξέταση ρουτίνας για λήψη αποφάσεων.","Histologie/IHC":"Ιστολογία/IHC","Metastase eines SOX10-/S100-positiven malignen Melanoms.":"Μετάσταση κακοήθους μελανώματος θετικού για SOX10/S100.","Klinik initial":"Αρχική κλινική κατάσταση","Keine symptomatische ZNS-Beteiligung; keine Steroidtherapie.":"Χωρίς συμπτωματική συμμετοχή του ΚΝΣ· χωρίς θεραπεία με στεροειδή.","Material-QC":"QC υλικού","Lebermetastase mit ca. 60 % Tumor; DNA-QC gut.":"Ηπατική μετάσταση με περ. 60% όγκο· καλό QC DNA.","BRAF-V600-Status muss rasch vorliegen; unnötige Zusatzanalysen dürfen die Entscheidung nicht verzögern.":"Η κατάσταση BRAF V600 πρέπει να είναι γρήγορα διαθέσιμη· περιττές πρόσθετες αναλύσεις δεν πρέπει να καθυστερούν την απόφαση.","Therapiesequenz kann nicht aus der Pathologie allein entschieden werden; aktuelle klinische Dynamik muss ins MTB zurückgespielt werden.":"Η θεραπευτική αλληλουχία δεν μπορεί να αποφασιστεί μόνο από την παθολογία· η τρέχουσα κλινική δυναμική πρέπει να επιστρέφει στο MTB.","PD-L1/TMB/TILs sind nicht als zwingende Sequenzmarker definiert.":"PD-L1/TMB/TILs δεν ορίζονται ως υποχρεωτικοί δείκτες αλληλουχίας.","Welche molekulare Information muss für die Targeted-Therapy-Option zuerst belastbar vorliegen?":"Ποια μοριακή πληροφορία πρέπει πρώτα να είναι αξιόπιστα διαθέσιμη για την επιλογή στοχευμένης θεραπείας;","PD-L1 zwingend":"PD-L1 υποχρεωτικό","TMB zwingend":"TMB υποχρεωτικό","CD8/TIL-IHC zwingend":"IHC CD8/TIL υποχρεωτική","BRAF V600 ist die zentrale molekulare Voraussetzung für eine BRAF/MEK-basierte Option.":"Το BRAF V600 είναι η βασική μοριακή προϋπόθεση για επιλογή βασισμένη σε BRAF/MEK.","Welche Faktoren beeinflussen die Sequenzentscheidung zusätzlich zum BRAF-Status?":"Ποιοι παράγοντες επηρεάζουν την αλληλουχία επιπλέον της κατάστασης BRAF;","Klinisches Progressionstempo und Tumorlast":"Κλινικός ρυθμός εξέλιξης και φορτίο όγκου","ZNS-Beteiligung und neurologische Symptomatik":"Συμμετοχή ΚΝΣ και νευρολογικά συμπτώματα","Steroidbedarf/Immuntherapiefähigkeit":"Ανάγκη στεροειδών/καταλληλότητα για ανοσοθεραπεία","Allgemeinzustand und Eignung für die jeweiligen Regime":"Γενική κατάσταση και καταλληλότητα για τα αντίστοιχα σχήματα","Alleiniger PD-L1-Wert als Sequenzschalter":"Μόνο η τιμή PD-L1 ως διακόπτης αλληλουχίας","Die Sequenz ist eine klinisch-strategische Entscheidung, nicht nur eine Genotypentscheidung.":"Η αλληλουχία είναι κλινικο-στρατηγική απόφαση, όχι απλώς απόφαση γονοτύπου.","Der Patient ist BRAF V600E-positiv und klinisch stabil. Welche Aussage ist am besten?":"Ο ασθενής είναι BRAF V600E-θετικός και κλινικά σταθερός. Ποια δήλωση είναι η καλύτερη;","Für viele geeignete Patienten spricht die Sequenzevidenz für Immuntherapie-first; individuelle Faktoren bleiben entscheidend.":"Για πολλούς κατάλληλους ασθενείς, η τεκμηρίωση αλληλουχίας υποστηρίζει ανοσοθεραπεία πρώτα· οι ατομικοί παράγοντες παραμένουν καθοριστικοί.","BRAF V600E bedeutet zwingend BRAF/MEK zuerst.":"Το BRAF V600E επιβάλλει BRAF/MEK πρώτα.","Bei BRAF-Mutation sollte Immuntherapie nicht eingesetzt werden.":"Η ανοσοθεραπεία δεν πρέπει να χρησιμοποιείται όταν υπάρχει μετάλλαξη BRAF.","Erst PD-L1 entscheidet, ob BRAF/MEK oder Immuntherapie beginnt.":"Μόνο το PD-L1 αποφασίζει εάν θα αρχίσει BRAF/MEK ή ανοσοθεραπεία.","Randomisierte Sequenzdaten favorisieren bei vielen geeigneten Patienten Immuntherapie-first, ohne jede dringliche Ausnahmesituation abzudecken.":"Τα τυχαιοποιημένα δεδομένα αλληλουχίας ευνοούν ανοσοθεραπεία πρώτα σε πολλούς κατάλληλους ασθενείς, χωρίς να καλύπτουν κάθε επείγουσα εξαιρετική κατάσταση.","Bestimmen Sie den BRAF-V600-Status und formulieren Sie anschließend eine Sequenzempfehlung, die Evidenz und aktuelle klinische Dynamik ausdrücklich miteinander verknüpft.":"Προσδιορίστε την κατάσταση BRAF V600 και στη συνέχεια διατυπώστε σύσταση αλληλουχίας που συνδέει ρητά την τεκμηρίωση με την τρέχουσα κλινική δυναμική.","BRAF-V600-Testung rasch durchführen.":"Διενεργήστε ταχέως έλεγχο BRAF V600.","Bei BRAF p.V600E beide prinzipiellen Strategien als verfügbar benennen.":"Σε BRAF p.V600E, αναφέρετε ότι και οι δύο βασικές στρατηγικές είναι διαθέσιμες.","Bei klinisch stabilem, immuntherapiefähigem Patienten die Evidenz für Immuntherapie-first diskutieren.":"Σε κλινικά σταθερό ασθενή κατάλληλο για ανοσοθεραπεία, συζητήστε την τεκμηρίωση υπέρ ανοσοθεραπείας πρώτα.","Vor Therapiebeginn aktuelle ZNS-Situation, Steroidbedarf und Progressionstempo erneut prüfen.":"Πριν από την έναρξη θεραπείας, επανεκτιμήστε την τρέχουσα κατάσταση ΚΝΣ, την ανάγκη στεροειδών και τον ρυθμό εξέλιξης.","Bei akuter Dynamik die Notwendigkeit schnellen Ansprechens neu gewichten.":"Σε οξεία κλινική δυναμική, επανασταθμίστε την ανάγκη για ταχεία ανταπόκριση.","Validiertes breites Panel, wenn BRAF V600 ohne relevante Verzögerung sicher erfasst wird.":"Επικυρωμένο ευρύ panel εφόσον καλύπτει αξιόπιστα BRAF V600 χωρίς σημαντική καθυστέρηση.","Targeted Therapy first bei dringlicher klinischer Situation oder wenn Immuntherapie nicht geeignet ist; dies muss explizit klinisch begründet werden.":"Στοχευμένη θεραπεία πρώτα σε επείγουσα κλινική κατάσταση ή όταν η ανοσοθεραπεία δεν είναι κατάλληλη· αυτό πρέπει να αιτιολογείται ρητά κλινικά.","BRAF-mutiert = automatisch Targeted Therapy first":"BRAF-mutant = αυτόματα στοχευμένη θεραπεία πρώτα","Der Genotyp eröffnet die Option, entscheidet aber nicht alleine die optimale Sequenz.":"Ο γονότυπος ανοίγει την επιλογή αλλά δεν καθορίζει μόνος του τη βέλτιστη αλληλουχία.","PD-L1 entscheidet die Reihenfolge":"Το PD-L1 αποφασίζει την αλληλουχία","Beim metastasierten Melanom ist PD-L1 kein einfacher Sequenzschalter zwischen BRAF/MEK und Immuntherapie.":"Στο μεταστατικό μελάνωμα, το PD-L1 δεν είναι απλός διακόπτης αλληλουχίας μεταξύ BRAF/MEK και ανοσοθεραπείας.","Klinik vom Molekularbefund trennen":"Διαχωρισμός κλινικής κατάστασης από το μοριακό εύρημα","Eine Sequenzentscheidung kann sich durch akute Progression innerhalb von Tagen verändern.":"Μια απόφαση αλληλουχίας μπορεί να αλλάξει μέσα σε ημέρες λόγω οξείας εξέλιξης.","48 Stunden später: neue symptomatische Hirnmetastase":"48 ώρες αργότερα: νέα συμπτωματική εγκεφαλική μετάσταση","Noch vor Therapiebeginn entwickelt der Patient Kopfschmerzen und eine diskrete Hemiparese. Das MRT zeigt eine neue symptomatische Hirnmetastase; Dexamethason wird begonnen. Gleichzeitig liegt der molekulare Befund vor: BRAF p.V600E. Die ursprünglich in Ruhe geplante Sequenz muss unter dem Gesichtspunkt rascher Krankheitskontrolle und Steroidbedarf neu diskutiert werden.":"Πριν από την έναρξη θεραπείας, ο ασθενής εμφανίζει κεφαλαλγία και ήπια ημιπάρεση. Η MRI δείχνει νέα συμπτωματική εγκεφαλική μετάσταση και αρχίζει δεξαμεθαζόνη. Ταυτόχρονα είναι διαθέσιμο το μοριακό αποτέλεσμα: BRAF p.V600E. Η αρχικά σχεδιασμένη αλληλουχία πρέπει τώρα να επανεξεταστεί με γνώμονα την ανάγκη ταχείας ελέγχου της νόσου και τη χρήση στεροειδών.","Der molekulare Befund ist unverändert, aber die klinische Priorität hat sich verändert. Genau deshalb darf BRAF V600 nie isoliert als Sequenzautomat interpretiert werden.":"Το μοριακό εύρημα παραμένει ίδιο, αλλά η κλινική προτεραιότητα άλλαξε. Γι’ αυτό ακριβώς το BRAF V600 δεν πρέπει ποτέ να ερμηνεύεται απομονωμένα ως αυτόματη εντολή αλληλουχίας.","BRAF positiv, Klinik integriert":"BRAF θετικό, ενσωματωμένο κλινικό πλαίσιο","BRAF p.V600E nachweisbar. Beide Strategien sind grundsätzlich verfügbar; nach klinischer Verschlechterung wird die Notwendigkeit schneller Kontrolle im MTB neu gewichtet.":"Ανιχνεύεται BRAF p.V600E. Και οι δύο στρατηγικές είναι κατ’ αρχήν διαθέσιμες· μετά την κλινική επιδείνωση, η ανάγκη ταχείας ελέγχου επανασταθμίζεται στο MTB.","Sehr gute Verbindung von molekularer Option und klinischer Situation.":"Πολύ καλή σύνδεση μεταξύ μοριακής επιλογής και κλινικής κατάστασης.","Mutation entscheidet alles":"Η μετάλλαξη αποφασίζει τα πάντα","BRAF p.V600E wird automatisch mit 'BRAF/MEK zuerst' gleichgesetzt, unabhängig von Klinik und Sequenzevidenz.":"Το BRAF p.V600E εξισώνεται αυτόματα με «BRAF/MEK πρώτα», ανεξάρτητα από το κλινικό πλαίσιο και την τεκμηρίωση αλληλουχίας.","Zu mechanistisch; Option und Sequenz wurden verwechselt.":"Υπερβολικά μηχανιστικό· η ύπαρξη επιλογής συγχέεται με την αλληλουχία.","Nur IO-Kontextmarker":"Μόνο δείκτες πλαισίου IO","PD-L1/TMB/TILs werden breit untersucht, BRAF bleibt ausstehend.":"PD-L1/TMB/TILs εξετάζονται ευρέως ενώ το BRAF παραμένει σε εκκρεμότητα.","Die zentrale molekulare Voraussetzung für eine Targeted-Therapy-Option fehlt.":"Λείπει η βασική μοριακή προϋπόθεση για επιλογή στοχευμένης θεραπείας.","BRAF V600E positiv, klinisch stabil":"BRAF V600E θετικό, κλινικά σταθερός","Immuntherapie-first als evidenzgestützte Standardstrategie für viele geeignete Patienten diskutieren.":"Συζητήστε την ανοσοθεραπεία πρώτα ως τεκμηριωμένη στρατηγική standard για πολλούς κατάλληλους ασθενείς.","Langfristige Sequenzplanung steht im Vordergrund.":"Η μακροπρόθεσμη στρατηγική αλληλουχίας βρίσκεται στο προσκήνιο.","Neue symptomatische ZNS-Progression/Steroidbedarf":"Νέα συμπτωματική εξέλιξη ΚΝΣ/ανάγκη στεροειδών","Sequenz im MTB sofort neu bewerten und schnelle Krankheitskontrolle stärker gewichten.":"Επανεκτιμήστε άμεσα την αλληλουχία στο MTB και δώστε μεγαλύτερη βαρύτητα στον ταχύ έλεγχο της νόσου.","Targeted Therapy kann klinisch an Gewicht gewinnen.":"Η στοχευμένη θεραπεία μπορεί να αποκτήσει μεγαλύτερη κλινική βαρύτητα.","BRAF nicht bestimmt":"BRAF μη προσδιορισμένο","Schnelltest nachfordern.":"Ζητήστε ταχεία εξέταση.","Sequenzentscheidung bleibt unvollständig.":"Η απόφαση αλληλουχίας παραμένει ελλιπής.","BRAF V600 ist ein prädiktiver Marker für eine Target-Option, kein automatischer Sequenzbefehl.":"Το BRAF V600 είναι προβλεπτικός δείκτης για στοχευμένη επιλογή, όχι αυτόματη εντολή αλληλουχίας.","Bei vielen geeigneten, stabilen Patienten spricht randomisierte Sequenzevidenz für Immuntherapie-first.":"Για πολλούς κατάλληλους και σταθερούς ασθενείς, η τυχαιοποιημένη τεκμηρίωση αλληλουχίας υποστηρίζει ανοσοθεραπεία πρώτα.","Akute klinische Dynamik kann die optimale Reihenfolge verändern.":"Η οξεία κλινική δυναμική μπορεί να αλλάξει τη βέλτιστη σειρά.","Molekularpathologie ist Teil der Entscheidung, aber nicht deren alleiniger Eigentümer.":"Η μοριακή παθολογία αποτελεί μέρος της απόφασης, αλλά δεν είναι ο μοναδικός της ιδιοκτήτης.","BRAF p.V600E wird rasch bestätigt. Zunächst wäre bei klinischer Stabilität für viele geeignete Patienten Immuntherapie-first evidenzgestützt. Der Twist – symptomatische Hirnmetastase mit Steroidbedarf – erzwingt eine erneute klinische Gewichtung und kann die Bedeutung einer rasch wirksamen BRAF/MEK-Strategie erhöhen. PD-L1/TMB/TILs sind kein einfacher Sequenzschalter.":"Το BRAF p.V600E επιβεβαιώνεται γρήγορα. Αρχικά, σε κλινική σταθερότητα, ανοσοθεραπεία πρώτα θα ήταν τεκμηριωμένη για πολλούς κατάλληλους ασθενείς. Η ανατροπή – συμπτωματική εγκεφαλική μετάσταση με ανάγκη στεροειδών – επιβάλλει νέα κλινική στάθμιση και μπορεί να αυξήσει τη σημασία μιας ταχέως αποτελεσματικής στρατηγικής BRAF/MEK. PD-L1/TMB/TILs δεν αποτελούν απλό διακόπτη αλληλουχίας.","BRAF als Voraussetzung erkannt":"BRAF αναγνωρίστηκε ως προϋπόθεση","Keine automatische Targeted-first-Regel":"Χωρίς αυτόματο κανόνα στοχευμένης θεραπείας πρώτα","Klinische Dynamik integriert":"Ενσωματωμένη κλινική δυναμική","IO-Kontextmarker nicht überinterpretiert":"Οι δείκτες πλαισίου IO δεν υπερερμηνεύονται","Welche Patientengruppen waren in Sequenzstudien besonders gut repräsentiert – und welche weniger?":"Ποιες ομάδες ασθενών εκπροσωπήθηκαν ιδιαίτερα καλά στις μελέτες αλληλουχίας – και ποιες λιγότερο;","Wie ändert Steroidbedarf die praktische Immuntherapieplanung?":"Πώς αλλάζει η ανάγκη στεροειδών τον πρακτικό σχεδιασμό ανοσοθεραπείας;","Welche Information muss die Pathologie liefern und welche Entscheidung bleibt interdisziplinär?":"Ποια πληροφορία πρέπει να παρέχει η παθολογία και ποια απόφαση παραμένει διεπιστημονική;","symptomatische Hirnmetastase nach initial stabiler Situation":"συμπτωματική εγκεφαλική μετάσταση μετά από αρχικά σταθερή κατάσταση","Mutation eröffnet Option, Klinik bestimmt Sequenz":"Η μετάλλαξη ανοίγει την επιλογή, η κλινική κατάσταση καθορίζει την αλληλουχία","BRAF-Test → stabile Sequenzplanung → klinischer Twist → Re-Assessment":"Έλεγχος BRAF → σταθερός σχεδιασμός αλληλουχίας → κλινική ανατροπή → επανεκτίμηση","GIST mit KIT/PDGFRA-Fragestellung → Welcher Marker entscheidet über TKI-Auswahl?":"GIST με ερώτημα KIT/PDGFRA → Ποιος δείκτης καθορίζει την επιλογή TKI;","GIST mit KIT/PDGFRA-Fragestellung":"GIST με ερώτημα KIT/PDGFRA","Sarkomzentrum / MTB":"Κέντρο σαρκωμάτων / MTB","64-jährige Patientin mit gastralem GIST und neu aufgetretenen Lebermetastasen.":"Γυναίκα 64 ετών με γαστρικό GIST και νέες ηπατικές μεταστάσεις.","Ist 'GIST = Imatinib' ausreichend, oder muss vor der TKI-Auswahl der KIT/PDGFRA-Genotyp vorliegen?":"Αρκεί το «GIST = imatinib» ή πρέπει να είναι γνωστός ο γονότυπος KIT/PDGFRA πριν από την επιλογή TKI;","Therapiebeginn ist nach Abschluss der molekularen Typisierung geplant.":"Η θεραπεία προγραμματίζεται να αρχίσει μετά την ολοκλήρωση της μοριακής τυποποίησης.","Primärtumor":"Πρωτοπαθής όγκος","Gastraler GIST, vor drei Jahren reseziert; nun hepatische Metastasierung.":"Γαστρικό GIST που εξαιρέθηκε πριν από τρία χρόνια· τώρα ηπατικές μεταστάσεις.","Keine systemische TKI-Therapie.":"Χωρίς συστηματική θεραπεία TKI.","Klinischer Reflex":"Κλινικό αντανακλαστικό","Im Tumorboard fällt früh der Satz: 'CD117-positiver GIST – dann Imatinib.'":"Νωρίς στο ογκολογικό συμβούλιο ακούγεται: «CD117-θετικό GIST – άρα imatinib.»","Lernziel":"Μαθησιακός στόχος","Diagnosemarker und prädiktiver Genotyp müssen getrennt werden.":"Οι διαγνωστικοί δείκτες και ο προβλεπτικός γονότυπος πρέπει να διαχωρίζονται.","Epithelioider mesenchymaler Tumor, morphologisch passend zu GIST.":"Επιθηλιοειδής μεσεγχυματικός όγκος, μορφολογικά συμβατός με GIST.","DOG1 stark positiv, CD117 nur fokal/heterogen positiv.":"DOG1 έντονα θετικό, CD117 μόνο εστιακά/ετερογενώς θετικό.","Arbeitsdiagnose":"Διάγνωση εργασίας","Metastasierter gastrointestinaler Stromatumor.":"Μεταστατικός γαστρεντερικός στρωματικός όγκος.","Welcher KIT-/PDGFRA-Genotyp liegt vor und verändert er die TKI-Auswahl?":"Ποιος γονότυπος KIT/PDGFRA υπάρχει και αλλάζει την επιλογή TKI;","FFPE-Lebermetastase, Block H3.":"FFPE ηπατική μετάσταση, block H3.","ca. 75 %, DNA-QC gut.":"περ. 75%, καλό QC DNA.","6 ungefärbte Schnitte verfügbar.":"Διατίθενται 6 άχρωμες τομές.","Ein sehr breites Pan-Tumor-Panel ist für die konkrete Erstfrage unnötig, wenn eine valide KIT/PDGFRA-Analyse verfügbar ist.":"Ένα πολύ ευρύ pan-tumor panel είναι περιττό για το συγκεκριμένο αρχικό ερώτημα όταν υπάρχει έγκυρη ανάλυση KIT/PDGFRA.","KIT/PDGFRA-Genotyp":"Γονότυπος KIT/PDGFRA","KIT/PDGFRA":"KIT/PDGFRA","PDGFRA Exon 18 p.D842V nachweisbar; keine aktivierende KIT-Mutation. Die Konstellation ist für die TKI-Auswahl unmittelbar relevant.":"Ανιχνεύεται PDGFRA exon 18 p.D842V· δεν υπάρχει ενεργοποιητική μετάλλαξη KIT. Η συνύπαρξη αυτή είναι άμεσα σχετική με την επιλογή TKI.","Hoher Tumoranteil, DNA-Qualität gut; gezielte KIT/PDGFRA-Analyse vollständig auswertbar.":"Υψηλό ποσοστό όγκου, καλή ποιότητα DNA· η στοχευμένη ανάλυση KIT/PDGFRA είναι πλήρως αξιολογήσιμη.","Metastasierter GIST mit PDGFRA p.D842V. Der Genotyp widerspricht dem reflexhaften 'Imatinib für jeden GIST'-Schema und verlangt eine genotypspezifische TKI-Strategie.":"Μεταστατικό GIST με PDGFRA p.D842V. Ο γονότυπος αναιρεί το αντανακλαστικό «imatinib για κάθε GIST» και απαιτεί γονοτυπο-ειδική στρατηγική TKI.","Teilbefund: Die GIST-Diagnose ist morphologisch/IHC-basiert gesichert, aber ohne KIT/PDGFRA-Genotyp ist die prädiktive TKI-Einordnung unvollständig.":"Μερικό εύρημα: Η διάγνωση GIST έχει τεκμηριωθεί μορφολογικά/IHC, αλλά χωρίς γονότυπο KIT/PDGFRA η προβλεπτική ταξινόμηση για TKI είναι ελλιπής.","DOG1/CD117 als Diagnosekontext, nicht als ausreichenden prädiktiven Marker einordnen":"Ταξινομήστε DOG1/CD117 ως διαγνωστικό πλαίσιο και όχι ως επαρκείς προβλεπτικούς δείκτες","PDGFRA D842V explizit benennen":"Αναφέρετε ρητά PDGFRA D842V","Genotypspezifische TKI-Auswahl statt pauschalem Imatinib-Reflex formulieren":"Διατυπώστε γονοτυπο-ειδική επιλογή TKI αντί γενικευμένου αντανακλαστικού imatinib","Bei KIT/PDGFRA-Wildtyp weitere molekulare Subklassifikation als mögliche Folgefrage erwähnen, ohne sie in diesem Fall zu erzwingen":"Σε KIT/PDGFRA wild type, αναφέρετε περαιτέρω μοριακή υποταξινόμηση ως πιθανό επόμενο βήμα χωρίς να την επιβάλλετε σε αυτή την περίπτωση","Optimale Lösung: KIT/PDGFRA gezielt bestimmen. Der Nachweis von PDGFRA p.D842V ist der Twist, der die TKI-Auswahl gegenüber einem pauschalen Imatinib-Ansatz verändert.":"Βέλτιστη λύση: Διενεργήστε στοχευμένο έλεγχο KIT/PDGFRA. Η ανίχνευση PDGFRA p.D842V είναι η ανατροπή που αλλάζει την επιλογή TKI σε σχέση με μια γενικευμένη προσέγγιση imatinib.","KIT":"KIT","PDGFRA":"PDGFRA","GIST":"GIST","Mini":"Mini","GIST ist nicht gleich Imatinib: PDGFRA D842V kippt den TKI-Reflex":"GIST δεν σημαίνει imatinib: το PDGFRA D842V ανατρέπει το αντανακλαστικό TKI","Molekularpathologie / Sarkompathologie / MTB":"Μοριακή παθολογία / Παθολογία σαρκωμάτων / MTB","GIST-Diagnosemarker und prädiktiven KIT/PDGFRA-Genotyp klar trennen.":"Διαχωρίστε σαφώς τους διαγνωστικούς δείκτες GIST από τον προβλεπτικό γονότυπο KIT/PDGFRA.","Vor systemischer TKI-Therapie die für Sensitivität/Resistenz relevante Mutationsklasse bestimmen.":"Πριν από συστηματική θεραπεία TKI, προσδιορίστε την κατηγορία μετάλλαξης που σχετίζεται με ευαισθησία/αντοχή.","PDGFRA D842V als klinisch entscheidenden Sonderfall erkennen.":"Αναγνωρίστε το PDGFRA D842V ως κλινικά καθοριστική ειδική περίπτωση.","Für eine fokussierte klinische Frage eine gezielte, ressourcenschonende Methode wählen.":"Επιλέξτε εστιασμένη, αποδοτική ως προς τους πόρους μέθοδο για ένα εστιασμένο κλινικό ερώτημα.","Im Sarkomboard ist der Fall scheinbar in zehn Sekunden erledigt: metastasierter GIST, DOG1 positiv, also Imatinib. Die Pathologin stoppt die Diskussion mit einer einfachen Frage: 'Welcher KIT- oder PDGFRA-Genotyp liegt eigentlich vor?' Plötzlich ist klar, dass der diagnostische Name noch keine prädiktive Antwort ist.":"Στο συμβούλιο σαρκωμάτων η περίπτωση φαίνεται να έχει λυθεί σε δέκα δευτερόλεπτα: μεταστατικό GIST, DOG1 θετικό, άρα imatinib. Η παθολογοανατόμος σταματά τη συζήτηση με μια απλή ερώτηση: «Ποιος γονότυπος KIT ή PDGFRA υπάρχει πραγματικά;» Ξαφνικά γίνεται σαφές ότι η διαγνωστική ονομασία δεν αποτελεί ακόμη προβλεπτική απάντηση.","64-jährige Patientin mit vor drei Jahren reseziertem gastralem GIST und jetzt multiplen Lebermetastasen. DOG1 stark positiv, CD117 fokal. Keine bisherige TKI-Therapie. Vor Therapiebeginn soll der KIT/PDGFRA-Status geklärt werden.":"Γυναίκα 64 ετών με γαστρικό GIST που εξαιρέθηκε πριν από τρία χρόνια και τώρα πολλαπλές ηπατικές μεταστάσεις. DOG1 έντονα θετικό, CD117 εστιακό. Χωρίς προηγούμενη θεραπεία TKI. Η κατάσταση KIT/PDGFRA πρέπει να διευκρινιστεί πριν από την έναρξη θεραπείας.","Diagnose":"Διάγνωση","Morphologie und DOG1/CD117 sichern den GIST-Kontext.":"Η μορφολογία και DOG1/CD117 τεκμηριώνουν το πλαίσιο GIST.","IHC beantwortet 'Was ist der Tumor?', nicht automatisch 'Welcher TKI wirkt?'.":"Η IHC απαντά στο «Τι είναι ο όγκος;», όχι αυτόματα στο «Ποιος TKI δρα;». ","Therapiefrage":"Θεραπευτικό ερώτημα","Die Onkologie möchte mit einer TKI-Therapie beginnen.":"Η ογκολογία θέλει να αρχίσει θεραπεία TKI.","Der prädiktive Genotyp gehört vor die Wirkstoffwahl.":"Ο προβλεπτικός γονότυπος πρέπει να προηγείται της επιλογής φαρμάκου.","Lebermetastase, 75 % Tumor, DNA-QC sehr gut; nur sechs Schnitte nötig verfügbar.":"Ηπατική μετάσταση, 75% όγκος, πολύ καλό QC DNA· απαιτούνται/διατίθενται μόνο έξι τομές.","Eine fokussierte KIT/PDGFRA-Analyse ist effizient.":"Μια εστιασμένη ανάλυση KIT/PDGFRA είναι αποδοτική.","Epithelioider mesenchymaler Tumor, vereinbar mit GIST.":"Επιθηλιοειδής μεσεγχυματικός όγκος, συμβατός με GIST.","DOG1 stark positiv; CD117 fokal/heterogen positiv.":"DOG1 έντονα θετικό· CD117 εστιακά/ετερογενώς θετικό.","Systemtherapie":"Συστηματική θεραπεία","Noch nicht begonnen.":"Δεν έχει ακόμη αρχίσει.","Kleine, aber sehr tumorreiche Metastasenbiopsie.":"Μικρή αλλά ιδιαίτερα πλούσια σε όγκο βιοψία μετάστασης.","Die klinische Kernfrage ist fokussiert; ein extrem breites Pan-Tumor-Panel ist nicht zwingend nötig.":"Το βασικό κλινικό ερώτημα είναι εστιασμένο· ένα εξαιρετικά ευρύ pan-tumor panel δεν είναι υποχρεωτικό.","Therapie sollte nicht allein aufgrund der IHC gestartet werden, wenn der Genotyp zeitnah verfügbar ist.":"Η θεραπεία δεν πρέπει να αρχίσει μόνο βάσει IHC όταν ο γονότυπος μπορεί να είναι έγκαιρα διαθέσιμος.","Welcher Befund entscheidet in diesem Fall am direktesten über die TKI-Auswahl?":"Ποιο εύρημα καθορίζει πιο άμεσα την επιλογή TKI σε αυτή την περίπτωση;","KIT/PDGFRA-Mutationsstatus":"Κατάσταση μεταλλάξεων KIT/PDGFRA","Stärke der CD117-IHC allein":"Μόνο η ένταση IHC CD117","Ki-67 allein":"Μόνο Ki-67","Der KIT/PDGFRA-Genotyp ist für die prädiktive Einordnung zentral.":"Ο γονότυπος KIT/PDGFRA είναι κεντρικός για την προβλεπτική ταξινόμηση.","Was bedeutet DOG1+/CD117+ für die TKI-Wahl?":"Τι σημαίνει DOG1+/CD117+ για την επιλογή TKI;","Es stützt die GIST-Diagnose, ersetzt aber die Genotypisierung nicht.":"Υποστηρίζει τη διάγνωση GIST, αλλά δεν αντικαθιστά τη γονοτύπηση.","Es beweist Imatinib-Sensitivität.":"Αποδεικνύει ευαισθησία στο imatinib.","Es schließt PDGFRA-Mutationen aus.":"Αποκλείει μεταλλάξεις PDGFRA.","Es macht molekulare Diagnostik grundsätzlich überflüssig.":"Καθιστά τον μοριακό έλεγχο γενικά περιττό.","Diagnostische IHC und prädiktive Genotypisierung beantworten verschiedene Fragen.":"Η διαγνωστική IHC και η προβλεπτική γονοτύπηση απαντούν σε διαφορετικά ερωτήματα.","Wählen Sie die minimale diagnostische Strategie, mit der die geplante TKI-Therapie genotypspezifisch abgesichert werden kann.":"Επιλέξτε την ελάχιστη διαγνωστική στρατηγική που μπορεί να τεκμηριώσει τη σχεδιαζόμενη θεραπεία TKI με τρόπο ειδικό για τον γονότυπο.","GIST-Diagnose als gesichert akzeptieren.":"Αποδεχθείτε τη διάγνωση GIST ως τεκμηριωμένη.","KIT/PDGFRA-Mutationsanalyse durchführen.":"Διενεργήστε ανάλυση μεταλλάξεων KIT/PDGFRA.","Mutation auf Exon/Variantebene berichten.":"Αναφέρετε τη μετάλλαξη σε επίπεδο exon/παραλλαγής.","Therapieempfehlung an die konkrete Sensitivitäts-/Resistenzkonstellation koppeln.":"Συνδέστε τη θεραπευτική σύσταση με τη συγκεκριμένη συνύπαρξη ευαισθησίας/αντοχής.","Bei KIT/PDGFRA-Wildtyp weitere Subklassifikation nur als Folgefrage erwägen.":"Σε KIT/PDGFRA wild type, εξετάστε περαιτέρω υποταξινόμηση μόνο ως επόμενο ερώτημα.","Breiteres validiertes NGS-Panel, wenn es KIT/PDGFRA vollständig abdeckt und ohne relevante Mehrbelastung verfügbar ist.":"Ευρύτερο επικυρωμένο panel NGS εάν καλύπτει πλήρως KIT/PDGFRA και είναι διαθέσιμο χωρίς σημαντική πρόσθετη επιβάρυνση.","CD117 positiv = Imatinib":"CD117 θετικό = imatinib","Diagnostische Proteinexpression wird fälschlich als prädiktiver Genotyp interpretiert.":"Η διαγνωστική πρωτεϊνική έκφραση ερμηνεύεται λανθασμένα ως προβλεπτικός γονότυπος.","Pan-Panel ohne klare Zusatzfrage":"Pan-panel χωρίς σαφές πρόσθετο ερώτημα","Kann funktionieren, ist bei der fokussierten Erstfrage aber unnötig breit.":"Μπορεί να λειτουργήσει, αλλά είναι περιττά ευρύ για το εστιασμένο αρχικό ερώτημα.","Therapie vor Genotyp":"Θεραπεία πριν από τον γονότυπο","Eine klinisch relevante Resistenz-/Sensitivitätskonstellation kann übersehen werden.":"Μπορεί να παραβλεφθεί κλινικά σημαντική συνύπαρξη αντοχής/ευαισθησίας.","PDGFRA D842V statt 'klassischem KIT-GIST'":"PDGFRA D842V αντί «κλασικού KIT-GIST»","Die gezielte Sequenzierung zeigt keine KIT-Mutation, sondern PDGFRA Exon 18 p.D842V. Der zunächst reflexhaft diskutierte Imatinib-Start wäre für genau diese Konstellation ungeeignet; die TKI-Strategie muss genotypspezifisch geändert werden.":"Η στοχευμένη αλληλούχηση δεν δείχνει μετάλλαξη KIT αλλά PDGFRA exon 18 p.D842V. Η αντανακλαστικά συζητηθείσα έναρξη imatinib θα ήταν ακατάλληλη ακριβώς για αυτή τη συνύπαρξη· η στρατηγική TKI πρέπει να αλλάξει σύμφωνα με τον γονότυπο.","Der Fall zeigt maximal kompakt, warum Diagnosesicherung und prädiktive Molekularpathologie zwei getrennte Schritte sind.":"Η περίπτωση δείχνει πολύ συνοπτικά γιατί η διαγνωστική επιβεβαίωση και η προβλεπτική μοριακή παθολογία είναι δύο ξεχωριστά βήματα.","Genotyp vor TKI":"Γονότυπος πριν από TKI","PDGFRA Exon 18 p.D842V, KIT wildtyp.":"PDGFRA exon 18 p.D842V, KIT wild type.","Kernentscheidung getroffen; TKI-Auswahl kann genotypspezifisch erfolgen.":"Η βασική απόφαση ελήφθη· η επιλογή TKI μπορεί να γίνει με βάση τον γονότυπο.","IHC reicht":"Η IHC αρκεί","GIST wird korrekt diagnostiziert, aber ohne KIT/PDGFRA-Genotyp pauschal als Imatinib-sensitiv behandelt.":"Το GIST διαγιγνώσκεται σωστά, αλλά χωρίς γονότυπο KIT/PDGFRA αντιμετωπίζεται γενικά ως ευαίσθητο στο imatinib.","Diagnose korrekt, prädiktive Ebene verfehlt.":"Σωστή διάγνωση, χαμένη προβλεπτική διάσταση.","Breites Pan-Panel":"Ευρύ pan-panel","PDGFRA D842V wird ebenfalls gefunden, jedoch mit mehr Ressourcen als für die Kernfrage nötig.":"Το PDGFRA D842V ανιχνεύεται επίσης, αλλά με περισσότερους πόρους από όσους απαιτούνται για το βασικό ερώτημα.","Fachlich brauchbar, aber weniger fokussiert.":"Κλινικά χρήσιμο, αλλά λιγότερο εστιασμένο.","PDGFRA D842V":"PDGFRA D842V","Genotypspezifische TKI-Strategie im Sarkomboard diskutieren.":"Συζητήστε γονοτυπο-ειδική στρατηγική TKI στο συμβούλιο σαρκωμάτων.","Pauschaler Imatinib-Reflex wird vermieden.":"Αποφεύγεται το γενικευμένο αντανακλαστικό imatinib.","KIT/PDGFRA wildtyp":"KIT/PDGFRA wild type","Weitere molekulare Subklassifikation erwägen.":"Εξετάστε περαιτέρω μοριακή υποταξινόμηση.","Der Fall geht in eine zweite diagnostische Ebene über.":"Η περίπτωση περνά σε δεύτερο διαγνωστικό επίπεδο.","DOG1/CD117 sichern den diagnostischen Kontext, nicht die TKI-Sensitivität.":"DOG1/CD117 τεκμηριώνουν το διαγνωστικό πλαίσιο, όχι την ευαισθησία σε TKI.","KIT/PDGFRA-Genotypisierung ist eine prädiktive Entscheidungsebene.":"Η γονοτύπηση KIT/PDGFRA αποτελεί προβλεπτικό επίπεδο απόφασης.","PDGFRA D842V ist der klassische Fall, in dem ein pauschaler Imatinib-Reflex scheitert.":"Το PDGFRA D842V είναι η κλασική περίπτωση όπου αποτυγχάνει ο γενικευμένος αντανακλαστικός χειρισμός με imatinib.","Fokussierte Diagnostik kann besser sein als maximale Panelbreite, wenn die klinische Frage klar ist.":"Η εστιασμένη διάγνωση μπορεί να είναι καλύτερη από το μέγιστο εύρος panel όταν το κλινικό ερώτημα είναι σαφές.","Gezielte KIT/PDGFRA-Analyse vor TKI-Start. Ergebnis: PDGFRA Exon 18 p.D842V, KIT wildtyp. Damit ist der reflexhafte Imatinib-Ansatz nicht passend; die Therapie muss genotypspezifisch geplant werden.":"Στοχευμένη ανάλυση KIT/PDGFRA πριν από την έναρξη TKI. Αποτέλεσμα: PDGFRA exon 18 p.D842V, KIT wild type. Επομένως η αντανακλαστική προσέγγιση με imatinib δεν είναι κατάλληλη· η θεραπεία πρέπει να σχεδιαστεί βάσει γονοτύπου.","Diagnose vs. Prädiktion getrennt":"Διαχωρισμός διάγνωσης και πρόβλεψης","KIT/PDGFRA gewählt":"Επιλέχθηκε KIT/PDGFRA","D842V korrekt gewichtet":"D842V σταθμισμένο σωστά","Keine unnötige Panelinflation":"Χωρίς περιττή διόγκωση panel","Welche weiteren GIST-Genotypen beeinflussen Dosis oder TKI-Sensitivität?":"Ποιοι άλλοι γονότυποι GIST επηρεάζουν τη δόση ή την ευαισθησία σε TKI;","Wann wäre ein breiteres Panel sinnvoll?":"Πότε θα ήταν χρήσιμο ένα ευρύτερο panel;","Wie sollte ein Befund formuliert sein, damit Diagnose und Prädiktion klar getrennt bleiben?":"Πώς πρέπει να διατυπωθεί μια έκθεση ώστε διάγνωση και πρόβλεψη να παραμένουν σαφώς διαχωρισμένες;","GIST-Diagnose ist nicht gleich TKI-Sensitivität":"Η διάγνωση GIST δεν ισοδυναμεί με ευαισθησία σε TKI","IHC-Diagnose → Genotyp → TKI-Wechsel":"Διάγνωση IHC → γονότυπος → αλλαγή TKI","Cholangiozelluläres Karzinom mit FGFR2/IDH-Frage → Paneldiagnostik und Studienoptionen":"Χολαγγειοκαρκίνωμα με ερώτημα FGFR2/IDH → έλεγχος panel και επιλογές κλινικών μελετών","Cholangiozelluläres Karzinom mit F…":"Χολαγγειοκαρκίνωμα με ερώτημα FGFR2/IDH…","Hepatobiliäre Onkologie / MTB":"Ηπατοχολική ογκολογία / MTB","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie.":"Γυναίκα 59 ετών με μη εξαιρέσιμο ενδοηπατικό χολαγγειοκαρκίνωμα και εξέλιξη μετά θεραπεία πρώτης γραμμής.","Welche molekulare Profilierung ist jetzt sinnvoll, insbesondere für FGFR2- und IDH1/2-Alterationen sowie weitere potenziell targetierbare Befunde?":"Ποιο μοριακό profiling είναι κατάλληλο τώρα, ιδιαίτερα για αλλοιώσεις FGFR2 και IDH1/2 καθώς και άλλα δυνητικά στοχεύσιμα ευρήματα;","Der molekulare Befund soll vor Festlegung der nächsten Therapielinie vorliegen.":"Η μοριακή έκθεση πρέπει να είναι διαθέσιμη πριν από τον καθορισμό της επόμενης γραμμής θεραπείας.","Tumorlokalisation":"Εντόπιση όγκου","Intrahepatische dominante Raumforderung mit multiplen Satelliten und pulmonalen Metastasen.":"Κυρίαρχη ενδοηπατική μάζα με πολλαπλούς δορυφόρους και πνευμονικές μεταστάσεις.","Systemische Erstlinientherapie abgeschlossen; aktuell radiologischer Progress.":"Ολοκληρώθηκε συστηματική θεραπεία πρώτης γραμμής· τρέχουσα ακτινολογική εξέλιξη.","Ein kleines DNA-only-Panel aus der Erstdiagnose meldete keinen therapeutisch relevanten SNV/Indel-Befund; Fusionen waren im Bericht nicht valide abgedeckt.":"Ένα μικρό DNA-only panel από την αρχική διάγνωση δεν ανέφερε θεραπευτικά σχετικό SNV/indel· οι συντήξεις δεν καλύπτονταν έγκυρα στην έκθεση.","'Panel negativ' wird im Tumorboard bereits mit 'keine Target-Option' gleichgesetzt.":"Στο ογκολογικό συμβούλιο το «αρνητικό panel» εξισώνεται ήδη με «καμία στοχεύσιμη επιλογή». ","Adenokarzinom mit tubulären und desmoplastischen Anteilen, vereinbar mit intrahepatischem Cholangiokarzinom.":"Αδενοκαρκίνωμα με σωληνώδη και δεσμοπλαστικά στοιχεία, συμβατό με ενδοηπατικό χολαγγειοκαρκίνωμα.","CK7 positiv; HepPar1/Arginase-1 negativ; klinisch-radiologische Integration stützt iCCA.":"CK7 θετικό· HepPar1/Arginase-1 αρνητικά· η κλινικο-ακτινολογική ενσωμάτωση υποστηρίζει iCCA.","Breite DNA-basierte Alterationen und insbesondere strukturelle FGFR2-Ereignisse müssen methodisch adäquat erfasst werden.":"Οι ευρείες DNA-βασισμένες αλλοιώσεις και ιδιαίτερα τα δομικά συμβάντα FGFR2 πρέπει να ανιχνεύονται με μεθοδολογικά κατάλληλες εξετάσεις.","Nicht relevant":"Δεν είναι σχετικό","Neuroonkologische IDH1-R132H-IHC, G-CIMP oder ein ZNS-Methylierungsclassifier beantworten diese Fragestellung nicht.":"Η νευρο-ογκολογική IHC IDH1-R132H, το G-CIMP ή ένας classifier μεθυλίωσης ΚΝΣ δεν απαντούν σε αυτό το ερώτημα.","FFPE-Leberbiopsie, Block C5.":"FFPE βιοψία ήπατος, block C5.","ca. 50 %, ausreichende vitale Tumorareale.":"περ. 50%, επαρκείς βιώσιμες περιοχές όγκου.","DNA/RNA-QC":"QC DNA/RNA","DNA gut; RNA nach QC ausreichend.":"Καλή ποιότητα DNA· επαρκές RNA μετά το QC.","Erneutes DNA-only-Testen ohne valide Fusionserfassung kann denselben blinden Fleck reproduzieren.":"Η επανάληψη DNA-only ελέγχου χωρίς έγκυρη κάλυψη συντήξεων μπορεί να αναπαράγει το ίδιο τυφλό σημείο.","CCA-Molekularprofil / IDH1/2-Kontext":"Μοριακό προφίλ CCA / πλαίσιο IDH1/2","FGFR2-Fusions-/Rearrangementdiagnostik":"Έλεγχος σύντηξης/αναδιάταξης FGFR2","CCA-DNA-Profil":"Προφίλ DNA CCA","Keine pathogene IDH1/2-Mutation; kein BRAF-V600- oder ERBB2-Hotspot-Befund. Das DNA-Profil allein erklärt keine Target-Option.":"Δεν ανιχνεύεται παθογόνος μετάλλαξη IDH1/2, ούτε BRAF V600 ή hotspot ERBB2. Το DNA προφίλ μόνο του δεν αναδεικνύει στοχεύσιμη επιλογή.","FGFR2-Fusionsdiagnostik":"Έλεγχος σύντηξης FGFR2","FGFR2::BICC1-Fusion nachweisbar. Der Befund ist bei intrahepatischem Cholangiokarzinom therapeutisch relevant und gehört in die nächste Linienplanung.":"Ανιχνεύεται σύντηξη FGFR2::BICC1. Το εύρημα είναι θεραπευτικά σχετικό στο ενδοηπατικό χολαγγειοκαρκίνωμα και πρέπει να ενταχθεί στον σχεδιασμό της επόμενης γραμμής.","DNA und RNA aus dem markierten Tumorareal sind auswertbar; ausreichende Restreserve vorhanden.":"DNA και RNA από τη σημειωμένη περιοχή όγκου είναι αξιολογήσιμα· υπάρχει επαρκές υπολειπόμενο υλικό.","Intrahepatisches Cholangiokarzinom mit FGFR2::BICC1-Fusion und ohne IDH1/2-Mutation. Die zuvor DNA-only negative Profilierung war kein ausreichender Ausschluss einer strukturellen Targetalteration.":"Ενδοηπατικό χολαγγειοκαρκίνωμα με σύντηξη FGFR2::BICC1 και χωρίς μετάλλαξη IDH1/2. Το προηγούμενο αρνητικό DNA-only profiling δεν ήταν επαρκές για να αποκλείσει δομική στοχεύσιμη αλλοίωση.","Teilbefund: Die CCA-Profilierung ist ohne belastbare FGFR2-Fusions-/Rearrangementdiagnostik unvollständig. Neuroonkologische IDH-/Methylierungsverfahren sind für diese Frage nicht geeignet.":"Μερικό εύρημα: Το profiling CCA είναι ελλιπές χωρίς αξιόπιστο έλεγχο σύντηξης/αναδιάταξης FGFR2. Οι νευρο-ογκολογικές μέθοδοι IDH/μεθυλίωσης δεν είναι κατάλληλες για αυτό το ερώτημα.","Intrahepatisches Cholangiokarzinom als relevanten molekularen Kontext benennen":"Αναφέρετε το ενδοηπατικό χολαγγειοκαρκίνωμα ως το σχετικό μοριακό πλαίσιο","FGFR2-Fusion/Rearrangement als eigenständige strukturelle Alterationsklasse erfassen":"Καταγράψτε σύντηξη/αναδιάταξη FGFR2 ως ξεχωριστή κατηγορία δομικής αλλοίωσης","IDH1/2-Sequenzierung im CCA-Kontext von neuroonkologischer IDH-IHC/Methylomdiagnostik trennen":"Διαχωρίστε την αλληλούχηση IDH1/2 στο πλαίσιο CCA από τη νευρο-ογκολογική IHC IDH/ανάλυση μεθυλώματος","DNA-only Negativbefund nicht als vollständigen Fusionsausschluss formulieren":"Μην διατυπώνετε ένα αρνητικό DNA-only αποτέλεσμα ως πλήρη αποκλεισμό συντήξεων","Optimale Lösung: CCA-spezifisches Molekularprofil plus valide FGFR2-Fusionserfassung. Der ZNS-Methylierungs-/G-CIMP-Copyover wird vollständig entfernt.":"Βέλτιστη λύση: Μοριακό προφίλ ειδικό για CCA συν έγκυρη ανίχνευση σύντηξης FGFR2. Το copyover μεθυλίωσης ΚΝΣ/G-CIMP αφαιρείται πλήρως.","IDH":"IDH","FGFR":"FGFR","Intrahepatisches Cholangiokarzinom: Das negative DNA-Panel übersieht die strukturelle Targetalteration":"Ενδοηπατικό χολαγγειοκαρκίνωμα: Το αρνητικό DNA panel χάνει τη δομική στοχεύσιμη αλλοίωση","Molekularpathologie / hepatobiliäre Onkologie / MTB":"Μοριακή παθολογία / ηπατοχολική ογκολογία / MTB","Das intrahepatische Cholangiokarzinom als Entität mit relevanter breiter molekularer Profilierung einordnen.":"Ταξινομήστε το ενδοηπατικό χολαγγειοκαρκίνωμα ως οντότητα που απαιτεί σχετικό ευρύ μοριακό profiling.","FGFR2-Fusionen/Rearrangements methodisch von SNV/Indel-Analysen unterscheiden.":"Διαχωρίστε μεθοδολογικά τις συντήξεις/αναδιατάξεις FGFR2 από τις αναλύσεις SNV/indel.","IDH1/2 im CCA-Kontext von neuroonkologischer IDH-IHC/G-CIMP/Methylomdiagnostik trennen.":"Διαχωρίστε τα IDH1/2 στο πλαίσιο CCA από τη νευρο-ογκολογική διάγνωση IHC IDH/G-CIMP/μεθυλώματος.","Einen negativen DNA-only-Befund nicht als vollständigen Ausschluss struktureller Targetalterationen interpretieren.":"Μην ερμηνεύετε αρνητικό DNA-only αποτέλεσμα ως πλήρη αποκλεισμό δομικών στοχεύσιμων αλλοιώσεων.","Im hepatobiliären MTB liegt ein alter Molekularbefund mit der Überschrift 'kein targetierbarer Befund'. Die 59-jährige Patientin mit intrahepatischem Cholangiokarzinom ist nach Erstlinientherapie progredient, und die nächste Linie muss geplant werden. Beim Blick in den Methodenteil zeigt sich: Das damalige kleine Panel war DNA-basiert und auf SNV/Indels fokussiert. FGFR2-Rearrangements wurden nicht valide breit erfasst. Gleichzeitig findet sich in der Falllogik ein völlig fachfremder Verweis auf G-CIMP und einen ZNS-Methylierungsclassifier – genau diese Altlast soll der Fall jetzt bewusst bereinigen.":"Στο ηπατοχολικό MTB υπάρχει παλιά μοριακή έκθεση με τίτλο «κανένα στοχεύσιμο εύρημα». Η 59χρονη με ενδοηπατικό χολαγγειοκαρκίνωμα έχει εξελιχθεί μετά θεραπεία πρώτης γραμμής και πρέπει να σχεδιαστεί η επόμενη γραμμή. Η ενότητα μεθόδων δείχνει ότι το παλιό μικρό panel ήταν DNA-βασισμένο και εστιασμένο σε SNV/indels. Οι αναδιατάξεις FGFR2 δεν καλύπτονταν έγκυρα και ευρέως. Ταυτόχρονα, η λογική του περιστατικού περιέχει μια εντελώς άσχετη αναφορά σε G-CIMP και classifier μεθυλίωσης ΚΝΣ – ακριβώς αυτή την παλιά αστοχία καλείται τώρα το περιστατικό να διορθώσει συνειδητά.","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie. DNA-only-Vorbefund ohne relevante SNV/Indel-Targetalteration. Für die nächste Linie sollen FGFR2-Fusionen/Rearrangements, IDH1/2 und weitere relevante molekulare Alterationen methodisch vollständig bewertet werden.":"Γυναίκα 59 ετών με μη εξαιρέσιμο ενδοηπατικό χολαγγειοκαρκίνωμα και εξέλιξη μετά πρώτη γραμμή. Προηγούμενο DNA-only αποτέλεσμα χωρίς σχετική στοχεύσιμη αλλοίωση SNV/indel. Για την επόμενη γραμμή πρέπει να αξιολογηθούν πλήρως, με κατάλληλες μεθόδους, συντήξεις/αναδιατάξεις FGFR2, IDH1/2 και άλλες σχετικές μοριακές αλλοιώσεις.","Entität":"Οντότητα","Intrahepatisches Cholangiokarzinom mit metastasierter Erkrankung.":"Ενδοηπατικό χολαγγειοκαρκίνωμα με μεταστατική νόσο.","Tumorentität und Erkrankungsphase bestimmen die sinnvolle molekulare Breite.":"Η οντότητα του όγκου και η φάση της νόσου καθορίζουν το κατάλληλο εύρος μοριακού ελέγχου.","Kleines DNA-only-Panel ohne relevanten SNV/Indel-Treffer; keine belastbare breite Fusionserfassung.":"Μικρό DNA-only panel χωρίς σχετικό SNV/indel εύρημα· χωρίς αξιόπιστη ευρεία κάλυψη συντήξεων.","Ein negatives SNV/Indel-Profil schließt strukturelle Alterationen nicht aus.":"Ένα αρνητικό προφίλ SNV/indel δεν αποκλείει δομικές αλλοιώσεις.","Leberbiopsie mit 50 % Tumor; DNA und RNA ausreichend.":"Βιοψία ήπατος με 50% όγκο· επαρκές DNA και RNA.","Es gibt keinen technischen Grund, die Fusionsfrage offen zu lassen.":"Δεν υπάρχει τεχνικός λόγος να παραμείνει ανοιχτό το ερώτημα της σύντηξης.","Copyover-Falle":"Παγίδα copyover","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier gehören in neuroonkologische Kontexte und beantworten die CCA-Targetfrage nicht.":"Η IHC IDH1-R132H, το G-CIMP και οι classifiers μεθυλίωσης ΚΝΣ ανήκουν σε νευρο-ογκολογικά πλαίσια και δεν απαντούν στο ερώτημα στόχευσης του CCA.","Gleiche Genbezeichnung bedeutet nicht gleiche diagnostische Methode oder biologische Fragestellung.":"Το ίδιο όνομα γονιδίου δεν σημαίνει την ίδια διαγνωστική μέθοδο ή το ίδιο βιολογικό ερώτημα.","Adenokarzinom mit desmoplastischem Stroma; klinisch-radiologisch und immunhistologisch mit intrahepatischem CCA vereinbar.":"Αδενοκαρκίνωμα με δεσμοπλαστικό στρώμα· κλινικά, ακτινολογικά και ανοσοϊστολογικά συμβατό με ενδοηπατικό CCA.","DNA-only Vorprofil":"Προηγούμενο DNA-only προφίλ","Kein relevanter IDH1/2-, BRAF-V600- oder ERBB2-Hotspot-Befund; Fusionserfassung unzureichend.":"Χωρίς σχετικό εύρημα IDH1/2, BRAF V600 ή hotspot ERBB2· ανεπαρκής κάλυψη συντήξεων.","ausreichend für gezielte Fusionsanalyse.":"επαρκές για στοχευμένη ανάλυση σύντηξης.","Zehn ungefärbte Schnitte verfügbar.":"Διατίθενται δέκα άχρωμες τομές.","DNA und RNA sind ausreichend; die Limitation liegt primär in der Wahl des Assays.":"DNA και RNA είναι επαρκή· ο περιορισμός βρίσκεται κυρίως στην επιλογή assay.","Neuroonkologische IDH-/Methylierungsverfahren sind explizit entitätsfremd.":"Οι νευρο-ογκολογικές μέθοδοι IDH/μεθυλίωσης είναι ρητά ακατάλληλες για αυτή την οντότητα.","Das TAT-Ziel liegt vor der nächsten Therapieentscheidung.":"Ο στόχος TAT είναι πριν από την επόμενη θεραπευτική απόφαση.","Welche molekulare Kernstrategie ist bei diesem progredienten intrahepatischen Cholangiokarzinom sinnvoll?":"Ποια βασική μοριακή στρατηγική είναι κατάλληλη για αυτό το προοδευτικό ενδοηπατικό χολαγγειοκαρκίνωμα;","CCA-spezifisches Molekularprofil plus valide FGFR2-Fusions-/Rearrangementdiagnostik":"Μοριακό προφίλ ειδικό για CCA συν έγκυρος έλεγχος σύντηξης/αναδιάταξης FGFR2","IDH1-R132H-IHC plus ZNS-Methylierungsclassifier":"IHC IDH1-R132H συν classifier μεθυλίωσης ΚΝΣ","Keine weitere Diagnostik, weil das alte DNA-Panel negativ war":"Καμία περαιτέρω εξέταση επειδή το παλιό DNA panel ήταν αρνητικό","MGMT-Promotor-Methylierung":"Μεθυλίωση του υποκινητή MGMT","Die klinische Frage verlangt CCA-spezifische molekulare Profilierung mit adäquater Erfassung struktureller Alterationen.":"Το κλινικό ερώτημα απαιτεί μοριακό profiling ειδικό για CCA με επαρκή ανίχνευση δομικών αλλοιώσεων.","Wie soll IDH in diesem Fall untersucht/eingeordnet werden?":"Πώς πρέπει να ελεγχθεί/ερμηνευθεί το IDH σε αυτή την περίπτωση;","IDH1/2-Sequenzierung im CCA-Panel-/Targetkontext":"Αλληλούχηση IDH1/2 στο πλαίσιο panel/στόχευσης CCA","IDH1-R132H-IHC als primärer CCA-Screeningstandard":"IHC IDH1-R132H ως κύριο standard screening για CCA","G-CIMP-Profil als Therapiebiomarker":"Προφίλ G-CIMP ως θεραπευτικός βιοδείκτης","ZNS-Methylierungsclassifier":"Classifier μεθυλίωσης ΚΝΣ","Die neuroonkologische R132H-IHC/G-CIMP-/Classifier-Logik darf nicht auf das Cholangiokarzinom übertragen werden.":"Η νευρο-ογκολογική λογική R132H IHC/G-CIMP/classifier δεν πρέπει να μεταφέρεται στο χολαγγειοκαρκίνωμα.","Das alte DNA-only-Panel ist negativ. Was folgt daraus für FGFR2?":"Το παλιό DNA-only panel είναι αρνητικό. Τι συνεπάγεται αυτό για FGFR2;","Eine Fusion/Rearrangement-Frage kann weiterhin offen sein, wenn der Assay diese Alterationsklasse nicht valide abdeckt.":"Το ερώτημα σύντηξης/αναδιάταξης μπορεί να παραμένει ανοικτό εάν το assay δεν καλύπτει έγκυρα αυτή την κατηγορία αλλοιώσεων.","FGFR2 ist sicher ausgeschlossen.":"Το FGFR2 έχει αποκλειστεί με βεβαιότητα.","Dann kann nur noch IDH1 relevant sein.":"Τότε μόνο το IDH1 μπορεί να παραμένει σχετικό.","Strukturelle Alterationen sind beim CCA klinisch nicht relevant.":"Οι δομικές αλλοιώσεις δεν είναι κλινικά σχετικές στο CCA.","SNV/Indel-negative DNA-Daten sind kein universeller Fusionsausschluss.":"Τα DNA δεδομένα αρνητικά για SNV/indel δεν αποτελούν καθολικό αποκλεισμό συντήξεων.","Planen Sie eine CCA-spezifische molekulare Abklärung für die nächste Therapielinie und entfernen Sie die neuroonkologischen Copyover-Methoden vollständig aus der Entscheidungslogik.":"Σχεδιάστε μοριακή διερεύνηση ειδική για CCA για την επόμενη θεραπευτική γραμμή και αφαιρέστε πλήρως τις νευρο-ογκολογικές copyover μεθόδους από τη λογική απόφασης.","Intrahepatischen CCA-Kontext bestätigen.":"Επιβεβαιώστε το πλαίσιο ενδοηπατικού CCA.","CCA-spezifisches DNA-Profil für IDH1/2 und weitere relevante Alterationen nutzen.":"Χρησιμοποιήστε DNA προφίλ ειδικό για CCA για IDH1/2 και άλλες σχετικές αλλοιώσεις.","FGFR2-Fusion/Rearrangement mit einer dafür validierten Methode explizit erfassen.":"Ελέγξτε ρητά σύντηξη/αναδιάταξη FGFR2 με επικυρωμένη μέθοδο.","DNA-only Negativbefund methodisch begrenzen.":"Περιορίστε μεθοδολογικά την ερμηνεία του αρνητικού DNA-only αποτελέσματος.","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier nicht verwenden.":"Μην χρησιμοποιείτε IHC IDH1-R132H, G-CIMP ή classifier μεθυλίωσης ΚΝΣ.","Validiertes kombiniertes DNA/RNA-Pan-Panel mit sicherer FGFR2-Fusionserfassung.":"Επικυρωμένο συνδυασμένο DNA/RNA pan-panel με αξιόπιστη κάλυψη συντήξεων FGFR2.","Gezielte FGFR2-Fusionsdiagnostik plus separates IDH1/2-Assay, wenn ein integriertes CCA-Panel nicht verfügbar ist.":"Στοχευμένος έλεγχος σύντηξης FGFR2 συν ξεχωριστό assay IDH1/2 εάν δεν υπάρχει ολοκληρωμένο CCA panel.","Fachfremder Copyover; beantwortet weder FGFR2- noch IDH1/2-Targetfrage beim CCA.":"Άσχετο copyover· δεν απαντά ούτε στο ερώτημα FGFR2 ούτε στο ερώτημα στόχευσης IDH1/2 στο CCA.","IDH1-R132H-IHC als CCA-Standard":"IHC IDH1-R132H ως standard CCA","Neuroonkologische Screeninglogik wird auf eine andere Entität übertragen.":"Η νευρο-ογκολογική λογική screening μεταφέρεται σε άλλη οντότητα.","DNA-negativ = keine Targetoption":"DNA αρνητικό = καμία στοχεύσιμη επιλογή","Strukturelle Alterationen können methodisch offen bleiben.":"Οι δομικές αλλοιώσεις μπορεί να παραμένουν μεθοδολογικά άλυτες.","FGFR2::BICC1 trotz 'kein targetierbarer Befund'":"FGFR2::BICC1 παρά το «κανένα στοχεύσιμο εύρημα»","Die CCA-spezifische DNA-Analyse bleibt für IDH1/2, BRAF und ERBB2 ohne relevanten Treffer. Die gezielte Fusionsdiagnostik detektiert jedoch eine FGFR2::BICC1-Fusion. Der alte Satz 'kein targetierbarer Befund' war damit nicht biologisch falsch, sondern methodisch zu weit formuliert.":"Η ειδική για CCA ανάλυση DNA παραμένει χωρίς σχετικό εύρημα για IDH1/2, BRAF και ERBB2. Ωστόσο, ο στοχευμένος έλεγχος συντήξεων ανιχνεύει σύντηξη FGFR2::BICC1. Η παλιά φράση «κανένα στοχεύσιμο εύρημα» δεν ήταν επομένως βιολογικά λανθασμένη, αλλά μεθοδολογικά υπερβολικά γενική.","Die zentrale Lektion ist zweifach: strukturelle Alterationen brauchen passende Assays, und identische Genbegriffe dürfen nicht entitätsfremde Diagnostikpfade triggern.":"Το βασικό μάθημα είναι διπλό: οι δομικές αλλοιώσεις απαιτούν κατάλληλα assays και οι ίδιες ονομασίες γονιδίων δεν πρέπει να ενεργοποιούν διαγνωστικές οδούς ακατάλληλες για την οντότητα.","CCA-Profil + Fusion":"Προφίλ CCA + σύντηξη","FGFR2::BICC1-Fusion nachweisbar; IDH1/2 wildtyp; kein BRAF-V600-/ERBB2-Hotspot-Befund.":"Ανιχνεύεται σύντηξη FGFR2::BICC1· IDH1/2 wild type· χωρίς BRAF V600/hotspot ERBB2.","Vollständige, entitätsspezifische Profilierung mit klinisch relevanter Targetalteration.":"Πλήρες, ειδικό για την οντότητα profiling με κλινικά σχετική στοχεύσιμη αλλοίωση.","DNA-only wiederholt":"Επαναλήφθηκε DNA-only","Kein relevanter SNV/Indel-Treffer; FGFR2-Fusionsstatus bleibt offen.":"Χωρίς σχετικό SNV/indel εύρημα· η κατάσταση σύντηξης FGFR2 παραμένει άλυτη.","Der alte methodische blinde Fleck wurde reproduziert.":"Το παλιό μεθοδολογικό τυφλό σημείο αναπαράχθηκε.","Neuroonkologischer IDH-Pfad":"Νευρο-ογκολογική οδός IDH","IDH1-R132H-IHC/Methylierungsclassifier werden angefordert; die eigentliche CCA-Targetfrage bleibt ungelöst.":"Ζητούνται IHC IDH1-R132H/classifier μεθυλίωσης· το πραγματικό ερώτημα στόχευσης του CCA παραμένει άλυτο.","Klarer Cross-Template-Fehler.":"Σαφές σφάλμα cross-template.","FGFR2-Fusion positiv":"Θετική σύντηξη FGFR2","Target-Relevanz und passende Therapielinie im hepatobiliären MTB diskutieren.":"Συζητήστε τη σημασία του target και την κατάλληλη θεραπευτική γραμμή στο ηπατοχολικό MTB.","Der Befund verändert die nächste Linienplanung.":"Το εύρημα αλλάζει τον σχεδιασμό της επόμενης γραμμής.","FGFR2 negativ, DNA-Profil ohne Target":"FGFR2 αρνητικό, DNA προφίλ χωρίς target","Weitere im validierten Panel erfasste Alterationsklassen und Studienoptionen prüfen.":"Εξετάστε άλλες κατηγορίες αλλοιώσεων που καλύπτονται από το επικυρωμένο panel και επιλογές κλινικών μελετών.","Negativbefund bleibt methodisch transparent.":"Το αρνητικό αποτέλεσμα παραμένει μεθοδολογικά διαφανές.","Nur CNS-IDH/Methylom gewählt":"Επιλέχθηκαν μόνο IDH/μεθύλωμα ΚΝΣ","Anforderung korrigieren und CCA-spezifische Diagnostik durchführen.":"Διορθώστε το αίτημα και διενεργήστε διάγνωση ειδική για CCA.","Material/TAT-Verlust, aber fachlich rettbarer Fall.":"Απώλεια υλικού/TAT, αλλά κλινικά διασώσιμη περίπτωση.","Beim iCCA ist molekulare Profilierung Teil moderner Therapieplanung.":"Στο iCCA, το μοριακό profiling αποτελεί μέρος του σύγχρονου θεραπευτικού σχεδιασμού.","FGFR2-Fusionen sind strukturelle Alterationen und benötigen passende Assayabdeckung.":"Οι συντήξεις FGFR2 είναι δομικές αλλοιώσεις και απαιτούν κατάλληλη κάλυψη assay.","IDH1/2 im Cholangiokarzinom ist nicht dasselbe diagnostische Problem wie IDH/G-CIMP im Gliom.":"Τα IDH1/2 στο χολαγγειοκαρκίνωμα δεν αποτελούν το ίδιο διαγνωστικό πρόβλημα με IDH/G-CIMP στο γλοίωμα.","Cross-Template-Copyover ist ein reales Qualitätsrisiko in standardisierten Fallbibliotheken und Labor-Workflows.":"Το cross-template copyover αποτελεί πραγματικό κίνδυνο ποιότητας σε τυποποιημένες βιβλιοθήκες περιστατικών και εργαστηριακές ροές εργασίας.","CCA-spezifisches Molekularprofil plus explizite FGFR2-Fusions-/Rearrangementdiagnostik. Ergebnis: FGFR2::BICC1-Fusion, IDH1/2 wildtyp. Die bisherigen neuroonkologischen IDH1-R132H-/G-CIMP-/Methylierungsclassifier-Elemente sind fachfremd und werden vollständig entfernt.":"Μοριακό προφίλ ειδικό για CCA συν ρητός έλεγχος σύντηξης/αναδιάταξης FGFR2. Αποτέλεσμα: σύντηξη FGFR2::BICC1, IDH1/2 wild type. Τα προηγούμενα νευρο-ογκολογικά στοιχεία IDH1-R132H/G-CIMP/classifier μεθυλίωσης είναι ακατάλληλα και αφαιρούνται πλήρως.","iCCA-Kontext erkannt":"Αναγνωρίστηκε το πλαίσιο iCCA","FGFR2 strukturell korrekt getestet":"FGFR2 ελέγχθηκε σωστά ως δομική αλλοίωση","IDH1/2 entitätsspezifisch eingeordnet":"IDH1/2 ερμηνεύτηκαν ειδικά για την οντότητα","CNS-Copyover aktiv verworfen":"Το copyover ΚΝΣ απορρίφθηκε ενεργά","Wann reicht ein DNA-Panel für Fusionen, wann nicht?":"Πότε αρκεί ένα DNA panel για συντήξεις και πότε όχι;","Welche weiteren Alterationsklassen sollten CCA-Panels abdecken?":"Ποιες άλλες κατηγορίες αλλοιώσεων πρέπει να καλύπτουν τα CCA panels;","Wie können Template-Bibliotheken gegen Cross-Entity-Copyover QA-gesichert werden?":"Πώς μπορούν οι βιβλιοθήκες templates να διασφαλιστούν με QA έναντι cross-entity copyover;","FGFR2::BICC1 nach DNA-only Negativbefund":"FGFR2::BICC1 μετά από αρνητικό DNA-only αποτέλεσμα","Strukturelle Targets brauchen passende Methoden":"Οι δομικοί στόχοι απαιτούν κατάλληλες μεθόδους","DNA-negativ → Assaycheck → CCA-Profil + Fusion → FGFR2":"DNA αρνητικό → έλεγχος assay → προφίλ CCA + σύντηξη → FGFR2","Rechte Kolonkarzinom-Metastase mit BRAF V600E → Prognose, MSI-Kontext, Therapieoption":"Μετάσταση δεξιού καρκίνου παχέος εντέρου με BRAF V600E → πρόγνωση, πλαίσιο MSI, θεραπευτική επιλογή","Rechte Kolonkarzinom-Metastase mit…":"Μετάσταση δεξιού καρκίνου παχέος εντέρου με…","Viszeralonkologie / Molekulares Tumorboard":"Σπλαχνική ογκολογία / Μοριακό ογκολογικό συμβούλιο","72-jährige Patientin mit rechtsseitigem Kolonkarzinom und synchronen Leber- und Peritonealmetastasen.":"Γυναίκα 72 ετών με καρκίνο δεξιού κόλου και σύγχρονες ηπατικές και περιτοναϊκές μεταστάσεις.","Im Tumorprofil wurde BRAF p.V600E nachgewiesen. Welche prognostische und therapeutische Bedeutung hat der Befund im CRC – und was muss zusätzlich über MMR/MSI bekannt sein?":"Στο προφίλ όγκου ανιχνεύθηκε BRAF p.V600E. Ποια είναι η προγνωστική και θεραπευτική του σημασία στο CRC – και τι άλλο πρέπει να γνωρίζουμε για MMR/MSI;","Die Erstlinienstrategie soll im MTB innerhalb weniger Tage festgelegt werden.":"Η στρατηγική πρώτης γραμμής πρέπει να καθοριστεί στο MTB εντός λίγων ημερών.","Coecum/Colon ascendens, rechtsseitig.":"Τυφλό/ανιόν κόλον, δεξιά πλευρά.","Metastasiert mit Leber- und Peritonealbefall; ECOG 1.":"Μεταστατική νόσος με ηπατική και περιτοναϊκή συμμετοχή· ECOG 1.","BRAF V600E wird reflexartig wie beim Melanom interpretiert oder mit MSI-H gleichgesetzt. Beides ist im CRC falsch bzw. unvollständig.":"Το BRAF V600E ερμηνεύεται αντανακλαστικά όπως στο μελάνωμα ή εξισώνεται με MSI-H. Και τα δύο είναι λανθασμένα ή ελλιπή στο CRC.","Mäßig bis gering differenziertes kolorektales Adenokarzinom mit fokal muzinöser Morphologie.":"Μέτρια έως χαμηλά διαφοροποιημένο ορθοκολικό αδενοκαρκίνωμα με εστιακή βλεννώδη μορφολογία.","Lineage":"Γραμμή διαφοροποίησης","CDX2/SATB2 positiv; Morphologie und Klinik vereinbar mit kolorektalem Primarius.":"CDX2/SATB2 θετικά· μορφολογία και κλινικό πλαίσιο συμβατά με ορθοκολική πρωτοπαθή εστία.","Molekularer Vorbefund":"Προηγούμενο μοριακό αποτέλεσμα","BRAF p.V600E in einer schnellen Einzeltestung nachgewiesen.":"BRAF p.V600E ανιχνεύθηκε σε ταχεία εξέταση μεμονωμένου γονιδίου.","Ist der Tumor dMMR/MSI-H oder pMMR/MSS, und wie muss die BRAF-Alteration CRC-spezifisch therapeutisch eingeordnet werden?":"Είναι ο όγκος dMMR/MSI-H ή pMMR/MSS και πώς πρέπει να ερμηνευθεί θεραπευτικά η αλλοίωση BRAF με CRC-ειδικό τρόπο;","FFPE-Resektat, Block C6 mit vitalem invasivem Tumor.":"FFPE παρασκεύασμα εκτομής, block C6 με βιώσιμο διηθητικό όγκο.","ca. 55 %, gut geeignet für DNA-basierte Analysen.":"περ. 55%, κατάλληλο για DNA-βασισμένες αναλύσεις.","DNA-Qualität gut; MMR-IHC technisch gut beurteilbar.":"Καλή ποιότητα DNA· η IHC MMR είναι τεχνικά καλά αξιολογήσιμη.","Melanom-spezifische BRAF-Methoden oder Therapiealgorithmen beantworten die CRC-Frage nicht.":"Οι ειδικές για μελάνωμα μέθοδοι BRAF ή θεραπευτικοί αλγόριθμοι δεν απαντούν στο ερώτημα του CRC.","BRAF-V600E im CRC-Kontext":"BRAF V600E στο πλαίσιο CRC","MMR-IHC":"IHC MMR","MSI-Testung":"Έλεγχος MSI","BRAF V600E":"BRAF V600E","BRAF p.V600E nachweisbar. Der Befund ist im metastasierten CRC prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden – nicht nach dem Melanom-Algorithmus.":"Ανιχνεύεται BRAF p.V600E. Το εύρημα είναι προγνωστικά και θεραπευτικά σχετικό στο μεταστατικό CRC, αλλά πρέπει να ερμηνεύεται βάσει CRC-ειδικής τεκμηρίωσης – όχι αλγορίθμου μελανώματος.","Erweiterter RAS-Status":"Εκτεταμένη κατάσταση RAS","KRAS/NRAS Wildtyp. Der BRAF-V600E-Befund bleibt der dominante MAPK-Treiberkontext.":"KRAS/NRAS wild type. Το εύρημα BRAF V600E παραμένει το κυρίαρχο πλαίσιο driver MAPK.","Intakte nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Διατηρημένη πυρηνική έκφραση MLH1, PMS2, MSH2 και MSH6: pMMR.","MSI":"MSI","MSS / kein MSI-H. BRAF V600E ist damit gerade nicht automatisch mit MSI-H gleichzusetzen.":"MSS / χωρίς MSI-H. Το BRAF V600E επομένως δεν ισοδυναμεί αυτόματα με MSI-H.","MLH1-Methylierung":"Μεθυλίωση MLH1","Bei erhaltener MLH1/PMS2-Expression besteht in diesem Fall keine primäre Reflexindikation; die Zusatzanalyse liefert keinen entscheidungsrelevanten Mehrwert.":"Με διατηρημένη έκφραση MLH1/PMS2 δεν υπάρχει πρωτογενής ένδειξη reflex σε αυτή την περίπτωση· η πρόσθετη ανάλυση δεν προσφέρει όφελος σχετικό με την απόφαση.","Tumoranteil und DNA-Qualität ausreichend; MMR-IHC auswertbar.":"Επαρκές ποσοστό όγκου και ποιότητα DNA· αξιολογήσιμη IHC MMR.","BRAF p.V600E liegt in einem rechtsseitigen, pMMR/MSS metastasierten CRC vor. Der Befund ist prognostisch ungünstig und eröffnet einen CRC-spezifischen BRAF-gerichteten Therapiekontext mit EGFR-Blockade nach aktueller Therapielinie/Leitlinie. Eine Melanom-artige BRAF/MEK-Übertragung ist nicht angemessen; BRAF V600E bedeutet außerdem nicht automatisch MSI-H.":"Το BRAF p.V600E υπάρχει σε δεξιό, pMMR/MSS μεταστατικό CRC. Το εύρημα είναι δυσμενές προγνωστικά και ανοίγει CRC-ειδικό θεραπευτικό πλαίσιο στόχευσης BRAF με αποκλεισμό EGFR σύμφωνα με την τρέχουσα γραμμή/κατευθυντήρια οδηγία. Η μεταφορά σχήματος BRAF/MEK τύπου μελανώματος είναι ακατάλληλη· το BRAF V600E επίσης δεν σημαίνει αυτόματα MSI-H.","Teilbefund: BRAF V600E ist bekannt, aber ohne MMR/MSI-Kontext bleibt die molekulare Einordnung unvollständig. Therapie- und Prognoseaussagen dürfen nicht aus einem Melanom-Template übernommen werden.":"Μερικό εύρημα: Το BRAF V600E είναι γνωστό, αλλά χωρίς πλαίσιο MMR/MSI η μοριακή ταξινόμηση παραμένει ελλιπής. Οι θεραπευτικές και προγνωστικές δηλώσεις δεν πρέπει να αντιγράφονται από template μελανώματος.","BRAF V600E als CRC-spezifischen prognostisch/therapeutisch relevanten Befund benennen":"Αναφέρετε το BRAF V600E ως CRC-ειδικό εύρημα με προγνωστική και θεραπευτική σημασία","BRAF V600E nicht mit MSI-H gleichsetzen; pMMR/MSS separat kommunizieren":"Μην εξισώνετε BRAF V600E με MSI-H· αναφέρετε ξεχωριστά pMMR/MSS","BRAF-gerichtete Strategie im CRC mit EGFR-Blockade und aktueller Therapielinie verknüpfen, nicht mit einem Melanom-Schema":"Συνδέστε τη CRC-ειδική στρατηγική στόχευσης BRAF με αποκλεισμό EGFR και την τρέχουσα θεραπευτική γραμμή, όχι με σχήμα μελανώματος","Entitätsspezifische Evidenz und aktuelle Leitlinien-/Zulassungssituation sprachlich sauber begrenzen":"Διατυπώστε την ειδική για την οντότητα τεκμηρίωση και την τρέχουσα κατάσταση οδηγιών/έγκρισης με κατάλληλους περιορισμούς","Optimale Lösung: BRAF V600E, RAS-Kontext und MMR/MSI gemeinsam einordnen; der Tumor ist pMMR/MSS und benötigt eine CRC-spezifische BRAF-/EGFR-Therapielogik statt eines Melanom-Copyovers.":"Βέλτιστη λύση: Ερμηνεύστε μαζί BRAF V600E, πλαίσιο RAS και MMR/MSI· ο όγκος είναι pMMR/MSS και απαιτεί CRC-ειδική θεραπευτική λογική BRAF/EGFR αντί για copyover μελανώματος.","CRC":"CRC","mCRC":"mCRC","pMMR":"pMMR","MSS":"MSS","anti-EGFR":"anti-EGFR","Targeted Therapy":"Στοχευμένη θεραπεία","BRAF V600E im rechten mCRC: CRC-Biologie statt Melanom-Copyover":"BRAF V600E σε δεξιό mCRC: βιολογία CRC αντί copyover μελανώματος","Molekularpathologie / Viszeralonkologie / MTB":"Μοριακή παθολογία / Σπλαχνική ογκολογία / MTB","BRAF V600E beim mCRC prognostisch und therapeutisch korrekt einordnen.":"Ερμηνεύστε σωστά το BRAF V600E προγνωστικά και θεραπευτικά στο mCRC.","BRAF V600E nicht automatisch mit MSI-H gleichsetzen, sondern MMR/MSI separat prüfen.":"Μην εξισώνετε αυτόματα BRAF V600E με MSI-H· αξιολογήστε ξεχωριστά MMR/MSI.","Die CRC-spezifische BRAF-Therapielogik von Melanom-Algorithmen abgrenzen.":"Διαχωρίστε τη CRC-ειδική θεραπευτική λογική BRAF από τους αλγορίθμους μελανώματος.","Rechtsseitigkeit, pMMR/MSS und BRAF-Kontext in einer integrierten MTB-Aussage zusammenführen.":"Ενσωματώστε πλευρικότητα, pMMR/MSS και πλαίσιο BRAF σε μία ενιαία δήλωση MTB.","Im MTB fällt sofort der rote Marker 'BRAF V600E' ins Auge. Jemand schlägt vor, den Fall wie ein BRAF-mutiertes Melanom zu behandeln; ein anderer sagt, rechtsseitig plus BRAF sei wahrscheinlich ohnehin MSI-high. Beides klingt auf den ersten Blick plausibel – und beides greift zu kurz.":"Στο MTB, ο κόκκινος δείκτης «BRAF V600E» τραβά αμέσως την προσοχή. Κάποιος προτείνει να αντιμετωπιστεί το περιστατικό σαν BRAF-mutant μελάνωμα· άλλος λέει ότι δεξιό CRC με BRAF είναι πιθανότατα ούτως ή άλλως MSI-high. Και τα δύο ακούγονται αρχικά εύλογα – και τα δύο όμως είναι ανεπαρκή.","72-jährige Patientin mit rechtsseitigem metastasiertem CRC. BRAF p.V600E wurde bereits nachgewiesen. Die Lernaufgabe besteht darin, die Mutation entitätsspezifisch zu interpretieren, MMR/MSI unabhängig zu klären und aus Prognose, Immuntherapie- und BRAF-Targetkontext eine belastbare MTB-Empfehlung zu formulieren.":"Γυναίκα 72 ετών με δεξιό μεταστατικό CRC. Το BRAF p.V600E είναι ήδη γνωστό. Στόχος είναι η ειδική για την οντότητα ερμηνεία της μετάλλαξης, η ανεξάρτητη διευκρίνιση MMR/MSI και η διατύπωση ισχυρής σύστασης MTB από πρόγνωση, ανοσοθεραπευτικό πλαίσιο και στόχευση BRAF.","Tumorbiologie":"Βιολογία όγκου","Rechtsseitiges metastasiertes CRC mit BRAF V600E.":"Δεξιό μεταστατικό CRC με BRAF V600E.","BRAF ist ein starker biologischer Kontextmarker, aber nicht die gesamte Therapieentscheidung.":"Το BRAF είναι ισχυρός βιολογικός δείκτης πλαισίου, αλλά όχι ολόκληρη η θεραπευτική απόφαση.","Zu Beginn noch unbekannt.":"Αρχικά άγνωστο.","BRAF V600E und MSI-H sind assoziiert, aber nicht synonym.":"BRAF V600E και MSI-H συσχετίζονται, αλλά δεν είναι συνώνυμα.","Therapiekontext":"Θεραπευτικό πλαίσιο","Erstlinienentscheidung steht an.":"Εκκρεμεί απόφαση πρώτης γραμμής.","BRAF-Targeting im CRC folgt einer anderen Logik als beim Melanom.":"Η στόχευση BRAF στο CRC ακολουθεί διαφορετική λογική από το μελάνωμα.","Schneller BRAF-Befund":"Ταχύ αποτέλεσμα BRAF","BRAF p.V600E positiv.":"BRAF p.V600E θετικό.","Rechtsseitiges kolorektales Adenokarzinom, metastasiert.":"Δεξιό ορθοκολικό αδενοκαρκίνωμα, μεταστατικό.","Material ausreichend für MMR-IHC und MSI-Testung.":"Επαρκές υλικό για IHC MMR και έλεγχο MSI.","Zehn Schnitte reichen für eine fokussierte CRC-Diagnostik.":"Δέκα τομές αρκούν για εστιασμένη διάγνωση CRC.","Melanom-spezifische Zusatztests sind methodisch und didaktisch Low Value.":"Οι πρόσθετες εξετάσεις ειδικές για μελάνωμα έχουν χαμηλή μεθοδολογική και διδακτική αξία.","MMR/MSI muss trotz bekanntem BRAF-Befund eigenständig beantwortet werden.":"Το MMR/MSI πρέπει να απαντηθεί ανεξάρτητα παρά το γνωστό αποτέλεσμα BRAF.","Welche Aussage zum BRAF-V600E-Befund ist im mCRC am treffendsten?":"Ποια δήλωση για BRAF V600E στο mCRC είναι η πιο ακριβής;","BRAF V600E ist prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden; ein Melanom-Algorithmus darf nicht übertragen werden.":"Το BRAF V600E είναι προγνωστικά και θεραπευτικά σχετικό, αλλά πρέπει να ερμηνεύεται βάσει CRC-ειδικής τεκμηρίωσης· δεν πρέπει να μεταφέρεται αλγόριθμος μελανώματος.","BRAF V600E bedeutet unabhängig von der Entität denselben BRAF/MEK-Algorithmus wie beim Melanom.":"Το BRAF V600E σημαίνει τον ίδιο αλγόριθμο BRAF/MEK όπως στο μελάνωμα, ανεξάρτητα από την οντότητα.","BRAF V600E ist beim CRC nur prognostisch, nicht therapeutisch relevant.":"Στο CRC, το BRAF V600E είναι μόνο προγνωστικό και όχι θεραπευτικά σχετικό.","Bei rechtsseitigem CRC spielt BRAF keine Rolle.":"Στο δεξιό CRC, το BRAF δεν έχει σημασία.","Entitätsspezifische Biologie und Therapiedaten sind entscheidend.":"Η ειδική για την οντότητα βιολογία και τα θεραπευτικά δεδομένα είναι καθοριστικά.","BRAF V600E ist nachgewiesen. Was folgt für MMR/MSI?":"Ανιχνεύεται BRAF V600E. Τι συνεπάγεται αυτό για MMR/MSI;","MMR/MSI weiterhin separat bestimmen; BRAF V600E beweist weder dMMR noch MSI-H.":"Συνεχίστε να αξιολογείτε MMR/MSI ξεχωριστά· το BRAF V600E δεν αποδεικνύει ούτε dMMR ούτε MSI-H.","BRAF V600E reicht als Surrogat für MSI-H.":"Το BRAF V600E αρκεί ως υποκατάστατο για MSI-H.","MMR/MSI ist bei BRAF-mutiertem mCRC therapeutisch bedeutungslos.":"Το MMR/MSI είναι θεραπευτικά άσχετο στο BRAF-mutant mCRC.","PD-L1 ersetzt die MSI-Testung.":"Το PD-L1 αντικαθιστά τον έλεγχο MSI.","Die MMR/MSI-Ebene besitzt eine unabhängige prädiktive und ggf. hereditäre Bedeutung.":"Το επίπεδο MMR/MSI έχει ανεξάρτητη προβλεπτική και ενδεχομένως κληρονομική σημασία.","Welche Targetlogik ist für BRAF V600E im mCRC korrekt?":"Ποια λογική στόχευσης είναι σωστή για BRAF V600E στο mCRC;","CRC-spezifische BRAF-gerichtete Strategie unter Einbezug der EGFR-Achse gemäß aktueller Therapielinie/Leitlinie.":"CRC-ειδική στρατηγική στόχευσης BRAF με ενσωμάτωση του άξονα EGFR σύμφωνα με την τρέχουσα θεραπευτική γραμμή/οδηγία.","BRAF-Inhibitor allein ist die logische Standardstrategie.":"Ο αναστολέας BRAF μόνος είναι η λογική standard στρατηγική.","BRAF/MEK wie beim Melanom ohne CRC-spezifischen Kontext.":"BRAF/MEK όπως στο μελάνωμα χωρίς CRC-ειδικό πλαίσιο.","BRAF V600E ist nicht targetierbar.":"Το BRAF V600E δεν είναι στοχεύσιμο.","Beim CRC ist die EGFR-Rückkopplung/Signalachse Teil der therapeutischen BRAF-Logik.":"Στο CRC, η ανάδραση/σηματοδότηση EGFR αποτελεί μέρος της θεραπευτικής λογικής BRAF.","Interpretieren Sie BRAF V600E in einem rechtsseitigen mCRC und vervollständigen Sie MMR/MSI so, dass Prognose, Immuntherapie- und BRAF-Targetkontext sauber getrennt und integriert werden.":"Ερμηνεύστε BRAF V600E σε δεξιό mCRC και ολοκληρώστε MMR/MSI ώστε πρόγνωση, ανοσοθεραπεία και πλαίσιο στόχευσης BRAF να διαχωρίζονται και να ενσωματώνονται καθαρά.","BRAF-V600E-Befund entitätsspezifisch bestätigen/einordnen.":"Επιβεβαιώστε/ταξινομήστε το εύρημα BRAF V600E ειδικά για την οντότητα.","MMR-IHC und MSI unabhängig bestimmen.":"Προσδιορίστε ανεξάρτητα IHC MMR και MSI.","Ergebnis pMMR/MSS explizit kommunizieren.":"Αναφέρετε ρητά το αποτέλεσμα pMMR/MSS.","BRAF V600E als prognostisch ungünstigen und therapeutisch relevanten CRC-Kontext berichten.":"Αναφέρετε BRAF V600E ως δυσμενές προγνωστικό και θεραπευτικά σχετικό πλαίσιο CRC.","Keinen Melanom-Algorithmus übertragen; aktuelle CRC-spezifische BRAF/EGFR-Strategie heranziehen.":"Μην μεταφέρετε αλγόριθμο μελανώματος· χρησιμοποιήστε την τρέχουσα CRC-ειδική στρατηγική BRAF/EGFR.","Kolon-NGS-Panel zur gemeinsamen Erfassung von BRAF/RAS plus separate MMR-IHC/MSI.":"Colon NGS panel για κοινή ανίχνευση BRAF/RAS συν ξεχωριστά IHC MMR/MSI.","Breiteres validiertes Pan-Panel, sofern BRAF und MSI zuverlässig abgedeckt und die MMR-IHC sinnvoll ergänzt werden.":"Ευρύτερο επικυρωμένο pan-panel εφόσον BRAF και MSI καλύπτονται αξιόπιστα και προστίθεται κατάλληλα IHC MMR.","Melanom-BRAF-Template":"BRAF template μελανώματος","Gleiche Mutation bedeutet nicht gleichen Therapiealgorithmus über Tumorentitäten hinweg.":"Η ίδια μετάλλαξη δεν σημαίνει τον ίδιο θεραπευτικό αλγόριθμο σε διαφορετικές οντότητες όγκου.","BRAF = MSI-H":"BRAF = MSI-H","Assoziation ist kein Ersatz für MMR/MSI-Diagnostik.":"Η συσχέτιση δεν υποκαθιστά τον έλεγχο MMR/MSI.","BRAF allein befundet":"Αναφέρθηκε μόνο BRAF","Der Immuntherapie-/MMR-Kontext bleibt offen.":"Το πλαίσιο ανοσοθεραπείας/MMR παραμένει άλυτο.","BRAF V600E – aber pMMR/MSS":"BRAF V600E – αλλά pMMR/MSS","Die MMR-IHC ist vollständig erhalten und die MSI-Testung zeigt MSS. Der rechtsseitige BRAF-V600E-Tumor ist damit gerade kein MSI-H-Fall. Gleichzeitig wird klar: Der BRAF-Befund führt nicht in einen Melanom-Pfad, sondern in eine CRC-spezifische BRAF-/EGFR-Therapielogik.":"Η IHC MMR είναι πλήρως διατηρημένη και ο έλεγχος MSI δείχνει MSS. Επομένως ο δεξιός BRAF V600E όγκος δεν είναι περίπτωση MSI-H. Παράλληλα γίνεται σαφές ότι το εύρημα BRAF δεν οδηγεί σε οδό μελανώματος αλλά σε CRC-ειδική θεραπευτική λογική BRAF/EGFR.","Der Fall löst zwei häufige Kurzschlüsse gleichzeitig auf: BRAF ist weder ein MSI-Surrogat noch eine entitätsunabhängige Therapieschablone.":"Η περίπτωση διορθώνει ταυτόχρονα δύο συχνές συντομεύσεις: το BRAF δεν είναι ούτε υποκατάστατο MSI ούτε ανεξάρτητο από την οντότητα θεραπευτικό template.","CRC-spezifisch vollständig":"Πλήρες και ειδικό για CRC","BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Prognostisch ungünstiger BRAF-Kontext; CRC-spezifische BRAF-gerichtete Strategie mit EGFR-Blockade nach aktueller Linie/Leitlinie diskutieren.":"BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Δυσμενές προγνωστικό πλαίσιο BRAF· συζητήστε CRC-ειδική στρατηγική στόχευσης BRAF με αποκλεισμό EGFR σύμφωνα με την τρέχουσα γραμμή/οδηγία.","Entität, MSI und Targetlogik korrekt integriert.":"Οντότητα, MSI και λογική στόχευσης ενσωματώθηκαν σωστά.","Nur BRAF":"Μόνο BRAF","BRAF V600E ist bekannt, MMR/MSI bleibt offen.":"Το BRAF V600E είναι γνωστό· MMR/MSI παραμένει άλυτο.","Therapeutisch und biologisch unvollständig.":"Θεραπευτικά και βιολογικά ελλιπές.","Melanom-Copyover":"Copyover μελανώματος","BRAF/MEK-Logik wird ohne CRC-spezifischen Kontext übertragen.":"Η λογική BRAF/MEK μεταφέρεται χωρίς CRC-ειδικό πλαίσιο.","Cross-Entity-Fehlinterpretation.":"Εσφαλμένη ερμηνεία μεταξύ οντοτήτων.","pMMR/MSS bestätigt":"pMMR/MSS επιβεβαιωμένο","BRAF- und Chemotherapie-/EGFR-Kontext nach aktueller Linie im MTB diskutieren.":"Συζητήστε στο MTB το πλαίσιο BRAF και χημειοθεραπείας/EGFR σύμφωνα με την τρέχουσα θεραπευτική γραμμή.","Der Fall bleibt Targeted-Therapy-orientiert, ohne MSI-H-IO-Pfad.":"Η περίπτωση παραμένει προσανατολισμένη στη στοχευμένη θεραπεία, χωρίς οδό IO MSI-H.","unerwartet dMMR/MSI-H":"απρόσμενο dMMR/MSI-H","Immuntherapie- und Lynch/sporadisch-Kontext zusätzlich priorisieren.":"Δώστε επιπλέον προτεραιότητα στην ανοσοθεραπεία και στο πλαίσιο Lynch/σποραδικού.","Therapiepriorisierung verändert sich.":"Η θεραπευτική ιεράρχηση αλλάζει.","BRAF V600E ist im CRC entitätsspezifisch zu interpretieren.":"Το BRAF V600E πρέπει να ερμηνεύεται ειδικά για την οντότητα στο CRC.","BRAF V600E und MSI-H sind nicht gleichbedeutend.":"BRAF V600E και MSI-H δεν είναι ισοδύναμα.","MMR/MSI bleibt ein unabhängiger Biomarkerblock.":"Το MMR/MSI παραμένει ανεξάρτητο block βιοδεικτών.","BRAF-gerichtete Therapie im CRC bindet die EGFR-Achse ein und darf nicht aus dem Melanom kopiert werden.":"Η στοχευμένη θεραπεία BRAF στο CRC ενσωματώνει τον άξονα EGFR και δεν πρέπει να αντιγράφεται από το μελάνωμα.","BRAF V600E + pMMR/MSS im rechtsseitigen mCRC. Kein Melanom-Algorithmus; CRC-spezifische BRAF-/EGFR-Strategie nach aktueller Therapielinie. MMR/MSI separat bestimmt und korrekt negativ eingeordnet.":"BRAF V600E + pMMR/MSS σε δεξιό mCRC. Χωρίς αλγόριθμο μελανώματος· CRC-ειδική στρατηγική BRAF/EGFR σύμφωνα με την τρέχουσα θεραπευτική γραμμή. MMR/MSI ελέγχθηκε ξεχωριστά και ερμηνεύτηκε σωστά ως αρνητικό.","Entitätsspezifische BRAF-Interpretation":"Ειδική για την οντότητα ερμηνεία BRAF","MMR/MSI unabhängig geprüft":"MMR/MSI ελέγχθηκε ανεξάρτητα","kein Melanom-Copyover":"χωρίς copyover μελανώματος","Prognose vs. Prädiktion getrennt":"Διαχωρισμός πρόγνωσης έναντι πρόβλεψης","Warum ist BRAF V600E kein MSI-Surrogat?":"Γιατί το BRAF V600E δεν είναι υποκατάστατο MSI;","Warum reicht BRAF-Hemmung allein im CRC biologisch/klinisch nicht als Übertrag aus dem Melanom?":"Γιατί η αναστολή BRAF μόνη της δεν μεταφέρεται βιολογικά/κλινικά από το μελάνωμα στο CRC;","Welche Rolle spielt die Tumorlokalisation zusätzlich?":"Ποιον πρόσθετο ρόλο παίζει η πλευρικότητα του όγκου;","DE master":"DE master","BRAF V600E, aber pMMR/MSS":"BRAF V600E, αλλά pMMR/MSS","Mutation ist entitätsspezifisch zu interpretieren":"Η μετάλλαξη πρέπει να ερμηνεύεται ειδικά για την οντότητα","BRAF+ → MMR/MSI separat → pMMR/MSS → CRC-spezifische BRAF/EGFR-Logik":"BRAF+ → ξεχωριστός έλεγχος MMR/MSI → pMMR/MSS → CRC-ειδική λογική BRAF/EGFR","Polypenrest statt invasivem Tumor eingeschickt → Befundbar oder neues Material anfordern?":"Υπόλειμμα πολύποδα αντί διηθητικού όγκου → Μπορεί να αναφερθεί ή χρειάζεται νέο υλικό;","Polypenrest statt invasivem Tumor …":"Υπόλειμμα πολύποδα αντί διηθητικού όγκου …","Viszeralonkologie / Molekularpathologie":"Σπλαχνική ογκολογία / Μοριακή παθολογία","64-jähriger Patient mit metastasiertem Sigma-Karzinom; vor Beginn der Systemtherapie werden RAS/BRAF und MMR/MSI angefordert.":"Ασθενής 64 ετών με μεταστατικό καρκίνωμα σιγμοειδούς· ζητούνται RAS/BRAF και MMR/MSI πριν από συστηματική θεραπεία.","Der eingesandte Block soll 'repräsentatives Tumorgewebe' enthalten. Ist das Material tatsächlich für die prädiktive Diagnostik geeignet?":"Το υποβληθέν block υποτίθεται ότι περιέχει «αντιπροσωπευτικό ιστό όγκου». Είναι πράγματι κατάλληλο για προβλεπτική διάγνωση;","MTB in vier Tagen; die Onkologie bittet ausdrücklich um eine schnelle Freigabe.":"MTB σε τέσσερις ημέρες· η ογκολογία ζητά ρητά ταχεία έκδοση.","Vorgeschichte":"Ιστορικό","Zunächst endoskopische Polypektomie, anschließend onkologische Sigmaresektion mit invasivem Adenokarzinom; inzwischen Lebermetastasen.":"Αρχικά ενδοσκοπική πολυπεκτομή, κατόπιν ογκολογική εκτομή σιγμοειδούς με διηθητικό αδενοκαρκίνωμα· τώρα ηπατικές μεταστάσεις.","Anforderung":"Αίτημα","Auf dem Molekularschein steht Block 'A1'. Im Pathologiesystem existieren jedoch sowohl Polypektomie A1 als auch Resektionsblock B7.":"Στο μοριακό παραπεμπτικό αναγράφεται block «A1». Στο σύστημα παθολογίας όμως υπάρχουν τόσο η πολυπεκτομή A1 όσο και το block εκτομής B7.","Ein automatisches 'Material vorhanden → testen' wäre schnell, könnte aber die falsche Läsion analysieren.":"Μια αυτόματη προσέγγιση «υλικό διαθέσιμο → εξέταση» θα ήταν γρήγορη αλλά θα μπορούσε να αναλύσει τη λάθος βλάβη.","Technisch erfolgreiche Molekulardiagnostik ist nicht automatisch klinisch valide, wenn das untersuchte Gewebe die Fragestellung nicht repräsentiert.":"Η τεχνικά επιτυχής μοριακή διάγνωση δεν είναι αυτόματα κλινικά έγκυρη εάν ο εξεταζόμενος ιστός δεν αντιπροσωπεύει το κλινικό ερώτημα.","HE-Reevaluation des eingesandten Blocks":"Επανεκτίμηση H&E του υποβληθέντος block","Tubulovillöses Adenom mit hochgradiger intraepithelialer Neoplasie; kein sicher invasives Karzinom im eingesandten Material.":"Σωληνολαχνωτό αδένωμα με υψηλόβαθμη ενδοεπιθηλιακή νεοπλασία· χωρίς βέβαιο διηθητικό καρκίνωμα στο υποβληθέν υλικό.","Diskrepanz":"Ασυμφωνία","Die klinische Anforderung lautet metastasiertes CRC, der ausgewählte Block repräsentiert jedoch nur den früheren Polypenrest.":"Το κλινικό αίτημα αφορά μεταστατικό CRC, αλλά το επιλεγμένο block αντιπροσωπεύει μόνο το προηγούμενο υπόλειμμα πολύποδα.","Verfügbarer Alternativblock":"Διαθέσιμο εναλλακτικό block","Im Archiv ist Resektionsblock B7 mit invasivem Adenokarzinom und ca. 60 % Tumor dokumentiert.":"Στο αρχείο τεκμηριώνεται block εκτομής B7 με διηθητικό αδενοκαρκίνωμα και περ. 60% όγκο.","Darf der Polypenblock trotzdem molekular befundet werden oder muss die Analyse gestoppt und repräsentatives invasives Tumormaterial angefordert werden?":"Μπορεί παρ’ όλα αυτά να εκδοθεί μοριακή έκθεση από το block πολύποδα ή πρέπει να σταματήσει η ανάλυση και να ζητηθεί αντιπροσωπευτικό διηθητικό υλικό όγκου;","Eingesandter Block":"Υποβληθέν block","Polypektomie A1, adenomatöses Gewebe ohne sichere Invasion.":"Πολυπεκτομή A1, αδενωματώδης ιστός χωρίς βέβαιη διήθηση.","Tumoranteil für die klinische Fragestellung":"Ποσοστό όγκου για το κλινικό ερώτημα","0 % sicher invasives Karzinom.":"0% βέβαιο διηθητικό καρκίνωμα.","Technische DNA-Qualität":"Τεχνική ποιότητα DNA","gut – genau das macht die Falle gefährlich.":"καλή – ακριβώς αυτό κάνει την παγίδα επικίνδυνη.","Archivhinweis":"Σημείωση αρχείου","Resektionsblock B7 ist verfügbar und enthält repräsentatives invasives Karzinom.":"Το block εκτομής B7 είναι διαθέσιμο και περιέχει αντιπροσωπευτικό διηθητικό καρκίνωμα.","Ein molekular technisch plausibler Befund aus dem Polypenrest darf nicht als Biomarkerbefund des metastasierten invasiven Karzinoms ausgegeben werden.":"Ένα τεχνικά εύλογο μοριακό αποτέλεσμα από το υπόλειμμα πολύποδα δεν πρέπει να εκδίδεται ως αποτέλεσμα βιοδεικτών του μεταστατικού διηθητικού καρκινώματος.","Materialidentität / HE-Reevaluation":"Ταυτότητα υλικού / επανεκτίμηση H&E","Repräsentatives invasives Tumormaterial anfordern":"Ζητήστε αντιπροσωπευτικό υλικό διηθητικού όγκου","HE-Reevaluation":"Επανεκτίμηση H&E","Im eingesandten Block findet sich adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Das Material repräsentiert die klinische Fragestellung nicht.":"Το υποβληθέν block περιέχει αδενωματώδη ιστό με υψηλόβαθμη δυσπλασία αλλά χωρίς βέβαιο διηθητικό καρκίνωμα. Το υλικό δεν αντιπροσωπεύει το κλινικό ερώτημα.","Neues / korrektes Tumormaterial":"Νέο / σωστό υλικό όγκου","Resektionsblock B7 wird nachgefordert: invasives kolorektales Adenokarzinom, ca. 60 % Tumoranteil, für prädiktive Molekulardiagnostik geeignet.":"Ζητείται το block εκτομής B7: διηθητικό ορθοκολικό αδενοκαρκίνωμα, περ. 60% ποσοστό όγκου, κατάλληλο για προβλεπτική μοριακή διάγνωση.","MMR/MSI auf dem falschen Block":"MMR/MSI στο λάθος block","Die Untersuchung kann technisch auswertbar sein, beantwortet aber am adenomatösen Polypenrest die Biomarkerfrage des invasiven/metastasierten Karzinoms nicht belastbar. Keine klinische Freigabe als Tumorbefund.":"Η εξέταση μπορεί να είναι τεχνικά αξιολογήσιμη, αλλά στο αδενωματώδες υπόλειμμα πολύποδα δεν απαντά αξιόπιστα στο ερώτημα βιοδείκτη του διηθητικού/μεταστατικού καρκινώματος. Μην την εκδώσετε κλινικά ως αποτέλεσμα όγκου.","NGS/RAS/BRAF auf dem falschen Block":"NGS/RAS/BRAF στο λάθος block","Technisch plausibler Befund aus adenomatösem Gewebe – z. B. APC-Alteration bei fehlendem RAS/BRAF-Nachweis. Dieser Befund darf nicht als prädiktiver Status des invasiven/metastasierten CRC interpretiert werden.":"Τεχνικά εύλογο εύρημα από αδενωματώδη ιστό – π.χ. αλλοίωση APC χωρίς ανίχνευση RAS/BRAF. Δεν πρέπει να ερμηνεύεται ως προβλεπτική κατάσταση του διηθητικού/μεταστατικού CRC.","Präanalytik":"Προαναλυτική","Anforderung, Blockbezeichnung und Histologie sind diskordant; vor Freigabe muss die Probenidentität bzw. Repräsentativität geklärt werden.":"Αίτημα, ονομασία block και ιστολογία είναι ασύμφωνα· η ταυτότητα/αντιπροσωπευτικότητα του δείγματος πρέπει να διευκρινιστεί πριν από την έκδοση.","Der eingesandte Polypenblock ist für die prädiktive Diagnostik des metastasierten invasiven CRC nicht geeignet. Die Analyse muss für diese klinische Fragestellung gestoppt bzw. nicht freigegeben und repräsentatives invasives Tumormaterial angefordert werden. Ein technisch erfolgreicher Befund aus dem falschen Gewebe wäre klinisch irreführend.":"Το υποβληθέν block πολύποδα είναι ακατάλληλο για προβλεπτική διάγνωση του μεταστατικού διηθητικού CRC. Η εξέταση πρέπει να σταματήσει/να μη δοθεί για αυτό το κλινικό ερώτημα και να ζητηθεί αντιπροσωπευτικό διηθητικό υλικό όγκου. Ένα τεχνικά επιτυχές αποτέλεσμα από λάθος ιστό θα ήταν κλινικά παραπλανητικό.","Teilbefund: Ohne HE-Reevaluation und Abgleich der Blockidentität bleibt unklar, ob das untersuchte Material den invasiven Tumor repräsentiert. Molekulare Ergebnisse dürfen nicht allein aufgrund technischer QC freigegeben werden.":"Μερικό εύρημα: Χωρίς επανεκτίμηση H&E και έλεγχο ταυτότητας του block, παραμένει ασαφές εάν το εξεταζόμενο υλικό αντιπροσωπεύει τον διηθητικό όγκο. Τα μοριακά αποτελέσματα δεν πρέπει να εκδίδονται μόνο βάσει τεχνικού QC.","Falsches/nicht repräsentatives Material als primäres Problem erkennen":"Αναγνωρίστε το λάθος/μη αντιπροσωπευτικό υλικό ως κύριο πρόβλημα","Molekulare Freigabe stoppen bzw. nicht als invasiven Tumor befundet ausgeben":"Σταματήστε τη μοριακή έκδοση ή μην την εκδώσετε ως αποτέλεσμα διηθητικού όγκου","Diskrepanz und Grund der Nachforderung transparent mit Klinik/Pathologie kommunizieren":"Επικοινωνήστε διαφανώς την ασυμφωνία και τον λόγο νέου αιτήματος με την κλινική/παθολογία","Technische Validität klar von klinischer Validität unterscheiden":"Διαχωρίστε σαφώς την τεχνική από την κλινική εγκυρότητα","Optimale Lösung: zuerst HE und Materialidentität prüfen; der eingesandte Polypenrest ist klinisch ungeeignet. Nicht 'irgendetwas' sequenzieren und befundbar machen, sondern den richtigen invasiven Tumorblock anfordern.":"Βέλτιστη λύση: Ελέγξτε πρώτα H&E και ταυτότητα υλικού· το υποβληθέν υπόλειμμα πολύποδα είναι κλινικά ακατάλληλο. Μην αλληλουχήσετε «ό,τι υπάρχει» για να το κάνετε αναφέρσιμο· ζητήστε το σωστό block διηθητικού όγκου.","falsches Material":"λάθος υλικό","Materialidentität":"Ταυτότητα υλικού","LAB":"LAB","Falscher Block, perfektes QC: Wann ein technisch guter Befund klinisch wertlos ist":"Λάθος block, τέλειο QC: Πότε ένα τεχνικά καλό αποτέλεσμα είναι κλινικά άχρηστο","Molekularpathologie / Pathologieassistenz / Labor":"Μοριακή παθολογία / Υποστήριξη παθολογίας / Εργαστήριο","Repräsentativität des Materials vor Molekulardiagnostik prüfen.":"Ελέγξτε την αντιπροσωπευτικότητα του υλικού πριν από τη μοριακή διάγνωση.","Technische Validität von klinischer Validität unterscheiden.":"Διαχωρίστε τεχνική και κλινική εγκυρότητα.","Bei falschem/nicht invasivem Material die Freigabe stoppen und korrektes Tumorgewebe anfordern.":"Σε λάθος/μη διηθητικό υλικό, σταματήστε την έκδοση και ζητήστε σωστό ιστό όγκου.","Eine Präanalytik-Diskrepanz nachvollziehbar dokumentieren und kommunizieren.":"Τεκμηριώστε και επικοινωνήστε με ιχνηλασιμότητα μια προαναλυτική ασυμφωνία.","Die DNA-QC ist hervorragend, der Tumorboard-Termin ist nah und der Auftrag lautet RAS/BRAF/MMR/MSI. Der einzige Haken: Auf dem Kontroll-HE liegt gar kein invasives Karzinom, sondern nur der Rest eines früheren Adenoms. Genau jetzt entscheidet sich, ob 'gute Technik' zur gefährlichen Scheinsicherheit wird.":"Το QC DNA είναι εξαιρετικό, το tumor board πλησιάζει και το αίτημα είναι RAS/BRAF/MMR/MSI. Η μόνη παγίδα: στο control H&E δεν υπάρχει καθόλου διηθητικό καρκίνωμα, μόνο υπόλειμμα προηγούμενου αδενώματος. Ακριβώς εδώ η «καλή τεχνική» μπορεί να γίνει επικίνδυνη ψευδής ασφάλεια.","64-jähriger Patient mit metastasiertem Sigma-Karzinom. Für die prädiktive Molekulardiagnostik wurde versehentlich der Block einer früheren Polypektomie ausgewählt. Er enthält adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Ein repräsentativer Resektionsblock ist im Archiv vorhanden.":"Ασθενής 64 ετών με μεταστατικό καρκίνωμα σιγμοειδούς. Για προβλεπτική μοριακή διάγνωση επιλέχθηκε κατά λάθος το block προηγούμενης πολυπεκτομής. Περιέχει αδενωματώδη ιστό με υψηλόβαθμη δυσπλασία αλλά χωρίς βέβαιο διηθητικό καρκίνωμα. Στο αρχείο υπάρχει αντιπροσωπευτικό block εκτομής.","RAS/BRAF und MMR/MSI vor Systemtherapie.":"RAS/BRAF και MMR/MSI πριν από συστηματική θεραπεία.","Die klinische Frage bezieht sich auf das invasive/metastasierte Karzinom.":"Το κλινικό ερώτημα αφορά το διηθητικό/μεταστατικό καρκίνωμα.","Polypektomie A1 mit Adenom/HGIEN, ohne sichere Invasion.":"Πολυπεκτομή A1 με αδένωμα/HGIEN, χωρίς βέβαιη διήθηση.","Die Probenidentität ist klinisch falsch, obwohl die DNA technisch gut sein kann.":"Η ταυτότητα του δείγματος είναι κλινικά λανθασμένη, παρότι το DNA μπορεί να είναι τεχνικά καλό.","Alternativmaterial":"Εναλλακτικό υλικό","Resektionsblock B7 mit ca. 60 % invasivem Tumor ist verfügbar.":"Το block εκτομής B7 με περ. 60% διηθητικό όγκο είναι διαθέσιμο.","Die richtige Lösung ist Nachforderung/Blockwechsel, nicht Interpretation des falschen Materials.":"Η σωστή λύση είναι να ζητηθεί/αλλαχθεί το block, όχι να ερμηνευθεί το λάθος υλικό.","Kein sicher invasives Karzinom im eingesandten Block.":"Χωρίς βέβαιο διηθητικό καρκίνωμα στο υποβληθέν block.","Sehr gute DNA-Qualität – technisch wären PCR/NGS problemlos möglich.":"Πολύ καλή ποιότητα DNA – τεχνικά PCR/NGS θα ήταν απλά.","LIMS-Abgleich":"Διασταύρωση LIMS","Block A1 gehört zur Polypektomie; Resektionsblock B7 trägt den invasiven Tumor.":"Το block A1 ανήκει στην πολυπεκτομή· το block εκτομής B7 περιέχει τον διηθητικό όγκο.","MTB in vier Tagen erzeugt realen Zeitdruck.":"Το MTB σε τέσσερις ημέρες δημιουργεί πραγματική πίεση χρόνου.","Das korrekte Material existiert, muss aber aktiv nachgefordert/umgebucht werden.":"Το σωστό υλικό υπάρχει αλλά πρέπει να ζητηθεί/ανατεθεί ενεργά.","Jede Molekulardiagnostik am falschen Block produziert potenziell einen technisch plausiblen, klinisch irreführenden Befund.":"Κάθε μοριακός έλεγχος στο λάθος block μπορεί να παράγει τεχνικά εύλογο αλλά κλινικά παραπλανητικό αποτέλεσμα.","Was ist der nächste entscheidende Schritt?":"Ποιο είναι το επόμενο καθοριστικό βήμα;","HE/Blockidentität prüfen, Analyse am Polypenrest stoppen und repräsentatives invasives Tumormaterial anfordern.":"Ελέγξτε H&E/ταυτότητα block, σταματήστε την ανάλυση στο υπόλειμμα πολύποδα και ζητήστε αντιπροσωπευτικό υλικό διηθητικού όγκου.","Wegen des MTB-Termins sofort NGS durchführen; gute DNA-QC reicht.":"Λόγω της προθεσμίας MTB, διενεργήστε άμεσα NGS· καλό QC DNA αρκεί.","Nur MMR-IHC durchführen und den Rest später entscheiden.":"Διενεργήστε μόνο IHC MMR και αποφασίστε τα υπόλοιπα αργότερα.","Molekularbefund aus dem Adenom als Status des metastasierten CRC berichten.":"Αναφέρετε το μοριακό αποτέλεσμα από το αδένωμα ως κατάσταση του μεταστατικού CRC.","Präanalytische Repräsentativität ist Voraussetzung jeder klinischen Interpretation.":"Η προαναλυτική αντιπροσωπευτικότητα είναι προϋπόθεση για κάθε κλινική ερμηνεία.","Ein NGS-Lauf aus dem Polypenrest ist technisch valide. Ist der Befund damit klinisch valide?":"Ένα NGS run από το υπόλειμμα πολύποδα είναι τεχνικά έγκυρο. Είναι άρα και κλινικά έγκυρο το αποτέλεσμα;","Nein. Ein technisch korrekter Befund kann klinisch unbrauchbar sein, wenn das analysierte Gewebe die Fragestellung nicht repräsentiert.":"Όχι. Ένα τεχνικά σωστό αποτέλεσμα μπορεί να είναι κλινικά άχρηστο εάν ο εξεταζόμενος ιστός δεν αντιπροσωπεύει το κλινικό ερώτημα.","Ja. Technische QC ist die einzige Voraussetzung für Freigabe.":"Ναι. Το τεχνικό QC είναι η μόνη προϋπόθεση για έκδοση.","Ja, sofern RAS/BRAF Wildtyp sind.":"Ναι, εφόσον RAS/BRAF είναι wild type.","Ja, wenn ein breites Panel benutzt wurde.":"Ναι, εάν χρησιμοποιήθηκε ευρύ panel.","Analytische Qualität ersetzt nicht Probenidentität und klinische Repräsentativität.":"Η αναλυτική ποιότητα δεν αντικαθιστά την ταυτότητα δείγματος και την κλινική αντιπροσωπευτικότητα.","Wie soll die Diskrepanz behandelt werden?":"Πώς πρέπει να αντιμετωπιστεί η ασυμφωνία;","Dokumentieren, Einsender/Pathologie kontaktieren, korrekten Block nachfordern und erst dann prädiktiv testen.":"Τεκμηριώστε, επικοινωνήστε με τον αποστολέα/παθολογία, ζητήστε το σωστό block και μόνο τότε διενεργήστε προβλεπτικό έλεγχο.","Intern korrigieren, aber nicht dokumentieren.":"Διορθώστε εσωτερικά αλλά μην το τεκμηριώσετε.","Annehmen, dass Polyp und Karzinom denselben Biomarkerstatus haben.":"Υποθέστε ότι πολύποδας και καρκίνωμα έχουν την ίδια κατάσταση βιοδεικτών.","Gesamten Fall endgültig abbrechen, obwohl geeignetes Material vorhanden ist.":"Διακόψτε οριστικά όλη την περίπτωση παρότι υπάρχει κατάλληλο υλικό.","Rückverfolgbarkeit und transparente Kommunikation gehören zur Fehlerbeherrschung.":"Η ιχνηλασιμότητα και η διαφανής επικοινωνία αποτελούν μέρος του ελέγχου σφαλμάτων.","Entscheiden Sie, ob der Polypenrest befundbar ist, und steuern Sie den Fall so, dass nur repräsentatives invasives Tumorgewebe in die prädiktive Diagnostik eingeht.":"Αποφασίστε εάν το υπόλειμμα πολύποδα μπορεί να αναφερθεί και διαχειριστείτε την περίπτωση ώστε μόνο αντιπροσωπευτικός διηθητικός ιστός όγκου να εισέλθει στην προβλεπτική διάγνωση.","Kontroll-HE des ausgewählten Blocks prüfen.":"Ελέγξτε το control H&E του επιλεγμένου block.","Diskrepanz zwischen Anforderung und Histologie erkennen.":"Αναγνωρίστε την ασυμφωνία μεταξύ αιτήματος και ιστολογίας.","Molekulare Freigabe am Polypenrest stoppen.":"Σταματήστε τη μοριακή έκδοση από το υπόλειμμα πολύποδα.","Resektionsblock B7 bzw. anderes repräsentatives invasives Material anfordern.":"Ζητήστε το block εκτομής B7 ή άλλο αντιπροσωπευτικό διηθητικό υλικό.","Diskrepanz und Kommunikation dokumentieren.":"Τεκμηριώστε την ασυμφωνία και την επικοινωνία.","Erst am korrekten Tumormaterial mit RAS/BRAF/MMR/MSI fortfahren.":"Συνεχίστε με RAS/BRAF/MMR/MSI μόνο στο σωστό υλικό όγκου.","Geeignete Metastasenbiopsie anfordern, falls der Resektionsblock nicht verfügbar/qualitativ ungeeignet wäre.":"Ζητήστε κατάλληλη βιοψία μετάστασης εάν το block εκτομής δεν είναι διαθέσιμο/ποιοτικά ακατάλληλο.","'DNA ist gut, also los'":"«Το DNA είναι καλό, άρα προχωράμε»","Technische QC sagt nichts darüber aus, ob die richtige Läsion untersucht wird.":"Το τεχνικό QC δεν λέει τίποτα για το αν εξετάζεται η σωστή βλάβη.","Adenom-Biomarker = Karzinom-Biomarker":"Βιοδείκτης αδενώματος = βιοδείκτης καρκινώματος","Klonale Evolution und fehlende Repräsentativität machen diese Gleichsetzung unzulässig.":"Η κλωνική εξέλιξη και η έλλειψη αντιπροσωπευτικότητας καθιστούν αυτή την εξίσωση μη έγκυρη.","Zeitdruck als Freigabeargument":"Η πίεση χρόνου ως επιχείρημα για έκδοση","Ein schneller falscher Befund ist schlechter als eine dokumentierte Nachforderung.":"Ένα γρήγορο λάθος αποτέλεσμα είναι χειρότερο από ένα τεκμηριωμένο αίτημα για σωστό υλικό.","Der falsche Block liefert einen überzeugenden Befund":"Το λάθος block δίνει πειστικό αποτέλεσμα","Wird voreilig sequenziert, zeigt das Adenom eine plausible APC-Alteration und keinen RAS/BRAF-Treiber. Technisch sieht alles sauber aus. Erst der HE-/LIMS-Abgleich zeigt, dass dieser Befund für das invasive metastasierte CRC gar nicht freigegeben werden darf.":"Εάν η αλληλούχηση γίνει πρόωρα, το αδένωμα δείχνει εύλογη αλλοίωση APC και κανέναν driver RAS/BRAF. Τεχνικά όλα φαίνονται καθαρά. Μόνο ο έλεγχος H&E/LIMS αποκαλύπτει ότι αυτό το αποτέλεσμα δεν πρέπει να εκδοθεί για το διηθητικό μεταστατικό CRC.","Die gefährlichsten Präanalytikfehler produzieren nicht zwingend einen technischen Fehler – sondern einen glaubwürdigen Befund am falschen Material.":"Τα πιο επικίνδυνα προαναλυτικά σφάλματα δεν προκαλούν απαραίτητα τεχνικό σφάλμα – μπορεί να παράγουν ένα πειστικό αποτέλεσμα στο λάθος υλικό.","Materialfehler vor Analytik gestoppt":"Σφάλμα υλικού σταμάτησε πριν από την ανάλυση","HE zeigt kein invasives Karzinom; korrekter Resektionsblock B7 wird angefordert.":"Το H&E δεν δείχνει διηθητικό καρκίνωμα· ζητείται το σωστό block εκτομής B7.","Patientensicher und ressourcenschonend.":"Ασφαλές για τον ασθενή και αποδοτικό ως προς τους πόρους.","Technisch erfolgreich, klinisch falsch":"Τεχνικά επιτυχές, κλινικά λάθος","NGS aus Adenom: APC-Alteration, RAS/BRAF WT. Befund darf nicht als metastasiertes CRC interpretiert werden.":"NGS από αδένωμα: αλλοίωση APC, RAS/BRAF WT. Το αποτέλεσμα δεν πρέπει να ερμηνεύεται ως μεταστατικό CRC.","Analytisch valide, klinisch invalide.":"Αναλυτικά έγκυρο, κλινικά άκυρο.","Falschen Block freigegeben":"Εκδόθηκε λάθος block","Adenom-Befund wird als Tumorprofil berichtet.":"Το αποτέλεσμα αδενώματος αναφέρεται ως προφίλ όγκου.","Kritischer Präanalytik-/Freigabefehler.":"Κρίσιμο προαναλυτικό/σφάλμα έκδοσης.","Resektionsblock B7 verfügbar":"Διαθέσιμο block εκτομής B7","Kontroll-HE, Tumormarkierung und reguläre CRC-Biomarkerdiagnostik durchführen.":"Διενεργήστε control H&E, σήμανση όγκου και τυπική διάγνωση βιοδεικτών CRC.","Der Fall kann ohne neue invasive Probengewinnung korrekt abgeschlossen werden.":"Η περίπτωση μπορεί να ολοκληρωθεί σωστά χωρίς νέα επεμβατική δειγματοληψία.","Kein geeignetes Archivmaterial":"Χωρίς κατάλληλο αρχειακό υλικό","Mit Klinik eine geeignete Metastasen- oder Primärtumorprobe abstimmen.":"Συντονίστε με την κλινική κατάλληλο δείγμα μετάστασης ή πρωτοπαθούς όγκου.","TAT steigt, klinische Validität bleibt gewahrt.":"Το TAT αυξάνεται, η κλινική εγκυρότητα διατηρείται.","Materialidentität und Repräsentativität stehen vor analytischer QC.":"Η ταυτότητα και αντιπροσωπευτικότητα υλικού προηγούνται του αναλυτικού QC.","Ein technisch valider Befund kann klinisch falsch sein.":"Ένα τεχνικά έγκυρο αποτέλεσμα μπορεί να είναι κλινικά λάθος.","Polyp/Adenom ist kein automatischer Surrogatblock für ein invasives metastasiertes CRC.":"Ο πολύποδας/αδένωμα δεν αποτελεί αυτόματο surrogate block για διηθητικό μεταστατικό CRC.","Zeitdruck rechtfertigt keine Freigabe aus falschem Material.":"Η πίεση χρόνου δεν δικαιολογεί έκδοση από λάθος υλικό.","HE-Reevaluation zeigt nur Adenom/HGIEN. Molekulare Freigabe stoppen, Blockidentität klären und Resektionsblock B7 mit invasivem Tumor anfordern. Etwaige bereits erzeugte Daten aus dem Polypenrest nicht als prädiktiven Tumorbefund freigeben.":"Η επανεκτίμηση H&E δείχνει μόνο αδένωμα/HGIEN. Σταματήστε τη μοριακή έκδοση, διευκρινίστε την ταυτότητα του block και ζητήστε το block εκτομής B7 με διηθητικό όγκο. Μην εκδώσετε τυχόν ήδη παραχθέντα δεδομένα από το υπόλειμμα πολύποδα ως προβλεπτικό αποτέλεσμα όγκου.","Präanalytik vor Analytik":"Προαναλυτική πριν από αναλυτική","Stop/No-Go korrekt":"Σωστό Stop/No-Go","korrektes Material angefordert":"ζητήθηκε σωστό υλικό","technische vs. klinische Validität verstanden":"κατανόηση τεχνικής έναντι κλινικής εγκυρότητας","Welche Kontrollen verhindern solche Blockverwechslungen?":"Ποιοι έλεγχοι αποτρέπουν τέτοιες συγχύσεις blocks;","Wann kann ein Vorläuferläsionsblock überhaupt sinnvoll molekular untersucht werden?":"Πότε μπορεί ένα block προκαρκινικής βλάβης να εξεταστεί μοριακά με νόημα;","Wie dokumentiert man einen bereits erzeugten, aber klinisch nicht freigabefähigen Datensatz?":"Πώς πρέπει να τεκμηριώνεται ένα ήδη παραχθέν dataset που δεν μπορεί να εκδοθεί κλινικά;","perfekte DNA aus falschem Gewebe":"τέλειο DNA από λάθος ιστό","technisch valide ≠ klinisch valide":"τεχνικά έγκυρο ≠ κλινικά έγκυρο","HE → Diskrepanz → Stop → korrekter Block":"H&E → ασυμφωνία → stop → σωστό block","HER2-amplifiziertes RAS-WT-CRC → HER2 als Resistenz-/Target-Kontext":"HER2-amplified RAS-WT CRC → HER2 ως πλαίσιο αντοχής/στόχευσης","HER2-amplifiziertes RAS-WT-CRC":"HER2-amplified RAS-WT CRC","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom. Initial RAS/BRAF-Wildtyp und pMMR/MSS; unter FOLFOX plus Cetuximab zunächst deutliche Remission, jetzt hepatischer Progress.":"Ασθενής 61 ετών με αριστερό μεταστατικό καρκίνωμα σιγμοειδούς. Αρχικά RAS/BRAF wild type και pMMR/MSS· έντονη ύφεση με FOLFOX + cetuximab, τώρα ηπατική εξέλιξη.","Der Progressionsbefund zeigt weiterhin keine RAS- oder BRAF-Mutation, aber einen ERBB2/HER2-Copy-number-Hinweis. Wie ist das therapeutisch zu interpretieren?":"Το δείγμα εξέλιξης εξακολουθεί να μην δείχνει μετάλλαξη RAS ή BRAF, αλλά υποδηλώνει αύξηση copy-number ERBB2/HER2. Πώς πρέπει να ερμηνευθεί θεραπευτικά;","Die nächste Therapielinie soll im MTB in fünf Tagen festgelegt werden.":"Η επόμενη θεραπευτική γραμμή πρέπει να καθοριστεί στο MTB σε πέντε ημέρες.","Sigma, linksseitig; initiale Resektion vor 18 Monaten.":"Σιγμοειδές, αριστερά· αρχική εκτομή πριν από 18 μήνες.","Initiales Molekularprofil":"Αρχικό μοριακό προφίλ","KRAS/NRAS Wildtyp, BRAF Wildtyp, pMMR/MSS.":"KRAS/NRAS wild type, BRAF wild type, pMMR/MSS.","Therapieverlauf":"Πορεία θεραπείας","FOLFOX plus Cetuximab mit gutem initialem Ansprechen; nach 11 Monaten Progress einzelner Leberläsionen.":"FOLFOX + cetuximab με καλή αρχική ανταπόκριση· εξέλιξη μεμονωμένων ηπατικών βλαβών μετά από 11 μήνες.","Didaktischer Schlüssel":"Διδακτικό κλειδί","Der Satz 'RAS und BRAF negativ' ist beim mCRC therapeutisch nicht einfach 'kein Befund': Das Fehlen etablierter MAPK-Downstream-Resistenztreiber ist eine Voraussetzung, die anti-EGFR-Antikörperstrategie bei passendem klinischem Kontext überhaupt eröffnet.":"Στο mCRC, η φράση «RAS και BRAF αρνητικά» δεν σημαίνει θεραπευτικά απλώς «κανένα εύρημα»: η απουσία καθιερωμένων downstream MAPK drivers αντοχής αποτελεί προϋπόθεση που επιτρέπει στρατηγική με anti-EGFR αντισώματα στο κατάλληλο κλινικό πλαίσιο.","Warum kann der Tumor trotz weiterem RAS/BRAF-Wildtyp progredient sein, und welche Rolle spielt HER2?":"Γιατί μπορεί ο όγκος να εξελιχθεί παρά το διατηρούμενο RAS/BRAF wild type και ποιος είναι ο ρόλος του HER2;","Progressionsbiopsie":"Βιοψία εξέλιξης","Lebermetastase eines kolorektalen Adenokarzinoms, vital und gut repräsentativ.":"Ηπατική μετάσταση ορθοκολικού αδενοκαρκινώματος, βιώσιμη και καλά αντιπροσωπευτική.","ca. 65 %.":"περ. 65%.","Aus der Primärdiagnostik pMMR/MSS, klinisch ausreichend dokumentiert.":"pMMR/MSS από την αρχική διάγνωση, επαρκώς τεκμηριωμένο κλινικά.","Progressionsprofil":"Προφίλ εξέλιξης","Kein RAS-/BRAF-Resistenzbefund; ERBB2 mit deutlicher Copy-number-Erhöhung im DNA-Panel.":"Χωρίς εύρημα αντοχής RAS/BRAF· ERBB2 με έντονη αύξηση copy-number στο DNA panel.","Ist die ERBB2-Veränderung bestätigt, und wie verändert sie die scheinbar 'negative' RAS/BRAF-Situation?":"Επιβεβαιώνεται η αλλοίωση ERBB2 και πώς αλλάζει τη φαινομενικά «αρνητική» κατάσταση RAS/BRAF;","FFPE-Lebermetastasenbiopsie, Block L3.":"FFPE βιοψία ηπατικής μετάστασης, block L3.","ca. 65 %, DNA-QC sehr gut.":"περ. 65%, πολύ καλό QC DNA.","HER2-Bestätigung":"Επιβεβαίωση HER2","IHC/ISH ist am vorhandenen Material möglich.":"IHC/ISH είναι εφικτή στο διαθέσιμο υλικό.","Breite Wiederholung bereits gesicherter MMR/MSI-Diagnostik verbraucht Material, während die konkrete Progressionsfrage HER2-Bestätigung und Resistenzkontext betrifft.":"Η ευρεία επανάληψη ήδη τεκμηριωμένου ελέγχου MMR/MSI καταναλώνει υλικό, ενώ το συγκεκριμένο ερώτημα εξέλιξης αφορά επιβεβαίωση HER2 και πλαίσιο αντοχής.","Progressionsprofil / RAS-BRAF-ERBB2-Kontext":"Προφίλ εξέλιξης / πλαίσιο RAS-BRAF-ERBB2","HER2-Amplifikation bestätigen":"Επιβεβαιώστε ενίσχυση HER2","KRAS/NRAS weiterhin Wildtyp, BRAF Wildtyp; keine neue klassische RAS/RAF-Resistenzmutation. ERBB2 zeigt eine hochgradige Copy-number-Erhöhung.":"KRAS/NRAS παραμένουν wild type, BRAF wild type· χωρίς νέα κλασική μετάλλαξη αντοχής RAS/RAF. Το ERBB2 δείχνει υψηλού επιπέδου αύξηση copy-number.","KRAS/NRAS Wildtyp. Das Fehlen einer RAS-Mutation ist im geeigneten linksseitigen mCRC-Kontext therapeutisch relevant, garantiert aber keine dauerhafte Sensitivität gegenüber anti-EGFR-Antikörpern.":"KRAS/NRAS wild type. Η απουσία μετάλλαξης RAS είναι θεραπευτικά σχετική στο κατάλληλο πλαίσιο αριστερού mCRC, αλλά δεν εγγυάται μακροχρόνια ευαισθησία σε anti-EGFR αντισώματα.","BRAF V600E nicht nachweisbar. RAS/BRAF-Wildtyp bedeutet nicht 'molekular ohne Bedeutung', sondern schließt wichtige etablierte MAPK-Resistenztreiber aus.":"Δεν ανιχνεύεται BRAF V600E. RAS/BRAF wild type δεν σημαίνει «μοριακά χωρίς σημασία»· αποκλείει σημαντικούς καθιερωμένους MAPK drivers αντοχής.","HER2 IHC/ISH":"IHC/ISH HER2","HER2 stark überexprimiert / ERBB2 amplifiziert. Der Befund ist im RAS/BRAF-WT-mCRC ein relevanter Target- und möglicher anti-EGFR-Resistenzkontext, insbesondere in der Progressionssituation.":"HER2 έντονα υπερεκφρασμένο / ERBB2 ενισχυμένο. Στο RAS/BRAF-WT mCRC, το εύρημα αποτελεί σχετικό target και πιθανό πλαίσιο αντοχής anti-EGFR, ιδιαίτερα κατά την εξέλιξη.","HER2-IHC allein":"Μόνο IHC HER2","HER2 IHC 3+. Im CRC-Kontext sollte die zugrunde liegende ERBB2-Amplifikation bzw. ein validierter HER2-positiver Status nach lokalem Algorithmus gesichert werden.":"HER2 IHC 3+. Στο πλαίσιο CRC, η υποκείμενη ενίσχυση ERBB2 ή έγκυρη HER2-θετική κατάσταση πρέπει να επιβεβαιώνεται σύμφωνα με τον τοπικό αλγόριθμο.","Erneute MMR/MSI-Testung":"Επανάληψη ελέγχου MMR/MSI","pMMR/MSS wird bestätigt. In diesem Fall war der Status bereits belastbar bekannt; die Wiederholung beantwortet die konkrete Progressions-/HER2-Frage kaum und ist daher eher ressourcenarm zu priorisieren.":"Το pMMR/MSS επιβεβαιώνεται. Σε αυτή την περίπτωση η κατάσταση ήταν ήδη αξιόπιστα γνωστή· η επανάληψη απαντά ελάχιστα στο συγκεκριμένο ερώτημα εξέλιξης/HER2 και επομένως έχει χαμηλή προτεραιότητα ως προς τους πόρους.","Progressionsbiopsie repräsentativ; hohe Tumorzellularität und gute DNA-Qualität. Baseline-HER2-Status war nicht bestimmt.":"Αντιπροσωπευτική βιοψία εξέλιξης· υψηλή κυτταροβρίθεια όγκου και καλή ποιότητα DNA. Η baseline κατάσταση HER2 δεν είχε προσδιοριστεί.","RAS/BRAF-Wildtyp ist beim linksseitigen mCRC kein bedeutungsloser Negativbefund: Das Fehlen zentraler downstream MAPK-Resistenztreiber schafft erst die molekulare Voraussetzung für eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext. Wildtyp garantiert jedoch keine Sensitivität. Im Progress wird eine bestätigte ERBB2/HER2-Amplifikation gefunden, die einen alternativen Signalweg, einen möglichen anti-EGFR-Resistenzkontext und zugleich eine HER2-gerichtete Therapieoption im passenden Linien-/Zulassungskontext eröffnet. Ohne Baseline-HER2 kann nicht sicher behauptet werden, dass die Amplifikation neu erworben wurde.":"Το RAS/BRAF wild type δεν είναι ανούσιο αρνητικό εύρημα στο αριστερό mCRC: η απουσία βασικών downstream MAPK drivers αντοχής δημιουργεί τη μοριακή προϋπόθεση για στρατηγική με anti-EGFR αντισώματα στο κατάλληλο κλινικό πλαίσιο. Ωστόσο, το wild type δεν εγγυάται ευαισθησία. Κατά την εξέλιξη ανιχνεύεται επιβεβαιωμένη ενίσχυση ERBB2/HER2, που ανοίγει εναλλακτική οδό σηματοδότησης, πιθανό πλαίσιο αντοχής anti-EGFR και ταυτόχρονα επιλογή HER2-στοχευμένης θεραπείας στο κατάλληλο πλαίσιο γραμμής/έγκρισης. Χωρίς baseline HER2 δεν μπορεί να υποστηριχθεί με βεβαιότητα ότι η ενίσχυση αποκτήθηκε πρόσφατα.","Teilbefund: RAS/BRAF-Wildtyp ist korrekt erkannt, aber entweder wird 'negativ' fälschlich als therapeutisch bedeutungslos bezeichnet oder die ERBB2-Copy-number-Veränderung bleibt unbestätigt. Beides verhindert eine belastbare Progressionsinterpretation.":"Μερικό εύρημα: Το RAS/BRAF wild type αναγνωρίζεται σωστά, αλλά είτε το «αρνητικό» περιγράφεται λανθασμένα ως θεραπευτικά χωρίς σημασία είτε η αλλοίωση copy-number ERBB2 παραμένει ανεπιβεβαίωτη. Και τα δύο εμποδίζουν αξιόπιστη ερμηνεία της εξέλιξης.","Explizit erklären: RAS/BRAF-Wildtyp ist ein therapeutisch relevanter 'negativer' Befund, der anti-EGFR bei passendem linksseitigem mCRC-Kontext ermöglicht":"Εξηγήστε ρητά: Το RAS/BRAF wild type είναι θεραπευτικά σχετικό «αρνητικό» εύρημα επιλογής που επιτρέπει anti-EGFR στο κατάλληλο πλαίσιο αριστερού mCRC","Wildtyp nicht als Garantie für anti-EGFR-Sensitivität darstellen":"Μην παρουσιάζετε το wild type ως εγγύηση ευαισθησίας σε anti-EGFR","HER2-Amplifikation als alternativen Target-/Resistenzkontext integrieren":"Ενσωματώστε την ενίσχυση HER2 ως εναλλακτικό πλαίσιο στόχευσης/αντοχής","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher neu erworben":"Χωρίς baseline HER2, μην υποστηρίζετε ότι η ενίσχυση είναι σίγουρα νεοαποκτηθείσα","Aktuelle Linien-/Leitlinien-/Zulassungssituation für HER2-gerichtete Therapie transparent berücksichtigen":"Λάβετε διαφανώς υπόψη το τρέχον πλαίσιο γραμμής/οδηγίας/έγκρισης για HER2-στοχευμένη θεραπεία","Optimale Lösung: den RAS/BRAF-Wildtyp bewusst als therapeutisch positiven Selektionsbefund erklären; Progress trotz Wildtyp als Hinweis auf alternative Resistenzwege verstehen und die ERBB2/HER2-Amplifikation bestätigen und als Target-/Resistenzkontext integrieren.":"Βέλτιστη λύση: Εξηγήστε συνειδητά το RAS/BRAF wild type ως θεραπευτικά θετικό εύρημα επιλογής· αντιληφθείτε την εξέλιξη παρά το wild type ως ένδειξη εναλλακτικών οδών αντοχής και επιβεβαιώστε την ενίσχυση ERBB2/HER2, ενσωματώνοντάς την ως πλαίσιο στόχευσης/αντοχής.","RAS Wildtyp":"RAS wild type","BRAF Wildtyp":"BRAF wild type","ERBB2 Amplifikation":"Ενίσχυση ERBB2","Resistenz":"Αντοχή","Wenn 'negativ' therapeutisch positiv ist: RAS/BRAF-Wildtyp, anti-EGFR und der HER2-Twist":"Όταν το «αρνητικό» είναι θεραπευτικά θετικό: RAS/BRAF wild type, anti-EGFR και η ανατροπή HER2","RAS/BRAF-Wildtyp als therapeutisch relevanten negativen Selektionsbefund im mCRC erklären.":"Εξηγήστε το RAS/BRAF wild type ως θεραπευτικά σχετικό αρνητικό εύρημα επιλογής στο mCRC.","Anti-EGFR-Eignung als Kontextentscheidung und nicht als garantierte Sensitivität verstehen.":"Κατανοήστε την καταλληλότητα για anti-EGFR ως απόφαση πλαισίου και όχι ως εγγυημένη ευαισθησία.","HER2/ERBB2-Amplifikation als alternativen Target- und möglichen Resistenzkontext integrieren.":"Ενσωματώστε την ενίσχυση HER2/ERBB2 ως εναλλακτικό target και πιθανό πλαίσιο αντοχής.","Zwischen 'nach Progress nachgewiesen' und 'erworben' unterscheiden, wenn kein Baseline-HER2 vorliegt.":"Διαχωρίστε το «ανιχνεύθηκε μετά την εξέλιξη» από το «αποκτήθηκε» όταν δεν υπάρχει baseline HER2.","Im Progressions-MTB steht auf der Folie: 'KRAS, NRAS, BRAF: keine Mutation nachweisbar'. Ein Kollege fasst zusammen: 'Molekular also wieder negativ.' Genau hier liegt der Kern des Falls: Beim mCRC kann ein negativer RAS/BRAF-Befund therapeutisch eine positive Information sein – und trotzdem erklärt er den jetzigen Progress nicht. Im selben Panel taucht nämlich eine deutliche ERBB2-Copy-number-Erhöhung auf.":"Στη διαφάνεια του MTB εξέλιξης αναγράφεται: «KRAS, NRAS, BRAF: δεν ανιχνεύεται μετάλλαξη». Ένας συνάδελφος συνοψίζει: «Άρα μοριακά πάλι αρνητικό.» Εδώ ακριβώς βρίσκεται ο πυρήνας του περιστατικού: στο mCRC, ένα αρνητικό αποτέλεσμα RAS/BRAF μπορεί να είναι θεραπευτικά θετική πληροφορία – και παρ’ όλα αυτά να μην εξηγεί την τρέχουσα εξέλιξη. Στο ίδιο panel όμως εμφανίζεται έντονη αύξηση copy-number ERBB2.","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom, initial RAS/BRAF-Wildtyp und pMMR/MSS. Unter FOLFOX plus Cetuximab gutes Ansprechen, nach elf Monaten Progress in der Leber. Die Progressionsbiopsie bleibt RAS/BRAF-Wildtyp, zeigt aber eine hochgradige ERBB2-Copy-number-Erhöhung. Der Fall soll den scheinbaren Widerspruch 'negativ = therapeutisch positiv' erklären und anschließend HER2 als alternativen Resistenz-/Targetkontext einordnen.":"Ασθενής 61 ετών με αριστερό μεταστατικό καρκίνωμα σιγμοειδούς, αρχικά RAS/BRAF wild type και pMMR/MSS. Καλή ανταπόκριση σε FOLFOX + cetuximab, ηπατική εξέλιξη μετά 11 μήνες. Η βιοψία εξέλιξης παραμένει RAS/BRAF wild type αλλά δείχνει υψηλού επιπέδου αύξηση copy-number ERBB2. Η περίπτωση εξηγεί τη φαινομενική αντίφαση «αρνητικό = θεραπευτικά θετικό» και στη συνέχεια ταξινομεί HER2 ως εναλλακτικό πλαίσιο αντοχής/στόχευσης.","Baseline":"Baseline","Linksseitiges mCRC, RAS/BRAF-Wildtyp, pMMR/MSS.":"Αριστερό mCRC, RAS/BRAF wild type, pMMR/MSS.","Dieser Molekularkontext ermöglichte grundsätzlich eine anti-EGFR-Antikörperstrategie.":"Αυτό το μοριακό πλαίσιο επέτρεψε κατ’ αρχήν στρατηγική με anti-EGFR αντισώματα.","Gutes initiales Ansprechen unter FOLFOX + Cetuximab, Progress nach 11 Monaten.":"Καλή αρχική ανταπόκριση σε FOLFOX + cetuximab, εξέλιξη μετά 11 μήνες.","Wildtyp ist Selektion, keine Garantie dauerhafter Sensitivität.":"Το wild type είναι κριτήριο επιλογής, όχι εγγύηση μακροχρόνιας ευαισθησίας.","Weiterhin RAS/BRAF-Wildtyp, aber ERBB2-Copy-number hoch.":"Παραμένει RAS/BRAF wild type, αλλά υψηλό copy-number ERBB2.","Resistenz kann über alternative Signalwege entstehen/bestehen.":"Η αντοχή μπορεί να προκύψει/παραμένει μέσω εναλλακτικών οδών σηματοδότησης.","Limitation":"Περιορισμός","HER2 wurde an der Baseline nicht bestimmt.":"Το HER2 δεν είχε προσδιοριστεί στο baseline.","Die aktuelle Amplifikation darf nicht sicher als neu erworben bezeichnet werden.":"Η τρέχουσα ενίσχυση δεν μπορεί να χαρακτηριστεί με βεβαιότητα ως νεοαποκτηθείσα.","Initialdiagnostik":"Αρχική διάγνωση","KRAS/NRAS WT, BRAF WT, pMMR/MSS.":"KRAS/NRAS WT, BRAF WT, pMMR/MSS.","Aktueller Progress":"Τρέχουσα εξέλιξη","Lebermetastasenbiopsie mit 65 % Tumor und guter DNA-QC.":"Βιοψία ηπατικής μετάστασης με 65% όγκο και καλό QC DNA.","Panel-Hinweis":"Ένδειξη panel","ERBB2 hochgradige Copy-number-Erhöhung; RAS/BRAF weiter WT.":"Υψηλού επιπέδου αύξηση copy-number ERBB2· RAS/BRAF παραμένουν WT.","Neun Schnitte reichen für HER2-Bestätigung und fokussierte Progressionsdiagnostik.":"Εννέα τομές αρκούν για επιβεβαίωση HER2 και εστιασμένη διάγνωση εξέλιξης.","MMR/MSI ist bereits belastbar dokumentiert und muss nicht reflexartig wiederholt werden.":"Το MMR/MSI είναι ήδη αξιόπιστα τεκμηριωμένο και δεν χρειάζεται αντανακλαστική επανάληψη.","HER2-Status sollte orthogonal/validiert bestätigt werden, bevor die therapeutische Schlussfolgerung formuliert wird.":"Η κατάσταση HER2 πρέπει να επιβεβαιωθεί ορθογώνια/με επικυρωμένη μέθοδο πριν από τη διατύπωση θεραπευτικού συμπεράσματος.","Wie ist 'KRAS/NRAS/BRAF: keine pathogene Mutation nachweisbar' beim linksseitigen mCRC therapeutisch zu lesen?":"Πώς πρέπει να διαβαστεί θεραπευτικά το «KRAS/NRAS/BRAF: δεν ανιχνεύεται παθογόνος μετάλλαξη» στο αριστερό mCRC;","Als therapeutisch relevanter Wildtyp-/Ausschlussbefund: zentrale downstream MAPK-Resistenztreiber fehlen, sodass eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext grundsätzlich möglich wird.":"Ως θεραπευτικά σχετικό wild-type/εύρημα αποκλεισμού: απουσιάζουν βασικοί downstream MAPK drivers αντοχής, οπότε καθίσταται δυνατή στρατηγική με anti-EGFR αντισώματα στο κατάλληλο κλινικό πλαίσιο.","Als völlig bedeutungsloser Negativbefund ohne therapeutische Aussage.":"Ως εντελώς ανούσιο αρνητικό εύρημα χωρίς θεραπευτική σημασία.","Als Garantie, dass anti-EGFR sicher und dauerhaft wirkt.":"Ως εγγύηση ότι το anti-EGFR θα δράσει με βεβαιότητα και μακροχρόνια.","Als Beweis, dass auch HER2 keine Rolle spielen kann.":"Ως απόδειξη ότι ούτε το HER2 μπορεί να έχει ρόλο.","Das Fehlen von RAS/BRAF-Treibern ist eine positive Selektionsinformation, aber keine Erfolgsgarantie.":"Η απουσία drivers RAS/BRAF αποτελεί θετική πληροφορία επιλογής, αλλά όχι εγγύηση επιτυχίας.","Der Patient progrediert trotz weiterem RAS/BRAF-Wildtyp. Was ist die beste Interpretation?":"Ο ασθενής εξελίσσεται παρά το διατηρούμενο RAS/BRAF wild type. Ποια είναι η καλύτερη ερμηνεία;","Wildtyp schließt nur bestimmte Resistenzwege aus; alternative Mechanismen wie HER2/ERBB2 können relevant sein.":"Το wild type αποκλείει μόνο ορισμένες οδούς αντοχής· εναλλακτικοί μηχανισμοί όπως HER2/ERBB2 μπορεί να είναι σχετικοί.","Progress beweist, dass der RAS/BRAF-Test falsch sein muss.":"Η εξέλιξη αποδεικνύει ότι ο έλεγχος RAS/BRAF πρέπει να είναι λάθος.","Damit war die ursprüngliche anti-EGFR-Strategie grundsätzlich falsch.":"Αυτό σημαίνει ότι η αρχική στρατηγική anti-EGFR ήταν εξαρχής λανθασμένη.","Molekulare Diagnostik kann den Progress nicht mehr erklären.":"Η μοριακή διάγνωση δεν μπορεί πλέον να εξηγήσει την εξέλιξη.","Resistenzbiologie ist breiter als RAS/BRAF allein.":"Η βιολογία της αντοχής είναι ευρύτερη από RAS/BRAF μόνο.","Wie sollte die ERBB2-Copy-number-Erhöhung weiterbehandelt werden?":"Πώς πρέπει να διερευνηθεί περαιτέρω η αύξηση copy-number ERBB2;","HER2-positiven Status mit validiertem IHC/ISH-Algorithmus bestätigen und als Target-/möglichen anti-EGFR-Resistenzkontext integrieren.":"Επιβεβαιώστε HER2-θετική κατάσταση με επικυρωμένο αλγόριθμο IHC/ISH και ενσωματώστε την ως target/πιθανό πλαίσιο αντοχής anti-EGFR.","Ignorieren, da RAS/BRAF Wildtyp sind.":"Αγνοήστε το επειδή RAS/BRAF είναι wild type.","Ohne weitere Prüfung als sicher erworbene Resistenzmutation bezeichnen.":"Χωρίς περαιτέρω έλεγχο, χαρακτηρίστε την ως σίγουρα αποκτηθείσα μετάλλαξη αντοχής.","Unverändert nach Mammakarzinom-Regeln interpretieren.":"Ερμηνεύστε αμετάβλητα σύμφωνα με κανόνες καρκίνου μαστού.","HER2 ist entitätsspezifisch zu bestätigen und zu interpretieren; Baseline fehlt für eine sichere Akquisitionsaussage.":"Το HER2 πρέπει να επιβεβαιωθεί και να ερμηνευθεί ειδικά για την οντότητα· η απουσία baseline εμποδίζει βέβαιη δήλωση απόκτησης.","Darf die HER2-Amplifikation als 'erworben unter Cetuximab' bezeichnet werden?":"Μπορεί η ενίσχυση HER2 να χαρακτηριστεί «αποκτηθείσα υπό cetuximab»;","Nicht sicher. Ohne Baseline-HER2 kann sie präexistent gewesen oder unter Therapie selektiert/angereichert worden sein.":"Όχι με βεβαιότητα. Χωρίς baseline HER2, μπορεί να προϋπήρχε ή να επιλέχθηκε/εμπλουτίστηκε υπό θεραπεία.","Ja, weil sie erst beim Progress gemessen wurde.":"Ναι, επειδή μετρήθηκε μόνο κατά την εξέλιξη.","Ja, weil RAS/BRAF Wildtyp sind.":"Ναι, επειδή RAS/BRAF είναι wild type.","Die zeitliche Einordnung ist für die Befundsprache irrelevant.":"Η χρονική ταξινόμηση είναι άσχετη με τη διατύπωση της έκθεσης.","Nachweiszeitpunkt und biologischer Entstehungszeitpunkt sind nicht identisch.":"Ο χρόνος ανίχνευσης και ο βιολογικός χρόνος εμφάνισης δεν είναι ταυτόσημοι.","Erklären Sie zuerst, warum RAS/BRAF-Wildtyp im mCRC eine therapeutisch relevante 'negative' Information ist. Integrieren Sie danach die bestätigte HER2-Amplifikation in die Progressions- und Targetinterpretation, ohne Überinterpretation der Akquisition.":"Εξηγήστε πρώτα γιατί το RAS/BRAF wild type στο mCRC αποτελεί θεραπευτικά σχετική «αρνητική» πληροφορία. Στη συνέχεια ενσωματώστε την επιβεβαιωμένη ενίσχυση HER2 στην ερμηνεία εξέλιξης και στόχευσης χωρίς υπερερμηνεία της απόκτησης.","Linksseitigkeit und initialen RAS/BRAF-Wildtyp zusammen mit pMMR/MSS erfassen.":"Καταγράψτε αριστερή πλευρικότητα και αρχικό RAS/BRAF wild type μαζί με pMMR/MSS.","RAS/BRAF-Wildtyp als Selektionsvoraussetzung für anti-EGFR-Antikörper erklären, nicht als 'kein Befund'.":"Εξηγήστε το RAS/BRAF wild type ως προϋπόθεση επιλογής για anti-EGFR αντισώματα και όχι ως «κανένα εύρημα».","Progress trotz Wildtyp als Hinweis auf alternative Resistenzmechanismen verstehen.":"Κατανοήστε την εξέλιξη παρά το wild type ως ένδειξη εναλλακτικών μηχανισμών αντοχής.","ERBB2-Copy-number-Befund durch HER2-IHC/ISH bestätigen.":"Επιβεβαιώστε το εύρημα copy-number ERBB2 με IHC/ISH HER2.","HER2 als Target- und möglichen anti-EGFR-Resistenzkontext berichten.":"Αναφέρετε HER2 ως target και πιθανό πλαίσιο αντοχής anti-EGFR.","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher erworben.":"Χωρίς baseline HER2, μην υποστηρίζετε ότι η ενίσχυση είναι σίγουρα αποκτηθείσα.","Validiertes breit angelegtes Progressionspanel mit zuverlässiger ERBB2-CNV-Erfassung plus orthogonale HER2-Bestätigung.":"Επικυρωμένο ευρύ progression panel με αξιόπιστη ανίχνευση ERBB2 CNV συν ορθογώνια επιβεβαίωση HER2.","Bei nicht ausreichendem Gewebe ctDNA als ergänzender Resistenzansatz, sofern methodisch geeignet; negativer ctDNA-Befund würde Gewebe jedoch nicht automatisch ersetzen.":"Εάν ο ιστός είναι ανεπαρκής, ctDNA ως συμπληρωματική προσέγγιση αντοχής όταν είναι μεθοδολογικά κατάλληλο· ένα αρνητικό ctDNA αποτέλεσμα δεν θα αντικαθιστούσε αυτόματα τον ιστό.","'Alles negativ'":"«Όλα αρνητικά»","RAS/BRAF-Wildtyp ist therapeutisch relevante Selektionsinformation.":"Το RAS/BRAF wild type αποτελεί θεραπευτικά σχετική πληροφορία επιλογής.","Wildtyp = garantiert sensitiv":"Wild type = εγγυημένη ευαισθησία","Andere primäre oder sekundäre Resistenzmechanismen bleiben möglich.":"Άλλοι πρωτογενείς ή δευτερογενείς μηχανισμοί αντοχής παραμένουν πιθανοί.","HER2 = sicher erworben":"HER2 = σίγουρα αποκτηθέν","Ohne Baseline-HER2 kann die zeitliche Entstehung nicht bewiesen werden.":"Χωρίς baseline HER2, ο χρόνος εμφάνισης δεν μπορεί να αποδειχθεί.","Nur MMR/MSI wiederholen":"Επαναλάβετε μόνο MMR/MSI","Der Status ist bereits bekannt und beantwortet die konkrete Progressionsfrage kaum.":"Η κατάσταση είναι ήδη γνωστή και απαντά ελάχιστα στο συγκεκριμένο ερώτημα εξέλιξης.","Kein RAS/RAF-Resistenztreiber – dafür HER2 amplifiziert":"Χωρίς driver αντοχής RAS/RAF – αλλά HER2 ενισχυμένο","Das Progressionspanel bleibt KRAS/NRAS/BRAF-Wildtyp. Genau dieser 'negative' Befund war initial therapeutisch hilfreich, erklärt aber den aktuellen Progress nicht. Die HER2-Bestätigung zeigt IHC 3+ und ERBB2-Amplifikation. Damit erscheint ein alternativer Signal-/Resistenzweg und zugleich ein neuer Targetkontext. Weil Baseline-HER2 fehlt, bleibt offen, ob die Amplifikation schon vorher vorhanden oder unter Therapie selektiert war.":"Το progression panel παραμένει KRAS/NRAS/BRAF wild type. Ακριβώς αυτό το «αρνητικό» αποτέλεσμα ήταν αρχικά θεραπευτικά χρήσιμο, αλλά δεν εξηγεί την τρέχουσα εξέλιξη. Η επιβεβαίωση HER2 δείχνει IHC 3+ και ενίσχυση ERBB2. Έτσι εμφανίζεται εναλλακτική οδός σηματοδότησης/αντοχής και ταυτόχρονα νέο πλαίσιο στόχευσης. Επειδή δεν υπάρχει baseline HER2, παραμένει ανοιχτό εάν η ενίσχυση προϋπήρχε ή επιλέχθηκε υπό θεραπεία.","Der Fall trennt drei Ebenen, die häufig vermischt werden: Selektionsmarker, Resistenzmechanismus und Target. 'Negativ' und 'positiv' sind therapeutisch kontextabhängige Begriffe.":"Η περίπτωση διαχωρίζει τρία επίπεδα που συχνά συγχέονται: δείκτης επιλογής, μηχανισμός αντοχής και target. Το «αρνητικό» και «θετικό» είναι θεραπευτικοί όροι που εξαρτώνται από το πλαίσιο.","Wildtyp richtig gelesen + HER2 integriert":"Wild type σωστά ερμηνευμένο + HER2 ενσωματωμένο","KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplifiziert. Anti-EGFR war im initialen linksseitigen WT-Kontext plausibel; HER2 ist nun ein relevanter Target-/Resistenzkontext. Akquisition nicht beweisbar.":"KRAS/NRAS/BRAF WT· HER2 IHC 3+ / ERBB2 ενισχυμένο. Το anti-EGFR ήταν εύλογο στο αρχικό αριστερό WT πλαίσιο· το HER2 είναι τώρα σχετικό πλαίσιο στόχευσης/αντοχής. Η απόκτηση δεν μπορεί να αποδειχθεί.","Alle Ebenen sauber getrennt und integriert.":"Όλα τα επίπεδα διαχωρίζονται και ενσωματώνονται καθαρά.","Wildtyp als 'negativ' abgehakt":"Wild type απορρίφθηκε ως «αρνητικό»","RAS/BRAF WT wird nur als fehlender Befund erwähnt; HER2 wird zwar gefunden, aber die Selektionslogik bleibt unverstanden.":"Το RAS/BRAF WT αναφέρεται μόνο ως απουσία ευρήματος· το HER2 ανιχνεύεται, αλλά η λογική επιλογής παραμένει παρερμηνευμένη.","Zentrales Lernziel verfehlt.":"Χάθηκε ο βασικός μαθησιακός στόχος.","HER2 als sicher erworbene Resistenz bezeichnet":"HER2 χαρακτηρίζεται ως σίγουρα αποκτηθείσα αντοχή","Kausalität/Akquisition wird ohne Baseline behauptet.":"Αιτιότητα/απόκτηση δηλώνεται χωρίς baseline.","Überinterpretation der zeitlichen Evidenz.":"Υπερερμηνεία της χρονικής τεκμηρίωσης.","HER2 bestätigt":"HER2 επιβεβαιωμένο","HER2-gerichtete Therapieoptionen nach aktueller Zulassung/Leitlinie und Vorbehandlung im MTB prüfen.":"Εξετάστε στο MTB τις επιλογές HER2-στοχευμένης θεραπείας σύμφωνα με την τρέχουσα έγκριση/οδηγία και την προηγούμενη θεραπεία.","Der Progressionsbefund eröffnet eine neue therapeutische Achse.":"Το εύρημα εξέλιξης ανοίγει νέο θεραπευτικό άξονα.","HER2 nicht bestätigt":"HER2 μη επιβεβαιωμένο","Alternative Resistenzmechanismen im Progressionsprofil/ctDNA/Gewebe prüfen.":"Ελέγξτε εναλλακτικούς μηχανισμούς αντοχής στο προφίλ εξέλιξης/ctDNA/ιστό.","RAS/BRAF-Wildtyp allein erklärt den Progress weiterhin nicht.":"Το RAS/BRAF wild type μόνο του εξακολουθεί να μην εξηγεί την εξέλιξη.","Beim mCRC kann ein negativer Mutationsbefund therapeutisch positiv sein.":"Στο mCRC, ένα αρνητικό αποτέλεσμα μετάλλαξης μπορεί να είναι θεραπευτικά θετικό.","RAS/BRAF-Wildtyp ist Voraussetzung/Selektionsinformation für anti-EGFR, aber keine Garantie für Wirkung.":"Το RAS/BRAF wild type αποτελεί προϋπόθεση/πληροφορία επιλογής για anti-EGFR, αλλά όχι εγγύηση αποτελεσματικότητας.","HER2-Amplifikation kann einen alternativen Target-/Resistenzkontext darstellen.":"Η ενίσχυση HER2 μπορεί να αποτελέσει εναλλακτικό πλαίσιο στόχευσης/αντοχής.","Ohne Baseline darf 'erworben' nicht behauptet werden.":"Χωρίς baseline, δεν πρέπει να δηλώνεται «αποκτηθέν».","Linksseitiges mCRC mit initial RAS/BRAF-WT/pMMR/MSS: der Wildtypstatus ist eine positive Selektionsinformation für anti-EGFR-Antikörper. Beim Progress bleibt RAS/BRAF WT, aber ERBB2 ist amplifiziert und HER2 bestätigt. HER2 als alternativen Target-/Resistenzkontext berichten; mangels Baseline nicht als sicher erworben bezeichnen.":"Αριστερό mCRC με αρχικό RAS/BRAF-WT/pMMR/MSS: η κατάσταση wild type αποτελεί θετική πληροφορία επιλογής για anti-EGFR αντισώματα. Κατά την εξέλιξη, RAS/BRAF παραμένει WT, αλλά ERBB2 είναι ενισχυμένο και HER2 επιβεβαιωμένο. Αναφέρετε HER2 ως εναλλακτικό πλαίσιο στόχευσης/αντοχής· χωρίς baseline, μην το χαρακτηρίζετε σίγουρα αποκτηθέν.","negativ=positiv-Konzept explizit verstanden":"ρητή κατανόηση της έννοιας «αρνητικό = θετικό»","WT nicht als Erfolgsgarantie":"WT δεν αντιμετωπίζεται ως εγγύηση επιτυχίας","HER2 bestätigt und integriert":"HER2 επιβεβαιωμένο και ενσωματωμένο","Akquisitionssprache begrenzt":"Η διατύπωση περί απόκτησης περιορίζεται κατάλληλα","Warum sind Wildtypbefunde in der Onkologie oft therapeutisch hochinformativ?":"Γιατί τα wild-type ευρήματα είναι συχνά ιδιαίτερα θεραπευτικά πληροφοριακά στην ογκολογία;","Welche weiteren anti-EGFR-Resistenzmechanismen gibt es neben RAS/BRAF?":"Ποιοι άλλοι μηχανισμοί αντοχής anti-EGFR υπάρχουν πέρα από RAS/BRAF;","Wie verändert ctDNA die Rechallenge-/Resistenzdiagnostik?":"Πώς αλλάζει το ctDNA τη διάγνωση rechallenge/αντοχής;","RAS/BRAF WT bleibt, HER2 wird positiv":"RAS/BRAF παραμένει WT, HER2 γίνεται θετικό","negativ kann therapeutisch positiv sein":"το αρνητικό μπορεί να είναι θεραπευτικά θετικό","WT-Selektion → anti-EGFR → Progress → HER2-Amplifikation":"Επιλογή WT → anti-EGFR → εξέλιξη → ενίσχυση HER2","Mammakarzinom: BRCA/PIK3CA/ERBB2-Kontext → Klassische Marker vs. Panel-Zusatznutzen":"Καρκίνος μαστού: πλαίσιο BRCA/PIK3CA/ERBB2 → κλασικοί δείκτες έναντι πρόσθετης αξίας panel","Mammakarzinom: BRCA/PIK3CA/ERBB2-K…":"Καρκίνος μαστού: πλαίσιο BRCA/PIK3CA/ERBB2…","Gynäko-Onkologie / Molekulares Tumorboard":"Γυναικολογική ογκολογία / Μοριακό ογκολογικό συμβούλιο","56-jährige Patientin mit sechs Jahre zuvor behandeltem invasivem Mammakarzinom; jetzt neu aufgetretene Leber- und Knochenmetastasen nach Progress unter endokriner Therapie plus CDK4/6-Inhibition.":"Γυναίκα 56 ετών με διηθητικό καρκίνο μαστού που αντιμετωπίστηκε πριν από έξι χρόνια· τώρα νέες ηπατικές και οστικές μεταστάσεις μετά εξέλιξη υπό ενδοκρινική θεραπεία + αναστολή CDK4/6.","Welche klassischen prädiktiven Marker müssen an der Metastase erneut geklärt werden, und welchen zusätzlichen therapeutischen Nutzen liefern PIK3CA- sowie BRCA/HRR-Analysen?":"Ποιοι κλασικοί προβλεπτικοί δείκτες πρέπει να επανεκτιμηθούν στη μετάσταση και ποια πρόσθετη θεραπευτική αξία παρέχουν οι αναλύσεις PIK3CA και BRCA/HRR;","Therapiewechsel soll im nächsten MTB festgelegt werden.":"Η αλλαγή θεραπείας πρέπει να καθοριστεί στο επόμενο MTB.","Primärtumor vor 6 Jahren":"Πρωτοπαθής όγκος πριν από 6 χρόνια","ER 95 %, PgR 70 %, HER2 IHC 0; adjuvante Chemotherapie und anschließende endokrine Therapie.":"ER 95%, PgR 70%, HER2 IHC 0· επικουρική χημειοθεραπεία και στη συνέχεια ενδοκρινική θεραπεία.","Metastasierte Situation":"Μεταστατική κατάσταση","Nach initialer Krankheitskontrolle unter Aromatasehemmer + CDK4/6-Inhibitor nun hepatischer Progress.":"Μετά αρχικό έλεγχο της νόσου με αναστολέα αρωματάσης + αναστολέα CDK4/6, τώρα ηπατική εξέλιξη.","Familienanamnese":"Οικογενειακό ιστορικό","Mutter mit Ovarialkarzinom im Alter von 63 Jahren; bisher keine dokumentierte humangenetische Abklärung.":"Μητέρα με καρκίνο ωοθηκών σε ηλικία 63 ετών· μέχρι σήμερα χωρίς τεκμηριωμένη γενετική συμβουλευτική/εξέταση.","Ein breites Panel wird als Ersatz für die erneute Bestimmung der klassischen Tumorbiologie verstanden – oder ein Tumor-BRCA-Befund wird direkt als gesicherte Keimbahnmutation behandelt.":"Ένα ευρύ panel θεωρείται υποκατάστατο της επανεκτίμησης της κλασικής βιολογίας όγκου – ή ένα εύρημα BRCA στον όγκο αντιμετωπίζεται απευθείας ως αποδεδειγμένη germline μετάλλαξη.","Metastasenbiopsie":"Βιοψία μετάστασης","Adenokarzinom, morphologisch und immunhistochemisch vereinbar mit Mammakarzinommetastase.":"Αδενοκαρκίνωμα μορφολογικά και ανοσοϊστοχημικά συμβατό με μετάσταση καρκίνου μαστού.","Rezeptorstatus Metastase":"Κατάσταση υποδοχέων μετάστασης","ER 80 %, PgR 5 %. HER2-IHC 2+ und damit für die klassische HER2-Statusbestimmung zunächst äquivok.":"ER 80%, PgR 5%. HER2 IHC 2+ και επομένως αρχικά αμφίβολο για την κλασική αξιολόγηση κατάστασης HER2.","Offene molekulare Fragen":"Ανοιχτά μοριακά ερωτήματα","PIK3CA als endokrin-targetierbarer Kontext; BRCA1/2/HRR wegen PARP- und hereditärer Fragestellung.":"PIK3CA ως ενδοκρινικά στοχεύσιμο πλαίσιο· BRCA1/2/HRR λόγω PARP και κληρονομικού ερωτήματος.","Kernproblem":"Βασικό πρόβλημα","Klassische Marker und Molekularpanel beantworten unterschiedliche Ebenen derselben Therapieentscheidung.":"Οι κλασικοί δείκτες και τα μοριακά panels απαντούν σε διαφορετικά επίπεδα της ίδιας θεραπευτικής απόφασης.","FFPE-Leberbiopsie, Block L3.":"FFPE βιοψία ήπατος, block L3.","ca. 45 %, nach Makrodissektion gut geeignet.":"περ. 45%, κατάλληλο μετά από μακροδιατομή.","11 ungefärbte Schnitte; genug für gezielte IHC/ISH und fokussierte Molekulardiagnostik.":"11 άχρωμες τομές· επαρκείς για εστιασμένη IHC/ISH και στοχευμένη μοριακή διάγνωση.","DNA ausreichend; HER2-IHC technisch gut beurteilbar.":"Επαρκές DNA· η IHC HER2 είναι τεχνικά καλά αξιολογήσιμη.","Ein großes Pan-Panel verbraucht mehr Material, ersetzt aber weder die validierte HER2-IHC/ISH-Ebene noch die getrennte Keimbahnabklärung.":"Ένα μεγάλο pan-panel καταναλώνει περισσότερο υλικό αλλά δεν αντικαθιστά ούτε το επικυρωμένο επίπεδο HER2 IHC/ISH ούτε τη χωριστή germline αξιολόγηση.","HER2-Status der Metastase klären":"Διευκρινίστε την κατάσταση HER2 της μετάστασης","PIK3CA-Kontext":"Πλαίσιο PIK3CA","Tumor-BRCA/HRR-Kontext":"Πλαίσιο BRCA/HRR όγκου","HER2-Status":"Κατάσταση HER2","HER2-IHC 2+; ERBB2-ISH/FISH ohne Amplifikation. Der Tumor ist damit nicht HER2-amplifiziert; die äquivoke IHC allein darf nicht als HER2-positiv überinterpretiert werden.":"HER2 IHC 2+· ERBB2 ISH/FISH χωρίς ενίσχυση. Ο όγκος επομένως δεν είναι HER2-amplified· η αμφίβολη IHC μόνη της δεν πρέπει να υπερερμηνεύεται ως HER2-θετική.","PIK3CA":"PIK3CA","PIK3CA p.H1047R, pathogen/aktivierend. Im HR-positiven, HER2-negativen metastasierten Kontext therapeutisch relevant abhängig von Vorbehandlung, Therapielinie und aktueller Zulassung/Leitlinie.":"PIK3CA p.H1047R, παθογόνος/ενεργοποιητική. Θεραπευτικά σχετική σε HR-θετική, HER2-αρνητική μεταστατική νόσο ανάλογα με προθεραπεία, γραμμή θεραπείας και τρέχουσα έγκριση/οδηγία.","Tumor-BRCA/HRR":"BRCA/HRR όγκου","BRCA2-Frameshift-Variante mit Loss-of-function-Konsequenz, VAF 47 %. Der Tumorbefund kann eine therapeutisch und hereditär relevante Spur sein, beweist aber für sich keine Keimbahnmutation.":"Frameshift παραλλαγή BRCA2 με συνέπεια loss-of-function, VAF 47%. Το εύρημα στον όγκο μπορεί να αποτελεί θεραπευτικά και κληρονομικά σημαντική ένδειξη, αλλά δεν αποδεικνύει από μόνο του germline μετάλλαξη.","Humangenetische Weiterleitung":"Παραπομπή για γενετική συμβουλευτική","Humangenetische Beratung und Keimbahnabklärung werden empfohlen. Die hereditäre Einordnung erfolgt aus einer geeigneten Normalprobe und getrennt vom Tumor-only-Befund.":"Συνιστώνται γενετική συμβουλευτική και germline έλεγχος. Η κληρονομική ταξινόμηση γίνεται από κατάλληλο φυσιολογικό δείγμα και ξεχωριστά από το tumor-only εύρημα.","Rezeptorbiologie":"Βιολογία υποδοχέων","ER 80 %, PgR 5 %; HER2-IHC 2+ an der Metastase.":"ER 80%, PgR 5%· HER2 IHC 2+ στη μετάσταση.","Metastasenbiopsie ausreichend für fokussierte IHC/ISH und Molekulardiagnostik.":"Επαρκής βιοψία μετάστασης για εστιασμένη IHC/ISH και μοριακή διάγνωση.","HR-positives metastasiertes Mammakarzinom mit HER2-IHC 2+, aber ohne ERBB2-Amplifikation. Zusätzlich liegt eine aktivierende PIK3CA-Mutation vor. Eine pathogene BRCA2-Loss-of-function-Variante wurde im Tumor gefunden; ihre Keimbahnherkunft ist aus der Tumoranalyse nicht ableitbar und muss separat humangenetisch geklärt werden. Klassische Rezeptor-/HER2-Diagnostik und molekulare Zusatzdiagnostik ergänzen sich und dürfen nicht gegeneinander ersetzt werden.":"HR-θετικός μεταστατικός καρκίνος μαστού με HER2 IHC 2+ αλλά χωρίς ενίσχυση ERBB2. Επιπλέον υπάρχει ενεργοποιητική μετάλλαξη PIK3CA. Στον όγκο βρέθηκε παθογόνος loss-of-function παραλλαγή BRCA2· η germline προέλευσή της δεν μπορεί να συναχθεί από την ανάλυση όγκου και πρέπει να διευκρινιστεί ξεχωριστά με γενετική συμβουλευτική/έλεγχο. Η κλασική διάγνωση υποδοχέων/HER2 και ο πρόσθετος μοριακός έλεγχος συμπληρώνουν ο ένας τον άλλο και δεν πρέπει να αντικαθίστανται μεταξύ τους.","Teilbefund: Die molekularen Zusatzmarker sind nur im aktuellen ER/PgR/HER2-Kontext sinnvoll interpretierbar. Ein HER2-IHC-2+-Befund benötigt die validierte ISH/FISH-Klärung; ein Tumor-BRCA2-Befund ist nicht automatisch ein Keimbahnbefund.":"Μερικό εύρημα: Οι πρόσθετοι μοριακοί δείκτες μπορούν να ερμηνευθούν ουσιαστικά μόνο στο τρέχον πλαίσιο ER/PgR/HER2. Ένα αποτέλεσμα HER2 IHC 2+ απαιτεί έγκυρη διευκρίνιση ISH/FISH· ένα εύρημα BRCA2 στον όγκο δεν είναι αυτόματα germline εύρημα.","Aktuellen ER/PgR/HER2-Kontext der Metastase als Grundlage benennen":"Αναφέρετε το τρέχον πλαίσιο ER/PgR/HER2 της μετάστασης ως βάση","HER2 IHC 2+ durch ISH/FISH klären und nicht vorschnell als HER2-positiv bezeichnen":"Διευκρινίστε HER2 IHC 2+ με ISH/FISH και μην το χαρακτηρίζετε πρόωρα HER2-θετικό","PIK3CA als zusätzlichen, therapielinienabhängigen Targetkontext integrieren":"Ενσωματώστε PIK3CA ως πρόσθετο target πλαίσιο εξαρτώμενο από τη θεραπευτική γραμμή","Tumor-BRCA2 therapeutisch/hereditär relevant einordnen, Keimbahn aber separat klären":"Ταξινομήστε το BRCA2 όγκου ως θεραπευτικά/κληρονομικά σχετικό, αλλά αξιολογήστε germline ξεχωριστά","Paneldiagnostik nicht als Ersatz für klassische Biomarker oder Humangenetik darstellen":"Μην παρουσιάζετε το panel testing ως υποκατάστατο κλασικών βιοδεικτών ή γενετικής συμβουλευτικής","Optimale Lösung: Metastasenbiologie zuerst korrekt mit ER/PgR/HER2 charakterisieren; HER2 2+ durch ISH als nicht amplifiziert klären; PIK3CA als zusätzliche therapeutische Information nutzen; pathogene Tumor-BRCA2-Variante als wichtige Spur berichten, aber Keimbahnstatus separat abklären.":"Βέλτιστη λύση: Χαρακτηρίστε πρώτα σωστά τη βιολογία της μετάστασης με ER/PgR/HER2· διευκρινίστε HER2 2+ με ISH ως μη ενισχυμένο· χρησιμοποιήστε PIK3CA ως πρόσθετη θεραπευτική πληροφορία· αναφέρετε την παθογόνο BRCA2 παραλλαγή στον όγκο ως σημαντική ένδειξη, αλλά αξιολογήστε germline κατάσταση ξεχωριστά.","Mammakarzinom":"Καρκίνος μαστού","HR+":"HR+","BRCA2":"BRCA2","Keimbahn":"Germline","PARP":"PARP","Klassische Marker zuerst, Panel danach: HER2 2+, PIK3CA und der Tumor-BRCA2-Twist":"Πρώτα οι κλασικοί δείκτες, μετά το panel: HER2 2+, PIK3CA και η ανατροπή BRCA2 στον όγκο","Molekularpathologie / Gynäko-Onkologie / MTB":"Μοριακή παθολογία / Γυναικολογική ογκολογία / MTB","Bei metastasiertem Mammakarzinom die aktuelle Tumorbiologie der Metastase einschließlich ER/PgR/HER2 als Grundlage der Systemtherapie verstehen.":"Στον μεταστατικό καρκίνο μαστού, κατανοήστε την τρέχουσα βιολογία της μετάστασης, συμπεριλαμβανομένων ER/PgR/HER2, ως βάση της συστηματικής θεραπείας.","HER2-IHC 2+ nicht als HER2-positiv überinterpretieren, sondern mit validierter ISH/FISH klären.":"Μην υπερερμηνεύετε HER2 IHC 2+ ως HER2-θετικό· διευκρινίστε με επικυρωμένο ISH/FISH.","PIK3CA als zusätzliche molekulare Therapieinformation im HR-positiven/HER2-negativen Kontext einordnen.":"Εντάξτε το PIK3CA ως πρόσθετη μοριακή θεραπευτική πληροφορία στο πλαίσιο HR-θετικού/HER2-αρνητικού όγκου.","Eine pathogene BRCA2-Variante aus Tumor-only-NGS von einer gesicherten Keimbahnmutation trennen.":"Διαχωρίστε μια παθογόνο παραλλαγή BRCA2 από tumor-only NGS από μια επιβεβαιωμένη βλαστική μετάλλαξη.","Verstehen, dass Multigen-NGS klassische Biomarker ergänzt, aber nicht ersetzt.":"Κατανοήστε ότι το πολυγονιδιακό NGS συμπληρώνει τους κλασικούς βιοδείκτες αλλά δεν τους αντικαθιστά.","Die Lebermetastase ist ER-positiv und HER2-IHC 2+. Parallel meldet das Panel eine aktivierende PIK3CA-Mutation und eine pathogene BRCA2-Frameshift-Variante. Im Tumorboard fallen sofort drei vermeintlich einfache Schlussfolgerungen: 'HER2-positiv', 'PIK3CA-targetierbar' und 'BRCA erblich'. Genau dieser Fall zeigt, warum alle drei Aussagen erst im richtigen diagnostischen Kontext belastbar werden.":"Η ηπατική μετάσταση είναι ER-θετική και HER2 IHC 2+. Παράλληλα, το panel αναφέρει ενεργοποιητική μετάλλαξη PIK3CA και παθογόνο frameshift παραλλαγή BRCA2. Στο μοριακό ογκολογικό συμβούλιο προκύπτουν αμέσως τρία φαινομενικά απλά συμπεράσματα: «HER2-θετικό», «PIK3CA ως target» και «κληρονομικό BRCA». Η περίπτωση δείχνει γιατί και οι τρεις δηλώσεις είναι αξιόπιστες μόνο στο σωστό διαγνωστικό πλαίσιο.","56-jährige Patientin mit HR-positivem Mammakarzinom und hepatischem Progress nach endokriner Therapie plus CDK4/6-Inhibition. Die aktuelle Metastasenbiopsie ist ER 80 %, PgR 5 % und HER2-IHC 2+. Gesucht wird eine integrierte Therapiebiologie aus klassischer HER2-Diagnostik, PIK3CA und BRCA/HRR, ohne die Grenzen von Tumor-only-NGS zu verwischen.":"Ασθενής 56 ετών με HR-θετικό καρκίνο μαστού και ηπατική πρόοδο μετά από ενδοκρινική θεραπεία και αναστολέα CDK4/6. Η τρέχουσα βιοψία μετάστασης είναι ER 80%, PgR 5% και HER2 IHC 2+. Ζητείται ολοκληρωμένη θεραπευτική βιολογία από κλασική HER2 διάγνωση, PIK3CA και BRCA/HRR, χωρίς να συγχέονται οι περιορισμοί του tumor-only NGS.","Metastasenbiologie":"Βιολογία μετάστασης","ER 80 %, PgR 5 %, HER2-IHC 2+.":"ER 80%, PgR 5%, HER2 IHC 2+.","Die aktuelle Metastase kann sich biologisch vom Primärtumor unterscheiden; klassische Marker bleiben Grundlage.":"Η τρέχουσα μετάσταση μπορεί να διαφέρει βιολογικά από τον πρωτοπαθή όγκο· οι κλασικοί δείκτες παραμένουν θεμελιώδεις.","Molekulare Zusatzebene":"Πρόσθετο μοριακό επίπεδο","PIK3CA und BRCA/HRR sollen gezielt ergänzt werden.":"Τα PIK3CA και BRCA/HRR πρέπει να προστεθούν στοχευμένα.","Zusatznutzen entsteht erst im bekannten HR/HER2-Kontext.":"Η πρόσθετη αξία προκύπτει μόνο μέσα στο γνωστό πλαίσιο HR/HER2.","Familienrelevanz":"Οικογενειακή σημασία","Mutter mit Ovarialkarzinom; keine bisherige Humangenetik.":"Μητέρα με καρκίνο ωοθηκών· χωρίς προηγούμενο γενετικό έλεγχο/συμβουλευτική.","Tumor-only kann einen Verdacht erzeugen, aber Keimbahn nicht beweisen.":"Η tumor-only ανάλυση μπορεί να εγείρει υποψία, αλλά δεν αποδεικνύει βλαστική προέλευση.","Mammakarzinommetastase, ER 80 %, PgR 5 %, HER2-IHC 2+.":"Μετάσταση καρκίνου μαστού, ER 80%, PgR 5%, HER2 IHC 2+.","Vor sechs Jahren ER/PgR stark positiv, HER2-IHC 0.":"Πριν από έξι χρόνια έντονα ER/PgR-θετικό, HER2 IHC 0.","Leberbiopsie mit ca. 45 % Tumor; fokussierte IHC/ISH und NGS sind möglich.":"Ηπατική βιοψία με περίπου 45% όγκο· στοχευμένα IHC/ISH και NGS είναι εφικτά.","Elf Schnitte erlauben eine fokussierte Diagnostik, aber unnötige Breitdiagnostik kostet Material.":"Έντεκα τομές επιτρέπουν στοχευμένη διάγνωση, αλλά περιττός ευρύς έλεγχος καταναλώνει υλικό.","HER2-IHC 2+ benötigt eine validierte Amplifikationsabklärung; NGS ersetzt diesen diagnostischen Algorithmus nicht automatisch.":"HER2 IHC 2+ απαιτεί επικυρωμένο έλεγχο ενίσχυσης· το NGS δεν αντικαθιστά αυτόματα αυτόν τον διαγνωστικό αλγόριθμο.","Eine Normalprobe für die Keimbahnabklärung ist in der Tumorpathologie nicht vorhanden.":"Δεν υπάρχει διαθέσιμο φυσιολογικό δείγμα στην ογκολογική παθολογία για έλεγχο βλαστικής σειράς.","Was ist die wichtigste Grundlage, bevor PIK3CA/BRCA therapeutisch interpretiert werden?":"Ποια είναι η σημαντικότερη βάση πριν από τη θεραπευτική ερμηνεία PIK3CA/BRCA;","Die aktuelle ER/PgR/HER2-Biologie der Metastase muss belastbar feststehen; das Panel ergänzt diese Ebene.":"Η τρέχουσα βιολογία ER/PgR/HER2 της μετάστασης πρέπει να τεκμηριωθεί αξιόπιστα· το panel συμπληρώνει αυτό το επίπεδο.","Ein ausreichend breites NGS-Panel ersetzt ER/PgR/HER2 vollständig.":"Ένα αρκετά ευρύ NGS panel αντικαθιστά πλήρως ER/PgR/HER2.","Der Rezeptorstatus des Primärtumors vor sechs Jahren reicht aus.":"Η κατάσταση υποδοχέων του πρωτοπαθούς όγκου πριν από έξι χρόνια αρκεί.","BRCA2 entscheidet unabhängig von HR/HER2 über die gesamte Therapie.":"Το BRCA2 καθορίζει όλη τη θεραπεία ανεξάρτητα από HR/HER2.","Beim metastasierten Mammakarzinom bleibt die aktuelle Tumorbiologie eine zentrale prädiktive Grundlage.":"Στον μεταστατικό καρκίνο μαστού, η τρέχουσα βιολογία του όγκου παραμένει κεντρική προγνωστική/προβλεπτική βάση.","Die Metastase ist HER2-IHC 2+. Was bedeutet das?":"Η μετάσταση είναι HER2 IHC 2+. Τι σημαίνει αυτό;","Äquivoker Befund: ERBB2-Amplifikation mit validierter ISH/FISH klären; IHC 2+ allein ist nicht gleich HER2-amplifiziert.":"Αμφίβολο εύρημα: διευκρινίστε ενίσχυση ERBB2 με επικυρωμένο ISH/FISH· IHC 2+ μόνο του δεν ισοδυναμεί με ενίσχυση HER2.","HER2-positiv, weitere Klärung unnötig.":"HER2-θετικό, δεν απαιτείται περαιτέρω διευκρίνιση.","Sicher HER2-negativ, ISH ist nie erforderlich.":"Σίγουρα HER2-αρνητικό· ISH δεν απαιτείται ποτέ.","Nur die BRCA-Analyse entscheidet, HER2 ist irrelevant.":"Μόνο η ανάλυση BRCA έχει σημασία· το HER2 είναι άσχετο.","IHC 2+ benötigt die etablierte Amplifikationsabklärung.":"IHC 2+ απαιτεί τον καθιερωμένο έλεγχο ενίσχυσης.","Tumor-NGS zeigt eine pathogene BRCA2-Frameshift-Variante mit VAF 47 %. Was darf daraus geschlossen werden?":"Το tumor NGS δείχνει παθογόνο frameshift παραλλαγή BRCA2 με VAF 47%. Τι μπορεί να συμπερανθεί;","Der Befund ist therapeutisch/hereditär relevant, aber Tumor-only beweist keine Keimbahnmutation; Humangenetik/Normalprobe separat klären.":"Το εύρημα είναι θεραπευτικά/κληρονομικά σημαντικό, αλλά το tumor-only δεν αποδεικνύει βλαστική μετάλλαξη· απαιτείται ξεχωριστή γενετική συμβουλευτική/φυσιολογικό δείγμα.","VAF nahe 50 % beweist eine Keimbahnmutation.":"VAF κοντά στο 50% αποδεικνύει βλαστική μετάλλαξη.","Da die Probe Tumorgewebe ist, ist die Variante sicher rein somatisch.":"Επειδή το δείγμα είναι ιστός όγκου, η παραλλαγή είναι σίγουρα αμιγώς σωματική.","Eine Frameshift-Variante ist automatisch eine VUS.":"Μια frameshift παραλλαγή είναι αυτόματα VUS.","Tumor-VAF und selbst LOH trennen somatisch und Keimbahn nicht zuverlässig.":"Η VAF στον όγκο και ακόμη και LOH δεν διαχωρίζουν αξιόπιστα σωματική από βλαστική προέλευση.","Wie ist der Zusatznutzen des Panels hier am besten beschrieben?":"Πώς περιγράφεται καλύτερα η πρόσθετη αξία του panel εδώ;","PIK3CA/BRCA liefern zusätzliche therapie- und familienrelevante Information, ersetzen aber weder HER2-IHC/ISH noch die Keimbahnabklärung.":"PIK3CA/BRCA παρέχουν πρόσθετες πληροφορίες σχετικές με θεραπεία και οικογένεια, αλλά δεν αντικαθιστούν ούτε HER2 IHC/ISH ούτε τον έλεγχο βλαστικής σειράς.","Das Panel macht klassische Biomarker und Humangenetik überflüssig.":"Το panel καθιστά περιττούς τους κλασικούς βιοδείκτες και τη γενετική συμβουλευτική.","Molekulardiagnostik hat bei HR-positivem Mammakarzinom keinen Zusatznutzen.":"Η μοριακή διάγνωση δεν προσθέτει αξία στον HR-θετικό καρκίνο μαστού.","Nur BRCA2 ist relevant; PIK3CA und HER2 können ignoriert werden.":"Μόνο το BRCA2 είναι σημαντικό· PIK3CA και HER2 μπορούν να αγνοηθούν.","Die Stärke liegt in der Integration komplementärer diagnostischer Ebenen.":"Η δύναμη βρίσκεται στην ενσωμάτωση συμπληρωματικών διαγνωστικών επιπέδων.","Formulieren Sie eine integrierte MTB-Aussage, die den aktuellen HR/HER2-Status der Metastase, PIK3CA und die Tumor-BRCA2-Variante zusammenführt und klar trennt, welche Information unmittelbar tumorbezogen ist und welche eine separate Keimbahnabklärung erfordert.":"Διατυπώστε ολοκληρωμένη δήλωση MTB που συνδυάζει το τρέχον HR/HER2 της μετάστασης, το PIK3CA και την παραλλαγή BRCA2 του όγκου και διαχωρίζει σαφώς ποια πληροφορία αφορά άμεσα τον όγκο και ποια απαιτεί ξεχωριστό έλεγχο βλαστικής σειράς.","Aktuelle Metastasenbiologie mit ER/PgR/HER2 als Grundlage verwenden.":"Χρησιμοποιήστε ως βάση την τρέχουσα βιολογία της μετάστασης με ER/PgR/HER2.","HER2-IHC 2+ durch ISH/FISH klären: keine ERBB2-Amplifikation.":"Διευκρινίστε HER2 IHC 2+ με ISH/FISH: χωρίς ενίσχυση ERBB2.","PIK3CA p.H1047R als zusätzlichen therapielinienabhängigen Targetkontext berichten.":"Αναφέρετε το PIK3CA p.H1047R ως πρόσθετο target πλαίσιο που εξαρτάται από τη γραμμή θεραπείας.","Tumor-BRCA2-Loss-of-function als relevante molekulare Spur einordnen.":"Εντάξτε το tumor BRCA2 loss-of-function ως σημαντική μοριακή ένδειξη.","Tumor-BRCA2 nicht als gesicherte Keimbahnmutation bezeichnen; humangenetische Beratung/Normalprobe empfehlen.":"Μην χαρακτηρίζετε το tumor BRCA2 ως επιβεβαιωμένη βλαστική μετάλλαξη· συστήστε γενετική συμβουλευτική/φυσιολογικό δείγμα.","Therapieoptionen an aktuelle Zulassung, Vorbehandlung und Gesamtbiologie binden.":"Συνδέστε τις θεραπευτικές επιλογές με την τρέχουσα έγκριση, την προηγούμενη θεραπεία και τη συνολική βιολογία.","Validiertes Multigenpanel zur kombinierten Erfassung von PIK3CA und BRCA/HRR, sofern HER2 weiterhin separat nach validiertem IHC/ISH-Algorithmus beurteilt wird.":"Επικυρωμένο πολυγονιδιακό panel για συνδυασμένη ανίχνευση PIK3CA και BRCA/HRR, εφόσον το HER2 συνεχίζει να αξιολογείται ξεχωριστά με επικυρωμένο αλγόριθμο IHC/ISH.","Gezielte PIK3CA-Analyse plus Tumor-BRCA/HRR-Panel, um Material und TAT zu schonen.":"Στοχευμένη ανάλυση PIK3CA συν tumor BRCA/HRR panel για εξοικονόμηση υλικού και TAT.","HER2 2+ = HER2-positiv":"HER2 2+ = HER2-θετικό","IHC 2+ ist äquivok und benötigt die Amplifikationsabklärung.":"IHC 2+ είναι αμφίβολο και απαιτεί έλεγχο ενίσχυσης.","Tumor-BRCA2 = Keimbahn-BRCA2":"Tumor BRCA2 = germline BRCA2","Tumor-only-NGS kann die Herkunft nicht sicher bestimmen.":"Το tumor-only NGS δεν μπορεί να καθορίσει αξιόπιστα την προέλευση.","Pan-Panel ersetzt alles":"Το pan-panel αντικαθιστά τα πάντα","Klassische Protein-/Amplifikationsmarker und Humangenetik beantworten andere diagnostische Ebenen.":"Οι κλασικοί δείκτες πρωτεΐνης/ενίσχυσης και η γενετική βλαστικής σειράς απαντούν σε διαφορετικά διαγνωστικά επίπεδα.","Primärtumorstatus reicht":"Η κατάσταση του πρωτοπαθούς όγκου αρκεί","Bei metastasierter Erkrankung kann eine Rebiopsie die aktuelle Tumorbiologie neu bewerten.":"Στη μεταστατική νόσο, η επαναβιοψία μπορεί να επανεκτιμήσει την τρέχουσα βιολογία του όγκου.","Zwei 'positive' Befunde – aber keiner bedeutet das, was der erste Blick suggeriert":"Δύο «θετικά» ευρήματα – αλλά κανένα δεν σημαίνει αυτό που υποδηλώνει η πρώτη ματιά","HER2-IHC 2+ wird durch ISH als nicht amplifiziert geklärt. Gleichzeitig zeigt Tumor-NGS BRCA2 Loss-of-function bei VAF 47 %. Das klingt nach HER2-positiv plus erblichem BRCA-Syndrom – tatsächlich ist ersteres äquivok/nicht amplifiziert und letzteres zunächst ein Tumorbefund mit notwendiger separater Keimbahnklärung. Die klar tumorbezogene Zusatzinformation ist eine aktivierende PIK3CA-p.H1047R-Mutation.":"Το HER2 IHC 2+ διευκρινίζεται με ISH ως μη ενισχυμένο. Παράλληλα, tumor NGS δείχνει BRCA2 loss-of-function με VAF 47%. Αυτό ακούγεται σαν HER2-θετικό νόσημα και κληρονομικό σύνδρομο BRCA – στην πραγματικότητα, το πρώτο είναι αμφίβολο/μη ενισχυμένο και το δεύτερο αρχικά αποτελεί εύρημα όγκου που απαιτεί ξεχωριστή διερεύνηση βλαστικής σειράς. Η σαφώς tumor-related πρόσθετη πληροφορία είναι ενεργοποιητική μετάλλαξη PIK3CA p.H1047R.","Der Fall zwingt zur Trennung von Proteinexpression, Genamplifikation, somatischer Tumorgenetik und Keimbahnstatus – vier Ebenen, die therapeutisch miteinander interagieren, aber diagnostisch nicht austauschbar sind.":"Η περίπτωση επιβάλλει διαχωρισμό έκφρασης πρωτεΐνης, γονιδιακής ενίσχυσης, σωματικής γενετικής του όγκου και κατάστασης βλαστικής σειράς – τέσσερα επίπεδα που αλληλεπιδρούν θεραπευτικά αλλά δεν είναι διαγνωστικά εναλλάξιμα.","Klassik und Molekularprofil integriert":"Ενσωμάτωση κλασικών δεικτών και μοριακού προφίλ","ER 80 %, PgR 5 %, HER2-IHC 2+/ISH nicht amplifiziert; PIK3CA p.H1047R; pathogene BRCA2-Frameshift-Variante im Tumor. PIK3CA im aktuellen HR+/HER2-negativen Therapiekontext berücksichtigen; BRCA2 als relevante Tumorspur mit separater Keimbahnabklärung berichten.":"ER 80%, PgR 5%, HER2 IHC 2+/ISH μη ενισχυμένο· PIK3CA p.H1047R· παθογόνος frameshift παραλλαγή BRCA2 στον όγκο. Εξετάστε το PIK3CA στο τρέχον HR+/HER2-αρνητικό θεραπευτικό πλαίσιο· αναφέρετε το BRCA2 ως σημαντικό εύρημα όγκου με ξεχωριστό έλεγχο βλαστικής σειράς.","Alle diagnostischen Ebenen korrekt getrennt und integriert.":"Όλα τα διαγνωστικά επίπεδα διαχωρίστηκαν και ενσωματώθηκαν σωστά.","Panel gut, klassische Ebene offen":"Καλό panel, κλασικό επίπεδο αδιευκρίνιστο","PIK3CA und BRCA2 werden gefunden, HER2-IHC 2+ aber nicht durch ISH geklärt.":"PIK3CA και BRCA2 ανιχνεύονται, αλλά HER2 IHC 2+ δεν διευκρινίζεται με ISH.","Therapiebiologie bleibt unvollständig.":"Η θεραπευτική βιολογία παραμένει ελλιπής.","HER2 und Keimbahn überinterpretiert":"Υπερερμηνεία HER2 και βλαστικής σειράς","HER2-IHC 2+ wird als HER2-positiv und Tumor-BRCA2 als sicher keimbahnpathogen bezeichnet.":"HER2 IHC 2+ χαρακτηρίζεται HER2-θετικό και tumor BRCA2 ως σίγουρα παθογόνο βλαστικής σειράς.","Zwei zentrale diagnostische Grenzüberschreitungen.":"Δύο μείζονες υπερβάσεις διαγνωστικών ορίων.","Tumor-BRCA2 pathologisch":"Παθολογικό tumor BRCA2","Humangenetische Beratung und Keimbahntestung aus geeigneter Normalprobe veranlassen.":"Οργανώστε γενετική συμβουλευτική και έλεγχο βλαστικής σειράς από κατάλληλο φυσιολογικό δείγμα.","Therapie- und Familienrelevanz werden getrennt, aber koordiniert weiterverfolgt.":"Η θεραπευτική και οικογενειακή σημασία διερευνώνται ξεχωριστά αλλά συντονισμένα.","HER2-ISH nicht amplifiziert":"HER2 ISH μη ενισχυμένο","Therapieplanung im HR+/HER2-negativen Kontext fortsetzen und PIK3CA/weitere Linienmarker berücksichtigen.":"Συνεχίστε τον θεραπευτικό σχεδιασμό στο HR+/HER2-αρνητικό πλαίσιο και εξετάστε PIK3CA/άλλους δείκτες ανά γραμμή.","HER2-IHC 2+ wird nicht als Amplifikationspositivität fehlgedeutet.":"HER2 IHC 2+ δεν παρερμηνεύεται ως θετικότητα ενίσχυσης.","Beim metastasierten Mammakarzinom bleibt die aktuelle ER/PgR/HER2-Biologie zentral.":"Στον μεταστατικό καρκίνο μαστού, η τρέχουσα βιολογία ER/PgR/HER2 παραμένει κεντρική.","HER2-IHC 2+ ist ein Klärungsbefund, kein automatisches positives Endergebnis.":"HER2 IHC 2+ είναι εύρημα που απαιτεί διευκρίνιση, όχι αυτόματα θετικό τελικό αποτέλεσμα.","PIK3CA erweitert die therapeutische Information im passenden HR+/HER2-negativen Kontext.":"Το PIK3CA επεκτείνει τη θεραπευτική πληροφορία στο κατάλληλο HR+/HER2-αρνητικό πλαίσιο.","Tumor-only BRCA kann klinisch hochrelevant sein, beweist aber keinen Keimbahnstatus.":"Το tumor-only BRCA μπορεί να είναι εξαιρετικά κλινικά σημαντικό αλλά δεν αποδεικνύει κατάσταση βλαστικής σειράς.","Multigen-NGS ergänzt klassische Pathologiemarker; es ersetzt sie nicht.":"Το πολυγονιδιακό NGS συμπληρώνει τους κλασικούς δείκτες παθολογίας· δεν τους αντικαθιστά.","Aktuelle Metastasenbiologie zuerst: HR-positiv, HER2-IHC 2+, aber ISH nicht amplifiziert. PIK3CA p.H1047R ist als zusätzlicher therapeutischer Marker relevant. Die pathogene BRCA2-Frameshift-Variante stammt aus Tumor-only-NGS; sie darf nicht als Keimbahnmutation bezeichnet werden und löst eine separate humangenetische Abklärung aus.":"Πρώτα η τρέχουσα βιολογία μετάστασης: HR-θετικό, HER2 IHC 2+, αλλά ISH μη ενισχυμένο. Το PIK3CA p.H1047R είναι σημαντικό ως πρόσθετος θεραπευτικός δείκτης. Η παθογόνος frameshift παραλλαγή BRCA2 προέρχεται από tumor-only NGS· δεν πρέπει να χαρακτηριστεί βλαστική μετάλλαξη και απαιτεί ξεχωριστή γενετική διερεύνηση.","HER2 2+ korrekt geklärt":"HER2 2+ σωστά διευκρινισμένο","PIK3CA im passenden Kontext integriert":"PIK3CA ενσωματωμένο στο κατάλληλο πλαίσιο","Tumor vs. Keimbahn getrennt":"Διαχωρισμός όγκου και βλαστικής σειράς","Panel nicht als Ersatz klassischer Marker":"Το panel δεν αντιμετωπίζεται ως υποκατάστατο κλασικών δεικτών","Warum sollte die Metastase erneut auf ER/PgR/HER2 untersucht werden?":"Γιατί πρέπει να επανελεγχθεί η μετάσταση για ER/PgR/HER2;","Welche Aussage kann eine Tumor-VAF von etwa 50 % zur Keimbahnherkunft leisten – und welche nicht?":"Τι μπορεί να μας πει VAF όγκου περίπου 50% για βλαστική προέλευση – και τι δεν μπορεί;","Wann ist ein breites Panel gegenüber fokussierter Diagnostik wirklich sinnvoll?":"Πότε είναι ένα ευρύ panel πραγματικά χρήσιμο σε σύγκριση με στοχευμένη διάγνωση;","HER2 2+ nicht amplifiziert + Tumor-BRCA2 ist nicht automatisch Keimbahn":"HER2 2+ μη ενισχυμένο + tumor BRCA2 δεν σημαίνει αυτόματα βλαστική προέλευση","Klassische Marker und Molekularprofil sind komplementär":"Οι κλασικοί δείκτες και το μοριακό προφίλ είναι συμπληρωματικά","Metastasenbiologie → HER2-Klärung → PIK3CA/BRCA → Keimbahn separat":"Βιολογία μετάστασης → διευκρίνιση HER2 → PIK3CA/BRCA → ξεχωριστά βλαστική σειρά","Metastasiertes Prostatakarzinom: HRR-Gene/MMR → PARP/IO/Studie und Keimbahnfrage":"Μεταστατικός καρκίνος προστάτη: γονίδια HRR/MMR → PARP/IO/μελέτη και ερώτημα βλαστικής σειράς","Metastasiertes Prostatakarzinom: H…":"Μεταστατικός καρκίνος προστάτη: H…","Uro-Onkologie / Molekulares Tumorboard":"Ουρο-ογκολογία / Μοριακό ογκολογικό συμβούλιο","69-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom und radiologischem Progress nach Androgendeprivation plus neuem hormonellen Wirkstoff.":"Ασθενής 69 ετών με μεταστατικό ευνουχοάντοχο καρκίνο προστάτη και ακτινολογική πρόοδο μετά από ανδρογονικό αποκλεισμό συν νεότερο ορμονικό παράγοντα.","Gibt es einen HRR-/BRCA-Biomarker für eine PARP-Strategie? Besteht ein MMR/MSI-basierter Immuntherapiekontext? Muss eine Keimbahnabklärung folgen?":"Υπάρχει βιοδείκτης HRR/BRCA για στρατηγική PARP; Υπάρχει πλαίσιο ανοσοθεραπείας βάσει MMR/MSI; Χρειάζεται έλεγχος βλαστικής σειράς;","Therapieentscheidung in der kommenden Woche.":"Θεραπευτική απόφαση την επόμενη εβδομάδα.","Verlauf":"Πορεία","Initial lokal fortgeschrittenes Adenokarzinom; später ossäre und nodale Metastasierung, jetzt mCRPC.":"Αρχικά τοπικά προχωρημένο αδενοκαρκίνωμα· αργότερα οστικές και λεμφαδενικές μεταστάσεις, τώρα mCRPC.","ADT fortgeführt; Progress unter neuem hormonellem Wirkstoff.":"Συνέχιση ADT· πρόοδος υπό νεότερο ορμονικό παράγοντα.","Auf dem ursprünglichen Anforderungsschein 'unauffällig'. Im Gespräch berichtet der Patient später von einem Bruder mit Pankreaskarzinom und einem Vater mit Prostatakarzinom.":"Στο αρχικό παραπεμπτικό αναγράφεται «χωρίς ιδιαίτερα στοιχεία». Αργότερα στη συζήτηση, ο ασθενής αναφέρει αδελφό με καρκίνο παγκρέατος και πατέρα με καρκίνο προστάτη.","HRD-Score aus dem Ovarialkarzinom wird als universeller PARP-Test verwendet oder Tumor-BRCA und Keimbahnstatus werden gleichgesetzt.":"Ένα HRD score από τον καρκίνο ωοθηκών χρησιμοποιείται ως καθολικό τεστ PARP ή το tumor BRCA εξισώνεται με τη βλαστική κατάσταση.","Stanzbiopsie einer Lebermetastase mit hochgradigem Prostataadenokarzinom.":"Core βιοψία ηπατικής μετάστασης με υψηλού βαθμού αδενοκαρκίνωμα προστάτη.","NKX3.1/PSA-Kontext mit Prostataursprung vereinbar.":"Προφίλ NKX3.1/PSA συμβατό με προστατική προέλευση.","Klinische Frage":"Κλινικό ερώτημα","Therapiebiomarker im mCRPC, nicht erneute Primärdiagnostik.":"Θεραπευτικοί βιοδείκτες στο mCRPC, όχι επανάληψη της πρωτοπαθούς διάγνωσης.","BRCA/HRR, MMR/MSI und hereditäre Einordnung.":"BRCA/HRR, MMR/MSI και κληρονομική ταξινόμηση.","ca. 55 %, ausreichend für NGS und MMR-IHC.":"περ. 55%, επαρκές για NGS και MMR IHC.","DNA":"DNA","gute Qualität.":"καλή ποιότητα.","12 Schnitte.":"12 τομές.","Methodenfalle":"Μεθοδολογική παγίδα","Ein unspezifischer HRD-Genomic-Scar-Score ist hier nicht der primäre etablierte Selektionsweg; gen-spezifische HRR/BRCA-Diagnostik und MMR/MSI beantworten die konkrete Frage direkter.":"Ένα μη ειδικό HRD genomic-scar score δεν αποτελεί εδώ τον κύριο καθιερωμένο τρόπο επιλογής· η γονιδιο-ειδική διάγνωση HRR/BRCA και το MMR/MSI απαντούν πιο άμεσα στο συγκεκριμένο ερώτημα.","Prostata-HRR/BRCA-Status":"Κατάσταση HRR/BRCA προστάτη","MMR/MSI-Kontext":"Πλαίσιο MMR/MSI","HRR/BRCA":"HRR/BRCA","Pathogene BRCA2-Frameshift-Variante im Tumor, VAF 58 %, mit zusätzlichem Verlust des Wildtypallels vereinbar. Im mCRPC ist BRCA1/2 unabhängig von somatischer oder Keimbahnherkunft ein relevanter PARP-Biomarkerkontext; die konkrete Therapie richtet sich nach Vorbehandlung und aktueller Zulassung/Leitlinie.":"Παθογόνος frameshift παραλλαγή BRCA2 στον όγκο, VAF 58%, συμβατή με πρόσθετη απώλεια του wild-type αλληλίου. Στο mCRPC, BRCA1/2 ανεξάρτητα από σωματική ή βλαστική προέλευση αποτελούν σχετικό πλαίσιο βιοδείκτη PARP· η συγκεκριμένη θεραπεία εξαρτάται από προηγούμενη αγωγή και τρέχουσα έγκριση/κατευθυντήριες οδηγίες.","Erhaltene Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Διατηρημένη έκφραση MLH1, PMS2, MSH2 και MSH6: pMMR.","MSS / kein MSI-H. Damit ergibt sich aus MMR/MSI in diesem Fall kein spezifischer IO-Biomarkerkontext.":"MSS / χωρίς MSI-H. Επομένως, το MMR/MSI δεν παρέχει εδώ ειδικό πλαίσιο βιοδείκτη IO.","HRD-Score":"HRD score","Ein Genomic-Scar/HRD-Score liefert im Prostatakarzinom keine gleichwertige, etablierte Ersatzinformation für die gen-spezifische BRCA/HRR-Diagnostik. Er darf den BRCA2-Befund nicht überstimmen oder eine negative HRR-Analyse ersetzen.":"Ένα genomic-scar/HRD score στον καρκίνο προστάτη δεν παρέχει ισοδύναμη καθιερωμένη πληροφορία υποκατάστασης της γονιδιο-ειδικής διάγνωσης BRCA/HRR. Δεν πρέπει να υπερισχύει του ευρήματος BRCA2 ούτε να αντικαθιστά αρνητική ανάλυση HRR.","Keimbahnabklärung":"Έλεγχος βλαστικής σειράς","Humangenetische Beratung/Keimbahntestung wird aufgrund der pathogenen BRCA2-Variante und der Familienanamnese empfohlen. Tumor-only VAF und LOH beweisen die Keimbahnherkunft nicht.":"Συστήνεται γενετική συμβουλευτική/έλεγχος βλαστικής σειράς λόγω της παθογόνου παραλλαγής BRCA2 και του οικογενειακού ιστορικού. Tumor-only VAF και LOH δεν αποδεικνύουν βλαστική προέλευση.","Klinischer Status":"Κλινική κατάσταση","mCRPC mit Progress nach neuem hormonellen Wirkstoff.":"mCRPC με πρόοδο μετά από νεότερο ορμονικό παράγοντα.","Metastasenbiopsie mit ausreichendem Tumoranteil für HRR- und MMR-Diagnostik.":"Βιοψία μετάστασης με επαρκές ποσοστό όγκου για έλεγχο HRR και MMR.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und Hinweis auf biallelische Inaktivierung; pMMR/MSS. Der BRCA2-Befund eröffnet einen PARP-relevanten Therapiekontext gemäß aktueller Indikation/Vorbehandlung. Die Tumoranalyse unterscheidet somatisch und Keimbahn nicht sicher; wegen BRCA2 und Familienanamnese ist eine separate humangenetische Keimbahnabklärung angezeigt. Ein HRD-Score ist kein notwendiger Ersatz für diese gen-spezifische Prostata-Diagnostik.":"mCRPC με παθογόνο loss-of-function αλλοίωση BRCA2 και ενδείξεις συμβατές με διαλληλική αδρανοποίηση· pMMR/MSS. Το εύρημα BRCA2 ανοίγει θεραπευτικό πλαίσιο σχετικό με PARP σύμφωνα με την τρέχουσα ένδειξη/προηγούμενη θεραπεία. Ο έλεγχος όγκου δεν διαχωρίζει αξιόπιστα σωματική από βλαστική προέλευση· λόγω BRCA2 και οικογενειακού ιστορικού ενδείκνυται ξεχωριστός γενετικός έλεγχος βλαστικής σειράς. Ένα HRD score δεν είναι αναγκαίο υποκατάστατο αυτής της γονιδιο-ειδικής διάγνωσης προστάτη.","Teilbefund: HRR/BRCA, MMR/MSI und Keimbahnfrage müssen getrennt beantwortet werden. Ein tumor-only BRCA2-Befund kann therapeutisch relevant sein, sagt aber nicht automatisch, ob die Variante vererbt ist.":"Μερικό αποτέλεσμα: HRR/BRCA, MMR/MSI και το ερώτημα βλαστικής σειράς πρέπει να απαντηθούν ξεχωριστά. Ένα tumor-only εύρημα BRCA2 μπορεί να είναι θεραπευτικά σημαντικό, αλλά δεν δείχνει αυτόματα αν η παραλλαγή είναι κληρονομούμενη.","BRCA2 im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen":"Εντάξτε το BRCA2 στο mCRPC ως γονιδιο-ειδικό πλαίσιο βιοδείκτη PARP","pMMR/MSS als fehlenden MMR/MSI-basierten IO-Selektionsbefund kommunizieren":"Αναφέρετε pMMR/MSS ως απουσία ευρήματος επιλογής IO βάσει MMR/MSI","Tumor-BRCA2 nicht mit Keimbahn gleichsetzen; Humangenetik empfehlen":"Μην εξισώνετε tumor BRCA2 με βλαστική σειρά· συστήστε γενετική συμβουλευτική","HRD-Score nicht als universellen oder zwingenden Prostata-PARP-Selektionsmarker darstellen":"Μην παρουσιάζετε το HRD score ως καθολικό ή υποχρεωτικό δείκτη επιλογής PARP στον προστάτη","Therapieempfehlung an aktuelle Zulassung, Vorbehandlung und klinischen Kontext binden":"Συνδέστε τη θεραπευτική σύσταση με την τρέχουσα έγκριση, την προηγούμενη θεραπεία και το κλινικό πλαίσιο","Optimale Lösung: BRCA2 im Tumor als therapeutisch relevanten mCRPC-Biomarker erkennen, pMMR/MSS separat für den IO-Kontext dokumentieren, HRD-Score nicht aus dem Ovarial-Workflow übertragen und die Keimbahnfrage wegen möglicher Familienrelevanz eigenständig humangenetisch klären.":"Βέλτιστη λύση: αναγνωρίστε το tumor BRCA2 ως θεραπευτικά σημαντικό βιοδείκτη mCRPC, τεκμηριώστε ξεχωριστά pMMR/MSS για το πλαίσιο IO, μην μεταφέρετε το HRD score από το workflow ωοθηκών και διευκρινίστε ανεξάρτητα το ερώτημα βλαστικής σειράς μέσω γενετικής λόγω πιθανής οικογενειακής σημασίας.","Prostatakarzinom":"Καρκίνος προστάτη","mCRPC":"mCRPC","HRR":"HRR","MMR":"MMR","BRCA2 im mCRPC: therapeutisch relevant – aber ist es auch Keimbahn?":"BRCA2 στο mCRPC: θεραπευτικά σημαντικό – αλλά είναι και βλαστικής σειράς;","Molekularpathologie / Uro-Onkologie / MTB":"Μοριακή παθολογία / Ουρο-ογκολογία / MTB","BRCA1/2- und HRR-Alterationen im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen.":"Εντάξτε τις αλλοιώσεις BRCA1/2 και HRR στο mCRPC ως γονιδιο-ειδικό πλαίσιο βιοδείκτη PARP.","Somatische und Keimbahn-BRCA-Alterationen therapeutisch und hereditär getrennt betrachten.":"Αντιμετωπίστε ξεχωριστά τις σωματικές και βλαστικές αλλοιώσεις BRCA από θεραπευτική και κληρονομική σκοπιά.","MMR/MSI als eigenständigen IO-Biomarkerblock prüfen.":"Αξιολογήστε MMR/MSI ως ανεξάρτητο block βιοδείκτη IO.","Einen ovarialkarzinomtypischen HRD-Genomic-Scar-Score nicht als universellen Pflichtmarker auf das Prostatakarzinom übertragen.":"Μην μεταφέρετε ένα HRD genomic-scar score τύπου καρκίνου ωοθηκών στον καρκίνο προστάτη ως καθολικό υποχρεωτικό δείκτη.","Familienanamnese und humangenetische Weiterleitung in die MTB-Empfehlung integrieren.":"Ενσωματώστε το οικογενειακό ιστορικό και την παραπομπή στη γενετική στη σύσταση MTB.","Das Tumorpanel meldet eine pathogene BRCA2-Frameshift-Variante mit VAF 58 % und Hinweis auf Verlust des zweiten Allels. Im MTB heißt es sofort: 'Dann ist das erblich – und wir brauchen noch einen HRD-Score, bevor PARP möglich ist.' Der Fall ist ideal, um zwei häufige Ebenenfehler gleichzeitig zu korrigieren.":"Το tumor panel αναφέρει παθογόνο frameshift παραλλαγή BRCA2 με VAF 58% και ένδειξη απώλειας του δεύτερου αλληλίου. Στο MTB ακούγεται αμέσως: «Άρα είναι κληρονομικό – και χρειαζόμαστε ακόμη HRD score πριν από PARP.» Η περίπτωση είναι ιδανική για τη διόρθωση δύο συχνών σφαλμάτων κατηγοριοποίησης ταυτόχρονα.","69-jähriger Patient mit mCRPC und Progress nach neuem hormonellem Wirkstoff. Eine Lebermetastasenbiopsie steht für HRR/BRCA- und MMR/MSI-Diagnostik zur Verfügung. Gesucht wird eine Therapieempfehlung, die den tumorbezogenen BRCA2-Befund nutzt, die Keimbahnfrage separat löst und keine Ovarial-HRD-Logik auf die Prostata überträgt.":"Ασθενής 69 ετών με mCRPC και πρόοδο μετά από νεότερο ορμονικό παράγοντα. Διατίθεται βιοψία ηπατικής μετάστασης για έλεγχο HRR/BRCA και MMR/MSI. Στόχος είναι θεραπευτική σύσταση που αξιοποιεί το εύρημα tumor BRCA2, λύνει ξεχωριστά το ερώτημα βλαστικής σειράς και δεν μεταφέρει τη λογική HRD των ωοθηκών στον καρκίνο προστάτη.","Therapiesituation":"Θεραπευτικό πλαίσιο","mCRPC nach Progress unter neuem hormonellem Wirkstoff.":"mCRPC μετά από πρόοδο υπό νεότερο ορμονικό παράγοντα.","Der konkrete Therapiekontext macht BRCA1/2 besonders relevant.":"Το συγκεκριμένο θεραπευτικό πλαίσιο καθιστά τα BRCA1/2 ιδιαίτερα σημαντικά.","Hereditäre Ebene":"Κληρονομικό επίπεδο","Bruder mit Pankreas- und Vater mit Prostatakarzinom werden erst im Gespräch bekannt.":"Αδελφός με καρκίνο παγκρέατος και πατέρας με καρκίνο προστάτη αναφέρονται μόνο κατά τη συζήτηση.","Familienanamnese verstärkt die Keimbahnindikation, ersetzt aber keine Testung.":"Το οικογενειακό ιστορικό ενισχύει την ένδειξη για έλεγχο βλαστικής σειράς αλλά δεν τον αντικαθιστά.","IO-Ebene":"Επίπεδο IO","MMR/MSI ist zu Beginn unbekannt.":"Το MMR/MSI είναι άγνωστο αρχικά.","DNA-Reparaturdefekt allgemein ist nicht gleich dMMR/MSI-H.":"Ένα γενικό ελάττωμα επιδιόρθωσης DNA δεν ισοδυναμεί με dMMR/MSI-H.","Lebermetastase, ca. 55 % Tumor; DNA und IHC gut auswertbar.":"Ηπατική μετάσταση, περ. 55% όγκος· DNA και IHC αξιολογούνται καλά.","mCRPC mit Progress nach neuem hormonellem Wirkstoff.":"mCRPC με πρόοδο μετά από νεότερο ορμονικό παράγοντα.","Im Verlauf Pankreas- und Prostatakarzinom bei nahen Angehörigen berichtet.":"Κατά την πορεία αναφέρονται καρκίνος παγκρέατος και προστάτη σε στενούς συγγενείς.","Gen-spezifische HRR/BRCA-Diagnostik hat für die konkrete Frage höhere Priorität als ein unspezifischer HRD-Genomic-Scar-Score.":"Ο γονιδιο-ειδικός έλεγχος HRR/BRCA έχει υψηλότερη προτεραιότητα για αυτό το ερώτημα από ένα μη ειδικό HRD genomic-scar score.","Tumorgewebe enthält keine saubere Normalreferenz für die Keimbahnfrage.":"Ο ιστός όγκου δεν παρέχει καθαρή φυσιολογική αναφορά για το ερώτημα βλαστικής σειράς.","MMR/MSI benötigt eine eigene funktionelle/biomarkerbezogene Beurteilung.":"Το MMR/MSI απαιτεί δική του λειτουργική/βιοδεικτική αξιολόγηση.","Was ist der zentrale PARP-Biomarkerbefund in diesem Fall?":"Ποιο είναι το κεντρικό εύρημα βιοδείκτη PARP σε αυτή την περίπτωση;","Die pathogene BRCA2-Alteration im mCRPC ist der entscheidende gen-spezifische Biomarkerkontext; die konkrete Nutzung hängt von Vorbehandlung und aktueller Indikation ab.":"Η παθογόνος αλλοίωση BRCA2 στο mCRPC είναι το καθοριστικό γονιδιο-ειδικό πλαίσιο βιοδείκτη· η συγκεκριμένη χρήση εξαρτάται από προηγούμενη θεραπεία και τρέχουσα ένδειξη.","Nur ein positiver HRD-Score erlaubt eine PARP-Strategie.":"Μόνο θετικό HRD score επιτρέπει στρατηγική PARP.","pMMR ist der entscheidende PARP-Biomarker.":"Το pMMR είναι ο καθοριστικός βιοδείκτης PARP.","Eine VAF über 50 % ist allein der therapeutische Biomarker.":"VAF άνω του 50% από μόνο του είναι ο θεραπευτικός βιοδείκτης.","Bei mCRPC ist die gen-spezifische BRCA1/2-Alteration zentral; ein Ovarial-HRD-Score ist kein universeller Ersatz.":"Στο mCRPC, η γονιδιο-ειδική αλλοίωση BRCA1/2 είναι κεντρική· ένα ovarian HRD score δεν αποτελεί καθολικό υποκατάστατο.","Tumor-BRCA2, VAF 58 %, mit LOH: Ist damit die Keimbahnherkunft bewiesen?":"Tumor BRCA2, VAF 58%, με LOH: αποδεικνύεται έτσι βλαστική προέλευση;","Nein. Der Tumorbefund kann therapeutisch relevant sein, aber die Keimbahnherkunft muss aus einer geeigneten Normalprobe separat geklärt werden.":"Όχι. Το εύρημα όγκου μπορεί να είναι θεραπευτικά σημαντικό, αλλά η βλαστική προέλευση πρέπει να ελεγχθεί ξεχωριστά με κατάλληλο φυσιολογικό δείγμα.","Ja, VAF >50 % beweist Keimbahn.":"Ναι, VAF >50% αποδεικνύει βλαστική προέλευση.","Ja, LOH beweist immer eine erbliche Variante.":"Ναι, LOH αποδεικνύει πάντα κληρονομική παραλλαγή.","Nein, Tumorvarianten können grundsätzlich nie Keimbahn sein.":"Όχι, οι παραλλαγές όγκου δεν μπορούν ποτέ να είναι βλαστικές.","Tumor-only-NGS trennt somatische und Keimbahnherkunft nicht sicher.":"Το tumor-only NGS δεν μπορεί να διαχωρίσει αξιόπιστα σωματική από βλαστική προέλευση.","Reicht eine HRR/BRCA-Alteration als Begründung für eine MMR/MSI-basierte Immuntherapie?":"Αρκεί μια αλλοίωση HRR/BRCA για αιτιολόγηση ανοσοθεραπείας βάσει MMR/MSI;","Nein. MMR/MSI ist ein separater Biomarkerblock; hier zeigt pMMR/MSS keinen spezifischen MSI-basierten IO-Kontext.":"Όχι. Το MMR/MSI είναι ξεχωριστό block βιοδείκτη· εδώ pMMR/MSS δεν παρέχει ειδικό IO πλαίσιο βάσει MSI.","Ja. Jede DNA-Reparaturmutation bedeutet immunogen und ICI-sensitiv.":"Ναι. Κάθε μετάλλαξη επιδιόρθωσης DNA σημαίνει ανοσογονικό και ευαίσθητο σε ICI.","BRCA2 ist funktionell gleichbedeutend mit MSI-H.":"Το BRCA2 είναι λειτουργικά ισοδύναμο με MSI-H.","Nur PD-L1 kann die Frage beantworten.":"Μόνο το PD-L1 μπορεί να απαντήσει στο ερώτημα.","HRR und MMR sind unterschiedliche Reparaturachsen mit unterschiedlichen Biomarkerfolgen.":"HRR και MMR είναι διαφορετικοί μηχανισμοί επιδιόρθωσης με διαφορετικές βιοδεικτικές συνέπειες.","Welche Rolle sollte der HRD-Score hier spielen?":"Ποιος πρέπει να είναι ο ρόλος του HRD score εδώ;","Nicht als Pflicht- oder Ersatzmarker: gen-spezifische BRCA/HRR-Diagnostik ist für diesen Prostatafall entscheidender.":"Όχι ως υποχρεωτικός ή υποκατάστατος δείκτης: η γονιδιο-ειδική διάγνωση BRCA/HRR είναι πιο καθοριστική σε αυτή την περίπτωση προστάτη.","Zwingend vor jeder PARP-Diskussion.":"Υποχρεωτικό πριν από κάθε συζήτηση PARP.","Er ersetzt die Keimbahnabklärung.":"Αντικαθιστά τον έλεγχο βλαστικής σειράς.","Er entscheidet primär über Immuntherapie.":"Καθορίζει πρωτίστως την ανοσοθεραπεία.","Der Ovarial-HRD-Workflow darf nicht unkritisch auf mCRPC übertragen werden.":"Το ovarian HRD workflow δεν πρέπει να μεταφέρεται άκριτα στο mCRPC.","Ordnen Sie BRCA2, MMR/MSI und die Keimbahnfrage beim mCRPC so ein, dass die therapeutische Relevanz des Tumorbefunds genutzt wird, ohne die hereditäre Herkunft zu behaupten oder einen HRD-Score unnötig zur Voraussetzung zu machen.":"Εντάξτε BRCA2, MMR/MSI και το ερώτημα βλαστικής σειράς στο mCRPC έτσι ώστε να αξιοποιείται η θεραπευτική σημασία του ευρήματος όγκου χωρίς να δηλώνεται κληρονομική προέλευση ή να τίθεται άσκοπα HRD score ως προϋπόθεση.","Validierte HRR/BRCA-Diagnostik am Tumor durchführen.":"Διενεργήστε επικυρωμένο tumor HRR/BRCA testing.","Pathogene BRCA2-Loss-of-function-Alteration als relevanten mCRPC-Biomarkerkontext berichten.":"Αναφέρετε την παθογόνο loss-of-function αλλοίωση BRCA2 ως σημαντικό πλαίσιο βιοδείκτη mCRPC.","MMR-IHC/MSI separat prüfen: pMMR/MSS.":"Αξιολογήστε ξεχωριστά MMR IHC/MSI: pMMR/MSS.","PARP-Option an aktuelle Indikation, Vorbehandlung und klinische Eignung binden.":"Συνδέστε την επιλογή PARP με την τρέχουσα ένδειξη, την προηγούμενη θεραπεία και την κλινική καταλληλότητα.","Keimbahnherkunft aus Tumor-VAF/LOH nicht ableiten; Humangenetik/Normalprobe empfehlen.":"Μην συμπεραίνετε βλαστική προέλευση από tumor VAF/LOH· συστήστε γενετική/φυσιολογικό δείγμα.","HRD-Score nicht als universellen Pflichtmarker aus dem Ovarialkarzinom übernehmen.":"Μην υιοθετείτε το HRD score από τον καρκίνο ωοθηκών ως καθολικό υποχρεωτικό δείκτη.","Validiertes Tumor-BRCA/HRR-Panel statt Prostata-spezifischem Panel, sofern relevante HRR-Gene und Copy-number/Variantentypen ausreichend erfasst werden.":"Επικυρωμένο tumor BRCA/HRR panel αντί prostate-specific panel, εφόσον τα σχετικά γονίδια HRR και οι τύποι copy-number/variant καλύπτονται επαρκώς.","Breiteres validiertes Panel mit BRCA/HRR plus MSI, wenn Material und TAT vertretbar sind; funktionelle MMR-IHC kann ergänzen.":"Ευρύτερο επικυρωμένο panel με BRCA/HRR συν MSI εφόσον υλικό και TAT είναι αποδεκτά· λειτουργικό MMR IHC μπορεί να συμπληρώσει.","HRD-Score als Pflicht":"HRD score ως υποχρεωτικό","Überträgt einen entitätsspezifischen Ovarial-Workflow auf die Prostata.":"Μεταφέρει ένα entity-specific ovarian workflow στον καρκίνο προστάτη.","Tumor-BRCA = erblich":"Tumor BRCA = κληρονομικό","Tumor-only-NGS beweist keine Keimbahnherkunft.":"Το tumor-only NGS δεν αποδεικνύει βλαστική προέλευση.","BRCA = MSI/IO":"BRCA = MSI/IO","HRR und MMR sind verschiedene Reparaturwege und Biomarker.":"HRR και MMR είναι διαφορετικοί μηχανισμοί επιδιόρθωσης και βιοδείκτες.","Familienanamnese ignorieren":"Αγνόηση οικογενειακού ιστορικού","Ein möglicher Keimbahnbefund hat Konsequenzen für Patient und Angehörige.":"Ένα πιθανό εύρημα βλαστικής σειράς έχει συνέπειες για τον ασθενή και τους συγγενείς.","Therapie kann schon tumorbezogen relevant sein, Familienrelevanz bleibt trotzdem offen":"Η θεραπεία μπορεί ήδη να είναι σχετική σε επίπεδο όγκου ενώ η οικογενειακή σημασία παραμένει ανοιχτή","Die BRCA2-Loss-of-function-Alteration ist im mCRPC therapeutisch relevant, auch wenn sie somatisch sein könnte. Gleichzeitig macht die aktualisierte Familienanamnese eine Keimbahnabklärung besonders wichtig. MMR-IHC und MSI sind unauffällig. Der vermeintlich noch fehlende HRD-Score ist dagegen gar nicht der zentrale nächste Schritt.":"Η loss-of-function αλλοίωση BRCA2 είναι θεραπευτικά σημαντική στο mCRPC ακόμη κι αν μπορεί να είναι σωματική. Παράλληλα, το επικαιροποιημένο οικογενειακό ιστορικό καθιστά ιδιαίτερα σημαντικό τον έλεγχο βλαστικής σειράς. MMR IHC και MSI είναι χωρίς παθολογικά ευρήματα. Το υποτιθέμενο «ελλείπον» HRD score όμως δεν είναι καθόλου το κεντρικό επόμενο βήμα.","Der Fall trennt Therapiebiomarker und Hereditätsdiagnostik: dieselbe Variante kann für die Tumortherapie relevant sein, während ihre Herkunft für die Familie separat geklärt werden muss.":"Η περίπτωση διαχωρίζει τους θεραπευτικούς βιοδείκτες από την κληρονομική διάγνωση: η ίδια παραλλαγή μπορεί να είναι σημαντική για τη θεραπεία του όγκου, ενώ η προέλευσή της πρέπει να διευκρινιστεί ξεχωριστά για την οικογένεια.","BRCA2 genutzt, Keimbahn sauber getrennt":"Αξιοποίηση BRCA2, καθαρός διαχωρισμός βλαστικής σειράς","Pathogene BRCA2-Loss-of-function-Alteration im Tumor mit Hinweis auf biallelische Inaktivierung; pMMR/MSS. PARP-relevanter mCRPC-Kontext gemäß aktueller Indikation/Vorbehandlung; separate humangenetische Keimbahnabklärung empfohlen. HRD-Score nicht als Pflichtmarker benötigt.":"Παθογόνος loss-of-function αλλοίωση BRCA2 στον όγκο με ενδείξεις συμβατές με διαλληλική αδρανοποίηση· pMMR/MSS. Πλαίσιο mCRPC σχετικό με PARP σύμφωνα με τρέχουσα ένδειξη/προηγούμενη θεραπεία· συστήνεται ξεχωριστός γενετικός έλεγχος βλαστικής σειράς. HRD score δεν απαιτείται ως υποχρεωτικός δείκτης.","Therapie-, IO- und Hereditätsebene korrekt getrennt.":"Σωστός διαχωρισμός θεραπευτικού, IO και κληρονομικού επιπέδου.","BRCA2 erkannt, Heredität offen":"BRCA2 αναγνωρίστηκε, κληρονομικότητα ανοιχτή","BRCA2 wird therapeutisch korrekt erkannt, aber Keimbahnabklärung/Familienrelevanz nicht adressiert.":"Το BRCA2 αναγνωρίζεται σωστά θεραπευτικά, αλλά δεν αντιμετωπίζεται ο έλεγχος βλαστικής σειράς/η οικογενειακή σημασία.","Klinisch wichtige zweite Ebene fehlt.":"Λείπει ένα κλινικά σημαντικό δεύτερο επίπεδο.","Ovarial-Workflow kopiert":"Αντιγραφή ovarian workflow","PARP-Entscheidung wird von einem HRD-Score abhängig gemacht und Tumor-BRCA2 zugleich als sicher erblich bezeichnet.":"Η απόφαση PARP εξαρτάται από HRD score ενώ ταυτόχρονα το tumor BRCA2 χαρακτηρίζεται σίγουρα κληρονομικό.","Zwei entitätsspezifische Fehlübertragungen.":"Δύο λανθασμένες entity-specific μεταφορές.","Pathogene BRCA2-Variante im Tumor":"Παθογόνος παραλλαγή BRCA2 στον όγκο","PARP-Eignung nach aktueller Indikation/Vorbehandlung prüfen und parallel humangenetische Beratung veranlassen.":"Αξιολογήστε την καταλληλότητα για PARP σύμφωνα με τρέχουσα ένδειξη/προηγούμενη θεραπεία και οργανώστε παράλληλα γενετική συμβουλευτική.","Therapieentscheidung und Familienabklärung laufen koordiniert, aber diagnostisch getrennt.":"Η θεραπευτική απόφαση και η οικογενειακή διερεύνηση προχωρούν συντονισμένα αλλά διαγνωστικά ξεχωριστά.","Keinen MSI/MMR-basierten IO-Biomarker behaupten; andere klinische IO-Indikationen nur separat bewerten.":"Μην ισχυρίζεστε βιοδείκτη IO βάσει MSI/MMR· άλλες κλινικές ενδείξεις IO να αξιολογούνται μόνο ξεχωριστά.","DNA-Reparatur wird nicht pauschal mit Immuntherapie gleichgesetzt.":"Η επιδιόρθωση DNA δεν εξισώνεται γενικά με ανοσοθεραπεία.","BRCA1/2 ist im mCRPC ein gen-spezifischer, therapeutisch relevanter Biomarkerkontext.":"BRCA1/2 αποτελεί γονιδιο-ειδικό, θεραπευτικά σημαντικό πλαίσιο βιοδείκτη στο mCRPC.","Somatische und Keimbahn-BRCA-Alterationen sind für Therapie und Familie unterschiedliche Ebenen.":"Οι σωματικές και βλαστικές αλλοιώσεις BRCA αποτελούν διαφορετικά επίπεδα για θεραπεία και οικογένεια.","Tumor-VAF/LOH beweist die Keimbahn nicht.":"Tumor VAF/LOH δεν αποδεικνύει βλαστική προέλευση.","MMR/MSI muss unabhängig von HRR beurteilt werden.":"Το MMR/MSI πρέπει να αξιολογείται ανεξάρτητα από HRR.","Ein HRD-Genomic-Scar-Score ist kein universeller Pflichtmarker für PARP über Tumorentitäten hinweg.":"Ένα HRD genomic-scar score δεν είναι καθολικός υποχρεωτικός δείκτης για PARP σε όλες τις οντότητες όγκων.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und pMMR/MSS. BRCA2 ist tumorbezogen PARP-relevant gemäß aktueller Indikation/Vorbehandlung. Die Keimbahnherkunft ist nicht aus Tumor-VAF oder LOH ableitbar; wegen Befund und Familienanamnese Humangenetik empfehlen. Kein obligatorischer Ovarial-HRD-Score.":"mCRPC με παθογόνο loss-of-function αλλοίωση BRCA2 και pMMR/MSS. Το BRCA2 είναι σε επίπεδο όγκου σχετικό με PARP σύμφωνα με τρέχουσα ένδειξη/προηγούμενη θεραπεία. Η βλαστική προέλευση δεν συνάγεται από tumor VAF ή LOH· συστήστε γενετική λόγω του ευρήματος και του οικογενειακού ιστορικού. Χωρίς υποχρεωτικό ovarian HRD score.","BRCA2 tumorbezogen korrekt genutzt":"Σωστή αξιοποίηση tumor BRCA2","MMR/MSI separat bewertet":"MMR/MSI αξιολογήθηκε ξεχωριστά","Keimbahn nicht behauptet":"Δεν δηλώνεται βλαστική προέλευση","HRD-Score nicht zum Pflichtmarker gemacht":"HRD score δεν καθίσταται υποχρεωτικό","Warum kann derselbe BRCA2-Befund therapeutisch nutzbar sein, obwohl die Keimbahnherkunft noch offen ist?":"Γιατί μπορεί το ίδιο εύρημα BRCA2 να αξιοποιηθεί θεραπευτικά ενώ η βλαστική προέλευση παραμένει αδιευκρίνιστη;","Welche Proben eignen sich zur Keimbahnklärung?":"Ποια δείγματα είναι κατάλληλα για διευκρίνιση της βλαστικής κατάστασης;","Warum sind HRD-Genomic-Scar-Tests nicht automatisch zwischen Tumorentitäten übertragbar?":"Γιατί τα HRD genomic-scar tests δεν μεταφέρονται αυτόματα μεταξύ οντοτήτων όγκων;","BRCA2 ist therapeutisch relevant, ohne dass die Keimbahn bereits geklärt ist":"Το BRCA2 είναι θεραπευτικά σημαντικό χωρίς να έχει ήδη διευκρινιστεί η βλαστική κατάσταση","Therapiebiomarker und Hereditätsstatus sind getrennte Ebenen":"Θεραπευτικός βιοδείκτης και κληρονομική κατάσταση είναι ξεχωριστά επίπεδα","HRR/BRCA → MMR/MSI separat → PARP-Kontext → Keimbahnklärung":"HRR/BRCA → MMR/MSI ξεχωριστά → πλαίσιο PARP → διευκρίνιση βλαστικής σειράς","Therapieassoziierte MDS/AML nach DNA-schädigender Therapie → Instabilität als Chance und Risiko einordnen":"Θεραπεία-σχετιζόμενο MDS/AML μετά από DNA-damaging θεραπεία → ένταξη της αστάθειας ως ευκαιρίας και κινδύνου","Therapieassoziierte MDS/AML nach D…":"Θεραπεία-σχετιζόμενο MDS/AML μετά από D…","Hämatologie / interdisziplinäres Tumorboard":"Αιματολογία / Διεπιστημονικό ογκολογικό συμβούλιο","67-jährige Patientin mit neu aufgetretener Pancytopenie acht Jahre nach Behandlung eines Mammakarzinoms mit zytotoxischer Chemotherapie und Radiotherapie.":"Ασθενής 67 ετών με νεοεμφανιζόμενη πανκυτταροπενία οκτώ χρόνια μετά από θεραπεία καρκίνου μαστού με κυτταροτοξική χημειοθεραπεία και ακτινοθεραπεία.","Wie werden Morphologie, Zytogenetik, molekulares Profil und die frühere zytotoxische Therapie zu einer belastbaren Diagnose- und Risikoeinschätzung integriert?":"Πώς πρέπει να ενσωματωθούν μορφολογία, κυτταρογενετική, μοριακό προφίλ και προηγούμενη κυτταροτοξική θεραπεία σε αξιόπιστη διάγνωση και εκτίμηση κινδύνου;","Therapiebeginn nach Abschluss der hämatologischen Klassifikation.":"Η θεραπεία ξεκινά μετά την ολοκλήρωση της αιματολογικής ταξινόμησης.","Anthrazyklin-/Cyclophosphamid-haltige Chemotherapie und Bestrahlung vor acht Jahren.":"Χημειοθεραπεία με ανθρακυκλίνη/κυκλοφωσφαμίδη και ακτινοθεραπεία πριν από οκτώ χρόνια.","Aktuell":"Τρέχοντα ευρήματα","Hb 8,4 g/dl, Thrombozyten 46/nl, Neutrophile 0,7/nl; peripher 9 % Blasten.":"Hb 8,4 g/dl, αιμοπετάλια 46/nl, ουδετερόφιλα 0,7/nl· 9% βλάστες περιφερικά.","Knochenmark":"Μυελός των οστών","27 % myeloische Blasten, ausgeprägte Dysplasie.":"27% μυελοειδείς βλάστες, έντονη δυσπλασία.","Die Vorgeschichte wird allein zur Diagnose 'therapieassoziierte AML' gemacht oder ein einzelner DNMT3A-/TET2-/ASXL1-Befund wird ohne Morphologie/Zytogenetik als Neoplasiebeweis interpretiert.":"Το ιστορικό μόνο χρησιμοποιείται για διάγνωση «therapy-related AML» ή ένα μεμονωμένο εύρημα DNMT3A/TET2/ASXL1 ερμηνεύεται ως απόδειξη νεοπλασίας χωρίς μορφολογία/κυτταρογενετική.","Morphologie + Vorbefunde":"Μορφολογία + προϋπάρχοντα ευρήματα","Hyperzellulär, 27 % Blasten, dysplastische Granulo- und Megakaryopoese.":"Υπερκυτταρικός, 27% βλάστες, δυσπλαστική κοκκιοποίηση και μεγακαρυοποίηση.","Zytogenetik":"Κυτταρογενετική","Komplexer Karyotyp mit -5/del(5q), -7 und 17p-Verlust.":"Σύνθετος καρυότυπος με -5/del(5q), -7 και απώλεια 17p.","Akute myeloische Neoplasie mit hochriskanter Genominstabilität; frühere zytotoxische Exposition muss als qualifizierender Kontext integriert werden.":"Οξεία μυελοειδής νεοπλασία με υψηλού κινδύνου γονιδιωματική αστάθεια· η προηγούμενη κυτταροτοξική έκθεση πρέπει να ενσωματωθεί ως qualifying context.","Welche Rolle spielt das molekulare Profil – und was darf daraus gerade nicht abgeleitet werden?":"Ποιος είναι ο ρόλος του μοριακού προφίλ – και τι ακριβώς δεν πρέπει να συναχθεί από αυτό;","EDTA-Knochenmarkaspirat plus Trepanobiopsie.":"EDTA αναρρόφηση μυελού οστών συν trephine biopsy.","Tumorzellanteil":"Ποσοστό νεοπλασματικών κυττάρων","Blasten ca. 27 %; NGS aus Knochenmark geeignet.":"Βλάστες περ. 27%· ο μυελός οστών είναι κατάλληλος για NGS.","Vorbefunde":"Προϋπάρχοντα ευρήματα","Morphologie und Zytogenetik liegen bereits vor und dürfen nicht durch NGS ersetzt werden.":"Μορφολογία και κυτταρογενετική είναι ήδη διαθέσιμες και δεν πρέπει να αντικατασταθούν από NGS.","Ein Pan-Tumorpanel mit TMB/MSI wäre für die konkrete myeloische Klassifikationsfrage Low Value; das fokussierte hämatologische Panel ist näher an der Fragestellung.":"Ένα pan-tumor panel με TMB/MSI θα είχε χαμηλή αξία για το συγκεκριμένο ερώτημα μυελοειδούς ταξινόμησης· ένα στοχευμένο αιματολογικό panel είναι πιο κοντά στο κλινικό ερώτημα.","Myeloischer Molekularkontext":"Μοριακό πλαίσιο μυελοειδούς νόσου","Hämatologisches NGS":"Αιματολογικό NGS","TP53 p.R273H mit VAF 43 % sowie DNMT3A p.R882H mit VAF 4 %. Im Kontext von 17p-Verlust und komplexem Karyotyp ist TP53 Teil der hochriskanten Neoplasie; die niedrigfrequente DNMT3A-Alteration allein wäre dagegen kein Beweis für AML und kann klonale Hämatopoese repräsentieren.":"TP53 p.R273H με VAF 43% και DNMT3A p.R882H με VAF 4%. Στο πλαίσιο απώλειας 17p και σύνθετου καρυοτύπου, το TP53 αποτελεί μέρος της υψηλού κινδύνου νεοπλασίας· η χαμηλής συχνότητας αλλοίωση DNMT3A από μόνη της δεν θα αποδείκνυε AML και μπορεί να αντιπροσωπεύει κλωνική αιμοποίηση.","Zusätzliche solide-tumororientierte TMB/MSI-/Pan-Cancer-Information beantwortet die zentrale myeloische Klassifikations- und Risikofrage nicht besser und erzeugt unnötige Nebenbefunde.":"Πρόσθετη TMB/MSI/pan-cancer πληροφορία προσανατολισμένη σε συμπαγείς όγκους δεν απαντά καλύτερα στο κεντρικό ερώτημα μυελοειδούς ταξινόμησης και κινδύνου και δημιουργεί περιττά παρεμπίπτοντα ευρήματα.","Morphologie":"Μορφολογία","27 % myeloische Blasten mit Dysplasie.":"27% μυελοειδείς βλάστες με δυσπλασία.","Exposition":"Έκθεση","Zytotoxische Chemotherapie/Radiotherapie acht Jahre zuvor.":"Κυτταροτοξική χημειοθεραπεία/ακτινοθεραπεία οκτώ χρόνια νωρίτερα.","Akute myeloische Neoplasie mit TP53-Alteration und komplexer Zytogenetik nach vorausgegangener zytotoxischer Therapie. Die frühere Therapie ist ein wichtiger qualifizierender klinischer Kontext, die Erkrankung wird jedoch primär aus Morphologie und genetischen Merkmalen klassifiziert. Der TP53/komplexe-Karyotyp-Kontext spricht für ungünstige Biologie. Eine niedrigfrequente DNMT3A-Alteration allein wäre nicht ausreichend, um die Neoplasie zu definieren. 'Genomische Instabilität' ist hier kein pauschales Target- oder Immuntherapiesignal.":"Οξεία μυελοειδής νεοπλασία με αλλοίωση TP53 και σύνθετη κυτταρογενετική μετά από προηγούμενη κυτταροτοξική θεραπεία. Η προηγούμενη θεραπεία είναι σημαντικό qualifying κλινικό πλαίσιο, αλλά η νόσος ταξινομείται πρωτίστως βάσει μορφολογίας και γενετικών χαρακτηριστικών. Το πλαίσιο TP53/σύνθετου καρυοτύπου υποδηλώνει δυσμενή βιολογία. Μια χαμηλής συχνότητας αλλοίωση DNMT3A μόνη της δεν αρκεί για να ορίσει τη νεοπλασία. Η «γονιδιωματική αστάθεια» δεν αποτελεί εδώ γενικό σήμα target ή ανοσοθεραπείας.","Teilbefund: Die frühere zytotoxische Therapie erhöht die Plausibilität eines post-zytotoxischen/therapiebezogenen Kontextes, ersetzt aber nicht die aktuelle morphologische und genetische Klassifikation. CHIP-typische Varianten dürfen nicht isoliert überinterpretiert werden.":"Μερικό αποτέλεσμα: η προηγούμενη κυτταροτοξική θεραπεία αυξάνει την πιθανότητα post-cytotoxic/therapy-related πλαισίου, αλλά δεν αντικαθιστά την τρέχουσα μορφολογική και γενετική ταξινόμηση. CHIP-τυπικές παραλλαγές δεν πρέπει να υπερερμηνεύονται μεμονωμένα.","Morphologie/Genetik priorisieren und frühere zytotoxische Therapie als qualifizierenden Kontext integrieren":"Προτεραιότητα σε μορφολογία/γενετική και ενσωμάτωση προηγούμενης κυτταροτοξικής θεραπείας ως qualifying context","TP53 plus komplexen Karyotyp als hochriskante Biologie erkennen":"Αναγνωρίστε TP53 συν σύνθετο καρυότυπο ως υψηλού κινδύνου βιολογία","Niedrigfrequentes DNMT3A nicht allein als AML-Beweis interpretieren":"Μην ερμηνεύετε χαμηλής συχνότητας DNMT3A μόνο του ως απόδειξη AML","Genominstabilität nicht automatisch als Target-/TMB-/IO-Chance verkaufen":"Μην παρουσιάζετε αυτόματα τη γονιδιωματική αστάθεια ως ευκαιρία target/TMB/IO","Hämatologische Klassifikation und Risikostratifikation nicht durch ein solides Pan-Panel ersetzen":"Μην αντικαθιστάτε αιματολογική ταξινόμηση και risk stratification με pan-panel συμπαγών όγκων","Optimale Lösung: AML/myeloische Neoplasie aus Morphologie und Genetik klassifizieren; die frühere zytotoxische Therapie als qualifizierenden Kontext dokumentieren; TP53 plus komplexe Zytogenetik als ungünstige Biologie einordnen; niedrigfrequentes DNMT3A als potenziellen CH-Klon nicht überbewerten.":"Βέλτιστη λύση: ταξινομήστε AML/μυελοειδή νεοπλασία από μορφολογία και γενετική· τεκμηριώστε προηγούμενη κυτταροτοξική θεραπεία ως qualifying context· εντάξτε TP53 συν σύνθετη κυτταρογενετική ως δυσμενή βιολογία· μην υπερεκτιμάτε χαμηλής συχνότητας DNMT3A, που μπορεί να αντιπροσωπεύει κλώνο CH.","AML":"AML","post cytotoxic therapy":"μετά από κυτταροτοξική θεραπεία","TP53":"TP53","complex karyotype":"σύνθετος καρυότυπος","clonal hematopoiesis":"κλωνική αιμοποίηση","genomic instability":"γονιδιωματική αστάθεια","Nach zytotoxischer Therapie: TP53, komplexer Karyotyp und die Falle 'Genominstabilität = Target'":"Μετά από κυτταροτοξική θεραπεία: TP53, σύνθετος καρυότυπος και η παγίδα «γονιδιωματική αστάθεια = target»","Molekularpathologie / Hämatologie / Translation":"Μοριακή παθολογία / Αιματολογία / Μετάφραση","Eine myeloische Neoplasie nach zytotoxischer Therapie primär aus aktueller Morphologie und Genetik klassifizieren und die frühere Exposition als qualifizierenden Kontext integrieren.":"Ταξινομήστε μυελοειδή νεοπλασία μετά από κυτταροτοξική θεραπεία πρωτίστως από τρέχουσα μορφολογία και γενετική και ενσωματώστε την προηγούμενη έκθεση ως qualifying context.","TP53 plus komplexe Zytogenetik als hochriskante Biologie erkennen.":"Αναγνωρίστε TP53 συν σύνθετη κυτταρογενετική ως υψηλού κινδύνου βιολογία.","CHIP-typische Varianten wie niedrigfrequentes DNMT3A nicht isoliert als AML-Beweis interpretieren.":"Μην ερμηνεύετε CHIP-τυπικές παραλλαγές όπως χαμηλής συχνότητας DNMT3A μεμονωμένα ως απόδειξη AML.","Das biologische Konzept 'genomische Instabilität' nicht automatisch in einen therapeutischen Target- oder Immuntherapiemarker übersetzen.":"Μην μεταφράζετε αυτόματα τη βιολογική έννοια «γονιδιωματική αστάθεια» σε θεραπευτικό target ή δείκτη ανοσοθεραπείας.","Solide-tumororientierte Pan-Cancer-Tests nicht unkritisch auf eine myeloische Fragestellung übertragen.":"Μην μεταφέρετε άκριτα pan-cancer tests προσανατολισμένα σε συμπαγείς όγκους σε μυελοειδές ερώτημα.","Acht Jahre nach Chemotherapie und Bestrahlung wegen Mammakarzinoms entwickelt die Patientin eine Pancytopenie. Das Knochenmark zeigt 27 % Blasten, der Karyotyp ist komplex. Im NGS erscheinen TP53 mit hoher und DNMT3A mit sehr niedriger VAF. Im Board fallen zwei schnelle Erklärungen: 'Die alte Chemotherapie hat die AML verursacht' und 'viel Genominstabilität bedeutet vielleicht viel Target-/IO-Potenzial'. Beide Aussagen müssen präziser werden.":"Οκτώ χρόνια μετά από χημειοθεραπεία και ακτινοθεραπεία για καρκίνο μαστού, η ασθενής αναπτύσσει πανκυτταροπενία. Ο μυελός δείχνει 27% βλάστες και ο καρυότυπος είναι σύνθετος. Το NGS δείχνει TP53 με υψηλή VAF και DNMT3A με πολύ χαμηλή VAF. Στο board προκύπτουν δύο γρήγορες εξηγήσεις: «Η παλιά χημειοθεραπεία προκάλεσε την AML» και «πολλή γονιδιωματική αστάθεια ίσως σημαίνει πολύ target/IO δυναμικό». Και οι δύο δηλώσεις χρειάζονται μεγαλύτερη ακρίβεια.","67-jährige Patientin mit akuter myeloischer Neoplasie nach vorausgegangener zytotoxischer Therapie. Morphologie und komplexe Zytogenetik stehen bereits fest; das molekulare Panel soll die biologische Einordnung ergänzen. Ziel ist nicht, aus einer Exposition oder einem Einzelgen allein eine Diagnose zu konstruieren, sondern die aktuelle Erkrankung korrekt zu klassifizieren und die Genominstabilität klinisch realistisch zu bewerten.":"Ασθενής 67 ετών με οξεία μυελοειδή νεοπλασία μετά από προηγούμενη κυτταροτοξική θεραπεία. Μορφολογία και σύνθετη κυτταρογενετική είναι ήδη τεκμηριωμένες· το μοριακό panel πρέπει να συμπληρώσει τη βιολογική ταξινόμηση. Στόχος δεν είναι να κατασκευαστεί διάγνωση από μία έκθεση ή ένα γονίδιο, αλλά να ταξινομηθεί σωστά η τρέχουσα νόσος και να αξιολογηθεί κλινικά ρεαλιστικά η γονιδιωματική αστάθεια.","27 % myeloische Blasten mit deutlicher Dysplasie.":"27% μυελοειδείς βλάστες με έντονη δυσπλασία.","Die aktuelle Neoplasie ist morphologisch manifest; NGS ersetzt diese Ebene nicht.":"Η τρέχουσα νεοπλασία είναι μορφολογικά έκδηλη· το NGS δεν αντικαθιστά αυτό το επίπεδο.","Mehrere strukturelle Verluste sprechen für hochriskante klonale Genominstabilität.":"Πολλαπλές δομικές απώλειες υποδηλώνουν υψηλού κινδύνου κλωνική γονιδιωματική αστάθεια.","Zytotoxische Chemotherapie und Radiotherapie acht Jahre zuvor.":"Κυτταροτοξική χημειοθεραπεία και ακτινοθεραπεία οκτώ χρόνια νωρίτερα.","Wichtiger diagnostischer Qualifier/Kontext, aber nicht die alleinige Krankheitsdefinition.":"Σημαντικό diagnostic qualifier/context, αλλά όχι ο μοναδικός ορισμός της νόσου.","Blutbild":"Γενική αίματος","Pancytopenie, peripher 9 % Blasten.":"Πανκυτταροπενία, 9% βλάστες περιφερικά.","27 % Blasten, dysplastische Myelopoese.":"27% βλάστες, δυσπλαστική μυελοποίηση.","Karyotyp":"Καρυότυπος","Komplex mit -5/del(5q), -7 und 17p-Verlust.":"Σύνθετος με -5/del(5q), -7 και απώλεια 17p.","Knochenmark ist für fokussiertes hämatologisches NGS geeignet.":"Ο μυελός οστών είναι κατάλληλος για στοχευμένο αιματολογικό NGS.","Morphologie und Zytogenetik sind bereits hochinformativ und dürfen nicht durch einen molekularen Einzelmarker ersetzt werden.":"Μορφολογία και κυτταρογενετική είναι ήδη πολύ πληροφοριακές και δεν πρέπει να αντικατασταθούν από έναν μόνο μοριακό δείκτη.","Ein solides Pan-Cancer-Panel mit TMB/MSI erzeugt für diese Fragestellung eher Nebeninformation als klinischen Mehrwert.":"Ένα pan-cancer panel συμπαγών όγκων με TMB/MSI θα παρήγαγε περισσότερο παρεμπίπτοντα δεδομένα παρά κλινική αξία για αυτό το ερώτημα.","Wie sollte die frühere zytotoxische Therapie diagnostisch verwendet werden?":"Πώς πρέπει να χρησιμοποιηθεί διαγνωστικά η προηγούμενη κυτταροτοξική θεραπεία;","Als wichtiger qualifizierender Kontext einer anhand aktueller morphologischer/genetischer Merkmale klassifizierten myeloischen Neoplasie.":"Ως σημαντικό qualifying context για μυελοειδή νεοπλασία ταξινομημένη βάσει τρεχόντων μορφολογικών/γενετικών χαρακτηριστικών.","Allein die Exposition definiert unabhängig von aktuellen Befunden automatisch die AML-Untergruppe.":"Η έκθεση μόνη της ορίζει αυτόματα την υποομάδα AML ανεξάρτητα από τα τρέχοντα ευρήματα.","Die frühere Therapie darf in der Diagnose überhaupt nicht erwähnt werden.":"Η προηγούμενη θεραπεία δεν πρέπει να αναφέρεται καθόλου στη διάγνωση.","Sie ist primär ein therapeutischer Target-Biomarker.":"Είναι πρωτίστως θεραπευτικός target biomarker.","Moderne Klassifikation priorisiert die aktuelle Krankheitsbiologie; die Exposition wird als relevanter Kontext/Qualifier integriert.":"Η σύγχρονη ταξινόμηση δίνει προτεραιότητα στην τρέχουσα βιολογία της νόσου· η έκθεση ενσωματώνεται ως σχετικό context/qualifier.","Wie ist TP53 VAF 43 % zusammen mit 17p-Verlust und komplexem Karyotyp zu bewerten?":"Πώς πρέπει να αξιολογηθεί TP53 VAF 43% μαζί με απώλεια 17p και σύνθετο καρυότυπο;","Als Teil einer hochriskanten TP53-/komplex-karyotypischen Krankheitsbiologie, nicht als isolierter Einzelmarker.":"Ως μέρος υψηλού κινδύνου βιολογίας TP53/σύνθετου καρυοτύπου, όχι ως μεμονωμένος δείκτης.","Als einfacher Targetmarker mit erwartbar günstiger Prognose.":"Ως απλός target marker με αναμενόμενη ευνοϊκή πρόγνωση.","Sicher nur CHIP, weil TP53 auch in klonaler Hämatopoese vorkommen kann.":"Σίγουρα μόνο CHIP επειδή TP53 μπορεί επίσης να εμφανιστεί σε κλωνική αιμοποίηση.","Zytogenetik macht molekulare Befunde irrelevant.":"Η κυτταρογενετική καθιστά τα μοριακά ευρήματα άσχετα.","Genetischer Kontext und klonale Architektur sind entscheidend.":"Το γενετικό πλαίσιο και η κλωνική αρχιτεκτονική είναι καθοριστικά.","DNMT3A p.R882H liegt zusätzlich mit 4 % VAF vor. Was ist die beste Interpretation?":"Επιπλέον υπάρχει DNMT3A p.R882H με VAF 4%. Ποια είναι η καλύτερη ερμηνεία;","Ein niedrigfrequenter CH-Klon ist möglich; DNMT3A allein beweist weder AML noch erklärt es die gesamte hochriskante Erkrankung.":"Είναι πιθανός χαμηλής συχνότητας κλώνος CH· το DNMT3A μόνο του ούτε αποδεικνύει AML ούτε εξηγεί ολόκληρη την υψηλού κινδύνου νόσο.","DNMT3A definiert allein die AML.":"Το DNMT3A μόνο του ορίζει AML.","4 % VAF beweist eine Keimbahnmutation.":"VAF 4% αποδεικνύει βλαστική μετάλλαξη.","DNMT3A ist ein PARP-Biomarker.":"Το DNMT3A είναι βιοδείκτης PARP.","CHIP-typische Gene müssen im morphologischen und klonalen Kontext interpretiert werden.":"CHIP-τυπικά γονίδια πρέπει να ερμηνεύονται στο μορφολογικό και κλωνικό πλαίσιο.","Was bedeutet die ausgeprägte Genominstabilität therapeutisch?":"Τι σημαίνει θεραπευτικά η έντονη γονιδιωματική αστάθεια;","Sie erklärt aggressive klonale Evolution/Risikobiologie, ist aber kein pauschaler TMB-, IO- oder Targetmarker; konkrete Alterationen und hämatologische Evidenz entscheiden.":"Εξηγεί επιθετική κλωνική εξέλιξη/βιολογία κινδύνου, αλλά δεν είναι γενικός δείκτης TMB, IO ή target· οι συγκεκριμένες αλλοιώσεις και τα αιματολογικά δεδομένα καθορίζουν.","Viele Aberrationen bedeuten automatisch hohe Immuntherapie-Sensitivität.":"Πολλές ανωμαλίες σημαίνουν αυτόματα υψηλή ευαισθησία στην ανοσοθεραπεία.","Komplexer Karyotyp ist automatisch eine PARP-Indikation.":"Ένας σύνθετος καρυότυπος αποτελεί αυτόματα ένδειξη PARP.","Mehr Instabilität bedeutet generell bessere Targetierbarkeit und Prognose.":"Περισσότερη αστάθεια σημαίνει γενικά καλύτερη targetability και πρόγνωση.","Ein biologisches Hallmark ist nicht identisch mit einem validierten klinischen Biomarker.":"Ένα βιολογικό hallmark δεν ταυτίζεται με έναν επικυρωμένο κλινικό βιοδείκτη.","Integrieren Sie frühere zytotoxische Therapie, Morphologie, komplexen Karyotyp und TP53/DNMT3A so, dass Diagnose-/Risikokontext und Grenzen des Begriffs 'genomische Instabilität' klar werden.":"Ενσωματώστε προηγούμενη κυτταροτοξική θεραπεία, μορφολογία, σύνθετο καρυότυπο και TP53/DNMT3A ώστε να είναι σαφή το διαγνωστικό/risk πλαίσιο και τα όρια του όρου «γονιδιωματική αστάθεια».","Aktuelle myeloische Neoplasie aus Morphologie und Genetik einordnen.":"Ταξινομήστε την τρέχουσα μυελοειδή νεοπλασία από μορφολογία και γενετική.","Vorausgegangene zytotoxische Therapie als relevanten post-zytotoxischen/therapiebezogenen Qualifier dokumentieren.":"Τεκμηριώστε προηγούμενη κυτταροτοξική θεραπεία ως σχετικό post-cytotoxic/therapy-related qualifier.","TP53 zusammen mit 17p-Verlust und komplexem Karyotyp als hochriskanten biologischen Kontext bewerten.":"Αξιολογήστε TP53 μαζί με απώλεια 17p και σύνθετο καρυότυπο ως υψηλού κινδύνου βιολογικό πλαίσιο.","Niedrigfrequentes DNMT3A nicht isoliert als AML-definierend interpretieren.":"Μην ερμηνεύετε χαμηλής συχνότητας DNMT3A μεμονωμένα ως AML-defining.","Keine pauschale PARP-/IO-/TMB-Logik aus 'Genominstabilität' ableiten.":"Μην συνάγετε γενική λογική PARP/IO/TMB από «γονιδιωματική αστάθεια».","Hämatologiespezifische Diagnostik gegenüber einem Pan-Cancer-Panel priorisieren.":"Δώστε προτεραιότητα σε αιματολογικά ειδική διάγνωση έναντι pan-cancer panel.","Ein umfassenderes validiertes myeloisches NGS-Panel wäre für reale Routinediagnostik sinnvoll, sofern Morphologie, Immunphänotyp und Zytogenetik integriert bleiben.":"Ένα πιο ολοκληρωμένο επικυρωμένο myeloid NGS panel θα ήταν κατάλληλο στην πραγματική routine διάγνωση, εφόσον μορφολογία, ανοσοφαινότυπος και κυτταρογενετική παραμένουν ενσωματωμένα.","Bei unklarer klonaler Architektur kann eine geeignete Verlauf-/Vorprobe helfen, präexistente klonale Hämatopoese von dominanter Leukämieklonalität abzugrenzen.":"Αν η κλωνική αρχιτεκτονική είναι ασαφής, κατάλληλο follow-up/προηγούμενο δείγμα μπορεί να βοηθήσει στη διάκριση προϋπάρχουσας κλωνικής αιμοποίησης από κυρίαρχη λευχαιμική κλωνικότητα.","Exposition = Diagnose":"Έκθεση = διάγνωση","Die frühere Therapie ist Kontext/Qualifier; aktuelle Morphologie und Genetik definieren die Erkrankung.":"Η προηγούμενη θεραπεία είναι context/qualifier· η τρέχουσα μορφολογία και γενετική ορίζουν τη νόσο.","DNMT3A = AML":"DNMT3A = AML","CHIP-typische Varianten können ohne manifeste Neoplasie vorkommen und brauchen Kontext.":"CHIP-τυπικές παραλλαγές μπορεί να εμφανίζονται χωρίς έκδηλη νεοπλασία και χρειάζονται πλαίσιο.","Genominstabilität = IO/PARP":"Γονιδιωματική αστάθεια = IO/PARP","Hallmark und validierter prädiktiver Biomarker sind nicht dasselbe.":"Hallmark και επικυρωμένος προβλεπτικός βιοδείκτης δεν είναι το ίδιο.","Pan-Cancer-TMB/MSI":"Pan-cancer TMB/MSI","Für die konkrete myeloische Klassifikationsfrage ist dies kein sinnvoller Primäransatz.":"Αυτό δεν αποτελεί χρήσιμη πρωτογενή προσέγγιση για το συγκεκριμένο ερώτημα μυελοειδούς ταξινόμησης.","Der kleine DNMT3A-Klon ist nicht die Geschichte – TP53 plus Karyotyp ist es":"Ο μικρός κλώνος DNMT3A δεν είναι η ιστορία – TP53 συν καρυότυπος είναι","Das Panel zeigt DNMT3A p.R882H nur mit 4 % VAF, daneben TP53 p.R273H mit 43 %. Zusammen mit 17p-Verlust und komplexem Karyotyp ist TP53 Teil der dominanten hochriskanten Krankheitsbiologie. DNMT3A kann dagegen einen kleineren, möglicherweise präexistierenden CH-Klon markieren. Die 'vielen genetischen Schäden' sind hier vor allem Risikosignatur – nicht automatisch therapeutische Verwundbarkeit.":"Το panel δείχνει DNMT3A p.R882H μόνο με VAF 4%, δίπλα σε TP53 p.R273H με 43%. Μαζί με απώλεια 17p και σύνθετο καρυότυπο, το TP53 αποτελεί μέρος της κυρίαρχης υψηλού κινδύνου βιολογίας της νόσου. Το DNMT3A αντίθετα μπορεί να σηματοδοτεί μικρότερο, πιθανώς προϋπάρχοντα κλώνο CH. Οι «πολλές γενετικές βλάβες» εδώ είναι κυρίως signature κινδύνου – όχι αυτόματα θεραπευτική ευπάθεια.","Der Fall zeigt, dass Mutationsnamen ohne Klonstärke, Zytogenetik, Morphologie und klinischen Kontext leicht in die falsche Richtung führen.":"Η περίπτωση δείχνει πόσο εύκολα ονόματα μεταλλάξεων χωρίς μέγεθος κλώνου, κυτταρογενετική, μορφολογία και κλινικό πλαίσιο μπορεί να οδηγήσουν σε λάθος κατεύθυνση.","Klonale Architektur und Exposition integriert":"Ενσωμάτωση κλωνικής αρχιτεκτονικής και έκθεσης","Akute myeloische Neoplasie mit TP53-Alteration und komplexem Karyotyp nach zytotoxischer Therapie. TP53/17p/komplexer Karyotyp = hochriskanter dominanter Kontext; DNMT3A 4 % VAF potenziell CH-Klon. Keine pauschale Target-/IO-Aussage aus Genominstabilität.":"Οξεία μυελοειδής νεοπλασία με αλλοίωση TP53 και σύνθετο καρυότυπο μετά από κυτταροτοξική θεραπεία. TP53/17p/σύνθετος καρυότυπος = κυρίαρχο υψηλού κινδύνου πλαίσιο· DNMT3A VAF 4% πιθανός κλώνος CH. Καμία γενική δήλωση target/IO από γονιδιωματική αστάθεια.","Morphologie, Genetik, Exposition und Klonalität korrekt zusammengeführt.":"Μορφολογία, γενετική, έκθεση και κλωνικότητα ενσωματώθηκαν σωστά.","Therapieassoziiert erkannt, Genetik zu grob":"Αναγνώριση therapy-related πλαισίου, υπερβολικά αδρή γενετική ερμηνεία","Die frühere Chemotherapie wird korrekt erwähnt, aber TP53 und DNMT3A werden gleichgewichtet und der komplexe Karyotyp bleibt unterbewertet.":"Η προηγούμενη χημειοθεραπεία αναφέρεται σωστά, αλλά TP53 και DNMT3A σταθμίζονται ισότιμα και ο σύνθετος καρυότυπος υποεκτιμάται.","Klonale und prognostische Hierarchie fehlt.":"Λείπει η κλωνική και προγνωστική ιεραρχία.","Instabilität als Therapiechance verkauft":"Η αστάθεια παρουσιάζεται ως θεραπευτική ευκαιρία","Komplexer Karyotyp und TP53 werden als unspezifischer Hinweis auf hohe TMB/IO- oder PARP-Sensitivität interpretiert.":"Σύνθετος καρυότυπος και TP53 ερμηνεύονται ως μη ειδική ένδειξη υψηλού TMB/IO ή ευαισθησίας PARP.","Hallmark wurde fälschlich zum prädiktiven Biomarker gemacht.":"Ένα hallmark μετατράπηκε λανθασμένα σε προβλεπτικό βιοδείκτη.","TP53 + komplexer Karyotyp bestätigt":"Επιβεβαίωση TP53 + σύνθετου καρυοτύπου","Hämatologische Risikostratifikation und Therapieplanung entsprechend der hochriskanten Krankheitsbiologie durchführen.":"Διενεργήστε αιματολογική risk stratification και θεραπευτικό σχεδιασμό σύμφωνα με την υψηλού κινδύνου βιολογία της νόσου.","Die Priorität liegt auf korrekter Klassifikation/Risiko- und Therapieplanung, nicht auf unspezifischem Pan-Cancer-Targeting.":"Προτεραιότητα είναι η σωστή ταξινόμηση/risk και ο θεραπευτικός σχεδιασμός, όχι μη ειδικό pan-cancer targeting.","niedrigfrequente CH-typische Variante":"χαμηλής συχνότητας CH-τυπική παραλλαγή","Nur im Kontext interpretieren; bei Bedarf Verlauf/Vorproben zur Klonhistorie heranziehen.":"Ερμηνεύστε μόνο στο πλαίσιο· αν χρειάζεται χρησιμοποιήστε follow-up/προηγούμενα δείγματα για την κλωνική ιστορία.","CHIP und manifeste Neoplasie werden nicht verwechselt.":"CHIP και έκδηλη νεοπλασία δεν συγχέονται.","Post-zytotoxische/therapiebezogene Vorgeschichte ist ein wichtiger Qualifier, nicht die alleinige Definition der aktuellen myeloischen Erkrankung.":"Το post-cytotoxic/therapy-related ιστορικό είναι σημαντικό qualifier, όχι ο μοναδικός ορισμός της τρέχουσας μυελοειδούς νόσου.","TP53 plus komplexer Karyotyp kennzeichnet hochriskante Biologie.":"TP53 συν σύνθετος καρυότυπος χαρακτηρίζουν υψηλού κινδύνου βιολογία.","Niedrige VAF in CHIP-typischen Genen kann eine kleinere Begleitklonalität darstellen.":"Χαμηλή VAF σε CHIP-τυπικά γονίδια μπορεί να αντιπροσωπεύει μικρότερη συνοδό κλωνικότητα.","Genomische Instabilität ist ein Hallmark, aber kein universeller Target- oder Immuntherapiemarker.":"Η γονιδιωματική αστάθεια είναι hallmark, αλλά όχι καθολικός βιοδείκτης target ή ανοσοθεραπείας.","Hämatologische Diagnostik muss Morphologie, Zytogenetik und Molekulargenetik integrieren.":"Η αιματολογική διάγνωση πρέπει να ενσωματώνει μορφολογία, κυτταρογενετική και μοριακή γενετική.","Akute myeloische Neoplasie nach zytotoxischer Therapie mit dominanter TP53-/komplex-karyotypischer Hochrisikobiologie. Die Exposition wird als Qualifier integriert. DNMT3A bei 4 % VAF kann eine kleinere CH-Klonalität repräsentieren und definiert die AML nicht. Aus Genominstabilität folgt keine pauschale PARP-/IO-Indikation.":"Οξεία μυελοειδής νεοπλασία μετά από κυτταροτοξική θεραπεία με κυρίαρχη υψηλού κινδύνου βιολογία TP53/σύνθετου καρυοτύπου. Η έκθεση ενσωματώνεται ως qualifier. DNMT3A με VAF 4% μπορεί να αντιπροσωπεύει μικρότερο κλώνο CH και δεν ορίζει AML. Η γονιδιωματική αστάθεια δεν συνεπάγεται γενική ένδειξη PARP/IO.","Exposition als Qualifier statt Alleindefinition":"Έκθεση ως qualifier αντί μοναδικού ορισμού","TP53/komplexer Karyotyp priorisiert":"Προτεραιότητα σε TP53/σύνθετο καρυότυπο","DNMT3A niedrig-VAF nicht überinterpretiert":"Χαμηλής VAF DNMT3A χωρίς υπερερμηνεία","Hallmark ≠ klinischer Biomarker":"Hallmark ≠ κλινικός βιοδείκτης","Warum sind Therapiegeschichte und aktuelle Genetik beide wichtig, aber nicht austauschbar?":"Γιατί είναι σημαντικά τόσο το ιστορικό θεραπείας όσο και η τρέχουσα γενετική, αλλά δεν είναι εναλλάξιμα;","Wie hilft die VAF bei der Interpretation möglicher CH-Klone?":"Πώς βοηθά η VAF στην ερμηνεία πιθανών κλώνων CH;","Welche zusätzlichen Untersuchungen gehören real zur AML-Klassifikation, obwohl dieser Simulatorfall den Fokus enger setzt?":"Ποιες πρόσθετες εξετάσεις ανήκουν πραγματικά στην ταξινόμηση AML, παρότι αυτό το simulator case έχει στενότερο focus;","DNMT3A low-VAF ist Nebenklon; TP53 plus komplexer Karyotyp dominiert":"Χαμηλής VAF DNMT3A είναι δευτερεύων κλώνος· TP53 συν σύνθετος καρυότυπος κυριαρχούν","Genominstabilität ist Risikobiologie, nicht automatisch Target":"Η γονιδιωματική αστάθεια είναι βιολογία κινδύνου, όχι αυτόματα target","Exposition → Morphologie/Zytogenetik → TP53/DNMT3A-Klonalität → Risikokontext":"Έκθεση → μορφολογία/κυτταρογενετική → κλωνικότητα TP53/DNMT3A → πλαίσιο κινδύνου","„Cold Tumor“ mit wenig TILs und dichter Stromabarriere → Warum ist PD-1 allein wahrscheinlich schwach?":"«Cold tumor» με λίγα TILs και πυκνό στρωματικό φραγμό → Γιατί πιθανότατα είναι αδύναμο το PD-1 μόνο;","„Cold Tumor“ mit wenig TILs und di…":"«Cold tumor» με λίγα TILs και πυ…","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach systemischer Erstlinientherapie. Ein externer Zusatzbefund nennt PD-L1 TPS 15 % und löst die Frage nach einer PD-1-Monotherapie aus.":"Ασθενής 64 ετών με μεταστατικό παγκρεατικό πορογενές αδενοκαρκίνωμα και πρόοδο μετά από συστηματική θεραπεία πρώτης γραμμής. Εξωτερικός συμπληρωματικός έλεγχος αναφέρει PD-L1 TPS 15% και εγείρει το ερώτημα μονοθεραπείας PD-1.","Ist die PD-L1-Expression hier ein belastbarer Hinweis auf Checkpoint-Sensitivität – oder spricht das gesamte Tumor-Immune-Milieu eher dagegen?":"Είναι η έκφραση PD-L1 εδώ αξιόπιστη ένδειξη ευαισθησίας σε checkpoint – ή το συνολικό tumor-immune milieu συνηγορεί κατά;","Die Zweitlinienstrategie soll im nächsten MTB festgelegt werden.":"Η στρατηγική δεύτερης γραμμής θα καθοριστεί στο επόμενο MTB.","Krankheitsverlauf":"Πορεία νόσου","Primär lokal fortgeschritten, später hepatische Metastasierung; nun radiologischer Progress.":"Αρχικά τοπικά προχωρημένο, αργότερα ηπατική μετάσταση· τώρα ακτινολογική πρόοδος.","Systemische Standardtherapie, insgesamt gute Belastbarkeit; keine bekannte Autoimmunerkrankung.":"Συστηματική standard θεραπεία, συνολικά καλή γενική κατάσταση· χωρίς γνωστή αυτοάνοση νόσο.","Externer Impuls":"Εξωτερικό ερέθισμα","PD-L1 TPS 15 % wird im Zuweiserbrief als 'positiv – Immuntherapie möglich?' markiert.":"PD-L1 TPS 15% σημειώνεται στο παραπεμπτικό ως «θετικό – ανοσοθεραπεία δυνατή;».","Ein exprimierter Checkpoint wird mit bereits vorhandener effektiver Antitumor-Immunität gleichgesetzt.":"Ένα εκφραζόμενο checkpoint εξισώνεται με ήδη υπάρχουσα αποτελεσματική αντικαρκινική ανοσία.","Duktales Adenokarzinom mit ausgeprägter desmoplastischer Stromareaktion.":"Πορογενές αδενοκαρκίνωμα με έντονη δεσμοπλαστική στρωματική αντίδραση.","Immunmorphologie":"Ανοσομορφολογία","Nur wenige intraepitheliale Lymphozyten; Immunzellen liegen überwiegend stromal/peritumoral.":"Μόνο λίγα ενδοεπιθηλιακά λεμφοκύτταρα· τα ανοσοκύτταρα βρίσκονται κυρίως στο στρώμα/περιφερικά του όγκου.","PD-L1 Vorbefund":"Προηγούμενο αποτέλεσμα PD-L1","TPS 15 %, technisch plausibel und reproduzierbar.":"TPS 15%, τεχνικά εύλογο και αναπαραγώγιμο.","MMR/MSI, TMB sowie räumlicher TIL-/Stromakontext.":"MMR/MSI, TMB και χωρικό πλαίσιο TIL/στρώματος.","FFPE-Lebermetastase, Block M4.":"FFPE ηπατική μετάσταση, block M4.","ca. 35 %, nach Makrodissektion ausreichend.":"περ. 35%, επαρκές μετά από μακροδιατομή.","10 Schnitte; fokussierte IHC plus DNA-basierte Zusatzdiagnostik möglich.":"10 τομές· είναι δυνατά στοχευμένο IHC και πρόσθετος DNA-based έλεγχος.","Explorative TME-Marker können die Biologie illustrieren, sind aber kein validierter Ersatz für etablierte prädiktive Marker.":"Οι exploratory TME markers μπορούν να απεικονίσουν τη βιολογία αλλά δεν αποτελούν επικυρωμένο υποκατάστατο καθιερωμένων προβλεπτικών δεικτών.","Etablierte immunonkologische Biomarker":"Καθιερωμένοι ανοσο-ογκολογικοί βιοδείκτες","TIL-/TME-Kontext":"Πλαίσιο TIL/TME","MMR-Proteine erhalten; molekular MSS. Es liegt damit kein dMMR/MSI-H-Kontext als etablierter starker ICI-Biomarker vor.":"Διατηρημένες πρωτεΐνες MMR· μοριακά MSS. Επομένως δεν υπάρχει πλαίσιο dMMR/MSI-H ως καθιερωμένος ισχυρός βιοδείκτης ICI.","TMB niedrig (3,2 Mut/Mb). Der Wert liefert in diesem Fall keinen zusätzlichen Hinweis auf eine ausgeprägte Neoantigenlast.":"TMB χαμηλό (3,2 Mut/Mb). Στην περίπτωση αυτή η τιμή δεν παρέχει πρόσθετη ένδειξη υψηλού νεοαντιγονικού φορτίου.","PD-L1 TPS 15 % wird bestätigt. Der Befund ist real, darf beim Pankreasadenokarzinom aber nicht isoliert als ausreichender Selektionsmarker für PD-1-Monotherapie interpretiert werden.":"PD-L1 TPS 15% επιβεβαιώνεται. Το εύρημα είναι πραγματικό, αλλά στο παγκρεατικό αδενοκαρκίνωμα δεν πρέπει να ερμηνεύεται μεμονωμένα ως επαρκής δείκτης επιλογής για μονοθεραπεία PD-1.","Immuninfiltrat":"Ανοσολογικό διήθημα","CD8-positive T-Zellen sind insgesamt spärlich und überwiegend stromal/peritumoral; nur wenige erreichen Tumorzellnester.":"Τα CD8-θετικά Τ κύτταρα είναι συνολικά λίγα και κυρίως στρωματικά/περιφερικά του όγκου· μόνο λίγα φθάνουν στις νησίδες καρκινικών κυττάρων.","Stromakontext":"Στρωματικό πλαίσιο","Ausgeprägte desmoplastische, fibroblastenreiche Stromazone mit immune-excluded Muster. Der Befund illustriert eine physische/biologische Barriere, ist aber kein eigenständig validierter Therapie-Selektionsassay.":"Έντονη δεσμοπλαστική, πλούσια σε ινοβλάστες στρωματική ζώνη με immune-excluded pattern. Το εύρημα απεικονίζει φυσικό/βιολογικό φραγμό αλλά δεν αποτελεί ανεξάρτητα επικυρωμένο assay επιλογής θεραπείας.","Ausgeprägt desmoplastisches Pankreasadenokarzinom mit wenig intratumoralen Lymphozyten.":"Έντονα δεσμοπλαστικό παγκρεατικό αδενοκαρκίνωμα με λίγα ενδοογκικά λεμφοκύτταρα.","IHC und DNA-basierte Analysen technisch auswertbar.":"IHC και DNA-based αναλύσεις τεχνικά αξιολογήσιμες.","Metastasiertes duktales Pankreasadenokarzinom mit bestätigter PD-L1-Expression, jedoch pMMR/MSS, niedriger TMB und deutlich immune-excluded/desmoplastischem Mikromilieu. PD-L1 allein begründet hier keine belastbare PD-1-Monotherapie-Strategie. TIL-/Stromamarker erklären die biologische Plausibilität eines 'cold/excluded' Tumors, sind aber selbst keine validierten Selektionsmarker.":"Μεταστατικό παγκρεατικό πορογενές αδενοκαρκίνωμα με επιβεβαιωμένη έκφραση PD-L1, αλλά pMMR/MSS, χαμηλό TMB και σαφώς immune-excluded/δεσμοπλαστικό μικροπεριβάλλον. Το PD-L1 μόνο του δεν αποτελεί εδώ αξιόπιστη βάση για στρατηγική μονοθεραπείας PD-1. Οι TIL/στρωματικοί δείκτες εξηγούν τη βιολογική πιθανότητα ενός «cold/excluded» όγκου, αλλά δεν είναι οι ίδιοι επικυρωμένοι δείκτες επιλογής.","Teilbefund: PD-L1 ist exprimiert, aber ohne MMR/MSI/TMB- und räumlichen TIL-Kontext bleibt die Aussage zur Checkpoint-Sensitivität unvollständig.":"Μερικό αποτέλεσμα: PD-L1 εκφράζεται, αλλά χωρίς MMR/MSI/TMB και χωρικό πλαίσιο TIL, η εκτίμηση ευαισθησίας στα checkpoints παραμένει ελλιπής.","PD-L1 als Kontextmarker, nicht als alleinige Therapieentscheidung behandeln":"Αντιμετωπίστε το PD-L1 ως δείκτη πλαισίου, όχι ως μοναδική θεραπευτική απόφαση","pMMR/MSS und niedrige TMB als fehlende starke ICI-Signale benennen":"Αναφέρετε pMMR/MSS και χαμηλό TMB ως απουσία ισχυρών σημάτων ICI","immune-excluded/desmoplastisches Muster biologisch erklären":"Εξηγήστε βιολογικά το immune-excluded/δεσμοπλαστικό pattern","TME-IHC nicht als validierten Therapie-Selektionsassay verkaufen":"Μην παρουσιάζετε το TME IHC ως επικυρωμένο assay επιλογής θεραπείας","Falschaussage: PD-L1-Positivität beweist eine ausreichende Effektor-T-Zell-Antwort":"Λανθασμένη δήλωση: η θετικότητα PD-L1 αποδεικνύει επαρκή απόκριση effector T cells","Optimale Lösung: PD-L1 15 % nicht isoliert interpretieren; pMMR/MSS, niedrige TMB und das immune-excluded/desmoplastische Muster integrieren. Die TME-Befunde erklären die biologische Barriere, ersetzen aber keine klinisch validierten Biomarker oder leitliniengerechte Therapieentscheidung.":"Βέλτιστη λύση: μην ερμηνεύετε PD-L1 15% μεμονωμένα· ενσωματώστε pMMR/MSS, χαμηλό TMB και immune-excluded/δεσμοπλαστικό pattern. Τα ευρήματα TME εξηγούν τον βιολογικό φραγμό αλλά δεν αντικαθιστούν κλινικά επικυρωμένους βιοδείκτες ή guideline-based θεραπευτικές αποφάσεις.","Pankreasadenokarzinom":"Παγκρεατικό αδενοκαρκίνωμα","TMB-low":"TMB-low","TILs":"TILs","TME":"TME","Desmoplasie":"Δεσμοπλασία","Immune exclusion":"Ανοσολογικός αποκλεισμός","PD-L1 vorhanden, aber die T-Zellen kommen nicht hinein: immune-excluded Pankreasadenokarzinom":"PD-L1 υπάρχει, αλλά τα Τ κύτταρα δεν εισέρχονται: immune-excluded παγκρεατικό αδενοκαρκίνωμα","Molekularpathologie / Gastroonkologie / MTB":"Μοριακή παθολογία / Γαστρεντερική ογκολογία / MTB","PD-L1-Expression von einer tatsächlich inflamed/hot Tumormikroumgebung unterscheiden.":"Διαχωρίστε την έκφραση PD-L1 από ένα πραγματικά inflamed/hot μικροπεριβάλλον όγκου.","MMR/MSI und TMB als etabliertere immunonkologische Biomarker gegenüber explorativen TME-Markern priorisieren.":"Δώστε προτεραιότητα σε MMR/MSI και TMB ως πιο καθιερωμένους ανοσο-ογκολογικούς βιοδείκτες έναντι exploratory TME markers.","Ein immune-excluded Muster aus Morphologie, TIL-Verteilung und desmoplastischem Stroma ableiten.":"Συνάγετε immune-excluded pattern από μορφολογία, κατανομή TIL και δεσμοπλαστικό στρώμα.","Verstehen, dass Stromabarriere/TIL-IHC die Biologie erklären, aber keine validierte Therapie-Selektion ersetzen.":"Κατανοήστε ότι ο στρωματικός φραγμός/TIL IHC εξηγεί τη βιολογία αλλά δεν αντικαθιστά επικυρωμένη επιλογή θεραπείας.","PD-1-Monotherapie nicht allein aus einem PD-L1-positiven Befund ableiten.":"Μην συνάγετε μονοθεραπεία PD-1 μόνο από θετικό εύρημα PD-L1.","Im Zuweiserbrief steht fett: 'PD-L1 TPS 15 % – Immuntherapie?' Auf dem HE sieht der Tumor jedoch fast wie eine Festung aus: breite desmoplastische Stromazonen, wenige T-Zellen und kaum Lymphozyten in den Tumorzellnestern. Der Fall zwingt zur Frage, ob ein exprimierter Checkpoint überhaupt etwas nützt, wenn kaum aktivierbare Effektor-T-Zellen den Tumor erreichen.":"Στο παραπεμπτικό αναγράφεται με έντονα γράμματα: «PD-L1 TPS 15% – ανοσοθεραπεία;» Στο H&E όμως ο όγκος μοιάζει σχεδόν με φρούριο: πλατιές δεσμοπλαστικές στρωματικές ζώνες, λίγα Τ κύτταρα και ελάχιστα λεμφοκύτταρα στις νησίδες καρκινικών κυττάρων. Η περίπτωση θέτει το ερώτημα αν ένα εκφραζόμενο checkpoint έχει αξία όταν λίγα ενεργοποιήσιμα effector T cells φθάνουν στον όγκο.","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach Erstlinientherapie. Ein externer PD-L1-Befund ist positiv. Im MTB soll geklärt werden, ob daraus eine belastbare PD-1-Monotherapie-Strategie folgt und welche Bedeutung das auffallend desmoplastische, lymphozytenarme Mikromilieu besitzt.":"Ασθενής 64 ετών με μεταστατικό παγκρεατικό πορογενές αδενοκαρκίνωμα και πρόοδο μετά από θεραπεία πρώτης γραμμής. Εξωτερικό αποτέλεσμα PD-L1 είναι θετικό. Το MTB πρέπει να διευκρινίσει αν αυτό στηρίζει αξιόπιστη στρατηγική μονοθεραπείας PD-1 και ποια είναι η σημασία του έντονα δεσμοπλαστικού, φτωχού σε λεμφοκύτταρα μικροπεριβάλλοντος.","Verlockender Einzelmarker":"Δελεαστικός μεμονωμένος δείκτης","PD-L1 TPS 15 % ist technisch reproduzierbar.":"PD-L1 TPS 15% είναι τεχνικά αναπαραγώγιμο.","Ein real positiver Marker kann trotzdem im falschen Entitäts-/Biologiekontext wenig prädiktive Aussage besitzen.":"Ένας πραγματικά θετικός δείκτης μπορεί παρ’ όλα αυτά να έχει μικρή προβλεπτική αξία στο λάθος entity/biological context.","Morphologisches Gegenargument":"Μορφολογικό αντεπιχείρημα","Breite Desmoplasie, wenige intratumorale TILs.":"Εκτεταμένη δεσμοπλασία, λίγα ενδοογκικά TILs.","Checkpoint-Blockade reaktiviert vorhandene Immunantwort; sie erzeugt nicht automatisch eine fehlende T-Zell-Infiltration.":"Η checkpoint blockade επανενεργοποιεί υπάρχουσα ανοσολογική απόκριση· δεν δημιουργεί αυτόματα την απούσα διήθηση Τ κυττάρων.","Validierte vs. explorative Ebene":"Επικυρωμένο vs exploratory επίπεδο","MMR/MSI/TMB können klinisch validierte Signale liefern; TME-IHC illustriert Mechanismen.":"MMR/MSI/TMB μπορούν να παρέχουν κλινικά επικυρωμένα σήματα· TME IHC απεικονίζει μηχανισμούς.","Mechanistische Plausibilität und validierter Therapiebiomarker sind nicht dasselbe.":"Η μηχανιστική πιθανότητα και ο επικυρωμένος θεραπευτικός βιοδείκτης δεν είναι το ίδιο.","PDAC mit ausgeprägter Desmoplasie und wenig intratumoralen Lymphozyten.":"PDAC με έντονη δεσμοπλασία και λίγα ενδοογκικά λεμφοκύτταρα.","TPS 15 %, reproduzierbar.":"TPS 15%, αναπαραγώγιμο.","Metastasenblock mit ca. 35 % Tumoranteil; fokussierte Zusatzdiagnostik möglich.":"Block μετάστασης με περ. 35% όγκο· εφικτός στοχευμένος πρόσθετος έλεγχος.","Nur zehn Schnitte: explorative Zusatz-IHC muss einen klaren didaktischen/biologischen Nutzen haben.":"Μόνο δέκα τομές: exploratory πρόσθετο IHC πρέπει να έχει σαφή διδακτική/βιολογική αξία.","TME-/Stroma-IHC ist in diesem Fall bewusst eine mechanistische Zusatzebene, kein validierter Companion-Diagnostic-Ersatz.":"Το TME/στρωματικό IHC είναι σκόπιμα πρόσθετο μηχανιστικό επίπεδο σε αυτή την περίπτωση, όχι επικυρωμένο substitute companion diagnostic.","MMR/MSI/TMB müssen gegenüber breit gestreuter Immun-IHC priorisiert werden, wenn die Therapiefrage im Vordergrund steht.":"MMR/MSI/TMB πρέπει να έχουν προτεραιότητα έναντι ευρέως διασκορπισμένου immune IHC όταν κεντρικό είναι το θεραπευτικό ερώτημα.","Was bedeutet PD-L1 TPS 15 % in diesem PDAC am ehesten?":"Τι σημαίνει πιθανότερα PD-L1 TPS 15% σε αυτό το PDAC;","Der Befund ist biologisch real, reicht aber ohne entitätsspezifisch validierten Kontext nicht für eine belastbare PD-1-Monotherapie-Entscheidung.":"Το εύρημα είναι βιολογικά πραγματικό, αλλά χωρίς entity-specific επικυρωμένο πλαίσιο δεν αρκεί για αξιόπιστη απόφαση μονοθεραπείας PD-1.","Jede PD-L1-Positivität ist tumoragnostisch eine ICI-Indikation.":"Κάθε θετικότητα PD-L1 αποτελεί tumor-agnostic ένδειξη για ICI.","PD-L1 kann bei PDAC technisch nicht gemessen werden.":"Το PD-L1 τεχνικά δεν μπορεί να μετρηθεί στο PDAC.","PD-L1 15 % beweist automatisch TMB-high.":"PD-L1 15% αποδεικνύει αυτόματα TMB-high.","PD-L1-Expression ist nicht tumoragnostisch gleichbedeutend mit validierter Checkpoint-Sensitivität.":"Η έκφραση PD-L1 δεν είναι tumor-agnostic συνώνυμη με επικυρωμένη checkpoint sensitivity.","Wodurch ist ein immune-excluded Muster am besten charakterisiert?":"Τι χαρακτηρίζει καλύτερα ένα immune-excluded pattern;","Immunzellen sind vorhanden, bleiben aber überwiegend im Stroma/peritumoral und erreichen Tumorzellnester nur schlecht.":"Τα ανοσοκύτταρα υπάρχουν αλλά παραμένουν κυρίως στο στρώμα/περιφερικά του όγκου και φθάνουν δύσκολα στις νησίδες καρκινικών κυττάρων.","Dichtes intraepitheliales CD8-Infiltrat in allen Tumorarealen.":"Πυκνό ενδοεπιθηλιακό CD8 διήθημα σε όλες τις περιοχές του όγκου.","Jeder immune-excluded Tumor ist automatisch MSI-H.":"Κάθε immune-excluded όγκος είναι αυτόματα MSI-H.","PD-L1-Expression allein definiert immune exclusion.":"Η έκφραση PD-L1 μόνη της ορίζει immune exclusion.","Die räumliche Verteilung der Immunzellen ist zentral; 'vorhanden' ist nicht gleich 'im Tumor wirksam'.":"Η χωρική κατανομή των ανοσοκυττάρων είναι κεντρική· «παρόντα» δεν σημαίνει «αποτελεσματικά μέσα στον όγκο».","Welche Zusatzdiagnostik sollte für die klinische IO-Frage priorisiert werden?":"Ποιος πρόσθετος έλεγχος πρέπει να έχει προτεραιότητα για το κλινικό ερώτημα IO;","MMR/MSI und ggf. TMB als etabliertere Biomarker; TME-IHC nur ergänzend/mechanistisch.":"MMR/MSI και, όπου ενδείκνυται, TMB ως πιο καθιερωμένοι βιοδείκτες· TME IHC μόνο συμπληρωματικά/μηχανιστικά.","Nur CAF-/Stroma-IHC, da diese allein die Therapie festlegt.":"Μόνο CAF/στρωματικό IHC, αφού αυτό μόνο καθορίζει τη θεραπεία.","PD-L1 mehrfach wiederholen, bis ein höherer Wert entsteht.":"Επαναλάβετε PD-L1 μέχρι να προκύψει υψηλότερη τιμή.","Keine weitere Kontextdiagnostik; TPS 15 % reicht.":"Καμία περαιτέρω context διάγνωση· TPS 15% αρκεί.","Explorative TME-Marker dürfen validierte Biomarker nicht ersetzen.":"Οι exploratory TME markers δεν πρέπει να αντικαθιστούν επικυρωμένους βιοδείκτες.","Wie darf der desmoplastische/TIL-arme Befund im MTB verwendet werden?":"Πώς μπορεί να χρησιμοποιηθεί στο MTB το δεσμοπλαστικό/TIL-poor εύρημα;","Als biologische Erklärung für geringe Checkpoint-Sensitivität bzw. immune exclusion – nicht als eigenständiger validierter Therapieausschlusstest.":"Ως βιολογική εξήγηση για χαμηλή checkpoint sensitivity ή immune exclusion – όχι ως ανεξάρτητα επικυρωμένο treatment-exclusion test.","Als absolute Kontraindikation gegen jede Immuntherapie.":"Ως απόλυτη αντένδειξη για κάθε ανοσοθεραπεία.","Als Beweis für einen zugelassenen CAF-Target-Standard.":"Ως απόδειξη εγκεκριμένου standard CAF-targeting.","Morphologie und TIL-Verteilung sind grundsätzlich bedeutungslos.":"Η μορφολογία και η κατανομή TIL είναι εξ ορισμού χωρίς σημασία.","Der TME-Befund ist mechanistisch stark, klinisch aber nicht als alleiniger Selektionsassay validiert.":"Το εύρημα TME είναι μηχανιστικά ισχυρό αλλά δεν είναι κλινικά επικυρωμένο ως μοναδικό assay επιλογής.","Formulieren Sie die MTB-Kernaussage so, dass PD-L1, pMMR/MSS/TMB und das immune-excluded/desmoplastische Muster hierarchisch korrekt integriert werden, ohne explorative TME-Befunde zu einem Companion Diagnostic aufzuwerten.":"Διατυπώστε την κεντρική δήλωση MTB ώστε PD-L1, pMMR/MSS/TMB και immune-excluded/δεσμοπλαστικό pattern να ενσωματώνονται στη σωστή ιεραρχία χωρίς τα exploratory TME findings να αναβαθμίζονται σε companion diagnostic.","PD-L1 TPS 15 % als realen, aber nicht ausreichenden Einzelbefund anerkennen.":"Αναγνωρίστε PD-L1 TPS 15% ως πραγματικό αλλά ανεπαρκές μεμονωμένο εύρημα.","MMR/MSI prüfen: pMMR/MSS.":"Αξιολογήστε MMR/MSI: pMMR/MSS.","TMB als niedrig einordnen.":"Χαρακτηρίστε το TMB ως χαμηλό.","Räumlich spärliches CD8-Infiltrat und Desmoplasie als immune-excluded TME beschreiben.":"Περιγράψτε τη χωρικά αραιή CD8 διήθηση και τη δεσμοπλασία ως immune-excluded TME.","PD-1-Monotherapie nicht allein aus PD-L1 ableiten.":"Μην συνάγετε μονοθεραπεία PD-1 μόνο από PD-L1.","TME-IHC als mechanistische Zusatzinformation, nicht als validierten Selektionsmarker berichten.":"Αναφέρετε TME IHC ως πρόσθετη μηχανιστική πληροφορία, όχι ως επικυρωμένο δείκτη επιλογής.","MMR-IHC plus MSI-Test und TMB aus einem validierten breiteren Panel, sofern Material und TAT dies erlauben.":"MMR IHC συν MSI testing και TMB από επικυρωμένο ευρύτερο panel, εφόσον υλικό και TAT το επιτρέπουν.","Auf zusätzliche Stroma-IHC verzichten, wenn die Morphologie die immune exclusion bereits überzeugend zeigt und die klinisch validierten Biomarker priorisiert werden.":"Παραλείψτε πρόσθετο στρωματικό IHC αν η μορφολογία δείχνει ήδη πειστικά immune exclusion και προτεραιοποιούνται κλινικά επικυρωμένοι βιοδείκτες.","PD-L1 = ICI":"PD-L1 = ICI","Die prädiktive Bedeutung von PD-L1 ist entitäts- und therapiespezifisch.":"Η προβλεπτική σημασία του PD-L1 είναι entity- και therapy-specific.","CAF-IHC als Companion Diagnostic":"CAF IHC ως companion diagnostic","Mechanistische TME-Marker sind hier nicht als eigenständige Therapie-Selektion validiert.":"Οι μηχανιστικοί TME markers δεν είναι εδώ επικυρωμένοι ως ανεξάρτητα εργαλεία επιλογής θεραπείας.","TIL-arm = absolute Resistenz":"TIL-poor = απόλυτη αντίσταση","Biologische Wahrscheinlichkeit ist keine absolute patientenindividuelle Ausschlussregel.":"Η βιολογική πιθανότητα δεν αποτελεί απόλυτο patient-specific κανόνα αποκλεισμού.","TMB/MSI ignorieren":"Αγνόηση TMB/MSI","Damit würden etabliertere immunonkologische Biomarker ausgelassen.":"Έτσι θα παραλείπονταν πιο καθιερωμένοι ανοσο-ογκολογικοί βιοδείκτες.","Der 'positive' Marker sitzt auf einem biologisch kalten Tumor":"Ο «θετικός» δείκτης βρίσκεται σε βιολογικά cold όγκο","PD-L1 TPS 15 % wird bestätigt – gleichzeitig ist der Tumor pMMR/MSS, TMB-low und zeigt nur wenige CD8-T-Zellen, die überwiegend im desmoplastischen Stroma stecken bleiben. Der vermeintlich positive Einzelmarker kippt dadurch nicht ins 'falsch', sondern bekommt die richtige Hierarchie: biologischer Kontextmarker statt Therapie-Schalter.":"PD-L1 TPS 15% επιβεβαιώνεται – ταυτόχρονα ο όγκος είναι pMMR/MSS, TMB-low και δείχνει μόνο λίγα CD8 T cells που παραμένουν κυρίως παγιδευμένα στο δεσμοπλαστικό στρώμα. Ο φαινομενικά θετικός μεμονωμένος δείκτης δεν γίνεται «λάθος», αλλά αποκτά τη σωστή ιεραρχία: βιολογικός δείκτης πλαισίου αντί θεραπευτικού διακόπτη.","Der Fall trennt Expression eines Checkpoints von einer vorhandenen effektiven Antitumor-Immunantwort und zeigt, warum räumliche TME-Biologie die Interpretation verändert.":"Η περίπτωση διαχωρίζει την έκφραση checkpoint από μια υπάρχουσα αποτελεσματική αντικαρκινική ανοσολογική απόκριση και δείχνει γιατί η χωρική βιολογία του TME αλλάζει την ερμηνεία.","PD-L1 im richtigen TME-Kontext":"PD-L1 στο σωστό TME πλαίσιο","PD-L1 TPS 15 %, pMMR/MSS, TMB 3,2 Mut/Mb, CD8-arm/immune-excluded mit ausgeprägter Desmoplasie. Kein belastbarer Grund für PD-1-Monotherapie allein aus PD-L1; TME-Befund mechanistisch, nicht als Companion Diagnostic.":"PD-L1 TPS 15%, pMMR/MSS, TMB 3,2 Mut/Mb, CD8-poor/immune-excluded με έντονη δεσμοπλασία. Καμία αξιόπιστη βάση για μονοθεραπεία PD-1 μόνο από PD-L1· το εύρημα TME είναι μηχανιστικό, όχι companion diagnostic.","Validierte Biomarker und TME-Biologie korrekt hierarchisiert.":"Σωστή ιεράρχηση επικυρωμένων βιοδεικτών και βιολογίας TME.","Cold erkannt, Biomarkerhierarchie unklar":"Αναγνώριση cold pattern, ασαφής ιεραρχία βιοδεικτών","Desmoplasie und wenige TILs werden beschrieben, MMR/MSI/TMB aber nicht integriert.":"Περιγράφονται δεσμοπλασία και λίγα TILs, αλλά MMR/MSI/TMB δεν ενσωματώνονται.","Biologisch plausibel, klinisch unvollständig.":"Βιολογικά εύλογο, κλινικά ελλιπές.","PD-L1 als universeller IO-Schalter":"PD-L1 ως καθολικός διακόπτης IO","TPS 15 % wird als ausreichende tumoragnostische ICI-Indikation interpretiert.":"TPS 15% ερμηνεύεται ως επαρκής tumor-agnostic ένδειξη ICI.","Entitätsspezifische Biomarkerlogik übergangen.":"Παρακάμπτεται entity-specific λογική βιοδεικτών.","pMMR/MSS und TMB-low bestätigt":"Επιβεβαίωση pMMR/MSS και TMB-low","Therapieplanung auf etablierte PDAC-Strategien bzw. passende Studien fokussieren; PD-L1 nicht isoliert übergewichten.":"Εστιάστε τον θεραπευτικό σχεδιασμό σε καθιερωμένες στρατηγικές PDAC ή κατάλληλες μελέτες· μην υπερσταθμίζετε μεμονωμένα το PD-L1.","Der Fall bleibt evidenzbasiert statt biomarkergetrieben spekulativ.":"Η περίπτωση παραμένει evidence-based αντί για biomarker-driven speculative.","TME-/Stromaforschung diskutiert":"Συζήτηση έρευνας TME/στρώματος","Studienoptionen klar als experimentell kennzeichnen.":"Χαρακτηρίστε σαφώς τις επιλογές μελετών ως πειραματικές.","Mechanistische Hypothesen werden von Routineempfehlungen getrennt.":"Οι μηχανιστικές υποθέσεις διαχωρίζονται από τις routine συστάσεις.","PD-L1-Expression ist nicht gleichbedeutend mit vorhandener effektiver T-Zell-Antwort.":"Η έκφραση PD-L1 δεν είναι συνώνυμη με υπάρχουσα αποτελεσματική Τ-cell response.","Immune exclusion beschreibt die räumliche Barriere zwischen Immunzellen und Tumorzellnestern.":"Immune exclusion περιγράφει τον χωρικό φραγμό μεταξύ ανοσοκυττάρων και νησίδων καρκινικών κυττάρων.","pMMR/MSS und niedrige TMB liefern hier keine starken etablierten Immunogenitätssignale.":"pMMR/MSS και χαμηλό TMB δεν παρέχουν εδώ ισχυρά καθιερωμένα σήματα ανοσογονικότητας.","TME-/CAF-/TIL-Marker können Mechanismen erklären, sind aber nicht automatisch validierte Therapie-Selektionstests.":"TME/CAF/TIL markers μπορούν να εξηγούν μηχανισμούς αλλά δεν είναι αυτόματα επικυρωμένα tests επιλογής θεραπείας.","Der klinische Wert eines Biomarkers hängt von Entität, Therapie und Evidenzniveau ab.":"Η κλινική αξία ενός βιοδείκτη εξαρτάται από την οντότητα, τη θεραπεία και το επίπεδο τεκμηρίωσης.","PD-L1 TPS 15 % ist kein ausreichender Monotherapie-Schalter. Der Tumor ist pMMR/MSS und TMB-low; morphologisch/IHC zeigt sich ein deutlich immune-excluded, desmoplastisches TME. Das erklärt biologisch eine geringe Wahrscheinlichkeit effektiver Checkpoint-Reaktivierung, darf aber nicht als absoluter Ausschlusstest oder validierter Companion Diagnostic formuliert werden.":"PD-L1 TPS 15% δεν είναι επαρκής διακόπτης μονοθεραπείας. Ο όγκος είναι pMMR/MSS και TMB-low· μορφολογικά/IHC υπάρχει σαφώς immune-excluded, δεσμοπλαστικό TME. Αυτό εξηγεί βιολογικά χαμηλή πιθανότητα αποτελεσματικής checkpoint reactivation, αλλά δεν πρέπει να διατυπωθεί ως απόλυτο test αποκλεισμού ή επικυρωμένο companion diagnostic.","PD-L1 nicht überinterpretiert":"PD-L1 χωρίς υπερερμηνεία","MMR/MSI/TMB priorisiert":"Προτεραιότητα σε MMR/MSI/TMB","immune-excluded räumlich verstanden":"Χωρική κατανόηση immune-excluded","TME-Marker als explorativ begrenzt":"TME markers περιορισμένοι ως exploratory","Warum kann PD-L1 exprimiert sein, obwohl kaum T-Zellen im Tumor sitzen?":"Γιατί μπορεί να εκφράζεται PD-L1 παρότι σχεδόν δεν υπάρχουν Τ κύτταρα μέσα στον όγκο;","Was unterscheidet immune-desert von immune-excluded?":"Τι διακρίνει immune-desert από immune-excluded;","Welche TME-Marker sind mechanistisch interessant, aber nicht routineprädiktiv validiert?":"Ποιοι TME markers είναι μηχανιστικά ενδιαφέροντες αλλά όχι επικυρωμένοι ως routine predictive markers;","PD-L1 positiv, aber pMMR/MSS/TMB-low + immune-excluded":"PD-L1 θετικό, αλλά pMMR/MSS/TMB-low + immune-excluded","Checkpoint-Expression braucht einen validierten Entitäts- und Immunitätskontext":"Η checkpoint expression απαιτεί επικυρωμένο πλαίσιο οντότητας και ανοσίας","PD-L1 → MMR/MSI/TMB → räumliche TILs → TME-Limitation":"PD-L1 → MMR/MSI/TMB → χωρικά TILs → περιορισμός TME","PD-L1 positiv, aber niedrige TMB und kein Immuninfiltrat → PD-L1 nicht überinterpretieren":"PD-L1 θετικό, αλλά χαμηλό TMB και χωρίς ανοσολογικό διήθημα → μην υπερερμηνεύετε PD-L1","PD-L1 positiv, aber niedrige TMB u…":"PD-L1 θετικό, αλλά χαμηλό TMB κ…","61-jährige Patientin mit metastasiertem kolorektalem Adenokarzinom nach Progress unter mehreren Standardtherapien. In einer Metastasenbiopsie wird PD-L1 CPS 25 berichtet.":"Ασθενής 61 ετών με μεταστατικό κολοορθικό αδενοκαρκίνωμα μετά από πρόοδο σε αρκετές standard θεραπείες. Σε βιοψία μετάστασης αναφέρεται PD-L1 CPS 25.","Kann die hohe PD-L1-Expression trotz fehlender klassischer Immunogenitätsmarker eine PD-1-Monotherapie begründen?":"Μπορεί η υψηλή έκφραση PD-L1 να αιτιολογήσει μονοθεραπεία PD-1 παρά την απουσία κλασικών δεικτών ανοσογονικότητας;","Es wird nach einer weiteren systemischen Option gesucht; Studienzugang wird parallel geprüft.":"Αναζητείται επιπλέον συστηματική επιλογή· παράλληλα αξιολογείται πρόσβαση σε μελέτη.","Primarius":"Πρωτοπαθής όγκος","Linksseitiges Kolonkarzinom, inzwischen hepatisch und pulmonal metastasiert.":"Αριστερόπλευρος καρκίνος παχέος εντέρου, πλέον με ηπατικές και πνευμονικές μεταστάσεις.","Fluoropyrimidin/Oxaliplatin, Irinotecan-basierte Therapie und weitere leitliniengerechte Linien.":"Φθοριοπυριμιδίνη/οξαλιπλατίνη, θεραπεία με ιρινοτεκάνη και περαιτέρω guideline-concordant γραμμές.","Außenbefund":"Εξωτερικό αποτέλεσμα","PD-L1 CPS 25 wird auf dem Deckblatt fett hervorgehoben.":"PD-L1 CPS 25 επισημαίνεται με έντονα γράμματα στο εξώφυλλο.","Ein 'positiver' Marker wird aus einer anderen Tumorentität in den CRC-Kontext übertragen, obwohl die prädiktive Hierarchie dort anders ist.":"Ένας «θετικός» δείκτης μεταφέρεται από άλλη οντότητα όγκου στο πλαίσιο CRC, παρότι η προβλεπτική ιεραρχία εκεί διαφέρει.","Kolorektales Adenokarzinom, mäßig differenziert; keine ausgeprägt lymphozytenreiche Morphologie.":"Μέτρια διαφοροποιημένο κολοορθικό αδενοκαρκίνωμα· χωρίς έντονα λεμφοκυτταροβριθή μορφολογία.","CPS 25, überwiegend durch PD-L1-positive Immunzellen an Nekrose-/Stromagrenzen mitgetragen.":"CPS 25, κυρίως λόγω PD-L1-θετικών ανοσοκυττάρων στα όρια νέκρωσης/στρώματος.","Nur spärliche intratumorale CD8-positive Lymphozyten.":"Μόνο λίγα ενδοογκικά CD8-θετικά λεμφοκύτταρα.","MMR/MSI und TMB als entitätsspezifisch relevanter immunonkologischer Kontext.":"MMR/MSI και TMB ως entity-relevant ανοσο-ογκολογικό πλαίσιο.","FFPE-Lebermetastase, Block H2.":"FFPE ηπατική μετάσταση, block H2.","ca. 50 %, gut geeignet.":"περ. 50%, πολύ κατάλληλο.","PD-L1 ist technisch messbar, seine prädiktive Bedeutung ist aber entitäts- und therapiespezifisch; ein numerisch hoher Score ist nicht automatisch ein universeller IO-Biomarker.":"Το PD-L1 είναι τεχνικά μετρήσιμο, αλλά η προβλεπτική του σημασία είναι entity- και therapy-specific· ένας αριθμητικά υψηλός score δεν αποτελεί αυτόματα καθολικό IO biomarker.","Immunonkologischer Kontext":"Ανοσο-ογκολογικό πλαίσιο","Erhaltene nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Διατηρημένη πυρηνική έκφραση MLH1, PMS2, MSH2 και MSH6: pMMR.","MSS. Damit fehlt der für mCRC etablierte dMMR/MSI-H-Immuntherapiekontext.":"MSS. Επομένως απουσιάζει το καθιερωμένο dMMR/MSI-H πλαίσιο ανοσοθεραπείας για mCRC.","TMB niedrig (4,0 Mut/Mb).":"TMB χαμηλό (4,0 Mut/Mb).","PD-L1 CPS 25 bestätigt. Die Expression ist biologisch real, aber im pMMR/MSS-mCRC kein Ersatz für einen validierten MSI/dMMR-basierten Selektionsmarker.":"PD-L1 CPS 25 επιβεβαιώνεται. Η έκφραση είναι βιολογικά πραγματική, αλλά στο pMMR/MSS mCRC δεν αντικαθιστά επικυρωμένο δείκτη επιλογής βάσει MSI/dMMR.","TIL-Kontext":"Πλαίσιο TIL","Nur wenige intratumorale CD8-positive T-Zellen; kein ausgeprägt inflamed/hot pattern.":"Μόνο λίγα ενδοογκικά CD8-θετικά Τ κύτταρα· χωρίς έντονο inflamed/hot pattern.","Kernausgangslage":"Κεντρική αφετηρία","PD-L1 CPS 25 bei mCRC ohne morphologisch ausgeprägtes Immuninfiltrat.":"PD-L1 CPS 25 σε mCRC χωρίς μορφολογικά έντονο ανοσολογικό διήθημα.","MMR-IHC, MSI und DNA-basierte Zusatzanalysen technisch verwertbar.":"MMR IHC, MSI και DNA-based πρόσθετες αναλύσεις τεχνικά αξιοποιήσιμες.","Metastasiertes CRC mit realer PD-L1-Expression, aber pMMR/MSS, niedriger TMB und spärlichem intratumoralem T-Zell-Infiltrat. PD-L1-Positivität allein begründet in diesem Kontext keine etablierte PD-1-Monotherapie. Für mCRC besitzt dMMR/MSI-H eine deutlich stärkere und validierte prädiktive Rolle; experimentelle Kombinationen bei pMMR/MSS gehören in einen Studien-/Evidenzkontext.":"Μεταστατικό CRC με πραγματική έκφραση PD-L1, αλλά pMMR/MSS, χαμηλό TMB και αραιό ενδοογκικό διήθημα Τ κυττάρων. Η θετικότητα PD-L1 μόνη της δεν τεκμηριώνει καθιερωμένη μονοθεραπεία PD-1 σε αυτό το πλαίσιο. Στο mCRC, dMMR/MSI-H έχει σαφώς ισχυρότερο και επικυρωμένο προβλεπτικό ρόλο· πειραματικοί συνδυασμοί στο pMMR/MSS ανήκουν σε πλαίσιο μελέτης/τεκμηρίωσης.","Teilbefund: PD-L1 ist hoch, aber ohne MMR/MSI-Kontext ist die Übertragbarkeit auf eine Therapieentscheidung nicht belastbar.":"Μερικό αποτέλεσμα: PD-L1 είναι υψηλό, αλλά χωρίς πλαίσιο MMR/MSI η μεταφορά του σε θεραπευτική απόφαση δεν είναι αξιόπιστη.","PD-L1-Bedeutung entitätsspezifisch einordnen":"Ερμηνεύστε τη σημασία PD-L1 με entity-specific τρόπο","pMMR/MSS als entscheidenden Gegenbefund zur einfachen PD-L1-Logik benennen":"Αναφέρετε pMMR/MSS ως καθοριστικό αντεπιχείρημα στην απλή λογική PD-L1","niedrige TMB und spärliches Infiltrat als zusätzliche Kontextmarker integrieren":"Ενσωματώστε χαμηλό TMB και αραιό διήθημα ως πρόσθετους δείκτες πλαισίου","pMMR/MSS-IO-Kombinationen nicht mit etablierter Monotherapie gleichsetzen":"Μην εξισώνετε pMMR/MSS IO combinations με καθιερωμένη μονοθεραπεία","Falschaussage: Hoher PD-L1-Score ist tumoragnostisch immer prädiktiv":"Λανθασμένη δήλωση: υψηλό PD-L1 score είναι πάντα tumor-agnostic προβλεπτικό","Optimale Lösung: PD-L1 CPS 25 ist kein universeller IO-Schalter. Im pMMR/MSS-mCRC mit niedriger TMB und wenig TILs darf der Score die entitätsspezifisch validierte Biomarkerhierarchie nicht überstimmen; experimentelle Strategien gehören in Studien.":"Βέλτιστη λύση: PD-L1 CPS 25 δεν είναι καθολικός διακόπτης IO. Σε pMMR/MSS mCRC με χαμηλό TMB και λίγα TILs, το score δεν πρέπει να υπερισχύει της entity-specific επικυρωμένης ιεραρχίας βιοδεικτών· οι πειραματικές στρατηγικές ανήκουν σε μελέτες.","TIL-low":"TIL-low","Immuntherapie":"Ανοσοθεραπεία","Biomarkerhierarchie":"Ιεραρχία βιοδεικτών","PD-L1 CPS 25 und trotzdem kein ICI-Biomarker: MSS-mCRC als Überinterpretationsfalle":"PD-L1 CPS 25 και παρ’ όλα αυτά χωρίς ICI biomarker: MSS mCRC ως παγίδα υπερερμηνείας","PD-L1 als entitätsabhängigen und nicht tumoragnostischen Biomarker verstehen.":"Κατανοήστε το PD-L1 ως entity-dependent και όχι tumor-agnostic βιοδείκτη.","Beim mCRC dMMR/MSI-H gegenüber PD-L1 als prädiktiv stärker validierten IO-Kontext priorisieren.":"Στο mCRC, δώστε προτεραιότητα σε dMMR/MSI-H έναντι PD-L1 ως ισχυρότερα επικυρωμένο προβλεπτικό πλαίσιο IO.","pMMR/MSS, niedrige TMB und TIL-Armut als konsistente Gegenkonstellation zu einer simplen PD-L1-Logik integrieren.":"Ενσωματώστε pMMR/MSS, χαμηλό TMB και φτωχά TILs ως συνεπή αντιπαράθεση στην απλή λογική PD-L1.","PD-L1-Score und zelluläre Quelle/Spatial Context nicht mit universeller Therapieindikation verwechseln.":"Μην συγχέετε PD-L1 score και κυτταρική πηγή/χωρικό πλαίσιο με καθολική θεραπευτική ένδειξη.","Experimentelle ICI-Kombinationen im pMMR/MSS-mCRC von etablierter Monotherapie unterscheiden.":"Διαχωρίστε πειραματικούς ICI συνδυασμούς στο pMMR/MSS mCRC από καθιερωμένη μονοθεραπεία.","Der Außenbefund klingt spektakulär: PD-L1 CPS 25. Im Tumorboard kommt sofort die Frage nach Pembrolizumab. Doch die Histologie ist lymphozytenarm, die MMR-Proteine sind erhalten und der Tumor ist MSS. Der Fall ist ein Lehrstück dafür, dass derselbe Biomarkerwert je nach Tumorentität völlig unterschiedliche klinische Bedeutung haben kann.":"Το εξωτερικό report ακούγεται εντυπωσιακό: PD-L1 CPS 25. Στο tumor board προτείνεται αμέσως pembrolizumab. Όμως η ιστολογία είναι φτωχή σε λεμφοκύτταρα, οι πρωτεΐνες MMR διατηρούνται και ο όγκος είναι MSS. Η περίπτωση δείχνει ότι η ίδια τιμή βιοδείκτη μπορεί να έχει εντελώς διαφορετική κλινική σημασία ανάλογα με την οντότητα όγκου.","61-jährige Patientin mit mehrfach vorbehandeltem metastasiertem kolorektalem Adenokarzinom. Eine Metastasenbiopsie zeigt PD-L1 CPS 25. Gesucht ist eine evidenzbasierte Einordnung, ob dieser Wert im pMMR/MSS-mCRC eine etablierte PD-1-Monotherapie begründet oder ob die entitätsspezifische MSI/dMMR-Hierarchie Vorrang hat.":"Ασθενής 61 ετών με πολυθεραπευμένο μεταστατικό κολοορθικό αδενοκαρκίνωμα. Βιοψία μετάστασης δείχνει PD-L1 CPS 25. Ζητείται evidence-based εκτίμηση αν αυτή η τιμή στηρίζει καθιερωμένη μονοθεραπεία PD-1 σε pMMR/MSS mCRC ή αν υπερισχύει η entity-specific ιεραρχία MSI/dMMR.","Hohe Zahl, falsche Abkürzung":"Υψηλός αριθμός, λάθος συντόμευση","PD-L1 CPS 25 wird als 'positiv' hervorgehoben.":"PD-L1 CPS 25 επισημαίνεται ως «θετικό».","Ein numerisch hoher Wert ist nur dann prädiktiv, wenn Assay, Scoring, Entität und Therapie dafür validiert sind.":"Μια αριθμητικά υψηλή τιμή είναι προβλεπτική μόνο αν assay, scoring, entity και θεραπεία έχουν επικυρωθεί για αυτή τη χρήση.","CRC-spezifische Hierarchie":"CRC-specific ιεραρχία","MMR/MSI ist für die IO-Selektion beim mCRC zentral.":"MMR/MSI είναι κεντρικό για επιλογή IO στο mCRC.","Biomarker dürfen nicht entitätsübergreifend ohne Evidenz transferiert werden.":"Οι βιοδείκτες δεν πρέπει να μεταφέρονται μεταξύ οντοτήτων χωρίς τεκμηρίωση.","Biologisches Gesamtbild":"Συνολική βιολογική εικόνα","TMB-low und TIL-arm.":"TMB-low και TIL-poor.","Mehrere unabhängige Kontextsignale sprechen gegen die einfache Annahme eines hoch immunogenen Tumors.":"Πολλαπλά ανεξάρτητα contextual signals συνηγορούν κατά της απλής υπόθεσης ενός ιδιαίτερα ανοσογονικού όγκου.","PD-L1 Außenbefund":"Εξωτερικό αποτέλεσμα PD-L1","CPS 25, überwiegend an Tumor-/Stromagrenzen und Immunzellen.":"CPS 25, κυρίως στα όρια όγκου/στρώματος και σε ανοσοκύτταρα.","Keine ausgeprägt lymphozytenreiche CRC-Morphologie.":"Χωρίς έντονα λεμφοκυτταροβριθή μορφολογία CRC.","Lebermetastase mit ca. 50 % Tumoranteil.":"Ηπατική μετάσταση με περ. 50% όγκο.","MMR-IHC und MSI-Testung sind mit wenig Material möglich und beantworten die entscheidende CRC-spezifische Frage direkter als wiederholte PD-L1-IHC.":"MMR IHC και MSI testing απαιτούν λίγο υλικό και απαντούν πιο άμεσα στο καθοριστικό CRC-specific ερώτημα από επαναλαμβανόμενο PD-L1 IHC.","TMB ist additive Kontextinformation und darf MSI/dMMR nicht ersetzen.":"Το TMB είναι πρόσθετη contextual πληροφορία και δεν πρέπει να αντικαθιστά MSI/dMMR.","Breite Zusatzdiagnostik soll nicht nur deshalb erfolgen, weil ein einzelner PD-L1-Score klinisch verlockend wirkt.":"Ευρύς πρόσθετος έλεγχος δεν πρέπει να γίνεται μόνο επειδή ένα μεμονωμένο PD-L1 score φαίνεται κλινικά δελεαστικό.","Wie ist PD-L1 CPS 25 im mCRC grundsätzlich zu behandeln?":"Πώς πρέπει γενικά να αντιμετωπίζεται PD-L1 CPS 25 στο mCRC;","Als entitätsspezifisch zu interpretierender Kontextbefund; nicht als universeller tumoragnostischer ICI-Schalter.":"Ως contextual εύρημα που πρέπει να ερμηνεύεται ανά οντότητα· όχι ως καθολικός tumor-agnostic διακόπτης ICI.","CPS ≥10 ist bei jeder soliden Tumorentität automatisch prädiktiv.":"CPS ≥10 είναι αυτόματα προβλεπτικό σε κάθε οντότητα συμπαγούς όγκου.","PD-L1-IHC ist im CRC technisch grundsätzlich ungültig.":"PD-L1 IHC είναι εξ ορισμού τεχνικά άκυρο στο CRC.","PD-L1 CPS 25 beweist MSI-H.":"PD-L1 CPS 25 αποδεικνύει MSI-H.","Prädiktive Biomarker funktionieren nur in validiertem Entitäts-/Therapiekontext.":"Οι προβλεπτικοί βιοδείκτες λειτουργούν μόνο σε επικυρωμένο entity/treatment context.","Welcher Befund besitzt beim mCRC die klarere etablierte IO-Relevanz?":"Ποιο εύρημα έχει σαφέστερη καθιερωμένη σημασία IO στο mCRC;","dMMR/MSI-H.":"dMMR/MSI-H.","PD-L1 CPS allein.":"Μόνο PD-L1 CPS.","TIL-Zahl allein.":"Μόνο ο αριθμός των TIL.","Tumornekrose allein.":"Μόνο η νέκρωση του όγκου.","dMMR/MSI-H ist der etablierte zentrale Immuntherapie-Biomarkerkontext im mCRC.":"Το dMMR/MSI-H αποτελεί το καθιερωμένο κεντρικό πλαίσιο βιοδεικτών ανοσοθεραπείας στο mCRC.","PD-L1 CPS 25, aber pMMR/MSS und TMB 4 Mut/Mb. Was ist die sauberste Aussage?":"PD-L1 CPS 25, αλλά pMMR/MSS και TMB 4 mut/Mb. Ποια είναι η καταλληλότερη διατύπωση;","PD-L1 überstimmt pMMR/MSS nicht; daraus folgt keine etablierte PD-1-Monotherapie. Studienstrategien müssen als experimentell gekennzeichnet werden.":"Το PD-L1 δεν υπερισχύει του pMMR/MSS· αυτό δεν τεκμηριώνει καθιερωμένη ένδειξη για μονοθεραπεία anti-PD-1. Οι στρατηγικές μελετών πρέπει να χαρακτηρίζονται ως πειραματικές.","Hoher CPS macht die Monotherapie unabhängig von MSI zum Standard.":"Ένα υψηλό CPS καθιστά τη μονοθεραπεία πρότυπο ανεξάρτητα από το MSI.","Ein pMMR/MSS-CRC kann in keiner Studie jemals auf Immuntherapie reagieren.":"Ένα CRC pMMR/MSS δεν μπορεί ποτέ να ανταποκριθεί σε ανοσοθεραπεία σε καμία μελέτη.","CPS 25 definiert automatisch TMB-high.":"Το CPS 25 ορίζει αυτόματα TMB-high.","Fehlende etablierte Monotherapie-Indikation ist nicht gleichbedeutend mit biologisch unmöglicher Aktivität in Studienkombinationen.":"Η απουσία καθιερωμένης ένδειξης μονοθεραπείας δεν σημαίνει ότι η δραστικότητα σε ερευνητικούς συνδυασμούς είναι βιολογικά αδύνατη.","Warum ist es hilfreich zu wissen, woher der CPS stammt?":"Γιατί είναι χρήσιμο να γνωρίζουμε από πού προέρχεται το CPS;","PD-L1-positive Immunzellen an Stromagrenzen können den Score erhöhen, ohne ein dichtes intratumorales Effektor-T-Zell-Infiltrat zu belegen.":"PD-L1-θετικά ανοσοκύτταρα στα όρια του στρώματος μπορούν να αυξήσουν το score χωρίς να αποδεικνύουν πυκνή ενδοογκική διήθηση από ενεργά Τ-κύτταρα.","Immunzell-PD-L1 beweist immer bessere ICI-Wirkung.":"Το PD-L1 στα ανοσοκύτταρα αποδεικνύει πάντα καλύτερη αποτελεσματικότητα των ICI.","CPS darf Immunzellen niemals berücksichtigen.":"Το CPS δεν πρέπει ποτέ να περιλαμβάνει ανοσοκύτταρα.","Zelluläre Quelle und räumlicher Kontext sind grundsätzlich irrelevant.":"Η κυτταρική προέλευση και το χωρικό πλαίσιο είναι θεμελιωδώς άσχετα.","Score und räumliche Immunbiologie sind unterschiedliche Informationsebenen.":"Το score και η χωρική ανοσοβιολογία αποτελούν διαφορετικά επίπεδα πληροφορίας.","Entscheiden Sie, wie PD-L1 CPS 25 im pMMR/MSS-mCRC berichtet und im MTB gewichtet wird, ohne den Befund zu ignorieren oder ihn entitätsfremd zur etablierten ICI-Indikation aufzuwerten.":"Αποφασίστε πώς πρέπει να αναφερθεί και να σταθμιστεί στο MTB ένα PD-L1 CPS 25 σε pMMR/MSS mCRC, χωρίς να αγνοηθεί το εύρημα ούτε να αναβαθμιστεί εκτός του επικυρωμένου, ειδικού για την οντότητα πλαισίου ένδειξης ICI.","PD-L1 CPS 25 als technisch realen Befund anerkennen.":"Αναγνωρίστε το PD-L1 CPS 25 ως τεχνικά πραγματικό εύρημα.","MMR-IHC und MSI prüfen: pMMR/MSS.":"Ελέγξτε MMR-IHC και MSI: pMMR/MSS.","TMB als niedrig und TIL-Infiltrat als spärlich einordnen.":"Χαρακτηρίστε το TMB ως χαμηλό και τη διήθηση TIL ως αραιή.","PD-L1 im CRC nicht als tumoragnostischen Therapie-Schalter formulieren.":"Μη διατυπώνετε το PD-L1 στο CRC ως tumor-agnostic διακόπτη θεραπείας.","Keine etablierte PD-1-Monotherapie aus PD-L1 allein ableiten.":"Μην εξάγετε καθιερωμένη ένδειξη μονοθεραπείας anti-PD-1 μόνο από το PD-L1.","Experimentelle pMMR/MSS-IO-Kombinationen ausschließlich als Studienoption/Evidenzentwicklung kennzeichnen.":"Χαρακτηρίστε τους πειραματικούς συνδυασμούς ανοσοθεραπείας σε pMMR/MSS αποκλειστικά ως επιλογές μελέτης/εξελισσόμενη τεκμηρίωση.","MMR-IHC plus MSI-Test; TMB nur ergänzend, wenn bereits aus validiertem Panel verfügbar.":"MMR-IHC συν έλεγχος MSI· TMB μόνο συμπληρωματικά εφόσον είναι ήδη διαθέσιμο από επικυρωμένο panel.","Bei klarem pMMR/MSS kann auf wiederholte PD-L1-IHC verzichtet werden, wenn sie die klinische Entscheidung nicht verändert.":"Με σαφώς τεκμηριωμένο pMMR/MSS, η επανάληψη PD-L1-IHC μπορεί να παραλειφθεί εάν δεν αλλάζει την κλινική απόφαση.","CPS aus anderer Entität übertragen":"Μεταφορά CPS από άλλη οντότητα όγκου","PD-L1-Cutoffs sind nicht tumoragnostisch austauschbar.":"Τα cutoffs του PD-L1 δεν είναι εναλλάξιμα μεταξύ διαφορετικών τύπων όγκων.","PD-L1 ignorieren":"Αγνοήστε το PD-L1","Der Befund ist biologisch real und kann Forschung/Studienkontext informieren; er ist nur nicht der etablierte Selektionsmarker.":"Το εύρημα είναι βιολογικά πραγματικό και μπορεί να ενημερώσει το ερευνητικό/μελετητικό πλαίσιο· απλώς δεν αποτελεί τον καθιερωμένο βιοδείκτη επιλογής.","pMMR/MSS = absolute Immunresistenz":"pMMR/MSS = απόλυτη ανοσολογική αντίσταση","Das wäre zu absolut; Studienkombinationen werden untersucht.":"Αυτό θα ήταν υπερβολικά απόλυτο· διερευνώνται πειραματικοί συνδυασμοί.","TMB ersetzt MSI":"Το TMB αντικαθιστά το MSI","TMB und MSI sind verwandte, aber nicht austauschbare Biomarker.":"TMB και MSI είναι σχετιζόμενοι αλλά μη εναλλάξιμοι βιοδείκτες.","Die 25 ist echt – aber klinisch nicht der Hauptmarker":"Το 25 είναι πραγματικό — αλλά κλινικά δεν είναι ο κύριος δείκτης","PD-L1 CPS 25 wird bestätigt. Gleichzeitig zeigen MMR-IHC und MSI-Testung pMMR/MSS, TMB liegt bei 4 Mut/Mb und CD8-T-Zellen sind spärlich. Der Twist ist nicht, dass PD-L1 'falsch' war, sondern dass ein realer positiver Befund außerhalb seines validierten Entitätskontexts therapeutisch viel weniger trägt.":"Επιβεβαιώνεται PD-L1 CPS 25. Ταυτόχρονα, MMR-IHC και έλεγχος MSI δείχνουν pMMR/MSS, το TMB είναι 4 mut/Mb και τα CD8 Τ-κύτταρα είναι αραιά. Το twist δεν είναι ότι το PD-L1 ήταν «λάθος», αλλά ότι ένα πραγματικά θετικό εύρημα έχει πολύ μικρότερο θεραπευτικό βάρος εκτός του επικυρωμένου, ειδικού για την οντότητα πλαισίου.","So wird die zentrale Präzisionsonkologie-Kompetenz trainiert: Biomarker werden nicht nach Positiv/Negativ, sondern nach Evidenz, Entität und Therapiehierarchie interpretiert.":"Έτσι εκπαιδεύεται μια βασική δεξιότητα της ογκολογίας ακριβείας: οι βιοδείκτες δεν ερμηνεύονται απλώς ως θετικοί/αρνητικοί, αλλά με βάση την τεκμηρίωση, την οντότητα και την ιεραρχία θεραπείας.","PD-L1 entitätsspezifisch begrenzt":"PD-L1 με περιορισμό βάσει του ειδικού για την οντότητα πλαισίου","PD-L1 CPS 25, pMMR/MSS, TMB 4 Mut/Mb, TIL-arm. Keine etablierte PD-1-Monotherapie aus PD-L1 allein; dMMR/MSI-H wäre der relevante validierte IO-Kontext. Studienkombinationen klar als experimentell kennzeichnen.":"PD-L1 CPS 25, pMMR/MSS, TMB 4 mut/Mb, λίγα TIL. Δεν τεκμηριώνεται καθιερωμένη μονοθεραπεία anti-PD-1 μόνο από το PD-L1· το dMMR/MSI-H θα ήταν το σχετικό επικυρωμένο πλαίσιο ICI. Οι συνδυασμοί μελετών να χαρακτηρίζονται σαφώς ως πειραματικοί.","Biomarkerhierarchie sauber getroffen.":"Η ιεραρχία των βιοδεικτών προσδιορίστηκε σωστά.","MSS erkannt, PD-L1 aber nicht eingeordnet":"Αναγνωρίστηκε MSS, αλλά το PD-L1 δεν εντάχθηκε στο σωστό πλαίσιο","pMMR/MSS wird berichtet, der hohe CPS bleibt ohne Erklärung im Raum.":"Αναφέρεται pMMR/MSS, αλλά το υψηλό CPS παραμένει χωρίς ερμηνεία.","Der wichtigste Lernkonflikt wird nicht aufgelöst.":"Η βασική μαθησιακή σύγκρουση παραμένει άλυτη.","CPS 25 = Pembrolizumab":"CPS 25 = pembrolizumab","PD-L1 wird entitätsübergreifend als Standardindikation interpretiert.":"Το PD-L1 ερμηνεύεται δια-οντολογικά ως τυπική ένδειξη.","Validierungskontext missachtet.":"Παραβλέπεται το πλαίσιο επικύρωσης.","Nicht-MSI-basierte Routineoptionen und geeignete klinische Studien prüfen.":"Αξιολογήστε καθιερωμένες επιλογές που δεν βασίζονται στο MSI και κατάλληλες κλινικές μελέτες.","Experimentelle Immuntherapiestrategien bleiben möglich, aber werden nicht als etablierte Monotherapie verkauft.":"Οι πειραματικές στρατηγικές ανοσοθεραπείας παραμένουν δυνατές, αλλά δεν πρέπει να παρουσιάζονται ως καθιερωμένη μονοθεραπεία.","PD-L1 ist kein tumoragnostischer Biomarker.":"Το PD-L1 δεν είναι tumor-agnostic βιοδείκτης.","Im mCRC hat dMMR/MSI-H eine zentrale etablierte prädiktive Rolle für Checkpoint-Inhibition.":"Στο mCRC, το dMMR/MSI-H έχει κεντρικό και καθιερωμένο προβλεπτικό ρόλο για την αναστολή immune checkpoints.","pMMR/MSS und niedrige TMB/TILs relativieren die intuitive Interpretation eines hohen PD-L1-Scores.":"Το pMMR/MSS και τα χαμηλά TMB/TIL μετριάζουν τη διαισθητική ερμηνεία ενός υψηλού score PD-L1.","Ein positiver Labormarker kann korrekt gemessen und trotzdem klinisch nicht entscheidend sein.":"Ένας θετικός εργαστηριακός δείκτης μπορεί να έχει μετρηθεί σωστά και παρ’ όλα αυτά να μην είναι κλινικά καθοριστικός.","Studienevidenz bei pMMR/MSS darf nicht mit Routine-Standard gleichgesetzt werden.":"Η τεκμηρίωση από μελέτες σε pMMR/MSS δεν πρέπει να εξισώνεται με το πρότυπο φροντίδας ρουτίνας.","PD-L1 CPS 25 ist ein realer Kontextbefund, aber im pMMR/MSS-mCRC kein etablierter Ersatz für dMMR/MSI-H. TMB ist niedrig, TILs spärlich. Daher keine etablierte PD-1-Monotherapie allein aus dem CPS ableiten; Studienkombinationen nur als experimentelle Optionen kommunizieren.":"Το PD-L1 CPS 25 είναι πραγματικό εύρημα πλαισίου, αλλά σε pMMR/MSS mCRC δεν αποτελεί καθιερωμένο υποκατάστατο του dMMR/MSI-H. Το TMB είναι χαμηλό και τα TIL αραιά. Επομένως, μην εξάγετε καθιερωμένη μονοθεραπεία anti-PD-1 μόνο από το CPS· οι συνδυασμοί μελετών να επικοινωνούνται μόνο ως πειραματικές επιλογές.","Entitätsspezifität":"Ειδικότητα ανά οντότητα","MMR/MSI priorisiert":"Προτεραιοποίηση MMR/MSI","PD-L1 nicht ignoriert, aber begrenzt":"Το PD-L1 δεν αγνοείται, αλλά περιορίζεται κατάλληλα","Studie vs. Standard getrennt":"Διαχωρισμός μελέτης και προτύπου θεραπείας","Warum kann derselbe PD-L1-Score in zwei Tumorentitäten unterschiedliche Bedeutung besitzen?":"Γιατί το ίδιο score PD-L1 μπορεί να έχει διαφορετική σημασία σε δύο οντότητες όγκου;","Welche Biomarker sind tumoragnostisch zugelassen und welche nicht?":"Ποιοι βιοδείκτες έχουν tumor-agnostic εγκρίσεις και ποιοι όχι;","Wie formuliert man einen 'positiven, aber nicht entscheidenden' Marker verständlich im Befund?":"Πώς διατυπώνετε με σαφήνεια σε μια έκθεση έναν «θετικό αλλά μη καθοριστικό» δείκτη;","PD-L1 CPS 25 wird durch pMMR/MSS/TMB-low relativiert":"Το PD-L1 CPS 25 μετριάζεται από pMMR/MSS/TMB-low","Biomarkerpositivität ist ohne Entitätsvalidierung keine Therapieindikation":"Η θετικότητα ενός βιοδείκτη δεν αποτελεί θεραπευτική ένδειξη χωρίς επικύρωση ειδική για την οντότητα","PD-L1 → MMR/MSI → TMB/TIL → Evidenzhierarchie":"PD-L1 → MMR/MSI → TMB/TIL → ιεραρχία τεκμηρίωσης","MSI-H-Karzinom: Therapieoption und Lynch-Abklärung → IO, MMR-IHC, Keimbahnkontext":"Καρκίνωμα MSI-H: θεραπευτική επιλογή και διερεύνηση Lynch → IO, MMR-IHC, πλαίσιο βλαστικής σειράς","MSI-H-Karzinom: Therapieoption und…":"Καρκίνωμα MSI-H: θεραπευτική επιλογή και…","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und pulmonalen Metastasen. Im Primärtumor war keine strukturierte MMR-/Lynch-Abklärung dokumentiert.":"49χρονη ασθενής με υποτροπιάζον ενδομητριοειδές καρκίνωμα ενδομητρίου και πνευμονικές μεταστάσεις. Στον πρωτοπαθή όγκο δεν είχε τεκμηριωθεί οργανωμένος έλεγχος MMR/Lynch.","Ist der Tumor dMMR/MSI-H und damit immuntherapeutisch relevant? Welche Reflexdiagnostik ist bei einem MMR-Verlust erforderlich, und wann muss Humangenetik folgen?":"Είναι ο όγκος dMMR/MSI-H και επομένως σχετικός με ανοσοθεραπεία; Ποιος αντανακλαστικός έλεγχος απαιτείται σε απώλεια MMR και πότε πρέπει να ακολουθήσει γενετική διερεύνηση;","Die molekulare Einordnung soll Therapieplanung und hereditäre Beratung parallel strukturieren.":"Η μοριακή ταξινόμηση πρέπει να οργανώσει παράλληλα τον θεραπευτικό σχεδιασμό και τη συμβουλευτική για κληρονομική προδιάθεση.","Alter":"Ηλικία","49 Jahre bei aktueller Rezidivsituation.":"49 ετών κατά την τρέχουσα υποτροπή.","Mutter mit Kolonkarzinom mit 52 Jahren; mütterlicher Onkel mit Urothelkarzinom des oberen Harntrakts.":"Μητέρα με καρκίνο παχέος εντέρου στα 52 έτη· μητρικός θείος με ουροθηλιακό καρκίνωμα ανώτερου ουροποιητικού.","Außenbefund nennt 'MSI verdächtig', ohne dokumentierte MMR-IHC oder MLH1-Methylierung.":"Η εξωτερική γνωμάτευση αναφέρει «ύποπτο για MSI» χωρίς τεκμηριωμένη MMR-IHC ή μεθυλίωση MLH1.","CRC-Reflexdiagnostik wird unverändert auf das Endometriumkarzinom übertragen – insbesondere BRAF-V600E statt MLH1-Promotormethylierung.":"Η αντανακλαστική διαγνωστική του CRC μεταφέρεται αυτούσια στο καρκίνωμα ενδομητρίου — ιδιαίτερα το BRAF V600E αντί της μεθυλίωσης του υποκινητή MLH1.","Endometrioides Endometriumkarzinom, high-grade, mit fokal lymphozytenreichem Stroma.":"Υψηλού βαθμού ενδομητριοειδές καρκίνωμα ενδομητρίου με εστιακά λεμφοκυτταροβριθές στρώμα.","Rezidiv-/Metastasenmaterial bestätigt endometrialen Ursprung.":"Το υλικό από υποτροπή/μετάσταση επιβεβαιώνει ενδομητρική προέλευση.","MMR-Proteinmuster, MSI-Status und bei MLH1/PMS2-Verlust die Frage einer sporadischen MLH1-Promotormethylierung.":"Το πρότυπο πρωτεϊνών MMR, η κατάσταση MSI και, σε απώλεια MLH1/PMS2, το ενδεχόμενο σποραδικής μεθυλίωσης του υποκινητή MLH1.","Therapiebiomarker und Lynch-Screening nutzen dieselbe MMR-Biologie, führen aber zu unterschiedlichen nächsten Schritten.":"Ο θεραπευτικός βιοδείκτης και ο έλεγχος Lynch βασίζονται στην ίδια βιολογία MMR, αλλά οδηγούν σε διαφορετικά επόμενα βήματα.","FFPE-Resektat des Primärtumors plus aktuelle Metastasenbiopsie.":"FFPE υλικό εκτομής του πρωτοπαθούς όγκου και πρόσφατη βιοψία μετάστασης.","Primärtumor ca. 60 %, DNA gut geeignet.":"Πρωτοπαθής όγκος περίπου 60%, DNA καλής καταλληλότητας.","Ausreichend für MMR-IHC und molekulare Reflexdiagnostik.":"Επαρκές για MMR-IHC και μοριακό αντανακλαστικό έλεγχο.","BRAF V600E ist als Lynch-Reflex aus dem CRC-Kontext bekannt, beantwortet beim Endometriumkarzinom aber nicht die entscheidende sporadisch-vs.-hereditär-Frage.":"Το BRAF V600E είναι γνωστό ως αντανακλαστικός έλεγχος Lynch στο CRC, αλλά στο καρκίνωμα ενδομητρίου δεν απαντά στο κρίσιμο ερώτημα σποραδικό έναντι κληρονομικού.","MSI-Bestätigung":"Επιβεβαίωση MSI","MLH1-Reflexdiagnostik":"Αντανακλαστικός έλεγχος MLH1","Hereditäre Weiterleitung":"Παραπομπή για κληρονομική διερεύνηση","Verlust von MLH1 und PMS2 bei erhaltener Expression von MSH2 und MSH6: dMMR-Muster.":"Απώλεια MLH1 και PMS2 με διατηρημένη έκφραση MSH2 και MSH6: πρότυπο dMMR.","MSI-high, konsistent mit dem dMMR-Befund.":"MSI-high, συμβατό με το εύρημα dMMR.","MLH1-Promotormethylierung":"Μεθυλίωση υποκινητή MLH1","Keine MLH1-Promotor-Hypermethylierung nachweisbar. Damit ist eine häufige sporadische Ursache des MLH1/PMS2-Verlusts nicht belegt; Lynch-Syndrom bleibt abklärungsbedürftig, ist aber noch nicht bewiesen.":"Δεν ανιχνεύεται υπερμεθυλίωση του υποκινητή MLH1. Επομένως δεν τεκμηριώνεται μια συχνή σποραδική αιτία της απώλειας MLH1/PMS2· το σύνδρομο Lynch εξακολουθεί να απαιτεί διερεύνηση, αλλά δεν έχει ακόμη αποδειχθεί.","BRAF-V600E-Testung ist hier kein geeigneter Lynch-Screening-Reflex. Die aus dem CRC bekannte BRAF-Logik darf nicht auf das Endometriumkarzinom übertragen werden.":"Ο έλεγχος BRAF V600E δεν αποτελεί εδώ κατάλληλο αντανακλαστικό τεστ για screening Lynch. Η λογική BRAF από το CRC δεν πρέπει να μεταφέρεται στο καρκίνωμα ενδομητρίου.","Humangenetische Beratung und Keimbahndiagnostik der MMR/Lynch-relevanten Gene werden empfohlen; der Tumorbefund allein stellt keine Lynch-Diagnose.":"Συνιστώνται γενετική συμβουλευτική και έλεγχος βλαστικής σειράς των σχετικών με MMR/Lynch γονιδίων· το αποτέλεσμα του όγκου από μόνο του δεν τεκμηριώνει διάγνωση συνδρόμου Lynch.","PD-L1/TMB Zusatzkontext":"Συμπληρωματικό πλαίσιο PD-L1/TMB","Zusatzmarker können berichtet werden, stehen aber hinter dem robusten dMMR/MSI-H-Befund zurück und sind für die Lynch-Reflexdiagnostik nicht entscheidend.":"Πρόσθετοι δείκτες μπορούν να αναφερθούν, αλλά παραμένουν δευτερεύοντες έναντι του ισχυρού ευρήματος dMMR/MSI-H και δεν είναι καθοριστικοί για την αντανακλαστική διερεύνηση Lynch.","Rezidiviertes Endometriumkarzinom bei junger Patientin mit auffälliger Familienanamnese.":"Υποτροπιάζον καρκίνωμα ενδομητρίου σε νεαρή ασθενή με επιβαρυμένο οικογενειακό ιστορικό.","MMR-IHC und MSI-/Methylierungsdiagnostik technisch verwertbar.":"MMR-IHC και έλεγχος MSI/μεθυλίωσης είναι τεχνικά αξιολογήσιμα.","Rezidiviertes Endometriumkarzinom mit MLH1/PMS2-Verlust und MSI-H. Der dMMR/MSI-H-Befund ist therapeutisch relevant. Da keine MLH1-Promotor-Hypermethylierung nachweisbar ist, bleibt ein Lynch-Syndrom abklärungsbedürftig und erfordert humangenetische Beratung/Keimbahndiagnostik. BRAF V600E ist in diesem Endometrium-Kontext kein adäquater Ersatzreflex und Lynch ist aus dem Tumorbefund allein nicht bewiesen.":"Υποτροπιάζον καρκίνωμα ενδομητρίου με απώλεια MLH1/PMS2 και MSI-H. Το εύρημα dMMR/MSI-H είναι θεραπευτικά σημαντικό. Επειδή δεν ανιχνεύεται υπερμεθυλίωση του υποκινητή MLH1, το σύνδρομο Lynch εξακολουθεί να απαιτεί διερεύνηση με γενετική συμβουλευτική/έλεγχο βλαστικής σειράς. Το BRAF V600E δεν αποτελεί κατάλληλο υποκατάστατο αντανακλαστικό τεστ σε αυτό το ενδομητρικό πλαίσιο και το Lynch δεν αποδεικνύεται μόνο από το εύρημα του όγκου.","Teilbefund: dMMR/MSI-H ist erkannt, aber ohne MLH1-Methylierungsreflex und humangenetische Weiterleitung bleibt die hereditäre Ebene unvollständig.":"Μερικό αποτέλεσμα: αναγνωρίζεται dMMR/MSI-H, αλλά χωρίς αντανακλαστικό έλεγχο μεθυλίωσης MLH1 και παραπομπή σε γενετική, η κληρονομική διάσταση παραμένει ελλιπής.","dMMR/MSI-H als starken prädiktiven Immuntherapiekontext benennen":"Αναφέρετε το dMMR/MSI-H ως ισχυρό προβλεπτικό πλαίσιο ανοσοθεραπείας","MLH1/PMS2-Verlust korrekt als gekoppeltes MMR-Muster einordnen":"Ερμηνεύστε σωστά την απώλεια MLH1/PMS2 ως συζευγμένο πρότυπο MMR","MLH1-Promotormethylierung als passenden Endometrium-Reflex nutzen":"Χρησιμοποιήστε τη μεθυλίωση του υποκινητή MLH1 ως κατάλληλο αντανακλαστικό τεστ για το ενδομήτριο","fehlende Methylierung → Lynch-Abklärung empfehlen, aber Lynch nicht als bewiesen darstellen":"Απουσία μεθυλίωσης → συστήστε διερεύνηση Lynch, αλλά μην παρουσιάζετε το σύνδρομο Lynch ως αποδεδειγμένο","Falschaussage: BRAF-V600E ist auch beim Endometriumkarzinom der Standardreflex für MLH1/PMS2-Verlust":"Λανθασμένη δήλωση: το BRAF V600E είναι και στο καρκίνωμα ενδομητρίου το τυπικό αντανακλαστικό τεστ για απώλεια MLH1/PMS2","Optimale Lösung: MLH1/PMS2-Verlust + MSI-H therapeutisch kommunizieren; beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex prüfen. Fehlt die Methylierung, humangenetisch weiterleiten – ohne aus dem Tumorscreening bereits eine Lynch-Diagnose zu machen.":"Βέλτιστη λύση: επικοινωνήστε θεραπευτικά την απώλεια MLH1/PMS2 + MSI-H· στο καρκίνωμα ενδομητρίου, ελέγξτε αντανακλαστικά τη μεθυλίωση του υποκινητή MLH1. Εάν δεν υπάρχει μεθυλίωση, παραπέμψτε για γενετική διερεύνηση — χωρίς να μετατρέπετε το tumor screening από μόνο του σε διάγνωση Lynch.","Endometriumkarzinom":"Καρκίνωμα ενδομητρίου","dMMR":"dMMR","MSI-H":"MSI-H","MLH1":"MLH1","PMS2":"PMS2","Lynch":"Lynch","MSI-H und MLH1/PMS2-Verlust: Endometriumkarzinom zwischen Immuntherapie und Lynch-Abklärung":"MSI-H και απώλεια MLH1/PMS2: καρκίνωμα ενδομητρίου μεταξύ ανοσοθεραπείας και διερεύνησης Lynch","Molekularpathologie / Gynäko-Onkologie / Humangenetik / MTB":"Μοριακή Παθολογία / Γυναικολογική Ογκολογία / Ιατρική Γενετική / MTB","MMR-IHC-Muster korrekt lesen und MLH1/PMS2-Verlust funktionell einordnen.":"Διαβάστε σωστά το πρότυπο MMR-IHC και ερμηνεύστε λειτουργικά την απώλεια MLH1/PMS2.","dMMR/MSI-H gleichzeitig als prädiktiven Therapiebiomarker und als möglichen Hinweis auf hereditäre Prädisposition verstehen.":"Κατανοήστε το dMMR/MSI-H τόσο ως προβλεπτικό θεραπευτικό βιοδείκτη όσο και ως πιθανή ένδειξη κληρονομικής προδιάθεσης.","Beim Endometriumkarzinom MLH1-Promotormethylierung als passenden Reflex bei MLH1/PMS2-Verlust einsetzen.":"Στο καρκίνωμα ενδομητρίου, χρησιμοποιήστε τη μεθυλίωση του υποκινητή MLH1 ως κατάλληλο αντανακλαστικό τεστ για απώλεια MLH1/PMS2.","Den CRC-spezifischen BRAF-V600E-Reflex nicht unkritisch auf das Endometriumkarzinom übertragen.":"Μη μεταφέρετε άκριτα το ειδικό για CRC αντανακλαστικό BRAF V600E στο καρκίνωμα ενδομητρίου.","Fehlende MLH1-Methylierung als Anlass zur Lynch-Abklärung, nicht als bereits bewiesenes Lynch-Syndrom kommunizieren.":"Επικοινωνήστε την απουσία μεθυλίωσης MLH1 ως λόγο για διερεύνηση Lynch, όχι ως ήδη αποδεδειγμένο σύνδρομο Lynch.","Die MMR-IHC zeigt einen klaren MLH1/PMS2-Verlust, der MSI-Test ist high. Im Tumorboard sind sich alle einig, dass das therapeutisch wichtig ist. Dann kommt die zweite Frage: 'Dann machen wir jetzt BRAF wie beim Kolon?' Genau hier kippt der Fall von Immuntherapie in echte molekularpathologische Reflexdiagnostik.":"Η MMR-IHC δείχνει σαφή απώλεια MLH1/PMS2 και ο έλεγχος MSI είναι high. Στο tumor board όλοι συμφωνούν ότι αυτό είναι θεραπευτικά σημαντικό. Έπειτα έρχεται η δεύτερη ερώτηση: «Τότε κάνουμε τώρα BRAF, όπως στο κόλον;» Ακριβώς εδώ η περίπτωση μετατοπίζεται από την ανοσοθεραπεία σε πραγματική αντανακλαστική διαγνωστική μοριακής παθολογίας.","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und auffälliger Familienanamnese. Der Tumor ist dMMR/MSI-H mit MLH1/PMS2-Verlust. Gesucht wird die korrekte Trennung von unmittelbarer therapeutischer Relevanz und Lynch-Screening inklusive entitätsspezifischem MLH1-Methylierungsreflex.":"49χρονη ασθενής με υποτροπιάζον ενδομητριοειδές καρκίνωμα ενδομητρίου και επιβαρυμένο οικογενειακό ιστορικό. Ο όγκος είναι dMMR/MSI-H με απώλεια MLH1/PMS2. Στόχος είναι ο σωστός διαχωρισμός της άμεσης θεραπευτικής σημασίας από το screening Lynch, συμπεριλαμβανομένου του ειδικού για την οντότητα αντανακλαστικού ελέγχου μεθυλίωσης MLH1.","Ein Befund, zwei Konsequenzen":"Ένα εύρημα, δύο συνέπειες","dMMR/MSI-H ist therapie- und hereditär relevant.":"Το dMMR/MSI-H είναι σημαντικό τόσο θεραπευτικά όσο και για κληρονομική διερεύνηση.","Dieselbe Tumorbiologie kann unterschiedliche klinische Pfade auslösen.":"Η ίδια βιολογία όγκου μπορεί να ενεργοποιήσει διαφορετικές κλινικές διαδρομές.","Verlustmuster":"Πρότυπο απώλειας","MLH1 und PMS2 fehlen gemeinsam.":"MLH1 και PMS2 απουσιάζουν μαζί.","Das Heterodimer-Muster lenkt die Reflexdiagnostik auf MLH1.":"Το πρότυπο του ετεροδιμερούς κατευθύνει τον αντανακλαστικό έλεγχο προς το MLH1.","Entität zählt":"Η οντότητα του όγκου έχει σημασία","BRAF-Reflex ist aus dem CRC bekannt.":"Ο αντανακλαστικός έλεγχος BRAF είναι γνωστός από το CRC.","Reflexalgorithmen dürfen nicht mechanisch zwischen Tumorentitäten übertragen werden.":"Οι αντανακλαστικοί αλγόριθμοι δεν πρέπει να μεταφέρονται μηχανικά μεταξύ οντοτήτων όγκων.","High-grade endometrioides Endometriumkarzinom.":"Υψηλού βαθμού ενδομητριοειδές καρκίνωμα ενδομητρίου.","Mutter Kolonkarzinom mit 52, Onkel oberer Harntrakt.":"Μητέρα με καρκίνο παχέος εντέρου στα 52, θείος με καρκίνο ανώτερου ουροποιητικού.","Primärtumor mit guter DNA-Qualität; MMR-IHC und Methylierung möglich.":"Πρωτοπαθής όγκος με καλή ποιότητα DNA· MMR-IHC και έλεγχος μεθυλίωσης εφικτά.","MMR-IHC liefert bereits das entscheidende Proteinverlustmuster und sollte nicht durch ein unspezifisches Breitpanel ersetzt werden.":"Η MMR-IHC παρέχει ήδη το καθοριστικό πρότυπο απώλειας πρωτεϊνών και δεν πρέπει να αντικαθίσταται από μη ειδικό ευρύ panel.","Bei MLH1/PMS2-Verlust ist eine gezielte MLH1-Promotormethylierung material- und fragestellungseffizient.":"Σε απώλεια MLH1/PMS2, ο στοχευμένος έλεγχος μεθυλίωσης του υποκινητή MLH1 είναι αποδοτικός τόσο ως προς το υλικό όσο και ως προς το κλινικό ερώτημα.","Die Keimbahndiagnostik benötigt humangenetische Beratung und eine geeignete Normalprobe; Tumorgewebe allein reicht nicht.":"Ο έλεγχος βλαστικής σειράς απαιτεί γενετική συμβουλευτική και κατάλληλο φυσιολογικό δείγμα· ο ιστός του όγκου μόνος του δεν επαρκεί.","MMR-IHC: MLH1 und PMS2 verloren, MSH2/MSH6 erhalten. Was ist der passende nächste Reflex im Endometriumkarzinom?":"MMR-IHC: απώλεια MLH1 και PMS2, διατήρηση MSH2/MSH6. Ποιος είναι ο κατάλληλος επόμενος αντανακλαστικός έλεγχος στο καρκίνωμα ενδομητρίου;","MLH1-Promotormethylierung prüfen, um eine häufige sporadische MLH1-Inaktivierung zu erfassen.":"Ελέγξτε τη μεθυλίωση του υποκινητή MLH1 για να ανιχνεύσετε έναν συχνό σποραδικό μηχανισμό αδρανοποίησης MLH1.","BRAF V600E ist hier der Standardreflex wie beim CRC.":"Το BRAF V600E είναι εδώ το τυπικό αντανακλαστικό τεστ, όπως και στο CRC.","Nur PD-L1 nachtesten; MMR-Muster ist für Lynch irrelevant.":"Επαναλάβετε μόνο PD-L1· το πρότυπο MMR είναι άσχετο με το Lynch.","Kein Reflex: MLH1/PMS2-Verlust beweist bereits Lynch.":"Δεν χρειάζεται αντανακλαστικός έλεγχος: η απώλεια MLH1/PMS2 αποδεικνύει ήδη σύνδρομο Lynch.","Beim Endometriumkarzinom ist die MLH1-Promotormethylierung der relevante Reflex bei MLH1/PMS2-Verlust.":"Στο καρκίνωμα ενδομητρίου, η μεθυλίωση του υποκινητή MLH1 είναι ο σχετικός αντανακλαστικός έλεγχος για απώλεια MLH1/PMS2.","Was bedeutet dMMR/MSI-H therapeutisch?":"Τι σημαίνει θεραπευτικά το dMMR/MSI-H;","Ein starker prädiktiver Immuntherapiekontext, dessen konkrete Nutzung von Stadium, Linie und aktueller Zulassung/Leitlinie abhängt.":"Ένα ισχυρό προβλεπτικό πλαίσιο ανοσοθεραπείας, η συγκεκριμένη χρήση του οποίου εξαρτάται από στάδιο, γραμμή θεραπείας και τρέχουσα έγκριση/κατευθυντήρια οδηγία.","Ohne hohen PD-L1-Score ist MSI-H therapeutisch bedeutungslos.":"Χωρίς υψηλό score PD-L1, το MSI-H δεν έχει θεραπευτική σημασία.","MSI-H ist ausschließlich ein Lynch-Screeningmarker.":"Το MSI-H είναι αποκλειστικά δείκτης screening Lynch.","MSI-H beweist eine Keimbahn-MMR-Mutation.":"Το MSI-H αποδεικνύει μετάλλαξη MMR βλαστικής σειράς.","dMMR/MSI-H besitzt eine eigenständige prädiktive Bedeutung, unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"Το dMMR/MSI-H έχει αυτοτελή προβλεπτική σημασία, ανεξάρτητα από το αν η αιτία είναι σποραδική ή κληρονομική.","MLH1/PMS2-Verlust + MSI-H, aber keine MLH1-Promotormethylierung. Was folgt?":"Απώλεια MLH1/PMS2 + MSI-H, αλλά χωρίς μεθυλίωση του υποκινητή MLH1. Τι ακολουθεί;","Lynch-Syndrom bleibt verdächtig: humangenetische Beratung/Keimbahndiagnostik veranlassen, ohne Lynch bereits als bewiesen zu bezeichnen.":"Το σύνδρομο Lynch παραμένει ύποπτο: οργανώστε γενετική συμβουλευτική/έλεγχο βλαστικής σειράς χωρίς να χαρακτηρίζετε ήδη το Lynch ως αποδεδειγμένο.","Lynch-Syndrom ist damit sicher bewiesen.":"Το σύνδρομο Lynch έχει πλέον αποδειχθεί οριστικά.","Fehlende Methylierung beweist einen sporadischen Tumor.":"Η απουσία μεθυλίωσης αποδεικνύει σποραδικό όγκο.","Nur ein negatives BRAF-Ergebnis kann jetzt Lynch ausschließen.":"Μόνο ένα αρνητικό αποτέλεσμα BRAF μπορεί πλέον να αποκλείσει το σύνδρομο Lynch.","Tumorscreening stratifiziert den Verdacht; die Keimbahndiagnose ist ein separater Schritt.":"Το tumor screening διαβαθμίζει την υποψία· η διάγνωση βλαστικής σειράς αποτελεί ξεχωριστό βήμα.","Warum ist BRAF V600E hier eine Falle?":"Γιατί το BRAF V600E αποτελεί παγίδα εδώ;","Der BRAF-Reflex gehört zur CRC-spezifischen MLH1/PMS2-Logik und ist beim Endometriumkarzinom kein adäquater Ersatz für MLH1-Promotormethylierung.":"Ο αντανακλαστικός έλεγχος BRAF ανήκει στον ειδικό για CRC αλγόριθμο MLH1/PMS2 και δεν αποτελεί κατάλληλο υποκατάστατο της μεθυλίωσης του υποκινητή MLH1 στο καρκίνωμα ενδομητρίου.","BRAF kann in keinem Endometriumtumor mutiert sein.":"Το BRAF δεν μπορεί ποτέ να είναι μεταλλαγμένο σε κανέναν όγκο ενδομητρίου.","BRAF bestimmt hier ausschließlich die PD-L1-Expression.":"Το BRAF καθορίζει εδώ αποκλειστικά την έκφραση PD-L1.","CRC- und Endometrium-Reflexalgorithmen sind identisch.":"Οι αντανακλαστικοί αλγόριθμοι CRC και ενδομητρίου είναι πανομοιότυποι.","Reflexdiagnostik ist entitätsspezifisch und darf nicht als universelles Rezept behandelt werden.":"Η αντανακλαστική διαγνωστική είναι ειδική για την οντότητα και δεν πρέπει να αντιμετωπίζεται ως καθολική συνταγή.","Formulieren Sie eine integrierte MTB-/Befundaussage, die dMMR/MSI-H therapeutisch würdigt, den MLH1/PMS2-Verlust korrekt reflexdiagnostisch weiterführt und die Lynch-Frage sauber von der Tumordiagnostik trennt.":"Διατυπώστε μια ολοκληρωμένη δήλωση MTB/γνωμάτευσης που να αποδίδει σωστά τη θεραπευτική σημασία του dMMR/MSI-H, να συνεχίζει ορθά την απώλεια MLH1/PMS2 με αντανακλαστικό έλεγχο και να διαχωρίζει καθαρά το ερώτημα Lynch από τη διαγνωστική του όγκου.","MMR-IHC: MLH1/PMS2-Verlust benennen.":"MMR-IHC: αναφέρετε απώλεια MLH1/PMS2.","MSI-H als konsistenten molekularen Befund bestätigen.":"Επιβεβαιώστε το MSI-H ως συμβατό μοριακό εύρημα.","dMMR/MSI-H als prädiktiven IO-Kontext kommunizieren.":"Επικοινωνήστε το dMMR/MSI-H ως προβλεπτικό πλαίσιο ανοσοθεραπείας.","MLH1-Promotormethylierung als entitätsspezifischen Reflex durchführen.":"Πραγματοποιήστε έλεγχο μεθυλίωσης του υποκινητή MLH1 ως αντανακλαστικό τεστ ειδικό για την οντότητα.","Fehlende MLH1-Methylierung als erhöhten Lynch-Verdacht, nicht als Beweis interpretieren.":"Ερμηνεύστε την απουσία μεθυλίωσης MLH1 ως αυξημένη υποψία για σύνδρομο Lynch, όχι ως απόδειξη.","Humangenetische Beratung/Keimbahndiagnostik empfehlen.":"Συστήστε γενετική συμβουλευτική/έλεγχο βλαστικής σειράς.","BRAF-V600E-CRC-Reflex ausdrücklich nicht übertragen.":"Μην μεταφέρετε ρητά τον αντανακλαστικό έλεγχο BRAF V600E του CRC.","MSI kann molekular aus einem validierten Panel bestätigt werden, sofern MMR-IHC und MLH1-Methylierungsreflex trotzdem korrekt integriert werden.":"Το MSI μπορεί να επιβεβαιωθεί μοριακά από επικυρωμένο panel, υπό την προϋπόθεση ότι η MMR-IHC και ο αντανακλαστικός έλεγχος μεθυλίωσης MLH1 ενσωματώνονται σωστά.","Bei bereits qualitativ eindeutiger dMMR-IHC kann die therapeutische Kommunikation sofort erfolgen, während die hereditäre Reflexdiagnostik parallel abgeschlossen wird.":"Εάν η dMMR-IHC είναι ήδη σαφής και τεχνικά αξιόπιστη, η θεραπευτική ερμηνεία μπορεί να κοινοποιηθεί άμεσα ενώ η κληρονομική αντανακλαστική διερεύνηση ολοκληρώνεται παράλληλα.","BRAF wie beim CRC":"BRAF όπως στο CRC","Entitätsspezifischer Reflexalgorithmus falsch übertragen.":"Ο ειδικός για την οντότητα αντανακλαστικός αλγόριθμος μεταφέρθηκε λανθασμένα.","MSI-H = Lynch":"MSI-H = Lynch","Viele dMMR/MSI-H-Tumoren sind sporadisch; Tumorscreening ist keine Keimbahndiagnose.":"Πολλοί όγκοι dMMR/MSI-H είναι σποραδικοί· το tumor screening δεν αποτελεί διάγνωση βλαστικής σειράς.","Methylierungsnegativ = bewiesen erblich":"Αρνητική μεθυλίωση = αποδεδειγμένα κληρονομικό","Der Befund erhöht den Verdacht, beweist aber noch keine Keimbahnmutation.":"Το αποτέλεσμα αυξάνει την υποψία, αλλά δεν αποδεικνύει ακόμη μετάλλαξη βλαστικής σειράς.","PD-L1 priorisieren":"Δώστε προτεραιότητα στο PD-L1","dMMR/MSI-H ist hier der robustere Kernbiomarker; PD-L1 ist für die Lynch-Frage irrelevant.":"Το dMMR/MSI-H είναι εδώ ο ισχυρότερος βασικός βιοδείκτης· το PD-L1 είναι άσχετο με το ερώτημα Lynch.","Der CRC-Reflex wäre hier genau der falsche Automatismus":"Ο αντανακλαστικός αλγόριθμος του CRC θα ήταν ακριβώς ο λάθος αυτοματισμός εδώ","MLH1/PMS2-Verlust und MSI-H wirken zunächst wie ein vertrauter CRC-Fall. Doch beim Endometriumkarzinom ist der sinnvolle Reflex die MLH1-Promotormethylierung – nicht BRAF V600E. Als die Methylierung negativ bleibt, steigt der Lynch-Verdacht deutlich, ohne bereits zur genetischen Diagnose zu werden.":"Η απώλεια MLH1/PMS2 και το MSI-H μοιάζουν αρχικά με οικεία περίπτωση CRC. Στο καρκίνωμα ενδομητρίου όμως ο κατάλληλος αντανακλαστικός έλεγχος είναι η μεθυλίωση του υποκινητή MLH1 — όχι το BRAF V600E. Όταν η μεθυλίωση παραμένει αρνητική, η υποψία για Lynch αυξάνει σημαντικά χωρίς ακόμη να αποτελεί γενετική διάγνωση.","Der Fall trainiert zwei Kernkompetenzen gleichzeitig: entitätsspezifische Reflexdiagnostik und saubere Trennung von Tumor-Screening und Keimbahndiagnose.":"Η περίπτωση εκπαιδεύει ταυτόχρονα δύο βασικές δεξιότητες: αντανακλαστική διαγνωστική ειδική για την οντότητα και σαφή διαχωρισμό μεταξύ tumor screening και διάγνωσης βλαστικής σειράς.","Therapie und Lynch-Pfad sauber getrennt":"Καθαρός διαχωρισμός θεραπείας και διαδρομής Lynch","MLH1/PMS2-Verlust, MSI-H, keine MLH1-Promotormethylierung. dMMR/MSI-H als IO-relevant berichten; Lynch-Syndrom humangenetisch abklären. BRAF-CRC-Reflex nicht verwenden.":"Απώλεια MLH1/PMS2, MSI-H, χωρίς μεθυλίωση υποκινητή MLH1. Αναφέρετε το dMMR/MSI-H ως σχετικό για IO· προχωρήστε σε γενετική διερεύνηση για σύνδρομο Lynch. Μην χρησιμοποιείτε τον αντανακλαστικό έλεγχο BRAF του CRC.","Beide klinischen Konsequenzen korrekt geführt.":"Και οι δύο κλινικές συνέπειες αντιμετωπίστηκαν σωστά.","IO erkannt, Lynch-Pfad unvollständig":"Αναγνωρίστηκε IO, αλλά η διαδρομή Lynch είναι ελλιπής","dMMR/MSI-H wird therapeutisch korrekt eingeordnet, MLH1-Methylierung/Genetik fehlen.":"Το dMMR/MSI-H ερμηνεύεται σωστά θεραπευτικά, αλλά λείπουν ο έλεγχος μεθυλίωσης MLH1/η παραπομπή σε γενετική.","Hereditäre Konsequenz verpasst.":"Παραλείφθηκε η κληρονομική συνέπεια.","BRAF-Automatismus":"Αυτοματισμός BRAF","BRAF V600E wird als Standardreflex bestellt und ein negatives Ergebnis als Lynch-Beweis interpretiert.":"Παραγγέλλεται BRAF V600E ως τυπικό αντανακλαστικό τεστ και ένα αρνητικό αποτέλεσμα ερμηνεύεται ως απόδειξη συνδρόμου Lynch.","Entitätsspezifische Reflexdiagnostik und Keimbahnlogik verfehlt.":"Αστοχία στη διαγνωστική αντανακλαστική λογική ειδική για την οντότητα και στη λογική βλαστικής σειράς.","MLH1-Methylierung negativ":"Αρνητική μεθυλίωση MLH1","Humangenetische Beratung und Keimbahndiagnostik veranlassen.":"Οργανώστε γενετική συμβουλευτική και έλεγχο βλαστικής σειράς.","Lynch-Syndrom kann bestätigt oder ausgeschlossen werden; Familienmanagement erst danach festlegen.":"Το σύνδρομο Lynch μπορεί τότε να επιβεβαιωθεί ή να αποκλειστεί· η διαχείριση της οικογένειας πρέπει να καθοριστεί μόνο μετά.","dMMR/MSI-H bestätigt":"Επιβεβαιωμένο dMMR/MSI-H","Therapieplanung mit aktuellem endometriumkarzinomspezifischem IO-Standard/Leitlinie abgleichen.":"Ευθυγραμμίστε τον θεραπευτικό σχεδιασμό με το τρέχον ειδικό για το καρκίνωμα ενδομητρίου πρότυπο/οδηγία IO.","Prädiktiver Befund wird unabhängig von der noch offenen Keimbahnursache genutzt.":"Το προβλεπτικό εύρημα μπορεί να αξιοποιηθεί ανεξάρτητα από την ακόμη αδιευκρίνιστη αιτία βλαστικής σειράς.","dMMR/MSI-H kann zugleich Therapiebiomarker und Hinweis auf hereditäre Prädisposition sein.":"Το dMMR/MSI-H μπορεί ταυτόχρονα να αποτελεί θεραπευτικό βιοδείκτη και ένδειξη κληρονομικής προδιάθεσης.","MLH1/PMS2-Verlust lenkt die Reflexdiagnostik auf MLH1-Promotormethylierung.":"Η απώλεια MLH1/PMS2 κατευθύνει τον αντανακλαστικό έλεγχο προς τη μεθυλίωση του υποκινητή MLH1.","CRC-BRAF-Reflexe dürfen nicht automatisch auf das Endometriumkarzinom übertragen werden.":"Οι αντανακλαστικοί έλεγχοι BRAF του CRC δεν πρέπει να μεταφέρονται αυτόματα στο καρκίνωμα ενδομητρίου.","Fehlende MLH1-Methylierung erhöht den Lynch-Verdacht, beweist aber keine Keimbahnmutation.":"Η απουσία μεθυλίωσης MLH1 αυξάνει την υποψία για σύνδρομο Lynch, αλλά δεν αποδεικνύει μετάλλαξη βλαστικής σειράς.","Tumorbiomarker und Humangenetik laufen parallel, aber diagnostisch getrennt.":"Οι βιοδείκτες όγκου και η ιατρική γενετική προχωρούν παράλληλα, αλλά παραμένουν διαγνωστικά διακριτά.","MLH1/PMS2-Verlust + MSI-H = dMMR/MSI-H und damit therapeutisch relevant. Beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex; hier negativ. Deshalb Lynch-Syndrom humangenetisch abklären, aber nicht bereits diagnostizieren. BRAF V600E ist kein adäquater Ersatzreflex.":"Απώλεια MLH1/PMS2 + MSI-H = dMMR/MSI-H και συνεπώς θεραπευτικά σημαντικό. Στο καρκίνωμα ενδομητρίου χρησιμοποιήστε τη μεθυλίωση του υποκινητή MLH1 ως αντανακλαστικό τεστ· εδώ είναι αρνητική. Επομένως προχωρήστε σε γενετική διερεύνηση για σύνδρομο Lynch, χωρίς να το διαγνώσετε ήδη. Το BRAF V600E δεν αποτελεί κατάλληλο υποκατάστατο αντανακλαστικό τεστ.","MMR-Muster korrekt":"Σωστό πρότυπο MMR","MLH1-Methylierungsreflex":"Αντανακλαστικός έλεγχος μεθυλίωσης MLH1","IO-Relevanz":"Σημασία για IO","Lynch-Verdacht ≠ Diagnose":"Υποψία Lynch ≠ διάγνωση","BRAF-Copyover vermieden":"Αποφεύχθηκε το copyover BRAF","Warum fallen MLH1 und PMS2 gemeinsam aus?":"Γιατί χάνονται μαζί τα MLH1 και PMS2;","Warum unterscheidet sich der Reflexalgorithmus zwischen CRC und Endometrium?":"Γιατί διαφέρει ο αντανακλαστικός αλγόριθμος μεταξύ CRC και καρκινώματος ενδομητρίου;","Welche Information darf bereits im Tumorbefund stehen und welche erst nach Keimbahndiagnostik?":"Ποιες πληροφορίες μπορούν ήδη να αναφέρονται στη γνωμάτευση του όγκου και ποιες μόνο μετά από έλεγχο βλαστικής σειράς;","MLH1/PMS2-Verlust + keine MLH1-Methylierung":"Απώλεια MLH1/PMS2 + χωρίς μεθυλίωση MLH1","dMMR ist Therapiebiomarker und Lynch-Screening, aber Entität bestimmt den Reflex":"Το dMMR είναι τόσο θεραπευτικός βιοδείκτης όσο και screening Lynch, αλλά η οντότητα του όγκου καθορίζει τον αντανακλαστικό έλεγχο","MMR-IHC → MSI → MLH1-Methylierung → Humangenetik":"MMR-IHC → MSI → μεθυλίωση MLH1 → ιατρική γενετική","Antibiotika kurz vor ICI, Mikrobiom-Frage im Tumorboard → Evidenz korrekt begrenzen":"Αντιβιοτικά λίγο πριν από ICI, ερώτημα μικροβιώματος στο tumor board → σωστός περιορισμός της τεκμηρίωσης","Antibiotika kurz vor ICI, Mikrobio…":"Αντιβιοτικά λίγο πριν από ICI, μικροβίω…","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom. PD-L1 TPS 80 %. Vor Beginn der geplanten Immuntherapie musste er wegen einer mikrobiologisch gesicherten bakteriellen Pneumonie sieben Tage breit antibiotisch behandelt werden.":"72χρονος άνδρας με μεταστατικό πνευμονικό αδενοκαρκίνωμα. PD-L1 TPS 80%. Πριν από την προγραμματισμένη έναρξη ανοσοθεραπείας χρειάστηκε επτά ημέρες ευρέος φάσματος αντιβιοτικά για μικροβιολογικά επιβεβαιωμένη βακτηριακή πνευμονία.","Soll die notwendige Antibiotikatherapie wegen möglicher Mikrobiom-Effekte die ICI-Entscheidung verändern, verzögern oder durch Mikrobiom-Interventionen 'kompensiert' werden?":"Πρέπει η αναγκαία αντιβιοτική αγωγή, λόγω πιθανών επιδράσεων στο μικροβίωμα, να αλλάξει ή να καθυστερήσει την απόφαση για ICI ή να «αντισταθμιστεί» με παρεμβάσεις στο μικροβίωμα;","Die Pneumonie ist klinisch abgeheilt; Systemtherapie soll zeitnah beginnen.":"Η πνευμονία έχει κλινικά υποχωρήσει· η συστηματική θεραπεία πρέπει να ξεκινήσει σύντομα.","Tumor":"Όγκος","Metastasiertes Lungenadenokarzinom, ECOG 1.":"Μεταστατικό πνευμονικό αδενοκαρκίνωμα, ECOG 1.","Treiberdiagnostik":"Έλεγχος driver","Breites DNA/RNA-Profil ohne etablierte actionable Driveralteration; ALK/ROS1/RET/NTRK/METex14/EGFR etc. ohne therapieentscheidenden Befund.":"Ευρεία ανάλυση DNA/RNA χωρίς καθιερωμένη actionable driver αλλοίωση· ALK/ROS1/RET/NTRK/METex14/EGFR κ.λπ. χωρίς εύρημα που να καθορίζει θεραπεία.","TPS 80 %, technisch valide.":"TPS 80%, τεχνικά έγκυρο.","Antibiotika":"Αντιβιοτικά","Piperacillin/Tazobactam, anschließend orale Komplettierung wegen gesicherter bakterieller Pneumonie; Therapie war klinisch indiziert.":"Πιπερακιλλίνη/ταζομπακτάμη και στη συνέχεια από του στόματος ολοκλήρωση για επιβεβαιωμένη βακτηριακή πνευμονία· η θεραπεία ήταν κλινικά ενδεδειγμένη.","Eine populationsbasierte Assoziation zwischen Antibiotika/Mikrobiom und ICI-Outcome wird zur individuellen Kontraindikation oder zum Anlass für unvalidierte Probiotika/FMT gemacht.":"Μια συσχέτιση σε επίπεδο πληθυσμού μεταξύ αντιβιοτικών/μικροβιώματος και έκβασης ICI μετατρέπεται σε ατομική αντένδειξη ή σε λόγο για μη επικυρωμένα προβιοτικά/FMT.","Pulmonales Adenokarzinom, TTF-1/Napsin A positiv.":"Πνευμονικό αδενοκαρκίνωμα, TTF-1/Napsin A θετικά.","TPS 80 %.":"TPS 80%.","Molekularprofil":"Μοριακό προφίλ","DNA/RNA-basierte Treiberdiagnostik ohne etablierte Targetalteration.":"Έλεγχος driver βάσει DNA/RNA χωρίς καθιερωμένη στοχεύσιμη αλλοίωση.","Nicht die Tumordiagnostik, sondern die Evidenzstärke der Mikrobiom-/Antibiotika-Assoziation und ihre Konsequenz für die individuelle Therapie.":"Το κρίσιμο ζήτημα δεν είναι ο έλεγχος του όγκου, αλλά η ισχύς της τεκμηρίωσης για τη συσχέτιση μικροβιώματος/αντιβιοτικών και η συνέπειά της για την ατομική θεραπευτική απόφαση.","Kleine Bronchialbiopsie; wesentliche Treiber- und PD-L1-Diagnostik bereits vollständig.":"Μικρή βρογχική βιοψία· ο ουσιώδης έλεγχος driver και PD-L1 έχει ήδη ολοκληρωθεί.","Restmaterial":"Υπόλοιπο υλικό","Nur noch begrenzt verfügbar.":"Παραμένει διαθέσιμο μόνο περιορισμένο υλικό.","Zusätzliche TMB-/TIL-/Breitdiagnostik kann den Effekt einer Antibiotikatherapie auf das Darmmikrobiom nicht valide quantifizieren und erzeugt keine etablierte 'ICI-Freigabe'.":"Πρόσθετος έλεγχος TMB/TIL/ευρύς δεν μπορεί να ποσοτικοποιήσει έγκυρα την επίδραση της αντιβιοτικής αγωγής στο εντερικό μικροβίωμα και δεν δημιουργεί καθιερωμένη «έγκριση ICI».","Klinische Ressource":"Κλινικός πόρος","Der wichtigste Zusatzdatensatz ist hier die Indikation und zeitliche Einordnung der Antibiotikatherapie – nicht noch ein Tumortest.":"Το σημαντικότερο πρόσθετο σύνολο δεδομένων εδώ είναι η ένδειξη και ο χρονισμός της αντιβιοτικής αγωγής — όχι ακόμη ένας έλεγχος όγκου.","Validierter Tumor-/ICI-Kontext":"Επικυρωμένο πλαίσιο όγκου/ICI","PD-L1 TPS 80 % bestätigt. Der Marker bleibt ein etablierter Bestandteil der NSCLC-Therapieplanung im passenden driver-negativen Kontext.":"Επιβεβαιώνεται PD-L1 TPS 80%. Ο δείκτης παραμένει καθιερωμένο στοιχείο του θεραπευτικού σχεδιασμού NSCLC στο κατάλληλο driver-negative πλαίσιο.","Treiberprofil":"Προφίλ driver","Keine etablierte actionable Driveralteration nach integrierter DNA/RNA-Diagnostik. Die hohe PD-L1-Expression wird damit nicht durch einen offensichtlichen targetierbaren Treiberkontext verdrängt.":"Δεν υπάρχει καθιερωμένη actionable driver αλλοίωση μετά από ολοκληρωμένο έλεγχο DNA/RNA. Επομένως η υψηλή έκφραση PD-L1 δεν υποσκελίζεται από προφανές στοχεύσιμο driver context.","TMB intermediär (7 Mut/Mb). Dieser Wert beantwortet die Antibiotika-/Mikrobiomfrage nicht und ersetzt die validierte NSCLC-Biomarkerhierarchie nicht.":"Ενδιάμεσο TMB (7 mut/Mb). Η τιμή αυτή δεν απαντά στο ερώτημα αντιβιοτικών/μικροβιώματος και δεν αντικαθιστά την επικυρωμένη ιεραρχία βιοδεικτών NSCLC.","Mäßiges CD8-Infiltrat. Auch dieser Befund erlaubt keine patientenspezifische Quantifizierung eines möglichen Antibiotikaeffekts auf ICI-Wirksamkeit.":"Μέτρια διήθηση CD8. Ούτε αυτό το εύρημα επιτρέπει ποσοτικοποίηση ειδικού για τον ασθενή αποτελέσματος των αντιβιοτικών στην αποτελεσματικότητα ICI.","Antibiotikaanamnese":"Ιστορικό αντιβιοτικών","Sieben Tage notwendige Antibiotikatherapie wegen gesicherter bakterieller Pneumonie unmittelbar vor geplantem ICI-Beginn.":"Επτά ημέρες αναγκαίας αντιβιοτικής αγωγής για επιβεβαιωμένη βακτηριακή πνευμονία αμέσως πριν από την προγραμματισμένη έναρξη ICI.","Infektion abgeheilt; Patient therapiefähig.":"Η λοίμωξη έχει υποχωρήσει· ο ασθενής είναι κατάλληλος για θεραπεία.","Evidenzkonflikt":"Σύγκρουση τεκμηρίωσης","Beobachtungsdaten zeigen Assoziationen zwischen Antibiotikaexposition und schlechteren ICI-Outcomes, beweisen aber für den individuellen Patienten keine kausale Therapieresistenz.":"Παρατηρησιακά δεδομένα δείχνουν συσχετίσεις μεταξύ έκθεσης σε αντιβιοτικά και χειρότερων εκβάσεων με ICI, αλλά δεν αποδεικνύουν αιτιώδη θεραπευτική αντοχή στον μεμονωμένο ασθενή.","Driver-negatives metastasiertes NSCLC mit hoher PD-L1-Expression. Die kürzlich notwendige Antibiotikatherapie ist als möglicher prognostischer/biologischer Kontext diskutierbar, stellt aber keine validierte individuelle Kontraindikation gegen eine indizierte Checkpoint-Therapie dar. Eine klinisch notwendige bakterielle Infektion durfte nicht unbehandelt bleiben. Unnötige Antibiotika sollten vermieden werden; Mikrobiomtests, Probiotika oder FMT sind nicht als routinemäßige Kompensationsstrategie validiert und gehören – sofern überhaupt – in Studien.":"Driver-negative μεταστατικό NSCLC με υψηλή έκφραση PD-L1. Η πρόσφατη αναγκαία αντιβιοτική αγωγή μπορεί να συζητηθεί ως πιθανό προγνωστικό/βιολογικό πλαίσιο, αλλά δεν αποτελεί επικυρωμένη ατομική αντένδειξη για ενδεδειγμένη θεραπεία checkpoint. Μια κλινικά σημαντική βακτηριακή λοίμωξη δεν έπρεπε να μείνει χωρίς θεραπεία. Τα περιττά αντιβιοτικά πρέπει να αποφεύγονται· έλεγχοι μικροβιώματος, προβιοτικά ή FMT δεν είναι επικυρωμένα ως στρατηγικές ρουτίνας για «αντιστάθμιση» και, αν χρησιμοποιούνται, ανήκουν σε κλινικές μελέτες.","Teilbefund: Die Mikrobiom-Assoziation wird erwähnt, aber ohne Trennung von Kausalität, Konfounding, klinischer Antibiotikaindikation und validierten Tumorbiomarkern bleibt die Empfehlung unsauber.":"Μερική ερμηνεία: αναφέρεται η συσχέτιση με το μικροβίωμα, αλλά χωρίς διαχωρισμό αιτιότητας, confounding, κλινικής ένδειξης των αντιβιοτικών και επικυρωμένων βιοδεικτών όγκου, η σύσταση παραμένει ασαφής.","PD-L1 und vollständigen Driverstatus als etablierte NSCLC-Biomarkerhierarchie priorisieren":"Δώστε προτεραιότητα στο PD-L1 και στον πλήρη driver status ως την καθιερωμένη ιεραρχία βιοδεικτών NSCLC","Antibiotika/ICI als Assoziation mit möglichem Confounding, nicht als individuellen Resistenztest erklären":"Εξηγήστε αντιβιοτικά/ICI ως συσχέτιση με πιθανό confounding, όχι ως ατομικό τεστ αντοχής","klinisch notwendige Antibiotikatherapie nicht retrospektiv als Fehler darstellen":"Μην παρουσιάζετε αναδρομικά την κλινικά αναγκαία αντιβιοτική αγωγή ως σφάλμα","keine unvalidierte Mikrobiomdiagnostik, Probiotika oder FMT als Routineempfehlung aussprechen":"Μη συστήνετε μη επικυρωμένο έλεγχο μικροβιώματος, προβιοτικά ή FMT ως ρουτίνα","Falschaussage: Antibiotika kurz vor ICI sind eine absolute Kontraindikation gegen Immuntherapie":"Λανθασμένη δήλωση: τα αντιβιοτικά λίγο πριν από ICI αποτελούν απόλυτη αντένδειξη για ανοσοθεραπεία","Optimale Lösung: Hohe PD-L1-Expression und driver-negativer NSCLC-Kontext bleiben die belastbaren Therapiebiomarker. Die notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext zu erwähnen, aber nicht als validierte individuelle Kontraindikation. Keine unvalidierten Mikrobiom-Interventionen außerhalb von Studien.":"Βέλτιστη λύση: η υψηλή έκφραση PD-L1 και το driver-negative πλαίσιο NSCLC παραμένουν οι αξιόπιστοι θεραπευτικοί βιοδείκτες. Η αναγκαία αντιβιοτική αγωγή πρέπει να αναφερθεί ως πιθανό πλαίσιο έκβασης, αλλά όχι ως επικυρωμένη ατομική αντένδειξη. Καμία μη επικυρωμένη παρέμβαση στο μικροβίωμα εκτός μελετών.","Mikrobiom":"Μικροβίωμα","ICI":"ICI","Confounding":"Confounding","Antibiotika vor ICI: relevante Assoziation, aber keine patientenindividuelle Kontraindikation":"Αντιβιοτικά πριν από ICI: σχετική συσχέτιση, αλλά όχι ατομική αντένδειξη","Beobachtungsassoziation, Kausalität und Confounding in der Mikrobiom-/ICI-Literatur unterscheiden.":"Διακρίνετε παρατηρησιακή συσχέτιση, αιτιότητα και confounding στη βιβλιογραφία μικροβιώματος/ICI.","Validierte NSCLC-Tumorbiomarker gegenüber unvalidierten Mikrobiom-Surrogaten priorisieren.":"Δώστε προτεραιότητα σε επικυρωμένους βιοδείκτες NSCLC έναντι μη επικυρωμένων surrogate δεικτών μικροβιώματος.","Klinisch notwendige Antibiotikatherapie nicht retrospektiv als vermeidbaren onkologischen Fehler behandeln.":"Μην αντιμετωπίζετε αναδρομικά την κλινικά αναγκαία αντιβιοτική αγωγή ως αποτρέψιμο ογκολογικό σφάλμα.","Eine vorausgegangene Antibiotikaexposition nicht als absolute ICI-Kontraindikation formulieren.":"Μη διατυπώνετε προηγούμενη έκθεση σε αντιβιοτικά ως απόλυτη αντένδειξη για ICI.","Mikrobiomtests, Probiotika und FMT als experimentell statt als Routinetherapie einordnen.":"Χαρακτηρίστε έλεγχο μικροβιώματος, προβιοτικά και FMT ως πειραματικά και όχι ως θεραπεία ρουτίνας.","Der Patient hat genau den Tumor, bei dem das Team an Checkpoint-Therapie denkt: driver-negatives NSCLC, PD-L1 TPS 80 %. Dann fällt im Medikamentenplan auf, dass er in der Vorwoche sieben Tage Breitbandantibiotika bekommen hat. Sofort steht die Frage im Raum: 'Haben wir damit die Immuntherapie kaputtgemacht?' Der Fall dreht sich weniger um einen weiteren Labortest als um Evidenzkompetenz.":"Ο ασθενής έχει ακριβώς τον τύπο όγκου για τον οποίο η ομάδα σκέφτεται θεραπεία checkpoint: driver-negative NSCLC, PD-L1 TPS 80%. Στη λίστα φαρμάκων όμως φαίνεται ότι την προηγούμενη εβδομάδα έλαβε επτά ημέρες ευρέος φάσματος αντιβιοτικά. Αμέσως τίθεται το ερώτημα: «Καταστρέψαμε έτσι την ανοσοθεραπεία;» Η περίπτωση αφορά λιγότερο έναν ακόμη εργαστηριακό έλεγχο και περισσότερο την ικανότητα αξιολόγησης της τεκμηρίωσης.","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom, vollständiger DNA/RNA-Treiberdiagnostik ohne actionable Alteration und PD-L1 TPS 80 %. Unmittelbar vor geplantem ICI-Beginn wurde eine mikrobiologisch gesicherte Pneumonie leitliniengerecht antibiotisch behandelt. Das MTB soll entscheiden, ob dies die Immuntherapie verändert und wie Mikrobiomdaten klinisch korrekt begrenzt werden.":"72χρονος άνδρας με μεταστατικό πνευμονικό αδενοκαρκίνωμα, πλήρη έλεγχο driver DNA/RNA χωρίς actionable αλλοίωση και PD-L1 TPS 80%. Αμέσως πριν από την προγραμματισμένη έναρξη ICI, μικροβιολογικά επιβεβαιωμένη πνευμονία αντιμετωπίστηκε ορθά με αντιβιοτικά. Το MTB πρέπει να αποφασίσει εάν αυτό αλλάζει την ανοσοθεραπεία και πώς πρέπει να περιοριστεί κλινικά η ερμηνεία των δεδομένων μικροβιώματος.","Starker etablierter Tumorbiomarker":"Ισχυρός καθιερωμένος βιοδείκτης όγκου","PD-L1 TPS 80 %, kein etablierter actionable Driver.":"PD-L1 TPS 80%, χωρίς καθιερωμένο actionable driver.","Die Therapieplanung basiert zunächst auf validierten Tumor- und Klinikfaktoren.":"Ο θεραπευτικός σχεδιασμός βασίζεται πρώτα σε επικυρωμένους ογκολογικούς και κλινικούς παράγοντες.","Reale Mikrobiomassoziation":"Πραγματική συσχέτιση με το μικροβίωμα","Antibiotikaexposition um ICI-Beginn ist in Kohorten mit schlechterem Outcome assoziiert.":"Η έκθεση σε αντιβιοτικά γύρω από την έναρξη ICI συσχετίζεται με χειρότερες εκβάσεις σε κοόρτες.","Assoziation kann biologisch plausibel sein und trotzdem durch Infektion, Krankheitslast oder andere Faktoren konfundiert werden.":"Μια συσχέτιση μπορεί να είναι βιολογικά εύλογη και παρ’ όλα αυτά να επηρεάζεται από confounding λόγω λοίμωξης, φορτίου νόσου ή άλλων παραγόντων.","Klinische Indikation zählt":"Η κλινική ένδειξη έχει σημασία","Die Pneumonie war gesichert und behandlungsbedürftig.":"Η πνευμονία ήταν επιβεβαιωμένη και απαιτούσε θεραπεία.","Ein notwendiges Antibiotikum wird nicht dadurch falsch, dass es möglicherweise das Mikrobiom beeinflusst.":"Ένα αναγκαίο αντιβιοτικό δεν γίνεται λανθασμένο απλώς επειδή μπορεί να επηρεάσει το μικροβίωμα.","DNA/RNA-Treiberprofil":"Προφίλ driver DNA/RNA","Kein etablierter actionable Driver.":"Κανένας καθιερωμένος actionable driver.","Sieben Tage wegen gesicherter bakterieller Pneumonie; Infektion jetzt abgeheilt.":"Επτά ημέρες για επιβεβαιωμένη βακτηριακή πνευμονία· η λοίμωξη έχει πλέον υποχωρήσει.","Restmaterial ist knapp; zusätzliche Tumortests beantworten die Mikrobiomfrage nicht valide.":"Το υπόλοιπο υλικό είναι περιορισμένο· πρόσθετοι έλεγχοι όγκου δεν απαντούν έγκυρα στο ερώτημα μικροβιώματος.","Der Simulator enthält bewusst keinen 'Mikrobiom-ICI-Freigabetest', weil hierfür kein etablierter Routineassay mit validiertem Cutoff existiert.":"Ο simulator σκόπιμα δεν περιλαμβάνει «τεστ έγκρισης ICI βάσει μικροβιώματος», επειδή δεν υπάρχει καθιερωμένη εξέταση ρουτίνας με επικυρωμένο cutoff για αυτόν τον σκοπό.","Die entscheidende Zusatzinformation ist klinisch: Indikation, Zeitpunkt, Dauer und Infektionsstatus.":"Η καθοριστική πρόσθετη πληροφορία είναι κλινική: ένδειξη, χρονισμός, διάρκεια και κατάσταση της λοίμωξης.","Was lässt sich aus der Beobachtung 'Antibiotika um ICI-Beginn sind mit schlechterem Outcome assoziiert' für diesen Patienten ableiten?":"Τι μπορεί να συναχθεί για αυτόν τον ασθενή από την παρατήρηση ότι «τα αντιβιοτικά γύρω από την έναρξη ICI συσχετίζονται με χειρότερη έκβαση»;","Es ist ein relevanter möglicher Risiko-/Biologiekontext, aber kein kausaler individueller Resistenztest; Confounding durch Infektion und Krankheitsstatus muss bedacht werden.":"Αποτελεί σχετικό πιθανό πλαίσιο κινδύνου/βιολογίας, αλλά όχι αιτιώδες ατομικό τεστ αντοχής· πρέπει να ληφθεί υπόψη confounding από τη λοίμωξη και την κατάσταση της νόσου.","Antibiotika beweisen, dass ICI nicht mehr wirken kann.":"Τα αντιβιοτικά αποδεικνύουν ότι το ICI δεν μπορεί πλέον να λειτουργήσει.","Beobachtungsdaten sind grundsätzlich wertlos und dürfen nie erwähnt werden.":"Τα παρατηρησιακά δεδομένα είναι θεμελιωδώς άχρηστα και δεν πρέπει ποτέ να αναφέρονται.","ICI muss nach jeder Antibiotikagabe zwingend für einen festen Zeitraum verschoben werden.":"Το ICI πρέπει πάντοτε να αναβάλλεται για σταθερό χρονικό διάστημα μετά από οποιαδήποτε αντιβιοτική αγωγή.","Beobachtungsassoziationen sind klinisch relevant, aber nicht gleichbedeutend mit kausaler patientenindividueller Vorhersage.":"Οι παρατηρησιακές συσχετίσεις είναι κλινικά σημαντικές, αλλά δεν ισοδυναμούν με αιτιώδη πρόβλεψη ειδική για τον ασθενή.","War die Antibiotikatherapie onkologisch ein Fehler?":"Ήταν η αντιβιοτική αγωγή ογκολογικό λάθος;","Nein. Eine gesicherte bakterielle Pneumonie musste behandelt werden; unnötige Antibiotika sollten vermieden werden, notwendige aber nicht aus Mikrobiomangst vorenthalten werden.":"Όχι. Η επιβεβαιωμένη βακτηριακή πνευμονία απαιτούσε θεραπεία· τα περιττά αντιβιοτικά πρέπει να αποφεύγονται, αλλά η αναγκαία θεραπεία δεν πρέπει να παραλείπεται από φόβο για το μικροβίωμα.","Ja. Vor ICI dürfen Antibiotika nie gegeben werden.":"Ναι. Δεν πρέπει ποτέ να δίνονται αντιβιοτικά πριν από ICI.","Nur wenn gleichzeitig FMT gegeben wird, war sie vertretbar.":"Ήταν αποδεκτή μόνο εάν χορηγήθηκε ταυτόχρονα FMT.","Bei PD-L1 80 % ist eine Infektionsbehandlung generell unwichtig.":"Με PD-L1 80%, η θεραπεία μιας λοίμωξης είναι γενικά ασήμαντη.","Patientensicherheit und Behandlung einer realen Infektion haben Vorrang vor nicht validierter Mikrobiomoptimierung.":"Η ασφάλεια του ασθενούς και η θεραπεία πραγματικής λοίμωξης υπερισχύουν μη επικυρωμένης βελτιστοποίησης του μικροβιώματος.","Soll jetzt routinemäßig ein Mikrobiomtest, Probiotikum oder FMT zur 'Rettung' der ICI-Wirkung veranlasst werden?":"Πρέπει τώρα να ζητηθεί ως ρουτίνα έλεγχος μικροβιώματος, προβιοτικό ή FMT για να «σωθεί» η αποτελεσματικότητα ICI;","Nein. Solche Strategien sind derzeit nicht als routinemäßige patientenindividuelle Kompensation validiert und gehören gegebenenfalls in Studien.":"Όχι. Τέτοιες στρατηγικές δεν είναι σήμερα επικυρωμένες ως ατομική αντιστάθμιση ρουτίνας και, εάν εξετάζονται, ανήκουν σε κλινικές μελέτες.","FMT ist nach Antibiotika vor ICI Standard.":"Το FMT είναι standard μετά από αντιβιοτικά πριν από ICI.","Ein frei verkäufliches Probiotikum ist evidenzbasiert obligat.":"Ένα προβιοτικό χωρίς συνταγή είναι τεκμηριωμένο και υποχρεωτικό.","Ein einzelnes 16S-Profil kann zuverlässig die ICI-Wirkung vorhersagen.":"Ένα μεμονωμένο προφίλ 16S μπορεί να προβλέψει αξιόπιστα την αποτελεσματικότητα ICI.","Mikrobiominterventionen sind ein Forschungsfeld, kein etablierter Routinealgorithmus zur ICI-Freigabe.":"Οι παρεμβάσεις στο μικροβίωμα αποτελούν πεδίο έρευνας, όχι καθιερωμένο αλγόριθμο ρουτίνας για «έγκριση» ICI.","Welche Information sollte die Therapieentscheidung stärker tragen?":"Ποια πληροφορία πρέπει να έχει μεγαλύτερο βάρος στη θεραπευτική απόφαση;","Validierter NSCLC-Kontext aus Histologie, vollständigem Driverprofil, PD-L1, Klinik und Infektionsstatus; Antibiotikaexposition als zusätzlicher Unsicherheits-/Risikokontext.":"Επικυρωμένο πλαίσιο NSCLC από ιστολογία, πλήρες driver profile, PD-L1, κλινική κατάσταση και κατάσταση λοίμωξης· η έκθεση σε αντιβιοτικά ως πρόσθετο πλαίσιο αβεβαιότητας/κινδύνου.","Allein die Antibiotikaexposition.":"Μόνο η έκθεση σε αντιβιοτικά.","Ein zusätzlicher TMB-Wert unabhängig von PD-L1 und Driverstatus.":"Μια πρόσθετη τιμή TMB ανεξάρτητα από PD-L1 και driver status.","Ein experimentelles Darmmikrobiomprofil.":"Ένα πειραματικό προφίλ εντερικού μικροβιώματος.","Evidenzhierarchie verhindert, dass ein interessanter Forschungsmarker etablierte Therapiebiomarker verdrängt.":"Η ιεραρχία τεκμηρίωσης αποτρέπει έναν ενδιαφέροντα ερευνητικό δείκτη από το να εκτοπίσει καθιερωμένους θεραπευτικούς βιοδείκτες.","Formulieren Sie eine MTB-Empfehlung, die die Antibiotika-/Mikrobiomassoziation ernst nimmt, aber die individuelle Therapieentscheidung auf validierte NSCLC-Biomarker und den aktuellen klinischen Zustand stützt.":"Διατυπώστε σύσταση MTB που λαμβάνει σοβαρά τη συσχέτιση αντιβιοτικών/μικροβιώματος, αλλά βασίζει την ατομική θεραπευτική απόφαση σε επικυρωμένους βιοδείκτες NSCLC και στην τρέχουσα κλινική κατάσταση.","Driver-negatives NSCLC und PD-L1 TPS 80 % als validierten Tumorkontext priorisieren.":"Δώστε προτεραιότητα στο driver-negative NSCLC και PD-L1 TPS 80% ως επικυρωμένο πλαίσιο όγκου.","Antibiotikaexposition zeitlich und indikationsbezogen dokumentieren.":"Τεκμηριώστε την έκθεση σε αντιβιοτικά με χρονισμό και ένδειξη.","Assoziation mit schlechterem ICI-Outcome als Beobachtungsbefund mit möglichem Confounding erklären.":"Εξηγήστε τη συσχέτιση με χειρότερες εκβάσεις ICI ως παρατηρησιακό εύρημα με πιθανό confounding.","Notwendige Infektionsbehandlung nicht als Fehler darstellen.":"Μην παρουσιάζετε την αναγκαία θεραπεία της λοίμωξης ως σφάλμα.","Keine absolute ICI-Kontraindikation oder fixe Wartezeit allein aus Antibiotika ableiten.":"Μην εξάγετε από τα αντιβιοτικά μόνο απόλυτη αντένδειξη για ICI ή σταθερή περίοδο αναμονής.","Keine routinemäßigen Mikrobiomtests/Probiotika/FMT außerhalb validierter Indikation bzw. klinischer Studien empfehlen.":"Μη συστήνετε ως ρουτίνα τεστ μικροβιώματος/προβιοτικά/FMT εκτός επικυρωμένης ένδειξης ή κλινικής μελέτης.","Wenn nach Abheilung der Infektion klinische Gründe für eine kurze Verzögerung bestehen, diese klinisch und nicht als 'Mikrobiom-Washout' begründen.":"Εάν υπάρχουν κλινικοί λόγοι για μικρή καθυστέρηση μετά την υποχώρηση της λοίμωξης, αιτιολογήστε την κλινικά και όχι ως «microbiome washout». ","Mikrobiomstudie anbieten, sofern verfügbar und ohne die Standardtherapie unangemessen zu verzögern.":"Προσφέρετε συμμετοχή σε μελέτη μικροβιώματος εφόσον είναι διαθέσιμη και δεν καθυστερεί αδικαιολόγητα την καθιερωμένη θεραπεία.","Antibiotika = absolute ICI-Kontraindikation":"Αντιβιοτικά = απόλυτη αντένδειξη για ICI","Dafür existiert kein validierter patientenindividueller Entscheidungsalgorithmus.":"Δεν υπάρχει επικυρωμένος αλγόριθμος απόφασης ειδικός για τον ασθενή γι’ αυτό.","Notwendige Infektion unbehandelt lassen":"Αφήστε χωρίς θεραπεία λοίμωξη που χρειάζεται αντιμετώπιση","Patientensicherheit und Infektionskontrolle haben Vorrang.":"Η ασφάλεια του ασθενούς και ο έλεγχος της λοίμωξης έχουν προτεραιότητα.","FMT/Probiotika als Routine":"FMT/προβιοτικά ως ρουτίνα","Experimentelle Interventionen dürfen nicht als Standard verkauft werden.":"Οι πειραματικές παρεμβάσεις δεν πρέπει να παρουσιάζονται ως πρότυπο φροντίδας.","Mehr Tumortests bestellen":"Παραγγείλετε περισσότερους ελέγχους όγκου","TMB/TILs quantifizieren keinen individuellen Antibiotika-Mikrobiomeffekt.":"TMB/TIL δεν ποσοτικοποιούν ατομικό αποτέλεσμα αντιβιοτικών-μικροβιώματος.","Das Antibiotikum war möglicherweise biologisch ungünstig – und trotzdem medizinisch richtig":"Το αντιβιοτικό μπορεί να ήταν βιολογικά δυσμενές — και παρ’ όλα αυτά ιατρικά σωστό","Die Literaturassoziation ist plausibel und soll nicht weggewischt werden. Gleichzeitig war die Pneumonie mikrobiologisch gesichert und behandlungsbedürftig. Der zentrale Twist ist daher epistemisch: Ein möglicher negativer Biomarker-/Expositionskontext macht eine notwendige Behandlung nicht falsch und liefert keine validierte individuelle ICI-Kontraindikation.":"Η συσχέτιση στη βιβλιογραφία είναι εύλογη και δεν πρέπει να απορρίπτεται. Ταυτόχρονα, η πνευμονία ήταν μικροβιολογικά επιβεβαιωμένη και απαιτούσε θεραπεία. Το κεντρικό twist είναι επομένως επιστημολογικό: ένα δυνητικά δυσμενές πλαίσιο βιοδείκτη/έκθεσης δεν καθιστά λανθασμένη μια αναγκαία θεραπεία ούτε παρέχει επικυρωμένη ατομική αντένδειξη για ICI.","Der Fall trainiert Evidenzstufen, Confounding und die Fähigkeit, populationsbasierte Forschung nicht in überharte Einzelpatientenregeln zu übersetzen.":"Η περίπτωση εκπαιδεύει στη διαβάθμιση τεκμηρίωσης, στο confounding και στην ικανότητα να μη μετατρέπεται η πληθυσμιακή έρευνα σε υπερβολικά άκαμπτους κανόνες για τον μεμονωμένο ασθενή.","Evidenz sauber begrenzt":"Σωστός περιορισμός της τεκμηρίωσης","Driver-negatives NSCLC, PD-L1 TPS 80 %. Antibiotika wegen gesicherter Pneumonie waren notwendig. Exposition als möglicher Outcome-Kontext erwähnen, aber keine absolute ICI-Kontraindikation oder Mikrobiom-Routineintervention ableiten.":"Driver-negative NSCLC, PD-L1 TPS 80%. Τα αντιβιοτικά για επιβεβαιωμένη πνευμονία ήταν αναγκαία. Αναφέρετε την έκθεση ως πιθανό πλαίσιο έκβασης, αλλά μην εξάγετε απόλυτη αντένδειξη για ICI ή παρέμβαση ρουτίνας στο μικροβίωμα.","Validierte Biomarker und unsichere Exposition korrekt gewichtet.":"Οι επικυρωμένοι βιοδείκτες και η αβέβαιη έκθεση σταθμίστηκαν σωστά.","Assoziation erkannt, aber zu viel Unsicherheit":"Η συσχέτιση αναγνωρίστηκε, αλλά με υπερβολική αβεβαιότητα","Antibiotikadaten werden erwähnt, die Therapie wird jedoch ohne belastbare Grundlage allein deshalb unbestimmt verschoben.":"Αναφέρονται τα δεδομένα αντιβιοτικών, αλλά η θεραπεία αναβάλλεται αόριστα αποκλειστικά γι’ αυτό χωρίς ισχυρή τεκμηρίωση.","Beobachtungsdaten zu stark operationalisiert.":"Υπερβολική επιχειρησιακή εφαρμογή παρατηρησιακών δεδομένων.","ICI gestrichen, FMT empfohlen":"Ακύρωση ICI, σύσταση FMT","Antibiotika werden als Beweis für ICI-Resistenz behandelt und FMT/Probiotika als Routine empfohlen.":"Τα αντιβιοτικά αντιμετωπίζονται ως απόδειξη αντοχής σε ICI και FMT/προβιοτικά συστήνονται ως ρουτίνα.","Evidenzniveau und Patientensicherheit verfehlt.":"Αστοχία στο επίπεδο τεκμηρίωσης και στην ασφάλεια του ασθενούς.","Infektion klinisch abgeheilt":"Κλινική ύφεση λοίμωξης","Systemtherapie nach regulären onkologischen Kriterien planen; keine fixe 'Mikrobiom-Wartezeit' erfinden.":"Σχεδιάστε τη συστηματική θεραπεία με τα συνήθη ογκολογικά κριτήρια· μην επινοείτε σταθερή «περίοδο αναμονής μικροβιώματος». ","Die Therapie wird nicht aufgrund unvalidierter Surrogate unangemessen verzögert.":"Η θεραπεία δεν καθυστερεί αδικαιολόγητα λόγω μη επικυρωμένων surrogate δεικτών.","künftige Antibiotikafrage":"Μελλοντικό ερώτημα αντιβιοτικών","Antibiotic stewardship: unnötige Exposition vermeiden, notwendige Infektionen zielgerichtet behandeln.":"Antibiotic stewardship: αποφεύγετε περιττή έκθεση και αντιμετωπίζετε στοχευμένα τις λοιμώξεις που χρειάζονται θεραπεία.","Pragmatische Risikoreduktion ohne Pseudopräzision.":"Πραγματιστική μείωση κινδύνου χωρίς ψευδο-ακρίβεια.","Mikrobiomstudie verfügbar":"Διαθέσιμη μελέτη μικροβιώματος","Teilnahme als Forschungsoption diskutieren.":"Συζητήστε τη συμμετοχή ως ερευνητική επιλογή.","Innovative Ansätze bleiben im passenden Evidenzrahmen.":"Οι καινοτόμες προσεγγίσεις παραμένουν στο κατάλληλο πλαίσιο τεκμηρίωσης.","Antibiotikaexposition um ICI ist in Beobachtungsdaten mit schlechteren Outcomes assoziiert, aber Confounding ist relevant.":"Η έκθεση σε αντιβιοτικά γύρω από ICI συσχετίζεται με χειρότερες εκβάσεις σε παρατηρησιακά δεδομένα, αλλά το confounding είναι σημαντικό.","Eine klinisch notwendige Antibiotikatherapie darf nicht aus Angst vor Mikrobiomeffekten vorenthalten werden.":"Η κλινικά αναγκαία αντιβιοτική αγωγή δεν πρέπει να παραλείπεται από φόβο για επιδράσεις στο μικροβίωμα.","Es gibt keinen etablierten Routine-Mikrobiomtest, der nach Antibiotika die individuelle ICI-Wirkung freigibt oder ausschließt.":"Δεν υπάρχει καθιερωμένο τεστ μικροβιώματος ρουτίνας που να εγκρίνει ή να αποκλείει την ατομική αποτελεσματικότητα ICI μετά από αντιβιοτικά.","FMT/Probiotika zur ICI-Optimierung sind Forschungsansätze, keine Standardkompensation.":"FMT/προβιοτικά για βελτιστοποίηση ICI είναι ερευνητικές προσεγγίσεις, όχι τυπική αντιστάθμιση.","Präzisionsonkologie bedeutet auch, Evidenzgrenzen präzise zu kommunizieren.":"Η ογκολογία ακριβείας σημαίνει επίσης ακριβή επικοινωνία των ορίων της τεκμηρίωσης.","PD-L1 TPS 80 % bei driver-negativem NSCLC bleibt ein etablierter Therapiebiomarkerkontext. Die kürzlich notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext relevant, aber keine validierte individuelle Kontraindikation. Keine unvalidierte fixe Wartezeit oder routinemäßige Mikrobiomintervention ableiten; unnötige Antibiotika künftig vermeiden, notwendige behandeln.":"PD-L1 TPS 80% σε driver-negative NSCLC παραμένει καθιερωμένο πλαίσιο θεραπευτικού βιοδείκτη. Η πρόσφατη αναγκαία αντιβιοτική αγωγή είναι σχετική ως πιθανό πλαίσιο έκβασης, αλλά όχι ως επικυρωμένη ατομική αντένδειξη. Μην εξάγετε μη επικυρωμένη σταθερή περίοδο αναμονής ή παρέμβαση ρουτίνας στο μικροβίωμα· αποφεύγετε μελλοντικά τα περιττά αντιβιοτικά και θεραπεύετε όταν είναι αναγκαίο.","Assoziation ≠ Kausalität":"Συσχέτιση ≠ αιτιότητα","Confounding erkannt":"Αναγνώριση confounding","Patientensicherheit":"Ασφάλεια ασθενούς","validierte Biomarker priorisiert":"Προτεραιοποίηση επικυρωμένων βιοδεικτών","keine unvalidierte Mikrobiomtherapie":"Καμία μη επικυρωμένη θεραπεία μικροβιώματος","Welche Confounder erklären die Antibiotika-ICI-Assoziation möglicherweise mit?":"Ποιοι συγχυτικοί παράγοντες μπορεί να εξηγούν εν μέρει τη συσχέτιση αντιβιοτικών-ICI;","Wann wird aus einem prognostischen Faktor ein prädiktiver Biomarker?":"Πότε ένας προγνωστικός παράγοντας γίνεται προβλεπτικός βιοδείκτης;","Wie kommuniziert man interessante, aber nicht handlungsleitende Forschung im MTB?":"Πώς επικοινωνείτε στο MTB ενδιαφέρουσα έρευνα που όμως δεν καθοδηγεί δράση;","notwendige Antibiotikatherapie trotz möglicher negativer Assoziation":"Αναγκαία αντιβιοτική αγωγή παρά πιθανή αρνητική συσχέτιση","Populationsassoziation ist keine individuelle Kontraindikation":"Η πληθυσμιακή συσχέτιση δεν είναι ατομική αντένδειξη","validierte Tumorbiomarker → Antibiotikaindikation → Evidenzgrad → keine Pseudopräzision":"επικυρωμένοι βιοδείκτες όγκου → ένδειξη αντιβιοτικών → επίπεδο τεκμηρίωσης → χωρίς ψευδο-ακρίβεια","IDH-mutiertes Gliom: R132H-IHC negativ – und trotzdem IDH-mutiert":"IDH-mutant γλοίωμα: R132H-IHC αρνητική — και όμως IDH-mutant","IDH-mutiertes Gliom mit G-CIMP-Pro…":"IDH-mutant γλοίωμα με προφίλ G-CIMP…","Neuropathologie / Neuroonkologisches Tumorboard":"Νευροπαθολογία / Νευρο-ογκολογικό tumor board","36-jähriger Patient nach Resektion eines linksfrontalen diffus infiltrierenden Glioms. Die IDH1-R132H-IHC ist negativ; Alter und Morphologie passen jedoch schlecht zu einem typischen IDH-Wildtyp-Glioblastom.":"36χρονος άνδρας μετά από εκτομή αριστερού μετωπιαίου διάχυτα διηθητικού γλοιώματος. Η IDH1 R132H-IHC είναι αρνητική· όμως ηλικία και μορφολογία δεν ταιριάζουν καλά με τυπικό IDH-wildtype γλοιοβλάστωμα.","Darf der Tumor nach negativer R132H-IHC als IDH-Wildtyp eingeordnet werden – und welche Rolle spielt das Methylierungsprofil?":"Μπορεί ο όγκος να ταξινομηθεί ως IDH-wildtype μετά από αρνητική R132H-IHC — και ποιος είναι ο ρόλος του προφίλ μεθυλίωσης;","Die integrierte Diagnose soll vor Festlegung der adjuvanten Therapie finalisiert werden.":"Η ολοκληρωμένη διάγνωση πρέπει να οριστικοποιηθεί πριν καθοριστεί η επικουρική θεραπεία.","Erstmanifestation mit fokalem Krampfanfall; MRT zeigt einen nicht kontrastmittelaufnehmenden frontalen Tumor.":"Αρχική εκδήλωση με εστιακή κρίση· MRI δείχνει μετωπιαίο όγκο χωρίς πρόσληψη σκιαγραφικού.","36 Jahre – damit ist eine nicht-kanonische IDH-Alteration klinisch relevant genug, um nach negativer R132H-IHC nicht vorschnell abzubrechen.":"Ηλικία 36 ετών — αρκετά σημαντική κλινικά ώστε μια μη κανονική αλλοίωση IDH να μην αποκλειστεί πρόωρα μετά από αρνητική R132H-IHC.","ATRX-Verlust und diffuse p53-Überexpression; 1p/19q-Kodeletion nicht nachweisbar.":"Απώλεια ATRX και διάχυτη υπερέκφραση p53· δεν ανιχνεύεται codeletion 1p/19q.","Eine negative mutationsspezifische IHC wird mit einem negativen Genstatus gleichgesetzt.":"Ένα αρνητικό αποτέλεσμα IHC ειδικό για μετάλλαξη εξισώνεται με αρνητικό γονιδιακό status.","Diffus infiltrierendes astrozytäres Gliom, mäßige Zelldichte, keine Nekrosen oder mikrovaskuläre Proliferation.":"Διάχυτα διηθητικό αστροκυτταρικό γλοίωμα, μέτρια κυτταροβρίθεια, χωρίς νέκρωση ή μικροαγγειακό πολλαπλασιασμό.","IDH1 R132H negativ; ATRX nukleär verloren; p53 in großer Tumorzellfraktion stark positiv.":"IDH1 R132H αρνητικό· πυρηνική απώλεια ATRX· έντονη θετικότητα p53 σε μεγάλο ποσοστό καρκινικών κυττάρων.","Molekulare Vorinformation":"Προηγούμενες μοριακές πληροφορίες","1p/19q intakt.":"1p/19q ακέραιο.","Nicht-kanonische IDH1/2-Mutation? Passt das epigenetische Gesamtprofil zu einem IDH-mutierten Astrozytom?":"Μη κανονική μετάλλαξη IDH1/2; Ταιριάζει το συνολικό επιγενετικό προφίλ με IDH-mutant αστροκύτωμα;","FFPE-Resektat, Block F6.":"FFPE υλικό εκτομής, block F6.","ca. 70 %, sehr gut geeignet.":"περ. 70%, πολύ καλά κατάλληλο.","ausreichend für Sequenzierung und Methylierungsprofil.":"επαρκές για αλληλούχηση και προφίλ μεθυλίωσης.","Eine fokale Bisulfit-PCR kann einzelne CpG-Loci untersuchen, ersetzt aber keinen genomeweiten CNS-Methylierungsclassifier.":"Μια εστιακή PCR διθειώδους μπορεί να εξετάσει μεμονωμένους CpG loci, αλλά δεν αντικαθιστά genome-wide classifier μεθυλίωσης CNS.","IDH1/2-Status vollständig klären":"Πλήρης διευκρίνιση status IDH1/2","CNS-Methylierungsprofil / Classifier":"Προφίλ μεθυλίωσης CNS / classifier","IDH1-R132H-IHC negativ; Sequenzierung zeigt eine pathogene nicht-kanonische IDH1-p.R132C-Mutation. Die negative R132H-IHC war daher kein Ausschluss eines IDH-mutierten Glioms.":"IDH1 R132H-IHC αρνητική· η αλληλούχηση δείχνει παθογόνο μη κανονική μετάλλαξη IDH1 p.R132C. Επομένως η αρνητική R132H-IHC δεν απέκλεισε IDH-mutant γλοίωμα.","Methylierungsclassifier":"Classifier μεθυλίωσης","Genomeweites Methylierungsprofil mit hochkonfidenter Zuordnung zur Familie der IDH-mutierten Astrozytome und ausgeprägtem G-CIMP-typischem Hypermethylierungsmuster.":"Genome-wide προφίλ μεθυλίωσης με υψηλής εμπιστοσύνης ταξινόμηση στην οικογένεια IDH-mutant αστροκυτωμάτων και έντονο G-CIMP-όμοιο πρότυπο υπερμεθυλίωσης.","Fokale Bisulfit-PCR":"Εστιακή PCR διθειώδους","Ein fokaler Methylierungsmarker ist messbar, erlaubt aber keine gleichwertige globale Tumorklassifikation und ist kein Ersatz für den CNS-Methylierungsclassifier.":"Ένας εστιακός δείκτης μεθυλίωσης μπορεί να μετρηθεί, αλλά δεν παρέχει ισοδύναμη συνολική ταξινόμηση του όγκου και δεν αντικαθιστά τον classifier μεθυλίωσης CNS.","Breites Panel":"Ευρύ panel","Zusätzliche Varianten ändern die zentrale integrierte Einordnung nicht; der breite Ansatz ist für die konkrete Klassifikationsfrage nicht zwingend erforderlich.":"Πρόσθετες παραλλαγές δεν αλλάζουν την κεντρική ολοκληρωμένη ταξινόμηση· μια ευρεία προσέγγιση δεν είναι απαραίτητη για το συγκεκριμένο ερώτημα ταξινόμησης.","Diffus infiltrierendes Astrozytom mit ATRX-Verlust und p53-Akkumulation; keine hochgradigen morphologischen Kriterien.":"Διάχυτα διηθητικό αστροκύτωμα με απώλεια ATRX και συσσώρευση p53· χωρίς μορφολογικά κριτήρια υψηλού βαθμού.","Tumoranteil und DNA-Qualität für Sequenzierung und Methylom geeignet.":"Ποσοστό όγκου και ποιότητα DNA κατάλληλα για αλληλούχηση και ανάλυση μεθυλώματος.","Die negative IDH1-R132H-IHC schließt bei diesem jungen Patienten eine IDH-Mutation nicht aus. Die Sequenzierung weist eine nicht-kanonische IDH1-p.R132C-Mutation nach; das genomeweite Methylierungsprofil unterstützt einen IDH-mutierten astrozytären Tumor und zeigt das erwartete G-CIMP-artige Hypermethylierungsmuster. Der Methylierungsclassifier ergänzt die integrierte Diagnose, ersetzt aber nicht Histologie und definierende molekulare Marker.":"Η αρνητική IDH1 R132H-IHC δεν αποκλείει μετάλλαξη IDH σε αυτόν τον νεαρό ασθενή. Η αλληλούχηση εντοπίζει μη κανονική μετάλλαξη IDH1 p.R132C· το genome-wide προφίλ μεθυλίωσης υποστηρίζει IDH-mutant αστροκυτταρικό όγκο και δείχνει το αναμενόμενο G-CIMP-όμοιο πρότυπο υπερμεθυλίωσης. Ο classifier μεθυλίωσης συμπληρώνει την ολοκληρωμένη διάγνωση, αλλά δεν αντικαθιστά την ιστολογία και τους καθοριστικούς μοριακούς δείκτες.","Teilbefund: Eine negative R132H-IHC allein reicht nicht, um den IDH-Status in diesem klinisch-morphologischen Kontext sicher festzulegen.":"Μερικό αποτέλεσμα: η αρνητική R132H-IHC από μόνη της δεν επαρκεί για ασφαλή καθορισμό του IDH status σε αυτό το κλινικομορφολογικό πλαίσιο.","R132H-IHC negativ nicht mit IDH1/2-Wildtyp gleichsetzen":"Μην εξισώνετε αρνητική R132H-IHC με IDH1/2 wildtype","Bei passendem Kontext Sequenzierung nicht-kanonischer IDH1/2-Varianten einfordern":"Στο κατάλληλο πλαίσιο, ζητήστε αλληλούχηση για μη κανονικές παραλλαγές IDH1/2","Methylierungsclassifier als integrativen Klassifikationsbaustein einordnen":"Εντάξτε τον classifier μεθυλίωσης ως ολοκληρωτικό διαγνωστικό στοιχείο","G-CIMP als biologisches/epigenetisches Muster erklären, nicht als isolierten Routinetest":"Εξηγήστε το G-CIMP ως βιολογικό/επιγενετικό πρότυπο, όχι ως μεμονωμένο τεστ ρουτίνας","Falschaussage: negative R132H-IHC beweist IDH-Wildtyp":"Λανθασμένη δήλωση: αρνητική R132H-IHC αποδεικνύει IDH wildtype","Optimale Lösung: R132H-IHC als Screening verstehen, nicht-kanonische IDH1/2-Mutationen bei passendem Kontext sequenzieren und das Methylom als integrativen, nicht alleinstehenden Klassifikationsbaustein verwenden.":"Βέλτιστη λύση: αντιληφθείτε την R132H-IHC ως screening, αλληλουχήστε μη κανονικές μεταλλάξεις IDH1/2 στο κατάλληλο πλαίσιο και χρησιμοποιήστε το μεθύλωμα ως ολοκληρωτικό, όχι αυτόνομο, στοιχείο ταξινόμησης.","Gliom":"Γλοίωμα","IDH1":"IDH1","non-canonical IDH":"μη κανονικό IDH","G-CIMP":"G-CIMP","Astrozytom":"Αστροκύτωμα","R132H negativ – aber nicht IDH-Wildtyp":"R132H αρνητικό — αλλά όχι IDH wildtype","Neuropathologie / Neuroonkologie / MTB":"Νευροπαθολογία / Νευρο-ογκολογία / MTB","IDH1-R132H-IHC als Screening und nicht als vollständigen IDH1/2-Ausschluss verstehen.":"Κατανοήστε την IDH1 R132H-IHC ως screening και όχι ως πλήρη αποκλεισμό αλλοιώσεων IDH1/2.","Bei jungem Patienten und passender Morphologie nicht-kanonische IDH1/2-Varianten sequenzieren.":"Σε νεαρό ασθενή με συμβατή μορφολογία, αλληλουχήστε μη κανονικές παραλλαγές IDH1/2.","G-CIMP als Folge der IDH-Biologie und nicht als isolierte Diagnose interpretieren.":"Ερμηνεύστε το G-CIMP ως συνέπεια της βιολογίας IDH και όχι ως μεμονωμένη διάγνωση.","Genomeweiten Methylierungsclassifier von fokaler Methylierungs-PCR unterscheiden.":"Διακρίνετε genome-wide classifier μεθυλίωσης από εστιακή PCR μεθυλίωσης.","Histologie, definierende Marker und Methylom zu einer integrierten Diagnose zusammenführen.":"Συνδυάστε ιστολογία, καθοριστικούς δείκτες και μεθύλωμα σε ολοκληρωμένη διάγνωση.","Die IDH1-R132H-IHC ist negativ. Der Patient ist aber 36, der Tumor sieht diffus astrozytär aus, ATRX ist verloren und 1p/19q intakt. Der vermeintlich einfache 'IDH-Wildtyp'-Stempel beginnt zu wackeln.":"Η IDH1 R132H-IHC είναι αρνητική. Όμως ο ασθενής είναι 36 ετών, ο όγκος φαίνεται διάχυτα αστροκυτταρικός, το ATRX έχει χαθεί και το 1p/19q είναι ακέραιο. Η φαινομενικά απλή ετικέτα «IDH-wildtype» αρχίζει να κλονίζεται.","36-jähriger Patient mit linksfrontalem diffus infiltrierendem Gliom. R132H-IHC negativ, ATRX-Verlust und p53-Akkumulation. Das Board muss entscheiden, ob weiter sequenziert wird und wie ein G-CIMP-/Methylierungsprofil die integrierte Diagnose unterstützt.":"36χρονος άνδρας με αριστερό μετωπιαίο διάχυτα διηθητικό γλοίωμα. R132H-IHC αρνητική, απώλεια ATRX και συσσώρευση p53. Το board πρέπει να αποφασίσει εάν θα συνεχίσει την αλληλούχηση και πώς ένα προφίλ G-CIMP/μεθυλίωσης υποστηρίζει την ολοκληρωμένη διάγνωση.","Screening ist nicht Sequenzierung":"Το screening δεν είναι αλληλούχηση","R132H-IHC erkennt die häufigste IDH1-Variante, nicht jede IDH1/2-Mutation.":"Η R132H-IHC ανιχνεύει τη συχνότερη παραλλαγή IDH1, όχι κάθε μετάλλαξη IDH1/2.","Ein negatives mutationsspezifisches Antikörperergebnis ist kein vollständiger Gen-Ausschluss.":"Ένα αρνητικό αποτέλεσμα αντισώματος ειδικού για μετάλλαξη δεν αποτελεί πλήρη αποκλεισμό σε επίπεδο γονιδίου.","Alter + Morphologie zählen":"Ηλικία + μορφολογία μετρούν","Junger Erwachsener, diffus astrozytärer Tumor, ATRX-Verlust.":"Νεαρός ενήλικας, διάχυτα αστροκυτταρικός όγκος, απώλεια ATRX.","Prätestwahrscheinlichkeit bestimmt, wann Sequenzierung trotz negativer IHC sinnvoll ist.":"Η προ-τεστ πιθανότητα καθορίζει πότε είναι χρήσιμη η αλληλούχηση παρά αρνητική IHC.","Epigenom als Integrator":"Επιγονιδίωμα ως ολοκληρωτής","IDH-Mutationen erzeugen ein charakteristisches Hypermethylierungsprogramm.":"Οι μεταλλάξεις IDH δημιουργούν χαρακτηριστικό πρόγραμμα υπερμεθυλίωσης.","Das Methylom unterstützt Klassifikation, ersetzt aber definierende Marker nicht.":"Το μεθύλωμα υποστηρίζει την ταξινόμηση, αλλά δεν αντικαθιστά τους καθοριστικούς δείκτες.","IDH1-R132H-IHC":"IDH1 R132H-IHC","ATRX/p53":"ATRX/p53","ATRX-Verlust, diffuse p53-Akkumulation":"Απώλεια ATRX, διάχυτη συσσώρευση p53","1p/19q":"1p/19q","keine Kodeletion":"χωρίς codeletion","Tumoranteil ca. 70 %, DNA gut.":"Ποσοστό όγκου περ. 70%, καλή ποιότητα DNA.","Keine Materialnot – die Herausforderung ist Testhierarchie, nicht Schnittökonomie.":"Δεν υπάρχει έλλειψη υλικού — η πρόκληση είναι η ιεραρχία εξετάσεων, όχι η οικονομία τομών.","Fokale Bisulfit-PCR ist kein Ersatz für genomeweite Klassifikation.":"Η εστιακή PCR διθειώδους δεν αντικαθιστά την ταξινόμηση σε επίπεδο γονιδιώματος.","Was ist der wichtigste Schluss aus negativer IDH1-R132H-IHC?":"Ποιο είναι το σημαντικότερο συμπέρασμα από αρνητική IDH1 R132H-IHC;","Bei passendem klinisch-morphologischem Kontext IDH1/2 sequenzieren, weil nicht-kanonische Mutationen übersehen werden können.":"Στο κατάλληλο κλινικομορφολογικό πλαίσιο, αλληλουχήστε IDH1/2 επειδή μπορεί να διαφύγουν μη κανονικές μεταλλάξεις.","IDH-Wildtyp ist sicher bewiesen.":"Το IDH wildtype έχει αποδειχθεί οριστικά.","Nur Methylierungsclassifier durchführen; Sequenzierung ist überflüssig.":"Πραγματοποιήστε μόνο classifier μεθυλίωσης· η αλληλούχηση είναι περιττή.","IDH ist bei Erwachsenen diagnostisch nicht relevant.":"Το IDH δεν είναι διαγνωστικά σημαντικό στους ενήλικες.","R132H-IHC ist hoch nützlich, aber mutationsspezifisch.":"Η R132H-IHC είναι πολύ χρήσιμη, αλλά ειδική για τη συγκεκριμένη μετάλλαξη.","Was bedeutet ein G-CIMP-artiges Profil am ehesten?":"Τι σημαίνει πιθανότερα ένα G-CIMP-όμοιο προφίλ;","Es ist ein epigenetisches Muster, das zur IDH-mutierten Biologie passt und die integrierte Klassifikation stützt.":"Είναι επιγενετικό πρότυπο συμβατό με IDH-mutant βιολογία και υποστηρίζει την ολοκληρωμένη ταξινόμηση.","Es definiert allein den WHO-Grad.":"Καθορίζει μόνο του τον βαθμό WHO.","Es ist ein eigenständiger zugelassener Therapietest.":"Είναι αυτόνομο εγκεκριμένο θεραπευτικό τεστ.","Es beweist eine Keimbahn-IDH-Mutation.":"Αποδεικνύει μετάλλαξη IDH βλαστικής σειράς.","G-CIMP ist biologischer/klassifikatorischer Kontext, kein alleiniger Therapie- oder Gradmarker.":"Το G-CIMP είναι βιολογικό/ταξινομικό πλαίσιο, όχι αυτόνομος δείκτης θεραπείας ή βαθμού.","Welche Aussage zum Methylierungsclassifier ist korrekt?":"Ποια δήλωση για τον classifier μεθυλίωσης είναι σωστή;","Genomeweites Profil kann diagnostisch stark sein, muss aber mit Histologie, QC und definierenden molekularen Markern integriert werden.":"Ένα genome-wide προφίλ μπορεί να είναι διαγνωστικά ισχυρό, αλλά πρέπει να ενσωματώνεται με ιστολογία, QC και καθοριστικούς μοριακούς δείκτες.","Der höchste Klassenname ist immer die Diagnose.":"Η ονομασία της υψηλότερης κλάσης είναι πάντα η διάγνωση.","Eine fokale Bisulfit-PCR ist gleichwertig.":"Μια εστιακή PCR διθειώδους είναι ισοδύναμη.","Methylom ersetzt IDH-Sequenzierung.":"Η ανάλυση μεθυλώματος αντικαθιστά την αλληλούχηση IDH.","Classifier ist stark, aber integrativ.":"Ο classifier είναι ισχυρός, αλλά ενσωματωτικός.","Sequenzierung zeigt IDH1 p.R132C. Was kippt dadurch?":"Η αλληλούχηση δείχνει IDH1 p.R132C. Τι αλλάζει;","Der Tumor ist IDH-mutiert; die negative R132H-IHC war ein Screening-False-negative für diese nicht-kanonische Variante.":"Ο όγκος είναι IDH-mutant· η αρνητική R132H-IHC ήταν screening false negative για αυτή τη μη κανονική παραλλαγή.","Die Sequenzierung muss falsch sein, weil die IHC negativ war.":"Η αλληλούχηση πρέπει να είναι λανθασμένη επειδή η IHC ήταν αρνητική.","IDH-Status bleibt Wildtyp.":"Το IDH status παραμένει wildtype.","Es folgt Keimbahndiagnostik auf Lynch.":"Προχωρήστε σε έλεγχο βλαστικής σειράς για σύνδρομο Lynch.","Nicht-kanonische IDH-Varianten sind der zentrale Twist.":"Οι μη κανονικές παραλλαγές IDH αποτελούν το κεντρικό twist.","Formulieren Sie die integrierte neuropathologische Kernaussage und begründen Sie, warum nach negativer R132H-IHC sequenziert wurde und wie das Methylom gewichtet wird.":"Διατυπώστε το ολοκληρωμένο νευροπαθολογικό συμπέρασμα και αιτιολογήστε γιατί έγινε αλληλούχηση μετά από αρνητική R132H-IHC και πώς σταθμίζεται το μεθύλωμα.","R132H-IHC als Screening einordnen.":"Εντάξτε την R132H-IHC ως screening test.","Nicht-kanonische IDH1/2-Sequenzierung bei hoher Prätestwahrscheinlichkeit durchführen.":"Πραγματοποιήστε αλληλούχηση μη κανονικών IDH1/2 όταν η προ-τεστ πιθανότητα είναι υψηλή.","IDH1 p.R132C als definierenden Befund anerkennen.":"Αναγνωρίστε το IDH1 p.R132C ως καθοριστικό εύρημα.","Methylierungsprofil/G-CIMP als konsistenten integrativen Baustein berichten.":"Αναφέρετε το προφίλ μεθυλίωσης/G-CIMP ως συμβατό ολοκληρωτικό στοιχείο.","Fokale Methylierungs-PCR nicht als gleichwertigen Classifier-Ersatz darstellen.":"Μην παρουσιάζετε εστιακή PCR μεθυλίωσης ως ισοδύναμο υποκατάστατο του classifier.","Auf Methylierungsclassifier verzichten, wenn Histologie und definierende molekulare Marker bereits eindeutig sind; in diesem Fall ist er didaktisch/klassifikatorisch zusätzlich hilfreich.":"Ο classifier μεθυλίωσης μπορεί να παραλειφθεί όταν ιστολογία και καθοριστικοί μοριακοί δείκτες είναι ήδη σαφείς· σε αυτή την περίπτωση είναι επιπλέον χρήσιμος διδακτικά/ταξινομικά.","Breites Panel nur bei zusätzlicher klinischer Fragestellung.":"Χρησιμοποιήστε ευρύ panel μόνο εάν υπάρχει πρόσθετο κλινικό ερώτημα.","R132H-negativ = IDH-WT":"R132H αρνητικό = IDH-WT","Mutationsspezifische IHC erfasst nicht alle IDH1/2-Varianten.":"Η IHC ειδική για μετάλλαξη δεν ανιχνεύει όλες τις παραλλαγές IDH1/2.","Classifier statt Sequenzierung":"Classifier αντί αλληλούχησης","Definierende Genalteration und epigenetische Klasse sind unterschiedliche Ebenen.":"Μια καθοριστική γονιδιακή αλλοίωση και μια επιγενετική κλάση είναι διαφορετικά επίπεδα πληροφορίας.","G-CIMP als Therapiebiomarker":"G-CIMP ως θεραπευτικός βιοδείκτης","Das Muster ist biologisch/klassifikatorisch, nicht allein handlungsleitend.":"Το πρότυπο είναι βιολογικό/ταξινομικό, όχι αυτοτελώς καθοδηγητικό για δράση.","Der 'negative' IDH-Test wird positiv":"Το «αρνητικό» τεστ IDH γίνεται θετικό","Die Sequenzierung weist IDH1 p.R132C nach. Gleichzeitig ordnet der Methylierungsclassifier den Tumor hochkonfident der IDH-mutierten Astrozytomfamilie zu. Der Twist ist kein Laborwiderspruch, sondern zeigt die Grenze einer mutationsspezifischen IHC.":"Η αλληλούχηση εντοπίζει IDH1 p.R132C. Ταυτόχρονα, ο classifier μεθυλίωσης αποδίδει με υψηλή εμπιστοσύνη τον όγκο στην οικογένεια IDH-mutant αστροκυτωμάτων. Το twist δεν είναι εργαστηριακή αντίφαση, αλλά δείχνει το όριο της IHC ειδικής για μετάλλαξη.","Er trainiert Prätestwahrscheinlichkeit, Methodengrenzen und integrierte CNS-Diagnostik.":"Εκπαιδεύει στην προ-τεστ πιθανότητα, στα όρια των μεθόδων και στην ολοκληρωμένη διαγνωστική CNS.","Screeninggrenze erkannt":"Αναγνώριση ορίου screening","R132H-IHC negativ, IDH1 p.R132C sequenziert, Methylom konsistent mit IDH-mutiertem Astrozytom/G-CIMP.":"R132H-IHC αρνητική, IDH1 p.R132C ανιχνεύεται με αλληλούχηση, μεθύλωμα συμβατό με IDH-mutant αστροκύτωμα/G-CIMP.","Methoden korrekt hierarchisiert.":"Οι μέθοδοι ιεραρχήθηκαν σωστά.","Methylom richtig, IDH zu spät":"Σωστό μεθύλωμα, IDH πολύ αργά","Classifier wird genutzt, die notwendige IDH1/2-Sequenzierung aber nicht sauber begründet.":"Χρησιμοποιείται ο classifier, αλλά η αναγκαία αλληλούχηση IDH1/2 δεν αιτιολογείται σωστά.","Definierenden Marker nicht durch Epigenom ersetzen.":"Μην αντικαθιστάτε καθοριστικό δείκτη με το επιγονιδίωμα.","IDH-Wildtyp abgestempelt":"Χαρακτηρίστηκε IDH-wildtype","Nach negativer R132H-IHC wird keine Sequenzierung veranlasst.":"Δεν ζητείται αλληλούχηση μετά από αρνητική R132H-IHC.","Zentralen methodischen Fallstrick verpasst.":"Παραλείφθηκε η κεντρική μεθοδολογική παγίδα.","Nicht-kanonische IDH-Mutation":"Μη κανονική μετάλλαξη IDH","Integrierte Diagnose entsprechend IDH-mutierter Entität formulieren.":"Διατυπώστε την ολοκληρωμένη διάγνωση σύμφωνα με την IDH-mutant οντότητα.","Der Tumor verlässt den IDH-Wildtyp-Pfad.":"Ο όγκος εγκαταλείπει τη διαδρομή IDH-wildtype.","Methylom diskordant":"Ασύμφωνο μεθύλωμα","QC, Tumoranteil und Differenzialdiagnose erneut prüfen.":"Επανεκτιμήστε QC, ποσοστό όγκου και διαφορική διάγνωση.","Keine automatisierte Übersteuerung der Morphologie.":"Καμία αυτόματη υπερίσχυση της μορφολογίας.","IDH1-R132H-IHC ist ein sehr gutes Screening, aber kein vollständiger IDH1/2-Ausschluss.":"Η IDH1 R132H-IHC είναι εξαιρετικό screening, αλλά όχι πλήρης αποκλεισμός IDH1/2.","Nicht-kanonische IDH-Mutationen sind besonders bei jüngeren Patienten mit passendem diffusem Gliom relevant.":"Οι μη κανονικές μεταλλάξεις IDH είναι ιδιαίτερα σημαντικές σε νεότερους ασθενείς με κατάλληλο πλαίσιο διάχυτου γλοιώματος.","IDH-Biologie erzeugt charakteristische epigenetische Muster wie G-CIMP.":"Η βιολογία IDH δημιουργεί χαρακτηριστικά επιγενετικά πρότυπα όπως το G-CIMP.","Methylierungsclassifier sind integrative Diagnostikwerkzeuge, keine Orakel.":"Οι classifiers μεθυλίωσης είναι ολοκληρωτικά διαγνωστικά εργαλεία, όχι μαντεία.","Fokale Methylierungs-PCR und genomeweiter Classifier beantworten unterschiedliche Fragen.":"Η εστιακή PCR μεθυλίωσης και ένας genome-wide classifier απαντούν διαφορετικά ερωτήματα.","Bei diesem 36-jährigen Patienten darf die negative R132H-IHC nicht als vollständiger IDH-Wildtyp-Nachweis gelten. IDH1/2-Sequenzierung weist IDH1 p.R132C nach. Das Methylierungsprofil unterstützt die IDH-mutierte astrozytäre Klassifikation und zeigt ein G-CIMP-artiges Muster. Histologie, IDH, ATRX/p53/1p19q und Methylom werden integriert.":"Σε αυτόν τον 36χρονο ασθενή, η αρνητική R132H-IHC δεν πρέπει να θεωρηθεί πλήρης απόδειξη IDH-wildtype status. Η αλληλούχηση IDH1/2 ανιχνεύει IDH1 p.R132C. Το προφίλ μεθυλίωσης υποστηρίζει IDH-mutant αστροκυτταρική ταξινόμηση και δείχνει G-CIMP-όμοιο πρότυπο. Ενσωματώνονται ιστολογία, IDH, ATRX/p53/1p19q και μεθύλωμα.","Screeninggrenze R132H-IHC":"Όριο screening της R132H-IHC","nicht-kanonische Sequenzierung":"Αλληλούχηση μη κανονικών παραλλαγών","Classifier integrativ":"Classifier ως ολοκληρωτικό εργαλείο","G-CIMP korrekt eingeordnet":"Σωστή ερμηνεία G-CIMP","Wann reicht R132H-IHC allein?":"Πότε αρκεί μόνο η R132H-IHC;","Warum ist Prätestwahrscheinlichkeit in der Molekularpathologie wichtig?":"Γιατί είναι σημαντική η προ-τεστ πιθανότητα στη μοριακή παθολογία;","Was kann ein Methylierungsclassifier, was eine fokale Bisulfit-PCR nicht kann?":"Τι μπορεί να κάνει ένας classifier μεθυλίωσης που δεν μπορεί μια εστιακή PCR διθειώδους;","IDH1 p.R132C trotz negativer R132H-IHC":"IDH1 p.R132C παρά αρνητική R132H-IHC","Negativer Screeningtest ist nicht automatisch negativer Genstatus":"Ένα αρνητικό screening test δεν σημαίνει αυτόματα αρνητικό γονιδιακό status","R132H-IHC → Sequenzierung → Methylom → integrierte Diagnose":"R132H-IHC → αλληλούχηση → μεθύλωμα → ολοκληρωμένη διάγνωση","Unklarer ZNS-Tumor: Der Methylierungsclassifier hilft – aber nur bei guter Probe":"Ασαφής όγκος CNS: ο classifier μεθυλίωσης βοηθά — αλλά μόνο με καλό δείγμα","Histologisch unklarer ZNS-Tumor: M…":"Ιστολογικά ασαφής όγκος CNS: m…","Neuropathologie / Neuroonkologisches Referenzboard":"Νευροπαθολογία / Νευρο-ογκολογικό board αναφοράς","47-jährige Patientin mit einem posterior-fossären Tumor. Histologie und IHC ergeben ein ungewöhnliches gliales/ependymales Mischbild; mehrere Differenzialdiagnosen bleiben plausibel.":"47χρονη γυναίκα με όγκο οπίσθιου βόθρου. Ιστολογία και IHC δείχνουν ασυνήθιστο μικτό γλοιακό/επενδυματικό πρότυπο· αρκετές διαφορικές διαγνώσεις παραμένουν εύλογες.","Kann ein DNA-Methylierungsclassifier die Diagnose klären – und wann darf ein Classifier-Ergebnis gerade nicht überinterpretiert werden?":"Μπορεί ένας classifier μεθυλίωσης DNA να διευκρινίσει τη διάγνωση — και πότε ειδικά δεν πρέπει να υπερερμηνεύεται ένα αποτέλεσμα classifier;","Die Referenzdiagnose beeinflusst Nachsorge und Therapieplanung.":"Η διάγνωση αναφοράς επηρεάζει την παρακολούθηση και τον θεραπευτικό σχεδιασμό.","Schwindel, Gangunsicherheit und okzipitale Kopfschmerzen; MRT mit gut abgrenzbarer Raumforderung im Kleinhirn.":"Ζάλη, αστάθεια βάδισης και ινιακή κεφαλαλγία· MRI δείχνει καλά περιγεγραμμένη μάζα παρεγκεφαλίδας.","Voroperation":"Προηγούμενη επέμβαση","Keine bekannte Tumorerkrankung.":"Χωρίς γνωστή νεοπλασματική νόσο.","Pathologie":"Παθολογία","Morphologie uneindeutig; IHC nicht widersprüchlich, aber nicht ausreichend spezifisch.":"Η μορφολογία είναι αμφίσημη· η IHC δεν είναι αντιφατική, αλλά δεν είναι αρκετά ειδική.","Ein Classifier-Score wird als maschinelles Wahrheitsurteil behandelt, unabhängig von Tumoranteil und Plausibilität.":"Ένα score classifier αντιμετωπίζεται ως μηχανική αλήθεια ανεξάρτητα από ποσοστό όγκου και βιολογική ευλογοφάνεια.","Piloide und stellenweise ependymale Architektur, fokale Gefäßhyalinisierung, keine eindeutige klassische Entität.":"Πιλοειδής και εστιακά επενδυματική αρχιτεκτονική, εστιακή αγγειακή υαλοποίηση, χωρίς σαφή κλασική οντότητα.","GFAP positiv; EMA nur fokal dot-like; OLIG2 heterogen; keine sichere Linie.":"GFAP θετικό· EMA μόνο εστιακά dot-like· OLIG2 ετερογενές· χωρίς ασφαλή γραμμή διαφοροποίησης.","Erste Differentialdiagnose":"Αρχική διαφορική διάγνωση","Ependymom versus astrozytärer/piloider Tumor.":"Επενδύμωμα έναντι αστροκυτταρικού/πιλοειδούς όγκου.","Genomeweites Methylierungsmuster und Copy-number-Kontext.":"Genome-wide πρότυπο μεθυλίωσης και copy-number context.","Erster FFPE-Block enthält nur ca. 15 % Tumor und viel reaktives Kleinhirngewebe; zweiter Block enthält ca. 65 % Tumor.":"Το πρώτο FFPE block περιέχει μόνο περίπου 15% όγκο και άφθονο αντιδραστικό παρεγκεφαλιδικό ιστό· το δεύτερο block περίπου 65% όγκο.","beide Blöcke technisch extrahierbar.":"Και τα δύο blocks είναι τεχνικά εξαγώγιμα.","Classifier-Risiko":"Κίνδυνος classifier","Niedriger Tumoranteil kann den Score und das Profil verwässern.":"Χαμηλό ποσοστό όγκου μπορεί να αραιώσει το score και το προφίλ.","Eine fokale Bisulfit-PCR beantwortet nicht die globale Klassifikationsfrage.":"Η εστιακή PCR διθειώδους δεν απαντά σε ερώτημα συνολικής ταξινόμησης.","Genomeweiter CNS-Methylierungsclassifier":"Genome-wide classifier μεθυλίωσης CNS","Classifier – Block mit wenig Tumor":"Classifier — block με χαμηλό ποσοστό όγκου","Erste Analyse aus dem tumorarmen Block liefert nur eine niedrig-konfidente, biologisch wenig plausible Zuordnung unterhalb des lokal validierten Freigabebereichs. Kein belastbarer Klassenruf.":"Η πρώτη ανάλυση από το low-tumor block δίνει μόνο low-confidence, βιολογικά μη πειστική ταξινόμηση κάτω από το τοπικά επικυρωμένο εύρος αναφοράς. Δεν υπάρχει αξιόπιστο class call.","Classifier – tumorangereicherter Block":"Classifier — tumor-enriched block","Nach Auswahl des tumorreichen Blocks ergibt sich eine hochkonfidente Zuordnung zur Methylierungsfamilie 'High-grade astrocytoma with piloid features' mit passendem Copy-number-Profil.":"Μετά την επιλογή του tumor-rich block προκύπτει υψηλής εμπιστοσύνης ταξινόμηση στην οικογένεια μεθυλίωσης «High-grade astrocytoma with piloid features» με συμβατό copy-number profile.","Lokale CpG-Methylierung nachweisbar, aber diagnostisch nicht ausreichend zur genomeweiten Klassifikation.":"Η τοπική μεθυλίωση CpG είναι ανιχνεύσιμη αλλά διαγνωστικά ανεπαρκής για genome-wide ταξινόμηση.","Molekulare Zusatzbefunde können die Plausibilität stützen, ersetzen aber bei diesem morphologisch schwierigen Fall den validierten Methylierungsclassifier nicht.":"Πρόσθετα μοριακά ευρήματα μπορούν να υποστηρίξουν την ευλογοφάνεια, αλλά δεν αντικαθιστούν τον επικυρωμένο classifier μεθυλίωσης σε αυτή τη μορφολογικά δύσκολη περίπτωση.","Histologisch uneindeutiger posterior-fossärer glialer Tumor.":"Ιστολογικά αμφίσημος γλοιακός όγκος οπίσθιου βόθρου.","Es stehen ein tumorarmer und ein deutlich tumorreicherer Block zur Verfügung.":"Διατίθενται ένα low-tumor block και ένα σαφώς πλουσιότερο σε όγκο block.","Der CNS-Methylierungsclassifier ist bei morphologisch unklaren Tumoren besonders wertvoll, sein Ergebnis muss aber zusammen mit Tumoranteil, QC, Score, Copy-number-Profil und Histologie bewertet werden. Der erste niedrig-konfidente Lauf aus tumorarmem Material ist nicht berichtsfähig; die Wiederholung aus tumorreichem Material liefert eine plausible hochkonfidente Klassifikation.":"Ο classifier μεθυλίωσης CNS είναι ιδιαίτερα πολύτιμος σε μορφολογικά ασαφείς όγκους, αλλά το αποτέλεσμα πρέπει να αξιολογείται μαζί με ποσοστό όγκου, QC, score, copy-number profile και ιστολογία. Το πρώτο low-confidence run από low-tumor υλικό δεν είναι reportable· η επανάληψη από tumor-rich υλικό δίνει εύλογη υψηλής εμπιστοσύνης ταξινόμηση.","Teilbefund: Ein niedrig-konfidentes Classifier-Ergebnis aus tumorarmem Material darf nicht als definitive Diagnose ausgegeben werden.":"Μερικό αποτέλεσμα: low-confidence αποτέλεσμα classifier από low-tumor υλικό δεν πρέπει να εκδίδεται ως οριστική διάγνωση.","Methylierungsclassifier gezielt bei diagnostisch schwierigem ZNS-Tumor einsetzen":"Χρησιμοποιήστε στοχευμένα τον classifier μεθυλίωσης σε διαγνωστικά δύσκολο όγκο CNS","Tumoranteil und Classifier-QC vor Klassenruf prüfen":"Ελέγξτε ποσοστό όγκου και QC του classifier πριν από class call","Classifier mit Histologie und molekularen Zusatzdaten integrieren":"Ενσωματώστε τον classifier με ιστολογία και πρόσθετα μοριακά δεδομένα","Bei unplausiblem Low-confidence-Ergebnis besseres Material wählen statt überinterpretieren":"Σε μη εύλογο low-confidence αποτέλεσμα, επιλέξτε καλύτερο υλικό αντί να το υπερερμηνεύσετε","Falschaussage: der höchste angezeigte Klassenname ist unabhängig vom Score die Diagnose":"Λανθασμένη δήλωση: η υψηλότερη εμφανιζόμενη κλάση είναι η διάγνωση ανεξάρτητα από το score","Optimale Lösung: Classifier als starken integrativen Diagnostikbaustein nutzen, aber nur aus geeignetem Material und mit validiertem Confidence-/QC-Kontext; ein Low-confidence-Ergebnis ist ein Hinweis, kein Wahrheitsurteil.":"Βέλτιστη λύση: χρησιμοποιήστε τον classifier ως ισχυρό ολοκληρωτικό διαγνωστικό στοιχείο, αλλά μόνο από κατάλληλο υλικό και σε επικυρωμένο πλαίσιο confidence/QC· ένα low-confidence αποτέλεσμα είναι ένδειξη, όχι ετυμηγορία αλήθειας.","ZNS":"CNS","Integrated diagnosis":"Ολοκληρωμένη διάγνωση","Der Classifier ist nur so gut wie Probe und Plausibilität":"Ο classifier είναι τόσο καλός όσο το δείγμα και η ευλογοφάνεια","Neuropathologie / Molekulardiagnostik / MTB":"Νευροπαθολογία / Μοριακή Διαγνωστική / MTB","Indikationen für CNS-Methylierungsclassification bei diagnostisch schwierigen Tumoren erkennen.":"Αναγνωρίστε ενδείξεις για classification μεθυλίωσης CNS σε διαγνωστικά δύσκολους όγκους.","Tumoranteil, QC und Confidence/Score vor Klassenruf prüfen.":"Ελέγξτε ποσοστό όγκου, QC και confidence/score πριν από class call.","Low-confidence-Ergebnisse nicht als definitive Diagnose ausgeben.":"Μην αναφέρετε low-confidence αποτελέσματα ως οριστική διάγνωση.","Bei unplausiblem Ergebnis besseres Material priorisieren.":"Δώστε προτεραιότητα σε καλύτερο υλικό όταν το αποτέλεσμα είναι μη εύλογο.","Classifier, Copy-number-Profil, Histologie und Molekulargenetik integrieren.":"Ενσωματώστε classifier, copy-number profile, ιστολογία και μοριακή γενετική.","Der Computer liefert einen Klassennamen – aber aus einem Block mit nur 15 % Tumor und mit einem Score unterhalb des lokal validierten Freigabebereichs. Die Versuchung ist groß, den Namen trotzdem in den Befund zu schreiben.":"Ο υπολογιστής δίνει όνομα κλάσης — αλλά από block με μόνο 15% όγκο και score κάτω από το τοπικά επικυρωμένο εύρος αναφοράς. Ο πειρασμός να γραφτεί παρ’ όλα αυτά το όνομα στη γνωμάτευση είναι μεγάλος.","47-jährige Patientin mit morphologisch uneindeutigem posterior-fossärem glialem Tumor. Zwei Blöcke unterscheiden sich massiv im Tumoranteil. Der Fall lehrt, wann Methylierungsclassification enorm hilfreich ist und wann ein scheinbares Ergebnis verworfen werden muss.":"47χρονη γυναίκα με μορφολογικά αμφίσημο γλοιακό όγκο οπίσθιου βόθρου. Δύο blocks διαφέρουν έντονα ως προς το ποσοστό όγκου. Η περίπτωση διδάσκει πότε η classification μεθυλίωσης είναι εξαιρετικά χρήσιμη και πότε ένα φαινομενικό αποτέλεσμα πρέπει να απορριφθεί.","Unklare Morphologie":"Ασαφής μορφολογία","Ependymal/piloid/glial überlappende Merkmale.":"Επικαλυπτόμενα επενδυματικά/πιλοειδή/γλοιακά χαρακτηριστικά.","Genau hier kann ein validierter classifier besonders wertvoll sein.":"Ακριβώς εδώ ένας επικυρωμένος classifier μπορεί να είναι ιδιαίτερα πολύτιμος.","Zwei Blöcke, zwei Welten":"Δύο blocks, δύο κόσμοι","15 % versus 65 % Tumoranteil.":"15% έναντι 65% ποσοστό όγκου.","Preanalytics beeinflusst auch digitale/epigenetische Klassifikatoren.":"Η προαναλυτική φάση επηρεάζει επίσης ψηφιακούς/επιγενετικούς classifiers.","Score braucht Kontext":"Το score χρειάζεται πλαίσιο","Low confidence + unplausible Morphologie.":"Low confidence + μη εύλογη μορφολογία.","Ein Output ist noch kein reportable Result.":"Ένα output δεν είναι ακόμη reportable result.","Block A":"Block A","ca. 15 % Tumor, viel normales Kleinhirngewebe":"περ. 15% όγκος, άφθονος φυσιολογικός παρεγκεφαλιδικός ιστός","Block B":"Block B","ca. 65 % Tumor":"περ. 65% όγκος","mehrere plausible ZNS-Differenzialdiagnosen":"Πολλαπλές εύλογες διαφορικές διαγνώσεις CNS","Classifier aus geeignetem tumorreichem Material priorisieren.":"Δώστε προτεραιότητα σε classifier testing από κατάλληλο tumor-rich υλικό.","Lokaler validierter Score-/QC-Rahmen ist Teil der Befundfreigabe.":"Το τοπικά επικυρωμένο πλαίσιο score/QC αποτελεί μέρος της αποδέσμευσης της γνωμάτευσης.","Fokale Bisulfit-PCR löst keine genomeweite Klassifikationsfrage.":"Η εστιακή PCR διθειώδους δεν λύνει ερώτημα genome-wide ταξινόμησης.","Wann ist der Methylierungsclassifier hier am wertvollsten?":"Πότε είναι πιο πολύτιμος εδώ ο classifier μεθυλίωσης;","Bei persistierender diagnostischer Unsicherheit trotz Histologie/IHC und ausreichendem Material.":"Όταν η διαγνωστική αβεβαιότητα επιμένει παρά ιστολογία/IHC και υπάρχει επαρκές υλικό.","Immer als Ersatz für Histologie.":"Πάντα ως υποκατάστατο της ιστολογίας.","Nur wenn eine medikamentöse Targettherapie existiert.":"Μόνο εάν υπάρχει στοχευμένη θεραπεία.","Bei Erwachsenen grundsätzlich nicht.":"Ποτέ στους ενήλικες.","Der größte Zusatznutzen entsteht bei schwierigen integrierten Diagnosen.":"Η μεγαλύτερη πρόσθετη αξία προκύπτει σε δύσκολες ολοκληρωμένες διαγνώσεις.","Wie wird ein niedrig-konfidentes Ergebnis aus 15-%-Tumorblock behandelt?":"Πώς πρέπει να αντιμετωπιστεί low-confidence αποτέλεσμα από block με 15% όγκο;","Nicht definitiv reporten; QC/Tumoranteil prüfen und besseres Material analysieren.":"Μην το αναφέρετε οριστικά· ελέγξτε QC/ποσοστό όγκου και αναλύστε καλύτερο υλικό.","Höchste Klasse trotzdem als Diagnose berichten.":"Αναφέρετε ούτως ή άλλως την υψηλότερη κλάση ως διάγνωση.","Mit HE-Diagnose mitteln.":"Υπολογίστε μέσο όρο με τη διάγνωση HE.","Score ist irrelevant.":"Το score είναι άσχετο.","Confidence und Präanalytik sind Teil der diagnostischen Aussage.":"Confidence και προαναλυτική φάση αποτελούν μέρος της διαγνωστικής δήλωσης.","Der tumorreiche Block liefert einen hochkonfidenten, morphologisch plausiblen Treffer. Was folgt?":"Το tumor-rich block δίνει υψηλής εμπιστοσύνης, μορφολογικά εύλογο αποτέλεσμα. Τι ακολουθεί;","Mit Histologie und molekularen Zusatzdaten integrieren und als starke diagnostische Evidenz nutzen.":"Ενσωματώστε το με ιστολογία και πρόσθετα μοριακά δεδομένα και χρησιμοποιήστε το ως ισχυρή διαγνωστική τεκμηρίωση.","Alle bisherigen Befunde verwerfen.":"Απορρίψτε όλα τα προηγούμενα ευρήματα.","Classifier immer ignorieren.":"Αγνοείτε πάντα τον classifier.","Erst eine fokale Bisulfit-PCR muss den Namen bestätigen.":"Πρώτα πρέπει εστιακή PCR διθειώδους να επιβεβαιώσει το όνομα.","Plausible hochkonfidente Klassifikation ist stark, aber integriert.":"Μια εύλογη υψηλής εμπιστοσύνης ταξινόμηση είναι ισχυρή, αλλά ενσωματωμένη.","Warum ist das begleitende Copy-number-Profil nützlich?":"Γιατί είναι χρήσιμο το συνοδό copy-number profile;","Es kann die Klassenplausibilität stützen und zusätzliche diagnostische Muster liefern.":"Μπορεί να υποστηρίξει την ευλογοφάνεια της κλάσης και να παρέχει πρόσθετα διαγνωστικά πρότυπα.","Es beweist Keimbahnveränderungen.":"Αποδεικνύει αλλοιώσεις βλαστικής σειράς.","Es ersetzt Histologie vollständig.":"Αντικαθιστά πλήρως την ιστολογία.","Es ist immer ein zugelassener Therapietest.":"Είναι πάντα εγκεκριμένο θεραπευτικό τεστ.","Classifier und CN-Profil ergänzen die integrierte Diagnose.":"Classifier και CN profile συμπληρώνουν την ολοκληρωμένη διάγνωση.","Entscheiden Sie, welcher Block analysiert und welches Classifier-Ergebnis reportet werden darf. Formulieren Sie die integrierte Diagnose mit klarer QC-Grenze.":"Αποφασίστε ποιο block πρέπει να αναλυθεί και ποιο αποτέλεσμα classifier μπορεί να αναφερθεί. Διατυπώστε την ολοκληρωμένη διάγνωση με σαφές όριο QC.","Morphologische Unsicherheit als legitime Classifier-Indikation erkennen.":"Αναγνωρίστε τη μορφολογική αβεβαιότητα ως θεμιτή ένδειξη για classifier.","Tumorarmen Block als Risikomaterial identifizieren.":"Αναγνωρίστε το low-tumor block ως υλικό κινδύνου.","Low-confidence-Ausgabe nicht als definitive Diagnose reporten.":"Μην αναφέρετε low-confidence output ως οριστική διάγνωση.","Tumorreichen Block analysieren.":"Αναλύστε το tumor-rich block.","Hochkonfidenten, plausiblen Classifier mit Morphologie/CN-Profil integrieren.":"Ενσωματώστε το υψηλής εμπιστοσύνης, εύλογο αποτέλεσμα classifier με μορφολογία/CN profile.","Bei fehlendem besserem Material eine rein deskriptive/NEC-artige Diagnose mit Limitation statt erzwungenem Classifier-Call.":"Εάν δεν υπάρχει καλύτερο υλικό, χρησιμοποιήστε καθαρά περιγραφική/NEC-όμοια διάγνωση με περιορισμούς αντί να εξαναγκάσετε class call.","Referenzzentrum bei persistierender Diskordanz.":"Παραπέμψτε σε κέντρο αναφοράς εάν η ασυμφωνία επιμένει.","Highest score wins":"Κερδίζει το υψηλότερο score","Confidence, QC und Plausibilität werden ignoriert.":"Confidence, QC και ευλογοφάνεια αγνοούνται.","Classifier ersetzt Histologie":"Ο classifier αντικαθιστά την ιστολογία","CNS-Diagnostik bleibt integriert.":"Η διαγνωστική CNS παραμένει ολοκληρωμένη.","Fokale Methylierung statt Methylom":"Εστιακή μεθυλίωση αντί μεθυλώματος","Lokaler Marker beantwortet eine andere Frage.":"Ένας τοπικός δείκτης απαντά σε διαφορετικό ερώτημα.","Der erste Classifier war technisch echt – diagnostisch trotzdem nicht gut genug":"Ο πρώτος classifier ήταν τεχνικά πραγματικός — αλλά διαγνωστικά ανεπαρκής","Aus dem tumorarmen Block entsteht ein Low-confidence-Match. Erst der gezielte Wechsel auf den tumorreichen Block erzeugt eine hochkonfidente, morphologisch passende Klassifikation. Das Problem war nicht 'KI vs. Mensch', sondern Präanalytik und Freigabekriterien.":"Το low-tumor block παράγει low-confidence match. Μόνο μετά από στοχευμένη μετάβαση στο tumor-rich block προκύπτει υψηλής εμπιστοσύνης ταξινόμηση που ταιριάζει μορφολογικά. Το πρόβλημα δεν ήταν «AI έναντι ανθρώπου», αλλά η προαναλυτική φάση και τα κριτήρια αποδέσμευσης.","Der Fall macht deutlich, dass auch moderne Klassifikatoren klassische Labor-QC brauchen.":"Η περίπτωση δείχνει καθαρά ότι και οι σύγχρονοι classifiers χρειάζονται κλασικό εργαστηριακό QC.","QC vor Klassenname":"QC πριν από το όνομα κλάσης","Low-confidence aus Block A verworfen; Block B liefert hochkonfidenten plausiblen Classifier-Match.":"Το low-confidence αποτέλεσμα από block A απορρίπτεται· το block B δίνει υψηλής εμπιστοσύνης, εύλογο classifier match.","Classifier als Laborverfahren behandelt, nicht als Black Box.":"Ο classifier αντιμετωπίζεται ως εργαστηριακή μέθοδος, όχι ως black box.","Richtige Klasse, falscher Weg":"Σωστή κλάση, λάθος διαδρομή","Klasse erkannt, aber der erste Low-score-Lauf wird nicht klar als nicht freigabefähig markiert.":"Η κλάση αναγνωρίζεται, αλλά το πρώτο low-score run δεν χαρακτηρίζεται καθαρά ως μη κατάλληλο για αποδέσμευση.","QA-Lernziel verfehlt.":"Παραλείφθηκε ο μαθησιακός στόχος QA.","Low score reportet":"Αναφορά low score","Erster angezeigter Klassenname wird ungeprüft zur Diagnose.":"Το πρώτο εμφανιζόμενο όνομα κλάσης υιοθετείται ως διάγνωση χωρίς έλεγχο.","Kritischer Befundfreigabefehler.":"Κρίσιμο σφάλμα αποδέσμευσης γνωμάτευσης.","Low-confidence / diskordant":"Low-confidence / ασύμφωνο","Tumoranteil, DNA-QC, Referenzklasse und Materialauswahl prüfen.":"Ελέγξτε ποσοστό όγκου, DNA QC, κλάση αναφοράς και επιλογή υλικού.","Keine Scheinsicherheit.":"Καμία ψευδής βεβαιότητα.","High-confidence + plausibel":"High confidence + εύλογο","In integrierte Diagnose übernehmen.":"Ενσωματώστε στην ολοκληρωμένη διάγνωση.","Methylom liefert echten diagnostischen Mehrwert.":"Το μεθύλωμα παρέχει πραγματική διαγνωστική προστιθέμενη αξία.","Methylierungsclassifier sind besonders bei schwierigen ZNS-Tumoren leistungsfähig.":"Οι classifiers μεθυλίωσης είναι ιδιαίτερα ισχυροί σε δύσκολους όγκους CNS.","Tumoranteil und Probenqualität beeinflussen das Ergebnis.":"Το ποσοστό όγκου και η ποιότητα δείγματος επηρεάζουν το αποτέλεσμα.","Confidence/Score ist kein kosmetischer Parameter, sondern Teil der Befundfreigabe.":"Confidence/score δεν είναι διακοσμητικό· αποτελεί μέρος της αποδέσμευσης της γνωμάτευσης.","Ein niedriger Score kann korrekt gerechnet und trotzdem diagnostisch nicht ausreichend sein.":"Ένα χαμηλό score μπορεί να υπολογιστεί σωστά και παρ’ όλα αυτά να είναι διαγνωστικά ανεπαρκές.","Moderne Klassifikation funktioniert nur integriert mit Pathologie und Molekulargenetik.":"Η σύγχρονη ταξινόμηση λειτουργεί μόνο όταν ενσωματώνεται με παθολογία και μοριακή γενετική.","Der erste Lauf aus tumorarmem Material ist trotz angezeigtem Klassennamen nicht freigabefähig. Nach Analyse des tumorreichen Blocks entsteht eine hochkonfidente, morphologisch und genomisch plausible Klassifikation. Diese wird als starker integrativer Diagnostikbaustein genutzt.":"Το πρώτο run από low-tumor υλικό δεν είναι αποδεσμεύσιμο παρά το εμφανιζόμενο όνομα κλάσης. Η ανάλυση του tumor-rich block δίνει στη συνέχεια υψηλής εμπιστοσύνης ταξινόμηση, μορφολογικά και γονιδιωματικά εύλογη. Χρησιμοποιείται ως ισχυρό ολοκληρωτικό διαγνωστικό στοιχείο.","QC/Confidence":"QC/Confidence","Materialauswahl":"Επιλογή υλικού","integrative Diagnose":"Ολοκληρωμένη διάγνωση","kein Black-box-Overcalling":"Χωρίς black-box overcalling","Welche Mindest-QC braucht ein Classifier in Ihrem Labor?":"Ποιο ελάχιστο QC απαιτεί ένας classifier στο εργαστήριό σας;","Wie berichtet man Low-confidence-Ergebnisse?":"Πώς πρέπει να αναφέρονται low-confidence αποτελέσματα;","Wann ist 'kein Klassenruf' die bessere Diagnose?":"Πότε είναι το «no class call» καλύτερη διαγνωστική επιλογή;","Low-confidence aus falschem Block":"Low confidence από λάθος block","Classifier braucht Labor-QC wie jede andere Methode":"Ένας classifier χρειάζεται εργαστηριακό QC όπως κάθε άλλη μέθοδος","Morphologische Unsicherheit → Materialwahl → Classifier-QC → integrierter Call":"Μορφολογική αβεβαιότητα → επιλογή υλικού → classifier QC → ολοκληρωμένο call","DNMT3A/TET2/ASXL1 bei Zytopenie: CHIP, CCUS oder MDS?":"DNMT3A/TET2/ASXL1 με κυτταροπενία: CHIP, CCUS ή MDS;","MDS/AML mit DNMT3A/TET2/ASXL1":"MDS/AML με DNMT3A/TET2/ASXL1","Hämatologie / Molekulares Board":"Αιματολογία / Μοριακό Board","74-jähriger Patient mit seit neun Monaten persistierender makrozytärer Anämie und milder Thrombozytopenie. Im peripheren Blut wurden DNMT3A- und TET2-Varianten gefunden.":"74χρονος άνδρας με επίμονη μακροκυτταρική αναιμία και ήπια θρομβοπενία επί εννέα μήνες. Στο περιφερικό αίμα ανιχνεύθηκαν παραλλαγές DNMT3A και TET2.","Beweisen diese Mutationen bereits ein MDS – oder handelt es sich um CHIP?":"Αποδεικνύουν ήδη αυτές οι μεταλλάξεις MDS — ή πρόκειται για CHIP;","Die Diagnose soll vor Einleitung einer krankheitsspezifischen Therapie geklärt werden.":"Η διάγνωση πρέπει να διευκρινιστεί πριν από έναρξη ειδικής θεραπείας της νόσου.","Hb 9,8 g/dl, MCV erhöht, Thrombozyten 115/nl; Leukozyten normal.":"Hb 9,8 g/dl, αυξημένο MCV, αιμοπετάλια 115/nl· λευκοκύτταρα φυσιολογικά.","Sekundäre Ursachen":"Δευτεροπαθείς αιτίες","Vitaminmangel, relevante Blutung, Niereninsuffizienz und Medikamente als Hauptursache weitgehend ausgeschlossen.":"Ανεπάρκεια βιταμινών, σημαντική αιμορραγία, νεφρική ανεπάρκεια και φάρμακα έχουν σε μεγάλο βαθμό αποκλειστεί ως κύρια αιτία.","Blut-NGS: DNMT3A p.R882H VAF 12 %, TET2 Frameshift VAF 8 %.":"NGS αίματος: DNMT3A p.R882H VAF 12%, TET2 frameshift VAF 8%.","Mutationen typischer CH-Gene werden mit einer definierten myeloischen Neoplasie gleichgesetzt.":"Μεταλλάξεις τυπικών γονιδίων CH εξισώνονται με καθορισμένη μυελοειδή νεοπλασία.","Knochenmark + Vorinformation":"Μυελός οστών + προηγούμενες πληροφορίες","Normo- bis leicht hyperzellulär; Dysplasie unterhalb diagnostischer Schwelle, Blasten 2 %.":"Νορμοκυτταρικός έως ήπια υπερκυτταρικός· δυσπλασία κάτω από το διαγνωστικό όριο, βλάστες 2%.","Kein MDS-definierender Befund.":"Κανένα εύρημα που να ορίζει MDS.","Flow":"Flow","Kein eindeutiger aberranter Blastenphänotyp.":"Χωρίς σαφή παθολογικό φαινότυπο βλαστών.","Wie werden persistierende Zytopenie und klonale Mutationen zusammengeführt?":"Πώς πρέπει να συνδυαστούν επίμονη κυτταροπενία και κλωνικές μεταλλάξεις;","Knochenmarkaspirat + Stanze sowie EDTA-Blut.":"Μυελικό αναρρόφημα + βιοψία και EDTA αίμα.","ausreichende Tiefe zur VAF-Beurteilung.":"Επαρκές βάθος για αξιολόγηση VAF.","CHIP setzt definitionsgemäß das Fehlen einer anderweitig ungeklärten Zytopenie voraus.":"Εξ ορισμού, CHIP προϋποθέτει απουσία κατά τα άλλα ανεξήγητης κυτταροπενίας.","Ein breites Pan-Cancer-Panel schafft nicht automatisch mehr diagnostische Sicherheit als eine integrierte hämatologische Bewertung.":"Ένα ευρύ pan-cancer panel δεν δημιουργεί αυτόματα μεγαλύτερη διαγνωστική βεβαιότητα από μια ολοκληρωμένη αιματολογική αξιολόγηση.","Knochenmark-/Morphologiekontext":"Πλαίσιο μυελού οστών/μορφολογίας","Klonale Hämatopoese / Myeloid-Panel":"Κλωνική αιμοποίηση / myeloid panel","Persistierende Zytopenie, aber keine ausreichende Dysplasie, keine erhöhte Blastenzahl und kein morphologisch definierendes MDS-Kriterium.":"Επίμονη κυτταροπενία, αλλά ανεπαρκής δυσπλασία, χωρίς αυξημένο αριθμό βλαστών και χωρίς μορφολογικά καθοριστικό κριτήριο MDS.","Myeloid-Panel":"Myeloid panel","DNMT3A p.R882H (VAF 12 %) und TET2 Frameshift (VAF 8 %); keine TP53-Alteration im untersuchten Panel. Klonalität ist belegt, eine MDS-Diagnose dadurch allein jedoch nicht.":"DNMT3A p.R882H (VAF 12%) και TET2 frameshift (VAF 8%)· καμία αλλοίωση TP53 στο εξεταζόμενο panel. Η κλωνικότητα τεκμηριώνεται, αλλά αυτό μόνο δεν ορίζει MDS.","Zusätzliche unspezifische Varianten erhöhen die Informationsmenge, lösen aber die diagnostische Abgrenzung nicht ohne Blutbild, Morphologie und definierende Kriterien.":"Πρόσθετες μη ειδικές παραλλαγές αυξάνουν την ποσότητα πληροφορίας, αλλά δεν λύνουν τη διαγνωστική διάκριση χωρίς γενική αίματος, μορφολογία και καθοριστικά κριτήρια.","Persistierende, anderweitig nicht erklärte Anämie und Thrombozytopenie.":"Επίμονη, κατά τα άλλα ανεξήγητη αναιμία και θρομβοπενία.","Keine ausreichenden morphologischen oder genetischen Kriterien für eine manifeste myeloische Neoplasie.":"Χωρίς επαρκή μορφολογικά ή γενετικά κριτήρια για έκδηλη μυελοειδή νεοπλασία.","Die DNMT3A- und TET2-Mutationen belegen klonale Hämatopoese, definieren aber allein kein MDS. Weil gleichzeitig persistierende ungeklärte Zytopenien bestehen, ist 'CHIP' nicht die passende Kategorie; bei fehlenden diagnostischen MDS-Kriterien passt die Konstellation zu einer klonalen Zytopenie unklarer Signifikanz (CCUS). Verlauf und erneute Abklärung bei Progression sind wichtiger als ein vorschnelles Neoplasie-Label.":"Οι μεταλλάξεις DNMT3A και TET2 τεκμηριώνουν κλωνική αιμοποίηση, αλλά δεν ορίζουν από μόνες τους MDS. Επειδή συνυπάρχουν επίμονες ανεξήγητες κυτταροπενίες, το «CHIP» δεν είναι η κατάλληλη κατηγορία· χωρίς διαγνωστικά κριτήρια MDS, η εικόνα ταιριάζει με clonal cytopenia of undetermined significance (CCUS). Η παρακολούθηση και επανεκτίμηση σε περίπτωση εξέλιξης είναι σημαντικότερες από πρόωρη ετικέτα νεοπλασίας.","Teilbefund: Mutationen in DNMT3A/TET2/ASXL1 können bei CHIP, CCUS und myeloischen Neoplasien vorkommen; die Diagnose entsteht erst aus Klinik, Blutbild, Morphologie und Genetik zusammen.":"Μερικό αποτέλεσμα: μεταλλάξεις DNMT3A/TET2/ASXL1 μπορούν να εμφανίζονται σε CHIP, CCUS και μυελοειδείς νεοπλασίες· η διάγνωση προκύπτει μόνο από ενσωμάτωση κλινικού πλαισίου, γενικής αίματος, μορφολογίας και γενετικής.","Klonale Mutation nicht mit MDS gleichsetzen":"Μην εξισώνετε κλωνική μετάλλαξη με MDS","CHIP nur ohne ungeklärte Zytopenie verwenden":"Χρησιμοποιήστε CHIP μόνο όταν δεν υπάρχει ανεξήγητη κυτταροπενία","CCUS als passende Zwischenkategorie bei Zytopenie + Klon ohne MDS-Kriterien erkennen":"Αναγνωρίστε CCUS ως κατάλληλη ενδιάμεση κατηγορία για κυτταροπενία + κλώνο χωρίς κριτήρια MDS","Verlaufskontrolle und erneute KM-Diagnostik bei Dynamik einplanen":"Σχεδιάστε παρακολούθηση και επανεκτίμηση μυελού εάν η εικόνα εξελιχθεί","Falschaussage: DNMT3A/TET2 beweisen eine hämatologische Neoplasie":"Λανθασμένη δήλωση: DNMT3A/TET2 αποδεικνύουν αιματολογική νεοπλασία","Optimale Lösung: DNMT3A/TET2 zeigen einen Klon; Zytopenie verhindert die CHIP-Bezeichnung, fehlende MDS-definierende Kriterien verhindern die MDS-Diagnose – damit ist CCUS die saubere integrierte Einordnung.":"Βέλτιστη λύση: DNMT3A/TET2 τεκμηριώνουν κλώνο· η κυτταροπενία αποκλείει την ετικέτα CHIP, ενώ η απουσία MDS-defining κριτηρίων αποκλείει διάγνωση MDS — άρα CCUS είναι η καθαρή ολοκληρωμένη ταξινόμηση.","Hämatologie":"Αιματολογία","DNMT3A":"DNMT3A","TET2":"TET2","CHIP":"CHIP","CCUS":"CCUS","MDS":"MDS","Clonal hematopoiesis":"Κλωνική αιμοποίηση","Der Klon ist echt – die Neoplasie noch nicht":"Ο κλώνος είναι πραγματικός — η νεοπλασία όχι ακόμη","Hämatopathologie / Hämatologie / MTB":"Αιματοπαθολογία / Αιματολογία / MTB","DNMT3A/TET2/ASXL1-Mutationen als häufige Klone und nicht als automatische MDS-Diagnose erkennen.":"Αναγνωρίστε μεταλλάξεις DNMT3A/TET2/ASXL1 ως συχνούς κλώνους και όχι ως αυτόματη διάγνωση MDS.","CHIP, CCUS und MDS anhand von Zytopenie und diagnostischen Kriterien trennen.":"Διακρίνετε CHIP, CCUS και MDS με βάση κυτταροπενία και διαγνωστικά κριτήρια.","VAF/Klonalität als Kontext, nicht als alleinige Entitätsdefinition verwenden.":"Χρησιμοποιήστε VAF/κλωνικότητα ως πλαίσιο, όχι ως μοναδικό ορισμό οντότητας.","Morphologie und Blutbild gegenüber 'Genetik allein' priorisieren.":"Δώστε προτεραιότητα σε μορφολογία και γενική αίματος έναντι της «γενετικής μόνο». ","Verlaufskontrolle als Teil einer ehrlichen diagnostischen Strategie verstehen.":"Κατανοήστε την παρακολούθηση ως μέρος μιας έντιμης διαγνωστικής στρατηγικής.","Zwei pathogene Mutationen stehen schwarz auf weiß im NGS-Bericht. Der Reflex lautet: 'Dann hat er MDS.' Das Knochenmark liefert aber keine ausreichenden Kriterien – und die persistierende Zytopenie macht gleichzeitig 'CHIP' falsch.":"Δύο παθογόνες μεταλλάξεις εμφανίζονται καθαρά στη γνωμάτευση NGS. Ο αυτοματισμός είναι: «Άρα έχει MDS.» Όμως ο μυελός δεν πληροί επαρκή κριτήρια — και η επίμονη κυτταροπενία κάνει ταυτόχρονα λάθος και το «CHIP». ","74-jähriger Patient mit ungeklärter makrozytärer Anämie und Thrombozytopenie. DNMT3A und TET2 sind mutiert, das Knochenmark bleibt jedoch unterhalb diagnostischer MDS-Schwellen. Gesucht ist die richtige Kategorie zwischen benignem Zufallsbefund und manifester Neoplasie.":"74χρονος άνδρας με ανεξήγητη μακροκυτταρική αναιμία και θρομβοπενία. DNMT3A και TET2 είναι μεταλλαγμένα, αλλά ο μυελός παραμένει κάτω από διαγνωστικά όρια MDS. Στόχος είναι η σωστή κατηγορία μεταξύ καλοήθους τυχαίου ευρήματος και έκδηλης νεοπλασίας.","Klonalität ist bewiesen":"Η κλωνικότητα αποδεικνύεται","DNMT3A 12 %, TET2 8 % VAF.":"DNMT3A 12%, TET2 8% VAF.","Ein Klon ist nicht automatisch eine Neoplasie.":"Ένας κλώνος δεν είναι αυτόματα νεοπλασία.","Zytopenie ist real":"Η κυτταροπενία είναι πραγματική","Persistierende Anämie + Thrombozytopenie ohne klare Sekundärursache.":"Επίμονη αναιμία + θρομβοπενία χωρίς σαφή δευτεροπαθή αιτία.","Damit passt die Definition von CHIP gerade nicht.":"Άρα η definition CHIP δεν ταιριάζει.","MDS-Kriterien fehlen":"Απουσιάζουν κριτήρια MDS","Blasten 2 %, Dysplasie unter Schwelle, keine definierende Genetik.":"Βλάστες 2%, δυσπλασία κάτω από το όριο, χωρίς καθοριστική γενετική.","CCUS ist eine sinnvolle Zwischenkategorie.":"CCUS είναι χρήσιμη ενδιάμεση κατηγορία.","Hb 9,8 g/dl; Thrombozyten 115/nl":"Hb 9,8 g/dl· αιμοπετάλια 115/nl","DNMT3A p.R882H 12 %, TET2 Frameshift 8 %":"DNMT3A p.R882H 12%, TET2 frameshift 8%","keine ausreichende Dysplasie, Blasten 2 %":"Ανεπαρκής δυσπλασία, βλάστες 2%","Knochenmarkmorphologie ist unverzichtbar.":"Η μορφολογία μυελού οστών είναι απαραίτητη.","Breites Pan-Cancer-NGS kann die Kategorie nicht ohne klinisch-hämatologischen Kontext definieren.":"Ευρύ pan-cancer NGS δεν μπορεί να ορίσει την κατηγορία χωρίς κλινικοαιματολογικό πλαίσιο.","Verlauf ist diagnostisch relevant, wenn Kriterien heute noch nicht erfüllt sind.":"Η παρακολούθηση είναι διαγνωστικά σημαντική όταν τα κριτήρια δεν πληρούνται ακόμη σήμερα.","Was beweisen DNMT3A/TET2 hier?":"Τι αποδεικνύουν εδώ DNMT3A/TET2;","Klonale Hämatopoese.":"Κλωνική αιμοποίηση.","Sicher ein MDS.":"Σίγουρα MDS.","Sicher AML.":"Σίγουρα AML.","Eine Keimbahnerkrankung.":"Διαταραχή βλαστικής σειράς.","Diese Gene überlappen stark zwischen CH, CCUS und myeloischen Neoplasien.":"Αυτά τα γονίδια επικαλύπτονται σημαντικά μεταξύ CH, CCUS και μυελοειδών νεοπλασιών.","Warum ist 'CHIP' hier unpassend?":"Γιατί είναι ακατάλληλο το «CHIP» εδώ;","Weil persistierende anderweitig ungeklärte Zytopenien bestehen.":"Επειδή υπάρχουν επίμονες κατά τα άλλα ανεξήγητες κυτταροπενίες.","Weil der Patient älter als 70 ist.":"Επειδή ο ασθενής είναι άνω των 70 ετών.","Weil zwei Mutationen vorliegen.":"Επειδή υπάρχουν δύο μεταλλάξεις.","Weil VAF über 5 % liegt.":"Επειδή το VAF είναι πάνω από 5%.","CHIP setzt gerade das Fehlen entsprechender ungeklärter Zytopenien voraus.":"Το CHIP ειδικά προϋποθέτει την απουσία αντίστοιχων ανεξήγητων κυτταροπενιών.","Welche Kategorie passt bei Zytopenie + Klon ohne MDS-definierende Kriterien am besten?":"Ποια κατηγορία ταιριάζει καλύτερα σε κυτταροπενία + κλώνο χωρίς MDS-defining κριτήρια;","CCUS.":"CCUS.","CHIP.":"CHIP.","AML.":"AML.","Normalbefund.":"Φυσιολογικό εύρημα.","CCUS beschreibt genau diese Zwischenkonstellation.":"Το CCUS περιγράφει ακριβώς αυτή την ενδιάμεση εικόνα.","Was ist die sinnvollste nächste Strategie?":"Ποια είναι η καταλληλότερη επόμενη στρατηγική;","Klinisch/hämatologisch monitoren und bei Dynamik erneut Knochenmark/Molekulargenetik bewerten.":"Παρακολουθήστε κλινικά/αιματολογικά και επανεκτιμήστε μυελό/μοριακή γενετική εάν υπάρξει εξέλιξη.","Sofort MDS-Therapie allein wegen DNMT3A/TET2.":"Ξεκινήστε άμεσα θεραπεία MDS αποκλειστικά βάσει DNMT3A/TET2.","Keine weitere Kontrolle.":"Καμία περαιτέρω παρακολούθηση.","Automatisch Keimbahntest für DNMT3A/TET2.":"Πραγματοποιήστε αυτόματα έλεγχο βλαστικής σειράς για DNMT3A/TET2.","Diagnostische Ehrlichkeit plus Verlauf ist hier angemessen.":"Διαγνωστική ειλικρίνεια και παρακολούθηση είναι κατάλληλες εδώ.","Ordnen Sie den Fall zwischen CHIP, CCUS und MDS ein und formulieren Sie, welche Information die Mutationen liefern – und welche nicht.":"Ταξινομήστε την περίπτωση μεταξύ CHIP, CCUS και MDS και διατυπώστε ποιες πληροφορίες παρέχουν οι μεταλλάξεις — και ποιες όχι.","Klonalität anerkennen.":"Αναγνωρίστε την κλωνικότητα.","Persistierende ungeklärte Zytopenie berücksichtigen.":"Λάβετε υπόψη την επίμονη ανεξήγητη κυτταροπενία.","Fehlende MDS-definierende Morphologie/Genetik benennen.":"Αναφέρετε την απουσία MDS-defining μορφολογίας/γενετικής.","CHIP ausschließen, weil Zytopenie vorhanden.":"Αποκλείστε CHIP επειδή υπάρχει κυτταροπενία.","CCUS als passendste aktuelle Kategorie formulieren.":"Διατυπώστε CCUS ως την καταλληλότερη τρέχουσα κατηγορία.","Verlaufskontrolle/erneute Diagnostik bei Progression empfehlen.":"Συστήστε παρακολούθηση/επανεκτίμηση εάν υπάρξει εξέλιξη.","Bei später neu auftretenden definierenden Kriterien Re-Klassifikation zur myeloischen Neoplasie.":"Εάν εμφανιστούν αργότερα καθοριστικά κριτήρια, επαναταξινομήστε ως μυελοειδή νεοπλασία.","Bei identifizierter sekundärer Zytopenieursache Neubewertung der CCUS-Einordnung.":"Εάν εντοπιστεί δευτεροπαθής αιτία κυτταροπενίας, επανεκτιμήστε την ταξινόμηση CCUS.","Mutation = MDS":"Μετάλλαξη = MDS","CH-Gene sind nicht krankheitsspezifisch.":"Τα γονίδια CH δεν είναι ειδικά για νόσο.","Alles CHIP":"Όλα είναι CHIP","Persistierende ungeklärte Zytopenie widerspricht CHIP.":"Η επίμονη ανεξήγητη κυτταροπενία δεν είναι συμβατή με CHIP.","Mehr Panel = mehr Diagnose":"Περισσότερο panel = περισσότερη διάγνωση","Diagnosekriterien bleiben klinisch-morphologisch integriert.":"Τα διαγνωστικά κριτήρια παραμένουν κλινικά και μορφολογικά ολοκληρωμένα.","Der richtige Befund ist die Zwischenkategorie":"Το σωστό αποτέλεσμα είναι η ενδιάμεση κατηγορία","Die Mutationen sind echt und klinisch relevant, aber weder 'Zufalls-CHIP' noch bereits diagnostisches MDS. Die Zytopenie verschiebt den Fall in CCUS – ein Ergebnis, das weniger endgültig klingt, aber fachlich präziser ist.":"Οι μεταλλάξεις είναι πραγματικές και κλινικά σημαντικές, αλλά δεν αποτελούν ούτε «τυχαίο CHIP» ούτε ακόμη διαγνωστικό MDS. Η κυτταροπενία μεταφέρει την περίπτωση σε CCUS — αποτέλεσμα που ακούγεται λιγότερο οριστικό, αλλά είναι ακριβέστερο.","Er trainiert, diagnostische Unsicherheit korrekt zu benennen statt molekulare Befunde zu overcallen.":"Εκπαιδεύει στην ορθή ονομασία της διαγνωστικής αβεβαιότητας αντί για overcalling μοριακών ευρημάτων.","CCUS sauber erkannt":"Σωστή αναγνώριση CCUS","Zytopenie + DNMT3A/TET2-Klon, aber keine MDS-definierenden Kriterien → CCUS.":"Κυτταροπενία + κλώνος DNMT3A/TET2, αλλά χωρίς MDS-defining κριτήρια → CCUS.","Klon, Klinik und Morphologie korrekt integriert.":"Κλώνος, κλινικό πλαίσιο και μορφολογία ενσωματώθηκαν σωστά.","CH erkannt, Kategorie unscharf":"Αναγνωρίστηκε CH, ασαφής κατηγορία","MDS wird vermieden, aber trotz Zytopenie 'CHIP' berichtet.":"Αποφεύγεται η διάγνωση MDS, αλλά παρά την κυτταροπενία αναφέρεται ως 'CHIP'.","Definition nicht sauber angewendet.":"Ο ορισμός δεν εφαρμόζεται σωστά.","NGS diagnostiziert MDS":"Το NGS διαγιγνώσκει MDS","DNMT3A/TET2 werden allein als MDS-Beweis verwendet.":"Τα DNMT3A/TET2 χρησιμοποιούνται μόνα τους ως απόδειξη MDS.","Molekulares Overcalling.":"Μοριακό overcalling.","Zytopenien verschlechtern sich":"Οι κυτταροπενίες επιδεινώνονται","Erneute Knochenmarkdiagnostik inklusive Morphologie/Genetik.":"Επανάληψη ελέγχου μυελού των οστών, συμπεριλαμβανομένης μορφολογίας/γενετικής.","Progression kann neue definierende Kriterien sichtbar machen.":"Η εξέλιξη μπορεί να αναδείξει νέα καθοριστικά κριτήρια.","Stabiler Verlauf":"Σταθερή πορεία","Strukturiertes Monitoring.":"Δομημένη παρακολούθηση.","Keine unnötige Neoplasietherapie.":"Χωρίς περιττή θεραπεία νεοπλασίας.","DNMT3A/TET2/ASXL1 sind häufige Gene klonaler Hämatopoese.":"Τα DNMT3A/TET2/ASXL1 είναι συχνά γονίδια στην κλωνική αιμοποίηση.","CHIP, CCUS und MDS teilen molekulare Befunde; Kontext trennt die Kategorien.":"CHIP, CCUS και MDS μοιράζονται μοριακά ευρήματα· το πλαίσιο διαχωρίζει τις κατηγορίες.","CHIP ohne ungeklärte Zytopenie, CCUS mit Zytopenie aber ohne definierende Neoplasiekriterien.":"CHIP χωρίς ανεξήγητη κυτταροπενία, CCUS με κυτταροπενία αλλά χωρίς καθοριστικά κριτήρια νεοπλασίας.","NGS erhöht Sensitivität für Klonalität, nicht automatisch Spezifität für MDS.":"Το NGS αυξάνει την ευαισθησία για κλωνικότητα, όχι αυτόματα την ειδικότητα για MDS.","Verlauf kann Teil der Diagnostik sein.":"Η παρακολούθηση της πορείας μπορεί να αποτελεί μέρος της διάγνωσης.","Die Mutationen belegen einen myeloischen Klon. Wegen persistierender ungeklärter Zytopenien ist CHIP unpassend; wegen fehlender MDS-definierender Morphologie/Genetik ist ein MDS derzeit nicht gesichert. Die präziseste Einordnung ist CCUS mit strukturierter Verlaufskontrolle.":"Οι μεταλλάξεις τεκμηριώνουν μυελοειδή κλώνο. Λόγω επίμονων ανεξήγητων κυτταροπενιών, το CHIP δεν είναι κατάλληλο· λόγω απουσίας μορφολογίας/γενετικής που ορίζει MDS, MDS δεν τεκμηριώνεται επί του παρόντος. Η ακριβέστερη ταξινόμηση είναι CCUS με δομημένη παρακολούθηση.","Mutation ≠ Neoplasie":"Μετάλλαξη ≠ νεοπλασία","CHIP vs CCUS":"CHIP vs CCUS","Morphologie integriert":"Ενσωμάτωση μορφολογίας","Monitoring":"Παρακολούθηση","Welche Mutationen erhöhen die Progressionswahrscheinlichkeit stärker?":"Ποιες μεταλλάξεις αυξάνουν περισσότερο την πιθανότητα εξέλιξης;","Wie verändert VAF die Risikoeinschätzung, ohne die Diagnose allein zu definieren?":"Πώς μεταβάλλει το VAF την εκτίμηση κινδύνου χωρίς να ορίζει από μόνο του τη διάγνωση;","Wann wiederholt man das Knochenmark?":"Πότε πρέπει να επαναληφθεί ο έλεγχος μυελού των οστών;","CCUS statt binärer CHIP/MDS-Antwort":"CCUS αντί για δυαδική απάντηση CHIP/MDS","Klonalität und Neoplasie sind nicht dasselbe":"Κλωνικότητα και νεοπλασία δεν είναι το ίδιο","Zytopenie → Klon → Morphologie → CCUS/MDS-Entscheidung":"Κυτταροπενία → κλώνος → μορφολογία → απόφαση CCUS/MDS","MSI-H-CRC mit MLH1/PMS2-Verlust: BRAF-Wildtyp ist noch kein Lynch-Syndrom":"MSI-H CRC με απώλεια MLH1/PMS2: BRAF wild type δεν σημαίνει ακόμη σύνδρομο Lynch","MLH1-Promotor-Methylierung bei MSI…":"Μεθυλίωση υποκινητή MLH1 σε MSI…","Viszeralonkologie / Humangenetik-Screening":"Ογκολογία σπλάχνων / γενετικός έλεγχος","71-jährige Patientin mit rechtsseitigem Kolonkarzinom. Universal-Screening zeigt Verlust von MLH1/PMS2 und MSI-H.":"Γυναίκα 71 ετών με καρκίνο δεξιού κόλου. Ο καθολικός έλεγχος δείχνει απώλεια MLH1/PMS2 και MSI-H.","Ist bei BRAF-Wildtyp nun automatisch von Lynch-Syndrom auszugehen – oder fehlt noch der entscheidende epigenetische Reflex?":"Το BRAF wild type σημαίνει πλέον αυτόματα σύνδρομο Lynch ή λείπει ακόμη ο καθοριστικός επιγενετικός αντανακλαστικός έλεγχος;","Der Tumorbefund soll therapeutisch und hereditär korrekt eingeordnet werden.":"Το εύρημα του όγκου πρέπει να ερμηνευθεί σωστά τόσο θεραπευτικά όσο και κληρονομικά.","Rechtsseitiges, lymphozytenreiches Adenokarzinom.":"Δεξιόπλευρο αδενοκαρκίνωμα πλούσιο σε λεμφοκύτταρα.","Familie":"Οικογενειακό ιστορικό","Keine auffällige Häufung Lynch-assoziierter Tumoren dokumentiert.":"Δεν τεκμηριώνεται αξιοσημείωτη οικογενειακή συσσώρευση όγκων που σχετίζονται με Lynch.","MLH1/PMS2-Verlust, MSI-H; BRAF V600E nicht nachweisbar.":"Απώλεια MLH1/PMS2, MSI-H· BRAF V600E δεν ανιχνεύεται.","BRAF-Wildtyp wird fälschlich als positiver Lynch-Nachweis interpretiert.":"Το BRAF wild type ερμηνεύεται λανθασμένα ως θετική απόδειξη συνδρόμου Lynch.","Mäßig differenziertes Adenokarzinom mit medullär/lymphozytenreichen Anteilen.":"Μέτρια διαφοροποιημένο αδενοκαρκίνωμα με μυελοειδείς/λεμφοκυτταροβριθείς περιοχές.","MLH1 und PMS2 verloren; MSH2/MSH6 erhalten.":"Απώλεια MLH1 και PMS2· διατήρηση MSH2/MSH6.","MSI-high bestätigt.":"Επιβεβαιωμένο MSI-high.","Somatische MLH1-Promotor-Methylierung als Ursache der MLH1-Inaktivierung.":"Σωματική μεθυλίωση του υποκινητή MLH1 ως αιτία αδρανοποίησης του MLH1.","FFPE-Resektat mit hohem Tumoranteil.":"Δείγμα εκτομής FFPE με υψηλή περιεκτικότητα σε όγκο.","Methylierung":"Μεθυλίωση","gezielter validierter MLH1-Promotor-Assay möglich.":"Είναι εφικτή μια στοχευμένη επικυρωμένη δοκιμασία υποκινητή MLH1.","Wildtyp – informativ, aber nicht beweisend für Lynch.":"Wild type — πληροφοριακό, αλλά όχι απόδειξη συνδρόμου Lynch.","Ein negatives Ausschlussmerkmal darf nicht in einen positiven hereditären Nachweis umgedeutet werden.":"Ένας αρνητικός δείκτης αποκλεισμού δεν πρέπει να μετατρέπεται σε θετική κληρονομική απόδειξη.","MLH1-Promotor-Methylierung":"Μεθυλίωση υποκινητή MLH1","Verlust von MLH1/PMS2 bei erhaltener MSH2/MSH6-Expression.":"Απώλεια MLH1/PMS2 με διατηρημένη έκφραση MSH2/MSH6.","MSI-high bestätigt; damit besteht ein therapeutisch relevanter dMMR/MSI-H-Kontext.":"Επιβεβαιωμένο MSI-high· συνεπώς υπάρχει θεραπευτικά σχετικό πλαίσιο dMMR/MSI-H.","BRAF V600E nicht nachweisbar. Das entfernt ein starkes Indiz für sporadische MLH1-Inaktivierung, beweist Lynch aber nicht.":"BRAF V600E δεν ανιχνεύεται. Αυτό αφαιρεί μια ισχυρή ένδειξη σποραδικής αδρανοποίησης MLH1, αλλά δεν αποδεικνύει σύνδρομο Lynch.","Deutliche MLH1-Promotor-Hypermethylierung. Die Konstellation spricht bei dieser 71-jährigen Patientin stark für eine sporadische epigenetische MLH1-Silenzierung; klinische/familiäre Auffälligkeiten bleiben dennoch zu berücksichtigen.":"Έντονη υπερμεθυλίωση του υποκινητή MLH1. Στη συγκεκριμένη ασθενή 71 ετών, το σύνολο των ευρημάτων υποστηρίζει ισχυρά σποραδική επιγενετική σίγαση του MLH1· ωστόσο πρέπει να συνεκτιμώνται κλινικά και οικογενειακά χαρακτηριστικά.","Kernbefund":"Κύριο εύρημα","dMMR/MSI-H durch MLH1/PMS2-Verlust.":"dMMR/MSI-H λόγω απώλειας MLH1/PMS2.","Wildtyp – kein Lynch-Beweis.":"Wild type — όχι απόδειξη συνδρόμου Lynch.","Der dMMR/MSI-H-Status ist therapeutisch relevant. Für die hereditäre Einordnung zeigt der MLH1/PMS2-Verlust zunächst nur die Richtung der Reflexdiagnostik. BRAF-Wildtyp beweist kein Lynch-Syndrom. Die nachgewiesene MLH1-Promotor-Hypermethylierung spricht stark für eine sporadische epigenetische MLH1-Inaktivierung; Alter, Familienanamnese und besondere klinische Konstellationen können dennoch eine weitergehende humangenetische Beurteilung rechtfertigen.":"Το dMMR/MSI-H status είναι θεραπευτικά σημαντικό. Για την κληρονομική ταξινόμηση, η απώλεια MLH1/PMS2 αρχικά υποδεικνύει μόνο την κατεύθυνση του reflex testing. Το BRAF wild type δεν αποδεικνύει σύνδρομο Lynch. Η ανιχνευθείσα υπερμεθυλίωση του υποκινητή MLH1 υποστηρίζει ισχυρά σποραδική επιγενετική αδρανοποίηση MLH1· ωστόσο η ηλικία, το οικογενειακό ιστορικό και ειδικές κλινικές συνθήκες μπορεί να δικαιολογούν περαιτέρω γενετική αξιολόγηση.","Teilbefund: MLH1/PMS2-Verlust + MSI-H ist nicht synonym mit Lynch; die Ursache der MLH1-Inaktivierung muss reflexdiagnostisch geklärt werden.":"Μερικό αποτέλεσμα: απώλεια MLH1/PMS2 + MSI-H δεν είναι συνώνυμο του συνδρόμου Lynch· η αιτία αδρανοποίησης MLH1 πρέπει να διευκρινιστεί με reflex testing.","dMMR/MSI-H therapeutisch korrekt einordnen":"Σωστή θεραπευτική ερμηνεία dMMR/MSI-H","BRAF-Wildtyp nicht als Lynch-Beweis interpretieren":"Μην ερμηνεύετε το BRAF wild type ως απόδειξη συνδρόμου Lynch","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex priorisieren":"Προτεραιοποιήστε τη μεθυλίωση υποκινητή MLH1 ως άμεσο επιγενετικό reflex test","Alter/Familie/klinischen Kontext trotz Methylierung berücksichtigen":"Συνεκτιμήστε ηλικία/οικογένεια/κλινικό πλαίσιο παρά τη μεθυλίωση","Falschaussage: BRAF-Wildtyp + MLH1/PMS2-Verlust = Lynch gesichert":"Λανθασμένη δήλωση: BRAF wild type + απώλεια MLH1/PMS2 = επιβεβαιωμένο σύνδρομο Lynch","Optimale Lösung: MSI-H/dMMR therapeutisch nutzen, MLH1/PMS2-Verlust hereditär reflexdiagnostisch abarbeiten und BRAF-Wildtyp nicht überinterpretieren; positive MLH1-Methylierung spricht stark für sporadische Silenzierung.":"Βέλτιστη λύση: αξιοποιήστε θεραπευτικά το MSI-H/dMMR, διερευνήστε την απώλεια MLH1/PMS2 με κατάλληλο κληρονομικό reflex testing και μην υπερερμηνεύετε το BRAF wild type· θετική μεθυλίωση MLH1 υποστηρίζει ισχυρά σποραδική σίγαση.","MLH1 methylation":"Μεθυλίωση MLH1","BRAF wild type":"BRAF wild type","BRAF-Wildtyp ist kein positiver Lynch-Test":"Το BRAF wild type δεν είναι θετικό τεστ για Lynch","Gastrointestinale Molekularpathologie / MTB / Humangenetik":"Γαστρεντερική μοριακή παθολογία / MTB / κλινική γενετική","MLH1/PMS2-Verlust als Trigger einer spezifischen Reflexdiagnostik verstehen.":"Κατανοήστε την απώλεια MLH1/PMS2 ως έναυσμα για ειδικό reflex testing.","MSI-H/dMMR therapeutische und hereditäre Ebenen trennen.":"Διαχωρίστε τη θεραπευτική και την κληρονομική διάσταση του MSI-H/dMMR.","BRAF V600E positiv als starkes sporadisches Indiz, BRAF-Wildtyp aber nicht als Lynch-Beweis verstehen.":"Κατανοήστε το θετικό BRAF V600E ως ισχυρή ένδειξη σποραδικής αιτιολογίας, αλλά όχι το BRAF wild type ως απόδειξη Lynch.","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex einordnen.":"Εντάξτε τη μεθυλίωση υποκινητή MLH1 ως άμεσο επιγενετικό reflex test.","Alter und Familienanamnese trotz scheinbar sporadischem Muster berücksichtigen.":"Συνεκτιμήστε ηλικία και οικογενειακό ιστορικό παρά το φαινομενικά σποραδικό πρότυπο.","MLH1 und PMS2 fehlen, der Tumor ist MSI-H – und BRAF ist Wildtyp. Im Board fällt sofort der Satz: 'Dann ist es Lynch.' Genau an dieser Stelle setzt der Fall an.":"MLH1 και PMS2 απουσιάζουν, ο όγκος είναι MSI-H — και το BRAF είναι wild type. Στο board ακούγεται αμέσως: «Τότε είναι Lynch.» Ακριβώς εκεί ξεκινά η περίπτωση.","71-jährige Patientin mit rechtsseitigem MSI-H-CRC und MLH1/PMS2-Verlust. BRAF V600E ist nicht nachweisbar. Die zentrale Frage ist, ob das bereits Lynch beweist oder ob die epigenetische Ursache der MLH1-Silenzierung noch direkt geprüft werden muss.":"Γυναίκα 71 ετών με δεξιόπλευρο MSI-H CRC και απώλεια MLH1/PMS2. BRAF V600E δεν ανιχνεύεται. Το κεντρικό ερώτημα είναι αν αυτό αποδεικνύει ήδη σύνδρομο Lynch ή αν πρέπει ακόμη να ελεγχθεί άμεσα η επιγενετική αιτία της σίγασης MLH1.","Therapieebene":"Θεραπευτική διάσταση","MSI-H/dMMR ist bereits ein wichtiger prädiktiver Tumorbefund.":"Το MSI-H/dMMR αποτελεί ήδη σημαντικό προγνωστικό/προβλεπτικό εύρημα όγκου.","Die Therapieaussage braucht nicht erst eine Lynch-Diagnose.":"Η θεραπευτική δήλωση δεν απαιτεί προηγούμενη διάγνωση Lynch.","MLH1/PMS2-Verlust kann sporadisch oder hereditär entstehen.":"Η απώλεια MLH1/PMS2 μπορεί να προκύψει σποραδικά ή κληρονομικά.","Reflexdiagnostik klärt die Ursache.":"Το reflex testing διευκρινίζει την αιτία.","Negativ ist nicht positiv":"Αρνητικό δεν σημαίνει θετικό","BRAF-Wildtyp entfernt ein sporadisches Indiz, beweist aber Lynch nicht.":"Το BRAF wild type αφαιρεί μια ένδειξη σποραδικής αιτιολογίας, αλλά δεν αποδεικνύει σύνδρομο Lynch.","Ausschlussmarker nicht in Bestätigungsmarker verwandeln.":"Μην μετατρέπετε έναν δείκτη αποκλεισμού σε δείκτη επιβεβαίωσης.","MLH1/PMS2 verloren":"Απώλεια MLH1/PMS2","MSI-high":"MSI-high","V600E nicht nachweisbar":"V600E δεν ανιχνεύεται","Ausreichendes Resektat für gezielte MLH1-Methylierungsanalyse.":"Επαρκές δείγμα εκτομής για στοχευμένη ανάλυση μεθυλίωσης MLH1.","Kein Grund für ein breites Panel, wenn die Reflexfrage fokussiert beantwortet werden kann.":"Δεν χρειάζεται ευρύ panel όταν το εστιασμένο reflex ερώτημα μπορεί να απαντηθεί άμεσα.","Klinischer Kontext bleibt Teil der Lynch-Risikobewertung.":"Το κλινικό πλαίσιο παραμένει μέρος της εκτίμησης κινδύνου Lynch.","Was bedeutet BRAF-Wildtyp bei MLH1/PMS2-Verlust?":"Τι σημαίνει BRAF wild type στο πλαίσιο απώλειας MLH1/PMS2;","Lynch bleibt möglich, ist aber nicht bewiesen; MLH1-Promotor-Methylierung sollte direkt geprüft werden.":"Το σύνδρομο Lynch παραμένει πιθανό αλλά δεν έχει αποδειχθεί· πρέπει να ελεγχθεί άμεσα η μεθυλίωση υποκινητή MLH1.","Lynch ist damit gesichert.":"Το σύνδρομο Lynch επιβεβαιώνεται έτσι.","Sporadisch ist damit gesichert.":"Η σποραδική αιτιολογία επιβεβαιώνεται έτσι.","BRAF hat nie Bedeutung im CRC-Lynch-Screening.":"Το BRAF δεν έχει ποτέ σημασία στον έλεγχο Lynch στο CRC.","Negatives BRAF-Ergebnis ist kein positiver Lynch-Nachweis.":"Ένα αρνητικό αποτέλεσμα BRAF δεν αποτελεί θετική απόδειξη συνδρόμου Lynch.","MLH1-Promotor-Methylierung ist deutlich positiv. Was ist die beste Interpretation?":"Η μεθυλίωση του υποκινητή MLH1 είναι σαφώς θετική. Ποια είναι η καλύτερη ερμηνεία;","Starkes Indiz für sporadische epigenetische MLH1-Silenzierung; klinische Sonderkonstellationen trotzdem beachten.":"Ισχυρή ένδειξη σποραδικής επιγενετικής σίγασης MLH1· ωστόσο πρέπει να λαμβάνονται υπόψη ειδικές κλινικές συνθήκες.","Beweist Lynch.":"Αποδεικνύει σύνδρομο Lynch.","Macht MSI-H therapeutisch irrelevant.":"Καθιστά το MSI-H θεραπευτικά άσχετο.","Ist bei CRC bedeutungslos.":"Δεν έχει σημασία στο CRC.","Tumorale MLH1-Hypermethylierung erklärt häufig sporadischen MLH1/PMS2-Verlust.":"Η υπερμεθυλίωση MLH1 στον όγκο εξηγεί συχνά σποραδική απώλεια MLH1/PMS2.","Welche Aussage trennt die Ebenen korrekt?":"Ποια δήλωση διαχωρίζει σωστά τις δύο διαστάσεις;","MSI-H/dMMR ist therapeutisch relevant; Lynch-Abklärung ist eine zusätzliche hereditäre Frage.":"Το MSI-H/dMMR είναι θεραπευτικά σημαντικό· η διερεύνηση Lynch αποτελεί πρόσθετο κληρονομικό ερώτημα.","Immuntherapie darf erst nach Keimbahnbefund diskutiert werden.":"Η ανοσοθεραπεία μπορεί να συζητηθεί μόνο μετά από αποτέλεσμα βλαστικής σειράς.","dMMR und Lynch sind Synonyme.":"dMMR και σύνδρομο Lynch είναι συνώνυμα.","Nur BRAF entscheidet beide Ebenen.":"Μόνο το BRAF καθορίζει και τις δύο διαστάσεις.","Tumorbiomarker und hereditäre Diagnose sind verwandt, aber nicht identisch.":"Ο βιοδείκτης όγκου και η κληρονομική διάγνωση σχετίζονται, αλλά δεν είναι ταυτόσημα.","Wann sollte trotz MLH1-Methylierung genauer hingesehen werden?":"Πότε πρέπει να διερευνάται περαιτέρω η περίπτωση παρά τη μεθυλίωση MLH1;","Bei ungewöhnlich jungem Alter, auffälliger Familien-/Eigenanamnese oder anderer klinischer Diskordanz.":"Σε ασυνήθιστα νεαρή ηλικία, ύποπτο ατομικό/οικογενειακό ιστορικό ή άλλη κλινική ασυμφωνία.","Nie.":"Ποτέ.","Immer vollständige Keimbahndiagnostik unabhängig vom Kontext.":"Πάντα πλήρης έλεγχος βλαστικής σειράς ανεξάρτητα από το πλαίσιο.","Nur bei PD-L1-Positivität.":"Μόνο με θετικό PD-L1.","Seltene konstitutionelle Epimutationen und klinische Sonderkonstellationen verhindern absolute Aussagen.":"Σπάνιες συνταγματικές επιμεταλλάξεις και ειδικές κλινικές συνθήκες δεν επιτρέπουν απόλυτες διατυπώσεις.","Formulieren Sie eine zweigeteilte MTB-Aussage: therapeutische Bedeutung von MSI-H/dMMR und hereditäre Einordnung des MLH1/PMS2-Verlusts nach BRAF- und MLH1-Methylierungsbefund.":"Διατυπώστε διμερή δήλωση MTB: τη θεραπευτική σημασία του MSI-H/dMMR και την κληρονομική ερμηνεία της απώλειας MLH1/PMS2 μετά τα αποτελέσματα BRAF και μεθυλίωσης MLH1.","dMMR/MSI-H therapeutisch einordnen.":"Θεραπευτική ερμηνεία dMMR/MSI-H.","MLH1/PMS2-Verlust als Reflextrigger verstehen.":"Κατανοήστε την απώλεια MLH1/PMS2 ως trigger για reflex testing.","BRAF-Wildtyp nicht als Lynch-Beweis formulieren.":"Μην αναφέρετε το BRAF wild type ως απόδειξη συνδρόμου Lynch.","MLH1-Promotor-Methylierung direkt testen.":"Ελέγξτε άμεσα τη μεθυλίωση υποκινητή MLH1.","Positive Methylierung als starkes sporadisches Indiz berichten.":"Αναφέρετε θετική μεθυλίωση ως ισχυρή ένδειξη σποραδικής σίγασης.","Klinische Sonderkonstellationen offenhalten.":"Διατηρήστε ανοιχτή την αξιολόγηση ειδικών κλινικών συνθηκών.","In Laborpfaden, die BRAF und Methylierung anders sequenzieren, ist die Kernaussage identisch: BRAF-WT allein reicht nicht für Lynch-Diagnose.":"Σε εργαστηριακές ροές που ακολουθούν διαφορετική σειρά για BRAF και μεθυλίωση, το βασικό μήνυμα είναι ίδιο: το BRAF wild type μόνο του δεν αρκεί για διάγνωση Lynch.","Bei klarer hereditärer Auffälligkeit humangenetische Vorstellung trotz Tumormethylierung erwägen.":"Σε σαφώς ύποπτα κληρονομικά χαρακτηριστικά, εξετάστε γενετική συμβουλευτική παρά τη μεθυλίωση του όγκου.","BRAF-WT = Lynch":"BRAF wild type = σύνδρομο Lynch","Negatives Ausschlussindiz ist kein positiver hereditärer Nachweis.":"Μια αρνητική ένδειξη αποκλεισμού δεν αποτελεί θετική κληρονομική απόδειξη.","dMMR = Lynch":"dMMR = σύνδρομο Lynch","Viele MLH1/PMS2-defiziente CRC sind sporadisch methyliert.":"Πολλά CRC με ανεπάρκεια MLH1/PMS2 είναι σποραδικά μεθυλιωμένα.","Methylierung löscht MSI-Therapiebedeutung":"Η μεθυλίωση καταργεί τη θεραπευτική σημασία του MSI","Therapeutische und hereditäre Ebenen werden vermischt.":"Οι θεραπευτικές και κληρονομικές διαστάσεις συγχέονται.","Der BRAF-Wildtyp führt in die falsche Sicherheit":"Το BRAF wild type δημιουργεί ψευδή βεβαιότητα","Obwohl BRAF V600E fehlt, ist der MLH1-Promotor deutlich methyliert. Das kippt die intuitive 'BRAF-WT = Lynch'-Kurzform und zeigt, warum der direkte epigenetische Reflex diagnostisch stärker ist.":"Παρότι το BRAF V600E απουσιάζει, ο υποκινητής MLH1 είναι σαφώς μεθυλιωμένος. Αυτό ανατρέπει τη διαισθητική συντόμευση «BRAF wild type = Lynch» και δείχνει γιατί το άμεσο επιγενετικό reflex test είναι διαγνωστικά ισχυρότερο.","Der Fall trainiert Negativbefunde, Reflexdiagnostik und die Trennung von Tumortherapie und Familienmedizin.":"Η περίπτωση εκπαιδεύει στην ερμηνεία αρνητικών ευρημάτων, στο reflex diagnostics και στον διαχωρισμό της θεραπείας όγκου από την οικογενειακή ιατρική.","Zwei Ebenen sauber getrennt":"Δύο διαστάσεις διαχωρισμένες καθαρά","MSI-H/dMMR therapeutisch relevant; BRAF-WT kein Lynch-Beweis; MLH1-Methylierung positiv → sporadische Silenzierung stark wahrscheinlich.":"MSI-H/dMMR θεραπευτικά σημαντικό· BRAF wild type δεν αποδεικνύει Lynch· θετική μεθυλίωση MLH1 → πολύ πιθανή σποραδική σίγαση.","Reflexdiagnostik korrekt.":"Σωστό reflex diagnostics.","Lynch offen, Methylierung vergessen":"Το Lynch παραμένει ανοιχτό, η μεθυλίωση ξεχάστηκε","BRAF-WT wird korrekt nicht überinterpretiert, aber der direkte MLH1-Reflex fehlt.":"Το BRAF wild type σωστά δεν υπερερμηνεύεται, αλλά λείπει το άμεσο reflex test MLH1.","Diagnostik unvollständig.":"Ατελής διαγνωστικός έλεγχος.","Keimbahndiagnose aus negativem Tumormarker abgeleitet.":"Διάγνωση βλαστικής σειράς συναγμένη από αρνητικό δείκτη όγκου.","Kritisches Overcalling.":"Κρίσιμο overcalling.","MLH1-Methylierung positiv":"Θετική μεθυλίωση MLH1","Sporadische MLH1-Silenzierung als wahrscheinlich berichten; Klinik/Familie abgleichen.":"Αναφέρετε ως πιθανή σποραδική σίγαση MLH1· συσχετίστε με κλινικό πλαίσιο/οικογενειακό ιστορικό.","Viele unnötige Keimbahnabklärungen können vermieden werden, ohne Sonderfälle zu ignorieren.":"Μπορούν να αποφευχθούν πολλές περιττές διερευνήσεις βλαστικής σειράς χωρίς να αγνοούνται οι εξαιρέσεις.","Humangenetische/germline Abklärung priorisieren.":"Προτεραιοποιήστε γενετική/βλαστικής σειράς διερεύνηση.","Lynch-Verdacht bleibt bestehen.":"Η υποψία συνδρόμου Lynch παραμένει.","MLH1/PMS2-Verlust ist kein automatischer Lynch-Befund.":"Η απώλεια MLH1/PMS2 δεν αποτελεί αυτόματα εύρημα Lynch.","BRAF V600E kann sporadische MLH1-Inaktivierung stützen; BRAF-Wildtyp beweist Lynch nicht.":"Το BRAF V600E μπορεί να υποστηρίζει σποραδική αδρανοποίηση MLH1· το BRAF wild type δεν αποδεικνύει σύνδρομο Lynch.","MLH1-Promotor-Methylierung ist ein direkter epigenetischer Reflex.":"Η μεθυλίωση υποκινητή MLH1 αποτελεί άμεσο επιγενετικό reflex test.","MSI-H/dMMR hat eine therapeutische Aussage unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"Το MSI-H/dMMR έχει θεραπευτική σημασία ανεξάρτητα από το αν η αιτία είναι σποραδική ή κληρονομική.","Sehr junges Alter oder auffällige Familienanamnese können trotz Tumormethylierung weitere Abklärung rechtfertigen.":"Πολύ νεαρή ηλικία ή ύποπτο οικογενειακό ιστορικό μπορεί να δικαιολογούν περαιτέρω διερεύνηση παρά τη μεθυλίωση του όγκου.","MSI-H/dMMR ist therapeutisch relevant. Für die hereditäre Einordnung ist BRAF-Wildtyp nicht beweisend; die positive MLH1-Promotor-Methylierung spricht stark für sporadische MLH1-Silenzierung. Alter und Familienanamnese bleiben als Sicherheitsnetz bestehen.":"Το MSI-H/dMMR είναι θεραπευτικά σημαντικό. Για την κληρονομική ταξινόμηση, το BRAF wild type δεν είναι αποδεικτικό· η θετική μεθυλίωση υποκινητή MLH1 υποστηρίζει ισχυρά σποραδική σίγαση MLH1. Η ηλικία και το οικογενειακό ιστορικό παραμένουν δίχτυ ασφαλείας.","BRAF-WT nicht overcallen":"Μην υπερερμηνεύετε το BRAF wild type","Therapie vs Heredität":"Θεραπεία vs κληρονομικότητα","Kontext":"Πλαίσιο","Warum ist ein negativer Marker selten ein positiver Beweis?":"Γιατί ένας αρνητικός δείκτης σπάνια αποτελεί θετική απόδειξη;","Wie unterscheiden sich BRAF- und MLH1-Methylierungsreflex?":"Πώς διαφέρουν τα reflex tests BRAF και μεθυλίωσης MLH1;","Wann kann Tumormethylierung eine hereditäre Ursache nicht vollständig ausschließen?":"Πότε η μεθυλίωση του όγκου δεν μπορεί να αποκλείσει πλήρως κληρονομική αιτία;","MLH1-Methylierung positiv trotz BRAF-WT":"Θετική μεθυλίωση MLH1 παρά το BRAF wild type","BRAF-Wildtyp ist kein Lynch-Beweis":"Το BRAF wild type δεν αποδεικνύει σύνδρομο Lynch","MMR/MSI → BRAF-Kontext → MLH1-Methylierung → hereditäre Einordnung":"MMR/MSI → πλαίσιο BRAF → μεθυλίωση MLH1 → κληρονομική ταξινόμηση","mCRC und Bevacizumab: Anti-VEGF braucht keinen VHL-Test":"mCRC και bevacizumab: το anti-VEGF δεν απαιτεί έλεγχο VHL","mCRC: Bevacizumab und VEGF-Angioge…":"mCRC: bevacizumab και αγγειογένεση VEGF…","63-jähriger Patient mit metastasiertem rechtsseitigem Kolonkarzinom, KRAS p.G12D-mutiert. Im Board wird Bevacizumab als Bestandteil der Systemtherapie diskutiert.":"Άνδρας 63 ετών με μεταστατικό καρκίνο δεξιού κόλου, KRAS p.G12D-mutated. Στο board συζητείται bevacizumab ως μέρος συστηματικής θεραπείας.","Muss vor Anti-VEGF-Therapie die VHL/HIF/VEGF-Achse des Tumors molekular getestet oder eine hohe VEGF-Expression nachgewiesen werden?":"Πριν από anti-VEGF θεραπεία πρέπει να ελεγχθεί μοριακά ο άξονας VHL/HIF/VEGF του όγκου ή να αποδειχθεί υψηλή έκφραση VEGF;","Therapieentscheidung in dieser Woche.":"Θεραπευτική απόφαση αυτή την εβδομάδα.","Rechtsseitiges mCRC mit multiplen Lebermetastasen.":"Δεξιόπλευρο mCRC με πολλαπλές ηπατικές μεταστάσεις.","KRAS p.G12D; BRAF-Wildtyp; pMMR/MSS aus Basisdiagnostik.":"KRAS p.G12D· BRAF wild type· pMMR/MSS από τον αρχικό έλεγχο.","Anti-EGFR ist wegen RAS-Mutation nicht der naheliegende Weg; eine antiangiogene Kombination wird diskutiert.":"Το anti-EGFR δεν είναι η προφανής επιλογή λόγω της μετάλλαξης RAS· συζητείται αντιαγγειογενετικός συνδυασμός.","Mechanistische Biologie wird mit einem notwendigen prädiktiven Companion Diagnostic verwechselt.":"Η μηχανιστική βιολογία συγχέεται με υποχρεωτικό προβλεπτικό companion diagnostic.","Konventionelles kolorektales Adenokarzinom mit vitalen Metastasenarealen.":"Συμβατικό κολοορθικό αδενοκαρκίνωμα με βιώσιμες μεταστατικές περιοχές.","Gefäße":"Αγγεία","Tumor zeigt erwartbare Neovaskularisation; kein spezifischer morphologischer Selektionsmarker.":"Ο όγκος εμφανίζει αναμενόμενη νεοαγγείωση· δεν υπάρχει ειδικός μορφολογικός δείκτης επιλογής.","Basisprofil":"Βασικό προφίλ","RAS-mutiert, pMMR/MSS.":"RAS-mutated, pMMR/MSS.","Welche Rolle spielt VEGF-Biologie für das Verständnis – und welche gerade nicht für die Testauswahl?":"Ποιον ρόλο παίζει η βιολογία VEGF στην κατανόηση και ποιον ακριβώς δεν παίζει στην επιλογή εξετάσεων;","FFPE-Lebermetastase, ausreichend für Zusatzanalysen.":"Ηπατική μετάσταση FFPE, επαρκής για πρόσθετες αναλύσεις.","Begrenzt; keine diagnostische Fragestellung rechtfertigt einen RCC-spezifischen VHL/HIF-Test.":"Περιορισμένο· κανένα διαγνωστικό ερώτημα δεν δικαιολογεί RCC-specific έλεγχο VHL/HIF.","Mechanismus":"Μηχανισμός","VEGF-A ist ein zentraler proangiogener Ligand; Bevacizumab neutralisiert VEGF-A.":"Το VEGF-A είναι κεντρικός προαγγειογενετικός ligand· το bevacizumab εξουδετερώνει το VEGF-A.","Ein biologisch plausibler Signalweg ist nicht automatisch ein validierter Patientenselektions-Biomarker.":"Ένα βιολογικά εύλογο pathway δεν αποτελεί αυτόματα επικυρωμένο βιοδείκτη επιλογής ασθενών.","VEGF-/Angiogenese-Kontext korrekt einordnen":"Σωστή ερμηνεία του πλαισίου VEGF/αγγειογένεσης","CRC-Basisprofil":"Βασικό προφίλ CRC","KRAS p.G12D, BRAF-Wildtyp, keine zusätzliche Alteration, die einen Anti-VEGF-spezifischen Companion-Diagnostic-Pfad definiert.":"KRAS p.G12D, BRAF wild type, χωρίς πρόσθετη αλλοίωση που να ορίζει anti-VEGF-specific companion-diagnostic pathway.","VEGF-Kontext":"Πλαίσιο VEGF","Anti-VEGF hemmt einen zentralen Angiogeneseweg; beim mCRC existiert jedoch kein etablierter routinemäßiger Tumor-VEGF- oder VHL/HIF-Test, der vor Bevacizumab positiv sein muss.":"Το anti-VEGF αναστέλλει κεντρικό pathway αγγειογένεσης· ωστόσο στο mCRC δεν υπάρχει καθιερωμένος routine έλεγχος tumor VEGF ή VHL/HIF που πρέπει να είναι θετικός πριν από bevacizumab.","Molekularer CRC-Kontext":"Μοριακό πλαίσιο CRC","KRAS-mutiert, pMMR/MSS.":"KRAS-mutated, pMMR/MSS.","Kernfrage":"Κεντρικό ερώτημα","Biologischen Wirkmechanismus von prädiktiver Testpflicht trennen.":"Διαχωρίστε τον βιολογικό μηχανισμό δράσης από την απαίτηση προβλεπτικού ελέγχου.","Bevacizumab adressiert die VEGF-A-vermittelte Angiogenese, seine klinische Anwendung beim mCRC setzt aber keinen positiven VHL/HIF-/VEGF-Tumortest voraus. Die RAS-Mutation erklärt hier den fehlenden anti-EGFR-Kontext, ist aber kein Gegenargument gegen die antiangiogene Wirklogik. Zusätzliche VHL/HIF-Testung wäre ein aus dem RCC übertragener Low-value-Copyover.":"Το bevacizumab στοχεύει την αγγειογένεση που μεσολαβείται από VEGF-A, αλλά η κλινική χρήση του στο mCRC δεν απαιτεί θετικό tumor test VHL/HIF/VEGF. Η μετάλλαξη RAS εξηγεί εδώ την απουσία anti-EGFR πλαισίου, αλλά δεν αποτελεί επιχείρημα κατά της αντιαγγειογενετικής λογικής. Πρόσθετος έλεγχος VHL/HIF θα ήταν low-value copyover από RCC.","Teilbefund: VEGF ist biologisch relevant, aber es fehlt die Trennung zwischen Wirkmechanismus und validiertem Selektionsbiomarker.":"Μερικό αποτέλεσμα: το VEGF είναι βιολογικά σημαντικό, αλλά λείπει ο διαχωρισμός μεταξύ μηχανισμού δράσης και επικυρωμένου selection biomarker.","VEGF-A/Angiogenese als Wirkmechanismus erklären":"Εξηγήστε VEGF-A/αγγειογένεση ως μηχανισμό δράσης","Keinen routinemäßigen positiven VEGF-/VHL-Test als Voraussetzung behaupten":"Μην ισχυρίζεστε ότι απαιτείται routine θετικό VEGF/VHL test","RAS-Mutation korrekt auf anti-EGFR, nicht auf Anti-VEGF beziehen":"Συσχετίστε σωστά τη μετάλλαξη RAS με anti-EGFR, όχι με anti-VEGF","RCC-spezifische VHL/HIF-Testung vermeiden":"Αποφύγετε RCC-specific έλεγχο VHL/HIF","Falschaussage: Bevacizumab nur bei molekular aktivierter VHL/HIF-Achse":"Λανθασμένη δήλωση: bevacizumab μόνο με μοριακή ενεργοποίηση του άξονα VHL/HIF","Optimale Lösung: Anti-VEGF biologisch sauber erklären, aber keinen erfundenen Companion Diagnostic verlangen; RAS-Status und VEGF-Therapieachse sind unterschiedliche Entscheidungsebenen.":"Βέλτιστη λύση: εξηγήστε σωστά τη βιολογία anti-VEGF χωρίς να επινοείτε companion diagnostic· το status RAS και ο θεραπευτικός άξονας VEGF είναι διαφορετικά επίπεδα απόφασης.","Bevacizumab":"Bevacizumab","VEGF":"VEGF","Angiogenese":"Αγγειογένεση","KRAS":"KRAS","Biomarker hierarchy":"Ιεραρχία βιοδεικτών","Anti-VEGF ist ein Wirkmechanismus, kein VHL-Companion-Diagnostic":"Το anti-VEGF είναι μηχανισμός δράσης, όχι VHL companion diagnostic","Gastroonkologie / Molekularpathologie / MTB":"Γαστρεντερική ογκολογία / μοριακή παθολογία / MTB","VEGF-Angiogenese als Wirkmechanismus von Bevacizumab erklären.":"Εξηγήστε την αγγειογένεση VEGF ως μηχανισμό δράσης του bevacizumab.","Wirkmechanismus und prädiktiven Companion Diagnostic sauber trennen.":"Διαχωρίστε σαφώς τον μηχανισμό δράσης από το προβλεπτικό companion diagnostic.","RAS-Status korrekt auf anti-EGFR und nicht auf Anti-VEGF beziehen.":"Συσχετίστε σωστά το status RAS με anti-EGFR και όχι με anti-VEGF.","Entitätsfremde VHL/HIF-Testung beim mCRC vermeiden.":"Αποφύγετε μη ενδεδειγμένο για την οντότητα έλεγχο VHL/HIF στο mCRC.","Material- und Testökonomie als Teil guter Präzisionsonkologie verstehen.":"Κατανοήστε την οικονομία υλικού και εξετάσεων ως μέρος καλής ογκολογίας ακριβείας.","Der Tumor ist KRAS-mutiert. Jemand fragt, ob man für Bevacizumab jetzt noch 'VHL/HIF/VEGF molekular bestätigen' müsse. Genau diese scheinbar logische Zusatzdiagnostik ist der Fehler.":"Ο όγκος είναι KRAS-mutated. Κάποιος ρωτά αν για bevacizumab πρέπει τώρα να «επιβεβαιωθούν μοριακά» VHL/HIF/VEGF. Ακριβώς αυτή η φαινομενικά λογική πρόσθετη εξέταση είναι το λάθος.","63-jähriger Patient mit KRAS-mutiertem, pMMR/MSS mCRC. Bevacizumab wird als Teil einer systemischen Kombination diskutiert. Die Aufgabe ist nicht, einen neuen Biomarker zu erfinden, sondern Mechanismus, RAS-Kontext und echte Testpflicht zu trennen.":"Άνδρας 63 ετών με KRAS-mutated, pMMR/MSS mCRC. Το bevacizumab συζητείται ως μέρος συστηματικού συνδυασμού. Η αποστολή δεν είναι να επινοηθεί νέος βιοδείκτης, αλλά να διαχωριστούν μηχανισμός, πλαίσιο RAS και πραγματικές απαιτήσεις ελέγχου.","RAS beantwortet eine andere Frage":"Το RAS απαντά διαφορετικό ερώτημα","KRAS p.G12D schließt einen klassischen anti-EGFR-Kontext aus.":"Το KRAS p.G12D αποκλείει κλασικό anti-EGFR πλαίσιο.","Das macht Anti-VEGF nicht biologisch unplausibel.":"Αυτό δεν καθιστά το anti-VEGF βιολογικά μη εύλογο.","VEGF ist zentral":"Το VEGF είναι κεντρικό","Tumorangiogenese benötigt proangiogene Signale.":"Η αγγειογένεση του όγκου απαιτεί προαγγειογενετικά σήματα.","Zentraler Mechanismus bedeutet nicht automatisch Companion Diagnostic.":"Κεντρικός μηχανισμός δεν σημαίνει αυτόματα companion diagnostic.","RCC-Copyover":"RCC copyover","VHL/HIF ist beim ccRCC kanonisch.":"Το VHL/HIF είναι κανονικό στο ccRCC.","Signalwege dürfen nicht blind zwischen Entitäten als Testalgorithmus übertragen werden.":"Τα pathways δεν πρέπει να μεταφέρονται τυφλά μεταξύ οντοτήτων ως αλγόριθμοι ελέγχου.","CRC-Profil":"Προφίλ CRC","KRAS p.G12D, BRAF-WT, pMMR/MSS":"KRAS p.G12D, BRAF wild type, pMMR/MSS","metastasiert, systemische Therapie geplant":"Μεταστατικό, προγραμματισμένη συστηματική θεραπεία","ausreichend, aber kein Grund für unnötige Zusatztests":"Επαρκές, αλλά χωρίς λόγο για περιττές πρόσθετες εξετάσεις","Keine validierte positive VEGF-/VHL-Testpflicht vor Bevacizumab im mCRC.":"Δεν υπάρχει επικυρωμένη απαίτηση θετικού VEGF/VHL test πριν από bevacizumab στο mCRC.","Entitätsfremde Testung verbraucht Ressourcen ohne Entscheidungsgewinn.":"Έλεγχος ακατάλληλος για την οντότητα καταναλώνει πόρους χωρίς όφελος για την απόφαση.","Mechanistische Erklärung kann ohne zusätzlichen Wet-lab-Test erfolgen.":"Η μηχανιστική εξήγηση μπορεί να δοθεί χωρίς πρόσθετο wet-lab test.","Was bedeutet KRAS p.G12D für die Anti-VEGF-Frage?":"Τι σημαίνει KRAS p.G12D για το ερώτημα anti-VEGF;","Es betrifft die anti-EGFR-Logik; es ist kein automatischer Ausschluss von Bevacizumab.":"Αφορά τη λογική anti-EGFR· δεν αποτελεί αυτόματο αποκλεισμό του bevacizumab.","Es ist eine Kontraindikation gegen Anti-VEGF.":"Αποτελεί αντένδειξη για anti-VEGF.","Es beweist besonders gutes Bevacizumab-Ansprechen.":"Αποδεικνύει ιδιαίτερα καλή ανταπόκριση στο bevacizumab.","RAS hat im CRC gar keine therapeutische Bedeutung.":"Το RAS δεν έχει καμία θεραπευτική σημασία στο CRC.","Therapieachsen müssen getrennt gehalten werden.":"Οι θεραπευτικοί άξονες πρέπει να διατηρούνται χωριστοί.","Braucht Bevacizumab einen positiven Tumor-VEGF/VHL-Test?":"Απαιτεί το bevacizumab θετικό tumor VEGF/VHL test;","Nein; der Wirkmechanismus ist biologisch VEGF-gerichtet, aber es existiert kein solcher routinemäßiger Companion-Diagnostic-Pfad.":"Όχι· ο μηχανισμός δράσης είναι βιολογικά VEGF-directed, αλλά δεν υπάρχει τέτοιο routine companion-diagnostic pathway.","Ja, VHL-Mutation ist Voraussetzung.":"Ναι, απαιτείται μετάλλαξη VHL.","Ja, hohe VEGF-IHC muss dokumentiert sein.":"Ναι, πρέπει να τεκμηριωθεί υψηλή VEGF IHC.","Ja, HIF-2α muss mutiert sein.":"Ναι, το HIF-2α πρέπει να είναι μεταλλαγμένο.","Mechanismus und Testpflicht sind nicht dasselbe.":"Ο μηχανισμός δράσης και η απαίτηση εξέτασης δεν είναι το ίδιο.","Warum ist ein VHL/HIF-Panel hier Low-value?":"Γιατί ένα panel VHL/HIF είναι low-value εδώ;","Es importiert ccRCC-Biologie in einen CRC-Therapiealgorithmus ohne validierten Selektionsnutzen.":"Μεταφέρει βιολογία ccRCC σε αλγόριθμο θεραπείας CRC χωρίς επικυρωμένο όφελος επιλογής.","Nur weil es teuer ist.":"Μόνο επειδή είναι ακριβό.","Weil CRC keine DNA enthält.":"Επειδή το CRC δεν περιέχει DNA.","Weil VEGF im CRC keine Rolle spielt.":"Επειδή το VEGF δεν παίζει ρόλο στο CRC.","Entitätsspezifische Evidenz entscheidet.":"Η ειδική για την οντότητα τεκμηρίωση καθορίζει την απάντηση.","Was ist hier Präzisionsonkologie?":"Τι είναι ογκολογία ακριβείας εδώ;","Die richtigen wenigen Informationen verwenden und unnötige Tests weglassen.":"Χρησιμοποιήστε τις λίγες σωστές πληροφορίες και παραλείψτε περιττές εξετάσεις.","Immer das breiteste Panel bestellen.":"Παραγγέλνετε πάντα το ευρύτερο panel.","Jeden bekannten Signalweg molekular bestätigen.":"Επιβεβαιώστε μοριακά κάθε γνωστό pathway.","Nur positive Biomarker zählen.":"Μόνο οι θετικοί βιοδείκτες μετρούν.","Präzision ist nicht Informationsmaximierung.":"Η ακρίβεια δεν είναι μεγιστοποίηση πληροφορίας.","Formulieren Sie die Anti-VEGF-Rationale und begründen Sie explizit, warum weder KRAS-Mutation noch fehlende VHL/HIF-Testung die Bevacizumab-Logik aufheben.":"Διατυπώστε τη λογική anti-VEGF και εξηγήστε ρητά γιατί ούτε η μετάλλαξη KRAS ούτε η απουσία ελέγχου VHL/HIF αναιρεί τη λογική του bevacizumab.","KRAS p.G12D als anti-EGFR-Resistenzkontext benennen.":"Αναγνωρίστε το KRAS p.G12D ως πλαίσιο αντοχής anti-EGFR.","VEGF-Angiogenese als Wirkmechanismus erklären.":"Εξηγήστε την αγγειογένεση VEGF ως μηχανισμό δράσης.","Keine positive VEGF-/VHL-Testpflicht erfinden.":"Μην επινοείτε απαίτηση θετικού VEGF/VHL test.","VHL/HIF-Testung als entitätsfremden Low-value-Test vermeiden.":"Αποφύγετε έλεγχο VHL/HIF ως low-value test ακατάλληλο για την οντότητα.","Therapieentscheidung im klinischen CRC-Kontext belassen.":"Διατηρήστε τη θεραπευτική απόφαση στο κλινικό πλαίσιο CRC.","Breites CRC-Panel nur, wenn andere therapeutische Fragestellungen offen sind.":"Χρησιμοποιήστε ευρύ CRC panel μόνο αν παραμένουν άλλα θεραπευτικά ερωτήματα.","VEGF-Biologie rein interpretativ erklären, ohne Zusatztest.":"Εξηγήστε ερμηνευτικά τη βιολογία VEGF χωρίς πρόσθετη εξέταση.","VHL testen, weil VEGF":"Ελέγξτε VHL επειδή VEGF","RCC-Biologie wird ohne Evidenz in CRC übertragen.":"Η βιολογία RCC μεταφέρεται στο CRC χωρίς τεκμηρίωση.","KRAS-mutiert = kein Bevacizumab":"KRAS-mutated = όχι bevacizumab","RAS und VEGF sind unterschiedliche therapeutische Achsen.":"RAS και VEGF είναι διαφορετικοί θεραπευτικοί άξονες.","Mehr Test = mehr Präzision":"Περισσότερες εξετάσεις = περισσότερη ακρίβεια","Test ohne Entscheidungsnutzen ist Low-value.":"Εξέταση χωρίς αξία για την απόφαση είναι low-value.","Der beste Test ist hier: keiner":"Η καλύτερη εξέταση εδώ είναι: καμία","Die vorhandenen Daten reichen für die Anti-VEGF-Rationale. Ein VHL/HIF-Panel würde nichts klinisch Validiertes hinzufügen. Der Twist ist, dass fachliche Tiefe nicht durch zusätzliche Diagnostik, sondern durch korrektes Weglassen entsteht.":"Τα διαθέσιμα δεδομένα αρκούν για τη λογική anti-VEGF. Ένα panel VHL/HIF δεν θα πρόσθετε τίποτα κλινικά επικυρωμένο. Το twist είναι ότι η επιστημονική βάθος δεν φαίνεται με περισσότερη διάγνωση, αλλά με τη σωστή παράλειψή της.","Er trainiert Testökonomie und verhindert pathway-driven Overdiagnostics.":"Εκπαιδεύει στην οικονομία εξετάσεων και αποτρέπει pathway-driven overdiagnostics.","Mechanismus ohne Pseudobiomarker":"Μηχανισμός χωρίς ψευδο-βιοδείκτη","KRAS-mutiertes mCRC; Anti-VEGF biologisch plausibel, kein VHL/VEGF Companion Diagnostic erforderlich.":"KRAS-mutated mCRC· anti-VEGF βιολογικά εύλογο, δεν απαιτείται VHL/VEGF companion diagnostic.","Saubere Evidenzhierarchie.":"Καθαρή ιεραρχία τεκμηρίωσης.","VEGF erklärt, RAS unscharf":"VEGF εξηγημένο, RAS ασαφές","Angiogenese korrekt, aber RAS-/anti-EGFR-Kontext wird vermischt.":"Η αγγειογένεση είναι σωστή, αλλά το πλαίσιο RAS/anti-EGFR συγχέεται.","Therapieachsen trennen.":"Διαχωρίστε τους θεραπευτικούς άξονες.","VHL-Pflicht erfunden":"Επινοημένη απαίτηση VHL","Bevacizumab wird von einem RCC-artigen VHL/HIF-Panel abhängig gemacht.":"Το bevacizumab εξαρτάται από RCC-like panel VHL/HIF.","Entitäts-Copyover.":"Entity copyover.","Weitere CRC-Targets offen":"Πρόσθετα CRC targets ακόμη ανοιχτά","Entitätsspezifische Standarddiagnostik ergänzen.":"Συμπληρώστε standard diagnostics ειδικά για την οντότητα.","Zusatztests beantworten echte Fragen.":"Οι πρόσθετες εξετάσεις απαντούν πραγματικά ερωτήματα.","Nur Anti-VEGF-Mechanismus gefragt":"Ζητείται μόνο ο μηχανισμός anti-VEGF","Interpretation statt Wet-lab-Overtesting.":"Ερμηνεία αντί για wet-lab overtesting.","Material und TAT werden geschont.":"Διατηρούνται υλικό και TAT.","Bevacizumab neutralisiert VEGF-A und adressiert Tumorangiogenese.":"Το bevacizumab εξουδετερώνει VEGF-A και στοχεύει την αγγειογένεση του όγκου.","Für mCRC ist kein positiver VHL/HIF-/Tumor-VEGF-Test als Routinevoraussetzung etabliert.":"Δεν έχει καθιερωθεί θετικό VHL/HIF/tumor-VEGF test ως routine προϋπόθεση στο mCRC.","RAS-Status entscheidet eine andere Therapieachse.":"Το status RAS καθορίζει διαφορετικό θεραπευτικό άξονα.","Mechanistische Plausibilität ist nicht gleich Companion Diagnostic.":"Η μηχανιστική ευλογοφάνεια δεν είναι το ίδιο με companion diagnostic.","Gute Präzisionsdiagnostik beinhaltet bewusstes Weglassen unnötiger Tests.":"Η καλή διάγνωση ακριβείας περιλαμβάνει τη συνειδητή παράλειψη περιττών εξετάσεων.","Die KRAS-Mutation erklärt den fehlenden anti-EGFR-Kontext, nicht eine Anti-VEGF-Kontraindikation. Bevacizumab wirkt über VEGF-A; ein positiver VHL/HIF-/VEGF-Tumortest ist dafür im mCRC nicht erforderlich. VHL/HIF-Testung wäre Low-value.":"Η μετάλλαξη KRAS εξηγεί την απουσία anti-EGFR πλαισίου, όχι αντένδειξη anti-VEGF. Το bevacizumab δρα μέσω VEGF-A· θετικό tumor test VHL/HIF/VEGF δεν απαιτείται στο mCRC. Ο έλεγχος VHL/HIF θα ήταν low-value.","Mechanismus vs Biomarker":"Μηχανισμός vs βιοδείκτης","RAS-Achse getrennt":"Διαχωρισμένος άξονας RAS","kein VHL-Copyover":"Χωρίς VHL copyover","Testökonomie":"Οικονομία εξετάσεων","Warum führen Signalwegdiagramme manchmal zu Overdiagnostics?":"Γιατί τα pathway diagrams οδηγούν μερικές φορές σε overdiagnostics;","Was unterscheidet einen Wirkmechanismus von einem Companion Diagnostic?":"Τι διακρίνει έναν μηχανισμό δράσης από companion diagnostic;","Wann ist ein nicht bestellter Test die beste Entscheidung?":"Πότε η μη παραγγελία εξέτασης είναι η καλύτερη απόφαση;","VHL/HIF wird bewusst nicht getestet":"VHL/HIF συνειδητά δεν ελέγχεται","Mechanismus ≠ Companion Diagnostic":"Μηχανισμός ≠ companion diagnostic","CRC-Profil → Therapieachse → VEGF-Rationale → kein Zusatztest":"Προφίλ CRC → θεραπευτικός άξονας → λογική VEGF → χωρίς πρόσθετη εξέταση","Klarzelliges RCC: VHL/HIF/VEGF erklärt die Biologie – wählt aber nicht allein die Therapie":"Clear-cell RCC: VHL/HIF/VEGF εξηγεί τη βιολογία — αλλά δεν επιλέγει μόνο του τη θεραπεία","Klarzelliges RCC: VHL/HIF/VEGF-Ach…":"Clear-cell RCC: άξονας VHL/HIF/VEGF…","Uroonkologie / Molekulares Tumorboard":"Ουρο-ογκολογία / Molecular Tumor Board","59-jähriger Patient mit metastasiertem klarzelligem Nierenzellkarzinom. Ein Tumorpanel weist eine inaktivierende VHL-Alteration nach.":"Άνδρας 59 ετών με μεταστατικό clear-cell νεφροκυτταρικό καρκίνωμα. Tumor panel ανιχνεύει αδρανοποιητική αλλοίωση VHL.","Wie erklärt die VHL/HIF/VEGF-Achse die ausgeprägte Vaskularisierung und die Plausibilität von VEGFR-TKI/IO-Kombinationen – und wie weit darf man den VHL-Befund therapeutisch individualisieren?":"Πώς εξηγεί ο άξονας VHL/HIF/VEGF την έντονη αγγείωση και την ευλογοφάνεια συνδυασμών VEGFR-TKI/IO — και μέχρι ποιο σημείο μπορεί το εύρημα VHL να εξατομικεύσει θεραπεία;","Erstlinienstrategie soll im interdisziplinären Board festgelegt werden.":"Η στρατηγική πρώτης γραμμής πρέπει να καθοριστεί στο διεπιστημονικό board.","Krankheit":"Νόσος","Nephrektomie vor 18 Monaten; nun pulmonale und ossäre Metastasen.":"Νεφρεκτομή πριν από 18 μήνες· τώρα πνευμονικές και οστικές μεταστάσεις.","Klarzelliges RCC, typische feine Gefäßarchitektur.":"Clear-cell RCC, τυπική λεπτή αγγειακή αρχιτεκτονική.","VHL Loss-of-function im Tumor.":"VHL loss-of-function στον όγκο.","Ein häufiger biologischer Driver wird als spezifischer prädiktiver Marker für genau eine zugelassene Kombination missverstanden.":"Ένας συχνός βιολογικός driver παρερμηνεύεται ως ειδικός προβλεπτικός δείκτης για ακριβώς έναν εγκεκριμένο συνδυασμό.","Alveolär/nestartig aufgebauter klarzelliger Tumor mit dichtem kapillärem Netzwerk.":"Clear-cell όγκος με κυψελιδώδη/nested αρχιτεκτονική και πυκνό τριχοειδικό δίκτυο.","Biologie":"Βιολογία","VHL-Verlust stabilisiert HIF-Signale und fördert u. a. VEGF-abhängige Angiogenese.":"Η απώλεια VHL σταθεροποιεί τη σηματοδότηση HIF και προάγει, μεταξύ άλλων, VEGF-dependent αγγειογένεση.","Moderne Erstlinienoptionen kombinieren häufig Immuncheckpoint- und VEGFR-gerichtete Strategien.":"Οι σύγχρονες επιλογές πρώτης γραμμής συχνά συνδυάζουν immune-checkpoint και VEGFR-directed στρατηγικές.","Biologische Plausibilität versus echte prädiktive Individualisierung.":"Βιολογική ευλογοφάνεια έναντι πραγματικής προβλεπτικής εξατομίκευσης.","Nephrektomieblock und aktuelle Metastasenbiopsie verfügbar.":"Διαθέσιμο block νεφρεκτομής και τρέχουσα βιοψία μετάστασης.","Testnutzen":"Χρησιμότητα ελέγχου","VHL/HIF-Kontext kann die Biologie illustrieren, ist aber für Standard-IO/TKI-Auswahl nicht zwingend als positiver Companion Diagnostic erforderlich.":"Το πλαίσιο VHL/HIF μπορεί να απεικονίσει τη βιολογία, αλλά θετικό companion diagnostic δεν είναι υποχρεωτικό για standard επιλογή IO/TKI.","Mehr Molekulardaten dürfen keine Scheingenauigkeit bei der Auswahl zwischen mehreren klinisch etablierten Regimen erzeugen.":"Περισσότερα μοριακά δεδομένα δεν πρέπει να δημιουργούν ψευδή ακρίβεια στην επιλογή μεταξύ πολλών κλινικά καθιερωμένων regimens.","VHL/HIF/VEGF-Biologie integrieren":"Ενσωματώστε τη βιολογία VHL/HIF/VEGF","VHL/HIF":"VHL/HIF","Inaktivierende VHL-Alteration; Befund passt zur kanonischen ccRCC-Biologie mit HIF-Stabilisierung und proangiogenem Programm.":"Αδρανοποιητική αλλοίωση VHL· το εύρημα ταιριάζει με την κανονική βιολογία ccRCC με σταθεροποίηση HIF και προαγγειογενετικό πρόγραμμα.","Die ausgeprägte Angiogenese erklärt die Wirksamkeitslogik VEGFR-gerichteter TKIs; die Kombination mit IO adressiert gleichzeitig Tumorimmunität und Gefäß-/TME-Biologie.":"Η έντονη αγγειογένεση εξηγεί τη λογική VEGFR-directed TKI· ο συνδυασμός με IO στοχεύει ταυτόχρονα την ανοσία του όγκου και τη βιολογία αγγείων/TME.","Klarzelliges RCC mit prominentem kapillärem Netzwerk.":"Clear-cell RCC με έντονο τριχοειδικό δίκτυο.","Kernbotschaft":"Κεντρικό μήνυμα","Biologischer Driver ≠ alleiniger prädiktiver Regimenselektor.":"Βιολογικός driver ≠ μοναδικός προβλεπτικός selector regimen.","Der VHL-Verlust liefert eine sehr plausible biologische Erklärung für HIF-Aktivierung und VEGF-dominierte Angiogenese des klarzelligen RCC. Daraus folgt die biologische Plausibilität VEGFR-gerichteter Therapie und kombinierter IO/VEGFR-Strategien. Der konkrete VHL-Tumorbefund ist jedoch kein alleiniger validierter Selektionsmarker, der eine bestimmte Erstlinienkombination gegenüber allen anderen festlegt.":"Η απώλεια VHL προσφέρει πολύ εύλογη βιολογική εξήγηση για ενεργοποίηση HIF και VEGF-dominant αγγειογένεση στο clear-cell RCC. Αυτό υποστηρίζει τη βιολογική ευλογοφάνεια VEGFR-directed θεραπείας και συνδυασμένων στρατηγικών IO/VEGFR. Ωστόσο, το συγκεκριμένο tumor VHL finding δεν είναι μοναδικός επικυρωμένος selection marker που καθορίζει μία first-line combination έναντι όλων των άλλων.","Teilbefund: VHL/HIF/VEGF erklärt die Erkrankungsbiologie, beantwortet aber die klinische Regimenwahl nicht ohne Gesamtpatientenkontext.":"Μερικό αποτέλεσμα: VHL/HIF/VEGF εξηγεί τη βιολογία της νόσου αλλά δεν απαντά στην επιλογή regimen χωρίς το συνολικό κλινικό πλαίσιο.","VHL-Verlust biologisch korrekt über HIF/VEGF erklären":"Εξηγήστε βιολογικά την απώλεια VHL μέσω HIF/VEGF","Rationale von VEGFR-TKI + IO mechanistisch erläutern":"Εξηγήστε μηχανιστικά τη λογική VEGFR-TKI + IO","VHL nicht als alleinigen prädiktiven Regimenselektor verkaufen":"Μην παρουσιάζετε το VHL ως μοναδικό προβλεπτικό selector regimen","Risikogruppe, Komorbiditäten und klinische Faktoren in der Therapieentscheidung belassen":"Διατηρήστε risk group, συννοσηρότητες και κλινικούς παράγοντες στη θεραπευτική απόφαση","Falschaussage: VHL-Mutation bestimmt zwingend eine bestimmte IO/TKI-Kombination":"Λανθασμένη δήλωση: η μετάλλαξη VHL επιβάλλει συγκεκριμένο συνδυασμό IO/TKI","Optimale Lösung: VHL/HIF/VEGF als Lehrbuchbeispiel einer biologisch sehr starken Achse nutzen, ohne daraus einen nicht validierten Präzisionsmarker für die konkrete Regimenwahl zu machen.":"Βέλτιστη λύση: χρησιμοποιήστε VHL/HIF/VEGF ως κλασικό παράδειγμα βιολογικά ισχυρού άξονα χωρίς να το μετατρέψετε σε μη επικυρωμένο precision marker για την επιλογή συγκεκριμένου regimen.","ccRCC":"ccRCC","VHL":"VHL","HIF":"HIF","VEGFR-TKI":"VEGFR-TKI","VHL erklärt fast alles – aber nicht die konkrete Regimenwahl":"Το VHL εξηγεί σχεδόν τα πάντα — αλλά όχι τη συγκεκριμένη επιλογή regimen","Uroonkologie / Molekularpathologie / MTB":"Ουρο-ογκολογία / μοριακή παθολογία / MTB","VHL-Verlust über HIF-Stabilisierung und VEGF-Angiogenese erklären.":"Εξηγήστε την απώλεια VHL μέσω σταθεροποίησης HIF και αγγειογένεσης VEGF.","Die starke Vaskularisierung des ccRCC biologisch mit VEGFR-TKI verknüpfen.":"Συνδέστε βιολογικά την έντονη αγγείωση του ccRCC με VEGFR-TKI.","Komplementäre Rationale von IO + VEGFR-TKI verstehen.":"Κατανοήστε τη συμπληρωματική λογική IO + VEGFR-TKI.","VHL als häufigen biologischen Driver, aber nicht als alleinigen Regimenselektor einordnen.":"Εντάξτε το VHL ως συχνό βιολογικό driver, αλλά όχι ως μοναδικό selector regimen.","Klinische Faktoren neben Tumorbiologie in der Therapiewahl belassen.":"Διατηρήστε τους κλινικούς παράγοντες μαζί με τη βιολογία του όγκου στην επιλογή θεραπείας.","Das Panel zeigt eine klare VHL-Loss-of-function-Mutation. Der Befund ist biologisch wunderschön – so schön, dass man leicht zu viel daraus ableitet und glaubt, er müsse nun exakt eine bestimmte Kombination bestimmen.":"Το panel δείχνει σαφή μετάλλαξη VHL loss-of-function. Το εύρημα είναι βιολογικά εξαιρετικά καθαρό — τόσο ώστε εύκολα να συναχθεί υπερβολικά ότι πρέπει πλέον να καθορίζει ακριβώς έναν συνδυασμό.","59-jähriger Patient mit metastasiertem klarzelligem RCC und VHL-Loss-of-function. Ziel ist, VHL/HIF/VEGF als Lehrbuchachse zu verstehen und gleichzeitig die Grenze zur klinischen Prädiktion zu ziehen.":"Άνδρας 59 ετών με μεταστατικό clear-cell RCC και VHL loss-of-function. Στόχος είναι η κατανόηση VHL/HIF/VEGF ως κλασικού άξονα και ταυτόχρονα η χάραξη του ορίου προς την κλινική πρόβλεψη.","Kanonische Biologie":"Κανονική βιολογία","VHL-Verlust → HIF-Stabilisierung → proangiogenes Programm.":"Απώλεια VHL → σταθεροποίηση HIF → προαγγειογενετικό πρόγραμμα.","ccRCC ist ein Paradebeispiel für pathway-driven Tumorbiologie.":"Το ccRCC είναι χαρακτηριστικό παράδειγμα pathway-driven βιολογίας όγκου.","Therapie-Rationale":"Θεραπευτική λογική","VEGFR-TKI adressieren die angiogene Achse; IO adressiert Tumorimmunität/TME.":"Τα VEGFR-TKI στοχεύουν τον αγγειογενετικό άξονα· το IO στοχεύει την ανοσία του όγκου/TME.","Kombinationen können biologisch komplementär sein.":"Οι συνδυασμοί μπορούν να είναι βιολογικά συμπληρωματικοί.","Grenze":"Όριο","VHL ist häufig, aber kein alleiniger Selektor zwischen allen Standardregimen.":"Το VHL είναι συχνό, αλλά όχι ο μοναδικός selector μεταξύ όλων των standard regimens.","Biologische Erklärung ist stärker als prädiktive Spezifität.":"Η βιολογική εξήγηση είναι ισχυρότερη από την προβλεπτική ειδικότητα.","typisches klarzelliges RCC mit feinem Kapillarnetz":"Τυπικό clear-cell RCC με λεπτό τριχοειδικό δίκτυο","Tumor-NGS":"Tumor NGS","VHL Loss-of-function":"VHL loss-of-function","metastasiert, Erstlinie offen":"Μεταστατικό, ανοιχτή επιλογή πρώτης γραμμής","Kein zusätzlicher Test muss eine bestimmte IO/TKI-Kombination 'freigeben'.":"Καμία πρόσθετη εξέταση δεν χρειάζεται να «εγκρίνει» συγκεκριμένο συνδυασμό IO/TKI.","VHL-Tumorbefund ist nicht automatisch hereditär; Keimbahnfrage nur bei passendem klinischem Kontext.":"Ένα tumor VHL finding δεν είναι αυτόματα κληρονομικό· germline ερώτημα τίθεται μόνο σε κατάλληλο κλινικό πλαίσιο.","Klinische Risikogruppe, Komorbiditäten und Nebenwirkungsprofile bleiben entscheidend.":"Η κλινική ομάδα κινδύνου, οι συννοσηρότητες και τα προφίλ τοξικότητας παραμένουν καθοριστικά.","Welche Kette beschreibt die ccRCC-Biologie am besten?":"Ποια αλυσίδα περιγράφει καλύτερα τη βιολογία του ccRCC;","VHL-Verlust → HIF-Stabilisierung → VEGF/proangiogene Programme.":"Απώλεια VHL → σταθεροποίηση HIF → VEGF/προαγγειογενετικά προγράμματα.","KRAS → EGFR → MSI.":"KRAS → EGFR → MSI.","BRCA → HRD → VEGF.":"BRCA → HRD → VEGF.","MMR-Verlust → VHL.":"Απώλεια MMR → VHL.","Die VHL/HIF/VEGF-Achse ist kanonisch.":"Ο άξονας VHL/HIF/VEGF είναι κανονικός.","Warum ist IO + VEGFR-TKI biologisch plausibel?":"Γιατί το IO + VEGFR-TKI είναι βιολογικά εύλογο;","Gefäß-/TME- und Immunachsen werden komplementär adressiert.":"Οι αγγειακοί/TME και ανοσολογικοί άξονες στοχεύονται συμπληρωματικά.","Weil nur VHL-mutierte Tumoren IO vertragen.":"Επειδή μόνο οι VHL-mutated όγκοι ανέχονται IO.","Beide Medikamente blockieren exakt dasselbe Molekül.":"Και τα δύο φάρμακα μπλοκάρουν ακριβώς το ίδιο μόριο.","Weil PD-L1 immer hoch sein muss.":"Επειδή το PD-L1 πρέπει πάντα να είναι υψηλό.","Die Kombination adressiert unterschiedliche, interagierende Ebenen.":"Ο συνδυασμός στοχεύει διαφορετικά, αλληλεπιδρώντα επίπεδα.","Was darf aus VHL Loss-of-function NICHT abgeleitet werden?":"Τι ΔΕΝ πρέπει να συναχθεί από VHL loss-of-function;","Dass genau eine bestimmte Erstlinienkombination zwingend die einzig richtige ist.":"Ότι ακριβώς ένας συγκεκριμένος συνδυασμός πρώτης γραμμής είναι υποχρεωτικά η μόνη σωστή επιλογή.","Dass HIF/VEGF-Biologie plausibel ist.":"Ότι η βιολογία HIF/VEGF είναι εύλογη.","Dass angiogene Programme typisch sein können.":"Ότι αγγειογενετικά προγράμματα μπορεί να είναι τυπικά.","Dass der Befund zur ccRCC-Biologie passt.":"Ότι το εύρημα ταιριάζει στη βιολογία ccRCC.","VHL ist biologisch stark, aber nicht so prädiktiv spezifisch.":"Το VHL είναι βιολογικά ισχυρό, αλλά όχι τόσο προβλεπτικά ειδικό.","Wann wird aus Tumor-VHL eine Keimbahnfrage?":"Πότε ένα tumor VHL finding γίνεται germline ερώτημα;","Bei passendem Alter, multifokaler/bilateraler Erkrankung oder VHL-Syndrom-typischem klinischem Kontext – nicht automatisch bei jedem somatischen Tumorbefund.":"Με κατάλληλη ηλικία, πολυεστιακή/αμφοτερόπλευρη νόσο ή κλινικό πλαίσιο τυπικό συνδρόμου VHL — όχι αυτόματα για κάθε σωματικό tumor finding.","Immer.":"Πάντα.","Nur wenn TKI versagt.":"Μόνο αν αποτύχει το TKI.","Tumor- und Keimbahnebene müssen getrennt werden.":"Τα επίπεδα όγκου και βλαστικής σειράς πρέπει να διαχωρίζονται.","Erklären Sie im MTB VHL/HIF/VEGF und die Kombination von antiangiogener und immunologischer Therapie, ohne den VHL-Befund zu einem nicht validierten Ein-Patient-ein-Regime-Marker zu machen.":"Εξηγήστε στο MTB το VHL/HIF/VEGF και τον συνδυασμό αντιαγγειογενετικής και ανοσολογικής θεραπείας χωρίς να μετατρέψετε το VHL finding σε μη επικυρωμένο one-patient-one-regimen marker.","VHL-Verlust biologisch erklären.":"Εξηγήστε βιολογικά την απώλεια VHL.","HIF/VEGF-Angiogenese ableiten.":"Συνάγετε αγγειογένεση HIF/VEGF.","VEGFR-TKI-Rationale erläutern.":"Εξηγήστε τη λογική VEGFR-TKI.","IO-Komponente als komplementäre Immun-/TME-Achse erklären.":"Εξηγήστε το IO component ως συμπληρωματικό ανοσολογικό/TME άξονα.","VHL nicht als alleinigen Regimenselektor überinterpretieren.":"Μην υπερερμηνεύετε το VHL ως μοναδικό selector regimen.","Keimbahnfrage nur bei klinischem Anlass öffnen.":"Ανοίξτε germline ερώτημα μόνο με κλινική ένδειξη.","Auf VHL-Testung verzichten, wenn Histologie und klinische Therapiefrage bereits klar sind; der Fall nutzt sie als didaktischen Biologieanker.":"Παραλείψτε έλεγχο VHL όταν η ιστολογία και το κλινικό θεραπευτικό ερώτημα είναι ήδη σαφή· η περίπτωση το χρησιμοποιεί ως διδακτική βιολογική άγκυρα.","Breiteres Panel nur bei zusätzlicher Target-/Studienfrage.":"Χρησιμοποιήστε ευρύτερο panel μόνο για πρόσθετο ερώτημα target/study.","VHL = bestimmtes Regime":"VHL = συγκεκριμένο regimen","Biologischer Driver besitzt nicht diese prädiktive Spezifität.":"Ο βιολογικός driver δεν διαθέτει αυτή την προβλεπτική ειδικότητα.","Tumor-VHL = VHL-Syndrom":"Tumor VHL = σύνδρομο VHL","Somatisch und Keimbahn werden verwechselt.":"Σωματικό και germline συγχέονται.","VEGF-TKI und IO tun dasselbe":"VEGF-TKI και IO κάνουν το ίδιο","Komplementäre Mechanismen werden verkannt.":"Παραβλέπονται συμπληρωματικοί μηχανισμοί.","Der stärkste biologische Befund ist nicht der stärkste Selektionsmarker":"Το ισχυρότερο βιολογικό εύρημα δεν είναι ο ισχυρότερος δείκτης επιλογής","VHL Loss-of-function passt perfekt zum Tumor und erklärt die Angiogenese. Trotzdem wählt er nicht allein zwischen den klinisch etablierten Erstlinienoptionen. Der Fall kippt von 'Pathway gefunden' zu 'Evidenzgrad verstanden'.":"Το VHL loss-of-function ταιριάζει απόλυτα στον όγκο και εξηγεί την αγγειογένεση. Ωστόσο δεν επιλέγει μόνο του μεταξύ των κλινικά καθιερωμένων επιλογών πρώτης γραμμής. Η περίπτωση μετακινείται από το «βρέθηκε pathway» στο «κατανοήθηκε το επίπεδο τεκμηρίωσης». ","Präzisionsonkologie braucht Grenzen selbst bei sehr überzeugender Biologie.":"Η ογκολογία ακριβείας χρειάζεται όρια ακόμη και με πολύ πειστική βιολογία.","Biologie stark, Prädiktion begrenzt":"Ισχυρή βιολογία, περιορισμένη πρόβλεψη","VHL/HIF/VEGF korrekt erklärt; IO/TKI plausibel; konkrete Regimenwahl klinisch, nicht allein VHL-basiert.":"VHL/HIF/VEGF εξηγείται σωστά· IO/TKI εύλογο· η συγκεκριμένη επιλογή regimen είναι κλινική, όχι μόνο VHL-based.","Sehr gute Hierarchie.":"Πολύ καλή ιεραρχία.","Achse verstanden, Regime überpräzisiert":"Ο άξονας κατανοήθηκε, το regimen υπερ-εξειδικεύτηκε","VHL korrekt, aber eine Kombination wird molekular zwingend gemacht.":"Το VHL είναι σωστό, αλλά ένας συνδυασμός καθίσταται μοριακά υποχρεωτικός.","Biologie überinterpretiert.":"Υπερερμηνεία βιολογίας.","VHL ignoriert oder germline gesetzt":"VHL αγνοείται ή αποδίδεται στη βλαστική σειρά","Entweder zentrale Biologie verpasst oder somatischen Befund automatisch hereditär erklärt.":"Είτε χάνεται η κεντρική βιολογία είτε το σωματικό εύρημα δηλώνεται αυτόματα κληρονομικό.","Integration misslungen.":"Αποτυχία ενσωμάτωσης.","VHL-Syndrom-verdächtige Klinik":"Κλινική υποψία συνδρόμου VHL","Humangenetische Abklärung separat initiieren.":"Ξεκινήστε ξεχωριστή γενετική διερεύνηση.","Hereditäre Ebene korrekt adressiert.":"Η κληρονομική διάσταση αντιμετωπίζεται σωστά.","Standard metastasiertes ccRCC":"Τυπικό μεταστατικό ccRCC","Regimenwahl anhand aktueller klinischer Kriterien/Guidelines.":"Επιλογή regimen σύμφωνα με τρέχοντα κλινικά κριτήρια/guidelines.","Molekularbiologie informiert, ersetzt aber nicht die klinische Auswahl.":"Η μοριακή βιολογία ενημερώνει, αλλά δεν αντικαθιστά την κλινική επιλογή.","VHL/HIF/VEGF ist eine kanonische ccRCC-Achse.":"Το VHL/HIF/VEGF είναι κανονικός άξονας ccRCC.","VEGFR-TKI haben eine starke biologische Rationale im hochangiogenen ccRCC.":"Τα VEGFR-TKI έχουν ισχυρή βιολογική λογική στο έντονα αγγειογενετικό ccRCC.","IO/VEGFR-Kombinationen adressieren komplementäre Ebenen.":"Οι συνδυασμοί IO/VEGFR στοχεύουν συμπληρωματικά επίπεδα.","VHL ist kein alleiniger validierter Selektor für ein bestimmtes Standardregime.":"Το VHL δεν είναι μοναδικός επικυρωμένος selector για συγκεκριμένο standard regimen.","Somatischer VHL-Befund ist nicht automatisch VHL-Syndrom.":"Ένα σωματικό VHL finding δεν σημαίνει αυτόματα σύνδρομο VHL.","VHL Loss-of-function erklärt HIF-Stabilisierung und VEGF-dominierte Angiogenese des ccRCC. Diese Biologie macht VEGFR-gerichtete und kombinierte IO/VEGFR-Strategien plausibel, bestimmt aber nicht allein das konkrete Regime. Klinischer Gesamtkontext bleibt entscheidend.":"Το VHL loss-of-function εξηγεί τη σταθεροποίηση HIF και τη VEGF-dominant αγγειογένεση στο ccRCC. Αυτή η βιολογία καθιστά εύλογες VEGFR-directed και συνδυασμένες IO/VEGFR στρατηγικές, αλλά δεν καθορίζει μόνη της το συγκεκριμένο regimen. Το συνολικό κλινικό πλαίσιο παραμένει καθοριστικό.","VHL/HIF/VEGF":"VHL/HIF/VEGF","Kombinationsrationale":"Λογική συνδυασμού","prädiktive Grenze":"Προβλεπτικό όριο","somatisch vs germline":"Σωματικό vs germline","Warum sind manche Driver diagnostisch stark, aber prädiktiv schwach?":"Γιατί κάποιοι drivers είναι διαγνωστικά ισχυροί αλλά προβλεπτικά ασθενείς;","Welche TME-Effekte können VEGF-Inhibition immunologisch haben?":"Ποιες ανοσολογικές επιδράσεις στο TME μπορεί να έχει η αναστολή VEGF;","Wann wird eine Tumor-VHL-Variante humangenetisch relevant?":"Πότε μια tumor VHL variant γίνεται σχετική για κλινική γενετική;","VHL erklärt Biologie, aber nicht allein das Regime":"Το VHL εξηγεί τη βιολογία, αλλά όχι μόνο του το regimen","Pathway-Stärke ≠ Selektionsspezifität":"Ισχύς pathway ≠ ειδικότητα επιλογής","VHL → HIF/VEGF → TKI/IO-Rationale → klinische Regimenwahl":"VHL → HIF/VEGF → λογική TKI/IO → κλινική επιλογή regimen","Rezidiv-Glioblastom unter Bevacizumab: Wenn das MRT besser aussieht als der Tumor":"Υποτροπιάζον γλοιοβλάστωμα υπό bevacizumab: όταν η MRI φαίνεται καλύτερη από τον όγκο","Glioblastom mit Gefäßproliferation…":"Γλοιοβλάστωμα με αγγειακή πολλαπλασιασμό…","Neuroonkologie / Neuro-Radiologie / MTB":"Νευρο-ογκολογία / Νευρο-ακτινολογία / MTB","62-jähriger Patient mit rezidiviertem IDH-Wildtyp-Glioblastom, ausgeprägtem perifokalem Ödem und steroidabhängigen neurologischen Symptomen. Bevacizumab wird zur Krankheits- und Symptomkontrolle diskutiert.":"Άνδρας 62 ετών με υποτροπιάζον IDH-wild-type γλοιοβλάστωμα, έντονο περιεστιακό οίδημα και steroid-dependent νευρολογικά συμπτώματα. Το bevacizumab συζητείται για έλεγχο νόσου και συμπτωμάτων.","Was kann Anti-VEGF kurzfristig bewirken – und warum darf eine dramatische Abnahme der Kontrastmittelaufnahme nicht automatisch als proportionale Tumorzellreduktion gelesen werden?":"Τι μπορεί να επιτύχει βραχυπρόθεσμα το anti-VEGF — και γιατί μια δραματική μείωση της πρόσληψης σκιαγραφικού δεν πρέπει να ερμηνεύεται αυτόματα ως ανάλογη μείωση καρκινικών κυττάρων;","Hoher Symptomdruck durch Ödem.":"Υψηλό φορτίο συμπτωμάτων λόγω οιδήματος.","Operation, Radiochemotherapie und Temozolomid; jetzt erstes relevantes Rezidiv.":"Χειρουργείο, ακτινοχημειοθεραπεία και temozolomide· τώρα πρώτη κλινικά σημαντική υποτροπή.","Hemiparese und Kopfschmerzen, Dexamethasonbedarf steigend.":"Ημιπάρεση και κεφαλαλγίες, αυξανόμενη ανάγκη dexamethasone.","MRT":"MRI","Stark kontrastmittelaufnehmendes Rezidiv mit ausgeprägtem vasogenem Ödem.":"Υποτροπή με έντονη πρόσληψη σκιαγραφικού και σημαντικό αγγειογενές οίδημα.","Radiologische Kontrastmittelreduktion nach Anti-VEGF wird mit echter Zytoreduktion gleichgesetzt.":"Η ακτινολογική μείωση της πρόσληψης σκιαγραφικού μετά από anti-VEGF εξισώνεται με πραγματική κυτταρομείωση.","Glioblastomtypische Nekrosen und mikrovaskuläre Proliferation.":"Τυπικές για γλοιοβλάστωμα νεκρώσεις και μικροαγγειακή πολλαπλασιασμός.","Hypoxie und proangiogene Signale prägen den Tumor.":"Η υποξία και τα προαγγειογενετικά σήματα διαμορφώνουν τον όγκο.","Anti-VEGF-Effekt":"Επίδραση anti-VEGF","Gefäßpermeabilität und Ödem können rasch abnehmen.":"Η αγγειακή διαπερατότητα και το οίδημα μπορούν να μειωθούν γρήγορα.","Wie wird die Bildgebung nach Therapiebeginn korrekt interpretiert?":"Πώς πρέπει να ερμηνεύεται σωστά η απεικόνιση μετά την έναρξη θεραπείας;","Archiviertes Resektat ausreichend; keine neue Biopsie allein zur 'VEGF-Testung' erforderlich.":"Το αρχειοθετημένο δείγμα εκτομής είναι επαρκές· δεν απαιτείται νέα βιοψία μόνο για «έλεγχο VEGF». ","Testfalle":"Παγίδα ελέγχου","Ein RCC-spezifischer VHL/HIF-Test hat hier keinen sinnvollen Selektionsnutzen.":"RCC-specific έλεγχος VHL/HIF δεν έχει ουσιαστική χρησιμότητα επιλογής εδώ.","Radiologie":"Ακτινολογία","Kontrastmittelaufnahme ist stark von Blut-Hirn-Schranken-Permeabilität abhängig.":"Η πρόσληψη σκιαγραφικού εξαρτάται έντονα από τη διαπερατότητα του αιματοεγκεφαλικού φραγμού.","Symptomverbesserung kann real sein, auch wenn der antitumorale Effekt begrenzt bleibt.":"Η βελτίωση των συμπτωμάτων μπορεί να είναι πραγματική ακόμη και αν το αντικαρκινικό αποτέλεσμα παραμένει περιορισμένο.","Anti-VEGF-/Angiogenese-Kontext":"Πλαίσιο anti-VEGF/αγγειογένεσης","GBM zeigt ausgeprägte Gefäßproliferation; Anti-VEGF kann Gefäßpermeabilität und vasogenes Ödem rasch reduzieren.":"Το GBM εμφανίζει έντονη αγγειακή πολλαπλασιασμό· το anti-VEGF μπορεί να μειώσει γρήγορα την αγγειακή διαπερατότητα και το αγγειογενές οίδημα.","VHL/HIF-Panel":"Panel VHL/HIF","RCC-spezifische VHL/HIF-Testung liefert für diesen GBM-Fall keinen validierten Therapie-Selektionsnutzen und wäre ein entitätsfremder Low-value-Test.":"RCC-specific έλεγχος VHL/HIF δεν προσφέρει επικυρωμένο όφελος επιλογής θεραπείας σε αυτή την περίπτωση GBM και θα ήταν low-value test ακατάλληλο για την οντότητα.","Zusätzliche genomische Information ändert die zentrale Anti-VEGF-/Imaging-Lernfrage nicht.":"Πρόσθετη γονιδιωματική πληροφορία δεν αλλάζει το κεντρικό εκπαιδευτικό ερώτημα anti-VEGF/imaging.","MRT vor Therapie":"MRI πριν από θεραπεία","Starke Kontrastmittelaufnahme und ausgeprägtes vasogenes Ödem.":"Έντονη πρόσληψη σκιαγραφικού και σημαντικό αγγειογενές οίδημα.","Steroidabhängige fokal-neurologische Symptome.":"Steroid-dependent εστιακά νευρολογικά συμπτώματα.","Anti-VEGF kann beim rezidivierten Glioblastom rasch Gefäßpermeabilität und Ödem reduzieren und damit Symptome sowie Kontrastmittelaufnahme deutlich verbessern. Diese radiologische 'Pseudoresponse' darf jedoch nicht mit einer proportionalen Eliminierung infiltrierender Tumorzellen gleichgesetzt werden. Verlaufskontrolle muss deshalb neben Kontrastmittelaufnahme auch FLAIR/non-enhancing disease, Klinik und Steroidbedarf integrieren.":"Το anti-VEGF μπορεί να μειώσει γρήγορα την αγγειακή διαπερατότητα και το οίδημα στο υποτροπιάζον γλοιοβλάστωμα, βελτιώνοντας σημαντικά συμπτώματα και πρόσληψη σκιαγραφικού. Ωστόσο αυτή η ακτινολογική «pseudoresponse» δεν πρέπει να εξισώνεται με ανάλογη εξάλειψη διηθητικών καρκινικών κυττάρων. Η παρακολούθηση πρέπει να ενσωματώνει enhancement, FLAIR/non-enhancing disease, κλινική εικόνα και ανάγκη στεροειδών.","Teilbefund: Die Gefäßreaktion kann eindrucksvoll sein, sagt aber allein wenig über die gesamte infiltrative Tumorlast aus.":"Μερικό αποτέλεσμα: η αγγειακή ανταπόκριση μπορεί να είναι εντυπωσιακή, αλλά μόνη της λέει λίγα για το συνολικό διηθητικό φορτίο όγκου.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem erklären":"Εξηγήστε την επίδραση anti-VEGF στην αγγειακή διαπερατότητα/οίδημα","Pseudoresponse von echter proportionaler Zytoreduktion trennen":"Διαχωρίστε pseudoresponse από πραγματική αναλογική κυτταρομείωση","FLAIR/non-enhancing disease und Klinik mitbewerten":"Αξιολογήστε επίσης FLAIR/non-enhancing disease και κλινική εικόνα","RCC-VHL/HIF-Testung nicht importieren":"Μην εισάγετε έλεγχο VHL/HIF από RCC","Falschaussage: 80 % weniger Enhancement = 80 % weniger Tumorzellen":"Λανθασμένη δήλωση: 80% λιγότερο enhancement = 80% λιγότερα καρκινικά κύτταρα","Optimale Lösung: Bevacizumab kann klinisch sehr wertvolle Ödem-/Permeabilitätseffekte erzeugen; gerade deshalb muss die beeindruckende MRT-Reaktion als mögliche Pseudoresponse erkannt und multimodal beurteilt werden.":"Βέλτιστη λύση: το bevacizumab μπορεί να προσφέρει κλινικά πολύτιμες επιδράσεις σε οίδημα/διαπερατότητα· ακριβώς γι' αυτό η εντυπωσιακή MRI response πρέπει να αναγνωρίζεται ως πιθανή pseudoresponse και να αξιολογείται πολυτροπικά.","Glioblastom":"Γλοιοβλάστωμα","Pseudoresponse":"Pseudoresponse","Ödem":"Οίδημα","Das MRT schrumpft schneller als der Tumor":"Η MRI «συρρικνώνεται» ταχύτερα από τον όγκο","Neuroonkologie / Neuroradiologie / MTB":"Νευρο-ογκολογία / Νευροακτινολογία / MTB","VEGF-bedingte Gefäßpermeabilität und Ödem beim GBM erklären.":"Εξηγήστε VEGF-related αγγειακή διαπερατότητα και οίδημα στο GBM.","Anti-VEGF-bedingte Pseudoresponse erkennen.":"Αναγνωρίστε anti-VEGF-induced pseudoresponse.","Kontrastmittelreduktion nicht direkt in Tumorzellreduktion übersetzen.":"Μην μεταφράζετε άμεσα τη μείωση enhancement σε μείωση καρκινικών κυττάρων.","FLAIR/non-enhancing disease, Klinik und Steroidbedarf in die Verlaufskontrolle integrieren.":"Ενσωματώστε FLAIR/non-enhancing disease, κλινική εικόνα και ανάγκη στεροειδών στην παρακολούθηση.","Entitätsfremde VHL/HIF-Testung vermeiden.":"Αποφύγετε έλεγχο VHL/HIF ακατάλληλο για την οντότητα.","Zwei Wochen nach Bevacizumab ist die Kontrastmittelaufnahme dramatisch kleiner, der Patient braucht weniger Steroid und fühlt sich besser. Auf den ersten Blick ein spektakuläres Tumoransprechen – bis man versteht, was Anti-VEGF mit der Blut-Hirn-Schranke macht.":"Δύο εβδομάδες μετά το bevacizumab, το enhancement είναι δραματικά μικρότερο, ο ασθενής χρειάζεται λιγότερα στεροειδή και αισθάνεται καλύτερα. Με την πρώτη ματιά, εντυπωσιακή ανταπόκριση όγκου — μέχρι να κατανοήσει κανείς τι κάνει το anti-VEGF στον αιματοεγκεφαλικό φραγμό.","62-jähriger Patient mit symptomatischem Rezidiv eines IDH-Wildtyp-Glioblastoms. Bevacizumab wird wegen Ödem und Progress eingesetzt. Der Fall lehrt, echte klinische Verbesserung und radiologische Pseudoresponse gleichzeitig richtig zu würdigen.":"Άνδρας 62 ετών με συμπτωματική υποτροπή IDH-wild-type γλοιοβλαστώματος. Το bevacizumab χρησιμοποιείται για οίδημα και πρόοδο. Η περίπτωση διδάσκει πώς να αξιολογούνται σωστά ταυτόχρονα η πραγματική κλινική βελτίωση και η ακτινολογική pseudoresponse.","Gefäßpermeabilität":"Αγγειακή διαπερατότητα","GBM-Gefäße sind abnormal und leaky.":"Τα αγγεία του GBM είναι ανώμαλα και leaky.","Enhancement ist nicht nur Tumormasse, sondern auch Blut-Hirn-Schranken-Phänomen.":"Το enhancement αντανακλά όχι μόνο μάζα όγκου, αλλά και φαινόμενο του αιματοεγκεφαλικού φραγμού.","Anti-VEGF kann wirklich helfen":"Το anti-VEGF μπορεί πραγματικά να βοηθήσει","Ödem und Steroidbedarf sinken.":"Το οίδημα και η ανάγκη στεροειδών μειώνονται.","Pseudoresponse bedeutet nicht 'kein Nutzen'.":"Pseudoresponse δεν σημαίνει «κανένα όφελος». ","Aber Imaging kann täuschen":"Αλλά η απεικόνιση μπορεί να παραπλανήσει","Non-enhancing/infiltrative disease kann fortbestehen.":"Non-enhancing/infiltrative disease μπορεί να επιμένει.","Response muss multimodal bewertet werden.":"Η ανταπόκριση πρέπει να αξιολογείται πολυτροπικά.","Vor Therapie":"Πριν από θεραπεία","starkes Enhancement + massives vasogenes Ödem":"Έντονο enhancement + μαζικό αγγειογενές οίδημα","Hemiparese, Kopfschmerz, Steroidbedarf":"Ημιπάρεση, κεφαλαλγία, ανάγκη στεροειδών","Nekrose + mikrovaskuläre Proliferation":"Νέκρωση + μικροαγγειακή πολλαπλασιασμός","Keine neue Biopsie nur zur VEGF-Testung nötig.":"Δεν απαιτείται νέα βιοψία μόνο για έλεγχο VEGF.","VHL/HIF-Panel ist hier ein bewusster RCC-Copyover und nicht erforderlich.":"Το panel VHL/HIF είναι εδώ σκόπιμο RCC copyover και δεν απαιτείται.","Radiologische Verlaufskriterien müssen Anti-VEGF-Effekte berücksichtigen.":"Τα ακτινολογικά κριτήρια ανταπόκρισης πρέπει να λαμβάνουν υπόψη τις επιδράσεις anti-VEGF.","Was erklärt die schnelle Abnahme des Enhancements am besten?":"Τι εξηγεί καλύτερα τη γρήγορη μείωση του enhancement;","Reduzierte Gefäßpermeabilität/Normalisierung und weniger Ödem können einen großen Anteil beitragen.":"Η μειωμένη αγγειακή διαπερατότητα/ομαλοποίηση και το λιγότερο οίδημα μπορούν να συμβάλουν σημαντικά.","Es beweist proportional dieselbe Abnahme der Tumorzellzahl.":"Αποδεικνύει ανάλογη μείωση του αριθμού καρκινικών κυττάρων.","IDH-Mutation entsteht unter Therapie.":"Αναπτύσσεται μετάλλαξη IDH κατά τη θεραπεία.","Es ist immer Strahlennekrose.":"Είναι πάντα ακτινική νέκρωση.","Anti-VEGF beeinflusst die Blut-Hirn-Schranke stark.":"Το anti-VEGF επηρεάζει έντονα τον αιματοεγκεφαλικό φραγμό.","Was bedeutet 'Pseudoresponse'?":"Τι σημαίνει «pseudoresponse»;","Radiologisch eindrucksvolle Abnahme des Enhancements kann den antitumoralen Zell-Effekt überschätzen.":"Μια ακτινολογικά εντυπωσιακή μείωση του enhancement μπορεί να υπερεκτιμήσει το αντικαρκινικό κυτταρικό αποτέλεσμα.","Jede klinische Verbesserung ist eingebildet.":"Κάθε κλινική βελτίωση είναι φανταστική.","Es bedeutet zwingend Progress.":"Σημαίνει υποχρεωτικά πρόοδο.","MRT ist technisch unbrauchbar.":"Η MRI είναι τεχνικά άχρηστη.","Der Nutzen kann real sein, aber Enhancement überschätzt den Zell-Effekt.":"Το όφελος μπορεί να είναι πραγματικό, αλλά το enhancement υπερεκτιμά το κυτταρικό αποτέλεσμα.","Was muss zusätzlich betrachtet werden?":"Τι άλλο πρέπει να συνεκτιμηθεί;","FLAIR/non-enhancing disease, Klinik, Steroidbedarf und serieller Verlauf.":"FLAIR/non-enhancing disease, κλινική εικόνα, ανάγκη στεροειδών και διαχρονική πορεία.","Nur kontrastmittelaufnehmendes Volumen.":"Μόνο ο όγκος με enhancement.","VHL-Mutationsstatus.":"Status μετάλλαξης VHL.","PD-L1-IHC.":"PD-L1 IHC.","Anti-VEGF erfordert breitere Responsebewertung.":"Το anti-VEGF απαιτεί ευρύτερη αξιολόγηση ανταπόκρισης.","Warum ist VHL/HIF-Panel hier falsch?":"Γιατί είναι λάθος το panel VHL/HIF εδώ;","Es importiert einen RCC-spezifischen Test ohne validierten Selektionsnutzen in den GBM-Fall.":"Μεταφέρει RCC-specific test στην περίπτωση GBM χωρίς επικυρωμένη χρησιμότητα επιλογής.","GBM hat keine DNA.":"Το GBM δεν έχει DNA.","VEGF ist im GBM irrelevant.":"Το VEGF είναι άσχετο στο GBM.","Nur wegen TAT.":"Μόνο λόγω TAT.","Angiogenese ist gemeinsam, Testalgorithmen sind entitätsspezifisch.":"Η αγγειογένεση είναι κοινή, αλλά οι αλγόριθμοι ελέγχου είναι ειδικοί για την οντότητα.","Bewerten Sie die frühe MRT- und klinische Veränderung nach Bevacizumab und formulieren Sie, warum eine starke Kontrastmittelreduktion nicht automatisch eine gleich starke Zytoreduktion bedeutet.":"Αξιολογήστε την πρώιμη MRI και κλινική μεταβολή μετά bevacizumab και εξηγήστε γιατί μεγάλη μείωση enhancement δεν σημαίνει αυτόματα εξίσου μεγάλη κυτταρομείωση.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem benennen.":"Αναγνωρίστε την επίδραση anti-VEGF στην αγγειακή διαπερατότητα/οίδημα.","Klinische Symptomverbesserung anerkennen.":"Αναγνωρίστε την κλινική βελτίωση συμπτωμάτων.","Pseudoresponse erklären.":"Εξηγήστε pseudoresponse.","FLAIR/non-enhancing disease und seriellen Verlauf integrieren.":"Ενσωματώστε FLAIR/non-enhancing disease και διαχρονική πορεία.","VHL/HIF-Testung vermeiden.":"Αποφύγετε έλεγχο VHL/HIF.","Wenn Bildgebung und Klinik diskordant bleiben, neuroradiologische Spezialverfahren/Verlauf nutzen.":"Αν απεικόνιση και κλινική εικόνα παραμένουν ασύμφωνες, χρησιμοποιήστε εξειδικευμένες νευροακτινολογικές τεχνικές/παρακολούθηση.","Bevacizumab primär symptomatisch/krankheitskontrollierend diskutieren, ohne radiologische Überversprechen.":"Συζητήστε bevacizumab κυρίως για έλεγχο συμπτωμάτων/νόσου χωρίς ακτινολογικές υπερβολικές υποσχέσεις.","Enhancement = Tumorzellzahl":"Enhancement = αριθμός καρκινικών κυττάρων","BBB-Permeabilität beeinflusst Enhancement stark.":"Η διαπερατότητα BBB επηρεάζει έντονα το enhancement.","Pseudoresponse = kein Nutzen":"Pseudoresponse = κανένα όφελος","Ödem- und Steroidreduktion können klinisch sehr relevant sein.":"Η μείωση οιδήματος και ανάγκης στεροειδών μπορεί να είναι πολύ σημαντική κλινικά.","VHL testen":"Ελέγξτε VHL","RCC-Copyover ohne Selektionsnutzen.":"RCC copyover χωρίς χρησιμότητα επιλογής.","80 % weniger Enhancement, aber nicht 80 % weniger Tumor":"80% λιγότερο enhancement, αλλά όχι 80% λιγότερος όγκος","Der Patient verbessert sich und das MRT sieht spektakulär aus. FLAIR zeigt jedoch weiter infiltrative Erkrankung. Der Twist ist doppelt: Der Effekt ist klinisch real und radiologisch zugleich potenziell irreführend.":"Ο ασθενής βελτιώνεται και η MRI φαίνεται εντυπωσιακή. Ωστόσο το FLAIR εξακολουθεί να δείχνει διηθητική νόσο. Το twist είναι διπλό: το αποτέλεσμα είναι κλινικά πραγματικό και ταυτόχρονα ακτινολογικά δυνητικά παραπλανητικό.","Er verhindert sowohl Über- als auch Unterbewertung antiangiogener Therapie.":"Αποτρέπει τόσο την υπερεκτίμηση όσο και την υποεκτίμηση αντιαγγειογενετικής θεραπείας.","Pseudoresponse richtig gelesen":"Pseudoresponse ερμηνεύτηκε σωστά","Ödem/Enhancement deutlich geringer, Klinik besser; infiltrative FLAIR-Komponente bleibt → Response nicht als proportionale Zytoreduktion überinterpretieren.":"Οίδημα/enhancement σαφώς μειωμένα, κλινική βελτίωση· η διηθητική FLAIR συνιστώσα παραμένει → μην υπερερμηνεύετε την ανταπόκριση ως αναλογική κυτταρομείωση.","Neuroonkologische Response korrekt.":"Σωστή ερμηνεία νευρο-ογκολογικής ανταπόκρισης.","Pseudoresponse erkannt, Nutzen abgewertet":"Pseudoresponse αναγνωρίστηκε, το όφελος υποτιμήθηκε","Imaging-Falle erkannt, aber reale Symptom-/Ödemkontrolle fälschlich als bedeutungslos bezeichnet.":"Η απεικονιστική παγίδα αναγνωρίζεται, αλλά ο πραγματικός έλεγχος συμπτωμάτων/οιδήματος χαρακτηρίζεται λανθασμένα ασήμαντος.","Zu einseitig.":"Υπερβολικά μονόπλευρο.","MRT = Zellzählung":"MRI = αριθμός κυττάρων","Kontrastmittelvolumen wird direkt als Tumormasse interpretiert.":"Ο όγκος με enhancement ερμηνεύεται άμεσα ως μάζα όγκου.","Zentralen Anti-VEGF-Effekt verpasst.":"Χάνεται η κεντρική επίδραση anti-VEGF.","Enhancement sinkt, FLAIR stabil/steigend":"Enhancement μειώνεται, FLAIR σταθερό/αυξανόμενο","Pseudoresponse/discordant response erwägen und seriell beurteilen.":"Εξετάστε pseudoresponse/discordant response και αξιολογήστε διαχρονικά.","Keine falsche Vollremission.":"Χωρίς ψευδή πλήρη ύφεση.","Steroidbedarf sinkt":"Η ανάγκη στεροειδών μειώνεται","Als echten klinischen Benefit dokumentieren.":"Τεκμηριώστε ως πραγματικό κλινικό όφελος.","Symptomkontrolle wird nicht kleingeredet.":"Ο έλεγχος συμπτωμάτων δεν υποτιμάται.","VEGF-Inhibition kann Gefäßpermeabilität und Ödem rasch reduzieren.":"Η αναστολή VEGF μπορεί να μειώσει γρήγορα την αγγειακή διαπερατότητα και το οίδημα.","Kontrastmittelaufnahme ist beim GBM kein reiner Tumorzellmarker.":"Το contrast enhancement στο GBM δεν είναι καθαρός δείκτης καρκινικών κυττάρων.","Pseudoresponse kann gleichzeitig mit echter klinischer Besserung bestehen.":"Pseudoresponse μπορεί να συνυπάρχει με πραγματική κλινική βελτίωση.","FLAIR/non-enhancing disease und Klinik gehören in die Verlaufskontrolle.":"FLAIR/non-enhancing disease και κλινική εικόνα ανήκουν στην αξιολόγηση παρακολούθησης.","Angiogenese-Biologie rechtfertigt nicht automatisch VHL/HIF-Tumortestung.":"Η βιολογία της αγγειογένεσης δεν δικαιολογεί αυτόματα tumor testing VHL/HIF.","Nach Bevacizumab sinken Enhancement, Ödem und Steroidbedarf deutlich. Das ist klinisch relevant, kann aber den zytoreduktiven Effekt überschätzen. FLAIR/non-enhancing disease und Verlauf müssen integriert werden; ein RCC-artiges VHL/HIF-Panel hat keinen Selektionsnutzen.":"Μετά το bevacizumab, enhancement, οίδημα και ανάγκη στεροειδών μειώνονται σημαντικά. Αυτό είναι κλινικά σημαντικό αλλά μπορεί να υπερεκτιμά την κυτταρομειωτική επίδραση. FLAIR/non-enhancing disease και πορεία πρέπει να ενσωματώνονται· RCC-like panel VHL/HIF δεν έχει χρησιμότητα επιλογής.","Ödem vs Tumor":"Οίδημα vs όγκος","multimodale Bildgebung":"Πολυτροπική απεικόνιση","kein RCC-Copyover":"Χωρίς RCC copyover","Wie unterscheiden sich Pseudoprogression und Pseudoresponse?":"Πώς διαφέρουν pseudoprogression και pseudoresponse;","Welche klinischen Parameter helfen bei anti-VEGF?":"Ποιες κλινικές παράμετροι βοηθούν κατά τη θεραπεία anti-VEGF;","Warum ist Enhancement biologisch kein einfacher Tumormasse-Readout?":"Γιατί το enhancement δεν είναι βιολογικά απλό readout μάζας όγκου;","dramatische MRT-Besserung trotz persistierender FLAIR-Krankheit":"Δραματική βελτίωση MRI παρά επίμονη FLAIR νόσο","Anti-VEGF verändert Bildgebung und Klinik unterschiedlich":"Το anti-VEGF αλλάζει διαφορετικά απεικόνιση και κλινική εικόνα","VEGF/Ödem → Bevacizumab → Enhancement fällt → multimodale Response":"VEGF/οίδημα → bevacizumab → enhancement μειώνεται → πολυτροπική αξιολόγηση ανταπόκρισης","PD-L1 und TMB sehen gut aus – aber die T-Zellen bleiben im Stroma":"PD-L1 και TMB φαίνονται ευνοϊκά — αλλά τα T cells παραμένουν στο στρώμα","Stromareicher Tumor mit immune-exc…":"Όγκος πλούσιος σε στρώμα με immune-exc…","68-jähriger Patient mit metastasiertem Urothelkarzinom. Vor Checkpoint-Therapie lagen PD-L1-Expression und eine relativ hohe Mutationslast vor; klinisch kam es dennoch zu frühem Progress.":"Άνδρας 68 ετών με μεταστατικό ουροθηλιακό καρκίνωμα. Πριν από checkpoint therapy υπήρχαν έκφραση PD-L1 και σχετικά υψηλό mutational burden· παρ' όλα αυτά εμφανίστηκε πρώιμη κλινική πρόοδος.","Wie kann ein scheinbar immunogener Tumor trotzdem primär resistent sein – und was lehrt die räumliche Verteilung der Immunzellen?":"Πώς μπορεί ένας φαινομενικά ανοσογόνος όγκος να είναι παρ' όλα αυτά πρωτογενώς ανθεκτικός — και τι μας διδάσκει η χωρική κατανομή των ανοσοκυττάρων;","Retrospektive Einordnung und Studienplanung für die nächste Linie.":"Αναδρομική ερμηνεία και σχεδιασμός μελέτης για την επόμενη γραμμή.","PD-L1 hoch; TMB erhöht; kein MSI-H-Kontext.":"PD-L1 υψηλό· TMB αυξημένο· χωρίς πλαίσιο MSI-H.","Checkpoint-Inhibition mit frühem radiologischem Progress.":"Checkpoint inhibition με πρώιμη ακτινολογική πρόοδο.","Biopsie":"Βιοψία","Progressionsbiopsie zeigt stark stromareichen Tumor.":"Η βιοψία προόδου δείχνει όγκο έντονα πλούσιο σε στρώμα.","Biomarkerwerte werden ohne räumlichen Zellkontext als Garantie für Immunantwort interpretiert.":"Οι τιμές βιοδεικτών ερμηνεύονται ως εγγύηση ανοσολογικής ανταπόκρισης χωρίς χωρικό κυτταρικό πλαίσιο.","Invasive Tumornester in breiten fibrotischen Stromasepten.":"Διηθητικές νησίδες όγκου μέσα σε ευρέα ινώδη στρωματικά διαφράγματα.","CD8":"CD8","Viele T-Zellen vorhanden, aber überwiegend im peritumoralen Stroma; Tumorzellnester selbst sind arm an CD8-Zellen.":"Υπάρχουν πολλά T cells, αλλά κυρίως στο περινεοπλασματικό στρώμα· οι ίδιες οι νησίδες όγκου περιέχουν λίγα CD8 cells.","CAF-Kontext":"Πλαίσιο CAF","FAP/αSMA-reiches aktiviertes Stroma.":"Ενεργοποιημένο στρώμα πλούσιο σε FAP/αSMA.","Immune-excluded statt wirklich inflamed/hot.":"Immune-excluded αντί για πραγματικά inflamed/hot.","Progressionsbiopsie mit 45 % Tumoranteil.":"Βιοψία προόδου με 45% περιεκτικότητα σε όγκο.","ausreichend für fokussierte TIL-/Stroma-IHC.":"Επαρκής για εστιασμένη TIL/stroma IHC.","Evidenzgrenze":"Όριο τεκμηρίωσης","TME-IHC erklärt die Resistenzbiologie, ist aber kein routinemäßiger alleiniger Therapieausschluss- oder Auswahltest.":"Η TME IHC εξηγεί τη βιολογία αντοχής, αλλά δεν αποτελεί routine stand-alone test αποκλεισμού ή επιλογής θεραπείας.","Räumliche Biologie nicht mit einem neuen Companion Diagnostic verwechseln.":"Μην συγχέετε τη χωρική βιολογία με νέο companion diagnostic.","Stroma-/Immune-exclusion-Kontext":"Πλαίσιο στρώματος/immune-exclusion","PD-L1 bleibt deutlich exprimiert; der Befund allein erklärt die fehlende klinische Antwort nicht.":"Το PD-L1 παραμένει σαφώς εκφρασμένο· το εύρημα μόνο του δεν εξηγεί την έλλειψη κλινικής ανταπόκρισης.","TMB erhöht. Potenziell vorhandene Neoantigene garantieren dennoch keine effektive T-Zell-Interaktion mit den Tumorzellen.":"TMB αυξημένο. Τα πιθανά νεοαντιγόνα παρ' όλα αυτά δεν εγγυώνται αποτελεσματική αλληλεπίδραση T cells με καρκινικά κύτταρα.","TIL-Verteilung":"Κατανομή TIL","CD8-positive T-Zellen sind zahlreich, bleiben jedoch überwiegend stromal/peritumoral; intratumorale Penetration ist gering.":"Τα CD8-positive T cells είναι πολλά, αλλά παραμένουν κυρίως στρωματικά/περινεοπλασματικά· η ενδοογκική διείσδυση είναι χαμηλή.","Stroma":"Στρώμα","Breites FAP/αSMA-positives fibroblastenreiches Stroma stützt ein immune-excluded Muster. Der Befund ist mechanistisch plausibel, aber kein allein validierter Therapie-Selektionsassay.":"Ευρύ στρώμα πλούσιο σε FAP/αSMA-positive ινοβλάστες υποστηρίζει immune-excluded pattern. Το εύρημα είναι μηχανιστικά εύλογο, αλλά δεν αποτελεί stand-alone επικυρωμένο assay επιλογής θεραπείας.","Klinischer Twist":"Κλινικό twist","Früher Progress trotz scheinbar günstiger Immunmarker.":"Πρώιμη πρόοδος παρά τους φαινομενικά ευνοϊκούς ανοσολογικούς δείκτες.","Stark stromareicher Tumor mit räumlicher Trennung von CD8-Zellen und Tumornestern.":"Όγκος έντονα πλούσιος σε στρώμα με χωρικό διαχωρισμό CD8 cells και νησίδων όγκου.","PD-L1-Expression und erhöhte TMB können immunologische Potenziale anzeigen, garantieren aber keine effektive Antitumor-Immunität. Die Progressionsbiopsie zeigt ein klassisches immune-excluded Muster: T-Zellen sind vorhanden, werden jedoch durch das stromale Mikromilieu räumlich von Tumorzellen ferngehalten. Dieser Befund erklärt Resistenzbiologie, darf aber nicht als alleiniger validierter Companion Diagnostic für eine konkrete Folgetherapie überinterpretiert werden.":"Η έκφραση PD-L1 και το αυξημένο TMB μπορούν να υποδηλώνουν ανοσολογικό δυναμικό, αλλά δεν εγγυώνται αποτελεσματική αντικαρκινική ανοσία. Η βιοψία προόδου δείχνει κλασικό immune-excluded pattern: T cells υπάρχουν, αλλά το στρωματικό μικροπεριβάλλον τα κρατά χωρικά μακριά από τα καρκινικά κύτταρα. Αυτό εξηγεί τη βιολογία αντοχής, αλλά δεν πρέπει να υπερερμηνεύεται ως stand-alone επικυρωμένο companion diagnostic για συγκεκριμένη επόμενη θεραπεία.","Teilbefund: Gute Biomarkerwerte ohne räumliche TIL-Analyse erklären die tatsächliche Immunfunktion nur unvollständig.":"Μερικό αποτέλεσμα: ευνοϊκές τιμές βιοδεικτών χωρίς χωρική ανάλυση TIL περιγράφουν ατελώς την πραγματική ανοσολογική λειτουργία.","TMB/PD-L1 als Potenzialmarker von funktioneller T-Zell-Tumor-Interaktion trennen":"Διαχωρίστε TMB/PD-L1 ως δείκτες δυναμικού από τη λειτουργική αλληλεπίδραση T-cell–tumor","Immune exclusion über räumliche CD8-Verteilung erkennen":"Αναγνωρίστε immune exclusion μέσω της χωρικής κατανομής CD8","CAF-/Stroma-Barriere biologisch erklären":"Εξηγήστε βιολογικά το φράγμα CAF/στρώματος","TME-IHC nicht zum nicht validierten Therapieausschlusstest machen":"Μην μετατρέπετε TME IHC σε μη επικυρωμένο test αποκλεισμού θεραπείας","Falschaussage: hohe TMB + PD-L1 garantieren Checkpoint-Ansprechen":"Λανθασμένη δήλωση: υψηλό TMB + PD-L1 εγγυώνται ανταπόκριση σε checkpoint","Optimale Lösung: PD-L1/TMB nicht als Garantie interpretieren; die räumliche TIL-Verteilung zeigt, dass Immunzellen vorhanden, aber funktionell vom Tumor ausgeschlossen sind. Mechanistisch stark, prädiktiv aber nicht als alleiniger Routinetest validiert.":"Βέλτιστη λύση: μην ερμηνεύετε PD-L1/TMB ως εγγύηση· η χωρική κατανομή TIL δείχνει ότι ανοσοκύτταρα υπάρχουν αλλά αποκλείονται λειτουργικά από τον όγκο. Μηχανιστικά ισχυρό, αλλά όχι επικυρωμένο ως stand-alone routine predictive test.","CAF":"CAF","Urothelkarzinom":"Ουροθηλιακό καρκίνωμα","Viele T-Zellen – aber auf der falschen Seite der Stromabarriere":"Πολλά T cells — αλλά στη λάθος πλευρά του στρωματικού φραγμού","Molekularpathologie / Immunonkologie / MTB":"Μοριακή παθολογία / Ανοσο-ογκολογία / MTB","PD-L1/TMB als Potenzialmarker von funktioneller Immunantwort unterscheiden.":"Διαχωρίστε PD-L1/TMB ως δείκτες δυναμικού από τη λειτουργική ανοσολογική ανταπόκριση.","Immune-excluded Muster anhand räumlicher TIL-Verteilung erkennen.":"Αναγνωρίστε immune-excluded pattern από τη χωρική κατανομή TIL.","CAF-/Stromabarriere als Resistenzmechanismus erklären.":"Εξηγήστε το φράγμα CAF/στρώματος ως μηχανισμό αντοχής.","TME-IHC als mechanistischen und nicht automatisch validierten Selektionsmarker einordnen.":"Εντάξτε TME IHC ως μηχανιστική, όχι αυτόματα ως επικυρωμένο selection marker.","Klinische Nonresponse trotz günstiger Einzelmarker biologisch plausibel erklären.":"Εξηγήστε βιολογικά την κλινική nonresponse παρά ευνοϊκούς μεμονωμένους δείκτες.","PD-L1 ist hoch, TMB ist erhöht – und der Tumor wächst unter Checkpoint-Inhibition trotzdem weiter. In der Progressionsbiopsie sind sogar viele CD8-T-Zellen zu sehen. Das Problem: Sie stehen fast alle draußen im Stroma.":"Το PD-L1 είναι υψηλό, το TMB αυξημένο — κι όμως ο όγκος συνεχίζει να μεγαλώνει υπό checkpoint inhibition. Η βιοψία προόδου δείχνει ακόμη και πολλά CD8 T cells. Το πρόβλημα: σχεδόν όλα παραμένουν έξω, στο στρώμα.","68-jähriger Patient mit metastasiertem Urothelkarzinom und frühem Progress unter ICI trotz scheinbar günstiger PD-L1-/TMB-Konstellation. Die Progressionsbiopsie zeigt, dass nicht die Zahl allein, sondern die räumliche Position der Immunzellen entscheidend ist.":"Άνδρας 68 ετών με μεταστατικό ουροθηλιακό καρκίνωμα και πρώιμη πρόοδο υπό ICI παρά φαινομενικά ευνοϊκή συνθήκη PD-L1/TMB. Η βιοψία προόδου δείχνει ότι δεν μετρά μόνο ο αριθμός, αλλά και η χωρική θέση των ανοσοκυττάρων.","Potenzial":"Δυναμικό","PD-L1 hoch, TMB erhöht.":"PD-L1 υψηλό, TMB αυξημένο.","Diese Marker können Immunogenität anzeigen, garantieren aber keine effektive Antwort.":"Αυτοί οι δείκτες μπορούν να υποδηλώνουν ανοσογονικότητα, αλλά δεν εγγυώνται αποτελεσματική ανταπόκριση.","Raum":"Χώρος","CD8-Zellen liegen vor allem stromal/peritumoral.":"Τα CD8 cells εντοπίζονται κυρίως στρωματικά/περινεοπλασματικά.","Immune exclusion ist ein räumliches Phänomen.":"Το immune exclusion είναι χωρικό φαινόμενο.","Barriere":"Φραγμός","FAP/αSMA-reiches Stroma.":"Στρώμα πλούσιο σε FAP/αSMA.","CAF/Matrix können physische und signalbiologische Barrieren bilden.":"CAF/μήτρα μπορούν να σχηματίσουν φυσικά και σηματοδοτικά εμπόδια.","deutlich exprimiert":"Σαφώς εκφρασμένο","erhöht":"Αυξημένο","früher Progress unter Checkpoint-Inhibition":"Πρώιμη πρόοδος υπό checkpoint inhibition","Progressionsbiopsie ermöglicht räumliche TIL-/Stroma-Bewertung.":"Η βιοψία προόδου επιτρέπει χωρική αξιολόγηση TIL/στρώματος.","TME-Marker sind keine validierte alleinige Folgetherapie-Selektion.":"Οι δείκτες TME δεν είναι επικυρωμένοι ως stand-alone tests επιλογής επόμενης θεραπείας.","Mechanistische Erklärung darf nicht in Pseudopräzision kippen.":"Η μηχανιστική εξήγηση δεν πρέπει να μετατρέπεται σε ψευδο-ακρίβεια.","Was ist die wichtigste Erklärung für PD-L1/TMB ohne Response?":"Ποια είναι η σημαντικότερη εξήγηση για PD-L1/TMB χωρίς ανταπόκριση;","Marker zeigen Potenzial, aber nicht zwingend erfolgreiche T-Zell-Penetration und Funktion im Tumornest.":"Οι δείκτες δείχνουν δυναμικό, αλλά όχι απαραίτητα επιτυχή διείσδυση και λειτουργία T cells μέσα στις νησίδες όγκου.","PD-L1 und TMB müssen technisch falsch sein.":"PD-L1 και TMB πρέπει να είναι τεχνικά λανθασμένα.","So eine Konstellation ist unmöglich.":"Μια τέτοια συνθήκη είναι αδύνατη.","Hohe TMB beweist MSI-H.":"Υψηλό TMB αποδεικνύει MSI-H.","Biomarker und Funktion sind unterschiedliche Ebenen.":"Οι βιοδείκτες και η λειτουργία είναι διαφορετικά επίπεδα.","Welcher Befund definiert immune exclusion am besten?":"Ποιο εύρημα ορίζει καλύτερα immune exclusion;","Viele T-Zellen im Stroma, wenige innerhalb der Tumorzellnester.":"Πολλά T cells στο στρώμα, λίγα μέσα στις νησίδες όγκου.","Gar keine Immunzellen im gesamten Präparat.":"Καθόλου ανοσοκύτταρα σε ολόκληρο το παρασκεύασμα.","Dichtes intraepitheliales CD8-Infiltrat.":"Πυκνή ενδοεπιθηλιακή διήθηση CD8.","PD-L1 hoch.":"PD-L1 υψηλό.","Räumliche Verteilung ist zentral.":"Η χωρική κατανομή είναι κεντρική.","Wie darf FAP/αSMA/CD8-IHC genutzt werden?":"Πώς μπορεί να χρησιμοποιηθεί FAP/αSMA/CD8 IHC;","Als mechanistische Unterstützung eines stromal-excluded Musters, nicht als alleiniger zugelassener Companion Diagnostic.":"Ως μηχανιστική υποστήριξη stromal-excluded pattern, όχι ως stand-alone εγκεκριμένο companion diagnostic.","Als absolute Kontraindikation gegen jede ICI.":"Ως απόλυτη αντένδειξη για κάθε ICI.","Als Beweis für eine Standard-CAF-Therapie.":"Ως απόδειξη για standard CAF therapy.","Gar nicht interpretieren.":"Μην το ερμηνεύετε καθόλου.","Mechanistisch stark, klinisch nicht allein selektiv validiert.":"Μηχανιστικά ισχυρό, αλλά όχι κλινικά επικυρωμένο ως stand-alone selector.","Was ist die beste MTB-Kommunikation?":"Ποια είναι η καλύτερη επικοινωνία στο MTB;","Günstige Einzelmarker anerkennen, reale Nonresponse und spatial TME integrieren, experimentelle TME-Strategien als Studienoption kennzeichnen.":"Αναγνωρίστε τους ευνοϊκούς μεμονωμένους δείκτες, ενσωματώστε την πραγματική nonresponse και το spatial TME και χαρακτηρίστε πειραματικές TME στρατηγικές ως study options.","PD-L1 so oft wiederholen, bis ein höherer Wert entsteht.":"Επαναλάβετε PD-L1 μέχρι να προκύψει υψηλότερη τιμή.","TMB/PD-L1 als nutzlos erklären.":"Δηλώστε TMB/PD-L1 άχρηστα.","CAF-Targeting als Standard empfehlen.":"Συστήστε CAF-targeting ως standard.","Evidenzhierarchie + Biologie.":"Ιεραρχία τεκμηρίωσης + βιολογία.","Erklären Sie die primäre Resistenz trotz PD-L1/TMB und formulieren Sie, welche Aussage die Progressionsbiopsie liefert – und welche Therapieentscheidung sie gerade nicht allein rechtfertigt.":"Εξηγήστε την πρωτογενή αντοχή παρά PD-L1/TMB και διατυπώστε τι δείχνει η βιοψία προόδου — και ποια θεραπευτική απόφαση ακριβώς δεν δικαιολογεί μόνη της.","PD-L1/TMB als Potenzial, nicht Garantie einordnen.":"Εντάξτε PD-L1/TMB ως δυναμικό, όχι εγγύηση.","CD8-Verteilung räumlich beschreiben.":"Περιγράψτε χωρικά την κατανομή CD8.","Immune exclusion erkennen.":"Αναγνωρίστε immune exclusion.","CAF-/Stromabarriere mechanistisch erklären.":"Εξηγήστε μηχανιστικά το φράγμα CAF/στρώματος.","TME-IHC nicht als alleinigen Companion Diagnostic verwenden.":"Μην χρησιμοποιείτε TME IHC ως stand-alone companion diagnostic.","Studienoptionen klar als experimentell markieren.":"Χαρακτηρίστε σαφώς τις study options ως πειραματικές.","Wenn keine Progressionsbiopsie verfügbar ist, morphologische/radiologische Daten nutzen und TME-Hypothese als Hypothese belassen.":"Αν δεν υπάρχει βιοψία προόδου, χρησιμοποιήστε μορφολογικά/ακτινολογικά δεδομένα και διατηρήστε την TME υπόθεση ως υπόθεση.","TME-gerichtete Studien bei passender Verfügbarkeit diskutieren.":"Συζητήστε TME-directed studies εφόσον είναι κατάλληλα διαθέσιμες.","PD-L1/TMB garantieren Response":"PD-L1/TMB εγγυώνται ανταπόκριση","Funktionelle Immunantwort braucht mehr als Potenzialmarker.":"Η λειτουργική ανοσολογική ανταπόκριση απαιτεί περισσότερα από δείκτες δυναμικού.","TME-IHC = Therapieausschluss":"TME IHC = αποκλεισμός θεραπείας","Nicht als alleiniger validierter Selektionsassay etabliert.":"Δεν έχει καθιερωθεί ως stand-alone επικυρωμένο selection assay.","CAF-Targeting Standard":"CAF targeting standard","Mechanismus wird zu Routineempfehlung überhöht.":"Ένας μηχανισμός υπερβάλλεται σε routine σύσταση.","Die T-Zellen sind da – und kommen trotzdem nicht an den Tumor":"Τα T cells υπάρχουν — και παρ' όλα αυτά δεν φτάνουν στον όγκο","Die Progressionsbiopsie zeigt viele CD8-Zellen, aber fast ausschließlich in FAP/αSMA-reichem Stroma. Der scheinbare Widerspruch zwischen 'immunogen' und 'resistent' löst sich räumlich auf.":"Η βιοψία προόδου δείχνει πολλά CD8 cells, αλλά σχεδόν αποκλειστικά σε στρώμα πλούσιο σε FAP/αSMA. Η φαινομενική αντίφαση μεταξύ «ανοσογόνου» και «ανθεκτικού» λύνεται χωρικά.","Der Fall macht aus TME ein sichtbares diagnostisches Konzept statt einer abstrakten Signalwegfolie.":"Η περίπτωση μετατρέπει το TME σε ορατή διαγνωστική έννοια αντί για αφηρημένο pathway slide.","Spatial biology integriert":"Χωρική βιολογία ενσωματωμένη","PD-L1/TMB günstig, aber CD8 stromal ausgeschlossen; TME erklärt Resistenz, ohne einen neuen Companion Diagnostic zu behaupten.":"PD-L1/TMB ευνοϊκά, αλλά CD8 cells αποκλείονται στρωματικά· το TME εξηγεί την αντοχή χωρίς να ισχυρίζεται νέο companion diagnostic.","Biologie und Evidenz sauber getrennt.":"Βιολογία και τεκμηρίωση διαχωρίζονται καθαρά.","Stroma erkannt, Marker verworfen":"Το στρώμα αναγνωρίστηκε, οι δείκτες απορρίφθηκαν","Immune exclusion korrekt, aber PD-L1/TMB pauschal als wertlos dargestellt.":"Το immune exclusion είναι σωστό, αλλά PD-L1/TMB χαρακτηρίζονται συνολικά άχρηστα.","Zu absolut.":"Υπερβολικά απόλυτο.","Biomarker-Garantie":"Εγγύηση βιοδείκτη","Früher Progress wird ignoriert, weil PD-L1/TMB 'gut' sind.":"Η πρώιμη πρόοδος αγνοείται επειδή PD-L1/TMB είναι «καλά». ","Funktionelle Ebene verpasst.":"Χάνεται το λειτουργικό επίπεδο.","Studie mit TME-gerichteter Kombination verfügbar":"Διαθέσιμη μελέτη με TME-directed combination","Als experimentelle Option diskutieren.":"Συζητήστε ως πειραματική επιλογή.","Mechanistische Hypothese wird im passenden Evidenzrahmen genutzt.":"Η μηχανιστική υπόθεση χρησιμοποιείται στο κατάλληλο πλαίσιο τεκμηρίωσης.","Keine Studie":"Χωρίς μελέτη","Standardtherapie nach etablierter Entitätslogik.":"Standard therapy σύμφωνα με καθιερωμένη λογική ειδική για την οντότητα.","TME-Befund bleibt erklärend, nicht pseudoprädiktiv.":"Το TME finding παραμένει εξηγητικό, όχι ψευδο-προβλεπτικό.","Biomarker können Potenzial anzeigen, aber keine Antwort garantieren.":"Οι βιοδείκτες μπορούν να δείχνουν δυναμικό, αλλά δεν εγγυώνται ανταπόκριση.","Immune exclusion ist räumlich: Immunzellen vorhanden, aber vom Tumornest ferngehalten.":"Το immune exclusion είναι χωρικό: ανοσοκύτταρα υπάρχουν αλλά κρατούνται μακριά από τις νησίδες όγκου.","CAF-/Matrix-Komponenten können physische und signalbiologische Barrieren bilden.":"Συστατικά CAF/μήτρας μπορούν να σχηματίσουν φυσικά και σηματοδοτικά εμπόδια.","TME-IHC ist mechanistisch wertvoll, aber kein automatisch validierter Companion Diagnostic.":"Η TME IHC είναι μηχανιστικά πολύτιμη, αλλά όχι αυτόματα επικυρωμένο companion diagnostic.","Progressionsmaterial kann Resistenzbiologie sichtbar machen.":"Υλικό προόδου μπορεί να αποκαλύψει τη βιολογία αντοχής.","Trotz PD-L1 und erhöhter TMB zeigt die Progressionsbiopsie ein immune-excluded Muster mit CD8-Zellen im stromalen Kompartiment. Das erklärt die fehlende effektive Tumorinteraktion, ist aber kein alleiniger routinemäßiger Selektionsmarker für eine konkrete Folgetherapie.":"Παρά PD-L1 και αυξημένο TMB, η βιοψία προόδου δείχνει immune-excluded pattern με CD8 cells στο στρωματικό διαμέρισμα. Αυτό εξηγεί την έλλειψη αποτελεσματικής αλληλεπίδρασης με τον όγκο, αλλά δεν αποτελεί stand-alone routine selection marker για συγκεκριμένη επόμενη θεραπεία.","Marker vs Funktion":"Δείκτες vs λειτουργία","spatial TILs":"Χωρικά TILs","Stromabarriere":"Στρωματικός φραγμός","Was ist der Unterschied zwischen immune-desert und immune-excluded?":"Ποια είναι η διαφορά μεταξύ immune-desert και immune-excluded;","Welche Rolle kann TGF-β/CAF-Biologie spielen?":"Ποιον ρόλο μπορεί να παίξει η βιολογία TGF-β/CAF;","Wie könnte Digitalpathologie spatial TILs künftig standardisieren?":"Πώς θα μπορούσε η ψηφιακή παθολογία να τυποποιήσει τα spatial TILs στο μέλλον;","viele CD8-Zellen, aber außerhalb der Tumornester":"Πολλά CD8 cells, αλλά έξω από τις νησίδες όγκου","Räumliche Immunbiologie kann Einzelmarker widersprechen":"Η χωρική ανοσοβιολογία μπορεί να αντιφάσκει με μεμονωμένους δείκτες","PD-L1/TMB → Nonresponse → spatial biopsy → immune exclusion":"PD-L1/TMB → nonresponse → spatial biopsy → immune exclusion","pT1-CRC nach Endoskopie: Tumor budding als sichtbarer Invasions-Hallmark":"pT1 CRC μετά ενδοσκόπηση: tumor budding ως ορατό hallmark διήθησης","EMT-/Invasionsfront-Fall mit Metas…":"Περίπτωση EMT/μέτωπο διήθησης με metas…","Gastroenterologie / Viszeralchirurgie / Pathologieboard":"Γαστρεντερολογία / Σπλαχνική χειρουργική / Pathology board","56-jähriger Patient nach endoskopischer en-bloc-Resektion eines pT1-Sigmakarzinoms. Die Frage ist, ob die lokale Therapie ausreicht oder wegen Lymphknotenrisiko eine onkologische Nachresektion diskutiert werden muss.":"Άνδρας 56 ετών μετά ενδοσκοπική en-bloc εκτομή pT1 καρκινώματος σιγμοειδούς. Το ερώτημα είναι αν η τοπική θεραπεία αρκεί ή αν πρέπει να συζητηθεί ογκολογική επανεκτομή λόγω κινδύνου λεμφαδενικών μεταστάσεων.","Welche morphologischen Merkmale an der Invasionsfront sind klinisch relevant – und welche Rolle spielt das EMT-Konzept dabei?":"Ποια μορφολογικά χαρακτηριστικά στο μέτωπο διήθησης είναι κλινικά σημαντικά — και ποιον ρόλο παίζει η έννοια EMT;","Entscheidung über weitere Operation im nächsten Board.":"Απόφαση για περαιτέρω χειρουργείο στο επόμενο board.","Endoskopie":"Ενδοσκόπηση","20-mm-Läsion, vollständig en bloc reseziert.":"Βλάβη 20 mm, πλήρως εκτομημένη en bloc.","pT1-Adenokarzinom, Resektionsrand tumorfrei.":"pT1 αδενοκαρκίνωμα, όριο εκτομής ελεύθερο όγκου.","Konflikt":"Σύγκρουση","Ein 'R0' klingt beruhigend, aber R0 beantwortet das Risiko okkulter Lymphknotenmetastasen nicht allein.":"Ένα «R0» ακούγεται καθησυχαστικό, αλλά το R0 μόνο του δεν απαντά στον κίνδυνο λανθανουσών λεμφαδενικών μεταστάσεων.","Ein experimentelles EMT-IHC-Panel wird höher gewichtet als validierte histopathologische Risikofaktoren.":"Ένα πειραματικό EMT IHC panel αξιολογείται υψηλότερα από επικυρωμένους ιστοπαθολογικούς παράγοντες κινδύνου.","Histologie + Invasionsfront":"Ιστολογία + μέτωπο διήθησης","Submukosale Invasion; an der tiefsten Front zahlreiche Einzelzellen und kleine Tumorzellcluster entsprechend hochgradigem Tumor budding.":"Υποβλεννογόνια διήθηση· στο βαθύτερο μέτωπο, πολλά μεμονωμένα κύτταρα και μικρά clusters όγκου που αντιστοιχούν σε high-grade tumor budding.","Weitere Risiken":"Πρόσθετοι κίνδυνοι","Fokale lymphovaskuläre Invasion; keine schlechte Differenzierung.":"Εστιακή λεμφαγγειακή διήθηση· χωρίς κακή διαφοροποίηση.","EMT-Kontext":"Πλαίσιο EMT","An Buds fokal reduzierte membranäre E-Cadherin-Expression und veränderte β-Catenin-Lokalisation möglich – biologisch passend zu partieller EMT.":"Στα buds μπορεί να εμφανίζεται εστιακά μειωμένη μεμβρανική έκφραση E-cadherin και αλλοιωμένη εντόπιση β-catenin — βιολογικά συμβατά με partial EMT.","Morphologischer Risikomarker versus mechanistischer Zusatzbefund.":"Μορφολογικός δείκτης κινδύνου έναντι πρόσθετου μηχανιστικού ευρήματος.","Komplettes endoskopisches Resektat, gut orientiert.":"Πλήρες ενδοσκοπικό δείγμα εκτομής, καλά προσανατολισμένο.","Primärentscheidung":"Κύρια απόφαση","HE-basierte Bewertung von Budding, LVI, Differenzierung, Invasionstiefe und Resektionsrand.":"H&E-based αξιολόγηση budding, LVI, διαφοροποίησης, βάθους διήθησης και ορίου εκτομής.","Zusatz-IHC":"Πρόσθετη IHC","EMT-Panel kann den Hallmark illustrieren, ist aber nicht erforderlich, um den klinischen Hochrisikobefund zu erkennen.":"Ένα EMT panel μπορεί να απεικονίσει το hallmark αλλά δεν απαιτείται για την αναγνώριση του κλινικού high-risk ευρήματος.","Mechanismusmarker dürfen die standardisierte Morphologie nicht verdrängen.":"Οι μηχανιστικοί δείκτες δεν πρέπει να εκτοπίζουν την τυποποιημένη μορφολογία.","Histologische Invasionsfront / Risikofaktoren":"Ιστολογικό μέτωπο διήθησης / παράγοντες κινδύνου","HE / Invasionsfront":"H&E / μέτωπο διήθησης","Hochgradiges Tumor budding an der tiefen Invasionsfront plus fokale lymphovaskuläre Invasion. Diese histopathologischen Hochrisikofaktoren sind für die Entscheidung nach endoskopischer pT1-Resektion klinisch relevant.":"High-grade tumor budding στο βαθύ μέτωπο διήθησης συν εστιακή λεμφαγγειακή διήθηση. Αυτοί οι ιστοπαθολογικοί high-risk παράγοντες είναι κλινικά σημαντικοί για την απόφαση μετά ενδοσκοπική pT1 εκτομή.","EMT-IHC":"EMT IHC","Buds zeigen fokal reduzierte E-Cadherin-Membranfärbung, Vimentin-Zunahme und veränderte β-Catenin-Lokalisation – mechanistisch vereinbar mit partieller EMT, aber kein eigenständiger validierter Operationsindikator.":"Τα buds δείχνουν εστιακά μειωμένη μεμβρανική χρώση E-cadherin, αύξηση vimentin και αλλοιωμένη εντόπιση β-catenin — μηχανιστικά συμβατά με partial EMT, αλλά όχι ανεξάρτητη επικυρωμένη ένδειξη χειρουργείου.","Breite Tumorgenetik liefert für die unmittelbare pT1-Risikostratifikation keinen Ersatz für die relevanten histopathologischen Invasionsmerkmale.":"Η ευρεία γενετική του όγκου δεν αντικαθιστά τα σχετικά ιστοπαθολογικά χαρακτηριστικά διήθησης για άμεση pT1 stratification κινδύνου.","Resektion":"Εκτομή","Endoskopisch R0.":"Ενδοσκοπικό R0.","Invasionsfront":"Μέτωπο διήθησης","Hochgradiges Tumor budding und fokale Lymphgefäßinvasion.":"High-grade tumor budding και εστιακή λεμφική διήθηση.","Der Fall verbindet Morphologie und Hallmark-Biologie: Tumor budding an der Invasionsfront ist ein sichtbares Korrelat invasiver/plastischer Tumorzellzustände und bei pT1-CRC ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen. EMT-IHC kann die Biologie illustrieren, entscheidet aber nicht über die weitere Operation. Die klinische Konsequenz entsteht aus standardisierten Hochrisikofaktoren wie Budding, LVI, Differenzierung, Tiefe und Resektionsstatus.":"Η περίπτωση συνδέει μορφολογία και hallmark βιολογία: tumor budding στο μέτωπο διήθησης είναι ορατό correlate διηθητικών/πλαστικών καταστάσεων καρκινικών κυττάρων και καθιερωμένος ιστοπαθολογικός παράγοντας κινδύνου λεμφαδενικών μεταστάσεων στο pT1 CRC. EMT IHC μπορεί να απεικονίσει τη βιολογία, αλλά δεν αποφασίζει περαιτέρω χειρουργείο. Η κλινική συνέπεια προκύπτει από τυποποιημένους high-risk παράγοντες όπως budding, LVI, διαφοροποίηση, βάθος και status εκτομής.","Teilbefund: EMT ist biologisch plausibel, aber die klinische Risikoeinschätzung muss an validierten histopathologischen Merkmalen hängen.":"Μερικό αποτέλεσμα: το EMT είναι βιολογικά εύλογο, αλλά η κλινική εκτίμηση κινδύνου πρέπει να βασίζεται σε επικυρωμένα ιστοπαθολογικά χαρακτηριστικά.","Tumor budding als klinisch relevanten Invasionsfront-Befund erkennen":"Αναγνωρίστε tumor budding ως κλινικά σημαντικό εύρημα του μετώπου διήθησης","R0 nicht mit niedrigem Lymphknotenrisiko gleichsetzen":"Μην εξισώνετε R0 με χαμηλό λεμφαδενικό κίνδυνο","EMT als mechanistische Erklärung, nicht als eigenständigen Routine-Selektionsassay einordnen":"Εντάξτε EMT ως μηχανιστική εξήγηση, όχι ως stand-alone routine selection assay","HE-basierte standardisierte Risikofaktoren priorisieren":"Προτεραιοποιήστε τυποποιημένους H&E-based παράγοντες κινδύνου","Falschaussage: ein positives EMT-IHC-Panel ist die Operationsindikation":"Λανθασμένη δήλωση: θετικό EMT IHC panel αποτελεί ένδειξη χειρουργείου","Optimale Lösung: Morphologie zuerst. High-grade budding und LVI machen den pT1-Fall trotz R0 klinisch risikorelevant; EMT-IHC erklärt das Hallmark, ersetzt aber nicht die standardisierte histopathologische Entscheidung.":"Βέλτιστη λύση: πρώτα μορφολογία. High-grade budding και LVI καθιστούν την pT1 περίπτωση κλινικά υψηλού κινδύνου παρά το R0· EMT IHC εξηγεί το hallmark, αλλά δεν αντικαθιστά την τυποποιημένη ιστοπαθολογική απόφαση.","pT1 CRC":"pT1 CRC","Tumor budding":"Tumor budding","Invasion":"Διήθηση","EMT":"EMT","Lymphovascular invasion":"Λεμφαγγειακή διήθηση","Hallmarks":"Hallmarks","Tumor budding: Hallmark im HE statt EMT-Overtesting":"Tumor budding: hallmark ορατό στο H&E αντί για EMT overtesting","GI-Pathologie / Molekularpathologie / MTB":"GI παθολογία / Μοριακή παθολογία / MTB","Tumor budding als morphologisches Korrelat invasiver/plastischer Tumorzellzustände erkennen.":"Αναγνωρίστε tumor budding ως μορφολογικό correlate διηθητικών/πλαστικών καταστάσεων καρκινικών κυττάρων.","Bei pT1-CRC klinisch relevante histopathologische Hochrisikofaktoren priorisieren.":"Προτεραιοποιήστε κλινικά σημαντικούς ιστοπαθολογικούς high-risk παράγοντες στο pT1 CRC.","R0-Resektion von Lymphknotenrisiko unterscheiden.":"Διαχωρίστε R0 εκτομή από λεμφαδενικό κίνδυνο.","EMT-IHC als mechanistische Illustration und nicht als eigenständigen Operationsindikator einordnen.":"Εντάξτε EMT IHC ως μηχανιστική απεικόνιση, όχι ως stand-alone ένδειξη χειρουργείου.","Morphologie direkt mit Hallmark-Biologie und klinischer Konsequenz verbinden.":"Συνδέστε άμεσα τη μορφολογία με hallmark βιολογία και κλινική συνέπεια.","Der Polyp ist komplett raus, der Rand ist frei – eigentlich klingt alles gut. An der tiefen Invasionsfront stehen jedoch zahlreiche einzelne Tumorzellen und kleine Cluster: High-grade tumor budding. Genau dort wird ein abstrakter Hallmark plötzlich klinisch sichtbar.":"Ο πολύποδας έχει αφαιρεθεί πλήρως και το όριο είναι καθαρό — όλα ακούγονται καλά. Ωστόσο στο βαθύ μέτωπο διήθησης υπάρχουν πολλά μεμονωμένα καρκινικά κύτταρα και μικρά clusters: high-grade tumor budding. Ακριβώς εκεί ένα αφηρημένο hallmark γίνεται ξαφνικά κλινικά ορατό.","56-jähriger Patient nach endoskopischer R0-Resektion eines pT1-Sigmakarzinoms. Das Board muss entscheiden, ob wegen histopathologischer Hochrisikofaktoren eine onkologische Nachresektion diskutiert werden sollte. EMT ist die biologische Erklärung, aber nicht der primäre klinische Test.":"Άνδρας 56 ετών μετά ενδοσκοπική R0 εκτομή pT1 καρκινώματος σιγμοειδούς. Το board πρέπει να αποφασίσει αν πρέπει να συζητηθεί ογκολογική επανεκτομή λόγω ιστοπαθολογικών high-risk παραγόντων. Το EMT είναι η βιολογική εξήγηση, αλλά όχι η κύρια κλινική εξέταση.","R0 ist nicht alles":"Το R0 δεν είναι το παν","Lokale Exzision ist vollständig.":"Η τοπική εκτομή είναι πλήρης.","Okkultes Lymphknotenrisiko bleibt eine andere Frage.":"Ο λανθάνων λεμφαδενικός κίνδυνος παραμένει ξεχωριστό ερώτημα.","Budding ist sichtbar":"Το budding είναι ορατό","Einzelzellen/kleine Cluster an der Invasionsfront.":"Μεμονωμένα κύτταρα/μικρά clusters στο μέτωπο διήθησης.","Morphologie kann funktionelle Tumorbiologie verdichten.":"Η μορφολογία μπορεί να συμπυκνώνει λειτουργική βιολογία όγκου.","EMT erklärt, entscheidet aber nicht allein":"Το EMT εξηγεί, αλλά δεν αποφασίζει μόνο του","E-Cadherin/Vimentin/β-Catenin können partielle EMT illustrieren.":"E-cadherin/vimentin/β-catenin μπορούν να απεικονίσουν partial EMT.","Standardisierte Histopathologie trägt die klinische Entscheidung.":"Η τυποποιημένη ιστοπαθολογία καθοδηγεί την κλινική απόφαση.","Resektionsstatus":"Status εκτομής","R0":"R0","high-grade tumor budding + fokale LVI":"High-grade tumor budding + εστιακή LVI","Differenzierung":"Διαφοροποίηση","nicht schlecht differenziert":"Όχι χαμηλής διαφοροποίησης","Komplettes gut orientiertes endoskopisches Resektat.":"Πλήρες, καλά προσανατολισμένο ενδοσκοπικό δείγμα εκτομής.","HE-Reevaluation ist der wichtigste 'Test'.":"Η επανεκτίμηση H&E είναι η σημαντικότερη «εξέταση». ","EMT-IHC verbraucht Schnitte ohne zwingenden Zusatznutzen für die Operationsentscheidung.":"Η EMT IHC καταναλώνει τομές χωρίς επιτακτικό πρόσθετο όφελος για τη χειρουργική απόφαση.","Welche Aussage zu Tumor budding im pT1-CRC ist am treffendsten?":"Ποια δήλωση για tumor budding στο pT1 CRC είναι η ακριβέστερη;","Es ist ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen und muss mit anderen Hochrisikofaktoren integriert werden.":"Είναι καθιερωμένος ιστοπαθολογικός παράγοντας κινδύνου λεμφαδενικών μεταστάσεων και πρέπει να ενσωματώνεται με άλλους high-risk παράγοντες.","Es ist nur ein interessantes Morphologiedetail.":"Είναι μόνο ενδιαφέρουσα μορφολογική λεπτομέρεια.","Es kann nur durch NGS diagnostiziert werden.":"Μπορεί να διαγνωστεί μόνο με NGS.","Es ist synonym mit positivem Resektionsrand.":"Είναι συνώνυμο θετικού ορίου εκτομής.","Budding hat klinische Risikobedeutung.":"Το budding έχει κλινική σημασία κινδύνου.","Was bedeutet R0 hier?":"Τι σημαίνει R0 εδώ;","Die lokale Resektion ist vollständig; das nodale Metastasierungsrisiko wird dadurch nicht automatisch null.":"Η τοπική εκτομή είναι πλήρης· ο κίνδυνος λεμφαδενικών μεταστάσεων δεν γίνεται αυτόματα μηδενικός.","Heilung ist sicher.":"Η ίαση είναι βέβαιη.","Lymphknotenmetastasen sind ausgeschlossen.":"Οι λεμφαδενικές μεταστάσεις αποκλείονται.","EMT ist ausgeschlossen.":"Το EMT αποκλείεται.","Lokaler Randstatus und biologisches Metastasierungsrisiko sind getrennt.":"Το τοπικό status ορίου και ο βιολογικός κίνδυνος μετάστασης είναι ξεχωριστά.","Welche Rolle hat das EMT-IHC-Panel?":"Ποιον ρόλο έχει το EMT IHC panel;","Es kann partielle EMT mechanistisch illustrieren, ist aber kein eigenständiger validierter Operationsindikator.":"Μπορεί να απεικονίσει μηχανιστικά partial EMT, αλλά δεν είναι ανεξάρτητη επικυρωμένη ένδειξη χειρουργείου.","Es ist zwingend vor jeder Nachresektion erforderlich.":"Είναι υποχρεωτικό πριν από κάθε επανεκτομή.","Es ersetzt Tumor budding.":"Αντικαθιστά tumor budding.","Es liefert unmittelbar eine zugelassene Targettherapie.":"Παρέχει άμεσα εγκεκριμένη στοχευμένη θεραπεία.","Mechanismusmarker ≠ klinischer Standard-Risikomarker.":"Μηχανιστικός δείκτης ≠ κλινικός standard δείκτης κινδύνου.","Welche Befunde tragen die klinische Entscheidung primär?":"Ποια ευρήματα καθορίζουν πρωτίστως την κλινική απόφαση;","Budding, LVI, Differenzierung, Invasionstiefe und Resektionsstatus im standardisierten histopathologischen Kontext.":"Budding, LVI, διαφοροποίηση, βάθος διήθησης και status εκτομής στο τυποποιημένο ιστοπαθολογικό πλαίσιο.","Nur E-Cadherin/Vimentin.":"Μόνο E-cadherin/vimentin.","Breites Pan-Cancer-NGS.":"Ευρύ pan-cancer NGS.","PD-L1.":"PD-L1.","Morphologische Risikofaktoren sind hier zentral.":"Οι μορφολογικοί παράγοντες κινδύνου είναι κεντρικοί εδώ.","Leiten Sie vom HE-Befund an der Invasionsfront über die Hallmark-Biologie zur klinischen Konsequenz nach endoskopischer pT1-Resektion ab.":"Συνάγετε την κλινική συνέπεια μετά ενδοσκοπική pT1 εκτομή από το H&E εύρημα στο μέτωπο διήθησης μέσω hallmark βιολογίας.","R0 als lokalen Resektionsstatus anerkennen.":"Αναγνωρίστε R0 ως τοπικό status εκτομής.","High-grade tumor budding erkennen und standardisiert bewerten.":"Αναγνωρίστε και αξιολογήστε τυποποιημένα high-grade tumor budding.","LVI als zusätzlichen Hochrisikofaktor integrieren.":"Ενσωματώστε LVI ως πρόσθετο high-risk παράγοντα.","EMT als mechanistische Erklärung formulieren.":"Διατυπώστε το EMT ως μηχανιστική εξήγηση.","EMT-IHC nicht zur Operationsvoraussetzung machen.":"Μην κάνετε EMT IHC προϋπόθεση για χειρουργείο.","Onkologische Nachresektion wegen kombinierter Hochrisikofaktoren im Board diskutieren.":"Συζητήστε ογκολογική επανεκτομή στο board λόγω συνδυασμένων high-risk παραγόντων.","Auf EMT-IHC vollständig verzichten und die Hallmark-Biologie rein morphologisch erklären – klinisch absolut vertretbar.":"Παραλείψτε πλήρως EMT IHC και εξηγήστε hallmark βιολογία μόνο μορφολογικά — κλινικά απολύτως αποδεκτό.","Bei Grenzfällen zusätzliche pathologische Zweitbegutachtung statt breitem Molekularpanel.":"Σε οριακές περιπτώσεις, χρησιμοποιήστε πρόσθετη παθολογοανατομική επανεκτίμηση αντί για ευρύ μοριακό panel.","R0 = kein Risiko":"R0 = κανένας κίνδυνος","Lymphknotenrisiko ist nicht identisch mit lokalem Randstatus.":"Ο λεμφαδενικός κίνδυνος δεν είναι ταυτόσημος με το τοπικό status ορίου.","EMT-IHC entscheidet":"Η EMT IHC αποφασίζει","Mechanistische Marker ersetzen keine validierte pT1-Risikostratifikation.":"Οι μηχανιστικοί δείκτες δεν αντικαθιστούν την επικυρωμένη pT1 stratification κινδύνου.","Budding nur Forschung":"Budding μόνο για έρευνα","Budding besitzt etablierte prognostische/Risikobedeutung.":"Το budding έχει καθιερωμένη προγνωστική/κινδύνου σημασία.","Der wichtigste Hallmark-Test ist bereits auf dem HE":"Το σημαντικότερο hallmark test βρίσκεται ήδη στην H&E τομή","Das optionale EMT-Panel zeigt erwartbare partielle EMT-Zeichen, ändert aber die klinische Entscheidung nicht. High-grade budding und LVI waren bereits im HE sichtbar und tragen die Konsequenz.":"Το προαιρετικό EMT panel δείχνει αναμενόμενα σημεία partial EMT, αλλά δεν αλλάζει την κλινική απόφαση. High-grade budding και LVI ήταν ήδη ορατά στο H&E και καθορίζουν τη συνέπεια.","Der Fall verbindet Grundlagenbiologie mit Pathologieroutine, ohne Molekulardiagnostik künstlich aufzublähen.":"Η περίπτωση συνδέει τη βασική βιολογία με τη ρουτίνα παθολογίας χωρίς τεχνητή διόγκωση της μοριακής διάγνωσης.","Morphologie → Hallmark → Konsequenz":"Μορφολογία → hallmark → συνέπεια","R0-pT1-CRC, aber high-grade budding + LVI → relevantes nodales Risiko; EMT mechanistisch, nicht als Pflichtassay.":"R0 pT1 CRC, αλλά high-grade budding + LVI → σημαντικός λεμφαδενικός κίνδυνος· EMT μηχανιστικό, όχι υποχρεωτικό assay.","Genau die gewünschte Integrationsleistung.":"Ακριβώς η επιθυμητή ενσωμάτωση.","EMT verstanden, Risiko unscharf":"EMT κατανοητό, κίνδυνος ασαφής","Biologie gut erklärt, aber klinisch relevante Histofaktoren nicht priorisiert.":"Η βιολογία εξηγείται καλά, αλλά οι κλινικά σημαντικοί ιστολογικοί παράγοντες δεν προτεραιοποιούνται.","Zu grundlagenlastig.":"Υπερβολικά επικεντρωμένο στη βασική βιολογία.","R0 = erledigt":"R0 = τελείωσε","Budding/LVI werden trotz freiem Rand ignoriert.":"Budding/LVI αγνοούνται παρά το καθαρό όριο.","Klinische Konsequenz verpasst.":"Χάνεται η κλινική συνέπεια.","Mehrere histologische Hochrisikofaktoren":"Πολλαπλοί ιστολογικοί high-risk παράγοντες","Onkologische Nachresektion mit Lymphknotenbewertung im interdisziplinären Kontext diskutieren.":"Συζητήστε ογκολογική επανεκτομή με λεμφαδενική αξιολόγηση σε διεπιστημονικό πλαίσιο.","Nodales Risiko wird adressiert.":"Ο λεμφαδενικός κίνδυνος αντιμετωπίζεται.","Keine Hochrisikofaktoren":"Χωρίς high-risk παράγοντες","Lokale Strategie nach geltenden Kriterien erwägen.":"Εξετάστε τοπική στρατηγική σύμφωνα με ισχύοντα κριτήρια.","Übertherapie vermeiden.":"Αποφύγετε υπερθεραπεία.","Tumor budding ist ein morphologisches Korrelat von Invasion/plastischen Zellzuständen.":"Tumor budding είναι μορφολογικό correlate διήθησης/πλαστικών κυτταρικών καταστάσεων.","Bei pT1-CRC ist budding ein klinisch relevanter Risikofaktor für Lymphknotenmetastasen.":"Στο pT1 CRC, το budding είναι κλινικά σημαντικός παράγοντας κινδύνου λεμφαδενικών μεταστάσεων.","R0 beantwortet die lokale Resektion, nicht automatisch das nodale Risiko.":"Το R0 απαντά στο τοπικό status εκτομής, όχι αυτόματα στον λεμφαδενικό κίνδυνο.","EMT-IHC kann Mechanismus illustrieren, ist aber kein notwendiger Operationsindikator.":"EMT IHC μπορεί να απεικονίσει τον μηχανισμό, αλλά δεν είναι αναγκαία ένδειξη χειρουργείου.","HE kann funktionelle Tumorbiologie als kumulative Morphologie sichtbar machen.":"Το H&E μπορεί να καταστήσει ορατή τη λειτουργική βιολογία του όγκου ως σωρευτική μορφολογία.","Trotz R0-Resektion zeigen high-grade tumor budding und LVI ein relevantes Lymphknotenrisiko. Tumor budding verbindet die Invasionsfront direkt mit Hallmark-Biologie; EMT-IHC ist optional erklärend, nicht entscheidungsdefinierend.":"Παρά R0 εκτομή, high-grade tumor budding και LVI υποδηλώνουν σημαντικό λεμφαδενικό κίνδυνο. Tumor budding συνδέει άμεσα το μέτωπο διήθησης με hallmark βιολογία· EMT IHC είναι προαιρετική και εξηγητική, όχι καθοριστική της απόφασης.","R0 vs nodales Risiko":"R0 vs λεμφαδενικός κίνδυνος","EMT als Mechanismus":"EMT ως μηχανισμός","Morphologie priorisiert":"Μορφολογία σε προτεραιότητα","Welche HE-Merkmale sind funktionelle 'Fingerabdrücke' von Hallmarks?":"Ποια H&E χαρακτηριστικά είναι λειτουργικά «δακτυλικά αποτυπώματα» hallmarks;","Warum ist partielle EMT biologisch plausibler als ein binärer EMT-Schalter?":"Γιατί το partial EMT είναι βιολογικά πιο εύλογο από έναν δυαδικό EMT switch;","Wo hilft Molekulardiagnostik – und wo macht sie einen guten HE-Befund nur komplizierter?":"Πού βοηθά η μοριακή διάγνωση — και πού απλώς περιπλέκει ένα καλό H&E εύρημα;","high-grade budding trotz R0":"High-grade budding παρά R0","Morphologie kann Hallmarks klinisch relevant abbilden":"Η μορφολογία μπορεί να απεικονίζει hallmarks με κλινικά σημαντικό τρόπο","R0 → Invasionsfront → budding/LVI → Hallmark → klinische Konsequenz":"R0 → μέτωπο διήθησης → budding/LVI → hallmark → κλινική συνέπεια","Coverage-Loch im EGFR-Exon 20: „negativ“ ist hier nicht negativ":"Κενό κάλυψης στο εξόνιο 20 του EGFR: εδώ το «αρνητικό» δεν είναι αρνητικό","Coverage-Loch in therapieentscheid…":"Κενό κάλυψης σε εξόνιο καθοριστικό για τη θεραπεία…","58-jährige Nie-Raucherin mit metastasiertem pulmonalem Adenokarzinom. Das DNA-Panel wird als „kein therapierbarer Treiber nachweisbar“ zusammengefasst.":"58χρονη μη καπνίστρια με μεταστατικό πνευμονικό αδενοκαρκίνωμα. Το DNA panel συνοψίζεται ως «δεν ανιχνεύθηκε θεραπευτικά αξιοποιήσιμος driver». ","Darf der Fall als molekular negativ abgeschlossen werden, obwohl der Coverage-Report für EGFR-Exon 20 unterhalb des laborintern validierten Mindestkriteriums liegt?":"Μπορεί η περίπτωση να κλείσει ως μοριακά αρνητική, παρότι η αναφορά κάλυψης για το εξόνιο 20 του EGFR είναι κάτω από το εσωτερικά επικυρωμένο ελάχιστο κριτήριο του εργαστηρίου;","Die Erstlinienentscheidung soll in vier Tagen fallen.":"Η απόφαση για τη θεραπεία πρώτης γραμμής πρέπει να ληφθεί σε τέσσερις ημέρες.","ECOG 1, Leber- und Knochenmetastasen; ausreichend Zeit für eine gezielte Nachklärung, aber nicht für beliebig viele Wiederholungen.":"ECOG 1, ηπατικές και οστικές μεταστάσεις· υπάρχει αρκετός χρόνος για στοχευμένη διευκρίνιση, αλλά όχι για απεριόριστες επαναλήψεις.","KRAS, BRAF, MET-Exon-14 und ERBB2 ohne pathogene Alteration; Fusionstestung separat vorgesehen.":"KRAS, BRAF, εξόνιο 14 του MET και ERBB2 χωρίς παθογόνο αλλοίωση· ο έλεγχος συντήξεων έχει προγραμματιστεί ξεχωριστά.","QC-Hinweis":"Σημείωση QC","Median-Coverage des Panels ca. 780×, EGFR-Exon 20 jedoch nur 24×; laborintern validiertes Mindestkriterium für einen negativen Call wird dort nicht erreicht.":"Η διάμεση κάλυψη του panel είναι περίπου 780×, αλλά το εξόνιο 20 του EGFR μόλις 24×· εκεί δεν πληρούται το εσωτερικά επικυρωμένο ελάχιστο κριτήριο του εργαστηρίου για αρνητικό call.","Ein global „guter“ Run wird mit vollständiger lokaler Aussagefähigkeit gleichgesetzt.":"Ένα συνολικά «καλό» run εξισώνεται με πλήρη τοπική αξιολογησιμότητα.","Adenokarzinom der Lunge, TTF1/Napsin A positiv.":"Αδενοκαρκίνωμα πνεύμονα, TTF1/Napsin A θετικά.","ca. 45 %.":"περ. 45%.","Ist das Exon tatsächlich wildtyp oder nur unzureichend untersucht?":"Είναι το εξόνιο πραγματικά wild type ή απλώς ανεπαρκώς διερευνημένο;","Hinweis":"Σημείωση","„Nicht nachgewiesen“ und „nicht ausreichend geprüft“ sind unterschiedliche Aussagen.":"Το «δεν ανιχνεύθηκε» και το «δεν αξιολογήθηκε επαρκώς» είναι διαφορετικές δηλώσεις.","FFPE-Lebermetastase, Restblock vorhanden.":"FFPE ηπατική μετάσταση, διαθέσιμο υπόλοιπο block.","Menge ausreichend; übrige Targets technisch unauffällig.":"Επαρκής ποσότητα· οι υπόλοιποι στόχοι είναι τεχνικά χωρίς αξιοσημείωτα ευρήματα.","Coverage":"Κάλυψη","isolierter Dropout in EGFR-Exon 20.":"μεμονωμένο dropout στο εξόνιο 20 του EGFR.","Ressourcen":"Πόροι","Eine gezielte orthogonale Abklärung ist schneller und materialsparender als ein blindes komplettes Re-Panel.":"Μια στοχευμένη ορθογώνια διευκρίνιση είναι ταχύτερη και εξοικονομεί περισσότερο υλικό από μια τυφλή επανάληψη ολόκληρου του panel.","Coverage-/QC-Review":"Έλεγχος coverage/QC","Nicht ausreichend abgedecktes Exon gezielt klären":"Στοχευμένη διευκρίνιση του ανεπαρκώς καλυμμένου εξονίου","Coverage-Review":"Έλεγχος κάλυψης","Der Run ist global valide, aber EGFR-Exon 20 unterschreitet das laborintern validierte Mindestkriterium. Für dieses Exon ist ein negativer Befund nicht belastbar.":"Το run είναι συνολικά έγκυρο, αλλά το εξόνιο 20 του EGFR βρίσκεται κάτω από το εσωτερικά επικυρωμένο ελάχιστο κριτήριο του εργαστηρίου. Ένα αρνητικό αποτέλεσμα για αυτό το εξόνιο δεν είναι αξιόπιστο.","Orthogonale Abklärung":"Ορθογώνια διευκρίνιση","Eine unabhängig amplifizierte, validierte Zielmethode weist eine EGFR-Exon-20-Insertion nach. Der ursprüngliche „negative“ Panelbefund war an dieser Stelle nicht aussagefähig.":"Μια επικυρωμένη στοχευμένη μέθοδος με ανεξάρτητη ενίσχυση ανιχνεύει εισαγωγή στο εξόνιο 20 του EGFR. Το αρχικό «αρνητικό» αποτέλεσμα του panel δεν ήταν πληροφοριακό σε αυτή τη θέση.","NGS-Wiederholung":"Επανάληψη NGS","Die Wiederholung mit demselben Assay zeigt erneut den lokalen Dropout. Ein identisches technisches Design löst den systematischen Coverage-Ausfall nicht zuverlässig.":"Η επανάληψη του ίδιου assay δείχνει ξανά το τοπικό dropout. Ένας πανομοιότυπος τεχνικός σχεδιασμός δεν επιλύει αξιόπιστα τη συστηματική αποτυχία κάλυψης.","Breites Re-Panel":"Ευρύ re-panel","Mehr Panelbreite beantwortet das lokale Coverage-Problem nicht automatisch; entscheidend ist die validierte Abdeckung des fraglichen Exons.":"Μεγαλύτερο εύρος panel δεν λύνει αυτόματα ένα τοπικό πρόβλημα κάλυψης· καθοριστική είναι η επικυρωμένη κάλυψη του συγκεκριμένου εξονίου.","Global gute Sequenzierqualität; isolierter lokaler Coverage-Ausfall in einem therapieentscheidenden Bereich.":"Συνολικά καλή ποιότητα αλληλούχησης· μεμονωμένη τοπική αποτυχία κάλυψης σε περιοχή καθοριστική για τη θεραπεία.","Ein negativer Call ist nur für ausreichend validiert untersuchte Zielregionen zulässig.":"Αρνητικό call επιτρέπεται μόνο για περιοχές-στόχους που έχουν εξεταστεί επαρκώς υπό επικυρωμένες συνθήκες.","Der NGS-Run ist nicht insgesamt ungültig, aber EGFR-Exon 20 ist wegen lokaler Unterabdeckung nicht sicher negativ befundbar. Die Limitation muss explizit berichtet und die Zielregion gezielt nachuntersucht werden. Eine orthogonale Methode weist schließlich eine EGFR-Exon-20-Insertion nach.":"Το NGS run δεν είναι συνολικά άκυρο, αλλά το εξόνιο 20 του EGFR δεν μπορεί να αναφερθεί αξιόπιστα ως αρνητικό λόγω τοπικής υποκάλυψης. Ο περιορισμός πρέπει να αναφερθεί ρητά και η περιοχή-στόχος να επανελεγχθεί ειδικά. Μια ορθογώνια μέθοδος ανιχνεύει τελικά εισαγωγή στο εξόνιο 20 του EGFR.","Teilbefund: Das Panel darf nicht pauschal als vollständig negativ zusammengefasst werden, solange die therapieentscheidende Zielregion das validierte Coverage-Kriterium nicht erfüllt.":"Μερική αναφορά: το panel δεν πρέπει να συνοψίζεται ως πλήρως αρνητικό όσο η θεραπευτικά καθοριστική περιοχή-στόχος δεν πληροί το επικυρωμένο κριτήριο κάλυψης.","lokale Coverage statt nur Mittelwert prüfen":"ελέγξτε την τοπική κάλυψη, όχι μόνο τον μέσο όρο","„nicht nachgewiesen“ von „nicht ausreichend untersucht“ trennen":"διαχωρίστε το «δεν ανιχνεύθηκε» από το «δεν αξιολογήθηκε επαρκώς»","gezielte Nachtestung definieren":"καθορίστε στοχευμένο επανέλεγχο","Falschaussage: hohe Median-Coverage macht jede Zielregion sicher negativ":"Λανθασμένη δήλωση: υψηλή διάμεση κάλυψη καθιστά κάθε περιοχή-στόχο αξιόπιστα αρνητική","Optimale Lösung: lokalen Coverage-Defekt erkennen, die Aussage im Befund begrenzen und das betroffene Exon mit einer unabhängigen validierten Methode schließen.":"Βέλτιστη λύση: αναγνωρίστε το τοπικό ελάττωμα κάλυψης, περιορίστε τη διατύπωση στην αναφορά και κλείστε το κενό για το επηρεαζόμενο εξόνιο με ανεξάρτητη επικυρωμένη μέθοδο.","MTB-LAB":"MTB-LAB","Das Loch im „negativen“ Panel":"Το κενό στο «αρνητικό» panel","Molekularpathologie / NGS-Freigabe / MTB":"Μοριακή παθολογία / έγκριση NGS / MTB","Coverage auf Zielregionsebene statt nur als Run-Mittelwert bewerten.":"Αξιολογήστε την κάλυψη σε επίπεδο περιοχής-στόχου και όχι μόνο ως μέσο όρο του run.","Nicht nachgewiesen von nicht ausreichend untersucht unterscheiden.":"Διαχωρίστε το δεν ανιχνεύθηκε από το δεν αξιολογήθηκε επαρκώς.","Bei lokalem Coverage-Ausfall Limitation und gezielte Nachtestung formulieren.":"Σε τοπική αποτυχία κάλυψης, διατυπώστε τον περιορισμό και τον στοχευμένο επανέλεγχο.","Wiederholung desselben Assays von einer methodisch unabhängigen Bestätigung unterscheiden.":"Διαχωρίστε την επανάληψη του ίδιου assay από μεθοδολογικά ανεξάρτητη επιβεβαίωση.","Der Bericht sagt „kein therapierbarer Treiber“. Im QC-Tab fällt aber eine einzige rote Zeile auf: EGFR-Exon 20, 24×. Der Rest des Panels liegt bei mehreren hundert Reads. Genau dort darf aus „nichts gesehen“ kein „sicher nicht vorhanden“ werden.":"Η αναφορά λέει «κανένας θεραπευτικά αξιοποιήσιμος driver». Στην καρτέλα QC όμως ξεχωρίζει μία κόκκινη γραμμή: εξόνιο 20 του EGFR, 24×. Το υπόλοιπο panel έχει αρκετές εκατοντάδες reads. Ακριβώς εδώ το «δεν είδαμε τίποτα» δεν πρέπει να γίνει «σίγουρα δεν υπάρχει». ","58-jährige Nie-Raucherin mit metastasiertem Lungenadenokarzinom. Das Panel ist global technisch gut, aber eine therapieentscheidende Zielregion unterschreitet das validierte Mindestkriterium. Das Board muss entscheiden, ob limitiert berichtet, wiederholt oder orthogonal geschlossen wird.":"58χρονη μη καπνίστρια με μεταστατικό αδενοκαρκίνωμα πνεύμονα. Το panel είναι συνολικά τεχνικά καλό, αλλά μια θεραπευτικά καθοριστική περιοχή-στόχος βρίσκεται κάτω από το επικυρωμένο ελάχιστο κριτήριο. Το board πρέπει να αποφασίσει αν θα εκδώσει περιορισμένη αναφορά, θα επαναλάβει το τεστ ή θα κλείσει το κενό ορθογώνια.","Global gut, lokal schlecht":"Συνολικά καλό, τοπικά ανεπαρκές","Median-Coverage ca. 780×, EGFR-Exon 20 nur 24×.":"Διάμεση κάλυψη περ. 780×, εξόνιο 20 EGFR μόνο 24×.","Run-QC ersetzt keine Target-QC.":"Το QC του run δεν αντικαθιστά το QC του στόχου.","Sprache ist Diagnostik":"Η γλώσσα είναι μέρος της διάγνωσης","„Keine Mutation nachweisbar“ behauptet mehr als „Region nicht ausreichend abgedeckt“.":"Το «δεν ανιχνεύθηκε μετάλλαξη» δηλώνει περισσότερα από το «η περιοχή δεν καλύφθηκε επαρκώς». ","Befundformulierung muss die analytische Aussagegrenze spiegeln.":"Η διατύπωση της αναφοράς πρέπει να αντικατοπτρίζει τα αναλυτικά όρια της ερμηνείας.","Wiederholung ist nicht automatisch unabhängig":"Η επανάληψη δεν είναι αυτομάτως ανεξάρτητη","Ein identisches Assaydesign kann denselben Dropout reproduzieren.":"Ένας πανομοιότυπος σχεδιασμός assay μπορεί να αναπαράγει το ίδιο dropout.","Orthogonale Testung kann systematische Assaygrenzen besser adressieren.":"Ο ορθογώνιος έλεγχος μπορεί να αντιμετωπίσει καλύτερα συστηματικούς περιορισμούς του assay.","ca. 45 %":"περ. 45 %","Panel-QC":"QC panel","global valide":"συνολικά έγκυρο","Lokale QC":"Τοπικό QC","EGFR-Exon 20 unter laborintern validierter Mindest-Coverage":"Εξόνιο 20 EGFR κάτω από την ελάχιστη κάλυψη που έχει επικυρωθεί από το εργαστήριο","Restmaterial vorhanden, aber nicht unbegrenzt.":"Υπάρχει υπόλοιπο υλικό, αλλά όχι απεριόριστο.","Zeitkritische Therapieentscheidung.":"Χρονικά κρίσιμη θεραπευτική απόφαση.","Der lokale Coverage-Grenzwert ist assay- und laborvalidiert; es wird kein universeller Zahlenwert postuliert.":"Το τοπικό όριο κάλυψης είναι επικυρωμένο για το assay και το εργαστήριο· δεν προτείνεται καθολική αριθμητική τιμή.","Welche Aussage ist bei hoher Median-Coverage, aber unzureichender Coverage eines therapieentscheidenden Exons korrekt?":"Ποια δήλωση είναι σωστή όταν η διάμεση κάλυψη είναι υψηλή αλλά η κάλυψη ενός θεραπευτικά καθοριστικού εξονίου είναι ανεπαρκής;","Der Run kann global valide sein, während dieses Exon nicht sicher negativ befundbar ist.":"Το run μπορεί να είναι συνολικά έγκυρο, ενώ αυτό το εξόνιο δεν μπορεί να αναφερθεί αξιόπιστα ως αρνητικό.","Hohe Median-Coverage macht alle Exons sicher negativ.":"Η υψηλή διάμεση κάλυψη καθιστά όλα τα εξόνια αξιόπιστα αρνητικά.","Der gesamte Run ist zwingend ungültig.":"Ολόκληρο το run είναι υποχρεωτικά άκυρο.","Coverage ist nur für Forschungsdaten relevant.":"Η κάλυψη έχει σημασία μόνο για ερευνητικά δεδομένα.","Aussagefähigkeit wird zielregionsbezogen bewertet.":"Η αξιολογησιμότητα εκτιμάται σε επίπεδο περιοχής-στόχου.","Wie sollte die Limitation berichtet werden?":"Πώς πρέπει να αναφερθεί ο περιορισμός;","Die betroffene Region ausdrücklich als nicht ausreichend beurteilt kennzeichnen und Nachtestung empfehlen.":"Χαρακτηρίστε ρητά την επηρεαζόμενη περιοχή ως ανεπαρκώς αξιολογημένη και συστήστε επανέλεγχο.","Gesamtbefund schlicht „negativ“ nennen.":"Χαρακτηρίστε απλώς το συνολικό αποτέλεσμα ως «αρνητικό». ","Coverage nur intern dokumentieren.":"Καταγράψτε την κάλυψη μόνο εσωτερικά.","Direkt eine Therapie ausschließen.":"Αποκλείστε άμεσα μια θεραπευτική επιλογή.","Die klinische Aussage darf die analytische Leistung nicht überschreiten.":"Η κλινική δήλωση δεν πρέπει να υπερβαίνει την αναλυτική απόδοση.","Was ist bei einem reproduzierbaren lokalen Assay-Dropout besonders sinnvoll?":"Τι είναι ιδιαίτερα κατάλληλο σε ένα αναπαραγώγιμο τοπικό dropout του assay;","Eine unabhängig validierte Methode für die Zielregion einsetzen.":"Χρησιμοποιήστε ανεξάρτητα επικυρωμένη μέθοδο για την περιοχή-στόχο.","Den identischen Assay beliebig oft wiederholen.":"Επαναλάβετε το ίδιο assay όσες φορές θέλετε.","Nur ein größeres Panel bestellen, ohne die Zielabdeckung zu prüfen.":"Παραγγείλετε μόνο μεγαλύτερο panel χωρίς να ελέγξετε την κάλυψη του στόχου.","Keine weitere Abklärung.":"Καμία περαιτέρω διευκρίνιση.","Eine methodisch unabhängige Lösung adressiert systematische Grenzen besser.":"Μια μεθοδολογικά ανεξάρτητη λύση αντιμετωπίζει καλύτερα τους συστηματικούς περιορισμούς.","Die orthogonale Methode weist eine EGFR-Exon-20-Insertion nach. Was war der ursprüngliche Fehler?":"Η ορθογώνια μέθοδος ανιχνεύει εισαγωγή στο εξόνιο 20 του EGFR. Ποιο ήταν το αρχικό σφάλμα;","Ein nicht ausreichend untersuchter Bereich wurde wie ein sicher negativer Bereich behandelt.":"Μια ανεπαρκώς εξετασμένη περιοχή αντιμετωπίστηκε ως αξιόπιστα αρνητική.","Der gesamte NGS-Run war zwingend wertlos.":"Ολόκληρο το NGS run ήταν υποχρεωτικά άχρηστο.","Die Histologie war falsch.":"Η ιστολογία ήταν λανθασμένη.","Es wurde eine Keimbahnvariante übersehen.":"Παραβλέφθηκε παραλλαγή βλαστικής σειράς.","Der Fehler lag in der Reichweite der Negativaussage.":"Το σφάλμα βρισκόταν στην εμβέλεια της αρνητικής δήλωσης.","Entscheiden Sie, wie der Panelbefund freigegeben wird und wie die offene Zielregion methodisch geschlossen wird.":"Αποφασίστε πώς θα εγκριθεί το αποτέλεσμα του panel και πώς θα κλείσει μεθοδολογικά η ανοιχτή περιοχή-στόχος.","Coverage-Report auf therapieentscheidende Regionen prüfen.":"Ελέγξτε την αναφορά κάλυψης για θεραπευτικά καθοριστικές περιοχές.","Lokale Limitation explizit formulieren.":"Διατυπώστε ρητά τον τοπικό περιορισμό.","Nicht den gesamten Run verwerfen, wenn der Rest valide ist.":"Μην απορρίπτετε ολόκληρο το run αν το υπόλοιπο είναι έγκυρο.","Gezielte orthogonale oder technisch geeignete Wiederholungsstrategie wählen.":"Επιλέξτε στοχευμένη ορθογώνια ή τεχνικά κατάλληλη στρατηγική επανάληψης.","Endbefund nach Nachtestung aktualisieren.":"Ενημερώστε την τελική αναφορά μετά τον επανέλεγχο.","Wiederholung des Panels kann vertretbar sein, wenn die Ursache plausibel zufällig/librarybezogen ist und das Wiederholungsdesign die Zielregion zuverlässig abdeckt.":"Η επανάληψη του panel μπορεί να είναι εύλογη αν η αιτία είναι πιθανώς τυχαία/σχετιζόμενη με τη library και ο σχεδιασμός της επανάληψης καλύπτει αξιόπιστα την περιοχή-στόχο.","„Panel negativ“ trotz Coverage-Loch":"«Αρνητικό panel» παρά το κενό κάλυψης","Überdehnt die analytische Aussage.":"Υπερεκτείνει την αναλυτική δήλωση.","Run komplett verwerfen":"Απόρριψη ολόκληρου του run","Ignoriert, dass die übrigen Regionen valide sein können.":"Αγνοεί ότι οι υπόλοιπες περιοχές μπορεί να είναι έγκυρες.","Blind identisch wiederholen":"Τυφλή πανομοιότυπη επανάληψη","Kann systematische Dropouts reproduzieren.":"Μπορεί να αναπαράγει συστηματικά dropouts.","Die rote Zeile war der eigentliche Befund":"Η κόκκινη γραμμή ήταν το πραγματικό εύρημα","Die gezielte unabhängige Nachtestung weist eine EGFR-Exon-20-Insertion nach.":"Ο στοχευμένος ανεξάρτητος επανέλεγχος ανιχνεύει εισαγωγή στο εξόνιο 20 του EGFR.","Der Fall zeigt, dass analytische Nichtbeurteilbarkeit klinisch relevanter sein kann als ein langer negativer Variantenbericht.":"Η περίπτωση δείχνει ότι η αναλυτική μη αξιολογησιμότητα μπορεί να είναι κλινικά πιο σημαντική από μια μακρά αρνητική αναφορά παραλλαγών.","Limitiert + gezielt geschlossen":"Περιορισμένο + στοχευμένα διευκρινισμένο","Lokale Limitation erkannt, orthogonal nachgetestet, relevante Alteration gefunden.":"Αναγνωρίστηκε τοπικός περιορισμός, έγινε ορθογώνιος επανέλεγχος και βρέθηκε σχετική αλλοίωση.","Vollständige analytische und klinische Einordnung.":"Πλήρης αναλυτική και κλινική ερμηνεία.","Falsch-negativ freigegeben":"Εγκρίθηκε ως ψευδώς αρνητικό","Coverage-Loch wird ignoriert und die Region als negativ berichtet.":"Το κενό κάλυψης αγνοείται και η περιοχή αναφέρεται ως αρνητική.","Kritischer Scope-Fehler.":"Κρίσιμο σφάλμα εμβέλειας.","Ganzer Run verworfen":"Απόρριψη ολόκληρου του run","Valide übrige Ergebnisse werden unnötig wiederholt.":"Άλλα έγκυρα αποτελέσματα επαναλαμβάνονται άσκοπα.","Unnötiger Material-/TAT-Verlust.":"Άσκοπη απώλεια υλικού/TAT.","Coverage unter validiertem Kriterium":"Κάλυψη κάτω από το επικυρωμένο κριτήριο","Zielregion als nicht sicher beurteilbar kennzeichnen":"Χαρακτηρίστε την περιοχή-στόχο ως μη αξιόπιστα αξιολογήσιμη","Nachtestung erforderlich, wenn klinisch relevant.":"Απαιτείται επανέλεγχος εφόσον είναι κλινικά σχετικό.","Coverage ist lokal.":"Η κάλυψη είναι τοπική.","Negativbefunde brauchen nachgewiesene analytische Aussagefähigkeit.":"Τα αρνητικά ευρήματα απαιτούν αποδεδειγμένη αναλυτική αξιολογησιμότητα.","Limitationen gehören in die klinische Kernaussage, nicht nur in interne QC.":"Οι περιορισμοί ανήκουν στην κεντρική κλινική δήλωση, όχι μόνο στο εσωτερικό QC.","Der Run bleibt für ausreichend abgedeckte Regionen valide. EGFR-Exon 20 ist nicht sicher negativ befundbar und muss explizit limitiert sowie gezielt nachuntersucht werden; eine unabhängige Methode schließt die diagnostische Lücke.":"Το run παραμένει έγκυρο για τις επαρκώς καλυμμένες περιοχές. Το εξόνιο 20 του EGFR δεν μπορεί να αναφερθεί αξιόπιστα ως αρνητικό και πρέπει να περιοριστεί ρητά και να επανελεγχθεί ειδικά· μια ανεξάρτητη μέθοδος κλείνει το διαγνωστικό κενό.","Target-spezifische QC":"QC ειδικό για τον στόχο","Befundsprache":"Γλώσσα αναφοράς","Nachteststrategie":"Στρατηγική επανελέγχου","Wann reicht eine NGS-Wiederholung?":"Πότε αρκεί η επανάληψη NGS;","Welche Coverage-Metriken müssen im Labor validiert sein?":"Ποιες μετρικές κάλυψης πρέπει να επικυρωθούν στο εργαστήριο;","Wie formuliert man Negativbefunde bei partieller Nichtbeurteilbarkeit?":"Πώς διατυπώνονται τα αρνητικά ευρήματα όταν μέρος του assay δεν είναι αξιολογήσιμο;","Twist: relevanter Befund liegt in der QC, nicht in der Variantenliste":"Twist: το σχετικό εύρημα βρίσκεται στο QC, όχι στη λίστα παραλλαγών","Kernfehler: nicht ausreichend untersucht ≠ negativ":"Κεντρικό σφάλμα: ανεπαρκώς αξιολογημένο ≠ αρνητικό","Referenzpfad: Coverage prüfen → limitieren → gezielt schließen":"Διαδρομή αναφοράς: έλεγχος κάλυψης → διατύπωση περιορισμού → στοχευμένο κλείσιμο κενού","1,4 % EGFR-T790M im FFPE: Resistenzmutation oder Desaminierungsartefakt?":"EGFR T790M 1,4 % σε FFPE: μετάλλαξη αντοχής ή artifact απαμίνωσης;","FFPE-C>T-Artefakt bei niedriger VA…":"FFPE C>T artifact σε χαμηλό VAF…","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress unter zielgerichteter Therapie. In einer kleinen FFPE-Rebiopsie wird zusätzlich EGFR p.T790M mit 1,4 % VAF gemeldet.":"67χρονος ασθενής με EGFR-mutant NSCLC και πρόοδο υπό στοχευμένη θεραπεία. Σε μικρή FFPE επαναβιοψία αναφέρεται επιπλέον EGFR p.T790M με VAF 1,4 %.","Ist die niedrigfrequente C>T-Variante als echte Resistenzsubpopulation belastbar oder zunächst artefaktverdächtig?":"Είναι η χαμηλής συχνότητας C>T παραλλαγή αξιόπιστη ως πραγματικός ανθεκτικός υποπληθυσμός ή πρέπει αρχικά να θεωρηθεί ύποπτη για artifact;","Therapiewechsel soll kurzfristig festgelegt werden.":"Η αλλαγή θεραπείας πρέπει να αποφασιστεί σύντομα.","Primärtreiber":"Πρωτογενής driver","Bekannte klonale EGFR-aktivierende Mutation mit hoher VAF wird in der Rebiopsie erneut nachgewiesen.":"Η γνωστή κλωνική ενεργοποιητική μετάλλαξη EGFR με υψηλό VAF ανιχνεύεται ξανά στην επαναβιοψία.","Neue Variante":"Νέα παραλλαγή","EGFR p.T790M, 1,4 % VAF, nur knapp oberhalb der technischen Reporting-Grenze.":"EGFR p.T790M, VAF 1,4 %, μόλις πάνω από το τεχνικό όριο αναφοράς.","Kleine Biopsie, lange Formalinfixierung; DNA zeigt deutliche Fragmentierung.":"Μικρή βιοψία, παρατεταμένη μονιμοποίηση σε φορμόλη· το DNA εμφανίζει έντονο κατακερματισμό.","Actionability des Gens wird mit analytischer Validität des einzelnen Calls verwechselt.":"Η actionability του γονιδίου συγχέεται με την αναλυτική εγκυρότητα του συγκεκριμένου call.","Vitales Adenokarzinom, Tumoranteil ca. 30 %.":"Βιώσιμο αδενοκαρκίνωμα, περιεκτικότητα όγκου περ. 30 %.","Sequenzdaten":"Δεδομένα αλληλούχησης","T790M vorwiegend in einem Strang-/Endkontext, niedrige Molekülzahl; mehrere weitere sehr niedrige C>T/G>A-Ereignisse.":"Το T790M κυρίως σε strand/end-context, χαμηλός αριθμός μορίων· αρκετά επιπλέον πολύ χαμηλού επιπέδου συμβάντα C>T/G>A.","Echte Subklonmutation oder FFPE-bedingte Cytosindesaminierung?":"Πραγματική υποκλωνική μετάλλαξη ή αποαμίνωση κυτοσίνης σχετιζόμενη με FFPE;","Ein klinisch attraktiver Call verdient nicht weniger, sondern mehr QC.":"Ένα κλινικά ελκυστικό call απαιτεί περισσότερο QC, όχι λιγότερο.","FFPE-Stanzbiopsie, nur wenige Restrollen.":"FFPE core biopsy, με διαθέσιμες μόνο λίγες υπολειπόμενες τομές.","stark fragmentiert.":"έντονα κατακερματισμένο.","Alternative":"Εναλλακτική","zweite Extraktion aus tieferen Schnitten möglich.":"είναι δυνατή δεύτερη εκχύλιση από βαθύτερες τομές.","Orthogonale Bestätigung gezielt möglich.":"Είναι δυνατή στοχευμένη ορθογώνια επιβεβαίωση.","FFPE-Artefaktprüfung":"Έλεγχος τεχνουργημάτων FFPE","Niedrigfrequenten klinisch relevanten Call bestätigen":"Επιβεβαίωση κλινικά σχετικού call χαμηλής συχνότητας","Artefaktreview":"Ανασκόπηση τεχνουργημάτων","Der Call zeigt typische Warnsignale: sehr niedrige VAF, geringe unabhängige Molekülzahl, ungünstiger Strang-/Read-End-Kontext und zusätzliche niedrigfrequente C>T/G>A-Ereignisse im stark fragmentierten FFPE-Material.":"Το call εμφανίζει τυπικά προειδοποιητικά σημεία: πολύ χαμηλό VAF, λίγα ανεξάρτητα μόρια, δυσμενές strand/read-end context και πρόσθετα C>T/G>A συμβάντα χαμηλής συχνότητας σε έντονα κατακερματισμένο FFPE υλικό.","Orthogonale Bestätigung":"Ορθογώνια επιβεβαίωση","In einer unabhängigen Extraktion und orthogonalen Zielmethode ist p.T790M nicht reproduzierbar, während die bekannte klonale EGFR-Mutation stabil nachweisbar bleibt. Gesamtbild spricht für FFPE-Artefakt.":"Σε ανεξάρτητη εκχύλιση και ορθογώνια στοχευμένη μέθοδο, το p.T790M δεν αναπαράγεται, ενώ η γνωστή κλωνική μετάλλαξη EGFR παραμένει σταθερά ανιχνεύσιμη. Συνολικά, το πρότυπο συνηγορεί υπέρ FFPE τεχνουργήματος.","Mehr Sequenzierbreite ersetzt die gezielte analytische Prüfung des grenzwertigen Calls nicht.":"Η μεγαλύτερη ευρύτητα αλληλούχησης δεν υποκαθιστά τη στοχευμένη αναλυτική αξιολόγηση του οριακού call.","Stark fragmentierte FFPE-DNA mit erhöhtem Risiko niedrigfrequenter Desaminierungsartefakte.":"Έντονα κατακερματισμένο FFPE DNA με αυξημένο κίνδυνο τεχνουργημάτων αποαμίνωσης χαμηλής συχνότητας.","Niedrige VAF allein beweist weder Artefakt noch Subklon; Muster, Reproduzierbarkeit und Assay-QC entscheiden.":"Το χαμηλό VAF από μόνο του δεν αποδεικνύει ούτε τεχνούργημα ούτε υποκλώνο· καθοριστικά είναι το πρότυπο, η αναπαραγωγιμότητα και το QC της δοκιμασίας.","Die klinisch relevante C>T-Variante liegt in einem stark artefaktanfälligen FFPE-Kontext und ist nicht unabhängig reproduzierbar. Sie darf daher nicht als gesicherte Resistenzmutation berichtet werden; die bekannte klonale EGFR-Alteration bleibt dagegen robust nachweisbar.":"Η κλινικά σχετική παραλλαγή C>T βρίσκεται σε FFPE πλαίσιο με υψηλό κίνδυνο τεχνουργήματος και δεν αναπαράγεται ανεξάρτητα. Επομένως δεν πρέπει να αναφερθεί ως επιβεβαιωμένη μετάλλαξη αντοχής· αντίθετα, η γνωστή κλωνική αλλοίωση EGFR παραμένει ισχυρά ανιχνεύσιμη.","Teilbefund: Eine niedrigfrequente C>T-Variante in stark geschädigter FFPE-DNA muss vor therapeutischer Interpretation auf Artefaktmuster und Reproduzierbarkeit geprüft werden.":"Μερικό αποτέλεσμα: παραλλαγή C>T χαμηλής συχνότητας σε σοβαρά κατεστραμμένο FFPE DNA πρέπει να αξιολογηθεί για πρότυπο τεχνουργήματος και αναπαραγωγιμότητα πριν από θεραπευτική ερμηνεία.","Desaminierungsartefakte als Differenzialdiagnose nennen":"Αναφορά τεχνουργημάτων αποαμίνωσης ως διαφορικής εξήγησης","VAF nicht isoliert interpretieren":"Μην ερμηνεύετε το VAF απομονωμένα","klinisch relevanten Low-VAF-Call unabhängig bestätigen":"Ανεξάρτητη επιβεβαίωση κλινικά σχετικού call χαμηλού VAF","Falschaussage: therapierbares Gen macht jeden Low-VAF-Call automatisch echt":"Λανθασμένη δήλωση: ένα actionable γονίδιο καθιστά αυτόματα πραγματικό κάθε call χαμηλού VAF","Optimale Lösung: Low-VAF-C>T-Call im FFPE-Kontext kritisch prüfen, technische Artefaktmerkmale berücksichtigen und vor Therapieableitung unabhängig bestätigen.":"Βέλτιστη λύση: κριτική αξιολόγηση του C>T call χαμηλού VAF στο FFPE πλαίσιο, συνεκτίμηση τεχνικών χαρακτηριστικών τεχνουργήματος και ανεξάρτητη επιβεβαίωση πριν από θεραπευτικά συμπεράσματα.","FFPE":"FFPE","Artefakt":"Τεχνούργημα","Low VAF":"Χαμηλό VAF","Der attraktive 1,4-%-Call":"Το ελκυστικό call του 1,4%","Molekularpathologie / NGS-QC / MTB":"Μοριακή Παθολογία / NGS QC / MTB","FFPE-bedingte C>T/G>A-Artefakte als analytische Differenzialdiagnose erkennen.":"Αναγνώριση FFPE-σχετιζόμενων C>T/G>A τεχνουργημάτων ως αναλυτικής διαφορικής διάγνωσης.","VAF, Molekülzahl, Strang-/Read-Kontext und Reproduzierbarkeit gemeinsam bewerten.":"Συνεκτίμηση VAF, αριθμού μορίων, strand/read context και αναπαραγωγιμότητας.","Klinische Relevanz nicht mit analytischer Validität verwechseln.":"Μη συγχέετε την κλινική σημασία με την αναλυτική εγκυρότητα.","Low-VAF-Calls vor weitreichender Therapieableitung angemessen bestätigen.":"Κατάλληλη επιβεβαίωση call χαμηλού VAF πριν από θεραπευτικές αποφάσεις μεγάλης συνέπειας.","Auf dem Variantenboard leuchtet EGFR p.T790M. VAF 1,4 %. Klinisch wäre der Befund wichtig – analytisch sieht er aber genau so aus, wie ein alter FFPE-Block Probleme machen kann.":"Στο variant board εμφανίζεται EGFR p.T790M. VAF 1,4%. Κλινικά το εύρημα θα ήταν σημαντικό — αναλυτικά όμως μοιάζει ακριβώς με πρόβλημα που μπορεί να δημιουργήσει παλιό FFPE block.","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress. In einer kleinen, stark fragmentierten Rebiopsie erscheint ein neuer C>T-Call knapp oberhalb der Reporting-Grenze. Das Board muss entscheiden, ob dies ein echter Resistenzklon ist.":"Ασθενής 67 ετών με EGFR-mutant NSCLC και πρόοδο. Σε μικρή, έντονα κατακερματισμένη επαναβιοψία εμφανίζεται νέο C>T call λίγο πάνω από το όριο αναφοράς. Το board πρέπει να αποφασίσει αν πρόκειται για πραγματικό υποκλώνο αντοχής.","Actionability ist kein QC-Kriterium":"Η actionability δεν είναι κριτήριο QC","Ein therapeutisch interessanter Genname macht einen Call nicht analytisch wahr.":"Ένα θεραπευτικά ενδιαφέρον όνομα γονιδίου δεν καθιστά ένα call αναλυτικά αληθές.","Analytische Validität kommt vor klinischer Interpretation.":"Η αναλυτική εγκυρότητα προηγείται της κλινικής ερμηνείας.","FFPE-Muster":"Πρότυπο FFPE","Mehrere sehr niedrige C>T/G>A-Ereignisse und fragmentierte DNA erhöhen den Artefaktverdacht.":"Πολλαπλά C>T/G>A συμβάντα πολύ χαμηλού επιπέδου και κατακερματισμένο DNA αυξάνουν την υποψία τεχνουργήματος.","Muster ist informativer als eine einzelne VAF.":"Το πρότυπο είναι πιο πληροφοριακό από ένα μεμονωμένο VAF.","Unabhängige Reproduzierbarkeit":"Ανεξάρτητη αναπαραγωγιμότητα","Eine zweite Extraktion/orthogonale Methode kann einen grenzwertigen Call stabilisieren oder entkräften.":"Μια δεύτερη εκχύλιση/ορθογώνια μέθοδος μπορεί να ενισχύσει ή να αποδυναμώσει ένα οριακό call.","Bestätigung sollte möglichst methodisch unabhängig sein.":"Η επιβεβαίωση πρέπει, όπου είναι δυνατό, να είναι μεθοδολογικά ανεξάρτητη.","Bekannter Treiber":"Γνωστός driver","klonale EGFR-aktivierende Mutation robust nachweisbar":"κλωνική ενεργοποιητική μετάλλαξη EGFR ανιχνεύεται με αξιοπιστία","Neuer Call":"Νέο call","EGFR p.T790M, 1,4 % VAF":"EGFR p.T790M, VAF 1,4%","FFPE-QC":"FFPE QC","stark fragmentiert; weitere sehr niedrige C>T/G>A-Ereignisse":"έντονα κατακερματισμένο· πρόσθετα C>T/G>A συμβάντα πολύ χαμηλού επιπέδου","Wenig Restmaterial.":"Ελάχιστο υπολειπόμενο υλικό.","Der Fall postuliert keine universelle VAF-Grenze; entscheidend ist die laborvalidierte Performance im konkreten Assay.":"Το περιστατικό δεν θέτει καθολικό όριο VAF· καθοριστική είναι η εργαστηριακά επικυρωμένη απόδοση της συγκεκριμένης δοκιμασίας.","Was ist der erste richtige Schritt bei einem klinisch relevanten 1,4-%-C>T-Call in stark geschädigtem FFPE?":"Ποιο είναι το πρώτο σωστό βήμα για κλινικά σχετικό C>T call 1,4% σε σοβαρά κατεστραμμένο FFPE υλικό;","Call-level QC und FFPE-Artefaktmuster prüfen.":"Έλεγχος call-level QC και του προτύπου FFPE τεχνουργημάτων.","Sofort Therapie ableiten.":"Άμεση θεραπευτική απόφαση.","Jede Variante unter 5 % grundsätzlich verwerfen.":"Απόρριψη κάθε παραλλαγής κάτω από 5% ως γενικός κανόνας.","Keimbahntestung veranlassen.":"Δρομολόγηση βλαστικού ελέγχου.","Es gibt keine universelle VAF-Regel; der Call muss assay- und kontextbezogen validiert werden.":"Δεν υπάρχει καθολικός κανόνας VAF· το call πρέπει να επικυρωθεί με βάση τη δοκιμασία και το συγκεκριμένο πλαίσιο.","Welche Befunde erhöhen hier den Artefaktverdacht?":"Ποια ευρήματα αυξάνουν εδώ την υποψία τεχνουργήματος;","sehr niedrige VAF/geringe Molekülzahl":"πολύ χαμηλό VAF/λίγα μόρια","mehrere niedrigfrequente C>T/G>A-Ereignisse":"πολλαπλά C>T/G>A συμβάντα χαμηλής συχνότητας","stark fragmentierte FFPE-DNA":"έντονα κατακερματισμένο FFPE DNA","bekannte klonale Treibermutation ist robust":"η γνωστή κλωνική driver μετάλλαξη είναι αξιόπιστη","Die Kombination aus FFPE-Schaden und typischem Substitutionsmuster ist verdächtig.":"Ο συνδυασμός FFPE βλάβης και τυπικού προτύπου υποκαταστάσεων είναι ύποπτος.","Was erhöht die Sicherheit vor therapeutischer Interpretation am stärksten?":"Τι αυξάνει περισσότερο τη βεβαιότητα πριν από τη θεραπευτική ερμηνεία;","Unabhängige Extraktion und/oder orthogonale validierte Zielmethode.":"Ανεξάρτητη εκχύλιση και/ή επικυρωμένη ορθογώνια στοχευμένη μέθοδος.","Längere Literaturrecherche ohne analytische Prüfung.":"Εκτενέστερη βιβλιογραφική αναζήτηση χωρίς αναλυτικό έλεγχο.","Den gleichen Report erneut öffnen.":"Να ανοίξει ξανά το ίδιο report.","Nur die Therapierbarkeit des Gens bewerten.":"Αξιολόγηση μόνο της θεραπευτικής στοχευσιμότητας του γονιδίου.","Reproduzierbarkeit adressiert die analytische Kernfrage.":"Η αναπαραγωγιμότητα απαντά στο βασικό αναλυτικό ερώτημα.","T790M ist unabhängig nicht reproduzierbar, der bekannte klonale EGFR-Treiber schon. Wie ist das Gesamtbild?":"Το T790M δεν αναπαράγεται ανεξάρτητα, αλλά ο γνωστός κλωνικός EGFR driver αναπαράγεται. Πώς ερμηνεύεται το συνολικό πρότυπο;","Der neue Low-VAF-Call ist nicht gesichert und im Kontext am ehesten artefaktbedingt.":"Το νέο call χαμηλού VAF δεν είναι επιβεβαιωμένο και, στο συγκεκριμένο πλαίσιο, είναι πιθανότερα τεχνούργημα.","T790M ist trotzdem sicher echt.":"Το T790M παραμένει παρ’ όλα αυτά σίγουρα πραγματικό.","Auch der bekannte EGFR-Treiber ist damit falsch.":"Άρα και ο γνωστός EGFR driver πρέπει να είναι ψευδής.","Der Unterschied ist ohne Bedeutung.":"Η διαφορά δεν έχει σημασία.","Selektive Nichtreproduzierbarkeit plus Artefaktmuster entkräftet den grenzwertigen Call.":"Η επιλεκτική μη αναπαραγωγιμότητα μαζί με το πρότυπο τεχνουργήματος αποδυναμώνει το οριακό call.","Bewerten Sie, ob der Low-VAF-Call als gesichert berichtet und therapeutisch verwendet werden darf.":"Αξιολογήστε αν το call χαμηλού VAF μπορεί να αναφερθεί ως επιβεβαιωμένο και να χρησιμοποιηθεί θεραπευτικά.","FFPE-Qualität und Substitutionsmuster prüfen.":"Έλεγχος ποιότητας FFPE και προτύπου υποκαταστάσεων.","Call-level Evidenz bewerten.":"Αξιολόγηση της τεκμηρίωσης σε επίπεδο call.","Low-VAF nicht pauschal verwerfen, aber bei hoher Konsequenz bestätigen.":"Μην απορρίπτετε κατηγορηματικά το χαμηλό VAF, αλλά επιβεβαιώστε το όταν η κλινική συνέπεια είναι μεγάλη.","Unabhängige Reproduzierbarkeit einbeziehen.":"Συνεκτίμηση της ανεξάρτητης αναπαραγωγιμότητας.","Nur robuste Befunde in die Therapiekernaussage aufnehmen.":"Συμπεριλάβετε μόνο αξιόπιστα ευρήματα στη βασική θεραπευτική δήλωση.","Bei sehr gut validiertem ultrasensitivem Assay und überzeugender unabhängiger Molekülevidenz kann ein niedriger VAF real sein; der Fall lehrt keine starre Prozentgrenze.":"Με καλά επικυρωμένη υπερευαίσθητη δοκιμασία και πειστική ανεξάρτητη μοριακή τεκμηρίωση, ένα χαμηλό VAF μπορεί να είναι πραγματικό· το περιστατικό δεν διδάσκει άκαμπτο ποσοστιαίο όριο.","<5 % = immer Artefakt":"<5% = πάντα τεχνούργημα","Ignoriert echte Subklone und assayspezifische Nachweisgrenzen.":"Αγνοεί πραγματικούς υποκλώνους και assay-specific όρια ανίχνευσης.","Actionable = echt":"Actionable = πραγματικό","Verwechselt klinische mit analytischer Evidenz.":"Συγχέει την κλινική με την αναλυτική τεκμηρίωση.","Breites Re-Panel statt Call-QC":"Επανάληψη ευρέος panel αντί για call-level QC","Mehr Daten lösen den konkreten Artefaktverdacht nicht automatisch.":"Περισσότερα δεδομένα δεν λύνουν αυτόματα τη συγκεκριμένη υποψία τεχνουργήματος.","Die Resistenzmutation verschwindet":"Η μετάλλαξη αντοχής εξαφανίζεται","In unabhängiger Extraktion und orthogonaler Zielmethode ist T790M nicht reproduzierbar, der klonale Primärtreiber jedoch stabil.":"Σε ανεξάρτητη εκχύλιση και ορθογώνια στοχευμένη μέθοδο, το T790M δεν αναπαράγεται, ενώ ο κλωνικός πρωτογενής driver παραμένει σταθερός.","Der attraktivste Befund des Reports ist nicht der belastbarste.":"Το πιο ελκυστικό εύρημα του report δεν είναι το πιο αξιόπιστο.","Low-VAF korrekt entkräftet":"Η κλήση χαμηλού VAF αποκλείστηκε ορθά","Artefaktmuster erkannt und Call unabhängig nicht bestätigt.":"Αναγνωρίστηκε πρότυπο τεχνουργήματος και η κλήση δεν επιβεβαιώθηκε ανεξάρτητα.","Therapeutisches Overcalling vermieden.":"Αποφεύχθηκε η θεραπευτική υπερερμηνεία.","Direkt als Resistenzmutation berichtet":"Αναφέρθηκε απευθείας ως μετάλλαξη αντοχής","Ein grenzwertiger FFPE-Call steuert die Therapie.":"Μια οριακή κλήση FFPE καθορίζει τη θεραπευτική απόφαση.","Analytische Evidenz unzureichend.":"Η αναλυτική τεκμηρίωση είναι ανεπαρκής.","Pauschal unter 5 % verworfen":"Απορρίφθηκε αυτόματα κάτω από 5 %","Der richtige Ausgang wird aus der falschen Regel abgeleitet.":"Το σωστό αποτέλεσμα προκύπτει από λάθος κανόνα.","Keine universelle VAF-Grenze verwenden.":"Μην χρησιμοποιείτε καθολικό όριο VAF.","klinisch relevanter Low-VAF-Call + Artefaktmuster":"κλινικά σημαντική κλήση χαμηλού VAF + πρότυπο τεχνουργήματος","analytische Bestätigung vor finaler Therapieaussage":"αναλυτική επιβεβαίωση πριν από την τελική θεραπευτική διατύπωση","Bei Nichtbestätigung nicht als gesicherte Resistenzmutation berichten.":"Εάν δεν επιβεβαιωθεί, να μην αναφερθεί ως τεκμηριωμένη μετάλλαξη αντοχής.","FFPE-Artefakte sind call- und kontextabhängig.":"Τα τεχνουργήματα FFPE εξαρτώνται από την κλήση και το πλαίσιο.","Niedrige VAF ist ein Warnsignal, kein Urteil.":"Ένα χαμηλό VAF είναι προειδοποιητικό σήμα, όχι τελική κρίση.","Je größer die klinische Konsequenz, desto wichtiger die analytische Absicherung.":"Όσο μεγαλύτερη είναι η κλινική συνέπεια, τόσο σημαντικότερη είναι η αναλυτική επιβεβαίωση.","Der T790M-Call ist aufgrund des FFPE-Musters und fehlender unabhängiger Reproduzierbarkeit nicht gesichert; keine Therapieentscheidung allein darauf stützen.":"Η κλήση T790M δεν θεωρείται τεκμηριωμένη λόγω του προτύπου τεχνουργήματος FFPE και της έλλειψης ανεξάρτητης αναπαραγωγιμότητας· μην στηρίζετε θεραπευτική απόφαση μόνο σε αυτήν.","Low-VAF-Interpretation":"Ερμηνεία χαμηλού VAF","Bestätigung":"Επιβεβαίωση","Welche Artefaktmuster sind plattformabhängig?":"Ποια πρότυπα τεχνουργημάτων εξαρτώνται από την πλατφόρμα;","Wann ist eine zweite Extraktion sinnvoll?":"Πότε είναι χρήσιμη μια δεύτερη εκχύλιση;","Wie dokumentiert man nicht bestätigte Calls?":"Πώς τεκμηριώνονται οι μη επιβεβαιωμένες κλήσεις;","Twist: klinisch attraktivster Call ist analytisch schwächster":"Ανατροπή: η κλινικά ελκυστικότερη κλήση είναι η αναλυτικά ασθενέστερη","Keine starre VAF-Grenze":"Χωρίς άκαμπτο όριο VAF","Referenzpfad: Call-QC → Artefaktmuster → unabhängige Bestätigung":"Διαδρομή αναφοράς: QC κλήσης → πρότυπο τεχνουργήματος → ανεξάρτητη επιβεβαίωση","Tumor-only BRCA2 bei 48 % VAF: therapeutisch relevant, Keimbahn trotzdem offen":"Tumor-only BRCA2 με VAF 48%: θεραπευτικά σχετικό, η βλαστική προέλευση παραμένει ανοιχτή","Tumor-only NGS: Keimbahnverdacht B…":"Tumor-only NGS: υποψία βλαστικής παραλλαγής B…","61-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom. Tumor-only NGS zeigt eine pathogene truncierende BRCA2-Variante mit 48 % VAF.":"Ασθενής 61 ετών με μεταστατικό ευνουχοάντοχο καρκίνο προστάτη. Tumor-only NGS δείχνει παθογόνο truncating παραλλαγή BRCA2 με VAF 48%.","Darf aus VAF und Gen direkt auf eine Keimbahnmutation geschlossen werden – und wie werden therapeutische und hereditäre Konsequenzen getrennt?":"Μπορεί μόνο από το VAF και το γονίδιο να τεκμηριωθεί βλαστική μετάλλαξη — και πώς διαχωρίζονται οι θεραπευτικές από τις κληρονομικές συνέπειες;","Systemische Therapieentscheidung und genetische Beratung sollen parallel geplant werden.":"Ο σχεδιασμός της συστηματικής θεραπείας και η γενετική συμβουλευτική πρέπει να προχωρούν παράλληλα.","Schwester mit Mammakarzinom mit 46 Jahren, Vater mit Prostatakarzinom mit 58 Jahren.":"Αδελφή με καρκίνο μαστού στα 46 έτη, πατέρας με καρκίνο προστάτη στα 58 έτη.","Tumorprofil":"Μοριακό προφίλ όγκου","Pathogene BRCA2-Trunkierung; Tumorreinheit und Kopienzahl machen eine Herkunft aus der VAF allein nicht eindeutig.":"Παθογόνος truncating παραλλαγή BRCA2· η καθαρότητα του όγκου και ο αριθμός αντιγράφων δεν επιτρέπουν τον προσδιορισμό της προέλευσης μόνο από το VAF.","„ungefähr 50 %“ wird mit „Keimbahn bewiesen“ gleichgesetzt.":"Το «περίπου 50%» εξισώνεται με «αποδεδειγμένα βλαστικό». ","Tumorbiomarker und hereditäre Diagnostik sauber entkoppeln und dann wieder integrieren.":"Σαφής διαχωρισμός του ογκολογικού βιοδείκτη από τον κληρονομικό έλεγχο και στη συνέχεια επανένταξή τους σε ενιαία ερμηνεία.","Metastasiertes Prostataadenokarzinom.":"Μεταστατικό αδενοκαρκίνωμα προστάτη.","BRCA2 pathogene Loss-of-function-Variante, VAF 48 %.":"Παθογόνος loss-of-function παραλλαγή BRCA2, VAF 48%.","somatisch, Keimbahn oder beides im Tumorkontext?":"σωματική, βλαστική ή και τα δύο στο πλαίσιο του όγκου;","Tumorreinheit, LOH und Copy-number können VAF deutlich verschieben.":"Η καθαρότητα του όγκου, το LOH και ο αριθμός αντιγράφων μπορούν να μεταβάλουν σημαντικά το VAF.","FFPE-Metastase für Tumorprofil; EDTA-Blut für bestätigende Keimbahndiagnostik verfügbar.":"FFPE μετάσταση για μοριακό προφίλ όγκου· διαθέσιμο αίμα EDTA για επιβεβαιωτικό βλαστικό έλεγχο.","ca. 60 %.":"περ. 60%.","Consent":"Συναίνεση","Genetische Beratung/Einwilligung für Keimbahndiagnostik erforderlich.":"Για τον βλαστικό έλεγχο απαιτούνται γενετική συμβουλευτική και συναίνεση.","Tumor-normal bzw. gezielte Keimbahnbestätigung möglich.":"Είναι δυνατή ανάλυση tumor-normal ή στοχευμένη επιβεβαίωση στη βλαστική σειρά.","Tumor-BRCA/HRR einordnen":"Ερμηνεία του BRCA/HRR στον όγκο","Potenzielle Keimbahn separat klären":"Ξεχωριστή διερεύνηση πιθανής βλαστικής προέλευσης","Pathogene BRCA2-Loss-of-function-Variante im Tumor; für die tumorbezogene Therapieentscheidung relevant, ohne damit die Keimbahnherkunft zu beweisen.":"Παθογόνος loss-of-function παραλλαγή BRCA2 στον όγκο· σχετική για ογκολογική θεραπεία χωρίς να αποδεικνύει βλαστική προέλευση.","Die pathogene BRCA2-Variante wird im konstitutionellen Material bestätigt: Keimbahnmutation. Der Tumor-only-Befund war ein Hinweis, nicht der Beweis.":"Η παθογόνος παραλλαγή BRCA2 επιβεβαιώνεται σε συνταγματικό υλικό: βλαστική μετάλλαξη. Το tumor-only εύρημα ήταν ένδειξη, όχι απόδειξη.","Humangenetische Beratung":"Γενετική συμβουλευτική","Genetische Beratung wird veranlasst; hereditäre Konsequenzen werden außerhalb des reinen Tumorbefunds adressiert.":"Δρομολογείται γενετική συμβουλευτική· οι κληρονομικές συνέπειες αντιμετωπίζονται εκτός του καθαρά tumor-only πορίσματος.","Tumor-only":"Tumor-only","Ohne Normalprobe kann die Herkunft einer Variante nicht allein aus der VAF sicher bestimmt werden.":"Χωρίς φυσιολογικό δείγμα, η προέλευση μιας παραλλαγής δεν μπορεί να προσδιοριστεί αξιόπιστα μόνο από το VAF.","Therapeutische Tumorrelevanz und hereditäre Bedeutung sind getrennte Fragestellungen.":"Η θεραπευτική σημασία για τον όγκο και η κληρονομική σημασία είναι διαφορετικά ερωτήματα.","Die pathogene BRCA2-Variante ist im Tumor therapeutisch relevant, aber Tumor-only Sequenzierung beweist keine Keimbahnherkunft. VAF um 50 % erhöht den Verdacht, ist wegen Tumorreinheit, LOH und Copy-number jedoch nicht beweisend. Die bestätigende Analyse im konstitutionellen Material zeigt hier tatsächlich eine Keimbahnmutation.":"Η παθογόνος παραλλαγή BRCA2 είναι θεραπευτικά σχετική στον όγκο, αλλά η tumor-only αλληλούχηση δεν αποδεικνύει βλαστική προέλευση. VAF περίπου 50% αυξάνει την υποψία, αλλά δεν αποτελεί απόδειξη λόγω καθαρότητας όγκου, LOH και αριθμού αντιγράφων. Η επιβεβαιωτική ανάλυση σε συνταγματικό υλικό δείχνει εδώ βλαστική μετάλλαξη.","Teilbefund: Ein Tumor-only BRCA2-Befund kann therapeutisch relevant sein und gleichzeitig eine separate Keimbahnabklärung auslösen; die VAF allein entscheidet die Herkunft nicht.":"Μερικό εύρημα: ένα tumor-only αποτέλεσμα BRCA2 μπορεί να είναι θεραπευτικά σχετικό και ταυτόχρονα να απαιτεί ξεχωριστό βλαστικό έλεγχο· το VAF μόνο δεν καθορίζει την προέλευση.","Tumoractionability separat bewerten":"Ξεχωριστή αξιολόγηση της actionability του όγκου","Keimbahnverdacht separat adressieren":"Ξεχωριστή αντιμετώπιση της υποψίας βλαστικής προέλευσης","VAF nicht als Herkunftsbeweis verwenden":"Μην χρησιμοποιείτε το VAF ως απόδειξη προέλευσης","Falschaussage: 48–50 % VAF im Tumor beweist Keimbahn":"Λανθασμένη δήλωση: VAF 48–50% στον όγκο αποδεικνύει βλαστική προέλευση","Optimale Lösung: Tumorbefund therapeutisch einordnen, Keimbahnverdacht transparent markieren und mit konstitutionellem Material/genetischer Beratung bestätigen.":"Βέλτιστη λύση: θεραπευτική ερμηνεία του ογκολογικού ευρήματος, σαφής επισήμανση της υποψίας βλαστικής προέλευσης και επιβεβαίωση με συνταγματικό υλικό/γενετική συμβουλευτική.","48 % sind kein Abstammungsnachweis":"Το 48% δεν αποτελεί απόδειξη βλαστικής προέλευσης","Molekulares Tumorboard / Humangenetik-Schnittstelle":"Διεπαφή Μοριακού Ογκολογικού Συμβουλίου / Γενετικής","Tumor-only NGS nicht mit Keimbahndiagnostik gleichsetzen.":"Μην εξισώνετε το tumor-only NGS με βλαστική διαγνωστική.","VAF nur als Hinweis und nie isoliert als Herkunftsbeweis nutzen.":"Χρησιμοποιείτε το VAF μόνο ως ένδειξη και ποτέ απομονωμένα ως απόδειξη προέλευσης.","Tumorbezogene Therapieinformation und hereditäre Konsequenzen getrennt bearbeiten.":"Διαχειριστείτε χωριστά τις πληροφορίες για ογκολογική θεραπεία και τις κληρονομικές συνέπειες.","Bestätigende Keimbahndiagnostik mit geeigneter Beratung/Einwilligung veranlassen.":"Δρομολογήστε επιβεβαιωτικό βλαστικό έλεγχο με κατάλληλη συμβουλευτική/συναίνεση.","BRCA2, pathogene Trunkierung, VAF 48 %. Der Report sieht „keimbahnverdächtig“ aus – aber 48 % im Tumor sind keine Blutprobe. Genau hier muss das Board zwei richtige Aussagen gleichzeitig halten.":"BRCA2, παθογόνος truncating παραλλαγή, VAF 48%. Το report φαίνεται «ύποπτο για βλαστική προέλευση» — αλλά 48% σε όγκο δεν είναι δείγμα αίματος. Εδώ ακριβώς το board πρέπει να κρατήσει ταυτόχρονα δύο σωστές δηλώσεις.","61-jähriger Patient mit mCRPC und pathogener BRCA2-Variante im Tumor-only Panel. Der Befund kann therapeutisch relevant sein. Wegen VAF und Familienanamnese besteht zusätzlich Keimbahnverdacht, der separat bestätigt werden muss.":"Ασθενής 61 ετών με mCRPC και παθογόνο παραλλαγή BRCA2 σε tumor-only panel. Το εύρημα μπορεί να είναι θεραπευτικά σχετικό. Το VAF και το οικογενειακό ιστορικό εγείρουν επιπλέον υποψία βλαστικής προέλευσης, η οποία πρέπει να επιβεβαιωθεί ξεχωριστά.","VAF ist modellabhängig":"Το VAF εξαρτάται από το μοντέλο/πλαίσιο","Tumorreinheit, LOH, Amplifikation/Deletion und Klonalität verschieben die beobachtete VAF.":"Η καθαρότητα του όγκου, το LOH, η ενίσχυση/διαγραφή και η κλωνικότητα μπορούν να μετατοπίσουν το παρατηρούμενο VAF.","50 % ist kein magischer Keimbahn-Cutoff.":"Το 50% δεν είναι μαγικό cutoff βλαστικής προέλευσης.","Zwei Konsequenzachsen":"Δύο άξονες συνεπειών","Tumortherapie kann auf dem somatischen Befund beruhen; Familien-/Prädispositionsfragen brauchen Keimbahndiagnostik.":"Η θεραπεία του όγκου μπορεί να βασιστεί στο σωματικό εύρημα· τα ερωτήματα οικογένειας/προδιάθεσης απαιτούν βλαστικό έλεγχο.","Dasselbe Gen erzeugt zwei unterschiedliche Workflows.":"Το ίδιο γονίδιο δημιουργεί δύο διαφορετικές ροές εργασίας.","Tumor-only hat Grenzen":"Το tumor-only έχει περιορισμούς","Ohne Normalprobe bleibt die Herkunft vieler Varianten unbestimmt.":"Χωρίς φυσιολογικό δείγμα, η προέλευση πολλών παραλλαγών παραμένει αδιευκρίνιστη.","Bericht und Beratung müssen das transparent machen.":"Το report και η συμβουλευτική πρέπει να το καθιστούν σαφές.","pathogene BRCA2-LoF, VAF 48 %":"παθογόνος BRCA2 LoF, VAF 48%","frühes Mammakarzinom bei Schwester, Prostatakarzinom beim Vater":"πρώιμος καρκίνος μαστού στην αδελφή, καρκίνος προστάτη στον πατέρα","Normalprobe":"Φυσιολογικό δείγμα","noch nicht untersucht":"δεν έχει εξεταστεί ακόμη","Konstitutionelles Material verfügbar.":"Υπάρχει διαθέσιμο συνταγματικό υλικό.","Hereditäre Diagnostik erfordert eigenen Prozess/Einwilligung.":"Η κληρονομική διαγνωστική απαιτεί ξεχωριστή διαδικασία/συναίνεση.","Tumor-VAF wird im Kontext von Reinheit und Copy-number interpretiert.":"Το VAF του όγκου ερμηνεύεται στο πλαίσιο της καθαρότητας και του αριθμού αντιγράφων.","Was beweist eine pathogene BRCA2-Variante mit 48 % VAF im Tumor-only Panel?":"Τι αποδεικνύει παθογόνος παραλλαγή BRCA2 με VAF 48% σε tumor-only panel;","Sie ist keimbahnverdächtig, beweist aber ohne konstitutionelle Probe keine Keimbahnherkunft.":"Εγείρει υποψία βλαστικής προέλευσης, αλλά δεν την αποδεικνύει χωρίς συνταγματικό υλικό.","Keimbahn ist sicher bewiesen.":"Η βλαστική προέλευση είναι αποδεδειγμένη με βεβαιότητα.","Somatisch ist sicher bewiesen.":"Η σωματική προέλευση είναι αποδεδειγμένη με βεβαιότητα.","Die Variante ist ein Artefakt.":"Η παραλλαγή είναι τεχνούργημα.","Tumorreinheit und Copy-number verhindern einfache VAF-Herkunftsregeln.":"Η καθαρότητα του όγκου και ο αριθμός αντιγράφων δεν επιτρέπουν απλούς κανόνες προέλευσης βάσει VAF.","Welche zwei Fragen müssen getrennt beantwortet werden?":"Ποια δύο ερωτήματα πρέπει να απαντηθούν ξεχωριστά;","Welche tumorbezogene therapeutische Bedeutung hat BRCA2?":"Ποια θεραπευτική σημασία έχει το BRCA2 για τον όγκο;","Liegt eine konstitutionelle pathogene Variante vor?":"Υπάρχει παθογόνος παραλλαγή στη βλαστική σειρά;","Welche Farbe hat der Report?":"Τι χρώμα έχει το report;","Reicht das Alter allein als Keimbahntest?":"Αρκεί μόνο η ηλικία για βλαστικό έλεγχο;","Therapie und Prädisposition sind gekoppelt, aber nicht identisch.":"Η θεραπεία και η προδιάθεση συνδέονται, αλλά δεν είναι ταυτόσημες.","Wie wird die Keimbahnfrage belastbar geklärt?":"Πώς μπορεί να διευκρινιστεί αξιόπιστα το ερώτημα της βλαστικής προέλευσης;","Analyse geeigneten konstitutionellen Materials im passenden genetischen Prozess.":"Ανάλυση κατάλληλου συνταγματικού υλικού στο σωστό γενετικό πλαίσιο.","Nur VAF erneut ansehen.":"Απλώς ξανακοιτάξτε το VAF.","Nur denselben Tumor erneut sequenzieren.":"Απλώς επαναλάβετε αλληλούχηση του ίδιου όγκου.","Gar nicht; Tumor-only reicht.":"Καμία περαιτέρω ενέργεια· το tumor-only αρκεί.","Die Herkunft braucht konstitutionellen Vergleich/Bestätigung.":"Η προέλευση απαιτεί σύγκριση/επιβεβαίωση σε συνταγματικό υλικό.","Die Variante wird im Blut bestätigt. Was ändert sich?":"Η παραλλαγή επιβεβαιώνεται στο αίμα. Τι αλλάζει;","Zusätzlich zur Tumorrelevanz ist nun eine Keimbahnmutation bestätigt und hereditäre Konsequenzen können adressiert werden.":"Εκτός από τη σημασία για τον όγκο, πλέον επιβεβαιώνεται βλαστική μετάλλαξη και μπορούν να αντιμετωπιστούν οι κληρονομικές συνέπειες.","Die Tumorrelevanz verschwindet.":"Η σημασία για τον όγκο εξαφανίζεται.","Der Tumorbefund war falsch.":"Το ογκολογικό εύρημα ήταν λάθος.","Es gibt keinerlei zusätzliche Konsequenz.":"Δεν υπάρχουν πρόσθετες συνέπειες.","Die bestätigte Herkunft ergänzt den Tumorbefund um eine zweite klinische Dimension.":"Η επιβεβαιωμένη προέλευση προσθέτει δεύτερη κλινική διάσταση στο ογκολογικό εύρημα.","Formulieren Sie Tumor- und Keimbahnaussage getrennt und definieren Sie den nächsten diagnostischen Schritt.":"Διατυπώστε χωριστά το ογκολογικό και το βλαστικό συμπέρασμα και ορίστε το επόμενο διαγνωστικό βήμα.","Pathogene BRCA2-Variante im Tumor als tumorbezogenen Biomarker einordnen.":"Ερμηνεύστε την παθογόνο παραλλαγή BRCA2 στον όγκο ως ογκολογικό βιοδείκτη.","VAF und Familienanamnese als Keimbahnverdacht, nicht Beweis, kommunizieren.":"Επικοινωνήστε το VAF και το οικογενειακό ιστορικό ως στοιχεία υποψίας βλαστικής προέλευσης, όχι ως απόδειξη.","Konstitutionelle Testung/genetische Beratung veranlassen.":"Δρομολογήστε συνταγματικό έλεγχο/γενετική συμβουλευτική.","Nach Bestätigung hereditäre Ebene getrennt dokumentieren.":"Μετά την επιβεβαίωση, τεκμηριώστε χωριστά την κληρονομική διάσταση.","Je nach lokaler Struktur kann eine direkte Überweisung zur Humangenetik statt tumor-normal Analyse im selben Labor sinnvoll sein.":"Ανάλογα με την τοπική δομή, μπορεί να είναι καταλληλότερη η άμεση παραπομπή στη γενετική αντί για tumor-normal ανάλυση στο ίδιο εργαστήριο.","48 % = Keimbahn":"48% = βλαστικό","VAF im Tumor hängt von Reinheit, LOH und Copy-number ab.":"Το VAF του όγκου εξαρτάται από καθαρότητα, LOH και αριθμό αντιγράφων.","Nur Therapie, Keimbahn ignorieren":"Μόνο θεραπεία, αγνόηση της βλαστικής διάστασης","Verpasst potenziell relevante Prädispositionsinformation.":"Χάνει δυνητικά σημαντική πληροφορία προδιάθεσης.","Nur Keimbahn diskutieren":"Συζήτηση μόνο της βλαστικής διάστασης","Ignoriert die unmittelbare tumorbezogene Bedeutung.":"Αγνοεί την άμεση σημασία για τον όγκο.","Der Verdacht bestätigt sich – aber erst im richtigen Material":"Η υποψία επιβεβαιώνεται — αλλά μόνο στο σωστό υλικό","Die BRCA2-Variante wird im konstitutionellen Material bestätigt.":"Η παραλλαγή BRCA2 επιβεβαιώνεται σε συνταγματικό υλικό.","Der Fall zeigt den Unterschied zwischen einem starken Hinweis aus Tumor-only NGS und einem echten Keimbahnnachweis.":"Το περιστατικό δείχνει τη διαφορά μεταξύ ισχυρής ένδειξης από tumor-only NGS και πραγματικής βλαστικής επιβεβαίωσης.","Tumorrelevanz genutzt, Keimbahn separat bestätigt.":"Η ογκολογική σημασία αξιοποιείται, η βλαστική κατάσταση επιβεβαιώνεται ξεχωριστά.","Vollständige Präzisionsonkologie plus Prädispositionslogik.":"Πλήρης ογκολογία ακριβείας συν λογική προδιάθεσης.","Keimbahn aus 48 % behauptet":"Βλαστική προέλευση δηλώνεται από 48%","Herkunft ohne Normalprobe overcallt.":"Υπερερμηνεία της προέλευσης χωρίς φυσιολογικό δείγμα.","Methodisch unzulässig.":"Μεθοδολογικά μη αποδεκτό.","Keimbahnverdacht ignoriert":"Αγνόηση της υποψίας βλαστικής προέλευσης","Hereditäre Ebene bleibt ungeklärt.":"Η κληρονομική διάσταση παραμένει αδιευκρίνιστη.","Unvollständige Nachsorge.":"Ελλιπής παρακολούθηση.","pathogene Variante in Prädispositionsgen im Tumor-only Kontext":"παθογόνος παραλλαγή σε γονίδιο προδιάθεσης σε tumor-only πλαίσιο","Keimbahnpotenzial bewerten und ggf. Bestätigung/Genetik veranlassen":"αξιολόγηση βλαστικού δυναμικού και δρομολόγηση επιβεβαίωσης/γενετικής όπου ενδείκνυται","Tumorbefund nicht als konstitutionellen Befund etikettieren.":"Μην χαρακτηρίζετε το ογκολογικό εύρημα ως συνταγματικό εύρημα.","Tumor-only ist keine Keimbahndiagnostik.":"Το tumor-only δεν είναι βλαστική διαγνωστική.","VAF ist ein Hinweis, kein Beweis.":"Το VAF είναι ένδειξη, όχι απόδειξη.","Dasselbe Variantenergebnis kann therapeutische und hereditäre Konsequenzen parallel haben.":"Το ίδιο αποτέλεσμα παραλλαγής μπορεί να έχει παράλληλα θεραπευτικές και κληρονομικές συνέπειες.","Pathogene BRCA2-Variante im Tumor therapeutisch relevant; Keimbahnherkunft aus Tumor-only/VAF nicht beweisbar. Bestätigende konstitutionelle Diagnostik ist indiziert und zeigt hier eine Keimbahnmutation.":"Η παθογόνος παραλλαγή BRCA2 στον όγκο είναι θεραπευτικά σχετική· η βλαστική προέλευση δεν αποδεικνύεται από tumor-only/VAF. Ενδείκνυται επιβεβαιωτικός συνταγματικός έλεγχος, ο οποίος εδώ δείχνει βλαστική μετάλλαξη.","Tumor-only-Grenzen":"Περιορισμοί tumor-only","VAF-Interpretation":"Ερμηνεία VAF","Keimbahnworkflow":"Ροή εργασίας βλαστικού ελέγχου","Welche Gene lösen besonders häufig Keimbahn-Reflexfragen aus?":"Ποια γονίδια εγείρουν συχνότερα reflex ερωτήματα για βλαστική προέλευση;","Wie beeinflusst LOH die Tumor-VAF?":"Πώς επηρεάζει το LOH το VAF του όγκου;","Wie formuliert man Keimbahnverdacht im Tumorbericht?":"Πώς διατυπώνεται η υποψία βλαστικής προέλευσης σε ογκολογικό report;","Twist: 48 % ist Hinweis, kein Beweis":"Twist: 48% είναι ένδειξη, όχι απόδειξη","Tumor- und Keimbahnkonsequenz getrennt":"Διαχωρισμός ογκολογικών και βλαστικών συνεπειών","Referenzpfad: Tumoractionability → Keimbahnverdacht → konstitutionelle Bestätigung":"Διαδρομή αναφοράς: tumor actionability → υποψία βλαστικής προέλευσης → συνταγματική επιβεβαίωση","ALK-IHC positiv, DNA-NGS negativ: die Fusion steckt im Transkript":"ALK IHC θετικό, DNA NGS αρνητικό: η σύντηξη βρίσκεται στο μεταγράφημα","DNA-NGS negativ, aber Fusionsverda…":"DNA NGS αρνητικό, αλλά η υποψία σύντηξης παραμένει…","Sarkomzentrum / Molekulares Tumorboard":"Κέντρο σαρκωμάτων / Μοριακό Ογκολογικό Συμβούλιο","34-jährige Patientin mit nicht vollständig resezierbarem inflammatorischem myofibroblastärem Tumor (IMT) im kleinen Becken. ALK-IHC diffus stark positiv, DNA-basiertes Panel meldet keine ALK-Fusion.":"Ασθενής 34 ετών με μη πλήρως εξαιρέσιμο φλεγμονώδη μυοϊνοβλαστικό όγκο (IMT) της πυέλου. Η ALK IHC είναι διάχυτα έντονα θετική· DNA-based panel δεν αναφέρει σύντηξη ALK.","Ist die Fusionshypothese damit erledigt oder muss RNA-basiert/orthogonal weiter untersucht werden?":"Τελειώνει έτσι η υπόθεση σύντηξης ή πρέπει να συνεχιστεί RNA-based/ορθογώνιος έλεγχος;","Die systemische Behandlungsstrategie soll im Sarkomboard festgelegt werden.":"Η στρατηγική συστηματικής θεραπείας θα καθοριστεί στο συμβούλιο σαρκωμάτων.","Spindelzelliger myofibroblastärer Tumor mit entzündlichem Hintergrund, passend zu IMT.":"Ατρακτοκυτταρικός μυοϊνοβλαστικός όγκος με φλεγμονώδες υπόβαθρο, συμβατός με IMT.","ALK diffus zytoplasmatisch stark positiv.":"ALK διάχυτα έντονα κυτταροπλασματικά θετικό.","DNA-Panel":"DNA panel","Keine Fusion detektiert; Report weist darauf hin, dass nicht alle intronischen Breakpointregionen vollständig erfasst werden.":"Δεν ανιχνεύθηκε σύντηξη· το report αναφέρει ότι δεν καλύπτονται πλήρως όλες οι ενδονικές περιοχές breakpoint.","„Gen im Panel enthalten“ wird mit „jede mögliche Fusion erfasst“ gleichgesetzt.":"Το «το γονίδιο περιλαμβάνεται στο panel» εξισώνεται με «καλύπτεται κάθε πιθανή σύντηξη». ","IMT-morphologischer Kontext.":"Μορφολογικό πλαίσιο IMT.","ALK-IHC":"ALK IHC","stark positiv.":"έντονα θετικό.","kein Fusionscall.":"χωρίς fusion call.","Ist ein exprimiertes ALK-Fusionstranskript nachweisbar?":"Ανιχνεύεται εκφραζόμενο μεταγράφημα σύντηξης ALK;","FFPE-Resektat, RNA-QC ausreichend.":"FFPE παρασκεύασμα εκτομής, επαρκές RNA QC.","DNA-Limitation":"Περιορισμός DNA","Breakpoint kann außerhalb der erfassten intronischen Regionen liegen.":"Το breakpoint μπορεί να βρίσκεται εκτός των ενδονικών περιοχών που καλύπτονται.","Gezieltes RNA-Fusionspanel und FISH verfügbar.":"Διατίθενται στοχευμένο RNA fusion panel και FISH.","Fusionsverdacht mit geeigneter Methode klären":"Διευκρίνιση της υποψίας σύντηξης με κατάλληλη μέθοδο","RNA-basiertes Fusionspanel weist ein exprimiertes TPM3::ALK-Fusionstranskript nach.":"RNA-based fusion panel ανιχνεύει εκφραζόμενο μεταγράφημα σύντηξης TPM3::ALK.","ALK-Break-apart-FISH ist positiv und stützt das Rearrangement, ohne den Fusionspartner auf Sequenzebene zu definieren.":"ALK break-apart FISH είναι θετικό και υποστηρίζει την αναδιάταξη χωρίς να προσδιορίζει τον fusion partner σε επίπεδο αλληλουχίας.","Breites DNA-Panel":"Ευρύ DNA panel","Mehr DNA-Panelbreite garantiert keine vollständige Erfassung aller Fusionsbreakpoints; die relevante methodische Lücke bleibt.":"Μεγαλύτερη ευρύτητα DNA panel δεν εγγυάται πλήρη κάλυψη όλων των fusion breakpoints· το σχετικό μεθοδολογικό κενό παραμένει.","Prätestwahrscheinlichkeit":"Προtest πιθανότητα","Morphologie plus starke ALK-IHC machen einen Fusionsmechanismus plausibel.":"Η μορφολογία μαζί με έντονη ALK IHC καθιστούν πιθανό μηχανισμό σύντηξης.","Ein negatives DNA-Fusionsergebnis ist nur so vollständig wie das Assaydesign der relevanten intronischen Regionen.":"Ένα αρνητικό DNA αποτέλεσμα σύντηξης είναι τόσο πλήρες όσο το assay design των σχετικών ενδονικών περιοχών.","Der negative DNA-Fusionscall schließt in diesem hochgradig verdächtigen Kontext ein ALK-Rearrangement nicht aus. RNA-NGS weist ein exprimiertes TPM3::ALK-Transkript nach; ALK-FISH bestätigt das Rearrangement orthogonal. Der Fall zeigt den komplementären Wert von RNA- und DNA-basierten Ansätzen.":"Το αρνητικό DNA fusion call δεν αποκλείει αναδιάταξη ALK σε αυτό το ισχυρά ύποπτο πλαίσιο. RNA NGS ανιχνεύει εκφραζόμενο TPM3::ALK μεταγράφημα· ALK FISH επιβεβαιώνει ορθογώνια την αναδιάταξη. Το περιστατικό δείχνει τη συμπληρωματική αξία RNA- και DNA-based προσεγγίσεων.","Teilbefund: Bei hoher morphologisch-immunhistochemischer Prätestwahrscheinlichkeit ist ein negativer DNA-Fusionscall nicht automatisch abschließend.":"Μερικό αποτέλεσμα: με υψηλή μορφολογική/ανοσοϊστοχημική pretest πιθανότητα, ένα αρνητικό DNA fusion call δεν είναι αυτομάτως οριστικό.","Assaydesign/Breakpointabdeckung berücksichtigen":"Συνεκτίμηση assay design/κάλυψης breakpoints","RNA als direkte Ebene des exprimierten Fusionstranskripts einordnen":"Τοποθετήστε το RNA ως άμεσο επίπεδο του εκφραζόμενου μεταγραφήματος σύντηξης","FISH als orthogonalen Rearrangementnachweis einordnen":"Τοποθετήστε το FISH ως ορθογώνια απόδειξη αναδιάταξης","Falschaussage: ALK steht im DNA-Panel, daher sind alle ALK-Fusionen ausgeschlossen":"Λανθασμένη δήλωση: το ALK περιλαμβάνεται στο DNA panel, άρα αποκλείονται όλες οι συντήξεις ALK","Optimale Lösung: Widerspruch zwischen starker Prätestwahrscheinlichkeit und negativem DNA-Fusionscall erkennen und mit RNA-basierter Fusionsdiagnostik bzw. FISH klären.":"Βέλτιστη λύση: αναγνώριση της αντίφασης μεταξύ υψηλής pretest πιθανότητας και αρνητικού DNA fusion call και επίλυσή της με RNA-based έλεγχο συντήξεων και/ή FISH.","Fusion":"Σύντηξη","ALK":"ALK","DNA negativ, Biologie positiv":"DNA αρνητικό, βιολογία θετική","Molekularpathologie / Fusionsdiagnostik / Sarkom-MTB":"Μοριακή Παθολογία / Διαγνωστική Συντήξεων / MTB σαρκωμάτων","Grenzen DNA-basierter Fusionsdetektion durch Breakpoint-/Intronabdeckung verstehen.":"Κατανόηση των ορίων DNA-based ανίχνευσης συντήξεων λόγω κάλυψης breakpoint/intron.","RNA-NGS als komplementären Nachweis exprimierter Fusionstranskripte nutzen.":"Χρησιμοποιήστε RNA NGS ως συμπληρωματική απόδειξη εκφραζόμενων μεταγραφημάτων σύντηξης.","Prätestwahrscheinlichkeit aus Morphologie/IHC in die Methodenauswahl integrieren.":"Ενσωματώστε την pretest πιθανότητα από μορφολογία/IHC στην επιλογή μεθόδου.","FISH als orthogonalen Rearrangementnachweis mit begrenzter Partnerinformation einordnen.":"Ερμηνεύστε το FISH ως ορθογώνια απόδειξη αναδιάταξης με περιορισμένη πληροφορία για τον partner.","ALK ist immunhistochemisch leuchtend positiv, die Morphologie passt – und trotzdem sagt das DNA-Panel „keine Fusion“. Der Fall beginnt dort, wo ein Automat aufhören würde.":"Το ALK είναι έντονα θετικό στην IHC, η μορφολογία ταιριάζει — και παρ’ όλα αυτά το DNA panel λέει «χωρίς σύντηξη». Το περιστατικό αρχίζει εκεί όπου ένα αυτόματο σύστημα θα σταματούσε.","34-jährige Patientin mit IMT. ALK-IHC und Morphologie sprechen stark für einen Fusionsmechanismus, das DNA-Panel bleibt negativ. Das Assaydesign deckt nicht alle möglichen intronischen Breakpoints ab.":"Ασθενής 34 ετών με IMT. Η ALK IHC και η μορφολογία υποστηρίζουν έντονα μηχανισμό σύντηξης, αλλά το DNA panel είναι αρνητικό. Το assay design δεν καλύπτει όλα τα πιθανά ενδονικά breakpoints.","Panelinhalt ≠ vollständige Fusionsabdeckung":"Περιεχόμενο panel ≠ πλήρης κάλυψη συντήξεων","Ein Gen kann im Panel sein, ohne dass jeder relevante intronische Breakpoint erfasst wird.":"Ένα γονίδιο μπορεί να βρίσκεται στο panel χωρίς να καλύπτεται κάθε σχετικό ενδονικό breakpoint.","Assaydesign bestimmt Sensitivität.":"Το assay design καθορίζει την ευαισθησία.","RNA fragt nach dem Produkt":"Το RNA εξετάζει το προϊόν","Ein RNA-Fusionsassay kann das tatsächlich exprimierte Chimärtranskript nachweisen.":"Ένα RNA fusion assay μπορεί να ανιχνεύσει το πραγματικά εκφραζόμενο χιμαιρικό μεταγράφημα.","RNA und DNA sind komplementär.":"RNA και DNA είναι συμπληρωματικά.","Prätestwahrscheinlichkeit zählt":"Η pretest πιθανότητα έχει σημασία","Morphologie + ALK-IHC machen einen negativen DNA-Call unplausibel genug für Reflexdiagnostik.":"Μορφολογία + ALK IHC καθιστούν ένα αρνητικό DNA call αρκετά μη πειστικό ώστε να δικαιολογείται reflex testing.","Diagnostik ist Bayes, nicht nur Softwareoutput.":"Η διαγνωστική είναι Bayesian, όχι απλώς software output.","IMT-kompatibel":"συμβατό με IMT","diffus stark positiv":"διάχυτα έντονα θετικό","kein Fusionscall; intronische Coverage limitiert":"χωρίς fusion call· περιορισμένη ενδονική κάλυψη","RNA-Qualität ausreichend.":"Η ποιότητα RNA είναι επαρκής.","FISH verfügbar.":"Διαθέσιμο FISH.","Kein Bedarf für beliebige weitere DNA-Breite, wenn die offene Frage eine Fusion ist.":"Δεν χρειάζεται αυθαίρετη επιπλέον DNA ευρύτητα όταν το ανοιχτό ερώτημα είναι σύντηξη.","Wie ist der negative DNA-Fusionscall bei starker ALK-IHC und passender Morphologie zu bewerten?":"Πώς πρέπει να ερμηνευτεί το αρνητικό DNA fusion call με έντονη ALK IHC και συμβατή μορφολογία;","Er schließt eine Fusion nicht sicher aus, wenn relevante Breakpoints vom Assay nicht vollständig erfasst werden.":"Δεν αποκλείει με ασφάλεια σύντηξη αν τα σχετικά breakpoints δεν καλύπτονται πλήρως από τη δοκιμασία.","ALK-Fusion ist sicher ausgeschlossen.":"Η σύντηξη ALK αποκλείεται με βεβαιότητα.","IHC ist damit automatisch falsch.":"Άρα η IHC είναι αυτομάτως λανθασμένη.","Es handelt sich um Keimbahn-ALK.":"Πρόκειται για βλαστικό ALK.","Fusionssensitivität hängt stark vom Assaydesign ab.":"Η ευαισθησία ανίχνευσης συντήξεων εξαρτάται έντονα από το assay design.","Warum ist RNA-NGS hier besonders sinnvoll?":"Γιατί είναι ιδιαίτερα χρήσιμο το RNA NGS εδώ;","Es kann ein exprimiertes Fusionstranskript direkt erfassen und DNA-Breakpointgrenzen umgehen.":"Μπορεί να ανιχνεύσει άμεσα εκφραζόμενο μεταγράφημα σύντηξης και να παρακάμψει περιορισμούς των DNA breakpoints.","Es ist exakt derselbe Test wie DNA-NGS.":"Είναι ακριβώς η ίδια εξέταση με DNA NGS.","Es misst nur Proteinexpression.":"Μετρά μόνο πρωτεϊνική έκφραση.","Es ist primär ein Copy-number-Test.":"Είναι κυρίως copy-number test.","RNA liefert eine komplementäre Fusionsinformation.":"Το RNA παρέχει συμπληρωματική πληροφορία για τη σύντηξη.","Was kann ein positiver ALK-Break-apart-FISH hier sinnvoll beitragen?":"Τι μπορεί να προσθέσει χρήσιμα εδώ ένα θετικό ALK break-apart FISH;","Orthogonaler Nachweis eines ALK-Rearrangements, meist ohne genaue Partner-/Transkriptinformation.":"Ορθογώνια απόδειξη αναδιάταξης ALK, συνήθως χωρίς ακριβή πληροφορία partner/μεταγραφήματος.","Immer vollständige Sequenz des Fusionspartners.":"Πάντα την πλήρη αλληλουχία του fusion partner.","Quantitative RNA-Expression.":"Ποσοτική έκφραση RNA.","Keimbahnstatus.":"Βλαστική κατάσταση.","FISH ist schnell und orthogonal, aber informationsärmer als sequenzbasierte Partnerbestimmung.":"Το FISH είναι γρήγορο και ορθογώνιο, αλλά παρέχει λιγότερη πληροφορία από sequence-based αναγνώριση partner.","RNA-NGS zeigt TPM3::ALK. Was erklärt die DNA/RNA-Diskrepanz am besten?":"RNA NGS δείχνει TPM3::ALK. Τι εξηγεί καλύτερα τη διαφορά DNA/RNA;","Das DNA-Assaydesign hat den relevanten Breakpoint nicht zuverlässig abgedeckt; RNA erfasst das exprimierte Transkript.":"Το DNA assay design δεν κάλυψε αξιόπιστα το σχετικό breakpoint· το RNA ανιχνεύει το εκφραζόμενο μεταγράφημα.","RNA muss falsch sein, weil DNA negativ war.":"Το RNA πρέπει να είναι λάθος επειδή το DNA ήταν αρνητικό.","Die Histologie ist damit irrelevant.":"Άρα η ιστολογία είναι άσχετη.","Beide Tests sind negativ.":"Και οι δύο εξετάσεις είναι αρνητικές.","Komplementäre Assaygrenzen erklären die Diskrepanz.":"Οι συμπληρωματικοί περιορισμοί των δοκιμασιών εξηγούν τη διαφορά.","Entscheiden Sie, ob und wie der Fusionsverdacht nach negativem DNA-NGS weiter abgeklärt wird.":"Αποφασίστε αν και πώς θα διερευνηθεί περαιτέρω η υποψία σύντηξης μετά από αρνητικό DNA NGS.","Prätestwahrscheinlichkeit aus Morphologie/IHC festhalten.":"Καταγράψτε την pretest πιθανότητα από μορφολογία/IHC.","DNA-Assaydesign und intronische Abdeckung prüfen.":"Ελέγξτε το DNA assay design και την ενδονική κάλυψη.","RNA-basierte Fusionsdiagnostik ergänzen.":"Προσθέστε RNA-based έλεγχο συντήξεων.","FISH bei Bedarf orthogonal oder schnell ergänzen.":"Προσθέστε FISH ορθογώνια ή γρήγορα όταν χρειάζεται.","Endbefund als integrierte Fusionsevidenz formulieren.":"Διατυπώστε το τελικό report ως ολοκληρωμένη τεκμηρίωση σύντηξης.","Bei nicht verwertbarer RNA kann FISH eine praktikable orthogonale Alternative sein; für Partner-/Transkriptinformation bleibt sequenzbasierte Diagnostik überlegen.":"Αν το RNA δεν είναι αξιολογήσιμο, το FISH μπορεί να αποτελέσει πρακτική ορθογώνια εναλλακτική· sequence-based testing παραμένει ανώτερο για πληροφορία partner/μεταγραφήματος.","DNA negativ = Fusion ausgeschlossen":"DNA αρνητικό = σύντηξη αποκλείστηκε","Ignoriert intronische Assaygrenzen.":"Αγνοεί τους ενδονικούς περιορισμούς της δοκιμασίας.","Nur IHC als endgültiger Fusionsnachweis":"Μόνο IHC ως οριστική απόδειξη σύντηξης","Proteinexpression ist kontextabhängig und nicht identisch mit Sequenznachweis.":"Η πρωτεϊνική έκφραση εξαρτάται από το πλαίσιο και δεν ταυτίζεται με sequence evidence.","Beliebig größeres DNA-Panel":"Αυθαίρετα μεγαλύτερο DNA panel","Mehr Gene lösen nicht zwingend das Breakpointproblem.":"Περισσότερα γονίδια δεν λύνουν απαραίτητα το πρόβλημα του breakpoint.","Die Fusion war die ganze Zeit exprimiert":"Η σύντηξη ήταν εξαρχής εκφραζόμενη","RNA-NGS weist TPM3::ALK nach; FISH bestätigt das ALK-Rearrangement.":"RNA NGS ανιχνεύει TPM3::ALK· FISH επιβεβαιώνει την αναδιάταξη ALK.","Der negative DNA-Call war methodisch begrenzt, nicht biologisch endgültig.":"Το αρνητικό DNA call ήταν μεθοδολογικά περιορισμένο, όχι βιολογικά οριστικό.","Komplementär getestet":"Έγινε συμπληρωματικός έλεγχος","RNA weist exprimierte Fusion nach, FISH stützt Rearrangement.":"Το RNA ανιχνεύει την εκφραζόμενη σύντηξη, το FISH υποστηρίζει την αναδιάταξη.","Methodengerechte Auflösung der Diskrepanz.":"Μεθοδολογικά κατάλληλη επίλυση της ασυμφωνίας.","Nach DNA-NGS beendet":"Διακοπή μετά το DNA NGS","Relevante Fusion bleibt unentdeckt.":"Η σχετική σύντηξη παραμένει μη ανιχνευμένη.","Falsch-negatives Methodensilo.":"Ψευδώς αρνητικό μεθοδολογικό silo.","Nur IHC akzeptiert":"Αποδοχή μόνο IHC","Fusionsmechanismus nicht molekular geklärt.":"Ο μηχανισμός σύντηξης δεν έχει διευκρινιστεί μοριακά.","Unvollständige Charakterisierung.":"Ελλιπής χαρακτηρισμός.","hohe Fusionsprätestwahrscheinlichkeit + nichtinformativer/negativer DNA-Call":"υψηλή pretest πιθανότητα σύντηξης + μη πληροφοριακό/αρνητικό DNA call","RNA-Fusionsdiagnostik und/oder orthogonalen Assay ergänzen":"προσθήκη RNA fusion testing και/ή ορθογώνιας δοκιμασίας","Negativer DNA-Call nicht als universellen Ausschluss formulieren.":"Μην διατυπώνετε ένα αρνητικό DNA call ως καθολικό αποκλεισμό.","DNA- und RNA-Fusionsdiagnostik sind komplementär.":"Η DNA- και RNA-based διαγνωστική συντήξεων είναι συμπληρωματική.","Assaydesign ist Teil der Befundinterpretation.":"Το assay design αποτελεί μέρος της ερμηνείας του report.","Prätestwahrscheinlichkeit entscheidet, wann ein negativer Test nicht das Ende ist.":"Η pretest πιθανότητα καθορίζει πότε ένα αρνητικό τεστ δεν είναι το τέλος.","Trotz negativem DNA-NGS bleibt der Fusionsverdacht hoch; RNA-NGS weist TPM3::ALK nach, FISH bestätigt das Rearrangement. DNA-Negativität war durch die Breakpointabdeckung limitiert.":"Παρά το αρνητικό DNA NGS, η υποψία σύντηξης παραμένει υψηλή· RNA NGS ανιχνεύει TPM3::ALK και FISH επιβεβαιώνει την αναδιάταξη. Η DNA αρνητικότητα περιοριζόταν από την κάλυψη breakpoint.","Fusionsmethodik":"Μεθοδολογία συντήξεων","Assaygrenzen":"Περιορισμοί δοκιμασίας","Wann ist FISH schneller als RNA-NGS?":"Πότε είναι το FISH ταχύτερο από RNA NGS;","Welche RNA-QC ist für FFPE kritisch?":"Ποια RNA QC είναι κρίσιμα για FFPE;","Wie sollte ein negativer DNA-Fusionsbericht Limitationen nennen?":"Πώς πρέπει ένα αρνητικό DNA fusion report να αναφέρει τους περιορισμούς του;","Twist: DNA-negativ trotz echter Fusion":"Twist: DNA αρνητικό παρά πραγματική σύντηξη","RNA als komplementäre Ebene":"RNA ως συμπληρωματικό επίπεδο","Referenzpfad: Prätestwahrscheinlichkeit → Assaydesign → RNA/FISH":"Διαδρομή αναφοράς: pretest πιθανότητα → assay design → RNA/FISH","Liquid Biopsy negativ bei Progress: kein ctDNA-Signal ist kein Tumor-Wildtyp":"Αρνητική υγρή βιοψία στην πρόοδο: απουσία σήματος ctDNA δεν σημαίνει wild type όγκος","Liquid Biopsy negativ bei Progress":"Αρνητική υγρή βιοψία στην πρόοδο","66-jähriger Patient mit EGFR-mutiertem NSCLC und radiologischem Progress nach längerer Krankheitskontrolle. Plasma-NGS meldet „keine tumorassoziierte Variante nachweisbar“.":"Ασθενής 66 ετών με EGFR-mutant NSCLC και ακτινολογική πρόοδο μετά από παρατεταμένο έλεγχο νόσου. Plasma NGS αναφέρει «δεν ανιχνεύθηκε παραλλαγή σχετιζόμενη με όγκο». ","Darf das als fehlender Resistenzmechanismus interpretiert werden oder ist die Probe schlicht nicht informativ?":"Μπορεί αυτό να ερμηνευτεί ως απουσία μηχανισμού αντοχής ή το δείγμα είναι απλώς μη πληροφοριακό;","Therapieumstellung soll im nächsten MTB erfolgen.":"Η αλλαγή θεραπείας θα αποφασιστεί στο επόμενο MTB.","Neue Leberläsion und progrediente mediastinale Lymphknoten.":"Νέα ηπατική βλάβη και προοδευτικοί μεσοθωρακικοί λεμφαδένες.","Plasma":"Πλάσμα","Keine bekannte klonale EGFR-Mutation detektierbar; Tumorfraktionsschätzer sehr niedrig/nicht informativ.":"Η γνωστή κλωνική μετάλλαξη EGFR δεν ανιχνεύεται· η εκτίμηση tumor fraction είναι πολύ χαμηλή/μη πληροφοριακή.","Ein negativer Plasma-Report wird wie ein negativer Tumorbefund gelesen.":"Ένα αρνητικό plasma report διαβάζεται σαν αρνητικό αποτέλεσμα όγκου.","Informative von nichtinformativer Negativität unterscheiden.":"Διακρίνετε την πληροφοριακή από τη μη πληροφοριακή αρνητικότητα.","Vorbekannter Tumor":"Γνωστός όγκος","EGFR-aktivierende Mutation im ursprünglichen Tumor.":"Ενεργοποιητική μετάλλαξη EGFR στον αρχικό όγκο.","Plasma jetzt":"Πλάσμα τώρα","Weder der bekannte Treiber noch neue Resistenzalterationen detektierbar.":"Δεν ανιχνεύεται ούτε ο γνωστός driver ούτε νέες αλλοιώσεις αντοχής.","Fehlt biologisch ein Resistenzmechanismus oder fehlt im Plasma ausreichend ctDNA?":"Απουσιάζει βιολογικά μηχανισμός αντοχής ή απλώς δεν υπάρχει αρκετό ctDNA στο πλάσμα;","Wenn selbst der bekannte Tumormarker nicht erscheint, ist die Negativaussage besonders fragil.":"Αν δεν εμφανίζεται ούτε ο γνωστός ογκολογικός δείκτης, η αρνητική δήλωση είναι ιδιαίτερα εύθραυστη.","Plasma technisch korrekt gewonnen.":"Το πλάσμα συλλέχθηκε τεχνικά σωστά.","ctDNA":"ctDNA","sehr niedrige Tumorfraktion.":"πολύ χαμηλή tumor fraction.","Rebiopsie":"Επαναβιοψία","Leberläsion bildgesteuert zugänglich.":"Η ηπατική βλάβη είναι προσβάσιμη για απεικονιστικά καθοδηγούμενη βιοψία.","Tissue-Rebiopsie und Gewebeprofil möglich.":"Είναι δυνατές επαναβιοψία ιστού και tissue profiling.","Liquid-Biopsy-Informativität bewerten":"Αξιολόγηση της πληροφοριακότητας της υγρής βιοψίας","Nichtinformatives Plasma durch Tumorgewebe klären":"Διευκρίνιση μη πληροφοριακού πλάσματος με ιστό όγκου","Liquid Biopsy":"Υγρή βιοψία","Keine tumorassoziierte Variante nachweisbar; selbst der bekannte klonale EGFR-Treiber fehlt. Tumorfraktion sehr niedrig – negatives Ergebnis ist nicht als Tumor-Wildtyp interpretierbar.":"Δεν ανιχνεύεται παραλλαγή σχετιζόμενη με όγκο· απουσιάζει ακόμη και ο γνωστός κλωνικός EGFR driver. Η tumor fraction είναι πολύ χαμηλή — το αρνητικό αποτέλεσμα δεν μπορεί να ερμηνευτεί ως wild type όγκος.","Tissue-Rebiopsie":"Επαναβιοψία ιστού","Rebiopsie der progredienten Lebermetastase bestätigt Tumor und liefert ausreichend DNA für Gewebeprofiling.":"Η επαναβιοψία της προοδευτικής ηπατικής μετάστασης επιβεβαιώνει όγκο και παρέχει επαρκές DNA για tissue profiling.","Gewebeprofil":"Προφίλ ιστού","Im Progressionsgewebe bleibt der EGFR-Treiber nachweisbar; zusätzlich zeigt sich eine relevante MET-Amplifikation als Resistenzmechanismus.":"Ο EGFR driver παραμένει ανιχνεύσιμος στον ιστό προόδου· επιπλέον εμφανίζεται σημαντική ενίσχυση MET ως μηχανισμός αντοχής.","Plasma-QC":"Plasma QC","Technisch valide Probe, biologisch jedoch mit sehr niedriger/nicht informativer Tumorfraktion.":"Τεχνικά έγκυρο δείγμα, αλλά βιολογικά με πολύ χαμηλή/μη πληροφοριακή tumor fraction.","Ein nichtinformatives negatives ctDNA-Ergebnis darf einen Tumorbefund nicht ersetzen.":"Ένα μη πληροφοριακό αρνητικό αποτέλεσμα ctDNA δεν πρέπει να αντικαθιστά αποτέλεσμα ιστού όγκου.","Die negative Liquid Biopsy ist wegen sehr niedriger Tumorfraktion und fehlendem Nachweis sogar des bekannten Treibers nicht informativ. Geweberebiopsie ist deshalb sinnvoll und zeigt im Progressionsgewebe weiterhin die EGFR-Alteration sowie eine MET-Amplifikation. „Plasma negativ“ war kein Beweis für fehlende Tumoralterationen.":"Η αρνητική υγρή βιοψία είναι μη πληροφοριακή λόγω πολύ χαμηλής tumor fraction και απουσίας ακόμη και του γνωστού driver. Η επαναβιοψία ιστού είναι συνεπώς κατάλληλη και δείχνει την αλλοίωση EGFR μαζί με ενίσχυση MET στον ιστό προόδου. Το «αρνητικό πλάσμα» δεν ήταν απόδειξη απουσίας ογκολογικών αλλοιώσεων.","Teilbefund: Eine negative Liquid Biopsy muss im Kontext von ctDNA/Tumorfraktion, Tumorbiologie und bekannten Markerbefunden interpretiert werden.":"Μερικό αποτέλεσμα: αρνητική υγρή βιοψία πρέπει να ερμηνεύεται στο πλαίσιο ctDNA/tumor fraction, βιολογίας όγκου και γνωστών marker ευρημάτων.","Tumorfraktion/Shedding berücksichtigen":"Συνεκτίμηση tumor fraction/shedding","Fehlen des bekannten Treibers als Warnsignal für Nichtinformativität":"Απουσία του γνωστού driver ως προειδοποιητικό σημείο μη πληροφοριακότητας","bei klinischer Relevanz Gewebe-Reflex erwägen":"Εξετάστε reflex testing ιστού όταν είναι κλινικά σημαντικό","Falschaussage: Plasma negativ = Tumor molekular negativ":"Λανθασμένη δήλωση: αρνητικό πλάσμα = μοριακά αρνητικός όγκος","Optimale Lösung: negative Liquid Biopsy als möglicherweise nichtinformativ erkennen und bei zugänglichem Progressionsgewebe reflexartig tissue-basiert nachtesten.":"Βέλτιστη λύση: αναγνώριση της αρνητικής υγρής βιοψίας ως δυνητικά μη πληροφοριακής και reflex σε tissue-based testing όταν υπάρχει προσβάσιμος ιστός προόδου.","Progress":"Πρόοδος","Negativ – aber ohne Tumorsignal":"Αρνητικό — αλλά χωρίς σήμα όγκου","Thoraxonkologie / Liquid Biopsy / MTB":"Θωρακική Ογκολογία / Υγρή Βιοψία / MTB","Negative ctDNA-Ergebnisse von informativen positiven Ergebnissen asymmetrisch interpretieren.":"Ερμηνεύστε ασύμμετρα τα αρνητικά αποτελέσματα ctDNA σε σχέση με τα πληροφοριακά θετικά.","Tumorfraktion/Shedding und Nachweis eines bekannten Tumormarkers berücksichtigen.":"Συνεκτίμηση tumor fraction/shedding και ανίχνευσης γνωστού ογκολογικού marker.","Bei nichtinformativem Plasma und klinischer Relevanz Gewebetestung erwägen.":"Εξετάστε tissue testing όταν το πλάσμα είναι μη πληροφοριακό και το ερώτημα είναι κλινικά σημαντικό.","Plasma- und Tissue-Profiling als komplementäre Strategien verstehen.":"Κατανόηση plasma και tissue profiling ως συμπληρωματικών στρατηγικών.","Der Plasma-Report ist leer. Nicht einmal die bekannte EGFR-Mutation taucht auf. Das kann heißen „Tumor ohne Alterationen“ – oder viel wahrscheinlicher: „zu wenig Tumor-DNA im Röhrchen, um etwas sicher auszuschließen“.":"Το plasma report είναι άδειο. Δεν εμφανίζεται ούτε η γνωστή μετάλλαξη EGFR. Αυτό μπορεί να σημαίνει «όγκος χωρίς αλλοιώσεις» — ή, πολύ πιθανότερα, «πολύ λίγο tumor DNA στο σωληνάριο για να αποκλειστεί κάτι αξιόπιστα». ","66-jähriger Patient mit EGFR-mutiertem NSCLC im Progress. Plasma-NGS ist technisch valide, zeigt aber keine tumorassoziierten Varianten und eine sehr niedrige Tumorfraktion. Eine Leberläsion ist biopsierbar.":"Ασθενής 66 ετών με EGFR-mutant NSCLC σε πρόοδο. Plasma NGS είναι τεχνικά έγκυρο αλλά δεν δείχνει παραλλαγές σχετιζόμενες με όγκο και έχει πολύ χαμηλή tumor fraction. Ηπατική βλάβη είναι βιοψήσιμη.","Negativ ist asymmetrisch":"Η αρνητικότητα είναι ασύμμετρη","Ein positiver validierter ctDNA-Befund kann sehr informativ sein; ein negativer Befund kann bei niedrigem Shedding falsch-negativ sein.":"Ένα επικυρωμένο θετικό ctDNA αποτέλεσμα μπορεί να είναι πολύ πληροφοριακό· ένα αρνητικό μπορεί να είναι ψευδώς αρνητικό όταν το shedding είναι χαμηλό.","Negativaussagen brauchen Informativitätskontext.":"Οι αρνητικές δηλώσεις χρειάζονται πλαίσιο πληροφοριακότητας.","Der bekannte Treiber als interne Plausibilität":"Ο γνωστός driver ως εσωτερικός έλεγχος πιθανοφάνειας","Wenn die etablierte EGFR-Mutation nicht detektierbar ist, spricht das gegen ausreichend Tumorsignal.":"Αν η καθιερωμένη μετάλλαξη EGFR δεν ανιχνεύεται, αυτό συνηγορεί υπέρ ανεπαρκούς σήματος όγκου.","Vorwissen hilft, die Probe zu interpretieren.":"Η προηγούμενη γνώση βοηθά στην ερμηνεία του δείγματος.","Tissue bleibt relevant":"Ο ιστός παραμένει σημαντικός","Bei nichtinformativer ctDNA kann Gewebe einen Resistenzmechanismus sichtbar machen.":"Όταν το ctDNA είναι μη πληροφοριακό, ο ιστός μπορεί να αποκαλύψει μηχανισμό αντοχής.","Liquid Biopsy ersetzt Gewebe nicht in jeder Situation.":"Η υγρή βιοψία δεν αντικαθιστά τον ιστό σε κάθε περίπτωση.","EGFR-mutierter Primärtumor":"EGFR-mutant πρωτοπαθής όγκος","Plasma-NGS":"Plasma NGS","keine tumorassoziierte Variante":"καμία παραλλαγή σχετιζόμενη με όγκο","Tumorfraktion":"Tumor fraction","sehr niedrig / nicht informativ":"πολύ χαμηλή / μη πληροφοριακή","Plasma technisch korrekt.":"Το πλάσμα είναι τεχνικά επαρκές.","Progressionsgewebe zugänglich.":"Προσβάσιμος ιστός προόδου.","Copy-number-/Fusionserfassung kann zusätzlich von Assay und Tumorfraktion abhängen.":"Η ανίχνευση copy-number/συντήξεων μπορεί επιπλέον να εξαρτάται από τη δοκιμασία και την tumor fraction.","Wie ist eine negative ctDNA-Analyse bei sehr niedriger Tumorfraktion zu bewerten?":"Πώς πρέπει να αξιολογηθεί αρνητική ανάλυση ctDNA με πολύ χαμηλή tumor fraction;","Als potenziell nichtinformativ/falsch-negativ; Tumoralterationen sind damit nicht sicher ausgeschlossen.":"Ως δυνητικά μη πληροφοριακή/ψευδώς αρνητική· οι ογκολογικές αλλοιώσεις δεν αποκλείονται αξιόπιστα.","Der Tumor ist sicher wildtyp.":"Ο όγκος είναι σίγουρα wild type.","Es liegt sicher kein Tumor mehr vor.":"Σίγουρα δεν υπάρχει πλέον όγκος.","Nur Keimbahnvarianten sind möglich.":"Είναι δυνατές μόνο βλαστικές παραλλαγές.","ctDNA-Sensitivität hängt vom Tumorshedding und der Tumorfraktion ab.":"Η ευαισθησία ctDNA εξαρτάται από tumor shedding και tumor fraction.","Warum ist das Fehlen der bekannten klonalen EGFR-Mutation besonders wichtig?":"Γιατί είναι ιδιαίτερα σημαντική η απουσία της γνωστής κλωνικής μετάλλαξης EGFR;","Es ist ein Warnsignal, dass im Plasma möglicherweise kaum detektierbare Tumor-DNA vorliegt.":"Είναι προειδοποιητικό σημείο ότι μπορεί να υπάρχει ελάχιστο ανιχνεύσιμο tumor DNA στο πλάσμα.","Der Tumor muss EGFR sicher verloren haben.":"Ο όγκος πρέπει σίγουρα να έχει χάσει το EGFR.","Der gesamte Labortest ist technisch zwingend ungültig.":"Ολόκληρη η εργαστηριακή εξέταση είναι υποχρεωτικά τεχνικά άκυρη.","Es ist ohne Bedeutung.":"Δεν έχει σημασία.","Der bekannte Marker dient als biologische Plausibilitätskontrolle.":"Ο γνωστός marker λειτουργεί ως βιολογικός έλεγχος πιθανοφάνειας.","Was ist bei zugänglichem Progressionsgewebe der sinnvollste nächste Schritt?":"Ποιο είναι το καταλληλότερο επόμενο βήμα όταν υπάρχει προσβάσιμος ιστός προόδου;","Geweberebiopsie/Gewebeprofiling zur Resistenzklärung.":"Επαναβιοψία ιστού/tissue profiling για διευκρίνιση αντοχής.","Keine weitere Diagnostik.":"Καμία περαιτέρω διαγνωστική.","Nur dasselbe Plasmaresultat erneut interpretieren.":"Μόνο επανερμηνεία του ίδιου αποτελέσματος πλάσματος.","Methylierungsarray.":"Methylation array.","Nichtinformative ctDNA sollte bei relevanter Frage durch Gewebe ergänzt werden.":"Μη πληροφοριακό ctDNA πρέπει να συμπληρώνεται με ιστό όταν το ερώτημα είναι κλινικά σημαντικό.","Gewebe zeigt den bekannten EGFR-Treiber plus MET-Amplifikation. Was lehrt die Diskrepanz?":"Ο ιστός δείχνει τον γνωστό EGFR driver μαζί με ενίσχυση MET. Τι διδάσκει η ασυμφωνία;","Das negative Plasma war wegen geringer Tumorfraktion nicht ausreichend zum Ausschluss eines Resistenzmechanismus.":"Το αρνητικό αποτέλεσμα πλάσματος ήταν ανεπαρκές για αποκλεισμό μηχανισμού αντοχής λόγω χαμηλής tumor fraction.","Das Gewebe muss falsch sein.":"Ο ιστός πρέπει να είναι λάθος.","Liquid Biopsy ist grundsätzlich nutzlos.":"Η υγρή βιοψία είναι γενικά άχρηστη.","Beide Befunde bedeuten dasselbe.":"Και τα δύο ευρήματα σημαίνουν το ίδιο.","Liquid Biopsy ist wertvoll, aber negative Ergebnisse sind kontextabhängig.":"Η υγρή βιοψία είναι πολύτιμη, αλλά τα αρνητικά αποτελέσματα εξαρτώνται από το πλαίσιο.","Entscheiden Sie, ob die negative Liquid Biopsy die Resistenzdiagnostik beendet oder eine Tissue-Reflexstrategie nötig ist.":"Αποφασίστε αν η αρνητική υγρή βιοψία ολοκληρώνει τον έλεγχο αντοχής ή απαιτεί tissue-reflex στρατηγική.","Plasma-QC und Tumorfraktion bewerten.":"Αξιολόγηση plasma QC και tumor fraction.","Bekannten Tumormarker als Plausibilitätsanker nutzen.":"Χρησιμοποιήστε τον γνωστό ογκολογικό marker ως άγκυρα πιθανοφάνειας.","Negativbefund nicht überinterpretieren.":"Μην υπερερμηνεύετε το αρνητικό αποτέλεσμα.","Bei zugänglichem Progressionsgewebe Gewebetestung ergänzen.":"Προσθέστε tissue testing όταν υπάρχει προσβάσιμος ιστός προόδου.","Diskrepanz integriert berichten.":"Αναφέρετε ολοκληρωμένα την ασυμφωνία.","Wenn Gewebe nicht zugänglich ist, kann eine erneute Plasmaanalyse zu einem biologisch günstigeren Zeitpunkt oder eine alternative Flüssigkeit je nach Entität erwogen werden; das ersetzt keine pauschale Garantie.":"Αν ο ιστός δεν είναι προσβάσιμος, μπορεί να εξεταστεί επανάληψη plasma analysis σε βιολογικά ευνοϊκότερο χρόνο ή εναλλακτικό υγρό ανάλογα με την οντότητα· αυτό δεν αποτελεί καθολική εγγύηση.","Plasma negativ = Tumor negativ":"Αρνητικό πλάσμα = αρνητικός όγκος","Ignoriert falsch-negative Ergebnisse bei niedrigem Shedding.":"Αγνοεί ψευδώς αρνητικά αποτελέσματα με χαμηλό shedding.","Liquid Biopsy generell verwerfen":"Γενική απόρριψη της υγρής βιοψίας","Positive/informative Ergebnisse können klinisch sehr nützlich sein.":"Θετικά/πληροφοριακά αποτελέσματα μπορεί να είναι πολύ χρήσιμα κλινικά.","Tumorfraktion ignorieren":"Αγνόηση tumor fraction","Entfernt den wichtigsten Informativitätsparameter.":"Αφαιρεί τον σημαντικότερο δείκτη πληροφοριακότητας.","Das Gewebe findet, was das Plasma nicht sehen konnte":"Ο ιστός βρίσκει αυτό που το πλάσμα δεν μπορούσε να δει","Tissue-Profiling zeigt den bekannten Treiber und eine MET-Amplifikation.":"Το tissue profiling δείχνει τον γνωστό driver και ενίσχυση MET.","Die diagnostische Frage war nicht „war der Plasmatest technisch okay?“, sondern „war er biologisch informativ genug, um etwas auszuschließen?“":"Το διαγνωστικό ερώτημα δεν ήταν «ήταν τεχνικά σωστό το plasma test;» αλλά «ήταν βιολογικά αρκετά πληροφοριακό ώστε να αποκλείσει κάτι;». ","Nichtinformativ erkannt":"Αναγνώριση μη πληροφοριακού αποτελέσματος","Tissue-Reflex deckt Resistenzmechanismus auf.":"Το tissue reflex αποκαλύπτει μηχανισμό αντοχής.","Korrekte Liquid-Biopsy-Logik.":"Σωστή λογική υγρής βιοψίας.","Nach negativem Plasma beendet":"Διακοπή μετά από αρνητικό πλάσμα","Resistenzmechanismus bleibt unentdeckt.":"Ο μηχανισμός αντοχής παραμένει μη ανιχνευμένος.","Falsch-negatives Overconfidence.":"Υπερβολική βεβαιότητα από ψευδώς αρνητικό αποτέλεσμα.","Liquid Biopsy generell abgelehnt":"Γενική απόρριψη υγρής βιοψίας","Methodennutzen wird unnötig negiert.":"Η χρησιμότητα της μεθόδου ακυρώνεται αδικαιολόγητα.","Zu pauschal.":"Υπερβολικά γενικό.","negatives ctDNA + niedrige Tumorfraktion/fehlender bekannter Treiber":"αρνητικό ctDNA + χαμηλή tumor fraction/απουσία γνωστού driver","Ergebnis als nichtinformativ kennzeichnen und Gewebe erwägen":"χαρακτηρισμός αποτελέσματος ως μη πληροφοριακού και εξέταση ιστού","Keine sichere Negativaussage über Tumorgenom.":"Δεν είναι δυνατή αξιόπιστη αρνητική δήλωση για το γονιδίωμα του όγκου.","Negative ctDNA-Befunde sind kontextabhängig.":"Τα αρνητικά ευρήματα ctDNA εξαρτώνται από το πλαίσιο.","Tumorfraktion und Shedding gehören zur Interpretation.":"Tumor fraction και shedding ανήκουν στην ερμηνεία.","Plasma und Gewebe ergänzen sich.":"Πλάσμα και ιστός αλληλοσυμπληρώνονται.","Negative Liquid Biopsy bei sehr niedriger Tumorfraktion und fehlendem bekanntem Treiber ist nicht ausreichend zum Ausschluss von Resistenzalterationen; Gewebe-Reflex zeigt hier MET-Amplifikation.":"Αρνητική υγρή βιοψία με πολύ χαμηλή tumor fraction και απουσία γνωστού driver δεν επαρκεί για αποκλεισμό αλλοιώσεων αντοχής· το tissue reflex αποκαλύπτει εδώ ενίσχυση MET.","ctDNA-Informativität":"Πληροφοριακότητα ctDNA","Reflex-Tissue":"Tissue reflex","Negativbefund":"Αρνητικό αποτέλεσμα","Welche Tumorlokalisationen sheddern schlecht?":"Ποιες εντοπίσεις όγκου έχουν χαμηλό shedding;","Wann ist Plasma besonders sinnvoll?":"Πότε είναι ιδιαίτερα χρήσιμο το πλάσμα;","Wie sollte Tumorfraktion im Report kommuniziert werden?":"Πώς πρέπει να αναφέρεται η tumor fraction στο report;","Twist: technisch negatives Plasma, biologisch nichtinformativ":"Twist: τεχνικά αρνητικό πλάσμα, βιολογικά μη πληροφοριακό","Bekannter Treiber als Plausibilitätsanker":"Γνωστός driver ως άγκυρα πιθανοφάνειας","Referenzpfad: Tumorfraktion → Negativität begrenzen → Tissue-Reflex":"Διαδρομή αναφοράς: tumor fraction → περιορισμός αρνητικής ερμηνείας → tissue reflex","NPM1-MRD: diagnostisches NGS negativ, gezielte PCR noch positiv":"NPM1 MRD: διαγνωστικό NGS αρνητικό, στοχευμένη PCR ακόμη θετική","qPCR/dPCR für MRD statt breites Pa…":"qPCR/dPCR για MRD αντί ευρέος panel…","Hämatologie / Molekulares Tumorboard":"Αιματολογία / Μοριακό Ογκολογικό Συμβούλιο","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung in morphologischer kompletter Remission. Ein breites myeloisches NGS-Panel ist „negativ“.":"Ασθενής 52 ετών με NPM1-mutated AML μετά από consolidation σε μορφολογική πλήρη ύφεση. Ένα ευρύ μυελοειδές NGS panel είναι «αρνητικό». ","Reicht das breite Panel für die MRD-Beurteilung oder braucht es die hochsensitive, zielgerichtete NPM1-Methode?":"Αρκεί το ευρύ panel για αξιολόγηση MRD ή απαιτείται η υψηλής ευαισθησίας στοχευμένη μέθοδος NPM1;","MRD-Status soll vor der nächsten risikoadaptierten Entscheidung vorliegen.":"Η κατάσταση MRD πρέπει να είναι διαθέσιμη πριν από την επόμενη risk-adapted απόφαση.","Diagnosemarker":"Διαγνωστικός marker","NPM1-Mutation bei Erstdiagnose eindeutig dokumentiert.":"Η μετάλλαξη NPM1 έχει τεκμηριωθεί σαφώς στην αρχική διάγνωση.","<5 % Blasten, komplette morphologische Remission.":"<5% βλάστες, πλήρης μορφολογική ύφεση.","Breites NGS":"Ευρύ NGS","Keine pathogene Variante oberhalb der diagnostischen Reporting-Grenzen.":"Καμία παθογόνος παραλλαγή πάνω από τα διαγνωστικά όρια αναφοράς.","Breite wird mit Sensitivität verwechselt.":"Η ευρύτητα συγχέεται με την ευαισθησία.","morphologisch in Remission.":"σε μορφολογική ύφεση.","Zielmarker":"Marker-στόχος","NPM1 patientenspezifisch bekannt.":"Γνωστός patient-specific marker NPM1.","Ist unterhalb der Sensitivität eines diagnostischen Panels noch messbare Resterkrankung nachweisbar?":"Μπορεί να ανιχνευθεί μετρήσιμη υπολειπόμενη νόσος κάτω από την ευαισθησία ενός διαγνωστικού panel;","MRD ist eine andere analytische Aufgabe als initiale Genotypisierung.":"Η MRD είναι διαφορετικό αναλυτικό έργο από την αρχική γονοτύπηση.","Knochenmark, ausreichende Nukleinsäurequalität.":"Μυελός οστών, επαρκής ποιότητα νουκλεϊκών οξέων.","bekannter NPM1-Marker.":"γνωστός marker NPM1.","Methodenwahl":"Επιλογή μεθόδου","gezielte qPCR/dPCR-artige MRD-Methode vs. breites Panel.":"στοχευμένη qPCR/dPCR-like μέθοδος MRD έναντι ευρέος panel.","Beide technisch verfügbar; entscheidend ist die validierte Sensitivität für die Fragestellung.":"Και τα δύο είναι τεχνικά διαθέσιμα· καθοριστική είναι η επικυρωμένη ευαισθησία για το κλινικό ερώτημα.","Sensitive zielgerichtete MRD-Methode":"Ευαίσθητη στοχευμένη μέθοδος MRD","Zielgerichtete MRD-PCR":"Στοχευμένη PCR MRD","Patientenspezifischer NPM1-Marker bleibt in niedriger Menge reproduzierbar positiv; messbare Resterkrankung ist trotz morphologischer Remission nachweisbar.":"Ο patient-specific marker NPM1 παραμένει αναπαραγώγιμα θετικός σε χαμηλό επίπεδο· μετρήσιμη υπολειπόμενη νόσος ανιχνεύεται παρά τη μορφολογική ύφεση.","Breites myeloisches Panel":"Ευρύ μυελοειδές panel","Keine Variante oberhalb der diagnostischen Panelgrenzen; dieser Negativbefund erreicht nicht automatisch die für NPM1-MRD erforderliche Sensitivität.":"Καμία παραλλαγή πάνω από τα όρια του διαγνωστικού panel· αυτό το αρνητικό αποτέλεσμα δεν επιτυγχάνει αυτομάτως την ευαισθησία που απαιτείται για NPM1 MRD.","Komplette morphologische Remission.":"Πλήρης μορφολογική ύφεση.","Diagnostische Panelbreite und MRD-Sensitivität sind unterschiedliche Leistungsmerkmale.":"Η ευρύτητα διαγνωστικού panel και η ευαισθησία MRD είναι διαφορετικά χαρακτηριστικά απόδοσης.","Das negative diagnostische NGS-Panel beweist keine molekulare MRD-Negativität. Da ein geeigneter NPM1-Zielmarker bekannt ist, ist eine validierte hochsensitive zielgerichtete qPCR/dPCR-basierte Strategie angemessen. Diese bleibt niedrig positiv und zeigt messbare Resterkrankung trotz morphologischer Remission.":"Ένα αρνητικό διαγνωστικό NGS panel δεν αποδεικνύει μοριακή MRD αρνητικότητα. Εφόσον είναι γνωστός κατάλληλος NPM1 marker, ενδείκνυται επικυρωμένη υψηλής ευαισθησίας στοχευμένη στρατηγική qPCR/dPCR. Παραμένει χαμηλού επιπέδου θετική και δείχνει μετρήσιμη υπολειπόμενη νόσο παρά τη μορφολογική ύφεση.","Teilbefund: Für MRD muss die Methode zur erwarteten sehr niedrigen Krankheitslast und zum bekannten Zielmarker passen; ein breites Diagnostikpanel ist nicht automatisch sensitiv genug.":"Μερικό αποτέλεσμα: για MRD η μέθοδος πρέπει να ταιριάζει στο αναμενόμενο πολύ χαμηλό φορτίο νόσου και στον γνωστό marker-στόχο· ένα ευρύ διαγνωστικό panel δεν είναι αυτομάτως αρκετά ευαίσθητο.","Diagnostik vs. MRD als unterschiedliche Testzwecke trennen":"Διαχωρίστε τη διαγνωστική από τη MRD ως διαφορετικούς σκοπούς εξέτασης","assayvalidierte Sensitivität berücksichtigen":"Συνεκτίμηση της assay-validated ευαισθησίας","stabilen geeigneten Zielmarker nutzen":"Χρησιμοποιήστε σταθερό κατάλληλο marker-στόχο","Falschaussage: breiteres Panel ist für MRD automatisch besser":"Λανθασμένη δήλωση: ένα ευρύτερο panel είναι αυτομάτως καλύτερο για MRD","Optimale Lösung: bekannten NPM1-Marker mit validierter hochsensitiver Zielmethode verfolgen; diagnostisches NGS negativ nicht mit MRD-negativ gleichsetzen.":"Βέλτιστη λύση: παρακολούθηση του γνωστού marker NPM1 με επικυρωμένη υψηλής ευαισθησίας στοχευμένη μέθοδο· μην εξισώνετε αρνητικό διαγνωστικό NGS με MRD αρνητικό.","MRD":"MRD","NPM1":"NPM1","qPCR":"qPCR","dPCR":"dPCR","Breit negativ, hochsensitiv positiv":"Ευρύ αρνητικό, υψηλής ευαισθησίας θετικό","Hämatologie / molekulare MRD-Diagnostik":"Αιματολογία / μοριακή διαγνωστική MRD","Diagnostisches NGS von MRD-Methodik unterscheiden.":"Διακρίνετε το διαγνωστικό NGS από τη μεθοδολογία MRD.","Bei bekanntem geeignetem Marker eine validierte hochsensitive Zielmethode wählen.":"Όταν υπάρχει κατάλληλος γνωστός marker, επιλέξτε επικυρωμένη υψηλής ευαισθησίας στοχευμένη μέθοδο.","Analytische Sensitivität passend zur klinischen Fragestellung bewerten.":"Αξιολογήστε αναλυτική ευαισθησία κατάλληλη για το κλινικό ερώτημα.","Morphologische Remission nicht mit molekularer MRD-Negativität gleichsetzen.":"Μην εξισώνετε μορφολογική ύφεση με μοριακή MRD αρνητικότητα.","Im Abschlussbefund steht zweimal „negativ“: Morphologie unauffällig, breites NGS ohne Treffer. Die NPM1-MRD-PCR sagt trotzdem positiv. Der Widerspruch ist nur scheinbar – die Methoden fragen auf völlig unterschiedlichen Tiefen.":"Το τελικό report γράφει δύο φορές «αρνητικό»: η μορφολογία είναι χωρίς παθολογικά ευρήματα, το ευρύ NGS δεν βρίσκει τίποτα. Παρ’ όλα αυτά η NPM1 MRD PCR είναι θετική. Η αντίφαση είναι μόνο φαινομενική — οι μέθοδοι εξετάζουν τη νόσο σε εντελώς διαφορετικά βάθη.","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung. Morphologisch komplette Remission und diagnostisches Panel ohne Varianten oberhalb seiner Reporting-Grenzen. Für die MRD-Frage steht ein bekannter NPM1-Zielmarker zur Verfügung.":"Ασθενής 52 ετών με NPM1-mutated AML μετά από consolidation. Μορφολογική πλήρης ύφεση και διαγνωστικό panel χωρίς παραλλαγές πάνω από τα όρια αναφοράς του. Για το ερώτημα MRD υπάρχει γνωστός marker-στόχος NPM1.","Breite ist nicht Tiefe":"Η ευρύτητα δεν είναι βάθος","Ein diagnostisches Panel kann viele Gene erfassen, aber nicht dieselbe Nachweisgrenze wie eine fokussierte MRD-Methode erreichen.":"Ένα διαγνωστικό panel μπορεί να καλύπτει πολλά γονίδια χωρίς να φτάνει στο ίδιο όριο ανίχνευσης με στοχευμένη μέθοδο MRD.","Methodenauswahl folgt der Frage.":"Η επιλογή μεθόδου ακολουθεί το ερώτημα.","Bekannter Marker ist ein Vorteil":"Ένας γνωστός marker είναι πλεονέκτημα","NPM1 ist bei Diagnose dokumentiert und gezielt verfolgbar.":"Το NPM1 έχει τεκμηριωθεί στη διάγνωση και μπορεί να παρακολουθηθεί στοχευμένα.","MRD kann patientenspezifisch hochsensitiv sein.":"Η MRD μπορεί να είναι υψηλής ευαισθησίας και patient-specific.","Remission hat Ebenen":"Η ύφεση έχει επίπεδα","Morphologische CR und molekulare MRD sind nicht synonym.":"Μορφολογική CR και μοριακή MRD δεν είναι συνώνυμα.","Mehrere Ebenen der Krankheitslast koexistieren.":"Συνυπάρχουν πολλαπλά επίπεδα φορτίου νόσου.","NPM1-mutierte AML":"NPM1-mutated AML","komplette Remission":"πλήρης ύφεση","kein Call oberhalb diagnostischer Reporting-Grenze":"κανένα call πάνω από το διαγνωστικό όριο αναφοράς","Knochenmarkmaterial ausreichend.":"Επαρκές υλικό μυελού οστών.","Zielmarker bekannt.":"Γνωστός marker-στόχος.","Die konkrete Nachweisgrenze ist labor- und assayvalidiert; keine universelle Prozentzahl wird vorausgesetzt.":"Το ακριβές όριο ανίχνευσης είναι επικυρωμένο από το εργαστήριο και τη δοκιμασία· δεν υποτίθεται καθολικό ποσοστό.","Welche Methode passt am besten zur MRD-Frage bei bekanntem NPM1-Zielmarker?":"Ποια μέθοδος ταιριάζει καλύτερα στο ερώτημα MRD όταν υπάρχει γνωστός marker-στόχος NPM1;","Validierte hochsensitive zielgerichtete qPCR/dPCR-basierte MRD-Methode.":"Επικυρωμένη υψηλής ευαισθησίας στοχευμένη μέθοδος MRD βασισμένη σε qPCR/dPCR.","Nur ein möglichst breites diagnostisches Panel.":"Μόνο το ευρύτερο δυνατό διαγνωστικό panel.","Nur HE-Morphologie.":"Μόνο μορφολογία HE.","MRD verlangt hohe Sensitivität für einen geeigneten Zielmarker.":"Η MRD απαιτεί υψηλή ευαισθησία για κατάλληλο marker-στόχο.","Was bedeutet ein negatives diagnostisches NGS-Panel hier?":"Τι σημαίνει εδώ ένα αρνητικό διαγνωστικό NGS panel;","Keine Variante oberhalb seiner validierten Grenzen; molekulare MRD unterhalb dieser Grenzen kann bestehen.":"Καμία παραλλαγή πάνω από τα επικυρωμένα όριά του· μοριακή MRD κάτω από αυτά τα όρια μπορεί να εξακολουθεί να υπάρχει.","Absolut keine Leukämiezelle vorhanden.":"Δεν υπάρχει απολύτως κανένα λευχαιμικό κύτταρο.","MRD ist sicher negativ, unabhängig vom Assay.":"Η MRD είναι σίγουρα αρνητική ανεξάρτητα από τη δοκιμασία.","Die ursprüngliche AML-Diagnose war falsch.":"Η αρχική διάγνωση AML ήταν λανθασμένη.","Negativität gilt nur innerhalb der analytischen Leistungsfähigkeit.":"Η αρνητικότητα ισχύει μόνο εντός των ορίων αναλυτικής απόδοσης.","Morphologische komplette Remission und MRD-positiv – ist das möglich?":"Μορφολογική πλήρης ύφεση και MRD θετική — είναι δυνατό;","Ja; MRD-Methoden erfassen deutlich niedrigere Krankheitslast als Morphologie.":"Ναι· οι μέθοδοι MRD ανιχνεύουν πολύ χαμηλότερο φορτίο νόσου από τη μορφολογία.","Nein, die Befunde schließen sich aus.":"Όχι, τα ευρήματα αλληλοαποκλείονται.","MRD ist immer Artefakt.":"Η MRD είναι πάντα τεχνούργημα.","MRD hat keine klinische Bedeutung.":"Η MRD δεν έχει κλινική σημασία.","Die Ebenen messen unterschiedliche Sensitivitätsbereiche.":"Τα επίπεδα μετρούν διαφορετικά εύρη ευαισθησίας.","Die NPM1-MRD-Methode ist reproduzierbar niedrig positiv. Wie lautet die Kernaussage?":"Η μέθοδος NPM1 MRD είναι αναπαραγώγιμα χαμηλά θετική. Ποια είναι η βασική δήλωση;","Molekulare MRD ist nachweisbar, obwohl Morphologie und diagnostisches Panel negativ sind.":"Μοριακή MRD ανιχνεύεται παρότι η μορφολογία και το διαγνωστικό panel είναι αρνητικά.","Das breite Panel überschreibt die MRD-PCR.":"Το ευρύ panel υπερισχύει της MRD PCR.","CR bedeutet zwingend null Resterkrankung.":"CR σημαίνει υποχρεωτικά μηδενική υπολειπόμενη νόσο.","Der Zielmarker darf nicht verwendet werden.":"Ο marker-στόχος δεν πρέπει να χρησιμοποιηθεί.","Die gezielte validierte MRD-Methode ist für diese Frage geeigneter.":"Η επικυρωμένη στοχευμένη μέθοδος MRD είναι καταλληλότερη για αυτό το ερώτημα.","Wählen und begründen Sie die Methode zur molekularen MRD-Beurteilung.":"Επιλέξτε και αιτιολογήστε τη μέθοδο για αξιολόγηση μοριακής MRD.","Klinische Frage als MRD statt Diagnose definieren.":"Ορίστε το κλινικό ερώτημα ως MRD και όχι ως διάγνωση.","Geeigneten bekannten Zielmarker identifizieren.":"Εντοπίστε κατάλληλο γνωστό marker-στόχο.","Assayvalidierte Sensitivität berücksichtigen.":"Συνεκτιμήστε την assay-validated ευαισθησία.","Zielgerichtete MRD-PCR verwenden.":"Χρησιμοποιήστε στοχευμένη MRD PCR.","Ergebnis getrennt von Morphologie und diagnostischem Panel berichten.":"Αναφέρετε το αποτέλεσμα χωριστά από μορφολογία και διαγνωστικό panel.","NGS-basierte MRD kann in validierten spezialisierten Ansätzen sinnvoll sein; der Fall richtet sich gegen die unkritische Verwendung eines routinemäßigen diagnostischen Breitenpanels als MRD-Ersatz.":"NGS-based MRD μπορεί να είναι χρήσιμη σε επικυρωμένες εξειδικευμένες προσεγγίσεις· το περιστατικό στρέφεται κατά της άκριτης χρήσης ενός routine ευρέος διαγνωστικού panel ως υποκατάστατου MRD.","Breiter = sensitiver":"Ευρύτερο = πιο ευαίσθητο","Verwechselt Panelumfang mit Nachweisgrenze.":"Συγχέει το εύρος του panel με το όριο ανίχνευσης.","Morphologische CR = MRD-negativ":"Μορφολογική CR = MRD αρνητική","Ignoriert unterschiedliche Sensitivitätsebenen.":"Αγνοεί διαφορετικά επίπεδα ευαισθησίας.","Jede Persistenzmutation als MRD":"Κάθε επίμονη μετάλλαξη ως MRD","Nicht jeder Marker ist gleich geeignet; clonal hematopoiesis kann einzelne Gene persistieren lassen.":"Δεν είναι κάθε marker εξίσου κατάλληλος· η κλωνική αιμοποίηση μπορεί να προκαλεί επιμονή ορισμένων γονιδίων.","Die Resterkrankung liegt unter der Paneloberfläche":"Η υπολειπόμενη νόσος βρίσκεται κάτω από την επιφάνεια του panel","Gezielte NPM1-MRD bleibt reproduzierbar positiv.":"Η στοχευμένη NPM1 MRD παραμένει αναπαραγώγιμα θετική.","Der Fall zeigt, warum Testzweck und Sensitivität wichtiger sind als maximale Genbreite.":"Το περιστατικό δείχνει γιατί ο σκοπός της εξέτασης και η ευαισθησία έχουν μεγαλύτερη σημασία από τη μέγιστη γονιδιακή ευρύτητα.","Zielgerichtete MRD":"Στοχευμένη MRD","NPM1-MRD korrekt nachgewiesen.":"NPM1 MRD ανιχνεύθηκε σωστά.","Fragestellungsgerechte Methodik.":"Μεθοδολογία κατάλληλη για το ερώτημα.","Nur breites Panel":"Μόνο ευρύ panel","Niedrige Resterkrankung wird fälschlich als negativ interpretiert.":"Χαμηλού επιπέδου υπολειπόμενη νόσος ερμηνεύεται λανθασμένα ως αρνητική.","Sensitivitätsproblem.":"Πρόβλημα ευαισθησίας.","Nur Morphologie":"Μόνο μορφολογία","Molekulare Resterkrankung bleibt unsichtbar.":"Η μοριακή υπολειπόμενη νόσος παραμένει αόρατη.","Unvollständig.":"Ελλιπές.","bekannter geeigneter MRD-Marker":"γνωστός κατάλληλος marker MRD","validierte hochsensitive Zielmethode nutzen":"χρήση επικυρωμένης υψηλής ευαισθησίας στοχευμένης μεθόδου","Diagnostische Panelnegativität nicht als MRD-Negativität umdeuten.":"Μην επανερμηνεύετε αρνητικό διαγνωστικό panel ως MRD αρνητικότητα.","MRD ist eine eigene analytische Aufgabe.":"Η MRD είναι ξεχωριστό αναλυτικό έργο.","Breite und Sensitivität sind unabhängige Dimensionen.":"Ευρύτητα και ευαισθησία είναι ανεξάρτητες διαστάσεις.","Der beste Test ist der, dessen validierte Leistung zur klinischen Frage passt.":"Η καλύτερη εξέταση είναι εκείνη της οποίας η επικυρωμένη απόδοση ταιριάζει στο κλινικό ερώτημα.","Bei bekannter NPM1-mutierter AML ist die validierte zielgerichtete MRD-PCR der geeignete Test; diagnostisches NGS negativ schließt niedriggradige molekulare Resterkrankung nicht aus.":"Σε γνωστή NPM1-mutated AML, η επικυρωμένη στοχευμένη MRD PCR είναι η κατάλληλη εξέταση· αρνητικό διαγνωστικό NGS δεν αποκλείει χαμηλού επιπέδου μοριακή υπολειπόμενη νόσο.","MRD-Methodenwahl":"Επιλογή μεθόδου MRD","Sensitivität":"Ευαισθησία","Befundebenen":"Επίπεδα αποτελεσμάτων","Welche Mutationen sind für AML-MRD problematisch?":"Ποιες μεταλλάξεις είναι προβληματικές για AML MRD;","Wann ist dPCR gegenüber qPCR sinnvoll?":"Πότε είναι χρήσιμη η dPCR έναντι της qPCR;","Welche Rolle hat NGS-basierte MRD?":"Ποιος είναι ο ρόλος της NGS-based MRD;","Twist: diagnostisches NGS negativ, MRD-PCR positiv":"Twist: διαγνωστικό NGS αρνητικό, MRD PCR θετική","Breite ≠ Sensitivität":"Ευρύτητα ≠ ευαισθησία","Referenzpfad: Zielmarker → validierte MRD-Methode → getrennte Interpretation":"Διαδρομή αναφοράς: marker-στόχος → επικυρωμένη μέθοδος MRD → ξεχωριστή ερμηνεία","MGMT-Frage im gesicherten Glioblastom: lokaler Marker statt Classifier-Overkill":"Ερώτημα MGMT σε επιβεβαιωμένο γλοιοβλάστωμα: τοπικός δείκτης αντί για υπερβολική χρήση ταξινομητή","Bisulfit-PCR vs. Methylierungsarra…":"PCR με διθειώδες έναντι συστοιχίας μεθυλίωσης…","69-jähriger Patient mit histologisch und molekular eindeutig klassifiziertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung wird der MGMT-Promotor-Methylierungsstatus benötigt.":"Ασθενής 69 ετών με ιστολογικά και μοριακά σαφώς ταξινομημένο γλοιοβλάστωμα, IDH wild type. Για τον σχεδιασμό της θεραπείας απαιτείται η κατάσταση μεθυλίωσης του υποκινητή MGMT.","Braucht dieser Fall einen genomeweiten Methylierungsclassifier oder eine validierte zielgerichtete MGMT-Methylierungsanalyse?":"Χρειάζεται αυτή η περίπτωση ταξινομητή μεθυλίωσης σε επίπεδο γονιδιώματος ή επικυρωμένη στοχευμένη ανάλυση μεθυλίωσης MGMT;","Adjuvante Therapieplanung steht unmittelbar an.":"Ο σχεδιασμός της επικουρικής θεραπείας επίκειται.","Glioblastom, IDH-Wildtyp, integriert gesichert; keine offene Entitätsfrage.":"Γλοιοβλάστωμα, IDH wild type, τεκμηριωμένη ολοκληρωμένη διάγνωση· δεν υπάρχει ανοιχτό ερώτημα οντότητας.","Offene Biomarkerfrage":"Ανοιχτό ερώτημα βιοδείκτη","MGMT-Promotor-Methylierung.":"Μεθυλίωση του υποκινητή MGMT.","Ein technologisch umfassenderes Methylierungsarray wird automatisch als „besser“ angesehen.":"Μια τεχνολογικά πιο ολοκληρωμένη συστοιχία μεθυλίωσης θεωρείται αυτόματα «καλύτερη».","Testscope an die konkrete klinische Frage und lokale Validierung koppeln.":"Αντιστοιχίστε το εύρος της εξέτασης στο συγκεκριμένο κλινικό ερώτημα και στην τοπική επικύρωση.","Hochgradiges diffuses Astrozytom mit Nekrosen und mikrovaskulärer Proliferation.":"Υψηλού βαθμού διάχυτο αστροκύττωμα με νέκρωση και μικροαγγειακό πολλαπλασιασμό.","IDH-Wildtyp; integrierte Diagnose steht.":"IDH wild type· η ολοκληρωμένη διάγνωση έχει τεκμηριωθεί.","MGMT-Promotor-Methylierungsstatus.":"Κατάσταση μεθυλίωσης του υποκινητή MGMT.","Klassifikation und prädiktiver Einzelmarker sind zwei verschiedene Aufgaben.":"Η ταξινόμηση και ένας μεμονωμένος προβλεπτικός βιοδείκτης είναι δύο διαφορετικά καθήκοντα.","FFPE-Resektat, ausreichender Tumoranteil.":"Δείγμα εκτομής FFPE, επαρκής περιεκτικότητα σε όγκο.","für beide Verfahren ausreichend.":"επαρκές και για τις δύο μεθόδους.","Lokale Validierung":"Τοπική επικύρωση","Bisulfit-basierte Zielmethode ist für MGMT klinisch validiert; das Array wird im Labor primär für CNS-Klassifikation eingesetzt.":"Η στοχευμένη μέθοδος με διθειώδες είναι κλινικά επικυρωμένη για MGMT· η συστοιχία χρησιμοποιείται στο συγκεκριμένο εργαστήριο κυρίως για ταξινόμηση όγκων ΚΝΣ.","Array wäre teurer/langsamer und beantwortet hier keine offene Klassifikationsfrage.":"Η συστοιχία θα ήταν ακριβότερη/βραδύτερη και δεν θα απαντούσε εδώ σε κάποιο ανοιχτό ερώτημα ταξινόμησης.","Zielgerichtete validierte MGMT-Methylierungsanalyse":"Στοχευμένη επικυρωμένη ανάλυση μεθυλίωσης MGMT","Zielgerichtete Bisulfit-Methylierungsanalyse":"Στοχευμένη ανάλυση μεθυλίωσης με διθειώδες","MGMT-Promotor-Methylierung ist mit der lokal validierten zielgerichteten Methode nachweisbar und für die konkrete prädiktive Fragestellung berichtbar.":"Η μεθυλίωση του υποκινητή MGMT ανιχνεύεται με την τοπικά επικυρωμένη στοχευμένη μέθοδο και μπορεί να αναφερθεί για το συγκεκριμένο προβλεπτικό ερώτημα.","CNS-Methylierungsclassifier":"Ταξινομητής μεθυλίωσης ΚΝΣ","Das genomeweite Profil bestätigt die bereits gesicherte Tumorklasse, ist in diesem Labor aber nicht als Ersatz für die klinische MGMT-Einzelmarkerbestimmung validiert.":"Το γονιδιωματικής κλίμακας προφίλ επιβεβαιώνει την ήδη τεκμηριωμένη κατηγορία όγκου, αλλά στο συγκεκριμένο εργαστήριο δεν έχει επικυρωθεί ως υποκατάστατο της κλινικής εξέτασης MGMT ως μεμονωμένου δείκτη.","Zusätzliche Sequenzierungsbreite beantwortet die epigenetische MGMT-Frage nicht.":"Η πρόσθετη έκταση αλληλούχησης δεν απαντά στο επιγενετικό ερώτημα MGMT.","Tumorentität bereits integriert gesichert.":"Η οντότητα του όγκου έχει ήδη τεκμηριωθεί με ολοκληρωμένη διάγνωση.","Mehr Omik ist nicht automatisch die passendere Methode; Scope und Validierung müssen zur Frage passen.":"Περισσότερη ομική πληροφορία δεν σημαίνει αυτόματα καταλληλότερη μέθοδο· το εύρος και η επικύρωση πρέπει να ταιριάζουν στο ερώτημα.","Da die Tumorentität bereits sicher klassifiziert ist und die konkrete Frage MGMT-Promotor-Methylierung lautet, ist die lokal validierte zielgerichtete Bisulfitmethode die passende Untersuchung. Ein genomeweiter Methylierungsclassifier wäre für eine offene Entitätsfrage sinnvoll, ist hier aber unnötig und im lokalen Workflow kein validierter Ersatz für den prädiktiven Einzelmarker.":"Εφόσον η οντότητα του όγκου έχει ήδη ταξινομηθεί με βεβαιότητα και το συγκεκριμένο ερώτημα είναι η μεθυλίωση του υποκινητή MGMT, η τοπικά επικυρωμένη στοχευμένη μέθοδος με διθειώδες είναι η κατάλληλη εξέταση. Ένας ταξινομητής μεθυλίωσης σε επίπεδο γονιδιώματος θα ήταν χρήσιμος για ανοιχτό ερώτημα οντότητας, αλλά εδώ είναι περιττός και δεν αποτελεί επικυρωμένο υποκατάστατο του μεμονωμένου προβλεπτικού βιοδείκτη στην τοπική ροή εργασίας.","Teilbefund: Lokaler prädiktiver Marker und globale epigenetische Klassifikation sind unterschiedliche diagnostische Aufgaben.":"Μερικό αποτέλεσμα: ένας τοπικός προβλεπτικός βιοδείκτης και η συνολική επιγενετική ταξινόμηση είναι διαφορετικά διαγνωστικά καθήκοντα.","Fragestellung vor Technologie wählen":"Επιλέξτε πρώτα το κλινικό ερώτημα και μετά την τεχνολογία","lokale klinische Validierung berücksichtigen":"λάβετε υπόψη την τοπική κλινική επικύρωση","Classifier für Klassifikation, nicht automatisch für jeden Methylierungsmarker":"ταξινομητής για ταξινόμηση, όχι αυτόματα για κάθε βιοδείκτη μεθυλίωσης","Falschaussage: genomeweit ist immer klinisch besser":"Λανθασμένη δήλωση: η ανάλυση σε επίπεδο γονιδιώματος είναι πάντα κλινικά καλύτερη","Optimale Lösung: gesicherte Diagnose respektieren und die offene MGMT-Frage mit der dafür validierten zielgerichteten Methylierungsmethode beantworten.":"Βέλτιστη λύση: σεβαστείτε την τεκμηριωμένη διάγνωση και απαντήστε στο ανοιχτό ερώτημα MGMT με τη στοχευμένη μέθοδο μεθυλίωσης που έχει επικυρωθεί για αυτόν τον σκοπό.","MGMT":"MGMT","Bisulfit":"Διθειώδες","CNS":"ΚΝΣ","Nicht jedes Methylom braucht ein Methylom":"Δεν χρειάζεται κάθε ερώτημα μεθυλίωσης ένα μεθυλίωμα","Neuropathologie / Methodenauswahl":"Νευροπαθολογία / επιλογή μεθόδου","Zielgerichtete Methylierungsanalyse von genomeweiter Klassifikation unterscheiden.":"Διακρίνετε τη στοχευμένη ανάλυση μεθυλίωσης από την ταξινόμηση σε επίπεδο γονιδιώματος.","Methodenumfang nicht mit klinischer Eignung gleichsetzen.":"Μην εξισώνετε το εύρος της μεθόδου με την κλινική καταλληλότητα.","Lokale Validierung und Intended Use in die Auswahl integrieren.":"Ενσωματώστε την τοπική επικύρωση και την προβλεπόμενη χρήση στην επιλογή της εξέτασης.","Bei bereits gesicherter Entität unnötige Classifier-Diagnostik vermeiden.":"Αποφύγετε περιττή διαγνωστική με ταξινομητή όταν η οντότητα έχει ήδη τεκμηριωθεί.","Die Diagnose steht. Die einzige offene Frage lautet MGMT. Trotzdem liegt im Warenkorb ein genomeweites Methylierungsarray – weil „mehr Daten“ intuitiv nach „mehr Sicherheit“ klingt.":"Η διάγνωση έχει τεκμηριωθεί. Το μόνο ανοιχτό ερώτημα είναι το MGMT. Παρ' όλα αυτά, στο καλάθι υπάρχει συστοιχία μεθυλίωσης σε επίπεδο γονιδιώματος, επειδή «περισσότερα δεδομένα» ακούγονται διαισθητικά σαν «περισσότερη βεβαιότητα».","69-jähriger Patient mit integriert gesichertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung ist ausschließlich der MGMT-Promotor-Methylierungsstatus offen. Das Labor hat dafür eine validierte zielgerichtete Bisulfitmethode; der CNS-Classifier ist für Entitätsklassifikation validiert.":"Ασθενής 69 ετών με ολοκληρωμένα επιβεβαιωμένο γλοιοβλάστωμα, IDH wild type. Για τον σχεδιασμό της θεραπείας παραμένει ανοιχτή μόνο η κατάσταση μεθυλίωσης του υποκινητή MGMT. Το εργαστήριο διαθέτει για αυτό επικυρωμένη στοχευμένη μέθοδο με διθειώδες· ο ταξινομητής ΚΝΣ είναι επικυρωμένος για ταξινόμηση οντοτήτων.","Frage vor Plattform":"Πρώτα το ερώτημα, μετά η πλατφόρμα","MGMT-Status ist eine fokale Biomarkerfrage, Tumorklassifikation eine globale Musterfrage.":"Η κατάσταση MGMT είναι ερώτημα εστιακού βιοδείκτη· η ταξινόμηση του όγκου είναι ερώτημα συνολικού προτύπου.","Testscope muss die Fragestellung spiegeln.":"Το εύρος της εξέτασης πρέπει να αντανακλά το ερώτημα.","Validierung schlägt Prestige":"Η επικύρωση υπερισχύει του κύρους","Ein technisch komplexeres Verfahren ist nicht automatisch für jeden klinischen Output validiert.":"Μια τεχνικά πιο σύνθετη μέθοδος δεν είναι αυτόματα επικυρωμένη για κάθε κλινικό αποτέλεσμα.","Intended Use ist Teil der Methode.":"Η προβλεπόμενη χρήση αποτελεί μέρος της μεθόδου.","Materialökonomie":"Οικονομία υλικού","Unnötige Omik verbraucht Zeit, Geld und ggf. Material.":"Η περιττή ομική ανάλυση καταναλώνει χρόνο, χρήματα και ενδεχομένως υλικό.","Effizienz ist diagnostische Qualität.":"Η αποδοτικότητα αποτελεί διαγνωστική ποιότητα.","Entitätsdiagnose":"Διάγνωση οντότητας","bereits integriert gesichert":"ήδη τεκμηριωμένη με ολοκληρωμένη διάγνωση","Lokaler Workflow":"Τοπική ροή εργασίας","zielgerichtete Bisulfitmethode klinisch validiert":"στοχευμένη μέθοδος με διθειώδες κλινικά επικυρωμένη","Ausreichendes Material.":"Επαρκές υλικό.","Kein Klassifikationsproblem.":"Δεν υπάρχει πρόβλημα ταξινόμησης.","Das Array ist lokal nicht als direkter Ersatz für die MGMT-Einzelmarkerfreigabe validiert.":"Η συστοιχία δεν έχει επικυρωθεί τοπικά ως άμεσο υποκατάστατο της αναφοράς MGMT ως μεμονωμένου δείκτη.","Welche Methode passt zur isolierten MGMT-Frage bei bereits gesicherter Glioblastomdiagnose am besten?":"Ποια μέθοδος ταιριάζει καλύτερα στο μεμονωμένο ερώτημα MGMT όταν η διάγνωση γλοιοβλαστώματος έχει ήδη τεκμηριωθεί;","Die dafür lokal validierte zielgerichtete Bisulfit-Methylierungsanalyse.":"Η τοπικά επικυρωμένη στοχευμένη ανάλυση μεθυλίωσης με διθειώδες.","Zwingend genomeweiter Classifier.":"Υποχρεωτικός ταξινομητής σε επίπεδο γονιδιώματος.","Breites DNA-NGS.":"Ευρύ DNA-NGS.","FISH.":"FISH.","Der klinische Output ist ein definierter lokaler Methylierungsmarker.":"Το κλινικό αποτέλεσμα είναι ένας καθορισμένος τοπικός βιοδείκτης μεθυλίωσης.","Wann wäre der CNS-Methylierungsclassifier besonders sinnvoll?":"Πότε είναι ιδιαίτερα χρήσιμος ο ταξινομητής μεθυλίωσης ΚΝΣ;","Bei diagnostisch unklarer Tumorentität, wenn ein genomeweites Muster die integrierte Klassifikation unterstützen kann.":"Σε διαγνωστικά ασαφή οντότητα όγκου, όταν ένα πρότυπο σε επίπεδο γονιδιώματος μπορεί να υποστηρίξει την ολοκληρωμένη ταξινόμηση.","Bei jedem MGMT-Auftrag unabhängig von Diagnose.":"Για κάθε αίτημα MGMT ανεξάρτητα από τη διάγνωση.","Zur AML-MRD.":"Για MRD στην AML.","Für Keimbahndiagnostik.":"Για διαγνωστική γεννητικής σειράς.","Classifier und Einzelmarker haben unterschiedliche Intended Uses.":"Ο ταξινομητής και ο μεμονωμένος βιοδείκτης έχουν διαφορετικές προβλεπόμενες χρήσεις.","Warum darf ein Array nicht automatisch den lokal validierten MGMT-Test ersetzen?":"Γιατί μια συστοιχία δεν πρέπει να αντικαθιστά αυτόματα την τοπικά επικυρωμένη εξέταση MGMT;","Weil klinische Freigabe die validierte Performance für genau diesen Output voraussetzt.":"Επειδή η κλινική αναφορά απαιτεί επικυρωμένη απόδοση για ακριβώς αυτό το αποτέλεσμα.","Weil Arrays grundsätzlich ungenau sind.":"Επειδή οι συστοιχίες είναι εγγενώς ανακριβείς.","Weil Arrays keine DNA messen.":"Επειδή οι συστοιχίες δεν μετρούν DNA.","Weil Methylierungsarrays nie diagnostisch genutzt werden.":"Επειδή οι συστοιχίες μεθυλίωσης δεν χρησιμοποιούνται ποτέ διαγνωστικά.","Die Aussage richtet sich gegen ungeprüften Methodenwechsel, nicht gegen Arrays an sich.":"Το ζητούμενο είναι να αποφεύγεται η μη επικυρωμένη αλλαγή μεθόδου, όχι να απορρίπτονται οι συστοιχίες καθεαυτές.","Das Array bestätigt erwartungsgemäß die Tumorklasse, liefert aber keinen lokal validierten MGMT-Report. Was war der Fehler?":"Η συστοιχία επιβεβαιώνει την αναμενόμενη κατηγορία όγκου, αλλά δεν παρέχει τοπικά επικυρωμένη αναφορά MGMT. Ποιο ήταν το λάθος;","Eine globale Klassifikationsplattform wurde für eine fokale prädiktive Frage eingesetzt, ohne passenden validierten Output.":"Χρησιμοποιήθηκε πλατφόρμα συνολικής ταξινόμησης για ένα εστιακό προβλεπτικό ερώτημα χωρίς κατάλληλο επικυρωμένο αποτέλεσμα.","Methylierungsclassifier sind grundsätzlich nutzlos.":"Οι ταξινομητές μεθυλίωσης είναι εξ ορισμού άχρηστοι.","Es gibt keinen Unterschied.":"Δεν υπάρχει διαφορά.","Technische Information und klinisch validierter Output sind nicht identisch.":"Η τεχνική πληροφορία και ένα κλινικά επικυρωμένο αποτέλεσμα δεν είναι ταυτόσημα.","Wählen Sie die Methylierungsmethode passend zur konkreten klinischen Frage.":"Επιλέξτε τη μέθοδο μεθυλίωσης σύμφωνα με το συγκεκριμένο κλινικό ερώτημα.","Prüfen, ob die Tumorentität bereits gesichert ist.":"Ελέγξτε αν η οντότητα του όγκου έχει ήδη τεκμηριωθεί.","Offene Frage als MGMT-Einzelmarker definieren.":"Ορίστε το ανοιχτό ερώτημα ως ερώτημα MGMT μεμονωμένου δείκτη.","Lokal validierten Zielassay verwenden.":"Χρησιμοποιήστε την τοπικά επικυρωμένη στοχευμένη δοκιμασία.","Classifier nur bei echter globaler Klassifikationsfrage einsetzen.":"Χρησιμοποιήστε τον ταξινομητή μόνο όταν υπάρχει πραγματικό ερώτημα συνολικής ταξινόμησης.","Intended Use im Befund transparent halten.":"Διατηρήστε σαφή την προβλεπόμενη χρήση στην αναφορά.","Wenn ein Labor einen arraybasierten MGMT-Algorithmus spezifisch klinisch validiert hat, kann dieser lokal geeignet sein; der Fall lehrt Scope/Validierung, keine universelle Plattformhierarchie.":"Εάν ένα εργαστήριο έχει ειδικά κλινικά επικυρώσει αλγόριθμο MGMT βασισμένο σε συστοιχία, αυτός μπορεί να είναι κατάλληλος τοπικά· η περίπτωση διδάσκει εύρος/επικύρωση και όχι καθολική ιεραρχία πλατφορμών.","Mehr Daten = besser":"Περισσότερα δεδομένα = καλύτερα","Ignoriert Fragestellung und Validierung.":"Αγνοεί το κλινικό ερώτημα και την επικύρωση.","Classifier nie verwenden":"Μην χρησιμοποιείτε ποτέ ταξινομητή","Bei unklaren CNS-Tumoren kann er sehr wertvoll sein.":"Μπορεί να είναι πολύ πολύτιμος σε διαγνωστικά ασαφείς όγκους ΚΝΣ.","NGS für MGMT-Methylierung":"NGS για μεθυλίωση MGMT","Sequenzvarianten beantworten die epigenetische Frage nicht.":"Οι παραλλαγές αλληλουχίας δεν απαντούν στο επιγενετικό ερώτημα.","Das teurere Ergebnis beantwortet die falsche Frage":"Το ακριβότερο αποτέλεσμα απαντά στη λάθος ερώτηση","Der Classifier bestätigt nur die bereits bekannte Tumorklasse; die klinisch offene MGMT-Frage bleibt ohne lokal validierten Einzelmarkeroutput bestehen.":"Ο ταξινομητής επιβεβαιώνει μόνο την ήδη γνωστή κατηγορία όγκου· το κλινικά ανοιχτό ερώτημα MGMT παραμένει αναπάντητο χωρίς τοπικά επικυρωμένο αποτέλεσμα μεμονωμένου δείκτη.","Der Fall verschiebt Methodenauswahl von Technologieprestige zu Intended Use.":"Η περίπτωση μετατοπίζει την επιλογή μεθόδου από το κύρος της τεχνολογίας προς την προβλεπόμενη χρήση.","Zielmarker passend getestet":"Ο δείκτης-στόχος εξετάστηκε κατάλληλα","MGMT mit validierter Zielmethode berichtet.":"Το MGMT αναφέρθηκε με την επικυρωμένη στοχευμένη μέθοδο.","Effizient und klinisch passend.":"Αποδοτικό και κλινικά κατάλληλο.","Classifier ohne offene Klassifikationsfrage":"Ταξινομητής χωρίς ανοιχτό ερώτημα ταξινόμησης","Mehr Daten, aber falscher primärer Output.":"Περισσότερα δεδομένα, αλλά λάθος πρωτεύον αποτέλεσμα.","Scope-Mismatch.":"Ασυμφωνία εύρους.","Epigenetische Frage bleibt offen.":"Το επιγενετικό ερώτημα παραμένει άλυτο.","Methodenfehler.":"Σφάλμα μεθόδου.","isolierte validierte Einzelmarkerfrage":"μεμονωμένο επικυρωμένο ερώτημα ενός δείκτη","zielgerichteten validierten Assay bevorzugen":"προτιμήστε την επικυρωμένη στοχευμένη δοκιμασία","globale Omik nur bei zusätzlicher passender Fragestellung.":"συνολική ομική ανάλυση μόνο όταν υπάρχει πρόσθετο κατάλληλο ερώτημα.","Fragestellung bestimmt Methodenumfang.":"Το κλινικό ερώτημα καθορίζει το εύρος της μεθόδου.","Methylierungsclassifier und lokaler Bisulfitassay sind nicht austauschbar.":"Ο ταξινομητής μεθυλίωσης και η τοπική δοκιμασία με διθειώδες δεν είναι εναλλάξιμα.","Intended Use und lokale Validierung gehören zur klinischen Interpretation.":"Η προβλεπόμενη χρήση και η τοπική επικύρωση αποτελούν μέρος της κλινικής ερμηνείας.","Bei gesichertem Glioblastom und isolierter MGMT-Frage ist die lokal validierte zielgerichtete Methylierungsanalyse angemessen; ein Classifier ist kein automatischer Ersatz.":"Σε τεκμηριωμένο γλοιοβλάστωμα και μεμονωμένο ερώτημα MGMT, η τοπικά επικυρωμένη στοχευμένη ανάλυση μεθυλίωσης είναι κατάλληλη· ένας ταξινομητής δεν αποτελεί αυτόματο υποκατάστατο.","Methodenscope":"Εύρος μεθόδου","Validierung":"Επικύρωση","Methylierungsdiagnostik":"Διαγνωστική μεθυλίωσης","Wann ist ein CNS-Classifier wirklich diagnostisch entscheidend?":"Πότε ένας ταξινομητής ΚΝΣ είναι πραγματικά διαγνωστικά καθοριστικός;","Wie validiert man einen MGMT-Assay?":"Πώς επικυρώνεται μια δοκιμασία MGMT;","Wann kann ein Array mehrere Outputs klinisch tragen?":"Πότε μπορεί μια συστοιχία να υποστηρίξει πολλαπλά κλινικά αποτελέσματα;","Twist: globale Plattform beantwortet lokale Frage nicht automatisch":"Ανατροπή: μια συνολική πλατφόρμα δεν απαντά αυτόματα σε ένα τοπικό ερώτημα","Intended Use vor Omikbreite":"Προβλεπόμενη χρήση πριν από το εύρος της ομικής","Referenzpfad: klinische Frage → validierter Output → Methode":"Διαδρομή αναφοράς: κλινικό ερώτημα → επικυρωμένο αποτέλεσμα → μέθοδος","EWSR1-FISH positiv: schneller Rearrangementnachweis, aber noch keine Entität":"Θετικό FISH EWSR1: ταχεία ανίχνευση αναδιάταξης, αλλά όχι ακόμη οντότητα","Amplifikation/Fusion: FISH als sch…":"Ενίσχυση/σύντηξη: FISH ως ταχεία συμπληρωματική…","Sarkomzentrum / Referenzpathologie":"Κέντρο σαρκωμάτων / παθολογοανατομικό εργαστήριο αναφοράς","32-jährige Patientin mit einem tiefen Weichteiltumor am Fuß. Morphologisch monomorpher Tumor; EWSR1-Break-apart-FISH wird wegen Zeitdruck früh durchgeführt und ist positiv.":"Γυναίκα 32 ετών με εν τω βάθει όγκο μαλακών μορίων του άκρου ποδός. Μορφολογικά πρόκειται για μονόμορφο όγκο· λόγω πίεσης χρόνου πραγματοποιείται νωρίς FISH break-apart EWSR1 και είναι θετικό.","Darf daraus unmittelbar „Ewing-Sarkom“ werden oder braucht es partner-/transkriptspezifische Auflösung?":"Μπορεί αυτό να χαρακτηριστεί άμεσα «σάρκωμα Ewing» ή απαιτείται ειδική ταυτοποίηση του εταίρου/μεταγράφου;","Neoadjuvante Strategie wird in wenigen Tagen diskutiert.":"Η νεοεπικουρική στρατηγική θα συζητηθεί μέσα στις επόμενες ημέρες.","Monomorphe Zellen, aber nicht klassisch genug für eine alleinige Ewing-Diagnose.":"Μονόμορφα κύτταρα, αλλά όχι αρκετά κλασικά για αυτόνομη διάγνωση Ewing.","EWSR1-Break-apart positiv.":"EWSR1 break-apart θετικό.","Ein Gen-Rearrangement wird mit einer bestimmten Tumorentität gleichgesetzt.":"Μια γονιδιακή αναδιάταξη εξισώνεται με συγκεκριμένη οντότητα όγκου.","FISH als schnellen, robusten, aber informationsbegrenzten Test einordnen.":"Αντιμετωπίστε το FISH ως ταχεία και ανθεκτική, αλλά πληροφοριακά περιορισμένη εξέταση.","Melaninarm, nested/solid; immunhistochemischer Kontext nicht eindeutig für Ewing.":"Φτωχό σε μελανίνη, nested/solid πρότυπο· το ανοσοϊστοχημικό πλαίσιο δεν είναι σαφώς συμβατό με Ewing.","EWSR1 rearrangiert.":"EWSR1 αναδιαταγμένο.","Welcher Partner und welche Transkriptfusion liegt vor?":"Ποιος εταίρος και ποιο μεταγραφικό προϊόν σύντηξης υπάρχουν;","EWSR1-Rearrangements kommen in mehreren Tumorentitäten vor.":"Αναδιατάξεις EWSR1 εμφανίζονται σε πολλαπλές οντότητες όγκων.","FFPE-Biopsie; RNA ausreichend.":"Βιοψία FFPE· επαρκές RNA.","schnell verfügbar und technisch robust.":"γρήγορα διαθέσιμο και τεχνικά ανθεκτικό.","Targeted RNA-NGS verfügbar.":"Διαθέσιμο στοχευμένο RNA-NGS.","Partnerbestimmung kann die Entitätsdiagnose entscheidend verändern.":"Η ταυτοποίηση του εταίρου μπορεί να αλλάξει καθοριστικά τη διάγνωση της οντότητας.","Rearrangement schnell/orthogonal erfassen":"Ταχεία/ορθογώνια ανίχνευση της αναδιάταξης","Fusionspartner/Transkript klären":"Διευκρίνιση εταίρου/μεταγράφου σύντηξης","Break-apart-FISH":"FISH break-apart","EWSR1-Break-apart positiv: ein EWSR1-Rearrangement ist nachgewiesen, die Partneridentität und damit die genaue Entität sind dadurch nicht allein definiert.":"Θετικό EWSR1 break-apart: τεκμηριώνεται αναδιάταξη EWSR1, αλλά η ταυτότητα του εταίρου και συνεπώς η ακριβής οντότητα δεν καθορίζονται μόνο από αυτό.","RNA-NGS weist EWSR1::ATF1 nach und unterstützt im passenden morphologisch-immunhistochemischen Kontext die Diagnose eines Clear-Cell-Sarkoms statt eines Ewing-Sarkoms.":"Το RNA-NGS ανιχνεύει EWSR1::ATF1 και, στο κατάλληλο μορφολογικό-ανοσοϊστοχημικό πλαίσιο, υποστηρίζει διάγνωση σαρκώματος διαυγών κυττάρων αντί σαρκώματος Ewing.","Zusatzvarianten tragen weniger zur Kernfrage bei als die direkte Partnerbestimmung der Fusion.":"Πρόσθετες παραλλαγές συμβάλλουν λιγότερο στο κεντρικό ερώτημα από την άμεση ταυτοποίηση του εταίρου σύντηξης.","schneller Rearrangementnachweis, aber keine universelle Entitätsdefinition.":"ταχεία ανίχνευση αναδιάταξης, αλλά όχι καθολικός ορισμός οντότητας.","Gen-Rearrangement und Fusionspartner müssen im morphologischen Kontext interpretiert werden.":"Η γονιδιακή αναδιάταξη και ο εταίρος σύντηξης πρέπει να ερμηνεύονται στο μορφολογικό πλαίσιο.","EWSR1-Break-apart-FISH ist ein sinnvoller schneller Nachweis eines Rearrangements, beweist aber nicht automatisch ein Ewing-Sarkom. Die RNA-basierte Partnerbestimmung zeigt EWSR1::ATF1 und verschiebt die integrierte Diagnose im passenden Kontext zu einem Clear-Cell-Sarkom. FISH bleibt wertvoll – aber seine Aussagegrenze muss respektiert werden.":"Το FISH break-apart EWSR1 είναι χρήσιμη ταχεία εξέταση για ανίχνευση αναδιάταξης, αλλά δεν αποδεικνύει αυτόματα σάρκωμα Ewing. Η ταυτοποίηση εταίρου με βάση το RNA αποκαλύπτει EWSR1::ATF1 και μετατοπίζει την ολοκληρωμένη διάγνωση, στο κατάλληλο πλαίσιο, προς σάρκωμα διαυγών κυττάρων. Το FISH παραμένει πολύτιμο, αλλά πρέπει να γίνονται σεβαστά τα όρια της δήλωσής του.","Teilbefund: Ein positiver Break-apart-FISH beantwortet „ist das Gen rearrangiert?“, nicht immer „welche Fusion/Entität liegt vor?“.":"Μερικό αποτέλεσμα: ένα θετικό break-apart FISH απαντά «είναι αναδιαταγμένο το γονίδιο;», όχι πάντα «ποια σύντηξη/οντότητα υπάρχει;». ","FISH-Stärke und -Grenze benennen":"Δηλώστε το πλεονέκτημα και το όριο του FISH","Partnerbestimmung bei entitätsrelevanter Frage ergänzen":"Προσθέστε ταυτοποίηση εταίρου όταν είναι σημαντική για τη διάγνωση της οντότητας","Molekularbefund in Morphologie/IHC integrieren":"Ενσωματώστε το μοριακό αποτέλεσμα με μορφολογία/IHC","Falschaussage: EWSR1-FISH positiv = Ewing-Sarkom":"Λανθασμένη δήλωση: θετικό FISH EWSR1 = σάρκωμα Ewing","Optimale Lösung: FISH als schnellen Rearrangementnachweis nutzen, aber bei nicht entitätsspezifischem Genereignis den Partner mit RNA-NGS bestimmen und integriert diagnostizieren.":"Βέλτιστη λύση: χρησιμοποιήστε FISH για ταχεία ανίχνευση αναδιάταξης, αλλά όταν το γονιδιακό συμβάν δεν είναι ειδικό για οντότητα, προσδιορίστε τον εταίρο με RNA-NGS και θέστε ολοκληρωμένη διάγνωση.","EWSR1":"EWSR1","Sarcoma":"Σάρκωμα","FISH positiv – Diagnose noch offen":"FISH θετικό – η διάγνωση παραμένει ανοιχτή","Sarkompathologie / FISH / RNA-Fusion":"Παθολογία σαρκωμάτων / FISH / σύντηξη RNA","Break-apart-FISH als schnellen Rearrangementnachweis korrekt einordnen.":"Τοποθετήστε σωστά το break-apart FISH ως ταχεία εξέταση αναδιάταξης.","Nicht entitätsspezifische Rearrangements nicht überinterpretieren.":"Μην υπερερμηνεύετε αναδιατάξεις που δεν είναι ειδικές για οντότητα.","RNA-NGS zur Partner-/Transkriptbestimmung nutzen.":"Χρησιμοποιήστε RNA-NGS για ταυτοποίηση εταίρου/μεταγράφου.","Morphologie, IHC, FISH und RNA integriert bewerten.":"Αξιολογήστε ολοκληρωμένα μορφολογία, IHC, FISH και RNA.","Der FISH ist positiv. EWSR1 rearrangiert. Im ersten Moment klingt das wie die Diagnose – bis man sich erinnert, dass EWSR1 in mehreren völlig unterschiedlichen Tumoren rearrangiert sein kann.":"Το FISH είναι θετικό. Το EWSR1 είναι αναδιαταγμένο. Στην αρχή ακούγεται σαν διάγνωση, μέχρι να θυμηθείτε ότι το EWSR1 μπορεί να είναι αναδιαταγμένο σε αρκετούς εντελώς διαφορετικούς όγκους.","32-jährige Patientin mit Weichteiltumor am Fuß. EWSR1-Break-apart-FISH ist positiv, die Morphologie aber nicht klassisch für Ewing. RNA ist ausreichend für Partnerbestimmung.":"Γυναίκα 32 ετών με όγκο μαλακών μορίων του άκρου ποδός. Το FISH break-apart EWSR1 είναι θετικό, αλλά η μορφολογία δεν είναι κλασική για Ewing. Το RNA είναι επαρκές για ταυτοποίηση εταίρου.","FISH beantwortet eine enge Frage":"Το FISH απαντά σε στενό ερώτημα","Break-apart: Rearrangement ja/nein.":"Break-apart: αναδιάταξη ναι/όχι.","Partner und Transkript bleiben oft offen.":"Ο εταίρος και το μετάγραφο συχνά παραμένουν άγνωστα.","Genereignis ist nicht immer entitätsspezifisch":"Το γονιδιακό συμβάν δεν είναι πάντα ειδικό για οντότητα","EWSR1 kann verschiedene Fusionspartner und Tumorentitäten haben.":"Το EWSR1 μπορεί να έχει διαφορετικούς εταίρους σύντηξης και να εμφανίζεται σε διαφορετικές οντότητες όγκων.","Molekularer Befund braucht Kontext.":"Ένα μοριακό αποτέλεσμα χρειάζεται πλαίσιο.","RNA löst die Partnerfrage":"Το RNA επιλύει το ερώτημα του εταίρου","Sequenzbasierter Transkriptnachweis kann die diagnostische Klasse entscheidend präzisieren.":"Η ανίχνευση μεταγράφου με βάση την αλληλούχηση μπορεί να εξειδικεύσει καθοριστικά τη διαγνωστική κατηγορία.","FISH und RNA konkurrieren nicht, sie ergänzen sich.":"FISH και RNA δεν ανταγωνίζονται· αλληλοσυμπληρώνονται.","monomorph, aber nicht klassisch Ewing":"μονόμορφο, αλλά όχι κλασικό Ewing","EWSR1 break-apart positiv":"EWSR1 break-apart θετικό","Zeitdruck macht FISH attraktiv.":"Η πίεση χρόνου καθιστά το FISH ελκυστικό.","RNA-NGS ist innerhalb der diagnostischen Frist möglich.":"Το RNA-NGS είναι εφικτό εντός του διαγνωστικού χρονικού πλαισίου.","Positives FISH darf nicht über seine validierte Zielaussage hinaus interpretiert werden.":"Ένα θετικό FISH δεν πρέπει να ερμηνεύεται πέρα από την επικυρωμένη δήλωση-στόχο του.","Was beweist ein positiver EWSR1-Break-apart-FISH primär?":"Τι αποδεικνύει πρωτίστως ένα θετικό FISH break-apart EWSR1;","Ein EWSR1-Rearrangement.":"Αναδιάταξη EWSR1.","Immer ein Ewing-Sarkom.":"Πάντα σάρκωμα Ewing.","Immer den exakten Fusionspartner.":"Πάντα τον ακριβή εταίρο σύντηξης.","Quantitative Proteinexpression.":"Ποσοτική έκφραση πρωτεΐνης.","Break-apart-FISH ist genbezogen, nicht zwingend partner- oder entitätsspezifisch.":"Το break-apart FISH είναι ειδικό για το γονίδιο, όχι απαραίτητα για τον εταίρο ή την οντότητα.","Warum ist RNA-NGS bei atypischer Morphologie sinnvoll?":"Γιατί είναι χρήσιμο το RNA-NGS όταν η μορφολογία είναι άτυπη;","Zur Bestimmung des exprimierten Fusionspartners/Transkripts.":"Για την ταυτοποίηση του εκφραζόμενου εταίρου/μεταγράφου σύντηξης.","Weil es exakt dasselbe wie FISH misst.":"Επειδή μετρά ακριβώς το ίδιο πράγμα με το FISH.","Nur zur Copy-number-Bestimmung.":"Μόνο για προσδιορισμό αριθμού αντιγράφων.","Nur für Keimbahn.":"Μόνο για έλεγχο γεννητικής σειράς.","Die Partnerinformation kann die Diagnose präzisieren.":"Η πληροφορία για τον εταίρο μπορεί να εξειδικεύσει τη διάγνωση.","Wie sollte ein Fusionsbefund diagnostisch verwendet werden?":"Πώς πρέπει να χρησιμοποιείται διαγνωστικά ένα αποτέλεσμα σύντηξης;","Mit Morphologie, IHC und klinischem Kontext integrieren.":"Ενσωματώστε το με τη μορφολογία, την IHC και το κλινικό πλαίσιο.","Molekularer Befund ersetzt immer die Histologie.":"Ένα μοριακό αποτέλεσμα αντικαθιστά πάντα την ιστολογία.","Molekulare Befunde sind bei Sarkomen unwichtig.":"Τα μοριακά αποτελέσματα είναι ασήμαντα στα σαρκώματα.","FISH entscheidet jede Entität allein.":"Το FISH καθορίζει μόνο του κάθε οντότητα.","Entitätsdiagnostik ist integriert.":"Η διάγνωση οντότητας είναι ολοκληρωμένη.","RNA zeigt EWSR1::ATF1. Was ändert sich?":"Το RNA δείχνει EWSR1::ATF1. Τι αλλάζει;","Im passenden Kontext unterstützt dies Clear-Cell-Sarkom statt einer vorschnellen Ewing-Diagnose.":"Στο κατάλληλο πλαίσιο, αυτό υποστηρίζει σάρκωμα διαυγών κυττάρων αντί για πρόωρη διάγνωση Ewing.","Es beweist weiterhin Ewing unabhängig vom Partner.":"Εξακολουθεί να αποδεικνύει Ewing ανεξάρτητα από τον εταίρο.","Der positive FISH war falsch.":"Το θετικό FISH ήταν λάθος.","Partnerinformation ist bedeutungslos.":"Η πληροφορία για τον εταίρο δεν έχει σημασία.","Die Partneridentität kann die Entitätszuordnung entscheidend verändern.":"Η ταυτότητα του εταίρου μπορεί να αλλάξει καθοριστικά την απόδοση της οντότητας.","Nutzen Sie FISH dort, wo er stark ist, und definieren Sie, wann Partnerbestimmung erforderlich ist.":"Χρησιμοποιήστε το FISH εκεί όπου υπερέχει και ορίστε πότε απαιτείται ταυτοποίηση εταίρου.","Morphologie und Prätestwahrscheinlichkeit erfassen.":"Αξιολογήστε τη μορφολογία και την προεξεταστική πιθανότητα.","FISH als schnellen Rearrangementnachweis verwenden.":"Χρησιμοποιήστε FISH ως ταχεία εξέταση αναδιάταξης.","Aussagegrenze explizit halten.":"Διατηρήστε ρητό το όριο της δήλωσης.","Bei entitätsrelevanter Partnerfrage RNA-NGS ergänzen.":"Προσθέστε RNA-NGS όταν η ταυτότητα του εταίρου είναι σημαντική για την οντότητα.","Integrierte Diagnose aus allen Ebenen formulieren.":"Διατυπώστε ολοκληρωμένη διάγνωση από όλα τα επίπεδα.","Bei sehr charakteristischer Morphologie und entitätsspezifischem Rearrangement kann FISH ausreichend sein; das hängt von Gen, Tumorart und validiertem diagnostischem Kontext ab.":"Με πολύ χαρακτηριστική μορφολογία και αναδιάταξη ειδική για οντότητα, το FISH μπορεί να επαρκεί· αυτό εξαρτάται από το γονίδιο, τον τύπο όγκου και το επικυρωμένο διαγνωστικό πλαίσιο.","Break-apart = Partner bekannt":"Break-apart = γνωστός εταίρος","FISH liefert diese Information häufig nicht.":"Το FISH συχνά δεν παρέχει αυτή την πληροφορία.","EWSR1 = Ewing":"EWSR1 = Ewing","EWSR1 ist nicht entitätsspezifisch.":"Το EWSR1 δεν είναι ειδικό για οντότητα.","FISH ist veraltet und nutzlos":"Το FISH είναι παρωχημένο και άχρηστο","FISH kann schnell, robust und materialeffizient sehr wertvoll sein.":"Το FISH μπορεί να είναι ταχύ, ανθεκτικό, οικονομικό σε υλικό και πολύ πολύτιμο.","Der Partner kippt die Diagnose":"Ο εταίρος αλλάζει τη διάγνωση","RNA zeigt EWSR1::ATF1 statt einer Ewing-typischen Fusion.":"Το RNA δείχνει EWSR1::ATF1 αντί για σύντηξη τυπική του Ewing.","FISH war korrekt positiv, aber die überzogene Interpretation wäre falsch gewesen.":"Το FISH ήταν σωστά θετικό, αλλά η υπερβολική ερμηνεία θα ήταν λανθασμένη.","FISH + RNA integriert":"Ολοκληρωμένο FISH + RNA","Rearrangement schnell erkannt, Partner korrekt bestimmt, Diagnose präzisiert.":"Ταχεία ανίχνευση αναδιάταξης, σωστή ταυτοποίηση εταίρου, εξειδίκευση διάγνωσης.","Stärken beider Methoden genutzt.":"Αξιοποιήθηκαν τα πλεονεκτήματα και των δύο μεθόδων.","Ewing nur aus EWSR1-FISH":"Ewing μόνο βάσει FISH EWSR1","Entität falsch überinterpretiert.":"Λανθασμένη υπερερμηνεία της οντότητας.","Scope-Fehler.":"Σφάλμα εύρους.","FISH komplett verworfen":"Πλήρης απόρριψη του FISH","Schnelle robuste Information unnötig verloren.":"Ταχεία και αξιόπιστη πληροφορία χάνεται άσκοπα.","positiver genbezogener FISH ohne entitätsspezifische Eindeutigkeit":"θετικό γονιδιοκεντρικό FISH χωρίς σαφή ειδικότητα οντότητας","Partner-/Transkriptbestimmung erwägen":"εξετάστε ταυτοποίηση εταίρου/μεταγράφου","Diagnose nicht allein aus Gen-Rearrangement ableiten.":"μην εξάγετε τη διάγνωση μόνο από τη γονιδιακή αναδιάταξη.","FISH bleibt klinisch nützlich.":"Το FISH παραμένει κλινικά χρήσιμο.","Aussagegrenze ist Teil der Methode.":"Το όριο της δήλωσης αποτελεί μέρος της μεθόδου.","Partnerinformation kann diagnostisch wichtiger sein als der reine Gen-Rearrangementnachweis.":"Η πληροφορία για τον εταίρο μπορεί να είναι διαγνωστικά σημαντικότερη από την απλή ανίχνευση της γονιδιακής αναδιάταξης.","EWSR1-FISH bestätigt ein Rearrangement, aber keine automatische Ewing-Diagnose; RNA-NGS zeigt EWSR1::ATF1 und präzisiert die Entität im morphologischen Kontext.":"Το FISH EWSR1 επιβεβαιώνει αναδιάταξη αλλά δεν διαγιγνώσκει αυτόματα Ewing· το RNA-NGS δείχνει EWSR1::ATF1 και εξειδικεύει την οντότητα στο μορφολογικό πλαίσιο.","FISH-Scope":"Εύρος FISH","Partnerbestimmung":"Ταυτοποίηση εταίρου","integrierte Sarkomdiagnostik":"Ολοκληρωμένη διάγνωση σαρκώματος","Welche Break-apart-Sonden sind besonders entitätsspezifisch oder unspezifisch?":"Ποιες ανιχνευτικές κεφαλές break-apart είναι ιδιαίτερα ειδικές ή μη ειδικές για οντότητα;","Wann ist FISH bei schlechter RNA die beste Option?":"Πότε είναι το FISH η καλύτερη επιλογή όταν το RNA είναι κακής ποιότητας;","Wie formuliert man einen positiven FISH ohne Partner?":"Πώς διατυπώνετε ένα θετικό αποτέλεσμα FISH χωρίς γνωστό εταίρο;","Twist: FISH korrekt, Interpretation fast falsch":"Ανατροπή: σωστό FISH, σχεδόν λάθος ερμηνεία","Gen-Rearrangement ≠ Entität":"Γονιδιακή αναδιάταξη ≠ οντότητα","Referenzpfad: FISH → Scope prüfen → RNA-Partner → integrieren":"Διαδρομή αναφοράς: FISH → έλεγχος εύρους → εταίρος RNA → ολοκλήρωση","23 Seiten Multiomics: eine belastbare Kernaussage, viele Hypothesen":"23 σελίδες multiomics: ένα αξιόπιστο βασικό μήνυμα, πολλές υποθέσεις","Multiomics-Bericht: viel Informati…":"Αναφορά multiomics: πολλή πληροφορί…","Hepatobiliäres Tumorboard / Präzisionsonkologie":"Ηπατοχολικό ογκολογικό συμβούλιο / ογκολογία ακριβείας","59-jährige Patientin mit metastasiertem intrahepatischem Cholangiokarzinom. Ein externer Multiomics-Bericht umfasst DNA, RNA, Immunmarker und Proteinsignaturen auf 23 Seiten.":"Γυναίκα 59 ετών με μεταστατικό ενδοηπατικό χολαγγειοκαρκίνωμα. Εξωτερική αναφορά multiomics 23 σελίδων περιλαμβάνει DNA, RNA, ανοσολογικούς δείκτες και πρωτεϊνικές υπογραφές.","Welche Befunde sind unmittelbar klinisch belastbar, welche nur biologischer Kontext und welche reine Hypothese?":"Ποια ευρήματα είναι άμεσα κλινικά αξιόπιστα, ποια αποτελούν μόνο βιολογικό πλαίσιο και ποια είναι καθαρές υποθέσεις;","Das MTB hat sieben Minuten für die molekulare Kernaussage.":"Το ογκολογικό συμβούλιο έχει επτά λεπτά για το βασικό μοριακό μήνυμα.","Pathogene IDH1 p.R132C-Mutation; keine FGFR2-Fusion im validierten Fusionsassay.":"Παθογόνος μετάλλαξη IDH1 p.R132C· καμία σύντηξη FGFR2 στην επικυρωμένη εξέταση συντήξεων.","FGFR2-Expression deutlich erhöht; mehrere Pathway-Scores für MAPK/EMT.":"Σημαντικά αυξημένη έκφραση FGFR2· αρκετές βαθμολογίες οδών MAPK/EMT.","Immunprofil":"Ανοσολογικό προφίλ","MSS, niedrige TMB; PD-L1 niedrig.":"MSS, χαμηλό TMB· χαμηλό PD-L1.","Der visuell spektakulärste Omics-Score wird mit einem validierten prädiktiven Biomarker gleichgesetzt.":"Η οπτικά πιο εντυπωσιακή βαθμολογία omics εξισώνεται με επικυρωμένο προβλεπτικό βιοδείκτη.","Intrahepatisches Cholangiokarzinom.":"Ενδοηπατικό χολαγγειοκαρκίνωμα.","Molekulare Schlüsseldaten":"Βασικά μοριακά δεδομένα","IDH1 pathogen; keine FGFR2-Fusion.":"Παθογόνο IDH1· καμία σύντηξη FGFR2.","Explorative Daten":"Διερευνητικά δεδομένα","FGFR2-high expression, EMT-/MET-Signaturen.":"Υψηλή έκφραση FGFR2, υπογραφές EMT/MET.","Was gehört in die erste Zeile des Tumorboards?":"Τι πρέπει να μπει στην πρώτη γραμμή της σύνοψης του ογκολογικού συμβουλίου;","Mehrere Omics-Layer bereits erzeugt.":"Έχουν ήδη παραχθεί πολλαπλά επίπεδα omics.","Problem":"Πρόβλημα","Nicht Datenmangel, sondern Evidenzpriorisierung.":"Όχι έλλειψη δεδομένων, αλλά ιεράρχηση τεκμηρίωσης.","Zeit":"Χρόνος","MTB-Kommunikation muss extrem komprimiert sein.":"Η επικοινωνία στο ογκολογικό συμβούλιο πρέπει να είναι εξαιρετικά συμπυκνωμένη.","Keine weitere Messung nötig, bevor die vorhandenen Daten sauber hierarchisiert sind.":"Δεν απαιτείται περαιτέρω μέτρηση πριν ιεραρχηθούν σωστά τα υπάρχοντα δεδομένα.","Multiomics-Evidenz priorisieren und verdichten":"Ιεραρχήστε και συμπυκνώστε την τεκμηρίωση multiomics","Multiomics-Kernaussage":"Βασικό μήνυμα multiomics","Kernaussage: pathogene IDH1-Alteration als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. FGFR2-Überexpression sowie EMT/MET-Signaturen bleiben explorativ und dürfen nicht wie validierte prädiktive Targets kommuniziert werden.":"Βασικό μήνυμα: παθογόνος αλλοίωση IDH1 ως καθιερωμένος σχετιζόμενος με τον όγκο βιοδείκτης· καμία σύντηξη FGFR2. Η υπερέκφραση FGFR2 και οι υπογραφές EMT/MET παραμένουν διερευνητικές και δεν πρέπει να παρουσιάζονται ως επικυρωμένοι προβλεπτικοί στόχοι.","Noch breiteres Panel":"Ακόμη ευρύτερο panel","Mehr Daten lösen die zentrale Aufgabe – Evidenzhierarchie und klare Kommunikation – nicht.":"Περισσότερα δεδομένα δεν λύνουν το κεντρικό πρόβλημα — ιεράρχηση τεκμηρίωσης και σαφής επικοινωνία.","Informationsdichte":"Πυκνότητα πληροφορίας","Viele biologisch interessante Signale, aber nur wenige direkt handlungsleitende Befunde.":"Πολλά βιολογικά ενδιαφέροντα σήματα, αλλά λίγα ευρήματα που καθοδηγούν άμεσα απόφαση.","Multiomics braucht Evidenzhierarchie, nicht nur Datensynthese.":"Τα multiomics χρειάζονται ιεράρχηση τεκμηρίωσης, όχι απλώς σύνθεση δεδομένων.","Der Bericht wird auf eine belastbare klinische Kernaussage reduziert: pathogene IDH1-Veränderung als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression ist nicht gleichbedeutend mit einer FGFR2-Fusion, und EMT/MET-/Pathway-Signaturen bleiben ohne passende klinische Validierung explorativ. Das MTB erhält Evidenzstufen statt Datenrauschen.":"Η αναφορά συμπυκνώνεται σε ένα αξιόπιστο κλινικό βασικό μήνυμα: παθογόνος αλλοίωση IDH1 ως καθιερωμένος σχετιζόμενος με τον όγκο βιοδείκτης· καμία σύντηξη FGFR2. Η υψηλή έκφραση FGFR2 δεν ισοδυναμεί με σύντηξη FGFR2 και οι υπογραφές EMT/MET/μονοπατιών παραμένουν διερευνητικές χωρίς κατάλληλη κλινική επικύρωση. Το ογκολογικό συμβούλιο λαμβάνει επίπεδα τεκμηρίωσης αντί για θόρυβο δεδομένων.","Teilbefund: Multiomics ist nur dann klinisch nützlich, wenn validierte Biomarker, Kontextsignale und Hypothesen klar getrennt werden.":"Μερικό αποτέλεσμα: τα multiomics είναι κλινικά χρήσιμα μόνο όταν οι επικυρωμένοι βιοδείκτες, τα σήματα πλαισίου και οι υποθέσεις διαχωρίζονται σαφώς.","Befunde nach klinischer Evidenz ordnen":"Ιεράρχηση ευρημάτων βάσει κλινικής τεκμηρίωσης","Expression nicht mit Fusion gleichsetzen":"Μην εξισώνετε την έκφραση με τη σύντηξη","explorative Signaturen als Hypothesen kennzeichnen":"Χαρακτηρίστε τις διερευνητικές υπογραφές ως υποθέσεις","Falschaussage: stärkstes Heatmap-Signal = bestes Target":"Λανθασμένη δήλωση: ισχυρότερο σήμα heatmap = καλύτερος στόχος","Optimale Lösung: aus vielen Daten eine kurze Evidenzhierarchie bauen – gesicherter Biomarker zuerst, relevante negative Befunde danach, explorative Omics klar als Hypothesen.":"Βέλτιστη λύση: δημιουργήστε από πολλά δεδομένα μια σύντομη ιεράρχηση τεκμηρίωσης — πρώτα ο καθιερωμένος βιοδείκτης, έπειτα τα σχετικά αρνητικά ευρήματα και τα διερευνητικά omics σαφώς χαρακτηρισμένα ως υποθέσεις.","Multiomics":"Multiomics","MTB-RES":"MTB-RES","23 Seiten auf drei Sätze reduzieren":"Συμπυκνώστε 23 σελίδες σε τρεις προτάσεις","Präzisionsonkologie / MTB-Kommunikation":"Ογκολογία ακριβείας / επικοινωνία στο ογκολογικό συμβούλιο","Multiomics-Befunde nach klinischer Evidenz hierarchisieren.":"Ιεραρχήστε τα ευρήματα multiomics βάσει κλινικής τεκμηρίωσης.","Genomische Alteration, Expression und Pathway-Signatur nicht miteinander gleichsetzen.":"Μην εξισώνετε γονιδιωματική αλλοίωση, έκφραση και υπογραφή μονοπατιού.","Relevante Negativbefunde sichtbar halten.":"Διατηρήστε ορατά τα σχετικά αρνητικά ευρήματα.","Explorative Hypothesen klar von handlungsleitenden Biomarkern trennen.":"Διαχωρίστε σαφώς τις διερευνητικές υποθέσεις από τους βιοδείκτες που καθοδηγούν απόφαση.","Eine präzise MTB-Kernaussage aus Datenfülle formulieren.":"Διατυπώστε ένα ακριβές βασικό μήνυμα για το ογκολογικό συμβούλιο από μια αναφορά πλούσια σε δεδομένα.","Der Report ist 23 Seiten lang. Das Tumorboard hat sieben Minuten. Die Aufgabe ist nicht, alles vorzulesen – sondern zu wissen, welche zwei Sätze wirklich eine Entscheidung tragen.":"Η αναφορά έχει 23 σελίδες. Το ογκολογικό συμβούλιο έχει επτά λεπτά. Το ζητούμενο δεν είναι να διαβαστούν όλα — αλλά να γνωρίζετε ποιες δύο προτάσεις στηρίζουν πραγματικά μια απόφαση.","59-jährige Patientin mit intrahepatischem Cholangiokarzinom. DNA, RNA und weitere Omics-Layer liegen vor. Eine pathogene IDH1-Alteration ist klar, eine FGFR2-Fusion fehlt, während FGFR2-Expression und mehrere Pathway-Scores hoch sind.":"Γυναίκα 59 ετών με ενδοηπατικό χολαγγειοκαρκίνωμα. Υπάρχουν δεδομένα DNA, RNA και πρόσθετων επιπέδων omics. Υπάρχει σαφής παθογόνος αλλοίωση IDH1, δεν ανιχνεύεται σύντηξη FGFR2, ενώ η έκφραση FGFR2 και αρκετές βαθμολογίες μονοπατιών είναι υψηλές.","Evidenz vor Datenmenge":"Η τεκμηρίωση πριν από τον όγκο δεδομένων","Ein validierter Biomarker wiegt klinisch mehr als viele explorative Signaturen.":"Ένας επικυρωμένος βιοδείκτης έχει μεγαλύτερη κλινική βαρύτητα από πολλές διερευνητικές υπογραφές.","Informationsmenge ist keine Evidenzstufe.":"Η ποσότητα πληροφορίας δεν αποτελεί επίπεδο τεκμηρίωσης.","Expression ≠ Fusion":"Έκφραση ≠ σύντηξη","Hohe FGFR2-mRNA ist biologisch interessant, aber nicht dasselbe wie ein nachgewiesenes FGFR2-Fusionsereignis.":"Υψηλό FGFR2 mRNA είναι βιολογικά ενδιαφέρον, αλλά δεν είναι το ίδιο με τεκμηριωμένο συμβάν σύντηξης FGFR2.","Omics-Layer messen unterschiedliche Phänomene.":"Τα επίπεδα omics μετρούν διαφορετικά φαινόμενα.","Negative Befunde können entscheidend sein":"Τα αρνητικά ευρήματα μπορεί να είναι καθοριστικά","„Keine FGFR2-Fusion“ verhindert ein falsches Target-Narrativ.":"«Καμία σύντηξη FGFR2» αποτρέπει ένα ψευδές αφήγημα στόχου.","Klinische Zusammenfassung braucht auch relevante Ausschlüsse.":"Μια κλινική σύνοψη χρειάζεται και σχετικά αρνητικά ευρήματα.","IDH1 p.R132C pathogen":"IDH1 p.R132C παθογόνο","keine FGFR2-Fusion":"καμία σύντηξη FGFR2","FGFR2 hoch exprimiert; EMT/MET-Signaturen erhöht":"Υψηλή έκφραση FGFR2· αυξημένες υπογραφές EMT/MET","Immunkontext":"Ανοσολογικό πλαίσιο","MSS, TMB niedrig, PD-L1 niedrig":"MSS, χαμηλό TMB, χαμηλό PD-L1","Alle Daten bereits vorhanden.":"Όλα τα δεδομένα είναι ήδη διαθέσιμα.","Keine akute Materialfrage.":"Δεν υπάρχει οξύ πρόβλημα υλικού.","Limitierend ist die Evidenzinterpretation, nicht die Messkapazität.":"Ο περιορισμός είναι η ερμηνεία της τεκμηρίωσης, όχι η μετρητική ικανότητα.","Was gehört in die erste Zeile der MTB-Zusammenfassung?":"Τι πρέπει να μπει στην πρώτη γραμμή της σύνοψης του ογκολογικού συμβουλίου;","Der klinisch am besten validierte relevante Biomarker und seine konkrete Bedeutung.":"Ο κλινικά καλύτερα επικυρωμένος σχετικός βιοδείκτης και η συγκεκριμένη σημασία του.","Die stärkste Farbe der Heatmap.":"Το πιο έντονο χρώμα στο heatmap.","Alle 200 Signaturen alphabetisch.":"Και οι 200 υπογραφές αλφαβητικά.","Jede VUS vor gesicherten Befunden.":"Κάθε VUS πριν από τα τεκμηριωμένα ευρήματα.","MTB-Kommunikation priorisiert klinische Evidenz.":"Η επικοινωνία στο ογκολογικό συμβούλιο ιεραρχεί την κλινική τεκμηρίωση.","Was bedeutet hohe FGFR2-Expression ohne nachgewiesene FGFR2-Fusion?":"Τι σημαίνει υψηλή έκφραση FGFR2 χωρίς τεκμηριωμένη σύντηξη FGFR2;","Biologischer/explorativer Kontext, aber kein automatischer Ersatz für den validierten Fusionsbiomarker.":"Βιολογικό/διερευνητικό πλαίσιο, αλλά όχι αυτόματο υποκατάστατο του επικυρωμένου βιοδείκτη σύντηξης.","Eine Fusion ist damit bewiesen.":"Με αυτό αποδεικνύεται σύντηξη.","Target-Therapie ist allein dadurch zwingend.":"Η στοχευμένη θεραπεία είναι υποχρεωτική μόνο βάσει αυτού.","RNA ist grundsätzlich Artefakt.":"Το RNA είναι εγγενώς τεχνούργημα.","Expression und strukturelle Genfusion sind verschiedene Befundarten.":"Η έκφραση και η δομική γονιδιακή σύντηξη είναι διαφορετικοί τύποι ευρημάτων.","Warum ist „keine FGFR2-Fusion“ ein wichtiger Befund?":"Γιατί είναι σημαντικό εύρημα το «καμία σύντηξη FGFR2»;","Er verhindert, dass die hohe Expression fälschlich als etablierter Fusions-Targetkontext verkauft wird.":"Αποτρέπει την εσφαλμένη παρουσίαση της υψηλής έκφρασης ως καθιερωμένου πλαισίου στόχου σύντηξης.","Negative Befunde gehören nie ins MTB.":"Τα αρνητικά ευρήματα δεν ανήκουν ποτέ στο ογκολογικό συμβούλιο.","Er hat keinerlei Interpretationswert.":"Δεν έχει καμία ερμηνευτική αξία.","Er macht IDH1 automatisch negativ.":"Καθιστά αυτόματα το IDH1 αρνητικό.","Relevante Negativbefunde begrenzen falsche Handlungsableitungen.":"Τα σχετικά αρνητικά ευρήματα περιορίζουν λανθασμένα συμπεράσματα περί actionability.","Der Bericht rankt „FGFR pathway activation“ als stärkstes Signal. Was tun Sie?":"Η αναφορά κατατάσσει την «ενεργοποίηση της οδού FGFR» ως το ισχυρότερο σήμα. Τι κάνετε;","Als explorative Signatur kennzeichnen und hinter validierten molekularen Befunden priorisieren.":"Χαρακτηρίστε το ως διερευνητική υπογραφή και ιεραρχήστε το μετά τα επικυρωμένα μοριακά ευρήματα.","Als stärkstes Target behandeln.":"Αντιμετωπίστε το ως τον ισχυρότερο στόχο.","Alle Omics-Daten verwerfen.":"Απορρίψτε όλα τα δεδομένα omics.","Eine FGFR2-Fusion daraus ableiten.":"Συμπεράνετε σύντηξη FGFR2 από αυτό.","Pathway-Scores sind ohne entsprechende klinische Validierung Hypothesen, keine automatischen Companion Biomarker.":"Χωρίς αντίστοιχη κλινική επικύρωση, οι βαθμολογίες μονοπατιών είναι υποθέσεις και όχι αυτόματοι companion biomarkers.","Verdichten Sie den Multiomics-Bericht zu einer evidenzhierarchischen MTB-Kernaussage.":"Συμπυκνώστε την αναφορά multiomics σε ένα βασικό μήνυμα για το ογκολογικό συμβούλιο με ιεράρχηση τεκμηρίωσης.","Validierte/etablierte Biomarker identifizieren.":"Εντοπίστε επικυρωμένους/καθιερωμένους βιοδείκτες.","Relevante negative Befunde sichtbar machen.":"Καταστήστε ορατά τα σχετικά αρνητικά ευρήματα.","Expression, Fusion, Protein und Pathways als unterschiedliche Ebenen behandeln.":"Αντιμετωπίστε έκφραση, σύντηξη, πρωτεΐνη και μονοπάτια ως διαφορετικά επίπεδα.","Explorative Signaturen kennzeichnen.":"Χαρακτηρίστε τις διερευνητικές υπογραφές.","MTB-Aussage auf Entscheidung statt Dateninventar fokussieren.":"Εστιάστε τη δήλωση του ογκολογικού συμβουλίου στην απόφαση και όχι στην απογραφή δεδομένων.","Explorative Omics können für Studienhypothesen oder Translation wertvoll sein; sie gehören nur nicht unmarkiert in dieselbe Evidenzstufe wie validierte klinische Biomarker.":"Τα διερευνητικά omics μπορεί να είναι πολύτιμα για ερευνητικές υποθέσεις ή μεταφραστική έρευνα· απλώς δεν πρέπει να τοποθετούνται χωρίς επισήμανση στο ίδιο επίπεδο τεκμηρίωσης με επικυρωμένους κλινικούς βιοδείκτες.","Heatmap-Tophit = Target":"Κορυφαίο hit heatmap = στόχος","Visuelle Effektstärke ersetzt keine klinische Validierung.":"Το οπτικό μέγεθος επίδρασης δεν αντικαθιστά την κλινική επικύρωση.","Alles in einen Satz pressen":"Συμπυκνώστε τα πάντα σε μία πρόταση","Verwischt Evidenzstufen.":"Θολώνει τα επίπεδα τεκμηρίωσης.","Exploratives komplett löschen":"Διαγράψτε πλήρως τα διερευνητικά δεδομένα","Verliert wissenschaftlich wertvolle Hypothesen; besser klar labeln.":"Χάνει επιστημονικά πολύτιμες υποθέσεις· καλύτερα να επισημαίνονται σαφώς.","Der lauteste Signalweg ist nicht die stärkste klinische Aussage":"Το πιο «ηχηρό» μονοπάτι δεν είναι η ισχυρότερη κλινική δήλωση","FGFR2-Expression ist hoch, aber es gibt keine FGFR2-Fusion. Die belastbare Topline bleibt die pathogene IDH1-Alteration; Omics-Signaturen werden als explorativ eingeordnet.":"Η έκφραση FGFR2 είναι υψηλή, αλλά δεν υπάρχει σύντηξη FGFR2. Το αξιόπιστο κύριο μήνυμα παραμένει η παθογόνος αλλοίωση IDH1· οι υπογραφές omics κατατάσσονται ως διερευνητικές.","Der Twist dreht die Priorität von Signalstärke zu Evidenzstärke.":"Η ανατροπή μετατοπίζει την προτεραιότητα από την ένταση του σήματος στην ισχύ της τεκμηρίωσης.","Klarer Biomarker, klarer Ausschluss, klar markierte Hypothesen.":"Σαφής βιοδείκτης, σαφής αποκλεισμός, σαφώς επισημασμένες υποθέσεις.","MTB-taugliche Verdichtung.":"Συμπύκνωση κατάλληλη για ογκολογικό συμβούλιο.","Report vorgelesen":"Ανάγνωση της αναφοράς","Viele Daten, keine Entscheidung.":"Πολλά δεδομένα, καμία απόφαση.","Informationsüberlastung.":"Υπερφόρτωση πληροφορίας.","FGFR2-expression als Fusion behandelt":"Η έκφραση FGFR2 αντιμετωπίζεται ως σύντηξη","Explorativer Befund wird targetiert.":"Το διερευνητικό εύρημα στοχοποιείται.","Layer-Verwechslung.":"Σύγχυση επιπέδων.","Omics-Signal ohne validierten klinischen Biomarkerstatus":"Σήμα omics χωρίς επικυρωμένη κατάσταση κλινικού βιοδείκτη","als explorativ/hypothesengenerierend kennzeichnen":"χαρακτηρίστε ως διερευνητικό/παραγωγό υποθέσεων","nicht auf gleiche Ebene wie etablierte prädiktive Marker stellen.":"μην τοποθετείτε στο ίδιο επίπεδο με καθιερωμένους προβλεπτικούς δείκτες.","Multiomics braucht Evidenzhierarchie.":"Τα multiomics χρειάζονται ιεράρχηση τεκμηρίωσης.","Biologische Plausibilität ist nicht identisch mit klinischer Actionability.":"Η βιολογική ευλογοφάνεια δεν ταυτίζεται με την κλινική actionability.","Gute MTB-Kommunikation ist selektiv und transparent.":"Η καλή επικοινωνία στο ογκολογικό συμβούλιο είναι επιλεκτική και διαφανής.","Kernaussage: pathogene IDH1-Alteration als belastbarer tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression und Pathway-Signaturen sind explorativ und nicht als validierte Targets zu überinterpretieren.":"Βασικό μήνυμα: παθογόνος αλλοίωση IDH1 ως αξιόπιστος σχετιζόμενος με τον όγκο βιοδείκτης· καμία σύντηξη FGFR2. Η υψηλή έκφραση FGFR2 και οι υπογραφές μονοπατιών είναι διερευνητικές και δεν πρέπει να υπερερμηνεύονται ως επικυρωμένοι στόχοι.","Evidenzpriorisierung":"Ιεράρχηση τεκμηρίωσης","Omics-Layer":"Επίπεδα omics","Wie viele Ebenen sollte ein MTB-Report zeigen?":"Πόσα επίπεδα πρέπει να εμφανίζει μια αναφορά για ογκολογικό συμβούλιο;","Wie labelt man explorative Signaturen?":"Πώς επισημαίνετε τις διερευνητικές υπογραφές;","Welche negativen Befunde sind entscheidungsrelevant?":"Ποια αρνητικά ευρήματα είναι σημαντικά για την απόφαση;","Twist: stärkstes Signal ist nicht stärkste Evidenz":"Ανατροπή: το ισχυρότερο σήμα δεν είναι η ισχυρότερη τεκμηρίωση","Referenzpfad: validiert → relevante Negative → explorativ":"Διαδρομή αναφοράς: επικυρωμένο → σχετικά αρνητικά → διερευνητικό","dna_rna_lung_combo":"Συνδυασμένο πνευμονικό πάνελ DNA/RNA","Resistenzdiagnostik bei Progress":"Έλεγχος μηχανισμών αντοχής κατά την πρόοδο","Gewebe-Rebiopsie bei negativer Liquid Biopsy":"Επαναβιοψία ιστού μετά από αρνητική υγρή βιοψία","Liquid Biopsy richtig einordnen":"Ορθή ερμηνεία της υγρής βιοψίας","Progressionspanel: erworbener Resistenzmechanismus wird plausibilisiert; Liquid Biopsy allein ist bei negativem Ergebnis nicht ausreichend.":"Πάνελ κατά την πρόοδο: τεκμηριώνεται πιθανός επίκτητος μηχανισμός αντοχής· μια αρνητική υγρή βιοψία από μόνη της δεν επαρκεί.","Rebiopsie liefert beurteilbares Tumormaterial für Resistenzanalyse.":"Η επαναβιοψία παρέχει αξιολογήσιμο νεοπλασματικό υλικό για ανάλυση αντοχής.","Negative Liquid Biopsy wird nur mit ctDNA-/Materialkontext interpretiert; Rebiopsie bleibt Option.":"Μια αρνητική υγρή βιοψία ερμηνεύεται μόνο στο πλαίσιο του ctDNA και της επάρκειας του δείγματος· η επαναβιοψία παραμένει επιλογή.","Integrierte Interpretation vollständig: Liquid Biopsy negativ: reicht das oder Rebiopsie? Die gewählten Methoden beantworten die Kernfrage mit angemessener Aussagekraft und Limitationen.":"Ολοκληρωμένη ερμηνεία: αρνητική υγρή βιοψία — αρκεί ή απαιτείται επαναβιοψία; Οι επιλεγμένες μέθοδοι απαντούν στο βασικό ερώτημα με κατάλληλη διαγνωστική ισχύ και σαφείς περιορισμούς.","Teilbefund: Für die Kernentscheidung („Liquid Biopsy negativ: reicht das oder Rebiopsie?“) fehlen noch zentrale Bausteine oder die Methode ist zu eng gewählt.":"Μερικό αποτέλεσμα: για τη βασική απόφαση («Αρνητική υγρή βιοψία: αρκεί ή χρειάζεται επαναβιοψία;») λείπουν ακόμη κρίσιμα στοιχεία ή η επιλεγμένη μέθοδος είναι υπερβολικά περιορισμένη.","Resistenzdiagnostik bei Progress in der MTB-Kernaussage korrekt einordnen":"Ορθή ένταξη του ελέγχου αντοχής κατά την πρόοδο στο βασικό μήνυμα του MTB","Gewebe-Rebiopsie bei negativer Liquid Biopsy in der MTB-Kernaussage korrekt einordnen":"Ορθή ένταξη της επαναβιοψίας ιστού μετά από αρνητική υγρή βιοψία στο βασικό μήνυμα του MTB","Liquid Biopsy richtig einordnen in der MTB-Kernaussage korrekt einordnen":"Ορθή ερμηνεία της υγρής βιοψίας στο βασικό μήνυμα του MTB","Optimale Lösung: Liquid Biopsy negativ: reicht das oder Rebiopsie? – mit fallgerechter Methodenkombination, Material-/QC-Bewertung und klarer MTB-Kommunikation.":"Βέλτιστη λύση: αρνητική υγρή βιοψία — αρκεί ή απαιτείται επαναβιοψία; Χρησιμοποιήστε συνδυασμό μεθόδων κατάλληλο για το περιστατικό, αξιολογήστε το πλαίσιο δείγματος/QC και διατυπώστε σαφώς το συμπέρασμα στο MTB.","RNA-Fusionsdiagnostik primär fehlt":"Λείπει ο πρωτογενής έλεγχος συντήξεων με RNA","entitätsfremde Tests gewählt":"Επιλέχθηκαν εξετάσεις άσχετες με τη συγκεκριμένη οντότητα","nur Liquid Biopsy gewählt":"Επιλέχθηκε μόνο υγρή βιοψία","Rebiopsie gewählt, aber MET/CNV/Transformation nicht bedacht":"Επιλέχθηκε επαναβιοψία, αλλά δεν εξετάστηκαν MET/CNV/ιστολογικός μετασχηματισμός","MTB Basics / Präanalytik":"Βασικές αρχές MTB / Προαναλυτική φάση","colon_ngs_panel":"Πάνελ NGS για καρκίνο παχέος εντέρου","MTB Basics / Genominstabilität":"Βασικές αρχές MTB / Γονιδιωματική αστάθεια","broad_pan_panel":"Ευρύ πάνελ pan-cancer","MTB Basics / Advanced":"Βασικές αρχές MTB / Προχωρημένο","hoch.":"υψηλό.","MTB / Molecular Diagnostics":"MTB / Μοριακή διαγνωστική","wildtyp":"άγριος τύπος"},"es":{"ERBB2-VUS im RAS/BRAF-WT-mCRC: Genname ist noch kein Target":"VUS de ERBB2 en mCRC RAS/BRAF-WT: el nombre del gen aún no es una diana terapéutica","VUS im Onkogen":"VUS en un oncogén","Initialer Auftrag":"Solicitud inicial","Einsender":"Solicitante","Gastroonkologie / Molekulares Tumorboard":"Oncología gastrointestinal / Comité Molecular de Tumores","Klinische Information":"Información clínica","63-jährige Patientin mit linksseitigem metastasiertem CRC und Progress nach mehreren Therapielinien. Ein externer NGS-Bericht markiert „ERBB2 altered“ prominent.":"Paciente de 63 años con CRC metastásico izquierdo y progresión tras varias líneas de tratamiento. Un informe NGS externo destaca de forma prominente «ERBB2 altered». ","Fragestellung":"Pregunta clínica","Reicht eine seltene ERBB2-Missense-VUS als Grundlage für HER2-gerichtete Therapie?":"¿Es suficiente una VUS missense rara de ERBB2 para justificar una terapia dirigida a HER2?","Zeitfenster":"Plazo","Nächste Therapielinie soll im MTB diskutiert werden.":"La siguiente línea de tratamiento se discutirá en el comité molecular.","Anamnese und klinischer Kontext":"Antecedentes y contexto clínico","Molekularer Kontext":"Contexto molecular","KRAS/NRAS/BRAF wildtyp, pMMR/MSS.":"KRAS/NRAS/BRAF de tipo salvaje, pMMR/MSS.","Externer Report":"Informe externo","Seltene ERBB2-Missense-Variante, VAF 18 %, Klassifikation VUS; im Summary trotzdem gelb als „potential target“ hervorgehoben.":"Variante missense rara de ERBB2, VAF 18 %, clasificada como VUS; pese a ello aparece resaltada en amarillo en el resumen como «potential target». ","Didaktische Falle":"Trampa didáctica","Genname, Datenbanktreffer und Actionability werden miteinander vermischt.":"Se están confundiendo el nombre del gen, el hallazgo en una base de datos y la accionabilidad.","Ziel":"Objetivo","Variante, Biomarker und klinische Evidenz getrennt bewerten.":"Evaluar por separado la variante, el biomarcador y la evidencia clínica.","Histologie + Vorinformation":"Histología + información previa","Histologie":"Histología","Metastasiertes kolorektales Adenokarzinom.":"Adenocarcinoma colorrectal metastásico.","HER2-IHC":"IHC de HER2","noch nicht erfolgt.":"aún no realizada.","ISH":"ISH","Offen":"Pendiente","Gibt es unabhängig von der VUS einen etablierten HER2-Biomarker?":"¿Existe un biomarcador HER2 establecido independientemente de la VUS?","Materialprüfung":"Revisión del material","Material":"Material","FFPE-Metastase, ausreichend.":"Metástasis FFPE, material suficiente.","Tumoranteil":"Fracción tumoral","ca. 55 %.":"aprox. 55 %.","NGS-QC":"QC de NGS","Variante technisch robust detektiert.":"Variante detectada con alta robustez técnica.","Wichtig":"Importante","Technisch echt bedeutet nicht automatisch klinisch bedeutsam.":"Que sea técnicamente real no significa automáticamente que sea clínicamente relevante.","ERBB2-Variantenbewertung":"Evaluación de la variante ERBB2","VUS-/Evidenzkurationsschritt":"Paso de curación de VUS/evidencia","Unabhängigen HER2-Biomarker prüfen":"Evaluar un biomarcador HER2 independiente","ERBB2-NGS":"NGS de ERBB2","Seltene ERBB2-Missense-Variante, VAF 18 %, technisch robust; aktuelle Klassifikation VUS.":"Variante missense rara de ERBB2, VAF 18 %, técnicamente robusta; clasificación actual: VUS.","VUS-Curation":"Curación de VUS","Keine ausreichende klinische Evidenz für prädiktive Actionability; einzelne präklinische Hinweise reichen nicht zur Hochstufung.":"Evidencia clínica insuficiente para una accionabilidad predictiva; los indicios preclínicos aislados no bastan para reclasificarla al alza.","HER2 IHC 1+, keine starke membranöse Überexpression.":"IHC de HER2 1+, sin sobreexpresión membranosa intensa.","HER2-FISH/ISH":"FISH/ISH de HER2","Keine ERBB2-Amplifikation.":"Sin amplificación de ERBB2.","Fehlentscheidung":"Decisión incorrecta","Eine direkte HER2-Therapieempfehlung allein aus einer VUS wäre ein Evidenz-Overcall.":"Recomendar directamente una terapia dirigida a HER2 basándose solo en una VUS sería una sobreinterpretación de la evidencia.","Die VUS ist technisch real detektiert.":"La VUS es técnicamente real.","Kernaussage":"Mensaje clave","Technische Echtheit, Pathogenität und prädiktive Actionability sind drei getrennte Ebenen.":"La validez técnica, la patogenicidad y la accionabilidad predictiva son tres niveles distintos.","Die ERBB2-Variante ist technisch robust, aber klinisch weiterhin VUS und darf nicht als gesicherter prädiktiver Biomarker behandelt werden. HER2-IHC 1+ und fehlende ERBB2-Amplifikation liefern keinen unabhängigen etablierten HER2-Amplifikationskontext. Eine Therapieempfehlung allein aus der VUS wäre nicht evidenzbasiert.":"La variante ERBB2 es técnicamente robusta, pero clínicamente sigue siendo una VUS y no debe tratarse como un biomarcador predictivo establecido. La IHC HER2 1+ y la ausencia de amplificación de ERBB2 no aportan un contexto independiente establecido de amplificación de HER2. Una recomendación terapéutica basada solo en la VUS no estaría respaldada por la evidencia.","Teilbefund: Ein technisch echter Variantenfund ist ohne belastbare funktionelle/klinische Evidenz nicht automatisch actionable.":"Resultado parcial: un hallazgo de variante técnicamente real no es automáticamente accionable sin evidencia funcional/clínica sólida.","VUS klar als VUS benennen":"Identificar claramente la VUS como VUS","technische Validität, Pathogenität und Actionability trennen":"separar la validez técnica, la patogenicidad y la accionabilidad","IHC/ISH als separaten Biomarkerpfad verstehen":"entender la IHC/ISH como una vía de biomarcador HER2 independiente","Falschaussage: ERBB2 steht im Genfeld, also ist HER2-Therapie indiziert":"Afirmación falsa: ERBB2 aparece en el campo del gen, por tanto está indicada una terapia anti-HER2","Optimale Lösung: ERBB2-VUS nicht overcallen, unabhängige HER2-Biomarker separat prüfen und die Therapieaussage an Evidenz statt an Genname oder Datenbankfarbe koppeln.":"Solución óptima: no sobreinterpretar la VUS de ERBB2, evaluar por separado biomarcadores HER2 independientes y basar la conclusión terapéutica en la evidencia, no en el nombre del gen ni en el color de una base de datos.","VUS":"VUS","ERBB2":"ERBB2","HER2":"HER2","Evidenz":"Evidencia","MTB":"MTB","Deep Dive":"Deep Dive","Das gelbe „potential target“":"El «potential target» amarillo","Molekulares Tumorboard / Varianteninterpretation":"Comité Molecular de Tumores / interpretación de variantes","VUS nicht als pathogene/actionable Variante berichten.":"No informar una VUS como patogénica/accionable.","Technische Validität, biologische Pathogenität und klinische Prädiktion trennen.":"Separar la validez técnica, la patogenicidad biológica y la predicción clínica.","IHC/ISH bei HER2 als eigenständigen Biomarkerpfad einordnen.":"Considerar la IHC/ISH de HER2 como una vía de biomarcador independiente.","Datenbank-/Software-Highlights nicht mit klinischer Evidenz verwechseln.":"No confundir los resaltados de bases de datos/software con evidencia clínica.","Im externen Report ist ERBB2 gelb hervorgehoben: „potential target“. In der Detailzeile steht jedoch schlicht VUS. Der Fall ist ein Test dafür, ob das Board die Farbe oder die Evidenz liest.":"En el informe externo, ERBB2 aparece resaltado en amarillo: «potential target». Sin embargo, en la línea de detalle figura simplemente VUS. El caso pone a prueba si el comité lee el color o la evidencia.","63-jährige Patientin mit RAS/BRAF-WT-mCRC. Eine seltene ERBB2-Missense-Variante ist technisch sicher detektiert, aber als VUS klassifiziert. Das Board soll entscheiden, ob daraus eine HER2-gerichtete Therapieaussage entsteht.":"Paciente de 63 años con mCRC RAS/BRAF-WT. Una variante missense rara de ERBB2 está técnicamente bien sustentada, pero clasificada como VUS. El comité debe decidir si de ello puede derivarse una conclusión terapéutica dirigida a HER2.","Drei Ebenen":"Tres niveles","Call echt? Variante pathogen? Befund prädiktiv?":"¿Call real? ¿Variante patogénica? ¿Hallazgo predictivo?","Diese Ebenen dürfen nicht zusammenfallen.":"Estos niveles no deben confundirse entre sí.","HER2 ist mehr als ein Genname":"HER2 es más que el nombre de un gen","Amplifikation/Überexpression und einzelne Sequenzvarianten sind unterschiedliche Biomarker.":"La amplificación/sobreexpresión y las variantes de secuencia individuales son biomarcadores distintos.","Methoden beantworten verschiedene Fragen.":"Los métodos responden a preguntas diferentes.","Software ist keine Leitlinie":"El software no es una guía clínica","Ein automatisch hervorgehobener Datenbanktreffer kann evidenzarm sein.":"Un hallazgo de base de datos resaltado automáticamente puede tener evidencia débil.","Finale Interpretation bleibt fachlich verantwortlich.":"La interpretación final sigue siendo una responsabilidad profesional.","ERBB2-Variante":"Variante ERBB2","VAF 18 %, technisch robust, Klassifikation VUS":"VAF 18 %, técnicamente robusta, clasificada como VUS","RAS/BRAF":"RAS/BRAF","MMR/MSI":"MMR/MSI","pMMR/MSS":"pMMR/MSS","Material ausreichend.":"Material suficiente.","Keine analytische Unsicherheit des Calls – die Unsicherheit ist interpretativ.":"No existe incertidumbre analítica del call; la incertidumbre es interpretativa.","Der Fall verlangt keine Therapieempfehlung aus einem nicht etablierten VUS.":"El caso no exige una recomendación terapéutica a partir de una VUS no establecida.","Was ist die korrekte Bedeutung einer technisch robusten ERBB2-VUS?":"¿Cuál es el significado correcto de una VUS de ERBB2 técnicamente robusta?","Die Variante ist nach aktueller Evidenz nicht ausreichend als pathogen/prädiktiv klassifiziert.":"Según la evidencia actual, la variante no está suficientemente clasificada como patogénica/predictiva.","Jede ERBB2-Variante ist actionable.":"Toda variante de ERBB2 es accionable.","VUS bedeutet sicher benign.":"VUS significa con certeza benigna.","VUS bedeutet Keimbahn.":"VUS significa germinal.","VUS beschreibt unzureichende Evidenz, nicht eine halbe Therapieindikation.":"VUS describe evidencia insuficiente, no media indicación terapéutica.","Welche Ebenen müssen getrennt bewertet werden?":"¿Qué niveles deben evaluarse por separado?","analytische Echtheit des Calls":"validez analítica del call","Pathogenität/biologische Bedeutung":"patogenicidad/significado biológico","klinisch-prädiktive Evidenz":"evidencia clínica predictiva","Farbe im Software-Report":"color en el informe del software","Der Software-Look ist keine Evidenzebene.":"El aspecto del software no constituye un nivel de evidencia.","HER2 IHC 1+ und keine ERBB2-Amplifikation: Was folgt daraus?":"IHC HER2 1+ y sin amplificación de ERBB2: ¿qué se concluye?","Es liegt kein unabhängiger etablierter Amplifikations-/Überexpressionsbefund vor, der die VUS „rettet“.":"No existe un hallazgo independiente establecido de amplificación/sobreexpresión que «rescate» la VUS.","Damit wird die VUS automatisch pathogen.":"Esto hace que la VUS sea automáticamente patogénica.","HER2-Therapie ist allein dadurch zwingend.":"Solo por ello, la terapia dirigida a HER2 es obligatoria.","IHC/ISH und Sequenzierung messen exakt dasselbe.":"La IHC/ISH y la secuenciación miden exactamente lo mismo.","Die Methoden adressieren unterschiedliche Biomarker.":"Los métodos evalúan biomarcadores diferentes.","Eine Datenbank nennt einen präklinischen Zelllinienhinweis. Reicht das zur Therapieableitung?":"Una base de datos cita un hallazgo preclínico en una línea celular. ¿Basta para derivar una terapia?","Nein; präklinische Hinweise können Hypothesen stützen, ersetzen aber keine ausreichende klinische Evidenz für diese VUS.":"No; los hallazgos preclínicos pueden apoyar hipótesis, pero no sustituyen una evidencia clínica suficiente para esta VUS.","Ja, jeder präklinische Treffer macht eine VUS actionable.":"Sí, cualquier hallazgo preclínico convierte una VUS en accionable.","Literatur ist grundsätzlich irrelevant.":"La literatura es fundamentalmente irrelevante.","Die Variante wird automatisch Tier I.":"La variante pasa automáticamente a Tier I.","Evidenzhierarchie und variantenspezifische Daten müssen berücksichtigt werden.":"Deben considerarse la jerarquía de evidencia y los datos específicos de la variante.","Formulieren Sie eine MTB-Kernaussage, die den ERBB2-Fund korrekt einordnet, ohne ihn zu overcallen.":"Formule un mensaje clave para el comité que clasifique correctamente el hallazgo ERBB2 sin sobreinterpretarlo.","Technische Echtheit bestätigen.":"Confirmar la validez técnica.","Aktuelle Variantenklassifikation übernehmen bzw. fachlich kuratieren.":"Adoptar o revisar profesionalmente la clasificación actual de la variante.","Keine Pathogenität/Actionability aus dem Genname ableiten.":"No inferir patogenicidad/accionabilidad a partir del nombre del gen.","HER2-IHC/ISH als separaten Biomarkerpfad bewerten.":"Evaluar la IHC/ISH de HER2 como una vía de biomarcador separada.","VUS klar und nicht handlungsleitend kommunizieren; Re-Evaluation bei neuer Evidenz möglich.":"Comunicar claramente la VUS como no orientadora de conducta; puede reevaluarse si aparece nueva evidencia.","Studieneinschluss kann je nach Protokoll breitere molekulare Kriterien verwenden; das ist von einer etablierten Therapieempfehlung zu trennen.":"Según el protocolo, la inclusión en un ensayo puede utilizar criterios moleculares más amplios; esto debe distinguirse de una recomendación terapéutica establecida.","Genname = Target":"Nombre del gen = diana","Ignoriert Variantenspezifität und Evidenz.":"Ignora la especificidad de la variante y la evidencia.","VUS = benign":"VUS = benigna","Unsicherheit wird fälschlich in Harmlosigkeit umgedeutet.":"La incertidumbre se reinterpreta erróneamente como benignidad.","IHC/ISH macht Missense-VUS pathogen":"La IHC/ISH convierte una VUS missense en patogénica","Unterschiedliche Biomarkerfragen werden vermischt.":"Se confunden preguntas distintas sobre biomarcadores.","Die Variante ist echt – und trotzdem kein Target":"La variante es real, y aun así no es una diana","Curation bestätigt die technische Echtheit, aber nicht die klinische Actionability. HER2-IHC/ISH liefern ebenfalls keinen unabhängigen etablierten HER2-Befund.":"La curación confirma la validez técnica, pero no la accionabilidad clínica. La IHC/ISH de HER2 tampoco aporta un hallazgo HER2 independiente establecido.","Der Twist ist kein Laborfehler, sondern die Trennung von Detektion und Bedeutung.":"El giro no es un error de laboratorio, sino la separación entre detección y significado.","VUS sauber begrenzt":"VUS correctamente delimitada","Technisch echt, klinisch unklar, kein Overcalling.":"Técnicamente real, clínicamente incierta, sin sobreinterpretación.","Evidenzgerechte MTB-Kommunikation.":"Comunicación del MTB basada en la evidencia.","Direkt HER2-Therapie":"Terapia HER2 directa","VUS wird wie ein etablierter Biomarker behandelt.":"La VUS se trata como un biomarcador establecido.","Kritischer Interpretationsfehler.":"Error crítico de interpretación.","VUS verschwiegen":"VUS omitida","Unsicherheit wird nicht transparent kommuniziert.":"La incertidumbre no se comunica de forma transparente.","Besser klar benennen und begrenzen.":"Es mejor nombrarla y delimitarla claramente.","VUS ohne ausreichende prädiktive Evidenz":"VUS sin evidencia predictiva suficiente","nicht als gesichertes Target formulieren":"no describirla como diana establecida","ggf. Re-Evaluation bei neuer Evidenz.":"considerar una reevaluación si aparece nueva evidencia.","VUS ist eine Evidenzkategorie.":"VUS es una categoría de evidencia.","Softwareannotation ersetzt keine fachliche Varianteninterpretation.":"La anotación del software no sustituye la interpretación profesional de variantes.","Ein Gen kann mehrere völlig unterschiedliche Biomarkerarten tragen.":"Un gen puede albergar varios tipos de biomarcadores completamente distintos.","ERBB2-VUS technisch bestätigt, jedoch ohne ausreichende klinisch-prädiktive Evidenz; HER2 IHC/ISH ohne unabhängigen positiven Biomarker. Keine etablierte Therapieableitung allein aus der VUS.":"VUS de ERBB2 confirmada técnicamente, pero sin evidencia clínica predictiva suficiente; IHC/ISH de HER2 sin biomarcador positivo independiente. No existe una implicación terapéutica establecida basada solo en la VUS.","Evidenzhierarchie":"Jerarquía de evidencia","Variantenspezifität":"Especificidad de la variante","MTB-Kommunikation":"Comunicación MTB","Wann darf eine VUS reklassifiziert werden?":"¿Cuándo puede reclasificarse una VUS?","Wie häufig sollte Re-Annotation erfolgen?":"¿Con qué frecuencia debería realizarse una reanotación?","Wie verhindert man Software-bedingtes Overcalling?":"¿Cómo puede evitarse la sobreinterpretación inducida por el software?","Twist: technisch echt ≠ klinisch actionable":"Giro: técnicamente real ≠ clínicamente accionable","HER2-IHC/ISH und Sequenz-VUS getrennt":"IHC/ISH de HER2 y VUS de secuencia evaluadas por separado","Referenzpfad: Call → Klassifikation → Evidenz → klinische Aussage":"Ruta de referencia: call → clasificación → evidencia → conclusión clínica","ALK/ROS1/RET/NTRK-Fusionsverdacht bei jungem Nie-Raucher → FISH, RNA-NGS oder DNA-NGS?":"Sospecha de fusión ALK/ROS1/RET/NTRK en una paciente joven no fumadora → ¿FISH, NGS de ARN o NGS de ADN?","ALK/ROS1/RET/NTRK-Fusionsverdacht …":"Sospecha de fusión ALK/ROS1/RET/NTRK …","Thoraxonkologie / Molekulares Tumorboard":"Oncología torácica / Comité Molecular de Tumores","42-jährige Patientin, Nie-Raucherin, metastasiertes pulmonales Adenokarzinom mit Leber- und Knochenmetastasen.":"Paciente de 42 años, no fumadora, con adenocarcinoma pulmonar metastásico con metástasis hepáticas y óseas.","Ein externes DNA-basiertes Panel meldet keinen therapierbaren Treiber. Ist die molekulare Abklärung damit abgeschlossen oder muss eine Fusionsdiagnostik ergänzt werden?":"Un panel externo basado en ADN no identifica ningún driver accionable. ¿Está completa la evaluación molecular o debe añadirse un estudio de fusiones?","Die Erstlinientherapie soll im MTB in fünf Tagen festgelegt werden.":"El tratamiento de primera línea se definirá en el comité molecular dentro de cinco días.","Raucherstatus":"Tabaquismo","Nie-Raucherin, keine relevante berufliche Exposition.":"No fumadora, sin exposición ocupacional relevante.","Klinischer Verlauf":"Evolución clínica","ECOG 1, symptomatische ossäre Metastase, insgesamt aber klinisch stabil.":"ECOG 1, metástasis ósea sintomática, pero clínicamente estable en conjunto.","Vorbefund":"Resultado previo","Externes DNA-NGS ohne EGFR-, KRAS-, BRAF-, MET-Exon-14- oder ERBB2-Alteration; der Bericht enthält keine belastbare Aussage zur RNA-basierten Fusionserfassung.":"NGS de ADN externo sin alteraciones en EGFR, KRAS, BRAF, MET exón 14 ni ERBB2; el informe no aporta una conclusión sólida sobre la detección de fusiones basada en ARN.","Entscheidungsdruck":"Presión para decidir","Die Onkologie erwägt bereits eine nicht zielgerichtete Systemtherapie, falls kein Treiber gefunden wird.":"Oncología ya contempla una terapia sistémica no dirigida si no se identifica ningún driver.","HE":"H&E","Mäßig differenziertes pulmonales Adenokarzinom in einer Lebermetastasenbiopsie.":"Adenocarcinoma pulmonar moderadamente diferenciado en biopsia de metástasis hepática.","IHC":"IHC","TTF-1 und Napsin A positiv; p40 negativ. Die Morphologie und der klinische Kontext stützen einen pulmonalen Primarius.":"TTF-1 y Napsina A positivos; p40 negativo. La morfología y el contexto clínico apoyan un primario pulmonar.","Biologischer Hinweis":"Indicio biológico","Junges Alter und Nie-Raucherstatus erhöhen die Aufmerksamkeit für eine onkogene Treiberalteration, ersetzen aber keinen methodisch vollständigen Nachweis.":"La edad joven y la ausencia de tabaquismo aumentan la sospecha de una alteración driver oncogénica, pero no sustituyen un estudio metodológicamente completo.","Offene Frage":"Pregunta abierta","Wurden ALK-, ROS1-, RET- und NTRK-Fusionen mit einer dafür geeigneten Methode tatsächlich ausreichend ausgeschlossen?":"¿Se excluyeron realmente las fusiones ALK, ROS1, RET y NTRK con un método adecuado?","FFPE-Leberbiopsie, Block M2.":"Biopsia hepática FFPE, bloque M2.","ca. 35–40 %, nach Markierung gut geeignet.":"aprox. 35–40 %, bien adecuado tras el marcado.","RNA-Prognose":"Previsión del ARN","RNA-Qualität nach Vorprüfung grenzwertig bis ausreichend; noch genügend Material für einen gezielten RNA-Ansatz.":"La calidad del ARN es limítrofe a suficiente tras la evaluación preliminar; queda material suficiente para un enfoque dirigido de ARN.","Schnittbudget":"Presupuesto de cortes","8 ungefärbte Schnitte verfügbar.":"Disponibles 8 cortes sin teñir.","Materialfalle":"Trampa de material","Ein wiederholtes DNA-only-Panel verbraucht Material und kann die eigentliche Fusionsfrage trotzdem offenlassen.":"Repetir un panel solo de ADN consume material y puede seguir dejando sin resolver la verdadera cuestión de las fusiones.","Breite Fusionsdiagnostik":"Estudio amplio de fusiones","DNA-NGS":"NGS de ADN","Kein relevanter SNV/Indel-Treiber nachweisbar. Die konkrete Assay-Konfiguration erlaubt keinen belastbaren Ausschluss aller klinisch relevanten Fusionen.":"No se detecta ningún driver SNV/indel relevante. La configuración concreta del ensayo no permite excluir de forma fiable todas las fusiones clínicamente relevantes.","RNA-Fusionsdiagnostik":"Estudio de fusiones por ARN","KIF5B::RET-Fusion nachweisbar; in-frame und exprimiert. Der Befund erklärt den bisher DNA-negativen Treiberstatus.":"Se detecta una fusión KIF5B::RET, in-frame y expresada. El hallazgo explica el estado previamente negativo para drivers en ADN.","FISH":"FISH","Bei gezielter RET-FISH zeigt sich ein Rearrangement. Die Methode bestätigt die Umlagerung, liefert aber nicht die Breite einer parallelen RNA-Fusionsanalyse.":"La FISH dirigida a RET muestra un reordenamiento. El método confirma el reordenamiento, pero no ofrece la amplitud de un análisis paralelo de fusiones por ARN.","QC":"QC","Tumorzellanteil ausreichend. RNA ist knapp, aber nach QC verwertbar; Material Stewardship bleibt relevant.":"Fracción tumoral suficiente. El ARN es escaso, pero utilizable tras el QC; la gestión responsable del material sigue siendo relevante.","Die RNA-basierte Fusionsdiagnostik weist eine therapeutisch relevante KIF5B::RET-Fusion nach. Der zuvor negative DNA-Befund war kein belastbarer Ausschluss einer onkogenen Fusion.":"El estudio de fusiones basado en ARN detecta una fusión KIF5B::RET terapéuticamente relevante. El resultado previo negativo en ADN no constituía una exclusión fiable de una fusión oncogénica.","Teilbefund: Eine gezielte Einzelmethode oder DNA-only-Strategie kann die breite Fusionsfrage nicht vollständig beantworten. Eine RNA-basierte Fusionsdiagnostik sollte ergänzt werden.":"Resultado parcial: un único método dirigido o una estrategia solo de ADN no puede responder por completo a la cuestión amplia de las fusiones. Debe añadirse un estudio de fusiones basado en ARN.","Die RET-Fusion als therapieentscheidenden Treiber benennen":"Identificar la fusión RET como driver determinante para el tratamiento","DNA-only nicht mit umfassend treibernegativ gleichsetzen":"no equiparar una estrategia solo de ADN con un resultado globalmente negativo para drivers","FISH als gezielte Bestätigungs-/Alternativmethode, nicht als universellen Ersatz einer breiten RNA-Analyse einordnen":"considerar FISH como método dirigido confirmatorio/alternativo, no como sustituto universal de un análisis amplio de ARN","Assay- und RNA-QC-Limitationen transparent kommunizieren":"comunicar de forma transparente las limitaciones del ensayo y del QC de ARN","Optimale Lösung: vorhandenen DNA-Befund methodisch prüfen und die offene Fusionsfrage mit einer breiten RNA-basierten Analyse schließen; gezielte FISH kann bei konkreter Hypothese ergänzen.":"Solución óptima: revisar metodológicamente el resultado de ADN existente y cerrar la cuestión abierta de las fusiones con un análisis amplio basado en ARN; puede añadirse FISH dirigida ante una hipótesis concreta.","NSCLC":"NSCLC","NGS":"NGS","RNA":"ARN","MVP":"MVP","Standard":"Estándar","Junge Nie-Raucherin mit DNA-negativem NSCLC: Ist der Tumor wirklich treibernegativ?":"Paciente joven no fumadora con NSCLC negativo en ADN: ¿es realmente un tumor sin driver?","Molekularpathologie / Thoraxonkologie / MTB":"Patología molecular / Oncología torácica / MTB","Einen negativen DNA-NGS-Befund nur innerhalb der tatsächlich validierten Assaygrenzen interpretieren.":"Interpretar un resultado NGS de ADN negativo únicamente dentro de los límites del ensayo realmente validados.","RNA-basierte Fusionsdiagnostik bei klinisch plausibler Fusionsfrage gegenüber serieller FISH und erneutem DNA-only-Test priorisieren.":"Priorizar el estudio de fusiones basado en ARN frente a FISH seriadas y a repetir un test solo de ADN cuando exista una sospecha clínica plausible de fusión.","FISH als gezielte orthogonale Methode sinnvoll einordnen, ohne sie mit einer breiten parallelen Fusionssuche gleichzusetzen.":"Situar correctamente la FISH como método ortogonal dirigido, sin equipararla a un cribado amplio y paralelo de fusiones.","Einen methodisch unvollständigen 'kein Treiber'-Befund im MTB aktiv korrigieren.":"Corregir activamente en el MTB un resultado «sin driver» metodológicamente incompleto.","Mittwochmorgen vor dem Thorax-MTB. Auf dem Bildschirm steht bei einer 42-jährigen Nie-Raucherin mit metastasiertem Lungenadenokarzinom bereits der externe Satz: 'Kein therapeutisch relevanter Treiber nachweisbar.' Die Onkologie plant deshalb eine nicht zielgerichtete Systemtherapie. Beim Lesen des Methodenteils fällt jedoch auf: Untersucht wurde ein DNA-only-Panel; eine belastbare RNA-basierte Fusionsdiagnostik ist nicht dokumentiert. Aus einem scheinbar abgeschlossenen Befund wird wieder eine offene Therapiefrage.":"Miércoles por la mañana antes del MTB torácico. En la pantalla, el informe externo de una paciente de 42 años, no fumadora, con adenocarcinoma pulmonar metastásico ya dice: «No se detecta ningún driver terapéuticamente relevante». Por ello, oncología está planificando una terapia sistémica no dirigida. Sin embargo, al leer la metodología se observa que solo se realizó un panel de ADN; no se documenta un estudio robusto de fusiones basado en ARN. Un resultado aparentemente cerrado vuelve a convertirse en una pregunta terapéutica abierta.","42-jährige Nie-Raucherin, ECOG 1, pulmonales Adenokarzinom mit Leber- und Knochenmetastasen. Externes DNA-NGS ohne relevante SNV/Indel-Treiber. Für das MTB muss entschieden werden, ob dieser Befund als treibernegativ akzeptiert werden kann oder ob die offene ALK/ROS1/RET/NTRK-Fusionsfrage mit einer geeigneten Methode geschlossen werden muss.":"Paciente de 42 años, no fumadora, ECOG 1, con adenocarcinoma pulmonar y metástasis hepáticas y óseas. El NGS de ADN externo no muestra ningún driver SNV/indel relevante. El MTB debe decidir si puede aceptarse como negativo para drivers o si debe cerrarse la cuestión abierta de fusiones ALK/ROS1/RET/NTRK con un método adecuado.","Klinischer Kontext":"Contexto clínico","Junges Alter, Nie-Raucherstatus und Adenokarzinom machen eine onkogene Treiberalteration plausibel, beweisen sie aber nicht.":"La edad joven, la ausencia de tabaquismo y el adenocarcinoma hacen plausible una alteración driver oncogénica, pero no la demuestran.","Klinische Plausibilität steuert die Aufmerksamkeit; die Diagnose entsteht aus Methodik und Befund.":"La plausibilidad clínica dirige la atención; el diagnóstico se establece mediante la metodología y el resultado.","Externer Befund":"Resultado externo","DNA-NGS: EGFR, KRAS, BRAF, MET-Exon-14 und ERBB2 ohne relevante Alteration. Der Methodenteil beschreibt keine validierte breite RNA-Fusionsanalyse.":"NGS de ADN: EGFR, KRAS, BRAF, MET exón 14 y ERBB2 sin alteraciones relevantes. La sección de métodos no describe ningún análisis amplio validado de fusiones por ARN.","'Negativ' ist nur so breit wie der verwendete Assay.":"«Negativo» solo es tan amplio como el ensayo utilizado.","Leberbiopsie mit 35–40 % Tumor, acht ungefärbte Schnitte. RNA-QC ist grenzwertig bis ausreichend.":"Biopsia hepática con 35–40 % de tumor, ocho cortes sin teñir. El QC de ARN es limítrofe a suficiente.","Jetzt ist eine gezielte, informationsreiche Ergänzung sinnvoller als serielle Einzeltests.":"Ahora es más útil una prueba adicional dirigida y rica en información que una serie de pruebas individuales.","MTB-Druck":"Presión temporal del MTB","Therapieentscheidung in fünf Tagen; jeder unnötige Zusatzlauf kostet Zeit und Material.":"Decisión terapéutica en cinco días; cada corrida adicional innecesaria consume tiempo y material.","TAT und Material Stewardship gehören zur klinischen Methodenauswahl.":"El TAT y la gestión responsable del material forman parte de la selección clínica del método.","HE/IHC":"H&E/IHC","Metastase eines TTF-1-/Napsin-A-positiven pulmonalen Adenokarzinoms.":"Metástasis de un adenocarcinoma pulmonar TTF-1/Napsina A positivo.","DNA-NGS extern":"NGS de ADN externo","Kein relevanter SNV/Indel-Treiber; Fusionsabdeckung nicht ausreichend dokumentiert.":"Sin driver SNV/indel relevante; la cobertura de fusiones no está documentada adecuadamente.","RNA-QC":"QC de ARN","RNA ist nicht perfekt, aber für einen zielgerichteten Fusionsassay noch verwertbar.":"El ARN no es perfecto, pero sigue siendo utilizable para un ensayo dirigido de fusiones.","Nur acht ungefärbte Schnitte verbleiben.":"Solo quedan ocho cortes sin teñir.","TAT-Ziel fünf Tage bis MTB.":"Objetivo de TAT: cinco días hasta el MTB.","Eine breite serielle FISH-Strategie würde mehrere Einzelansätze und Vorannahmen benötigen.":"Una estrategia amplia de FISH seriadas requeriría múltiples pruebas individuales y supuestos previos.","Ein erneutes DNA-only-Panel kann denselben methodischen blinden Fleck reproduzieren.":"Repetir un panel solo de ADN puede reproducir el mismo punto ciego metodológico.","Was bedeutet der externe Satz 'kein therapeutisch relevanter Treiber nachweisbar' in diesem Fall?":"¿Qué significa en este caso la afirmación externa «no se detecta ningún driver terapéuticamente relevante»?","Alle relevanten Treiber einschließlich Fusionen sind sicher ausgeschlossen.":"Se han excluido con seguridad todos los drivers relevantes, incluidas las fusiones.","Er gilt nur innerhalb der validierten DNA-Assaygrenzen; die Fusionsfrage bleibt offen.":"Solo es válido dentro de los límites validados del ensayo de ADN; la cuestión de las fusiones sigue abierta.","Bei Nie-Rauchern ist ein negativer Befund grundsätzlich falsch.":"En no fumadores, un resultado negativo siempre es falso.","Er bedeutet automatisch, dass jetzt jede Fusion einzeln per FISH getestet werden muss.":"Significa automáticamente que ahora hay que estudiar cada fusión individualmente por FISH.","Ein negativer molekularer Befund ist immer an die analytische Abdeckung der verwendeten Methode gebunden.":"Un resultado molecular negativo siempre está ligado a la cobertura analítica del método utilizado.","Welche Ergänzung beantwortet die offene breite Fusionsfrage am effizientesten?":"¿Qué prueba adicional responde de forma más eficiente a la cuestión abierta y amplia de las fusiones?","Breites RNA-basiertes Fusionspanel":"Panel amplio de fusiones basado en ARN","Dasselbe DNA-only-Panel noch einmal":"El mismo panel solo de ADN otra vez","Eine einzelne ALK-FISH als vollständiger Ersatz":"Una sola FISH de ALK como sustituto completo","Keine Ergänzung, weil die Histologie bereits eindeutig ist":"Ninguna prueba adicional porque la histología ya es inequívoca","RNA-NGS kann mehrere exprimierte Fusionsereignisse parallel erfassen und ist für diese offene Fragestellung besonders geeignet.":"El NGS de ARN puede detectar en paralelo múltiples eventos de fusión expresados y es especialmente adecuado para esta pregunta abierta.","Wann bleibt FISH in diesem Fall sinnvoll?":"¿Cuándo sigue siendo útil la FISH en este caso?","Bei konkreter Genhypothese als schnelle/orthogonale Bestätigung":"Ante una hipótesis génica concreta, como confirmación rápida/ortogonal","Wenn RNA nicht verwertbar ist und ein gezielter Rearrangement-Nachweis benötigt wird":"Cuando el ARN no es utilizable y se requiere una detección dirigida de reordenamiento","Als universell umfassender Ersatz für eine breite RNA-Fusionsanalyse":"Como sustituto universal y exhaustivo de un análisis amplio de fusiones por ARN","Zur sicheren Bestimmung jedes Fusionspartners":"Para determinar con seguridad cada pareja de fusión","FISH ist für gezielte Rearrangement-Fragen nützlich, aber meist weniger breit und partnerinformativ als RNA-basierte Verfahren.":"La FISH es útil para preguntas dirigidas sobre reordenamientos, pero suele ser menos amplia y menos informativa sobre la pareja que los métodos basados en ARN.","Entscheiden Sie, ob der externe DNA-negative Befund als vollständig akzeptiert werden kann und welche Ergänzung jetzt mit dem verbliebenen Material die größte klinische Information liefert.":"Decida si el resultado externo negativo en ADN puede aceptarse como completo y qué prueba adicional aporta ahora la mayor información clínica con el material restante.","Methodenteil des externen DNA-Befunds prüfen und die unzureichend geklärte Fusionsabdeckung benennen.":"Revisar la sección de métodos del resultado de ADN externo e identificar la cobertura de fusiones insuficientemente resuelta.","RNA-basiertes Fusionspanel priorisieren.":"Priorizar un panel de fusiones basado en ARN.","Material aus dem markierten Tumorareal gezielt für RNA aufarbeiten.":"Procesar específicamente para ARN el material de la zona tumoral marcada.","FISH nur bei konkreter Hypothese oder nicht verwertbarer RNA als gezielte Alternative/Bestätigung einsetzen.":"Utilizar FISH solo como alternativa/confirmación dirigida ante una hipótesis concreta o un ARN no utilizable.","Im MTB bis zum Abschluss der Fusionsdiagnostik nicht 'treibernegativ' formulieren.":"No describir el caso como «negativo para drivers» en el MTB hasta completar el estudio de fusiones.","Validiertes kombiniertes DNA/RNA-Pan-Panel, wenn es die relevante Fusionsbreite sicher abdeckt und Material/TAT vertretbar sind.":"Un pan-panel combinado ADN/ARN validado si cubre de forma fiable el espectro relevante de fusiones y el material/TAT son aceptables.","Gezielte RET-FISH, wenn RNA technisch scheitert und die konkrete Hypothese bereits fokussiert ist.":"FISH dirigida a RET si el ARN falla técnicamente y la hipótesis concreta ya está focalizada.","DNA-negativ = vollständig negativ":"ADN negativo = completamente negativo","Die Aussage überschreitet die analytische Reichweite des verwendeten Assays.":"La afirmación excede el alcance analítico del ensayo utilizado.","Serielle FISH für jede denkbare Fusion":"FISH seriadas para cada fusión imaginable","Material- und zeitintensiv; benötigt Vorannahmen und ist weniger parallelisierbar.":"Consume material y tiempo; requiere supuestos previos y es menos paralelizable.","Noch einmal dasselbe DNA-only-Panel":"Repetir el mismo panel solo de ADN","Wiederholung behebt keinen systematischen Assay-Blindspot.":"Repetir no corrige un punto ciego sistemático del ensayo.","Der 'treibernegative' Tumor ist nicht treibernegativ":"El tumor «negativo para drivers» no es negativo para drivers","Das RNA-Fusionspanel detektiert eine exprimierte KIF5B::RET-Fusion. Eine anschließende gezielte RET-FISH bestätigt ein Rearrangement. Der zunächst geplante nicht zielgerichtete Therapieweg muss im MTB neu bewertet werden.":"El panel de fusiones de ARN detecta una fusión KIF5B::RET expresada. Una FISH dirigida a RET posterior confirma un reordenamiento. La estrategia terapéutica no dirigida inicialmente planificada debe reevaluarse en el MTB.","Der Fehler lag nicht in der Qualität des ersten DNA-Laufs, sondern in der zu breiten Interpretation eines methodisch begrenzten Negativbefunds.":"El error no estuvo en la calidad de la primera corrida de ADN, sino en la interpretación demasiado amplia de un resultado negativo metodológicamente limitado.","RNA schließt die offene Lücke":"El ARN cierra la brecha abierta","KIF5B::RET-Fusion nachweisbar; DNA-SNV/Indel-Profil ohne weiteren relevanten Treiber.":"Se detecta fusión KIF5B::RET; perfil SNV/indel en ADN sin otro driver relevante.","Sehr gut: Assaygrenze erkannt, passende Methode ergänzt, klinisch entscheidenden Treiber gefunden.":"Excelente: se reconoció la limitación del ensayo, se añadió el método adecuado y se encontró un driver clínicamente decisivo.","DNA-only bleibt Endpunkt":"Solo ADN se mantiene como punto final","Kein SNV/Indel-Treiber; Fusionsstatus bleibt methodisch unzureichend geklärt.":"Sin driver SNV/indel; el estado de fusiones sigue metodológicamente insuficientemente resuelto.","Der Befund klingt abgeschlossen, ist es aber nicht.":"El informe parece cerrado, pero no lo está.","Einzel-FISH":"FISH de un solo gen","Eine gezielte Einzel-FISH kann ein bestimmtes Rearrangement beantworten, lässt andere Fusionsklassen offen.":"Una FISH dirigida individual puede responder una cuestión concreta de reordenamiento, pero deja abiertas otras clases de fusiones.","Bei fokussierter Hypothese sinnvoll, als breite Erststrategie unvollständig.":"Útil ante una hipótesis focalizada, incompleta como estrategia inicial amplia.","RNA ausreichend":"ARN suficiente","Breites RNA-Fusionspanel durchführen.":"Realizar un panel amplio de fusiones por ARN.","Direkter Nachweis KIF5B::RET und vollständige MTB-Einordnung.":"Detección directa de KIF5B::RET e interpretación completa en el MTB.","RNA nicht verwertbar":"ARN no utilizable","Gezielte FISH/alternatives validiertes Material erwägen.":"Considerar FISH dirigida/material alternativo validado.","Fragestellung wird fokussiert weiterverfolgt statt vorschnell geschlossen.":"La cuestión se sigue de forma focalizada en lugar de cerrarla prematuramente.","Nur DNA ausgewählt":"Seleccionado solo ADN","Fusionsdiagnostik nachfordern.":"Solicitar estudio de fusiones.","Fall ist rettbar, aber TAT und Score verschlechtern sich.":"El caso puede rescatarse, pero empeoran el TAT y la puntuación.","Ein negativer Befund ist kein universeller biologischer Zustand, sondern ein methodisch begrenztes Messergebnis.":"Un resultado negativo no es un estado biológico universal, sino un resultado de medición limitado por el método.","RNA-basierte Verfahren sind bei vielen Fusionsfragen besonders wertvoll.":"Los métodos basados en ARN son especialmente valiosos para muchas cuestiones de fusiones.","FISH bleibt relevant, wenn die Frage gezielt ist oder RNA scheitert.":"La FISH sigue siendo relevante cuando la pregunta es dirigida o cuando falla el ARN.","Das Wort 'treibernegativ' sollte nur verwendet werden, wenn die relevanten Alterationsklassen tatsächlich adäquat untersucht wurden.":"El término «negativo para drivers» solo debería utilizarse cuando las clases de alteraciones relevantes se hayan estudiado realmente de forma adecuada.","Der externe DNA-Befund darf nicht als vollständiger Treiberausschluss übernommen werden. Die offene Fusionsfrage wird mit einem breiten RNA-basierten Fusionspanel geschlossen. Ergebnis: KIF5B::RET-Fusion. FISH kann gezielt bestätigen oder bei nicht verwertbarer RNA aushelfen.":"El resultado externo de ADN no debe asumirse como exclusión completa de drivers. La cuestión abierta de las fusiones se cierra con un panel amplio basado en ARN. Resultado: fusión KIF5B::RET. La FISH puede confirmar de forma dirigida o utilizarse como alternativa si el ARN no es utilizable.","Assaygrenze erkannt":"Limitación del ensayo reconocida","RNA-Fusionsdiagnostik priorisiert":"Estudio de fusiones por ARN priorizado","FISH korrekt eingeordnet":"FISH correctamente situada","Kein Overclaim eines negativen DNA-Befunds":"Sin sobreinterpretar un resultado de ADN negativo","Wann ist DNA-NGS für Fusionen ausreichend?":"¿Cuándo es suficiente el NGS de ADN para fusiones?","Welche Informationen liefert RNA zusätzlich zur strukturellen Umlagerung?":"¿Qué información aporta el ARN además del reordenamiento estructural?","Wie sollte ein pathologischer Negativbefund formuliert sein, wenn eine relevante Alterationsklasse nicht sicher abgedeckt ist?":"¿Cómo debe redactarse un resultado anatomopatológico negativo cuando una clase relevante de alteraciones no está cubierta de forma fiable?","DE master reviewed structure":"Estructura maestra DE revisada","KIF5B::RET trotz DNA-negativem Vorbericht":"KIF5B::RET pese al informe previo negativo en ADN","Negativbefunde sind assaygebunden":"Los resultados negativos dependen del ensayo","DNA-negativ → Methodencheck → RNA → Fusion":"ADN negativo → revisión del método → ARN → fusión","KRAS-mutiertes NSCLC mit STK11/KEAP1-Kontext → Target, Prognose, Immuntherapie-Kontext korrekt gewichten":"NSCLC con mutación KRAS y contexto STK11/KEAP1 → ponderar correctamente diana, pronóstico y contexto de inmunoterapia","KRAS-mutiertes NSCLC mit STK11/KEA…":"NSCLC con mutación KRAS y STK11/KEA…","Thoraxonkologie / MTB":"Oncología torácica / MTB","66-jähriger Patient mit metastasiertem Lungenadenokarzinom. Das DNA-Panel zeigt KRAS p.G12C sowie pathogene STK11- und KEAP1-Alterationen.":"Paciente de 66 años con adenocarcinoma pulmonar metastásico. El panel de ADN muestra KRAS p.G12C junto con alteraciones patogénicas de STK11 y KEAP1.","Bedeutet die Ko-Mutationskonstellation, dass Immuntherapie nicht sinnvoll ist? Welche Information ist tatsächlich therapeutisch, welche prognostisch und welche nur biologischer Kontext?":"¿Implica el patrón de comutaciones que la inmunoterapia no es útil? ¿Qué información es realmente terapéutica, cuál pronóstica y cuál solo contexto biológico?","Therapieentscheidung im MTB innerhalb einer Woche.":"Decisión terapéutica en el MTB dentro de una semana.","35 pack years, vor sechs Jahren aufgehört.":"35 paquetes-año, dejó de fumar hace seis años.","Stadium":"Estadio","Leber-, Nebennieren- und ossäre Metastasen; ECOG 1.":"Metástasis hepáticas, suprarrenales y óseas; ECOG 1.","Vorbehandlung":"Tratamiento previo","Keine systemische Therapie im metastasierten Stadium.":"Sin tratamiento sistémico en el contexto metastásico.","Klinische Falle":"Trampa clínica","Im Vorbericht wurde STK11/KEAP1 bereits als 'Immuntherapie-Resistenzmarker' bezeichnet. Das Tumorboard möchte wissen, ob daraus ein Therapieausschluss folgt.":"El informe preliminar ya ha etiquetado STK11/KEAP1 como «marcadores de resistencia a la inmunoterapia». El comité quiere saber si de ello se deriva una exclusión terapéutica.","Pulmonales Adenokarzinom mit soliden und azinären Anteilen.":"Adenocarcinoma pulmonar con componentes sólidos y acinares.","TTF-1 positiv, p40 negativ.":"TTF-1 positivo, p40 negativo.","PD-L1":"PD-L1","Noch ausstehend.":"Pendiente.","Molekular":"Molecular","KRAS p.G12C, STK11 loss-of-function und KEAP1 loss-of-function; keine klassische EGFR-/ALK-/ROS1-Treiberkonstellation.":"KRAS p.G12C, STK11 loss-of-function y KEAP1 loss-of-function; sin constelación clásica de drivers EGFR/ALK/ROS1.","Wie werden KRAS-Targetierbarkeit, adverse Ko-Mutationen und Immuntherapie-Kontext getrennt und zusammengeführt?":"¿Cómo deben separarse e integrarse la posibilidad de dirigir KRAS, las comutaciones adversas y el contexto de inmunoterapia?","FFPE-Lungenbiopsie mit ca. 45 % Tumoranteil.":"Biopsia pulmonar FFPE con aprox. 45 % de fracción tumoral.","DNA-QC":"QC de ADN","ausreichend, Panel vollständig auswertbar.":"suficiente, panel completamente evaluable.","9 ungefärbte Schnitte verfügbar.":"Disponibles 9 cortes sin teñir.","Zusätzliche explorative Biomarker dürfen nicht den Eindruck erzeugen, es gebe einen validierten Einzeltest, der die Immuntherapieentscheidung sicher vorhersagt.":"Los biomarcadores exploratorios adicionales no deben crear la impresión de que existe una única prueba validada que prediga con seguridad la decisión de inmunoterapia.","KRAS/STK11/KEAP1-Kontext":"Contexto KRAS/STK11/KEAP1","PD-L1-Kontext":"Contexto PD-L1","KRAS/STK11/KEAP1":"KRAS/STK11/KEAP1","KRAS p.G12C sowie pathogene STK11- und KEAP1-loss-of-function-Alterationen. Die Ko-Mutationen markieren eine biologisch ungünstige Subgruppe, sind aber kein eigenständiger binärer Ausschlusstest für Immuntherapie.":"KRAS p.G12C junto con alteraciones patogénicas loss-of-function de STK11 y KEAP1. Las comutaciones marcan un subgrupo biológicamente desfavorable, pero no constituyen una prueba binaria independiente para excluir inmunoterapia.","PD-L1 TPS 70 %. Hohe Expression ist klinisch relevant, muss aber zusammen mit klinischem Kontext und Ko-Mutationen interpretiert werden.":"PD-L1 TPS 70 %. La expresión alta es clínicamente relevante, pero debe interpretarse junto con el contexto clínico y las comutaciones.","TMB":"TMB","TMB im intermediären Bereich. Kein Befund, der die komplexe Ko-Mutationskonstellation alleine auflöst.":"TMB en rango intermedio. Ningún hallazgo resuelve por sí solo la compleja constelación de comutaciones.","Immun-Kontext-IHC":"IHC de contexto inmunitario","Relativ geringes CD8-positives Infiltrat. Biologisch interessant, aber kein validierter alleiniger Therapieausschlussmarker.":"Infiltrado CD8 positivo relativamente escaso. Biológicamente interesante, pero no es un marcador independiente validado de exclusión terapéutica.","DNA-QC und Tumoranteil ausreichend; PD-L1 technisch auswertbar.":"QC de ADN y fracción tumoral suficientes; PD-L1 técnicamente evaluable.","KRAS p.G12C ist ein potenziell therapeutisch relevanter Genotyp im passenden Behandlungskontext. STK11/KEAP1 sind wichtige adverse biologische/prognostische Ko-Alterationen, dürfen aber nicht als binärer 'kein ICI'-Marker überinterpretiert werden. PD-L1 TPS 70 % bleibt eine eigenständige klinisch relevante Information.":"KRAS p.G12C es un genotipo potencialmente relevante desde el punto de vista terapéutico en el contexto de tratamiento adecuado. STK11/KEAP1 son coalteraciones biológicas/pronósticas adversas importantes, pero no deben sobreinterpretarse como marcadores binarios de «no ICI». PD-L1 TPS 70 % sigue siendo una información clínica relevante independiente.","Teilbefund: KRAS/Ko-Mutationen oder PD-L1 fehlen. Ohne beide Ebenen ist eine ausgewogene MTB-Einordnung nicht möglich.":"Resultado parcial: faltan KRAS/comutaciones o PD-L1. Sin ambos niveles no es posible una interpretación equilibrada en el MTB.","KRAS p.G12C als Genotyp mit möglicher Target-Relevanz im passenden Therapiekontext benennen":"Identificar KRAS p.G12C como genotipo con posible relevancia como diana en el contexto terapéutico adecuado","STK11/KEAP1 als adverse Kontextmarker, nicht als absoluten ICI-Ausschluss darstellen":"Describir STK11/KEAP1 como marcadores de contexto adverso, no como exclusiones absolutas de ICI","PD-L1 separat und nicht durch Ko-Mutationen 'weginterpretieren'":"Informar PD-L1 por separado y no «anularlo» por la presencia de comutaciones","Prognostische Assoziation und prädiktive Therapieentscheidung sprachlich trennen":"Separar en la redacción la asociación pronóstica de la decisión terapéutica predictiva","Optimale Lösung: KRAS, STK11/KEAP1 und PD-L1 auf getrennten Evidenzebenen berichten und im MTB integrieren; keine einzelne Ko-Mutation als absoluten Therapieausschluss verwenden.":"Solución óptima: informar KRAS, STK11/KEAP1 y PD-L1 en niveles de evidencia separados e integrarlos en el MTB; no utilizar ninguna comutación aislada como exclusión terapéutica absoluta.","Immunescape":"Escape inmunitario","Phase":"Fase","KRAS/STK11/KEAP1-NSCLC: Kontextmarker sind kein Therapie-Ausschalter":"NSCLC KRAS/STK11/KEAP1: los marcadores de contexto no son interruptores terapéuticos","KRAS-Targetierbarkeit, STK11/KEAP1-Kontext und PD-L1 auf getrennten Evidenzebenen einordnen.":"Situar la posibilidad de dirigir KRAS, el contexto STK11/KEAP1 y PD-L1 en niveles de evidencia separados.","Prognostische bzw. assoziierte Resistenzsignale nicht als validierten binären prädiktiven Ausschlusstest formulieren.":"No formular señales pronósticas o asociadas a resistencia como una prueba predictiva binaria validada de exclusión.","Widersprüchliche Biomarkerinformationen in einer balancierten MTB-Aussage integrieren.":"Integrar la información biomarcadora contradictoria en una conclusión equilibrada del MTB.","Explorative TME-Marker von klinisch etablierten Routineentscheidungen trennen.":"Separar los marcadores exploratorios del TME de las decisiones rutinarias clínicamente establecidas.","Im Thorax-MTB liegt ein Befund mit drei fett markierten Genen: KRAS, STK11 und KEAP1. Der Vorbericht bezeichnet die beiden Ko-Mutationen bereits als 'Immuntherapie-Resistenzmarker'. Gleichzeitig ist PD-L1 noch nicht bestimmt. Die klinische Frage lautet nicht nur, was mutiert ist, sondern ob aus dieser biologisch ungünstigen Konstellation wirklich ein Therapieverbot abgeleitet werden darf.":"En el MTB torácico, el informe presenta tres genes en negrita: KRAS, STK11 y KEAP1. El informe preliminar ya denomina a las dos comutaciones «marcadores de resistencia a la inmunoterapia». Al mismo tiempo, PD-L1 aún no se ha determinado. La pregunta clínica no es solo qué está mutado, sino si esta constelación biológicamente desfavorable justifica realmente prohibir una terapia.","66-jähriger Patient, ehemaliger starker Raucher, metastasiertes Lungenadenokarzinom mit Leber-, Nebennieren- und Knochenmetastasen, ECOG 1. DNA-NGS zeigt KRAS p.G12C plus pathogene STK11- und KEAP1-Alterationen. Das MTB möchte Target-Relevanz, Prognose und Immuntherapie-Kontext sauber gewichten.":"Paciente de 66 años, exfumador intenso, con adenocarcinoma pulmonar metastásico en hígado, suprarrenales y hueso, ECOG 1. El NGS de ADN muestra KRAS p.G12C junto con alteraciones patogénicas de STK11 y KEAP1. El MTB quiere ponderar correctamente la relevancia como diana, el pronóstico y el contexto de inmunoterapia.","Genotyp":"Genotipo","KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.":"KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.","Nicht jede genetische Information erfüllt dieselbe klinische Funktion.":"No toda información genética cumple la misma función clínica.","Klinik":"Situación clínica","Hohe Tumorlast, aber aktuell stabil; keine vorangegangene systemische Therapie im metastasierten Stadium.":"Alta carga tumoral, pero actualmente estable; sin tratamiento sistémico previo en el contexto metastásico.","Therapieentscheidungen bleiben klinisch eingebettet.":"Las decisiones terapéuticas siguen integradas en el contexto clínico.","Vorbericht":"Informe preliminar","STK11/KEAP1 wurden als 'ICI-resistent' bezeichnet.":"STK11/KEAP1 se etiquetaron como «resistentes a ICI».","Assoziation mit ungünstigen Outcomes ist nicht dasselbe wie ein validierter absoluter Ausschlussmarker.":"La asociación con resultados desfavorables no equivale a un marcador absoluto de exclusión validado.","Offene Information":"Información pendiente","PD-L1 steht noch aus; zusätzliche TMB-/TIL-Daten könnten biologischen Kontext liefern, sind aber kein Ersatz für klinische Evidenz.":"PD-L1 sigue pendiente; datos adicionales de TMB/TIL pueden aportar contexto biológico, pero no sustituyen la evidencia clínica.","Mehr Biomarker bedeutet nicht automatisch eine klarere Therapieentscheidung.":"Más biomarcadores no producen automáticamente una decisión terapéutica más clara.","KRAS p.G12C; pathogene STK11- und KEAP1-loss-of-function-Alterationen.":"KRAS p.G12C; alteraciones patogénicas loss-of-function de STK11 y KEAP1.","TTF-1-positives pulmonales Adenokarzinom.":"Adenocarcinoma pulmonar TTF-1 positivo.","Noch nicht bestimmt.":"Aún no determinado.","Ausreichendes FFPE-Material; keine akute Materialknappheit.":"Material FFPE suficiente; sin escasez aguda de material.","Die eigentliche Grenze ist interpretativ: zusätzliche Marker dürfen nicht als stärker validiert erscheinen, als sie sind.":"La verdadera limitación es interpretativa: los marcadores adicionales no deben parecer más validados de lo que realmente están.","TMB/CD8-IHC können Kontext liefern, sind in diesem Fall aber nicht als zwingende Entscheidungsmarker definiert.":"TMB/IHC de CD8 pueden aportar contexto, pero no se definen como marcadores obligatorios de decisión en este caso.","Welche Aussagen sind fachlich angemessen?":"¿Qué afirmaciones son profesionalmente adecuadas?","KRAS p.G12C kann im geeigneten Therapiekontext targetrelevant sein.":"KRAS p.G12C puede ser relevante como diana en el contexto terapéutico adecuado.","STK11/KEAP1 kennzeichnen eine biologisch/prognostisch ungünstige Subgruppe.":"STK11/KEAP1 identifican un subgrupo biológica/pronósticamente desfavorable.","STK11 oder KEAP1 schließen Immuntherapie grundsätzlich aus.":"STK11 o KEAP1 excluyen de forma general la inmunoterapia.","PD-L1 bleibt eine eigenständige klinisch relevante Information.":"PD-L1 sigue siendo una información clínicamente relevante independiente.","Die Marker besitzen unterschiedliche Rollen; STK11/KEAP1 sind kein binärer ICI-Ausschluss.":"Los marcadores tienen funciones diferentes; STK11/KEAP1 no son exclusiones binarias de ICI.","PD-L1 ergibt später TPS 70 %. Wie ist der Befund zu integrieren?":"Posteriormente, PD-L1 resulta TPS 70 %. ¿Cómo debe integrarse?","Ignorieren, weil STK11/KEAP1 wichtiger sind.":"Ignorarlo porque STK11/KEAP1 son más importantes.","PD-L1 70 % garantiert eine sehr gute ICI-Antwort.":"PD-L1 70 % garantiza una respuesta excelente a ICI.","Als relevante positive Information berichten, aber zusammen mit klinischem Kontext und der adversen Ko-Mutationsbiologie interpretieren.":"Informarlo como dato positivo relevante, pero interpretarlo junto con el contexto clínico y la biología adversa de las comutaciones.","STK11/KEAP1 und PD-L1 heben sich gegenseitig auf; deshalb keine Aussage möglich.":"STK11/KEAP1 y PD-L1 se anulan entre sí; por tanto no puede hacerse ninguna conclusión.","Widersprüchliche Biomarker werden integriert, nicht gegeneinander 'verrechnet'.":"Los biomarcadores contradictorios se integran, no se «restan» entre sí.","Welche Rolle haben TMB oder CD8/TIL-IHC hier?":"¿Qué papel tienen aquí TMB o la IHC de CD8/TIL?","Optionaler biologischer Kontext; kein alleiniger validierter Therapieausschluss.":"Contexto biológico opcional; no una exclusión terapéutica independiente validada.","Zwingend erforderlich, bevor überhaupt eine Therapie diskutiert werden darf.":"Obligatorio antes incluso de poder discutir cualquier tratamiento.","Sie ersetzen PD-L1 vollständig.":"Sustituyen completamente a PD-L1.","Sie sind in der Tumorbiologie grundsätzlich bedeutungslos.":"Son fundamentalmente irrelevantes en la biología tumoral.","Die Zusatzmarker können das biologische Bild vertiefen, lösen die klinische Evidenzfrage aber nicht allein.":"Los marcadores adicionales pueden profundizar el contexto biológico, pero no resuelven por sí solos la cuestión de la evidencia clínica.","Formulieren Sie eine MTB-Empfehlung, die KRAS p.G12C, STK11/KEAP1 und PD-L1 korrekt gewichtet, ohne aus einer Ko-Mutation ein nicht validiertes Therapieverbot zu machen.":"Formule una recomendación del MTB que pondere correctamente KRAS p.G12C, STK11/KEAP1 y PD-L1 sin convertir una comutación en una prohibición terapéutica no validada.","KRAS p.G12C als eigenständigen Genotyp mit potenzieller Target-Relevanz im passenden Behandlungskontext benennen.":"Identificar KRAS p.G12C como genotipo independiente con posible relevancia como diana en el contexto terapéutico adecuado.","STK11/KEAP1 als adverse biologische/prognostische Ko-Alterationen beschreiben.":"Describir STK11/KEAP1 como coalteraciones biológicas/pronósticas adversas.","PD-L1 bestimmen und separat berichten.":"Determinar e informar PD-L1 por separado.","Aus STK11/KEAP1 keinen absoluten Immuntherapieausschluss ableiten.":"No derivar una exclusión absoluta de inmunoterapia a partir de STK11/KEAP1.","Optional erhobene TMB/TIL-Daten als Kontext, nicht als übergeordneten Entscheidungsmarker kennzeichnen.":"Etiquetar los datos TMB/TIL obtenidos opcionalmente como contexto, no como marcador decisional superior.","Breites DNA-Panel statt fokussierter KRAS/STK11/KEAP1-Analyse, wenn es bereits Bestandteil der vollständigen NSCLC-Profilierung ist.":"Panel amplio de ADN en lugar de un análisis focalizado KRAS/STK11/KEAP1 cuando ya forma parte del perfil completo del NSCLC.","TMB oder Immun-Kontext-IHC als zusätzliche Lehr-/Kontextinformation, solange daraus keine binäre Therapieentscheidung konstruiert wird.":"TMB o IHC de contexto inmunitario como información adicional docente/contextual, siempre que no se construya a partir de ello una decisión terapéutica binaria.","STK11/KEAP1 = kein ICI":"STK11/KEAP1 = no ICI","Aus einer adversen Assoziation wird fälschlich ein absoluter prädiktiver Ausschlussmarker.":"Una asociación adversa se convierte erróneamente en un marcador predictivo absoluto de exclusión.","PD-L1 hoch = sichere Antwort":"PD-L1 alto = respuesta garantizada","Auch ein etablierter Biomarker ist kein individuelles Response-Versprechen.":"Ni siquiera un biomarcador establecido garantiza una respuesta individual.","Jeden Kontextmarker erzwingen":"Forzar todos los marcadores contextuales","Mehr Messwerte erhöhen nicht automatisch die klinische Entscheidungsqualität.":"Más mediciones no mejoran automáticamente la calidad de la decisión clínica.","Der 'resistente' Tumor hat PD-L1 TPS 70 %":"El tumor «resistente» tiene PD-L1 TPS 70 %","Die nachgeforderte PD-L1-IHC zeigt eine hohe Expression von 70 %. Eine optionale Immun-Kontext-IHC zeigt gleichzeitig nur ein geringes CD8-Infiltrat. Statt einer eindeutigen Antwort entsteht ein scheinbarer Widerspruch: positive etablierte Information, adverse Ko-Mutationsbiologie und ein eher 'cold' wirkendes Mikromilieu.":"La IHC de PD-L1 solicitada muestra una expresión alta del 70 %. Una IHC opcional de contexto inmunitario muestra al mismo tiempo una infiltración CD8 escasa. En lugar de una respuesta clara surge una aparente contradicción: información establecida positiva, biología adversa de comutaciones y un microambiente más bien «frío».","Der Fall zwingt dazu, Biomarker nach Evidenzebene zu gewichten statt sie zu einem simplen Plus/Minus-Score zu verrechnen.":"El caso obliga a ponderar los biomarcadores según su nivel de evidencia en lugar de reducirlos a una simple puntuación de más/menos.","Evidenzebenen getrennt":"Niveles de evidencia separados","KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70 %. Ko-Mutationen werden als adverse Kontextmarker berichtet, nicht als absoluter ICI-Ausschluss.":"KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70 %. Las comutaciones se informan como marcadores contextuales adversos, no como criterios absolutos de exclusión de ICI.","Sehr gute, klinisch belastbare Integration.":"Integración muy buena y clínicamente sólida.","STK11/KEAP1 verbieten ICI":"STK11/KEAP1 prohíben ICI","Die Ko-Mutationen werden als definitive prädiktive Resistenzmarker ausgegeben.":"Las comutaciones se informan como marcadores predictivos definitivos de resistencia.","Overcalling: prognostisch/assoziativ wird mit binär prädiktiv verwechselt.":"Sobreinterpretación: se confunde evidencia pronóstica/asociativa con evidencia predictiva binaria.","Nur PD-L1 zählt":"Solo importa PD-L1","PD-L1 70 % wird ohne Genotyp- und Ko-Mutationskontext als eindeutige Antwort dargestellt.":"PD-L1 70 % se presenta como respuesta inequívoca sin contexto de genotipo ni comutaciones.","Unvollständige Integration und zu starke Individualprognose.":"Integración incompleta y pronóstico individual demasiado categórico.","PD-L1 fehlt":"Falta PD-L1","PD-L1 ergänzen.":"Añadir PD-L1.","Etablierte klinische Information steht für die MTB-Integration zur Verfügung.":"Hay información clínica establecida disponible para la integración en el MTB.","TMB/TILs gewählt":"TMB/TIL seleccionados","Als optionalen Kontext berichten.":"Informar como contexto opcional.","Kein zusätzlicher binärer Therapieentscheid aus diesen Daten.":"No debe derivarse de estos datos ninguna decisión terapéutica binaria adicional.","STK11/KEAP1 als Ausschluss formuliert":"STK11/KEAP1 formulados como exclusión","Befund sprachlich korrigieren.":"Corregir la redacción del informe.","Prognostische/assoziierte Evidenz wird von prädiktiver Aussage getrennt.":"La evidencia pronóstica/asociativa se separa de las afirmaciones predictivas.","Ein molekulares Panel liefert nicht automatisch Marker gleicher klinischer Wertigkeit.":"Un panel molecular no genera automáticamente marcadores de igual valor clínico.","STK11/KEAP1 sind wichtige adverse Kontextinformationen, aber keine simplen ICI-Ausschalter.":"STK11/KEAP1 aportan información contextual adversa importante, pero no son simples interruptores que anulan los ICI.","PD-L1 bleibt relevant, ohne individuelle Antwort zu garantieren.":"PD-L1 sigue siendo relevante sin garantizar una respuesta individual.","Gute MTB-Kommunikation macht die Evidenzebene jeder Aussage sichtbar.":"Una buena comunicación en el MTB hace explícito el nivel de evidencia de cada afirmación.","KRAS p.G12C wird als eigenständiger targetrelevanter Genotyp im passenden Therapiekontext berichtet. STK11/KEAP1 werden als adverse biologische/prognostische Ko-Alterationen eingeordnet, nicht als absolutes ICI-Verbot. PD-L1 TPS 70 % bleibt klinisch relevant. TMB/TILs können Kontext liefern, dürfen aber nicht überinterpretiert werden.":"KRAS p.G12C se informa como genotipo con relevancia terapéutica propia en el contexto adecuado. STK11/KEAP1 se clasifican como coalteraciones biológicas/pronósticas adversas, no como una prohibición absoluta de ICI. PD-L1 TPS 70 % sigue siendo clínicamente relevante. TMB/TIL pueden aportar contexto, pero no deben sobreinterpretarse.","Keine binäre STK11/KEAP1-Überinterpretation":"Sin sobreinterpretación binaria de STK11/KEAP1","PD-L1 integriert":"PD-L1 integrado","KRAS-Targetebene getrennt":"Nivel de diana KRAS separado","Zusatzmarker limitiert formuliert":"Marcadores adicionales formulados con limitaciones","Wann wird ein prognostischer Marker prädiktiv?":"¿Cuándo se convierte un marcador pronóstico en predictivo?","Wie sollte ein Befund formuliert sein, damit die Onkologie die Evidenzebene sofort erkennt?":"¿Cómo debe redactarse un informe para que oncología reconozca de inmediato el nivel de evidencia?","Welche Rolle könnten Ko-Mutationen künftig für Therapiestratifizierung spielen, ohne heutige Routineentscheidungen vorwegzunehmen?":"¿Qué papel podrían desempeñar las comutaciones en la futura estratificación terapéutica sin anticipar indebidamente las decisiones rutinarias actuales?","PD-L1 70 % trotz STK11/KEAP1":"PD-L1 70 % pese a STK11/KEAP1","Biomarker nach Evidenzebene gewichten":"Ponderar biomarcadores según nivel de evidencia","Genotyp → Ko-Mutationen → PD-L1 → integrierte Aussage":"Genotipo → comutaciones → PD-L1 → conclusión integrada","Melanom: BRAF V600 und Immuntherapie-Sequenz → Schnelle TKI-Therapie vs. Immuncheckpoint-Strategie":"Melanoma: BRAF V600 y secuenciación de inmunoterapia → terapia dirigida rápida frente a estrategia con checkpoint inmunitario","Melanom: BRAF V600 und Immuntherap…":"Melanoma: BRAF V600 y secuenciación de inmunoterap…","Dermatoonkologie / Interdisziplinäres Tumorboard":"Dermatooncología / Comité multidisciplinar de tumores","51-jähriger Patient mit neu metastasiertem kutanem Melanom, pulmonalen und hepatischen Metastasen.":"Paciente de 51 años con melanoma cutáneo recientemente metastásico, con metástasis pulmonares y hepáticas.","Liegt eine BRAF-V600-Alteration vor und wie beeinflusst sie die Sequenz zwischen Immuncheckpoint- und BRAF/MEK-Strategie?":"¿Existe una alteración BRAF V600 y cómo influye en la secuenciación entre estrategias de checkpoint inmunitario y BRAF/MEK?","Systemische Therapie soll innerhalb weniger Tage beginnen.":"El tratamiento sistémico debe comenzar en pocos días.","Performance":"Estado funcional","ECOG 0–1, zunächst klinisch stabil.":"ECOG 0–1, inicialmente clínicamente estable.","Tumorlast":"Carga tumoral","Mehrere Lebermetastasen, LDH moderat erhöht, keine initialen neurologischen Symptome.":"Múltiples metástasis hepáticas, LDH moderadamente elevada, sin síntomas neurológicos iniciales.","Entscheidungsfalle":"Trampa de decisión","Der Nachweis einer BRAF-V600-Mutation entscheidet nicht automatisch über die erste Therapiesequenz; klinisches Tempo, ZNS-Situation, Steroidbedarf und Eignung für Immuntherapie sind mitentscheidend.":"La detección de una mutación BRAF V600 no determina automáticamente la primera secuencia terapéutica; también importan el ritmo clínico, la situación del SNC, la necesidad de corticoides y la idoneidad para inmunoterapia.","Metastase eines malignen Melanoms.":"Metástasis de melanoma maligno.","SOX10 und S100 positiv, Melan-A fokal positiv.":"SOX10 y S100 positivos, Melan-A focalmente positivo.","Molekulare Kernfrage":"Pregunta molecular central","BRAF V600 muss rasch geklärt werden, damit beide strategischen Optionen realistisch bewertet werden können.":"BRAF V600 debe aclararse rápidamente para poder valorar de forma realista ambas opciones estratégicas.","Nicht die Kernfrage":"No es la pregunta central","PD-L1, TMB oder TILs sind in diesem Fall keine einfachen Schalter für die Sequenzentscheidung.":"PD-L1, TMB o TIL no son interruptores simples para decidir la secuencia en este caso.","FFPE-Lebermetastase, Block L4.":"Metástasis hepática FFPE, bloque L4.","ca. 60 %, geringe Nekrose.":"aprox. 60 %, escasa necrosis.","gut; rascher BRAF-Test technisch problemlos möglich.":"buena; la prueba rápida de BRAF es técnicamente sencilla.","10 ungefärbte Schnitte verfügbar.":"Hay 10 cortes sin teñir disponibles.","Breite Zusatzdiagnostik darf die dringliche BRAF-Klärung nicht verzögern.":"Las pruebas adicionales amplias no deben retrasar la aclaración urgente de BRAF.","BRAF V600-Status":"Estado BRAF V600","BRAF V600":"BRAF V600","BRAF p.V600E nachweisbar. Damit ist eine BRAF/MEK-basierte Therapieoption grundsätzlich vorhanden.":"Se detecta BRAF p.V600E. Por tanto, existe en principio una opción terapéutica basada en BRAF/MEK.","Melanom-IO-Kontext":"Contexto IO del melanoma","Immunhistologischer Kontext ohne eindeutigen Ausschlussbefund. Die Sequenzentscheidung bleibt primär klinisch-strategisch und wird nicht durch einen einzelnen IHC-Marker festgelegt.":"Contexto inmunohistológico sin un hallazgo claro de exclusión. La decisión de secuenciación sigue siendo principalmente clínico-estratégica y no la determina un único marcador de IHC.","TMB erhöht. Dies ersetzt weder die BRAF-Testung noch die klinische Sequenzentscheidung.":"TMB elevado. Esto no sustituye ni la prueba de BRAF ni la decisión clínica de secuenciación.","Tumoranteil und DNA-Qualität sind gut; BRAF-V600-Status ist rasch und belastbar bestimmbar.":"La fracción tumoral y la calidad del ADN son buenas; el estado BRAF V600 puede determinarse con rapidez y fiabilidad.","BRAF p.V600E ist nachweisbar und eröffnet eine BRAF/MEK-Option. Bei zunächst klinisch stabilem, immuntherapiefähigem Patienten spricht die Evidenz häufig für eine Immuntherapie-first-Strategie; bei rascher klinischer Verschlechterung oder notwendigem schnellen Tumoransprechen kann sich die Gewichtung zugunsten einer zielgerichteten Therapie verschieben.":"Se detecta BRAF p.V600E y se abre una opción BRAF/MEK. En un paciente inicialmente estable y apto para inmunoterapia, la evidencia suele favorecer una estrategia de inmunoterapia primero; ante deterioro clínico rápido o necesidad de una respuesta tumoral rápida, el balance puede inclinarse hacia la terapia dirigida.","Teilbefund: Ohne geklärten BRAF-V600-Status fehlt eine zentrale Voraussetzung für die Sequenzplanung. Zusätzliche IO-Kontextmarker ersetzen diese Klärung nicht.":"Hallazgo parcial: sin aclarar el estado BRAF V600 falta un requisito central para planificar la secuencia. Los marcadores adicionales de contexto IO no sustituyen esta aclaración.","BRAF V600 als Voraussetzung für eine BRAF/MEK-Option benennen":"Indicar BRAF V600 como requisito para una opción BRAF/MEK","Therapiesequenz nicht allein aus dem Mutationsstatus ableiten":"No derivar la secuencia terapéutica solo del estado mutacional","Tumorlast, klinisches Tempo, ZNS-Beteiligung/Steroidbedarf und Immuntherapiefähigkeit berücksichtigen":"Considerar carga tumoral, ritmo clínico, afectación del SNC/necesidad de corticoides e idoneidad para inmunoterapia","PD-L1/TMB/TILs nicht als simplen Sequenzschalter verwenden":"No usar PD-L1/TMB/TIL como simple interruptor de secuenciación","Optimale Lösung: BRAF V600 rasch klären und anschließend die Sequenz anhand von Evidenz und klinischer Dynamik entscheiden; Mutation vorhanden bedeutet nicht automatisch 'Targeted Therapy zuerst'.":"Solución óptima: aclarar rápidamente BRAF V600 y después decidir la secuencia según la evidencia y la dinámica clínica; que exista la mutación no significa automáticamente «terapia dirigida primero».","BRAF":"BRAF","KI":"IA","Melanom":"Melanoma","BRAF-V600-Melanom: Die Mutation eröffnet eine Option – die Klinik bestimmt die Sequenz":"Melanoma BRAF V600: la mutación abre una opción, la situación clínica determina la secuencia","Molekularpathologie / Dermatoonkologie / MTB":"Patología molecular / Dermatooncología / MTB","BRAF V600 als prädiktiven Marker für eine Target-Option korrekt bestimmen.":"Determinar correctamente BRAF V600 como marcador predictivo para una opción de terapia dirigida.","Den BRAF-Nachweis nicht mit einer automatischen Targeted-Therapy-first-Entscheidung verwechseln.":"No confundir la detección de BRAF con una decisión automática de terapia dirigida primero.","Klinisches Tempo, Tumorlast, ZNS-Beteiligung, Steroidbedarf und Immuntherapiefähigkeit in die Sequenz einbeziehen.":"Incluir ritmo clínico, carga tumoral, afectación del SNC, necesidad de corticoides e idoneidad para inmunoterapia en la secuenciación.","PD-L1/TMB/TILs beim Melanom nicht als einfachen Sequenzschalter überinterpretieren.":"No sobreinterpretar PD-L1/TMB/TIL en melanoma como un simple interruptor de secuenciación.","Freitagnachmittag im Melanomboard. Ein 51-jähriger Patient mit neu metastasiertem Melanom ist BRAF noch nicht getestet. Die Onkologie diskutiert bereits zwei sehr unterschiedliche Strategien: zuerst Immuncheckpoint-Therapie mit Aussicht auf langanhaltende Kontrolle oder – falls BRAF V600 positiv – eine BRAF/MEK-Therapie mit typischerweise rascherem Ansprechen. Noch wirkt der Patient klinisch stabil. Die Frage scheint planbar. Zwei Tage später ändert sich die Situation.":"Viernes por la tarde en el comité de melanoma. Un paciente de 51 años con melanoma recién metastásico aún no ha sido estudiado para BRAF. Oncología ya discute dos estrategias muy distintas: primero terapia con checkpoint inmunitario, con posibilidad de control duradero, o – si BRAF V600 es positivo – terapia BRAF/MEK con una respuesta habitualmente más rápida. El paciente aún parece clínicamente estable. La cuestión parece planificable. Dos días después, la situación cambia.","51-jähriger Patient, kutanes Melanom mit Leber- und Lungenmetastasen, ECOG 0–1, moderat erhöhtes LDH. Keine systemische Vorbehandlung. Zunächst keine neurologischen Symptome. Für die Sequenzentscheidung muss der BRAF-V600-Status rasch vorliegen; die endgültige Strategie darf aber nicht allein aus dem Genotyp abgeleitet werden.":"Paciente de 51 años, melanoma cutáneo con metástasis hepáticas y pulmonares, ECOG 0–1, LDH moderadamente elevada. Sin tratamiento sistémico previo. Inicialmente sin síntomas neurológicos. El estado BRAF V600 debe estar disponible con rapidez para decidir la secuencia, pero la estrategia final no debe derivarse solo del genotipo.","Molekulare Voraussetzung":"Requisito molecular","Ohne BRAF-V600-Nachweis gibt es keine belastbare Grundlage für eine BRAF/MEK-Strategie.":"Sin detección de BRAF V600 no existe una base sólida para una estrategia BRAF/MEK.","Erst Option nachweisen, dann Sequenz diskutieren.":"Primero demostrar la opción y después discutir la secuencia.","Initiale Klinik":"Situación clínica inicial","ECOG 0–1, systemisch metastasiert, aber zunächst keine akute Organ- oder ZNS-Symptomatik.":"ECOG 0–1, enfermedad metastásica sistémica, pero inicialmente sin síntomas agudos orgánicos ni del SNC.","Bei klinischer Stabilität kann Langzeitstrategie stärker gewichtet werden.":"Con estabilidad clínica, la estrategia a largo plazo puede ponderarse más.","Evidenz zur Sequenz":"Evidencia sobre secuenciación","Für viele geeignete Patienten mit BRAF-V600-mutiertem metastasiertem Melanom spricht die randomisierte Sequenzevidenz für Immuntherapie zuerst; dies ist aber keine starre Regel für jede klinische Situation.":"Para muchos pacientes aptos con melanoma metastásico BRAF V600 mutado, la evidencia aleatorizada sobre secuenciación respalda inmunoterapia primero; sin embargo, no es una regla rígida para toda situación clínica.","Populationsevidenz und individuelle Dringlichkeit müssen zusammengeführt werden.":"La evidencia poblacional y la urgencia individual deben integrarse.","Nicht der Schalter":"No es el interruptor","PD-L1, TMB und TILs können biologisch interessant sein, ersetzen aber weder BRAF-Testung noch die klinische Sequenzentscheidung.":"PD-L1, TMB y TIL pueden ser biológicamente interesantes, pero no sustituyen ni la prueba de BRAF ni la decisión clínica de secuenciación.","Nicht jedes messbare Immunmerkmal ist ein Routine-Entscheidungstest.":"No toda característica inmunitaria medible es una prueba rutinaria para decidir.","Histologie/IHC":"Histología/IHC","Metastase eines SOX10-/S100-positiven malignen Melanoms.":"Metástasis de melanoma maligno SOX10/S100 positivo.","Klinik initial":"Situación clínica inicial","Keine symptomatische ZNS-Beteiligung; keine Steroidtherapie.":"Sin afectación sintomática del SNC; sin tratamiento con corticoides.","Material-QC":"QC del material","Lebermetastase mit ca. 60 % Tumor; DNA-QC gut.":"Metástasis hepática con aprox. 60 % de tumor; QC de ADN bueno.","BRAF-V600-Status muss rasch vorliegen; unnötige Zusatzanalysen dürfen die Entscheidung nicht verzögern.":"El estado BRAF V600 debe estar disponible rápidamente; los análisis adicionales innecesarios no deben retrasar la decisión.","Therapiesequenz kann nicht aus der Pathologie allein entschieden werden; aktuelle klinische Dynamik muss ins MTB zurückgespielt werden.":"La secuencia terapéutica no puede decidirse solo desde patología; la dinámica clínica actual debe reincorporarse al MTB.","PD-L1/TMB/TILs sind nicht als zwingende Sequenzmarker definiert.":"PD-L1/TMB/TIL no están definidos como marcadores obligatorios de secuenciación.","Welche molekulare Information muss für die Targeted-Therapy-Option zuerst belastbar vorliegen?":"¿Qué información molecular debe estar disponible de forma fiable primero para la opción de terapia dirigida?","PD-L1 zwingend":"PD-L1 obligatorio","TMB zwingend":"TMB obligatorio","CD8/TIL-IHC zwingend":"IHC CD8/TIL obligatoria","BRAF V600 ist die zentrale molekulare Voraussetzung für eine BRAF/MEK-basierte Option.":"BRAF V600 es el requisito molecular central para una opción basada en BRAF/MEK.","Welche Faktoren beeinflussen die Sequenzentscheidung zusätzlich zum BRAF-Status?":"¿Qué factores influyen en la secuenciación además del estado BRAF?","Klinisches Progressionstempo und Tumorlast":"Ritmo clínico de progresión y carga tumoral","ZNS-Beteiligung und neurologische Symptomatik":"Afectación del SNC y síntomas neurológicos","Steroidbedarf/Immuntherapiefähigkeit":"Necesidad de corticoides/idoneidad para inmunoterapia","Allgemeinzustand und Eignung für die jeweiligen Regime":"Estado general e idoneidad para los respectivos regímenes","Alleiniger PD-L1-Wert als Sequenzschalter":"Valor de PD-L1 aislado como interruptor de secuenciación","Die Sequenz ist eine klinisch-strategische Entscheidung, nicht nur eine Genotypentscheidung.":"La secuenciación es una decisión clínico-estratégica, no solo una decisión genotípica.","Der Patient ist BRAF V600E-positiv und klinisch stabil. Welche Aussage ist am besten?":"El paciente es BRAF V600E positivo y está clínicamente estable. ¿Cuál es la mejor afirmación?","Für viele geeignete Patienten spricht die Sequenzevidenz für Immuntherapie-first; individuelle Faktoren bleiben entscheidend.":"Para muchos pacientes aptos, la evidencia de secuenciación respalda inmunoterapia primero; los factores individuales siguen siendo decisivos.","BRAF V600E bedeutet zwingend BRAF/MEK zuerst.":"BRAF V600E obliga a usar BRAF/MEK primero.","Bei BRAF-Mutation sollte Immuntherapie nicht eingesetzt werden.":"No debe utilizarse inmunoterapia si BRAF está mutado.","Erst PD-L1 entscheidet, ob BRAF/MEK oder Immuntherapie beginnt.":"PD-L1 por sí solo decide si se inicia BRAF/MEK o inmunoterapia.","Randomisierte Sequenzdaten favorisieren bei vielen geeigneten Patienten Immuntherapie-first, ohne jede dringliche Ausnahmesituation abzudecken.":"Los datos aleatorizados de secuenciación favorecen inmunoterapia primero en muchos pacientes aptos, sin abarcar todas las situaciones urgentes excepcionales.","Bestimmen Sie den BRAF-V600-Status und formulieren Sie anschließend eine Sequenzempfehlung, die Evidenz und aktuelle klinische Dynamik ausdrücklich miteinander verknüpft.":"Determinar el estado BRAF V600 y formular después una recomendación de secuenciación que vincule explícitamente la evidencia con la dinámica clínica actual.","BRAF-V600-Testung rasch durchführen.":"Realizar rápidamente la prueba BRAF V600.","Bei BRAF p.V600E beide prinzipiellen Strategien als verfügbar benennen.":"Si está presente BRAF p.V600E, indicar que ambas estrategias principales están disponibles.","Bei klinisch stabilem, immuntherapiefähigem Patienten die Evidenz für Immuntherapie-first diskutieren.":"En un paciente clínicamente estable y apto para inmunoterapia, discutir la evidencia a favor de inmunoterapia primero.","Vor Therapiebeginn aktuelle ZNS-Situation, Steroidbedarf und Progressionstempo erneut prüfen.":"Antes de iniciar el tratamiento, reevaluar la situación actual del SNC, la necesidad de corticoides y el ritmo de progresión.","Bei akuter Dynamik die Notwendigkeit schnellen Ansprechens neu gewichten.":"Ante una dinámica clínica aguda, volver a ponderar la necesidad de una respuesta rápida.","Validiertes breites Panel, wenn BRAF V600 ohne relevante Verzögerung sicher erfasst wird.":"Panel amplio validado si cubre de forma fiable BRAF V600 sin retraso relevante.","Targeted Therapy first bei dringlicher klinischer Situation oder wenn Immuntherapie nicht geeignet ist; dies muss explizit klinisch begründet werden.":"Terapia dirigida primero en una situación clínica urgente o cuando la inmunoterapia no sea adecuada; debe justificarse clínicamente de forma explícita.","BRAF-mutiert = automatisch Targeted Therapy first":"BRAF mutado = automáticamente terapia dirigida primero","Der Genotyp eröffnet die Option, entscheidet aber nicht alleine die optimale Sequenz.":"El genotipo abre la opción, pero no determina por sí solo la secuencia óptima.","PD-L1 entscheidet die Reihenfolge":"PD-L1 decide la secuencia","Beim metastasierten Melanom ist PD-L1 kein einfacher Sequenzschalter zwischen BRAF/MEK und Immuntherapie.":"En melanoma metastásico, PD-L1 no es un simple interruptor de secuenciación entre BRAF/MEK e inmunoterapia.","Klinik vom Molekularbefund trennen":"Separar situación clínica del hallazgo molecular","Eine Sequenzentscheidung kann sich durch akute Progression innerhalb von Tagen verändern.":"Una decisión de secuenciación puede cambiar en cuestión de días por una progresión aguda.","48 Stunden später: neue symptomatische Hirnmetastase":"48 horas después: nueva metástasis cerebral sintomática","Noch vor Therapiebeginn entwickelt der Patient Kopfschmerzen und eine diskrete Hemiparese. Das MRT zeigt eine neue symptomatische Hirnmetastase; Dexamethason wird begonnen. Gleichzeitig liegt der molekulare Befund vor: BRAF p.V600E. Die ursprünglich in Ruhe geplante Sequenz muss unter dem Gesichtspunkt rascher Krankheitskontrolle und Steroidbedarf neu diskutiert werden.":"Antes de iniciar el tratamiento, el paciente desarrolla cefalea y una hemiparesia discreta. La RM muestra una nueva metástasis cerebral sintomática y se inicia dexametasona. Al mismo tiempo llega el resultado molecular: BRAF p.V600E. La secuencia inicialmente planificada con calma debe replantearse ante la necesidad de un control rápido de la enfermedad y el uso de corticoides.","Der molekulare Befund ist unverändert, aber die klinische Priorität hat sich verändert. Genau deshalb darf BRAF V600 nie isoliert als Sequenzautomat interpretiert werden.":"El hallazgo molecular no ha cambiado, pero sí la prioridad clínica. Precisamente por eso BRAF V600 nunca debe interpretarse de forma aislada como una orden automática de secuenciación.","BRAF positiv, Klinik integriert":"BRAF positivo, contexto clínico integrado","BRAF p.V600E nachweisbar. Beide Strategien sind grundsätzlich verfügbar; nach klinischer Verschlechterung wird die Notwendigkeit schneller Kontrolle im MTB neu gewichtet.":"Se detecta BRAF p.V600E. Ambas estrategias están disponibles en principio; tras el deterioro clínico, la necesidad de control rápido se vuelve a ponderar en el MTB.","Sehr gute Verbindung von molekularer Option und klinischer Situation.":"Muy buena conexión entre la opción molecular y la situación clínica.","Mutation entscheidet alles":"La mutación lo decide todo","BRAF p.V600E wird automatisch mit 'BRAF/MEK zuerst' gleichgesetzt, unabhängig von Klinik und Sequenzevidenz.":"BRAF p.V600E se equipara automáticamente con «BRAF/MEK primero», independientemente del contexto clínico y de la evidencia de secuenciación.","Zu mechanistisch; Option und Sequenz wurden verwechselt.":"Demasiado mecanicista; se confundió la disponibilidad de una opción con la secuencia.","Nur IO-Kontextmarker":"Solo marcadores de contexto IO","PD-L1/TMB/TILs werden breit untersucht, BRAF bleibt ausstehend.":"Se estudian ampliamente PD-L1/TMB/TIL mientras BRAF sigue pendiente.","Die zentrale molekulare Voraussetzung für eine Targeted-Therapy-Option fehlt.":"Falta el requisito molecular central para una opción de terapia dirigida.","BRAF V600E positiv, klinisch stabil":"BRAF V600E positivo, clínicamente estable","Immuntherapie-first als evidenzgestützte Standardstrategie für viele geeignete Patienten diskutieren.":"Discutir inmunoterapia primero como estrategia estándar respaldada por evidencia para muchos pacientes aptos.","Langfristige Sequenzplanung steht im Vordergrund.":"La planificación de la secuencia a largo plazo es prioritaria.","Neue symptomatische ZNS-Progression/Steroidbedarf":"Nueva progresión sintomática del SNC/necesidad de corticoides","Sequenz im MTB sofort neu bewerten und schnelle Krankheitskontrolle stärker gewichten.":"Reevaluar inmediatamente la secuencia en el MTB y dar mayor peso al control rápido de la enfermedad.","Targeted Therapy kann klinisch an Gewicht gewinnen.":"La terapia dirigida puede ganar peso clínico.","BRAF nicht bestimmt":"BRAF no determinado","Schnelltest nachfordern.":"Solicitar prueba rápida.","Sequenzentscheidung bleibt unvollständig.":"La decisión de secuenciación sigue incompleta.","BRAF V600 ist ein prädiktiver Marker für eine Target-Option, kein automatischer Sequenzbefehl.":"BRAF V600 es un marcador predictivo para una opción dirigida, no una orden automática de secuenciación.","Bei vielen geeigneten, stabilen Patienten spricht randomisierte Sequenzevidenz für Immuntherapie-first.":"Para muchos pacientes aptos y estables, la evidencia aleatorizada de secuenciación respalda inmunoterapia primero.","Akute klinische Dynamik kann die optimale Reihenfolge verändern.":"La dinámica clínica aguda puede cambiar el orden óptimo.","Molekularpathologie ist Teil der Entscheidung, aber nicht deren alleiniger Eigentümer.":"La patología molecular forma parte de la decisión, pero no es su único dueño.","BRAF p.V600E wird rasch bestätigt. Zunächst wäre bei klinischer Stabilität für viele geeignete Patienten Immuntherapie-first evidenzgestützt. Der Twist – symptomatische Hirnmetastase mit Steroidbedarf – erzwingt eine erneute klinische Gewichtung und kann die Bedeutung einer rasch wirksamen BRAF/MEK-Strategie erhöhen. PD-L1/TMB/TILs sind kein einfacher Sequenzschalter.":"BRAF p.V600E se confirma rápidamente. Inicialmente, con estabilidad clínica, inmunoterapia primero estaría respaldada por evidencia para muchos pacientes aptos. El giro – una metástasis cerebral sintomática que requiere corticoides – obliga a una nueva ponderación clínica y puede aumentar la relevancia de una estrategia BRAF/MEK de acción rápida. PD-L1/TMB/TIL no son un simple interruptor de secuenciación.","BRAF als Voraussetzung erkannt":"BRAF reconocido como requisito","Keine automatische Targeted-first-Regel":"Sin regla automática de terapia dirigida primero","Klinische Dynamik integriert":"Dinámica clínica integrada","IO-Kontextmarker nicht überinterpretiert":"Marcadores de contexto IO no sobreinterpretados","Welche Patientengruppen waren in Sequenzstudien besonders gut repräsentiert – und welche weniger?":"¿Qué grupos de pacientes estuvieron especialmente bien representados en los estudios de secuenciación y cuáles menos?","Wie ändert Steroidbedarf die praktische Immuntherapieplanung?":"¿Cómo cambia la necesidad de corticoides la planificación práctica de la inmunoterapia?","Welche Information muss die Pathologie liefern und welche Entscheidung bleibt interdisziplinär?":"¿Qué información debe aportar patología y qué decisión sigue siendo interdisciplinar?","symptomatische Hirnmetastase nach initial stabiler Situation":"metástasis cerebral sintomática tras una situación inicialmente estable","Mutation eröffnet Option, Klinik bestimmt Sequenz":"La mutación abre la opción, la situación clínica determina la secuencia","BRAF-Test → stabile Sequenzplanung → klinischer Twist → Re-Assessment":"Prueba BRAF → planificación estable de secuencia → giro clínico → reevaluación","GIST mit KIT/PDGFRA-Fragestellung → Welcher Marker entscheidet über TKI-Auswahl?":"GIST con cuestión KIT/PDGFRA → ¿Qué marcador determina la selección del TKI?","GIST mit KIT/PDGFRA-Fragestellung":"GIST con cuestión KIT/PDGFRA","Sarkomzentrum / MTB":"Centro de sarcomas / MTB","64-jährige Patientin mit gastralem GIST und neu aufgetretenen Lebermetastasen.":"Mujer de 64 años con GIST gástrico y nuevas metástasis hepáticas.","Ist 'GIST = Imatinib' ausreichend, oder muss vor der TKI-Auswahl der KIT/PDGFRA-Genotyp vorliegen?":"¿Es suficiente «GIST = imatinib» o debe conocerse el genotipo KIT/PDGFRA antes de elegir el TKI?","Therapiebeginn ist nach Abschluss der molekularen Typisierung geplant.":"El inicio del tratamiento está previsto tras completar la tipificación molecular.","Primärtumor":"Tumor primario","Gastraler GIST, vor drei Jahren reseziert; nun hepatische Metastasierung.":"GIST gástrico resecado hace tres años; ahora metástasis hepáticas.","Keine systemische TKI-Therapie.":"Sin tratamiento sistémico con TKI.","Klinischer Reflex":"Reflejo clínico","Im Tumorboard fällt früh der Satz: 'CD117-positiver GIST – dann Imatinib.'":"En el comité se dice pronto: «GIST CD117 positivo; entonces imatinib». ","Lernziel":"Objetivo de aprendizaje","Diagnosemarker und prädiktiver Genotyp müssen getrennt werden.":"Los marcadores diagnósticos y el genotipo predictivo deben mantenerse separados.","Epithelioider mesenchymaler Tumor, morphologisch passend zu GIST.":"Tumor mesenquimal epitelioide, morfológicamente compatible con GIST.","DOG1 stark positiv, CD117 nur fokal/heterogen positiv.":"DOG1 intensamente positivo, CD117 solo focal/heterogéneamente positivo.","Arbeitsdiagnose":"Diagnóstico de trabajo","Metastasierter gastrointestinaler Stromatumor.":"Tumor del estroma gastrointestinal metastásico.","Welcher KIT-/PDGFRA-Genotyp liegt vor und verändert er die TKI-Auswahl?":"¿Qué genotipo KIT/PDGFRA está presente y modifica la selección del TKI?","FFPE-Lebermetastase, Block H3.":"Metástasis hepática FFPE, bloque H3.","ca. 75 %, DNA-QC gut.":"aprox. 75 %, QC de ADN bueno.","6 ungefärbte Schnitte verfügbar.":"Hay 6 cortes sin teñir disponibles.","Ein sehr breites Pan-Tumor-Panel ist für die konkrete Erstfrage unnötig, wenn eine valide KIT/PDGFRA-Analyse verfügbar ist.":"Un panel pan-tumoral muy amplio es innecesario para la pregunta inicial concreta si se dispone de un análisis KIT/PDGFRA válido.","KIT/PDGFRA-Genotyp":"Genotipo KIT/PDGFRA","KIT/PDGFRA":"KIT/PDGFRA","PDGFRA Exon 18 p.D842V nachweisbar; keine aktivierende KIT-Mutation. Die Konstellation ist für die TKI-Auswahl unmittelbar relevant.":"Se detecta PDGFRA exón 18 p.D842V; no hay mutación activadora de KIT. Esta constelación es directamente relevante para la selección del TKI.","Hoher Tumoranteil, DNA-Qualität gut; gezielte KIT/PDGFRA-Analyse vollständig auswertbar.":"Alta fracción tumoral, buena calidad de ADN; el análisis dirigido KIT/PDGFRA es completamente evaluable.","Metastasierter GIST mit PDGFRA p.D842V. Der Genotyp widerspricht dem reflexhaften 'Imatinib für jeden GIST'-Schema und verlangt eine genotypspezifische TKI-Strategie.":"GIST metastásico con PDGFRA p.D842V. El genotipo contradice el reflejo «imatinib para todo GIST» y exige una estrategia TKI específica del genotipo.","Teilbefund: Die GIST-Diagnose ist morphologisch/IHC-basiert gesichert, aber ohne KIT/PDGFRA-Genotyp ist die prädiktive TKI-Einordnung unvollständig.":"Hallazgo parcial: el diagnóstico de GIST está establecido por morfología/IHC, pero sin el genotipo KIT/PDGFRA la clasificación predictiva para TKI está incompleta.","DOG1/CD117 als Diagnosekontext, nicht als ausreichenden prädiktiven Marker einordnen":"Clasificar DOG1/CD117 como contexto diagnóstico, no como marcadores predictivos suficientes","PDGFRA D842V explizit benennen":"Indicar explícitamente PDGFRA D842V","Genotypspezifische TKI-Auswahl statt pauschalem Imatinib-Reflex formulieren":"Formular una selección de TKI específica del genotipo en lugar de un reflejo general de imatinib","Bei KIT/PDGFRA-Wildtyp weitere molekulare Subklassifikation als mögliche Folgefrage erwähnen, ohne sie in diesem Fall zu erzwingen":"Si KIT/PDGFRA son wild type, mencionar una subclasificación molecular adicional como posible paso posterior sin imponerla en este caso","Optimale Lösung: KIT/PDGFRA gezielt bestimmen. Der Nachweis von PDGFRA p.D842V ist der Twist, der die TKI-Auswahl gegenüber einem pauschalen Imatinib-Ansatz verändert.":"Solución óptima: realizar un análisis dirigido KIT/PDGFRA. La detección de PDGFRA p.D842V es el giro que cambia la selección del TKI frente a un enfoque general con imatinib.","KIT":"KIT","PDGFRA":"PDGFRA","GIST":"GIST","Mini":"Mini","GIST ist nicht gleich Imatinib: PDGFRA D842V kippt den TKI-Reflex":"GIST no equivale a imatinib: PDGFRA D842V cambia el reflejo del TKI","Molekularpathologie / Sarkompathologie / MTB":"Patología molecular / Patología de sarcomas / MTB","GIST-Diagnosemarker und prädiktiven KIT/PDGFRA-Genotyp klar trennen.":"Separar claramente los marcadores diagnósticos de GIST del genotipo predictivo KIT/PDGFRA.","Vor systemischer TKI-Therapie die für Sensitivität/Resistenz relevante Mutationsklasse bestimmen.":"Antes de la terapia sistémica con TKI, determinar la clase mutacional relevante para sensibilidad/resistencia.","PDGFRA D842V als klinisch entscheidenden Sonderfall erkennen.":"Reconocer PDGFRA D842V como un caso especial clínicamente decisivo.","Für eine fokussierte klinische Frage eine gezielte, ressourcenschonende Methode wählen.":"Elegir un método dirigido y eficiente en recursos para una pregunta clínica focalizada.","Im Sarkomboard ist der Fall scheinbar in zehn Sekunden erledigt: metastasierter GIST, DOG1 positiv, also Imatinib. Die Pathologin stoppt die Diskussion mit einer einfachen Frage: 'Welcher KIT- oder PDGFRA-Genotyp liegt eigentlich vor?' Plötzlich ist klar, dass der diagnostische Name noch keine prädiktive Antwort ist.":"En el comité de sarcomas, el caso parece resuelto en diez segundos: GIST metastásico, DOG1 positivo, por tanto imatinib. La patóloga detiene la discusión con una pregunta sencilla: «¿Qué genotipo KIT o PDGFRA está realmente presente?». De repente queda claro que el nombre diagnóstico aún no es una respuesta predictiva.","64-jährige Patientin mit vor drei Jahren reseziertem gastralem GIST und jetzt multiplen Lebermetastasen. DOG1 stark positiv, CD117 fokal. Keine bisherige TKI-Therapie. Vor Therapiebeginn soll der KIT/PDGFRA-Status geklärt werden.":"Mujer de 64 años con GIST gástrico resecado hace tres años y ahora múltiples metástasis hepáticas. DOG1 intensamente positivo, CD117 focal. Sin tratamiento previo con TKI. Debe aclararse el estado KIT/PDGFRA antes de iniciar el tratamiento.","Diagnose":"Diagnóstico","Morphologie und DOG1/CD117 sichern den GIST-Kontext.":"La morfología y DOG1/CD117 establecen el contexto de GIST.","IHC beantwortet 'Was ist der Tumor?', nicht automatisch 'Welcher TKI wirkt?'.":"La IHC responde «¿Qué es el tumor?», no automáticamente «¿Qué TKI funciona?». ","Therapiefrage":"Pregunta terapéutica","Die Onkologie möchte mit einer TKI-Therapie beginnen.":"Oncología desea iniciar tratamiento con TKI.","Der prädiktive Genotyp gehört vor die Wirkstoffwahl.":"El genotipo predictivo debe preceder a la selección del fármaco.","Lebermetastase, 75 % Tumor, DNA-QC sehr gut; nur sechs Schnitte nötig verfügbar.":"Metástasis hepática, 75 % de tumor, QC de ADN muy bueno; solo se requieren/disponen seis cortes.","Eine fokussierte KIT/PDGFRA-Analyse ist effizient.":"Un análisis dirigido KIT/PDGFRA es eficiente.","Epithelioider mesenchymaler Tumor, vereinbar mit GIST.":"Tumor mesenquimal epitelioide, compatible con GIST.","DOG1 stark positiv; CD117 fokal/heterogen positiv.":"DOG1 intensamente positivo; CD117 positivo focal/heterogéneo.","Systemtherapie":"Tratamiento sistémico","Noch nicht begonnen.":"Aún no iniciado.","Kleine, aber sehr tumorreiche Metastasenbiopsie.":"Biopsia metastásica pequeña pero muy rica en tumor.","Die klinische Kernfrage ist fokussiert; ein extrem breites Pan-Tumor-Panel ist nicht zwingend nötig.":"La pregunta clínica central está focalizada; no es obligatorio un panel pan-tumoral extremadamente amplio.","Therapie sollte nicht allein aufgrund der IHC gestartet werden, wenn der Genotyp zeitnah verfügbar ist.":"El tratamiento no debe iniciarse solo basándose en IHC si el genotipo puede estar disponible rápidamente.","Welcher Befund entscheidet in diesem Fall am direktesten über die TKI-Auswahl?":"¿Qué hallazgo determina más directamente la selección del TKI en este caso?","KIT/PDGFRA-Mutationsstatus":"Estado mutacional KIT/PDGFRA","Stärke der CD117-IHC allein":"Solo la intensidad de la IHC CD117","Ki-67 allein":"Solo Ki-67","Der KIT/PDGFRA-Genotyp ist für die prädiktive Einordnung zentral.":"El genotipo KIT/PDGFRA es central para la clasificación predictiva.","Was bedeutet DOG1+/CD117+ für die TKI-Wahl?":"¿Qué significa DOG1+/CD117+ para la selección del TKI?","Es stützt die GIST-Diagnose, ersetzt aber die Genotypisierung nicht.":"Apoya el diagnóstico de GIST, pero no sustituye la genotipificación.","Es beweist Imatinib-Sensitivität.":"Demuestra sensibilidad a imatinib.","Es schließt PDGFRA-Mutationen aus.":"Excluye mutaciones de PDGFRA.","Es macht molekulare Diagnostik grundsätzlich überflüssig.":"Hace innecesario en general el diagnóstico molecular.","Diagnostische IHC und prädiktive Genotypisierung beantworten verschiedene Fragen.":"La IHC diagnóstica y la genotipificación predictiva responden preguntas distintas.","Wählen Sie die minimale diagnostische Strategie, mit der die geplante TKI-Therapie genotypspezifisch abgesichert werden kann.":"Elegir la estrategia diagnóstica mínima que permita respaldar la terapia TKI planificada de forma específica del genotipo.","GIST-Diagnose als gesichert akzeptieren.":"Aceptar el diagnóstico de GIST como establecido.","KIT/PDGFRA-Mutationsanalyse durchführen.":"Realizar análisis mutacional de KIT/PDGFRA.","Mutation auf Exon/Variantebene berichten.":"Informar la mutación a nivel de exón/variante.","Therapieempfehlung an die konkrete Sensitivitäts-/Resistenzkonstellation koppeln.":"Vincular la recomendación terapéutica con la constelación específica de sensibilidad/resistencia.","Bei KIT/PDGFRA-Wildtyp weitere Subklassifikation nur als Folgefrage erwägen.":"Si KIT/PDGFRA son wild type, considerar una subclasificación adicional solo como pregunta posterior.","Breiteres validiertes NGS-Panel, wenn es KIT/PDGFRA vollständig abdeckt und ohne relevante Mehrbelastung verfügbar ist.":"Panel NGS validado más amplio si cubre completamente KIT/PDGFRA y está disponible sin una carga adicional relevante.","CD117 positiv = Imatinib":"CD117 positivo = imatinib","Diagnostische Proteinexpression wird fälschlich als prädiktiver Genotyp interpretiert.":"La expresión proteica diagnóstica se interpreta erróneamente como genotipo predictivo.","Pan-Panel ohne klare Zusatzfrage":"Pan-panel sin pregunta adicional clara","Kann funktionieren, ist bei der fokussierten Erstfrage aber unnötig breit.":"Puede funcionar, pero es innecesariamente amplio para la pregunta inicial focalizada.","Therapie vor Genotyp":"Tratamiento antes del genotipo","Eine klinisch relevante Resistenz-/Sensitivitätskonstellation kann übersehen werden.":"Puede pasarse por alto una constelación de resistencia/sensibilidad clínicamente relevante.","PDGFRA D842V statt 'klassischem KIT-GIST'":"PDGFRA D842V en lugar de «GIST KIT clásico»","Die gezielte Sequenzierung zeigt keine KIT-Mutation, sondern PDGFRA Exon 18 p.D842V. Der zunächst reflexhaft diskutierte Imatinib-Start wäre für genau diese Konstellation ungeeignet; die TKI-Strategie muss genotypspezifisch geändert werden.":"La secuenciación dirigida no muestra una mutación KIT, sino PDGFRA exón 18 p.D842V. El inicio reflejo con imatinib sería inadecuado precisamente para esta constelación; la estrategia TKI debe modificarse según el genotipo.","Der Fall zeigt maximal kompakt, warum Diagnosesicherung und prädiktive Molekularpathologie zwei getrennte Schritte sind.":"El caso muestra de forma muy compacta por qué la confirmación diagnóstica y la patología molecular predictiva son dos pasos separados.","Genotyp vor TKI":"Genotipo antes del TKI","PDGFRA Exon 18 p.D842V, KIT wildtyp.":"PDGFRA exón 18 p.D842V, KIT wild type.","Kernentscheidung getroffen; TKI-Auswahl kann genotypspezifisch erfolgen.":"Decisión central tomada; la selección del TKI puede realizarse según el genotipo.","IHC reicht":"La IHC es suficiente","GIST wird korrekt diagnostiziert, aber ohne KIT/PDGFRA-Genotyp pauschal als Imatinib-sensitiv behandelt.":"El GIST se diagnostica correctamente, pero sin genotipo KIT/PDGFRA se trata de forma genérica como sensible a imatinib.","Diagnose korrekt, prädiktive Ebene verfehlt.":"Diagnóstico correcto, nivel predictivo omitido.","Breites Pan-Panel":"Pan-panel amplio","PDGFRA D842V wird ebenfalls gefunden, jedoch mit mehr Ressourcen als für die Kernfrage nötig.":"PDGFRA D842V también se detecta, pero utilizando más recursos de los necesarios para la pregunta central.","Fachlich brauchbar, aber weniger fokussiert.":"Clínicamente útil, pero menos focalizado.","PDGFRA D842V":"PDGFRA D842V","Genotypspezifische TKI-Strategie im Sarkomboard diskutieren.":"Discutir una estrategia TKI específica del genotipo en el comité de sarcomas.","Pauschaler Imatinib-Reflex wird vermieden.":"Se evita el reflejo generalizado de imatinib.","KIT/PDGFRA wildtyp":"KIT/PDGFRA wild type","Weitere molekulare Subklassifikation erwägen.":"Considerar una subclasificación molecular adicional.","Der Fall geht in eine zweite diagnostische Ebene über.":"El caso pasa a un segundo nivel diagnóstico.","DOG1/CD117 sichern den diagnostischen Kontext, nicht die TKI-Sensitivität.":"DOG1/CD117 establecen el contexto diagnóstico, no la sensibilidad al TKI.","KIT/PDGFRA-Genotypisierung ist eine prädiktive Entscheidungsebene.":"La genotipificación KIT/PDGFRA es un nivel predictivo de decisión.","PDGFRA D842V ist der klassische Fall, in dem ein pauschaler Imatinib-Reflex scheitert.":"PDGFRA D842V es el caso clásico en el que falla el reflejo generalizado de imatinib.","Fokussierte Diagnostik kann besser sein als maximale Panelbreite, wenn die klinische Frage klar ist.":"Un diagnóstico focalizado puede ser mejor que la máxima amplitud de panel cuando la pregunta clínica está clara.","Gezielte KIT/PDGFRA-Analyse vor TKI-Start. Ergebnis: PDGFRA Exon 18 p.D842V, KIT wildtyp. Damit ist der reflexhafte Imatinib-Ansatz nicht passend; die Therapie muss genotypspezifisch geplant werden.":"Análisis dirigido KIT/PDGFRA antes de iniciar TKI. Resultado: PDGFRA exón 18 p.D842V, KIT wild type. Por tanto, el enfoque reflejo con imatinib no es adecuado; el tratamiento debe planificarse según el genotipo.","Diagnose vs. Prädiktion getrennt":"Diagnóstico y predicción separados","KIT/PDGFRA gewählt":"KIT/PDGFRA seleccionado","D842V korrekt gewichtet":"D842V ponderado correctamente","Keine unnötige Panelinflation":"Sin inflación innecesaria del panel","Welche weiteren GIST-Genotypen beeinflussen Dosis oder TKI-Sensitivität?":"¿Qué otros genotipos de GIST influyen en la dosis o en la sensibilidad a TKI?","Wann wäre ein breiteres Panel sinnvoll?":"¿Cuándo sería útil un panel más amplio?","Wie sollte ein Befund formuliert sein, damit Diagnose und Prädiktion klar getrennt bleiben?":"¿Cómo debe redactarse un informe para que diagnóstico y predicción queden claramente separados?","GIST-Diagnose ist nicht gleich TKI-Sensitivität":"El diagnóstico de GIST no equivale a sensibilidad a TKI","IHC-Diagnose → Genotyp → TKI-Wechsel":"Diagnóstico por IHC → genotipo → cambio de TKI","Cholangiozelluläres Karzinom mit FGFR2/IDH-Frage → Paneldiagnostik und Studienoptionen":"Colangiocarcinoma con cuestión FGFR2/IDH → análisis por panel y opciones de ensayo clínico","Cholangiozelluläres Karzinom mit F…":"Colangiocarcinoma con cuestión FGFR2/IDH…","Hepatobiliäre Onkologie / MTB":"Oncología hepatobiliar / MTB","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie.":"Mujer de 59 años con colangiocarcinoma intrahepático irresecable y progresión tras tratamiento de primera línea.","Welche molekulare Profilierung ist jetzt sinnvoll, insbesondere für FGFR2- und IDH1/2-Alterationen sowie weitere potenziell targetierbare Befunde?":"¿Qué perfil molecular es adecuado ahora, especialmente para alteraciones FGFR2 e IDH1/2 y otros hallazgos potencialmente accionables?","Der molekulare Befund soll vor Festlegung der nächsten Therapielinie vorliegen.":"El informe molecular debe estar disponible antes de definir la siguiente línea de tratamiento.","Tumorlokalisation":"Localización tumoral","Intrahepatische dominante Raumforderung mit multiplen Satelliten und pulmonalen Metastasen.":"Masa intrahepática dominante con múltiples satélites y metástasis pulmonares.","Systemische Erstlinientherapie abgeschlossen; aktuell radiologischer Progress.":"Tratamiento sistémico de primera línea completado; progresión radiológica actual.","Ein kleines DNA-only-Panel aus der Erstdiagnose meldete keinen therapeutisch relevanten SNV/Indel-Befund; Fusionen waren im Bericht nicht valide abgedeckt.":"Un pequeño panel solo de ADN del diagnóstico inicial no informó ningún SNV/indel terapéuticamente relevante; las fusiones no estaban cubiertas de forma válida.","'Panel negativ' wird im Tumorboard bereits mit 'keine Target-Option' gleichgesetzt.":"En el comité, «panel negativo» ya se equipara a «sin opción dirigida». ","Adenokarzinom mit tubulären und desmoplastischen Anteilen, vereinbar mit intrahepatischem Cholangiokarzinom.":"Adenocarcinoma con componentes tubulares y desmoplásicos, compatible con colangiocarcinoma intrahepático.","CK7 positiv; HepPar1/Arginase-1 negativ; klinisch-radiologische Integration stützt iCCA.":"CK7 positivo; HepPar1/Arginase-1 negativos; la integración clínico-radiológica apoya iCCA.","Breite DNA-basierte Alterationen und insbesondere strukturelle FGFR2-Ereignisse müssen methodisch adäquat erfasst werden.":"Las alteraciones amplias basadas en ADN y, en particular, los eventos estructurales de FGFR2 deben captarse con métodos adecuados.","Nicht relevant":"No relevante","Neuroonkologische IDH1-R132H-IHC, G-CIMP oder ein ZNS-Methylierungsclassifier beantworten diese Fragestellung nicht.":"La IHC IDH1-R132H de neurooncología, G-CIMP o un clasificador de metilación del SNC no responden a esta pregunta.","FFPE-Leberbiopsie, Block C5.":"Biopsia hepática FFPE, bloque C5.","ca. 50 %, ausreichende vitale Tumorareale.":"aprox. 50 %, áreas tumorales viables suficientes.","DNA/RNA-QC":"QC ADN/ARN","DNA gut; RNA nach QC ausreichend.":"ADN bueno; ARN suficiente tras QC.","Erneutes DNA-only-Testen ohne valide Fusionserfassung kann denselben blinden Fleck reproduzieren.":"Repetir un análisis solo de ADN sin cobertura válida de fusiones puede reproducir el mismo punto ciego.","CCA-Molekularprofil / IDH1/2-Kontext":"Perfil molecular de CCA / contexto IDH1/2","FGFR2-Fusions-/Rearrangementdiagnostik":"Estudio de fusión/reordenamiento FGFR2","CCA-DNA-Profil":"Perfil de ADN de CCA","Keine pathogene IDH1/2-Mutation; kein BRAF-V600- oder ERBB2-Hotspot-Befund. Das DNA-Profil allein erklärt keine Target-Option.":"Sin mutación patogénica IDH1/2; sin hallazgo BRAF V600 ni hotspot ERBB2. El perfil de ADN por sí solo no revela una opción dirigida.","FGFR2-Fusionsdiagnostik":"Estudio de fusiones FGFR2","FGFR2::BICC1-Fusion nachweisbar. Der Befund ist bei intrahepatischem Cholangiokarzinom therapeutisch relevant und gehört in die nächste Linienplanung.":"Se detecta fusión FGFR2::BICC1. El hallazgo es terapéuticamente relevante en colangiocarcinoma intrahepático y debe incorporarse a la planificación de la siguiente línea.","DNA und RNA aus dem markierten Tumorareal sind auswertbar; ausreichende Restreserve vorhanden.":"El ADN y ARN del área tumoral marcada son evaluables; queda suficiente reserva de material.","Intrahepatisches Cholangiokarzinom mit FGFR2::BICC1-Fusion und ohne IDH1/2-Mutation. Die zuvor DNA-only negative Profilierung war kein ausreichender Ausschluss einer strukturellen Targetalteration.":"Colangiocarcinoma intrahepático con fusión FGFR2::BICC1 y sin mutación IDH1/2. El perfil previo negativo solo de ADN no fue suficiente para excluir una alteración estructural dirigible.","Teilbefund: Die CCA-Profilierung ist ohne belastbare FGFR2-Fusions-/Rearrangementdiagnostik unvollständig. Neuroonkologische IDH-/Methylierungsverfahren sind für diese Frage nicht geeignet.":"Hallazgo parcial: el perfil de CCA está incompleto sin un estudio robusto de fusiones/reordenamientos FGFR2. Los métodos IDH/metilación de neurooncología no son adecuados para esta cuestión.","Intrahepatisches Cholangiokarzinom als relevanten molekularen Kontext benennen":"Indicar el colangiocarcinoma intrahepático como contexto molecular relevante","FGFR2-Fusion/Rearrangement als eigenständige strukturelle Alterationsklasse erfassen":"Captar la fusión/reordenamiento FGFR2 como una clase estructural de alteración propia","IDH1/2-Sequenzierung im CCA-Kontext von neuroonkologischer IDH-IHC/Methylomdiagnostik trennen":"Separar la secuenciación IDH1/2 en el contexto de CCA de la IHC IDH/estudio del metiloma de neurooncología","DNA-only Negativbefund nicht als vollständigen Fusionsausschluss formulieren":"No formular un resultado negativo solo de ADN como exclusión completa de fusiones","Optimale Lösung: CCA-spezifisches Molekularprofil plus valide FGFR2-Fusionserfassung. Der ZNS-Methylierungs-/G-CIMP-Copyover wird vollständig entfernt.":"Solución óptima: perfil molecular específico de CCA más detección válida de fusiones FGFR2. Se elimina por completo el copyover de metilación del SNC/G-CIMP.","IDH":"IDH","FGFR":"FGFR","Intrahepatisches Cholangiokarzinom: Das negative DNA-Panel übersieht die strukturelle Targetalteration":"Colangiocarcinoma intrahepático: el panel de ADN negativo pasa por alto la alteración estructural dirigible","Molekularpathologie / hepatobiliäre Onkologie / MTB":"Patología molecular / oncología hepatobiliar / MTB","Das intrahepatische Cholangiokarzinom als Entität mit relevanter breiter molekularer Profilierung einordnen.":"Clasificar el colangiocarcinoma intrahepático como una entidad que requiere un perfil molecular amplio relevante.","FGFR2-Fusionen/Rearrangements methodisch von SNV/Indel-Analysen unterscheiden.":"Distinguir metodológicamente las fusiones/reordenamientos FGFR2 de los análisis de SNV/indel.","IDH1/2 im CCA-Kontext von neuroonkologischer IDH-IHC/G-CIMP/Methylomdiagnostik trennen.":"Separar IDH1/2 en el contexto de CCA del diagnóstico de neurooncología mediante IHC IDH/G-CIMP/metiloma.","Einen negativen DNA-only-Befund nicht als vollständigen Ausschluss struktureller Targetalterationen interpretieren.":"No interpretar un resultado negativo solo de ADN como exclusión completa de alteraciones estructurales dirigibles.","Im hepatobiliären MTB liegt ein alter Molekularbefund mit der Überschrift 'kein targetierbarer Befund'. Die 59-jährige Patientin mit intrahepatischem Cholangiokarzinom ist nach Erstlinientherapie progredient, und die nächste Linie muss geplant werden. Beim Blick in den Methodenteil zeigt sich: Das damalige kleine Panel war DNA-basiert und auf SNV/Indels fokussiert. FGFR2-Rearrangements wurden nicht valide breit erfasst. Gleichzeitig findet sich in der Falllogik ein völlig fachfremder Verweis auf G-CIMP und einen ZNS-Methylierungsclassifier – genau diese Altlast soll der Fall jetzt bewusst bereinigen.":"En el MTB hepatobiliar hay un antiguo informe molecular titulado «sin hallazgo dirigible». La paciente de 59 años con colangiocarcinoma intrahepático ha progresado tras la primera línea y debe planificarse la siguiente. Al revisar el apartado de métodos se ve que el pequeño panel previo era de ADN y se centraba en SNV/indels. Los reordenamientos FGFR2 no estaban cubiertos de forma amplia y válida. Al mismo tiempo, la lógica del caso contiene una referencia completamente ajena a G-CIMP y a un clasificador de metilación del SNC: justamente este residuo histórico es lo que el caso pretende corregir de forma explícita.","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie. DNA-only-Vorbefund ohne relevante SNV/Indel-Targetalteration. Für die nächste Linie sollen FGFR2-Fusionen/Rearrangements, IDH1/2 und weitere relevante molekulare Alterationen methodisch vollständig bewertet werden.":"Mujer de 59 años con colangiocarcinoma intrahepático irresecable y progresión tras primera línea. Resultado previo solo de ADN sin alteración SNV/indel dirigible relevante. Para la siguiente línea deben evaluarse de forma completa, con métodos adecuados, las fusiones/reordenamientos FGFR2, IDH1/2 y otras alteraciones moleculares relevantes.","Entität":"Entidad","Intrahepatisches Cholangiokarzinom mit metastasierter Erkrankung.":"Colangiocarcinoma intrahepático con enfermedad metastásica.","Tumorentität und Erkrankungsphase bestimmen die sinnvolle molekulare Breite.":"La entidad tumoral y la fase de la enfermedad determinan la amplitud molecular adecuada.","Kleines DNA-only-Panel ohne relevanten SNV/Indel-Treffer; keine belastbare breite Fusionserfassung.":"Pequeño panel solo de ADN sin hallazgo SNV/indel relevante; sin cobertura amplia y robusta de fusiones.","Ein negatives SNV/Indel-Profil schließt strukturelle Alterationen nicht aus.":"Un perfil SNV/indel negativo no excluye alteraciones estructurales.","Leberbiopsie mit 50 % Tumor; DNA und RNA ausreichend.":"Biopsia hepática con 50 % de tumor; ADN y ARN suficientes.","Es gibt keinen technischen Grund, die Fusionsfrage offen zu lassen.":"No hay ninguna razón técnica para dejar sin resolver la cuestión de las fusiones.","Copyover-Falle":"Trampa de copyover","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier gehören in neuroonkologische Kontexte und beantworten die CCA-Targetfrage nicht.":"La IHC IDH1-R132H, G-CIMP y los clasificadores de metilación del SNC pertenecen a contextos neurooncológicos y no responden a la pregunta de diana en CCA.","Gleiche Genbezeichnung bedeutet nicht gleiche diagnostische Methode oder biologische Fragestellung.":"El mismo nombre de gen no implica el mismo método diagnóstico ni la misma pregunta biológica.","Adenokarzinom mit desmoplastischem Stroma; klinisch-radiologisch und immunhistologisch mit intrahepatischem CCA vereinbar.":"Adenocarcinoma con estroma desmoplásico; clínica, radiológica e inmunohistológicamente compatible con CCA intrahepático.","DNA-only Vorprofil":"Perfil previo solo de ADN","Kein relevanter IDH1/2-, BRAF-V600- oder ERBB2-Hotspot-Befund; Fusionserfassung unzureichend.":"Sin hallazgo relevante de IDH1/2, BRAF V600 o hotspot ERBB2; cobertura de fusiones insuficiente.","ausreichend für gezielte Fusionsanalyse.":"suficiente para análisis dirigido de fusiones.","Zehn ungefärbte Schnitte verfügbar.":"Hay diez cortes sin teñir disponibles.","DNA und RNA sind ausreichend; die Limitation liegt primär in der Wahl des Assays.":"El ADN y ARN son suficientes; la limitación reside principalmente en la elección del ensayo.","Neuroonkologische IDH-/Methylierungsverfahren sind explizit entitätsfremd.":"Los métodos IDH/metilación de neurooncología son explícitamente inadecuados para esta entidad.","Das TAT-Ziel liegt vor der nächsten Therapieentscheidung.":"El objetivo de TAT es antes de la siguiente decisión terapéutica.","Welche molekulare Kernstrategie ist bei diesem progredienten intrahepatischen Cholangiokarzinom sinnvoll?":"¿Qué estrategia molecular central es adecuada para este colangiocarcinoma intrahepático progresivo?","CCA-spezifisches Molekularprofil plus valide FGFR2-Fusions-/Rearrangementdiagnostik":"Perfil molecular específico de CCA más estudio válido de fusión/reordenamiento FGFR2","IDH1-R132H-IHC plus ZNS-Methylierungsclassifier":"IHC IDH1-R132H más clasificador de metilación del SNC","Keine weitere Diagnostik, weil das alte DNA-Panel negativ war":"Sin más pruebas porque el antiguo panel de ADN fue negativo","MGMT-Promotor-Methylierung":"Metilación del promotor de MGMT","Die klinische Frage verlangt CCA-spezifische molekulare Profilierung mit adäquater Erfassung struktureller Alterationen.":"La pregunta clínica exige un perfil molecular específico de CCA con captación adecuada de alteraciones estructurales.","Wie soll IDH in diesem Fall untersucht/eingeordnet werden?":"¿Cómo debe estudiarse/interpretarse IDH en este caso?","IDH1/2-Sequenzierung im CCA-Panel-/Targetkontext":"Secuenciación IDH1/2 en contexto de panel/diana de CCA","IDH1-R132H-IHC als primärer CCA-Screeningstandard":"IHC IDH1-R132H como estándar primario de cribado en CCA","G-CIMP-Profil als Therapiebiomarker":"Perfil G-CIMP como biomarcador terapéutico","ZNS-Methylierungsclassifier":"Clasificador de metilación del SNC","Die neuroonkologische R132H-IHC/G-CIMP-/Classifier-Logik darf nicht auf das Cholangiokarzinom übertragen werden.":"La lógica R132H IHC/G-CIMP/clasificador de neurooncología no debe trasladarse al colangiocarcinoma.","Das alte DNA-only-Panel ist negativ. Was folgt daraus für FGFR2?":"El antiguo panel solo de ADN es negativo. ¿Qué implica esto para FGFR2?","Eine Fusion/Rearrangement-Frage kann weiterhin offen sein, wenn der Assay diese Alterationsklasse nicht valide abdeckt.":"La cuestión de fusión/reordenamiento puede seguir abierta si el ensayo no cubre válidamente esta clase de alteraciones.","FGFR2 ist sicher ausgeschlossen.":"FGFR2 está definitivamente excluido.","Dann kann nur noch IDH1 relevant sein.":"Entonces solo IDH1 puede seguir siendo relevante.","Strukturelle Alterationen sind beim CCA klinisch nicht relevant.":"Las alteraciones estructurales no son clínicamente relevantes en CCA.","SNV/Indel-negative DNA-Daten sind kein universeller Fusionsausschluss.":"Los datos de ADN negativos para SNV/indel no excluyen universalmente las fusiones.","Planen Sie eine CCA-spezifische molekulare Abklärung für die nächste Therapielinie und entfernen Sie die neuroonkologischen Copyover-Methoden vollständig aus der Entscheidungslogik.":"Planificar un estudio molecular específico de CCA para la siguiente línea y eliminar por completo de la lógica decisional los métodos de copyover neurooncológicos.","Intrahepatischen CCA-Kontext bestätigen.":"Confirmar el contexto de CCA intrahepático.","CCA-spezifisches DNA-Profil für IDH1/2 und weitere relevante Alterationen nutzen.":"Utilizar un perfil de ADN específico de CCA para IDH1/2 y otras alteraciones relevantes.","FGFR2-Fusion/Rearrangement mit einer dafür validierten Methode explizit erfassen.":"Evaluar explícitamente fusión/reordenamiento FGFR2 con un método validado.","DNA-only Negativbefund methodisch begrenzen.":"Limitar metodológicamente la interpretación del resultado negativo solo de ADN.","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier nicht verwenden.":"No utilizar IHC IDH1-R132H, G-CIMP ni clasificador de metilación del SNC.","Validiertes kombiniertes DNA/RNA-Pan-Panel mit sicherer FGFR2-Fusionserfassung.":"Pan-panel combinado ADN/ARN validado con cobertura fiable de fusiones FGFR2.","Gezielte FGFR2-Fusionsdiagnostik plus separates IDH1/2-Assay, wenn ein integriertes CCA-Panel nicht verfügbar ist.":"Estudio dirigido de fusiones FGFR2 más ensayo separado IDH1/2 si no está disponible un panel integrado de CCA.","Fachfremder Copyover; beantwortet weder FGFR2- noch IDH1/2-Targetfrage beim CCA.":"Copyover ajeno; no responde ni a la pregunta FGFR2 ni a la cuestión de diana IDH1/2 en CCA.","IDH1-R132H-IHC als CCA-Standard":"IHC IDH1-R132H como estándar de CCA","Neuroonkologische Screeninglogik wird auf eine andere Entität übertragen.":"La lógica de cribado de neurooncología se traslada a otra entidad.","DNA-negativ = keine Targetoption":"ADN negativo = sin opción dirigida","Strukturelle Alterationen können methodisch offen bleiben.":"Las alteraciones estructurales pueden quedar sin resolver por limitaciones metodológicas.","FGFR2::BICC1 trotz 'kein targetierbarer Befund'":"FGFR2::BICC1 pese a «sin hallazgo dirigible»","Die CCA-spezifische DNA-Analyse bleibt für IDH1/2, BRAF und ERBB2 ohne relevanten Treffer. Die gezielte Fusionsdiagnostik detektiert jedoch eine FGFR2::BICC1-Fusion. Der alte Satz 'kein targetierbarer Befund' war damit nicht biologisch falsch, sondern methodisch zu weit formuliert.":"El análisis de ADN específico de CCA sigue sin hallazgos relevantes en IDH1/2, BRAF y ERBB2. Sin embargo, el estudio dirigido de fusiones detecta una fusión FGFR2::BICC1. Por tanto, la frase antigua «sin hallazgo dirigible» no era biológicamente falsa, sino metodológicamente demasiado amplia.","Die zentrale Lektion ist zweifach: strukturelle Alterationen brauchen passende Assays, und identische Genbegriffe dürfen nicht entitätsfremde Diagnostikpfade triggern.":"La lección central es doble: las alteraciones estructurales requieren ensayos adecuados y nombres génicos idénticos no deben activar rutas diagnósticas impropias de la entidad.","CCA-Profil + Fusion":"Perfil CCA + fusión","FGFR2::BICC1-Fusion nachweisbar; IDH1/2 wildtyp; kein BRAF-V600-/ERBB2-Hotspot-Befund.":"Se detecta fusión FGFR2::BICC1; IDH1/2 wild type; sin hallazgo BRAF V600/hotspot ERBB2.","Vollständige, entitätsspezifische Profilierung mit klinisch relevanter Targetalteration.":"Perfil completo y específico de la entidad con una alteración dirigible clínicamente relevante.","DNA-only wiederholt":"Repetición de ADN solo","Kein relevanter SNV/Indel-Treffer; FGFR2-Fusionsstatus bleibt offen.":"Sin hallazgo SNV/indel relevante; el estado de fusión FGFR2 sigue sin resolverse.","Der alte methodische blinde Fleck wurde reproduziert.":"Se reprodujo el antiguo punto ciego metodológico.","Neuroonkologischer IDH-Pfad":"Ruta IDH de neurooncología","IDH1-R132H-IHC/Methylierungsclassifier werden angefordert; die eigentliche CCA-Targetfrage bleibt ungelöst.":"Se solicitan IHC IDH1-R132H/clasificador de metilación; la verdadera pregunta de diana en CCA sigue sin resolverse.","Klarer Cross-Template-Fehler.":"Error claro entre plantillas.","FGFR2-Fusion positiv":"Fusión FGFR2 positiva","Target-Relevanz und passende Therapielinie im hepatobiliären MTB diskutieren.":"Discutir la relevancia de la diana y la línea terapéutica adecuada en el MTB hepatobiliar.","Der Befund verändert die nächste Linienplanung.":"El hallazgo cambia la planificación de la siguiente línea.","FGFR2 negativ, DNA-Profil ohne Target":"FGFR2 negativo, perfil de ADN sin diana","Weitere im validierten Panel erfasste Alterationsklassen und Studienoptionen prüfen.":"Revisar otras clases de alteraciones cubiertas por el panel validado y opciones de ensayo clínico.","Negativbefund bleibt methodisch transparent.":"El resultado negativo mantiene transparencia metodológica.","Nur CNS-IDH/Methylom gewählt":"Solo se seleccionó IDH/metiloma del SNC","Anforderung korrigieren und CCA-spezifische Diagnostik durchführen.":"Corregir la solicitud y realizar diagnóstico específico de CCA.","Material/TAT-Verlust, aber fachlich rettbarer Fall.":"Pérdida de material/TAT, pero caso clínicamente rescatable.","Beim iCCA ist molekulare Profilierung Teil moderner Therapieplanung.":"En iCCA, el perfil molecular forma parte de la planificación terapéutica moderna.","FGFR2-Fusionen sind strukturelle Alterationen und benötigen passende Assayabdeckung.":"Las fusiones FGFR2 son alteraciones estructurales y requieren una cobertura de ensayo adecuada.","IDH1/2 im Cholangiokarzinom ist nicht dasselbe diagnostische Problem wie IDH/G-CIMP im Gliom.":"IDH1/2 en colangiocarcinoma no es el mismo problema diagnóstico que IDH/G-CIMP en glioma.","Cross-Template-Copyover ist ein reales Qualitätsrisiko in standardisierten Fallbibliotheken und Labor-Workflows.":"El copyover entre plantillas es un riesgo real de calidad en bibliotecas de casos estandarizadas y flujos de laboratorio.","CCA-spezifisches Molekularprofil plus explizite FGFR2-Fusions-/Rearrangementdiagnostik. Ergebnis: FGFR2::BICC1-Fusion, IDH1/2 wildtyp. Die bisherigen neuroonkologischen IDH1-R132H-/G-CIMP-/Methylierungsclassifier-Elemente sind fachfremd und werden vollständig entfernt.":"Perfil molecular específico de CCA más estudio explícito de fusión/reordenamiento FGFR2. Resultado: fusión FGFR2::BICC1, IDH1/2 wild type. Los elementos previos de neurooncología IDH1-R132H/G-CIMP/clasificador de metilación son inadecuados y se eliminan por completo.","iCCA-Kontext erkannt":"Contexto iCCA reconocido","FGFR2 strukturell korrekt getestet":"FGFR2 estudiado correctamente como alteración estructural","IDH1/2 entitätsspezifisch eingeordnet":"IDH1/2 interpretado de forma específica de la entidad","CNS-Copyover aktiv verworfen":"Copyover del SNC rechazado activamente","Wann reicht ein DNA-Panel für Fusionen, wann nicht?":"¿Cuándo es suficiente un panel de ADN para fusiones y cuándo no?","Welche weiteren Alterationsklassen sollten CCA-Panels abdecken?":"¿Qué otras clases de alteraciones deberían cubrir los paneles de CCA?","Wie können Template-Bibliotheken gegen Cross-Entity-Copyover QA-gesichert werden?":"¿Cómo pueden protegerse mediante QA las bibliotecas de plantillas frente al copyover entre entidades?","FGFR2::BICC1 nach DNA-only Negativbefund":"FGFR2::BICC1 tras un resultado negativo solo de ADN","Strukturelle Targets brauchen passende Methoden":"Las dianas estructurales requieren métodos adecuados","DNA-negativ → Assaycheck → CCA-Profil + Fusion → FGFR2":"ADN negativo → revisión del ensayo → perfil CCA + fusión → FGFR2","Rechte Kolonkarzinom-Metastase mit BRAF V600E → Prognose, MSI-Kontext, Therapieoption":"Metástasis de cáncer de colon derecho con BRAF V600E → pronóstico, contexto MSI, opción terapéutica","Rechte Kolonkarzinom-Metastase mit…":"Metástasis de cáncer de colon derecho con…","Viszeralonkologie / Molekulares Tumorboard":"Oncología visceral / Comité Molecular de Tumores","72-jährige Patientin mit rechtsseitigem Kolonkarzinom und synchronen Leber- und Peritonealmetastasen.":"Mujer de 72 años con cáncer de colon derecho y metástasis hepáticas y peritoneales sincrónicas.","Im Tumorprofil wurde BRAF p.V600E nachgewiesen. Welche prognostische und therapeutische Bedeutung hat der Befund im CRC – und was muss zusätzlich über MMR/MSI bekannt sein?":"Se detectó BRAF p.V600E en el perfil tumoral. ¿Qué relevancia pronóstica y terapéutica tiene en CRC y qué más debe conocerse sobre MMR/MSI?","Die Erstlinienstrategie soll im MTB innerhalb weniger Tage festgelegt werden.":"La estrategia de primera línea debe definirse en el MTB en pocos días.","Coecum/Colon ascendens, rechtsseitig.":"Ciego/colon ascendente, lado derecho.","Metastasiert mit Leber- und Peritonealbefall; ECOG 1.":"Metastásico con afectación hepática y peritoneal; ECOG 1.","BRAF V600E wird reflexartig wie beim Melanom interpretiert oder mit MSI-H gleichgesetzt. Beides ist im CRC falsch bzw. unvollständig.":"BRAF V600E se interpreta de forma refleja como en melanoma o se equipara con MSI-H. Ambas cosas son incorrectas o incompletas en CRC.","Mäßig bis gering differenziertes kolorektales Adenokarzinom mit fokal muzinöser Morphologie.":"Adenocarcinoma colorrectal moderada a pobremente diferenciado con morfología mucinosa focal.","Lineage":"Linaje","CDX2/SATB2 positiv; Morphologie und Klinik vereinbar mit kolorektalem Primarius.":"CDX2/SATB2 positivos; morfología y clínica compatibles con primario colorrectal.","Molekularer Vorbefund":"Resultado molecular previo","BRAF p.V600E in einer schnellen Einzeltestung nachgewiesen.":"BRAF p.V600E detectado en una prueba rápida de gen único.","Ist der Tumor dMMR/MSI-H oder pMMR/MSS, und wie muss die BRAF-Alteration CRC-spezifisch therapeutisch eingeordnet werden?":"¿Es el tumor dMMR/MSI-H o pMMR/MSS y cómo debe interpretarse terapéuticamente la alteración BRAF de forma específica para CRC?","FFPE-Resektat, Block C6 mit vitalem invasivem Tumor.":"Pieza de resección FFPE, bloque C6 con tumor invasivo viable.","ca. 55 %, gut geeignet für DNA-basierte Analysen.":"aprox. 55 %, bien adecuado para análisis basados en ADN.","DNA-Qualität gut; MMR-IHC technisch gut beurteilbar.":"Calidad de ADN buena; IHC MMR técnicamente bien evaluable.","Melanom-spezifische BRAF-Methoden oder Therapiealgorithmen beantworten die CRC-Frage nicht.":"Los métodos BRAF o algoritmos terapéuticos específicos de melanoma no responden a la cuestión de CRC.","BRAF-V600E im CRC-Kontext":"BRAF V600E en contexto CRC","MMR-IHC":"IHC MMR","MSI-Testung":"Estudio MSI","BRAF V600E":"BRAF V600E","BRAF p.V600E nachweisbar. Der Befund ist im metastasierten CRC prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden – nicht nach dem Melanom-Algorithmus.":"Se detecta BRAF p.V600E. El hallazgo es pronóstica y terapéuticamente relevante en CRC metastásico, pero debe interpretarse según evidencia específica de CRC, no con un algoritmo de melanoma.","Erweiterter RAS-Status":"Estado RAS ampliado","KRAS/NRAS Wildtyp. Der BRAF-V600E-Befund bleibt der dominante MAPK-Treiberkontext.":"KRAS/NRAS wild type. El hallazgo BRAF V600E sigue siendo el contexto driver MAPK dominante.","Intakte nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expresión nuclear conservada de MLH1, PMS2, MSH2 y MSH6: pMMR.","MSI":"MSI","MSS / kein MSI-H. BRAF V600E ist damit gerade nicht automatisch mit MSI-H gleichzusetzen.":"MSS / sin MSI-H. Por tanto, BRAF V600E no equivale automáticamente a MSI-H.","MLH1-Methylierung":"Metilación MLH1","Bei erhaltener MLH1/PMS2-Expression besteht in diesem Fall keine primäre Reflexindikation; die Zusatzanalyse liefert keinen entscheidungsrelevanten Mehrwert.":"Con expresión conservada de MLH1/PMS2 no existe indicación refleja primaria en este caso; el análisis adicional no aporta un beneficio relevante para la decisión.","Tumoranteil und DNA-Qualität ausreichend; MMR-IHC auswertbar.":"Fracción tumoral y calidad de ADN suficientes; IHC MMR evaluable.","BRAF p.V600E liegt in einem rechtsseitigen, pMMR/MSS metastasierten CRC vor. Der Befund ist prognostisch ungünstig und eröffnet einen CRC-spezifischen BRAF-gerichteten Therapiekontext mit EGFR-Blockade nach aktueller Therapielinie/Leitlinie. Eine Melanom-artige BRAF/MEK-Übertragung ist nicht angemessen; BRAF V600E bedeutet außerdem nicht automatisch MSI-H.":"BRAF p.V600E está presente en un CRC metastásico derecho, pMMR/MSS. El hallazgo es pronósticamente desfavorable y abre un contexto terapéutico específico de CRC con diana BRAF y bloqueo de EGFR según la línea/guía vigente. No es apropiado trasladar un esquema BRAF/MEK tipo melanoma; BRAF V600E tampoco significa automáticamente MSI-H.","Teilbefund: BRAF V600E ist bekannt, aber ohne MMR/MSI-Kontext bleibt die molekulare Einordnung unvollständig. Therapie- und Prognoseaussagen dürfen nicht aus einem Melanom-Template übernommen werden.":"Hallazgo parcial: BRAF V600E es conocido, pero sin contexto MMR/MSI la clasificación molecular sigue incompleta. Las afirmaciones terapéuticas y pronósticas no deben copiarse de una plantilla de melanoma.","BRAF V600E als CRC-spezifischen prognostisch/therapeutisch relevanten Befund benennen":"Indicar BRAF V600E como hallazgo específico de CRC con relevancia pronóstica y terapéutica","BRAF V600E nicht mit MSI-H gleichsetzen; pMMR/MSS separat kommunizieren":"No equiparar BRAF V600E con MSI-H; comunicar pMMR/MSS por separado","BRAF-gerichtete Strategie im CRC mit EGFR-Blockade und aktueller Therapielinie verknüpfen, nicht mit einem Melanom-Schema":"Vincular la estrategia dirigida a BRAF en CRC con bloqueo de EGFR y la línea terapéutica actual, no con un esquema de melanoma","Entitätsspezifische Evidenz und aktuelle Leitlinien-/Zulassungssituation sprachlich sauber begrenzen":"Formular la evidencia específica de la entidad y la situación actual de guías/aprobación con limitaciones adecuadas","Optimale Lösung: BRAF V600E, RAS-Kontext und MMR/MSI gemeinsam einordnen; der Tumor ist pMMR/MSS und benötigt eine CRC-spezifische BRAF-/EGFR-Therapielogik statt eines Melanom-Copyovers.":"Solución óptima: interpretar conjuntamente BRAF V600E, contexto RAS y MMR/MSI; el tumor es pMMR/MSS y requiere una lógica terapéutica BRAF/EGFR específica de CRC, no un copyover de melanoma.","CRC":"CRC","mCRC":"mCRC","pMMR":"pMMR","MSS":"MSS","anti-EGFR":"anti-EGFR","Targeted Therapy":"Terapia dirigida","BRAF V600E im rechten mCRC: CRC-Biologie statt Melanom-Copyover":"BRAF V600E en mCRC derecho: biología de CRC en lugar de copyover de melanoma","Molekularpathologie / Viszeralonkologie / MTB":"Patología molecular / Oncología visceral / MTB","BRAF V600E beim mCRC prognostisch und therapeutisch korrekt einordnen.":"Interpretar correctamente BRAF V600E en términos pronósticos y terapéuticos en mCRC.","BRAF V600E nicht automatisch mit MSI-H gleichsetzen, sondern MMR/MSI separat prüfen.":"No equiparar automáticamente BRAF V600E con MSI-H; evaluar MMR/MSI por separado.","Die CRC-spezifische BRAF-Therapielogik von Melanom-Algorithmen abgrenzen.":"Distinguir la lógica terapéutica de BRAF específica de CRC de los algoritmos de melanoma.","Rechtsseitigkeit, pMMR/MSS und BRAF-Kontext in einer integrierten MTB-Aussage zusammenführen.":"Integrar lateralidad, pMMR/MSS y contexto BRAF en una única conclusión del MTB.","Im MTB fällt sofort der rote Marker 'BRAF V600E' ins Auge. Jemand schlägt vor, den Fall wie ein BRAF-mutiertes Melanom zu behandeln; ein anderer sagt, rechtsseitig plus BRAF sei wahrscheinlich ohnehin MSI-high. Beides klingt auf den ersten Blick plausibel – und beides greift zu kurz.":"En el MTB, el marcador rojo «BRAF V600E» llama inmediatamente la atención. Alguien propone tratar el caso como un melanoma BRAF mutado; otro dice que, al ser derecho y BRAF, probablemente ya sea MSI-high. Ambas ideas parecen plausibles a primera vista, y ambas se quedan cortas.","72-jährige Patientin mit rechtsseitigem metastasiertem CRC. BRAF p.V600E wurde bereits nachgewiesen. Die Lernaufgabe besteht darin, die Mutation entitätsspezifisch zu interpretieren, MMR/MSI unabhängig zu klären und aus Prognose, Immuntherapie- und BRAF-Targetkontext eine belastbare MTB-Empfehlung zu formulieren.":"Mujer de 72 años con CRC metastásico derecho. BRAF p.V600E ya es conocido. La tarea es interpretar la mutación de forma específica de la entidad, aclarar MMR/MSI de manera independiente y formular una recomendación sólida del MTB integrando pronóstico, inmunoterapia y contexto de diana BRAF.","Tumorbiologie":"Biología tumoral","Rechtsseitiges metastasiertes CRC mit BRAF V600E.":"CRC metastásico derecho con BRAF V600E.","BRAF ist ein starker biologischer Kontextmarker, aber nicht die gesamte Therapieentscheidung.":"BRAF es un potente marcador contextual biológico, pero no constituye toda la decisión terapéutica.","Zu Beginn noch unbekannt.":"Desconocido inicialmente.","BRAF V600E und MSI-H sind assoziiert, aber nicht synonym.":"BRAF V600E y MSI-H están asociados, pero no son sinónimos.","Therapiekontext":"Contexto terapéutico","Erstlinienentscheidung steht an.":"Decisión de primera línea pendiente.","BRAF-Targeting im CRC folgt einer anderen Logik als beim Melanom.":"La estrategia dirigida a BRAF en CRC sigue una lógica distinta a la del melanoma.","Schneller BRAF-Befund":"Resultado rápido de BRAF","BRAF p.V600E positiv.":"BRAF p.V600E positivo.","Rechtsseitiges kolorektales Adenokarzinom, metastasiert.":"Adenocarcinoma colorrectal derecho, metastásico.","Material ausreichend für MMR-IHC und MSI-Testung.":"Material suficiente para IHC MMR y estudio MSI.","Zehn Schnitte reichen für eine fokussierte CRC-Diagnostik.":"Diez cortes son suficientes para un diagnóstico focalizado de CRC.","Melanom-spezifische Zusatztests sind methodisch und didaktisch Low Value.":"Las pruebas adicionales específicas de melanoma tienen bajo valor metodológico y didáctico.","MMR/MSI muss trotz bekanntem BRAF-Befund eigenständig beantwortet werden.":"MMR/MSI debe resolverse de forma independiente pese al resultado BRAF conocido.","Welche Aussage zum BRAF-V600E-Befund ist im mCRC am treffendsten?":"¿Qué afirmación sobre BRAF V600E en mCRC es la más correcta?","BRAF V600E ist prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden; ein Melanom-Algorithmus darf nicht übertragen werden.":"BRAF V600E es relevante pronóstica y terapéuticamente, pero debe interpretarse según evidencia específica de CRC; no debe trasladarse un algoritmo de melanoma.","BRAF V600E bedeutet unabhängig von der Entität denselben BRAF/MEK-Algorithmus wie beim Melanom.":"BRAF V600E implica el mismo algoritmo BRAF/MEK que en melanoma, independientemente de la entidad.","BRAF V600E ist beim CRC nur prognostisch, nicht therapeutisch relevant.":"En CRC, BRAF V600E es solo pronóstico, no terapéuticamente relevante.","Bei rechtsseitigem CRC spielt BRAF keine Rolle.":"En CRC derecho, BRAF no tiene relevancia.","Entitätsspezifische Biologie und Therapiedaten sind entscheidend.":"La biología específica de la entidad y los datos terapéuticos son decisivos.","BRAF V600E ist nachgewiesen. Was folgt für MMR/MSI?":"Se detecta BRAF V600E. ¿Qué implica para MMR/MSI?","MMR/MSI weiterhin separat bestimmen; BRAF V600E beweist weder dMMR noch MSI-H.":"Seguir evaluando MMR/MSI por separado; BRAF V600E no demuestra ni dMMR ni MSI-H.","BRAF V600E reicht als Surrogat für MSI-H.":"BRAF V600E es suficiente como sustituto de MSI-H.","MMR/MSI ist bei BRAF-mutiertem mCRC therapeutisch bedeutungslos.":"MMR/MSI es terapéuticamente irrelevante en mCRC con BRAF mutado.","PD-L1 ersetzt die MSI-Testung.":"PD-L1 sustituye el estudio MSI.","Die MMR/MSI-Ebene besitzt eine unabhängige prädiktive und ggf. hereditäre Bedeutung.":"El nivel MMR/MSI tiene una relevancia predictiva independiente y potencialmente hereditaria.","Welche Targetlogik ist für BRAF V600E im mCRC korrekt?":"¿Qué lógica de diana es correcta para BRAF V600E en mCRC?","CRC-spezifische BRAF-gerichtete Strategie unter Einbezug der EGFR-Achse gemäß aktueller Therapielinie/Leitlinie.":"Estrategia dirigida a BRAF específica de CRC incorporando el eje EGFR según la línea terapéutica/guía actual.","BRAF-Inhibitor allein ist die logische Standardstrategie.":"Un inhibidor de BRAF solo es la estrategia estándar lógica.","BRAF/MEK wie beim Melanom ohne CRC-spezifischen Kontext.":"BRAF/MEK como en melanoma sin contexto específico de CRC.","BRAF V600E ist nicht targetierbar.":"BRAF V600E no es dirigible.","Beim CRC ist die EGFR-Rückkopplung/Signalachse Teil der therapeutischen BRAF-Logik.":"En CRC, la retroalimentación/señalización de EGFR forma parte de la lógica terapéutica de BRAF.","Interpretieren Sie BRAF V600E in einem rechtsseitigen mCRC und vervollständigen Sie MMR/MSI so, dass Prognose, Immuntherapie- und BRAF-Targetkontext sauber getrennt und integriert werden.":"Interpretar BRAF V600E en un mCRC derecho y completar MMR/MSI de modo que pronóstico, inmunoterapia y contexto de diana BRAF queden claramente separados e integrados.","BRAF-V600E-Befund entitätsspezifisch bestätigen/einordnen.":"Confirmar/clasificar el hallazgo BRAF V600E de forma específica de la entidad.","MMR-IHC und MSI unabhängig bestimmen.":"Determinar IHC MMR y MSI de forma independiente.","Ergebnis pMMR/MSS explizit kommunizieren.":"Comunicar explícitamente el resultado pMMR/MSS.","BRAF V600E als prognostisch ungünstigen und therapeutisch relevanten CRC-Kontext berichten.":"Informar BRAF V600E como contexto de CRC de mal pronóstico y relevancia terapéutica.","Keinen Melanom-Algorithmus übertragen; aktuelle CRC-spezifische BRAF/EGFR-Strategie heranziehen.":"No trasladar un algoritmo de melanoma; utilizar la estrategia BRAF/EGFR específica de CRC vigente.","Kolon-NGS-Panel zur gemeinsamen Erfassung von BRAF/RAS plus separate MMR-IHC/MSI.":"Panel NGS de colon para detección conjunta de BRAF/RAS más IHC MMR/MSI por separado.","Breiteres validiertes Pan-Panel, sofern BRAF und MSI zuverlässig abgedeckt und die MMR-IHC sinnvoll ergänzt werden.":"Pan-panel validado más amplio, siempre que BRAF y MSI estén cubiertos de forma fiable y se añada adecuadamente IHC MMR.","Melanom-BRAF-Template":"Plantilla BRAF de melanoma","Gleiche Mutation bedeutet nicht gleichen Therapiealgorithmus über Tumorentitäten hinweg.":"La misma mutación no implica el mismo algoritmo terapéutico en distintas entidades tumorales.","BRAF = MSI-H":"BRAF = MSI-H","Assoziation ist kein Ersatz für MMR/MSI-Diagnostik.":"La asociación no sustituye el estudio MMR/MSI.","BRAF allein befundet":"Solo se informa BRAF","Der Immuntherapie-/MMR-Kontext bleibt offen.":"El contexto de inmunoterapia/MMR queda sin resolver.","BRAF V600E – aber pMMR/MSS":"BRAF V600E, pero pMMR/MSS","Die MMR-IHC ist vollständig erhalten und die MSI-Testung zeigt MSS. Der rechtsseitige BRAF-V600E-Tumor ist damit gerade kein MSI-H-Fall. Gleichzeitig wird klar: Der BRAF-Befund führt nicht in einen Melanom-Pfad, sondern in eine CRC-spezifische BRAF-/EGFR-Therapielogik.":"La IHC MMR está completamente conservada y el estudio MSI muestra MSS. Por tanto, el tumor derecho BRAF V600E no es un caso MSI-H. Al mismo tiempo queda claro que el hallazgo BRAF no conduce a una vía de melanoma, sino a una lógica terapéutica BRAF/EGFR específica de CRC.","Der Fall löst zwei häufige Kurzschlüsse gleichzeitig auf: BRAF ist weder ein MSI-Surrogat noch eine entitätsunabhängige Therapieschablone.":"El caso resuelve dos atajos frecuentes a la vez: BRAF no es ni un sustituto de MSI ni una plantilla terapéutica independiente de la entidad.","CRC-spezifisch vollständig":"Completo y específico de CRC","BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Prognostisch ungünstiger BRAF-Kontext; CRC-spezifische BRAF-gerichtete Strategie mit EGFR-Blockade nach aktueller Linie/Leitlinie diskutieren.":"BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Contexto BRAF de mal pronóstico; discutir estrategia dirigida a BRAF específica de CRC con bloqueo de EGFR según línea/guía vigente.","Entität, MSI und Targetlogik korrekt integriert.":"Entidad, MSI y lógica de diana correctamente integrados.","Nur BRAF":"Solo BRAF","BRAF V600E ist bekannt, MMR/MSI bleibt offen.":"BRAF V600E es conocido; MMR/MSI sigue sin resolverse.","Therapeutisch und biologisch unvollständig.":"Incompleto terapéutica y biológicamente.","Melanom-Copyover":"Copyover de melanoma","BRAF/MEK-Logik wird ohne CRC-spezifischen Kontext übertragen.":"La lógica BRAF/MEK se traslada sin contexto específico de CRC.","Cross-Entity-Fehlinterpretation.":"Interpretación errónea entre entidades.","pMMR/MSS bestätigt":"pMMR/MSS confirmado","BRAF- und Chemotherapie-/EGFR-Kontext nach aktueller Linie im MTB diskutieren.":"Discutir el contexto BRAF y quimioterapia/EGFR en el MTB según la línea terapéutica actual.","Der Fall bleibt Targeted-Therapy-orientiert, ohne MSI-H-IO-Pfad.":"El caso sigue orientado a terapia dirigida, sin una vía IO por MSI-H.","unerwartet dMMR/MSI-H":"dMMR/MSI-H inesperado","Immuntherapie- und Lynch/sporadisch-Kontext zusätzlich priorisieren.":"Priorizar además inmunoterapia y contexto Lynch/esporádico.","Therapiepriorisierung verändert sich.":"Cambia la priorización terapéutica.","BRAF V600E ist im CRC entitätsspezifisch zu interpretieren.":"BRAF V600E debe interpretarse de forma específica de la entidad en CRC.","BRAF V600E und MSI-H sind nicht gleichbedeutend.":"BRAF V600E y MSI-H no son equivalentes.","MMR/MSI bleibt ein unabhängiger Biomarkerblock.":"MMR/MSI sigue siendo un bloque independiente de biomarcadores.","BRAF-gerichtete Therapie im CRC bindet die EGFR-Achse ein und darf nicht aus dem Melanom kopiert werden.":"El tratamiento dirigido a BRAF en CRC incorpora el eje EGFR y no debe copiarse del melanoma.","BRAF V600E + pMMR/MSS im rechtsseitigen mCRC. Kein Melanom-Algorithmus; CRC-spezifische BRAF-/EGFR-Strategie nach aktueller Therapielinie. MMR/MSI separat bestimmt und korrekt negativ eingeordnet.":"BRAF V600E + pMMR/MSS en mCRC derecho. Sin algoritmo de melanoma; estrategia BRAF/EGFR específica de CRC según línea terapéutica actual. MMR/MSI evaluado por separado e interpretado correctamente como negativo.","Entitätsspezifische BRAF-Interpretation":"Interpretación BRAF específica de la entidad","MMR/MSI unabhängig geprüft":"MMR/MSI evaluado independientemente","kein Melanom-Copyover":"sin copyover de melanoma","Prognose vs. Prädiktion getrennt":"Pronóstico vs. predicción separados","Warum ist BRAF V600E kein MSI-Surrogat?":"¿Por qué BRAF V600E no es un sustituto de MSI?","Warum reicht BRAF-Hemmung allein im CRC biologisch/klinisch nicht als Übertrag aus dem Melanom?":"¿Por qué la inhibición de BRAF sola no puede trasladarse biológica/clínicamente del melanoma al CRC?","Welche Rolle spielt die Tumorlokalisation zusätzlich?":"¿Qué papel adicional desempeña la lateralidad tumoral?","DE master":"Master DE","BRAF V600E, aber pMMR/MSS":"BRAF V600E, pero pMMR/MSS","Mutation ist entitätsspezifisch zu interpretieren":"La mutación debe interpretarse de forma específica de la entidad","BRAF+ → MMR/MSI separat → pMMR/MSS → CRC-spezifische BRAF/EGFR-Logik":"BRAF+ → evaluar MMR/MSI por separado → pMMR/MSS → lógica BRAF/EGFR específica de CRC","Polypenrest statt invasivem Tumor eingeschickt → Befundbar oder neues Material anfordern?":"Resto de pólipo enviado en lugar de tumor invasivo → ¿Informable o solicitar nuevo material?","Polypenrest statt invasivem Tumor …":"Resto de pólipo en lugar de tumor invasivo …","Viszeralonkologie / Molekularpathologie":"Oncología visceral / Patología molecular","64-jähriger Patient mit metastasiertem Sigma-Karzinom; vor Beginn der Systemtherapie werden RAS/BRAF und MMR/MSI angefordert.":"Paciente de 64 años con carcinoma sigmoide metastásico; se solicitan RAS/BRAF y MMR/MSI antes del tratamiento sistémico.","Der eingesandte Block soll 'repräsentatives Tumorgewebe' enthalten. Ist das Material tatsächlich für die prädiktive Diagnostik geeignet?":"Se supone que el bloque enviado contiene «tejido tumoral representativo». ¿Es realmente adecuado para diagnóstico predictivo?","MTB in vier Tagen; die Onkologie bittet ausdrücklich um eine schnelle Freigabe.":"MTB en cuatro días; oncología solicita expresamente una liberación rápida.","Vorgeschichte":"Antecedentes","Zunächst endoskopische Polypektomie, anschließend onkologische Sigmaresektion mit invasivem Adenokarzinom; inzwischen Lebermetastasen.":"Inicialmente polipectomía endoscópica, seguida de resección oncológica de sigma con adenocarcinoma invasivo; ahora metástasis hepáticas.","Anforderung":"Solicitud","Auf dem Molekularschein steht Block 'A1'. Im Pathologiesystem existieren jedoch sowohl Polypektomie A1 als auch Resektionsblock B7.":"En la solicitud molecular figura el bloque «A1». Sin embargo, en el sistema de patología existen tanto la polipectomía A1 como el bloque de resección B7.","Ein automatisches 'Material vorhanden → testen' wäre schnell, könnte aber die falsche Läsion analysieren.":"Un enfoque automático «material disponible → analizar» sería rápido, pero podría estudiar la lesión equivocada.","Technisch erfolgreiche Molekulardiagnostik ist nicht automatisch klinisch valide, wenn das untersuchte Gewebe die Fragestellung nicht repräsentiert.":"Un diagnóstico molecular técnicamente exitoso no es automáticamente válido clínicamente si el tejido analizado no representa la pregunta clínica.","HE-Reevaluation des eingesandten Blocks":"Reevaluación H&E del bloque enviado","Tubulovillöses Adenom mit hochgradiger intraepithelialer Neoplasie; kein sicher invasives Karzinom im eingesandten Material.":"Adenoma tubulovelloso con neoplasia intraepitelial de alto grado; sin carcinoma invasivo seguro en el material enviado.","Diskrepanz":"Discrepancia","Die klinische Anforderung lautet metastasiertes CRC, der ausgewählte Block repräsentiert jedoch nur den früheren Polypenrest.":"La solicitud clínica es para CRC metastásico, pero el bloque seleccionado representa solo el resto del pólipo previo.","Verfügbarer Alternativblock":"Bloque alternativo disponible","Im Archiv ist Resektionsblock B7 mit invasivem Adenokarzinom und ca. 60 % Tumor dokumentiert.":"En el archivo consta el bloque de resección B7 con adenocarcinoma invasivo y aprox. 60 % de tumor.","Darf der Polypenblock trotzdem molekular befundet werden oder muss die Analyse gestoppt und repräsentatives invasives Tumormaterial angefordert werden?":"¿Puede informarse molecularmente el bloque del pólipo o debe detenerse el análisis y solicitar material representativo de tumor invasivo?","Eingesandter Block":"Bloque enviado","Polypektomie A1, adenomatöses Gewebe ohne sichere Invasion.":"Polipectomía A1, tejido adenomatoso sin invasión segura.","Tumoranteil für die klinische Fragestellung":"Fracción tumoral para la pregunta clínica","0 % sicher invasives Karzinom.":"0 % de carcinoma invasivo seguro.","Technische DNA-Qualität":"Calidad técnica del ADN","gut – genau das macht die Falle gefährlich.":"buena, precisamente lo que hace peligrosa la trampa.","Archivhinweis":"Nota de archivo","Resektionsblock B7 ist verfügbar und enthält repräsentatives invasives Karzinom.":"El bloque de resección B7 está disponible y contiene carcinoma invasivo representativo.","Ein molekular technisch plausibler Befund aus dem Polypenrest darf nicht als Biomarkerbefund des metastasierten invasiven Karzinoms ausgegeben werden.":"Un resultado molecular técnicamente plausible del resto del pólipo no debe emitirse como resultado de biomarcadores del carcinoma invasivo metastásico.","Materialidentität / HE-Reevaluation":"Identidad del material / reevaluación H&E","Repräsentatives invasives Tumormaterial anfordern":"Solicitar material representativo de tumor invasivo","HE-Reevaluation":"Reevaluación H&E","Im eingesandten Block findet sich adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Das Material repräsentiert die klinische Fragestellung nicht.":"El bloque enviado contiene tejido adenomatoso con displasia de alto grado, pero sin carcinoma invasivo seguro. El material no representa la pregunta clínica.","Neues / korrektes Tumormaterial":"Material tumoral nuevo / correcto","Resektionsblock B7 wird nachgefordert: invasives kolorektales Adenokarzinom, ca. 60 % Tumoranteil, für prädiktive Molekulardiagnostik geeignet.":"Se solicita el bloque de resección B7: adenocarcinoma colorrectal invasivo, aprox. 60 % de fracción tumoral, adecuado para diagnóstico molecular predictivo.","MMR/MSI auf dem falschen Block":"MMR/MSI en el bloque equivocado","Die Untersuchung kann technisch auswertbar sein, beantwortet aber am adenomatösen Polypenrest die Biomarkerfrage des invasiven/metastasierten Karzinoms nicht belastbar. Keine klinische Freigabe als Tumorbefund.":"La prueba puede ser técnicamente evaluable, pero en el resto adenomatoso del pólipo no responde de forma fiable a la pregunta de biomarcadores del carcinoma invasivo/metastásico. No liberarla clínicamente como resultado tumoral.","NGS/RAS/BRAF auf dem falschen Block":"NGS/RAS/BRAF en el bloque equivocado","Technisch plausibler Befund aus adenomatösem Gewebe – z. B. APC-Alteration bei fehlendem RAS/BRAF-Nachweis. Dieser Befund darf nicht als prädiktiver Status des invasiven/metastasierten CRC interpretiert werden.":"Hallazgo técnicamente plausible en tejido adenomatoso, p. ej. alteración APC sin RAS/BRAF detectado. No debe interpretarse como estado predictivo del CRC invasivo/metastásico.","Präanalytik":"Preanalítica","Anforderung, Blockbezeichnung und Histologie sind diskordant; vor Freigabe muss die Probenidentität bzw. Repräsentativität geklärt werden.":"La solicitud, la identificación del bloque y la histología son discordantes; la identidad/representatividad de la muestra debe aclararse antes de liberar el resultado.","Der eingesandte Polypenblock ist für die prädiktive Diagnostik des metastasierten invasiven CRC nicht geeignet. Die Analyse muss für diese klinische Fragestellung gestoppt bzw. nicht freigegeben und repräsentatives invasives Tumormaterial angefordert werden. Ein technisch erfolgreicher Befund aus dem falschen Gewebe wäre klinisch irreführend.":"El bloque de pólipo enviado no es adecuado para diagnóstico predictivo del CRC invasivo metastásico. El análisis debe detenerse/no liberarse para esta pregunta clínica y solicitarse material representativo de tumor invasivo. Un resultado técnicamente exitoso del tejido equivocado sería clínicamente engañoso.","Teilbefund: Ohne HE-Reevaluation und Abgleich der Blockidentität bleibt unklar, ob das untersuchte Material den invasiven Tumor repräsentiert. Molekulare Ergebnisse dürfen nicht allein aufgrund technischer QC freigegeben werden.":"Hallazgo parcial: sin reevaluación H&E y comprobación de la identidad del bloque sigue sin saberse si el material estudiado representa el tumor invasivo. Los resultados moleculares no deben liberarse basándose solo en QC técnico.","Falsches/nicht repräsentatives Material als primäres Problem erkennen":"Reconocer el material erróneo/no representativo como problema primario","Molekulare Freigabe stoppen bzw. nicht als invasiven Tumor befundet ausgeben":"Detener la liberación molecular o no emitirla como resultado de tumor invasivo","Diskrepanz und Grund der Nachforderung transparent mit Klinik/Pathologie kommunizieren":"Comunicar de forma transparente la discrepancia y el motivo de solicitar nuevo material con clínica/patología","Technische Validität klar von klinischer Validität unterscheiden":"Distinguir claramente validez técnica y validez clínica","Optimale Lösung: zuerst HE und Materialidentität prüfen; der eingesandte Polypenrest ist klinisch ungeeignet. Nicht 'irgendetwas' sequenzieren und befundbar machen, sondern den richtigen invasiven Tumorblock anfordern.":"Solución óptima: comprobar primero H&E e identidad del material; el resto de pólipo enviado es clínicamente inadecuado. No secuenciar «lo que haya» para hacerlo informable; solicitar el bloque correcto de tumor invasivo.","falsches Material":"material equivocado","Materialidentität":"Identidad del material","LAB":"LAB","Falscher Block, perfektes QC: Wann ein technisch guter Befund klinisch wertlos ist":"Bloque equivocado, QC perfecto: cuándo un buen resultado técnico carece de valor clínico","Molekularpathologie / Pathologieassistenz / Labor":"Patología molecular / Asistencia de patología / Laboratorio","Repräsentativität des Materials vor Molekulardiagnostik prüfen.":"Comprobar la representatividad del material antes del diagnóstico molecular.","Technische Validität von klinischer Validität unterscheiden.":"Distinguir validez técnica y clínica.","Bei falschem/nicht invasivem Material die Freigabe stoppen und korrektes Tumorgewebe anfordern.":"Ante material erróneo/no invasivo, detener la liberación y solicitar tejido tumoral correcto.","Eine Präanalytik-Diskrepanz nachvollziehbar dokumentieren und kommunizieren.":"Documentar y comunicar de forma trazable una discrepancia preanalítica.","Die DNA-QC ist hervorragend, der Tumorboard-Termin ist nah und der Auftrag lautet RAS/BRAF/MMR/MSI. Der einzige Haken: Auf dem Kontroll-HE liegt gar kein invasives Karzinom, sondern nur der Rest eines früheren Adenoms. Genau jetzt entscheidet sich, ob 'gute Technik' zur gefährlichen Scheinsicherheit wird.":"El QC de ADN es excelente, se acerca el comité y la solicitud es RAS/BRAF/MMR/MSI. El único problema: en el H&E de control no hay ningún carcinoma invasivo, solo el resto de un adenoma previo. Justo aquí una «buena técnica» puede convertirse en una falsa seguridad peligrosa.","64-jähriger Patient mit metastasiertem Sigma-Karzinom. Für die prädiktive Molekulardiagnostik wurde versehentlich der Block einer früheren Polypektomie ausgewählt. Er enthält adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Ein repräsentativer Resektionsblock ist im Archiv vorhanden.":"Paciente de 64 años con carcinoma sigmoide metastásico. Para el diagnóstico molecular predictivo se seleccionó por error el bloque de una polipectomía previa. Contiene tejido adenomatoso con displasia de alto grado, pero sin carcinoma invasivo seguro. Hay un bloque de resección representativo disponible en el archivo.","RAS/BRAF und MMR/MSI vor Systemtherapie.":"RAS/BRAF y MMR/MSI antes del tratamiento sistémico.","Die klinische Frage bezieht sich auf das invasive/metastasierte Karzinom.":"La pregunta clínica se refiere al carcinoma invasivo/metastásico.","Polypektomie A1 mit Adenom/HGIEN, ohne sichere Invasion.":"Polipectomía A1 con adenoma/HGIEN, sin invasión segura.","Die Probenidentität ist klinisch falsch, obwohl die DNA technisch gut sein kann.":"La identidad de la muestra es clínicamente errónea aunque el ADN pueda ser técnicamente bueno.","Alternativmaterial":"Material alternativo","Resektionsblock B7 mit ca. 60 % invasivem Tumor ist verfügbar.":"Está disponible el bloque de resección B7 con aprox. 60 % de tumor invasivo.","Die richtige Lösung ist Nachforderung/Blockwechsel, nicht Interpretation des falschen Materials.":"La solución correcta es solicitar/cambiar de bloque, no interpretar el material equivocado.","Kein sicher invasives Karzinom im eingesandten Block.":"Sin carcinoma invasivo seguro en el bloque enviado.","Sehr gute DNA-Qualität – technisch wären PCR/NGS problemlos möglich.":"Calidad de ADN muy buena: técnicamente PCR/NGS serían sencillos.","LIMS-Abgleich":"Comprobación en LIMS","Block A1 gehört zur Polypektomie; Resektionsblock B7 trägt den invasiven Tumor.":"El bloque A1 pertenece a la polipectomía; el bloque de resección B7 contiene el tumor invasivo.","MTB in vier Tagen erzeugt realen Zeitdruck.":"El MTB en cuatro días genera una presión de tiempo real.","Das korrekte Material existiert, muss aber aktiv nachgefordert/umgebucht werden.":"El material correcto existe, pero debe solicitarse/reasignarse activamente.","Jede Molekulardiagnostik am falschen Block produziert potenziell einen technisch plausiblen, klinisch irreführenden Befund.":"Cualquier análisis molecular en el bloque equivocado puede producir un resultado técnicamente plausible pero clínicamente engañoso.","Was ist der nächste entscheidende Schritt?":"¿Cuál es el siguiente paso decisivo?","HE/Blockidentität prüfen, Analyse am Polypenrest stoppen und repräsentatives invasives Tumormaterial anfordern.":"Comprobar H&E/identidad del bloque, detener el análisis del resto de pólipo y solicitar material representativo de tumor invasivo.","Wegen des MTB-Termins sofort NGS durchführen; gute DNA-QC reicht.":"Por el plazo del MTB, realizar NGS inmediatamente; un buen QC de ADN es suficiente.","Nur MMR-IHC durchführen und den Rest später entscheiden.":"Realizar solo IHC MMR y decidir el resto después.","Molekularbefund aus dem Adenom als Status des metastasierten CRC berichten.":"Informar el resultado molecular del adenoma como estado del CRC metastásico.","Präanalytische Repräsentativität ist Voraussetzung jeder klinischen Interpretation.":"La representatividad preanalítica es un requisito para cualquier interpretación clínica.","Ein NGS-Lauf aus dem Polypenrest ist technisch valide. Ist der Befund damit klinisch valide?":"Un run de NGS del resto del pólipo es técnicamente válido. ¿Eso hace que el resultado sea clínicamente válido?","Nein. Ein technisch korrekter Befund kann klinisch unbrauchbar sein, wenn das analysierte Gewebe die Fragestellung nicht repräsentiert.":"No. Un resultado técnicamente correcto puede ser clínicamente inutilizable si el tejido analizado no representa la pregunta clínica.","Ja. Technische QC ist die einzige Voraussetzung für Freigabe.":"Sí. El QC técnico es el único requisito para liberar el resultado.","Ja, sofern RAS/BRAF Wildtyp sind.":"Sí, siempre que RAS/BRAF sean wild type.","Ja, wenn ein breites Panel benutzt wurde.":"Sí, si se utilizó un panel amplio.","Analytische Qualität ersetzt nicht Probenidentität und klinische Repräsentativität.":"La calidad analítica no sustituye la identidad de la muestra ni la representatividad clínica.","Wie soll die Diskrepanz behandelt werden?":"¿Cómo debe gestionarse la discrepancia?","Dokumentieren, Einsender/Pathologie kontaktieren, korrekten Block nachfordern und erst dann prädiktiv testen.":"Documentar, contactar con el solicitante/patología, pedir el bloque correcto y solo entonces realizar pruebas predictivas.","Intern korrigieren, aber nicht dokumentieren.":"Corregir internamente, pero no documentar.","Annehmen, dass Polyp und Karzinom denselben Biomarkerstatus haben.":"Asumir que pólipo y carcinoma tienen el mismo estado de biomarcadores.","Gesamten Fall endgültig abbrechen, obwohl geeignetes Material vorhanden ist.":"Abandonar definitivamente todo el caso aunque haya material adecuado disponible.","Rückverfolgbarkeit und transparente Kommunikation gehören zur Fehlerbeherrschung.":"La trazabilidad y la comunicación transparente forman parte del control de errores.","Entscheiden Sie, ob der Polypenrest befundbar ist, und steuern Sie den Fall so, dass nur repräsentatives invasives Tumorgewebe in die prädiktive Diagnostik eingeht.":"Decidir si el resto de pólipo es informable y gestionar el caso para que solo tejido tumoral invasivo representativo entre en el diagnóstico predictivo.","Kontroll-HE des ausgewählten Blocks prüfen.":"Revisar el H&E de control del bloque seleccionado.","Diskrepanz zwischen Anforderung und Histologie erkennen.":"Reconocer la discrepancia entre solicitud e histología.","Molekulare Freigabe am Polypenrest stoppen.":"Detener la liberación molecular del resto de pólipo.","Resektionsblock B7 bzw. anderes repräsentatives invasives Material anfordern.":"Solicitar el bloque de resección B7 u otro material invasivo representativo.","Diskrepanz und Kommunikation dokumentieren.":"Documentar la discrepancia y la comunicación.","Erst am korrekten Tumormaterial mit RAS/BRAF/MMR/MSI fortfahren.":"Continuar con RAS/BRAF/MMR/MSI solo en el material tumoral correcto.","Geeignete Metastasenbiopsie anfordern, falls der Resektionsblock nicht verfügbar/qualitativ ungeeignet wäre.":"Solicitar una biopsia metastásica adecuada si el bloque de resección no está disponible/es cualitativamente inadecuado.","'DNA ist gut, also los'":"«El ADN es bueno, así que adelante»","Technische QC sagt nichts darüber aus, ob die richtige Läsion untersucht wird.":"El QC técnico no dice nada sobre si se está analizando la lesión correcta.","Adenom-Biomarker = Karzinom-Biomarker":"Biomarcador de adenoma = biomarcador de carcinoma","Klonale Evolution und fehlende Repräsentativität machen diese Gleichsetzung unzulässig.":"La evolución clonal y la falta de representatividad invalidan esta equivalencia.","Zeitdruck als Freigabeargument":"Presión de tiempo como argumento para liberar","Ein schneller falscher Befund ist schlechter als eine dokumentierte Nachforderung.":"Un resultado rápido pero incorrecto es peor que una solicitud documentada de material correcto.","Der falsche Block liefert einen überzeugenden Befund":"El bloque equivocado produce un resultado convincente","Wird voreilig sequenziert, zeigt das Adenom eine plausible APC-Alteration und keinen RAS/BRAF-Treiber. Technisch sieht alles sauber aus. Erst der HE-/LIMS-Abgleich zeigt, dass dieser Befund für das invasive metastasierte CRC gar nicht freigegeben werden darf.":"Si se secuencia de forma prematura, el adenoma muestra una alteración APC plausible y ningún driver RAS/BRAF. Técnicamente todo parece limpio. Solo la comprobación H&E/LIMS revela que este resultado no puede liberarse para el CRC invasivo metastásico.","Die gefährlichsten Präanalytikfehler produzieren nicht zwingend einen technischen Fehler – sondern einen glaubwürdigen Befund am falschen Material.":"Los errores preanalíticos más peligrosos no necesariamente producen un error técnico: pueden producir un resultado creíble en el material equivocado.","Materialfehler vor Analytik gestoppt":"Error de material detenido antes del análisis","HE zeigt kein invasives Karzinom; korrekter Resektionsblock B7 wird angefordert.":"H&E no muestra carcinoma invasivo; se solicita el bloque de resección correcto B7.","Patientensicher und ressourcenschonend.":"Seguro para el paciente y eficiente en recursos.","Technisch erfolgreich, klinisch falsch":"Técnicamente exitoso, clínicamente erróneo","NGS aus Adenom: APC-Alteration, RAS/BRAF WT. Befund darf nicht als metastasiertes CRC interpretiert werden.":"NGS del adenoma: alteración APC, RAS/BRAF WT. El resultado no debe interpretarse como CRC metastásico.","Analytisch valide, klinisch invalide.":"Analíticamente válido, clínicamente inválido.","Falschen Block freigegeben":"Bloque equivocado liberado","Adenom-Befund wird als Tumorprofil berichtet.":"El resultado del adenoma se informa como perfil tumoral.","Kritischer Präanalytik-/Freigabefehler.":"Error preanalítico/de liberación crítico.","Resektionsblock B7 verfügbar":"Bloque de resección B7 disponible","Kontroll-HE, Tumormarkierung und reguläre CRC-Biomarkerdiagnostik durchführen.":"Realizar H&E de control, marcaje tumoral y diagnóstico habitual de biomarcadores de CRC.","Der Fall kann ohne neue invasive Probengewinnung korrekt abgeschlossen werden.":"El caso puede completarse correctamente sin obtener una nueva muestra invasiva.","Kein geeignetes Archivmaterial":"Sin material de archivo adecuado","Mit Klinik eine geeignete Metastasen- oder Primärtumorprobe abstimmen.":"Coordinar con clínica una muestra adecuada de metástasis o tumor primario.","TAT steigt, klinische Validität bleibt gewahrt.":"Aumenta el TAT, se preserva la validez clínica.","Materialidentität und Repräsentativität stehen vor analytischer QC.":"La identidad y representatividad del material preceden al QC analítico.","Ein technisch valider Befund kann klinisch falsch sein.":"Un resultado técnicamente válido puede ser clínicamente erróneo.","Polyp/Adenom ist kein automatischer Surrogatblock für ein invasives metastasiertes CRC.":"El pólipo/adenoma no es un bloque sustituto automático para un CRC invasivo metastásico.","Zeitdruck rechtfertigt keine Freigabe aus falschem Material.":"La presión de tiempo no justifica liberar un resultado del material equivocado.","HE-Reevaluation zeigt nur Adenom/HGIEN. Molekulare Freigabe stoppen, Blockidentität klären und Resektionsblock B7 mit invasivem Tumor anfordern. Etwaige bereits erzeugte Daten aus dem Polypenrest nicht als prädiktiven Tumorbefund freigeben.":"La reevaluación H&E muestra solo adenoma/HGIEN. Detener la liberación molecular, aclarar la identidad del bloque y solicitar el bloque de resección B7 con tumor invasivo. No liberar los datos ya generados del resto de pólipo como resultado predictivo tumoral.","Präanalytik vor Analytik":"Preanalítica antes que analítica","Stop/No-Go korrekt":"Stop/No-Go correcto","korrektes Material angefordert":"material correcto solicitado","technische vs. klinische Validität verstanden":"validez técnica vs. clínica comprendida","Welche Kontrollen verhindern solche Blockverwechslungen?":"¿Qué controles evitan este tipo de confusiones de bloques?","Wann kann ein Vorläuferläsionsblock überhaupt sinnvoll molekular untersucht werden?":"¿Cuándo puede estudiarse molecularmente de forma útil un bloque de lesión precursora?","Wie dokumentiert man einen bereits erzeugten, aber klinisch nicht freigabefähigen Datensatz?":"¿Cómo debe documentarse un conjunto de datos ya generado pero no liberable clínicamente?","perfekte DNA aus falschem Gewebe":"ADN perfecto del tejido equivocado","technisch valide ≠ klinisch valide":"técnicamente válido ≠ clínicamente válido","HE → Diskrepanz → Stop → korrekter Block":"H&E → discrepancia → stop → bloque correcto","HER2-amplifiziertes RAS-WT-CRC → HER2 als Resistenz-/Target-Kontext":"CRC RAS-WT con amplificación HER2 → HER2 como contexto de resistencia/diana","HER2-amplifiziertes RAS-WT-CRC":"CRC RAS-WT con amplificación HER2","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom. Initial RAS/BRAF-Wildtyp und pMMR/MSS; unter FOLFOX plus Cetuximab zunächst deutliche Remission, jetzt hepatischer Progress.":"Paciente de 61 años con carcinoma sigmoide metastásico izquierdo. Inicialmente RAS/BRAF wild type y pMMR/MSS; marcada remisión con FOLFOX más cetuximab, ahora progresión hepática.","Der Progressionsbefund zeigt weiterhin keine RAS- oder BRAF-Mutation, aber einen ERBB2/HER2-Copy-number-Hinweis. Wie ist das therapeutisch zu interpretieren?":"La muestra de progresión sigue sin mostrar mutaciones RAS o BRAF, pero sugiere una ganancia de número de copias ERBB2/HER2. ¿Cómo debe interpretarse terapéuticamente?","Die nächste Therapielinie soll im MTB in fünf Tagen festgelegt werden.":"La siguiente línea terapéutica debe definirse en el MTB en cinco días.","Sigma, linksseitig; initiale Resektion vor 18 Monaten.":"Sigma, lado izquierdo; resección inicial hace 18 meses.","Initiales Molekularprofil":"Perfil molecular inicial","KRAS/NRAS Wildtyp, BRAF Wildtyp, pMMR/MSS.":"KRAS/NRAS wild type, BRAF wild type, pMMR/MSS.","Therapieverlauf":"Evolución del tratamiento","FOLFOX plus Cetuximab mit gutem initialem Ansprechen; nach 11 Monaten Progress einzelner Leberläsionen.":"FOLFOX más cetuximab con buena respuesta inicial; progresión de lesiones hepáticas individuales tras 11 meses.","Didaktischer Schlüssel":"Clave didáctica","Der Satz 'RAS und BRAF negativ' ist beim mCRC therapeutisch nicht einfach 'kein Befund': Das Fehlen etablierter MAPK-Downstream-Resistenztreiber ist eine Voraussetzung, die anti-EGFR-Antikörperstrategie bei passendem klinischem Kontext überhaupt eröffnet.":"En mCRC, la frase «RAS y BRAF negativos» no significa terapéuticamente simplemente «sin hallazgos»: la ausencia de drivers establecidos de resistencia downstream MAPK es una condición que permite una estrategia con anticuerpos anti-EGFR en el contexto clínico adecuado.","Warum kann der Tumor trotz weiterem RAS/BRAF-Wildtyp progredient sein, und welche Rolle spielt HER2?":"¿Por qué puede progresar el tumor pese a mantenerse RAS/BRAF wild type y qué papel desempeña HER2?","Progressionsbiopsie":"Biopsia de progresión","Lebermetastase eines kolorektalen Adenokarzinoms, vital und gut repräsentativ.":"Metástasis hepática de adenocarcinoma colorrectal, viable y bien representativa.","ca. 65 %.":"aprox. 65 %.","Aus der Primärdiagnostik pMMR/MSS, klinisch ausreichend dokumentiert.":"pMMR/MSS de la evaluación inicial, suficientemente documentado clínicamente.","Progressionsprofil":"Perfil de progresión","Kein RAS-/BRAF-Resistenzbefund; ERBB2 mit deutlicher Copy-number-Erhöhung im DNA-Panel.":"Sin hallazgo de resistencia RAS/BRAF; ERBB2 con marcada ganancia de número de copias en el panel de ADN.","Ist die ERBB2-Veränderung bestätigt, und wie verändert sie die scheinbar 'negative' RAS/BRAF-Situation?":"¿Está confirmada la alteración ERBB2 y cómo cambia la situación aparentemente «negativa» de RAS/BRAF?","FFPE-Lebermetastasenbiopsie, Block L3.":"Biopsia FFPE de metástasis hepática, bloque L3.","ca. 65 %, DNA-QC sehr gut.":"aprox. 65 %, QC de ADN muy bueno.","HER2-Bestätigung":"Confirmación HER2","IHC/ISH ist am vorhandenen Material möglich.":"Es posible realizar IHC/ISH en el material disponible.","Breite Wiederholung bereits gesicherter MMR/MSI-Diagnostik verbraucht Material, während die konkrete Progressionsfrage HER2-Bestätigung und Resistenzkontext betrifft.":"Repetir ampliamente un estudio MMR/MSI ya establecido consume material, mientras que la pregunta concreta de progresión se centra en confirmar HER2 y el contexto de resistencia.","Progressionsprofil / RAS-BRAF-ERBB2-Kontext":"Perfil de progresión / contexto RAS-BRAF-ERBB2","HER2-Amplifikation bestätigen":"Confirmar amplificación HER2","KRAS/NRAS weiterhin Wildtyp, BRAF Wildtyp; keine neue klassische RAS/RAF-Resistenzmutation. ERBB2 zeigt eine hochgradige Copy-number-Erhöhung.":"KRAS/NRAS siguen wild type, BRAF wild type; no hay nueva mutación clásica de resistencia RAS/RAF. ERBB2 muestra una ganancia de número de copias de alto nivel.","KRAS/NRAS Wildtyp. Das Fehlen einer RAS-Mutation ist im geeigneten linksseitigen mCRC-Kontext therapeutisch relevant, garantiert aber keine dauerhafte Sensitivität gegenüber anti-EGFR-Antikörpern.":"KRAS/NRAS wild type. La ausencia de mutación RAS es terapéuticamente relevante en el contexto adecuado de mCRC izquierdo, pero no garantiza sensibilidad duradera a anticuerpos anti-EGFR.","BRAF V600E nicht nachweisbar. RAS/BRAF-Wildtyp bedeutet nicht 'molekular ohne Bedeutung', sondern schließt wichtige etablierte MAPK-Resistenztreiber aus.":"No se detecta BRAF V600E. RAS/BRAF wild type no significa «sin relevancia molecular»; excluye importantes drivers establecidos de resistencia MAPK.","HER2 IHC/ISH":"IHC/ISH HER2","HER2 stark überexprimiert / ERBB2 amplifiziert. Der Befund ist im RAS/BRAF-WT-mCRC ein relevanter Target- und möglicher anti-EGFR-Resistenzkontext, insbesondere in der Progressionssituation.":"HER2 fuertemente sobreexpresado / ERBB2 amplificado. En mCRC RAS/BRAF-WT, el hallazgo es una diana relevante y un posible contexto de resistencia anti-EGFR, especialmente en progresión.","HER2-IHC allein":"Solo IHC HER2","HER2 IHC 3+. Im CRC-Kontext sollte die zugrunde liegende ERBB2-Amplifikation bzw. ein validierter HER2-positiver Status nach lokalem Algorithmus gesichert werden.":"HER2 IHC 3+. En el contexto de CRC, debe confirmarse la amplificación ERBB2 subyacente o un estado HER2 positivo validado según el algoritmo local.","Erneute MMR/MSI-Testung":"Repetir estudio MMR/MSI","pMMR/MSS wird bestätigt. In diesem Fall war der Status bereits belastbar bekannt; die Wiederholung beantwortet die konkrete Progressions-/HER2-Frage kaum und ist daher eher ressourcenarm zu priorisieren.":"Se confirma pMMR/MSS. En este caso el estado ya se conocía de forma sólida; repetirlo apenas responde a la pregunta concreta de progresión/HER2 y por tanto debe tener baja prioridad de recursos.","Progressionsbiopsie repräsentativ; hohe Tumorzellularität und gute DNA-Qualität. Baseline-HER2-Status war nicht bestimmt.":"Biopsia de progresión representativa; alta celularidad tumoral y buena calidad de ADN. No se determinó HER2 en baseline.","RAS/BRAF-Wildtyp ist beim linksseitigen mCRC kein bedeutungsloser Negativbefund: Das Fehlen zentraler downstream MAPK-Resistenztreiber schafft erst die molekulare Voraussetzung für eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext. Wildtyp garantiert jedoch keine Sensitivität. Im Progress wird eine bestätigte ERBB2/HER2-Amplifikation gefunden, die einen alternativen Signalweg, einen möglichen anti-EGFR-Resistenzkontext und zugleich eine HER2-gerichtete Therapieoption im passenden Linien-/Zulassungskontext eröffnet. Ohne Baseline-HER2 kann nicht sicher behauptet werden, dass die Amplifikation neu erworben wurde.":"RAS/BRAF wild type no es un hallazgo negativo carente de significado en mCRC izquierdo: la ausencia de drivers clave de resistencia downstream MAPK crea el requisito molecular para una estrategia con anticuerpos anti-EGFR en el contexto clínico adecuado. Sin embargo, el wild type no garantiza sensibilidad. En la progresión se confirma una amplificación ERBB2/HER2, que abre una vía de señalización alternativa, un posible contexto de resistencia anti-EGFR y a la vez una opción terapéutica dirigida a HER2 en el contexto apropiado de línea/aprobación. Sin HER2 basal no puede afirmarse con certeza que la amplificación sea de nueva adquisición.","Teilbefund: RAS/BRAF-Wildtyp ist korrekt erkannt, aber entweder wird 'negativ' fälschlich als therapeutisch bedeutungslos bezeichnet oder die ERBB2-Copy-number-Veränderung bleibt unbestätigt. Beides verhindert eine belastbare Progressionsinterpretation.":"Hallazgo parcial: RAS/BRAF wild type se reconoce correctamente, pero o bien «negativo» se describe erróneamente como terapéuticamente irrelevante o la alteración de número de copias ERBB2 queda sin confirmar. Ambas cosas impiden una interpretación sólida de la progresión.","Explizit erklären: RAS/BRAF-Wildtyp ist ein therapeutisch relevanter 'negativer' Befund, der anti-EGFR bei passendem linksseitigem mCRC-Kontext ermöglicht":"Explicar explícitamente: RAS/BRAF wild type es un hallazgo de selección «negativo» terapéuticamente relevante que permite anti-EGFR en el contexto adecuado de mCRC izquierdo","Wildtyp nicht als Garantie für anti-EGFR-Sensitivität darstellen":"No presentar wild type como garantía de sensibilidad a anti-EGFR","HER2-Amplifikation als alternativen Target-/Resistenzkontext integrieren":"Integrar la amplificación HER2 como contexto alternativo de diana/resistencia","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher neu erworben":"Sin HER2 basal, no afirmar que la amplificación sea definitivamente adquirida de novo","Aktuelle Linien-/Leitlinien-/Zulassungssituation für HER2-gerichtete Therapie transparent berücksichtigen":"Considerar de forma transparente el contexto actual de línea/guía/aprobación para terapia dirigida a HER2","Optimale Lösung: den RAS/BRAF-Wildtyp bewusst als therapeutisch positiven Selektionsbefund erklären; Progress trotz Wildtyp als Hinweis auf alternative Resistenzwege verstehen und die ERBB2/HER2-Amplifikation bestätigen und als Target-/Resistenzkontext integrieren.":"Solución óptima: explicar RAS/BRAF wild type como un hallazgo de selección terapéuticamente positivo; entender la progresión pese al wild type como pista de vías alternativas de resistencia y confirmar la amplificación ERBB2/HER2, integrándola como contexto de diana/resistencia.","RAS Wildtyp":"RAS wild type","BRAF Wildtyp":"BRAF wild type","ERBB2 Amplifikation":"Amplificación ERBB2","Resistenz":"Resistencia","Wenn 'negativ' therapeutisch positiv ist: RAS/BRAF-Wildtyp, anti-EGFR und der HER2-Twist":"Cuando «negativo» es terapéuticamente positivo: RAS/BRAF wild type, anti-EGFR y el giro HER2","RAS/BRAF-Wildtyp als therapeutisch relevanten negativen Selektionsbefund im mCRC erklären.":"Explicar RAS/BRAF wild type como hallazgo negativo de selección terapéuticamente relevante en mCRC.","Anti-EGFR-Eignung als Kontextentscheidung und nicht als garantierte Sensitivität verstehen.":"Entender la elegibilidad para anti-EGFR como una decisión contextual y no como sensibilidad garantizada.","HER2/ERBB2-Amplifikation als alternativen Target- und möglichen Resistenzkontext integrieren.":"Integrar la amplificación HER2/ERBB2 como diana alternativa y posible contexto de resistencia.","Zwischen 'nach Progress nachgewiesen' und 'erworben' unterscheiden, wenn kein Baseline-HER2 vorliegt.":"Distinguir «detectado tras progresión» de «adquirido» cuando no se dispone de HER2 basal.","Im Progressions-MTB steht auf der Folie: 'KRAS, NRAS, BRAF: keine Mutation nachweisbar'. Ein Kollege fasst zusammen: 'Molekular also wieder negativ.' Genau hier liegt der Kern des Falls: Beim mCRC kann ein negativer RAS/BRAF-Befund therapeutisch eine positive Information sein – und trotzdem erklärt er den jetzigen Progress nicht. Im selben Panel taucht nämlich eine deutliche ERBB2-Copy-number-Erhöhung auf.":"En la diapositiva del MTB de progresión figura: «KRAS, NRAS, BRAF: no se detecta mutación». Un colega resume: «Entonces, molecularmente otra vez negativo». Ese es exactamente el núcleo del caso: en mCRC, un resultado RAS/BRAF negativo puede ser información terapéuticamente positiva y, aun así, no explicar la progresión actual. En el mismo panel aparece además una marcada ganancia de número de copias de ERBB2.","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom, initial RAS/BRAF-Wildtyp und pMMR/MSS. Unter FOLFOX plus Cetuximab gutes Ansprechen, nach elf Monaten Progress in der Leber. Die Progressionsbiopsie bleibt RAS/BRAF-Wildtyp, zeigt aber eine hochgradige ERBB2-Copy-number-Erhöhung. Der Fall soll den scheinbaren Widerspruch 'negativ = therapeutisch positiv' erklären und anschließend HER2 als alternativen Resistenz-/Targetkontext einordnen.":"Paciente de 61 años con carcinoma sigmoide metastásico izquierdo, inicialmente RAS/BRAF wild type y pMMR/MSS. Buena respuesta a FOLFOX más cetuximab, progresión hepática tras 11 meses. La biopsia de progresión sigue RAS/BRAF wild type, pero muestra una ganancia de número de copias ERBB2 de alto nivel. El caso pretende explicar la aparente contradicción «negativo = terapéuticamente positivo» y después situar HER2 como contexto alternativo de resistencia/diana.","Baseline":"Baseline","Linksseitiges mCRC, RAS/BRAF-Wildtyp, pMMR/MSS.":"mCRC izquierdo, RAS/BRAF wild type, pMMR/MSS.","Dieser Molekularkontext ermöglichte grundsätzlich eine anti-EGFR-Antikörperstrategie.":"Este contexto molecular permitió en principio una estrategia con anticuerpos anti-EGFR.","Gutes initiales Ansprechen unter FOLFOX + Cetuximab, Progress nach 11 Monaten.":"Buena respuesta inicial a FOLFOX + cetuximab, progresión tras 11 meses.","Wildtyp ist Selektion, keine Garantie dauerhafter Sensitivität.":"Wild type es selección, no garantía de sensibilidad duradera.","Weiterhin RAS/BRAF-Wildtyp, aber ERBB2-Copy-number hoch.":"Sigue RAS/BRAF wild type, pero el número de copias ERBB2 es alto.","Resistenz kann über alternative Signalwege entstehen/bestehen.":"La resistencia puede surgir/persistir mediante vías de señalización alternativas.","Limitation":"Limitación","HER2 wurde an der Baseline nicht bestimmt.":"HER2 no se determinó en baseline.","Die aktuelle Amplifikation darf nicht sicher als neu erworben bezeichnet werden.":"La amplificación actual no puede describirse con certeza como adquirida de novo.","Initialdiagnostik":"Diagnóstico inicial","KRAS/NRAS WT, BRAF WT, pMMR/MSS.":"KRAS/NRAS WT, BRAF WT, pMMR/MSS.","Aktueller Progress":"Progresión actual","Lebermetastasenbiopsie mit 65 % Tumor und guter DNA-QC.":"Biopsia de metástasis hepática con 65 % de tumor y buen QC de ADN.","Panel-Hinweis":"Señal del panel","ERBB2 hochgradige Copy-number-Erhöhung; RAS/BRAF weiter WT.":"Ganancia de número de copias ERBB2 de alto nivel; RAS/BRAF siguen WT.","Neun Schnitte reichen für HER2-Bestätigung und fokussierte Progressionsdiagnostik.":"Nueve cortes son suficientes para confirmar HER2 y realizar un diagnóstico focalizado de progresión.","MMR/MSI ist bereits belastbar dokumentiert und muss nicht reflexartig wiederholt werden.":"MMR/MSI ya está sólidamente documentado y no necesita repetirse de forma refleja.","HER2-Status sollte orthogonal/validiert bestätigt werden, bevor die therapeutische Schlussfolgerung formuliert wird.":"El estado HER2 debe confirmarse ortogonalmente/con un método validado antes de formular la conclusión terapéutica.","Wie ist 'KRAS/NRAS/BRAF: keine pathogene Mutation nachweisbar' beim linksseitigen mCRC therapeutisch zu lesen?":"¿Cómo debe interpretarse terapéuticamente «KRAS/NRAS/BRAF: no se detecta mutación patogénica» en mCRC izquierdo?","Als therapeutisch relevanter Wildtyp-/Ausschlussbefund: zentrale downstream MAPK-Resistenztreiber fehlen, sodass eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext grundsätzlich möglich wird.":"Como hallazgo wild type/de exclusión terapéuticamente relevante: faltan drivers clave de resistencia downstream MAPK, de modo que una estrategia con anticuerpos anti-EGFR se vuelve posible en el contexto clínico adecuado.","Als völlig bedeutungsloser Negativbefund ohne therapeutische Aussage.":"Como hallazgo negativo completamente carente de significado terapéutico.","Als Garantie, dass anti-EGFR sicher und dauerhaft wirkt.":"Como garantía de que anti-EGFR funcionará de forma segura y duradera.","Als Beweis, dass auch HER2 keine Rolle spielen kann.":"Como prueba de que HER2 tampoco puede desempeñar ningún papel.","Das Fehlen von RAS/BRAF-Treibern ist eine positive Selektionsinformation, aber keine Erfolgsgarantie.":"La ausencia de drivers RAS/BRAF es información positiva de selección, pero no garantía de éxito.","Der Patient progrediert trotz weiterem RAS/BRAF-Wildtyp. Was ist die beste Interpretation?":"El paciente progresa pese a mantenerse RAS/BRAF wild type. ¿Cuál es la mejor interpretación?","Wildtyp schließt nur bestimmte Resistenzwege aus; alternative Mechanismen wie HER2/ERBB2 können relevant sein.":"Wild type solo excluye determinadas vías de resistencia; mecanismos alternativos como HER2/ERBB2 pueden ser relevantes.","Progress beweist, dass der RAS/BRAF-Test falsch sein muss.":"La progresión demuestra que la prueba RAS/BRAF debe ser errónea.","Damit war die ursprüngliche anti-EGFR-Strategie grundsätzlich falsch.":"Esto significa que la estrategia anti-EGFR inicial fue fundamentalmente incorrecta.","Molekulare Diagnostik kann den Progress nicht mehr erklären.":"El diagnóstico molecular ya no puede explicar la progresión.","Resistenzbiologie ist breiter als RAS/BRAF allein.":"La biología de la resistencia es más amplia que RAS/BRAF por sí solos.","Wie sollte die ERBB2-Copy-number-Erhöhung weiterbehandelt werden?":"¿Cómo debe estudiarse después la ganancia de número de copias ERBB2?","HER2-positiven Status mit validiertem IHC/ISH-Algorithmus bestätigen und als Target-/möglichen anti-EGFR-Resistenzkontext integrieren.":"Confirmar el estado HER2 positivo con un algoritmo IHC/ISH validado e integrarlo como diana/posible contexto de resistencia anti-EGFR.","Ignorieren, da RAS/BRAF Wildtyp sind.":"Ignorarlo porque RAS/BRAF son wild type.","Ohne weitere Prüfung als sicher erworbene Resistenzmutation bezeichnen.":"Sin más pruebas, denominarla mutación de resistencia definitivamente adquirida.","Unverändert nach Mammakarzinom-Regeln interpretieren.":"Interpretar sin cambios según las reglas de cáncer de mama.","HER2 ist entitätsspezifisch zu bestätigen und zu interpretieren; Baseline fehlt für eine sichere Akquisitionsaussage.":"HER2 debe confirmarse e interpretarse de forma específica de la entidad; la falta de baseline impide afirmar una adquisición con certeza.","Darf die HER2-Amplifikation als 'erworben unter Cetuximab' bezeichnet werden?":"¿Puede describirse la amplificación HER2 como «adquirida bajo cetuximab»?","Nicht sicher. Ohne Baseline-HER2 kann sie präexistent gewesen oder unter Therapie selektiert/angereichert worden sein.":"No con certeza. Sin HER2 basal, puede haber sido preexistente o haber sido seleccionada/enriquecida bajo tratamiento.","Ja, weil sie erst beim Progress gemessen wurde.":"Sí, porque solo se midió en la progresión.","Ja, weil RAS/BRAF Wildtyp sind.":"Sí, porque RAS/BRAF son wild type.","Die zeitliche Einordnung ist für die Befundsprache irrelevant.":"La clasificación temporal es irrelevante para la redacción del informe.","Nachweiszeitpunkt und biologischer Entstehungszeitpunkt sind nicht identisch.":"El momento de detección y el momento biológico de aparición no son idénticos.","Erklären Sie zuerst, warum RAS/BRAF-Wildtyp im mCRC eine therapeutisch relevante 'negative' Information ist. Integrieren Sie danach die bestätigte HER2-Amplifikation in die Progressions- und Targetinterpretation, ohne Überinterpretation der Akquisition.":"Explicar primero por qué RAS/BRAF wild type en mCRC es información «negativa» terapéuticamente relevante. Después integrar la amplificación HER2 confirmada en la interpretación de progresión y diana sin sobreinterpretar su adquisición.","Linksseitigkeit und initialen RAS/BRAF-Wildtyp zusammen mit pMMR/MSS erfassen.":"Recoger lateralidad izquierda y RAS/BRAF wild type inicial junto con pMMR/MSS.","RAS/BRAF-Wildtyp als Selektionsvoraussetzung für anti-EGFR-Antikörper erklären, nicht als 'kein Befund'.":"Explicar RAS/BRAF wild type como requisito de selección para anticuerpos anti-EGFR, no como «sin hallazgos».","Progress trotz Wildtyp als Hinweis auf alternative Resistenzmechanismen verstehen.":"Entender la progresión pese al wild type como pista de mecanismos alternativos de resistencia.","ERBB2-Copy-number-Befund durch HER2-IHC/ISH bestätigen.":"Confirmar el hallazgo de número de copias ERBB2 mediante IHC/ISH HER2.","HER2 als Target- und möglichen anti-EGFR-Resistenzkontext berichten.":"Informar HER2 como diana y posible contexto de resistencia anti-EGFR.","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher erworben.":"Sin HER2 basal, no afirmar que la amplificación sea definitivamente adquirida.","Validiertes breit angelegtes Progressionspanel mit zuverlässiger ERBB2-CNV-Erfassung plus orthogonale HER2-Bestätigung.":"Panel amplio validado de progresión con detección fiable de CNV ERBB2 más confirmación HER2 ortogonal.","Bei nicht ausreichendem Gewebe ctDNA als ergänzender Resistenzansatz, sofern methodisch geeignet; negativer ctDNA-Befund würde Gewebe jedoch nicht automatisch ersetzen.":"Si el tejido es insuficiente, ctDNA como enfoque complementario de resistencia cuando sea metodológicamente adecuado; un resultado ctDNA negativo no sustituiría automáticamente al tejido.","'Alles negativ'":"«Todo negativo»","RAS/BRAF-Wildtyp ist therapeutisch relevante Selektionsinformation.":"RAS/BRAF wild type es información de selección terapéuticamente relevante.","Wildtyp = garantiert sensitiv":"Wild type = sensibilidad garantizada","Andere primäre oder sekundäre Resistenzmechanismen bleiben möglich.":"Siguen siendo posibles otros mecanismos de resistencia primaria o secundaria.","HER2 = sicher erworben":"HER2 = definitivamente adquirido","Ohne Baseline-HER2 kann die zeitliche Entstehung nicht bewiesen werden.":"Sin HER2 basal, no puede demostrarse el momento de aparición.","Nur MMR/MSI wiederholen":"Repetir solo MMR/MSI","Der Status ist bereits bekannt und beantwortet die konkrete Progressionsfrage kaum.":"El estado ya se conoce y apenas responde a la pregunta concreta de progresión.","Kein RAS/RAF-Resistenztreiber – dafür HER2 amplifiziert":"Sin driver RAS/RAF de resistencia, pero HER2 amplificado","Das Progressionspanel bleibt KRAS/NRAS/BRAF-Wildtyp. Genau dieser 'negative' Befund war initial therapeutisch hilfreich, erklärt aber den aktuellen Progress nicht. Die HER2-Bestätigung zeigt IHC 3+ und ERBB2-Amplifikation. Damit erscheint ein alternativer Signal-/Resistenzweg und zugleich ein neuer Targetkontext. Weil Baseline-HER2 fehlt, bleibt offen, ob die Amplifikation schon vorher vorhanden oder unter Therapie selektiert war.":"El panel de progresión sigue KRAS/NRAS/BRAF wild type. Precisamente este resultado «negativo» fue terapéuticamente útil al inicio, pero no explica la progresión actual. La confirmación HER2 muestra IHC 3+ y amplificación ERBB2. Así aparece una vía alternativa de señalización/resistencia y, al mismo tiempo, un nuevo contexto de diana. Como no hay HER2 basal, queda abierto si la amplificación ya estaba presente o fue seleccionada bajo tratamiento.","Der Fall trennt drei Ebenen, die häufig vermischt werden: Selektionsmarker, Resistenzmechanismus und Target. 'Negativ' und 'positiv' sind therapeutisch kontextabhängige Begriffe.":"El caso separa tres niveles que suelen mezclarse: marcador de selección, mecanismo de resistencia y diana. «Negativo» y «positivo» son términos terapéuticos dependientes del contexto.","Wildtyp richtig gelesen + HER2 integriert":"Wild type interpretado correctamente + HER2 integrado","KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplifiziert. Anti-EGFR war im initialen linksseitigen WT-Kontext plausibel; HER2 ist nun ein relevanter Target-/Resistenzkontext. Akquisition nicht beweisbar.":"KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplificado. Anti-EGFR fue plausible en el contexto inicial izquierdo WT; HER2 es ahora un contexto relevante de diana/resistencia. No puede demostrarse adquisición.","Alle Ebenen sauber getrennt und integriert.":"Todos los niveles correctamente separados e integrados.","Wildtyp als 'negativ' abgehakt":"Wild type descartado como «negativo»","RAS/BRAF WT wird nur als fehlender Befund erwähnt; HER2 wird zwar gefunden, aber die Selektionslogik bleibt unverstanden.":"RAS/BRAF WT se menciona solo como ausencia de hallazgo; se detecta HER2, pero la lógica de selección sigue sin comprenderse.","Zentrales Lernziel verfehlt.":"Objetivo central de aprendizaje no alcanzado.","HER2 als sicher erworbene Resistenz bezeichnet":"HER2 etiquetado como resistencia definitivamente adquirida","Kausalität/Akquisition wird ohne Baseline behauptet.":"Se afirma causalidad/adquisición sin baseline.","Überinterpretation der zeitlichen Evidenz.":"Sobreinterpretación de la evidencia temporal.","HER2 bestätigt":"HER2 confirmado","HER2-gerichtete Therapieoptionen nach aktueller Zulassung/Leitlinie und Vorbehandlung im MTB prüfen.":"Revisar en el MTB las opciones de tratamiento dirigido a HER2 según aprobación/guía actual y tratamiento previo.","Der Progressionsbefund eröffnet eine neue therapeutische Achse.":"El hallazgo de progresión abre un nuevo eje terapéutico.","HER2 nicht bestätigt":"HER2 no confirmado","Alternative Resistenzmechanismen im Progressionsprofil/ctDNA/Gewebe prüfen.":"Evaluar mecanismos alternativos de resistencia en el perfil de progresión/ctDNA/tejido.","RAS/BRAF-Wildtyp allein erklärt den Progress weiterhin nicht.":"RAS/BRAF wild type por sí solo sigue sin explicar la progresión.","Beim mCRC kann ein negativer Mutationsbefund therapeutisch positiv sein.":"En mCRC, un resultado mutacional negativo puede ser terapéuticamente positivo.","RAS/BRAF-Wildtyp ist Voraussetzung/Selektionsinformation für anti-EGFR, aber keine Garantie für Wirkung.":"RAS/BRAF wild type es un requisito/información de selección para anti-EGFR, pero no garantía de eficacia.","HER2-Amplifikation kann einen alternativen Target-/Resistenzkontext darstellen.":"La amplificación HER2 puede representar un contexto alternativo de diana/resistencia.","Ohne Baseline darf 'erworben' nicht behauptet werden.":"Sin baseline, no debe afirmarse «adquirido».","Linksseitiges mCRC mit initial RAS/BRAF-WT/pMMR/MSS: der Wildtypstatus ist eine positive Selektionsinformation für anti-EGFR-Antikörper. Beim Progress bleibt RAS/BRAF WT, aber ERBB2 ist amplifiziert und HER2 bestätigt. HER2 als alternativen Target-/Resistenzkontext berichten; mangels Baseline nicht als sicher erworben bezeichnen.":"mCRC izquierdo con RAS/BRAF-WT/pMMR/MSS inicial: el estado wild type es información positiva de selección para anticuerpos anti-EGFR. En progresión, RAS/BRAF sigue WT, pero ERBB2 está amplificado y HER2 confirmado. Informar HER2 como contexto alternativo de diana/resistencia; sin baseline, no denominarlo definitivamente adquirido.","negativ=positiv-Konzept explizit verstanden":"concepto «negativo = positivo» comprendido explícitamente","WT nicht als Erfolgsgarantie":"WT no tratado como garantía de éxito","HER2 bestätigt und integriert":"HER2 confirmado e integrado","Akquisitionssprache begrenzt":"Redacción sobre adquisición adecuadamente limitada","Warum sind Wildtypbefunde in der Onkologie oft therapeutisch hochinformativ?":"¿Por qué los hallazgos wild type suelen ser muy informativos terapéuticamente en oncología?","Welche weiteren anti-EGFR-Resistenzmechanismen gibt es neben RAS/BRAF?":"¿Qué otros mecanismos de resistencia anti-EGFR existen además de RAS/BRAF?","Wie verändert ctDNA die Rechallenge-/Resistenzdiagnostik?":"¿Cómo cambia ctDNA el diagnóstico de rechallenge/resistencia?","RAS/BRAF WT bleibt, HER2 wird positiv":"RAS/BRAF sigue WT, HER2 se vuelve positivo","negativ kann therapeutisch positiv sein":"negativo puede ser terapéuticamente positivo","WT-Selektion → anti-EGFR → Progress → HER2-Amplifikation":"Selección WT → anti-EGFR → progresión → amplificación HER2","Mammakarzinom: BRCA/PIK3CA/ERBB2-Kontext → Klassische Marker vs. Panel-Zusatznutzen":"Cáncer de mama: contexto BRCA/PIK3CA/ERBB2 → marcadores clásicos frente al valor añadido del panel","Mammakarzinom: BRCA/PIK3CA/ERBB2-K…":"Cáncer de mama: contexto BRCA/PIK3CA/ERBB2…","Gynäko-Onkologie / Molekulares Tumorboard":"Oncología ginecológica / Comité Molecular de Tumores","56-jährige Patientin mit sechs Jahre zuvor behandeltem invasivem Mammakarzinom; jetzt neu aufgetretene Leber- und Knochenmetastasen nach Progress unter endokriner Therapie plus CDK4/6-Inhibition.":"Mujer de 56 años con cáncer de mama invasivo tratado seis años antes; ahora nuevas metástasis hepáticas y óseas tras progresión con terapia endocrina más inhibición CDK4/6.","Welche klassischen prädiktiven Marker müssen an der Metastase erneut geklärt werden, und welchen zusätzlichen therapeutischen Nutzen liefern PIK3CA- sowie BRCA/HRR-Analysen?":"¿Qué marcadores predictivos clásicos deben reevaluarse en la metástasis y qué valor terapéutico adicional aportan los análisis PIK3CA y BRCA/HRR?","Therapiewechsel soll im nächsten MTB festgelegt werden.":"El cambio de tratamiento debe definirse en el próximo MTB.","Primärtumor vor 6 Jahren":"Tumor primario hace 6 años","ER 95 %, PgR 70 %, HER2 IHC 0; adjuvante Chemotherapie und anschließende endokrine Therapie.":"ER 95 %, PgR 70 %, HER2 IHC 0; quimioterapia adyuvante seguida de terapia endocrina.","Metastasierte Situation":"Situación metastásica","Nach initialer Krankheitskontrolle unter Aromatasehemmer + CDK4/6-Inhibitor nun hepatischer Progress.":"Tras control inicial de la enfermedad con inhibidor de aromatasa + inhibidor CDK4/6, ahora progresión hepática.","Familienanamnese":"Antecedentes familiares","Mutter mit Ovarialkarzinom im Alter von 63 Jahren; bisher keine dokumentierte humangenetische Abklärung.":"Madre con cáncer de ovario a los 63 años; sin asesoramiento/pruebas genéticas documentadas hasta la fecha.","Ein breites Panel wird als Ersatz für die erneute Bestimmung der klassischen Tumorbiologie verstanden – oder ein Tumor-BRCA-Befund wird direkt als gesicherte Keimbahnmutation behandelt.":"Se entiende un panel amplio como sustituto de reevaluar la biología tumoral clásica, o un hallazgo BRCA tumoral se trata directamente como mutación germinal demostrada.","Metastasenbiopsie":"Biopsia metastásica","Adenokarzinom, morphologisch und immunhistochemisch vereinbar mit Mammakarzinommetastase.":"Adenocarcinoma morfológica e inmunohistoquímicamente compatible con metástasis de cáncer de mama.","Rezeptorstatus Metastase":"Estado de receptores de la metástasis","ER 80 %, PgR 5 %. HER2-IHC 2+ und damit für die klassische HER2-Statusbestimmung zunächst äquivok.":"ER 80 %, PgR 5 %. HER2 IHC 2+ y, por tanto, inicialmente equívoco para la determinación clásica del estado HER2.","Offene molekulare Fragen":"Preguntas moleculares abiertas","PIK3CA als endokrin-targetierbarer Kontext; BRCA1/2/HRR wegen PARP- und hereditärer Fragestellung.":"PIK3CA como contexto dirigible en el ámbito endocrino; BRCA1/2/HRR por cuestiones de PARP y herencia.","Kernproblem":"Problema central","Klassische Marker und Molekularpanel beantworten unterschiedliche Ebenen derselben Therapieentscheidung.":"Los marcadores clásicos y los paneles moleculares responden a distintos niveles de una misma decisión terapéutica.","FFPE-Leberbiopsie, Block L3.":"Biopsia hepática FFPE, bloque L3.","ca. 45 %, nach Makrodissektion gut geeignet.":"aprox. 45 %, bien adecuado tras macrodiseción.","11 ungefärbte Schnitte; genug für gezielte IHC/ISH und fokussierte Molekulardiagnostik.":"11 cortes sin teñir; suficientes para IHC/ISH dirigida y diagnóstico molecular focalizado.","DNA ausreichend; HER2-IHC technisch gut beurteilbar.":"ADN suficiente; IHC HER2 técnicamente bien evaluable.","Ein großes Pan-Panel verbraucht mehr Material, ersetzt aber weder die validierte HER2-IHC/ISH-Ebene noch die getrennte Keimbahnabklärung.":"Un pan-panel grande consume más material, pero no sustituye ni el nivel validado de HER2 IHC/ISH ni la evaluación germinal separada.","HER2-Status der Metastase klären":"Aclarar el estado HER2 de la metástasis","PIK3CA-Kontext":"Contexto PIK3CA","Tumor-BRCA/HRR-Kontext":"Contexto tumoral BRCA/HRR","HER2-Status":"Estado HER2","HER2-IHC 2+; ERBB2-ISH/FISH ohne Amplifikation. Der Tumor ist damit nicht HER2-amplifiziert; die äquivoke IHC allein darf nicht als HER2-positiv überinterpretiert werden.":"HER2 IHC 2+; ERBB2 ISH/FISH sin amplificación. Por tanto, el tumor no está amplificado para HER2; la IHC equívoca por sí sola no debe sobreinterpretarse como HER2 positiva.","PIK3CA":"PIK3CA","PIK3CA p.H1047R, pathogen/aktivierend. Im HR-positiven, HER2-negativen metastasierten Kontext therapeutisch relevant abhängig von Vorbehandlung, Therapielinie und aktueller Zulassung/Leitlinie.":"PIK3CA p.H1047R, patogénica/activadora. Terapéuticamente relevante en enfermedad metastásica HR positiva, HER2 negativa según tratamiento previo, línea terapéutica y aprobación/guía actual.","Tumor-BRCA/HRR":"BRCA/HRR tumoral","BRCA2-Frameshift-Variante mit Loss-of-function-Konsequenz, VAF 47 %. Der Tumorbefund kann eine therapeutisch und hereditär relevante Spur sein, beweist aber für sich keine Keimbahnmutation.":"Variante frameshift BRCA2 con consecuencia loss-of-function, VAF 47 %. El hallazgo tumoral puede ser una pista relevante terapéutica y hereditariamente, pero no demuestra por sí solo una mutación germinal.","Humangenetische Weiterleitung":"Derivación a asesoramiento genético","Humangenetische Beratung und Keimbahnabklärung werden empfohlen. Die hereditäre Einordnung erfolgt aus einer geeigneten Normalprobe und getrennt vom Tumor-only-Befund.":"Se recomienda asesoramiento genético y estudio germinal. La clasificación hereditaria se realiza a partir de una muestra normal adecuada y separadamente del hallazgo tumor-only.","Rezeptorbiologie":"Biología de receptores","ER 80 %, PgR 5 %; HER2-IHC 2+ an der Metastase.":"ER 80 %, PgR 5 %; HER2 IHC 2+ en la metástasis.","Metastasenbiopsie ausreichend für fokussierte IHC/ISH und Molekulardiagnostik.":"Biopsia metastásica suficiente para IHC/ISH dirigida y diagnóstico molecular.","HR-positives metastasiertes Mammakarzinom mit HER2-IHC 2+, aber ohne ERBB2-Amplifikation. Zusätzlich liegt eine aktivierende PIK3CA-Mutation vor. Eine pathogene BRCA2-Loss-of-function-Variante wurde im Tumor gefunden; ihre Keimbahnherkunft ist aus der Tumoranalyse nicht ableitbar und muss separat humangenetisch geklärt werden. Klassische Rezeptor-/HER2-Diagnostik und molekulare Zusatzdiagnostik ergänzen sich und dürfen nicht gegeneinander ersetzt werden.":"Cáncer de mama metastásico HR positivo con HER2 IHC 2+, pero sin amplificación ERBB2. Además, existe una mutación activadora PIK3CA. En el tumor se encontró una variante patogénica BRCA2 loss-of-function; su origen germinal no puede inferirse del análisis tumoral y debe aclararse por separado mediante asesoramiento/estudio genético. El diagnóstico clásico de receptores/HER2 y las pruebas moleculares adicionales se complementan y no deben sustituirse entre sí.","Teilbefund: Die molekularen Zusatzmarker sind nur im aktuellen ER/PgR/HER2-Kontext sinnvoll interpretierbar. Ein HER2-IHC-2+-Befund benötigt die validierte ISH/FISH-Klärung; ein Tumor-BRCA2-Befund ist nicht automatisch ein Keimbahnbefund.":"Hallazgo parcial: los marcadores moleculares adicionales solo pueden interpretarse con sentido en el contexto actual ER/PgR/HER2. Un resultado HER2 IHC 2+ requiere aclaración validada por ISH/FISH; un hallazgo BRCA2 tumoral no es automáticamente un hallazgo germinal.","Aktuellen ER/PgR/HER2-Kontext der Metastase als Grundlage benennen":"Indicar el contexto actual ER/PgR/HER2 de la metástasis como fundamento","HER2 IHC 2+ durch ISH/FISH klären und nicht vorschnell als HER2-positiv bezeichnen":"Aclarar HER2 IHC 2+ mediante ISH/FISH y no denominarlo prematuramente HER2 positivo","PIK3CA als zusätzlichen, therapielinienabhängigen Targetkontext integrieren":"Integrar PIK3CA como contexto de diana adicional dependiente de la línea terapéutica","Tumor-BRCA2 therapeutisch/hereditär relevant einordnen, Keimbahn aber separat klären":"Clasificar BRCA2 tumoral como relevante terapéutica/hereditariamente, pero estudiar germinal por separado","Paneldiagnostik nicht als Ersatz für klassische Biomarker oder Humangenetik darstellen":"No presentar el panel como sustituto de biomarcadores clásicos ni del asesoramiento genético","Optimale Lösung: Metastasenbiologie zuerst korrekt mit ER/PgR/HER2 charakterisieren; HER2 2+ durch ISH als nicht amplifiziert klären; PIK3CA als zusätzliche therapeutische Information nutzen; pathogene Tumor-BRCA2-Variante als wichtige Spur berichten, aber Keimbahnstatus separat abklären.":"Solución óptima: caracterizar primero correctamente la biología de la metástasis con ER/PgR/HER2; aclarar HER2 2+ mediante ISH como no amplificado; utilizar PIK3CA como información terapéutica adicional; informar la variante patogénica BRCA2 tumoral como una pista importante, pero evaluar el estado germinal por separado.","Mammakarzinom":"Cáncer de mama","HR+":"HR+","BRCA2":"BRCA2","Keimbahn":"Germinal","PARP":"PARP","Klassische Marker zuerst, Panel danach: HER2 2+, PIK3CA und der Tumor-BRCA2-Twist":"Primero marcadores clásicos, después panel: HER2 2+, PIK3CA y el giro BRCA2 tumoral","Molekularpathologie / Gynäko-Onkologie / MTB":"Patología molecular / Oncología ginecológica / MTB","Bei metastasiertem Mammakarzinom die aktuelle Tumorbiologie der Metastase einschließlich ER/PgR/HER2 als Grundlage der Systemtherapie verstehen.":"En cáncer de mama metastásico, comprender la biología actual de la metástasis, incluidos ER/PgR/HER2, como fundamento del tratamiento sistémico.","HER2-IHC 2+ nicht als HER2-positiv überinterpretieren, sondern mit validierter ISH/FISH klären.":"No sobreinterpretar HER2 IHQ 2+ como HER2 positivo; aclararlo con ISH/FISH validada.","PIK3CA als zusätzliche molekulare Therapieinformation im HR-positiven/HER2-negativen Kontext einordnen.":"Integrar PIK3CA como información molecular terapéutica adicional en el contexto HR positivo/HER2 negativo.","Eine pathogene BRCA2-Variante aus Tumor-only-NGS von einer gesicherten Keimbahnmutation trennen.":"Distinguir una variante patogénica de BRCA2 detectada por NGS tumor-only de una mutación germinal confirmada.","Verstehen, dass Multigen-NGS klassische Biomarker ergänzt, aber nicht ersetzt.":"Comprender que el NGS multigénico complementa los biomarcadores clásicos, pero no los sustituye.","Die Lebermetastase ist ER-positiv und HER2-IHC 2+. Parallel meldet das Panel eine aktivierende PIK3CA-Mutation und eine pathogene BRCA2-Frameshift-Variante. Im Tumorboard fallen sofort drei vermeintlich einfache Schlussfolgerungen: 'HER2-positiv', 'PIK3CA-targetierbar' und 'BRCA erblich'. Genau dieser Fall zeigt, warum alle drei Aussagen erst im richtigen diagnostischen Kontext belastbar werden.":"La metástasis hepática es ER positiva y HER2 IHQ 2+. En paralelo, el panel informa una mutación activadora de PIK3CA y una variante frameshift patogénica de BRCA2. En el comité aparecen de inmediato tres conclusiones aparentemente sencillas: «HER2 positivo», «PIK3CA accionable» y «BRCA hereditario». Este caso muestra por qué las tres afirmaciones solo son sólidas en el contexto diagnóstico correcto.","56-jährige Patientin mit HR-positivem Mammakarzinom und hepatischem Progress nach endokriner Therapie plus CDK4/6-Inhibition. Die aktuelle Metastasenbiopsie ist ER 80 %, PgR 5 % und HER2-IHC 2+. Gesucht wird eine integrierte Therapiebiologie aus klassischer HER2-Diagnostik, PIK3CA und BRCA/HRR, ohne die Grenzen von Tumor-only-NGS zu verwischen.":"Paciente de 56 años con cáncer de mama HR positivo y progresión hepática tras terapia endocrina más inhibición de CDK4/6. La biopsia metastásica actual es ER 80%, PgR 5% y HER2 IHQ 2+. Se busca una biología terapéutica integrada a partir del diagnóstico clásico de HER2, PIK3CA y BRCA/HRR, sin difuminar las limitaciones del NGS tumor-only.","Metastasenbiologie":"Biología metastásica","ER 80 %, PgR 5 %, HER2-IHC 2+.":"ER 80%, PgR 5%, HER2 IHQ 2+.","Die aktuelle Metastase kann sich biologisch vom Primärtumor unterscheiden; klassische Marker bleiben Grundlage.":"La metástasis actual puede diferir biológicamente del tumor primario; los marcadores clásicos siguen siendo fundamentales.","Molekulare Zusatzebene":"Capa molecular adicional","PIK3CA und BRCA/HRR sollen gezielt ergänzt werden.":"PIK3CA y BRCA/HRR deben añadirse de forma dirigida.","Zusatznutzen entsteht erst im bekannten HR/HER2-Kontext.":"El valor añadido surge solo dentro del contexto HR/HER2 conocido.","Familienrelevanz":"Relevancia familiar","Mutter mit Ovarialkarzinom; keine bisherige Humangenetik.":"Madre con cáncer de ovario; sin estudio genético previo.","Tumor-only kann einen Verdacht erzeugen, aber Keimbahn nicht beweisen.":"El análisis tumor-only puede generar sospecha, pero no demostrar un origen germinal.","Mammakarzinommetastase, ER 80 %, PgR 5 %, HER2-IHC 2+.":"Metástasis de cáncer de mama, ER 80%, PgR 5%, HER2 IHQ 2+.","Vor sechs Jahren ER/PgR stark positiv, HER2-IHC 0.":"Hace seis años, ER/PgR fuertemente positivos, HER2 IHQ 0.","Leberbiopsie mit ca. 45 % Tumor; fokussierte IHC/ISH und NGS sind möglich.":"Biopsia hepática con aproximadamente un 45% de tumor; son factibles IHQ/ISH focalizadas y NGS.","Elf Schnitte erlauben eine fokussierte Diagnostik, aber unnötige Breitdiagnostik kostet Material.":"Once cortes permiten un diagnóstico focalizado, pero las pruebas amplias innecesarias consumen material.","HER2-IHC 2+ benötigt eine validierte Amplifikationsabklärung; NGS ersetzt diesen diagnostischen Algorithmus nicht automatisch.":"HER2 IHQ 2+ requiere una evaluación validada de amplificación; el NGS no sustituye automáticamente este algoritmo diagnóstico.","Eine Normalprobe für die Keimbahnabklärung ist in der Tumorpathologie nicht vorhanden.":"En patología tumoral no se dispone de una muestra normal para el estudio germinal.","Was ist die wichtigste Grundlage, bevor PIK3CA/BRCA therapeutisch interpretiert werden?":"¿Cuál es la base más importante antes de interpretar PIK3CA/BRCA con fines terapéuticos?","Die aktuelle ER/PgR/HER2-Biologie der Metastase muss belastbar feststehen; das Panel ergänzt diese Ebene.":"La biología ER/PgR/HER2 actual de la metástasis debe estar bien establecida; el panel complementa esta capa.","Ein ausreichend breites NGS-Panel ersetzt ER/PgR/HER2 vollständig.":"Un panel NGS suficientemente amplio sustituye por completo ER/PgR/HER2.","Der Rezeptorstatus des Primärtumors vor sechs Jahren reicht aus.":"El estado de receptores del tumor primario de hace seis años es suficiente.","BRCA2 entscheidet unabhängig von HR/HER2 über die gesamte Therapie.":"BRCA2 determina todo el tratamiento independientemente de HR/HER2.","Beim metastasierten Mammakarzinom bleibt die aktuelle Tumorbiologie eine zentrale prädiktive Grundlage.":"En el cáncer de mama metastásico, la biología tumoral actual sigue siendo una base predictiva central.","Die Metastase ist HER2-IHC 2+. Was bedeutet das?":"La metástasis es HER2 IHQ 2+. ¿Qué significa?","Äquivoker Befund: ERBB2-Amplifikation mit validierter ISH/FISH klären; IHC 2+ allein ist nicht gleich HER2-amplifiziert.":"Hallazgo equívoco: aclarar la amplificación de ERBB2 mediante ISH/FISH validada; IHQ 2+ por sí sola no equivale a HER2 amplificado.","HER2-positiv, weitere Klärung unnötig.":"HER2 positivo, no hace falta ninguna aclaración adicional.","Sicher HER2-negativ, ISH ist nie erforderlich.":"Definitivamente HER2 negativo; nunca se requiere ISH.","Nur die BRCA-Analyse entscheidet, HER2 ist irrelevant.":"Solo importa el análisis de BRCA; HER2 es irrelevante.","IHC 2+ benötigt die etablierte Amplifikationsabklärung.":"IHQ 2+ requiere el estudio establecido de amplificación.","Tumor-NGS zeigt eine pathogene BRCA2-Frameshift-Variante mit VAF 47 %. Was darf daraus geschlossen werden?":"El NGS tumoral muestra una variante frameshift patogénica de BRCA2 con VAF del 47 %. ¿Qué puede concluirse?","Der Befund ist therapeutisch/hereditär relevant, aber Tumor-only beweist keine Keimbahnmutation; Humangenetik/Normalprobe separat klären.":"El hallazgo es relevante terapéutica/hereditariamente, pero el análisis tumor-only no demuestra una mutación germinal; debe aclararse por separado mediante genética/muestra normal.","VAF nahe 50 % beweist eine Keimbahnmutation.":"Una VAF cercana al 50 % demuestra una mutación germinal.","Da die Probe Tumorgewebe ist, ist die Variante sicher rein somatisch.":"Como la muestra es tejido tumoral, la variante es con seguridad puramente somática.","Eine Frameshift-Variante ist automatisch eine VUS.":"Una variante frameshift es automáticamente una VUS.","Tumor-VAF und selbst LOH trennen somatisch und Keimbahn nicht zuverlässig.":"La VAF tumoral e incluso la LOH no distinguen de forma fiable el origen somático del germinal.","Wie ist der Zusatznutzen des Panels hier am besten beschrieben?":"¿Cómo se describe mejor aquí el valor añadido del panel?","PIK3CA/BRCA liefern zusätzliche therapie- und familienrelevante Information, ersetzen aber weder HER2-IHC/ISH noch die Keimbahnabklärung.":"PIK3CA/BRCA aportan información adicional relevante para tratamiento y familia, pero no sustituyen ni HER2 IHQ/ISH ni el estudio germinal.","Das Panel macht klassische Biomarker und Humangenetik überflüssig.":"El panel hace innecesarios los biomarcadores clásicos y la genética.","Molekulardiagnostik hat bei HR-positivem Mammakarzinom keinen Zusatznutzen.":"El diagnóstico molecular no aporta valor adicional en el cáncer de mama HR positivo.","Nur BRCA2 ist relevant; PIK3CA und HER2 können ignoriert werden.":"Solo BRCA2 es relevante; PIK3CA y HER2 pueden ignorarse.","Die Stärke liegt in der Integration komplementärer diagnostischer Ebenen.":"La fortaleza está en integrar capas diagnósticas complementarias.","Formulieren Sie eine integrierte MTB-Aussage, die den aktuellen HR/HER2-Status der Metastase, PIK3CA und die Tumor-BRCA2-Variante zusammenführt und klar trennt, welche Information unmittelbar tumorbezogen ist und welche eine separate Keimbahnabklärung erfordert.":"Formule una conclusión integrada del MTB que reúna el estado HR/HER2 actual de la metástasis, PIK3CA y la variante BRCA2 tumoral, diferenciando claramente qué información es directamente tumoral y cuál requiere un estudio germinal separado.","Aktuelle Metastasenbiologie mit ER/PgR/HER2 als Grundlage verwenden.":"Utilizar como base la biología metastásica actual con ER/PgR/HER2.","HER2-IHC 2+ durch ISH/FISH klären: keine ERBB2-Amplifikation.":"Aclarar HER2 IHQ 2+ mediante ISH/FISH: sin amplificación de ERBB2.","PIK3CA p.H1047R als zusätzlichen therapielinienabhängigen Targetkontext berichten.":"Informar PIK3CA p.H1047R como contexto diana adicional dependiente de la línea terapéutica.","Tumor-BRCA2-Loss-of-function als relevante molekulare Spur einordnen.":"Integrar la pérdida de función de BRCA2 tumoral como una pista molecular relevante.","Tumor-BRCA2 nicht als gesicherte Keimbahnmutation bezeichnen; humangenetische Beratung/Normalprobe empfehlen.":"No etiquetar BRCA2 tumoral como mutación germinal confirmada; recomendar genética/muestra normal.","Therapieoptionen an aktuelle Zulassung, Vorbehandlung und Gesamtbiologie binden.":"Vincular las opciones terapéuticas a la autorización vigente, tratamientos previos y biología global.","Validiertes Multigenpanel zur kombinierten Erfassung von PIK3CA und BRCA/HRR, sofern HER2 weiterhin separat nach validiertem IHC/ISH-Algorithmus beurteilt wird.":"Panel multigénico validado para detectar conjuntamente PIK3CA y BRCA/HRR, siempre que HER2 siga evaluándose por separado mediante un algoritmo IHQ/ISH validado.","Gezielte PIK3CA-Analyse plus Tumor-BRCA/HRR-Panel, um Material und TAT zu schonen.":"Análisis dirigido de PIK3CA más panel tumoral BRCA/HRR para ahorrar material y TAT.","HER2 2+ = HER2-positiv":"HER2 2+ = HER2 positivo","IHC 2+ ist äquivok und benötigt die Amplifikationsabklärung.":"IHQ 2+ es equívoca y requiere evaluación de amplificación.","Tumor-BRCA2 = Keimbahn-BRCA2":"BRCA2 tumoral = BRCA2 germinal","Tumor-only-NGS kann die Herkunft nicht sicher bestimmen.":"El NGS tumor-only no puede determinar con certeza el origen.","Pan-Panel ersetzt alles":"El pan-panel lo sustituye todo","Klassische Protein-/Amplifikationsmarker und Humangenetik beantworten andere diagnostische Ebenen.":"Los marcadores clásicos de proteína/amplificación y la genética germinal responden a capas diagnósticas diferentes.","Primärtumorstatus reicht":"El estado del tumor primario es suficiente","Bei metastasierter Erkrankung kann eine Rebiopsie die aktuelle Tumorbiologie neu bewerten.":"En enfermedad metastásica, una rebiopsia puede reevaluar la biología tumoral actual.","Zwei 'positive' Befunde – aber keiner bedeutet das, was der erste Blick suggeriert":"Dos hallazgos «positivos», pero ninguno significa lo que parece a primera vista","HER2-IHC 2+ wird durch ISH als nicht amplifiziert geklärt. Gleichzeitig zeigt Tumor-NGS BRCA2 Loss-of-function bei VAF 47 %. Das klingt nach HER2-positiv plus erblichem BRCA-Syndrom – tatsächlich ist ersteres äquivok/nicht amplifiziert und letzteres zunächst ein Tumorbefund mit notwendiger separater Keimbahnklärung. Die klar tumorbezogene Zusatzinformation ist eine aktivierende PIK3CA-p.H1047R-Mutation.":"HER2 IHQ 2+ se aclara por ISH como no amplificado. Al mismo tiempo, el NGS tumoral muestra pérdida de función de BRCA2 con VAF del 47 %. Parece un tumor HER2 positivo más un síndrome BRCA hereditario; en realidad, lo primero es equívoco/no amplificado y lo segundo es inicialmente un hallazgo tumoral que requiere aclaración germinal separada. La información adicional claramente tumoral es una mutación activadora PIK3CA p.H1047R.","Der Fall zwingt zur Trennung von Proteinexpression, Genamplifikation, somatischer Tumorgenetik und Keimbahnstatus – vier Ebenen, die therapeutisch miteinander interagieren, aber diagnostisch nicht austauschbar sind.":"El caso obliga a separar expresión proteica, amplificación génica, genética somática tumoral y estado germinal: cuatro capas que interactúan terapéuticamente, pero no son intercambiables desde el punto de vista diagnóstico.","Klassik und Molekularprofil integriert":"Marcadores clásicos y perfil molecular integrados","ER 80 %, PgR 5 %, HER2-IHC 2+/ISH nicht amplifiziert; PIK3CA p.H1047R; pathogene BRCA2-Frameshift-Variante im Tumor. PIK3CA im aktuellen HR+/HER2-negativen Therapiekontext berücksichtigen; BRCA2 als relevante Tumorspur mit separater Keimbahnabklärung berichten.":"ER 80%, PgR 5%, HER2 IHQ 2+/ISH no amplificado; PIK3CA p.H1047R; variante frameshift patogénica de BRCA2 en el tumor. Considerar PIK3CA en el contexto terapéutico actual HR+/HER2 negativo; informar BRCA2 como hallazgo tumoral relevante con evaluación germinal separada.","Alle diagnostischen Ebenen korrekt getrennt und integriert.":"Todas las capas diagnósticas se separan e integran correctamente.","Panel gut, klassische Ebene offen":"Panel correcto, capa clásica sin resolver","PIK3CA und BRCA2 werden gefunden, HER2-IHC 2+ aber nicht durch ISH geklärt.":"Se detectan PIK3CA y BRCA2, pero HER2 IHQ 2+ no se aclara mediante ISH.","Therapiebiologie bleibt unvollständig.":"La biología terapéutica sigue incompleta.","HER2 und Keimbahn überinterpretiert":"HER2 y germinal sobreinterpretados","HER2-IHC 2+ wird als HER2-positiv und Tumor-BRCA2 als sicher keimbahnpathogen bezeichnet.":"HER2 IHQ 2+ se etiqueta como HER2 positivo y BRCA2 tumoral como definitivamente patogénico germinal.","Zwei zentrale diagnostische Grenzüberschreitungen.":"Dos transgresiones diagnósticas centrales.","Tumor-BRCA2 pathologisch":"BRCA2 tumoral patológico","Humangenetische Beratung und Keimbahntestung aus geeigneter Normalprobe veranlassen.":"Solicitar asesoramiento genético y estudio germinal a partir de una muestra normal adecuada.","Therapie- und Familienrelevanz werden getrennt, aber koordiniert weiterverfolgt.":"La relevancia terapéutica y familiar se aborda por separado, pero de forma coordinada.","HER2-ISH nicht amplifiziert":"HER2 ISH no amplificado","Therapieplanung im HR+/HER2-negativen Kontext fortsetzen und PIK3CA/weitere Linienmarker berücksichtigen.":"Continuar la planificación terapéutica en el contexto HR+/HER2 negativo y considerar PIK3CA/u otros marcadores dependientes de línea.","HER2-IHC 2+ wird nicht als Amplifikationspositivität fehlgedeutet.":"HER2 IHQ 2+ no se interpreta erróneamente como positividad de amplificación.","Beim metastasierten Mammakarzinom bleibt die aktuelle ER/PgR/HER2-Biologie zentral.":"En el cáncer de mama metastásico, la biología actual ER/PgR/HER2 sigue siendo central.","HER2-IHC 2+ ist ein Klärungsbefund, kein automatisches positives Endergebnis.":"HER2 IHQ 2+ es un hallazgo que requiere aclaración, no un resultado final automáticamente positivo.","PIK3CA erweitert die therapeutische Information im passenden HR+/HER2-negativen Kontext.":"PIK3CA amplía la información terapéutica en el contexto apropiado HR+/HER2 negativo.","Tumor-only BRCA kann klinisch hochrelevant sein, beweist aber keinen Keimbahnstatus.":"BRCA tumor-only puede ser muy relevante clínicamente, pero no demuestra el estado germinal.","Multigen-NGS ergänzt klassische Pathologiemarker; es ersetzt sie nicht.":"El NGS multigénico complementa los marcadores clásicos de patología; no los sustituye.","Aktuelle Metastasenbiologie zuerst: HR-positiv, HER2-IHC 2+, aber ISH nicht amplifiziert. PIK3CA p.H1047R ist als zusätzlicher therapeutischer Marker relevant. Die pathogene BRCA2-Frameshift-Variante stammt aus Tumor-only-NGS; sie darf nicht als Keimbahnmutation bezeichnet werden und löst eine separate humangenetische Abklärung aus.":"Primero la biología metastásica actual: HR positivo, HER2 IHQ 2+, pero ISH no amplificado. PIK3CA p.H1047R es relevante como marcador terapéutico adicional. La variante frameshift patogénica de BRCA2 procede de NGS tumor-only; no debe llamarse mutación germinal y desencadena una evaluación genética separada.","HER2 2+ korrekt geklärt":"HER2 2+ aclarado correctamente","PIK3CA im passenden Kontext integriert":"PIK3CA integrado en el contexto adecuado","Tumor vs. Keimbahn getrennt":"Tumoral frente a germinal separados","Panel nicht als Ersatz klassischer Marker":"El panel no se considera sustituto de los marcadores clásicos","Warum sollte die Metastase erneut auf ER/PgR/HER2 untersucht werden?":"¿Por qué debería reevaluarse la metástasis para ER/PgR/HER2?","Welche Aussage kann eine Tumor-VAF von etwa 50 % zur Keimbahnherkunft leisten – und welche nicht?":"¿Qué puede indicar una VAF tumoral de alrededor del 50 % sobre un origen germinal y qué no puede indicar?","Wann ist ein breites Panel gegenüber fokussierter Diagnostik wirklich sinnvoll?":"¿Cuándo es realmente útil un panel amplio frente a un diagnóstico focalizado?","HER2 2+ nicht amplifiziert + Tumor-BRCA2 ist nicht automatisch Keimbahn":"HER2 2+ no amplificado + BRCA2 tumoral no equivale automáticamente a germinal","Klassische Marker und Molekularprofil sind komplementär":"Los marcadores clásicos y el perfil molecular son complementarios","Metastasenbiologie → HER2-Klärung → PIK3CA/BRCA → Keimbahn separat":"Biología metastásica → aclaración HER2 → PIK3CA/BRCA → germinal por separado","Metastasiertes Prostatakarzinom: HRR-Gene/MMR → PARP/IO/Studie und Keimbahnfrage":"Cáncer de próstata metastásico: genes HRR/MMR → PARP/IO/ensayo y cuestión germinal","Metastasiertes Prostatakarzinom: H…":"Cáncer de próstata metastásico: H…","Uro-Onkologie / Molekulares Tumorboard":"Urooncología / Comité Molecular de Tumores","69-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom und radiologischem Progress nach Androgendeprivation plus neuem hormonellen Wirkstoff.":"Paciente de 69 años con cáncer de próstata metastásico resistente a la castración y progresión radiológica tras deprivación androgénica más un nuevo agente hormonal.","Gibt es einen HRR-/BRCA-Biomarker für eine PARP-Strategie? Besteht ein MMR/MSI-basierter Immuntherapiekontext? Muss eine Keimbahnabklärung folgen?":"¿Existe un biomarcador HRR/BRCA para una estrategia PARP? ¿Hay un contexto de inmunoterapia basado en MMR/MSI? ¿Debe realizarse evaluación germinal?","Therapieentscheidung in der kommenden Woche.":"Decisión terapéutica la próxima semana.","Verlauf":"Evolución","Initial lokal fortgeschrittenes Adenokarzinom; später ossäre und nodale Metastasierung, jetzt mCRPC.":"Inicialmente adenocarcinoma localmente avanzado; posteriormente metástasis óseas y ganglionares, ahora mCRPC.","ADT fortgeführt; Progress unter neuem hormonellem Wirkstoff.":"ADT mantenida; progresión con un nuevo agente hormonal.","Auf dem ursprünglichen Anforderungsschein 'unauffällig'. Im Gespräch berichtet der Patient später von einem Bruder mit Pankreaskarzinom und einem Vater mit Prostatakarzinom.":"En la solicitud original figura «sin antecedentes relevantes». Más tarde, durante la conversación, el paciente refiere un hermano con cáncer de páncreas y un padre con cáncer de próstata.","HRD-Score aus dem Ovarialkarzinom wird als universeller PARP-Test verwendet oder Tumor-BRCA und Keimbahnstatus werden gleichgesetzt.":"Se usa un score HRD del cáncer de ovario como prueba PARP universal o se equipara BRCA tumoral con estado germinal.","Stanzbiopsie einer Lebermetastase mit hochgradigem Prostataadenokarzinom.":"Biopsia con aguja gruesa de metástasis hepática con adenocarcinoma de próstata de alto grado.","NKX3.1/PSA-Kontext mit Prostataursprung vereinbar.":"Contexto NKX3.1/PSA compatible con origen prostático.","Klinische Frage":"Pregunta clínica","Therapiebiomarker im mCRPC, nicht erneute Primärdiagnostik.":"Biomarcadores terapéuticos en mCRPC, no repetir el diagnóstico primario.","BRCA/HRR, MMR/MSI und hereditäre Einordnung.":"BRCA/HRR, MMR/MSI y clasificación hereditaria.","ca. 55 %, ausreichend für NGS und MMR-IHC.":"aprox. 55 %, suficiente para NGS e IHQ MMR.","DNA":"ADN","gute Qualität.":"buena calidad.","12 Schnitte.":"12 cortes.","Methodenfalle":"Trampa metodológica","Ein unspezifischer HRD-Genomic-Scar-Score ist hier nicht der primäre etablierte Selektionsweg; gen-spezifische HRR/BRCA-Diagnostik und MMR/MSI beantworten die konkrete Frage direkter.":"Un score genómico de cicatriz HRD inespecífico no es aquí la vía primaria establecida de selección; el diagnóstico HRR/BRCA específico por genes y MMR/MSI responden de forma más directa a la pregunta concreta.","Prostata-HRR/BRCA-Status":"Estado HRR/BRCA prostático","MMR/MSI-Kontext":"Contexto MMR/MSI","HRR/BRCA":"HRR/BRCA","Pathogene BRCA2-Frameshift-Variante im Tumor, VAF 58 %, mit zusätzlichem Verlust des Wildtypallels vereinbar. Im mCRPC ist BRCA1/2 unabhängig von somatischer oder Keimbahnherkunft ein relevanter PARP-Biomarkerkontext; die konkrete Therapie richtet sich nach Vorbehandlung und aktueller Zulassung/Leitlinie.":"Variante frameshift patogénica de BRCA2 en el tumor, VAF 58 %, compatible con pérdida adicional del alelo wild type. En mCRPC, BRCA1/2, independientemente del origen somático o germinal, constituye un contexto biomarcador relevante para PARP; el tratamiento concreto depende de la terapia previa y de la autorización/guías vigentes.","Erhaltene Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expresión conservada de MLH1, PMS2, MSH2 y MSH6: pMMR.","MSS / kein MSI-H. Damit ergibt sich aus MMR/MSI in diesem Fall kein spezifischer IO-Biomarkerkontext.":"MSS / sin MSI-H. Por tanto, MMR/MSI no aporta en este caso un contexto biomarcador específico para IO.","HRD-Score":"Score HRD","Ein Genomic-Scar/HRD-Score liefert im Prostatakarzinom keine gleichwertige, etablierte Ersatzinformation für die gen-spezifische BRCA/HRR-Diagnostik. Er darf den BRCA2-Befund nicht überstimmen oder eine negative HRR-Analyse ersetzen.":"Un score genomic-scar/HRD en cáncer de próstata no aporta información sustitutiva equivalente y establecida al diagnóstico BRCA/HRR específico por genes. No debe prevalecer sobre el hallazgo BRCA2 ni sustituir un análisis HRR negativo.","Keimbahnabklärung":"Evaluación germinal","Humangenetische Beratung/Keimbahntestung wird aufgrund der pathogenen BRCA2-Variante und der Familienanamnese empfohlen. Tumor-only VAF und LOH beweisen die Keimbahnherkunft nicht.":"Se recomienda asesoramiento genético/estudio germinal por la variante patogénica BRCA2 y los antecedentes familiares. La VAF tumor-only y la LOH no demuestran origen germinal.","Klinischer Status":"Estado clínico","mCRPC mit Progress nach neuem hormonellen Wirkstoff.":"mCRPC con progresión tras un nuevo agente hormonal.","Metastasenbiopsie mit ausreichendem Tumoranteil für HRR- und MMR-Diagnostik.":"Biopsia metastásica con contenido tumoral suficiente para estudio HRR y MMR.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und Hinweis auf biallelische Inaktivierung; pMMR/MSS. Der BRCA2-Befund eröffnet einen PARP-relevanten Therapiekontext gemäß aktueller Indikation/Vorbehandlung. Die Tumoranalyse unterscheidet somatisch und Keimbahn nicht sicher; wegen BRCA2 und Familienanamnese ist eine separate humangenetische Keimbahnabklärung angezeigt. Ein HRD-Score ist kein notwendiger Ersatz für diese gen-spezifische Prostata-Diagnostik.":"mCRPC con alteración patogénica loss-of-function de BRCA2 y datos compatibles con inactivación bialélica; pMMR/MSS. El hallazgo BRCA2 abre un contexto terapéutico relevante para PARP según indicación vigente y tratamiento previo. El análisis tumoral no distingue de forma fiable origen somático de germinal; por BRCA2 y los antecedentes familiares está indicada una evaluación germinal separada en genética. Un score HRD no es un sustituto necesario de este diagnóstico prostático específico por genes.","Teilbefund: HRR/BRCA, MMR/MSI und Keimbahnfrage müssen getrennt beantwortet werden. Ein tumor-only BRCA2-Befund kann therapeutisch relevant sein, sagt aber nicht automatisch, ob die Variante vererbt ist.":"Resultado parcial: HRR/BRCA, MMR/MSI y la cuestión germinal deben responderse por separado. Un hallazgo BRCA2 tumor-only puede ser terapéuticamente relevante, pero no indica automáticamente si la variante es heredada.","BRCA2 im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen":"Integrar BRCA2 en mCRPC como contexto biomarcador PARP específico por gen","pMMR/MSS als fehlenden MMR/MSI-basierten IO-Selektionsbefund kommunizieren":"Comunicar pMMR/MSS como ausencia de un hallazgo de selección para IO basado en MMR/MSI","Tumor-BRCA2 nicht mit Keimbahn gleichsetzen; Humangenetik empfehlen":"No equiparar BRCA2 tumoral con germinal; recomendar genética","HRD-Score nicht als universellen oder zwingenden Prostata-PARP-Selektionsmarker darstellen":"No presentar el score HRD como marcador universal u obligatorio de selección PARP en próstata","Therapieempfehlung an aktuelle Zulassung, Vorbehandlung und klinischen Kontext binden":"Vincular la recomendación terapéutica a la autorización vigente, tratamiento previo y contexto clínico","Optimale Lösung: BRCA2 im Tumor als therapeutisch relevanten mCRPC-Biomarker erkennen, pMMR/MSS separat für den IO-Kontext dokumentieren, HRD-Score nicht aus dem Ovarial-Workflow übertragen und die Keimbahnfrage wegen möglicher Familienrelevanz eigenständig humangenetisch klären.":"Solución óptima: reconocer BRCA2 tumoral como biomarcador terapéuticamente relevante en mCRPC, documentar pMMR/MSS por separado para el contexto IO, no trasladar el score HRD del flujo ovárico y aclarar de forma independiente la cuestión germinal mediante genética por su posible relevancia familiar.","Prostatakarzinom":"Cáncer de próstata","mCRPC":"mCRPC","HRR":"HRR","MMR":"MMR","BRCA2 im mCRPC: therapeutisch relevant – aber ist es auch Keimbahn?":"BRCA2 en mCRPC: terapéuticamente relevante, pero ¿también es germinal?","Molekularpathologie / Uro-Onkologie / MTB":"Patología molecular / Urooncología / MTB","BRCA1/2- und HRR-Alterationen im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen.":"Integrar las alteraciones BRCA1/2 y HRR en mCRPC como contexto biomarcador PARP específico por genes.","Somatische und Keimbahn-BRCA-Alterationen therapeutisch und hereditär getrennt betrachten.":"Considerar por separado las alteraciones BRCA somáticas y germinales desde las perspectivas terapéutica y hereditaria.","MMR/MSI als eigenständigen IO-Biomarkerblock prüfen.":"Evaluar MMR/MSI como bloque biomarcador independiente para IO.","Einen ovarialkarzinomtypischen HRD-Genomic-Scar-Score nicht als universellen Pflichtmarker auf das Prostatakarzinom übertragen.":"No trasladar un score HRD genomic-scar típico de ovario al cáncer de próstata como marcador universal obligatorio.","Familienanamnese und humangenetische Weiterleitung in die MTB-Empfehlung integrieren.":"Integrar los antecedentes familiares y la derivación a genética en la recomendación del MTB.","Das Tumorpanel meldet eine pathogene BRCA2-Frameshift-Variante mit VAF 58 % und Hinweis auf Verlust des zweiten Allels. Im MTB heißt es sofort: 'Dann ist das erblich – und wir brauchen noch einen HRD-Score, bevor PARP möglich ist.' Der Fall ist ideal, um zwei häufige Ebenenfehler gleichzeitig zu korrigieren.":"El panel tumoral informa una variante frameshift patogénica de BRCA2 con VAF del 58 % y evidencia de pérdida del segundo alelo. En el MTB se dice de inmediato: «Entonces es hereditario, y todavía necesitamos un score HRD antes de poder usar PARP». El caso es ideal para corregir a la vez dos errores frecuentes de categoría.","69-jähriger Patient mit mCRPC und Progress nach neuem hormonellem Wirkstoff. Eine Lebermetastasenbiopsie steht für HRR/BRCA- und MMR/MSI-Diagnostik zur Verfügung. Gesucht wird eine Therapieempfehlung, die den tumorbezogenen BRCA2-Befund nutzt, die Keimbahnfrage separat löst und keine Ovarial-HRD-Logik auf die Prostata überträgt.":"Paciente de 69 años con mCRPC y progresión tras un nuevo agente hormonal. Se dispone de biopsia de metástasis hepática para estudio HRR/BRCA y MMR/MSI. Se busca una recomendación terapéutica que utilice el hallazgo BRCA2 tumoral, resuelva por separado la cuestión germinal y no traslade la lógica HRD ovárica al cáncer de próstata.","Therapiesituation":"Situación terapéutica","mCRPC nach Progress unter neuem hormonellem Wirkstoff.":"mCRPC tras progresión con un nuevo agente hormonal.","Der konkrete Therapiekontext macht BRCA1/2 besonders relevant.":"El contexto terapéutico concreto hace que BRCA1/2 sea especialmente relevante.","Hereditäre Ebene":"Capa hereditaria","Bruder mit Pankreas- und Vater mit Prostatakarzinom werden erst im Gespräch bekannt.":"Un hermano con cáncer de páncreas y un padre con cáncer de próstata solo se refieren durante la entrevista.","Familienanamnese verstärkt die Keimbahnindikation, ersetzt aber keine Testung.":"Los antecedentes familiares refuerzan la indicación de estudio germinal, pero no sustituyen la prueba.","IO-Ebene":"Capa IO","MMR/MSI ist zu Beginn unbekannt.":"MMR/MSI es desconocido al inicio.","DNA-Reparaturdefekt allgemein ist nicht gleich dMMR/MSI-H.":"Un defecto de reparación del ADN en general no equivale a dMMR/MSI-H.","Lebermetastase, ca. 55 % Tumor; DNA und IHC gut auswertbar.":"Metástasis hepática, aprox. 55 % de tumor; ADN e IHQ evaluables adecuadamente.","mCRPC mit Progress nach neuem hormonellem Wirkstoff.":"mCRPC con progresión tras un nuevo agente hormonal.","Im Verlauf Pankreas- und Prostatakarzinom bei nahen Angehörigen berichtet.":"Durante la evolución se refieren cáncer de páncreas y de próstata en familiares cercanos.","Gen-spezifische HRR/BRCA-Diagnostik hat für die konkrete Frage höhere Priorität als ein unspezifischer HRD-Genomic-Scar-Score.":"El estudio HRR/BRCA específico por genes tiene mayor prioridad para esta pregunta que un score HRD genomic-scar inespecífico.","Tumorgewebe enthält keine saubere Normalreferenz für die Keimbahnfrage.":"El tejido tumoral no proporciona una referencia normal limpia para la cuestión germinal.","MMR/MSI benötigt eine eigene funktionelle/biomarkerbezogene Beurteilung.":"MMR/MSI requiere su propia evaluación funcional/de biomarcadores.","Was ist der zentrale PARP-Biomarkerbefund in diesem Fall?":"¿Cuál es el hallazgo biomarcador central para PARP en este caso?","Die pathogene BRCA2-Alteration im mCRPC ist der entscheidende gen-spezifische Biomarkerkontext; die konkrete Nutzung hängt von Vorbehandlung und aktueller Indikation ab.":"La alteración patogénica de BRCA2 en mCRPC es el contexto biomarcador específico por gen decisivo; su uso concreto depende del tratamiento previo y la indicación vigente.","Nur ein positiver HRD-Score erlaubt eine PARP-Strategie.":"Solo un score HRD positivo permite una estrategia PARP.","pMMR ist der entscheidende PARP-Biomarker.":"pMMR es el biomarcador PARP decisivo.","Eine VAF über 50 % ist allein der therapeutische Biomarker.":"Una VAF superior al 50 % por sí sola es el biomarcador terapéutico.","Bei mCRPC ist die gen-spezifische BRCA1/2-Alteration zentral; ein Ovarial-HRD-Score ist kein universeller Ersatz.":"En mCRPC, la alteración BRCA1/2 específica por gen es central; un score HRD ovárico no es un sustituto universal.","Tumor-BRCA2, VAF 58 %, mit LOH: Ist damit die Keimbahnherkunft bewiesen?":"BRCA2 tumoral, VAF 58 %, con LOH: ¿demuestra esto un origen germinal?","Nein. Der Tumorbefund kann therapeutisch relevant sein, aber die Keimbahnherkunft muss aus einer geeigneten Normalprobe separat geklärt werden.":"No. El hallazgo tumoral puede ser terapéuticamente relevante, pero el origen germinal debe estudiarse por separado con una muestra normal adecuada.","Ja, VAF >50 % beweist Keimbahn.":"Sí, VAF >50 % demuestra origen germinal.","Ja, LOH beweist immer eine erbliche Variante.":"Sí, la LOH siempre demuestra una variante heredada.","Nein, Tumorvarianten können grundsätzlich nie Keimbahn sein.":"No, las variantes tumorales nunca pueden ser germinales.","Tumor-only-NGS trennt somatische und Keimbahnherkunft nicht sicher.":"El NGS tumor-only no puede distinguir de forma fiable el origen somático del germinal.","Reicht eine HRR/BRCA-Alteration als Begründung für eine MMR/MSI-basierte Immuntherapie?":"¿Es suficiente una alteración HRR/BRCA para justificar inmunoterapia basada en MMR/MSI?","Nein. MMR/MSI ist ein separater Biomarkerblock; hier zeigt pMMR/MSS keinen spezifischen MSI-basierten IO-Kontext.":"No. MMR/MSI es un bloque biomarcador separado; aquí pMMR/MSS no aporta un contexto específico de IO basado en MSI.","Ja. Jede DNA-Reparaturmutation bedeutet immunogen und ICI-sensitiv.":"Sí. Cualquier mutación de reparación del ADN implica inmunogenicidad y sensibilidad a ICI.","BRCA2 ist funktionell gleichbedeutend mit MSI-H.":"BRCA2 es funcionalmente equivalente a MSI-H.","Nur PD-L1 kann die Frage beantworten.":"Solo PD-L1 puede responder a la pregunta.","HRR und MMR sind unterschiedliche Reparaturachsen mit unterschiedlichen Biomarkerfolgen.":"HRR y MMR son vías de reparación diferentes con consecuencias biomarcadoras distintas.","Welche Rolle sollte der HRD-Score hier spielen?":"¿Qué papel debería desempeñar aquí el score HRD?","Nicht als Pflicht- oder Ersatzmarker: gen-spezifische BRCA/HRR-Diagnostik ist für diesen Prostatafall entscheidender.":"No como marcador obligatorio o sustituto: el diagnóstico BRCA/HRR específico por genes es más decisivo para este caso de próstata.","Zwingend vor jeder PARP-Diskussion.":"Obligatorio antes de cualquier discusión sobre PARP.","Er ersetzt die Keimbahnabklärung.":"Sustituye la evaluación germinal.","Er entscheidet primär über Immuntherapie.":"Determina principalmente la inmunoterapia.","Der Ovarial-HRD-Workflow darf nicht unkritisch auf mCRPC übertragen werden.":"El flujo HRD ovárico no debe trasladarse de forma acrítica al mCRPC.","Ordnen Sie BRCA2, MMR/MSI und die Keimbahnfrage beim mCRPC so ein, dass die therapeutische Relevanz des Tumorbefunds genutzt wird, ohne die hereditäre Herkunft zu behaupten oder einen HRD-Score unnötig zur Voraussetzung zu machen.":"Integrar BRCA2, MMR/MSI y la cuestión germinal en mCRPC de modo que se aproveche la relevancia terapéutica del hallazgo tumoral sin afirmar origen hereditario ni convertir innecesariamente un score HRD en requisito previo.","Validierte HRR/BRCA-Diagnostik am Tumor durchführen.":"Realizar un estudio tumoral HRR/BRCA validado.","Pathogene BRCA2-Loss-of-function-Alteration als relevanten mCRPC-Biomarkerkontext berichten.":"Informar la alteración patogénica loss-of-function de BRCA2 como contexto biomarcador relevante en mCRPC.","MMR-IHC/MSI separat prüfen: pMMR/MSS.":"Evaluar IHQ MMR/MSI por separado: pMMR/MSS.","PARP-Option an aktuelle Indikation, Vorbehandlung und klinische Eignung binden.":"Vincular la opción PARP a la indicación vigente, tratamiento previo e idoneidad clínica.","Keimbahnherkunft aus Tumor-VAF/LOH nicht ableiten; Humangenetik/Normalprobe empfehlen.":"No inferir origen germinal a partir de VAF/LOH tumoral; recomendar genética/muestra normal.","HRD-Score nicht als universellen Pflichtmarker aus dem Ovarialkarzinom übernehmen.":"No adoptar el score HRD del cáncer de ovario como marcador universal obligatorio.","Validiertes Tumor-BRCA/HRR-Panel statt Prostata-spezifischem Panel, sofern relevante HRR-Gene und Copy-number/Variantentypen ausreichend erfasst werden.":"Panel tumoral BRCA/HRR validado en lugar de un panel específico de próstata, siempre que cubra adecuadamente genes HRR relevantes y tipos de copy-number/variantes.","Breiteres validiertes Panel mit BRCA/HRR plus MSI, wenn Material und TAT vertretbar sind; funktionelle MMR-IHC kann ergänzen.":"Panel validado más amplio con BRCA/HRR más MSI si el material y el TAT lo permiten; la IHQ funcional de MMR puede complementar.","HRD-Score als Pflicht":"Score HRD como obligatorio","Überträgt einen entitätsspezifischen Ovarial-Workflow auf die Prostata.":"Traslada un flujo ovárico específico de entidad al cáncer de próstata.","Tumor-BRCA = erblich":"BRCA tumoral = hereditario","Tumor-only-NGS beweist keine Keimbahnherkunft.":"El NGS tumor-only no demuestra origen germinal.","BRCA = MSI/IO":"BRCA = MSI/IO","HRR und MMR sind verschiedene Reparaturwege und Biomarker.":"HRR y MMR son vías de reparación y biomarcadores distintos.","Familienanamnese ignorieren":"Ignorar antecedentes familiares","Ein möglicher Keimbahnbefund hat Konsequenzen für Patient und Angehörige.":"Un posible hallazgo germinal tiene consecuencias para el paciente y sus familiares.","Therapie kann schon tumorbezogen relevant sein, Familienrelevanz bleibt trotzdem offen":"El tratamiento puede ser ya relevante a nivel tumoral aunque la relevancia familiar siga sin resolver","Die BRCA2-Loss-of-function-Alteration ist im mCRPC therapeutisch relevant, auch wenn sie somatisch sein könnte. Gleichzeitig macht die aktualisierte Familienanamnese eine Keimbahnabklärung besonders wichtig. MMR-IHC und MSI sind unauffällig. Der vermeintlich noch fehlende HRD-Score ist dagegen gar nicht der zentrale nächste Schritt.":"La alteración loss-of-function de BRCA2 es terapéuticamente relevante en mCRPC aunque pudiera ser somática. Al mismo tiempo, la historia familiar actualizada hace especialmente importante el estudio germinal. La IHQ MMR y MSI son normales. Sin embargo, el score HRD supuestamente pendiente no es en absoluto el siguiente paso central.","Der Fall trennt Therapiebiomarker und Hereditätsdiagnostik: dieselbe Variante kann für die Tumortherapie relevant sein, während ihre Herkunft für die Familie separat geklärt werden muss.":"El caso separa biomarcadores terapéuticos de diagnóstico hereditario: la misma variante puede ser relevante para tratar el tumor mientras su origen debe aclararse por separado para la familia.","BRCA2 genutzt, Keimbahn sauber getrennt":"BRCA2 utilizado, germinal correctamente separado","Pathogene BRCA2-Loss-of-function-Alteration im Tumor mit Hinweis auf biallelische Inaktivierung; pMMR/MSS. PARP-relevanter mCRPC-Kontext gemäß aktueller Indikation/Vorbehandlung; separate humangenetische Keimbahnabklärung empfohlen. HRD-Score nicht als Pflichtmarker benötigt.":"Alteración patogénica loss-of-function de BRCA2 en el tumor con datos compatibles con inactivación bialélica; pMMR/MSS. Contexto mCRPC relevante para PARP según indicación vigente/tratamiento previo; se recomienda estudio germinal separado en genética. No se requiere un score HRD como marcador obligatorio.","Therapie-, IO- und Hereditätsebene korrekt getrennt.":"Capas terapéutica, IO y hereditaria correctamente separadas.","BRCA2 erkannt, Heredität offen":"BRCA2 reconocido, herencia sin resolver","BRCA2 wird therapeutisch korrekt erkannt, aber Keimbahnabklärung/Familienrelevanz nicht adressiert.":"BRCA2 se reconoce correctamente como terapéutico, pero no se aborda el estudio germinal/relevancia familiar.","Klinisch wichtige zweite Ebene fehlt.":"Falta una segunda capa clínicamente importante.","Ovarial-Workflow kopiert":"Flujo ovárico copiado","PARP-Entscheidung wird von einem HRD-Score abhängig gemacht und Tumor-BRCA2 zugleich als sicher erblich bezeichnet.":"La decisión sobre PARP se hace depender de un score HRD y, al mismo tiempo, BRCA2 tumoral se considera definitivamente hereditario.","Zwei entitätsspezifische Fehlübertragungen.":"Dos extrapolaciones erróneas específicas de entidad.","Pathogene BRCA2-Variante im Tumor":"Variante patogénica de BRCA2 en el tumor","PARP-Eignung nach aktueller Indikation/Vorbehandlung prüfen und parallel humangenetische Beratung veranlassen.":"Evaluar la elegibilidad para PARP según indicación vigente/tratamiento previo y organizar en paralelo asesoramiento genético.","Therapieentscheidung und Familienabklärung laufen koordiniert, aber diagnostisch getrennt.":"La decisión terapéutica y la evaluación familiar avanzan de forma coordinada pero diagnósticamente separada.","Keinen MSI/MMR-basierten IO-Biomarker behaupten; andere klinische IO-Indikationen nur separat bewerten.":"No afirmar un biomarcador IO basado en MSI/MMR; otras indicaciones clínicas de IO deben valorarse por separado.","DNA-Reparatur wird nicht pauschal mit Immuntherapie gleichgesetzt.":"La reparación del ADN no se equipara de forma general con inmunoterapia.","BRCA1/2 ist im mCRPC ein gen-spezifischer, therapeutisch relevanter Biomarkerkontext.":"BRCA1/2 constituye un contexto biomarcador específico por genes y terapéuticamente relevante en mCRPC.","Somatische und Keimbahn-BRCA-Alterationen sind für Therapie und Familie unterschiedliche Ebenen.":"Las alteraciones BRCA somáticas y germinales representan capas distintas para tratamiento y familia.","Tumor-VAF/LOH beweist die Keimbahn nicht.":"La VAF/LOH tumoral no demuestra origen germinal.","MMR/MSI muss unabhängig von HRR beurteilt werden.":"MMR/MSI debe evaluarse independientemente de HRR.","Ein HRD-Genomic-Scar-Score ist kein universeller Pflichtmarker für PARP über Tumorentitäten hinweg.":"Un score HRD genomic-scar no es un marcador universal obligatorio para PARP en todas las entidades tumorales.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und pMMR/MSS. BRCA2 ist tumorbezogen PARP-relevant gemäß aktueller Indikation/Vorbehandlung. Die Keimbahnherkunft ist nicht aus Tumor-VAF oder LOH ableitbar; wegen Befund und Familienanamnese Humangenetik empfehlen. Kein obligatorischer Ovarial-HRD-Score.":"mCRPC con alteración patogénica loss-of-function de BRCA2 y pMMR/MSS. BRCA2 es relevante para PARP a nivel tumoral según indicación vigente/tratamiento previo. El origen germinal no puede inferirse de VAF tumoral o LOH; recomendar genética por el hallazgo y los antecedentes familiares. Sin score HRD ovárico obligatorio.","BRCA2 tumorbezogen korrekt genutzt":"BRCA2 tumoral utilizado correctamente","MMR/MSI separat bewertet":"MMR/MSI evaluado por separado","Keimbahn nicht behauptet":"No se afirma origen germinal","HRD-Score nicht zum Pflichtmarker gemacht":"El score HRD no se convierte en obligatorio","Warum kann derselbe BRCA2-Befund therapeutisch nutzbar sein, obwohl die Keimbahnherkunft noch offen ist?":"¿Por qué el mismo hallazgo BRCA2 puede ser útil terapéuticamente aunque el origen germinal siga sin aclararse?","Welche Proben eignen sich zur Keimbahnklärung?":"¿Qué muestras son adecuadas para aclarar el estado germinal?","Warum sind HRD-Genomic-Scar-Tests nicht automatisch zwischen Tumorentitäten übertragbar?":"¿Por qué los tests HRD genomic-scar no son automáticamente transferibles entre entidades tumorales?","BRCA2 ist therapeutisch relevant, ohne dass die Keimbahn bereits geklärt ist":"BRCA2 es terapéuticamente relevante sin que el estado germinal esté ya aclarado","Therapiebiomarker und Hereditätsstatus sind getrennte Ebenen":"Biomarcador terapéutico y estado hereditario son capas separadas","HRR/BRCA → MMR/MSI separat → PARP-Kontext → Keimbahnklärung":"HRR/BRCA → MMR/MSI por separado → contexto PARP → aclaración germinal","Therapieassoziierte MDS/AML nach DNA-schädigender Therapie → Instabilität als Chance und Risiko einordnen":"MDS/AML asociada a terapia tras tratamiento dañino para el ADN → interpretar la inestabilidad como oportunidad y riesgo","Therapieassoziierte MDS/AML nach D…":"MDS/AML asociada a terapia tras D…","Hämatologie / interdisziplinäres Tumorboard":"Hematología / Comité Tumoral Interdisciplinar","67-jährige Patientin mit neu aufgetretener Pancytopenie acht Jahre nach Behandlung eines Mammakarzinoms mit zytotoxischer Chemotherapie und Radiotherapie.":"Paciente de 67 años con pancitopenia de nueva aparición ocho años después de tratar un cáncer de mama con quimioterapia citotóxica y radioterapia.","Wie werden Morphologie, Zytogenetik, molekulares Profil und die frühere zytotoxische Therapie zu einer belastbaren Diagnose- und Risikoeinschätzung integriert?":"¿Cómo integrar morfología, citogenética, perfil molecular y terapia citotóxica previa en una evaluación diagnóstica y de riesgo sólida?","Therapiebeginn nach Abschluss der hämatologischen Klassifikation.":"El tratamiento comienza tras completar la clasificación hematológica.","Anthrazyklin-/Cyclophosphamid-haltige Chemotherapie und Bestrahlung vor acht Jahren.":"Quimioterapia con antraciclina/ciclofosfamida y radioterapia hace ocho años.","Aktuell":"Hallazgos actuales","Hb 8,4 g/dl, Thrombozyten 46/nl, Neutrophile 0,7/nl; peripher 9 % Blasten.":"Hb 8,4 g/dl, plaquetas 46/nl, neutrófilos 0,7/nl; 9 % de blastos en sangre periférica.","Knochenmark":"Médula ósea","27 % myeloische Blasten, ausgeprägte Dysplasie.":"27 % de blastos mieloides, displasia marcada.","Die Vorgeschichte wird allein zur Diagnose 'therapieassoziierte AML' gemacht oder ein einzelner DNMT3A-/TET2-/ASXL1-Befund wird ohne Morphologie/Zytogenetik als Neoplasiebeweis interpretiert.":"Se usa únicamente la historia para diagnosticar «AML relacionada con terapia», o un hallazgo aislado de DNMT3A/TET2/ASXL1 se interpreta como prueba de neoplasia sin morfología/citogenética.","Morphologie + Vorbefunde":"Morfología + hallazgos previos","Hyperzellulär, 27 % Blasten, dysplastische Granulo- und Megakaryopoese.":"Hipercelular, 27 % de blastos, granulopoyesis y megacariopoyesis displásicas.","Zytogenetik":"Citogenética","Komplexer Karyotyp mit -5/del(5q), -7 und 17p-Verlust.":"Cariotipo complejo con -5/del(5q), -7 y pérdida de 17p.","Akute myeloische Neoplasie mit hochriskanter Genominstabilität; frühere zytotoxische Exposition muss als qualifizierender Kontext integriert werden.":"Neoplasia mieloide aguda con inestabilidad genómica de alto riesgo; la exposición citotóxica previa debe integrarse como contexto cualificador.","Welche Rolle spielt das molekulare Profil – und was darf daraus gerade nicht abgeleitet werden?":"¿Qué papel desempeña el perfil molecular y qué no debe inferirse de él?","EDTA-Knochenmarkaspirat plus Trepanobiopsie.":"Aspirado de médula ósea en EDTA más biopsia trepanada.","Tumorzellanteil":"Contenido tumoral","Blasten ca. 27 %; NGS aus Knochenmark geeignet.":"Blastos aprox. 27 %; médula ósea adecuada para NGS.","Vorbefunde":"Hallazgos previos","Morphologie und Zytogenetik liegen bereits vor und dürfen nicht durch NGS ersetzt werden.":"Morfología y citogenética ya están disponibles y no deben ser sustituidas por NGS.","Ein Pan-Tumorpanel mit TMB/MSI wäre für die konkrete myeloische Klassifikationsfrage Low Value; das fokussierte hämatologische Panel ist näher an der Fragestellung.":"Un panel pan-tumoral con TMB/MSI tendría poco valor para la pregunta concreta de clasificación mieloide; un panel hematológico focalizado se ajusta mejor a la cuestión clínica.","Myeloischer Molekularkontext":"Contexto molecular mieloide","Hämatologisches NGS":"NGS hematológico","TP53 p.R273H mit VAF 43 % sowie DNMT3A p.R882H mit VAF 4 %. Im Kontext von 17p-Verlust und komplexem Karyotyp ist TP53 Teil der hochriskanten Neoplasie; die niedrigfrequente DNMT3A-Alteration allein wäre dagegen kein Beweis für AML und kann klonale Hämatopoese repräsentieren.":"TP53 p.R273H con VAF 43 % y DNMT3A p.R882H con VAF 4 %. En el contexto de pérdida 17p y cariotipo complejo, TP53 forma parte de la neoplasia de alto riesgo; la alteración DNMT3A de baja frecuencia por sí sola no demostraría AML y puede representar hematopoyesis clonal.","Zusätzliche solide-tumororientierte TMB/MSI-/Pan-Cancer-Information beantwortet die zentrale myeloische Klassifikations- und Risikofrage nicht besser und erzeugt unnötige Nebenbefunde.":"La información adicional TMB/MSI/pan-cancer orientada a tumores sólidos no responde mejor a la cuestión central de clasificación y riesgo mieloide y genera hallazgos incidentales innecesarios.","Morphologie":"Morfología","27 % myeloische Blasten mit Dysplasie.":"27 % de blastos mieloides con displasia.","Exposition":"Exposición","Zytotoxische Chemotherapie/Radiotherapie acht Jahre zuvor.":"Quimioterapia citotóxica/radioterapia ocho años antes.","Akute myeloische Neoplasie mit TP53-Alteration und komplexer Zytogenetik nach vorausgegangener zytotoxischer Therapie. Die frühere Therapie ist ein wichtiger qualifizierender klinischer Kontext, die Erkrankung wird jedoch primär aus Morphologie und genetischen Merkmalen klassifiziert. Der TP53/komplexe-Karyotyp-Kontext spricht für ungünstige Biologie. Eine niedrigfrequente DNMT3A-Alteration allein wäre nicht ausreichend, um die Neoplasie zu definieren. 'Genomische Instabilität' ist hier kein pauschales Target- oder Immuntherapiesignal.":"Neoplasia mieloide aguda con alteración TP53 y citogenética compleja tras terapia citotóxica previa. El tratamiento anterior es un contexto clínico cualificador importante, pero la enfermedad se clasifica principalmente por morfología y características genéticas. El contexto TP53/cariotipo complejo indica biología adversa. Una alteración DNMT3A de baja frecuencia por sí sola no bastaría para definir la neoplasia. La «inestabilidad genómica» no es aquí una señal genérica de target o inmunoterapia.","Teilbefund: Die frühere zytotoxische Therapie erhöht die Plausibilität eines post-zytotoxischen/therapiebezogenen Kontextes, ersetzt aber nicht die aktuelle morphologische und genetische Klassifikation. CHIP-typische Varianten dürfen nicht isoliert überinterpretiert werden.":"Resultado parcial: la terapia citotóxica previa aumenta la plausibilidad de un contexto poscitotóxico/relacionado con terapia, pero no sustituye la clasificación morfológica y genética actual. Las variantes típicas de CHIP no deben sobreinterpretarse de forma aislada.","Morphologie/Genetik priorisieren und frühere zytotoxische Therapie als qualifizierenden Kontext integrieren":"Priorizar morfología/genética e integrar la terapia citotóxica previa como contexto cualificador","TP53 plus komplexen Karyotyp als hochriskante Biologie erkennen":"Reconocer TP53 más cariotipo complejo como biología de alto riesgo","Niedrigfrequentes DNMT3A nicht allein als AML-Beweis interpretieren":"No interpretar DNMT3A de baja frecuencia por sí solo como prueba de AML","Genominstabilität nicht automatisch als Target-/TMB-/IO-Chance verkaufen":"No presentar automáticamente la inestabilidad genómica como oportunidad target/TMB/IO","Hämatologische Klassifikation und Risikostratifikation nicht durch ein solides Pan-Panel ersetzen":"No sustituir clasificación hematológica y estratificación de riesgo por un pan-panel de tumores sólidos","Optimale Lösung: AML/myeloische Neoplasie aus Morphologie und Genetik klassifizieren; die frühere zytotoxische Therapie als qualifizierenden Kontext dokumentieren; TP53 plus komplexe Zytogenetik als ungünstige Biologie einordnen; niedrigfrequentes DNMT3A als potenziellen CH-Klon nicht überbewerten.":"Solución óptima: clasificar AML/neoplasia mieloide a partir de morfología y genética; documentar la terapia citotóxica previa como contexto cualificador; interpretar TP53 más citogenética compleja como biología adversa; no sobrevalorar DNMT3A de baja frecuencia, que puede representar un clon CH.","AML":"AML","post cytotoxic therapy":"post terapia citotóxica","TP53":"TP53","complex karyotype":"cariotipo complejo","clonal hematopoiesis":"hematopoyesis clonal","genomic instability":"inestabilidad genómica","Nach zytotoxischer Therapie: TP53, komplexer Karyotyp und die Falle 'Genominstabilität = Target'":"Tras terapia citotóxica: TP53, cariotipo complejo y la trampa «inestabilidad genómica = target»","Molekularpathologie / Hämatologie / Translation":"Patología molecular / Hematología / Traslación","Eine myeloische Neoplasie nach zytotoxischer Therapie primär aus aktueller Morphologie und Genetik klassifizieren und die frühere Exposition als qualifizierenden Kontext integrieren.":"Clasificar una neoplasia mieloide tras terapia citotóxica principalmente por morfología y genética actuales e integrar la exposición previa como contexto cualificador.","TP53 plus komplexe Zytogenetik als hochriskante Biologie erkennen.":"Reconocer TP53 más citogenética compleja como biología de alto riesgo.","CHIP-typische Varianten wie niedrigfrequentes DNMT3A nicht isoliert als AML-Beweis interpretieren.":"No interpretar de forma aislada variantes típicas de CHIP como DNMT3A de baja frecuencia como prueba de AML.","Das biologische Konzept 'genomische Instabilität' nicht automatisch in einen therapeutischen Target- oder Immuntherapiemarker übersetzen.":"No traducir automáticamente el concepto biológico «inestabilidad genómica» en una diana terapéutica o marcador de inmunoterapia.","Solide-tumororientierte Pan-Cancer-Tests nicht unkritisch auf eine myeloische Fragestellung übertragen.":"No trasladar acríticamente pruebas pan-cancer orientadas a tumores sólidos a una pregunta mieloide.","Acht Jahre nach Chemotherapie und Bestrahlung wegen Mammakarzinoms entwickelt die Patientin eine Pancytopenie. Das Knochenmark zeigt 27 % Blasten, der Karyotyp ist komplex. Im NGS erscheinen TP53 mit hoher und DNMT3A mit sehr niedriger VAF. Im Board fallen zwei schnelle Erklärungen: 'Die alte Chemotherapie hat die AML verursacht' und 'viel Genominstabilität bedeutet vielleicht viel Target-/IO-Potenzial'. Beide Aussagen müssen präziser werden.":"Ocho años después de quimioterapia y radioterapia por cáncer de mama, la paciente desarrolla pancitopenia. La médula muestra 27 % de blastos y el cariotipo es complejo. El NGS revela TP53 con VAF alta y DNMT3A con VAF muy baja. En el comité surgen dos explicaciones rápidas: «La quimioterapia antigua causó la AML» y «mucha inestabilidad genómica quizá signifique mucho potencial target/IO». Ambas afirmaciones necesitan mayor precisión.","67-jährige Patientin mit akuter myeloischer Neoplasie nach vorausgegangener zytotoxischer Therapie. Morphologie und komplexe Zytogenetik stehen bereits fest; das molekulare Panel soll die biologische Einordnung ergänzen. Ziel ist nicht, aus einer Exposition oder einem Einzelgen allein eine Diagnose zu konstruieren, sondern die aktuelle Erkrankung korrekt zu klassifizieren und die Genominstabilität klinisch realistisch zu bewerten.":"Paciente de 67 años con neoplasia mieloide aguda tras terapia citotóxica previa. La morfología y la citogenética compleja ya están establecidas; el panel molecular debe complementar la clasificación biológica. El objetivo no es construir un diagnóstico a partir de una exposición o un solo gen, sino clasificar correctamente la enfermedad actual y valorar clínicamente la inestabilidad genómica de forma realista.","27 % myeloische Blasten mit deutlicher Dysplasie.":"27 % de blastos mieloides con displasia marcada.","Die aktuelle Neoplasie ist morphologisch manifest; NGS ersetzt diese Ebene nicht.":"La neoplasia actual es morfológicamente manifiesta; el NGS no sustituye esta capa.","Mehrere strukturelle Verluste sprechen für hochriskante klonale Genominstabilität.":"Múltiples pérdidas estructurales indican inestabilidad genómica clonal de alto riesgo.","Zytotoxische Chemotherapie und Radiotherapie acht Jahre zuvor.":"Quimioterapia citotóxica y radioterapia ocho años antes.","Wichtiger diagnostischer Qualifier/Kontext, aber nicht die alleinige Krankheitsdefinition.":"Cualificador/contexto diagnóstico importante, pero no definición única de la enfermedad.","Blutbild":"Hemograma","Pancytopenie, peripher 9 % Blasten.":"Pancitopenia, 9 % de blastos en sangre periférica.","27 % Blasten, dysplastische Myelopoese.":"27 % de blastos, mielopoyesis displásica.","Karyotyp":"Cariotipo","Komplex mit -5/del(5q), -7 und 17p-Verlust.":"Complejo con -5/del(5q), -7 y pérdida de 17p.","Knochenmark ist für fokussiertes hämatologisches NGS geeignet.":"La médula ósea es adecuada para NGS hematológico focalizado.","Morphologie und Zytogenetik sind bereits hochinformativ und dürfen nicht durch einen molekularen Einzelmarker ersetzt werden.":"Morfología y citogenética ya son altamente informativas y no deben sustituirse por un único marcador molecular.","Ein solides Pan-Cancer-Panel mit TMB/MSI erzeugt für diese Fragestellung eher Nebeninformation als klinischen Mehrwert.":"Un panel pan-cancer de tumores sólidos con TMB/MSI generaría más información incidental que valor clínico para esta pregunta.","Wie sollte die frühere zytotoxische Therapie diagnostisch verwendet werden?":"¿Cómo debe utilizarse diagnósticamente la terapia citotóxica previa?","Als wichtiger qualifizierender Kontext einer anhand aktueller morphologischer/genetischer Merkmale klassifizierten myeloischen Neoplasie.":"Como contexto cualificador importante de una neoplasia mieloide clasificada por características morfológicas/genéticas actuales.","Allein die Exposition definiert unabhängig von aktuellen Befunden automatisch die AML-Untergruppe.":"La exposición por sí sola define automáticamente el subgrupo AML independientemente de los hallazgos actuales.","Die frühere Therapie darf in der Diagnose überhaupt nicht erwähnt werden.":"La terapia previa no debe mencionarse en absoluto en el diagnóstico.","Sie ist primär ein therapeutischer Target-Biomarker.":"Es principalmente un biomarcador diana terapéutica.","Moderne Klassifikation priorisiert die aktuelle Krankheitsbiologie; die Exposition wird als relevanter Kontext/Qualifier integriert.":"La clasificación moderna prioriza la biología actual de la enfermedad; la exposición se integra como contexto/cualificador relevante.","Wie ist TP53 VAF 43 % zusammen mit 17p-Verlust und komplexem Karyotyp zu bewerten?":"¿Cómo debe valorarse TP53 con VAF 43 % junto con pérdida 17p y cariotipo complejo?","Als Teil einer hochriskanten TP53-/komplex-karyotypischen Krankheitsbiologie, nicht als isolierter Einzelmarker.":"Como parte de una biología de enfermedad TP53/cariotipo complejo de alto riesgo, no como marcador aislado.","Als einfacher Targetmarker mit erwartbar günstiger Prognose.":"Como marcador diana simple con pronóstico favorable esperado.","Sicher nur CHIP, weil TP53 auch in klonaler Hämatopoese vorkommen kann.":"Seguro que solo es CHIP porque TP53 también puede aparecer en hematopoyesis clonal.","Zytogenetik macht molekulare Befunde irrelevant.":"La citogenética hace irrelevantes los hallazgos moleculares.","Genetischer Kontext und klonale Architektur sind entscheidend.":"El contexto genético y la arquitectura clonal son decisivos.","DNMT3A p.R882H liegt zusätzlich mit 4 % VAF vor. Was ist die beste Interpretation?":"Además se detecta DNMT3A p.R882H con VAF del 4 %. ¿Cuál es la mejor interpretación?","Ein niedrigfrequenter CH-Klon ist möglich; DNMT3A allein beweist weder AML noch erklärt es die gesamte hochriskante Erkrankung.":"Es posible un clon CH de baja frecuencia; DNMT3A por sí solo ni demuestra AML ni explica toda la enfermedad de alto riesgo.","DNMT3A definiert allein die AML.":"DNMT3A por sí solo define AML.","4 % VAF beweist eine Keimbahnmutation.":"Una VAF del 4 % demuestra una mutación germinal.","DNMT3A ist ein PARP-Biomarker.":"DNMT3A es un biomarcador PARP.","CHIP-typische Gene müssen im morphologischen und klonalen Kontext interpretiert werden.":"Los genes típicos de CHIP deben interpretarse en contexto morfológico y clonal.","Was bedeutet die ausgeprägte Genominstabilität therapeutisch?":"¿Qué significa terapéuticamente la marcada inestabilidad genómica?","Sie erklärt aggressive klonale Evolution/Risikobiologie, ist aber kein pauschaler TMB-, IO- oder Targetmarker; konkrete Alterationen und hämatologische Evidenz entscheiden.":"Explica evolución clonal agresiva/biología de riesgo, pero no es un marcador genérico TMB, IO o target; deciden las alteraciones concretas y la evidencia hematológica.","Viele Aberrationen bedeuten automatisch hohe Immuntherapie-Sensitivität.":"Muchas aberraciones significan automáticamente alta sensibilidad a inmunoterapia.","Komplexer Karyotyp ist automatisch eine PARP-Indikation.":"Un cariotipo complejo indica automáticamente PARP.","Mehr Instabilität bedeutet generell bessere Targetierbarkeit und Prognose.":"Más inestabilidad significa en general mejor posibilidad de tratamiento dirigido y mejor pronóstico.","Ein biologisches Hallmark ist nicht identisch mit einem validierten klinischen Biomarker.":"Un hallmark biológico no es idéntico a un biomarcador clínico validado.","Integrieren Sie frühere zytotoxische Therapie, Morphologie, komplexen Karyotyp und TP53/DNMT3A so, dass Diagnose-/Risikokontext und Grenzen des Begriffs 'genomische Instabilität' klar werden.":"Integrar terapia citotóxica previa, morfología, cariotipo complejo y TP53/DNMT3A para dejar claros el contexto diagnóstico/de riesgo y los límites del término «inestabilidad genómica».","Aktuelle myeloische Neoplasie aus Morphologie und Genetik einordnen.":"Clasificar la neoplasia mieloide actual por morfología y genética.","Vorausgegangene zytotoxische Therapie als relevanten post-zytotoxischen/therapiebezogenen Qualifier dokumentieren.":"Documentar la terapia citotóxica previa como cualificador poscitotóxico/relacionado con terapia relevante.","TP53 zusammen mit 17p-Verlust und komplexem Karyotyp als hochriskanten biologischen Kontext bewerten.":"Evaluar TP53 junto con pérdida 17p y cariotipo complejo como contexto biológico de alto riesgo.","Niedrigfrequentes DNMT3A nicht isoliert als AML-definierend interpretieren.":"No interpretar DNMT3A de baja frecuencia de forma aislada como definitorio de AML.","Keine pauschale PARP-/IO-/TMB-Logik aus 'Genominstabilität' ableiten.":"No inferir una lógica general PARP/IO/TMB a partir de «inestabilidad genómica».","Hämatologiespezifische Diagnostik gegenüber einem Pan-Cancer-Panel priorisieren.":"Priorizar el diagnóstico hematológico específico frente a un panel pan-cancer.","Ein umfassenderes validiertes myeloisches NGS-Panel wäre für reale Routinediagnostik sinnvoll, sofern Morphologie, Immunphänotyp und Zytogenetik integriert bleiben.":"Un panel NGS mieloide validado más completo sería adecuado en diagnóstico rutinario real, siempre que se integren morfología, inmunofenotipo y citogenética.","Bei unklarer klonaler Architektur kann eine geeignete Verlauf-/Vorprobe helfen, präexistente klonale Hämatopoese von dominanter Leukämieklonalität abzugrenzen.":"Si la arquitectura clonal no está clara, una muestra adecuada de seguimiento/previa puede ayudar a distinguir hematopoyesis clonal preexistente de clonación leucémica dominante.","Exposition = Diagnose":"Exposición = diagnóstico","Die frühere Therapie ist Kontext/Qualifier; aktuelle Morphologie und Genetik definieren die Erkrankung.":"La terapia previa es contexto/cualificador; la morfología y genética actuales definen la enfermedad.","DNMT3A = AML":"DNMT3A = AML","CHIP-typische Varianten können ohne manifeste Neoplasie vorkommen und brauchen Kontext.":"Las variantes típicas de CHIP pueden aparecer sin neoplasia manifiesta y requieren contexto.","Genominstabilität = IO/PARP":"Inestabilidad genómica = IO/PARP","Hallmark und validierter prädiktiver Biomarker sind nicht dasselbe.":"Hallmark y biomarcador predictivo validado no son lo mismo.","Pan-Cancer-TMB/MSI":"TMB/MSI pan-cancer","Für die konkrete myeloische Klassifikationsfrage ist dies kein sinnvoller Primäransatz.":"No es un enfoque primario útil para la pregunta concreta de clasificación mieloide.","Der kleine DNMT3A-Klon ist nicht die Geschichte – TP53 plus Karyotyp ist es":"El pequeño clon DNMT3A no es la historia; TP53 más el cariotipo sí","Das Panel zeigt DNMT3A p.R882H nur mit 4 % VAF, daneben TP53 p.R273H mit 43 %. Zusammen mit 17p-Verlust und komplexem Karyotyp ist TP53 Teil der dominanten hochriskanten Krankheitsbiologie. DNMT3A kann dagegen einen kleineren, möglicherweise präexistierenden CH-Klon markieren. Die 'vielen genetischen Schäden' sind hier vor allem Risikosignatur – nicht automatisch therapeutische Verwundbarkeit.":"El panel muestra DNMT3A p.R882H con solo 4 % de VAF, junto a TP53 p.R273H con 43 %. Con pérdida 17p y cariotipo complejo, TP53 forma parte de la biología dominante de alto riesgo. DNMT3A, en cambio, puede marcar un clon CH menor, posiblemente preexistente. Las «muchas lesiones genéticas» son aquí ante todo una firma de riesgo, no automáticamente una vulnerabilidad terapéutica.","Der Fall zeigt, dass Mutationsnamen ohne Klonstärke, Zytogenetik, Morphologie und klinischen Kontext leicht in die falsche Richtung führen.":"El caso muestra cómo los nombres de mutaciones, sin tamaño clonal, citogenética, morfología y contexto clínico, pueden conducir fácilmente en la dirección equivocada.","Klonale Architektur und Exposition integriert":"Arquitectura clonal y exposición integradas","Akute myeloische Neoplasie mit TP53-Alteration und komplexem Karyotyp nach zytotoxischer Therapie. TP53/17p/komplexer Karyotyp = hochriskanter dominanter Kontext; DNMT3A 4 % VAF potenziell CH-Klon. Keine pauschale Target-/IO-Aussage aus Genominstabilität.":"Neoplasia mieloide aguda con alteración TP53 y cariotipo complejo tras terapia citotóxica. TP53/17p/cariotipo complejo = contexto dominante de alto riesgo; DNMT3A VAF 4 % potencial clon CH. Sin afirmación genérica target/IO derivada de inestabilidad genómica.","Morphologie, Genetik, Exposition und Klonalität korrekt zusammengeführt.":"Morfología, genética, exposición y clonalidad correctamente integradas.","Therapieassoziiert erkannt, Genetik zu grob":"Contexto relacionado con terapia reconocido, genética demasiado burda","Die frühere Chemotherapie wird korrekt erwähnt, aber TP53 und DNMT3A werden gleichgewichtet und der komplexe Karyotyp bleibt unterbewertet.":"La quimioterapia previa se menciona correctamente, pero TP53 y DNMT3A se ponderan por igual y se infravalora el cariotipo complejo.","Klonale und prognostische Hierarchie fehlt.":"Falta la jerarquía clonal y pronóstica.","Instabilität als Therapiechance verkauft":"Inestabilidad vendida como oportunidad terapéutica","Komplexer Karyotyp und TP53 werden als unspezifischer Hinweis auf hohe TMB/IO- oder PARP-Sensitivität interpretiert.":"El cariotipo complejo y TP53 se interpretan como indicación inespecífica de TMB alto/IO o sensibilidad a PARP.","Hallmark wurde fälschlich zum prädiktiven Biomarker gemacht.":"Un hallmark se ha convertido erróneamente en biomarcador predictivo.","TP53 + komplexer Karyotyp bestätigt":"TP53 + cariotipo complejo confirmado","Hämatologische Risikostratifikation und Therapieplanung entsprechend der hochriskanten Krankheitsbiologie durchführen.":"Realizar estratificación hematológica del riesgo y planificación terapéutica según la biología de alto riesgo de la enfermedad.","Die Priorität liegt auf korrekter Klassifikation/Risiko- und Therapieplanung, nicht auf unspezifischem Pan-Cancer-Targeting.":"La prioridad es clasificación correcta/riesgo y planificación terapéutica, no targeting pan-cancer inespecífico.","niedrigfrequente CH-typische Variante":"variante típica de CH de baja frecuencia","Nur im Kontext interpretieren; bei Bedarf Verlauf/Vorproben zur Klonhistorie heranziehen.":"Interpretar solo en contexto; si es necesario, utilizar muestras de seguimiento/previas para estudiar la historia clonal.","CHIP und manifeste Neoplasie werden nicht verwechselt.":"No se confunden CHIP y neoplasia manifiesta.","Post-zytotoxische/therapiebezogene Vorgeschichte ist ein wichtiger Qualifier, nicht die alleinige Definition der aktuellen myeloischen Erkrankung.":"La historia poscitotóxica/relacionada con terapia es un cualificador importante, no la única definición de la enfermedad mieloide actual.","TP53 plus komplexer Karyotyp kennzeichnet hochriskante Biologie.":"TP53 más cariotipo complejo caracteriza una biología de alto riesgo.","Niedrige VAF in CHIP-typischen Genen kann eine kleinere Begleitklonalität darstellen.":"Una VAF baja en genes típicos de CHIP puede representar una clonación acompañante menor.","Genomische Instabilität ist ein Hallmark, aber kein universeller Target- oder Immuntherapiemarker.":"La inestabilidad genómica es un hallmark, pero no un biomarcador universal de target o inmunoterapia.","Hämatologische Diagnostik muss Morphologie, Zytogenetik und Molekulargenetik integrieren.":"El diagnóstico hematológico debe integrar morfología, citogenética y genética molecular.","Akute myeloische Neoplasie nach zytotoxischer Therapie mit dominanter TP53-/komplex-karyotypischer Hochrisikobiologie. Die Exposition wird als Qualifier integriert. DNMT3A bei 4 % VAF kann eine kleinere CH-Klonalität repräsentieren und definiert die AML nicht. Aus Genominstabilität folgt keine pauschale PARP-/IO-Indikation.":"Neoplasia mieloide aguda tras terapia citotóxica con biología dominante de alto riesgo TP53/cariotipo complejo. La exposición se integra como cualificador. DNMT3A con VAF 4 % puede representar un clon CH menor y no define AML. La inestabilidad genómica no implica una indicación general PARP/IO.","Exposition als Qualifier statt Alleindefinition":"Exposición como cualificador y no como definición única","TP53/komplexer Karyotyp priorisiert":"TP53/cariotipo complejo priorizados","DNMT3A niedrig-VAF nicht überinterpretiert":"DNMT3A de VAF baja no sobreinterpretado","Hallmark ≠ klinischer Biomarker":"Hallmark ≠ biomarcador clínico","Warum sind Therapiegeschichte und aktuelle Genetik beide wichtig, aber nicht austauschbar?":"¿Por qué son importantes tanto la historia terapéutica como la genética actual, pero no son intercambiables?","Wie hilft die VAF bei der Interpretation möglicher CH-Klone?":"¿Cómo ayuda la VAF a interpretar posibles clones CH?","Welche zusätzlichen Untersuchungen gehören real zur AML-Klassifikation, obwohl dieser Simulatorfall den Fokus enger setzt?":"¿Qué estudios adicionales forman realmente parte de la clasificación de AML aunque este caso del simulador tenga un foco más estrecho?","DNMT3A low-VAF ist Nebenklon; TP53 plus komplexer Karyotyp dominiert":"DNMT3A de VAF baja es un clon menor; domina TP53 más cariotipo complejo","Genominstabilität ist Risikobiologie, nicht automatisch Target":"La inestabilidad genómica es biología de riesgo, no automáticamente una diana","Exposition → Morphologie/Zytogenetik → TP53/DNMT3A-Klonalität → Risikokontext":"Exposición → morfología/citogenética → clonalidad TP53/DNMT3A → contexto de riesgo","„Cold Tumor“ mit wenig TILs und dichter Stromabarriere → Warum ist PD-1 allein wahrscheinlich schwach?":"«Tumor frío» con pocos TIL y barrera estromal densa → ¿Por qué es probable que PD-1 solo sea débil?","„Cold Tumor“ mit wenig TILs und di…":"«Tumor frío» con pocos TIL y ba…","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach systemischer Erstlinientherapie. Ein externer Zusatzbefund nennt PD-L1 TPS 15 % und löst die Frage nach einer PD-1-Monotherapie aus.":"Paciente de 64 años con adenocarcinoma ductal pancreático metastásico y progresión tras tratamiento sistémico de primera línea. Un informe externo complementario cita PD-L1 TPS 15 % y plantea la cuestión de monoterapia PD-1.","Ist die PD-L1-Expression hier ein belastbarer Hinweis auf Checkpoint-Sensitivität – oder spricht das gesamte Tumor-Immune-Milieu eher dagegen?":"¿Es la expresión PD-L1 aquí una señal sólida de sensibilidad a checkpoint, o el microambiente tumoral-inmune global sugiere lo contrario?","Die Zweitlinienstrategie soll im nächsten MTB festgelegt werden.":"La estrategia de segunda línea se decidirá en el próximo MTB.","Krankheitsverlauf":"Evolución de la enfermedad","Primär lokal fortgeschritten, später hepatische Metastasierung; nun radiologischer Progress.":"Inicialmente localmente avanzado, posteriormente metástasis hepática; ahora progresión radiológica.","Systemische Standardtherapie, insgesamt gute Belastbarkeit; keine bekannte Autoimmunerkrankung.":"Tratamiento sistémico estándar, buen estado general; sin enfermedad autoinmune conocida.","Externer Impuls":"Impulso externo","PD-L1 TPS 15 % wird im Zuweiserbrief als 'positiv – Immuntherapie möglich?' markiert.":"PD-L1 TPS 15 % aparece marcado en la carta de derivación como «positivo – ¿inmunoterapia posible?».","Ein exprimierter Checkpoint wird mit bereits vorhandener effektiver Antitumor-Immunität gleichgesetzt.":"Se equipara un checkpoint expresado con inmunidad antitumoral efectiva ya existente.","Duktales Adenokarzinom mit ausgeprägter desmoplastischer Stromareaktion.":"Adenocarcinoma ductal con marcada reacción estromal desmoplásica.","Immunmorphologie":"Morfología inmune","Nur wenige intraepitheliale Lymphozyten; Immunzellen liegen überwiegend stromal/peritumoral.":"Solo unos pocos linfocitos intraepiteliales; las células inmunes son predominantemente estromales/peritumorales.","PD-L1 Vorbefund":"Resultado previo de PD-L1","TPS 15 %, technisch plausibel und reproduzierbar.":"TPS 15 %, técnicamente plausible y reproducible.","MMR/MSI, TMB sowie räumlicher TIL-/Stromakontext.":"MMR/MSI, TMB y contexto espacial TIL/estroma.","FFPE-Lebermetastase, Block M4.":"Metástasis hepática FFPE, bloque M4.","ca. 35 %, nach Makrodissektion ausreichend.":"aprox. 35 %, suficiente tras macrodisección.","10 Schnitte; fokussierte IHC plus DNA-basierte Zusatzdiagnostik möglich.":"10 cortes; es posible IHQ focalizada más estudios adicionales basados en ADN.","Explorative TME-Marker können die Biologie illustrieren, sind aber kein validierter Ersatz für etablierte prädiktive Marker.":"Los marcadores exploratorios del TME pueden ilustrar la biología, pero no son un sustituto validado de los marcadores predictivos establecidos.","Etablierte immunonkologische Biomarker":"Biomarcadores inmunooncológicos establecidos","TIL-/TME-Kontext":"Contexto TIL/TME","MMR-Proteine erhalten; molekular MSS. Es liegt damit kein dMMR/MSI-H-Kontext als etablierter starker ICI-Biomarker vor.":"Proteínas MMR conservadas; molecularmente MSS. Por tanto, no existe un contexto dMMR/MSI-H como biomarcador fuerte establecido para ICI.","TMB niedrig (3,2 Mut/Mb). Der Wert liefert in diesem Fall keinen zusätzlichen Hinweis auf eine ausgeprägte Neoantigenlast.":"TMB bajo (3,2 Mut/Mb). En este caso, el valor no aporta un indicio adicional de una elevada carga de neoantígenos.","PD-L1 TPS 15 % wird bestätigt. Der Befund ist real, darf beim Pankreasadenokarzinom aber nicht isoliert als ausreichender Selektionsmarker für PD-1-Monotherapie interpretiert werden.":"Se confirma PD-L1 TPS 15 %. El hallazgo es real, pero en adenocarcinoma pancreático no debe interpretarse de forma aislada como marcador suficiente de selección para monoterapia PD-1.","Immuninfiltrat":"Infiltrado inmune","CD8-positive T-Zellen sind insgesamt spärlich und überwiegend stromal/peritumoral; nur wenige erreichen Tumorzellnester.":"Las células T CD8 positivas son escasas en conjunto y predominantemente estromales/peritumorales; solo unas pocas alcanzan los nidos tumorales.","Stromakontext":"Contexto estromal","Ausgeprägte desmoplastische, fibroblastenreiche Stromazone mit immune-excluded Muster. Der Befund illustriert eine physische/biologische Barriere, ist aber kein eigenständig validierter Therapie-Selektionsassay.":"Zona estromal desmoplásica marcada, rica en fibroblastos, con patrón immune-excluded. El hallazgo ilustra una barrera física/biológica, pero no es un ensayo validado independiente para selección terapéutica.","Ausgeprägt desmoplastisches Pankreasadenokarzinom mit wenig intratumoralen Lymphozyten.":"Adenocarcinoma pancreático marcadamente desmoplásico con pocos linfocitos intratumorales.","IHC und DNA-basierte Analysen technisch auswertbar.":"IHQ y análisis basados en ADN técnicamente evaluables.","Metastasiertes duktales Pankreasadenokarzinom mit bestätigter PD-L1-Expression, jedoch pMMR/MSS, niedriger TMB und deutlich immune-excluded/desmoplastischem Mikromilieu. PD-L1 allein begründet hier keine belastbare PD-1-Monotherapie-Strategie. TIL-/Stromamarker erklären die biologische Plausibilität eines 'cold/excluded' Tumors, sind aber selbst keine validierten Selektionsmarker.":"Adenocarcinoma ductal pancreático metastásico con expresión PD-L1 confirmada, pero pMMR/MSS, TMB bajo y microambiente claramente immune-excluded/desmoplásico. PD-L1 por sí solo no proporciona aquí una base sólida para una estrategia de monoterapia PD-1. Los marcadores TIL/estromales explican la plausibilidad biológica de un tumor «cold/excluded», pero no son por sí mismos marcadores de selección validados.","Teilbefund: PD-L1 ist exprimiert, aber ohne MMR/MSI/TMB- und räumlichen TIL-Kontext bleibt die Aussage zur Checkpoint-Sensitivität unvollständig.":"Resultado parcial: PD-L1 se expresa, pero sin MMR/MSI/TMB y contexto espacial de TIL, la valoración de sensibilidad a checkpoint sigue incompleta.","PD-L1 als Kontextmarker, nicht als alleinige Therapieentscheidung behandeln":"Tratar PD-L1 como marcador de contexto, no como única decisión terapéutica","pMMR/MSS und niedrige TMB als fehlende starke ICI-Signale benennen":"Señalar pMMR/MSS y TMB bajo como ausencia de señales fuertes para ICI","immune-excluded/desmoplastisches Muster biologisch erklären":"Explicar biológicamente el patrón immune-excluded/desmoplásico","TME-IHC nicht als validierten Therapie-Selektionsassay verkaufen":"No presentar la IHQ del TME como ensayo validado de selección terapéutica","Falschaussage: PD-L1-Positivität beweist eine ausreichende Effektor-T-Zell-Antwort":"Afirmación falsa: la positividad PD-L1 demuestra una respuesta adecuada de células T efectoras","Optimale Lösung: PD-L1 15 % nicht isoliert interpretieren; pMMR/MSS, niedrige TMB und das immune-excluded/desmoplastische Muster integrieren. Die TME-Befunde erklären die biologische Barriere, ersetzen aber keine klinisch validierten Biomarker oder leitliniengerechte Therapieentscheidung.":"Solución óptima: no interpretar PD-L1 15 % de forma aislada; integrar pMMR/MSS, TMB bajo y el patrón immune-excluded/desmoplásico. Los hallazgos del TME explican la barrera biológica, pero no sustituyen biomarcadores validados clínicamente ni decisiones terapéuticas basadas en guías.","Pankreasadenokarzinom":"Adenocarcinoma pancreático","TMB-low":"TMB-low","TILs":"TIL","TME":"TME","Desmoplasie":"Desmoplasia","Immune exclusion":"Exclusión inmune","PD-L1 vorhanden, aber die T-Zellen kommen nicht hinein: immune-excluded Pankreasadenokarzinom":"PD-L1 presente, pero las células T no entran: adenocarcinoma pancreático immune-excluded","Molekularpathologie / Gastroonkologie / MTB":"Patología molecular / Oncología gastrointestinal / MTB","PD-L1-Expression von einer tatsächlich inflamed/hot Tumormikroumgebung unterscheiden.":"Distinguir la expresión PD-L1 de un microambiente tumoral realmente inflamed/hot.","MMR/MSI und TMB als etabliertere immunonkologische Biomarker gegenüber explorativen TME-Markern priorisieren.":"Priorizar MMR/MSI y TMB como biomarcadores inmunooncológicos más establecidos frente a marcadores exploratorios del TME.","Ein immune-excluded Muster aus Morphologie, TIL-Verteilung und desmoplastischem Stroma ableiten.":"Inferir un patrón immune-excluded a partir de morfología, distribución de TIL y estroma desmoplásico.","Verstehen, dass Stromabarriere/TIL-IHC die Biologie erklären, aber keine validierte Therapie-Selektion ersetzen.":"Comprender que la barrera estromal/IHQ de TIL explica la biología, pero no sustituye una selección terapéutica validada.","PD-1-Monotherapie nicht allein aus einem PD-L1-positiven Befund ableiten.":"No inferir monoterapia PD-1 únicamente de un hallazgo PD-L1 positivo.","Im Zuweiserbrief steht fett: 'PD-L1 TPS 15 % – Immuntherapie?' Auf dem HE sieht der Tumor jedoch fast wie eine Festung aus: breite desmoplastische Stromazonen, wenige T-Zellen und kaum Lymphozyten in den Tumorzellnestern. Der Fall zwingt zur Frage, ob ein exprimierter Checkpoint überhaupt etwas nützt, wenn kaum aktivierbare Effektor-T-Zellen den Tumor erreichen.":"En la carta de derivación aparece en negrita: «PD-L1 TPS 15 % – ¿inmunoterapia?». Sin embargo, en HE el tumor parece casi una fortaleza: amplias zonas estromales desmoplásicas, pocas células T y apenas linfocitos en los nidos tumorales. El caso obliga a preguntarse si un checkpoint expresado sirve de algo cuando pocas células T efectoras activables alcanzan el tumor.","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach Erstlinientherapie. Ein externer PD-L1-Befund ist positiv. Im MTB soll geklärt werden, ob daraus eine belastbare PD-1-Monotherapie-Strategie folgt und welche Bedeutung das auffallend desmoplastische, lymphozytenarme Mikromilieu besitzt.":"Paciente de 64 años con adenocarcinoma ductal pancreático metastásico y progresión tras primera línea. Un resultado externo de PD-L1 es positivo. El MTB debe determinar si esto sustenta una estrategia sólida de monoterapia PD-1 y qué significado tiene el llamativo microambiente desmoplásico y pobre en linfocitos.","Verlockender Einzelmarker":"Marcador único tentador","PD-L1 TPS 15 % ist technisch reproduzierbar.":"PD-L1 TPS 15 % es técnicamente reproducible.","Ein real positiver Marker kann trotzdem im falschen Entitäts-/Biologiekontext wenig prädiktive Aussage besitzen.":"Un marcador realmente positivo puede tener aun así poco valor predictivo en el contexto incorrecto de entidad/biología.","Morphologisches Gegenargument":"Contraargumento morfológico","Breite Desmoplasie, wenige intratumorale TILs.":"Desmoplasia extensa, pocos TIL intratumorales.","Checkpoint-Blockade reaktiviert vorhandene Immunantwort; sie erzeugt nicht automatisch eine fehlende T-Zell-Infiltration.":"El bloqueo de checkpoint reactiva una respuesta inmune existente; no crea automáticamente una infiltración de células T ausente.","Validierte vs. explorative Ebene":"Capa validada vs exploratoria","MMR/MSI/TMB können klinisch validierte Signale liefern; TME-IHC illustriert Mechanismen.":"MMR/MSI/TMB pueden aportar señales validadas clínicamente; la IHQ del TME ilustra mecanismos.","Mechanistische Plausibilität und validierter Therapiebiomarker sind nicht dasselbe.":"La plausibilidad mecanística y un biomarcador terapéutico validado no son lo mismo.","PDAC mit ausgeprägter Desmoplasie und wenig intratumoralen Lymphozyten.":"PDAC con marcada desmoplasia y pocos linfocitos intratumorales.","TPS 15 %, reproduzierbar.":"TPS 15 %, reproducible.","Metastasenblock mit ca. 35 % Tumoranteil; fokussierte Zusatzdiagnostik möglich.":"Bloque metastásico con aprox. 35 % de tumor; estudios adicionales focalizados posibles.","Nur zehn Schnitte: explorative Zusatz-IHC muss einen klaren didaktischen/biologischen Nutzen haben.":"Solo diez cortes: la IHQ exploratoria adicional debe tener un claro valor didáctico/biológico.","TME-/Stroma-IHC ist in diesem Fall bewusst eine mechanistische Zusatzebene, kein validierter Companion-Diagnostic-Ersatz.":"La IHQ TME/estromal es deliberadamente una capa mecanística adicional en este caso, no un sustituto validado de companion diagnostic.","MMR/MSI/TMB müssen gegenüber breit gestreuter Immun-IHC priorisiert werden, wenn die Therapiefrage im Vordergrund steht.":"MMR/MSI/TMB deben priorizarse frente a una IHQ inmune amplia cuando la pregunta terapéutica es central.","Was bedeutet PD-L1 TPS 15 % in diesem PDAC am ehesten?":"¿Qué significa más probablemente PD-L1 TPS 15 % en este PDAC?","Der Befund ist biologisch real, reicht aber ohne entitätsspezifisch validierten Kontext nicht für eine belastbare PD-1-Monotherapie-Entscheidung.":"El hallazgo es biológicamente real, pero sin un contexto validado específico de entidad no basta para una decisión sólida de monoterapia PD-1.","Jede PD-L1-Positivität ist tumoragnostisch eine ICI-Indikation.":"Cualquier positividad PD-L1 es una indicación tumor-agnostic para ICI.","PD-L1 kann bei PDAC technisch nicht gemessen werden.":"PD-L1 no puede medirse técnicamente en PDAC.","PD-L1 15 % beweist automatisch TMB-high.":"PD-L1 15 % demuestra automáticamente TMB-high.","PD-L1-Expression ist nicht tumoragnostisch gleichbedeutend mit validierter Checkpoint-Sensitivität.":"La expresión PD-L1 no es sinónimo tumor-agnostic de sensibilidad validada a checkpoint.","Wodurch ist ein immune-excluded Muster am besten charakterisiert?":"¿Qué caracteriza mejor un patrón immune-excluded?","Immunzellen sind vorhanden, bleiben aber überwiegend im Stroma/peritumoral und erreichen Tumorzellnester nur schlecht.":"Las células inmunes están presentes, pero permanecen predominantemente en el estroma/peritumoral y alcanzan mal los nidos tumorales.","Dichtes intraepitheliales CD8-Infiltrat in allen Tumorarealen.":"Infiltrado CD8 intraepitelial denso en todas las áreas tumorales.","Jeder immune-excluded Tumor ist automatisch MSI-H.":"Todo tumor immune-excluded es automáticamente MSI-H.","PD-L1-Expression allein definiert immune exclusion.":"La expresión PD-L1 por sí sola define immune exclusion.","Die räumliche Verteilung der Immunzellen ist zentral; 'vorhanden' ist nicht gleich 'im Tumor wirksam'.":"La distribución espacial de las células inmunes es central; «presente» no equivale a «efectivo dentro del tumor».","Welche Zusatzdiagnostik sollte für die klinische IO-Frage priorisiert werden?":"¿Qué estudios adicionales deben priorizarse para la pregunta clínica de IO?","MMR/MSI und ggf. TMB als etabliertere Biomarker; TME-IHC nur ergänzend/mechanistisch.":"MMR/MSI y, cuando proceda, TMB como biomarcadores más establecidos; IHQ del TME solo como complemento/mecanística.","Nur CAF-/Stroma-IHC, da diese allein die Therapie festlegt.":"Solo IHQ CAF/estromal, ya que esto por sí solo determina el tratamiento.","PD-L1 mehrfach wiederholen, bis ein höherer Wert entsteht.":"Repetir PD-L1 hasta obtener un valor mayor.","Keine weitere Kontextdiagnostik; TPS 15 % reicht.":"Sin más estudios de contexto; TPS 15 % es suficiente.","Explorative TME-Marker dürfen validierte Biomarker nicht ersetzen.":"Los marcadores exploratorios del TME no deben sustituir biomarcadores validados.","Wie darf der desmoplastische/TIL-arme Befund im MTB verwendet werden?":"¿Cómo puede utilizarse en el MTB el hallazgo desmoplásico/pobre en TIL?","Als biologische Erklärung für geringe Checkpoint-Sensitivität bzw. immune exclusion – nicht als eigenständiger validierter Therapieausschlusstest.":"Como explicación biológica de baja sensibilidad a checkpoint o immune exclusion, no como prueba independiente validada para excluir tratamiento.","Als absolute Kontraindikation gegen jede Immuntherapie.":"Como contraindicación absoluta para cualquier inmunoterapia.","Als Beweis für einen zugelassenen CAF-Target-Standard.":"Como prueba de un estándar aprobado dirigido a CAF.","Morphologie und TIL-Verteilung sind grundsätzlich bedeutungslos.":"Morfología y distribución de TIL carecen por principio de relevancia.","Der TME-Befund ist mechanistisch stark, klinisch aber nicht als alleiniger Selektionsassay validiert.":"El hallazgo del TME es mecanísticamente sólido, pero no está validado clínicamente como ensayo único de selección.","Formulieren Sie die MTB-Kernaussage so, dass PD-L1, pMMR/MSS/TMB und das immune-excluded/desmoplastische Muster hierarchisch korrekt integriert werden, ohne explorative TME-Befunde zu einem Companion Diagnostic aufzuwerten.":"Formule la conclusión central del MTB integrando PD-L1, pMMR/MSS/TMB y el patrón immune-excluded/desmoplásico en la jerarquía correcta, sin elevar los hallazgos exploratorios del TME a companion diagnostic.","PD-L1 TPS 15 % als realen, aber nicht ausreichenden Einzelbefund anerkennen.":"Reconocer PD-L1 TPS 15 % como un hallazgo real pero insuficiente por sí solo.","MMR/MSI prüfen: pMMR/MSS.":"Evaluar MMR/MSI: pMMR/MSS.","TMB als niedrig einordnen.":"Clasificar TMB como bajo.","Räumlich spärliches CD8-Infiltrat und Desmoplasie als immune-excluded TME beschreiben.":"Describir la infiltración CD8 espacialmente escasa y la desmoplasia como TME immune-excluded.","PD-1-Monotherapie nicht allein aus PD-L1 ableiten.":"No inferir monoterapia PD-1 solo a partir de PD-L1.","TME-IHC als mechanistische Zusatzinformation, nicht als validierten Selektionsmarker berichten.":"Informar la IHQ del TME como información mecanística adicional, no como marcador de selección validado.","MMR-IHC plus MSI-Test und TMB aus einem validierten breiteren Panel, sofern Material und TAT dies erlauben.":"IHQ MMR más estudio MSI y TMB a partir de un panel validado más amplio, si material y TAT lo permiten.","Auf zusätzliche Stroma-IHC verzichten, wenn die Morphologie die immune exclusion bereits überzeugend zeigt und die klinisch validierten Biomarker priorisiert werden.":"Omitir IHQ estromal adicional si la morfología ya demuestra convincentemente immune exclusion y se priorizan biomarcadores validados clínicamente.","PD-L1 = ICI":"PD-L1 = ICI","Die prädiktive Bedeutung von PD-L1 ist entitäts- und therapiespezifisch.":"La significación predictiva de PD-L1 es específica de entidad y terapia.","CAF-IHC als Companion Diagnostic":"IHQ CAF como companion diagnostic","Mechanistische TME-Marker sind hier nicht als eigenständige Therapie-Selektion validiert.":"Los marcadores mecanísticos del TME no están validados aquí como herramientas independientes de selección terapéutica.","TIL-arm = absolute Resistenz":"Pocos TIL = resistencia absoluta","Biologische Wahrscheinlichkeit ist keine absolute patientenindividuelle Ausschlussregel.":"La probabilidad biológica no es una regla absoluta de exclusión para un paciente concreto.","TMB/MSI ignorieren":"Ignorar TMB/MSI","Damit würden etabliertere immunonkologische Biomarker ausgelassen.":"Así se omitirían biomarcadores inmunooncológicos más establecidos.","Der 'positive' Marker sitzt auf einem biologisch kalten Tumor":"El marcador «positivo» está sobre un tumor biológicamente frío","PD-L1 TPS 15 % wird bestätigt – gleichzeitig ist der Tumor pMMR/MSS, TMB-low und zeigt nur wenige CD8-T-Zellen, die überwiegend im desmoplastischen Stroma stecken bleiben. Der vermeintlich positive Einzelmarker kippt dadurch nicht ins 'falsch', sondern bekommt die richtige Hierarchie: biologischer Kontextmarker statt Therapie-Schalter.":"Se confirma PD-L1 TPS 15 %; al mismo tiempo el tumor es pMMR/MSS, TMB-low y muestra pocas células T CD8, en gran parte atrapadas en el estroma desmoplásico. El marcador único aparentemente positivo no se vuelve «incorrecto», sino que adquiere la jerarquía adecuada: marcador de contexto biológico y no interruptor terapéutico.","Der Fall trennt Expression eines Checkpoints von einer vorhandenen effektiven Antitumor-Immunantwort und zeigt, warum räumliche TME-Biologie die Interpretation verändert.":"El caso separa expresión de checkpoint de una respuesta inmune antitumoral efectiva ya existente y muestra por qué la biología espacial del TME cambia la interpretación.","PD-L1 im richtigen TME-Kontext":"PD-L1 en el contexto TME correcto","PD-L1 TPS 15 %, pMMR/MSS, TMB 3,2 Mut/Mb, CD8-arm/immune-excluded mit ausgeprägter Desmoplasie. Kein belastbarer Grund für PD-1-Monotherapie allein aus PD-L1; TME-Befund mechanistisch, nicht als Companion Diagnostic.":"PD-L1 TPS 15 %, pMMR/MSS, TMB 3,2 Mut/Mb, pobre en CD8/immune-excluded con marcada desmoplasia. Sin base sólida para monoterapia PD-1 solo por PD-L1; hallazgo TME mecanístico, no companion diagnostic.","Validierte Biomarker und TME-Biologie korrekt hierarchisiert.":"Biomarcadores validados y biología TME correctamente jerarquizados.","Cold erkannt, Biomarkerhierarchie unklar":"Patrón frío reconocido, jerarquía de biomarcadores poco clara","Desmoplasie und wenige TILs werden beschrieben, MMR/MSI/TMB aber nicht integriert.":"Se describen desmoplasia y pocos TIL, pero no se integran MMR/MSI/TMB.","Biologisch plausibel, klinisch unvollständig.":"Biológicamente plausible, clínicamente incompleto.","PD-L1 als universeller IO-Schalter":"PD-L1 como interruptor universal de IO","TPS 15 % wird als ausreichende tumoragnostische ICI-Indikation interpretiert.":"TPS 15 % se interpreta como una indicación ICI tumor-agnostic suficiente.","Entitätsspezifische Biomarkerlogik übergangen.":"Se omite la lógica de biomarcadores específica de entidad.","pMMR/MSS und TMB-low bestätigt":"pMMR/MSS y TMB-low confirmados","Therapieplanung auf etablierte PDAC-Strategien bzw. passende Studien fokussieren; PD-L1 nicht isoliert übergewichten.":"Centrar la planificación terapéutica en estrategias establecidas para PDAC o ensayos apropiados; no sobreponderar PD-L1 de forma aislada.","Der Fall bleibt evidenzbasiert statt biomarkergetrieben spekulativ.":"El caso se mantiene basado en evidencia y no especulativo impulsado por biomarcadores.","TME-/Stromaforschung diskutiert":"Investigación TME/estromal discutida","Studienoptionen klar als experimentell kennzeichnen.":"Etiquetar claramente las opciones de ensayo como experimentales.","Mechanistische Hypothesen werden von Routineempfehlungen getrennt.":"Las hipótesis mecanísticas se separan de las recomendaciones rutinarias.","PD-L1-Expression ist nicht gleichbedeutend mit vorhandener effektiver T-Zell-Antwort.":"La expresión PD-L1 no es sinónimo de una respuesta efectiva de células T ya existente.","Immune exclusion beschreibt die räumliche Barriere zwischen Immunzellen und Tumorzellnestern.":"Immune exclusion describe la barrera espacial entre células inmunes y nidos tumorales.","pMMR/MSS und niedrige TMB liefern hier keine starken etablierten Immunogenitätssignale.":"pMMR/MSS y TMB bajo no aportan aquí señales fuertes y establecidas de inmunogenicidad.","TME-/CAF-/TIL-Marker können Mechanismen erklären, sind aber nicht automatisch validierte Therapie-Selektionstests.":"Los marcadores TME/CAF/TIL pueden explicar mecanismos, pero no son automáticamente pruebas validadas de selección terapéutica.","Der klinische Wert eines Biomarkers hängt von Entität, Therapie und Evidenzniveau ab.":"El valor clínico de un biomarcador depende de entidad, terapia y nivel de evidencia.","PD-L1 TPS 15 % ist kein ausreichender Monotherapie-Schalter. Der Tumor ist pMMR/MSS und TMB-low; morphologisch/IHC zeigt sich ein deutlich immune-excluded, desmoplastisches TME. Das erklärt biologisch eine geringe Wahrscheinlichkeit effektiver Checkpoint-Reaktivierung, darf aber nicht als absoluter Ausschlusstest oder validierter Companion Diagnostic formuliert werden.":"PD-L1 TPS 15 % no es un interruptor suficiente para monoterapia. El tumor es pMMR/MSS y TMB-low; morfológicamente/IHQ muestra un TME claramente immune-excluded y desmoplásico. Esto explica biológicamente una baja probabilidad de reactivación efectiva del checkpoint, pero no debe formularse como prueba absoluta de exclusión ni como companion diagnostic validado.","PD-L1 nicht überinterpretiert":"PD-L1 no sobreinterpretado","MMR/MSI/TMB priorisiert":"MMR/MSI/TMB priorizados","immune-excluded räumlich verstanden":"immune-excluded comprendido espacialmente","TME-Marker als explorativ begrenzt":"Marcadores TME limitados como exploratorios","Warum kann PD-L1 exprimiert sein, obwohl kaum T-Zellen im Tumor sitzen?":"¿Por qué puede expresarse PD-L1 aunque apenas haya células T dentro del tumor?","Was unterscheidet immune-desert von immune-excluded?":"¿Qué diferencia immune-desert de immune-excluded?","Welche TME-Marker sind mechanistisch interessant, aber nicht routineprädiktiv validiert?":"¿Qué marcadores del TME son interesantes mecanísticamente pero no están validados como predictivos de rutina?","PD-L1 positiv, aber pMMR/MSS/TMB-low + immune-excluded":"PD-L1 positivo, pero pMMR/MSS/TMB-low + immune-excluded","Checkpoint-Expression braucht einen validierten Entitäts- und Immunitätskontext":"La expresión de checkpoint requiere un contexto validado de entidad e inmunidad","PD-L1 → MMR/MSI/TMB → räumliche TILs → TME-Limitation":"PD-L1 → MMR/MSI/TMB → TIL espaciales → limitación TME","PD-L1 positiv, aber niedrige TMB und kein Immuninfiltrat → PD-L1 nicht überinterpretieren":"PD-L1 positivo, pero TMB bajo y sin infiltrado inmune → no sobreinterpretar PD-L1","PD-L1 positiv, aber niedrige TMB u…":"PD-L1 positivo, pero TMB bajo y…","61-jährige Patientin mit metastasiertem kolorektalem Adenokarzinom nach Progress unter mehreren Standardtherapien. In einer Metastasenbiopsie wird PD-L1 CPS 25 berichtet.":"Paciente de 61 años con adenocarcinoma colorrectal metastásico tras progresión con varias terapias estándar. En una biopsia metastásica se informa PD-L1 CPS 25.","Kann die hohe PD-L1-Expression trotz fehlender klassischer Immunogenitätsmarker eine PD-1-Monotherapie begründen?":"¿Puede una alta expresión PD-L1 justificar monoterapia PD-1 pese a la ausencia de marcadores clásicos de inmunogenicidad?","Es wird nach einer weiteren systemischen Option gesucht; Studienzugang wird parallel geprüft.":"Se busca una opción sistémica adicional; en paralelo se evalúa acceso a ensayos.","Primarius":"Tumor primario","Linksseitiges Kolonkarzinom, inzwischen hepatisch und pulmonal metastasiert.":"Cáncer de colon izquierdo, actualmente metastásico a hígado y pulmón.","Fluoropyrimidin/Oxaliplatin, Irinotecan-basierte Therapie und weitere leitliniengerechte Linien.":"Fluoropirimidina/oxaliplatino, tratamiento basado en irinotecán y otras líneas conforme a guías.","Außenbefund":"Informe externo","PD-L1 CPS 25 wird auf dem Deckblatt fett hervorgehoben.":"PD-L1 CPS 25 aparece destacado en negrita en la portada.","Ein 'positiver' Marker wird aus einer anderen Tumorentität in den CRC-Kontext übertragen, obwohl die prädiktive Hierarchie dort anders ist.":"Un marcador «positivo» se traslada desde otra entidad tumoral al contexto CRC aunque allí la jerarquía predictiva es diferente.","Kolorektales Adenokarzinom, mäßig differenziert; keine ausgeprägt lymphozytenreiche Morphologie.":"Adenocarcinoma colorrectal moderadamente diferenciado; sin morfología marcadamente rica en linfocitos.","CPS 25, überwiegend durch PD-L1-positive Immunzellen an Nekrose-/Stromagrenzen mitgetragen.":"CPS 25, impulsado predominantemente por células inmunes PD-L1 positivas en interfaces necrosis/estroma.","Nur spärliche intratumorale CD8-positive Lymphozyten.":"Solo escasos linfocitos CD8 positivos intratumorales.","MMR/MSI und TMB als entitätsspezifisch relevanter immunonkologischer Kontext.":"MMR/MSI y TMB como contexto inmunooncológico relevante para la entidad.","FFPE-Lebermetastase, Block H2.":"Metástasis hepática FFPE, bloque H2.","ca. 50 %, gut geeignet.":"aprox. 50 %, bien adecuado.","PD-L1 ist technisch messbar, seine prädiktive Bedeutung ist aber entitäts- und therapiespezifisch; ein numerisch hoher Score ist nicht automatisch ein universeller IO-Biomarker.":"PD-L1 es técnicamente medible, pero su significado predictivo es específico de entidad y terapia; un score numéricamente alto no es automáticamente un biomarcador IO universal.","Immunonkologischer Kontext":"Contexto inmunooncológico","Erhaltene nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expresión nuclear conservada de MLH1, PMS2, MSH2 y MSH6: pMMR.","MSS. Damit fehlt der für mCRC etablierte dMMR/MSI-H-Immuntherapiekontext.":"MSS. Por tanto, falta el contexto de inmunoterapia dMMR/MSI-H establecido para mCRC.","TMB niedrig (4,0 Mut/Mb).":"TMB bajo (4,0 Mut/Mb).","PD-L1 CPS 25 bestätigt. Die Expression ist biologisch real, aber im pMMR/MSS-mCRC kein Ersatz für einen validierten MSI/dMMR-basierten Selektionsmarker.":"PD-L1 CPS 25 confirmado. La expresión es biológicamente real, pero en mCRC pMMR/MSS no sustituye un marcador validado de selección basado en MSI/dMMR.","TIL-Kontext":"Contexto TIL","Nur wenige intratumorale CD8-positive T-Zellen; kein ausgeprägt inflamed/hot pattern.":"Solo unas pocas células T CD8 positivas intratumorales; sin patrón inflamed/hot marcado.","Kernausgangslage":"Situación de partida","PD-L1 CPS 25 bei mCRC ohne morphologisch ausgeprägtes Immuninfiltrat.":"PD-L1 CPS 25 en mCRC sin infiltrado inmune morfológicamente prominente.","MMR-IHC, MSI und DNA-basierte Zusatzanalysen technisch verwertbar.":"IHQ MMR, MSI y análisis adicionales basados en ADN técnicamente utilizables.","Metastasiertes CRC mit realer PD-L1-Expression, aber pMMR/MSS, niedriger TMB und spärlichem intratumoralem T-Zell-Infiltrat. PD-L1-Positivität allein begründet in diesem Kontext keine etablierte PD-1-Monotherapie. Für mCRC besitzt dMMR/MSI-H eine deutlich stärkere und validierte prädiktive Rolle; experimentelle Kombinationen bei pMMR/MSS gehören in einen Studien-/Evidenzkontext.":"CRC metastásico con expresión PD-L1 real, pero pMMR/MSS, TMB bajo y escaso infiltrado intratumoral de células T. La positividad PD-L1 por sí sola no justifica en este contexto una monoterapia PD-1 establecida. En mCRC, dMMR/MSI-H tiene un papel predictivo mucho más fuerte y validado; las combinaciones experimentales en pMMR/MSS pertenecen al contexto de ensayo/evidencia.","Teilbefund: PD-L1 ist hoch, aber ohne MMR/MSI-Kontext ist die Übertragbarkeit auf eine Therapieentscheidung nicht belastbar.":"Resultado parcial: PD-L1 es alto, pero sin contexto MMR/MSI su traslado a una decisión terapéutica no es sólido.","PD-L1-Bedeutung entitätsspezifisch einordnen":"Interpretar el significado de PD-L1 de forma específica para la entidad","pMMR/MSS als entscheidenden Gegenbefund zur einfachen PD-L1-Logik benennen":"Señalar pMMR/MSS como hallazgo decisivo contra la lógica simple de PD-L1","niedrige TMB und spärliches Infiltrat als zusätzliche Kontextmarker integrieren":"Integrar TMB bajo e infiltrado escaso como marcadores contextuales adicionales","pMMR/MSS-IO-Kombinationen nicht mit etablierter Monotherapie gleichsetzen":"No equiparar combinaciones IO en pMMR/MSS con monoterapia establecida","Falschaussage: Hoher PD-L1-Score ist tumoragnostisch immer prädiktiv":"Afirmación falsa: un score PD-L1 alto siempre es predictivo de forma tumor-agnostic","Optimale Lösung: PD-L1 CPS 25 ist kein universeller IO-Schalter. Im pMMR/MSS-mCRC mit niedriger TMB und wenig TILs darf der Score die entitätsspezifisch validierte Biomarkerhierarchie nicht überstimmen; experimentelle Strategien gehören in Studien.":"Solución óptima: PD-L1 CPS 25 no es un interruptor IO universal. En mCRC pMMR/MSS con TMB bajo y pocos TIL, el score no debe prevalecer sobre la jerarquía de biomarcadores validada específicamente para la entidad; las estrategias experimentales pertenecen a ensayos.","TIL-low":"TIL-low","Immuntherapie":"Inmunoterapia","Biomarkerhierarchie":"Jerarquía de biomarcadores","PD-L1 CPS 25 und trotzdem kein ICI-Biomarker: MSS-mCRC als Überinterpretationsfalle":"PD-L1 CPS 25 y aun así sin biomarcador ICI: mCRC MSS como trampa de sobreinterpretación","PD-L1 als entitätsabhängigen und nicht tumoragnostischen Biomarker verstehen.":"Comprender PD-L1 como biomarcador dependiente de la entidad y no tumor-agnostic.","Beim mCRC dMMR/MSI-H gegenüber PD-L1 als prädiktiv stärker validierten IO-Kontext priorisieren.":"En mCRC, priorizar dMMR/MSI-H frente a PD-L1 como contexto IO predictivo más sólidamente validado.","pMMR/MSS, niedrige TMB und TIL-Armut als konsistente Gegenkonstellation zu einer simplen PD-L1-Logik integrieren.":"Integrar pMMR/MSS, TMB bajo y escasez de TIL como una constelación coherente contra la lógica simple de PD-L1.","PD-L1-Score und zelluläre Quelle/Spatial Context nicht mit universeller Therapieindikation verwechseln.":"No confundir score PD-L1 y fuente celular/contexto espacial con una indicación terapéutica universal.","Experimentelle ICI-Kombinationen im pMMR/MSS-mCRC von etablierter Monotherapie unterscheiden.":"Distinguir combinaciones ICI experimentales en mCRC pMMR/MSS de monoterapia establecida.","Der Außenbefund klingt spektakulär: PD-L1 CPS 25. Im Tumorboard kommt sofort die Frage nach Pembrolizumab. Doch die Histologie ist lymphozytenarm, die MMR-Proteine sind erhalten und der Tumor ist MSS. Der Fall ist ein Lehrstück dafür, dass derselbe Biomarkerwert je nach Tumorentität völlig unterschiedliche klinische Bedeutung haben kann.":"El informe externo suena espectacular: PD-L1 CPS 25. En el comité se plantea inmediatamente pembrolizumab. Pero la histología es pobre en linfocitos, las proteínas MMR están conservadas y el tumor es MSS. El caso demuestra que el mismo valor de biomarcador puede tener una relevancia clínica completamente distinta según la entidad tumoral.","61-jährige Patientin mit mehrfach vorbehandeltem metastasiertem kolorektalem Adenokarzinom. Eine Metastasenbiopsie zeigt PD-L1 CPS 25. Gesucht ist eine evidenzbasierte Einordnung, ob dieser Wert im pMMR/MSS-mCRC eine etablierte PD-1-Monotherapie begründet oder ob die entitätsspezifische MSI/dMMR-Hierarchie Vorrang hat.":"Paciente de 61 años con adenocarcinoma colorrectal metastásico muy pretratado. Una biopsia metastásica muestra PD-L1 CPS 25. Se busca una valoración basada en evidencia de si este valor justifica monoterapia PD-1 establecida en mCRC pMMR/MSS o si debe prevalecer la jerarquía MSI/dMMR específica de la entidad.","Hohe Zahl, falsche Abkürzung":"Número alto, atajo equivocado","PD-L1 CPS 25 wird als 'positiv' hervorgehoben.":"PD-L1 CPS 25 se destaca como «positivo».","Ein numerisch hoher Wert ist nur dann prädiktiv, wenn Assay, Scoring, Entität und Therapie dafür validiert sind.":"Un valor numéricamente alto solo es predictivo si ensayo, scoring, entidad y tratamiento están validados para ese uso.","CRC-spezifische Hierarchie":"Jerarquía específica de CRC","MMR/MSI ist für die IO-Selektion beim mCRC zentral.":"MMR/MSI es central para la selección de IO en mCRC.","Biomarker dürfen nicht entitätsübergreifend ohne Evidenz transferiert werden.":"Los biomarcadores no deben trasladarse entre entidades sin evidencia.","Biologisches Gesamtbild":"Panorama biológico global","TMB-low und TIL-arm.":"TMB-low y pobre en TIL.","Mehrere unabhängige Kontextsignale sprechen gegen die einfache Annahme eines hoch immunogenen Tumors.":"Varias señales contextuales independientes van contra la simple suposición de un tumor altamente inmunogénico.","PD-L1 Außenbefund":"Resultado externo de PD-L1","CPS 25, überwiegend an Tumor-/Stromagrenzen und Immunzellen.":"CPS 25, predominantemente en interfaces tumor/estroma y células inmunes.","Keine ausgeprägt lymphozytenreiche CRC-Morphologie.":"Sin morfología CRC marcadamente rica en linfocitos.","Lebermetastase mit ca. 50 % Tumoranteil.":"Metástasis hepática con aprox. 50 % de tumor.","MMR-IHC und MSI-Testung sind mit wenig Material möglich und beantworten die entscheidende CRC-spezifische Frage direkter als wiederholte PD-L1-IHC.":"IHQ MMR y estudio MSI requieren poco material y responden más directamente a la pregunta decisiva específica de CRC que repetir IHQ PD-L1.","TMB ist additive Kontextinformation und darf MSI/dMMR nicht ersetzen.":"TMB es información contextual adicional y no debe sustituir MSI/dMMR.","Breite Zusatzdiagnostik soll nicht nur deshalb erfolgen, weil ein einzelner PD-L1-Score klinisch verlockend wirkt.":"No debe realizarse un estudio adicional amplio solo porque un único score PD-L1 resulte clínicamente tentador.","Wie ist PD-L1 CPS 25 im mCRC grundsätzlich zu behandeln?":"¿Cómo debe manejarse en general PD-L1 CPS 25 en mCRC?","Als entitätsspezifisch zu interpretierender Kontextbefund; nicht als universeller tumoragnostischer ICI-Schalter.":"Como hallazgo contextual que debe interpretarse según la entidad; no como interruptor ICI universal tumor-agnostic.","CPS ≥10 ist bei jeder soliden Tumorentität automatisch prädiktiv.":"CPS ≥10 es automáticamente predictivo en cualquier entidad de tumor sólido.","PD-L1-IHC ist im CRC technisch grundsätzlich ungültig.":"La IHQ PD-L1 es técnicamente inválida en CRC por principio.","PD-L1 CPS 25 beweist MSI-H.":"PD-L1 CPS 25 demuestra MSI-H.","Prädiktive Biomarker funktionieren nur in validiertem Entitäts-/Therapiekontext.":"Los biomarcadores predictivos solo funcionan dentro de un contexto validado de entidad/tratamiento.","Welcher Befund besitzt beim mCRC die klarere etablierte IO-Relevanz?":"¿Qué hallazgo tiene una relevancia IO establecida más clara en mCRC?","dMMR/MSI-H.":"dMMR/MSI-H.","PD-L1 CPS allein.":"Solo PD-L1 CPS.","TIL-Zahl allein.":"Solo el número de TIL.","Tumornekrose allein.":"Solo la necrosis tumoral.","dMMR/MSI-H ist der etablierte zentrale Immuntherapie-Biomarkerkontext im mCRC.":"dMMR/MSI-H es el contexto central establecido de biomarcadores de inmunoterapia en el mCRC.","PD-L1 CPS 25, aber pMMR/MSS und TMB 4 Mut/Mb. Was ist die sauberste Aussage?":"PD-L1 CPS 25, pero pMMR/MSS y TMB 4 mut/Mb. ¿Cuál es la afirmación más adecuada?","PD-L1 überstimmt pMMR/MSS nicht; daraus folgt keine etablierte PD-1-Monotherapie. Studienstrategien müssen als experimentell gekennzeichnet werden.":"PD-L1 no anula el contexto pMMR/MSS; de ello no se deriva una indicación establecida de monoterapia anti-PD-1. Las estrategias de ensayo deben identificarse como experimentales.","Hoher CPS macht die Monotherapie unabhängig von MSI zum Standard.":"Un CPS alto convierte la monoterapia en estándar independientemente del MSI.","Ein pMMR/MSS-CRC kann in keiner Studie jemals auf Immuntherapie reagieren.":"Un CRC pMMR/MSS nunca puede responder a inmunoterapia en ningún ensayo.","CPS 25 definiert automatisch TMB-high.":"CPS 25 define automáticamente TMB-high.","Fehlende etablierte Monotherapie-Indikation ist nicht gleichbedeutend mit biologisch unmöglicher Aktivität in Studienkombinationen.":"La ausencia de una indicación establecida de monoterapia no significa que la actividad en combinaciones en investigación sea biológicamente imposible.","Warum ist es hilfreich zu wissen, woher der CPS stammt?":"¿Por qué es útil saber de dónde procede el CPS?","PD-L1-positive Immunzellen an Stromagrenzen können den Score erhöhen, ohne ein dichtes intratumorales Effektor-T-Zell-Infiltrat zu belegen.":"Las células inmunes PD-L1 positivas en los límites del estroma pueden elevar la puntuación sin demostrar un infiltrado intratumoral denso de linfocitos T efectores.","Immunzell-PD-L1 beweist immer bessere ICI-Wirkung.":"El PD-L1 en células inmunes siempre demuestra una mayor eficacia de los ICI.","CPS darf Immunzellen niemals berücksichtigen.":"El CPS nunca debe incluir células inmunes.","Zelluläre Quelle und räumlicher Kontext sind grundsätzlich irrelevant.":"El origen celular y el contexto espacial son fundamentalmente irrelevantes.","Score und räumliche Immunbiologie sind unterschiedliche Informationsebenen.":"La puntuación y la biología inmunitaria espacial son niveles de información diferentes.","Entscheiden Sie, wie PD-L1 CPS 25 im pMMR/MSS-mCRC berichtet und im MTB gewichtet wird, ohne den Befund zu ignorieren oder ihn entitätsfremd zur etablierten ICI-Indikation aufzuwerten.":"Decida cómo debe informarse y ponderarse en el MTB un PD-L1 CPS 25 en un mCRC pMMR/MSS, sin ignorar el hallazgo ni elevarlo fuera de su contexto validado específico de entidad a una indicación establecida de ICI.","PD-L1 CPS 25 als technisch realen Befund anerkennen.":"Reconocer PD-L1 CPS 25 como un hallazgo técnicamente real.","MMR-IHC und MSI prüfen: pMMR/MSS.":"Comprobar IHQ de MMR y MSI: pMMR/MSS.","TMB als niedrig und TIL-Infiltrat als spärlich einordnen.":"Clasificar el TMB como bajo y el infiltrado de TIL como escaso.","PD-L1 im CRC nicht als tumoragnostischen Therapie-Schalter formulieren.":"No formular PD-L1 en CRC como un interruptor terapéutico agnóstico del tumor.","Keine etablierte PD-1-Monotherapie aus PD-L1 allein ableiten.":"No derivar una indicación establecida de monoterapia anti-PD-1 únicamente a partir de PD-L1.","Experimentelle pMMR/MSS-IO-Kombinationen ausschließlich als Studienoption/Evidenzentwicklung kennzeichnen.":"Identificar las combinaciones experimentales de inmunoterapia en pMMR/MSS exclusivamente como opciones de ensayo/evidencia en evolución.","MMR-IHC plus MSI-Test; TMB nur ergänzend, wenn bereits aus validiertem Panel verfügbar.":"IHQ de MMR más prueba de MSI; TMB solo como complemento si ya está disponible a partir de un panel validado.","Bei klarem pMMR/MSS kann auf wiederholte PD-L1-IHC verzichtet werden, wenn sie die klinische Entscheidung nicht verändert.":"Con pMMR/MSS claramente establecido, puede omitirse repetir la IHQ de PD-L1 si no cambia la decisión clínica.","CPS aus anderer Entität übertragen":"Trasladar el CPS desde otra entidad tumoral","PD-L1-Cutoffs sind nicht tumoragnostisch austauschbar.":"Los puntos de corte de PD-L1 no son intercambiables entre tipos tumorales.","PD-L1 ignorieren":"Ignorar PD-L1","Der Befund ist biologisch real und kann Forschung/Studienkontext informieren; er ist nur nicht der etablierte Selektionsmarker.":"El hallazgo es biológicamente real y puede aportar información en investigación/ensayos; simplemente no es el biomarcador de selección establecido.","pMMR/MSS = absolute Immunresistenz":"pMMR/MSS = resistencia inmunitaria absoluta","Das wäre zu absolut; Studienkombinationen werden untersucht.":"Eso sería demasiado absoluto; se están estudiando combinaciones experimentales.","TMB ersetzt MSI":"TMB sustituye a MSI","TMB und MSI sind verwandte, aber nicht austauschbare Biomarker.":"TMB y MSI son biomarcadores relacionados, pero no intercambiables.","Die 25 ist echt – aber klinisch nicht der Hauptmarker":"El 25 es real, pero clínicamente no es el marcador principal","PD-L1 CPS 25 wird bestätigt. Gleichzeitig zeigen MMR-IHC und MSI-Testung pMMR/MSS, TMB liegt bei 4 Mut/Mb und CD8-T-Zellen sind spärlich. Der Twist ist nicht, dass PD-L1 'falsch' war, sondern dass ein realer positiver Befund außerhalb seines validierten Entitätskontexts therapeutisch viel weniger trägt.":"Se confirma PD-L1 CPS 25. Al mismo tiempo, la IHQ de MMR y la prueba de MSI muestran pMMR/MSS, el TMB es de 4 mut/Mb y los linfocitos T CD8 son escasos. El giro no es que PD-L1 fuera «incorrecto», sino que un hallazgo realmente positivo tiene mucho menos peso terapéutico fuera de su contexto validado específico de entidad.","So wird die zentrale Präzisionsonkologie-Kompetenz trainiert: Biomarker werden nicht nach Positiv/Negativ, sondern nach Evidenz, Entität und Therapiehierarchie interpretiert.":"Así se entrena una competencia central de la oncología de precisión: los biomarcadores no se interpretan solo como positivos/negativos, sino según la evidencia, la entidad y la jerarquía terapéutica.","PD-L1 entitätsspezifisch begrenzt":"PD-L1 limitado por el contexto específico de entidad","PD-L1 CPS 25, pMMR/MSS, TMB 4 Mut/Mb, TIL-arm. Keine etablierte PD-1-Monotherapie aus PD-L1 allein; dMMR/MSI-H wäre der relevante validierte IO-Kontext. Studienkombinationen klar als experimentell kennzeichnen.":"PD-L1 CPS 25, pMMR/MSS, TMB 4 mut/Mb, TIL escasos. No hay monoterapia anti-PD-1 establecida únicamente por PD-L1; dMMR/MSI-H sería el contexto ICI validado relevante. Etiquetar claramente las combinaciones de ensayo como experimentales.","Biomarkerhierarchie sauber getroffen.":"Jerarquía de biomarcadores correctamente identificada.","MSS erkannt, PD-L1 aber nicht eingeordnet":"MSS reconocido, pero PD-L1 no contextualizado","pMMR/MSS wird berichtet, der hohe CPS bleibt ohne Erklärung im Raum.":"Se informa pMMR/MSS, pero el CPS alto queda sin explicación.","Der wichtigste Lernkonflikt wird nicht aufgelöst.":"El conflicto de aprendizaje principal queda sin resolver.","CPS 25 = Pembrolizumab":"CPS 25 = pembrolizumab","PD-L1 wird entitätsübergreifend als Standardindikation interpretiert.":"PD-L1 se interpreta de forma transversal entre entidades como una indicación estándar.","Validierungskontext missachtet.":"Se ignora el contexto de validación.","Nicht-MSI-basierte Routineoptionen und geeignete klinische Studien prüfen.":"Evaluar opciones establecidas no basadas en MSI y ensayos clínicos adecuados.","Experimentelle Immuntherapiestrategien bleiben möglich, aber werden nicht als etablierte Monotherapie verkauft.":"Las estrategias experimentales de inmunoterapia siguen siendo posibles, pero no deben presentarse como monoterapia establecida.","PD-L1 ist kein tumoragnostischer Biomarker.":"PD-L1 no es un biomarcador agnóstico del tumor.","Im mCRC hat dMMR/MSI-H eine zentrale etablierte prädiktive Rolle für Checkpoint-Inhibition.":"En mCRC, dMMR/MSI-H tiene un papel predictivo central y establecido para la inhibición de checkpoints inmunitarios.","pMMR/MSS und niedrige TMB/TILs relativieren die intuitive Interpretation eines hohen PD-L1-Scores.":"pMMR/MSS y TMB/TIL bajos moderan la interpretación intuitiva de una puntuación PD-L1 alta.","Ein positiver Labormarker kann korrekt gemessen und trotzdem klinisch nicht entscheidend sein.":"Un marcador de laboratorio positivo puede medirse correctamente y aun así no ser clínicamente decisivo.","Studienevidenz bei pMMR/MSS darf nicht mit Routine-Standard gleichgesetzt werden.":"La evidencia de ensayos en pMMR/MSS no debe equipararse al estándar asistencial de rutina.","PD-L1 CPS 25 ist ein realer Kontextbefund, aber im pMMR/MSS-mCRC kein etablierter Ersatz für dMMR/MSI-H. TMB ist niedrig, TILs spärlich. Daher keine etablierte PD-1-Monotherapie allein aus dem CPS ableiten; Studienkombinationen nur als experimentelle Optionen kommunizieren.":"PD-L1 CPS 25 es un hallazgo contextual real, pero en mCRC pMMR/MSS no es un sustituto establecido de dMMR/MSI-H. El TMB es bajo y los TIL son escasos. Por tanto, no derivar una monoterapia anti-PD-1 establecida solo del CPS; comunicar las combinaciones de ensayo únicamente como opciones experimentales.","Entitätsspezifität":"Especificidad de entidad","MMR/MSI priorisiert":"MMR/MSI priorizado","PD-L1 nicht ignoriert, aber begrenzt":"PD-L1 no ignorado, pero correctamente limitado","Studie vs. Standard getrennt":"Ensayo y estándar diferenciados","Warum kann derselbe PD-L1-Score in zwei Tumorentitäten unterschiedliche Bedeutung besitzen?":"¿Por qué la misma puntuación PD-L1 puede tener un significado diferente en dos entidades tumorales?","Welche Biomarker sind tumoragnostisch zugelassen und welche nicht?":"¿Qué biomarcadores tienen aprobaciones agnósticas del tumor y cuáles no?","Wie formuliert man einen 'positiven, aber nicht entscheidenden' Marker verständlich im Befund?":"¿Cómo se formula claramente en un informe un marcador «positivo, pero no decisivo»?","PD-L1 CPS 25 wird durch pMMR/MSS/TMB-low relativiert":"PD-L1 CPS 25 queda relativizado por pMMR/MSS/TMB-low","Biomarkerpositivität ist ohne Entitätsvalidierung keine Therapieindikation":"La positividad de un biomarcador no constituye una indicación terapéutica sin validación específica de entidad","PD-L1 → MMR/MSI → TMB/TIL → Evidenzhierarchie":"PD-L1 → MMR/MSI → TMB/TIL → jerarquía de evidencia","MSI-H-Karzinom: Therapieoption und Lynch-Abklärung → IO, MMR-IHC, Keimbahnkontext":"Carcinoma MSI-H: opción terapéutica y estudio de Lynch → IO, IHQ de MMR, contexto germinal","MSI-H-Karzinom: Therapieoption und…":"Carcinoma MSI-H: opción terapéutica y…","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und pulmonalen Metastasen. Im Primärtumor war keine strukturierte MMR-/Lynch-Abklärung dokumentiert.":"Paciente de 49 años con carcinoma endometrioide de endometrio recidivado y metástasis pulmonares. En el tumor primario no se había documentado un estudio estructurado de MMR/Lynch.","Ist der Tumor dMMR/MSI-H und damit immuntherapeutisch relevant? Welche Reflexdiagnostik ist bei einem MMR-Verlust erforderlich, und wann muss Humangenetik folgen?":"¿Es el tumor dMMR/MSI-H y, por tanto, relevante para inmunoterapia? ¿Qué estudio reflejo se requiere ante una pérdida de MMR y cuándo debe seguir genética?","Die molekulare Einordnung soll Therapieplanung und hereditäre Beratung parallel strukturieren.":"La clasificación molecular debe estructurar en paralelo la planificación terapéutica y el asesoramiento hereditario.","Alter":"Edad","49 Jahre bei aktueller Rezidivsituation.":"49 años en la situación actual de recaída.","Mutter mit Kolonkarzinom mit 52 Jahren; mütterlicher Onkel mit Urothelkarzinom des oberen Harntrakts.":"Madre con cáncer colorrectal a los 52 años; tío materno con carcinoma urotelial del tracto urinario superior.","Außenbefund nennt 'MSI verdächtig', ohne dokumentierte MMR-IHC oder MLH1-Methylierung.":"El informe externo indica «sospecha de MSI» sin IHQ de MMR ni metilación de MLH1 documentadas.","CRC-Reflexdiagnostik wird unverändert auf das Endometriumkarzinom übertragen – insbesondere BRAF-V600E statt MLH1-Promotormethylierung.":"La estrategia refleja del CRC se traslada sin cambios al carcinoma endometrial, en particular BRAF V600E en lugar de la metilación del promotor de MLH1.","Endometrioides Endometriumkarzinom, high-grade, mit fokal lymphozytenreichem Stroma.":"Carcinoma endometrioide de endometrio de alto grado con estroma focalmente rico en linfocitos.","Rezidiv-/Metastasenmaterial bestätigt endometrialen Ursprung.":"El material de recaída/metástasis confirma el origen endometrial.","MMR-Proteinmuster, MSI-Status und bei MLH1/PMS2-Verlust die Frage einer sporadischen MLH1-Promotormethylierung.":"Patrón de proteínas MMR, estado MSI y, ante pérdida de MLH1/PMS2, la cuestión de una metilación esporádica del promotor de MLH1.","Therapiebiomarker und Lynch-Screening nutzen dieselbe MMR-Biologie, führen aber zu unterschiedlichen nächsten Schritten.":"El biomarcador terapéutico y el cribado de Lynch utilizan la misma biología MMR, pero conducen a pasos posteriores diferentes.","FFPE-Resektat des Primärtumors plus aktuelle Metastasenbiopsie.":"Pieza de resección FFPE del tumor primario más biopsia metastásica actual.","Primärtumor ca. 60 %, DNA gut geeignet.":"Tumor primario aprox. 60 %, ADN bien adecuado.","Ausreichend für MMR-IHC und molekulare Reflexdiagnostik.":"Suficiente para IHQ de MMR y pruebas moleculares reflejas.","BRAF V600E ist als Lynch-Reflex aus dem CRC-Kontext bekannt, beantwortet beim Endometriumkarzinom aber nicht die entscheidende sporadisch-vs.-hereditär-Frage.":"BRAF V600E se conoce como reflejo de Lynch en el contexto del CRC, pero en el carcinoma endometrial no responde a la cuestión clave esporádico frente a hereditario.","MSI-Bestätigung":"Confirmación de MSI","MLH1-Reflexdiagnostik":"Estudio reflejo de MLH1","Hereditäre Weiterleitung":"Derivación para estudio hereditario","Verlust von MLH1 und PMS2 bei erhaltener Expression von MSH2 und MSH6: dMMR-Muster.":"Pérdida de MLH1 y PMS2 con expresión conservada de MSH2 y MSH6: patrón dMMR.","MSI-high, konsistent mit dem dMMR-Befund.":"MSI-high, concordante con el hallazgo dMMR.","MLH1-Promotormethylierung":"Metilación del promotor de MLH1","Keine MLH1-Promotor-Hypermethylierung nachweisbar. Damit ist eine häufige sporadische Ursache des MLH1/PMS2-Verlusts nicht belegt; Lynch-Syndrom bleibt abklärungsbedürftig, ist aber noch nicht bewiesen.":"No se detecta hipermetilación del promotor de MLH1. Por tanto, no se demuestra una causa esporádica frecuente de pérdida de MLH1/PMS2; el síndrome de Lynch sigue requiriendo estudio, pero aún no está demostrado.","BRAF-V600E-Testung ist hier kein geeigneter Lynch-Screening-Reflex. Die aus dem CRC bekannte BRAF-Logik darf nicht auf das Endometriumkarzinom übertragen werden.":"La prueba de BRAF V600E no es aquí un reflejo adecuado para el cribado de Lynch. La lógica de BRAF conocida del CRC no debe trasladarse al carcinoma endometrial.","Humangenetische Beratung und Keimbahndiagnostik der MMR/Lynch-relevanten Gene werden empfohlen; der Tumorbefund allein stellt keine Lynch-Diagnose.":"Se recomiendan asesoramiento genético y estudio germinal de los genes relevantes para MMR/Lynch; el resultado tumoral por sí solo no establece un diagnóstico de síndrome de Lynch.","PD-L1/TMB Zusatzkontext":"Contexto adicional de PD-L1/TMB","Zusatzmarker können berichtet werden, stehen aber hinter dem robusten dMMR/MSI-H-Befund zurück und sind für die Lynch-Reflexdiagnostik nicht entscheidend.":"Los marcadores adicionales pueden informarse, pero quedan por detrás del hallazgo robusto dMMR/MSI-H y no son decisivos para el estudio reflejo de Lynch.","Rezidiviertes Endometriumkarzinom bei junger Patientin mit auffälliger Familienanamnese.":"Carcinoma endometrial recidivado en una paciente joven con antecedentes familiares llamativos.","MMR-IHC und MSI-/Methylierungsdiagnostik technisch verwertbar.":"La IHQ de MMR y las pruebas de MSI/metilación son técnicamente evaluables.","Rezidiviertes Endometriumkarzinom mit MLH1/PMS2-Verlust und MSI-H. Der dMMR/MSI-H-Befund ist therapeutisch relevant. Da keine MLH1-Promotor-Hypermethylierung nachweisbar ist, bleibt ein Lynch-Syndrom abklärungsbedürftig und erfordert humangenetische Beratung/Keimbahndiagnostik. BRAF V600E ist in diesem Endometrium-Kontext kein adäquater Ersatzreflex und Lynch ist aus dem Tumorbefund allein nicht bewiesen.":"Carcinoma endometrial recidivado con pérdida de MLH1/PMS2 y MSI-H. El hallazgo dMMR/MSI-H es relevante terapéuticamente. Como no se detecta hipermetilación del promotor de MLH1, el síndrome de Lynch sigue requiriendo estudio y precisa asesoramiento genético/prueba germinal. BRAF V600E no es un reflejo sustituto adecuado en este contexto endometrial y Lynch no queda demostrado solo por el hallazgo tumoral.","Teilbefund: dMMR/MSI-H ist erkannt, aber ohne MLH1-Methylierungsreflex und humangenetische Weiterleitung bleibt die hereditäre Ebene unvollständig.":"Resultado parcial: se reconoce dMMR/MSI-H, pero sin estudio reflejo de metilación de MLH1 y derivación a genética, la dimensión hereditaria queda incompleta.","dMMR/MSI-H als starken prädiktiven Immuntherapiekontext benennen":"Indicar dMMR/MSI-H como un contexto predictivo sólido para inmunoterapia","MLH1/PMS2-Verlust korrekt als gekoppeltes MMR-Muster einordnen":"Interpretar correctamente la pérdida de MLH1/PMS2 como un patrón MMR acoplado","MLH1-Promotormethylierung als passenden Endometrium-Reflex nutzen":"Utilizar la metilación del promotor de MLH1 como reflejo adecuado en endometrio","fehlende Methylierung → Lynch-Abklärung empfehlen, aber Lynch nicht als bewiesen darstellen":"Sin metilación → recomendar estudio de Lynch, pero no presentar el síndrome de Lynch como demostrado","Falschaussage: BRAF-V600E ist auch beim Endometriumkarzinom der Standardreflex für MLH1/PMS2-Verlust":"Afirmación falsa: BRAF V600E también es el reflejo estándar ante pérdida de MLH1/PMS2 en carcinoma endometrial","Optimale Lösung: MLH1/PMS2-Verlust + MSI-H therapeutisch kommunizieren; beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex prüfen. Fehlt die Methylierung, humangenetisch weiterleiten – ohne aus dem Tumorscreening bereits eine Lynch-Diagnose zu machen.":"Solución óptima: comunicar terapéuticamente la pérdida de MLH1/PMS2 + MSI-H; en carcinoma endometrial, evaluar la metilación del promotor de MLH1 como prueba refleja. Si no hay metilación, derivar a evaluación genética, sin convertir el cribado tumoral por sí solo en un diagnóstico de Lynch.","Endometriumkarzinom":"Carcinoma endometrial","dMMR":"dMMR","MSI-H":"MSI-H","MLH1":"MLH1","PMS2":"PMS2","Lynch":"Lynch","MSI-H und MLH1/PMS2-Verlust: Endometriumkarzinom zwischen Immuntherapie und Lynch-Abklärung":"MSI-H y pérdida de MLH1/PMS2: carcinoma endometrial entre inmunoterapia y estudio de Lynch","Molekularpathologie / Gynäko-Onkologie / Humangenetik / MTB":"Patología molecular / Oncología ginecológica / Genética médica / MTB","MMR-IHC-Muster korrekt lesen und MLH1/PMS2-Verlust funktionell einordnen.":"Leer correctamente el patrón de IHQ de MMR e interpretar funcionalmente la pérdida de MLH1/PMS2.","dMMR/MSI-H gleichzeitig als prädiktiven Therapiebiomarker und als möglichen Hinweis auf hereditäre Prädisposition verstehen.":"Comprender dMMR/MSI-H tanto como biomarcador predictivo terapéutico como posible indicio de predisposición hereditaria.","Beim Endometriumkarzinom MLH1-Promotormethylierung als passenden Reflex bei MLH1/PMS2-Verlust einsetzen.":"En carcinoma endometrial, utilizar la metilación del promotor de MLH1 como prueba refleja adecuada ante pérdida de MLH1/PMS2.","Den CRC-spezifischen BRAF-V600E-Reflex nicht unkritisch auf das Endometriumkarzinom übertragen.":"No trasladar de forma acrítica al carcinoma endometrial el reflejo BRAF V600E específico del CRC.","Fehlende MLH1-Methylierung als Anlass zur Lynch-Abklärung, nicht als bereits bewiesenes Lynch-Syndrom kommunizieren.":"Comunicar la ausencia de metilación de MLH1 como motivo para estudiar Lynch, no como síndrome de Lynch ya demostrado.","Die MMR-IHC zeigt einen klaren MLH1/PMS2-Verlust, der MSI-Test ist high. Im Tumorboard sind sich alle einig, dass das therapeutisch wichtig ist. Dann kommt die zweite Frage: 'Dann machen wir jetzt BRAF wie beim Kolon?' Genau hier kippt der Fall von Immuntherapie in echte molekularpathologische Reflexdiagnostik.":"La IHQ de MMR muestra una clara pérdida de MLH1/PMS2 y la prueba de MSI es high. En el comité todos coinciden en que esto es terapéuticamente importante. Entonces llega la segunda pregunta: «¿Ahora hacemos BRAF como en colon?» Justo aquí el caso pasa de inmunoterapia a una auténtica estrategia refleja de patología molecular.","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und auffälliger Familienanamnese. Der Tumor ist dMMR/MSI-H mit MLH1/PMS2-Verlust. Gesucht wird die korrekte Trennung von unmittelbarer therapeutischer Relevanz und Lynch-Screening inklusive entitätsspezifischem MLH1-Methylierungsreflex.":"Paciente de 49 años con carcinoma endometrioide de endometrio recidivado y antecedentes familiares llamativos. El tumor es dMMR/MSI-H con pérdida de MLH1/PMS2. La tarea es separar correctamente la relevancia terapéutica inmediata del cribado de Lynch, incluido el reflejo de metilación de MLH1 específico de la entidad.","Ein Befund, zwei Konsequenzen":"Un hallazgo, dos consecuencias","dMMR/MSI-H ist therapie- und hereditär relevant.":"dMMR/MSI-H es relevante tanto terapéuticamente como para la evaluación hereditaria.","Dieselbe Tumorbiologie kann unterschiedliche klinische Pfade auslösen.":"La misma biología tumoral puede desencadenar vías clínicas diferentes.","Verlustmuster":"Patrón de pérdida","MLH1 und PMS2 fehlen gemeinsam.":"MLH1 y PMS2 se pierden conjuntamente.","Das Heterodimer-Muster lenkt die Reflexdiagnostik auf MLH1.":"El patrón del heterodímero dirige el estudio reflejo hacia MLH1.","Entität zählt":"La entidad tumoral importa","BRAF-Reflex ist aus dem CRC bekannt.":"El reflejo de BRAF se conoce del CRC.","Reflexalgorithmen dürfen nicht mechanisch zwischen Tumorentitäten übertragen werden.":"Los algoritmos reflejos no deben trasladarse mecánicamente entre entidades tumorales.","High-grade endometrioides Endometriumkarzinom.":"Carcinoma endometrioide de endometrio de alto grado.","Mutter Kolonkarzinom mit 52, Onkel oberer Harntrakt.":"Madre con cáncer colorrectal a los 52, tío con cáncer del tracto urinario superior.","Primärtumor mit guter DNA-Qualität; MMR-IHC und Methylierung möglich.":"Tumor primario con ADN de buena calidad; IHQ de MMR y estudio de metilación factibles.","MMR-IHC liefert bereits das entscheidende Proteinverlustmuster und sollte nicht durch ein unspezifisches Breitpanel ersetzt werden.":"La IHQ de MMR ya proporciona el patrón decisivo de pérdida proteica y no debe sustituirse por un panel amplio inespecífico.","Bei MLH1/PMS2-Verlust ist eine gezielte MLH1-Promotormethylierung material- und fragestellungseffizient.":"Ante pérdida de MLH1/PMS2, la prueba dirigida de metilación del promotor de MLH1 es eficiente tanto en material como respecto a la pregunta clínica.","Die Keimbahndiagnostik benötigt humangenetische Beratung und eine geeignete Normalprobe; Tumorgewebe allein reicht nicht.":"El estudio germinal requiere asesoramiento genético y una muestra normal adecuada; el tejido tumoral por sí solo no es suficiente.","MMR-IHC: MLH1 und PMS2 verloren, MSH2/MSH6 erhalten. Was ist der passende nächste Reflex im Endometriumkarzinom?":"IHQ de MMR: pérdida de MLH1 y PMS2, MSH2/MSH6 conservados. ¿Cuál es la prueba refleja adecuada a continuación en carcinoma endometrial?","MLH1-Promotormethylierung prüfen, um eine häufige sporadische MLH1-Inaktivierung zu erfassen.":"Evaluar la metilación del promotor de MLH1 para detectar un mecanismo esporádico frecuente de inactivación de MLH1.","BRAF V600E ist hier der Standardreflex wie beim CRC.":"BRAF V600E es aquí la prueba refleja estándar, igual que en CRC.","Nur PD-L1 nachtesten; MMR-Muster ist für Lynch irrelevant.":"Solo repetir PD-L1; el patrón MMR es irrelevante para Lynch.","Kein Reflex: MLH1/PMS2-Verlust beweist bereits Lynch.":"Sin estudio reflejo: la pérdida de MLH1/PMS2 ya demuestra síndrome de Lynch.","Beim Endometriumkarzinom ist die MLH1-Promotormethylierung der relevante Reflex bei MLH1/PMS2-Verlust.":"En carcinoma endometrial, la metilación del promotor de MLH1 es la prueba refleja relevante ante pérdida de MLH1/PMS2.","Was bedeutet dMMR/MSI-H therapeutisch?":"¿Qué significa dMMR/MSI-H desde el punto de vista terapéutico?","Ein starker prädiktiver Immuntherapiekontext, dessen konkrete Nutzung von Stadium, Linie und aktueller Zulassung/Leitlinie abhängt.":"Un contexto predictivo sólido para inmunoterapia, cuyo uso concreto depende del estadio, la línea terapéutica y la autorización/guía vigente.","Ohne hohen PD-L1-Score ist MSI-H therapeutisch bedeutungslos.":"Sin una puntuación PD-L1 alta, MSI-H carece de relevancia terapéutica.","MSI-H ist ausschließlich ein Lynch-Screeningmarker.":"MSI-H es exclusivamente un marcador de cribado de Lynch.","MSI-H beweist eine Keimbahn-MMR-Mutation.":"MSI-H demuestra una mutación germinal de MMR.","dMMR/MSI-H besitzt eine eigenständige prädiktive Bedeutung, unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"dMMR/MSI-H tiene relevancia predictiva propia, independientemente de que la causa sea esporádica o hereditaria.","MLH1/PMS2-Verlust + MSI-H, aber keine MLH1-Promotormethylierung. Was folgt?":"Pérdida de MLH1/PMS2 + MSI-H, pero sin metilación del promotor de MLH1. ¿Qué sigue?","Lynch-Syndrom bleibt verdächtig: humangenetische Beratung/Keimbahndiagnostik veranlassen, ohne Lynch bereits als bewiesen zu bezeichnen.":"El síndrome de Lynch sigue siendo sospechoso: organizar asesoramiento genético/prueba germinal sin etiquetarlo ya como demostrado.","Lynch-Syndrom ist damit sicher bewiesen.":"El síndrome de Lynch queda así definitivamente demostrado.","Fehlende Methylierung beweist einen sporadischen Tumor.":"La ausencia de metilación demuestra un tumor esporádico.","Nur ein negatives BRAF-Ergebnis kann jetzt Lynch ausschließen.":"Solo un resultado BRAF negativo puede excluir ahora el síndrome de Lynch.","Tumorscreening stratifiziert den Verdacht; die Keimbahndiagnose ist ein separater Schritt.":"El cribado tumoral estratifica la sospecha; el diagnóstico germinal es un paso separado.","Warum ist BRAF V600E hier eine Falle?":"¿Por qué BRAF V600E es una trampa aquí?","Der BRAF-Reflex gehört zur CRC-spezifischen MLH1/PMS2-Logik und ist beim Endometriumkarzinom kein adäquater Ersatz für MLH1-Promotormethylierung.":"El reflejo de BRAF pertenece al algoritmo MLH1/PMS2 específico del CRC y no es un sustituto adecuado de la metilación del promotor de MLH1 en carcinoma endometrial.","BRAF kann in keinem Endometriumtumor mutiert sein.":"BRAF nunca puede estar mutado en un tumor endometrial.","BRAF bestimmt hier ausschließlich die PD-L1-Expression.":"BRAF determina aquí exclusivamente la expresión de PD-L1.","CRC- und Endometrium-Reflexalgorithmen sind identisch.":"Los algoritmos reflejos de CRC y endometrio son idénticos.","Reflexdiagnostik ist entitätsspezifisch und darf nicht als universelles Rezept behandelt werden.":"El diagnóstico reflejo es específico de entidad y no debe tratarse como una receta universal.","Formulieren Sie eine integrierte MTB-/Befundaussage, die dMMR/MSI-H therapeutisch würdigt, den MLH1/PMS2-Verlust korrekt reflexdiagnostisch weiterführt und die Lynch-Frage sauber von der Tumordiagnostik trennt.":"Formule una declaración integrada de MTB/informe que valore adecuadamente la relevancia terapéutica de dMMR/MSI-H, continúe correctamente la pérdida de MLH1/PMS2 con el estudio reflejo y separe con claridad la cuestión de Lynch del diagnóstico tumoral.","MMR-IHC: MLH1/PMS2-Verlust benennen.":"IHQ de MMR: indicar pérdida de MLH1/PMS2.","MSI-H als konsistenten molekularen Befund bestätigen.":"Confirmar MSI-H como hallazgo molecular concordante.","dMMR/MSI-H als prädiktiven IO-Kontext kommunizieren.":"Comunicar dMMR/MSI-H como contexto predictivo para inmunoterapia.","MLH1-Promotormethylierung als entitätsspezifischen Reflex durchführen.":"Realizar la metilación del promotor de MLH1 como prueba refleja específica de la entidad.","Fehlende MLH1-Methylierung als erhöhten Lynch-Verdacht, nicht als Beweis interpretieren.":"Interpretar la ausencia de metilación de MLH1 como un aumento de la sospecha de Lynch, no como prueba.","Humangenetische Beratung/Keimbahndiagnostik empfehlen.":"Recomendar asesoramiento genético/prueba germinal.","BRAF-V600E-CRC-Reflex ausdrücklich nicht übertragen.":"No trasladar expresamente el reflejo BRAF V600E del CRC.","MSI kann molekular aus einem validierten Panel bestätigt werden, sofern MMR-IHC und MLH1-Methylierungsreflex trotzdem korrekt integriert werden.":"El MSI puede confirmarse molecularmente a partir de un panel validado, siempre que se integren correctamente la IHQ de MMR y el reflejo de metilación de MLH1.","Bei bereits qualitativ eindeutiger dMMR-IHC kann die therapeutische Kommunikation sofort erfolgen, während die hereditäre Reflexdiagnostik parallel abgeschlossen wird.":"Si la IHQ dMMR ya es inequívoca y técnicamente válida, la interpretación terapéutica puede comunicarse de inmediato mientras se completa en paralelo el estudio reflejo hereditario.","BRAF wie beim CRC":"BRAF como en CRC","Entitätsspezifischer Reflexalgorithmus falsch übertragen.":"Algoritmo reflejo específico de entidad trasladado incorrectamente.","MSI-H = Lynch":"MSI-H = Lynch","Viele dMMR/MSI-H-Tumoren sind sporadisch; Tumorscreening ist keine Keimbahndiagnose.":"Muchos tumores dMMR/MSI-H son esporádicos; el cribado tumoral no es un diagnóstico germinal.","Methylierungsnegativ = bewiesen erblich":"Metilación negativa = hereditario demostrado","Der Befund erhöht den Verdacht, beweist aber noch keine Keimbahnmutation.":"El resultado aumenta la sospecha, pero aún no demuestra una mutación germinal.","PD-L1 priorisieren":"Priorizar PD-L1","dMMR/MSI-H ist hier der robustere Kernbiomarker; PD-L1 ist für die Lynch-Frage irrelevant.":"dMMR/MSI-H es aquí el biomarcador central más sólido; PD-L1 es irrelevante para la cuestión de Lynch.","Der CRC-Reflex wäre hier genau der falsche Automatismus":"El reflejo del CRC sería precisamente el automatismo equivocado aquí","MLH1/PMS2-Verlust und MSI-H wirken zunächst wie ein vertrauter CRC-Fall. Doch beim Endometriumkarzinom ist der sinnvolle Reflex die MLH1-Promotormethylierung – nicht BRAF V600E. Als die Methylierung negativ bleibt, steigt der Lynch-Verdacht deutlich, ohne bereits zur genetischen Diagnose zu werden.":"La pérdida de MLH1/PMS2 y MSI-H parecen inicialmente un caso familiar de CRC. Pero en carcinoma endometrial el reflejo adecuado es la metilación del promotor de MLH1, no BRAF V600E. Cuando la metilación resulta negativa, la sospecha de Lynch aumenta claramente sin convertirse todavía en un diagnóstico genético.","Der Fall trainiert zwei Kernkompetenzen gleichzeitig: entitätsspezifische Reflexdiagnostik und saubere Trennung von Tumor-Screening und Keimbahndiagnose.":"Este caso entrena dos competencias centrales a la vez: diagnóstico reflejo específico de entidad y separación clara entre cribado tumoral y diagnóstico germinal.","Therapie und Lynch-Pfad sauber getrennt":"Tratamiento y vía de Lynch claramente separados","MLH1/PMS2-Verlust, MSI-H, keine MLH1-Promotormethylierung. dMMR/MSI-H als IO-relevant berichten; Lynch-Syndrom humangenetisch abklären. BRAF-CRC-Reflex nicht verwenden.":"Pérdida de MLH1/PMS2, MSI-H, sin metilación del promotor de MLH1. Informar dMMR/MSI-H como relevante para IO; realizar evaluación genética de síndrome de Lynch. No utilizar el reflejo BRAF del CRC.","Beide klinischen Konsequenzen korrekt geführt.":"Ambas consecuencias clínicas correctamente manejadas.","IO erkannt, Lynch-Pfad unvollständig":"IO reconocida, vía de Lynch incompleta","dMMR/MSI-H wird therapeutisch korrekt eingeordnet, MLH1-Methylierung/Genetik fehlen.":"dMMR/MSI-H se interpreta correctamente en lo terapéutico, pero faltan la metilación de MLH1/la derivación a genética.","Hereditäre Konsequenz verpasst.":"Se omitió la consecuencia hereditaria.","BRAF-Automatismus":"Automatismo BRAF","BRAF V600E wird als Standardreflex bestellt und ein negatives Ergebnis als Lynch-Beweis interpretiert.":"Se solicita BRAF V600E como reflejo estándar y un resultado negativo se interpreta como prueba de síndrome de Lynch.","Entitätsspezifische Reflexdiagnostik und Keimbahnlogik verfehlt.":"Se fallan el diagnóstico reflejo específico de entidad y la lógica germinal.","MLH1-Methylierung negativ":"Metilación de MLH1 negativa","Humangenetische Beratung und Keimbahndiagnostik veranlassen.":"Organizar asesoramiento genético y prueba germinal.","Lynch-Syndrom kann bestätigt oder ausgeschlossen werden; Familienmanagement erst danach festlegen.":"El síndrome de Lynch podrá entonces confirmarse o excluirse; el manejo familiar debe definirse solo después.","dMMR/MSI-H bestätigt":"dMMR/MSI-H confirmado","Therapieplanung mit aktuellem endometriumkarzinomspezifischem IO-Standard/Leitlinie abgleichen.":"Alinear la planificación terapéutica con el estándar/guía actual de IO específico para carcinoma endometrial.","Prädiktiver Befund wird unabhängig von der noch offenen Keimbahnursache genutzt.":"El hallazgo predictivo puede utilizarse independientemente de que la causa germinal siga sin resolverse.","dMMR/MSI-H kann zugleich Therapiebiomarker und Hinweis auf hereditäre Prädisposition sein.":"dMMR/MSI-H puede ser simultáneamente biomarcador terapéutico e indicio de predisposición hereditaria.","MLH1/PMS2-Verlust lenkt die Reflexdiagnostik auf MLH1-Promotormethylierung.":"La pérdida de MLH1/PMS2 dirige el estudio reflejo hacia la metilación del promotor de MLH1.","CRC-BRAF-Reflexe dürfen nicht automatisch auf das Endometriumkarzinom übertragen werden.":"Los reflejos de BRAF del CRC no deben trasladarse automáticamente al carcinoma endometrial.","Fehlende MLH1-Methylierung erhöht den Lynch-Verdacht, beweist aber keine Keimbahnmutation.":"La ausencia de metilación de MLH1 aumenta la sospecha de síndrome de Lynch, pero no demuestra una mutación germinal.","Tumorbiomarker und Humangenetik laufen parallel, aber diagnostisch getrennt.":"Los biomarcadores tumorales y la genética médica avanzan en paralelo, pero permanecen diagnósticamente separados.","MLH1/PMS2-Verlust + MSI-H = dMMR/MSI-H und damit therapeutisch relevant. Beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex; hier negativ. Deshalb Lynch-Syndrom humangenetisch abklären, aber nicht bereits diagnostizieren. BRAF V600E ist kein adäquater Ersatzreflex.":"Pérdida de MLH1/PMS2 + MSI-H = dMMR/MSI-H y, por tanto, relevancia terapéutica. En carcinoma endometrial utilizar la metilación del promotor de MLH1 como prueba refleja; aquí es negativa. Por ello, realizar evaluación genética de síndrome de Lynch, pero sin diagnosticarlo todavía. BRAF V600E no es un reflejo sustituto adecuado.","MMR-Muster korrekt":"Patrón MMR correcto","MLH1-Methylierungsreflex":"Reflejo de metilación de MLH1","IO-Relevanz":"Relevancia IO","Lynch-Verdacht ≠ Diagnose":"Sospecha de Lynch ≠ diagnóstico","BRAF-Copyover vermieden":"Se evitó el traslado de BRAF","Warum fallen MLH1 und PMS2 gemeinsam aus?":"¿Por qué se pierden conjuntamente MLH1 y PMS2?","Warum unterscheidet sich der Reflexalgorithmus zwischen CRC und Endometrium?":"¿Por qué difiere el algoritmo reflejo entre CRC y carcinoma endometrial?","Welche Information darf bereits im Tumorbefund stehen und welche erst nach Keimbahndiagnostik?":"¿Qué información puede figurar ya en el informe tumoral y cuál solo después del estudio germinal?","MLH1/PMS2-Verlust + keine MLH1-Methylierung":"Pérdida de MLH1/PMS2 + sin metilación de MLH1","dMMR ist Therapiebiomarker und Lynch-Screening, aber Entität bestimmt den Reflex":"dMMR es biomarcador terapéutico y cribado de Lynch, pero la entidad tumoral determina el reflejo","MMR-IHC → MSI → MLH1-Methylierung → Humangenetik":"IHQ de MMR → MSI → metilación de MLH1 → genética médica","Antibiotika kurz vor ICI, Mikrobiom-Frage im Tumorboard → Evidenz korrekt begrenzen":"Antibióticos poco antes de ICI, cuestión del microbioma en el comité → limitar correctamente la evidencia","Antibiotika kurz vor ICI, Mikrobio…":"Antibióticos poco antes de ICI, microbio…","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom. PD-L1 TPS 80 %. Vor Beginn der geplanten Immuntherapie musste er wegen einer mikrobiologisch gesicherten bakteriellen Pneumonie sieben Tage breit antibiotisch behandelt werden.":"Varón de 72 años con adenocarcinoma pulmonar metastásico. PD-L1 TPS 80 %. Antes del inicio previsto de inmunoterapia precisó siete días de antibióticos de amplio espectro por una neumonía bacteriana confirmada microbiológicamente.","Soll die notwendige Antibiotikatherapie wegen möglicher Mikrobiom-Effekte die ICI-Entscheidung verändern, verzögern oder durch Mikrobiom-Interventionen 'kompensiert' werden?":"¿Debe la antibioterapia necesaria, por posibles efectos sobre el microbioma, cambiar o retrasar la decisión de ICI, o «compensarse» mediante intervenciones sobre el microbioma?","Die Pneumonie ist klinisch abgeheilt; Systemtherapie soll zeitnah beginnen.":"La neumonía ha remitido clínicamente; la terapia sistémica debe iniciarse con prontitud.","Tumor":"Tumor","Metastasiertes Lungenadenokarzinom, ECOG 1.":"Adenocarcinoma pulmonar metastásico, ECOG 1.","Treiberdiagnostik":"Estudio de drivers","Breites DNA/RNA-Profil ohne etablierte actionable Driveralteration; ALK/ROS1/RET/NTRK/METex14/EGFR etc. ohne therapieentscheidenden Befund.":"Perfil amplio de ADN/ARN sin una alteración driver actionable establecida; ALK/ROS1/RET/NTRK/METex14/EGFR, etc., sin hallazgo determinante para el tratamiento.","TPS 80 %, technisch valide.":"TPS 80 %, técnicamente válido.","Antibiotika":"Antibióticos","Piperacillin/Tazobactam, anschließend orale Komplettierung wegen gesicherter bakterieller Pneumonie; Therapie war klinisch indiziert.":"Piperacilina/tazobactam seguida de finalización oral por neumonía bacteriana confirmada; el tratamiento estaba clínicamente indicado.","Eine populationsbasierte Assoziation zwischen Antibiotika/Mikrobiom und ICI-Outcome wird zur individuellen Kontraindikation oder zum Anlass für unvalidierte Probiotika/FMT gemacht.":"Una asociación poblacional entre antibióticos/microbioma y resultado de ICI se convierte en una contraindicación individual o en motivo para probióticos/FMT no validados.","Pulmonales Adenokarzinom, TTF-1/Napsin A positiv.":"Adenocarcinoma pulmonar, TTF-1/Napsina A positivo.","TPS 80 %.":"TPS 80 %.","Molekularprofil":"Perfil molecular","DNA/RNA-basierte Treiberdiagnostik ohne etablierte Targetalteration.":"Estudio de drivers basado en ADN/ARN sin una alteración diana establecida.","Nicht die Tumordiagnostik, sondern die Evidenzstärke der Mikrobiom-/Antibiotika-Assoziation und ihre Konsequenz für die individuelle Therapie.":"La cuestión clave no es el estudio tumoral, sino la solidez de la evidencia sobre la asociación microbioma/antibióticos y su consecuencia para la decisión terapéutica individual.","Kleine Bronchialbiopsie; wesentliche Treiber- und PD-L1-Diagnostik bereits vollständig.":"Biopsia bronquial pequeña; estudio esencial de drivers y PD-L1 ya completo.","Restmaterial":"Material restante","Nur noch begrenzt verfügbar.":"Solo queda material limitado.","Zusätzliche TMB-/TIL-/Breitdiagnostik kann den Effekt einer Antibiotikatherapie auf das Darmmikrobiom nicht valide quantifizieren und erzeugt keine etablierte 'ICI-Freigabe'.":"Las pruebas adicionales de TMB/TIL o amplias no pueden cuantificar de forma válida el efecto de la antibioterapia sobre el microbioma intestinal ni generan una «autorización ICI» establecida.","Klinische Ressource":"Recurso clínico","Der wichtigste Zusatzdatensatz ist hier die Indikation und zeitliche Einordnung der Antibiotikatherapie – nicht noch ein Tumortest.":"El dato adicional más importante aquí es la indicación y el momento de la antibioterapia, no otra prueba tumoral.","Validierter Tumor-/ICI-Kontext":"Contexto tumoral/ICI validado","PD-L1 TPS 80 % bestätigt. Der Marker bleibt ein etablierter Bestandteil der NSCLC-Therapieplanung im passenden driver-negativen Kontext.":"PD-L1 TPS 80 % confirmado. El marcador sigue siendo un componente establecido de la planificación terapéutica del NSCLC en el contexto driver-negativo adecuado.","Treiberprofil":"Perfil de drivers","Keine etablierte actionable Driveralteration nach integrierter DNA/RNA-Diagnostik. Die hohe PD-L1-Expression wird damit nicht durch einen offensichtlichen targetierbaren Treiberkontext verdrängt.":"No se identifica una alteración driver actionable establecida tras el estudio integrado de ADN/ARN. Por tanto, la alta expresión de PD-L1 no queda desplazada por un contexto driver claramente diana.","TMB intermediär (7 Mut/Mb). Dieser Wert beantwortet die Antibiotika-/Mikrobiomfrage nicht und ersetzt die validierte NSCLC-Biomarkerhierarchie nicht.":"TMB intermedio (7 mut/Mb). Este valor no responde a la cuestión antibióticos/microbioma ni sustituye la jerarquía validada de biomarcadores del NSCLC.","Mäßiges CD8-Infiltrat. Auch dieser Befund erlaubt keine patientenspezifische Quantifizierung eines möglichen Antibiotikaeffekts auf ICI-Wirksamkeit.":"Infiltrado CD8 moderado. Este hallazgo tampoco permite cuantificar un efecto específico del paciente de los antibióticos sobre la eficacia de ICI.","Antibiotikaanamnese":"Antecedentes de antibióticos","Sieben Tage notwendige Antibiotikatherapie wegen gesicherter bakterieller Pneumonie unmittelbar vor geplantem ICI-Beginn.":"Siete días de antibioterapia necesaria por neumonía bacteriana confirmada inmediatamente antes del inicio previsto de ICI.","Infektion abgeheilt; Patient therapiefähig.":"Infección resuelta; paciente apto para tratamiento.","Evidenzkonflikt":"Conflicto de evidencia","Beobachtungsdaten zeigen Assoziationen zwischen Antibiotikaexposition und schlechteren ICI-Outcomes, beweisen aber für den individuellen Patienten keine kausale Therapieresistenz.":"Los datos observacionales muestran asociaciones entre la exposición a antibióticos y peores resultados con ICI, pero no demuestran resistencia terapéutica causal en un paciente individual.","Driver-negatives metastasiertes NSCLC mit hoher PD-L1-Expression. Die kürzlich notwendige Antibiotikatherapie ist als möglicher prognostischer/biologischer Kontext diskutierbar, stellt aber keine validierte individuelle Kontraindikation gegen eine indizierte Checkpoint-Therapie dar. Eine klinisch notwendige bakterielle Infektion durfte nicht unbehandelt bleiben. Unnötige Antibiotika sollten vermieden werden; Mikrobiomtests, Probiotika oder FMT sind nicht als routinemäßige Kompensationsstrategie validiert und gehören – sofern überhaupt – in Studien.":"NSCLC metastásico driver-negativo con alta expresión de PD-L1. La antibioterapia reciente y necesaria puede discutirse como posible contexto pronóstico/biológico, pero no constituye una contraindicación individual validada para una terapia de checkpoint indicada. Una infección bacteriana clínicamente relevante no debía quedar sin tratar. Deben evitarse antibióticos innecesarios; pruebas de microbioma, probióticos o FMT no están validados como estrategias rutinarias de compensación y, en todo caso, corresponden al ámbito de los ensayos.","Teilbefund: Die Mikrobiom-Assoziation wird erwähnt, aber ohne Trennung von Kausalität, Konfounding, klinischer Antibiotikaindikation und validierten Tumorbiomarkern bleibt die Empfehlung unsauber.":"Interpretación parcial: se menciona la asociación con el microbioma, pero sin separar causalidad, confusión, indicación clínica de antibióticos y biomarcadores tumorales validados, la recomendación queda imprecisa.","PD-L1 und vollständigen Driverstatus als etablierte NSCLC-Biomarkerhierarchie priorisieren":"Priorizar PD-L1 y el estado completo de drivers como jerarquía establecida de biomarcadores del NSCLC","Antibiotika/ICI als Assoziation mit möglichem Confounding, nicht als individuellen Resistenztest erklären":"Explicar antibióticos/ICI como una asociación con posible confusión, no como una prueba individual de resistencia","klinisch notwendige Antibiotikatherapie nicht retrospektiv als Fehler darstellen":"No presentar retrospectivamente la antibioterapia clínicamente necesaria como un error","keine unvalidierte Mikrobiomdiagnostik, Probiotika oder FMT als Routineempfehlung aussprechen":"No recomendar pruebas de microbioma no validadas, probióticos o FMT como rutina","Falschaussage: Antibiotika kurz vor ICI sind eine absolute Kontraindikation gegen Immuntherapie":"Afirmación falsa: los antibióticos poco antes de ICI son una contraindicación absoluta para inmunoterapia","Optimale Lösung: Hohe PD-L1-Expression und driver-negativer NSCLC-Kontext bleiben die belastbaren Therapiebiomarker. Die notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext zu erwähnen, aber nicht als validierte individuelle Kontraindikation. Keine unvalidierten Mikrobiom-Interventionen außerhalb von Studien.":"Solución óptima: la alta expresión de PD-L1 y el contexto driver-negativo del NSCLC siguen siendo los biomarcadores terapéuticos fiables. La antibioterapia necesaria debe mencionarse como posible contexto de resultado, pero no como contraindicación individual validada. No realizar intervenciones no validadas sobre el microbioma fuera de ensayos.","Mikrobiom":"Microbioma","ICI":"ICI","Confounding":"Confusión","Antibiotika vor ICI: relevante Assoziation, aber keine patientenindividuelle Kontraindikation":"Antibióticos antes de ICI: asociación relevante, pero no contraindicación individual","Beobachtungsassoziation, Kausalität und Confounding in der Mikrobiom-/ICI-Literatur unterscheiden.":"Distinguir asociación observacional, causalidad y confusión en la literatura sobre microbioma/ICI.","Validierte NSCLC-Tumorbiomarker gegenüber unvalidierten Mikrobiom-Surrogaten priorisieren.":"Priorizar biomarcadores tumorales validados del NSCLC frente a sustitutos no validados del microbioma.","Klinisch notwendige Antibiotikatherapie nicht retrospektiv als vermeidbaren onkologischen Fehler behandeln.":"No tratar retrospectivamente la antibioterapia clínicamente necesaria como un error oncológico evitable.","Eine vorausgegangene Antibiotikaexposition nicht als absolute ICI-Kontraindikation formulieren.":"No formular la exposición previa a antibióticos como una contraindicación absoluta para ICI.","Mikrobiomtests, Probiotika und FMT als experimentell statt als Routinetherapie einordnen.":"Clasificar las pruebas de microbioma, probióticos y FMT como experimentales y no como tratamiento rutinario.","Der Patient hat genau den Tumor, bei dem das Team an Checkpoint-Therapie denkt: driver-negatives NSCLC, PD-L1 TPS 80 %. Dann fällt im Medikamentenplan auf, dass er in der Vorwoche sieben Tage Breitbandantibiotika bekommen hat. Sofort steht die Frage im Raum: 'Haben wir damit die Immuntherapie kaputtgemacht?' Der Fall dreht sich weniger um einen weiteren Labortest als um Evidenzkompetenz.":"El paciente tiene exactamente el tipo de tumor en el que el equipo considera terapia de checkpoint: NSCLC driver-negativo, PD-L1 TPS 80 %. Entonces, en la medicación aparece que la semana anterior recibió siete días de antibióticos de amplio espectro. Surge de inmediato la pregunta: «¿Hemos estropeado con ello la inmunoterapia?» El caso trata menos de pedir otra prueba de laboratorio y más de competencia en interpretación de la evidencia.","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom, vollständiger DNA/RNA-Treiberdiagnostik ohne actionable Alteration und PD-L1 TPS 80 %. Unmittelbar vor geplantem ICI-Beginn wurde eine mikrobiologisch gesicherte Pneumonie leitliniengerecht antibiotisch behandelt. Das MTB soll entscheiden, ob dies die Immuntherapie verändert und wie Mikrobiomdaten klinisch korrekt begrenzt werden.":"Varón de 72 años con adenocarcinoma pulmonar metastásico, estudio completo de drivers ADN/ARN sin alteración actionable y PD-L1 TPS 80 %. Inmediatamente antes del inicio previsto de ICI, una neumonía confirmada microbiológicamente fue tratada adecuadamente con antibióticos. El MTB debe decidir si esto modifica la inmunoterapia y cómo limitar correctamente en clínica los datos del microbioma.","Starker etablierter Tumorbiomarker":"Biomarcador tumoral sólido y establecido","PD-L1 TPS 80 %, kein etablierter actionable Driver.":"PD-L1 TPS 80 %, sin driver actionable establecido.","Die Therapieplanung basiert zunächst auf validierten Tumor- und Klinikfaktoren.":"La planificación terapéutica se basa primero en factores tumorales y clínicos validados.","Reale Mikrobiomassoziation":"Asociación real con el microbioma","Antibiotikaexposition um ICI-Beginn ist in Kohorten mit schlechterem Outcome assoziiert.":"La exposición a antibióticos alrededor del inicio de ICI se asocia con peores resultados en cohortes.","Assoziation kann biologisch plausibel sein und trotzdem durch Infektion, Krankheitslast oder andere Faktoren konfundiert werden.":"Una asociación puede ser biológicamente plausible y, aun así, estar confundida por infección, carga de enfermedad u otros factores.","Klinische Indikation zählt":"La indicación clínica importa","Die Pneumonie war gesichert und behandlungsbedürftig.":"La neumonía estaba confirmada y requería tratamiento.","Ein notwendiges Antibiotikum wird nicht dadurch falsch, dass es möglicherweise das Mikrobiom beeinflusst.":"Un antibiótico necesario no se vuelve incorrecto solo porque pueda influir en el microbioma.","DNA/RNA-Treiberprofil":"Perfil de drivers ADN/ARN","Kein etablierter actionable Driver.":"Sin driver actionable establecido.","Sieben Tage wegen gesicherter bakterieller Pneumonie; Infektion jetzt abgeheilt.":"Siete días por neumonía bacteriana confirmada; infección actualmente resuelta.","Restmaterial ist knapp; zusätzliche Tumortests beantworten die Mikrobiomfrage nicht valide.":"Queda poco material; pruebas tumorales adicionales no responden de forma válida a la cuestión del microbioma.","Der Simulator enthält bewusst keinen 'Mikrobiom-ICI-Freigabetest', weil hierfür kein etablierter Routineassay mit validiertem Cutoff existiert.":"El simulador no incluye deliberadamente ninguna «prueba de autorización de ICI por microbioma», porque no existe un ensayo rutinario establecido con punto de corte validado para este fin.","Die entscheidende Zusatzinformation ist klinisch: Indikation, Zeitpunkt, Dauer und Infektionsstatus.":"La información adicional decisiva es clínica: indicación, momento, duración y estado de la infección.","Was lässt sich aus der Beobachtung 'Antibiotika um ICI-Beginn sind mit schlechterem Outcome assoziiert' für diesen Patienten ableiten?":"¿Qué puede inferirse para este paciente de la observación de que «los antibióticos alrededor del inicio de ICI se asocian con peor resultado»?","Es ist ein relevanter möglicher Risiko-/Biologiekontext, aber kein kausaler individueller Resistenztest; Confounding durch Infektion und Krankheitsstatus muss bedacht werden.":"Es un posible contexto relevante de riesgo/biología, pero no una prueba causal de resistencia individual; debe considerarse la confusión por infección y estado de la enfermedad.","Antibiotika beweisen, dass ICI nicht mehr wirken kann.":"Los antibióticos demuestran que ICI ya no puede funcionar.","Beobachtungsdaten sind grundsätzlich wertlos und dürfen nie erwähnt werden.":"Los datos observacionales carecen por completo de valor y nunca deben mencionarse.","ICI muss nach jeder Antibiotikagabe zwingend für einen festen Zeitraum verschoben werden.":"ICI debe aplazarse obligatoriamente durante un periodo fijo tras cualquier ciclo de antibióticos.","Beobachtungsassoziationen sind klinisch relevant, aber nicht gleichbedeutend mit kausaler patientenindividueller Vorhersage.":"Las asociaciones observacionales son clínicamente relevantes, pero no equivalen a una predicción causal específica del paciente.","War die Antibiotikatherapie onkologisch ein Fehler?":"¿Fue la antibioterapia un error oncológico?","Nein. Eine gesicherte bakterielle Pneumonie musste behandelt werden; unnötige Antibiotika sollten vermieden werden, notwendige aber nicht aus Mikrobiomangst vorenthalten werden.":"No. La neumonía bacteriana confirmada requería tratamiento; deben evitarse antibióticos innecesarios, pero no debe negarse un tratamiento necesario por temor a efectos sobre el microbioma.","Ja. Vor ICI dürfen Antibiotika nie gegeben werden.":"Sí. Nunca deben administrarse antibióticos antes de ICI.","Nur wenn gleichzeitig FMT gegeben wird, war sie vertretbar.":"Solo era aceptable si se administraba FMT simultáneamente.","Bei PD-L1 80 % ist eine Infektionsbehandlung generell unwichtig.":"Con PD-L1 80 %, tratar una infección carece en general de importancia.","Patientensicherheit und Behandlung einer realen Infektion haben Vorrang vor nicht validierter Mikrobiomoptimierung.":"La seguridad del paciente y el tratamiento de una infección real tienen prioridad sobre una optimización no validada del microbioma.","Soll jetzt routinemäßig ein Mikrobiomtest, Probiotikum oder FMT zur 'Rettung' der ICI-Wirkung veranlasst werden?":"¿Debe solicitarse ahora de rutina una prueba de microbioma, un probiótico o FMT para «rescatar» la eficacia de ICI?","Nein. Solche Strategien sind derzeit nicht als routinemäßige patientenindividuelle Kompensation validiert und gehören gegebenenfalls in Studien.":"No. Estas estrategias no están actualmente validadas como compensación rutinaria individualizada y, si se consideran, pertenecen al ámbito de los ensayos clínicos.","FMT ist nach Antibiotika vor ICI Standard.":"FMT es estándar tras antibióticos antes de ICI.","Ein frei verkäufliches Probiotikum ist evidenzbasiert obligat.":"Un probiótico de venta libre es obligatorio y basado en evidencia.","Ein einzelnes 16S-Profil kann zuverlässig die ICI-Wirkung vorhersagen.":"Un único perfil 16S puede predecir de forma fiable la eficacia de ICI.","Mikrobiominterventionen sind ein Forschungsfeld, kein etablierter Routinealgorithmus zur ICI-Freigabe.":"Las intervenciones sobre el microbioma son un campo de investigación, no un algoritmo rutinario establecido para autorizar ICI.","Welche Information sollte die Therapieentscheidung stärker tragen?":"¿Qué información debería pesar más en la decisión terapéutica?","Validierter NSCLC-Kontext aus Histologie, vollständigem Driverprofil, PD-L1, Klinik und Infektionsstatus; Antibiotikaexposition als zusätzlicher Unsicherheits-/Risikokontext.":"Contexto NSCLC validado a partir de histología, perfil completo de drivers, PD-L1, situación clínica y estado de la infección; exposición a antibióticos como contexto adicional de incertidumbre/riesgo.","Allein die Antibiotikaexposition.":"Solo la exposición a antibióticos.","Ein zusätzlicher TMB-Wert unabhängig von PD-L1 und Driverstatus.":"Un valor adicional de TMB independientemente de PD-L1 y del estado de drivers.","Ein experimentelles Darmmikrobiomprofil.":"Un perfil experimental del microbioma intestinal.","Evidenzhierarchie verhindert, dass ein interessanter Forschungsmarker etablierte Therapiebiomarker verdrängt.":"Una jerarquía de evidencia evita que un marcador de investigación interesante desplace a biomarcadores terapéuticos establecidos.","Formulieren Sie eine MTB-Empfehlung, die die Antibiotika-/Mikrobiomassoziation ernst nimmt, aber die individuelle Therapieentscheidung auf validierte NSCLC-Biomarker und den aktuellen klinischen Zustand stützt.":"Formule una recomendación del MTB que tome en serio la asociación antibióticos/microbioma, pero base la decisión terapéutica individual en biomarcadores validados de NSCLC y en el estado clínico actual.","Driver-negatives NSCLC und PD-L1 TPS 80 % als validierten Tumorkontext priorisieren.":"Priorizar NSCLC driver-negativo y PD-L1 TPS 80 % como contexto tumoral validado.","Antibiotikaexposition zeitlich und indikationsbezogen dokumentieren.":"Documentar la exposición a antibióticos con su momento e indicación.","Assoziation mit schlechterem ICI-Outcome als Beobachtungsbefund mit möglichem Confounding erklären.":"Explicar la asociación con peores resultados de ICI como un hallazgo observacional con posible confusión.","Notwendige Infektionsbehandlung nicht als Fehler darstellen.":"No presentar el tratamiento necesario de la infección como un error.","Keine absolute ICI-Kontraindikation oder fixe Wartezeit allein aus Antibiotika ableiten.":"No derivar una contraindicación absoluta para ICI ni un periodo fijo de espera únicamente por los antibióticos.","Keine routinemäßigen Mikrobiomtests/Probiotika/FMT außerhalb validierter Indikation bzw. klinischer Studien empfehlen.":"No recomendar de rutina pruebas de microbioma/probióticos/FMT fuera de una indicación validada o ensayo clínico.","Wenn nach Abheilung der Infektion klinische Gründe für eine kurze Verzögerung bestehen, diese klinisch und nicht als 'Mikrobiom-Washout' begründen.":"Si existen razones clínicas para un breve retraso tras resolver la infección, justificarlas clínicamente y no como un «lavado del microbioma».","Mikrobiomstudie anbieten, sofern verfügbar und ohne die Standardtherapie unangemessen zu verzögern.":"Ofrecer un estudio del microbioma si está disponible, siempre que no retrase indebidamente el tratamiento estándar.","Antibiotika = absolute ICI-Kontraindikation":"Antibióticos = contraindicación absoluta para ICI","Dafür existiert kein validierter patientenindividueller Entscheidungsalgorithmus.":"No existe un algoritmo validado de decisión individual para ello.","Notwendige Infektion unbehandelt lassen":"Dejar sin tratar una infección que necesita tratamiento","Patientensicherheit und Infektionskontrolle haben Vorrang.":"La seguridad del paciente y el control de la infección tienen prioridad.","FMT/Probiotika als Routine":"FMT/probióticos como rutina","Experimentelle Interventionen dürfen nicht als Standard verkauft werden.":"Las intervenciones experimentales no deben presentarse como estándar asistencial.","Mehr Tumortests bestellen":"Pedir más pruebas tumorales","TMB/TILs quantifizieren keinen individuellen Antibiotika-Mikrobiomeffekt.":"TMB/TIL no cuantifican un efecto individual antibiótico-microbioma.","Das Antibiotikum war möglicherweise biologisch ungünstig – und trotzdem medizinisch richtig":"El antibiótico pudo ser biológicamente desfavorable y, aun así, médicamente correcto","Die Literaturassoziation ist plausibel und soll nicht weggewischt werden. Gleichzeitig war die Pneumonie mikrobiologisch gesichert und behandlungsbedürftig. Der zentrale Twist ist daher epistemisch: Ein möglicher negativer Biomarker-/Expositionskontext macht eine notwendige Behandlung nicht falsch und liefert keine validierte individuelle ICI-Kontraindikation.":"La asociación descrita en la literatura es plausible y no debe descartarse. Al mismo tiempo, la neumonía estaba confirmada microbiológicamente y requería tratamiento. El giro central es, por tanto, epistemológico: un posible contexto desfavorable de biomarcador/exposición no convierte en erróneo un tratamiento necesario ni proporciona una contraindicación individual validada para ICI.","Der Fall trainiert Evidenzstufen, Confounding und die Fähigkeit, populationsbasierte Forschung nicht in überharte Einzelpatientenregeln zu übersetzen.":"El caso entrena la gradación de evidencia, la confusión y la capacidad de no convertir investigación poblacional en reglas excesivamente rígidas para el paciente individual.","Evidenz sauber begrenzt":"Evidencia correctamente acotada","Driver-negatives NSCLC, PD-L1 TPS 80 %. Antibiotika wegen gesicherter Pneumonie waren notwendig. Exposition als möglicher Outcome-Kontext erwähnen, aber keine absolute ICI-Kontraindikation oder Mikrobiom-Routineintervention ableiten.":"NSCLC driver-negativo, PD-L1 TPS 80 %. Los antibióticos por neumonía confirmada eran necesarios. Mencionar la exposición como posible contexto de resultado, pero no derivar una contraindicación absoluta para ICI ni una intervención rutinaria sobre el microbioma.","Validierte Biomarker und unsichere Exposition korrekt gewichtet.":"Biomarcadores validados y exposición incierta ponderados correctamente.","Assoziation erkannt, aber zu viel Unsicherheit":"Asociación reconocida, pero con demasiada incertidumbre","Antibiotikadaten werden erwähnt, die Therapie wird jedoch ohne belastbare Grundlage allein deshalb unbestimmt verschoben.":"Se mencionan los datos de antibióticos, pero el tratamiento se aplaza indefinidamente solo por ello y sin base sólida.","Beobachtungsdaten zu stark operationalisiert.":"Datos observacionales excesivamente operacionalizados.","ICI gestrichen, FMT empfohlen":"ICI cancelada, FMT recomendada","Antibiotika werden als Beweis für ICI-Resistenz behandelt und FMT/Probiotika als Routine empfohlen.":"Los antibióticos se tratan como prueba de resistencia a ICI y se recomiendan FMT/probióticos como rutina.","Evidenzniveau und Patientensicherheit verfehlt.":"Se fallan el nivel de evidencia y la seguridad del paciente.","Infektion klinisch abgeheilt":"Infección resuelta clínicamente","Systemtherapie nach regulären onkologischen Kriterien planen; keine fixe 'Mikrobiom-Wartezeit' erfinden.":"Planificar la terapia sistémica según criterios oncológicos habituales; no inventar un «periodo de espera del microbioma» fijo.","Die Therapie wird nicht aufgrund unvalidierter Surrogate unangemessen verzögert.":"El tratamiento no se retrasa indebidamente por sustitutos no validados.","künftige Antibiotikafrage":"Cuestión futura de antibióticos","Antibiotic stewardship: unnötige Exposition vermeiden, notwendige Infektionen zielgerichtet behandeln.":"Antibiotic stewardship: evitar exposiciones innecesarias y tratar de forma dirigida las infecciones que lo requieran.","Pragmatische Risikoreduktion ohne Pseudopräzision.":"Reducción pragmática del riesgo sin pseudoprecisión.","Mikrobiomstudie verfügbar":"Estudio de microbioma disponible","Teilnahme als Forschungsoption diskutieren.":"Comentar la participación como opción de investigación.","Innovative Ansätze bleiben im passenden Evidenzrahmen.":"Los enfoques innovadores permanecen en el marco de evidencia adecuado.","Antibiotikaexposition um ICI ist in Beobachtungsdaten mit schlechteren Outcomes assoziiert, aber Confounding ist relevant.":"La exposición a antibióticos alrededor de ICI se asocia con peores resultados en datos observacionales, pero la confusión es relevante.","Eine klinisch notwendige Antibiotikatherapie darf nicht aus Angst vor Mikrobiomeffekten vorenthalten werden.":"No debe negarse una antibioterapia clínicamente necesaria por temor a efectos sobre el microbioma.","Es gibt keinen etablierten Routine-Mikrobiomtest, der nach Antibiotika die individuelle ICI-Wirkung freigibt oder ausschließt.":"No existe una prueba rutinaria establecida del microbioma que autorice o descarte la eficacia individual de ICI tras antibióticos.","FMT/Probiotika zur ICI-Optimierung sind Forschungsansätze, keine Standardkompensation.":"FMT/probióticos para optimizar ICI son enfoques de investigación, no una compensación estándar.","Präzisionsonkologie bedeutet auch, Evidenzgrenzen präzise zu kommunizieren.":"La oncología de precisión también significa comunicar con precisión los límites de la evidencia.","PD-L1 TPS 80 % bei driver-negativem NSCLC bleibt ein etablierter Therapiebiomarkerkontext. Die kürzlich notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext relevant, aber keine validierte individuelle Kontraindikation. Keine unvalidierte fixe Wartezeit oder routinemäßige Mikrobiomintervention ableiten; unnötige Antibiotika künftig vermeiden, notwendige behandeln.":"PD-L1 TPS 80 % en NSCLC driver-negativo sigue siendo un contexto establecido de biomarcador terapéutico. La antibioterapia reciente y necesaria es relevante como posible contexto de resultado, pero no como contraindicación individual validada. No inferir un periodo fijo de espera no validado ni una intervención rutinaria sobre el microbioma; evitar antibióticos innecesarios en el futuro y tratar cuando sean necesarios.","Assoziation ≠ Kausalität":"Asociación ≠ causalidad","Confounding erkannt":"Confusión reconocida","Patientensicherheit":"Seguridad del paciente","validierte Biomarker priorisiert":"Biomarcadores validados priorizados","keine unvalidierte Mikrobiomtherapie":"Sin terapia de microbioma no validada","Welche Confounder erklären die Antibiotika-ICI-Assoziation möglicherweise mit?":"¿Qué factores de confusión podrían explicar en parte la asociación antibióticos-ICI?","Wann wird aus einem prognostischen Faktor ein prädiktiver Biomarker?":"¿Cuándo se convierte un factor pronóstico en un biomarcador predictivo?","Wie kommuniziert man interessante, aber nicht handlungsleitende Forschung im MTB?":"¿Cómo se comunica en el MTB una investigación interesante pero no orientadora de decisiones?","notwendige Antibiotikatherapie trotz möglicher negativer Assoziation":"Antibioterapia necesaria pese a una posible asociación negativa","Populationsassoziation ist keine individuelle Kontraindikation":"La asociación poblacional no es una contraindicación individual","validierte Tumorbiomarker → Antibiotikaindikation → Evidenzgrad → keine Pseudopräzision":"biomarcadores tumorales validados → indicación de antibióticos → nivel de evidencia → sin pseudoprecisión","IDH-mutiertes Gliom: R132H-IHC negativ – und trotzdem IDH-mutiert":"Glioma IDH-mutante: IHQ R132H negativa y, aun así, IDH-mutante","IDH-mutiertes Gliom mit G-CIMP-Pro…":"Glioma IDH-mutante con perfil G-CIMP…","Neuropathologie / Neuroonkologisches Tumorboard":"Neuropatología / Comité neurooncológico","36-jähriger Patient nach Resektion eines linksfrontalen diffus infiltrierenden Glioms. Die IDH1-R132H-IHC ist negativ; Alter und Morphologie passen jedoch schlecht zu einem typischen IDH-Wildtyp-Glioblastom.":"Varón de 36 años tras resección de un glioma difusamente infiltrante frontal izquierdo. La IHQ de IDH1 R132H es negativa; sin embargo, la edad y la morfología encajan mal con un glioblastoma IDH-wildtype típico.","Darf der Tumor nach negativer R132H-IHC als IDH-Wildtyp eingeordnet werden – und welche Rolle spielt das Methylierungsprofil?":"¿Puede clasificarse el tumor como IDH-wildtype tras una IHQ R132H negativa y qué papel desempeña el perfil de metilación?","Die integrierte Diagnose soll vor Festlegung der adjuvanten Therapie finalisiert werden.":"El diagnóstico integrado debe finalizarse antes de definir el tratamiento adyuvante.","Erstmanifestation mit fokalem Krampfanfall; MRT zeigt einen nicht kontrastmittelaufnehmenden frontalen Tumor.":"Presentación inicial con crisis focal; la RM muestra un tumor frontal sin realce de contraste.","36 Jahre – damit ist eine nicht-kanonische IDH-Alteration klinisch relevant genug, um nach negativer R132H-IHC nicht vorschnell abzubrechen.":"36 años: una alteración IDH no canónica es clínicamente lo bastante relevante como para no detenerse prematuramente tras una IHQ R132H negativa.","ATRX-Verlust und diffuse p53-Überexpression; 1p/19q-Kodeletion nicht nachweisbar.":"Pérdida de ATRX y sobreexpresión difusa de p53; no se detecta codeleción 1p/19q.","Eine negative mutationsspezifische IHC wird mit einem negativen Genstatus gleichgesetzt.":"Un resultado IHQ negativo específico de mutación se equipara a un estado genético negativo.","Diffus infiltrierendes astrozytäres Gliom, mäßige Zelldichte, keine Nekrosen oder mikrovaskuläre Proliferation.":"Glioma astrocítico difusamente infiltrante, celularidad moderada, sin necrosis ni proliferación microvascular.","IDH1 R132H negativ; ATRX nukleär verloren; p53 in großer Tumorzellfraktion stark positiv.":"IDH1 R132H negativo; pérdida nuclear de ATRX; positividad intensa de p53 en una gran fracción de células tumorales.","Molekulare Vorinformation":"Información molecular previa","1p/19q intakt.":"1p/19q intacto.","Nicht-kanonische IDH1/2-Mutation? Passt das epigenetische Gesamtprofil zu einem IDH-mutierten Astrozytom?":"¿Mutación IDH1/2 no canónica? ¿Encaja el perfil epigenético global con un astrocitoma IDH-mutante?","FFPE-Resektat, Block F6.":"Pieza de resección FFPE, bloque F6.","ca. 70 %, sehr gut geeignet.":"aprox. 70 %, muy adecuado.","ausreichend für Sequenzierung und Methylierungsprofil.":"suficiente para secuenciación y perfil de metilación.","Eine fokale Bisulfit-PCR kann einzelne CpG-Loci untersuchen, ersetzt aber keinen genomeweiten CNS-Methylierungsclassifier.":"Una PCR focal con bisulfito puede estudiar loci CpG individuales, pero no sustituye a un clasificador de metilación CNS genómico.","IDH1/2-Status vollständig klären":"Resolver completamente el estado IDH1/2","CNS-Methylierungsprofil / Classifier":"Perfil de metilación CNS / clasificador","IDH1-R132H-IHC negativ; Sequenzierung zeigt eine pathogene nicht-kanonische IDH1-p.R132C-Mutation. Die negative R132H-IHC war daher kein Ausschluss eines IDH-mutierten Glioms.":"IHQ IDH1 R132H negativa; la secuenciación muestra una mutación patogénica no canónica IDH1 p.R132C. Por tanto, la IHQ R132H negativa no excluía un glioma IDH-mutante.","Methylierungsclassifier":"Clasificador de metilación","Genomeweites Methylierungsprofil mit hochkonfidenter Zuordnung zur Familie der IDH-mutierten Astrozytome und ausgeprägtem G-CIMP-typischem Hypermethylierungsmuster.":"Perfil de metilación genómico con asignación de alta confianza a la familia de astrocitomas IDH-mutantes y un patrón pronunciado de hipermetilación tipo G-CIMP.","Fokale Bisulfit-PCR":"PCR focal con bisulfito","Ein fokaler Methylierungsmarker ist messbar, erlaubt aber keine gleichwertige globale Tumorklassifikation und ist kein Ersatz für den CNS-Methylierungsclassifier.":"Puede medirse un marcador focal de metilación, pero no proporciona una clasificación tumoral global equivalente ni sustituye al clasificador de metilación CNS.","Breites Panel":"Panel amplio","Zusätzliche Varianten ändern die zentrale integrierte Einordnung nicht; der breite Ansatz ist für die konkrete Klassifikationsfrage nicht zwingend erforderlich.":"Las variantes adicionales no cambian la clasificación integrada central; un enfoque amplio no es imprescindible para la pregunta específica de clasificación.","Diffus infiltrierendes Astrozytom mit ATRX-Verlust und p53-Akkumulation; keine hochgradigen morphologischen Kriterien.":"Astrocitoma difusamente infiltrante con pérdida de ATRX y acumulación de p53; sin criterios morfológicos de alto grado.","Tumoranteil und DNA-Qualität für Sequenzierung und Methylom geeignet.":"Fracción tumoral y calidad de ADN adecuadas para secuenciación y análisis del metiloma.","Die negative IDH1-R132H-IHC schließt bei diesem jungen Patienten eine IDH-Mutation nicht aus. Die Sequenzierung weist eine nicht-kanonische IDH1-p.R132C-Mutation nach; das genomeweite Methylierungsprofil unterstützt einen IDH-mutierten astrozytären Tumor und zeigt das erwartete G-CIMP-artige Hypermethylierungsmuster. Der Methylierungsclassifier ergänzt die integrierte Diagnose, ersetzt aber nicht Histologie und definierende molekulare Marker.":"La IHQ IDH1 R132H negativa no excluye una mutación IDH en este paciente joven. La secuenciación identifica una mutación no canónica IDH1 p.R132C; el perfil genómico de metilación respalda un tumor astrocítico IDH-mutante y muestra el patrón esperado de hipermetilación tipo G-CIMP. El clasificador de metilación complementa el diagnóstico integrado, pero no sustituye a la histología ni a los marcadores moleculares definitorios.","Teilbefund: Eine negative R132H-IHC allein reicht nicht, um den IDH-Status in diesem klinisch-morphologischen Kontext sicher festzulegen.":"Resultado parcial: una IHQ R132H negativa por sí sola no basta para establecer con certeza el estado IDH en este contexto clínico-morfológico.","R132H-IHC negativ nicht mit IDH1/2-Wildtyp gleichsetzen":"No equiparar IHQ R132H negativa con IDH1/2 wildtype","Bei passendem Kontext Sequenzierung nicht-kanonischer IDH1/2-Varianten einfordern":"En el contexto adecuado, solicitar secuenciación de variantes IDH1/2 no canónicas","Methylierungsclassifier als integrativen Klassifikationsbaustein einordnen":"Considerar el clasificador de metilación como componente diagnóstico integrador","G-CIMP als biologisches/epigenetisches Muster erklären, nicht als isolierten Routinetest":"Explicar G-CIMP como patrón biológico/epigenético, no como prueba rutinaria aislada","Falschaussage: negative R132H-IHC beweist IDH-Wildtyp":"Afirmación falsa: una IHQ R132H negativa demuestra IDH wildtype","Optimale Lösung: R132H-IHC als Screening verstehen, nicht-kanonische IDH1/2-Mutationen bei passendem Kontext sequenzieren und das Methylom als integrativen, nicht alleinstehenden Klassifikationsbaustein verwenden.":"Solución óptima: entender la IHQ R132H como cribado, secuenciar mutaciones IDH1/2 no canónicas en el contexto adecuado y utilizar el metiloma como componente integrador, no independiente, de la clasificación.","Gliom":"Glioma","IDH1":"IDH1","non-canonical IDH":"IDH no canónico","G-CIMP":"G-CIMP","Astrozytom":"Astrocitoma","R132H negativ – aber nicht IDH-Wildtyp":"R132H negativo, pero no IDH wildtype","Neuropathologie / Neuroonkologie / MTB":"Neuropatología / Neurooncología / MTB","IDH1-R132H-IHC als Screening und nicht als vollständigen IDH1/2-Ausschluss verstehen.":"Entender la IHQ IDH1 R132H como cribado y no como exclusión completa de alteraciones IDH1/2.","Bei jungem Patienten und passender Morphologie nicht-kanonische IDH1/2-Varianten sequenzieren.":"En un paciente joven con morfología compatible, secuenciar variantes IDH1/2 no canónicas.","G-CIMP als Folge der IDH-Biologie und nicht als isolierte Diagnose interpretieren.":"Interpretar G-CIMP como consecuencia de la biología IDH y no como diagnóstico aislado.","Genomeweiten Methylierungsclassifier von fokaler Methylierungs-PCR unterscheiden.":"Distinguir un clasificador genómico de metilación de una PCR focal de metilación.","Histologie, definierende Marker und Methylom zu einer integrierten Diagnose zusammenführen.":"Integrar histología, marcadores definitorios y metiloma en un diagnóstico integrado.","Die IDH1-R132H-IHC ist negativ. Der Patient ist aber 36, der Tumor sieht diffus astrozytär aus, ATRX ist verloren und 1p/19q intakt. Der vermeintlich einfache 'IDH-Wildtyp'-Stempel beginnt zu wackeln.":"La IHQ IDH1 R132H es negativa. Pero el paciente tiene 36 años, el tumor parece difusamente astrocítico, ATRX está perdido y 1p/19q está intacto. La aparentemente sencilla etiqueta «IDH-wildtype» empieza a tambalearse.","36-jähriger Patient mit linksfrontalem diffus infiltrierendem Gliom. R132H-IHC negativ, ATRX-Verlust und p53-Akkumulation. Das Board muss entscheiden, ob weiter sequenziert wird und wie ein G-CIMP-/Methylierungsprofil die integrierte Diagnose unterstützt.":"Varón de 36 años con glioma difusamente infiltrante frontal izquierdo. IHQ R132H negativa, pérdida de ATRX y acumulación de p53. El comité debe decidir si continuar la secuenciación y cómo un perfil G-CIMP/de metilación apoya el diagnóstico integrado.","Screening ist nicht Sequenzierung":"El cribado no es secuenciación","R132H-IHC erkennt die häufigste IDH1-Variante, nicht jede IDH1/2-Mutation.":"La IHQ R132H detecta la variante IDH1 más frecuente, no todas las mutaciones IDH1/2.","Ein negatives mutationsspezifisches Antikörperergebnis ist kein vollständiger Gen-Ausschluss.":"Un resultado negativo con un anticuerpo específico de mutación no supone una exclusión completa a nivel génico.","Alter + Morphologie zählen":"Edad + morfología importan","Junger Erwachsener, diffus astrozytärer Tumor, ATRX-Verlust.":"Adulto joven, tumor difusamente astrocítico, pérdida de ATRX.","Prätestwahrscheinlichkeit bestimmt, wann Sequenzierung trotz negativer IHC sinnvoll ist.":"La probabilidad pretest determina cuándo es útil secuenciar pese a una IHQ negativa.","Epigenom als Integrator":"Epigenoma como integrador","IDH-Mutationen erzeugen ein charakteristisches Hypermethylierungsprogramm.":"Las mutaciones IDH generan un programa característico de hipermetilación.","Das Methylom unterstützt Klassifikation, ersetzt aber definierende Marker nicht.":"El metiloma apoya la clasificación, pero no sustituye a los marcadores definitorios.","IDH1-R132H-IHC":"IHQ IDH1 R132H","ATRX/p53":"ATRX/p53","ATRX-Verlust, diffuse p53-Akkumulation":"Pérdida de ATRX, acumulación difusa de p53","1p/19q":"1p/19q","keine Kodeletion":"sin codeleción","Tumoranteil ca. 70 %, DNA gut.":"Fracción tumoral aprox. 70 %, ADN de buena calidad.","Keine Materialnot – die Herausforderung ist Testhierarchie, nicht Schnittökonomie.":"No hay escasez de material: el reto es la jerarquía de pruebas, no ahorrar cortes.","Fokale Bisulfit-PCR ist kein Ersatz für genomeweite Klassifikation.":"La PCR focal con bisulfito no sustituye la clasificación genómica.","Was ist der wichtigste Schluss aus negativer IDH1-R132H-IHC?":"¿Cuál es la conclusión más importante de una IHQ IDH1 R132H negativa?","Bei passendem klinisch-morphologischem Kontext IDH1/2 sequenzieren, weil nicht-kanonische Mutationen übersehen werden können.":"En el contexto clínico-morfológico adecuado, secuenciar IDH1/2 porque pueden pasarse por alto mutaciones no canónicas.","IDH-Wildtyp ist sicher bewiesen.":"IDH wildtype queda definitivamente demostrado.","Nur Methylierungsclassifier durchführen; Sequenzierung ist überflüssig.":"Realizar solo el clasificador de metilación; la secuenciación es innecesaria.","IDH ist bei Erwachsenen diagnostisch nicht relevant.":"IDH no es relevante para el diagnóstico en adultos.","R132H-IHC ist hoch nützlich, aber mutationsspezifisch.":"La IHQ R132H es muy útil, pero específica de mutación.","Was bedeutet ein G-CIMP-artiges Profil am ehesten?":"¿Qué significa más probablemente un perfil tipo G-CIMP?","Es ist ein epigenetisches Muster, das zur IDH-mutierten Biologie passt und die integrierte Klassifikation stützt.":"Es un patrón epigenético compatible con biología IDH-mutante y apoya la clasificación integrada.","Es definiert allein den WHO-Grad.":"Por sí solo define el grado OMS.","Es ist ein eigenständiger zugelassener Therapietest.":"Es una prueba terapéutica independiente aprobada.","Es beweist eine Keimbahn-IDH-Mutation.":"Demuestra una mutación germinal de IDH.","G-CIMP ist biologischer/klassifikatorischer Kontext, kein alleiniger Therapie- oder Gradmarker.":"G-CIMP es un contexto biológico/clasificatorio, no un marcador independiente de tratamiento o grado.","Welche Aussage zum Methylierungsclassifier ist korrekt?":"¿Qué afirmación sobre el clasificador de metilación es correcta?","Genomeweites Profil kann diagnostisch stark sein, muss aber mit Histologie, QC und definierenden molekularen Markern integriert werden.":"Un perfil genómico puede ser muy potente para el diagnóstico, pero debe integrarse con histología, QC y marcadores moleculares definitorios.","Der höchste Klassenname ist immer die Diagnose.":"El nombre de la clase más alta es siempre el diagnóstico.","Eine fokale Bisulfit-PCR ist gleichwertig.":"Una PCR focal con bisulfito es equivalente.","Methylom ersetzt IDH-Sequenzierung.":"El metiloma sustituye la secuenciación de IDH.","Classifier ist stark, aber integrativ.":"El clasificador es potente, pero integrador.","Sequenzierung zeigt IDH1 p.R132C. Was kippt dadurch?":"La secuenciación muestra IDH1 p.R132C. ¿Qué cambia?","Der Tumor ist IDH-mutiert; die negative R132H-IHC war ein Screening-False-negative für diese nicht-kanonische Variante.":"El tumor es IDH-mutante; la IHQ R132H negativa fue un falso negativo de cribado para esta variante no canónica.","Die Sequenzierung muss falsch sein, weil die IHC negativ war.":"La secuenciación debe ser errónea porque la IHQ era negativa.","IDH-Status bleibt Wildtyp.":"El estado IDH sigue siendo wildtype.","Es folgt Keimbahndiagnostik auf Lynch.":"Proceder a estudio germinal de síndrome de Lynch.","Nicht-kanonische IDH-Varianten sind der zentrale Twist.":"Las variantes IDH no canónicas son el giro central.","Formulieren Sie die integrierte neuropathologische Kernaussage und begründen Sie, warum nach negativer R132H-IHC sequenziert wurde und wie das Methylom gewichtet wird.":"Formule la conclusión neuropatológica integrada y explique por qué se realizó secuenciación tras una IHQ R132H negativa y cómo se pondera el metiloma.","R132H-IHC als Screening einordnen.":"Considerar la IHQ R132H como prueba de cribado.","Nicht-kanonische IDH1/2-Sequenzierung bei hoher Prätestwahrscheinlichkeit durchführen.":"Realizar secuenciación de variantes IDH1/2 no canónicas cuando la probabilidad pretest sea alta.","IDH1 p.R132C als definierenden Befund anerkennen.":"Reconocer IDH1 p.R132C como hallazgo definitorio.","Methylierungsprofil/G-CIMP als konsistenten integrativen Baustein berichten.":"Informar el perfil de metilación/G-CIMP como componente integrador concordante.","Fokale Methylierungs-PCR nicht als gleichwertigen Classifier-Ersatz darstellen.":"No presentar la PCR focal de metilación como sustituto equivalente del clasificador.","Auf Methylierungsclassifier verzichten, wenn Histologie und definierende molekulare Marker bereits eindeutig sind; in diesem Fall ist er didaktisch/klassifikatorisch zusätzlich hilfreich.":"Puede omitirse el clasificador de metilación cuando la histología y los marcadores moleculares definitorios ya son inequívocos; en este caso aporta además valor docente/clasificatorio.","Breites Panel nur bei zusätzlicher klinischer Fragestellung.":"Utilizar un panel amplio solo si existe una pregunta clínica adicional.","R132H-negativ = IDH-WT":"R132H negativo = IDH-WT","Mutationsspezifische IHC erfasst nicht alle IDH1/2-Varianten.":"La IHQ específica de mutación no detecta todas las variantes IDH1/2.","Classifier statt Sequenzierung":"Clasificador en lugar de secuenciación","Definierende Genalteration und epigenetische Klasse sind unterschiedliche Ebenen.":"Una alteración génica definitoria y una clase epigenética son niveles de información diferentes.","G-CIMP als Therapiebiomarker":"G-CIMP como biomarcador terapéutico","Das Muster ist biologisch/klassifikatorisch, nicht allein handlungsleitend.":"El patrón es biológico/clasificatorio, no orientador de acción por sí solo.","Der 'negative' IDH-Test wird positiv":"La prueba IDH «negativa» se vuelve positiva","Die Sequenzierung weist IDH1 p.R132C nach. Gleichzeitig ordnet der Methylierungsclassifier den Tumor hochkonfident der IDH-mutierten Astrozytomfamilie zu. Der Twist ist kein Laborwiderspruch, sondern zeigt die Grenze einer mutationsspezifischen IHC.":"La secuenciación identifica IDH1 p.R132C. Al mismo tiempo, el clasificador de metilación asigna con alta confianza el tumor a la familia de astrocitomas IDH-mutantes. El giro no es una contradicción de laboratorio, sino que demuestra el límite de la IHQ específica de mutación.","Er trainiert Prätestwahrscheinlichkeit, Methodengrenzen und integrierte CNS-Diagnostik.":"Entrena probabilidad pretest, limitaciones de método y diagnóstico CNS integrado.","Screeninggrenze erkannt":"Limitación del cribado reconocida","R132H-IHC negativ, IDH1 p.R132C sequenziert, Methylom konsistent mit IDH-mutiertem Astrozytom/G-CIMP.":"IHQ R132H negativa, IDH1 p.R132C detectado por secuenciación, metiloma compatible con astrocitoma IDH-mutante/G-CIMP.","Methoden korrekt hierarchisiert.":"Métodos correctamente jerarquizados.","Methylom richtig, IDH zu spät":"Metiloma correcto, IDH demasiado tarde","Classifier wird genutzt, die notwendige IDH1/2-Sequenzierung aber nicht sauber begründet.":"Se utiliza el clasificador, pero no se justifica correctamente la secuenciación IDH1/2 necesaria.","Definierenden Marker nicht durch Epigenom ersetzen.":"No sustituir un marcador definitorio por el epigenoma.","IDH-Wildtyp abgestempelt":"Etiquetado como IDH-wildtype","Nach negativer R132H-IHC wird keine Sequenzierung veranlasst.":"No se solicita secuenciación tras una IHQ R132H negativa.","Zentralen methodischen Fallstrick verpasst.":"Se omite la principal trampa metodológica.","Nicht-kanonische IDH-Mutation":"Mutación IDH no canónica","Integrierte Diagnose entsprechend IDH-mutierter Entität formulieren.":"Formular el diagnóstico integrado según la entidad IDH-mutante.","Der Tumor verlässt den IDH-Wildtyp-Pfad.":"El tumor sale de la vía IDH-wildtype.","Methylom diskordant":"Metiloma discordante","QC, Tumoranteil und Differenzialdiagnose erneut prüfen.":"Reevaluar QC, fracción tumoral y diagnóstico diferencial.","Keine automatisierte Übersteuerung der Morphologie.":"No sobreescribir automáticamente la morfología.","IDH1-R132H-IHC ist ein sehr gutes Screening, aber kein vollständiger IDH1/2-Ausschluss.":"La IHQ IDH1 R132H es un excelente cribado, pero no una exclusión completa de IDH1/2.","Nicht-kanonische IDH-Mutationen sind besonders bei jüngeren Patienten mit passendem diffusem Gliom relevant.":"Las mutaciones IDH no canónicas son especialmente relevantes en pacientes jóvenes con un contexto adecuado de glioma difuso.","IDH-Biologie erzeugt charakteristische epigenetische Muster wie G-CIMP.":"La biología IDH genera patrones epigenéticos característicos como G-CIMP.","Methylierungsclassifier sind integrative Diagnostikwerkzeuge, keine Orakel.":"Los clasificadores de metilación son herramientas diagnósticas integradoras, no oráculos.","Fokale Methylierungs-PCR und genomeweiter Classifier beantworten unterschiedliche Fragen.":"La PCR focal de metilación y un clasificador genómico responden a preguntas diferentes.","Bei diesem 36-jährigen Patienten darf die negative R132H-IHC nicht als vollständiger IDH-Wildtyp-Nachweis gelten. IDH1/2-Sequenzierung weist IDH1 p.R132C nach. Das Methylierungsprofil unterstützt die IDH-mutierte astrozytäre Klassifikation und zeigt ein G-CIMP-artiges Muster. Histologie, IDH, ATRX/p53/1p19q und Methylom werden integriert.":"En este paciente de 36 años, una IHQ R132H negativa no debe considerarse prueba completa de estado IDH-wildtype. La secuenciación IDH1/2 detecta IDH1 p.R132C. El perfil de metilación apoya la clasificación astrocítica IDH-mutante y muestra un patrón tipo G-CIMP. Se integran histología, IDH, ATRX/p53/1p19q y metiloma.","Screeninggrenze R132H-IHC":"Limitación del cribado con IHQ R132H","nicht-kanonische Sequenzierung":"Secuenciación no canónica","Classifier integrativ":"Clasificador integrador","G-CIMP korrekt eingeordnet":"G-CIMP correctamente interpretado","Wann reicht R132H-IHC allein?":"¿Cuándo basta la IHQ R132H por sí sola?","Warum ist Prätestwahrscheinlichkeit in der Molekularpathologie wichtig?":"¿Por qué es importante la probabilidad pretest en patología molecular?","Was kann ein Methylierungsclassifier, was eine fokale Bisulfit-PCR nicht kann?":"¿Qué puede hacer un clasificador de metilación que no puede una PCR focal con bisulfito?","IDH1 p.R132C trotz negativer R132H-IHC":"IDH1 p.R132C pese a IHQ R132H negativa","Negativer Screeningtest ist nicht automatisch negativer Genstatus":"Una prueba de cribado negativa no equivale automáticamente a un estado génico negativo","R132H-IHC → Sequenzierung → Methylom → integrierte Diagnose":"IHQ R132H → secuenciación → metiloma → diagnóstico integrado","Unklarer ZNS-Tumor: Der Methylierungsclassifier hilft – aber nur bei guter Probe":"Tumor CNS incierto: el clasificador de metilación ayuda, pero solo con una buena muestra","Histologisch unklarer ZNS-Tumor: M…":"Tumor CNS histológicamente incierto: m…","Neuropathologie / Neuroonkologisches Referenzboard":"Neuropatología / Comité de referencia neurooncológico","47-jährige Patientin mit einem posterior-fossären Tumor. Histologie und IHC ergeben ein ungewöhnliches gliales/ependymales Mischbild; mehrere Differenzialdiagnosen bleiben plausibel.":"Mujer de 47 años con tumor de fosa posterior. Histología e IHQ muestran un patrón mixto glial/ependimario inusual; varias posibilidades diagnósticas siguen siendo plausibles.","Kann ein DNA-Methylierungsclassifier die Diagnose klären – und wann darf ein Classifier-Ergebnis gerade nicht überinterpretiert werden?":"¿Puede un clasificador de metilación de ADN aclarar el diagnóstico y cuándo no debe sobreinterpretarse un resultado del clasificador?","Die Referenzdiagnose beeinflusst Nachsorge und Therapieplanung.":"El diagnóstico de referencia influye en el seguimiento y la planificación terapéutica.","Schwindel, Gangunsicherheit und okzipitale Kopfschmerzen; MRT mit gut abgrenzbarer Raumforderung im Kleinhirn.":"Mareo, inestabilidad de la marcha y cefalea occipital; la RM muestra una masa cerebelosa bien delimitada.","Voroperation":"Cirugía previa","Keine bekannte Tumorerkrankung.":"Sin enfermedad tumoral conocida.","Pathologie":"Patología","Morphologie uneindeutig; IHC nicht widersprüchlich, aber nicht ausreichend spezifisch.":"La morfología es ambigua; la IHQ no es contradictoria, pero sí insuficientemente específica.","Ein Classifier-Score wird als maschinelles Wahrheitsurteil behandelt, unabhängig von Tumoranteil und Plausibilität.":"Una puntuación del clasificador se trata como verdad de la máquina, independientemente de la fracción tumoral y la plausibilidad.","Piloide und stellenweise ependymale Architektur, fokale Gefäßhyalinisierung, keine eindeutige klassische Entität.":"Arquitectura piloide y focalmente ependimaria, hialinización vascular focal, sin una entidad clásica inequívoca.","GFAP positiv; EMA nur fokal dot-like; OLIG2 heterogen; keine sichere Linie.":"GFAP positivo; EMA solo focalmente dot-like; OLIG2 heterogéneo; sin línea segura.","Erste Differentialdiagnose":"Diagnóstico diferencial inicial","Ependymom versus astrozytärer/piloider Tumor.":"Ependimoma frente a tumor astrocítico/piloide.","Genomeweites Methylierungsmuster und Copy-number-Kontext.":"Patrón genómico de metilación y contexto de número de copias.","Erster FFPE-Block enthält nur ca. 15 % Tumor und viel reaktives Kleinhirngewebe; zweiter Block enthält ca. 65 % Tumor.":"El primer bloque FFPE contiene solo aprox. 15 % de tumor y abundante tejido cerebeloso reactivo; el segundo bloque contiene aprox. 65 % de tumor.","beide Blöcke technisch extrahierbar.":"Ambos bloques son técnicamente extraíbles.","Classifier-Risiko":"Riesgo del clasificador","Niedriger Tumoranteil kann den Score und das Profil verwässern.":"Una baja fracción tumoral puede diluir la puntuación y el perfil.","Eine fokale Bisulfit-PCR beantwortet nicht die globale Klassifikationsfrage.":"La PCR focal con bisulfito no responde a una pregunta de clasificación global.","Genomeweiter CNS-Methylierungsclassifier":"Clasificador genómico de metilación CNS","Classifier – Block mit wenig Tumor":"Clasificador — bloque con poco tumor","Erste Analyse aus dem tumorarmen Block liefert nur eine niedrig-konfidente, biologisch wenig plausible Zuordnung unterhalb des lokal validierten Freigabebereichs. Kein belastbarer Klassenruf.":"El primer análisis del bloque con poco tumor ofrece solo una asignación de baja confianza, biológicamente poco plausible y por debajo del rango local validado para informar. Sin llamada de clase fiable.","Classifier – tumorangereicherter Block":"Clasificador — bloque enriquecido en tumor","Nach Auswahl des tumorreichen Blocks ergibt sich eine hochkonfidente Zuordnung zur Methylierungsfamilie 'High-grade astrocytoma with piloid features' mit passendem Copy-number-Profil.":"Tras seleccionar el bloque rico en tumor, se obtiene una asignación de alta confianza a la familia de metilación «High-grade astrocytoma with piloid features» con perfil de número de copias concordante.","Lokale CpG-Methylierung nachweisbar, aber diagnostisch nicht ausreichend zur genomeweiten Klassifikation.":"La metilación CpG local es detectable, pero insuficiente para una clasificación genómica.","Molekulare Zusatzbefunde können die Plausibilität stützen, ersetzen aber bei diesem morphologisch schwierigen Fall den validierten Methylierungsclassifier nicht.":"Hallazgos moleculares adicionales pueden apoyar la plausibilidad, pero no sustituyen al clasificador de metilación validado en este caso morfológicamente difícil.","Histologisch uneindeutiger posterior-fossärer glialer Tumor.":"Tumor glial de fosa posterior histológicamente ambiguo.","Es stehen ein tumorarmer und ein deutlich tumorreicherer Block zur Verfügung.":"Hay disponible un bloque con poco tumor y otro claramente más rico en tumor.","Der CNS-Methylierungsclassifier ist bei morphologisch unklaren Tumoren besonders wertvoll, sein Ergebnis muss aber zusammen mit Tumoranteil, QC, Score, Copy-number-Profil und Histologie bewertet werden. Der erste niedrig-konfidente Lauf aus tumorarmem Material ist nicht berichtsfähig; die Wiederholung aus tumorreichem Material liefert eine plausible hochkonfidente Klassifikation.":"El clasificador de metilación CNS es especialmente valioso en tumores morfológicamente inciertos, pero su resultado debe evaluarse junto con fracción tumoral, QC, puntuación, perfil de número de copias e histología. La primera corrida de baja confianza con material pobre en tumor no es informable; la repetición con material rico en tumor proporciona una clasificación plausible de alta confianza.","Teilbefund: Ein niedrig-konfidentes Classifier-Ergebnis aus tumorarmem Material darf nicht als definitive Diagnose ausgegeben werden.":"Resultado parcial: un resultado de baja confianza del clasificador a partir de material pobre en tumor no debe emitirse como diagnóstico definitivo.","Methylierungsclassifier gezielt bei diagnostisch schwierigem ZNS-Tumor einsetzen":"Utilizar de forma dirigida el clasificador de metilación en un tumor CNS de diagnóstico difícil","Tumoranteil und Classifier-QC vor Klassenruf prüfen":"Comprobar fracción tumoral y QC del clasificador antes de emitir una clase","Classifier mit Histologie und molekularen Zusatzdaten integrieren":"Integrar el clasificador con histología y datos moleculares adicionales","Bei unplausiblem Low-confidence-Ergebnis besseres Material wählen statt überinterpretieren":"Ante un resultado de baja confianza poco plausible, elegir mejor material en lugar de sobreinterpretarlo","Falschaussage: der höchste angezeigte Klassenname ist unabhängig vom Score die Diagnose":"Afirmación falsa: el nombre de la clase más alta mostrada es el diagnóstico independientemente de la puntuación","Optimale Lösung: Classifier als starken integrativen Diagnostikbaustein nutzen, aber nur aus geeignetem Material und mit validiertem Confidence-/QC-Kontext; ein Low-confidence-Ergebnis ist ein Hinweis, kein Wahrheitsurteil.":"Solución óptima: utilizar el clasificador como un potente componente diagnóstico integrador, pero solo con material adecuado y dentro de un contexto validado de confianza/QC; un resultado de baja confianza es una pista, no un veredicto de verdad.","ZNS":"CNS","Integrated diagnosis":"Diagnóstico integrado","Der Classifier ist nur so gut wie Probe und Plausibilität":"El clasificador solo es tan bueno como la muestra y la plausibilidad","Neuropathologie / Molekulardiagnostik / MTB":"Neuropatología / Diagnóstico molecular / MTB","Indikationen für CNS-Methylierungsclassification bei diagnostisch schwierigen Tumoren erkennen.":"Reconocer indicaciones para clasificación de metilación CNS en tumores de diagnóstico difícil.","Tumoranteil, QC und Confidence/Score vor Klassenruf prüfen.":"Comprobar fracción tumoral, QC y confianza/puntuación antes de emitir una clase.","Low-confidence-Ergebnisse nicht als definitive Diagnose ausgeben.":"No informar resultados de baja confianza como diagnóstico definitivo.","Bei unplausiblem Ergebnis besseres Material priorisieren.":"Priorizar mejor material cuando el resultado sea poco plausible.","Classifier, Copy-number-Profil, Histologie und Molekulargenetik integrieren.":"Integrar clasificador, perfil de número de copias, histología y genética molecular.","Der Computer liefert einen Klassennamen – aber aus einem Block mit nur 15 % Tumor und mit einem Score unterhalb des lokal validierten Freigabebereichs. Die Versuchung ist groß, den Namen trotzdem in den Befund zu schreiben.":"El ordenador ofrece un nombre de clase, pero a partir de un bloque con solo 15 % de tumor y una puntuación por debajo del rango local validado para informar. La tentación de poner el nombre en el informe es grande.","47-jährige Patientin mit morphologisch uneindeutigem posterior-fossärem glialem Tumor. Zwei Blöcke unterscheiden sich massiv im Tumoranteil. Der Fall lehrt, wann Methylierungsclassification enorm hilfreich ist und wann ein scheinbares Ergebnis verworfen werden muss.":"Mujer de 47 años con tumor glial de fosa posterior morfológicamente ambiguo. Dos bloques difieren enormemente en fracción tumoral. El caso enseña cuándo la clasificación por metilación es enormemente útil y cuándo debe descartarse un resultado aparente.","Unklare Morphologie":"Morfología incierta","Ependymal/piloid/glial überlappende Merkmale.":"Características ependimarias/piloides/gliales solapadas.","Genau hier kann ein validierter classifier besonders wertvoll sein.":"Es precisamente aquí donde un clasificador validado puede ser especialmente valioso.","Zwei Blöcke, zwei Welten":"Dos bloques, dos mundos","15 % versus 65 % Tumoranteil.":"15 % frente a 65 % de fracción tumoral.","Preanalytics beeinflusst auch digitale/epigenetische Klassifikatoren.":"La preanalítica también afecta a clasificadores digitales/epigenéticos.","Score braucht Kontext":"La puntuación necesita contexto","Low confidence + unplausible Morphologie.":"Baja confianza + morfología poco plausible.","Ein Output ist noch kein reportable Result.":"Una salida aún no es un resultado informable.","Block A":"Bloque A","ca. 15 % Tumor, viel normales Kleinhirngewebe":"aprox. 15 % de tumor, abundante tejido cerebeloso normal","Block B":"Bloque B","ca. 65 % Tumor":"aprox. 65 % de tumor","mehrere plausible ZNS-Differenzialdiagnosen":"Varios diagnósticos diferenciales CNS plausibles","Classifier aus geeignetem tumorreichem Material priorisieren.":"Priorizar el clasificador con material adecuado rico en tumor.","Lokaler validierter Score-/QC-Rahmen ist Teil der Befundfreigabe.":"El marco local validado de puntuación/QC forma parte de la liberación del informe.","Fokale Bisulfit-PCR löst keine genomeweite Klassifikationsfrage.":"La PCR focal con bisulfito no resuelve una pregunta de clasificación genómica.","Wann ist der Methylierungsclassifier hier am wertvollsten?":"¿Cuándo es más valioso aquí el clasificador de metilación?","Bei persistierender diagnostischer Unsicherheit trotz Histologie/IHC und ausreichendem Material.":"Cuando persiste la incertidumbre diagnóstica pese a histología/IHQ y se dispone de material suficiente.","Immer als Ersatz für Histologie.":"Siempre como sustituto de la histología.","Nur wenn eine medikamentöse Targettherapie existiert.":"Solo si existe una terapia dirigida.","Bei Erwachsenen grundsätzlich nicht.":"Nunca en adultos.","Der größte Zusatznutzen entsteht bei schwierigen integrierten Diagnosen.":"El mayor valor añadido se obtiene en diagnósticos integrados difíciles.","Wie wird ein niedrig-konfidentes Ergebnis aus 15-%-Tumorblock behandelt?":"¿Cómo debe manejarse un resultado de baja confianza de un bloque con 15 % de tumor?","Nicht definitiv reporten; QC/Tumoranteil prüfen und besseres Material analysieren.":"No informar de forma definitiva; comprobar QC/fracción tumoral y analizar mejor material.","Höchste Klasse trotzdem als Diagnose berichten.":"Informar de todos modos la clase más alta como diagnóstico.","Mit HE-Diagnose mitteln.":"Promediarlo con el diagnóstico HE.","Score ist irrelevant.":"La puntuación es irrelevante.","Confidence und Präanalytik sind Teil der diagnostischen Aussage.":"La confianza y la preanalítica forman parte de la afirmación diagnóstica.","Der tumorreiche Block liefert einen hochkonfidenten, morphologisch plausiblen Treffer. Was folgt?":"El bloque rico en tumor ofrece un resultado de alta confianza y morfológicamente plausible. ¿Qué sigue?","Mit Histologie und molekularen Zusatzdaten integrieren und als starke diagnostische Evidenz nutzen.":"Integrarlo con histología y datos moleculares adicionales y utilizarlo como evidencia diagnóstica sólida.","Alle bisherigen Befunde verwerfen.":"Descartar todos los hallazgos previos.","Classifier immer ignorieren.":"Ignorar siempre el clasificador.","Erst eine fokale Bisulfit-PCR muss den Namen bestätigen.":"Primero una PCR focal con bisulfito debe confirmar el nombre.","Plausible hochkonfidente Klassifikation ist stark, aber integriert.":"Una clasificación plausible de alta confianza es sólida, pero debe integrarse.","Warum ist das begleitende Copy-number-Profil nützlich?":"¿Por qué es útil el perfil de número de copias acompañante?","Es kann die Klassenplausibilität stützen und zusätzliche diagnostische Muster liefern.":"Puede apoyar la plausibilidad de la clase y aportar patrones diagnósticos adicionales.","Es beweist Keimbahnveränderungen.":"Demuestra alteraciones germinales.","Es ersetzt Histologie vollständig.":"Sustituye completamente la histología.","Es ist immer ein zugelassener Therapietest.":"Siempre es una prueba terapéutica aprobada.","Classifier und CN-Profil ergänzen die integrierte Diagnose.":"El clasificador y el perfil CN complementan el diagnóstico integrado.","Entscheiden Sie, welcher Block analysiert und welches Classifier-Ergebnis reportet werden darf. Formulieren Sie die integrierte Diagnose mit klarer QC-Grenze.":"Decida qué bloque debe analizarse y qué resultado del clasificador puede informarse. Formule el diagnóstico integrado con un límite de QC claro.","Morphologische Unsicherheit als legitime Classifier-Indikation erkennen.":"Reconocer la incertidumbre morfológica como indicación legítima del clasificador.","Tumorarmen Block als Risikomaterial identifizieren.":"Identificar el bloque con poco tumor como material de riesgo.","Low-confidence-Ausgabe nicht als definitive Diagnose reporten.":"No informar una salida de baja confianza como diagnóstico definitivo.","Tumorreichen Block analysieren.":"Analizar el bloque rico en tumor.","Hochkonfidenten, plausiblen Classifier mit Morphologie/CN-Profil integrieren.":"Integrar el resultado plausible de alta confianza del clasificador con morfología/perfil CN.","Bei fehlendem besserem Material eine rein deskriptive/NEC-artige Diagnose mit Limitation statt erzwungenem Classifier-Call.":"Si no hay mejor material, utilizar un diagnóstico puramente descriptivo/tipo NEC con limitaciones en lugar de forzar una llamada del clasificador.","Referenzzentrum bei persistierender Diskordanz.":"Remitir a un centro de referencia si persiste la discordancia.","Highest score wins":"Gana la puntuación más alta","Confidence, QC und Plausibilität werden ignoriert.":"Se ignoran confianza, QC y plausibilidad.","Classifier ersetzt Histologie":"El clasificador sustituye a la histología","CNS-Diagnostik bleibt integriert.":"El diagnóstico CNS sigue siendo integrado.","Fokale Methylierung statt Methylom":"Metilación focal en lugar de metiloma","Lokaler Marker beantwortet eine andere Frage.":"Un marcador local responde a una pregunta diferente.","Der erste Classifier war technisch echt – diagnostisch trotzdem nicht gut genug":"El primer clasificador era técnicamente real, pero diagnósticamente insuficiente","Aus dem tumorarmen Block entsteht ein Low-confidence-Match. Erst der gezielte Wechsel auf den tumorreichen Block erzeugt eine hochkonfidente, morphologisch passende Klassifikation. Das Problem war nicht 'KI vs. Mensch', sondern Präanalytik und Freigabekriterien.":"El bloque pobre en tumor produce una coincidencia de baja confianza. Solo tras cambiar de forma deliberada al bloque rico en tumor aparece una clasificación de alta confianza y morfológicamente concordante. El problema no era «IA frente a humano», sino la preanalítica y los criterios de liberación.","Der Fall macht deutlich, dass auch moderne Klassifikatoren klassische Labor-QC brauchen.":"El caso deja claro que los clasificadores modernos también requieren QC clásico de laboratorio.","QC vor Klassenname":"QC antes del nombre de clase","Low-confidence aus Block A verworfen; Block B liefert hochkonfidenten plausiblen Classifier-Match.":"Se descarta el resultado de baja confianza del bloque A; el bloque B ofrece una coincidencia del clasificador plausible y de alta confianza.","Classifier als Laborverfahren behandelt, nicht als Black Box.":"El clasificador se trata como método de laboratorio, no como caja negra.","Richtige Klasse, falscher Weg":"Clase correcta, camino equivocado","Klasse erkannt, aber der erste Low-score-Lauf wird nicht klar als nicht freigabefähig markiert.":"Se reconoce la clase, pero la primera corrida con puntuación baja no se marca claramente como no liberable.","QA-Lernziel verfehlt.":"Se pierde el objetivo didáctico de QA.","Low score reportet":"Puntuación baja informada","Erster angezeigter Klassenname wird ungeprüft zur Diagnose.":"El primer nombre de clase mostrado se adopta como diagnóstico sin revisión.","Kritischer Befundfreigabefehler.":"Error crítico de liberación del informe.","Low-confidence / diskordant":"Baja confianza / discordante","Tumoranteil, DNA-QC, Referenzklasse und Materialauswahl prüfen.":"Comprobar fracción tumoral, QC de ADN, clase de referencia y selección de material.","Keine Scheinsicherheit.":"Sin falsa certeza.","High-confidence + plausibel":"Alta confianza + plausible","In integrierte Diagnose übernehmen.":"Incorporar al diagnóstico integrado.","Methylom liefert echten diagnostischen Mehrwert.":"El metiloma aporta un valor diagnóstico añadido real.","Methylierungsclassifier sind besonders bei schwierigen ZNS-Tumoren leistungsfähig.":"Los clasificadores de metilación son especialmente potentes en tumores CNS difíciles.","Tumoranteil und Probenqualität beeinflussen das Ergebnis.":"La fracción tumoral y la calidad de la muestra afectan al resultado.","Confidence/Score ist kein kosmetischer Parameter, sondern Teil der Befundfreigabe.":"La confianza/puntuación no es cosmética; forma parte de la liberación del informe.","Ein niedriger Score kann korrekt gerechnet und trotzdem diagnostisch nicht ausreichend sein.":"Una puntuación baja puede estar correctamente calculada y aun así ser insuficiente para el diagnóstico.","Moderne Klassifikation funktioniert nur integriert mit Pathologie und Molekulargenetik.":"La clasificación moderna funciona solo integrada con patología y genética molecular.","Der erste Lauf aus tumorarmem Material ist trotz angezeigtem Klassennamen nicht freigabefähig. Nach Analyse des tumorreichen Blocks entsteht eine hochkonfidente, morphologisch und genomisch plausible Klassifikation. Diese wird als starker integrativer Diagnostikbaustein genutzt.":"La primera corrida con material pobre en tumor no es liberable pese al nombre de clase mostrado. El análisis del bloque rico en tumor produce después una clasificación de alta confianza, morfológica y genómicamente plausible. Se utiliza como un potente componente diagnóstico integrador.","QC/Confidence":"QC/Confianza","Materialauswahl":"Selección de material","integrative Diagnose":"Diagnóstico integrado","kein Black-box-Overcalling":"Sin sobreinterpretación de caja negra","Welche Mindest-QC braucht ein Classifier in Ihrem Labor?":"¿Qué QC mínimo requiere un clasificador en su laboratorio?","Wie berichtet man Low-confidence-Ergebnisse?":"¿Cómo deben informarse los resultados de baja confianza?","Wann ist 'kein Klassenruf' die bessere Diagnose?":"¿Cuándo es mejor «sin llamada de clase»?","Low-confidence aus falschem Block":"Baja confianza del bloque equivocado","Classifier braucht Labor-QC wie jede andere Methode":"Un clasificador necesita QC de laboratorio como cualquier otro método","Morphologische Unsicherheit → Materialwahl → Classifier-QC → integrierter Call":"Incertidumbre morfológica → selección de material → QC del clasificador → llamada integrada","DNMT3A/TET2/ASXL1 bei Zytopenie: CHIP, CCUS oder MDS?":"DNMT3A/TET2/ASXL1 con citopenia: ¿CHIP, CCUS o MDS?","MDS/AML mit DNMT3A/TET2/ASXL1":"MDS/AML con DNMT3A/TET2/ASXL1","Hämatologie / Molekulares Board":"Hematología / Comité molecular","74-jähriger Patient mit seit neun Monaten persistierender makrozytärer Anämie und milder Thrombozytopenie. Im peripheren Blut wurden DNMT3A- und TET2-Varianten gefunden.":"Varón de 74 años con anemia macrocítica persistente y trombocitopenia leve durante nueve meses. En sangre periférica se detectaron variantes de DNMT3A y TET2.","Beweisen diese Mutationen bereits ein MDS – oder handelt es sich um CHIP?":"¿Estas mutaciones ya demuestran MDS o se trata de CHIP?","Die Diagnose soll vor Einleitung einer krankheitsspezifischen Therapie geklärt werden.":"El diagnóstico debe aclararse antes de iniciar un tratamiento específico de la enfermedad.","Hb 9,8 g/dl, MCV erhöht, Thrombozyten 115/nl; Leukozyten normal.":"Hb 9,8 g/dl, VCM elevado, plaquetas 115/nl; leucocitos normales.","Sekundäre Ursachen":"Causas secundarias","Vitaminmangel, relevante Blutung, Niereninsuffizienz und Medikamente als Hauptursache weitgehend ausgeschlossen.":"Déficit vitamínico, hemorragia relevante, insuficiencia renal y fármacos se han descartado en gran medida como causa principal.","Blut-NGS: DNMT3A p.R882H VAF 12 %, TET2 Frameshift VAF 8 %.":"NGS en sangre: DNMT3A p.R882H VAF 12 %, TET2 frameshift VAF 8 %.","Mutationen typischer CH-Gene werden mit einer definierten myeloischen Neoplasie gleichgesetzt.":"Las mutaciones de genes típicos de CH se equiparan a una neoplasia mieloide definida.","Knochenmark + Vorinformation":"Médula ósea + información previa","Normo- bis leicht hyperzellulär; Dysplasie unterhalb diagnostischer Schwelle, Blasten 2 %.":"Normocelular a levemente hipercelular; displasia por debajo del umbral diagnóstico, blastos 2 %.","Kein MDS-definierender Befund.":"Sin hallazgo definitorio de MDS.","Flow":"Citometría de flujo","Kein eindeutiger aberranter Blastenphänotyp.":"Sin fenotipo aberrante inequívoco de blastos.","Wie werden persistierende Zytopenie und klonale Mutationen zusammengeführt?":"¿Cómo deben integrarse la citopenia persistente y las mutaciones clonales?","Knochenmarkaspirat + Stanze sowie EDTA-Blut.":"Aspirado medular + biopsia y sangre EDTA.","ausreichende Tiefe zur VAF-Beurteilung.":"Profundidad suficiente para evaluar VAF.","CHIP setzt definitionsgemäß das Fehlen einer anderweitig ungeklärten Zytopenie voraus.":"Por definición, CHIP requiere ausencia de citopenia no explicada por otra causa.","Ein breites Pan-Cancer-Panel schafft nicht automatisch mehr diagnostische Sicherheit als eine integrierte hämatologische Bewertung.":"Un panel pan-cáncer amplio no genera automáticamente más certeza diagnóstica que una evaluación hematológica integrada.","Knochenmark-/Morphologiekontext":"Contexto médula ósea/morfología","Klonale Hämatopoese / Myeloid-Panel":"Hematopoyesis clonal / panel mieloide","Persistierende Zytopenie, aber keine ausreichende Dysplasie, keine erhöhte Blastenzahl und kein morphologisch definierendes MDS-Kriterium.":"Citopenia persistente, pero displasia insuficiente, sin aumento de blastos y sin criterio morfológico definitorio de MDS.","Myeloid-Panel":"Panel mieloide","DNMT3A p.R882H (VAF 12 %) und TET2 Frameshift (VAF 8 %); keine TP53-Alteration im untersuchten Panel. Klonalität ist belegt, eine MDS-Diagnose dadurch allein jedoch nicht.":"DNMT3A p.R882H (VAF 12 %) y TET2 frameshift (VAF 8 %); sin alteración de TP53 en el panel estudiado. La clonalidad está demostrada, pero esto por sí solo no establece un MDS.","Zusätzliche unspezifische Varianten erhöhen die Informationsmenge, lösen aber die diagnostische Abgrenzung nicht ohne Blutbild, Morphologie und definierende Kriterien.":"Variantes adicionales inespecíficas aumentan la cantidad de información, pero no resuelven la distinción diagnóstica sin hemograma, morfología y criterios definitorios.","Persistierende, anderweitig nicht erklärte Anämie und Thrombozytopenie.":"Anemia y trombocitopenia persistentes, no explicadas por otra causa.","Keine ausreichenden morphologischen oder genetischen Kriterien für eine manifeste myeloische Neoplasie.":"Sin criterios morfológicos o genéticos suficientes para una neoplasia mieloide manifiesta.","Die DNMT3A- und TET2-Mutationen belegen klonale Hämatopoese, definieren aber allein kein MDS. Weil gleichzeitig persistierende ungeklärte Zytopenien bestehen, ist 'CHIP' nicht die passende Kategorie; bei fehlenden diagnostischen MDS-Kriterien passt die Konstellation zu einer klonalen Zytopenie unklarer Signifikanz (CCUS). Verlauf und erneute Abklärung bei Progression sind wichtiger als ein vorschnelles Neoplasie-Label.":"Las mutaciones DNMT3A y TET2 demuestran hematopoyesis clonal, pero por sí solas no definen un MDS. Como también existen citopenias persistentes no explicadas, «CHIP» no es la categoría adecuada; en ausencia de criterios diagnósticos de MDS, la constelación encaja con citopenia clonal de significado incierto (CCUS). El seguimiento y la reevaluación si hay progresión son más importantes que una etiqueta prematura de neoplasia.","Teilbefund: Mutationen in DNMT3A/TET2/ASXL1 können bei CHIP, CCUS und myeloischen Neoplasien vorkommen; die Diagnose entsteht erst aus Klinik, Blutbild, Morphologie und Genetik zusammen.":"Resultado parcial: las mutaciones DNMT3A/TET2/ASXL1 pueden aparecer en CHIP, CCUS y neoplasias mieloides; el diagnóstico surge solo al integrar contexto clínico, hemograma, morfología y genética.","Klonale Mutation nicht mit MDS gleichsetzen":"No equiparar una mutación clonal con MDS","CHIP nur ohne ungeklärte Zytopenie verwenden":"Utilizar CHIP solo en ausencia de citopenia no explicada","CCUS als passende Zwischenkategorie bei Zytopenie + Klon ohne MDS-Kriterien erkennen":"Reconocer CCUS como categoría intermedia adecuada para citopenia + clon sin criterios de MDS","Verlaufskontrolle und erneute KM-Diagnostik bei Dynamik einplanen":"Planificar seguimiento y reevaluación de médula ósea si el cuadro evoluciona","Falschaussage: DNMT3A/TET2 beweisen eine hämatologische Neoplasie":"Afirmación falsa: DNMT3A/TET2 demuestran una neoplasia hematológica","Optimale Lösung: DNMT3A/TET2 zeigen einen Klon; Zytopenie verhindert die CHIP-Bezeichnung, fehlende MDS-definierende Kriterien verhindern die MDS-Diagnose – damit ist CCUS die saubere integrierte Einordnung.":"Solución óptima: DNMT3A/TET2 demuestran un clon; la citopenia impide la etiqueta CHIP y la ausencia de criterios definitorios de MDS impide diagnosticar MDS, por lo que CCUS es la clasificación integrada correcta.","Hämatologie":"Hematología","DNMT3A":"DNMT3A","TET2":"TET2","CHIP":"CHIP","CCUS":"CCUS","MDS":"MDS","Clonal hematopoiesis":"Hematopoyesis clonal","Der Klon ist echt – die Neoplasie noch nicht":"El clon es real, la neoplasia aún no","Hämatopathologie / Hämatologie / MTB":"Hematopatología / Hematología / MTB","DNMT3A/TET2/ASXL1-Mutationen als häufige Klone und nicht als automatische MDS-Diagnose erkennen.":"Reconocer las mutaciones DNMT3A/TET2/ASXL1 como clones frecuentes y no como diagnóstico automático de MDS.","CHIP, CCUS und MDS anhand von Zytopenie und diagnostischen Kriterien trennen.":"Distinguir CHIP, CCUS y MDS mediante citopenia y criterios diagnósticos.","VAF/Klonalität als Kontext, nicht als alleinige Entitätsdefinition verwenden.":"Utilizar VAF/clonalidad como contexto, no como única definición de una entidad.","Morphologie und Blutbild gegenüber 'Genetik allein' priorisieren.":"Priorizar morfología y hemograma frente a «genética sola».","Verlaufskontrolle als Teil einer ehrlichen diagnostischen Strategie verstehen.":"Entender el seguimiento como parte de una estrategia diagnóstica honesta.","Zwei pathogene Mutationen stehen schwarz auf weiß im NGS-Bericht. Der Reflex lautet: 'Dann hat er MDS.' Das Knochenmark liefert aber keine ausreichenden Kriterien – und die persistierende Zytopenie macht gleichzeitig 'CHIP' falsch.":"Dos mutaciones patogénicas aparecen claramente en el informe NGS. El reflejo es: «Entonces tiene MDS». Pero la médula ósea no cumple criterios suficientes y la citopenia persistente hace que «CHIP» tampoco sea correcto.","74-jähriger Patient mit ungeklärter makrozytärer Anämie und Thrombozytopenie. DNMT3A und TET2 sind mutiert, das Knochenmark bleibt jedoch unterhalb diagnostischer MDS-Schwellen. Gesucht ist die richtige Kategorie zwischen benignem Zufallsbefund und manifester Neoplasie.":"Varón de 74 años con anemia macrocítica y trombocitopenia no explicadas. DNMT3A y TET2 están mutados, pero la médula ósea permanece por debajo de los umbrales diagnósticos de MDS. La tarea es identificar la categoría correcta entre un hallazgo incidental benigno y una neoplasia manifiesta.","Klonalität ist bewiesen":"La clonalidad está demostrada","DNMT3A 12 %, TET2 8 % VAF.":"DNMT3A 12 %, TET2 8 % VAF.","Ein Klon ist nicht automatisch eine Neoplasie.":"Un clon no es automáticamente una neoplasia.","Zytopenie ist real":"La citopenia es real","Persistierende Anämie + Thrombozytopenie ohne klare Sekundärursache.":"Anemia persistente + trombocitopenia sin causa secundaria clara.","Damit passt die Definition von CHIP gerade nicht.":"Por tanto, la definición de CHIP no encaja.","MDS-Kriterien fehlen":"Faltan criterios de MDS","Blasten 2 %, Dysplasie unter Schwelle, keine definierende Genetik.":"Blastos 2 %, displasia por debajo del umbral, sin genética definitoria.","CCUS ist eine sinnvolle Zwischenkategorie.":"CCUS es una categoría intermedia útil.","Hb 9,8 g/dl; Thrombozyten 115/nl":"Hb 9,8 g/dl; plaquetas 115/nl","DNMT3A p.R882H 12 %, TET2 Frameshift 8 %":"DNMT3A p.R882H 12 %, TET2 frameshift 8 %","keine ausreichende Dysplasie, Blasten 2 %":"Displasia insuficiente, blastos 2 %","Knochenmarkmorphologie ist unverzichtbar.":"La morfología de médula ósea es indispensable.","Breites Pan-Cancer-NGS kann die Kategorie nicht ohne klinisch-hämatologischen Kontext definieren.":"Un NGS pan-cáncer amplio no puede definir la categoría sin contexto clínico-hematológico.","Verlauf ist diagnostisch relevant, wenn Kriterien heute noch nicht erfüllt sind.":"El seguimiento es diagnósticamente relevante cuando los criterios aún no se cumplen hoy.","Was beweisen DNMT3A/TET2 hier?":"¿Qué demuestran aquí DNMT3A/TET2?","Klonale Hämatopoese.":"Hematopoyesis clonal.","Sicher ein MDS.":"MDS con certeza.","Sicher AML.":"AML con certeza.","Eine Keimbahnerkrankung.":"Un trastorno germinal.","Diese Gene überlappen stark zwischen CH, CCUS und myeloischen Neoplasien.":"Estos genes se solapan ampliamente entre CH, CCUS y neoplasias mieloides.","Warum ist 'CHIP' hier unpassend?":"¿Por qué «CHIP» es inapropiado aquí?","Weil persistierende anderweitig ungeklärte Zytopenien bestehen.":"Porque existen citopenias persistentes no explicadas por otra causa.","Weil der Patient älter als 70 ist.":"Porque el paciente tiene más de 70 años.","Weil zwei Mutationen vorliegen.":"Porque hay dos mutaciones.","Weil VAF über 5 % liegt.":"Porque la VAF supera el 5 %.","CHIP setzt gerade das Fehlen entsprechender ungeklärter Zytopenien voraus.":"CHIP requiere precisamente la ausencia de citopenias correspondientes no explicadas.","Welche Kategorie passt bei Zytopenie + Klon ohne MDS-definierende Kriterien am besten?":"¿Qué categoría encaja mejor con citopenia + clon sin criterios definitorios de MDS?","CCUS.":"CCUS.","CHIP.":"CHIP.","AML.":"AML.","Normalbefund.":"Hallazgo normal.","CCUS beschreibt genau diese Zwischenkonstellation.":"CCUS describe exactamente esta constelación intermedia.","Was ist die sinnvollste nächste Strategie?":"¿Cuál es la estrategia más adecuada a continuación?","Klinisch/hämatologisch monitoren und bei Dynamik erneut Knochenmark/Molekulargenetik bewerten.":"Monitorizar clínica/hematológicamente y reevaluar médula ósea/genética molecular si hay progresión.","Sofort MDS-Therapie allein wegen DNMT3A/TET2.":"Iniciar de inmediato tratamiento de MDS únicamente por DNMT3A/TET2.","Keine weitere Kontrolle.":"Sin seguimiento adicional.","Automatisch Keimbahntest für DNMT3A/TET2.":"Realizar automáticamente estudio germinal de DNMT3A/TET2.","Diagnostische Ehrlichkeit plus Verlauf ist hier angemessen.":"La honestidad diagnóstica y el seguimiento son apropiados aquí.","Ordnen Sie den Fall zwischen CHIP, CCUS und MDS ein und formulieren Sie, welche Information die Mutationen liefern – und welche nicht.":"Clasifique el caso entre CHIP, CCUS y MDS y formule qué información aportan las mutaciones y cuál no.","Klonalität anerkennen.":"Reconocer la clonalidad.","Persistierende ungeklärte Zytopenie berücksichtigen.":"Tener en cuenta la citopenia persistente no explicada.","Fehlende MDS-definierende Morphologie/Genetik benennen.":"Indicar la ausencia de morfología/genética definitoria de MDS.","CHIP ausschließen, weil Zytopenie vorhanden.":"Excluir CHIP porque existe citopenia.","CCUS als passendste aktuelle Kategorie formulieren.":"Formular CCUS como la categoría actual más adecuada.","Verlaufskontrolle/erneute Diagnostik bei Progression empfehlen.":"Recomendar seguimiento/reevaluación si hay progresión.","Bei später neu auftretenden definierenden Kriterien Re-Klassifikation zur myeloischen Neoplasie.":"Si más adelante aparecen criterios definitorios, reclasificar como neoplasia mieloide.","Bei identifizierter sekundärer Zytopenieursache Neubewertung der CCUS-Einordnung.":"Si se identifica una causa secundaria de citopenia, reevaluar la clasificación CCUS.","Mutation = MDS":"Mutación = MDS","CH-Gene sind nicht krankheitsspezifisch.":"Los genes CH no son específicos de enfermedad.","Alles CHIP":"Todo es CHIP","Persistierende ungeklärte Zytopenie widerspricht CHIP.":"La citopenia persistente no explicada es incompatible con CHIP.","Mehr Panel = mehr Diagnose":"Más panel = más diagnóstico","Diagnosekriterien bleiben klinisch-morphologisch integriert.":"Los criterios diagnósticos siguen integrados clínica y morfológicamente.","Der richtige Befund ist die Zwischenkategorie":"El resultado correcto es la categoría intermedia","Die Mutationen sind echt und klinisch relevant, aber weder 'Zufalls-CHIP' noch bereits diagnostisches MDS. Die Zytopenie verschiebt den Fall in CCUS – ein Ergebnis, das weniger endgültig klingt, aber fachlich präziser ist.":"Las mutaciones son reales y clínicamente relevantes, pero no representan ni «CHIP incidental» ni todavía un MDS diagnóstico. La citopenia desplaza el caso a CCUS, un resultado que suena menos definitivo pero es más preciso.","Er trainiert, diagnostische Unsicherheit korrekt zu benennen statt molekulare Befunde zu overcallen.":"Entrena la capacidad de nombrar correctamente la incertidumbre diagnóstica en lugar de sobreinterpretar hallazgos moleculares.","CCUS sauber erkannt":"CCUS correctamente reconocido","Zytopenie + DNMT3A/TET2-Klon, aber keine MDS-definierenden Kriterien → CCUS.":"Citopenia + clon DNMT3A/TET2, pero sin criterios definitorios de MDS → CCUS.","Klon, Klinik und Morphologie korrekt integriert.":"Clon, contexto clínico y morfología correctamente integrados.","CH erkannt, Kategorie unscharf":"CH reconocida, categoría poco clara","MDS wird vermieden, aber trotz Zytopenie 'CHIP' berichtet.":"Se evita MDS, pero pese a la citopenia se informa como 'CHIP'.","Definition nicht sauber angewendet.":"La definición no se aplica correctamente.","NGS diagnostiziert MDS":"NGS diagnostica MDS","DNMT3A/TET2 werden allein als MDS-Beweis verwendet.":"DNMT3A/TET2 se utilizan por sí solos como prueba de MDS.","Molekulares Overcalling.":"Sobreinterpretación molecular.","Zytopenien verschlechtern sich":"Las citopenias empeoran","Erneute Knochenmarkdiagnostik inklusive Morphologie/Genetik.":"Repetir el estudio de médula ósea, incluida morfología/genética.","Progression kann neue definierende Kriterien sichtbar machen.":"La progresión puede revelar nuevos criterios definitorios.","Stabiler Verlauf":"Evolución estable","Strukturiertes Monitoring.":"Monitorización estructurada.","Keine unnötige Neoplasietherapie.":"Sin tratamiento innecesario de una neoplasia.","DNMT3A/TET2/ASXL1 sind häufige Gene klonaler Hämatopoese.":"DNMT3A/TET2/ASXL1 son genes frecuentes en la hematopoyesis clonal.","CHIP, CCUS und MDS teilen molekulare Befunde; Kontext trennt die Kategorien.":"CHIP, CCUS y MDS comparten hallazgos moleculares; el contexto separa las categorías.","CHIP ohne ungeklärte Zytopenie, CCUS mit Zytopenie aber ohne definierende Neoplasiekriterien.":"CHIP sin citopenia inexplicada; CCUS con citopenia pero sin criterios definitorios de neoplasia.","NGS erhöht Sensitivität für Klonalität, nicht automatisch Spezifität für MDS.":"NGS aumenta la sensibilidad para detectar clonalidad, no automáticamente la especificidad para MDS.","Verlauf kann Teil der Diagnostik sein.":"La evolución longitudinal puede formar parte del proceso diagnóstico.","Die Mutationen belegen einen myeloischen Klon. Wegen persistierender ungeklärter Zytopenien ist CHIP unpassend; wegen fehlender MDS-definierender Morphologie/Genetik ist ein MDS derzeit nicht gesichert. Die präziseste Einordnung ist CCUS mit strukturierter Verlaufskontrolle.":"Las mutaciones demuestran un clon mieloide. Debido a las citopenias persistentes inexplicadas, CHIP no es apropiado; al faltar morfología/genética definitoria de MDS, actualmente no se puede establecer MDS. La clasificación más precisa es CCUS con seguimiento estructurado.","Mutation ≠ Neoplasie":"Mutación ≠ neoplasia","CHIP vs CCUS":"CHIP vs CCUS","Morphologie integriert":"Morfología integrada","Monitoring":"Monitorización","Welche Mutationen erhöhen die Progressionswahrscheinlichkeit stärker?":"¿Qué mutaciones aumentan más la probabilidad de progresión?","Wie verändert VAF die Risikoeinschätzung, ohne die Diagnose allein zu definieren?":"¿Cómo modifica la VAF la evaluación del riesgo sin definir por sí sola el diagnóstico?","Wann wiederholt man das Knochenmark?":"¿Cuándo debe repetirse el estudio de médula ósea?","CCUS statt binärer CHIP/MDS-Antwort":"CCUS en lugar de una respuesta binaria CHIP/MDS","Klonalität und Neoplasie sind nicht dasselbe":"Clonalidad y neoplasia no son lo mismo","Zytopenie → Klon → Morphologie → CCUS/MDS-Entscheidung":"Citopenia → clon → morfología → decisión CCUS/MDS","MSI-H-CRC mit MLH1/PMS2-Verlust: BRAF-Wildtyp ist noch kein Lynch-Syndrom":"CRC MSI-H con pérdida de MLH1/PMS2: BRAF wild type aún no es síndrome de Lynch","MLH1-Promotor-Methylierung bei MSI…":"Metilación del promotor de MLH1 en MSI…","Viszeralonkologie / Humangenetik-Screening":"Oncología visceral / cribado genético","71-jährige Patientin mit rechtsseitigem Kolonkarzinom. Universal-Screening zeigt Verlust von MLH1/PMS2 und MSI-H.":"Mujer de 71 años con cáncer de colon derecho. El cribado universal muestra pérdida de MLH1/PMS2 y MSI-H.","Ist bei BRAF-Wildtyp nun automatisch von Lynch-Syndrom auszugehen – oder fehlt noch der entscheidende epigenetische Reflex?":"¿BRAF wild type implica ahora automáticamente síndrome de Lynch o aún falta la prueba refleja epigenética decisiva?","Der Tumorbefund soll therapeutisch und hereditär korrekt eingeordnet werden.":"El hallazgo tumoral debe interpretarse correctamente tanto a nivel terapéutico como hereditario.","Rechtsseitiges, lymphozytenreiches Adenokarzinom.":"Adenocarcinoma derecho rico en linfocitos.","Familie":"Antecedentes familiares","Keine auffällige Häufung Lynch-assoziierter Tumoren dokumentiert.":"No se documenta una agregación llamativa de tumores asociados a Lynch.","MLH1/PMS2-Verlust, MSI-H; BRAF V600E nicht nachweisbar.":"Pérdida de MLH1/PMS2, MSI-H; BRAF V600E no detectado.","BRAF-Wildtyp wird fälschlich als positiver Lynch-Nachweis interpretiert.":"BRAF wild type se interpreta erróneamente como evidencia positiva de síndrome de Lynch.","Mäßig differenziertes Adenokarzinom mit medullär/lymphozytenreichen Anteilen.":"Adenocarcinoma moderadamente diferenciado con áreas medulares/ricas en linfocitos.","MLH1 und PMS2 verloren; MSH2/MSH6 erhalten.":"MLH1 y PMS2 perdidos; MSH2/MSH6 conservados.","MSI-high bestätigt.":"MSI-high confirmado.","Somatische MLH1-Promotor-Methylierung als Ursache der MLH1-Inaktivierung.":"Metilación somática del promotor de MLH1 como causa de la inactivación de MLH1.","FFPE-Resektat mit hohem Tumoranteil.":"Pieza de resección FFPE con alto contenido tumoral.","Methylierung":"Metilación","gezielter validierter MLH1-Promotor-Assay möglich.":"Es posible realizar un ensayo dirigido y validado del promotor de MLH1.","Wildtyp – informativ, aber nicht beweisend für Lynch.":"Wild type: informativo, pero no demuestra síndrome de Lynch.","Ein negatives Ausschlussmerkmal darf nicht in einen positiven hereditären Nachweis umgedeutet werden.":"Un marcador de exclusión negativo no debe reinterpretarse como evidencia hereditaria positiva.","MLH1-Promotor-Methylierung":"Metilación del promotor de MLH1","Verlust von MLH1/PMS2 bei erhaltener MSH2/MSH6-Expression.":"Pérdida de MLH1/PMS2 con expresión conservada de MSH2/MSH6.","MSI-high bestätigt; damit besteht ein therapeutisch relevanter dMMR/MSI-H-Kontext.":"MSI-high confirmado; con ello existe un contexto dMMR/MSI-H terapéuticamente relevante.","BRAF V600E nicht nachweisbar. Das entfernt ein starkes Indiz für sporadische MLH1-Inaktivierung, beweist Lynch aber nicht.":"BRAF V600E no detectado. Esto elimina un indicio fuerte de inactivación esporádica de MLH1, pero no demuestra síndrome de Lynch.","Deutliche MLH1-Promotor-Hypermethylierung. Die Konstellation spricht bei dieser 71-jährigen Patientin stark für eine sporadische epigenetische MLH1-Silenzierung; klinische/familiäre Auffälligkeiten bleiben dennoch zu berücksichtigen.":"Hipermetilación marcada del promotor de MLH1. En esta paciente de 71 años, la constelación apoya firmemente un silenciamiento epigenético esporádico de MLH1; aun así deben considerarse las particularidades clínicas y familiares.","Kernbefund":"Hallazgo clave","dMMR/MSI-H durch MLH1/PMS2-Verlust.":"dMMR/MSI-H por pérdida de MLH1/PMS2.","Wildtyp – kein Lynch-Beweis.":"Wild type: no demuestra síndrome de Lynch.","Der dMMR/MSI-H-Status ist therapeutisch relevant. Für die hereditäre Einordnung zeigt der MLH1/PMS2-Verlust zunächst nur die Richtung der Reflexdiagnostik. BRAF-Wildtyp beweist kein Lynch-Syndrom. Die nachgewiesene MLH1-Promotor-Hypermethylierung spricht stark für eine sporadische epigenetische MLH1-Inaktivierung; Alter, Familienanamnese und besondere klinische Konstellationen können dennoch eine weitergehende humangenetische Beurteilung rechtfertigen.":"El estado dMMR/MSI-H es terapéuticamente relevante. Para la clasificación hereditaria, la pérdida de MLH1/PMS2 inicialmente solo indica la dirección del estudio reflejo. BRAF wild type no demuestra síndrome de Lynch. La hipermetilación detectada del promotor de MLH1 apoya firmemente una inactivación epigenética esporádica de MLH1; aun así, la edad, los antecedentes familiares y determinadas constelaciones clínicas pueden justificar una evaluación genética adicional.","Teilbefund: MLH1/PMS2-Verlust + MSI-H ist nicht synonym mit Lynch; die Ursache der MLH1-Inaktivierung muss reflexdiagnostisch geklärt werden.":"Resultado parcial: pérdida de MLH1/PMS2 + MSI-H no es sinónimo de síndrome de Lynch; la causa de la inactivación de MLH1 debe aclararse mediante estudio reflejo.","dMMR/MSI-H therapeutisch korrekt einordnen":"Interpretar correctamente dMMR/MSI-H desde el punto de vista terapéutico","BRAF-Wildtyp nicht als Lynch-Beweis interpretieren":"No interpretar BRAF wild type como prueba de síndrome de Lynch","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex priorisieren":"Priorizar la metilación del promotor de MLH1 como prueba refleja epigenética directa","Alter/Familie/klinischen Kontext trotz Methylierung berücksichtigen":"Considerar edad/familia/contexto clínico pese a la metilación","Falschaussage: BRAF-Wildtyp + MLH1/PMS2-Verlust = Lynch gesichert":"Afirmación falsa: BRAF wild type + pérdida de MLH1/PMS2 = síndrome de Lynch confirmado","Optimale Lösung: MSI-H/dMMR therapeutisch nutzen, MLH1/PMS2-Verlust hereditär reflexdiagnostisch abarbeiten und BRAF-Wildtyp nicht überinterpretieren; positive MLH1-Methylierung spricht stark für sporadische Silenzierung.":"Solución óptima: utilizar MSI-H/dMMR terapéuticamente, estudiar la pérdida de MLH1/PMS2 mediante el algoritmo reflejo hereditario adecuado y no sobreinterpretar BRAF wild type; la metilación positiva de MLH1 apoya firmemente un silenciamiento esporádico.","MLH1 methylation":"Metilación de MLH1","BRAF wild type":"BRAF wild type","BRAF-Wildtyp ist kein positiver Lynch-Test":"BRAF wild type no es una prueba positiva de Lynch","Gastrointestinale Molekularpathologie / MTB / Humangenetik":"Patología molecular gastrointestinal / MTB / genética clínica","MLH1/PMS2-Verlust als Trigger einer spezifischen Reflexdiagnostik verstehen.":"Entender la pérdida de MLH1/PMS2 como desencadenante de un estudio reflejo específico.","MSI-H/dMMR therapeutische und hereditäre Ebenen trennen.":"Separar las dimensiones terapéutica y hereditaria de MSI-H/dMMR.","BRAF V600E positiv als starkes sporadisches Indiz, BRAF-Wildtyp aber nicht als Lynch-Beweis verstehen.":"Entender BRAF V600E positivo como un fuerte indicio de origen esporádico, pero no BRAF wild type como prueba de Lynch.","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex einordnen.":"Considerar la metilación del promotor de MLH1 como la prueba refleja epigenética directa.","Alter und Familienanamnese trotz scheinbar sporadischem Muster berücksichtigen.":"Considerar la edad y los antecedentes familiares pese a un patrón aparentemente esporádico.","MLH1 und PMS2 fehlen, der Tumor ist MSI-H – und BRAF ist Wildtyp. Im Board fällt sofort der Satz: 'Dann ist es Lynch.' Genau an dieser Stelle setzt der Fall an.":"Faltan MLH1 y PMS2, el tumor es MSI-H y BRAF es wild type. En el board surge enseguida la frase: «Entonces es Lynch». Precisamente ahí empieza el caso.","71-jährige Patientin mit rechtsseitigem MSI-H-CRC und MLH1/PMS2-Verlust. BRAF V600E ist nicht nachweisbar. Die zentrale Frage ist, ob das bereits Lynch beweist oder ob die epigenetische Ursache der MLH1-Silenzierung noch direkt geprüft werden muss.":"Mujer de 71 años con CRC derecho MSI-H y pérdida de MLH1/PMS2. BRAF V600E no se detecta. La cuestión central es si esto ya demuestra síndrome de Lynch o si aún debe estudiarse directamente la causa epigenética del silenciamiento de MLH1.","Therapieebene":"Dimensión terapéutica","MSI-H/dMMR ist bereits ein wichtiger prädiktiver Tumorbefund.":"MSI-H/dMMR ya es un hallazgo tumoral predictivo importante.","Die Therapieaussage braucht nicht erst eine Lynch-Diagnose.":"La conclusión terapéutica no requiere primero un diagnóstico de Lynch.","MLH1/PMS2-Verlust kann sporadisch oder hereditär entstehen.":"La pérdida de MLH1/PMS2 puede aparecer de forma esporádica o hereditaria.","Reflexdiagnostik klärt die Ursache.":"El estudio reflejo aclara la causa.","Negativ ist nicht positiv":"Negativo no significa positivo","BRAF-Wildtyp entfernt ein sporadisches Indiz, beweist aber Lynch nicht.":"BRAF wild type elimina un indicio de origen esporádico, pero no demuestra síndrome de Lynch.","Ausschlussmarker nicht in Bestätigungsmarker verwandeln.":"No convertir un marcador de exclusión en un marcador de confirmación.","MLH1/PMS2 verloren":"MLH1/PMS2 perdidos","MSI-high":"MSI-high","V600E nicht nachweisbar":"V600E no detectado","Ausreichendes Resektat für gezielte MLH1-Methylierungsanalyse.":"Pieza de resección adecuada para análisis dirigido de metilación de MLH1.","Kein Grund für ein breites Panel, wenn die Reflexfrage fokussiert beantwortet werden kann.":"No es necesario un panel amplio si la pregunta refleja focalizada puede responderse directamente.","Klinischer Kontext bleibt Teil der Lynch-Risikobewertung.":"El contexto clínico sigue formando parte de la evaluación del riesgo de Lynch.","Was bedeutet BRAF-Wildtyp bei MLH1/PMS2-Verlust?":"¿Qué significa BRAF wild type en el contexto de pérdida de MLH1/PMS2?","Lynch bleibt möglich, ist aber nicht bewiesen; MLH1-Promotor-Methylierung sollte direkt geprüft werden.":"El síndrome de Lynch sigue siendo posible, pero no está demostrado; debe estudiarse directamente la metilación del promotor de MLH1.","Lynch ist damit gesichert.":"Con ello queda confirmado el síndrome de Lynch.","Sporadisch ist damit gesichert.":"Con ello queda confirmado un origen esporádico.","BRAF hat nie Bedeutung im CRC-Lynch-Screening.":"BRAF nunca tiene relevancia en el cribado de Lynch en CRC.","Negatives BRAF-Ergebnis ist kein positiver Lynch-Nachweis.":"Un resultado BRAF negativo no es evidencia positiva de síndrome de Lynch.","MLH1-Promotor-Methylierung ist deutlich positiv. Was ist die beste Interpretation?":"La metilación del promotor de MLH1 es claramente positiva. ¿Cuál es la mejor interpretación?","Starkes Indiz für sporadische epigenetische MLH1-Silenzierung; klinische Sonderkonstellationen trotzdem beachten.":"Fuerte indicio de silenciamiento epigenético esporádico de MLH1; aun así deben considerarse situaciones clínicas especiales.","Beweist Lynch.":"Demuestra síndrome de Lynch.","Macht MSI-H therapeutisch irrelevant.":"Hace que MSI-H sea terapéuticamente irrelevante.","Ist bei CRC bedeutungslos.":"No tiene relevancia en CRC.","Tumorale MLH1-Hypermethylierung erklärt häufig sporadischen MLH1/PMS2-Verlust.":"La hipermetilación tumoral de MLH1 explica con frecuencia la pérdida esporádica de MLH1/PMS2.","Welche Aussage trennt die Ebenen korrekt?":"¿Qué afirmación separa correctamente ambas dimensiones?","MSI-H/dMMR ist therapeutisch relevant; Lynch-Abklärung ist eine zusätzliche hereditäre Frage.":"MSI-H/dMMR es terapéuticamente relevante; el estudio de Lynch es una cuestión hereditaria adicional.","Immuntherapie darf erst nach Keimbahnbefund diskutiert werden.":"La inmunoterapia solo puede discutirse tras obtener un resultado germinal.","dMMR und Lynch sind Synonyme.":"dMMR y síndrome de Lynch son sinónimos.","Nur BRAF entscheidet beide Ebenen.":"Solo BRAF determina ambas dimensiones.","Tumorbiomarker und hereditäre Diagnose sind verwandt, aber nicht identisch.":"El biomarcador tumoral y el diagnóstico hereditario están relacionados, pero no son idénticos.","Wann sollte trotz MLH1-Methylierung genauer hingesehen werden?":"¿Cuándo debe investigarse con más detalle pese a la metilación de MLH1?","Bei ungewöhnlich jungem Alter, auffälliger Familien-/Eigenanamnese oder anderer klinischer Diskordanz.":"Ante edad inusualmente joven, antecedentes personales/familiares llamativos u otra discordancia clínica.","Nie.":"Nunca.","Immer vollständige Keimbahndiagnostik unabhängig vom Kontext.":"Realizar siempre estudio germinal completo independientemente del contexto.","Nur bei PD-L1-Positivität.":"Solo si PD-L1 es positivo.","Seltene konstitutionelle Epimutationen und klinische Sonderkonstellationen verhindern absolute Aussagen.":"Las epimutaciones constitucionales raras y las situaciones clínicas especiales impiden afirmaciones absolutas.","Formulieren Sie eine zweigeteilte MTB-Aussage: therapeutische Bedeutung von MSI-H/dMMR und hereditäre Einordnung des MLH1/PMS2-Verlusts nach BRAF- und MLH1-Methylierungsbefund.":"Formule una conclusión de MTB en dos partes: significado terapéutico de MSI-H/dMMR e interpretación hereditaria de la pérdida de MLH1/PMS2 tras los resultados de BRAF y metilación de MLH1.","dMMR/MSI-H therapeutisch einordnen.":"Interpretar dMMR/MSI-H terapéuticamente.","MLH1/PMS2-Verlust als Reflextrigger verstehen.":"Entender la pérdida de MLH1/PMS2 como desencadenante del estudio reflejo.","BRAF-Wildtyp nicht als Lynch-Beweis formulieren.":"No informar BRAF wild type como prueba de síndrome de Lynch.","MLH1-Promotor-Methylierung direkt testen.":"Analizar directamente la metilación del promotor de MLH1.","Positive Methylierung als starkes sporadisches Indiz berichten.":"Informar la metilación positiva como fuerte indicio de silenciamiento esporádico.","Klinische Sonderkonstellationen offenhalten.":"Mantener abiertas las situaciones clínicas especiales.","In Laborpfaden, die BRAF und Methylierung anders sequenzieren, ist die Kernaussage identisch: BRAF-WT allein reicht nicht für Lynch-Diagnose.":"En algoritmos de laboratorio que secuencian BRAF y metilación de forma distinta, el mensaje clave es el mismo: BRAF wild type por sí solo no basta para diagnosticar Lynch.","Bei klarer hereditärer Auffälligkeit humangenetische Vorstellung trotz Tumormethylierung erwägen.":"Si existen rasgos hereditarios claramente sospechosos, considerar consulta genética pese a la metilación tumoral.","BRAF-WT = Lynch":"BRAF wild type = síndrome de Lynch","Negatives Ausschlussindiz ist kein positiver hereditärer Nachweis.":"Un indicio de exclusión negativo no es evidencia hereditaria positiva.","dMMR = Lynch":"dMMR = síndrome de Lynch","Viele MLH1/PMS2-defiziente CRC sind sporadisch methyliert.":"Muchos CRC deficientes en MLH1/PMS2 presentan metilación esporádica.","Methylierung löscht MSI-Therapiebedeutung":"La metilación elimina el significado terapéutico de MSI","Therapeutische und hereditäre Ebenen werden vermischt.":"Se mezclan las dimensiones terapéutica y hereditaria.","Der BRAF-Wildtyp führt in die falsche Sicherheit":"BRAF wild type genera una falsa seguridad","Obwohl BRAF V600E fehlt, ist der MLH1-Promotor deutlich methyliert. Das kippt die intuitive 'BRAF-WT = Lynch'-Kurzform und zeigt, warum der direkte epigenetische Reflex diagnostisch stärker ist.":"Aunque BRAF V600E está ausente, el promotor de MLH1 está claramente metilado. Esto rompe el atajo intuitivo «BRAF wild type = Lynch» y muestra por qué la prueba refleja epigenética directa es diagnósticamente más sólida.","Der Fall trainiert Negativbefunde, Reflexdiagnostik und die Trennung von Tumortherapie und Familienmedizin.":"El caso entrena la interpretación de hallazgos negativos, el diagnóstico reflejo y la separación entre terapia tumoral y medicina familiar/genética.","Zwei Ebenen sauber getrennt":"Dos dimensiones claramente separadas","MSI-H/dMMR therapeutisch relevant; BRAF-WT kein Lynch-Beweis; MLH1-Methylierung positiv → sporadische Silenzierung stark wahrscheinlich.":"MSI-H/dMMR terapéuticamente relevante; BRAF wild type no demuestra Lynch; metilación de MLH1 positiva → silenciamiento esporádico muy probable.","Reflexdiagnostik korrekt.":"Diagnóstico reflejo correcto.","Lynch offen, Methylierung vergessen":"Lynch queda abierto, se olvida la metilación","BRAF-WT wird korrekt nicht überinterpretiert, aber der direkte MLH1-Reflex fehlt.":"BRAF wild type no se sobreinterpreta, correctamente, pero falta el estudio reflejo directo de MLH1.","Diagnostik unvollständig.":"Estudio diagnóstico incompleto.","Keimbahndiagnose aus negativem Tumormarker abgeleitet.":"Diagnóstico germinal inferido a partir de un marcador tumoral negativo.","Kritisches Overcalling.":"Sobreinterpretación crítica.","MLH1-Methylierung positiv":"Metilación de MLH1 positiva","Sporadische MLH1-Silenzierung als wahrscheinlich berichten; Klinik/Familie abgleichen.":"Informar como probable el silenciamiento esporádico de MLH1; correlacionar con contexto clínico/antecedentes familiares.","Viele unnötige Keimbahnabklärungen können vermieden werden, ohne Sonderfälle zu ignorieren.":"Pueden evitarse muchos estudios germinales innecesarios sin ignorar los casos especiales.","Humangenetische/germline Abklärung priorisieren.":"Priorizar evaluación genética/germinal.","Lynch-Verdacht bleibt bestehen.":"Persiste la sospecha de síndrome de Lynch.","MLH1/PMS2-Verlust ist kein automatischer Lynch-Befund.":"La pérdida de MLH1/PMS2 no equivale automáticamente a Lynch.","BRAF V600E kann sporadische MLH1-Inaktivierung stützen; BRAF-Wildtyp beweist Lynch nicht.":"BRAF V600E puede apoyar una inactivación esporádica de MLH1; BRAF wild type no demuestra síndrome de Lynch.","MLH1-Promotor-Methylierung ist ein direkter epigenetischer Reflex.":"La metilación del promotor de MLH1 es una prueba refleja epigenética directa.","MSI-H/dMMR hat eine therapeutische Aussage unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"MSI-H/dMMR tiene significado terapéutico independientemente de que la causa sea esporádica o hereditaria.","Sehr junges Alter oder auffällige Familienanamnese können trotz Tumormethylierung weitere Abklärung rechtfertigen.":"Una edad muy joven o antecedentes familiares sospechosos pueden justificar estudios adicionales pese a la metilación tumoral.","MSI-H/dMMR ist therapeutisch relevant. Für die hereditäre Einordnung ist BRAF-Wildtyp nicht beweisend; die positive MLH1-Promotor-Methylierung spricht stark für sporadische MLH1-Silenzierung. Alter und Familienanamnese bleiben als Sicherheitsnetz bestehen.":"MSI-H/dMMR es terapéuticamente relevante. Para la clasificación hereditaria, BRAF wild type no es concluyente; la metilación positiva del promotor de MLH1 apoya firmemente un silenciamiento esporádico de MLH1. La edad y los antecedentes familiares siguen siendo una red de seguridad.","BRAF-WT nicht overcallen":"No sobreinterpretar BRAF wild type","Therapie vs Heredität":"Terapia vs herencia","Kontext":"Contexto","Warum ist ein negativer Marker selten ein positiver Beweis?":"¿Por qué un marcador negativo rara vez constituye una prueba positiva?","Wie unterscheiden sich BRAF- und MLH1-Methylierungsreflex?":"¿En qué se diferencian los estudios reflejos de BRAF y metilación de MLH1?","Wann kann Tumormethylierung eine hereditäre Ursache nicht vollständig ausschließen?":"¿Cuándo puede la metilación tumoral no excluir por completo una causa hereditaria?","MLH1-Methylierung positiv trotz BRAF-WT":"Metilación de MLH1 positiva pese a BRAF wild type","BRAF-Wildtyp ist kein Lynch-Beweis":"BRAF wild type no demuestra síndrome de Lynch","MMR/MSI → BRAF-Kontext → MLH1-Methylierung → hereditäre Einordnung":"MMR/MSI → contexto BRAF → metilación de MLH1 → clasificación hereditaria","mCRC und Bevacizumab: Anti-VEGF braucht keinen VHL-Test":"mCRC y bevacizumab: anti-VEGF no requiere una prueba de VHL","mCRC: Bevacizumab und VEGF-Angioge…":"mCRC: bevacizumab y angiogénesis VEGF…","63-jähriger Patient mit metastasiertem rechtsseitigem Kolonkarzinom, KRAS p.G12D-mutiert. Im Board wird Bevacizumab als Bestandteil der Systemtherapie diskutiert.":"Varón de 63 años con cáncer de colon derecho metastásico, mutado KRAS p.G12D. En el board se discute bevacizumab como parte del tratamiento sistémico.","Muss vor Anti-VEGF-Therapie die VHL/HIF/VEGF-Achse des Tumors molekular getestet oder eine hohe VEGF-Expression nachgewiesen werden?":"¿Antes de la terapia anti-VEGF debe estudiarse molecularmente el eje VHL/HIF/VEGF del tumor o demostrarse una alta expresión de VEGF?","Therapieentscheidung in dieser Woche.":"Decisión terapéutica esta semana.","Rechtsseitiges mCRC mit multiplen Lebermetastasen.":"mCRC derecho con múltiples metástasis hepáticas.","KRAS p.G12D; BRAF-Wildtyp; pMMR/MSS aus Basisdiagnostik.":"KRAS p.G12D; BRAF wild type; pMMR/MSS del estudio basal.","Anti-EGFR ist wegen RAS-Mutation nicht der naheliegende Weg; eine antiangiogene Kombination wird diskutiert.":"Anti-EGFR no es la vía evidente por la mutación RAS; se discute una combinación antiangiogénica.","Mechanistische Biologie wird mit einem notwendigen prädiktiven Companion Diagnostic verwechselt.":"La biología mecanística se confunde con un companion diagnostic predictivo obligatorio.","Konventionelles kolorektales Adenokarzinom mit vitalen Metastasenarealen.":"Adenocarcinoma colorrectal convencional con áreas metastásicas viables.","Gefäße":"Vasos","Tumor zeigt erwartbare Neovaskularisation; kein spezifischer morphologischer Selektionsmarker.":"El tumor muestra neovascularización esperable; no existe un marcador morfológico específico de selección.","Basisprofil":"Perfil basal","RAS-mutiert, pMMR/MSS.":"RAS mutado, pMMR/MSS.","Welche Rolle spielt VEGF-Biologie für das Verständnis – und welche gerade nicht für die Testauswahl?":"¿Qué papel desempeña la biología de VEGF en la comprensión y qué papel precisamente no desempeña en la selección de pruebas?","FFPE-Lebermetastase, ausreichend für Zusatzanalysen.":"Metástasis hepática FFPE, adecuada para análisis adicionales.","Begrenzt; keine diagnostische Fragestellung rechtfertigt einen RCC-spezifischen VHL/HIF-Test.":"Limitado; ninguna cuestión diagnóstica justifica una prueba VHL/HIF específica de RCC.","Mechanismus":"Mecanismo","VEGF-A ist ein zentraler proangiogener Ligand; Bevacizumab neutralisiert VEGF-A.":"VEGF-A es un ligando proangiogénico central; bevacizumab neutraliza VEGF-A.","Ein biologisch plausibler Signalweg ist nicht automatisch ein validierter Patientenselektions-Biomarker.":"Una vía biológicamente plausible no es automáticamente un biomarcador validado de selección de pacientes.","VEGF-/Angiogenese-Kontext korrekt einordnen":"Interpretar correctamente el contexto VEGF/angiogénesis","CRC-Basisprofil":"Perfil basal de CRC","KRAS p.G12D, BRAF-Wildtyp, keine zusätzliche Alteration, die einen Anti-VEGF-spezifischen Companion-Diagnostic-Pfad definiert.":"KRAS p.G12D, BRAF wild type, sin alteración adicional que defina una vía de companion diagnostic específica para anti-VEGF.","VEGF-Kontext":"Contexto VEGF","Anti-VEGF hemmt einen zentralen Angiogeneseweg; beim mCRC existiert jedoch kein etablierter routinemäßiger Tumor-VEGF- oder VHL/HIF-Test, der vor Bevacizumab positiv sein muss.":"Anti-VEGF inhibe una vía central de angiogénesis; sin embargo, en mCRC no existe una prueba tumoral rutinaria establecida de VEGF o VHL/HIF que deba ser positiva antes de bevacizumab.","Molekularer CRC-Kontext":"Contexto molecular de CRC","KRAS-mutiert, pMMR/MSS.":"KRAS mutado, pMMR/MSS.","Kernfrage":"Pregunta central","Biologischen Wirkmechanismus von prädiktiver Testpflicht trennen.":"Separar el mecanismo biológico de acción de la exigencia de pruebas predictivas.","Bevacizumab adressiert die VEGF-A-vermittelte Angiogenese, seine klinische Anwendung beim mCRC setzt aber keinen positiven VHL/HIF-/VEGF-Tumortest voraus. Die RAS-Mutation erklärt hier den fehlenden anti-EGFR-Kontext, ist aber kein Gegenargument gegen die antiangiogene Wirklogik. Zusätzliche VHL/HIF-Testung wäre ein aus dem RCC übertragener Low-value-Copyover.":"Bevacizumab actúa sobre la angiogénesis mediada por VEGF-A, pero su uso clínico en mCRC no requiere una prueba tumoral VHL/HIF/VEGF positiva. La mutación RAS explica aquí la ausencia de un contexto anti-EGFR, pero no es un argumento contra el mecanismo antiangiogénico. Un estudio adicional VHL/HIF sería un copyover de bajo valor procedente de RCC.","Teilbefund: VEGF ist biologisch relevant, aber es fehlt die Trennung zwischen Wirkmechanismus und validiertem Selektionsbiomarker.":"Resultado parcial: VEGF es biológicamente relevante, pero falta distinguir entre mecanismo de acción y biomarcador validado de selección.","VEGF-A/Angiogenese als Wirkmechanismus erklären":"Explicar VEGF-A/angiogénesis como mecanismo de acción","Keinen routinemäßigen positiven VEGF-/VHL-Test als Voraussetzung behaupten":"No afirmar que se requiere una prueba positiva rutinaria de VEGF/VHL","RAS-Mutation korrekt auf anti-EGFR, nicht auf Anti-VEGF beziehen":"Relacionar correctamente la mutación RAS con anti-EGFR, no con anti-VEGF","RCC-spezifische VHL/HIF-Testung vermeiden":"Evitar pruebas VHL/HIF específicas de RCC","Falschaussage: Bevacizumab nur bei molekular aktivierter VHL/HIF-Achse":"Afirmación falsa: bevacizumab solo con activación molecular del eje VHL/HIF","Optimale Lösung: Anti-VEGF biologisch sauber erklären, aber keinen erfundenen Companion Diagnostic verlangen; RAS-Status und VEGF-Therapieachse sind unterschiedliche Entscheidungsebenen.":"Solución óptima: explicar correctamente la biología anti-VEGF sin inventar un companion diagnostic; el estado RAS y el eje terapéutico VEGF son niveles de decisión distintos.","Bevacizumab":"Bevacizumab","VEGF":"VEGF","Angiogenese":"Angiogénesis","KRAS":"KRAS","Biomarker hierarchy":"Jerarquía de biomarcadores","Anti-VEGF ist ein Wirkmechanismus, kein VHL-Companion-Diagnostic":"Anti-VEGF es un mecanismo de acción, no un companion diagnostic de VHL","Gastroonkologie / Molekularpathologie / MTB":"Oncología gastrointestinal / patología molecular / MTB","VEGF-Angiogenese als Wirkmechanismus von Bevacizumab erklären.":"Explicar la angiogénesis VEGF como mecanismo de acción de bevacizumab.","Wirkmechanismus und prädiktiven Companion Diagnostic sauber trennen.":"Separar claramente mecanismo de acción y companion diagnostic predictivo.","RAS-Status korrekt auf anti-EGFR und nicht auf Anti-VEGF beziehen.":"Relacionar correctamente el estado RAS con anti-EGFR y no con anti-VEGF.","Entitätsfremde VHL/HIF-Testung beim mCRC vermeiden.":"Evitar pruebas VHL/HIF ajenas a la entidad en mCRC.","Material- und Testökonomie als Teil guter Präzisionsonkologie verstehen.":"Entender la economía de material y pruebas como parte de una buena oncología de precisión.","Der Tumor ist KRAS-mutiert. Jemand fragt, ob man für Bevacizumab jetzt noch 'VHL/HIF/VEGF molekular bestätigen' müsse. Genau diese scheinbar logische Zusatzdiagnostik ist der Fehler.":"El tumor está mutado en KRAS. Alguien pregunta si para bevacizumab hay que «confirmar molecularmente» VHL/HIF/VEGF. Precisamente esa prueba adicional aparentemente lógica es el error.","63-jähriger Patient mit KRAS-mutiertem, pMMR/MSS mCRC. Bevacizumab wird als Teil einer systemischen Kombination diskutiert. Die Aufgabe ist nicht, einen neuen Biomarker zu erfinden, sondern Mechanismus, RAS-Kontext und echte Testpflicht zu trennen.":"Varón de 63 años con mCRC mutado en KRAS, pMMR/MSS. Se plantea bevacizumab como parte de una combinación sistémica. La tarea no es inventar un nuevo biomarcador, sino separar mecanismo, contexto RAS y requisitos reales de pruebas.","RAS beantwortet eine andere Frage":"RAS responde a otra pregunta","KRAS p.G12D schließt einen klassischen anti-EGFR-Kontext aus.":"KRAS p.G12D excluye un contexto anti-EGFR clásico.","Das macht Anti-VEGF nicht biologisch unplausibel.":"Eso no hace que anti-VEGF sea biológicamente implausible.","VEGF ist zentral":"VEGF es central","Tumorangiogenese benötigt proangiogene Signale.":"La angiogénesis tumoral requiere señales proangiogénicas.","Zentraler Mechanismus bedeutet nicht automatisch Companion Diagnostic.":"Un mecanismo central no implica automáticamente un companion diagnostic.","RCC-Copyover":"Copyover de RCC","VHL/HIF ist beim ccRCC kanonisch.":"VHL/HIF es canónico en ccRCC.","Signalwege dürfen nicht blind zwischen Entitäten als Testalgorithmus übertragen werden.":"Las vías no deben trasladarse ciegamente entre entidades como algoritmos de pruebas.","CRC-Profil":"Perfil CRC","KRAS p.G12D, BRAF-WT, pMMR/MSS":"KRAS p.G12D, BRAF wild type, pMMR/MSS","metastasiert, systemische Therapie geplant":"Metastásico, tratamiento sistémico planificado","ausreichend, aber kein Grund für unnötige Zusatztests":"Adecuado, pero sin motivo para pruebas adicionales innecesarias","Keine validierte positive VEGF-/VHL-Testpflicht vor Bevacizumab im mCRC.":"No existe un requisito validado de prueba VEGF/VHL positiva antes de bevacizumab en mCRC.","Entitätsfremde Testung verbraucht Ressourcen ohne Entscheidungsgewinn.":"Las pruebas ajenas a la entidad consumen recursos sin aportar valor a la decisión.","Mechanistische Erklärung kann ohne zusätzlichen Wet-lab-Test erfolgen.":"La explicación mecanística puede darse sin una prueba wet-lab adicional.","Was bedeutet KRAS p.G12D für die Anti-VEGF-Frage?":"¿Qué significa KRAS p.G12D para la cuestión anti-VEGF?","Es betrifft die anti-EGFR-Logik; es ist kein automatischer Ausschluss von Bevacizumab.":"Afecta a la lógica anti-EGFR; no excluye automáticamente bevacizumab.","Es ist eine Kontraindikation gegen Anti-VEGF.":"Es una contraindicación para anti-VEGF.","Es beweist besonders gutes Bevacizumab-Ansprechen.":"Demuestra una respuesta especialmente buena a bevacizumab.","RAS hat im CRC gar keine therapeutische Bedeutung.":"RAS no tiene ninguna relevancia terapéutica en CRC.","Therapieachsen müssen getrennt gehalten werden.":"Los ejes terapéuticos deben mantenerse separados.","Braucht Bevacizumab einen positiven Tumor-VEGF/VHL-Test?":"¿Requiere bevacizumab una prueba tumoral VEGF/VHL positiva?","Nein; der Wirkmechanismus ist biologisch VEGF-gerichtet, aber es existiert kein solcher routinemäßiger Companion-Diagnostic-Pfad.":"No; el mecanismo de acción está biológicamente dirigido a VEGF, pero no existe una vía rutinaria de companion diagnostic de ese tipo.","Ja, VHL-Mutation ist Voraussetzung.":"Sí, se requiere una mutación VHL.","Ja, hohe VEGF-IHC muss dokumentiert sein.":"Sí, debe documentarse una IHC VEGF alta.","Ja, HIF-2α muss mutiert sein.":"Sí, HIF-2α debe estar mutado.","Mechanismus und Testpflicht sind nicht dasselbe.":"Mecanismo de acción y requisito de prueba no son lo mismo.","Warum ist ein VHL/HIF-Panel hier Low-value?":"¿Por qué un panel VHL/HIF es de bajo valor aquí?","Es importiert ccRCC-Biologie in einen CRC-Therapiealgorithmus ohne validierten Selektionsnutzen.":"Importa biología de ccRCC a un algoritmo terapéutico de CRC sin beneficio validado de selección.","Nur weil es teuer ist.":"Solo porque es caro.","Weil CRC keine DNA enthält.":"Porque CRC no contiene ADN.","Weil VEGF im CRC keine Rolle spielt.":"Porque VEGF no tiene ningún papel en CRC.","Entitätsspezifische Evidenz entscheidet.":"La evidencia específica de la entidad determina la respuesta.","Was ist hier Präzisionsonkologie?":"¿Qué es oncología de precisión aquí?","Die richtigen wenigen Informationen verwenden und unnötige Tests weglassen.":"Usar la poca información adecuada y omitir pruebas innecesarias.","Immer das breiteste Panel bestellen.":"Pedir siempre el panel más amplio.","Jeden bekannten Signalweg molekular bestätigen.":"Confirmar molecularmente cada vía conocida.","Nur positive Biomarker zählen.":"Solo cuentan los biomarcadores positivos.","Präzision ist nicht Informationsmaximierung.":"La precisión no es maximización de información.","Formulieren Sie die Anti-VEGF-Rationale und begründen Sie explizit, warum weder KRAS-Mutation noch fehlende VHL/HIF-Testung die Bevacizumab-Logik aufheben.":"Formule la justificación anti-VEGF y explique explícitamente por qué ni la mutación KRAS ni la ausencia de pruebas VHL/HIF invalidan la lógica de bevacizumab.","KRAS p.G12D als anti-EGFR-Resistenzkontext benennen.":"Identificar KRAS p.G12D como contexto de resistencia anti-EGFR.","VEGF-Angiogenese als Wirkmechanismus erklären.":"Explicar la angiogénesis VEGF como mecanismo de acción.","Keine positive VEGF-/VHL-Testpflicht erfinden.":"No inventar un requisito de prueba VEGF/VHL positiva.","VHL/HIF-Testung als entitätsfremden Low-value-Test vermeiden.":"Evitar pruebas VHL/HIF como test de bajo valor ajeno a la entidad.","Therapieentscheidung im klinischen CRC-Kontext belassen.":"Mantener la decisión terapéutica dentro del contexto clínico de CRC.","Breites CRC-Panel nur, wenn andere therapeutische Fragestellungen offen sind.":"Utilizar un panel amplio de CRC solo si quedan otras cuestiones terapéuticas abiertas.","VEGF-Biologie rein interpretativ erklären, ohne Zusatztest.":"Explicar la biología de VEGF de forma interpretativa, sin pruebas adicionales.","VHL testen, weil VEGF":"Analizar VHL porque VEGF","RCC-Biologie wird ohne Evidenz in CRC übertragen.":"La biología de RCC se traslada a CRC sin evidencia.","KRAS-mutiert = kein Bevacizumab":"KRAS mutado = no bevacizumab","RAS und VEGF sind unterschiedliche therapeutische Achsen.":"RAS y VEGF son ejes terapéuticos distintos.","Mehr Test = mehr Präzision":"Más pruebas = más precisión","Test ohne Entscheidungsnutzen ist Low-value.":"Una prueba sin valor para la decisión es de bajo valor.","Der beste Test ist hier: keiner":"La mejor prueba aquí es: ninguna","Die vorhandenen Daten reichen für die Anti-VEGF-Rationale. Ein VHL/HIF-Panel würde nichts klinisch Validiertes hinzufügen. Der Twist ist, dass fachliche Tiefe nicht durch zusätzliche Diagnostik, sondern durch korrektes Weglassen entsteht.":"Los datos disponibles bastan para la justificación anti-VEGF. Un panel VHL/HIF no aportaría nada clínicamente validado. El giro es que la profundidad experta no se demuestra con más diagnóstico, sino omitiendo correctamente lo innecesario.","Er trainiert Testökonomie und verhindert pathway-driven Overdiagnostics.":"Entrena la economía de pruebas y evita el sobrediagnóstico impulsado por pathways.","Mechanismus ohne Pseudobiomarker":"Mecanismo sin pseudobiomarcador","KRAS-mutiertes mCRC; Anti-VEGF biologisch plausibel, kein VHL/VEGF Companion Diagnostic erforderlich.":"mCRC mutado en KRAS; anti-VEGF biológicamente plausible, no se requiere companion diagnostic VHL/VEGF.","Saubere Evidenzhierarchie.":"Jerarquía de evidencia clara.","VEGF erklärt, RAS unscharf":"VEGF explicado, RAS poco claro","Angiogenese korrekt, aber RAS-/anti-EGFR-Kontext wird vermischt.":"La angiogénesis es correcta, pero se mezcla el contexto RAS/anti-EGFR.","Therapieachsen trennen.":"Separar los ejes terapéuticos.","VHL-Pflicht erfunden":"Requisito VHL inventado","Bevacizumab wird von einem RCC-artigen VHL/HIF-Panel abhängig gemacht.":"Bevacizumab se hace depender de un panel VHL/HIF tipo RCC.","Entitäts-Copyover.":"Copyover de entidad.","Weitere CRC-Targets offen":"Otros targets de CRC aún abiertos","Entitätsspezifische Standarddiagnostik ergänzen.":"Añadir diagnóstico estándar específico de la entidad.","Zusatztests beantworten echte Fragen.":"Las pruebas adicionales responden preguntas reales.","Nur Anti-VEGF-Mechanismus gefragt":"Solo se pregunta por el mecanismo anti-VEGF","Interpretation statt Wet-lab-Overtesting.":"Interpretación en lugar de sobrepruebas wet-lab.","Material und TAT werden geschont.":"Se preservan material y TAT.","Bevacizumab neutralisiert VEGF-A und adressiert Tumorangiogenese.":"Bevacizumab neutraliza VEGF-A y actúa sobre la angiogénesis tumoral.","Für mCRC ist kein positiver VHL/HIF-/Tumor-VEGF-Test als Routinevoraussetzung etabliert.":"No existe una prueba positiva VHL/HIF/VEGF tumoral establecida como requisito rutinario en mCRC.","RAS-Status entscheidet eine andere Therapieachse.":"El estado RAS determina un eje terapéutico distinto.","Mechanistische Plausibilität ist nicht gleich Companion Diagnostic.":"La plausibilidad mecanística no equivale a un companion diagnostic.","Gute Präzisionsdiagnostik beinhaltet bewusstes Weglassen unnötiger Tests.":"Un buen diagnóstico de precisión incluye omitir deliberadamente pruebas innecesarias.","Die KRAS-Mutation erklärt den fehlenden anti-EGFR-Kontext, nicht eine Anti-VEGF-Kontraindikation. Bevacizumab wirkt über VEGF-A; ein positiver VHL/HIF-/VEGF-Tumortest ist dafür im mCRC nicht erforderlich. VHL/HIF-Testung wäre Low-value.":"La mutación KRAS explica la ausencia de contexto anti-EGFR, no una contraindicación anti-VEGF. Bevacizumab actúa a través de VEGF-A; no se requiere una prueba tumoral positiva VHL/HIF/VEGF en mCRC. El estudio VHL/HIF sería de bajo valor.","Mechanismus vs Biomarker":"Mecanismo vs biomarcador","RAS-Achse getrennt":"Eje RAS separado","kein VHL-Copyover":"Sin copyover VHL","Testökonomie":"Economía de pruebas","Warum führen Signalwegdiagramme manchmal zu Overdiagnostics?":"¿Por qué los diagramas de pathways conducen a veces a sobrediagnóstico?","Was unterscheidet einen Wirkmechanismus von einem Companion Diagnostic?":"¿Qué distingue un mecanismo de acción de un companion diagnostic?","Wann ist ein nicht bestellter Test die beste Entscheidung?":"¿Cuándo no pedir una prueba es la mejor decisión?","VHL/HIF wird bewusst nicht getestet":"VHL/HIF no se analiza deliberadamente","Mechanismus ≠ Companion Diagnostic":"Mecanismo ≠ companion diagnostic","CRC-Profil → Therapieachse → VEGF-Rationale → kein Zusatztest":"Perfil CRC → eje terapéutico → justificación VEGF → sin prueba adicional","Klarzelliges RCC: VHL/HIF/VEGF erklärt die Biologie – wählt aber nicht allein die Therapie":"RCC de células claras: VHL/HIF/VEGF explica la biología, pero no selecciona por sí solo el tratamiento","Klarzelliges RCC: VHL/HIF/VEGF-Ach…":"RCC de células claras: eje VHL/HIF/VEGF…","Uroonkologie / Molekulares Tumorboard":"Oncología urológica / Molecular Tumor Board","59-jähriger Patient mit metastasiertem klarzelligem Nierenzellkarzinom. Ein Tumorpanel weist eine inaktivierende VHL-Alteration nach.":"Varón de 59 años con carcinoma renal de células claras metastásico. Un panel tumoral detecta una alteración inactivante de VHL.","Wie erklärt die VHL/HIF/VEGF-Achse die ausgeprägte Vaskularisierung und die Plausibilität von VEGFR-TKI/IO-Kombinationen – und wie weit darf man den VHL-Befund therapeutisch individualisieren?":"¿Cómo explica el eje VHL/HIF/VEGF la marcada vascularización y la plausibilidad de combinaciones VEGFR-TKI/IO, y hasta qué punto puede utilizarse el hallazgo de VHL para individualizar el tratamiento?","Erstlinienstrategie soll im interdisziplinären Board festgelegt werden.":"La estrategia de primera línea debe definirse en el board interdisciplinario.","Krankheit":"Enfermedad","Nephrektomie vor 18 Monaten; nun pulmonale und ossäre Metastasen.":"Nefrectomía hace 18 meses; ahora metástasis pulmonares y óseas.","Klarzelliges RCC, typische feine Gefäßarchitektur.":"RCC de células claras, arquitectura vascular fina típica.","VHL Loss-of-function im Tumor.":"VHL loss-of-function en el tumor.","Ein häufiger biologischer Driver wird als spezifischer prädiktiver Marker für genau eine zugelassene Kombination missverstanden.":"Un driver biológico frecuente se interpreta erróneamente como marcador predictivo específico para exactamente una combinación aprobada.","Alveolär/nestartig aufgebauter klarzelliger Tumor mit dichtem kapillärem Netzwerk.":"Tumor de células claras con patrón alveolar/anidado y densa red capilar.","Biologie":"Biología","VHL-Verlust stabilisiert HIF-Signale und fördert u. a. VEGF-abhängige Angiogenese.":"La pérdida de VHL estabiliza la señalización HIF y favorece, entre otros efectos, la angiogénesis dependiente de VEGF.","Moderne Erstlinienoptionen kombinieren häufig Immuncheckpoint- und VEGFR-gerichtete Strategien.":"Las opciones modernas de primera línea combinan con frecuencia estrategias de checkpoint inmunitario y dirigidas contra VEGFR.","Biologische Plausibilität versus echte prädiktive Individualisierung.":"Plausibilidad biológica frente a verdadera individualización predictiva.","Nephrektomieblock und aktuelle Metastasenbiopsie verfügbar.":"Disponibles el bloque de nefrectomía y la biopsia actual de metástasis.","Testnutzen":"Utilidad de las pruebas","VHL/HIF-Kontext kann die Biologie illustrieren, ist aber für Standard-IO/TKI-Auswahl nicht zwingend als positiver Companion Diagnostic erforderlich.":"El contexto VHL/HIF puede ilustrar la biología, pero no es obligatorio un companion diagnostic positivo para la selección estándar IO/TKI.","Mehr Molekulardaten dürfen keine Scheingenauigkeit bei der Auswahl zwischen mehreren klinisch etablierten Regimen erzeugen.":"Más datos moleculares no deben generar una falsa precisión al elegir entre varios regímenes clínicamente establecidos.","VHL/HIF/VEGF-Biologie integrieren":"Integrar la biología VHL/HIF/VEGF","VHL/HIF":"VHL/HIF","Inaktivierende VHL-Alteration; Befund passt zur kanonischen ccRCC-Biologie mit HIF-Stabilisierung und proangiogenem Programm.":"Alteración inactivante de VHL; el hallazgo encaja con la biología canónica de ccRCC con estabilización de HIF y programa proangiogénico.","Die ausgeprägte Angiogenese erklärt die Wirksamkeitslogik VEGFR-gerichteter TKIs; die Kombination mit IO adressiert gleichzeitig Tumorimmunität und Gefäß-/TME-Biologie.":"La angiogénesis marcada explica la lógica de los TKI dirigidos a VEGFR; la combinación con IO aborda simultáneamente la inmunidad tumoral y la biología vascular/TME.","Klarzelliges RCC mit prominentem kapillärem Netzwerk.":"RCC de células claras con red capilar prominente.","Kernbotschaft":"Mensaje clave","Biologischer Driver ≠ alleiniger prädiktiver Regimenselektor.":"Driver biológico ≠ selector predictivo único del régimen.","Der VHL-Verlust liefert eine sehr plausible biologische Erklärung für HIF-Aktivierung und VEGF-dominierte Angiogenese des klarzelligen RCC. Daraus folgt die biologische Plausibilität VEGFR-gerichteter Therapie und kombinierter IO/VEGFR-Strategien. Der konkrete VHL-Tumorbefund ist jedoch kein alleiniger validierter Selektionsmarker, der eine bestimmte Erstlinienkombination gegenüber allen anderen festlegt.":"La pérdida de VHL ofrece una explicación biológica muy plausible de la activación de HIF y la angiogénesis dominada por VEGF en el RCC de células claras. Esto apoya la plausibilidad biológica del tratamiento dirigido a VEGFR y de las estrategias combinadas IO/VEGFR. Sin embargo, el hallazgo tumoral específico de VHL no es un marcador de selección único validado que determine una combinación de primera línea sobre todas las demás.","Teilbefund: VHL/HIF/VEGF erklärt die Erkrankungsbiologie, beantwortet aber die klinische Regimenwahl nicht ohne Gesamtpatientenkontext.":"Resultado parcial: VHL/HIF/VEGF explica la biología de la enfermedad, pero no resuelve la elección del régimen sin el contexto clínico global.","VHL-Verlust biologisch korrekt über HIF/VEGF erklären":"Explicar biológicamente la pérdida de VHL mediante HIF/VEGF","Rationale von VEGFR-TKI + IO mechanistisch erläutern":"Explicar mecanísticamente la justificación de VEGFR-TKI + IO","VHL nicht als alleinigen prädiktiven Regimenselektor verkaufen":"No presentar VHL como selector predictivo único del régimen","Risikogruppe, Komorbiditäten und klinische Faktoren in der Therapieentscheidung belassen":"Mantener grupo de riesgo, comorbilidades y factores clínicos en la decisión terapéutica","Falschaussage: VHL-Mutation bestimmt zwingend eine bestimmte IO/TKI-Kombination":"Afirmación falsa: la mutación VHL obliga a una combinación IO/TKI específica","Optimale Lösung: VHL/HIF/VEGF als Lehrbuchbeispiel einer biologisch sehr starken Achse nutzen, ohne daraus einen nicht validierten Präzisionsmarker für die konkrete Regimenwahl zu machen.":"Solución óptima: utilizar VHL/HIF/VEGF como ejemplo de libro de texto de un eje biológicamente muy potente sin convertirlo en un marcador de precisión no validado para seleccionar el régimen concreto.","ccRCC":"ccRCC","VHL":"VHL","HIF":"HIF","VEGFR-TKI":"VEGFR-TKI","VHL erklärt fast alles – aber nicht die konkrete Regimenwahl":"VHL explica casi todo, pero no la elección concreta del régimen","Uroonkologie / Molekularpathologie / MTB":"Oncología urológica / patología molecular / MTB","VHL-Verlust über HIF-Stabilisierung und VEGF-Angiogenese erklären.":"Explicar la pérdida de VHL mediante estabilización de HIF y angiogénesis VEGF.","Die starke Vaskularisierung des ccRCC biologisch mit VEGFR-TKI verknüpfen.":"Relacionar biológicamente la fuerte vascularización del ccRCC con VEGFR-TKI.","Komplementäre Rationale von IO + VEGFR-TKI verstehen.":"Comprender la justificación complementaria de IO + VEGFR-TKI.","VHL als häufigen biologischen Driver, aber nicht als alleinigen Regimenselektor einordnen.":"Considerar VHL como driver biológico frecuente, pero no como único selector del régimen.","Klinische Faktoren neben Tumorbiologie in der Therapiewahl belassen.":"Mantener los factores clínicos junto con la biología tumoral en la elección del tratamiento.","Das Panel zeigt eine klare VHL-Loss-of-function-Mutation. Der Befund ist biologisch wunderschön – so schön, dass man leicht zu viel daraus ableitet und glaubt, er müsse nun exakt eine bestimmte Kombination bestimmen.":"El panel muestra una clara mutación VHL loss-of-function. El hallazgo es biológicamente muy elegante, tanto que resulta fácil inferir demasiado y asumir que debe determinar exactamente una combinación.","59-jähriger Patient mit metastasiertem klarzelligem RCC und VHL-Loss-of-function. Ziel ist, VHL/HIF/VEGF als Lehrbuchachse zu verstehen und gleichzeitig die Grenze zur klinischen Prädiktion zu ziehen.":"Varón de 59 años con RCC de células claras metastásico y VHL loss-of-function. El objetivo es entender VHL/HIF/VEGF como eje de libro de texto y, al mismo tiempo, marcar el límite con la predicción clínica.","Kanonische Biologie":"Biología canónica","VHL-Verlust → HIF-Stabilisierung → proangiogenes Programm.":"Pérdida de VHL → estabilización de HIF → programa proangiogénico.","ccRCC ist ein Paradebeispiel für pathway-driven Tumorbiologie.":"ccRCC es un ejemplo paradigmático de biología tumoral impulsada por pathways.","Therapie-Rationale":"Justificación terapéutica","VEGFR-TKI adressieren die angiogene Achse; IO adressiert Tumorimmunität/TME.":"Los VEGFR-TKI actúan sobre el eje angiogénico; IO actúa sobre la inmunidad tumoral/TME.","Kombinationen können biologisch komplementär sein.":"Las combinaciones pueden ser biológicamente complementarias.","Grenze":"Límite","VHL ist häufig, aber kein alleiniger Selektor zwischen allen Standardregimen.":"VHL es frecuente, pero no es el único selector entre todos los regímenes estándar.","Biologische Erklärung ist stärker als prädiktive Spezifität.":"La explicación biológica es más fuerte que la especificidad predictiva.","typisches klarzelliges RCC mit feinem Kapillarnetz":"RCC de células claras típico con fina red capilar","Tumor-NGS":"NGS tumoral","VHL Loss-of-function":"VHL loss-of-function","metastasiert, Erstlinie offen":"Metastásico, primera línea abierta","Kein zusätzlicher Test muss eine bestimmte IO/TKI-Kombination 'freigeben'.":"Ninguna prueba adicional tiene que «autorizar» una combinación IO/TKI concreta.","VHL-Tumorbefund ist nicht automatisch hereditär; Keimbahnfrage nur bei passendem klinischem Kontext.":"Un hallazgo tumoral de VHL no es automáticamente hereditario; la cuestión germinal solo surge con un contexto clínico apropiado.","Klinische Risikogruppe, Komorbiditäten und Nebenwirkungsprofile bleiben entscheidend.":"El grupo de riesgo clínico, las comorbilidades y los perfiles de toxicidad siguen siendo decisivos.","Welche Kette beschreibt die ccRCC-Biologie am besten?":"¿Qué cadena describe mejor la biología del ccRCC?","VHL-Verlust → HIF-Stabilisierung → VEGF/proangiogene Programme.":"Pérdida de VHL → estabilización de HIF → programas VEGF/proangiogénicos.","KRAS → EGFR → MSI.":"KRAS → EGFR → MSI.","BRCA → HRD → VEGF.":"BRCA → HRD → VEGF.","MMR-Verlust → VHL.":"Pérdida MMR → VHL.","Die VHL/HIF/VEGF-Achse ist kanonisch.":"El eje VHL/HIF/VEGF es canónico.","Warum ist IO + VEGFR-TKI biologisch plausibel?":"¿Por qué IO + VEGFR-TKI es biológicamente plausible?","Gefäß-/TME- und Immunachsen werden komplementär adressiert.":"Los ejes vascular/TME e inmunitario se abordan de forma complementaria.","Weil nur VHL-mutierte Tumoren IO vertragen.":"Porque solo los tumores mutados en VHL toleran IO.","Beide Medikamente blockieren exakt dasselbe Molekül.":"Ambos fármacos bloquean exactamente la misma molécula.","Weil PD-L1 immer hoch sein muss.":"Porque PD-L1 siempre debe ser alto.","Die Kombination adressiert unterschiedliche, interagierende Ebenen.":"La combinación actúa sobre niveles distintos e interactuantes.","Was darf aus VHL Loss-of-function NICHT abgeleitet werden?":"¿Qué NO debe inferirse de VHL loss-of-function?","Dass genau eine bestimmte Erstlinienkombination zwingend die einzig richtige ist.":"Que una única combinación específica de primera línea sea necesariamente la única opción correcta.","Dass HIF/VEGF-Biologie plausibel ist.":"Que la biología HIF/VEGF es plausible.","Dass angiogene Programme typisch sein können.":"Que los programas angiogénicos pueden ser típicos.","Dass der Befund zur ccRCC-Biologie passt.":"Que el hallazgo encaja con la biología del ccRCC.","VHL ist biologisch stark, aber nicht so prädiktiv spezifisch.":"VHL es biológicamente potente, pero no tan específico desde el punto de vista predictivo.","Wann wird aus Tumor-VHL eine Keimbahnfrage?":"¿Cuándo un hallazgo tumoral de VHL se convierte en una cuestión germinal?","Bei passendem Alter, multifokaler/bilateraler Erkrankung oder VHL-Syndrom-typischem klinischem Kontext – nicht automatisch bei jedem somatischen Tumorbefund.":"Con una edad adecuada, enfermedad multifocal/bilateral o contexto clínico típico del síndrome VHL, no automáticamente ante cualquier hallazgo tumoral somático.","Immer.":"Siempre.","Nur wenn TKI versagt.":"Solo si falla el TKI.","Tumor- und Keimbahnebene müssen getrennt werden.":"Deben separarse los niveles tumoral y germinal.","Erklären Sie im MTB VHL/HIF/VEGF und die Kombination von antiangiogener und immunologischer Therapie, ohne den VHL-Befund zu einem nicht validierten Ein-Patient-ein-Regime-Marker zu machen.":"Explique en el MTB VHL/HIF/VEGF y la combinación de terapia antiangiogénica e inmunológica sin convertir el hallazgo de VHL en un marcador no validado de «un paciente–un régimen». ","VHL-Verlust biologisch erklären.":"Explicar biológicamente la pérdida de VHL.","HIF/VEGF-Angiogenese ableiten.":"Derivar la angiogénesis HIF/VEGF.","VEGFR-TKI-Rationale erläutern.":"Explicar la justificación de VEGFR-TKI.","IO-Komponente als komplementäre Immun-/TME-Achse erklären.":"Explicar el componente IO como eje inmunitario/TME complementario.","VHL nicht als alleinigen Regimenselektor überinterpretieren.":"No sobreinterpretar VHL como único selector del régimen.","Keimbahnfrage nur bei klinischem Anlass öffnen.":"Abrir la cuestión germinal solo si existe indicación clínica.","Auf VHL-Testung verzichten, wenn Histologie und klinische Therapiefrage bereits klar sind; der Fall nutzt sie als didaktischen Biologieanker.":"Omitir la prueba de VHL cuando la histología y la cuestión terapéutica clínica ya están claras; el caso la utiliza como ancla didáctica de biología.","Breiteres Panel nur bei zusätzlicher Target-/Studienfrage.":"Utilizar un panel más amplio solo si existe una cuestión adicional de target/estudio.","VHL = bestimmtes Regime":"VHL = régimen específico","Biologischer Driver besitzt nicht diese prädiktive Spezifität.":"El driver biológico no posee esa especificidad predictiva.","Tumor-VHL = VHL-Syndrom":"VHL tumoral = síndrome VHL","Somatisch und Keimbahn werden verwechselt.":"Se confunden los niveles somático y germinal.","VEGF-TKI und IO tun dasselbe":"VEGF-TKI e IO hacen lo mismo","Komplementäre Mechanismen werden verkannt.":"Se pasan por alto mecanismos complementarios.","Der stärkste biologische Befund ist nicht der stärkste Selektionsmarker":"El hallazgo biológico más fuerte no es el marcador de selección más fuerte","VHL Loss-of-function passt perfekt zum Tumor und erklärt die Angiogenese. Trotzdem wählt er nicht allein zwischen den klinisch etablierten Erstlinienoptionen. Der Fall kippt von 'Pathway gefunden' zu 'Evidenzgrad verstanden'.":"VHL loss-of-function encaja perfectamente con el tumor y explica la angiogénesis. Aun así, por sí solo no elige entre las opciones de primera línea clínicamente establecidas. El caso pasa de «pathway encontrado» a «nivel de evidencia comprendido». ","Präzisionsonkologie braucht Grenzen selbst bei sehr überzeugender Biologie.":"La oncología de precisión necesita límites incluso con una biología muy convincente.","Biologie stark, Prädiktion begrenzt":"Biología fuerte, predicción limitada","VHL/HIF/VEGF korrekt erklärt; IO/TKI plausibel; konkrete Regimenwahl klinisch, nicht allein VHL-basiert.":"VHL/HIF/VEGF correctamente explicado; IO/TKI plausible; la elección concreta del régimen es clínica, no basada solo en VHL.","Sehr gute Hierarchie.":"Muy buena jerarquía.","Achse verstanden, Regime überpräzisiert":"Eje comprendido, régimen sobreprecisado","VHL korrekt, aber eine Kombination wird molekular zwingend gemacht.":"VHL es correcto, pero una combinación se convierte en molecularmente obligatoria.","Biologie überinterpretiert.":"Biología sobreinterpretada.","VHL ignoriert oder germline gesetzt":"VHL ignorado o asignado a germinal","Entweder zentrale Biologie verpasst oder somatischen Befund automatisch hereditär erklärt.":"O se pierde la biología central o el hallazgo somático se declara automáticamente hereditario.","Integration misslungen.":"Integración fallida.","VHL-Syndrom-verdächtige Klinik":"Clínica sospechosa de síndrome VHL","Humangenetische Abklärung separat initiieren.":"Iniciar evaluación genética por separado.","Hereditäre Ebene korrekt adressiert.":"Dimensión hereditaria correctamente abordada.","Standard metastasiertes ccRCC":"ccRCC metastásico estándar","Regimenwahl anhand aktueller klinischer Kriterien/Guidelines.":"Selección del régimen según criterios clínicos/guidelines actuales.","Molekularbiologie informiert, ersetzt aber nicht die klinische Auswahl.":"La biología molecular informa, pero no sustituye la selección clínica.","VHL/HIF/VEGF ist eine kanonische ccRCC-Achse.":"VHL/HIF/VEGF es un eje canónico del ccRCC.","VEGFR-TKI haben eine starke biologische Rationale im hochangiogenen ccRCC.":"Los VEGFR-TKI tienen una sólida justificación biológica en el ccRCC altamente angiogénico.","IO/VEGFR-Kombinationen adressieren komplementäre Ebenen.":"Las combinaciones IO/VEGFR actúan sobre niveles complementarios.","VHL ist kein alleiniger validierter Selektor für ein bestimmtes Standardregime.":"VHL no es un selector único validado para un régimen estándar concreto.","Somatischer VHL-Befund ist nicht automatisch VHL-Syndrom.":"Un hallazgo somático de VHL no equivale automáticamente a síndrome VHL.","VHL Loss-of-function erklärt HIF-Stabilisierung und VEGF-dominierte Angiogenese des ccRCC. Diese Biologie macht VEGFR-gerichtete und kombinierte IO/VEGFR-Strategien plausibel, bestimmt aber nicht allein das konkrete Regime. Klinischer Gesamtkontext bleibt entscheidend.":"VHL loss-of-function explica la estabilización de HIF y la angiogénesis dominada por VEGF en ccRCC. Esta biología hace plausibles las estrategias dirigidas a VEGFR y combinadas IO/VEGFR, pero no determina por sí sola el régimen concreto. El contexto clínico global sigue siendo decisivo.","VHL/HIF/VEGF":"VHL/HIF/VEGF","Kombinationsrationale":"Justificación de la combinación","prädiktive Grenze":"Límite predictivo","somatisch vs germline":"Somático vs germinal","Warum sind manche Driver diagnostisch stark, aber prädiktiv schwach?":"¿Por qué algunos drivers son fuertes diagnósticamente pero débiles predictivamente?","Welche TME-Effekte können VEGF-Inhibition immunologisch haben?":"¿Qué efectos inmunológicos sobre el TME puede tener la inhibición de VEGF?","Wann wird eine Tumor-VHL-Variante humangenetisch relevant?":"¿Cuándo una variante tumoral de VHL adquiere relevancia para genética clínica?","VHL erklärt Biologie, aber nicht allein das Regime":"VHL explica la biología, pero no el régimen por sí solo","Pathway-Stärke ≠ Selektionsspezifität":"Potencia del pathway ≠ especificidad de selección","VHL → HIF/VEGF → TKI/IO-Rationale → klinische Regimenwahl":"VHL → HIF/VEGF → justificación TKI/IO → elección clínica del régimen","Rezidiv-Glioblastom unter Bevacizumab: Wenn das MRT besser aussieht als der Tumor":"Glioblastoma recurrente con bevacizumab: cuando la RM parece mejor que el tumor","Glioblastom mit Gefäßproliferation…":"Glioblastoma con proliferación vascular…","Neuroonkologie / Neuro-Radiologie / MTB":"Neurooncología / Neurorradiología / MTB","62-jähriger Patient mit rezidiviertem IDH-Wildtyp-Glioblastom, ausgeprägtem perifokalem Ödem und steroidabhängigen neurologischen Symptomen. Bevacizumab wird zur Krankheits- und Symptomkontrolle diskutiert.":"Varón de 62 años con glioblastoma IDH-wild-type recurrente, marcado edema perifocal y síntomas neurológicos dependientes de esteroides. Se discute bevacizumab para control de la enfermedad y de los síntomas.","Was kann Anti-VEGF kurzfristig bewirken – und warum darf eine dramatische Abnahme der Kontrastmittelaufnahme nicht automatisch als proportionale Tumorzellreduktion gelesen werden?":"¿Qué puede lograr anti-VEGF a corto plazo y por qué una disminución drástica del realce con contraste no debe interpretarse automáticamente como una reducción proporcional de células tumorales?","Hoher Symptomdruck durch Ödem.":"Alta carga sintomática por edema.","Operation, Radiochemotherapie und Temozolomid; jetzt erstes relevantes Rezidiv.":"Cirugía, radioquimioterapia y temozolomida; ahora primera recurrencia clínicamente relevante.","Hemiparese und Kopfschmerzen, Dexamethasonbedarf steigend.":"Hemiparesia y cefaleas, necesidad creciente de dexametasona.","MRT":"RM","Stark kontrastmittelaufnehmendes Rezidiv mit ausgeprägtem vasogenem Ödem.":"Recurrencia con intenso realce por contraste y marcado edema vasogénico.","Radiologische Kontrastmittelreduktion nach Anti-VEGF wird mit echter Zytoreduktion gleichgesetzt.":"La reducción radiológica del realce tras anti-VEGF se equipara a una verdadera citorreducción.","Glioblastomtypische Nekrosen und mikrovaskuläre Proliferation.":"Necrosis y proliferación microvascular típicas de glioblastoma.","Hypoxie und proangiogene Signale prägen den Tumor.":"La hipoxia y las señales proangiogénicas caracterizan el tumor.","Anti-VEGF-Effekt":"Efecto anti-VEGF","Gefäßpermeabilität und Ödem können rasch abnehmen.":"La permeabilidad vascular y el edema pueden disminuir rápidamente.","Wie wird die Bildgebung nach Therapiebeginn korrekt interpretiert?":"¿Cómo debe interpretarse correctamente la imagen tras iniciar el tratamiento?","Archiviertes Resektat ausreichend; keine neue Biopsie allein zur 'VEGF-Testung' erforderlich.":"La pieza de resección archivada es adecuada; no se requiere una nueva biopsia solo para «estudio de VEGF». ","Testfalle":"Trampa de pruebas","Ein RCC-spezifischer VHL/HIF-Test hat hier keinen sinnvollen Selektionsnutzen.":"Una prueba VHL/HIF específica de RCC no tiene aquí utilidad relevante de selección.","Radiologie":"Radiología","Kontrastmittelaufnahme ist stark von Blut-Hirn-Schranken-Permeabilität abhängig.":"El realce con contraste depende en gran medida de la permeabilidad de la barrera hematoencefálica.","Symptomverbesserung kann real sein, auch wenn der antitumorale Effekt begrenzt bleibt.":"La mejoría sintomática puede ser real aunque el efecto antitumoral siga siendo limitado.","Anti-VEGF-/Angiogenese-Kontext":"Contexto anti-VEGF/angiogénesis","GBM zeigt ausgeprägte Gefäßproliferation; Anti-VEGF kann Gefäßpermeabilität und vasogenes Ödem rasch reduzieren.":"El GBM presenta marcada proliferación vascular; anti-VEGF puede reducir rápidamente la permeabilidad vascular y el edema vasogénico.","VHL/HIF-Panel":"Panel VHL/HIF","RCC-spezifische VHL/HIF-Testung liefert für diesen GBM-Fall keinen validierten Therapie-Selektionsnutzen und wäre ein entitätsfremder Low-value-Test.":"El estudio VHL/HIF específico de RCC no aporta beneficio validado para seleccionar tratamiento en este caso de GBM y sería una prueba de bajo valor ajena a la entidad.","Zusätzliche genomische Information ändert die zentrale Anti-VEGF-/Imaging-Lernfrage nicht.":"La información genómica adicional no cambia la cuestión central de aprendizaje anti-VEGF/imagen.","MRT vor Therapie":"RM antes del tratamiento","Starke Kontrastmittelaufnahme und ausgeprägtes vasogenes Ödem.":"Marcado realce con contraste y edema vasogénico pronunciado.","Steroidabhängige fokal-neurologische Symptome.":"Síntomas neurológicos focales dependientes de esteroides.","Anti-VEGF kann beim rezidivierten Glioblastom rasch Gefäßpermeabilität und Ödem reduzieren und damit Symptome sowie Kontrastmittelaufnahme deutlich verbessern. Diese radiologische 'Pseudoresponse' darf jedoch nicht mit einer proportionalen Eliminierung infiltrierender Tumorzellen gleichgesetzt werden. Verlaufskontrolle muss deshalb neben Kontrastmittelaufnahme auch FLAIR/non-enhancing disease, Klinik und Steroidbedarf integrieren.":"Anti-VEGF puede reducir rápidamente la permeabilidad vascular y el edema en el glioblastoma recurrente, mejorando de forma marcada los síntomas y el realce. Sin embargo, esta «pseudoresponse» radiológica no debe equipararse con una eliminación proporcional de células tumorales infiltrativas. El seguimiento debe integrar realce, FLAIR/non-enhancing disease, clínica y necesidad de esteroides.","Teilbefund: Die Gefäßreaktion kann eindrucksvoll sein, sagt aber allein wenig über die gesamte infiltrative Tumorlast aus.":"Resultado parcial: la respuesta vascular puede ser impresionante, pero por sí sola dice poco sobre la carga tumoral infiltrativa total.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem erklären":"Explicar el efecto anti-VEGF sobre permeabilidad vascular/edema","Pseudoresponse von echter proportionaler Zytoreduktion trennen":"Separar pseudoresponse de verdadera citorreducción proporcional","FLAIR/non-enhancing disease und Klinik mitbewerten":"Valorar también FLAIR/non-enhancing disease y la clínica","RCC-VHL/HIF-Testung nicht importieren":"No importar pruebas VHL/HIF de RCC","Falschaussage: 80 % weniger Enhancement = 80 % weniger Tumorzellen":"Afirmación falsa: 80 % menos realce = 80 % menos células tumorales","Optimale Lösung: Bevacizumab kann klinisch sehr wertvolle Ödem-/Permeabilitätseffekte erzeugen; gerade deshalb muss die beeindruckende MRT-Reaktion als mögliche Pseudoresponse erkannt und multimodal beurteilt werden.":"Solución óptima: bevacizumab puede producir efectos clínicamente valiosos sobre edema/permeabilidad; precisamente por ello, la impresionante respuesta en RM debe reconocerse como posible pseudoresponse y evaluarse de forma multimodal.","Glioblastom":"Glioblastoma","Pseudoresponse":"Pseudoresponse","Ödem":"Edema","Das MRT schrumpft schneller als der Tumor":"La RM se reduce más rápido que el tumor","Neuroonkologie / Neuroradiologie / MTB":"Neurooncología / Neurorradiología / MTB","VEGF-bedingte Gefäßpermeabilität und Ödem beim GBM erklären.":"Explicar la permeabilidad vascular y el edema relacionados con VEGF en GBM.","Anti-VEGF-bedingte Pseudoresponse erkennen.":"Reconocer la pseudoresponse inducida por anti-VEGF.","Kontrastmittelreduktion nicht direkt in Tumorzellreduktion übersetzen.":"No traducir directamente la reducción del realce en menor número de células tumorales.","FLAIR/non-enhancing disease, Klinik und Steroidbedarf in die Verlaufskontrolle integrieren.":"Integrar FLAIR/non-enhancing disease, clínica y necesidad de esteroides en el seguimiento.","Entitätsfremde VHL/HIF-Testung vermeiden.":"Evitar pruebas VHL/HIF ajenas a la entidad.","Zwei Wochen nach Bevacizumab ist die Kontrastmittelaufnahme dramatisch kleiner, der Patient braucht weniger Steroid und fühlt sich besser. Auf den ersten Blick ein spektakuläres Tumoransprechen – bis man versteht, was Anti-VEGF mit der Blut-Hirn-Schranke macht.":"Dos semanas después de bevacizumab, el realce es drásticamente menor, el paciente necesita menos esteroides y se siente mejor. A primera vista, una respuesta tumoral espectacular, hasta comprender qué hace anti-VEGF sobre la barrera hematoencefálica.","62-jähriger Patient mit symptomatischem Rezidiv eines IDH-Wildtyp-Glioblastoms. Bevacizumab wird wegen Ödem und Progress eingesetzt. Der Fall lehrt, echte klinische Verbesserung und radiologische Pseudoresponse gleichzeitig richtig zu würdigen.":"Varón de 62 años con recurrencia sintomática de glioblastoma IDH-wild-type. Se utiliza bevacizumab por edema y progresión. El caso enseña a valorar correctamente tanto la mejoría clínica real como la pseudoresponse radiológica.","Gefäßpermeabilität":"Permeabilidad vascular","GBM-Gefäße sind abnormal und leaky.":"Los vasos del GBM son anormales y permeables.","Enhancement ist nicht nur Tumormasse, sondern auch Blut-Hirn-Schranken-Phänomen.":"El realce refleja no solo masa tumoral, sino también un fenómeno de la barrera hematoencefálica.","Anti-VEGF kann wirklich helfen":"Anti-VEGF puede ayudar de verdad","Ödem und Steroidbedarf sinken.":"Disminuyen el edema y la necesidad de esteroides.","Pseudoresponse bedeutet nicht 'kein Nutzen'.":"Pseudoresponse no significa «sin beneficio». ","Aber Imaging kann täuschen":"Pero la imagen puede engañar","Non-enhancing/infiltrative disease kann fortbestehen.":"La enfermedad no realzante/infiltrativa puede persistir.","Response muss multimodal bewertet werden.":"La respuesta debe evaluarse de forma multimodal.","Vor Therapie":"Antes del tratamiento","starkes Enhancement + massives vasogenes Ödem":"Realce intenso + edema vasogénico masivo","Hemiparese, Kopfschmerz, Steroidbedarf":"Hemiparesia, cefalea, necesidad de esteroides","Nekrose + mikrovaskuläre Proliferation":"Necrosis + proliferación microvascular","Keine neue Biopsie nur zur VEGF-Testung nötig.":"No se requiere una nueva biopsia solo para estudiar VEGF.","VHL/HIF-Panel ist hier ein bewusster RCC-Copyover und nicht erforderlich.":"El panel VHL/HIF es aquí un copyover deliberado de RCC y no es necesario.","Radiologische Verlaufskriterien müssen Anti-VEGF-Effekte berücksichtigen.":"Los criterios radiológicos de respuesta deben tener en cuenta los efectos anti-VEGF.","Was erklärt die schnelle Abnahme des Enhancements am besten?":"¿Qué explica mejor la rápida disminución del realce?","Reduzierte Gefäßpermeabilität/Normalisierung und weniger Ödem können einen großen Anteil beitragen.":"La reducción de la permeabilidad vascular/normalización y el menor edema pueden contribuir de forma importante.","Es beweist proportional dieselbe Abnahme der Tumorzellzahl.":"Demuestra una disminución proporcional del número de células tumorales.","IDH-Mutation entsteht unter Therapie.":"Apare una mutación IDH durante el tratamiento.","Es ist immer Strahlennekrose.":"Siempre es necrosis por radiación.","Anti-VEGF beeinflusst die Blut-Hirn-Schranke stark.":"Anti-VEGF influye fuertemente en la barrera hematoencefálica.","Was bedeutet 'Pseudoresponse'?":"¿Qué significa «pseudoresponse»?","Radiologisch eindrucksvolle Abnahme des Enhancements kann den antitumoralen Zell-Effekt überschätzen.":"Una disminución radiológicamente llamativa del realce puede sobreestimar el efecto antitumoral celular.","Jede klinische Verbesserung ist eingebildet.":"Toda mejoría clínica es imaginaria.","Es bedeutet zwingend Progress.":"Significa necesariamente progresión.","MRT ist technisch unbrauchbar.":"La RM es técnicamente inutilizable.","Der Nutzen kann real sein, aber Enhancement überschätzt den Zell-Effekt.":"El beneficio puede ser real, pero el realce sobreestima el efecto celular.","Was muss zusätzlich betrachtet werden?":"¿Qué más debe considerarse?","FLAIR/non-enhancing disease, Klinik, Steroidbedarf und serieller Verlauf.":"FLAIR/non-enhancing disease, clínica, necesidad de esteroides y evolución seriada.","Nur kontrastmittelaufnehmendes Volumen.":"Solo el volumen con realce.","VHL-Mutationsstatus.":"Estado mutacional de VHL.","PD-L1-IHC.":"IHC PD-L1.","Anti-VEGF erfordert breitere Responsebewertung.":"Anti-VEGF requiere una evaluación más amplia de la respuesta.","Warum ist VHL/HIF-Panel hier falsch?":"¿Por qué es incorrecto el panel VHL/HIF aquí?","Es importiert einen RCC-spezifischen Test ohne validierten Selektionsnutzen in den GBM-Fall.":"Importa una prueba específica de RCC al caso de GBM sin utilidad validada de selección.","GBM hat keine DNA.":"GBM no contiene ADN.","VEGF ist im GBM irrelevant.":"VEGF es irrelevante en GBM.","Nur wegen TAT.":"Solo por TAT.","Angiogenese ist gemeinsam, Testalgorithmen sind entitätsspezifisch.":"La angiogénesis es compartida, pero los algoritmos de pruebas son específicos de la entidad.","Bewerten Sie die frühe MRT- und klinische Veränderung nach Bevacizumab und formulieren Sie, warum eine starke Kontrastmittelreduktion nicht automatisch eine gleich starke Zytoreduktion bedeutet.":"Valore los cambios precoces en RM y clínica tras bevacizumab y explique por qué una gran reducción del realce no implica automáticamente una citorreducción igual de intensa.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem benennen.":"Identificar el efecto anti-VEGF sobre permeabilidad vascular/edema.","Klinische Symptomverbesserung anerkennen.":"Reconocer la mejoría clínica sintomática.","Pseudoresponse erklären.":"Explicar pseudoresponse.","FLAIR/non-enhancing disease und seriellen Verlauf integrieren.":"Integrar FLAIR/non-enhancing disease y evolución seriada.","VHL/HIF-Testung vermeiden.":"Evitar pruebas VHL/HIF.","Wenn Bildgebung und Klinik diskordant bleiben, neuroradiologische Spezialverfahren/Verlauf nutzen.":"Si imagen y clínica siguen siendo discordantes, utilizar técnicas neurorradiológicas especializadas/seguimiento.","Bevacizumab primär symptomatisch/krankheitskontrollierend diskutieren, ohne radiologische Überversprechen.":"Plantear bevacizumab principalmente para control sintomático/de enfermedad, sin prometer en exceso la respuesta radiológica.","Enhancement = Tumorzellzahl":"Realce = número de células tumorales","BBB-Permeabilität beeinflusst Enhancement stark.":"La permeabilidad de la BBB influye fuertemente en el realce.","Pseudoresponse = kein Nutzen":"Pseudoresponse = sin beneficio","Ödem- und Steroidreduktion können klinisch sehr relevant sein.":"La reducción del edema y de la necesidad de esteroides puede ser clínicamente muy relevante.","VHL testen":"Analizar VHL","RCC-Copyover ohne Selektionsnutzen.":"Copyover de RCC sin utilidad de selección.","80 % weniger Enhancement, aber nicht 80 % weniger Tumor":"80 % menos realce, pero no 80 % menos tumor","Der Patient verbessert sich und das MRT sieht spektakulär aus. FLAIR zeigt jedoch weiter infiltrative Erkrankung. Der Twist ist doppelt: Der Effekt ist klinisch real und radiologisch zugleich potenziell irreführend.":"El paciente mejora y la RM parece espectacular. Sin embargo, FLAIR sigue mostrando enfermedad infiltrativa. El giro es doble: el efecto es clínicamente real y, al mismo tiempo, radiológicamente potencialmente engañoso.","Er verhindert sowohl Über- als auch Unterbewertung antiangiogener Therapie.":"Evita tanto la sobrevaloración como la infravaloración de la terapia antiangiogénica.","Pseudoresponse richtig gelesen":"Pseudoresponse correctamente interpretada","Ödem/Enhancement deutlich geringer, Klinik besser; infiltrative FLAIR-Komponente bleibt → Response nicht als proportionale Zytoreduktion überinterpretieren.":"Edema/realce claramente reducidos, clínica mejor; persiste componente infiltrativo FLAIR → no sobreinterpretar la respuesta como citorreducción proporcional.","Neuroonkologische Response korrekt.":"Respuesta neurooncológica correctamente interpretada.","Pseudoresponse erkannt, Nutzen abgewertet":"Pseudoresponse reconocida, beneficio infravalorado","Imaging-Falle erkannt, aber reale Symptom-/Ödemkontrolle fälschlich als bedeutungslos bezeichnet.":"Se reconoce la trampa de imagen, pero se considera erróneamente irrelevante el verdadero control de síntomas/edema.","Zu einseitig.":"Demasiado unilateral.","MRT = Zellzählung":"RM = recuento celular","Kontrastmittelvolumen wird direkt als Tumormasse interpretiert.":"El volumen con realce se interpreta directamente como masa tumoral.","Zentralen Anti-VEGF-Effekt verpasst.":"Se pasa por alto el efecto central anti-VEGF.","Enhancement sinkt, FLAIR stabil/steigend":"Disminuye el realce, FLAIR estable/en aumento","Pseudoresponse/discordant response erwägen und seriell beurteilen.":"Considerar pseudoresponse/respuesta discordante y evaluar de forma seriada.","Keine falsche Vollremission.":"Sin falsa remisión completa.","Steroidbedarf sinkt":"Disminuye la necesidad de esteroides","Als echten klinischen Benefit dokumentieren.":"Documentar como beneficio clínico real.","Symptomkontrolle wird nicht kleingeredet.":"No se minimiza el control sintomático.","VEGF-Inhibition kann Gefäßpermeabilität und Ödem rasch reduzieren.":"La inhibición de VEGF puede reducir rápidamente la permeabilidad vascular y el edema.","Kontrastmittelaufnahme ist beim GBM kein reiner Tumorzellmarker.":"El realce con contraste en GBM no es un marcador puro de células tumorales.","Pseudoresponse kann gleichzeitig mit echter klinischer Besserung bestehen.":"Pseudoresponse puede coexistir con una mejoría clínica real.","FLAIR/non-enhancing disease und Klinik gehören in die Verlaufskontrolle.":"FLAIR/non-enhancing disease y la clínica deben formar parte del seguimiento.","Angiogenese-Biologie rechtfertigt nicht automatisch VHL/HIF-Tumortestung.":"La biología de la angiogénesis no justifica automáticamente pruebas tumorales VHL/HIF.","Nach Bevacizumab sinken Enhancement, Ödem und Steroidbedarf deutlich. Das ist klinisch relevant, kann aber den zytoreduktiven Effekt überschätzen. FLAIR/non-enhancing disease und Verlauf müssen integriert werden; ein RCC-artiges VHL/HIF-Panel hat keinen Selektionsnutzen.":"Tras bevacizumab disminuyen claramente el realce, el edema y la necesidad de esteroides. Esto es clínicamente relevante, pero puede sobreestimar el efecto citorreductor. Deben integrarse FLAIR/non-enhancing disease y la evolución; un panel VHL/HIF tipo RCC no tiene utilidad de selección.","Ödem vs Tumor":"Edema vs tumor","multimodale Bildgebung":"Imagen multimodal","kein RCC-Copyover":"Sin copyover RCC","Wie unterscheiden sich Pseudoprogression und Pseudoresponse?":"¿En qué se diferencian pseudoprogression y pseudoresponse?","Welche klinischen Parameter helfen bei anti-VEGF?":"¿Qué parámetros clínicos ayudan durante la terapia anti-VEGF?","Warum ist Enhancement biologisch kein einfacher Tumormasse-Readout?":"¿Por qué el realce no es biológicamente un simple readout de masa tumoral?","dramatische MRT-Besserung trotz persistierender FLAIR-Krankheit":"Mejoría drástica en RM pese a enfermedad FLAIR persistente","Anti-VEGF verändert Bildgebung und Klinik unterschiedlich":"Anti-VEGF modifica de forma distinta imagen y clínica","VEGF/Ödem → Bevacizumab → Enhancement fällt → multimodale Response":"VEGF/edema → bevacizumab → disminuye realce → evaluación multimodal de respuesta","PD-L1 und TMB sehen gut aus – aber die T-Zellen bleiben im Stroma":"PD-L1 y TMB parecen favorables, pero las células T permanecen en el estroma","Stromareicher Tumor mit immune-exc…":"Tumor rico en estroma con immune-exc…","68-jähriger Patient mit metastasiertem Urothelkarzinom. Vor Checkpoint-Therapie lagen PD-L1-Expression und eine relativ hohe Mutationslast vor; klinisch kam es dennoch zu frühem Progress.":"Varón de 68 años con carcinoma urotelial metastásico. Antes de la terapia checkpoint había expresión de PD-L1 y carga mutacional relativamente alta; aun así se produjo progresión clínica precoz.","Wie kann ein scheinbar immunogener Tumor trotzdem primär resistent sein – und was lehrt die räumliche Verteilung der Immunzellen?":"¿Cómo puede un tumor aparentemente inmunogénico ser aun así primariamente resistente y qué enseña la distribución espacial de las células inmunitarias?","Retrospektive Einordnung und Studienplanung für die nächste Linie.":"Interpretación retrospectiva y planificación de estudio para la siguiente línea.","PD-L1 hoch; TMB erhöht; kein MSI-H-Kontext.":"PD-L1 alto; TMB elevado; sin contexto MSI-H.","Checkpoint-Inhibition mit frühem radiologischem Progress.":"Inhibición checkpoint con progresión radiológica precoz.","Biopsie":"Biopsia","Progressionsbiopsie zeigt stark stromareichen Tumor.":"La biopsia de progresión muestra un tumor muy rico en estroma.","Biomarkerwerte werden ohne räumlichen Zellkontext als Garantie für Immunantwort interpretiert.":"Los valores de biomarcadores se interpretan como garantía de respuesta inmunitaria sin contexto celular espacial.","Invasive Tumornester in breiten fibrotischen Stromasepten.":"Nidos tumorales invasivos en amplios septos estromales fibrosos.","CD8":"CD8","Viele T-Zellen vorhanden, aber überwiegend im peritumoralen Stroma; Tumorzellnester selbst sind arm an CD8-Zellen.":"Hay muchas células T, pero predominantemente en el estroma peritumoral; los propios nidos tumorales contienen pocas células CD8.","CAF-Kontext":"Contexto CAF","FAP/αSMA-reiches aktiviertes Stroma.":"Estroma activado rico en FAP/αSMA.","Immune-excluded statt wirklich inflamed/hot.":"Immune-excluded más que verdaderamente inflamed/hot.","Progressionsbiopsie mit 45 % Tumoranteil.":"Biopsia de progresión con 45 % de contenido tumoral.","ausreichend für fokussierte TIL-/Stroma-IHC.":"Adecuada para IHC focalizada de TIL/estroma.","Evidenzgrenze":"Límite de evidencia","TME-IHC erklärt die Resistenzbiologie, ist aber kein routinemäßiger alleiniger Therapieausschluss- oder Auswahltest.":"La IHC del TME explica la biología de resistencia, pero no es una prueba rutinaria independiente de exclusión o selección terapéutica.","Räumliche Biologie nicht mit einem neuen Companion Diagnostic verwechseln.":"No confundir la biología espacial con un nuevo companion diagnostic.","Stroma-/Immune-exclusion-Kontext":"Contexto estroma/immune-exclusion","PD-L1 bleibt deutlich exprimiert; der Befund allein erklärt die fehlende klinische Antwort nicht.":"PD-L1 sigue claramente expresado; este hallazgo por sí solo no explica la falta de respuesta clínica.","TMB erhöht. Potenziell vorhandene Neoantigene garantieren dennoch keine effektive T-Zell-Interaktion mit den Tumorzellen.":"TMB elevado. Los neoantígenos potenciales no garantizan, sin embargo, una interacción eficaz de las células T con las células tumorales.","TIL-Verteilung":"Distribución de TIL","CD8-positive T-Zellen sind zahlreich, bleiben jedoch überwiegend stromal/peritumoral; intratumorale Penetration ist gering.":"Las células T CD8 positivas son numerosas, pero permanecen predominantemente estromales/peritumorales; la penetración intratumoral es baja.","Stroma":"Estroma","Breites FAP/αSMA-positives fibroblastenreiches Stroma stützt ein immune-excluded Muster. Der Befund ist mechanistisch plausibel, aber kein allein validierter Therapie-Selektionsassay.":"Un amplio estroma rico en fibroblastos FAP/αSMA positivos apoya un patrón immune-excluded. El hallazgo es mecanísticamente plausible, pero no es un assay validado independiente de selección terapéutica.","Klinischer Twist":"Giro clínico","Früher Progress trotz scheinbar günstiger Immunmarker.":"Progresión precoz pese a marcadores inmunitarios aparentemente favorables.","Stark stromareicher Tumor mit räumlicher Trennung von CD8-Zellen und Tumornestern.":"Tumor muy rico en estroma con separación espacial entre células CD8 y nidos tumorales.","PD-L1-Expression und erhöhte TMB können immunologische Potenziale anzeigen, garantieren aber keine effektive Antitumor-Immunität. Die Progressionsbiopsie zeigt ein klassisches immune-excluded Muster: T-Zellen sind vorhanden, werden jedoch durch das stromale Mikromilieu räumlich von Tumorzellen ferngehalten. Dieser Befund erklärt Resistenzbiologie, darf aber nicht als alleiniger validierter Companion Diagnostic für eine konkrete Folgetherapie überinterpretiert werden.":"La expresión de PD-L1 y un TMB elevado pueden indicar potencial inmunológico, pero no garantizan una inmunidad antitumoral eficaz. La biopsia de progresión muestra un patrón clásico immune-excluded: hay células T, pero el microambiente estromal las mantiene espacialmente alejadas de las células tumorales. Esto explica la biología de resistencia, pero no debe sobreinterpretarse como un companion diagnostic validado independiente para una terapia posterior concreta.","Teilbefund: Gute Biomarkerwerte ohne räumliche TIL-Analyse erklären die tatsächliche Immunfunktion nur unvollständig.":"Resultado parcial: valores favorables de biomarcadores sin análisis espacial de TIL describen de forma incompleta la función inmunitaria real.","TMB/PD-L1 als Potenzialmarker von funktioneller T-Zell-Tumor-Interaktion trennen":"Separar TMB/PD-L1 como marcadores de potencial de la interacción funcional célula T–tumor","Immune exclusion über räumliche CD8-Verteilung erkennen":"Reconocer immune exclusion mediante la distribución espacial de CD8","CAF-/Stroma-Barriere biologisch erklären":"Explicar biológicamente la barrera CAF/estromal","TME-IHC nicht zum nicht validierten Therapieausschlusstest machen":"No convertir la IHC del TME en una prueba no validada de exclusión terapéutica","Falschaussage: hohe TMB + PD-L1 garantieren Checkpoint-Ansprechen":"Afirmación falsa: TMB alto + PD-L1 garantizan respuesta a checkpoint","Optimale Lösung: PD-L1/TMB nicht als Garantie interpretieren; die räumliche TIL-Verteilung zeigt, dass Immunzellen vorhanden, aber funktionell vom Tumor ausgeschlossen sind. Mechanistisch stark, prädiktiv aber nicht als alleiniger Routinetest validiert.":"Solución óptima: no interpretar PD-L1/TMB como garantía; la distribución espacial de TIL muestra que las células inmunitarias están presentes, pero funcionalmente excluidas del tumor. Mecanísticamente sólido, pero no validado como prueba predictiva rutinaria independiente.","CAF":"CAF","Urothelkarzinom":"Carcinoma urotelial","Viele T-Zellen – aber auf der falschen Seite der Stromabarriere":"Muchas células T, pero en el lado equivocado de la barrera estromal","Molekularpathologie / Immunonkologie / MTB":"Patología molecular / Inmuno-oncología / MTB","PD-L1/TMB als Potenzialmarker von funktioneller Immunantwort unterscheiden.":"Distinguir PD-L1/TMB como marcadores de potencial de la respuesta inmunitaria funcional.","Immune-excluded Muster anhand räumlicher TIL-Verteilung erkennen.":"Reconocer un patrón immune-excluded por la distribución espacial de TIL.","CAF-/Stromabarriere als Resistenzmechanismus erklären.":"Explicar la barrera CAF/estromal como mecanismo de resistencia.","TME-IHC als mechanistischen und nicht automatisch validierten Selektionsmarker einordnen.":"Considerar la IHC del TME como mecanística, no automáticamente como marcador validado de selección.","Klinische Nonresponse trotz günstiger Einzelmarker biologisch plausibel erklären.":"Explicar biológicamente la falta de respuesta clínica pese a marcadores individuales favorables.","PD-L1 ist hoch, TMB ist erhöht – und der Tumor wächst unter Checkpoint-Inhibition trotzdem weiter. In der Progressionsbiopsie sind sogar viele CD8-T-Zellen zu sehen. Das Problem: Sie stehen fast alle draußen im Stroma.":"PD-L1 es alto, TMB está elevado y el tumor sigue creciendo bajo inhibición checkpoint. La biopsia de progresión incluso muestra muchas células T CD8. El problema: casi todas permanecen fuera, en el estroma.","68-jähriger Patient mit metastasiertem Urothelkarzinom und frühem Progress unter ICI trotz scheinbar günstiger PD-L1-/TMB-Konstellation. Die Progressionsbiopsie zeigt, dass nicht die Zahl allein, sondern die räumliche Position der Immunzellen entscheidend ist.":"Varón de 68 años con carcinoma urotelial metastásico y progresión precoz bajo ICI pese a una constelación aparentemente favorable de PD-L1/TMB. La biopsia de progresión muestra que importa no solo el número, sino también la posición espacial de las células inmunitarias.","Potenzial":"Potencial","PD-L1 hoch, TMB erhöht.":"PD-L1 alto, TMB elevado.","Diese Marker können Immunogenität anzeigen, garantieren aber keine effektive Antwort.":"Estos marcadores pueden indicar inmunogenicidad, pero no garantizan una respuesta eficaz.","Raum":"Espacio","CD8-Zellen liegen vor allem stromal/peritumoral.":"Las células CD8 se sitúan principalmente en zonas estromales/peritumorales.","Immune exclusion ist ein räumliches Phänomen.":"Immune exclusion es un fenómeno espacial.","Barriere":"Barrera","FAP/αSMA-reiches Stroma.":"Estroma rico en FAP/αSMA.","CAF/Matrix können physische und signalbiologische Barrieren bilden.":"CAF/matriz pueden formar barreras físicas y de señalización.","deutlich exprimiert":"Claramente expresado","erhöht":"Elevado","früher Progress unter Checkpoint-Inhibition":"Progresión precoz bajo inhibición checkpoint","Progressionsbiopsie ermöglicht räumliche TIL-/Stroma-Bewertung.":"La biopsia de progresión permite evaluación espacial de TIL/estroma.","TME-Marker sind keine validierte alleinige Folgetherapie-Selektion.":"Los marcadores del TME no están validados como pruebas independientes de selección de terapia posterior.","Mechanistische Erklärung darf nicht in Pseudopräzision kippen.":"La explicación mecanística no debe convertirse en pseudoprecisión.","Was ist die wichtigste Erklärung für PD-L1/TMB ohne Response?":"¿Cuál es la explicación más importante de PD-L1/TMB sin respuesta?","Marker zeigen Potenzial, aber nicht zwingend erfolgreiche T-Zell-Penetration und Funktion im Tumornest.":"Los marcadores indican potencial, pero no necesariamente penetración y función eficaces de las células T dentro de los nidos tumorales.","PD-L1 und TMB müssen technisch falsch sein.":"PD-L1 y TMB deben ser técnicamente incorrectos.","So eine Konstellation ist unmöglich.":"Una constelación así es imposible.","Hohe TMB beweist MSI-H.":"TMB alto demuestra MSI-H.","Biomarker und Funktion sind unterschiedliche Ebenen.":"Biomarcadores y función son niveles distintos.","Welcher Befund definiert immune exclusion am besten?":"¿Qué hallazgo define mejor immune exclusion?","Viele T-Zellen im Stroma, wenige innerhalb der Tumorzellnester.":"Muchas células T en el estroma, pocas dentro de los nidos tumorales.","Gar keine Immunzellen im gesamten Präparat.":"Ninguna célula inmunitaria en toda la muestra.","Dichtes intraepitheliales CD8-Infiltrat.":"Infiltrado CD8 intraepitelial denso.","PD-L1 hoch.":"PD-L1 alto.","Räumliche Verteilung ist zentral.":"La distribución espacial es central.","Wie darf FAP/αSMA/CD8-IHC genutzt werden?":"¿Cómo puede utilizarse la IHC FAP/αSMA/CD8?","Als mechanistische Unterstützung eines stromal-excluded Musters, nicht als alleiniger zugelassener Companion Diagnostic.":"Como apoyo mecanístico de un patrón stromal-excluded, no como companion diagnostic aprobado independiente.","Als absolute Kontraindikation gegen jede ICI.":"Como contraindicación absoluta para cualquier ICI.","Als Beweis für eine Standard-CAF-Therapie.":"Como prueba para una terapia CAF estándar.","Gar nicht interpretieren.":"No interpretarlo en absoluto.","Mechanistisch stark, klinisch nicht allein selektiv validiert.":"Mecanísticamente sólido, pero no validado clínicamente como selector independiente.","Was ist die beste MTB-Kommunikation?":"¿Cuál es la mejor comunicación en el MTB?","Günstige Einzelmarker anerkennen, reale Nonresponse und spatial TME integrieren, experimentelle TME-Strategien als Studienoption kennzeichnen.":"Reconocer los marcadores individuales favorables, integrar la falta de respuesta real y el TME espacial, y señalar las estrategias experimentales sobre TME como opciones de estudio.","PD-L1 so oft wiederholen, bis ein höherer Wert entsteht.":"Repetir PD-L1 hasta obtener un valor más alto.","TMB/PD-L1 als nutzlos erklären.":"Declarar TMB/PD-L1 inútiles.","CAF-Targeting als Standard empfehlen.":"Recomendar CAF targeting como estándar.","Evidenzhierarchie + Biologie.":"Jerarquía de evidencia + biología.","Erklären Sie die primäre Resistenz trotz PD-L1/TMB und formulieren Sie, welche Aussage die Progressionsbiopsie liefert – und welche Therapieentscheidung sie gerade nicht allein rechtfertigt.":"Explique la resistencia primaria pese a PD-L1/TMB e indique qué aporta la biopsia de progresión y qué decisión terapéutica no justifica por sí sola.","PD-L1/TMB als Potenzial, nicht Garantie einordnen.":"Considerar PD-L1/TMB como potencial, no garantía.","CD8-Verteilung räumlich beschreiben.":"Describir espacialmente la distribución de CD8.","Immune exclusion erkennen.":"Reconocer immune exclusion.","CAF-/Stromabarriere mechanistisch erklären.":"Explicar mecanísticamente la barrera CAF/estromal.","TME-IHC nicht als alleinigen Companion Diagnostic verwenden.":"No utilizar la IHC del TME como companion diagnostic independiente.","Studienoptionen klar als experimentell markieren.":"Marcar claramente las opciones de estudio como experimentales.","Wenn keine Progressionsbiopsie verfügbar ist, morphologische/radiologische Daten nutzen und TME-Hypothese als Hypothese belassen.":"Si no hay biopsia de progresión, usar datos morfológicos/radiológicos y mantener la hipótesis del TME como hipótesis.","TME-gerichtete Studien bei passender Verfügbarkeit diskutieren.":"Discutir estudios dirigidos al TME si están disponibles de forma apropiada.","PD-L1/TMB garantieren Response":"PD-L1/TMB garantizan respuesta","Funktionelle Immunantwort braucht mehr als Potenzialmarker.":"La respuesta inmunitaria funcional requiere más que marcadores de potencial.","TME-IHC = Therapieausschluss":"IHC TME = exclusión terapéutica","Nicht als alleiniger validierter Selektionsassay etabliert.":"No está establecido como assay validado independiente de selección.","CAF-Targeting Standard":"CAF targeting estándar","Mechanismus wird zu Routineempfehlung überhöht.":"Un mecanismo se eleva indebidamente a recomendación rutinaria.","Die T-Zellen sind da – und kommen trotzdem nicht an den Tumor":"Las células T están ahí y aun así no llegan al tumor","Die Progressionsbiopsie zeigt viele CD8-Zellen, aber fast ausschließlich in FAP/αSMA-reichem Stroma. Der scheinbare Widerspruch zwischen 'immunogen' und 'resistent' löst sich räumlich auf.":"La biopsia de progresión muestra muchas células CD8, pero casi exclusivamente en estroma rico en FAP/αSMA. La aparente contradicción entre «inmunogénico» y «resistente» se resuelve espacialmente.","Der Fall macht aus TME ein sichtbares diagnostisches Konzept statt einer abstrakten Signalwegfolie.":"El caso convierte el TME en un concepto diagnóstico visible en lugar de una diapositiva abstracta de pathways.","Spatial biology integriert":"Biología espacial integrada","PD-L1/TMB günstig, aber CD8 stromal ausgeschlossen; TME erklärt Resistenz, ohne einen neuen Companion Diagnostic zu behaupten.":"PD-L1/TMB favorables, pero células CD8 excluidas por el estroma; el TME explica la resistencia sin afirmar un nuevo companion diagnostic.","Biologie und Evidenz sauber getrennt.":"Biología y evidencia claramente separadas.","Stroma erkannt, Marker verworfen":"Estroma reconocido, marcadores descartados","Immune exclusion korrekt, aber PD-L1/TMB pauschal als wertlos dargestellt.":"Immune exclusion es correcto, pero PD-L1/TMB se declaran globalmente inútiles.","Zu absolut.":"Demasiado absoluto.","Biomarker-Garantie":"Garantía por biomarcador","Früher Progress wird ignoriert, weil PD-L1/TMB 'gut' sind.":"Se ignora la progresión precoz porque PD-L1/TMB son «buenos». ","Funktionelle Ebene verpasst.":"Se pierde el nivel funcional.","Studie mit TME-gerichteter Kombination verfügbar":"Estudio con combinación dirigida al TME disponible","Als experimentelle Option diskutieren.":"Discutir como opción experimental.","Mechanistische Hypothese wird im passenden Evidenzrahmen genutzt.":"La hipótesis mecanística se utiliza dentro del marco de evidencia apropiado.","Keine Studie":"Sin estudio","Standardtherapie nach etablierter Entitätslogik.":"Tratamiento estándar según la lógica establecida específica de la entidad.","TME-Befund bleibt erklärend, nicht pseudoprädiktiv.":"El hallazgo del TME sigue siendo explicativo, no pseudopredictivo.","Biomarker können Potenzial anzeigen, aber keine Antwort garantieren.":"Los biomarcadores pueden indicar potencial, pero no garantizar respuesta.","Immune exclusion ist räumlich: Immunzellen vorhanden, aber vom Tumornest ferngehalten.":"Immune exclusion es espacial: hay células inmunitarias, pero se mantienen alejadas de los nidos tumorales.","CAF-/Matrix-Komponenten können physische und signalbiologische Barrieren bilden.":"Los componentes CAF/matriz pueden formar barreras físicas y de señalización.","TME-IHC ist mechanistisch wertvoll, aber kein automatisch validierter Companion Diagnostic.":"La IHC del TME es valiosa mecanísticamente, pero no un companion diagnostic automáticamente validado.","Progressionsmaterial kann Resistenzbiologie sichtbar machen.":"El material de progresión puede revelar la biología de resistencia.","Trotz PD-L1 und erhöhter TMB zeigt die Progressionsbiopsie ein immune-excluded Muster mit CD8-Zellen im stromalen Kompartiment. Das erklärt die fehlende effektive Tumorinteraktion, ist aber kein alleiniger routinemäßiger Selektionsmarker für eine konkrete Folgetherapie.":"Pese a PD-L1 y TMB elevado, la biopsia de progresión muestra un patrón immune-excluded con células CD8 en el compartimento estromal. Esto explica la falta de interacción tumoral eficaz, pero no es un marcador rutinario independiente de selección de una terapia posterior concreta.","Marker vs Funktion":"Marcadores vs función","spatial TILs":"TIL espaciales","Stromabarriere":"Barrera estromal","Was ist der Unterschied zwischen immune-desert und immune-excluded?":"¿Cuál es la diferencia entre immune-desert e immune-excluded?","Welche Rolle kann TGF-β/CAF-Biologie spielen?":"¿Qué papel puede desempeñar la biología TGF-β/CAF?","Wie könnte Digitalpathologie spatial TILs künftig standardisieren?":"¿Cómo podría la patología digital estandarizar los TIL espaciales en el futuro?","viele CD8-Zellen, aber außerhalb der Tumornester":"Muchas células CD8, pero fuera de los nidos tumorales","Räumliche Immunbiologie kann Einzelmarker widersprechen":"La biología inmunitaria espacial puede contradecir marcadores individuales","PD-L1/TMB → Nonresponse → spatial biopsy → immune exclusion":"PD-L1/TMB → falta de respuesta → biopsia espacial → immune exclusion","pT1-CRC nach Endoskopie: Tumor budding als sichtbarer Invasions-Hallmark":"CRC pT1 tras endoscopia: tumor budding como hallmark visible de invasión","EMT-/Invasionsfront-Fall mit Metas…":"Caso EMT/frente invasivo con metas…","Gastroenterologie / Viszeralchirurgie / Pathologieboard":"Gastroenterología / Cirugía visceral / Board de patología","56-jähriger Patient nach endoskopischer en-bloc-Resektion eines pT1-Sigmakarzinoms. Die Frage ist, ob die lokale Therapie ausreicht oder wegen Lymphknotenrisiko eine onkologische Nachresektion diskutiert werden muss.":"Varón de 56 años tras resección endoscópica en bloc de un carcinoma sigmoideo pT1. La cuestión es si el tratamiento local es suficiente o si debe plantearse una resección oncológica adicional por riesgo ganglionar.","Welche morphologischen Merkmale an der Invasionsfront sind klinisch relevant – und welche Rolle spielt das EMT-Konzept dabei?":"¿Qué rasgos morfológicos del frente invasivo son clínicamente relevantes y qué papel desempeña el concepto EMT?","Entscheidung über weitere Operation im nächsten Board.":"Decisión sobre cirugía adicional en el próximo board.","Endoskopie":"Endoscopia","20-mm-Läsion, vollständig en bloc reseziert.":"Lesión de 20 mm, resecada completamente en bloc.","pT1-Adenokarzinom, Resektionsrand tumorfrei.":"Adenocarcinoma pT1, margen de resección libre de tumor.","Konflikt":"Conflicto","Ein 'R0' klingt beruhigend, aber R0 beantwortet das Risiko okkulter Lymphknotenmetastasen nicht allein.":"Un «R0» suena tranquilizador, pero R0 por sí solo no responde al riesgo de metástasis ganglionares ocultas.","Ein experimentelles EMT-IHC-Panel wird höher gewichtet als validierte histopathologische Risikofaktoren.":"Se da más peso a un panel IHC EMT experimental que a factores de riesgo histopatológicos validados.","Histologie + Invasionsfront":"Histología + frente invasivo","Submukosale Invasion; an der tiefsten Front zahlreiche Einzelzellen und kleine Tumorzellcluster entsprechend hochgradigem Tumor budding.":"Invasión submucosa; en el frente más profundo, numerosas células aisladas y pequeños grupos tumorales correspondientes a tumor budding de alto grado.","Weitere Risiken":"Riesgos adicionales","Fokale lymphovaskuläre Invasion; keine schlechte Differenzierung.":"Invasión linfovascular focal; sin mala diferenciación.","EMT-Kontext":"Contexto EMT","An Buds fokal reduzierte membranäre E-Cadherin-Expression und veränderte β-Catenin-Lokalisation möglich – biologisch passend zu partieller EMT.":"En los buds puede observarse reducción focal de la expresión membranosa de E-cadherina y localización alterada de β-catenina, biológicamente compatible con EMT parcial.","Morphologischer Risikomarker versus mechanistischer Zusatzbefund.":"Marcador morfológico de riesgo frente a hallazgo mecanístico adicional.","Komplettes endoskopisches Resektat, gut orientiert.":"Pieza completa de resección endoscópica, bien orientada.","Primärentscheidung":"Decisión principal","HE-basierte Bewertung von Budding, LVI, Differenzierung, Invasionstiefe und Resektionsrand.":"Evaluación basada en HE de budding, LVI, diferenciación, profundidad de invasión y margen de resección.","Zusatz-IHC":"IHC adicional","EMT-Panel kann den Hallmark illustrieren, ist aber nicht erforderlich, um den klinischen Hochrisikobefund zu erkennen.":"Un panel EMT puede ilustrar el hallmark, pero no es necesario para reconocer el hallazgo clínico de alto riesgo.","Mechanismusmarker dürfen die standardisierte Morphologie nicht verdrängen.":"Los marcadores mecanísticos no deben desplazar la morfología estandarizada.","Histologische Invasionsfront / Risikofaktoren":"Frente invasivo histológico / factores de riesgo","HE / Invasionsfront":"HE / frente invasivo","Hochgradiges Tumor budding an der tiefen Invasionsfront plus fokale lymphovaskuläre Invasion. Diese histopathologischen Hochrisikofaktoren sind für die Entscheidung nach endoskopischer pT1-Resektion klinisch relevant.":"Tumor budding de alto grado en el frente invasivo profundo más invasión linfovascular focal. Estos factores histopatológicos de alto riesgo son clínicamente relevantes para la decisión tras resección endoscópica pT1.","EMT-IHC":"IHC EMT","Buds zeigen fokal reduzierte E-Cadherin-Membranfärbung, Vimentin-Zunahme und veränderte β-Catenin-Lokalisation – mechanistisch vereinbar mit partieller EMT, aber kein eigenständiger validierter Operationsindikator.":"Los buds muestran reducción focal de la tinción membranosa de E-cadherina, aumento de vimentina y localización alterada de β-catenina, mecanísticamente compatible con EMT parcial, pero no una indicación quirúrgica independiente validada.","Breite Tumorgenetik liefert für die unmittelbare pT1-Risikostratifikation keinen Ersatz für die relevanten histopathologischen Invasionsmerkmale.":"La genética tumoral amplia no sustituye los rasgos histopatológicos de invasión relevantes para la estratificación inmediata del riesgo pT1.","Resektion":"Resección","Endoskopisch R0.":"R0 endoscópico.","Invasionsfront":"Frente invasivo","Hochgradiges Tumor budding und fokale Lymphgefäßinvasion.":"Tumor budding de alto grado e invasión linfática focal.","Der Fall verbindet Morphologie und Hallmark-Biologie: Tumor budding an der Invasionsfront ist ein sichtbares Korrelat invasiver/plastischer Tumorzellzustände und bei pT1-CRC ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen. EMT-IHC kann die Biologie illustrieren, entscheidet aber nicht über die weitere Operation. Die klinische Konsequenz entsteht aus standardisierten Hochrisikofaktoren wie Budding, LVI, Differenzierung, Tiefe und Resektionsstatus.":"El caso conecta morfología y biología hallmark: el tumor budding en el frente invasivo es un correlato visible de estados tumorales invasivos/plásticos y un factor histopatológico establecido de riesgo de metástasis ganglionares en CRC pT1. La IHC EMT puede ilustrar la biología, pero no decide la cirugía adicional. La consecuencia clínica deriva de factores estandarizados de alto riesgo como budding, LVI, diferenciación, profundidad y estado de resección.","Teilbefund: EMT ist biologisch plausibel, aber die klinische Risikoeinschätzung muss an validierten histopathologischen Merkmalen hängen.":"Resultado parcial: EMT es biológicamente plausible, pero la evaluación del riesgo clínico debe basarse en rasgos histopatológicos validados.","Tumor budding als klinisch relevanten Invasionsfront-Befund erkennen":"Reconocer tumor budding como hallazgo clínicamente relevante del frente invasivo","R0 nicht mit niedrigem Lymphknotenrisiko gleichsetzen":"No equiparar R0 con bajo riesgo ganglionar","EMT als mechanistische Erklärung, nicht als eigenständigen Routine-Selektionsassay einordnen":"Considerar EMT como explicación mecanística, no como assay rutinario independiente de selección","HE-basierte standardisierte Risikofaktoren priorisieren":"Priorizar factores de riesgo estandarizados basados en HE","Falschaussage: ein positives EMT-IHC-Panel ist die Operationsindikation":"Afirmación falsa: un panel IHC EMT positivo es la indicación quirúrgica","Optimale Lösung: Morphologie zuerst. High-grade budding und LVI machen den pT1-Fall trotz R0 klinisch risikorelevant; EMT-IHC erklärt das Hallmark, ersetzt aber nicht die standardisierte histopathologische Entscheidung.":"Solución óptima: primero la morfología. Budding de alto grado y LVI hacen que el caso pT1 sea clínicamente de alto riesgo pese a R0; la IHC EMT explica el hallmark, pero no sustituye la decisión histopatológica estandarizada.","pT1 CRC":"CRC pT1","Tumor budding":"Tumor budding","Invasion":"Invasión","EMT":"EMT","Lymphovascular invasion":"Invasión linfovascular","Hallmarks":"Hallmarks","Tumor budding: Hallmark im HE statt EMT-Overtesting":"Tumor budding: hallmark visible en HE en lugar de sobrepruebas EMT","GI-Pathologie / Molekularpathologie / MTB":"Patología GI / Patología molecular / MTB","Tumor budding als morphologisches Korrelat invasiver/plastischer Tumorzellzustände erkennen.":"Reconocer tumor budding como correlato morfológico de estados tumorales invasivos/plásticos.","Bei pT1-CRC klinisch relevante histopathologische Hochrisikofaktoren priorisieren.":"Priorizar factores histopatológicos de alto riesgo clínicamente relevantes en CRC pT1.","R0-Resektion von Lymphknotenrisiko unterscheiden.":"Distinguir resección R0 de riesgo ganglionar.","EMT-IHC als mechanistische Illustration und nicht als eigenständigen Operationsindikator einordnen.":"Considerar la IHC EMT como ilustración mecanística, no como indicación quirúrgica independiente.","Morphologie direkt mit Hallmark-Biologie und klinischer Konsequenz verbinden.":"Conectar directamente morfología con biología hallmark y consecuencia clínica.","Der Polyp ist komplett raus, der Rand ist frei – eigentlich klingt alles gut. An der tiefen Invasionsfront stehen jedoch zahlreiche einzelne Tumorzellen und kleine Cluster: High-grade tumor budding. Genau dort wird ein abstrakter Hallmark plötzlich klinisch sichtbar.":"El pólipo está completamente extirpado y el margen es libre: todo parece favorable. Sin embargo, en el frente invasivo profundo hay numerosas células tumorales aisladas y pequeños grupos: tumor budding de alto grado. Ahí es donde un hallmark abstracto se vuelve de pronto clínicamente visible.","56-jähriger Patient nach endoskopischer R0-Resektion eines pT1-Sigmakarzinoms. Das Board muss entscheiden, ob wegen histopathologischer Hochrisikofaktoren eine onkologische Nachresektion diskutiert werden sollte. EMT ist die biologische Erklärung, aber nicht der primäre klinische Test.":"Varón de 56 años tras resección endoscópica R0 de un carcinoma sigmoideo pT1. El board debe decidir si debe discutirse una resección oncológica adicional por factores histopatológicos de alto riesgo. EMT es la explicación biológica, pero no la prueba clínica principal.","R0 ist nicht alles":"R0 no lo es todo","Lokale Exzision ist vollständig.":"La escisión local es completa.","Okkultes Lymphknotenrisiko bleibt eine andere Frage.":"El riesgo ganglionar oculto sigue siendo una cuestión distinta.","Budding ist sichtbar":"El budding es visible","Einzelzellen/kleine Cluster an der Invasionsfront.":"Células aisladas/pequeños grupos en el frente invasivo.","Morphologie kann funktionelle Tumorbiologie verdichten.":"La morfología puede condensar la biología tumoral funcional.","EMT erklärt, entscheidet aber nicht allein":"EMT explica, pero no decide por sí solo","E-Cadherin/Vimentin/β-Catenin können partielle EMT illustrieren.":"E-cadherina/vimentina/β-catenina pueden ilustrar EMT parcial.","Standardisierte Histopathologie trägt die klinische Entscheidung.":"La histopatología estandarizada sustenta la decisión clínica.","Resektionsstatus":"Estado de resección","R0":"R0","high-grade tumor budding + fokale LVI":"Tumor budding de alto grado + LVI focal","Differenzierung":"Diferenciación","nicht schlecht differenziert":"No pobremente diferenciado","Komplettes gut orientiertes endoskopisches Resektat.":"Pieza completa de resección endoscópica, bien orientada.","HE-Reevaluation ist der wichtigste 'Test'.":"La reevaluación HE es la «prueba» más importante.","EMT-IHC verbraucht Schnitte ohne zwingenden Zusatznutzen für die Operationsentscheidung.":"La IHC EMT consume cortes sin un beneficio adicional imprescindible para la decisión quirúrgica.","Welche Aussage zu Tumor budding im pT1-CRC ist am treffendsten?":"¿Qué afirmación sobre tumor budding en CRC pT1 es la más acertada?","Es ist ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen und muss mit anderen Hochrisikofaktoren integriert werden.":"Es un factor histopatológico establecido de riesgo de metástasis ganglionares y debe integrarse con otros factores de alto riesgo.","Es ist nur ein interessantes Morphologiedetail.":"Es solo un detalle morfológico interesante.","Es kann nur durch NGS diagnostiziert werden.":"Solo puede diagnosticarse mediante NGS.","Es ist synonym mit positivem Resektionsrand.":"Es sinónimo de margen de resección positivo.","Budding hat klinische Risikobedeutung.":"El budding tiene relevancia clínica de riesgo.","Was bedeutet R0 hier?":"¿Qué significa R0 aquí?","Die lokale Resektion ist vollständig; das nodale Metastasierungsrisiko wird dadurch nicht automatisch null.":"La resección local es completa; el riesgo de metástasis ganglionares no pasa automáticamente a cero.","Heilung ist sicher.":"La curación está asegurada.","Lymphknotenmetastasen sind ausgeschlossen.":"Se excluyen metástasis ganglionares.","EMT ist ausgeschlossen.":"EMT está excluida.","Lokaler Randstatus und biologisches Metastasierungsrisiko sind getrennt.":"El estado del margen local y el riesgo biológico de metástasis son distintos.","Welche Rolle hat das EMT-IHC-Panel?":"¿Qué papel tiene el panel IHC EMT?","Es kann partielle EMT mechanistisch illustrieren, ist aber kein eigenständiger validierter Operationsindikator.":"Puede ilustrar mecanísticamente EMT parcial, pero no es una indicación quirúrgica independiente validada.","Es ist zwingend vor jeder Nachresektion erforderlich.":"Es obligatorio antes de toda resección adicional.","Es ersetzt Tumor budding.":"Sustituye tumor budding.","Es liefert unmittelbar eine zugelassene Targettherapie.":"Proporciona directamente una terapia dirigida aprobada.","Mechanismusmarker ≠ klinischer Standard-Risikomarker.":"Marcador mecanístico ≠ marcador clínico estándar de riesgo.","Welche Befunde tragen die klinische Entscheidung primär?":"¿Qué hallazgos sustentan principalmente la decisión clínica?","Budding, LVI, Differenzierung, Invasionstiefe und Resektionsstatus im standardisierten histopathologischen Kontext.":"Budding, LVI, diferenciación, profundidad de invasión y estado de resección en el contexto histopatológico estandarizado.","Nur E-Cadherin/Vimentin.":"Solo E-cadherina/vimentina.","Breites Pan-Cancer-NGS.":"NGS pan-cancer amplio.","PD-L1.":"PD-L1.","Morphologische Risikofaktoren sind hier zentral.":"Los factores morfológicos de riesgo son centrales aquí.","Leiten Sie vom HE-Befund an der Invasionsfront über die Hallmark-Biologie zur klinischen Konsequenz nach endoskopischer pT1-Resektion ab.":"Derive la consecuencia clínica tras resección endoscópica pT1 desde el hallazgo HE del frente invasivo pasando por la biología hallmark.","R0 als lokalen Resektionsstatus anerkennen.":"Reconocer R0 como estado local de resección.","High-grade tumor budding erkennen und standardisiert bewerten.":"Reconocer y evaluar de forma estandarizada tumor budding de alto grado.","LVI als zusätzlichen Hochrisikofaktor integrieren.":"Integrar LVI como factor adicional de alto riesgo.","EMT als mechanistische Erklärung formulieren.":"Formular EMT como explicación mecanística.","EMT-IHC nicht zur Operationsvoraussetzung machen.":"No convertir la IHC EMT en requisito para cirugía.","Onkologische Nachresektion wegen kombinierter Hochrisikofaktoren im Board diskutieren.":"Discutir resección oncológica adicional en el board por la combinación de factores de alto riesgo.","Auf EMT-IHC vollständig verzichten und die Hallmark-Biologie rein morphologisch erklären – klinisch absolut vertretbar.":"Omitir por completo la IHC EMT y explicar la biología hallmark solo morfológicamente: clínicamente totalmente aceptable.","Bei Grenzfällen zusätzliche pathologische Zweitbegutachtung statt breitem Molekularpanel.":"En casos límite, utilizar una segunda revisión patológica en lugar de un panel molecular amplio.","R0 = kein Risiko":"R0 = sin riesgo","Lymphknotenrisiko ist nicht identisch mit lokalem Randstatus.":"El riesgo ganglionar no es idéntico al estado del margen local.","EMT-IHC entscheidet":"La IHC EMT decide","Mechanistische Marker ersetzen keine validierte pT1-Risikostratifikation.":"Los marcadores mecanísticos no sustituyen la estratificación validada del riesgo pT1.","Budding nur Forschung":"Budding solo para investigación","Budding besitzt etablierte prognostische/Risikobedeutung.":"El budding tiene relevancia pronóstica/de riesgo establecida.","Der wichtigste Hallmark-Test ist bereits auf dem HE":"La prueba hallmark más importante ya está en la HE","Das optionale EMT-Panel zeigt erwartbare partielle EMT-Zeichen, ändert aber die klinische Entscheidung nicht. High-grade budding und LVI waren bereits im HE sichtbar und tragen die Konsequenz.":"El panel EMT opcional muestra rasgos esperables de EMT parcial, pero no cambia la decisión clínica. El budding de alto grado y LVI ya eran visibles en HE y sustentan la consecuencia.","Der Fall verbindet Grundlagenbiologie mit Pathologieroutine, ohne Molekulardiagnostik künstlich aufzublähen.":"El caso conecta biología básica con patología rutinaria sin inflar artificialmente el diagnóstico molecular.","Morphologie → Hallmark → Konsequenz":"Morfología → hallmark → consecuencia","R0-pT1-CRC, aber high-grade budding + LVI → relevantes nodales Risiko; EMT mechanistisch, nicht als Pflichtassay.":"CRC pT1 R0, pero budding de alto grado + LVI → riesgo ganglionar relevante; EMT mecanístico, no assay obligatorio.","Genau die gewünschte Integrationsleistung.":"Exactamente la integración buscada.","EMT verstanden, Risiko unscharf":"EMT comprendido, riesgo poco claro","Biologie gut erklärt, aber klinisch relevante Histofaktoren nicht priorisiert.":"La biología está bien explicada, pero no se priorizan los factores histológicos clínicamente relevantes.","Zu grundlagenlastig.":"Demasiado centrado en biología básica.","R0 = erledigt":"R0 = resuelto","Budding/LVI werden trotz freiem Rand ignoriert.":"Se ignoran budding/LVI pese al margen libre.","Klinische Konsequenz verpasst.":"Se pierde la consecuencia clínica.","Mehrere histologische Hochrisikofaktoren":"Múltiples factores histológicos de alto riesgo","Onkologische Nachresektion mit Lymphknotenbewertung im interdisziplinären Kontext diskutieren.":"Discutir resección oncológica adicional con evaluación ganglionar en contexto interdisciplinario.","Nodales Risiko wird adressiert.":"Se aborda el riesgo ganglionar.","Keine Hochrisikofaktoren":"Sin factores de alto riesgo","Lokale Strategie nach geltenden Kriterien erwägen.":"Considerar estrategia local según criterios aplicables.","Übertherapie vermeiden.":"Evitar sobretratamiento.","Tumor budding ist ein morphologisches Korrelat von Invasion/plastischen Zellzuständen.":"Tumor budding es un correlato morfológico de invasión/estados celulares plásticos.","Bei pT1-CRC ist budding ein klinisch relevanter Risikofaktor für Lymphknotenmetastasen.":"En CRC pT1, el budding es un factor de riesgo clínicamente relevante de metástasis ganglionares.","R0 beantwortet die lokale Resektion, nicht automatisch das nodale Risiko.":"R0 responde al estado de resección local, no automáticamente al riesgo ganglionar.","EMT-IHC kann Mechanismus illustrieren, ist aber kein notwendiger Operationsindikator.":"La IHC EMT puede ilustrar el mecanismo, pero no es una indicación quirúrgica necesaria.","HE kann funktionelle Tumorbiologie als kumulative Morphologie sichtbar machen.":"HE puede hacer visible la biología tumoral funcional como morfología acumulativa.","Trotz R0-Resektion zeigen high-grade tumor budding und LVI ein relevantes Lymphknotenrisiko. Tumor budding verbindet die Invasionsfront direkt mit Hallmark-Biologie; EMT-IHC ist optional erklärend, nicht entscheidungsdefinierend.":"Pese a resección R0, tumor budding de alto grado y LVI indican un riesgo ganglionar relevante. Tumor budding conecta directamente el frente invasivo con la biología hallmark; la IHC EMT es opcional y explicativa, no definitoria de la decisión.","R0 vs nodales Risiko":"R0 vs riesgo ganglionar","EMT als Mechanismus":"EMT como mecanismo","Morphologie priorisiert":"Morfología priorizada","Welche HE-Merkmale sind funktionelle 'Fingerabdrücke' von Hallmarks?":"¿Qué rasgos HE son «huellas» funcionales de hallmarks?","Warum ist partielle EMT biologisch plausibler als ein binärer EMT-Schalter?":"¿Por qué EMT parcial es biológicamente más plausible que un interruptor EMT binario?","Wo hilft Molekulardiagnostik – und wo macht sie einen guten HE-Befund nur komplizierter?":"¿Dónde ayuda el diagnóstico molecular y dónde solo complica un buen hallazgo HE?","high-grade budding trotz R0":"Budding de alto grado pese a R0","Morphologie kann Hallmarks klinisch relevant abbilden":"La morfología puede representar hallmarks de forma clínicamente relevante","R0 → Invasionsfront → budding/LVI → Hallmark → klinische Konsequenz":"R0 → frente invasivo → budding/LVI → hallmark → consecuencia clínica","Coverage-Loch im EGFR-Exon 20: „negativ“ ist hier nicht negativ":"Brecha de cobertura en el exón 20 de EGFR: aquí «negativo» no significa negativo","Coverage-Loch in therapieentscheid…":"Brecha de cobertura en un exón decisivo para el tratamiento…","58-jährige Nie-Raucherin mit metastasiertem pulmonalem Adenokarzinom. Das DNA-Panel wird als „kein therapierbarer Treiber nachweisbar“ zusammengefasst.":"Mujer de 58 años, nunca fumadora, con adenocarcinoma pulmonar metastásico. El panel de ADN se resume como «no se detecta ningún driver accionable». ","Darf der Fall als molekular negativ abgeschlossen werden, obwohl der Coverage-Report für EGFR-Exon 20 unterhalb des laborintern validierten Mindestkriteriums liegt?":"¿Puede cerrarse el caso como molecularmente negativo aunque el informe de cobertura del exón 20 de EGFR esté por debajo del criterio mínimo validado internamente por el laboratorio?","Die Erstlinienentscheidung soll in vier Tagen fallen.":"La decisión de primera línea debe tomarse en cuatro días.","ECOG 1, Leber- und Knochenmetastasen; ausreichend Zeit für eine gezielte Nachklärung, aber nicht für beliebig viele Wiederholungen.":"ECOG 1, metástasis hepáticas y óseas; hay tiempo suficiente para una aclaración dirigida, pero no para repeticiones ilimitadas.","KRAS, BRAF, MET-Exon-14 und ERBB2 ohne pathogene Alteration; Fusionstestung separat vorgesehen.":"KRAS, BRAF, exón 14 de MET y ERBB2 sin alteraciones patogénicas; el estudio de fusiones está previsto por separado.","QC-Hinweis":"Nota de QC","Median-Coverage des Panels ca. 780×, EGFR-Exon 20 jedoch nur 24×; laborintern validiertes Mindestkriterium für einen negativen Call wird dort nicht erreicht.":"La cobertura mediana del panel es de aproximadamente 780×, pero el exón 20 de EGFR solo alcanza 24×; en esa región no se cumple el criterio mínimo validado internamente por el laboratorio para un call negativo.","Ein global „guter“ Run wird mit vollständiger lokaler Aussagefähigkeit gleichgesetzt.":"Se equipara un run globalmente «bueno» con una interpretabilidad local completa.","Adenokarzinom der Lunge, TTF1/Napsin A positiv.":"Adenocarcinoma pulmonar, TTF1/Napsin A positivos.","ca. 45 %.":"aprox. 45 %.","Ist das Exon tatsächlich wildtyp oder nur unzureichend untersucht?":"¿El exón es realmente wild type o simplemente se ha estudiado de forma insuficiente?","Hinweis":"Nota","„Nicht nachgewiesen“ und „nicht ausreichend geprüft“ sind unterschiedliche Aussagen.":"«No detectado» y «no evaluado suficientemente» son afirmaciones distintas.","FFPE-Lebermetastase, Restblock vorhanden.":"Metástasis hepática FFPE, bloque residual disponible.","Menge ausreichend; übrige Targets technisch unauffällig.":"Cantidad suficiente; el resto de dianas sin incidencias técnicas.","Coverage":"Cobertura","isolierter Dropout in EGFR-Exon 20.":"dropout aislado en el exón 20 de EGFR.","Ressourcen":"Recursos","Eine gezielte orthogonale Abklärung ist schneller und materialsparender als ein blindes komplettes Re-Panel.":"Una aclaración ortogonal dirigida es más rápida y consume menos material que repetir a ciegas todo el panel.","Coverage-/QC-Review":"Revisión de cobertura/QC","Nicht ausreichend abgedecktes Exon gezielt klären":"Aclaración dirigida del exón con cobertura insuficiente","Coverage-Review":"Revisión de cobertura","Der Run ist global valide, aber EGFR-Exon 20 unterschreitet das laborintern validierte Mindestkriterium. Für dieses Exon ist ein negativer Befund nicht belastbar.":"El run es globalmente válido, pero el exón 20 de EGFR queda por debajo del criterio mínimo validado internamente por el laboratorio. Un resultado negativo para este exón no es fiable.","Orthogonale Abklärung":"Aclaración ortogonal","Eine unabhängig amplifizierte, validierte Zielmethode weist eine EGFR-Exon-20-Insertion nach. Der ursprüngliche „negative“ Panelbefund war an dieser Stelle nicht aussagefähig.":"Un método dirigido validado con amplificación independiente detecta una inserción en el exón 20 de EGFR. El resultado «negativo» original del panel no era informativo en esa región.","NGS-Wiederholung":"Repetición de NGS","Die Wiederholung mit demselben Assay zeigt erneut den lokalen Dropout. Ein identisches technisches Design löst den systematischen Coverage-Ausfall nicht zuverlässig.":"La repetición del mismo ensayo vuelve a mostrar el dropout local. Un diseño técnico idéntico no resuelve de forma fiable el fallo sistemático de cobertura.","Breites Re-Panel":"Re-panel amplio","Mehr Panelbreite beantwortet das lokale Coverage-Problem nicht automatisch; entscheidend ist die validierte Abdeckung des fraglichen Exons.":"Un panel más amplio no resuelve automáticamente un problema local de cobertura; lo decisivo es la cobertura validada del exón en cuestión.","Global gute Sequenzierqualität; isolierter lokaler Coverage-Ausfall in einem therapieentscheidenden Bereich.":"Calidad de secuenciación globalmente buena; fallo local aislado de cobertura en una región decisiva para el tratamiento.","Ein negativer Call ist nur für ausreichend validiert untersuchte Zielregionen zulässig.":"Un call negativo solo es admisible para regiones diana estudiadas suficientemente en condiciones validadas.","Der NGS-Run ist nicht insgesamt ungültig, aber EGFR-Exon 20 ist wegen lokaler Unterabdeckung nicht sicher negativ befundbar. Die Limitation muss explizit berichtet und die Zielregion gezielt nachuntersucht werden. Eine orthogonale Methode weist schließlich eine EGFR-Exon-20-Insertion nach.":"El run de NGS no es inválido en su conjunto, pero el exón 20 de EGFR no puede informarse de forma fiable como negativo debido a una cobertura local insuficiente. La limitación debe comunicarse explícitamente y la región diana debe reanalizarse de forma dirigida. Un método ortogonal detecta finalmente una inserción del exón 20 de EGFR.","Teilbefund: Das Panel darf nicht pauschal als vollständig negativ zusammengefasst werden, solange die therapieentscheidende Zielregion das validierte Coverage-Kriterium nicht erfüllt.":"Informe parcial: el panel no debe resumirse globalmente como completamente negativo mientras la región diana decisiva para el tratamiento no cumpla el criterio validado de cobertura.","lokale Coverage statt nur Mittelwert prüfen":"comprobar la cobertura local, no solo la media","„nicht nachgewiesen“ von „nicht ausreichend untersucht“ trennen":"distinguir «no detectado» de «no evaluado suficientemente»","gezielte Nachtestung definieren":"definir el reanálisis dirigido","Falschaussage: hohe Median-Coverage macht jede Zielregion sicher negativ":"Afirmación falsa: una cobertura mediana alta hace que todas las regiones diana sean negativas con seguridad","Optimale Lösung: lokalen Coverage-Defekt erkennen, die Aussage im Befund begrenzen und das betroffene Exon mit einer unabhängigen validierten Methode schließen.":"Solución óptima: reconocer el defecto local de cobertura, limitar la afirmación en el informe y cerrar el exón afectado con un método validado independiente.","MTB-LAB":"MTB-LAB","Das Loch im „negativen“ Panel":"La brecha en el panel «negativo»","Molekularpathologie / NGS-Freigabe / MTB":"Patología molecular / liberación de NGS / MTB","Coverage auf Zielregionsebene statt nur als Run-Mittelwert bewerten.":"Evaluar la cobertura a nivel de región diana y no solo como media del run.","Nicht nachgewiesen von nicht ausreichend untersucht unterscheiden.":"Distinguir no detectado de no evaluado suficientemente.","Bei lokalem Coverage-Ausfall Limitation und gezielte Nachtestung formulieren.":"Ante un fallo local de cobertura, formular la limitación y el reanálisis dirigido.","Wiederholung desselben Assays von einer methodisch unabhängigen Bestätigung unterscheiden.":"Distinguir la repetición del mismo ensayo de una confirmación metodológicamente independiente.","Der Bericht sagt „kein therapierbarer Treiber“. Im QC-Tab fällt aber eine einzige rote Zeile auf: EGFR-Exon 20, 24×. Der Rest des Panels liegt bei mehreren hundert Reads. Genau dort darf aus „nichts gesehen“ kein „sicher nicht vorhanden“ werden.":"El informe dice «ningún driver accionable». Pero en la pestaña de QC destaca una única línea roja: exón 20 de EGFR, 24×. El resto del panel tiene varios cientos de reads. Precisamente ahí, «no se vio nada» no puede convertirse en «con seguridad no está presente». ","58-jährige Nie-Raucherin mit metastasiertem Lungenadenokarzinom. Das Panel ist global technisch gut, aber eine therapieentscheidende Zielregion unterschreitet das validierte Mindestkriterium. Das Board muss entscheiden, ob limitiert berichtet, wiederholt oder orthogonal geschlossen wird.":"Mujer de 58 años, nunca fumadora, con adenocarcinoma pulmonar metastásico. El panel es técnicamente bueno en conjunto, pero una región diana decisiva para el tratamiento queda por debajo del criterio mínimo validado. El board debe decidir si informa con limitación, repite el test o cierra la brecha de forma ortogonal.","Global gut, lokal schlecht":"Globalmente bueno, localmente deficiente","Median-Coverage ca. 780×, EGFR-Exon 20 nur 24×.":"Cobertura mediana aprox. 780×, exón 20 de EGFR solo 24×.","Run-QC ersetzt keine Target-QC.":"El QC del run no sustituye al QC de la diana.","Sprache ist Diagnostik":"El lenguaje forma parte del diagnóstico","„Keine Mutation nachweisbar“ behauptet mehr als „Region nicht ausreichend abgedeckt“.":"«No se detecta mutación» afirma más que «región con cobertura insuficiente». ","Befundformulierung muss die analytische Aussagegrenze spiegeln.":"La redacción del informe debe reflejar los límites analíticos de interpretación.","Wiederholung ist nicht automatisch unabhängig":"Repetir no equivale automáticamente a independencia","Ein identisches Assaydesign kann denselben Dropout reproduzieren.":"Un diseño de ensayo idéntico puede reproducir el mismo dropout.","Orthogonale Testung kann systematische Assaygrenzen besser adressieren.":"El estudio ortogonal puede abordar mejor las limitaciones sistemáticas del ensayo.","ca. 45 %":"aprox. 45 %","Panel-QC":"QC del panel","global valide":"globalmente válido","Lokale QC":"QC local","EGFR-Exon 20 unter laborintern validierter Mindest-Coverage":"Exón 20 de EGFR por debajo de la cobertura mínima validada por el laboratorio","Restmaterial vorhanden, aber nicht unbegrenzt.":"Hay material residual, pero no es ilimitado.","Zeitkritische Therapieentscheidung.":"Decisión terapéutica urgente.","Der lokale Coverage-Grenzwert ist assay- und laborvalidiert; es wird kein universeller Zahlenwert postuliert.":"El umbral local de cobertura está validado para el ensayo y el laboratorio; no se postula un valor numérico universal.","Welche Aussage ist bei hoher Median-Coverage, aber unzureichender Coverage eines therapieentscheidenden Exons korrekt?":"¿Qué afirmación es correcta cuando la cobertura mediana es alta pero la cobertura de un exón decisivo para el tratamiento es insuficiente?","Der Run kann global valide sein, während dieses Exon nicht sicher negativ befundbar ist.":"El run puede ser globalmente válido mientras este exón no puede informarse de forma fiable como negativo.","Hohe Median-Coverage macht alle Exons sicher negativ.":"Una cobertura mediana alta hace que todos los exones sean negativos con seguridad.","Der gesamte Run ist zwingend ungültig.":"Todo el run es necesariamente inválido.","Coverage ist nur für Forschungsdaten relevant.":"La cobertura solo es relevante para datos de investigación.","Aussagefähigkeit wird zielregionsbezogen bewertet.":"La interpretabilidad se evalúa a nivel de región diana.","Wie sollte die Limitation berichtet werden?":"¿Cómo debe informarse la limitación?","Die betroffene Region ausdrücklich als nicht ausreichend beurteilt kennzeichnen und Nachtestung empfehlen.":"Indicar explícitamente que la región afectada no se ha evaluado suficientemente y recomendar un reanálisis.","Gesamtbefund schlicht „negativ“ nennen.":"Llamar simplemente «negativo» al resultado global. ","Coverage nur intern dokumentieren.":"Documentar la cobertura solo internamente.","Direkt eine Therapie ausschließen.":"Excluir directamente una opción terapéutica.","Die klinische Aussage darf die analytische Leistung nicht überschreiten.":"La afirmación clínica no debe exceder el rendimiento analítico.","Was ist bei einem reproduzierbaren lokalen Assay-Dropout besonders sinnvoll?":"¿Qué es especialmente adecuado ante un dropout local reproducible del ensayo?","Eine unabhängig validierte Methode für die Zielregion einsetzen.":"Utilizar un método validado de forma independiente para la región diana.","Den identischen Assay beliebig oft wiederholen.":"Repetir el ensayo idéntico tantas veces como se quiera.","Nur ein größeres Panel bestellen, ohne die Zielabdeckung zu prüfen.":"Solicitar solo un panel más amplio sin comprobar la cobertura de la diana.","Keine weitere Abklärung.":"Ninguna aclaración adicional.","Eine methodisch unabhängige Lösung adressiert systematische Grenzen besser.":"Una solución metodológicamente independiente aborda mejor las limitaciones sistemáticas.","Die orthogonale Methode weist eine EGFR-Exon-20-Insertion nach. Was war der ursprüngliche Fehler?":"El método ortogonal detecta una inserción en el exón 20 de EGFR. ¿Cuál fue el error original?","Ein nicht ausreichend untersuchter Bereich wurde wie ein sicher negativer Bereich behandelt.":"Una región insuficientemente estudiada se trató como si fuera negativa con seguridad.","Der gesamte NGS-Run war zwingend wertlos.":"Todo el run de NGS era necesariamente inútil.","Die Histologie war falsch.":"La histología era incorrecta.","Es wurde eine Keimbahnvariante übersehen.":"Se pasó por alto una variante germinal.","Der Fehler lag in der Reichweite der Negativaussage.":"El error estaba en el alcance de la afirmación negativa.","Entscheiden Sie, wie der Panelbefund freigegeben wird und wie die offene Zielregion methodisch geschlossen wird.":"Decida cómo liberar el resultado del panel y cómo cerrar metodológicamente la región diana pendiente.","Coverage-Report auf therapieentscheidende Regionen prüfen.":"Revisar el informe de cobertura en las regiones decisivas para el tratamiento.","Lokale Limitation explizit formulieren.":"Formular explícitamente la limitación local.","Nicht den gesamten Run verwerfen, wenn der Rest valide ist.":"No descartar todo el run si el resto es válido.","Gezielte orthogonale oder technisch geeignete Wiederholungsstrategie wählen.":"Elegir una estrategia ortogonal dirigida o una repetición técnicamente adecuada.","Endbefund nach Nachtestung aktualisieren.":"Actualizar el informe final tras el reanálisis.","Wiederholung des Panels kann vertretbar sein, wenn die Ursache plausibel zufällig/librarybezogen ist und das Wiederholungsdesign die Zielregion zuverlässig abdeckt.":"Repetir el panel puede ser razonable si la causa es plausiblemente aleatoria/relacionada con la library y el diseño de repetición cubre de forma fiable la región diana.","„Panel negativ“ trotz Coverage-Loch":"«Panel negativo» pese a una brecha de cobertura","Überdehnt die analytische Aussage.":"Excede el alcance analítico.","Run komplett verwerfen":"Descartar todo el run","Ignoriert, dass die übrigen Regionen valide sein können.":"Ignora que las demás regiones pueden ser válidas.","Blind identisch wiederholen":"Repetir de forma idéntica a ciegas","Kann systematische Dropouts reproduzieren.":"Puede reproducir dropouts sistemáticos.","Die rote Zeile war der eigentliche Befund":"La línea roja era el verdadero hallazgo","Die gezielte unabhängige Nachtestung weist eine EGFR-Exon-20-Insertion nach.":"El reanálisis dirigido e independiente detecta una inserción en el exón 20 de EGFR.","Der Fall zeigt, dass analytische Nichtbeurteilbarkeit klinisch relevanter sein kann als ein langer negativer Variantenbericht.":"El caso muestra que la no evaluabilidad analítica puede ser clínicamente más relevante que un largo informe de variantes negativas.","Limitiert + gezielt geschlossen":"Limitado + resuelto de forma dirigida","Lokale Limitation erkannt, orthogonal nachgetestet, relevante Alteration gefunden.":"Limitación local reconocida, reanalizada de forma ortogonal, alteración relevante encontrada.","Vollständige analytische und klinische Einordnung.":"Interpretación analítica y clínica completa.","Falsch-negativ freigegeben":"Liberado como falso negativo","Coverage-Loch wird ignoriert und die Region als negativ berichtet.":"Se ignora la brecha de cobertura y la región se informa como negativa.","Kritischer Scope-Fehler.":"Error crítico de alcance.","Ganzer Run verworfen":"Todo el run descartado","Valide übrige Ergebnisse werden unnötig wiederholt.":"Se repiten innecesariamente otros resultados válidos.","Unnötiger Material-/TAT-Verlust.":"Pérdida innecesaria de material/TAT.","Coverage unter validiertem Kriterium":"Cobertura por debajo del criterio validado","Zielregion als nicht sicher beurteilbar kennzeichnen":"Indicar que la región diana no puede evaluarse con fiabilidad","Nachtestung erforderlich, wenn klinisch relevant.":"Se requiere reanálisis si es clínicamente relevante.","Coverage ist lokal.":"La cobertura es local.","Negativbefunde brauchen nachgewiesene analytische Aussagefähigkeit.":"Los resultados negativos requieren una interpretabilidad analítica demostrada.","Limitationen gehören in die klinische Kernaussage, nicht nur in interne QC.":"Las limitaciones deben figurar en la afirmación clínica central, no solo en el QC interno.","Der Run bleibt für ausreichend abgedeckte Regionen valide. EGFR-Exon 20 ist nicht sicher negativ befundbar und muss explizit limitiert sowie gezielt nachuntersucht werden; eine unabhängige Methode schließt die diagnostische Lücke.":"El run sigue siendo válido para las regiones suficientemente cubiertas. El exón 20 de EGFR no puede informarse de forma fiable como negativo y debe limitarse explícitamente y reanalizarse de forma dirigida; un método independiente cierra la brecha diagnóstica.","Target-spezifische QC":"QC específico de la diana","Befundsprache":"Lenguaje del informe","Nachteststrategie":"Estrategia de reanálisis","Wann reicht eine NGS-Wiederholung?":"¿Cuándo basta con repetir el NGS?","Welche Coverage-Metriken müssen im Labor validiert sein?":"¿Qué métricas de cobertura deben validarse en el laboratorio?","Wie formuliert man Negativbefunde bei partieller Nichtbeurteilbarkeit?":"¿Cómo se redactan los resultados negativos cuando una parte del ensayo no es evaluable?","Twist: relevanter Befund liegt in der QC, nicht in der Variantenliste":"Twist: el hallazgo relevante está en el QC, no en la lista de variantes","Kernfehler: nicht ausreichend untersucht ≠ negativ":"Error central: insuficientemente evaluado ≠ negativo","Referenzpfad: Coverage prüfen → limitieren → gezielt schließen":"Ruta de referencia: revisar cobertura → indicar limitación → cerrar la brecha de forma dirigida","1,4 % EGFR-T790M im FFPE: Resistenzmutation oder Desaminierungsartefakt?":"EGFR T790M al 1,4 % en FFPE: ¿mutación de resistencia o artefacto de desaminación?","FFPE-C>T-Artefakt bei niedriger VA…":"Artefacto FFPE C>T con VAF baja…","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress unter zielgerichteter Therapie. In einer kleinen FFPE-Rebiopsie wird zusätzlich EGFR p.T790M mit 1,4 % VAF gemeldet.":"Paciente de 67 años con NSCLC mutado en EGFR y progresión bajo terapia dirigida. En una pequeña rebiopsia FFPE se informa además EGFR p.T790M con VAF del 1,4 %.","Ist die niedrigfrequente C>T-Variante als echte Resistenzsubpopulation belastbar oder zunächst artefaktverdächtig?":"¿Es fiable la variante C>T de baja frecuencia como verdadera subpoblación resistente o debe considerarse inicialmente sospechosa de artefacto?","Therapiewechsel soll kurzfristig festgelegt werden.":"El cambio de tratamiento debe decidirse a corto plazo.","Primärtreiber":"Driver primario","Bekannte klonale EGFR-aktivierende Mutation mit hoher VAF wird in der Rebiopsie erneut nachgewiesen.":"La mutación activadora clonal conocida de EGFR, con VAF alta, vuelve a detectarse en la rebiopsia.","Neue Variante":"Nueva variante","EGFR p.T790M, 1,4 % VAF, nur knapp oberhalb der technischen Reporting-Grenze.":"EGFR p.T790M, VAF del 1,4 %, apenas por encima del umbral técnico de informe.","Kleine Biopsie, lange Formalinfixierung; DNA zeigt deutliche Fragmentierung.":"Biopsia pequeña, fijación prolongada en formol; el ADN muestra fragmentación marcada.","Actionability des Gens wird mit analytischer Validität des einzelnen Calls verwechselt.":"Se confunde la accionabilidad del gen con la validez analítica del call individual.","Vitales Adenokarzinom, Tumoranteil ca. 30 %.":"Adenocarcinoma viable, contenido tumoral aprox. 30 %.","Sequenzdaten":"Datos de secuenciación","T790M vorwiegend in einem Strang-/Endkontext, niedrige Molekülzahl; mehrere weitere sehr niedrige C>T/G>A-Ereignisse.":"T790M predominantemente en un contexto de hebra/extremo, bajo número de moléculas; varios eventos C>T/G>A adicionales de nivel muy bajo.","Echte Subklonmutation oder FFPE-bedingte Cytosindesaminierung?":"¿Mutación subclonal real o desaminación de citosina relacionada con FFPE?","Ein klinisch attraktiver Call verdient nicht weniger, sondern mehr QC.":"Un call clínicamente atractivo merece más QC, no menos.","FFPE-Stanzbiopsie, nur wenige Restrollen.":"Biopsia con aguja gruesa FFPE, con solo unas pocas secciones restantes disponibles.","stark fragmentiert.":"muy fragmentado.","Alternative":"Alternativa","zweite Extraktion aus tieferen Schnitten möglich.":"es posible una segunda extracción a partir de cortes más profundos.","Orthogonale Bestätigung gezielt möglich.":"Es posible una confirmación ortogonal dirigida.","FFPE-Artefaktprüfung":"Evaluación de artefactos FFPE","Niedrigfrequenten klinisch relevanten Call bestätigen":"Confirmar un call clínicamente relevante de baja frecuencia","Artefaktreview":"Revisión de artefactos","Der Call zeigt typische Warnsignale: sehr niedrige VAF, geringe unabhängige Molekülzahl, ungünstiger Strang-/Read-End-Kontext und zusätzliche niedrigfrequente C>T/G>A-Ereignisse im stark fragmentierten FFPE-Material.":"El call muestra señales de alarma típicas: VAF muy baja, pocas moléculas independientes, contexto desfavorable de hebra/extremo de lectura y eventos C>T/G>A adicionales de baja frecuencia en material FFPE muy fragmentado.","Orthogonale Bestätigung":"Confirmación ortogonal","In einer unabhängigen Extraktion und orthogonalen Zielmethode ist p.T790M nicht reproduzierbar, während die bekannte klonale EGFR-Mutation stabil nachweisbar bleibt. Gesamtbild spricht für FFPE-Artefakt.":"En una extracción independiente y con un método dirigido ortogonal, p.T790M no es reproducible, mientras que la mutación clonal conocida de EGFR sigue detectándose de forma estable. En conjunto, el patrón favorece un artefacto FFPE.","Mehr Sequenzierbreite ersetzt die gezielte analytische Prüfung des grenzwertigen Calls nicht.":"Una mayor amplitud de secuenciación no sustituye la evaluación analítica dirigida del call limítrofe.","Stark fragmentierte FFPE-DNA mit erhöhtem Risiko niedrigfrequenter Desaminierungsartefakte.":"ADN FFPE muy fragmentado con mayor riesgo de artefactos de desaminación de baja frecuencia.","Niedrige VAF allein beweist weder Artefakt noch Subklon; Muster, Reproduzierbarkeit und Assay-QC entscheiden.":"Una VAF baja por sí sola no demuestra ni artefacto ni subclon; son decisivos el patrón, la reproducibilidad y el QC del ensayo.","Die klinisch relevante C>T-Variante liegt in einem stark artefaktanfälligen FFPE-Kontext und ist nicht unabhängig reproduzierbar. Sie darf daher nicht als gesicherte Resistenzmutation berichtet werden; die bekannte klonale EGFR-Alteration bleibt dagegen robust nachweisbar.":"La variante C>T clínicamente relevante aparece en un contexto FFPE muy propenso a artefactos y no es reproducible de forma independiente. Por tanto, no debe informarse como mutación de resistencia confirmada; en cambio, la alteración clonal conocida de EGFR sigue detectándose de forma robusta.","Teilbefund: Eine niedrigfrequente C>T-Variante in stark geschädigter FFPE-DNA muss vor therapeutischer Interpretation auf Artefaktmuster und Reproduzierbarkeit geprüft werden.":"Resultado parcial: una variante C>T de baja frecuencia en ADN FFPE muy dañado debe evaluarse por patrón de artefacto y reproducibilidad antes de una interpretación terapéutica.","Desaminierungsartefakte als Differenzialdiagnose nennen":"Mencionar los artefactos de desaminación como explicación diferencial","VAF nicht isoliert interpretieren":"No interpretar el VAF de forma aislada","klinisch relevanten Low-VAF-Call unabhängig bestätigen":"Confirmar de forma independiente un call clínicamente relevante con VAF baja","Falschaussage: therapierbares Gen macht jeden Low-VAF-Call automatisch echt":"Afirmación falsa: un gen accionable hace que cualquier call con VAF baja sea automáticamente real","Optimale Lösung: Low-VAF-C>T-Call im FFPE-Kontext kritisch prüfen, technische Artefaktmerkmale berücksichtigen und vor Therapieableitung unabhängig bestätigen.":"Solución óptima: evaluar críticamente el call C>T de baja VAF en el contexto FFPE, considerar las características técnicas de artefacto y confirmarlo de forma independiente antes de extraer implicaciones terapéuticas.","FFPE":"FFPE","Artefakt":"Artefacto","Low VAF":"VAF baja","Der attraktive 1,4-%-Call":"El atractivo call del 1,4 %","Molekularpathologie / NGS-QC / MTB":"Patología molecular / QC de NGS / MTB","FFPE-bedingte C>T/G>A-Artefakte als analytische Differenzialdiagnose erkennen.":"Reconocer los artefactos C>T/G>A relacionados con FFPE como diagnóstico diferencial analítico.","VAF, Molekülzahl, Strang-/Read-Kontext und Reproduzierbarkeit gemeinsam bewerten.":"Evaluar conjuntamente VAF, número de moléculas, contexto de hebra/lectura y reproducibilidad.","Klinische Relevanz nicht mit analytischer Validität verwechseln.":"No confundir relevancia clínica con validez analítica.","Low-VAF-Calls vor weitreichender Therapieableitung angemessen bestätigen.":"Confirmar adecuadamente los calls con VAF baja antes de decisiones terapéuticas de gran alcance.","Auf dem Variantenboard leuchtet EGFR p.T790M. VAF 1,4 %. Klinisch wäre der Befund wichtig – analytisch sieht er aber genau so aus, wie ein alter FFPE-Block Probleme machen kann.":"En el panel de variantes aparece EGFR p.T790M. VAF 1,4 %. Clínicamente sería un hallazgo importante, pero analíticamente tiene exactamente el aspecto de un problema que puede generar un bloque FFPE antiguo.","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress. In einer kleinen, stark fragmentierten Rebiopsie erscheint ein neuer C>T-Call knapp oberhalb der Reporting-Grenze. Das Board muss entscheiden, ob dies ein echter Resistenzklon ist.":"Paciente de 67 años con NSCLC mutado en EGFR y progresión. En una rebiopsia pequeña y muy fragmentada aparece un nuevo call C>T justo por encima del umbral de informe. El comité debe decidir si se trata de un subclon real de resistencia.","Actionability ist kein QC-Kriterium":"La accionabilidad no es un criterio de QC","Ein therapeutisch interessanter Genname macht einen Call nicht analytisch wahr.":"Un nombre de gen terapéuticamente interesante no convierte un call en analíticamente verdadero.","Analytische Validität kommt vor klinischer Interpretation.":"La validez analítica precede a la interpretación clínica.","FFPE-Muster":"Patrón FFPE","Mehrere sehr niedrige C>T/G>A-Ereignisse und fragmentierte DNA erhöhen den Artefaktverdacht.":"Varios eventos C>T/G>A a niveles muy bajos y ADN fragmentado aumentan la sospecha de artefacto.","Muster ist informativer als eine einzelne VAF.":"El patrón es más informativo que un único VAF.","Unabhängige Reproduzierbarkeit":"Reproducibilidad independiente","Eine zweite Extraktion/orthogonale Methode kann einen grenzwertigen Call stabilisieren oder entkräften.":"Una segunda extracción/método ortogonal puede respaldar o refutar un call limítrofe.","Bestätigung sollte möglichst methodisch unabhängig sein.":"La confirmación debe ser metodológicamente independiente siempre que sea posible.","Bekannter Treiber":"Driver conocido","klonale EGFR-aktivierende Mutation robust nachweisbar":"mutación activadora clonal de EGFR detectada de forma robusta","Neuer Call":"Nuevo call","EGFR p.T790M, 1,4 % VAF":"EGFR p.T790M, VAF 1,4 %","FFPE-QC":"QC FFPE","stark fragmentiert; weitere sehr niedrige C>T/G>A-Ereignisse":"muy fragmentado; eventos C>T/G>A adicionales a niveles muy bajos","Wenig Restmaterial.":"Poco material restante.","Der Fall postuliert keine universelle VAF-Grenze; entscheidend ist die laborvalidierte Performance im konkreten Assay.":"El caso no plantea un umbral universal de VAF; lo decisivo es el rendimiento validado en el laboratorio del ensayo concreto.","Was ist der erste richtige Schritt bei einem klinisch relevanten 1,4-%-C>T-Call in stark geschädigtem FFPE?":"¿Cuál es el primer paso correcto ante un call C>T clínicamente relevante del 1,4 % en material FFPE muy dañado?","Call-level QC und FFPE-Artefaktmuster prüfen.":"Revisar el QC a nivel de call y el patrón de artefacto FFPE.","Sofort Therapie ableiten.":"Derivar tratamiento inmediatamente.","Jede Variante unter 5 % grundsätzlich verwerfen.":"Descartar por norma cualquier variante por debajo del 5 %.","Keimbahntestung veranlassen.":"Solicitar estudio germinal.","Es gibt keine universelle VAF-Regel; der Call muss assay- und kontextbezogen validiert werden.":"No existe una regla universal de VAF; el call debe validarse en función del ensayo y del contexto.","Welche Befunde erhöhen hier den Artefaktverdacht?":"¿Qué hallazgos aumentan aquí la sospecha de artefacto?","sehr niedrige VAF/geringe Molekülzahl":"VAF muy baja/pocas moléculas","mehrere niedrigfrequente C>T/G>A-Ereignisse":"múltiples eventos C>T/G>A de baja frecuencia","stark fragmentierte FFPE-DNA":"ADN FFPE muy fragmentado","bekannte klonale Treibermutation ist robust":"la mutación driver clonal conocida es robusta","Die Kombination aus FFPE-Schaden und typischem Substitutionsmuster ist verdächtig.":"La combinación de daño FFPE y un patrón típico de sustituciones resulta sospechosa.","Was erhöht die Sicherheit vor therapeutischer Interpretation am stärksten?":"¿Qué aumenta más la confianza antes de la interpretación terapéutica?","Unabhängige Extraktion und/oder orthogonale validierte Zielmethode.":"Extracción independiente y/o método dirigido ortogonal validado.","Längere Literaturrecherche ohne analytische Prüfung.":"Una búsqueda bibliográfica más extensa sin evaluación analítica.","Den gleichen Report erneut öffnen.":"Volver a abrir el mismo informe.","Nur die Therapierbarkeit des Gens bewerten.":"Valorar únicamente si el gen es tratable como diana.","Reproduzierbarkeit adressiert die analytische Kernfrage.":"La reproducibilidad aborda la cuestión analítica central.","T790M ist unabhängig nicht reproduzierbar, der bekannte klonale EGFR-Treiber schon. Wie ist das Gesamtbild?":"T790M no es reproducible de forma independiente, pero el driver clonal conocido de EGFR sí. ¿Cómo debe interpretarse el conjunto?","Der neue Low-VAF-Call ist nicht gesichert und im Kontext am ehesten artefaktbedingt.":"El nuevo call de baja VAF no está confirmado y, en este contexto, es muy probablemente un artefacto.","T790M ist trotzdem sicher echt.":"T790M sigue siendo definitivamente real.","Auch der bekannte EGFR-Treiber ist damit falsch.":"Por tanto, el driver conocido de EGFR también debe ser falso.","Der Unterschied ist ohne Bedeutung.":"La diferencia no tiene importancia.","Selektive Nichtreproduzierbarkeit plus Artefaktmuster entkräftet den grenzwertigen Call.":"La falta selectiva de reproducibilidad, junto con el patrón de artefacto, debilita el call limítrofe.","Bewerten Sie, ob der Low-VAF-Call als gesichert berichtet und therapeutisch verwendet werden darf.":"Valore si el call de baja VAF puede informarse como confirmado y utilizarse terapéuticamente.","FFPE-Qualität und Substitutionsmuster prüfen.":"Revisar la calidad FFPE y el patrón de sustituciones.","Call-level Evidenz bewerten.":"Evaluar la evidencia a nivel de call.","Low-VAF nicht pauschal verwerfen, aber bei hoher Konsequenz bestätigen.":"No descartar categóricamente una VAF baja, pero confirmarla cuando la consecuencia clínica sea importante.","Unabhängige Reproduzierbarkeit einbeziehen.":"Incorporar la reproducibilidad independiente en la evaluación.","Nur robuste Befunde in die Therapiekernaussage aufnehmen.":"Incluir solo hallazgos robustos en la conclusión terapéutica principal.","Bei sehr gut validiertem ultrasensitivem Assay und überzeugender unabhängiger Molekülevidenz kann ein niedriger VAF real sein; der Fall lehrt keine starre Prozentgrenze.":"Con un ensayo ultrasensible bien validado y evidencia molecular independiente convincente, una VAF baja puede ser real; el caso no enseña un umbral porcentual rígido.","<5 % = immer Artefakt":"<5 % = siempre artefacto","Ignoriert echte Subklone und assayspezifische Nachweisgrenzen.":"Ignora subclones reales y límites de detección específicos del ensayo.","Actionable = echt":"Accionable = real","Verwechselt klinische mit analytischer Evidenz.":"Confunde evidencia clínica con evidencia analítica.","Breites Re-Panel statt Call-QC":"Repetir un panel amplio en lugar de QC a nivel de call","Mehr Daten lösen den konkreten Artefaktverdacht nicht automatisch.":"Más datos no resuelven automáticamente la sospecha concreta de artefacto.","Die Resistenzmutation verschwindet":"La mutación de resistencia desaparece","In unabhängiger Extraktion und orthogonaler Zielmethode ist T790M nicht reproduzierbar, der klonale Primärtreiber jedoch stabil.":"En una extracción independiente y con un método dirigido ortogonal, T790M no es reproducible, mientras que el driver clonal primario permanece estable.","Der attraktivste Befund des Reports ist nicht der belastbarste.":"El hallazgo más atractivo del informe no es el más robusto.","Low-VAF korrekt entkräftet":"La llamada de VAF baja se descartó correctamente","Artefaktmuster erkannt und Call unabhängig nicht bestätigt.":"Se reconoció un patrón de artefacto y la llamada no se confirmó de forma independiente.","Therapeutisches Overcalling vermieden.":"Se evitó la sobreinterpretación terapéutica.","Direkt als Resistenzmutation berichtet":"Informada directamente como mutación de resistencia","Ein grenzwertiger FFPE-Call steuert die Therapie.":"Una llamada FFPE limítrofe determina la decisión terapéutica.","Analytische Evidenz unzureichend.":"La evidencia analítica es insuficiente.","Pauschal unter 5 % verworfen":"Descartada automáticamente por debajo del 5 %","Der richtige Ausgang wird aus der falschen Regel abgeleitet.":"Se llega al resultado correcto aplicando una regla equivocada.","Keine universelle VAF-Grenze verwenden.":"No utilice un umbral universal de VAF.","klinisch relevanter Low-VAF-Call + Artefaktmuster":"llamada de VAF baja clínicamente relevante + patrón de artefacto","analytische Bestätigung vor finaler Therapieaussage":"confirmación analítica antes de la conclusión terapéutica final","Bei Nichtbestätigung nicht als gesicherte Resistenzmutation berichten.":"Si no se confirma, no debe informarse como una mutación de resistencia establecida.","FFPE-Artefakte sind call- und kontextabhängig.":"Los artefactos FFPE dependen de la llamada y del contexto.","Niedrige VAF ist ein Warnsignal, kein Urteil.":"Una VAF baja es una señal de alerta, no un veredicto.","Je größer die klinische Konsequenz, desto wichtiger die analytische Absicherung.":"Cuanto mayor sea la consecuencia clínica, más importante es la confirmación analítica.","Der T790M-Call ist aufgrund des FFPE-Musters und fehlender unabhängiger Reproduzierbarkeit nicht gesichert; keine Therapieentscheidung allein darauf stützen.":"La llamada T790M no está confirmada debido al patrón de artefacto FFPE y a la falta de reproducibilidad independiente; no debe basarse una decisión terapéutica únicamente en ella.","Low-VAF-Interpretation":"Interpretación de VAF baja","Bestätigung":"Confirmación","Welche Artefaktmuster sind plattformabhängig?":"¿Qué patrones de artefacto dependen de la plataforma?","Wann ist eine zweite Extraktion sinnvoll?":"¿Cuándo es útil una segunda extracción?","Wie dokumentiert man nicht bestätigte Calls?":"¿Cómo deben documentarse las llamadas no confirmadas?","Twist: klinisch attraktivster Call ist analytisch schwächster":"Giro: la llamada más atractiva clínicamente es la más débil analíticamente","Keine starre VAF-Grenze":"Sin umbral rígido de VAF","Referenzpfad: Call-QC → Artefaktmuster → unabhängige Bestätigung":"Ruta de referencia: QC de la llamada → patrón de artefacto → confirmación independiente","Tumor-only BRCA2 bei 48 % VAF: therapeutisch relevant, Keimbahn trotzdem offen":"BRCA2 tumor-only con VAF del 48 %: relevante terapéuticamente, el origen germinal sigue sin resolverse","Tumor-only NGS: Keimbahnverdacht B…":"NGS tumor-only: sospecha de variante germinal B…","61-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom. Tumor-only NGS zeigt eine pathogene truncierende BRCA2-Variante mit 48 % VAF.":"Paciente de 61 años con cáncer de próstata metastásico resistente a la castración. El NGS tumor-only muestra una variante truncante patogénica de BRCA2 con VAF del 48 %.","Darf aus VAF und Gen direkt auf eine Keimbahnmutation geschlossen werden – und wie werden therapeutische und hereditäre Konsequenzen getrennt?":"¿Puede inferirse directamente una mutación germinal solo por el VAF y el gen, y cómo deben separarse las consecuencias terapéuticas de las hereditarias?","Systemische Therapieentscheidung und genetische Beratung sollen parallel geplant werden.":"La planificación del tratamiento sistémico y el asesoramiento genético deben realizarse en paralelo.","Schwester mit Mammakarzinom mit 46 Jahren, Vater mit Prostatakarzinom mit 58 Jahren.":"Hermana con cáncer de mama a los 46 años, padre con cáncer de próstata a los 58 años.","Tumorprofil":"Perfil tumoral","Pathogene BRCA2-Trunkierung; Tumorreinheit und Kopienzahl machen eine Herkunft aus der VAF allein nicht eindeutig.":"Truncación patogénica de BRCA2; la pureza tumoral y el número de copias impiden determinar el origen de la variante solo por el VAF.","„ungefähr 50 %“ wird mit „Keimbahn bewiesen“ gleichgesetzt.":"Se equipara «aproximadamente 50 %» con «germinal demostrado».","Tumorbiomarker und hereditäre Diagnostik sauber entkoppeln und dann wieder integrieren.":"Separar con claridad el biomarcador tumoral del diagnóstico hereditario y, después, volver a integrar ambos niveles.","Metastasiertes Prostataadenokarzinom.":"Adenocarcinoma de próstata metastásico.","BRCA2 pathogene Loss-of-function-Variante, VAF 48 %.":"Variante patogénica loss-of-function de BRCA2, VAF del 48 %.","somatisch, Keimbahn oder beides im Tumorkontext?":"¿somática, germinal o ambas en el contexto tumoral?","Tumorreinheit, LOH und Copy-number können VAF deutlich verschieben.":"La pureza tumoral, la LOH y el número de copias pueden desplazar de forma importante el VAF.","FFPE-Metastase für Tumorprofil; EDTA-Blut für bestätigende Keimbahndiagnostik verfügbar.":"Metástasis FFPE para perfil tumoral; sangre EDTA disponible para confirmación germinal.","ca. 60 %.":"aprox. 60 %.","Consent":"Consentimiento","Genetische Beratung/Einwilligung für Keimbahndiagnostik erforderlich.":"Para el estudio germinal se requieren asesoramiento genético y consentimiento.","Tumor-normal bzw. gezielte Keimbahnbestätigung möglich.":"Es posible realizar análisis tumor-normal o confirmación germinal dirigida.","Tumor-BRCA/HRR einordnen":"Interpretar BRCA/HRR tumoral","Potenzielle Keimbahn separat klären":"Aclarar por separado un posible origen germinal","Pathogene BRCA2-Loss-of-function-Variante im Tumor; für die tumorbezogene Therapieentscheidung relevant, ohne damit die Keimbahnherkunft zu beweisen.":"Variante patogénica loss-of-function de BRCA2 en el tumor; relevante para el tratamiento dirigido al tumor sin demostrar origen germinal.","Die pathogene BRCA2-Variante wird im konstitutionellen Material bestätigt: Keimbahnmutation. Der Tumor-only-Befund war ein Hinweis, nicht der Beweis.":"La variante patogénica de BRCA2 se confirma en material constitucional: mutación germinal. El hallazgo tumor-only fue una pista, no una prueba.","Humangenetische Beratung":"Asesoramiento genético","Genetische Beratung wird veranlasst; hereditäre Konsequenzen werden außerhalb des reinen Tumorbefunds adressiert.":"Se organiza asesoramiento genético; las implicaciones hereditarias se abordan fuera del informe tumor-only.","Tumor-only":"Tumor-only","Ohne Normalprobe kann die Herkunft einer Variante nicht allein aus der VAF sicher bestimmt werden.":"Sin una muestra normal, el origen de una variante no puede determinarse de forma fiable solo por el VAF.","Therapeutische Tumorrelevanz und hereditäre Bedeutung sind getrennte Fragestellungen.":"La relevancia terapéutica tumoral y el significado hereditario son cuestiones distintas.","Die pathogene BRCA2-Variante ist im Tumor therapeutisch relevant, aber Tumor-only Sequenzierung beweist keine Keimbahnherkunft. VAF um 50 % erhöht den Verdacht, ist wegen Tumorreinheit, LOH und Copy-number jedoch nicht beweisend. Die bestätigende Analyse im konstitutionellen Material zeigt hier tatsächlich eine Keimbahnmutation.":"La variante patogénica de BRCA2 es terapéuticamente relevante en el tumor, pero la secuenciación tumor-only no demuestra un origen germinal. Un VAF cercano al 50 % aumenta la sospecha, pero no es concluyente debido a la pureza tumoral, la LOH y el número de copias. En este caso, el análisis confirmatorio en material constitucional demuestra una mutación germinal.","Teilbefund: Ein Tumor-only BRCA2-Befund kann therapeutisch relevant sein und gleichzeitig eine separate Keimbahnabklärung auslösen; die VAF allein entscheidet die Herkunft nicht.":"Resultado parcial: un hallazgo BRCA2 tumor-only puede ser terapéuticamente relevante y, al mismo tiempo, indicar un estudio germinal separado; el VAF por sí solo no determina el origen.","Tumoractionability separat bewerten":"Evaluar por separado la accionabilidad tumoral","Keimbahnverdacht separat adressieren":"Abordar por separado la sospecha de origen germinal","VAF nicht als Herkunftsbeweis verwenden":"No utilizar el VAF como prueba del origen","Falschaussage: 48–50 % VAF im Tumor beweist Keimbahn":"Afirmación falsa: un VAF del 48–50 % en tumor demuestra origen germinal","Optimale Lösung: Tumorbefund therapeutisch einordnen, Keimbahnverdacht transparent markieren und mit konstitutionellem Material/genetischer Beratung bestätigen.":"Solución óptima: interpretar terapéuticamente el hallazgo tumoral, señalar de forma transparente la sospecha de origen germinal y confirmarla con material constitucional/asesoramiento genético.","48 % sind kein Abstammungsnachweis":"El 48 % no demuestra el origen germinal","Molekulares Tumorboard / Humangenetik-Schnittstelle":"Interfaz Comité Molecular de Tumores / Genética","Tumor-only NGS nicht mit Keimbahndiagnostik gleichsetzen.":"No equiparar el NGS tumor-only con el diagnóstico germinal.","VAF nur als Hinweis und nie isoliert als Herkunftsbeweis nutzen.":"Utilizar el VAF solo como indicio y nunca de forma aislada como prueba del origen.","Tumorbezogene Therapieinformation und hereditäre Konsequenzen getrennt bearbeiten.":"Abordar por separado la información terapéutica tumoral y las implicaciones hereditarias.","Bestätigende Keimbahndiagnostik mit geeigneter Beratung/Einwilligung veranlassen.":"Solicitar estudio germinal confirmatorio con asesoramiento/consentimiento adecuados.","BRCA2, pathogene Trunkierung, VAF 48 %. Der Report sieht „keimbahnverdächtig“ aus – aber 48 % im Tumor sind keine Blutprobe. Genau hier muss das Board zwei richtige Aussagen gleichzeitig halten.":"BRCA2, variante truncante patogénica, VAF 48 %. El informe parece «sugestivo de origen germinal», pero un 48 % en tumor no es una muestra de sangre. Aquí el comité debe sostener dos afirmaciones correctas al mismo tiempo.","61-jähriger Patient mit mCRPC und pathogener BRCA2-Variante im Tumor-only Panel. Der Befund kann therapeutisch relevant sein. Wegen VAF und Familienanamnese besteht zusätzlich Keimbahnverdacht, der separat bestätigt werden muss.":"Paciente de 61 años con mCRPC y una variante patogénica de BRCA2 en un panel tumor-only. El hallazgo puede ser terapéuticamente relevante. El VAF y los antecedentes familiares añaden sospecha de origen germinal, que debe confirmarse por separado.","VAF ist modellabhängig":"El VAF depende del modelo/contexto","Tumorreinheit, LOH, Amplifikation/Deletion und Klonalität verschieben die beobachtete VAF.":"La pureza tumoral, la LOH, la amplificación/deleción y la clonalidad pueden modificar el VAF observado.","50 % ist kein magischer Keimbahn-Cutoff.":"El 50 % no es un umbral mágico de origen germinal.","Zwei Konsequenzachsen":"Dos ejes de consecuencias","Tumortherapie kann auf dem somatischen Befund beruhen; Familien-/Prädispositionsfragen brauchen Keimbahndiagnostik.":"El tratamiento tumoral puede basarse en el hallazgo somático; las cuestiones familiares/de predisposición requieren estudio germinal.","Dasselbe Gen erzeugt zwei unterschiedliche Workflows.":"El mismo gen genera dos flujos de trabajo distintos.","Tumor-only hat Grenzen":"El tumor-only tiene limitaciones","Ohne Normalprobe bleibt die Herkunft vieler Varianten unbestimmt.":"Sin una muestra normal, el origen de muchas variantes sigue sin resolverse.","Bericht und Beratung müssen das transparent machen.":"El informe y el asesoramiento deben dejarlo claro.","pathogene BRCA2-LoF, VAF 48 %":"BRCA2 LoF patogénica, VAF 48 %","frühes Mammakarzinom bei Schwester, Prostatakarzinom beim Vater":"cáncer de mama precoz en la hermana, cáncer de próstata en el padre","Normalprobe":"Muestra normal","noch nicht untersucht":"aún no estudiada","Konstitutionelles Material verfügbar.":"Hay material constitucional disponible.","Hereditäre Diagnostik erfordert eigenen Prozess/Einwilligung.":"El diagnóstico hereditario requiere un proceso/consentimiento separado.","Tumor-VAF wird im Kontext von Reinheit und Copy-number interpretiert.":"El VAF tumoral se interpreta en el contexto de la pureza y del número de copias.","Was beweist eine pathogene BRCA2-Variante mit 48 % VAF im Tumor-only Panel?":"¿Qué demuestra una variante patogénica de BRCA2 con VAF del 48 % en un panel tumor-only?","Sie ist keimbahnverdächtig, beweist aber ohne konstitutionelle Probe keine Keimbahnherkunft.":"Sugiere un posible origen germinal, pero no lo demuestra sin material constitucional.","Keimbahn ist sicher bewiesen.":"El origen germinal está demostrado con certeza.","Somatisch ist sicher bewiesen.":"El origen somático está demostrado con certeza.","Die Variante ist ein Artefakt.":"La variante es un artefacto.","Tumorreinheit und Copy-number verhindern einfache VAF-Herkunftsregeln.":"La pureza tumoral y el número de copias impiden aplicar reglas simples de origen basadas en el VAF.","Welche zwei Fragen müssen getrennt beantwortet werden?":"¿Qué dos preguntas deben responderse por separado?","Welche tumorbezogene therapeutische Bedeutung hat BRCA2?":"¿Qué significado terapéutico tumoral tiene BRCA2?","Liegt eine konstitutionelle pathogene Variante vor?":"¿Existe una variante patogénica constitucional?","Welche Farbe hat der Report?":"¿De qué color es el informe?","Reicht das Alter allein als Keimbahntest?":"¿Basta la edad por sí sola para un estudio germinal?","Therapie und Prädisposition sind gekoppelt, aber nicht identisch.":"Tratamiento y predisposición están relacionados, pero no son idénticos.","Wie wird die Keimbahnfrage belastbar geklärt?":"¿Cómo puede resolverse de forma fiable la cuestión germinal?","Analyse geeigneten konstitutionellen Materials im passenden genetischen Prozess.":"Analizar material constitucional adecuado dentro del proceso genético correspondiente.","Nur VAF erneut ansehen.":"Limitarse a revisar de nuevo el VAF.","Nur denselben Tumor erneut sequenzieren.":"Secuenciar de nuevo únicamente el mismo tumor.","Gar nicht; Tumor-only reicht.":"No hacer nada; el tumor-only es suficiente.","Die Herkunft braucht konstitutionellen Vergleich/Bestätigung.":"El origen requiere comparación/confirmación constitucional.","Die Variante wird im Blut bestätigt. Was ändert sich?":"La variante se confirma en sangre. ¿Qué cambia?","Zusätzlich zur Tumorrelevanz ist nun eine Keimbahnmutation bestätigt und hereditäre Konsequenzen können adressiert werden.":"Además de la relevancia tumoral, ahora se confirma una mutación germinal y pueden abordarse las implicaciones hereditarias.","Die Tumorrelevanz verschwindet.":"La relevancia tumoral desaparece.","Der Tumorbefund war falsch.":"El hallazgo tumoral era erróneo.","Es gibt keinerlei zusätzliche Konsequenz.":"No hay ninguna consecuencia adicional.","Die bestätigte Herkunft ergänzt den Tumorbefund um eine zweite klinische Dimension.":"El origen confirmado añade una segunda dimensión clínica al hallazgo tumoral.","Formulieren Sie Tumor- und Keimbahnaussage getrennt und definieren Sie den nächsten diagnostischen Schritt.":"Formular por separado la conclusión tumoral y la germinal y definir el siguiente paso diagnóstico.","Pathogene BRCA2-Variante im Tumor als tumorbezogenen Biomarker einordnen.":"Interpretar la variante patogénica de BRCA2 en el tumor como biomarcador tumoral.","VAF und Familienanamnese als Keimbahnverdacht, nicht Beweis, kommunizieren.":"Comunicar el VAF y los antecedentes familiares como elementos de sospecha germinal, no como prueba.","Konstitutionelle Testung/genetische Beratung veranlassen.":"Solicitar estudio constitucional/asesoramiento genético.","Nach Bestätigung hereditäre Ebene getrennt dokumentieren.":"Tras la confirmación, documentar por separado la dimensión hereditaria.","Je nach lokaler Struktur kann eine direkte Überweisung zur Humangenetik statt tumor-normal Analyse im selben Labor sinnvoll sein.":"Según la organización local, puede ser adecuado derivar directamente a genética en lugar de realizar un análisis tumor-normal en el mismo laboratorio.","48 % = Keimbahn":"48 % = germinal","VAF im Tumor hängt von Reinheit, LOH und Copy-number ab.":"El VAF tumoral depende de la pureza, la LOH y el número de copias.","Nur Therapie, Keimbahn ignorieren":"Solo tratamiento, ignorar lo germinal","Verpasst potenziell relevante Prädispositionsinformation.":"Omite información potencialmente relevante sobre predisposición.","Nur Keimbahn diskutieren":"Discutir solo lo germinal","Ignoriert die unmittelbare tumorbezogene Bedeutung.":"Ignora la relevancia tumoral inmediata.","Der Verdacht bestätigt sich – aber erst im richtigen Material":"La sospecha se confirma, pero solo en el material adecuado","Die BRCA2-Variante wird im konstitutionellen Material bestätigt.":"La variante de BRCA2 se confirma en material constitucional.","Der Fall zeigt den Unterschied zwischen einem starken Hinweis aus Tumor-only NGS und einem echten Keimbahnnachweis.":"El caso muestra la diferencia entre un indicio fuerte procedente de NGS tumor-only y una verdadera confirmación germinal.","Tumorrelevanz genutzt, Keimbahn separat bestätigt.":"Se utiliza la relevancia tumoral y el estado germinal se confirma por separado.","Vollständige Präzisionsonkologie plus Prädispositionslogik.":"Oncología de precisión completa más lógica de predisposición.","Keimbahn aus 48 % behauptet":"Se afirma origen germinal por un 48 %","Herkunft ohne Normalprobe overcallt.":"Se sobreinterpreta el origen sin una muestra normal.","Methodisch unzulässig.":"Metodológicamente inválido.","Keimbahnverdacht ignoriert":"Se ignora la sospecha germinal","Hereditäre Ebene bleibt ungeklärt.":"La dimensión hereditaria queda sin aclarar.","Unvollständige Nachsorge.":"Seguimiento incompleto.","pathogene Variante in Prädispositionsgen im Tumor-only Kontext":"variante patogénica en un gen de predisposición en contexto tumor-only","Keimbahnpotenzial bewerten und ggf. Bestätigung/Genetik veranlassen":"valorar el potencial germinal y solicitar confirmación/genética cuando proceda","Tumorbefund nicht als konstitutionellen Befund etikettieren.":"No etiquetar el hallazgo tumoral como hallazgo constitucional.","Tumor-only ist keine Keimbahndiagnostik.":"Tumor-only no equivale a diagnóstico germinal.","VAF ist ein Hinweis, kein Beweis.":"El VAF es un indicio, no una prueba.","Dasselbe Variantenergebnis kann therapeutische und hereditäre Konsequenzen parallel haben.":"El mismo resultado de variante puede tener consecuencias terapéuticas y hereditarias en paralelo.","Pathogene BRCA2-Variante im Tumor therapeutisch relevant; Keimbahnherkunft aus Tumor-only/VAF nicht beweisbar. Bestätigende konstitutionelle Diagnostik ist indiziert und zeigt hier eine Keimbahnmutation.":"La variante patogénica de BRCA2 en el tumor es terapéuticamente relevante; el origen germinal no puede demostrarse a partir de tumor-only/VAF. Está indicado un estudio constitucional confirmatorio, que en este caso demuestra una mutación germinal.","Tumor-only-Grenzen":"Limitaciones del tumor-only","VAF-Interpretation":"Interpretación del VAF","Keimbahnworkflow":"Flujo de trabajo germinal","Welche Gene lösen besonders häufig Keimbahn-Reflexfragen aus?":"¿Qué genes plantean con mayor frecuencia cuestiones reflejas de origen germinal?","Wie beeinflusst LOH die Tumor-VAF?":"¿Cómo influye la LOH en el VAF tumoral?","Wie formuliert man Keimbahnverdacht im Tumorbericht?":"¿Cómo debe formularse la sospecha de origen germinal en un informe tumoral?","Twist: 48 % ist Hinweis, kein Beweis":"Twist: 48 % es un indicio, no una prueba","Tumor- und Keimbahnkonsequenz getrennt":"Separar las consecuencias tumorales y germinales","Referenzpfad: Tumoractionability → Keimbahnverdacht → konstitutionelle Bestätigung":"Ruta de referencia: accionabilidad tumoral → sospecha germinal → confirmación constitucional","ALK-IHC positiv, DNA-NGS negativ: die Fusion steckt im Transkript":"IHC de ALK positiva, NGS de ADN negativo: la fusión está en el transcrito","DNA-NGS negativ, aber Fusionsverda…":"NGS de ADN negativo, pero persiste la sospecha de fusión…","Sarkomzentrum / Molekulares Tumorboard":"Centro de sarcomas / Comité Molecular de Tumores","34-jährige Patientin mit nicht vollständig resezierbarem inflammatorischem myofibroblastärem Tumor (IMT) im kleinen Becken. ALK-IHC diffus stark positiv, DNA-basiertes Panel meldet keine ALK-Fusion.":"Paciente de 34 años con tumor miofibroblástico inflamatorio (IMT) pélvico no completamente resecable. La IHC de ALK es difusa e intensamente positiva; un panel basado en ADN no informa ninguna fusión de ALK.","Ist die Fusionshypothese damit erledigt oder muss RNA-basiert/orthogonal weiter untersucht werden?":"¿Queda descartada la hipótesis de fusión o debe continuar el estudio basado en ARN/ortogonal?","Die systemische Behandlungsstrategie soll im Sarkomboard festgelegt werden.":"La estrategia de tratamiento sistémico debe definirse en el comité de sarcomas.","Spindelzelliger myofibroblastärer Tumor mit entzündlichem Hintergrund, passend zu IMT.":"Tumor miofibroblástico fusocelular con fondo inflamatorio, compatible con IMT.","ALK diffus zytoplasmatisch stark positiv.":"ALK difusa e intensamente positivo en citoplasma.","DNA-Panel":"Panel de ADN","Keine Fusion detektiert; Report weist darauf hin, dass nicht alle intronischen Breakpointregionen vollständig erfasst werden.":"No se detecta fusión; el informe señala que no todas las regiones intrónicas de breakpoint están completamente cubiertas.","„Gen im Panel enthalten“ wird mit „jede mögliche Fusion erfasst“ gleichgesetzt.":"Se equipara «el gen está incluido en el panel» con «se cubren todas las fusiones posibles».","IMT-morphologischer Kontext.":"Contexto morfológico de IMT.","ALK-IHC":"IHC de ALK","stark positiv.":"intensamente positivo.","kein Fusionscall.":"sin call de fusión.","Ist ein exprimiertes ALK-Fusionstranskript nachweisbar?":"¿Puede detectarse un transcrito de fusión de ALK expresado?","FFPE-Resektat, RNA-QC ausreichend.":"Pieza de resección FFPE, QC de ARN adecuado.","DNA-Limitation":"Limitación del ADN","Breakpoint kann außerhalb der erfassten intronischen Regionen liegen.":"El breakpoint puede situarse fuera de las regiones intrónicas capturadas.","Gezieltes RNA-Fusionspanel und FISH verfügbar.":"Se dispone de panel dirigido de fusiones de ARN y FISH.","Fusionsverdacht mit geeigneter Methode klären":"Aclarar la sospecha de fusión con un método adecuado","RNA-basiertes Fusionspanel weist ein exprimiertes TPM3::ALK-Fusionstranskript nach.":"El panel de fusiones basado en ARN detecta un transcrito de fusión TPM3::ALK expresado.","ALK-Break-apart-FISH ist positiv und stützt das Rearrangement, ohne den Fusionspartner auf Sequenzebene zu definieren.":"La FISH break-apart de ALK es positiva y respalda el reordenamiento, sin definir el socio de fusión a nivel de secuencia.","Breites DNA-Panel":"Panel de ADN amplio","Mehr DNA-Panelbreite garantiert keine vollständige Erfassung aller Fusionsbreakpoints; die relevante methodische Lücke bleibt.":"Un panel de ADN más amplio no garantiza la cobertura completa de todos los breakpoints de fusión; persiste la laguna metodológica relevante.","Prätestwahrscheinlichkeit":"Probabilidad pretest","Morphologie plus starke ALK-IHC machen einen Fusionsmechanismus plausibel.":"La morfología junto con una IHC de ALK intensamente positiva hacen plausible un mecanismo de fusión.","Ein negatives DNA-Fusionsergebnis ist nur so vollständig wie das Assaydesign der relevanten intronischen Regionen.":"Un resultado negativo de fusión en ADN es tan completo como lo permita el diseño del ensayo para las regiones intrónicas relevantes.","Der negative DNA-Fusionscall schließt in diesem hochgradig verdächtigen Kontext ein ALK-Rearrangement nicht aus. RNA-NGS weist ein exprimiertes TPM3::ALK-Transkript nach; ALK-FISH bestätigt das Rearrangement orthogonal. Der Fall zeigt den komplementären Wert von RNA- und DNA-basierten Ansätzen.":"El call negativo de fusión en ADN no excluye un reordenamiento de ALK en este contexto de alta sospecha. El NGS de ARN detecta un transcrito TPM3::ALK expresado; la FISH de ALK confirma ortogonalmente el reordenamiento. El caso muestra el valor complementario de los enfoques basados en ARN y ADN.","Teilbefund: Bei hoher morphologisch-immunhistochemischer Prätestwahrscheinlichkeit ist ein negativer DNA-Fusionscall nicht automatisch abschließend.":"Resultado parcial: con una alta probabilidad pretest morfológica/inmunohistoquímica, un call negativo de fusión en ADN no es automáticamente definitivo.","Assaydesign/Breakpointabdeckung berücksichtigen":"Considerar el diseño del ensayo/la cobertura de breakpoints","RNA als direkte Ebene des exprimierten Fusionstranskripts einordnen":"Situar el ARN como nivel directo del transcrito de fusión expresado","FISH als orthogonalen Rearrangementnachweis einordnen":"Situar la FISH como evidencia ortogonal de reordenamiento","Falschaussage: ALK steht im DNA-Panel, daher sind alle ALK-Fusionen ausgeschlossen":"Afirmación falsa: ALK está incluido en el panel de ADN, por tanto se excluyen todas las fusiones de ALK","Optimale Lösung: Widerspruch zwischen starker Prätestwahrscheinlichkeit und negativem DNA-Fusionscall erkennen und mit RNA-basierter Fusionsdiagnostik bzw. FISH klären.":"Solución óptima: reconocer la discordancia entre una alta probabilidad pretest y un call negativo de fusión en ADN, y resolverla mediante estudio de fusiones basado en ARN y/o FISH.","Fusion":"Fusión","ALK":"ALK","DNA negativ, Biologie positiv":"ADN negativo, biología positiva","Molekularpathologie / Fusionsdiagnostik / Sarkom-MTB":"Patología molecular / Diagnóstico de fusiones / MTB de sarcomas","Grenzen DNA-basierter Fusionsdetektion durch Breakpoint-/Intronabdeckung verstehen.":"Comprender los límites de la detección de fusiones basada en ADN por la cobertura de breakpoints/intrones.","RNA-NGS als komplementären Nachweis exprimierter Fusionstranskripte nutzen.":"Utilizar NGS de ARN como evidencia complementaria de transcritos de fusión expresados.","Prätestwahrscheinlichkeit aus Morphologie/IHC in die Methodenauswahl integrieren.":"Integrar la probabilidad pretest derivada de morfología/IHC en la selección del método.","FISH als orthogonalen Rearrangementnachweis mit begrenzter Partnerinformation einordnen.":"Interpretar la FISH como evidencia ortogonal de reordenamiento con información limitada sobre el socio.","ALK ist immunhistochemisch leuchtend positiv, die Morphologie passt – und trotzdem sagt das DNA-Panel „keine Fusion“. Der Fall beginnt dort, wo ein Automat aufhören würde.":"ALK es intensamente positivo por IHC, la morfología encaja y, sin embargo, el panel de ADN dice «sin fusión». El caso empieza donde un sistema automático se detendría.","34-jährige Patientin mit IMT. ALK-IHC und Morphologie sprechen stark für einen Fusionsmechanismus, das DNA-Panel bleibt negativ. Das Assaydesign deckt nicht alle möglichen intronischen Breakpoints ab.":"Paciente de 34 años con IMT. La IHC de ALK y la morfología apoyan fuertemente un mecanismo de fusión, pero el panel de ADN es negativo. El diseño del ensayo no cubre todos los breakpoints intrónicos posibles.","Panelinhalt ≠ vollständige Fusionsabdeckung":"Contenido del panel ≠ cobertura completa de fusiones","Ein Gen kann im Panel sein, ohne dass jeder relevante intronische Breakpoint erfasst wird.":"Un gen puede estar incluido en el panel sin que se cubra cada breakpoint intrónico relevante.","Assaydesign bestimmt Sensitivität.":"El diseño del ensayo determina la sensibilidad.","RNA fragt nach dem Produkt":"El ARN pregunta por el producto","Ein RNA-Fusionsassay kann das tatsächlich exprimierte Chimärtranskript nachweisen.":"Un ensayo de fusiones de ARN puede detectar el transcrito quimérico realmente expresado.","RNA und DNA sind komplementär.":"ARN y ADN son complementarios.","Prätestwahrscheinlichkeit zählt":"La probabilidad pretest importa","Morphologie + ALK-IHC machen einen negativen DNA-Call unplausibel genug für Reflexdiagnostik.":"Morfología + IHC de ALK hacen que un call negativo de ADN sea suficientemente poco plausible como para justificar estudio reflejo.","Diagnostik ist Bayes, nicht nur Softwareoutput.":"El diagnóstico es bayesiano, no solo una salida de software.","IMT-kompatibel":"compatible con IMT","diffus stark positiv":"difusa e intensamente positivo","kein Fusionscall; intronische Coverage limitiert":"sin call de fusión; cobertura intrónica limitada","RNA-Qualität ausreichend.":"Calidad de ARN adecuada.","FISH verfügbar.":"FISH disponible.","Kein Bedarf für beliebige weitere DNA-Breite, wenn die offene Frage eine Fusion ist.":"No hace falta ampliar arbitrariamente el ADN cuando la cuestión abierta es una fusión.","Wie ist der negative DNA-Fusionscall bei starker ALK-IHC und passender Morphologie zu bewerten?":"¿Cómo debe interpretarse el call negativo de fusión en ADN con IHC de ALK intensamente positiva y morfología compatible?","Er schließt eine Fusion nicht sicher aus, wenn relevante Breakpoints vom Assay nicht vollständig erfasst werden.":"No excluye de forma segura una fusión si el ensayo no cubre por completo los breakpoints relevantes.","ALK-Fusion ist sicher ausgeschlossen.":"La fusión de ALK está definitivamente excluida.","IHC ist damit automatisch falsch.":"Por tanto, la IHC es automáticamente errónea.","Es handelt sich um Keimbahn-ALK.":"Se trata de ALK germinal.","Fusionssensitivität hängt stark vom Assaydesign ab.":"La sensibilidad para fusiones depende mucho del diseño del ensayo.","Warum ist RNA-NGS hier besonders sinnvoll?":"¿Por qué es especialmente útil el NGS de ARN aquí?","Es kann ein exprimiertes Fusionstranskript direkt erfassen und DNA-Breakpointgrenzen umgehen.":"Puede detectar directamente un transcrito de fusión expresado y sortear las limitaciones de breakpoints del ADN.","Es ist exakt derselbe Test wie DNA-NGS.":"Es exactamente la misma prueba que el NGS de ADN.","Es misst nur Proteinexpression.":"Mide únicamente expresión proteica.","Es ist primär ein Copy-number-Test.":"Es principalmente una prueba de número de copias.","RNA liefert eine komplementäre Fusionsinformation.":"El ARN aporta información complementaria sobre la fusión.","Was kann ein positiver ALK-Break-apart-FISH hier sinnvoll beitragen?":"¿Qué puede aportar aquí una FISH break-apart de ALK positiva?","Orthogonaler Nachweis eines ALK-Rearrangements, meist ohne genaue Partner-/Transkriptinformation.":"Evidencia ortogonal de un reordenamiento de ALK, generalmente sin información exacta sobre socio/transcrito.","Immer vollständige Sequenz des Fusionspartners.":"Siempre la secuencia completa del socio de fusión.","Quantitative RNA-Expression.":"Expresión cuantitativa de ARN.","Keimbahnstatus.":"Estado germinal.","FISH ist schnell und orthogonal, aber informationsärmer als sequenzbasierte Partnerbestimmung.":"La FISH es rápida y ortogonal, pero ofrece menos información que la identificación del socio basada en secuencia.","RNA-NGS zeigt TPM3::ALK. Was erklärt die DNA/RNA-Diskrepanz am besten?":"El NGS de ARN muestra TPM3::ALK. ¿Qué explica mejor la discrepancia ADN/ARN?","Das DNA-Assaydesign hat den relevanten Breakpoint nicht zuverlässig abgedeckt; RNA erfasst das exprimierte Transkript.":"El diseño del ensayo de ADN no cubrió de forma fiable el breakpoint relevante; el ARN detecta el transcrito expresado.","RNA muss falsch sein, weil DNA negativ war.":"El ARN debe ser erróneo porque el ADN fue negativo.","Die Histologie ist damit irrelevant.":"La histología es por tanto irrelevante.","Beide Tests sind negativ.":"Ambas pruebas son negativas.","Komplementäre Assaygrenzen erklären die Diskrepanz.":"Las limitaciones complementarias de los ensayos explican la discrepancia.","Entscheiden Sie, ob und wie der Fusionsverdacht nach negativem DNA-NGS weiter abgeklärt wird.":"Decidir si y cómo seguir estudiando la sospecha de fusión tras un NGS de ADN negativo.","Prätestwahrscheinlichkeit aus Morphologie/IHC festhalten.":"Registrar la probabilidad pretest derivada de morfología/IHC.","DNA-Assaydesign und intronische Abdeckung prüfen.":"Revisar el diseño del ensayo de ADN y la cobertura intrónica.","RNA-basierte Fusionsdiagnostik ergänzen.":"Añadir estudio de fusiones basado en ARN.","FISH bei Bedarf orthogonal oder schnell ergänzen.":"Añadir FISH de forma ortogonal o rápida cuando sea necesario.","Endbefund als integrierte Fusionsevidenz formulieren.":"Formular el informe final como evidencia integrada de fusión.","Bei nicht verwertbarer RNA kann FISH eine praktikable orthogonale Alternative sein; für Partner-/Transkriptinformation bleibt sequenzbasierte Diagnostik überlegen.":"Si el ARN no es evaluable, la FISH puede ser una alternativa ortogonal práctica; el estudio basado en secuencia sigue siendo superior para información de socio/transcrito.","DNA negativ = Fusion ausgeschlossen":"ADN negativo = fusión excluida","Ignoriert intronische Assaygrenzen.":"Ignora las limitaciones intrónicas del ensayo.","Nur IHC als endgültiger Fusionsnachweis":"Solo IHC como evidencia definitiva de fusión","Proteinexpression ist kontextabhängig und nicht identisch mit Sequenznachweis.":"La expresión proteica depende del contexto y no equivale a evidencia de secuencia.","Beliebig größeres DNA-Panel":"Panel de ADN arbitrariamente mayor","Mehr Gene lösen nicht zwingend das Breakpointproblem.":"Más genes no resuelven necesariamente el problema del breakpoint.","Die Fusion war die ganze Zeit exprimiert":"La fusión estuvo expresada todo el tiempo","RNA-NGS weist TPM3::ALK nach; FISH bestätigt das ALK-Rearrangement.":"El NGS de ARN detecta TPM3::ALK; la FISH confirma el reordenamiento de ALK.","Der negative DNA-Call war methodisch begrenzt, nicht biologisch endgültig.":"El call negativo de ADN estaba limitado metodológicamente, no era biológicamente definitivo.","Komplementär getestet":"Estudio complementario realizado","RNA weist exprimierte Fusion nach, FISH stützt Rearrangement.":"El ARN detecta la fusión expresada y la FISH respalda el reordenamiento.","Methodengerechte Auflösung der Diskrepanz.":"Resolución de la discrepancia adecuada al método.","Nach DNA-NGS beendet":"Se detuvo tras el NGS de ADN","Relevante Fusion bleibt unentdeckt.":"La fusión relevante queda sin detectar.","Falsch-negatives Methodensilo.":"Silo metodológico falsamente negativo.","Nur IHC akzeptiert":"Se acepta solo la IHC","Fusionsmechanismus nicht molekular geklärt.":"El mecanismo de fusión no queda aclarado molecularmente.","Unvollständige Charakterisierung.":"Caracterización incompleta.","hohe Fusionsprätestwahrscheinlichkeit + nichtinformativer/negativer DNA-Call":"alta probabilidad pretest de fusión + call de ADN no informativo/negativo","RNA-Fusionsdiagnostik und/oder orthogonalen Assay ergänzen":"añadir estudio de fusiones de ARN y/o un ensayo ortogonal","Negativer DNA-Call nicht als universellen Ausschluss formulieren.":"No formular un call negativo de ADN como exclusión universal.","DNA- und RNA-Fusionsdiagnostik sind komplementär.":"El diagnóstico de fusiones basado en ADN y ARN es complementario.","Assaydesign ist Teil der Befundinterpretation.":"El diseño del ensayo forma parte de la interpretación del informe.","Prätestwahrscheinlichkeit entscheidet, wann ein negativer Test nicht das Ende ist.":"La probabilidad pretest determina cuándo una prueba negativa no es el final.","Trotz negativem DNA-NGS bleibt der Fusionsverdacht hoch; RNA-NGS weist TPM3::ALK nach, FISH bestätigt das Rearrangement. DNA-Negativität war durch die Breakpointabdeckung limitiert.":"A pesar del NGS de ADN negativo, la sospecha de fusión sigue siendo alta; el NGS de ARN detecta TPM3::ALK y la FISH confirma el reordenamiento. La negatividad en ADN estaba limitada por la cobertura del breakpoint.","Fusionsmethodik":"Metodología de fusiones","Assaygrenzen":"Limitaciones del ensayo","Wann ist FISH schneller als RNA-NGS?":"¿Cuándo es la FISH más rápida que el NGS de ARN?","Welche RNA-QC ist für FFPE kritisch?":"¿Qué parámetros de QC de ARN son críticos para FFPE?","Wie sollte ein negativer DNA-Fusionsbericht Limitationen nennen?":"¿Cómo debe expresar sus limitaciones un informe negativo de fusiones en ADN?","Twist: DNA-negativ trotz echter Fusion":"Twist: ADN negativo pese a una fusión real","RNA als komplementäre Ebene":"ARN como capa complementaria","Referenzpfad: Prätestwahrscheinlichkeit → Assaydesign → RNA/FISH":"Ruta de referencia: probabilidad pretest → diseño del ensayo → ARN/FISH","Liquid Biopsy negativ bei Progress: kein ctDNA-Signal ist kein Tumor-Wildtyp":"Biopsia líquida negativa en progresión: ausencia de señal de ctDNA no equivale a tumor wild type","Liquid Biopsy negativ bei Progress":"Biopsia líquida negativa en progresión","66-jähriger Patient mit EGFR-mutiertem NSCLC und radiologischem Progress nach längerer Krankheitskontrolle. Plasma-NGS meldet „keine tumorassoziierte Variante nachweisbar“.":"Paciente de 66 años con NSCLC mutado en EGFR y progresión radiológica tras un control prolongado de la enfermedad. El NGS plasmático informa «no se detecta ninguna variante asociada al tumor».","Darf das als fehlender Resistenzmechanismus interpretiert werden oder ist die Probe schlicht nicht informativ?":"¿Puede interpretarse como ausencia de mecanismo de resistencia o la muestra es simplemente no informativa?","Therapieumstellung soll im nächsten MTB erfolgen.":"El cambio terapéutico debe decidirse en el próximo MTB.","Neue Leberläsion und progrediente mediastinale Lymphknoten.":"Nueva lesión hepática y adenopatías mediastínicas progresivas.","Plasma":"Plasma","Keine bekannte klonale EGFR-Mutation detektierbar; Tumorfraktionsschätzer sehr niedrig/nicht informativ.":"La mutación clonal conocida de EGFR no es detectable; la estimación de fracción tumoral es muy baja/no informativa.","Ein negativer Plasma-Report wird wie ein negativer Tumorbefund gelesen.":"Un informe plasmático negativo se interpreta como un resultado tumoral negativo.","Informative von nichtinformativer Negativität unterscheiden.":"Distinguir una negatividad informativa de una no informativa.","Vorbekannter Tumor":"Tumor conocido","EGFR-aktivierende Mutation im ursprünglichen Tumor.":"Mutación activadora de EGFR en el tumor original.","Plasma jetzt":"Plasma ahora","Weder der bekannte Treiber noch neue Resistenzalterationen detektierbar.":"No se detectan ni el driver conocido ni nuevas alteraciones de resistencia.","Fehlt biologisch ein Resistenzmechanismus oder fehlt im Plasma ausreichend ctDNA?":"¿Falta biológicamente un mecanismo de resistencia o simplemente hay ctDNA insuficiente en plasma?","Wenn selbst der bekannte Tumormarker nicht erscheint, ist die Negativaussage besonders fragil.":"Si ni siquiera aparece el marcador tumoral conocido, la conclusión negativa es especialmente frágil.","Plasma technisch korrekt gewonnen.":"Plasma obtenido correctamente desde el punto de vista técnico.","ctDNA":"ctDNA","sehr niedrige Tumorfraktion.":"fracción tumoral muy baja.","Rebiopsie":"Rebiopsia","Leberläsion bildgesteuert zugänglich.":"Lesión hepática accesible para biopsia guiada por imagen.","Tissue-Rebiopsie und Gewebeprofil möglich.":"Es posible realizar rebiopsia tisular y perfilado del tejido.","Liquid-Biopsy-Informativität bewerten":"Evaluar la informatividad de la biopsia líquida","Nichtinformatives Plasma durch Tumorgewebe klären":"Aclarar un plasma no informativo mediante tejido tumoral","Liquid Biopsy":"Biopsia líquida","Keine tumorassoziierte Variante nachweisbar; selbst der bekannte klonale EGFR-Treiber fehlt. Tumorfraktion sehr niedrig – negatives Ergebnis ist nicht als Tumor-Wildtyp interpretierbar.":"No se detecta ninguna variante asociada al tumor; incluso falta el driver clonal conocido de EGFR. La fracción tumoral es muy baja: el resultado negativo no puede interpretarse como tumor wild type.","Tissue-Rebiopsie":"Rebiopsia tisular","Rebiopsie der progredienten Lebermetastase bestätigt Tumor und liefert ausreichend DNA für Gewebeprofiling.":"La rebiopsia de la metástasis hepática progresiva confirma tumor y proporciona ADN suficiente para perfilado tisular.","Gewebeprofil":"Perfil tisular","Im Progressionsgewebe bleibt der EGFR-Treiber nachweisbar; zusätzlich zeigt sich eine relevante MET-Amplifikation als Resistenzmechanismus.":"El driver de EGFR sigue siendo detectable en el tejido de progresión; además aparece una amplificación relevante de MET como mecanismo de resistencia.","Plasma-QC":"QC de plasma","Technisch valide Probe, biologisch jedoch mit sehr niedriger/nicht informativer Tumorfraktion.":"Muestra técnicamente válida, pero biológicamente con fracción tumoral muy baja/no informativa.","Ein nichtinformatives negatives ctDNA-Ergebnis darf einen Tumorbefund nicht ersetzen.":"Un resultado negativo de ctDNA no informativo no debe sustituir un resultado tumoral.","Die negative Liquid Biopsy ist wegen sehr niedriger Tumorfraktion und fehlendem Nachweis sogar des bekannten Treibers nicht informativ. Geweberebiopsie ist deshalb sinnvoll und zeigt im Progressionsgewebe weiterhin die EGFR-Alteration sowie eine MET-Amplifikation. „Plasma negativ“ war kein Beweis für fehlende Tumoralterationen.":"La biopsia líquida negativa no es informativa por la fracción tumoral muy baja y la ausencia incluso del driver conocido. Por ello es apropiada una rebiopsia tisular, que muestra la alteración de EGFR y una amplificación de MET en el tejido de progresión. «Plasma negativo» no demostraba ausencia de alteraciones tumorales.","Teilbefund: Eine negative Liquid Biopsy muss im Kontext von ctDNA/Tumorfraktion, Tumorbiologie und bekannten Markerbefunden interpretiert werden.":"Resultado parcial: una biopsia líquida negativa debe interpretarse en el contexto de ctDNA/fracción tumoral, biología tumoral y marcadores conocidos.","Tumorfraktion/Shedding berücksichtigen":"Considerar fracción tumoral/shedding","Fehlen des bekannten Treibers als Warnsignal für Nichtinformativität":"Ausencia del driver conocido como señal de alerta de falta de informatividad","bei klinischer Relevanz Gewebe-Reflex erwägen":"Considerar estudio reflejo en tejido cuando sea clínicamente relevante","Falschaussage: Plasma negativ = Tumor molekular negativ":"Afirmación falsa: plasma negativo = tumor molecularmente negativo","Optimale Lösung: negative Liquid Biopsy als möglicherweise nichtinformativ erkennen und bei zugänglichem Progressionsgewebe reflexartig tissue-basiert nachtesten.":"Solución óptima: reconocer una biopsia líquida negativa como potencialmente no informativa y realizar estudio reflejo basado en tejido cuando haya tejido de progresión accesible.","Progress":"Progresión","Negativ – aber ohne Tumorsignal":"Negativo, pero sin señal tumoral","Thoraxonkologie / Liquid Biopsy / MTB":"Oncología torácica / Biopsia líquida / MTB","Negative ctDNA-Ergebnisse von informativen positiven Ergebnissen asymmetrisch interpretieren.":"Interpretar de forma asimétrica los resultados negativos de ctDNA frente a resultados positivos informativos.","Tumorfraktion/Shedding und Nachweis eines bekannten Tumormarkers berücksichtigen.":"Considerar fracción tumoral/shedding y detección de un marcador tumoral conocido.","Bei nichtinformativem Plasma und klinischer Relevanz Gewebetestung erwägen.":"Considerar estudio tisular cuando el plasma no es informativo y la cuestión es clínicamente relevante.","Plasma- und Tissue-Profiling als komplementäre Strategien verstehen.":"Entender el perfilado de plasma y tejido como estrategias complementarias.","Der Plasma-Report ist leer. Nicht einmal die bekannte EGFR-Mutation taucht auf. Das kann heißen „Tumor ohne Alterationen“ – oder viel wahrscheinlicher: „zu wenig Tumor-DNA im Röhrchen, um etwas sicher auszuschließen“.":"El informe plasmático está vacío. Ni siquiera aparece la mutación conocida de EGFR. Puede significar «tumor sin alteraciones» o, mucho más probablemente, «demasiado poco ADN tumoral en el tubo para excluir nada con seguridad».","66-jähriger Patient mit EGFR-mutiertem NSCLC im Progress. Plasma-NGS ist technisch valide, zeigt aber keine tumorassoziierten Varianten und eine sehr niedrige Tumorfraktion. Eine Leberläsion ist biopsierbar.":"Paciente de 66 años con NSCLC mutado en EGFR en progresión. El NGS plasmático es técnicamente válido, pero no muestra variantes asociadas al tumor y presenta una fracción tumoral muy baja. Una lesión hepática es biopsiable.","Negativ ist asymmetrisch":"La negatividad es asimétrica","Ein positiver validierter ctDNA-Befund kann sehr informativ sein; ein negativer Befund kann bei niedrigem Shedding falsch-negativ sein.":"Un resultado positivo de ctDNA validado puede ser muy informativo; un resultado negativo puede ser falso negativo cuando el shedding es bajo.","Negativaussagen brauchen Informativitätskontext.":"Las conclusiones negativas requieren un contexto de informatividad.","Der bekannte Treiber als interne Plausibilität":"El driver conocido como control interno de plausibilidad","Wenn die etablierte EGFR-Mutation nicht detektierbar ist, spricht das gegen ausreichend Tumorsignal.":"Si la mutación establecida de EGFR no es detectable, esto sugiere señal tumoral insuficiente.","Vorwissen hilft, die Probe zu interpretieren.":"La información previa ayuda a interpretar la muestra.","Tissue bleibt relevant":"El tejido sigue siendo relevante","Bei nichtinformativer ctDNA kann Gewebe einen Resistenzmechanismus sichtbar machen.":"Cuando el ctDNA no es informativo, el tejido puede revelar un mecanismo de resistencia.","Liquid Biopsy ersetzt Gewebe nicht in jeder Situation.":"La biopsia líquida no sustituye al tejido en todas las situaciones.","EGFR-mutierter Primärtumor":"Tumor primario mutado en EGFR","Plasma-NGS":"NGS plasmático","keine tumorassoziierte Variante":"ninguna variante asociada al tumor","Tumorfraktion":"Fracción tumoral","sehr niedrig / nicht informativ":"muy baja / no informativa","Plasma technisch korrekt.":"Plasma técnicamente adecuado.","Progressionsgewebe zugänglich.":"Tejido de progresión accesible.","Copy-number-/Fusionserfassung kann zusätzlich von Assay und Tumorfraktion abhängen.":"La detección de número de copias/fusiones puede depender además del ensayo y de la fracción tumoral.","Wie ist eine negative ctDNA-Analyse bei sehr niedriger Tumorfraktion zu bewerten?":"¿Cómo debe valorarse un análisis de ctDNA negativo con fracción tumoral muy baja?","Als potenziell nichtinformativ/falsch-negativ; Tumoralterationen sind damit nicht sicher ausgeschlossen.":"Como potencialmente no informativo/falso negativo; no se excluyen de forma fiable alteraciones tumorales.","Der Tumor ist sicher wildtyp.":"El tumor es definitivamente wild type.","Es liegt sicher kein Tumor mehr vor.":"Seguro que ya no hay tumor.","Nur Keimbahnvarianten sind möglich.":"Solo son posibles variantes germinales.","ctDNA-Sensitivität hängt vom Tumorshedding und der Tumorfraktion ab.":"La sensibilidad del ctDNA depende del shedding tumoral y de la fracción tumoral.","Warum ist das Fehlen der bekannten klonalen EGFR-Mutation besonders wichtig?":"¿Por qué es especialmente importante la ausencia de la mutación clonal conocida de EGFR?","Es ist ein Warnsignal, dass im Plasma möglicherweise kaum detektierbare Tumor-DNA vorliegt.":"Es una señal de alerta de que puede haber muy poco ADN tumoral detectable en plasma.","Der Tumor muss EGFR sicher verloren haben.":"El tumor debe haber perdido necesariamente EGFR.","Der gesamte Labortest ist technisch zwingend ungültig.":"Toda la prueba de laboratorio es necesariamente técnicamente inválida.","Es ist ohne Bedeutung.":"No tiene importancia.","Der bekannte Marker dient als biologische Plausibilitätskontrolle.":"El marcador conocido sirve como control biológico de plausibilidad.","Was ist bei zugänglichem Progressionsgewebe der sinnvollste nächste Schritt?":"¿Cuál es el siguiente paso más apropiado cuando hay tejido de progresión accesible?","Geweberebiopsie/Gewebeprofiling zur Resistenzklärung.":"Rebiopsia tisular/perfilado tisular para aclarar la resistencia.","Keine weitere Diagnostik.":"Ningún estudio adicional.","Nur dasselbe Plasmaresultat erneut interpretieren.":"Reinterpretar únicamente el mismo resultado plasmático.","Methylierungsarray.":"Array de metilación.","Nichtinformative ctDNA sollte bei relevanter Frage durch Gewebe ergänzt werden.":"El ctDNA no informativo debe complementarse con tejido cuando la cuestión sea clínicamente relevante.","Gewebe zeigt den bekannten EGFR-Treiber plus MET-Amplifikation. Was lehrt die Diskrepanz?":"El tejido muestra el driver conocido de EGFR más amplificación de MET. ¿Qué enseña la discrepancia?","Das negative Plasma war wegen geringer Tumorfraktion nicht ausreichend zum Ausschluss eines Resistenzmechanismus.":"El resultado plasmático negativo era insuficiente para excluir un mecanismo de resistencia debido a la baja fracción tumoral.","Das Gewebe muss falsch sein.":"El tejido debe ser erróneo.","Liquid Biopsy ist grundsätzlich nutzlos.":"La biopsia líquida es inútil en general.","Beide Befunde bedeuten dasselbe.":"Ambos hallazgos significan lo mismo.","Liquid Biopsy ist wertvoll, aber negative Ergebnisse sind kontextabhängig.":"La biopsia líquida es valiosa, pero los resultados negativos dependen del contexto.","Entscheiden Sie, ob die negative Liquid Biopsy die Resistenzdiagnostik beendet oder eine Tissue-Reflexstrategie nötig ist.":"Decidir si la biopsia líquida negativa pone fin al estudio de resistencia o requiere una estrategia reflejo en tejido.","Plasma-QC und Tumorfraktion bewerten.":"Evaluar QC del plasma y fracción tumoral.","Bekannten Tumormarker als Plausibilitätsanker nutzen.":"Utilizar el marcador tumoral conocido como ancla de plausibilidad.","Negativbefund nicht überinterpretieren.":"No sobreinterpretar el resultado negativo.","Bei zugänglichem Progressionsgewebe Gewebetestung ergänzen.":"Añadir estudio tisular cuando haya tejido de progresión accesible.","Diskrepanz integriert berichten.":"Informar la discrepancia de forma integrada.","Wenn Gewebe nicht zugänglich ist, kann eine erneute Plasmaanalyse zu einem biologisch günstigeren Zeitpunkt oder eine alternative Flüssigkeit je nach Entität erwogen werden; das ersetzt keine pauschale Garantie.":"Si el tejido no es accesible, puede considerarse repetir el análisis plasmático en un momento biológicamente más favorable o utilizar otro líquido según la entidad; esto no ofrece una garantía universal.","Plasma negativ = Tumor negativ":"Plasma negativo = tumor negativo","Ignoriert falsch-negative Ergebnisse bei niedrigem Shedding.":"Ignora resultados falsos negativos con bajo shedding.","Liquid Biopsy generell verwerfen":"Rechazar por completo la biopsia líquida","Positive/informative Ergebnisse können klinisch sehr nützlich sein.":"Los resultados positivos/informativos pueden ser muy útiles clínicamente.","Tumorfraktion ignorieren":"Ignorar la fracción tumoral","Entfernt den wichtigsten Informativitätsparameter.":"Elimina el parámetro de informatividad más importante.","Das Gewebe findet, was das Plasma nicht sehen konnte":"El tejido encuentra lo que el plasma no pudo ver","Tissue-Profiling zeigt den bekannten Treiber und eine MET-Amplifikation.":"El perfilado tisular muestra el driver conocido y una amplificación de MET.","Die diagnostische Frage war nicht „war der Plasmatest technisch okay?“, sondern „war er biologisch informativ genug, um etwas auszuschließen?“":"La pregunta diagnóstica no era «¿estaba técnicamente bien la prueba plasmática?», sino «¿era biológicamente lo bastante informativa como para excluir algo?».","Nichtinformativ erkannt":"Resultado no informativo reconocido","Tissue-Reflex deckt Resistenzmechanismus auf.":"El estudio reflejo en tejido revela un mecanismo de resistencia.","Korrekte Liquid-Biopsy-Logik.":"Lógica correcta de biopsia líquida.","Nach negativem Plasma beendet":"Se detuvo tras plasma negativo","Resistenzmechanismus bleibt unentdeckt.":"El mecanismo de resistencia queda sin detectar.","Falsch-negatives Overconfidence.":"Exceso de confianza en un falso negativo.","Liquid Biopsy generell abgelehnt":"Biopsia líquida rechazada por completo","Methodennutzen wird unnötig negiert.":"Se niega innecesariamente la utilidad del método.","Zu pauschal.":"Demasiado general.","negatives ctDNA + niedrige Tumorfraktion/fehlender bekannter Treiber":"ctDNA negativo + baja fracción tumoral/ausencia del driver conocido","Ergebnis als nichtinformativ kennzeichnen und Gewebe erwägen":"marcar el resultado como no informativo y considerar tejido","Keine sichere Negativaussage über Tumorgenom.":"No puede hacerse una afirmación negativa fiable sobre el genoma tumoral.","Negative ctDNA-Befunde sind kontextabhängig.":"Los hallazgos negativos de ctDNA dependen del contexto.","Tumorfraktion und Shedding gehören zur Interpretation.":"La fracción tumoral y el shedding forman parte de la interpretación.","Plasma und Gewebe ergänzen sich.":"Plasma y tejido se complementan.","Negative Liquid Biopsy bei sehr niedriger Tumorfraktion und fehlendem bekanntem Treiber ist nicht ausreichend zum Ausschluss von Resistenzalterationen; Gewebe-Reflex zeigt hier MET-Amplifikation.":"Una biopsia líquida negativa con fracción tumoral muy baja y ausencia del driver conocido es insuficiente para excluir alteraciones de resistencia; el estudio reflejo en tejido revela aquí una amplificación de MET.","ctDNA-Informativität":"Informatividad del ctDNA","Reflex-Tissue":"Reflejo en tejido","Negativbefund":"Resultado negativo","Welche Tumorlokalisationen sheddern schlecht?":"¿Qué localizaciones tumorales liberan poco ctDNA?","Wann ist Plasma besonders sinnvoll?":"¿Cuándo es especialmente útil el plasma?","Wie sollte Tumorfraktion im Report kommuniziert werden?":"¿Cómo debe comunicarse la fracción tumoral en el informe?","Twist: technisch negatives Plasma, biologisch nichtinformativ":"Twist: plasma técnicamente negativo, biológicamente no informativo","Bekannter Treiber als Plausibilitätsanker":"Driver conocido como ancla de plausibilidad","Referenzpfad: Tumorfraktion → Negativität begrenzen → Tissue-Reflex":"Ruta de referencia: fracción tumoral → limitar interpretación negativa → reflejo en tejido","NPM1-MRD: diagnostisches NGS negativ, gezielte PCR noch positiv":"MRD de NPM1: NGS diagnóstico negativo, PCR dirigida aún positiva","qPCR/dPCR für MRD statt breites Pa…":"qPCR/dPCR para MRD en lugar de un panel amplio…","Hämatologie / Molekulares Tumorboard":"Hematología / Comité Molecular de Tumores","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung in morphologischer kompletter Remission. Ein breites myeloisches NGS-Panel ist „negativ“.":"Paciente de 52 años con AML mutada en NPM1 tras consolidación, en remisión completa morfológica. Un panel NGS mieloide amplio es «negativo».","Reicht das breite Panel für die MRD-Beurteilung oder braucht es die hochsensitive, zielgerichtete NPM1-Methode?":"¿Es suficiente el panel amplio para valorar MRD o se necesita el método NPM1 dirigido de alta sensibilidad?","MRD-Status soll vor der nächsten risikoadaptierten Entscheidung vorliegen.":"El estado de MRD debe conocerse antes de la siguiente decisión adaptada al riesgo.","Diagnosemarker":"Marcador diagnóstico","NPM1-Mutation bei Erstdiagnose eindeutig dokumentiert.":"Mutación de NPM1 claramente documentada en el diagnóstico inicial.","<5 % Blasten, komplette morphologische Remission.":"<5 % de blastos, remisión completa morfológica.","Breites NGS":"NGS amplio","Keine pathogene Variante oberhalb der diagnostischen Reporting-Grenzen.":"Ninguna variante patogénica por encima de los umbrales diagnósticos de informe.","Breite wird mit Sensitivität verwechselt.":"Se confunde amplitud con sensibilidad.","morphologisch in Remission.":"en remisión morfológica.","Zielmarker":"Marcador diana","NPM1 patientenspezifisch bekannt.":"Marcador NPM1 específico de la paciente conocido.","Ist unterhalb der Sensitivität eines diagnostischen Panels noch messbare Resterkrankung nachweisbar?":"¿Puede detectarse enfermedad residual medible por debajo de la sensibilidad de un panel diagnóstico?","MRD ist eine andere analytische Aufgabe als initiale Genotypisierung.":"La MRD es una tarea analítica distinta del genotipado inicial.","Knochenmark, ausreichende Nukleinsäurequalität.":"Médula ósea, calidad de ácidos nucleicos adecuada.","bekannter NPM1-Marker.":"marcador NPM1 conocido.","Methodenwahl":"Selección del método","gezielte qPCR/dPCR-artige MRD-Methode vs. breites Panel.":"método de MRD dirigido tipo qPCR/dPCR frente a panel amplio.","Beide technisch verfügbar; entscheidend ist die validierte Sensitivität für die Fragestellung.":"Ambos están técnicamente disponibles; lo decisivo es la sensibilidad validada para la cuestión clínica.","Sensitive zielgerichtete MRD-Methode":"Método de MRD dirigido sensible","Zielgerichtete MRD-PCR":"PCR de MRD dirigida","Patientenspezifischer NPM1-Marker bleibt in niedriger Menge reproduzierbar positiv; messbare Resterkrankung ist trotz morphologischer Remission nachweisbar.":"El marcador NPM1 específico de la paciente sigue siendo reproduciblemente positivo a bajo nivel; se detecta enfermedad residual medible pese a la remisión morfológica.","Breites myeloisches Panel":"Panel mieloide amplio","Keine Variante oberhalb der diagnostischen Panelgrenzen; dieser Negativbefund erreicht nicht automatisch die für NPM1-MRD erforderliche Sensitivität.":"Ninguna variante por encima de los límites del panel diagnóstico; este resultado negativo no alcanza automáticamente la sensibilidad necesaria para MRD de NPM1.","Komplette morphologische Remission.":"Remisión completa morfológica.","Diagnostische Panelbreite und MRD-Sensitivität sind unterschiedliche Leistungsmerkmale.":"La amplitud de un panel diagnóstico y la sensibilidad para MRD son características de rendimiento distintas.","Das negative diagnostische NGS-Panel beweist keine molekulare MRD-Negativität. Da ein geeigneter NPM1-Zielmarker bekannt ist, ist eine validierte hochsensitive zielgerichtete qPCR/dPCR-basierte Strategie angemessen. Diese bleibt niedrig positiv und zeigt messbare Resterkrankung trotz morphologischer Remission.":"Un panel NGS diagnóstico negativo no demuestra negatividad molecular de MRD. Como se conoce un marcador diana NPM1 adecuado, es apropiada una estrategia dirigida validada y altamente sensible basada en qPCR/dPCR. Permanece positiva a bajo nivel y demuestra enfermedad residual medible pese a la remisión morfológica.","Teilbefund: Für MRD muss die Methode zur erwarteten sehr niedrigen Krankheitslast und zum bekannten Zielmarker passen; ein breites Diagnostikpanel ist nicht automatisch sensitiv genug.":"Resultado parcial: para MRD, el método debe ajustarse a la muy baja carga de enfermedad esperada y al marcador diana conocido; un panel diagnóstico amplio no es automáticamente lo bastante sensible.","Diagnostik vs. MRD als unterschiedliche Testzwecke trennen":"Separar diagnóstico y MRD como finalidades analíticas distintas","assayvalidierte Sensitivität berücksichtigen":"Considerar la sensibilidad validada del ensayo","stabilen geeigneten Zielmarker nutzen":"Utilizar un marcador diana estable y adecuado","Falschaussage: breiteres Panel ist für MRD automatisch besser":"Afirmación falsa: un panel más amplio es automáticamente mejor para MRD","Optimale Lösung: bekannten NPM1-Marker mit validierter hochsensitiver Zielmethode verfolgen; diagnostisches NGS negativ nicht mit MRD-negativ gleichsetzen.":"Solución óptima: seguir el marcador NPM1 conocido con un método dirigido validado y altamente sensible; no equiparar NGS diagnóstico negativo con MRD negativa.","MRD":"MRD","NPM1":"NPM1","qPCR":"qPCR","dPCR":"dPCR","Breit negativ, hochsensitiv positiv":"Negativo en panel amplio, positivo con alta sensibilidad","Hämatologie / molekulare MRD-Diagnostik":"Hematología / diagnóstico molecular de MRD","Diagnostisches NGS von MRD-Methodik unterscheiden.":"Distinguir NGS diagnóstico de metodología de MRD.","Bei bekanntem geeignetem Marker eine validierte hochsensitive Zielmethode wählen.":"Cuando exista un marcador conocido adecuado, elegir un método dirigido validado y altamente sensible.","Analytische Sensitivität passend zur klinischen Fragestellung bewerten.":"Valorar una sensibilidad analítica adecuada a la cuestión clínica.","Morphologische Remission nicht mit molekularer MRD-Negativität gleichsetzen.":"No equiparar remisión morfológica con negatividad molecular de MRD.","Im Abschlussbefund steht zweimal „negativ“: Morphologie unauffällig, breites NGS ohne Treffer. Die NPM1-MRD-PCR sagt trotzdem positiv. Der Widerspruch ist nur scheinbar – die Methoden fragen auf völlig unterschiedlichen Tiefen.":"El informe final dice «negativo» dos veces: la morfología no muestra hallazgos y el NGS amplio no detecta nada. Sin embargo, la PCR de MRD de NPM1 es positiva. La contradicción es solo aparente: los métodos interrogan la enfermedad a profundidades completamente distintas.","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung. Morphologisch komplette Remission und diagnostisches Panel ohne Varianten oberhalb seiner Reporting-Grenzen. Für die MRD-Frage steht ein bekannter NPM1-Zielmarker zur Verfügung.":"Paciente de 52 años con AML mutada en NPM1 tras consolidación. Remisión completa morfológica y panel diagnóstico sin variantes por encima de sus umbrales de informe. Para la cuestión de MRD se dispone de un marcador diana NPM1 conocido.","Breite ist nicht Tiefe":"Amplitud no es profundidad","Ein diagnostisches Panel kann viele Gene erfassen, aber nicht dieselbe Nachweisgrenze wie eine fokussierte MRD-Methode erreichen.":"Un panel diagnóstico puede abarcar muchos genes sin alcanzar el mismo límite de detección que un método de MRD focalizado.","Methodenauswahl folgt der Frage.":"La selección del método depende de la pregunta.","Bekannter Marker ist ein Vorteil":"Un marcador conocido es una ventaja","NPM1 ist bei Diagnose dokumentiert und gezielt verfolgbar.":"NPM1 está documentado en el diagnóstico y puede seguirse de forma dirigida.","MRD kann patientenspezifisch hochsensitiv sein.":"La MRD puede ser altamente sensible y específica del paciente.","Remission hat Ebenen":"La remisión tiene niveles","Morphologische CR und molekulare MRD sind nicht synonym.":"CR morfológica y MRD molecular no son sinónimos.","Mehrere Ebenen der Krankheitslast koexistieren.":"Coexisten varios niveles de carga de enfermedad.","NPM1-mutierte AML":"AML mutada en NPM1","komplette Remission":"remisión completa","kein Call oberhalb diagnostischer Reporting-Grenze":"ningún call por encima del umbral diagnóstico de informe","Knochenmarkmaterial ausreichend.":"Material de médula ósea adecuado.","Zielmarker bekannt.":"Marcador diana conocido.","Die konkrete Nachweisgrenze ist labor- und assayvalidiert; keine universelle Prozentzahl wird vorausgesetzt.":"El límite exacto de detección está validado por laboratorio y ensayo; no se presupone un porcentaje universal.","Welche Methode passt am besten zur MRD-Frage bei bekanntem NPM1-Zielmarker?":"¿Qué método se ajusta mejor a la cuestión de MRD cuando existe un marcador diana NPM1 conocido?","Validierte hochsensitive zielgerichtete qPCR/dPCR-basierte MRD-Methode.":"Método de MRD dirigido, validado y altamente sensible basado en qPCR/dPCR.","Nur ein möglichst breites diagnostisches Panel.":"Solo el panel diagnóstico más amplio posible.","Nur HE-Morphologie.":"Solo morfología HE.","MRD verlangt hohe Sensitivität für einen geeigneten Zielmarker.":"La MRD requiere alta sensibilidad para un marcador diana adecuado.","Was bedeutet ein negatives diagnostisches NGS-Panel hier?":"¿Qué significa aquí un panel NGS diagnóstico negativo?","Keine Variante oberhalb seiner validierten Grenzen; molekulare MRD unterhalb dieser Grenzen kann bestehen.":"Ninguna variante por encima de sus límites validados; puede existir MRD molecular por debajo de esos límites.","Absolut keine Leukämiezelle vorhanden.":"No hay absolutamente ninguna célula leucémica.","MRD ist sicher negativ, unabhängig vom Assay.":"La MRD es definitivamente negativa independientemente del ensayo.","Die ursprüngliche AML-Diagnose war falsch.":"El diagnóstico original de AML era erróneo.","Negativität gilt nur innerhalb der analytischen Leistungsfähigkeit.":"La negatividad solo es válida dentro de los límites del rendimiento analítico.","Morphologische komplette Remission und MRD-positiv – ist das möglich?":"Remisión completa morfológica y MRD positiva: ¿es posible?","Ja; MRD-Methoden erfassen deutlich niedrigere Krankheitslast als Morphologie.":"Sí; los métodos de MRD detectan cargas de enfermedad mucho menores que la morfología.","Nein, die Befunde schließen sich aus.":"No, los hallazgos son incompatibles.","MRD ist immer Artefakt.":"La MRD siempre es un artefacto.","MRD hat keine klinische Bedeutung.":"La MRD no tiene relevancia clínica.","Die Ebenen messen unterschiedliche Sensitivitätsbereiche.":"Los niveles miden rangos de sensibilidad distintos.","Die NPM1-MRD-Methode ist reproduzierbar niedrig positiv. Wie lautet die Kernaussage?":"El método de MRD de NPM1 es reproduciblemente positivo a bajo nivel. ¿Cuál es la conclusión principal?","Molekulare MRD ist nachweisbar, obwohl Morphologie und diagnostisches Panel negativ sind.":"Se detecta MRD molecular aunque la morfología y el panel diagnóstico sean negativos.","Das breite Panel überschreibt die MRD-PCR.":"El panel amplio anula la PCR de MRD.","CR bedeutet zwingend null Resterkrankung.":"CR implica necesariamente cero enfermedad residual.","Der Zielmarker darf nicht verwendet werden.":"No debe utilizarse el marcador diana.","Die gezielte validierte MRD-Methode ist für diese Frage geeigneter.":"El método de MRD dirigido validado es más adecuado para esta cuestión.","Wählen und begründen Sie die Methode zur molekularen MRD-Beurteilung.":"Seleccionar y justificar el método para valorar MRD molecular.","Klinische Frage als MRD statt Diagnose definieren.":"Definir la cuestión clínica como MRD y no como diagnóstico.","Geeigneten bekannten Zielmarker identifizieren.":"Identificar un marcador diana conocido y adecuado.","Assayvalidierte Sensitivität berücksichtigen.":"Considerar la sensibilidad validada del ensayo.","Zielgerichtete MRD-PCR verwenden.":"Utilizar PCR de MRD dirigida.","Ergebnis getrennt von Morphologie und diagnostischem Panel berichten.":"Informar el resultado por separado de la morfología y del panel diagnóstico.","NGS-basierte MRD kann in validierten spezialisierten Ansätzen sinnvoll sein; der Fall richtet sich gegen die unkritische Verwendung eines routinemäßigen diagnostischen Breitenpanels als MRD-Ersatz.":"La MRD basada en NGS puede ser útil en enfoques especializados validados; el caso se opone al uso acrítico de un panel diagnóstico amplio rutinario como sustituto del estudio de MRD.","Breiter = sensitiver":"Más amplio = más sensible","Verwechselt Panelumfang mit Nachweisgrenze.":"Confunde alcance del panel con límite de detección.","Morphologische CR = MRD-negativ":"CR morfológica = MRD negativa","Ignoriert unterschiedliche Sensitivitätsebenen.":"Ignora los distintos niveles de sensibilidad.","Jede Persistenzmutation als MRD":"Cualquier mutación persistente como MRD","Nicht jeder Marker ist gleich geeignet; clonal hematopoiesis kann einzelne Gene persistieren lassen.":"No todos los marcadores son igualmente adecuados; la hematopoyesis clonal puede hacer persistir determinados genes.","Die Resterkrankung liegt unter der Paneloberfläche":"La enfermedad residual está por debajo de la superficie del panel","Gezielte NPM1-MRD bleibt reproduzierbar positiv.":"La MRD dirigida de NPM1 sigue siendo reproduciblemente positiva.","Der Fall zeigt, warum Testzweck und Sensitivität wichtiger sind als maximale Genbreite.":"El caso muestra por qué la finalidad del test y la sensibilidad importan más que la máxima amplitud génica.","Zielgerichtete MRD":"MRD dirigida","NPM1-MRD korrekt nachgewiesen.":"MRD de NPM1 correctamente detectada.","Fragestellungsgerechte Methodik.":"Metodología adecuada a la cuestión.","Nur breites Panel":"Solo panel amplio","Niedrige Resterkrankung wird fälschlich als negativ interpretiert.":"La enfermedad residual de bajo nivel se interpreta erróneamente como negativa.","Sensitivitätsproblem.":"Problema de sensibilidad.","Nur Morphologie":"Solo morfología","Molekulare Resterkrankung bleibt unsichtbar.":"La enfermedad residual molecular queda invisible.","Unvollständig.":"Incompleto.","bekannter geeigneter MRD-Marker":"marcador MRD conocido y adecuado","validierte hochsensitive Zielmethode nutzen":"utilizar un método dirigido validado y altamente sensible","Diagnostische Panelnegativität nicht als MRD-Negativität umdeuten.":"No reinterpretar la negatividad del panel diagnóstico como negatividad de MRD.","MRD ist eine eigene analytische Aufgabe.":"La MRD es una tarea analítica propia.","Breite und Sensitivität sind unabhängige Dimensionen.":"Amplitud y sensibilidad son dimensiones independientes.","Der beste Test ist der, dessen validierte Leistung zur klinischen Frage passt.":"La mejor prueba es aquella cuyo rendimiento validado se ajusta a la cuestión clínica.","Bei bekannter NPM1-mutierter AML ist die validierte zielgerichtete MRD-PCR der geeignete Test; diagnostisches NGS negativ schließt niedriggradige molekulare Resterkrankung nicht aus.":"En AML conocida mutada en NPM1, la PCR de MRD dirigida y validada es la prueba adecuada; un NGS diagnóstico negativo no excluye enfermedad residual molecular de bajo nivel.","MRD-Methodenwahl":"Selección del método de MRD","Sensitivität":"Sensibilidad","Befundebenen":"Niveles de resultado","Welche Mutationen sind für AML-MRD problematisch?":"¿Qué mutaciones son problemáticas para MRD en AML?","Wann ist dPCR gegenüber qPCR sinnvoll?":"¿Cuándo es útil la dPCR frente a la qPCR?","Welche Rolle hat NGS-basierte MRD?":"¿Qué papel tiene la MRD basada en NGS?","Twist: diagnostisches NGS negativ, MRD-PCR positiv":"Twist: NGS diagnóstico negativo, PCR de MRD positiva","Breite ≠ Sensitivität":"Amplitud ≠ sensibilidad","Referenzpfad: Zielmarker → validierte MRD-Methode → getrennte Interpretation":"Ruta de referencia: marcador diana → método de MRD validado → interpretación separada","MGMT-Frage im gesicherten Glioblastom: lokaler Marker statt Classifier-Overkill":"Pregunta de MGMT en un glioblastoma confirmado: marcador local en lugar de un exceso de clasificador","Bisulfit-PCR vs. Methylierungsarra…":"PCR con bisulfito vs. array de metilación…","69-jähriger Patient mit histologisch und molekular eindeutig klassifiziertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung wird der MGMT-Promotor-Methylierungsstatus benötigt.":"Paciente de 69 años con glioblastoma clasificado inequívocamente desde el punto de vista histológico y molecular, IDH wild type. Para planificar el tratamiento se necesita el estado de metilación del promotor de MGMT.","Braucht dieser Fall einen genomeweiten Methylierungsclassifier oder eine validierte zielgerichtete MGMT-Methylierungsanalyse?":"¿Necesita este caso un clasificador de metilación de todo el genoma o un análisis dirigido y validado de metilación de MGMT?","Adjuvante Therapieplanung steht unmittelbar an.":"La planificación del tratamiento adyuvante es inminente.","Glioblastom, IDH-Wildtyp, integriert gesichert; keine offene Entitätsfrage.":"Glioblastoma, IDH wild type, diagnóstico integrado establecido; no hay una cuestión de entidad pendiente.","Offene Biomarkerfrage":"Pregunta abierta sobre biomarcadores","MGMT-Promotor-Methylierung.":"Metilación del promotor de MGMT.","Ein technologisch umfassenderes Methylierungsarray wird automatisch als „besser“ angesehen.":"Un array de metilación tecnológicamente más amplio se considera automáticamente «mejor».","Testscope an die konkrete klinische Frage und lokale Validierung koppeln.":"Ajuste el alcance de la prueba a la pregunta clínica concreta y a la validación local.","Hochgradiges diffuses Astrozytom mit Nekrosen und mikrovaskulärer Proliferation.":"Astrocitoma difuso de alto grado con necrosis y proliferación microvascular.","IDH-Wildtyp; integrierte Diagnose steht.":"IDH wild type; diagnóstico integrado establecido.","MGMT-Promotor-Methylierungsstatus.":"Estado de metilación del promotor de MGMT.","Klassifikation und prädiktiver Einzelmarker sind zwei verschiedene Aufgaben.":"La clasificación y un biomarcador predictivo individual son dos tareas diferentes.","FFPE-Resektat, ausreichender Tumoranteil.":"Muestra de resección FFPE, contenido tumoral adecuado.","für beide Verfahren ausreichend.":"suficiente para ambos métodos.","Lokale Validierung":"Validación local","Bisulfit-basierte Zielmethode ist für MGMT klinisch validiert; das Array wird im Labor primär für CNS-Klassifikation eingesetzt.":"El método dirigido basado en bisulfito está validado clínicamente para MGMT; en este laboratorio el array se utiliza principalmente para la clasificación de tumores del SNC.","Array wäre teurer/langsamer und beantwortet hier keine offene Klassifikationsfrage.":"El array sería más caro/lento y aquí no respondería a ninguna cuestión de clasificación pendiente.","Zielgerichtete validierte MGMT-Methylierungsanalyse":"Análisis dirigido y validado de metilación de MGMT","Zielgerichtete Bisulfit-Methylierungsanalyse":"Análisis dirigido de metilación con bisulfito","MGMT-Promotor-Methylierung ist mit der lokal validierten zielgerichteten Methode nachweisbar und für die konkrete prädiktive Fragestellung berichtbar.":"La metilación del promotor de MGMT se detecta con el método dirigido validado localmente y puede informarse para la pregunta predictiva concreta.","CNS-Methylierungsclassifier":"Clasificador de metilación del SNC","Das genomeweite Profil bestätigt die bereits gesicherte Tumorklasse, ist in diesem Labor aber nicht als Ersatz für die klinische MGMT-Einzelmarkerbestimmung validiert.":"El perfil de todo el genoma confirma la clase tumoral ya establecida, pero en este laboratorio no está validado como sustituto de la determinación clínica de MGMT como marcador individual.","Zusätzliche Sequenzierungsbreite beantwortet die epigenetische MGMT-Frage nicht.":"Una secuenciación más amplia no responde a la pregunta epigenética de MGMT.","Tumorentität bereits integriert gesichert.":"Entidad tumoral ya establecida mediante diagnóstico integrado.","Mehr Omik ist nicht automatisch die passendere Methode; Scope und Validierung müssen zur Frage passen.":"Más ómica no implica automáticamente un método más adecuado; el alcance y la validación deben ajustarse a la pregunta.","Da die Tumorentität bereits sicher klassifiziert ist und die konkrete Frage MGMT-Promotor-Methylierung lautet, ist die lokal validierte zielgerichtete Bisulfitmethode die passende Untersuchung. Ein genomeweiter Methylierungsclassifier wäre für eine offene Entitätsfrage sinnvoll, ist hier aber unnötig und im lokalen Workflow kein validierter Ersatz für den prädiktiven Einzelmarker.":"Dado que la entidad tumoral ya está clasificada con seguridad y la pregunta concreta es la metilación del promotor de MGMT, la prueba adecuada es el método dirigido con bisulfito validado localmente. Un clasificador de metilación de todo el genoma sería útil ante una entidad no resuelta, pero aquí es innecesario y no constituye en el flujo local un sustituto validado del biomarcador predictivo individual.","Teilbefund: Lokaler prädiktiver Marker und globale epigenetische Klassifikation sind unterschiedliche diagnostische Aufgaben.":"Resultado parcial: un biomarcador predictivo local y una clasificación epigenética global son tareas diagnósticas diferentes.","Fragestellung vor Technologie wählen":"Elegir la pregunta antes que la tecnología","lokale klinische Validierung berücksichtigen":"tener en cuenta la validación clínica local","Classifier für Klassifikation, nicht automatisch für jeden Methylierungsmarker":"clasificador para clasificación, no automáticamente para cada biomarcador de metilación","Falschaussage: genomeweit ist immer klinisch besser":"Afirmación incorrecta: lo genómico siempre es clínicamente mejor","Optimale Lösung: gesicherte Diagnose respektieren und die offene MGMT-Frage mit der dafür validierten zielgerichteten Methylierungsmethode beantworten.":"Solución óptima: respetar el diagnóstico establecido y responder a la pregunta abierta de MGMT con el método dirigido de metilación validado para ese fin.","MGMT":"MGMT","Bisulfit":"Bisulfito","CNS":"SNC","Nicht jedes Methylom braucht ein Methylom":"No toda pregunta de metilación necesita un metiloma","Neuropathologie / Methodenauswahl":"Neuropatología / selección del método","Zielgerichtete Methylierungsanalyse von genomeweiter Klassifikation unterscheiden.":"Distinguir el análisis dirigido de metilación de la clasificación de todo el genoma.","Methodenumfang nicht mit klinischer Eignung gleichsetzen.":"No equiparar amplitud metodológica con idoneidad clínica.","Lokale Validierung und Intended Use in die Auswahl integrieren.":"Integrar la validación local y el uso previsto en la selección de la prueba.","Bei bereits gesicherter Entität unnötige Classifier-Diagnostik vermeiden.":"Evitar diagnósticos innecesarios con clasificador cuando la entidad ya está establecida.","Die Diagnose steht. Die einzige offene Frage lautet MGMT. Trotzdem liegt im Warenkorb ein genomeweites Methylierungsarray – weil „mehr Daten“ intuitiv nach „mehr Sicherheit“ klingt.":"El diagnóstico está establecido. La única pregunta abierta es MGMT. Sin embargo, en el carrito hay un array de metilación de todo el genoma, porque intuitivamente «más datos» suena a «más certeza».","69-jähriger Patient mit integriert gesichertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung ist ausschließlich der MGMT-Promotor-Methylierungsstatus offen. Das Labor hat dafür eine validierte zielgerichtete Bisulfitmethode; der CNS-Classifier ist für Entitätsklassifikation validiert.":"Paciente de 69 años con glioblastoma confirmado de forma integrada, IDH wild type. Para la planificación terapéutica solo queda pendiente el estado de metilación del promotor de MGMT. El laboratorio dispone para ello de un método dirigido con bisulfito validado; el clasificador del SNC está validado para la clasificación de entidades.","Frage vor Plattform":"La pregunta antes que la plataforma","MGMT-Status ist eine fokale Biomarkerfrage, Tumorklassifikation eine globale Musterfrage.":"El estado de MGMT es una pregunta focal de biomarcador; la clasificación tumoral es una pregunta de patrón global.","Testscope muss die Fragestellung spiegeln.":"El alcance de la prueba debe reflejar la pregunta.","Validierung schlägt Prestige":"La validación prima sobre el prestigio","Ein technisch komplexeres Verfahren ist nicht automatisch für jeden klinischen Output validiert.":"Un método técnicamente más complejo no está automáticamente validado para cualquier resultado clínico.","Intended Use ist Teil der Methode.":"El uso previsto forma parte del método.","Materialökonomie":"Economía de material","Unnötige Omik verbraucht Zeit, Geld und ggf. Material.":"La ómica innecesaria consume tiempo, dinero y potencialmente material.","Effizienz ist diagnostische Qualität.":"La eficiencia es calidad diagnóstica.","Entitätsdiagnose":"Diagnóstico de entidad","bereits integriert gesichert":"ya establecido mediante diagnóstico integrado","Lokaler Workflow":"Flujo de trabajo local","zielgerichtete Bisulfitmethode klinisch validiert":"método dirigido con bisulfito validado clínicamente","Ausreichendes Material.":"Material adecuado.","Kein Klassifikationsproblem.":"No hay un problema de clasificación.","Das Array ist lokal nicht als direkter Ersatz für die MGMT-Einzelmarkerfreigabe validiert.":"El array no está validado localmente como sustituto directo del informe de MGMT como marcador individual.","Welche Methode passt zur isolierten MGMT-Frage bei bereits gesicherter Glioblastomdiagnose am besten?":"¿Qué método se ajusta mejor a la pregunta aislada de MGMT cuando el diagnóstico de glioblastoma ya está establecido?","Die dafür lokal validierte zielgerichtete Bisulfit-Methylierungsanalyse.":"El análisis dirigido de metilación con bisulfito validado localmente.","Zwingend genomeweiter Classifier.":"Clasificador obligatorio de todo el genoma.","Breites DNA-NGS.":"NGS de ADN amplio.","FISH.":"FISH.","Der klinische Output ist ein definierter lokaler Methylierungsmarker.":"El resultado clínico es un biomarcador local de metilación definido.","Wann wäre der CNS-Methylierungsclassifier besonders sinnvoll?":"¿Cuándo es especialmente útil el clasificador de metilación del SNC?","Bei diagnostisch unklarer Tumorentität, wenn ein genomeweites Muster die integrierte Klassifikation unterstützen kann.":"Ante una entidad tumoral diagnósticamente incierta, cuando un patrón de todo el genoma puede apoyar la clasificación integrada.","Bei jedem MGMT-Auftrag unabhängig von Diagnose.":"Para toda solicitud de MGMT independientemente del diagnóstico.","Zur AML-MRD.":"Para MRD en LMA.","Für Keimbahndiagnostik.":"Para diagnóstico de línea germinal.","Classifier und Einzelmarker haben unterschiedliche Intended Uses.":"El clasificador y el biomarcador individual tienen usos previstos diferentes.","Warum darf ein Array nicht automatisch den lokal validierten MGMT-Test ersetzen?":"¿Por qué no debe un array sustituir automáticamente la prueba de MGMT validada localmente?","Weil klinische Freigabe die validierte Performance für genau diesen Output voraussetzt.":"Porque el informe clínico requiere un rendimiento validado para ese resultado concreto.","Weil Arrays grundsätzlich ungenau sind.":"Porque los arrays son inherentemente inexactos.","Weil Arrays keine DNA messen.":"Porque los arrays no miden ADN.","Weil Methylierungsarrays nie diagnostisch genutzt werden.":"Porque los arrays de metilación nunca se utilizan con fines diagnósticos.","Die Aussage richtet sich gegen ungeprüften Methodenwechsel, nicht gegen Arrays an sich.":"El objetivo es evitar un cambio de método no validado, no rechazar los arrays como tales.","Das Array bestätigt erwartungsgemäß die Tumorklasse, liefert aber keinen lokal validierten MGMT-Report. Was war der Fehler?":"El array confirma la clase tumoral esperada, pero no proporciona un informe de MGMT validado localmente. ¿Cuál fue el error?","Eine globale Klassifikationsplattform wurde für eine fokale prädiktive Frage eingesetzt, ohne passenden validierten Output.":"Se utilizó una plataforma de clasificación global para una pregunta predictiva focal sin un resultado validado adecuado.","Methylierungsclassifier sind grundsätzlich nutzlos.":"Los clasificadores de metilación son fundamentalmente inútiles.","Es gibt keinen Unterschied.":"No hay ninguna diferencia.","Technische Information und klinisch validierter Output sind nicht identisch.":"La información técnica y un resultado validado clínicamente no son idénticos.","Wählen Sie die Methylierungsmethode passend zur konkreten klinischen Frage.":"Elegir el método de metilación según la pregunta clínica concreta.","Prüfen, ob die Tumorentität bereits gesichert ist.":"Comprobar si la entidad tumoral ya está establecida.","Offene Frage als MGMT-Einzelmarker definieren.":"Definir la pregunta abierta como una cuestión de MGMT de marcador individual.","Lokal validierten Zielassay verwenden.":"Utilizar el ensayo dirigido validado localmente.","Classifier nur bei echter globaler Klassifikationsfrage einsetzen.":"Utilizar el clasificador solo cuando exista una verdadera cuestión de clasificación global.","Intended Use im Befund transparent halten.":"Mantener transparente el uso previsto en el informe.","Wenn ein Labor einen arraybasierten MGMT-Algorithmus spezifisch klinisch validiert hat, kann dieser lokal geeignet sein; der Fall lehrt Scope/Validierung, keine universelle Plattformhierarchie.":"Si un laboratorio ha validado clínicamente de forma específica un algoritmo de MGMT basado en array, este puede ser adecuado localmente; el caso enseña alcance/validación, no una jerarquía universal de plataformas.","Mehr Daten = besser":"Más datos = mejor","Ignoriert Fragestellung und Validierung.":"Ignora la pregunta clínica y la validación.","Classifier nie verwenden":"No utilizar nunca un clasificador","Bei unklaren CNS-Tumoren kann er sehr wertvoll sein.":"Puede ser muy valioso en tumores del SNC con diagnóstico incierto.","NGS für MGMT-Methylierung":"NGS para metilación de MGMT","Sequenzvarianten beantworten die epigenetische Frage nicht.":"Las variantes de secuencia no responden a la pregunta epigenética.","Das teurere Ergebnis beantwortet die falsche Frage":"El resultado más caro responde a la pregunta equivocada","Der Classifier bestätigt nur die bereits bekannte Tumorklasse; die klinisch offene MGMT-Frage bleibt ohne lokal validierten Einzelmarkeroutput bestehen.":"El clasificador solo confirma la clase tumoral ya conocida; la pregunta clínica abierta de MGMT queda sin respuesta sin un resultado de marcador individual validado localmente.","Der Fall verschiebt Methodenauswahl von Technologieprestige zu Intended Use.":"El caso desplaza la selección del método del prestigio tecnológico al uso previsto.","Zielmarker passend getestet":"Marcador diana evaluado adecuadamente","MGMT mit validierter Zielmethode berichtet.":"MGMT informado mediante el método dirigido validado.","Effizient und klinisch passend.":"Eficiente y clínicamente adecuado.","Classifier ohne offene Klassifikationsfrage":"Clasificador sin una cuestión abierta de clasificación","Mehr Daten, aber falscher primärer Output.":"Más datos, pero el resultado primario equivocado.","Scope-Mismatch.":"Desajuste de alcance.","Epigenetische Frage bleibt offen.":"La pregunta epigenética sigue sin resolverse.","Methodenfehler.":"Error de método.","isolierte validierte Einzelmarkerfrage":"pregunta aislada y validada de marcador individual","zielgerichteten validierten Assay bevorzugen":"preferir el ensayo dirigido validado","globale Omik nur bei zusätzlicher passender Fragestellung.":"ómica global solo si existe una pregunta adicional adecuada.","Fragestellung bestimmt Methodenumfang.":"La pregunta clínica determina el alcance metodológico.","Methylierungsclassifier und lokaler Bisulfitassay sind nicht austauschbar.":"El clasificador de metilación y el ensayo local con bisulfito no son intercambiables.","Intended Use und lokale Validierung gehören zur klinischen Interpretation.":"El uso previsto y la validación local forman parte de la interpretación clínica.","Bei gesichertem Glioblastom und isolierter MGMT-Frage ist die lokal validierte zielgerichtete Methylierungsanalyse angemessen; ein Classifier ist kein automatischer Ersatz.":"Con un glioblastoma establecido y una pregunta aislada de MGMT, el análisis dirigido de metilación validado localmente es apropiado; un clasificador no es un sustituto automático.","Methodenscope":"Alcance del método","Validierung":"Validación","Methylierungsdiagnostik":"Diagnóstico de metilación","Wann ist ein CNS-Classifier wirklich diagnostisch entscheidend?":"¿Cuándo es un clasificador del SNC realmente decisivo para el diagnóstico?","Wie validiert man einen MGMT-Assay?":"¿Cómo se valida un ensayo de MGMT?","Wann kann ein Array mehrere Outputs klinisch tragen?":"¿Cuándo puede un array sustentar múltiples resultados clínicos?","Twist: globale Plattform beantwortet lokale Frage nicht automatisch":"Giro: una plataforma global no responde automáticamente a una pregunta local","Intended Use vor Omikbreite":"Uso previsto antes que amplitud ómica","Referenzpfad: klinische Frage → validierter Output → Methode":"Ruta de referencia: pregunta clínica → resultado validado → método","EWSR1-FISH positiv: schneller Rearrangementnachweis, aber noch keine Entität":"FISH de EWSR1 positivo: detección rápida de reordenamiento, pero aún no una entidad","Amplifikation/Fusion: FISH als sch…":"Amplificación/fusión: FISH como complemento rápido…","Sarkomzentrum / Referenzpathologie":"Centro de sarcomas / patología de referencia","32-jährige Patientin mit einem tiefen Weichteiltumor am Fuß. Morphologisch monomorpher Tumor; EWSR1-Break-apart-FISH wird wegen Zeitdruck früh durchgeführt und ist positiv.":"Mujer de 32 años con un tumor profundo de partes blandas en el pie. Morfológicamente es un tumor monomorfo; por la presión de tiempo se realiza precozmente un FISH break-apart de EWSR1, que resulta positivo.","Darf daraus unmittelbar „Ewing-Sarkom“ werden oder braucht es partner-/transkriptspezifische Auflösung?":"¿Puede concluirse de inmediato «sarcoma de Ewing» o se necesita resolución específica del socio/transcrito?","Neoadjuvante Strategie wird in wenigen Tagen diskutiert.":"La estrategia neoadyuvante se discutirá en pocos días.","Monomorphe Zellen, aber nicht klassisch genug für eine alleinige Ewing-Diagnose.":"Células monomorfas, pero no lo bastante clásicas para un diagnóstico de Ewing por sí solo.","EWSR1-Break-apart positiv.":"EWSR1 break-apart positivo.","Ein Gen-Rearrangement wird mit einer bestimmten Tumorentität gleichgesetzt.":"Se equipara un reordenamiento génico con una entidad tumoral concreta.","FISH als schnellen, robusten, aber informationsbegrenzten Test einordnen.":"Situar el FISH como una prueba rápida y robusta, pero limitada en información.","Melaninarm, nested/solid; immunhistochemischer Kontext nicht eindeutig für Ewing.":"Pobre en melanina, patrón nested/sólido; el contexto inmunohistoquímico no es inequívoco para Ewing.","EWSR1 rearrangiert.":"EWSR1 reordenado.","Welcher Partner und welche Transkriptfusion liegt vor?":"¿Qué socio y qué transcrito de fusión están presentes?","EWSR1-Rearrangements kommen in mehreren Tumorentitäten vor.":"Los reordenamientos de EWSR1 aparecen en múltiples entidades tumorales.","FFPE-Biopsie; RNA ausreichend.":"Biopsia FFPE; ARN adecuado.","schnell verfügbar und technisch robust.":"disponible rápidamente y técnicamente robusto.","Targeted RNA-NGS verfügbar.":"NGS de ARN dirigido disponible.","Partnerbestimmung kann die Entitätsdiagnose entscheidend verändern.":"La identificación del socio puede cambiar de forma decisiva el diagnóstico de entidad.","Rearrangement schnell/orthogonal erfassen":"Detectar el reordenamiento de forma rápida/ortogonal","Fusionspartner/Transkript klären":"Aclarar el socio/transcrito de fusión","Break-apart-FISH":"FISH break-apart","EWSR1-Break-apart positiv: ein EWSR1-Rearrangement ist nachgewiesen, die Partneridentität und damit die genaue Entität sind dadurch nicht allein definiert.":"EWSR1 break-apart positivo: se demuestra un reordenamiento de EWSR1, pero la identidad del socio y, por tanto, la entidad exacta no quedan definidas solo con este resultado.","RNA-NGS weist EWSR1::ATF1 nach und unterstützt im passenden morphologisch-immunhistochemischen Kontext die Diagnose eines Clear-Cell-Sarkoms statt eines Ewing-Sarkoms.":"El NGS de ARN detecta EWSR1::ATF1 y, en el contexto morfológico-inmunohistoquímico adecuado, apoya el diagnóstico de sarcoma de células claras en lugar de sarcoma de Ewing.","Zusatzvarianten tragen weniger zur Kernfrage bei als die direkte Partnerbestimmung der Fusion.":"Las variantes adicionales aportan menos a la pregunta central que la identificación directa del socio de fusión.","schneller Rearrangementnachweis, aber keine universelle Entitätsdefinition.":"detección rápida del reordenamiento, pero no una definición universal de entidad.","Gen-Rearrangement und Fusionspartner müssen im morphologischen Kontext interpretiert werden.":"El reordenamiento génico y el socio de fusión deben interpretarse en el contexto morfológico.","EWSR1-Break-apart-FISH ist ein sinnvoller schneller Nachweis eines Rearrangements, beweist aber nicht automatisch ein Ewing-Sarkom. Die RNA-basierte Partnerbestimmung zeigt EWSR1::ATF1 und verschiebt die integrierte Diagnose im passenden Kontext zu einem Clear-Cell-Sarkom. FISH bleibt wertvoll – aber seine Aussagegrenze muss respektiert werden.":"El FISH break-apart de EWSR1 es una prueba rápida y útil para detectar un reordenamiento, pero no demuestra automáticamente un sarcoma de Ewing. La identificación del socio basada en ARN revela EWSR1::ATF1 y desplaza el diagnóstico integrado, en el contexto adecuado, hacia un sarcoma de células claras. El FISH sigue siendo valioso, pero deben respetarse los límites de su interpretación.","Teilbefund: Ein positiver Break-apart-FISH beantwortet „ist das Gen rearrangiert?“, nicht immer „welche Fusion/Entität liegt vor?“.":"Resultado parcial: un FISH break-apart positivo responde «¿está reordenado el gen?», no siempre «¿qué fusión/entidad está presente?». ","FISH-Stärke und -Grenze benennen":"Indicar la fortaleza y el límite del FISH","Partnerbestimmung bei entitätsrelevanter Frage ergänzen":"Añadir identificación del socio cuando sea relevante para el diagnóstico de entidad","Molekularbefund in Morphologie/IHC integrieren":"Integrar el resultado molecular con morfología/IHQ","Falschaussage: EWSR1-FISH positiv = Ewing-Sarkom":"Afirmación incorrecta: FISH de EWSR1 positivo = sarcoma de Ewing","Optimale Lösung: FISH als schnellen Rearrangementnachweis nutzen, aber bei nicht entitätsspezifischem Genereignis den Partner mit RNA-NGS bestimmen und integriert diagnostizieren.":"Solución óptima: utilizar FISH para detectar rápidamente el reordenamiento, pero cuando el evento génico no sea específico de entidad, determinar el socio mediante NGS de ARN y establecer un diagnóstico integrado.","EWSR1":"EWSR1","Sarcoma":"Sarcoma","FISH positiv – Diagnose noch offen":"FISH positivo: el diagnóstico sigue abierto","Sarkompathologie / FISH / RNA-Fusion":"Patología de sarcomas / FISH / fusión de ARN","Break-apart-FISH als schnellen Rearrangementnachweis korrekt einordnen.":"Situar correctamente el FISH break-apart como prueba rápida de reordenamiento.","Nicht entitätsspezifische Rearrangements nicht überinterpretieren.":"No sobreinterpretar reordenamientos que no sean específicos de entidad.","RNA-NGS zur Partner-/Transkriptbestimmung nutzen.":"Utilizar NGS de ARN para identificar el socio/transcrito.","Morphologie, IHC, FISH und RNA integriert bewerten.":"Evaluar de forma integrada morfología, IHQ, FISH y ARN.","Der FISH ist positiv. EWSR1 rearrangiert. Im ersten Moment klingt das wie die Diagnose – bis man sich erinnert, dass EWSR1 in mehreren völlig unterschiedlichen Tumoren rearrangiert sein kann.":"El FISH es positivo. EWSR1 está reordenado. Al principio parece que ya tenemos el diagnóstico, hasta recordar que EWSR1 puede estar reordenado en varios tumores completamente distintos.","32-jährige Patientin mit Weichteiltumor am Fuß. EWSR1-Break-apart-FISH ist positiv, die Morphologie aber nicht klassisch für Ewing. RNA ist ausreichend für Partnerbestimmung.":"Mujer de 32 años con un tumor de partes blandas en el pie. El FISH break-apart de EWSR1 es positivo, pero la morfología no es clásica para Ewing. El ARN es adecuado para identificar el socio.","FISH beantwortet eine enge Frage":"El FISH responde una pregunta concreta","Break-apart: Rearrangement ja/nein.":"Break-apart: reordenamiento sí/no.","Partner und Transkript bleiben oft offen.":"El socio y el transcrito a menudo quedan sin resolver.","Genereignis ist nicht immer entitätsspezifisch":"El evento génico no siempre es específico de entidad","EWSR1 kann verschiedene Fusionspartner und Tumorentitäten haben.":"EWSR1 puede tener diferentes socios de fusión y aparecer en distintas entidades tumorales.","Molekularer Befund braucht Kontext.":"Un resultado molecular necesita contexto.","RNA löst die Partnerfrage":"El ARN resuelve la cuestión del socio","Sequenzbasierter Transkriptnachweis kann die diagnostische Klasse entscheidend präzisieren.":"La detección del transcrito basada en secuenciación puede precisar de forma decisiva la clase diagnóstica.","FISH und RNA konkurrieren nicht, sie ergänzen sich.":"FISH y ARN no compiten; se complementan.","monomorph, aber nicht klassisch Ewing":"monomorfo, pero no clásico para Ewing","EWSR1 break-apart positiv":"EWSR1 break-apart positivo","Zeitdruck macht FISH attraktiv.":"La presión de tiempo hace atractivo el FISH.","RNA-NGS ist innerhalb der diagnostischen Frist möglich.":"El NGS de ARN es posible dentro del plazo diagnóstico.","Positives FISH darf nicht über seine validierte Zielaussage hinaus interpretiert werden.":"Un FISH positivo no debe interpretarse más allá de su afirmación diana validada.","Was beweist ein positiver EWSR1-Break-apart-FISH primär?":"¿Qué demuestra principalmente un FISH break-apart de EWSR1 positivo?","Ein EWSR1-Rearrangement.":"Un reordenamiento de EWSR1.","Immer ein Ewing-Sarkom.":"Siempre sarcoma de Ewing.","Immer den exakten Fusionspartner.":"Siempre el socio exacto de fusión.","Quantitative Proteinexpression.":"Expresión proteica cuantitativa.","Break-apart-FISH ist genbezogen, nicht zwingend partner- oder entitätsspezifisch.":"El FISH break-apart es específico del gen, no necesariamente del socio ni de la entidad.","Warum ist RNA-NGS bei atypischer Morphologie sinnvoll?":"¿Por qué es útil el NGS de ARN cuando la morfología es atípica?","Zur Bestimmung des exprimierten Fusionspartners/Transkripts.":"Para identificar el socio/transcrito de fusión expresado.","Weil es exakt dasselbe wie FISH misst.":"Porque mide exactamente lo mismo que FISH.","Nur zur Copy-number-Bestimmung.":"Solo para determinar el número de copias.","Nur für Keimbahn.":"Solo para estudio de línea germinal.","Die Partnerinformation kann die Diagnose präzisieren.":"La información del socio puede precisar el diagnóstico.","Wie sollte ein Fusionsbefund diagnostisch verwendet werden?":"¿Cómo debe utilizarse diagnósticamente un resultado de fusión?","Mit Morphologie, IHC und klinischem Kontext integrieren.":"Integrarlo con morfología, IHQ y contexto clínico.","Molekularer Befund ersetzt immer die Histologie.":"Un resultado molecular siempre sustituye a la histología.","Molekulare Befunde sind bei Sarkomen unwichtig.":"Los resultados moleculares no son importantes en sarcomas.","FISH entscheidet jede Entität allein.":"FISH determina por sí solo cualquier entidad.","Entitätsdiagnostik ist integriert.":"El diagnóstico de entidad es integrado.","RNA zeigt EWSR1::ATF1. Was ändert sich?":"El ARN muestra EWSR1::ATF1. ¿Qué cambia?","Im passenden Kontext unterstützt dies Clear-Cell-Sarkom statt einer vorschnellen Ewing-Diagnose.":"En el contexto adecuado, esto apoya un sarcoma de células claras en lugar de un diagnóstico prematuro de Ewing.","Es beweist weiterhin Ewing unabhängig vom Partner.":"Sigue demostrando Ewing independientemente del socio.","Der positive FISH war falsch.":"El FISH positivo era erróneo.","Partnerinformation ist bedeutungslos.":"La información del socio carece de importancia.","Die Partneridentität kann die Entitätszuordnung entscheidend verändern.":"La identidad del socio puede cambiar decisivamente la asignación de entidad.","Nutzen Sie FISH dort, wo er stark ist, und definieren Sie, wann Partnerbestimmung erforderlich ist.":"Utilizar FISH donde es fuerte y definir cuándo se requiere identificar el socio.","Morphologie und Prätestwahrscheinlichkeit erfassen.":"Evaluar la morfología y la probabilidad pretest.","FISH als schnellen Rearrangementnachweis verwenden.":"Utilizar FISH como prueba rápida de reordenamiento.","Aussagegrenze explizit halten.":"Mantener explícito el límite interpretativo.","Bei entitätsrelevanter Partnerfrage RNA-NGS ergänzen.":"Añadir NGS de ARN cuando la identidad del socio sea relevante para la entidad.","Integrierte Diagnose aus allen Ebenen formulieren.":"Formular un diagnóstico integrado a partir de todos los niveles.","Bei sehr charakteristischer Morphologie und entitätsspezifischem Rearrangement kann FISH ausreichend sein; das hängt von Gen, Tumorart und validiertem diagnostischem Kontext ab.":"Con una morfología muy característica y un reordenamiento específico de entidad, el FISH puede ser suficiente; depende del gen, el tipo tumoral y el contexto diagnóstico validado.","Break-apart = Partner bekannt":"Break-apart = socio conocido","FISH liefert diese Information häufig nicht.":"El FISH a menudo no proporciona esta información.","EWSR1 = Ewing":"EWSR1 = Ewing","EWSR1 ist nicht entitätsspezifisch.":"EWSR1 no es específico de entidad.","FISH ist veraltet und nutzlos":"FISH está obsoleto y es inútil","FISH kann schnell, robust und materialeffizient sehr wertvoll sein.":"FISH puede ser rápido, robusto, eficiente en material y muy valioso.","Der Partner kippt die Diagnose":"El socio cambia el diagnóstico","RNA zeigt EWSR1::ATF1 statt einer Ewing-typischen Fusion.":"El ARN muestra EWSR1::ATF1 en lugar de una fusión típica de Ewing.","FISH war korrekt positiv, aber die überzogene Interpretation wäre falsch gewesen.":"El FISH era correctamente positivo, pero la interpretación excesiva habría sido errónea.","FISH + RNA integriert":"FISH + ARN integrados","Rearrangement schnell erkannt, Partner korrekt bestimmt, Diagnose präzisiert.":"Reordenamiento detectado rápidamente, socio identificado correctamente, diagnóstico precisado.","Stärken beider Methoden genutzt.":"Se aprovecharon las fortalezas de ambos métodos.","Ewing nur aus EWSR1-FISH":"Ewing solo a partir del FISH de EWSR1","Entität falsch überinterpretiert.":"Entidad sobreinterpretada incorrectamente.","Scope-Fehler.":"Error de alcance.","FISH komplett verworfen":"FISH descartado por completo","Schnelle robuste Information unnötig verloren.":"Información rápida y robusta perdida innecesariamente.","positiver genbezogener FISH ohne entitätsspezifische Eindeutigkeit":"FISH génico positivo sin especificidad inequívoca de entidad","Partner-/Transkriptbestimmung erwägen":"considerar la identificación del socio/transcrito","Diagnose nicht allein aus Gen-Rearrangement ableiten.":"no derivar el diagnóstico solo del reordenamiento génico.","FISH bleibt klinisch nützlich.":"FISH sigue siendo clínicamente útil.","Aussagegrenze ist Teil der Methode.":"El límite interpretativo forma parte del método.","Partnerinformation kann diagnostisch wichtiger sein als der reine Gen-Rearrangementnachweis.":"La información del socio puede ser diagnósticamente más importante que la mera detección del reordenamiento génico.","EWSR1-FISH bestätigt ein Rearrangement, aber keine automatische Ewing-Diagnose; RNA-NGS zeigt EWSR1::ATF1 und präzisiert die Entität im morphologischen Kontext.":"El FISH de EWSR1 confirma un reordenamiento, pero no diagnostica automáticamente Ewing; el NGS de ARN muestra EWSR1::ATF1 y precisa la entidad en el contexto morfológico.","FISH-Scope":"Alcance del FISH","Partnerbestimmung":"Identificación del socio","integrierte Sarkomdiagnostik":"Diagnóstico integrado de sarcoma","Welche Break-apart-Sonden sind besonders entitätsspezifisch oder unspezifisch?":"¿Qué sondas break-apart son especialmente específicas o inespecíficas de entidad?","Wann ist FISH bei schlechter RNA die beste Option?":"¿Cuándo es FISH la mejor opción con ARN de mala calidad?","Wie formuliert man einen positiven FISH ohne Partner?":"¿Cómo se redacta un FISH positivo sin socio conocido?","Twist: FISH korrekt, Interpretation fast falsch":"Giro: FISH correcto, interpretación casi errónea","Gen-Rearrangement ≠ Entität":"Reordenamiento génico ≠ entidad","Referenzpfad: FISH → Scope prüfen → RNA-Partner → integrieren":"Ruta de referencia: FISH → comprobar alcance → socio por ARN → integrar","23 Seiten Multiomics: eine belastbare Kernaussage, viele Hypothesen":"23 páginas de multiómica: un mensaje central sólido, muchas hipótesis","Multiomics-Bericht: viel Informati…":"Informe multiómico: mucha informaci…","Hepatobiliäres Tumorboard / Präzisionsonkologie":"Comité hepatobiliar / oncología de precisión","59-jährige Patientin mit metastasiertem intrahepatischem Cholangiokarzinom. Ein externer Multiomics-Bericht umfasst DNA, RNA, Immunmarker und Proteinsignaturen auf 23 Seiten.":"Mujer de 59 años con colangiocarcinoma intrahepático metastásico. Un informe multiómico externo de 23 páginas incluye ADN, ARN, marcadores inmunitarios y firmas proteicas.","Welche Befunde sind unmittelbar klinisch belastbar, welche nur biologischer Kontext und welche reine Hypothese?":"¿Qué hallazgos son clínicamente sólidos de forma inmediata, cuáles son solo contexto biológico y cuáles son meras hipótesis?","Das MTB hat sieben Minuten für die molekulare Kernaussage.":"El comité dispone de siete minutos para el mensaje molecular central.","Pathogene IDH1 p.R132C-Mutation; keine FGFR2-Fusion im validierten Fusionsassay.":"Mutación patogénica IDH1 p.R132C; sin fusión de FGFR2 en el ensayo de fusiones validado.","FGFR2-Expression deutlich erhöht; mehrere Pathway-Scores für MAPK/EMT.":"Expresión de FGFR2 marcadamente elevada; varias puntuaciones de vías MAPK/EMT.","Immunprofil":"Perfil inmunitario","MSS, niedrige TMB; PD-L1 niedrig.":"MSS, TMB bajo; PD-L1 bajo.","Der visuell spektakulärste Omics-Score wird mit einem validierten prädiktiven Biomarker gleichgesetzt.":"La puntuación ómica visualmente más llamativa se equipara con un biomarcador predictivo validado.","Intrahepatisches Cholangiokarzinom.":"Colangiocarcinoma intrahepático.","Molekulare Schlüsseldaten":"Datos moleculares clave","IDH1 pathogen; keine FGFR2-Fusion.":"IDH1 patogénico; sin fusión de FGFR2.","Explorative Daten":"Datos exploratorios","FGFR2-high expression, EMT-/MET-Signaturen.":"Expresión alta de FGFR2, firmas EMT/MET.","Was gehört in die erste Zeile des Tumorboards?":"¿Qué debe figurar en la primera línea del resumen para el comité?","Mehrere Omics-Layer bereits erzeugt.":"Ya se han generado múltiples capas ómicas.","Problem":"Problema","Nicht Datenmangel, sondern Evidenzpriorisierung.":"No falta de datos, sino priorización de la evidencia.","Zeit":"Tiempo","MTB-Kommunikation muss extrem komprimiert sein.":"La comunicación en el comité debe ser extremadamente concisa.","Keine weitere Messung nötig, bevor die vorhandenen Daten sauber hierarchisiert sind.":"No se necesita ninguna medición adicional antes de jerarquizar correctamente los datos existentes.","Multiomics-Evidenz priorisieren und verdichten":"Priorizar y condensar la evidencia multiómica","Multiomics-Kernaussage":"Mensaje central multiómico","Kernaussage: pathogene IDH1-Alteration als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. FGFR2-Überexpression sowie EMT/MET-Signaturen bleiben explorativ und dürfen nicht wie validierte prädiktive Targets kommuniziert werden.":"Mensaje central: alteración patogénica de IDH1 como biomarcador tumoral establecido; sin fusión de FGFR2. La sobreexpresión de FGFR2 y las firmas EMT/MET siguen siendo exploratorias y no deben comunicarse como dianas predictivas validadas.","Noch breiteres Panel":"Panel aún más amplio","Mehr Daten lösen die zentrale Aufgabe – Evidenzhierarchie und klare Kommunikation – nicht.":"Más datos no resuelven la tarea central: jerarquía de evidencia y comunicación clara.","Informationsdichte":"Densidad de información","Viele biologisch interessante Signale, aber nur wenige direkt handlungsleitende Befunde.":"Muchas señales biológicamente interesantes, pero pocos hallazgos directamente orientadores de decisiones.","Multiomics braucht Evidenzhierarchie, nicht nur Datensynthese.":"La multiómica necesita una jerarquía de evidencia, no solo síntesis de datos.","Der Bericht wird auf eine belastbare klinische Kernaussage reduziert: pathogene IDH1-Veränderung als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression ist nicht gleichbedeutend mit einer FGFR2-Fusion, und EMT/MET-/Pathway-Signaturen bleiben ohne passende klinische Validierung explorativ. Das MTB erhält Evidenzstufen statt Datenrauschen.":"El informe se reduce a un mensaje clínico central sólido: alteración patogénica de IDH1 como biomarcador tumoral establecido; sin fusión de FGFR2. La expresión elevada de FGFR2 no equivale a una fusión de FGFR2, y las firmas EMT/MET/de vías siguen siendo exploratorias sin validación clínica adecuada. El comité recibe niveles de evidencia en lugar de ruido de datos.","Teilbefund: Multiomics ist nur dann klinisch nützlich, wenn validierte Biomarker, Kontextsignale und Hypothesen klar getrennt werden.":"Resultado parcial: la multiómica solo es clínicamente útil cuando se separan claramente los biomarcadores validados, las señales de contexto y las hipótesis.","Befunde nach klinischer Evidenz ordnen":"Ordenar los hallazgos por evidencia clínica","Expression nicht mit Fusion gleichsetzen":"No equiparar expresión con fusión","explorative Signaturen als Hypothesen kennzeichnen":"Etiquetar las firmas exploratorias como hipótesis","Falschaussage: stärkstes Heatmap-Signal = bestes Target":"Afirmación incorrecta: señal más intensa del heatmap = mejor diana","Optimale Lösung: aus vielen Daten eine kurze Evidenzhierarchie bauen – gesicherter Biomarker zuerst, relevante negative Befunde danach, explorative Omics klar als Hypothesen.":"Solución óptima: construir una jerarquía breve de evidencia a partir de muchos datos: primero el biomarcador establecido, después los hallazgos negativos relevantes y la ómica exploratoria claramente etiquetada como hipótesis.","Multiomics":"Multiómica","MTB-RES":"MTB-RES","23 Seiten auf drei Sätze reduzieren":"Reducir 23 páginas a tres frases","Präzisionsonkologie / MTB-Kommunikation":"Oncología de precisión / comunicación en comité","Multiomics-Befunde nach klinischer Evidenz hierarchisieren.":"Jerarquizar los hallazgos multiómicos según la evidencia clínica.","Genomische Alteration, Expression und Pathway-Signatur nicht miteinander gleichsetzen.":"No equiparar alteración genómica, expresión y firma de vía.","Relevante Negativbefunde sichtbar halten.":"Mantener visibles los hallazgos negativos relevantes.","Explorative Hypothesen klar von handlungsleitenden Biomarkern trennen.":"Separar claramente las hipótesis exploratorias de los biomarcadores que guían decisiones.","Eine präzise MTB-Kernaussage aus Datenfülle formulieren.":"Formular un mensaje central preciso para el comité a partir de un informe rico en datos.","Der Report ist 23 Seiten lang. Das Tumorboard hat sieben Minuten. Die Aufgabe ist nicht, alles vorzulesen – sondern zu wissen, welche zwei Sätze wirklich eine Entscheidung tragen.":"El informe tiene 23 páginas. El comité dispone de siete minutos. La tarea no es leerlo todo, sino saber qué dos frases sustentan realmente una decisión.","59-jährige Patientin mit intrahepatischem Cholangiokarzinom. DNA, RNA und weitere Omics-Layer liegen vor. Eine pathogene IDH1-Alteration ist klar, eine FGFR2-Fusion fehlt, während FGFR2-Expression und mehrere Pathway-Scores hoch sind.":"Mujer de 59 años con colangiocarcinoma intrahepático. Se dispone de ADN, ARN y capas ómicas adicionales. Existe una alteración patogénica clara de IDH1, no se detecta fusión de FGFR2, mientras que la expresión de FGFR2 y varias puntuaciones de vías son elevadas.","Evidenz vor Datenmenge":"Evidencia antes que volumen de datos","Ein validierter Biomarker wiegt klinisch mehr als viele explorative Signaturen.":"Un biomarcador validado tiene más peso clínico que muchas firmas exploratorias.","Informationsmenge ist keine Evidenzstufe.":"La cantidad de información no es un nivel de evidencia.","Expression ≠ Fusion":"Expresión ≠ fusión","Hohe FGFR2-mRNA ist biologisch interessant, aber nicht dasselbe wie ein nachgewiesenes FGFR2-Fusionsereignis.":"Un ARNm de FGFR2 elevado es biológicamente interesante, pero no equivale a un evento de fusión de FGFR2 demostrado.","Omics-Layer messen unterschiedliche Phänomene.":"Las capas ómicas miden fenómenos diferentes.","Negative Befunde können entscheidend sein":"Los hallazgos negativos pueden ser decisivos","„Keine FGFR2-Fusion“ verhindert ein falsches Target-Narrativ.":"«Sin fusión de FGFR2» evita una narrativa de diana falsa.","Klinische Zusammenfassung braucht auch relevante Ausschlüsse.":"Un resumen clínico también necesita exclusiones relevantes.","IDH1 p.R132C pathogen":"IDH1 p.R132C patogénico","keine FGFR2-Fusion":"sin fusión de FGFR2","FGFR2 hoch exprimiert; EMT/MET-Signaturen erhöht":"FGFR2 altamente expresado; firmas EMT/MET elevadas","Immunkontext":"Contexto inmunitario","MSS, TMB niedrig, PD-L1 niedrig":"MSS, TMB bajo, PD-L1 bajo","Alle Daten bereits vorhanden.":"Todos los datos ya están disponibles.","Keine akute Materialfrage.":"No hay un problema agudo de material.","Limitierend ist die Evidenzinterpretation, nicht die Messkapazität.":"La limitación es la interpretación de la evidencia, no la capacidad de medición.","Was gehört in die erste Zeile der MTB-Zusammenfassung?":"¿Qué debe figurar en la primera línea del resumen para el comité?","Der klinisch am besten validierte relevante Biomarker und seine konkrete Bedeutung.":"El biomarcador relevante mejor validado clínicamente y su significado concreto.","Die stärkste Farbe der Heatmap.":"El color más intenso del heatmap.","Alle 200 Signaturen alphabetisch.":"Las 200 firmas en orden alfabético.","Jede VUS vor gesicherten Befunden.":"Cada VUS antes que los hallazgos establecidos.","MTB-Kommunikation priorisiert klinische Evidenz.":"La comunicación en el comité prioriza la evidencia clínica.","Was bedeutet hohe FGFR2-Expression ohne nachgewiesene FGFR2-Fusion?":"¿Qué significa una expresión alta de FGFR2 sin una fusión de FGFR2 demostrada?","Biologischer/explorativer Kontext, aber kein automatischer Ersatz für den validierten Fusionsbiomarker.":"Contexto biológico/exploratorio, pero no un sustituto automático del biomarcador de fusión validado.","Eine Fusion ist damit bewiesen.":"Con ello queda demostrada una fusión.","Target-Therapie ist allein dadurch zwingend.":"La terapia dirigida es obligatoria solo por este motivo.","RNA ist grundsätzlich Artefakt.":"El ARN es inherentemente un artefact.","Expression und strukturelle Genfusion sind verschiedene Befundarten.":"La expresión y la fusión génica estructural son tipos de hallazgos diferentes.","Warum ist „keine FGFR2-Fusion“ ein wichtiger Befund?":"¿Por qué es importante el hallazgo «sin fusión de FGFR2»?","Er verhindert, dass die hohe Expression fälschlich als etablierter Fusions-Targetkontext verkauft wird.":"Evita que la expresión alta se presente erróneamente como un contexto establecido de diana por fusión.","Negative Befunde gehören nie ins MTB.":"Los hallazgos negativos nunca deben estar en el comité.","Er hat keinerlei Interpretationswert.":"No tiene ningún valor interpretativo.","Er macht IDH1 automatisch negativ.":"Hace que IDH1 sea automáticamente negativo.","Relevante Negativbefunde begrenzen falsche Handlungsableitungen.":"Los hallazgos negativos relevantes limitan inferencias falsas de accionabilidad.","Der Bericht rankt „FGFR pathway activation“ als stärkstes Signal. Was tun Sie?":"El informe clasifica «activación de la vía FGFR» como la señal más fuerte. ¿Qué hace?","Als explorative Signatur kennzeichnen und hinter validierten molekularen Befunden priorisieren.":"Etiquetarlo como firma exploratoria y situarlo por detrás de los hallazgos moleculares validados.","Als stärkstes Target behandeln.":"Tratarlo como la diana más fuerte.","Alle Omics-Daten verwerfen.":"Descartar todos los datos ómicos.","Eine FGFR2-Fusion daraus ableiten.":"Inferir una fusión de FGFR2 a partir de ello.","Pathway-Scores sind ohne entsprechende klinische Validierung Hypothesen, keine automatischen Companion Biomarker.":"Sin la correspondiente validación clínica, las puntuaciones de vías son hipótesis, no biomarcadores companion automáticos.","Verdichten Sie den Multiomics-Bericht zu einer evidenzhierarchischen MTB-Kernaussage.":"Condensar el informe multiómico en un mensaje central para el comité jerarquizado por evidencia.","Validierte/etablierte Biomarker identifizieren.":"Identificar biomarcadores validados/establecidos.","Relevante negative Befunde sichtbar machen.":"Hacer visibles los hallazgos negativos relevantes.","Expression, Fusion, Protein und Pathways als unterschiedliche Ebenen behandeln.":"Tratar expresión, fusión, proteína y vías como capas diferentes.","Explorative Signaturen kennzeichnen.":"Etiquetar las firmas exploratorias.","MTB-Aussage auf Entscheidung statt Dateninventar fokussieren.":"Centrar la declaración para el comité en la decisión, no en el inventario de datos.","Explorative Omics können für Studienhypothesen oder Translation wertvoll sein; sie gehören nur nicht unmarkiert in dieselbe Evidenzstufe wie validierte klinische Biomarker.":"La ómica exploratoria puede ser valiosa para hipótesis de estudio o investigación traslacional; simplemente no debe situarse sin etiquetar en el mismo nivel de evidencia que los biomarcadores clínicos validados.","Heatmap-Tophit = Target":"Top hit del heatmap = diana","Visuelle Effektstärke ersetzt keine klinische Validierung.":"La magnitud visual del efecto no sustituye la validación clínica.","Alles in einen Satz pressen":"Comprimir todo en una sola frase","Verwischt Evidenzstufen.":"Difumina los niveles de evidencia.","Exploratives komplett löschen":"Eliminar por completo lo exploratorio","Verliert wissenschaftlich wertvolle Hypothesen; besser klar labeln.":"Se pierden hipótesis científicamente valiosas; es mejor etiquetarlas claramente.","Der lauteste Signalweg ist nicht die stärkste klinische Aussage":"La vía más llamativa no es la afirmación clínica más fuerte","FGFR2-Expression ist hoch, aber es gibt keine FGFR2-Fusion. Die belastbare Topline bleibt die pathogene IDH1-Alteration; Omics-Signaturen werden als explorativ eingeordnet.":"La expresión de FGFR2 es alta, pero no existe fusión de FGFR2. La conclusión principal sólida sigue siendo la alteración patogénica de IDH1; las firmas ómicas se clasifican como exploratorias.","Der Twist dreht die Priorität von Signalstärke zu Evidenzstärke.":"El giro desplaza la prioridad de la intensidad de la señal a la solidez de la evidencia.","Klarer Biomarker, klarer Ausschluss, klar markierte Hypothesen.":"Biomarcador claro, exclusión clara, hipótesis claramente etiquetadas.","MTB-taugliche Verdichtung.":"Síntesis apta para comité.","Report vorgelesen":"Informe leído en voz alta","Viele Daten, keine Entscheidung.":"Muchos datos, ninguna decisión.","Informationsüberlastung.":"Sobrecarga de información.","FGFR2-expression als Fusion behandelt":"Expresión de FGFR2 tratada como fusión","Explorativer Befund wird targetiert.":"El hallazgo exploratorio se trata como diana.","Layer-Verwechslung.":"Confusión de capas.","Omics-Signal ohne validierten klinischen Biomarkerstatus":"Señal ómica sin estatus validado de biomarcador clínico","als explorativ/hypothesengenerierend kennzeichnen":"etiquetar como exploratorio/generador de hipótesis","nicht auf gleiche Ebene wie etablierte prädiktive Marker stellen.":"no situar al mismo nivel que los marcadores predictivos establecidos.","Multiomics braucht Evidenzhierarchie.":"La multiómica necesita una jerarquía de evidencia.","Biologische Plausibilität ist nicht identisch mit klinischer Actionability.":"La plausibilidad biológica no es idéntica a la accionabilidad clínica.","Gute MTB-Kommunikation ist selektiv und transparent.":"Una buena comunicación en comité es selectiva y transparente.","Kernaussage: pathogene IDH1-Alteration als belastbarer tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression und Pathway-Signaturen sind explorativ und nicht als validierte Targets zu überinterpretieren.":"Mensaje central: alteración patogénica de IDH1 como biomarcador tumoral sólido; sin fusión de FGFR2. La expresión alta de FGFR2 y las firmas de vías son exploratorias y no deben sobreinterpretarse como dianas validadas.","Evidenzpriorisierung":"Priorización de la evidencia","Omics-Layer":"Capas ómicas","Wie viele Ebenen sollte ein MTB-Report zeigen?":"¿Cuántos niveles debe mostrar un informe para comité?","Wie labelt man explorative Signaturen?":"¿Cómo se etiquetan las firmas exploratorias?","Welche negativen Befunde sind entscheidungsrelevant?":"¿Qué hallazgos negativos son relevantes para la decisión?","Twist: stärkstes Signal ist nicht stärkste Evidenz":"Giro: la señal más fuerte no es la evidencia más fuerte","Referenzpfad: validiert → relevante Negative → explorativ":"Ruta de referencia: validado → negativos relevantes → exploratorio","dna_rna_lung_combo":"Panel pulmonar combinado de ADN/ARN","Resistenzdiagnostik bei Progress":"Estudio de resistencia en la progresión","Gewebe-Rebiopsie bei negativer Liquid Biopsy":"Rebiopsia tisular tras una biopsia líquida negativa","Liquid Biopsy richtig einordnen":"Interpretar correctamente la biopsia líquida","Progressionspanel: erworbener Resistenzmechanismus wird plausibilisiert; Liquid Biopsy allein ist bei negativem Ergebnis nicht ausreichend.":"Panel en progresión: se sustenta un mecanismo de resistencia adquirido; una biopsia líquida negativa por sí sola no es suficiente.","Rebiopsie liefert beurteilbares Tumormaterial für Resistenzanalyse.":"La rebiopsia proporciona material tumoral evaluable para el análisis de resistencia.","Negative Liquid Biopsy wird nur mit ctDNA-/Materialkontext interpretiert; Rebiopsie bleibt Option.":"Una biopsia líquida negativa se interpreta únicamente en el contexto de la ctDNA y la idoneidad de la muestra; la rebiopsia sigue siendo una opción.","Integrierte Interpretation vollständig: Liquid Biopsy negativ: reicht das oder Rebiopsie? Die gewählten Methoden beantworten die Kernfrage mit angemessener Aussagekraft und Limitationen.":"Interpretación integrada completa: biopsia líquida negativa, ¿es suficiente o se requiere rebiopsia? Los métodos seleccionados responden a la cuestión central con un alcance analítico y unas limitaciones apropiados.","Teilbefund: Für die Kernentscheidung („Liquid Biopsy negativ: reicht das oder Rebiopsie?“) fehlen noch zentrale Bausteine oder die Methode ist zu eng gewählt.":"Resultado parcial: aún faltan elementos esenciales para la decisión central («Biopsia líquida negativa: ¿es suficiente o se necesita una rebiopsia?») o el método elegido es demasiado limitado.","Resistenzdiagnostik bei Progress in der MTB-Kernaussage korrekt einordnen":"Integrar correctamente el estudio de resistencia en progresión en el mensaje central del MTB","Gewebe-Rebiopsie bei negativer Liquid Biopsy in der MTB-Kernaussage korrekt einordnen":"Integrar correctamente la rebiopsia tisular tras una biopsia líquida negativa en el mensaje central del MTB","Liquid Biopsy richtig einordnen in der MTB-Kernaussage korrekt einordnen":"Interpretar correctamente la biopsia líquida en el mensaje central del MTB","Optimale Lösung: Liquid Biopsy negativ: reicht das oder Rebiopsie? – mit fallgerechter Methodenkombination, Material-/QC-Bewertung und klarer MTB-Kommunikation.":"Solución óptima: biopsia líquida negativa, ¿es suficiente o se requiere rebiopsia? Utilice una combinación de métodos adecuada al caso, valore el contexto de muestra/QC y comunique claramente la conclusión en el MTB.","RNA-Fusionsdiagnostik primär fehlt":"Falta el estudio primario de fusiones mediante ARN","entitätsfremde Tests gewählt":"Se seleccionaron pruebas ajenas a la entidad tumoral","nur Liquid Biopsy gewählt":"Se seleccionó únicamente biopsia líquida","Rebiopsie gewählt, aber MET/CNV/Transformation nicht bedacht":"Se seleccionó rebiopsia, pero no se consideraron MET/CNV/transformación histológica","MTB Basics / Präanalytik":"Fundamentos de MTB / Preanalítica","colon_ngs_panel":"Panel NGS de cáncer colorrectal","MTB Basics / Genominstabilität":"Fundamentos de MTB / Inestabilidad genómica","broad_pan_panel":"Panel pan-cáncer amplio","MTB Basics / Advanced":"Fundamentos de MTB / Avanzado","hoch.":"alto.","MTB / Molecular Diagnostics":"MTB / Diagnóstico molecular","wildtyp":"tipo salvaje"},"fr":{"ERBB2-VUS im RAS/BRAF-WT-mCRC: Genname ist noch kein Target":"VUS d’ERBB2 dans un mCRC RAS/BRAF-WT : le nom du gène n’est pas encore une cible thérapeutique","VUS im Onkogen":"VUS dans un oncogène","Initialer Auftrag":"Demande initiale","Einsender":"Prescripteur","Gastroonkologie / Molekulares Tumorboard":"Oncologie digestive / RCP moléculaire","Klinische Information":"Informations cliniques","63-jährige Patientin mit linksseitigem metastasiertem CRC und Progress nach mehreren Therapielinien. Ein externer NGS-Bericht markiert „ERBB2 altered“ prominent.":"Patiente de 63 ans avec CRC métastatique gauche et progression après plusieurs lignes de traitement. Un rapport NGS externe met en évidence de façon proéminente «ERBB2 altered». ","Fragestellung":"Question clinique","Reicht eine seltene ERBB2-Missense-VUS als Grundlage für HER2-gerichtete Therapie?":"Une VUS missense rare d’ERBB2 suffit-elle à justifier un traitement ciblant HER2 ?","Zeitfenster":"Délai","Nächste Therapielinie soll im MTB diskutiert werden.":"La prochaine ligne thérapeutique doit être discutée en RCP moléculaire.","Anamnese und klinischer Kontext":"Antécédents et contexte clinique","Molekularer Kontext":"Contexte moléculaire","KRAS/NRAS/BRAF wildtyp, pMMR/MSS.":"KRAS/NRAS/BRAF de type sauvage, pMMR/MSS.","Externer Report":"Rapport externe","Seltene ERBB2-Missense-Variante, VAF 18 %, Klassifikation VUS; im Summary trotzdem gelb als „potential target“ hervorgehoben.":"Variant missense rare d’ERBB2, VAF 18 %, classée VUS ; néanmoins surlignée en jaune dans le résumé comme « potential target ». ","Didaktische Falle":"Piège pédagogique","Genname, Datenbanktreffer und Actionability werden miteinander vermischt.":"Le nom du gène, le résultat de base de données et l’actionnabilité sont confondus.","Ziel":"Objectif","Variante, Biomarker und klinische Evidenz getrennt bewerten.":"Évaluer séparément le variant, le biomarqueur et les données cliniques.","Histologie + Vorinformation":"Histologie + informations antérieures","Histologie":"Histologie","Metastasiertes kolorektales Adenokarzinom.":"Adénocarcinome colorectal métastatique.","HER2-IHC":"IHC HER2","noch nicht erfolgt.":"pas encore réalisée.","ISH":"ISH","Offen":"En attente","Gibt es unabhängig von der VUS einen etablierten HER2-Biomarker?":"Existe-t-il un biomarqueur HER2 établi indépendamment de la VUS ?","Materialprüfung":"Évaluation du matériel","Material":"Matériel","FFPE-Metastase, ausreichend.":"Métastase FFPE, matériel suffisant.","Tumoranteil":"Fraction tumorale","ca. 55 %.":"env. 55 %.","NGS-QC":"QC NGS","Variante technisch robust detektiert.":"Variant détecté avec une forte robustesse technique.","Wichtig":"Important","Technisch echt bedeutet nicht automatisch klinisch bedeutsam.":"Le fait qu’un résultat soit techniquement réel ne signifie pas automatiquement qu’il soit cliniquement pertinent.","ERBB2-Variantenbewertung":"Évaluation du variant ERBB2","VUS-/Evidenzkurationsschritt":"Étape de curation VUS/données","Unabhängigen HER2-Biomarker prüfen":"Évaluer un biomarqueur HER2 indépendant","ERBB2-NGS":"NGS ERBB2","Seltene ERBB2-Missense-Variante, VAF 18 %, technisch robust; aktuelle Klassifikation VUS.":"Variant missense rare d’ERBB2, VAF 18 %, techniquement robuste ; classification actuelle : VUS.","VUS-Curation":"Curation de la VUS","Keine ausreichende klinische Evidenz für prädiktive Actionability; einzelne präklinische Hinweise reichen nicht zur Hochstufung.":"Données cliniques insuffisantes pour une actionnabilité prédictive ; des éléments précliniques isolés ne suffisent pas à reclasser le variant.","HER2 IHC 1+, keine starke membranöse Überexpression.":"IHC HER2 1+, sans forte surexpression membranaire.","HER2-FISH/ISH":"FISH/ISH HER2","Keine ERBB2-Amplifikation.":"Pas d’amplification d’ERBB2.","Fehlentscheidung":"Décision incorrecte","Eine direkte HER2-Therapieempfehlung allein aus einer VUS wäre ein Evidenz-Overcall.":"Recommander directement un traitement ciblant HER2 sur la seule base d’une VUS constituerait une surinterprétation des données.","Die VUS ist technisch real detektiert.":"La VUS est techniquement réelle.","Kernaussage":"Message clé","Technische Echtheit, Pathogenität und prädiktive Actionability sind drei getrennte Ebenen.":"La validité technique, la pathogénicité et l’actionnabilité prédictive sont trois niveaux distincts.","Die ERBB2-Variante ist technisch robust, aber klinisch weiterhin VUS und darf nicht als gesicherter prädiktiver Biomarker behandelt werden. HER2-IHC 1+ und fehlende ERBB2-Amplifikation liefern keinen unabhängigen etablierten HER2-Amplifikationskontext. Eine Therapieempfehlung allein aus der VUS wäre nicht evidenzbasiert.":"Le variant ERBB2 est techniquement robuste mais reste cliniquement une VUS et ne doit pas être considéré comme un biomarqueur prédictif établi. Une IHC HER2 1+ et l’absence d’amplification d’ERBB2 n’apportent pas de contexte indépendant établi d’amplification HER2. Une recommandation thérapeutique fondée uniquement sur la VUS ne serait pas basée sur les preuves.","Teilbefund: Ein technisch echter Variantenfund ist ohne belastbare funktionelle/klinische Evidenz nicht automatisch actionable.":"Résultat partiel : un variant techniquement réel n’est pas automatiquement actionnable sans données fonctionnelles/cliniques robustes.","VUS klar als VUS benennen":"Identifier clairement la VUS comme VUS","technische Validität, Pathogenität und Actionability trennen":"séparer validité technique, pathogénicité et actionnabilité","IHC/ISH als separaten Biomarkerpfad verstehen":"comprendre l’IHC/ISH comme une voie biomarqueur HER2 distincte","Falschaussage: ERBB2 steht im Genfeld, also ist HER2-Therapie indiziert":"Affirmation fausse : ERBB2 figure dans le champ du gène, donc un traitement ciblant HER2 est indiqué","Optimale Lösung: ERBB2-VUS nicht overcallen, unabhängige HER2-Biomarker separat prüfen und die Therapieaussage an Evidenz statt an Genname oder Datenbankfarbe koppeln.":"Solution optimale : ne pas surinterpréter la VUS d’ERBB2, évaluer séparément les biomarqueurs HER2 indépendants et fonder la conclusion thérapeutique sur les données plutôt que sur le nom du gène ou la couleur d’une base de données.","VUS":"VUS","ERBB2":"ERBB2","HER2":"HER2","Evidenz":"Données probantes","MTB":"MTB","Deep Dive":"Deep Dive","Das gelbe „potential target“":"Le « potential target » en jaune","Molekulares Tumorboard / Varianteninterpretation":"RCP moléculaire / interprétation des variants","VUS nicht als pathogene/actionable Variante berichten.":"Ne pas rapporter une VUS comme pathogène/actionnable.","Technische Validität, biologische Pathogenität und klinische Prädiktion trennen.":"Séparer validité technique, pathogénicité biologique et prédiction clinique.","IHC/ISH bei HER2 als eigenständigen Biomarkerpfad einordnen.":"Considérer l’IHC/ISH HER2 comme une voie biomarqueur indépendante.","Datenbank-/Software-Highlights nicht mit klinischer Evidenz verwechseln.":"Ne pas confondre les mises en évidence de bases de données/logiciels avec les données cliniques.","Im externen Report ist ERBB2 gelb hervorgehoben: „potential target“. In der Detailzeile steht jedoch schlicht VUS. Der Fall ist ein Test dafür, ob das Board die Farbe oder die Evidenz liest.":"Dans le rapport externe, ERBB2 est surligné en jaune : « potential target ». Pourtant, la ligne détaillée indique simplement VUS. Le cas teste si la RCP lit la couleur ou les preuves.","63-jährige Patientin mit RAS/BRAF-WT-mCRC. Eine seltene ERBB2-Missense-Variante ist technisch sicher detektiert, aber als VUS klassifiziert. Das Board soll entscheiden, ob daraus eine HER2-gerichtete Therapieaussage entsteht.":"Patiente de 63 ans avec mCRC RAS/BRAF-WT. Un variant missense rare d’ERBB2 est techniquement bien établi mais classé VUS. La RCP doit décider si cela permet une conclusion thérapeutique ciblant HER2.","Drei Ebenen":"Trois niveaux","Call echt? Variante pathogen? Befund prädiktiv?":"Call réel ? Variant pathogène ? Résultat prédictif ?","Diese Ebenen dürfen nicht zusammenfallen.":"Ces niveaux ne doivent pas être confondus.","HER2 ist mehr als ein Genname":"HER2 ne se résume pas à un nom de gène","Amplifikation/Überexpression und einzelne Sequenzvarianten sind unterschiedliche Biomarker.":"L’amplification/surexpression et les variants de séquence individuels sont des biomarqueurs différents.","Methoden beantworten verschiedene Fragen.":"Les méthodes répondent à des questions différentes.","Software ist keine Leitlinie":"Un logiciel n’est pas une recommandation clinique","Ein automatisch hervorgehobener Datenbanktreffer kann evidenzarm sein.":"Un résultat de base de données automatiquement mis en évidence peut reposer sur des données faibles.","Finale Interpretation bleibt fachlich verantwortlich.":"L’interprétation finale reste une responsabilité professionnelle.","ERBB2-Variante":"Variant ERBB2","VAF 18 %, technisch robust, Klassifikation VUS":"VAF 18 %, techniquement robuste, classée VUS","RAS/BRAF":"RAS/BRAF","MMR/MSI":"MMR/MSI","pMMR/MSS":"pMMR/MSS","Material ausreichend.":"Matériel suffisant.","Keine analytische Unsicherheit des Calls – die Unsicherheit ist interpretativ.":"Il n’existe pas d’incertitude analytique sur le call ; l’incertitude est interprétative.","Der Fall verlangt keine Therapieempfehlung aus einem nicht etablierten VUS.":"Le cas ne demande pas de recommandation thérapeutique à partir d’une VUS non établie.","Was ist die korrekte Bedeutung einer technisch robusten ERBB2-VUS?":"Quelle est la signification correcte d’une VUS d’ERBB2 techniquement robuste ?","Die Variante ist nach aktueller Evidenz nicht ausreichend als pathogen/prädiktiv klassifiziert.":"Selon les données actuelles, le variant n’est pas suffisamment classé comme pathogène/prédictif.","Jede ERBB2-Variante ist actionable.":"Tout variant ERBB2 est actionnable.","VUS bedeutet sicher benign.":"VUS signifie certainement bénin.","VUS bedeutet Keimbahn.":"VUS signifie germinal.","VUS beschreibt unzureichende Evidenz, nicht eine halbe Therapieindikation.":"Une VUS décrit des données insuffisantes, pas une demi-indication thérapeutique.","Welche Ebenen müssen getrennt bewertet werden?":"Quels niveaux doivent être évalués séparément ?","analytische Echtheit des Calls":"validité analytique du call","Pathogenität/biologische Bedeutung":"pathogénicité/signification biologique","klinisch-prädiktive Evidenz":"données cliniques prédictives","Farbe im Software-Report":"couleur dans le rapport logiciel","Der Software-Look ist keine Evidenzebene.":"L’apparence dans le logiciel n’est pas un niveau de preuve.","HER2 IHC 1+ und keine ERBB2-Amplifikation: Was folgt daraus?":"IHC HER2 1+ et absence d’amplification d’ERBB2 : qu’en conclure ?","Es liegt kein unabhängiger etablierter Amplifikations-/Überexpressionsbefund vor, der die VUS „rettet“.":"Il n’existe pas de résultat indépendant établi d’amplification/surexpression qui « sauve » la VUS.","Damit wird die VUS automatisch pathogen.":"Cela rend automatiquement la VUS pathogène.","HER2-Therapie ist allein dadurch zwingend.":"Sur cette seule base, un traitement ciblant HER2 est obligatoire.","IHC/ISH und Sequenzierung messen exakt dasselbe.":"L’IHC/ISH et le séquençage mesurent exactement la même chose.","Die Methoden adressieren unterschiedliche Biomarker.":"Les méthodes évaluent des biomarqueurs différents.","Eine Datenbank nennt einen präklinischen Zelllinienhinweis. Reicht das zur Therapieableitung?":"Une base de données cite un résultat préclinique sur une lignée cellulaire. Est-ce suffisant pour déduire un traitement ?","Nein; präklinische Hinweise können Hypothesen stützen, ersetzen aber keine ausreichende klinische Evidenz für diese VUS.":"Non ; des résultats précliniques peuvent soutenir des hypothèses mais ne remplacent pas des données cliniques suffisantes pour cette VUS.","Ja, jeder präklinische Treffer macht eine VUS actionable.":"Oui, tout résultat préclinique rend une VUS actionnable.","Literatur ist grundsätzlich irrelevant.":"La littérature est fondamentalement sans intérêt.","Die Variante wird automatisch Tier I.":"Le variant devient automatiquement Tier I.","Evidenzhierarchie und variantenspezifische Daten müssen berücksichtigt werden.":"La hiérarchie des preuves et les données spécifiques au variant doivent être prises en compte.","Formulieren Sie eine MTB-Kernaussage, die den ERBB2-Fund korrekt einordnet, ohne ihn zu overcallen.":"Formulez un message clé pour la RCP qui classe correctement le résultat ERBB2 sans le surinterpréter.","Technische Echtheit bestätigen.":"Confirmer la validité technique.","Aktuelle Variantenklassifikation übernehmen bzw. fachlich kuratieren.":"Reprendre ou curer professionnellement la classification actuelle du variant.","Keine Pathogenität/Actionability aus dem Genname ableiten.":"Ne pas déduire pathogénicité/actionnabilité du nom du gène.","HER2-IHC/ISH als separaten Biomarkerpfad bewerten.":"Évaluer l’IHC/ISH HER2 comme une voie biomarqueur distincte.","VUS klar und nicht handlungsleitend kommunizieren; Re-Evaluation bei neuer Evidenz möglich.":"Communiquer clairement que la VUS ne guide pas la conduite ; une réévaluation est possible si de nouvelles données apparaissent.","Studieneinschluss kann je nach Protokoll breitere molekulare Kriterien verwenden; das ist von einer etablierten Therapieempfehlung zu trennen.":"Selon le protocole, l’inclusion dans un essai peut utiliser des critères moléculaires plus larges ; cela doit être distingué d’une recommandation thérapeutique établie.","Genname = Target":"Nom du gène = cible","Ignoriert Variantenspezifität und Evidenz.":"Ignore la spécificité du variant et les données.","VUS = benign":"VUS = bénin","Unsicherheit wird fälschlich in Harmlosigkeit umgedeutet.":"L’incertitude est à tort réinterprétée comme bénignité.","IHC/ISH macht Missense-VUS pathogen":"L’IHC/ISH rend une VUS missense pathogène","Unterschiedliche Biomarkerfragen werden vermischt.":"Des questions de biomarqueurs différentes sont confondues.","Die Variante ist echt – und trotzdem kein Target":"Le variant est réel — et pourtant ce n’est pas une cible","Curation bestätigt die technische Echtheit, aber nicht die klinische Actionability. HER2-IHC/ISH liefern ebenfalls keinen unabhängigen etablierten HER2-Befund.":"La curation confirme la validité technique mais pas l’actionnabilité clinique. L’IHC/ISH HER2 n’apporte pas non plus de résultat HER2 indépendant établi.","Der Twist ist kein Laborfehler, sondern die Trennung von Detektion und Bedeutung.":"Le retournement n’est pas une erreur de laboratoire, mais la séparation entre détection et signification.","VUS sauber begrenzt":"VUS correctement délimitée","Technisch echt, klinisch unklar, kein Overcalling.":"Techniquement réelle, cliniquement incertaine, sans surinterprétation.","Evidenzgerechte MTB-Kommunikation.":"Communication en RCP fondée sur les données.","Direkt HER2-Therapie":"Traitement HER2 direct","VUS wird wie ein etablierter Biomarker behandelt.":"La VUS est traitée comme un biomarqueur établi.","Kritischer Interpretationsfehler.":"Erreur critique d’interprétation.","VUS verschwiegen":"VUS omise","Unsicherheit wird nicht transparent kommuniziert.":"L’incertitude n’est pas communiquée de manière transparente.","Besser klar benennen und begrenzen.":"Mieux vaut la nommer et la délimiter clairement.","VUS ohne ausreichende prädiktive Evidenz":"VUS sans données prédictives suffisantes","nicht als gesichertes Target formulieren":"ne pas la présenter comme une cible établie","ggf. Re-Evaluation bei neuer Evidenz.":"envisager une réévaluation si de nouvelles données apparaissent.","VUS ist eine Evidenzkategorie.":"La VUS est une catégorie de preuve.","Softwareannotation ersetzt keine fachliche Varianteninterpretation.":"L’annotation logicielle ne remplace pas l’interprétation professionnelle des variants.","Ein Gen kann mehrere völlig unterschiedliche Biomarkerarten tragen.":"Un gène peut porter plusieurs types de biomarqueurs totalement différents.","ERBB2-VUS technisch bestätigt, jedoch ohne ausreichende klinisch-prädiktive Evidenz; HER2 IHC/ISH ohne unabhängigen positiven Biomarker. Keine etablierte Therapieableitung allein aus der VUS.":"VUS d’ERBB2 techniquement confirmée, mais sans données cliniques prédictives suffisantes ; IHC/ISH HER2 sans biomarqueur positif indépendant. Aucune implication thérapeutique établie sur la seule base de la VUS.","Evidenzhierarchie":"Hiérarchie des preuves","Variantenspezifität":"Spécificité du variant","MTB-Kommunikation":"Communication RCP","Wann darf eine VUS reklassifiziert werden?":"Quand une VUS peut-elle être reclassée ?","Wie häufig sollte Re-Annotation erfolgen?":"À quelle fréquence faut-il réannoter ?","Wie verhindert man Software-bedingtes Overcalling?":"Comment prévenir la surinterprétation induite par le logiciel ?","Twist: technisch echt ≠ klinisch actionable":"Retournement : techniquement réel ≠ cliniquement actionnable","HER2-IHC/ISH und Sequenz-VUS getrennt":"IHC/ISH HER2 et VUS de séquence évaluées séparément","Referenzpfad: Call → Klassifikation → Evidenz → klinische Aussage":"Parcours de référence : call → classification → preuves → conclusion clinique","ALK/ROS1/RET/NTRK-Fusionsverdacht bei jungem Nie-Raucher → FISH, RNA-NGS oder DNA-NGS?":"Suspicion de fusion ALK/ROS1/RET/NTRK chez une jeune patiente jamais fumeuse → FISH, NGS ARN ou NGS ADN ?","ALK/ROS1/RET/NTRK-Fusionsverdacht …":"Suspicion de fusion ALK/ROS1/RET/NTRK …","Thoraxonkologie / Molekulares Tumorboard":"Oncologie thoracique / RCP moléculaire","42-jährige Patientin, Nie-Raucherin, metastasiertes pulmonales Adenokarzinom mit Leber- und Knochenmetastasen.":"Patiente de 42 ans, jamais fumeuse, présentant un adénocarcinome pulmonaire métastatique avec métastases hépatiques et osseuses.","Ein externes DNA-basiertes Panel meldet keinen therapierbaren Treiber. Ist die molekulare Abklärung damit abgeschlossen oder muss eine Fusionsdiagnostik ergänzt werden?":"Un panel externe basé sur l’ADN ne rapporte aucun driver actionnable. Le bilan moléculaire est-il complet ou faut-il ajouter une recherche de fusions ?","Die Erstlinientherapie soll im MTB in fünf Tagen festgelegt werden.":"Le traitement de première ligne doit être défini en RCP moléculaire dans cinq jours.","Raucherstatus":"Statut tabagique","Nie-Raucherin, keine relevante berufliche Exposition.":"Jamais fumeuse, sans exposition professionnelle pertinente.","Klinischer Verlauf":"Évolution clinique","ECOG 1, symptomatische ossäre Metastase, insgesamt aber klinisch stabil.":"ECOG 1, métastase osseuse symptomatique, mais état clinique globalement stable.","Vorbefund":"Résultat antérieur","Externes DNA-NGS ohne EGFR-, KRAS-, BRAF-, MET-Exon-14- oder ERBB2-Alteration; der Bericht enthält keine belastbare Aussage zur RNA-basierten Fusionserfassung.":"NGS ADN externe sans altération EGFR, KRAS, BRAF, MET exon 14 ni ERBB2 ; le rapport ne fournit pas de conclusion robuste sur la détection des fusions basée sur l’ARN.","Entscheidungsdruck":"Pression décisionnelle","Die Onkologie erwägt bereits eine nicht zielgerichtete Systemtherapie, falls kein Treiber gefunden wird.":"L’oncologie envisage déjà un traitement systémique non ciblé si aucun driver n’est identifié.","HE":"HES","Mäßig differenziertes pulmonales Adenokarzinom in einer Lebermetastasenbiopsie.":"Adénocarcinome pulmonaire moyennement différencié dans une biopsie de métastase hépatique.","IHC":"IHC","TTF-1 und Napsin A positiv; p40 negativ. Die Morphologie und der klinische Kontext stützen einen pulmonalen Primarius.":"TTF-1 et Napsine A positifs ; p40 négatif. La morphologie et le contexte clinique sont en faveur d’une origine pulmonaire.","Biologischer Hinweis":"Indice biologique","Junges Alter und Nie-Raucherstatus erhöhen die Aufmerksamkeit für eine onkogene Treiberalteration, ersetzen aber keinen methodisch vollständigen Nachweis.":"Le jeune âge et l’absence de tabagisme renforcent la suspicion d’une altération driver oncogénique, mais ne remplacent pas un bilan méthodologiquement complet.","Offene Frage":"Question ouverte","Wurden ALK-, ROS1-, RET- und NTRK-Fusionen mit einer dafür geeigneten Methode tatsächlich ausreichend ausgeschlossen?":"Les fusions ALK, ROS1, RET et NTRK ont-elles réellement été exclues par une méthode appropriée ?","FFPE-Leberbiopsie, Block M2.":"Biopsie hépatique FFPE, bloc M2.","ca. 35–40 %, nach Markierung gut geeignet.":"env. 35–40 %, bien adapté après repérage.","RNA-Prognose":"Pronostic ARN","RNA-Qualität nach Vorprüfung grenzwertig bis ausreichend; noch genügend Material für einen gezielten RNA-Ansatz.":"La qualité de l’ARN est limite à suffisante après évaluation préliminaire ; il reste assez de matériel pour une approche ARN ciblée.","Schnittbudget":"Budget de lames","8 ungefärbte Schnitte verfügbar.":"8 coupes non colorées disponibles.","Materialfalle":"Piège lié au matériel","Ein wiederholtes DNA-only-Panel verbraucht Material und kann die eigentliche Fusionsfrage trotzdem offenlassen.":"Répéter un panel ADN seul consomme du matériel et peut encore laisser sans réponse la véritable question des fusions.","Breite Fusionsdiagnostik":"Recherche large de fusions","DNA-NGS":"NGS ADN","Kein relevanter SNV/Indel-Treiber nachweisbar. Die konkrete Assay-Konfiguration erlaubt keinen belastbaren Ausschluss aller klinisch relevanten Fusionen.":"Aucun driver SNV/indel pertinent détecté. La configuration spécifique de l’essai ne permet pas d’exclure de façon fiable toutes les fusions cliniquement pertinentes.","RNA-Fusionsdiagnostik":"Recherche de fusions par ARN","KIF5B::RET-Fusion nachweisbar; in-frame und exprimiert. Der Befund erklärt den bisher DNA-negativen Treiberstatus.":"Fusion KIF5B::RET détectée, in-frame et exprimée. Le résultat explique le statut driver précédemment négatif en ADN.","FISH":"FISH","Bei gezielter RET-FISH zeigt sich ein Rearrangement. Die Methode bestätigt die Umlagerung, liefert aber nicht die Breite einer parallelen RNA-Fusionsanalyse.":"Une FISH ciblée RET montre un réarrangement. La méthode confirme le réarrangement mais n’offre pas l’étendue d’une analyse parallèle des fusions par ARN.","QC":"QC","Tumorzellanteil ausreichend. RNA ist knapp, aber nach QC verwertbar; Material Stewardship bleibt relevant.":"Fraction tumorale suffisante. L’ARN est limité mais exploitable après QC ; la gestion raisonnée du matériel reste importante.","Die RNA-basierte Fusionsdiagnostik weist eine therapeutisch relevante KIF5B::RET-Fusion nach. Der zuvor negative DNA-Befund war kein belastbarer Ausschluss einer onkogenen Fusion.":"La recherche de fusions basée sur l’ARN détecte une fusion KIF5B::RET thérapeutiquement pertinente. Le résultat ADN précédemment négatif n’excluait pas de manière fiable une fusion oncogénique.","Teilbefund: Eine gezielte Einzelmethode oder DNA-only-Strategie kann die breite Fusionsfrage nicht vollständig beantworten. Eine RNA-basierte Fusionsdiagnostik sollte ergänzt werden.":"Résultat partiel : une méthode ciblée unique ou une stratégie ADN seule ne permet pas de répondre complètement à la question large des fusions. Une recherche de fusions basée sur l’ARN doit être ajoutée.","Die RET-Fusion als therapieentscheidenden Treiber benennen":"Identifier la fusion RET comme driver déterminant pour le traitement","DNA-only nicht mit umfassend treibernegativ gleichsetzen":"ne pas assimiler ADN seul à un statut globalement négatif pour les drivers","FISH als gezielte Bestätigungs-/Alternativmethode, nicht als universellen Ersatz einer breiten RNA-Analyse einordnen":"considérer la FISH comme méthode ciblée de confirmation/alternative, et non comme substitut universel à une analyse ARN large","Assay- und RNA-QC-Limitationen transparent kommunizieren":"communiquer de façon transparente les limites de l’essai et du QC ARN","Optimale Lösung: vorhandenen DNA-Befund methodisch prüfen und die offene Fusionsfrage mit einer breiten RNA-basierten Analyse schließen; gezielte FISH kann bei konkreter Hypothese ergänzen.":"Solution optimale : revoir méthodologiquement le résultat ADN existant et résoudre la question ouverte des fusions par une analyse ARN large ; une FISH ciblée peut compléter en cas d’hypothèse précise.","NSCLC":"NSCLC","NGS":"NGS","RNA":"ARN","MVP":"MVP","Standard":"Standard","Junge Nie-Raucherin mit DNA-negativem NSCLC: Ist der Tumor wirklich treibernegativ?":"Jeune patiente jamais fumeuse avec NSCLC négatif en ADN : la tumeur est-elle réellement sans driver ?","Molekularpathologie / Thoraxonkologie / MTB":"Pathologie moléculaire / Oncologie thoracique / RCP","Einen negativen DNA-NGS-Befund nur innerhalb der tatsächlich validierten Assaygrenzen interpretieren.":"Interpréter un résultat NGS ADN négatif uniquement dans les limites réellement validées de l’essai.","RNA-basierte Fusionsdiagnostik bei klinisch plausibler Fusionsfrage gegenüber serieller FISH und erneutem DNA-only-Test priorisieren.":"Prioriser la recherche de fusions basée sur l’ARN par rapport à des FISH sérielles et à la répétition d’un test ADN seul lorsqu’une fusion est cliniquement plausible.","FISH als gezielte orthogonale Methode sinnvoll einordnen, ohne sie mit einer breiten parallelen Fusionssuche gleichzusetzen.":"Positionner correctement la FISH comme méthode orthogonale ciblée sans l’assimiler à un dépistage large et parallèle des fusions.","Einen methodisch unvollständigen 'kein Treiber'-Befund im MTB aktiv korrigieren.":"Corriger activement en RCP un résultat « sans driver » méthodologiquement incomplet.","Mittwochmorgen vor dem Thorax-MTB. Auf dem Bildschirm steht bei einer 42-jährigen Nie-Raucherin mit metastasiertem Lungenadenokarzinom bereits der externe Satz: 'Kein therapeutisch relevanter Treiber nachweisbar.' Die Onkologie plant deshalb eine nicht zielgerichtete Systemtherapie. Beim Lesen des Methodenteils fällt jedoch auf: Untersucht wurde ein DNA-only-Panel; eine belastbare RNA-basierte Fusionsdiagnostik ist nicht dokumentiert. Aus einem scheinbar abgeschlossenen Befund wird wieder eine offene Therapiefrage.":"Mercredi matin avant la RCP thoracique. À l’écran, le rapport externe d’une patiente de 42 ans, jamais fumeuse, présentant un adénocarcinome pulmonaire métastatique indique déjà : « Aucun driver thérapeutiquement pertinent détecté ». L’oncologie prévoit donc un traitement systémique non ciblé. Mais la section méthodologique révèle qu’un panel ADN seul a été réalisé ; aucune recherche robuste de fusions basée sur l’ARN n’est documentée. Un résultat apparemment clos redevient une question thérapeutique ouverte.","42-jährige Nie-Raucherin, ECOG 1, pulmonales Adenokarzinom mit Leber- und Knochenmetastasen. Externes DNA-NGS ohne relevante SNV/Indel-Treiber. Für das MTB muss entschieden werden, ob dieser Befund als treibernegativ akzeptiert werden kann oder ob die offene ALK/ROS1/RET/NTRK-Fusionsfrage mit einer geeigneten Methode geschlossen werden muss.":"Patiente de 42 ans, jamais fumeuse, ECOG 1, avec adénocarcinome pulmonaire et métastases hépatiques et osseuses. Le NGS ADN externe ne montre aucun driver SNV/indel pertinent. La RCP doit décider si ce résultat peut être considéré comme négatif pour les drivers ou si la question ouverte des fusions ALK/ROS1/RET/NTRK doit être résolue par une méthode adaptée.","Klinischer Kontext":"Contexte clinique","Junges Alter, Nie-Raucherstatus und Adenokarzinom machen eine onkogene Treiberalteration plausibel, beweisen sie aber nicht.":"Le jeune âge, l’absence de tabagisme et l’adénocarcinome rendent plausible une altération driver oncogénique sans la prouver.","Klinische Plausibilität steuert die Aufmerksamkeit; die Diagnose entsteht aus Methodik und Befund.":"La plausibilité clinique oriente l’attention ; le diagnostic repose sur la méthode et le résultat.","Externer Befund":"Résultat externe","DNA-NGS: EGFR, KRAS, BRAF, MET-Exon-14 und ERBB2 ohne relevante Alteration. Der Methodenteil beschreibt keine validierte breite RNA-Fusionsanalyse.":"NGS ADN : EGFR, KRAS, BRAF, MET exon 14 et ERBB2 sans altération pertinente. La section méthodologique ne décrit aucune analyse large et validée des fusions par ARN.","'Negativ' ist nur so breit wie der verwendete Assay.":"« Négatif » n’est jamais plus large que l’essai utilisé.","Leberbiopsie mit 35–40 % Tumor, acht ungefärbte Schnitte. RNA-QC ist grenzwertig bis ausreichend.":"Biopsie hépatique avec 35–40 % de tumeur, huit coupes non colorées. Le QC ARN est limite à suffisant.","Jetzt ist eine gezielte, informationsreiche Ergänzung sinnvoller als serielle Einzeltests.":"Un complément ciblé et riche en information est désormais plus utile que des tests unitaires sériels.","MTB-Druck":"Pression temporelle de la RCP","Therapieentscheidung in fünf Tagen; jeder unnötige Zusatzlauf kostet Zeit und Material.":"Décision thérapeutique dans cinq jours ; chaque run supplémentaire inutile coûte du temps et du matériel.","TAT und Material Stewardship gehören zur klinischen Methodenauswahl.":"Le TAT et la gestion raisonnée du matériel font partie du choix clinique de la méthode.","HE/IHC":"HES/IHC","Metastase eines TTF-1-/Napsin-A-positiven pulmonalen Adenokarzinoms.":"Métastase d’un adénocarcinome pulmonaire TTF-1/Napsine A positif.","DNA-NGS extern":"NGS ADN externe","Kein relevanter SNV/Indel-Treiber; Fusionsabdeckung nicht ausreichend dokumentiert.":"Aucun driver SNV/indel pertinent ; la couverture des fusions n’est pas suffisamment documentée.","RNA-QC":"QC ARN","RNA ist nicht perfekt, aber für einen zielgerichteten Fusionsassay noch verwertbar.":"L’ARN n’est pas parfait, mais reste exploitable pour un essai ciblé de fusions.","Nur acht ungefärbte Schnitte verbleiben.":"Il ne reste que huit coupes non colorées.","TAT-Ziel fünf Tage bis MTB.":"Objectif TAT : cinq jours avant la RCP.","Eine breite serielle FISH-Strategie würde mehrere Einzelansätze und Vorannahmen benötigen.":"Une stratégie large de FISH sérielles nécessiterait plusieurs tests individuels et des hypothèses préalables.","Ein erneutes DNA-only-Panel kann denselben methodischen blinden Fleck reproduzieren.":"Répéter un panel ADN seul peut reproduire le même angle mort méthodologique.","Was bedeutet der externe Satz 'kein therapeutisch relevanter Treiber nachweisbar' in diesem Fall?":"Que signifie dans ce cas la phrase externe « aucun driver thérapeutiquement pertinent détecté » ?","Alle relevanten Treiber einschließlich Fusionen sind sicher ausgeschlossen.":"Tous les drivers pertinents, y compris les fusions, ont été exclus avec certitude.","Er gilt nur innerhalb der validierten DNA-Assaygrenzen; die Fusionsfrage bleibt offen.":"Elle ne vaut que dans les limites validées de l’essai ADN ; la question des fusions reste ouverte.","Bei Nie-Rauchern ist ein negativer Befund grundsätzlich falsch.":"Chez les non-fumeurs, un résultat négatif est toujours faux.","Er bedeutet automatisch, dass jetzt jede Fusion einzeln per FISH getestet werden muss.":"Cela signifie automatiquement que chaque fusion doit maintenant être testée individuellement par FISH.","Ein negativer molekularer Befund ist immer an die analytische Abdeckung der verwendeten Methode gebunden.":"Un résultat moléculaire négatif est toujours limité par la couverture analytique de la méthode utilisée.","Welche Ergänzung beantwortet die offene breite Fusionsfrage am effizientesten?":"Quel examen complémentaire répond le plus efficacement à la question large et ouverte des fusions ?","Breites RNA-basiertes Fusionspanel":"Panel large de fusions basé sur l’ARN","Dasselbe DNA-only-Panel noch einmal":"Le même panel ADN seul à nouveau","Eine einzelne ALK-FISH als vollständiger Ersatz":"Une seule FISH ALK comme substitut complet","Keine Ergänzung, weil die Histologie bereits eindeutig ist":"Aucun examen complémentaire car l’histologie est déjà sans équivoque","RNA-NGS kann mehrere exprimierte Fusionsereignisse parallel erfassen und ist für diese offene Fragestellung besonders geeignet.":"Le NGS ARN peut détecter en parallèle plusieurs événements de fusion exprimés et convient particulièrement à cette question ouverte.","Wann bleibt FISH in diesem Fall sinnvoll?":"Quand la FISH reste-t-elle utile dans ce cas ?","Bei konkreter Genhypothese als schnelle/orthogonale Bestätigung":"Pour une hypothèse génique précise, comme confirmation rapide/orthogonale","Wenn RNA nicht verwertbar ist und ein gezielter Rearrangement-Nachweis benötigt wird":"Lorsque l’ARN est inexploitable et qu’une détection ciblée de réarrangement est nécessaire","Als universell umfassender Ersatz für eine breite RNA-Fusionsanalyse":"Comme substitut universel et exhaustif d’une analyse large des fusions par ARN","Zur sicheren Bestimmung jedes Fusionspartners":"Pour déterminer de façon fiable chaque partenaire de fusion","FISH ist für gezielte Rearrangement-Fragen nützlich, aber meist weniger breit und partnerinformativ als RNA-basierte Verfahren.":"La FISH est utile pour des questions ciblées de réarrangement, mais elle est généralement moins large et moins informative sur le partenaire que les méthodes basées sur l’ARN.","Entscheiden Sie, ob der externe DNA-negative Befund als vollständig akzeptiert werden kann und welche Ergänzung jetzt mit dem verbliebenen Material die größte klinische Information liefert.":"Décidez si le résultat ADN externe négatif peut être considéré comme complet et quel examen complémentaire apporte maintenant le plus d’information clinique avec le matériel restant.","Methodenteil des externen DNA-Befunds prüfen und die unzureichend geklärte Fusionsabdeckung benennen.":"Revoir la section méthodologique du résultat ADN externe et signaler la couverture des fusions insuffisamment clarifiée.","RNA-basiertes Fusionspanel priorisieren.":"Prioriser un panel de fusions basé sur l’ARN.","Material aus dem markierten Tumorareal gezielt für RNA aufarbeiten.":"Traiter spécifiquement pour l’ARN le matériel provenant de la zone tumorale repérée.","FISH nur bei konkreter Hypothese oder nicht verwertbarer RNA als gezielte Alternative/Bestätigung einsetzen.":"Utiliser la FISH uniquement comme alternative/confirmation ciblée en cas d’hypothèse précise ou d’ARN inexploitable.","Im MTB bis zum Abschluss der Fusionsdiagnostik nicht 'treibernegativ' formulieren.":"Ne pas qualifier le cas de « négatif pour les drivers » en RCP avant la fin de la recherche de fusions.","Validiertes kombiniertes DNA/RNA-Pan-Panel, wenn es die relevante Fusionsbreite sicher abdeckt und Material/TAT vertretbar sind.":"Un pan-panel combiné ADN/ARN validé s’il couvre de façon fiable le spectre pertinent des fusions et si le matériel/TAT sont acceptables.","Gezielte RET-FISH, wenn RNA technisch scheitert und die konkrete Hypothese bereits fokussiert ist.":"FISH RET ciblée si l’ARN échoue techniquement et si l’hypothèse précise est déjà focalisée.","DNA-negativ = vollständig negativ":"ADN négatif = complètement négatif","Die Aussage überschreitet die analytische Reichweite des verwendeten Assays.":"L’affirmation dépasse la portée analytique de l’essai utilisé.","Serielle FISH für jede denkbare Fusion":"FISH sérielles pour chaque fusion envisageable","Material- und zeitintensiv; benötigt Vorannahmen und ist weniger parallelisierbar.":"Coûteux en matériel et en temps ; nécessite des hypothèses préalables et se prête moins au parallélisme.","Noch einmal dasselbe DNA-only-Panel":"Répéter le même panel ADN seul","Wiederholung behebt keinen systematischen Assay-Blindspot.":"Répéter ne corrige pas un angle mort systématique de l’essai.","Der 'treibernegative' Tumor ist nicht treibernegativ":"La tumeur « négative pour les drivers » ne l’est pas","Das RNA-Fusionspanel detektiert eine exprimierte KIF5B::RET-Fusion. Eine anschließende gezielte RET-FISH bestätigt ein Rearrangement. Der zunächst geplante nicht zielgerichtete Therapieweg muss im MTB neu bewertet werden.":"Le panel de fusions ARN détecte une fusion KIF5B::RET exprimée. Une FISH RET ciblée secondaire confirme un réarrangement. La stratégie thérapeutique non ciblée initialement prévue doit être réévaluée en RCP.","Der Fehler lag nicht in der Qualität des ersten DNA-Laufs, sondern in der zu breiten Interpretation eines methodisch begrenzten Negativbefunds.":"L’erreur ne résidait pas dans la qualité du premier run ADN, mais dans l’interprétation trop large d’un résultat négatif méthodologiquement limité.","RNA schließt die offene Lücke":"L’ARN comble la lacune","KIF5B::RET-Fusion nachweisbar; DNA-SNV/Indel-Profil ohne weiteren relevanten Treiber.":"Fusion KIF5B::RET détectée ; profil SNV/indel ADN sans autre driver pertinent.","Sehr gut: Assaygrenze erkannt, passende Methode ergänzt, klinisch entscheidenden Treiber gefunden.":"Excellent : limite de l’essai reconnue, méthode adaptée ajoutée, driver cliniquement décisif identifié.","DNA-only bleibt Endpunkt":"L’ADN seul reste le point final","Kein SNV/Indel-Treiber; Fusionsstatus bleibt methodisch unzureichend geklärt.":"Aucun driver SNV/indel ; le statut des fusions reste méthodologiquement insuffisamment clarifié.","Der Befund klingt abgeschlossen, ist es aber nicht.":"Le rapport semble complet, mais ne l’est pas.","Einzel-FISH":"FISH monogénique","Eine gezielte Einzel-FISH kann ein bestimmtes Rearrangement beantworten, lässt andere Fusionsklassen offen.":"Une FISH ciblée unique peut répondre à une question précise de réarrangement mais laisse ouvertes d’autres classes de fusions.","Bei fokussierter Hypothese sinnvoll, als breite Erststrategie unvollständig.":"Utile pour une hypothèse ciblée, incomplète comme stratégie initiale large.","RNA ausreichend":"ARN suffisant","Breites RNA-Fusionspanel durchführen.":"Réaliser un panel large de fusions ARN.","Direkter Nachweis KIF5B::RET und vollständige MTB-Einordnung.":"Détection directe de KIF5B::RET et interprétation complète en RCP.","RNA nicht verwertbar":"ARN inexploitable","Gezielte FISH/alternatives validiertes Material erwägen.":"Envisager une FISH ciblée/un matériel alternatif validé.","Fragestellung wird fokussiert weiterverfolgt statt vorschnell geschlossen.":"La question est poursuivie de façon ciblée plutôt que close prématurément.","Nur DNA ausgewählt":"ADN seul sélectionné","Fusionsdiagnostik nachfordern.":"Demander une recherche de fusions.","Fall ist rettbar, aber TAT und Score verschlechtern sich.":"Le cas peut être rattrapé, mais le TAT et le score se dégradent.","Ein negativer Befund ist kein universeller biologischer Zustand, sondern ein methodisch begrenztes Messergebnis.":"Un résultat négatif n’est pas un état biologique universel, mais un résultat de mesure limité par la méthode.","RNA-basierte Verfahren sind bei vielen Fusionsfragen besonders wertvoll.":"Les méthodes basées sur l’ARN sont particulièrement utiles pour de nombreuses questions de fusion.","FISH bleibt relevant, wenn die Frage gezielt ist oder RNA scheitert.":"La FISH reste pertinente lorsque la question est ciblée ou que l’ARN échoue.","Das Wort 'treibernegativ' sollte nur verwendet werden, wenn die relevanten Alterationsklassen tatsächlich adäquat untersucht wurden.":"Le terme « négatif pour les drivers » ne doit être utilisé que lorsque les classes d’altérations pertinentes ont réellement été étudiées de façon adéquate.","Der externe DNA-Befund darf nicht als vollständiger Treiberausschluss übernommen werden. Die offene Fusionsfrage wird mit einem breiten RNA-basierten Fusionspanel geschlossen. Ergebnis: KIF5B::RET-Fusion. FISH kann gezielt bestätigen oder bei nicht verwertbarer RNA aushelfen.":"Le résultat ADN externe ne doit pas être repris comme exclusion complète des drivers. La question ouverte des fusions est résolue par un panel large basé sur l’ARN. Résultat : fusion KIF5B::RET. La FISH peut confirmer de façon ciblée ou servir d’alternative si l’ARN est inexploitable.","Assaygrenze erkannt":"Limite de l’essai reconnue","RNA-Fusionsdiagnostik priorisiert":"Recherche de fusions ARN priorisée","FISH korrekt eingeordnet":"FISH correctement positionnée","Kein Overclaim eines negativen DNA-Befunds":"Pas de surinterprétation d’un résultat ADN négatif","Wann ist DNA-NGS für Fusionen ausreichend?":"Quand le NGS ADN est-il suffisant pour les fusions ?","Welche Informationen liefert RNA zusätzlich zur strukturellen Umlagerung?":"Quelles informations l’ARN apporte-t-il en plus du réarrangement structurel ?","Wie sollte ein pathologischer Negativbefund formuliert sein, wenn eine relevante Alterationsklasse nicht sicher abgedeckt ist?":"Comment formuler un résultat anatomopathologique négatif lorsqu’une classe d’altérations pertinente n’est pas couverte de façon fiable ?","DE master reviewed structure":"Structure master DE revue","KIF5B::RET trotz DNA-negativem Vorbericht":"KIF5B::RET malgré le rapport ADN négatif antérieur","Negativbefunde sind assaygebunden":"Les résultats négatifs dépendent de l’essai","DNA-negativ → Methodencheck → RNA → Fusion":"ADN négatif → vérification de la méthode → ARN → fusion","KRAS-mutiertes NSCLC mit STK11/KEAP1-Kontext → Target, Prognose, Immuntherapie-Kontext korrekt gewichten":"NSCLC muté KRAS avec contexte STK11/KEAP1 → pondérer correctement cible, pronostic et contexte d’immunothérapie","KRAS-mutiertes NSCLC mit STK11/KEA…":"NSCLC muté KRAS avec STK11/KEA…","Thoraxonkologie / MTB":"Oncologie thoracique / RCP","66-jähriger Patient mit metastasiertem Lungenadenokarzinom. Das DNA-Panel zeigt KRAS p.G12C sowie pathogene STK11- und KEAP1-Alterationen.":"Patient de 66 ans avec adénocarcinome pulmonaire métastatique. Le panel ADN montre KRAS p.G12C ainsi que des altérations pathogènes de STK11 et KEAP1.","Bedeutet die Ko-Mutationskonstellation, dass Immuntherapie nicht sinnvoll ist? Welche Information ist tatsächlich therapeutisch, welche prognostisch und welche nur biologischer Kontext?":"Le profil de comutations signifie-t-il que l’immunothérapie n’est pas utile ? Quelle information est réellement thérapeutique, laquelle pronostique et laquelle relève seulement du contexte biologique ?","Therapieentscheidung im MTB innerhalb einer Woche.":"Décision thérapeutique en RCP dans la semaine.","35 pack years, vor sechs Jahren aufgehört.":"35 paquets-années, arrêt du tabac il y a six ans.","Stadium":"Stade","Leber-, Nebennieren- und ossäre Metastasen; ECOG 1.":"Métastases hépatiques, surrénaliennes et osseuses ; ECOG 1.","Vorbehandlung":"Traitement antérieur","Keine systemische Therapie im metastasierten Stadium.":"Aucun traitement systémique au stade métastatique.","Klinische Falle":"Piège clinique","Im Vorbericht wurde STK11/KEAP1 bereits als 'Immuntherapie-Resistenzmarker' bezeichnet. Das Tumorboard möchte wissen, ob daraus ein Therapieausschluss folgt.":"Le rapport préliminaire a déjà qualifié STK11/KEAP1 de « marqueurs de résistance à l’immunothérapie ». La RCP veut savoir si cela implique une exclusion thérapeutique.","Pulmonales Adenokarzinom mit soliden und azinären Anteilen.":"Adénocarcinome pulmonaire avec contingents solides et acinaires.","TTF-1 positiv, p40 negativ.":"TTF-1 positif, p40 négatif.","PD-L1":"PD-L1","Noch ausstehend.":"En attente.","Molekular":"Moléculaire","KRAS p.G12C, STK11 loss-of-function und KEAP1 loss-of-function; keine klassische EGFR-/ALK-/ROS1-Treiberkonstellation.":"KRAS p.G12C, STK11 loss-of-function et KEAP1 loss-of-function ; pas de profil driver classique EGFR/ALK/ROS1.","Wie werden KRAS-Targetierbarkeit, adverse Ko-Mutationen und Immuntherapie-Kontext getrennt und zusammengeführt?":"Comment séparer puis intégrer la ciblabilité de KRAS, les comutations défavorables et le contexte d’immunothérapie ?","FFPE-Lungenbiopsie mit ca. 45 % Tumoranteil.":"Biopsie pulmonaire FFPE avec env. 45 % de fraction tumorale.","DNA-QC":"QC ADN","ausreichend, Panel vollständig auswertbar.":"suffisant, panel entièrement interprétable.","9 ungefärbte Schnitte verfügbar.":"9 coupes non colorées disponibles.","Zusätzliche explorative Biomarker dürfen nicht den Eindruck erzeugen, es gebe einen validierten Einzeltest, der die Immuntherapieentscheidung sicher vorhersagt.":"Des biomarqueurs exploratoires supplémentaires ne doivent pas donner l’impression qu’il existe un test unique validé prédisant avec certitude la décision d’immunothérapie.","KRAS/STK11/KEAP1-Kontext":"Contexte KRAS/STK11/KEAP1","PD-L1-Kontext":"Contexte PD-L1","KRAS/STK11/KEAP1":"KRAS/STK11/KEAP1","KRAS p.G12C sowie pathogene STK11- und KEAP1-loss-of-function-Alterationen. Die Ko-Mutationen markieren eine biologisch ungünstige Subgruppe, sind aber kein eigenständiger binärer Ausschlusstest für Immuntherapie.":"KRAS p.G12C associé à des altérations pathogènes loss-of-function de STK11 et KEAP1. Les comutations définissent un sous-groupe biologiquement défavorable mais ne constituent pas un test binaire autonome d’exclusion de l’immunothérapie.","PD-L1 TPS 70 %. Hohe Expression ist klinisch relevant, muss aber zusammen mit klinischem Kontext und Ko-Mutationen interpretiert werden.":"PD-L1 TPS 70 %. L’expression élevée est cliniquement pertinente mais doit être interprétée avec le contexte clinique et les comutations.","TMB":"TMB","TMB im intermediären Bereich. Kein Befund, der die komplexe Ko-Mutationskonstellation alleine auflöst.":"TMB dans la zone intermédiaire. Aucun résultat ne résout à lui seul le profil complexe de comutations.","Immun-Kontext-IHC":"IHC du contexte immunitaire","Relativ geringes CD8-positives Infiltrat. Biologisch interessant, aber kein validierter alleiniger Therapieausschlussmarker.":"Infiltrat CD8 positif relativement faible. Biologiquement intéressant, mais pas un marqueur autonome validé d’exclusion thérapeutique.","DNA-QC und Tumoranteil ausreichend; PD-L1 technisch auswertbar.":"QC ADN et fraction tumorale suffisants ; PD-L1 techniquement évaluable.","KRAS p.G12C ist ein potenziell therapeutisch relevanter Genotyp im passenden Behandlungskontext. STK11/KEAP1 sind wichtige adverse biologische/prognostische Ko-Alterationen, dürfen aber nicht als binärer 'kein ICI'-Marker überinterpretiert werden. PD-L1 TPS 70 % bleibt eine eigenständige klinisch relevante Information.":"KRAS p.G12C est un génotype potentiellement pertinent sur le plan thérapeutique dans le contexte de traitement approprié. STK11/KEAP1 sont des co-altérations biologiques/pronostiques défavorables importantes mais ne doivent pas être surinterprétées comme marqueurs binaires « pas d’ICI ». PD-L1 TPS 70 % reste une information clinique pertinente indépendante.","Teilbefund: KRAS/Ko-Mutationen oder PD-L1 fehlen. Ohne beide Ebenen ist eine ausgewogene MTB-Einordnung nicht möglich.":"Résultat partiel : KRAS/comutations ou PD-L1 manquent. Sans ces deux niveaux, une interprétation équilibrée en RCP n’est pas possible.","KRAS p.G12C als Genotyp mit möglicher Target-Relevanz im passenden Therapiekontext benennen":"Identifier KRAS p.G12C comme génotype potentiellement ciblable dans le contexte thérapeutique approprié","STK11/KEAP1 als adverse Kontextmarker, nicht als absoluten ICI-Ausschluss darstellen":"Décrire STK11/KEAP1 comme marqueurs de contexte défavorable, et non comme exclusions absolues des ICI","PD-L1 separat und nicht durch Ko-Mutationen 'weginterpretieren'":"Rapporter PD-L1 séparément et ne pas « l’annuler » du fait des comutations","Prognostische Assoziation und prädiktive Therapieentscheidung sprachlich trennen":"Distinguer dans la formulation association pronostique et décision thérapeutique prédictive","Optimale Lösung: KRAS, STK11/KEAP1 und PD-L1 auf getrennten Evidenzebenen berichten und im MTB integrieren; keine einzelne Ko-Mutation als absoluten Therapieausschluss verwenden.":"Solution optimale : rapporter KRAS, STK11/KEAP1 et PD-L1 à des niveaux de preuve distincts et les intégrer en RCP ; ne jamais utiliser une co-mutation isolée comme exclusion thérapeutique absolue.","Immunescape":"Échappement immunitaire","Phase":"Phase","KRAS/STK11/KEAP1-NSCLC: Kontextmarker sind kein Therapie-Ausschalter":"NSCLC KRAS/STK11/KEAP1 : les marqueurs de contexte ne sont pas des interrupteurs thérapeutiques","KRAS-Targetierbarkeit, STK11/KEAP1-Kontext und PD-L1 auf getrennten Evidenzebenen einordnen.":"Classer la ciblabilité de KRAS, le contexte STK11/KEAP1 et PD-L1 à des niveaux de preuve distincts.","Prognostische bzw. assoziierte Resistenzsignale nicht als validierten binären prädiktiven Ausschlusstest formulieren.":"Ne pas formuler des signaux pronostiques ou associés à la résistance comme un test prédictif binaire validé d’exclusion.","Widersprüchliche Biomarkerinformationen in einer balancierten MTB-Aussage integrieren.":"Intégrer des informations biomarqueurs contradictoires dans une conclusion équilibrée de RCP.","Explorative TME-Marker von klinisch etablierten Routineentscheidungen trennen.":"Séparer les marqueurs exploratoires du TME des décisions de routine cliniquement établies.","Im Thorax-MTB liegt ein Befund mit drei fett markierten Genen: KRAS, STK11 und KEAP1. Der Vorbericht bezeichnet die beiden Ko-Mutationen bereits als 'Immuntherapie-Resistenzmarker'. Gleichzeitig ist PD-L1 noch nicht bestimmt. Die klinische Frage lautet nicht nur, was mutiert ist, sondern ob aus dieser biologisch ungünstigen Konstellation wirklich ein Therapieverbot abgeleitet werden darf.":"En RCP thoracique, le rapport comporte trois gènes en gras : KRAS, STK11 et KEAP1. Le rapport préliminaire qualifie déjà les deux comutations de « marqueurs de résistance à l’immunothérapie ». Parallèlement, PD-L1 n’a pas encore été déterminé. La question clinique n’est pas seulement de savoir ce qui est muté, mais si ce profil biologiquement défavorable justifie réellement une interdiction thérapeutique.","66-jähriger Patient, ehemaliger starker Raucher, metastasiertes Lungenadenokarzinom mit Leber-, Nebennieren- und Knochenmetastasen, ECOG 1. DNA-NGS zeigt KRAS p.G12C plus pathogene STK11- und KEAP1-Alterationen. Das MTB möchte Target-Relevanz, Prognose und Immuntherapie-Kontext sauber gewichten.":"Patient de 66 ans, ancien gros fumeur, avec adénocarcinome pulmonaire métastatique au foie, aux surrénales et aux os, ECOG 1. Le NGS ADN montre KRAS p.G12C associé à des altérations pathogènes de STK11 et KEAP1. La RCP souhaite pondérer correctement pertinence de cible, pronostic et contexte d’immunothérapie.","Genotyp":"Génotype","KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.":"KRAS p.G12C, STK11 loss-of-function, KEAP1 loss-of-function.","Nicht jede genetische Information erfüllt dieselbe klinische Funktion.":"Toutes les informations génétiques n’ont pas la même fonction clinique.","Klinik":"Situation clinique","Hohe Tumorlast, aber aktuell stabil; keine vorangegangene systemische Therapie im metastasierten Stadium.":"Charge tumorale élevée mais actuellement stable ; aucun traitement systémique antérieur au stade métastatique.","Therapieentscheidungen bleiben klinisch eingebettet.":"Les décisions thérapeutiques restent inscrites dans le contexte clinique.","Vorbericht":"Rapport préliminaire","STK11/KEAP1 wurden als 'ICI-resistent' bezeichnet.":"STK11/KEAP1 ont été qualifiés de « résistants aux ICI ».","Assoziation mit ungünstigen Outcomes ist nicht dasselbe wie ein validierter absoluter Ausschlussmarker.":"Une association à des résultats défavorables n’équivaut pas à un marqueur absolu d’exclusion validé.","Offene Information":"Information en attente","PD-L1 steht noch aus; zusätzliche TMB-/TIL-Daten könnten biologischen Kontext liefern, sind aber kein Ersatz für klinische Evidenz.":"PD-L1 est encore en attente ; des données TMB/TIL supplémentaires peuvent apporter un contexte biologique mais ne remplacent pas les données cliniques.","Mehr Biomarker bedeutet nicht automatisch eine klarere Therapieentscheidung.":"Davantage de biomarqueurs ne conduisent pas automatiquement à une décision thérapeutique plus claire.","KRAS p.G12C; pathogene STK11- und KEAP1-loss-of-function-Alterationen.":"KRAS p.G12C ; altérations pathogènes loss-of-function de STK11 et KEAP1.","TTF-1-positives pulmonales Adenokarzinom.":"Adénocarcinome pulmonaire TTF-1 positif.","Noch nicht bestimmt.":"Pas encore déterminé.","Ausreichendes FFPE-Material; keine akute Materialknappheit.":"Matériel FFPE suffisant ; pas de pénurie aiguë de matériel.","Die eigentliche Grenze ist interpretativ: zusätzliche Marker dürfen nicht als stärker validiert erscheinen, als sie sind.":"La véritable limite est interprétative : les marqueurs supplémentaires ne doivent pas paraître plus validés qu’ils ne le sont réellement.","TMB/CD8-IHC können Kontext liefern, sind in diesem Fall aber nicht als zwingende Entscheidungsmarker definiert.":"TMB/IHC CD8 peuvent apporter du contexte mais ne sont pas définis comme marqueurs décisionnels obligatoires dans ce cas.","Welche Aussagen sind fachlich angemessen?":"Quelles affirmations sont professionnellement appropriées ?","KRAS p.G12C kann im geeigneten Therapiekontext targetrelevant sein.":"KRAS p.G12C peut être pertinent comme cible dans le contexte thérapeutique approprié.","STK11/KEAP1 kennzeichnen eine biologisch/prognostisch ungünstige Subgruppe.":"STK11/KEAP1 identifient un sous-groupe biologiquement/pronostiquement défavorable.","STK11 oder KEAP1 schließen Immuntherapie grundsätzlich aus.":"STK11 ou KEAP1 excluent en principe l’immunothérapie.","PD-L1 bleibt eine eigenständige klinisch relevante Information.":"PD-L1 reste une information clinique pertinente indépendante.","Die Marker besitzen unterschiedliche Rollen; STK11/KEAP1 sind kein binärer ICI-Ausschluss.":"Les marqueurs ont des rôles différents ; STK11/KEAP1 ne sont pas des exclusions binaires des ICI.","PD-L1 ergibt später TPS 70 %. Wie ist der Befund zu integrieren?":"PD-L1 revient ensuite avec un TPS à 70 %. Comment intégrer ce résultat ?","Ignorieren, weil STK11/KEAP1 wichtiger sind.":"L’ignorer car STK11/KEAP1 sont plus importants.","PD-L1 70 % garantiert eine sehr gute ICI-Antwort.":"PD-L1 70 % garantit une excellente réponse aux ICI.","Als relevante positive Information berichten, aber zusammen mit klinischem Kontext und der adversen Ko-Mutationsbiologie interpretieren.":"Le rapporter comme information positive pertinente, mais l’interpréter avec le contexte clinique et la biologie défavorable des comutations.","STK11/KEAP1 und PD-L1 heben sich gegenseitig auf; deshalb keine Aussage möglich.":"STK11/KEAP1 et PD-L1 s’annulent mutuellement ; aucune conclusion n’est donc possible.","Widersprüchliche Biomarker werden integriert, nicht gegeneinander 'verrechnet'.":"Des biomarqueurs contradictoires s’intègrent ; ils ne se « soustraient » pas l’un à l’autre.","Welche Rolle haben TMB oder CD8/TIL-IHC hier?":"Quel rôle jouent ici le TMB ou l’IHC CD8/TIL ?","Optionaler biologischer Kontext; kein alleiniger validierter Therapieausschluss.":"Contexte biologique optionnel ; pas une exclusion thérapeutique autonome validée.","Zwingend erforderlich, bevor überhaupt eine Therapie diskutiert werden darf.":"Obligatoire avant même de pouvoir discuter un traitement.","Sie ersetzen PD-L1 vollständig.":"Ils remplacent complètement PD-L1.","Sie sind in der Tumorbiologie grundsätzlich bedeutungslos.":"Ils sont fondamentalement sans pertinence en biologie tumorale.","Die Zusatzmarker können das biologische Bild vertiefen, lösen die klinische Evidenzfrage aber nicht allein.":"Les marqueurs supplémentaires peuvent approfondir le contexte biologique mais ne résolvent pas à eux seuls la question des preuves cliniques.","Formulieren Sie eine MTB-Empfehlung, die KRAS p.G12C, STK11/KEAP1 und PD-L1 korrekt gewichtet, ohne aus einer Ko-Mutation ein nicht validiertes Therapieverbot zu machen.":"Formulez une recommandation de RCP qui pondère correctement KRAS p.G12C, STK11/KEAP1 et PD-L1 sans transformer une comutation en interdiction thérapeutique non validée.","KRAS p.G12C als eigenständigen Genotyp mit potenzieller Target-Relevanz im passenden Behandlungskontext benennen.":"Identifier KRAS p.G12C comme génotype indépendant potentiellement pertinent comme cible dans le contexte thérapeutique approprié.","STK11/KEAP1 als adverse biologische/prognostische Ko-Alterationen beschreiben.":"Décrire STK11/KEAP1 comme des co-altérations biologiques/pronostiques défavorables.","PD-L1 bestimmen und separat berichten.":"Déterminer et rapporter PD-L1 séparément.","Aus STK11/KEAP1 keinen absoluten Immuntherapieausschluss ableiten.":"Ne pas déduire une exclusion absolue de l’immunothérapie à partir de STK11/KEAP1.","Optional erhobene TMB/TIL-Daten als Kontext, nicht als übergeordneten Entscheidungsmarker kennzeichnen.":"Présenter les données TMB/TIL obtenues en option comme du contexte, et non comme un marqueur décisionnel supérieur.","Breites DNA-Panel statt fokussierter KRAS/STK11/KEAP1-Analyse, wenn es bereits Bestandteil der vollständigen NSCLC-Profilierung ist.":"Panel ADN large plutôt qu’une analyse focalisée KRAS/STK11/KEAP1 lorsqu’il fait déjà partie du profilage complet du NSCLC.","TMB oder Immun-Kontext-IHC als zusätzliche Lehr-/Kontextinformation, solange daraus keine binäre Therapieentscheidung konstruiert wird.":"TMB ou IHC du contexte immunitaire comme information pédagogique/contextuelle supplémentaire, tant qu’on n’en déduit pas une décision thérapeutique binaire.","STK11/KEAP1 = kein ICI":"STK11/KEAP1 = pas d’ICI","Aus einer adversen Assoziation wird fälschlich ein absoluter prädiktiver Ausschlussmarker.":"Une association défavorable est transformée à tort en marqueur prédictif absolu d’exclusion.","PD-L1 hoch = sichere Antwort":"PD-L1 élevé = réponse garantie","Auch ein etablierter Biomarker ist kein individuelles Response-Versprechen.":"Même un biomarqueur établi ne garantit pas une réponse individuelle.","Jeden Kontextmarker erzwingen":"Imposer tous les marqueurs contextuels","Mehr Messwerte erhöhen nicht automatisch die klinische Entscheidungsqualität.":"Davantage de mesures n’améliorent pas automatiquement la qualité de la décision clinique.","Der 'resistente' Tumor hat PD-L1 TPS 70 %":"La tumeur « résistante » a un PD-L1 TPS de 70 %","Die nachgeforderte PD-L1-IHC zeigt eine hohe Expression von 70 %. Eine optionale Immun-Kontext-IHC zeigt gleichzeitig nur ein geringes CD8-Infiltrat. Statt einer eindeutigen Antwort entsteht ein scheinbarer Widerspruch: positive etablierte Information, adverse Ko-Mutationsbiologie und ein eher 'cold' wirkendes Mikromilieu.":"L’IHC PD-L1 demandée montre une expression élevée de 70 %. Une IHC optionnelle du contexte immunitaire montre simultanément un faible infiltrat CD8. Au lieu d’une réponse univoque apparaît une contradiction apparente : information établie positive, biologie défavorable des co-mutations et microenvironnement plutôt « froid ».","Der Fall zwingt dazu, Biomarker nach Evidenzebene zu gewichten statt sie zu einem simplen Plus/Minus-Score zu verrechnen.":"Le cas impose de pondérer les biomarqueurs selon leur niveau de preuve plutôt que de les réduire à un simple score plus/moins.","Evidenzebenen getrennt":"Niveaux de preuve séparés","KRAS p.G12C + STK11/KEAP1; PD-L1 TPS 70 %. Ko-Mutationen werden als adverse Kontextmarker berichtet, nicht als absoluter ICI-Ausschluss.":"KRAS p.G12C + STK11/KEAP1 ; PD-L1 TPS 70 %. Les co-mutations sont rapportées comme marqueurs contextuels défavorables, et non comme critères absolus d’exclusion des ICI.","Sehr gute, klinisch belastbare Integration.":"Très bonne intégration, cliniquement robuste.","STK11/KEAP1 verbieten ICI":"STK11/KEAP1 interdisent les ICI","Die Ko-Mutationen werden als definitive prädiktive Resistenzmarker ausgegeben.":"Les co-mutations sont présentées comme des marqueurs prédictifs définitifs de résistance.","Overcalling: prognostisch/assoziativ wird mit binär prädiktiv verwechselt.":"Surinterprétation : les données pronostiques/associatives sont confondues avec une preuve prédictive binaire.","Nur PD-L1 zählt":"Seul PD-L1 compte","PD-L1 70 % wird ohne Genotyp- und Ko-Mutationskontext als eindeutige Antwort dargestellt.":"Un PD-L1 à 70 % est présenté comme une réponse univoque sans contexte génotypique ni de co-mutations.","Unvollständige Integration und zu starke Individualprognose.":"Intégration incomplète et pronostic individuel formulé de façon trop catégorique.","PD-L1 fehlt":"PD-L1 manquant","PD-L1 ergänzen.":"Ajouter PD-L1.","Etablierte klinische Information steht für die MTB-Integration zur Verfügung.":"Une information clinique établie est disponible pour l’intégration en RCP moléculaire.","TMB/TILs gewählt":"TMB/TIL sélectionnés","Als optionalen Kontext berichten.":"Rapporter comme contexte optionnel.","Kein zusätzlicher binärer Therapieentscheid aus diesen Daten.":"Aucune décision thérapeutique binaire supplémentaire ne doit être déduite de ces données.","STK11/KEAP1 als Ausschluss formuliert":"STK11/KEAP1 formulés comme exclusion","Befund sprachlich korrigieren.":"Corriger la formulation du compte rendu.","Prognostische/assoziierte Evidenz wird von prädiktiver Aussage getrennt.":"Les données pronostiques/associatives sont séparées des affirmations prédictives.","Ein molekulares Panel liefert nicht automatisch Marker gleicher klinischer Wertigkeit.":"Un panel moléculaire ne produit pas automatiquement des marqueurs de valeur clinique équivalente.","STK11/KEAP1 sind wichtige adverse Kontextinformationen, aber keine simplen ICI-Ausschalter.":"STK11/KEAP1 constituent des informations contextuelles défavorables importantes, mais ne sont pas de simples interrupteurs excluant les ICI.","PD-L1 bleibt relevant, ohne individuelle Antwort zu garantieren.":"PD-L1 reste pertinent sans garantir une réponse individuelle.","Gute MTB-Kommunikation macht die Evidenzebene jeder Aussage sichtbar.":"Une bonne communication en RCP moléculaire rend explicite le niveau de preuve de chaque affirmation.","KRAS p.G12C wird als eigenständiger targetrelevanter Genotyp im passenden Therapiekontext berichtet. STK11/KEAP1 werden als adverse biologische/prognostische Ko-Alterationen eingeordnet, nicht als absolutes ICI-Verbot. PD-L1 TPS 70 % bleibt klinisch relevant. TMB/TILs können Kontext liefern, dürfen aber nicht überinterpretiert werden.":"KRAS p.G12C est rapporté comme un génotype ayant une pertinence thérapeutique propre dans le contexte approprié. STK11/KEAP1 sont classés comme co-altérations biologiques/pronostiques défavorables, et non comme une interdiction absolue des ICI. Un PD-L1 TPS de 70 % reste cliniquement pertinent. TMB/TIL peuvent apporter du contexte, mais ne doivent pas être surinterprétés.","Keine binäre STK11/KEAP1-Überinterpretation":"Pas de surinterprétation binaire de STK11/KEAP1","PD-L1 integriert":"PD-L1 intégré","KRAS-Targetebene getrennt":"Niveau de ciblage KRAS séparé","Zusatzmarker limitiert formuliert":"Marqueurs supplémentaires formulés avec leurs limites","Wann wird ein prognostischer Marker prädiktiv?":"Quand un marqueur pronostique devient-il prédictif ?","Wie sollte ein Befund formuliert sein, damit die Onkologie die Evidenzebene sofort erkennt?":"Comment formuler un compte rendu afin que l’oncologie identifie immédiatement le niveau de preuve ?","Welche Rolle könnten Ko-Mutationen künftig für Therapiestratifizierung spielen, ohne heutige Routineentscheidungen vorwegzunehmen?":"Quel rôle les co-mutations pourraient-elles jouer à l’avenir dans la stratification thérapeutique sans préjuger des décisions de routine actuelles ?","PD-L1 70 % trotz STK11/KEAP1":"PD-L1 70 % malgré STK11/KEAP1","Biomarker nach Evidenzebene gewichten":"Pondérer les biomarqueurs selon le niveau de preuve","Genotyp → Ko-Mutationen → PD-L1 → integrierte Aussage":"Génotype → co-mutations → PD-L1 → conclusion intégrée","Melanom: BRAF V600 und Immuntherapie-Sequenz → Schnelle TKI-Therapie vs. Immuncheckpoint-Strategie":"Mélanome : BRAF V600 et séquençage de l’immunothérapie → thérapie ciblée rapide versus stratégie par inhibiteurs de checkpoint","Melanom: BRAF V600 und Immuntherap…":"Mélanome : BRAF V600 et séquençage de l’immunothérap…","Dermatoonkologie / Interdisziplinäres Tumorboard":"Dermato-oncologie / RCP multidisciplinaire","51-jähriger Patient mit neu metastasiertem kutanem Melanom, pulmonalen und hepatischen Metastasen.":"Patient de 51 ans présentant un mélanome cutané récemment métastatique avec métastases pulmonaires et hépatiques.","Liegt eine BRAF-V600-Alteration vor und wie beeinflusst sie die Sequenz zwischen Immuncheckpoint- und BRAF/MEK-Strategie?":"Une altération BRAF V600 est-elle présente et comment influence-t-elle la séquence entre stratégies par inhibiteurs de checkpoint et BRAF/MEK ?","Systemische Therapie soll innerhalb weniger Tage beginnen.":"Le traitement systémique doit débuter dans les prochains jours.","Performance":"Performance status","ECOG 0–1, zunächst klinisch stabil.":"ECOG 0–1, initialement cliniquement stable.","Tumorlast":"Charge tumorale","Mehrere Lebermetastasen, LDH moderat erhöht, keine initialen neurologischen Symptome.":"Métastases hépatiques multiples, LDH modérément élevée, sans symptôme neurologique initial.","Entscheidungsfalle":"Piège décisionnel","Der Nachweis einer BRAF-V600-Mutation entscheidet nicht automatisch über die erste Therapiesequenz; klinisches Tempo, ZNS-Situation, Steroidbedarf und Eignung für Immuntherapie sind mitentscheidend.":"La détection d’une mutation BRAF V600 ne détermine pas automatiquement la première séquence thérapeutique ; le rythme clinique, la situation du SNC, le besoin en corticoïdes et l’aptitude à l’immunothérapie comptent également.","Metastase eines malignen Melanoms.":"Métastase de mélanome malin.","SOX10 und S100 positiv, Melan-A fokal positiv.":"SOX10 et S100 positifs, Melan-A focalement positif.","Molekulare Kernfrage":"Question moléculaire centrale","BRAF V600 muss rasch geklärt werden, damit beide strategischen Optionen realistisch bewertet werden können.":"Le statut BRAF V600 doit être clarifié rapidement afin d’évaluer de façon réaliste les deux options stratégiques.","Nicht die Kernfrage":"Ce n’est pas la question centrale","PD-L1, TMB oder TILs sind in diesem Fall keine einfachen Schalter für die Sequenzentscheidung.":"PD-L1, TMB ou TIL ne sont pas de simples interrupteurs pour décider de la séquence dans ce cas.","FFPE-Lebermetastase, Block L4.":"Métastase hépatique FFPE, bloc L4.","ca. 60 %, geringe Nekrose.":"env. 60 %, faible nécrose.","gut; rascher BRAF-Test technisch problemlos möglich.":"bonne ; le test rapide de BRAF est techniquement simple.","10 ungefärbte Schnitte verfügbar.":"10 lames non colorées sont disponibles.","Breite Zusatzdiagnostik darf die dringliche BRAF-Klärung nicht verzögern.":"Des analyses complémentaires larges ne doivent pas retarder la clarification urgente du statut BRAF.","BRAF V600-Status":"Statut BRAF V600","BRAF V600":"BRAF V600","BRAF p.V600E nachweisbar. Damit ist eine BRAF/MEK-basierte Therapieoption grundsätzlich vorhanden.":"BRAF p.V600E détecté. Une option thérapeutique fondée sur BRAF/MEK est donc disponible en principe.","Melanom-IO-Kontext":"Contexte IO du mélanome","Immunhistologischer Kontext ohne eindeutigen Ausschlussbefund. Die Sequenzentscheidung bleibt primär klinisch-strategisch und wird nicht durch einen einzelnen IHC-Marker festgelegt.":"Contexte immunohistologique sans élément d’exclusion clair. La décision de séquençage reste avant tout clinico-stratégique et n’est pas déterminée par un seul marqueur IHC.","TMB erhöht. Dies ersetzt weder die BRAF-Testung noch die klinische Sequenzentscheidung.":"TMB élevé. Cela ne remplace ni le test BRAF ni la décision clinique de séquençage.","Tumoranteil und DNA-Qualität sind gut; BRAF-V600-Status ist rasch und belastbar bestimmbar.":"La fraction tumorale et la qualité de l’ADN sont bonnes ; le statut BRAF V600 peut être déterminé rapidement et de façon fiable.","BRAF p.V600E ist nachweisbar und eröffnet eine BRAF/MEK-Option. Bei zunächst klinisch stabilem, immuntherapiefähigem Patienten spricht die Evidenz häufig für eine Immuntherapie-first-Strategie; bei rascher klinischer Verschlechterung oder notwendigem schnellen Tumoransprechen kann sich die Gewichtung zugunsten einer zielgerichteten Therapie verschieben.":"BRAF p.V600E est détecté et ouvre une option BRAF/MEK. Chez un patient initialement cliniquement stable et apte à l’immunothérapie, les données favorisent souvent une stratégie d’immunothérapie en premier ; en cas d’aggravation clinique rapide ou de besoin d’une réponse tumorale rapide, la balance peut se déplacer vers la thérapie ciblée.","Teilbefund: Ohne geklärten BRAF-V600-Status fehlt eine zentrale Voraussetzung für die Sequenzplanung. Zusätzliche IO-Kontextmarker ersetzen diese Klärung nicht.":"Résultat partiel : sans clarification du statut BRAF V600, une condition essentielle de la planification de séquence manque. Les marqueurs supplémentaires de contexte IO ne remplacent pas cette clarification.","BRAF V600 als Voraussetzung für eine BRAF/MEK-Option benennen":"Présenter BRAF V600 comme condition préalable à une option BRAF/MEK","Therapiesequenz nicht allein aus dem Mutationsstatus ableiten":"Ne pas déduire la séquence thérapeutique du seul statut mutationnel","Tumorlast, klinisches Tempo, ZNS-Beteiligung/Steroidbedarf und Immuntherapiefähigkeit berücksichtigen":"Prendre en compte charge tumorale, rythme clinique, atteinte du SNC/besoin en corticoïdes et aptitude à l’immunothérapie","PD-L1/TMB/TILs nicht als simplen Sequenzschalter verwenden":"Ne pas utiliser PD-L1/TMB/TIL comme simple interrupteur de séquençage","Optimale Lösung: BRAF V600 rasch klären und anschließend die Sequenz anhand von Evidenz und klinischer Dynamik entscheiden; Mutation vorhanden bedeutet nicht automatisch 'Targeted Therapy zuerst'.":"Solution optimale : clarifier rapidement BRAF V600 puis décider de la séquence selon les données et la dynamique clinique ; la présence de la mutation ne signifie pas automatiquement « thérapie ciblée d’abord ».","BRAF":"BRAF","KI":"IA","Melanom":"Mélanome","BRAF-V600-Melanom: Die Mutation eröffnet eine Option – die Klinik bestimmt die Sequenz":"Mélanome BRAF V600 : la mutation ouvre une option – la clinique détermine la séquence","Molekularpathologie / Dermatoonkologie / MTB":"Pathologie moléculaire / Dermato-oncologie / RCP moléculaire","BRAF V600 als prädiktiven Marker für eine Target-Option korrekt bestimmen.":"Déterminer correctement BRAF V600 comme marqueur prédictif d’une option de thérapie ciblée.","Den BRAF-Nachweis nicht mit einer automatischen Targeted-Therapy-first-Entscheidung verwechseln.":"Ne pas confondre la détection de BRAF avec une décision automatique de thérapie ciblée en premier.","Klinisches Tempo, Tumorlast, ZNS-Beteiligung, Steroidbedarf und Immuntherapiefähigkeit in die Sequenz einbeziehen.":"Intégrer rythme clinique, charge tumorale, atteinte du SNC, besoin en corticoïdes et aptitude à l’immunothérapie dans la séquence.","PD-L1/TMB/TILs beim Melanom nicht als einfachen Sequenzschalter überinterpretieren.":"Ne pas surinterpréter PD-L1/TMB/TIL dans le mélanome comme un simple interrupteur de séquençage.","Freitagnachmittag im Melanomboard. Ein 51-jähriger Patient mit neu metastasiertem Melanom ist BRAF noch nicht getestet. Die Onkologie diskutiert bereits zwei sehr unterschiedliche Strategien: zuerst Immuncheckpoint-Therapie mit Aussicht auf langanhaltende Kontrolle oder – falls BRAF V600 positiv – eine BRAF/MEK-Therapie mit typischerweise rascherem Ansprechen. Noch wirkt der Patient klinisch stabil. Die Frage scheint planbar. Zwei Tage später ändert sich die Situation.":"Vendredi après-midi en RCP mélanome. Un patient de 51 ans présentant un mélanome nouvellement métastatique n’a pas encore été testé pour BRAF. L’oncologie discute déjà deux stratégies très différentes : d’abord une immunothérapie par inhibiteurs de checkpoint, avec une perspective de contrôle durable, ou – si BRAF V600 est positif – une thérapie BRAF/MEK avec une réponse généralement plus rapide. Le patient paraît encore cliniquement stable. La décision semble pouvoir être planifiée. Deux jours plus tard, la situation change.","51-jähriger Patient, kutanes Melanom mit Leber- und Lungenmetastasen, ECOG 0–1, moderat erhöhtes LDH. Keine systemische Vorbehandlung. Zunächst keine neurologischen Symptome. Für die Sequenzentscheidung muss der BRAF-V600-Status rasch vorliegen; die endgültige Strategie darf aber nicht allein aus dem Genotyp abgeleitet werden.":"Patient de 51 ans, mélanome cutané avec métastases hépatiques et pulmonaires, ECOG 0–1, LDH modérément élevée. Aucun traitement systémique antérieur. Initialement sans symptôme neurologique. Le statut BRAF V600 doit être disponible rapidement pour la séquence, mais la stratégie finale ne doit pas être déduite du seul génotype.","Molekulare Voraussetzung":"Prérequis moléculaire","Ohne BRAF-V600-Nachweis gibt es keine belastbare Grundlage für eine BRAF/MEK-Strategie.":"Sans détection de BRAF V600, il n’existe pas de base robuste pour une stratégie BRAF/MEK.","Erst Option nachweisen, dann Sequenz diskutieren.":"D’abord établir l’option, puis discuter de la séquence.","Initiale Klinik":"Situation clinique initiale","ECOG 0–1, systemisch metastasiert, aber zunächst keine akute Organ- oder ZNS-Symptomatik.":"ECOG 0–1, maladie métastatique systémique, mais initialement sans symptôme aigu d’organe ni du SNC.","Bei klinischer Stabilität kann Langzeitstrategie stärker gewichtet werden.":"En cas de stabilité clinique, la stratégie à long terme peut être davantage pondérée.","Evidenz zur Sequenz":"Données sur la séquence thérapeutique","Für viele geeignete Patienten mit BRAF-V600-mutiertem metastasiertem Melanom spricht die randomisierte Sequenzevidenz für Immuntherapie zuerst; dies ist aber keine starre Regel für jede klinische Situation.":"Chez de nombreux patients éligibles atteints d’un mélanome métastatique BRAF V600 muté, les données randomisées de séquençage soutiennent l’immunothérapie en premier ; ce n’est toutefois pas une règle rigide pour toute situation clinique.","Populationsevidenz und individuelle Dringlichkeit müssen zusammengeführt werden.":"Les données populationnelles et l’urgence individuelle doivent être intégrées.","Nicht der Schalter":"Ce n’est pas l’interrupteur","PD-L1, TMB und TILs können biologisch interessant sein, ersetzen aber weder BRAF-Testung noch die klinische Sequenzentscheidung.":"PD-L1, TMB et TIL peuvent être biologiquement intéressants, mais ne remplacent ni le test BRAF ni la décision clinique de séquençage.","Nicht jedes messbare Immunmerkmal ist ein Routine-Entscheidungstest.":"Toute caractéristique immunitaire mesurable n’est pas pour autant un test décisionnel de routine.","Histologie/IHC":"Histologie/IHC","Metastase eines SOX10-/S100-positiven malignen Melanoms.":"Métastase d’un mélanome malin SOX10/S100 positif.","Klinik initial":"Situation clinique initiale","Keine symptomatische ZNS-Beteiligung; keine Steroidtherapie.":"Pas d’atteinte symptomatique du SNC ; pas de corticothérapie.","Material-QC":"QC du matériel","Lebermetastase mit ca. 60 % Tumor; DNA-QC gut.":"Métastase hépatique avec env. 60 % de tumeur ; QC ADN satisfaisant.","BRAF-V600-Status muss rasch vorliegen; unnötige Zusatzanalysen dürfen die Entscheidung nicht verzögern.":"Le statut BRAF V600 doit être disponible rapidement ; des analyses complémentaires inutiles ne doivent pas retarder la décision.","Therapiesequenz kann nicht aus der Pathologie allein entschieden werden; aktuelle klinische Dynamik muss ins MTB zurückgespielt werden.":"La séquence thérapeutique ne peut pas être décidée par la seule pathologie ; la dynamique clinique actuelle doit être réintégrée dans la RCP moléculaire.","PD-L1/TMB/TILs sind nicht als zwingende Sequenzmarker definiert.":"PD-L1/TMB/TIL ne sont pas définis comme marqueurs obligatoires de séquençage.","Welche molekulare Information muss für die Targeted-Therapy-Option zuerst belastbar vorliegen?":"Quelle information moléculaire doit d’abord être disponible de façon fiable pour l’option de thérapie ciblée ?","PD-L1 zwingend":"PD-L1 obligatoire","TMB zwingend":"TMB obligatoire","CD8/TIL-IHC zwingend":"IHC CD8/TIL obligatoire","BRAF V600 ist die zentrale molekulare Voraussetzung für eine BRAF/MEK-basierte Option.":"BRAF V600 est le prérequis moléculaire central d’une option fondée sur BRAF/MEK.","Welche Faktoren beeinflussen die Sequenzentscheidung zusätzlich zum BRAF-Status?":"Quels facteurs influencent la séquence en plus du statut BRAF ?","Klinisches Progressionstempo und Tumorlast":"Rythme clinique de progression et charge tumorale","ZNS-Beteiligung und neurologische Symptomatik":"Atteinte du SNC et symptômes neurologiques","Steroidbedarf/Immuntherapiefähigkeit":"Besoin en corticoïdes/aptitude à l’immunothérapie","Allgemeinzustand und Eignung für die jeweiligen Regime":"État général et aptitude aux différents schémas thérapeutiques","Alleiniger PD-L1-Wert als Sequenzschalter":"Valeur PD-L1 seule comme interrupteur de séquençage","Die Sequenz ist eine klinisch-strategische Entscheidung, nicht nur eine Genotypentscheidung.":"Le séquençage thérapeutique est une décision clinico-stratégique, pas seulement une décision génotypique.","Der Patient ist BRAF V600E-positiv und klinisch stabil. Welche Aussage ist am besten?":"Le patient est BRAF V600E positif et cliniquement stable. Quelle affirmation est la plus juste ?","Für viele geeignete Patienten spricht die Sequenzevidenz für Immuntherapie-first; individuelle Faktoren bleiben entscheidend.":"Chez de nombreux patients éligibles, les données de séquençage soutiennent l’immunothérapie en premier ; les facteurs individuels restent déterminants.","BRAF V600E bedeutet zwingend BRAF/MEK zuerst.":"BRAF V600E impose BRAF/MEK en premier.","Bei BRAF-Mutation sollte Immuntherapie nicht eingesetzt werden.":"L’immunothérapie ne doit pas être utilisée en cas de mutation BRAF.","Erst PD-L1 entscheidet, ob BRAF/MEK oder Immuntherapie beginnt.":"PD-L1 seul décide si BRAF/MEK ou l’immunothérapie doit être commencé en premier.","Randomisierte Sequenzdaten favorisieren bei vielen geeigneten Patienten Immuntherapie-first, ohne jede dringliche Ausnahmesituation abzudecken.":"Les données randomisées de séquençage favorisent l’immunothérapie en premier chez de nombreux patients éligibles, sans couvrir toutes les situations urgentes exceptionnelles.","Bestimmen Sie den BRAF-V600-Status und formulieren Sie anschließend eine Sequenzempfehlung, die Evidenz und aktuelle klinische Dynamik ausdrücklich miteinander verknüpft.":"Déterminer le statut BRAF V600 puis formuler une recommandation de séquençage reliant explicitement les données à la dynamique clinique actuelle.","BRAF-V600-Testung rasch durchführen.":"Réaliser rapidement le test BRAF V600.","Bei BRAF p.V600E beide prinzipiellen Strategien als verfügbar benennen.":"En présence de BRAF p.V600E, indiquer que les deux stratégies principales sont disponibles.","Bei klinisch stabilem, immuntherapiefähigem Patienten die Evidenz für Immuntherapie-first diskutieren.":"Chez un patient cliniquement stable et apte à l’immunothérapie, discuter les données en faveur d’une immunothérapie en premier.","Vor Therapiebeginn aktuelle ZNS-Situation, Steroidbedarf und Progressionstempo erneut prüfen.":"Avant le début du traitement, réévaluer la situation du SNC, le besoin en corticoïdes et le rythme de progression.","Bei akuter Dynamik die Notwendigkeit schnellen Ansprechens neu gewichten.":"En cas de dynamique clinique aiguë, repondérer le besoin d’une réponse rapide.","Validiertes breites Panel, wenn BRAF V600 ohne relevante Verzögerung sicher erfasst wird.":"Panel large validé s’il couvre de façon fiable BRAF V600 sans délai significatif.","Targeted Therapy first bei dringlicher klinischer Situation oder wenn Immuntherapie nicht geeignet ist; dies muss explizit klinisch begründet werden.":"Thérapie ciblée en premier dans une situation clinique urgente ou lorsque l’immunothérapie n’est pas adaptée ; cela doit être explicitement justifié sur le plan clinique.","BRAF-mutiert = automatisch Targeted Therapy first":"BRAF muté = automatiquement thérapie ciblée en premier","Der Genotyp eröffnet die Option, entscheidet aber nicht alleine die optimale Sequenz.":"Le génotype ouvre l’option mais ne détermine pas à lui seul la séquence optimale.","PD-L1 entscheidet die Reihenfolge":"PD-L1 décide de la séquence","Beim metastasierten Melanom ist PD-L1 kein einfacher Sequenzschalter zwischen BRAF/MEK und Immuntherapie.":"Dans le mélanome métastatique, PD-L1 n’est pas un simple interrupteur de séquençage entre BRAF/MEK et immunothérapie.","Klinik vom Molekularbefund trennen":"Séparer la clinique du résultat moléculaire","Eine Sequenzentscheidung kann sich durch akute Progression innerhalb von Tagen verändern.":"Une décision de séquençage peut changer en quelques jours en raison d’une progression aiguë.","48 Stunden später: neue symptomatische Hirnmetastase":"48 heures plus tard : nouvelle métastase cérébrale symptomatique","Noch vor Therapiebeginn entwickelt der Patient Kopfschmerzen und eine diskrete Hemiparese. Das MRT zeigt eine neue symptomatische Hirnmetastase; Dexamethason wird begonnen. Gleichzeitig liegt der molekulare Befund vor: BRAF p.V600E. Die ursprünglich in Ruhe geplante Sequenz muss unter dem Gesichtspunkt rascher Krankheitskontrolle und Steroidbedarf neu diskutiert werden.":"Avant le début du traitement, le patient développe des céphalées et une hémiparésie discrète. L’IRM montre une nouvelle métastase cérébrale symptomatique ; une dexaméthasone est débutée. Au même moment, le résultat moléculaire arrive : BRAF p.V600E. La séquence initialement planifiée dans un contexte stable doit être rediscutée au regard du besoin de contrôle rapide de la maladie et de la corticothérapie.","Der molekulare Befund ist unverändert, aber die klinische Priorität hat sich verändert. Genau deshalb darf BRAF V600 nie isoliert als Sequenzautomat interpretiert werden.":"Le résultat moléculaire n’a pas changé, mais la priorité clinique oui. C’est précisément pourquoi BRAF V600 ne doit jamais être interprété isolément comme une commande automatique de séquençage.","BRAF positiv, Klinik integriert":"BRAF positif, contexte clinique intégré","BRAF p.V600E nachweisbar. Beide Strategien sind grundsätzlich verfügbar; nach klinischer Verschlechterung wird die Notwendigkeit schneller Kontrolle im MTB neu gewichtet.":"BRAF p.V600E détecté. Les deux stratégies sont disponibles en principe ; après l’aggravation clinique, le besoin de contrôle rapide est repondéré en RCP moléculaire.","Sehr gute Verbindung von molekularer Option und klinischer Situation.":"Très bonne articulation entre l’option moléculaire et la situation clinique.","Mutation entscheidet alles":"La mutation décide de tout","BRAF p.V600E wird automatisch mit 'BRAF/MEK zuerst' gleichgesetzt, unabhängig von Klinik und Sequenzevidenz.":"BRAF p.V600E est automatiquement assimilé à « BRAF/MEK en premier », indépendamment du contexte clinique et des données de séquençage.","Zu mechanistisch; Option und Sequenz wurden verwechselt.":"Trop mécaniste ; la disponibilité d’une option a été confondue avec la séquence.","Nur IO-Kontextmarker":"Uniquement des marqueurs de contexte IO","PD-L1/TMB/TILs werden breit untersucht, BRAF bleibt ausstehend.":"PD-L1/TMB/TIL sont largement explorés alors que BRAF reste en attente.","Die zentrale molekulare Voraussetzung für eine Targeted-Therapy-Option fehlt.":"Le prérequis moléculaire central d’une option de thérapie ciblée manque.","BRAF V600E positiv, klinisch stabil":"BRAF V600E positif, cliniquement stable","Immuntherapie-first als evidenzgestützte Standardstrategie für viele geeignete Patienten diskutieren.":"Discuter l’immunothérapie en premier comme stratégie standard étayée par les données chez de nombreux patients éligibles.","Langfristige Sequenzplanung steht im Vordergrund.":"La planification de la séquence à long terme est prioritaire.","Neue symptomatische ZNS-Progression/Steroidbedarf":"Nouvelle progression symptomatique du SNC/besoin en corticoïdes","Sequenz im MTB sofort neu bewerten und schnelle Krankheitskontrolle stärker gewichten.":"Réévaluer immédiatement la séquence en RCP moléculaire et accorder davantage de poids au contrôle rapide de la maladie.","Targeted Therapy kann klinisch an Gewicht gewinnen.":"La thérapie ciblée peut gagner en importance clinique.","BRAF nicht bestimmt":"BRAF non déterminé","Schnelltest nachfordern.":"Demander un test rapide.","Sequenzentscheidung bleibt unvollständig.":"La décision de séquençage reste incomplète.","BRAF V600 ist ein prädiktiver Marker für eine Target-Option, kein automatischer Sequenzbefehl.":"BRAF V600 est un marqueur prédictif d’une option ciblée, pas une commande automatique de séquençage.","Bei vielen geeigneten, stabilen Patienten spricht randomisierte Sequenzevidenz für Immuntherapie-first.":"Chez de nombreux patients éligibles et stables, les données randomisées de séquençage soutiennent l’immunothérapie en premier.","Akute klinische Dynamik kann die optimale Reihenfolge verändern.":"Une dynamique clinique aiguë peut modifier l’ordre optimal.","Molekularpathologie ist Teil der Entscheidung, aber nicht deren alleiniger Eigentümer.":"La pathologie moléculaire participe à la décision, mais n’en est pas l’unique propriétaire.","BRAF p.V600E wird rasch bestätigt. Zunächst wäre bei klinischer Stabilität für viele geeignete Patienten Immuntherapie-first evidenzgestützt. Der Twist – symptomatische Hirnmetastase mit Steroidbedarf – erzwingt eine erneute klinische Gewichtung und kann die Bedeutung einer rasch wirksamen BRAF/MEK-Strategie erhöhen. PD-L1/TMB/TILs sind kein einfacher Sequenzschalter.":"BRAF p.V600E est rapidement confirmé. Initialement, en situation de stabilité clinique, une immunothérapie en premier serait étayée par les données chez de nombreux patients éligibles. Le twist – une métastase cérébrale symptomatique nécessitant des corticoïdes – impose une nouvelle pondération clinique et peut renforcer l’intérêt d’une stratégie BRAF/MEK à action rapide. PD-L1/TMB/TIL ne sont pas un simple interrupteur de séquençage.","BRAF als Voraussetzung erkannt":"BRAF reconnu comme prérequis","Keine automatische Targeted-first-Regel":"Pas de règle automatique de thérapie ciblée en premier","Klinische Dynamik integriert":"Dynamique clinique intégrée","IO-Kontextmarker nicht überinterpretiert":"Marqueurs de contexte IO non surinterprétés","Welche Patientengruppen waren in Sequenzstudien besonders gut repräsentiert – und welche weniger?":"Quels groupes de patients étaient particulièrement bien représentés dans les études de séquençage – et lesquels moins ?","Wie ändert Steroidbedarf die praktische Immuntherapieplanung?":"Comment le besoin en corticoïdes modifie-t-il la planification pratique de l’immunothérapie ?","Welche Information muss die Pathologie liefern und welche Entscheidung bleibt interdisziplinär?":"Quelle information la pathologie doit-elle fournir et quelle décision reste interdisciplinaire ?","symptomatische Hirnmetastase nach initial stabiler Situation":"métastase cérébrale symptomatique après une situation initialement stable","Mutation eröffnet Option, Klinik bestimmt Sequenz":"La mutation ouvre l’option, la clinique détermine la séquence","BRAF-Test → stabile Sequenzplanung → klinischer Twist → Re-Assessment":"Test BRAF → planification stable de la séquence → twist clinique → réévaluation","GIST mit KIT/PDGFRA-Fragestellung → Welcher Marker entscheidet über TKI-Auswahl?":"GIST avec question KIT/PDGFRA → Quel marqueur détermine le choix du TKI ?","GIST mit KIT/PDGFRA-Fragestellung":"GIST avec question KIT/PDGFRA","Sarkomzentrum / MTB":"Centre des sarcomes / RCP moléculaire","64-jährige Patientin mit gastralem GIST und neu aufgetretenen Lebermetastasen.":"Patiente de 64 ans présentant un GIST gastrique et de nouvelles métastases hépatiques.","Ist 'GIST = Imatinib' ausreichend, oder muss vor der TKI-Auswahl der KIT/PDGFRA-Genotyp vorliegen?":"« GIST = imatinib » suffit-il ou faut-il disposer du génotype KIT/PDGFRA avant de choisir le TKI ?","Therapiebeginn ist nach Abschluss der molekularen Typisierung geplant.":"Le traitement est prévu après achèvement du typage moléculaire.","Primärtumor":"Tumeur primitive","Gastraler GIST, vor drei Jahren reseziert; nun hepatische Metastasierung.":"GIST gastrique réséqué il y a trois ans ; désormais métastases hépatiques.","Keine systemische TKI-Therapie.":"Aucun traitement systémique par TKI.","Klinischer Reflex":"Réflexe clinique","Im Tumorboard fällt früh der Satz: 'CD117-positiver GIST – dann Imatinib.'":"Très tôt en RCP, quelqu’un dit : « GIST CD117 positif – donc imatinib. »","Lernziel":"Objectif pédagogique","Diagnosemarker und prädiktiver Genotyp müssen getrennt werden.":"Les marqueurs diagnostiques et le génotype prédictif doivent être clairement distingués.","Epithelioider mesenchymaler Tumor, morphologisch passend zu GIST.":"Tumeur mésenchymateuse épithélioïde, morphologiquement compatible avec un GIST.","DOG1 stark positiv, CD117 nur fokal/heterogen positiv.":"DOG1 fortement positif, CD117 seulement focal/hétérogène.","Arbeitsdiagnose":"Diagnostic de travail","Metastasierter gastrointestinaler Stromatumor.":"Tumeur stromale gastro-intestinale métastatique.","Welcher KIT-/PDGFRA-Genotyp liegt vor und verändert er die TKI-Auswahl?":"Quel génotype KIT/PDGFRA est présent et modifie-t-il le choix du TKI ?","FFPE-Lebermetastase, Block H3.":"Métastase hépatique FFPE, bloc H3.","ca. 75 %, DNA-QC gut.":"env. 75 %, QC ADN satisfaisant.","6 ungefärbte Schnitte verfügbar.":"6 lames non colorées sont disponibles.","Ein sehr breites Pan-Tumor-Panel ist für die konkrete Erstfrage unnötig, wenn eine valide KIT/PDGFRA-Analyse verfügbar ist.":"Un panel pan-tumoral très large est inutile pour la question initiale ciblée lorsqu’une analyse KIT/PDGFRA valide est disponible.","KIT/PDGFRA-Genotyp":"Génotype KIT/PDGFRA","KIT/PDGFRA":"KIT/PDGFRA","PDGFRA Exon 18 p.D842V nachweisbar; keine aktivierende KIT-Mutation. Die Konstellation ist für die TKI-Auswahl unmittelbar relevant.":"PDGFRA exon 18 p.D842V détecté ; aucune mutation activatrice de KIT. Cette constellation est directement pertinente pour le choix du TKI.","Hoher Tumoranteil, DNA-Qualität gut; gezielte KIT/PDGFRA-Analyse vollständig auswertbar.":"Fraction tumorale élevée, bonne qualité d’ADN ; l’analyse ciblée KIT/PDGFRA est entièrement interprétable.","Metastasierter GIST mit PDGFRA p.D842V. Der Genotyp widerspricht dem reflexhaften 'Imatinib für jeden GIST'-Schema und verlangt eine genotypspezifische TKI-Strategie.":"GIST métastatique avec PDGFRA p.D842V. Le génotype contredit le réflexe « imatinib pour tout GIST » et impose une stratégie TKI spécifique du génotype.","Teilbefund: Die GIST-Diagnose ist morphologisch/IHC-basiert gesichert, aber ohne KIT/PDGFRA-Genotyp ist die prädiktive TKI-Einordnung unvollständig.":"Résultat partiel : le diagnostic de GIST est établi par morphologie/IHC, mais sans génotype KIT/PDGFRA, la classification prédictive pour le TKI est incomplète.","DOG1/CD117 als Diagnosekontext, nicht als ausreichenden prädiktiven Marker einordnen":"Classer DOG1/CD117 comme contexte diagnostique, pas comme marqueurs prédictifs suffisants","PDGFRA D842V explizit benennen":"Mentionner explicitement PDGFRA D842V","Genotypspezifische TKI-Auswahl statt pauschalem Imatinib-Reflex formulieren":"Formuler un choix de TKI spécifique du génotype plutôt qu’un réflexe systématique d’imatinib","Bei KIT/PDGFRA-Wildtyp weitere molekulare Subklassifikation als mögliche Folgefrage erwähnen, ohne sie in diesem Fall zu erzwingen":"En cas de KIT/PDGFRA wild type, mentionner une sous-classification moléculaire complémentaire comme éventuelle étape ultérieure sans l’imposer ici","Optimale Lösung: KIT/PDGFRA gezielt bestimmen. Der Nachweis von PDGFRA p.D842V ist der Twist, der die TKI-Auswahl gegenüber einem pauschalen Imatinib-Ansatz verändert.":"Solution optimale : réaliser un test ciblé KIT/PDGFRA. La détection de PDGFRA p.D842V constitue le twist qui modifie le choix du TKI par rapport à une approche systématique par imatinib.","KIT":"KIT","PDGFRA":"PDGFRA","GIST":"GIST","Mini":"Mini","GIST ist nicht gleich Imatinib: PDGFRA D842V kippt den TKI-Reflex":"GIST ne signifie pas imatinib : PDGFRA D842V renverse le réflexe TKI","Molekularpathologie / Sarkompathologie / MTB":"Pathologie moléculaire / Pathologie des sarcomes / RCP moléculaire","GIST-Diagnosemarker und prädiktiven KIT/PDGFRA-Genotyp klar trennen.":"Séparer clairement les marqueurs diagnostiques du GIST du génotype prédictif KIT/PDGFRA.","Vor systemischer TKI-Therapie die für Sensitivität/Resistenz relevante Mutationsklasse bestimmen.":"Avant un traitement systémique par TKI, déterminer la classe mutationnelle pertinente pour la sensibilité/résistance.","PDGFRA D842V als klinisch entscheidenden Sonderfall erkennen.":"Reconnaître PDGFRA D842V comme un cas particulier cliniquement déterminant.","Für eine fokussierte klinische Frage eine gezielte, ressourcenschonende Methode wählen.":"Choisir une méthode ciblée et économe en ressources pour une question clinique ciblée.","Im Sarkomboard ist der Fall scheinbar in zehn Sekunden erledigt: metastasierter GIST, DOG1 positiv, also Imatinib. Die Pathologin stoppt die Diskussion mit einer einfachen Frage: 'Welcher KIT- oder PDGFRA-Genotyp liegt eigentlich vor?' Plötzlich ist klar, dass der diagnostische Name noch keine prädiktive Antwort ist.":"En RCP sarcome, le cas paraît réglé en dix secondes : GIST métastatique, DOG1 positif, donc imatinib. La pathologiste interrompt la discussion par une question simple : « Quel génotype KIT ou PDGFRA est réellement présent ? » Il devient soudain évident que le nom diagnostique n’est pas encore une réponse prédictive.","64-jährige Patientin mit vor drei Jahren reseziertem gastralem GIST und jetzt multiplen Lebermetastasen. DOG1 stark positiv, CD117 fokal. Keine bisherige TKI-Therapie. Vor Therapiebeginn soll der KIT/PDGFRA-Status geklärt werden.":"Patiente de 64 ans avec GIST gastrique réséqué il y a trois ans et désormais de multiples métastases hépatiques. DOG1 fortement positif, CD117 focal. Aucun traitement TKI antérieur. Le statut KIT/PDGFRA doit être clarifié avant le début du traitement.","Diagnose":"Diagnostic","Morphologie und DOG1/CD117 sichern den GIST-Kontext.":"La morphologie et DOG1/CD117 établissent le contexte de GIST.","IHC beantwortet 'Was ist der Tumor?', nicht automatisch 'Welcher TKI wirkt?'.":"L’IHC répond à « Quelle est la tumeur ? », pas automatiquement à « Quel TKI fonctionne ? ».","Therapiefrage":"Question thérapeutique","Die Onkologie möchte mit einer TKI-Therapie beginnen.":"L’oncologie souhaite débuter un traitement par TKI.","Der prädiktive Genotyp gehört vor die Wirkstoffwahl.":"Le génotype prédictif doit précéder le choix du médicament.","Lebermetastase, 75 % Tumor, DNA-QC sehr gut; nur sechs Schnitte nötig verfügbar.":"Métastase hépatique, 75 % de tumeur, très bon QC ADN ; seulement six lames sont nécessaires/disponibles.","Eine fokussierte KIT/PDGFRA-Analyse ist effizient.":"Une analyse ciblée KIT/PDGFRA est efficace.","Epithelioider mesenchymaler Tumor, vereinbar mit GIST.":"Tumeur mésenchymateuse épithélioïde, compatible avec un GIST.","DOG1 stark positiv; CD117 fokal/heterogen positiv.":"DOG1 fortement positif ; CD117 positif de façon focale/hétérogène.","Systemtherapie":"Traitement systémique","Noch nicht begonnen.":"Pas encore commencé.","Kleine, aber sehr tumorreiche Metastasenbiopsie.":"Petite biopsie métastatique mais très riche en tumeur.","Die klinische Kernfrage ist fokussiert; ein extrem breites Pan-Tumor-Panel ist nicht zwingend nötig.":"La question clinique centrale est ciblée ; un panel pan-tumoral extrêmement large n’est pas obligatoire.","Therapie sollte nicht allein aufgrund der IHC gestartet werden, wenn der Genotyp zeitnah verfügbar ist.":"Le traitement ne devrait pas être commencé sur la seule base de l’IHC si le génotype peut être obtenu rapidement.","Welcher Befund entscheidet in diesem Fall am direktesten über die TKI-Auswahl?":"Quel résultat détermine le plus directement le choix du TKI dans ce cas ?","KIT/PDGFRA-Mutationsstatus":"Statut mutationnel KIT/PDGFRA","Stärke der CD117-IHC allein":"Intensité de l’IHC CD117 seule","Ki-67 allein":"Ki-67 seul","Der KIT/PDGFRA-Genotyp ist für die prädiktive Einordnung zentral.":"Le génotype KIT/PDGFRA est central pour la classification prédictive.","Was bedeutet DOG1+/CD117+ für die TKI-Wahl?":"Que signifie DOG1+/CD117+ pour le choix du TKI ?","Es stützt die GIST-Diagnose, ersetzt aber die Genotypisierung nicht.":"Cela soutient le diagnostic de GIST, mais ne remplace pas le génotypage.","Es beweist Imatinib-Sensitivität.":"Cela prouve la sensibilité à l’imatinib.","Es schließt PDGFRA-Mutationen aus.":"Cela exclut les mutations PDGFRA.","Es macht molekulare Diagnostik grundsätzlich überflüssig.":"Cela rend le diagnostic moléculaire fondamentalement inutile.","Diagnostische IHC und prädiktive Genotypisierung beantworten verschiedene Fragen.":"L’IHC diagnostique et le génotypage prédictif répondent à des questions différentes.","Wählen Sie die minimale diagnostische Strategie, mit der die geplante TKI-Therapie genotypspezifisch abgesichert werden kann.":"Choisir la stratégie diagnostique minimale permettant d’étayer le traitement TKI prévu de façon spécifique au génotype.","GIST-Diagnose als gesichert akzeptieren.":"Considérer le diagnostic de GIST comme établi.","KIT/PDGFRA-Mutationsanalyse durchführen.":"Réaliser une analyse mutationnelle KIT/PDGFRA.","Mutation auf Exon/Variantebene berichten.":"Rapporter la mutation au niveau exon/variant.","Therapieempfehlung an die konkrete Sensitivitäts-/Resistenzkonstellation koppeln.":"Relier la recommandation thérapeutique à la constellation spécifique de sensibilité/résistance.","Bei KIT/PDGFRA-Wildtyp weitere Subklassifikation nur als Folgefrage erwägen.":"En cas de KIT/PDGFRA wild type, envisager une sous-classification complémentaire uniquement comme question ultérieure.","Breiteres validiertes NGS-Panel, wenn es KIT/PDGFRA vollständig abdeckt und ohne relevante Mehrbelastung verfügbar ist.":"Panel NGS validé plus large s’il couvre intégralement KIT/PDGFRA et est disponible sans charge supplémentaire significative.","CD117 positiv = Imatinib":"CD117 positif = imatinib","Diagnostische Proteinexpression wird fälschlich als prädiktiver Genotyp interpretiert.":"L’expression protéique diagnostique est interprétée à tort comme un génotype prédictif.","Pan-Panel ohne klare Zusatzfrage":"Pan-panel sans question complémentaire claire","Kann funktionieren, ist bei der fokussierten Erstfrage aber unnötig breit.":"Cela peut fonctionner, mais c’est inutilement large pour la question initiale ciblée.","Therapie vor Genotyp":"Traitement avant génotype","Eine klinisch relevante Resistenz-/Sensitivitätskonstellation kann übersehen werden.":"Une constellation de résistance/sensibilité cliniquement pertinente peut être manquée.","PDGFRA D842V statt 'klassischem KIT-GIST'":"PDGFRA D842V au lieu d’un « GIST KIT classique »","Die gezielte Sequenzierung zeigt keine KIT-Mutation, sondern PDGFRA Exon 18 p.D842V. Der zunächst reflexhaft diskutierte Imatinib-Start wäre für genau diese Konstellation ungeeignet; die TKI-Strategie muss genotypspezifisch geändert werden.":"Le séquençage ciblé ne montre pas de mutation KIT, mais PDGFRA exon 18 p.D842V. Le démarrage réflexe par imatinib serait inadapté précisément dans cette constellation ; la stratégie TKI doit être modifiée selon le génotype.","Der Fall zeigt maximal kompakt, warum Diagnosesicherung und prädiktive Molekularpathologie zwei getrennte Schritte sind.":"Ce cas montre de manière très concise pourquoi la confirmation diagnostique et la pathologie moléculaire prédictive sont deux étapes distinctes.","Genotyp vor TKI":"Génotype avant TKI","PDGFRA Exon 18 p.D842V, KIT wildtyp.":"PDGFRA exon 18 p.D842V, KIT wild type.","Kernentscheidung getroffen; TKI-Auswahl kann genotypspezifisch erfolgen.":"Décision centrale prise ; le choix du TKI peut être effectué selon le génotype.","IHC reicht":"L’IHC suffit","GIST wird korrekt diagnostiziert, aber ohne KIT/PDGFRA-Genotyp pauschal als Imatinib-sensitiv behandelt.":"Le GIST est correctement diagnostiqué mais, sans génotype KIT/PDGFRA, il est traité de façon générique comme sensible à l’imatinib.","Diagnose korrekt, prädiktive Ebene verfehlt.":"Diagnostic correct, niveau prédictif manqué.","Breites Pan-Panel":"Pan-panel large","PDGFRA D842V wird ebenfalls gefunden, jedoch mit mehr Ressourcen als für die Kernfrage nötig.":"PDGFRA D842V est également détecté, mais avec davantage de ressources que nécessaire pour la question centrale.","Fachlich brauchbar, aber weniger fokussiert.":"Cliniquement exploitable, mais moins ciblé.","PDGFRA D842V":"PDGFRA D842V","Genotypspezifische TKI-Strategie im Sarkomboard diskutieren.":"Discuter une stratégie TKI spécifique du génotype en RCP sarcome.","Pauschaler Imatinib-Reflex wird vermieden.":"Le réflexe systématique d’imatinib est évité.","KIT/PDGFRA wildtyp":"KIT/PDGFRA wild type","Weitere molekulare Subklassifikation erwägen.":"Envisager une sous-classification moléculaire complémentaire.","Der Fall geht in eine zweite diagnostische Ebene über.":"Le cas passe à un deuxième niveau diagnostique.","DOG1/CD117 sichern den diagnostischen Kontext, nicht die TKI-Sensitivität.":"DOG1/CD117 établissent le contexte diagnostique, pas la sensibilité au TKI.","KIT/PDGFRA-Genotypisierung ist eine prädiktive Entscheidungsebene.":"Le génotypage KIT/PDGFRA constitue un niveau décisionnel prédictif.","PDGFRA D842V ist der klassische Fall, in dem ein pauschaler Imatinib-Reflex scheitert.":"PDGFRA D842V est le cas classique où le réflexe systématique d’imatinib échoue.","Fokussierte Diagnostik kann besser sein als maximale Panelbreite, wenn die klinische Frage klar ist.":"Un diagnostic ciblé peut être préférable à une largeur maximale de panel lorsque la question clinique est claire.","Gezielte KIT/PDGFRA-Analyse vor TKI-Start. Ergebnis: PDGFRA Exon 18 p.D842V, KIT wildtyp. Damit ist der reflexhafte Imatinib-Ansatz nicht passend; die Therapie muss genotypspezifisch geplant werden.":"Analyse ciblée KIT/PDGFRA avant le début du TKI. Résultat : PDGFRA exon 18 p.D842V, KIT wild type. L’approche réflexe par imatinib n’est donc pas adaptée ; le traitement doit être planifié selon le génotype.","Diagnose vs. Prädiktion getrennt":"Diagnostic et prédiction séparés","KIT/PDGFRA gewählt":"KIT/PDGFRA sélectionné","D842V korrekt gewichtet":"D842V correctement pondéré","Keine unnötige Panelinflation":"Pas d’inflation inutile du panel","Welche weiteren GIST-Genotypen beeinflussen Dosis oder TKI-Sensitivität?":"Quels autres génotypes de GIST influencent la dose ou la sensibilité aux TKI ?","Wann wäre ein breiteres Panel sinnvoll?":"Quand un panel plus large serait-il utile ?","Wie sollte ein Befund formuliert sein, damit Diagnose und Prädiktion klar getrennt bleiben?":"Comment formuler un compte rendu pour que diagnostic et prédiction restent clairement distincts ?","GIST-Diagnose ist nicht gleich TKI-Sensitivität":"Le diagnostic de GIST n’équivaut pas à la sensibilité aux TKI","IHC-Diagnose → Genotyp → TKI-Wechsel":"Diagnostic IHC → génotype → changement de TKI","Cholangiozelluläres Karzinom mit FGFR2/IDH-Frage → Paneldiagnostik und Studienoptionen":"Cholangiocarcinome avec question FGFR2/IDH → analyse par panel et options d’essais cliniques","Cholangiozelluläres Karzinom mit F…":"Cholangiocarcinome avec question FGFR2/IDH…","Hepatobiliäre Onkologie / MTB":"Oncologie hépatobiliaire / RCP moléculaire","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie.":"Patiente de 59 ans présentant un cholangiocarcinome intrahépatique non résécable en progression après traitement de première ligne.","Welche molekulare Profilierung ist jetzt sinnvoll, insbesondere für FGFR2- und IDH1/2-Alterationen sowie weitere potenziell targetierbare Befunde?":"Quel profilage moléculaire est approprié maintenant, notamment pour les altérations FGFR2 et IDH1/2 ainsi que d’autres résultats potentiellement ciblables ?","Der molekulare Befund soll vor Festlegung der nächsten Therapielinie vorliegen.":"Le compte rendu moléculaire doit être disponible avant le choix de la prochaine ligne thérapeutique.","Tumorlokalisation":"Localisation tumorale","Intrahepatische dominante Raumforderung mit multiplen Satelliten und pulmonalen Metastasen.":"Masse intrahépatique dominante avec multiples satellites et métastases pulmonaires.","Systemische Erstlinientherapie abgeschlossen; aktuell radiologischer Progress.":"Traitement systémique de première ligne terminé ; progression radiologique actuelle.","Ein kleines DNA-only-Panel aus der Erstdiagnose meldete keinen therapeutisch relevanten SNV/Indel-Befund; Fusionen waren im Bericht nicht valide abgedeckt.":"Un petit panel ADN seul réalisé au diagnostic initial n’a rapporté aucun SNV/indel thérapeutiquement pertinent ; les fusions n’étaient pas couvertes de façon valide.","'Panel negativ' wird im Tumorboard bereits mit 'keine Target-Option' gleichgesetzt.":"En RCP, « panel négatif » est déjà assimilé à « aucune option ciblée ».","Adenokarzinom mit tubulären und desmoplastischen Anteilen, vereinbar mit intrahepatischem Cholangiokarzinom.":"Adénocarcinome avec composantes tubulaires et desmoplasiques, compatible avec un cholangiocarcinome intrahépatique.","CK7 positiv; HepPar1/Arginase-1 negativ; klinisch-radiologische Integration stützt iCCA.":"CK7 positif ; HepPar1/Arginase-1 négatifs ; l’intégration clinico-radiologique soutient un iCCA.","Breite DNA-basierte Alterationen und insbesondere strukturelle FGFR2-Ereignisse müssen methodisch adäquat erfasst werden.":"Les altérations larges basées sur l’ADN et, en particulier, les événements structuraux FGFR2 doivent être détectés par des méthodes adaptées.","Nicht relevant":"Non pertinent","Neuroonkologische IDH1-R132H-IHC, G-CIMP oder ein ZNS-Methylierungsclassifier beantworten diese Fragestellung nicht.":"L’IHC IDH1-R132H de neuro-oncologie, le G-CIMP ou un classificateur de méthylation du SNC ne répondent pas à cette question.","FFPE-Leberbiopsie, Block C5.":"Biopsie hépatique FFPE, bloc C5.","ca. 50 %, ausreichende vitale Tumorareale.":"env. 50 %, zones tumorales viables suffisantes.","DNA/RNA-QC":"QC ADN/ARN","DNA gut; RNA nach QC ausreichend.":"ADN de bonne qualité ; ARN suffisant après QC.","Erneutes DNA-only-Testen ohne valide Fusionserfassung kann denselben blinden Fleck reproduzieren.":"Répéter un test ADN seul sans couverture valide des fusions peut reproduire le même angle mort.","CCA-Molekularprofil / IDH1/2-Kontext":"Profil moléculaire CCA / contexte IDH1/2","FGFR2-Fusions-/Rearrangementdiagnostik":"Recherche de fusion/réarrangement FGFR2","CCA-DNA-Profil":"Profil ADN CCA","Keine pathogene IDH1/2-Mutation; kein BRAF-V600- oder ERBB2-Hotspot-Befund. Das DNA-Profil allein erklärt keine Target-Option.":"Aucune mutation pathogène IDH1/2 ; aucun BRAF V600 ni hotspot ERBB2. Le profil ADN seul ne révèle pas d’option ciblée.","FGFR2-Fusionsdiagnostik":"Recherche de fusion FGFR2","FGFR2::BICC1-Fusion nachweisbar. Der Befund ist bei intrahepatischem Cholangiokarzinom therapeutisch relevant und gehört in die nächste Linienplanung.":"Fusion FGFR2::BICC1 détectée. Ce résultat est thérapeutiquement pertinent dans le cholangiocarcinome intrahépatique et doit être intégré à la planification de la ligne suivante.","DNA und RNA aus dem markierten Tumorareal sind auswertbar; ausreichende Restreserve vorhanden.":"L’ADN et l’ARN de la zone tumorale marquée sont interprétables ; une réserve de matériel suffisante demeure.","Intrahepatisches Cholangiokarzinom mit FGFR2::BICC1-Fusion und ohne IDH1/2-Mutation. Die zuvor DNA-only negative Profilierung war kein ausreichender Ausschluss einer strukturellen Targetalteration.":"Cholangiocarcinome intrahépatique avec fusion FGFR2::BICC1 et sans mutation IDH1/2. Le profilage antérieur négatif par ADN seul ne suffisait pas à exclure une altération structurale ciblable.","Teilbefund: Die CCA-Profilierung ist ohne belastbare FGFR2-Fusions-/Rearrangementdiagnostik unvollständig. Neuroonkologische IDH-/Methylierungsverfahren sind für diese Frage nicht geeignet.":"Résultat partiel : le profilage CCA est incomplet sans recherche robuste de fusion/réarrangement FGFR2. Les méthodes IDH/méthylation de neuro-oncologie ne conviennent pas à cette question.","Intrahepatisches Cholangiokarzinom als relevanten molekularen Kontext benennen":"Mentionner le cholangiocarcinome intrahépatique comme contexte moléculaire pertinent","FGFR2-Fusion/Rearrangement als eigenständige strukturelle Alterationsklasse erfassen":"Détecter fusion/réarrangement FGFR2 comme classe distincte d’altération structurale","IDH1/2-Sequenzierung im CCA-Kontext von neuroonkologischer IDH-IHC/Methylomdiagnostik trennen":"Séparer le séquençage IDH1/2 dans le contexte CCA de l’IHC IDH/du méthylome de neuro-oncologie","DNA-only Negativbefund nicht als vollständigen Fusionsausschluss formulieren":"Ne pas formuler un résultat négatif ADN seul comme exclusion complète des fusions","Optimale Lösung: CCA-spezifisches Molekularprofil plus valide FGFR2-Fusionserfassung. Der ZNS-Methylierungs-/G-CIMP-Copyover wird vollständig entfernt.":"Solution optimale : profil moléculaire spécifique CCA plus détection valide des fusions FGFR2. Le copyover méthylation SNC/G-CIMP est entièrement supprimé.","IDH":"IDH","FGFR":"FGFR","Intrahepatisches Cholangiokarzinom: Das negative DNA-Panel übersieht die strukturelle Targetalteration":"Cholangiocarcinome intrahépatique : le panel ADN négatif manque l’altération structurale ciblable","Molekularpathologie / hepatobiliäre Onkologie / MTB":"Pathologie moléculaire / oncologie hépatobiliaire / RCP moléculaire","Das intrahepatische Cholangiokarzinom als Entität mit relevanter breiter molekularer Profilierung einordnen.":"Considérer le cholangiocarcinome intrahépatique comme une entité nécessitant un profilage moléculaire large pertinent.","FGFR2-Fusionen/Rearrangements methodisch von SNV/Indel-Analysen unterscheiden.":"Distinguer méthodologiquement les fusions/réarrangements FGFR2 des analyses SNV/indel.","IDH1/2 im CCA-Kontext von neuroonkologischer IDH-IHC/G-CIMP/Methylomdiagnostik trennen.":"Séparer IDH1/2 dans le contexte CCA du diagnostic neuro-oncologique par IHC IDH/G-CIMP/méthylome.","Einen negativen DNA-only-Befund nicht als vollständigen Ausschluss struktureller Targetalterationen interpretieren.":"Ne pas interpréter un résultat négatif ADN seul comme exclusion complète des altérations structurales ciblables.","Im hepatobiliären MTB liegt ein alter Molekularbefund mit der Überschrift 'kein targetierbarer Befund'. Die 59-jährige Patientin mit intrahepatischem Cholangiokarzinom ist nach Erstlinientherapie progredient, und die nächste Linie muss geplant werden. Beim Blick in den Methodenteil zeigt sich: Das damalige kleine Panel war DNA-basiert und auf SNV/Indels fokussiert. FGFR2-Rearrangements wurden nicht valide breit erfasst. Gleichzeitig findet sich in der Falllogik ein völlig fachfremder Verweis auf G-CIMP und einen ZNS-Methylierungsclassifier – genau diese Altlast soll der Fall jetzt bewusst bereinigen.":"En RCP hépatobiliaire, un ancien compte rendu moléculaire porte le titre « aucun résultat ciblable ». La patiente de 59 ans atteinte d’un cholangiocarcinome intrahépatique a progressé après la première ligne et la ligne suivante doit être planifiée. L’examen de la section méthodes montre que l’ancien petit panel était basé sur l’ADN et centré sur les SNV/indels. Les réarrangements FGFR2 n’étaient pas couverts de façon large et valide. Parallèlement, la logique du cas contient une référence totalement hors sujet au G-CIMP et à un classificateur de méthylation du SNC – précisément l’héritage erroné que ce cas doit désormais corriger explicitement.","59-jährige Patientin mit nicht resektablem intrahepatischem Cholangiokarzinom und Progress nach Erstlinientherapie. DNA-only-Vorbefund ohne relevante SNV/Indel-Targetalteration. Für die nächste Linie sollen FGFR2-Fusionen/Rearrangements, IDH1/2 und weitere relevante molekulare Alterationen methodisch vollständig bewertet werden.":"Patiente de 59 ans avec cholangiocarcinome intrahépatique non résécable en progression après première ligne. Résultat antérieur ADN seul sans altération SNV/indel ciblable pertinente. Pour la ligne suivante, les fusions/réarrangements FGFR2, IDH1/2 et les autres altérations moléculaires pertinentes doivent être évalués complètement par des méthodes appropriées.","Entität":"Entité","Intrahepatisches Cholangiokarzinom mit metastasierter Erkrankung.":"Cholangiocarcinome intrahépatique métastatique.","Tumorentität und Erkrankungsphase bestimmen die sinnvolle molekulare Breite.":"L’entité tumorale et la phase de la maladie déterminent l’étendue moléculaire appropriée.","Kleines DNA-only-Panel ohne relevanten SNV/Indel-Treffer; keine belastbare breite Fusionserfassung.":"Petit panel ADN seul sans résultat SNV/indel pertinent ; absence de couverture large et robuste des fusions.","Ein negatives SNV/Indel-Profil schließt strukturelle Alterationen nicht aus.":"Un profil SNV/indel négatif n’exclut pas les altérations structurales.","Leberbiopsie mit 50 % Tumor; DNA und RNA ausreichend.":"Biopsie hépatique avec 50 % de tumeur ; ADN et ARN suffisants.","Es gibt keinen technischen Grund, die Fusionsfrage offen zu lassen.":"Aucune raison technique ne justifie de laisser la question des fusions sans réponse.","Copyover-Falle":"Piège de copyover","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier gehören in neuroonkologische Kontexte und beantworten die CCA-Targetfrage nicht.":"L’IHC IDH1-R132H, le G-CIMP et les classificateurs de méthylation du SNC relèvent de contextes neuro-oncologiques et ne répondent pas à la question de ciblage du CCA.","Gleiche Genbezeichnung bedeutet nicht gleiche diagnostische Methode oder biologische Fragestellung.":"Le même nom de gène n’implique ni la même méthode diagnostique ni la même question biologique.","Adenokarzinom mit desmoplastischem Stroma; klinisch-radiologisch und immunhistologisch mit intrahepatischem CCA vereinbar.":"Adénocarcinome avec stroma desmoplasique ; compatible cliniquement, radiologiquement et immunohistologiquement avec un CCA intrahépatique.","DNA-only Vorprofil":"Profil antérieur ADN seul","Kein relevanter IDH1/2-, BRAF-V600- oder ERBB2-Hotspot-Befund; Fusionserfassung unzureichend.":"Aucun résultat pertinent IDH1/2, BRAF V600 ou hotspot ERBB2 ; couverture des fusions insuffisante.","ausreichend für gezielte Fusionsanalyse.":"suffisant pour une analyse ciblée des fusions.","Zehn ungefärbte Schnitte verfügbar.":"Dix lames non colorées sont disponibles.","DNA und RNA sind ausreichend; die Limitation liegt primär in der Wahl des Assays.":"L’ADN et l’ARN sont suffisants ; la limitation réside principalement dans le choix de l’essai.","Neuroonkologische IDH-/Methylierungsverfahren sind explizit entitätsfremd.":"Les méthodes IDH/méthylation de neuro-oncologie sont explicitement inadaptées à cette entité.","Das TAT-Ziel liegt vor der nächsten Therapieentscheidung.":"L’objectif de TAT est avant la prochaine décision thérapeutique.","Welche molekulare Kernstrategie ist bei diesem progredienten intrahepatischen Cholangiokarzinom sinnvoll?":"Quelle stratégie moléculaire centrale est appropriée pour ce cholangiocarcinome intrahépatique en progression ?","CCA-spezifisches Molekularprofil plus valide FGFR2-Fusions-/Rearrangementdiagnostik":"Profil moléculaire spécifique CCA plus recherche valide de fusion/réarrangement FGFR2","IDH1-R132H-IHC plus ZNS-Methylierungsclassifier":"IHC IDH1-R132H plus classificateur de méthylation du SNC","Keine weitere Diagnostik, weil das alte DNA-Panel negativ war":"Aucun test supplémentaire car l’ancien panel ADN était négatif","MGMT-Promotor-Methylierung":"Méthylation du promoteur de MGMT","Die klinische Frage verlangt CCA-spezifische molekulare Profilierung mit adäquater Erfassung struktureller Alterationen.":"La question clinique exige un profilage moléculaire spécifique CCA avec détection adéquate des altérations structurales.","Wie soll IDH in diesem Fall untersucht/eingeordnet werden?":"Comment IDH doit-il être testé/interprété dans ce cas ?","IDH1/2-Sequenzierung im CCA-Panel-/Targetkontext":"Séquençage IDH1/2 dans le contexte panel/ciblage du CCA","IDH1-R132H-IHC als primärer CCA-Screeningstandard":"IHC IDH1-R132H comme standard principal de dépistage du CCA","G-CIMP-Profil als Therapiebiomarker":"Profil G-CIMP comme biomarqueur thérapeutique","ZNS-Methylierungsclassifier":"Classificateur de méthylation du SNC","Die neuroonkologische R132H-IHC/G-CIMP-/Classifier-Logik darf nicht auf das Cholangiokarzinom übertragen werden.":"La logique neuro-oncologique R132H IHC/G-CIMP/classificateur ne doit pas être transposée au cholangiocarcinome.","Das alte DNA-only-Panel ist negativ. Was folgt daraus für FGFR2?":"L’ancien panel ADN seul est négatif. Qu’en déduire pour FGFR2 ?","Eine Fusion/Rearrangement-Frage kann weiterhin offen sein, wenn der Assay diese Alterationsklasse nicht valide abdeckt.":"La question d’une fusion/d’un réarrangement peut rester ouverte si l’essai ne couvre pas valablement cette classe d’altérations.","FGFR2 ist sicher ausgeschlossen.":"FGFR2 est définitivement exclu.","Dann kann nur noch IDH1 relevant sein.":"Alors seul IDH1 peut encore être pertinent.","Strukturelle Alterationen sind beim CCA klinisch nicht relevant.":"Les altérations structurales ne sont pas cliniquement pertinentes dans le CCA.","SNV/Indel-negative DNA-Daten sind kein universeller Fusionsausschluss.":"Des données ADN négatives pour SNV/indel n’excluent pas universellement les fusions.","Planen Sie eine CCA-spezifische molekulare Abklärung für die nächste Therapielinie und entfernen Sie die neuroonkologischen Copyover-Methoden vollständig aus der Entscheidungslogik.":"Planifier un bilan moléculaire spécifique CCA pour la prochaine ligne et supprimer totalement de la logique décisionnelle les méthodes de copyover neuro-oncologiques.","Intrahepatischen CCA-Kontext bestätigen.":"Confirmer le contexte de CCA intrahépatique.","CCA-spezifisches DNA-Profil für IDH1/2 und weitere relevante Alterationen nutzen.":"Utiliser un profil ADN spécifique CCA pour IDH1/2 et les autres altérations pertinentes.","FGFR2-Fusion/Rearrangement mit einer dafür validierten Methode explizit erfassen.":"Évaluer explicitement fusion/réarrangement FGFR2 par une méthode validée.","DNA-only Negativbefund methodisch begrenzen.":"Limiter méthodologiquement l’interprétation du résultat négatif ADN seul.","IDH1-R132H-IHC, G-CIMP und ZNS-Methylierungsclassifier nicht verwenden.":"Ne pas utiliser IHC IDH1-R132H, G-CIMP ni classificateur de méthylation du SNC.","Validiertes kombiniertes DNA/RNA-Pan-Panel mit sicherer FGFR2-Fusionserfassung.":"Pan-panel combiné ADN/ARN validé avec couverture fiable des fusions FGFR2.","Gezielte FGFR2-Fusionsdiagnostik plus separates IDH1/2-Assay, wenn ein integriertes CCA-Panel nicht verfügbar ist.":"Recherche ciblée de fusion FGFR2 plus essai IDH1/2 séparé si aucun panel CCA intégré n’est disponible.","Fachfremder Copyover; beantwortet weder FGFR2- noch IDH1/2-Targetfrage beim CCA.":"Copyover hors sujet ; ne répond ni à la question FGFR2 ni à la question de ciblage IDH1/2 dans le CCA.","IDH1-R132H-IHC als CCA-Standard":"IHC IDH1-R132H comme standard du CCA","Neuroonkologische Screeninglogik wird auf eine andere Entität übertragen.":"La logique de dépistage neuro-oncologique est transposée à une autre entité.","DNA-negativ = keine Targetoption":"ADN négatif = aucune option ciblée","Strukturelle Alterationen können methodisch offen bleiben.":"Les altérations structurales peuvent rester non résolues sur le plan méthodologique.","FGFR2::BICC1 trotz 'kein targetierbarer Befund'":"FGFR2::BICC1 malgré « aucun résultat ciblable »","Die CCA-spezifische DNA-Analyse bleibt für IDH1/2, BRAF und ERBB2 ohne relevanten Treffer. Die gezielte Fusionsdiagnostik detektiert jedoch eine FGFR2::BICC1-Fusion. Der alte Satz 'kein targetierbarer Befund' war damit nicht biologisch falsch, sondern methodisch zu weit formuliert.":"L’analyse ADN spécifique CCA reste sans résultat pertinent pour IDH1/2, BRAF et ERBB2. Cependant, la recherche ciblée de fusions détecte une fusion FGFR2::BICC1. L’ancienne formule « aucun résultat ciblable » n’était donc pas biologiquement fausse, mais méthodologiquement trop large.","Die zentrale Lektion ist zweifach: strukturelle Alterationen brauchen passende Assays, und identische Genbegriffe dürfen nicht entitätsfremde Diagnostikpfade triggern.":"La leçon centrale est double : les altérations structurales nécessitent des essais adaptés et des noms de gènes identiques ne doivent pas déclencher des voies diagnostiques inappropriées à l’entité.","CCA-Profil + Fusion":"Profil CCA + fusion","FGFR2::BICC1-Fusion nachweisbar; IDH1/2 wildtyp; kein BRAF-V600-/ERBB2-Hotspot-Befund.":"Fusion FGFR2::BICC1 détectée ; IDH1/2 wild type ; aucun BRAF V600/hotspot ERBB2.","Vollständige, entitätsspezifische Profilierung mit klinisch relevanter Targetalteration.":"Profilage complet, spécifique à l’entité, avec altération ciblable cliniquement pertinente.","DNA-only wiederholt":"ADN seul répété","Kein relevanter SNV/Indel-Treffer; FGFR2-Fusionsstatus bleibt offen.":"Aucun résultat SNV/indel pertinent ; le statut de fusion FGFR2 reste non résolu.","Der alte methodische blinde Fleck wurde reproduziert.":"L’ancien angle mort méthodologique a été reproduit.","Neuroonkologischer IDH-Pfad":"Voie IDH de neuro-oncologie","IDH1-R132H-IHC/Methylierungsclassifier werden angefordert; die eigentliche CCA-Targetfrage bleibt ungelöst.":"IHC IDH1-R132H/classificateur de méthylation sont demandés ; la véritable question de ciblage du CCA reste non résolue.","Klarer Cross-Template-Fehler.":"Erreur cross-template évidente.","FGFR2-Fusion positiv":"Fusion FGFR2 positive","Target-Relevanz und passende Therapielinie im hepatobiliären MTB diskutieren.":"Discuter la pertinence de la cible et de la ligne thérapeutique appropriée en RCP hépatobiliaire.","Der Befund verändert die nächste Linienplanung.":"Le résultat modifie la planification de la ligne suivante.","FGFR2 negativ, DNA-Profil ohne Target":"FGFR2 négatif, profil ADN sans cible","Weitere im validierten Panel erfasste Alterationsklassen und Studienoptionen prüfen.":"Examiner les autres classes d’altérations couvertes par le panel validé et les options d’essais cliniques.","Negativbefund bleibt methodisch transparent.":"Le résultat négatif reste méthodologiquement transparent.","Nur CNS-IDH/Methylom gewählt":"Uniquement IDH/méthylome SNC sélectionné","Anforderung korrigieren und CCA-spezifische Diagnostik durchführen.":"Corriger la demande et réaliser un diagnostic spécifique CCA.","Material/TAT-Verlust, aber fachlich rettbarer Fall.":"Perte de matériel/TAT, mais cas cliniquement rattrapable.","Beim iCCA ist molekulare Profilierung Teil moderner Therapieplanung.":"Dans l’iCCA, le profilage moléculaire fait partie de la planification thérapeutique moderne.","FGFR2-Fusionen sind strukturelle Alterationen und benötigen passende Assayabdeckung.":"Les fusions FGFR2 sont des altérations structurales et nécessitent une couverture d’essai adaptée.","IDH1/2 im Cholangiokarzinom ist nicht dasselbe diagnostische Problem wie IDH/G-CIMP im Gliom.":"IDH1/2 dans le cholangiocarcinome ne constitue pas le même problème diagnostique que IDH/G-CIMP dans le gliome.","Cross-Template-Copyover ist ein reales Qualitätsrisiko in standardisierten Fallbibliotheken und Labor-Workflows.":"Le copyover entre templates constitue un véritable risque qualité dans les bibliothèques de cas standardisées et les workflows de laboratoire.","CCA-spezifisches Molekularprofil plus explizite FGFR2-Fusions-/Rearrangementdiagnostik. Ergebnis: FGFR2::BICC1-Fusion, IDH1/2 wildtyp. Die bisherigen neuroonkologischen IDH1-R132H-/G-CIMP-/Methylierungsclassifier-Elemente sind fachfremd und werden vollständig entfernt.":"Profil moléculaire spécifique CCA plus recherche explicite de fusion/réarrangement FGFR2. Résultat : fusion FGFR2::BICC1, IDH1/2 wild type. Les anciens éléments neuro-oncologiques IDH1-R132H/G-CIMP/classificateur de méthylation sont inappropriés et sont entièrement supprimés.","iCCA-Kontext erkannt":"Contexte iCCA reconnu","FGFR2 strukturell korrekt getestet":"FGFR2 correctement testé comme altération structurale","IDH1/2 entitätsspezifisch eingeordnet":"IDH1/2 interprété de façon spécifique à l’entité","CNS-Copyover aktiv verworfen":"Copyover SNC activement rejeté","Wann reicht ein DNA-Panel für Fusionen, wann nicht?":"Quand un panel ADN suffit-il pour les fusions, et quand ne suffit-il pas ?","Welche weiteren Alterationsklassen sollten CCA-Panels abdecken?":"Quelles autres classes d’altérations les panels CCA devraient-ils couvrir ?","Wie können Template-Bibliotheken gegen Cross-Entity-Copyover QA-gesichert werden?":"Comment sécuriser par QA les bibliothèques de templates contre le copyover entre entités ?","FGFR2::BICC1 nach DNA-only Negativbefund":"FGFR2::BICC1 après un résultat négatif ADN seul","Strukturelle Targets brauchen passende Methoden":"Les cibles structurales nécessitent des méthodes adaptées","DNA-negativ → Assaycheck → CCA-Profil + Fusion → FGFR2":"ADN négatif → vérification de l’essai → profil CCA + fusion → FGFR2","Rechte Kolonkarzinom-Metastase mit BRAF V600E → Prognose, MSI-Kontext, Therapieoption":"Métastase de cancer du côlon droit avec BRAF V600E → pronostic, contexte MSI, option thérapeutique","Rechte Kolonkarzinom-Metastase mit…":"Métastase de cancer du côlon droit avec…","Viszeralonkologie / Molekulares Tumorboard":"Oncologie digestive / RCP moléculaire","72-jährige Patientin mit rechtsseitigem Kolonkarzinom und synchronen Leber- und Peritonealmetastasen.":"Patiente de 72 ans avec cancer du côlon droit et métastases hépatiques et péritonéales synchrones.","Im Tumorprofil wurde BRAF p.V600E nachgewiesen. Welche prognostische und therapeutische Bedeutung hat der Befund im CRC – und was muss zusätzlich über MMR/MSI bekannt sein?":"BRAF p.V600E a été détecté dans le profil tumoral. Quelle est sa signification pronostique et thérapeutique dans le CRC – et que faut-il encore savoir sur MMR/MSI ?","Die Erstlinienstrategie soll im MTB innerhalb weniger Tage festgelegt werden.":"La stratégie de première ligne doit être définie en RCP moléculaire dans les prochains jours.","Coecum/Colon ascendens, rechtsseitig.":"Cæcum/côlon ascendant, côté droit.","Metastasiert mit Leber- und Peritonealbefall; ECOG 1.":"Maladie métastatique avec atteinte hépatique et péritonéale ; ECOG 1.","BRAF V600E wird reflexartig wie beim Melanom interpretiert oder mit MSI-H gleichgesetzt. Beides ist im CRC falsch bzw. unvollständig.":"BRAF V600E est interprété par réflexe comme dans le mélanome ou assimilé à MSI-H. Dans le CRC, ces deux approches sont erronées ou incomplètes.","Mäßig bis gering differenziertes kolorektales Adenokarzinom mit fokal muzinöser Morphologie.":"Adénocarcinome colorectal modérément à peu différencié avec morphologie mucineuse focale.","Lineage":"Lignée","CDX2/SATB2 positiv; Morphologie und Klinik vereinbar mit kolorektalem Primarius.":"CDX2/SATB2 positifs ; morphologie et contexte clinique compatibles avec une origine colorectale.","Molekularer Vorbefund":"Résultat moléculaire antérieur","BRAF p.V600E in einer schnellen Einzeltestung nachgewiesen.":"BRAF p.V600E détecté par un test rapide monogénique.","Ist der Tumor dMMR/MSI-H oder pMMR/MSS, und wie muss die BRAF-Alteration CRC-spezifisch therapeutisch eingeordnet werden?":"La tumeur est-elle dMMR/MSI-H ou pMMR/MSS, et comment l’altération BRAF doit-elle être interprétée thérapeutiquement de façon spécifique au CRC ?","FFPE-Resektat, Block C6 mit vitalem invasivem Tumor.":"Pièce de résection FFPE, bloc C6 avec tumeur invasive viable.","ca. 55 %, gut geeignet für DNA-basierte Analysen.":"env. 55 %, bien adapté aux analyses basées sur l’ADN.","DNA-Qualität gut; MMR-IHC technisch gut beurteilbar.":"Bonne qualité d’ADN ; IHC MMR techniquement bien interprétable.","Melanom-spezifische BRAF-Methoden oder Therapiealgorithmen beantworten die CRC-Frage nicht.":"Les méthodes BRAF ou algorithmes thérapeutiques spécifiques du mélanome ne répondent pas à la question du CRC.","BRAF-V600E im CRC-Kontext":"BRAF V600E dans le contexte CRC","MMR-IHC":"IHC MMR","MSI-Testung":"Test MSI","BRAF V600E":"BRAF V600E","BRAF p.V600E nachweisbar. Der Befund ist im metastasierten CRC prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden – nicht nach dem Melanom-Algorithmus.":"BRAF p.V600E détecté. Le résultat est pertinent sur les plans pronostique et thérapeutique dans le CRC métastatique, mais doit être interprété selon les données spécifiques au CRC – et non selon un algorithme de mélanome.","Erweiterter RAS-Status":"Statut RAS étendu","KRAS/NRAS Wildtyp. Der BRAF-V600E-Befund bleibt der dominante MAPK-Treiberkontext.":"KRAS/NRAS wild type. Le résultat BRAF V600E reste le contexte driver MAPK dominant.","Intakte nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expression nucléaire conservée de MLH1, PMS2, MSH2 et MSH6 : pMMR.","MSI":"MSI","MSS / kein MSI-H. BRAF V600E ist damit gerade nicht automatisch mit MSI-H gleichzusetzen.":"MSS / absence de MSI-H. BRAF V600E n’est donc précisément pas synonyme de MSI-H.","MLH1-Methylierung":"Méthylation MLH1","Bei erhaltener MLH1/PMS2-Expression besteht in diesem Fall keine primäre Reflexindikation; die Zusatzanalyse liefert keinen entscheidungsrelevanten Mehrwert.":"Avec une expression conservée de MLH1/PMS2, il n’existe pas d’indication réflexe primaire dans ce cas ; l’analyse supplémentaire n’apporte pas de bénéfice décisionnel.","Tumoranteil und DNA-Qualität ausreichend; MMR-IHC auswertbar.":"Fraction tumorale et qualité de l’ADN suffisantes ; IHC MMR interprétable.","BRAF p.V600E liegt in einem rechtsseitigen, pMMR/MSS metastasierten CRC vor. Der Befund ist prognostisch ungünstig und eröffnet einen CRC-spezifischen BRAF-gerichteten Therapiekontext mit EGFR-Blockade nach aktueller Therapielinie/Leitlinie. Eine Melanom-artige BRAF/MEK-Übertragung ist nicht angemessen; BRAF V600E bedeutet außerdem nicht automatisch MSI-H.":"BRAF p.V600E est présent dans un CRC métastatique droit, pMMR/MSS. Le résultat est de mauvais pronostic et ouvre un contexte thérapeutique spécifique au CRC de ciblage de BRAF avec blocage d’EGFR selon la ligne thérapeutique/les recommandations actuelles. Une transposition de type mélanome BRAF/MEK est inappropriée ; BRAF V600E ne signifie pas non plus automatiquement MSI-H.","Teilbefund: BRAF V600E ist bekannt, aber ohne MMR/MSI-Kontext bleibt die molekulare Einordnung unvollständig. Therapie- und Prognoseaussagen dürfen nicht aus einem Melanom-Template übernommen werden.":"Résultat partiel : BRAF V600E est connu, mais sans contexte MMR/MSI, la classification moléculaire reste incomplète. Les affirmations thérapeutiques et pronostiques ne doivent pas être reprises d’un template de mélanome.","BRAF V600E als CRC-spezifischen prognostisch/therapeutisch relevanten Befund benennen":"Présenter BRAF V600E comme résultat spécifique au CRC, pertinent sur les plans pronostique et thérapeutique","BRAF V600E nicht mit MSI-H gleichsetzen; pMMR/MSS separat kommunizieren":"Ne pas assimiler BRAF V600E à MSI-H ; communiquer pMMR/MSS séparément","BRAF-gerichtete Strategie im CRC mit EGFR-Blockade und aktueller Therapielinie verknüpfen, nicht mit einem Melanom-Schema":"Relier la stratégie de ciblage de BRAF dans le CRC au blocage d’EGFR et à la ligne thérapeutique actuelle, pas à un schéma de mélanome","Entitätsspezifische Evidenz und aktuelle Leitlinien-/Zulassungssituation sprachlich sauber begrenzen":"Formuler les données spécifiques à l’entité et la situation actuelle des recommandations/autorisations avec les limitations appropriées","Optimale Lösung: BRAF V600E, RAS-Kontext und MMR/MSI gemeinsam einordnen; der Tumor ist pMMR/MSS und benötigt eine CRC-spezifische BRAF-/EGFR-Therapielogik statt eines Melanom-Copyovers.":"Solution optimale : interpréter ensemble BRAF V600E, le contexte RAS et MMR/MSI ; la tumeur est pMMR/MSS et nécessite une logique thérapeutique BRAF/EGFR spécifique au CRC plutôt qu’un copyover de mélanome.","CRC":"CRC","mCRC":"mCRC","pMMR":"pMMR","MSS":"MSS","anti-EGFR":"anti-EGFR","Targeted Therapy":"Thérapie ciblée","BRAF V600E im rechten mCRC: CRC-Biologie statt Melanom-Copyover":"BRAF V600E dans le mCRC droit : biologie du CRC plutôt que copyover de mélanome","Molekularpathologie / Viszeralonkologie / MTB":"Pathologie moléculaire / Oncologie digestive / RCP moléculaire","BRAF V600E beim mCRC prognostisch und therapeutisch korrekt einordnen.":"Interpréter correctement BRAF V600E sur les plans pronostique et thérapeutique dans le mCRC.","BRAF V600E nicht automatisch mit MSI-H gleichsetzen, sondern MMR/MSI separat prüfen.":"Ne pas assimiler automatiquement BRAF V600E à MSI-H ; évaluer MMR/MSI séparément.","Die CRC-spezifische BRAF-Therapielogik von Melanom-Algorithmen abgrenzen.":"Distinguer la logique thérapeutique BRAF spécifique au CRC des algorithmes du mélanome.","Rechtsseitigkeit, pMMR/MSS und BRAF-Kontext in einer integrierten MTB-Aussage zusammenführen.":"Intégrer latéralité, pMMR/MSS et contexte BRAF dans une seule conclusion de RCP moléculaire.","Im MTB fällt sofort der rote Marker 'BRAF V600E' ins Auge. Jemand schlägt vor, den Fall wie ein BRAF-mutiertes Melanom zu behandeln; ein anderer sagt, rechtsseitig plus BRAF sei wahrscheinlich ohnehin MSI-high. Beides klingt auf den ersten Blick plausibel – und beides greift zu kurz.":"En RCP, le marqueur rouge « BRAF V600E » attire immédiatement l’attention. Quelqu’un propose de traiter le cas comme un mélanome BRAF muté ; un autre affirme que côté droit plus BRAF signifie probablement de toute façon MSI-high. Les deux idées paraissent plausibles au premier abord – et toutes deux sont insuffisantes.","72-jährige Patientin mit rechtsseitigem metastasiertem CRC. BRAF p.V600E wurde bereits nachgewiesen. Die Lernaufgabe besteht darin, die Mutation entitätsspezifisch zu interpretieren, MMR/MSI unabhängig zu klären und aus Prognose, Immuntherapie- und BRAF-Targetkontext eine belastbare MTB-Empfehlung zu formulieren.":"Patiente de 72 ans avec CRC métastatique droit. BRAF p.V600E est déjà connu. L’objectif pédagogique est d’interpréter la mutation de façon spécifique à l’entité, de clarifier MMR/MSI indépendamment et de formuler une recommandation robuste de RCP intégrant pronostic, immunothérapie et contexte de ciblage de BRAF.","Tumorbiologie":"Biologie tumorale","Rechtsseitiges metastasiertes CRC mit BRAF V600E.":"CRC métastatique droit avec BRAF V600E.","BRAF ist ein starker biologischer Kontextmarker, aber nicht die gesamte Therapieentscheidung.":"BRAF est un marqueur contextuel biologique fort, mais ne constitue pas l’ensemble de la décision thérapeutique.","Zu Beginn noch unbekannt.":"Initialement inconnu.","BRAF V600E und MSI-H sind assoziiert, aber nicht synonym.":"BRAF V600E et MSI-H sont associés, mais ne sont pas synonymes.","Therapiekontext":"Contexte thérapeutique","Erstlinienentscheidung steht an.":"Décision de première ligne en attente.","BRAF-Targeting im CRC folgt einer anderen Logik als beim Melanom.":"Le ciblage de BRAF dans le CRC suit une logique différente de celle du mélanome.","Schneller BRAF-Befund":"Résultat BRAF rapide","BRAF p.V600E positiv.":"BRAF p.V600E positif.","Rechtsseitiges kolorektales Adenokarzinom, metastasiert.":"Adénocarcinome colorectal droit, métastatique.","Material ausreichend für MMR-IHC und MSI-Testung.":"Matériel suffisant pour IHC MMR et test MSI.","Zehn Schnitte reichen für eine fokussierte CRC-Diagnostik.":"Dix lames suffisent pour un diagnostic CRC ciblé.","Melanom-spezifische Zusatztests sind methodisch und didaktisch Low Value.":"Les tests supplémentaires spécifiques du mélanome ont une faible valeur méthodologique et pédagogique.","MMR/MSI muss trotz bekanntem BRAF-Befund eigenständig beantwortet werden.":"MMR/MSI doit être déterminé indépendamment malgré le résultat BRAF connu.","Welche Aussage zum BRAF-V600E-Befund ist im mCRC am treffendsten?":"Quelle affirmation concernant BRAF V600E dans le mCRC est la plus juste ?","BRAF V600E ist prognostisch und therapeutisch relevant, muss aber nach CRC-spezifischer Evidenz interpretiert werden; ein Melanom-Algorithmus darf nicht übertragen werden.":"BRAF V600E est pertinent sur les plans pronostique et thérapeutique, mais doit être interprété selon les données spécifiques au CRC ; un algorithme de mélanome ne doit pas être transposé.","BRAF V600E bedeutet unabhängig von der Entität denselben BRAF/MEK-Algorithmus wie beim Melanom.":"BRAF V600E implique le même algorithme BRAF/MEK que dans le mélanome, quelle que soit l’entité.","BRAF V600E ist beim CRC nur prognostisch, nicht therapeutisch relevant.":"Dans le CRC, BRAF V600E est uniquement pronostique, sans pertinence thérapeutique.","Bei rechtsseitigem CRC spielt BRAF keine Rolle.":"Dans le CRC droit, BRAF n’a pas d’importance.","Entitätsspezifische Biologie und Therapiedaten sind entscheidend.":"La biologie spécifique à l’entité et les données thérapeutiques sont déterminantes.","BRAF V600E ist nachgewiesen. Was folgt für MMR/MSI?":"BRAF V600E est détecté. Qu’en déduire pour MMR/MSI ?","MMR/MSI weiterhin separat bestimmen; BRAF V600E beweist weder dMMR noch MSI-H.":"Continuer à évaluer MMR/MSI séparément ; BRAF V600E ne prouve ni dMMR ni MSI-H.","BRAF V600E reicht als Surrogat für MSI-H.":"BRAF V600E suffit comme substitut de MSI-H.","MMR/MSI ist bei BRAF-mutiertem mCRC therapeutisch bedeutungslos.":"MMR/MSI est sans pertinence thérapeutique dans le mCRC BRAF muté.","PD-L1 ersetzt die MSI-Testung.":"PD-L1 remplace le test MSI.","Die MMR/MSI-Ebene besitzt eine unabhängige prädiktive und ggf. hereditäre Bedeutung.":"Le niveau MMR/MSI a une signification prédictive indépendante et potentiellement héréditaire.","Welche Targetlogik ist für BRAF V600E im mCRC korrekt?":"Quelle logique de ciblage est correcte pour BRAF V600E dans le mCRC ?","CRC-spezifische BRAF-gerichtete Strategie unter Einbezug der EGFR-Achse gemäß aktueller Therapielinie/Leitlinie.":"Stratégie de ciblage de BRAF spécifique au CRC intégrant l’axe EGFR selon la ligne thérapeutique/les recommandations actuelles.","BRAF-Inhibitor allein ist die logische Standardstrategie.":"Un inhibiteur de BRAF seul est la stratégie standard logique.","BRAF/MEK wie beim Melanom ohne CRC-spezifischen Kontext.":"BRAF/MEK comme dans le mélanome sans contexte spécifique au CRC.","BRAF V600E ist nicht targetierbar.":"BRAF V600E n’est pas ciblable.","Beim CRC ist die EGFR-Rückkopplung/Signalachse Teil der therapeutischen BRAF-Logik.":"Dans le CRC, la rétroaction/la signalisation EGFR fait partie de la logique thérapeutique de BRAF.","Interpretieren Sie BRAF V600E in einem rechtsseitigen mCRC und vervollständigen Sie MMR/MSI so, dass Prognose, Immuntherapie- und BRAF-Targetkontext sauber getrennt und integriert werden.":"Interpréter BRAF V600E dans un mCRC droit et compléter MMR/MSI afin de séparer clairement puis intégrer pronostic, immunothérapie et contexte de ciblage de BRAF.","BRAF-V600E-Befund entitätsspezifisch bestätigen/einordnen.":"Confirmer/classer le résultat BRAF V600E de façon spécifique à l’entité.","MMR-IHC und MSI unabhängig bestimmen.":"Déterminer indépendamment IHC MMR et MSI.","Ergebnis pMMR/MSS explizit kommunizieren.":"Communiquer explicitement le résultat pMMR/MSS.","BRAF V600E als prognostisch ungünstigen und therapeutisch relevanten CRC-Kontext berichten.":"Rapporter BRAF V600E comme contexte CRC de mauvais pronostic et thérapeutiquement pertinent.","Keinen Melanom-Algorithmus übertragen; aktuelle CRC-spezifische BRAF/EGFR-Strategie heranziehen.":"Ne pas transposer un algorithme de mélanome ; utiliser la stratégie BRAF/EGFR actuelle spécifique au CRC.","Kolon-NGS-Panel zur gemeinsamen Erfassung von BRAF/RAS plus separate MMR-IHC/MSI.":"Panel NGS colorectal pour la détection conjointe BRAF/RAS plus IHC MMR/MSI séparés.","Breiteres validiertes Pan-Panel, sofern BRAF und MSI zuverlässig abgedeckt und die MMR-IHC sinnvoll ergänzt werden.":"Pan-panel validé plus large à condition que BRAF et MSI soient couverts de façon fiable et que l’IHC MMR soit ajoutée de façon appropriée.","Melanom-BRAF-Template":"Template BRAF de mélanome","Gleiche Mutation bedeutet nicht gleichen Therapiealgorithmus über Tumorentitäten hinweg.":"La même mutation n’implique pas le même algorithme thérapeutique dans toutes les entités tumorales.","BRAF = MSI-H":"BRAF = MSI-H","Assoziation ist kein Ersatz für MMR/MSI-Diagnostik.":"Une association ne remplace pas le diagnostic MMR/MSI.","BRAF allein befundet":"BRAF rapporté seul","Der Immuntherapie-/MMR-Kontext bleibt offen.":"Le contexte immunothérapie/MMR reste non résolu.","BRAF V600E – aber pMMR/MSS":"BRAF V600E – mais pMMR/MSS","Die MMR-IHC ist vollständig erhalten und die MSI-Testung zeigt MSS. Der rechtsseitige BRAF-V600E-Tumor ist damit gerade kein MSI-H-Fall. Gleichzeitig wird klar: Der BRAF-Befund führt nicht in einen Melanom-Pfad, sondern in eine CRC-spezifische BRAF-/EGFR-Therapielogik.":"L’IHC MMR est entièrement conservée et le test MSI montre MSS. La tumeur droite BRAF V600E n’est donc précisément pas un cas MSI-H. En parallèle, il devient clair que le résultat BRAF ne conduit pas vers une voie de mélanome mais vers une logique thérapeutique BRAF/EGFR spécifique au CRC.","Der Fall löst zwei häufige Kurzschlüsse gleichzeitig auf: BRAF ist weder ein MSI-Surrogat noch eine entitätsunabhängige Therapieschablone.":"Le cas corrige deux raccourcis fréquents à la fois : BRAF n’est ni un substitut de MSI ni un template thérapeutique indépendant de l’entité.","CRC-spezifisch vollständig":"Complet et spécifique au CRC","BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Prognostisch ungünstiger BRAF-Kontext; CRC-spezifische BRAF-gerichtete Strategie mit EGFR-Blockade nach aktueller Linie/Leitlinie diskutieren.":"BRAF V600E, KRAS/NRAS WT, pMMR/MSS. Contexte BRAF de mauvais pronostic ; discuter une stratégie de ciblage de BRAF spécifique au CRC avec blocage d’EGFR selon la ligne/les recommandations actuelles.","Entität, MSI und Targetlogik korrekt integriert.":"Entité, MSI et logique de ciblage correctement intégrés.","Nur BRAF":"BRAF seul","BRAF V600E ist bekannt, MMR/MSI bleibt offen.":"BRAF V600E est connu ; MMR/MSI reste non résolu.","Therapeutisch und biologisch unvollständig.":"Incomplet sur les plans thérapeutique et biologique.","Melanom-Copyover":"Copyover de mélanome","BRAF/MEK-Logik wird ohne CRC-spezifischen Kontext übertragen.":"La logique BRAF/MEK est transposée sans contexte spécifique au CRC.","Cross-Entity-Fehlinterpretation.":"Mauvaise interprétation inter-entités.","pMMR/MSS bestätigt":"pMMR/MSS confirmé","BRAF- und Chemotherapie-/EGFR-Kontext nach aktueller Linie im MTB diskutieren.":"Discuter en RCP le contexte BRAF et chimiothérapie/EGFR selon la ligne thérapeutique actuelle.","Der Fall bleibt Targeted-Therapy-orientiert, ohne MSI-H-IO-Pfad.":"Le cas reste orienté vers la thérapie ciblée, sans voie IO liée à MSI-H.","unerwartet dMMR/MSI-H":"dMMR/MSI-H inattendu","Immuntherapie- und Lynch/sporadisch-Kontext zusätzlich priorisieren.":"Prioriser aussi l’immunothérapie et le contexte Lynch/sporadique.","Therapiepriorisierung verändert sich.":"La priorisation thérapeutique change.","BRAF V600E ist im CRC entitätsspezifisch zu interpretieren.":"BRAF V600E doit être interprété de façon spécifique à l’entité dans le CRC.","BRAF V600E und MSI-H sind nicht gleichbedeutend.":"BRAF V600E et MSI-H ne sont pas équivalents.","MMR/MSI bleibt ein unabhängiger Biomarkerblock.":"MMR/MSI reste un bloc de biomarqueurs indépendant.","BRAF-gerichtete Therapie im CRC bindet die EGFR-Achse ein und darf nicht aus dem Melanom kopiert werden.":"Le traitement ciblant BRAF dans le CRC intègre l’axe EGFR et ne doit pas être copié du mélanome.","BRAF V600E + pMMR/MSS im rechtsseitigen mCRC. Kein Melanom-Algorithmus; CRC-spezifische BRAF-/EGFR-Strategie nach aktueller Therapielinie. MMR/MSI separat bestimmt und korrekt negativ eingeordnet.":"BRAF V600E + pMMR/MSS dans un mCRC droit. Pas d’algorithme de mélanome ; stratégie BRAF/EGFR spécifique au CRC selon la ligne thérapeutique actuelle. MMR/MSI évalué séparément et correctement interprété comme négatif.","Entitätsspezifische BRAF-Interpretation":"Interprétation BRAF spécifique à l’entité","MMR/MSI unabhängig geprüft":"MMR/MSI évalué indépendamment","kein Melanom-Copyover":"pas de copyover de mélanome","Prognose vs. Prädiktion getrennt":"Pronostic vs prédiction séparés","Warum ist BRAF V600E kein MSI-Surrogat?":"Pourquoi BRAF V600E n’est-il pas un substitut de MSI ?","Warum reicht BRAF-Hemmung allein im CRC biologisch/klinisch nicht als Übertrag aus dem Melanom?":"Pourquoi l’inhibition de BRAF seule ne peut-elle pas être transposée biologiquement/cliniquement du mélanome au CRC ?","Welche Rolle spielt die Tumorlokalisation zusätzlich?":"Quel rôle supplémentaire joue la latéralité tumorale ?","DE master":"Master DE","BRAF V600E, aber pMMR/MSS":"BRAF V600E, mais pMMR/MSS","Mutation ist entitätsspezifisch zu interpretieren":"La mutation doit être interprétée de façon spécifique à l’entité","BRAF+ → MMR/MSI separat → pMMR/MSS → CRC-spezifische BRAF/EGFR-Logik":"BRAF+ → évaluer MMR/MSI séparément → pMMR/MSS → logique BRAF/EGFR spécifique au CRC","Polypenrest statt invasivem Tumor eingeschickt → Befundbar oder neues Material anfordern?":"Reste de polype envoyé au lieu de la tumeur invasive → Peut-on rendre un résultat ou faut-il demander un nouveau matériel ?","Polypenrest statt invasivem Tumor …":"Reste de polype au lieu de la tumeur invasive …","Viszeralonkologie / Molekularpathologie":"Oncologie digestive / Pathologie moléculaire","64-jähriger Patient mit metastasiertem Sigma-Karzinom; vor Beginn der Systemtherapie werden RAS/BRAF und MMR/MSI angefordert.":"Patient de 64 ans avec carcinome sigmoïdien métastatique ; RAS/BRAF et MMR/MSI sont demandés avant le traitement systémique.","Der eingesandte Block soll 'repräsentatives Tumorgewebe' enthalten. Ist das Material tatsächlich für die prädiktive Diagnostik geeignet?":"Le bloc envoyé est censé contenir « du tissu tumoral représentatif ». Le matériel est-il réellement adapté au diagnostic prédictif ?","MTB in vier Tagen; die Onkologie bittet ausdrücklich um eine schnelle Freigabe.":"RCP moléculaire dans quatre jours ; l’oncologie demande explicitement une libération rapide.","Vorgeschichte":"Antécédents","Zunächst endoskopische Polypektomie, anschließend onkologische Sigmaresektion mit invasivem Adenokarzinom; inzwischen Lebermetastasen.":"Initialement polypectomie endoscopique, puis résection oncologique du sigmoïde montrant un adénocarcinome invasif ; désormais métastases hépatiques.","Anforderung":"Demande","Auf dem Molekularschein steht Block 'A1'. Im Pathologiesystem existieren jedoch sowohl Polypektomie A1 als auch Resektionsblock B7.":"La demande moléculaire indique le bloc « A1 ». Dans le système de pathologie, il existe cependant à la fois la polypectomie A1 et le bloc de résection B7.","Ein automatisches 'Material vorhanden → testen' wäre schnell, könnte aber die falsche Läsion analysieren.":"Une approche automatique « matériel disponible → tester » serait rapide, mais pourrait analyser la mauvaise lésion.","Technisch erfolgreiche Molekulardiagnostik ist nicht automatisch klinisch valide, wenn das untersuchte Gewebe die Fragestellung nicht repräsentiert.":"Un diagnostic moléculaire techniquement réussi n’est pas automatiquement cliniquement valide si le tissu analysé ne représente pas la question clinique.","HE-Reevaluation des eingesandten Blocks":"Réévaluation H&E du bloc envoyé","Tubulovillöses Adenom mit hochgradiger intraepithelialer Neoplasie; kein sicher invasives Karzinom im eingesandten Material.":"Adénome tubulo-villeux avec néoplasie intraépithéliale de haut grade ; aucun carcinome invasif certain dans le matériel envoyé.","Diskrepanz":"Discordance","Die klinische Anforderung lautet metastasiertes CRC, der ausgewählte Block repräsentiert jedoch nur den früheren Polypenrest.":"La demande clinique concerne un CRC métastatique, mais le bloc sélectionné ne représente que le reste de l’ancien polype.","Verfügbarer Alternativblock":"Bloc alternatif disponible","Im Archiv ist Resektionsblock B7 mit invasivem Adenokarzinom und ca. 60 % Tumor dokumentiert.":"Le bloc de résection B7, contenant un adénocarcinome invasif avec env. 60 % de tumeur, est documenté dans les archives.","Darf der Polypenblock trotzdem molekular befundet werden oder muss die Analyse gestoppt und repräsentatives invasives Tumormaterial angefordert werden?":"Le bloc de polype peut-il malgré tout faire l’objet d’un compte rendu moléculaire ou faut-il arrêter l’analyse et demander du tissu tumoral invasif représentatif ?","Eingesandter Block":"Bloc envoyé","Polypektomie A1, adenomatöses Gewebe ohne sichere Invasion.":"Polypectomie A1, tissu adénomateux sans invasion certaine.","Tumoranteil für die klinische Fragestellung":"Fraction tumorale pour la question clinique","0 % sicher invasives Karzinom.":"0 % de carcinome invasif certain.","Technische DNA-Qualität":"Qualité technique de l’ADN","gut – genau das macht die Falle gefährlich.":"bonne – précisément ce qui rend le piège dangereux.","Archivhinweis":"Note d’archive","Resektionsblock B7 ist verfügbar und enthält repräsentatives invasives Karzinom.":"Le bloc de résection B7 est disponible et contient un carcinome invasif représentatif.","Ein molekular technisch plausibler Befund aus dem Polypenrest darf nicht als Biomarkerbefund des metastasierten invasiven Karzinoms ausgegeben werden.":"Un résultat moléculaire techniquement plausible provenant du reste de polype ne doit pas être rendu comme résultat de biomarqueurs du carcinome invasif métastatique.","Materialidentität / HE-Reevaluation":"Identité du matériel / réévaluation H&E","Repräsentatives invasives Tumormaterial anfordern":"Demander du tissu tumoral invasif représentatif","HE-Reevaluation":"Réévaluation H&E","Im eingesandten Block findet sich adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Das Material repräsentiert die klinische Fragestellung nicht.":"Le bloc envoyé contient du tissu adénomateux avec dysplasie de haut grade, mais aucun carcinome invasif certain. Le matériel ne représente pas la question clinique.","Neues / korrektes Tumormaterial":"Nouveau / bon matériel tumoral","Resektionsblock B7 wird nachgefordert: invasives kolorektales Adenokarzinom, ca. 60 % Tumoranteil, für prädiktive Molekulardiagnostik geeignet.":"Le bloc de résection B7 est demandé : adénocarcinome colorectal invasif, env. 60 % de fraction tumorale, adapté au diagnostic moléculaire prédictif.","MMR/MSI auf dem falschen Block":"MMR/MSI sur le mauvais bloc","Die Untersuchung kann technisch auswertbar sein, beantwortet aber am adenomatösen Polypenrest die Biomarkerfrage des invasiven/metastasierten Karzinoms nicht belastbar. Keine klinische Freigabe als Tumorbefund.":"Le test peut être techniquement interprétable, mais sur le reste adénomateux du polype il ne répond pas de façon fiable à la question de biomarqueurs du carcinome invasif/métastatique. Ne pas le libérer cliniquement comme résultat tumoral.","NGS/RAS/BRAF auf dem falschen Block":"NGS/RAS/BRAF sur le mauvais bloc","Technisch plausibler Befund aus adenomatösem Gewebe – z. B. APC-Alteration bei fehlendem RAS/BRAF-Nachweis. Dieser Befund darf nicht als prädiktiver Status des invasiven/metastasierten CRC interpretiert werden.":"Résultat techniquement plausible sur tissu adénomateux – p. ex. altération APC sans détection RAS/BRAF. Il ne doit pas être interprété comme le statut prédictif du CRC invasif/métastatique.","Präanalytik":"Pré-analytique","Anforderung, Blockbezeichnung und Histologie sind diskordant; vor Freigabe muss die Probenidentität bzw. Repräsentativität geklärt werden.":"La demande, la désignation du bloc et l’histologie sont discordantes ; l’identité/la représentativité de l’échantillon doit être clarifiée avant libération.","Der eingesandte Polypenblock ist für die prädiktive Diagnostik des metastasierten invasiven CRC nicht geeignet. Die Analyse muss für diese klinische Fragestellung gestoppt bzw. nicht freigegeben und repräsentatives invasives Tumormaterial angefordert werden. Ein technisch erfolgreicher Befund aus dem falschen Gewebe wäre klinisch irreführend.":"Le bloc de polype envoyé n’est pas adapté au diagnostic prédictif du CRC invasif métastatique. L’analyse doit être arrêtée/ne pas être libérée pour cette question clinique et du tissu tumoral invasif représentatif doit être demandé. Un résultat techniquement réussi sur le mauvais tissu serait cliniquement trompeur.","Teilbefund: Ohne HE-Reevaluation und Abgleich der Blockidentität bleibt unklar, ob das untersuchte Material den invasiven Tumor repräsentiert. Molekulare Ergebnisse dürfen nicht allein aufgrund technischer QC freigegeben werden.":"Résultat partiel : sans réévaluation H&E et vérification de l’identité du bloc, on ne sait pas si le matériel analysé représente la tumeur invasive. Les résultats moléculaires ne doivent pas être libérés sur la seule base du QC technique.","Falsches/nicht repräsentatives Material als primäres Problem erkennen":"Reconnaître le mauvais matériel/non représentatif comme problème principal","Molekulare Freigabe stoppen bzw. nicht als invasiven Tumor befundet ausgeben":"Arrêter la libération moléculaire ou ne pas la rendre comme résultat de tumeur invasive","Diskrepanz und Grund der Nachforderung transparent mit Klinik/Pathologie kommunizieren":"Communiquer de façon transparente la discordance et la raison de la nouvelle demande avec les cliniciens/la pathologie","Technische Validität klar von klinischer Validität unterscheiden":"Distinguer clairement validité technique et validité clinique","Optimale Lösung: zuerst HE und Materialidentität prüfen; der eingesandte Polypenrest ist klinisch ungeeignet. Nicht 'irgendetwas' sequenzieren und befundbar machen, sondern den richtigen invasiven Tumorblock anfordern.":"Solution optimale : vérifier d’abord H&E et l’identité du matériel ; le reste de polype envoyé est cliniquement inadapté. Ne pas séquencer « ce qui est là » pour rendre un résultat ; demander le bon bloc de tumeur invasive.","falsches Material":"mauvais matériel","Materialidentität":"Identité du matériel","LAB":"LAB","Falscher Block, perfektes QC: Wann ein technisch guter Befund klinisch wertlos ist":"Mauvais bloc, QC parfait : quand un bon résultat technique est cliniquement sans valeur","Molekularpathologie / Pathologieassistenz / Labor":"Pathologie moléculaire / Assistance en pathologie / Laboratoire","Repräsentativität des Materials vor Molekulardiagnostik prüfen.":"Vérifier la représentativité du matériel avant le diagnostic moléculaire.","Technische Validität von klinischer Validität unterscheiden.":"Distinguer validité technique et validité clinique.","Bei falschem/nicht invasivem Material die Freigabe stoppen und korrektes Tumorgewebe anfordern.":"En cas de mauvais matériel/non invasif, arrêter la libération et demander le bon tissu tumoral.","Eine Präanalytik-Diskrepanz nachvollziehbar dokumentieren und kommunizieren.":"Documenter et communiquer de façon traçable une discordance pré-analytique.","Die DNA-QC ist hervorragend, der Tumorboard-Termin ist nah und der Auftrag lautet RAS/BRAF/MMR/MSI. Der einzige Haken: Auf dem Kontroll-HE liegt gar kein invasives Karzinom, sondern nur der Rest eines früheren Adenoms. Genau jetzt entscheidet sich, ob 'gute Technik' zur gefährlichen Scheinsicherheit wird.":"Le QC ADN est excellent, la RCP approche et la demande porte sur RAS/BRAF/MMR/MSI. Seul problème : sur le contrôle H&E, il n’y a aucun carcinome invasif, uniquement le reste d’un ancien adénome. C’est précisément là que la « bonne technique » peut devenir une dangereuse fausse sécurité.","64-jähriger Patient mit metastasiertem Sigma-Karzinom. Für die prädiktive Molekulardiagnostik wurde versehentlich der Block einer früheren Polypektomie ausgewählt. Er enthält adenomatöses Gewebe mit hochgradiger Dysplasie, aber kein sicher invasives Karzinom. Ein repräsentativer Resektionsblock ist im Archiv vorhanden.":"Patient de 64 ans avec carcinome sigmoïdien métastatique. Le bloc d’une ancienne polypectomie a été sélectionné par erreur pour le diagnostic moléculaire prédictif. Il contient du tissu adénomateux avec dysplasie de haut grade, mais aucun carcinome invasif certain. Un bloc de résection représentatif est disponible dans les archives.","RAS/BRAF und MMR/MSI vor Systemtherapie.":"RAS/BRAF et MMR/MSI avant traitement systémique.","Die klinische Frage bezieht sich auf das invasive/metastasierte Karzinom.":"La question clinique concerne le carcinome invasif/métastatique.","Polypektomie A1 mit Adenom/HGIEN, ohne sichere Invasion.":"Polypectomie A1 avec adénome/HGIEN, sans invasion certaine.","Die Probenidentität ist klinisch falsch, obwohl die DNA technisch gut sein kann.":"L’identité de l’échantillon est cliniquement erronée, même si l’ADN peut être techniquement bon.","Alternativmaterial":"Matériel alternatif","Resektionsblock B7 mit ca. 60 % invasivem Tumor ist verfügbar.":"Le bloc de résection B7 avec env. 60 % de tumeur invasive est disponible.","Die richtige Lösung ist Nachforderung/Blockwechsel, nicht Interpretation des falschen Materials.":"La bonne solution est de demander/changer de bloc, pas d’interpréter le mauvais matériel.","Kein sicher invasives Karzinom im eingesandten Block.":"Aucun carcinome invasif certain dans le bloc envoyé.","Sehr gute DNA-Qualität – technisch wären PCR/NGS problemlos möglich.":"Très bonne qualité d’ADN – techniquement PCR/NGS seraient simples.","LIMS-Abgleich":"Vérification LIMS","Block A1 gehört zur Polypektomie; Resektionsblock B7 trägt den invasiven Tumor.":"Le bloc A1 correspond à la polypectomie ; le bloc de résection B7 contient la tumeur invasive.","MTB in vier Tagen erzeugt realen Zeitdruck.":"La RCP dans quatre jours crée une vraie pression temporelle.","Das korrekte Material existiert, muss aber aktiv nachgefordert/umgebucht werden.":"Le bon matériel existe mais doit être activement demandé/réaffecté.","Jede Molekulardiagnostik am falschen Block produziert potenziell einen technisch plausiblen, klinisch irreführenden Befund.":"Tout test moléculaire sur le mauvais bloc peut produire un résultat techniquement plausible mais cliniquement trompeur.","Was ist der nächste entscheidende Schritt?":"Quelle est la prochaine étape décisive ?","HE/Blockidentität prüfen, Analyse am Polypenrest stoppen und repräsentatives invasives Tumormaterial anfordern.":"Vérifier H&E/l’identité du bloc, arrêter l’analyse sur le reste de polype et demander du tissu tumoral invasif représentatif.","Wegen des MTB-Termins sofort NGS durchführen; gute DNA-QC reicht.":"En raison de l’échéance de la RCP, lancer immédiatement le NGS ; un bon QC ADN suffit.","Nur MMR-IHC durchführen und den Rest später entscheiden.":"Réaliser uniquement l’IHC MMR et décider du reste plus tard.","Molekularbefund aus dem Adenom als Status des metastasierten CRC berichten.":"Rapporter le résultat moléculaire de l’adénome comme statut du CRC métastatique.","Präanalytische Repräsentativität ist Voraussetzung jeder klinischen Interpretation.":"La représentativité pré-analytique est un prérequis à toute interprétation clinique.","Ein NGS-Lauf aus dem Polypenrest ist technisch valide. Ist der Befund damit klinisch valide?":"Un run NGS à partir du reste de polype est techniquement valide. Le résultat est-il pour autant cliniquement valide ?","Nein. Ein technisch korrekter Befund kann klinisch unbrauchbar sein, wenn das analysierte Gewebe die Fragestellung nicht repräsentiert.":"Non. Un résultat techniquement correct peut être cliniquement inutilisable si le tissu analysé ne représente pas la question clinique.","Ja. Technische QC ist die einzige Voraussetzung für Freigabe.":"Oui. Le QC technique est le seul prérequis à la libération.","Ja, sofern RAS/BRAF Wildtyp sind.":"Oui, à condition que RAS/BRAF soient wild type.","Ja, wenn ein breites Panel benutzt wurde.":"Oui, si un panel large a été utilisé.","Analytische Qualität ersetzt nicht Probenidentität und klinische Repräsentativität.":"La qualité analytique ne remplace ni l’identité de l’échantillon ni sa représentativité clinique.","Wie soll die Diskrepanz behandelt werden?":"Comment gérer la discordance ?","Dokumentieren, Einsender/Pathologie kontaktieren, korrekten Block nachfordern und erst dann prädiktiv testen.":"Documenter, contacter le prescripteur/la pathologie, demander le bon bloc et seulement ensuite réaliser le test prédictif.","Intern korrigieren, aber nicht dokumentieren.":"Corriger en interne, mais ne pas documenter.","Annehmen, dass Polyp und Karzinom denselben Biomarkerstatus haben.":"Supposer que le polype et le carcinome ont le même statut de biomarqueurs.","Gesamten Fall endgültig abbrechen, obwohl geeignetes Material vorhanden ist.":"Abandonner définitivement tout le cas alors qu’un matériel adapté est disponible.","Rückverfolgbarkeit und transparente Kommunikation gehören zur Fehlerbeherrschung.":"La traçabilité et la communication transparente font partie de la maîtrise des erreurs.","Entscheiden Sie, ob der Polypenrest befundbar ist, und steuern Sie den Fall so, dass nur repräsentatives invasives Tumorgewebe in die prädiktive Diagnostik eingeht.":"Décider si le reste de polype est rapportable et gérer le cas afin que seul du tissu tumoral invasif représentatif entre dans le diagnostic prédictif.","Kontroll-HE des ausgewählten Blocks prüfen.":"Revoir le contrôle H&E du bloc sélectionné.","Diskrepanz zwischen Anforderung und Histologie erkennen.":"Reconnaître la discordance entre demande et histologie.","Molekulare Freigabe am Polypenrest stoppen.":"Arrêter la libération moléculaire à partir du reste de polype.","Resektionsblock B7 bzw. anderes repräsentatives invasives Material anfordern.":"Demander le bloc de résection B7 ou un autre matériel invasif représentatif.","Diskrepanz und Kommunikation dokumentieren.":"Documenter la discordance et la communication.","Erst am korrekten Tumormaterial mit RAS/BRAF/MMR/MSI fortfahren.":"Ne poursuivre RAS/BRAF/MMR/MSI que sur le bon matériel tumoral.","Geeignete Metastasenbiopsie anfordern, falls der Resektionsblock nicht verfügbar/qualitativ ungeeignet wäre.":"Demander une biopsie métastatique adaptée si le bloc de résection n’est pas disponible/est qualitativement inadéquat.","'DNA ist gut, also los'":"« L’ADN est bon, donc on y va »","Technische QC sagt nichts darüber aus, ob die richtige Läsion untersucht wird.":"Le QC technique ne dit rien sur le fait que la bonne lésion soit analysée.","Adenom-Biomarker = Karzinom-Biomarker":"Biomarqueur d’adénome = biomarqueur de carcinome","Klonale Evolution und fehlende Repräsentativität machen diese Gleichsetzung unzulässig.":"L’évolution clonale et le manque de représentativité rendent cette équivalence invalide.","Zeitdruck als Freigabeargument":"La pression temporelle comme argument de libération","Ein schneller falscher Befund ist schlechter als eine dokumentierte Nachforderung.":"Un résultat faux rendu rapidement est pire qu’une demande documentée du bon matériel.","Der falsche Block liefert einen überzeugenden Befund":"Le mauvais bloc donne un résultat convaincant","Wird voreilig sequenziert, zeigt das Adenom eine plausible APC-Alteration und keinen RAS/BRAF-Treiber. Technisch sieht alles sauber aus. Erst der HE-/LIMS-Abgleich zeigt, dass dieser Befund für das invasive metastasierte CRC gar nicht freigegeben werden darf.":"Si le séquençage est réalisé trop tôt, l’adénome montre une altération APC plausible et aucun driver RAS/BRAF. Techniquement, tout paraît propre. Seul le contrôle H&E/LIMS révèle que ce résultat ne doit pas être libéré pour le CRC invasif métastatique.","Die gefährlichsten Präanalytikfehler produzieren nicht zwingend einen technischen Fehler – sondern einen glaubwürdigen Befund am falschen Material.":"Les erreurs pré-analytiques les plus dangereuses ne produisent pas nécessairement une erreur technique – elles peuvent produire un résultat crédible sur le mauvais matériel.","Materialfehler vor Analytik gestoppt":"Erreur de matériel arrêtée avant analyse","HE zeigt kein invasives Karzinom; korrekter Resektionsblock B7 wird angefordert.":"H&E ne montre aucun carcinome invasif ; le bon bloc de résection B7 est demandé.","Patientensicher und ressourcenschonend.":"Sûr pour le patient et économe en ressources.","Technisch erfolgreich, klinisch falsch":"Techniquement réussi, cliniquement faux","NGS aus Adenom: APC-Alteration, RAS/BRAF WT. Befund darf nicht als metastasiertes CRC interpretiert werden.":"NGS sur adénome : altération APC, RAS/BRAF WT. Le résultat ne doit pas être interprété comme celui du CRC métastatique.","Analytisch valide, klinisch invalide.":"Analytiquement valide, cliniquement invalide.","Falschen Block freigegeben":"Mauvais bloc libéré","Adenom-Befund wird als Tumorprofil berichtet.":"Le résultat de l’adénome est rapporté comme profil tumoral.","Kritischer Präanalytik-/Freigabefehler.":"Erreur critique pré-analytique/de libération.","Resektionsblock B7 verfügbar":"Bloc de résection B7 disponible","Kontroll-HE, Tumormarkierung und reguläre CRC-Biomarkerdiagnostik durchführen.":"Réaliser contrôle H&E, marquage tumoral et diagnostic standard des biomarqueurs CRC.","Der Fall kann ohne neue invasive Probengewinnung korrekt abgeschlossen werden.":"Le cas peut être correctement terminé sans obtenir de nouvel échantillon invasif.","Kein geeignetes Archivmaterial":"Aucun matériel d’archive adapté","Mit Klinik eine geeignete Metastasen- oder Primärtumorprobe abstimmen.":"Coordonner avec l’équipe clinique un échantillon adapté de métastase ou de tumeur primitive.","TAT steigt, klinische Validität bleibt gewahrt.":"Le TAT augmente, la validité clinique est préservée.","Materialidentität und Repräsentativität stehen vor analytischer QC.":"L’identité et la représentativité du matériel passent avant le QC analytique.","Ein technisch valider Befund kann klinisch falsch sein.":"Un résultat techniquement valide peut être cliniquement faux.","Polyp/Adenom ist kein automatischer Surrogatblock für ein invasives metastasiertes CRC.":"Le polype/l’adénome n’est pas un bloc substitut automatique pour un CRC invasif métastatique.","Zeitdruck rechtfertigt keine Freigabe aus falschem Material.":"La pression temporelle ne justifie pas de libérer un résultat à partir du mauvais matériel.","HE-Reevaluation zeigt nur Adenom/HGIEN. Molekulare Freigabe stoppen, Blockidentität klären und Resektionsblock B7 mit invasivem Tumor anfordern. Etwaige bereits erzeugte Daten aus dem Polypenrest nicht als prädiktiven Tumorbefund freigeben.":"La réévaluation H&E ne montre qu’un adénome/HGIEN. Arrêter la libération moléculaire, clarifier l’identité du bloc et demander le bloc de résection B7 avec tumeur invasive. Ne pas libérer d’éventuelles données déjà générées à partir du reste de polype comme résultat tumoral prédictif.","Präanalytik vor Analytik":"Pré-analytique avant analytique","Stop/No-Go korrekt":"Stop/No-Go correct","korrektes Material angefordert":"bon matériel demandé","technische vs. klinische Validität verstanden":"validité technique vs clinique comprise","Welche Kontrollen verhindern solche Blockverwechslungen?":"Quels contrôles préviennent ce type d’erreur de bloc ?","Wann kann ein Vorläuferläsionsblock überhaupt sinnvoll molekular untersucht werden?":"Quand un bloc de lésion précurseur peut-il être utilement étudié moléculairement ?","Wie dokumentiert man einen bereits erzeugten, aber klinisch nicht freigabefähigen Datensatz?":"Comment documenter un jeu de données déjà généré mais non libérable cliniquement ?","perfekte DNA aus falschem Gewebe":"ADN parfait du mauvais tissu","technisch valide ≠ klinisch valide":"techniquement valide ≠ cliniquement valide","HE → Diskrepanz → Stop → korrekter Block":"H&E → discordance → stop → bon bloc","HER2-amplifiziertes RAS-WT-CRC → HER2 als Resistenz-/Target-Kontext":"CRC RAS-WT amplifié HER2 → HER2 comme contexte de résistance/ciblage","HER2-amplifiziertes RAS-WT-CRC":"CRC RAS-WT amplifié HER2","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom. Initial RAS/BRAF-Wildtyp und pMMR/MSS; unter FOLFOX plus Cetuximab zunächst deutliche Remission, jetzt hepatischer Progress.":"Patient de 61 ans avec carcinome sigmoïdien métastatique gauche. Initialement RAS/BRAF wild type et pMMR/MSS ; nette rémission sous FOLFOX plus cetuximab, désormais progression hépatique.","Der Progressionsbefund zeigt weiterhin keine RAS- oder BRAF-Mutation, aber einen ERBB2/HER2-Copy-number-Hinweis. Wie ist das therapeutisch zu interpretieren?":"L’échantillon de progression ne montre toujours pas de mutation RAS ou BRAF, mais suggère un gain de nombre de copies ERBB2/HER2. Comment l’interpréter sur le plan thérapeutique ?","Die nächste Therapielinie soll im MTB in fünf Tagen festgelegt werden.":"La prochaine ligne thérapeutique doit être définie en RCP moléculaire dans cinq jours.","Sigma, linksseitig; initiale Resektion vor 18 Monaten.":"Sigmoïde, côté gauche ; résection initiale il y a 18 mois.","Initiales Molekularprofil":"Profil moléculaire initial","KRAS/NRAS Wildtyp, BRAF Wildtyp, pMMR/MSS.":"KRAS/NRAS wild type, BRAF wild type, pMMR/MSS.","Therapieverlauf":"Évolution thérapeutique","FOLFOX plus Cetuximab mit gutem initialem Ansprechen; nach 11 Monaten Progress einzelner Leberläsionen.":"FOLFOX plus cetuximab avec bonne réponse initiale ; progression de certaines lésions hépatiques après 11 mois.","Didaktischer Schlüssel":"Clé pédagogique","Der Satz 'RAS und BRAF negativ' ist beim mCRC therapeutisch nicht einfach 'kein Befund': Das Fehlen etablierter MAPK-Downstream-Resistenztreiber ist eine Voraussetzung, die anti-EGFR-Antikörperstrategie bei passendem klinischem Kontext überhaupt eröffnet.":"Dans le mCRC, la formule « RAS et BRAF négatifs » ne signifie pas simplement « aucun résultat » sur le plan thérapeutique : l’absence de drivers de résistance downstream MAPK établis est une condition qui rend possible une stratégie par anticorps anti-EGFR dans un contexte clinique approprié.","Warum kann der Tumor trotz weiterem RAS/BRAF-Wildtyp progredient sein, und welche Rolle spielt HER2?":"Pourquoi la tumeur peut-elle progresser malgré un statut RAS/BRAF toujours wild type, et quel rôle joue HER2 ?","Progressionsbiopsie":"Biopsie de progression","Lebermetastase eines kolorektalen Adenokarzinoms, vital und gut repräsentativ.":"Métastase hépatique d’adénocarcinome colorectal, viable et bien représentative.","ca. 65 %.":"env. 65 %.","Aus der Primärdiagnostik pMMR/MSS, klinisch ausreichend dokumentiert.":"pMMR/MSS issu du diagnostic initial, suffisamment documenté sur le plan clinique.","Progressionsprofil":"Profil de progression","Kein RAS-/BRAF-Resistenzbefund; ERBB2 mit deutlicher Copy-number-Erhöhung im DNA-Panel.":"Aucun résultat de résistance RAS/BRAF ; ERBB2 avec gain marqué du nombre de copies dans le panel ADN.","Ist die ERBB2-Veränderung bestätigt, und wie verändert sie die scheinbar 'negative' RAS/BRAF-Situation?":"L’altération ERBB2 est-elle confirmée et comment modifie-t-elle la situation RAS/BRAF apparemment « négative » ?","FFPE-Lebermetastasenbiopsie, Block L3.":"Biopsie FFPE de métastase hépatique, bloc L3.","ca. 65 %, DNA-QC sehr gut.":"env. 65 %, très bon QC ADN.","HER2-Bestätigung":"Confirmation HER2","IHC/ISH ist am vorhandenen Material möglich.":"IHC/ISH est réalisable sur le matériel disponible.","Breite Wiederholung bereits gesicherter MMR/MSI-Diagnostik verbraucht Material, während die konkrete Progressionsfrage HER2-Bestätigung und Resistenzkontext betrifft.":"Répéter largement un bilan MMR/MSI déjà établi consomme du matériel, alors que la question spécifique de progression concerne la confirmation HER2 et le contexte de résistance.","Progressionsprofil / RAS-BRAF-ERBB2-Kontext":"Profil de progression / contexte RAS-BRAF-ERBB2","HER2-Amplifikation bestätigen":"Confirmer l’amplification HER2","KRAS/NRAS weiterhin Wildtyp, BRAF Wildtyp; keine neue klassische RAS/RAF-Resistenzmutation. ERBB2 zeigt eine hochgradige Copy-number-Erhöhung.":"KRAS/NRAS restent wild type, BRAF wild type ; aucune nouvelle mutation classique de résistance RAS/RAF. ERBB2 montre un gain de nombre de copies de haut niveau.","KRAS/NRAS Wildtyp. Das Fehlen einer RAS-Mutation ist im geeigneten linksseitigen mCRC-Kontext therapeutisch relevant, garantiert aber keine dauerhafte Sensitivität gegenüber anti-EGFR-Antikörpern.":"KRAS/NRAS wild type. L’absence de mutation RAS est thérapeutiquement pertinente dans un contexte approprié de mCRC gauche, mais ne garantit pas une sensibilité durable aux anticorps anti-EGFR.","BRAF V600E nicht nachweisbar. RAS/BRAF-Wildtyp bedeutet nicht 'molekular ohne Bedeutung', sondern schließt wichtige etablierte MAPK-Resistenztreiber aus.":"BRAF V600E non détecté. RAS/BRAF wild type ne signifie pas « sans signification moléculaire » ; cela exclut d’importants drivers de résistance MAPK établis.","HER2 IHC/ISH":"IHC/ISH HER2","HER2 stark überexprimiert / ERBB2 amplifiziert. Der Befund ist im RAS/BRAF-WT-mCRC ein relevanter Target- und möglicher anti-EGFR-Resistenzkontext, insbesondere in der Progressionssituation.":"HER2 fortement surexprimé / ERBB2 amplifié. Dans le mCRC RAS/BRAF-WT, ce résultat constitue une cible pertinente et un possible contexte de résistance aux anti-EGFR, notamment en situation de progression.","HER2-IHC allein":"IHC HER2 seule","HER2 IHC 3+. Im CRC-Kontext sollte die zugrunde liegende ERBB2-Amplifikation bzw. ein validierter HER2-positiver Status nach lokalem Algorithmus gesichert werden.":"HER2 IHC 3+. Dans le contexte du CRC, l’amplification ERBB2 sous-jacente ou un statut HER2 positif validé doit être confirmé selon l’algorithme local.","Erneute MMR/MSI-Testung":"Répéter le test MMR/MSI","pMMR/MSS wird bestätigt. In diesem Fall war der Status bereits belastbar bekannt; die Wiederholung beantwortet die konkrete Progressions-/HER2-Frage kaum und ist daher eher ressourcenarm zu priorisieren.":"pMMR/MSS est confirmé. Dans ce cas, ce statut était déjà solidement connu ; le répéter répond peu à la question spécifique progression/HER2 et doit donc être peu prioritaire en termes de ressources.","Progressionsbiopsie repräsentativ; hohe Tumorzellularität und gute DNA-Qualität. Baseline-HER2-Status war nicht bestimmt.":"Biopsie de progression représentative ; forte cellularité tumorale et bonne qualité d’ADN. Le statut HER2 à baseline n’avait pas été déterminé.","RAS/BRAF-Wildtyp ist beim linksseitigen mCRC kein bedeutungsloser Negativbefund: Das Fehlen zentraler downstream MAPK-Resistenztreiber schafft erst die molekulare Voraussetzung für eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext. Wildtyp garantiert jedoch keine Sensitivität. Im Progress wird eine bestätigte ERBB2/HER2-Amplifikation gefunden, die einen alternativen Signalweg, einen möglichen anti-EGFR-Resistenzkontext und zugleich eine HER2-gerichtete Therapieoption im passenden Linien-/Zulassungskontext eröffnet. Ohne Baseline-HER2 kann nicht sicher behauptet werden, dass die Amplifikation neu erworben wurde.":"RAS/BRAF wild type n’est pas un résultat négatif dénué de sens dans le mCRC gauche : l’absence de drivers clés de résistance downstream MAPK crée le prérequis moléculaire à une stratégie par anticorps anti-EGFR dans le contexte clinique approprié. Le statut wild type ne garantit toutefois pas la sensibilité. À la progression, une amplification ERBB2/HER2 confirmée est trouvée, ouvrant une voie de signalisation alternative, un possible contexte de résistance aux anti-EGFR et, simultanément, une option thérapeutique ciblant HER2 dans le contexte approprié de ligne/d’autorisation. Sans statut HER2 à baseline, on ne peut affirmer avec certitude que l’amplification est nouvellement acquise.","Teilbefund: RAS/BRAF-Wildtyp ist korrekt erkannt, aber entweder wird 'negativ' fälschlich als therapeutisch bedeutungslos bezeichnet oder die ERBB2-Copy-number-Veränderung bleibt unbestätigt. Beides verhindert eine belastbare Progressionsinterpretation.":"Résultat partiel : le statut RAS/BRAF wild type est correctement reconnu, mais soit « négatif » est décrit à tort comme sans signification thérapeutique, soit l’altération du nombre de copies ERBB2 reste non confirmée. Dans les deux cas, l’interprétation de la progression n’est pas robuste.","Explizit erklären: RAS/BRAF-Wildtyp ist ein therapeutisch relevanter 'negativer' Befund, der anti-EGFR bei passendem linksseitigem mCRC-Kontext ermöglicht":"Expliquer explicitement : RAS/BRAF wild type est un résultat de sélection « négatif » mais thérapeutiquement pertinent, permettant les anti-EGFR dans le contexte approprié de mCRC gauche","Wildtyp nicht als Garantie für anti-EGFR-Sensitivität darstellen":"Ne pas présenter le wild type comme une garantie de sensibilité aux anti-EGFR","HER2-Amplifikation als alternativen Target-/Resistenzkontext integrieren":"Intégrer l’amplification HER2 comme contexte alternatif de ciblage/résistance","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher neu erworben":"Sans HER2 à baseline, ne pas affirmer que l’amplification est certainement nouvellement acquise","Aktuelle Linien-/Leitlinien-/Zulassungssituation für HER2-gerichtete Therapie transparent berücksichtigen":"Prendre en compte de façon transparente le contexte actuel de ligne/recommandations/autorisation pour le traitement ciblant HER2","Optimale Lösung: den RAS/BRAF-Wildtyp bewusst als therapeutisch positiven Selektionsbefund erklären; Progress trotz Wildtyp als Hinweis auf alternative Resistenzwege verstehen und die ERBB2/HER2-Amplifikation bestätigen und als Target-/Resistenzkontext integrieren.":"Solution optimale : expliquer délibérément RAS/BRAF wild type comme un résultat de sélection thérapeutiquement positif ; comprendre la progression malgré le wild type comme un indice de voies de résistance alternatives et confirmer l’amplification ERBB2/HER2, en l’intégrant comme contexte de ciblage/résistance.","RAS Wildtyp":"RAS wild type","BRAF Wildtyp":"BRAF wild type","ERBB2 Amplifikation":"Amplification ERBB2","Resistenz":"Résistance","Wenn 'negativ' therapeutisch positiv ist: RAS/BRAF-Wildtyp, anti-EGFR und der HER2-Twist":"Quand « négatif » est thérapeutiquement positif : RAS/BRAF wild type, anti-EGFR et le twist HER2","RAS/BRAF-Wildtyp als therapeutisch relevanten negativen Selektionsbefund im mCRC erklären.":"Expliquer RAS/BRAF wild type comme résultat négatif de sélection thérapeutiquement pertinent dans le mCRC.","Anti-EGFR-Eignung als Kontextentscheidung und nicht als garantierte Sensitivität verstehen.":"Comprendre l’éligibilité aux anti-EGFR comme une décision contextuelle et non comme une sensibilité garantie.","HER2/ERBB2-Amplifikation als alternativen Target- und möglichen Resistenzkontext integrieren.":"Intégrer l’amplification HER2/ERBB2 comme cible alternative et possible contexte de résistance.","Zwischen 'nach Progress nachgewiesen' und 'erworben' unterscheiden, wenn kein Baseline-HER2 vorliegt.":"Distinguer « détecté après progression » de « acquis » lorsqu’aucun statut HER2 à baseline n’est disponible.","Im Progressions-MTB steht auf der Folie: 'KRAS, NRAS, BRAF: keine Mutation nachweisbar'. Ein Kollege fasst zusammen: 'Molekular also wieder negativ.' Genau hier liegt der Kern des Falls: Beim mCRC kann ein negativer RAS/BRAF-Befund therapeutisch eine positive Information sein – und trotzdem erklärt er den jetzigen Progress nicht. Im selben Panel taucht nämlich eine deutliche ERBB2-Copy-number-Erhöhung auf.":"Sur la diapositive de RCP de progression, on lit : « KRAS, NRAS, BRAF : aucune mutation détectée ». Un collègue résume : « Donc, moléculairement négatif à nouveau. » C’est précisément le cœur du cas : dans le mCRC, un résultat RAS/BRAF négatif peut être une information thérapeutiquement positive – tout en n’expliquant pas la progression actuelle. Le même panel montre toutefois un gain marqué du nombre de copies ERBB2.","61-jähriger Patient mit linksseitigem metastasiertem Sigma-Karzinom, initial RAS/BRAF-Wildtyp und pMMR/MSS. Unter FOLFOX plus Cetuximab gutes Ansprechen, nach elf Monaten Progress in der Leber. Die Progressionsbiopsie bleibt RAS/BRAF-Wildtyp, zeigt aber eine hochgradige ERBB2-Copy-number-Erhöhung. Der Fall soll den scheinbaren Widerspruch 'negativ = therapeutisch positiv' erklären und anschließend HER2 als alternativen Resistenz-/Targetkontext einordnen.":"Patient de 61 ans avec carcinome sigmoïdien métastatique gauche, initialement RAS/BRAF wild type et pMMR/MSS. Bonne réponse à FOLFOX plus cetuximab, progression hépatique après 11 mois. La biopsie de progression reste RAS/BRAF wild type mais montre un gain de nombre de copies ERBB2 de haut niveau. Le cas vise à expliquer l’apparente contradiction « négatif = thérapeutiquement positif », puis à classer HER2 comme contexte alternatif de résistance/ciblage.","Baseline":"Baseline","Linksseitiges mCRC, RAS/BRAF-Wildtyp, pMMR/MSS.":"mCRC gauche, RAS/BRAF wild type, pMMR/MSS.","Dieser Molekularkontext ermöglichte grundsätzlich eine anti-EGFR-Antikörperstrategie.":"Ce contexte moléculaire rendait en principe possible une stratégie par anticorps anti-EGFR.","Gutes initiales Ansprechen unter FOLFOX + Cetuximab, Progress nach 11 Monaten.":"Bonne réponse initiale à FOLFOX + cetuximab, progression après 11 mois.","Wildtyp ist Selektion, keine Garantie dauerhafter Sensitivität.":"Le wild type est un critère de sélection, pas une garantie de sensibilité durable.","Weiterhin RAS/BRAF-Wildtyp, aber ERBB2-Copy-number hoch.":"Toujours RAS/BRAF wild type, mais nombre de copies ERBB2 élevé.","Resistenz kann über alternative Signalwege entstehen/bestehen.":"La résistance peut apparaître/persister via des voies de signalisation alternatives.","Limitation":"Limitation","HER2 wurde an der Baseline nicht bestimmt.":"HER2 n’a pas été évalué à baseline.","Die aktuelle Amplifikation darf nicht sicher als neu erworben bezeichnet werden.":"L’amplification actuelle ne peut pas être décrite avec certitude comme nouvellement acquise.","Initialdiagnostik":"Diagnostic initial","KRAS/NRAS WT, BRAF WT, pMMR/MSS.":"KRAS/NRAS WT, BRAF WT, pMMR/MSS.","Aktueller Progress":"Progression actuelle","Lebermetastasenbiopsie mit 65 % Tumor und guter DNA-QC.":"Biopsie de métastase hépatique avec 65 % de tumeur et bon QC ADN.","Panel-Hinweis":"Signal du panel","ERBB2 hochgradige Copy-number-Erhöhung; RAS/BRAF weiter WT.":"Gain de nombre de copies ERBB2 de haut niveau ; RAS/BRAF restent WT.","Neun Schnitte reichen für HER2-Bestätigung und fokussierte Progressionsdiagnostik.":"Neuf lames suffisent pour confirmer HER2 et réaliser un diagnostic ciblé de progression.","MMR/MSI ist bereits belastbar dokumentiert und muss nicht reflexartig wiederholt werden.":"MMR/MSI est déjà solidement documenté et ne doit pas être répété par réflexe.","HER2-Status sollte orthogonal/validiert bestätigt werden, bevor die therapeutische Schlussfolgerung formuliert wird.":"Le statut HER2 doit être confirmé par une méthode orthogonale/validée avant de formuler la conclusion thérapeutique.","Wie ist 'KRAS/NRAS/BRAF: keine pathogene Mutation nachweisbar' beim linksseitigen mCRC therapeutisch zu lesen?":"Comment lire thérapeutiquement « KRAS/NRAS/BRAF : aucune mutation pathogène détectée » dans le mCRC gauche ?","Als therapeutisch relevanter Wildtyp-/Ausschlussbefund: zentrale downstream MAPK-Resistenztreiber fehlen, sodass eine anti-EGFR-Antikörperstrategie im passenden klinischen Kontext grundsätzlich möglich wird.":"Comme résultat wild type/d’exclusion thérapeutiquement pertinent : les principaux drivers de résistance downstream MAPK sont absents, rendant possible une stratégie par anticorps anti-EGFR dans le contexte clinique approprié.","Als völlig bedeutungsloser Negativbefund ohne therapeutische Aussage.":"Comme résultat négatif totalement dépourvu de signification thérapeutique.","Als Garantie, dass anti-EGFR sicher und dauerhaft wirkt.":"Comme garantie que les anti-EGFR fonctionneront de façon certaine et durable.","Als Beweis, dass auch HER2 keine Rolle spielen kann.":"Comme preuve que HER2 ne peut pas non plus jouer de rôle.","Das Fehlen von RAS/BRAF-Treibern ist eine positive Selektionsinformation, aber keine Erfolgsgarantie.":"L’absence de drivers RAS/BRAF est une information positive de sélection, mais pas une garantie de succès.","Der Patient progrediert trotz weiterem RAS/BRAF-Wildtyp. Was ist die beste Interpretation?":"Le patient progresse malgré un statut RAS/BRAF toujours wild type. Quelle est la meilleure interprétation ?","Wildtyp schließt nur bestimmte Resistenzwege aus; alternative Mechanismen wie HER2/ERBB2 können relevant sein.":"Le wild type n’exclut que certaines voies de résistance ; des mécanismes alternatifs comme HER2/ERBB2 peuvent être pertinents.","Progress beweist, dass der RAS/BRAF-Test falsch sein muss.":"La progression prouve que le test RAS/BRAF doit être faux.","Damit war die ursprüngliche anti-EGFR-Strategie grundsätzlich falsch.":"Cela signifie que la stratégie anti-EGFR initiale était fondamentalement erronée.","Molekulare Diagnostik kann den Progress nicht mehr erklären.":"Le diagnostic moléculaire ne peut plus expliquer la progression.","Resistenzbiologie ist breiter als RAS/BRAF allein.":"La biologie de la résistance est plus large que RAS/BRAF seuls.","Wie sollte die ERBB2-Copy-number-Erhöhung weiterbehandelt werden?":"Comment poursuivre l’évaluation du gain de nombre de copies ERBB2 ?","HER2-positiven Status mit validiertem IHC/ISH-Algorithmus bestätigen und als Target-/möglichen anti-EGFR-Resistenzkontext integrieren.":"Confirmer le statut HER2 positif par un algorithme IHC/ISH validé et l’intégrer comme cible/possible contexte de résistance aux anti-EGFR.","Ignorieren, da RAS/BRAF Wildtyp sind.":"L’ignorer parce que RAS/BRAF sont wild type.","Ohne weitere Prüfung als sicher erworbene Resistenzmutation bezeichnen.":"Sans autre test, la qualifier de mutation de résistance certainement acquise.","Unverändert nach Mammakarzinom-Regeln interpretieren.":"L’interpréter telle quelle selon les règles du cancer du sein.","HER2 ist entitätsspezifisch zu bestätigen und zu interpretieren; Baseline fehlt für eine sichere Akquisitionsaussage.":"HER2 doit être confirmé et interprété de façon spécifique à l’entité ; l’absence de baseline empêche d’affirmer une acquisition certaine.","Darf die HER2-Amplifikation als 'erworben unter Cetuximab' bezeichnet werden?":"L’amplification HER2 peut-elle être décrite comme « acquise sous cetuximab » ?","Nicht sicher. Ohne Baseline-HER2 kann sie präexistent gewesen oder unter Therapie selektiert/angereichert worden sein.":"Pas avec certitude. Sans HER2 à baseline, elle peut avoir été préexistante ou sélectionnée/enrichie sous traitement.","Ja, weil sie erst beim Progress gemessen wurde.":"Oui, car elle n’a été mesurée qu’à la progression.","Ja, weil RAS/BRAF Wildtyp sind.":"Oui, parce que RAS/BRAF sont wild type.","Die zeitliche Einordnung ist für die Befundsprache irrelevant.":"La classification temporelle n’a aucune importance pour la formulation du compte rendu.","Nachweiszeitpunkt und biologischer Entstehungszeitpunkt sind nicht identisch.":"Le moment de détection et le moment biologique d’apparition ne sont pas identiques.","Erklären Sie zuerst, warum RAS/BRAF-Wildtyp im mCRC eine therapeutisch relevante 'negative' Information ist. Integrieren Sie danach die bestätigte HER2-Amplifikation in die Progressions- und Targetinterpretation, ohne Überinterpretation der Akquisition.":"Expliquer d’abord pourquoi RAS/BRAF wild type dans le mCRC est une information « négative » thérapeutiquement pertinente. Puis intégrer l’amplification HER2 confirmée dans l’interprétation de la progression et du ciblage sans surinterpréter son acquisition.","Linksseitigkeit und initialen RAS/BRAF-Wildtyp zusammen mit pMMR/MSS erfassen.":"Intégrer le côté gauche et le statut RAS/BRAF wild type initial avec pMMR/MSS.","RAS/BRAF-Wildtyp als Selektionsvoraussetzung für anti-EGFR-Antikörper erklären, nicht als 'kein Befund'.":"Expliquer RAS/BRAF wild type comme prérequis de sélection pour les anticorps anti-EGFR, et non comme « aucun résultat ».","Progress trotz Wildtyp als Hinweis auf alternative Resistenzmechanismen verstehen.":"Comprendre la progression malgré le wild type comme un indice de mécanismes de résistance alternatifs.","ERBB2-Copy-number-Befund durch HER2-IHC/ISH bestätigen.":"Confirmer le résultat de nombre de copies ERBB2 par IHC/ISH HER2.","HER2 als Target- und möglichen anti-EGFR-Resistenzkontext berichten.":"Rapporter HER2 comme cible et possible contexte de résistance aux anti-EGFR.","Ohne Baseline-HER2 nicht behaupten, die Amplifikation sei sicher erworben.":"Sans HER2 à baseline, ne pas affirmer que l’amplification est certainement acquise.","Validiertes breit angelegtes Progressionspanel mit zuverlässiger ERBB2-CNV-Erfassung plus orthogonale HER2-Bestätigung.":"Panel large validé de progression avec détection fiable des CNV ERBB2 plus confirmation HER2 orthogonale.","Bei nicht ausreichendem Gewebe ctDNA als ergänzender Resistenzansatz, sofern methodisch geeignet; negativer ctDNA-Befund würde Gewebe jedoch nicht automatisch ersetzen.":"Si le tissu est insuffisant, utiliser le ctDNA comme approche complémentaire de résistance lorsque méthodologiquement approprié ; un résultat ctDNA négatif ne remplacerait toutefois pas automatiquement le tissu.","'Alles negativ'":"« Tout négatif »","RAS/BRAF-Wildtyp ist therapeutisch relevante Selektionsinformation.":"RAS/BRAF wild type est une information de sélection thérapeutiquement pertinente.","Wildtyp = garantiert sensitiv":"Wild type = sensibilité garantie","Andere primäre oder sekundäre Resistenzmechanismen bleiben möglich.":"D’autres mécanismes de résistance primaire ou secondaire restent possibles.","HER2 = sicher erworben":"HER2 = certainement acquis","Ohne Baseline-HER2 kann die zeitliche Entstehung nicht bewiesen werden.":"Sans HER2 à baseline, le moment d’apparition ne peut pas être prouvé.","Nur MMR/MSI wiederholen":"Répéter seulement MMR/MSI","Der Status ist bereits bekannt und beantwortet die konkrete Progressionsfrage kaum.":"Ce statut est déjà connu et répond peu à la question spécifique de progression.","Kein RAS/RAF-Resistenztreiber – dafür HER2 amplifiziert":"Aucun driver de résistance RAS/RAF – mais HER2 amplifié","Das Progressionspanel bleibt KRAS/NRAS/BRAF-Wildtyp. Genau dieser 'negative' Befund war initial therapeutisch hilfreich, erklärt aber den aktuellen Progress nicht. Die HER2-Bestätigung zeigt IHC 3+ und ERBB2-Amplifikation. Damit erscheint ein alternativer Signal-/Resistenzweg und zugleich ein neuer Targetkontext. Weil Baseline-HER2 fehlt, bleibt offen, ob die Amplifikation schon vorher vorhanden oder unter Therapie selektiert war.":"Le panel de progression reste KRAS/NRAS/BRAF wild type. C’est précisément ce résultat « négatif » qui était thérapeutiquement utile au départ, mais il n’explique pas la progression actuelle. La confirmation HER2 montre IHC 3+ et amplification ERBB2. Cela révèle une voie alternative de signalisation/résistance et, simultanément, un nouveau contexte de ciblage. Comme le statut HER2 à baseline n’est pas disponible, on ne sait pas si l’amplification était déjà présente ou sélectionnée sous traitement.","Der Fall trennt drei Ebenen, die häufig vermischt werden: Selektionsmarker, Resistenzmechanismus und Target. 'Negativ' und 'positiv' sind therapeutisch kontextabhängige Begriffe.":"Le cas sépare trois niveaux souvent confondus : marqueur de sélection, mécanisme de résistance et cible. « Négatif » et « positif » sont des termes thérapeutiques dépendant du contexte.","Wildtyp richtig gelesen + HER2 integriert":"Wild type correctement interprété + HER2 intégré","KRAS/NRAS/BRAF WT; HER2 IHC 3+ / ERBB2 amplifiziert. Anti-EGFR war im initialen linksseitigen WT-Kontext plausibel; HER2 ist nun ein relevanter Target-/Resistenzkontext. Akquisition nicht beweisbar.":"KRAS/NRAS/BRAF WT ; HER2 IHC 3+ / ERBB2 amplifié. Les anti-EGFR étaient plausibles dans le contexte initial gauche WT ; HER2 constitue désormais un contexte pertinent de ciblage/résistance. L’acquisition ne peut être prouvée.","Alle Ebenen sauber getrennt und integriert.":"Tous les niveaux sont clairement séparés et intégrés.","Wildtyp als 'negativ' abgehakt":"Wild type classé comme « négatif »","RAS/BRAF WT wird nur als fehlender Befund erwähnt; HER2 wird zwar gefunden, aber die Selektionslogik bleibt unverstanden.":"RAS/BRAF WT n’est mentionné que comme absence de résultat ; HER2 est trouvé, mais la logique de sélection reste mal comprise.","Zentrales Lernziel verfehlt.":"Objectif pédagogique central manqué.","HER2 als sicher erworbene Resistenz bezeichnet":"HER2 qualifié de résistance certainement acquise","Kausalität/Akquisition wird ohne Baseline behauptet.":"La causalité/l’acquisition est affirmée sans baseline.","Überinterpretation der zeitlichen Evidenz.":"Surinterprétation des données temporelles.","HER2 bestätigt":"HER2 confirmé","HER2-gerichtete Therapieoptionen nach aktueller Zulassung/Leitlinie und Vorbehandlung im MTB prüfen.":"Examiner en RCP les options de traitement ciblant HER2 selon l’autorisation/les recommandations actuelles et les traitements antérieurs.","Der Progressionsbefund eröffnet eine neue therapeutische Achse.":"Le résultat de progression ouvre un nouvel axe thérapeutique.","HER2 nicht bestätigt":"HER2 non confirmé","Alternative Resistenzmechanismen im Progressionsprofil/ctDNA/Gewebe prüfen.":"Évaluer d’autres mécanismes de résistance dans le profil de progression/ctDNA/tissu.","RAS/BRAF-Wildtyp allein erklärt den Progress weiterhin nicht.":"RAS/BRAF wild type seul n’explique toujours pas la progression.","Beim mCRC kann ein negativer Mutationsbefund therapeutisch positiv sein.":"Dans le mCRC, un résultat mutationnel négatif peut être thérapeutiquement positif.","RAS/BRAF-Wildtyp ist Voraussetzung/Selektionsinformation für anti-EGFR, aber keine Garantie für Wirkung.":"RAS/BRAF wild type est un prérequis/une information de sélection pour les anti-EGFR, mais pas une garantie d’efficacité.","HER2-Amplifikation kann einen alternativen Target-/Resistenzkontext darstellen.":"L’amplification HER2 peut représenter un contexte alternatif de ciblage/résistance.","Ohne Baseline darf 'erworben' nicht behauptet werden.":"Sans baseline, il ne faut pas affirmer « acquis ».","Linksseitiges mCRC mit initial RAS/BRAF-WT/pMMR/MSS: der Wildtypstatus ist eine positive Selektionsinformation für anti-EGFR-Antikörper. Beim Progress bleibt RAS/BRAF WT, aber ERBB2 ist amplifiziert und HER2 bestätigt. HER2 als alternativen Target-/Resistenzkontext berichten; mangels Baseline nicht als sicher erworben bezeichnen.":"mCRC gauche avec RAS/BRAF-WT/pMMR/MSS initial : le statut wild type est une information positive de sélection pour les anticorps anti-EGFR. À la progression, RAS/BRAF reste WT, mais ERBB2 est amplifié et HER2 confirmé. Rapporter HER2 comme contexte alternatif de ciblage/résistance ; sans baseline, ne pas le qualifier de certainement acquis.","negativ=positiv-Konzept explizit verstanden":"concept « négatif = positif » explicitement compris","WT nicht als Erfolgsgarantie":"WT non considéré comme garantie de succès","HER2 bestätigt und integriert":"HER2 confirmé et intégré","Akquisitionssprache begrenzt":"Formulation sur l’acquisition correctement limitée","Warum sind Wildtypbefunde in der Onkologie oft therapeutisch hochinformativ?":"Pourquoi les résultats wild type sont-ils souvent très informatifs sur le plan thérapeutique en oncologie ?","Welche weiteren anti-EGFR-Resistenzmechanismen gibt es neben RAS/BRAF?":"Quels autres mécanismes de résistance aux anti-EGFR existent en dehors de RAS/BRAF ?","Wie verändert ctDNA die Rechallenge-/Resistenzdiagnostik?":"Comment le ctDNA modifie-t-il le diagnostic de rechallenge/résistance ?","RAS/BRAF WT bleibt, HER2 wird positiv":"RAS/BRAF reste WT, HER2 devient positif","negativ kann therapeutisch positiv sein":"négatif peut être thérapeutiquement positif","WT-Selektion → anti-EGFR → Progress → HER2-Amplifikation":"Sélection WT → anti-EGFR → progression → amplification HER2","Mammakarzinom: BRCA/PIK3CA/ERBB2-Kontext → Klassische Marker vs. Panel-Zusatznutzen":"Cancer du sein : contexte BRCA/PIK3CA/ERBB2 → marqueurs classiques versus valeur ajoutée du panel","Mammakarzinom: BRCA/PIK3CA/ERBB2-K…":"Cancer du sein : contexte BRCA/PIK3CA/ERBB2…","Gynäko-Onkologie / Molekulares Tumorboard":"Oncologie gynécologique / RCP moléculaire","56-jährige Patientin mit sechs Jahre zuvor behandeltem invasivem Mammakarzinom; jetzt neu aufgetretene Leber- und Knochenmetastasen nach Progress unter endokriner Therapie plus CDK4/6-Inhibition.":"Patiente de 56 ans avec cancer du sein invasif traité six ans auparavant ; nouvelles métastases hépatiques et osseuses après progression sous hormonothérapie plus inhibition CDK4/6.","Welche klassischen prädiktiven Marker müssen an der Metastase erneut geklärt werden, und welchen zusätzlichen therapeutischen Nutzen liefern PIK3CA- sowie BRCA/HRR-Analysen?":"Quels marqueurs prédictifs classiques doivent être réévalués dans la métastase, et quelle valeur thérapeutique supplémentaire apportent les analyses PIK3CA et BRCA/HRR ?","Therapiewechsel soll im nächsten MTB festgelegt werden.":"Le changement de traitement doit être défini lors de la prochaine RCP moléculaire.","Primärtumor vor 6 Jahren":"Tumeur primitive il y a 6 ans","ER 95 %, PgR 70 %, HER2 IHC 0; adjuvante Chemotherapie und anschließende endokrine Therapie.":"ER 95 %, PgR 70 %, HER2 IHC 0 ; chimiothérapie adjuvante puis hormonothérapie.","Metastasierte Situation":"Situation métastatique","Nach initialer Krankheitskontrolle unter Aromatasehemmer + CDK4/6-Inhibitor nun hepatischer Progress.":"Après contrôle initial de la maladie sous inhibiteur de l’aromatase + inhibiteur CDK4/6, progression hépatique actuelle.","Familienanamnese":"Antécédents familiaux","Mutter mit Ovarialkarzinom im Alter von 63 Jahren; bisher keine dokumentierte humangenetische Abklärung.":"Mère atteinte d’un cancer de l’ovaire à 63 ans ; aucune consultation/test génétique documenté à ce jour.","Ein breites Panel wird als Ersatz für die erneute Bestimmung der klassischen Tumorbiologie verstanden – oder ein Tumor-BRCA-Befund wird direkt als gesicherte Keimbahnmutation behandelt.":"Un panel large est considéré comme substitut à la réévaluation de la biologie tumorale classique – ou un résultat BRCA tumoral est directement traité comme une mutation germinale prouvée.","Metastasenbiopsie":"Biopsie métastatique","Adenokarzinom, morphologisch und immunhistochemisch vereinbar mit Mammakarzinommetastase.":"Adénocarcinome morphologiquement et immunohistochimiquement compatible avec une métastase de cancer du sein.","Rezeptorstatus Metastase":"Statut des récepteurs de la métastase","ER 80 %, PgR 5 %. HER2-IHC 2+ und damit für die klassische HER2-Statusbestimmung zunächst äquivok.":"ER 80 %, PgR 5 %. HER2 IHC 2+ et donc initialement équivoque pour la détermination classique du statut HER2.","Offene molekulare Fragen":"Questions moléculaires ouvertes","PIK3CA als endokrin-targetierbarer Kontext; BRCA1/2/HRR wegen PARP- und hereditärer Fragestellung.":"PIK3CA comme contexte ciblable en endocrinologie ; BRCA1/2/HRR en raison des questions PARP et héréditaires.","Kernproblem":"Problème central","Klassische Marker und Molekularpanel beantworten unterschiedliche Ebenen derselben Therapieentscheidung.":"Les marqueurs classiques et les panels moléculaires répondent à différents niveaux d’une même décision thérapeutique.","FFPE-Leberbiopsie, Block L3.":"Biopsie hépatique FFPE, bloc L3.","ca. 45 %, nach Makrodissektion gut geeignet.":"env. 45 %, bien adapté après macrodissection.","11 ungefärbte Schnitte; genug für gezielte IHC/ISH und fokussierte Molekulardiagnostik.":"11 lames non colorées ; suffisantes pour IHC/ISH ciblée et diagnostic moléculaire focalisé.","DNA ausreichend; HER2-IHC technisch gut beurteilbar.":"ADN suffisant ; IHC HER2 techniquement bien interprétable.","Ein großes Pan-Panel verbraucht mehr Material, ersetzt aber weder die validierte HER2-IHC/ISH-Ebene noch die getrennte Keimbahnabklärung.":"Un grand pan-panel consomme davantage de matériel mais ne remplace ni le niveau validé HER2 IHC/ISH ni l’évaluation germinale séparée.","HER2-Status der Metastase klären":"Clarifier le statut HER2 de la métastase","PIK3CA-Kontext":"Contexte PIK3CA","Tumor-BRCA/HRR-Kontext":"Contexte tumoral BRCA/HRR","HER2-Status":"Statut HER2","HER2-IHC 2+; ERBB2-ISH/FISH ohne Amplifikation. Der Tumor ist damit nicht HER2-amplifiziert; die äquivoke IHC allein darf nicht als HER2-positiv überinterpretiert werden.":"HER2 IHC 2+ ; ERBB2 ISH/FISH sans amplification. La tumeur n’est donc pas amplifiée HER2 ; une IHC équivoque seule ne doit pas être surinterprétée comme HER2 positive.","PIK3CA":"PIK3CA","PIK3CA p.H1047R, pathogen/aktivierend. Im HR-positiven, HER2-negativen metastasierten Kontext therapeutisch relevant abhängig von Vorbehandlung, Therapielinie und aktueller Zulassung/Leitlinie.":"PIK3CA p.H1047R, pathogène/activatrice. Thérapeutiquement pertinente dans la maladie métastatique HR positive, HER2 négative selon les traitements antérieurs, la ligne thérapeutique et l’autorisation/les recommandations actuelles.","Tumor-BRCA/HRR":"BRCA/HRR tumoral","BRCA2-Frameshift-Variante mit Loss-of-function-Konsequenz, VAF 47 %. Der Tumorbefund kann eine therapeutisch und hereditär relevante Spur sein, beweist aber für sich keine Keimbahnmutation.":"Variant frameshift BRCA2 avec conséquence loss-of-function, VAF 47 %. Le résultat tumoral peut être un indice pertinent sur les plans thérapeutique et héréditaire, mais ne prouve pas à lui seul une mutation germinale.","Humangenetische Weiterleitung":"Orientation en oncogénétique","Humangenetische Beratung und Keimbahnabklärung werden empfohlen. Die hereditäre Einordnung erfolgt aus einer geeigneten Normalprobe und getrennt vom Tumor-only-Befund.":"Une consultation d’oncogénétique et un test germinal sont recommandés. La classification héréditaire est réalisée sur un échantillon normal approprié, séparément du résultat tumor-only.","Rezeptorbiologie":"Biologie des récepteurs","ER 80 %, PgR 5 %; HER2-IHC 2+ an der Metastase.":"ER 80 %, PgR 5 % ; HER2 IHC 2+ dans la métastase.","Metastasenbiopsie ausreichend für fokussierte IHC/ISH und Molekulardiagnostik.":"Biopsie métastatique suffisante pour IHC/ISH ciblée et diagnostic moléculaire.","HR-positives metastasiertes Mammakarzinom mit HER2-IHC 2+, aber ohne ERBB2-Amplifikation. Zusätzlich liegt eine aktivierende PIK3CA-Mutation vor. Eine pathogene BRCA2-Loss-of-function-Variante wurde im Tumor gefunden; ihre Keimbahnherkunft ist aus der Tumoranalyse nicht ableitbar und muss separat humangenetisch geklärt werden. Klassische Rezeptor-/HER2-Diagnostik und molekulare Zusatzdiagnostik ergänzen sich und dürfen nicht gegeneinander ersetzt werden.":"Cancer du sein métastatique HR positif avec HER2 IHC 2+, mais sans amplification ERBB2. Une mutation activatrice PIK3CA est également présente. Un variant pathogène loss-of-function BRCA2 a été trouvé dans la tumeur ; son origine germinale ne peut pas être déduite de l’analyse tumorale et doit être clarifiée séparément par consultation/test génétique. Le diagnostic classique des récepteurs/HER2 et les analyses moléculaires complémentaires se complètent et ne doivent pas se substituer l’un à l’autre.","Teilbefund: Die molekularen Zusatzmarker sind nur im aktuellen ER/PgR/HER2-Kontext sinnvoll interpretierbar. Ein HER2-IHC-2+-Befund benötigt die validierte ISH/FISH-Klärung; ein Tumor-BRCA2-Befund ist nicht automatisch ein Keimbahnbefund.":"Résultat partiel : les marqueurs moléculaires supplémentaires ne peuvent être interprétés correctement que dans le contexte actuel ER/PgR/HER2. Un résultat HER2 IHC 2+ nécessite une clarification validée par ISH/FISH ; un résultat BRCA2 tumoral n’est pas automatiquement germinal.","Aktuellen ER/PgR/HER2-Kontext der Metastase als Grundlage benennen":"Présenter le contexte actuel ER/PgR/HER2 de la métastase comme fondement","HER2 IHC 2+ durch ISH/FISH klären und nicht vorschnell als HER2-positiv bezeichnen":"Clarifier HER2 IHC 2+ par ISH/FISH et ne pas le qualifier prématurément de HER2 positif","PIK3CA als zusätzlichen, therapielinienabhängigen Targetkontext integrieren":"Intégrer PIK3CA comme contexte de ciblage supplémentaire dépendant de la ligne thérapeutique","Tumor-BRCA2 therapeutisch/hereditär relevant einordnen, Keimbahn aber separat klären":"Classer BRCA2 tumoral comme pertinent sur les plans thérapeutique/héréditaire, mais évaluer le germinal séparément","Paneldiagnostik nicht als Ersatz für klassische Biomarker oder Humangenetik darstellen":"Ne pas présenter le panel comme substitut aux biomarqueurs classiques ou à l’oncogénétique","Optimale Lösung: Metastasenbiologie zuerst korrekt mit ER/PgR/HER2 charakterisieren; HER2 2+ durch ISH als nicht amplifiziert klären; PIK3CA als zusätzliche therapeutische Information nutzen; pathogene Tumor-BRCA2-Variante als wichtige Spur berichten, aber Keimbahnstatus separat abklären.":"Solution optimale : caractériser d’abord correctement la biologie métastatique avec ER/PgR/HER2 ; clarifier HER2 2+ par ISH comme non amplifié ; utiliser PIK3CA comme information thérapeutique supplémentaire ; rapporter le variant BRCA2 pathogène tumoral comme un indice important, mais évaluer le statut germinal séparément.","Mammakarzinom":"Cancer du sein","HR+":"HR+","BRCA2":"BRCA2","Keimbahn":"Germinal","PARP":"PARP","Klassische Marker zuerst, Panel danach: HER2 2+, PIK3CA und der Tumor-BRCA2-Twist":"Marqueurs classiques d’abord, panel ensuite : HER2 2+, PIK3CA et le twist BRCA2 tumoral","Molekularpathologie / Gynäko-Onkologie / MTB":"Pathologie moléculaire / Oncologie gynécologique / RCP moléculaire","Bei metastasiertem Mammakarzinom die aktuelle Tumorbiologie der Metastase einschließlich ER/PgR/HER2 als Grundlage der Systemtherapie verstehen.":"Dans le cancer du sein métastatique, comprendre la biologie actuelle de la métastase, notamment ER/PgR/HER2, comme fondement du traitement systémique.","HER2-IHC 2+ nicht als HER2-positiv überinterpretieren, sondern mit validierter ISH/FISH klären.":"Ne pas surinterpréter HER2 IHC 2+ comme HER2 positif ; clarifier par ISH/FISH validée.","PIK3CA als zusätzliche molekulare Therapieinformation im HR-positiven/HER2-negativen Kontext einordnen.":"Intégrer PIK3CA comme information moléculaire thérapeutique supplémentaire dans le contexte RH positif/HER2 négatif.","Eine pathogene BRCA2-Variante aus Tumor-only-NGS von einer gesicherten Keimbahnmutation trennen.":"Distinguer un variant pathogène de BRCA2 détecté par NGS tumor-only d’une mutation germinale confirmée.","Verstehen, dass Multigen-NGS klassische Biomarker ergänzt, aber nicht ersetzt.":"Comprendre que le NGS multigénique complète les biomarqueurs classiques sans les remplacer.","Die Lebermetastase ist ER-positiv und HER2-IHC 2+. Parallel meldet das Panel eine aktivierende PIK3CA-Mutation und eine pathogene BRCA2-Frameshift-Variante. Im Tumorboard fallen sofort drei vermeintlich einfache Schlussfolgerungen: 'HER2-positiv', 'PIK3CA-targetierbar' und 'BRCA erblich'. Genau dieser Fall zeigt, warum alle drei Aussagen erst im richtigen diagnostischen Kontext belastbar werden.":"La métastase hépatique est ER positive et HER2 IHC 2+. En parallèle, le panel rapporte une mutation activatrice de PIK3CA et un variant frameshift pathogène de BRCA2. Trois conclusions apparemment simples émergent immédiatement en RCP moléculaire : « HER2 positif », « PIK3CA ciblable » et « BRCA héréditaire ». Ce cas montre précisément pourquoi ces trois affirmations ne deviennent robustes que dans le bon contexte diagnostique.","56-jährige Patientin mit HR-positivem Mammakarzinom und hepatischem Progress nach endokriner Therapie plus CDK4/6-Inhibition. Die aktuelle Metastasenbiopsie ist ER 80 %, PgR 5 % und HER2-IHC 2+. Gesucht wird eine integrierte Therapiebiologie aus klassischer HER2-Diagnostik, PIK3CA und BRCA/HRR, ohne die Grenzen von Tumor-only-NGS zu verwischen.":"Patiente de 56 ans présentant un cancer du sein RH positif avec progression hépatique après hormonothérapie plus inhibition de CDK4/6. La biopsie métastatique actuelle est ER 80 %, PgR 5 % et HER2 IHC 2+. Il faut intégrer la biologie thérapeutique à partir du diagnostic HER2 classique, de PIK3CA et de BRCA/HRR, sans brouiller les limites du NGS tumor-only.","Metastasenbiologie":"Biologie métastatique","ER 80 %, PgR 5 %, HER2-IHC 2+.":"ER 80 %, PgR 5 %, HER2 IHC 2+.","Die aktuelle Metastase kann sich biologisch vom Primärtumor unterscheiden; klassische Marker bleiben Grundlage.":"La métastase actuelle peut différer biologiquement de la tumeur primitive ; les marqueurs classiques restent fondamentaux.","Molekulare Zusatzebene":"Niveau moléculaire supplémentaire","PIK3CA und BRCA/HRR sollen gezielt ergänzt werden.":"PIK3CA et BRCA/HRR doivent être ajoutés de manière ciblée.","Zusatznutzen entsteht erst im bekannten HR/HER2-Kontext.":"La valeur ajoutée n’apparaît que dans le contexte RH/HER2 connu.","Familienrelevanz":"Pertinence familiale","Mutter mit Ovarialkarzinom; keine bisherige Humangenetik.":"Mère atteinte d’un cancer de l’ovaire ; aucune évaluation génétique antérieure.","Tumor-only kann einen Verdacht erzeugen, aber Keimbahn nicht beweisen.":"L’analyse tumor-only peut susciter une suspicion, mais ne peut pas prouver une origine germinale.","Mammakarzinommetastase, ER 80 %, PgR 5 %, HER2-IHC 2+.":"Métastase de cancer du sein, ER 80 %, PgR 5 %, HER2 IHC 2+.","Vor sechs Jahren ER/PgR stark positiv, HER2-IHC 0.":"Il y a six ans, ER/PgR fortement positifs, HER2 IHC 0.","Leberbiopsie mit ca. 45 % Tumor; fokussierte IHC/ISH und NGS sind möglich.":"Biopsie hépatique avec environ 45 % de tumeur ; IHC/ISH ciblées et NGS sont réalisables.","Elf Schnitte erlauben eine fokussierte Diagnostik, aber unnötige Breitdiagnostik kostet Material.":"Onze coupes permettent un diagnostic ciblé, mais des explorations larges inutiles consomment du matériel.","HER2-IHC 2+ benötigt eine validierte Amplifikationsabklärung; NGS ersetzt diesen diagnostischen Algorithmus nicht automatisch.":"HER2 IHC 2+ nécessite une recherche validée d’amplification ; le NGS ne remplace pas automatiquement cet algorithme diagnostique.","Eine Normalprobe für die Keimbahnabklärung ist in der Tumorpathologie nicht vorhanden.":"Aucun échantillon normal n’est disponible en pathologie tumorale pour l’évaluation germinale.","Was ist die wichtigste Grundlage, bevor PIK3CA/BRCA therapeutisch interpretiert werden?":"Quelle est la base la plus importante avant d’interpréter PIK3CA/BRCA sur le plan thérapeutique ?","Die aktuelle ER/PgR/HER2-Biologie der Metastase muss belastbar feststehen; das Panel ergänzt diese Ebene.":"La biologie ER/PgR/HER2 actuelle de la métastase doit être établie de manière fiable ; le panel complète ce niveau.","Ein ausreichend breites NGS-Panel ersetzt ER/PgR/HER2 vollständig.":"Un panel NGS suffisamment large remplace totalement ER/PgR/HER2.","Der Rezeptorstatus des Primärtumors vor sechs Jahren reicht aus.":"Le statut des récepteurs de la tumeur primitive d’il y a six ans suffit.","BRCA2 entscheidet unabhängig von HR/HER2 über die gesamte Therapie.":"BRCA2 détermine l’ensemble du traitement indépendamment de RH/HER2.","Beim metastasierten Mammakarzinom bleibt die aktuelle Tumorbiologie eine zentrale prädiktive Grundlage.":"Dans le cancer du sein métastatique, la biologie tumorale actuelle reste une base prédictive centrale.","Die Metastase ist HER2-IHC 2+. Was bedeutet das?":"La métastase est HER2 IHC 2+. Qu’est-ce que cela signifie ?","Äquivoker Befund: ERBB2-Amplifikation mit validierter ISH/FISH klären; IHC 2+ allein ist nicht gleich HER2-amplifiziert.":"Résultat équivoque : clarifier l’amplification d’ERBB2 par ISH/FISH validée ; IHC 2+ seul n’équivaut pas à une amplification de HER2.","HER2-positiv, weitere Klärung unnötig.":"HER2 positif, aucune clarification supplémentaire n’est nécessaire.","Sicher HER2-negativ, ISH ist nie erforderlich.":"Certainement HER2 négatif ; l’ISH n’est jamais nécessaire.","Nur die BRCA-Analyse entscheidet, HER2 ist irrelevant.":"Seule l’analyse de BRCA compte ; HER2 est sans pertinence.","IHC 2+ benötigt die etablierte Amplifikationsabklärung.":"IHC 2+ nécessite le bilan d’amplification établi.","Tumor-NGS zeigt eine pathogene BRCA2-Frameshift-Variante mit VAF 47 %. Was darf daraus geschlossen werden?":"Le NGS tumoral montre un variant frameshift pathogène de BRCA2 avec une VAF de 47 %. Que peut-on en conclure ?","Der Befund ist therapeutisch/hereditär relevant, aber Tumor-only beweist keine Keimbahnmutation; Humangenetik/Normalprobe separat klären.":"Le résultat est pertinent sur les plans thérapeutique et héréditaire, mais le tumor-only ne prouve pas une mutation germinale ; il faut la clarifier séparément par conseil génétique/échantillon normal.","VAF nahe 50 % beweist eine Keimbahnmutation.":"Une VAF proche de 50 % prouve une mutation germinale.","Da die Probe Tumorgewebe ist, ist die Variante sicher rein somatisch.":"Puisque l’échantillon est tumoral, le variant est forcément purement somatique.","Eine Frameshift-Variante ist automatisch eine VUS.":"Un variant frameshift est automatiquement un VUS.","Tumor-VAF und selbst LOH trennen somatisch und Keimbahn nicht zuverlässig.":"La VAF tumorale et même la LOH ne distinguent pas de façon fiable une origine somatique d’une origine germinale.","Wie ist der Zusatznutzen des Panels hier am besten beschrieben?":"Comment décrire au mieux la valeur ajoutée du panel ici ?","PIK3CA/BRCA liefern zusätzliche therapie- und familienrelevante Information, ersetzen aber weder HER2-IHC/ISH noch die Keimbahnabklärung.":"PIK3CA/BRCA apportent des informations supplémentaires pertinentes pour le traitement et la famille, mais ne remplacent ni HER2 IHC/ISH ni l’évaluation germinale.","Das Panel macht klassische Biomarker und Humangenetik überflüssig.":"Le panel rend inutiles les biomarqueurs classiques et le conseil génétique.","Molekulardiagnostik hat bei HR-positivem Mammakarzinom keinen Zusatznutzen.":"Le diagnostic moléculaire n’apporte aucune valeur ajoutée dans le cancer du sein RH positif.","Nur BRCA2 ist relevant; PIK3CA und HER2 können ignoriert werden.":"Seul BRCA2 est pertinent ; PIK3CA et HER2 peuvent être ignorés.","Die Stärke liegt in der Integration komplementärer diagnostischer Ebenen.":"La force réside dans l’intégration de niveaux diagnostiques complémentaires.","Formulieren Sie eine integrierte MTB-Aussage, die den aktuellen HR/HER2-Status der Metastase, PIK3CA und die Tumor-BRCA2-Variante zusammenführt und klar trennt, welche Information unmittelbar tumorbezogen ist und welche eine separate Keimbahnabklärung erfordert.":"Formulez une conclusion intégrée de RCP moléculaire réunissant le statut RH/HER2 actuel de la métastase, PIK3CA et le variant tumoral BRCA2, tout en distinguant clairement l’information directement tumorale de celle nécessitant une évaluation germinale séparée.","Aktuelle Metastasenbiologie mit ER/PgR/HER2 als Grundlage verwenden.":"Utiliser comme base la biologie métastatique actuelle avec ER/PgR/HER2.","HER2-IHC 2+ durch ISH/FISH klären: keine ERBB2-Amplifikation.":"Clarifier HER2 IHC 2+ par ISH/FISH : absence d’amplification d’ERBB2.","PIK3CA p.H1047R als zusätzlichen therapielinienabhängigen Targetkontext berichten.":"Rapporter PIK3CA p.H1047R comme contexte de ciblage supplémentaire dépendant de la ligne thérapeutique.","Tumor-BRCA2-Loss-of-function als relevante molekulare Spur einordnen.":"Interpréter la perte de fonction tumorale de BRCA2 comme un indice moléculaire pertinent.","Tumor-BRCA2 nicht als gesicherte Keimbahnmutation bezeichnen; humangenetische Beratung/Normalprobe empfehlen.":"Ne pas qualifier BRCA2 tumoral de mutation germinale confirmée ; recommander un conseil génétique/échantillon normal.","Therapieoptionen an aktuelle Zulassung, Vorbehandlung und Gesamtbiologie binden.":"Lier les options thérapeutiques à l’autorisation actuelle, aux traitements antérieurs et à la biologie globale.","Validiertes Multigenpanel zur kombinierten Erfassung von PIK3CA und BRCA/HRR, sofern HER2 weiterhin separat nach validiertem IHC/ISH-Algorithmus beurteilt wird.":"Panel multigénique validé pour la détection combinée de PIK3CA et BRCA/HRR, à condition que HER2 continue d’être évalué séparément selon un algorithme IHC/ISH validé.","Gezielte PIK3CA-Analyse plus Tumor-BRCA/HRR-Panel, um Material und TAT zu schonen.":"Analyse ciblée de PIK3CA plus panel tumoral BRCA/HRR afin d’économiser le matériel et le TAT.","HER2 2+ = HER2-positiv":"HER2 2+ = HER2 positif","IHC 2+ ist äquivok und benötigt die Amplifikationsabklärung.":"IHC 2+ est équivoque et nécessite une évaluation de l’amplification.","Tumor-BRCA2 = Keimbahn-BRCA2":"BRCA2 tumoral = BRCA2 germinal","Tumor-only-NGS kann die Herkunft nicht sicher bestimmen.":"Le NGS tumor-only ne peut pas déterminer de façon fiable l’origine.","Pan-Panel ersetzt alles":"Le pan-panel remplace tout","Klassische Protein-/Amplifikationsmarker und Humangenetik beantworten andere diagnostische Ebenen.":"Les marqueurs classiques de protéine/amplification et la génétique germinale répondent à des niveaux diagnostiques différents.","Primärtumorstatus reicht":"Le statut de la tumeur primitive suffit","Bei metastasierter Erkrankung kann eine Rebiopsie die aktuelle Tumorbiologie neu bewerten.":"En situation métastatique, une rebiopsie peut réévaluer la biologie tumorale actuelle.","Zwei 'positive' Befunde – aber keiner bedeutet das, was der erste Blick suggeriert":"Deux résultats « positifs » – mais aucun ne signifie ce que suggère le premier regard","HER2-IHC 2+ wird durch ISH als nicht amplifiziert geklärt. Gleichzeitig zeigt Tumor-NGS BRCA2 Loss-of-function bei VAF 47 %. Das klingt nach HER2-positiv plus erblichem BRCA-Syndrom – tatsächlich ist ersteres äquivok/nicht amplifiziert und letzteres zunächst ein Tumorbefund mit notwendiger separater Keimbahnklärung. Die klar tumorbezogene Zusatzinformation ist eine aktivierende PIK3CA-p.H1047R-Mutation.":"HER2 IHC 2+ est clarifié par ISH comme non amplifié. En parallèle, le NGS tumoral montre une perte de fonction de BRCA2 à une VAF de 47 %. Cela évoque au premier abord une tumeur HER2 positive associée à un syndrome BRCA héréditaire ; en réalité, le premier résultat est équivoque/non amplifié et le second est d’abord un résultat tumoral nécessitant une clarification germinale séparée. L’information additionnelle clairement tumorale est une mutation activatrice PIK3CA p.H1047R.","Der Fall zwingt zur Trennung von Proteinexpression, Genamplifikation, somatischer Tumorgenetik und Keimbahnstatus – vier Ebenen, die therapeutisch miteinander interagieren, aber diagnostisch nicht austauschbar sind.":"Le cas impose de séparer expression protéique, amplification génique, génétique somatique tumorale et statut germinal – quatre niveaux qui interagissent sur le plan thérapeutique sans être interchangeables sur le plan diagnostique.","Klassik und Molekularprofil integriert":"Marqueurs classiques et profil moléculaire intégrés","ER 80 %, PgR 5 %, HER2-IHC 2+/ISH nicht amplifiziert; PIK3CA p.H1047R; pathogene BRCA2-Frameshift-Variante im Tumor. PIK3CA im aktuellen HR+/HER2-negativen Therapiekontext berücksichtigen; BRCA2 als relevante Tumorspur mit separater Keimbahnabklärung berichten.":"ER 80 %, PgR 5 %, HER2 IHC 2+/ISH non amplifié ; PIK3CA p.H1047R ; variant frameshift pathogène de BRCA2 dans la tumeur. Prendre en compte PIK3CA dans le contexte thérapeutique actuel RH+/HER2 négatif ; rapporter BRCA2 comme résultat tumoral pertinent avec évaluation germinale séparée.","Alle diagnostischen Ebenen korrekt getrennt und integriert.":"Tous les niveaux diagnostiques sont correctement séparés et intégrés.","Panel gut, klassische Ebene offen":"Panel correct, niveau classique non résolu","PIK3CA und BRCA2 werden gefunden, HER2-IHC 2+ aber nicht durch ISH geklärt.":"PIK3CA et BRCA2 sont détectés, mais HER2 IHC 2+ n’est pas clarifié par ISH.","Therapiebiologie bleibt unvollständig.":"La biologie thérapeutique reste incomplète.","HER2 und Keimbahn überinterpretiert":"HER2 et statut germinal surinterprétés","HER2-IHC 2+ wird als HER2-positiv und Tumor-BRCA2 als sicher keimbahnpathogen bezeichnet.":"HER2 IHC 2+ est qualifié de HER2 positif et BRCA2 tumoral de certainement pathogène germinal.","Zwei zentrale diagnostische Grenzüberschreitungen.":"Deux franchissements majeurs de limites diagnostiques.","Tumor-BRCA2 pathologisch":"BRCA2 tumoral pathologique","Humangenetische Beratung und Keimbahntestung aus geeigneter Normalprobe veranlassen.":"Organiser un conseil génétique et une analyse germinale à partir d’un échantillon normal approprié.","Therapie- und Familienrelevanz werden getrennt, aber koordiniert weiterverfolgt.":"Les implications thérapeutiques et familiales sont poursuivies séparément mais de manière coordonnée.","HER2-ISH nicht amplifiziert":"HER2 ISH non amplifié","Therapieplanung im HR+/HER2-negativen Kontext fortsetzen und PIK3CA/weitere Linienmarker berücksichtigen.":"Poursuivre la planification thérapeutique dans le contexte RH+/HER2 négatif et prendre en compte PIK3CA/autres marqueurs selon la ligne.","HER2-IHC 2+ wird nicht als Amplifikationspositivität fehlgedeutet.":"HER2 IHC 2+ n’est pas interprété à tort comme une amplification positive.","Beim metastasierten Mammakarzinom bleibt die aktuelle ER/PgR/HER2-Biologie zentral.":"Dans le cancer du sein métastatique, la biologie actuelle ER/PgR/HER2 reste centrale.","HER2-IHC 2+ ist ein Klärungsbefund, kein automatisches positives Endergebnis.":"HER2 IHC 2+ est un résultat à clarifier, pas un résultat final automatiquement positif.","PIK3CA erweitert die therapeutische Information im passenden HR+/HER2-negativen Kontext.":"PIK3CA enrichit l’information thérapeutique dans le contexte approprié RH+/HER2 négatif.","Tumor-only BRCA kann klinisch hochrelevant sein, beweist aber keinen Keimbahnstatus.":"Un résultat BRCA tumor-only peut être très pertinent cliniquement sans prouver le statut germinal.","Multigen-NGS ergänzt klassische Pathologiemarker; es ersetzt sie nicht.":"Le NGS multigénique complète les marqueurs classiques d’anatomopathologie ; il ne les remplace pas.","Aktuelle Metastasenbiologie zuerst: HR-positiv, HER2-IHC 2+, aber ISH nicht amplifiziert. PIK3CA p.H1047R ist als zusätzlicher therapeutischer Marker relevant. Die pathogene BRCA2-Frameshift-Variante stammt aus Tumor-only-NGS; sie darf nicht als Keimbahnmutation bezeichnet werden und löst eine separate humangenetische Abklärung aus.":"D’abord la biologie métastatique actuelle : RH positif, HER2 IHC 2+, mais ISH non amplifié. PIK3CA p.H1047R est pertinent comme marqueur thérapeutique supplémentaire. Le variant frameshift pathogène de BRCA2 provient d’un NGS tumor-only ; il ne doit pas être qualifié de mutation germinale et justifie une évaluation génétique séparée.","HER2 2+ korrekt geklärt":"HER2 2+ correctement clarifié","PIK3CA im passenden Kontext integriert":"PIK3CA intégré dans le contexte approprié","Tumor vs. Keimbahn getrennt":"Tumoral et germinal distingués","Panel nicht als Ersatz klassischer Marker":"Le panel n’est pas considéré comme un substitut aux marqueurs classiques","Warum sollte die Metastase erneut auf ER/PgR/HER2 untersucht werden?":"Pourquoi faut-il réévaluer ER/PgR/HER2 sur la métastase ?","Welche Aussage kann eine Tumor-VAF von etwa 50 % zur Keimbahnherkunft leisten – und welche nicht?":"Que peut indiquer une VAF tumorale d’environ 50 % sur une origine germinale – et que ne peut-elle pas indiquer ?","Wann ist ein breites Panel gegenüber fokussierter Diagnostik wirklich sinnvoll?":"Quand un panel large est-il réellement utile par rapport à un diagnostic ciblé ?","HER2 2+ nicht amplifiziert + Tumor-BRCA2 ist nicht automatisch Keimbahn":"HER2 2+ non amplifié + BRCA2 tumoral ne signifie pas automatiquement germinal","Klassische Marker und Molekularprofil sind komplementär":"Les marqueurs classiques et le profil moléculaire sont complémentaires","Metastasenbiologie → HER2-Klärung → PIK3CA/BRCA → Keimbahn separat":"Biologie métastatique → clarification HER2 → PIK3CA/BRCA → germinal séparément","Metastasiertes Prostatakarzinom: HRR-Gene/MMR → PARP/IO/Studie und Keimbahnfrage":"Cancer de la prostate métastatique : gènes HRR/MMR → PARP/IO/essai et question germinale","Metastasiertes Prostatakarzinom: H…":"Cancer de la prostate métastatique : H…","Uro-Onkologie / Molekulares Tumorboard":"Uro-oncologie / RCP moléculaire","69-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom und radiologischem Progress nach Androgendeprivation plus neuem hormonellen Wirkstoff.":"Patient de 69 ans atteint d’un cancer de la prostate métastatique résistant à la castration, avec progression radiologique après privation androgénique plus un nouvel agent hormonal.","Gibt es einen HRR-/BRCA-Biomarker für eine PARP-Strategie? Besteht ein MMR/MSI-basierter Immuntherapiekontext? Muss eine Keimbahnabklärung folgen?":"Existe-t-il un biomarqueur HRR/BRCA pour une stratégie PARP ? Existe-t-il un contexte d’immunothérapie basé sur MMR/MSI ? Une évaluation germinale est-elle nécessaire ?","Therapieentscheidung in der kommenden Woche.":"Décision thérapeutique la semaine prochaine.","Verlauf":"Évolution","Initial lokal fortgeschrittenes Adenokarzinom; später ossäre und nodale Metastasierung, jetzt mCRPC.":"Initialement adénocarcinome localement avancé ; puis métastases osseuses et ganglionnaires, actuellement mCRPC.","ADT fortgeführt; Progress unter neuem hormonellem Wirkstoff.":"ADT poursuivie ; progression sous un nouvel agent hormonal.","Auf dem ursprünglichen Anforderungsschein 'unauffällig'. Im Gespräch berichtet der Patient später von einem Bruder mit Pankreaskarzinom und einem Vater mit Prostatakarzinom.":"La demande initiale indique « sans particularité ». Lors de l’entretien, le patient rapporte ensuite un frère atteint d’un cancer du pancréas et un père atteint d’un cancer de la prostate.","HRD-Score aus dem Ovarialkarzinom wird als universeller PARP-Test verwendet oder Tumor-BRCA und Keimbahnstatus werden gleichgesetzt.":"Un score HRD du cancer de l’ovaire est utilisé comme test PARP universel, ou BRCA tumoral est assimilé au statut germinal.","Stanzbiopsie einer Lebermetastase mit hochgradigem Prostataadenokarzinom.":"Biopsie carottée d’une métastase hépatique avec adénocarcinome prostatique de haut grade.","NKX3.1/PSA-Kontext mit Prostataursprung vereinbar.":"Contexte NKX3.1/PSA compatible avec une origine prostatique.","Klinische Frage":"Question clinique","Therapiebiomarker im mCRPC, nicht erneute Primärdiagnostik.":"Biomarqueurs thérapeutiques dans le mCRPC, pas une nouvelle confirmation du diagnostic initial.","BRCA/HRR, MMR/MSI und hereditäre Einordnung.":"BRCA/HRR, MMR/MSI et évaluation héréditaire.","ca. 55 %, ausreichend für NGS und MMR-IHC.":"env. 55 %, suffisant pour NGS et IHC MMR.","DNA":"ADN","gute Qualität.":"bonne qualité.","12 Schnitte.":"12 coupes.","Methodenfalle":"Piège méthodologique","Ein unspezifischer HRD-Genomic-Scar-Score ist hier nicht der primäre etablierte Selektionsweg; gen-spezifische HRR/BRCA-Diagnostik und MMR/MSI beantworten die konkrete Frage direkter.":"Un score génomique HRD de type genomic scar non spécifique n’est pas ici la voie de sélection établie principale ; le diagnostic HRR/BRCA spécifique des gènes et MMR/MSI répond plus directement à la question clinique.","Prostata-HRR/BRCA-Status":"Statut HRR/BRCA prostatique","MMR/MSI-Kontext":"Contexte MMR/MSI","HRR/BRCA":"HRR/BRCA","Pathogene BRCA2-Frameshift-Variante im Tumor, VAF 58 %, mit zusätzlichem Verlust des Wildtypallels vereinbar. Im mCRPC ist BRCA1/2 unabhängig von somatischer oder Keimbahnherkunft ein relevanter PARP-Biomarkerkontext; die konkrete Therapie richtet sich nach Vorbehandlung und aktueller Zulassung/Leitlinie.":"Variant frameshift pathogène de BRCA2 dans la tumeur, VAF 58 %, compatible avec une perte supplémentaire de l’allèle wild type. Dans le mCRPC, BRCA1/2, qu’il soit d’origine somatique ou germinale, constitue un contexte biomarqueur pertinent pour PARP ; le traitement concret dépend des lignes antérieures et des autorisations/recommandations actuelles.","Erhaltene Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expression conservée de MLH1, PMS2, MSH2 et MSH6 : pMMR.","MSS / kein MSI-H. Damit ergibt sich aus MMR/MSI in diesem Fall kein spezifischer IO-Biomarkerkontext.":"MSS / absence de MSI-H. Ainsi, MMR/MSI n’apporte pas dans ce cas de contexte biomarqueur spécifique pour l’IO.","HRD-Score":"Score HRD","Ein Genomic-Scar/HRD-Score liefert im Prostatakarzinom keine gleichwertige, etablierte Ersatzinformation für die gen-spezifische BRCA/HRR-Diagnostik. Er darf den BRCA2-Befund nicht überstimmen oder eine negative HRR-Analyse ersetzen.":"Un score genomic-scar/HRD dans le cancer de la prostate ne fournit pas une information de remplacement équivalente et établie au diagnostic BRCA/HRR spécifique des gènes. Il ne doit pas supplanter le résultat BRCA2 ni remplacer une analyse HRR négative.","Keimbahnabklärung":"Évaluation germinale","Humangenetische Beratung/Keimbahntestung wird aufgrund der pathogenen BRCA2-Variante und der Familienanamnese empfohlen. Tumor-only VAF und LOH beweisen die Keimbahnherkunft nicht.":"Un conseil génétique/une analyse germinale est recommandé en raison du variant pathogène BRCA2 et de l’histoire familiale. La VAF tumor-only et la LOH ne prouvent pas une origine germinale.","Klinischer Status":"Statut clinique","mCRPC mit Progress nach neuem hormonellen Wirkstoff.":"mCRPC avec progression après un nouvel agent hormonal.","Metastasenbiopsie mit ausreichendem Tumoranteil für HRR- und MMR-Diagnostik.":"Biopsie métastatique avec teneur tumorale suffisante pour les analyses HRR et MMR.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und Hinweis auf biallelische Inaktivierung; pMMR/MSS. Der BRCA2-Befund eröffnet einen PARP-relevanten Therapiekontext gemäß aktueller Indikation/Vorbehandlung. Die Tumoranalyse unterscheidet somatisch und Keimbahn nicht sicher; wegen BRCA2 und Familienanamnese ist eine separate humangenetische Keimbahnabklärung angezeigt. Ein HRD-Score ist kein notwendiger Ersatz für diese gen-spezifische Prostata-Diagnostik.":"mCRPC avec altération pathogène loss-of-function de BRCA2 et arguments compatibles avec une inactivation biallélique ; pMMR/MSS. Le résultat BRCA2 ouvre un contexte thérapeutique pertinent pour PARP selon l’indication actuelle et les traitements antérieurs. L’analyse tumorale ne distingue pas de façon fiable une origine somatique d’une origine germinale ; en raison de BRCA2 et de l’histoire familiale, une évaluation germinale séparée en génétique est indiquée. Un score HRD n’est pas un substitut nécessaire à cette approche diagnostique prostatique spécifique des gènes.","Teilbefund: HRR/BRCA, MMR/MSI und Keimbahnfrage müssen getrennt beantwortet werden. Ein tumor-only BRCA2-Befund kann therapeutisch relevant sein, sagt aber nicht automatisch, ob die Variante vererbt ist.":"Résultat partiel : HRR/BRCA, MMR/MSI et la question germinale doivent être traités séparément. Un résultat BRCA2 tumor-only peut être thérapeutiquement pertinent sans indiquer automatiquement si le variant est hérité.","BRCA2 im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen":"Interpréter BRCA2 dans le mCRPC comme contexte biomarqueur PARP spécifique du gène","pMMR/MSS als fehlenden MMR/MSI-basierten IO-Selektionsbefund kommunizieren":"Communiquer pMMR/MSS comme absence de critère de sélection IO basé sur MMR/MSI","Tumor-BRCA2 nicht mit Keimbahn gleichsetzen; Humangenetik empfehlen":"Ne pas assimiler BRCA2 tumoral au germinal ; recommander un conseil génétique","HRD-Score nicht als universellen oder zwingenden Prostata-PARP-Selektionsmarker darstellen":"Ne pas présenter le score HRD comme un marqueur universel ou obligatoire de sélection PARP dans la prostate","Therapieempfehlung an aktuelle Zulassung, Vorbehandlung und klinischen Kontext binden":"Lier la recommandation thérapeutique à l’autorisation actuelle, aux traitements antérieurs et au contexte clinique","Optimale Lösung: BRCA2 im Tumor als therapeutisch relevanten mCRPC-Biomarker erkennen, pMMR/MSS separat für den IO-Kontext dokumentieren, HRD-Score nicht aus dem Ovarial-Workflow übertragen und die Keimbahnfrage wegen möglicher Familienrelevanz eigenständig humangenetisch klären.":"Solution optimale : reconnaître BRCA2 tumoral comme biomarqueur thérapeutiquement pertinent du mCRPC, documenter séparément pMMR/MSS pour le contexte IO, ne pas transposer le score HRD du workflow ovarien et clarifier indépendamment la question germinale en génétique en raison de son impact familial potentiel.","Prostatakarzinom":"Cancer de la prostate","mCRPC":"mCRPC","HRR":"HRR","MMR":"MMR","BRCA2 im mCRPC: therapeutisch relevant – aber ist es auch Keimbahn?":"BRCA2 dans le mCRPC : pertinent sur le plan thérapeutique – mais est-il aussi germinal ?","Molekularpathologie / Uro-Onkologie / MTB":"Pathologie moléculaire / Uro-oncologie / RCP moléculaire","BRCA1/2- und HRR-Alterationen im mCRPC als gen-spezifischen PARP-Biomarkerkontext einordnen.":"Interpréter les altérations BRCA1/2 et HRR dans le mCRPC comme contexte biomarqueur PARP spécifique des gènes.","Somatische und Keimbahn-BRCA-Alterationen therapeutisch und hereditär getrennt betrachten.":"Considérer séparément les altérations BRCA somatiques et germinales sur les plans thérapeutique et héréditaire.","MMR/MSI als eigenständigen IO-Biomarkerblock prüfen.":"Évaluer MMR/MSI comme bloc biomarqueur IO indépendant.","Einen ovarialkarzinomtypischen HRD-Genomic-Scar-Score nicht als universellen Pflichtmarker auf das Prostatakarzinom übertragen.":"Ne pas transposer au cancer de la prostate un score HRD genomic-scar de type ovarien comme marqueur universel obligatoire.","Familienanamnese und humangenetische Weiterleitung in die MTB-Empfehlung integrieren.":"Intégrer l’histoire familiale et l’orientation en génétique dans la recommandation de RCP moléculaire.","Das Tumorpanel meldet eine pathogene BRCA2-Frameshift-Variante mit VAF 58 % und Hinweis auf Verlust des zweiten Allels. Im MTB heißt es sofort: 'Dann ist das erblich – und wir brauchen noch einen HRD-Score, bevor PARP möglich ist.' Der Fall ist ideal, um zwei häufige Ebenenfehler gleichzeitig zu korrigieren.":"Le panel tumoral rapporte un variant frameshift pathogène de BRCA2 avec une VAF de 58 % et des arguments en faveur de la perte du second allèle. En RCP moléculaire, quelqu’un conclut aussitôt : « Alors c’est héréditaire – et il nous faut encore un score HRD avant d’envisager PARP. » Ce cas est idéal pour corriger simultanément deux erreurs de catégorie fréquentes.","69-jähriger Patient mit mCRPC und Progress nach neuem hormonellem Wirkstoff. Eine Lebermetastasenbiopsie steht für HRR/BRCA- und MMR/MSI-Diagnostik zur Verfügung. Gesucht wird eine Therapieempfehlung, die den tumorbezogenen BRCA2-Befund nutzt, die Keimbahnfrage separat löst und keine Ovarial-HRD-Logik auf die Prostata überträgt.":"Patient de 69 ans avec mCRPC en progression après un nouvel agent hormonal. Une biopsie de métastase hépatique est disponible pour les analyses HRR/BRCA et MMR/MSI. L’objectif est une recommandation thérapeutique exploitant le résultat BRCA2 tumoral, traitant séparément la question germinale et ne transposant pas la logique HRD ovarienne au cancer de la prostate.","Therapiesituation":"Contexte thérapeutique","mCRPC nach Progress unter neuem hormonellem Wirkstoff.":"mCRPC après progression sous un nouvel agent hormonal.","Der konkrete Therapiekontext macht BRCA1/2 besonders relevant.":"Le contexte thérapeutique précis rend BRCA1/2 particulièrement pertinent.","Hereditäre Ebene":"Niveau héréditaire","Bruder mit Pankreas- und Vater mit Prostatakarzinom werden erst im Gespräch bekannt.":"Un frère atteint d’un cancer du pancréas et un père atteint d’un cancer de la prostate ne sont signalés qu’au cours de l’entretien.","Familienanamnese verstärkt die Keimbahnindikation, ersetzt aber keine Testung.":"L’histoire familiale renforce l’indication d’analyse germinale, mais ne remplace pas l’analyse elle-même.","IO-Ebene":"Niveau IO","MMR/MSI ist zu Beginn unbekannt.":"MMR/MSI est inconnu au départ.","DNA-Reparaturdefekt allgemein ist nicht gleich dMMR/MSI-H.":"Un défaut de réparation de l’ADN en général n’équivaut pas à dMMR/MSI-H.","Lebermetastase, ca. 55 % Tumor; DNA und IHC gut auswertbar.":"Métastase hépatique, env. 55 % de tumeur ; ADN et IHC facilement évaluables.","mCRPC mit Progress nach neuem hormonellem Wirkstoff.":"mCRPC avec progression après un nouvel agent hormonal.","Im Verlauf Pankreas- und Prostatakarzinom bei nahen Angehörigen berichtet.":"Au cours de l’évolution, des cancers du pancréas et de la prostate sont rapportés chez des apparentés proches.","Gen-spezifische HRR/BRCA-Diagnostik hat für die konkrete Frage höhere Priorität als ein unspezifischer HRD-Genomic-Scar-Score.":"L’analyse HRR/BRCA spécifique des gènes est prioritaire pour cette question par rapport à un score HRD genomic-scar non spécifique.","Tumorgewebe enthält keine saubere Normalreferenz für die Keimbahnfrage.":"Le tissu tumoral ne fournit pas de référence normale fiable pour la question germinale.","MMR/MSI benötigt eine eigene funktionelle/biomarkerbezogene Beurteilung.":"MMR/MSI nécessite sa propre évaluation fonctionnelle/biomarqueur.","Was ist der zentrale PARP-Biomarkerbefund in diesem Fall?":"Quel est le résultat biomarqueur PARP central dans ce cas ?","Die pathogene BRCA2-Alteration im mCRPC ist der entscheidende gen-spezifische Biomarkerkontext; die konkrete Nutzung hängt von Vorbehandlung und aktueller Indikation ab.":"L’altération pathogène de BRCA2 dans le mCRPC est le contexte biomarqueur spécifique du gène déterminant ; son utilisation concrète dépend des traitements antérieurs et de l’indication actuelle.","Nur ein positiver HRD-Score erlaubt eine PARP-Strategie.":"Seul un score HRD positif permet une stratégie PARP.","pMMR ist der entscheidende PARP-Biomarker.":"pMMR est le biomarqueur PARP déterminant.","Eine VAF über 50 % ist allein der therapeutische Biomarker.":"Une VAF supérieure à 50 % constitue à elle seule le biomarqueur thérapeutique.","Bei mCRPC ist die gen-spezifische BRCA1/2-Alteration zentral; ein Ovarial-HRD-Score ist kein universeller Ersatz.":"Dans le mCRPC, l’altération BRCA1/2 spécifique du gène est centrale ; un score HRD ovarien n’est pas un substitut universel.","Tumor-BRCA2, VAF 58 %, mit LOH: Ist damit die Keimbahnherkunft bewiesen?":"BRCA2 tumoral, VAF 58 %, avec LOH : cela prouve-t-il une origine germinale ?","Nein. Der Tumorbefund kann therapeutisch relevant sein, aber die Keimbahnherkunft muss aus einer geeigneten Normalprobe separat geklärt werden.":"Non. Le résultat tumoral peut être pertinent sur le plan thérapeutique, mais l’origine germinale doit être évaluée séparément sur un échantillon normal approprié.","Ja, VAF >50 % beweist Keimbahn.":"Oui, une VAF >50 % prouve une origine germinale.","Ja, LOH beweist immer eine erbliche Variante.":"Oui, la LOH prouve toujours qu’un variant est hérité.","Nein, Tumorvarianten können grundsätzlich nie Keimbahn sein.":"Non, les variants tumoraux ne peuvent jamais être germinaux.","Tumor-only-NGS trennt somatische und Keimbahnherkunft nicht sicher.":"Le NGS tumor-only ne peut pas distinguer de façon fiable une origine somatique d’une origine germinale.","Reicht eine HRR/BRCA-Alteration als Begründung für eine MMR/MSI-basierte Immuntherapie?":"Une altération HRR/BRCA suffit-elle à justifier une immunothérapie basée sur MMR/MSI ?","Nein. MMR/MSI ist ein separater Biomarkerblock; hier zeigt pMMR/MSS keinen spezifischen MSI-basierten IO-Kontext.":"Non. MMR/MSI constitue un bloc biomarqueur distinct ; ici pMMR/MSS n’apporte pas de contexte IO spécifique basé sur MSI.","Ja. Jede DNA-Reparaturmutation bedeutet immunogen und ICI-sensitiv.":"Oui. Toute mutation de réparation de l’ADN signifie immunogénicité et sensibilité aux ICI.","BRCA2 ist funktionell gleichbedeutend mit MSI-H.":"BRCA2 est fonctionnellement équivalent à MSI-H.","Nur PD-L1 kann die Frage beantworten.":"Seul PD-L1 peut répondre à la question.","HRR und MMR sind unterschiedliche Reparaturachsen mit unterschiedlichen Biomarkerfolgen.":"HRR et MMR sont des voies de réparation différentes avec des conséquences biomarqueurs différentes.","Welche Rolle sollte der HRD-Score hier spielen?":"Quel rôle le score HRD doit-il jouer ici ?","Nicht als Pflicht- oder Ersatzmarker: gen-spezifische BRCA/HRR-Diagnostik ist für diesen Prostatafall entscheidender.":"Pas comme marqueur obligatoire ou substitutif : le diagnostic BRCA/HRR spécifique des gènes est plus déterminant dans ce cas prostatique.","Zwingend vor jeder PARP-Diskussion.":"Obligatoire avant toute discussion concernant PARP.","Er ersetzt die Keimbahnabklärung.":"Il remplace l’évaluation germinale.","Er entscheidet primär über Immuntherapie.":"Il détermine principalement l’immunothérapie.","Der Ovarial-HRD-Workflow darf nicht unkritisch auf mCRPC übertragen werden.":"Le workflow HRD ovarien ne doit pas être transposé sans esprit critique au mCRPC.","Ordnen Sie BRCA2, MMR/MSI und die Keimbahnfrage beim mCRPC so ein, dass die therapeutische Relevanz des Tumorbefunds genutzt wird, ohne die hereditäre Herkunft zu behaupten oder einen HRD-Score unnötig zur Voraussetzung zu machen.":"Interpréter BRCA2, MMR/MSI et la question germinale dans le mCRPC de manière à exploiter la pertinence thérapeutique du résultat tumoral sans affirmer une origine héréditaire ni imposer inutilement un score HRD comme préalable.","Validierte HRR/BRCA-Diagnostik am Tumor durchführen.":"Réaliser une analyse tumorale HRR/BRCA validée.","Pathogene BRCA2-Loss-of-function-Alteration als relevanten mCRPC-Biomarkerkontext berichten.":"Rapporter l’altération pathogène loss-of-function de BRCA2 comme contexte biomarqueur pertinent du mCRPC.","MMR-IHC/MSI separat prüfen: pMMR/MSS.":"Évaluer séparément IHC MMR/MSI : pMMR/MSS.","PARP-Option an aktuelle Indikation, Vorbehandlung und klinische Eignung binden.":"Lier l’option PARP à l’indication actuelle, aux traitements antérieurs et à l’adéquation clinique.","Keimbahnherkunft aus Tumor-VAF/LOH nicht ableiten; Humangenetik/Normalprobe empfehlen.":"Ne pas déduire une origine germinale de la VAF/LOH tumorale ; recommander une évaluation génétique/échantillon normal.","HRD-Score nicht als universellen Pflichtmarker aus dem Ovarialkarzinom übernehmen.":"Ne pas reprendre le score HRD du cancer de l’ovaire comme marqueur universel obligatoire.","Validiertes Tumor-BRCA/HRR-Panel statt Prostata-spezifischem Panel, sofern relevante HRR-Gene und Copy-number/Variantentypen ausreichend erfasst werden.":"Panel tumoral BRCA/HRR validé plutôt qu’un panel spécifique de la prostate, à condition que les gènes HRR pertinents et les types de copy-number/variants soient correctement couverts.","Breiteres validiertes Panel mit BRCA/HRR plus MSI, wenn Material und TAT vertretbar sind; funktionelle MMR-IHC kann ergänzen.":"Panel validé plus large incluant BRCA/HRR plus MSI si le matériel et le TAT le permettent ; l’IHC fonctionnelle MMR peut compléter.","HRD-Score als Pflicht":"Score HRD obligatoire","Überträgt einen entitätsspezifischen Ovarial-Workflow auf die Prostata.":"Transpose au cancer de la prostate un workflow ovarien spécifique d’entité.","Tumor-BRCA = erblich":"BRCA tumoral = héréditaire","Tumor-only-NGS beweist keine Keimbahnherkunft.":"Le NGS tumor-only ne prouve pas une origine germinale.","BRCA = MSI/IO":"BRCA = MSI/IO","HRR und MMR sind verschiedene Reparaturwege und Biomarker.":"HRR et MMR sont des voies de réparation et des biomarqueurs différents.","Familienanamnese ignorieren":"Ignorer l’histoire familiale","Ein möglicher Keimbahnbefund hat Konsequenzen für Patient und Angehörige.":"Un possible résultat germinal a des conséquences pour le patient et ses apparentés.","Therapie kann schon tumorbezogen relevant sein, Familienrelevanz bleibt trotzdem offen":"Le traitement peut déjà être pertinent au niveau tumoral alors que l’impact familial reste à clarifier","Die BRCA2-Loss-of-function-Alteration ist im mCRPC therapeutisch relevant, auch wenn sie somatisch sein könnte. Gleichzeitig macht die aktualisierte Familienanamnese eine Keimbahnabklärung besonders wichtig. MMR-IHC und MSI sind unauffällig. Der vermeintlich noch fehlende HRD-Score ist dagegen gar nicht der zentrale nächste Schritt.":"L’altération loss-of-function de BRCA2 est thérapeutiquement pertinente dans le mCRPC même si elle peut être somatique. Parallèlement, l’histoire familiale actualisée rend l’évaluation germinale particulièrement importante. L’IHC MMR et le MSI sont sans anomalie. En revanche, le score HRD supposément encore manquant n’est pas du tout l’étape centrale suivante.","Der Fall trennt Therapiebiomarker und Hereditätsdiagnostik: dieselbe Variante kann für die Tumortherapie relevant sein, während ihre Herkunft für die Familie separat geklärt werden muss.":"Le cas distingue biomarqueur thérapeutique et diagnostic héréditaire : le même variant peut être pertinent pour traiter la tumeur alors que son origine doit être clarifiée séparément pour la famille.","BRCA2 genutzt, Keimbahn sauber getrennt":"BRCA2 exploité, statut germinal clairement séparé","Pathogene BRCA2-Loss-of-function-Alteration im Tumor mit Hinweis auf biallelische Inaktivierung; pMMR/MSS. PARP-relevanter mCRPC-Kontext gemäß aktueller Indikation/Vorbehandlung; separate humangenetische Keimbahnabklärung empfohlen. HRD-Score nicht als Pflichtmarker benötigt.":"Altération pathogène loss-of-function de BRCA2 dans la tumeur avec arguments compatibles avec une inactivation biallélique ; pMMR/MSS. Contexte mCRPC pertinent pour PARP selon l’indication actuelle/les traitements antérieurs ; évaluation germinale séparée en génétique recommandée. Le score HRD n’est pas requis comme marqueur obligatoire.","Therapie-, IO- und Hereditätsebene korrekt getrennt.":"Niveaux thérapeutique, IO et héréditaire correctement distingués.","BRCA2 erkannt, Heredität offen":"BRCA2 reconnu, hérédité non clarifiée","BRCA2 wird therapeutisch korrekt erkannt, aber Keimbahnabklärung/Familienrelevanz nicht adressiert.":"BRCA2 est correctement reconnu sur le plan thérapeutique, mais l’évaluation germinale/l’impact familial n’est pas abordé.","Klinisch wichtige zweite Ebene fehlt.":"Un deuxième niveau cliniquement important manque.","Ovarial-Workflow kopiert":"Workflow ovarien copié","PARP-Entscheidung wird von einem HRD-Score abhängig gemacht und Tumor-BRCA2 zugleich als sicher erblich bezeichnet.":"La décision PARP est rendue dépendante d’un score HRD tandis que BRCA2 tumoral est simultanément déclaré certainement héréditaire.","Zwei entitätsspezifische Fehlübertragungen.":"Deux extrapolations erronées spécifiques d’entité.","Pathogene BRCA2-Variante im Tumor":"Variant pathogène de BRCA2 dans la tumeur","PARP-Eignung nach aktueller Indikation/Vorbehandlung prüfen und parallel humangenetische Beratung veranlassen.":"Évaluer l’éligibilité à PARP selon l’indication actuelle/les traitements antérieurs et organiser en parallèle un conseil génétique.","Therapieentscheidung und Familienabklärung laufen koordiniert, aber diagnostisch getrennt.":"Décision thérapeutique et évaluation familiale avancent de manière coordonnée mais diagnostiquement séparée.","Keinen MSI/MMR-basierten IO-Biomarker behaupten; andere klinische IO-Indikationen nur separat bewerten.":"Ne pas revendiquer de biomarqueur IO basé sur MSI/MMR ; évaluer séparément d’éventuelles autres indications cliniques d’IO.","DNA-Reparatur wird nicht pauschal mit Immuntherapie gleichgesetzt.":"La réparation de l’ADN n’est pas assimilée globalement à l’immunothérapie.","BRCA1/2 ist im mCRPC ein gen-spezifischer, therapeutisch relevanter Biomarkerkontext.":"BRCA1/2 constitue dans le mCRPC un contexte biomarqueur spécifique des gènes et pertinent sur le plan thérapeutique.","Somatische und Keimbahn-BRCA-Alterationen sind für Therapie und Familie unterschiedliche Ebenen.":"Les altérations BRCA somatiques et germinales correspondent à des niveaux différents pour le traitement et la famille.","Tumor-VAF/LOH beweist die Keimbahn nicht.":"La VAF/LOH tumorale ne prouve pas l’origine germinale.","MMR/MSI muss unabhängig von HRR beurteilt werden.":"MMR/MSI doit être évalué indépendamment de HRR.","Ein HRD-Genomic-Scar-Score ist kein universeller Pflichtmarker für PARP über Tumorentitäten hinweg.":"Un score HRD genomic-scar n’est pas un marqueur universel obligatoire pour PARP dans toutes les entités tumorales.","mCRPC mit pathogener BRCA2-Loss-of-function-Alteration und pMMR/MSS. BRCA2 ist tumorbezogen PARP-relevant gemäß aktueller Indikation/Vorbehandlung. Die Keimbahnherkunft ist nicht aus Tumor-VAF oder LOH ableitbar; wegen Befund und Familienanamnese Humangenetik empfehlen. Kein obligatorischer Ovarial-HRD-Score.":"mCRPC avec altération pathogène loss-of-function de BRCA2 et pMMR/MSS. BRCA2 est pertinent pour PARP au niveau tumoral selon l’indication actuelle/les traitements antérieurs. L’origine germinale ne peut être déduite de la VAF tumorale ou de la LOH ; recommander une évaluation génétique en raison du résultat et de l’histoire familiale. Pas de score HRD ovarien obligatoire.","BRCA2 tumorbezogen korrekt genutzt":"BRCA2 tumoral correctement exploité","MMR/MSI separat bewertet":"MMR/MSI évalué séparément","Keimbahn nicht behauptet":"Origine germinale non affirmée","HRD-Score nicht zum Pflichtmarker gemacht":"Score HRD non rendu obligatoire","Warum kann derselbe BRCA2-Befund therapeutisch nutzbar sein, obwohl die Keimbahnherkunft noch offen ist?":"Pourquoi le même résultat BRCA2 peut-il être exploité thérapeutiquement alors que son origine germinale reste non clarifiée ?","Welche Proben eignen sich zur Keimbahnklärung?":"Quels échantillons sont adaptés pour clarifier le statut germinal ?","Warum sind HRD-Genomic-Scar-Tests nicht automatisch zwischen Tumorentitäten übertragbar?":"Pourquoi les tests HRD genomic-scar ne sont-ils pas automatiquement transposables entre entités tumorales ?","BRCA2 ist therapeutisch relevant, ohne dass die Keimbahn bereits geklärt ist":"BRCA2 est pertinent sur le plan thérapeutique sans que le statut germinal soit déjà clarifié","Therapiebiomarker und Hereditätsstatus sind getrennte Ebenen":"Biomarqueur thérapeutique et statut héréditaire sont des niveaux distincts","HRR/BRCA → MMR/MSI separat → PARP-Kontext → Keimbahnklärung":"HRR/BRCA → MMR/MSI séparément → contexte PARP → clarification germinale","Therapieassoziierte MDS/AML nach DNA-schädigender Therapie → Instabilität als Chance und Risiko einordnen":"MDS/LAM liée au traitement après thérapie génotoxique → interpréter l’instabilité comme opportunité et risque","Therapieassoziierte MDS/AML nach D…":"MDS/LAM liée au traitement après D…","Hämatologie / interdisziplinäres Tumorboard":"Hématologie / RCP interdisciplinaire","67-jährige Patientin mit neu aufgetretener Pancytopenie acht Jahre nach Behandlung eines Mammakarzinoms mit zytotoxischer Chemotherapie und Radiotherapie.":"Patiente de 67 ans présentant une pancytopénie récente huit ans après traitement d’un cancer du sein par chimiothérapie cytotoxique et radiothérapie.","Wie werden Morphologie, Zytogenetik, molekulares Profil und die frühere zytotoxische Therapie zu einer belastbaren Diagnose- und Risikoeinschätzung integriert?":"Comment intégrer morphologie, cytogénétique, profil moléculaire et traitement cytotoxique antérieur dans une évaluation diagnostique et pronostique robuste ?","Therapiebeginn nach Abschluss der hämatologischen Klassifikation.":"Le traitement débute après finalisation de la classification hématologique.","Anthrazyklin-/Cyclophosphamid-haltige Chemotherapie und Bestrahlung vor acht Jahren.":"Chimiothérapie à base d’anthracycline/cyclophosphamide et radiothérapie huit ans auparavant.","Aktuell":"Résultats actuels","Hb 8,4 g/dl, Thrombozyten 46/nl, Neutrophile 0,7/nl; peripher 9 % Blasten.":"Hb 8,4 g/dl, plaquettes 46/nl, neutrophiles 0,7/nl ; 9 % de blastes périphériques.","Knochenmark":"Moelle osseuse","27 % myeloische Blasten, ausgeprägte Dysplasie.":"27 % de blastes myéloïdes, dysplasie marquée.","Die Vorgeschichte wird allein zur Diagnose 'therapieassoziierte AML' gemacht oder ein einzelner DNMT3A-/TET2-/ASXL1-Befund wird ohne Morphologie/Zytogenetik als Neoplasiebeweis interpretiert.":"L’antécédent seul sert à poser le diagnostic de « LAM liée au traitement », ou un résultat isolé DNMT3A/TET2/ASXL1 est interprété comme preuve de néoplasie sans morphologie/cytogénétique.","Morphologie + Vorbefunde":"Morphologie + résultats antérieurs","Hyperzellulär, 27 % Blasten, dysplastische Granulo- und Megakaryopoese.":"Hypercellulaire, 27 % de blastes, granulopoïèse et mégacaryopoïèse dysplasiques.","Zytogenetik":"Cytogénétique","Komplexer Karyotyp mit -5/del(5q), -7 und 17p-Verlust.":"Caryotype complexe avec -5/del(5q), -7 et perte de 17p.","Akute myeloische Neoplasie mit hochriskanter Genominstabilität; frühere zytotoxische Exposition muss als qualifizierender Kontext integriert werden.":"Néoplasie myéloïde aiguë avec instabilité génomique à haut risque ; l’exposition cytotoxique antérieure doit être intégrée comme contexte qualifiant.","Welche Rolle spielt das molekulare Profil – und was darf daraus gerade nicht abgeleitet werden?":"Quel rôle joue le profil moléculaire – et que ne faut-il surtout pas en déduire ?","EDTA-Knochenmarkaspirat plus Trepanobiopsie.":"Aspirat médullaire sur EDTA plus biopsie ostéomédullaire.","Tumorzellanteil":"Contenu tumoral","Blasten ca. 27 %; NGS aus Knochenmark geeignet.":"Blastes env. 27 % ; moelle osseuse adaptée au NGS.","Vorbefunde":"Résultats antérieurs","Morphologie und Zytogenetik liegen bereits vor und dürfen nicht durch NGS ersetzt werden.":"La morphologie et la cytogénétique sont déjà disponibles et ne doivent pas être remplacées par le NGS.","Ein Pan-Tumorpanel mit TMB/MSI wäre für die konkrete myeloische Klassifikationsfrage Low Value; das fokussierte hämatologische Panel ist näher an der Fragestellung.":"Un panel pan-tumoral avec TMB/MSI serait de faible valeur pour la question précise de classification myéloïde ; un panel hématologique ciblé répond mieux à la question clinique.","Myeloischer Molekularkontext":"Contexte moléculaire myéloïde","Hämatologisches NGS":"NGS hématologique","TP53 p.R273H mit VAF 43 % sowie DNMT3A p.R882H mit VAF 4 %. Im Kontext von 17p-Verlust und komplexem Karyotyp ist TP53 Teil der hochriskanten Neoplasie; die niedrigfrequente DNMT3A-Alteration allein wäre dagegen kein Beweis für AML und kann klonale Hämatopoese repräsentieren.":"TP53 p.R273H avec VAF 43 % et DNMT3A p.R882H avec VAF 4 %. Dans le contexte d’une perte 17p et d’un caryotype complexe, TP53 fait partie de la néoplasie à haut risque ; l’altération DNMT3A de faible fréquence seule ne prouverait pas une LAM et peut représenter une hématopoïèse clonale.","Zusätzliche solide-tumororientierte TMB/MSI-/Pan-Cancer-Information beantwortet die zentrale myeloische Klassifikations- und Risikofrage nicht besser und erzeugt unnötige Nebenbefunde.":"Des informations supplémentaires TMB/MSI/pan-cancer orientées tumeurs solides ne répondent pas mieux à la question centrale de classification et de risque myéloïde et génèrent des résultats accessoires inutiles.","Morphologie":"Morphologie","27 % myeloische Blasten mit Dysplasie.":"27 % de blastes myéloïdes avec dysplasie.","Exposition":"Exposition","Zytotoxische Chemotherapie/Radiotherapie acht Jahre zuvor.":"Chimiothérapie cytotoxique/radiothérapie huit ans auparavant.","Akute myeloische Neoplasie mit TP53-Alteration und komplexer Zytogenetik nach vorausgegangener zytotoxischer Therapie. Die frühere Therapie ist ein wichtiger qualifizierender klinischer Kontext, die Erkrankung wird jedoch primär aus Morphologie und genetischen Merkmalen klassifiziert. Der TP53/komplexe-Karyotyp-Kontext spricht für ungünstige Biologie. Eine niedrigfrequente DNMT3A-Alteration allein wäre nicht ausreichend, um die Neoplasie zu definieren. 'Genomische Instabilität' ist hier kein pauschales Target- oder Immuntherapiesignal.":"Néoplasie myéloïde aiguë avec altération TP53 et cytogénétique complexe après traitement cytotoxique antérieur. Le traitement antérieur constitue un contexte clinique qualifiant important, mais la maladie est classée principalement selon la morphologie et les caractéristiques génétiques. Le contexte TP53/caryotype complexe indique une biologie défavorable. Une altération DNMT3A de faible fréquence seule ne suffirait pas à définir la néoplasie. L’« instabilité génomique » n’est pas ici un signal général de cible ou d’immunothérapie.","Teilbefund: Die frühere zytotoxische Therapie erhöht die Plausibilität eines post-zytotoxischen/therapiebezogenen Kontextes, ersetzt aber nicht die aktuelle morphologische und genetische Klassifikation. CHIP-typische Varianten dürfen nicht isoliert überinterpretiert werden.":"Résultat partiel : un traitement cytotoxique antérieur augmente la plausibilité d’un contexte post-cytotoxique/liée au traitement, mais ne remplace pas la classification morphologique et génétique actuelle. Les variants typiques de CHIP ne doivent pas être surinterprétés isolément.","Morphologie/Genetik priorisieren und frühere zytotoxische Therapie als qualifizierenden Kontext integrieren":"Prioriser morphologie/génétique et intégrer le traitement cytotoxique antérieur comme contexte qualifiant","TP53 plus komplexen Karyotyp als hochriskante Biologie erkennen":"Reconnaître TP53 plus caryotype complexe comme biologie à haut risque","Niedrigfrequentes DNMT3A nicht allein als AML-Beweis interpretieren":"Ne pas interpréter DNMT3A de faible fréquence seul comme preuve de LAM","Genominstabilität nicht automatisch als Target-/TMB-/IO-Chance verkaufen":"Ne pas présenter automatiquement l’instabilité génomique comme opportunité de ciblage/TMB/IO","Hämatologische Klassifikation und Risikostratifikation nicht durch ein solides Pan-Panel ersetzen":"Ne pas remplacer classification hématologique et stratification du risque par un pan-panel de tumeurs solides","Optimale Lösung: AML/myeloische Neoplasie aus Morphologie und Genetik klassifizieren; die frühere zytotoxische Therapie als qualifizierenden Kontext dokumentieren; TP53 plus komplexe Zytogenetik als ungünstige Biologie einordnen; niedrigfrequentes DNMT3A als potenziellen CH-Klon nicht überbewerten.":"Solution optimale : classer la LAM/néoplasie myéloïde à partir de la morphologie et de la génétique ; documenter le traitement cytotoxique antérieur comme contexte qualifiant ; considérer TP53 plus cytogénétique complexe comme biologie défavorable ; ne pas surévaluer DNMT3A de faible fréquence, qui peut représenter un clone CH.","AML":"LAM","post cytotoxic therapy":"post-traitement cytotoxique","TP53":"TP53","complex karyotype":"caryotype complexe","clonal hematopoiesis":"hématopoïèse clonale","genomic instability":"instabilité génomique","Nach zytotoxischer Therapie: TP53, komplexer Karyotyp und die Falle 'Genominstabilität = Target'":"Après traitement cytotoxique : TP53, caryotype complexe et le piège « instabilité génomique = cible »","Molekularpathologie / Hämatologie / Translation":"Pathologie moléculaire / Hématologie / Translation","Eine myeloische Neoplasie nach zytotoxischer Therapie primär aus aktueller Morphologie und Genetik klassifizieren und die frühere Exposition als qualifizierenden Kontext integrieren.":"Classer une néoplasie myéloïde après traitement cytotoxique principalement à partir de la morphologie et de la génétique actuelles et intégrer l’exposition antérieure comme contexte qualifiant.","TP53 plus komplexe Zytogenetik als hochriskante Biologie erkennen.":"Reconnaître TP53 plus cytogénétique complexe comme biologie à haut risque.","CHIP-typische Varianten wie niedrigfrequentes DNMT3A nicht isoliert als AML-Beweis interpretieren.":"Ne pas interpréter isolément des variants typiques de CHIP comme DNMT3A de faible fréquence comme preuve de LAM.","Das biologische Konzept 'genomische Instabilität' nicht automatisch in einen therapeutischen Target- oder Immuntherapiemarker übersetzen.":"Ne pas traduire automatiquement le concept biologique d’« instabilité génomique » en cible thérapeutique ou marqueur d’immunothérapie.","Solide-tumororientierte Pan-Cancer-Tests nicht unkritisch auf eine myeloische Fragestellung übertragen.":"Ne pas transposer sans esprit critique des tests pan-cancer orientés tumeurs solides à une question myéloïde.","Acht Jahre nach Chemotherapie und Bestrahlung wegen Mammakarzinoms entwickelt die Patientin eine Pancytopenie. Das Knochenmark zeigt 27 % Blasten, der Karyotyp ist komplex. Im NGS erscheinen TP53 mit hoher und DNMT3A mit sehr niedriger VAF. Im Board fallen zwei schnelle Erklärungen: 'Die alte Chemotherapie hat die AML verursacht' und 'viel Genominstabilität bedeutet vielleicht viel Target-/IO-Potenzial'. Beide Aussagen müssen präziser werden.":"Huit ans après une chimiothérapie et une radiothérapie pour cancer du sein, la patiente développe une pancytopénie. La moelle montre 27 % de blastes et le caryotype est complexe. Le NGS révèle TP53 à VAF élevée et DNMT3A à très faible VAF. Deux explications rapides surgissent en RCP : « L’ancienne chimiothérapie a causé la LAM » et « beaucoup d’instabilité génomique signifie peut-être beaucoup de potentiel de ciblage/IO ». Ces deux affirmations doivent être précisées.","67-jährige Patientin mit akuter myeloischer Neoplasie nach vorausgegangener zytotoxischer Therapie. Morphologie und komplexe Zytogenetik stehen bereits fest; das molekulare Panel soll die biologische Einordnung ergänzen. Ziel ist nicht, aus einer Exposition oder einem Einzelgen allein eine Diagnose zu konstruieren, sondern die aktuelle Erkrankung korrekt zu klassifizieren und die Genominstabilität klinisch realistisch zu bewerten.":"Patiente de 67 ans avec néoplasie myéloïde aiguë après traitement cytotoxique antérieur. La morphologie et la cytogénétique complexe sont déjà établies ; le panel moléculaire doit compléter la classification biologique. L’objectif n’est pas de construire un diagnostic à partir d’une exposition ou d’un seul gène, mais de classer correctement la maladie actuelle et d’évaluer de manière cliniquement réaliste l’instabilité génomique.","27 % myeloische Blasten mit deutlicher Dysplasie.":"27 % de blastes myéloïdes avec dysplasie marquée.","Die aktuelle Neoplasie ist morphologisch manifest; NGS ersetzt diese Ebene nicht.":"La néoplasie actuelle est morphologiquement manifeste ; le NGS ne remplace pas ce niveau.","Mehrere strukturelle Verluste sprechen für hochriskante klonale Genominstabilität.":"De multiples pertes structurales indiquent une instabilité génomique clonale à haut risque.","Zytotoxische Chemotherapie und Radiotherapie acht Jahre zuvor.":"Chimiothérapie cytotoxique et radiothérapie huit ans auparavant.","Wichtiger diagnostischer Qualifier/Kontext, aber nicht die alleinige Krankheitsdefinition.":"Qualificateur/contexte diagnostique important, mais pas définition unique de la maladie.","Blutbild":"Numération sanguine","Pancytopenie, peripher 9 % Blasten.":"Pancytopénie, 9 % de blastes périphériques.","27 % Blasten, dysplastische Myelopoese.":"27 % de blastes, myélopoïèse dysplasique.","Karyotyp":"Caryotype","Komplex mit -5/del(5q), -7 und 17p-Verlust.":"Complexe avec -5/del(5q), -7 et perte de 17p.","Knochenmark ist für fokussiertes hämatologisches NGS geeignet.":"La moelle osseuse est adaptée à un NGS hématologique ciblé.","Morphologie und Zytogenetik sind bereits hochinformativ und dürfen nicht durch einen molekularen Einzelmarker ersetzt werden.":"La morphologie et la cytogénétique sont déjà très informatives et ne doivent pas être remplacées par un seul marqueur moléculaire.","Ein solides Pan-Cancer-Panel mit TMB/MSI erzeugt für diese Fragestellung eher Nebeninformation als klinischen Mehrwert.":"Un panel pan-cancer de tumeurs solides avec TMB/MSI générerait davantage d’informations accessoires que de valeur clinique pour cette question.","Wie sollte die frühere zytotoxische Therapie diagnostisch verwendet werden?":"Comment utiliser diagnostiquement le traitement cytotoxique antérieur ?","Als wichtiger qualifizierender Kontext einer anhand aktueller morphologischer/genetischer Merkmale klassifizierten myeloischen Neoplasie.":"Comme contexte qualifiant important d’une néoplasie myéloïde classée selon les caractéristiques morphologiques/génétiques actuelles.","Allein die Exposition definiert unabhängig von aktuellen Befunden automatisch die AML-Untergruppe.":"L’exposition seule définit automatiquement le sous-groupe de LAM indépendamment des résultats actuels.","Die frühere Therapie darf in der Diagnose überhaupt nicht erwähnt werden.":"Le traitement antérieur ne doit pas du tout être mentionné dans le diagnostic.","Sie ist primär ein therapeutischer Target-Biomarker.":"C’est avant tout un biomarqueur cible thérapeutique.","Moderne Klassifikation priorisiert die aktuelle Krankheitsbiologie; die Exposition wird als relevanter Kontext/Qualifier integriert.":"La classification moderne donne la priorité à la biologie actuelle de la maladie ; l’exposition est intégrée comme contexte/qualificateur pertinent.","Wie ist TP53 VAF 43 % zusammen mit 17p-Verlust und komplexem Karyotyp zu bewerten?":"Comment évaluer TP53 avec VAF 43 % associé à une perte 17p et un caryotype complexe ?","Als Teil einer hochriskanten TP53-/komplex-karyotypischen Krankheitsbiologie, nicht als isolierter Einzelmarker.":"Comme élément d’une biologie TP53/caryotype complexe à haut risque, et non comme marqueur isolé.","Als einfacher Targetmarker mit erwartbar günstiger Prognose.":"Comme simple marqueur cible avec pronostic favorable attendu.","Sicher nur CHIP, weil TP53 auch in klonaler Hämatopoese vorkommen kann.":"Certainement seulement un CHIP puisque TP53 peut aussi survenir dans l’hématopoïèse clonale.","Zytogenetik macht molekulare Befunde irrelevant.":"La cytogénétique rend les résultats moléculaires sans pertinence.","Genetischer Kontext und klonale Architektur sind entscheidend.":"Le contexte génétique et l’architecture clonale sont déterminants.","DNMT3A p.R882H liegt zusätzlich mit 4 % VAF vor. Was ist die beste Interpretation?":"DNMT3A p.R882H est également présent à une VAF de 4 %. Quelle est la meilleure interprétation ?","Ein niedrigfrequenter CH-Klon ist möglich; DNMT3A allein beweist weder AML noch erklärt es die gesamte hochriskante Erkrankung.":"Un clone CH de faible fréquence est possible ; DNMT3A seul ne prouve ni la LAM ni n’explique l’ensemble de la maladie à haut risque.","DNMT3A definiert allein die AML.":"DNMT3A seul définit la LAM.","4 % VAF beweist eine Keimbahnmutation.":"Une VAF de 4 % prouve une mutation germinale.","DNMT3A ist ein PARP-Biomarker.":"DNMT3A est un biomarqueur PARP.","CHIP-typische Gene müssen im morphologischen und klonalen Kontext interpretiert werden.":"Les gènes typiques de CHIP doivent être interprétés dans leur contexte morphologique et clonal.","Was bedeutet die ausgeprägte Genominstabilität therapeutisch?":"Que signifie sur le plan thérapeutique l’instabilité génomique marquée ?","Sie erklärt aggressive klonale Evolution/Risikobiologie, ist aber kein pauschaler TMB-, IO- oder Targetmarker; konkrete Alterationen und hämatologische Evidenz entscheiden.":"Elle explique une évolution clonale agressive/une biologie de risque, mais n’est pas un marqueur général de TMB, d’IO ou de ciblage ; les altérations précises et les données hématologiques déterminent la conduite.","Viele Aberrationen bedeuten automatisch hohe Immuntherapie-Sensitivität.":"De nombreuses anomalies signifient automatiquement une forte sensibilité à l’immunothérapie.","Komplexer Karyotyp ist automatisch eine PARP-Indikation.":"Un caryotype complexe indique automatiquement PARP.","Mehr Instabilität bedeutet generell bessere Targetierbarkeit und Prognose.":"Davantage d’instabilité signifie généralement une meilleure ciblabilité et un meilleur pronostic.","Ein biologisches Hallmark ist nicht identisch mit einem validierten klinischen Biomarker.":"Un hallmark biologique n’est pas identique à un biomarqueur clinique validé.","Integrieren Sie frühere zytotoxische Therapie, Morphologie, komplexen Karyotyp und TP53/DNMT3A so, dass Diagnose-/Risikokontext und Grenzen des Begriffs 'genomische Instabilität' klar werden.":"Intégrer traitement cytotoxique antérieur, morphologie, caryotype complexe et TP53/DNMT3A afin de clarifier le contexte diagnostique/de risque et les limites du terme « instabilité génomique ».","Aktuelle myeloische Neoplasie aus Morphologie und Genetik einordnen.":"Classer la néoplasie myéloïde actuelle à partir de la morphologie et de la génétique.","Vorausgegangene zytotoxische Therapie als relevanten post-zytotoxischen/therapiebezogenen Qualifier dokumentieren.":"Documenter le traitement cytotoxique antérieur comme qualificateur post-cytotoxique/liée au traitement pertinent.","TP53 zusammen mit 17p-Verlust und komplexem Karyotyp als hochriskanten biologischen Kontext bewerten.":"Évaluer TP53 avec la perte 17p et le caryotype complexe comme contexte biologique à haut risque.","Niedrigfrequentes DNMT3A nicht isoliert als AML-definierend interpretieren.":"Ne pas interpréter DNMT3A de faible fréquence isolément comme définissant la LAM.","Keine pauschale PARP-/IO-/TMB-Logik aus 'Genominstabilität' ableiten.":"Ne pas déduire une logique générale PARP/IO/TMB de l’« instabilité génomique ».","Hämatologiespezifische Diagnostik gegenüber einem Pan-Cancer-Panel priorisieren.":"Prioriser le diagnostic hématologique spécifique par rapport à un panel pan-cancer.","Ein umfassenderes validiertes myeloisches NGS-Panel wäre für reale Routinediagnostik sinnvoll, sofern Morphologie, Immunphänotyp und Zytogenetik integriert bleiben.":"Un panel NGS myéloïde validé plus complet serait approprié en routine réelle, à condition de maintenir l’intégration de la morphologie, de l’immunophénotype et de la cytogénétique.","Bei unklarer klonaler Architektur kann eine geeignete Verlauf-/Vorprobe helfen, präexistente klonale Hämatopoese von dominanter Leukämieklonalität abzugrenzen.":"Si l’architecture clonale est incertaine, un échantillon approprié de suivi/antérieur peut aider à distinguer une hématopoïèse clonale préexistante d’une clonalité leucémique dominante.","Exposition = Diagnose":"Exposition = diagnostic","Die frühere Therapie ist Kontext/Qualifier; aktuelle Morphologie und Genetik definieren die Erkrankung.":"Le traitement antérieur est un contexte/qualificateur ; la morphologie et la génétique actuelles définissent la maladie.","DNMT3A = AML":"DNMT3A = LAM","CHIP-typische Varianten können ohne manifeste Neoplasie vorkommen und brauchen Kontext.":"Les variants typiques de CHIP peuvent survenir sans néoplasie manifeste et nécessitent un contexte.","Genominstabilität = IO/PARP":"Instabilité génomique = IO/PARP","Hallmark und validierter prädiktiver Biomarker sind nicht dasselbe.":"Hallmark et biomarqueur prédictif validé ne sont pas la même chose.","Pan-Cancer-TMB/MSI":"TMB/MSI pan-cancer","Für die konkrete myeloische Klassifikationsfrage ist dies kein sinnvoller Primäransatz.":"Ce n’est pas une approche primaire utile pour la question précise de classification myéloïde.","Der kleine DNMT3A-Klon ist nicht die Geschichte – TP53 plus Karyotyp ist es":"Le petit clone DNMT3A n’est pas l’histoire – TP53 plus le caryotype, oui","Das Panel zeigt DNMT3A p.R882H nur mit 4 % VAF, daneben TP53 p.R273H mit 43 %. Zusammen mit 17p-Verlust und komplexem Karyotyp ist TP53 Teil der dominanten hochriskanten Krankheitsbiologie. DNMT3A kann dagegen einen kleineren, möglicherweise präexistierenden CH-Klon markieren. Die 'vielen genetischen Schäden' sind hier vor allem Risikosignatur – nicht automatisch therapeutische Verwundbarkeit.":"Le panel montre DNMT3A p.R882H à seulement 4 % de VAF, aux côtés de TP53 p.R273H à 43 %. Avec la perte 17p et le caryotype complexe, TP53 fait partie de la biologie dominante à haut risque. DNMT3A peut en revanche marquer un clone CH plus petit, possiblement préexistant. Les « nombreuses lésions génétiques » constituent ici surtout une signature de risque – pas automatiquement une vulnérabilité thérapeutique.","Der Fall zeigt, dass Mutationsnamen ohne Klonstärke, Zytogenetik, Morphologie und klinischen Kontext leicht in die falsche Richtung führen.":"Le cas montre à quel point des noms de mutations sans taille clonale, cytogénétique, morphologie ni contexte clinique peuvent facilement orienter dans la mauvaise direction.","Klonale Architektur und Exposition integriert":"Architecture clonale et exposition intégrées","Akute myeloische Neoplasie mit TP53-Alteration und komplexem Karyotyp nach zytotoxischer Therapie. TP53/17p/komplexer Karyotyp = hochriskanter dominanter Kontext; DNMT3A 4 % VAF potenziell CH-Klon. Keine pauschale Target-/IO-Aussage aus Genominstabilität.":"Néoplasie myéloïde aiguë avec altération TP53 et caryotype complexe après traitement cytotoxique. TP53/17p/caryotype complexe = contexte dominant à haut risque ; DNMT3A VAF 4 % potentiellement clone CH. Pas d’affirmation générale de ciblage/IO à partir de l’instabilité génomique.","Morphologie, Genetik, Exposition und Klonalität korrekt zusammengeführt.":"Morphologie, génétique, exposition et clonalité correctement intégrées.","Therapieassoziiert erkannt, Genetik zu grob":"Contexte lié au traitement reconnu, génétique trop grossière","Die frühere Chemotherapie wird korrekt erwähnt, aber TP53 und DNMT3A werden gleichgewichtet und der komplexe Karyotyp bleibt unterbewertet.":"La chimiothérapie antérieure est correctement mentionnée, mais TP53 et DNMT3A sont pondérés de façon égale et le caryotype complexe est sous-évalué.","Klonale und prognostische Hierarchie fehlt.":"La hiérarchie clonale et pronostique manque.","Instabilität als Therapiechance verkauft":"Instabilité présentée comme opportunité thérapeutique","Komplexer Karyotyp und TP53 werden als unspezifischer Hinweis auf hohe TMB/IO- oder PARP-Sensitivität interpretiert.":"Le caryotype complexe et TP53 sont interprétés comme un indice non spécifique de TMB élevé/IO ou de sensibilité à PARP.","Hallmark wurde fälschlich zum prädiktiven Biomarker gemacht.":"Un hallmark a été transformé à tort en biomarqueur prédictif.","TP53 + komplexer Karyotyp bestätigt":"TP53 + caryotype complexe confirmés","Hämatologische Risikostratifikation und Therapieplanung entsprechend der hochriskanten Krankheitsbiologie durchführen.":"Réaliser la stratification hématologique du risque et la planification thérapeutique selon la biologie à haut risque de la maladie.","Die Priorität liegt auf korrekter Klassifikation/Risiko- und Therapieplanung, nicht auf unspezifischem Pan-Cancer-Targeting.":"La priorité est la classification correcte/le risque et la planification thérapeutique, pas un ciblage pan-cancer non spécifique.","niedrigfrequente CH-typische Variante":"variant typique de CH de faible fréquence","Nur im Kontext interpretieren; bei Bedarf Verlauf/Vorproben zur Klonhistorie heranziehen.":"Interpréter uniquement dans le contexte ; si nécessaire utiliser des échantillons de suivi/antérieurs pour l’histoire clonale.","CHIP und manifeste Neoplasie werden nicht verwechselt.":"CHIP et néoplasie manifeste ne sont pas confondus.","Post-zytotoxische/therapiebezogene Vorgeschichte ist ein wichtiger Qualifier, nicht die alleinige Definition der aktuellen myeloischen Erkrankung.":"L’antécédent post-cytotoxique/liée au traitement est un qualificateur important, pas la seule définition de la maladie myéloïde actuelle.","TP53 plus komplexer Karyotyp kennzeichnet hochriskante Biologie.":"TP53 plus caryotype complexe caractérise une biologie à haut risque.","Niedrige VAF in CHIP-typischen Genen kann eine kleinere Begleitklonalität darstellen.":"Une faible VAF dans des gènes typiques de CHIP peut représenter un clone associé plus petit.","Genomische Instabilität ist ein Hallmark, aber kein universeller Target- oder Immuntherapiemarker.":"L’instabilité génomique est un hallmark, mais pas un biomarqueur universel de ciblage ou d’immunothérapie.","Hämatologische Diagnostik muss Morphologie, Zytogenetik und Molekulargenetik integrieren.":"Le diagnostic hématologique doit intégrer morphologie, cytogénétique et génétique moléculaire.","Akute myeloische Neoplasie nach zytotoxischer Therapie mit dominanter TP53-/komplex-karyotypischer Hochrisikobiologie. Die Exposition wird als Qualifier integriert. DNMT3A bei 4 % VAF kann eine kleinere CH-Klonalität repräsentieren und definiert die AML nicht. Aus Genominstabilität folgt keine pauschale PARP-/IO-Indikation.":"Néoplasie myéloïde aiguë après traitement cytotoxique avec biologie dominante à haut risque TP53/caryotype complexe. L’exposition est intégrée comme qualificateur. DNMT3A à VAF 4 % peut représenter un petit clone CH et ne définit pas la LAM. L’instabilité génomique n’implique pas une indication générale PARP/IO.","Exposition als Qualifier statt Alleindefinition":"Exposition comme qualificateur plutôt que définition unique","TP53/komplexer Karyotyp priorisiert":"TP53/caryotype complexe priorisés","DNMT3A niedrig-VAF nicht überinterpretiert":"DNMT3A à faible VAF non surinterprété","Hallmark ≠ klinischer Biomarker":"Hallmark ≠ biomarqueur clinique","Warum sind Therapiegeschichte und aktuelle Genetik beide wichtig, aber nicht austauschbar?":"Pourquoi l’histoire thérapeutique et la génétique actuelle sont-elles toutes deux importantes sans être interchangeables ?","Wie hilft die VAF bei der Interpretation möglicher CH-Klone?":"Comment la VAF aide-t-elle à interpréter d’éventuels clones CH ?","Welche zusätzlichen Untersuchungen gehören real zur AML-Klassifikation, obwohl dieser Simulatorfall den Fokus enger setzt?":"Quels examens supplémentaires font réellement partie de la classification de la LAM, même si ce cas du simulateur a un focus plus étroit ?","DNMT3A low-VAF ist Nebenklon; TP53 plus komplexer Karyotyp dominiert":"DNMT3A à faible VAF est un clone mineur ; TP53 plus caryotype complexe dominent","Genominstabilität ist Risikobiologie, nicht automatisch Target":"L’instabilité génomique est une biologie de risque, pas automatiquement une cible","Exposition → Morphologie/Zytogenetik → TP53/DNMT3A-Klonalität → Risikokontext":"Exposition → morphologie/cytogénétique → clonalité TP53/DNMT3A → contexte de risque","„Cold Tumor“ mit wenig TILs und dichter Stromabarriere → Warum ist PD-1 allein wahrscheinlich schwach?":"« Tumeur froide » avec peu de TIL et une barrière stromale dense → Pourquoi PD-1 seul est-il probablement peu efficace ?","„Cold Tumor“ mit wenig TILs und di…":"« Tumeur froide » avec peu de TIL et ba…","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach systemischer Erstlinientherapie. Ein externer Zusatzbefund nennt PD-L1 TPS 15 % und löst die Frage nach einer PD-1-Monotherapie aus.":"Patient de 64 ans atteint d’un adénocarcinome canalaire pancréatique métastatique en progression après traitement systémique de première ligne. Un rapport externe complémentaire mentionne PD-L1 TPS 15 % et soulève la question d’une monothérapie anti-PD-1.","Ist die PD-L1-Expression hier ein belastbarer Hinweis auf Checkpoint-Sensitivität – oder spricht das gesamte Tumor-Immune-Milieu eher dagegen?":"L’expression de PD-L1 est-elle ici un indice robuste de sensibilité aux checkpoints – ou l’ensemble du milieu immuno-tumoral va-t-il plutôt à l’encontre ?","Die Zweitlinienstrategie soll im nächsten MTB festgelegt werden.":"La stratégie de deuxième ligne doit être décidée lors de la prochaine RCP moléculaire.","Krankheitsverlauf":"Évolution de la maladie","Primär lokal fortgeschritten, später hepatische Metastasierung; nun radiologischer Progress.":"Initialement localement avancé, puis métastases hépatiques ; progression radiologique actuelle.","Systemische Standardtherapie, insgesamt gute Belastbarkeit; keine bekannte Autoimmunerkrankung.":"Traitement systémique standard, état général globalement bon ; aucune maladie auto-immune connue.","Externer Impuls":"Élément externe","PD-L1 TPS 15 % wird im Zuweiserbrief als 'positiv – Immuntherapie möglich?' markiert.":"PD-L1 TPS 15 % est indiqué dans la lettre d’adressage comme « positif – immunothérapie possible ? ».","Ein exprimierter Checkpoint wird mit bereits vorhandener effektiver Antitumor-Immunität gleichgesetzt.":"L’expression d’un checkpoint est assimilée à une immunité antitumorale efficace déjà présente.","Duktales Adenokarzinom mit ausgeprägter desmoplastischer Stromareaktion.":"Adénocarcinome canalaire avec réaction stromale desmoplastique marquée.","Immunmorphologie":"Morphologie immunitaire","Nur wenige intraepitheliale Lymphozyten; Immunzellen liegen überwiegend stromal/peritumoral.":"Très peu de lymphocytes intraépithéliaux ; les cellules immunitaires sont principalement stromales/péritumorales.","PD-L1 Vorbefund":"Résultat PD-L1 antérieur","TPS 15 %, technisch plausibel und reproduzierbar.":"TPS 15 %, techniquement plausible et reproductible.","MMR/MSI, TMB sowie räumlicher TIL-/Stromakontext.":"MMR/MSI, TMB et contexte spatial TIL/stroma.","FFPE-Lebermetastase, Block M4.":"Métastase hépatique FFPE, bloc M4.","ca. 35 %, nach Makrodissektion ausreichend.":"env. 35 %, suffisant après macrodissection.","10 Schnitte; fokussierte IHC plus DNA-basierte Zusatzdiagnostik möglich.":"10 coupes ; IHC ciblée plus analyses supplémentaires basées sur l’ADN possibles.","Explorative TME-Marker können die Biologie illustrieren, sind aber kein validierter Ersatz für etablierte prädiktive Marker.":"Les marqueurs exploratoires du TME peuvent illustrer la biologie, mais ne remplacent pas de manière validée les marqueurs prédictifs établis.","Etablierte immunonkologische Biomarker":"Biomarqueurs immuno-oncologiques établis","TIL-/TME-Kontext":"Contexte TIL/TME","MMR-Proteine erhalten; molekular MSS. Es liegt damit kein dMMR/MSI-H-Kontext als etablierter starker ICI-Biomarker vor.":"Protéines MMR conservées ; profil moléculaire MSS. Il n’existe donc pas de contexte dMMR/MSI-H constituant un biomarqueur ICI fort et établi.","TMB niedrig (3,2 Mut/Mb). Der Wert liefert in diesem Fall keinen zusätzlichen Hinweis auf eine ausgeprägte Neoantigenlast.":"TMB faible (3,2 Mut/Mb). Dans ce cas, la valeur n’apporte pas d’indice supplémentaire d’une forte charge néoantigénique.","PD-L1 TPS 15 % wird bestätigt. Der Befund ist real, darf beim Pankreasadenokarzinom aber nicht isoliert als ausreichender Selektionsmarker für PD-1-Monotherapie interpretiert werden.":"PD-L1 TPS 15 % est confirmé. Le résultat est réel, mais dans l’adénocarcinome pancréatique il ne doit pas être interprété isolément comme marqueur de sélection suffisant pour une monothérapie anti-PD-1.","Immuninfiltrat":"Infiltrat immunitaire","CD8-positive T-Zellen sind insgesamt spärlich und überwiegend stromal/peritumoral; nur wenige erreichen Tumorzellnester.":"Les lymphocytes T CD8 positifs sont globalement rares et principalement stromaux/péritumoraux ; seuls quelques-uns atteignent les amas de cellules tumorales.","Stromakontext":"Contexte stromal","Ausgeprägte desmoplastische, fibroblastenreiche Stromazone mit immune-excluded Muster. Der Befund illustriert eine physische/biologische Barriere, ist aber kein eigenständig validierter Therapie-Selektionsassay.":"Zone stromale desmoplastique marquée, riche en fibroblastes, avec pattern immune-excluded. Ce résultat illustre une barrière physique/biologique, mais ne constitue pas un test de sélection thérapeutique validé de façon indépendante.","Ausgeprägt desmoplastisches Pankreasadenokarzinom mit wenig intratumoralen Lymphozyten.":"Adénocarcinome pancréatique fortement desmoplastique avec peu de lymphocytes intratumoraux.","IHC und DNA-basierte Analysen technisch auswertbar.":"IHC et analyses basées sur l’ADN techniquement évaluables.","Metastasiertes duktales Pankreasadenokarzinom mit bestätigter PD-L1-Expression, jedoch pMMR/MSS, niedriger TMB und deutlich immune-excluded/desmoplastischem Mikromilieu. PD-L1 allein begründet hier keine belastbare PD-1-Monotherapie-Strategie. TIL-/Stromamarker erklären die biologische Plausibilität eines 'cold/excluded' Tumors, sind aber selbst keine validierten Selektionsmarker.":"Adénocarcinome canalaire pancréatique métastatique avec expression PD-L1 confirmée, mais pMMR/MSS, TMB faible et microenvironnement nettement immune-excluded/desmoplastique. PD-L1 seul ne fournit pas ici de base robuste pour une stratégie de monothérapie anti-PD-1. Les marqueurs TIL/stromaux expliquent la plausibilité biologique d’une tumeur « froide/exclue », mais ne sont pas eux-mêmes des marqueurs de sélection validés.","Teilbefund: PD-L1 ist exprimiert, aber ohne MMR/MSI/TMB- und räumlichen TIL-Kontext bleibt die Aussage zur Checkpoint-Sensitivität unvollständig.":"Résultat partiel : PD-L1 est exprimé, mais sans contexte MMR/MSI/TMB et spatial des TIL, l’évaluation de la sensibilité aux checkpoints reste incomplète.","PD-L1 als Kontextmarker, nicht als alleinige Therapieentscheidung behandeln":"Considérer PD-L1 comme marqueur contextuel, pas comme seule décision thérapeutique","pMMR/MSS und niedrige TMB als fehlende starke ICI-Signale benennen":"Mentionner pMMR/MSS et TMB faible comme absence de signaux ICI forts","immune-excluded/desmoplastisches Muster biologisch erklären":"Expliquer biologiquement le pattern immune-excluded/desmoplastique","TME-IHC nicht als validierten Therapie-Selektionsassay verkaufen":"Ne pas présenter l’IHC du TME comme test validé de sélection thérapeutique","Falschaussage: PD-L1-Positivität beweist eine ausreichende Effektor-T-Zell-Antwort":"Affirmation erronée : la positivité PD-L1 prouve une réponse adéquate des lymphocytes T effecteurs","Optimale Lösung: PD-L1 15 % nicht isoliert interpretieren; pMMR/MSS, niedrige TMB und das immune-excluded/desmoplastische Muster integrieren. Die TME-Befunde erklären die biologische Barriere, ersetzen aber keine klinisch validierten Biomarker oder leitliniengerechte Therapieentscheidung.":"Solution optimale : ne pas interpréter PD-L1 15 % isolément ; intégrer pMMR/MSS, TMB faible et le pattern immune-excluded/desmoplastique. Les résultats du TME expliquent la barrière biologique, mais ne remplacent ni les biomarqueurs validés cliniquement ni les décisions thérapeutiques fondées sur les recommandations.","Pankreasadenokarzinom":"Adénocarcinome pancréatique","TMB-low":"TMB-low","TILs":"TIL","TME":"TME","Desmoplasie":"Desmoplasie","Immune exclusion":"Exclusion immunitaire","PD-L1 vorhanden, aber die T-Zellen kommen nicht hinein: immune-excluded Pankreasadenokarzinom":"PD-L1 présent, mais les lymphocytes T n’entrent pas : adénocarcinome pancréatique immune-excluded","Molekularpathologie / Gastroonkologie / MTB":"Pathologie moléculaire / Oncologie digestive / RCP moléculaire","PD-L1-Expression von einer tatsächlich inflamed/hot Tumormikroumgebung unterscheiden.":"Distinguer l’expression de PD-L1 d’un microenvironnement tumoral réellement inflammatoire/hot.","MMR/MSI und TMB als etabliertere immunonkologische Biomarker gegenüber explorativen TME-Markern priorisieren.":"Prioriser MMR/MSI et TMB comme biomarqueurs immuno-oncologiques plus établis par rapport aux marqueurs exploratoires du TME.","Ein immune-excluded Muster aus Morphologie, TIL-Verteilung und desmoplastischem Stroma ableiten.":"Déduire un pattern immune-excluded à partir de la morphologie, de la distribution des TIL et du stroma desmoplastique.","Verstehen, dass Stromabarriere/TIL-IHC die Biologie erklären, aber keine validierte Therapie-Selektion ersetzen.":"Comprendre que la barrière stromale/l’IHC des TIL explique la biologie mais ne remplace pas une sélection thérapeutique validée.","PD-1-Monotherapie nicht allein aus einem PD-L1-positiven Befund ableiten.":"Ne pas déduire une monothérapie anti-PD-1 d’un résultat PD-L1 positif seul.","Im Zuweiserbrief steht fett: 'PD-L1 TPS 15 % – Immuntherapie?' Auf dem HE sieht der Tumor jedoch fast wie eine Festung aus: breite desmoplastische Stromazonen, wenige T-Zellen und kaum Lymphozyten in den Tumorzellnestern. Der Fall zwingt zur Frage, ob ein exprimierter Checkpoint überhaupt etwas nützt, wenn kaum aktivierbare Effektor-T-Zellen den Tumor erreichen.":"La lettre d’adressage indique en gras : « PD-L1 TPS 15 % – immunothérapie ? ». Pourtant, en H&E, la tumeur ressemble presque à une forteresse : larges zones stromales desmoplastiques, peu de lymphocytes T et presque aucun lymphocyte dans les amas tumoraux. Le cas impose de se demander si un checkpoint exprimé est réellement utile lorsque peu de lymphocytes T effecteurs activables atteignent la tumeur.","64-jähriger Patient mit metastasiertem duktalem Pankreasadenokarzinom und Progress nach Erstlinientherapie. Ein externer PD-L1-Befund ist positiv. Im MTB soll geklärt werden, ob daraus eine belastbare PD-1-Monotherapie-Strategie folgt und welche Bedeutung das auffallend desmoplastische, lymphozytenarme Mikromilieu besitzt.":"Patient de 64 ans avec adénocarcinome canalaire pancréatique métastatique en progression après première ligne. Un résultat externe PD-L1 est positif. La RCP moléculaire doit déterminer si cela soutient une stratégie robuste de monothérapie anti-PD-1 et quelle est la signification du microenvironnement fortement desmoplastique et pauvre en lymphocytes.","Verlockender Einzelmarker":"Marqueur unique séduisant","PD-L1 TPS 15 % ist technisch reproduzierbar.":"PD-L1 TPS 15 % est techniquement reproductible.","Ein real positiver Marker kann trotzdem im falschen Entitäts-/Biologiekontext wenig prädiktive Aussage besitzen.":"Un marqueur réellement positif peut malgré tout avoir peu de valeur prédictive dans un mauvais contexte d’entité/biologie.","Morphologisches Gegenargument":"Contre-argument morphologique","Breite Desmoplasie, wenige intratumorale TILs.":"Desmoplasie étendue, peu de TIL intratumoraux.","Checkpoint-Blockade reaktiviert vorhandene Immunantwort; sie erzeugt nicht automatisch eine fehlende T-Zell-Infiltration.":"Le blocage des checkpoints réactive une réponse immunitaire existante ; il ne crée pas automatiquement une infiltration lymphocytaire T absente.","Validierte vs. explorative Ebene":"Niveau validé vs exploratoire","MMR/MSI/TMB können klinisch validierte Signale liefern; TME-IHC illustriert Mechanismen.":"MMR/MSI/TMB peuvent fournir des signaux validés cliniquement ; l’IHC du TME illustre des mécanismes.","Mechanistische Plausibilität und validierter Therapiebiomarker sind nicht dasselbe.":"La plausibilité mécanistique et un biomarqueur thérapeutique validé ne sont pas la même chose.","PDAC mit ausgeprägter Desmoplasie und wenig intratumoralen Lymphozyten.":"PDAC avec desmoplasie marquée et peu de lymphocytes intratumoraux.","TPS 15 %, reproduzierbar.":"TPS 15 %, reproductible.","Metastasenblock mit ca. 35 % Tumoranteil; fokussierte Zusatzdiagnostik möglich.":"Bloc métastatique avec env. 35 % de tumeur ; analyses supplémentaires ciblées possibles.","Nur zehn Schnitte: explorative Zusatz-IHC muss einen klaren didaktischen/biologischen Nutzen haben.":"Seulement dix coupes : une IHC exploratoire supplémentaire doit avoir une valeur pédagogique/biologique claire.","TME-/Stroma-IHC ist in diesem Fall bewusst eine mechanistische Zusatzebene, kein validierter Companion-Diagnostic-Ersatz.":"L’IHC TME/stromale constitue volontairement ici un niveau mécanistique supplémentaire, et non un substitut validé à un companion diagnostic.","MMR/MSI/TMB müssen gegenüber breit gestreuter Immun-IHC priorisiert werden, wenn die Therapiefrage im Vordergrund steht.":"MMR/MSI/TMB doivent être prioritaires par rapport à une IHC immunitaire large lorsque la question thérapeutique est centrale.","Was bedeutet PD-L1 TPS 15 % in diesem PDAC am ehesten?":"Que signifie le plus probablement PD-L1 TPS 15 % dans ce PDAC ?","Der Befund ist biologisch real, reicht aber ohne entitätsspezifisch validierten Kontext nicht für eine belastbare PD-1-Monotherapie-Entscheidung.":"Le résultat est biologiquement réel, mais sans contexte validé spécifique de l’entité, il ne suffit pas pour une décision robuste de monothérapie anti-PD-1.","Jede PD-L1-Positivität ist tumoragnostisch eine ICI-Indikation.":"Toute positivité PD-L1 constitue une indication tumor-agnostique d’ICI.","PD-L1 kann bei PDAC technisch nicht gemessen werden.":"PD-L1 ne peut techniquement pas être mesuré dans le PDAC.","PD-L1 15 % beweist automatisch TMB-high.":"PD-L1 15 % prouve automatiquement un TMB-high.","PD-L1-Expression ist nicht tumoragnostisch gleichbedeutend mit validierter Checkpoint-Sensitivität.":"L’expression de PD-L1 n’est pas synonyme, de manière tumor-agnostique, d’une sensibilité validée aux checkpoints.","Wodurch ist ein immune-excluded Muster am besten charakterisiert?":"Qu’est-ce qui caractérise le mieux un pattern immune-excluded ?","Immunzellen sind vorhanden, bleiben aber überwiegend im Stroma/peritumoral und erreichen Tumorzellnester nur schlecht.":"Les cellules immunitaires sont présentes, mais restent principalement dans le stroma/en périphérie tumorale et atteignent peu les amas de cellules tumorales.","Dichtes intraepitheliales CD8-Infiltrat in allen Tumorarealen.":"Infiltrat CD8 intraépithélial dense dans toutes les zones tumorales.","Jeder immune-excluded Tumor ist automatisch MSI-H.":"Toute tumeur immune-excluded est automatiquement MSI-H.","PD-L1-Expression allein definiert immune exclusion.":"L’expression de PD-L1 seule définit l’exclusion immunitaire.","Die räumliche Verteilung der Immunzellen ist zentral; 'vorhanden' ist nicht gleich 'im Tumor wirksam'.":"La distribution spatiale des cellules immunitaires est centrale ; « présentes » ne signifie pas « efficaces dans la tumeur ».","Welche Zusatzdiagnostik sollte für die klinische IO-Frage priorisiert werden?":"Quels examens supplémentaires doivent être prioritaires pour la question clinique d’IO ?","MMR/MSI und ggf. TMB als etabliertere Biomarker; TME-IHC nur ergänzend/mechanistisch.":"MMR/MSI et, le cas échéant, TMB comme biomarqueurs plus établis ; IHC du TME uniquement en complément/mécanistique.","Nur CAF-/Stroma-IHC, da diese allein die Therapie festlegt.":"Uniquement IHC CAF/stromale, puisque celle-ci détermine à elle seule le traitement.","PD-L1 mehrfach wiederholen, bis ein höherer Wert entsteht.":"Répéter PD-L1 jusqu’à obtenir une valeur plus élevée.","Keine weitere Kontextdiagnostik; TPS 15 % reicht.":"Aucun autre examen contextuel ; TPS 15 % suffit.","Explorative TME-Marker dürfen validierte Biomarker nicht ersetzen.":"Les marqueurs exploratoires du TME ne doivent pas remplacer des biomarqueurs validés.","Wie darf der desmoplastische/TIL-arme Befund im MTB verwendet werden?":"Comment le résultat desmoplastique/pauvre en TIL peut-il être utilisé en RCP moléculaire ?","Als biologische Erklärung für geringe Checkpoint-Sensitivität bzw. immune exclusion – nicht als eigenständiger validierter Therapieausschlusstest.":"Comme explication biologique d’une faible sensibilité aux checkpoints ou d’une exclusion immunitaire – pas comme test validé indépendant d’exclusion thérapeutique.","Als absolute Kontraindikation gegen jede Immuntherapie.":"Comme contre-indication absolue à toute immunothérapie.","Als Beweis für einen zugelassenen CAF-Target-Standard.":"Comme preuve d’un standard approuvé ciblant les CAF.","Morphologie und TIL-Verteilung sind grundsätzlich bedeutungslos.":"La morphologie et la distribution des TIL sont fondamentalement sans signification.","Der TME-Befund ist mechanistisch stark, klinisch aber nicht als alleiniger Selektionsassay validiert.":"Le résultat TME est mécanistiquement fort, mais n’est pas validé cliniquement comme test de sélection unique.","Formulieren Sie die MTB-Kernaussage so, dass PD-L1, pMMR/MSS/TMB und das immune-excluded/desmoplastische Muster hierarchisch korrekt integriert werden, ohne explorative TME-Befunde zu einem Companion Diagnostic aufzuwerten.":"Formulez la conclusion centrale de la RCP moléculaire en intégrant PD-L1, pMMR/MSS/TMB et le pattern immune-excluded/desmoplastique selon la hiérarchie correcte, sans élever les résultats exploratoires du TME au rang de companion diagnostic.","PD-L1 TPS 15 % als realen, aber nicht ausreichenden Einzelbefund anerkennen.":"Reconnaître PD-L1 TPS 15 % comme résultat réel mais insuffisant à lui seul.","MMR/MSI prüfen: pMMR/MSS.":"Évaluer MMR/MSI : pMMR/MSS.","TMB als niedrig einordnen.":"Classer le TMB comme faible.","Räumlich spärliches CD8-Infiltrat und Desmoplasie als immune-excluded TME beschreiben.":"Décrire l’infiltration CD8 spatialement rare et la desmoplasie comme un TME immune-excluded.","PD-1-Monotherapie nicht allein aus PD-L1 ableiten.":"Ne pas déduire une monothérapie anti-PD-1 de PD-L1 seul.","TME-IHC als mechanistische Zusatzinformation, nicht als validierten Selektionsmarker berichten.":"Rapporter l’IHC du TME comme information mécanistique supplémentaire, pas comme marqueur de sélection validé.","MMR-IHC plus MSI-Test und TMB aus einem validierten breiteren Panel, sofern Material und TAT dies erlauben.":"IHC MMR plus test MSI et TMB à partir d’un panel validé plus large, si le matériel et le TAT le permettent.","Auf zusätzliche Stroma-IHC verzichten, wenn die Morphologie die immune exclusion bereits überzeugend zeigt und die klinisch validierten Biomarker priorisiert werden.":"Omettre une IHC stromale supplémentaire si la morphologie démontre déjà de façon convaincante l’exclusion immunitaire et que les biomarqueurs validés cliniquement sont prioritaires.","PD-L1 = ICI":"PD-L1 = ICI","Die prädiktive Bedeutung von PD-L1 ist entitäts- und therapiespezifisch.":"La valeur prédictive de PD-L1 dépend de l’entité et du traitement.","CAF-IHC als Companion Diagnostic":"IHC CAF comme companion diagnostic","Mechanistische TME-Marker sind hier nicht als eigenständige Therapie-Selektion validiert.":"Les marqueurs mécanistiques du TME ne sont pas ici validés comme outils indépendants de sélection thérapeutique.","TIL-arm = absolute Resistenz":"Peu de TIL = résistance absolue","Biologische Wahrscheinlichkeit ist keine absolute patientenindividuelle Ausschlussregel.":"Une probabilité biologique ne constitue pas une règle absolue d’exclusion individuelle.","TMB/MSI ignorieren":"Ignorer TMB/MSI","Damit würden etabliertere immunonkologische Biomarker ausgelassen.":"Cela omettrait des biomarqueurs immuno-oncologiques plus établis.","Der 'positive' Marker sitzt auf einem biologisch kalten Tumor":"Le marqueur « positif » se trouve sur une tumeur biologiquement froide","PD-L1 TPS 15 % wird bestätigt – gleichzeitig ist der Tumor pMMR/MSS, TMB-low und zeigt nur wenige CD8-T-Zellen, die überwiegend im desmoplastischen Stroma stecken bleiben. Der vermeintlich positive Einzelmarker kippt dadurch nicht ins 'falsch', sondern bekommt die richtige Hierarchie: biologischer Kontextmarker statt Therapie-Schalter.":"PD-L1 TPS 15 % est confirmé – parallèlement, la tumeur est pMMR/MSS, TMB-low et ne montre que peu de lymphocytes T CD8, largement retenus dans le stroma desmoplastique. Le marqueur unique apparemment positif ne devient donc pas « faux » ; il prend sa juste place dans la hiérarchie : marqueur de contexte biologique plutôt qu’interrupteur thérapeutique.","Der Fall trennt Expression eines Checkpoints von einer vorhandenen effektiven Antitumor-Immunantwort und zeigt, warum räumliche TME-Biologie die Interpretation verändert.":"Le cas distingue l’expression d’un checkpoint d’une réponse immunitaire antitumorale efficace existante et montre pourquoi la biologie spatiale du TME modifie l’interprétation.","PD-L1 im richtigen TME-Kontext":"PD-L1 dans le bon contexte TME","PD-L1 TPS 15 %, pMMR/MSS, TMB 3,2 Mut/Mb, CD8-arm/immune-excluded mit ausgeprägter Desmoplasie. Kein belastbarer Grund für PD-1-Monotherapie allein aus PD-L1; TME-Befund mechanistisch, nicht als Companion Diagnostic.":"PD-L1 TPS 15 %, pMMR/MSS, TMB 3,2 Mut/Mb, pauvre en CD8/immune-excluded avec desmoplasie marquée. Pas de base robuste pour une monothérapie anti-PD-1 à partir de PD-L1 seul ; résultat TME mécanistique, pas un companion diagnostic.","Validierte Biomarker und TME-Biologie korrekt hierarchisiert.":"Biomarqueurs validés et biologie du TME correctement hiérarchisés.","Cold erkannt, Biomarkerhierarchie unklar":"Pattern froid reconnu, hiérarchie des biomarqueurs incertaine","Desmoplasie und wenige TILs werden beschrieben, MMR/MSI/TMB aber nicht integriert.":"La desmoplasie et le faible nombre de TIL sont décrits, mais MMR/MSI/TMB ne sont pas intégrés.","Biologisch plausibel, klinisch unvollständig.":"Biologiquement plausible, cliniquement incomplet.","PD-L1 als universeller IO-Schalter":"PD-L1 comme interrupteur IO universel","TPS 15 % wird als ausreichende tumoragnostische ICI-Indikation interpretiert.":"TPS 15 % est interprété comme une indication ICI tumor-agnostique suffisante.","Entitätsspezifische Biomarkerlogik übergangen.":"La logique des biomarqueurs spécifique de l’entité est ignorée.","pMMR/MSS und TMB-low bestätigt":"pMMR/MSS et TMB-low confirmés","Therapieplanung auf etablierte PDAC-Strategien bzw. passende Studien fokussieren; PD-L1 nicht isoliert übergewichten.":"Centrer la planification thérapeutique sur les stratégies établies pour le PDAC ou des essais appropriés ; ne pas surpondérer PD-L1 isolément.","Der Fall bleibt evidenzbasiert statt biomarkergetrieben spekulativ.":"Le cas reste fondé sur les preuves plutôt que spéculatif et piloté par un biomarqueur.","TME-/Stromaforschung diskutiert":"Recherche TME/stromale discutée","Studienoptionen klar als experimentell kennzeichnen.":"Qualifier clairement les options d’essais d’expérimentales.","Mechanistische Hypothesen werden von Routineempfehlungen getrennt.":"Les hypothèses mécanistiques sont séparées des recommandations de routine.","PD-L1-Expression ist nicht gleichbedeutend mit vorhandener effektiver T-Zell-Antwort.":"L’expression de PD-L1 n’est pas synonyme d’une réponse efficace des lymphocytes T déjà présente.","Immune exclusion beschreibt die räumliche Barriere zwischen Immunzellen und Tumorzellnestern.":"L’exclusion immunitaire décrit la barrière spatiale entre les cellules immunitaires et les amas de cellules tumorales.","pMMR/MSS und niedrige TMB liefern hier keine starken etablierten Immunogenitätssignale.":"pMMR/MSS et TMB faible n’apportent ici aucun signal fort et établi d’immunogénicité.","TME-/CAF-/TIL-Marker können Mechanismen erklären, sind aber nicht automatisch validierte Therapie-Selektionstests.":"Les marqueurs TME/CAF/TIL peuvent expliquer des mécanismes, mais ne sont pas automatiquement des tests validés de sélection thérapeutique.","Der klinische Wert eines Biomarkers hängt von Entität, Therapie und Evidenzniveau ab.":"La valeur clinique d’un biomarqueur dépend de l’entité, du traitement et du niveau de preuve.","PD-L1 TPS 15 % ist kein ausreichender Monotherapie-Schalter. Der Tumor ist pMMR/MSS und TMB-low; morphologisch/IHC zeigt sich ein deutlich immune-excluded, desmoplastisches TME. Das erklärt biologisch eine geringe Wahrscheinlichkeit effektiver Checkpoint-Reaktivierung, darf aber nicht als absoluter Ausschlusstest oder validierter Companion Diagnostic formuliert werden.":"PD-L1 TPS 15 % n’est pas un interrupteur suffisant pour une monothérapie. La tumeur est pMMR/MSS et TMB-low ; morphologiquement/IHC, le TME est clairement immune-excluded et desmoplastique. Cela explique biologiquement une faible probabilité de réactivation efficace des checkpoints, mais ne doit pas être formulé comme test absolu d’exclusion ni comme companion diagnostic validé.","PD-L1 nicht überinterpretiert":"PD-L1 non surinterprété","MMR/MSI/TMB priorisiert":"MMR/MSI/TMB prioritaires","immune-excluded räumlich verstanden":"immune-excluded compris spatialement","TME-Marker als explorativ begrenzt":"Marqueurs TME limités au champ exploratoire","Warum kann PD-L1 exprimiert sein, obwohl kaum T-Zellen im Tumor sitzen?":"Pourquoi PD-L1 peut-il être exprimé alors qu’il y a très peu de lymphocytes T dans la tumeur ?","Was unterscheidet immune-desert von immune-excluded?":"Qu’est-ce qui distingue immune-desert d’immune-excluded ?","Welche TME-Marker sind mechanistisch interessant, aber nicht routineprädiktiv validiert?":"Quels marqueurs du TME sont intéressants sur le plan mécanistique mais non validés comme prédictifs en routine ?","PD-L1 positiv, aber pMMR/MSS/TMB-low + immune-excluded":"PD-L1 positif, mais pMMR/MSS/TMB-low + immune-excluded","Checkpoint-Expression braucht einen validierten Entitäts- und Immunitätskontext":"L’expression d’un checkpoint nécessite un contexte validé d’entité et d’immunité","PD-L1 → MMR/MSI/TMB → räumliche TILs → TME-Limitation":"PD-L1 → MMR/MSI/TMB → TIL spatiaux → limite du TME","PD-L1 positiv, aber niedrige TMB und kein Immuninfiltrat → PD-L1 nicht überinterpretieren":"PD-L1 positif, mais TMB faible et absence d’infiltrat immunitaire → ne pas surinterpréter PD-L1","PD-L1 positiv, aber niedrige TMB u…":"PD-L1 positif, mais TMB faible et…","61-jährige Patientin mit metastasiertem kolorektalem Adenokarzinom nach Progress unter mehreren Standardtherapien. In einer Metastasenbiopsie wird PD-L1 CPS 25 berichtet.":"Patiente de 61 ans atteinte d’un adénocarcinome colorectal métastatique après progression sous plusieurs traitements standards. Une biopsie métastatique rapporte PD-L1 CPS 25.","Kann die hohe PD-L1-Expression trotz fehlender klassischer Immunogenitätsmarker eine PD-1-Monotherapie begründen?":"Une forte expression de PD-L1 peut-elle justifier une monothérapie anti-PD-1 malgré l’absence de marqueurs classiques d’immunogénicité ?","Es wird nach einer weiteren systemischen Option gesucht; Studienzugang wird parallel geprüft.":"Une nouvelle option systémique est recherchée ; l’accès à un essai est évalué en parallèle.","Primarius":"Tumeur primitive","Linksseitiges Kolonkarzinom, inzwischen hepatisch und pulmonal metastasiert.":"Cancer du côlon gauche, désormais métastatique au foie et au poumon.","Fluoropyrimidin/Oxaliplatin, Irinotecan-basierte Therapie und weitere leitliniengerechte Linien.":"Fluoropyrimidine/oxaliplatine, traitement à base d’irinotécan et autres lignes conformes aux recommandations.","Außenbefund":"Rapport externe","PD-L1 CPS 25 wird auf dem Deckblatt fett hervorgehoben.":"PD-L1 CPS 25 est mis en évidence en gras sur la page de garde.","Ein 'positiver' Marker wird aus einer anderen Tumorentität in den CRC-Kontext übertragen, obwohl die prädiktive Hierarchie dort anders ist.":"Un marqueur « positif » est transposé depuis une autre entité tumorale au contexte CRC alors que la hiérarchie prédictive y est différente.","Kolorektales Adenokarzinom, mäßig differenziert; keine ausgeprägt lymphozytenreiche Morphologie.":"Adénocarcinome colorectal moyennement différencié ; pas de morphologie fortement riche en lymphocytes.","CPS 25, überwiegend durch PD-L1-positive Immunzellen an Nekrose-/Stromagrenzen mitgetragen.":"CPS 25, principalement porté par des cellules immunitaires PD-L1 positives aux interfaces nécrose/stroma.","Nur spärliche intratumorale CD8-positive Lymphozyten.":"Seulement de rares lymphocytes CD8 positifs intratumoraux.","MMR/MSI und TMB als entitätsspezifisch relevanter immunonkologischer Kontext.":"MMR/MSI et TMB comme contexte immuno-oncologique pertinent pour l’entité.","FFPE-Lebermetastase, Block H2.":"Métastase hépatique FFPE, bloc H2.","ca. 50 %, gut geeignet.":"env. 50 %, bien adapté.","PD-L1 ist technisch messbar, seine prädiktive Bedeutung ist aber entitäts- und therapiespezifisch; ein numerisch hoher Score ist nicht automatisch ein universeller IO-Biomarker.":"PD-L1 est techniquement mesurable, mais sa valeur prédictive dépend de l’entité et du traitement ; un score numériquement élevé n’est pas automatiquement un biomarqueur IO universel.","Immunonkologischer Kontext":"Contexte immuno-oncologique","Erhaltene nukleäre Expression von MLH1, PMS2, MSH2 und MSH6: pMMR.":"Expression nucléaire conservée de MLH1, PMS2, MSH2 et MSH6 : pMMR.","MSS. Damit fehlt der für mCRC etablierte dMMR/MSI-H-Immuntherapiekontext.":"MSS. Le contexte dMMR/MSI-H établi pour l’immunothérapie dans le mCRC est donc absent.","TMB niedrig (4,0 Mut/Mb).":"TMB faible (4,0 Mut/Mb).","PD-L1 CPS 25 bestätigt. Die Expression ist biologisch real, aber im pMMR/MSS-mCRC kein Ersatz für einen validierten MSI/dMMR-basierten Selektionsmarker.":"PD-L1 CPS 25 confirmé. L’expression est biologiquement réelle, mais dans le mCRC pMMR/MSS elle ne remplace pas un marqueur de sélection validé basé sur MSI/dMMR.","TIL-Kontext":"Contexte TIL","Nur wenige intratumorale CD8-positive T-Zellen; kein ausgeprägt inflamed/hot pattern.":"Seulement quelques lymphocytes T CD8 positifs intratumoraux ; pas de pattern inflammatoire/hot marqué.","Kernausgangslage":"Situation de départ centrale","PD-L1 CPS 25 bei mCRC ohne morphologisch ausgeprägtes Immuninfiltrat.":"PD-L1 CPS 25 dans un mCRC sans infiltrat immunitaire morphologiquement marqué.","MMR-IHC, MSI und DNA-basierte Zusatzanalysen technisch verwertbar.":"IHC MMR, MSI et analyses supplémentaires basées sur l’ADN techniquement exploitables.","Metastasiertes CRC mit realer PD-L1-Expression, aber pMMR/MSS, niedriger TMB und spärlichem intratumoralem T-Zell-Infiltrat. PD-L1-Positivität allein begründet in diesem Kontext keine etablierte PD-1-Monotherapie. Für mCRC besitzt dMMR/MSI-H eine deutlich stärkere und validierte prädiktive Rolle; experimentelle Kombinationen bei pMMR/MSS gehören in einen Studien-/Evidenzkontext.":"CRC métastatique avec expression réelle de PD-L1, mais pMMR/MSS, TMB faible et faible infiltrat intratumoral de lymphocytes T. La positivité PD-L1 seule ne justifie pas ici une monothérapie anti-PD-1 établie. Dans le mCRC, dMMR/MSI-H possède un rôle prédictif nettement plus fort et validé ; les combinaisons expérimentales dans le pMMR/MSS relèvent d’un contexte d’essai/de preuve.","Teilbefund: PD-L1 ist hoch, aber ohne MMR/MSI-Kontext ist die Übertragbarkeit auf eine Therapieentscheidung nicht belastbar.":"Résultat partiel : PD-L1 est élevé, mais sans contexte MMR/MSI sa transposition à une décision thérapeutique n’est pas robuste.","PD-L1-Bedeutung entitätsspezifisch einordnen":"Interpréter la signification de PD-L1 de manière spécifique à l’entité","pMMR/MSS als entscheidenden Gegenbefund zur einfachen PD-L1-Logik benennen":"Mentionner pMMR/MSS comme résultat décisif contre une logique simple fondée sur PD-L1","niedrige TMB und spärliches Infiltrat als zusätzliche Kontextmarker integrieren":"Intégrer TMB faible et infiltrat rare comme marqueurs contextuels supplémentaires","pMMR/MSS-IO-Kombinationen nicht mit etablierter Monotherapie gleichsetzen":"Ne pas assimiler les combinaisons IO en pMMR/MSS à une monothérapie établie","Falschaussage: Hoher PD-L1-Score ist tumoragnostisch immer prädiktiv":"Affirmation erronée : un score PD-L1 élevé est toujours prédictif de manière tumor-agnostique","Optimale Lösung: PD-L1 CPS 25 ist kein universeller IO-Schalter. Im pMMR/MSS-mCRC mit niedriger TMB und wenig TILs darf der Score die entitätsspezifisch validierte Biomarkerhierarchie nicht überstimmen; experimentelle Strategien gehören in Studien.":"Solution optimale : PD-L1 CPS 25 n’est pas un interrupteur IO universel. Dans un mCRC pMMR/MSS avec TMB faible et peu de TIL, le score ne doit pas supplanter la hiérarchie de biomarqueurs validée pour l’entité ; les stratégies expérimentales relèvent d’essais.","TIL-low":"TIL-low","Immuntherapie":"Immunothérapie","Biomarkerhierarchie":"Hiérarchie des biomarqueurs","PD-L1 CPS 25 und trotzdem kein ICI-Biomarker: MSS-mCRC als Überinterpretationsfalle":"PD-L1 CPS 25 et pourtant pas de biomarqueur ICI : mCRC MSS comme piège de surinterprétation","PD-L1 als entitätsabhängigen und nicht tumoragnostischen Biomarker verstehen.":"Comprendre PD-L1 comme biomarqueur dépendant de l’entité et non tumor-agnostique.","Beim mCRC dMMR/MSI-H gegenüber PD-L1 als prädiktiv stärker validierten IO-Kontext priorisieren.":"Dans le mCRC, prioriser dMMR/MSI-H par rapport à PD-L1 comme contexte IO prédictif mieux validé.","pMMR/MSS, niedrige TMB und TIL-Armut als konsistente Gegenkonstellation zu einer simplen PD-L1-Logik integrieren.":"Intégrer pMMR/MSS, TMB faible et rareté des TIL comme configuration cohérente allant à l’encontre d’une logique simple fondée sur PD-L1.","PD-L1-Score und zelluläre Quelle/Spatial Context nicht mit universeller Therapieindikation verwechseln.":"Ne pas confondre score PD-L1 et source cellulaire/contexte spatial avec une indication thérapeutique universelle.","Experimentelle ICI-Kombinationen im pMMR/MSS-mCRC von etablierter Monotherapie unterscheiden.":"Distinguer les combinaisons ICI expérimentales dans le mCRC pMMR/MSS d’une monothérapie établie.","Der Außenbefund klingt spektakulär: PD-L1 CPS 25. Im Tumorboard kommt sofort die Frage nach Pembrolizumab. Doch die Histologie ist lymphozytenarm, die MMR-Proteine sind erhalten und der Tumor ist MSS. Der Fall ist ein Lehrstück dafür, dass derselbe Biomarkerwert je nach Tumorentität völlig unterschiedliche klinische Bedeutung haben kann.":"Le rapport externe semble spectaculaire : PD-L1 CPS 25. En RCP, le pembrolizumab est immédiatement évoqué. Mais l’histologie est pauvre en lymphocytes, les protéines MMR sont conservées et la tumeur est MSS. Ce cas montre que la même valeur de biomarqueur peut avoir une signification clinique totalement différente selon l’entité tumorale.","61-jährige Patientin mit mehrfach vorbehandeltem metastasiertem kolorektalem Adenokarzinom. Eine Metastasenbiopsie zeigt PD-L1 CPS 25. Gesucht ist eine evidenzbasierte Einordnung, ob dieser Wert im pMMR/MSS-mCRC eine etablierte PD-1-Monotherapie begründet oder ob die entitätsspezifische MSI/dMMR-Hierarchie Vorrang hat.":"Patiente de 61 ans avec adénocarcinome colorectal métastatique lourdement prétraité. Une biopsie métastatique montre PD-L1 CPS 25. Il faut évaluer sur la base des preuves si cette valeur justifie une monothérapie anti-PD-1 établie dans le mCRC pMMR/MSS ou si la hiérarchie MSI/dMMR spécifique de l’entité doit primer.","Hohe Zahl, falsche Abkürzung":"Chiffre élevé, mauvais raccourci","PD-L1 CPS 25 wird als 'positiv' hervorgehoben.":"PD-L1 CPS 25 est mis en avant comme « positif ».","Ein numerisch hoher Wert ist nur dann prädiktiv, wenn Assay, Scoring, Entität und Therapie dafür validiert sind.":"Une valeur numériquement élevée n’est prédictive que si le test, le scoring, l’entité et le traitement sont validés pour cet usage.","CRC-spezifische Hierarchie":"Hiérarchie spécifique au CRC","MMR/MSI ist für die IO-Selektion beim mCRC zentral.":"MMR/MSI est central pour la sélection IO dans le mCRC.","Biomarker dürfen nicht entitätsübergreifend ohne Evidenz transferiert werden.":"Les biomarqueurs ne doivent pas être transposés entre entités sans preuve.","Biologisches Gesamtbild":"Tableau biologique global","TMB-low und TIL-arm.":"TMB-low et pauvre en TIL.","Mehrere unabhängige Kontextsignale sprechen gegen die einfache Annahme eines hoch immunogenen Tumors.":"Plusieurs signaux contextuels indépendants s’opposent à l’hypothèse simple d’une tumeur hautement immunogène.","PD-L1 Außenbefund":"Résultat externe PD-L1","CPS 25, überwiegend an Tumor-/Stromagrenzen und Immunzellen.":"CPS 25, principalement aux interfaces tumeur/stroma et sur les cellules immunitaires.","Keine ausgeprägt lymphozytenreiche CRC-Morphologie.":"Pas de morphologie CRC fortement riche en lymphocytes.","Lebermetastase mit ca. 50 % Tumoranteil.":"Métastase hépatique avec env. 50 % de contenu tumoral.","MMR-IHC und MSI-Testung sind mit wenig Material möglich und beantworten die entscheidende CRC-spezifische Frage direkter als wiederholte PD-L1-IHC.":"L’IHC MMR et le test MSI nécessitent peu de matériel et répondent plus directement à la question décisive spécifique au CRC que la répétition de l’IHC PD-L1.","TMB ist additive Kontextinformation und darf MSI/dMMR nicht ersetzen.":"Le TMB est une information contextuelle complémentaire et ne doit pas remplacer MSI/dMMR.","Breite Zusatzdiagnostik soll nicht nur deshalb erfolgen, weil ein einzelner PD-L1-Score klinisch verlockend wirkt.":"Des analyses supplémentaires larges ne doivent pas être réalisées uniquement parce qu’un score PD-L1 isolé paraît cliniquement séduisant.","Wie ist PD-L1 CPS 25 im mCRC grundsätzlich zu behandeln?":"Comment faut-il généralement interpréter PD-L1 CPS 25 dans le mCRC ?","Als entitätsspezifisch zu interpretierender Kontextbefund; nicht als universeller tumoragnostischer ICI-Schalter.":"Comme résultat contextuel à interpréter selon l’entité ; pas comme interrupteur ICI universel tumor-agnostique.","CPS ≥10 ist bei jeder soliden Tumorentität automatisch prädiktiv.":"CPS ≥10 est automatiquement prédictif dans toute entité de tumeur solide.","PD-L1-IHC ist im CRC technisch grundsätzlich ungültig.":"L’IHC PD-L1 est techniquement invalide dans le CRC par principe.","PD-L1 CPS 25 beweist MSI-H.":"PD-L1 CPS 25 prouve MSI-H.","Prädiktive Biomarker funktionieren nur in validiertem Entitäts-/Therapiekontext.":"Les biomarqueurs prédictifs ne fonctionnent que dans un contexte entité/traitement validé.","Welcher Befund besitzt beim mCRC die klarere etablierte IO-Relevanz?":"Quel résultat possède la pertinence IO établie la plus claire dans le mCRC ?","dMMR/MSI-H.":"dMMR/MSI-H.","PD-L1 CPS allein.":"PD-L1 CPS seul.","TIL-Zahl allein.":"Nombre de TIL seul.","Tumornekrose allein.":"Nécrose tumorale seule.","dMMR/MSI-H ist der etablierte zentrale Immuntherapie-Biomarkerkontext im mCRC.":"dMMR/MSI-H constitue le contexte central établi de biomarqueurs d’immunothérapie dans le mCRC.","PD-L1 CPS 25, aber pMMR/MSS und TMB 4 Mut/Mb. Was ist die sauberste Aussage?":"PD-L1 CPS 25, mais pMMR/MSS et TMB 4 mut/Mb. Quelle est la formulation la plus appropriée ?","PD-L1 überstimmt pMMR/MSS nicht; daraus folgt keine etablierte PD-1-Monotherapie. Studienstrategien müssen als experimentell gekennzeichnet werden.":"PD-L1 ne supplante pas le contexte pMMR/MSS ; cela n’établit pas d’indication à une monothérapie anti-PD-1. Les stratégies d’essai doivent être qualifiées d’expérimentales.","Hoher CPS macht die Monotherapie unabhängig von MSI zum Standard.":"Un CPS élevé fait de la monothérapie un standard indépendamment du MSI.","Ein pMMR/MSS-CRC kann in keiner Studie jemals auf Immuntherapie reagieren.":"Un CRC pMMR/MSS ne peut jamais répondre à l’immunothérapie dans aucun essai.","CPS 25 definiert automatisch TMB-high.":"Un CPS de 25 définit automatiquement un TMB élevé.","Fehlende etablierte Monotherapie-Indikation ist nicht gleichbedeutend mit biologisch unmöglicher Aktivität in Studienkombinationen.":"L’absence d’indication établie en monothérapie ne signifie pas qu’une activité dans des associations expérimentales soit biologiquement impossible.","Warum ist es hilfreich zu wissen, woher der CPS stammt?":"Pourquoi est-il utile de savoir d’où provient le CPS ?","PD-L1-positive Immunzellen an Stromagrenzen können den Score erhöhen, ohne ein dichtes intratumorales Effektor-T-Zell-Infiltrat zu belegen.":"Des cellules immunitaires PD-L1 positives aux interfaces stromales peuvent augmenter le score sans démontrer un infiltrat intratumoral dense de lymphocytes T effecteurs.","Immunzell-PD-L1 beweist immer bessere ICI-Wirkung.":"Le PD-L1 des cellules immunitaires prouve toujours une meilleure efficacité des ICI.","CPS darf Immunzellen niemals berücksichtigen.":"Le CPS ne doit jamais inclure les cellules immunitaires.","Zelluläre Quelle und räumlicher Kontext sind grundsätzlich irrelevant.":"L’origine cellulaire et le contexte spatial sont fondamentalement sans importance.","Score und räumliche Immunbiologie sind unterschiedliche Informationsebenen.":"Le score et la biologie immunitaire spatiale constituent des niveaux d’information différents.","Entscheiden Sie, wie PD-L1 CPS 25 im pMMR/MSS-mCRC berichtet und im MTB gewichtet wird, ohne den Befund zu ignorieren oder ihn entitätsfremd zur etablierten ICI-Indikation aufzuwerten.":"Décidez comment rapporter et pondérer un PD-L1 CPS 25 dans le MTB d’un mCRC pMMR/MSS, sans ignorer le résultat ni l’élever, hors de son contexte validé propre à l’entité, au rang d’indication établie d’ICI.","PD-L1 CPS 25 als technisch realen Befund anerkennen.":"Reconnaître le PD-L1 CPS 25 comme un résultat techniquement réel.","MMR-IHC und MSI prüfen: pMMR/MSS.":"Vérifier l’IHC MMR et le MSI : pMMR/MSS.","TMB als niedrig und TIL-Infiltrat als spärlich einordnen.":"Classer le TMB comme faible et l’infiltrat de TIL comme peu abondant.","PD-L1 im CRC nicht als tumoragnostischen Therapie-Schalter formulieren.":"Ne pas présenter le PD-L1 dans le CRC comme un interrupteur thérapeutique tumor-agnostique.","Keine etablierte PD-1-Monotherapie aus PD-L1 allein ableiten.":"Ne pas déduire une indication établie de monothérapie anti-PD-1 du seul PD-L1.","Experimentelle pMMR/MSS-IO-Kombinationen ausschließlich als Studienoption/Evidenzentwicklung kennzeichnen.":"Qualifier les associations d’immunothérapie expérimentales en pMMR/MSS uniquement comme options d’essai/données en évolution.","MMR-IHC plus MSI-Test; TMB nur ergänzend, wenn bereits aus validiertem Panel verfügbar.":"IHC MMR plus test MSI ; TMB uniquement en complément s’il est déjà disponible à partir d’un panel validé.","Bei klarem pMMR/MSS kann auf wiederholte PD-L1-IHC verzichtet werden, wenn sie die klinische Entscheidung nicht verändert.":"En cas de pMMR/MSS clairement établi, une répétition de l’IHC PD-L1 peut être omise si elle ne modifie pas la décision clinique.","CPS aus anderer Entität übertragen":"Transposer le CPS d’une autre entité tumorale","PD-L1-Cutoffs sind nicht tumoragnostisch austauschbar.":"Les seuils de PD-L1 ne sont pas interchangeables entre les différents types tumoraux.","PD-L1 ignorieren":"Ignorer le PD-L1","Der Befund ist biologisch real und kann Forschung/Studienkontext informieren; er ist nur nicht der etablierte Selektionsmarker.":"Le résultat est biologiquement réel et peut informer le contexte de recherche/d’essai ; il ne constitue simplement pas le biomarqueur de sélection établi.","pMMR/MSS = absolute Immunresistenz":"pMMR/MSS = résistance immunitaire absolue","Das wäre zu absolut; Studienkombinationen werden untersucht.":"Cette affirmation serait trop absolue ; des associations expérimentales sont à l’étude.","TMB ersetzt MSI":"Le TMB remplace le MSI","TMB und MSI sind verwandte, aber nicht austauschbare Biomarker.":"Le TMB et le MSI sont des biomarqueurs liés, mais non interchangeables.","Die 25 ist echt – aber klinisch nicht der Hauptmarker":"Le 25 est réel — mais cliniquement, ce n’est pas le marqueur principal","PD-L1 CPS 25 wird bestätigt. Gleichzeitig zeigen MMR-IHC und MSI-Testung pMMR/MSS, TMB liegt bei 4 Mut/Mb und CD8-T-Zellen sind spärlich. Der Twist ist nicht, dass PD-L1 'falsch' war, sondern dass ein realer positiver Befund außerhalb seines validierten Entitätskontexts therapeutisch viel weniger trägt.":"Le PD-L1 CPS 25 est confirmé. Parallèlement, l’IHC MMR et le test MSI montrent un statut pMMR/MSS, le TMB est de 4 mut/Mb et les lymphocytes T CD8 sont peu nombreux. Le twist n’est pas que le PD-L1 était «faux», mais qu’un résultat réellement positif a beaucoup moins de poids thérapeutique hors de son contexte validé propre à l’entité.","So wird die zentrale Präzisionsonkologie-Kompetenz trainiert: Biomarker werden nicht nach Positiv/Negativ, sondern nach Evidenz, Entität und Therapiehierarchie interpretiert.":"Cela entraîne une compétence centrale de l’oncologie de précision : les biomarqueurs ne sont pas interprétés simplement comme positifs/négatifs, mais selon le niveau de preuve, l’entité et la hiérarchie thérapeutique.","PD-L1 entitätsspezifisch begrenzt":"PD-L1 limité par le contexte propre à l’entité","PD-L1 CPS 25, pMMR/MSS, TMB 4 Mut/Mb, TIL-arm. Keine etablierte PD-1-Monotherapie aus PD-L1 allein; dMMR/MSI-H wäre der relevante validierte IO-Kontext. Studienkombinationen klar als experimentell kennzeichnen.":"PD-L1 CPS 25, pMMR/MSS, TMB 4 mut/Mb, TIL peu abondants. Pas de monothérapie anti-PD-1 établie sur le seul PD-L1 ; dMMR/MSI-H constituerait le contexte ICI validé pertinent. Les associations d’essai doivent être clairement qualifiées d’expérimentales.","Biomarkerhierarchie sauber getroffen.":"Hiérarchie des biomarqueurs correctement identifiée.","MSS erkannt, PD-L1 aber nicht eingeordnet":"MSS reconnu, mais PD-L1 non contextualisé","pMMR/MSS wird berichtet, der hohe CPS bleibt ohne Erklärung im Raum.":"Le statut pMMR/MSS est rapporté, mais le CPS élevé reste sans explication.","Der wichtigste Lernkonflikt wird nicht aufgelöst.":"Le conflit pédagogique principal reste non résolu.","CPS 25 = Pembrolizumab":"CPS 25 = pembrolizumab","PD-L1 wird entitätsübergreifend als Standardindikation interpretiert.":"Le PD-L1 est interprété entre entités tumorales comme une indication standard.","Validierungskontext missachtet.":"Le contexte de validation est ignoré.","Nicht-MSI-basierte Routineoptionen und geeignete klinische Studien prüfen.":"Évaluer les options établies non fondées sur le MSI et les essais cliniques appropriés.","Experimentelle Immuntherapiestrategien bleiben möglich, aber werden nicht als etablierte Monotherapie verkauft.":"Des stratégies d’immunothérapie expérimentales restent possibles, mais ne doivent pas être présentées comme une monothérapie établie.","PD-L1 ist kein tumoragnostischer Biomarker.":"Le PD-L1 n’est pas un biomarqueur tumor-agnostique.","Im mCRC hat dMMR/MSI-H eine zentrale etablierte prädiktive Rolle für Checkpoint-Inhibition.":"Dans le mCRC, dMMR/MSI-H joue un rôle prédictif central et établi pour l’inhibition des checkpoints immunitaires.","pMMR/MSS und niedrige TMB/TILs relativieren die intuitive Interpretation eines hohen PD-L1-Scores.":"Le statut pMMR/MSS et de faibles TMB/TIL nuancent l’interprétation intuitive d’un score PD-L1 élevé.","Ein positiver Labormarker kann korrekt gemessen und trotzdem klinisch nicht entscheidend sein.":"Un marqueur de laboratoire positif peut être correctement mesuré sans être pour autant cliniquement décisif.","Studienevidenz bei pMMR/MSS darf nicht mit Routine-Standard gleichgesetzt werden.":"Les données d’essais en pMMR/MSS ne doivent pas être assimilées au standard de soins de routine.","PD-L1 CPS 25 ist ein realer Kontextbefund, aber im pMMR/MSS-mCRC kein etablierter Ersatz für dMMR/MSI-H. TMB ist niedrig, TILs spärlich. Daher keine etablierte PD-1-Monotherapie allein aus dem CPS ableiten; Studienkombinationen nur als experimentelle Optionen kommunizieren.":"Le PD-L1 CPS 25 est un résultat contextuel réel, mais dans un mCRC pMMR/MSS il ne constitue pas un substitut établi à dMMR/MSI-H. Le TMB est faible et les TIL peu abondants. Il ne faut donc pas déduire une monothérapie anti-PD-1 établie du seul CPS ; les associations d’essai doivent être communiquées uniquement comme options expérimentales.","Entitätsspezifität":"Spécificité de l’entité","MMR/MSI priorisiert":"MMR/MSI priorisé","PD-L1 nicht ignoriert, aber begrenzt":"PD-L1 non ignoré, mais correctement limité","Studie vs. Standard getrennt":"Essai et standard distingués","Warum kann derselbe PD-L1-Score in zwei Tumorentitäten unterschiedliche Bedeutung besitzen?":"Pourquoi un même score PD-L1 peut-il avoir une signification différente dans deux entités tumorales ?","Welche Biomarker sind tumoragnostisch zugelassen und welche nicht?":"Quels biomarqueurs disposent d’autorisations tumor-agnostiques et lesquels n’en disposent pas ?","Wie formuliert man einen 'positiven, aber nicht entscheidenden' Marker verständlich im Befund?":"Comment formuler clairement dans un compte rendu un marqueur « positif mais non décisif » ?","PD-L1 CPS 25 wird durch pMMR/MSS/TMB-low relativiert":"Le PD-L1 CPS 25 est relativisé par pMMR/MSS/TMB-low","Biomarkerpositivität ist ohne Entitätsvalidierung keine Therapieindikation":"La positivité d’un biomarqueur ne constitue pas une indication thérapeutique sans validation propre à l’entité","PD-L1 → MMR/MSI → TMB/TIL → Evidenzhierarchie":"PD-L1 → MMR/MSI → TMB/TIL → hiérarchie des preuves","MSI-H-Karzinom: Therapieoption und Lynch-Abklärung → IO, MMR-IHC, Keimbahnkontext":"Carcinome MSI-H : option thérapeutique et bilan Lynch → IO, IHC MMR, contexte germinal","MSI-H-Karzinom: Therapieoption und…":"Carcinome MSI-H : option thérapeutique et…","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und pulmonalen Metastasen. Im Primärtumor war keine strukturierte MMR-/Lynch-Abklärung dokumentiert.":"Patiente de 49 ans atteinte d’un carcinome endométrioïde de l’endomètre récidivant avec métastases pulmonaires. Aucun bilan structuré MMR/Lynch n’avait été documenté sur la tumeur primitive.","Ist der Tumor dMMR/MSI-H und damit immuntherapeutisch relevant? Welche Reflexdiagnostik ist bei einem MMR-Verlust erforderlich, und wann muss Humangenetik folgen?":"La tumeur est-elle dMMR/MSI-H et donc pertinente pour l’immunothérapie ? Quel test réflexe est requis en cas de perte MMR, et quand faut-il poursuivre par une consultation de génétique ?","Die molekulare Einordnung soll Therapieplanung und hereditäre Beratung parallel strukturieren.":"La classification moléculaire doit structurer en parallèle la planification thérapeutique et le conseil en génétique héréditaire.","Alter":"Âge","49 Jahre bei aktueller Rezidivsituation.":"49 ans lors de la récidive actuelle.","Mutter mit Kolonkarzinom mit 52 Jahren; mütterlicher Onkel mit Urothelkarzinom des oberen Harntrakts.":"Mère atteinte d’un cancer colorectal à 52 ans ; oncle maternel atteint d’un carcinome urothélial des voies urinaires supérieures.","Außenbefund nennt 'MSI verdächtig', ohne dokumentierte MMR-IHC oder MLH1-Methylierung.":"Le compte rendu externe mentionne « suspicion de MSI » sans IHC MMR ni méthylation de MLH1 documentées.","CRC-Reflexdiagnostik wird unverändert auf das Endometriumkarzinom übertragen – insbesondere BRAF-V600E statt MLH1-Promotormethylierung.":"La stratégie réflexe du CRC est transposée telle quelle au carcinome de l’endomètre — notamment BRAF V600E à la place de la méthylation du promoteur de MLH1.","Endometrioides Endometriumkarzinom, high-grade, mit fokal lymphozytenreichem Stroma.":"Carcinome endométrioïde de l’endomètre de haut grade avec stroma focalement riche en lymphocytes.","Rezidiv-/Metastasenmaterial bestätigt endometrialen Ursprung.":"Le matériel de récidive/métastase confirme l’origine endométriale.","MMR-Proteinmuster, MSI-Status und bei MLH1/PMS2-Verlust die Frage einer sporadischen MLH1-Promotormethylierung.":"Profil des protéines MMR, statut MSI et, en cas de perte MLH1/PMS2, question d’une méthylation sporadique du promoteur de MLH1.","Therapiebiomarker und Lynch-Screening nutzen dieselbe MMR-Biologie, führen aber zu unterschiedlichen nächsten Schritten.":"Le biomarqueur thérapeutique et le dépistage de Lynch reposent sur la même biologie MMR, mais conduisent à des étapes ultérieures différentes.","FFPE-Resektat des Primärtumors plus aktuelle Metastasenbiopsie.":"Pièce de résection FFPE de la tumeur primitive plus biopsie métastatique actuelle.","Primärtumor ca. 60 %, DNA gut geeignet.":"Tumeur primitive env. 60 %, ADN de bonne qualité.","Ausreichend für MMR-IHC und molekulare Reflexdiagnostik.":"Suffisant pour l’IHC MMR et les tests moléculaires réflexes.","BRAF V600E ist als Lynch-Reflex aus dem CRC-Kontext bekannt, beantwortet beim Endometriumkarzinom aber nicht die entscheidende sporadisch-vs.-hereditär-Frage.":"BRAF V600E est connu comme test réflexe de Lynch dans le contexte du CRC, mais dans le carcinome de l’endomètre il ne répond pas à la question essentielle sporadique versus héréditaire.","MSI-Bestätigung":"Confirmation du MSI","MLH1-Reflexdiagnostik":"Test réflexe MLH1","Hereditäre Weiterleitung":"Orientation vers une évaluation héréditaire","Verlust von MLH1 und PMS2 bei erhaltener Expression von MSH2 und MSH6: dMMR-Muster.":"Perte de MLH1 et PMS2 avec expression conservée de MSH2 et MSH6 : profil dMMR.","MSI-high, konsistent mit dem dMMR-Befund.":"MSI-high, concordant avec le résultat dMMR.","MLH1-Promotormethylierung":"Méthylation du promoteur de MLH1","Keine MLH1-Promotor-Hypermethylierung nachweisbar. Damit ist eine häufige sporadische Ursache des MLH1/PMS2-Verlusts nicht belegt; Lynch-Syndrom bleibt abklärungsbedürftig, ist aber noch nicht bewiesen.":"Aucune hyperméthylation du promoteur de MLH1 n’est détectée. Une cause sporadique fréquente de la perte MLH1/PMS2 n’est donc pas démontrée ; un syndrome de Lynch doit encore être exploré, mais n’est pas prouvé à ce stade.","BRAF-V600E-Testung ist hier kein geeigneter Lynch-Screening-Reflex. Die aus dem CRC bekannte BRAF-Logik darf nicht auf das Endometriumkarzinom übertragen werden.":"Le test BRAF V600E n’est pas ici un réflexe approprié pour le dépistage de Lynch. La logique BRAF connue dans le CRC ne doit pas être transposée au carcinome de l’endomètre.","Humangenetische Beratung und Keimbahndiagnostik der MMR/Lynch-relevanten Gene werden empfohlen; der Tumorbefund allein stellt keine Lynch-Diagnose.":"Un conseil génétique et une analyse germinale des gènes pertinents pour MMR/Lynch sont recommandés ; le résultat tumoral seul n’établit pas un diagnostic de syndrome de Lynch.","PD-L1/TMB Zusatzkontext":"Contexte complémentaire PD-L1/TMB","Zusatzmarker können berichtet werden, stehen aber hinter dem robusten dMMR/MSI-H-Befund zurück und sind für die Lynch-Reflexdiagnostik nicht entscheidend.":"Des marqueurs supplémentaires peuvent être rapportés, mais restent secondaires par rapport au résultat robuste dMMR/MSI-H et ne sont pas déterminants pour le bilan réflexe de Lynch.","Rezidiviertes Endometriumkarzinom bei junger Patientin mit auffälliger Familienanamnese.":"Carcinome de l’endomètre récidivant chez une patiente jeune avec antécédents familiaux évocateurs.","MMR-IHC und MSI-/Methylierungsdiagnostik technisch verwertbar.":"L’IHC MMR et les tests MSI/méthylation sont techniquement interprétables.","Rezidiviertes Endometriumkarzinom mit MLH1/PMS2-Verlust und MSI-H. Der dMMR/MSI-H-Befund ist therapeutisch relevant. Da keine MLH1-Promotor-Hypermethylierung nachweisbar ist, bleibt ein Lynch-Syndrom abklärungsbedürftig und erfordert humangenetische Beratung/Keimbahndiagnostik. BRAF V600E ist in diesem Endometrium-Kontext kein adäquater Ersatzreflex und Lynch ist aus dem Tumorbefund allein nicht bewiesen.":"Carcinome de l’endomètre récidivant avec perte MLH1/PMS2 et MSI-H. Le résultat dMMR/MSI-H est thérapeutiquement pertinent. En l’absence d’hyperméthylation du promoteur de MLH1, un syndrome de Lynch reste à explorer et nécessite conseil génétique/analyse germinale. BRAF V600E n’est pas un réflexe substitutif approprié dans ce contexte endométrial, et le syndrome de Lynch n’est pas prouvé par le seul résultat tumoral.","Teilbefund: dMMR/MSI-H ist erkannt, aber ohne MLH1-Methylierungsreflex und humangenetische Weiterleitung bleibt die hereditäre Ebene unvollständig.":"Résultat partiel : dMMR/MSI-H est reconnu, mais sans test réflexe de méthylation de MLH1 ni orientation en génétique, la dimension héréditaire reste incomplète.","dMMR/MSI-H als starken prädiktiven Immuntherapiekontext benennen":"Présenter dMMR/MSI-H comme un contexte prédictif fort pour l’immunothérapie","MLH1/PMS2-Verlust korrekt als gekoppeltes MMR-Muster einordnen":"Interpréter correctement la perte MLH1/PMS2 comme un profil MMR couplé","MLH1-Promotormethylierung als passenden Endometrium-Reflex nutzen":"Utiliser la méthylation du promoteur de MLH1 comme test réflexe approprié dans l’endomètre","fehlende Methylierung → Lynch-Abklärung empfehlen, aber Lynch nicht als bewiesen darstellen":"Absence de méthylation → recommander un bilan Lynch, sans présenter le syndrome de Lynch comme prouvé","Falschaussage: BRAF-V600E ist auch beim Endometriumkarzinom der Standardreflex für MLH1/PMS2-Verlust":"Affirmation fausse : BRAF V600E est également le réflexe standard en cas de perte MLH1/PMS2 dans le carcinome de l’endomètre","Optimale Lösung: MLH1/PMS2-Verlust + MSI-H therapeutisch kommunizieren; beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex prüfen. Fehlt die Methylierung, humangenetisch weiterleiten – ohne aus dem Tumorscreening bereits eine Lynch-Diagnose zu machen.":"Solution optimale : communiquer la perte MLH1/PMS2 + MSI-H sur le plan thérapeutique ; dans le carcinome de l’endomètre, rechercher la méthylation du promoteur de MLH1 en réflexe. En l’absence de méthylation, orienter vers une évaluation génétique — sans transformer le dépistage tumoral à lui seul en diagnostic de Lynch.","Endometriumkarzinom":"Carcinome de l’endomètre","dMMR":"dMMR","MSI-H":"MSI-H","MLH1":"MLH1","PMS2":"PMS2","Lynch":"Lynch","MSI-H und MLH1/PMS2-Verlust: Endometriumkarzinom zwischen Immuntherapie und Lynch-Abklärung":"MSI-H et perte MLH1/PMS2 : carcinome de l’endomètre entre immunothérapie et bilan Lynch","Molekularpathologie / Gynäko-Onkologie / Humangenetik / MTB":"Pathologie moléculaire / Oncologie gynécologique / Génétique médicale / MTB","MMR-IHC-Muster korrekt lesen und MLH1/PMS2-Verlust funktionell einordnen.":"Lire correctement le profil IHC MMR et interpréter fonctionnellement la perte MLH1/PMS2.","dMMR/MSI-H gleichzeitig als prädiktiven Therapiebiomarker und als möglichen Hinweis auf hereditäre Prädisposition verstehen.":"Comprendre dMMR/MSI-H à la fois comme biomarqueur thérapeutique prédictif et comme indice possible de prédisposition héréditaire.","Beim Endometriumkarzinom MLH1-Promotormethylierung als passenden Reflex bei MLH1/PMS2-Verlust einsetzen.":"Dans le carcinome de l’endomètre, utiliser la méthylation du promoteur de MLH1 comme test réflexe approprié en cas de perte MLH1/PMS2.","Den CRC-spezifischen BRAF-V600E-Reflex nicht unkritisch auf das Endometriumkarzinom übertragen.":"Ne pas transposer sans discernement au carcinome de l’endomètre le réflexe BRAF V600E spécifique du CRC.","Fehlende MLH1-Methylierung als Anlass zur Lynch-Abklärung, nicht als bereits bewiesenes Lynch-Syndrom kommunizieren.":"Présenter l’absence de méthylation de MLH1 comme un motif de bilan Lynch, et non comme un syndrome de Lynch déjà prouvé.","Die MMR-IHC zeigt einen klaren MLH1/PMS2-Verlust, der MSI-Test ist high. Im Tumorboard sind sich alle einig, dass das therapeutisch wichtig ist. Dann kommt die zweite Frage: 'Dann machen wir jetzt BRAF wie beim Kolon?' Genau hier kippt der Fall von Immuntherapie in echte molekularpathologische Reflexdiagnostik.":"L’IHC MMR montre une perte nette de MLH1/PMS2 et le test MSI est high. Au tumor board, tout le monde s’accorde sur l’importance thérapeutique. Puis vient la deuxième question : « Alors, on fait BRAF comme pour le côlon ? » C’est précisément là que le cas passe de l’immunothérapie à une véritable stratégie réflexe de pathologie moléculaire.","49-jährige Patientin mit rezidiviertem endometrioidem Endometriumkarzinom und auffälliger Familienanamnese. Der Tumor ist dMMR/MSI-H mit MLH1/PMS2-Verlust. Gesucht wird die korrekte Trennung von unmittelbarer therapeutischer Relevanz und Lynch-Screening inklusive entitätsspezifischem MLH1-Methylierungsreflex.":"Patiente de 49 ans avec carcinome endométrioïde de l’endomètre récidivant et antécédents familiaux évocateurs. La tumeur est dMMR/MSI-H avec perte MLH1/PMS2. Il faut distinguer correctement la pertinence thérapeutique immédiate du dépistage de Lynch, y compris le réflexe de méthylation de MLH1 propre à l’entité.","Ein Befund, zwei Konsequenzen":"Un résultat, deux conséquences","dMMR/MSI-H ist therapie- und hereditär relevant.":"dMMR/MSI-H est pertinent à la fois sur le plan thérapeutique et héréditaire.","Dieselbe Tumorbiologie kann unterschiedliche klinische Pfade auslösen.":"Une même biologie tumorale peut déclencher des parcours cliniques différents.","Verlustmuster":"Profil de perte","MLH1 und PMS2 fehlen gemeinsam.":"MLH1 et PMS2 sont perdus conjointement.","Das Heterodimer-Muster lenkt die Reflexdiagnostik auf MLH1.":"Le profil d’hétérodimère oriente le test réflexe vers MLH1.","Entität zählt":"L’entité tumorale compte","BRAF-Reflex ist aus dem CRC bekannt.":"Le réflexe BRAF est connu dans le CRC.","Reflexalgorithmen dürfen nicht mechanisch zwischen Tumorentitäten übertragen werden.":"Les algorithmes réflexes ne doivent pas être transposés mécaniquement d’une entité tumorale à l’autre.","High-grade endometrioides Endometriumkarzinom.":"Carcinome endométrioïde de l’endomètre de haut grade.","Mutter Kolonkarzinom mit 52, Onkel oberer Harntrakt.":"Mère avec cancer colorectal à 52 ans, oncle avec cancer des voies urinaires supérieures.","Primärtumor mit guter DNA-Qualität; MMR-IHC und Methylierung möglich.":"Tumeur primitive avec ADN de bonne qualité ; IHC MMR et analyse de méthylation réalisables.","MMR-IHC liefert bereits das entscheidende Proteinverlustmuster und sollte nicht durch ein unspezifisches Breitpanel ersetzt werden.":"L’IHC MMR fournit déjà le profil décisif de perte protéique et ne doit pas être remplacée par un panel large non spécifique.","Bei MLH1/PMS2-Verlust ist eine gezielte MLH1-Promotormethylierung material- und fragestellungseffizient.":"En cas de perte MLH1/PMS2, l’analyse ciblée de la méthylation du promoteur de MLH1 est efficiente à la fois en termes de matériel et de question clinique.","Die Keimbahndiagnostik benötigt humangenetische Beratung und eine geeignete Normalprobe; Tumorgewebe allein reicht nicht.":"L’analyse germinale nécessite un conseil génétique et un échantillon normal approprié ; le tissu tumoral seul ne suffit pas.","MMR-IHC: MLH1 und PMS2 verloren, MSH2/MSH6 erhalten. Was ist der passende nächste Reflex im Endometriumkarzinom?":"IHC MMR : perte de MLH1 et PMS2, MSH2/MSH6 conservés. Quel est le test réflexe approprié ensuite dans un carcinome de l’endomètre ?","MLH1-Promotormethylierung prüfen, um eine häufige sporadische MLH1-Inaktivierung zu erfassen.":"Rechercher la méthylation du promoteur de MLH1 afin d’identifier un mécanisme sporadique fréquent d’inactivation de MLH1.","BRAF V600E ist hier der Standardreflex wie beim CRC.":"BRAF V600E est ici le réflexe standard, comme dans le CRC.","Nur PD-L1 nachtesten; MMR-Muster ist für Lynch irrelevant.":"Répéter uniquement le PD-L1 ; le profil MMR est sans rapport avec Lynch.","Kein Reflex: MLH1/PMS2-Verlust beweist bereits Lynch.":"Pas de test réflexe : la perte MLH1/PMS2 prouve déjà un syndrome de Lynch.","Beim Endometriumkarzinom ist die MLH1-Promotormethylierung der relevante Reflex bei MLH1/PMS2-Verlust.":"Dans le carcinome de l’endomètre, la méthylation du promoteur de MLH1 est le test réflexe pertinent en cas de perte MLH1/PMS2.","Was bedeutet dMMR/MSI-H therapeutisch?":"Que signifie dMMR/MSI-H sur le plan thérapeutique ?","Ein starker prädiktiver Immuntherapiekontext, dessen konkrete Nutzung von Stadium, Linie und aktueller Zulassung/Leitlinie abhängt.":"Un contexte prédictif fort pour l’immunothérapie, dont l’utilisation concrète dépend du stade, de la ligne thérapeutique et des autorisations/recommandations en vigueur.","Ohne hohen PD-L1-Score ist MSI-H therapeutisch bedeutungslos.":"Sans score PD-L1 élevé, MSI-H n’a pas de signification thérapeutique.","MSI-H ist ausschließlich ein Lynch-Screeningmarker.":"MSI-H est exclusivement un marqueur de dépistage de Lynch.","MSI-H beweist eine Keimbahn-MMR-Mutation.":"MSI-H prouve une mutation germinale MMR.","dMMR/MSI-H besitzt eine eigenständige prädiktive Bedeutung, unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"dMMR/MSI-H possède une valeur prédictive propre, que la cause soit sporadique ou héréditaire.","MLH1/PMS2-Verlust + MSI-H, aber keine MLH1-Promotormethylierung. Was folgt?":"Perte MLH1/PMS2 + MSI-H, mais pas de méthylation du promoteur de MLH1. Quelle est la suite ?","Lynch-Syndrom bleibt verdächtig: humangenetische Beratung/Keimbahndiagnostik veranlassen, ohne Lynch bereits als bewiesen zu bezeichnen.":"Un syndrome de Lynch reste suspect : organiser un conseil génétique/une analyse germinale sans le présenter déjà comme prouvé.","Lynch-Syndrom ist damit sicher bewiesen.":"Le syndrome de Lynch est ainsi définitivement prouvé.","Fehlende Methylierung beweist einen sporadischen Tumor.":"L’absence de méthylation prouve une tumeur sporadique.","Nur ein negatives BRAF-Ergebnis kann jetzt Lynch ausschließen.":"Seul un résultat BRAF négatif peut maintenant exclure un syndrome de Lynch.","Tumorscreening stratifiziert den Verdacht; die Keimbahndiagnose ist ein separater Schritt.":"Le dépistage tumoral stratifie la suspicion ; le diagnostic germinal constitue une étape distincte.","Warum ist BRAF V600E hier eine Falle?":"Pourquoi BRAF V600E est-il un piège ici ?","Der BRAF-Reflex gehört zur CRC-spezifischen MLH1/PMS2-Logik und ist beim Endometriumkarzinom kein adäquater Ersatz für MLH1-Promotormethylierung.":"Le réflexe BRAF appartient à l’algorithme MLH1/PMS2 spécifique du CRC et ne constitue pas un substitut approprié à la méthylation du promoteur de MLH1 dans le carcinome de l’endomètre.","BRAF kann in keinem Endometriumtumor mutiert sein.":"BRAF ne peut jamais être muté dans une tumeur endométriale.","BRAF bestimmt hier ausschließlich die PD-L1-Expression.":"BRAF détermine ici uniquement l’expression de PD-L1.","CRC- und Endometrium-Reflexalgorithmen sind identisch.":"Les algorithmes réflexes du CRC et de l’endomètre sont identiques.","Reflexdiagnostik ist entitätsspezifisch und darf nicht als universelles Rezept behandelt werden.":"La stratégie diagnostique réflexe est spécifique de l’entité et ne doit pas être traitée comme une recette universelle.","Formulieren Sie eine integrierte MTB-/Befundaussage, die dMMR/MSI-H therapeutisch würdigt, den MLH1/PMS2-Verlust korrekt reflexdiagnostisch weiterführt und die Lynch-Frage sauber von der Tumordiagnostik trennt.":"Formulez une conclusion intégrée MTB/compte rendu qui valorise correctement la pertinence thérapeutique de dMMR/MSI-H, poursuit de manière appropriée la perte MLH1/PMS2 par le test réflexe adéquat et sépare clairement la question de Lynch du diagnostic tumoral.","MMR-IHC: MLH1/PMS2-Verlust benennen.":"IHC MMR : mentionner la perte MLH1/PMS2.","MSI-H als konsistenten molekularen Befund bestätigen.":"Confirmer MSI-H comme résultat moléculaire concordant.","dMMR/MSI-H als prädiktiven IO-Kontext kommunizieren.":"Communiquer dMMR/MSI-H comme contexte prédictif pour l’immunothérapie.","MLH1-Promotormethylierung als entitätsspezifischen Reflex durchführen.":"Réaliser la méthylation du promoteur de MLH1 comme test réflexe spécifique de l’entité.","Fehlende MLH1-Methylierung als erhöhten Lynch-Verdacht, nicht als Beweis interpretieren.":"Interpréter l’absence de méthylation de MLH1 comme un renforcement de la suspicion de Lynch, et non comme une preuve.","Humangenetische Beratung/Keimbahndiagnostik empfehlen.":"Recommander un conseil génétique/une analyse germinale.","BRAF-V600E-CRC-Reflex ausdrücklich nicht übertragen.":"Ne pas transposer explicitement le réflexe BRAF V600E du CRC.","MSI kann molekular aus einem validierten Panel bestätigt werden, sofern MMR-IHC und MLH1-Methylierungsreflex trotzdem korrekt integriert werden.":"Le MSI peut être confirmé moléculairement à partir d’un panel validé, à condition que l’IHC MMR et le réflexe de méthylation de MLH1 soient correctement intégrés.","Bei bereits qualitativ eindeutiger dMMR-IHC kann die therapeutische Kommunikation sofort erfolgen, während die hereditäre Reflexdiagnostik parallel abgeschlossen wird.":"Si l’IHC dMMR est déjà sans ambiguïté et techniquement fiable, l’interprétation thérapeutique peut être communiquée immédiatement tandis que le bilan réflexe héréditaire est complété en parallèle.","BRAF wie beim CRC":"BRAF comme dans le CRC","Entitätsspezifischer Reflexalgorithmus falsch übertragen.":"Algorithme réflexe propre à l’entité transposé à tort.","MSI-H = Lynch":"MSI-H = Lynch","Viele dMMR/MSI-H-Tumoren sind sporadisch; Tumorscreening ist keine Keimbahndiagnose.":"De nombreuses tumeurs dMMR/MSI-H sont sporadiques ; le dépistage tumoral n’est pas un diagnostic germinal.","Methylierungsnegativ = bewiesen erblich":"Méthylation négative = héréditaire prouvé","Der Befund erhöht den Verdacht, beweist aber noch keine Keimbahnmutation.":"Le résultat augmente la suspicion mais ne prouve pas encore une mutation germinale.","PD-L1 priorisieren":"Prioriser le PD-L1","dMMR/MSI-H ist hier der robustere Kernbiomarker; PD-L1 ist für die Lynch-Frage irrelevant.":"dMMR/MSI-H est ici le biomarqueur central le plus robuste ; le PD-L1 est sans rapport avec la question de Lynch.","Der CRC-Reflex wäre hier genau der falsche Automatismus":"Le réflexe du CRC serait précisément le mauvais automatisme ici","MLH1/PMS2-Verlust und MSI-H wirken zunächst wie ein vertrauter CRC-Fall. Doch beim Endometriumkarzinom ist der sinnvolle Reflex die MLH1-Promotormethylierung – nicht BRAF V600E. Als die Methylierung negativ bleibt, steigt der Lynch-Verdacht deutlich, ohne bereits zur genetischen Diagnose zu werden.":"La perte MLH1/PMS2 et le MSI-H évoquent d’abord un cas familier de CRC. Mais dans le carcinome de l’endomètre, le réflexe approprié est la méthylation du promoteur de MLH1 — et non BRAF V600E. Lorsque la méthylation reste négative, la suspicion de Lynch augmente nettement sans constituer encore un diagnostic génétique.","Der Fall trainiert zwei Kernkompetenzen gleichzeitig: entitätsspezifische Reflexdiagnostik und saubere Trennung von Tumor-Screening und Keimbahndiagnose.":"Ce cas entraîne simultanément deux compétences clés : une stratégie réflexe propre à l’entité et une séparation nette entre dépistage tumoral et diagnostic germinal.","Therapie und Lynch-Pfad sauber getrennt":"Traitement et parcours Lynch clairement séparés","MLH1/PMS2-Verlust, MSI-H, keine MLH1-Promotormethylierung. dMMR/MSI-H als IO-relevant berichten; Lynch-Syndrom humangenetisch abklären. BRAF-CRC-Reflex nicht verwenden.":"Perte MLH1/PMS2, MSI-H, absence de méthylation du promoteur de MLH1. Rapporter dMMR/MSI-H comme pertinent pour l’IO ; poursuivre par une évaluation génétique du syndrome de Lynch. Ne pas utiliser le réflexe BRAF du CRC.","Beide klinischen Konsequenzen korrekt geführt.":"Les deux conséquences cliniques sont correctement prises en charge.","IO erkannt, Lynch-Pfad unvollständig":"IO reconnue, parcours Lynch incomplet","dMMR/MSI-H wird therapeutisch korrekt eingeordnet, MLH1-Methylierung/Genetik fehlen.":"dMMR/MSI-H est correctement interprété sur le plan thérapeutique, mais la méthylation de MLH1/l’orientation en génétique manquent.","Hereditäre Konsequenz verpasst.":"La conséquence héréditaire a été manquée.","BRAF-Automatismus":"Automatisme BRAF","BRAF V600E wird als Standardreflex bestellt und ein negatives Ergebnis als Lynch-Beweis interpretiert.":"BRAF V600E est demandé comme réflexe standard et un résultat négatif est interprété comme preuve d’un syndrome de Lynch.","Entitätsspezifische Reflexdiagnostik und Keimbahnlogik verfehlt.":"La stratégie réflexe propre à l’entité et la logique germinale sont manquées.","MLH1-Methylierung negativ":"Méthylation MLH1 négative","Humangenetische Beratung und Keimbahndiagnostik veranlassen.":"Organiser un conseil génétique et une analyse germinale.","Lynch-Syndrom kann bestätigt oder ausgeschlossen werden; Familienmanagement erst danach festlegen.":"Le syndrome de Lynch pourra alors être confirmé ou exclu ; la prise en charge familiale ne doit être définie qu’ensuite.","dMMR/MSI-H bestätigt":"dMMR/MSI-H confirmé","Therapieplanung mit aktuellem endometriumkarzinomspezifischem IO-Standard/Leitlinie abgleichen.":"Aligner la planification thérapeutique sur le standard/la recommandation IO actuelle spécifique du carcinome de l’endomètre.","Prädiktiver Befund wird unabhängig von der noch offenen Keimbahnursache genutzt.":"Le résultat prédictif peut être utilisé indépendamment de l’origine germinale encore non résolue.","dMMR/MSI-H kann zugleich Therapiebiomarker und Hinweis auf hereditäre Prädisposition sein.":"dMMR/MSI-H peut être à la fois un biomarqueur thérapeutique et un indice de prédisposition héréditaire.","MLH1/PMS2-Verlust lenkt die Reflexdiagnostik auf MLH1-Promotormethylierung.":"La perte MLH1/PMS2 oriente le test réflexe vers la méthylation du promoteur de MLH1.","CRC-BRAF-Reflexe dürfen nicht automatisch auf das Endometriumkarzinom übertragen werden.":"Les réflexes BRAF du CRC ne doivent pas être automatiquement transposés au carcinome de l’endomètre.","Fehlende MLH1-Methylierung erhöht den Lynch-Verdacht, beweist aber keine Keimbahnmutation.":"L’absence de méthylation de MLH1 augmente la suspicion de syndrome de Lynch, mais ne prouve pas une mutation germinale.","Tumorbiomarker und Humangenetik laufen parallel, aber diagnostisch getrennt.":"Les biomarqueurs tumoraux et la génétique médicale avancent en parallèle, mais restent diagnostiquement distincts.","MLH1/PMS2-Verlust + MSI-H = dMMR/MSI-H und damit therapeutisch relevant. Beim Endometriumkarzinom MLH1-Promotormethylierung als Reflex; hier negativ. Deshalb Lynch-Syndrom humangenetisch abklären, aber nicht bereits diagnostizieren. BRAF V600E ist kein adäquater Ersatzreflex.":"Perte MLH1/PMS2 + MSI-H = dMMR/MSI-H et donc pertinence thérapeutique. Dans le carcinome de l’endomètre, utiliser la méthylation du promoteur de MLH1 comme test réflexe ; ici elle est négative. Il faut donc poursuivre par une évaluation génétique du syndrome de Lynch, sans encore le diagnostiquer. BRAF V600E n’est pas un réflexe substitutif approprié.","MMR-Muster korrekt":"Profil MMR correct","MLH1-Methylierungsreflex":"Réflexe de méthylation MLH1","IO-Relevanz":"Pertinence IO","Lynch-Verdacht ≠ Diagnose":"Suspicion de Lynch ≠ diagnostic","BRAF-Copyover vermieden":"Transposition BRAF évitée","Warum fallen MLH1 und PMS2 gemeinsam aus?":"Pourquoi MLH1 et PMS2 sont-ils perdus conjointement ?","Warum unterscheidet sich der Reflexalgorithmus zwischen CRC und Endometrium?":"Pourquoi l’algorithme réflexe diffère-t-il entre le CRC et le carcinome de l’endomètre ?","Welche Information darf bereits im Tumorbefund stehen und welche erst nach Keimbahndiagnostik?":"Quelles informations peuvent déjà figurer dans le compte rendu tumoral et lesquelles seulement après l’analyse germinale ?","MLH1/PMS2-Verlust + keine MLH1-Methylierung":"Perte MLH1/PMS2 + absence de méthylation MLH1","dMMR ist Therapiebiomarker und Lynch-Screening, aber Entität bestimmt den Reflex":"dMMR est à la fois biomarqueur thérapeutique et dépistage de Lynch, mais l’entité tumorale détermine le réflexe","MMR-IHC → MSI → MLH1-Methylierung → Humangenetik":"IHC MMR → MSI → méthylation MLH1 → génétique médicale","Antibiotika kurz vor ICI, Mikrobiom-Frage im Tumorboard → Evidenz korrekt begrenzen":"Antibiotiques peu avant l’ICI, question du microbiome au tumor board → limiter correctement la portée des données","Antibiotika kurz vor ICI, Mikrobio…":"Antibiotiques peu avant l’ICI, microbio…","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom. PD-L1 TPS 80 %. Vor Beginn der geplanten Immuntherapie musste er wegen einer mikrobiologisch gesicherten bakteriellen Pneumonie sieben Tage breit antibiotisch behandelt werden.":"Homme de 72 ans atteint d’un adénocarcinome pulmonaire métastatique. PD-L1 TPS 80 %. Avant le début prévu de l’immunothérapie, il a nécessité sept jours d’antibiotiques à large spectre pour une pneumonie bactérienne confirmée microbiologiquement.","Soll die notwendige Antibiotikatherapie wegen möglicher Mikrobiom-Effekte die ICI-Entscheidung verändern, verzögern oder durch Mikrobiom-Interventionen 'kompensiert' werden?":"L’antibiothérapie nécessaire doit-elle, en raison d’effets possibles sur le microbiome, modifier ou retarder la décision d’ICI, ou être « compensée » par des interventions sur le microbiome ?","Die Pneumonie ist klinisch abgeheilt; Systemtherapie soll zeitnah beginnen.":"La pneumonie est cliniquement résolue ; le traitement systémique doit débuter rapidement.","Tumor":"Tumeur","Metastasiertes Lungenadenokarzinom, ECOG 1.":"Adénocarcinome pulmonaire métastatique, ECOG 1.","Treiberdiagnostik":"Recherche de drivers","Breites DNA/RNA-Profil ohne etablierte actionable Driveralteration; ALK/ROS1/RET/NTRK/METex14/EGFR etc. ohne therapieentscheidenden Befund.":"Profilage large ADN/ARN sans altération driver actionable établie ; ALK/ROS1/RET/NTRK/METex14/EGFR, etc., sans résultat déterminant pour le traitement.","TPS 80 %, technisch valide.":"TPS 80 %, techniquement valide.","Antibiotika":"Antibiotiques","Piperacillin/Tazobactam, anschließend orale Komplettierung wegen gesicherter bakterieller Pneumonie; Therapie war klinisch indiziert.":"Pipéracilline/tazobactam puis relais oral pour pneumonie bactérienne confirmée ; le traitement était cliniquement indiqué.","Eine populationsbasierte Assoziation zwischen Antibiotika/Mikrobiom und ICI-Outcome wird zur individuellen Kontraindikation oder zum Anlass für unvalidierte Probiotika/FMT gemacht.":"Une association populationnelle entre antibiotiques/microbiome et résultat sous ICI est transformée en contre-indication individuelle ou en justification de probiotiques/FMT non validés.","Pulmonales Adenokarzinom, TTF-1/Napsin A positiv.":"Adénocarcinome pulmonaire, TTF-1/Napsine A positifs.","TPS 80 %.":"TPS 80 %.","Molekularprofil":"Profil moléculaire","DNA/RNA-basierte Treiberdiagnostik ohne etablierte Targetalteration.":"Recherche de drivers basée sur ADN/ARN sans altération ciblable établie.","Nicht die Tumordiagnostik, sondern die Evidenzstärke der Mikrobiom-/Antibiotika-Assoziation und ihre Konsequenz für die individuelle Therapie.":"La question clé n’est pas le bilan tumoral, mais la solidité des données sur l’association microbiome/antibiotiques et sa conséquence pour la décision thérapeutique individuelle.","Kleine Bronchialbiopsie; wesentliche Treiber- und PD-L1-Diagnostik bereits vollständig.":"Petite biopsie bronchique ; bilan essentiel des drivers et du PD-L1 déjà complet.","Restmaterial":"Matériel restant","Nur noch begrenzt verfügbar.":"Il ne reste qu’un matériel limité.","Zusätzliche TMB-/TIL-/Breitdiagnostik kann den Effekt einer Antibiotikatherapie auf das Darmmikrobiom nicht valide quantifizieren und erzeugt keine etablierte 'ICI-Freigabe'.":"Des tests supplémentaires TMB/TIL ou larges ne peuvent pas quantifier valablement l’effet de l’antibiothérapie sur le microbiome intestinal et ne génèrent pas une « autorisation ICI » établie.","Klinische Ressource":"Ressource clinique","Der wichtigste Zusatzdatensatz ist hier die Indikation und zeitliche Einordnung der Antibiotikatherapie – nicht noch ein Tumortest.":"L’information complémentaire la plus importante ici est l’indication et le calendrier de l’antibiothérapie — pas un test tumoral supplémentaire.","Validierter Tumor-/ICI-Kontext":"Contexte tumoral/ICI validé","PD-L1 TPS 80 % bestätigt. Der Marker bleibt ein etablierter Bestandteil der NSCLC-Therapieplanung im passenden driver-negativen Kontext.":"PD-L1 TPS 80 % confirmé. Le marqueur reste un élément établi de la planification thérapeutique du NSCLC dans le contexte driver négatif approprié.","Treiberprofil":"Profil des drivers","Keine etablierte actionable Driveralteration nach integrierter DNA/RNA-Diagnostik. Die hohe PD-L1-Expression wird damit nicht durch einen offensichtlichen targetierbaren Treiberkontext verdrängt.":"Aucune altération driver actionable établie après analyse intégrée ADN/ARN. La forte expression de PD-L1 n’est donc pas supplantée par un contexte driver manifestement ciblable.","TMB intermediär (7 Mut/Mb). Dieser Wert beantwortet die Antibiotika-/Mikrobiomfrage nicht und ersetzt die validierte NSCLC-Biomarkerhierarchie nicht.":"TMB intermédiaire (7 mut/Mb). Cette valeur ne répond pas à la question antibiotiques/microbiome et ne remplace pas la hiérarchie validée des biomarqueurs du NSCLC.","Mäßiges CD8-Infiltrat. Auch dieser Befund erlaubt keine patientenspezifische Quantifizierung eines möglichen Antibiotikaeffekts auf ICI-Wirksamkeit.":"Infiltrat CD8 modéré. Ce résultat ne permet pas non plus de quantifier un effet propre au patient des antibiotiques sur l’efficacité de l’ICI.","Antibiotikaanamnese":"Historique antibiotique","Sieben Tage notwendige Antibiotikatherapie wegen gesicherter bakterieller Pneumonie unmittelbar vor geplantem ICI-Beginn.":"Sept jours d’antibiothérapie nécessaire pour pneumonie bactérienne confirmée immédiatement avant le début prévu de l’ICI.","Infektion abgeheilt; Patient therapiefähig.":"Infection résolue ; patient apte au traitement.","Evidenzkonflikt":"Conflit de données","Beobachtungsdaten zeigen Assoziationen zwischen Antibiotikaexposition und schlechteren ICI-Outcomes, beweisen aber für den individuellen Patienten keine kausale Therapieresistenz.":"Les données observationnelles montrent des associations entre l’exposition aux antibiotiques et de moins bons résultats sous ICI, mais ne prouvent pas une résistance thérapeutique causale chez un patient donné.","Driver-negatives metastasiertes NSCLC mit hoher PD-L1-Expression. Die kürzlich notwendige Antibiotikatherapie ist als möglicher prognostischer/biologischer Kontext diskutierbar, stellt aber keine validierte individuelle Kontraindikation gegen eine indizierte Checkpoint-Therapie dar. Eine klinisch notwendige bakterielle Infektion durfte nicht unbehandelt bleiben. Unnötige Antibiotika sollten vermieden werden; Mikrobiomtests, Probiotika oder FMT sind nicht als routinemäßige Kompensationsstrategie validiert und gehören – sofern überhaupt – in Studien.":"NSCLC métastatique driver négatif avec forte expression de PD-L1. L’antibiothérapie récente et nécessaire peut être discutée comme contexte pronostique/biologique possible, mais ne constitue pas une contre-indication individuelle validée à une thérapie par checkpoint indiquée. Une infection bactérienne cliniquement nécessitant un traitement ne devait pas rester non traitée. Les antibiotiques inutiles doivent être évités ; les tests du microbiome, probiotiques ou FMT ne sont pas validés comme stratégies de compensation de routine et relèvent, le cas échéant, des essais cliniques.","Teilbefund: Die Mikrobiom-Assoziation wird erwähnt, aber ohne Trennung von Kausalität, Konfounding, klinischer Antibiotikaindikation und validierten Tumorbiomarkern bleibt die Empfehlung unsauber.":"Interprétation partielle : l’association avec le microbiome est mentionnée, mais sans distinguer causalité, facteurs de confusion, indication clinique des antibiotiques et biomarqueurs tumoraux validés, la recommandation reste imprécise.","PD-L1 und vollständigen Driverstatus als etablierte NSCLC-Biomarkerhierarchie priorisieren":"Prioriser le PD-L1 et le statut complet des drivers comme hiérarchie établie des biomarqueurs du NSCLC","Antibiotika/ICI als Assoziation mit möglichem Confounding, nicht als individuellen Resistenztest erklären":"Expliquer antibiotiques/ICI comme une association avec facteurs de confusion possibles, et non comme un test individuel de résistance","klinisch notwendige Antibiotikatherapie nicht retrospektiv als Fehler darstellen":"Ne pas présenter rétrospectivement une antibiothérapie cliniquement nécessaire comme une erreur","keine unvalidierte Mikrobiomdiagnostik, Probiotika oder FMT als Routineempfehlung aussprechen":"Ne pas recommander en routine des tests du microbiome, probiotiques ou FMT non validés","Falschaussage: Antibiotika kurz vor ICI sind eine absolute Kontraindikation gegen Immuntherapie":"Affirmation fausse : les antibiotiques peu avant l’ICI constituent une contre-indication absolue à l’immunothérapie","Optimale Lösung: Hohe PD-L1-Expression und driver-negativer NSCLC-Kontext bleiben die belastbaren Therapiebiomarker. Die notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext zu erwähnen, aber nicht als validierte individuelle Kontraindikation. Keine unvalidierten Mikrobiom-Interventionen außerhalb von Studien.":"Solution optimale : la forte expression de PD-L1 et le contexte NSCLC driver négatif restent les biomarqueurs thérapeutiques fiables. L’antibiothérapie nécessaire doit être mentionnée comme contexte possible d’issue, mais non comme contre-indication individuelle validée. Pas d’intervention non validée sur le microbiome hors essai.","Mikrobiom":"Microbiome","ICI":"ICI","Confounding":"Facteurs de confusion","Antibiotika vor ICI: relevante Assoziation, aber keine patientenindividuelle Kontraindikation":"Antibiotiques avant ICI : association pertinente, mais pas contre-indication individuelle","Beobachtungsassoziation, Kausalität und Confounding in der Mikrobiom-/ICI-Literatur unterscheiden.":"Distinguer association observationnelle, causalité et facteurs de confusion dans la littérature microbiome/ICI.","Validierte NSCLC-Tumorbiomarker gegenüber unvalidierten Mikrobiom-Surrogaten priorisieren.":"Prioriser les biomarqueurs tumoraux validés du NSCLC par rapport aux marqueurs substitutifs non validés du microbiome.","Klinisch notwendige Antibiotikatherapie nicht retrospektiv als vermeidbaren onkologischen Fehler behandeln.":"Ne pas considérer rétrospectivement une antibiothérapie cliniquement nécessaire comme une erreur oncologique évitable.","Eine vorausgegangene Antibiotikaexposition nicht als absolute ICI-Kontraindikation formulieren.":"Ne pas présenter une exposition antibiotique antérieure comme une contre-indication absolue à l’ICI.","Mikrobiomtests, Probiotika und FMT als experimentell statt als Routinetherapie einordnen.":"Classer les tests du microbiome, probiotiques et FMT comme expérimentaux plutôt que comme traitement de routine.","Der Patient hat genau den Tumor, bei dem das Team an Checkpoint-Therapie denkt: driver-negatives NSCLC, PD-L1 TPS 80 %. Dann fällt im Medikamentenplan auf, dass er in der Vorwoche sieben Tage Breitbandantibiotika bekommen hat. Sofort steht die Frage im Raum: 'Haben wir damit die Immuntherapie kaputtgemacht?' Der Fall dreht sich weniger um einen weiteren Labortest als um Evidenzkompetenz.":"Le patient a exactement le type de tumeur pour lequel l’équipe envisage une thérapie par checkpoint : NSCLC driver négatif, PD-L1 TPS 80 %. Puis la liste des médicaments révèle qu’il a reçu sept jours d’antibiotiques à large spectre la semaine précédente. La question surgit aussitôt : « Avons-nous compromis l’immunothérapie ? » Le cas porte moins sur un test de laboratoire supplémentaire que sur la maîtrise de l’évaluation des preuves.","72-jähriger Patient mit metastasiertem pulmonalem Adenokarzinom, vollständiger DNA/RNA-Treiberdiagnostik ohne actionable Alteration und PD-L1 TPS 80 %. Unmittelbar vor geplantem ICI-Beginn wurde eine mikrobiologisch gesicherte Pneumonie leitliniengerecht antibiotisch behandelt. Das MTB soll entscheiden, ob dies die Immuntherapie verändert und wie Mikrobiomdaten klinisch korrekt begrenzt werden.":"Homme de 72 ans avec adénocarcinome pulmonaire métastatique, bilan complet des drivers ADN/ARN sans altération actionable et PD-L1 TPS 80 %. Juste avant le début prévu de l’ICI, une pneumonie confirmée microbiologiquement a été correctement traitée par antibiotiques. Le MTB doit décider si cela modifie l’immunothérapie et comment limiter correctement la portée clinique des données sur le microbiome.","Starker etablierter Tumorbiomarker":"Biomarqueur tumoral fort et établi","PD-L1 TPS 80 %, kein etablierter actionable Driver.":"PD-L1 TPS 80 %, aucun driver actionable établi.","Die Therapieplanung basiert zunächst auf validierten Tumor- und Klinikfaktoren.":"La planification thérapeutique repose d’abord sur des facteurs tumoraux et cliniques validés.","Reale Mikrobiomassoziation":"Association réelle avec le microbiome","Antibiotikaexposition um ICI-Beginn ist in Kohorten mit schlechterem Outcome assoziiert.":"L’exposition aux antibiotiques autour du début de l’ICI est associée à de moins bons résultats dans des cohortes.","Assoziation kann biologisch plausibel sein und trotzdem durch Infektion, Krankheitslast oder andere Faktoren konfundiert werden.":"Une association peut être biologiquement plausible tout en étant confondue par l’infection, la charge de maladie ou d’autres facteurs.","Klinische Indikation zählt":"L’indication clinique compte","Die Pneumonie war gesichert und behandlungsbedürftig.":"La pneumonie était confirmée et nécessitait un traitement.","Ein notwendiges Antibiotikum wird nicht dadurch falsch, dass es möglicherweise das Mikrobiom beeinflusst.":"Un antibiotique nécessaire ne devient pas inapproprié simplement parce qu’il peut influencer le microbiome.","DNA/RNA-Treiberprofil":"Profil des drivers ADN/ARN","Kein etablierter actionable Driver.":"Aucun driver actionable établi.","Sieben Tage wegen gesicherter bakterieller Pneumonie; Infektion jetzt abgeheilt.":"Sept jours pour pneumonie bactérienne confirmée ; infection désormais résolue.","Restmaterial ist knapp; zusätzliche Tumortests beantworten die Mikrobiomfrage nicht valide.":"Le matériel restant est limité ; des tests tumoraux supplémentaires ne répondent pas valablement à la question du microbiome.","Der Simulator enthält bewusst keinen 'Mikrobiom-ICI-Freigabetest', weil hierfür kein etablierter Routineassay mit validiertem Cutoff existiert.":"Le simulateur ne comporte délibérément aucun « test d’autorisation ICI par le microbiome », car il n’existe pas de test de routine établi avec seuil validé pour cet objectif.","Die entscheidende Zusatzinformation ist klinisch: Indikation, Zeitpunkt, Dauer und Infektionsstatus.":"L’information complémentaire décisive est clinique : indication, calendrier, durée et statut infectieux.","Was lässt sich aus der Beobachtung 'Antibiotika um ICI-Beginn sind mit schlechterem Outcome assoziiert' für diesen Patienten ableiten?":"Que peut-on déduire pour ce patient de l’observation selon laquelle « les antibiotiques autour du début de l’ICI sont associés à de moins bons résultats » ?","Es ist ein relevanter möglicher Risiko-/Biologiekontext, aber kein kausaler individueller Resistenztest; Confounding durch Infektion und Krankheitsstatus muss bedacht werden.":"C’est un contexte possible pertinent de risque/biologie, mais pas un test causal de résistance individuelle ; il faut tenir compte des facteurs de confusion liés à l’infection et à l’état de la maladie.","Antibiotika beweisen, dass ICI nicht mehr wirken kann.":"Les antibiotiques prouvent que l’ICI ne peut plus fonctionner.","Beobachtungsdaten sind grundsätzlich wertlos und dürfen nie erwähnt werden.":"Les données observationnelles sont fondamentalement sans valeur et ne doivent jamais être mentionnées.","ICI muss nach jeder Antibiotikagabe zwingend für einen festen Zeitraum verschoben werden.":"L’ICI doit obligatoirement être reportée pendant une durée fixe après toute antibiothérapie.","Beobachtungsassoziationen sind klinisch relevant, aber nicht gleichbedeutend mit kausaler patientenindividueller Vorhersage.":"Les associations observationnelles sont cliniquement pertinentes, mais ne valent pas prédiction causale propre au patient.","War die Antibiotikatherapie onkologisch ein Fehler?":"L’antibiothérapie était-elle une erreur oncologique ?","Nein. Eine gesicherte bakterielle Pneumonie musste behandelt werden; unnötige Antibiotika sollten vermieden werden, notwendige aber nicht aus Mikrobiomangst vorenthalten werden.":"Non. La pneumonie bactérienne confirmée nécessitait un traitement ; les antibiotiques inutiles doivent être évités, mais un traitement nécessaire ne doit pas être refusé par crainte d’effets sur le microbiome.","Ja. Vor ICI dürfen Antibiotika nie gegeben werden.":"Oui. Les antibiotiques ne doivent jamais être administrés avant l’ICI.","Nur wenn gleichzeitig FMT gegeben wird, war sie vertretbar.":"Elle n’était acceptable qu’à condition d’administrer une FMT simultanément.","Bei PD-L1 80 % ist eine Infektionsbehandlung generell unwichtig.":"Avec un PD-L1 à 80 %, traiter une infection est généralement sans importance.","Patientensicherheit und Behandlung einer realen Infektion haben Vorrang vor nicht validierter Mikrobiomoptimierung.":"La sécurité du patient et le traitement d’une infection réelle priment sur une optimisation non validée du microbiome.","Soll jetzt routinemäßig ein Mikrobiomtest, Probiotikum oder FMT zur 'Rettung' der ICI-Wirkung veranlasst werden?":"Faut-il désormais prescrire en routine un test du microbiome, un probiotique ou une FMT pour « sauver » l’efficacité de l’ICI ?","Nein. Solche Strategien sind derzeit nicht als routinemäßige patientenindividuelle Kompensation validiert und gehören gegebenenfalls in Studien.":"Non. Ces stratégies ne sont actuellement pas validées comme compensation individualisée de routine et, si elles sont envisagées, relèvent des essais cliniques.","FMT ist nach Antibiotika vor ICI Standard.":"La FMT est standard après antibiotiques avant ICI.","Ein frei verkäufliches Probiotikum ist evidenzbasiert obligat.":"Un probiotique en vente libre est fondé sur les preuves et obligatoire.","Ein einzelnes 16S-Profil kann zuverlässig die ICI-Wirkung vorhersagen.":"Un profil 16S unique peut prédire de manière fiable l’efficacité de l’ICI.","Mikrobiominterventionen sind ein Forschungsfeld, kein etablierter Routinealgorithmus zur ICI-Freigabe.":"Les interventions sur le microbiome relèvent de la recherche, pas d’un algorithme de routine établi pour autoriser l’ICI.","Welche Information sollte die Therapieentscheidung stärker tragen?":"Quelle information doit peser davantage dans la décision thérapeutique ?","Validierter NSCLC-Kontext aus Histologie, vollständigem Driverprofil, PD-L1, Klinik und Infektionsstatus; Antibiotikaexposition als zusätzlicher Unsicherheits-/Risikokontext.":"Contexte NSCLC validé à partir de l’histologie, du profil complet des drivers, du PD-L1, de l’état clinique et infectieux ; exposition antibiotique comme contexte supplémentaire d’incertitude/risque.","Allein die Antibiotikaexposition.":"L’exposition aux antibiotiques seule.","Ein zusätzlicher TMB-Wert unabhängig von PD-L1 und Driverstatus.":"Une valeur TMB supplémentaire indépendamment du PD-L1 et du statut des drivers.","Ein experimentelles Darmmikrobiomprofil.":"Un profil expérimental du microbiome intestinal.","Evidenzhierarchie verhindert, dass ein interessanter Forschungsmarker etablierte Therapiebiomarker verdrängt.":"Une hiérarchie des preuves empêche qu’un marqueur de recherche intéressant supplante des biomarqueurs thérapeutiques établis.","Formulieren Sie eine MTB-Empfehlung, die die Antibiotika-/Mikrobiomassoziation ernst nimmt, aber die individuelle Therapieentscheidung auf validierte NSCLC-Biomarker und den aktuellen klinischen Zustand stützt.":"Formulez une recommandation MTB qui prend au sérieux l’association antibiotiques/microbiome, tout en fondant la décision thérapeutique individuelle sur des biomarqueurs validés du NSCLC et l’état clinique actuel.","Driver-negatives NSCLC und PD-L1 TPS 80 % als validierten Tumorkontext priorisieren.":"Prioriser le contexte tumoral validé : NSCLC driver négatif et PD-L1 TPS 80 %.","Antibiotikaexposition zeitlich und indikationsbezogen dokumentieren.":"Documenter l’exposition antibiotique avec son calendrier et son indication.","Assoziation mit schlechterem ICI-Outcome als Beobachtungsbefund mit möglichem Confounding erklären.":"Expliquer l’association avec de moins bons résultats sous ICI comme une observation susceptible de facteurs de confusion.","Notwendige Infektionsbehandlung nicht als Fehler darstellen.":"Ne pas présenter le traitement nécessaire de l’infection comme une erreur.","Keine absolute ICI-Kontraindikation oder fixe Wartezeit allein aus Antibiotika ableiten.":"Ne pas déduire des seuls antibiotiques une contre-indication absolue à l’ICI ni un délai d’attente fixe.","Keine routinemäßigen Mikrobiomtests/Probiotika/FMT außerhalb validierter Indikation bzw. klinischer Studien empfehlen.":"Ne pas recommander en routine tests du microbiome/probiotiques/FMT hors indication validée ou essai clinique.","Wenn nach Abheilung der Infektion klinische Gründe für eine kurze Verzögerung bestehen, diese klinisch und nicht als 'Mikrobiom-Washout' begründen.":"S’il existe des raisons cliniques pour un bref délai après résolution de l’infection, les justifier cliniquement plutôt que comme un « washout du microbiome ».","Mikrobiomstudie anbieten, sofern verfügbar und ohne die Standardtherapie unangemessen zu verzögern.":"Proposer une étude sur le microbiome si elle est disponible, sans retarder indûment le traitement standard.","Antibiotika = absolute ICI-Kontraindikation":"Antibiotiques = contre-indication absolue à l’ICI","Dafür existiert kein validierter patientenindividueller Entscheidungsalgorithmus.":"Il n’existe pas d’algorithme décisionnel validé propre au patient pour cela.","Notwendige Infektion unbehandelt lassen":"Laisser non traitée une infection nécessitant un traitement","Patientensicherheit und Infektionskontrolle haben Vorrang.":"La sécurité du patient et le contrôle de l’infection sont prioritaires.","FMT/Probiotika als Routine":"FMT/probiotiques en routine","Experimentelle Interventionen dürfen nicht als Standard verkauft werden.":"Les interventions expérimentales ne doivent pas être présentées comme un standard de soins.","Mehr Tumortests bestellen":"Demander davantage de tests tumoraux","TMB/TILs quantifizieren keinen individuellen Antibiotika-Mikrobiomeffekt.":"TMB/TIL ne quantifient pas un effet individuel antibiotiques-microbiome.","Das Antibiotikum war möglicherweise biologisch ungünstig – und trotzdem medizinisch richtig":"L’antibiotique a pu être biologiquement défavorable — tout en restant médicalement approprié","Die Literaturassoziation ist plausibel und soll nicht weggewischt werden. Gleichzeitig war die Pneumonie mikrobiologisch gesichert und behandlungsbedürftig. Der zentrale Twist ist daher epistemisch: Ein möglicher negativer Biomarker-/Expositionskontext macht eine notwendige Behandlung nicht falsch und liefert keine validierte individuelle ICI-Kontraindikation.":"L’association rapportée dans la littérature est plausible et ne doit pas être balayée. Dans le même temps, la pneumonie était confirmée microbiologiquement et nécessitait un traitement. Le twist central est donc épistémique : un contexte de biomarqueur/exposition potentiellement défavorable ne rend pas erroné un traitement nécessaire et ne fournit pas de contre-indication individuelle validée à l’ICI.","Der Fall trainiert Evidenzstufen, Confounding und die Fähigkeit, populationsbasierte Forschung nicht in überharte Einzelpatientenregeln zu übersetzen.":"Ce cas entraîne à la gradation des preuves, aux facteurs de confusion et à la capacité de ne pas transformer la recherche populationnelle en règles trop rigides pour un patient donné.","Evidenz sauber begrenzt":"Portée des preuves correctement limitée","Driver-negatives NSCLC, PD-L1 TPS 80 %. Antibiotika wegen gesicherter Pneumonie waren notwendig. Exposition als möglicher Outcome-Kontext erwähnen, aber keine absolute ICI-Kontraindikation oder Mikrobiom-Routineintervention ableiten.":"NSCLC driver négatif, PD-L1 TPS 80 %. Les antibiotiques pour pneumonie confirmée étaient nécessaires. Mentionner l’exposition comme contexte possible d’issue, sans en déduire une contre-indication absolue à l’ICI ni une intervention de routine sur le microbiome.","Validierte Biomarker und unsichere Exposition korrekt gewichtet.":"Biomarqueurs validés et exposition incertaine correctement pondérés.","Assoziation erkannt, aber zu viel Unsicherheit":"Association reconnue, mais trop d’incertitude","Antibiotikadaten werden erwähnt, die Therapie wird jedoch ohne belastbare Grundlage allein deshalb unbestimmt verschoben.":"Les données sur les antibiotiques sont mentionnées, mais le traitement est ensuite reporté indéfiniment sur ce seul motif, sans base solide.","Beobachtungsdaten zu stark operationalisiert.":"Données observationnelles sur-opérationnalisées.","ICI gestrichen, FMT empfohlen":"ICI annulée, FMT recommandée","Antibiotika werden als Beweis für ICI-Resistenz behandelt und FMT/Probiotika als Routine empfohlen.":"Les antibiotiques sont considérés comme preuve de résistance à l’ICI et FMT/probiotiques sont recommandés en routine.","Evidenzniveau und Patientensicherheit verfehlt.":"Niveau de preuve et sécurité du patient non respectés.","Infektion klinisch abgeheilt":"Infection cliniquement résolue","Systemtherapie nach regulären onkologischen Kriterien planen; keine fixe 'Mikrobiom-Wartezeit' erfinden.":"Planifier le traitement systémique selon les critères oncologiques habituels ; ne pas inventer un « délai d’attente microbiome » fixe.","Die Therapie wird nicht aufgrund unvalidierter Surrogate unangemessen verzögert.":"Le traitement n’est pas retardé à tort en raison de marqueurs substitutifs non validés.","künftige Antibiotikafrage":"Question future sur les antibiotiques","Antibiotic stewardship: unnötige Exposition vermeiden, notwendige Infektionen zielgerichtet behandeln.":"Antibiotic stewardship : éviter les expositions inutiles et traiter de manière ciblée les infections qui le nécessitent.","Pragmatische Risikoreduktion ohne Pseudopräzision.":"Réduction pragmatique du risque sans pseudo-précision.","Mikrobiomstudie verfügbar":"Étude sur le microbiome disponible","Teilnahme als Forschungsoption diskutieren.":"Discuter la participation comme option de recherche.","Innovative Ansätze bleiben im passenden Evidenzrahmen.":"Les approches innovantes restent dans le cadre de preuve approprié.","Antibiotikaexposition um ICI ist in Beobachtungsdaten mit schlechteren Outcomes assoziiert, aber Confounding ist relevant.":"L’exposition aux antibiotiques autour de l’ICI est associée à de moins bons résultats dans les données observationnelles, mais les facteurs de confusion sont importants.","Eine klinisch notwendige Antibiotikatherapie darf nicht aus Angst vor Mikrobiomeffekten vorenthalten werden.":"Une antibiothérapie cliniquement nécessaire ne doit pas être refusée par crainte d’effets sur le microbiome.","Es gibt keinen etablierten Routine-Mikrobiomtest, der nach Antibiotika die individuelle ICI-Wirkung freigibt oder ausschließt.":"Il n’existe pas de test de routine établi du microbiome permettant d’autoriser ou d’exclure l’efficacité individuelle de l’ICI après antibiotiques.","FMT/Probiotika zur ICI-Optimierung sind Forschungsansätze, keine Standardkompensation.":"FMT/probiotiques pour optimiser l’ICI sont des approches de recherche, pas une compensation standard.","Präzisionsonkologie bedeutet auch, Evidenzgrenzen präzise zu kommunizieren.":"L’oncologie de précision signifie aussi communiquer avec précision les limites des preuves.","PD-L1 TPS 80 % bei driver-negativem NSCLC bleibt ein etablierter Therapiebiomarkerkontext. Die kürzlich notwendige Antibiotikatherapie ist als möglicher Outcome-Kontext relevant, aber keine validierte individuelle Kontraindikation. Keine unvalidierte fixe Wartezeit oder routinemäßige Mikrobiomintervention ableiten; unnötige Antibiotika künftig vermeiden, notwendige behandeln.":"Un PD-L1 TPS 80 % dans un NSCLC driver négatif reste un contexte établi de biomarqueur thérapeutique. L’antibiothérapie récente et nécessaire est pertinente comme contexte possible d’issue, mais non comme contre-indication individuelle validée. Ne pas déduire de délai d’attente fixe non validé ni d’intervention routinière sur le microbiome ; éviter les antibiotiques inutiles à l’avenir et traiter ceux qui sont nécessaires.","Assoziation ≠ Kausalität":"Association ≠ causalité","Confounding erkannt":"Facteurs de confusion reconnus","Patientensicherheit":"Sécurité du patient","validierte Biomarker priorisiert":"Biomarqueurs validés priorisés","keine unvalidierte Mikrobiomtherapie":"Pas de traitement du microbiome non validé","Welche Confounder erklären die Antibiotika-ICI-Assoziation möglicherweise mit?":"Quels facteurs de confusion pourraient expliquer en partie l’association antibiotiques-ICI ?","Wann wird aus einem prognostischen Faktor ein prädiktiver Biomarker?":"Quand un facteur pronostique devient-il un biomarqueur prédictif ?","Wie kommuniziert man interessante, aber nicht handlungsleitende Forschung im MTB?":"Comment communiquer au MTB une recherche intéressante mais non décisionnelle ?","notwendige Antibiotikatherapie trotz möglicher negativer Assoziation":"Antibiothérapie nécessaire malgré une association potentiellement défavorable","Populationsassoziation ist keine individuelle Kontraindikation":"Une association populationnelle n’est pas une contre-indication individuelle","validierte Tumorbiomarker → Antibiotikaindikation → Evidenzgrad → keine Pseudopräzision":"biomarqueurs tumoraux validés → indication antibiotique → niveau de preuve → pas de pseudo-précision","IDH-mutiertes Gliom: R132H-IHC negativ – und trotzdem IDH-mutiert":"Gliome IDH-muté : IHC R132H négative — et pourtant IDH-muté","IDH-mutiertes Gliom mit G-CIMP-Pro…":"Gliome IDH-muté avec profil G-CIMP…","Neuropathologie / Neuroonkologisches Tumorboard":"Neuropathologie / Tumor board neuro-oncologique","36-jähriger Patient nach Resektion eines linksfrontalen diffus infiltrierenden Glioms. Die IDH1-R132H-IHC ist negativ; Alter und Morphologie passen jedoch schlecht zu einem typischen IDH-Wildtyp-Glioblastom.":"Homme de 36 ans après résection d’un gliome diffusément infiltrant frontal gauche. L’IHC IDH1 R132H est négative ; toutefois, l’âge et la morphologie concordent mal avec un glioblastome IDH-wildtype typique.","Darf der Tumor nach negativer R132H-IHC als IDH-Wildtyp eingeordnet werden – und welche Rolle spielt das Methylierungsprofil?":"Peut-on classer la tumeur comme IDH-wildtype après une IHC R132H négative — et quel rôle joue le profil de méthylation ?","Die integrierte Diagnose soll vor Festlegung der adjuvanten Therapie finalisiert werden.":"Le diagnostic intégré doit être finalisé avant de déterminer le traitement adjuvant.","Erstmanifestation mit fokalem Krampfanfall; MRT zeigt einen nicht kontrastmittelaufnehmenden frontalen Tumor.":"Présentation initiale par crise focale ; l’IRM montre une tumeur frontale non rehaussée.","36 Jahre – damit ist eine nicht-kanonische IDH-Alteration klinisch relevant genug, um nach negativer R132H-IHC nicht vorschnell abzubrechen.":"36 ans — une altération IDH non canonique est suffisamment pertinente cliniquement pour ne pas s’arrêter prématurément après une IHC R132H négative.","ATRX-Verlust und diffuse p53-Überexpression; 1p/19q-Kodeletion nicht nachweisbar.":"Perte d’ATRX et surexpression diffuse de p53 ; aucune codélétion 1p/19q détectée.","Eine negative mutationsspezifische IHC wird mit einem negativen Genstatus gleichgesetzt.":"Un résultat IHC négatif spécifique d’une mutation est assimilé à un statut génique négatif.","Diffus infiltrierendes astrozytäres Gliom, mäßige Zelldichte, keine Nekrosen oder mikrovaskuläre Proliferation.":"Gliome astrocytaire diffusément infiltrant, cellularité modérée, sans nécrose ni prolifération microvasculaire.","IDH1 R132H negativ; ATRX nukleär verloren; p53 in großer Tumorzellfraktion stark positiv.":"IDH1 R132H négatif ; perte nucléaire d’ATRX ; forte positivité p53 dans une grande fraction des cellules tumorales.","Molekulare Vorinformation":"Informations moléculaires antérieures","1p/19q intakt.":"1p/19q intact.","Nicht-kanonische IDH1/2-Mutation? Passt das epigenetische Gesamtprofil zu einem IDH-mutierten Astrozytom?":"Mutation IDH1/2 non canonique ? Le profil épigénétique global correspond-il à un astrocytome IDH-muté ?","FFPE-Resektat, Block F6.":"Pièce de résection FFPE, bloc F6.","ca. 70 %, sehr gut geeignet.":"env. 70 %, très bien adapté.","ausreichend für Sequenzierung und Methylierungsprofil.":"suffisant pour séquençage et profil de méthylation.","Eine fokale Bisulfit-PCR kann einzelne CpG-Loci untersuchen, ersetzt aber keinen genomeweiten CNS-Methylierungsclassifier.":"Une PCR bisulfite ciblée peut étudier des loci CpG individuels, mais ne remplace pas un classificateur de méthylation CNS à l’échelle du génome.","IDH1/2-Status vollständig klären":"Clarifier complètement le statut IDH1/2","CNS-Methylierungsprofil / Classifier":"Profil de méthylation CNS / classificateur","IDH1-R132H-IHC negativ; Sequenzierung zeigt eine pathogene nicht-kanonische IDH1-p.R132C-Mutation. Die negative R132H-IHC war daher kein Ausschluss eines IDH-mutierten Glioms.":"IHC IDH1 R132H négative ; le séquençage met en évidence une mutation pathogène non canonique IDH1 p.R132C. L’IHC R132H négative n’excluait donc pas un gliome IDH-muté.","Methylierungsclassifier":"Classificateur de méthylation","Genomeweites Methylierungsprofil mit hochkonfidenter Zuordnung zur Familie der IDH-mutierten Astrozytome und ausgeprägtem G-CIMP-typischem Hypermethylierungsmuster.":"Profil de méthylation à l’échelle du génome avec attribution de haute confiance à la famille des astrocytomes IDH-mutés et profil d’hyperméthylation marqué de type G-CIMP.","Fokale Bisulfit-PCR":"PCR bisulfite ciblée","Ein fokaler Methylierungsmarker ist messbar, erlaubt aber keine gleichwertige globale Tumorklassifikation und ist kein Ersatz für den CNS-Methylierungsclassifier.":"Un marqueur de méthylation ciblé peut être mesuré, mais ne fournit pas une classification tumorale globale équivalente et ne remplace pas le classificateur de méthylation CNS.","Breites Panel":"Panel large","Zusätzliche Varianten ändern die zentrale integrierte Einordnung nicht; der breite Ansatz ist für die konkrete Klassifikationsfrage nicht zwingend erforderlich.":"Les variants supplémentaires ne modifient pas la classification intégrée centrale ; une approche large n’est pas indispensable pour la question de classification spécifique.","Diffus infiltrierendes Astrozytom mit ATRX-Verlust und p53-Akkumulation; keine hochgradigen morphologischen Kriterien.":"Astrocytome diffusément infiltrant avec perte d’ATRX et accumulation de p53 ; sans critères morphologiques de haut grade.","Tumoranteil und DNA-Qualität für Sequenzierung und Methylom geeignet.":"Fraction tumorale et qualité de l’ADN adaptées au séquençage et à l’analyse du méthylome.","Die negative IDH1-R132H-IHC schließt bei diesem jungen Patienten eine IDH-Mutation nicht aus. Die Sequenzierung weist eine nicht-kanonische IDH1-p.R132C-Mutation nach; das genomeweite Methylierungsprofil unterstützt einen IDH-mutierten astrozytären Tumor und zeigt das erwartete G-CIMP-artige Hypermethylierungsmuster. Der Methylierungsclassifier ergänzt die integrierte Diagnose, ersetzt aber nicht Histologie und definierende molekulare Marker.":"L’IHC IDH1 R132H négative n’exclut pas une mutation IDH chez ce jeune patient. Le séquençage identifie une mutation non canonique IDH1 p.R132C ; le profil de méthylation à l’échelle du génome soutient une tumeur astrocytaire IDH-mutée et montre le profil d’hyperméthylation attendu de type G-CIMP. Le classificateur de méthylation complète le diagnostic intégré, mais ne remplace pas l’histologie ni les marqueurs moléculaires définissant l’entité.","Teilbefund: Eine negative R132H-IHC allein reicht nicht, um den IDH-Status in diesem klinisch-morphologischen Kontext sicher festzulegen.":"Résultat partiel : une IHC R132H négative seule ne suffit pas à établir avec certitude le statut IDH dans ce contexte clinico-morphologique.","R132H-IHC negativ nicht mit IDH1/2-Wildtyp gleichsetzen":"Ne pas assimiler une IHC R132H négative à IDH1/2 wildtype","Bei passendem Kontext Sequenzierung nicht-kanonischer IDH1/2-Varianten einfordern":"Dans le contexte approprié, demander un séquençage des variants IDH1/2 non canoniques","Methylierungsclassifier als integrativen Klassifikationsbaustein einordnen":"Considérer le classificateur de méthylation comme un élément diagnostique intégratif","G-CIMP als biologisches/epigenetisches Muster erklären, nicht als isolierten Routinetest":"Expliquer G-CIMP comme un profil biologique/épigénétique, et non comme un test de routine isolé","Falschaussage: negative R132H-IHC beweist IDH-Wildtyp":"Affirmation fausse : une IHC R132H négative prouve un statut IDH wildtype","Optimale Lösung: R132H-IHC als Screening verstehen, nicht-kanonische IDH1/2-Mutationen bei passendem Kontext sequenzieren und das Methylom als integrativen, nicht alleinstehenden Klassifikationsbaustein verwenden.":"Solution optimale : comprendre l’IHC R132H comme un dépistage, séquencer les mutations IDH1/2 non canoniques dans le contexte approprié et utiliser le méthylome comme composant intégratif, non autonome, de la classification.","Gliom":"Gliome","IDH1":"IDH1","non-canonical IDH":"IDH non canonique","G-CIMP":"G-CIMP","Astrozytom":"Astrocytome","R132H negativ – aber nicht IDH-Wildtyp":"R132H négatif — mais pas IDH wildtype","Neuropathologie / Neuroonkologie / MTB":"Neuropathologie / Neuro-oncologie / MTB","IDH1-R132H-IHC als Screening und nicht als vollständigen IDH1/2-Ausschluss verstehen.":"Comprendre l’IHC IDH1 R132H comme un dépistage et non comme une exclusion complète des altérations IDH1/2.","Bei jungem Patienten und passender Morphologie nicht-kanonische IDH1/2-Varianten sequenzieren.":"Chez un patient jeune avec morphologie compatible, séquencer les variants IDH1/2 non canoniques.","G-CIMP als Folge der IDH-Biologie und nicht als isolierte Diagnose interpretieren.":"Interpréter G-CIMP comme une conséquence de la biologie IDH et non comme un diagnostic isolé.","Genomeweiten Methylierungsclassifier von fokaler Methylierungs-PCR unterscheiden.":"Distinguer un classificateur de méthylation à l’échelle du génome d’une PCR de méthylation ciblée.","Histologie, definierende Marker und Methylom zu einer integrierten Diagnose zusammenführen.":"Combiner histologie, marqueurs définissant l’entité et méthylome dans un diagnostic intégré.","Die IDH1-R132H-IHC ist negativ. Der Patient ist aber 36, der Tumor sieht diffus astrozytär aus, ATRX ist verloren und 1p/19q intakt. Der vermeintlich einfache 'IDH-Wildtyp'-Stempel beginnt zu wackeln.":"L’IHC IDH1 R132H est négative. Mais le patient a 36 ans, la tumeur paraît diffusément astrocytaire, ATRX est perdu et 1p/19q est intact. L’étiquette apparemment simple « IDH-wildtype » commence à vaciller.","36-jähriger Patient mit linksfrontalem diffus infiltrierendem Gliom. R132H-IHC negativ, ATRX-Verlust und p53-Akkumulation. Das Board muss entscheiden, ob weiter sequenziert wird und wie ein G-CIMP-/Methylierungsprofil die integrierte Diagnose unterstützt.":"Homme de 36 ans avec gliome diffusément infiltrant frontal gauche. IHC R132H négative, perte d’ATRX et accumulation de p53. Le board doit décider s’il faut poursuivre le séquençage et comment un profil G-CIMP/de méthylation soutient le diagnostic intégré.","Screening ist nicht Sequenzierung":"Le dépistage n’est pas le séquençage","R132H-IHC erkennt die häufigste IDH1-Variante, nicht jede IDH1/2-Mutation.":"L’IHC R132H détecte le variant IDH1 le plus fréquent, pas toutes les mutations IDH1/2.","Ein negatives mutationsspezifisches Antikörperergebnis ist kein vollständiger Gen-Ausschluss.":"Un résultat négatif avec un anticorps spécifique d’une mutation ne constitue pas une exclusion complète au niveau du gène.","Alter + Morphologie zählen":"Âge + morphologie comptent","Junger Erwachsener, diffus astrozytärer Tumor, ATRX-Verlust.":"Jeune adulte, tumeur diffusément astrocytaire, perte d’ATRX.","Prätestwahrscheinlichkeit bestimmt, wann Sequenzierung trotz negativer IHC sinnvoll ist.":"La probabilité pré-test détermine quand le séquençage est utile malgré une IHC négative.","Epigenom als Integrator":"Épigénome comme intégrateur","IDH-Mutationen erzeugen ein charakteristisches Hypermethylierungsprogramm.":"Les mutations IDH génèrent un programme caractéristique d’hyperméthylation.","Das Methylom unterstützt Klassifikation, ersetzt aber definierende Marker nicht.":"Le méthylome soutient la classification, mais ne remplace pas les marqueurs définissant l’entité.","IDH1-R132H-IHC":"IHC IDH1 R132H","ATRX/p53":"ATRX/p53","ATRX-Verlust, diffuse p53-Akkumulation":"Perte d’ATRX, accumulation diffuse de p53","1p/19q":"1p/19q","keine Kodeletion":"pas de codélétion","Tumoranteil ca. 70 %, DNA gut.":"Fraction tumorale env. 70 %, ADN de bonne qualité.","Keine Materialnot – die Herausforderung ist Testhierarchie, nicht Schnittökonomie.":"Pas de pénurie de matériel — le défi est la hiérarchie des tests, pas l’économie des coupes.","Fokale Bisulfit-PCR ist kein Ersatz für genomeweite Klassifikation.":"La PCR bisulfite ciblée ne remplace pas la classification à l’échelle du génome.","Was ist der wichtigste Schluss aus negativer IDH1-R132H-IHC?":"Quelle est la conclusion la plus importante d’une IHC IDH1 R132H négative ?","Bei passendem klinisch-morphologischem Kontext IDH1/2 sequenzieren, weil nicht-kanonische Mutationen übersehen werden können.":"Dans le contexte clinico-morphologique approprié, séquencer IDH1/2 car des mutations non canoniques peuvent être manquées.","IDH-Wildtyp ist sicher bewiesen.":"Le statut IDH wildtype est définitivement prouvé.","Nur Methylierungsclassifier durchführen; Sequenzierung ist überflüssig.":"Réaliser uniquement le classificateur de méthylation ; le séquençage est inutile.","IDH ist bei Erwachsenen diagnostisch nicht relevant.":"IDH n’est pas pertinent pour le diagnostic chez l’adulte.","R132H-IHC ist hoch nützlich, aber mutationsspezifisch.":"L’IHC R132H est très utile, mais spécifique de la mutation.","Was bedeutet ein G-CIMP-artiges Profil am ehesten?":"Que signifie le plus probablement un profil de type G-CIMP ?","Es ist ein epigenetisches Muster, das zur IDH-mutierten Biologie passt und die integrierte Klassifikation stützt.":"Il s’agit d’un profil épigénétique compatible avec la biologie IDH-mutée et qui soutient la classification intégrée.","Es definiert allein den WHO-Grad.":"Il définit à lui seul le grade OMS.","Es ist ein eigenständiger zugelassener Therapietest.":"C’est un test thérapeutique autonome approuvé.","Es beweist eine Keimbahn-IDH-Mutation.":"Il prouve une mutation germinale IDH.","G-CIMP ist biologischer/klassifikatorischer Kontext, kein alleiniger Therapie- oder Gradmarker.":"G-CIMP est un contexte biologique/classificatoire, pas un marqueur autonome de traitement ou de grade.","Welche Aussage zum Methylierungsclassifier ist korrekt?":"Quelle affirmation sur le classificateur de méthylation est correcte ?","Genomeweites Profil kann diagnostisch stark sein, muss aber mit Histologie, QC und definierenden molekularen Markern integriert werden.":"Un profil à l’échelle du génome peut être diagnostiquement puissant, mais doit être intégré à l’histologie, au QC et aux marqueurs moléculaires définissant l’entité.","Der höchste Klassenname ist immer die Diagnose.":"Le nom de la classe la plus élevée est toujours le diagnostic.","Eine fokale Bisulfit-PCR ist gleichwertig.":"Une PCR bisulfite ciblée est équivalente.","Methylom ersetzt IDH-Sequenzierung.":"L’analyse du méthylome remplace le séquençage IDH.","Classifier ist stark, aber integrativ.":"Le classificateur est puissant, mais intégratif.","Sequenzierung zeigt IDH1 p.R132C. Was kippt dadurch?":"Le séquençage montre IDH1 p.R132C. Qu’est-ce que cela change ?","Der Tumor ist IDH-mutiert; die negative R132H-IHC war ein Screening-False-negative für diese nicht-kanonische Variante.":"La tumeur est IDH-mutée ; l’IHC R132H négative était un faux négatif de dépistage pour ce variant non canonique.","Die Sequenzierung muss falsch sein, weil die IHC negativ war.":"Le séquençage doit être faux puisque l’IHC était négative.","IDH-Status bleibt Wildtyp.":"Le statut IDH reste wildtype.","Es folgt Keimbahndiagnostik auf Lynch.":"Poursuivre par une analyse germinale du syndrome de Lynch.","Nicht-kanonische IDH-Varianten sind der zentrale Twist.":"Les variants IDH non canoniques constituent le twist central.","Formulieren Sie die integrierte neuropathologische Kernaussage und begründen Sie, warum nach negativer R132H-IHC sequenziert wurde und wie das Methylom gewichtet wird.":"Formulez la conclusion neuropathologique intégrée et expliquez pourquoi un séquençage a été réalisé après une IHC R132H négative et comment le méthylome est pondéré.","R132H-IHC als Screening einordnen.":"Considérer l’IHC R132H comme un test de dépistage.","Nicht-kanonische IDH1/2-Sequenzierung bei hoher Prätestwahrscheinlichkeit durchführen.":"Réaliser un séquençage des variants IDH1/2 non canoniques lorsque la probabilité pré-test est élevée.","IDH1 p.R132C als definierenden Befund anerkennen.":"Reconnaître IDH1 p.R132C comme résultat définissant l’entité.","Methylierungsprofil/G-CIMP als konsistenten integrativen Baustein berichten.":"Rapporter le profil de méthylation/G-CIMP comme composant intégratif concordant.","Fokale Methylierungs-PCR nicht als gleichwertigen Classifier-Ersatz darstellen.":"Ne pas présenter la PCR de méthylation ciblée comme un substitut équivalent du classificateur.","Auf Methylierungsclassifier verzichten, wenn Histologie und definierende molekulare Marker bereits eindeutig sind; in diesem Fall ist er didaktisch/klassifikatorisch zusätzlich hilfreich.":"Le classificateur de méthylation peut être omis lorsque l’histologie et les marqueurs moléculaires définissant l’entité sont déjà sans ambiguïté ; dans ce cas, il apporte un intérêt pédagogique/classificatoire supplémentaire.","Breites Panel nur bei zusätzlicher klinischer Fragestellung.":"Utiliser un panel large uniquement en présence d’une question clinique supplémentaire.","R132H-negativ = IDH-WT":"R132H négatif = IDH-WT","Mutationsspezifische IHC erfasst nicht alle IDH1/2-Varianten.":"L’IHC spécifique d’une mutation ne détecte pas tous les variants IDH1/2.","Classifier statt Sequenzierung":"Classificateur à la place du séquençage","Definierende Genalteration und epigenetische Klasse sind unterschiedliche Ebenen.":"Une altération génique définissant l’entité et une classe épigénétique sont des niveaux d’information différents.","G-CIMP als Therapiebiomarker":"G-CIMP comme biomarqueur thérapeutique","Das Muster ist biologisch/klassifikatorisch, nicht allein handlungsleitend.":"Le profil est biologique/classificatoire, et non décisionnel à lui seul.","Der 'negative' IDH-Test wird positiv":"Le test IDH « négatif » devient positif","Die Sequenzierung weist IDH1 p.R132C nach. Gleichzeitig ordnet der Methylierungsclassifier den Tumor hochkonfident der IDH-mutierten Astrozytomfamilie zu. Der Twist ist kein Laborwiderspruch, sondern zeigt die Grenze einer mutationsspezifischen IHC.":"Le séquençage identifie IDH1 p.R132C. En parallèle, le classificateur de méthylation attribue avec une forte confiance la tumeur à la famille des astrocytomes IDH-mutés. Le twist n’est pas une contradiction de laboratoire, mais illustre la limite d’une IHC spécifique d’une mutation.","Er trainiert Prätestwahrscheinlichkeit, Methodengrenzen und integrierte CNS-Diagnostik.":"Il entraîne à la probabilité pré-test, aux limites méthodologiques et au diagnostic intégré du SNC.","Screeninggrenze erkannt":"Limite du dépistage reconnue","R132H-IHC negativ, IDH1 p.R132C sequenziert, Methylom konsistent mit IDH-mutiertem Astrozytom/G-CIMP.":"IHC R132H négative, IDH1 p.R132C détecté par séquençage, méthylome compatible avec un astrocytome IDH-muté/G-CIMP.","Methoden korrekt hierarchisiert.":"Méthodes correctement hiérarchisées.","Methylom richtig, IDH zu spät":"Méthylome correct, IDH trop tardif","Classifier wird genutzt, die notwendige IDH1/2-Sequenzierung aber nicht sauber begründet.":"Le classificateur est utilisé, mais le séquençage IDH1/2 nécessaire n’est pas correctement justifié.","Definierenden Marker nicht durch Epigenom ersetzen.":"Ne pas remplacer un marqueur définissant l’entité par l’épigénome.","IDH-Wildtyp abgestempelt":"Étiqueté IDH-wildtype","Nach negativer R132H-IHC wird keine Sequenzierung veranlasst.":"Aucun séquençage n’est demandé après une IHC R132H négative.","Zentralen methodischen Fallstrick verpasst.":"Le principal piège méthodologique est manqué.","Nicht-kanonische IDH-Mutation":"Mutation IDH non canonique","Integrierte Diagnose entsprechend IDH-mutierter Entität formulieren.":"Formuler le diagnostic intégré selon l’entité IDH-mutée.","Der Tumor verlässt den IDH-Wildtyp-Pfad.":"La tumeur sort de la voie IDH-wildtype.","Methylom diskordant":"Méthylome discordant","QC, Tumoranteil und Differenzialdiagnose erneut prüfen.":"Réévaluer le QC, la fraction tumorale et le diagnostic différentiel.","Keine automatisierte Übersteuerung der Morphologie.":"Pas d’écrasement automatique de la morphologie.","IDH1-R132H-IHC ist ein sehr gutes Screening, aber kein vollständiger IDH1/2-Ausschluss.":"L’IHC IDH1 R132H est un excellent dépistage, mais pas une exclusion complète d’IDH1/2.","Nicht-kanonische IDH-Mutationen sind besonders bei jüngeren Patienten mit passendem diffusem Gliom relevant.":"Les mutations IDH non canoniques sont particulièrement pertinentes chez les patients plus jeunes dans un contexte compatible de gliome diffus.","IDH-Biologie erzeugt charakteristische epigenetische Muster wie G-CIMP.":"La biologie IDH produit des profils épigénétiques caractéristiques tels que G-CIMP.","Methylierungsclassifier sind integrative Diagnostikwerkzeuge, keine Orakel.":"Les classificateurs de méthylation sont des outils diagnostiques intégratifs, pas des oracles.","Fokale Methylierungs-PCR und genomeweiter Classifier beantworten unterschiedliche Fragen.":"La PCR de méthylation ciblée et un classificateur à l’échelle du génome répondent à des questions différentes.","Bei diesem 36-jährigen Patienten darf die negative R132H-IHC nicht als vollständiger IDH-Wildtyp-Nachweis gelten. IDH1/2-Sequenzierung weist IDH1 p.R132C nach. Das Methylierungsprofil unterstützt die IDH-mutierte astrozytäre Klassifikation und zeigt ein G-CIMP-artiges Muster. Histologie, IDH, ATRX/p53/1p19q und Methylom werden integriert.":"Chez ce patient de 36 ans, une IHC R132H négative ne doit pas être considérée comme preuve complète d’un statut IDH-wildtype. Le séquençage IDH1/2 détecte IDH1 p.R132C. Le profil de méthylation soutient une classification astrocytaire IDH-mutée et montre un profil de type G-CIMP. Histologie, IDH, ATRX/p53/1p19q et méthylome sont intégrés.","Screeninggrenze R132H-IHC":"Limite du dépistage par IHC R132H","nicht-kanonische Sequenzierung":"Séquençage des variants non canoniques","Classifier integrativ":"Classificateur intégratif","G-CIMP korrekt eingeordnet":"G-CIMP correctement interprété","Wann reicht R132H-IHC allein?":"Quand l’IHC R132H seule suffit-elle ?","Warum ist Prätestwahrscheinlichkeit in der Molekularpathologie wichtig?":"Pourquoi la probabilité pré-test est-elle importante en pathologie moléculaire ?","Was kann ein Methylierungsclassifier, was eine fokale Bisulfit-PCR nicht kann?":"Que peut faire un classificateur de méthylation qu’une PCR bisulfite ciblée ne peut pas faire ?","IDH1 p.R132C trotz negativer R132H-IHC":"IDH1 p.R132C malgré une IHC R132H négative","Negativer Screeningtest ist nicht automatisch negativer Genstatus":"Un test de dépistage négatif n’équivaut pas automatiquement à un statut génique négatif","R132H-IHC → Sequenzierung → Methylom → integrierte Diagnose":"IHC R132H → séquençage → méthylome → diagnostic intégré","Unklarer ZNS-Tumor: Der Methylierungsclassifier hilft – aber nur bei guter Probe":"Tumeur du SNC indéterminée : le classificateur de méthylation aide — mais seulement avec un bon échantillon","Histologisch unklarer ZNS-Tumor: M…":"Tumeur du SNC histologiquement indéterminée : m…","Neuropathologie / Neuroonkologisches Referenzboard":"Neuropathologie / Board de référence neuro-oncologique","47-jährige Patientin mit einem posterior-fossären Tumor. Histologie und IHC ergeben ein ungewöhnliches gliales/ependymales Mischbild; mehrere Differenzialdiagnosen bleiben plausibel.":"Patiente de 47 ans avec tumeur de la fosse postérieure. L’histologie et l’IHC montrent un profil mixte glial/épendymaire inhabituel ; plusieurs diagnostics différentiels restent plausibles.","Kann ein DNA-Methylierungsclassifier die Diagnose klären – und wann darf ein Classifier-Ergebnis gerade nicht überinterpretiert werden?":"Un classificateur de méthylation de l’ADN peut-il clarifier le diagnostic — et quand un résultat du classificateur ne doit-il surtout pas être surinterprété ?","Die Referenzdiagnose beeinflusst Nachsorge und Therapieplanung.":"Le diagnostic de référence influence le suivi et la planification thérapeutique.","Schwindel, Gangunsicherheit und okzipitale Kopfschmerzen; MRT mit gut abgrenzbarer Raumforderung im Kleinhirn.":"Vertiges, instabilité de la marche et céphalées occipitales ; l’IRM montre une masse cérébelleuse bien circonscrite.","Voroperation":"Chirurgie antérieure","Keine bekannte Tumorerkrankung.":"Aucune maladie tumorale connue.","Pathologie":"Pathologie","Morphologie uneindeutig; IHC nicht widersprüchlich, aber nicht ausreichend spezifisch.":"La morphologie est ambiguë ; l’IHC n’est pas contradictoire, mais insuffisamment spécifique.","Ein Classifier-Score wird als maschinelles Wahrheitsurteil behandelt, unabhängig von Tumoranteil und Plausibilität.":"Un score de classificateur est traité comme une vérité machine, indépendamment de la fraction tumorale et de la plausibilité.","Piloide und stellenweise ependymale Architektur, fokale Gefäßhyalinisierung, keine eindeutige klassische Entität.":"Architecture piloïde et focalement épendymaire, hyalinisation vasculaire focale, sans entité classique sans ambiguïté.","GFAP positiv; EMA nur fokal dot-like; OLIG2 heterogen; keine sichere Linie.":"GFAP positif ; EMA seulement focalement en points ; OLIG2 hétérogène ; pas de lignée certaine.","Erste Differentialdiagnose":"Diagnostic différentiel initial","Ependymom versus astrozytärer/piloider Tumor.":"Épendymome versus tumeur astrocytaire/piloïde.","Genomeweites Methylierungsmuster und Copy-number-Kontext.":"Profil de méthylation à l’échelle du génome et contexte du nombre de copies.","Erster FFPE-Block enthält nur ca. 15 % Tumor und viel reaktives Kleinhirngewebe; zweiter Block enthält ca. 65 % Tumor.":"Le premier bloc FFPE ne contient qu’environ 15 % de tumeur et beaucoup de tissu cérébelleux réactionnel ; le second bloc contient environ 65 % de tumeur.","beide Blöcke technisch extrahierbar.":"Les deux blocs sont techniquement extractibles.","Classifier-Risiko":"Risque lié au classificateur","Niedriger Tumoranteil kann den Score und das Profil verwässern.":"Une faible fraction tumorale peut diluer le score et le profil.","Eine fokale Bisulfit-PCR beantwortet nicht die globale Klassifikationsfrage.":"Une PCR bisulfite ciblée ne répond pas à une question de classification globale.","Genomeweiter CNS-Methylierungsclassifier":"Classificateur de méthylation CNS à l’échelle du génome","Classifier – Block mit wenig Tumor":"Classificateur — bloc pauvre en tumeur","Erste Analyse aus dem tumorarmen Block liefert nur eine niedrig-konfidente, biologisch wenig plausible Zuordnung unterhalb des lokal validierten Freigabebereichs. Kein belastbarer Klassenruf.":"La première analyse du bloc pauvre en tumeur ne fournit qu’une attribution de faible confiance, biologiquement peu plausible et sous le seuil local validé de compte rendu. Aucun appel de classe fiable.","Classifier – tumorangereicherter Block":"Classificateur — bloc enrichi en tumeur","Nach Auswahl des tumorreichen Blocks ergibt sich eine hochkonfidente Zuordnung zur Methylierungsfamilie 'High-grade astrocytoma with piloid features' mit passendem Copy-number-Profil.":"Après sélection du bloc riche en tumeur, une attribution de haute confiance à la famille de méthylation « High-grade astrocytoma with piloid features » est obtenue, avec un profil du nombre de copies concordant.","Lokale CpG-Methylierung nachweisbar, aber diagnostisch nicht ausreichend zur genomeweiten Klassifikation.":"La méthylation locale des CpG est détectable, mais diagnostiquement insuffisante pour une classification à l’échelle du génome.","Molekulare Zusatzbefunde können die Plausibilität stützen, ersetzen aber bei diesem morphologisch schwierigen Fall den validierten Methylierungsclassifier nicht.":"Des résultats moléculaires supplémentaires peuvent renforcer la plausibilité, mais ne remplacent pas le classificateur de méthylation validé dans ce cas morphologiquement difficile.","Histologisch uneindeutiger posterior-fossärer glialer Tumor.":"Tumeur gliale de la fosse postérieure histologiquement ambiguë.","Es stehen ein tumorarmer und ein deutlich tumorreicherer Block zur Verfügung.":"Un bloc pauvre en tumeur et un bloc nettement plus riche en tumeur sont disponibles.","Der CNS-Methylierungsclassifier ist bei morphologisch unklaren Tumoren besonders wertvoll, sein Ergebnis muss aber zusammen mit Tumoranteil, QC, Score, Copy-number-Profil und Histologie bewertet werden. Der erste niedrig-konfidente Lauf aus tumorarmem Material ist nicht berichtsfähig; die Wiederholung aus tumorreichem Material liefert eine plausible hochkonfidente Klassifikation.":"Le classificateur de méthylation CNS est particulièrement utile dans les tumeurs morphologiquement indéterminées, mais son résultat doit être évalué avec la fraction tumorale, le QC, le score, le profil du nombre de copies et l’histologie. Le premier run de faible confiance sur matériel pauvre en tumeur n’est pas rapportable ; la répétition sur matériel riche en tumeur fournit une classification plausible de haute confiance.","Teilbefund: Ein niedrig-konfidentes Classifier-Ergebnis aus tumorarmem Material darf nicht als definitive Diagnose ausgegeben werden.":"Résultat partiel : un résultat de classificateur de faible confiance issu d’un matériel pauvre en tumeur ne doit pas être rendu comme diagnostic définitif.","Methylierungsclassifier gezielt bei diagnostisch schwierigem ZNS-Tumor einsetzen":"Utiliser de façon ciblée le classificateur de méthylation pour une tumeur du SNC diagnostiquement difficile","Tumoranteil und Classifier-QC vor Klassenruf prüfen":"Vérifier la fraction tumorale et le QC du classificateur avant tout appel de classe","Classifier mit Histologie und molekularen Zusatzdaten integrieren":"Intégrer le classificateur à l’histologie et aux données moléculaires supplémentaires","Bei unplausiblem Low-confidence-Ergebnis besseres Material wählen statt überinterpretieren":"En cas de résultat de faible confiance peu plausible, choisir un meilleur matériel plutôt que de le surinterpréter","Falschaussage: der höchste angezeigte Klassenname ist unabhängig vom Score die Diagnose":"Affirmation fausse : le nom de classe affiché le plus élevé est le diagnostic quel que soit le score","Optimale Lösung: Classifier als starken integrativen Diagnostikbaustein nutzen, aber nur aus geeignetem Material und mit validiertem Confidence-/QC-Kontext; ein Low-confidence-Ergebnis ist ein Hinweis, kein Wahrheitsurteil.":"Solution optimale : utiliser le classificateur comme un puissant composant diagnostique intégratif, mais uniquement à partir d’un matériel approprié et dans un cadre validé de confiance/QC ; un résultat de faible confiance est un indice, pas un verdict de vérité.","ZNS":"SNC","Integrated diagnosis":"Diagnostic intégré","Der Classifier ist nur so gut wie Probe und Plausibilität":"Le classificateur n’est fiable qu’à la hauteur de l’échantillon et de la plausibilité","Neuropathologie / Molekulardiagnostik / MTB":"Neuropathologie / Diagnostic moléculaire / MTB","Indikationen für CNS-Methylierungsclassification bei diagnostisch schwierigen Tumoren erkennen.":"Reconnaître les indications de la classification par méthylation du SNC dans les tumeurs diagnostiquement difficiles.","Tumoranteil, QC und Confidence/Score vor Klassenruf prüfen.":"Vérifier fraction tumorale, QC et confiance/score avant tout appel de classe.","Low-confidence-Ergebnisse nicht als definitive Diagnose ausgeben.":"Ne pas rapporter les résultats de faible confiance comme diagnostic définitif.","Bei unplausiblem Ergebnis besseres Material priorisieren.":"Prioriser un meilleur matériel lorsque le résultat est peu plausible.","Classifier, Copy-number-Profil, Histologie und Molekulargenetik integrieren.":"Intégrer classificateur, profil du nombre de copies, histologie et génétique moléculaire.","Der Computer liefert einen Klassennamen – aber aus einem Block mit nur 15 % Tumor und mit einem Score unterhalb des lokal validierten Freigabebereichs. Die Versuchung ist groß, den Namen trotzdem in den Befund zu schreiben.":"L’ordinateur fournit un nom de classe — mais à partir d’un bloc ne contenant que 15 % de tumeur et avec un score inférieur au seuil local validé de compte rendu. La tentation d’inscrire malgré tout le nom dans le rapport est forte.","47-jährige Patientin mit morphologisch uneindeutigem posterior-fossärem glialem Tumor. Zwei Blöcke unterscheiden sich massiv im Tumoranteil. Der Fall lehrt, wann Methylierungsclassification enorm hilfreich ist und wann ein scheinbares Ergebnis verworfen werden muss.":"Patiente de 47 ans avec tumeur gliale de la fosse postérieure morphologiquement ambiguë. Deux blocs diffèrent fortement par leur fraction tumorale. Le cas montre quand la classification par méthylation est extrêmement utile et quand un résultat apparent doit être rejeté.","Unklare Morphologie":"Morphologie indéterminée","Ependymal/piloid/glial überlappende Merkmale.":"Caractéristiques épendymaires/piloïdes/gliales chevauchantes.","Genau hier kann ein validierter classifier besonders wertvoll sein.":"C’est précisément ici qu’un classificateur validé peut être particulièrement précieux.","Zwei Blöcke, zwei Welten":"Deux blocs, deux mondes","15 % versus 65 % Tumoranteil.":"15 % versus 65 % de fraction tumorale.","Preanalytics beeinflusst auch digitale/epigenetische Klassifikatoren.":"La pré-analytique affecte également les classificateurs numériques/épigénétiques.","Score braucht Kontext":"Le score nécessite un contexte","Low confidence + unplausible Morphologie.":"Faible confiance + morphologie peu plausible.","Ein Output ist noch kein reportable Result.":"Une sortie n’est pas encore un résultat rapportable.","Block A":"Bloc A","ca. 15 % Tumor, viel normales Kleinhirngewebe":"env. 15 % de tumeur, beaucoup de tissu cérébelleux normal","Block B":"Bloc B","ca. 65 % Tumor":"env. 65 % de tumeur","mehrere plausible ZNS-Differenzialdiagnosen":"Plusieurs diagnostics différentiels du SNC plausibles","Classifier aus geeignetem tumorreichem Material priorisieren.":"Prioriser le classificateur à partir d’un matériel approprié riche en tumeur.","Lokaler validierter Score-/QC-Rahmen ist Teil der Befundfreigabe.":"Le cadre score/QC validé localement fait partie de la validation du compte rendu.","Fokale Bisulfit-PCR löst keine genomeweite Klassifikationsfrage.":"Une PCR bisulfite ciblée ne résout pas une question de classification à l’échelle du génome.","Wann ist der Methylierungsclassifier hier am wertvollsten?":"Quand le classificateur de méthylation est-il le plus utile ici ?","Bei persistierender diagnostischer Unsicherheit trotz Histologie/IHC und ausreichendem Material.":"Lorsque l’incertitude diagnostique persiste malgré l’histologie/IHC et qu’un matériel suffisant est disponible.","Immer als Ersatz für Histologie.":"Toujours en remplacement de l’histologie.","Nur wenn eine medikamentöse Targettherapie existiert.":"Uniquement s’il existe une thérapie ciblée.","Bei Erwachsenen grundsätzlich nicht.":"Jamais chez l’adulte.","Der größte Zusatznutzen entsteht bei schwierigen integrierten Diagnosen.":"La plus grande valeur ajoutée se situe dans les diagnostics intégrés difficiles.","Wie wird ein niedrig-konfidentes Ergebnis aus 15-%-Tumorblock behandelt?":"Comment gérer un résultat de faible confiance provenant d’un bloc à 15 % de tumeur ?","Nicht definitiv reporten; QC/Tumoranteil prüfen und besseres Material analysieren.":"Ne pas rendre de façon définitive ; vérifier QC/fraction tumorale et analyser un meilleur matériel.","Höchste Klasse trotzdem als Diagnose berichten.":"Rapporter malgré tout la classe la plus élevée comme diagnostic.","Mit HE-Diagnose mitteln.":"Faire une moyenne avec le diagnostic HE.","Score ist irrelevant.":"Le score est sans importance.","Confidence und Präanalytik sind Teil der diagnostischen Aussage.":"La confiance et la pré-analytique font partie de l’interprétation diagnostique.","Der tumorreiche Block liefert einen hochkonfidenten, morphologisch plausiblen Treffer. Was folgt?":"Le bloc riche en tumeur fournit un résultat de haute confiance, morphologiquement plausible. Quelle est la suite ?","Mit Histologie und molekularen Zusatzdaten integrieren und als starke diagnostische Evidenz nutzen.":"L’intégrer à l’histologie et aux données moléculaires supplémentaires et l’utiliser comme argument diagnostique fort.","Alle bisherigen Befunde verwerfen.":"Écarter tous les résultats antérieurs.","Classifier immer ignorieren.":"Toujours ignorer le classificateur.","Erst eine fokale Bisulfit-PCR muss den Namen bestätigen.":"Une PCR bisulfite ciblée doit d’abord confirmer le nom.","Plausible hochkonfidente Klassifikation ist stark, aber integriert.":"Une classification plausible de haute confiance est forte, mais doit être intégrée.","Warum ist das begleitende Copy-number-Profil nützlich?":"Pourquoi le profil du nombre de copies associé est-il utile ?","Es kann die Klassenplausibilität stützen und zusätzliche diagnostische Muster liefern.":"Il peut soutenir la plausibilité de la classe et apporter des profils diagnostiques supplémentaires.","Es beweist Keimbahnveränderungen.":"Il prouve des altérations germinales.","Es ersetzt Histologie vollständig.":"Il remplace complètement l’histologie.","Es ist immer ein zugelassener Therapietest.":"C’est toujours un test thérapeutique approuvé.","Classifier und CN-Profil ergänzen die integrierte Diagnose.":"Le classificateur et le profil CN complètent le diagnostic intégré.","Entscheiden Sie, welcher Block analysiert und welches Classifier-Ergebnis reportet werden darf. Formulieren Sie die integrierte Diagnose mit klarer QC-Grenze.":"Décidez quel bloc doit être analysé et quel résultat du classificateur peut être rapporté. Formulez le diagnostic intégré avec une limite QC claire.","Morphologische Unsicherheit als legitime Classifier-Indikation erkennen.":"Reconnaître l’incertitude morphologique comme indication légitime du classificateur.","Tumorarmen Block als Risikomaterial identifizieren.":"Identifier le bloc pauvre en tumeur comme matériel à risque.","Low-confidence-Ausgabe nicht als definitive Diagnose reporten.":"Ne pas rapporter une sortie de faible confiance comme diagnostic définitif.","Tumorreichen Block analysieren.":"Analyser le bloc riche en tumeur.","Hochkonfidenten, plausiblen Classifier mit Morphologie/CN-Profil integrieren.":"Intégrer le résultat plausible de haute confiance du classificateur à la morphologie/au profil CN.","Bei fehlendem besserem Material eine rein deskriptive/NEC-artige Diagnose mit Limitation statt erzwungenem Classifier-Call.":"En l’absence de meilleur matériel, utiliser un diagnostic purement descriptif/de type NEC avec limitations plutôt que de forcer un appel de classe.","Referenzzentrum bei persistierender Diskordanz.":"Adresser à un centre de référence en cas de discordance persistante.","Highest score wins":"Le score le plus élevé gagne","Confidence, QC und Plausibilität werden ignoriert.":"Confiance, QC et plausibilité sont ignorés.","Classifier ersetzt Histologie":"Le classificateur remplace l’histologie","CNS-Diagnostik bleibt integriert.":"Le diagnostic du SNC reste intégré.","Fokale Methylierung statt Methylom":"Méthylation ciblée à la place du méthylome","Lokaler Marker beantwortet eine andere Frage.":"Un marqueur local répond à une autre question.","Der erste Classifier war technisch echt – diagnostisch trotzdem nicht gut genug":"Le premier classificateur était techniquement réel — mais diagnostiquement insuffisant","Aus dem tumorarmen Block entsteht ein Low-confidence-Match. Erst der gezielte Wechsel auf den tumorreichen Block erzeugt eine hochkonfidente, morphologisch passende Klassifikation. Das Problem war nicht 'KI vs. Mensch', sondern Präanalytik und Freigabekriterien.":"Le bloc pauvre en tumeur produit une correspondance de faible confiance. Ce n’est qu’après passage ciblé au bloc riche en tumeur qu’apparaît une classification de haute confiance, morphologiquement concordante. Le problème n’était pas « IA versus humain », mais la pré-analytique et les critères de validation.","Der Fall macht deutlich, dass auch moderne Klassifikatoren klassische Labor-QC brauchen.":"Le cas montre clairement que les classificateurs modernes nécessitent eux aussi un QC de laboratoire classique.","QC vor Klassenname":"QC avant le nom de classe","Low-confidence aus Block A verworfen; Block B liefert hochkonfidenten plausiblen Classifier-Match.":"Le résultat de faible confiance du bloc A est rejeté ; le bloc B fournit une correspondance plausible de haute confiance.","Classifier als Laborverfahren behandelt, nicht als Black Box.":"Le classificateur est traité comme une méthode de laboratoire, pas comme une boîte noire.","Richtige Klasse, falscher Weg":"Bonne classe, mauvais chemin","Klasse erkannt, aber der erste Low-score-Lauf wird nicht klar als nicht freigabefähig markiert.":"La classe est reconnue, mais le premier run à faible score n’est pas clairement signalé comme non validable.","QA-Lernziel verfehlt.":"L’objectif pédagogique de QA est manqué.","Low score reportet":"Faible score rapporté","Erster angezeigter Klassenname wird ungeprüft zur Diagnose.":"Le premier nom de classe affiché est retenu comme diagnostic sans vérification.","Kritischer Befundfreigabefehler.":"Erreur critique de validation du compte rendu.","Low-confidence / diskordant":"Faible confiance / discordant","Tumoranteil, DNA-QC, Referenzklasse und Materialauswahl prüfen.":"Vérifier fraction tumorale, QC de l’ADN, classe de référence et sélection du matériel.","Keine Scheinsicherheit.":"Pas de fausse certitude.","High-confidence + plausibel":"Haute confiance + plausible","In integrierte Diagnose übernehmen.":"Intégrer au diagnostic intégré.","Methylom liefert echten diagnostischen Mehrwert.":"Le méthylome apporte une réelle valeur diagnostique ajoutée.","Methylierungsclassifier sind besonders bei schwierigen ZNS-Tumoren leistungsfähig.":"Les classificateurs de méthylation sont particulièrement performants dans les tumeurs difficiles du SNC.","Tumoranteil und Probenqualität beeinflussen das Ergebnis.":"La fraction tumorale et la qualité de l’échantillon influencent le résultat.","Confidence/Score ist kein kosmetischer Parameter, sondern Teil der Befundfreigabe.":"La confiance/le score n’est pas cosmétique ; il fait partie de la validation du compte rendu.","Ein niedriger Score kann korrekt gerechnet und trotzdem diagnostisch nicht ausreichend sein.":"Un faible score peut être correctement calculé tout en restant diagnostiquement insuffisant.","Moderne Klassifikation funktioniert nur integriert mit Pathologie und Molekulargenetik.":"La classification moderne ne fonctionne qu’en intégration avec la pathologie et la génétique moléculaire.","Der erste Lauf aus tumorarmem Material ist trotz angezeigtem Klassennamen nicht freigabefähig. Nach Analyse des tumorreichen Blocks entsteht eine hochkonfidente, morphologisch und genomisch plausible Klassifikation. Diese wird als starker integrativer Diagnostikbaustein genutzt.":"Le premier run sur matériel pauvre en tumeur n’est pas validable malgré un nom de classe affiché. L’analyse du bloc riche en tumeur fournit ensuite une classification de haute confiance, morphologiquement et génomiquement plausible. Celle-ci est utilisée comme un puissant composant diagnostique intégratif.","QC/Confidence":"QC/Confiance","Materialauswahl":"Sélection du matériel","integrative Diagnose":"Diagnostic intégré","kein Black-box-Overcalling":"Pas de surinterprétation en boîte noire","Welche Mindest-QC braucht ein Classifier in Ihrem Labor?":"Quel QC minimal un classificateur nécessite-t-il dans votre laboratoire ?","Wie berichtet man Low-confidence-Ergebnisse?":"Comment rapporter les résultats de faible confiance ?","Wann ist 'kein Klassenruf' die bessere Diagnose?":"Quand « pas d’appel de classe » est-il la meilleure option diagnostique ?","Low-confidence aus falschem Block":"Faible confiance à partir du mauvais bloc","Classifier braucht Labor-QC wie jede andere Methode":"Un classificateur nécessite un QC de laboratoire comme toute autre méthode","Morphologische Unsicherheit → Materialwahl → Classifier-QC → integrierter Call":"Incertitude morphologique → sélection du matériel → QC du classificateur → appel intégré","DNMT3A/TET2/ASXL1 bei Zytopenie: CHIP, CCUS oder MDS?":"DNMT3A/TET2/ASXL1 avec cytopénie : CHIP, CCUS ou MDS ?","MDS/AML mit DNMT3A/TET2/ASXL1":"MDS/AML avec DNMT3A/TET2/ASXL1","Hämatologie / Molekulares Board":"Hématologie / Board moléculaire","74-jähriger Patient mit seit neun Monaten persistierender makrozytärer Anämie und milder Thrombozytopenie. Im peripheren Blut wurden DNMT3A- und TET2-Varianten gefunden.":"Homme de 74 ans avec anémie macrocytaire persistante et thrombopénie légère depuis neuf mois. Des variants DNMT3A et TET2 ont été détectés dans le sang périphérique.","Beweisen diese Mutationen bereits ein MDS – oder handelt es sich um CHIP?":"Ces mutations prouvent-elles déjà un MDS — ou s’agit-il d’un CHIP ?","Die Diagnose soll vor Einleitung einer krankheitsspezifischen Therapie geklärt werden.":"Le diagnostic doit être clarifié avant d’initier un traitement spécifique de la maladie.","Hb 9,8 g/dl, MCV erhöht, Thrombozyten 115/nl; Leukozyten normal.":"Hb 9,8 g/dl, VGM augmenté, plaquettes 115/nl ; leucocytes normaux.","Sekundäre Ursachen":"Causes secondaires","Vitaminmangel, relevante Blutung, Niereninsuffizienz und Medikamente als Hauptursache weitgehend ausgeschlossen.":"Carence vitaminique, saignement significatif, insuffisance rénale et médicaments ont été largement exclus comme cause principale.","Blut-NGS: DNMT3A p.R882H VAF 12 %, TET2 Frameshift VAF 8 %.":"NGS sanguin : DNMT3A p.R882H VAF 12 %, TET2 frameshift VAF 8 %.","Mutationen typischer CH-Gene werden mit einer definierten myeloischen Neoplasie gleichgesetzt.":"Les mutations de gènes typiques de CH sont assimilées à une néoplasie myéloïde définie.","Knochenmark + Vorinformation":"Moelle osseuse + informations antérieures","Normo- bis leicht hyperzellulär; Dysplasie unterhalb diagnostischer Schwelle, Blasten 2 %.":"Normocellulaire à légèrement hypercellulaire ; dysplasie sous le seuil diagnostique, blastes 2 %.","Kein MDS-definierender Befund.":"Aucun résultat définissant un MDS.","Flow":"Cytométrie en flux","Kein eindeutiger aberranter Blastenphänotyp.":"Aucun phénotype aberrant de blastes sans ambiguïté.","Wie werden persistierende Zytopenie und klonale Mutationen zusammengeführt?":"Comment intégrer la cytopénie persistante et les mutations clonales ?","Knochenmarkaspirat + Stanze sowie EDTA-Blut.":"Aspirat médullaire + biopsie et sang EDTA.","ausreichende Tiefe zur VAF-Beurteilung.":"Profondeur suffisante pour évaluer la VAF.","CHIP setzt definitionsgemäß das Fehlen einer anderweitig ungeklärten Zytopenie voraus.":"Par définition, CHIP exige l’absence de cytopénie autrement inexpliquée.","Ein breites Pan-Cancer-Panel schafft nicht automatisch mehr diagnostische Sicherheit als eine integrierte hämatologische Bewertung.":"Un panel pan-cancer large ne crée pas automatiquement plus de certitude diagnostique qu’une évaluation hématologique intégrée.","Knochenmark-/Morphologiekontext":"Contexte moelle osseuse/morphologie","Klonale Hämatopoese / Myeloid-Panel":"Hématopoïèse clonale / panel myéloïde","Persistierende Zytopenie, aber keine ausreichende Dysplasie, keine erhöhte Blastenzahl und kein morphologisch definierendes MDS-Kriterium.":"Cytopénie persistante, mais dysplasie insuffisante, pas d’augmentation des blastes et aucun critère morphologique définissant un MDS.","Myeloid-Panel":"Panel myéloïde","DNMT3A p.R882H (VAF 12 %) und TET2 Frameshift (VAF 8 %); keine TP53-Alteration im untersuchten Panel. Klonalität ist belegt, eine MDS-Diagnose dadurch allein jedoch nicht.":"DNMT3A p.R882H (VAF 12 %) et TET2 frameshift (VAF 8 %) ; aucune altération TP53 dans le panel étudié. La clonalité est démontrée, mais cela ne suffit pas à établir un MDS.","Zusätzliche unspezifische Varianten erhöhen die Informationsmenge, lösen aber die diagnostische Abgrenzung nicht ohne Blutbild, Morphologie und definierende Kriterien.":"Des variants supplémentaires non spécifiques augmentent la quantité d’informations, mais ne résolvent pas la distinction diagnostique sans numération sanguine, morphologie et critères définissant l’entité.","Persistierende, anderweitig nicht erklärte Anämie und Thrombozytopenie.":"Anémie et thrombopénie persistantes, autrement inexpliquées.","Keine ausreichenden morphologischen oder genetischen Kriterien für eine manifeste myeloische Neoplasie.":"Pas de critères morphologiques ou génétiques suffisants pour une néoplasie myéloïde manifeste.","Die DNMT3A- und TET2-Mutationen belegen klonale Hämatopoese, definieren aber allein kein MDS. Weil gleichzeitig persistierende ungeklärte Zytopenien bestehen, ist 'CHIP' nicht die passende Kategorie; bei fehlenden diagnostischen MDS-Kriterien passt die Konstellation zu einer klonalen Zytopenie unklarer Signifikanz (CCUS). Verlauf und erneute Abklärung bei Progression sind wichtiger als ein vorschnelles Neoplasie-Label.":"Les mutations DNMT3A et TET2 démontrent une hématopoïèse clonale, mais ne définissent pas à elles seules un MDS. Comme des cytopénies persistantes inexpliquées sont également présentes, « CHIP » n’est pas la catégorie appropriée ; en l’absence de critères diagnostiques de MDS, la constellation correspond à une cytopénie clonale de signification indéterminée (CCUS). Le suivi et une réévaluation en cas d’évolution sont plus importants qu’une étiquette prématurée de néoplasie.","Teilbefund: Mutationen in DNMT3A/TET2/ASXL1 können bei CHIP, CCUS und myeloischen Neoplasien vorkommen; die Diagnose entsteht erst aus Klinik, Blutbild, Morphologie und Genetik zusammen.":"Résultat partiel : les mutations DNMT3A/TET2/ASXL1 peuvent être présentes dans CHIP, CCUS et les néoplasies myéloïdes ; le diagnostic n’émerge qu’en intégrant contexte clinique, numération sanguine, morphologie et génétique.","Klonale Mutation nicht mit MDS gleichsetzen":"Ne pas assimiler une mutation clonale à un MDS","CHIP nur ohne ungeklärte Zytopenie verwenden":"Utiliser CHIP uniquement en l’absence de cytopénie inexpliquée","CCUS als passende Zwischenkategorie bei Zytopenie + Klon ohne MDS-Kriterien erkennen":"Reconnaître CCUS comme catégorie intermédiaire appropriée en cas de cytopénie + clone sans critères de MDS","Verlaufskontrolle und erneute KM-Diagnostik bei Dynamik einplanen":"Planifier le suivi et une nouvelle évaluation médullaire si la situation évolue","Falschaussage: DNMT3A/TET2 beweisen eine hämatologische Neoplasie":"Affirmation fausse : DNMT3A/TET2 prouvent une néoplasie hématologique","Optimale Lösung: DNMT3A/TET2 zeigen einen Klon; Zytopenie verhindert die CHIP-Bezeichnung, fehlende MDS-definierende Kriterien verhindern die MDS-Diagnose – damit ist CCUS die saubere integrierte Einordnung.":"Solution optimale : DNMT3A/TET2 démontrent un clone ; la cytopénie empêche l’étiquette CHIP, tandis que l’absence de critères définissant un MDS empêche le diagnostic de MDS — CCUS est donc la classification intégrée la plus juste.","Hämatologie":"Hématologie","DNMT3A":"DNMT3A","TET2":"TET2","CHIP":"CHIP","CCUS":"CCUS","MDS":"MDS","Clonal hematopoiesis":"Hématopoïèse clonale","Der Klon ist echt – die Neoplasie noch nicht":"Le clone est réel — la néoplasie pas encore","Hämatopathologie / Hämatologie / MTB":"Hématopathologie / Hématologie / MTB","DNMT3A/TET2/ASXL1-Mutationen als häufige Klone und nicht als automatische MDS-Diagnose erkennen.":"Reconnaître les mutations DNMT3A/TET2/ASXL1 comme des clones fréquents et non comme un diagnostic automatique de MDS.","CHIP, CCUS und MDS anhand von Zytopenie und diagnostischen Kriterien trennen.":"Distinguer CHIP, CCUS et MDS à partir de la cytopénie et des critères diagnostiques.","VAF/Klonalität als Kontext, nicht als alleinige Entitätsdefinition verwenden.":"Utiliser VAF/clonalité comme contexte, non comme seule définition d’une entité.","Morphologie und Blutbild gegenüber 'Genetik allein' priorisieren.":"Prioriser morphologie et numération sanguine par rapport à la « génétique seule ».","Verlaufskontrolle als Teil einer ehrlichen diagnostischen Strategie verstehen.":"Comprendre le suivi comme faisant partie d’une stratégie diagnostique honnête.","Zwei pathogene Mutationen stehen schwarz auf weiß im NGS-Bericht. Der Reflex lautet: 'Dann hat er MDS.' Das Knochenmark liefert aber keine ausreichenden Kriterien – und die persistierende Zytopenie macht gleichzeitig 'CHIP' falsch.":"Deux mutations pathogènes figurent clairement dans le compte rendu NGS. Le réflexe est : « Donc il a un MDS. » Mais la moelle osseuse ne remplit pas de critères suffisants — et la cytopénie persistante rend en même temps l’étiquette « CHIP » incorrecte.","74-jähriger Patient mit ungeklärter makrozytärer Anämie und Thrombozytopenie. DNMT3A und TET2 sind mutiert, das Knochenmark bleibt jedoch unterhalb diagnostischer MDS-Schwellen. Gesucht ist die richtige Kategorie zwischen benignem Zufallsbefund und manifester Neoplasie.":"Homme de 74 ans avec anémie macrocytaire et thrombopénie inexpliquées. DNMT3A et TET2 sont mutés, mais la moelle reste sous les seuils diagnostiques du MDS. Il faut identifier la bonne catégorie entre découverte fortuite bénigne et néoplasie manifeste.","Klonalität ist bewiesen":"La clonalité est démontrée","DNMT3A 12 %, TET2 8 % VAF.":"DNMT3A 12 %, TET2 8 % VAF.","Ein Klon ist nicht automatisch eine Neoplasie.":"Un clone n’est pas automatiquement une néoplasie.","Zytopenie ist real":"La cytopénie est réelle","Persistierende Anämie + Thrombozytopenie ohne klare Sekundärursache.":"Anémie persistante + thrombopénie sans cause secondaire claire.","Damit passt die Definition von CHIP gerade nicht.":"La définition de CHIP ne convient donc pas.","MDS-Kriterien fehlen":"Les critères de MDS sont absents","Blasten 2 %, Dysplasie unter Schwelle, keine definierende Genetik.":"Blastes 2 %, dysplasie sous le seuil, pas de génétique définissant l’entité.","CCUS ist eine sinnvolle Zwischenkategorie.":"CCUS est une catégorie intermédiaire pertinente.","Hb 9,8 g/dl; Thrombozyten 115/nl":"Hb 9,8 g/dl ; plaquettes 115/nl","DNMT3A p.R882H 12 %, TET2 Frameshift 8 %":"DNMT3A p.R882H 12 %, TET2 frameshift 8 %","keine ausreichende Dysplasie, Blasten 2 %":"Dysplasie insuffisante, blastes 2 %","Knochenmarkmorphologie ist unverzichtbar.":"La morphologie médullaire est indispensable.","Breites Pan-Cancer-NGS kann die Kategorie nicht ohne klinisch-hämatologischen Kontext definieren.":"Un NGS pan-cancer large ne peut pas définir la catégorie sans contexte clinico-hématologique.","Verlauf ist diagnostisch relevant, wenn Kriterien heute noch nicht erfüllt sind.":"Le suivi est diagnostiquement pertinent lorsque les critères ne sont pas encore remplis aujourd’hui.","Was beweisen DNMT3A/TET2 hier?":"Que prouvent DNMT3A/TET2 ici ?","Klonale Hämatopoese.":"Hématopoïèse clonale.","Sicher ein MDS.":"MDS certain.","Sicher AML.":"AML certaine.","Eine Keimbahnerkrankung.":"Une affection germinale.","Diese Gene überlappen stark zwischen CH, CCUS und myeloischen Neoplasien.":"Ces gènes se chevauchent largement entre CH, CCUS et les néoplasies myéloïdes.","Warum ist 'CHIP' hier unpassend?":"Pourquoi « CHIP » est-il inapproprié ici ?","Weil persistierende anderweitig ungeklärte Zytopenien bestehen.":"Parce qu’il existe des cytopénies persistantes autrement inexpliquées.","Weil der Patient älter als 70 ist.":"Parce que le patient a plus de 70 ans.","Weil zwei Mutationen vorliegen.":"Parce que deux mutations sont présentes.","Weil VAF über 5 % liegt.":"Parce que la VAF est supérieure à 5 %.","CHIP setzt gerade das Fehlen entsprechender ungeklärter Zytopenien voraus.":"CHIP exige précisément l’absence de cytopénies correspondantes inexpliquées.","Welche Kategorie passt bei Zytopenie + Klon ohne MDS-definierende Kriterien am besten?":"Quelle catégorie correspond le mieux à cytopénie + clone sans critères définissant un MDS ?","CCUS.":"CCUS.","CHIP.":"CHIP.","AML.":"AML.","Normalbefund.":"Résultat normal.","CCUS beschreibt genau diese Zwischenkonstellation.":"CCUS décrit exactement cette constellation intermédiaire.","Was ist die sinnvollste nächste Strategie?":"Quelle est la stratégie la plus appropriée ensuite ?","Klinisch/hämatologisch monitoren und bei Dynamik erneut Knochenmark/Molekulargenetik bewerten.":"Surveiller cliniquement/hématologiquement et réévaluer moelle osseuse/génétique moléculaire en cas d’évolution.","Sofort MDS-Therapie allein wegen DNMT3A/TET2.":"Commencer immédiatement un traitement de MDS sur la seule base de DNMT3A/TET2.","Keine weitere Kontrolle.":"Aucun suivi supplémentaire.","Automatisch Keimbahntest für DNMT3A/TET2.":"Réaliser automatiquement une analyse germinale de DNMT3A/TET2.","Diagnostische Ehrlichkeit plus Verlauf ist hier angemessen.":"L’honnêteté diagnostique associée au suivi est appropriée ici.","Ordnen Sie den Fall zwischen CHIP, CCUS und MDS ein und formulieren Sie, welche Information die Mutationen liefern – und welche nicht.":"Classez le cas entre CHIP, CCUS et MDS et précisez quelles informations les mutations apportent — et lesquelles elles n’apportent pas.","Klonalität anerkennen.":"Reconnaître la clonalité.","Persistierende ungeklärte Zytopenie berücksichtigen.":"Tenir compte de la cytopénie persistante inexpliquée.","Fehlende MDS-definierende Morphologie/Genetik benennen.":"Mentionner l’absence de morphologie/génétique définissant un MDS.","CHIP ausschließen, weil Zytopenie vorhanden.":"Écarter CHIP parce qu’une cytopénie est présente.","CCUS als passendste aktuelle Kategorie formulieren.":"Formuler CCUS comme la catégorie actuelle la plus appropriée.","Verlaufskontrolle/erneute Diagnostik bei Progression empfehlen.":"Recommander suivi/réévaluation en cas d’évolution.","Bei später neu auftretenden definierenden Kriterien Re-Klassifikation zur myeloischen Neoplasie.":"Si des critères définissant l’entité apparaissent ultérieurement, reclasser en néoplasie myéloïde.","Bei identifizierter sekundärer Zytopenieursache Neubewertung der CCUS-Einordnung.":"Si une cause secondaire de cytopénie est identifiée, réévaluer la classification CCUS.","Mutation = MDS":"Mutation = MDS","CH-Gene sind nicht krankheitsspezifisch.":"Les gènes CH ne sont pas spécifiques d’une maladie.","Alles CHIP":"Tout est CHIP","Persistierende ungeklärte Zytopenie widerspricht CHIP.":"Une cytopénie persistante inexpliquée est incompatible avec CHIP.","Mehr Panel = mehr Diagnose":"Plus de panel = plus de diagnostic","Diagnosekriterien bleiben klinisch-morphologisch integriert.":"Les critères diagnostiques restent intégrés cliniquement et morphologiquement.","Der richtige Befund ist die Zwischenkategorie":"Le bon résultat est la catégorie intermédiaire","Die Mutationen sind echt und klinisch relevant, aber weder 'Zufalls-CHIP' noch bereits diagnostisches MDS. Die Zytopenie verschiebt den Fall in CCUS – ein Ergebnis, das weniger endgültig klingt, aber fachlich präziser ist.":"Les mutations sont réelles et cliniquement pertinentes, mais ne correspondent ni à un « CHIP fortuit » ni encore à un MDS diagnostique. La cytopénie fait basculer le cas vers CCUS — un résultat moins définitif en apparence, mais plus précis.","Er trainiert, diagnostische Unsicherheit korrekt zu benennen statt molekulare Befunde zu overcallen.":"Il entraîne à nommer correctement l’incertitude diagnostique plutôt qu’à surinterpréter les résultats moléculaires.","CCUS sauber erkannt":"CCUS correctement reconnu","Zytopenie + DNMT3A/TET2-Klon, aber keine MDS-definierenden Kriterien → CCUS.":"Cytopénie + clone DNMT3A/TET2, mais sans critères définissant un MDS → CCUS.","Klon, Klinik und Morphologie korrekt integriert.":"Clone, contexte clinique et morphologie correctement intégrés.","CH erkannt, Kategorie unscharf":"CH reconnue, catégorie imprécise","MDS wird vermieden, aber trotz Zytopenie 'CHIP' berichtet.":"Le MDS est évité, mais malgré la cytopénie le cas est rapporté comme 'CHIP'.","Definition nicht sauber angewendet.":"La définition n'est pas correctement appliquée.","NGS diagnostiziert MDS":"Le NGS diagnostique un MDS","DNMT3A/TET2 werden allein als MDS-Beweis verwendet.":"DNMT3A/TET2 sont utilisés seuls comme preuve de MDS.","Molekulares Overcalling.":"Surinterprétation moléculaire.","Zytopenien verschlechtern sich":"Les cytopénies s'aggravent","Erneute Knochenmarkdiagnostik inklusive Morphologie/Genetik.":"Répéter le bilan médullaire, y compris morphologie/génétique.","Progression kann neue definierende Kriterien sichtbar machen.":"La progression peut faire apparaître de nouveaux critères définitoires.","Stabiler Verlauf":"Évolution stable","Strukturiertes Monitoring.":"Surveillance structurée.","Keine unnötige Neoplasietherapie.":"Pas de traitement néoplasique inutile.","DNMT3A/TET2/ASXL1 sind häufige Gene klonaler Hämatopoese.":"DNMT3A/TET2/ASXL1 sont des gènes fréquents dans l'hématopoïèse clonale.","CHIP, CCUS und MDS teilen molekulare Befunde; Kontext trennt die Kategorien.":"CHIP, CCUS et MDS partagent des anomalies moléculaires ; le contexte distingue les catégories.","CHIP ohne ungeklärte Zytopenie, CCUS mit Zytopenie aber ohne definierende Neoplasiekriterien.":"CHIP sans cytopénie inexpliquée ; CCUS avec cytopénie mais sans critères définissant une néoplasie.","NGS erhöht Sensitivität für Klonalität, nicht automatisch Spezifität für MDS.":"Le NGS augmente la sensibilité pour la clonalité, pas automatiquement la spécificité pour le MDS.","Verlauf kann Teil der Diagnostik sein.":"L'évolution dans le temps peut faire partie de la démarche diagnostique.","Die Mutationen belegen einen myeloischen Klon. Wegen persistierender ungeklärter Zytopenien ist CHIP unpassend; wegen fehlender MDS-definierender Morphologie/Genetik ist ein MDS derzeit nicht gesichert. Die präziseste Einordnung ist CCUS mit strukturierter Verlaufskontrolle.":"Les mutations démontrent un clone myéloïde. En raison de cytopénies persistantes inexpliquées, CHIP n'est pas approprié ; en l'absence de morphologie/génétique définissant un MDS, un MDS n'est actuellement pas établi. La classification la plus précise est CCUS avec suivi structuré.","Mutation ≠ Neoplasie":"Mutation ≠ néoplasie","CHIP vs CCUS":"CHIP vs CCUS","Morphologie integriert":"Morphologie intégrée","Monitoring":"Surveillance","Welche Mutationen erhöhen die Progressionswahrscheinlichkeit stärker?":"Quelles mutations augmentent davantage la probabilité de progression ?","Wie verändert VAF die Risikoeinschätzung, ohne die Diagnose allein zu definieren?":"Comment la VAF modifie-t-elle l'évaluation du risque sans définir à elle seule le diagnostic ?","Wann wiederholt man das Knochenmark?":"Quand faut-il répéter l'évaluation médullaire ?","CCUS statt binärer CHIP/MDS-Antwort":"CCUS plutôt qu'une réponse binaire CHIP/MDS","Klonalität und Neoplasie sind nicht dasselbe":"Clonalité et néoplasie ne sont pas synonymes","Zytopenie → Klon → Morphologie → CCUS/MDS-Entscheidung":"Cytopénie → clone → morphologie → décision CCUS/MDS","MSI-H-CRC mit MLH1/PMS2-Verlust: BRAF-Wildtyp ist noch kein Lynch-Syndrom":"CRC MSI-H avec perte de MLH1/PMS2 : BRAF wild type ne signifie pas encore syndrome de Lynch","MLH1-Promotor-Methylierung bei MSI…":"Méthylation du promoteur de MLH1 dans MSI…","Viszeralonkologie / Humangenetik-Screening":"Oncologie viscérale / dépistage génétique","71-jährige Patientin mit rechtsseitigem Kolonkarzinom. Universal-Screening zeigt Verlust von MLH1/PMS2 und MSI-H.":"Patiente de 71 ans atteinte d'un cancer du côlon droit. Le dépistage universel montre une perte de MLH1/PMS2 et un statut MSI-H.","Ist bei BRAF-Wildtyp nun automatisch von Lynch-Syndrom auszugehen – oder fehlt noch der entscheidende epigenetische Reflex?":"BRAF wild type implique-t-il désormais automatiquement un syndrome de Lynch, ou manque-t-il encore le test réflexe épigénétique décisif ?","Der Tumorbefund soll therapeutisch und hereditär korrekt eingeordnet werden.":"Le résultat tumoral doit être correctement interprété sur les plans thérapeutique et héréditaire.","Rechtsseitiges, lymphozytenreiches Adenokarzinom.":"Adénocarcinome droit riche en lymphocytes.","Familie":"Antécédents familiaux","Keine auffällige Häufung Lynch-assoziierter Tumoren dokumentiert.":"Aucune agrégation notable de tumeurs associées à Lynch n'est documentée.","MLH1/PMS2-Verlust, MSI-H; BRAF V600E nicht nachweisbar.":"Perte de MLH1/PMS2, MSI-H ; BRAF V600E non détecté.","BRAF-Wildtyp wird fälschlich als positiver Lynch-Nachweis interpretiert.":"BRAF wild type est interprété à tort comme une preuve positive de syndrome de Lynch.","Mäßig differenziertes Adenokarzinom mit medullär/lymphozytenreichen Anteilen.":"Adénocarcinome modérément différencié avec des zones médullaires/riches en lymphocytes.","MLH1 und PMS2 verloren; MSH2/MSH6 erhalten.":"MLH1 et PMS2 perdus ; MSH2/MSH6 conservés.","MSI-high bestätigt.":"MSI-high confirmé.","Somatische MLH1-Promotor-Methylierung als Ursache der MLH1-Inaktivierung.":"Méthylation somatique du promoteur de MLH1 comme cause de l'inactivation de MLH1.","FFPE-Resektat mit hohem Tumoranteil.":"Pièce de résection FFPE à forte teneur tumorale.","Methylierung":"Méthylation","gezielter validierter MLH1-Promotor-Assay möglich.":"Un test ciblé et validé du promoteur de MLH1 est réalisable.","Wildtyp – informativ, aber nicht beweisend für Lynch.":"Wild type — informatif, mais ne prouve pas un syndrome de Lynch.","Ein negatives Ausschlussmerkmal darf nicht in einen positiven hereditären Nachweis umgedeutet werden.":"Un marqueur d'exclusion négatif ne doit pas être transformé en preuve héréditaire positive.","MLH1-Promotor-Methylierung":"Méthylation du promoteur de MLH1","Verlust von MLH1/PMS2 bei erhaltener MSH2/MSH6-Expression.":"Perte de MLH1/PMS2 avec expression conservée de MSH2/MSH6.","MSI-high bestätigt; damit besteht ein therapeutisch relevanter dMMR/MSI-H-Kontext.":"MSI-high confirmé ; il existe donc un contexte dMMR/MSI-H pertinent sur le plan thérapeutique.","BRAF V600E nicht nachweisbar. Das entfernt ein starkes Indiz für sporadische MLH1-Inaktivierung, beweist Lynch aber nicht.":"BRAF V600E non détecté. Cela retire un indice fort en faveur d'une inactivation sporadique de MLH1, mais ne prouve pas un syndrome de Lynch.","Deutliche MLH1-Promotor-Hypermethylierung. Die Konstellation spricht bei dieser 71-jährigen Patientin stark für eine sporadische epigenetische MLH1-Silenzierung; klinische/familiäre Auffälligkeiten bleiben dennoch zu berücksichtigen.":"Hyperméthylation marquée du promoteur de MLH1. Chez cette patiente de 71 ans, la constellation est fortement en faveur d'un silençage épigénétique sporadique de MLH1 ; les particularités cliniques et familiales doivent néanmoins rester prises en compte.","Kernbefund":"Résultat clé","dMMR/MSI-H durch MLH1/PMS2-Verlust.":"dMMR/MSI-H par perte de MLH1/PMS2.","Wildtyp – kein Lynch-Beweis.":"Wild type — ne prouve pas un syndrome de Lynch.","Der dMMR/MSI-H-Status ist therapeutisch relevant. Für die hereditäre Einordnung zeigt der MLH1/PMS2-Verlust zunächst nur die Richtung der Reflexdiagnostik. BRAF-Wildtyp beweist kein Lynch-Syndrom. Die nachgewiesene MLH1-Promotor-Hypermethylierung spricht stark für eine sporadische epigenetische MLH1-Inaktivierung; Alter, Familienanamnese und besondere klinische Konstellationen können dennoch eine weitergehende humangenetische Beurteilung rechtfertigen.":"Le statut dMMR/MSI-H est pertinent sur le plan thérapeutique. Pour l'interprétation héréditaire, la perte de MLH1/PMS2 indique d'abord seulement l'orientation des tests réflexes. BRAF wild type ne prouve pas un syndrome de Lynch. L'hyperméthylation détectée du promoteur de MLH1 est fortement en faveur d'une inactivation épigénétique sporadique de MLH1 ; l'âge, les antécédents familiaux et certaines situations cliniques peuvent néanmoins justifier une évaluation génétique complémentaire.","Teilbefund: MLH1/PMS2-Verlust + MSI-H ist nicht synonym mit Lynch; die Ursache der MLH1-Inaktivierung muss reflexdiagnostisch geklärt werden.":"Résultat partiel : perte de MLH1/PMS2 + MSI-H n'est pas synonyme de syndrome de Lynch ; la cause de l'inactivation de MLH1 doit être clarifiée par des tests réflexes.","dMMR/MSI-H therapeutisch korrekt einordnen":"Interpréter correctement dMMR/MSI-H sur le plan thérapeutique","BRAF-Wildtyp nicht als Lynch-Beweis interpretieren":"Ne pas interpréter BRAF wild type comme une preuve de syndrome de Lynch","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex priorisieren":"Prioriser la méthylation du promoteur de MLH1 comme test réflexe épigénétique direct","Alter/Familie/klinischen Kontext trotz Methylierung berücksichtigen":"Tenir compte de l'âge/des antécédents familiaux/du contexte clinique malgré la méthylation","Falschaussage: BRAF-Wildtyp + MLH1/PMS2-Verlust = Lynch gesichert":"Affirmation erronée : BRAF wild type + perte de MLH1/PMS2 = syndrome de Lynch confirmé","Optimale Lösung: MSI-H/dMMR therapeutisch nutzen, MLH1/PMS2-Verlust hereditär reflexdiagnostisch abarbeiten und BRAF-Wildtyp nicht überinterpretieren; positive MLH1-Methylierung spricht stark für sporadische Silenzierung.":"Solution optimale : exploiter MSI-H/dMMR sur le plan thérapeutique, explorer la perte de MLH1/PMS2 par le bilan réflexe héréditaire approprié et ne pas surinterpréter BRAF wild type ; une méthylation positive de MLH1 est fortement en faveur d'un silençage sporadique.","MLH1 methylation":"Méthylation de MLH1","BRAF wild type":"BRAF wild type","BRAF-Wildtyp ist kein positiver Lynch-Test":"BRAF wild type n'est pas un test positif de Lynch","Gastrointestinale Molekularpathologie / MTB / Humangenetik":"Pathologie moléculaire gastro-intestinale / MTB / génétique clinique","MLH1/PMS2-Verlust als Trigger einer spezifischen Reflexdiagnostik verstehen.":"Comprendre la perte de MLH1/PMS2 comme le déclencheur d'un bilan réflexe spécifique.","MSI-H/dMMR therapeutische und hereditäre Ebenen trennen.":"Séparer les dimensions thérapeutique et héréditaire de MSI-H/dMMR.","BRAF V600E positiv als starkes sporadisches Indiz, BRAF-Wildtyp aber nicht als Lynch-Beweis verstehen.":"Comprendre BRAF V600E positif comme un indice fort de caractère sporadique, mais BRAF wild type non comme une preuve de Lynch.","MLH1-Promotor-Methylierung als direkten epigenetischen Reflex einordnen.":"Considérer la méthylation du promoteur de MLH1 comme le test réflexe épigénétique direct.","Alter und Familienanamnese trotz scheinbar sporadischem Muster berücksichtigen.":"Tenir compte de l'âge et des antécédents familiaux malgré un profil apparemment sporadique.","MLH1 und PMS2 fehlen, der Tumor ist MSI-H – und BRAF ist Wildtyp. Im Board fällt sofort der Satz: 'Dann ist es Lynch.' Genau an dieser Stelle setzt der Fall an.":"MLH1 et PMS2 sont absents, la tumeur est MSI-H — et BRAF est wild type. En réunion, quelqu'un dit immédiatement : « Alors c'est Lynch. » C'est précisément là que commence le cas.","71-jährige Patientin mit rechtsseitigem MSI-H-CRC und MLH1/PMS2-Verlust. BRAF V600E ist nicht nachweisbar. Die zentrale Frage ist, ob das bereits Lynch beweist oder ob die epigenetische Ursache der MLH1-Silenzierung noch direkt geprüft werden muss.":"Patiente de 71 ans avec CRC droit MSI-H et perte de MLH1/PMS2. BRAF V600E n'est pas détecté. La question centrale est de savoir si cela prouve déjà un syndrome de Lynch ou si la cause épigénétique du silençage de MLH1 doit encore être testée directement.","Therapieebene":"Dimension thérapeutique","MSI-H/dMMR ist bereits ein wichtiger prädiktiver Tumorbefund.":"MSI-H/dMMR constitue déjà un résultat tumoral prédictif important.","Die Therapieaussage braucht nicht erst eine Lynch-Diagnose.":"La conclusion thérapeutique ne nécessite pas au préalable un diagnostic de Lynch.","MLH1/PMS2-Verlust kann sporadisch oder hereditär entstehen.":"La perte de MLH1/PMS2 peut être sporadique ou héréditaire.","Reflexdiagnostik klärt die Ursache.":"Le bilan réflexe clarifie la cause.","Negativ ist nicht positiv":"Négatif ne signifie pas positif","BRAF-Wildtyp entfernt ein sporadisches Indiz, beweist aber Lynch nicht.":"BRAF wild type retire un indice de caractère sporadique, mais ne prouve pas un syndrome de Lynch.","Ausschlussmarker nicht in Bestätigungsmarker verwandeln.":"Ne pas transformer un marqueur d'exclusion en marqueur de confirmation.","MLH1/PMS2 verloren":"MLH1/PMS2 perdus","MSI-high":"MSI-high","V600E nicht nachweisbar":"V600E non détecté","Ausreichendes Resektat für gezielte MLH1-Methylierungsanalyse.":"Pièce de résection adéquate pour une analyse ciblée de la méthylation de MLH1.","Kein Grund für ein breites Panel, wenn die Reflexfrage fokussiert beantwortet werden kann.":"Pas besoin d'un large panel si la question réflexe ciblée peut recevoir une réponse directe.","Klinischer Kontext bleibt Teil der Lynch-Risikobewertung.":"Le contexte clinique reste un élément de l'évaluation du risque de Lynch.","Was bedeutet BRAF-Wildtyp bei MLH1/PMS2-Verlust?":"Que signifie BRAF wild type en présence d'une perte de MLH1/PMS2 ?","Lynch bleibt möglich, ist aber nicht bewiesen; MLH1-Promotor-Methylierung sollte direkt geprüft werden.":"Un syndrome de Lynch reste possible mais n'est pas prouvé ; la méthylation du promoteur de MLH1 doit être testée directement.","Lynch ist damit gesichert.":"Le syndrome de Lynch est ainsi confirmé.","Sporadisch ist damit gesichert.":"Le caractère sporadique est ainsi confirmé.","BRAF hat nie Bedeutung im CRC-Lynch-Screening.":"BRAF n'a jamais d'intérêt dans le dépistage du syndrome de Lynch dans le CRC.","Negatives BRAF-Ergebnis ist kein positiver Lynch-Nachweis.":"Un résultat BRAF négatif n'est pas une preuve positive de syndrome de Lynch.","MLH1-Promotor-Methylierung ist deutlich positiv. Was ist die beste Interpretation?":"La méthylation du promoteur de MLH1 est nettement positive. Quelle est la meilleure interprétation ?","Starkes Indiz für sporadische epigenetische MLH1-Silenzierung; klinische Sonderkonstellationen trotzdem beachten.":"Argument fort en faveur d'un silençage épigénétique sporadique de MLH1 ; certaines situations cliniques particulières doivent néanmoins être prises en compte.","Beweist Lynch.":"Prouve un syndrome de Lynch.","Macht MSI-H therapeutisch irrelevant.":"Rend MSI-H sans pertinence thérapeutique.","Ist bei CRC bedeutungslos.":"N'a pas d'intérêt dans le CRC.","Tumorale MLH1-Hypermethylierung erklärt häufig sporadischen MLH1/PMS2-Verlust.":"L'hyperméthylation tumorale de MLH1 explique fréquemment une perte sporadique de MLH1/PMS2.","Welche Aussage trennt die Ebenen korrekt?":"Quelle proposition sépare correctement les deux dimensions ?","MSI-H/dMMR ist therapeutisch relevant; Lynch-Abklärung ist eine zusätzliche hereditäre Frage.":"MSI-H/dMMR est pertinent sur le plan thérapeutique ; l'évaluation de Lynch constitue une question héréditaire supplémentaire.","Immuntherapie darf erst nach Keimbahnbefund diskutiert werden.":"L'immunothérapie ne peut être discutée qu'après un résultat germinal.","dMMR und Lynch sind Synonyme.":"dMMR et syndrome de Lynch sont synonymes.","Nur BRAF entscheidet beide Ebenen.":"Seul BRAF détermine les deux dimensions.","Tumorbiomarker und hereditäre Diagnose sind verwandt, aber nicht identisch.":"Le biomarqueur tumoral et le diagnostic héréditaire sont liés, mais ne sont pas identiques.","Wann sollte trotz MLH1-Methylierung genauer hingesehen werden?":"Quand faut-il approfondir malgré une méthylation de MLH1 ?","Bei ungewöhnlich jungem Alter, auffälliger Familien-/Eigenanamnese oder anderer klinischer Diskordanz.":"En cas d'âge inhabituellement jeune, d'antécédents personnels/familiaux évocateurs ou d'une autre discordance clinique.","Nie.":"Jamais.","Immer vollständige Keimbahndiagnostik unabhängig vom Kontext.":"Toujours réaliser un bilan germinal complet indépendamment du contexte.","Nur bei PD-L1-Positivität.":"Uniquement en cas de positivité PD-L1.","Seltene konstitutionelle Epimutationen und klinische Sonderkonstellationen verhindern absolute Aussagen.":"De rares épimutations constitutionnelles et certaines situations cliniques particulières empêchent les affirmations absolues.","Formulieren Sie eine zweigeteilte MTB-Aussage: therapeutische Bedeutung von MSI-H/dMMR und hereditäre Einordnung des MLH1/PMS2-Verlusts nach BRAF- und MLH1-Methylierungsbefund.":"Formulez une conclusion MTB en deux volets : signification thérapeutique de MSI-H/dMMR et interprétation héréditaire de la perte de MLH1/PMS2 après les résultats BRAF et de méthylation de MLH1.","dMMR/MSI-H therapeutisch einordnen.":"Interpréter dMMR/MSI-H sur le plan thérapeutique.","MLH1/PMS2-Verlust als Reflextrigger verstehen.":"Comprendre la perte de MLH1/PMS2 comme déclencheur du bilan réflexe.","BRAF-Wildtyp nicht als Lynch-Beweis formulieren.":"Ne pas rapporter BRAF wild type comme preuve de syndrome de Lynch.","MLH1-Promotor-Methylierung direkt testen.":"Tester directement la méthylation du promoteur de MLH1.","Positive Methylierung als starkes sporadisches Indiz berichten.":"Rapporter une méthylation positive comme un argument fort en faveur d'un silençage sporadique.","Klinische Sonderkonstellationen offenhalten.":"Garder ouvertes les situations cliniques particulières.","In Laborpfaden, die BRAF und Methylierung anders sequenzieren, ist die Kernaussage identisch: BRAF-WT allein reicht nicht für Lynch-Diagnose.":"Dans les algorithmes de laboratoire où BRAF et la méthylation sont ordonnés différemment, le message clé reste identique : BRAF wild type seul ne suffit pas au diagnostic de Lynch.","Bei klarer hereditärer Auffälligkeit humangenetische Vorstellung trotz Tumormethylierung erwägen.":"En présence d'éléments héréditaires clairement évocateurs, envisager une consultation de génétique malgré la méthylation tumorale.","BRAF-WT = Lynch":"BRAF wild type = syndrome de Lynch","Negatives Ausschlussindiz ist kein positiver hereditärer Nachweis.":"Un indice d'exclusion négatif n'est pas une preuve héréditaire positive.","dMMR = Lynch":"dMMR = syndrome de Lynch","Viele MLH1/PMS2-defiziente CRC sind sporadisch methyliert.":"De nombreux CRC déficients en MLH1/PMS2 présentent une méthylation sporadique.","Methylierung löscht MSI-Therapiebedeutung":"La méthylation annule la signification thérapeutique de MSI","Therapeutische und hereditäre Ebenen werden vermischt.":"Les dimensions thérapeutique et héréditaire sont confondues.","Der BRAF-Wildtyp führt in die falsche Sicherheit":"BRAF wild type crée une fausse certitude","Obwohl BRAF V600E fehlt, ist der MLH1-Promotor deutlich methyliert. Das kippt die intuitive 'BRAF-WT = Lynch'-Kurzform und zeigt, warum der direkte epigenetische Reflex diagnostisch stärker ist.":"Bien que BRAF V600E soit absent, le promoteur de MLH1 est nettement méthylé. Cela renverse le raccourci intuitif « BRAF wild type = Lynch » et montre pourquoi le test réflexe épigénétique direct est diagnostiquement plus robuste.","Der Fall trainiert Negativbefunde, Reflexdiagnostik und die Trennung von Tumortherapie und Familienmedizin.":"Le cas entraîne à l'interprétation des résultats négatifs, au diagnostic réflexe et à la séparation entre traitement tumoral et médecine familiale/génétique.","Zwei Ebenen sauber getrennt":"Deux dimensions clairement séparées","MSI-H/dMMR therapeutisch relevant; BRAF-WT kein Lynch-Beweis; MLH1-Methylierung positiv → sporadische Silenzierung stark wahrscheinlich.":"MSI-H/dMMR pertinent sur le plan thérapeutique ; BRAF wild type ne prouve pas Lynch ; méthylation MLH1 positive → silençage sporadique très probable.","Reflexdiagnostik korrekt.":"Diagnostic réflexe correct.","Lynch offen, Methylierung vergessen":"Lynch reste ouvert, la méthylation est oubliée","BRAF-WT wird korrekt nicht überinterpretiert, aber der direkte MLH1-Reflex fehlt.":"BRAF wild type n'est correctement pas surinterprété, mais le test réflexe direct de MLH1 manque.","Diagnostik unvollständig.":"Bilan diagnostique incomplet.","Keimbahndiagnose aus negativem Tumormarker abgeleitet.":"Diagnostic germinal déduit d'un marqueur tumoral négatif.","Kritisches Overcalling.":"Surinterprétation critique.","MLH1-Methylierung positiv":"Méthylation MLH1 positive","Sporadische MLH1-Silenzierung als wahrscheinlich berichten; Klinik/Familie abgleichen.":"Rapporter un silençage sporadique de MLH1 comme probable ; corréler au contexte clinique/aux antécédents familiaux.","Viele unnötige Keimbahnabklärungen können vermieden werden, ohne Sonderfälle zu ignorieren.":"De nombreuses explorations germinales inutiles peuvent être évitées sans ignorer les situations particulières.","Humangenetische/germline Abklärung priorisieren.":"Prioriser l'évaluation génétique/germinale.","Lynch-Verdacht bleibt bestehen.":"La suspicion de syndrome de Lynch persiste.","MLH1/PMS2-Verlust ist kein automatischer Lynch-Befund.":"La perte de MLH1/PMS2 n'est pas automatiquement un résultat de Lynch.","BRAF V600E kann sporadische MLH1-Inaktivierung stützen; BRAF-Wildtyp beweist Lynch nicht.":"BRAF V600E peut étayer une inactivation sporadique de MLH1 ; BRAF wild type ne prouve pas un syndrome de Lynch.","MLH1-Promotor-Methylierung ist ein direkter epigenetischer Reflex.":"La méthylation du promoteur de MLH1 est un test réflexe épigénétique direct.","MSI-H/dMMR hat eine therapeutische Aussage unabhängig davon, ob die Ursache sporadisch oder hereditär ist.":"MSI-H/dMMR a une signification thérapeutique, que la cause soit sporadique ou héréditaire.","Sehr junges Alter oder auffällige Familienanamnese können trotz Tumormethylierung weitere Abklärung rechtfertigen.":"Un âge très jeune ou des antécédents familiaux évocateurs peuvent justifier des explorations complémentaires malgré la méthylation tumorale.","MSI-H/dMMR ist therapeutisch relevant. Für die hereditäre Einordnung ist BRAF-Wildtyp nicht beweisend; die positive MLH1-Promotor-Methylierung spricht stark für sporadische MLH1-Silenzierung. Alter und Familienanamnese bleiben als Sicherheitsnetz bestehen.":"MSI-H/dMMR est pertinent sur le plan thérapeutique. Pour l'interprétation héréditaire, BRAF wild type n'est pas concluant ; la méthylation positive du promoteur de MLH1 est fortement en faveur d'un silençage sporadique de MLH1. L'âge et les antécédents familiaux restent un filet de sécurité.","BRAF-WT nicht overcallen":"Ne pas surinterpréter BRAF wild type","Therapie vs Heredität":"Thérapie vs hérédité","Kontext":"Contexte","Warum ist ein negativer Marker selten ein positiver Beweis?":"Pourquoi un marqueur négatif constitue-t-il rarement une preuve positive ?","Wie unterscheiden sich BRAF- und MLH1-Methylierungsreflex?":"En quoi les tests réflexes BRAF et de méthylation de MLH1 diffèrent-ils ?","Wann kann Tumormethylierung eine hereditäre Ursache nicht vollständig ausschließen?":"Quand la méthylation tumorale peut-elle ne pas exclure complètement une cause héréditaire ?","MLH1-Methylierung positiv trotz BRAF-WT":"Méthylation MLH1 positive malgré BRAF wild type","BRAF-Wildtyp ist kein Lynch-Beweis":"BRAF wild type ne prouve pas un syndrome de Lynch","MMR/MSI → BRAF-Kontext → MLH1-Methylierung → hereditäre Einordnung":"MMR/MSI → contexte BRAF → méthylation MLH1 → interprétation héréditaire","mCRC und Bevacizumab: Anti-VEGF braucht keinen VHL-Test":"mCRC et bévacizumab : l'anti-VEGF ne nécessite pas de test VHL","mCRC: Bevacizumab und VEGF-Angioge…":"mCRC : bévacizumab et angiogenèse VEGF…","63-jähriger Patient mit metastasiertem rechtsseitigem Kolonkarzinom, KRAS p.G12D-mutiert. Im Board wird Bevacizumab als Bestandteil der Systemtherapie diskutiert.":"Homme de 63 ans avec cancer du côlon droit métastatique, muté KRAS p.G12D. Le board discute du bévacizumab dans le cadre du traitement systémique.","Muss vor Anti-VEGF-Therapie die VHL/HIF/VEGF-Achse des Tumors molekular getestet oder eine hohe VEGF-Expression nachgewiesen werden?":"Avant un traitement anti-VEGF, faut-il tester moléculairement l'axe VHL/HIF/VEGF de la tumeur ou démontrer une forte expression de VEGF ?","Therapieentscheidung in dieser Woche.":"Décision thérapeutique cette semaine.","Rechtsseitiges mCRC mit multiplen Lebermetastasen.":"mCRC droit avec multiples métastases hépatiques.","KRAS p.G12D; BRAF-Wildtyp; pMMR/MSS aus Basisdiagnostik.":"KRAS p.G12D ; BRAF wild type ; pMMR/MSS au bilan initial.","Anti-EGFR ist wegen RAS-Mutation nicht der naheliegende Weg; eine antiangiogene Kombination wird diskutiert.":"L'anti-EGFR n'est pas la voie évidente en raison de la mutation RAS ; une combinaison antiangiogénique est discutée.","Mechanistische Biologie wird mit einem notwendigen prädiktiven Companion Diagnostic verwechselt.":"La biologie mécanistique est confondue avec un companion diagnostic prédictif obligatoire.","Konventionelles kolorektales Adenokarzinom mit vitalen Metastasenarealen.":"Adénocarcinome colorectal conventionnel avec zones métastatiques viables.","Gefäße":"Vaisseaux","Tumor zeigt erwartbare Neovaskularisation; kein spezifischer morphologischer Selektionsmarker.":"La tumeur montre la néovascularisation attendue ; il n'existe pas de marqueur morphologique spécifique de sélection.","Basisprofil":"Profil de base","RAS-mutiert, pMMR/MSS.":"RAS muté, pMMR/MSS.","Welche Rolle spielt VEGF-Biologie für das Verständnis – und welche gerade nicht für die Testauswahl?":"Quel rôle joue la biologie du VEGF dans la compréhension, et quel rôle ne joue-t-elle précisément pas dans le choix des tests ?","FFPE-Lebermetastase, ausreichend für Zusatzanalysen.":"Métastase hépatique FFPE, adéquate pour des analyses supplémentaires.","Begrenzt; keine diagnostische Fragestellung rechtfertigt einen RCC-spezifischen VHL/HIF-Test.":"Limité ; aucune question diagnostique ne justifie un test VHL/HIF spécifique du RCC.","Mechanismus":"Mécanisme","VEGF-A ist ein zentraler proangiogener Ligand; Bevacizumab neutralisiert VEGF-A.":"VEGF-A est un ligand proangiogénique central ; le bévacizumab neutralise VEGF-A.","Ein biologisch plausibler Signalweg ist nicht automatisch ein validierter Patientenselektions-Biomarker.":"Une voie biologiquement plausible n'est pas automatiquement un biomarqueur validé de sélection des patients.","VEGF-/Angiogenese-Kontext korrekt einordnen":"Interpréter correctement le contexte VEGF/angiogenèse","CRC-Basisprofil":"Profil CRC de base","KRAS p.G12D, BRAF-Wildtyp, keine zusätzliche Alteration, die einen Anti-VEGF-spezifischen Companion-Diagnostic-Pfad definiert.":"KRAS p.G12D, BRAF wild type, sans autre altération définissant une voie de companion diagnostic spécifique de l'anti-VEGF.","VEGF-Kontext":"Contexte VEGF","Anti-VEGF hemmt einen zentralen Angiogeneseweg; beim mCRC existiert jedoch kein etablierter routinemäßiger Tumor-VEGF- oder VHL/HIF-Test, der vor Bevacizumab positiv sein muss.":"L'anti-VEGF inhibe une voie centrale de l'angiogenèse ; toutefois, dans le mCRC, il n'existe pas de test tumoral de routine VEGF ou VHL/HIF établi qui doive être positif avant le bévacizumab.","Molekularer CRC-Kontext":"Contexte moléculaire du CRC","KRAS-mutiert, pMMR/MSS.":"KRAS muté, pMMR/MSS.","Kernfrage":"Question centrale","Biologischen Wirkmechanismus von prädiktiver Testpflicht trennen.":"Séparer le mécanisme biologique d'action de l'exigence d'un test prédictif.","Bevacizumab adressiert die VEGF-A-vermittelte Angiogenese, seine klinische Anwendung beim mCRC setzt aber keinen positiven VHL/HIF-/VEGF-Tumortest voraus. Die RAS-Mutation erklärt hier den fehlenden anti-EGFR-Kontext, ist aber kein Gegenargument gegen die antiangiogene Wirklogik. Zusätzliche VHL/HIF-Testung wäre ein aus dem RCC übertragener Low-value-Copyover.":"Le bévacizumab cible l'angiogenèse médiée par VEGF-A, mais son utilisation clinique dans le mCRC ne nécessite pas de test tumoral VHL/HIF/VEGF positif. La mutation RAS explique ici l'absence de contexte anti-EGFR, mais n'est pas un argument contre la logique antiangiogénique. Un test VHL/HIF supplémentaire serait un copyover de faible valeur issu du RCC.","Teilbefund: VEGF ist biologisch relevant, aber es fehlt die Trennung zwischen Wirkmechanismus und validiertem Selektionsbiomarker.":"Résultat partiel : VEGF est biologiquement pertinent, mais la distinction entre mécanisme d'action et biomarqueur validé de sélection manque.","VEGF-A/Angiogenese als Wirkmechanismus erklären":"Expliquer VEGF-A/angiogenèse comme mécanisme d'action","Keinen routinemäßigen positiven VEGF-/VHL-Test als Voraussetzung behaupten":"Ne pas prétendre qu'un test VEGF/VHL positif de routine est requis","RAS-Mutation korrekt auf anti-EGFR, nicht auf Anti-VEGF beziehen":"Relier correctement la mutation RAS à l'anti-EGFR, et non à l'anti-VEGF","RCC-spezifische VHL/HIF-Testung vermeiden":"Éviter les tests VHL/HIF spécifiques du RCC","Falschaussage: Bevacizumab nur bei molekular aktivierter VHL/HIF-Achse":"Affirmation erronée : bévacizumab uniquement en cas d'activation moléculaire de l'axe VHL/HIF","Optimale Lösung: Anti-VEGF biologisch sauber erklären, aber keinen erfundenen Companion Diagnostic verlangen; RAS-Status und VEGF-Therapieachse sind unterschiedliche Entscheidungsebenen.":"Solution optimale : expliquer correctement la biologie anti-VEGF sans inventer de companion diagnostic ; le statut RAS et l'axe thérapeutique VEGF sont des niveaux décisionnels distincts.","Bevacizumab":"Bévacizumab","VEGF":"VEGF","Angiogenese":"Angiogenèse","KRAS":"KRAS","Biomarker hierarchy":"Hiérarchie des biomarqueurs","Anti-VEGF ist ein Wirkmechanismus, kein VHL-Companion-Diagnostic":"L'anti-VEGF est un mécanisme d'action, pas un companion diagnostic VHL","Gastroonkologie / Molekularpathologie / MTB":"Oncologie gastro-intestinale / pathologie moléculaire / MTB","VEGF-Angiogenese als Wirkmechanismus von Bevacizumab erklären.":"Expliquer l'angiogenèse VEGF comme mécanisme d'action du bévacizumab.","Wirkmechanismus und prädiktiven Companion Diagnostic sauber trennen.":"Séparer clairement mécanisme d'action et companion diagnostic prédictif.","RAS-Status korrekt auf anti-EGFR und nicht auf Anti-VEGF beziehen.":"Relier correctement le statut RAS à l'anti-EGFR et non à l'anti-VEGF.","Entitätsfremde VHL/HIF-Testung beim mCRC vermeiden.":"Éviter les tests VHL/HIF inadaptés à l'entité dans le mCRC.","Material- und Testökonomie als Teil guter Präzisionsonkologie verstehen.":"Comprendre l'économie du matériel et des tests comme une composante d'une bonne oncologie de précision.","Der Tumor ist KRAS-mutiert. Jemand fragt, ob man für Bevacizumab jetzt noch 'VHL/HIF/VEGF molekular bestätigen' müsse. Genau diese scheinbar logische Zusatzdiagnostik ist der Fehler.":"La tumeur est mutée KRAS. Quelqu'un demande s'il faut désormais « confirmer moléculairement » VHL/HIF/VEGF pour le bévacizumab. C'est précisément ce test supplémentaire apparemment logique qui constitue l'erreur.","63-jähriger Patient mit KRAS-mutiertem, pMMR/MSS mCRC. Bevacizumab wird als Teil einer systemischen Kombination diskutiert. Die Aufgabe ist nicht, einen neuen Biomarker zu erfinden, sondern Mechanismus, RAS-Kontext und echte Testpflicht zu trennen.":"Homme de 63 ans avec mCRC muté KRAS, pMMR/MSS. Le bévacizumab est envisagé dans une combinaison systémique. La tâche n'est pas d'inventer un nouveau biomarqueur, mais de distinguer mécanisme, contexte RAS et véritables exigences de tests.","RAS beantwortet eine andere Frage":"RAS répond à une autre question","KRAS p.G12D schließt einen klassischen anti-EGFR-Kontext aus.":"KRAS p.G12D exclut un contexte anti-EGFR classique.","Das macht Anti-VEGF nicht biologisch unplausibel.":"Cela ne rend pas l'anti-VEGF biologiquement non plausible.","VEGF ist zentral":"VEGF est central","Tumorangiogenese benötigt proangiogene Signale.":"L'angiogenèse tumorale nécessite des signaux proangiogéniques.","Zentraler Mechanismus bedeutet nicht automatisch Companion Diagnostic.":"Un mécanisme central n'implique pas automatiquement un companion diagnostic.","RCC-Copyover":"Copyover du RCC","VHL/HIF ist beim ccRCC kanonisch.":"VHL/HIF est canonique dans le ccRCC.","Signalwege dürfen nicht blind zwischen Entitäten als Testalgorithmus übertragen werden.":"Les voies ne doivent pas être transposées aveuglément entre entités comme algorithmes de tests.","CRC-Profil":"Profil CRC","KRAS p.G12D, BRAF-WT, pMMR/MSS":"KRAS p.G12D, BRAF wild type, pMMR/MSS","metastasiert, systemische Therapie geplant":"Métastatique, traitement systémique prévu","ausreichend, aber kein Grund für unnötige Zusatztests":"Adéquat, mais sans raison de réaliser des tests supplémentaires inutiles","Keine validierte positive VEGF-/VHL-Testpflicht vor Bevacizumab im mCRC.":"Aucune exigence validée de test VEGF/VHL positif avant le bévacizumab dans le mCRC.","Entitätsfremde Testung verbraucht Ressourcen ohne Entscheidungsgewinn.":"Des tests inadaptés à l'entité consomment des ressources sans apporter de valeur décisionnelle.","Mechanistische Erklärung kann ohne zusätzlichen Wet-lab-Test erfolgen.":"L'explication mécanistique peut être donnée sans test wet-lab supplémentaire.","Was bedeutet KRAS p.G12D für die Anti-VEGF-Frage?":"Que signifie KRAS p.G12D pour la question anti-VEGF ?","Es betrifft die anti-EGFR-Logik; es ist kein automatischer Ausschluss von Bevacizumab.":"Cela concerne la logique anti-EGFR ; ce n'est pas une exclusion automatique du bévacizumab.","Es ist eine Kontraindikation gegen Anti-VEGF.":"C'est une contre-indication à l'anti-VEGF.","Es beweist besonders gutes Bevacizumab-Ansprechen.":"Cela prouve une réponse particulièrement bonne au bévacizumab.","RAS hat im CRC gar keine therapeutische Bedeutung.":"RAS n'a aucune pertinence thérapeutique dans le CRC.","Therapieachsen müssen getrennt gehalten werden.":"Les axes thérapeutiques doivent rester distincts.","Braucht Bevacizumab einen positiven Tumor-VEGF/VHL-Test?":"Le bévacizumab nécessite-t-il un test tumoral VEGF/VHL positif ?","Nein; der Wirkmechanismus ist biologisch VEGF-gerichtet, aber es existiert kein solcher routinemäßiger Companion-Diagnostic-Pfad.":"Non ; le mécanisme d'action est biologiquement dirigé contre VEGF, mais aucune voie de companion diagnostic de routine de ce type n'existe.","Ja, VHL-Mutation ist Voraussetzung.":"Oui, une mutation VHL est requise.","Ja, hohe VEGF-IHC muss dokumentiert sein.":"Oui, une IHC VEGF élevée doit être documentée.","Ja, HIF-2α muss mutiert sein.":"Oui, HIF-2α doit être muté.","Mechanismus und Testpflicht sind nicht dasselbe.":"Mécanisme d'action et exigence de test ne sont pas la même chose.","Warum ist ein VHL/HIF-Panel hier Low-value?":"Pourquoi un panel VHL/HIF est-il de faible valeur ici ?","Es importiert ccRCC-Biologie in einen CRC-Therapiealgorithmus ohne validierten Selektionsnutzen.":"Il importe la biologie du ccRCC dans un algorithme thérapeutique du CRC sans bénéfice validé de sélection.","Nur weil es teuer ist.":"Uniquement parce que c'est coûteux.","Weil CRC keine DNA enthält.":"Parce que le CRC ne contient pas d'ADN.","Weil VEGF im CRC keine Rolle spielt.":"Parce que VEGF ne joue aucun rôle dans le CRC.","Entitätsspezifische Evidenz entscheidet.":"Les données spécifiques à l'entité déterminent la réponse.","Was ist hier Präzisionsonkologie?":"Qu'est-ce que l'oncologie de précision ici ?","Die richtigen wenigen Informationen verwenden und unnötige Tests weglassen.":"Utiliser les quelques bonnes informations et éviter les tests inutiles.","Immer das breiteste Panel bestellen.":"Toujours prescrire le panel le plus large.","Jeden bekannten Signalweg molekular bestätigen.":"Confirmer moléculairement chaque voie connue.","Nur positive Biomarker zählen.":"Seuls les biomarqueurs positifs comptent.","Präzision ist nicht Informationsmaximierung.":"La précision n'est pas la maximisation de l'information.","Formulieren Sie die Anti-VEGF-Rationale und begründen Sie explizit, warum weder KRAS-Mutation noch fehlende VHL/HIF-Testung die Bevacizumab-Logik aufheben.":"Formulez la justification anti-VEGF et expliquez explicitement pourquoi ni la mutation KRAS ni l'absence de test VHL/HIF n'invalident la logique du bévacizumab.","KRAS p.G12D als anti-EGFR-Resistenzkontext benennen.":"Identifier KRAS p.G12D comme contexte de résistance à l'anti-EGFR.","VEGF-Angiogenese als Wirkmechanismus erklären.":"Expliquer l'angiogenèse VEGF comme mécanisme d'action.","Keine positive VEGF-/VHL-Testpflicht erfinden.":"Ne pas inventer d'exigence de test VEGF/VHL positif.","VHL/HIF-Testung als entitätsfremden Low-value-Test vermeiden.":"Éviter le test VHL/HIF comme test de faible valeur inadapté à l'entité.","Therapieentscheidung im klinischen CRC-Kontext belassen.":"Maintenir la décision thérapeutique dans le contexte clinique du CRC.","Breites CRC-Panel nur, wenn andere therapeutische Fragestellungen offen sind.":"Utiliser un large panel CRC uniquement si d'autres questions thérapeutiques restent ouvertes.","VEGF-Biologie rein interpretativ erklären, ohne Zusatztest.":"Expliquer la biologie du VEGF de manière interprétative, sans test supplémentaire.","VHL testen, weil VEGF":"Tester VHL parce que VEGF","RCC-Biologie wird ohne Evidenz in CRC übertragen.":"La biologie du RCC est transposée au CRC sans preuve.","KRAS-mutiert = kein Bevacizumab":"KRAS muté = pas de bévacizumab","RAS und VEGF sind unterschiedliche therapeutische Achsen.":"RAS et VEGF sont des axes thérapeutiques différents.","Mehr Test = mehr Präzision":"Plus de tests = plus de précision","Test ohne Entscheidungsnutzen ist Low-value.":"Un test sans valeur décisionnelle est de faible valeur.","Der beste Test ist hier: keiner":"Le meilleur test ici est : aucun","Die vorhandenen Daten reichen für die Anti-VEGF-Rationale. Ein VHL/HIF-Panel würde nichts klinisch Validiertes hinzufügen. Der Twist ist, dass fachliche Tiefe nicht durch zusätzliche Diagnostik, sondern durch korrektes Weglassen entsteht.":"Les données disponibles suffisent à la justification anti-VEGF. Un panel VHL/HIF n'ajouterait rien de validé cliniquement. Le twist est que l'expertise ne se démontre pas par davantage de diagnostics, mais par leur omission correcte lorsqu'ils sont inutiles.","Er trainiert Testökonomie und verhindert pathway-driven Overdiagnostics.":"Il entraîne à l'économie des tests et évite les surdiagnostics guidés par les pathways.","Mechanismus ohne Pseudobiomarker":"Mécanisme sans pseudo-biomarqueur","KRAS-mutiertes mCRC; Anti-VEGF biologisch plausibel, kein VHL/VEGF Companion Diagnostic erforderlich.":"mCRC muté KRAS ; anti-VEGF biologiquement plausible, aucun companion diagnostic VHL/VEGF requis.","Saubere Evidenzhierarchie.":"Hiérarchie des preuves claire.","VEGF erklärt, RAS unscharf":"VEGF expliqué, RAS imprécis","Angiogenese korrekt, aber RAS-/anti-EGFR-Kontext wird vermischt.":"L'angiogenèse est correcte, mais le contexte RAS/anti-EGFR est confondu.","Therapieachsen trennen.":"Séparer les axes thérapeutiques.","VHL-Pflicht erfunden":"Exigence VHL inventée","Bevacizumab wird von einem RCC-artigen VHL/HIF-Panel abhängig gemacht.":"Le bévacizumab est rendu dépendant d'un panel VHL/HIF de type RCC.","Entitäts-Copyover.":"Copyover d'entité.","Weitere CRC-Targets offen":"Autres cibles CRC encore ouvertes","Entitätsspezifische Standarddiagnostik ergänzen.":"Compléter par les diagnostics standards spécifiques à l'entité.","Zusatztests beantworten echte Fragen.":"Les tests supplémentaires répondent à de vraies questions.","Nur Anti-VEGF-Mechanismus gefragt":"Seul le mécanisme anti-VEGF est demandé","Interpretation statt Wet-lab-Overtesting.":"Interprétation plutôt que surinvestigation wet-lab.","Material und TAT werden geschont.":"Le matériel et le TAT sont préservés.","Bevacizumab neutralisiert VEGF-A und adressiert Tumorangiogenese.":"Le bévacizumab neutralise VEGF-A et cible l'angiogenèse tumorale.","Für mCRC ist kein positiver VHL/HIF-/Tumor-VEGF-Test als Routinevoraussetzung etabliert.":"Aucun test tumoral VHL/HIF/VEGF positif n'est établi comme prérequis de routine dans le mCRC.","RAS-Status entscheidet eine andere Therapieachse.":"Le statut RAS détermine un autre axe thérapeutique.","Mechanistische Plausibilität ist nicht gleich Companion Diagnostic.":"La plausibilité mécanistique n'équivaut pas à un companion diagnostic.","Gute Präzisionsdiagnostik beinhaltet bewusstes Weglassen unnötiger Tests.":"Un bon diagnostic de précision comprend l'omission volontaire des tests inutiles.","Die KRAS-Mutation erklärt den fehlenden anti-EGFR-Kontext, nicht eine Anti-VEGF-Kontraindikation. Bevacizumab wirkt über VEGF-A; ein positiver VHL/HIF-/VEGF-Tumortest ist dafür im mCRC nicht erforderlich. VHL/HIF-Testung wäre Low-value.":"La mutation KRAS explique l'absence de contexte anti-EGFR, et non une contre-indication à l'anti-VEGF. Le bévacizumab agit via VEGF-A ; un test tumoral VHL/HIF/VEGF positif n'est pas requis dans le mCRC. Un test VHL/HIF serait de faible valeur.","Mechanismus vs Biomarker":"Mécanisme vs biomarqueur","RAS-Achse getrennt":"Axe RAS séparé","kein VHL-Copyover":"Pas de copyover VHL","Testökonomie":"Économie des tests","Warum führen Signalwegdiagramme manchmal zu Overdiagnostics?":"Pourquoi les schémas de pathways conduisent-ils parfois à des surdiagnostics ?","Was unterscheidet einen Wirkmechanismus von einem Companion Diagnostic?":"Qu'est-ce qui distingue un mécanisme d'action d'un companion diagnostic ?","Wann ist ein nicht bestellter Test die beste Entscheidung?":"Quand ne pas prescrire un test est-il la meilleure décision ?","VHL/HIF wird bewusst nicht getestet":"VHL/HIF n'est délibérément pas testé","Mechanismus ≠ Companion Diagnostic":"Mécanisme ≠ companion diagnostic","CRC-Profil → Therapieachse → VEGF-Rationale → kein Zusatztest":"Profil CRC → axe thérapeutique → justification VEGF → pas de test supplémentaire","Klarzelliges RCC: VHL/HIF/VEGF erklärt die Biologie – wählt aber nicht allein die Therapie":"RCC à cellules claires : VHL/HIF/VEGF explique la biologie — mais ne sélectionne pas à lui seul le traitement","Klarzelliges RCC: VHL/HIF/VEGF-Ach…":"RCC à cellules claires : axe VHL/HIF/VEGF…","Uroonkologie / Molekulares Tumorboard":"Oncologie urologique / Molecular Tumor Board","59-jähriger Patient mit metastasiertem klarzelligem Nierenzellkarzinom. Ein Tumorpanel weist eine inaktivierende VHL-Alteration nach.":"Homme de 59 ans avec carcinome rénal à cellules claires métastatique. Un panel tumoral détecte une altération inactivante de VHL.","Wie erklärt die VHL/HIF/VEGF-Achse die ausgeprägte Vaskularisierung und die Plausibilität von VEGFR-TKI/IO-Kombinationen – und wie weit darf man den VHL-Befund therapeutisch individualisieren?":"Comment l'axe VHL/HIF/VEGF explique-t-il la forte vascularisation et la plausibilité des combinaisons VEGFR-TKI/IO, et jusqu'où le résultat VHL peut-il individualiser le traitement ?","Erstlinienstrategie soll im interdisziplinären Board festgelegt werden.":"La stratégie de première ligne doit être définie en réunion multidisciplinaire.","Krankheit":"Maladie","Nephrektomie vor 18 Monaten; nun pulmonale und ossäre Metastasen.":"Néphrectomie il y a 18 mois ; désormais métastases pulmonaires et osseuses.","Klarzelliges RCC, typische feine Gefäßarchitektur.":"RCC à cellules claires, architecture vasculaire fine typique.","VHL Loss-of-function im Tumor.":"VHL loss-of-function dans la tumeur.","Ein häufiger biologischer Driver wird als spezifischer prädiktiver Marker für genau eine zugelassene Kombination missverstanden.":"Un driver biologique fréquent est interprété à tort comme un marqueur prédictif spécifique d'une seule combinaison approuvée.","Alveolär/nestartig aufgebauter klarzelliger Tumor mit dichtem kapillärem Netzwerk.":"Tumeur à cellules claires d'architecture alvéolaire/en nids avec réseau capillaire dense.","Biologie":"Biologie","VHL-Verlust stabilisiert HIF-Signale und fördert u. a. VEGF-abhängige Angiogenese.":"La perte de VHL stabilise la signalisation HIF et favorise notamment l'angiogenèse dépendante du VEGF.","Moderne Erstlinienoptionen kombinieren häufig Immuncheckpoint- und VEGFR-gerichtete Strategien.":"Les options modernes de première ligne combinent souvent des stratégies de checkpoint immunitaire et dirigées contre VEGFR.","Biologische Plausibilität versus echte prädiktive Individualisierung.":"Plausibilité biologique versus véritable individualisation prédictive.","Nephrektomieblock und aktuelle Metastasenbiopsie verfügbar.":"Bloc de néphrectomie et biopsie actuelle de métastase disponibles.","Testnutzen":"Utilité des tests","VHL/HIF-Kontext kann die Biologie illustrieren, ist aber für Standard-IO/TKI-Auswahl nicht zwingend als positiver Companion Diagnostic erforderlich.":"Le contexte VHL/HIF peut illustrer la biologie, mais un companion diagnostic positif n'est pas indispensable pour la sélection standard IO/TKI.","Mehr Molekulardaten dürfen keine Scheingenauigkeit bei der Auswahl zwischen mehreren klinisch etablierten Regimen erzeugen.":"Davantage de données moléculaires ne doivent pas créer une fausse précision dans le choix entre plusieurs schémas cliniquement établis.","VHL/HIF/VEGF-Biologie integrieren":"Intégrer la biologie VHL/HIF/VEGF","VHL/HIF":"VHL/HIF","Inaktivierende VHL-Alteration; Befund passt zur kanonischen ccRCC-Biologie mit HIF-Stabilisierung und proangiogenem Programm.":"Altération inactivante de VHL ; le résultat est cohérent avec la biologie canonique du ccRCC, avec stabilisation de HIF et programme proangiogénique.","Die ausgeprägte Angiogenese erklärt die Wirksamkeitslogik VEGFR-gerichteter TKIs; die Kombination mit IO adressiert gleichzeitig Tumorimmunität und Gefäß-/TME-Biologie.":"La forte angiogenèse explique la logique des TKI dirigés contre VEGFR ; l'association avec IO cible simultanément l'immunité tumorale et la biologie vasculaire/TME.","Klarzelliges RCC mit prominentem kapillärem Netzwerk.":"RCC à cellules claires avec réseau capillaire proéminent.","Kernbotschaft":"Message clé","Biologischer Driver ≠ alleiniger prädiktiver Regimenselektor.":"Driver biologique ≠ unique sélecteur prédictif du schéma thérapeutique.","Der VHL-Verlust liefert eine sehr plausible biologische Erklärung für HIF-Aktivierung und VEGF-dominierte Angiogenese des klarzelligen RCC. Daraus folgt die biologische Plausibilität VEGFR-gerichteter Therapie und kombinierter IO/VEGFR-Strategien. Der konkrete VHL-Tumorbefund ist jedoch kein alleiniger validierter Selektionsmarker, der eine bestimmte Erstlinienkombination gegenüber allen anderen festlegt.":"La perte de VHL fournit une explication biologique très plausible de l'activation de HIF et de l'angiogenèse dominée par VEGF dans le RCC à cellules claires. Cela soutient la plausibilité biologique d'un traitement dirigé contre VEGFR et des stratégies combinées IO/VEGFR. Toutefois, le résultat tumoral VHL spécifique n'est pas un marqueur de sélection validé unique imposant une combinaison de première ligne plutôt que toutes les autres.","Teilbefund: VHL/HIF/VEGF erklärt die Erkrankungsbiologie, beantwortet aber die klinische Regimenwahl nicht ohne Gesamtpatientenkontext.":"Résultat partiel : VHL/HIF/VEGF explique la biologie de la maladie, mais ne détermine pas le choix du schéma sans le contexte clinique global.","VHL-Verlust biologisch korrekt über HIF/VEGF erklären":"Expliquer biologiquement la perte de VHL via HIF/VEGF","Rationale von VEGFR-TKI + IO mechanistisch erläutern":"Expliquer mécanistiquement la logique VEGFR-TKI + IO","VHL nicht als alleinigen prädiktiven Regimenselektor verkaufen":"Ne pas présenter VHL comme l'unique sélecteur prédictif du schéma","Risikogruppe, Komorbiditäten und klinische Faktoren in der Therapieentscheidung belassen":"Conserver groupe de risque, comorbidités et facteurs cliniques dans la décision thérapeutique","Falschaussage: VHL-Mutation bestimmt zwingend eine bestimmte IO/TKI-Kombination":"Affirmation erronée : une mutation VHL impose une combinaison IO/TKI spécifique","Optimale Lösung: VHL/HIF/VEGF als Lehrbuchbeispiel einer biologisch sehr starken Achse nutzen, ohne daraus einen nicht validierten Präzisionsmarker für die konkrete Regimenwahl zu machen.":"Solution optimale : utiliser VHL/HIF/VEGF comme exemple classique d'un axe biologiquement très puissant sans en faire un marqueur de précision non validé pour sélectionner le schéma précis.","ccRCC":"ccRCC","VHL":"VHL","HIF":"HIF","VEGFR-TKI":"VEGFR-TKI","VHL erklärt fast alles – aber nicht die konkrete Regimenwahl":"VHL explique presque tout — mais pas le choix précis du schéma thérapeutique","Uroonkologie / Molekularpathologie / MTB":"Oncologie urologique / pathologie moléculaire / MTB","VHL-Verlust über HIF-Stabilisierung und VEGF-Angiogenese erklären.":"Expliquer la perte de VHL par la stabilisation de HIF et l'angiogenèse VEGF.","Die starke Vaskularisierung des ccRCC biologisch mit VEGFR-TKI verknüpfen.":"Relier biologiquement la forte vascularisation du ccRCC aux VEGFR-TKI.","Komplementäre Rationale von IO + VEGFR-TKI verstehen.":"Comprendre la logique complémentaire de IO + VEGFR-TKI.","VHL als häufigen biologischen Driver, aber nicht als alleinigen Regimenselektor einordnen.":"Considérer VHL comme un driver biologique fréquent, mais non comme l'unique sélecteur du schéma.","Klinische Faktoren neben Tumorbiologie in der Therapiewahl belassen.":"Maintenir les facteurs cliniques aux côtés de la biologie tumorale dans le choix thérapeutique.","Das Panel zeigt eine klare VHL-Loss-of-function-Mutation. Der Befund ist biologisch wunderschön – so schön, dass man leicht zu viel daraus ableitet und glaubt, er müsse nun exakt eine bestimmte Kombination bestimmen.":"Le panel montre une mutation VHL loss-of-function nette. Le résultat est biologiquement très élégant — au point qu'il devient facile d'en déduire trop et de croire qu'il doit désormais déterminer exactement une combinaison.","59-jähriger Patient mit metastasiertem klarzelligem RCC und VHL-Loss-of-function. Ziel ist, VHL/HIF/VEGF als Lehrbuchachse zu verstehen und gleichzeitig die Grenze zur klinischen Prädiktion zu ziehen.":"Homme de 59 ans avec RCC à cellules claires métastatique et VHL loss-of-function. L'objectif est de comprendre VHL/HIF/VEGF comme un axe classique tout en traçant la limite avec la prédiction clinique.","Kanonische Biologie":"Biologie canonique","VHL-Verlust → HIF-Stabilisierung → proangiogenes Programm.":"Perte de VHL → stabilisation de HIF → programme proangiogénique.","ccRCC ist ein Paradebeispiel für pathway-driven Tumorbiologie.":"Le ccRCC est un exemple emblématique de biologie tumorale pilotée par un pathway.","Therapie-Rationale":"Justification thérapeutique","VEGFR-TKI adressieren die angiogene Achse; IO adressiert Tumorimmunität/TME.":"Les VEGFR-TKI ciblent l'axe angiogénique ; IO cible l'immunité tumorale/TME.","Kombinationen können biologisch komplementär sein.":"Les associations peuvent être biologiquement complémentaires.","Grenze":"Limite","VHL ist häufig, aber kein alleiniger Selektor zwischen allen Standardregimen.":"VHL est fréquent, mais n'est pas l'unique sélecteur parmi tous les schémas standards.","Biologische Erklärung ist stärker als prädiktive Spezifität.":"L'explication biologique est plus forte que la spécificité prédictive.","typisches klarzelliges RCC mit feinem Kapillarnetz":"RCC à cellules claires typique avec fin réseau capillaire","Tumor-NGS":"NGS tumoral","VHL Loss-of-function":"VHL loss-of-function","metastasiert, Erstlinie offen":"Métastatique, choix de première ligne ouvert","Kein zusätzlicher Test muss eine bestimmte IO/TKI-Kombination 'freigeben'.":"Aucun test supplémentaire ne doit « autoriser » une combinaison IO/TKI précise.","VHL-Tumorbefund ist nicht automatisch hereditär; Keimbahnfrage nur bei passendem klinischem Kontext.":"Un résultat tumoral VHL n'est pas automatiquement héréditaire ; la question germinale ne se pose qu'en présence d'un contexte clinique approprié.","Klinische Risikogruppe, Komorbiditäten und Nebenwirkungsprofile bleiben entscheidend.":"Le groupe de risque clinique, les comorbidités et les profils de toxicité restent déterminants.","Welche Kette beschreibt die ccRCC-Biologie am besten?":"Quelle chaîne décrit le mieux la biologie du ccRCC ?","VHL-Verlust → HIF-Stabilisierung → VEGF/proangiogene Programme.":"Perte de VHL → stabilisation de HIF → programmes VEGF/proangiogéniques.","KRAS → EGFR → MSI.":"KRAS → EGFR → MSI.","BRCA → HRD → VEGF.":"BRCA → HRD → VEGF.","MMR-Verlust → VHL.":"Perte MMR → VHL.","Die VHL/HIF/VEGF-Achse ist kanonisch.":"L'axe VHL/HIF/VEGF est canonique.","Warum ist IO + VEGFR-TKI biologisch plausibel?":"Pourquoi IO + VEGFR-TKI est-il biologiquement plausible ?","Gefäß-/TME- und Immunachsen werden komplementär adressiert.":"Les axes vasculaire/TME et immunitaire sont ciblés de manière complémentaire.","Weil nur VHL-mutierte Tumoren IO vertragen.":"Parce que seules les tumeurs mutées VHL tolèrent IO.","Beide Medikamente blockieren exakt dasselbe Molekül.":"Les deux médicaments bloquent exactement la même molécule.","Weil PD-L1 immer hoch sein muss.":"Parce que PD-L1 doit toujours être élevé.","Die Kombination adressiert unterschiedliche, interagierende Ebenen.":"L'association cible des niveaux différents et interactifs.","Was darf aus VHL Loss-of-function NICHT abgeleitet werden?":"Que ne faut-il PAS déduire d'un VHL loss-of-function ?","Dass genau eine bestimmte Erstlinienkombination zwingend die einzig richtige ist.":"Qu'une seule combinaison précise de première ligne soit nécessairement l'unique bon choix.","Dass HIF/VEGF-Biologie plausibel ist.":"Que la biologie HIF/VEGF est plausible.","Dass angiogene Programme typisch sein können.":"Que des programmes angiogéniques puissent être typiques.","Dass der Befund zur ccRCC-Biologie passt.":"Que le résultat est cohérent avec la biologie du ccRCC.","VHL ist biologisch stark, aber nicht so prädiktiv spezifisch.":"VHL est biologiquement fort, mais pas aussi spécifique sur le plan prédictif.","Wann wird aus Tumor-VHL eine Keimbahnfrage?":"Quand un résultat tumoral VHL devient-il une question germinale ?","Bei passendem Alter, multifokaler/bilateraler Erkrankung oder VHL-Syndrom-typischem klinischem Kontext – nicht automatisch bei jedem somatischen Tumorbefund.":"En cas d'âge approprié, de maladie multifocale/bilatérale ou de contexte clinique typique d'un syndrome VHL — pas automatiquement pour chaque résultat tumoral somatique.","Immer.":"Toujours.","Nur wenn TKI versagt.":"Uniquement si le TKI échoue.","Tumor- und Keimbahnebene müssen getrennt werden.":"Les niveaux tumoral et germinal doivent être distingués.","Erklären Sie im MTB VHL/HIF/VEGF und die Kombination von antiangiogener und immunologischer Therapie, ohne den VHL-Befund zu einem nicht validierten Ein-Patient-ein-Regime-Marker zu machen.":"Expliquez en MTB VHL/HIF/VEGF et l'association d'un traitement antiangiogénique et immunologique sans transformer le résultat VHL en marqueur non validé « un patient–un schéma ».","VHL-Verlust biologisch erklären.":"Expliquer biologiquement la perte de VHL.","HIF/VEGF-Angiogenese ableiten.":"Déduire l'angiogenèse HIF/VEGF.","VEGFR-TKI-Rationale erläutern.":"Expliquer la logique des VEGFR-TKI.","IO-Komponente als komplementäre Immun-/TME-Achse erklären.":"Expliquer la composante IO comme axe immunitaire/TME complémentaire.","VHL nicht als alleinigen Regimenselektor überinterpretieren.":"Ne pas surinterpréter VHL comme unique sélecteur du schéma.","Keimbahnfrage nur bei klinischem Anlass öffnen.":"N'ouvrir la question germinale qu'en cas d'indication clinique.","Auf VHL-Testung verzichten, wenn Histologie und klinische Therapiefrage bereits klar sind; der Fall nutzt sie als didaktischen Biologieanker.":"Ne pas tester VHL lorsque l'histologie et la question thérapeutique clinique sont déjà claires ; le cas l'utilise comme ancrage didactique de biologie.","Breiteres Panel nur bei zusätzlicher Target-/Studienfrage.":"Utiliser un panel plus large uniquement pour une question supplémentaire de cible/étude.","VHL = bestimmtes Regime":"VHL = schéma précis","Biologischer Driver besitzt nicht diese prädiktive Spezifität.":"Le driver biologique ne possède pas cette spécificité prédictive.","Tumor-VHL = VHL-Syndrom":"VHL tumoral = syndrome VHL","Somatisch und Keimbahn werden verwechselt.":"Somatique et germinal sont confondus.","VEGF-TKI und IO tun dasselbe":"VEGF-TKI et IO font la même chose","Komplementäre Mechanismen werden verkannt.":"Les mécanismes complémentaires sont méconnus.","Der stärkste biologische Befund ist nicht der stärkste Selektionsmarker":"Le résultat biologique le plus fort n'est pas le marqueur de sélection le plus fort","VHL Loss-of-function passt perfekt zum Tumor und erklärt die Angiogenese. Trotzdem wählt er nicht allein zwischen den klinisch etablierten Erstlinienoptionen. Der Fall kippt von 'Pathway gefunden' zu 'Evidenzgrad verstanden'.":"Le VHL loss-of-function correspond parfaitement à la tumeur et explique l'angiogenèse. Pourtant, il ne choisit pas à lui seul entre les options de première ligne cliniquement établies. Le cas passe de « pathway identifié » à « niveau de preuve compris ».","Präzisionsonkologie braucht Grenzen selbst bei sehr überzeugender Biologie.":"L'oncologie de précision a besoin de limites même face à une biologie très convaincante.","Biologie stark, Prädiktion begrenzt":"Biologie forte, prédiction limitée","VHL/HIF/VEGF korrekt erklärt; IO/TKI plausibel; konkrete Regimenwahl klinisch, nicht allein VHL-basiert.":"VHL/HIF/VEGF correctement expliqué ; IO/TKI plausible ; le choix précis du schéma est clinique, et non fondé sur VHL seul.","Sehr gute Hierarchie.":"Très bonne hiérarchie.","Achse verstanden, Regime überpräzisiert":"Axe compris, schéma sur-précisé","VHL korrekt, aber eine Kombination wird molekular zwingend gemacht.":"VHL est correctement interprété, mais une combinaison est rendue moléculairement obligatoire.","Biologie überinterpretiert.":"Biologie surinterprétée.","VHL ignoriert oder germline gesetzt":"VHL ignoré ou attribué au germinal","Entweder zentrale Biologie verpasst oder somatischen Befund automatisch hereditär erklärt.":"Soit la biologie centrale est manquée, soit le résultat somatique est automatiquement déclaré héréditaire.","Integration misslungen.":"Intégration échouée.","VHL-Syndrom-verdächtige Klinik":"Contexte clinique évocateur d'un syndrome VHL","Humangenetische Abklärung separat initiieren.":"Initier séparément une évaluation génétique.","Hereditäre Ebene korrekt adressiert.":"Dimension héréditaire correctement abordée.","Standard metastasiertes ccRCC":"ccRCC métastatique standard","Regimenwahl anhand aktueller klinischer Kriterien/Guidelines.":"Choix du schéma selon les critères cliniques/guidelines actuels.","Molekularbiologie informiert, ersetzt aber nicht die klinische Auswahl.":"La biologie moléculaire informe, mais ne remplace pas le choix clinique.","VHL/HIF/VEGF ist eine kanonische ccRCC-Achse.":"VHL/HIF/VEGF est un axe canonique du ccRCC.","VEGFR-TKI haben eine starke biologische Rationale im hochangiogenen ccRCC.":"Les VEGFR-TKI ont une forte justification biologique dans le ccRCC hautement angiogénique.","IO/VEGFR-Kombinationen adressieren komplementäre Ebenen.":"Les combinaisons IO/VEGFR ciblent des niveaux complémentaires.","VHL ist kein alleiniger validierter Selektor für ein bestimmtes Standardregime.":"VHL n'est pas un sélecteur validé unique pour un schéma standard précis.","Somatischer VHL-Befund ist nicht automatisch VHL-Syndrom.":"Un résultat somatique VHL ne signifie pas automatiquement syndrome VHL.","VHL Loss-of-function erklärt HIF-Stabilisierung und VEGF-dominierte Angiogenese des ccRCC. Diese Biologie macht VEGFR-gerichtete und kombinierte IO/VEGFR-Strategien plausibel, bestimmt aber nicht allein das konkrete Regime. Klinischer Gesamtkontext bleibt entscheidend.":"Le VHL loss-of-function explique la stabilisation de HIF et l'angiogenèse dominée par VEGF dans le ccRCC. Cette biologie rend plausibles les stratégies dirigées contre VEGFR et combinées IO/VEGFR, mais ne détermine pas à elle seule le schéma précis. Le contexte clinique global reste déterminant.","VHL/HIF/VEGF":"VHL/HIF/VEGF","Kombinationsrationale":"Justification de l'association","prädiktive Grenze":"Limite prédictive","somatisch vs germline":"Somatique vs germinal","Warum sind manche Driver diagnostisch stark, aber prädiktiv schwach?":"Pourquoi certains drivers sont-ils forts sur le plan diagnostique mais faibles sur le plan prédictif ?","Welche TME-Effekte können VEGF-Inhibition immunologisch haben?":"Quels effets immunologiques sur le TME l'inhibition du VEGF peut-elle avoir ?","Wann wird eine Tumor-VHL-Variante humangenetisch relevant?":"Quand une variante tumorale VHL devient-elle pertinente pour la génétique clinique ?","VHL erklärt Biologie, aber nicht allein das Regime":"VHL explique la biologie, mais pas à lui seul le schéma","Pathway-Stärke ≠ Selektionsspezifität":"Force du pathway ≠ spécificité de sélection","VHL → HIF/VEGF → TKI/IO-Rationale → klinische Regimenwahl":"VHL → HIF/VEGF → justification TKI/IO → choix clinique du schéma","Rezidiv-Glioblastom unter Bevacizumab: Wenn das MRT besser aussieht als der Tumor":"Glioblastome récidivant sous bévacizumab : quand l'IRM paraît meilleure que la tumeur","Glioblastom mit Gefäßproliferation…":"Glioblastome avec prolifération vasculaire…","Neuroonkologie / Neuro-Radiologie / MTB":"Neuro-oncologie / Neuroradiologie / MTB","62-jähriger Patient mit rezidiviertem IDH-Wildtyp-Glioblastom, ausgeprägtem perifokalem Ödem und steroidabhängigen neurologischen Symptomen. Bevacizumab wird zur Krankheits- und Symptomkontrolle diskutiert.":"Homme de 62 ans avec glioblastome IDH-wild-type récidivant, important œdème périfocal et symptômes neurologiques dépendants des corticoïdes. Le bévacizumab est discuté pour le contrôle de la maladie et des symptômes.","Was kann Anti-VEGF kurzfristig bewirken – und warum darf eine dramatische Abnahme der Kontrastmittelaufnahme nicht automatisch als proportionale Tumorzellreduktion gelesen werden?":"Que peut obtenir l'anti-VEGF à court terme, et pourquoi une diminution spectaculaire du rehaussement ne doit-elle pas être interprétée automatiquement comme une réduction proportionnelle des cellules tumorales ?","Hoher Symptomdruck durch Ödem.":"Forte charge symptomatique liée à l'œdème.","Operation, Radiochemotherapie und Temozolomid; jetzt erstes relevantes Rezidiv.":"Chirurgie, radiochimiothérapie et témozolomide ; désormais première récidive cliniquement significative.","Hemiparese und Kopfschmerzen, Dexamethasonbedarf steigend.":"Hémiparésie et céphalées, besoins croissants en dexaméthasone.","MRT":"IRM","Stark kontrastmittelaufnehmendes Rezidiv mit ausgeprägtem vasogenem Ödem.":"Récidive fortement rehaussée avec important œdème vasogénique.","Radiologische Kontrastmittelreduktion nach Anti-VEGF wird mit echter Zytoreduktion gleichgesetzt.":"La diminution radiologique du rehaussement après anti-VEGF est assimilée à une véritable cytoréduction.","Glioblastomtypische Nekrosen und mikrovaskuläre Proliferation.":"Nécroses et prolifération microvasculaire typiques du glioblastome.","Hypoxie und proangiogene Signale prägen den Tumor.":"L'hypoxie et les signaux proangiogéniques façonnent la tumeur.","Anti-VEGF-Effekt":"Effet anti-VEGF","Gefäßpermeabilität und Ödem können rasch abnehmen.":"La perméabilité vasculaire et l'œdème peuvent diminuer rapidement.","Wie wird die Bildgebung nach Therapiebeginn korrekt interpretiert?":"Comment l'imagerie doit-elle être correctement interprétée après le début du traitement ?","Archiviertes Resektat ausreichend; keine neue Biopsie allein zur 'VEGF-Testung' erforderlich.":"La pièce de résection archivée est adéquate ; aucune nouvelle biopsie n'est requise uniquement pour un « test VEGF ».","Testfalle":"Piège de test","Ein RCC-spezifischer VHL/HIF-Test hat hier keinen sinnvollen Selektionsnutzen.":"Un test VHL/HIF spécifique du RCC n'a ici aucune utilité de sélection pertinente.","Radiologie":"Radiologie","Kontrastmittelaufnahme ist stark von Blut-Hirn-Schranken-Permeabilität abhängig.":"Le rehaussement dépend fortement de la perméabilité de la barrière hémato-encéphalique.","Symptomverbesserung kann real sein, auch wenn der antitumorale Effekt begrenzt bleibt.":"L'amélioration symptomatique peut être réelle même si l'effet antitumoral reste limité.","Anti-VEGF-/Angiogenese-Kontext":"Contexte anti-VEGF/angiogenèse","GBM zeigt ausgeprägte Gefäßproliferation; Anti-VEGF kann Gefäßpermeabilität und vasogenes Ödem rasch reduzieren.":"Le GBM présente une prolifération vasculaire marquée ; l'anti-VEGF peut réduire rapidement la perméabilité vasculaire et l'œdème vasogénique.","VHL/HIF-Panel":"Panel VHL/HIF","RCC-spezifische VHL/HIF-Testung liefert für diesen GBM-Fall keinen validierten Therapie-Selektionsnutzen und wäre ein entitätsfremder Low-value-Test.":"Le test VHL/HIF spécifique du RCC n'apporte aucun bénéfice validé de sélection thérapeutique dans ce cas de GBM et serait un test de faible valeur inadapté à l'entité.","Zusätzliche genomische Information ändert die zentrale Anti-VEGF-/Imaging-Lernfrage nicht.":"Des informations génomiques supplémentaires ne modifient pas la question centrale d'apprentissage anti-VEGF/imagerie.","MRT vor Therapie":"IRM avant traitement","Starke Kontrastmittelaufnahme und ausgeprägtes vasogenes Ödem.":"Rehaussement marqué et important œdème vasogénique.","Steroidabhängige fokal-neurologische Symptome.":"Symptômes neurologiques focaux dépendants des corticoïdes.","Anti-VEGF kann beim rezidivierten Glioblastom rasch Gefäßpermeabilität und Ödem reduzieren und damit Symptome sowie Kontrastmittelaufnahme deutlich verbessern. Diese radiologische 'Pseudoresponse' darf jedoch nicht mit einer proportionalen Eliminierung infiltrierender Tumorzellen gleichgesetzt werden. Verlaufskontrolle muss deshalb neben Kontrastmittelaufnahme auch FLAIR/non-enhancing disease, Klinik und Steroidbedarf integrieren.":"L'anti-VEGF peut réduire rapidement la perméabilité vasculaire et l'œdème dans le glioblastome récidivant, avec une nette amélioration des symptômes et du rehaussement. Cependant, cette « pseudoresponse » radiologique ne doit pas être assimilée à une élimination proportionnelle des cellules tumorales infiltrantes. Le suivi doit intégrer le rehaussement, le FLAIR/non-enhancing disease, la clinique et les besoins en corticoïdes.","Teilbefund: Die Gefäßreaktion kann eindrucksvoll sein, sagt aber allein wenig über die gesamte infiltrative Tumorlast aus.":"Résultat partiel : la réponse vasculaire peut être impressionnante, mais à elle seule renseigne peu sur la charge tumorale infiltrante totale.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem erklären":"Expliquer l'effet anti-VEGF sur la perméabilité vasculaire/l'œdème","Pseudoresponse von echter proportionaler Zytoreduktion trennen":"Distinguer pseudoresponse et véritable cytoréduction proportionnelle","FLAIR/non-enhancing disease und Klinik mitbewerten":"Évaluer également FLAIR/non-enhancing disease et la clinique","RCC-VHL/HIF-Testung nicht importieren":"Ne pas importer les tests VHL/HIF du RCC","Falschaussage: 80 % weniger Enhancement = 80 % weniger Tumorzellen":"Affirmation erronée : 80 % de rehaussement en moins = 80 % de cellules tumorales en moins","Optimale Lösung: Bevacizumab kann klinisch sehr wertvolle Ödem-/Permeabilitätseffekte erzeugen; gerade deshalb muss die beeindruckende MRT-Reaktion als mögliche Pseudoresponse erkannt und multimodal beurteilt werden.":"Solution optimale : le bévacizumab peut produire des effets cliniquement précieux sur l'œdème/la perméabilité ; c'est précisément pourquoi l'impressionnante réponse IRM doit être reconnue comme une possible pseudoresponse et évaluée de manière multimodale.","Glioblastom":"Glioblastome","Pseudoresponse":"Pseudoresponse","Ödem":"Œdème","Das MRT schrumpft schneller als der Tumor":"L'IRM rétrécit plus vite que la tumeur","Neuroonkologie / Neuroradiologie / MTB":"Neuro-oncologie / Neuroradiologie / MTB","VEGF-bedingte Gefäßpermeabilität und Ödem beim GBM erklären.":"Expliquer la perméabilité vasculaire et l'œdème liés au VEGF dans le GBM.","Anti-VEGF-bedingte Pseudoresponse erkennen.":"Reconnaître la pseudoresponse induite par l'anti-VEGF.","Kontrastmittelreduktion nicht direkt in Tumorzellreduktion übersetzen.":"Ne pas traduire directement la diminution du rehaussement en diminution du nombre de cellules tumorales.","FLAIR/non-enhancing disease, Klinik und Steroidbedarf in die Verlaufskontrolle integrieren.":"Intégrer FLAIR/non-enhancing disease, clinique et besoins en corticoïdes au suivi.","Entitätsfremde VHL/HIF-Testung vermeiden.":"Éviter les tests VHL/HIF inadaptés à l'entité.","Zwei Wochen nach Bevacizumab ist die Kontrastmittelaufnahme dramatisch kleiner, der Patient braucht weniger Steroid und fühlt sich besser. Auf den ersten Blick ein spektakuläres Tumoransprechen – bis man versteht, was Anti-VEGF mit der Blut-Hirn-Schranke macht.":"Deux semaines après le bévacizumab, le rehaussement a fortement diminué, le patient a besoin de moins de corticoïdes et se sent mieux. À première vue, une réponse tumorale spectaculaire — jusqu'à comprendre ce que l'anti-VEGF fait à la barrière hémato-encéphalique.","62-jähriger Patient mit symptomatischem Rezidiv eines IDH-Wildtyp-Glioblastoms. Bevacizumab wird wegen Ödem und Progress eingesetzt. Der Fall lehrt, echte klinische Verbesserung und radiologische Pseudoresponse gleichzeitig richtig zu würdigen.":"Homme de 62 ans avec récidive symptomatique d'un glioblastome IDH-wild-type. Le bévacizumab est utilisé pour l'œdème et la progression. Le cas apprend à apprécier correctement à la fois l'amélioration clinique réelle et la pseudoresponse radiologique.","Gefäßpermeabilität":"Perméabilité vasculaire","GBM-Gefäße sind abnormal und leaky.":"Les vaisseaux du GBM sont anormaux et perméables.","Enhancement ist nicht nur Tumormasse, sondern auch Blut-Hirn-Schranken-Phänomen.":"Le rehaussement reflète non seulement la masse tumorale, mais aussi un phénomène de barrière hémato-encéphalique.","Anti-VEGF kann wirklich helfen":"L'anti-VEGF peut réellement aider","Ödem und Steroidbedarf sinken.":"L'œdème et les besoins en corticoïdes diminuent.","Pseudoresponse bedeutet nicht 'kein Nutzen'.":"Pseudoresponse ne signifie pas « aucun bénéfice ».","Aber Imaging kann täuschen":"Mais l'imagerie peut tromper","Non-enhancing/infiltrative disease kann fortbestehen.":"La maladie non rehaussée/infiltrante peut persister.","Response muss multimodal bewertet werden.":"La réponse doit être évaluée de manière multimodale.","Vor Therapie":"Avant traitement","starkes Enhancement + massives vasogenes Ödem":"Rehaussement marqué + œdème vasogénique massif","Hemiparese, Kopfschmerz, Steroidbedarf":"Hémiparésie, céphalées, besoins en corticoïdes","Nekrose + mikrovaskuläre Proliferation":"Nécrose + prolifération microvasculaire","Keine neue Biopsie nur zur VEGF-Testung nötig.":"Aucune nouvelle biopsie n'est requise uniquement pour tester VEGF.","VHL/HIF-Panel ist hier ein bewusster RCC-Copyover und nicht erforderlich.":"Le panel VHL/HIF est ici un copyover délibéré du RCC et n'est pas nécessaire.","Radiologische Verlaufskriterien müssen Anti-VEGF-Effekte berücksichtigen.":"Les critères radiologiques de réponse doivent tenir compte des effets anti-VEGF.","Was erklärt die schnelle Abnahme des Enhancements am besten?":"Qu'est-ce qui explique le mieux la diminution rapide du rehaussement ?","Reduzierte Gefäßpermeabilität/Normalisierung und weniger Ödem können einen großen Anteil beitragen.":"La réduction de la perméabilité vasculaire/normalisation et de l'œdème peut y contribuer largement.","Es beweist proportional dieselbe Abnahme der Tumorzellzahl.":"Cela prouve une diminution proportionnelle du nombre de cellules tumorales.","IDH-Mutation entsteht unter Therapie.":"Une mutation IDH apparaît sous traitement.","Es ist immer Strahlennekrose.":"Il s'agit toujours d'une radionécrose.","Anti-VEGF beeinflusst die Blut-Hirn-Schranke stark.":"L'anti-VEGF influence fortement la barrière hémato-encéphalique.","Was bedeutet 'Pseudoresponse'?":"Que signifie « pseudoresponse » ?","Radiologisch eindrucksvolle Abnahme des Enhancements kann den antitumoralen Zell-Effekt überschätzen.":"Une diminution radiologiquement impressionnante du rehaussement peut surestimer l'effet antitumoral cellulaire.","Jede klinische Verbesserung ist eingebildet.":"Toute amélioration clinique est imaginaire.","Es bedeutet zwingend Progress.":"Cela signifie nécessairement une progression.","MRT ist technisch unbrauchbar.":"L'IRM est techniquement inutilisable.","Der Nutzen kann real sein, aber Enhancement überschätzt den Zell-Effekt.":"Le bénéfice peut être réel, mais le rehaussement surestime l'effet cellulaire.","Was muss zusätzlich betrachtet werden?":"Que faut-il également prendre en compte ?","FLAIR/non-enhancing disease, Klinik, Steroidbedarf und serieller Verlauf.":"FLAIR/non-enhancing disease, clinique, besoins en corticoïdes et évolution sériée.","Nur kontrastmittelaufnehmendes Volumen.":"Uniquement le volume rehaussé.","VHL-Mutationsstatus.":"Statut mutationnel VHL.","PD-L1-IHC.":"IHC PD-L1.","Anti-VEGF erfordert breitere Responsebewertung.":"L'anti-VEGF nécessite une évaluation plus large de la réponse.","Warum ist VHL/HIF-Panel hier falsch?":"Pourquoi le panel VHL/HIF est-il incorrect ici ?","Es importiert einen RCC-spezifischen Test ohne validierten Selektionsnutzen in den GBM-Fall.":"Il importe dans le cas de GBM un test spécifique du RCC sans utilité de sélection validée.","GBM hat keine DNA.":"Le GBM ne contient pas d'ADN.","VEGF ist im GBM irrelevant.":"VEGF n'a pas d'intérêt dans le GBM.","Nur wegen TAT.":"Uniquement à cause du TAT.","Angiogenese ist gemeinsam, Testalgorithmen sind entitätsspezifisch.":"L'angiogenèse est commune, mais les algorithmes de tests sont spécifiques à l'entité.","Bewerten Sie die frühe MRT- und klinische Veränderung nach Bevacizumab und formulieren Sie, warum eine starke Kontrastmittelreduktion nicht automatisch eine gleich starke Zytoreduktion bedeutet.":"Évaluez les modifications précoces de l'IRM et de la clinique après bévacizumab et expliquez pourquoi une forte diminution du rehaussement n'implique pas automatiquement une cytoréduction équivalente.","Anti-VEGF-Effekt auf Gefäßpermeabilität/Ödem benennen.":"Identifier l'effet anti-VEGF sur la perméabilité vasculaire/l'œdème.","Klinische Symptomverbesserung anerkennen.":"Reconnaître l'amélioration clinique symptomatique.","Pseudoresponse erklären.":"Expliquer la pseudoresponse.","FLAIR/non-enhancing disease und seriellen Verlauf integrieren.":"Intégrer FLAIR/non-enhancing disease et l'évolution sériée.","VHL/HIF-Testung vermeiden.":"Éviter les tests VHL/HIF.","Wenn Bildgebung und Klinik diskordant bleiben, neuroradiologische Spezialverfahren/Verlauf nutzen.":"Si l'imagerie et la clinique restent discordantes, utiliser des techniques neuroradiologiques spécialisées/un suivi.","Bevacizumab primär symptomatisch/krankheitskontrollierend diskutieren, ohne radiologische Überversprechen.":"Discuter le bévacizumab principalement pour le contrôle symptomatique/de la maladie, sans surpromettre la réponse radiologique.","Enhancement = Tumorzellzahl":"Rehaussement = nombre de cellules tumorales","BBB-Permeabilität beeinflusst Enhancement stark.":"La perméabilité de la BBB influence fortement le rehaussement.","Pseudoresponse = kein Nutzen":"Pseudoresponse = aucun bénéfice","Ödem- und Steroidreduktion können klinisch sehr relevant sein.":"La diminution de l'œdème et des besoins en corticoïdes peut être très pertinente cliniquement.","VHL testen":"Tester VHL","RCC-Copyover ohne Selektionsnutzen.":"Copyover du RCC sans utilité de sélection.","80 % weniger Enhancement, aber nicht 80 % weniger Tumor":"80 % de rehaussement en moins, mais pas 80 % de tumeur en moins","Der Patient verbessert sich und das MRT sieht spektakulär aus. FLAIR zeigt jedoch weiter infiltrative Erkrankung. Der Twist ist doppelt: Der Effekt ist klinisch real und radiologisch zugleich potenziell irreführend.":"Le patient s'améliore et l'IRM paraît spectaculaire. Pourtant, le FLAIR montre toujours une maladie infiltrante. Le twist est double : l'effet est cliniquement réel et, en même temps, potentiellement trompeur sur le plan radiologique.","Er verhindert sowohl Über- als auch Unterbewertung antiangiogener Therapie.":"Il évite à la fois la surestimation et la sous-estimation du traitement antiangiogénique.","Pseudoresponse richtig gelesen":"Pseudoresponse correctement interprétée","Ödem/Enhancement deutlich geringer, Klinik besser; infiltrative FLAIR-Komponente bleibt → Response nicht als proportionale Zytoreduktion überinterpretieren.":"Œdème/rehaussement nettement réduits, clinique améliorée ; composante infiltrante FLAIR persistante → ne pas surinterpréter la réponse comme une cytoréduction proportionnelle.","Neuroonkologische Response korrekt.":"Réponse neuro-oncologique correctement interprétée.","Pseudoresponse erkannt, Nutzen abgewertet":"Pseudoresponse reconnue, bénéfice minimisé","Imaging-Falle erkannt, aber reale Symptom-/Ödemkontrolle fälschlich als bedeutungslos bezeichnet.":"Le piège d'imagerie est reconnu, mais le véritable contrôle des symptômes/de l'œdème est à tort considéré comme sans importance.","Zu einseitig.":"Trop unilatéral.","MRT = Zellzählung":"IRM = comptage cellulaire","Kontrastmittelvolumen wird direkt als Tumormasse interpretiert.":"Le volume rehaussé est directement interprété comme masse tumorale.","Zentralen Anti-VEGF-Effekt verpasst.":"L'effet central de l'anti-VEGF est manqué.","Enhancement sinkt, FLAIR stabil/steigend":"Le rehaussement diminue, FLAIR stable/en augmentation","Pseudoresponse/discordant response erwägen und seriell beurteilen.":"Envisager une pseudoresponse/réponse discordante et évaluer dans le temps.","Keine falsche Vollremission.":"Pas de fausse rémission complète.","Steroidbedarf sinkt":"Les besoins en corticoïdes diminuent","Als echten klinischen Benefit dokumentieren.":"Documenter comme bénéfice clinique réel.","Symptomkontrolle wird nicht kleingeredet.":"Le contrôle symptomatique n'est pas minimisé.","VEGF-Inhibition kann Gefäßpermeabilität und Ödem rasch reduzieren.":"L'inhibition du VEGF peut réduire rapidement la perméabilité vasculaire et l'œdème.","Kontrastmittelaufnahme ist beim GBM kein reiner Tumorzellmarker.":"Le rehaussement dans le GBM n'est pas un marqueur pur des cellules tumorales.","Pseudoresponse kann gleichzeitig mit echter klinischer Besserung bestehen.":"Une pseudoresponse peut coexister avec une véritable amélioration clinique.","FLAIR/non-enhancing disease und Klinik gehören in die Verlaufskontrolle.":"FLAIR/non-enhancing disease et la clinique doivent faire partie de l'évaluation de suivi.","Angiogenese-Biologie rechtfertigt nicht automatisch VHL/HIF-Tumortestung.":"La biologie de l'angiogenèse ne justifie pas automatiquement un test tumoral VHL/HIF.","Nach Bevacizumab sinken Enhancement, Ödem und Steroidbedarf deutlich. Das ist klinisch relevant, kann aber den zytoreduktiven Effekt überschätzen. FLAIR/non-enhancing disease und Verlauf müssen integriert werden; ein RCC-artiges VHL/HIF-Panel hat keinen Selektionsnutzen.":"Après bévacizumab, le rehaussement, l'œdème et les besoins en corticoïdes diminuent nettement. Cela est cliniquement pertinent, mais peut surestimer l'effet cytoréducteur. FLAIR/non-enhancing disease et l'évolution doivent être intégrés ; un panel VHL/HIF de type RCC n'a aucune utilité de sélection.","Ödem vs Tumor":"Œdème vs tumeur","multimodale Bildgebung":"Imagerie multimodale","kein RCC-Copyover":"Pas de copyover RCC","Wie unterscheiden sich Pseudoprogression und Pseudoresponse?":"En quoi pseudoprogression et pseudoresponse diffèrent-elles ?","Welche klinischen Parameter helfen bei anti-VEGF?":"Quels paramètres cliniques sont utiles sous traitement anti-VEGF ?","Warum ist Enhancement biologisch kein einfacher Tumormasse-Readout?":"Pourquoi le rehaussement n'est-il pas biologiquement un simple readout de la masse tumorale ?","dramatische MRT-Besserung trotz persistierender FLAIR-Krankheit":"Amélioration spectaculaire à l'IRM malgré une maladie FLAIR persistante","Anti-VEGF verändert Bildgebung und Klinik unterschiedlich":"L'anti-VEGF modifie différemment l'imagerie et la clinique","VEGF/Ödem → Bevacizumab → Enhancement fällt → multimodale Response":"VEGF/œdème → bévacizumab → baisse du rehaussement → évaluation multimodale de la réponse","PD-L1 und TMB sehen gut aus – aber die T-Zellen bleiben im Stroma":"PD-L1 et TMB semblent favorables — mais les cellules T restent dans le stroma","Stromareicher Tumor mit immune-exc…":"Tumeur riche en stroma avec immune-exc…","68-jähriger Patient mit metastasiertem Urothelkarzinom. Vor Checkpoint-Therapie lagen PD-L1-Expression und eine relativ hohe Mutationslast vor; klinisch kam es dennoch zu frühem Progress.":"Homme de 68 ans avec carcinome urothélial métastatique. Avant le traitement par checkpoint, une expression PD-L1 et une charge mutationnelle relativement élevée étaient présentes ; une progression clinique précoce est néanmoins survenue.","Wie kann ein scheinbar immunogener Tumor trotzdem primär resistent sein – und was lehrt die räumliche Verteilung der Immunzellen?":"Comment une tumeur apparemment immunogène peut-elle malgré tout être primitivement résistante, et que nous apprend la distribution spatiale des cellules immunitaires ?","Retrospektive Einordnung und Studienplanung für die nächste Linie.":"Interprétation rétrospective et planification d'étude pour la ligne suivante.","PD-L1 hoch; TMB erhöht; kein MSI-H-Kontext.":"PD-L1 élevé ; TMB augmenté ; pas de contexte MSI-H.","Checkpoint-Inhibition mit frühem radiologischem Progress.":"Inhibition de checkpoint avec progression radiologique précoce.","Biopsie":"Biopsie","Progressionsbiopsie zeigt stark stromareichen Tumor.":"La biopsie de progression montre une tumeur très riche en stroma.","Biomarkerwerte werden ohne räumlichen Zellkontext als Garantie für Immunantwort interpretiert.":"Les valeurs de biomarqueurs sont interprétées comme une garantie de réponse immunitaire sans contexte cellulaire spatial.","Invasive Tumornester in breiten fibrotischen Stromasepten.":"Nids tumoraux invasifs au sein de larges septa stromaux fibreux.","CD8":"CD8","Viele T-Zellen vorhanden, aber überwiegend im peritumoralen Stroma; Tumorzellnester selbst sind arm an CD8-Zellen.":"De nombreuses cellules T sont présentes, mais surtout dans le stroma péritumoral ; les nids tumoraux eux-mêmes contiennent peu de cellules CD8.","CAF-Kontext":"Contexte CAF","FAP/αSMA-reiches aktiviertes Stroma.":"Stroma activé riche en FAP/αSMA.","Immune-excluded statt wirklich inflamed/hot.":"Immune-excluded plutôt que véritablement inflamed/hot.","Progressionsbiopsie mit 45 % Tumoranteil.":"Biopsie de progression avec 45 % de contenu tumoral.","ausreichend für fokussierte TIL-/Stroma-IHC.":"Adéquate pour une IHC ciblée TIL/stroma.","Evidenzgrenze":"Limite des preuves","TME-IHC erklärt die Resistenzbiologie, ist aber kein routinemäßiger alleiniger Therapieausschluss- oder Auswahltest.":"L'IHC du TME explique la biologie de la résistance, mais n'est pas un test de routine autonome d'exclusion ou de sélection thérapeutique.","Räumliche Biologie nicht mit einem neuen Companion Diagnostic verwechseln.":"Ne pas confondre biologie spatiale et nouveau companion diagnostic.","Stroma-/Immune-exclusion-Kontext":"Contexte stroma/immune-exclusion","PD-L1 bleibt deutlich exprimiert; der Befund allein erklärt die fehlende klinische Antwort nicht.":"PD-L1 reste nettement exprimé ; ce résultat seul n'explique pas l'absence de réponse clinique.","TMB erhöht. Potenziell vorhandene Neoantigene garantieren dennoch keine effektive T-Zell-Interaktion mit den Tumorzellen.":"TMB élevé. Des néoantigènes potentiels ne garantissent toutefois pas une interaction efficace des cellules T avec les cellules tumorales.","TIL-Verteilung":"Distribution des TIL","CD8-positive T-Zellen sind zahlreich, bleiben jedoch überwiegend stromal/peritumoral; intratumorale Penetration ist gering.":"Les cellules T CD8 positives sont nombreuses, mais restent principalement stromales/péritumorales ; la pénétration intratumorale est faible.","Stroma":"Stroma","Breites FAP/αSMA-positives fibroblastenreiches Stroma stützt ein immune-excluded Muster. Der Befund ist mechanistisch plausibel, aber kein allein validierter Therapie-Selektionsassay.":"Un large stroma riche en fibroblastes FAP/αSMA positifs soutient un profil immune-excluded. Le résultat est mécanistiquement plausible, mais n'est pas un assay autonome validé de sélection thérapeutique.","Klinischer Twist":"Twist clinique","Früher Progress trotz scheinbar günstiger Immunmarker.":"Progression précoce malgré des marqueurs immunitaires apparemment favorables.","Stark stromareicher Tumor mit räumlicher Trennung von CD8-Zellen und Tumornestern.":"Tumeur très riche en stroma avec séparation spatiale des cellules CD8 et des nids tumoraux.","PD-L1-Expression und erhöhte TMB können immunologische Potenziale anzeigen, garantieren aber keine effektive Antitumor-Immunität. Die Progressionsbiopsie zeigt ein klassisches immune-excluded Muster: T-Zellen sind vorhanden, werden jedoch durch das stromale Mikromilieu räumlich von Tumorzellen ferngehalten. Dieser Befund erklärt Resistenzbiologie, darf aber nicht als alleiniger validierter Companion Diagnostic für eine konkrete Folgetherapie überinterpretiert werden.":"L'expression de PD-L1 et un TMB élevé peuvent indiquer un potentiel immunologique, mais ne garantissent pas une immunité antitumorale efficace. La biopsie de progression montre un profil classique immune-excluded : les cellules T sont présentes, mais le microenvironnement stromal les maintient spatialement à distance des cellules tumorales. Cela explique la biologie de la résistance, mais ne doit pas être surinterprété comme un companion diagnostic autonome validé pour un traitement ultérieur précis.","Teilbefund: Gute Biomarkerwerte ohne räumliche TIL-Analyse erklären die tatsächliche Immunfunktion nur unvollständig.":"Résultat partiel : des valeurs de biomarqueurs favorables sans analyse spatiale des TIL décrivent incomplètement la fonction immunitaire réelle.","TMB/PD-L1 als Potenzialmarker von funktioneller T-Zell-Tumor-Interaktion trennen":"Distinguer TMB/PD-L1 comme marqueurs de potentiel de l'interaction fonctionnelle cellule T–tumeur","Immune exclusion über räumliche CD8-Verteilung erkennen":"Reconnaître l'immune exclusion par la distribution spatiale de CD8","CAF-/Stroma-Barriere biologisch erklären":"Expliquer biologiquement la barrière CAF/stromale","TME-IHC nicht zum nicht validierten Therapieausschlusstest machen":"Ne pas transformer l'IHC du TME en test non validé d'exclusion thérapeutique","Falschaussage: hohe TMB + PD-L1 garantieren Checkpoint-Ansprechen":"Affirmation erronée : TMB élevé + PD-L1 garantissent une réponse au checkpoint","Optimale Lösung: PD-L1/TMB nicht als Garantie interpretieren; die räumliche TIL-Verteilung zeigt, dass Immunzellen vorhanden, aber funktionell vom Tumor ausgeschlossen sind. Mechanistisch stark, prädiktiv aber nicht als alleiniger Routinetest validiert.":"Solution optimale : ne pas interpréter PD-L1/TMB comme une garantie ; la distribution spatiale des TIL montre que les cellules immunitaires sont présentes mais fonctionnellement exclues de la tumeur. Mécanistiquement fort, mais non validé comme test prédictif de routine autonome.","CAF":"CAF","Urothelkarzinom":"Carcinome urothélial","Viele T-Zellen – aber auf der falschen Seite der Stromabarriere":"De nombreuses cellules T — mais du mauvais côté de la barrière stromale","Molekularpathologie / Immunonkologie / MTB":"Pathologie moléculaire / Immuno-oncologie / MTB","PD-L1/TMB als Potenzialmarker von funktioneller Immunantwort unterscheiden.":"Distinguer PD-L1/TMB comme marqueurs de potentiel de la réponse immunitaire fonctionnelle.","Immune-excluded Muster anhand räumlicher TIL-Verteilung erkennen.":"Reconnaître un profil immune-excluded à partir de la distribution spatiale des TIL.","CAF-/Stromabarriere als Resistenzmechanismus erklären.":"Expliquer la barrière CAF/stromale comme mécanisme de résistance.","TME-IHC als mechanistischen und nicht automatisch validierten Selektionsmarker einordnen.":"Considérer l'IHC du TME comme mécanistique, et non automatiquement comme marqueur validé de sélection.","Klinische Nonresponse trotz günstiger Einzelmarker biologisch plausibel erklären.":"Expliquer biologiquement la non-réponse clinique malgré des marqueurs individuels favorables.","PD-L1 ist hoch, TMB ist erhöht – und der Tumor wächst unter Checkpoint-Inhibition trotzdem weiter. In der Progressionsbiopsie sind sogar viele CD8-T-Zellen zu sehen. Das Problem: Sie stehen fast alle draußen im Stroma.":"PD-L1 est élevé, le TMB est augmenté — et pourtant la tumeur continue de progresser sous inhibition de checkpoint. La biopsie de progression montre même de nombreuses cellules T CD8. Le problème : presque toutes restent à l'extérieur, dans le stroma.","68-jähriger Patient mit metastasiertem Urothelkarzinom und frühem Progress unter ICI trotz scheinbar günstiger PD-L1-/TMB-Konstellation. Die Progressionsbiopsie zeigt, dass nicht die Zahl allein, sondern die räumliche Position der Immunzellen entscheidend ist.":"Homme de 68 ans avec carcinome urothélial métastatique et progression précoce sous ICI malgré un profil PD-L1/TMB apparemment favorable. La biopsie de progression montre que non seulement le nombre, mais aussi la position spatiale des cellules immunitaires est déterminante.","Potenzial":"Potentiel","PD-L1 hoch, TMB erhöht.":"PD-L1 élevé, TMB augmenté.","Diese Marker können Immunogenität anzeigen, garantieren aber keine effektive Antwort.":"Ces marqueurs peuvent indiquer une immunogénicité, mais ne garantissent pas une réponse efficace.","Raum":"Espace","CD8-Zellen liegen vor allem stromal/peritumoral.":"Les cellules CD8 se situent principalement dans les zones stromales/péritumorales.","Immune exclusion ist ein räumliches Phänomen.":"L'immune exclusion est un phénomène spatial.","Barriere":"Barrière","FAP/αSMA-reiches Stroma.":"Stroma riche en FAP/αSMA.","CAF/Matrix können physische und signalbiologische Barrieren bilden.":"Les CAF/la matrice peuvent former des barrières physiques et de signalisation.","deutlich exprimiert":"Nettement exprimé","erhöht":"Augmenté","früher Progress unter Checkpoint-Inhibition":"Progression précoce sous inhibition de checkpoint","Progressionsbiopsie ermöglicht räumliche TIL-/Stroma-Bewertung.":"La biopsie de progression permet une évaluation spatiale TIL/stroma.","TME-Marker sind keine validierte alleinige Folgetherapie-Selektion.":"Les marqueurs du TME ne sont pas validés comme tests autonomes de sélection du traitement ultérieur.","Mechanistische Erklärung darf nicht in Pseudopräzision kippen.":"L'explication mécanistique ne doit pas devenir une pseudo-précision.","Was ist die wichtigste Erklärung für PD-L1/TMB ohne Response?":"Quelle est l'explication la plus importante d'un PD-L1/TMB favorable sans réponse ?","Marker zeigen Potenzial, aber nicht zwingend erfolgreiche T-Zell-Penetration und Funktion im Tumornest.":"Les marqueurs indiquent un potentiel, mais pas nécessairement une pénétration et une fonction efficaces des cellules T dans les nids tumoraux.","PD-L1 und TMB müssen technisch falsch sein.":"PD-L1 et TMB doivent être techniquement erronés.","So eine Konstellation ist unmöglich.":"Une telle constellation est impossible.","Hohe TMB beweist MSI-H.":"Un TMB élevé prouve MSI-H.","Biomarker und Funktion sind unterschiedliche Ebenen.":"Biomarqueurs et fonction sont des niveaux différents.","Welcher Befund definiert immune exclusion am besten?":"Quel résultat définit le mieux l'immune exclusion ?","Viele T-Zellen im Stroma, wenige innerhalb der Tumorzellnester.":"De nombreuses cellules T dans le stroma, peu dans les nids tumoraux.","Gar keine Immunzellen im gesamten Präparat.":"Aucune cellule immunitaire dans l'ensemble du prélèvement.","Dichtes intraepitheliales CD8-Infiltrat.":"Infiltrat CD8 intraépithélial dense.","PD-L1 hoch.":"PD-L1 élevé.","Räumliche Verteilung ist zentral.":"La distribution spatiale est centrale.","Wie darf FAP/αSMA/CD8-IHC genutzt werden?":"Comment l'IHC FAP/αSMA/CD8 peut-elle être utilisée ?","Als mechanistische Unterstützung eines stromal-excluded Musters, nicht als alleiniger zugelassener Companion Diagnostic.":"Comme soutien mécanistique d'un profil stromal-excluded, et non comme companion diagnostic approuvé autonome.","Als absolute Kontraindikation gegen jede ICI.":"Comme contre-indication absolue à tout ICI.","Als Beweis für eine Standard-CAF-Therapie.":"Comme preuve en faveur d'un traitement CAF standard.","Gar nicht interpretieren.":"Ne pas l'interpréter du tout.","Mechanistisch stark, klinisch nicht allein selektiv validiert.":"Mécanistiquement fort, mais non validé cliniquement comme sélecteur autonome.","Was ist die beste MTB-Kommunikation?":"Quelle est la meilleure communication en MTB ?","Günstige Einzelmarker anerkennen, reale Nonresponse und spatial TME integrieren, experimentelle TME-Strategien als Studienoption kennzeichnen.":"Reconnaître les marqueurs individuels favorables, intégrer la non-réponse réelle et le TME spatial, et présenter les stratégies expérimentales ciblant le TME comme des options d'étude.","PD-L1 so oft wiederholen, bis ein höherer Wert entsteht.":"Répéter PD-L1 jusqu'à obtenir une valeur plus élevée.","TMB/PD-L1 als nutzlos erklären.":"Déclarer TMB/PD-L1 inutiles.","CAF-Targeting als Standard empfehlen.":"Recommander le ciblage CAF comme standard.","Evidenzhierarchie + Biologie.":"Hiérarchie des preuves + biologie.","Erklären Sie die primäre Resistenz trotz PD-L1/TMB und formulieren Sie, welche Aussage die Progressionsbiopsie liefert – und welche Therapieentscheidung sie gerade nicht allein rechtfertigt.":"Expliquez la résistance primaire malgré PD-L1/TMB et précisez ce que montre la biopsie de progression — et quelle décision thérapeutique elle ne justifie justement pas à elle seule.","PD-L1/TMB als Potenzial, nicht Garantie einordnen.":"Considérer PD-L1/TMB comme un potentiel, non une garantie.","CD8-Verteilung räumlich beschreiben.":"Décrire spatialement la distribution de CD8.","Immune exclusion erkennen.":"Reconnaître l'immune exclusion.","CAF-/Stromabarriere mechanistisch erklären.":"Expliquer mécanistiquement la barrière CAF/stromale.","TME-IHC nicht als alleinigen Companion Diagnostic verwenden.":"Ne pas utiliser l'IHC du TME comme companion diagnostic autonome.","Studienoptionen klar als experimentell markieren.":"Identifier clairement les options d'étude comme expérimentales.","Wenn keine Progressionsbiopsie verfügbar ist, morphologische/radiologische Daten nutzen und TME-Hypothese als Hypothese belassen.":"En l'absence de biopsie de progression, utiliser les données morphologiques/radiologiques et conserver l'hypothèse TME comme hypothèse.","TME-gerichtete Studien bei passender Verfügbarkeit diskutieren.":"Discuter des études ciblant le TME si elles sont disponibles de manière appropriée.","PD-L1/TMB garantieren Response":"PD-L1/TMB garantissent la réponse","Funktionelle Immunantwort braucht mehr als Potenzialmarker.":"Une réponse immunitaire fonctionnelle nécessite plus que des marqueurs de potentiel.","TME-IHC = Therapieausschluss":"IHC TME = exclusion thérapeutique","Nicht als alleiniger validierter Selektionsassay etabliert.":"Non établi comme assay de sélection validé autonome.","CAF-Targeting Standard":"Ciblage CAF standard","Mechanismus wird zu Routineempfehlung überhöht.":"Un mécanisme est abusivement élevé au rang de recommandation de routine.","Die T-Zellen sind da – und kommen trotzdem nicht an den Tumor":"Les cellules T sont là — et pourtant n'atteignent pas la tumeur","Die Progressionsbiopsie zeigt viele CD8-Zellen, aber fast ausschließlich in FAP/αSMA-reichem Stroma. Der scheinbare Widerspruch zwischen 'immunogen' und 'resistent' löst sich räumlich auf.":"La biopsie de progression montre de nombreuses cellules CD8, mais presque exclusivement dans un stroma riche en FAP/αSMA. La contradiction apparente entre « immunogène » et « résistant » se résout spatialement.","Der Fall macht aus TME ein sichtbares diagnostisches Konzept statt einer abstrakten Signalwegfolie.":"Le cas transforme le TME en concept diagnostique visible plutôt qu'en diapositive abstraite de pathway.","Spatial biology integriert":"Biologie spatiale intégrée","PD-L1/TMB günstig, aber CD8 stromal ausgeschlossen; TME erklärt Resistenz, ohne einen neuen Companion Diagnostic zu behaupten.":"PD-L1/TMB favorables, mais cellules CD8 exclues par le stroma ; le TME explique la résistance sans revendiquer un nouveau companion diagnostic.","Biologie und Evidenz sauber getrennt.":"Biologie et preuves clairement séparées.","Stroma erkannt, Marker verworfen":"Stroma reconnu, marqueurs rejetés","Immune exclusion korrekt, aber PD-L1/TMB pauschal als wertlos dargestellt.":"L'immune exclusion est correctement reconnue, mais PD-L1/TMB sont déclarés globalement sans valeur.","Zu absolut.":"Trop absolu.","Biomarker-Garantie":"Garantie par biomarqueur","Früher Progress wird ignoriert, weil PD-L1/TMB 'gut' sind.":"La progression précoce est ignorée parce que PD-L1/TMB sont « bons ».","Funktionelle Ebene verpasst.":"La dimension fonctionnelle est manquée.","Studie mit TME-gerichteter Kombination verfügbar":"Étude avec combinaison ciblant le TME disponible","Als experimentelle Option diskutieren.":"Discuter comme option expérimentale.","Mechanistische Hypothese wird im passenden Evidenzrahmen genutzt.":"L'hypothèse mécanistique est utilisée dans le cadre de preuve approprié.","Keine Studie":"Pas d'étude","Standardtherapie nach etablierter Entitätslogik.":"Traitement standard selon la logique établie propre à l'entité.","TME-Befund bleibt erklärend, nicht pseudoprädiktiv.":"Le résultat TME reste explicatif, non pseudo-prédictif.","Biomarker können Potenzial anzeigen, aber keine Antwort garantieren.":"Les biomarqueurs peuvent indiquer un potentiel, mais ne peuvent garantir la réponse.","Immune exclusion ist räumlich: Immunzellen vorhanden, aber vom Tumornest ferngehalten.":"L'immune exclusion est spatiale : les cellules immunitaires sont présentes mais maintenues à distance des nids tumoraux.","CAF-/Matrix-Komponenten können physische und signalbiologische Barrieren bilden.":"Les composants CAF/matrice peuvent former des barrières physiques et de signalisation.","TME-IHC ist mechanistisch wertvoll, aber kein automatisch validierter Companion Diagnostic.":"L'IHC du TME est précieuse sur le plan mécanistique, mais n'est pas automatiquement un companion diagnostic validé.","Progressionsmaterial kann Resistenzbiologie sichtbar machen.":"Le matériel de progression peut révéler la biologie de la résistance.","Trotz PD-L1 und erhöhter TMB zeigt die Progressionsbiopsie ein immune-excluded Muster mit CD8-Zellen im stromalen Kompartiment. Das erklärt die fehlende effektive Tumorinteraktion, ist aber kein alleiniger routinemäßiger Selektionsmarker für eine konkrete Folgetherapie.":"Malgré PD-L1 et un TMB élevé, la biopsie de progression montre un profil immune-excluded avec des cellules CD8 dans le compartiment stromal. Cela explique l'absence d'interaction tumorale efficace, mais ne constitue pas un marqueur de sélection de routine autonome pour un traitement ultérieur précis.","Marker vs Funktion":"Marqueurs vs fonction","spatial TILs":"TIL spatiaux","Stromabarriere":"Barrière stromale","Was ist der Unterschied zwischen immune-desert und immune-excluded?":"Quelle est la différence entre immune-desert et immune-excluded ?","Welche Rolle kann TGF-β/CAF-Biologie spielen?":"Quel rôle la biologie TGF-β/CAF peut-elle jouer ?","Wie könnte Digitalpathologie spatial TILs künftig standardisieren?":"Comment la pathologie numérique pourrait-elle standardiser les TIL spatiaux à l'avenir ?","viele CD8-Zellen, aber außerhalb der Tumornester":"De nombreuses cellules CD8, mais en dehors des nids tumoraux","Räumliche Immunbiologie kann Einzelmarker widersprechen":"La biologie immunitaire spatiale peut contredire des marqueurs individuels","PD-L1/TMB → Nonresponse → spatial biopsy → immune exclusion":"PD-L1/TMB → non-réponse → biopsie spatiale → immune exclusion","pT1-CRC nach Endoskopie: Tumor budding als sichtbarer Invasions-Hallmark":"CRC pT1 après endoscopie : tumor budding comme hallmark visible d'invasion","EMT-/Invasionsfront-Fall mit Metas…":"Cas EMT/front d'invasion avec metas…","Gastroenterologie / Viszeralchirurgie / Pathologieboard":"Gastroentérologie / Chirurgie viscérale / Board de pathologie","56-jähriger Patient nach endoskopischer en-bloc-Resektion eines pT1-Sigmakarzinoms. Die Frage ist, ob die lokale Therapie ausreicht oder wegen Lymphknotenrisiko eine onkologische Nachresektion diskutiert werden muss.":"Homme de 56 ans après résection endoscopique en bloc d'un carcinome sigmoïdien pT1. La question est de savoir si le traitement local suffit ou si une résection oncologique complémentaire doit être discutée en raison du risque ganglionnaire.","Welche morphologischen Merkmale an der Invasionsfront sind klinisch relevant – und welche Rolle spielt das EMT-Konzept dabei?":"Quelles caractéristiques morphologiques du front d'invasion sont cliniquement pertinentes, et quel rôle joue le concept d'EMT ?","Entscheidung über weitere Operation im nächsten Board.":"Décision concernant une chirurgie supplémentaire lors du prochain board.","Endoskopie":"Endoscopie","20-mm-Läsion, vollständig en bloc reseziert.":"Lésion de 20 mm, complètement réséquée en bloc.","pT1-Adenokarzinom, Resektionsrand tumorfrei.":"Adénocarcinome pT1, marge de résection indemne de tumeur.","Konflikt":"Conflit","Ein 'R0' klingt beruhigend, aber R0 beantwortet das Risiko okkulter Lymphknotenmetastasen nicht allein.":"Un « R0 » paraît rassurant, mais R0 à lui seul ne répond pas au risque de métastases ganglionnaires occultes.","Ein experimentelles EMT-IHC-Panel wird höher gewichtet als validierte histopathologische Risikofaktoren.":"Un panel IHC EMT expérimental est davantage pondéré que des facteurs de risque histopathologiques validés.","Histologie + Invasionsfront":"Histologie + front d'invasion","Submukosale Invasion; an der tiefsten Front zahlreiche Einzelzellen und kleine Tumorzellcluster entsprechend hochgradigem Tumor budding.":"Invasion sous-muqueuse ; au front le plus profond, nombreuses cellules isolées et petits amas tumoraux correspondant à un tumor budding de haut grade.","Weitere Risiken":"Risques supplémentaires","Fokale lymphovaskuläre Invasion; keine schlechte Differenzierung.":"Invasion lymphovasculaire focale ; pas de mauvaise différenciation.","EMT-Kontext":"Contexte EMT","An Buds fokal reduzierte membranäre E-Cadherin-Expression und veränderte β-Catenin-Lokalisation möglich – biologisch passend zu partieller EMT.":"Au niveau des buds, une diminution focale de l'expression membranaire d'E-cadhérine et une localisation modifiée de β-caténine peuvent être observées — biologiquement compatibles avec une EMT partielle.","Morphologischer Risikomarker versus mechanistischer Zusatzbefund.":"Marqueur morphologique de risque versus résultat mécanistique supplémentaire.","Komplettes endoskopisches Resektat, gut orientiert.":"Pièce complète de résection endoscopique, bien orientée.","Primärentscheidung":"Décision principale","HE-basierte Bewertung von Budding, LVI, Differenzierung, Invasionstiefe und Resektionsrand.":"Évaluation sur H&E du budding, de la LVI, de la différenciation, de la profondeur d'invasion et de la marge de résection.","Zusatz-IHC":"IHC supplémentaire","EMT-Panel kann den Hallmark illustrieren, ist aber nicht erforderlich, um den klinischen Hochrisikobefund zu erkennen.":"Un panel EMT peut illustrer le hallmark, mais n'est pas nécessaire pour reconnaître le résultat clinique à haut risque.","Mechanismusmarker dürfen die standardisierte Morphologie nicht verdrängen.":"Les marqueurs mécanistiques ne doivent pas supplanter la morphologie standardisée.","Histologische Invasionsfront / Risikofaktoren":"Front d'invasion histologique / facteurs de risque","HE / Invasionsfront":"H&E / front d'invasion","Hochgradiges Tumor budding an der tiefen Invasionsfront plus fokale lymphovaskuläre Invasion. Diese histopathologischen Hochrisikofaktoren sind für die Entscheidung nach endoskopischer pT1-Resektion klinisch relevant.":"Tumor budding de haut grade au front d'invasion profond avec invasion lymphovasculaire focale. Ces facteurs histopathologiques à haut risque sont cliniquement pertinents pour la décision après résection endoscopique pT1.","EMT-IHC":"IHC EMT","Buds zeigen fokal reduzierte E-Cadherin-Membranfärbung, Vimentin-Zunahme und veränderte β-Catenin-Lokalisation – mechanistisch vereinbar mit partieller EMT, aber kein eigenständiger validierter Operationsindikator.":"Les buds montrent une diminution focale du marquage membranaire d'E-cadhérine, une augmentation de la vimentine et une localisation modifiée de β-caténine — mécanistiquement compatibles avec une EMT partielle, mais sans constituer une indication chirurgicale indépendante validée.","Breite Tumorgenetik liefert für die unmittelbare pT1-Risikostratifikation keinen Ersatz für die relevanten histopathologischen Invasionsmerkmale.":"Une génétique tumorale large ne remplace pas les caractéristiques histopathologiques d'invasion pertinentes pour la stratification immédiate du risque pT1.","Resektion":"Résection","Endoskopisch R0.":"R0 endoscopique.","Invasionsfront":"Front d'invasion","Hochgradiges Tumor budding und fokale Lymphgefäßinvasion.":"Tumor budding de haut grade et invasion lymphatique focale.","Der Fall verbindet Morphologie und Hallmark-Biologie: Tumor budding an der Invasionsfront ist ein sichtbares Korrelat invasiver/plastischer Tumorzellzustände und bei pT1-CRC ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen. EMT-IHC kann die Biologie illustrieren, entscheidet aber nicht über die weitere Operation. Die klinische Konsequenz entsteht aus standardisierten Hochrisikofaktoren wie Budding, LVI, Differenzierung, Tiefe und Resektionsstatus.":"Le cas relie morphologie et biologie des hallmarks : le tumor budding au front d'invasion est un corrélat visible d'états tumoraux invasifs/plastiques et un facteur de risque histopathologique établi de métastases ganglionnaires dans le CRC pT1. L'IHC EMT peut illustrer la biologie, mais ne décide pas d'une chirurgie complémentaire. La conséquence clinique découle de facteurs standardisés à haut risque tels que budding, LVI, différenciation, profondeur et statut de résection.","Teilbefund: EMT ist biologisch plausibel, aber die klinische Risikoeinschätzung muss an validierten histopathologischen Merkmalen hängen.":"Résultat partiel : l'EMT est biologiquement plausible, mais l'évaluation du risque clinique doit reposer sur des caractéristiques histopathologiques validées.","Tumor budding als klinisch relevanten Invasionsfront-Befund erkennen":"Reconnaître le tumor budding comme résultat cliniquement pertinent du front d'invasion","R0 nicht mit niedrigem Lymphknotenrisiko gleichsetzen":"Ne pas assimiler R0 à un faible risque ganglionnaire","EMT als mechanistische Erklärung, nicht als eigenständigen Routine-Selektionsassay einordnen":"Considérer l'EMT comme une explication mécanistique, non comme assay de sélection de routine autonome","HE-basierte standardisierte Risikofaktoren priorisieren":"Prioriser les facteurs de risque standardisés fondés sur H&E","Falschaussage: ein positives EMT-IHC-Panel ist die Operationsindikation":"Affirmation erronée : un panel IHC EMT positif constitue l'indication chirurgicale","Optimale Lösung: Morphologie zuerst. High-grade budding und LVI machen den pT1-Fall trotz R0 klinisch risikorelevant; EMT-IHC erklärt das Hallmark, ersetzt aber nicht die standardisierte histopathologische Entscheidung.":"Solution optimale : la morphologie d'abord. Un budding de haut grade et une LVI rendent le cas pT1 cliniquement à haut risque malgré R0 ; l'IHC EMT explique le hallmark, mais ne remplace pas la décision histopathologique standardisée.","pT1 CRC":"CRC pT1","Tumor budding":"Tumor budding","Invasion":"Invasion","EMT":"EMT","Lymphovascular invasion":"Invasion lymphovasculaire","Hallmarks":"Hallmarks","Tumor budding: Hallmark im HE statt EMT-Overtesting":"Tumor budding : un hallmark visible en H&E plutôt qu'un surtesting EMT","GI-Pathologie / Molekularpathologie / MTB":"Pathologie GI / Pathologie moléculaire / MTB","Tumor budding als morphologisches Korrelat invasiver/plastischer Tumorzellzustände erkennen.":"Reconnaître le tumor budding comme corrélat morphologique d'états tumoraux invasifs/plastiques.","Bei pT1-CRC klinisch relevante histopathologische Hochrisikofaktoren priorisieren.":"Prioriser les facteurs histopathologiques à haut risque cliniquement pertinents dans le CRC pT1.","R0-Resektion von Lymphknotenrisiko unterscheiden.":"Distinguer résection R0 et risque ganglionnaire.","EMT-IHC als mechanistische Illustration und nicht als eigenständigen Operationsindikator einordnen.":"Considérer l'IHC EMT comme une illustration mécanistique, non comme une indication chirurgicale autonome.","Morphologie direkt mit Hallmark-Biologie und klinischer Konsequenz verbinden.":"Relier directement morphologie, biologie des hallmarks et conséquence clinique.","Der Polyp ist komplett raus, der Rand ist frei – eigentlich klingt alles gut. An der tiefen Invasionsfront stehen jedoch zahlreiche einzelne Tumorzellen und kleine Cluster: High-grade tumor budding. Genau dort wird ein abstrakter Hallmark plötzlich klinisch sichtbar.":"Le polype est entièrement retiré et la marge est saine — tout paraît favorable. Pourtant, au front d'invasion profond, on observe de nombreuses cellules tumorales isolées et de petits amas : tumor budding de haut grade. C'est précisément là qu'un hallmark abstrait devient soudain cliniquement visible.","56-jähriger Patient nach endoskopischer R0-Resektion eines pT1-Sigmakarzinoms. Das Board muss entscheiden, ob wegen histopathologischer Hochrisikofaktoren eine onkologische Nachresektion diskutiert werden sollte. EMT ist die biologische Erklärung, aber nicht der primäre klinische Test.":"Homme de 56 ans après résection endoscopique R0 d'un carcinome sigmoïdien pT1. Le board doit décider si une résection oncologique complémentaire doit être discutée en raison de facteurs histopathologiques à haut risque. L'EMT est l'explication biologique, mais pas le test clinique principal.","R0 ist nicht alles":"R0 ne fait pas tout","Lokale Exzision ist vollständig.":"L'exérèse locale est complète.","Okkultes Lymphknotenrisiko bleibt eine andere Frage.":"Le risque ganglionnaire occulte reste une question distincte.","Budding ist sichtbar":"Le budding est visible","Einzelzellen/kleine Cluster an der Invasionsfront.":"Cellules isolées/petits amas au front d'invasion.","Morphologie kann funktionelle Tumorbiologie verdichten.":"La morphologie peut condenser la biologie tumorale fonctionnelle.","EMT erklärt, entscheidet aber nicht allein":"L'EMT explique, mais ne décide pas seule","E-Cadherin/Vimentin/β-Catenin können partielle EMT illustrieren.":"E-cadhérine/vimentine/β-caténine peuvent illustrer une EMT partielle.","Standardisierte Histopathologie trägt die klinische Entscheidung.":"L'histopathologie standardisée porte la décision clinique.","Resektionsstatus":"Statut de résection","R0":"R0","high-grade tumor budding + fokale LVI":"Tumor budding de haut grade + LVI focale","Differenzierung":"Différenciation","nicht schlecht differenziert":"Non peu différencié","Komplettes gut orientiertes endoskopisches Resektat.":"Pièce complète de résection endoscopique, bien orientée.","HE-Reevaluation ist der wichtigste 'Test'.":"La réévaluation H&E est le « test » le plus important.","EMT-IHC verbraucht Schnitte ohne zwingenden Zusatznutzen für die Operationsentscheidung.":"L'IHC EMT consomme des coupes sans bénéfice supplémentaire indispensable pour la décision chirurgicale.","Welche Aussage zu Tumor budding im pT1-CRC ist am treffendsten?":"Quelle affirmation concernant le tumor budding dans le CRC pT1 est la plus juste ?","Es ist ein etablierter histopathologischer Risikofaktor für Lymphknotenmetastasen und muss mit anderen Hochrisikofaktoren integriert werden.":"C'est un facteur de risque histopathologique établi de métastases ganglionnaires et il doit être intégré aux autres facteurs à haut risque.","Es ist nur ein interessantes Morphologiedetail.":"Ce n'est qu'un détail morphologique intéressant.","Es kann nur durch NGS diagnostiziert werden.":"Il ne peut être diagnostiqué que par NGS.","Es ist synonym mit positivem Resektionsrand.":"Il est synonyme de marge de résection positive.","Budding hat klinische Risikobedeutung.":"Le budding a une pertinence clinique en termes de risque.","Was bedeutet R0 hier?":"Que signifie R0 ici ?","Die lokale Resektion ist vollständig; das nodale Metastasierungsrisiko wird dadurch nicht automatisch null.":"La résection locale est complète ; le risque de métastases ganglionnaires n'est pas automatiquement nul.","Heilung ist sicher.":"La guérison est certaine.","Lymphknotenmetastasen sind ausgeschlossen.":"Les métastases ganglionnaires sont exclues.","EMT ist ausgeschlossen.":"L'EMT est exclue.","Lokaler Randstatus und biologisches Metastasierungsrisiko sind getrennt.":"Le statut de la marge locale et le risque biologique de métastase sont distincts.","Welche Rolle hat das EMT-IHC-Panel?":"Quel rôle joue le panel IHC EMT ?","Es kann partielle EMT mechanistisch illustrieren, ist aber kein eigenständiger validierter Operationsindikator.":"Il peut illustrer mécanistiquement une EMT partielle, mais ne constitue pas une indication chirurgicale indépendante validée.","Es ist zwingend vor jeder Nachresektion erforderlich.":"Il est obligatoire avant toute résection complémentaire.","Es ersetzt Tumor budding.":"Il remplace le tumor budding.","Es liefert unmittelbar eine zugelassene Targettherapie.":"Il fournit directement un traitement ciblé approuvé.","Mechanismusmarker ≠ klinischer Standard-Risikomarker.":"Marqueur mécanistique ≠ marqueur clinique standard de risque.","Welche Befunde tragen die klinische Entscheidung primär?":"Quels résultats portent principalement la décision clinique ?","Budding, LVI, Differenzierung, Invasionstiefe und Resektionsstatus im standardisierten histopathologischen Kontext.":"Budding, LVI, différenciation, profondeur d'invasion et statut de résection dans le contexte histopathologique standardisé.","Nur E-Cadherin/Vimentin.":"Uniquement E-cadhérine/vimentine.","Breites Pan-Cancer-NGS.":"NGS pan-cancer large.","PD-L1.":"PD-L1.","Morphologische Risikofaktoren sind hier zentral.":"Les facteurs morphologiques de risque sont centraux ici.","Leiten Sie vom HE-Befund an der Invasionsfront über die Hallmark-Biologie zur klinischen Konsequenz nach endoskopischer pT1-Resektion ab.":"Déduisez la conséquence clinique après résection endoscopique pT1 à partir du résultat H&E au front d'invasion, via la biologie des hallmarks.","R0 als lokalen Resektionsstatus anerkennen.":"Reconnaître R0 comme statut local de résection.","High-grade tumor budding erkennen und standardisiert bewerten.":"Reconnaître et évaluer de façon standardisée un tumor budding de haut grade.","LVI als zusätzlichen Hochrisikofaktor integrieren.":"Intégrer la LVI comme facteur supplémentaire à haut risque.","EMT als mechanistische Erklärung formulieren.":"Formuler l'EMT comme explication mécanistique.","EMT-IHC nicht zur Operationsvoraussetzung machen.":"Ne pas faire de l'IHC EMT un prérequis à la chirurgie.","Onkologische Nachresektion wegen kombinierter Hochrisikofaktoren im Board diskutieren.":"Discuter en board d'une résection oncologique complémentaire en raison de facteurs à haut risque combinés.","Auf EMT-IHC vollständig verzichten und die Hallmark-Biologie rein morphologisch erklären – klinisch absolut vertretbar.":"Omettre complètement l'IHC EMT et expliquer la biologie du hallmark uniquement par la morphologie — cliniquement tout à fait acceptable.","Bei Grenzfällen zusätzliche pathologische Zweitbegutachtung statt breitem Molekularpanel.":"Dans les cas limites, utiliser une seconde relecture anatomopathologique plutôt qu'un large panel moléculaire.","R0 = kein Risiko":"R0 = aucun risque","Lymphknotenrisiko ist nicht identisch mit lokalem Randstatus.":"Le risque ganglionnaire n'est pas identique au statut de la marge locale.","EMT-IHC entscheidet":"L'IHC EMT décide","Mechanistische Marker ersetzen keine validierte pT1-Risikostratifikation.":"Les marqueurs mécanistiques ne remplacent pas la stratification validée du risque pT1.","Budding nur Forschung":"Budding uniquement pour la recherche","Budding besitzt etablierte prognostische/Risikobedeutung.":"Le budding a une pertinence pronostique/de risque établie.","Der wichtigste Hallmark-Test ist bereits auf dem HE":"Le test de hallmark le plus important est déjà sur la lame H&E","Das optionale EMT-Panel zeigt erwartbare partielle EMT-Zeichen, ändert aber die klinische Entscheidung nicht. High-grade budding und LVI waren bereits im HE sichtbar und tragen die Konsequenz.":"Le panel EMT optionnel montre des signes attendus d'EMT partielle, mais ne modifie pas la décision clinique. Le budding de haut grade et la LVI étaient déjà visibles en H&E et portent la conséquence.","Der Fall verbindet Grundlagenbiologie mit Pathologieroutine, ohne Molekulardiagnostik künstlich aufzublähen.":"Le cas relie biologie fondamentale et pathologie de routine sans gonfler artificiellement le diagnostic moléculaire.","Morphologie → Hallmark → Konsequenz":"Morphologie → hallmark → conséquence","R0-pT1-CRC, aber high-grade budding + LVI → relevantes nodales Risiko; EMT mechanistisch, nicht als Pflichtassay.":"CRC pT1 R0, mais budding de haut grade + LVI → risque ganglionnaire pertinent ; EMT mécanistique, pas assay obligatoire.","Genau die gewünschte Integrationsleistung.":"Exactement l'intégration souhaitée.","EMT verstanden, Risiko unscharf":"EMT comprise, risque imprécis","Biologie gut erklärt, aber klinisch relevante Histofaktoren nicht priorisiert.":"La biologie est bien expliquée, mais les facteurs histologiques cliniquement pertinents ne sont pas priorisés.","Zu grundlagenlastig.":"Trop centré sur la biologie fondamentale.","R0 = erledigt":"R0 = terminé","Budding/LVI werden trotz freiem Rand ignoriert.":"Budding/LVI sont ignorés malgré une marge saine.","Klinische Konsequenz verpasst.":"La conséquence clinique est manquée.","Mehrere histologische Hochrisikofaktoren":"Multiples facteurs histologiques à haut risque","Onkologische Nachresektion mit Lymphknotenbewertung im interdisziplinären Kontext diskutieren.":"Discuter une résection oncologique complémentaire avec évaluation ganglionnaire dans un contexte multidisciplinaire.","Nodales Risiko wird adressiert.":"Le risque ganglionnaire est pris en compte.","Keine Hochrisikofaktoren":"Pas de facteurs à haut risque","Lokale Strategie nach geltenden Kriterien erwägen.":"Envisager une stratégie locale selon les critères applicables.","Übertherapie vermeiden.":"Éviter le surtraitement.","Tumor budding ist ein morphologisches Korrelat von Invasion/plastischen Zellzuständen.":"Le tumor budding est un corrélat morphologique de l'invasion/des états cellulaires plastiques.","Bei pT1-CRC ist budding ein klinisch relevanter Risikofaktor für Lymphknotenmetastasen.":"Dans le CRC pT1, le budding est un facteur de risque cliniquement pertinent de métastases ganglionnaires.","R0 beantwortet die lokale Resektion, nicht automatisch das nodale Risiko.":"R0 répond au statut de résection locale, pas automatiquement au risque ganglionnaire.","EMT-IHC kann Mechanismus illustrieren, ist aber kein notwendiger Operationsindikator.":"L'IHC EMT peut illustrer le mécanisme, mais n'est pas une indication chirurgicale nécessaire.","HE kann funktionelle Tumorbiologie als kumulative Morphologie sichtbar machen.":"H&E peut rendre visible la biologie tumorale fonctionnelle sous forme de morphologie cumulative.","Trotz R0-Resektion zeigen high-grade tumor budding und LVI ein relevantes Lymphknotenrisiko. Tumor budding verbindet die Invasionsfront direkt mit Hallmark-Biologie; EMT-IHC ist optional erklärend, nicht entscheidungsdefinierend.":"Malgré une résection R0, un tumor budding de haut grade et une LVI indiquent un risque ganglionnaire pertinent. Le tumor budding relie directement le front d'invasion à la biologie des hallmarks ; l'IHC EMT est optionnelle et explicative, non décisionnelle.","R0 vs nodales Risiko":"R0 vs risque ganglionnaire","EMT als Mechanismus":"EMT comme mécanisme","Morphologie priorisiert":"Morphologie priorisée","Welche HE-Merkmale sind funktionelle 'Fingerabdrücke' von Hallmarks?":"Quelles caractéristiques H&E sont des « empreintes » fonctionnelles des hallmarks ?","Warum ist partielle EMT biologisch plausibler als ein binärer EMT-Schalter?":"Pourquoi une EMT partielle est-elle biologiquement plus plausible qu'un interrupteur EMT binaire ?","Wo hilft Molekulardiagnostik – und wo macht sie einen guten HE-Befund nur komplizierter?":"Où le diagnostic moléculaire aide-t-il, et où ne fait-il que compliquer un bon résultat H&E ?","high-grade budding trotz R0":"Budding de haut grade malgré R0","Morphologie kann Hallmarks klinisch relevant abbilden":"La morphologie peut représenter les hallmarks de manière cliniquement pertinente","R0 → Invasionsfront → budding/LVI → Hallmark → klinische Konsequenz":"R0 → front d'invasion → budding/LVI → hallmark → conséquence clinique","Coverage-Loch im EGFR-Exon 20: „negativ“ ist hier nicht negativ":"Lacune de couverture dans l’exon 20 d’EGFR : ici, « négatif » ne signifie pas négatif","Coverage-Loch in therapieentscheid…":"Lacune de couverture dans un exon déterminant pour le traitement…","58-jährige Nie-Raucherin mit metastasiertem pulmonalem Adenokarzinom. Das DNA-Panel wird als „kein therapierbarer Treiber nachweisbar“ zusammengefasst.":"Patiente de 58 ans, jamais fumeuse, atteinte d’un adénocarcinome pulmonaire métastatique. Le panel ADN est résumé par « aucun driver actionnable détecté ».","Darf der Fall als molekular negativ abgeschlossen werden, obwohl der Coverage-Report für EGFR-Exon 20 unterhalb des laborintern validierten Mindestkriteriums liegt?":"Peut-on conclure que le cas est moléculairement négatif alors que la couverture de l’exon 20 d’EGFR est inférieure au critère minimal validé en interne par le laboratoire ?","Die Erstlinienentscheidung soll in vier Tagen fallen.":"La décision thérapeutique de première ligne doit être prise dans quatre jours.","ECOG 1, Leber- und Knochenmetastasen; ausreichend Zeit für eine gezielte Nachklärung, aber nicht für beliebig viele Wiederholungen.":"ECOG 1, métastases hépatiques et osseuses ; le délai permet une clarification ciblée, mais pas des répétitions illimitées.","KRAS, BRAF, MET-Exon-14 und ERBB2 ohne pathogene Alteration; Fusionstestung separat vorgesehen.":"KRAS, BRAF, exon 14 de MET et ERBB2 sans altération pathogène ; l’analyse des fusions est prévue séparément.","QC-Hinweis":"Note de QC","Median-Coverage des Panels ca. 780×, EGFR-Exon 20 jedoch nur 24×; laborintern validiertes Mindestkriterium für einen negativen Call wird dort nicht erreicht.":"Couverture médiane du panel d’environ 780×, mais seulement 24× pour l’exon 20 d’EGFR ; le critère minimal validé en interne pour un call négatif n’y est pas atteint.","Ein global „guter“ Run wird mit vollständiger lokaler Aussagefähigkeit gleichgesetzt.":"Un run globalement « bon » est assimilé à une interprétabilité locale complète.","Adenokarzinom der Lunge, TTF1/Napsin A positiv.":"Adénocarcinome pulmonaire, TTF1/Napsin A positifs.","ca. 45 %.":"env. 45 %.","Ist das Exon tatsächlich wildtyp oder nur unzureichend untersucht?":"L’exon est-il réellement wild type ou simplement insuffisamment étudié ?","Hinweis":"Remarque","„Nicht nachgewiesen“ und „nicht ausreichend geprüft“ sind unterschiedliche Aussagen.":"« Non détecté » et « insuffisamment évalué » sont deux affirmations différentes.","FFPE-Lebermetastase, Restblock vorhanden.":"Métastase hépatique FFPE, bloc résiduel disponible.","Menge ausreichend; übrige Targets technisch unauffällig.":"Quantité suffisante ; les autres cibles sont techniquement sans particularité.","Coverage":"Couverture","isolierter Dropout in EGFR-Exon 20.":"dropout isolé dans l’exon 20 d’EGFR.","Ressourcen":"Ressources","Eine gezielte orthogonale Abklärung ist schneller und materialsparender als ein blindes komplettes Re-Panel.":"Une clarification orthogonale ciblée est plus rapide et épargne davantage de matériel qu’une répétition à l’aveugle de l’ensemble du panel.","Coverage-/QC-Review":"Revue couverture/QC","Nicht ausreichend abgedecktes Exon gezielt klären":"Clarification ciblée de l’exon insuffisamment couvert","Coverage-Review":"Revue de la couverture","Der Run ist global valide, aber EGFR-Exon 20 unterschreitet das laborintern validierte Mindestkriterium. Für dieses Exon ist ein negativer Befund nicht belastbar.":"Le run est globalement valide, mais l’exon 20 d’EGFR est sous le critère minimal validé en interne. Un résultat négatif pour cet exon n’est pas fiable.","Orthogonale Abklärung":"Clarification orthogonale","Eine unabhängig amplifizierte, validierte Zielmethode weist eine EGFR-Exon-20-Insertion nach. Der ursprüngliche „negative“ Panelbefund war an dieser Stelle nicht aussagefähig.":"Une méthode ciblée validée avec amplification indépendante détecte une insertion de l’exon 20 d’EGFR. Le résultat initial « négatif » du panel n’était pas informatif à cet endroit.","NGS-Wiederholung":"Répétition du NGS","Die Wiederholung mit demselben Assay zeigt erneut den lokalen Dropout. Ein identisches technisches Design löst den systematischen Coverage-Ausfall nicht zuverlässig.":"La répétition du même test montre à nouveau le dropout local. Un design technique identique ne corrige pas de manière fiable le défaut systématique de couverture.","Breites Re-Panel":"Re-panel large","Mehr Panelbreite beantwortet das lokale Coverage-Problem nicht automatisch; entscheidend ist die validierte Abdeckung des fraglichen Exons.":"Un panel plus large ne résout pas automatiquement un problème local de couverture ; ce qui compte est la couverture validée de l’exon concerné.","Global gute Sequenzierqualität; isolierter lokaler Coverage-Ausfall in einem therapieentscheidenden Bereich.":"Qualité de séquençage globalement bonne ; défaut local isolé de couverture dans une région déterminante pour le traitement.","Ein negativer Call ist nur für ausreichend validiert untersuchte Zielregionen zulässig.":"Un call négatif n’est admissible que pour les régions cibles suffisamment étudiées dans des conditions validées.","Der NGS-Run ist nicht insgesamt ungültig, aber EGFR-Exon 20 ist wegen lokaler Unterabdeckung nicht sicher negativ befundbar. Die Limitation muss explizit berichtet und die Zielregion gezielt nachuntersucht werden. Eine orthogonale Methode weist schließlich eine EGFR-Exon-20-Insertion nach.":"Le run NGS n’est pas globalement invalide, mais l’exon 20 d’EGFR ne peut pas être rendu de façon fiable comme négatif en raison d’une sous-couverture locale. La limitation doit être explicitement signalée et la région cible retestée de manière spécifique. Une méthode orthogonale détecte finalement une insertion de l’exon 20 d’EGFR.","Teilbefund: Das Panel darf nicht pauschal als vollständig negativ zusammengefasst werden, solange die therapieentscheidende Zielregion das validierte Coverage-Kriterium nicht erfüllt.":"Compte rendu partiel : le panel ne doit pas être résumé comme entièrement négatif tant que la région cible déterminante pour le traitement ne satisfait pas au critère validé de couverture.","lokale Coverage statt nur Mittelwert prüfen":"vérifier la couverture locale, pas seulement la moyenne","„nicht nachgewiesen“ von „nicht ausreichend untersucht“ trennen":"distinguer « non détecté » de « insuffisamment évalué »","gezielte Nachtestung definieren":"définir un test complémentaire ciblé","Falschaussage: hohe Median-Coverage macht jede Zielregion sicher negativ":"Affirmation fausse : une couverture médiane élevée rend chaque région cible sûrement négative","Optimale Lösung: lokalen Coverage-Defekt erkennen, die Aussage im Befund begrenzen und das betroffene Exon mit einer unabhängigen validierten Methode schließen.":"Solution optimale : reconnaître le défaut local de couverture, limiter la portée du compte rendu et compléter l’exon concerné par une méthode indépendante validée.","MTB-LAB":"MTB-LAB","Das Loch im „negativen“ Panel":"La lacune du panel « négatif »","Molekularpathologie / NGS-Freigabe / MTB":"Pathologie moléculaire / validation NGS / MTB","Coverage auf Zielregionsebene statt nur als Run-Mittelwert bewerten.":"Évaluer la couverture au niveau de la région cible et pas seulement comme moyenne du run.","Nicht nachgewiesen von nicht ausreichend untersucht unterscheiden.":"Distinguer non détecté de insuffisamment évalué.","Bei lokalem Coverage-Ausfall Limitation und gezielte Nachtestung formulieren.":"En cas de défaut local de couverture, formuler la limitation et prévoir un test complémentaire ciblé.","Wiederholung desselben Assays von einer methodisch unabhängigen Bestätigung unterscheiden.":"Distinguer la répétition du même test d’une confirmation méthodologiquement indépendante.","Der Bericht sagt „kein therapierbarer Treiber“. Im QC-Tab fällt aber eine einzige rote Zeile auf: EGFR-Exon 20, 24×. Der Rest des Panels liegt bei mehreren hundert Reads. Genau dort darf aus „nichts gesehen“ kein „sicher nicht vorhanden“ werden.":"Le compte rendu indique « aucun driver actionnable ». Mais une ligne rouge ressort dans l’onglet QC : exon 20 d’EGFR, 24×. Le reste du panel comporte plusieurs centaines de reads. C’est précisément ici que « rien vu » ne doit pas devenir « certainement absent ».","58-jährige Nie-Raucherin mit metastasiertem Lungenadenokarzinom. Das Panel ist global technisch gut, aber eine therapieentscheidende Zielregion unterschreitet das validierte Mindestkriterium. Das Board muss entscheiden, ob limitiert berichtet, wiederholt oder orthogonal geschlossen wird.":"Patiente de 58 ans, jamais fumeuse, avec adénocarcinome pulmonaire métastatique. Le panel est globalement techniquement bon, mais une région cible déterminante pour le traitement est sous le critère minimal validé. Le board doit décider s’il faut rendre avec limitation, répéter le test ou compléter par une méthode orthogonale.","Global gut, lokal schlecht":"Globalement bon, localement insuffisant","Median-Coverage ca. 780×, EGFR-Exon 20 nur 24×.":"Couverture médiane env. 780×, exon 20 d’EGFR seulement 24×.","Run-QC ersetzt keine Target-QC.":"Le QC du run ne remplace pas le QC de la cible.","Sprache ist Diagnostik":"Le langage fait partie du diagnostic","„Keine Mutation nachweisbar“ behauptet mehr als „Region nicht ausreichend abgedeckt“.":"« Aucune mutation détectée » affirme davantage que « région insuffisamment couverte ».","Befundformulierung muss die analytische Aussagegrenze spiegeln.":"La formulation du compte rendu doit refléter les limites analytiques d’interprétation.","Wiederholung ist nicht automatisch unabhängig":"La répétition n’est pas automatiquement indépendante","Ein identisches Assaydesign kann denselben Dropout reproduzieren.":"Un design de test identique peut reproduire le même dropout.","Orthogonale Testung kann systematische Assaygrenzen besser adressieren.":"Un test orthogonal peut mieux prendre en compte les limites systématiques du test.","ca. 45 %":"env. 45 %","Panel-QC":"QC du panel","global valide":"globalement valide","Lokale QC":"QC local","EGFR-Exon 20 unter laborintern validierter Mindest-Coverage":"Exon 20 d’EGFR sous la couverture minimale validée par le laboratoire","Restmaterial vorhanden, aber nicht unbegrenzt.":"Du matériel résiduel est disponible, mais pas en quantité illimitée.","Zeitkritische Therapieentscheidung.":"Décision thérapeutique urgente.","Der lokale Coverage-Grenzwert ist assay- und laborvalidiert; es wird kein universeller Zahlenwert postuliert.":"Le seuil local de couverture est validé pour le test et le laboratoire ; aucune valeur numérique universelle n’est postulée.","Welche Aussage ist bei hoher Median-Coverage, aber unzureichender Coverage eines therapieentscheidenden Exons korrekt?":"Quelle affirmation est correcte lorsque la couverture médiane est élevée mais celle d’un exon déterminant pour le traitement est insuffisante ?","Der Run kann global valide sein, während dieses Exon nicht sicher negativ befundbar ist.":"Le run peut être globalement valide alors que cet exon ne peut pas être rendu de façon fiable comme négatif.","Hohe Median-Coverage macht alle Exons sicher negativ.":"Une couverture médiane élevée rend tous les exons sûrement négatifs.","Der gesamte Run ist zwingend ungültig.":"L’ensemble du run est nécessairement invalide.","Coverage ist nur für Forschungsdaten relevant.":"La couverture n’est pertinente que pour les données de recherche.","Aussagefähigkeit wird zielregionsbezogen bewertet.":"L’interprétabilité est évaluée au niveau de la région cible.","Wie sollte die Limitation berichtet werden?":"Comment la limitation doit-elle être rapportée ?","Die betroffene Region ausdrücklich als nicht ausreichend beurteilt kennzeichnen und Nachtestung empfehlen.":"Indiquer explicitement que la région concernée est insuffisamment évaluée et recommander un test complémentaire.","Gesamtbefund schlicht „negativ“ nennen.":"Qualifier simplement le résultat global de « négatif ».","Coverage nur intern dokumentieren.":"Documenter la couverture uniquement en interne.","Direkt eine Therapie ausschließen.":"Exclure directement une option thérapeutique.","Die klinische Aussage darf die analytische Leistung nicht überschreiten.":"La portée clinique ne doit pas dépasser les performances analytiques.","Was ist bei einem reproduzierbaren lokalen Assay-Dropout besonders sinnvoll?":"Quelle approche est particulièrement appropriée face à un dropout local reproductible du test ?","Eine unabhängig validierte Methode für die Zielregion einsetzen.":"Utiliser une méthode validée indépendamment pour la région cible.","Den identischen Assay beliebig oft wiederholen.":"Répéter le même test autant de fois que souhaité.","Nur ein größeres Panel bestellen, ohne die Zielabdeckung zu prüfen.":"Commander uniquement un panel plus large sans vérifier la couverture de la cible.","Keine weitere Abklärung.":"Aucune clarification supplémentaire.","Eine methodisch unabhängige Lösung adressiert systematische Grenzen besser.":"Une solution méthodologiquement indépendante répond mieux aux limites systématiques.","Die orthogonale Methode weist eine EGFR-Exon-20-Insertion nach. Was war der ursprüngliche Fehler?":"La méthode orthogonale détecte une insertion de l’exon 20 d’EGFR. Quelle était l’erreur initiale ?","Ein nicht ausreichend untersuchter Bereich wurde wie ein sicher negativer Bereich behandelt.":"Une région insuffisamment étudiée a été considérée comme sûrement négative.","Der gesamte NGS-Run war zwingend wertlos.":"L’ensemble du run NGS était nécessairement sans valeur.","Die Histologie war falsch.":"L’histologie était erronée.","Es wurde eine Keimbahnvariante übersehen.":"Une variante germinale a été manquée.","Der Fehler lag in der Reichweite der Negativaussage.":"L’erreur concernait la portée de l’affirmation négative.","Entscheiden Sie, wie der Panelbefund freigegeben wird und wie die offene Zielregion methodisch geschlossen wird.":"Décidez comment valider le résultat du panel et comment compléter méthodologiquement la région cible non résolue.","Coverage-Report auf therapieentscheidende Regionen prüfen.":"Examiner le rapport de couverture des régions déterminantes pour le traitement.","Lokale Limitation explizit formulieren.":"Formuler explicitement la limitation locale.","Nicht den gesamten Run verwerfen, wenn der Rest valide ist.":"Ne pas rejeter l’ensemble du run si le reste est valide.","Gezielte orthogonale oder technisch geeignete Wiederholungsstrategie wählen.":"Choisir une stratégie orthogonale ciblée ou une répétition techniquement appropriée.","Endbefund nach Nachtestung aktualisieren.":"Mettre à jour le compte rendu final après le test complémentaire.","Wiederholung des Panels kann vertretbar sein, wenn die Ursache plausibel zufällig/librarybezogen ist und das Wiederholungsdesign die Zielregion zuverlässig abdeckt.":"Répéter le panel peut être raisonnable si la cause est plausiblement aléatoire/liée à la library et si le protocole de répétition couvre fiablement la région cible.","„Panel negativ“ trotz Coverage-Loch":"« Panel négatif » malgré une lacune de couverture","Überdehnt die analytische Aussage.":"Dépasse la portée analytique.","Run komplett verwerfen":"Rejeter l’ensemble du run","Ignoriert, dass die übrigen Regionen valide sein können.":"Ignore que les autres régions peuvent être valides.","Blind identisch wiederholen":"Répéter à l’identique à l’aveugle","Kann systematische Dropouts reproduzieren.":"Peut reproduire des dropouts systématiques.","Die rote Zeile war der eigentliche Befund":"La ligne rouge était le véritable résultat","Die gezielte unabhängige Nachtestung weist eine EGFR-Exon-20-Insertion nach.":"Le test complémentaire ciblé et indépendant détecte une insertion de l’exon 20 d’EGFR.","Der Fall zeigt, dass analytische Nichtbeurteilbarkeit klinisch relevanter sein kann als ein langer negativer Variantenbericht.":"Ce cas montre que la non-évaluabilité analytique peut être cliniquement plus importante qu’un long rapport de variants négatifs.","Limitiert + gezielt geschlossen":"Limité + résolu de façon ciblée","Lokale Limitation erkannt, orthogonal nachgetestet, relevante Alteration gefunden.":"Limitation locale reconnue, retestée de manière orthogonale, altération pertinente identifiée.","Vollständige analytische und klinische Einordnung.":"Interprétation analytique et clinique complète.","Falsch-negativ freigegeben":"Validé à tort comme négatif","Coverage-Loch wird ignoriert und die Region als negativ berichtet.":"La lacune de couverture est ignorée et la région est rendue négative.","Kritischer Scope-Fehler.":"Erreur critique de portée.","Ganzer Run verworfen":"Run entier rejeté","Valide übrige Ergebnisse werden unnötig wiederholt.":"Les autres résultats valides sont répétés inutilement.","Unnötiger Material-/TAT-Verlust.":"Perte inutile de matériel/TAT.","Coverage unter validiertem Kriterium":"Couverture sous le critère validé","Zielregion als nicht sicher beurteilbar kennzeichnen":"Indiquer que la région cible n’est pas évaluabile de façon fiable","Nachtestung erforderlich, wenn klinisch relevant.":"Un test complémentaire est requis si cela est cliniquement pertinent.","Coverage ist lokal.":"La couverture est locale.","Negativbefunde brauchen nachgewiesene analytische Aussagefähigkeit.":"Les résultats négatifs exigent une interprétabilité analytique démontrée.","Limitationen gehören in die klinische Kernaussage, nicht nur in interne QC.":"Les limitations doivent figurer dans le message clinique principal, pas seulement dans le QC interne.","Der Run bleibt für ausreichend abgedeckte Regionen valide. EGFR-Exon 20 ist nicht sicher negativ befundbar und muss explizit limitiert sowie gezielt nachuntersucht werden; eine unabhängige Methode schließt die diagnostische Lücke.":"Le run reste valide pour les régions suffisamment couvertes. L’exon 20 d’EGFR ne peut pas être rendu de façon fiable comme négatif et doit être explicitement limité puis retesté de manière ciblée ; une méthode indépendante comble la lacune diagnostique.","Target-spezifische QC":"QC spécifique de la cible","Befundsprache":"Langage du compte rendu","Nachteststrategie":"Stratégie de test complémentaire","Wann reicht eine NGS-Wiederholung?":"Quand une répétition du NGS suffit-elle ?","Welche Coverage-Metriken müssen im Labor validiert sein?":"Quelles métriques de couverture doivent être validées au laboratoire ?","Wie formuliert man Negativbefunde bei partieller Nichtbeurteilbarkeit?":"Comment formuler les résultats négatifs lorsqu’une partie du test n’est pas évaluabile ?","Twist: relevanter Befund liegt in der QC, nicht in der Variantenliste":"Twist : le résultat pertinent se trouve dans le QC, pas dans la liste des variants","Kernfehler: nicht ausreichend untersucht ≠ negativ":"Erreur centrale : insuffisamment évalué ≠ négatif","Referenzpfad: Coverage prüfen → limitieren → gezielt schließen":"Parcours de référence : vérifier la couverture → formuler la limitation → combler la lacune de façon ciblée","1,4 % EGFR-T790M im FFPE: Resistenzmutation oder Desaminierungsartefakt?":"EGFR T790M à 1,4 % en FFPE : mutation de résistance ou artefact de désamination ?","FFPE-C>T-Artefakt bei niedriger VA…":"Artefact FFPE C>T à faible VAF…","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress unter zielgerichteter Therapie. In einer kleinen FFPE-Rebiopsie wird zusätzlich EGFR p.T790M mit 1,4 % VAF gemeldet.":"Patient de 67 ans avec NSCLC muté EGFR en progression sous thérapie ciblée. Une petite rebiopsie FFPE rapporte en plus EGFR p.T790M à 1,4 % de VAF.","Ist die niedrigfrequente C>T-Variante als echte Resistenzsubpopulation belastbar oder zunächst artefaktverdächtig?":"La variante C>T de faible fréquence est-elle fiable comme véritable sous-population résistante ou doit-elle d’abord être considérée comme suspecte d’artefact ?","Therapiewechsel soll kurzfristig festgelegt werden.":"Un changement thérapeutique doit être décidé rapidement.","Primärtreiber":"Driver primaire","Bekannte klonale EGFR-aktivierende Mutation mit hoher VAF wird in der Rebiopsie erneut nachgewiesen.":"La mutation activatrice clonale connue d’EGFR, à VAF élevée, est de nouveau détectée dans la rebiopsie.","Neue Variante":"Nouveau variant","EGFR p.T790M, 1,4 % VAF, nur knapp oberhalb der technischen Reporting-Grenze.":"EGFR p.T790M, VAF 1,4 %, juste au-dessus du seuil technique de rendu.","Kleine Biopsie, lange Formalinfixierung; DNA zeigt deutliche Fragmentierung.":"Petite biopsie, fixation prolongée au formol ; l’ADN présente une fragmentation marquée.","Actionability des Gens wird mit analytischer Validität des einzelnen Calls verwechselt.":"L’actionnabilité du gène est confondue avec la validité analytique du call individuel.","Vitales Adenokarzinom, Tumoranteil ca. 30 %.":"Adénocarcinome viable, cellularité tumorale env. 30 %.","Sequenzdaten":"Données de séquençage","T790M vorwiegend in einem Strang-/Endkontext, niedrige Molekülzahl; mehrere weitere sehr niedrige C>T/G>A-Ereignisse.":"T790M principalement dans un contexte de brin/extrémité, faible nombre de molécules ; plusieurs autres événements C>T/G>A à très faible niveau.","Echte Subklonmutation oder FFPE-bedingte Cytosindesaminierung?":"Véritable mutation sous-clonale ou désamination de la cytosine liée au FFPE ?","Ein klinisch attraktiver Call verdient nicht weniger, sondern mehr QC.":"Un call cliniquement attractif mérite davantage de QC, pas moins.","FFPE-Stanzbiopsie, nur wenige Restrollen.":"Carotte biopsique FFPE, avec seulement quelques coupes résiduelles disponibles.","stark fragmentiert.":"fortement fragmenté.","Alternative":"Alternative","zweite Extraktion aus tieferen Schnitten möglich.":"une seconde extraction à partir de coupes plus profondes est possible.","Orthogonale Bestätigung gezielt möglich.":"Une confirmation orthogonale ciblée est possible.","FFPE-Artefaktprüfung":"Évaluation des artefacts FFPE","Niedrigfrequenten klinisch relevanten Call bestätigen":"Confirmer un call cliniquement pertinent à faible fréquence","Artefaktreview":"Revue des artefacts","Der Call zeigt typische Warnsignale: sehr niedrige VAF, geringe unabhängige Molekülzahl, ungünstiger Strang-/Read-End-Kontext und zusätzliche niedrigfrequente C>T/G>A-Ereignisse im stark fragmentierten FFPE-Material.":"Le call présente des signaux d’alerte typiques : VAF très faible, peu de molécules indépendantes, contexte défavorable de brin/extrémité de lecture et événements C>T/G>A supplémentaires à faible fréquence dans un matériel FFPE fortement fragmenté.","Orthogonale Bestätigung":"Confirmation orthogonale","In einer unabhängigen Extraktion und orthogonalen Zielmethode ist p.T790M nicht reproduzierbar, während die bekannte klonale EGFR-Mutation stabil nachweisbar bleibt. Gesamtbild spricht für FFPE-Artefakt.":"Dans une extraction indépendante et avec une méthode ciblée orthogonale, p.T790M n’est pas reproductible, tandis que la mutation clonale d’EGFR connue reste détectable de façon stable. L’ensemble est en faveur d’un artefact FFPE.","Mehr Sequenzierbreite ersetzt die gezielte analytische Prüfung des grenzwertigen Calls nicht.":"Une plus grande largeur de séquençage ne remplace pas l’évaluation analytique ciblée du call limite.","Stark fragmentierte FFPE-DNA mit erhöhtem Risiko niedrigfrequenter Desaminierungsartefakte.":"ADN FFPE fortement fragmenté avec risque accru d’artefacts de désamination à faible fréquence.","Niedrige VAF allein beweist weder Artefakt noch Subklon; Muster, Reproduzierbarkeit und Assay-QC entscheiden.":"Une VAF faible seule ne prouve ni un artefact ni un sous-clone ; le profil, la reproductibilité et le QC du test sont déterminants.","Die klinisch relevante C>T-Variante liegt in einem stark artefaktanfälligen FFPE-Kontext und ist nicht unabhängig reproduzierbar. Sie darf daher nicht als gesicherte Resistenzmutation berichtet werden; die bekannte klonale EGFR-Alteration bleibt dagegen robust nachweisbar.":"Le variant C>T cliniquement pertinent survient dans un contexte FFPE fortement exposé aux artefacts et n’est pas reproductible indépendamment. Il ne doit donc pas être rapporté comme mutation de résistance confirmée ; en revanche, l’altération clonale d’EGFR connue reste détectée de manière robuste.","Teilbefund: Eine niedrigfrequente C>T-Variante in stark geschädigter FFPE-DNA muss vor therapeutischer Interpretation auf Artefaktmuster und Reproduzierbarkeit geprüft werden.":"Résultat partiel : un variant C>T à faible fréquence dans un ADN FFPE très altéré doit être évalué quant au profil d’artefact et à la reproductibilité avant toute interprétation thérapeutique.","Desaminierungsartefakte als Differenzialdiagnose nennen":"Mentionner les artefacts de désamination comme explication différentielle","VAF nicht isoliert interpretieren":"Ne pas interpréter la VAF isolément","klinisch relevanten Low-VAF-Call unabhängig bestätigen":"Confirmer indépendamment un call cliniquement pertinent à faible VAF","Falschaussage: therapierbares Gen macht jeden Low-VAF-Call automatisch echt":"Affirmation fausse : un gène actionnable rend automatiquement réel tout call à faible VAF","Optimale Lösung: Low-VAF-C>T-Call im FFPE-Kontext kritisch prüfen, technische Artefaktmerkmale berücksichtigen und vor Therapieableitung unabhängig bestätigen.":"Solution optimale : évaluer de façon critique le call C>T à faible VAF dans le contexte FFPE, tenir compte des caractéristiques techniques d’artefact et le confirmer indépendamment avant d’en tirer des conséquences thérapeutiques.","FFPE":"FFPE","Artefakt":"Artefact","Low VAF":"Faible VAF","Der attraktive 1,4-%-Call":"Le call attractif à 1,4 %","Molekularpathologie / NGS-QC / MTB":"Pathologie moléculaire / QC NGS / MTB","FFPE-bedingte C>T/G>A-Artefakte als analytische Differenzialdiagnose erkennen.":"Reconnaître les artefacts C>T/G>A liés au FFPE comme diagnostic différentiel analytique.","VAF, Molekülzahl, Strang-/Read-Kontext und Reproduzierbarkeit gemeinsam bewerten.":"Évaluer ensemble la VAF, le nombre de molécules, le contexte brin/lecture et la reproductibilité.","Klinische Relevanz nicht mit analytischer Validität verwechseln.":"Ne pas confondre pertinence clinique et validité analytique.","Low-VAF-Calls vor weitreichender Therapieableitung angemessen bestätigen.":"Confirmer de manière appropriée les calls à faible VAF avant des décisions thérapeutiques à forte conséquence.","Auf dem Variantenboard leuchtet EGFR p.T790M. VAF 1,4 %. Klinisch wäre der Befund wichtig – analytisch sieht er aber genau so aus, wie ein alter FFPE-Block Probleme machen kann.":"EGFR p.T790M apparaît sur le tableau des variants. VAF 1,4 %. Cliniquement, le résultat serait important ; analytiquement, il ressemble exactement au type de problème qu’un ancien bloc FFPE peut générer.","67-jähriger Patient mit EGFR-mutiertem NSCLC und Progress. In einer kleinen, stark fragmentierten Rebiopsie erscheint ein neuer C>T-Call knapp oberhalb der Reporting-Grenze. Das Board muss entscheiden, ob dies ein echter Resistenzklon ist.":"Patient de 67 ans avec NSCLC muté EGFR en progression. Dans une petite rebiopsie fortement fragmentée apparaît un nouveau call C>T juste au-dessus du seuil de rendu. Le comité doit décider s’il s’agit d’un véritable sous-clone de résistance.","Actionability ist kein QC-Kriterium":"L’actionnabilité n’est pas un critère de QC","Ein therapeutisch interessanter Genname macht einen Call nicht analytisch wahr.":"Un nom de gène intéressant sur le plan thérapeutique ne rend pas un call analytiquement vrai.","Analytische Validität kommt vor klinischer Interpretation.":"La validité analytique précède l’interprétation clinique.","FFPE-Muster":"Profil FFPE","Mehrere sehr niedrige C>T/G>A-Ereignisse und fragmentierte DNA erhöhen den Artefaktverdacht.":"Plusieurs événements C>T/G>A à très faible niveau et un ADN fragmenté augmentent la suspicion d’artefact.","Muster ist informativer als eine einzelne VAF.":"Le profil est plus informatif qu’une VAF isolée.","Unabhängige Reproduzierbarkeit":"Reproductibilité indépendante","Eine zweite Extraktion/orthogonale Methode kann einen grenzwertigen Call stabilisieren oder entkräften.":"Une seconde extraction/méthode orthogonale peut conforter ou réfuter un call limite.","Bestätigung sollte möglichst methodisch unabhängig sein.":"La confirmation doit être méthodologiquement indépendante dans la mesure du possible.","Bekannter Treiber":"Driver connu","klonale EGFR-aktivierende Mutation robust nachweisbar":"mutation activatrice clonale d’EGFR détectée de manière robuste","Neuer Call":"Nouveau call","EGFR p.T790M, 1,4 % VAF":"EGFR p.T790M, VAF 1,4 %","FFPE-QC":"QC FFPE","stark fragmentiert; weitere sehr niedrige C>T/G>A-Ereignisse":"fortement fragmenté ; événements C>T/G>A supplémentaires à très faible niveau","Wenig Restmaterial.":"Peu de matériel résiduel.","Der Fall postuliert keine universelle VAF-Grenze; entscheidend ist die laborvalidierte Performance im konkreten Assay.":"Le cas ne postule pas de seuil universel de VAF ; le facteur décisif est la performance du test spécifique validée par le laboratoire.","Was ist der erste richtige Schritt bei einem klinisch relevanten 1,4-%-C>T-Call in stark geschädigtem FFPE?":"Quelle est la première étape correcte face à un call C>T cliniquement pertinent à 1,4 % dans un matériel FFPE très altéré ?","Call-level QC und FFPE-Artefaktmuster prüfen.":"Revoir le QC au niveau du call et le profil d’artefact FFPE.","Sofort Therapie ableiten.":"En déduire immédiatement un traitement.","Jede Variante unter 5 % grundsätzlich verwerfen.":"Écarter systématiquement tout variant inférieur à 5 %.","Keimbahntestung veranlassen.":"Organiser un test germinal.","Es gibt keine universelle VAF-Regel; der Call muss assay- und kontextbezogen validiert werden.":"Il n’existe pas de règle universelle de VAF ; le call doit être validé en fonction du test et du contexte.","Welche Befunde erhöhen hier den Artefaktverdacht?":"Quels éléments augmentent ici la suspicion d’artefact ?","sehr niedrige VAF/geringe Molekülzahl":"VAF très faible/peu de molécules","mehrere niedrigfrequente C>T/G>A-Ereignisse":"multiples événements C>T/G>A à faible fréquence","stark fragmentierte FFPE-DNA":"ADN FFPE fortement fragmenté","bekannte klonale Treibermutation ist robust":"la mutation driver clonale connue est robuste","Die Kombination aus FFPE-Schaden und typischem Substitutionsmuster ist verdächtig.":"L’association de dommages FFPE et d’un profil de substitutions typique est suspecte.","Was erhöht die Sicherheit vor therapeutischer Interpretation am stärksten?":"Qu’est-ce qui augmente le plus la fiabilité avant l’interprétation thérapeutique ?","Unabhängige Extraktion und/oder orthogonale validierte Zielmethode.":"Extraction indépendante et/ou méthode ciblée orthogonale validée.","Längere Literaturrecherche ohne analytische Prüfung.":"Une recherche bibliographique plus longue sans évaluation analytique.","Den gleichen Report erneut öffnen.":"Rouvrir le même rapport.","Nur die Therapierbarkeit des Gens bewerten.":"Évaluer uniquement si le gène est ciblable thérapeutiquement.","Reproduzierbarkeit adressiert die analytische Kernfrage.":"La reproductibilité répond à la question analytique centrale.","T790M ist unabhängig nicht reproduzierbar, der bekannte klonale EGFR-Treiber schon. Wie ist das Gesamtbild?":"T790M n’est pas reproductible indépendamment, contrairement au driver clonal d’EGFR connu. Comment interpréter l’ensemble ?","Der neue Low-VAF-Call ist nicht gesichert und im Kontext am ehesten artefaktbedingt.":"Le nouveau call à faible VAF n’est pas confirmé et, dans ce contexte, est très probablement lié à un artefact.","T790M ist trotzdem sicher echt.":"T790M est malgré tout certainement réel.","Auch der bekannte EGFR-Treiber ist damit falsch.":"Le driver d’EGFR connu doit donc lui aussi être faux.","Der Unterschied ist ohne Bedeutung.":"La différence est sans importance.","Selektive Nichtreproduzierbarkeit plus Artefaktmuster entkräftet den grenzwertigen Call.":"La non-reproductibilité sélective associée au profil d’artefact invalide largement le call limite.","Bewerten Sie, ob der Low-VAF-Call als gesichert berichtet und therapeutisch verwendet werden darf.":"Évaluer si le call à faible VAF peut être rapporté comme confirmé et utilisé à des fins thérapeutiques.","FFPE-Qualität und Substitutionsmuster prüfen.":"Revoir la qualité FFPE et le profil de substitutions.","Call-level Evidenz bewerten.":"Évaluer les éléments de preuve au niveau du call.","Low-VAF nicht pauschal verwerfen, aber bei hoher Konsequenz bestätigen.":"Ne pas rejeter systématiquement une faible VAF, mais la confirmer lorsque l’enjeu clinique est important.","Unabhängige Reproduzierbarkeit einbeziehen.":"Intégrer la reproductibilité indépendante dans l’évaluation.","Nur robuste Befunde in die Therapiekernaussage aufnehmen.":"N’inclure que les résultats robustes dans le message thérapeutique principal.","Bei sehr gut validiertem ultrasensitivem Assay und überzeugender unabhängiger Molekülevidenz kann ein niedriger VAF real sein; der Fall lehrt keine starre Prozentgrenze.":"Avec un test ultrasensible bien validé et des éléments moléculaires indépendants convaincants, une faible VAF peut être réelle ; le cas n’enseigne pas de seuil de pourcentage rigide.","<5 % = immer Artefakt":"<5 % = toujours un artefact","Ignoriert echte Subklone und assayspezifische Nachweisgrenzen.":"Ignore les véritables sous-clones et les limites de détection spécifiques du test.","Actionable = echt":"Actionnable = réel","Verwechselt klinische mit analytischer Evidenz.":"Confond les éléments cliniques avec les preuves analytiques.","Breites Re-Panel statt Call-QC":"Répéter un panel large au lieu d’un QC au niveau du call","Mehr Daten lösen den konkreten Artefaktverdacht nicht automatisch.":"Davantage de données ne résolvent pas automatiquement la suspicion spécifique d’artefact.","Die Resistenzmutation verschwindet":"La mutation de résistance disparaît","In unabhängiger Extraktion und orthogonaler Zielmethode ist T790M nicht reproduzierbar, der klonale Primärtreiber jedoch stabil.":"Dans une extraction indépendante et avec une méthode ciblée orthogonale, T790M n’est pas reproductible, tandis que le driver clonal primaire reste stable.","Der attraktivste Befund des Reports ist nicht der belastbarste.":"Le résultat le plus attractif du compte rendu n’est pas le plus robuste.","Low-VAF korrekt entkräftet":"Le variant à faible VAF a été correctement réfuté","Artefaktmuster erkannt und Call unabhängig nicht bestätigt.":"Un profil d’artéfact a été identifié et le variant n’a pas été confirmé indépendamment.","Therapeutisches Overcalling vermieden.":"La surinterprétation thérapeutique a été évitée.","Direkt als Resistenzmutation berichtet":"Rapportée directement comme mutation de résistance","Ein grenzwertiger FFPE-Call steuert die Therapie.":"Un variant FFPE limite pilote la décision thérapeutique.","Analytische Evidenz unzureichend.":"Les preuves analytiques sont insuffisantes.","Pauschal unter 5 % verworfen":"Rejetée systématiquement en dessous de 5 %","Der richtige Ausgang wird aus der falschen Regel abgeleitet.":"Le bon résultat est obtenu à partir d’une mauvaise règle.","Keine universelle VAF-Grenze verwenden.":"Ne pas utiliser de seuil universel de VAF.","klinisch relevanter Low-VAF-Call + Artefaktmuster":"variant à faible VAF cliniquement pertinent + profil d’artéfact","analytische Bestätigung vor finaler Therapieaussage":"confirmation analytique avant la conclusion thérapeutique finale","Bei Nichtbestätigung nicht als gesicherte Resistenzmutation berichten.":"En l’absence de confirmation, ne pas la rapporter comme une mutation de résistance établie.","FFPE-Artefakte sind call- und kontextabhängig.":"Les artéfacts FFPE dépendent du variant et du contexte.","Niedrige VAF ist ein Warnsignal, kein Urteil.":"Une faible VAF est un signal d’alerte, pas un verdict.","Je größer die klinische Konsequenz, desto wichtiger die analytische Absicherung.":"Plus la conséquence clinique est importante, plus la confirmation analytique est essentielle.","Der T790M-Call ist aufgrund des FFPE-Musters und fehlender unabhängiger Reproduzierbarkeit nicht gesichert; keine Therapieentscheidung allein darauf stützen.":"Le variant T790M n’est pas établi en raison du profil d’artéfact FFPE et de l’absence de reproductibilité indépendante ; aucune décision thérapeutique ne doit reposer sur ce seul résultat.","Low-VAF-Interpretation":"Interprétation d’une faible VAF","Bestätigung":"Confirmation","Welche Artefaktmuster sind plattformabhängig?":"Quels profils d’artéfacts dépendent de la plateforme ?","Wann ist eine zweite Extraktion sinnvoll?":"Quand une seconde extraction est-elle utile ?","Wie dokumentiert man nicht bestätigte Calls?":"Comment documenter les variants non confirmés ?","Twist: klinisch attraktivster Call ist analytisch schwächster":"Twist : le variant le plus séduisant cliniquement est le plus faible analytiquement","Keine starre VAF-Grenze":"Pas de seuil de VAF rigide","Referenzpfad: Call-QC → Artefaktmuster → unabhängige Bestätigung":"Parcours de référence : QC du variant → profil d’artéfact → confirmation indépendante","Tumor-only BRCA2 bei 48 % VAF: therapeutisch relevant, Keimbahn trotzdem offen":"BRCA2 tumor-only à 48 % de VAF : pertinent sur le plan thérapeutique, statut germinal encore indéterminé","Tumor-only NGS: Keimbahnverdacht B…":"NGS tumor-only : suspicion de variant germinal B…","61-jähriger Patient mit metastasiertem kastrationsresistentem Prostatakarzinom. Tumor-only NGS zeigt eine pathogene truncierende BRCA2-Variante mit 48 % VAF.":"Patient de 61 ans atteint d’un cancer de la prostate métastatique résistant à la castration. Le NGS tumor-only montre un variant tronquant pathogène de BRCA2 à 48 % de VAF.","Darf aus VAF und Gen direkt auf eine Keimbahnmutation geschlossen werden – und wie werden therapeutische und hereditäre Konsequenzen getrennt?":"Peut-on conclure à une mutation germinale à partir de la VAF et du gène seuls, et comment séparer les conséquences thérapeutiques des implications héréditaires ?","Systemische Therapieentscheidung und genetische Beratung sollen parallel geplant werden.":"La planification du traitement systémique et le conseil génétique doivent être menés en parallèle.","Schwester mit Mammakarzinom mit 46 Jahren, Vater mit Prostatakarzinom mit 58 Jahren.":"Sœur atteinte d’un cancer du sein à 46 ans, père atteint d’un cancer de la prostate à 58 ans.","Tumorprofil":"Profil tumoral","Pathogene BRCA2-Trunkierung; Tumorreinheit und Kopienzahl machen eine Herkunft aus der VAF allein nicht eindeutig.":"Troncation pathogène de BRCA2 ; la pureté tumorale et le nombre de copies ne permettent pas de déterminer l’origine du variant à partir de la VAF seule.","„ungefähr 50 %“ wird mit „Keimbahn bewiesen“ gleichgesetzt.":"« Environ 50 % » est assimilé à « germinal prouvé ».","Tumorbiomarker und hereditäre Diagnostik sauber entkoppeln und dann wieder integrieren.":"Séparer clairement le biomarqueur tumoral du diagnostic héréditaire, puis réintégrer les deux dimensions.","Metastasiertes Prostataadenokarzinom.":"Adénocarcinome prostatique métastatique.","BRCA2 pathogene Loss-of-function-Variante, VAF 48 %.":"Variant pathogène loss-of-function de BRCA2, VAF 48 %.","somatisch, Keimbahn oder beides im Tumorkontext?":"somatique, germinale ou les deux dans le contexte tumoral ?","Tumorreinheit, LOH und Copy-number können VAF deutlich verschieben.":"La pureté tumorale, la LOH et le nombre de copies peuvent modifier fortement la VAF.","FFPE-Metastase für Tumorprofil; EDTA-Blut für bestätigende Keimbahndiagnostik verfügbar.":"Métastase FFPE pour le profilage tumoral ; sang EDTA disponible pour une confirmation germinale.","ca. 60 %.":"env. 60 %.","Consent":"Consentement","Genetische Beratung/Einwilligung für Keimbahndiagnostik erforderlich.":"Le test germinal nécessite un conseil génétique et un consentement.","Tumor-normal bzw. gezielte Keimbahnbestätigung möglich.":"Une analyse tumor-normal ou une confirmation germinale ciblée est possible.","Tumor-BRCA/HRR einordnen":"Interpréter le résultat BRCA/HRR tumoral","Potenzielle Keimbahn separat klären":"Clarifier séparément une éventuelle origine germinale","Pathogene BRCA2-Loss-of-function-Variante im Tumor; für die tumorbezogene Therapieentscheidung relevant, ohne damit die Keimbahnherkunft zu beweisen.":"Variant pathogène loss-of-function de BRCA2 dans la tumeur ; pertinent pour le traitement antitumoral sans prouver une origine germinale.","Die pathogene BRCA2-Variante wird im konstitutionellen Material bestätigt: Keimbahnmutation. Der Tumor-only-Befund war ein Hinweis, nicht der Beweis.":"Le variant pathogène de BRCA2 est confirmé dans le matériel constitutionnel : mutation germinale. Le résultat tumor-only était un indice, pas une preuve.","Humangenetische Beratung":"Conseil génétique","Genetische Beratung wird veranlasst; hereditäre Konsequenzen werden außerhalb des reinen Tumorbefunds adressiert.":"Un conseil génétique est organisé ; les implications héréditaires sont traitées en dehors du compte rendu tumor-only.","Tumor-only":"Tumor-only","Ohne Normalprobe kann die Herkunft einer Variante nicht allein aus der VAF sicher bestimmt werden.":"Sans échantillon normal, l’origine d’un variant ne peut pas être déterminée de façon fiable à partir de la VAF seule.","Therapeutische Tumorrelevanz und hereditäre Bedeutung sind getrennte Fragestellungen.":"La pertinence thérapeutique tumorale et la signification héréditaire sont deux questions distinctes.","Die pathogene BRCA2-Variante ist im Tumor therapeutisch relevant, aber Tumor-only Sequenzierung beweist keine Keimbahnherkunft. VAF um 50 % erhöht den Verdacht, ist wegen Tumorreinheit, LOH und Copy-number jedoch nicht beweisend. Die bestätigende Analyse im konstitutionellen Material zeigt hier tatsächlich eine Keimbahnmutation.":"Le variant pathogène de BRCA2 est pertinent sur le plan thérapeutique dans la tumeur, mais le séquençage tumor-only ne prouve pas une origine germinale. Une VAF autour de 50 % augmente la suspicion sans être concluante en raison de la pureté tumorale, de la LOH et du nombre de copies. Ici, l’analyse de confirmation dans le matériel constitutionnel démontre une mutation germinale.","Teilbefund: Ein Tumor-only BRCA2-Befund kann therapeutisch relevant sein und gleichzeitig eine separate Keimbahnabklärung auslösen; die VAF allein entscheidet die Herkunft nicht.":"Résultat partiel : un résultat BRCA2 tumor-only peut être pertinent sur le plan thérapeutique tout en déclenchant une exploration germinale distincte ; la VAF seule ne détermine pas l’origine.","Tumoractionability separat bewerten":"Évaluer séparément l’actionnabilité tumorale","Keimbahnverdacht separat adressieren":"Traiter séparément la suspicion d’origine germinale","VAF nicht als Herkunftsbeweis verwenden":"Ne pas utiliser la VAF comme preuve de l’origine","Falschaussage: 48–50 % VAF im Tumor beweist Keimbahn":"Affirmation fausse : une VAF de 48–50 % dans la tumeur prouve une origine germinale","Optimale Lösung: Tumorbefund therapeutisch einordnen, Keimbahnverdacht transparent markieren und mit konstitutionellem Material/genetischer Beratung bestätigen.":"Solution optimale : interpréter le résultat tumoral sur le plan thérapeutique, signaler clairement la suspicion d’origine germinale et la confirmer sur matériel constitutionnel/avec conseil génétique.","48 % sind kein Abstammungsnachweis":"48 % ne prouve pas l’origine germinale","Molekulares Tumorboard / Humangenetik-Schnittstelle":"Interface RCP moléculaire / Génétique","Tumor-only NGS nicht mit Keimbahndiagnostik gleichsetzen.":"Ne pas assimiler le NGS tumor-only au diagnostic germinal.","VAF nur als Hinweis und nie isoliert als Herkunftsbeweis nutzen.":"Utiliser la VAF uniquement comme indice et jamais isolément comme preuve de l’origine.","Tumorbezogene Therapieinformation und hereditäre Konsequenzen getrennt bearbeiten.":"Traiter séparément l’information thérapeutique tumorale et les implications héréditaires.","Bestätigende Keimbahndiagnostik mit geeigneter Beratung/Einwilligung veranlassen.":"Organiser un test germinal confirmatoire avec conseil/consentement approprié.","BRCA2, pathogene Trunkierung, VAF 48 %. Der Report sieht „keimbahnverdächtig“ aus – aber 48 % im Tumor sind keine Blutprobe. Genau hier muss das Board zwei richtige Aussagen gleichzeitig halten.":"BRCA2, variant tronquant pathogène, VAF 48 %. Le compte rendu paraît « évocateur d’un variant germinal » — mais 48 % dans une tumeur n’est pas un prélèvement sanguin. C’est précisément ici que le comité doit maintenir deux affirmations justes en parallèle.","61-jähriger Patient mit mCRPC und pathogener BRCA2-Variante im Tumor-only Panel. Der Befund kann therapeutisch relevant sein. Wegen VAF und Familienanamnese besteht zusätzlich Keimbahnverdacht, der separat bestätigt werden muss.":"Patient de 61 ans avec mCRPC et variant pathogène de BRCA2 dans un panel tumor-only. Le résultat peut être pertinent sur le plan thérapeutique. La VAF et les antécédents familiaux font en outre suspecter une origine germinale, qui doit être confirmée séparément.","VAF ist modellabhängig":"La VAF dépend du modèle/contexte","Tumorreinheit, LOH, Amplifikation/Deletion und Klonalität verschieben die beobachtete VAF.":"La pureté tumorale, la LOH, l’amplification/délétion et la clonalité peuvent modifier la VAF observée.","50 % ist kein magischer Keimbahn-Cutoff.":"50 % n’est pas un seuil magique de germinalité.","Zwei Konsequenzachsen":"Deux axes de conséquences","Tumortherapie kann auf dem somatischen Befund beruhen; Familien-/Prädispositionsfragen brauchen Keimbahndiagnostik.":"Le traitement tumoral peut s’appuyer sur le résultat somatique ; les questions familiales/de prédisposition nécessitent un test germinal.","Dasselbe Gen erzeugt zwei unterschiedliche Workflows.":"Le même gène entraîne deux parcours différents.","Tumor-only hat Grenzen":"Le tumor-only a des limites","Ohne Normalprobe bleibt die Herkunft vieler Varianten unbestimmt.":"Sans échantillon normal, l’origine de nombreux variants reste indéterminée.","Bericht und Beratung müssen das transparent machen.":"Le compte rendu et le conseil doivent l’expliciter clairement.","pathogene BRCA2-LoF, VAF 48 %":"BRCA2 LoF pathogène, VAF 48 %","frühes Mammakarzinom bei Schwester, Prostatakarzinom beim Vater":"cancer du sein précoce chez la sœur, cancer de la prostate chez le père","Normalprobe":"Échantillon normal","noch nicht untersucht":"pas encore analysé","Konstitutionelles Material verfügbar.":"Du matériel constitutionnel est disponible.","Hereditäre Diagnostik erfordert eigenen Prozess/Einwilligung.":"Le diagnostic héréditaire nécessite une procédure/un consentement distinct.","Tumor-VAF wird im Kontext von Reinheit und Copy-number interpretiert.":"La VAF tumorale s’interprète dans le contexte de la pureté et du nombre de copies.","Was beweist eine pathogene BRCA2-Variante mit 48 % VAF im Tumor-only Panel?":"Que prouve un variant pathogène de BRCA2 à 48 % de VAF dans un panel tumor-only ?","Sie ist keimbahnverdächtig, beweist aber ohne konstitutionelle Probe keine Keimbahnherkunft.":"Il fait suspecter une origine germinale sans la prouver en l’absence de matériel constitutionnel.","Keimbahn ist sicher bewiesen.":"L’origine germinale est définitivement prouvée.","Somatisch ist sicher bewiesen.":"L’origine somatique est définitivement prouvée.","Die Variante ist ein Artefakt.":"Le variant est un artefact.","Tumorreinheit und Copy-number verhindern einfache VAF-Herkunftsregeln.":"La pureté tumorale et le nombre de copies empêchent d’appliquer des règles simples d’origine basées sur la VAF.","Welche zwei Fragen müssen getrennt beantwortet werden?":"Quelles sont les deux questions à traiter séparément ?","Welche tumorbezogene therapeutische Bedeutung hat BRCA2?":"Quelle est la signification thérapeutique tumorale de BRCA2 ?","Liegt eine konstitutionelle pathogene Variante vor?":"Existe-t-il un variant pathogène constitutionnel ?","Welche Farbe hat der Report?":"De quelle couleur est le compte rendu ?","Reicht das Alter allein als Keimbahntest?":"L’âge seul suffit-il pour justifier un test germinal ?","Therapie und Prädisposition sind gekoppelt, aber nicht identisch.":"Traitement et prédisposition sont liés, mais ne se confondent pas.","Wie wird die Keimbahnfrage belastbar geklärt?":"Comment clarifier de manière fiable la question germinale ?","Analyse geeigneten konstitutionellen Materials im passenden genetischen Prozess.":"Analyser un matériel constitutionnel approprié dans le cadre génétique adapté.","Nur VAF erneut ansehen.":"Simplement regarder à nouveau la VAF.","Nur denselben Tumor erneut sequenzieren.":"Séquencer à nouveau uniquement la même tumeur.","Gar nicht; Tumor-only reicht.":"Ne rien faire ; le tumor-only suffit.","Die Herkunft braucht konstitutionellen Vergleich/Bestätigung.":"L’origine nécessite une comparaison/confirmation constitutionnelle.","Die Variante wird im Blut bestätigt. Was ändert sich?":"Le variant est confirmé dans le sang. Qu’est-ce qui change ?","Zusätzlich zur Tumorrelevanz ist nun eine Keimbahnmutation bestätigt und hereditäre Konsequenzen können adressiert werden.":"En plus de la pertinence tumorale, une mutation germinale est désormais confirmée et les implications héréditaires peuvent être prises en charge.","Die Tumorrelevanz verschwindet.":"La pertinence tumorale disparaît.","Der Tumorbefund war falsch.":"Le résultat tumoral était faux.","Es gibt keinerlei zusätzliche Konsequenz.":"Il n’y a aucune conséquence supplémentaire.","Die bestätigte Herkunft ergänzt den Tumorbefund um eine zweite klinische Dimension.":"L’origine confirmée ajoute une seconde dimension clinique au résultat tumoral.","Formulieren Sie Tumor- und Keimbahnaussage getrennt und definieren Sie den nächsten diagnostischen Schritt.":"Formuler séparément les conclusions tumorale et germinale et définir l’étape diagnostique suivante.","Pathogene BRCA2-Variante im Tumor als tumorbezogenen Biomarker einordnen.":"Interpréter le variant pathogène de BRCA2 dans la tumeur comme biomarqueur tumoral.","VAF und Familienanamnese als Keimbahnverdacht, nicht Beweis, kommunizieren.":"Présenter la VAF et les antécédents familiaux comme des éléments de suspicion germinale, non comme une preuve.","Konstitutionelle Testung/genetische Beratung veranlassen.":"Organiser un test constitutionnel/conseil génétique.","Nach Bestätigung hereditäre Ebene getrennt dokumentieren.":"Après confirmation, documenter séparément la dimension héréditaire.","Je nach lokaler Struktur kann eine direkte Überweisung zur Humangenetik statt tumor-normal Analyse im selben Labor sinnvoll sein.":"Selon l’organisation locale, une orientation directe vers la génétique peut être préférable à une analyse tumor-normal dans le même laboratoire.","48 % = Keimbahn":"48 % = germinal","VAF im Tumor hängt von Reinheit, LOH und Copy-number ab.":"La VAF tumorale dépend de la pureté, de la LOH et du nombre de copies.","Nur Therapie, Keimbahn ignorieren":"Uniquement le traitement, ignorer le germinal","Verpasst potenziell relevante Prädispositionsinformation.":"Fait manquer une information potentiellement pertinente de prédisposition.","Nur Keimbahn diskutieren":"Discuter uniquement du germinal","Ignoriert die unmittelbare tumorbezogene Bedeutung.":"Ignore la pertinence tumorale immédiate.","Der Verdacht bestätigt sich – aber erst im richtigen Material":"La suspicion se confirme — mais uniquement dans le bon matériel","Die BRCA2-Variante wird im konstitutionellen Material bestätigt.":"Le variant BRCA2 est confirmé dans le matériel constitutionnel.","Der Fall zeigt den Unterschied zwischen einem starken Hinweis aus Tumor-only NGS und einem echten Keimbahnnachweis.":"Le cas illustre la différence entre un indice fort issu d’un NGS tumor-only et une véritable confirmation germinale.","Tumorrelevanz genutzt, Keimbahn separat bestätigt.":"La pertinence tumorale est utilisée, le statut germinal est confirmé séparément.","Vollständige Präzisionsonkologie plus Prädispositionslogik.":"Oncologie de précision complète avec logique de prédisposition.","Keimbahn aus 48 % behauptet":"Origine germinale affirmée à partir de 48 %","Herkunft ohne Normalprobe overcallt.":"Origine surinterprétée sans échantillon normal.","Methodisch unzulässig.":"Méthodologiquement non valide.","Keimbahnverdacht ignoriert":"Suspicion germinale ignorée","Hereditäre Ebene bleibt ungeklärt.":"La dimension héréditaire reste non clarifiée.","Unvollständige Nachsorge.":"Suivi incomplet.","pathogene Variante in Prädispositionsgen im Tumor-only Kontext":"variant pathogène dans un gène de prédisposition en contexte tumor-only","Keimbahnpotenzial bewerten und ggf. Bestätigung/Genetik veranlassen":"évaluer le potentiel germinal et organiser une confirmation/prise en charge génétique si indiqué","Tumorbefund nicht als konstitutionellen Befund etikettieren.":"Ne pas étiqueter le résultat tumoral comme résultat constitutionnel.","Tumor-only ist keine Keimbahndiagnostik.":"Le tumor-only n’est pas un diagnostic germinal.","VAF ist ein Hinweis, kein Beweis.":"La VAF est un indice, pas une preuve.","Dasselbe Variantenergebnis kann therapeutische und hereditäre Konsequenzen parallel haben.":"Le même résultat de variant peut avoir en parallèle des conséquences thérapeutiques et héréditaires.","Pathogene BRCA2-Variante im Tumor therapeutisch relevant; Keimbahnherkunft aus Tumor-only/VAF nicht beweisbar. Bestätigende konstitutionelle Diagnostik ist indiziert und zeigt hier eine Keimbahnmutation.":"Le variant pathogène de BRCA2 dans la tumeur est pertinent sur le plan thérapeutique ; l’origine germinale ne peut pas être prouvée à partir du tumor-only/de la VAF. Un test constitutionnel confirmatoire est indiqué et démontre ici une mutation germinale.","Tumor-only-Grenzen":"Limites du tumor-only","VAF-Interpretation":"Interprétation de la VAF","Keimbahnworkflow":"Parcours germinal","Welche Gene lösen besonders häufig Keimbahn-Reflexfragen aus?":"Quels gènes déclenchent le plus souvent une réflexion réflexe sur une origine germinale ?","Wie beeinflusst LOH die Tumor-VAF?":"Comment la LOH influence-t-elle la VAF tumorale ?","Wie formuliert man Keimbahnverdacht im Tumorbericht?":"Comment formuler une suspicion d’origine germinale dans un compte rendu tumoral ?","Twist: 48 % ist Hinweis, kein Beweis":"Twist : 48 % est un indice, pas une preuve","Tumor- und Keimbahnkonsequenz getrennt":"Séparer les conséquences tumorales et germinales","Referenzpfad: Tumoractionability → Keimbahnverdacht → konstitutionelle Bestätigung":"Parcours de référence : actionnabilité tumorale → suspicion germinale → confirmation constitutionnelle","ALK-IHC positiv, DNA-NGS negativ: die Fusion steckt im Transkript":"IHC ALK positive, NGS ADN négatif : la fusion se trouve dans le transcrit","DNA-NGS negativ, aber Fusionsverda…":"NGS ADN négatif, mais la suspicion de fusion persiste…","Sarkomzentrum / Molekulares Tumorboard":"Centre des sarcomes / RCP moléculaire","34-jährige Patientin mit nicht vollständig resezierbarem inflammatorischem myofibroblastärem Tumor (IMT) im kleinen Becken. ALK-IHC diffus stark positiv, DNA-basiertes Panel meldet keine ALK-Fusion.":"Patiente de 34 ans atteinte d’une tumeur myofibroblastique inflammatoire (IMT) pelvienne non complètement résécable. L’IHC ALK est diffuse et fortement positive ; un panel basé sur l’ADN ne rapporte aucune fusion ALK.","Ist die Fusionshypothese damit erledigt oder muss RNA-basiert/orthogonal weiter untersucht werden?":"L’hypothèse de fusion est-elle close ou faut-il poursuivre par une analyse basée sur l’ARN/orthogonale ?","Die systemische Behandlungsstrategie soll im Sarkomboard festgelegt werden.":"La stratégie de traitement systémique doit être définie en RCP sarcomes.","Spindelzelliger myofibroblastärer Tumor mit entzündlichem Hintergrund, passend zu IMT.":"Tumeur myofibroblastique fusocellulaire à fond inflammatoire, compatible avec une IMT.","ALK diffus zytoplasmatisch stark positiv.":"ALK diffusément et fortement positif dans le cytoplasme.","DNA-Panel":"Panel ADN","Keine Fusion detektiert; Report weist darauf hin, dass nicht alle intronischen Breakpointregionen vollständig erfasst werden.":"Aucune fusion détectée ; le compte rendu précise que toutes les régions introniques de breakpoint ne sont pas entièrement couvertes.","„Gen im Panel enthalten“ wird mit „jede mögliche Fusion erfasst“ gleichgesetzt.":"« Gène inclus dans le panel » est assimilé à « toutes les fusions possibles sont couvertes ».","IMT-morphologischer Kontext.":"Contexte morphologique d’IMT.","ALK-IHC":"IHC ALK","stark positiv.":"fortement positif.","kein Fusionscall.":"aucun call de fusion.","Ist ein exprimiertes ALK-Fusionstranskript nachweisbar?":"Un transcrit de fusion ALK exprimé est-il détectable ?","FFPE-Resektat, RNA-QC ausreichend.":"Pièce de résection FFPE, QC ARN adéquat.","DNA-Limitation":"Limitation de l’ADN","Breakpoint kann außerhalb der erfassten intronischen Regionen liegen.":"Le breakpoint peut se situer en dehors des régions introniques capturées.","Gezieltes RNA-Fusionspanel und FISH verfügbar.":"Un panel ciblé de fusions ARN et une FISH sont disponibles.","Fusionsverdacht mit geeigneter Methode klären":"Clarifier la suspicion de fusion avec une méthode adaptée","RNA-basiertes Fusionspanel weist ein exprimiertes TPM3::ALK-Fusionstranskript nach.":"Le panel de fusions basé sur l’ARN détecte un transcrit de fusion TPM3::ALK exprimé.","ALK-Break-apart-FISH ist positiv und stützt das Rearrangement, ohne den Fusionspartner auf Sequenzebene zu definieren.":"La FISH break-apart ALK est positive et confirme le réarrangement sans définir le partenaire de fusion au niveau de la séquence.","Breites DNA-Panel":"Panel ADN large","Mehr DNA-Panelbreite garantiert keine vollständige Erfassung aller Fusionsbreakpoints; die relevante methodische Lücke bleibt.":"Un panel ADN plus large ne garantit pas la couverture complète de tous les breakpoints de fusion ; la lacune méthodologique pertinente persiste.","Prätestwahrscheinlichkeit":"Probabilité pré-test","Morphologie plus starke ALK-IHC machen einen Fusionsmechanismus plausibel.":"La morphologie associée à une forte positivité ALK en IHC rend plausible un mécanisme de fusion.","Ein negatives DNA-Fusionsergebnis ist nur so vollständig wie das Assaydesign der relevanten intronischen Regionen.":"Un résultat de fusion ADN négatif n’est complet qu’à hauteur du design du test pour les régions introniques pertinentes.","Der negative DNA-Fusionscall schließt in diesem hochgradig verdächtigen Kontext ein ALK-Rearrangement nicht aus. RNA-NGS weist ein exprimiertes TPM3::ALK-Transkript nach; ALK-FISH bestätigt das Rearrangement orthogonal. Der Fall zeigt den komplementären Wert von RNA- und DNA-basierten Ansätzen.":"Le call de fusion ADN négatif n’exclut pas un réarrangement ALK dans ce contexte très suspect. Le NGS ARN détecte un transcrit TPM3::ALK exprimé ; la FISH ALK confirme le réarrangement de façon orthogonale. Le cas illustre la complémentarité des approches basées sur l’ARN et l’ADN.","Teilbefund: Bei hoher morphologisch-immunhistochemischer Prätestwahrscheinlichkeit ist ein negativer DNA-Fusionscall nicht automatisch abschließend.":"Résultat partiel : avec une forte probabilité pré-test morphologique/immunohistochimique, un call de fusion ADN négatif n’est pas automatiquement définitif.","Assaydesign/Breakpointabdeckung berücksichtigen":"Prendre en compte le design du test/la couverture des breakpoints","RNA als direkte Ebene des exprimierten Fusionstranskripts einordnen":"Positionner l’ARN comme niveau direct du transcrit de fusion exprimé","FISH als orthogonalen Rearrangementnachweis einordnen":"Positionner la FISH comme preuve orthogonale de réarrangement","Falschaussage: ALK steht im DNA-Panel, daher sind alle ALK-Fusionen ausgeschlossen":"Affirmation fausse : ALK figure dans le panel ADN, donc toutes les fusions ALK sont exclues","Optimale Lösung: Widerspruch zwischen starker Prätestwahrscheinlichkeit und negativem DNA-Fusionscall erkennen und mit RNA-basierter Fusionsdiagnostik bzw. FISH klären.":"Solution optimale : reconnaître la discordance entre une forte probabilité pré-test et un call de fusion ADN négatif, puis la résoudre par une analyse de fusion basée sur l’ARN et/ou une FISH.","Fusion":"Fusion","ALK":"ALK","DNA negativ, Biologie positiv":"ADN négatif, biologie positive","Molekularpathologie / Fusionsdiagnostik / Sarkom-MTB":"Pathologie moléculaire / Diagnostic des fusions / RCP sarcomes","Grenzen DNA-basierter Fusionsdetektion durch Breakpoint-/Intronabdeckung verstehen.":"Comprendre les limites de la détection des fusions basée sur l’ADN liées à la couverture des breakpoints/introns.","RNA-NGS als komplementären Nachweis exprimierter Fusionstranskripte nutzen.":"Utiliser le NGS ARN comme preuve complémentaire des transcrits de fusion exprimés.","Prätestwahrscheinlichkeit aus Morphologie/IHC in die Methodenauswahl integrieren.":"Intégrer la probabilité pré-test issue de la morphologie/IHC dans le choix de la méthode.","FISH als orthogonalen Rearrangementnachweis mit begrenzter Partnerinformation einordnen.":"Interpréter la FISH comme preuve orthogonale de réarrangement avec une information limitée sur le partenaire.","ALK ist immunhistochemisch leuchtend positiv, die Morphologie passt – und trotzdem sagt das DNA-Panel „keine Fusion“. Der Fall beginnt dort, wo ein Automat aufhören würde.":"ALK est fortement positif en IHC, la morphologie concorde — et pourtant le panel ADN indique « aucune fusion ». Le cas commence là où un système automatisé s’arrêterait.","34-jährige Patientin mit IMT. ALK-IHC und Morphologie sprechen stark für einen Fusionsmechanismus, das DNA-Panel bleibt negativ. Das Assaydesign deckt nicht alle möglichen intronischen Breakpoints ab.":"Patiente de 34 ans avec IMT. L’IHC ALK et la morphologie soutiennent fortement un mécanisme de fusion, mais le panel ADN est négatif. Le design du test ne couvre pas tous les breakpoints introniques possibles.","Panelinhalt ≠ vollständige Fusionsabdeckung":"Contenu du panel ≠ couverture complète des fusions","Ein Gen kann im Panel sein, ohne dass jeder relevante intronische Breakpoint erfasst wird.":"Un gène peut figurer dans le panel sans que chaque breakpoint intronique pertinent soit couvert.","Assaydesign bestimmt Sensitivität.":"Le design du test détermine la sensibilité.","RNA fragt nach dem Produkt":"L’ARN interroge le produit","Ein RNA-Fusionsassay kann das tatsächlich exprimierte Chimärtranskript nachweisen.":"Un test de fusion ARN peut détecter le transcrit chimérique effectivement exprimé.","RNA und DNA sind komplementär.":"ARN et ADN sont complémentaires.","Prätestwahrscheinlichkeit zählt":"La probabilité pré-test compte","Morphologie + ALK-IHC machen einen negativen DNA-Call unplausibel genug für Reflexdiagnostik.":"Morphologie + IHC ALK rendent un call ADN négatif suffisamment peu plausible pour justifier un test réflexe.","Diagnostik ist Bayes, nicht nur Softwareoutput.":"Le diagnostic est bayésien, pas seulement une sortie logicielle.","IMT-kompatibel":"compatible avec une IMT","diffus stark positiv":"diffusément fortement positif","kein Fusionscall; intronische Coverage limitiert":"aucun call de fusion ; couverture intronique limitée","RNA-Qualität ausreichend.":"Qualité de l’ARN adéquate.","FISH verfügbar.":"FISH disponible.","Kein Bedarf für beliebige weitere DNA-Breite, wenn die offene Frage eine Fusion ist.":"Il n’est pas nécessaire d’élargir arbitrairement l’analyse ADN lorsque la question ouverte concerne une fusion.","Wie ist der negative DNA-Fusionscall bei starker ALK-IHC und passender Morphologie zu bewerten?":"Comment interpréter le call de fusion ADN négatif avec une forte positivité ALK en IHC et une morphologie compatible ?","Er schließt eine Fusion nicht sicher aus, wenn relevante Breakpoints vom Assay nicht vollständig erfasst werden.":"Il n’exclut pas de façon fiable une fusion si les breakpoints pertinents ne sont pas entièrement couverts par le test.","ALK-Fusion ist sicher ausgeschlossen.":"La fusion ALK est définitivement exclue.","IHC ist damit automatisch falsch.":"L’IHC est donc automatiquement fausse.","Es handelt sich um Keimbahn-ALK.":"Il s’agit d’ALK germinal.","Fusionssensitivität hängt stark vom Assaydesign ab.":"La sensibilité pour les fusions dépend fortement du design du test.","Warum ist RNA-NGS hier besonders sinnvoll?":"Pourquoi le NGS ARN est-il particulièrement utile ici ?","Es kann ein exprimiertes Fusionstranskript direkt erfassen und DNA-Breakpointgrenzen umgehen.":"Il peut détecter directement un transcrit de fusion exprimé et contourner les limites liées aux breakpoints ADN.","Es ist exakt derselbe Test wie DNA-NGS.":"C’est exactement le même test que le NGS ADN.","Es misst nur Proteinexpression.":"Il mesure uniquement l’expression protéique.","Es ist primär ein Copy-number-Test.":"Il s’agit principalement d’un test de nombre de copies.","RNA liefert eine komplementäre Fusionsinformation.":"L’ARN apporte une information complémentaire sur la fusion.","Was kann ein positiver ALK-Break-apart-FISH hier sinnvoll beitragen?":"Qu’apporte utilement ici une FISH break-apart ALK positive ?","Orthogonaler Nachweis eines ALK-Rearrangements, meist ohne genaue Partner-/Transkriptinformation.":"Preuve orthogonale d’un réarrangement ALK, généralement sans information précise sur le partenaire/transcrit.","Immer vollständige Sequenz des Fusionspartners.":"Toujours la séquence complète du partenaire de fusion.","Quantitative RNA-Expression.":"Expression quantitative de l’ARN.","Keimbahnstatus.":"Statut germinal.","FISH ist schnell und orthogonal, aber informationsärmer als sequenzbasierte Partnerbestimmung.":"La FISH est rapide et orthogonale, mais moins informative que l’identification du partenaire basée sur la séquence.","RNA-NGS zeigt TPM3::ALK. Was erklärt die DNA/RNA-Diskrepanz am besten?":"Le NGS ARN montre TPM3::ALK. Qu’est-ce qui explique le mieux la discordance ADN/ARN ?","Das DNA-Assaydesign hat den relevanten Breakpoint nicht zuverlässig abgedeckt; RNA erfasst das exprimierte Transkript.":"Le design du test ADN ne couvrait pas de façon fiable le breakpoint pertinent ; l’ARN détecte le transcrit exprimé.","RNA muss falsch sein, weil DNA negativ war.":"L’ARN doit être faux puisque l’ADN était négatif.","Die Histologie ist damit irrelevant.":"L’histologie est donc sans importance.","Beide Tests sind negativ.":"Les deux tests sont négatifs.","Komplementäre Assaygrenzen erklären die Diskrepanz.":"Les limites complémentaires des tests expliquent la discordance.","Entscheiden Sie, ob und wie der Fusionsverdacht nach negativem DNA-NGS weiter abgeklärt wird.":"Décider s’il faut poursuivre l’exploration d’une suspicion de fusion après un NGS ADN négatif, et comment.","Prätestwahrscheinlichkeit aus Morphologie/IHC festhalten.":"Documenter la probabilité pré-test issue de la morphologie/IHC.","DNA-Assaydesign und intronische Abdeckung prüfen.":"Revoir le design du test ADN et la couverture intronique.","RNA-basierte Fusionsdiagnostik ergänzen.":"Ajouter une analyse de fusion basée sur l’ARN.","FISH bei Bedarf orthogonal oder schnell ergänzen.":"Ajouter une FISH de façon orthogonale ou rapide si nécessaire.","Endbefund als integrierte Fusionsevidenz formulieren.":"Formuler le compte rendu final comme une preuve intégrée de fusion.","Bei nicht verwertbarer RNA kann FISH eine praktikable orthogonale Alternative sein; für Partner-/Transkriptinformation bleibt sequenzbasierte Diagnostik überlegen.":"Si l’ARN n’est pas exploitable, la FISH peut être une alternative orthogonale pratique ; l’analyse basée sur la séquence reste supérieure pour l’information sur le partenaire/transcrit.","DNA negativ = Fusion ausgeschlossen":"ADN négatif = fusion exclue","Ignoriert intronische Assaygrenzen.":"Ignore les limites introniques du test.","Nur IHC als endgültiger Fusionsnachweis":"IHC seule comme preuve définitive de fusion","Proteinexpression ist kontextabhängig und nicht identisch mit Sequenznachweis.":"L’expression protéique dépend du contexte et n’est pas équivalente à une preuve de séquence.","Beliebig größeres DNA-Panel":"Panel ADN arbitrairement plus large","Mehr Gene lösen nicht zwingend das Breakpointproblem.":"Davantage de gènes ne résolvent pas nécessairement le problème du breakpoint.","Die Fusion war die ganze Zeit exprimiert":"La fusion était exprimée depuis le début","RNA-NGS weist TPM3::ALK nach; FISH bestätigt das ALK-Rearrangement.":"Le NGS ARN détecte TPM3::ALK ; la FISH confirme le réarrangement ALK.","Der negative DNA-Call war methodisch begrenzt, nicht biologisch endgültig.":"Le call ADN négatif était limité méthodologiquement, pas biologiquement définitif.","Komplementär getestet":"Analyses complémentaires réalisées","RNA weist exprimierte Fusion nach, FISH stützt Rearrangement.":"L’ARN détecte la fusion exprimée, la FISH étaye le réarrangement.","Methodengerechte Auflösung der Diskrepanz.":"Résolution de la discordance adaptée aux méthodes.","Nach DNA-NGS beendet":"Arrêt après le NGS ADN","Relevante Fusion bleibt unentdeckt.":"La fusion pertinente reste non détectée.","Falsch-negatives Methodensilo.":"Silo méthodologique faussement négatif.","Nur IHC akzeptiert":"IHC seule acceptée","Fusionsmechanismus nicht molekular geklärt.":"Le mécanisme de fusion n’est pas élucidé moléculairement.","Unvollständige Charakterisierung.":"Caractérisation incomplète.","hohe Fusionsprätestwahrscheinlichkeit + nichtinformativer/negativer DNA-Call":"forte probabilité pré-test de fusion + call ADN non informatif/négatif","RNA-Fusionsdiagnostik und/oder orthogonalen Assay ergänzen":"ajouter une analyse de fusion ARN et/ou un test orthogonal","Negativer DNA-Call nicht als universellen Ausschluss formulieren.":"Ne pas formuler un call ADN négatif comme une exclusion universelle.","DNA- und RNA-Fusionsdiagnostik sind komplementär.":"Les diagnostics de fusion basés sur l’ADN et l’ARN sont complémentaires.","Assaydesign ist Teil der Befundinterpretation.":"Le design du test fait partie de l’interprétation du compte rendu.","Prätestwahrscheinlichkeit entscheidet, wann ein negativer Test nicht das Ende ist.":"La probabilité pré-test détermine quand un test négatif ne constitue pas la fin de l’investigation.","Trotz negativem DNA-NGS bleibt der Fusionsverdacht hoch; RNA-NGS weist TPM3::ALK nach, FISH bestätigt das Rearrangement. DNA-Negativität war durch die Breakpointabdeckung limitiert.":"Malgré un NGS ADN négatif, la suspicion de fusion reste élevée ; le NGS ARN détecte TPM3::ALK et la FISH confirme le réarrangement. La négativité ADN était limitée par la couverture du breakpoint.","Fusionsmethodik":"Méthodologie des fusions","Assaygrenzen":"Limites du test","Wann ist FISH schneller als RNA-NGS?":"Quand la FISH est-elle plus rapide que le NGS ARN ?","Welche RNA-QC ist für FFPE kritisch?":"Quels paramètres de QC ARN sont critiques en FFPE ?","Wie sollte ein negativer DNA-Fusionsbericht Limitationen nennen?":"Comment un compte rendu de fusion ADN négatif doit-il mentionner ses limites ?","Twist: DNA-negativ trotz echter Fusion":"Twist : ADN négatif malgré une véritable fusion","RNA als komplementäre Ebene":"ARN comme niveau complémentaire","Referenzpfad: Prätestwahrscheinlichkeit → Assaydesign → RNA/FISH":"Parcours de référence : probabilité pré-test → design du test → ARN/FISH","Liquid Biopsy negativ bei Progress: kein ctDNA-Signal ist kein Tumor-Wildtyp":"Biopsie liquide négative à la progression : absence de signal ctDNA ne signifie pas tumeur wild type","Liquid Biopsy negativ bei Progress":"Biopsie liquide négative à la progression","66-jähriger Patient mit EGFR-mutiertem NSCLC und radiologischem Progress nach längerer Krankheitskontrolle. Plasma-NGS meldet „keine tumorassoziierte Variante nachweisbar“.":"Patient de 66 ans avec NSCLC muté EGFR et progression radiologique après un contrôle prolongé de la maladie. Le NGS plasmatique rapporte « aucun variant associé à la tumeur détecté ».","Darf das als fehlender Resistenzmechanismus interpretiert werden oder ist die Probe schlicht nicht informativ?":"Peut-on l’interpréter comme une absence de mécanisme de résistance, ou l’échantillon est-il simplement non informatif ?","Therapieumstellung soll im nächsten MTB erfolgen.":"Le changement thérapeutique doit être décidé lors de la prochaine RCP moléculaire.","Neue Leberläsion und progrediente mediastinale Lymphknoten.":"Nouvelle lésion hépatique et adénopathies médiastinales progressives.","Plasma":"Plasma","Keine bekannte klonale EGFR-Mutation detektierbar; Tumorfraktionsschätzer sehr niedrig/nicht informativ.":"La mutation clonale d’EGFR connue n’est pas détectable ; l’estimation de la fraction tumorale est très faible/non informative.","Ein negativer Plasma-Report wird wie ein negativer Tumorbefund gelesen.":"Un compte rendu plasmatique négatif est lu comme un résultat tumoral négatif.","Informative von nichtinformativer Negativität unterscheiden.":"Distinguer une négativité informative d’une négativité non informative.","Vorbekannter Tumor":"Tumeur connue","EGFR-aktivierende Mutation im ursprünglichen Tumor.":"Mutation activatrice d’EGFR dans la tumeur initiale.","Plasma jetzt":"Plasma actuel","Weder der bekannte Treiber noch neue Resistenzalterationen detektierbar.":"Ni le driver connu ni de nouvelles altérations de résistance ne sont détectables.","Fehlt biologisch ein Resistenzmechanismus oder fehlt im Plasma ausreichend ctDNA?":"Un mécanisme de résistance est-il biologiquement absent, ou y a-t-il simplement trop peu de ctDNA dans le plasma ?","Wenn selbst der bekannte Tumormarker nicht erscheint, ist die Negativaussage besonders fragil.":"Si même le marqueur tumoral connu n’apparaît pas, l’affirmation négative est particulièrement fragile.","Plasma technisch korrekt gewonnen.":"Plasma prélevé correctement sur le plan technique.","ctDNA":"ctDNA","sehr niedrige Tumorfraktion.":"fraction tumorale très faible.","Rebiopsie":"Rebiopsie","Leberläsion bildgesteuert zugänglich.":"Lésion hépatique accessible à une biopsie guidée par l’imagerie.","Tissue-Rebiopsie und Gewebeprofil möglich.":"Une rebiopsie tissulaire et un profilage tissulaire sont possibles.","Liquid-Biopsy-Informativität bewerten":"Évaluer le caractère informatif de la biopsie liquide","Nichtinformatives Plasma durch Tumorgewebe klären":"Clarifier un plasma non informatif à l’aide du tissu tumoral","Liquid Biopsy":"Biopsie liquide","Keine tumorassoziierte Variante nachweisbar; selbst der bekannte klonale EGFR-Treiber fehlt. Tumorfraktion sehr niedrig – negatives Ergebnis ist nicht als Tumor-Wildtyp interpretierbar.":"Aucun variant associé à la tumeur n’est détecté ; même le driver clonal d’EGFR connu est absent. La fraction tumorale est très faible — le résultat négatif ne peut pas être interprété comme une tumeur wild type.","Tissue-Rebiopsie":"Rebiopsie tissulaire","Rebiopsie der progredienten Lebermetastase bestätigt Tumor und liefert ausreichend DNA für Gewebeprofiling.":"La rebiopsie de la métastase hépatique progressive confirme la tumeur et fournit suffisamment d’ADN pour le profilage tissulaire.","Gewebeprofil":"Profil tissulaire","Im Progressionsgewebe bleibt der EGFR-Treiber nachweisbar; zusätzlich zeigt sich eine relevante MET-Amplifikation als Resistenzmechanismus.":"Le driver d’EGFR reste détectable dans le tissu de progression ; une amplification pertinente de MET apparaît en plus comme mécanisme de résistance.","Plasma-QC":"QC plasmatique","Technisch valide Probe, biologisch jedoch mit sehr niedriger/nicht informativer Tumorfraktion.":"Échantillon techniquement valide, mais biologiquement avec une fraction tumorale très faible/non informative.","Ein nichtinformatives negatives ctDNA-Ergebnis darf einen Tumorbefund nicht ersetzen.":"Un résultat ctDNA négatif non informatif ne doit pas remplacer un résultat tumoral.","Die negative Liquid Biopsy ist wegen sehr niedriger Tumorfraktion und fehlendem Nachweis sogar des bekannten Treibers nicht informativ. Geweberebiopsie ist deshalb sinnvoll und zeigt im Progressionsgewebe weiterhin die EGFR-Alteration sowie eine MET-Amplifikation. „Plasma negativ“ war kein Beweis für fehlende Tumoralterationen.":"La biopsie liquide négative n’est pas informative en raison d’une fraction tumorale très faible et de l’absence même du driver connu. Une rebiopsie tissulaire est donc pertinente et met en évidence l’altération EGFR ainsi qu’une amplification de MET dans le tissu de progression. « Plasma négatif » ne prouvait pas l’absence d’altérations tumorales.","Teilbefund: Eine negative Liquid Biopsy muss im Kontext von ctDNA/Tumorfraktion, Tumorbiologie und bekannten Markerbefunden interpretiert werden.":"Résultat partiel : une biopsie liquide négative doit être interprétée dans le contexte du ctDNA/de la fraction tumorale, de la biologie tumorale et des marqueurs connus.","Tumorfraktion/Shedding berücksichtigen":"Prendre en compte la fraction tumorale/le shedding","Fehlen des bekannten Treibers als Warnsignal für Nichtinformativität":"Absence du driver connu comme signal d’alerte de non-informativité","bei klinischer Relevanz Gewebe-Reflex erwägen":"Envisager un test réflexe tissulaire si cliniquement pertinent","Falschaussage: Plasma negativ = Tumor molekular negativ":"Affirmation fausse : plasma négatif = tumeur moléculairement négative","Optimale Lösung: negative Liquid Biopsy als möglicherweise nichtinformativ erkennen und bei zugänglichem Progressionsgewebe reflexartig tissue-basiert nachtesten.":"Solution optimale : reconnaître qu’une biopsie liquide négative peut être non informative et effectuer un test réflexe sur tissu lorsqu’un tissu de progression accessible est disponible.","Progress":"Progression","Negativ – aber ohne Tumorsignal":"Négatif — mais sans signal tumoral","Thoraxonkologie / Liquid Biopsy / MTB":"Oncologie thoracique / Biopsie liquide / RCP moléculaire","Negative ctDNA-Ergebnisse von informativen positiven Ergebnissen asymmetrisch interpretieren.":"Interpréter les résultats ctDNA négatifs de manière asymétrique par rapport aux résultats positifs informatifs.","Tumorfraktion/Shedding und Nachweis eines bekannten Tumormarkers berücksichtigen.":"Prendre en compte la fraction tumorale/le shedding et la détection d’un marqueur tumoral connu.","Bei nichtinformativem Plasma und klinischer Relevanz Gewebetestung erwägen.":"Envisager une analyse tissulaire lorsque le plasma n’est pas informatif et que la question est cliniquement pertinente.","Plasma- und Tissue-Profiling als komplementäre Strategien verstehen.":"Comprendre le profilage plasmatique et tissulaire comme des stratégies complémentaires.","Der Plasma-Report ist leer. Nicht einmal die bekannte EGFR-Mutation taucht auf. Das kann heißen „Tumor ohne Alterationen“ – oder viel wahrscheinlicher: „zu wenig Tumor-DNA im Röhrchen, um etwas sicher auszuschließen“.":"Le compte rendu plasmatique est vide. Même la mutation EGFR connue n’apparaît pas. Cela peut signifier « tumeur sans altérations » — ou, bien plus probablement, « trop peu d’ADN tumoral dans le tube pour exclure quoi que ce soit de manière fiable ».","66-jähriger Patient mit EGFR-mutiertem NSCLC im Progress. Plasma-NGS ist technisch valide, zeigt aber keine tumorassoziierten Varianten und eine sehr niedrige Tumorfraktion. Eine Leberläsion ist biopsierbar.":"Patient de 66 ans avec NSCLC muté EGFR en progression. Le NGS plasmatique est techniquement valide mais ne montre aucun variant associé à la tumeur et présente une fraction tumorale très faible. Une lésion hépatique est biopsiable.","Negativ ist asymmetrisch":"La négativité est asymétrique","Ein positiver validierter ctDNA-Befund kann sehr informativ sein; ein negativer Befund kann bei niedrigem Shedding falsch-negativ sein.":"Un résultat ctDNA positif validé peut être très informatif ; un résultat négatif peut être faussement négatif lorsque le shedding est faible.","Negativaussagen brauchen Informativitätskontext.":"Les affirmations négatives nécessitent un contexte d’informativité.","Der bekannte Treiber als interne Plausibilität":"Le driver connu comme contrôle interne de plausibilité","Wenn die etablierte EGFR-Mutation nicht detektierbar ist, spricht das gegen ausreichend Tumorsignal.":"Si la mutation EGFR connue n’est pas détectable, cela plaide contre un signal tumoral suffisant.","Vorwissen hilft, die Probe zu interpretieren.":"Les informations antérieures aident à interpréter l’échantillon.","Tissue bleibt relevant":"Le tissu reste pertinent","Bei nichtinformativer ctDNA kann Gewebe einen Resistenzmechanismus sichtbar machen.":"Lorsque le ctDNA n’est pas informatif, le tissu peut révéler un mécanisme de résistance.","Liquid Biopsy ersetzt Gewebe nicht in jeder Situation.":"La biopsie liquide ne remplace pas le tissu dans toutes les situations.","EGFR-mutierter Primärtumor":"Tumeur primitive mutée EGFR","Plasma-NGS":"NGS plasmatique","keine tumorassoziierte Variante":"aucun variant associé à la tumeur","Tumorfraktion":"Fraction tumorale","sehr niedrig / nicht informativ":"très faible / non informative","Plasma technisch korrekt.":"Plasma techniquement adéquat.","Progressionsgewebe zugänglich.":"Tissu de progression accessible.","Copy-number-/Fusionserfassung kann zusätzlich von Assay und Tumorfraktion abhängen.":"La détection du nombre de copies/des fusions peut également dépendre du test et de la fraction tumorale.","Wie ist eine negative ctDNA-Analyse bei sehr niedriger Tumorfraktion zu bewerten?":"Comment évaluer une analyse ctDNA négative avec une fraction tumorale très faible ?","Als potenziell nichtinformativ/falsch-negativ; Tumoralterationen sind damit nicht sicher ausgeschlossen.":"Comme potentiellement non informative/faussement négative ; les altérations tumorales ne sont pas exclues de façon fiable.","Der Tumor ist sicher wildtyp.":"La tumeur est définitivement wild type.","Es liegt sicher kein Tumor mehr vor.":"Il n’y a certainement plus de tumeur.","Nur Keimbahnvarianten sind möglich.":"Seuls des variants germinaux sont possibles.","ctDNA-Sensitivität hängt vom Tumorshedding und der Tumorfraktion ab.":"La sensibilité du ctDNA dépend du shedding tumoral et de la fraction tumorale.","Warum ist das Fehlen der bekannten klonalen EGFR-Mutation besonders wichtig?":"Pourquoi l’absence de la mutation clonale d’EGFR connue est-elle particulièrement importante ?","Es ist ein Warnsignal, dass im Plasma möglicherweise kaum detektierbare Tumor-DNA vorliegt.":"C’est un signal d’alerte indiquant qu’il peut y avoir très peu d’ADN tumoral détectable dans le plasma.","Der Tumor muss EGFR sicher verloren haben.":"La tumeur a forcément perdu EGFR.","Der gesamte Labortest ist technisch zwingend ungültig.":"L’ensemble du test de laboratoire est nécessairement techniquement invalide.","Es ist ohne Bedeutung.":"C’est sans importance.","Der bekannte Marker dient als biologische Plausibilitätskontrolle.":"Le marqueur connu sert de contrôle biologique de plausibilité.","Was ist bei zugänglichem Progressionsgewebe der sinnvollste nächste Schritt?":"Quelle est l’étape suivante la plus appropriée lorsque le tissu de progression est accessible ?","Geweberebiopsie/Gewebeprofiling zur Resistenzklärung.":"Rebiopsie tissulaire/profilage tissulaire pour clarifier la résistance.","Keine weitere Diagnostik.":"Aucun examen supplémentaire.","Nur dasselbe Plasmaresultat erneut interpretieren.":"Réinterpréter uniquement le même résultat plasmatique.","Methylierungsarray.":"Array de méthylation.","Nichtinformative ctDNA sollte bei relevanter Frage durch Gewebe ergänzt werden.":"Un ctDNA non informatif doit être complété par le tissu lorsque la question est cliniquement pertinente.","Gewebe zeigt den bekannten EGFR-Treiber plus MET-Amplifikation. Was lehrt die Diskrepanz?":"Le tissu montre le driver EGFR connu ainsi qu’une amplification de MET. Que nous apprend la discordance ?","Das negative Plasma war wegen geringer Tumorfraktion nicht ausreichend zum Ausschluss eines Resistenzmechanismus.":"Le résultat plasmatique négatif était insuffisant pour exclure un mécanisme de résistance en raison de la faible fraction tumorale.","Das Gewebe muss falsch sein.":"Le tissu doit être faux.","Liquid Biopsy ist grundsätzlich nutzlos.":"La biopsie liquide est globalement inutile.","Beide Befunde bedeuten dasselbe.":"Les deux résultats signifient la même chose.","Liquid Biopsy ist wertvoll, aber negative Ergebnisse sind kontextabhängig.":"La biopsie liquide est utile, mais les résultats négatifs dépendent du contexte.","Entscheiden Sie, ob die negative Liquid Biopsy die Resistenzdiagnostik beendet oder eine Tissue-Reflexstrategie nötig ist.":"Décider si la biopsie liquide négative met fin à l’analyse de résistance ou nécessite une stratégie réflexe tissulaire.","Plasma-QC und Tumorfraktion bewerten.":"Évaluer le QC plasmatique et la fraction tumorale.","Bekannten Tumormarker als Plausibilitätsanker nutzen.":"Utiliser le marqueur tumoral connu comme ancrage de plausibilité.","Negativbefund nicht überinterpretieren.":"Ne pas surinterpréter le résultat négatif.","Bei zugänglichem Progressionsgewebe Gewebetestung ergänzen.":"Ajouter une analyse tissulaire lorsque le tissu de progression est accessible.","Diskrepanz integriert berichten.":"Rendre compte de la discordance de manière intégrée.","Wenn Gewebe nicht zugänglich ist, kann eine erneute Plasmaanalyse zu einem biologisch günstigeren Zeitpunkt oder eine alternative Flüssigkeit je nach Entität erwogen werden; das ersetzt keine pauschale Garantie.":"Si le tissu n’est pas accessible, une nouvelle analyse plasmatique à un moment biologiquement plus favorable ou un autre liquide peut être envisagé selon l’entité ; cela ne constitue pas une garantie universelle.","Plasma negativ = Tumor negativ":"Plasma négatif = tumeur négative","Ignoriert falsch-negative Ergebnisse bei niedrigem Shedding.":"Ignore les faux négatifs en cas de faible shedding.","Liquid Biopsy generell verwerfen":"Rejeter globalement la biopsie liquide","Positive/informative Ergebnisse können klinisch sehr nützlich sein.":"Les résultats positifs/informatifs peuvent être très utiles cliniquement.","Tumorfraktion ignorieren":"Ignorer la fraction tumorale","Entfernt den wichtigsten Informativitätsparameter.":"Écarte le paramètre d’informativité le plus important.","Das Gewebe findet, was das Plasma nicht sehen konnte":"Le tissu trouve ce que le plasma ne pouvait pas voir","Tissue-Profiling zeigt den bekannten Treiber und eine MET-Amplifikation.":"Le profilage tissulaire montre le driver connu et une amplification de MET.","Die diagnostische Frage war nicht „war der Plasmatest technisch okay?“, sondern „war er biologisch informativ genug, um etwas auszuschließen?“":"La question diagnostique n’était pas « le test plasmatique était-il techniquement correct ? », mais « était-il biologiquement assez informatif pour exclure quelque chose ? ».","Nichtinformativ erkannt":"Résultat non informatif reconnu","Tissue-Reflex deckt Resistenzmechanismus auf.":"Le réflexe tissulaire révèle un mécanisme de résistance.","Korrekte Liquid-Biopsy-Logik.":"Logique correcte de biopsie liquide.","Nach negativem Plasma beendet":"Arrêt après plasma négatif","Resistenzmechanismus bleibt unentdeckt.":"Le mécanisme de résistance reste non détecté.","Falsch-negatives Overconfidence.":"Excès de confiance dans un faux négatif.","Liquid Biopsy generell abgelehnt":"Biopsie liquide rejetée globalement","Methodennutzen wird unnötig negiert.":"L’utilité de la méthode est inutilement niée.","Zu pauschal.":"Trop catégorique.","negatives ctDNA + niedrige Tumorfraktion/fehlender bekannter Treiber":"ctDNA négatif + faible fraction tumorale/driver connu absent","Ergebnis als nichtinformativ kennzeichnen und Gewebe erwägen":"qualifier le résultat de non informatif et envisager le tissu","Keine sichere Negativaussage über Tumorgenom.":"Aucune affirmation négative fiable sur le génome tumoral.","Negative ctDNA-Befunde sind kontextabhängig.":"Les résultats ctDNA négatifs dépendent du contexte.","Tumorfraktion und Shedding gehören zur Interpretation.":"La fraction tumorale et le shedding font partie de l’interprétation.","Plasma und Gewebe ergänzen sich.":"Plasma et tissu sont complémentaires.","Negative Liquid Biopsy bei sehr niedriger Tumorfraktion und fehlendem bekanntem Treiber ist nicht ausreichend zum Ausschluss von Resistenzalterationen; Gewebe-Reflex zeigt hier MET-Amplifikation.":"Une biopsie liquide négative avec une fraction tumorale très faible et l’absence du driver connu ne suffit pas à exclure des altérations de résistance ; le réflexe tissulaire révèle ici une amplification de MET.","ctDNA-Informativität":"Informativité du ctDNA","Reflex-Tissue":"Réflexe tissulaire","Negativbefund":"Résultat négatif","Welche Tumorlokalisationen sheddern schlecht?":"Quels sites tumoraux ont un faible shedding ?","Wann ist Plasma besonders sinnvoll?":"Quand le plasma est-il particulièrement utile ?","Wie sollte Tumorfraktion im Report kommuniziert werden?":"Comment la fraction tumorale doit-elle être communiquée dans le compte rendu ?","Twist: technisch negatives Plasma, biologisch nichtinformativ":"Twist : plasma techniquement négatif, biologiquement non informatif","Bekannter Treiber als Plausibilitätsanker":"Driver connu comme ancrage de plausibilité","Referenzpfad: Tumorfraktion → Negativität begrenzen → Tissue-Reflex":"Parcours de référence : fraction tumorale → limiter l’interprétation négative → réflexe tissulaire","NPM1-MRD: diagnostisches NGS negativ, gezielte PCR noch positiv":"MRD NPM1 : NGS diagnostique négatif, PCR ciblée toujours positive","qPCR/dPCR für MRD statt breites Pa…":"qPCR/dPCR pour la MRD plutôt qu’un panel large…","Hämatologie / Molekulares Tumorboard":"Hématologie / RCP moléculaire","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung in morphologischer kompletter Remission. Ein breites myeloisches NGS-Panel ist „negativ“.":"Patiente de 52 ans avec AML mutée NPM1 après consolidation, en rémission complète morphologique. Un panel NGS myéloïde large est « négatif ».","Reicht das breite Panel für die MRD-Beurteilung oder braucht es die hochsensitive, zielgerichtete NPM1-Methode?":"Le panel large suffit-il pour l’évaluation de la MRD ou faut-il la méthode NPM1 ciblée hautement sensible ?","MRD-Status soll vor der nächsten risikoadaptierten Entscheidung vorliegen.":"Le statut MRD doit être disponible avant la prochaine décision adaptée au risque.","Diagnosemarker":"Marqueur diagnostique","NPM1-Mutation bei Erstdiagnose eindeutig dokumentiert.":"Mutation NPM1 clairement documentée au diagnostic initial.","<5 % Blasten, komplette morphologische Remission.":"<5 % de blastes, rémission complète morphologique.","Breites NGS":"NGS large","Keine pathogene Variante oberhalb der diagnostischen Reporting-Grenzen.":"Aucun variant pathogène au-dessus des seuils diagnostiques de rendu.","Breite wird mit Sensitivität verwechselt.":"La largeur est confondue avec la sensibilité.","morphologisch in Remission.":"en rémission morphologique.","Zielmarker":"Marqueur cible","NPM1 patientenspezifisch bekannt.":"Marqueur NPM1 spécifique de la patiente connu.","Ist unterhalb der Sensitivität eines diagnostischen Panels noch messbare Resterkrankung nachweisbar?":"Une maladie résiduelle mesurable peut-elle encore être détectée sous la sensibilité d’un panel diagnostique ?","MRD ist eine andere analytische Aufgabe als initiale Genotypisierung.":"La MRD est une tâche analytique différente du génotypage initial.","Knochenmark, ausreichende Nukleinsäurequalität.":"Moelle osseuse, qualité des acides nucléiques adéquate.","bekannter NPM1-Marker.":"marqueur NPM1 connu.","Methodenwahl":"Choix de la méthode","gezielte qPCR/dPCR-artige MRD-Methode vs. breites Panel.":"méthode MRD ciblée de type qPCR/dPCR versus panel large.","Beide technisch verfügbar; entscheidend ist die validierte Sensitivität für die Fragestellung.":"Les deux sont techniquement disponibles ; le facteur décisif est la sensibilité validée pour la question clinique.","Sensitive zielgerichtete MRD-Methode":"Méthode MRD ciblée sensible","Zielgerichtete MRD-PCR":"PCR MRD ciblée","Patientenspezifischer NPM1-Marker bleibt in niedriger Menge reproduzierbar positiv; messbare Resterkrankung ist trotz morphologischer Remission nachweisbar.":"Le marqueur NPM1 spécifique de la patiente reste reproductiblement positif à faible niveau ; une maladie résiduelle mesurable est détectable malgré la rémission morphologique.","Breites myeloisches Panel":"Panel myéloïde large","Keine Variante oberhalb der diagnostischen Panelgrenzen; dieser Negativbefund erreicht nicht automatisch die für NPM1-MRD erforderliche Sensitivität.":"Aucun variant au-dessus des seuils du panel diagnostique ; ce résultat négatif n’atteint pas automatiquement la sensibilité requise pour la MRD NPM1.","Komplette morphologische Remission.":"Rémission complète morphologique.","Diagnostische Panelbreite und MRD-Sensitivität sind unterschiedliche Leistungsmerkmale.":"La largeur d’un panel diagnostique et la sensibilité MRD sont des caractéristiques de performance différentes.","Das negative diagnostische NGS-Panel beweist keine molekulare MRD-Negativität. Da ein geeigneter NPM1-Zielmarker bekannt ist, ist eine validierte hochsensitive zielgerichtete qPCR/dPCR-basierte Strategie angemessen. Diese bleibt niedrig positiv und zeigt messbare Resterkrankung trotz morphologischer Remission.":"Un panel NGS diagnostique négatif ne prouve pas une MRD moléculaire négative. Puisqu’un marqueur cible NPM1 approprié est connu, une stratégie ciblée validée hautement sensible basée sur qPCR/dPCR est adaptée. Elle reste faiblement positive et démontre une maladie résiduelle mesurable malgré la rémission morphologique.","Teilbefund: Für MRD muss die Methode zur erwarteten sehr niedrigen Krankheitslast und zum bekannten Zielmarker passen; ein breites Diagnostikpanel ist nicht automatisch sensitiv genug.":"Résultat partiel : pour la MRD, la méthode doit être adaptée à la très faible charge de maladie attendue et au marqueur cible connu ; un panel diagnostique large n’est pas automatiquement assez sensible.","Diagnostik vs. MRD als unterschiedliche Testzwecke trennen":"Séparer le diagnostic et la MRD comme finalités d’analyse différentes","assayvalidierte Sensitivität berücksichtigen":"Prendre en compte la sensibilité validée du test","stabilen geeigneten Zielmarker nutzen":"Utiliser un marqueur cible stable et approprié","Falschaussage: breiteres Panel ist für MRD automatisch besser":"Affirmation fausse : un panel plus large est automatiquement meilleur pour la MRD","Optimale Lösung: bekannten NPM1-Marker mit validierter hochsensitiver Zielmethode verfolgen; diagnostisches NGS negativ nicht mit MRD-negativ gleichsetzen.":"Solution optimale : suivre le marqueur NPM1 connu avec une méthode ciblée validée hautement sensible ; ne pas assimiler un NGS diagnostique négatif à une MRD négative.","MRD":"MRD","NPM1":"NPM1","qPCR":"qPCR","dPCR":"dPCR","Breit negativ, hochsensitiv positiv":"Négatif en panel large, positif en méthode hautement sensible","Hämatologie / molekulare MRD-Diagnostik":"Hématologie / diagnostic moléculaire de la MRD","Diagnostisches NGS von MRD-Methodik unterscheiden.":"Distinguer le NGS diagnostique de la méthodologie MRD.","Bei bekanntem geeignetem Marker eine validierte hochsensitive Zielmethode wählen.":"Lorsqu’un marqueur connu approprié existe, choisir une méthode ciblée validée hautement sensible.","Analytische Sensitivität passend zur klinischen Fragestellung bewerten.":"Évaluer une sensibilité analytique adaptée à la question clinique.","Morphologische Remission nicht mit molekularer MRD-Negativität gleichsetzen.":"Ne pas assimiler rémission morphologique et MRD moléculaire négative.","Im Abschlussbefund steht zweimal „negativ“: Morphologie unauffällig, breites NGS ohne Treffer. Die NPM1-MRD-PCR sagt trotzdem positiv. Der Widerspruch ist nur scheinbar – die Methoden fragen auf völlig unterschiedlichen Tiefen.":"Le compte rendu final dit deux fois « négatif » : morphologie sans anomalie, NGS large sans détection. Pourtant, la PCR MRD NPM1 est positive. La contradiction n’est qu’apparente : les méthodes interrogent la maladie à des profondeurs totalement différentes.","52-jährige Patientin mit NPM1-mutierter AML nach Konsolidierung. Morphologisch komplette Remission und diagnostisches Panel ohne Varianten oberhalb seiner Reporting-Grenzen. Für die MRD-Frage steht ein bekannter NPM1-Zielmarker zur Verfügung.":"Patiente de 52 ans avec AML mutée NPM1 après consolidation. Rémission complète morphologique et panel diagnostique sans variant au-dessus de ses seuils de rendu. Un marqueur cible NPM1 connu est disponible pour la question de MRD.","Breite ist nicht Tiefe":"Largeur n’est pas profondeur","Ein diagnostisches Panel kann viele Gene erfassen, aber nicht dieselbe Nachweisgrenze wie eine fokussierte MRD-Methode erreichen.":"Un panel diagnostique peut couvrir de nombreux gènes sans atteindre la même limite de détection qu’une méthode MRD focalisée.","Methodenauswahl folgt der Frage.":"Le choix de la méthode suit la question.","Bekannter Marker ist ein Vorteil":"Un marqueur connu est un avantage","NPM1 ist bei Diagnose dokumentiert und gezielt verfolgbar.":"NPM1 est documenté au diagnostic et peut être suivi spécifiquement.","MRD kann patientenspezifisch hochsensitiv sein.":"La MRD peut être hautement sensible et spécifique du patient.","Remission hat Ebenen":"La rémission a plusieurs niveaux","Morphologische CR und molekulare MRD sind nicht synonym.":"RC morphologique et MRD moléculaire ne sont pas synonymes.","Mehrere Ebenen der Krankheitslast koexistieren.":"Plusieurs niveaux de charge de maladie coexistent.","NPM1-mutierte AML":"AML mutée NPM1","komplette Remission":"rémission complète","kein Call oberhalb diagnostischer Reporting-Grenze":"aucun call au-dessus du seuil diagnostique de rendu","Knochenmarkmaterial ausreichend.":"Matériel médullaire adéquat.","Zielmarker bekannt.":"Marqueur cible connu.","Die konkrete Nachweisgrenze ist labor- und assayvalidiert; keine universelle Prozentzahl wird vorausgesetzt.":"La limite exacte de détection est validée par le laboratoire et le test ; aucun pourcentage universel n’est supposé.","Welche Methode passt am besten zur MRD-Frage bei bekanntem NPM1-Zielmarker?":"Quelle méthode convient le mieux à la question de MRD lorsqu’un marqueur cible NPM1 connu est disponible ?","Validierte hochsensitive zielgerichtete qPCR/dPCR-basierte MRD-Methode.":"Méthode MRD ciblée validée hautement sensible basée sur qPCR/dPCR.","Nur ein möglichst breites diagnostisches Panel.":"Uniquement le panel diagnostique le plus large possible.","Nur HE-Morphologie.":"Morphologie HE uniquement.","MRD verlangt hohe Sensitivität für einen geeigneten Zielmarker.":"La MRD nécessite une forte sensibilité pour un marqueur cible approprié.","Was bedeutet ein negatives diagnostisches NGS-Panel hier?":"Que signifie ici un panel NGS diagnostique négatif ?","Keine Variante oberhalb seiner validierten Grenzen; molekulare MRD unterhalb dieser Grenzen kann bestehen.":"Aucun variant au-dessus de ses limites validées ; une MRD moléculaire sous ces limites peut néanmoins persister.","Absolut keine Leukämiezelle vorhanden.":"Il n’existe absolument aucune cellule leucémique.","MRD ist sicher negativ, unabhängig vom Assay.":"La MRD est définitivement négative quel que soit le test.","Die ursprüngliche AML-Diagnose war falsch.":"Le diagnostic initial d’AML était faux.","Negativität gilt nur innerhalb der analytischen Leistungsfähigkeit.":"La négativité ne vaut que dans les limites des performances analytiques.","Morphologische komplette Remission und MRD-positiv – ist das möglich?":"Rémission complète morphologique et MRD positive : est-ce possible ?","Ja; MRD-Methoden erfassen deutlich niedrigere Krankheitslast als Morphologie.":"Oui ; les méthodes MRD détectent des charges de maladie bien plus faibles que la morphologie.","Nein, die Befunde schließen sich aus.":"Non, les résultats s’excluent mutuellement.","MRD ist immer Artefakt.":"La MRD est toujours un artefact.","MRD hat keine klinische Bedeutung.":"La MRD n’a aucune signification clinique.","Die Ebenen messen unterschiedliche Sensitivitätsbereiche.":"Les niveaux mesurent des plages de sensibilité différentes.","Die NPM1-MRD-Methode ist reproduzierbar niedrig positiv. Wie lautet die Kernaussage?":"La méthode MRD NPM1 est reproductiblement faiblement positive. Quelle est la conclusion principale ?","Molekulare MRD ist nachweisbar, obwohl Morphologie und diagnostisches Panel negativ sind.":"Une MRD moléculaire est détectable malgré une morphologie et un panel diagnostique négatifs.","Das breite Panel überschreibt die MRD-PCR.":"Le panel large prévaut sur la PCR MRD.","CR bedeutet zwingend null Resterkrankung.":"RC signifie nécessairement absence totale de maladie résiduelle.","Der Zielmarker darf nicht verwendet werden.":"Le marqueur cible ne doit pas être utilisé.","Die gezielte validierte MRD-Methode ist für diese Frage geeigneter.":"La méthode MRD ciblée validée est mieux adaptée à cette question.","Wählen und begründen Sie die Methode zur molekularen MRD-Beurteilung.":"Choisir et justifier la méthode d’évaluation de la MRD moléculaire.","Klinische Frage als MRD statt Diagnose definieren.":"Définir la question clinique comme une question de MRD et non de diagnostic.","Geeigneten bekannten Zielmarker identifizieren.":"Identifier un marqueur cible connu approprié.","Assayvalidierte Sensitivität berücksichtigen.":"Prendre en compte la sensibilité validée du test.","Zielgerichtete MRD-PCR verwenden.":"Utiliser une PCR MRD ciblée.","Ergebnis getrennt von Morphologie und diagnostischem Panel berichten.":"Rapporter le résultat séparément de la morphologie et du panel diagnostique.","NGS-basierte MRD kann in validierten spezialisierten Ansätzen sinnvoll sein; der Fall richtet sich gegen die unkritische Verwendung eines routinemäßigen diagnostischen Breitenpanels als MRD-Ersatz.":"La MRD basée sur le NGS peut être utile dans des approches spécialisées validées ; le cas s’oppose à l’utilisation non critique d’un panel diagnostique large de routine comme substitut à l’analyse de MRD.","Breiter = sensitiver":"Plus large = plus sensible","Verwechselt Panelumfang mit Nachweisgrenze.":"Confond l’étendue du panel avec la limite de détection.","Morphologische CR = MRD-negativ":"RC morphologique = MRD négative","Ignoriert unterschiedliche Sensitivitätsebenen.":"Ignore les différents niveaux de sensibilité.","Jede Persistenzmutation als MRD":"Toute mutation persistante considérée comme MRD","Nicht jeder Marker ist gleich geeignet; clonal hematopoiesis kann einzelne Gene persistieren lassen.":"Tous les marqueurs ne sont pas également adaptés ; l’hématopoïèse clonale peut entraîner la persistance de certains gènes.","Die Resterkrankung liegt unter der Paneloberfläche":"La maladie résiduelle se situe sous la surface du panel","Gezielte NPM1-MRD bleibt reproduzierbar positiv.":"La MRD NPM1 ciblée reste reproductiblement positive.","Der Fall zeigt, warum Testzweck und Sensitivität wichtiger sind als maximale Genbreite.":"Le cas montre pourquoi la finalité du test et la sensibilité comptent davantage que la largeur génétique maximale.","Zielgerichtete MRD":"MRD ciblée","NPM1-MRD korrekt nachgewiesen.":"MRD NPM1 correctement détectée.","Fragestellungsgerechte Methodik.":"Méthodologie adaptée à la question.","Nur breites Panel":"Panel large uniquement","Niedrige Resterkrankung wird fälschlich als negativ interpretiert.":"Une maladie résiduelle de faible niveau est interprétée à tort comme négative.","Sensitivitätsproblem.":"Problème de sensibilité.","Nur Morphologie":"Morphologie uniquement","Molekulare Resterkrankung bleibt unsichtbar.":"La maladie résiduelle moléculaire reste invisible.","Unvollständig.":"Incomplet.","bekannter geeigneter MRD-Marker":"marqueur MRD connu et approprié","validierte hochsensitive Zielmethode nutzen":"utiliser une méthode ciblée validée hautement sensible","Diagnostische Panelnegativität nicht als MRD-Negativität umdeuten.":"Ne pas réinterpréter la négativité du panel diagnostique comme une MRD négative.","MRD ist eine eigene analytische Aufgabe.":"La MRD est une tâche analytique à part entière.","Breite und Sensitivität sind unabhängige Dimensionen.":"Largeur et sensibilité sont des dimensions indépendantes.","Der beste Test ist der, dessen validierte Leistung zur klinischen Frage passt.":"Le meilleur test est celui dont les performances validées correspondent à la question clinique.","Bei bekannter NPM1-mutierter AML ist die validierte zielgerichtete MRD-PCR der geeignete Test; diagnostisches NGS negativ schließt niedriggradige molekulare Resterkrankung nicht aus.":"Dans une AML connue mutée NPM1, la PCR MRD ciblée validée est le test approprié ; un NGS diagnostique négatif n’exclut pas une maladie résiduelle moléculaire de faible niveau.","MRD-Methodenwahl":"Choix de la méthode MRD","Sensitivität":"Sensibilité","Befundebenen":"Niveaux de résultats","Welche Mutationen sind für AML-MRD problematisch?":"Quelles mutations sont problématiques pour la MRD dans l’AML ?","Wann ist dPCR gegenüber qPCR sinnvoll?":"Quand la dPCR est-elle utile par rapport à la qPCR ?","Welche Rolle hat NGS-basierte MRD?":"Quel est le rôle de la MRD basée sur le NGS ?","Twist: diagnostisches NGS negativ, MRD-PCR positiv":"Twist : NGS diagnostique négatif, PCR MRD positive","Breite ≠ Sensitivität":"Largeur ≠ sensibilité","Referenzpfad: Zielmarker → validierte MRD-Methode → getrennte Interpretation":"Parcours de référence : marqueur cible → méthode MRD validée → interprétation séparée","MGMT-Frage im gesicherten Glioblastom: lokaler Marker statt Classifier-Overkill":"Question MGMT dans un glioblastome confirmé : marqueur local plutôt qu'un recours excessif au classifieur","Bisulfit-PCR vs. Methylierungsarra…":"PCR au bisulfite vs puce de méthylation…","69-jähriger Patient mit histologisch und molekular eindeutig klassifiziertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung wird der MGMT-Promotor-Methylierungsstatus benötigt.":"Patient de 69 ans présentant un glioblastome classé sans ambiguïté sur les plans histologique et moléculaire, IDH sauvage. Le statut de méthylation du promoteur de MGMT est requis pour la planification thérapeutique.","Braucht dieser Fall einen genomeweiten Methylierungsclassifier oder eine validierte zielgerichtete MGMT-Methylierungsanalyse?":"Ce cas nécessite-t-il un classifieur de méthylation pangénomique ou une analyse ciblée et validée de la méthylation de MGMT ?","Adjuvante Therapieplanung steht unmittelbar an.":"La planification du traitement adjuvant est imminente.","Glioblastom, IDH-Wildtyp, integriert gesichert; keine offene Entitätsfrage.":"Glioblastome, IDH sauvage, diagnostic intégré établi ; aucune question d'entité non résolue.","Offene Biomarkerfrage":"Question de biomarqueur ouverte","MGMT-Promotor-Methylierung.":"Méthylation du promoteur de MGMT.","Ein technologisch umfassenderes Methylierungsarray wird automatisch als „besser“ angesehen.":"Une puce de méthylation technologiquement plus exhaustive est automatiquement considérée comme « meilleure ».","Testscope an die konkrete klinische Frage und lokale Validierung koppeln.":"Adapter le périmètre du test à la question clinique précise et à la validation locale.","Hochgradiges diffuses Astrozytom mit Nekrosen und mikrovaskulärer Proliferation.":"Astrocytome diffus de haut grade avec nécrose et prolifération microvasculaire.","IDH-Wildtyp; integrierte Diagnose steht.":"IDH sauvage ; diagnostic intégré établi.","MGMT-Promotor-Methylierungsstatus.":"Statut de méthylation du promoteur de MGMT.","Klassifikation und prädiktiver Einzelmarker sind zwei verschiedene Aufgaben.":"La classification et un biomarqueur prédictif unique sont deux tâches différentes.","FFPE-Resektat, ausreichender Tumoranteil.":"Pièce de résection FFPE, cellularité tumorale suffisante.","für beide Verfahren ausreichend.":"suffisant pour les deux méthodes.","Lokale Validierung":"Validation locale","Bisulfit-basierte Zielmethode ist für MGMT klinisch validiert; das Array wird im Labor primär für CNS-Klassifikation eingesetzt.":"La méthode ciblée au bisulfite est cliniquement validée pour MGMT ; dans ce laboratoire, la puce est principalement utilisée pour la classification des tumeurs du SNC.","Array wäre teurer/langsamer und beantwortet hier keine offene Klassifikationsfrage.":"La puce serait plus coûteuse/plus lente et ne répondrait ici à aucune question de classification non résolue.","Zielgerichtete validierte MGMT-Methylierungsanalyse":"Analyse ciblée et validée de la méthylation de MGMT","Zielgerichtete Bisulfit-Methylierungsanalyse":"Analyse ciblée de méthylation au bisulfite","MGMT-Promotor-Methylierung ist mit der lokal validierten zielgerichteten Methode nachweisbar und für die konkrete prädiktive Fragestellung berichtbar.":"La méthylation du promoteur de MGMT est détectable par la méthode ciblée validée localement et peut être rendue pour la question prédictive précise.","CNS-Methylierungsclassifier":"Classifieur de méthylation du SNC","Das genomeweite Profil bestätigt die bereits gesicherte Tumorklasse, ist in diesem Labor aber nicht als Ersatz für die klinische MGMT-Einzelmarkerbestimmung validiert.":"Le profil pangénomique confirme la classe tumorale déjà établie, mais dans ce laboratoire il n'est pas validé comme substitut du dosage clinique de MGMT en marqueur unique.","Zusätzliche Sequenzierungsbreite beantwortet die epigenetische MGMT-Frage nicht.":"Une plus grande largeur de séquençage ne répond pas à la question épigénétique MGMT.","Tumorentität bereits integriert gesichert.":"Entité tumorale déjà établie par le diagnostic intégré.","Mehr Omik ist nicht automatisch die passendere Methode; Scope und Validierung müssen zur Frage passen.":"Plus d'omique ne signifie pas automatiquement une méthode plus appropriée ; le périmètre et la validation doivent correspondre à la question.","Da die Tumorentität bereits sicher klassifiziert ist und die konkrete Frage MGMT-Promotor-Methylierung lautet, ist die lokal validierte zielgerichtete Bisulfitmethode die passende Untersuchung. Ein genomeweiter Methylierungsclassifier wäre für eine offene Entitätsfrage sinnvoll, ist hier aber unnötig und im lokalen Workflow kein validierter Ersatz für den prädiktiven Einzelmarker.":"Puisque l'entité tumorale est déjà classée avec certitude et que la question précise porte sur la méthylation du promoteur de MGMT, la méthode ciblée au bisulfite validée localement est l'examen approprié. Un classifieur de méthylation pangénomique serait utile si l'entité restait indéterminée, mais il est inutile ici et ne constitue pas, dans le workflow local, un substitut validé au biomarqueur prédictif unique.","Teilbefund: Lokaler prädiktiver Marker und globale epigenetische Klassifikation sind unterschiedliche diagnostische Aufgaben.":"Résultat partiel : un biomarqueur prédictif local et une classification épigénétique globale sont des tâches diagnostiques différentes.","Fragestellung vor Technologie wählen":"Choisir la question avant la technologie","lokale klinische Validierung berücksichtigen":"tenir compte de la validation clinique locale","Classifier für Klassifikation, nicht automatisch für jeden Methylierungsmarker":"classifieur pour la classification, pas automatiquement pour chaque biomarqueur de méthylation","Falschaussage: genomeweit ist immer klinisch besser":"Affirmation erronée : le pangénomique est toujours meilleur sur le plan clinique","Optimale Lösung: gesicherte Diagnose respektieren und die offene MGMT-Frage mit der dafür validierten zielgerichteten Methylierungsmethode beantworten.":"Solution optimale : respecter le diagnostic établi et répondre à la question MGMT ouverte avec la méthode ciblée de méthylation validée à cet effet.","MGMT":"MGMT","Bisulfit":"Bisulfite","CNS":"SNC","Nicht jedes Methylom braucht ein Methylom":"Toute question de méthylation ne nécessite pas un méthylome","Neuropathologie / Methodenauswahl":"Neuropathologie / choix de la méthode","Zielgerichtete Methylierungsanalyse von genomeweiter Klassifikation unterscheiden.":"Distinguer l'analyse ciblée de méthylation de la classification pangénomique.","Methodenumfang nicht mit klinischer Eignung gleichsetzen.":"Ne pas confondre largeur méthodologique et pertinence clinique.","Lokale Validierung und Intended Use in die Auswahl integrieren.":"Intégrer la validation locale et l'usage prévu dans le choix du test.","Bei bereits gesicherter Entität unnötige Classifier-Diagnostik vermeiden.":"Éviter le recours inutile au classifieur lorsque l'entité est déjà établie.","Die Diagnose steht. Die einzige offene Frage lautet MGMT. Trotzdem liegt im Warenkorb ein genomeweites Methylierungsarray – weil „mehr Daten“ intuitiv nach „mehr Sicherheit“ klingt.":"Le diagnostic est établi. La seule question ouverte est MGMT. Pourtant, une puce de méthylation pangénomique se trouve dans le panier, car intuitivement « plus de données » semble signifier « plus de certitude ».","69-jähriger Patient mit integriert gesichertem Glioblastom, IDH-Wildtyp. Für die Therapieplanung ist ausschließlich der MGMT-Promotor-Methylierungsstatus offen. Das Labor hat dafür eine validierte zielgerichtete Bisulfitmethode; der CNS-Classifier ist für Entitätsklassifikation validiert.":"Patient de 69 ans avec glioblastome confirmé par diagnostic intégré, IDH sauvage. Pour la planification thérapeutique, seul le statut de méthylation du promoteur de MGMT reste à déterminer. Le laboratoire dispose pour cela d'une méthode ciblée au bisulfite validée ; le classifieur du SNC est validé pour la classification des entités.","Frage vor Plattform":"La question avant la plateforme","MGMT-Status ist eine fokale Biomarkerfrage, Tumorklassifikation eine globale Musterfrage.":"Le statut MGMT est une question de biomarqueur focal ; la classification tumorale est une question de profil global.","Testscope muss die Fragestellung spiegeln.":"Le périmètre du test doit refléter la question.","Validierung schlägt Prestige":"La validation prime sur le prestige","Ein technisch komplexeres Verfahren ist nicht automatisch für jeden klinischen Output validiert.":"Une méthode techniquement plus complexe n'est pas automatiquement validée pour chaque résultat clinique.","Intended Use ist Teil der Methode.":"L'usage prévu fait partie de la méthode.","Materialökonomie":"Économie de matériel","Unnötige Omik verbraucht Zeit, Geld und ggf. Material.":"Une omique inutile consomme du temps, de l'argent et potentiellement du matériel.","Effizienz ist diagnostische Qualität.":"L'efficience fait partie de la qualité diagnostique.","Entitätsdiagnose":"Diagnostic d'entité","bereits integriert gesichert":"déjà établi par diagnostic intégré","Lokaler Workflow":"Workflow local","zielgerichtete Bisulfitmethode klinisch validiert":"méthode ciblée au bisulfite cliniquement validée","Ausreichendes Material.":"Matériel suffisant.","Kein Klassifikationsproblem.":"Aucun problème de classification.","Das Array ist lokal nicht als direkter Ersatz für die MGMT-Einzelmarkerfreigabe validiert.":"La puce n'est pas validée localement comme substitut direct au compte rendu MGMT en marqueur unique.","Welche Methode passt zur isolierten MGMT-Frage bei bereits gesicherter Glioblastomdiagnose am besten?":"Quelle méthode est la mieux adaptée à la question MGMT isolée lorsque le diagnostic de glioblastome est déjà établi ?","Die dafür lokal validierte zielgerichtete Bisulfit-Methylierungsanalyse.":"L'analyse ciblée de méthylation au bisulfite validée localement.","Zwingend genomeweiter Classifier.":"Classifieur pangénomique obligatoire.","Breites DNA-NGS.":"NGS ADN large.","FISH.":"FISH.","Der klinische Output ist ein definierter lokaler Methylierungsmarker.":"Le résultat clinique attendu est un biomarqueur local de méthylation défini.","Wann wäre der CNS-Methylierungsclassifier besonders sinnvoll?":"Quand le classifieur de méthylation du SNC est-il particulièrement utile ?","Bei diagnostisch unklarer Tumorentität, wenn ein genomeweites Muster die integrierte Klassifikation unterstützen kann.":"Pour une entité tumorale diagnostiquement incertaine, lorsqu'un profil pangénomique peut soutenir la classification intégrée.","Bei jedem MGMT-Auftrag unabhängig von Diagnose.":"Pour toute demande MGMT, quel que soit le diagnostic.","Zur AML-MRD.":"Pour la MRD dans la LAM.","Für Keimbahndiagnostik.":"Pour le diagnostic constitutionnel.","Classifier und Einzelmarker haben unterschiedliche Intended Uses.":"Le classifieur et le biomarqueur unique ont des usages prévus différents.","Warum darf ein Array nicht automatisch den lokal validierten MGMT-Test ersetzen?":"Pourquoi une puce ne doit-elle pas remplacer automatiquement le test MGMT validé localement ?","Weil klinische Freigabe die validierte Performance für genau diesen Output voraussetzt.":"Parce que le rendu clinique exige des performances validées pour ce résultat précis.","Weil Arrays grundsätzlich ungenau sind.":"Parce que les puces sont intrinsèquement imprécises.","Weil Arrays keine DNA messen.":"Parce que les puces ne mesurent pas l'ADN.","Weil Methylierungsarrays nie diagnostisch genutzt werden.":"Parce que les puces de méthylation ne sont jamais utilisées à des fins diagnostiques.","Die Aussage richtet sich gegen ungeprüften Methodenwechsel, nicht gegen Arrays an sich.":"Le message vise à éviter un changement de méthode non validé, et non à rejeter les puces en elles-mêmes.","Das Array bestätigt erwartungsgemäß die Tumorklasse, liefert aber keinen lokal validierten MGMT-Report. Was war der Fehler?":"La puce confirme la classe tumorale attendue mais ne fournit pas de compte rendu MGMT validé localement. Quelle était l'erreur ?","Eine globale Klassifikationsplattform wurde für eine fokale prädiktive Frage eingesetzt, ohne passenden validierten Output.":"Une plateforme de classification globale a été utilisée pour une question prédictive focale sans résultat validé adapté.","Methylierungsclassifier sind grundsätzlich nutzlos.":"Les classifieurs de méthylation sont fondamentalement inutiles.","Es gibt keinen Unterschied.":"Il n'y a aucune différence.","Technische Information und klinisch validierter Output sind nicht identisch.":"L'information technique et un résultat cliniquement validé ne sont pas identiques.","Wählen Sie die Methylierungsmethode passend zur konkreten klinischen Frage.":"Choisir la méthode de méthylation en fonction de la question clinique précise.","Prüfen, ob die Tumorentität bereits gesichert ist.":"Vérifier si l'entité tumorale est déjà établie.","Offene Frage als MGMT-Einzelmarker definieren.":"Définir la question ouverte comme une question MGMT en marqueur unique.","Lokal validierten Zielassay verwenden.":"Utiliser le test ciblé validé localement.","Classifier nur bei echter globaler Klassifikationsfrage einsetzen.":"N'utiliser le classifieur que lorsqu'il existe une véritable question de classification globale.","Intended Use im Befund transparent halten.":"Rendre l'usage prévu explicite dans le compte rendu.","Wenn ein Labor einen arraybasierten MGMT-Algorithmus spezifisch klinisch validiert hat, kann dieser lokal geeignet sein; der Fall lehrt Scope/Validierung, keine universelle Plattformhierarchie.":"Si un laboratoire a spécifiquement validé cliniquement un algorithme MGMT fondé sur une puce, celui-ci peut être approprié localement ; ce cas enseigne le périmètre/la validation, et non une hiérarchie universelle des plateformes.","Mehr Daten = besser":"Plus de données = mieux","Ignoriert Fragestellung und Validierung.":"Ignore la question clinique et la validation.","Classifier nie verwenden":"Ne jamais utiliser de classifieur","Bei unklaren CNS-Tumoren kann er sehr wertvoll sein.":"Il peut être très utile dans les tumeurs du SNC diagnostiquement incertaines.","NGS für MGMT-Methylierung":"NGS pour la méthylation de MGMT","Sequenzvarianten beantworten die epigenetische Frage nicht.":"Les variants de séquence ne répondent pas à la question épigénétique.","Das teurere Ergebnis beantwortet die falsche Frage":"Le résultat le plus coûteux répond à la mauvaise question","Der Classifier bestätigt nur die bereits bekannte Tumorklasse; die klinisch offene MGMT-Frage bleibt ohne lokal validierten Einzelmarkeroutput bestehen.":"Le classifieur ne fait que confirmer la classe tumorale déjà connue ; la question clinique MGMT reste sans réponse en l'absence d'un résultat de marqueur unique validé localement.","Der Fall verschiebt Methodenauswahl von Technologieprestige zu Intended Use.":"Le cas déplace le choix de la méthode du prestige technologique vers l'usage prévu.","Zielmarker passend getestet":"Marqueur cible testé de manière appropriée","MGMT mit validierter Zielmethode berichtet.":"MGMT rendu avec la méthode ciblée validée.","Effizient und klinisch passend.":"Efficace et cliniquement approprié.","Classifier ohne offene Klassifikationsfrage":"Classifieur sans question de classification ouverte","Mehr Daten, aber falscher primärer Output.":"Plus de données, mais le mauvais résultat principal.","Scope-Mismatch.":"Inadéquation du périmètre.","Epigenetische Frage bleibt offen.":"La question épigénétique reste non résolue.","Methodenfehler.":"Erreur de méthode.","isolierte validierte Einzelmarkerfrage":"question isolée et validée de marqueur unique","zielgerichteten validierten Assay bevorzugen":"privilégier le test ciblé validé","globale Omik nur bei zusätzlicher passender Fragestellung.":"omique globale uniquement s'il existe une question supplémentaire pertinente.","Fragestellung bestimmt Methodenumfang.":"La question clinique détermine le périmètre méthodologique.","Methylierungsclassifier und lokaler Bisulfitassay sind nicht austauschbar.":"Le classifieur de méthylation et le test local au bisulfite ne sont pas interchangeables.","Intended Use und lokale Validierung gehören zur klinischen Interpretation.":"L'usage prévu et la validation locale font partie de l'interprétation clinique.","Bei gesichertem Glioblastom und isolierter MGMT-Frage ist die lokal validierte zielgerichtete Methylierungsanalyse angemessen; ein Classifier ist kein automatischer Ersatz.":"Dans un glioblastome établi avec une question MGMT isolée, l'analyse ciblée de méthylation validée localement est appropriée ; un classifieur n'est pas un substitut automatique.","Methodenscope":"Périmètre de la méthode","Validierung":"Validation","Methylierungsdiagnostik":"Diagnostic de méthylation","Wann ist ein CNS-Classifier wirklich diagnostisch entscheidend?":"Quand un classifieur du SNC est-il réellement déterminant sur le plan diagnostique ?","Wie validiert man einen MGMT-Assay?":"Comment valider un test MGMT ?","Wann kann ein Array mehrere Outputs klinisch tragen?":"Quand une puce peut-elle prendre en charge plusieurs résultats cliniques ?","Twist: globale Plattform beantwortet lokale Frage nicht automatisch":"Twist : une plateforme globale ne répond pas automatiquement à une question locale","Intended Use vor Omikbreite":"Usage prévu avant largeur omique","Referenzpfad: klinische Frage → validierter Output → Methode":"Parcours de référence : question clinique → résultat validé → méthode","EWSR1-FISH positiv: schneller Rearrangementnachweis, aber noch keine Entität":"FISH EWSR1 positif : détection rapide d'un réarrangement, mais pas encore une entité","Amplifikation/Fusion: FISH als sch…":"Amplification/fusion : FISH comme complément rapide…","Sarkomzentrum / Referenzpathologie":"Centre des sarcomes / anatomopathologie de référence","32-jährige Patientin mit einem tiefen Weichteiltumor am Fuß. Morphologisch monomorpher Tumor; EWSR1-Break-apart-FISH wird wegen Zeitdruck früh durchgeführt und ist positiv.":"Patiente de 32 ans présentant une tumeur profonde des tissus mous du pied. La morphologie montre une tumeur monomorphe ; en raison de l'urgence, un FISH break-apart EWSR1 est réalisé précocement et revient positif.","Darf daraus unmittelbar „Ewing-Sarkom“ werden oder braucht es partner-/transkriptspezifische Auflösung?":"Peut-on conclure immédiatement à un « sarcome d'Ewing » ou faut-il préciser le partenaire/le transcrit ?","Neoadjuvante Strategie wird in wenigen Tagen diskutiert.":"La stratégie néoadjuvante sera discutée dans quelques jours.","Monomorphe Zellen, aber nicht klassisch genug für eine alleinige Ewing-Diagnose.":"Cellules monomorphes, mais pas suffisamment classiques pour poser à elles seules un diagnostic d'Ewing.","EWSR1-Break-apart positiv.":"EWSR1 break-apart positif.","Ein Gen-Rearrangement wird mit einer bestimmten Tumorentität gleichgesetzt.":"Un réarrangement génique est assimilé à une entité tumorale précise.","FISH als schnellen, robusten, aber informationsbegrenzten Test einordnen.":"Positionner le FISH comme un test rapide et robuste, mais limité en information.","Melaninarm, nested/solid; immunhistochemischer Kontext nicht eindeutig für Ewing.":"Pauvre en mélanine, architecture en nids/solide ; le contexte immunohistochimique n'est pas sans ambiguïté en faveur d'Ewing.","EWSR1 rearrangiert.":"EWSR1 réarrangé.","Welcher Partner und welche Transkriptfusion liegt vor?":"Quel partenaire et quel transcrit de fusion sont présents ?","EWSR1-Rearrangements kommen in mehreren Tumorentitäten vor.":"Les réarrangements d'EWSR1 surviennent dans plusieurs entités tumorales.","FFPE-Biopsie; RNA ausreichend.":"Biopsie FFPE ; ARN suffisant.","schnell verfügbar und technisch robust.":"rapidement disponible et techniquement robuste.","Targeted RNA-NGS verfügbar.":"NGS ARN ciblé disponible.","Partnerbestimmung kann die Entitätsdiagnose entscheidend verändern.":"L'identification du partenaire peut modifier de façon décisive le diagnostic d'entité.","Rearrangement schnell/orthogonal erfassen":"Détecter rapidement/orthogonalement le réarrangement","Fusionspartner/Transkript klären":"Préciser le partenaire/le transcrit de fusion","Break-apart-FISH":"FISH break-apart","EWSR1-Break-apart positiv: ein EWSR1-Rearrangement ist nachgewiesen, die Partneridentität und damit die genaue Entität sind dadurch nicht allein definiert.":"EWSR1 break-apart positif : un réarrangement d'EWSR1 est démontré, mais l'identité du partenaire et donc l'entité exacte ne sont pas définies par ce seul résultat.","RNA-NGS weist EWSR1::ATF1 nach und unterstützt im passenden morphologisch-immunhistochemischen Kontext die Diagnose eines Clear-Cell-Sarkoms statt eines Ewing-Sarkoms.":"Le NGS ARN détecte EWSR1::ATF1 et, dans le contexte morphologique et immunohistochimique approprié, soutient un diagnostic de sarcome à cellules claires plutôt que de sarcome d'Ewing.","Zusatzvarianten tragen weniger zur Kernfrage bei als die direkte Partnerbestimmung der Fusion.":"Les variants supplémentaires contribuent moins à la question centrale que l'identification directe du partenaire de fusion.","schneller Rearrangementnachweis, aber keine universelle Entitätsdefinition.":"détection rapide du réarrangement, mais pas définition universelle d'une entité.","Gen-Rearrangement und Fusionspartner müssen im morphologischen Kontext interpretiert werden.":"Le réarrangement génique et le partenaire de fusion doivent être interprétés dans le contexte morphologique.","EWSR1-Break-apart-FISH ist ein sinnvoller schneller Nachweis eines Rearrangements, beweist aber nicht automatisch ein Ewing-Sarkom. Die RNA-basierte Partnerbestimmung zeigt EWSR1::ATF1 und verschiebt die integrierte Diagnose im passenden Kontext zu einem Clear-Cell-Sarkom. FISH bleibt wertvoll – aber seine Aussagegrenze muss respektiert werden.":"Le FISH break-apart EWSR1 est un test rapide utile pour détecter un réarrangement, mais il ne prouve pas automatiquement un sarcome d'Ewing. L'identification du partenaire par ARN révèle EWSR1::ATF1 et réoriente, dans le contexte approprié, le diagnostic intégré vers un sarcome à cellules claires. Le FISH reste précieux, mais ses limites d'interprétation doivent être respectées.","Teilbefund: Ein positiver Break-apart-FISH beantwortet „ist das Gen rearrangiert?“, nicht immer „welche Fusion/Entität liegt vor?“.":"Résultat partiel : un FISH break-apart positif répond à « le gène est-il réarrangé ? », mais pas toujours à « quelle fusion/entité est présente ? ».","FISH-Stärke und -Grenze benennen":"Préciser la force et la limite du FISH","Partnerbestimmung bei entitätsrelevanter Frage ergänzen":"Ajouter l'identification du partenaire lorsqu'elle est pertinente pour le diagnostic d'entité","Molekularbefund in Morphologie/IHC integrieren":"Intégrer le résultat moléculaire à la morphologie/IHC","Falschaussage: EWSR1-FISH positiv = Ewing-Sarkom":"Affirmation erronée : FISH EWSR1 positif = sarcome d'Ewing","Optimale Lösung: FISH als schnellen Rearrangementnachweis nutzen, aber bei nicht entitätsspezifischem Genereignis den Partner mit RNA-NGS bestimmen und integriert diagnostizieren.":"Solution optimale : utiliser le FISH pour détecter rapidement le réarrangement, mais lorsque l'événement génique n'est pas spécifique d'une entité, déterminer le partenaire par NGS ARN et établir un diagnostic intégré.","EWSR1":"EWSR1","Sarcoma":"Sarcome","FISH positiv – Diagnose noch offen":"FISH positif – diagnostic encore ouvert","Sarkompathologie / FISH / RNA-Fusion":"Pathologie des sarcomes / FISH / fusion ARN","Break-apart-FISH als schnellen Rearrangementnachweis korrekt einordnen.":"Positionner correctement le FISH break-apart comme test rapide de réarrangement.","Nicht entitätsspezifische Rearrangements nicht überinterpretieren.":"Ne pas surinterpréter les réarrangements non spécifiques d'une entité.","RNA-NGS zur Partner-/Transkriptbestimmung nutzen.":"Utiliser le NGS ARN pour identifier le partenaire/le transcrit.","Morphologie, IHC, FISH und RNA integriert bewerten.":"Évaluer de façon intégrée la morphologie, l'IHC, le FISH et l'ARN.","Der FISH ist positiv. EWSR1 rearrangiert. Im ersten Moment klingt das wie die Diagnose – bis man sich erinnert, dass EWSR1 in mehreren völlig unterschiedlichen Tumoren rearrangiert sein kann.":"Le FISH est positif. EWSR1 est réarrangé. Au premier abord, cela ressemble au diagnostic, jusqu'à ce que l'on se rappelle qu'EWSR1 peut être réarrangé dans plusieurs tumeurs totalement différentes.","32-jährige Patientin mit Weichteiltumor am Fuß. EWSR1-Break-apart-FISH ist positiv, die Morphologie aber nicht klassisch für Ewing. RNA ist ausreichend für Partnerbestimmung.":"Patiente de 32 ans avec tumeur des tissus mous du pied. Le FISH break-apart EWSR1 est positif, mais la morphologie n'est pas classique pour Ewing. L'ARN est suffisant pour identifier le partenaire.","FISH beantwortet eine enge Frage":"Le FISH répond à une question ciblée","Break-apart: Rearrangement ja/nein.":"Break-apart : réarrangement oui/non.","Partner und Transkript bleiben oft offen.":"Le partenaire et le transcrit restent souvent indéterminés.","Genereignis ist nicht immer entitätsspezifisch":"L'événement génique n'est pas toujours spécifique d'une entité","EWSR1 kann verschiedene Fusionspartner und Tumorentitäten haben.":"EWSR1 peut avoir différents partenaires de fusion et se rencontrer dans différentes entités tumorales.","Molekularer Befund braucht Kontext.":"Un résultat moléculaire nécessite un contexte.","RNA löst die Partnerfrage":"L'ARN résout la question du partenaire","Sequenzbasierter Transkriptnachweis kann die diagnostische Klasse entscheidend präzisieren.":"La détection du transcrit par séquençage peut préciser de façon décisive la classe diagnostique.","FISH und RNA konkurrieren nicht, sie ergänzen sich.":"FISH et ARN ne s'opposent pas ; ils se complètent.","monomorph, aber nicht klassisch Ewing":"monomorphe, mais non classique pour Ewing","EWSR1 break-apart positiv":"EWSR1 break-apart positif","Zeitdruck macht FISH attraktiv.":"L'urgence rend le FISH attractif.","RNA-NGS ist innerhalb der diagnostischen Frist möglich.":"Le NGS ARN est réalisable dans le délai diagnostique.","Positives FISH darf nicht über seine validierte Zielaussage hinaus interpretiert werden.":"Un FISH positif ne doit pas être interprété au-delà de son indication cible validée.","Was beweist ein positiver EWSR1-Break-apart-FISH primär?":"Que démontre principalement un FISH break-apart EWSR1 positif ?","Ein EWSR1-Rearrangement.":"Un réarrangement d'EWSR1.","Immer ein Ewing-Sarkom.":"Toujours un sarcome d'Ewing.","Immer den exakten Fusionspartner.":"Toujours le partenaire de fusion exact.","Quantitative Proteinexpression.":"Expression protéique quantitative.","Break-apart-FISH ist genbezogen, nicht zwingend partner- oder entitätsspezifisch.":"Le FISH break-apart est spécifique du gène, pas nécessairement du partenaire ou de l'entité.","Warum ist RNA-NGS bei atypischer Morphologie sinnvoll?":"Pourquoi le NGS ARN est-il utile lorsque la morphologie est atypique ?","Zur Bestimmung des exprimierten Fusionspartners/Transkripts.":"Pour identifier le partenaire/le transcrit de fusion exprimé.","Weil es exakt dasselbe wie FISH misst.":"Parce qu'il mesure exactement la même chose que le FISH.","Nur zur Copy-number-Bestimmung.":"Uniquement pour la détermination du nombre de copies.","Nur für Keimbahn.":"Uniquement pour l'analyse constitutionnelle.","Die Partnerinformation kann die Diagnose präzisieren.":"L'information sur le partenaire peut préciser le diagnostic.","Wie sollte ein Fusionsbefund diagnostisch verwendet werden?":"Comment un résultat de fusion doit-il être utilisé sur le plan diagnostique ?","Mit Morphologie, IHC und klinischem Kontext integrieren.":"L'intégrer à la morphologie, à l'IHC et au contexte clinique.","Molekularer Befund ersetzt immer die Histologie.":"Un résultat moléculaire remplace toujours l'histologie.","Molekulare Befunde sind bei Sarkomen unwichtig.":"Les résultats moléculaires sont sans importance dans les sarcomes.","FISH entscheidet jede Entität allein.":"Le FISH détermine à lui seul chaque entité.","Entitätsdiagnostik ist integriert.":"Le diagnostic d'entité est intégré.","RNA zeigt EWSR1::ATF1. Was ändert sich?":"L'ARN montre EWSR1::ATF1. Qu'est-ce qui change ?","Im passenden Kontext unterstützt dies Clear-Cell-Sarkom statt einer vorschnellen Ewing-Diagnose.":"Dans le contexte approprié, cela soutient un sarcome à cellules claires plutôt qu'un diagnostic prématuré d'Ewing.","Es beweist weiterhin Ewing unabhängig vom Partner.":"Cela prouve toujours Ewing quel que soit le partenaire.","Der positive FISH war falsch.":"Le FISH positif était erroné.","Partnerinformation ist bedeutungslos.":"L'information sur le partenaire n'a aucune importance.","Die Partneridentität kann die Entitätszuordnung entscheidend verändern.":"L'identité du partenaire peut modifier de façon décisive l'attribution de l'entité.","Nutzen Sie FISH dort, wo er stark ist, und definieren Sie, wann Partnerbestimmung erforderlich ist.":"Utiliser le FISH là où il est performant et définir quand l'identification du partenaire est nécessaire.","Morphologie und Prätestwahrscheinlichkeit erfassen.":"Évaluer la morphologie et la probabilité pré-test.","FISH als schnellen Rearrangementnachweis verwenden.":"Utiliser le FISH comme test rapide de réarrangement.","Aussagegrenze explizit halten.":"Rendre explicite la limite d'interprétation.","Bei entitätsrelevanter Partnerfrage RNA-NGS ergänzen.":"Ajouter un NGS ARN lorsque l'identité du partenaire est pertinente pour l'entité.","Integrierte Diagnose aus allen Ebenen formulieren.":"Formuler un diagnostic intégré à partir de tous les niveaux.","Bei sehr charakteristischer Morphologie und entitätsspezifischem Rearrangement kann FISH ausreichend sein; das hängt von Gen, Tumorart und validiertem diagnostischem Kontext ab.":"Avec une morphologie très caractéristique et un réarrangement spécifique d'une entité, le FISH peut suffire ; cela dépend du gène, du type tumoral et du contexte diagnostique validé.","Break-apart = Partner bekannt":"Break-apart = partenaire connu","FISH liefert diese Information häufig nicht.":"Le FISH ne fournit souvent pas cette information.","EWSR1 = Ewing":"EWSR1 = Ewing","EWSR1 ist nicht entitätsspezifisch.":"EWSR1 n'est pas spécifique d'une entité.","FISH ist veraltet und nutzlos":"Le FISH est obsolète et inutile","FISH kann schnell, robust und materialeffizient sehr wertvoll sein.":"Le FISH peut être rapide, robuste, économe en matériel et très utile.","Der Partner kippt die Diagnose":"Le partenaire change le diagnostic","RNA zeigt EWSR1::ATF1 statt einer Ewing-typischen Fusion.":"L'ARN montre EWSR1::ATF1 plutôt qu'une fusion typique d'Ewing.","FISH war korrekt positiv, aber die überzogene Interpretation wäre falsch gewesen.":"Le FISH était correctement positif, mais l'interprétation excessive aurait été erronée.","FISH + RNA integriert":"FISH + ARN intégrés","Rearrangement schnell erkannt, Partner korrekt bestimmt, Diagnose präzisiert.":"Réarrangement rapidement détecté, partenaire correctement identifié, diagnostic précisé.","Stärken beider Methoden genutzt.":"Les points forts des deux méthodes ont été exploités.","Ewing nur aus EWSR1-FISH":"Ewing sur le seul FISH EWSR1","Entität falsch überinterpretiert.":"Entité surinterprétée à tort.","Scope-Fehler.":"Erreur de périmètre.","FISH komplett verworfen":"FISH complètement écarté","Schnelle robuste Information unnötig verloren.":"Information rapide et robuste inutilement perdue.","positiver genbezogener FISH ohne entitätsspezifische Eindeutigkeit":"FISH génique positif sans spécificité univoque d'entité","Partner-/Transkriptbestimmung erwägen":"envisager l'identification du partenaire/du transcrit","Diagnose nicht allein aus Gen-Rearrangement ableiten.":"ne pas déduire le diagnostic du seul réarrangement génique.","FISH bleibt klinisch nützlich.":"Le FISH reste cliniquement utile.","Aussagegrenze ist Teil der Methode.":"La limite d'interprétation fait partie de la méthode.","Partnerinformation kann diagnostisch wichtiger sein als der reine Gen-Rearrangementnachweis.":"L'information sur le partenaire peut être diagnostiquement plus importante que la seule détection du réarrangement génique.","EWSR1-FISH bestätigt ein Rearrangement, aber keine automatische Ewing-Diagnose; RNA-NGS zeigt EWSR1::ATF1 und präzisiert die Entität im morphologischen Kontext.":"Le FISH EWSR1 confirme un réarrangement mais ne diagnostique pas automatiquement Ewing ; le NGS ARN montre EWSR1::ATF1 et précise l'entité dans le contexte morphologique.","FISH-Scope":"Périmètre du FISH","Partnerbestimmung":"Identification du partenaire","integrierte Sarkomdiagnostik":"Diagnostic intégré des sarcomes","Welche Break-apart-Sonden sind besonders entitätsspezifisch oder unspezifisch?":"Quelles sondes break-apart sont particulièrement spécifiques ou non spécifiques d'une entité ?","Wann ist FISH bei schlechter RNA die beste Option?":"Quand le FISH est-il la meilleure option avec un ARN de mauvaise qualité ?","Wie formuliert man einen positiven FISH ohne Partner?":"Comment formuler un FISH positif sans partenaire connu ?","Twist: FISH korrekt, Interpretation fast falsch":"Twist : FISH correct, interprétation presque erronée","Gen-Rearrangement ≠ Entität":"Réarrangement génique ≠ entité","Referenzpfad: FISH → Scope prüfen → RNA-Partner → integrieren":"Parcours de référence : FISH → vérifier le périmètre → partenaire ARN → intégrer","23 Seiten Multiomics: eine belastbare Kernaussage, viele Hypothesen":"23 pages de multiomique : un message central robuste, de nombreuses hypothèses","Multiomics-Bericht: viel Informati…":"Rapport multiomique : beaucoup d'informati…","Hepatobiliäres Tumorboard / Präzisionsonkologie":"RCP hépatobiliaire / oncologie de précision","59-jährige Patientin mit metastasiertem intrahepatischem Cholangiokarzinom. Ein externer Multiomics-Bericht umfasst DNA, RNA, Immunmarker und Proteinsignaturen auf 23 Seiten.":"Patiente de 59 ans présentant un cholangiocarcinome intrahépatique métastatique. Un rapport multiomique externe de 23 pages comprend ADN, ARN, marqueurs immunitaires et signatures protéiques.","Welche Befunde sind unmittelbar klinisch belastbar, welche nur biologischer Kontext und welche reine Hypothese?":"Quels résultats sont immédiatement robustes sur le plan clinique, lesquels ne constituent qu'un contexte biologique et lesquels ne sont que des hypothèses ?","Das MTB hat sieben Minuten für die molekulare Kernaussage.":"La RCP dispose de sept minutes pour le message moléculaire essentiel.","Pathogene IDH1 p.R132C-Mutation; keine FGFR2-Fusion im validierten Fusionsassay.":"Mutation pathogène IDH1 p.R132C ; aucune fusion FGFR2 dans le test de fusion validé.","FGFR2-Expression deutlich erhöht; mehrere Pathway-Scores für MAPK/EMT.":"Expression de FGFR2 nettement augmentée ; plusieurs scores de voies MAPK/EMT.","Immunprofil":"Profil immunitaire","MSS, niedrige TMB; PD-L1 niedrig.":"MSS, TMB faible ; PD-L1 faible.","Der visuell spektakulärste Omics-Score wird mit einem validierten prädiktiven Biomarker gleichgesetzt.":"Le score omique visuellement le plus spectaculaire est assimilé à un biomarqueur prédictif validé.","Intrahepatisches Cholangiokarzinom.":"Cholangiocarcinome intrahépatique.","Molekulare Schlüsseldaten":"Données moléculaires clés","IDH1 pathogen; keine FGFR2-Fusion.":"IDH1 pathogène ; aucune fusion FGFR2.","Explorative Daten":"Données exploratoires","FGFR2-high expression, EMT-/MET-Signaturen.":"Expression élevée de FGFR2, signatures EMT/MET.","Was gehört in die erste Zeile des Tumorboards?":"Que doit contenir la première ligne du résumé pour la RCP ?","Mehrere Omics-Layer bereits erzeugt.":"Plusieurs couches omiques ont déjà été générées.","Problem":"Problème","Nicht Datenmangel, sondern Evidenzpriorisierung.":"Non pas un manque de données, mais une priorisation des preuves.","Zeit":"Temps","MTB-Kommunikation muss extrem komprimiert sein.":"La communication en RCP doit être extrêmement concise.","Keine weitere Messung nötig, bevor die vorhandenen Daten sauber hierarchisiert sind.":"Aucune mesure supplémentaire n'est nécessaire avant d'avoir correctement hiérarchisé les données existantes.","Multiomics-Evidenz priorisieren und verdichten":"Prioriser et condenser les preuves multiomiques","Multiomics-Kernaussage":"Message central multiomique","Kernaussage: pathogene IDH1-Alteration als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. FGFR2-Überexpression sowie EMT/MET-Signaturen bleiben explorativ und dürfen nicht wie validierte prädiktive Targets kommuniziert werden.":"Message central : altération pathogène d'IDH1 comme biomarqueur tumoral établi ; aucune fusion FGFR2. La surexpression de FGFR2 et les signatures EMT/MET restent exploratoires et ne doivent pas être présentées comme des cibles prédictives validées.","Noch breiteres Panel":"Panel encore plus large","Mehr Daten lösen die zentrale Aufgabe – Evidenzhierarchie und klare Kommunikation – nicht.":"Davantage de données ne résout pas la tâche centrale : hiérarchie des preuves et communication claire.","Informationsdichte":"Densité d'information","Viele biologisch interessante Signale, aber nur wenige direkt handlungsleitende Befunde.":"De nombreux signaux biologiquement intéressants, mais peu de résultats directement décisionnels.","Multiomics braucht Evidenzhierarchie, nicht nur Datensynthese.":"La multiomique nécessite une hiérarchie des preuves, pas seulement une synthèse des données.","Der Bericht wird auf eine belastbare klinische Kernaussage reduziert: pathogene IDH1-Veränderung als etablierter tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression ist nicht gleichbedeutend mit einer FGFR2-Fusion, und EMT/MET-/Pathway-Signaturen bleiben ohne passende klinische Validierung explorativ. Das MTB erhält Evidenzstufen statt Datenrauschen.":"Le rapport est réduit à un message clinique central robuste : altération pathogène d'IDH1 comme biomarqueur tumoral établi ; aucune fusion FGFR2. Une forte expression de FGFR2 n'équivaut pas à une fusion FGFR2, et les signatures EMT/MET/de voies restent exploratoires sans validation clinique appropriée. La RCP reçoit des niveaux de preuve plutôt qu'un bruit de données.","Teilbefund: Multiomics ist nur dann klinisch nützlich, wenn validierte Biomarker, Kontextsignale und Hypothesen klar getrennt werden.":"Résultat partiel : la multiomique n'est cliniquement utile que si les biomarqueurs validés, les signaux de contexte et les hypothèses sont clairement séparés.","Befunde nach klinischer Evidenz ordnen":"Classer les résultats selon les preuves cliniques","Expression nicht mit Fusion gleichsetzen":"Ne pas assimiler expression et fusion","explorative Signaturen als Hypothesen kennzeichnen":"Étiqueter les signatures exploratoires comme hypothèses","Falschaussage: stärkstes Heatmap-Signal = bestes Target":"Affirmation erronée : signal le plus fort de la heatmap = meilleure cible","Optimale Lösung: aus vielen Daten eine kurze Evidenzhierarchie bauen – gesicherter Biomarker zuerst, relevante negative Befunde danach, explorative Omics klar als Hypothesen.":"Solution optimale : construire une courte hiérarchie des preuves à partir de nombreuses données — biomarqueur établi d'abord, résultats négatifs pertinents ensuite, omique exploratoire clairement étiquetée comme hypothèse.","Multiomics":"Multiomique","MTB-RES":"MTB-RES","23 Seiten auf drei Sätze reduzieren":"Réduire 23 pages à trois phrases","Präzisionsonkologie / MTB-Kommunikation":"Oncologie de précision / communication en RCP","Multiomics-Befunde nach klinischer Evidenz hierarchisieren.":"Hiérarchiser les résultats multiomiques selon les preuves cliniques.","Genomische Alteration, Expression und Pathway-Signatur nicht miteinander gleichsetzen.":"Ne pas assimiler altération génomique, expression et signature de voie.","Relevante Negativbefunde sichtbar halten.":"Maintenir visibles les résultats négatifs pertinents.","Explorative Hypothesen klar von handlungsleitenden Biomarkern trennen.":"Séparer clairement les hypothèses exploratoires des biomarqueurs guidant la décision.","Eine präzise MTB-Kernaussage aus Datenfülle formulieren.":"Formuler un message central précis pour la RCP à partir d'un rapport riche en données.","Der Report ist 23 Seiten lang. Das Tumorboard hat sieben Minuten. Die Aufgabe ist nicht, alles vorzulesen – sondern zu wissen, welche zwei Sätze wirklich eine Entscheidung tragen.":"Le rapport fait 23 pages. La RCP dispose de sept minutes. L'objectif n'est pas de tout lire, mais de savoir quelles deux phrases soutiennent réellement une décision.","59-jährige Patientin mit intrahepatischem Cholangiokarzinom. DNA, RNA und weitere Omics-Layer liegen vor. Eine pathogene IDH1-Alteration ist klar, eine FGFR2-Fusion fehlt, während FGFR2-Expression und mehrere Pathway-Scores hoch sind.":"Patiente de 59 ans avec cholangiocarcinome intrahépatique. Les données ADN, ARN et d'autres couches omiques sont disponibles. Une altération pathogène d'IDH1 est clairement identifiée, aucune fusion FGFR2 n'est détectée, tandis que l'expression de FGFR2 et plusieurs scores de voies sont élevés.","Evidenz vor Datenmenge":"Les preuves avant le volume de données","Ein validierter Biomarker wiegt klinisch mehr als viele explorative Signaturen.":"Un biomarqueur validé a plus de poids clinique que de nombreuses signatures exploratoires.","Informationsmenge ist keine Evidenzstufe.":"La quantité d'information n'est pas un niveau de preuve.","Expression ≠ Fusion":"Expression ≠ fusion","Hohe FGFR2-mRNA ist biologisch interessant, aber nicht dasselbe wie ein nachgewiesenes FGFR2-Fusionsereignis.":"Un ARNm FGFR2 élevé est biologiquement intéressant, mais ce n'est pas la même chose qu'un événement de fusion FGFR2 démontré.","Omics-Layer messen unterschiedliche Phänomene.":"Les couches omiques mesurent des phénomènes différents.","Negative Befunde können entscheidend sein":"Les résultats négatifs peuvent être décisifs","„Keine FGFR2-Fusion“ verhindert ein falsches Target-Narrativ.":"« Aucune fusion FGFR2 » évite un faux récit de cible thérapeutique.","Klinische Zusammenfassung braucht auch relevante Ausschlüsse.":"Un résumé clinique doit aussi inclure les exclusions pertinentes.","IDH1 p.R132C pathogen":"IDH1 p.R132C pathogène","keine FGFR2-Fusion":"aucune fusion FGFR2","FGFR2 hoch exprimiert; EMT/MET-Signaturen erhöht":"FGFR2 fortement exprimé ; signatures EMT/MET augmentées","Immunkontext":"Contexte immunitaire","MSS, TMB niedrig, PD-L1 niedrig":"MSS, TMB faible, PD-L1 faible","Alle Daten bereits vorhanden.":"Toutes les données sont déjà disponibles.","Keine akute Materialfrage.":"Aucun problème aigu de matériel.","Limitierend ist die Evidenzinterpretation, nicht die Messkapazität.":"La limite réside dans l'interprétation des preuves, pas dans la capacité de mesure.","Was gehört in die erste Zeile der MTB-Zusammenfassung?":"Que doit contenir la première ligne du résumé pour la RCP ?","Der klinisch am besten validierte relevante Biomarker und seine konkrete Bedeutung.":"Le biomarqueur pertinent le mieux validé cliniquement et sa signification concrète.","Die stärkste Farbe der Heatmap.":"La couleur la plus intense de la heatmap.","Alle 200 Signaturen alphabetisch.":"Les 200 signatures par ordre alphabétique.","Jede VUS vor gesicherten Befunden.":"Chaque VUS avant les résultats établis.","MTB-Kommunikation priorisiert klinische Evidenz.":"La communication en RCP priorise les preuves cliniques.","Was bedeutet hohe FGFR2-Expression ohne nachgewiesene FGFR2-Fusion?":"Que signifie une forte expression de FGFR2 sans fusion FGFR2 démontrée ?","Biologischer/explorativer Kontext, aber kein automatischer Ersatz für den validierten Fusionsbiomarker.":"Contexte biologique/exploratoire, mais pas substitut automatique au biomarqueur de fusion validé.","Eine Fusion ist damit bewiesen.":"Une fusion est ainsi prouvée.","Target-Therapie ist allein dadurch zwingend.":"Une thérapie ciblée est obligatoire sur cette seule base.","RNA ist grundsätzlich Artefakt.":"L'ARN est intrinsèquement un artefact.","Expression und strukturelle Genfusion sind verschiedene Befundarten.":"L'expression et la fusion génique structurelle sont des types de résultats différents.","Warum ist „keine FGFR2-Fusion“ ein wichtiger Befund?":"Pourquoi « aucune fusion FGFR2 » est-il un résultat important ?","Er verhindert, dass die hohe Expression fälschlich als etablierter Fusions-Targetkontext verkauft wird.":"Cela évite de présenter à tort une forte expression comme un contexte établi de cible liée à une fusion.","Negative Befunde gehören nie ins MTB.":"Les résultats négatifs n'ont jamais leur place en RCP.","Er hat keinerlei Interpretationswert.":"Cela n'a aucune valeur interprétative.","Er macht IDH1 automatisch negativ.":"Cela rend automatiquement IDH1 négatif.","Relevante Negativbefunde begrenzen falsche Handlungsableitungen.":"Les résultats négatifs pertinents limitent les fausses inférences d'actionnabilité.","Der Bericht rankt „FGFR pathway activation“ als stärkstes Signal. Was tun Sie?":"Le rapport classe « activation de la voie FGFR » comme le signal le plus fort. Que faites-vous ?","Als explorative Signatur kennzeichnen und hinter validierten molekularen Befunden priorisieren.":"L'étiqueter comme signature exploratoire et la placer derrière les résultats moléculaires validés.","Als stärkstes Target behandeln.":"Le traiter comme la cible la plus forte.","Alle Omics-Daten verwerfen.":"Écarter toutes les données omiques.","Eine FGFR2-Fusion daraus ableiten.":"En déduire une fusion FGFR2.","Pathway-Scores sind ohne entsprechende klinische Validierung Hypothesen, keine automatischen Companion Biomarker.":"Sans validation clinique correspondante, les scores de voies sont des hypothèses, pas des biomarqueurs compagnons automatiques.","Verdichten Sie den Multiomics-Bericht zu einer evidenzhierarchischen MTB-Kernaussage.":"Condenser le rapport multiomique en un message central pour la RCP hiérarchisé selon les preuves.","Validierte/etablierte Biomarker identifizieren.":"Identifier les biomarqueurs validés/établis.","Relevante negative Befunde sichtbar machen.":"Rendre visibles les résultats négatifs pertinents.","Expression, Fusion, Protein und Pathways als unterschiedliche Ebenen behandeln.":"Traiter expression, fusion, protéine et voies comme des couches différentes.","Explorative Signaturen kennzeichnen.":"Étiqueter les signatures exploratoires.","MTB-Aussage auf Entscheidung statt Dateninventar fokussieren.":"Centrer le message de la RCP sur la décision, pas sur l'inventaire des données.","Explorative Omics können für Studienhypothesen oder Translation wertvoll sein; sie gehören nur nicht unmarkiert in dieselbe Evidenzstufe wie validierte klinische Biomarker.":"L'omique exploratoire peut être précieuse pour des hypothèses d'étude ou la recherche translationnelle ; elle ne doit simplement pas être placée, sans étiquetage, au même niveau de preuve que des biomarqueurs cliniques validés.","Heatmap-Tophit = Target":"Top hit de la heatmap = cible","Visuelle Effektstärke ersetzt keine klinische Validierung.":"L'ampleur visuelle de l'effet ne remplace pas la validation clinique.","Alles in einen Satz pressen":"Tout condenser en une seule phrase","Verwischt Evidenzstufen.":"Brouille les niveaux de preuve.","Exploratives komplett löschen":"Supprimer complètement l'exploratoire","Verliert wissenschaftlich wertvolle Hypothesen; besser klar labeln.":"Fait perdre des hypothèses scientifiquement précieuses ; mieux vaut les étiqueter clairement.","Der lauteste Signalweg ist nicht die stärkste klinische Aussage":"La voie la plus spectaculaire n'est pas l'affirmation clinique la plus forte","FGFR2-Expression ist hoch, aber es gibt keine FGFR2-Fusion. Die belastbare Topline bleibt die pathogene IDH1-Alteration; Omics-Signaturen werden als explorativ eingeordnet.":"L'expression de FGFR2 est élevée, mais il n'existe pas de fusion FGFR2. Le message principal robuste reste l'altération pathogène d'IDH1 ; les signatures omiques sont classées comme exploratoires.","Der Twist dreht die Priorität von Signalstärke zu Evidenzstärke.":"Le twist déplace la priorité de la force du signal vers la force des preuves.","Klarer Biomarker, klarer Ausschluss, klar markierte Hypothesen.":"Biomarqueur clair, exclusion claire, hypothèses clairement étiquetées.","MTB-taugliche Verdichtung.":"Synthèse adaptée à la RCP.","Report vorgelesen":"Rapport lu à voix haute","Viele Daten, keine Entscheidung.":"Beaucoup de données, aucune décision.","Informationsüberlastung.":"Surcharge d'information.","FGFR2-expression als Fusion behandelt":"Expression de FGFR2 traitée comme une fusion","Explorativer Befund wird targetiert.":"Le résultat exploratoire est traité comme une cible.","Layer-Verwechslung.":"Confusion des couches.","Omics-Signal ohne validierten klinischen Biomarkerstatus":"Signal omique sans statut validé de biomarqueur clinique","als explorativ/hypothesengenerierend kennzeichnen":"étiqueter comme exploratoire/générateur d'hypothèses","nicht auf gleiche Ebene wie etablierte prädiktive Marker stellen.":"ne pas placer au même niveau que les marqueurs prédictifs établis.","Multiomics braucht Evidenzhierarchie.":"La multiomique nécessite une hiérarchie des preuves.","Biologische Plausibilität ist nicht identisch mit klinischer Actionability.":"La plausibilité biologique n'est pas identique à l'actionnabilité clinique.","Gute MTB-Kommunikation ist selektiv und transparent.":"Une bonne communication en RCP est sélective et transparente.","Kernaussage: pathogene IDH1-Alteration als belastbarer tumorbezogener Biomarker; keine FGFR2-Fusion. Hohe FGFR2-Expression und Pathway-Signaturen sind explorativ und nicht als validierte Targets zu überinterpretieren.":"Message central : altération pathogène d'IDH1 comme biomarqueur tumoral robuste ; aucune fusion FGFR2. La forte expression de FGFR2 et les signatures de voies sont exploratoires et ne doivent pas être surinterprétées comme des cibles validées.","Evidenzpriorisierung":"Priorisation des preuves","Omics-Layer":"Couches omiques","Wie viele Ebenen sollte ein MTB-Report zeigen?":"Combien de niveaux un rapport de RCP doit-il montrer ?","Wie labelt man explorative Signaturen?":"Comment étiqueter les signatures exploratoires ?","Welche negativen Befunde sind entscheidungsrelevant?":"Quels résultats négatifs sont pertinents pour la décision ?","Twist: stärkstes Signal ist nicht stärkste Evidenz":"Twist : le signal le plus fort n'est pas la preuve la plus forte","Referenzpfad: validiert → relevante Negative → explorativ":"Parcours de référence : validé → négatifs pertinents → exploratoire","dna_rna_lung_combo":"Panel pulmonaire combiné ADN/ARN","Resistenzdiagnostik bei Progress":"Analyse des mécanismes de résistance à la progression","Gewebe-Rebiopsie bei negativer Liquid Biopsy":"Rebiopsie tissulaire après une biopsie liquide négative","Liquid Biopsy richtig einordnen":"Interpréter correctement la biopsie liquide","Progressionspanel: erworbener Resistenzmechanismus wird plausibilisiert; Liquid Biopsy allein ist bei negativem Ergebnis nicht ausreichend.":"Panel à la progression : un mécanisme de résistance acquis est étayé ; une biopsie liquide négative seule est insuffisante.","Rebiopsie liefert beurteilbares Tumormaterial für Resistenzanalyse.":"La rebiopsie fournit du matériel tumoral évaluable pour l’analyse de résistance.","Negative Liquid Biopsy wird nur mit ctDNA-/Materialkontext interpretiert; Rebiopsie bleibt Option.":"Une biopsie liquide négative ne s’interprète qu’en tenant compte de l’ADNct et de l’adéquation du prélèvement ; la rebiopsie reste une option.","Integrierte Interpretation vollständig: Liquid Biopsy negativ: reicht das oder Rebiopsie? Die gewählten Methoden beantworten die Kernfrage mit angemessener Aussagekraft und Limitationen.":"Interprétation intégrée complète : biopsie liquide négative — est-ce suffisant ou faut-il une rebiopsie ? Les méthodes choisies répondent à la question centrale avec une portée analytique et des limites appropriées.","Teilbefund: Für die Kernentscheidung („Liquid Biopsy negativ: reicht das oder Rebiopsie?“) fehlen noch zentrale Bausteine oder die Methode ist zu eng gewählt.":"Résultat partiel : des éléments essentiels manquent encore pour la décision centrale (« Biopsie liquide négative : est-ce suffisant ou faut-il une rebiopsie ? ») ou la méthode choisie est trop limitée.","Resistenzdiagnostik bei Progress in der MTB-Kernaussage korrekt einordnen":"Intégrer correctement l’analyse de résistance à la progression dans le message central du MTB","Gewebe-Rebiopsie bei negativer Liquid Biopsy in der MTB-Kernaussage korrekt einordnen":"Intégrer correctement la rebiopsie tissulaire après une biopsie liquide négative dans le message central du MTB","Liquid Biopsy richtig einordnen in der MTB-Kernaussage korrekt einordnen":"Interpréter correctement la biopsie liquide dans le message central du MTB","Optimale Lösung: Liquid Biopsy negativ: reicht das oder Rebiopsie? – mit fallgerechter Methodenkombination, Material-/QC-Bewertung und klarer MTB-Kommunikation.":"Solution optimale : biopsie liquide négative — est-ce suffisant ou faut-il une rebiopsie ? Utiliser une combinaison de méthodes adaptée au cas, évaluer le contexte prélèvement/QC et communiquer clairement la conclusion au MTB.","RNA-Fusionsdiagnostik primär fehlt":"La recherche primaire de fusions par ARN est absente","entitätsfremde Tests gewählt":"Des tests non pertinents pour l’entité tumorale ont été sélectionnés","nur Liquid Biopsy gewählt":"Seule la biopsie liquide a été sélectionnée","Rebiopsie gewählt, aber MET/CNV/Transformation nicht bedacht":"La rebiopsie a été choisie, mais MET/CNV/la transformation histologique n’ont pas été pris en compte","MTB Basics / Präanalytik":"Bases du MTB / Pré-analytique","colon_ngs_panel":"Panel NGS du cancer colorectal","MTB Basics / Genominstabilität":"Bases du MTB / Instabilité génomique","broad_pan_panel":"Panel pan-cancer large","MTB Basics / Advanced":"Bases du MTB / Avancé","hoch.":"élevé.","MTB / Molecular Diagnostics":"MTB / Diagnostic moléculaire","wildtyp":"type sauvage"}};
function canonicalSig(c){try{c=c||((typeof activeCase!=='undefined')?activeCase:null);return !!(c&&CANONICAL_SIGNATURE_IDS.has(c.id));}catch(_){return false}}
window.MolPathCanonicalSignatureIds=[...CANONICAL_SIGNATURE_IDS];window.MolPathIsSignatureCase=canonicalSig;
try{isSig=function(c){return canonicalSig(c)}}catch(_){}
try{isSigCase=function(c){return canonicalSig(c)}}catch(_){}
try{v17IsSignature=function(c){return canonicalSig(c)}}catch(_){}
try{(cases||[]).forEach(c=>{c.signature_case=CANONICAL_SIGNATURE_IDS.has(c.id);})}catch(_){}
try{if(typeof DEEP_DIVE_MAP_V17!=='undefined')Object.keys(DEEP_DIVE_MAP_V17).forEach(id=>{if(DEEP_DIVE_MAP_V17[id])DEEP_DIVE_MAP_V17[id].is_signature_case=CANONICAL_SIGNATURE_IDS.has(id);})}catch(_){}
try{const LEGACY_FILTERED=filteredCases;filteredCases=function(){const cb=document.getElementById('signatureOnlyFilter');const wanted=!!(cb&&cb.checked);if(wanted)cb.checked=false;let list;try{list=LEGACY_FILTERED.apply(this,arguments)}finally{if(wanted&&cb)cb.checked=true}return wanted?(list||[]).filter(c=>canonicalSig(c)):list;}}catch(e){console.error('[MolPath '+VERSION+'] signature filter patch failed',e)}
function install(){try{if(!window.MolPathI18n||!window.MolPathI18n.dict)return false;['en','ro','el','es','fr'].forEach(l=>{window.MolPathI18n.dict[l]=window.MolPathI18n.dict[l]||{};Object.assign(window.MolPathI18n.dict[l],EXACT[l]);});return true}catch(e){console.error('[MolPath '+VERSION+'] i18n install failed',e);return false}}
function correctDashboard(){const home=document.getElementById('v20bHomeDashboard');if(!home)return;home.querySelectorAll('.v20b-metric').forEach(m=>{const label=(m.querySelector('span')?.textContent||'').trim().toLowerCase();if(label==='signature'){const b=m.querySelector('b');if(b)b.textContent='15';}})}
function stamp(){try{window.MOLPATH_APP_VERSION=VERSION;document.title='MolPath Simulator '+VERSION;const top=document.getElementById('v20bVersion')||document.querySelector('.v20b-topstatus .v20b-pill.primary');if(top){top.setAttribute('data-i18n-skip','1');top.textContent=VERSION}}catch(_){}}
const PREV=window.MolPathI18nAfterApply;window.MolPathI18nAfterApply=function(l){try{if(typeof PREV==='function')PREV(l)}catch(_){}install();stamp();correctDashboard();};
function boot(){install();stamp();try{if(typeof render==='function')render()}catch(_){}try{if(window.MolPathI18n&&typeof window.MolPathI18n.apply==='function')window.MolPathI18n.apply()}catch(_){}setTimeout(()=>{correctDashboard();try{renderCasePicker();renderKpi()}catch(_){}},0)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else setTimeout(boot,0);
window.MolPathV240t=Object.freeze({version:VERSION,signatureExpected:15,patientCareCases:42,translationInventoryRows:4642,entriesPerLanguage:Object.keys(EXACT.en).length,inventory:'changed_mtb_user_strings.json'});
